--
-- Name: _custom_merchant_payout(integer, timestamp without time zone, timestamp without time zone, character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo._custom_merchant_payout(v_tempplid integer DEFAULT 0, v_payfrom timestamp without time zone DEFAULT NULL::timestamp without time zone, v_payto timestamp without time zone DEFAULT NULL::timestamp without time zone, INOUT v_tempstrresult character varying DEFAULT ''::character varying) RETURNS character varying
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_neworderamount DECIMAL(18,2);
  v_dispathorderamount DECIMAL(18,2);
  v_completeorderamount DECIMAL(18,2);
  v_cancelorderamount DECIMAL(18,2);
  v_admincharge decimal(18,2);
BEGIN
  -- BEGIN TRAN (removed)
  -- SET option (removed)
  v_neworderamount := 0;
  v_dispathorderamount := 0;
  v_completeorderamount := 0;
  v_cancelorderamount := 0;
  SELECT COALESCE(SUM(single_dap), 0) INTO v_neworderamount FROM tbl_product_order_master AS pom INNER JOIN ims_subproduct AS sp ON pom.subprcode = sp.sprid INNER JOIN ims_masterproduct AS mp ON mp.mprid = sp.mprid INNER JOIN tbl_order_master AS om ON pom.orderid = om.orderid WHERE pom.intstatus = 0 AND om.orderdate BETWEEN v_payfrom AND v_payto AND mp.branchid = v_tempplid;
  SELECT COALESCE(SUM(single_dap), 0) INTO v_dispathorderamount FROM tbl_product_order_master AS pom INNER JOIN ims_subproduct AS sp ON pom.subprcode = sp.sprid INNER JOIN ims_masterproduct AS mp ON mp.mprid = sp.mprid INNER JOIN tbl_order_master AS om ON pom.orderid = om.orderid WHERE pom.intstatus = 4 AND om.orderdate BETWEEN v_payfrom AND v_payto AND mp.branchid = v_tempplid;
  SELECT COALESCE(SUM(single_dap), 0), COALESCE(SUM(sp.dap * sp.admincharge) / 100, 0) INTO v_completeorderamount, v_admincharge FROM tbl_product_order_master AS pom INNER JOIN ims_subproduct AS sp ON pom.subprcode = sp.sprid INNER JOIN ims_masterproduct AS mp ON mp.mprid = sp.mprid INNER JOIN tbl_order_master AS om ON pom.orderid = om.orderid WHERE pom.intstatus = 6 AND om.orderdate BETWEEN v_payfrom AND v_payto AND mp.branchid = v_tempplid;
  SELECT COALESCE(SUM(single_dap), 0) INTO v_cancelorderamount FROM tbl_product_order_master AS pom INNER JOIN ims_subproduct AS sp ON pom.subprcode = sp.sprid INNER JOIN ims_masterproduct AS mp ON mp.mprid = sp.mprid INNER JOIN tbl_order_master AS om ON pom.orderid = om.orderid WHERE pom.intstatus = 7 AND om.orderdate BETWEEN v_payfrom AND v_payto AND mp.branchid = v_tempplid;
  IF (v_tempplid <> 0) THEN
  UPDATE merchant_payout SET neworderamount = v_neworderamount, dispatchorderamount = v_dispathorderamount, cancelorderamount = v_cancelorderamount, completeorderamount = v_completeorderamount, admincharge = v_admincharge WHERE plid = v_tempplid AND active = 1;
  v_tempstrresult := 'OK';
  END IF;
  -- SET option (removed)
  -- COMMIT (removed)
END;
$$;


