--
-- Name: _distribute_level_income(date, text); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo._distribute_level_income(v_todate date DEFAULT NULL::date, INOUT v_stroutput text DEFAULT ''::text) RETURNS text
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_kid INT;
  v_loginid text;
  v_childid text;
  v_bool INT;
  v_noofdirectmember BIGINT;
  v_levelpercentage double precision;
  v_precapping DECIMAL(10,2);
  v_maxlevel INT;
  v_kitprice DECIMAL(10,2);
  v_bv numeric(19,4);
  v_sponserid text;
  v_type text;
  v_income DECIMAL(10,2);
  v_ismemberactive INT;
  cr_getlevel CURSOR FOR SELECT kid, loginid, bv FROM tbl_binaryincomedistribution WHERE payid = 0 AND CAST(date AS DATE) <= CAST(v_todate AS DATE) ORDER BY bidid ASC NULLS FIRST;
BEGIN
  BEGIN
  -- SET option (removed)
  v_kid := 0;
  v_loginid := '';
  v_childid := '';
  v_bool := 0;
  v_noofdirectmember := 0;
  v_levelpercentage := 0.00;
  v_precapping := 0.00;
  v_maxlevel := 2;
  v_kitprice := 0.00;
  v_bv := 0;
  v_sponserid := '';
  v_type := '';
  v_income := 0.00;
  v_ismemberactive := 0;
  OPEN cr_getlevel;
  FETCH cr_getlevel INTO v_kid,v_loginid,v_bv;
  WHILE (found) LOOP
  v_maxlevel := 2;
  v_bool := 1;
  v_childid := v_loginid;
  SELECT sponserid INTO v_childid FROM member_master WHERE loginid = v_childid;
  IF (v_bv > 0) THEN
  WHILE (v_bool = 1 AND v_maxlevel <= 13) LOOP
  SELECT COALESCE(sponserid, '0') INTO v_sponserid FROM member_master WHERE loginid = v_childid;
  IF (v_sponserid <> '0') THEN
  SELECT COALESCE(income, 0.00), type INTO v_levelpercentage, v_type FROM level_income_slab WHERE level = v_maxlevel AND status = 1;
  SELECT COUNT(1) INTO v_noofdirectmember FROM tbl_allsubscriptionmaster WHERE COALESCE(isapproved, 0) = 1 AND plid IN (SELECT plid FROM member_master WHERE sponserid = v_sponserid);
  SELECT active INTO v_ismemberactive FROM member_master WHERE loginid = v_sponserid;
  SELECT (v_bv * v_levelpercentage) / 100 INTO v_income;
  IF (v_noofdirectmember > 0) THEN
  IF (v_maxlevel >= 11 AND v_noofdirectmember >= 3) THEN
  INSERT INTO level_income (opid, fromid, toid, amount, income, level, type, date, remark, payid, status, active, isskip, kit_price, comm_per, tds_amt, tds_per, admin_amt, admin_per, member_active, tds_section_id, levelincometype) VALUES (0, v_loginid, v_sponserid, v_bv, v_income, v_maxlevel, v_type, dbo.FUN_GETCURRENTDATE(), v_type, 0, 1, 1, 0, v_bv, 0, 0, 0, 0, 0, v_ismemberactive, 2, 1);
  ELSE
  IF ((v_maxlevel >= 6 AND v_maxlevel <= 10) AND v_noofdirectmember >= 2) THEN
  INSERT INTO level_income (opid, fromid, toid, amount, income, level, type, date, remark, payid, status, active, isskip, kit_price, comm_per, tds_amt, tds_per, admin_amt, admin_per, member_active, tds_section_id, levelincometype) VALUES (0, v_loginid, v_sponserid, v_bv, v_income, v_maxlevel, v_type, dbo.FUN_GETCURRENTDATE(), v_type, 0, 1, 1, 0, v_bv, 0, 0, 0, 0, 0, v_ismemberactive, 2, 1);
  ELSE
  IF (v_maxlevel <= 5) THEN
  INSERT INTO level_income (opid, fromid, toid, amount, income, level, type, date, remark, payid, status, active, isskip, kit_price, comm_per, tds_amt, tds_per, admin_amt, admin_per, member_active, tds_section_id, levelincometype) VALUES (0, v_loginid, v_sponserid, v_bv, v_income, v_maxlevel, v_type, dbo.FUN_GETCURRENTDATE(), v_type, 0, 1, 1, 0, v_bv, 0, 0, 0, 0, 0, v_ismemberactive, 2, 1);
  ELSE
  INSERT INTO level_income (opid, fromid, toid, amount, income, level, type, date, remark, payid, status, active, isskip, kit_price, comm_per, tds_amt, tds_per, admin_amt, admin_per, member_active, tds_section_id, levelincometype) VALUES (0, v_loginid, v_sponserid, v_bv, v_income, v_maxlevel, v_type, dbo.FUN_GETCURRENTDATE(), 'Level Income Flushed.Because You Are Trying To Get The Income Of ' || CAST(v_maxlevel AS text) || ' 
					 Level But You Have Only ' || CAST(v_noofdirectmember AS text) || ' Paid Direct Member So Sorry.!!!', 0, 1, 0, 1, v_bv, 0, 0, 0, 0, 0, v_ismemberactive, 2, 1);
  END IF;
  END IF;
  END IF;
  ELSE
  INSERT INTO level_income (opid, fromid, toid, amount, income, level, type, date, remark, payid, status, active, isskip, kit_price, comm_per, tds_amt, tds_per, admin_amt, admin_per, member_active, tds_section_id, levelincometype) VALUES (0, v_loginid, v_sponserid, v_bv, v_income, v_maxlevel, v_type, dbo.FUN_GETCURRENTDATE(), 'Level Income Flushed.Because You Are Trying To Get The Income Of ' || CAST(v_maxlevel AS text) || ' Level But You Have Only ' || CAST(v_noofdirectmember AS text) || ' Paid Direct Member So Sorry.!!!', 0, 1, 0, 1, v_bv, 0, 0, 0, 0, 0, v_ismemberactive, 2, 1);
  END IF;
  v_maxlevel := v_maxlevel + 1;
  IF (v_maxlevel > 10) THEN
  v_bool := 0;
  END IF;
  ELSE
  v_bool := 0;
  v_sponserid := '0';
  END IF;
  v_childid := v_sponserid;
  END LOOP;
  END IF;
  FETCH cr_getlevel INTO v_kid,v_loginid,v_bv;
  END LOOP;
  CLOSE cr_getlevel;
  -- DEALLOCATE (removed)
  -- SET option (removed)
  v_stroutput := 'Ok';
  EXCEPTION WHEN OTHERS THEN
  v_stroutput := 'Not Okhey In Level Income';
  END;
END;
$$;


