  ELSE
  IF (v_maxlevel <= 5) THEN
  INSERT INTO level_income (opid, fromid, toid, amount, income, level, type, date, remark, payid, status, active, isskip, kit_price, comm_per, tds_amt, tds_per, admin_amt, admin_per, member_active, tds_section_id, levelincometype) VALUES (0, v_loginid, v_sponserid, v_earnedamount, v_income, v_maxlevel, v_type, dbo.FUN_GETCURRENTDATE(), v_type, 0, 1, 1, 0, v_earnedamount, 0, 0, 0, 0, 0, v_ismemberactive, 2, 2);
  ELSE
  INSERT INTO level_income (opid, fromid, toid, amount, income, level, type, date, remark, payid, status, active, isskip, kit_price, comm_per, tds_amt, tds_per, admin_amt, admin_per, member_active, tds_section_id, levelincometype) VALUES (0, v_loginid, v_sponserid, v_earnedamount, v_income, v_maxlevel, v_type, dbo.FUN_GETCURRENTDATE(), 'Level Income Flushed.Because You Are Trying To Get The Income Of ' || CAST(v_maxlevel AS text) || ' Level But You Have Only ' || CAST(v_noofdirectmember AS text) || ' Paid Direct Member So Sorry.!!!', 0, 1, 0, 1, v_earnedamount, 0, 0, 0, 0, 0, v_ismemberactive, 2, 2);
  END IF;
  END IF;
  END IF;
  ELSE
  INSERT INTO level_income (opid, fromid, toid, amount, income, level, type, date, remark, payid, status, active, isskip, kit_price, comm_per, tds_amt, tds_per, admin_amt, admin_per, member_active, tds_section_id, levelincometype) VALUES (0, v_loginid, v_sponserid, v_earnedamount, v_income, v_maxlevel, v_type, dbo.FUN_GETCURRENTDATE(), 'Level Income Flushed.Because You Are Trying To Get The Income Of ' || CAST(v_maxlevel AS text) || ' Level But You Have Only ' || CAST(v_noofdirectmember AS text) || ' Paid Direct Member So Sorry.!!!', 0, 1, 0, 1, v_earnedamount, 0, 0, 0, 0, 0, v_ismemberactive, 2, 2);
  END IF;
  v_maxlevel := v_maxlevel + 1;
  IF (v_maxlevel > 10) THEN
  v_bool := 0;
  END IF;
  ELSE
  v_bool := 0;
  v_sponserid := '0';
  END IF;
  v_childid := v_sponserid;
  END LOOP;
  END IF;
  FETCH cr_getlevel INTO v_earnedamount,v_plid,v_activitytype;
  END LOOP;
  CLOSE cr_getlevel;
  -- DEALLOCATE (removed)
  -- SET option (removed)
  v_stroutput := 'Ok';
  EXCEPTION WHEN OTHERS THEN
  v_stroutput := 'Not Okhey In Task Level Income';
  END;
END;
$$;


--
-- Name: _kyc_status(bigint, integer, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo._kyc_status(v_regno bigint DEFAULT 2015, v_int_status integer DEFAULT 0, v_approvalstatus integer DEFAULT 0) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_count_total_pending INT;
  v_count_total_reject INT;
  v_count_total_aproved INT;
  v_getcount INT;
BEGIN
  v_count_total_pending := 0;
  v_count_total_reject := 0;
  v_count_total_aproved := 0;
  v_getcount := 0;
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp (INT_ROW_NUMMBER INT GENERATED BY DEFAULT AS IDENTITY,
ID	INT DEFAULT(0),
REGNO	BIGINT,
TYPE	VARCHAR(200) DEFAULT(''),
bytea	VARCHAR(400) DEFAULT(''),
ISAPROVE	INT DEFAULT(0),
INT_STATUS	INT DEFAULT(0),
DTM_DATE	timestamp,
DTM_APROVE	timestamp,
COMMENTORREMARK	text  DEFAULT(''),
ISDELETED	INT DEFAULT(0),
GETMAINTYPE VARCHAR(50) DEFAULT(''),
STATUS_CLASS VARCHAR(50) DEFAULT(''),
AdressType varchar(100),
AddressTypeNo varchar(100)) ON COMMIT DROP;
  INSERT INTO tmp_temp (regno, type, isaprove, int_status, getmaintype, image) VALUES (v_regno, 'ID Proof', 0, 0, 'IDProof', 'NoImage.jpg'), (v_regno, 'Cheque/Passbook', 0, 0, 'bank-passbook', 'NoImage.jpg'), (v_regno, 'Photograph', 0, 0, 'photograph', 'NoImage.jpg'), (v_regno, 'Pancard Details', 0, 0, 'Pancard-Details', 'NoImage.jpg');
  SELECT COUNT(regno) INTO v_getcount FROM kyc WHERE regno = v_regno AND kyctype = 1;
  SELECT COUNT(regno) INTO v_count_total_pending FROM kyc WHERE regno = v_regno AND isaprove = 0 AND kyctype = 1;
  SELECT COUNT(regno) INTO v_count_total_reject FROM kyc WHERE regno = v_regno AND isaprove = 2 AND kyctype = 1;
  SELECT COUNT(regno) INTO v_count_total_aproved FROM kyc WHERE regno = v_regno AND isaprove = 1 AND kyctype = 1;
  SELECT CASE WHEN COALESCE(v_count_total_reject, 0) > 0 THEN 2 WHEN COALESCE(v_count_total_pending, 0) > 0 THEN 0 ELSE 1 END INTO v_int_status;
  UPDATE tm SET id = ky.id, image = COALESCE(ky.image, 'NoImage.jpg'), isaprove = COALESCE(ky.isaprove, 0), int_status = COALESCE(v_int_status, 0), dtm_date = COALESCE(ky.dtm_date, ''), dtm_aprove = COALESCE(ky.dtm_aprove, ''), commentorremark = COALESCE(ky.commentorremark, ''), isdeleted = COALESCE(ky.isdeleted, 0), status_class = CASE WHEN COALESCE(ky.isaprove, 0) = 0 THEN 'inprocess' WHEN COALESCE(ky.isaprove, 0) = 1 THEN 'verifiy' WHEN COALESCE(ky.isaprove, 0) = 2 THEN 'reject' END, adresstype = ky.addresstype, addresstypeno = addresstypeno FROM tmp_temp AS tm INNER JOIN kyc AS ky ON tm.getmaintype = ky.type AND ky.regno = v_regno;
  v_approvalstatus := v_count_total_aproved;
  RETURN QUERY SELECT * FROM tmp_temp;
  DROP TABLE IF EXISTS tmp_temp;
END;
$$;


--
-- Name: _kyc_status_all_member(integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo._kyc_status_all_member(v_int_total_count integer DEFAULT 0) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_count_total_pending int;
  v_count_total_reject int;
  v_count_total_aproved int;
BEGIN
  v_count_total_pending := 0;
  v_count_total_reject := 0;
  v_count_total_aproved := 0;
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp (int_row bigint GENERATED BY DEFAULT AS IDENTITY,
Regno bigint,
Loginid varchar(50),
Member_name varchar(200),
userName varchar(200),
Regdate varchar(50),
Kyc_status varchar(50)) ON COMMIT DROP;
  INSERT INTO tmp_temp SELECT mm.regno, mm.loginid, COALESCE(mm.fname, '') || ' ' || COALESCE(mm.lname, ''), COALESCE(mm.username, ''), mm.regdate, (CASE WHEN (SELECT COUNT(regno) FROM kyc WHERE regno = mm.regno AND isaprove = 1) = (SELECT COUNT(regno) FROM kyc WHERE regno = mm.regno) THEN 'Verified' WHEN (SELECT COUNT(regno) FROM kyc WHERE regno = mm.regno AND isaprove = 2) = (SELECT COUNT(regno) FROM kyc WHERE regno = mm.regno) THEN 'Rejected' ELSE 'Pending' END) FROM member_master AS mm WHERE mm.regno IN (SELECT regno FROM kyc);
  SELECT COUNT(regno) INTO v_int_total_count FROM tmp_temp;
  RETURN QUERY SELECT * FROM tmp_temp;
  DROP TABLE IF EXISTS tmp_temp;
END;
$$;


--
-- Name: _kyc_status_refer_dashborad(bigint, character varying, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo._kyc_status_refer_dashborad(v_regno bigint DEFAULT 2018, v_title character varying DEFAULT 'Incorporation-Certificate'::character varying, v_int_status integer DEFAULT 0) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_count_total_pending INT;
  v_count_total_reject INT;
  v_count_total_aproved INT;
  v_coutkyc INT;
BEGIN
  v_count_total_pending := 0;
  v_count_total_reject := 0;
  v_count_total_aproved := 0;
  v_coutkyc := 0;
  SELECT COUNT(1) INTO v_coutkyc FROM kyc WHERE regno = v_regno AND kyctype = 2;
  SELECT COUNT(regno) INTO v_count_total_pending FROM kyc WHERE regno = v_regno AND isaprove = 0 AND kyctype = 2;
  SELECT COUNT(regno) INTO v_count_total_reject FROM kyc WHERE regno = v_regno AND isaprove = 2 AND kyctype = 2;
  SELECT COUNT(regno) INTO v_count_total_aproved FROM kyc WHERE regno = v_regno AND isaprove = 1 AND kyctype = 2;
  SELECT CASE WHEN COALESCE(v_count_total_reject, 0) > 0 THEN 2 WHEN COALESCE(v_count_total_pending, 0) > 0 THEN 0 WHEN COALESCE(v_count_total_aproved, 0) = 4 THEN 1 ELSE 3 END INTO v_int_status;
  RETURN QUERY SELECT id, regno, (CASE WHEN type = 'Address-Proof' THEN 'Address Proof' WHEN type = 'Company-Address-Proof' THEN 'Company Address Proof' WHEN type = 'PANCARD-DETAILS' THEN 'Pancard Details' WHEN type = 'Memorandum-Of-Association' THEN 'Memorandum Of Association' WHEN type = 'Incorporation-Certificate' THEN 'Incorporation Certificate' WHEN type = 'Company-Pancard-Details' THEN 'Company Pancard Details' WHEN type = 'BANK-PASSBOOK' THEN 'Cheque/Passbook' ELSE 'Others' END) AS type, COALESCE(image, '') AS image, isaprove, COALESCE(v_int_status, 0) AS int_status, COALESCE(dtm_date, '') AS dtm_date, COALESCE(dtm_aprove, '') AS dtm_aprove, COALESCE(commentorremark, '') AS commentorremark, COALESCE(isdeleted, 0) AS isdeleted, COALESCE(kyctype, 2) AS kyctype, COALESCE(addresstype, '') AS addresstype, COALESCE(addressnumber, '') AS addressnumber FROM kyc WHERE regno = v_regno AND type = v_title AND kyctype = 2;
END;
$$;


--
-- Name: _kyc_status_refer_dashborad_reseller(bigint, character varying, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo._kyc_status_refer_dashborad_reseller(v_regno bigint DEFAULT 1, v_title character varying DEFAULT ''::character varying, v_int_status integer DEFAULT 0) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
