  v_count_total_aproved := 0;
  v_coutkyc := 0;
  SELECT COUNT(1) INTO v_coutkyc FROM kyc_distributor WHERE regno = v_regno AND kyctype = 2;
  SELECT COUNT(regno) INTO v_count_total_pending FROM kyc_distributor WHERE regno = v_regno AND isaprove = 0 AND kyctype = 2;
  SELECT COUNT(regno) INTO v_count_total_reject FROM kyc_distributor WHERE regno = v_regno AND isaprove = 2 AND kyctype = 2;
  SELECT COUNT(regno) INTO v_count_total_aproved FROM kyc_distributor WHERE regno = v_regno AND isaprove = 1 AND kyctype = 2;
  SELECT CASE WHEN COALESCE(v_count_total_reject, 0) > 0 THEN 2 WHEN COALESCE(v_count_total_pending, 0) > 0 THEN 0 WHEN COALESCE(v_count_total_aproved, 0) = 4 THEN 1 ELSE 3 END INTO v_int_status;
  RETURN QUERY SELECT id, regno, (CASE WHEN type = 'Address-Proof' THEN 'Address Proof' WHEN type = 'Company-Address-Proof' THEN 'Company Address Proof' WHEN type = 'PANCARD-DETAILS' THEN 'Pancard Details' WHEN type = 'Memorandum-Of-Association' THEN 'Memorandum Of Association' WHEN type = 'Incorporation-Certificate' THEN 'Incorporation Certificate' WHEN type = 'Company-Pancard-Details' THEN 'Company Pancard Details' WHEN type = 'BANK-PASSBOOK' THEN 'Cheque/Passbook' ELSE 'Others' END) AS type, COALESCE(image, '') AS image, isaprove, COALESCE(v_int_status, 0) AS int_status, COALESCE(dtm_date, '') AS dtm_date, COALESCE(dtm_aprove, '') AS dtm_aprove, COALESCE(commentorremark, '') AS commentorremark, COALESCE(isdeleted, 0) AS isdeleted, COALESCE(kyctype, 2) AS kyctype, COALESCE(addresstype, '') AS addresstype, COALESCE(addressnumber, '') AS addressnumber FROM kyc_distributor WHERE regno = v_regno AND type = v_title AND kyctype = 2;
END;
$$;


--
-- Name: acceptdatarecord(bigint); Type: FUNCTION; Schema: dbo; Owner: -
