CREATE FUNCTION dbo.acceptdatarecord(v_whid bigint) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
BEGIN
  RETURN QUERY SELECT wh.whid, wh.plid, wh.amount, wh.tranid, pl.loginid, COALESCE(pl.fname, '') || '' || COALESCE(pl.lname, '') AS membername, cm.currencysymbol FROM withdrawal_history AS wh INNER JOIN portal_login AS pl ON wh.plid = pl.plid LEFT JOIN tbl_currencymaster AS cm ON pl.cid = cm.cid WHERE wh.whid = v_whid;
