--
-- Name: acceptrejectpackrequests(bigint, integer, character varying, text, character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.acceptrejectpackrequests(v_preqid bigint, v_mode integer, v_admin_user character varying, v_admin_remarks text, INOUT v_strresult character varying) RETURNS character varying
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_plid bigint;
  v_packid int;
  v_validity int;
  v_noofads int;
  v_memexpdate timestamp;
  v_memremads int;
  v_maxexpdate timestamp;
  v_ctid int;
  v_catid int;
  v_pmid bigint;
  v_days int;
  v_madsid bigint;
BEGIN
  -- BEGIN TRAN (removed)
  IF (v_mode = 1) THEN
  SELECT plid, packid, ctid, catid, validity, quantity, pmid, featured_days INTO v_plid, v_packid, v_ctid, v_catid, v_validity, v_noofads, v_pmid, v_days FROM tbl_packrequestsdetails WHERE preqid = v_preqid;
  PERFORM dbo.usp_removeexpiredads(v_plid => v_plid);
  IF NOT EXISTS(SELECT 1 FROM tbl_memberadsdetails WHERE plid = v_plid AND ctid = v_ctid AND catid = v_catid AND featured_days = v_days AND status = 1) THEN
  INSERT INTO tbl_memberadsdetails (plid, ctid, catid, total_ads, used_ads, remain_ads, expired_ads, featured_days, exprdate, status) VALUES (v_plid, v_ctid, v_catid, v_noofads, 0, v_noofads, 0, v_days, (dbo.fun_getCurrentDate()) + (INTERVAL '1 DAY' * v_validity), 1);
  UPDATE tbl_packrequestsdetails SET status = 1, approve_reject_date = dbo.fun_getCurrentDate(), exprdate = ((dbo.fun_getCurrentDate()) + (INTERVAL '1 DAY' * v_validity)), admin_user = v_admin_user, admin_remarks = v_admin_remarks WHERE preqid = v_preqid;
  ELSE
  UPDATE tbl_packrequestsdetails SET status = 1, approve_reject_date = dbo.fun_getCurrentDate(), exprdate = ((dbo.fun_getCurrentDate()) + (INTERVAL '1 DAY' * v_validity)), admin_user = v_admin_user, admin_remarks = v_admin_remarks WHERE preqid = v_preqid;
  SELECT MAX(COALESCE(exprdate, dbo.fun_getCurrentDate())) INTO v_maxexpdate FROM tbl_packrequestsdetails WHERE plid = v_plid AND ctid = v_ctid AND catid = v_catid AND featured_days = v_days AND status = 1;
  UPDATE tbl_memberadsdetails SET total_ads = COALESCE(total_ads, 0) + v_noofads, remain_ads = COALESCE(remain_ads, 0) + v_noofads, exprdate = v_maxexpdate WHERE plid = v_plid AND ctid = v_ctid AND catid = v_catid AND featured_days = v_days AND status = 1;
  END IF;
  IF (v_pmid <> 0) THEN
  SELECT madsid, featured_days INTO v_madsid, v_days FROM tbl_memberadsdetails WHERE plid = v_plid AND ctid = v_ctid AND catid = v_catid AND status = 1 AND COALESCE(remain_ads, 0) > 0 ORDER BY exprdate ASC NULLS FIRST LIMIT 1;
  UPDATE tbl_memberadsdetails SET remain_ads = COALESCE(remain_ads, 0) - 1, used_ads = COALESCE(used_ads, 0) + 1 WHERE madsid = v_madsid;
  IF EXISTS(SELECT 1 FROM portal_master WHERE pmid = v_pmid AND isverfied = 1) THEN
  UPDATE portal_master SET expired_date = ((dbo.fun_getCurrentDate()) + (INTERVAL '1 DAY' * v_days)) WHERE pmid = v_pmid AND isverfied = 1;
  ELSE
  UPDATE portal_master SET featured_days = v_days WHERE pmid = v_pmid;
  END IF;
  END IF;
  v_strresult := 'Request Accepted Successfully...';
  END IF;
  IF (v_mode = 2) THEN
  UPDATE tbl_packrequestsdetails SET status = 2, approve_reject_date = dbo.fun_getCurrentDate(), admin_user = v_admin_user, admin_remarks = v_admin_remarks WHERE preqid = v_preqid;
  v_strresult := 'Request Rejected Successfully...';
  END IF;
  IF (0 <> 0) THEN
  v_strresult := 'Error Occured';
  -- ROLLBACK (removed)
  RETURN;
  END IF;
  -- COMMIT (removed)
END;
$$;


--
-- Name: add_update_delete_tbl_submenurole(integer, integer, text, character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.add_update_delete_tbl_submenurole(v_id integer DEFAULT 0, v_rid integer DEFAULT NULL::integer, v_collectionofid text DEFAULT NULL::text, INOUT v_strresult character varying DEFAULT NULL::character varying) RETURNS character varying
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_startwhile int;
  v_totalrow int;
  v_mid bigint;
  v_sid bigint;
  v_getsinglerow varchar(50);
  v_isedit int;
  v_isdelete int;
BEGIN
  -- BEGIN TRAN (removed)
  v_strresult := 'success';
  DROP TABLE IF EXISTS tmp_temp1;
  CREATE TEMP TABLE tmp_temp1 (intids int GENERATED BY DEFAULT AS IDENTITY,
	 getvalues varchar(500)) ON COMMIT DROP;
  DROP TABLE IF EXISTS tmp_temp2;
  CREATE TEMP TABLE tmp_temp2 (intid int GENERATED BY DEFAULT AS IDENTITY,
	 splitvla varchar(500)) ON COMMIT DROP;
  UPDATE tbl_mainmenurole SET status = 0 WHERE rid = v_rid;
  UPDATE tbl_submenurole SET status = 0, isedit = 0, isdelete = 0, active = 0 WHERE rid = v_rid;
  INSERT INTO tmp_temp1 SELECT value FROM dbo.SPLITSTRINGBYCUSTOMSYMBOL1(v_collectionofid, '|');
  v_startwhile := 1;
  v_totalrow := 0;
  v_mid := 0;
  v_sid := 0;
  v_isedit := 0;
  v_isdelete := 0;
  SELECT COUNT(intids) INTO v_totalrow FROM tmp_temp1;
  WHILE (v_startwhile <= v_totalrow) LOOP
  v_getsinglerow := '';
  SELECT getvalues INTO v_getsinglerow FROM tmp_temp1 WHERE intids = v_startwhile;
  TRUNCATE TABLE tmp_temp2;
  INSERT INTO tmp_temp2 SELECT value FROM dbo.SPLITSTRINGBYCUSTOMSYMBOL1(v_getsinglerow, ',');
  v_mid := 0;
  v_sid := 0;
  v_isedit := 0;
  v_isdelete := 0;
  SELECT splitvla INTO v_mid FROM tmp_temp2 WHERE intid = 1;
  SELECT splitvla INTO v_sid FROM tmp_temp2 WHERE intid = 2;
  SELECT splitvla INTO v_isedit FROM tmp_temp2 WHERE intid = 3;
  SELECT splitvla INTO v_isdelete FROM tmp_temp2 WHERE intid = 4;
  IF (v_mid > 0 AND v_rid > 0) THEN
  IF EXISTS(SELECT 1 FROM tbl_mainmenurole WHERE mid = v_mid AND rid = v_rid) THEN
  UPDATE tbl_mainmenurole SET status = 1, updatedate = CURRENT_TIMESTAMP WHERE mid = v_mid AND rid = v_rid;
  ELSE
  INSERT INTO tbl_mainmenurole (rid, mid, createdate, updatedate, status) VALUES (v_rid, v_mid, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 1);
  END IF;
  END IF;
  IF (v_mid > 0 AND v_rid > 0 AND v_sid > 0) THEN
  IF EXISTS(SELECT 1 FROM tbl_submenurole WHERE mid = v_mid AND rid = v_rid AND sid = v_sid) THEN
  UPDATE tbl_submenurole SET status = 1, isedit = v_isedit, isdelete = v_isdelete, updatedate = CURRENT_TIMESTAMP, active = 1 WHERE mid = v_mid AND rid = v_rid AND sid = v_sid;
  ELSE
  INSERT INTO tbl_submenurole (rid, mid, sid, createdate, updatedate, status, isedit, isdelete, active) VALUES (v_rid, v_mid, v_sid, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 1, v_isedit, v_isdelete, 1);
  END IF;
  ELSE
  IF (v_mid > 0 AND v_rid > 0 AND v_sid = 0) THEN
  IF EXISTS(SELECT 1 FROM tbl_submenurole WHERE mid = v_mid AND rid = v_rid AND sid = 0) THEN
  UPDATE tbl_submenurole SET status = 0, isedit = 0, isdelete = 0, updatedate = CURRENT_TIMESTAMP, active = 1 WHERE mid = v_mid AND rid = v_rid AND sid = 0;
  ELSE
  INSERT INTO tbl_submenurole (rid, mid, sid, createdate, updatedate, status, isedit, isdelete, active) VALUES (v_rid, v_mid, 0, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0, 0, 0, 1);
  END IF;
  END IF;
  END IF;
  v_startwhile := v_startwhile + 1;
  END LOOP;
  IF (0 <> 0) THEN
  v_strresult := 'Error occurred  Please try later';
  -- ROLLBACK (removed)
  RETURN;
  END IF;
  -- COMMIT (removed)
END;
$$;


--
-- Name: allmaillist(integer, character varying, character varying, text, integer, integer, integer, text, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.allmaillist(v_plid integer DEFAULT 0, v_fromdate character varying DEFAULT ''::character varying, v_todate character varying DEFAULT ''::character varying, v_groupname text DEFAULT ''::text, v_intresult integer DEFAULT 0, v_startrowindex integer DEFAULT 1, v_maxrows integer DEFAULT 100, v_loginid text DEFAULT ''::text, v_mode integer DEFAULT 0) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_query text;
  v_minindex INT;
  v_maxindex INT;
  v_query1 text;
BEGIN
  v_query := '';
  v_minindex := (v_startrowindex - 1) * v_maxrows + 1;
  v_maxindex := v_startrowindex * v_maxrows;
  IF (v_mode = 0) THEN
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp (RowNumber Bigint,
	TMCEMID int,
	ShortEmail Varchar(500),
	FullEmail text,
	Status Varchar(100),
	CREATEDATE Varchar(100),
	GROUPNAME text,
	REMARK text,
	NoofEmails Bigint,
	PLID Int) ON COMMIT DROP;
  v_query := v_query || ('Insert Into #Temp SELECT ROW_NUMBER() OVER (ORDER BY  TMCE.Create_Date Desc) AS RowNumber,
	TMCEMID,(Case When LEN(TMCE.EMAIL)>60 Then SUBSTRING(TMCE.EMAIL,0,30)+''...'' ELSE TMCE.EMAIL END)As ShortEmail,
	TMCE.EMAIL As FullEmail,(Case When TMCE.ISACTIVE=1 Then ''Active'' Else ''Deactive'' End)As Status,
	CONVERT(VARCHAR(15),CREATE_DATE,106) AS CREATEDATE,
	TMCE.GROUPNAME,TMCE.REMARK,(Len(TMCE.EMAIL) - Len(Replace(TMCE.EMAIL,'','','''')) + 1 ) As NoofEmails,TMCE.PLID
	FROM  TBL_MEMBER_CUSTOMER_EMAIL TMCE Where ISDELETED=0 ');
  IF (v_plid <> 0) THEN
  v_query := v_query || ('  And TMCE.PLID = ' || CAST(v_plid AS VARCHAR) || ' ');
  END IF;
  IF (v_fromdate <> '' AND v_todate <> '') THEN
  v_query := v_query || (' And Convert(date,TMCE.Create_Date,103) Between Convert(date,''' || v_fromdate || ''',103) And Convert(date,''' || v_todate || ''',103)');
  END IF;
  IF (v_fromdate <> '') THEN
  v_query := v_query || (' And Convert(date,TMCE.Create_Date,103) >= Convert(date,''' || v_fromdate || ''',103)');
  END IF;
  IF (v_todate <> '') THEN
  v_query := v_query || (' And Convert(date,TMCE.Create_Date,103) <= Convert(date,''' || v_todate || ''',103)');
  END IF;
  IF (v_groupname <> '') THEN
  v_query := v_query || (' And TMCE.GroupName = ''' || v_groupname || '''');
  END IF;
  IF (v_loginid <> '') THEN
  v_query := v_query || (' And MM.EmailID Like ''%' || v_loginid || '%''');
  END IF;
  EXECUTE v_query;
  RETURN QUERY SELECT * FROM tmp_temp WHERE rownumber BETWEEN v_minindex AND v_maxindex;
  SELECT COUNT(1) INTO v_intresult FROM tmp_temp;
  DROP TABLE IF EXISTS tmp_temp;
  END IF;
  IF (v_mode = 1) THEN
  v_query1 := '';
  DROP TABLE IF EXISTS tmp_temp1;
  CREATE TEMP TABLE tmp_temp1 (RowNumber Int GENERATED BY DEFAULT AS IDENTITY,
	PLID Int,
	TotalDeleted BigInt,
	TotalEmails BigInt,
	LoginID Varchar(500),
	MOBILE Varchar(100)) ON COMMIT DROP;
  v_query1 := v_query1 || (' Insert Into #Temp1 Select TMCE.PLID, (select Count(1) from TBL_MEMBER_CUSTOMER_EMAIL where ISDELETED=1 And ISACTIVE=0 AND PLID=TMCE.PLID) As TotalDeleted,
	Sum((Len(TMCE.EMAIL) - Len(Replace(TMCE.EMAIL,'','','''')) + 1 )) As TotalEmails,PL.LoginID As LoginID,PL.Phone As MOBILE
	From TBL_MEMBER_CUSTOMER_EMAIL TMCE
	Inner Join Portal_Login PL ON PL.PLID = TMCE.PLID Left Join COUNTRY C ON C.Cid = PL.CID Where PL.RegNo != 0 ');
  IF (v_loginid <> '') THEN
  v_query1 := v_query1 || (' And PL.LoginID Like ''%' || v_loginid || '%''');
  END IF;
  v_query1 := v_query1 || (' Group By TMCE.PLID,PL.LoginID,PL.Phone');
  EXECUTE v_query1;
  RETURN QUERY SELECT * FROM tmp_temp1 WHERE rownumber BETWEEN v_minindex AND v_maxindex;
  SELECT COUNT(1) INTO v_intresult FROM tmp_temp1;
  DROP TABLE IF EXISTS tmp_temp1;
  END IF;
END;
$$;


--
-- Name: allmobilelist(integer, character varying, character varying, text, integer, integer, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.allmobilelist(v_plid integer DEFAULT 0, v_fromdate character varying DEFAULT ''::character varying, v_todate character varying DEFAULT ''::character varying, v_groupname text DEFAULT ''::text, v_intresult integer DEFAULT 0, v_startrowindex integer DEFAULT 1, v_maxrows integer DEFAULT 100) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_query text;
  v_minindex INT;
  v_maxindex INT;
BEGIN
  v_query := '';
  v_minindex := (v_startrowindex - 1) * v_maxrows + 1;
  v_maxindex := v_startrowindex * v_maxrows;
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp (RowNumber Bigint,
	TMCSMID int,
	MOBILE text,
	ShortMobile Varchar(200),
	CREATEDATE Varchar(100),
	GROUPNAME text,
	REMARK text,
	NoofMobiles Bigint,
	ISACTIVE boolean) ON COMMIT DROP;
  v_query := v_query || ('Insert Into #Temp Select ROW_NUMBER() Over (Order by  TMCSMID) as RowNumber,
TMCSMID , MOBILE,
(Case When Len(MOBILE)>12 Then SUBSTRING(MOBILE,0,12)+''...'' Else MOBILE End) As ShortMobile,
CONVERT(VARCHAR(15),CREATE_DATE,106) AS CREATEDATE,
GROUPNAME,REMARK,(Len(MOBILE) - Len(Replace(MOBILE,'','','''')) + 1 ) As NoofMobiles,
ISACTIVE From  TBL_MEMBER_CUSTOMER_MOBILE where PLID = ' || CAST(v_plid AS VARCHAR) || ' and ISDELETED=0 ');
  IF (v_fromdate <> '' AND v_todate <> '') THEN
  v_query := v_query || (' And Convert(date,CREATE_DATE,103) Between Convert(date,''' || v_fromdate || ''',103) And Convert(date,''' || v_todate || ''',103)');
  END IF;
  IF (v_fromdate <> '') THEN
  v_query := v_query || (' And Convert(date,CREATE_DATE,103) >= Convert(date,''' || v_fromdate || ''',103)');
  END IF;
  IF (v_todate <> '') THEN
  v_query := v_query || (' And Convert(date,CREATE_DATE,103) <= Convert(date,''' || v_todate || ''',103)');
  END IF;
  IF (v_groupname <> '') THEN
  v_query := v_query || (' And GROUPNAME = ''' || v_groupname || '''');
  END IF;
  v_query := v_query || (' Order By TMCSMID Desc');
  EXECUTE v_query;
  RETURN QUERY SELECT * FROM tmp_temp WHERE rownumber BETWEEN v_minindex AND v_maxindex;
  SELECT COUNT(1) INTO v_intresult FROM tmp_temp;
  DROP TABLE IF EXISTS tmp_temp;
END;
$$;


--
-- Name: allsendemailhistory(integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.allsendemailhistory(v_plid integer) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
BEGIN
  RETURN QUERY SELECT smid, fromemail, toemail, senddate FROM tbl_sendmailhistory WHERE plid = v_plid;
END;
$$;


--
-- Name: backup_usp_customer_make_order(character varying, character varying, text, character varying, character varying, character varying, character varying, character varying, character varying, character varying, character varying, text, character varying, character varying, character varying, character varying, character varying, character varying, character varying, character varying, character varying, integer, integer, character varying, character varying, numeric, numeric, numeric, character varying, character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.backup_usp_customer_make_order(v_orderid character varying DEFAULT ''::character varying, v_loginid character varying DEFAULT ''::character varying, v_product text DEFAULT NULL::text, v_fname character varying DEFAULT ''::character varying, v_lname character varying DEFAULT ''::character varying, v_address11 character varying DEFAULT ''::character varying, v_towncity character varying DEFAULT ''::character varying, v_postalcode character varying DEFAULT ''::character varying, v_emails character varying DEFAULT ''::character varying, v_mobile character varying DEFAULT ''::character varying, v_paymode character varying DEFAULT ''::character varying, v_paymentremark text DEFAULT ''::text, v_ordertype character varying DEFAULT ''::character varying, v_sh_fname character varying DEFAULT ''::character varying, v_sh_lname character varying DEFAULT ''::character varying, v_sh_address11 character varying DEFAULT ''::character varying, v_sh_towncity character varying DEFAULT ''::character varying, v_sh_postalcode character varying DEFAULT ''::character varying, v_sh_emails character varying DEFAULT ''::character varying, v_sh_mobile character varying DEFAULT ''::character varying, v_strresult character varying DEFAULT NULL::character varying, v_distributorid integer DEFAULT 0, v_iscouponapplyed integer DEFAULT 0, v_username character varying DEFAULT ''::character varying, v_transactionpassword character varying DEFAULT ''::character varying, v_sumbv numeric DEFAULT 0, v_jp numeric DEFAULT 0, v_netorder numeric DEFAULT 0, v_usernameewallet character varying DEFAULT ''::character varying, v_transactionpasswordewallet character varying DEFAULT ''::character varying) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_orderidtemp VARCHAR(200);
  v_replacementday INT;
  v_ordercode VARCHAR(5);
  v_qty INT;
  v_prcode VARCHAR(50);
  v_prodqty VARCHAR(50);
  v_produnit VARCHAR(50);
  v_prodcolor VARCHAR(50);
  v_prodsize VARCHAR(50);
  v_prodimages VARCHAR(50);
  v_product_name VARCHAR(250);
  v_singl_dap numeric(19,4);
  v_total_dap numeric(19,4);
  v_countrow INT;
  v_countnewrow INT;
  v_value text;
  v_idx INT;
  v_orid BIGINT;
  v_total_qty INT;
  v_total_price numeric(19,4);
  v_total_paid_product_price numeric(19,4);
  v_maxpoid BIGINT;
  v_getcoupondiscoutvalue numeric(19,4);
  v_city VARCHAR(150);
  v_pv numeric(19,4);
  v_totalpv numeric(19,4);
  v_bv numeric(19,4);
  v_totalbv numeric(19,4);
  v_currentdate timestamp;
  v_defaultecombrcode VARCHAR(30);
  v_sh_charge numeric(19,4);
  v_total_sh_charge numeric(19,4);
  v_vcid numeric(19,4);
  v_vat numeric(19,4);
  v_totalvat numeric(19,4);
  v_total_single_price numeric(19,4);
  v_total_order_price numeric(19,4);
  v_actualprice numeric(19,4);
  v_total_single_purchasecost numeric(19,4);
  v_subprcode VARCHAR(30);
  v_total_single_dap numeric(19,4);
  v_prid_new BIGINT;
  v_singlebv numeric(19,4);
  v_stockin INT;
  v_stockout INT;
  v_stocknet INT;
  v_isoutofstock boolean;
  v_count INT;
  v_row INT;
  v_sprid BIGINT;
  v_branchid BIGINT;
  v_matchbranchid BIGINT;
  v_branchid_temp BIGINT;
  v_qntycount INT;
  v_childcount INT;
  v_rowcountchild INT;
  v_totalproductcost DECIMAL(18,2);
  v_totalproductshipping DECIMAL(18,2);
  v_totalproductpayable DECIMAL(18,2);
  v_totalproductbv DECIMAL(10,2);
  v_ewalletpayablebalance DECIMAL(18,8);
  v_pointredeempercent DECIMAL(18,8);
  v_discountamount DECIMAL(18,8);
  v_ref_regno VARCHAR(10);
  v_db_name VARCHAR(100);
  v_query text;
  v_stroutput varchar(100);
  v_transactionidout varchar(100);
  v_parmdefinition text;
  v_querysql text;
  v_regno INT;
BEGIN
  -- BEGIN TRAN (removed)
  v_orderidtemp := '';
  v_replacementday := 0;
  v_ordercode := '';
  v_singl_dap := 0;
  v_total_dap := 0;
  v_countrow := 0;
  v_countnewrow := 0;
  v_total_qty := 0;
  v_total_price := 0;
  v_total_paid_product_price := 0;
  v_getcoupondiscoutvalue := 0;
  v_pv := 0;
  v_totalpv := 0;
  v_bv := 0;
  v_totalbv := 0;
  v_sh_charge := 0;
  v_total_sh_charge := 0;
  v_vcid := 0;
  v_vat := 0;
  v_totalvat := 0;
  v_total_single_price := 0;
  v_total_order_price := 0;
  v_actualprice := 0;
  v_total_single_purchasecost := 0;
  v_total_single_dap := 0;
  v_singlebv := 0;
  v_stockin := 0;
  v_stockout := 0;
  v_stocknet := 0;
  v_isoutofstock := 0;
  DROP TABLE IF EXISTS tmp_temp1;
  CREATE TEMP TABLE tmp_temp1 ON COMMIT DROP AS SELECT LEFT(CAST(value AS TEXT), POSITION('^' IN value) - 1) AS sprid, SUBSTRING(value FROM POSITION('^' IN value) + 1 FOR LENGTH(CAST(value AS TEXT))) AS qty, COALESCE((SELECT branchid FROM ims_masterproduct AS pm INNER JOIN ims_subproduct AS sp ON sp.mprid = pm.mprid WHERE sp.sprid = LEFT(CAST(value AS TEXT), POSITION('^' IN value) - 1)), 0) AS branchid FROM SPLITSTRINGBYCUSTOMSYMBOL1(v_product, '|');
  DROP TABLE IF EXISTS tmp_temp2;
  CREATE TEMP TABLE tmp_temp2 ON COMMIT DROP AS SELECT ROW_NUMBER() OVER (ORDER BY branchid ASC NULLS FIRST) AS rowno, DENSE_RANK() OVER (ORDER BY branchid NULLS FIRST) AS denserank, * FROM tmp_temp1;
  RETURN QUERY SELECT * FROM tmp_temp2;
  v_count := 1;
  SELECT MAX(denserank) INTO v_countrow FROM tmp_temp2;
  WHILE (v_count <= v_countrow) LOOP
  v_row := 0;
  v_sprid := 0;
  v_branchid := 0;
  v_matchbranchid := 0;
  v_total_dap := 0;
  v_singl_dap := 0;
  v_total_qty := 0;
  v_total_qty := 0;
  v_total_dap := 0;
  v_total_sh_charge := 0;
  v_total_order_price := 0;
  v_totalvat := 0;
  v_branchid_temp := 0;
  v_qntycount := 0;
  SELECT branchid INTO v_branchid_temp FROM tmp_temp2 WHERE denserank = v_count LIMIT 1;
  RETURN QUERY SELECT v_count AS counts, v_countrow AS countrow, v_branchid_temp AS branchid_temp;
  SELECT v_strresult INTO v_orderid FROM dbo.getorderid(v_strresult => v_orderid);
  SELECT 'OD' INTO v_ordercode;
  v_orderid := v_ordercode || v_orderid;
  IF NOT EXISTS(SELECT 1 FROM tbl_order_master WHERE orderid = v_orderid) THEN
  v_orderidtemp := v_orderidtemp || ',' || v_orderid;
  v_qntycount := 0;
  SELECT SUM(CAST(qty AS INT)) INTO v_qntycount FROM tmp_temp2 WHERE branchid = v_branchid_temp;
  INSERT INTO tbl_order_master (loginid, orderid, ordertype, orderdate, order_qty, order_dap, total_vat, total_ship_ch, order_netamt, order_pv, order_bv, paymode, paytransid, payremark, fname, lname, mobileno, emailid, address, pincode, city, sh_fname, sh_lname, sh_mobileno, sh_emailid, sh_address, sh_pincode, sh_city, totalacceptedamt, totalrejectedamt, branchid, emp_code, status, intstatus, description, isbvdist) VALUES (v_loginid, v_orderid, v_ordertype, dbo.FUN_GETCURRENTDATE(), v_qntycount, 0, 0, 0, 0, v_jp, v_sumbv, v_paymode, '', v_paymentremark, v_fname, v_lname, v_mobile, v_emails, v_address11, v_postalcode, v_sh_towncity, v_sh_fname, v_sh_lname, v_sh_mobile, v_sh_emails, v_sh_address11, v_sh_postalcode, v_towncity, 0, 0, v_branchid_temp, '', 'Pending', 0, 'Order is pending', 0);
  v_childcount := 0;
  v_rowcountchild := 0;
  SELECT MIN(rowno) INTO v_rowcountchild FROM tmp_temp2 WHERE branchid = v_branchid_temp;
  SELECT MAX(rowno) INTO v_childcount FROM tmp_temp2 WHERE branchid = v_branchid_temp;
  RETURN QUERY SELECT v_rowcountchild AS childcountminxx, v_childcount AS childmaxyyy;
  WHILE (v_rowcountchild <= v_childcount) LOOP
  SELECT sprid, qty INTO v_prcode, v_qty FROM tmp_temp2 WHERE rowno = v_rowcountchild;
  SELECT dap, qty, unit, color, size, productimages, COALESCE(shippingcharges, 0), vatcategoryid, actualprice, subprcode, replacementday, stockin, stockout, stocknet, isoutofstock INTO v_singl_dap, v_prodqty, v_produnit, v_prodcolor, v_prodsize, v_prodimages, v_sh_charge, v_vcid, v_actualprice, v_subprcode, v_replacementday, v_stockin, v_stockout, v_stocknet, v_isoutofstock FROM ims_subproduct WHERE sprid = v_prcode;
  IF (v_stockin < v_qty) THEN
  -- ROLLBACK (removed)
  v_strresult := 'Failed';
  RETURN;
  END IF;
  SELECT producttitle INTO v_product_name FROM ims_masterproduct WHERE mprid = (SELECT mprid FROM ims_subproduct WHERE sprid = v_prcode);
  SELECT COALESCE(vatpercvalue, 0) INTO v_vat FROM tbl_vat_categories WHERE vcid = v_vcid;
  v_totalproductcost := 0;
  v_totalproductshipping := 0;
  v_totalproductpayable := 0;
  v_totalproductbv := 0;
  SELECT bv INTO v_totalproductbv FROM ims_subproduct WHERE mprid = (SELECT mprid FROM ims_subproduct WHERE sprid = v_prcode);
  v_total_dap := v_singl_dap * v_qty;
  v_totalproductshipping := v_sh_charge * v_qty;
  v_totalproductcost := v_total_dap + v_totalproductshipping;
  v_vat := (v_total_dap * v_vat) / 100;
  v_totalproductpayable := v_totalproductcost + v_vat;
  v_total_single_dap := v_total_single_dap + v_total_dap;
  v_total_sh_charge := v_total_sh_charge + v_totalproductshipping;
  v_total_order_price := v_total_order_price + v_totalproductpayable;
  v_total_qty := v_total_qty + v_qty;
  v_totalvat := v_totalvat + v_vat;
  v_totalproductbv := v_totalproductbv * v_qty;
  INSERT INTO tbl_product_order_master (loginid, orderid, subprcode, product_qty, single_dap, total_dap, total_ship_ch, total_cost, total_vat, total_pv, total_bv, total_purchase_cost, total_payble_vat, product_name, prodqty, prounit, prodcolor, prodsize, prod_images, status, intstatus, replacementday) VALUES (v_loginid, v_orderid, v_prcode, v_qty, v_singl_dap, v_total_dap, v_totalproductshipping, v_totalproductcost, v_vat, 0, v_totalproductbv, v_totalproductpayable, v_vat, v_product_name, v_prodqty, v_produnit, v_prodcolor, v_prodsize, v_prodimages, 'PENDING', 0, v_replacementday);
  UPDATE ims_subproduct SET stockin = COALESCE(stockin, 0) - v_qty, stockout = COALESCE(stockout, 0) + v_qty, stocknet = COALESCE(stocknet, 0) - v_qty, isoutofstock = (CASE WHEN COALESCE(stockin, 0) = v_qty THEN 1 ELSE 0 END) WHERE sprid = v_prcode;
  v_rowcountchild := v_rowcountchild + 1;
  END LOOP;
  UPDATE tbl_order_master SET order_qty = v_total_qty, order_dap = v_total_single_dap, total_ship_ch = v_total_sh_charge, order_netamt = v_total_order_price - (v_sumbv + v_jp + v_totalvat), total_vat = v_totalvat WHERE orderid = v_orderid;
  IF (v_paymode = 'EWAL') THEN
  v_ewalletpayablebalance := 0.00;
  v_pointredeempercent := 0.00;
  v_discountamount := 0.00;
  IF (v_iscouponapplyed = 0) THEN
  v_ewalletpayablebalance := v_total_order_price;
  ELSE
  SELECT pointredeempercent INTO v_pointredeempercent FROM tbl_distributor WHERE did = v_distributorid;
  v_discountamount := ((v_total_order_price * v_pointredeempercent) / 100);
  v_ewalletpayablebalance := v_total_order_price - v_discountamount;
  END IF;
  v_ref_regno := '';
  v_query := '';
  SELECT db_name INTO v_db_name FROM tbl_distributor WHERE did = v_distributorid;
  SELECT reference_regno INTO v_ref_regno FROM tbl_customerlogin WHERE loginid = v_loginid;
  v_stroutput := '';
  v_transactionidout := '';
  v_parmdefinition := N'@StrOutPut Nvarchar(100) OUTPUT,@TransactionIdOut Nvarchar(100) OUTPUT';
  v_querysql := '';
  v_querysql := 'EXEC [' || v_db_name || '].[DBO].[USP_SHOPING_TRANSACTION_DEBIT] ' || CAST(v_ref_regno AS VARCHAR(10)) || ',
			' || CAST(v_ewalletpayablebalance AS VARCHAR(20)) || ',''' || v_orderid || ''',@StrOutPut Out,@TransactionIdOut Out';
  EXECUTE v_querysql;
  UPDATE tbl_order_master SET transactionid = v_transactionidout WHERE orderid = v_orderid;
  IF (v_stroutput <> 'success') THEN
  UPDATE tbl_order_master SET intstatus = 5, description = 'Order status is Cancel', status = 'Cancel', transactionid = v_stroutput WHERE orderid = v_orderid;
  END IF;
  END IF;
  IF (v_iscouponapplyed = 1) THEN
  SELECT pointredeempercent INTO v_pointredeempercent FROM tbl_distributor WHERE did = v_distributorid;
  v_discountamount := ((v_total_order_price * v_pointredeempercent) / 100);
  v_regno := 0;
  IF EXISTS(SELECT 1 FROM db_mlmsoftware.dbo.portal_login WHERE username = v_username AND tpassword = v_transactionpassword AND active = 1) THEN
  SELECT regno INTO v_regno FROM db_mlmsoftware.dbo.portal_login WHERE username = v_username AND tpassword = v_transactionpassword AND active = 1;
  ELSE
  SELECT 0 INTO v_regno;
  END IF;
  v_querysql := 'EXEC [DB_MLMSOFTWARE].[DBO].[USP_SHOPING_TRANSACTION_DEBIT] ' || CAST(v_ref_regno AS VARCHAR(10)) || ',
			' || CAST(v_discountamount AS VARCHAR(20)) || ',''' || v_orderid || ''',@StrOutPut Out,@TransactionIdOut Out';
  EXECUTE v_querysql;
  UPDATE tbl_order_master SET discountcodetransactionid = v_transactionidout WHERE orderid = v_orderid;
  IF (v_stroutput <> 'success') THEN
  UPDATE tbl_order_master SET intstatus = 5, description = 'Order status is Cancelled', status = 'Cancelled', discountcodetransactionid = v_stroutput WHERE orderid = v_orderid;
  END IF;
  END IF;
  ELSE
  RAISE NOTICE '%', 'ELSE CONDITION';
  END IF;
  v_count := v_count + 1;
  END LOOP;
  v_strresult := v_orderidtemp || '^add';
  DROP TABLE IF EXISTS tmp_temp2;
  DROP TABLE IF EXISTS tmp_temp1;
  IF (0 <> 0) THEN
  -- ROLLBACK (removed)
  v_strresult := 'Some error occured';
  RETURN;
  END IF;
  -- COMMIT (removed)
END;
$$;


--
-- Name: backup_usp_distributordiscount(integer, integer, integer, character varying, character varying, numeric); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.backup_usp_distributordiscount(v_distributorid integer DEFAULT 1, v_mode integer DEFAULT 2, v_plid integer DEFAULT 1, v_username character varying DEFAULT 'root'::character varying, v_transactionpassword character varying DEFAULT 'UZPG00xlEHCc2FmEZnQtYQ=='::character varying, v_jp numeric DEFAULT 0.00) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_ref_regno VARCHAR(10);
  v_db_name VARCHAR(100);
  v_query text;
  v_regno INT;
BEGIN
  IF (v_mode = 1) THEN
  RETURN QUERY SELECT ewalletconsumeper, coinwalletconsumeper, commissionwalletconsumeper, (v_jp) AS pointredeempercent FROM tbl_distributor WHERE did = v_distributorid;
  END IF;
  IF (v_mode = 2) THEN
  IF (v_username = '' AND v_transactionpassword = '') THEN
  v_ref_regno := '';
  v_query := '';
  SELECT db_name INTO v_db_name FROM tbl_distributor WHERE did = v_distributorid;
  SELECT reference_regno INTO v_ref_regno FROM tbl_customerlogin WHERE clid = v_plid;
  v_query := 'SELECT AVAILABLE_FUND AS EWALLETCONSUMEPER,AVAILABLECOINWALLET AS COINWALLETCONSUMEPER,
		              AVAILABLECOMMISSIONWALLET AS COMMISSIONWALLETCONSUMEPER,TOTALAVAILABLESHOPPINGPOINTS AS POINTREDEEMPERCENT FROM 
					  [' || v_db_name || '].[DBO].MEMBER_PERFORMANCE   WHERE REGNO =' || v_ref_regno;
  EXECUTE v_query;
  ELSE
  v_regno := 0;
  IF EXISTS(SELECT 1 FROM db_mlmsoftware.dbo.portal_login WHERE username = v_username AND tpassword = v_transactionpassword AND active = 1) THEN
  SELECT regno INTO v_regno FROM db_mlmsoftware.dbo.portal_login WHERE username = v_username AND tpassword = v_transactionpassword AND active = 1;
  ELSE
  SELECT 0 INTO v_regno;
  END IF;
  v_query := 'SELECT AVAILABLE_FUND AS EWALLETCONSUMEPER,AVAILABLECOINWALLET AS COINWALLETCONSUMEPER,
		              AVAILABLECOMMISSIONWALLET AS COMMISSIONWALLETCONSUMEPER,TOTALAVAILABLESHOPPINGPOINTS AS POINTREDEEMPERCENT FROM 
					  [DB_MLMSOFTWARE].[DBO].MEMBER_PERFORMANCE   WHERE REGNO =' || CAST(v_regno AS VARCHAR(10));
  EXECUTE v_query;
  END IF;
  END IF;
END;
$$;


--
-- Name: bindingkeywordlist(bigint); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.bindingkeywordlist(v_pmid bigint) RETURNS text
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_returnoutallkeyword text;
  v_totalkeyword text;
  v_keyid text;
  v_newkeyid varchar(100);
BEGIN
  SELECT keyid INTO v_keyid FROM portal_master WHERE pmid = v_pmid;
  SELECT COALESCE(v_returnoutallkeyword || ', ', '') || keywordname INTO v_returnoutallkeyword FROM keyword_master WHERE kmid IN (SELECT value FROM dbo.SPLITSTRINGBYCOMMA(v_keyid));
  RETURN (v_returnoutallkeyword);
  RETURN NULL;
END;
$$;


--
-- Name: categrysearch(character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.categrysearch(v_catname character varying DEFAULT ''::character varying) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF (v_catname <> '') THEN
  RETURN QUERY SELECT pc.catname FROM product_category AS pc WHERE pc.catname LIKE v_catname || '%' AND catactive = 1 ORDER BY catname ASC NULLS FIRST;
  END IF;
END;
$$;


--
-- Name: check_username_ticket(character varying, character varying, character varying, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.check_username_ticket(v_accounttype character varying DEFAULT ''::character varying, v_username character varying DEFAULT ''::character varying, v_intresult character varying DEFAULT ''::character varying, v_did integer DEFAULT 1) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF (v_accounttype = '2') THEN
  IF EXISTS(SELECT 1 FROM tbl_customerlogin WHERE (phone = v_username OR emailid = v_username) AND did = v_did) THEN
  v_intresult := '1';
  ELSE
  v_intresult := '0';
  END IF;
  END IF;
  IF (v_accounttype = '1') THEN
  IF EXISTS(SELECT 1 FROM portal_login WHERE (phone = v_username OR emailid = v_username)) THEN
  v_intresult := '1';
  ELSE
  v_intresult := '0';
  END IF;
  END IF;
  IF (v_accounttype = '3') THEN
  IF EXISTS(SELECT 1 FROM tbl_distributor WHERE (phone = v_username OR emailid = v_username)) THEN
  v_intresult := '1';
  ELSE
  v_intresult := '0';
  END IF;
  END IF;
  RETURN QUERY SELECT v_intresult;
END;
$$;


--
-- Name: cpccatdetails(character varying, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.cpccatdetails(v_catname character varying DEFAULT ''::character varying, v_cid integer DEFAULT 0) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF (v_catname <> '' AND v_cid <> 0) THEN
  RETURN QUERY SELECT ROW_NUMBER() OVER (ORDER BY pc.catname ASC NULLS FIRST) AS number, pc.catid, pc.catname, (CASE WHEN tcc.cpc IS NULL THEN 0 ELSE tcc.cpc END) AS cpc, cm.currencycode AS currencysymbol FROM product_category AS pc LEFT JOIN tbl_cpcforcatergory AS tcc ON pc.catid = tcc.catid LEFT JOIN country AS cm ON tcc.cid = cm.cid WHERE pc.catname LIKE v_catname || '%' AND tcc.cid = v_cid ORDER BY catname ASC NULLS FIRST;
  ELSE
  IF (v_catname = '' AND v_cid <> 0) THEN
  RETURN QUERY SELECT ROW_NUMBER() OVER (ORDER BY pc.catname ASC NULLS FIRST) AS number, pc.catid, pc.catname, (CASE WHEN tcc.cpc IS NULL THEN 0 ELSE tcc.cpc END) AS cpc, cm.currencycode AS currencysymbol FROM product_category AS pc LEFT JOIN tbl_cpcforcatergory AS tcc ON pc.catid = tcc.catid LEFT JOIN country AS cm ON tcc.cid = cm.cid WHERE tcc.cid = v_cid ORDER BY catname ASC NULLS FIRST;
  RETURN QUERY SELECT * FROM country WHERE cactive = 1;
  ELSE
  RETURN QUERY SELECT ROW_NUMBER() OVER (ORDER BY pc.catname ASC NULLS FIRST) AS number, pc.catid, pc.catname, (CASE WHEN tcc.cpc IS NULL THEN 0 ELSE tcc.cpc END) AS cpc, cm.currencycode AS currencysymbol FROM product_category AS pc LEFT JOIN tbl_cpcforcatergory AS tcc ON pc.catid = tcc.catid LEFT JOIN country AS cm ON tcc.cid = cm.cid WHERE pc.catname LIKE v_catname || '%' AND tcc.cid = 21 ORDER BY catname ASC NULLS FIRST;
  END IF;
  END IF;
END;
$$;


--
-- Name: csvtotable(text); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.csvtotable(instr text) RETURNS TABLE(id bigint)
    LANGUAGE plpgsql IMMUTABLE
    AS $_$
BEGIN
    RETURN QUERY
    SELECT NULLIF(trim(s), '')::BIGINT
    FROM unnest(string_to_array(InStr, ',')) AS s
    WHERE trim(s) <> '' AND trim(s) ~ '^[0-9]+$';
END;
$_$;


--
-- Name: cursor_update_details_into_portal_master(); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.cursor_update_details_into_portal_master() RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_pmid BIGINT;
  v_lankmark text;
  v_comemailid text;
  v_yearofestable varchar(100);
  v_annualturnover numeric(19,4);
  v_noofemployee varchar(100);
  v_companyimage varchar(500);
  v_doc timestamp;
  v_companyprofileimage varchar(500);
  v_zipcode VARCHAR(100);
  v_cpertitle varchar(500);
  v_contactperson varchar(500);
  v_lname varchar(500);
  v_cpermobileno varchar(500);
  v_cperdesignation varchar(500);
  cursor_for_update CURSOR FOR SELECT pmid, lankmark, comemailid, yearofestable, annualturnover, noofemployee, companyimage, doc, companyprofileimage, zipcode, cpertitle, contactperson, lname, cpermobileno, cperdesignation FROM portal_master_details;
BEGIN
  OPEN cursor_for_update;
  IF v_cursor_rows > 0 THEN
  FETCH cursor_for_update INTO v_pmid,v_lankmark,v_comemailid,v_yearofestable,v_annualturnover,v_noofemployee,v_companyimage,v_doc,v_companyprofileimage,v_zipcode,v_cpertitle ,v_contactperson ,v_lname  ,v_cpermobileno  ,v_cperdesignation;
  WHILE FOUND LOOP
  UPDATE portal_master SET lankmark = v_lankmark, comemailid = v_comemailid, yearofestable = v_yearofestable, annualturnover = v_annualturnover, noofemployee = v_noofemployee, companyimage = v_companyimage, doc = v_doc, companyprofileimage = v_companyprofileimage, pincode = v_zipcode WHERE pmid = v_pmid;
  UPDATE portal_login SET title = v_cpertitle, fname = v_contactperson, lname = v_lname, phone = v_cpermobileno, designation = v_cperdesignation WHERE pmid = v_pmid;
  FETCH cursor_for_update INTO v_pmid,v_lankmark,v_comemailid,v_yearofestable,v_annualturnover,v_noofemployee,v_companyimage,v_doc,v_companyprofileimage,v_zipcode,v_cpertitle ,v_contactperson ,v_lname  ,v_cpermobileno  ,v_cperdesignation;
  END LOOP;
  END IF;
  CLOSE cursor_for_update;
  -- DEALLOCATE (removed)
END;
$$;


