--
-- Name: fact(integer, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.fact(v_number integer DEFAULT 5, INOUT v_retval integer DEFAULT 0) RETURNS integer
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_in INTEGER;
  v_out INTEGER;
BEGIN
  IF v_number <> 1 THEN
  SELECT v_number INTO v_in;
  SELECT v_retval INTO v_out FROM dbo.fact(v_number => v_in, v_retval => v_out);
  SELECT v_number * v_out INTO v_retval;
  v_number := v_number - 1;
  ELSE
  SELECT 1 INTO v_retval;
  END IF;
  RETURN;
END;
$$;


