--
-- Name: findkeycatidandsearchtype(character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.findkeycatidandsearchtype(v_searchvalue character varying) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_existpmid varchar(10);
  v_existcatid varchar(10);
  v_existkmid varchar(10);
  v_searchtype int;
  v_keycatid int;
  v_keycattype varchar(10);
BEGIN
  v_searchtype := 0;
  v_keycatid := 0;
  v_keycattype := '';
  IF EXISTS(SELECT catid FROM product_category WHERE catname = v_searchvalue AND catactive = 1) THEN
  v_existcatid := 'yes';
  ELSE
  v_existcatid := 'no';
  END IF;
  IF EXISTS(SELECT kmid FROM keyword_master WHERE keywordname = v_searchvalue AND kactive = 1) THEN
  v_existkmid := 'yes';
  ELSE
  v_existkmid := 'no';
  END IF;
  IF (v_existkmid = 'yes' AND v_existcatid = 'no') THEN
  v_searchtype := 2;
  v_keycattype := 'k';
  SELECT kmid INTO v_keycatid FROM keyword_master WHERE keywordname = v_searchvalue AND kactive = 1;
  END IF;
  IF (v_existkmid = 'no' AND v_existcatid = 'yes') THEN
  v_searchtype := 3;
  v_keycattype := 'c';
  SELECT catid INTO v_keycatid FROM product_category WHERE catname = v_searchvalue AND catactive = 1;
  END IF;
  IF (v_existkmid = 'yes' AND v_existcatid = 'yes') THEN
  v_searchtype := 3;
  v_keycattype := 'c';
  SELECT catid INTO v_keycatid FROM product_category WHERE catname = v_searchvalue AND catactive = 1;
  END IF;
  RETURN QUERY SELECT v_keycatid AS keycatid, v_keycattype AS keycattype;
END;
$$;


--
-- Name: findtotalreating(bigint); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.findtotalreating(v_pmid bigint) RETURNS integer
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_returnoutrating int;
  v_totalsum int;
  v_totalcount int;
  v_avg int;
BEGIN
  v_returnoutrating := 0;
  SELECT COALESCE(SUM(stars), 0) INTO v_totalsum FROM tbl_reviewmaster WHERE pmid = v_pmid AND status = 1;
  SELECT COUNT(rwid) INTO v_totalcount FROM tbl_reviewmaster WHERE pmid = v_pmid AND status = 1;
  IF (v_totalcount = 0) THEN
  v_returnoutrating := 0;
  END IF;
  IF (v_totalcount > 0) THEN
  v_returnoutrating := v_totalsum / v_totalcount;
  END IF;
  IF (v_returnoutrating IS NULL) THEN
  v_returnoutrating := 0;
  END IF;
  RETURN (v_returnoutrating);
  RETURN NULL;
END;
$$;


