  v_intresult := 1;
  IF (v_searchtypeparam = 1) THEN
  IF EXISTS(SELECT pmid FROM portal_master WHERE companyname = v_searchvalue AND active = 1 AND isverified = 1 AND cid = v_cid) THEN
  v_existpmid := 'YES';
  ELSE
  v_existpmid := 'NO';
  END IF;
