  IF (v_searchtypeparam = 2) THEN
  IF EXISTS(SELECT pmd.pmid FROM portal_deal_master AS pmd INNER JOIN portal_master AS pm ON pm.pmid = pmd.pmid WHERE pmd.title = v_searchvalue AND pmd.active = 1 AND isverified = 1 AND cid = v_cid) THEN
