  IF EXISTS(SELECT kmid FROM keyword_master WHERE keywordname = v_searchvalue AND kactive = 1) THEN
  v_existkmid := 'YES';
  ELSE
  v_existkmid := 'NO';
  END IF;
  IF (v_existpmid = 'YES' AND v_existkmid = 'NO' AND v_existcatid = 'NO') THEN
  v_searchtype := 1;
  END IF;
  IF (v_existpmid = 'NO' AND v_existkmid = 'YES' AND v_existcatid = 'NO') THEN
  v_searchtype := 2;
  END IF;
  IF (v_existpmid = 'NO' AND v_existkmid = 'NO' AND v_existcatid = 'YES') THEN
  v_searchtype := 3;
  END IF;
  IF (v_existpmid = 'YES' AND v_existkmid = 'YES' AND v_existcatid = 'YES') THEN
  v_searchtype := 3;
  END IF;
  IF (v_existpmid = 'NO' AND v_existkmid = 'NO' AND v_existcatid = 'NO') THEN
  v_searchtype := 0;
  END IF;
  IF (v_existpmid = 'YES' AND v_existkmid = 'YES' AND v_existcatid = 'NO') THEN
  v_searchtype := 2;
  END IF;
  IF (v_existpmid = 'YES' AND v_existkmid = 'NO' AND v_existcatid = 'YES') THEN
  v_searchtype := 3;
  END IF;
  IF (v_existpmid = 'NO' AND v_existkmid = 'YES' AND v_existcatid = 'YES') THEN
  v_searchtype := 3;
  END IF;
END;
$$;


