--
-- Name: fn_checkvalidurl_subdomain(text); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.fn_checkvalidurl_subdomain(v_actualurl text) RETURNS integer
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_valid int;
  v_isexists int;
  v_isnotexists int;
  v_lenghtofurl int;
  v_i int;
  v_insidelenghturl int;
BEGIN
  v_isexists := 0;
  v_isnotexists := 0;
  v_i := 1;
  v_lenghtofurl := LENGTH(CAST(v_actualurl AS TEXT));
  WHILE (v_i <= v_lenghtofurl) LOOP
  v_insidelenghturl := LENGTH(CAST(v_actualurl AS TEXT));
  SELECT SUBSTRING(v_actualurl FROM 2 FOR v_insidelenghturl) INTO v_actualurl;
  IF (v_insidelenghturl > 2) THEN
  IF EXISTS(SELECT pltid FROM portal_login_temp WHERE sp_url LIKE '%' || v_actualurl || '%') THEN
  v_isexists := 1;
  ELSE
  v_isnotexists := 1;
  END IF;
  END IF;
  v_i := v_i + 1;
  END LOOP;
  IF (v_isexists = 1) THEN
  v_valid := 1;
  ELSE
  v_valid := 0;
  END IF;
  RETURN v_valid;
  RETURN NULL;
END;
$$;


