--
-- Name: fun_getratingofsubproduct(bigint); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.fun_getratingofsubproduct(v_subproductid bigint DEFAULT 0) RETURNS character varying
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_countrev INT;
  v_totalstar INT;
  v_ratingstar INT;
BEGIN
  v_countrev := 0;
  v_totalstar := 0;
  v_ratingstar := 0;
  IF (COALESCE(v_subproductid, 0) <> 0) THEN
  SELECT COUNT(rwid) INTO v_countrev FROM tbl_reviewmaster WHERE pmid = v_subproductid AND status = 1;
  SELECT COALESCE(SUM(stars), 0) INTO v_totalstar FROM tbl_reviewmaster WHERE pmid = v_subproductid AND status = 1;
  IF (v_countrev > 0 AND v_totalstar > 0) THEN
  v_ratingstar := v_totalstar / v_countrev;
  END IF;
  END IF;
  RETURN COALESCE(v_ratingstar, 0);
  RETURN NULL;
END;
$$;


