--
-- Name: funsplitstring(text, character); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.funsplitstring(v_input text, v_character character) RETURNS TABLE(item character varying)
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_startindex INT;
  v_endindex INT;
BEGIN
  DROP TABLE IF EXISTS v_output;
  CREATE TEMP TABLE v_output (Item varchar(1000)) ON COMMIT DROP;
  v_startindex := 1;
  IF SUBSTRING(v_input FROM LENGTH(CAST(v_input AS TEXT)) - 1 FOR LENGTH(CAST(v_input AS TEXT))) <> v_character THEN
  v_input := v_input || v_character;
  END IF;
  WHILE POSITION(v_character IN v_input) > 0 LOOP
  v_endindex := POSITION(v_character IN v_input);
  INSERT INTO v_output (item) SELECT SUBSTRING(v_input FROM v_startindex FOR v_endindex - 1);
  v_input := SUBSTRING(v_input FROM v_endindex + 1 FOR LENGTH(CAST(v_input AS TEXT)));
  END LOOP;
  RETURN QUERY SELECT * FROM v_output;
  RETURN;
  RETURN QUERY SELECT * FROM v_output;
  RETURN;
END;
$$;


