--
-- Name: generateurl_on_pmid(bigint); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.generateurl_on_pmid(v_pmid bigint) RETURNS text
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_rawurl text;
  v_catid text;
  v_indexofcomma int;
  v_title text;
  v_ctname varchar(100);
  v_countryname varchar(100);
  v_catname varchar(100);
  v_autocatid text;
BEGIN
  SELECT catid, autocatid, RTRIM(LTRIM(REPLACE(title, '.', ''))), RTRIM(LTRIM(cityname)), RTRIM(LTRIM(c.countryname)) INTO v_catid, v_autocatid, v_title, v_ctname, v_countryname FROM portal_master AS pm INNER JOIN city AS ct ON pm.ctid = ct.ctid INNER JOIN country AS c ON pm.cid = c.cid WHERE pm.pmid = v_pmid;
  v_indexofcomma := CAST(POSITION(',' IN v_catid) AS INT);
  v_catid := SUBSTRING(v_catid FROM 0 FOR v_indexofcomma);
  IF (v_catid = '') THEN
  SELECT COALESCE(catid, '') INTO v_catid FROM portal_master WHERE pmid = v_pmid;
  END IF;
  IF (v_catid = '' OR v_catid = '0') THEN
  v_indexofcomma := CAST(POSITION(',' IN v_autocatid) AS INT);
  IF (v_indexofcomma = 0) THEN
  v_catid := v_autocatid;
  ELSE
  v_catid := SUBSTRING(v_autocatid FROM 0 FOR v_indexofcomma);
  END IF;
  END IF;
  SELECT COALESCE(RTRIM(LTRIM(catname)), '') INTO v_catname FROM product_category WHERE catid = CAST(v_catid AS INT);
  IF NOT EXISTS(SELECT COALESCE(RTRIM(LTRIM(catname)), '') FROM product_category WHERE catid = CAST(v_catid AS INT)) THEN
  v_indexofcomma := CAST(POSITION(',' IN v_autocatid) AS INT);
  IF (v_indexofcomma = 0) THEN
  v_catid := v_autocatid;
  ELSE
  v_catid := SUBSTRING(v_autocatid FROM 0 FOR v_indexofcomma);
  END IF;
  SELECT COALESCE(RTRIM(LTRIM(catname)), '') INTO v_catname FROM product_category WHERE catid = CAST(v_catid AS INT);
  END IF;
  v_rawurl := v_title || ' ' || v_catname || ' in ' || v_ctname || ' in ' || v_countryname || ' ' || CAST(v_pmid AS VARCHAR(100));
  v_rawurl := LOWER(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(v_rawurl, ' ', '-'), '&', 'and'), '/', '-'), '|', '-'), '#', '-'), '*', '-'), ':', '-'), '+', 'plus'));
  v_rawurl := 'business-details/' || v_rawurl;
  RETURN v_rawurl;
  RETURN NULL;
END;
$$;


--
-- Name: genratingdeallistingsurl(bigint); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.genratingdeallistingsurl(v_dealid bigint) RETURNS text
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_returnouturl text;
  v_autocatid text;
  v_indexofcomma INT;
  v_catid text;
  v_newcatid VARCHAR(100);
  v_pmid BIGINT;
BEGIN
  SELECT pmid INTO v_pmid FROM portal_deal_master WHERE dealid = v_dealid;
  SELECT catid, COALESCE(autocatid, '') INTO v_catid, v_autocatid FROM portal_master WHERE pmid = v_pmid;
  v_newcatid := CASE WHEN POSITION(',' IN v_catid) > 0 THEN SUBSTRING(v_catid FROM 1 FOR POSITION(',' IN v_catid) - 1) ELSE v_catid END;
  IF (v_catid = '' OR v_catid = '0') THEN
  v_indexofcomma := CAST(POSITION(',' IN v_autocatid) AS INT);
  IF (v_indexofcomma = 0) THEN
  v_catid := v_autocatid;
  ELSE
  v_catid := SUBSTRING(v_autocatid FROM 0 FOR v_indexofcomma);
  END IF;
  v_newcatid := v_catid;
  END IF;
  SELECT LOWER(REPLACE(REPLACE(REPLACE(REPLACE((pdm.title || '-' || pc.catname || '-in-' || c.cityname || '-in-' || countr.countryname || '-' || CAST(pdm.dealid AS VARCHAR(100))), ' ', '-'), '.', ''), '&', 'and'), '/', ' ')) INTO v_returnouturl FROM portal_master AS pm INNER JOIN portal_deal_master AS pdm ON pm.pmid = pdm.pmid INNER JOIN product_category AS pc ON v_newcatid = pc.catid INNER JOIN city AS c ON pm.ctid = c.ctid INNER JOIN country AS countr ON pm.cid = countr.cid WHERE pdm.dealid = v_dealid;
  RETURN ('/deals/' || v_returnouturl);
  RETURN NULL;
END;
$$;


--
-- Name: genratingurl(bigint); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.genratingurl(v_pmid bigint) RETURNS text
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_returnouturl text;
  v_autocatid text;
  v_indexofcomma INT;
  v_catid text;
  v_newcatid VARCHAR(100);
BEGIN
  SELECT catid, COALESCE(autocatid, '') INTO v_catid, v_autocatid FROM portal_master WHERE pmid = v_pmid;
  v_newcatid := CASE WHEN POSITION(',' IN v_catid) > 0 THEN SUBSTRING(v_catid FROM 1 FOR POSITION(',' IN v_catid) - 1) ELSE v_catid END;
  IF (v_catid = '' OR v_catid = '0') THEN
  v_indexofcomma := CAST(POSITION(',' IN v_autocatid) AS INT);
  IF (v_indexofcomma = 0) THEN
  v_catid := v_autocatid;
  ELSE
  v_catid := SUBSTRING(v_autocatid FROM 0 FOR v_indexofcomma);
  END IF;
  v_newcatid := v_catid;
  END IF;
  SELECT REPLACE(REPLACE(REPLACE(REPLACE((pm.companyname), ' ', '-'), '.', ''), '&', 'and'), '/', ' ') INTO v_returnouturl FROM portal_master AS pm INNER JOIN product_category AS pc ON v_newcatid = pc.catid INNER JOIN city AS c ON pm.ctid = c.ctid INNER JOIN country AS countr ON pm.cid = countr.cid WHERE pm.pmid = v_pmid;
  RETURN ('/' || v_returnouturl);
  RETURN NULL;
END;
$$;


