    LANGUAGE plpgsql
    AS $$
DECLARE
  v_refid_out varchar(100);
  v_logiinid varchar(100);
  v_pwd varchar(50);
BEGIN
  -- BEGIN TRAN (removed)
  IF NOT EXISTS(SELECT plid FROM portal_login WHERE COALESCE(qpayregno, 0) = v_qpayregno) THEN
  v_strresult := 'error^Please create Qbox user account first, then create Referal ID !';
  -- COMMIT (removed)
  RETURN;
  END IF;
  IF (v_mode = 'create' OR v_mode = 'update') THEN
  IF (v_refid = '') THEN
  v_strresult := 'error^Please enter Referal ID  !';
  -- COMMIT (removed)
  RETURN;
  END IF;
  IF EXISTS(SELECT plid FROM portal_login WHERE refral_id = v_refid AND qpayregno <> v_qpayregno) THEN
  v_strresult := 'error^Referal ID already exists, Please use another one !';
