  IF (v_mode = 'getrefid') THEN
  SELECT COALESCE(refral_id, ''), loginid, password INTO v_refid_out, v_logiinid, v_pwd FROM portal_login WHERE qpayregno = v_qpayregno;
  v_strresult := 'success^' || v_refid_out || '^' || v_logiinid || '^' || v_pwd;
  END IF;
  IF (0 <> 0) THEN
  v_strresult := 'error^Some error occured';
  -- ROLLBACK (removed)
  RETURN;
  END IF;
  -- COMMIT (removed)
END;
$$;


--
-- Name: get_resellerallpackages(integer, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.get_resellerallpackages(v_trsid integer DEFAULT 0, v_did integer DEFAULT 0) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_idtemp Int;
BEGIN
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp ON COMMIT DROP AS SELECT package.trpid, COALESCE(services.servicename, '') AS servicename, COALESCE(package.packagename, '') AS packagename, COALESCE(package.packageamount, 0) AS packageamount, COALESCE(package.packagefeatures, '') AS packagefeatures, COALESCE(package.active, '') AS active, CAST('' AS VARCHAR(100)) AS buystatus, package.trsid, COALESCE(CAST(istrial AS INT), 0) AS istrial FROM tbl_reseller_packages AS package INNER JOIN tbl_reseller_services AS services ON package.trsid = services.trsid WHERE package.active = 1 AND package.trsid = v_trsid;
  UPDATE tmp_temp SET buystatus = 'Already Purchased' FROM tmp_temp INNER JOIN tbl_reseller_purchased_packages_history ON tbl_reseller_purchased_packages_history.trpid = tmp_temp.trpid AND tbl_reseller_purchased_packages_history.trsid = tmp_temp.trsid WHERE did = v_did AND tmp_temp.trsid = v_trsid AND tbl_reseller_purchased_packages_history.did = v_did;
  UPDATE tmp_temp SET buystatus = 'Already Purchased' FROM tmp_temp INNER JOIN tbl_reseller_purchased_packages ON tbl_reseller_purchased_packages.trpid = tmp_temp.trpid AND tbl_reseller_purchased_packages.trsid = tmp_temp.trsid WHERE did = v_did AND tmp_temp.trsid = v_trsid AND tbl_reseller_purchased_packages.did = v_did;
  v_idtemp := 0;
  SELECT COALESCE(MAX(trpid), 0) INTO v_idtemp FROM tbl_reseller_purchased_packages WHERE did = v_did AND trsid = v_trsid GROUP BY trsid;
  UPDATE tmp_temp SET buystatus = 'N/A' WHERE NOT trpid IN (SELECT trpid FROM tbl_reseller_purchased_packages WHERE did = v_did AND trsid = v_trsid) AND buystatus <> 'Already Purchased' AND trpid < v_idtemp;
  UPDATE tmp_temp SET buystatus = 'N/A' WHERE NOT trpid IN (SELECT trpid FROM tbl_reseller_purchased_packages_history WHERE did = v_did AND trsid = v_trsid) AND buystatus <> 'Already Purchased' AND trpid < v_idtemp;
  UPDATE tmp_temp SET buystatus = 'BUY' WHERE NOT trpid IN (SELECT trpid FROM tbl_reseller_purchased_packages WHERE did = v_did AND trsid = v_trsid) AND buystatus <> 'Already Purchased' AND trpid > v_idtemp;
  UPDATE tmp_temp SET buystatus = 'BUY' WHERE NOT trpid IN (SELECT trpid FROM tbl_reseller_purchased_packages_history WHERE did = v_did AND trsid = v_trsid) AND buystatus <> 'Already Purchased' AND trpid > v_idtemp;
  UPDATE tmp_temp SET buystatus = 'BUY' WHERE NOT trpid IN (SELECT trpid FROM tbl_reseller_purchased_packages_history WHERE did = v_did AND trsid = v_trsid) AND buystatus <> 'Already Purchased' AND buystatus <> 'N/A' AND buystatus <> 'BUY';
  UPDATE tmp_temp SET buystatus = 'BUY' WHERE NOT trpid IN (SELECT trpid FROM tbl_reseller_purchased_packages WHERE did = v_did AND trsid = v_trsid) AND buystatus <> 'Already Purchased' AND buystatus <> 'BUY' AND buystatus <> 'N/A';
  RETURN QUERY SELECT * FROM tmp_temp;
  DROP TABLE IF EXISTS tmp_temp;
END;
$$;


