--
-- Name: getallattributelist(integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.getallattributelist(v_subcatid integer DEFAULT 1371) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_maincatid INT;
  v_catid INT;
  v_count INT;
  v_totalcount INT;
  v_tempdid INT;
  v_attrvalue text;
BEGIN
  -- BEGIN TRAN (removed)
  v_maincatid := 0;
  v_catid := 0;
  IF (v_subcatid = 0) THEN
  -- COMMIT (removed)
  RETURN;
  END IF;
  v_count := 1;
  v_totalcount := 1;
  v_tempdid := 0;
  v_attrvalue := '';
  IF (v_subcatid > 0) THEN
  SELECT maincatid, catid INTO v_maincatid, v_catid FROM dbo.tbl_sub_category WHERE subcatid = v_subcatid;
  DROP TABLE IF EXISTS tmp_datatemp;
  CREATE TEMP TABLE tmp_datatemp (ROWNUMBER INT GENERATED BY DEFAULT AS IDENTITY ,DID INT,DIDNAME VARCHAR(100),VALUE text,isSelectiveAttr boolean) ON COMMIT DROP;
  INSERT INTO tmp_datatemp SELECT tawc.ddl_id, tdd.name, '', isselectiveattr FROM tbl_attributes_with_category AS tawc LEFT JOIN tbl_dropdown AS tdd ON tawc.ddl_id = tdd.ddid WHERE ((sub_cat_id = v_subcatid OR (cat_id = v_catid AND sub_cat_id = 0)) OR (main_cat_id = v_maincatid AND cat_id = 0 AND sub_cat_id = 0)) AND is_active = 1;
  SELECT COUNT(1) INTO v_totalcount FROM tmp_datatemp;
  WHILE (v_totalcount >= v_count) LOOP
  SELECT did INTO v_tempdid FROM tmp_datatemp WHERE rownumber = v_count;
  SELECT COALESCE(v_attrvalue || ',', '') || content INTO v_attrvalue FROM tbl_dropdowndetails WHERE ddid = v_tempdid AND status = 1;
  v_attrvalue := SUBSTRING(v_attrvalue FROM 2 FOR LENGTH(CAST(v_attrvalue AS TEXT)));
  UPDATE tmp_datatemp SET value = v_attrvalue WHERE rownumber = v_count;
  v_attrvalue := '';
  v_count := v_count + 1;
  END LOOP;
  RETURN QUERY SELECT * FROM tmp_datatemp;
  DROP TABLE IF EXISTS tmp_datatemp;
  END IF;
  -- COMMIT (removed)
END;
$$;


