--
-- Name: getdatefunction(character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.getdatefunction(v_addate character varying) RETURNS character varying
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_minut varchar(30);
  v_value varchar(200);
  v_hours varchar(30);
  v_day varchar(50);
BEGIN
  SELECT (SELECT CAST(EXTRACT(epoch FROM CAST(CAST(GETUTCDATE() + INTERVAL '330 MINUTE' AS TIMESTAMP) AS TIMESTAMP) - CAST(CAST(v_addate AS TIMESTAMP) AS TIMESTAMP)) / 60 AS BIGINT)) INTO v_minut;
  SELECT (SELECT CAST(EXTRACT(epoch FROM CAST(CAST(GETUTCDATE() + INTERVAL '330 MINUTE' AS TIMESTAMP) AS TIMESTAMP) - CAST(CAST(v_addate AS TIMESTAMP) AS TIMESTAMP)) / 3600 AS BIGINT)) INTO v_hours;
  SELECT (SELECT CAST(EXTRACT(epoch FROM CAST(CAST(GETUTCDATE() + INTERVAL '330 MINUTE' AS TIMESTAMP) AS TIMESTAMP) - CAST(CAST(v_addate AS TIMESTAMP) AS TIMESTAMP)) / 86400 AS BIGINT)) INTO v_day;
  IF (v_minut = 1) THEN
  v_value := '1 minute ago';
  ELSE
  IF (v_minut > 1 AND v_minut < 60) THEN
  v_value := v_minut || ' minutes ago';
  ELSE
  IF (v_hours = 1) THEN
  v_value := '1 hour ago';
  ELSE
  IF (v_hours > 1 AND v_hours < 24) THEN
  v_value := v_hours || ' hours ago';
  ELSE
  IF (v_day = 1) THEN
  v_value := '1 day ago';
  ELSE
  IF (v_day > 1) THEN
  v_value := v_day || ' days ago';
  ELSE
  v_value := 'Few second ago';
  END IF;
  END IF;
  END IF;
  END IF;
  END IF;
  END IF;
  RETURN v_value;
  RETURN NULL;
END;
$$;


--
-- Name: getfriendlydatetimevalue(timestamp without time zone); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.getfriendlydatetimevalue(v_comparedate timestamp without time zone) RETURNS character varying
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_now timestamp;
  v_hours int;
  v_minutes int;
  v_suff varchar(256);
  v_found boolean;
  v_seconds int;
BEGIN
  v_found := 0;
  v_now := CURRENT_TIMESTAMP;
  v_hours := CAST(AGE(CAST(CAST(v_now AS TIMESTAMP) AS TIMESTAMP), CAST(CAST(v_comparedate AS TIMESTAMP) AS TIMESTAMP)) AS BIGINT) / 60;
  v_minutes := CAST(EXTRACT(epoch FROM CAST(CAST(CURRENT_TIMESTAMP AS TIMESTAMP) AS TIMESTAMP) - CAST(CAST(v_comparedate AS TIMESTAMP) AS TIMESTAMP)) / 60 AS BIGINT);
  v_seconds := v_minutes * 60;
  IF v_seconds <= 60 THEN
  v_suff := ' Just Now';
  v_found := 1;
  RETURN CAST(v_suff AS VARCHAR(30));
  END IF;
  IF (v_seconds > 60 AND v_minutes < 60) THEN
  v_suff := ' Minutes Ago';
  v_found := 1;
  RETURN CAST(v_minutes AS VARCHAR(30)) || v_suff;
  END IF;
  IF v_hours = 1 THEN
  v_suff := ' Hour Ago';
  v_found := 1;
  RETURN CAST(v_hours AS VARCHAR(30)) || v_suff;
  END IF;
  IF v_hours > 1 AND v_hours < 24 THEN
  v_suff := ' Hours Ago';
  RETURN CAST(v_hours AS VARCHAR(30)) || v_suff;
  v_found := 1;
  END IF;
  IF v_hours >= 24 AND v_hours <= 48 AND v_found = 0 THEN
  v_suff := ' Yesterday';
  RETURN CAST(v_suff AS VARCHAR(30));
  v_found := 1;
  END IF;
  IF v_hours > 48 AND v_hours < 168 AND v_found = 0 THEN
  v_hours := v_hours / 24;
  v_suff := ' Days Ago';
  RETURN CAST(v_hours AS VARCHAR(30)) || v_suff;
  v_found := 1;
  END IF;
  IF v_hours >= 168 AND v_hours <= 336 AND v_found = 0 THEN
  v_hours := v_hours / 168;
  v_suff := ' Week Ago';
  v_found := 1;
  END IF;
  IF v_hours > 168 AND v_hours < 720 AND v_found = 0 THEN
  v_hours := v_hours / 168;
  v_suff := ' Weeks Ago';
  v_found := 1;
  END IF;
  IF v_hours >= 720 AND v_hours < 1440 AND v_found = 0 THEN
  v_hours := v_hours / 720;
  v_suff := ' Month Ago';
  v_found := 1;
  END IF;
  IF v_hours > 720 AND v_hours < 8760 AND v_found = 0 THEN
  v_hours := v_hours / 720;
  v_suff := ' Months Ago';
  v_found := 1;
  END IF;
  IF v_hours = 8760 AND v_found = 0 THEN
  v_hours := v_hours / 8760;
  v_suff := ' Year Ago';
  v_found := 1;
  END IF;
  IF v_hours > 8760 AND v_found = 0 THEN
  v_hours := v_hours / 8760;
  v_suff := ' Years Ago';
  v_found := 1;
  END IF;
  RETURN CAST(v_hours AS VARCHAR(30)) || v_suff;
  RETURN NULL;
END;
$$;


--
-- Name: getinvoiceno(); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.getinvoiceno() RETURNS character varying
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_invoicecode VARCHAR(10);
  v_currentyear VARCHAR(100);
  v_nextyear VARCHAR(100);
  v_countno VARCHAR(100);
  v_invoice VARCHAR(100);
BEGIN
  SELECT COALESCE(symbol, '') INTO v_invoicecode FROM settings WHERE caption = 'Merchant-Invoice-Prefix' AND active = 1;
  SELECT EXTRACT(YEAR FROM CAST(dbo.FUN_GETCURRENTDATE() AS DATE)) INTO v_currentyear;
  v_nextyear := v_currentyear || 1;
  v_nextyear := RIGHT(CAST(v_nextyear AS TEXT), 2);
  SELECT COUNT(1) INTO v_countno FROM tbl_product_order_master WHERE NOT intstatus IN (7);
  SELECT RIGHT(CAST('000000' || CAST(v_countno AS VARCHAR(6)) AS TEXT), 6) INTO v_countno;
  v_invoice := v_invoicecode || '/' || v_currentyear || '-' || v_nextyear || '/' || v_countno;
  RETURN v_invoice;
  RETURN NULL;
END;
$$;


--
-- Name: getlistenquirydetails(integer, integer, character varying, character varying, character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.getlistenquirydetails(v_startrowindex integer DEFAULT 1, v_maxrows integer DEFAULT 100, v_fromdate character varying DEFAULT ''::character varying, v_todate character varying DEFAULT ''::character varying, v_result character varying DEFAULT ''::character varying) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_query text;
  v_minindex INT;
  v_maxindex INT;
BEGIN
  BEGIN
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp (RowNumber int GENERATED BY DEFAULT AS IDENTITY,
pmid int,
title varchar(100),
ccname varchar(100),
ccemailid varchar(100),
message varchar(200),
maildate varchar(100),
remark varchar(100),
remarkdate varchar(100),
ipaddress varchar(100),
ipdeatils varchar(100)) ON COMMIT DROP;
  v_query := '';
  v_minindex := (v_startrowindex - 1) * v_maxrows + 1;
  v_maxindex := v_startrowindex * v_maxrows;
  v_query := v_query || ('Insert Into #Temp select ROW_NUMBER() OVER(ORDER BY p.maildate desc) as rowNumber,piid,p.pmid , title, ccname , ccemailid, message ,
      (convert(varchar(20),maildate,105)+''''+convert(varchar(20),maildate,108)) as maildate ,remark ,remarkdate,ipaddress,
       ((''City: ''+ipcity+'',State: ''+ipstate+'',Country : ''+ipcountry))as  ipdeatils  from Portal_Inbox p inner join portal_master pm on pm.pmid=p.pmid');
  IF (v_fromdate <> '' AND v_todate <> '') THEN
  v_query := v_query || (' And  Convert(Varchar,EnqDate,110) Between ''' || CAST(TO_CHAR(v_fromdate, 'MM-DD-YYYY') AS VARCHAR(30)) || ''' And ''' || CAST(TO_CHAR(v_todate, 'MM-DD-YYYY') AS VARCHAR(30)) || ''' ');
  END IF;
  IF (v_fromdate <> '') THEN
  v_query := v_query || (' AND CONVERT(Varchar, EnqDate,110) >= CONVERT(Varchar,''' || v_fromdate || ''',110) ');
  END IF;
  IF (v_todate <> '') THEN
  v_query := v_query || (' AND CONVERT(Varchar, EnqDate,110)  <= CONVERT(Varchar,''' || v_todate || ''',110) ');
  END IF;
  EXECUTE v_query;
  RAISE NOTICE '%', (v_query);
  RETURN QUERY SELECT * FROM tmp_temp WHERE rownumber BETWEEN v_startrowindex AND v_maxrows;
  RETURN QUERY SELECT COUNT(1) AS totalrow FROM tmp_temp;
  DROP TABLE IF EXISTS tmp_temp;
  EXCEPTION WHEN OTHERS THEN
  v_result := sqlerrm;
  END;
END;
$$;


--
-- Name: getorderid(character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.getorderid(INOUT v_strresult character varying) RETURNS character varying
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_lower INT;
  v_upper INT;
  v_random INT;
  v_orderid VARCHAR(40);
  v_count INT;
  v_count_temp INT;
  v_loop INT;
  v_randnum INT;
BEGIN
  v_count_temp := 0;
  v_lower := 111111111;
  v_upper := 999999999;
  SELECT ROUND(((v_upper - v_lower - 1) * RANDOM() + v_lower), 0) INTO v_random;
  v_loop := 1;
  WHILE (v_loop = 1) LOOP
  SELECT COUNT(1) INTO v_count FROM tbl_order_master WHERE orderid = CAST(v_random AS VARCHAR(10));
  IF (v_count = 0 AND v_count_temp = 0) THEN
  v_orderid := CAST(v_random AS VARCHAR(10));
  v_loop := 0;
  ELSE
  SELECT ROUND(((v_upper - v_lower - 1) * RANDOM() + v_lower), 0) INTO v_random;
  END IF;
  END LOOP;
  v_strresult := v_orderid;
END;
$$;


--
-- Name: getpackdetails(); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.getpackdetails() RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
BEGIN
  RETURN QUERY SELECT COUNT(tid.kid) AS pack1, SUM(tid.price) AS totalprice FROM tbl_incomedistribution AS tid INNER JOIN member_master AS mm ON tid.regno = mm.regno WHERE tid.kid = 1;
  RETURN QUERY SELECT COUNT(tid.kid) AS pack2, SUM(tid.price) AS totalprice FROM tbl_incomedistribution AS tid INNER JOIN member_master AS mm ON tid.regno = mm.regno WHERE tid.kid = 2;
  RETURN QUERY SELECT COUNT(tid.kid) AS pack3, SUM(tid.price) AS totalprice FROM tbl_incomedistribution AS tid INNER JOIN member_master AS mm ON tid.regno = mm.regno WHERE tid.kid = 3;
  RETURN QUERY SELECT COUNT(tid.kid) AS pack4, SUM(tid.price) AS totalprice FROM tbl_incomedistribution AS tid INNER JOIN member_master AS mm ON tid.regno = mm.regno WHERE tid.kid = 4;
END;
$$;


--
-- Name: getserviceslist(integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.getserviceslist(v_pmid integer DEFAULT 0) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_catid text;
  v_countcatid int;
  v_i int;
BEGIN
  SELECT catid INTO v_catid FROM portal_master WHERE pmid = v_pmid;
  DROP TABLE IF EXISTS tmp_catid;
  CREATE TEMP TABLE tmp_catid ON COMMIT DROP AS SELECT * FROM dbo.SPLITSTRINGBYCOMMA(v_catid);
  SELECT COUNT(*) INTO v_countcatid FROM tmp_catid;
  v_i := 0;
  WHILE (v_i < v_countcatid) LOOP
  IF (v_i = 0) THEN
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp ON COMMIT DROP AS SELECT * FROM tbl_servicesmaster WHERE catid = 0;
  END IF;
  END LOOP;
  RETURN QUERY SELECT * FROM tbl_servicesmaster WHERE catid IN (v_catid);
END;
$$;


--
-- Name: gettotalvatcategory(bigint); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.gettotalvatcategory(v_branchid bigint DEFAULT 0) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
BEGIN
  RETURN QUERY SELECT ROW_NUMBER() OVER (ORDER BY vcid NULLS FIRST) AS rownumber, vcid, vattitle, vatpercvalue, active, statename, branchid FROM tbl_vat_categories WHERE branchid = 0 OR branchid = v_branchid;
END;
$$;


