--
-- Name: ims_usp_createcustomeraddress(bigint, character varying, character varying, character varying, integer, character varying, character varying, character varying, character varying, character varying, character varying, character varying, bigint, character varying, smallint, character varying, character varying, boolean, character varying, character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.ims_usp_createcustomeraddress(v_id bigint DEFAULT 0, v_pincode character varying DEFAULT '201001'::character varying, v_shortaddress character varying DEFAULT 'noida'::character varying, v_landmark character varying DEFAULT 'noida'::character varying, v_countryid integer DEFAULT 0, v_cityname character varying DEFAULT 'delhi'::character varying, v_countryname character varying DEFAULT 'India'::character varying, v_phoneno1 character varying DEFAULT '56345'::character varying, v_phoneno2 character varying DEFAULT '4563456'::character varying, v_email1 character varying DEFAULT 'p@gmail'::character varying, v_remarks character varying DEFAULT '12'::character varying, v_addresstype character varying DEFAULT 'as'::character varying, v_touserid bigint DEFAULT 27, v_tousertype character varying DEFAULT ''::character varying, v_addresstype1 smallint DEFAULT 1, v_cname character varying DEFAULT 'Harsh'::character varying, v_ipaddress character varying DEFAULT NULL::character varying, INOUT v_success boolean DEFAULT false, INOUT v_message character varying DEFAULT '1'::character varying, INOUT v_sqlresult character varying DEFAULT '1'::character varying) RETURNS record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_logid BigInt;
  v_error varchar(1000);
BEGIN
  BEGIN
  v_logid := 0;
  RAISE NOTICE '%', 00;
  SELECT COALESCE(cid, 0), COALESCE(countryname, '') INTO v_countryid, v_countryname FROM country WHERE cid = COALESCE(v_countryid, 0) OR countryname = COALESCE(v_cityname, '');
  RAISE NOTICE '%', 1;
  IF (v_touserid = NULL AND COALESCE(v_tousertype, '') = '') THEN
  v_success := 0;
  v_message := 'Your User Id and Type is null.';
  RETURN;
  END IF;
  RAISE NOTICE '%', 2;
  IF NOT EXISTS(SELECT 1 FROM ims_customeraddress WHERE id = v_id) THEN
  RAISE NOTICE '%', 3;
  PERFORM dbo.ims_usp_insertlog(v_iscatch => 0, v_operationtype => 'Insert', v_touserid => v_touserid, v_tousertype => v_tousertype, v_tablename => 'IMS_CustomerAddress', v_storedprocedure => 'ims_usp_CreateCustomerAddress', v_remarks => 'Insert Address - Line 45', v_ipaddress => v_ipaddress, v_success => v_logid);
  v_logid := LASTVAL();
  INSERT INTO ims_customeraddress (touserid, tousertype, addresstype1, cname, addresstype, pincode, shortaddress, landmark, cityid, stateid, countryid, villagename, cityname, districtname, statename, countryname, phoneno1, phoneno2, email1, email2, faxno1, faxno2, remarks, currencyid, isactive, logid, createddate, addressguid) VALUES (v_touserid, v_tousertype, v_addresstype1, v_cname, v_addresstype, v_pincode, v_shortaddress, v_landmark, 0, 0, v_countryid, '', v_cityname, '', '', v_countryname, v_phoneno1, v_phoneno2, v_email1, '', '', '', v_remarks, 0, 1, v_logid, CURRENT_TIMESTAMP, GEN_RANDOM_UUID());
  v_id := LASTVAL();
  v_sqlresult := v_id;
  v_success := 1;
  v_message := 'Your Address is Created Successfully.^' || CAST(v_id AS VARCHAR);
  ELSE
  PERFORM dbo.ims_usp_insertlog(v_iscatch => 0, v_operationtype => 'Update', v_touserid => v_touserid, v_tousertype => v_tousertype, v_tablename => 'IMS_CustomerAddress', v_storedprocedure => 'ims_usp_CreateAddress', v_remarks => 'Update Address - Line 57', v_ipaddress => v_ipaddress, v_success => v_logid);
  v_logid := LASTVAL();
  UPDATE ims_customeraddress SET addresstype = v_addresstype, pincode = v_pincode, shortaddress = v_shortaddress, landmark = v_landmark, countryid = v_countryid, cname = v_cname, cityname = v_cityname, countryname = v_countryname, phoneno1 = v_phoneno1, phoneno2 = v_phoneno2, email1 = v_email1, remarks = v_remarks, logid = v_logid, addresstype1 = v_addresstype1 WHERE id = v_id;
  v_sqlresult := v_id;
  v_success := 1;
  v_message := 'Your Address is Updated SuccessFully.^' || CAST(v_id AS VARCHAR);
  END IF;
  IF (COALESCE(v_id, 0) <> 0) THEN
  UPDATE ims_customeraddress SET isdefault = 0 WHERE touserid = v_touserid AND tousertype = v_tousertype;
  UPDATE ims_customeraddress SET isdefault = 1 WHERE id = v_id;
  END IF;
  EXCEPTION WHEN OTHERS THEN
  v_error := 'Error Message : ' || sqlerrm || ', Line ' || CAST(0 AS VARCHAR(5)) || ', ErrorSeverity :' || 0 || ', ErrorState :' || 0;
  PERFORM dbo.ims_usp_insertlog(v_iscatch => 1, v_operationtype => 'Insert/Update', v_touserid => v_touserid, v_tousertype => v_tousertype, v_tablename => 'IMS_CustomerAddress', v_storedprocedure => 'ims_usp_CreateAddress', v_remarks => v_error, v_ipaddress => v_ipaddress, v_success => v_success, v_message => v_message, v_sqlresult => v_logid);
  v_sqlresult := v_logid;
  v_success := 0;
  v_message := 'Your Address Creation is Failed.';
  END;
END;
$$;


--
-- Name: ims_usp_createproduct(bigint, bigint, bigint, integer, integer, integer, integer, character varying, character varying, character varying, character varying, character varying, character varying, text, boolean, integer, integer, character varying, numeric, numeric, integer, character varying, character varying, character varying, text, text, integer, numeric, numeric, numeric, integer, character varying, integer, integer, numeric, boolean, numeric, numeric, numeric, numeric, integer, character varying, character varying, character varying, numeric, integer, character varying, integer, integer, character varying, numeric, character varying, character varying, character varying, integer, text, character varying, numeric, numeric, numeric, numeric, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.ims_usp_createproduct(v_sprid bigint DEFAULT 0, v_mprid bigint DEFAULT 1, v_branchid bigint DEFAULT 0, v_companyid integer DEFAULT 0, v_catid integer DEFAULT 1, v_subcatid integer DEFAULT 0, v_brand integer DEFAULT 1, v_productcode character varying DEFAULT 'SM-Seller-102'::character varying, v_subprcode character varying DEFAULT ''::character varying, v_prodtitle character varying DEFAULT 'Samsung C4 (Black)'::character varying, v_activefrom character varying DEFAULT ''::character varying, v_activeto character varying DEFAULT ''::character varying, v_shortdesc character varying DEFAULT '(200 Character)Short Description'::character varying, v_fulldesc text DEFAULT '(2000 Character)Full Description'::text, v_isallowcoupon boolean DEFAULT false, v_minorderqty integer DEFAULT 0, v_maxorderqty integer DEFAULT 0, v_paymode character varying DEFAULT ''::character varying, v_sellmrp numeric DEFAULT 10, v_discountper numeric DEFAULT 10, v_qty integer DEFAULT 10, v_produnit character varying DEFAULT '10'::character varying, v_color character varying DEFAULT 'Yellow'::character varying, v_size character varying DEFAULT 'V'::character varying, v_prodimages text DEFAULT 'img1.jpg^img1.jpg^img1.jpg'::text, v_allattributes text DEFAULT 'Key1~Key2~Key3'::text, v_vcid integer DEFAULT 1, v_vatp numeric DEFAULT 0, v_directamt numeric DEFAULT 0, v_dap numeric DEFAULT 100, v_replacementday integer DEFAULT 0, v_keyfeatures character varying DEFAULT ''::character varying, v_stockin integer DEFAULT 10, v_procurementsla integer DEFAULT 0, v_shippingcharges numeric DEFAULT 10.2, v_cashondelivery boolean DEFAULT true, v_pkg_weight_kg numeric DEFAULT NULL::numeric, v_pkg_length_cms numeric DEFAULT NULL::numeric, v_pkg_breadth_cms numeric DEFAULT NULL::numeric, v_pkg_height_cms numeric DEFAULT NULL::numeric, v_warrentyinfocare integer DEFAULT 0, v_dealsids character varying DEFAULT ''::character varying, v_groupid character varying DEFAULT ''::character varying, INOUT v_strresult character varying DEFAULT ''::character varying, v_ywillrece numeric DEFAULT 0, v_ismerchantstatus integer DEFAULT 0, v_productentry character varying DEFAULT ''::character varying, v_fullfillment integer DEFAULT 0, v_procurementtype integer DEFAULT 0, v_hsn character varying DEFAULT ''::character varying, v_luxurycess numeric DEFAULT 0, v_manufacturingdetail character varying DEFAULT ''::character varying, v_importerdetail character varying DEFAULT ''::character varying, v_packerdetail character varying DEFAULT ''::character varying, v_countryorigin integer DEFAULT 0, v_specification text DEFAULT ''::text, v_productskucode character varying DEFAULT ''::character varying, v_bv numeric DEFAULT 0, v_pv numeric DEFAULT 0, v_cashback numeric DEFAULT 0, v_activationpv numeric DEFAULT 0, v_branchtype integer DEFAULT 1) RETURNS character varying
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_logid BIGINT;
  v_suprcode VARCHAR(500);
  v_subprcodetemp VARCHAR(500);
  v_mpridtemp BIGINT;
  v_qccount INT;
  v_qccounttemp INT;
  v_maincatid INT;
  v_cid INT;
  v_pricecurrency VARCHAR(50);
  v_maxmprid BIGINT;
  v_count1 INT;
  v_count2 INT;
  v_value VARCHAR(200);
  v_title VARCHAR(100);
  v_itemval VARCHAR(100);
  v_paybleamount Decimal(18,2);
  v_commissionamount Decimal(18,0);
  v_lastidentity BIGINT;
  v_bvhalfadmincharge Decimal(14,8);
  v_bvpercentadmincharge Decimal(14,8);
  v_bvpercentamountadmincharge Decimal(14,8);
  v_delieverycharge DECIMAL(14,8);
  v_handlingcharge DECIMAL(14,8);
  v_fixedfee DECIMAL(14,8);
  v_admincharge DECIMAL(14,8);
  v_gstpercentage DECIMAL(18,2);
  v_lower INT;
  v_upper INT;
  v_random INT;
  v_awk INT;
BEGIN
  -- BEGIN TRAN (removed)
  v_strresult := 'ok';
  v_logid := 0;
  v_qccount := 0;
  v_qccounttemp := 0;
  v_lastidentity := 0;
  v_bvhalfadmincharge := 0;
  v_bvpercentadmincharge := 0;
  v_bvpercentamountadmincharge := 0;
  v_delieverycharge := 0;
  v_handlingcharge := 0;
  v_fixedfee := 0;
  v_admincharge := 0;
  v_gstpercentage := 0;
  IF (v_activefrom = '') THEN
  v_activefrom := NULL;
  END IF;
  IF (v_activeto = '') THEN
  v_activeto := NULL;
  END IF;
  SELECT maincatid INTO v_maincatid FROM tbl_category WHERE catid = v_catid;
  v_cid := 1;
  SELECT CASE WHEN COALESCE(v_productcode, '') = '' THEN (SELECT CAST((COALESCE(MAX(mprid), 0) + 1) AS VARCHAR(100)) FROM ims_masterproduct) ELSE v_productcode END INTO v_productcode;
  SELECT CASE WHEN COALESCE(v_subprcode, '') = '' THEN (SELECT CAST((COALESCE(MAX(sprid), 0) + 1) AS VARCHAR(100)) FROM ims_subproduct) ELSE v_subprcode END INTO v_subprcode;
  SELECT bvper, admincharge INTO v_bvhalfadmincharge, v_bvpercentadmincharge FROM tbl_sub_category WHERE subcatid = v_subcatid;
  v_bvpercentamountadmincharge := v_dap * v_bvpercentadmincharge / 100;
  v_lower := 11111;
  v_upper := 99999;
  SELECT ROUND(((v_upper - v_lower - 1) * RANDOM() + v_lower), 0) INTO v_random;
  SELECT delieverycharge, handlingcharge, fixedfee, admincharge INTO v_delieverycharge, v_handlingcharge, v_fixedfee, v_admincharge FROM tbl_sub_category WHERE subcatid = v_subcatid;
  IF NOT EXISTS(SELECT 1 FROM ims_subproduct WHERE sprid = v_sprid) THEN
  IF NOT EXISTS(SELECT 1 FROM ims_subproduct WHERE mprid = v_mprid) THEN
  RAISE NOTICE '%', 'AAA';
  INSERT INTO ims_masterproduct (productcode, maincategoryid, subcategoryid, brandid, producttitle, shotdescription, fulldescription, keyfeatures, minorderqty, maxorderqty, paymode, vatcategoryid, companyid, branchid, createddate, modifydate, catid) VALUES (v_productcode, v_maincatid, v_subcatid, v_brand, v_prodtitle, v_shortdesc, v_fulldesc, v_keyfeatures, v_minorderqty, v_maxorderqty, v_paymode, v_vcid, v_companyid, v_branchid, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, v_catid);
  v_maxmprid := LASTVAL();
  ELSE
  v_maxmprid := v_mprid;
  END IF;
  RAISE NOTICE '%', 'BBB';
  INSERT INTO ims_subproduct (subprcode, mprid, qty, unit, color, size, productimages, shippingcharges, discountpercentage, vatcategoryid, actualprice, sellmrp, dap, directamount, activefrom, activeto, isallowcoupon, isactive, isverified, createddate, modifydate, replacementday, procurementsla, cashondelivery, weight_kg, length_cms, breadth_cms, height_cms, stockin, stockout, stocknet, isoutofstock, warrentyinfocare, dealsids, groupid, ywillrece, ismerchantstatus, productentry, puidno, fullfilmentby, procurementtype, hsn, luxurycess, manufacturerdetails, importerdetails, packerdetails, countryorigin, delieverycharge, handlingcharge, fixedfee, admincharge, qc_count, specification, prskucode, bv, pv, cashback_per, activationpv_per) VALUES (v_subprcode, v_maxmprid, v_qty, v_produnit, v_color, v_size, v_prodimages, v_shippingcharges, v_discountper, v_vcid, 0, v_sellmrp, v_dap, v_directamt, v_activefrom, v_activeto, v_isallowcoupon, 1, 0, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, v_replacementday, v_procurementsla, v_cashondelivery, v_pkg_weight_kg, v_pkg_length_cms, v_pkg_breadth_cms, v_pkg_height_cms, v_stockin, 0, v_stockin, (CASE WHEN v_stockin > 0 THEN 0 ELSE 1 END), v_warrentyinfocare, v_dealsids, v_groupid, v_ywillrece, v_ismerchantstatus, v_productentry, CAST(v_random AS VARCHAR(10)), v_fullfillment, v_procurementtype, v_hsn, v_luxurycess, v_manufacturingdetail, v_importerdetail, v_packerdetail, v_countryorigin, v_delieverycharge, v_handlingcharge, v_fixedfee, v_admincharge, 1, v_specification, v_productskucode, v_bv, v_pv, v_cashback, v_activationpv);
  v_sprid := LASTVAL();
  SELECT subprcode INTO v_subprcode FROM ims_subproduct WHERE sprid = v_sprid;
  SELECT IDENT_CURRENT('IMS_SUBPRODUCT') INTO v_lastidentity;
  v_strresult := 'ok^Success^Your Product Added Successfully.';
  ELSE
  SELECT mprid INTO v_mprid FROM ims_subproduct WHERE sprid = v_sprid;
  SELECT subprcode INTO v_suprcode FROM ims_subproduct WHERE mprid = v_mprid;
  SELECT subprcode INTO v_subprcodetemp FROM ims_subproduct WHERE subprcode = v_suprcode;
  SELECT mprid INTO v_mpridtemp FROM ims_subproduct_temp WHERE subprcode = v_subprcodetemp;
  SELECT qc_count INTO v_qccounttemp FROM ims_subproduct_temp WHERE mprid = v_mpridtemp;
  SELECT qc_count INTO v_qccount FROM ims_subproduct WHERE mprid = v_mprid;
  UPDATE ims_subproduct_temp SET ismerchantstatus = 4, qc_count = v_qccounttemp + 1 WHERE mprid = v_mpridtemp;
  UPDATE ims_masterproduct SET productcode = v_productcode, producttitle = v_prodtitle, shotdescription = v_shortdesc, fulldescription = v_fulldesc, keyfeatures = v_keyfeatures, minorderqty = v_minorderqty, maxorderqty = v_maxorderqty, paymode = v_paymode, vatcategoryid = v_vcid, modifydate = CURRENT_TIMESTAMP, catid = v_catid WHERE mprid = v_mprid;
  SELECT (CASE WHEN COALESCE(v_prodimages, '') = '' THEN productimages ELSE v_prodimages END) INTO v_prodimages FROM ims_subproduct WHERE sprid = v_sprid;
  UPDATE ims_subproduct SET qty = v_qty, unit = v_produnit, color = v_color, size = v_size, productimages = v_prodimages, discountpercentage = v_discountper, vatcategoryid = v_vcid, sellmrp = v_sellmrp, dap = v_dap, activefrom = v_activefrom, activeto = v_activeto, modifydate = CURRENT_TIMESTAMP, replacementday = v_replacementday, procurementsla = v_procurementsla, cashondelivery = v_cashondelivery, weight_kg = v_pkg_weight_kg, length_cms = v_pkg_length_cms, breadth_cms = v_pkg_breadth_cms, height_cms = v_pkg_height_cms, shippingcharges = v_shippingcharges, ywillrece = v_ywillrece, stockin = v_stockin, bv = v_bv, pv = v_pv, cashback_per = v_cashback, activationpv_per = v_activationpv, stockout = 0, stocknet = v_stockin, isoutofstock = (CASE WHEN v_stockin > 0 THEN 0 ELSE 1 END), warrentyinfocare = v_warrentyinfocare, isverified = 0, ismerchantstatus = 4, qc_count = v_qccount + 1, prskucode = v_productskucode WHERE sprid = v_sprid;
  SELECT v_sprid INTO v_lastidentity;
