  SELECT awct_id INTO v_awk FROM tbl_attributes_with_category WHERE att_name = v_title AND sub_cat_id = 0 AND (cat_id = COALESCE(v_catid, 0) OR main_cat_id = COALESCE(v_maincatid, 0));
  SELECT awct_id INTO v_awk FROM tbl_attributes_with_category WHERE att_name = v_title AND sub_cat_id = 0 AND (cat_id = COALESCE(v_catid, 0) AND main_cat_id = COALESCE(v_maincatid, 0));
  ELSE
  IF (COALESCE(v_maincatid, 0) <> 0) THEN
  SELECT awct_id INTO v_awk FROM tbl_attributes_with_category WHERE att_name = v_title AND sub_cat_id = 0 AND cat_id = 0 OR main_cat_id = COALESCE(v_maincatid, 0);
  END IF;
  END IF;
  END IF;
  INSERT INTO ims_masterproductattribute (sprid, title, value, showongrid, position, isactive, catid, awcid, subcatid) VALUES (v_lastidentity, v_title, v_itemval, 1, 1, 1, v_catid, v_awk, v_subcatid);
