y character varying DEFAULT ''::character varying, v_fullfillment integer DEFAULT 0, v_procurementtype integer DEFAULT 0, v_hsn character varying DEFAULT ''::character varying, v_luxurycess numeric DEFAULT 0, v_manufacturingdetail character varying DEFAULT ''::character varying, v_importerdetail character varying DEFAULT ''::character varying, v_packerdetail character varying DEFAULT ''::character varying, v_countryorigin integer DEFAULT 0, v_specification text DEFAULT ''::text, INOUT v_productskucode character varying DEFAULT ''::character varying, v_bv numeric DEFAULT 0, v_pv numeric DEFAULT 0, v_cashback numeric DEFAULT 0, v_activationpv numeric DEFAULT 0) RETURNS record
