  v_sprid := LASTVAL();
  SELECT subprcode INTO v_subprcode FROM ims_subproduct_temp WHERE sprid = v_sprid;
  SELECT IDENT_CURRENT('IMS_SubProduct_Temp') INTO v_lastidentity;
  IF (v_ismerchantstatus = 0) THEN
  v_strresult := 'ok^Success^Save to Draft Successfully.';
  ELSE
  v_strresult := 'ok^Success^Send to QC Successfully.';
  END IF;
  ELSE
