  SELECT (CASE WHEN COALESCE(v_prodimages, '') = '' THEN productimages ELSE v_prodimages END) INTO v_prodimages FROM ims_subproduct_temp WHERE sprid = v_sprid;
  UPDATE ims_subproduct_temp SET qty = v_qty, unit = v_produnit, color = v_color, size = v_size, productimages = v_prodimages, discountpercentage = v_discountper, vatcategoryid = v_vcid, sellmrp = v_sellmrp, dap = (((v_sellmrp - ((v_sellmrp * v_discountper) / 100)) - (((v_sellmrp - ((v_sellmrp * v_discountper) / 100))) * v_gstpercentage) / (100 + v_gstpercentage))), activefrom = v_activefrom, activeto = v_activeto, modifydate = CURRENT_TIMESTAMP, replacementday = v_replacementday, procurementsla = v_procurementsla, cashondelivery = v_cashondelivery, weight_kg = v_pkg_weight_kg, length_cms = v_pkg_length_cms, breadth_cms = v_pkg_breadth_cms, height_cms = v_pkg_height_cms, shippingcharges = v_shippingcharges, ywillrece = v_ywillrece, stockin = v_stockin, stockout = 0, stocknet = v_stockin, isoutofstock = (CASE WHEN v_stockin > 0 THEN 0 ELSE 1 END), warrentyinfocare = v_warrentyinfocare, isverified = 2, prskucode = v_productskucode, bv = v_bv, pv = v_pv, cashback_per = v_cashback, activationpv_per = v_activationpv WHERE sprid = v_sprid;
  DELETE FROM ims_masterproductattribute_temp WHERE sprid = v_sprid;
