  SELECT awct_id INTO v_awk FROM tbl_attributes_with_category WHERE att_name = v_title AND sub_cat_id = 0 AND (cat_id = COALESCE(v_catid, 0) OR main_cat_id = COALESCE(v_maincatid, 0));
  SELECT awct_id INTO v_awk FROM tbl_attributes_with_category WHERE att_name = v_title AND sub_cat_id = 0 AND (cat_id = COALESCE(v_catid, 0) AND main_cat_id = COALESCE(v_maincatid, 0));
