ying, INOUT v_strresult character varying DEFAULT ''::character varying, v_ywillrece numeric DEFAULT 0, v_ismerchantstatus integer DEFAULT 0, v_productentry character varying DEFAULT ''::character varying, v_random character varying DEFAULT ''::character varying, v_fullfillment integer DEFAULT 0, v_procurementtype integer DEFAULT 0, v_hsn character varying DEFAULT NULL::character varying, v_luxurycess numeric DEFAULT NULL::numeric, v_manufacturingdetail character varying DEFAULT NULL::character varying, v_importerdetail character varying DEFAULT NULL::character varying, v_packerdetail character varying DEFAULT NULL::character varying, v_countryorigin integer DEFAULT NULL::integer, v_specification text DEFAULT NULL::text, v_prskucode character varying DEFAULT NULL::character varying, v_bv numeric DEFAULT 0, v_pv numeric DEFAULT 0, v_cashback_per numeric DEFAULT 0, v_activationpv numeric DEFAULT 0) RETURNS character varying
