  END IF;
  RAISE NOTICE '%', 'BBB';
  INSERT INTO ims_subproduct (subprcode, mprid, qty, unit, color, size, productimages, shippingcharges, discountpercentage, vatcategoryid, actualprice, sellmrp, dap, directamount, activefrom, activeto, isallowcoupon, isactive, isverified, createddate, modifydate, replacementday, procurementsla, cashondelivery, weight_kg, length_cms, breadth_cms, height_cms, stockin, stockout, stocknet, isoutofstock, warrentyinfocare, dealsids, groupid, ywillrece, bv, ismerchantstatus, productentry, puidno, fullfilmentby, procurementtype, hsn, luxurycess, manufacturerdetails, importerdetails, packerdetails, countryorigin, delieverycharge, handlingcharge, fixedfee, admincharge, specification, prskucode, pv, cashback_per, activationpv_per) VALUES (v_subprcode, v_maxmprid, v_qty, v_produnit, v_color, v_size, v_prodimages, v_shippingcharges, v_discountper, v_vcid, 0, v_sellmrp, v_dap, v_directamt, v_activefrom, v_activeto, v_isallowcoupon, 1, 0, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, v_replacementday, v_procurementsla, v_cashondelivery, v_pkg_weight_kg, v_pkg_length_cms, v_pkg_breadth_cms, v_pkg_height_cms, v_stockin, 0, v_stockin, (CASE WHEN v_stockin > 0 THEN 0 ELSE 1 END), v_warrentyinfocare, v_dealsids, v_groupid, v_ywillrece, v_bv, v_ismerchantstatus, v_productentry, v_random, v_fullfillment, v_procurementtype, v_hsn, v_luxurycess, v_manufacturingdetail, v_importerdetail, v_packerdetail, v_countryorigin, v_delieverycharge, v_handlingcharge, v_fixedfee, v_admincharge, v_specification, v_prskucode, v_pv, v_cashback_per, v_activationpv);
  v_sprid := LASTVAL();
  SELECT subprcode INTO v_subprcode FROM ims_subproduct WHERE sprid = v_sprid;
  SELECT IDENT_CURRENT('IMS_SubProduct') INTO v_lastidentity;
  v_strresult := 'Your Product Added Ready List Successfully.';
  ELSE
  RAISE NOTICE '%', 'CCC';
  SELECT mprid INTO v_mprid FROM ims_subproduct WHERE sprid = v_sprid;
  UPDATE ims_masterproduct SET productcode = v_productcode, producttitle = v_prodtitle, shotdescription = v_shortdesc, fulldescription = v_fulldesc, keyfeatures = v_keyfeatures, minorderqty = v_minorderqty, maxorderqty = v_maxorderqty, paymode = v_paymode, vatcategoryid = v_vcid, modifydate = CURRENT_TIMESTAMP, catid = v_catid WHERE mprid = v_mprid;
  RAISE NOTICE '%', 'DDD';
  SELECT (CASE WHEN COALESCE(v_prodimages, '') = '' THEN productimages ELSE v_prodimages END) INTO v_prodimages FROM ims_subproduct WHERE sprid = v_sprid;
  UPDATE ims_subproduct SET qty = v_qty, unit = v_produnit, color = v_color, size = v_size, productimages = v_prodimages, discountpercentage = v_discountper, vatcategoryid = v_vcid, sellmrp = v_sellmrp, dap = v_dap, activefrom = v_activefrom, activeto = v_activeto, modifydate = CURRENT_TIMESTAMP, replacementday = v_replacementday, procurementsla = v_procurementsla, cashondelivery = v_cashondelivery, weight_kg = v_pkg_weight_kg, length_cms = v_pkg_length_cms, breadth_cms = v_pkg_breadth_cms, height_cms = v_pkg_height_cms, shippingcharges = v_shippingcharges, ywillrece = v_ywillrece, stockin = v_stockin, pv = v_pv, bv = v_bv, cashback_per = v_cashback_per, activationpv_per = v_activationpv, stockout = 0, stocknet = v_stockin, isoutofstock = (CASE WHEN v_stockin > 0 THEN 0 ELSE 1 END), warrentyinfocare = v_warrentyinfocare, isverified = 2 WHERE sprid = v_sprid;
  RAISE NOTICE '%', 'EEE';
  DELETE FROM ims_masterproductattribute WHERE sprid = v_sprid;
  SELECT v_sprid INTO v_lastidentity;
  v_strresult := 'Your Product Added Ready List Successfully.';
  END IF;
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp (rowno int GENERATED BY DEFAULT AS IDENTITY,  
  Value varchar(200)) ON COMMIT DROP;
  INSERT INTO tmp_temp SELECT value FROM dbo.SPLITSTRINGBYCUSTOMSYMBOL1(v_allattributes, '^') WHERE COALESCE(value, '') <> '';
  v_count1 := 1;
  SELECT COUNT(1) INTO v_count2 FROM tmp_temp;
  WHILE (v_count1 <= v_count2) LOOP
  RAISE NOTICE '%', 'FFF';
  SELECT value INTO v_value FROM tmp_temp WHERE rowno = v_count1;
  v_title := SUBSTRING(v_value FROM 1 FOR POSITION('~' IN v_value) - 1);
  v_itemval := SUBSTRING(v_value FROM POSITION('~' IN v_value) + 1 FOR LENGTH(CAST(v_value AS TEXT)));
  IF (v_value <> 'No') THEN
  v_awk := 0;
  END IF;
  SELECT maincatid INTO v_maincatid FROM dbo.tbl_category WHERE catid = v_catid;
  SELECT maincatid, catid INTO v_maincatid, v_catid FROM dbo.tbl_sub_category WHERE subcatid = v_subcatid;
  IF (COALESCE(v_subcatid, 0) <> 0) THEN
  RAISE NOTICE '%', 'subcat';
  SELECT awct_id INTO v_awk FROM tbl_attributes_with_category WHERE att_name = v_title AND (sub_cat_id = COALESCE(v_subcatid, 0) OR cat_id = COALESCE(v_catid, 0) OR main_cat_id = COALESCE(v_maincatid, 0));
  ELSE
  IF (COALESCE(v_catid, 0) <> 0) THEN
  RAISE NOTICE '%', 'cat';
  SELECT awct_id INTO v_awk FROM tbl_attributes_with_category WHERE att_name = v_title AND sub_cat_id = 0 AND (cat_id = COALESCE(v_catid, 0) OR main_cat_id = COALESCE(v_maincatid, 0));
  SELECT awct_id INTO v_awk FROM tbl_attributes_with_category WHERE att_name = v_title AND sub_cat_id = 0 AND (cat_id = COALESCE(v_catid, 0) AND main_cat_id = COALESCE(v_maincatid, 0));
  ELSE
  IF (COALESCE(v_maincatid, 0) <> 0) THEN
  RAISE NOTICE '%', 'main';
  SELECT awct_id INTO v_awk FROM tbl_attributes_with_category WHERE att_name = v_title AND sub_cat_id = 0 AND cat_id = 0 OR main_cat_id = COALESCE(v_maincatid, 0);
  END IF;
  END IF;
  END IF;
  INSERT INTO ims_masterproductattribute (sprid, title, value, showongrid, position, isactive, catid, awcid, subcatid) VALUES (v_lastidentity, v_title, v_itemval, 1, 1, 1, v_catid, v_awk, v_subcatid);
  v_count1 := v_count1 + 1;
  END LOOP;
  DROP TABLE IF EXISTS tmp_temp;
  IF (0 <> 0) THEN
  RAISE NOTICE '%', 'ERROR ims_usp_CreateProduct_Temp_MovetoReady';
  -- ROLLBACK (removed)
  v_strresult := 'error^error^Something Went Wrong.';
  RETURN;
  END IF;
  -- COMMIT (removed)
END;
$$;


