-- Name: ims_usp_getattributesbycolorsizemprid(bigint); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.ims_usp_getattributesbycolorsizemprid(v_mprid bigint DEFAULT 0) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_producttitle text;
  v_sprid text;
BEGIN
  -- SET option (removed)
  IF (v_mprid > 0) THEN
  SELECT COALESCE(producttitle, '') INTO v_producttitle FROM ims_masterproduct WHERE mprid = v_mprid;
  SELECT COALESCE(v_sprid || ', ', '') || CAST(sprid AS VARCHAR) INTO v_sprid FROM ims_subproduct WHERE mprid IN (SELECT mprid FROM ims_masterproduct WHERE producttitle = v_producttitle) AND isactive = 1 AND isverified = 1;
  RETURN QUERY SELECT * FROM (SELECT sprid, title, value, ROW_NUMBER() OVER (PARTITION BY value ORDER BY sprid DESC NULLS LAST) AS rn FROM ims_masterproductattribute WHERE sprid IN (SELECT value FROM SPLITSTRINGBYCOMMA(v_sprid))) AS a WHERE rn = 1;
  END IF;
  -- SET option (removed)
END;
$$;


