--
-- Name: ims_usp_getclientsalereport(character varying, character varying, bigint); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.ims_usp_getclientsalereport(v_monthyear character varying DEFAULT ''::character varying, v_searchtype character varying DEFAULT ''::character varying, v_branchid bigint DEFAULT 1) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_query text;
BEGIN
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp (BRANCHID BIGINT,
BRNAME VARCHAR(200),
ORDERMONTH INT,
MONTHANDYEAR VARCHAR(50),
ORDER_COST numeric(19,4),
ORDER_VAT numeric(19,4),
ORDER_NETAMT numeric(19,4) ,
PRODUCT_NAME VARCHAR(200),
SUBPRCODE VARCHAR(50)) ON COMMIT DROP;
  v_branchid := CASE WHEN COALESCE(v_branchid, 0) = 0 THEN 1 ELSE v_branchid END;
  v_query := 'INSERT INTO #TEMP SELECT BM.PLID,BM.FNAME+'' ''+BM.MNAME+'' ''+BM.LNAME+'' (MRID: ''+ CONVERT(VARCHAR(50),CSO.BRANCHID)+'')'' AS BRNAME,CONVERT(CHAR(2), CSP.PROCESSDATE , 110) MONTH, 
             CONVERT(CHAR(3), CSP.PROCESSDATE, 100) + CONVERT(CHAR(4), CSP.PROCESSDATE, 120) AS MONTHANDYEAR,
             CSP.TOTAL_COST,CSP.TOTAL_VAT,ORDER_NETAMT,CSP.PRODUCT_NAME,CSP.SUBPRCODE 
			 FROM TBL_PRODUCT_ORDER_MASTER CSP 
INNER JOIN  TBL_ORDER_MASTER CSO  ON CSO.ORDERID=CSP.ORDERID 
INNER JOIN MEMBER_MASTER BM ON BM.PLID=CSO.BRANCHID WHERE CSO.ORID>0 
			 AND (' || CAST(v_branchid AS VARCHAR(50)) || ' = 1 OR CSO.BRANCHID = ' || CAST(v_branchid AS VARCHAR(50)) || ')';
  IF (v_monthyear <> '' AND v_monthyear <> '- Select Month Year -') THEN
  v_query := v_query || ' AND CONVERT(CHAR(4), CSP.PROCESSDATE, 100) + CONVERT(CHAR(4), CSP.PROCESSDATE, 120)=''' || v_monthyear || '''';
  END IF;
  EXECUTE v_query;
  IF (v_searchtype = 'Branchwise') THEN
  RETURN QUERY SELECT branchid, brname, monthandyear, SUM(order_cost) AS order_cost, SUM(order_vat) AS order_vat, SUM(order_netamt) AS order_netamt, ordermonth FROM tmp_temp GROUP BY monthandyear, branchid, brname, ordermonth ORDER BY monthandyear NULLS FIRST;
  ELSE
  IF (v_searchtype = 'Productwise') THEN
  RETURN QUERY SELECT product_name, subprcode, monthandyear, SUM(order_cost) AS order_cost, SUM(order_vat) AS order_vat, SUM(order_netamt) AS order_netamt, ordermonth FROM tmp_temp GROUP BY product_name, monthandyear, ordermonth, subprcode;
  ELSE
  RETURN QUERY SELECT monthandyear, SUM(order_cost) AS order_cost, SUM(order_vat) AS order_vat, SUM(order_netamt) AS order_netamt, ordermonth FROM tmp_temp GROUP BY monthandyear, ordermonth ORDER BY monthandyear NULLS FIRST;
  END IF;
  END IF;
  DROP TABLE IF EXISTS tmp_temp;
  -- SET option (removed)
END;
$$;


--
-- Name: ims_usp_getdistinctattributesbymprid_mobile(bigint, bigint); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.ims_usp_getdistinctattributesbymprid_mobile(v_mprid bigint DEFAULT 456, v_mode bigint DEFAULT 2) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_subprcode varchar(250);
  v_maxmprid varchar(250);
  v_dynamicurl varchar(100);
  v_merchantproductlargeimage varchar(250);
BEGIN
  v_subprcode := '';
  v_maxmprid := '';
  v_dynamicurl := '';
  v_merchantproductlargeimage := '';
  SELECT merchantimagepath, merchantproductlargeimage INTO v_dynamicurl, v_merchantproductlargeimage FROM tbl_company;
  SELECT subprcode INTO v_subprcode FROM ims_subproduct WHERE mprid = v_mprid;
  IF (v_mode = 0) THEN
  RETURN QUERY SELECT title, value FROM ims_masterproductattribute AS im WHERE sprid IN (SELECT sprid FROM ims_subproduct WHERE mprid IN (SELECT mprid FROM ims_masterproduct WHERE producttitle IN (SELECT producttitle FROM ims_masterproduct WHERE mprid = v_mprid))) AND im.title = 'Size' GROUP BY title, value;
  ELSE
  IF (v_mode = 2) THEN
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp ON COMMIT DROP AS SELECT (SELECT COALESCE(colorcode, '') FROM tbl_hexacolrcode WHERE colorname = REPLACE(im.value, ' ', '')) AS colorcode, title, value, v_dynamicurl AS baseurl, (SELECT ims.productimages FROM ims_subproduct AS ims WHERE ims.sprid = im.sprid) AS imagename FROM ims_masterproductattribute AS im WHERE sprid IN (SELECT sprid FROM ims_subproduct WHERE mprid IN (SELECT mprid FROM ims_masterproduct WHERE producttitle IN (SELECT producttitle FROM ims_masterproduct WHERE mprid = v_mprid))) AND im.title = 'Color' GROUP BY title, value, sprid;
  RETURN QUERY SELECT colorcode, title, value FROM tmp_temp GROUP BY colorcode, title, value, baseurl, imagename;
  DROP TABLE IF EXISTS tmp_temp;
  ELSE
  DROP TABLE IF EXISTS tmp_temp_sub1;
  CREATE TEMP TABLE tmp_temp_sub1 ON COMMIT DROP AS SELECT title, value, sprid FROM ims_masterproductattribute WHERE sprid IN (v_mprid);
  RETURN QUERY SELECT * FROM tmp_temp_sub1;
  DROP TABLE IF EXISTS tmp_temp_sub1;
  END IF;
  END IF;
END;
$$;


