  IF (NOT dbo.REMOVESPACESANDSPECIALCHARS(v_title) IN ('ad-type', 'seller-type', 'price', 'condition')) THEN
  RAISE NOTICE '%', 1;
  IF EXISTS(SELECT 1 FROM ims_masterproductattribute WHERE dbo.REMOVESPACESANDSPECIALCHARS(title) = dbo.REMOVESPACESANDSPECIALCHARS(v_title) AND dbo.REMOVESPACESANDSPECIALCHARS(v_value) <> '') THEN
  INSERT INTO tmp_tempallpmid (mpaid, cnt) VALUES (0, v_cnt1);
  IF (v_countexists = 1) THEN
  RAISE NOTICE '%', 2;
  INSERT INTO tmp_tempallpmid (mpaid, cnt) SELECT m.mpaid, v_cnt1 FROM ims_masterproductattribute AS m JOIN (SELECT value AS pval FROM dbo.SPLITSTRINGBYCUSTOMSYMBOL1(v_value, '_')) AS p ON (',' || COALESCE(dbo.REMOVESPACESANDSPECIALCHARS(m.value), '') || ',' LIKE '%,' || COALESCE(dbo.REMOVESPACESANDSPECIALCHARS(p.pval), '') || ',%') WHERE dbo.REMOVESPACESANDSPECIALCHARS(title) = dbo.REMOVESPACESANDSPECIALCHARS(v_title);
  ELSE
  RAISE NOTICE '%', 3;
  INSERT INTO tmp_tempallpmid (mpaid, cnt) SELECT m.mpaid, v_cnt1 FROM ims_masterproductattribute AS m JOIN (SELECT value AS pval FROM dbo.SPLITSTRINGBYCUSTOMSYMBOL1(v_value, '_')) AS p ON (',' || COALESCE(dbo.REMOVESPACESANDSPECIALCHARS(m.value), '') || ',' LIKE '%,' || COALESCE(dbo.REMOVESPACESANDSPECIALCHARS(p.pval), '') || ',%') WHERE dbo.REMOVESPACESANDSPECIALCHARS(title) = dbo.REMOVESPACESANDSPECIALCHARS(v_title) AND (mpaid IN (SELECT mpaid FROM tmp_tempallpmid));
  END IF;
  RAISE NOTICE '%', 4;
  DELETE FROM tmp_tempallpmid WHERE cnt <> v_cnt1;
  v_countexists := v_countexists + 1;
  END IF;
  END IF;
  v_cnt1 := v_cnt1 + 1;
  RAISE NOTICE '%', 5;
  END LOOP;
  DROP TABLE IF EXISTS tmp_tempsplitval;
  RAISE NOTICE '%', 6;
  SELECT COALESCE(v_returnmpid || ',', '') || CAST(mpaid AS VARCHAR(50)) INTO v_returnmpid FROM tmp_tempallpmid;
  RAISE NOTICE '%', 7;
  IF (COALESCE(v_returnmpid, '') <> '') THEN
  RAISE NOTICE '%', 8;
  v_returnmpid := RIGHT(CAST(v_returnmpid AS TEXT), LENGTH(CAST(v_returnmpid AS TEXT)) - 1);
  END IF;
  v_returnmpid := CASE WHEN COALESCE(v_returnmpid, '0') = '0' THEN NULL ELSE v_returnmpid END;
  IF (v_returnmpid = '0' OR v_returnmpid = '') THEN
  v_returnmpid := NULL;
  END IF;
  RAISE NOTICE '%', v_returnmpid;
  DROP TABLE IF EXISTS tmp_tempallpmid;
  RAISE NOTICE '%', 'STOP IMS_USP_GETMPIDFROMQUERYSTRING';
END;
$$;


--
-- Name: ims_usp_getorderlist(integer, integer, bigint, character varying, character varying, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.ims_usp_getorderlist(v_startrowindex integer DEFAULT 1, v_maxrows integer DEFAULT 100, v_branchid bigint DEFAULT 1, v_fromdate character varying DEFAULT ''::character varying, v_todate character varying DEFAULT ''::character varying, v_totalcount integer DEFAULT 0) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_minindex int;
  v_maxindex int;
  v_query text;
BEGIN
  v_minindex := (v_startrowindex - 1) * v_maxrows + 1;
  v_maxindex := v_startrowindex * v_maxrows;
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp ON COMMIT DROP AS SELECT ROW_NUMBER() OVER (ORDER BY om.orderdate DESC NULLS LAST) AS rownumber, om.orid, om.loginid, om.orderid, om.ordertype, om.orderdate, om.order_qty, om.order_dap, om.total_ship_ch, om.total_vat, om.order_netamt, om.paymode, om.fname, om.lname, om.mobileno, om.emailid, om.address, om.pincode, om.city, om.totalacceptedamt, om.totalrejectedamt, om.status, om.intstatus, om.description, om.branchid, om.reason FROM tbl_order_master AS om WHERE om.status = 'ReadyToShip' AND om.intstatus = 4 AND (v_branchid = 1 OR om.branchid = v_branchid) AND ((v_fromdate = '' OR v_todate = '') OR (CAST(om.orderdate AS DATE) BETWEEN CAST(v_fromdate AS DATE) AND CAST(v_todate AS DATE)));
  RETURN QUERY SELECT * FROM tmp_temp WHERE rownumber BETWEEN v_minindex AND v_maxindex;
  SELECT COUNT(rownumber) INTO v_totalcount FROM tmp_temp;
  DROP TABLE IF EXISTS tmp_temp;
  -- SET option (removed)
END;
$$;


--
-- Name: ims_usp_getproductdetail(bigint, bigint); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.ims_usp_getproductdetail(v_sprid bigint DEFAULT 20904, v_mprid bigint DEFAULT 0) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF (v_sprid <> 0 AND v_mprid = 0) THEN
  RETURN QUERY SELECT sm.sprid, sm.subprcode, sm.mprid, pm.productcode, pm.maincategoryid, pm.subcategoryid, pm.catid, pm.producttitle, pm.shotdescription, pm.fulldescription, pm.minorderqty, pm.maxorderqty, pm.paymode, pm.companyid, pm.branchid, pm.keyfeatures, sm.qty, sm.unit, sm.color, sm.size, sm.stockin, sm.stockout, sm.isoutofstock, sm.productimages, sm.discountpercentage, sm.vatcategoryid, sm.actualprice, sm.sellmrp, sm.dap, sm.activefrom, sm.activeto, sm.islevel, sm.isallowcoupon, sm.isactive, sm.isverified, COALESCE(sm.replacementday, 0) AS replacementday, COALESCE(sm.procurementsla, 0) AS procurementsla, COALESCE(sm.cashondelivery, 0) AS cashondelivery, COALESCE(sm.weight_kg, 0) AS weight_kg, COALESCE(sm.length_cms, 0) AS length_cms, COALESCE(sm.breadth_cms, 0) AS breadth_cms, COALESCE(sm.height_cms, 0) AS height_cms, COALESCE(sm.shippingcharges, 0) AS shippingcharges, mc.maincatname AS maincategoryname, CAST(COALESCE(v.vatpercvalue, 0) AS DECIMAL(18, 0)) AS vatpercentage, COALESCE(warrentyinfocare, 0) AS warrentyinfocare, COALESCE(sm.ywillrece, 0) AS ywillrece, COALESCE(sm.hsn, '') AS hsn, (CASE WHEN sm.manufacturerdetails = '0' THEN '' ELSE COALESCE(sm.manufacturerdetails, '') END) AS manufacturerdetails, (CASE WHEN sm.packerdetails = '0' THEN '' ELSE COALESCE(sm.packerdetails, '') END) AS packerdetails, (CASE WHEN sm.importerdetails = '0' THEN '' ELSE COALESCE(sm.importerdetails, '') END) AS importerdetails, COALESCE(sm.luxurycess, 0) AS luxurycess, COALESCE(sm.fullfilmentby, 0) AS fullfilmentby, COALESCE(sm.procurementtype, 0) AS procurementtype FROM ims_masterproduct AS pm INNER JOIN ims_subproduct AS sm ON sm.mprid = pm.mprid INNER JOIN tbl_main_category AS mc ON mc.maincatid = pm.maincategoryid LEFT OUTER JOIN tbl_vat_categories AS v ON v.vcid = pm.vatcategoryid WHERE sm.sprid = v_sprid;
  END IF;
  IF (v_sprid = 0 AND v_mprid <> 0) THEN
  RETURN QUERY SELECT v_sprid AS sprid, pm.mprid, pm.productcode, pm.maincategoryid, pm.subcategoryid, pm.catid, pm.producttitle, pm.shotdescription, pm.fulldescription, pm.minorderqty, pm.maxorderqty, pm.paymode, pm.companyid, pm.branchid, pm.keyfeatures, mc.maincatname AS maincategoryname, CAST(COALESCE(v.vatpercvalue, 0) AS DECIMAL(18, 0)) AS vatpercentage FROM ims_masterproduct AS pm INNER JOIN tbl_main_category AS mc ON mc.maincatid = pm.maincategoryid LEFT OUTER JOIN tbl_vat_categories AS v ON v.vcid = pm.vatcategoryid WHERE pm.mprid = v_mprid;
  END IF;
END;
$$;


--
-- Name: ims_usp_getsettlementsreport(integer, integer, bigint, character varying, character varying, character varying, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.ims_usp_getsettlementsreport(v_startrowindex integer DEFAULT 1, v_maxrows integer DEFAULT 100, v_branchid bigint DEFAULT 1, v_orderid character varying DEFAULT ''::character varying, v_fromdate character varying DEFAULT ''::character varying, v_todate character varying DEFAULT ''::character varying, v_totalcount integer DEFAULT 0) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_minindex INT;
  v_maxindex INT;
  v_query text;
  v_totalcomm numeric(19,4);
BEGIN
  v_totalcomm := 0;
  v_minindex := (v_startrowindex - 1) * v_maxrows + 1;
  v_maxindex := v_startrowindex * v_maxrows;
  v_fromdate := (CASE WHEN v_fromdate = '' THEN NULL ELSE v_fromdate END);
  v_todate := (CASE WHEN v_todate = '' THEN NULL ELSE v_todate END);
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp ON COMMIT DROP AS SELECT ROW_NUMBER() OVER (ORDER BY lb.createddate DESC NULLS LAST) AS rownumber, frombrid, lb.orderid, cr AS creditamount, dr AS debitamount, balance, lb.remark1, lb.remark2, operatoruserid, COALESCE(e.fname, '') || ' ' || COALESCE(e.mname, '') || ' ' || COALESCE(e.lname, '') AS operatorname, lb.createddate FROM ims_ledgerbranch AS lb LEFT JOIN member_master AS e ON e.plid = lb.operatoruserid WHERE lb.isactive = 1 AND ltype = 'OrderConfirmation' AND (v_branchid = 0 OR frombrid = v_branchid) AND lb.orderid LIKE '%' || v_orderid || '%' AND ((v_fromdate IS NULL OR v_todate IS NULL) OR (TO_DATE(lb.createddate, 'DD-MM-YYYY') BETWEEN TO_DATE(v_fromdate, 'DD-MM-YYYY') AND TO_DATE(v_todate, 'DD-MM-YYYY'))) ORDER BY createddate DESC NULLS LAST;
  SELECT COUNT(rownumber) INTO v_totalcount FROM tmp_temp;
  RETURN QUERY SELECT *, v_totalcount AS totalcount FROM tmp_temp WHERE rownumber BETWEEN v_minindex AND v_maxindex ORDER BY frombrid NULLS FIRST;
  DROP TABLE IF EXISTS tmp_temp;
  -- SET option (removed)
END;
$$;


--
-- Name: ims_usp_getsortlist(character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.ims_usp_getsortlist(v_sortby character varying DEFAULT ''::character varying) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_subprcode varchar(250);
  v_maxmprid varchar(250);
BEGIN
  v_subprcode := '';
  v_maxmprid := '';
  RETURN QUERY SELECT name, id FROM tbl_sortdetails WHERE sortby = v_sortby;
END;
$$;


--
-- Name: ims_usp_getsortlist_mobile(integer, integer, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.ims_usp_getsortlist_mobile(v_maincatid integer DEFAULT 0, v_catid integer DEFAULT 0, v_subcatid integer DEFAULT 0) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF (v_maincatid > 0 AND v_subcatid > 0) THEN
  RETURN QUERY SELECT MIN(dap) AS minamount, MAX(dap) AS maxamount FROM ims_subproduct AS sp JOIN ims_masterproduct AS mp ON mp.mprid = sp.sprid AND mp.maincategoryid = v_maincatid AND subcategoryid = v_subcatid AND catid = v_catid AND isverified = 1;
  ELSE
  RETURN QUERY SELECT MIN(dap) AS minamount, MAX(dap) AS maxamount FROM ims_subproduct AS sp JOIN ims_masterproduct AS mp ON mp.mprid = sp.sprid AND (mp.maincategoryid = v_maincatid OR subcategoryid = v_subcatid);
  END IF;
END;
$$;


--
-- Name: ims_usp_getvatcategorydetail(integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.ims_usp_getvatcategorydetail(v_vcid integer DEFAULT 0) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
BEGIN
  RETURN QUERY SELECT ROW_NUMBER() OVER (ORDER BY vcid NULLS FIRST) AS rownumber, vcid, vattitle, vatpercvalue, active, statename, branchid FROM tbl_vat_categories WHERE vcid = v_vcid;
END;
$$;


--
-- Name: ims_usp_home_product_searching(integer, integer, integer, character varying, text, integer, integer, integer, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.ims_usp_home_product_searching(v_maincatid integer DEFAULT 0, v_catid integer DEFAULT 0, v_subcatid integer DEFAULT 0, v_sorting character varying DEFAULT ''::character varying, v_querystring text DEFAULT ''::text, v_pageno integer DEFAULT 1, v_noofrows integer DEFAULT 100, v_totalcount integer DEFAULT 0, v_did integer DEFAULT 1) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_minindex INT;
  v_maxindex INT;
  v_mindiscount DECIMAL(18,2);
  v_maxdiscount DECIMAL(18,2);
  v_minprice DECIMAL(18,2);
  v_maxprice DECIMAL(18,2);
  v_isoutofstock boolean;
  v_cnt INT;
  v_cnt1 INT;
  v_countexists INT;
  v_attributename VARCHAR(50);
  v_value VARCHAR(50);
  v_attributevalue VARCHAR(100);
  v_title VARCHAR(100);
  v_returnmpid text;
BEGIN
  BEGIN
  v_mindiscount := NULL;
  v_maxdiscount := NULL;
  v_minprice := NULL;
  v_maxprice := NULL;
  v_isoutofstock := NULL;
  v_cnt := 0;
  v_cnt1 := 0;
  v_countexists := 0;
  v_attributename := '';
  v_value := '';
  v_attributevalue := '';
  v_title := NULL;
  v_minindex := (v_pageno - 1) * v_noofrows + 1;
  v_maxindex := v_pageno * v_noofrows;
  RAISE NOTICE '%', 1;
  IF (v_maincatid = 0) THEN
  v_maincatid := 0;
  END IF;
  IF (COALESCE(v_querystring, '') <> '') THEN
  DROP TABLE IF EXISTS tmp_tempp;
  CREATE TEMP TABLE tmp_tempp (ROWNO BIGINT  ,ATTRIBUTENAME VARCHAR( 100)  ,ATTRIBUTEVALUE VARCHAR( 100)  ,VALUE VARCHAR( 100)) ON COMMIT DROP;
  INSERT INTO tmp_tempp SELECT ROW_NUMBER() OVER (ORDER BY value NULLS FIRST) AS rowno, LEFT(CAST(value AS TEXT), POSITION('=' IN value) - 1) AS attributename, SUBSTRING(value FROM POSITION('=' IN value) + 1 FOR LENGTH(CAST(value AS TEXT))) AS attributevalue, value FROM SPLITSTRINGBYCUSTOMSYMBOL1(v_querystring, '&');
  SELECT COUNT(1) INTO v_cnt FROM tmp_tempp;
  v_cnt1 := 1;
  v_countexists := 1;
  v_querystring := '';
  WHILE (v_cnt1 <= v_cnt) LOOP
  SELECT attributename, attributevalue, value INTO v_attributename, v_attributevalue, v_value FROM tmp_tempp WHERE rowno = v_cnt1;
  IF (v_attributename = 'PAGE') THEN
  SELECT value INTO v_pageno FROM SPLITSTRINGBYCUSTOMSYMBOL1(REPLACE(v_attributevalue, '-', '_'), '_');
  END IF;
  IF (v_attributename = 'CATEGORY' AND v_attributevalue = 'ALL') THEN
  v_maincatid := 0;
  v_catid := 0;
  v_subcatid := 0;
  END IF;
  IF (v_attributename = 'DISCOUNT') THEN
  SELECT CAST(MIN(CAST(value AS INT)) AS DECIMAL(18, 0)), CAST(MAX(CAST(value AS INT)) AS DECIMAL(18, 0)) INTO v_mindiscount, v_maxdiscount FROM SPLITSTRINGBYCUSTOMSYMBOL1(REPLACE(v_attributevalue, '-', '_'), '_');
  END IF;
  IF (v_attributename = 'PRICE') THEN
  SELECT CAST(MIN(CAST(value AS INT)) AS DECIMAL(18, 0)), CAST(MAX(CAST(value AS INT)) AS DECIMAL(18, 0)) INTO v_minprice, v_maxprice FROM SPLITSTRINGBYCUSTOMSYMBOL1(REPLACE(v_attributevalue, '-', '_'), '_');
  END IF;
  IF (v_attributename = 'ISOUT') THEN
  SELECT CAST(value AS BIT) INTO v_isoutofstock FROM SPLITSTRINGBYCUSTOMSYMBOL1(REPLACE(v_attributevalue, '-', '_'), '_');
  END IF;
  IF (v_attributename = 'Title') THEN
  SELECT CAST(value AS VARCHAR(50)) INTO v_title FROM SPLITSTRINGBYCUSTOMSYMBOL1(REPLACE(v_attributevalue, '-', '_'), '_');
  END IF;
  IF (v_attributename = 'PRICEASC' OR v_attributename = 'PRICEDESC') THEN
  SELECT CAST(value AS VARCHAR(50)) INTO v_sorting FROM SPLITSTRINGBYCUSTOMSYMBOL1(REPLACE(v_attributevalue, '-', '_'), '_');
  END IF;
  IF (v_attributename <> 'PRICE' AND v_attributename <> 'DISCOUNT' AND v_attributename <> 'ISOUT' AND v_attributename <> 'TITLE' AND v_attributename <> 'PAGE' AND v_attributename <> 'CATEGORY') THEN
  RAISE NOTICE '%', 'Actual Query String';
  v_querystring := v_querystring || '&' || v_value;
  END IF;
  RAISE NOTICE '%', 6;
  v_cnt1 := v_cnt1 + 1;
  END LOOP;
  DROP TABLE IF EXISTS tmp_tempp;
  v_returnmpid := '';
  SELECT v_returnmpid INTO v_returnmpid FROM dbo.ims_usp_getmpidfromquerystring(v_querystring => v_querystring, v_returnmpid => v_returnmpid);
  END IF;
  SELECT CASE WHEN COALESCE(v_maxdiscount, 0) = 0 THEN MAX(discountpercentage) ELSE v_maxdiscount END, CASE WHEN COALESCE(v_mindiscount, 0) = 0 THEN MIN(discountpercentage) ELSE v_mindiscount END, CASE WHEN COALESCE(v_minprice, 0) = 0 THEN MIN(dap) ELSE v_minprice END, CASE WHEN COALESCE(v_maxprice, 0) = 0 THEN MAX(dap) ELSE v_maxprice END INTO v_maxdiscount, v_mindiscount, v_minprice, v_maxprice FROM ims_subproduct;
  DROP TABLE IF EXISTS tmp_tempsearching;
  CREATE TEMP TABLE tmp_tempsearching (ROWNO BIGINT  ,MPRID BIGINT  ,PRODUCTCODE VARCHAR( 50)  ,PRODUCTTITLE VARCHAR( 300)  
		,SHOTDESCRIPTION VARCHAR( 2000)  ,FULLDESCRIPTION text ,SPRID BIGINT  ,PRODUCTIMAGES VARCHAR( 1000)  
		,DISCOUNTPERCENTAGE DECIMAL ,SELLMRP DECIMAL ,DAP DECIMAL  ,MASTERPRODUCTATTRIUBUTEID BIGINT  ,ATTRIBUTETITLE VARCHAR( 200) 
       ,ATTRIBUTEVALUE VARCHAR( 200)  ,KEYFEATURES VARCHAR( 2000)  ,RATINGSTAR INT ,MAINCATEGORYID BIGINT  ,SUBCATEGORYID BIGINT  ,CATEGORYID BIGINT, DEALSIDS VARCHAR(100),CREATEDDATE timestamp,MODIFYDATE timestamp,REPLACEMENTDAY INT,PROCUREMENTSLA INT,
 CASHONDELIVERY boolean,SHIPPINGCHARGES DECIMAL(18,2),STOCKIN INT,STOCKOUT INT ,STOCKNET INT ,ISOUTOFSTOCK boolean,BV numeric(19,4),PV decimal(10,2),Main_Cat_Code varchar(100),Sub_Cat_Code varchar(100),Cat_Code varchar(100)) ON COMMIT DROP;
  IF (v_sorting = 'PRICEASC') THEN
  IF (v_querystring = '') THEN
  IF (v_did > 0) THEN
  INSERT INTO tmp_tempsearching SELECT ROW_NUMBER() OVER (ORDER BY dap ASC NULLS FIRST) AS rowno, mprid, productcode, producttitle, shotdescription, fulldescription, vp.sprid, productimages, discountpercentage, sellmrp, dap, masterproductattriubuteid, attributetitle, attributevalue, keyfeatures, CAST(dbo.FUN_GETRATINGOFSUBPRODUCT(vp.sprid) AS INT) AS ratingstar, maincategoryid, subcategoryid, catid, dealsids, createddate, modifydate, replacementday, procurementsla, cashondelivery, shippingcharges, stockin, stockout, stocknet, isoutofstock, COALESCE(dpw.bv, 0) AS bv, COALESCE(dpw.pv, 0) AS pv, main_cat_code, sub_cat_code, cat_code FROM ims_view_allproductdeals AS vp LEFT JOIN tbl_distributor_comm_productwise AS dpw ON dpw.sprid = vp.sprid AND did = v_did WHERE (v_maincatid = 0 OR maincategoryid = v_maincatid) AND (v_catid = 0 OR catid = v_catid) AND (v_subcatid = 0 OR subcategoryid = v_subcatid) AND (v_title IS NULL OR producttitle LIKE '%' || v_title || '%') AND (discountpercentage BETWEEN v_mindiscount AND v_maxdiscount) AND (dap BETWEEN v_minprice AND v_maxprice) AND (v_isoutofstock IS NULL OR isoutofstock = v_isoutofstock);
  ELSE
  INSERT INTO tmp_tempsearching SELECT ROW_NUMBER() OVER (ORDER BY dap ASC NULLS FIRST) AS rowno, mprid, productcode, producttitle, shotdescription, fulldescription, sprid, productimages, discountpercentage, sellmrp, dap, masterproductattriubuteid, attributetitle, attributevalue, keyfeatures, CAST(dbo.FUN_GETRATINGOFSUBPRODUCT(sprid) AS INT) AS ratingstar, maincategoryid, subcategoryid, catid, dealsids, createddate, modifydate, replacementday, procurementsla, cashondelivery, shippingcharges, stockin, stockout, stocknet, isoutofstock, bv, pv, main_cat_code, sub_cat_code, cat_code FROM ims_view_allproductdeals WHERE (v_maincatid = 0 OR maincategoryid = v_maincatid) AND (v_catid = 0 OR catid = v_catid) AND (v_subcatid = 0 OR subcategoryid = v_subcatid) AND (v_title IS NULL OR producttitle LIKE '%' || v_title || '%') AND (discountpercentage BETWEEN v_mindiscount AND v_maxdiscount) AND (dap BETWEEN v_minprice AND v_maxprice) AND (v_isoutofstock IS NULL OR isoutofstock = v_isoutofstock);
  END IF;
  ELSE
  IF (v_did > 0) THEN
  INSERT INTO tmp_tempsearching SELECT ROW_NUMBER() OVER (ORDER BY dap ASC NULLS FIRST) AS rowno, mprid, productcode, producttitle, shotdescription, fulldescription, vp.sprid, productimages, discountpercentage, sellmrp, dap, masterproductattriubuteid, attributetitle, attributevalue, keyfeatures, CAST(dbo.FUN_GETRATINGOFSUBPRODUCT(vp.sprid) AS INT) AS ratingstar, maincategoryid, subcategoryid, catid, dealsids, createddate, modifydate, replacementday, procurementsla, cashondelivery, shippingcharges, stockin, stockout, stocknet, isoutofstock, COALESCE(dpw.bv, 0) AS bv, COALESCE(dpw.pv, 0) AS pv, main_cat_code, sub_cat_code, cat_code FROM ims_view_allproductdeals AS vp LEFT JOIN tbl_distributor_comm_productwise AS dpw ON dpw.sprid = vp.sprid AND did = v_did WHERE (v_maincatid = 0 OR maincategoryid = v_maincatid) AND (v_catid = 0 OR catid = v_catid) AND (v_subcatid = 0 OR subcategoryid = v_subcatid) AND (v_title IS NULL OR producttitle LIKE '%' || v_title || '%') AND (masterproductattriubuteid IN (SELECT * FROM dbo.SPLITSTRINGBYCUSTOMSYMBOL1(v_returnmpid, ','))) AND (discountpercentage BETWEEN v_mindiscount AND v_maxdiscount) AND (dap BETWEEN v_minprice AND v_maxprice) AND (v_isoutofstock IS NULL OR isoutofstock = v_isoutofstock);
  ELSE
  INSERT INTO tmp_tempsearching SELECT ROW_NUMBER() OVER (ORDER BY dap ASC NULLS FIRST) AS rowno, mprid, productcode, producttitle, shotdescription, fulldescription, sprid, productimages, discountpercentage, sellmrp, dap, masterproductattriubuteid, attributetitle, attributevalue, keyfeatures, CAST(dbo.FUN_GETRATINGOFSUBPRODUCT(sprid) AS INT) AS ratingstar, maincategoryid, subcategoryid, catid, dealsids, createddate, modifydate, replacementday, procurementsla, cashondelivery, shippingcharges, stockin, stockout, stocknet, isoutofstock, bv, pv, main_cat_code, sub_cat_code, cat_code FROM ims_view_allproductdeals WHERE (v_maincatid = 0 OR maincategoryid = v_maincatid) AND (v_catid = 0 OR catid = v_catid) AND (v_subcatid = 0 OR subcategoryid = v_subcatid) AND (v_title IS NULL OR producttitle LIKE '%' || v_title || '%') AND (masterproductattriubuteid IN (SELECT * FROM dbo.SPLITSTRINGBYCUSTOMSYMBOL1(v_returnmpid, ','))) AND (discountpercentage BETWEEN v_mindiscount AND v_maxdiscount) AND (dap BETWEEN v_minprice AND v_maxprice) AND (v_isoutofstock IS NULL OR isoutofstock = v_isoutofstock);
  END IF;
  END IF;
  ELSE
  IF (v_sorting = 'PRICEDESC') THEN
  IF (v_querystring = '') THEN
  IF (v_did > 0) THEN
