  RETURN QUERY SELECT (SELECT CASE WHEN COALESCE(COUNT(1), 0) > 0 THEN 1 ELSE 0 END FROM tbl_wishlist WHERE sprid = tm.sprid AND loginid = v_getclid AND status = 1) AS wishcount, * FROM tmp_tempsearching2 AS tm LIMIT 10;
