CREATE FUNCTION dbo.ims_usp_home_product_searching_dashboard_mobile_bak28082018(v_maincatid integer DEFAULT 0, v_catid integer DEFAULT 0, v_subcatid integer DEFAULT 0, v_sorting character varying DEFAULT ''::character varying, v_querystring text DEFAULT ''::text, v_pageno integer DEFAULT 1, v_noofrows integer DEFAULT 100, v_totalcount integer DEFAULT 0, v_did integer DEFAULT 0, v_uidno character varying DEFAULT ''::character varying, v_clid integer DEFAULT 0) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_minindex INT;
  v_maxindex INT;
  v_mindiscount DECIMAL(18,2);
  v_maxdiscount DECIMAL(18,2);
  v_minprice DECIMAL(18,2);
  v_maxprice DECIMAL(18,2);
  v_isoutofstock boolean;
  v_getdid int;
  v_cnt INT;
  v_cnt1 INT;
  v_countexists INT;
  v_attributename VARCHAR(50);
  v_value VARCHAR(50);
  v_attributevalue VARCHAR(100);
  v_title VARCHAR(100);
  v_dynamicurl varchar(100);
  v_returnmpid text;
