  BEGIN
  v_mindiscount := NULL;
  v_maxdiscount := NULL;
  v_minprice := NULL;
  v_maxprice := NULL;
  v_isoutofstock := NULL;
  v_getdid := 0;
  v_cnt := 0;
  v_cnt1 := 0;
  v_countexists := 0;
  v_attributename := '';
  v_value := '';
  v_attributevalue := '';
  v_title := NULL;
