  INSERT INTO tmp_tempsearching SELECT ROW_NUMBER() OVER (ORDER BY mprid NULLS FIRST) AS rowno, mprid, productcode, producttitle, vp.sprid, CASE WHEN POSITION('^' IN productimages) > 0 THEN (LEFT(CAST(v_dynamicurl || productimages AS TEXT), POSITION('^' IN v_dynamicurl || productimages) + 0)) ELSE v_dynamicurl || productimages || '^' END AS productimages, discountpercentage, sellmrp, dap, maincategoryid, subcategoryid, catid, COALESCE(dpw.bv, 0) AS bv, COALESCE(dpw.pv, 0) AS pv, (SELECT COALESCE(COUNT(1), 0) FROM tbl_wishlist WHERE sprid = vp.sprid AND loginid = v_clid AND status = 1) AS wishproduct FROM ims_view_allproductdeals AS vp LEFT JOIN tbl_distributor_comm_productwise AS dpw ON dpw.sprid = vp.sprid AND did = v_did WHERE (v_maincatid = 0 OR maincategoryid = v_maincatid) AND (v_catid = 0 OR catid = v_catid) AND (v_subcatid = 0 OR subcategoryid = v_subcatid) AND (v_title IS NULL OR producttitle LIKE '%' || v_title || '%') AND (masterproductattriubuteid IN (SELECT * FROM dbo.SPLITSTRINGBYCUSTOMSYMBOL1(v_returnmpid, ','))) AND (discountpercentage BETWEEN v_mindiscount AND v_maxdiscount) AND (dap BETWEEN v_minprice AND v_maxprice) AND (v_isoutofstock IS NULL OR isoutofstock = v_isoutofstock);
  ELSE
  INSERT INTO tmp_tempsearching SELECT ROW_NUMBER() OVER (ORDER BY mprid NULLS FIRST) AS rowno, mprid, productcode, producttitle, vp.sprid, CASE WHEN POSITION('^' IN productimages) > 0 THEN (LEFT(CAST(v_dynamicurl || productimages AS TEXT), POSITION('^' IN v_dynamicurl || productimages) + 0)) ELSE v_dynamicurl || productimages || '^' END AS productimages, discountpercentage, sellmrp, dap, maincategoryid, subcategoryid, catid, COALESCE(dpw.bv, 0) AS bv, COALESCE(dpw.pv, 0) AS pv, (SELECT COALESCE(COUNT(1), 0) FROM tbl_wishlist WHERE sprid = vp.sprid AND loginid = v_clid AND status = 1) AS wishproduct FROM ims_view_allproductdeals AS vp LEFT JOIN tbl_distributor_comm_productwise AS dpw ON dpw.sprid = vp.sprid AND did = v_did WHERE (v_maincatid = 0 OR maincategoryid = v_maincatid) AND (v_catid = 0 OR catid = v_catid) AND (v_subcatid = 0 OR subcategoryid = v_subcatid) AND (v_title IS NULL OR producttitle LIKE '%' || v_title || '%') AND (masterproductattriubuteid IN (SELECT * FROM dbo.SPLITSTRINGBYCUSTOMSYMBOL1(v_returnmpid, ','))) AND (discountpercentage BETWEEN v_mindiscount AND v_maxdiscount) AND (dap BETWEEN v_minprice AND v_maxprice) AND (v_isoutofstock IS NULL OR isoutofstock = v_isoutofstock);
  END IF;
  END IF;
  END IF;
  END IF;
  END IF;
  END IF;
  END IF;
  END IF;
  DROP TABLE IF EXISTS tmp_tempsearching1;
  CREATE TEMP TABLE tmp_tempsearching1 (PRODUCTTITLE varchar (250)) ON COMMIT DROP;
  INSERT INTO tmp_tempsearching1 SELECT producttitle FROM tmp_tempsearching GROUP BY producttitle HAVING COUNT(producttitle) >= 1;
  SELECT COUNT(rowno) INTO v_totalcount FROM tmp_tempsearching;
  RETURN QUERY SELECT v_totalcount AS totalcount, CASE WHEN wishproduct > 0 THEN 1 ELSE 0 END AS wishcount, * FROM tmp_tempsearching WHERE rowno IN (SELECT MIN(rowno) FROM tmp_tempsearching GROUP BY producttitle);
  DROP TABLE IF EXISTS tmp_tempsearching;
  DROP TABLE IF EXISTS tmp_tempsearching1;
  -- SET option (removed)
  EXCEPTION WHEN OTHERS THEN
  v_totalcount := 0;
  END;
END;
$$;


--
-- Name: ims_usp_home_product_searching_mobile(integer, integer, integer, character varying, text, integer, integer, integer, integer, character varying, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.ims_usp_home_product_searching_mobile(v_maincatid integer DEFAULT 0, v_catid integer DEFAULT 0, v_subcatid integer DEFAULT 0, v_sorting character varying DEFAULT ''::character varying, v_querystring text DEFAULT ''::text, v_pageno integer DEFAULT 1, v_noofrows integer DEFAULT 100, v_totalcount integer DEFAULT 0, v_did integer DEFAULT 1, v_uidno character varying DEFAULT ''::character varying, v_clid integer DEFAULT 0) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_minindex INT;
  v_maxindex INT;
  v_mindiscount DECIMAL(18,2);
  v_maxdiscount DECIMAL(18,2);
  v_minprice DECIMAL(18,2);
  v_maxprice DECIMAL(18,2);
  v_isoutofstock boolean;
  v_getdid int;
  v_cnt INT;
  v_cnt1 INT;
  v_countexists INT;
  v_attributename VARCHAR(50);
  v_value VARCHAR(50);
  v_attributevalue VARCHAR(100);
  v_title VARCHAR(100);
  v_dynamicurl varchar(100);
  v_returnmpid text;
BEGIN
  BEGIN
  v_mindiscount := NULL;
  v_maxdiscount := NULL;
  v_minprice := NULL;
  v_maxprice := NULL;
  v_isoutofstock := NULL;
  v_getdid := 0;
  v_cnt := 0;
  v_cnt1 := 0;
  v_countexists := 0;
  v_attributename := '';
  v_value := '';
  v_attributevalue := '';
  v_title := NULL;
  v_minindex := (v_pageno - 1) * v_noofrows + 1;
  v_maxindex := v_pageno * v_noofrows;
  RAISE NOTICE '%', 1;
  IF (v_maincatid = 0) THEN
  v_maincatid := 4;
  END IF;
  v_dynamicurl := '';
  SELECT merchantimagepath INTO v_dynamicurl FROM tbl_company;
  SELECT did INTO v_getdid FROM tbl_customerlogin WHERE clid = v_clid;
  IF (v_getdid > 0) THEN
  v_did := v_getdid;
  END IF;
  IF (COALESCE(v_querystring, '') <> '') THEN
  DROP TABLE IF EXISTS tmp_tempp;
  CREATE TEMP TABLE tmp_tempp (ROWNO BIGINT  ,ATTRIBUTENAME VARCHAR( 100)  ,ATTRIBUTEVALUE VARCHAR( 100)  ,VALUE VARCHAR( 100)) ON COMMIT DROP;
  INSERT INTO tmp_tempp SELECT ROW_NUMBER() OVER (ORDER BY value NULLS FIRST) AS rowno, LEFT(CAST(value AS TEXT), POSITION('=' IN value) - 1) AS attributename, SUBSTRING(value FROM POSITION('=' IN value) + 1 FOR LENGTH(CAST(value AS TEXT))) AS attributevalue, value FROM SPLITSTRINGBYCUSTOMSYMBOL1(v_querystring, '&');
  SELECT COUNT(1) INTO v_cnt FROM tmp_tempp;
  v_cnt1 := 1;
  v_countexists := 1;
  v_querystring := '';
  WHILE (v_cnt1 <= v_cnt) LOOP
  SELECT attributename, attributevalue, value INTO v_attributename, v_attributevalue, v_value FROM tmp_tempp WHERE rowno = v_cnt1;
  IF (v_attributename = 'PAGE') THEN
  SELECT value INTO v_pageno FROM SPLITSTRINGBYCUSTOMSYMBOL1(REPLACE(v_attributevalue, '-', '_'), '_');
  END IF;
  IF (v_attributename = 'CATEGORY' AND v_attributevalue = 'ALL') THEN
  v_maincatid := 0;
  v_catid := 0;
  v_subcatid := 0;
  END IF;
  IF (v_attributename = 'DISCOUNT') THEN
  SELECT CAST(MIN(CAST(value AS INT)) AS DECIMAL(18, 0)), CAST(MAX(CAST(value AS INT)) AS DECIMAL(18, 0)) INTO v_mindiscount, v_maxdiscount FROM SPLITSTRINGBYCUSTOMSYMBOL1(REPLACE(v_attributevalue, '-', '_'), '_');
  END IF;
  IF (v_attributename = 'PRICE') THEN
  SELECT CAST(MIN(CAST(value AS INT)) AS DECIMAL(18, 0)), CAST(MAX(CAST(value AS INT)) AS DECIMAL(18, 0)) INTO v_minprice, v_maxprice FROM SPLITSTRINGBYCUSTOMSYMBOL1(REPLACE(v_attributevalue, '-', '_'), '_');
  END IF;
  IF (v_attributename = 'ISOUT') THEN
  SELECT CAST(value AS BIT) INTO v_isoutofstock FROM SPLITSTRINGBYCUSTOMSYMBOL1(REPLACE(v_attributevalue, '-', '_'), '_');
  END IF;
  IF (v_attributename = 'Title') THEN
  SELECT CAST(value AS VARCHAR(50)) INTO v_title FROM SPLITSTRINGBYCUSTOMSYMBOL1(REPLACE(v_attributevalue, '-', '_'), '_');
  END IF;
  IF (v_attributename = 'PRICEASC' OR v_attributename = 'PRICEDESC') THEN
  SELECT CAST(value AS VARCHAR(50)) INTO v_sorting FROM SPLITSTRINGBYCUSTOMSYMBOL1(REPLACE(v_attributevalue, '-', '_'), '_');
  END IF;
  IF (v_attributename <> 'PRICE' AND v_attributename <> 'DISCOUNT' AND v_attributename <> 'ISOUT' AND v_attributename <> 'TITLE' AND v_attributename <> 'PAGE' AND v_attributename <> 'CATEGORY') THEN
  RAISE NOTICE '%', 'Actual Query String';
  v_querystring := v_querystring || '&' || v_value;
  END IF;
  RAISE NOTICE '%', 6;
  v_cnt1 := v_cnt1 + 1;
  END LOOP;
  DROP TABLE IF EXISTS tmp_tempp;
  v_returnmpid := '';
  SELECT v_returnmpid INTO v_returnmpid FROM dbo.ims_usp_getmpidfromquerystring(v_querystring => v_querystring, v_returnmpid => v_returnmpid);
  END IF;
  SELECT CASE WHEN COALESCE(v_maxdiscount, 0) = 0 THEN MAX(discountpercentage) ELSE v_maxdiscount END, CASE WHEN COALESCE(v_mindiscount, 0) = 0 THEN MIN(discountpercentage) ELSE v_mindiscount END, CASE WHEN COALESCE(v_minprice, 0) = 0 THEN MIN(dap) ELSE v_minprice END, CASE WHEN COALESCE(v_maxprice, 0) = 0 THEN MAX(dap) ELSE v_maxprice END INTO v_maxdiscount, v_mindiscount, v_minprice, v_maxprice FROM ims_subproduct;
