  INSERT INTO tmp_tempsearching SELECT ROW_NUMBER() OVER (ORDER BY dap ASC NULLS FIRST) AS rowno, mprid, productcode, producttitle, vp.sprid, CASE WHEN POSITION('^' IN productimages) > 0 THEN (LEFT(CAST(v_dynamicurl || productimages AS TEXT), POSITION('^' IN v_dynamicurl || productimages) + 0)) ELSE v_dynamicurl || productimages || '^' END AS productimages, discountpercentage, sellmrp, dap, maincategoryid, subcategoryid, catid, COALESCE(dpw.bv, 0) AS bv, COALESCE(dpw.pv, 0) AS pv, (SELECT COALESCE(COUNT(1), 0) FROM tbl_wishlist WHERE sprid = vp.sprid AND loginid = v_clid AND status = 1) AS wishproduct FROM ims_view_allproductdeals AS vp LEFT JOIN tbl_distributor_comm_productwise AS dpw ON dpw.sprid = vp.sprid AND did = v_did WHERE (v_maincatid = 0 OR maincategoryid = v_maincatid) AND (v_catid = 0 OR catid = v_catid) AND (v_subcatid = 0 OR subcategoryid = v_subcatid) AND (v_title IS NULL OR producttitle LIKE '%' || v_title || '%') AND (masterproductattriubuteid IN (SELECT * FROM dbo.SPLITSTRINGBYCUSTOMSYMBOL1(v_returnmpid, ','))) AND (discountpercentage BETWEEN v_mindiscount AND v_maxdiscount) AND (dap BETWEEN v_minprice AND v_maxprice) AND (v_isoutofstock IS NULL OR isoutofstock = v_isoutofstock);
  ELSE
  INSERT INTO tmp_tempsearching SELECT ROW_NUMBER() OVER (ORDER BY dap ASC NULLS FIRST) AS rowno, mprid, productcode, producttitle, sprid, CASE WHEN POSITION('^' IN productimages) > 0 THEN (LEFT(CAST(v_dynamicurl || productimages AS TEXT), POSITION('^' IN v_dynamicurl || productimages) + 0)) ELSE v_dynamicurl || productimages || '^' END AS productimages, discountpercentage, sellmrp, dap, maincategoryid, subcategoryid, catid, bv, pv, (SELECT COALESCE(COUNT(1), 0) FROM tbl_wishlist WHERE sprid = sprid AND loginid = v_clid AND status = 1) AS wishproduct FROM ims_view_allproductdeals WHERE (v_maincatid = 0 OR maincategoryid = v_maincatid) AND (v_catid = 0 OR catid = v_catid) AND (v_subcatid = 0 OR subcategoryid = v_subcatid) AND (v_title IS NULL OR producttitle LIKE '%' || v_title || '%') AND (masterproductattriubuteid IN (SELECT * FROM dbo.SPLITSTRINGBYCUSTOMSYMBOL1(v_returnmpid, ','))) AND (discountpercentage BETWEEN v_mindiscount AND v_maxdiscount) AND (dap BETWEEN v_minprice AND v_maxprice) AND (v_isoutofstock IS NULL OR isoutofstock = v_isoutofstock);
  END IF;
  END IF;
  ELSE
  IF (v_sorting = 'PRICEDESC') THEN
  IF (v_querystring = '') THEN
  IF (v_did > 0) THEN
  INSERT INTO tmp_tempsearching SELECT ROW_NUMBER() OVER (ORDER BY dap DESC NULLS LAST) AS rowno, mprid, productcode, producttitle, vp.sprid, CASE WHEN POSITION('^' IN productimages) > 0 THEN (LEFT(CAST(v_dynamicurl || productimages AS TEXT), POSITION('^' IN v_dynamicurl || productimages) + 0)) ELSE v_dynamicurl || productimages || '^' END AS productimages, discountpercentage, sellmrp, dap, maincategoryid, subcategoryid, catid, COALESCE(dpw.bv, 0) AS bv, COALESCE(dpw.pv, 0) AS pv, (SELECT COALESCE(COUNT(1), 0) FROM tbl_wishlist WHERE sprid = vp.sprid AND loginid = v_clid AND status = 1) AS wishproduct FROM ims_view_allproductdeals AS vp LEFT JOIN tbl_distributor_comm_productwise AS dpw ON dpw.sprid = vp.sprid AND did = v_did WHERE (v_maincatid = 0 OR maincategoryid = v_maincatid) AND (v_catid = 0 OR catid = v_catid) AND (v_subcatid = 0 OR subcategoryid = v_subcatid) AND (v_title IS NULL OR producttitle LIKE '%' || v_title || '%') AND (discountpercentage BETWEEN v_mindiscount AND v_maxdiscount) AND (dap BETWEEN v_minprice AND v_maxprice) AND (v_isoutofstock IS NULL OR isoutofstock = v_isoutofstock);
  ELSE
