--
-- Name: ims_usp_home_product_searching_new(integer, integer, integer, character varying, text, integer, integer, integer, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.ims_usp_home_product_searching_new(v_maincatid integer DEFAULT 0, v_catid integer DEFAULT 0, v_subcatid integer DEFAULT 0, v_sorting character varying DEFAULT ''::character varying, v_querystring text DEFAULT ''::text, v_pageno integer DEFAULT 1, v_noofrows integer DEFAULT 100, v_totalcount integer DEFAULT 0, v_did integer DEFAULT 1) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_minindex INT;
  v_maxindex INT;
  v_mindiscount DECIMAL(18,2);
  v_maxdiscount DECIMAL(18,2);
  v_minprice DECIMAL(18,2);
  v_maxprice DECIMAL(18,2);
  v_isoutofstock boolean;
  v_cnt INT;
  v_cnt1 INT;
  v_countexists INT;
  v_attributename VARCHAR(50);
  v_value VARCHAR(50);
  v_attributevalue VARCHAR(100);
  v_title VARCHAR(100);
BEGIN
  BEGIN
  v_mindiscount := NULL;
  v_maxdiscount := NULL;
  v_minprice := NULL;
  v_maxprice := NULL;
  v_isoutofstock := NULL;
  v_cnt := 0;
  v_cnt1 := 0;
  v_countexists := 0;
  v_attributename := '';
  v_value := '';
  v_attributevalue := '';
  v_title := NULL;
  v_minindex := (v_pageno - 1) * v_noofrows + 1;
  v_maxindex := v_pageno * v_noofrows;
  SELECT CASE WHEN COALESCE(v_maxdiscount, 0) = 0 THEN MAX(discountpercentage) ELSE v_maxdiscount END, CASE WHEN COALESCE(v_mindiscount, 0) = 0 THEN MIN(discountpercentage) ELSE v_mindiscount END, CASE WHEN COALESCE(v_minprice, 0) = 0 THEN MIN(dap) ELSE v_minprice END, CASE WHEN COALESCE(v_maxprice, 0) = 0 THEN MAX(dap) ELSE v_maxprice END INTO v_maxdiscount, v_mindiscount, v_minprice, v_maxprice FROM ims_subproduct;
  DROP TABLE IF EXISTS tmp_tempsearching;
  CREATE TEMP TABLE tmp_tempsearching (ROWNO BIGINT  ,MPRID BIGINT  ,PRODUCTCODE VARCHAR( 50)  ,PRODUCTTITLE VARCHAR( 300)  
		,SHOTDESCRIPTION VARCHAR( 2000)  ,FULLDESCRIPTION text ,SPRID BIGINT  ,PRODUCTIMAGES VARCHAR( 1000)  
		,DISCOUNTPERCENTAGE DECIMAL ,SELLMRP DECIMAL ,DAP DECIMAL  ,MASTERPRODUCTATTRIUBUTEID BIGINT  ,ATTRIBUTETITLE VARCHAR( 200) 
       ,ATTRIBUTEVALUE VARCHAR( 200)  ,KEYFEATURES VARCHAR( 2000)  ,RATINGSTAR INT ,MAINCATEGORYID BIGINT  ,SUBCATEGORYID BIGINT  ,CATEGORYID BIGINT, DEALSIDS VARCHAR(100),CREATEDDATE timestamp,MODIFYDATE timestamp,REPLACEMENTDAY INT,PROCUREMENTSLA INT,
 CASHONDELIVERY boolean,SHIPPINGCHARGES DECIMAL(18,2),STOCKIN INT,STOCKOUT INT ,STOCKNET INT ,ISOUTOFSTOCK boolean,BV numeric(19,4),PV decimal(10,2),Main_Cat_Code varchar(100),Sub_Cat_Code varchar(100),Cat_Code varchar(100)) ON COMMIT DROP;
  IF (v_querystring = '') THEN
  IF (v_did > 0) THEN
  INSERT INTO tmp_tempsearching SELECT ROW_NUMBER() OVER (ORDER BY mprid NULLS FIRST) AS rowno, mprid, productcode, producttitle, shotdescription, fulldescription, vp.sprid, productimages, discountpercentage, sellmrp, dap, masterproductattriubuteid, attributetitle, attributevalue, keyfeatures, CAST(dbo.FUN_GETRATINGOFSUBPRODUCT(vp.sprid) AS INT) AS ratingstar, maincategoryid, subcategoryid, catid, dealsids, createddate, modifydate, replacementday, procurementsla, cashondelivery, shippingcharges, stockin, stockout, stocknet, isoutofstock, COALESCE(dpw.bv, 0) AS bv, COALESCE(dpw.pv, 0) AS pv, main_cat_code, sub_cat_code, cat_code FROM ims_view_allproductdeals AS vp LEFT JOIN tbl_distributor_comm_productwise AS dpw ON dpw.sprid = vp.sprid AND did = v_did WHERE (discountpercentage BETWEEN v_mindiscount AND v_maxdiscount) AND (dap BETWEEN v_minprice AND v_maxprice) LIMIT 70;
  END IF;
  END IF;
  SELECT 0 INTO v_totalcount;
  RETURN QUERY SELECT v_totalcount AS totalcount, * FROM tmp_tempsearching WHERE rowno IN (SELECT MIN(rowno) FROM tmp_tempsearching GROUP BY producttitle) ORDER BY GEN_RANDOM_UUID() NULLS FIRST;
  DROP TABLE IF EXISTS tmp_tempsearching;
  -- SET option (removed)
  EXCEPTION WHEN OTHERS THEN
  v_totalcount := 0;
  END;
END;
$$;


--
-- Name: ims_usp_insertlog(boolean, character varying, bigint, character varying, character varying, character varying, character varying, character varying, boolean, character varying, bigint); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.ims_usp_insertlog(v_iscatch boolean DEFAULT false, v_operationtype character varying DEFAULT NULL::character varying, v_touserid bigint DEFAULT NULL::bigint, v_tousertype character varying DEFAULT NULL::character varying, v_tablename character varying DEFAULT NULL::character varying, v_storedprocedure character varying DEFAULT NULL::character varying, v_remarks character varying DEFAULT NULL::character varying, v_ipaddress character varying DEFAULT NULL::character varying, INOUT v_success boolean DEFAULT true, INOUT v_message character varying DEFAULT 'Your Log is created Successfully.'::character varying, INOUT v_sqlresult bigint DEFAULT 0) RETURNS record
    LANGUAGE plpgsql
    AS $$
BEGIN
  BEGIN
  INSERT INTO ims_logs (iscatch, operationtype, touserid, tousertype, tablename, storedprocedure, remarks, ipaddress, createddate, logsguid) VALUES (v_iscatch, v_operationtype, v_touserid, v_tousertype, v_tablename, v_storedprocedure, v_remarks, v_ipaddress, CURRENT_TIMESTAMP, GEN_RANDOM_UUID());
  v_sqlresult := LASTVAL();
  v_message := 'Your Log is Created Successfully.';
  EXCEPTION WHEN OTHERS THEN
  v_success := 0;
  v_message := 'Your Log is Failed.';
  END;
END;
$$;


--
-- Name: ims_usp_isdefault_customeraddress(uuid, bigint, character varying, character varying, boolean, character varying, character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.ims_usp_isdefault_customeraddress(v_addressguid uuid DEFAULT NULL::uuid, v_touserid bigint DEFAULT NULL::bigint, v_tousertype character varying DEFAULT NULL::character varying, v_ipaddress character varying DEFAULT NULL::character varying, INOUT v_success boolean DEFAULT true, INOUT v_message character varying DEFAULT ''::character varying, INOUT v_sqlresult character varying DEFAULT 0) RETURNS record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_logid BigInt;
  v_error varchar(1000);
BEGIN
  BEGIN
  v_logid := 0;
  IF EXISTS(SELECT 1 FROM ims_customeraddress WHERE addressguid = v_addressguid) THEN
  PERFORM dbo.ims_usp_insertlog(v_iscatch => 1, v_operationtype => 'Update', v_touserid => v_touserid, v_tousertype => v_tousertype, v_tablename => 'IMS_CustomerAddress', v_storedprocedure => 'ims_usp_ChangeIsDefault', v_remarks => 'Change Status of IsDefault', v_ipaddress => v_ipaddress, v_success => v_success, v_message => v_message, v_sqlresult => v_logid);
  v_logid := LASTVAL();
  UPDATE ims_customeraddress SET isdefault = 0 WHERE v_touserid = v_touserid AND tousertype = v_tousertype;
  UPDATE ims_customeraddress SET isdefault = 1 WHERE addressguid = v_addressguid;
  v_sqlresult := LASTVAL();
  v_success := 1;
  v_message := ' Your Change IsDefault Set successfully. ';
  ELSE
  v_success := 0;
  v_message := ' Your AddressGuid is Not Exist on Records. ';
  END IF;
  EXCEPTION WHEN OTHERS THEN
  v_error := 'Error Message : ' || sqlerrm || ', Line ' || CAST(0 AS VARCHAR(5)) || ', ErrorSeverity :' || 0 || ', ErrorState :' || 0;
  PERFORM dbo.ims_usp_insertlog(v_iscatch => 1, v_operationtype => 'Update', v_touserid => v_touserid, v_tousertype => v_tousertype, v_tablename => 'IMS_CustomerAddress', v_storedprocedure => 'ims_usp_ChangeIsDefault', v_remarks => v_error, v_ipaddress => v_ipaddress, v_success => v_success, v_message => v_message, v_sqlresult => v_logid);
  v_sqlresult := v_logid;
  v_success := 0;
  v_message := 'Your Change IsDefault Set failed.';
  END;
END;
$$;


