  RETURN;
  END IF;
  ELSE
  v_ddl_value := CAST(v_ddl_id AS VARCHAR(15)) || '_' || dbo.GENERATEDDL_ID(v_ddl_text);
  INSERT INTO tbl_dropdowndetails (dddid, ddid, type, content, details, status, createon) VALUES (v_dddid, v_parent_ddl_id, 'ddl_ID', v_ddl_text, v_ddl_value, 1, dbo.FUN_GETCURRENTDATE());
  v_strresult := 'success^' || CAST(v_dddid AS VARCHAR(15));
  END IF;
  ELSE
  -- COMMIT (removed)
