  RETURN;
  END IF;
  v_ddl_id := 0;
  RAISE NOTICE '%', v_ddl_value;
  RAISE NOTICE '%', v_ddl_id;
  UPDATE tbl_dropdowndetails SET content = v_ddl_text WHERE dddid = CAST(v_ddl_value AS VARCHAR(10));
  v_strresult := 'success^' || CAST(v_ddl_value AS VARCHAR(15));
  END IF;
  IF (v_mode = 'DELETE-ITEM') THEN
  v_ddl_id := 0;
  UPDATE tbl_dropdowndetails SET status = 0 WHERE dddid = CAST(v_ddl_value AS VARCHAR(10));
  v_strresult := 'success^' || CAST(v_ddl_value AS VARCHAR(15));
  END IF;
  IF (0 <> 0) THEN
  -- ROLLBACK (removed)
  v_strresult := 'error^Some error Occured !';
  RETURN;
  END IF;
  -- COMMIT (removed)
END;
$$;


