,SHOTDESCRIPTION VARCHAR( 2000)  ,FULLDESCRIPTION text ,SPRID BIGINT  ,PRODUCTIMAGES VARCHAR( 1000)                
,DISCOUNTPERCENTAGE DECIMAL(18,2) ,SELLMRP DECIMAL(18,2) ,DAP DECIMAL(18,2)  ,MASTERPRODUCTATTRIUBUTEID BIGINT  ,ATTRIBUTETITLE VARCHAR( 200)               
,ATTRIBUTEVALUE VARCHAR( 200)  ,KEYFEATURES VARCHAR( 2000)  ,RATINGSTAR INT ,MAINCATEGORYID BIGINT  ,SUBCATEGORYID BIGINT  ,CATEGORYID BIGINT, DEALSIDS VARCHAR(100),              
CREATEDDATE timestamp,MODIFYDATE timestamp,REPLACEMENTDAY INT,PROCUREMENTSLA INT,              
CASHONDELIVERY boolean,SHIPPINGCHARGES DECIMAL(18,2),STOCKIN INT,STOCKOUT INT ,STOCKNET INT ,ISOUTOFSTOCK boolean,            
BV DECIMAL(18,2),ActivationPV Decimal(10,2),PV DECIMAL(18,2),CASHBACK DECIMAL(18,8),INCLUDINGTAX DECIMAL(18,2),PrSKUCODE Varchar(100),ACTIVATIONPV_PER DECIMAL(10,8)) ON COMMIT DROP;
  SELECT COUNT(rowno) INTO v_totalcount FROM tmp_tempsearching WHERE rowno IN (SELECT MIN(rowno) FROM tmp_tempsearching GROUP BY producttitle);
  IF (v_storeid = 0) THEN
  INSERT INTO tmp_temp SELECT v_totalcount AS totalcount, * FROM tmp_tempsearching WHERE rowno IN (SELECT MIN(rowno) FROM tmp_tempsearching GROUP BY mprid) ORDER BY (CASE WHEN subcategoryid = v_subcatid THEN 0 END) DESC NULLS LAST;
  SELECT COUNT(rownumber) INTO v_currentcount FROM tmp_temp WHERE rownumber BETWEEN v_minindex AND v_maxindex;
  RETURN QUERY SELECT v_currentcount AS currentcount, * FROM tmp_temp WHERE rownumber BETWEEN v_minindex AND v_maxindex;
  ELSE
