--
-- Name: ims_usp_product_searching_bak(integer, integer, integer, character varying, text, integer, integer, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.ims_usp_product_searching_bak(v_maincatid integer DEFAULT 0, v_catid integer DEFAULT 0, v_subcatid integer DEFAULT 0, v_sorting character varying DEFAULT ''::character varying, v_querystring text DEFAULT ''::text, v_pageno integer DEFAULT 2, v_noofrows integer DEFAULT 10, v_totalcount integer DEFAULT 0) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_minindex INT;
  v_maxindex INT;
  v_mindiscount DECIMAL(18,2);
  v_maxdiscount DECIMAL(18,2);
  v_minprice DECIMAL(18,2);
  v_maxprice DECIMAL(18,2);
  v_isoutofstock boolean;
  v_cnt INT;
  v_cnt1 INT;
  v_countexists INT;
  v_attributename VARCHAR(50);
  v_value VARCHAR(50);
  v_attributevalue VARCHAR(100);
  v_title VARCHAR(100);
  v_returnmpid text;
BEGIN
  BEGIN
  v_mindiscount := NULL;
  v_maxdiscount := NULL;
  v_minprice := NULL;
  v_maxprice := NULL;
  v_isoutofstock := NULL;
  v_cnt := 0;
  v_cnt1 := 0;
  v_countexists := 0;
  v_attributename := '';
  v_value := '';
  v_attributevalue := '';
  v_title := NULL;
  v_minindex := (v_pageno - 1) * v_noofrows + 1;
  v_maxindex := v_pageno * v_noofrows;
  RAISE NOTICE '%', 1;
  IF (COALESCE(v_querystring, '') <> '') THEN
  DROP TABLE IF EXISTS tmp_tempp;
  CREATE TEMP TABLE tmp_tempp (ROWNO BIGINT  ,ATTRIBUTENAME VARCHAR( 100)  ,ATTRIBUTEVALUE VARCHAR( 100)  ,VALUE VARCHAR( 100)) ON COMMIT DROP;
  INSERT INTO tmp_tempp SELECT ROW_NUMBER() OVER (ORDER BY value NULLS FIRST) AS rowno, LEFT(CAST(value AS TEXT), POSITION('=' IN value) - 1) AS attributename, SUBSTRING(value FROM POSITION('=' IN value) + 1 FOR LENGTH(CAST(value AS TEXT))) AS attributevalue, value FROM SPLITSTRINGBYCUSTOMSYMBOL1(v_querystring, '&');
  SELECT COUNT(1) INTO v_cnt FROM tmp_tempp;
  v_cnt1 := 1;
  v_countexists := 1;
  v_querystring := '';
  WHILE (v_cnt1 <= v_cnt) LOOP
  SELECT attributename, attributevalue, value INTO v_attributename, v_attributevalue, v_value FROM tmp_tempp WHERE rowno = v_cnt1;
  IF (v_attributename = 'PAGE') THEN
  SELECT value INTO v_pageno FROM SPLITSTRINGBYCUSTOMSYMBOL1(REPLACE(v_attributevalue, '-', '_'), '_');
  END IF;
  IF (v_attributename = 'CATEGORY' AND v_attributevalue = 'ALL') THEN
  v_maincatid := 0;
  v_catid := 0;
  v_subcatid := 0;
  END IF;
  IF (v_attributename = 'DISCOUNT') THEN
  SELECT CAST(MIN(CAST(value AS INT)) AS DECIMAL(18, 0)), CAST(MAX(CAST(value AS INT)) AS DECIMAL(18, 0)) INTO v_mindiscount, v_maxdiscount FROM SPLITSTRINGBYCUSTOMSYMBOL1(REPLACE(v_attributevalue, '-', '_'), '_');
  END IF;
  IF (v_attributename = 'PRICE') THEN
  SELECT CAST(MIN(CAST(value AS INT)) AS DECIMAL(18, 0)), CAST(MAX(CAST(value AS INT)) AS DECIMAL(18, 0)) INTO v_minprice, v_maxprice FROM SPLITSTRINGBYCUSTOMSYMBOL1(REPLACE(v_attributevalue, '-', '_'), '_');
  END IF;
  IF (v_attributename = 'ISOUT') THEN
  SELECT CAST(value AS BIT) INTO v_isoutofstock FROM SPLITSTRINGBYCUSTOMSYMBOL1(REPLACE(v_attributevalue, '-', '_'), '_');
  END IF;
  IF (v_attributename = 'Title') THEN
  SELECT CAST(value AS VARCHAR(50)) INTO v_title FROM SPLITSTRINGBYCUSTOMSYMBOL1(REPLACE(v_attributevalue, '-', '_'), '_');
  END IF;
  IF (v_attributename = 'PRICEASC' OR v_attributename = 'PRICEDESC') THEN
  SELECT CAST(value AS VARCHAR(50)) INTO v_sorting FROM SPLITSTRINGBYCUSTOMSYMBOL1(REPLACE(v_attributevalue, '-', '_'), '_');
  END IF;
  IF (v_attributename <> 'PRICE' AND v_attributename <> 'DISCOUNT' AND v_attributename <> 'ISOUT' AND v_attributename <> 'TITLE' AND v_attributename <> 'PAGE' AND v_attributename <> 'CATEGORY') THEN
  RAISE NOTICE '%', 'Actual Query String';
  v_querystring := v_querystring || '&' || v_value;
  END IF;
  RAISE NOTICE '%', 6;
  v_cnt1 := v_cnt1 + 1;
  END LOOP;
  DROP TABLE IF EXISTS tmp_tempp;
  v_returnmpid := '';
  SELECT v_returnmpid INTO v_returnmpid FROM dbo.ims_usp_getmpidfromquerystring(v_querystring => v_querystring, v_returnmpid => v_returnmpid);
  END IF;
  SELECT CASE WHEN COALESCE(v_maxdiscount, 0) = 0 THEN MAX(discountpercentage) ELSE v_maxdiscount END, CASE WHEN COALESCE(v_mindiscount, 0) = 0 THEN MIN(discountpercentage) ELSE v_mindiscount END, CASE WHEN COALESCE(v_minprice, 0) = 0 THEN MIN(dap) ELSE v_minprice END, CASE WHEN COALESCE(v_maxprice, 0) = 0 THEN MAX(dap) ELSE v_maxprice END INTO v_maxdiscount, v_mindiscount, v_minprice, v_maxprice FROM ims_subproduct;
  DROP TABLE IF EXISTS tmp_tempsearching;
  CREATE TEMP TABLE tmp_tempsearching (ROWNO BIGINT  ,MPRID BIGINT  ,PRODUCTCODE VARCHAR( 50)  ,PRODUCTTITLE VARCHAR( 300)  
,SHOTDESCRIPTION VARCHAR( 2000)  ,FULLDESCRIPTION text ,SPRID BIGINT  ,PRODUCTIMAGES VARCHAR( 1000)  
,DISCOUNTPERCENTAGE DECIMAL ,SELLMRP DECIMAL ,DAP DECIMAL  ,MASTERPRODUCTATTRIUBUTEID BIGINT  ,ATTRIBUTETITLE VARCHAR( 200) 
,ATTRIBUTEVALUE VARCHAR( 200)  ,KEYFEATURES VARCHAR( 2000)  ,RATINGSTAR INT ,MAINCATEGORYID BIGINT  ,SUBCATEGORYID BIGINT  ,CATEGORYID BIGINT, DEALSIDS VARCHAR(100),
CREATEDDATE timestamp,MODIFYDATE timestamp,REPLACEMENTDAY INT,PROCUREMENTSLA INT,
CASHONDELIVERY boolean,SHIPPINGCHARGES DECIMAL(18,2),STOCKIN INT,STOCKOUT INT ,STOCKNET INT ,ISOUTOFSTOCK boolean,BV decimal(18,2),PV decimal(18,2)) ON COMMIT DROP;
  IF (v_sorting = 'PRICEASC') THEN
  IF (v_querystring = '') THEN
  INSERT INTO tmp_tempsearching SELECT ROW_NUMBER() OVER (ORDER BY dap ASC NULLS FIRST) AS rowno, mprid, productcode, producttitle, shotdescription, fulldescription, sprid, productimages, discountpercentage, sellmrp, dap, masterproductattriubuteid, attributetitle, attributevalue, keyfeatures, CAST(dbo.FUN_GETRATINGOFSUBPRODUCT(sprid) AS INT) AS ratingstar, maincategoryid, subcategoryid, catid, dealsids, createddate, modifydate, replacementday, procurementsla, cashondelivery, shippingcharges, stockin, stockout, stocknet, isoutofstock, bv, pv FROM ims_view_allproductdetail WHERE (v_maincatid = 0 OR maincategoryid = v_maincatid) AND (v_catid = 0 OR catid = v_catid) AND (v_subcatid = 0 OR subcategoryid = v_subcatid) AND (v_title IS NULL OR producttitle LIKE '%' || v_title || '%') AND (discountpercentage BETWEEN v_mindiscount AND v_maxdiscount) AND (dap BETWEEN v_minprice AND v_maxprice) AND (v_isoutofstock IS NULL OR isoutofstock = v_isoutofstock) ORDER BY GEN_RANDOM_UUID() NULLS FIRST;
  ELSE
  INSERT INTO tmp_tempsearching SELECT ROW_NUMBER() OVER (ORDER BY dap ASC NULLS FIRST) AS rowno, mprid, productcode, producttitle, shotdescription, fulldescription, sprid, productimages, discountpercentage, sellmrp, dap, masterproductattriubuteid, attributetitle, attributevalue, keyfeatures, CAST(dbo.FUN_GETRATINGOFSUBPRODUCT(sprid) AS INT) AS ratingstar, maincategoryid, subcategoryid, catid, dealsids, createddate, modifydate, replacementday, procurementsla, cashondelivery, shippingcharges, stockin, stockout, stocknet, isoutofstock, bv, pv FROM ims_view_allproductdetail WHERE (v_maincatid = 0 OR maincategoryid = v_maincatid) AND (v_catid = 0 OR catid = v_catid) AND (v_subcatid = 0 OR subcategoryid = v_subcatid) AND (v_title IS NULL OR producttitle LIKE '%' || v_title || '%') AND (masterproductattriubuteid IN (SELECT * FROM dbo.SPLITSTRINGBYCUSTOMSYMBOL1(v_returnmpid, ','))) AND (discountpercentage BETWEEN v_mindiscount AND v_maxdiscount) AND (dap BETWEEN v_minprice AND v_maxprice) AND (v_isoutofstock IS NULL OR isoutofstock = v_isoutofstock) ORDER BY GEN_RANDOM_UUID() NULLS FIRST;
  END IF;
  ELSE
