--

CREATE FUNCTION dbo.ims_usp_product_searching_mobile(v_maincatid integer DEFAULT 1002, v_catid integer DEFAULT 1002, v_subcatid integer DEFAULT 1004, v_sorting character varying DEFAULT ''::character varying, v_querystring text DEFAULT ''::text, v_pageno integer DEFAULT 1, v_noofrows integer DEFAULT 100, INOUT v_totalcount integer DEFAULT 0, v_did integer DEFAULT 8, v_uidno character varying DEFAULT ''::character varying, v_clid integer DEFAULT 0, v_sprid character varying DEFAULT ''::character varying, v_mindiscont integer DEFAULT 0, v_maxdiscount integer DEFAULT 0, v_minprice numeric DEFAULT 0, v_maxprice numeric DEFAULT 0, v_priceorder character varying DEFAULT ''::character varying, v_discountorder character varying DEFAULT ''::character varying) RETURNS integer
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_dynamicurl varchar(100);
  v_merchantproductlargeimage varchar(250);
  v_orderbyset varchar(100);
  v_query varchar(4000);
  v_getcount int;
BEGIN
  BEGIN
  v_dynamicurl := '';
  v_merchantproductlargeimage := '';
  v_orderbyset := 'NEWID()';
  v_query := '';
  v_getcount := 0;
  SELECT merchantimagepath, merchantproductlargeimage INTO v_dynamicurl, v_merchantproductlargeimage FROM tbl_company;
  IF (v_priceorder = 'priceasc') THEN
  v_orderbyset := 'DAP asc';
  ELSE
  IF (v_priceorder = 'pricedesc') THEN
  v_orderbyset := 'DAP desc';
  ELSE
  IF (v_discountorder = 'discountasc') THEN
  v_orderbyset := 'DISCOUNTPERCENTAGE asc';
  ELSE
  IF (v_discountorder = 'discountdesc') THEN
  v_orderbyset := 'DISCOUNTPERCENTAGE desc';
  ELSE
  v_orderbyset := 'NEWID()';
  END IF;
  END IF;
  END IF;
  END IF;
  IF (v_querystring = '') THEN
  IF (v_catid > 0 AND v_subcatid > 0) THEN
  DROP TABLE IF EXISTS tmp_trendingproductsdata;
  CREATE TEMP TABLE tmp_trendingproductsdata ON COMMIT DROP AS SELECT DISTINCT ROW_NUMBER() OVER (ORDER BY pm.mprid NULLS FIRST) AS rowno, pm.productcode, pm.maincategoryid, pm.subcategoryid, pm.producttitle, pm.catid, pms.sprid, pms.subprcode, pms.isoutofstock, pms.productimages, pms.shippingcharges, pms.discountpercentage, pms.sellmrp, pms.dap, pms.createddate, COALESCE(pms.cashondelivery, 0) AS cashondelivery, pa.mpaid AS masterproductattriubuteid, COALESCE(dcs.bv, 0) AS bv, COALESCE(dcs.cashback, 0) AS cashback FROM ims_masterproduct AS pm LEFT OUTER JOIN ims_subproduct AS pms ON pms.mprid = pm.mprid LEFT OUTER JOIN ims_masterproductattribute AS pa ON pa.sprid = pms.sprid LEFT OUTER JOIN tbl_category AS c ON pa.catid = c.catid LEFT OUTER JOIN portal_login AS br ON br.plid = pm.branchid LEFT OUTER JOIN tbl_sub_category AS tsb ON pm.subcategoryid = tsb.subcatid LEFT OUTER JOIN tbl_distributor_commission_structure AS dcs ON dcs.subsubcatid = tsb.subcatid AND dcs.did = v_did WHERE br.active = 1 AND pms.isactive = 1 AND pms.isverified = 1 AND br.status = 1 AND COALESCE(isverified, 0) = 1 AND (pm.maincategoryid = v_maincatid AND pm.catid = v_catid AND pm.subcategoryid = v_subcatid);
  SELECT COALESCE(COUNT(1), 0) INTO v_getcount FROM tmp_trendingproductsdata AS tm WHERE rowno IN (SELECT MIN(rowno) FROM tmp_trendingproductsdata GROUP BY producttitle);
  IF (v_getcount < 20) THEN
  PERFORM dbo.usp_getrelatedlist(v_maincatid => v_maincatid, v_catid => v_catid, v_subcatid => v_subcatid, v_did => v_did);
  END IF;
  IF (v_mindiscont > 0 AND v_maxdiscount > 0 AND v_minprice > 0 AND v_maxprice > 0) THEN
  v_query := 'SELECT top 50 (select case when isnull(count(1),0) >0 then 1 else 0 end  from tbl_WishList 
			 where sprid=tm.SPRID and loginid=' || CAST(v_clid AS VARCHAR(10)) || ' and status=1) as wishcount,''' || v_dynamicurl || ''' as BaseURL,* FROM #TRENDINGPRODUCTSDATA tm   
			 where ROWNO In(Select MIN(ROWNO) From #TRENDINGPRODUCTSDATA Group By PRODUCTTITLE)  
			 AND (tm.DISCOUNTPERCENTAGE BETWEEN ' || v_mindiscont || ' AND ' || v_maxdiscount || ')
			 AND (tm.DAP BETWEEN ' || v_minprice || ' AND ' || v_maxprice || ') ORDER BY ' || v_orderbyset || '';
  ELSE
  IF (v_mindiscont > 0 AND v_maxdiscount > 0 AND v_minprice = 0 AND v_maxprice = 0) THEN
  v_query := 'SELECT top 50 (select case when isnull(count(1),0) >0 then 1 else 0 end  from tbl_WishList 
			 where sprid=tm.SPRID and loginid=' || CAST(v_clid AS VARCHAR(10)) || ' and status=1) as wishcount,''' || v_dynamicurl || ''' as BaseURL,* FROM #TRENDINGPRODUCTSDATA tm   
			 where ROWNO In(Select MIN(ROWNO) From #TRENDINGPRODUCTSDATA Group By PRODUCTTITLE)
			  AND (tm.DISCOUNTPERCENTAGE BETWEEN ' || v_mindiscont || ' AND ' || v_maxdiscount || ') ORDER BY ' || v_orderbyset || '';
  ELSE
  IF (v_mindiscont = 0 AND v_maxdiscount = 0 AND v_minprice > 0 AND v_maxprice > 0) THEN
  v_query := 'SELECT top 50 (select case when isnull(count(1),0) >0 then 1 else 0 end  from tbl_WishList 
			 where sprid=tm.SPRID and loginid=' || CAST(v_clid AS VARCHAR(10)) || ' and status=1) as wishcount,''' || v_dynamicurl || ''' as BaseURL,* FROM #TRENDINGPRODUCTSDATA tm   
			 where ROWNO In(Select MIN(ROWNO) From #TRENDINGPRODUCTSDATA Group By PRODUCTTITLE) 
			  AND (tm.DAP BETWEEN ' || v_minprice || ' AND ' || v_maxprice || ') ORDER BY ' || v_orderbyset || '';
  ELSE
  v_query := 'SELECT top 50 (select case when isnull(count(1),0) >0 then 1 else 0 end  from tbl_WishList 
			 where sprid=tm.SPRID and loginid=' || CAST(v_clid AS VARCHAR(10)) || ' and status=1) as wishcount,''' || v_dynamicurl || ''' as BaseURL,* FROM #TRENDINGPRODUCTSDATA tm   
			 where ROWNO In(Select MIN(ROWNO) From #TRENDINGPRODUCTSDATA Group By PRODUCTTITLE) ORDER BY ' || v_orderbyset || '';
  END IF;
  END IF;
  END IF;
  RAISE NOTICE '%', v_query;
  EXECUTE v_query;
  DROP TABLE IF EXISTS tmp_trendingproductsdata;
  ELSE
  DROP TABLE IF EXISTS tmp_trendingproductsdata1;
  CREATE TEMP TABLE tmp_trendingproductsdata1 ON COMMIT DROP AS SELECT DISTINCT ROW_NUMBER() OVER (ORDER BY pm.mprid NULLS FIRST) AS rowno, pm.productcode, pm.maincategoryid, pm.subcategoryid, pm.producttitle, pm.catid, pms.sprid, pms.subprcode, pms.isoutofstock, pms.productimages, pms.shippingcharges, pms.discountpercentage, pms.sellmrp, pms.dap, pms.createddate, COALESCE(pms.cashondelivery, 0) AS cashondelivery, pa.mpaid AS masterproductattriubuteid, COALESCE(dcs.bv, 0) AS bv, COALESCE(dcs.cashback, 0) AS cashback FROM ims_masterproduct AS pm LEFT OUTER JOIN ims_subproduct AS pms ON pms.mprid = pm.mprid LEFT OUTER JOIN ims_masterproductattribute AS pa ON pa.sprid = pms.sprid LEFT OUTER JOIN tbl_category AS c ON pa.catid = c.catid LEFT OUTER JOIN portal_login AS br ON br.plid = pm.branchid LEFT OUTER JOIN tbl_sub_category AS tsb ON pm.subcategoryid = tsb.subcatid LEFT OUTER JOIN tbl_distributor_commission_structure AS dcs ON dcs.subsubcatid = tsb.subcatid AND dcs.did = v_did WHERE br.active = 1 AND pms.isactive = 1 AND pms.isverified = 1 AND br.status = 1 AND COALESCE(isverified, 0) = 1 AND (pm.maincategoryid = v_maincatid OR pm.catid = v_catid OR pm.subcategoryid = v_subcatid);
  IF (v_mindiscont > 0 AND v_maxdiscount > 0 AND v_minprice > 0 AND v_maxprice > 0) THEN
  v_query := 'SELECT top 50 (select case when isnull(count(1),0) >0 then 1 else 0 end  from tbl_WishList 
			 where sprid=tm.SPRID and loginid=' || CAST(v_clid AS VARCHAR(10)) || ' and status=1) as wishcount,''' || v_dynamicurl || ''' as BaseURL,* FROM #TRENDINGPRODUCTSDATA1 tm   
			 where ROWNO In(Select MIN(ROWNO) From #TRENDINGPRODUCTSDATA1 Group By PRODUCTTITLE)  
			 AND (tm.DISCOUNTPERCENTAGE BETWEEN ' || v_mindiscont || ' AND ' || v_maxdiscount || ')
			 AND (tm.DAP BETWEEN ' || v_minprice || ' AND ' || v_maxprice || ') ORDER BY ' || v_orderbyset || '';
  ELSE
  IF (v_mindiscont > 0 AND v_maxdiscount > 0 AND v_minprice = 0 AND v_maxprice = 0) THEN
  v_query := 'SELECT top 50 (select case when isnull(count(1),0) >0 then 1 else 0 end  from tbl_WishList 
			where sprid=tm.SPRID and loginid=' || CAST(v_clid AS VARCHAR(10)) || ' and status=1) as wishcount,''' || v_dynamicurl || '''  as BaseURL,* FROM #TRENDINGPRODUCTSDATA1 tm   
			 where ROWNO In(Select MIN(ROWNO) From #TRENDINGPRODUCTSDATA1 Group By PRODUCTTITLE)
			  AND (tm.DISCOUNTPERCENTAGE BETWEEN ' || v_mindiscont || ' AND ' || v_maxdiscount || ') ORDER BY ' || v_orderbyset || '';
  ELSE
  IF (v_mindiscont = 0 AND v_maxdiscount = 0 AND v_minprice > 0 AND v_maxprice > 0) THEN
  v_query := 'SELECT top 50 (select case when isnull(count(1),0) >0 then 1 else 0 end  from tbl_WishList 
			where sprid=tm.SPRID and loginid=' || CAST(v_clid AS VARCHAR(10)) || ' and status=1) as wishcount,''' || v_dynamicurl || ''' as BaseURL,* FROM #TRENDINGPRODUCTSDATA1 tm   
			 where ROWNO In(Select MIN(ROWNO) From #TRENDINGPRODUCTSDATA1 Group By PRODUCTTITLE) 
			  AND (tm.DAP BETWEEN ' || v_minprice || ' AND ' || v_maxprice || ') ORDER BY ' || v_orderbyset || '';
  ELSE
  v_query := 'SELECT top 50 (select case when isnull(count(1),0) >0 then 1 else 0 end  from tbl_WishList 
			 where sprid=tm.SPRID and loginid=' || CAST(v_clid AS VARCHAR(10)) || ' and status=1) as wishcount,''' || v_dynamicurl || ''' as BaseURL,* FROM #TRENDINGPRODUCTSDATA1 tm   
			 where ROWNO In(Select MIN(ROWNO) From #TRENDINGPRODUCTSDATA1 Group By PRODUCTTITLE) ORDER BY ' || v_orderbyset || '';
  END IF;
  END IF;
  END IF;
  RAISE NOTICE '%', v_query;
  EXECUTE v_query;
  END IF;
  ELSE
  IF (v_querystring <> '') THEN
  DROP TABLE IF EXISTS tmp_trendingproductsdata11;
  CREATE TEMP TABLE tmp_trendingproductsdata11 ON COMMIT DROP AS SELECT DISTINCT ROW_NUMBER() OVER (ORDER BY pm.mprid NULLS FIRST) AS rowno, pm.productcode, pm.maincategoryid, pm.subcategoryid, pm.producttitle, pm.catid, pms.sprid, pms.subprcode, pms.isoutofstock, pms.productimages, pms.shippingcharges, pms.discountpercentage, pms.sellmrp, pms.dap, pms.createddate, COALESCE(pms.cashondelivery, 0) AS cashondelivery, pa.mpaid AS masterproductattriubuteid, COALESCE(dcs.bv, 0) AS bv, COALESCE(dcs.cashback, 0) AS cashback FROM ims_masterproduct AS pm LEFT OUTER JOIN ims_subproduct AS pms ON pms.mprid = pm.mprid LEFT OUTER JOIN ims_masterproductattribute AS pa ON pa.sprid = pms.sprid LEFT OUTER JOIN tbl_category AS c ON pa.catid = c.catid LEFT OUTER JOIN portal_login AS br ON br.plid = pm.branchid LEFT OUTER JOIN tbl_sub_category AS tsb ON pm.subcategoryid = tsb.subcatid LEFT OUTER JOIN tbl_distributor_commission_structure AS dcs ON dcs.subsubcatid = tsb.subcatid AND dcs.did = v_did WHERE br.active = 1 AND pms.isactive = 1 AND pms.isverified = 1 AND br.status = 1 AND COALESCE(isverified, 0) = 1 AND (pm.maincategoryid = v_maincatid AND pm.catid = v_catid AND pm.subcategoryid = v_subcatid) AND pms.sprid IN (SELECT sprid FROM ims_masterproductattribute WHERE catid = v_catid AND subcatid = v_subcatid AND value IN ((SELECT * FROM dbo.SPLITSTRINGBYCUSTOMSYMBOL1(CAST(v_querystring AS VARCHAR(100)), ','))));
  IF (v_mindiscont > 0 AND v_maxdiscount > 0 AND v_minprice > 0 AND v_maxprice > 0) THEN
  v_query := 'SELECT top 50 (select case when isnull(count(1),0) >0 then 1 else 0 end  from tbl_WishList 
			where sprid=tm.SPRID and loginid=' || CAST(v_clid AS VARCHAR(10)) || ' and status=1) as wishcount,''' || v_dynamicurl || '''  as BaseURL,* FROM #TRENDINGPRODUCTSDATA11 tm   
			 where ROWNO In(Select MIN(ROWNO) From #TRENDINGPRODUCTSDATA11 Group By PRODUCTTITLE)  
			 AND (tm.DISCOUNTPERCENTAGE BETWEEN ' || v_mindiscont || ' AND ' || v_maxdiscount || ')
			 AND (tm.DAP BETWEEN ' || v_minprice || ' AND ' || v_maxprice || ') ORDER BY ' || v_orderbyset || '';
  ELSE
  IF (v_mindiscont > 0 AND v_maxdiscount > 0 AND v_minprice = 0 AND v_maxprice = 0) THEN
  v_query := 'SELECT top 50 (select case when isnull(count(1),0) >0 then 1 else 0 end  from tbl_WishList 
			 where sprid=tm.SPRID and loginid=' || CAST(v_clid AS VARCHAR(10)) || ' and status=1) as wishcount,''' || v_dynamicurl || '''  as BaseURL,* FROM #TRENDINGPRODUCTSDATA11 tm   
			 where ROWNO In(Select MIN(ROWNO) From #TRENDINGPRODUCTSDATA11 Group By PRODUCTTITLE)
			  AND (tm.DISCOUNTPERCENTAGE BETWEEN ' || v_mindiscont || ' AND ' || v_maxdiscount || ') ORDER BY ' || v_orderbyset || '';
  ELSE
  IF (v_mindiscont = 0 AND v_maxdiscount = 0 AND v_minprice > 0 AND v_maxprice > 0) THEN
  v_query := 'SELECT top 50 (select case when isnull(count(1),0) >0 then 1 else 0 end  from tbl_WishList 
			 where sprid=tm.SPRID and loginid=' || CAST(v_clid AS VARCHAR(10)) || ' and status=1) as wishcount,''' || v_dynamicurl || '''  as BaseURL,* FROM #TRENDINGPRODUCTSDATA11 tm   
			 where ROWNO In(Select MIN(ROWNO) From #TRENDINGPRODUCTSDATA11 Group By PRODUCTTITLE) 
			  AND (tm.DAP BETWEEN ' || v_minprice || ' AND ' || v_maxprice || ') ORDER BY ' || v_orderbyset || '';
  ELSE
  v_query := 'SELECT top 50 (select case when isnull(count(1),0) >0 then 1 else 0 end  from tbl_WishList 
			where sprid=tm.SPRID and loginid=' || CAST(v_clid AS VARCHAR(10)) || ' and status=1) as wishcount,''' || v_dynamicurl || '''  as BaseURL,* FROM #TRENDINGPRODUCTSDATA11 tm   
			 where ROWNO In(Select MIN(ROWNO) From #TRENDINGPRODUCTSDATA11 Group By PRODUCTTITLE) ORDER BY ' || v_orderbyset || '';
  END IF;
  END IF;
  END IF;
  RAISE NOTICE '%', v_query;
  EXECUTE v_query;
  DROP TABLE IF EXISTS tmp_trendingproductsdata11;
  ELSE
  DROP TABLE IF EXISTS tmp_trendingproductsdata3;
  CREATE TEMP TABLE tmp_trendingproductsdata3 ON COMMIT DROP AS SELECT DISTINCT ROW_NUMBER() OVER (ORDER BY pm.mprid NULLS FIRST) AS rowno, pm.productcode, pm.maincategoryid, pm.subcategoryid, pm.producttitle, pm.catid, pms.sprid, pms.subprcode, pms.isoutofstock, pms.productimages, pms.shippingcharges, pms.discountpercentage, pms.sellmrp, pms.dap, pms.createddate, COALESCE(pms.cashondelivery, 0) AS cashondelivery, pa.mpaid AS masterproductattriubuteid, COALESCE(dcs.bv, 0) AS bv, COALESCE(dcs.cashback, 0) AS cashback FROM ims_masterproduct AS pm LEFT OUTER JOIN ims_subproduct AS pms ON pms.mprid = pm.mprid LEFT OUTER JOIN ims_masterproductattribute AS pa ON pa.sprid = pms.sprid LEFT OUTER JOIN tbl_category AS c ON pa.catid = c.catid LEFT OUTER JOIN portal_login AS br ON br.plid = pm.branchid LEFT OUTER JOIN tbl_sub_category AS tsb ON pm.subcategoryid = tsb.subcatid LEFT OUTER JOIN tbl_distributor_commission_structure AS dcs ON dcs.subsubcatid = tsb.subcatid AND dcs.did = v_did WHERE br.active = 1 AND pms.isactive = 1 AND pms.isverified = 1 AND br.status = 1 AND COALESCE(isverified, 0) = 1 AND (pm.maincategoryid = v_maincatid OR pm.catid = v_catid OR pm.subcategoryid = v_subcatid);
  IF (v_mindiscont > 0 AND v_maxdiscount > 0 AND v_minprice > 0 AND v_maxprice > 0) THEN
  v_query := 'SELECT top 50 (select case when isnull(count(1),0) >0 then 1 else 0 end  from tbl_WishList 
			 where sprid=tm.SPRID and loginid=' || CAST(v_clid AS VARCHAR(10)) || ' and status=1) as wishcount,''' || v_dynamicurl || ''' as BaseURL,* FROM #TRENDINGPRODUCTSDATA3 tm   
			 where ROWNO In(Select MIN(ROWNO) From #TRENDINGPRODUCTSDATA3 Group By PRODUCTTITLE)  
			 AND (tm.DISCOUNTPERCENTAGE BETWEEN ' || v_mindiscont || ' AND ' || v_maxdiscount || ')
			 AND (tm.DAP BETWEEN ' || v_minprice || ' AND ' || v_maxprice || ') ORDER BY ' || v_orderbyset || '';
  ELSE
  IF (v_mindiscont > 0 AND v_maxdiscount > 0 AND v_minprice = 0 AND v_maxprice = 0) THEN
  v_query := 'SELECT top 50 (select case when isnull(count(1),0) >0 then 1 else 0 end  from tbl_WishList 
			where sprid=tm.SPRID and loginid=' || CAST(v_clid AS VARCHAR(10)) || ' and status=1) as wishcount,''' || v_dynamicurl || '''  as BaseURL,* FROM #TRENDINGPRODUCTSDATA3 tm   
			 where ROWNO In(Select MIN(ROWNO) From #TRENDINGPRODUCTSDATA3 Group By PRODUCTTITLE)
