--
-- Name: ims_usp_product_searching_mobile_backup27122018(integer, integer, integer, character varying, text, integer, integer, integer, integer, character varying, integer, character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.ims_usp_product_searching_mobile_backup27122018(v_maincatid integer DEFAULT 1011, v_catid integer DEFAULT 1053, v_subcatid integer DEFAULT 1371, v_sorting character varying DEFAULT ''::character varying, v_querystring text DEFAULT 'color=black-grey_blue'::text, v_pageno integer DEFAULT 1, v_noofrows integer DEFAULT 100, v_totalcount integer DEFAULT 0, v_did integer DEFAULT 0, v_uidno character varying DEFAULT ''::character varying, v_clid integer DEFAULT 0, v_sprid character varying DEFAULT ''::character varying) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_minindex INT;
  v_maxindex INT;
  v_mindiscount DECIMAL(18,2);
  v_maxdiscount DECIMAL(18,2);
  v_minprice DECIMAL(18,2);
  v_maxprice DECIMAL(18,2);
  v_isoutofstock boolean;
  v_getdid int;
  v_cnt INT;
  v_cnt1 INT;
  v_countexists INT;
  v_attributename VARCHAR(50);
  v_value VARCHAR(50);
  v_attributevalue VARCHAR(100);
  v_title VARCHAR(100);
  v_dynamicurl varchar(100);
  v_merchantproductlargeimage varchar(250);
  v_dynamicurl1 varchar(100);
  v_returnmpid text;
BEGIN
  BEGIN
  v_mindiscount := NULL;
  v_maxdiscount := NULL;
  v_minprice := NULL;
  v_maxprice := NULL;
  v_isoutofstock := NULL;
  v_getdid := 0;
  v_cnt := 0;
  v_cnt1 := 0;
  v_countexists := 0;
  v_attributename := '';
  v_value := '';
  v_attributevalue := '';
  v_title := NULL;
  v_minindex := (v_pageno - 1) * v_noofrows + 1;
  v_maxindex := v_pageno * v_noofrows;
  SELECT did INTO v_getdid FROM tbl_customerlogin WHERE clid = v_clid;
  v_dynamicurl := '';
  v_merchantproductlargeimage := '';
  v_dynamicurl1 := '';
  SELECT merchantimagepath, merchantproductlargeimage INTO v_dynamicurl1, v_merchantproductlargeimage FROM tbl_company;
  IF (v_getdid > 0) THEN
  v_did := v_getdid;
  END IF;
  SELECT COALESCE(pmm.maincategoryid, 0), COALESCE(pmm.catid, 0), COALESCE(pmm.subcategoryid, 0) INTO v_maincatid, v_catid, v_subcatid FROM ims_masterproduct AS pmm INNER JOIN ims_subproduct AS pms ON pms.mprid = pmm.mprid INNER JOIN portal_login AS br ON br.plid = pmm.branchid WHERE CAST(pms.sprid AS VARCHAR(100)) = v_sprid;
  RAISE NOTICE '%', 1;
  IF (COALESCE(v_querystring, '') <> '') THEN
  DROP TABLE IF EXISTS tmp_tempp;
  CREATE TEMP TABLE tmp_tempp (ROWNO BIGINT  ,ATTRIBUTENAME VARCHAR( 100)  ,ATTRIBUTEVALUE VARCHAR( 100)  ,VALUE VARCHAR( 100)) ON COMMIT DROP;
  INSERT INTO tmp_tempp SELECT ROW_NUMBER() OVER (ORDER BY value NULLS FIRST) AS rowno, LEFT(CAST(value AS TEXT), POSITION('=' IN value) - 1) AS attributename, SUBSTRING(value FROM POSITION('=' IN value) + 1 FOR LENGTH(CAST(value AS TEXT))) AS attributevalue, value FROM SPLITSTRINGBYCUSTOMSYMBOL1(v_querystring, '&');
  SELECT COUNT(1) INTO v_cnt FROM tmp_tempp;
  v_cnt1 := 1;
  v_countexists := 1;
  v_querystring := '';
  WHILE (v_cnt1 <= v_cnt) LOOP
  SELECT attributename, attributevalue, value INTO v_attributename, v_attributevalue, v_value FROM tmp_tempp WHERE rowno = v_cnt1;
  IF (v_attributename = 'PAGE') THEN
  SELECT value INTO v_pageno FROM SPLITSTRINGBYCUSTOMSYMBOL1(REPLACE(v_attributevalue, '-', '_'), '_');
  END IF;
  IF (v_attributename = 'CATEGORY' AND v_attributevalue = 'ALL') THEN
  v_maincatid := 0;
  v_catid := 0;
  v_subcatid := 0;
  END IF;
  IF (v_attributename = 'DISCOUNT') THEN
  SELECT CAST(MIN(CAST(value AS INT)) AS DECIMAL(18, 0)), CAST(MAX(CAST(value AS INT)) AS DECIMAL(18, 0)) INTO v_mindiscount, v_maxdiscount FROM SPLITSTRINGBYCUSTOMSYMBOL1(REPLACE(v_attributevalue, '-', '_'), '_');
  END IF;
  IF (v_attributename = 'PRICE') THEN
  SELECT CAST(MIN(CAST(value AS INT)) AS DECIMAL(18, 0)), CAST(MAX(CAST(value AS INT)) AS DECIMAL(18, 0)) INTO v_minprice, v_maxprice FROM SPLITSTRINGBYCUSTOMSYMBOL1(REPLACE(v_attributevalue, '-', '_'), '_');
  END IF;
  IF (v_attributename = 'ISOUT') THEN
  SELECT CAST(value AS BIT) INTO v_isoutofstock FROM SPLITSTRINGBYCUSTOMSYMBOL1(REPLACE(v_attributevalue, '-', '_'), '_');
  END IF;
  IF (v_attributename = 'Title') THEN
  SELECT CAST(value AS VARCHAR(50)) INTO v_title FROM SPLITSTRINGBYCUSTOMSYMBOL1(REPLACE(v_attributevalue, '-', '_'), '_');
  END IF;
  IF (v_attributename = 'PRICEASC' OR v_attributename = 'PRICEDESC') THEN
  SELECT CAST(value AS VARCHAR(50)) INTO v_sorting FROM SPLITSTRINGBYCUSTOMSYMBOL1(REPLACE(v_attributevalue, '-', '_'), '_');
  END IF;
  IF (v_attributename <> 'PRICE' AND v_attributename <> 'DISCOUNT' AND v_attributename <> 'ISOUT' AND v_attributename <> 'TITLE' AND v_attributename <> 'PAGE' AND v_attributename <> 'CATEGORY') THEN
  RAISE NOTICE '%', 'Actual Query String';
  v_querystring := v_querystring || '&' || v_value;
  END IF;
  RAISE NOTICE '%', 6;
  v_cnt1 := v_cnt1 + 1;
  END LOOP;
  DROP TABLE IF EXISTS tmp_tempp;
  v_returnmpid := '';
  SELECT v_returnmpid INTO v_returnmpid FROM dbo.ims_usp_getmpidfromquerystring_mobile(v_querystring => v_querystring, v_returnmpid => v_returnmpid);
  END IF;
  SELECT CASE WHEN COALESCE(v_maxdiscount, 0) = 0 THEN MAX(discountpercentage) ELSE v_maxdiscount END, CASE WHEN COALESCE(v_mindiscount, 0) = 0 THEN MIN(discountpercentage) ELSE v_mindiscount END, CASE WHEN COALESCE(v_minprice, 0) = 0 THEN MIN(dap) ELSE v_minprice END, CASE WHEN COALESCE(v_maxprice, 0) = 0 THEN MAX(dap) ELSE v_maxprice END INTO v_maxdiscount, v_mindiscount, v_minprice, v_maxprice FROM ims_subproduct;
  DROP TABLE IF EXISTS tmp_tempsearching;
  CREATE TEMP TABLE tmp_tempsearching (ROWNO BIGINT  ,MPRID BIGINT  ,PRODUCTCODE VARCHAR( 50)  ,PRODUCTTITLE VARCHAR( 300)  
,SPRID BIGINT  , PRODUCTIMAGES VARCHAR( 1000)  
,DISCOUNTPERCENTAGE DECIMAL ,SELLMRP DECIMAL ,DAP DECIMAL  ,MAINCATEGORYID BIGINT  ,SUBCATEGORYID BIGINT  ,CATEGORYID BIGINT,
BV decimal(18,2),PV decimal(18,2),wishproduct int) ON COMMIT DROP;
  IF (v_sorting = 'PRICEASC') THEN
  IF (v_querystring = '') THEN
  IF (v_did > 0) THEN
  INSERT INTO tmp_tempsearching SELECT ROW_NUMBER() OVER (ORDER BY dap ASC NULLS FIRST) AS rowno, mprid, productcode, producttitle, vp.sprid, CASE WHEN POSITION('^' IN productimages) > 0 THEN (LEFT(CAST(v_dynamicurl || productimages AS TEXT), POSITION('^' IN v_dynamicurl || productimages) + 0)) ELSE v_dynamicurl || productimages || '^' END AS productimages, discountpercentage, sellmrp, dap, maincategoryid, subcategoryid, catid, COALESCE(dpw.bv, 0) AS bv, COALESCE(dpw.pv, 0) AS pv, (SELECT COALESCE(COUNT(1), 0) FROM tbl_wishlist WHERE sprid = vp.sprid AND regno = v_clid AND status = 1) AS wishproduct FROM ims_view_allproductdetail AS vp LEFT JOIN tbl_distributor_comm_productwise AS dpw ON dpw.sprid = vp.sprid AND did = v_did WHERE (v_maincatid = 0 OR maincategoryid = v_maincatid) AND (v_catid = 0 OR catid = v_catid) AND (v_subcatid = 0 OR subcategoryid = v_subcatid) AND (v_title IS NULL OR producttitle LIKE '%' || v_title || '%') AND (discountpercentage BETWEEN v_mindiscount AND v_maxdiscount) AND (dap BETWEEN v_minprice AND v_maxprice) AND (v_isoutofstock IS NULL OR isoutofstock = v_isoutofstock) ORDER BY GEN_RANDOM_UUID() NULLS FIRST;
  ELSE
  INSERT INTO tmp_tempsearching SELECT ROW_NUMBER() OVER (ORDER BY dap ASC NULLS FIRST) AS rowno, mprid, productcode, producttitle, sprid, CASE WHEN POSITION('^' IN productimages) > 0 THEN (LEFT(CAST(v_dynamicurl || productimages AS TEXT), POSITION('^' IN v_dynamicurl || productimages) + 0)) ELSE v_dynamicurl || productimages || '^' END AS productimages, discountpercentage, sellmrp, dap, maincategoryid, subcategoryid, catid, bv, pv, (SELECT COALESCE(COUNT(1), 0) FROM tbl_wishlist WHERE sprid = sprid AND regno = v_clid AND status = 1) AS wishproduct FROM ims_view_allproductdetail WHERE (v_maincatid = 0 OR maincategoryid = v_maincatid) AND (v_catid = 0 OR catid = v_catid) AND (v_subcatid = 0 OR subcategoryid = v_subcatid) AND (v_title IS NULL OR producttitle LIKE '%' || v_title || '%') AND (discountpercentage BETWEEN v_mindiscount AND v_maxdiscount) AND (dap BETWEEN v_minprice AND v_maxprice) AND (v_isoutofstock IS NULL OR isoutofstock = v_isoutofstock) ORDER BY GEN_RANDOM_UUID() NULLS FIRST;
  END IF;
  ELSE
  IF (v_did > 0) THEN
  INSERT INTO tmp_tempsearching SELECT ROW_NUMBER() OVER (ORDER BY dap ASC NULLS FIRST) AS rowno, mprid, productcode, producttitle, vp.sprid, CASE WHEN POSITION('^' IN productimages) > 0 THEN (LEFT(CAST(v_dynamicurl || productimages AS TEXT), POSITION('^' IN v_dynamicurl || productimages) + 0)) ELSE v_dynamicurl || productimages || '^' END AS productimages, discountpercentage, sellmrp, dap, maincategoryid, subcategoryid, catid, COALESCE(dpw.bv, 0) AS bv, COALESCE(dpw.pv, 0) AS pv, (SELECT COALESCE(COUNT(1), 0) FROM tbl_wishlist WHERE sprid = vp.sprid AND regno = v_clid AND status = 1) AS wishproduct FROM ims_view_allproductdetail AS vp LEFT JOIN tbl_distributor_comm_productwise AS dpw ON dpw.sprid = vp.sprid AND did = v_did WHERE (v_maincatid = 0 OR maincategoryid = v_maincatid) AND (v_catid = 0 OR catid = v_catid) AND (v_subcatid = 0 OR subcategoryid = v_subcatid) AND (v_title IS NULL OR producttitle LIKE '%' || v_title || '%') AND (masterproductattriubuteid IN (SELECT * FROM dbo.SPLITSTRINGBYCUSTOMSYMBOL1(v_returnmpid, ','))) AND (discountpercentage BETWEEN v_mindiscount AND v_maxdiscount) AND (dap BETWEEN v_minprice AND v_maxprice) AND (v_isoutofstock IS NULL OR isoutofstock = v_isoutofstock) ORDER BY GEN_RANDOM_UUID() NULLS FIRST;
  ELSE
  INSERT INTO tmp_tempsearching SELECT ROW_NUMBER() OVER (ORDER BY dap ASC NULLS FIRST) AS rowno, mprid, productcode, producttitle, sprid, CASE WHEN POSITION('^' IN productimages) > 0 THEN (LEFT(CAST(v_dynamicurl || productimages AS TEXT), POSITION('^' IN v_dynamicurl || productimages) + 0)) ELSE v_dynamicurl || productimages || '^' END AS productimages, discountpercentage, sellmrp, dap, maincategoryid, subcategoryid, catid, bv, pv, (SELECT COALESCE(COUNT(1), 0) FROM tbl_wishlist WHERE sprid = sprid AND regno = v_clid AND status = 1) AS wishproduct FROM ims_view_allproductdetail WHERE (v_maincatid = 0 OR maincategoryid = v_maincatid) AND (v_catid = 0 OR catid = v_catid) AND (v_subcatid = 0 OR subcategoryid = v_subcatid) AND (v_title IS NULL OR producttitle LIKE '%' || v_title || '%') AND (masterproductattriubuteid IN (SELECT * FROM dbo.SPLITSTRINGBYCUSTOMSYMBOL1(v_returnmpid, ','))) AND (discountpercentage BETWEEN v_mindiscount AND v_maxdiscount) AND (dap BETWEEN v_minprice AND v_maxprice) AND (v_isoutofstock IS NULL OR isoutofstock = v_isoutofstock) ORDER BY GEN_RANDOM_UUID() NULLS FIRST;
  END IF;
  END IF;
  ELSE
  IF (v_sorting = 'PRICEDESC') THEN
  IF (v_querystring = '') THEN
  IF (v_did > 0) THEN
