  RETURN QUERY SELECT (SELECT CASE WHEN COALESCE(COUNT(1), 0) > 0 THEN 1 ELSE 0 END FROM tbl_wishlist WHERE sprid = tm.sprid AND loginid = v_clid AND status = 1) AS wishcount, v_dynamicurl1 AS baseurl, * FROM tmp_temp AS tm WHERE NOT sprid IN (v_sprid) AND rownumber BETWEEN v_minindex AND v_maxindex;
