CREATE FUNCTION dbo.ims_usp_product_searching_mobile_backup29122018(v_maincatid integer DEFAULT 1012, v_catid integer DEFAULT 1060, v_subcatid integer DEFAULT 1601, v_sorting character varying DEFAULT ''::character varying, v_querystring text DEFAULT 'color=black-grey_blue'::text, v_pageno integer DEFAULT 1, v_noofrows integer DEFAULT 100, v_totalcount integer DEFAULT 0, v_did integer DEFAULT 0, v_uidno character varying DEFAULT ''::character varying, v_clid integer DEFAULT 0, v_sprid character varying DEFAULT ''::character varying) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_dynamicurl varchar(100);
  v_merchantproductlargeimage varchar(250);
BEGIN
  BEGIN
  v_dynamicurl := '';
  v_merchantproductlargeimage := '';
  SELECT merchantimagepath, merchantproductlargeimage INTO v_dynamicurl, v_merchantproductlargeimage FROM tbl_company;
  DROP TABLE IF EXISTS tmp_trendingproductsdata;
  CREATE TEMP TABLE tmp_trendingproductsdata ON COMMIT DROP AS SELECT DISTINCT ROW_NUMBER() OVER (ORDER BY pm.mprid NULLS FIRST) AS rowno, pm.productcode, pm.maincategoryid, pm.subcategoryid, pm.producttitle, pm.catid, pms.sprid, pms.subprcode, pms.isoutofstock, pms.productimages, pms.shippingcharges, pms.discountpercentage, pms.sellmrp, pms.dap, pms.createddate, COALESCE(pms.cashondelivery, 0) AS cashondelivery, pa.mpaid AS masterproductattriubuteid, COALESCE(pms.bv, 0) AS bv, COALESCE(pms.pv, 0) AS pv FROM ims_masterproduct AS pm LEFT OUTER JOIN ims_subproduct AS pms ON pms.mprid = pm.mprid LEFT OUTER JOIN ims_masterproductattribute AS pa ON pa.sprid = pms.sprid LEFT OUTER JOIN tbl_category AS c ON pa.catid = c.catid LEFT OUTER JOIN portal_login AS br ON br.plid = pm.branchid WHERE br.active = 1 AND pms.isactive = 1 AND pms.isverified = 1 AND br.status = 1 AND COALESCE(isverified, 0) = 1 AND (pm.maincategoryid = v_maincatid AND pm.catid = v_catid AND pm.subcategoryid = v_subcatid);
  RETURN QUERY SELECT (SELECT CASE WHEN COALESCE(COUNT(1), 0) > 0 THEN 1 ELSE 0 END FROM tbl_wishlist WHERE sprid = tm.sprid AND loginid = v_clid AND status = 1) AS wishcount, v_dynamicurl AS baseurl, * FROM tmp_trendingproductsdata AS tm WHERE rowno IN (SELECT MIN(rowno) FROM tmp_trendingproductsdata GROUP BY producttitle) ORDER BY GEN_RANDOM_UUID() NULLS FIRST LIMIT 30;
  DROP TABLE IF EXISTS tmp_trendingproductsdata;
  v_totalcount := 10;
  -- SET option (removed)
  EXCEPTION WHEN OTHERS THEN
  v_totalcount := 0;
  END;
END;
$$;


