CREATE FUNCTION dbo.ims_usp_product_searching_relatedproducts(v_maincatid integer DEFAULT 1011, v_catid integer DEFAULT 0, v_subcatid integer DEFAULT 0, v_sorting character varying DEFAULT ''::character varying, v_querystring text DEFAULT ''::text, v_pageno integer DEFAULT 1, v_noofrows integer DEFAULT 30, v_totalcount integer DEFAULT 0, v_did integer DEFAULT 0) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_minindex INT;
  v_maxindex INT;
  v_mindiscount DECIMAL(18,2);
  v_maxdiscount DECIMAL(18,2);
  v_minprice DECIMAL(18,2);
  v_maxprice DECIMAL(18,2);
  v_isoutofstock boolean;
  v_cnt INT;
  v_cnt1 INT;
  v_countexists INT;
  v_attributename VARCHAR(50);
  v_value VARCHAR(50);
  v_attributevalue VARCHAR(100);
  v_title VARCHAR(100);
BEGIN
  BEGIN
  v_mindiscount := NULL;
  v_maxdiscount := NULL;
  v_minprice := NULL;
  v_maxprice := NULL;
  v_isoutofstock := NULL;
  v_cnt := 0;
  v_cnt1 := 0;
  v_countexists := 0;
  v_attributename := '';
  v_value := '';
  v_attributevalue := '';
  v_title := NULL;
  v_minindex := (v_pageno - 1) * v_noofrows + 1;
  v_maxindex := v_pageno * v_noofrows;
  DROP TABLE IF EXISTS tmp_tempsearching;
  CREATE TEMP TABLE tmp_tempsearching (ROWNO BIGINT  ,MPRID BIGINT  ,PRODUCTCODE VARCHAR( 50)  ,PRODUCTTITLE VARCHAR( 300)          
,SHOTDESCRIPTION VARCHAR( 2000)  ,FULLDESCRIPTION text ,SPRID BIGINT  ,PRODUCTIMAGES VARCHAR( 1000)          
,DISCOUNTPERCENTAGE DECIMAL ,SELLMRP DECIMAL ,DAP DECIMAL  ,MASTERPRODUCTATTRIUBUTEID BIGINT  ,ATTRIBUTETITLE VARCHAR( 200)         
,ATTRIBUTEVALUE VARCHAR( 200)  ,KEYFEATURES VARCHAR( 2000)  ,RATINGSTAR INT ,MAINCATEGORYID BIGINT  ,SUBCATEGORYID BIGINT  ,CATEGORYID BIGINT, DEALSIDS VARCHAR(100),        
CREATEDDATE timestamp,MODIFYDATE timestamp,REPLACEMENTDAY INT,PROCUREMENTSLA INT,        
CASHONDELIVERY boolean,SHIPPINGCHARGES DECIMAL(18,2),STOCKIN INT,STOCKOUT INT ,STOCKNET INT ,      
ISOUTOFSTOCK boolean,BV DECIMAL(18,2),ActivationPV DECIMAL(18,2),PV DECIMAL(18,2),INCLUDINGTAX DECIMAL(18,2),PrSKUCODE Varchar(100),ACTIVATIONPV_PER DECIMAL(18,8)) ON COMMIT DROP;
  IF (v_querystring = '') THEN
  IF (v_did > 0) THEN
  INSERT INTO tmp_tempsearching SELECT ROW_NUMBER() OVER (ORDER BY mprid NULLS FIRST) AS rowno, mprid, productcode, producttitle, shotdescription, fulldescription, vp.sprid, productimages, discountpercentage, sellmrp, dap, masterproductattriubuteid, attributetitle, attributevalue, keyfeatures, CAST(dbo.FUN_GETRATINGOFSUBPRODUCT(vp.sprid) AS INT) AS ratingstar, maincategoryid, subcategoryid, catid, dealsids, createddate, modifydate, replacementday, procurementsla, cashondelivery, shippingcharges, stockin, stockout, stocknet, isoutofstock, COALESCE(vp.bv, 0) AS bv, COALESCE(vp.activationpv, 0) AS activationpv, COALESCE(vp.pv, 0) AS pv, COALESCE(includingtax, 0) AS includingtax, prskucode, vp.activationpv_per FROM ims_view_allproductdetail AS vp LEFT JOIN tbl_distributor_comm_productwise AS dpw ON dpw.sprid = vp.sprid AND did = v_did WHERE (v_maincatid = 0 OR maincategoryid = v_maincatid) AND (v_catid = 0 OR catid = v_catid) AND (v_subcatid = 0 OR subcategoryid <> v_subcatid);
  ELSE
  INSERT INTO tmp_tempsearching SELECT ROW_NUMBER() OVER (ORDER BY mprid NULLS FIRST) AS rowno, mprid, productcode, producttitle, shotdescription, fulldescription, sprid, productimages, discountpercentage, sellmrp, dap, masterproductattriubuteid, attributetitle, attributevalue, keyfeatures, CAST(dbo.FUN_GETRATINGOFSUBPRODUCT(sprid) AS INT) AS ratingstar, maincategoryid, subcategoryid, catid, dealsids, createddate, modifydate, replacementday, procurementsla, cashondelivery, shippingcharges, stockin, stockout, stocknet, isoutofstock, bv, activationpv, pv, COALESCE(includingtax, 0) AS includingtax, prskucode, activationpv_per FROM ims_view_allproductdetail WHERE (v_maincatid = 0 OR maincategoryid = v_maincatid) AND (v_catid = 0 OR catid = v_catid) AND (v_subcatid = 0 OR subcategoryid <> v_subcatid);
  END IF;
  END IF;
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp (TOTALCOUNT text,ROWNUMBER BIGINT GENERATED BY DEFAULT AS IDENTITY, ROWNO BIGINT  ,MPRID BIGINT  ,PRODUCTCODE VARCHAR( 50)  ,PRODUCTTITLE VARCHAR( 300)          
,SHOTDESCRIPTION VARCHAR( 2000)  ,FULLDESCRIPTION text ,SPRID BIGINT  ,PRODUCTIMAGES VARCHAR( 1000)          
,DISCOUNTPERCENTAGE DECIMAL ,SELLMRP DECIMAL ,DAP DECIMAL  ,MASTERPRODUCTATTRIUBUTEID BIGINT  ,ATTRIBUTETITLE VARCHAR( 200)         
,ATTRIBUTEVALUE VARCHAR( 200)  ,KEYFEATURES VARCHAR( 2000)  ,RATINGSTAR INT ,MAINCATEGORYID BIGINT  ,SUBCATEGORYID BIGINT  ,CATEGORYID BIGINT, DEALSIDS VARCHAR(100),        
CREATEDDATE timestamp,MODIFYDATE timestamp,REPLACEMENTDAY INT,PROCUREMENTSLA INT,        
CASHONDELIVERY boolean,SHIPPINGCHARGES DECIMAL(18,2),STOCKIN INT,STOCKOUT INT ,STOCKNET INT ,      
ISOUTOFSTOCK boolean,BV DECIMAL(18,2),ActivationPV DECIMAL(18,2),PV DECIMAL(18,2),INCLUDINGTAX DECIMAL(18,2),PrSKUCODE Varchar(100),ACTIVATIONPV_PER DECIMAL(10,2)) ON COMMIT DROP;
