CREATE FUNCTION dbo.ims_usp_product_searching_relatedproducts_mobile(v_maincatid integer DEFAULT 1004, v_catid integer DEFAULT 0, v_subcatid integer DEFAULT 0, v_sorting character varying DEFAULT ''::character varying, v_querystring text DEFAULT ''::text, v_pageno integer DEFAULT 1, v_noofrows integer DEFAULT 30, v_totalcount integer DEFAULT 0, v_did integer DEFAULT 8, v_clid integer DEFAULT 0) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_minindex INT;
  v_maxindex INT;
  v_mindiscount DECIMAL(18,2);
  v_maxdiscount DECIMAL(18,2);
  v_minprice DECIMAL(18,2);
  v_maxprice DECIMAL(18,2);
  v_isoutofstock boolean;
  v_cnt INT;
  v_cnt1 INT;
  v_countexists INT;
  v_attributename VARCHAR(50);
  v_value VARCHAR(50);
  v_attributevalue VARCHAR(100);
  v_title VARCHAR(100);
  v_dynamicurl varchar(100);
  v_merchantproductlargeimage varchar(250);
BEGIN
  BEGIN
  v_mindiscount := NULL;
  v_maxdiscount := NULL;
  v_minprice := NULL;
  v_maxprice := NULL;
  v_isoutofstock := NULL;
  v_cnt := 0;
  v_cnt1 := 0;
  v_countexists := 0;
  v_attributename := '';
  v_value := '';
  v_attributevalue := '';
  v_title := NULL;
  v_minindex := (v_pageno - 1) * v_noofrows + 1;
  v_maxindex := v_pageno * v_noofrows;
  v_dynamicurl := '';
  v_merchantproductlargeimage := '';
  SELECT merchantimagepath, merchantproductlargeimage INTO v_dynamicurl, v_merchantproductlargeimage FROM tbl_company;
  DROP TABLE IF EXISTS tmp_tempsearching;
  CREATE TEMP TABLE tmp_tempsearching (ROWNO BIGINT  ,ProductCode VARCHAR( 50)  ,ProductTitle VARCHAR( 300)  
,SPRID BIGINT  ,ProductImages VARCHAR( 1000)  
,DiscountPercentage DECIMAL ,SellMRP DECIMAL ,DAP DECIMAL,RatingStar INT ,MaincategoryID BIGINT,SubcategoryID BIGINT  ,CATID BIGINT,
CreateDate timestamp,ShippingCharges DECIMAL(18,2),IsoutofStock boolean,BV DECIMAL(18,2),Cashback DECIMAL(18,2)) ON COMMIT DROP;
  IF (v_querystring = '') THEN
  IF (v_did > 0) THEN
  INSERT INTO tmp_tempsearching SELECT ROW_NUMBER() OVER (ORDER BY mprid NULLS FIRST) AS rowno, productcode AS productcode, producttitle AS producttitle, vp.sprid, productimages AS productimages, discountpercentage AS discountpercentage, sellmrp AS sellmrp, dap, CAST(dbo.FUN_GETRATINGOFSUBPRODUCT(vp.sprid) AS INT) AS ratingstar, maincategoryid AS maincategoryid, vp.subcategoryid AS subcategoryid, vp.catid, vp.createddate AS createdate, shippingcharges AS shippingcharges, isoutofstock AS isoutofstock, COALESCE(dcs.bv, 0) AS bv, COALESCE(dcs.cashback, 0) AS cashback FROM ims_view_allproductdetail AS vp LEFT OUTER JOIN tbl_sub_category AS tsb ON vp.subcategoryid = tsb.subcatid LEFT OUTER JOIN tbl_distributor_commission_structure AS dcs ON dcs.subsubcatid = tsb.subcatid AND dcs.did = v_did WHERE (v_maincatid = 0 OR vp.maincategoryid = v_maincatid) AND (v_catid = 0 OR vp.catid = v_catid) AND (v_subcatid = 0 OR vp.subcategoryid <> v_subcatid);
  ELSE
  INSERT INTO tmp_tempsearching SELECT ROW_NUMBER() OVER (ORDER BY mprid NULLS FIRST) AS rowno, productcode AS productcode, producttitle AS producttitle, sprid, productimages AS productimages, discountpercentage AS discountpercentage, sellmrp AS sellmrp, dap, CAST(dbo.FUN_GETRATINGOFSUBPRODUCT(sprid) AS INT) AS ratingstar, maincategoryid AS maincategoryid, vp.subcategoryid AS subcategoryid, vp.catid, vp.createddate AS createdate, shippingcharges AS shippingcharges, isoutofstock AS isoutofstock, COALESCE(dcs.bv, 0) AS bv, COALESCE(dcs.cashback, 0) AS cashback FROM ims_view_allproductdetail AS vp LEFT OUTER JOIN tbl_sub_category AS tsb ON vp.subcategoryid = tsb.subcatid LEFT OUTER JOIN tbl_distributor_commission_structure AS dcs ON dcs.subsubcatid = tsb.subcatid AND dcs.did = v_did WHERE (v_maincatid = 0 OR vp.maincategoryid = v_maincatid) AND (v_catid = 0 OR vp.catid = v_catid) AND (v_subcatid = 0 OR vp.subcategoryid <> v_subcatid);
  END IF;
  END IF;
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp (TOTALCOUNT text,ROWNUMBER BIGINT GENERATED BY DEFAULT AS IDENTITY, ROWNO BIGINT  ,ProductCode VARCHAR( 50)  ,ProductTitle VARCHAR( 300)  
,SPRID BIGINT  ,ProductImages VARCHAR( 1000)  
,DiscountPercentage DECIMAL ,SellMRP DECIMAL ,DAP DECIMAL,RatingStar INT ,MaincategoryID BIGINT  ,SubcategoryID BIGINT  ,CATID BIGINT,
CreateDate timestamp,ShippingCharges DECIMAL(18,2),IsoutofStock boolean,BV DECIMAL(18,2),Cashback DECIMAL(18,2)) ON COMMIT DROP;
  SELECT COUNT(rowno) INTO v_totalcount FROM tmp_tempsearching WHERE rowno IN (SELECT MIN(rowno) FROM tmp_tempsearching GROUP BY producttitle);
  INSERT INTO tmp_temp SELECT v_totalcount AS totalcount, * FROM tmp_tempsearching WHERE rowno IN (SELECT MIN(rowno) FROM tmp_tempsearching GROUP BY producttitle) ORDER BY (CASE WHEN subcategoryid = v_subcatid THEN 0 END) DESC NULLS LAST;
  IF (v_catid = 0 AND v_subcatid = 0) THEN
  RETURN QUERY SELECT v_dynamicurl AS baseurl, (SELECT CASE WHEN COALESCE(COUNT(1), 0) > 0 THEN 1 ELSE 0 END FROM tbl_wishlist WHERE sprid = tm.sprid AND loginid = v_clid AND status = 1) AS wishcount, * FROM tmp_temp AS tm WHERE rownumber BETWEEN v_minindex AND v_maxindex AND v_catid <> v_catid AND v_subcatid <> v_subcatid ORDER BY GEN_RANDOM_UUID() DESC NULLS LAST;
  ELSE
  RETURN QUERY SELECT v_dynamicurl AS baseurl, (SELECT CASE WHEN COALESCE(COUNT(1), 0) > 0 THEN 1 ELSE 0 END FROM tbl_wishlist WHERE sprid = tm.sprid AND loginid = v_clid AND status = 1) AS wishcount, * FROM tmp_temp AS tm WHERE rownumber BETWEEN v_minindex AND v_maxindex ORDER BY GEN_RANDOM_UUID() DESC NULLS LAST;
  END IF;
  DROP TABLE IF EXISTS tmp_temp;
  DROP TABLE IF EXISTS tmp_tempsearching;
  -- SET option (removed)
  EXCEPTION WHEN OTHERS THEN
  v_totalcount := 0;
  END;
END;
$$;


