  v_subcatid := 0;
  END IF;
  IF (v_attributename = 'DISCOUNT') THEN
  SELECT CAST(MIN(CAST(value AS INT)) AS DECIMAL(18, 0)), CAST(MAX(CAST(value AS INT)) AS DECIMAL(18, 0)) INTO v_mindiscount, v_maxdiscount FROM SPLITSTRINGBYCUSTOMSYMBOL1(REPLACE(v_attributevalue, '-', '_'), '_');
  END IF;
  IF (v_attributename = 'PRICE') THEN
  SELECT CAST(MIN(CAST(value AS INT)) AS DECIMAL(18, 0)), CAST(MAX(CAST(value AS INT)) AS DECIMAL(18, 0)) INTO v_minprice, v_maxprice FROM SPLITSTRINGBYCUSTOMSYMBOL1(REPLACE(v_attributevalue, '-', '_'), '_');
  END IF;
  IF (v_attributename = 'ISOUT') THEN
  SELECT CAST(value AS BIT) INTO v_isoutofstock FROM SPLITSTRINGBYCUSTOMSYMBOL1(REPLACE(v_attributevalue, '-', '_'), '_');
  END IF;
  IF (v_attributename = 'Title') THEN
  SELECT CAST(value AS VARCHAR(50)) INTO v_title FROM SPLITSTRINGBYCUSTOMSYMBOL1(REPLACE(v_attributevalue, '-', '_'), '_');
  END IF;
  IF (v_attributename = 'PRICEASC' OR v_attributename = 'PRICEDESC') THEN
  SELECT CAST(value AS VARCHAR(50)) INTO v_sorting FROM SPLITSTRINGBYCUSTOMSYMBOL1(REPLACE(v_attributevalue, '-', '_'), '_');
  END IF;
  IF (v_attributename <> 'PRICE' AND v_attributename <> 'DISCOUNT' AND v_attributename <> 'ISOUT' AND v_attributename <> 'TITLE' AND v_attributename <> 'PAGE' AND v_attributename <> 'CATEGORY') THEN
  RAISE NOTICE '%', 'Actual Query String';
  v_querystring := v_querystring || '&' || v_value;
  END IF;
  RAISE NOTICE '%', 6;
  v_cnt1 := v_cnt1 + 1;
  END LOOP;
  DROP TABLE IF EXISTS tmp_tempp;
  v_returnmpid := '';
  SELECT v_returnmpid INTO v_returnmpid FROM dbo.ims_usp_getmpidfromquerystring(v_querystring => v_querystring, v_returnmpid => v_returnmpid);
  END IF;
  SELECT CASE WHEN COALESCE(v_maxdiscount, 0) = 0 THEN MAX(discountpercentage) ELSE v_maxdiscount END, CASE WHEN COALESCE(v_mindiscount, 0) = 0 THEN MIN(discountpercentage) ELSE v_mindiscount END, CASE WHEN COALESCE(v_minprice, 0) = 0 THEN MIN(dap) ELSE v_minprice END, CASE WHEN COALESCE(v_maxprice, 0) = 0 THEN MAX(dap) ELSE v_maxprice END INTO v_maxdiscount, v_mindiscount, v_minprice, v_maxprice FROM ims_subproduct;
  DROP TABLE IF EXISTS tmp_tempsearching;
  CREATE TEMP TABLE tmp_tempsearching (ROWNO BIGINT  ,MPRID BIGINT  ,PRODUCTCODE VARCHAR( 50) ,
PRODUCTTITLE VARCHAR( 300)  ,SHOTDESCRIPTION VARCHAR( 2000)  ,FULLDESCRIPTION text ,
SPRID BIGINT  ,PRODUCTIMAGES VARCHAR( 1000)  ,DISCOUNTPERCENTAGE DECIMAL  
,SELLMRP DECIMAL ,DAP DECIMAL  ,MASTERPRODUCTATTRIUBUTEID BIGINT  ,ATTRIBUTETITLE VARCHAR(200) 
,ATTRIBUTEVALUE VARCHAR( 200)  ,KEYFEATURES VARCHAR( 2000)  ,RATINGSTAR INT ,MAINCATEGORYID BIGINT ,
SUBCATEGORYID BIGINT  ,CATEGORYID BIGINT, DEALSIDS VARCHAR(100),CREATEDDATE timestamp,MODIFYDATE timestamp,REPLACEMENTDAY INT,PROCUREMENTSLA INT,
CASHONDELIVERY boolean,SHIPPINGCHARGES DECIMAL(18,2),STOCKIN INT,STOCKOUT INT ,STOCKNET INT ,ISOUTOFSTOCK boolean) ON COMMIT DROP;
  IF (v_sorting = 'PRICEASC') THEN
  INSERT INTO tmp_tempsearching SELECT ROW_NUMBER() OVER (ORDER BY dap ASC NULLS FIRST) AS rowno, mprid, productcode, producttitle, shotdescription, fulldescription, sprid, productimages, discountpercentage, sellmrp, dap, masterproductattriubuteid, attributetitle, attributevalue, keyfeatures, CAST(dbo.FUN_GETRATINGOFSUBPRODUCT(sprid) AS INT) AS ratingstar, maincategoryid, subcategoryid, catid, dealsids, createddate, modifydate, replacementday, procurementsla, cashondelivery, shippingcharges, stockin, stockout, stocknet, isoutofstock FROM ims_view_allproductdetailhot WHERE (v_maincatid = 0 OR maincategoryid = v_maincatid) AND (v_catid = 0 OR catid = v_catid) AND (v_subcatid = 0 OR subcategoryid = v_subcatid) AND (v_title IS NULL OR producttitle LIKE '%' || v_title || '%') AND (v_returnmpid IS NULL OR masterproductattriubuteid IN (SELECT * FROM dbo.SPLITSTRINGBYCUSTOMSYMBOL1(v_returnmpid, ','))) AND (discountpercentage BETWEEN v_mindiscount AND v_maxdiscount) AND (dap BETWEEN v_minprice AND v_maxprice) AND (v_isoutofstock IS NULL OR isoutofstock = v_isoutofstock);
  ELSE
  IF (v_sorting = 'PRICEDESC') THEN
  INSERT INTO tmp_tempsearching SELECT ROW_NUMBER() OVER (ORDER BY dap DESC NULLS LAST) AS rowno, mprid, productcode, producttitle, shotdescription, fulldescription, sprid, productimages, discountpercentage, sellmrp, dap, masterproductattriubuteid, attributetitle, attributevalue, keyfeatures, CAST(dbo.FUN_GETRATINGOFSUBPRODUCT(sprid) AS INT) AS ratingstar, maincategoryid, subcategoryid, catid, dealsids, createddate, modifydate, replacementday, procurementsla, cashondelivery, shippingcharges, stockin, stockout, stocknet, isoutofstock FROM ims_view_allproductdetailhot WHERE (v_maincatid = 0 OR maincategoryid = v_maincatid) AND (v_catid = 0 OR catid = v_catid) AND (v_subcatid = 0 OR subcategoryid = v_subcatid) AND (v_title IS NULL OR producttitle LIKE '%' || v_title || '%') AND (v_returnmpid IS NULL OR masterproductattriubuteid IN (SELECT * FROM dbo.SPLITSTRINGBYCUSTOMSYMBOL1(v_returnmpid, ','))) AND (discountpercentage BETWEEN v_mindiscount AND v_maxdiscount) AND (dap BETWEEN v_minprice AND v_maxprice) AND (v_isoutofstock IS NULL OR isoutofstock = v_isoutofstock);
  ELSE
  INSERT INTO tmp_tempsearching SELECT ROW_NUMBER() OVER (ORDER BY mprid NULLS FIRST) AS rowno, mprid, productcode, producttitle, shotdescription, fulldescription, sprid, productimages, discountpercentage, sellmrp, dap, masterproductattriubuteid, attributetitle, attributevalue, keyfeatures, CAST(dbo.FUN_GETRATINGOFSUBPRODUCT(sprid) AS INT) AS ratingstar, maincategoryid, subcategoryid, catid, dealsids, createddate, modifydate, replacementday, procurementsla, cashondelivery, shippingcharges, stockin, stockout, stocknet, isoutofstock FROM ims_view_allproductdetailhot WHERE (v_maincatid = 0 OR maincategoryid = v_maincatid) AND (v_catid = 0 OR catid = v_catid) AND (v_subcatid = 0 OR subcategoryid = v_subcatid) AND (v_title IS NULL OR producttitle LIKE '%' || v_title || '%') AND (v_returnmpid IS NULL OR masterproductattriubuteid IN (SELECT * FROM dbo.SPLITSTRINGBYCUSTOMSYMBOL1(v_returnmpid, ','))) AND (discountpercentage BETWEEN v_mindiscount AND v_maxdiscount) AND (dap BETWEEN v_minprice AND v_maxprice) AND (v_isoutofstock IS NULL OR isoutofstock = v_isoutofstock);
  END IF;
  END IF;
  SELECT COUNT(rowno) INTO v_totalcount FROM tmp_tempsearching;
  RETURN QUERY SELECT v_totalcount AS totalcount, * FROM tmp_tempsearching WHERE rowno IN (SELECT MIN(rowno) FROM tmp_tempsearching GROUP BY producttitle) ORDER BY GEN_RANDOM_UUID() DESC NULLS LAST;
  DROP TABLE IF EXISTS tmp_tempsearching;
  -- SET option (removed)
  EXCEPTION WHEN OTHERS THEN
  v_totalcount := 0;
  END;
END;
$$;


--
-- Name: ims_usp_productcodeexist(character varying, boolean, character varying, character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.ims_usp_productcodeexist(v_productcode character varying DEFAULT ''::character varying, v_success boolean DEFAULT true, v_message character varying DEFAULT ''::character varying, v_sqlresult character varying DEFAULT 0) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF EXISTS(SELECT 1 FROM ims_subproduct_temp WHERE subprcode = v_productcode) THEN
  v_success := 0;
  v_message := v_productcode || ' Code Existing. So please choose another one.';
  ELSE
  v_success := 1;
  v_message := v_productcode || ' Code is available.';
  END IF;
  RETURN QUERY SELECT * FROM ims_masterproduct;
END;
$$;


--
-- Name: ims_usp_recentviewproduct(text, integer, integer, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.ims_usp_recentviewproduct(v_querystring text DEFAULT ''::text, v_pageno integer DEFAULT 1, v_noofrows integer DEFAULT 100, v_totalcount integer DEFAULT 0) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_minindex INT;
  v_maxindex INT;
  v_mindiscount DECIMAL(18,2);
  v_maxdiscount DECIMAL(18,2);
  v_minprice DECIMAL(18,2);
  v_maxprice DECIMAL(18,2);
  v_isoutofstock boolean;
  v_cnt INT;
  v_cnt1 INT;
  v_countexists INT;
  v_attributename VARCHAR(50);
  v_value VARCHAR(50);
  v_attributevalue VARCHAR(100);
  v_title VARCHAR(100);
BEGIN
  BEGIN
  v_mindiscount := NULL;
  v_maxdiscount := NULL;
  v_minprice := NULL;
  v_maxprice := NULL;
  v_isoutofstock := NULL;
  v_cnt := 0;
  v_cnt1 := 0;
  v_countexists := 0;
  v_attributename := '';
  v_value := '';
  v_attributevalue := '';
  v_title := NULL;
  v_minindex := (v_pageno - 1) * v_noofrows + 1;
  v_maxindex := v_pageno * v_noofrows;
  RAISE NOTICE '%', 1;
  DROP TABLE IF EXISTS tmp_tempsearching;
  CREATE TEMP TABLE tmp_tempsearching (ROWNO BIGINT  ,MPRID BIGINT  ,PRODUCTCODE VARCHAR( 50)  ,PRODUCTTITLE VARCHAR( 300) ,SHOTDESCRIPTION VARCHAR( 2000),
	FULLDESCRIPTION text ,SPRID BIGINT  ,PRODUCTIMAGES VARCHAR( 1000)  ,DISCOUNTPERCENTAGE DECIMAL,SELLMRP DECIMAL,DAP DECIMAL,
	MASTERPRODUCTATTRIUBUTEID BIGINT,ATTRIBUTETITLE VARCHAR( 200),ATTRIBUTEVALUE VARCHAR( 200),KEYFEATURES VARCHAR( 2000),RATINGSTAR INT,
	MAINCATEGORYID BIGINT  ,SUBCATEGORYID BIGINT  ,CATEGORYID BIGINT,STOCKIN INT,STOCKOUT INT ,STOCKNET INT ,ISOUTOFSTOCK boolean) ON COMMIT DROP;
  INSERT INTO tmp_tempsearching SELECT ROW_NUMBER() OVER (ORDER BY sprid NULLS FIRST) AS rowno, mprid, productcode, producttitle, shotdescription, fulldescription, sprid, productimages, discountpercentage, sellmrp, dap, masterproductattriubuteid, attributetitle, attributevalue, keyfeatures, CAST(dbo.FUN_GETRATINGOFSUBPRODUCT(sprid) AS INT) AS ratingstar, maincategoryid, subcategoryid, catid, stockin, stockout, stocknet, isoutofstock FROM ims_view_allproductdetail WHERE sprid IN (SELECT CAST(id AS BIGINT) FROM CSVTOTABLE(v_querystring));
  RAISE NOTICE '%', 10;
  SELECT COUNT(rowno) INTO v_totalcount FROM tmp_tempsearching;
  RETURN QUERY SELECT v_totalcount AS totalcount, * FROM tmp_tempsearching WHERE rowno BETWEEN v_minindex AND v_maxindex;
  RAISE NOTICE '%', 'Table Drop';
  DROP TABLE IF EXISTS tmp_tempsearching;
  -- SET option (removed)
  EXCEPTION WHEN OTHERS THEN
  v_totalcount := 0;
  END;
END;
$$;


--
-- Name: initcap(character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.initcap(v_inputstring character varying) RETURNS character varying
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_index INT;
  v_char CHAR(1);
  v_prevchar CHAR(1);
  v_outputstring VARCHAR(255);
BEGIN
  v_outputstring := LOWER(v_inputstring);
  v_index := 1;
  WHILE v_index <= LENGTH(CAST(v_inputstring AS TEXT)) LOOP
  v_char := SUBSTRING(v_inputstring FROM v_index FOR 1);
  v_prevchar := CASE WHEN v_index = 1 THEN ' ' ELSE SUBSTRING(v_inputstring FROM v_index - 1 FOR 1) END;
  IF v_prevchar IN (' ', ';', ':', '!', '?', ',', '.', '_', '-', '/', '&', '''', '(') THEN
  IF v_prevchar <> '''' OR UPPER(v_char) <> 'S' THEN
  v_outputstring := STUFF(v_outputstring, v_index, 1, UPPER(v_char));
  END IF;
  END IF;
  v_index := v_index + 1;
  END LOOP;
  RETURN v_outputstring;
  RETURN NULL;
END;
$$;


--
-- Name: insert_update_delete(bigint, bigint, text, bigint, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.insert_update_delete(v_ipid bigint DEFAULT 0, v_smcid bigint DEFAULT 0, v_ipaddress text DEFAULT ''::text, v_key_sp_id bigint DEFAULT 0, INOUT v_intresult integer DEFAULT 0) RETURNS integer
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_bid_price numeric(19,4);
  v_numberofhits bigint;
  v_gettotalavlableamt numeric(19,4);
  v_plid bigint;
  v_adsdeductamt numeric(19,4);
  v_err int;
  v_flushamount numeric(19,4);
BEGIN
  -- BEGIN TRAN (removed)
  SELECT smcid, bid_price, COALESCE(noofhits, 0) INTO v_smcid, v_bid_price, v_numberofhits FROM tbl_keyword_in_sponsorad WHERE key_sp_id = v_key_sp_id AND status = 1;
  v_numberofhits := v_numberofhits + 1;
  SELECT plid INTO v_plid FROM tbl_sponsor_master_campain WHERE smcid = v_smcid;
  SELECT current_amount, ads_deduct INTO v_gettotalavlableamt, v_adsdeductamt FROM tbl_adsewallet WHERE plid = v_plid AND status = 1;
  IF NOT EXISTS(SELECT * FROM tbl_hitsonsponsorads WHERE key_sp_id = v_key_sp_id AND ipaddress = v_ipaddress AND CAST(hitdate AS DATE) = CAST(dbo.fun_getCurrentDate() AS DATE)) THEN
  IF (v_gettotalavlableamt >= v_bid_price) THEN
  INSERT INTO tbl_hitsonsponsorads (smcid, ipaddress, bid_price, key_sp_id, intstatus, hitdate) VALUES (v_smcid, v_ipaddress, v_bid_price, v_key_sp_id, 1, dbo.fun_getCurrentDate());
  UPDATE tbl_keyword_in_sponsorad SET noofhits = v_numberofhits WHERE key_sp_id = v_key_sp_id AND status = 1;
  UPDATE tbl_adsewallet SET current_amount = (v_gettotalavlableamt - v_bid_price), ads_deduct = (v_adsdeductamt + v_bid_price) WHERE plid = v_plid AND status = 1;
  v_intresult := 3;
  ELSE
  SELECT COALESCE(flushamount, 0) INTO v_flushamount FROM tbl_sponsor_master_campain WHERE smcid = v_smcid;
  UPDATE tbl_sponsor_master_campain SET campactive = 2, flushamount = (v_flushamount + v_bid_price) WHERE smcid = v_smcid;
  v_intresult := 4;
  END IF;
  END IF;
  SELECT 0 INTO v_err;
  IF (v_err <> 0) THEN
  v_intresult := 0;
  -- ROLLBACK (removed)
  RETURN;
  END IF;
  -- COMMIT (removed)
END;
$$;


--
-- Name: insertreferalcommission(bigint, character varying, numeric, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.insertreferalcommission(v_plid bigint DEFAULT 0, v_currencysymb character varying DEFAULT ''::character varying, v_referalcom numeric DEFAULT NULL::numeric, INOUT v_intresult integer DEFAULT NULL::integer) RETURNS integer
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_totamount numeric(19,4);
  v_totcom numeric(19,4);
  v_qpayregno BIGINT;
  v_childpmid BIGINT;
BEGIN
  SELECT COALESCE(qpayregno, 0) INTO v_qpayregno FROM portal_login WHERE plid = v_plid;
  SELECT pmid INTO v_childpmid FROM portal_login WHERE intro_refid = v_plid;
  IF EXISTS(SELECT plid FROM ewallet WHERE plid = v_plid) THEN
  SELECT referalcommission, amount INTO v_totcom, v_totcom FROM ewallet WHERE plid = v_plid;
  UPDATE ewallet SET amount = v_totcom + v_referalcom, referalcommission = v_totcom + v_referalcom WHERE plid = v_plid;
  INSERT INTO member_perfornemce (plid, childpmid, amount, qpayregno, refincome, date, active, trantype) VALUES (v_plid, v_childpmid, v_referalcom, v_qpayregno, v_referalcom, CURRENT_TIMESTAMP, 1, 'Referral Income');
  v_intresult := 1;
  RETURN;
  ELSE
  INSERT INTO ewallet (plid, active, referalcommission, currencysymbol, amount) VALUES (v_plid, 1, v_referalcom, v_currencysymb, v_referalcom);
  INSERT INTO member_perfornemce (plid, childpmid, amount, qpayregno, refincome, date, active, trantype) VALUES (v_plid, v_childpmid, v_referalcom, v_qpayregno, v_referalcom, CURRENT_TIMESTAMP, 1, 'Referral Income');
  v_intresult := 2;
  RETURN;
  END IF;
END;
$$;


--
-- Name: insertupdateownsugestion(integer, text, integer, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.insertupdateownsugestion(v_pmid integer, v_getnewservices text, v_mode integer DEFAULT 0, v_intresult integer DEFAULT 0) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_getcatid text;
  v_getnaxsgid bigint;
BEGIN
  SELECT COALESCE(catid, '') INTO v_getcatid FROM portal_master WHERE active = 1 AND pmid = v_pmid;
  RETURN QUERY SELECT COALESCE(v_getcatid, '');
  IF (v_mode = 0) THEN
  IF NOT EXISTS(SELECT * FROM tbl_sugestedservices WHERE pmid = v_pmid AND REPLACE(service_name, '''', '') = v_getnewservices) THEN
  SELECT COALESCE(MAX(sgid), 0) + 1 INTO v_getnaxsgid FROM tbl_sugestedservices;
  INSERT INTO tbl_sugestedservices (sgid, catid, pmid, date, status, service_name) VALUES (v_getnaxsgid, COALESCE(v_getcatid, ''), v_pmid, dbo.fun_getCurrentDate(), 1, v_getnewservices);
  ELSE
  UPDATE tbl_sugestedservices SET status = 1 WHERE pmid = v_pmid AND REPLACE(service_name, '''', '') = v_getnewservices;
  END IF;
  ELSE
  IF EXISTS(SELECT * FROM tbl_sugestedservices WHERE pmid = v_pmid AND REPLACE(service_name, '''', '') = v_getnewservices) THEN
  UPDATE tbl_sugestedservices SET status = 0 WHERE pmid = v_pmid AND REPLACE(service_name, '''', '') = v_getnewservices;
  END IF;
  IF EXISTS(SELECT * FROM portal_product_desc WHERE pmid = v_pmid AND REPLACE(productname, '''', '') = v_getnewservices) THEN
  UPDATE portal_product_desc SET active = 0 WHERE pmid = v_pmid AND REPLACE(productname, '''', '') = v_getnewservices;
  END IF;
  END IF;
END;
$$;


--
-- Name: isnull(anyelement, anyelement); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo."isnull"(val anyelement, alt anyelement) RETURNS anyelement
    LANGUAGE plpgsql IMMUTABLE
    AS $$
BEGIN
    RETURN COALESCE(val, alt);
END;
$$;


--
-- Name: keywordsearch(character varying, character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.keywordsearch(v_keywordname character varying DEFAULT ''::character varying, v_catname character varying DEFAULT ''::character varying) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF (v_keywordname <> '') THEN
  RETURN QUERY SELECT pc.keywordname FROM keyword_master AS pc WHERE pc.keywordname LIKE '%' || v_keywordname || '%' AND kactive = 1 ORDER BY keywordname ASC NULLS FIRST;
  END IF;
  IF (v_catname <> '') THEN
  RETURN QUERY SELECT catname FROM product_category WHERE catname LIKE '%' || v_catname || '%' AND catactive = 1 ORDER BY catname ASC NULLS FIRST;
  END IF;
END;
$$;


--
-- Name: logmentainoperator(bigint, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.logmentainoperator(v_optid bigint, INOUT v_intresult integer) RETURNS integer
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_orid bigint;
BEGIN
  v_orid := 0;
  IF EXISTS(SELECT orid FROM tbl_operator_report WHERE optid = v_optid AND CAST(logintime AS DATE) = CAST(dbo.fun_getIndiaCurrentDate() AS DATE)) THEN
  SELECT orid INTO v_orid FROM tbl_operator_report WHERE optid = v_optid AND CAST(logintime AS DATE) = CAST(dbo.fun_getIndiaCurrentDate() AS DATE);
  UPDATE tbl_operator_report SET logouttime = dbo.fun_getIndiaCurrentDate() WHERE optid = v_optid AND orid = v_orid;
  v_intresult := 1;
  END IF;
END;
$$;


--
-- Name: masterproc(character varying, integer, integer, integer, integer, integer, integer, character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.masterproc(v_whycall character varying, v_countryid integer DEFAULT 96, v_stateid integer DEFAULT 33, v_classid integer DEFAULT 0, v_branchid integer DEFAULT 0, v_monthid integer DEFAULT 0, v_zoneid integer DEFAULT 0, v_date1 character varying DEFAULT ''::character varying) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF (v_whycall = 'classdll') THEN
  RETURN QUERY SELECT id, classname FROM class_master WHERE status = 1;
  END IF;
  IF (v_whycall = 'ActiveAcademicYear') THEN
  RETURN QUERY SELECT COALESCE(fyid, 0) AS fyid FROM financial_year WHERE isactive = 1 AND isclosed = 0;
  END IF;
  IF (v_whycall = 'Countrydll') THEN
  RETURN QUERY SELECT cid, countryname FROM country WHERE cactive = 1 ORDER BY countryname NULLS FIRST;
  END IF;
  IF (v_whycall = 'Statedll') THEN
  RETURN QUERY SELECT sid, statename FROM state WHERE cid = v_countryid ORDER BY statename NULLS FIRST;
  END IF;
  IF (v_whycall = 'Citydll') THEN
  RETURN QUERY SELECT ctid, cityname FROM city WHERE sid = v_stateid ORDER BY cityname NULLS FIRST;
  END IF;
  IF (v_whycall = 'BranchDll') THEN
  RETURN QUERY SELECT brid, (brcode || '--(' || brname || ')') AS brname FROM branch_master WHERE isactive = 1 AND isdeleted = 0 ORDER BY brid NULLS FIRST;
  END IF;
  IF (v_whycall = 'ClassInBranch') THEN
  RETURN QUERY SELECT classid, classname FROM classbranch_master WHERE branchid = v_branchid AND status = 1 AND classid IN (SELECT id FROM class_master WHERE status = 1);
  END IF;
  IF (v_whycall = 'ClasswithBranch') THEN
  RETURN QUERY SELECT cwsid, sectionname FROM classwithsection WHERE classid = v_classid AND branchid = v_branchid;
  END IF;
  IF (v_whycall = 'feestructureDll') THEN
  RETURN QUERY SELECT id, feename FROM feestructure WHERE status = 1 AND feesubtype = 0;
  END IF;
  IF (v_whycall = 'ddlTitle') THEN
  RETURN QUERY SELECT titleid, title FROM title;
  END IF;
  IF (v_whycall = 'ddlDesignation') THEN
  RETURN QUERY SELECT id, name FROM tbldesignation WHERE status = 1 ORDER BY name ASC NULLS FIRST;
  END IF;
  IF (v_whycall = 'ddlProbationPeriod') THEN
  RETURN QUERY SELECT id, timeinmonth FROM tblprobationperiod;
  END IF;
  IF (v_whycall = 'ddlQualification') THEN
  RETURN QUERY SELECT qid, name FROM tblqualification WHERE status = 1;
  END IF;
  IF (v_whycall = 'ddlProQualification') THEN
  RETURN QUERY SELECT id, name FROM tblprofessionalqualification WHERE status = 1;
  END IF;
  IF (v_whycall = 'ddlDepartment') THEN
  RETURN QUERY SELECT id, name FROM tbldepartment WHERE status = 1;
  END IF;
  IF (v_whycall = 'ddlStatus') THEN
  RETURN QUERY SELECT id, name FROM tblofferletterstatus;
  END IF;
  IF (v_whycall = 'Conveyancedll') THEN
  RETURN QUERY SELECT id, area FROM conveyance WHERE status = 1 ORDER BY area NULLS FIRST;
  END IF;
  IF (v_whycall = 'zone') THEN
  RETURN QUERY SELECT zoneid, zonename FROM zone_master WHERE status = 1;
  END IF;
  IF (v_whycall = 'areanamedll') THEN
  RETURN QUERY SELECT areaid, areaname FROM tbl_addarea WHERE zoneid = v_zoneid AND status = 1;
  END IF;
  IF (v_whycall = 'sectiondll') THEN
  RETURN QUERY SELECT cwsid, sectionname FROM classwithsection WHERE branchid = v_branchid AND status = 1 AND classid = v_classid;
  END IF;
  IF (v_whycall = 'MonthName') THEN
  RETURN QUERY SELECT monthid, monthname FROM month_name;
  END IF;
  IF (v_whycall = 'getYear') THEN
  RETURN QUERY SELECT EXTRACT(year FROM GETUTCDATE()) AS currentdate;
  END IF;
  IF (v_whycall = 'getdays') THEN
  RETURN QUERY SELECT days FROM month_name WHERE monthid = v_monthid;
  END IF;
  IF (v_whycall = 'dayName') THEN
  RETURN QUERY SELECT TO_CHAR(CAST(v_date1 AS TIMESTAMP), 'TMDay') AS thedayname;
  END IF;
END;
$$;


--
-- Name: memberusp_managereferal(integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.memberusp_managereferal(v_plid integer DEFAULT 1) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
BEGIN
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp (RowNumber Int GENERATED BY DEFAULT AS IDENTITY,

TLPMID Int,

PageName text,

PreviewURL text,

PageURL text,

IsDefault Int) ON COMMIT DROP;
