  UPDATE tmp_temp SET isdefault = 1 WHERE tlpmid = 1;
  RETURN QUERY SELECT * FROM tmp_temp;
END;
$$;


--
-- Name: myrandom_gen(integer, integer, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.myrandom_gen(v_start integer, v_end integer, v_number integer) RETURNS text
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_returnout text;
  v_jointallvar varchar(1000);
  v_findlenght int;
  v_aftercuttingfirst char;
  v_findlenghtnew int;
  v_i INT;
  v_irand INT;
  v_aftercuttingnew char;
  v_jointallvarnew text;
BEGIN
  v_jointallvar := CONCAT(v_start, '', v_end, '', v_number);
  v_findlenght := LENGTH(CAST(v_jointallvar AS TEXT));
  v_findlenghtnew := LENGTH(CAST(v_jointallvar AS TEXT));
  v_i := 1;
  WHILE (v_i <= v_findlenght) LOOP
  SELECT SUBSTRING(v_jointallvar FROM 1 FOR 1) INTO v_aftercuttingfirst;
  IF (v_aftercuttingfirst = 0) THEN
  v_returnout := CONCAT(v_returnout, '', '126');
  END IF;
  IF (v_aftercuttingfirst = 1) THEN
  v_returnout := CONCAT(v_returnout, '', '786');
  END IF;
  IF (v_aftercuttingfirst = 2) THEN
  v_returnout := CONCAT(v_returnout, '', '568');
  END IF;
  IF (v_aftercuttingfirst = 3) THEN
  v_returnout := CONCAT(v_returnout, '', '985');
  END IF;
  IF (v_aftercuttingfirst = 4) THEN
  v_returnout := CONCAT(v_returnout, '', '235');
  END IF;
  IF (v_aftercuttingfirst = 5) THEN
  v_returnout := CONCAT(v_returnout, '', '934');
  END IF;
  IF (v_aftercuttingfirst = 6) THEN
  v_returnout := CONCAT(v_returnout, '', '375');
  END IF;
  IF (v_aftercuttingfirst = 7) THEN
  v_returnout := CONCAT(v_returnout, '', '982');
  END IF;
  IF (v_aftercuttingfirst = 8) THEN
  v_returnout := CONCAT(v_returnout, '', '452');
  END IF;
  IF (v_aftercuttingfirst = 9) THEN
  v_returnout := CONCAT(v_returnout, '', '457');
  END IF;
  SELECT SUBSTRING(v_jointallvar FROM (2) FOR (v_findlenghtnew)) INTO v_jointallvar;
  v_findlenghtnew := LENGTH(CAST(v_jointallvar AS TEXT));
  v_i := v_i + 1;
  END LOOP;
  v_jointallvarnew := v_returnout;
  v_returnout := '';
  v_irand := 1;
  WHILE (v_irand <= 21) LOOP
  SELECT SUBSTRING(v_jointallvarnew FROM 1 FOR 1) INTO v_aftercuttingnew;
  v_returnout := CONCAT(v_returnout, '', v_aftercuttingnew);
  SELECT SUBSTRING(v_jointallvarnew FROM (3) FOR (21)) INTO v_jointallvarnew;
  v_irand := v_irand + 2;
  END LOOP;
  RETURN (v_returnout);
  RETURN NULL;
END;
$$;


