--
-- Name: newordercomplete(character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.newordercomplete(v_orderid character varying DEFAULT 'OD866759053'::character varying) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
BEGIN
  RETURN QUERY SELECT om.orid, (b.fname || ' ' || b.lname) AS merchantname, pom.poid, om.orderid, om.paymode, om.payremark, om.ordertype, om.orderdate, COALESCE(om.fname, '') || ' ' || COALESCE(om.lname, '') AS name, COALESCE(om.address, '') AS billadd, COALESCE(om.city, '-') AS city, COALESCE(om.pincode, '') AS pincode, om.emailid, om.mobileno, pom.product_name, pom.product_qty AS quntity, pom.single_dap AS singleprodprice, pom.total_dap, COALESCE(pom.prod_images, 'default-product-image.png') AS prod_images, pom.total_ship_ch, pom.total_cost, pom.total_payble_vat, (pom.total_purchase_cost - (SELECT COALESCE(pv, 0) FROM ims_subproduct WHERE sprid = pom.subprcode)) AS total_purchase_cost, om.order_qty AS orderqty, om.order_dap AS ordertotalamount, om.total_vat AS ordertotalvat, om.total_ship_ch AS ordershippingcharges, om.order_netamt AS totalpaybleamt, (SELECT COALESCE(bv, 0) FROM ims_subproduct WHERE sprid = pom.subprcode) AS bv, (SELECT COALESCE(pv, 0) FROM ims_subproduct WHERE sprid = pom.subprcode) AS pv, (SELECT COALESCE(subprcode, '') FROM ims_subproduct WHERE sprid = pom.subprcode) AS prcode, (SELECT COALESCE(sprid, 0) FROM ims_subproduct WHERE sprid = pom.subprcode) AS sprid, COALESCE(pom.orderno, '') AS orderno FROM tbl_order_master AS om LEFT JOIN tbl_product_order_master AS pom ON om.orderid = pom.orderid LEFT JOIN portal_login AS b ON b.plid = om.branchid WHERE pom.orderno IN (SELECT items FROM dbo.CUSTOMSPLIT(v_orderid, ',')) ORDER BY pom.orderid ASC NULLS FIRST;
END;
$$;


--
-- Name: ordercomplete(character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.ordercomplete(v_orderid character varying DEFAULT 'OD646667438'::character varying) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
BEGIN
  RETURN QUERY SELECT om.orid, (b.fname || ' ' || b.lname) AS merchantname, pom.poid, om.orderid, om.paymode, om.payremark, om.ordertype, REPLACE(CAST(TO_CHAR(om.orderdate, 'DD TMMon YYYY') AS VARCHAR(11)), ' ', '-') || ' ' || STUFF(RIGHT(CAST(CAST(TO_CHAR(om.orderdate, 'TMMon DD YYYY FMHH12:MI%p') AS VARCHAR(30)) AS TEXT), 7), 6, 0, ' ') AS orderdate, COALESCE(om.fname, '') || ' ' || COALESCE(om.lname, '') AS name, COALESCE(om.address, '') AS billadd, COALESCE(om.city, '-') AS city, COALESCE(om.pincode, '') AS pincode, om.emailid, om.mobileno, pom.product_name, pom.product_qty AS quntity, pom.single_dap AS singleprodprice, pom.total_dap, COALESCE(pom.prod_images, 'default-product-image.png') AS prod_images, pom.total_ship_ch, pom.total_cost, pom.total_payble_vat, (pom.total_purchase_cost - (SELECT COALESCE(pv, 0) FROM ims_subproduct WHERE sprid = pom.subprcode)) AS total_purchase_cost, om.order_qty AS orderqty, om.order_dap AS ordertotalamount, om.total_vat AS ordertotalvat, om.total_ship_ch AS ordershippingcharges, om.order_netamt AS totalpaybleamt, (SELECT COALESCE(bv, 0) FROM ims_subproduct WHERE sprid = pom.subprcode) AS bv, (SELECT COALESCE(pv, 0) FROM ims_subproduct WHERE sprid = pom.subprcode) AS pv, (SELECT COALESCE(subprcode, '') FROM ims_subproduct WHERE sprid = pom.subprcode) AS prcode, (SELECT COALESCE(sprid, 0) FROM ims_subproduct WHERE sprid = pom.subprcode) AS sprid, COALESCE(om.invoiceno, '') AS invoiceno, tcl.did, b.phone AS marchentmobileno, b.emailid AS marchentemailno, dm.mobileno AS marchentfrenchiesmobileno, dm.comemailid AS marchentfrenchiesemailno FROM tbl_order_master AS om LEFT JOIN tbl_product_order_master AS pom ON om.orderid = pom.orderid LEFT JOIN portal_login AS b ON b.plid = pom.plid LEFT JOIN portal_master AS pm ON b.pmid = pm.pmid LEFT JOIN distributor_master AS dm ON dm.pmid = pm.distributorid LEFT JOIN tbl_customerlogin AS tcl ON pom.loginid = tcl.loginid WHERE om.orderid IN (SELECT items FROM dbo.CUSTOMSPLIT(v_orderid, ',')) ORDER BY pom.orderid ASC NULLS FIRST;
END;
$$;


--
-- Name: orderplaced(character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.orderplaced(v_orderno character varying DEFAULT ''::character varying) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
BEGIN
  RETURN QUERY SELECT om.orid, (b.fname || ' ' || b.lname) AS merchantname, pom.poid, om.orderid, om.paymode, om.payremark, om.ordertype, om.orderdate, COALESCE(om.fname, '') || ' ' || COALESCE(om.lname, '') AS name, COALESCE(om.address, '') AS billadd, COALESCE(om.sh_city, '-') AS city, COALESCE(om.pincode, '') AS pincode, om.emailid, om.mobileno, pom.product_name, pom.product_qty AS quntity, pom.single_dap AS singleprodprice, pom.total_dap, COALESCE(pom.prod_images, 'default-product-image.png') AS prod_images, pom.total_ship_ch, pom.total_cost, pom.total_payble_vat, (pom.total_purchase_cost - (SELECT COALESCE(pv, 0) FROM ims_subproduct WHERE sprid = pom.subprcode)) AS total_purchase_cost, om.order_qty AS orderqty, om.order_dap AS ordertotalamount, om.total_vat AS ordertotalvat, om.total_ship_ch AS ordershippingcharges, om.order_netamt AS totalpaybleamt, (SELECT COALESCE(bv, 0) FROM ims_subproduct WHERE sprid = pom.subprcode) AS bv, (SELECT COALESCE(pv, 0) FROM ims_subproduct WHERE sprid = pom.subprcode) AS pv, (SELECT COALESCE(subprcode, '') FROM ims_subproduct WHERE sprid = pom.subprcode) AS prcode, (SELECT COALESCE(sprid, 0) FROM ims_subproduct WHERE sprid = pom.subprcode) AS sprid, COALESCE(pom.orderno, '') AS orderno, COALESCE(pma.companyname, '') AS companyname, COALESCE(pma.pick_state, '') AS pick_state, COALESCE(pma.pick_city, '') AS pick_city, COALESCE(pma.pick_area, '') AS pick_area, COALESCE(pma.pick_pincode, '') AS pick_pincode, COALESCE(pma.pick_address, '') AS pick_address, COALESCE(pma.gstno, '') AS gstno, COALESCE(ocs.handover, '') AS handover, COALESCE(imsp.subprcode, '') AS productcode, COALESCE(imsp.hsn, '') AS hsn, COALESCE(vc.vattitle, '') AS vattitle, COALESCE(vc.vatpercvalue, 0) AS vatpercvalue FROM tbl_order_master AS om LEFT JOIN tbl_product_order_master AS pom ON om.orderid = pom.orderid LEFT JOIN portal_login AS b ON b.plid = om.branchid LEFT JOIN portal_master AS pma ON pma.pmid = b.pmid LEFT JOIN ims_subproduct AS imsp ON imsp.sprid = pom.subprcode LEFT JOIN tbl_vat_categories AS vc ON vc.vcid = imsp.vatcategoryid LEFT JOIN tbl_order_confirmedstaus AS ocs ON ocs.orderno = pom.orderno WHERE pom.orderno IN (SELECT items FROM dbo.CUSTOMSPLIT(v_orderno, ',')) ORDER BY pom.orderid ASC NULLS FIRST;
END;
$$;


--
-- Name: proc_sendsmshistory(integer, bigint, text, text, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.proc_sendsmshistory(v_plid integer, v_type bigint DEFAULT 0, v_tomobile text DEFAULT NULL::text, v_message text DEFAULT ''::text, INOUT v_intresult integer DEFAULT NULL::integer) RETURNS integer
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_frommobile VARCHAR(50);
  v_msgtype VARCHAR(50);
BEGIN
  -- BEGIN TRAN (removed)
  v_frommobile := 'User';
  v_msgtype := '';
  IF (v_type = 1) THEN
  v_msgtype := 'Transactional';
  INSERT INTO msg_history SELECT v_msgtype, v_frommobile, value, dbo.FUN_GETCURRENTDATE(), v_message, 0, 0, v_plid, 1 FROM dbo.SPLITSTRINGBYCUSTOMSYMBOLUPDATE(v_tomobile, ',');
  v_intresult := 1;
  END IF;
  IF (v_type = 2) THEN
  v_msgtype := 'Promotional';
  INSERT INTO msg_history SELECT v_msgtype, v_frommobile, value, dbo.FUN_GETCURRENTDATE(), v_message, 0, 0, 0, 1 FROM dbo.SPLITSTRINGBYCUSTOMSYMBOLUPDATE(v_tomobile, ',');
  v_intresult := 1;
  END IF;
  IF (0 <> 0) THEN
  v_intresult := 0;
  -- ROLLBACK (removed)
  RETURN;
  END IF;
  -- COMMIT (removed)
END;
$$;


