--
-- Name: send_bulkmail_history(integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.send_bulkmail_history(v_plid integer) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
BEGIN
  RETURN QUERY SELECT ROW_NUMBER() OVER (ORDER BY tbl_sendmailhistory.smid NULLS FIRST) AS sm_id, tbl_sendmailhistory.fromemail, tbl_sendmailhistory.toemail, tbl_sendmailhistory.senddate FROM tbl_sendmailhistory WHERE plid = v_plid AND mailtype = 2;
END;
$$;


--
