--

CREATE FUNCTION dbo.send_mail_history(v_plid integer DEFAULT 0, v_tecmid integer DEFAULT 0, v_fromdate character varying DEFAULT ''::character varying, v_todate character varying DEFAULT ''::character varying, v_status character varying DEFAULT ''::character varying, v_intresult integer DEFAULT 0, v_startrowindex integer DEFAULT 1, v_maxrows integer DEFAULT 100) RETURNS SETOF record
    LANGUAGE plpgsql
