DECLARE
  v_minindex INT;
  v_maxindex INT;
  v_query text;
BEGIN
  v_minindex := (v_startrowindex - 1) * v_maxrows + 1;
  v_maxindex := v_startrowindex * v_maxrows;
  IF (v_tecmid = 0 AND v_plid <> 0) THEN
  v_query := '';
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp (ROWNUMBER Bigint,
	TECMID Bigint,
	CAMPAIGNNAME Varchar(500),
	CAMPAIGNDATE Varchar(100),
	SUBJECT Varchar(500),
	MESSAGE text,
	CREATEDATE Varchar(50),
	CAMPAIGNDATEANDTIME text,
	SendingStatus Varchar(100)) ON COMMIT DROP;
  v_query := v_query || ('Insert Into #Temp SELECT ROW_NUMBER() OVER (ORDER BY  TECMID DESC) AS ROWNUMBER,TECMID,CAMPAIGNNAME,
	CAMPAIGNDATE,SUBJECT,MESSAGE,CONVERT(VARCHAR(15),CREATEDDATE,106) AS CREATEDATE,
	CONCAT(CONVERT(VARCHAR(15),CAMPAIGNDATE,106),'' At '',CONVERT(VARCHAR(5),CAMPAIGNTIME),'' Hrs'') AS CAMPAIGNDATEANDTIME,
	(Case When IsMailSent=1 Then ''Sent'' Else ''Not Sent'' END)As SendingStatus
	FROM  TBL_EMAILCAMPAIGNMASTER  WHERE PLID = ' || CAST(v_plid AS VARCHAR) || ' AND ISACTIVE = 1 ');
  IF (v_fromdate <> '' AND v_todate <> '') THEN
  v_query := v_query || (' And Convert(date,CAMPAIGNDATE,103) Between Convert(date,''' || v_fromdate || ''',103) And Convert(date,''' || v_todate || ''',103)');
  END IF;
  IF (v_fromdate <> '') THEN
  v_query := v_query || (' And Convert(date,CAMPAIGNDATE,103) >= Convert(date,''' || v_fromdate || ''',103)');
  END IF;
  IF (v_todate <> '') THEN
  v_query := v_query || (' And Convert(date,CAMPAIGNDATE,103) <= Convert(date,''' || v_todate || ''',103)');
  END IF;
  IF (v_status <> '') THEN
  v_query := v_query || (' And IsMailSent = ' || v_status || '');
  END IF;
  EXECUTE v_query;
  RETURN QUERY SELECT * FROM tmp_temp WHERE rownumber BETWEEN v_minindex AND v_maxindex;
  SELECT COUNT(1) INTO v_intresult FROM tmp_temp;
  DROP TABLE IF EXISTS tmp_temp;
  ELSE
  UPDATE tbl_emailcampaignmaster SET isactive = 0, isdeleted = 1 WHERE tecmid = v_tecmid;
  END IF;
END;
$$;


--
-- Name: send_sms_history(integer, integer, character varying, character varying, character varying, integer, integer, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.send_sms_history(v_plid integer DEFAULT 0, v_tscmid integer DEFAULT 0, v_fromdate character varying DEFAULT ''::character varying, v_todate character varying DEFAULT ''::character varying, v_status character varying DEFAULT ''::character varying, v_intresult integer DEFAULT 0, v_startrowindex integer DEFAULT 1, v_maxrows integer DEFAULT 100) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_minindex INT;
  v_maxindex INT;
  v_query text;
BEGIN
  v_minindex := (v_startrowindex - 1) * v_maxrows + 1;
  v_maxindex := v_startrowindex * v_maxrows;
  IF (v_tscmid = 0) THEN
  v_query := '';
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp (ROWNUMBER Bigint,
	TSCMID Bigint,
	CAMPAIGNNAME Varchar(500),
	CAMPAIGNDATE Varchar(100),
	MESSAGE text,
	CREATEDATE Varchar(50),
	CAMPAIGNDATEANDTIME text,
	SendingStatus Varchar(100)) ON COMMIT DROP;
  v_query := v_query || ('Insert Into #Temp SELECT ROW_NUMBER() OVER (ORDER BY  TSCMID DESC) AS ROWNUMBER,TSCMID,CAMPAIGNNAME,
	CAMPAIGNDATE,MESSAGE,CONVERT(VARCHAR(15),CREATEDDATE,106) AS CREATEDATE,
	CONCAT(CONVERT(VARCHAR(15),CAMPAIGNDATE,106),'' At '',CONVERT(VARCHAR(5),CAMPAIGNTIME),'' Hrs'') AS CAMPAIGNDATEANDTIME,
	(Case When IsSmsSent=1 Then ''Sent'' Else ''Not Sent'' END)As SendingStatus
	FROM  TBL_SMSCAMPAIGNMASTER  WHERE SMSFROMPLID= ' || CAST(v_plid AS VARCHAR) || ' AND ISACTIVE = 1 ');
  IF (v_fromdate <> '' AND v_todate <> '') THEN
  v_query := v_query || (' And Convert(date,CAMPAIGNDATE,103) Between Convert(date,''' || v_fromdate || ''',103) And Convert(date,''' || v_todate || ''',103)');
  END IF;
  IF (v_fromdate <> '') THEN
  v_query := v_query || (' And Convert(date,CAMPAIGNDATE,103) >= Convert(date,''' || v_fromdate || ''',103)');
  END IF;
  IF (v_todate <> '') THEN
  v_query := v_query || (' And Convert(date,CAMPAIGNDATE,103) <= Convert(date,''' || v_todate || ''',103)');
  END IF;
  IF (v_status <> '') THEN
  v_query := v_query || (' And IsSmsSent = ' || v_status || '');
  END IF;
  EXECUTE v_query;
  RETURN QUERY SELECT * FROM tmp_temp WHERE rownumber BETWEEN v_minindex AND v_maxindex;
  SELECT COUNT(1) INTO v_intresult FROM tmp_temp;
  RETURN QUERY SELECT v_intresult AS totalrows;
  DROP TABLE IF EXISTS tmp_temp;
  ELSE
  UPDATE tbl_smscampaignmaster SET isactive = 0, isdeleted = 1 WHERE tscmid = v_tscmid;
  END IF;
END;
$$;


