--
-- Name: sp_adminprofile(integer, character varying, character varying, character varying, character varying, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.sp_adminprofile(v_adid integer, v_mobile character varying, v_emailid character varying, v_address character varying, v_phoneno character varying, INOUT v_intresult integer) RETURNS integer
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_count int;
BEGIN
  v_intresult := 0;
  SELECT COUNT(*) INTO v_count FROM admin_profile WHERE adid = v_adid;
  IF (v_count > 0) THEN
  UPDATE admin_profile SET mobile = v_mobile, emailid = v_emailid, address = v_address, phone = v_phoneno WHERE adid = v_adid;
  ELSE
  INSERT INTO admin_profile (adid, mobile, phone, emailid, address) VALUES (v_adid, v_mobile, v_phoneno, v_emailid, v_address);
  END IF;
  IF (0 > 0) THEN
  v_intresult := 1;
  RETURN;
  END IF;
END;
$$;


