CREATE FUNCTION dbo.sp_createaticket(v_fromplid text DEFAULT ''::text, v_categoryname text DEFAULT ''::text, v_catid integer DEFAULT 0, v_subject text DEFAULT ''::text, v_message text DEFAULT ''::text, v_image text DEFAULT ''::text, v_accounttype character varying DEFAULT ''::character varying, INOUT v_intresult1 text DEFAULT ''::text, INOUT v_memberemailid text DEFAULT ''::text, INOUT v_ticketid text DEFAULT ''::text, INOUT v_intresult integer DEFAULT 0, v_fromadmin integer DEFAULT 0, v_did integer DEFAULT 0) RETURNS record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_lower INT;
  v_upper INT;
  v_random INT;
  v_readadmin INT;
  v_readmem INT;
  v_countuwc INT;
  v_uid INT;
  v_countuwcq INT;
  v_countur INT;
  v_counttickets INT;
  v_countttr INT;
  v_counttts INT;
  v_countots INT;
  v_count0tr INT;
  v_emailidforsendemail VARCHAR(500);
  v_newticketid INT;
  v_cmobile VARCHAR(100);
BEGIN
  -- BEGIN TRAN (removed)
  v_lower := 1111111;
  v_upper := 9999999;
  SELECT ROUND(((v_upper - v_lower - 1) * RANDOM() + v_lower), 0) INTO v_random;
  IF (v_accounttype = '2') THEN
  INSERT INTO dbo.tbl_customer_notifications VALUES (2, v_fromplid, 'We have received your query and we are working on it', dbo.FUN_GETCURRENTDATE(), v_random, 0, 1, dbo.FUN_GETCURRENTDATE(), '', NULL);
  END IF;
  IF (v_accounttype = '1') THEN
  INSERT INTO tbl_merchant_notifications VALUES (1, v_fromplid, 'We have received your query and we are working on it', dbo.FUN_GETCURRENTDATE(), v_random, 0, 1, dbo.FUN_GETCURRENTDATE(), '', NULL);
  END IF;
  INSERT INTO tbl_ticketmaster (ticketno, fromplid, torequestno, categoryname, subject, message, date, lastupdate, status, active, fromtype1, toid, tmimage, isreadadmin, isreadmem, isattend, catid, uid, lastreplyfrom, notifytype, dontautoclose, accounttype, fromregno, did) VALUES (v_random, v_fromplid, '', v_categoryname, v_subject, v_message, dbo.FUN_GETCURRENTDATE(), dbo.FUN_GETCURRENTDATE(), 1, 0, 0, '', v_image, 0, 0, 0, v_catid, 0, 0, 0, 0, v_accounttype, v_fromadmin, v_did);
  SELECT ticketno INTO v_newticketid FROM tbl_ticketmaster WHERE tmid = (SELECT IDENT_CURRENT('TBL_TICKETMASTER'));
  v_ticketid := v_newticketid;
  IF (0 = 0) THEN
  v_intresult1 := 'Ok';
  v_intresult := 1;
  -- COMMIT (removed)
  RETURN;
  END IF;
  v_intresult1 := 'Cancel';
  -- ROLLBACK (removed)
END;
$$;


