--
-- Name: sp_datewisepurchaselist(integer, integer, character varying, character varying, text, character varying, character varying, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.sp_datewisepurchaselist(v_startrowindex integer DEFAULT 1, v_maxrows integer DEFAULT 1000, v_searchfield character varying DEFAULT ''::character varying, v_searchvalue character varying DEFAULT ''::character varying, v_rolename text DEFAULT ''::text, v_fromdate character varying DEFAULT ''::character varying, v_todate character varying DEFAULT ''::character varying, v_totalcount integer DEFAULT 0) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_minindex INT;
  v_maxindex INT;
  v_query text;
BEGIN
  v_minindex := (v_startrowindex - 1) * v_maxrows + 1;
  v_maxindex := v_startrowindex * v_maxrows;
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp (ROWNUMBER INT,

OrderDateTime timestamp,

 OrderAmount varchar(100),
 OrderQty varchar(100)) ON COMMIT DROP;
  IF ((v_fromdate = '') AND (v_todate = '')) THEN
  v_query := 'INSERT INTO #TEMP SELECT ROW_NUMBER() OVER (ORDER BY  count(vomid) ASC) RowNumber,
 CAST(OrderDateTime As DATE) Date, 
 --SUM(orderamount) AS Total_Amount,
 sum(Case when status = ''confirm''  then orderamount else 0 end) as Total_Amount,
 sum(Case when status = ''confirm''  then orderqty else 0 end) as Quantity
 FROM tbl_voucher_order_master
  GROUP BY CAST(OrderDateTime AS DATE) having 1=1 ';
  ELSE
  IF ((v_fromdate <> '') AND (v_todate = '')) THEN
  v_query := 'INSERT INTO #TEMP  SELECT ROW_NUMBER() OVER (ORDER BY  count(vomid) ASC) RowNumber,
 CAST(OrderDateTime As DATE) DATE, 
-- SUM(orderamount) AS Total_Amount,
 sum(Case when status = ''confirm''  then orderamount else 0 end) as Total_Amount,
 sum(Case when status = ''confirm''  then orderqty else 0 end) as Quantity
 FROM tbl_voucher_order_master  where CONVERT(DATE, OrderDateTime,103)= CONVERT(DATE, ''' || v_fromdate || ''',103)
  
  GROUP BY CAST(OrderDateTime AS DATE) having 1=1  ';
  ELSE
  IF ((v_fromdate = '') AND (v_todate <> '')) THEN
  v_query := 'INSERT INTO #TEMP  SELECT ROW_NUMBER() OVER (ORDER BY  count(vomid) ASC) RowNumber,
 CAST(OrderDateTime As DATE) DATE, 
-- SUM(orderamount) AS Total_Amount,
 sum(Case when status = ''confirm''  then orderamount else 0 end) as Total_Amount,
 sum(Case when status = ''confirm''  then orderqty else 0 end) as Quantity
 FROM tbl_voucher_order_master  where CONVERT(DATE, OrderDateTime,103)= CONVERT(DATE, ''' || v_todate || ''',103)
  
  GROUP BY CAST(OrderDateTime AS DATE) having 1=1  ';
  ELSE
  IF ((v_fromdate <> '') AND (v_todate <> '')) THEN
  v_query := 'INSERT INTO #TEMP  SELECT ROW_NUMBER() OVER (ORDER BY  count(vomid) ASC) RowNumber,
 CAST(OrderDateTime As DATE) DATE, 
 --SUM(orderamount) AS Total_Amount,
  sum(Case when status = ''confirm''  then orderamount else 0 end) as Total_Amount,
  sum(Case when status = ''confirm''  then orderqty else 0 end) as Quantity
 --sum(orderqty) Quantity 
 FROM tbl_voucher_order_master  where CONVERT(DATE, OrderDateTime,103) BETWEEN CONVERT(DATE, ''' || v_fromdate || ''',103)
   AND  CONVERT(DATE,''' || v_todate || ''',103)
  GROUP BY CAST(OrderDateTime AS DATE) having 1=1  ';
  END IF;
  END IF;
  END IF;
  END IF;
  IF (v_rolename <> '') THEN
  v_query := v_query || ' ORDER BY  vomid ASC ';
  END IF;
  EXECUTE v_query;
  RETURN QUERY SELECT * FROM tmp_temp WHERE rownumber BETWEEN v_minindex AND v_maxindex;
  SELECT COUNT(rownumber) INTO v_totalcount FROM tmp_temp;
  DROP TABLE IF EXISTS tmp_temp;
  -- SET option (removed)
END;
$$;


