--
-- Name: sp_voucher_order_confirmation(integer, integer, text, integer, character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.sp_voucher_order_confirmation(v_startrowindex integer DEFAULT 1, v_maxrows integer DEFAULT 1000, v_rolename text DEFAULT ''::text, v_totalcount integer DEFAULT 0, v_orderid character varying DEFAULT ''::character varying) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_minindex INT;
  v_maxindex INT;
  v_query text;
BEGIN
  v_minindex := (v_startrowindex - 1) * v_maxrows + 1;
  v_maxindex := v_startrowindex * v_maxrows;
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp (ROWNUMBER INT,
ProductName VARCHAR(100),

Email_Status VARCHAR(100),
Sms_Status VARCHAR(100),
VoucherNo VARCHAR(100),
Voucherguid varchar(100)) ON COMMIT DROP;
  v_query := 'INSERT INTO #TEMP SELECT ROW_NUMBER() OVER (ORDER BY   VOM.OrderId ASC) as ROWNUMBER ,

 ISNULL(VOCM.ProductName,'''') AS ProductName,

-- convert(varchar, VOCM.ACTIVITYDATETIME, 10) as ACTIVITYDATETIME,
 -- ISNULL(VOCM.ACTIVITYDATETIME,0) AS ACTIVITYDATETIME,

 ISNULL(VOCM.Email_Status,'''') AS Email_Status,
  ISNULL(VOCM.Sms_Status,'''') AS Sms_Status,
 ISNULL(VOCM.VoucherNo,'''') AS VoucherNo,
  ISNULL(VOCM.Voucherguid,'''') AS Voucherguid
 
FROM tbl_voucher_order_confirmation_master VOCM left join tbl_voucher_order_master VOM ON VOCM.OrderId=VOM.OrderId where VOM.OrderId=''' || v_orderid || '''';
  IF (v_rolename <> '') THEN
  v_query := v_query || ' AND TOTALROLES LIKE ''%' || v_rolename || '%''';
  END IF;
  v_query := v_query || ' ORDER BY  VOM.OrderId ASC ';
  EXECUTE v_query;
  RETURN QUERY SELECT * FROM tmp_temp WHERE rownumber BETWEEN v_minindex AND v_maxindex;
  SELECT COUNT(rownumber) INTO v_totalcount FROM tmp_temp;
  DROP TABLE IF EXISTS tmp_temp;
  -- SET option (removed)
  RETURN QUERY SELECT * FROM tbl_voucher_order_confirmation_master;
END;
$$;


