  v_rid1 := v_rid2;
  v_rolename1 := v_rolename2;
  ELSE
  v_rid1 := v_rid1 || ',' || v_rid2;
  v_rolename1 := v_rolename1 || ',' || v_rolename2;
  END IF;
  v_count5 := v_count5 + 1;
  END LOOP;
  UPDATE tbl_users SET role = v_rid1, rolename = v_rolename1 WHERE uid = v_uid;
  v_count1 := v_count1 + 1;
  DROP TABLE IF EXISTS dbo.tmp_temp3;
