--
-- Name: splitstringbycustomsymbol(text, character varying, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.splitstringbycustomsymbol(v_input text, v_symbol character varying, v_plid integer DEFAULT 0) RETURNS TABLE(value text)
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_str text;
  v_ind INT;
  v_symbollength INT;
BEGIN
  DROP TABLE IF EXISTS v_result;
  CREATE TEMP TABLE v_result (VALUE text) ON COMMIT DROP;
  v_symbollength := LENGTH(CAST(v_symbol AS TEXT));
  IF (NOT v_input IS NULL) THEN
  v_ind := POSITION(v_symbol IN v_input);
  WHILE v_ind > 0 LOOP
  v_str := SUBSTRING(v_input FROM 1 FOR v_ind - 1);
  v_input := SUBSTRING(v_input FROM v_ind + v_symbollength FOR LENGTH(CAST(v_input AS TEXT)) - v_ind);
  IF NOT EXISTS(SELECT 1 FROM tbl_member_customer_email WHERE email = v_str AND plid = v_plid AND isdeleted = 0) THEN
  IF NOT EXISTS(SELECT 1 FROM v_result WHERE value = v_str) THEN
  INSERT INTO v_result VALUES (v_str);
  END IF;
  END IF;
  v_ind := POSITION(v_symbol IN v_input);
  END LOOP;
  v_str := v_input;
  IF NOT EXISTS(SELECT 1 FROM tbl_member_customer_email WHERE email = v_str AND plid = v_plid AND isdeleted = 0) THEN
  IF NOT EXISTS(SELECT 1 FROM v_result WHERE value = v_str) THEN
  INSERT INTO v_result VALUES (v_str);
  END IF;
  END IF;
  END IF;
  RETURN QUERY SELECT * FROM v_result;
  RETURN;
  RETURN QUERY SELECT * FROM v_result;
  RETURN;
END;
$$;


