CREATE FUNCTION dbo.spmessage(v_id integer, v_message character varying, INOUT v_result character varying) RETURNS character varying
    LANGUAGE plpgsql
    AS $$
BEGIN
  UPDATE website_enquiry SET lastreplymsg = v_message, lastreplydate = CURRENT_TIMESTAMP WHERE id = v_id;
  IF (0 <> 0) THEN
  v_result := 'Error';
  ELSE
  v_result := 'Successfully Updated';
  END IF;
END;
$$;


