--

CREATE FUNCTION dbo.subscriptioncheck(v_plid integer DEFAULT 1) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF NOT EXISTS(SELECT 1 FROM tbl_membersubscriptionaccount WHERE plid = v_plid) THEN
  RETURN QUERY SELECT 0;
  END IF;
  IF EXISTS(SELECT 1 FROM tbl_membersubscriptionaccount WHERE plid = v_plid AND CURRENT_TIMESTAMP BETWEEN activationdate AND tilldate AND isactive = 1) THEN
  RETURN QUERY SELECT 1;
  ELSE
  RETURN QUERY SELECT 0;
  END IF;
END;
$$;


--
-- Name: sync_all_sequences(); Type: PROCEDURE; Schema: dbo; Owner: -
--

CREATE PROCEDURE dbo.sync_all_sequences()
    LANGUAGE plpgsql
    AS $$
DECLARE
    rec RECORD;
    max_val BIGINT;
BEGIN
    FOR rec IN
        SELECT s.relname AS seq_name, t.relname AS table_name, a.attname AS column_name
        FROM pg_class s
        JOIN pg_depend d ON d.objid = s.oid
        JOIN pg_class t ON t.oid = d.refobjid
        JOIN pg_attribute a ON a.attrelid = t.oid AND a.attnum = d.refobjsubid
        JOIN pg_namespace n ON n.oid = s.relnamespace
        WHERE s.relkind = 'S' AND n.nspname = 'dbo'
    LOOP
        EXECUTE format('SELECT COALESCE(MAX(%I), 1) FROM dbo.%I', rec.column_name, rec.table_name) INTO max_val;
        EXECUTE format('SELECT setval(''dbo.%I'', %s, true)', rec.seq_name, max_val);
        RAISE NOTICE 'Resynced sequence % for table %.% to %', rec.seq_name, rec.table_name, rec.column_name, max_val;
    END LOOP;
END;
$$;


