--
-- Name: update_smsapi_setting(integer, integer, integer, text, text, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.update_smsapi_setting(v_plid integer DEFAULT 0, v_status integer DEFAULT 0, v_prostatus integer DEFAULT 0, v_smsapi text DEFAULT ''::text, v_prosmsapi text DEFAULT ''::text, INOUT v_intresult integer DEFAULT 0) RETURNS integer
    LANGUAGE plpgsql
    AS $$
BEGIN
  v_intresult := 0;
  IF EXISTS(SELECT 1 FROM tbl_smsapisetting WHERE api_type = 1 AND plid = v_plid) THEN
  UPDATE tbl_smsapisetting SET sms_api = (CASE WHEN v_smsapi <> '' THEN v_smsapi ELSE sms_api END), status = (CASE WHEN (v_status = 0 OR v_status = 1) THEN v_status ELSE status END) WHERE api_type = 1 AND plid = v_plid;
  v_intresult := 2;
  ELSE
  IF (v_smsapi <> '') THEN
  INSERT INTO tbl_smsapisetting (sms_api, status, api_type, plid) VALUES (v_smsapi, v_status, 1, v_plid);
  END IF;
  v_intresult := 1;
  END IF;
  IF EXISTS(SELECT 1 FROM tbl_smsapisetting WHERE api_type = 2 AND plid = v_plid) THEN
  UPDATE tbl_smsapisetting SET sms_api = (CASE WHEN v_prosmsapi <> '' THEN v_prosmsapi ELSE sms_api END), status = (CASE WHEN (v_prostatus = 0 OR v_prostatus = 1) THEN v_prostatus ELSE status END) WHERE api_type = 2 AND plid = v_plid;
  v_intresult := 2;
  ELSE
  IF (v_prosmsapi <> '') THEN
  INSERT INTO tbl_smsapisetting (sms_api, status, api_type, plid) VALUES (v_prosmsapi, v_prostatus, 2, v_plid);
  END IF;
  v_intresult := 1;
  END IF;
END;
$$;


