  DROP TABLE IF EXISTS v_temp;
  CREATE TEMP TABLE v_temp (catid text) ON COMMIT DROP;
  SELECT COALESCE(catid, ''), COALESCE(keyid, '') INTO v_precatid, v_prekeyid FROM portal_master WHERE pmid = v_pmid;
  IF (v_mode = 'delete') THEN
  IF (v_producttype = 'c') THEN
  INSERT INTO v_tablevar SELECT value FROM dbo.SPLITSTRINGBYCOMMA(v_precatid);
  DELETE FROM v_tablevar WHERE value = 0;
  DELETE FROM v_tablevar WHERE value = v_prid;
  SELECT COALESCE(v_totalcatid || ',', '') || CAST(value AS VARCHAR(25)) INTO v_totalcatid FROM v_tablevar;
  UPDATE portal_master SET catid = v_totalcatid WHERE pmid = v_pmid;
  END IF;
  IF (v_producttype = 'k') THEN
  INSERT INTO v_tablevar SELECT value FROM dbo.SPLITSTRINGBYCOMMA(v_prekeyid);
  DELETE FROM v_tablevar WHERE value = 0;
  DELETE FROM v_tablevar WHERE value = v_prid;
  SELECT COALESCE(v_totalcatid || ',', '') || CAST(value AS VARCHAR(25)) INTO v_totalcatid FROM v_tablevar;
  UPDATE portal_master SET keyid = v_totalcatid WHERE pmid = v_pmid;
  END IF;
  END IF;
  IF (v_mode = 'add') THEN
  IF (v_producttype = 'c') THEN
  INSERT INTO v_tablevar SELECT value FROM dbo.SPLITSTRINGBYCOMMA(v_precatid);
  DELETE FROM v_tablevar WHERE value = 0;
  INSERT INTO v_tablevar VALUES (v_prid);
  SELECT COALESCE(v_totalcatid || ',', '') || CAST(value AS VARCHAR(25)) INTO v_totalcatid FROM v_tablevar;
  UPDATE portal_master SET catid = v_totalcatid WHERE pmid = v_pmid;
  END IF;
  IF (v_producttype = 'k') THEN
  INSERT INTO v_tablevar SELECT value FROM dbo.SPLITSTRINGBYCOMMA(v_prekeyid);
  DELETE FROM v_tablevar WHERE value = 0;
  INSERT INTO v_tablevar VALUES (v_prid);
  SELECT COALESCE(v_totalcatid || ',', '') || CAST(value AS VARCHAR(25)) INTO v_totalcatid FROM v_tablevar;
  UPDATE portal_master SET keyid = v_totalcatid WHERE pmid = v_pmid;
  END IF;
  END IF;
  SELECT COALESCE(catid, ''), COALESCE(keyid, '') INTO v_precatid, v_prekeyid FROM portal_master WHERE pmid = v_pmid;
  INSERT INTO v_temp SELECT catid FROM keyword_master WHERE kmid IN (SELECT value FROM dbo.SPLITSTRINGBYCOMMA(v_prekeyid)) EXCEPT SELECT value AS catid FROM dbo.SPLITSTRINGBYCOMMA(v_precatid);
  RETURN QUERY SELECT * FROM v_temp;
  SELECT COALESCE(v_reamincatid || ',', '') || catid INTO v_reamincatid FROM v_temp;
  RETURN QUERY SELECT v_reamincatid;
  RETURN QUERY SELECT v_precatid, v_prekeyid;
  UPDATE portal_master SET autocatid = v_reamincatid WHERE pmid = v_pmid;
  IF (0 <> 0) THEN
  -- ROLLBACK (removed)
  v_strresult := 'some error occured !';
  RETURN;
  END IF;
  -- COMMIT (removed)
END;
$$;


--
-- Name: updatelistingstatus(integer, character varying, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.updatelistingstatus(v_optid integer, v_date character varying, INOUT v_intresult integer) RETURNS integer
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_pmid bigint;
  v_qaid int;
  v_count int;
BEGIN
  -- BEGIN TRAN (removed)
  -- SET option (removed)
  SELECT COUNT(pmid) INTO v_count FROM portal_master WHERE optid = v_optid AND isverified = 0 AND CAST(TO_CHAR(doc, 'DD-MM-YYYY') AS VARCHAR(11)) = v_date;
  v_intresult := v_count;
  WHILE (v_count > 0) LOOP
  v_intresult := 5;
  v_pmid := (SELECT (pmid) FROM portal_master WHERE optid = v_optid AND CAST(TO_CHAR(doc, 'DD-MM-YYYY') AS VARCHAR(11)) = v_date AND isverified <> 2 LIMIT 1);
  SELECT optid INTO v_qaid FROM tbl_listingswithqa WHERE pmid = v_pmid;
  UPDATE portal_master SET isverified = 2 WHERE pmid = v_pmid;
  INSERT INTO unvarifiedlisting_master (pmid, message, date, optid, qaid, status) VALUES (v_pmid, 'entry is wrong , check it again', dbo.fun_getIndiaCurrentDate(), v_optid, v_qaid, 1);
  v_count := v_count - 1;
  v_intresult := 1;
  END LOOP;
  IF (0 <> 0) THEN
  -- ROLLBACK (removed)
  RETURN;
  END IF;
  -- SET option (removed)
  -- COMMIT (removed)
END;
$$;


