--
-- Name: updateseggistedservice(integer, integer, text); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.updateseggistedservice(v_catid integer, v_sgid integer, v_service_name text) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_intsemid bigint;
  v_precatid varchar(500);
  v_totalcatid varchar(500);
  v_status int;
BEGIN
  DROP TABLE IF EXISTS v_tablevar;
  CREATE TEMP TABLE v_tablevar (value varchar(300)) ON COMMIT DROP;
  DROP TABLE IF EXISTS v_temp;
  CREATE TEMP TABLE v_temp (catid text) ON COMMIT DROP;
  IF NOT EXISTS(SELECT semid FROM tbl_servicesmaster WHERE catid = v_catid AND service_name = v_service_name) THEN
  SELECT catid INTO v_precatid FROM tbl_sugestedservices WHERE sgid = v_sgid;
  INSERT INTO v_tablevar SELECT value FROM dbo.SPLITSTRINGBYCOMMA(v_precatid);
  DELETE FROM v_tablevar WHERE value = v_catid;
  SELECT COALESCE(v_totalcatid || ',', '') || CAST(value AS VARCHAR(500)) INTO v_totalcatid FROM v_tablevar;
  UPDATE tbl_sugestedservices SET catid = v_totalcatid WHERE sgid = v_sgid;
  SELECT COALESCE(MAX(semid), 0) + 1 INTO v_intsemid FROM tbl_servicesmaster;
  INSERT INTO tbl_servicesmaster (semid, catid, service_name, status) VALUES (v_intsemid, v_catid, v_service_name, 1);
  ELSE
  SELECT COALESCE(status, 0) INTO v_status FROM tbl_servicesmaster WHERE catid = v_catid AND service_name = v_service_name;
  IF (v_status > 0) THEN
  UPDATE tbl_servicesmaster SET status = 0 WHERE catid = v_catid AND service_name = v_service_name;
  ELSE
  UPDATE tbl_servicesmaster SET status = 1 WHERE catid = v_catid AND service_name = v_service_name;
  END IF;
  END IF;
END;
$$;


