--
-- Name: updatewithdrawal(bigint, character varying, character varying, character varying, character varying, character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.updatewithdrawal(v_whid bigint, v_status character varying, v_remarks character varying, v_paymode character varying, v_tranid character varying, v_strresult character varying DEFAULT ''::character varying) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_getamount numeric(19,4);
  v_getplid BIGINT;
BEGIN
  -- BEGIN TRAN (removed)
  v_strresult := 'success^success';
  IF (v_whid > 0) THEN
  RETURN QUERY SELECT * FROM withdrawal_history;
  UPDATE withdrawal_history SET status = v_status WHERE whid = v_whid;
  v_getamount := 0;
  v_getplid := 0;
  SELECT COALESCE(amount, 0), plid INTO v_getamount, v_getplid FROM withdrawal_history WHERE whid = v_whid;
  IF (v_status = 'reject') THEN
  UPDATE tbl_withdrawals SET rejectamt = COALESCE(rejectamt, 0) + COALESCE(v_getamount, 0) WHERE plid = v_getplid;
  UPDATE ewallet SET amount = COALESCE(amount, 0) + COALESCE(v_getamount, 0), dramount = COALESCE(dramount, 0) - COALESCE(v_getamount, 0) WHERE plid = v_getplid;
  INSERT INTO member_perfornemce (plid, amount, date, active, trantype, crdrtype) VALUES (v_getplid, COALESCE(v_getamount, 0), dbo.FUN_GETCURRENTDATE(), 1, 'Withdrawal cancelled', 'Cr');
  v_strresult := 'success^Rejected';
  ELSE
  IF (v_status = 'accept') THEN
  UPDATE withdrawal_history SET status = v_status, remarks = v_remarks, paymode = v_paymode, tranid = v_tranid WHERE whid = v_whid;
  UPDATE tbl_withdrawals SET acceptamt = COALESCE(acceptamt, 0) + COALESCE(v_getamount, 0) WHERE plid = v_getplid;
  v_strresult := 'success^Accepted';
  END IF;
  END IF;
  ELSE
  v_strresult := 'error^error';
  END IF;
  IF (0 <> 0) THEN
  v_strresult := 'error^Some error occured';
  -- ROLLBACK (removed)
  RETURN;
  END IF;
  -- COMMIT (removed)
END;
$$;


