--
-- Name: ups_getcatdetails(integer, integer, integer, text, integer, integer, integer, integer, text); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.ups_getcatdetails(v_aid integer DEFAULT 0, v_mode integer DEFAULT 0, v_catid integer DEFAULT 0, v_subcatname text DEFAULT ''::text, v_status integer DEFAULT 0, v_intresult integer DEFAULT 0, v_subcatid integer DEFAULT 0, v_maincatid integer DEFAULT 0, v_categoryname text DEFAULT ''::text) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_singleval varchar(500);
BEGIN
  DROP TABLE IF EXISTS tmp_temptable;
  CREATE TEMP TABLE tmp_temptable (ROWNO INT GENERATED BY DEFAULT AS IDENTITY,
SINGLEVALUE VARCHAR(200)) ON COMMIT DROP;
  INSERT INTO tmp_temptable SELECT value FROM dbo.SPLITSTRINGBYCUSTOMSYMBOLSHOPING(v_subcatname, '~');
  SELECT singlevalue INTO v_singleval FROM tmp_temptable;
  IF (v_mode = 0) THEN
  RETURN QUERY SELECT catid, catname, status AS catactive, maincatid AS gmid FROM tbl_category WHERE catid = v_aid;
  ELSE
  IF (v_mode = 1) THEN
  IF NOT EXISTS(SELECT 1 FROM tbl_category WHERE catname = v_subcatname AND catid <> v_aid AND maincatid = v_catid) THEN
  UPDATE tbl_category SET catname = v_subcatname, maincatid = v_catid, status = v_status, cat_code = dbo.REMOVESPACESANDSPECIALCHARS(v_singleval) WHERE catid = v_aid;
  v_intresult := 1;
  ELSE
  v_intresult := 2;
  END IF;
  ELSE
  IF (v_mode = 2) THEN
  RETURN QUERY SELECT * FROM tbl_sub_category WHERE subcatid = v_subcatid;
  ELSE
  IF (v_mode = 3) THEN
  UPDATE tbl_sub_category SET catid = v_catid, maincatid = v_maincatid, subcatname = v_subcatname, status = v_status, sub_cat_code = dbo.REMOVESPACESANDSPECIALCHARS(v_singleval) WHERE subcatid = v_subcatid;
  v_intresult := 1;
  ELSE
  IF (v_mode = 4) THEN
  RETURN QUERY SELECT maincatid, sequence, imagename, ishot_links FROM tbl_main_category WHERE maincatname = v_categoryname;
  END IF;
  END IF;
  END IF;
  END IF;
  END IF;
  DROP TABLE IF EXISTS tmp_temptable;
END;
$$;


