--
-- Name: ups_getlistingdetails(integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.ups_getlistingdetails(v_pmid integer DEFAULT 1) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_catid text;
  v_keyid text;
  v_ctid text;
  v_totalcategory text;
  v_totalkeyword text;
  v_totalcity text;
BEGIN
  SELECT catid, keyid, ctid INTO v_catid, v_keyid, v_ctid FROM portal_master WHERE pmid = v_pmid;
  SELECT COALESCE(v_totalcategory || ', ', '') || catname INTO v_totalcategory FROM product_category WHERE catid IN (SELECT value FROM dbo.SPLITSTRINGBYCOMMA(v_catid));
  SELECT COALESCE(v_totalkeyword || ', ', '') || keywordname INTO v_totalkeyword FROM keyword_master WHERE kmid IN (SELECT value FROM dbo.SPLITSTRINGBYCOMMA(v_keyid));
  SELECT COALESCE(v_totalcity || ', ', '') || cityname INTO v_totalcity FROM city WHERE ctid IN (SELECT value FROM dbo.SPLITSTRINGBYCOMMA(v_ctid));
  RETURN QUERY SELECT pm.pmid, pm.companyname, ('https://anavexchange.com/Company_Logo/' || COALESCE(pm.companyimage, '')) AS companyimage, CASE pm.yearofestable WHEN 0 THEN 'N/A' ELSE CAST(pm.yearofestable AS VARCHAR(30)) END AS yearofestable, pm.url, (CAST(TO_CHAR(pm.doc, 'DD-MM-YYYY') AS VARCHAR(24)) || ' ' || CAST(TO_CHAR(pm.doc, 'HH24:MI:SS') AS VARCHAR(24))) AS doc, (pl.title || ' ' || COALESCE(pl.fname, '') || ' ' || COALESCE(pl.lname, '')) AS name, (pl.phone) AS cpermobileno, pl.loginid, COALESCE(pl.username, '-') AS username, pl.password, COALESCE(pl.designation, '-') AS cperdesignation, COALESCE(s.statename, '') AS statename, c.countryname, COALESCE(ct.cityname, '') AS cityname, (COALESCE(pm.areaname, '') || '-' || COALESCE(pm.pincode, '')) AS areaname, (pm.address) AS building, pm.lankmark, pm.comemailid, pm.noofemployee, pm.mobileno AS companymob, pm.isverified, v_totalcategory AS totalcategory, v_totalkeyword AS totalkeyword, v_totalcity AS totalcity, COALESCE(pm.headerimage, '') AS headerimage, COALESCE(pm.companydesc, '') AS companydesc, pl.username, (CASE COALESCE(pl.title, 0) WHEN 0 THEN 'N/A' WHEN 1 THEN 'Mr.' WHEN 2 THEN 'Miss.' WHEN 3 THEN 'Mrs' WHEN 4 THEN 'M/S' ELSE 'N/A' END) AS title, (CASE COALESCE(pl.gender, 0) WHEN 1 THEN 'Male' WHEN 2 THEN 'Female' ELSE 'N/A' END) AS gender, COALESCE(pl.fatherormothername, 'N/A') AS fatherormothername, COALESCE(tq.name, 'N/A') AS highestqualification, (CASE WHEN COALESCE(pl.designation, '') = '' THEN 'N/A' END) AS designation FROM portal_master AS pm, portal_login AS pl LEFT JOIN tblqualification AS tq ON tq.qid = pl.highestqualification, state AS s, country AS c, city AS ct WHERE pm.pmid = pl.pmid AND pl.cid = c.cid AND pm.ctid = ct.ctid AND pm.sid = s.sid AND pm.pmid = v_pmid;
END;
$$;


--
-- Name: ups_getmanualdetails(integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.ups_getmanualdetails(v_pmid integer) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_pmtid bigint;
  v_sid bigint;
BEGIN
  v_sid := v_pmid;
  SELECT COALESCE(pmid, 0), COALESCE(pmtid, 0) INTO v_pmid, v_pmtid FROM suggestedarea_master WHERE said = v_pmid;
  IF (v_pmid > 0) THEN
  RETURN QUERY SELECT ROW_NUMBER() OVER (ORDER BY pm.pmid DESC NULLS LAST) AS rownumber, pm.pmid, v_sid AS sid, pm.companyname, COALESCE(c.countryname, '-') AS countryname, COALESCE(s.statename, '-') AS statename, COALESCE(ct.cityname, '-') AS cityname, COALESCE(pm.areaname, '-') AS areaname, pm.pincode FROM portal_master AS pm LEFT JOIN city AS ct ON ct.ctid = pm.ctid LEFT JOIN state AS s ON s.sid = pm.sid LEFT JOIN country AS c ON c.cid = pm.cid WHERE pm.ismannual = 1 AND pm.pmid = v_pmid;
  ELSE
  RETURN QUERY SELECT ROW_NUMBER() OVER (ORDER BY pm.pmtid DESC NULLS LAST) AS rownumber, pm.pmtid AS pmid, v_sid AS sid, pm.companyname, COALESCE(c.countryname, '-') AS countryname, COALESCE(s.statename, '-') AS statename, COALESCE(ct.cityname, '-') AS cityname, COALESCE(pm.areaname, '-') AS areaname, pm.pincode FROM portal_master_temp AS pm LEFT JOIN city AS ct ON ct.ctid = pm.ctid LEFT JOIN state AS s ON s.sid = pm.sid LEFT JOIN country AS c ON c.cid = pm.cid WHERE pm.ismannual = 1 AND pm.pmtid = v_pmtid;
  END IF;
END;
$$;


--
-- Name: ups_getsubscriptiondetails(integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.ups_getsubscriptiondetails(v_pmid integer) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_check int;
  v_catid text;
  v_keyid text;
  v_ctid text;
  v_aid text;
  v_pincode varchar(150);
  v_totalcategory text;
  v_totalkeyword text;
  v_totalcity text;
  v_totalarea text;
BEGIN
  SELECT 1 INTO v_check FROM portal_master WHERE pmid = v_pmid AND NOT expirydate IS NULL;
  IF (v_check = 1) THEN
  SELECT subaid, subcatid, subkeyid, subctid INTO v_aid, v_catid, v_keyid, v_ctid FROM portal_master WHERE pmid = v_pmid;
  SELECT COALESCE(v_totalcategory || ', ', '') || catname INTO v_totalcategory FROM product_category WHERE catid IN (SELECT value FROM dbo.SPLITSTRINGBYCOMMA(v_catid));
  SELECT COALESCE(v_totalkeyword || ', ', '') || keywordname INTO v_totalkeyword FROM keyword_master WHERE kmid IN (SELECT value FROM dbo.SPLITSTRINGBYCOMMA(v_keyid));
  SELECT COALESCE(v_totalarea || ', ', '') || areaname || '(' || pincode || ')' INTO v_totalarea FROM area_master WHERE aid IN (SELECT value FROM dbo.SPLITSTRINGBYCOMMA(v_aid));
  SELECT COALESCE(v_totalcity || ', ', '') || cityname INTO v_totalcity FROM city WHERE ctid IN (SELECT value FROM dbo.SPLITSTRINGBYCOMMA(v_ctid));
  RETURN QUERY SELECT CAST(TO_CHAR(pm.expirydate, 'DD TMMon YYYY') AS VARCHAR(24)) AS expirydate, sd.paymode, COALESCE(sd.noofmonth, 0) AS noofmonth, COALESCE((COALESCE(sd.price, 0) * COALESCE(sd.noofmonth, 0)), 0) AS totalamt, v_totalcategory AS totalcategory, v_totalkeyword AS totalkeyword, v_totalcity AS totalcity, v_totalarea AS totalarea, CAST(TO_CHAR(sd.approvedate, 'DD TMMon YYYY') AS VARCHAR(24)) AS approvedate FROM portal_master AS pm, tbl_subscription_details AS sd WHERE pm.pmid = v_pmid AND sd.pmid = pm.pmid;
  ELSE
  SELECT aid, catid, keyid, ctid INTO v_aid, v_catid, v_keyid, v_ctid FROM portal_master WHERE pmid = v_pmid;
  SELECT COALESCE(v_totalcategory || ', ', '') || catname INTO v_totalcategory FROM product_category WHERE catid IN (SELECT value FROM dbo.SPLITSTRINGBYCOMMA(v_catid));
  SELECT COALESCE(v_totalkeyword || ', ', '') || keywordname INTO v_totalkeyword FROM keyword_master WHERE kmid IN (SELECT value FROM dbo.SPLITSTRINGBYCOMMA(v_keyid));
  SELECT COALESCE(v_totalarea || ', ', '') || areaname || '(' || pincode || ')' INTO v_totalarea FROM area_master WHERE aid IN (SELECT value FROM dbo.SPLITSTRINGBYCOMMA(v_aid));
  SELECT COALESCE(v_totalcity || ', ', '') || cityname INTO v_totalcity FROM city WHERE ctid IN (SELECT value FROM dbo.SPLITSTRINGBYCOMMA(v_ctid));
  RETURN QUERY SELECT 'N/A' AS expirydate, 'N/A' AS approvedate, 'N/A' AS paymode, 'N/A' AS noofmonth, 'N/A' AS totalamt, v_totalcategory AS totalcategory, v_totalkeyword AS totalkeyword, v_totalcity AS totalcity, v_totalarea AS totalarea FROM portal_master AS pm WHERE pm.pmid = v_pmid;
  END IF;
END;
$$;


