--
-- Name: ups_insert_customer_address_mobile(bigint, character varying, character varying, character varying, integer, character varying, character varying, character varying, character varying, character varying, character varying, character varying, bigint, character varying, smallint, character varying, character varying, boolean, character varying, character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.ups_insert_customer_address_mobile(v_id bigint DEFAULT 0, v_pincode character varying DEFAULT '121'::character varying, v_shortaddress character varying DEFAULT 'noida'::character varying, v_landmark character varying DEFAULT 'noida'::character varying, v_countryid integer DEFAULT NULL::integer, v_cityname character varying DEFAULT 'delhi'::character varying, v_countryname character varying DEFAULT 'India'::character varying, v_phoneno1 character varying DEFAULT '56345'::character varying, v_phoneno2 character varying DEFAULT '4563456'::character varying, v_email1 character varying DEFAULT 'p@gmail'::character varying, v_remarks character varying DEFAULT '12'::character varying, v_addresstype character varying DEFAULT 'as'::character varying, v_touserid bigint DEFAULT NULL::bigint, v_tousertype character varying DEFAULT NULL::character varying, v_addresstype1 smallint DEFAULT 1, v_cname character varying DEFAULT 'Harsh'::character varying, v_ipaddress character varying DEFAULT NULL::character varying, INOUT v_success boolean DEFAULT false, INOUT v_message character varying DEFAULT '1'::character varying, INOUT v_sqlresult character varying DEFAULT '1'::character varying) RETURNS record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_getloginid BigInt;
BEGIN
  v_getloginid := 0;
  SELECT MAX(logid) + 1 INTO v_getloginid FROM ims_customeraddress;
  IF (v_id = 0) THEN
  INSERT INTO ims_customeraddress (touserid, tousertype, addresstype1, cname, addresstype, pincode, shortaddress, landmark, cityid, stateid, countryid, villagename, cityname, districtname, statename, countryname, phoneno1, phoneno2, email1, email2, faxno1, faxno2, remarks, currencyid, isactive, createddate, addressguid, logid) VALUES (v_touserid, 'Customer', v_addresstype1, v_cname, 'PermanentAddress', v_pincode, v_shortaddress, v_landmark, 0, 0, v_countryid, '', v_cityname, '', '', v_countryname, v_phoneno1, v_phoneno2, v_email1, '', '', '', v_remarks, 0, 1, CURRENT_TIMESTAMP, GEN_RANDOM_UUID(), v_getloginid);
  v_sqlresult := v_id;
  v_success := 1;
  v_message := 'Your Address is Created Successfully.' || CAST(v_cname AS VARCHAR);
  END IF;
  IF (v_id > 0) THEN
  UPDATE ims_customeraddress SET pincode = v_pincode, shortaddress = v_shortaddress, landmark = v_landmark, countryid = v_countryid, cname = v_cname, cityname = v_cityname, countryname = v_countryname, phoneno1 = v_phoneno1, phoneno2 = v_phoneno2, email1 = v_email1, remarks = v_remarks, addresstype1 = v_addresstype1 WHERE id = v_id;
  v_sqlresult := v_id;
  v_success := 1;
  v_message := 'Your Address is Updated Successfully.' || CAST(v_cname AS VARCHAR);
  END IF;
END;
$$;


--
-- Name: ups_replycontact(integer, text, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.ups_replycontact(v_pmid integer, v_msg text, INOUT v_result integer) RETURNS integer
    LANGUAGE plpgsql
    AS $$
BEGIN
  UPDATE website_enquiry SET lastreplydate = CURRENT_TIMESTAMP, lastreplymsg = v_msg WHERE id = v_pmid;
  v_result := 1;
END;
$$;


--
-- Name: usp_acceptreferralprogram(character varying, bigint, character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_acceptreferralprogram(v_sponser character varying DEFAULT ''::character varying, v_plid bigint DEFAULT 3625, INOUT v_result character varying DEFAULT ''::character varying) RETURNS character varying
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_intro_refid BIGINT;
  v_intro_plid BIGINT;
  v_sponserloginid VARCHAR(30);
  v_introregno BIGINT;
  v_loginid VARCHAR(30);
  v_strresult VARCHAR(200);
BEGIN
  -- BEGIN TRAN (removed)
  v_result := 'success';
  IF EXISTS(SELECT 1 FROM portal_login WHERE plid = v_plid AND intro_plid > 0) THEN
  v_result := 'Your account is already activated in referral program !';
  -- COMMIT (removed)
  RETURN;
  END IF;
  IF (v_sponser <> '') THEN
  IF NOT EXISTS(SELECT 1 FROM portal_login WHERE username = v_sponser) THEN
  v_result := 'Invalid Referral code !';
  -- COMMIT (removed)
  RETURN;
  END IF;
  ELSE
  v_intro_refid := 0;
  SELECT COALESCE(intro_refid, 0) INTO v_intro_refid FROM portal_login WHERE plid = v_plid;
  IF (v_intro_refid <= 0) THEN
  SELECT username INTO v_sponser FROM portal_login WHERE plid = 1;
  ELSE
  SELECT username INTO v_sponser FROM portal_login WHERE plid = v_intro_refid;
  END IF;
  END IF;
  v_intro_plid := 0;
  v_introregno := 0;
  SELECT plid INTO v_intro_plid FROM portal_login WHERE username = v_sponser;
  UPDATE portal_login SET intro_plid = v_intro_plid WHERE plid = v_plid;
  SELECT loginid, regno INTO v_sponserloginid, v_introregno FROM member_master WHERE plid = v_intro_plid;
  UPDATE member_master SET sponserid = v_sponserloginid, introregno = v_introregno WHERE plid = v_plid;
  SELECT loginid INTO v_loginid FROM member_master WHERE plid = v_plid;
  SELECT v_strresult INTO v_strresult FROM dbo.usp_activateandplaceinroot(v_loginid => v_loginid, v_sessionid => '', v_regno => v_plid, v_strresult => v_strresult);
  IF (v_strresult <> 'success') THEN
  -- ROLLBACK (removed)
  v_result := 'Some error occurred, Please try again !';
  RETURN;
  END IF;
  IF (0 <> 0) THEN
  -- ROLLBACK (removed)
  v_result := 'Some error occurred, Please try again !';
  RETURN;
  END IF;
  -- COMMIT (removed)
END;
$$;


--
-- Name: usp_activate_deactivate_ad(bigint, bigint, character varying, character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_activate_deactivate_ad(v_plid bigint, v_smcid bigint, v_mode character varying, INOUT v_strresult character varying) RETURNS character varying
    LANGUAGE plpgsql
    AS $$
BEGIN
  -- BEGIN TRAN (removed)
  v_strresult := 'ok';
  IF (v_mode = 'deactivate') THEN
  IF EXISTS(SELECT smcid FROM tbl_sponsor_master_campain WHERE plid = v_plid AND smcid = v_smcid AND campactive = 0) THEN
  -- COMMIT (removed)
  v_strresult := 'This Ad is already deactivated !';
  RETURN;
  END IF;
  UPDATE tbl_sponsor_master_campain SET campactive = 0 WHERE smcid = v_smcid AND plid = v_plid;
  END IF;
  IF (v_mode = 'activate') THEN
  IF NOT EXISTS(SELECT smcid FROM tbl_sponsor_master_campain WHERE plid = v_plid AND smcid = v_smcid) THEN
  -- COMMIT (removed)
  v_strresult := 'invalid details !';
  RETURN;
  END IF;
  IF EXISTS(SELECT smcid FROM tbl_sponsor_master_campain WHERE plid = v_plid AND smcid = v_smcid AND campactive = 1) THEN
  -- COMMIT (removed)
  v_strresult := 'This Ad is already activated !';
  RETURN;
  END IF;
  IF NOT EXISTS(SELECT key_sp_id FROM tbl_keyword_in_sponsorad WHERE smcid = v_smcid) THEN
  -- COMMIT (removed)
  v_strresult := 'Please add keywords in this Ads !';
  RETURN;
  END IF;
  IF NOT EXISTS(SELECT key_sp_id FROM tbl_keyword_in_sponsorad WHERE smcid = v_smcid AND status = 1) THEN
  -- COMMIT (removed)
  v_strresult := 'No keyword is activated in this Ads !';
  RETURN;
  END IF;
  UPDATE tbl_sponsor_master_campain SET campactive = 1 WHERE smcid = v_smcid AND plid = v_plid;
  END IF;
  IF (0 <> 0) THEN
  v_strresult := 'some error occured, please try again';
  -- ROLLBACK (removed)
  RETURN;
  END IF;
  -- COMMIT (removed)
END;
$$;


--
-- Name: usp_activateandplaceinroot(character varying, character varying, bigint, character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_activateandplaceinroot(v_loginid character varying DEFAULT ''::character varying, v_sessionid character varying DEFAULT ''::character varying, v_regno bigint DEFAULT 0, v_strresult character varying DEFAULT ''::character varying) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_mainrootid VARCHAR(50);
  v_leftid VARCHAR(50);
  v_rightid VARCHAR(50);
  v_bool INT;
  v_id VARCHAR(50);
  v_totalbv DECIMAL(18,3);
  v_side INT;
  v_parentid VARCHAR(25);
  v_intro_plid BIGINT;
  v_defaultsponserside INT;
  v_lastside INT;
BEGIN
  -- BEGIN TRAN (removed)
  v_strresult := 'success';
  IF NOT EXISTS(SELECT 1 FROM member_master WHERE loginid = v_loginid) THEN
  -- COMMIT (removed)
  v_strresult := 'Member Does Not Exists';
  RETURN;
  END IF;
  IF EXISTS(SELECT 1 FROM member_master WHERE loginid = v_loginid AND COALESCE(rootid, '0') <> '0') THEN
  -- COMMIT (removed)
  v_strresult := 'Member Already Activated';
  RETURN;
  END IF;
  v_mainrootid := '0';
  v_side := 0;
  v_intro_plid := 0;
  SELECT introregno INTO v_intro_plid FROM member_master WHERE regno = v_regno;
  v_defaultsponserside := 0;
  v_lastside := 0;
  IF (v_intro_plid > 0) THEN
  SELECT COALESCE(side, 0) INTO v_side FROM member_master WHERE regno = v_regno;
  SELECT loginid INTO v_mainrootid FROM member_master WHERE plid = v_intro_plid;
  IF (v_side = 0) THEN
  SELECT COALESCE(defaultsponserside, 3), COALESCE(lastside, 2), loginid INTO v_defaultsponserside, v_lastside, v_mainrootid FROM member_master WHERE plid = v_intro_plid;
  IF (v_defaultsponserside = 3) THEN
  IF (v_lastside = 1) THEN
  v_side := 2;
  UPDATE member_master SET lastside = 2 WHERE plid = v_intro_plid;
  END IF;
  IF (v_lastside = 2) THEN
  v_side := 1;
  UPDATE member_master SET lastside = 1 WHERE plid = v_intro_plid;
  END IF;
  ELSE
  IF (v_defaultsponserside = 1) THEN
  v_side := 1;
  ELSE
  IF (v_defaultsponserside = 2) THEN
  v_side := 2;
  END IF;
  END IF;
  END IF;
  ELSE
  SELECT COALESCE(lastside, 2), loginid INTO v_lastside, v_mainrootid FROM member_master WHERE plid = v_intro_plid;
  IF (v_side = 3) THEN
  IF (v_lastside = 1) THEN
  v_side := 2;
  END IF;
  IF (v_lastside = 2) THEN
  v_side := 1;
  END IF;
  UPDATE member_master SET lastside = v_side WHERE plid = v_intro_plid;
  END IF;
  END IF;
  ELSE
  -- COMMIT (removed)
  RETURN;
  END IF;
  IF (v_mainrootid = '0') THEN
  -- COMMIT (removed)
  v_strresult := 'success';
  RETURN;
  END IF;
  IF (v_side = 1 OR v_side = 2) THEN
  IF (v_side = 1) THEN
  v_parentid := '0';
  RETURN QUERY WITH employeelist AS (SELECT loginid, leftid, 1 AS emplevel FROM member_master AS boss WHERE boss.loginid = v_mainrootid UNION ALL SELECT emp.loginid, emp.leftid, el.emplevel + 1 FROM member_master AS emp INNER JOIN employeelist AS el ON emp.loginid = el.leftid WHERE emp.rootid >= 0) SELECT loginid AS v_parentid FROM employeelist WHERE leftid = 0;
  IF (v_parentid <> '0') THEN
  UPDATE member_master SET rootid = v_parentid WHERE loginid = v_loginid;
  UPDATE member_master SET leftid = v_loginid WHERE loginid = v_parentid;
  END IF;
  END IF;
  IF (v_side = 2) THEN
  v_parentid := '0';
  RETURN QUERY WITH employeelist AS (SELECT loginid, rightid, 1 AS emplevel FROM member_master AS boss WHERE boss.loginid = v_mainrootid UNION ALL SELECT emp.loginid, emp.rightid, el.emplevel + 1 FROM member_master AS emp INNER JOIN employeelist AS el ON emp.loginid = el.rightid WHERE emp.rootid >= 0) SELECT loginid AS v_parentid FROM employeelist WHERE rightid = 0;
  IF (v_parentid <> '0') THEN
  UPDATE member_master SET rootid = v_parentid WHERE loginid = v_loginid;
  UPDATE member_master SET rightid = v_loginid WHERE loginid = v_parentid;
  END IF;
  END IF;
  ELSE
  SELECT COALESCE(leftid, '0'), COALESCE(rightid, '0') INTO v_leftid, v_rightid FROM member_master WHERE loginid = v_mainrootid;
  IF (v_leftid = '0') THEN
  UPDATE member_master SET rootid = v_mainrootid WHERE loginid = v_loginid;
  UPDATE member_master SET leftid = v_loginid WHERE loginid = v_mainrootid;
  ELSE
  IF (v_rightid = '0') THEN
  UPDATE member_master SET rootid = v_mainrootid WHERE loginid = v_loginid;
  UPDATE member_master SET rightid = v_loginid WHERE loginid = v_mainrootid;
  ELSE
  DROP TABLE IF EXISTS tmp_tempids;
  CREATE TEMP TABLE tmp_tempids (ID INT GENERATED BY DEFAULT AS IDENTITY,
 	LOGINID VARCHAR(50),
 	STATUS boolean) ON COMMIT DROP;
  INSERT INTO tmp_tempids VALUES (v_leftid, 1);
  INSERT INTO tmp_tempids VALUES (v_rightid, 1);
  v_bool := 1;
  WHILE (v_bool > 0) LOOP
  SELECT loginid INTO v_id FROM tmp_tempids WHERE status = 1 ORDER BY id ASC NULLS FIRST LIMIT 1;
  SELECT COALESCE(leftid, '0'), COALESCE(rightid, '0') INTO v_leftid, v_rightid FROM member_master WHERE loginid = v_id;
  IF (v_leftid = '0') THEN
  UPDATE member_master SET rootid = v_id WHERE loginid = v_loginid;
  UPDATE member_master SET leftid = v_loginid WHERE loginid = v_id;
  v_bool := 0;
  ELSE
  IF (v_rightid = '0') THEN
  UPDATE member_master SET rootid = v_id WHERE loginid = v_loginid;
  UPDATE member_master SET rightid = v_loginid WHERE loginid = v_id;
  v_bool := 0;
  ELSE
  INSERT INTO tmp_tempids VALUES (v_leftid, 1);
  INSERT INTO tmp_tempids VALUES (v_rightid, 1);
  END IF;
  END IF;
  UPDATE tmp_tempids SET status = 0 WHERE id = v_id;
  END LOOP;
  DROP TABLE IF EXISTS tmp_tempids;
  END IF;
  END IF;
  END IF;
  IF EXISTS(SELECT 1 FROM tbl_member_pre_details WHERE loginid = v_loginid) THEN
  UPDATE tbl_member_pre_details SET side = v_side WHERE loginid = v_loginid;
  UPDATE tbl_member_pre_details SET rootid = v_parentid WHERE loginid = v_loginid;
  END IF;
  IF (0 <> 0) THEN
  -- ROLLBACK (removed)
  v_strresult := 'Something Went Wrong.Please Try Later.';
  RETURN;
  END IF;
  -- COMMIT (removed)
END;
$$;


--
-- Name: usp_activityreportmanager(integer, character varying, numeric, numeric, numeric, numeric, numeric, numeric, integer, integer, integer, integer, character varying, character varying, character varying, character varying, character varying, character varying, numeric); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_activityreportmanager(v_plid integer DEFAULT 0, v_date character varying DEFAULT ''::character varying, v_tearnedbyview numeric DEFAULT 0.00, v_tearnedbyshare numeric DEFAULT 0.00, v_tearnedbyblog numeric DEFAULT 0.00, v_tearnedbyclassified numeric DEFAULT 0.00, v_tearnedbybusinesslisting numeric DEFAULT 0.00, v_ttoatlearned numeric DEFAULT 0.00, v_startrowindex integer DEFAULT 1, v_maxrows integer DEFAULT 100, v_totalcountparam integer DEFAULT 0, v_mode integer DEFAULT 3, v_username character varying DEFAULT ''::character varying, v_searchfield character varying DEFAULT ''::character varying, v_searchvalue character varying DEFAULT ''::character varying, v_orderbyfield character varying DEFAULT ''::character varying, v_todate character varying DEFAULT ''::character varying, v_fromdate character varying DEFAULT ''::character varying, v_totalpoint numeric DEFAULT 0.00) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_earnedbyview Decimal(10,2);
  v_earnedbyshare Decimal(10,2);
  v_earnedbyblog Decimal(10,2);
  v_earnedbyclassified Decimal(10,2);
  v_earnedbybusinesslisting Decimal(10,2);
  v_toatlearned Decimal(10,2);
  v_dateofincome DATE;
  v_count Int;
  v_totalcount Int;
  v_tplid INT;
  v_newusername varchar(200);
  v_query text;
  v_query3 text;
  v_query2 text;
BEGIN
  v_earnedbyview := 0.00;
  v_earnedbyshare := 0.00;
  v_earnedbyblog := 0.00;
  v_earnedbyclassified := 0.00;
  v_earnedbybusinesslisting := 0.00;
  v_toatlearned := 0.00;
  v_count := 1;
  v_totalcount := 0;
  v_tplid := 0;
  v_newusername := '';
  IF (v_mode = 1) THEN
  DROP TABLE IF EXISTS tmp_tempreport;
  CREATE TEMP TABLE tmp_tempreport (SNO bigint GENERATED BY DEFAULT AS IDENTITY,
	PLID bigint,
	USERNAME text,
	EarnedByView Decimal(10,2),
	EarnedByShare Decimal(10,2),
	EarnedByBlog Decimal(10,2),
	EarnedByClassified Decimal(10,2),
	EarnedByBusinessListing Decimal(10,2),
	ToatlEarned Decimal(10,2)) ON COMMIT DROP;
  IF (v_plid = 0) THEN
  v_query := '';
  IF (v_date = '') THEN
  v_query := 'Insert Into #TempReport(PLID,USERNAME,EarnedByView,EarnedByShare,EarnedByBlog,EarnedByClassified,EarnedByBusinessListing,ToatlEarned)
	  Select MTI.PLID,UserName,0,0,0,0,0,0 From Tbl_MemberTaskIncomeDetails MTI INNER JOIN PORTAL_LOGIN PL ON PL.PLID=MTI.PLID';
  END IF;
  IF (v_date <> '') THEN
  v_query := 'Insert Into #TempReport(PLID,USERNAME,EarnedByView,EarnedByShare,EarnedByBlog,EarnedByClassified,EarnedByBusinessListing,ToatlEarned)
	   Select MTI.PLID,UserName,0,0,0,0,0,0 From Tbl_MemberTaskIncomeDetails MTI INNER JOIN PORTAL_LOGIN PL ON PL.PLID=MTI.PLID  WHERE CONVERT(Date,MTI.Date)=''' || CAST(CAST(v_date AS DATE) AS VARCHAR) || '''';
  END IF;
  RAISE NOTICE '%', v_query;
  IF (v_searchfield <> '') THEN
  IF (v_searchfield = 'LOGINID') THEN
  v_query := v_query || ' AND PL.LOGINID  LIKE ''%' || v_searchvalue || '%''';
  END IF;
  IF (v_searchfield = 'USERNAME') THEN
  IF (EXISTS(SELECT 1 FROM portal_login_temp WHERE username = v_searchvalue)) THEN
  v_query := v_query || (' AND PL.USERNAME LIKE ''%' || v_searchvalue || '%''');
  ELSE
  IF (EXISTS(SELECT 1 FROM portal_login_history WHERE username = v_searchvalue)) THEN
  SELECT (SELECT username FROM portal_login WHERE plid IN (SELECT plid FROM portal_login_history WHERE username = v_searchvalue)) INTO v_newusername;
  v_query := v_query || (' AND PL.USERNAME LIKE ''%' || v_newusername || '%''');
  ELSE
  v_query := v_query || ' AND PL.USERNAME LIKE ''%' || v_searchvalue || '%'' ';
  END IF;
  END IF;
  END IF;
  IF (v_searchfield = 'PHONE') THEN
  v_query := v_query || ' AND PL.PHONE  LIKE ''%' || v_searchvalue || '%''';
  END IF;
  END IF;
  v_query := v_query || ' Group By MTI.PLID,PL.UserName Order By UserName Asc';
  ELSE
  IF (v_plid <> 0) THEN
  v_query := 'Insert Into #TempReport(PLID,USERNAME,EarnedByView,EarnedByShare,EarnedByBlog,EarnedByClassified,EarnedByBusinessListing,ToatlEarned)
	Select MTI.PLID,UserName,0,0,0,0,0,0 From Tbl_MemberTaskIncomeDetails MTI INNER JOIN PORTAL_LOGIN PL ON PL.PLID=MTI.PLID Where PL.PLID=@PLID
	Group By MTI.PLID,PL.UserName Order By UserName Asc';
  END IF;
  END IF;
  EXECUTE v_query;
  SELECT COUNT(1) INTO v_totalcount FROM tmp_tempreport;
  WHILE (v_count <= v_totalcount) LOOP
  SELECT plid INTO v_tplid FROM tmp_tempreport WHERE sno = v_count;
  IF (v_date = '') THEN
  SELECT COALESCE(SUM(earnedamount), 0) INTO v_earnedbyview FROM tbl_membertaskincomedetails WHERE activitytype = 1 AND plid = v_tplid;
  SELECT COALESCE(SUM(earnedamount), 0) INTO v_earnedbyshare FROM tbl_membertaskincomedetails WHERE activitytype = 2 AND plid = v_tplid;
  SELECT COALESCE(SUM(earnedamount), 0) INTO v_earnedbyblog FROM tbl_membertaskincomedetails WHERE activitytype = 3 AND plid = v_tplid;
  SELECT COALESCE(SUM(earnedamount), 0) INTO v_earnedbyclassified FROM tbl_membertaskincomedetails WHERE activitytype = 4 AND plid = v_tplid;
  SELECT COALESCE(SUM(earnedamount), 0) INTO v_earnedbybusinesslisting FROM tbl_membertaskincomedetails WHERE activitytype = 5 AND plid = v_tplid;
  SELECT v_earnedbyview + v_earnedbyshare + v_earnedbyblog + v_earnedbyclassified + v_earnedbybusinesslisting INTO v_toatlearned;
  END IF;
  IF (v_date <> '') THEN
  SELECT COALESCE(SUM(earnedamount), 0) INTO v_earnedbyview FROM tbl_membertaskincomedetails WHERE activitytype = 1 AND plid = v_tplid AND CAST(date AS DATE) = CAST(v_date AS DATE);
  SELECT COALESCE(SUM(earnedamount), 0) INTO v_earnedbyshare FROM tbl_membertaskincomedetails WHERE activitytype = 2 AND plid = v_tplid AND CAST(date AS DATE) = CAST(v_date AS DATE);
  SELECT COALESCE(SUM(earnedamount), 0) INTO v_earnedbyblog FROM tbl_membertaskincomedetails WHERE activitytype = 3 AND plid = v_tplid AND CAST(date AS DATE) = CAST(v_date AS DATE);
  SELECT COALESCE(SUM(earnedamount), 0) INTO v_earnedbyclassified FROM tbl_membertaskincomedetails WHERE activitytype = 4 AND plid = v_tplid AND CAST(date AS DATE) = CAST(v_date AS DATE);
  SELECT COALESCE(SUM(earnedamount), 0) INTO v_earnedbybusinesslisting FROM tbl_membertaskincomedetails WHERE activitytype = 5 AND plid = v_tplid AND CAST(date AS DATE) = CAST(v_date AS DATE);
  SELECT v_earnedbyview + v_earnedbyshare + v_earnedbyblog + v_earnedbyclassified + v_earnedbybusinesslisting INTO v_toatlearned;
  END IF;
  UPDATE tmp_tempreport SET earnedbyview = v_earnedbyview, earnedbyshare = v_earnedbyshare, earnedbyblog = v_earnedbyblog, earnedbyclassified = v_earnedbyclassified, earnedbybusinesslisting = v_earnedbybusinesslisting, toatlearned = v_toatlearned WHERE sno = v_count;
  v_count := v_count + 1;
  END LOOP;
  IF (v_orderbyfield <> '') THEN
  IF (v_orderbyfield = 'VASC') THEN
  RETURN QUERY SELECT ROW_NUMBER() OVER (ORDER BY sno NULLS FIRST) AS sno, plid, username, earnedbyview, earnedbyshare, earnedbyblog, earnedbyclassified, earnedbybusinesslisting, toatlearned FROM tmp_tempreport WHERE sno BETWEEN v_startrowindex AND v_maxrows ORDER BY earnedbyview ASC NULLS FIRST;
  ELSE
  IF (v_orderbyfield = 'VDESC') THEN
  RETURN QUERY SELECT ROW_NUMBER() OVER (ORDER BY sno NULLS FIRST) AS sno, plid, username, earnedbyview, earnedbyshare, earnedbyblog, earnedbyclassified, earnedbybusinesslisting, toatlearned FROM tmp_tempreport WHERE sno BETWEEN v_startrowindex AND v_maxrows ORDER BY earnedbyview DESC NULLS LAST;
  ELSE
  IF (v_orderbyfield = 'SASC') THEN
  RETURN QUERY SELECT ROW_NUMBER() OVER (ORDER BY sno NULLS FIRST) AS sno, plid, username, earnedbyview, earnedbyshare, earnedbyblog, earnedbyclassified, earnedbybusinesslisting, toatlearned FROM tmp_tempreport WHERE sno BETWEEN v_startrowindex AND v_maxrows ORDER BY earnedbyshare ASC NULLS FIRST;
  ELSE
  IF (v_orderbyfield = 'SDESC') THEN
  RETURN QUERY SELECT ROW_NUMBER() OVER (ORDER BY sno NULLS FIRST) AS sno, plid, username, earnedbyview, earnedbyshare, earnedbyblog, earnedbyclassified, earnedbybusinesslisting, toatlearned FROM tmp_tempreport WHERE sno BETWEEN v_startrowindex AND v_maxrows ORDER BY earnedbyshare DESC NULLS LAST;
  ELSE
  IF (v_orderbyfield = 'CASC') THEN
  RETURN QUERY SELECT ROW_NUMBER() OVER (ORDER BY sno NULLS FIRST) AS sno, plid, username, earnedbyview, earnedbyshare, earnedbyblog, earnedbyclassified, earnedbybusinesslisting, toatlearned FROM tmp_tempreport WHERE sno BETWEEN v_startrowindex AND v_maxrows ORDER BY earnedbyclassified ASC NULLS FIRST;
  ELSE
  IF (v_orderbyfield = 'CDESC') THEN
  RETURN QUERY SELECT ROW_NUMBER() OVER (ORDER BY sno NULLS FIRST) AS sno, plid, username, earnedbyview, earnedbyshare, earnedbyblog, earnedbyclassified, earnedbybusinesslisting, toatlearned FROM tmp_tempreport WHERE sno BETWEEN v_startrowindex AND v_maxrows ORDER BY earnedbyclassified DESC NULLS LAST;
  ELSE
  IF (v_orderbyfield = 'BASC') THEN
  RETURN QUERY SELECT ROW_NUMBER() OVER (ORDER BY sno NULLS FIRST) AS sno, plid, username, earnedbyview, earnedbyshare, earnedbyblog, earnedbyclassified, earnedbybusinesslisting, toatlearned FROM tmp_tempreport WHERE sno BETWEEN v_startrowindex AND v_maxrows ORDER BY earnedbyblog ASC NULLS FIRST;
  ELSE
  IF (v_orderbyfield = 'BDESC') THEN
  RETURN QUERY SELECT ROW_NUMBER() OVER (ORDER BY sno NULLS FIRST) AS sno, plid, username, earnedbyview, earnedbyshare, earnedbyblog, earnedbyclassified, earnedbybusinesslisting, toatlearned FROM tmp_tempreport WHERE sno BETWEEN v_startrowindex AND v_maxrows ORDER BY earnedbyblog DESC NULLS LAST;
  ELSE
  IF (v_orderbyfield = 'LASC') THEN
  RETURN QUERY SELECT ROW_NUMBER() OVER (ORDER BY sno NULLS FIRST) AS sno, plid, username, earnedbyview, earnedbyshare, earnedbyblog, earnedbyclassified, earnedbybusinesslisting, toatlearned FROM tmp_tempreport WHERE sno BETWEEN v_startrowindex AND v_maxrows ORDER BY earnedbybusinesslisting ASC NULLS FIRST;
  ELSE
  IF (v_orderbyfield = 'LDESC') THEN
