--
-- Name: usp_add_agreemnnt(text, timestamp without time zone, character varying, character varying, text, bigint, numeric, integer, text, integer, character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_add_agreemnnt(v_selectvalues text, v_updatedate timestamp without time zone, v_name character varying, v_fathername character varying, v_address text, v_regno bigint, v_packamt numeric, v_clkamt integer, INOUT v_strresult text, v_mode integer, v_uploadimage character varying) RETURNS text
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF (v_mode = 1) THEN
  IF EXISTS(SELECT 1 FROM tbl_agreement_details WHERE regno = v_regno AND status <> 2) THEN
  v_strresult := 'Record Already Exists';
  RETURN;
  END IF;
  INSERT INTO tbl_agreement_details (regno, name, fathersname, address, updatedate, packageamount, clickamount, sentvia, tracking, upload_cou_or_postal, senddate, selectvalues, status, printdate, company_name) VALUES (v_regno, v_name, v_fathername, v_address, CURRENT_TIMESTAMP, v_packamt, v_clkamt, '', '', '', '', v_selectvalues, 1, CURRENT_TIMESTAMP, '');
  v_strresult := 'Record Added Successfully';
  IF (0 <> 0) THEN
  -- ROLLBACK (removed)
  v_strresult := 'Error occured. Please try later';
  RETURN;
  END IF;
  END IF;
  IF (v_mode = 2) THEN
  UPDATE tbl_agreement_details SET uploadimage = v_uploadimage WHERE regno = v_regno;
  v_strresult := 'Images Uploaded Successfully';
  END IF;
END;
$$;


