--
-- Name: usp_add_fund(); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_add_fund() RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
BEGIN
  RETURN QUERY SELECT DISTINCT ROW_NUMBER() OVER (ORDER BY sf.sfdid DESC NULLS LAST) AS rownumber, sf.datetime AS creditdate, sf.depositdate AS depositdate, sf.depositamount AS depositamount, sf.paymenttype AS paymenttype, CASE pum.ispaid WHEN 0 THEN 'Pending' WHEN 1 THEN 'Completed' END AS status, pum.commentorremark AS comment FROM tbl_sponserfunddetails AS sf INNER JOIN payyoumonerypaymenthistory AS pum ON sf.tpumphid = pum.tpumphid WHERE sf.status = 1;
END;
$$;


--
-- Name: usp_add_item(bigint, character varying, character varying, numeric, numeric, integer, character varying, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_add_item(v_plid bigint DEFAULT 54, v_itemcode character varying DEFAULT NULL::character varying, v_itemname character varying DEFAULT NULL::character varying, v_sellingprice numeric DEFAULT NULL::numeric, v_cpoint numeric DEFAULT NULL::numeric, v_status integer DEFAULT NULL::integer, v_strresult character varying DEFAULT ''::character varying, v_toilid integer DEFAULT 0) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
BEGIN
  -- BEGIN TRAN (removed)
  BEGIN
  IF (v_toilid = 0) THEN
  INSERT INTO tbl_offline_item_list (plid, itemname, itemcode, sellingprice, cpoints, addeddatetime, status, active) VALUES (v_plid, v_itemname, v_itemcode, v_sellingprice, v_cpoint, dbo.FUN_GETCURRENTDATE(), v_status, 1);
  END IF;
  IF (v_toilid <> 0) THEN
  UPDATE tbl_offline_item_list SET itemname = v_itemname, itemcode = v_itemcode, sellingprice = v_sellingprice, cpoints = v_cpoint, addeddatetime = dbo.FUN_GETCURRENTDATE(), status = v_status, active = v_status WHERE toilid = v_toilid;
  END IF;
  v_strresult := 'success';
  EXCEPTION WHEN OTHERS THEN
  RETURN QUERY SELECT sqlerrm;
  PERFORM dbo.sp_errorlog();
  IF (0 > 0) THEN
  -- ROLLBACK (removed)
  END IF;
  RETURN;
  END;
  IF (0 <> 0) THEN
  RETURN QUERY SELECT sqlerrm;
  v_strresult := 'ERROR';
  -- ROLLBACK (removed)
  RETURN;
  ELSE
  -- COMMIT (removed)
  END IF;
END;
$$;


--
-- Name: usp_add_master_commission(integer, integer, character varying, character varying, character varying, character varying, numeric, numeric, integer, character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_add_master_commission(v_mode integer DEFAULT 1, v_trpid integer DEFAULT 0, v_servicename character varying DEFAULT ''::character varying, v_operatorname character varying DEFAULT ''::character varying, v_operatorcode character varying DEFAULT ''::character varying, v_billtype character varying DEFAULT ''::character varying, v_commission numeric DEFAULT 0, v_surcharge numeric DEFAULT 0, v_active integer DEFAULT 0, INOUT v_strresult character varying DEFAULT ''::character varying) RETURNS character varying
    LANGUAGE plpgsql
    AS $$
BEGIN
  -- BEGIN TRAN (removed)
  IF (v_trpid = 0) THEN
  IF EXISTS(SELECT 1 FROM tbl_vendor_recharge_commission_structure WHERE servicename = v_servicename AND operatorname = v_operatorname) THEN
  v_strresult := 'OPERATOR NAME ALREADY EXISTS.';
  -- COMMIT (removed)
  RETURN;
  END IF;
  END IF;
  IF (v_mode = 1 AND v_trpid = 0) THEN
  IF NOT EXISTS(SELECT 1 FROM tbl_vendor_recharge_commission_structure WHERE servicename = v_servicename AND operatorname = v_operatorname) THEN
  INSERT INTO tbl_vendor_recharge_commission_structure (operatorname, operatorcode, servicename, billtype, commission, surcharge, status, createdate, active) VALUES (v_operatorname, v_operatorcode, v_servicename, v_billtype, v_commission, v_surcharge, 1, dbo.FUN_GETCURRENTDATE(), v_active);
  v_strresult := 'INSERT';
  END IF;
  ELSE
  IF EXISTS(SELECT 1 FROM tbl_vendor_recharge_commission_structure WHERE tvrcsid = v_trpid) THEN
  INSERT INTO tbl_vendor_recharge_commission_structure_history (tvrcsid, operatorname, operatorcode, servicename, billtype, commission, surcharge, status, createdate, active, modify_date) SELECT tvrcsid, operatorname, operatorcode, servicename, billtype, commission, surcharge, status, createdate, active, dbo.FUN_GETCURRENTDATE() FROM tbl_vendor_recharge_commission_structure WHERE tvrcsid = v_trpid;
  UPDATE tbl_vendor_recharge_commission_structure SET operatorname = v_operatorname, operatorcode = v_operatorcode, servicename = v_servicename, billtype = v_billtype, commission = v_commission, surcharge = v_surcharge, active = v_active WHERE tvrcsid = v_trpid;
  v_strresult := 'UPDATE';
  END IF;
  END IF;
  IF (0 <> 0) THEN
  v_strresult := 'ERROR OCCURRED. PLEASE TRY LATER';
  -- ROLLBACK (removed)
  RETURN;
  END IF;
  -- COMMIT (removed)
END;
$$;


