-- Name: usp_add_package(integer, integer, integer, character varying, numeric, text, integer, boolean, boolean, boolean, boolean, character varying, character varying, bigint, bigint, bigint, character varying, boolean, boolean, integer, boolean, boolean, boolean, boolean, integer, boolean, boolean, boolean, character varying, character varying, boolean); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_add_package(v_mode integer DEFAULT 1, v_trpid integer DEFAULT 0, v_trsid integer DEFAULT 1, v_packagename character varying DEFAULT ''::character varying, v_packageamount numeric DEFAULT 0, v_packagefeatures text DEFAULT ''::text, v_active integer DEFAULT 1, v_webhosting boolean DEFAULT false, v_freemarketingtool boolean DEFAULT false, v_multichannelsales boolean DEFAULT false, v_whitelabelbranding boolean DEFAULT false, v_storage character varying DEFAULT ''::character varying, v_discountcoupongen character varying DEFAULT ''::character varying, v_user bigint DEFAULT 0, v_targetaudience bigint DEFAULT 0, v_newcustomers bigint DEFAULT 0, v_onlinedatastorage character varying DEFAULT NULL::character varying, v_ddos boolean DEFAULT false, v_antivirus boolean DEFAULT false, v_emailstorage integer DEFAULT 0, v_seotools boolean DEFAULT false, v_smotool boolean DEFAULT false, v_autobackup boolean DEFAULT false, v_livechat boolean DEFAULT false, v_transactionalsms integer DEFAULT 0, v_logodesign boolean DEFAULT false, v_websiteskin boolean DEFAULT false, v_androidapp boolean DEFAULT false, v_multiplepaymentgateway character varying DEFAULT ''::character varying, INOUT v_strresult character varying DEFAULT ''::character varying, v_istrial boolean DEFAULT false) RETURNS character varying
    LANGUAGE plpgsql
    AS $$
BEGIN
  -- BEGIN TRAN (removed)
  IF (v_trpid = 0) THEN
  IF EXISTS(SELECT 1 FROM tbl_reseller_packages WHERE packagename = v_packagename AND trsid = v_trsid) THEN
  v_strresult := 'PACKAGE NAME ALREADY EXISTS.';
  -- COMMIT (removed)
  RETURN;
  END IF;
  END IF;
  IF EXISTS(SELECT 1 FROM tbl_reseller_packages WHERE trsid = v_trsid AND trpid = v_trpid AND istrial = 1) THEN
  v_strresult := 'FREE PAKCAGE ALREADY EXISTS.';
  -- COMMIT (removed)
  RETURN;
  END IF;
  IF (v_mode = 1 AND v_trpid = 0) THEN
  IF NOT EXISTS(SELECT 1 FROM tbl_reseller_packages WHERE packagename = v_packagename AND trsid = v_trsid) THEN
  INSERT INTO tbl_reseller_packages (trsid, packagename, packageamount, packagefeatures, active, createdate, webhosting, freemarketingtool, multichannelsales, whitelabelbranding, storage, discountcoupongen, "user", targetaudience, newcustomers, onlinedatastorage, ddos, antivirus, emailstorage, seotools, smotool, autobackup, livechat, transactionalsms, logodesign, websiteskin, androidapp, multiplepaymentgateway, istrial) VALUES (v_trsid, v_packagename, v_packageamount, v_packagefeatures, v_active, dbo.FUN_GETCURRENTDATE(), v_webhosting, v_freemarketingtool, v_multichannelsales, v_whitelabelbranding, v_storage, v_discountcoupongen, v_user, v_targetaudience, v_newcustomers, v_onlinedatastorage, v_ddos, v_antivirus, v_emailstorage, v_seotools, v_smotool, v_autobackup, v_livechat, v_transactionalsms, v_logodesign, v_websiteskin, v_androidapp, v_multiplepaymentgateway, v_istrial);
  v_strresult := 'INSERT';
  END IF;
  ELSE
  IF EXISTS(SELECT 1 FROM tbl_reseller_packages WHERE trpid = v_trpid) THEN
  INSERT INTO tbl_reseller_packages_history (trpid, trsid, packagename, packageamount, packagefeatures, active, createdate, modifydate, webhosting, freemarketingtool, multichannelsales, whitelabelbranding, storage, discountcoupongen, "user", targetaudience, newcustomers, onlinedatastorage, ddos, antivirus, emailstorage, seotools, smotool, autobackup, livechat, transactionalsms, logodesign, websiteskin, androidapp, multiplepaymentgateway) SELECT trpid, trsid, packagename, packageamount, packagefeatures, active, createdate, dbo.FUN_GETCURRENTDATE(), webhosting, freemarketingtool, multichannelsales, whitelabelbranding, storage, discountcoupongen, "user", targetaudience, newcustomers, onlinedatastorage, ddos, antivirus, emailstorage, seotools, smotool, autobackup, livechat, transactionalsms, logodesign, websiteskin, androidapp, multiplepaymentgateway FROM tbl_reseller_packages WHERE trpid = v_trpid AND trsid = v_trsid;
  UPDATE tbl_reseller_packages SET trsid = v_trsid, packagename = v_packagename, packageamount = v_packageamount, packagefeatures = v_packagefeatures, active = v_active, webhosting = v_webhosting, freemarketingtool = v_freemarketingtool, multichannelsales = v_multichannelsales, whitelabelbranding = v_whitelabelbranding, storage = v_storage, discountcoupongen = v_discountcoupongen, "user" = v_user, targetaudience = v_targetaudience, newcustomers = v_newcustomers, onlinedatastorage = v_onlinedatastorage, ddos = v_ddos, antivirus = v_antivirus, emailstorage = v_emailstorage, seotools = v_seotools, smotool = v_smotool, autobackup = v_autobackup, livechat = v_livechat, transactionalsms = v_transactionalsms, logodesign = v_logodesign, websiteskin = v_websiteskin, androidapp = v_androidapp, multiplepaymentgateway = v_multiplepaymentgateway, istrial = v_istrial WHERE trpid = v_trpid AND trsid = v_trsid;
  v_strresult := 'UPDATE';
  END IF;
  END IF;
  IF (0 <> 0) THEN
  v_strresult := 'ERROR OCCURRED. PLEASE TRY LATER';
  -- ROLLBACK (removed)
  RETURN;
  END IF;
  -- COMMIT (removed)
END;
$$;


--
-- Name: usp_add_update_delete_addfundmanually(character varying, character varying, bigint, numeric, text, character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_add_update_delete_addfundmanually(v_crdrtype character varying DEFAULT 'cr'::character varying, v_wallettype character varying DEFAULT 'ppc'::character varying, v_plid bigint DEFAULT 0, v_depositamount numeric DEFAULT 0, v_remark text DEFAULT ''::text, INOUT v_strresult character varying DEFAULT ''::character varying) RETURNS character varying
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_currentamt numeric(19,4);
  v_aew_id bigint;
  v_oldtotalamt numeric(19,4);
  v_oldcurrentamt numeric(19,4);
BEGIN
  -- BEGIN TRAN (removed)
  v_strresult := 'success^success';
  v_currentamt := 0;
  IF (v_wallettype = 'ppc') THEN
  v_currentamt := 0;
  IF NOT EXISTS(SELECT plid FROM tbl_adsewallet WHERE plid = v_plid) THEN
  SELECT COALESCE(MAX(aew_id), 0) + 1 INTO v_aew_id FROM tbl_adsewallet;
  INSERT INTO tbl_adsewallet (aew_id, plid, total_amount, current_amount, ads_deduct, status) VALUES (v_aew_id, v_plid, 0, 0, 0, 1);
  END IF;
  IF (v_crdrtype = 'cr') THEN
  INSERT INTO tbl_sponserfunddetails (plid, depositamount, datetime, paymenttype, status, depositdate, billid, reqfrom, remark, crdrtype) VALUES (v_plid, v_depositamount, dbo.fun_getCurrentDate(), 'manual', 1, dbo.fun_getCurrentDate(), 0, 'admin', v_remark, 'Cr');
  UPDATE tbl_adsewallet SET total_amount = COALESCE(total_amount, 0) + v_depositamount, current_amount = COALESCE(current_amount, 0) + v_depositamount WHERE plid = v_plid;
  END IF;
  IF (v_crdrtype = 'dr') THEN
  SELECT COALESCE(current_amount, 0) INTO v_currentamt FROM tbl_adsewallet WHERE plid = v_plid;
  IF (COALESCE(v_currentamt, 0) < v_depositamount) THEN
  v_strresult := 'error^Insufficient Balance, Current Balance is ' || CAST(v_currentamt AS VARCHAR(100));
  -- COMMIT (removed)
  ELSE
  INSERT INTO tbl_sponserfunddetails (plid, depositamount, datetime, paymenttype, status, depositdate, billid, reqfrom, remark, crdrtype) VALUES (v_plid, v_depositamount, dbo.fun_getCurrentDate(), 'manual', 1, dbo.fun_getCurrentDate(), 0, 'admin', v_remark, 'Dr');
  UPDATE tbl_adsewallet SET current_amount = COALESCE(current_amount, 0) - v_depositamount WHERE plid = v_plid;
  END IF;
  END IF;
  END IF;
  IF (v_wallettype = 'subs_wallet') THEN
  v_currentamt := 0;
  IF NOT EXISTS(SELECT plid FROM tbl_subscription_wallet WHERE plid = v_plid) THEN
  INSERT INTO tbl_subscription_wallet (plid, total_amount, current_amount, subs_deduct, status) VALUES (v_plid, 0, 0, 0, 1);
  END IF;
  IF (v_crdrtype = 'cr') THEN
  INSERT INTO tbl_subscription_wallet_history (plid, amount, crdrtype, type, remark, date, status, transremark) VALUES (v_plid, v_depositamount, 'Cr', 'subs_wallet', 'Credit By Admin', dbo.fun_getCurrentDate(), 1, v_remark);
  UPDATE tbl_subscription_wallet SET total_amount = COALESCE(total_amount, 0) + COALESCE(v_depositamount, 0), current_amount = COALESCE(current_amount, 0) + COALESCE(v_depositamount, 0) WHERE plid = v_plid;
  END IF;
  IF (v_crdrtype = 'dr') THEN
  SELECT COALESCE(current_amount, 0) INTO v_currentamt FROM tbl_subscription_wallet WHERE plid = v_plid;
  IF (COALESCE(v_currentamt, 0) < v_depositamount) THEN
  v_strresult := 'error^Insufficient Balance, Current Balance is ' || CAST(v_currentamt AS VARCHAR(100));
  -- COMMIT (removed)
  ELSE
  INSERT INTO tbl_subscription_wallet_history (plid, amount, crdrtype, type, remark, date, status, transremark) VALUES (v_plid, v_depositamount, 'Dr', 'subs_wallet', 'Debit By Admin', dbo.fun_getCurrentDate(), 1, v_remark);
  UPDATE tbl_subscription_wallet SET current_amount = COALESCE(current_amount, 0) - COALESCE(v_depositamount, 0) WHERE plid = v_plid;
  END IF;
  END IF;
  END IF;
  IF (0 <> 0) THEN
  v_strresult := 'error^Some error occured';
  -- ROLLBACK (removed)
  RETURN;
  END IF;
  -- COMMIT (removed)
END;
$$;


--
-- Name: usp_add_update_delete_addfundmanually_memberside(character varying, bigint, numeric, text, character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_add_update_delete_addfundmanually_memberside(v_wallettype character varying DEFAULT 'ppc'::character varying, v_plid bigint DEFAULT 0, v_depositamount numeric DEFAULT 0, v_remark text DEFAULT ''::text, INOUT v_strresult character varying DEFAULT ''::character varying) RETURNS character varying
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_currentamt numeric(19,4);
  v_transfertype VARCHAR(150);
  v_currencycode VARCHAR(20);
  v_getcrdrtype VARCHAR(15);
  v_aew_id BIGINT;
  v_tranid VARCHAR(20);
BEGIN
  -- BEGIN TRAN (removed)
  v_strresult := 'success^success';
  v_currentamt := 0;
  v_transfertype := '';
  v_currencycode := '';
  v_getcrdrtype := 'CR';
  SELECT COALESCE(amount, 0) INTO v_currentamt FROM ewallet WHERE plid = v_plid;
  IF (COALESCE(v_depositamount, 0) <= COALESCE(v_currentamt, 0)) THEN
  IF (v_wallettype <> '') THEN
  IF (v_wallettype = 'ppc') THEN
  v_transfertype := 'Trnasfer In Ads Wallet';
  IF NOT EXISTS(SELECT plid FROM tbl_adsewallet WHERE plid = v_plid) THEN
  SELECT COALESCE(MAX(aew_id), 0) + 1 INTO v_aew_id FROM tbl_adsewallet;
  INSERT INTO tbl_adsewallet (aew_id, plid, total_amount, current_amount, ads_deduct, status) VALUES (v_aew_id, v_plid, 0, 0, 0, 1);
  END IF;
  INSERT INTO tbl_sponserfunddetails (plid, depositamount, datetime, paymenttype, status, depositdate, billid, reqfrom, remark, crdrtype) VALUES (v_plid, v_depositamount, dbo.FUN_GETCURRENTDATE(), 'manual', 1, dbo.FUN_GETCURRENTDATE(), 0, 'member', 'Transfer from Earn wallet', 'Cr');
  v_getcrdrtype := 'Cr';
  UPDATE tbl_adsewallet SET total_amount = COALESCE(total_amount, 0) + v_depositamount, current_amount = COALESCE(current_amount, 0) + v_depositamount WHERE plid = v_plid;
  END IF;
  IF (v_wallettype = 'subs_wallet') THEN
  v_transfertype := 'Transfer In Subscription Wallet';
  v_currentamt := 0;
  IF NOT EXISTS(SELECT plid FROM tbl_subscription_wallet WHERE plid = v_plid) THEN
  INSERT INTO tbl_subscription_wallet (plid, total_amount, current_amount, subs_deduct, status) VALUES (v_plid, 0, 0, 0, 1);
  END IF;
  INSERT INTO tbl_subscription_wallet_history (plid, amount, crdrtype, type, remark, date, status, transremark) VALUES (v_plid, v_depositamount, 'Cr', 'subs_wallet', 'Credit By member', dbo.FUN_GETCURRENTDATE(), 1, 'Transfer from Earn wallet');
  v_getcrdrtype := 'Cr';
  UPDATE tbl_subscription_wallet SET total_amount = COALESCE(total_amount, 0) + COALESCE(v_depositamount, 0), current_amount = COALESCE(current_amount, 0) + COALESCE(v_depositamount, 0) WHERE plid = v_plid;
  END IF;
  IF (v_wallettype = 'withdrowal') THEN
  v_wallettype := 'Withdrowal';
  v_transfertype := 'withdrawal';
  v_currentamt := 0;
  IF NOT EXISTS(SELECT plid FROM tbl_withdrawals WHERE plid = v_plid) THEN
  INSERT INTO tbl_withdrawals (plid, type, crdrtype, withdrawamount, admincharge, tds, paybleamount, remainamount, transamount, date, status, remarks) VALUES (v_plid, '', '', 0, 0, 0, 0, 0, 0, dbo.FUN_GETCURRENTDATE(), 1, '');
  END IF;
  v_tranid := '';
  SELECT CAST(RIGHT(CAST(GEN_RANDOM_UUID() AS TEXT), 10) AS VARCHAR(10)) INTO v_tranid;
  INSERT INTO withdrawal_history (plid, crdrtype, trantype, amount, date, remarks, paymode, accountholdername, accountno, bankname, branchname, ifsc, responsetype, status, tranid) VALUES (v_plid, 'Dr', 'withdrawal', v_depositamount, dbo.FUN_GETCURRENTDATE(), 'withdrawal by member', '', '', '', '', '', '', '', 'Pending', '');
  v_getcrdrtype := 'Dr';
  UPDATE tbl_withdrawals SET withdrawamount = COALESCE(withdrawamount, 0) + COALESCE(v_depositamount, 0), paybleamount = COALESCE(paybleamount, 0) + COALESCE(v_depositamount, 0), transamount = COALESCE(transamount, 0) + COALESCE(v_depositamount, 0) WHERE plid = v_plid;
  END IF;
  INSERT INTO member_perfornemce (plid, amount, date, active, trantype, crdrtype) VALUES (v_plid, COALESCE(v_depositamount, 0), dbo.FUN_GETCURRENTDATE(), 1, v_transfertype, v_getcrdrtype);
  UPDATE ewallet SET amount = COALESCE(amount, 0) - COALESCE(v_depositamount, 0), dramount = COALESCE(dramount, 0) + COALESCE(v_depositamount, 0) WHERE plid = v_plid;
  END IF;
  ELSE
  v_strresult := 'error^Insufficient Balance, Current Balance is ' || CAST(v_currentamt AS VARCHAR(100));
  END IF;
  IF (0 <> 0) THEN
  v_strresult := 'error^Some error occured';
  -- ROLLBACK (removed)
  RETURN;
  END IF;
  -- COMMIT (removed)
END;
$$;


--
-- Name: usp_add_update_delete_adsewalletamt(bigint, bigint, numeric, timestamp without time zone, character varying, integer, timestamp without time zone, integer, character varying, text, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_add_update_delete_adsewalletamt(v_sfdid bigint DEFAULT 0, v_plid bigint DEFAULT 0, v_depositamount numeric DEFAULT 0, v_datetime timestamp without time zone DEFAULT NULL::timestamp without time zone, v_paymenttype character varying DEFAULT ''::character varying, v_status integer DEFAULT 1, v_depositdate timestamp without time zone DEFAULT NULL::timestamp without time zone, v_billid integer DEFAULT 0, v_reqfrom character varying DEFAULT 'Admin'::character varying, v_remark text DEFAULT ''::text, INOUT v_intresult integer DEFAULT 0) RETURNS integer
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_aew_id BIGINT;
  v_oldtotalamt numeric(19,4);
  v_oldcurrentamt numeric(19,4);
BEGIN
  -- BEGIN TRAN (removed)
  IF (v_sfdid = 0) THEN
  INSERT INTO tbl_sponserfunddetails (plid, depositamount, datetime, paymenttype, status, depositdate, billid, reqfrom, remark) VALUES (v_plid, v_depositamount, dbo.FUN_GETCURRENTDATE(), 'Manual', 1, dbo.FUN_GETCURRENTDATE(), 0, 'Admin', v_remark);
  IF NOT EXISTS(SELECT 1 FROM tbl_adsewallet WHERE plid = v_plid) THEN
  SELECT COALESCE(MAX(aew_id), 0) + 1 INTO v_aew_id FROM tbl_adsewallet;
  INSERT INTO tbl_adsewallet (aew_id, plid, total_amount, current_amount, ads_deduct, status) VALUES (v_aew_id, v_plid, v_depositamount, v_depositamount, 0, 1);
  ELSE
  SELECT COALESCE(total_amount, 0), COALESCE(current_amount, 0) INTO v_oldtotalamt, v_oldcurrentamt FROM tbl_adsewallet WHERE plid = v_plid;
  UPDATE tbl_adsewallet SET total_amount = v_oldtotalamt + v_depositamount, current_amount = v_oldcurrentamt + v_depositamount WHERE plid = v_plid;
  END IF;
  IF NOT EXISTS(SELECT 1 FROM ewallet WHERE plid = v_plid) THEN
  INSERT INTO ewallet (plid, amount, active, referalcommission, redemption, cramount, dramount, currencysymbol, currentrefferal, currentcramount) VALUES (v_plid, v_depositamount, 1, 0.00, 0.00, v_depositamount, 0.00, '', 0, v_depositamount);
  ELSE
  UPDATE ewallet SET amount = amount + v_depositamount, cramount = cramount + v_depositamount, currentcramount = currentcramount + v_depositamount WHERE plid = v_plid;
  END IF;
  INSERT INTO tbl_accountstatement (plid, cr, dr, balance, date, commentorremark) VALUES (v_plid, v_depositamount, 0.00, (SELECT amount FROM ewallet WHERE plid = v_plid), CURRENT_TIMESTAMP, 'Fund Added By Admin');
  END IF;
  IF (0 <> 0) THEN
  v_intresult := 0;
  -- ROLLBACK (removed)
  RETURN;
  ELSE
  v_intresult := 1;
  END IF;
  -- COMMIT (removed)
END;
$$;


--
-- Name: usp_add_update_delete_employee(text, integer, character varying, character varying, character varying, character varying, character varying, character varying, character varying, character varying, character varying, character varying, character varying, text, integer, integer, character varying, character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_add_update_delete_employee(v_totalroles text, v_emp_id integer, v_emp_password character varying DEFAULT ''::character varying, v_brcode character varying DEFAULT NULL::character varying, v_emp_name character varying DEFAULT ''::character varying, v_emp_email character varying DEFAULT ''::character varying, v_emp_mobile character varying DEFAULT ''::character varying, v_emp_mobile2 character varying DEFAULT ''::character varying, v_emp_statename character varying DEFAULT ''::character varying, v_emp_cityname character varying DEFAULT ''::character varying, v_emp_address character varying DEFAULT ''::character varying, v_emp_pincode character varying DEFAULT ''::character varying, v_emp_panno character varying DEFAULT ''::character varying, v_emp_image text DEFAULT ''::text, v_emp_gender integer DEFAULT NULL::integer, v_intflag integer DEFAULT 0, v_ext character varying DEFAULT 'JPG'::character varying, INOUT v_strresult character varying DEFAULT NULL::character varying) RETURNS character varying
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_getcount INT;
  v_emp_code VARCHAR(50);
  v_totalrolename text;
  v_checkempid BIGINT;
  v_active INT;
BEGIN
  -- BEGIN TRAN (removed)
  v_strresult := 'success';
  v_getcount := 0;
  IF (v_emp_id = 0 AND v_intflag = 0) THEN
  IF (v_totalroles = '') THEN
  v_strresult := 'error^Please select at least one role !';
  -- COMMIT (removed)
  RETURN;
  END IF;
  v_totalrolename := '';
  SELECT v_totalrolename || rolename || '^' INTO v_totalrolename FROM tbl_rolemaster WHERE rid IN (SELECT items FROM dbo.CUSTOMSPLIT(v_totalroles, '^')) AND status = 1;
  v_totalrolename := LEFT(CAST(v_totalrolename AS TEXT), LENGTH(CAST(v_totalrolename AS TEXT)) - 1);
  IF (v_totalrolename = '') THEN
  v_strresult := 'error^Please select at least one role !2' || v_totalrolename;
  -- COMMIT (removed)
  RETURN;
  END IF;
  IF NOT EXISTS(SELECT brid FROM tbl_branch_master WHERE brcode = v_brcode AND active = 1) THEN
  v_strresult := 'error^Invalid Branch/Store ID !';
  -- COMMIT (removed)
  RETURN;
  END IF;
  IF (v_emp_name = '') THEN
  v_strresult := 'error^Please enter employee name !';
  -- COMMIT (removed)
  RETURN;
  END IF;
  SELECT COALESCE(MAX(emp_id), 0) + 1 INTO v_emp_id FROM tbl_employee_master;
  v_emp_code := (500000 + v_emp_id);
  IF (v_emp_image <> '') THEN
  v_emp_image := CAST(v_emp_code AS VARCHAR(50)) || '.' || v_ext;
  END IF;
  INSERT INTO tbl_employee_master (emp_id, emp_code, emp_loginid, emp_password, brcode, emp_name, emp_email, emp_mobile, emp_mobile2, emp_statename, emp_cityname, emp_address, emp_pincode, emp_panno, emp_image, emp_gender, createdate, emp_lastlogin, active, isdelete, current_balance, totalroles) VALUES (v_emp_id, v_emp_code, v_emp_code, v_emp_password, v_brcode, v_emp_name, v_emp_email, v_emp_mobile, v_emp_mobile2, v_emp_statename, v_emp_cityname, v_emp_address, v_emp_pincode, v_emp_panno, v_emp_image, v_emp_gender, dbo.FUN_GETCURRENTDATE(), dbo.FUN_GETCURRENTDATE(), 1, 0, 0, v_totalrolename);
  v_strresult := 'success^Added New^' || CAST(v_emp_code AS VARCHAR(50)) || '^' || CAST(v_emp_image AS VARCHAR(50));
  ELSE
  IF (v_intflag = 1) THEN
  v_checkempid := 0;
  SELECT emp_code INTO v_emp_code FROM tbl_employee_master WHERE emp_id = v_emp_id;
  IF (v_emp_image <> '') THEN
  v_emp_image := CAST(v_emp_code AS VARCHAR(50)) || '.' || v_ext;
  END IF;
  IF NOT EXISTS(SELECT brid FROM tbl_branch_master WHERE brcode = v_brcode AND active = 1) THEN
  v_strresult := 'error^Invalid Branch/Store ID !';
  -- COMMIT (removed)
  RETURN;
  END IF;
  IF (v_emp_name = '') THEN
  v_strresult := 'error^Please enter employee name !';
  -- COMMIT (removed)
  RETURN;
  END IF;
  UPDATE tbl_employee_master SET emp_password = v_emp_password, brcode = v_brcode, emp_name = v_emp_name, emp_email = v_emp_email, emp_mobile = v_emp_mobile, emp_mobile2 = v_emp_mobile2, emp_statename = v_emp_statename, emp_cityname = v_emp_cityname, emp_address = v_emp_address, emp_pincode = v_emp_pincode, emp_panno = v_emp_panno, emp_image = v_emp_image, emp_gender = v_emp_gender, totalroles = v_totalroles WHERE emp_id = v_emp_id;
  v_strresult := 'success^Updated^' || CAST(v_emp_id AS VARCHAR(30)) || '^' || CAST(v_emp_image AS VARCHAR(50));
  ELSE
  v_active := 0;
  SELECT COALESCE(active, 0), emp_code INTO v_active, v_emp_code FROM tbl_employee_master WHERE emp_id = v_emp_id;
  IF (COALESCE(v_active, 0) = 0) THEN
  UPDATE tbl_employee_master SET active = 1 WHERE emp_id = v_emp_id;
  v_strresult := 'success^Active^' || CAST(v_emp_id AS VARCHAR(30)) || '^' || CAST(v_emp_code AS VARCHAR(50));
  ELSE
  UPDATE tbl_employee_master SET active = 0 WHERE emp_id = v_emp_id;
  v_strresult := 'success^Deactive^' || CAST(v_emp_id AS VARCHAR(30)) || '^' || CAST(v_emp_code AS VARCHAR(50));
  END IF;
  END IF;
  END IF;
  IF (0 <> 0) THEN
  v_strresult := 'error^Error occurred  Please try later';
  -- ROLLBACK (removed)
  RETURN;
  END IF;
  -- COMMIT (removed)
END;
$$;


--
-- Name: usp_add_vendor_master(integer, integer, character varying, character varying, integer, character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_add_vendor_master(v_mode integer DEFAULT 1, v_trpid integer DEFAULT 0, v_vendorname character varying DEFAULT ''::character varying, v_vendorcode character varying DEFAULT ''::character varying, v_active integer DEFAULT 0, INOUT v_strresult character varying DEFAULT ''::character varying) RETURNS character varying
    LANGUAGE plpgsql
    AS $$
BEGIN
  -- BEGIN TRAN (removed)
  IF (v_trpid = 0) THEN
  IF EXISTS(SELECT 1 FROM tbl_vendors WHERE vendorname = v_vendorname AND vendorcode = v_vendorcode) THEN
  -- COMMIT (removed)
  v_strresult := 'VENDOR NAME ALREADY EXISTS.';
  RETURN;
  END IF;
  END IF;
  IF (v_vendorname = '') THEN
  -- COMMIT (removed)
  v_strresult := 'VENDOR NAME NOT CORRECT.';
  RETURN;
  END IF;
  IF (v_vendorcode = '') THEN
  -- COMMIT (removed)
  v_strresult := 'VENDOR CODE NOT CORRECT.';
  RETURN;
  END IF;
  IF (v_mode = 1 AND v_trpid = 0) THEN
  IF NOT EXISTS(SELECT 1 FROM tbl_vendors WHERE vendorname = v_vendorname AND vendorcode = v_vendorcode) THEN
  INSERT INTO tbl_vendors (vendorname, vendorcode, active, createdate) VALUES (v_vendorname, v_vendorcode, v_active, dbo.FUN_GETCURRENTDATE());
  v_strresult := 'INSERT';
  END IF;
  ELSE
  IF EXISTS(SELECT 1 FROM tbl_vendors WHERE tvid = v_trpid) THEN
  INSERT INTO tbl_vendors_history (tvid, vendorname, vendorcode, active, createdate, updatedate) SELECT tvid, vendorname, vendorcode, active, createdate, dbo.FUN_GETCURRENTDATE() FROM tbl_vendors WHERE tvid = v_trpid;
  UPDATE tbl_vendors SET vendorname = v_vendorname, vendorcode = v_vendorcode, active = v_active WHERE tvid = v_trpid;
  v_strresult := 'UPDATE';
  END IF;
  END IF;
  IF (0 <> 0) THEN
  v_strresult := 'ERROR OCCURRED. PLEASE TRY LATER';
  -- ROLLBACK (removed)
  RETURN;
  END IF;
  -- COMMIT (removed)
END;
$$;


--
-- Name: usp_addcourier_pincode(character varying, character varying, character varying, character varying, character varying, integer, integer, integer, integer, integer, integer, integer, integer, integer, integer, integer, character varying, character varying, character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_addcourier_pincode(v_delivery character varying DEFAULT ''::character varying, v_pincode character varying DEFAULT ''::character varying, v_region character varying DEFAULT ''::character varying, v_state character varying DEFAULT ''::character varying, v_city character varying DEFAULT ''::character varying, v_prepaid integer DEFAULT 0, v_chkcod integer DEFAULT 0, v_chkreversepickup integer DEFAULT 0, v_status integer DEFAULT 1, v_chkpickup integer DEFAULT 0, v_intresult integer DEFAULT 0, v_tlpid integer DEFAULT 0, v_tcpid integer DEFAULT 0, v_mode integer DEFAULT 2, v_startrowindex integer DEFAULT 1, v_maxrows integer DEFAULT 10, v_fromdate character varying DEFAULT ''::character varying, v_todate character varying DEFAULT ''::character varying, v_logisticname character varying DEFAULT ''::character varying) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_minindex INT;
  v_maxindex INT;
  v_query text;
  v_condition text;
  v_countquery text;
BEGIN
  -- BEGIN TRAN (removed)
  -- SET option (removed)
  v_intresult := 0;
  v_query := '';
  v_condition := '';
  v_countquery := '';
  v_minindex := (v_startrowindex - 1) * v_maxrows + 1;
  v_maxindex := v_startrowindex * v_maxrows;
  IF (v_mode = 1) THEN
  IF EXISTS(SELECT 1 FROM tbl_courierpincodes WHERE deliverytype = v_delivery AND pincode = v_pincode AND region = v_region AND state = v_state AND city = v_city AND tlpid = v_tlpid) THEN
  v_intresult := 1;
  -- COMMIT (removed)
  RETURN;
  ELSE
  INSERT INTO tbl_courierpincodes (tlpid, deliverytype, pincode, city, state, region, prepaid, cod, reversepickup, pickup, createddate, active) VALUES (v_tlpid, v_delivery, v_pincode, v_city, v_state, v_region, v_prepaid, v_chkcod, v_chkreversepickup, v_chkpickup, CURRENT_TIMESTAMP, v_status);
  v_intresult := 2;
  END IF;
  END IF;
  IF (v_mode = 2) THEN
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp (ROWNUMBER int GENERATED BY DEFAULT AS IDENTITY,
 TCPID INT,
 DELIVERYTYPE varchar(100),
 PINCODE varchar(100),
 CITY varchar(100),
STATE varchar(100),
REGION varchar(100),
PREPAID int,
COD int,
REVERSEPICKUP int,
PICKUP int,
CREATEDDATE varchar(50),
ACTIVE  int,
TLPID int,
lOGISTICNAME VARCHAR(100)) ON COMMIT DROP;
  v_query := 'insert into #temp select tCP.TCPID, DELIVERYTYPE,tCP.PINCODE,tCP.CITY,tCP.STATE,
	 tCP.REGION,tCP.PREPAID,tCP.COD,tCP.REVERSEPICKUP,tCP.PICKUP,
	 tCP.CREATEDDATE,tCP.ACTIVE,tCP.TLPID,TLP.NAME from 
	 tbl_courierpincodes tCP leFt join TBL_LOGISTICPARTNERS TLP on TLP.TLPID=
	 tCP.TLPID where 1=1';
  IF (v_logisticname <> '') THEN
  v_query := v_query || ' AND  TLP.NAME=''' || v_logisticname || '''';
  END IF;
  IF (v_fromdate <> '' AND v_todate <> '') THEN
  v_query := v_query || '  AND CONVERT(varchar(50), tCP.CREATEDDATE,105)  >= CONVERT(varchar(50),''' || v_fromdate || ''',105)  
 AND CONVERT(varchar(50), tCP.CREATEDDATE,105) <= CONVERT(varchar(50),''' || v_todate || ''',105)';
  ELSE
  IF (v_fromdate <> '') THEN
  v_query := v_query || '  AND CONVERT(varchar(50), tCP.CREATEDDATE,105) between  CONVERT(varchar(50),''' || v_fromdate || ''',105) AND  CONVERT(varchar(50), DBO.FUN_GETCURRENTDATE(), 105)';
  ELSE
  IF (v_todate <> '') THEN
  v_query := v_query || '  AND CONVERT(varchar(50), tCP.CREATEDDATE,105) between CONVERT(varchar(50),''' || v_todate || ''',105) AND  CONVERT(varchar(50), DBO.FUN_GETCURRENTDATE(), 105)';
  END IF;
  END IF;
  END IF;
  IF (v_region <> '' AND v_state <> '') THEN
  IF (v_region = 'City') THEN
  v_query := v_query || ' and tCP.city=''' || v_state || '''';
  END IF;
  IF (v_region = 'State') THEN
  v_query := v_query || ' and tCP.state=''' || v_state || '''';
  END IF;
  IF (v_region = 'Region') THEN
  v_query := v_query || ' and tCP.REGION=''' || v_state || '''';
  END IF;
  END IF;
  IF (v_city <> '') THEN
  v_query := v_query || ' and tCP.DELIVERYTYPE=''' || v_city || '''';
  END IF;
  IF (v_pincode <> '') THEN
  v_query := v_query || ' and tCP.PINCODE=''' || v_pincode || '''';
  END IF;
  IF (v_tcpid > 0) THEN
  v_query := v_query || ' and tCP.TCPID=' || CAST(v_tcpid AS VARCHAR(50)) || '';
  END IF;
  v_query := v_query || ' order by tCP.CREATEDDATE desc';
  EXECUTE v_query;
  RETURN QUERY SELECT * FROM tmp_temp WHERE rownumber BETWEEN v_minindex AND v_maxindex;
  SELECT COUNT(1) INTO v_intresult FROM tmp_temp;
  END IF;
  IF (v_mode = 3) THEN
  IF EXISTS(SELECT 1 FROM tbl_courierpincodes WHERE deliverytype = v_delivery AND pincode = v_pincode AND region = v_region AND state = v_state AND city = v_city AND tlpid = v_tlpid AND tcpid <> v_tcpid) THEN
  v_intresult := 1;
  -- COMMIT (removed)
  RETURN;
  ELSE
  UPDATE tbl_courierpincodes SET deliverytype = v_delivery, pincode = v_pincode, city = v_city, state = v_state, region = v_region, prepaid = v_prepaid, cod = v_chkcod, reversepickup = v_chkreversepickup, pickup = v_chkpickup, createddate = CURRENT_TIMESTAMP, active = v_status, tlpid = v_tlpid WHERE tcpid = v_tcpid;
  v_intresult := 4;
  END IF;
  END IF;
  -- SET option (removed)
  -- COMMIT (removed)
END;
$$;


--
-- Name: usp_addemailid(text, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_addemailid(v_allemailid text DEFAULT ''::text, INOUT v_intresult integer DEFAULT 0) RETURNS integer
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_slice1 text;
  v_index1 int;
  v_slice2 text;
BEGIN
  -- BEGIN TRAN (removed)
  v_slice1 := '';
  v_slice2 := '';
  v_slice1 := v_allemailid;
  v_index1 := 1;
  WHILE v_index1 <> 0 LOOP
  SELECT POSITION(',' IN v_slice1) INTO v_index1;
  IF v_index1 <> 0 THEN
  SELECT LEFT(CAST(v_slice1 AS TEXT), v_index1 - 1) INTO v_slice2;
  ELSE
  SELECT v_slice1 INTO v_slice2;
  END IF;
  IF (v_slice2 <> '') THEN
  IF NOT EXISTS(SELECT 1 FROM blogsubscription_master WHERE emailid = v_slice2) THEN
  INSERT INTO blogsubscription_master (emailid, subscriptiondate, active, isdeleted) VALUES (v_slice2, CURRENT_TIMESTAMP, 1, 0);
  ELSE
  UPDATE blogsubscription_master SET active = 1, isdeleted = 0 WHERE emailid = v_slice2;
  END IF;
  END IF;
  IF (0 <> 0) THEN
  v_intresult := 0;
  -- ROLLBACK (removed)
  RETURN;
  ELSE
  v_intresult := 1;
  END IF;
  SELECT RIGHT(CAST(v_slice1 AS TEXT), LENGTH(CAST(v_slice1 AS TEXT)) - v_index1) INTO v_slice1;
  IF LENGTH(CAST(v_slice1 AS TEXT)) = 0 THEN
  EXIT;
  END IF;
  END LOOP;
  -- COMMIT (removed)
END;
$$;


