--
-- Name: usp_addfund_bycoupon(integer, character varying, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_addfund_bycoupon(v_slid integer DEFAULT 0, v_couponno character varying DEFAULT ''::character varying, INOUT v_intresult integer DEFAULT NULL::integer) RETURNS integer
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_billindid int;
  v_countryid int;
  v_couponamount numeric(19,4);
BEGIN
  -- SET option (removed)
  v_intresult := 0;
  v_billindid := 0;
  v_countryid := 0;
  v_couponamount := 0;
  SELECT cid INTO v_countryid FROM sponsor_master_detail WHERE plid = v_slid;
  SELECT amount INTO v_couponamount FROM coupon_master WHERE coupon_number = v_couponno;
  SELECT COALESCE(billid, 1) INTO v_billindid FROM tbl_sponserbilling WHERE plid = v_slid AND recentbillinginformation = 1;
  IF EXISTS(SELECT coupon_number FROM coupon_master WHERE cid = v_countryid AND coupon_number = v_couponno AND status = 1) THEN
  INSERT INTO tbl_sponserfunddetails (plid, depositamount, datetime, paymenttype, checkstatus, status, depositdate, billid, fundapprovedate) VALUES (v_slid, v_couponamount, GETUTCDATE(), 'Coupon', 0, 1, GETUTCDATE(), v_billindid, GETUTCDATE());
  UPDATE coupon_master SET status = 0 WHERE coupon_number = v_couponno AND cid = v_countryid;
  v_intresult := 1;
  RETURN;
  ELSE
  IF EXISTS(SELECT coupon_number FROM coupon_master WHERE coupon_number = v_couponno AND cid <> v_countryid AND status = 1) THEN
  v_intresult := 2;
  RETURN;
  ELSE
  IF EXISTS(SELECT coupon_number FROM coupon_master WHERE coupon_number = v_couponno AND status = 0) THEN
  v_intresult := 3;
  RETURN;
  ELSE
  IF NOT EXISTS(SELECT coupon_number FROM coupon_master WHERE coupon_number = v_couponno) THEN
  v_intresult := 0;
  END IF;
  END IF;
  END IF;
  END IF;
  IF (0 <> 0) THEN
  v_intresult := 0;
  RETURN;
  END IF;
  -- SET option (removed)
END;
$$;


