--
-- Name: usp_addfund_in_subswallet(bigint, character varying, numeric, character varying, timestamp without time zone, character varying, character varying, character varying, character varying, character varying, character varying, character varying, character varying, character varying, character varying, character varying, character varying, character varying, numeric, character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_addfund_in_subswallet(v_plid bigint, v_paymenttype character varying, v_depositamount numeric DEFAULT 0, v_checkno character varying DEFAULT ''::character varying, v_depositdate timestamp without time zone DEFAULT NULL::timestamp without time zone, v_bankname character varying DEFAULT ''::character varying, v_branchname character varying DEFAULT ''::character varying, v_accountnumber character varying DEFAULT ''::character varying, v_couponno character varying DEFAULT ''::character varying, v_fromloginid character varying DEFAULT ''::character varying, v_password character varying DEFAULT ''::character varying, v_reqfrom character varying DEFAULT 'member'::character varying, v_remark character varying DEFAULT ''::character varying, v_fname character varying DEFAULT ''::character varying, v_lname character varying DEFAULT ''::character varying, v_emailid character varying DEFAULT ''::character varying, v_contactno character varying DEFAULT ''::character varying, v_ipaddress character varying DEFAULT ''::character varying, v_amountinpound numeric DEFAULT 0, INOUT v_strresult character varying DEFAULT NULL::character varying) RETURNS character varying
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_check_sno INT;
  v_billindid INT;
  v_fromplid BIGINT;
  v_sfdid BIGINT;
  v_businessname VARCHAR(300);
  v_contactname VARCHAR(300);
  v_phonenumber VARCHAR(20);
  v_address VARCHAR(300);
  v_city VARCHAR(100);
  v_postalcode VARCHAR(20);
  v_sid INT;
  v_cid INT;
  v_transid VARCHAR(50);
  v_countryid INT;
  v_couponamount numeric(19,4);
  v_cid_plid INT;
  v_cid_fromplid INT;
  v_currentbalance numeric(19,4);
  v_aew_id BIGINT;
BEGIN
  -- BEGIN TRAN (removed)
  v_billindid := 0;
  v_sfdid := 0;
  v_strresult := 'ok';
  IF (v_paymenttype = 'cash') THEN
  INSERT INTO tbl_sponserfunddetails (plid, depositamount, datetime, paymenttype, depositdate, checkstatus, billid, status, reqfrom, remark, fundtype) VALUES (v_plid, v_depositamount, dbo.FUN_GETCURRENTDATE(), v_paymenttype, v_depositdate, v_checkno, v_billindid, 0, v_reqfrom, v_remark, 'subs_wallet');
  END IF;
  IF (v_paymenttype = 'paypal') THEN
  SELECT CAST(ROUND(CAST(((99999 - 11111 - 1) * RANDOM() + 11111) AS DECIMAL), 0) AS VARCHAR(50)) + CAST(ROUND(CAST(((99999 - 11111 - 1) * RANDOM() + 11111) AS DECIMAL), 0) AS VARCHAR(50)) + CAST(ROUND(CAST(((99999 - 11111 - 1) * RANDOM() + 11111) AS DECIMAL), 0) AS VARCHAR(50)) INTO v_transid;
  INSERT INTO tbl_sponserfunddetails (plid, depositamount, datetime, paymenttype, depositdate, checkstatus, billid, status, reqfrom, remark, fundtype, fname, lname, emailid, contactno, transid, onlinepaystauts, ipaddress, amountinpound) VALUES (v_plid, v_depositamount, dbo.FUN_GETCURRENTDATE(), v_paymenttype, v_depositdate, v_checkno, v_billindid, 0, v_reqfrom, v_remark, 'subs_wallet', v_fname, v_lname, v_emailid, v_contactno, v_transid, 'pending', v_ipaddress, v_amountinpound);
  v_strresult := 'ok^' || v_transid;
  END IF;
  IF (v_paymenttype = 'check') THEN
  INSERT INTO tbl_sponsercheckdetails VALUES (v_plid, v_checkno, v_depositdate, v_bankname, v_branchname, v_accountnumber, v_depositamount);
  SELECT MAX(chk_sno) INTO v_check_sno FROM tbl_sponsercheckdetails;
  INSERT INTO tbl_sponserfunddetails (plid, depositamount, datetime, paymenttype, depositdate, checkstatus, check_sno, billid, status, reqfrom, remark, fundtype) VALUES (v_plid, v_depositamount, dbo.FUN_GETCURRENTDATE(), 'cheque', v_depositdate, 0, v_check_sno, v_billindid, 0, v_reqfrom, v_remark, 'subs_wallet');
  END IF;
  IF (v_paymenttype = 'coupon') THEN
  v_countryid := 0;
  v_couponamount := 0;
  SELECT cid INTO v_countryid FROM sponsor_master_detail WHERE plid = v_plid;
  SELECT amount INTO v_couponamount FROM coupon_master WHERE coupon_number = v_couponno;
  SELECT COALESCE(billid, 1) INTO v_billindid FROM tbl_sponserbilling WHERE plid = v_plid AND recentbillinginformation = 1;
  IF EXISTS(SELECT coupon_number FROM coupon_master WHERE coupon_number = v_couponno AND cid <> v_countryid AND status = 1) THEN
  v_strresult := 'This Coupon is not valid for your Country.';
  -- ROLLBACK (removed)
  RETURN;
  ELSE
  IF EXISTS(SELECT coupon_number FROM coupon_master WHERE coupon_number = v_couponno AND status = 0) THEN
  v_strresult := 'This Coupon is used.';
  -- ROLLBACK (removed)
  RETURN;
  ELSE
  IF NOT EXISTS(SELECT coupon_number FROM coupon_master WHERE coupon_number = v_couponno) THEN
  v_strresult := 'Invalid Coupon No.';
  -- ROLLBACK (removed)
  RETURN;
  ELSE
  IF EXISTS(SELECT coupon_number FROM coupon_master WHERE cid = v_countryid AND coupon_number = v_couponno AND status = 1) THEN
  IF NOT EXISTS(SELECT plid FROM tbl_subscription_wallet WHERE plid = v_plid) THEN
  INSERT INTO tbl_subscription_wallet (plid, total_amount, current_amount, subs_deduct, status) VALUES (v_plid, 0, 0, 0, 1);
  END IF;
  INSERT INTO tbl_sponserfunddetails (plid, depositamount, datetime, paymenttype, checkstatus, status, depositdate, fundapprovedate, reqfrom, remark, coupon_number, fundtype) VALUES (v_plid, v_couponamount, dbo.FUN_GETCURRENTDATE(), 'Coupon', 0, 1, dbo.FUN_GETCURRENTDATE(), dbo.FUN_GETCURRENTDATE(), v_reqfrom, v_remark, v_couponno, 'subs_wallet');
  v_sfdid := IDENT_CURRENT('tbl_sponserfunddetails');
  UPDATE coupon_master SET status = 0 WHERE coupon_number = v_couponno AND cid = v_countryid;
  UPDATE tbl_subscription_wallet SET total_amount = total_amount + v_couponamount, current_amount = current_amount + v_couponamount WHERE plid = v_plid;
  INSERT INTO tbl_subscription_wallet_history (plid, amount, crdrtype, type, remark, date, status) VALUES (v_plid, v_couponamount, 'Cr', 'Coupon', 'From Coupon Redeem', dbo.FUN_GETCURRENTDATE(), 1);
  END IF;
  END IF;
  END IF;
  END IF;
  END IF;
  IF (v_paymenttype = 'ewallet') THEN
  IF NOT EXISTS(SELECT plid FROM portal_login WHERE loginid = v_fromloginid AND password = v_password) THEN
  v_strresult := 'Invalid User ID or password';
  -- COMMIT (removed)
  RETURN;
  END IF;
  IF (v_depositamount <= 0) THEN
  v_strresult := 'Amount should be greater than 0';
  -- COMMIT (removed)
  RETURN;
  END IF;
  SELECT plid INTO v_fromplid FROM portal_login WHERE loginid = v_fromloginid;
  SELECT cid INTO v_cid_plid FROM portal_login WHERE plid = v_plid;
  SELECT cid INTO v_cid_fromplid FROM portal_login WHERE plid = v_fromplid;
  IF (v_cid_plid <> v_cid_fromplid) THEN
  v_strresult := 'Qlook user id should be of same country !';
  -- COMMIT (removed)
  RETURN;
  END IF;
  IF NOT EXISTS(SELECT plid FROM ewallet WHERE plid = v_fromplid) THEN
  v_strresult := 'Insufficient balance in Earned Wallet !';
  -- COMMIT (removed)
  RETURN;
  END IF;
  SELECT COALESCE(amount, 0) INTO v_currentbalance FROM ewallet WHERE plid = v_fromplid;
  IF (v_currentbalance < v_depositamount) THEN
  v_strresult := 'Insufficient balance in wallet !';
  -- COMMIT (removed)
  RETURN;
  END IF;
  IF NOT EXISTS(SELECT plid FROM tbl_subscription_wallet WHERE plid = v_plid) THEN
  INSERT INTO tbl_subscription_wallet (plid, total_amount, current_amount, subs_deduct, status) VALUES (v_plid, 0, 0, 0, 1);
  END IF;
  UPDATE ewallet SET amount = amount - v_depositamount, dramount = dramount + v_depositamount WHERE plid = v_fromplid;
  INSERT INTO member_perfornemce (plid, amount, date, active, trantype) VALUES (v_fromplid, v_depositamount, dbo.FUN_GETCURRENTDATE(), 1, 'Transfer In Subscription Wallet');
  UPDATE tbl_subscription_wallet SET total_amount = total_amount + v_depositamount, current_amount = current_amount + v_depositamount WHERE plid = v_plid;
  INSERT INTO tbl_sponserfunddetails (plid, depositamount, datetime, paymenttype, depositdate, fundapprovedate, billid, fromplid, status, reqfrom, remark, fundtype) VALUES (v_plid, v_depositamount, dbo.FUN_GETCURRENTDATE(), v_paymenttype, dbo.FUN_GETCURRENTDATE(), dbo.FUN_GETCURRENTDATE(), v_billindid, v_fromplid, 1, v_reqfrom, v_remark, 'subs_wallet');
  INSERT INTO tbl_subscription_wallet_history (plid, amount, crdrtype, type, remark, date, status) VALUES (v_plid, v_depositamount, 'Cr', 'Wallet', 'From Earn Wallet', dbo.FUN_GETCURRENTDATE(), 1);
  END IF;
  IF (0 <> 0) THEN
  v_strresult := 'some error occured, please try again !';
  -- ROLLBACK (removed)
  RETURN;
  END IF;
  -- COMMIT (removed)
END;
$$;


--
-- Name: usp_addfundsdetail(integer, integer, integer, character varying, boolean, character varying, character varying, integer, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_addfundsdetail(v_startrowindex integer, v_maxrows integer, v_slid integer DEFAULT 0, v_orderbyfield character varying DEFAULT NULL::character varying, v_asc boolean DEFAULT NULL::boolean, v_searchfield character varying DEFAULT NULL::character varying, v_searchvalue character varying DEFAULT NULL::character varying, v_mode integer DEFAULT NULL::integer, v_recordcount integer DEFAULT NULL::integer) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_regno bigint;
  v_sqlquery text;
BEGIN
  -- SET option (removed)
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp (rowNumber int,

sfdid bigint,

PLID bigint,

DepositAmount varchar(500),

DepositDate varchar(200),

Status varchar(20),

FundApproveDate varchar(200),

PaymentType varchar(50),

Billid bigint,

check_sno varchar(50),

checkstatus  varchar(150)) ON COMMIT DROP;
  v_sqlquery := '';
  v_sqlquery := ' insert into #temp select  ROW_NUMBER() over(order by sfdid desc) as rownumber,

	sfdid,	plid,	DepositAmount as DepositAmount,	convert(varchar(10),DepositDate,105) as DepositDate,

	(CASE WHEN isnull(Status,0) = 0 THEN ''Pending'' WHEN isnull(Status,0) = 1 THEN ''Approved''  WHEN isnull(Status,0) = 2 THEN ''Rejected'' END) as Status ,

	(CASE WHEN FundApproveDate IS not NULL THEN convert(varchar(10),FundApproveDate, 105) ELSE '' ''  END) AS  FundApproveDate ,

	PaymentType,	(case when billid is null then 0 else billid end) as Billid,(case when check_sno is null then ''0'' else check_sno end)as check_sno,

	(case when checkstatus is null then ''0'' else checkstatus end)as checkstatus
	  from tbl_sponserfunddetails where plid=' || CAST(v_slid AS VARCHAR(20)) || ' and isnull(FundType,''ppc'')=''ppc'' and DepositAmount is not null';
  EXECUTE v_sqlquery;
  SELECT COUNT(*) INTO v_recordcount FROM tmp_temp;
  RETURN QUERY SELECT * FROM tmp_temp WHERE rownumber BETWEEN v_startrowindex AND v_maxrows;
  DROP TABLE IF EXISTS tmp_temp;
  RETURN QUERY SELECT v_recordcount AS recordcount;
  -- SET option (removed)
END;
$$;


