	(case when checkstatus is null then ''0'' else checkstatus end)as checkstatus  from tbl_sponserfunddetails 
	where plid=' || CAST(v_slid AS VARCHAR(20)) || ' and isnull(FundType,''ppc'')=''subs_wallet'' and DepositAmount is not null';
