--
-- Name: usp_addmoneyrequests(integer, numeric, character varying, character varying, character varying, character varying, character varying, character varying, character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_addmoneyrequests(v_clid integer DEFAULT 0, v_amount numeric DEFAULT 0, v_source character varying DEFAULT ''::character varying, v_successurl character varying DEFAULT ''::character varying, v_failureurl character varying DEFAULT ''::character varying, v_inprocessurl character varying DEFAULT ''::character varying, v_cancelledurl character varying DEFAULT ''::character varying, v_stroutput character varying DEFAULT ''::character varying, v_transactionid character varying DEFAULT ''::character varying) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_transid VARCHAR(50);
  v_loginid VARCHAR(50);
BEGIN
  BEGIN
  -- BEGIN TRAN (removed)
  IF (v_amount = 0) THEN
  v_stroutput := 'Amount should be greater than zero.';
  -- COMMIT (removed)
  RETURN;
  END IF;
  IF (v_amount < 0) THEN
  v_stroutput := 'Amount should be positive.';
  -- COMMIT (removed)
  RETURN;
  END IF;
  IF (v_clid <> 0) THEN
  IF EXISTS(SELECT 1 FROM tbl_customerlogin WHERE clid = v_clid) THEN
  v_transid := '';
  v_loginid := '';
  v_transid := CAST(CAST(GEN_RANDOM_UUID() AS BYTEA(5)) AS BIGINT) % 1000000000 + 1000000000;
  RETURN QUERY SELECT v_transid;
  SELECT COALESCE(loginid, '') INTO v_loginid FROM tbl_customerlogin WHERE clid = v_clid;
  IF EXISTS(SELECT 1 FROM tbl_addmoneyrequests WHERE transactionid = v_transid) THEN
  v_stroutput := 'Error';
  -- ROLLBACK (removed)
  RETURN;
  ELSE
  INSERT INTO tbl_addmoneyrequests (clid, loginid, transactionid, amount, processdatetime, source, successurl, failureurl, inprocessurl, cancelledurl, status, active) VALUES (v_clid, v_loginid, v_transid, v_amount, dbo.FUN_GETCURRENTDATE(), v_source, v_successurl, v_failureurl, v_inprocessurl, v_cancelledurl, 0, 1);
  v_stroutput := 'Success';
  v_transactionid := v_transid;
  -- COMMIT (removed)
  END IF;
  ELSE
  v_stroutput := 'Invalid customer.';
  -- COMMIT (removed)
  RETURN;
  END IF;
  END IF;
  EXCEPTION WHEN OTHERS THEN
  IF (0 <> 0) THEN
  v_stroutput := 'Error';
  -- ROLLBACK (removed)
  RETURN;
  END IF;
  END;
END;
$$;


--
-- Name: usp_addopeningday(text, text, text, text, text, integer, character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_addopeningday(v_dayid text DEFAULT ''::text, v_opentime text DEFAULT ''::text, v_closetime text DEFAULT ''::text, v_opentime1 text DEFAULT ''::text, v_closetime1 text DEFAULT ''::text, v_pmid integer DEFAULT 0, INOUT v_strresult character varying DEFAULT NULL::character varying) RETURNS character varying
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_slice1 text;
  v_index1 INT;
  v_slice2 text;
  v_slice3 text;
  v_index2 INT;
  v_slice4 text;
  v_slice5 text;
  v_index3 INT;
  v_slice6 text;
  v_slice7 text;
  v_index4 INT;
  v_slice8 text;
  v_slice9 text;
  v_index5 INT;
  v_slice10 text;
BEGIN
  -- SET option (removed)
  v_slice1 := v_dayid;
  v_slice3 := v_opentime;
  v_slice5 := v_closetime;
  v_slice7 := v_opentime1;
  v_slice9 := v_closetime1;
  v_strresult := 'Record Updated successfully';
  v_index1 := 1;
  v_index2 := 1;
  v_index3 := 1;
  v_index4 := 1;
  v_index5 := 1;
  WHILE v_index1 <> 0 AND v_index2 <> 0 AND v_index3 <> 0 LOOP
  SELECT POSITION(',' IN v_slice1) INTO v_index1;
  SELECT POSITION(',' IN v_slice3) INTO v_index2;
  SELECT POSITION(',' IN v_slice5) INTO v_index3;
  SELECT POSITION(',' IN v_slice7) INTO v_index4;
  SELECT POSITION(',' IN v_slice9) INTO v_index5;
  IF v_index1 <> 0 AND v_index2 <> 0 AND v_index3 <> 0 THEN
  SELECT LEFT(CAST(v_slice1 AS TEXT), v_index1 - 1) INTO v_slice2;
  SELECT LEFT(CAST(v_slice3 AS TEXT), v_index2 - 1) INTO v_slice4;
  SELECT LEFT(CAST(v_slice5 AS TEXT), v_index3 - 1) INTO v_slice6;
  SELECT LEFT(CAST(v_slice7 AS TEXT), v_index4 - 1) INTO v_slice8;
  SELECT LEFT(CAST(v_slice9 AS TEXT), v_index5 - 1) INTO v_slice10;
  ELSE
  SELECT v_slice1 INTO v_slice2;
  SELECT v_slice3 INTO v_slice4;
  SELECT v_slice5 INTO v_slice6;
  SELECT v_slice7 INTO v_slice8;
  SELECT v_slice9 INTO v_slice10;
  END IF;
  IF (v_slice2 = 1) THEN
  IF (v_slice4 <> '0') THEN
  INSERT INTO tblopeningdate (officeday, openingtime, closingtime, dayid, pmid, status, openingtimeevening, closingtimeevening, shifttype) VALUES ('Monday', v_slice4, v_slice6, 1, v_pmid, 1, v_slice8, v_slice10, '');
  ELSE
  INSERT INTO tblopeningdate (officeday, status, pmid, dayid) VALUES ('Monday', 0, v_pmid, 1);
  END IF;
  ELSE
  IF (v_slice2 = 2) THEN
  IF (v_slice4 <> '0') THEN
  INSERT INTO tblopeningdate (officeday, openingtime, closingtime, dayid, pmid, status, openingtimeevening, closingtimeevening, shifttype) VALUES ('Tuesday', v_slice4, v_slice6, 2, v_pmid, 1, v_slice8, v_slice10, '');
  ELSE
  INSERT INTO tblopeningdate (officeday, status, pmid, dayid) VALUES ('Tuesday', 0, v_pmid, 2);
  END IF;
