  UPDATE tblopeningdate SET officeday = 'Thursday', openingtime = v_slice4, closingtime = v_slice8, status = 1, openingtimeevening = v_slice10, closingtimeevening = v_slice6 WHERE dayid = 4 AND pmid = v_pmid;
