  IF (v_slice2 = 5) THEN
  IF (v_slice4 <> '0') THEN
  IF (v_slice8 <> '') THEN
  UPDATE tblopeningdate SET officeday = 'Friday', openingtime = v_slice4, closingtime = v_slice8, status = 1, openingtimeevening = v_slice10, closingtimeevening = v_slice6 WHERE dayid = 5 AND pmid = v_pmid;
