--
-- Name: usp_addpowerlegmaster(integer, character varying, integer, integer, character varying, character varying, character varying, character varying, integer, integer, integer, numeric); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_addpowerlegmaster(v_mode integer DEFAULT 1, v_sponserid character varying DEFAULT ''::character varying, v_side integer DEFAULT 0, v_nooflegs integer DEFAULT 0, v_fromdate character varying DEFAULT ''::character varying, v_todate character varying DEFAULT ''::character varying, v_searchtype character varying DEFAULT ''::character varying, v_searchtext character varying DEFAULT ''::character varying, v_startrowindex integer DEFAULT 1, v_maxrows integer DEFAULT 100, v_intresult integer DEFAULT 0, v_businessvolume numeric DEFAULT 0.00) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_query text;
BEGIN
  IF (v_mode = 1) THEN
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp (Rownumber Int GENERATED BY DEFAULT AS IDENTITY,
TAPLMID Int,
SponserID Varchar(500),
Side Varchar(50),
NoofLegs Varchar(50),
AddedDate Varchar(500),
IsActive Int,
IsDeleted Int,
BusinessVolume Decimal(10,2)) ON COMMIT DROP;
  v_query := '';
  v_query := v_query || ('Insert Into #Temp Select TAPLMID ,SponserID,
(Case When Side = 1 Then ''Left'' When Side = 2 Then ''Right'' When Side = 3 Then ''Auto'' End) As Side,NoofLegs,
Convert(Varchar(11),AddedDate,106) As AddedDate,IsActive,IsDeleted,BusinessVolume	
From Tbl_AddedPowerLegMaster Where IsDeleted = 0 ');
  IF (v_searchtext <> '') THEN
  v_query := v_query || (' And SponserID Like ''%' || v_searchtext || '%'' ');
  END IF;
  IF (v_fromdate <> '' AND v_todate <> '') THEN
  v_query := v_query || (' And  Convert(Varchar,AddedDate,110) Between ''' || CAST(TO_CHAR(v_fromdate, 'MM-DD-YYYY') AS VARCHAR(30)) || ''' And ''' || CAST(TO_CHAR(v_todate, 'MM-DD-YYYY') AS VARCHAR(30)) || ''' ');
  END IF;
  IF (v_fromdate <> '') THEN
  v_query := v_query || (' AND CONVERT(Varchar, AddedDate,110) >= CONVERT(Varchar,''' || v_fromdate || ''',110) ');
  END IF;
  IF (v_todate <> '') THEN
  v_query := v_query || (' AND CONVERT(Varchar, AddedDate,110)  <= CONVERT(Varchar,''' || v_todate || ''',110) ');
  END IF;
  v_query := v_query || (' Order by Taplmid desc');
  EXECUTE v_query;
  RETURN QUERY SELECT * FROM tmp_temp WHERE rownumber BETWEEN v_startrowindex AND v_maxrows;
  RETURN QUERY SELECT COUNT(1) AS totalrows FROM tmp_temp;
  DROP TABLE IF EXISTS tmp_temp;
  END IF;
  IF (v_mode = 2) THEN
  IF EXISTS(SELECT 1 FROM portal_login WHERE username = v_sponserid) THEN
  INSERT INTO tbl_addedpowerlegmaster (sponserid, side, nooflegs, addeddate, isactive, isdeleted, businessvolume) VALUES (v_sponserid, v_side, v_nooflegs, CURRENT_TIMESTAMP, 1, 0, v_businessvolume);
  v_intresult := 1;
  ELSE
  v_intresult := 2;
  END IF;
  END IF;
END;
$$;


