CREATE FUNCTION dbo.usp_addproductbv_pv(v_maincatid integer DEFAULT 0, v_catid integer DEFAULT 0, v_subcatid integer DEFAULT 0, v_comission numeric DEFAULT 0, v_bv numeric DEFAULT 0, v_pv numeric DEFAULT 0, v_did integer DEFAULT 0, INOUT v_result character varying DEFAULT ''::character varying) RETURNS character varying
