  UPDATE tbl_product_wise_bv_pv_setting SET bv = v_bv, pv = v_pv, update_date = dbo.FUN_GETCURRENTDATE(), update_by = v_did WHERE maincatid = v_maincatid AND catid = v_catid AND subcatid = v_subcatid AND did = v_did;
  v_result := 'UPDATE';
  ELSE
  INSERT INTO tbl_product_wise_bv_pv_setting (did, maincatid, catid, subcatid, commission, bv, pv, create_date, created_by) VALUES (v_did, v_maincatid, v_catid, v_subcatid, v_comission, v_bv, v_pv, dbo.FUN_GETCURRENTDATE(), v_did);
  v_result := 'UPDATE';
  END IF;
  -- COMMIT (removed)
  IF (0 <> 0) THEN
  PERFORM dbo.sp_errorlog();
  v_result := 'ERROR IN REQUEST';
  -- ROLLBACK (removed)
  END IF;
END;
$$;


