CREATE FUNCTION dbo.usp_addtocartprocess(v_tkpmid integer DEFAULT 0, v_regno bigint DEFAULT 0, v_frid integer DEFAULT 0, v_qty integer DEFAULT 0, v_mode integer DEFAULT 0, INOUT v_stroutput character varying DEFAULT ''::character varying, INOUT v_strcount integer DEFAULT 0, v_uidno character varying DEFAULT ''::character varying) RETURNS record
    LANGUAGE plpgsql
    AS $$
BEGIN
  BEGIN
  -- BEGIN TRAN (removed)
  IF (v_mode = 1) THEN
  IF EXISTS(SELECT 1 FROM dbo.tbl_addtocart WHERE sessionid = v_uidno AND sprid = v_tkpmid AND status = 1) THEN
  v_stroutput := 'SUCCESS';
  ELSE
  IF (v_regno > 0) THEN
  INSERT INTO dbo.tbl_addtocart VALUES (v_tkpmid, v_regno, v_qty, dbo.FUN_GETCURRENTDATE(), 1, v_uidno);
  END IF;
  v_stroutput := 'SUCCESS';
  END IF;
  v_strcount := (SELECT COUNT(1) FROM dbo.tbl_addtocart WHERE sessionid = v_uidno AND status = 1);
  -- COMMIT (removed)
  END IF;
  IF (v_regno > 0) THEN
  UPDATE tbl_addtocart SET clid = v_regno WHERE sessionid = v_uidno AND status = 1;
  END IF;
  IF (v_mode = 2) THEN
  IF EXISTS(SELECT 1 FROM dbo.tbl_addtocart WHERE sessionid = v_uidno AND sprid = v_tkpmid AND status = 1) THEN
  UPDATE dbo.tbl_addtocart SET status = 0, createddate = dbo.FUN_GETCURRENTDATE() WHERE sessionid = v_uidno AND sprid = v_tkpmid AND status = 1;
  v_stroutput := 'SUCCESS';
  ELSE
  v_stroutput := 'Item does not exists in your cart';
  -- ROLLBACK (removed)
  RETURN;
  END IF;
  v_strcount := (SELECT COUNT(1) FROM dbo.tbl_addtocart WHERE sessionid = v_uidno AND status = 1);
  -- COMMIT (removed)
  END IF;
  IF (v_mode = 7) THEN
  IF EXISTS(SELECT 1 FROM dbo.tbl_addtocart WHERE sessionid = v_uidno AND status = 1) THEN
  UPDATE dbo.tbl_addtocart SET clid = v_regno WHERE sessionid = v_uidno AND status = 1;
  v_stroutput := 'SUCCESS';
  ELSE
  v_stroutput := 'Item does not exists in your cart';
  -- ROLLBACK (removed)
  RETURN;
  END IF;
  v_strcount := (SELECT COUNT(1) FROM dbo.tbl_addtocart WHERE sessionid = v_uidno AND status = 1);
  -- COMMIT (removed)
  END IF;
  EXCEPTION WHEN OTHERS THEN
  IF (0 <> 0) THEN
  -- ROLLBACK (removed)
  v_stroutput := sqlerrm;
  RETURN;
  END IF;
  END;
END;
$$;


