--
-- Name: usp_admin_banklist(integer, integer, character varying, character varying, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_admin_banklist(v_startrowindex integer DEFAULT 1, v_maxrows integer DEFAULT 99999, v_fromdate character varying DEFAULT ''::character varying, v_todate character varying DEFAULT ''::character varying, v_totalcount integer DEFAULT 0) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_minindex INT;
  v_maxindex INT;
  v_query text;
BEGIN
  -- SET option (removed)
  v_minindex := (v_startrowindex - 1) * v_maxrows + 1;
  v_maxindex := v_startrowindex * v_maxrows;
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp (ROWNUMBER bigint GENERATED BY DEFAULT AS IDENTITY,
TABDID bigint,
EmpId bigint,
AccountHolderName varchar(100),
AccountNo varchar(100),
BankName varchar(100),
BranchName varchar(100),
IFSCCode varchar(100),
Date varchar(100),
UpdateDate varchar(100),
Status varchar(100),
Active int,
LOGO varchar(100),
Filename varchar(100)) ON COMMIT DROP;
  v_query := ' INSERT INTO #TEMP Select TABDID,EmpId,AccountHolderName,AccountNo,BankName,BranchName,IFSCCode,Date,UpdateDate
,Status,Active,LOGO,Filename from Tbl_Admin_BankDetails ';
  IF (v_fromdate <> '' AND v_todate = '') THEN
  v_query := v_query || (' AND Convert(date,TA.Updatedate,105) >= Convert(date,''' || v_fromdate || ''',105)');
  END IF;
  IF (v_fromdate = '' AND v_todate <> '') THEN
  v_query := v_query || (' AND CONVERT(DATE,TA.Updatedate,105) <= CONVERT(DATE,''' || v_todate || ''',105) ');
  END IF;
  IF (v_fromdate <> '' AND v_todate <> '') THEN
  v_query := v_query || (' AND CONVERT(DATE,TA.Updatedate,105) BETWEEN CONVERT(DATE,''' || v_fromdate || ''',105) AND CONVERT(DATE,''' || v_todate || ''',105)');
  END IF;
  EXECUTE v_query;
  RAISE NOTICE '%', (v_query);
  RETURN QUERY SELECT * FROM tmp_temp WHERE rownumber BETWEEN v_minindex AND v_maxindex;
  SELECT COUNT(rownumber) INTO v_totalcount FROM tmp_temp;
  DROP TABLE IF EXISTS tmp_temp;
  -- SET option (removed)
END;
$$;


