-- Name: usp_admin_campaigndetail(integer, bigint, bigint, integer, integer, integer, boolean, integer, text, character varying, character varying, text, character varying, character varying, character varying, character varying, character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_admin_campaigndetail(v_slid integer DEFAULT 0, v_cid bigint DEFAULT 96, v_ctid bigint DEFAULT 0, v_startrowindex integer DEFAULT 0, v_maxrows integer DEFAULT 0, v_mode integer DEFAULT 0, v_asc boolean DEFAULT false, v_recordcount integer DEFAULT 0, v_loginids text DEFAULT ''::text, v_orderbyfield character varying DEFAULT ''::character varying, v_status character varying DEFAULT ''::character varying, v_championname text DEFAULT ''::text, v_orderbyclick character varying DEFAULT ''::character varying, v_orderbycost character varying DEFAULT ''::character varying, v_fromdate character varying DEFAULT ''::character varying, v_todate character varying DEFAULT ''::character varying, v_cat character varying DEFAULT ''::character varying) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_sqlquery text;
  v_cateid VARCHAR(100);
BEGIN
  SELECT cid INTO v_cid FROM settings WHERE caption = 'Active Country';
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp (NUMBER BIGINT,
PLID BIGINT,
LOGINID text,
CTID text,
CID BIGINT, 
SMID BIGINT,
CAMPAINNAME text,
IMAGENAME text,
CURRENCYCODE text,
BUDJETPERDAY numeric(19,4),
SMCID BIGINT,
KEYWORDID text,
CAMPAINCREATEDATE timestamp,
TOTALDEDUCTAMOUNT numeric(19,4),
NOOFCLICKS BIGINT,
ADTYPE text,
DESCRIPTIONLINE1 text,
STATUS text) ON COMMIT DROP;
  IF (v_cid = 0) THEN
  v_cid := 96;
  END IF;
  v_sqlquery := 'INSERT INTO #TEMP SELECT ROW_NUMBER() OVER (ORDER BY CAMPAINCREATEDATE DESC ) AS NUMBER,TSMC.PLID,PL.LOGINID,TSMC.CTID,TSMC.CID,TSMC.SMID,CAMPAINNAME,
	TSMC.IMAGENAME,CON.CURRENCYCODE,BUDJETPERDAY,TSMC.SMCID,TSMC.KEYWORDID,
		CONVERT(DATE, TSMC.CAMPAINCREATEDATE,103) AS CAMPAINCREATEDATE,ISNULL(SFD.ADS_DEDUCT,0) AS TOTALDEDUCTAMOUNT ,ISNULL(SFD.NOOFCLICKS,0) AS NOOFCLICKS,
		CASE  WHEN ADTYPE=0 THEN ''TEXT'' WHEN ADTYPE=1 THEN ''IMAGE''  END AS ADTYPE, TSMC.DESCRIPTIONLINE1,CASE
		WHEN CAMPACTIVE=0 THEN ''DEACTIVE'' WHEN CAMPACTIVE=1 THEN ''ACTIVE''  WHEN CAMPACTIVE=2 THEN ''POUSE''  END AS STATUS FROM 
		TBL_SPONSOR_MASTER_CAMPAIN TSMC INNER JOIN SPONSOR_MASTER_DETAIL TSM ON TSM.PLID=TSMC.PLID
		  INNER JOIN PORTAL_LOGIN PL ON PL.PLID=TSMC.PLID LEFT JOIN (SELECT SMCID,SUM(NOOFHITS*BID_PRICE) AS ADS_DEDUCT,SUM(NOOFHITS) AS NOOFCLICKS
		  FROM TBL_KEYWORD_IN_SPONSORAD GROUP BY SMCID) SFD ON TSMC.SMCID=SFD.SMCID LEFT JOIN COUNTRY CON ON CON.CID=' || CAST(v_cid AS VARCHAR(10)) || '  WHERE TSMC.CID =' || CAST(v_cid AS VARCHAR(10));
  IF (v_slid > 0) THEN
  v_sqlquery := v_sqlquery || '  AND PL.PLID IN  (SELECT PLID FROM SPONSOR_MASTER_DETAIL WHERE SMDID =' || CAST(v_slid AS VARCHAR(30)) || ')';
  END IF;
  IF (v_todate <> '' AND v_fromdate = '') THEN
  v_fromdate := v_todate;
  ELSE
  IF (v_todate = '' AND v_fromdate <> '') THEN
  v_todate := v_fromdate;
  END IF;
  END IF;
  IF (v_todate <> '' AND v_fromdate <> '') THEN
  v_sqlquery := v_sqlquery || ' AND CONVERT(DATE,  TSMC.CAMPAINCREATEDATE,105)  BETWEEN CONVERT(DATE,''' || v_fromdate || ''',105) AND CONVERT(DATE,''' || v_todate || ''',105)';
  END IF;
  IF (v_status <> '') THEN
  v_sqlquery := v_sqlquery || '  AND CAMPACTIVE LIKE ''%' || v_status || '%''';
  END IF;
  IF (v_ctid > 0) THEN
  v_sqlquery := v_sqlquery || ' AND (TSMC.CTID) LIKE ''%,' || v_ctid || ',%''';
  END IF;
  IF (v_loginids <> '') THEN
  v_sqlquery := v_sqlquery || '  AND LOGINID LIKE ''%' || v_loginids || '%''';
  END IF;
  IF (v_championname <> '') THEN
  v_sqlquery := v_sqlquery || '  AND CAMPAINNAME LIKE ''%' || v_championname || '%''';
  END IF;
  IF ((v_orderbyclick <> '') AND (v_orderbycost <> '')) THEN
  v_sqlquery := v_sqlquery || '   ORDER BY NOOFCLICKS ' || v_orderbyclick || ' , BUDJETPERDAY ' || v_orderbycost || '';
  END IF;
  IF ((v_orderbyclick <> '') AND (v_orderbycost = '')) THEN
  v_sqlquery := v_sqlquery || '   ORDER BY NOOFCLICKS ' || v_orderbyclick || '';
  END IF;
  IF ((v_orderbyclick = '') AND (v_orderbycost <> '')) THEN
  v_sqlquery := v_sqlquery || '  ORDER BY BUDJETPERDAY ' || v_orderbycost || '';
  END IF;
  IF ((v_orderbyclick = '') AND (v_orderbycost = '')) THEN
  v_sqlquery := v_sqlquery || '   ORDER BY CAMPAINCREATEDATE DESC';
  END IF;
  EXECUTE v_sqlquery;
  SELECT COUNT(*) INTO v_recordcount FROM tmp_temp;
  IF (v_cat <> '') THEN
  SELECT catid INTO v_cateid FROM product_category WHERE catname = v_cat;
  RETURN QUERY SELECT * FROM tmp_temp WHERE smcid IN (SELECT DISTINCT smcid FROM tbl_keyword_in_sponsorad WHERE catid = v_cateid);
  ELSE
  RETURN QUERY SELECT * FROM tmp_temp;
  END IF;
  DROP TABLE IF EXISTS tmp_temp;
END;
$$;


--
-- Name: usp_admin_campaigndetail1(integer, integer, character varying, boolean, text, character varying, character varying, integer, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_admin_campaigndetail1(v_startrowindex integer, v_maxrows integer, v_orderbyfield character varying, v_asc boolean, v_loginids text DEFAULT ''::text, v_fromdate character varying DEFAULT NULL::character varying, v_todate character varying DEFAULT NULL::character varying, v_mode integer DEFAULT 0, v_recordcount integer DEFAULT NULL::integer) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF (v_todate = '' AND v_fromdate = '') THEN
  RETURN QUERY SELECT ROW_NUMBER() OVER (ORDER BY tsmc.smid NULLS FIRST) AS number, tsmc.plid, pl.loginid, tsmc.ctid, tsmc.cid, tsmc.smid, campainname, tsmc.imagename, budjetperday, tsmc.smcid, tsmc.keywordid, CAST(TO_CHAR(tsmc.campaincreatedate, 'DD TMMon YYYY') AS text) AS campaincreatedate, COALESCE(sfd.ads_deduct, 0) AS totaldeductamount, COALESCE(sfd.noofclicks, 0) AS noofclicks, CASE WHEN adtype = 0 THEN 'Text' WHEN adtype = 1 THEN 'Image' END AS adtype, tsmc.descriptionline1, CASE WHEN campactive = 0 THEN 'Deactive' WHEN campactive = 1 THEN 'Active' WHEN campactive = 2 THEN 'Pouse' END AS status FROM tbl_sponsor_master_campain AS tsmc INNER JOIN sponsor_master_detail AS tsm ON tsm.plid = tsmc.plid INNER JOIN portal_login AS pl ON pl.plid = tsmc.plid LEFT JOIN (SELECT smcid, SUM(noofhits * bid_price) AS ads_deduct, SUM(noofhits) AS noofclicks FROM tbl_keyword_in_sponsorad GROUP BY smcid) AS sfd ON tsmc.smcid = sfd.smcid;
  ELSE
  RETURN QUERY SELECT ROW_NUMBER() OVER (ORDER BY tsmc.smid NULLS FIRST) AS number, tsmc.plid, pl.loginid, tsmc.ctid, tsmc.cid, tsmc.smid, campainname, tsmc.imagename, budjetperday, tsmc.smcid, tsmc.keywordid, CAST(TO_CHAR(tsmc.campaincreatedate, 'DD TMMon YYYY') AS text) AS campaincreatedate, COALESCE(sfd.ads_deduct, 0) AS totaldeductamount, COALESCE(sfd.noofclicks, 0) AS noofclicks, CASE WHEN adtype = 0 THEN 'Text' WHEN adtype = 1 THEN 'Image' END AS adtype, tsmc.descriptionline1, CASE WHEN campactive = 0 THEN 'Deactive' WHEN campactive = 1 THEN 'Active' WHEN campactive = 2 THEN 'Pouse' END AS status FROM tbl_sponsor_master_campain AS tsmc INNER JOIN sponsor_master_detail AS tsm ON tsm.plid = tsmc.plid INNER JOIN portal_login AS pl ON pl.plid = tsmc.plid LEFT JOIN (SELECT smcid, SUM(noofhits * bid_price) AS ads_deduct, SUM(noofhits) AS noofclicks FROM tbl_keyword_in_sponsorad GROUP BY smcid) AS sfd ON tsmc.smcid = sfd.smcid WHERE CAST(TO_CHAR(tsmc.campaincreatedate, 'DD-MM-YYYY') AS text) BETWEEN v_fromdate AND v_todate;
  END IF;
END;
$$;


--
-- Name: usp_admin_deal_details(character varying, integer, integer, character varying, character varying, integer, character varying, character varying, character varying, character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_admin_deal_details(v_dealid character varying DEFAULT ''::character varying, v_startrowindex integer DEFAULT 1, v_maxrows integer DEFAULT 100, v_fromdate character varying DEFAULT ''::character varying, v_todate character varying DEFAULT ''::character varying, v_recordcount integer DEFAULT 0, v_reqfield character varying DEFAULT ''::character varying, v_searchvalue character varying DEFAULT ''::character varying, v_searchtext character varying DEFAULT ''::character varying, v_status character varying DEFAULT ''::character varying) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_sqlquery text;
  v_date VARCHAR(100);
BEGIN
  -- SET option (removed)
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp (ROWS INT,
DEALID INT,
PMID INT,
TITLE varchar(100),
OFFER VARCHAR(200),
IMAGES VARCHAR(250),
DESCRIPTION text,
DISCOUNT INT,
STARTPRICE INT,
FROMTIME varchar(50),
TOTIME varchar(50),
TERMS text,
HIGHLIGHTS text,
CREATEDATE VARCHAR(50),
ACTIVE smallint,
VERIFY smallint,
APPROVEDDATE VARCHAR(50),
REJECTDATE VARCHAR(50),
REJECTREASON text,
LoginID Varchar(200),
ShortDescription Varchar(100)) ON COMMIT DROP;
  v_sqlquery := '';
  v_sqlquery := ' INSERT INTO #TEMP SELECT ROW_NUMBER() OVER(ORDER BY PDM.TITLE) AS ROWS ,PDM.DEALID,
PDM.PMID,PDM.TITLE,PDM.OFFER,LEFT(PDM.IMAGES, CHARINDEX ('','', PDM.IMAGES + '','') - 1) AS IMAGES ,
PDM.DESCRIPTION,PDM.DISCOUNT,PDM.STARTPRICE,Convert(Varchar(20),PDM.FROMTIME,106) AS FROMTIME,
Convert(Varchar(20),PDM.TOTIME,106) AS TOTIME,PDM.TERMS,PDM.HIGHLIGHTS,
Convert(Varchar(20),PDM.CREATEDATE,106) AS CREATEDATE,PDM.ACTIVE,PDM.VERIFY,
(Case When IsNull(Convert(Varchar(20),PDM.APPROVEDDATE,106),'''')='''' Then ''N/A'' Else Convert(Varchar(20),PDM.APPROVEDDATE,106) End) As APPROVEDDATE,
(Case When IsNull(Convert(Varchar(20),PDM.REJECTDATE,106),'''')='''' Then ''N/A'' Else Convert(Varchar(20),PDM.REJECTDATE,106) End) As REJECTDATE,
(Case When IsNull(PDM.REJECTREASON,'''')= '''' Then ''N/A'' Else REJECTREASON End) As REJECTREASON,
(Select LOGINID from PORTAL_LOGIN where plid in (Select distinct plid from PORTAL_MASTER pm where pm.PMID=Pdm.PMID)) As LoginID,
(Case When Len(PDM.DESCRIPTION)>50 Then Substring(PDM.DESCRIPTION,0,50)+ ''... '' Else PDM.DESCRIPTION End ) As ShortDescription
FROM PORTAL_DEAL_MASTER PDM Left Join Portal_Login PL On PDM.PMID = PL.PLID 
WHERE (ISNULL(PDM.ACTIVE,0) IN (0,1)) AND  (ISNULL(PDM.VERIFY,0) IN (0,1,2))';
  IF (v_dealid <> '') THEN
  v_sqlquery := v_sqlquery || (' AND DEALID=' || v_dealid || '');
  END IF;
  IF (v_reqfield <> '') THEN
  IF (v_reqfield = '1') THEN
  v_date := 'PDM.CREATEDATE';
  END IF;
  IF (v_reqfield = '2') THEN
  v_date := 'PDM.FROMTIME';
  END IF;
  IF (v_reqfield = '3') THEN
  v_date := 'PDM.TOTIME';
  END IF;
  IF (v_fromdate <> '' AND v_todate <> '') THEN
  v_sqlquery := v_sqlquery || (' AND CONVERT(varchar(20),' || v_date || ',105) BETWEEN ''' || CAST(v_fromdate AS VARCHAR(200)) || ''' AND ''' || CAST(v_todate AS VARCHAR(200)) || ''' ');
  ELSE
  IF (v_fromdate <> '' OR v_todate <> '') THEN
  IF (v_fromdate <> '') THEN
  v_sqlquery := v_sqlquery || (' AND CONVERT(varchar(20),' || v_date || ',105) >= ''' || CAST(v_fromdate AS VARCHAR(200)) || '''');
  END IF;
  IF (v_todate <> '') THEN
  v_sqlquery := v_sqlquery || (' AND CONVERT(varchar(20),' || v_date || ',105) <= ''' || CAST(v_todate AS VARCHAR(200)) || '''');
  END IF;
  END IF;
  END IF;
  END IF;
  IF (v_status <> '') THEN
  v_sqlquery := v_sqlquery || ('AND PDM.VERIFY=''' || v_status || '''');
  END IF;
  IF (v_searchvalue = 'title') THEN
  IF (v_searchtext <> '') THEN
  v_sqlquery := v_sqlquery || ('AND PDM.TITLE LIKE ''%' || v_searchtext || '%''');
  END IF;
  END IF;
  EXECUTE v_sqlquery;
  SELECT COUNT(dealid) INTO v_recordcount FROM tmp_temp;
  RETURN QUERY SELECT ROW_NUMBER() OVER (ORDER BY dealid DESC NULLS LAST) AS rownumber, * FROM tmp_temp WHERE rows BETWEEN v_startrowindex AND v_maxrows ORDER BY dealid DESC NULLS LAST;
  IF (0 <> 0) THEN
  v_recordcount := 0;
  END IF;
  DROP TABLE IF EXISTS tmp_temp;
  RETURN QUERY SELECT v_recordcount AS recordcount;
  -- SET option (removed)
END;
$$;


--
-- Name: usp_admin_get_all_bv_report(integer, integer, character varying, character varying, character varying, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_admin_get_all_bv_report(v_startrowindex integer DEFAULT 1, v_maxrows integer DEFAULT 1000, v_fromdate character varying DEFAULT ''::character varying, v_todate character varying DEFAULT ''::character varying, v_resellername character varying DEFAULT ''::character varying, v_totalcount integer DEFAULT 0) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_minindex INT;
  v_maxindex INT;
  v_query text;
  v_condition text;
  v_countquery text;
  v_trpid INT;
  v_mindate VARCHAR(100);
  v_maxdate VARCHAR(100);
BEGIN
  -- BEGIN TRAN (removed)
  -- SET option (removed)
  v_condition := '';
  v_countquery := '';
  v_trpid := 0;
  v_mindate := '';
  v_maxdate := '';
  v_minindex := (v_startrowindex - 1) * v_maxrows + 1;
  v_maxindex := v_startrowindex * v_maxrows;
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp (ROWNUMBER INT GENERATED BY DEFAULT AS IDENTITY,
 CUSTOMERNAME VARCHAR(100),
 MOBILENO VARCHAR(100),
 DATE VARCHAR(100),
 BVPERCNTAGE DECIMAL(18,2),
 BV DECIMAL(18,2),
 ORDERID VARCHAR(100),
 ORDERNO VARCHAR(100),
 ORDERSTATUS INT,
 ORDERDERCYCLESTATUS VARCHAR(100),
 BENIFICARYID VARCHAR(100),
 TYPE VARCHAR(100),
 COMPANYNAME VARCHAR(100)) ON COMMIT DROP;
  v_query := ' INSERT INTO #TEMP SELECT (CL.FNAME+'' ''+CL.LNAME) AS NAME,CL.PHONE,CONVERT(VARCHAR,TRBVM.CREATE_DATE,106) AS DATE, 
ISNULL(TRBVD.BVPERCENTAGE,0),ISNULL(TRBVD.BVALUE,0) ,ISNULL(TRBVM.ORDERID,''N/A''),ISNULL(TRBVD.ORDERNO,''N/A''),
ISNULL(POM.INTSTATUS,0),(CASE WHEN POM.INTSTATUS in (0,2,3,4,5) THEN ''Pending'' WHEN POM.INTSTATUS=6 THEN ''Completed'' WHEN POM.INTSTATUS=7 THEN ''Cancelled''
 WHEN POM.INTSTATUS=9 THEN ''Out for Delivery'' END),
ISNULL(TRUN.USERNAME,''N/A''),ISNULL(TRS.SERVICENAME,''N/A''),ISNULL(DM.COMPANYNAME,'''')
FROM TBL_RESELLER_BV_PV_MASTER TRBVM  
LEFT JOIN TBL_RESELLER_BV_PV_DETAILS TRBVD ON TRBVM.COMID=TRBVD.COMID
LEFT JOIN TBL_PRODUCT_ORDER_MASTER POM ON  TRBVD.ORDERNO=POM.ORDERNO
LEFT JOIN TBL_CUSTOMERLOGIN CL ON POM.LOGINID=CL.LOGINID
LEFT JOIN TBL_RESELLER_SERVICES TRS ON TRBVD.TYPE=TRS.TRSID
LEFT JOIN TBL_REFERENCEUSERNAME TRUN ON CL.CLID=TRUN.CLID AND TRUN.STATUS=1
LEFT JOIN DISTRIBUTOR_MASTER DM ON TRBVM.DID=DM.PLID
WHERE TRBVD.RELEASEDSTATUS=0 ';
  IF ((v_fromdate <> '') AND (v_todate = '')) THEN
  v_query := v_query || ' AND CONVERT(DATE, TRBVM.CREATE_DATE,103) =  CONVERT(DATE, ''' || v_fromdate || ''',103)';
  END IF;
  IF ((v_fromdate = '') AND (v_todate <> '')) THEN
  v_query := v_query || ' AND CONVERT(DATE, TRBVM.CREATE_DATE,103) =  CONVERT(DATE, ''' || v_todate || ''',103) ';
  END IF;
  IF ((v_fromdate <> '') AND (v_todate <> '')) THEN
  v_query := v_query || ' AND CONVERT(DATE, TRBVM.CREATE_DATE,103) BETWEEN CONVERT(DATE, ''' || v_fromdate || ''',103) AND  CONVERT(DATE, ''' || v_todate || ''',103) ';
  END IF;
  IF (v_resellername <> '') THEN
  v_query := v_query || ' And DM.COMPANYNAME=''' || CAST(v_resellername AS VARCHAR(30)) || '''';
  END IF;
  EXECUTE v_query;
  RAISE NOTICE '%', v_query;
  RETURN QUERY SELECT * FROM tmp_temp WHERE rownumber BETWEEN v_minindex AND v_maxindex;
  SELECT COUNT(rownumber) INTO v_totalcount FROM tmp_temp;
  DROP TABLE IF EXISTS tmp_temp;
  -- COMMIT (removed)
END;
$$;


