LEFT JOIN TBL_CUSTOMERLOGIN CL ON POM.LOGINID=CL.LOGINID
LEFT JOIN TBL_RESELLER_SERVICES TRS ON TRBVD.TYPE=TRS.TRSID
LEFT JOIN TBL_REFERENCEUSERNAME TRUN ON CL.CLID=TRUN.CLID AND TRUN.STATUS=1
LEFT JOIN DISTRIBUTOR_MASTER DM ON TRBVM.DID=DM.PLID
WHERE TRBVD.RELEASEDSTATUS=0 ';
  IF ((v_fromdate <> '') AND (v_todate = '')) THEN
  v_query := v_query || ' AND CONVERT(DATE, TRBVM.CREATE_DATE,103) =  CONVERT(DATE, ''' || v_fromdate || ''',103)';
  END IF;
  IF ((v_fromdate = '') AND (v_todate <> '')) THEN
  v_query := v_query || ' AND CONVERT(DATE, TRBVM.CREATE_DATE,103) =  CONVERT(DATE, ''' || v_todate || ''',103) ';
  END IF;
  IF ((v_fromdate <> '') AND (v_todate <> '')) THEN
  v_query := v_query || ' AND CONVERT(DATE, TRBVM.CREATE_DATE,103) BETWEEN CONVERT(DATE, ''' || v_fromdate || ''',103) AND  CONVERT(DATE, ''' || v_todate || ''',103) ';
  END IF;
  IF (v_resellername <> '') THEN
  v_query := v_query || ' And DM.COMPANYNAME=''' || CAST(v_resellername AS VARCHAR(30)) || '''';
  END IF;
  EXECUTE v_query;
  RAISE NOTICE '%', v_query;
  RETURN QUERY SELECT * FROM tmp_temp WHERE rownumber BETWEEN v_minindex AND v_maxindex;
