--

CREATE FUNCTION dbo.usp_adminuserinvoice(v_tmsid integer DEFAULT 0) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_minindex int;
  v_maxindex int;
  v_query text;
BEGIN
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp (RowNumber Int GENERATED BY DEFAULT AS IDENTITY,TASMID bigint,TotalPayableAmount decimal(18,2),PaymentMode int,ModeName varchar(100),CommentORRemark text,RegNo bigint,ImageName text,
BankName varchar(100),BranchName varchar(100),ReferenceDate varchar(100),ReferenceNumber varchar(100),WalletId varchar(100),TransactionPassword varchar(100),
GoogleAuthenticationCode varchar(100),AllPackageId varchar(100),AllPackageType varchar(100),AllPackageAmount varchar(100),PuchaseDate varchar(50),IsActive int,
Status int,Plid bigint,AllPackageName varchar(500),IsApproved int,Transaction_id varchar(100),service_tax decimal(18,2),service_tax_per decimal(18,2),With_out_tax_Amount decimal(18,2),
username varchar(200),fullname varchar(200),mobile varchar(100),emailid varchar(100),ADDRESS varchar(100),CITY varchar(100),POSTALCODE varchar(100),alladdress text,sid int,
statename varchar(100),statenamepincode varchar(300),invoice_no varchar(50)) ON COMMIT DROP;
  v_query := 'insert into #temp  select  sm.TASMID,sm.TotalPayableAmount,sm.PaymentMode,sm.ModeName,sm.CommentORRemark,sm.RegNo,sm.ImageName,
sm.BankName,sm.BranchName,sm.ReferenceDate,sm.ReferenceNumber,sm.WalletId,sm.TransactionPassword,sm.GoogleAuthenticationCode ,sm.AllPackageId,sm.AllPackageType ,
sm.AllPackageAmount ,Convert(varchar(30),sm.PuchaseDate,105) as PuchaseDate,isnull(sm.IsActive,0),isnull(sm.Status,0) ,sm.Plid,REPLACE(isnull(sm.AllPackageName,''''),''~'','',''),isnull(sm.IsApproved,0) ,sm.Transaction_id,isnull(sm.service_tax,0),isnull(sm.service_tax_per,0) ,
isnull(sm.With_out_tax_Amount,0),pl.username,isnull(pl.fname,'''')+'' ''+isnull(pl.lname,'''') as fullname,isnull(pl.phone,'''') as mobile,isnull(pl.emailid,'''') as emailid,
isnull(sb.ADDRESS,''''),isnull(sb.CITY,''''),isnull(sb.POSTALCODE,''''),isnull(sb.ADDRESS,'''')+'',''+isnull(sb.CITY,'''') as alladdress,isnull(sb.sid,0),isnull(s.statename,''''),isnull(s.statename,'''')+''-''+isnull(sb.POSTALCODE,'''') as statenamepincode
,isnull(sm.invoice_no,'''') from Tbl_AllSubscriptionMaster sm inner join portal_login pl on pl.plid=sm.plid left join TBL_SPONSERBILLING sb on sb.plid=sm.plid left join state s on s.sid=sb.sid where sm.TASMID=' || CAST(v_tmsid AS VARCHAR(50)) || ' ';
  EXECUTE v_query;
  RETURN QUERY SELECT * FROM tmp_temp;
  DROP TABLE IF EXISTS tmp_temp;
  -- SET option (removed)
END;
$$;


--
-- Name: usp_agreementdetails(character varying, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_agreementdetails(v_regno character varying DEFAULT '6'::character varying, v_mode integer DEFAULT 1) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
BEGIN
  -- BEGIN TRAN (removed)
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp (rownumber bigint,
regno bigint,
Name varchar(200),
fathername varchar(200),
address varchar(200),
packageamount decimal(18,2),
clickamount int,
upgradedate timestamp,
selectvalues text,
maxamount decimal(18,2),
remark varchar(5000),
status varchar(30),
uploadimage varchar(5000)) ON COMMIT DROP;
  IF (v_mode = 1) THEN
  INSERT INTO tmp_temp (rownumber, regno, name, fathername, address, packageamount, clickamount, upgradedate, selectvalues, maxamount, remark, status, uploadimage) SELECT ROW_NUMBER() OVER (ORDER BY plid ASC NULLS FIRST) AS rownumber, mm.plid AS regno, CONCAT(COALESCE(mm.fname, ''), '', COALESCE(mm.lname, '')) AS name, COALESCE(mm.fatherormothername, '') AS fathername, '' AS address, '0' AS packageamount, 0 AS clickamount, '', '' AS selectvalues, '0' AS maxamount, '' AS remark, '' AS status, '' AS uploadimage FROM portal_login AS mm WHERE mm.plid = v_regno;
  END IF;
  IF (v_mode = 2) THEN
  INSERT INTO tmp_temp SELECT ROW_NUMBER() OVER (ORDER BY regno ASC NULLS FIRST) AS rownumber, regno AS regno, name AS name, fathersname AS fathername, address AS address, packageamount AS packageamount, clickamount AS clickamount, updatedate AS upgradedate, selectvalues AS selectvalues, 0, remark, (CASE WHEN status = 0 THEN 'Pending' WHEN status = 1 THEN 'Approved' WHEN status = 2 THEN 'Reject' END) AS status, COALESCE(uploadimage, '') AS uploadimage FROM tbl_agreement_details WHERE regno = v_regno AND status <> 2;
  END IF;
  RETURN QUERY SELECT * FROM tmp_temp;
  DROP TABLE IF EXISTS tmp_temp;
  -- COMMIT (removed)
END;
$$;


