  IF (v_mode = 1) THEN
  INSERT INTO tmp_temp (rownumber, regno, name, fathername, address, packageamount, clickamount, selectvalues, maxamount, remark, status, uploadimage, mobile, companyname, designation) SELECT ROW_NUMBER() OVER (ORDER BY did ASC NULLS FIRST) AS rownumber, mm.did AS regno, CONCAT(COALESCE(mm.fname, ''), '', COALESCE(mm.lname, '')) AS name, COALESCE(mm.fatherormothername, '') AS fathername, COALESCE((dm.address || ' ' || ' ' || c.cityname || ' ' || s.statename || 'Pincode ' || dm.pincode), '') AS address, '0' AS packageamount, 0 AS clickamount, '' AS selectvalues, '0' AS maxamount, '' AS remark, '' AS status, '' AS uploadimage, COALESCE(mm.phone, '') AS mobile, COALESCE(dm.companyname, '') AS companyname, COALESCE(dm.contact_person_designation, 'N/A') FROM tbl_distributor AS mm LEFT JOIN distributor_master AS dm ON mm.did = dm.plid LEFT JOIN city AS c ON dm.ctid = c.ctid LEFT JOIN state AS s ON dm.sid = s.sid WHERE mm.did = v_regno;
  END IF;
  IF (v_mode = 2) THEN
  INSERT INTO tmp_temp SELECT ROW_NUMBER() OVER (ORDER BY did ASC NULLS FIRST) AS rownumber, did AS regno, COALESCE(name, '') AS name, COALESCE(fathersname, '') AS fathername, COALESCE(address, '') AS address, packageamount AS packageamount, clickamount AS clickamount, COALESCE(updatedate, '') AS upgradedate, selectvalues AS selectvalues, 0, COALESCE(remark, '') AS remark, (CASE WHEN status = 0 THEN 'Pending' WHEN status = 1 THEN 'Approved' WHEN status = 2 THEN 'Reject' END) AS status, COALESCE(uploadimage, '') AS uploadimage, '', '', '' FROM tbl_agreement_details_distributor WHERE did = v_regno AND status <> 3;
  END IF;
  RETURN QUERY SELECT * FROM tmp_temp;
  DROP TABLE IF EXISTS tmp_temp;
  -- COMMIT (removed)
END;
$$;


--
-- Name: usp_agreementlist(integer, integer, integer, integer, character varying, character varying, character varying, character varying, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_agreementlist(v_regno integer DEFAULT 0, v_mode integer DEFAULT 1, v_startrowindex integer DEFAULT 1, v_maxrows integer DEFAULT 100, v_status character varying DEFAULT ''::character varying, v_mobileno character varying DEFAULT ''::character varying, v_fromdate character varying DEFAULT ''::character varying, v_todate character varying DEFAULT ''::character varying, v_totalcount integer DEFAULT 0) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_minindex INT;
  v_maxindex INT;
  v_query text;
BEGIN
  -- SET option (removed)
  v_minindex := (v_startrowindex - 1) * v_maxrows + 1;
  v_maxindex := v_startrowindex * v_maxrows;
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp (rownumber bigint ,
AGID bigint,
regno bigint,
username varchar(100),
Name text,
mobileno text,
fathername text,
address text,
packageamount decimal(18,2),
clickamount int,
senddate varchar(30),
selectvalues text,
status varchar(50),
coname varchar(500),
trackno varchar(500),
sendvia varchar(500),
printdate varchar(500),
Email varchar(200)) ON COMMIT DROP;
  IF (v_mode = '1') THEN
  v_query := ' INSERT INTO #TEMP Select ROW_NUMBER() over (order by TA.AGID desc) as rownumber ,TA.AGID as AGID,  MM.regNo as regno,
MM.USERNAME as username,isnull(MM.FNAME+MM.LNAME,'''') As Name, 
MM.PHONE as mobileno, isnull(MM.FatherOrMotherName,'''') as fathername,
'''' as address, 
TA.PackageAmount as packageamount, TA.ClickAmount as clickamount,convert(varchar,convert(date, TA.Updatedate,105)) as senddate, 
TA.selectvalues as selectvalues,
(Case When TA.status = 0 then ''Pending'' When TA.status = 1 then ''Approved'' When TA.status = 2 then ''Reject'' END) as status  
,TA.company_name as coname,TA.Tracking as trackno,TA.Sentvia as sendvia ,TA.printdate as printdate,MM.EMAILID
FROM tbl_Agreement_Details TA
join PORTAL_LOGIN MM   ON  TA.Regno=MM.PLID where TA.uploadimage <>''''  ';
  END IF;
  IF (v_status <> '') THEN
  v_query := v_query || 'And TA.status =''' || v_status || '''';
  END IF;
  IF (v_mobileno <> '') THEN
  v_query := v_query || 'And MM.PHONE =''' || v_mobileno || '''';
  END IF;
  IF (v_fromdate <> '' AND v_todate = '') THEN
  v_query := v_query || (' AND Convert(date,TA.Updatedate,105) >= Convert(date,''' || v_fromdate || ''',105)');
  END IF;
  IF (v_fromdate = '' AND v_todate <> '') THEN
  v_query := v_query || (' AND CONVERT(DATE,TA.Updatedate,105) <= CONVERT(DATE,''' || v_todate || ''',105) ');
  END IF;
  IF (v_fromdate <> '' AND v_todate <> '') THEN
  v_query := v_query || (' AND CONVERT(DATE,TA.Updatedate,105) BETWEEN CONVERT(DATE,''' || v_fromdate || ''',105) AND CONVERT(DATE,''' || v_todate || ''',105)');
  END IF;
  EXECUTE v_query;
  RAISE NOTICE '%', (v_query);
  RETURN QUERY SELECT * FROM tmp_temp WHERE rownumber BETWEEN v_minindex AND v_maxindex;
  SELECT COUNT(rownumber) INTO v_totalcount FROM tmp_temp;
  DROP TABLE IF EXISTS tmp_temp;
  -- SET option (removed)
END;
$$;


