CREATE FUNCTION dbo.usp_all_categorywisedetails(v_startrowindex integer DEFAULT 1, v_maxrows integer DEFAULT 1000, v_searchfield character varying DEFAULT ''::character varying, v_searchvalue character varying DEFAULT 'hh'::character varying, v_rolename text DEFAULT ''::text, v_totalcount integer DEFAULT 0) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_minindex INT;
  v_maxindex INT;
  v_query text;
BEGIN
  v_minindex := (v_startrowindex - 1) * v_maxrows + 1;
  v_maxindex := v_startrowindex * v_maxrows;
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp (ROWNUMBER INT,
CATEGORYNAME VARCHAR(100),
 OrderAmount VARCHAR(200)) ON COMMIT DROP;
  v_query := 'INSERT INTO #TEMP SELECT ROW_NUMBER() OVER (ORDER BY  vcm.vcmid ASC),
 ISNULL(vcm.CATEGORYNAME,'''') AS CATEGORYNAME,
   sum(Case when vom.status = ''Confirm''  then orderamount else 0 end) as Total_Amount  
  from TBL_VOUCHER_CATEGORY_MASTER  vcm
	left join TBL_VOUCHER_MASTER vm on vm.VCTID=vcm.VCMID
	left join TBL_VOUCHER_ORDER_MASTER vom on vom.vmid=vm.vmid 
	group by
	 vcm.categoryname,
	 vcm.vcmid ';
  v_query := v_query;
  v_query := v_query || ' ORDER BY  vcm.vcmid ASC ';
  EXECUTE v_query;
  RETURN QUERY SELECT * FROM tmp_temp WHERE rownumber BETWEEN v_minindex AND v_maxindex;
  SELECT COUNT(rownumber) INTO v_totalcount FROM tmp_temp;
  DROP TABLE IF EXISTS tmp_temp;
  -- SET option (removed)
END;
$$;


