--
-- Name: usp_all_emailid_list(integer, integer, text, text, text, text); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_all_emailid_list(v_pageno integer DEFAULT 0, v_pagesize integer DEFAULT 0, v_domain text DEFAULT ''::text, v_type text DEFAULT ''::text, v_country text DEFAULT ''::text, v_detailsofqlookqpay text DEFAULT 'qlook'::text) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_minindex INT;
  v_maxindex INT;
  v_recordcount INT;
  v_amount numeric(19,4);
  v_currencysymbol VARCHAR(20);
  v_totalamount numeric(19,4);
  v_sqlquery text;
  v_currentdate DATE;
BEGIN
  -- SET option (removed)
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp (ROWNUMBER BIGINT,

EMAILID text,

COUNTRY_NAME text,

TYPE text,

LASTMAILDATE timestamp) ON COMMIT DROP;
  v_minindex := 0;
  v_maxindex := 0;
  v_sqlquery := '';
  v_currentdate := CAST(dbo.FUN_GETCURRENTDATE() AS DATE);
  v_minindex := ((v_pageno - 1) * v_pagesize) + 1;
  v_maxindex := (v_pageno * v_pagesize);
  IF (v_detailsofqlookqpay = 'qlook') THEN
  IF (v_type = 'reg-user' OR v_type = 'blog-user' OR v_type = 'emai-subs-user' OR v_type = '') THEN
  v_sqlquery := 'INSERT INTO #TEMP  SELECT ROW_NUMBER() OVER(ORDER BY EMAILID  ASC) AS ROWNUMBER,EMAILID,COUNTRY_NAME,TYPE,LASTMAILDATE FROM VIEW_ALLEMAIL_IDS WHERE EMAILID!=''''';
  IF (v_country <> '') THEN
  v_sqlquery := v_sqlquery || ' AND COUNTRY_NAME=''' || v_country || '''';
  END IF;
  IF (v_type <> '') THEN
  v_sqlquery := v_sqlquery || ' AND TYPE=''' || v_type || '''';
  END IF;
  ELSE
  IF (v_type = 'referral-user' OR v_type = 'free-business-listed-user' OR v_type = 'paid-business-listed-user') THEN
  v_sqlquery := 'INSERT INTO #TEMP SELECT ROW_NUMBER() OVER(ORDER BY LoginId  ASC) AS ROWNUMBER,LoginId,''India'',''' || v_type || ''',GETDATE() FROM PORTAL_LOGIN WHERE LoginId!=''''';
  IF (v_country <> '') THEN
  v_sqlquery := v_sqlquery || ' AND CID=96';
  END IF;
  IF (v_type = 'referral-user') THEN
  v_sqlquery := v_sqlquery || ' AND ISNULL(REFRAL_ID,'''')<>''''';
  END IF;
  IF (v_type = 'free-business-listed-user') THEN
  v_sqlquery := v_sqlquery || ' AND ISNULL(PMID,0)>0';
  END IF;
  IF (v_type = 'paid-business-listed-user') THEN
  v_sqlquery := v_sqlquery || ' AND ISNULL(PMID,0)>0';
  END IF;
  END IF;
  END IF;
  ELSE
  IF (v_detailsofqlookqpay = 'bulkuser') THEN
  v_sqlquery := 'INSERT INTO #TEMP SELECT ROW_NUMBER() OVER(ORDER BY EMAILID  ASC) AS ROWNUMBER,EMAILID,''India'',''email-bulk-uploded'',NULL 

	FROM Tbl_TblAdminBulkUploadedEmailMaster WHERE EMAILID!=''''';
  IF (v_type <> '') THEN
  v_sqlquery := v_sqlquery || ' AND GroupName like ''%' || v_type || '%''';
  END IF;
  END IF;
  END IF;
  EXECUTE v_sqlquery;
  SELECT COUNT(*) INTO v_recordcount FROM tmp_temp;
  RETURN QUERY SELECT *, CASE WHEN COALESCE(lastmaildate, '') = v_currentdate THEN 'yes' ELSE 'no' END AS istodaymailsent, v_recordcount AS recordcount FROM tmp_temp WHERE rownumber BETWEEN v_minindex AND v_maxindex;
  RETURN QUERY SELECT v_recordcount AS recordcount, COALESCE(v_amount, 0) AS currentamouunt, COALESCE(v_currencysymbol, 0) AS currencysymbol, COALESCE(v_totalamount, 0) AS totalamount;
  DROP TABLE IF EXISTS tmp_temp;
  -- SET option (removed)
END;
$$;


--
-- Name: usp_all_employeelist(integer, integer, character varying, character varying, character varying, character varying, character varying, character varying, character varying, character varying, character varying, text, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_all_employeelist(v_startrowindex integer DEFAULT 1, v_maxrows integer DEFAULT 1000, v_searchfield character varying DEFAULT ''::character varying, v_searchvalue character varying DEFAULT ''::character varying, v_fromdate character varying DEFAULT ''::character varying, v_todate character varying DEFAULT ''::character varying, v_status character varying DEFAULT ''::character varying, v_state character varying DEFAULT ''::character varying, v_city character varying DEFAULT ''::character varying, v_brcode character varying DEFAULT ''::character varying, v_brtid character varying DEFAULT ''::character varying, v_rolename text DEFAULT ''::text, v_totalcount integer DEFAULT 0) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_minindex INT;
  v_maxindex INT;
  v_query text;
BEGIN
  v_minindex := (v_startrowindex - 1) * v_maxrows + 1;
  v_maxindex := v_startrowindex * v_maxrows;
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp (ROWNUMBER INT,
EMP_CODE VARCHAR(100),
EMP_ID INT,
EMP_LOGINID VARCHAR(100),
BRNAME VARCHAR(200),
BRCODE VARCHAR(50),
BRTYPE VARCHAR(100),
 EMP_NAME VARCHAR(200),
 EMP_EMAIL VARCHAR(200),
 EMP_MOBILE VARCHAR(50),
 EMP_MOBILE2 VARCHAR(50),
 EMP_STATENAME VARCHAR(200),
 DISTRICTNAME VARCHAR(100),
 EMP_CITYNAME VARCHAR(200),
 EMP_ADDRESS VARCHAR(200),
 EMP_PINCODE VARCHAR(20),
 EMP_PANNO VARCHAR(30),
 EMP_IMAGE text,
 
 EMP_PASSWORD  VARCHAR(150),EMP_GENDER VARCHAR(5),
 TOTALEMP INT DEFAULT(0),
 STATUS VARCHAR(20),
 CURRENT_BALANCE numeric(19,4),
 TOTALROLES text,
 COM_TITLE VARCHAR(100)) ON COMMIT DROP;
  v_query := 'INSERT INTO #TEMP SELECT ROW_NUMBER() OVER (ORDER BY  EMPM.BRCODE ASC),EMPM.EMP_CODE,EMPM.EMP_ID,EMPM.EMP_LOGINID,BRT.BRNAME,EMPM.BRCODE,BRT.BRTYPE,EMPM.EMP_NAME,EMPM.EMP_EMAIL,EMPM.EMP_MOBILE,
 EMPM.EMP_MOBILE2,EMPM.EMP_STATENAME,ISNULL(BRT.DISTRICTNAME,'''') AS DISTRICTNAME,EMPM.EMP_CITYNAME,EMPM.EMP_ADDRESS,EMPM.EMP_PINCODE,EMPM.EMP_PANNO,CASE WHEN EMPM.EMP_IMAGE<>'''' THEN ''..\EmployeeImage\''' || '+EMPM.EMP_IMAGE ELSE '''' END AS EMP_IMAGE,
EMPM.EMP_PASSWORD,EMPM.EMP_GENDER,(SELECT COUNT(BRCODE) FROM TBL_EMPLOYEE_MASTER WHERE BRCODE=EMPM.BRCODE)
 ,CASE WHEN EMPM.ACTIVE=1 THEN ''Active'' ELSE ''Deactive'' END AS STATUS,EMPM.CURRENT_BALANCE,EMPM.TOTALROLES,CM.COM_TITLE  FROM TBL_EMPLOYEE_MASTER EMPM 
LEFT JOIN TBL_BRANCH_MASTER BRT ON BRT.BRCODE=EMPM.BRCODE
LEFT JOIN TBL_COMPANYMASTER CM ON CM.COM_CODE=BRT.COM_CODE WHERE EMPM.ISDELETE=0 ';
  IF (v_searchfield <> '' AND v_searchvalue <> '') THEN
  IF (v_searchfield = 'EMP_ID') THEN
  v_query := v_query || ' AND EMPM.' || v_searchfield || '=' || v_searchvalue || '';
  ELSE
  IF (v_searchfield <> '') THEN
  v_query := v_query || ' AND EMPM.' || v_searchfield || ' LIKE ''%' || v_searchvalue || '%''';
  END IF;
  END IF;
  END IF;
  IF (v_status <> '') THEN
  v_query := v_query || ' AND EMPM.ACTIVE = ''' || v_status || '''';
  END IF;
  IF (v_brcode <> '') THEN
  v_query := v_query || ' AND EMPM.BRCODE = ' || v_brcode || '';
  END IF;
  IF (v_brtid <> '') THEN
  v_query := v_query || ' AND BRT.BRTID = ' || v_brtid || '';
  END IF;
  IF (v_city <> '') THEN
  v_query := v_query || ' AND ISNULL(EMPM.EMP_CITYNAME,'''') = ''' || v_city || '''';
  END IF;
  IF (v_state <> '') THEN
  v_query := v_query || ' AND ISNULL(EMPM.EMP_STATENAME,'''') = ''' || v_state || '''';
  END IF;
  IF ((v_fromdate <> '') AND (v_todate = '')) THEN
  v_query := v_query || ' AND CONVERT(DATE, EMPM.CREATEDATE, 105) BETWEEN  CONVERT(DATE, ''' || v_fromdate || ''', 105) AND  CONVERT(DATE, DBO.FUN_GETCURRENTDATE(), 105)';
  END IF;
  IF ((v_fromdate = '') AND (v_todate <> '')) THEN
  v_query := v_query || 'AND CONVERT(DATE, EMPM.CREATEDATE, 105) BETWEEN  CONVERT(DATE, ''' || v_todate || ''', 105) AND  CONVERT(DATE, DBO.FUN_GETCURRENTDATE(), 105)';
  END IF;
  IF ((v_fromdate <> '') AND (v_todate <> '')) THEN
  v_query := v_query || 'AND CONVERT(DATE, EMPM.CREATEDATE, 105) BETWEEN  CONVERT(DATE, ''' || v_fromdate || ''', 105) AND  CONVERT(DATE, ''' || v_todate || ''', 105)';
  END IF;
  IF (v_rolename <> '') THEN
  v_query := v_query || ' AND TOTALROLES LIKE ''%' || v_rolename || '%''';
  END IF;
  v_query := v_query || ' ORDER BY  EMPM.BRCODE ASC ';
  EXECUTE v_query;
  RETURN QUERY SELECT * FROM tmp_temp WHERE rownumber BETWEEN v_minindex AND v_maxindex;
  SELECT COUNT(rownumber) INTO v_totalcount FROM tmp_temp;
  DROP TABLE IF EXISTS tmp_temp;
  -- SET option (removed)
END;
$$;


--
-- Name: usp_all_hold_order(integer, integer, character varying, character varying, character varying, character varying, integer, character varying, character varying, bigint, character varying, integer, integer, character varying, character varying, character varying, character varying, character varying, character varying, character varying, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_all_hold_order(v_startrowindex integer DEFAULT 1, v_maxrows integer DEFAULT 100, v_searchfield character varying DEFAULT ''::character varying, v_searchvalue character varying DEFAULT ''::character varying, v_fromdate character varying DEFAULT ''::character varying, v_todate character varying DEFAULT ''::character varying, v_totalcount integer DEFAULT 0, v_orderid character varying DEFAULT ''::character varying, v_company character varying DEFAULT ''::character varying, v_poid bigint DEFAULT 0, v_orderno character varying DEFAULT ''::character varying, v_mode integer DEFAULT 1, v_statusid integer DEFAULT 0, v_loginid character varying DEFAULT ''::character varying, v_sortbydispatchorder character varying DEFAULT ''::character varying, v_statusdate character varying DEFAULT ''::character varying, v_docketno character varying DEFAULT ''::character varying, v_ddlcourier character varying DEFAULT ''::character varying, v_merchantname character varying DEFAULT ''::character varying, v_productname character varying DEFAULT ''::character varying, v_ddlcancelationtype integer DEFAULT 0) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_minindex INT;
  v_maxindex INT;
  v_query text;
BEGIN
  v_minindex := (v_startrowindex - 1) * v_maxrows + 1;
  v_maxindex := v_startrowindex * v_maxrows;
  IF (v_mode = 1) THEN
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp (ROWNUMBER BIGINT 
, LOGINID VARCHAR( 100) 
, NAME VARCHAR(1000) 
, BRCODE VARCHAR( 50) 
, MOBILENO VARCHAR(20) 
, ORDERID VARCHAR( 50) 
, ORDERDATE VARCHAR(50) 
, ORDER_QTY INT 
, ORDER_DAP DECIMAL (18,2) 
, ORDER_NETAMT DECIMAL (18,2)
, PAYMODE VARCHAR( 25) 
, CITY VARCHAR(300) 
, TOTAL_VAT DECIMAL (18,2)
, ORDERINTSTATUS INT 
, POID BIGINT 
, SPRID BIGINT 
, PRODUCT_QTY INT 
, SINGLE_DAP DECIMAL (18,2) 
, TOTAL_DAP DECIMAL  (18,2)
, TOTAL_SHIP_CH DECIMAL  (18,2)
, TOTAL_COST DECIMAL (18,2)
, PRODUCTTOTALVAT DECIMAL (18,2) 
,TOTAL_PURCHASE_COST DECIMAL (18,2)
, PRODUCT_NAME varchar (500)
, PRODQTY varchar (100)
, PROUNIT VARCHAR( 500) 
, PRODCOLOR varchar (100)
, PRODSIZE varchar (100)
, PROD_IMAGES text 
, STATUS VARCHAR(500) 
, PRODUCTINTSTATUS INT 
, PROCESSBY VARCHAR(500) 
, PROCESSDATE timestamp 
, PROCESSREMARK VARCHAR(500) 
, INVQTY INT 
, REASON VARCHAR(100) 
, ISCANCELBYMEMBER boolean 
, ISRETURN boolean
, ADDRESS text
, PINCODE VARCHAR (50)
, COUNTRYNAME VARCHAR (500)
,JP DECIMAL(18,0)
,BV DECIMAL(18,0)
,COMPANYNAME VARCHAR(1000)
,PMID BIGINT,
SUBPRCODE VARCHAR(1000),
APPROVED VARCHAR(1000),
DISPATCHDATE VARCHAR(1000),
ORDERNO VARCHAR(1000),
COURIERNAME VARCHAR(1000),
DOCKETNO VARCHAR(1000),
DATEDIFF INT,
MERCHANTNAME VARCHAR(100),
MORDERID VARCHAR(100),
INVOICENO VARCHAR(100),
CREATEDDATE VARCHAR(100),
PACKED VARCHAR(100),
HANDOVER VARCHAR(100),
INTRANSIT VARCHAR(100),
DELIVERED VARCHAR(100),
CANCEL VARCHAR(100),
OUTFORDELIVERY VARCHAR(100)) ON COMMIT DROP;
  v_query := 'INSERT INTO #TEMP SELECT ROW_NUMBER() OVER (ORDER BY OM.ORDERDATE DESC) AS ROWNUMBER,
POM.LOGINID,(OM.FNAME+''''+ISNULL(OM.LNAME,'''')) AS NAME,B.CLID AS BRCODE,OM.MOBILENO,
OM.ORDERID,OM.ORDERDATE,OM.ORDER_QTY,OM.ORDER_DAP,OM.ORDER_NETAMT,
(CASE WHEN OM.PAYMODE=''PAYUMONEY'' THEN ''WALLET'' ELSE OM.PAYMODE END) AS PAYMODE,
ISNULL(OM.SH_CITY,'''') AS CITY,
OM.TOTAL_VAT,OM.INTSTATUS AS ORDERINTSTATUS,POM.POID, CONVERT(BIGINT, POM.SUBPRCODE) AS SPRID,
POM.PRODUCT_QTY, POM.SINGLE_DAP, POM.TOTAL_DAP, POM.TOTAL_SHIP_CH, POM.TOTAL_COST,
POM.TOTAL_VAT AS PRODUCTTOTALVAT,POM.TOTAL_PURCHASE_COST, POM.PRODUCT_NAME, POM.PRODQTY, POM.PROUNIT, 
POM.PRODCOLOR, POM.PRODSIZE, POM.PROD_IMAGES, 
(CASE WHEN POM.STATUS=''COMPLETED'' THEN ''DELIVERED'' ELSE POM.STATUS END), 
POM.INTSTATUS AS PRODUCTINTSTATUS,
POM.PROCESSBY, POM. PROCESSDATE, POM.PROCESSREMARK,ISNULL(POM.INVQTY,0) AS INVQTY,
POM.REASON,ISNULL(POM.ISCANCELBYMEMBER,0) AS ISCANCELBYMEMBER , ISNULL(POM.ISRETURN,0) AS ISRETURN ,
ISNULL(OM.ADDRESS,'''') AS ADDRESS,ISNULL(OM.PINCODE,'''') AS PINCODE,ISNULL(IMS.COUNTRYNAME,'''') AS COUNTRYNAME,
ISNULL(IMSP.PV,0) AS JP,ISNULL(IMSP.BV,0) AS BV,PMA.COMPANYNAME,PMA.PMID,IMSP.SUBPRCODE,
ISNULL(OCS.PACKED,'''') AS APPROVED ,
ISNULL(OCS.PACKED+IMSP.PROCUREMENTSLA,'''') AS DISPATCHDATE,
ISNULL(POM.ORDERNO,'''') AS ORDERNO,
ISNULL(CM.CARRIER_NAME,'''') AS COURIERNAME,
ISNULL(POM.DOCKETNO,'''') AS DOCKETNO,
ISNULL(DATEDIFF(DAY,OM.ORDERDATE,OCS.DELIVERED),0) AS DATEDIFF,ISNULL(PMA.COMPANYNAME,'''') AS MERCHANTNAME,
POM.MORDERID,POM.INVOICENO,CONVERT(VARCHAR(100),OCS.CREATEDDATE,106),CONVERT(VARCHAR(100),OCS.PACKED,106),CONVERT(VARCHAR(100),OCS.HANDOVER,106),
CONVERT(VARCHAR(100),OCS.INTRANSIT,106),CONVERT(VARCHAR(100),OCS.DELIVERED,106),CONVERT(VARCHAR(100),OCS.CANCEL,106),CONVERT(VARCHAR(100),OCS.OUTFORDELIVERY,106)
FROM TBL_ORDER_MASTER OM 
LEFT JOIN TBL_PRODUCT_ORDER_MASTER POM ON POM.ORDERID = OM.ORDERID 
JOIN PORTAL_LOGIN PL ON PL.PLID=POM.PLID 
LEFT JOIN TBL_CUSTOMERLOGIN B ON B.LOGINID = OM.LOGINID
LEFT JOIN IMS_CUSTOMERADDRESS IMS ON IMS.ID=B.CLID
LEFT JOIN PORTAL_MASTER PMA ON PMA.PMID=PL.PMID
LEFT JOIN IMS_SUBPRODUCT IMSP ON IMSP.SPRID= POM.SUBPRCODE
LEFT JOIN TBL_COURIERMASTER CM ON CM.CMID=POM.CMID
LEFT JOIN TBL_ORDER_CONFIRMEDSTAUS OCS ON OCS.ORDERNO=POM.ORDERNO 
WHERE OM.INTSTATUS=-1 AND OM.ISADMINAPPROVALNEEDED=1';
  IF (v_merchantname <> '') THEN
  v_query := v_query || ' AND (PMA.COMPANYNAME)=''' || v_merchantname || '''';
  END IF;
  IF (v_productname <> '') THEN
  v_productname := REPLACE(v_productname, '''', '''''');
  v_query := v_query || ' AND POM.PRODUCT_NAME=''' || v_productname || '''';
  END IF;
  IF (v_searchfield <> '' AND v_searchvalue <> '') THEN
  IF (v_searchfield = 'MERCHANTCODE') THEN
  v_query := v_query || ' AND B.CODE=''' || v_searchvalue || '''';
  END IF;
  IF (v_searchfield = 'LOGINID') THEN
  v_query := v_query || ' AND OM.LOGINID=''' || v_searchvalue || '''';
  END IF;
  IF (v_searchfield = 'MEMBERNAME') THEN
  v_query := v_query || ' AND ISNULL(B.FNAME,'''')+'' ''+ISNULL(B.LNAME,'''') LIKE ''%' || v_searchvalue || '%''';
  END IF;
  IF (v_searchfield = 'ORDERID') THEN
  v_query := v_query || ' AND OM.ORDERID=''' || v_searchvalue || '''';
  END IF;
  END IF;
  IF (v_company <> '') THEN
  v_query := v_query || ' AND PMA.PMID LIKE ''%' || v_company || '%'' ';
  END IF;
  IF (v_orderno <> '') THEN
  v_query := v_query || ' AND POM.MORDERID = ''' || v_orderno || ''' ';
  END IF;
  IF (v_orderid <> '') THEN
  v_query := v_query || ' AND POM.ORDERID = ''' || v_orderid || ''' ';
  END IF;
  IF (v_poid > 0) THEN
  v_query := v_query || ' AND POM.POID= ''' || CAST(v_poid AS VARCHAR(30)) || ''' ';
  END IF;
  IF ((v_fromdate <> '') AND (v_todate = '')) THEN
  v_query := v_query || ' AND CONVERT(VARCHAR, CONVERT(DATE, OM.ORDERDATE, 105) ) BETWEEN  CONVERT(DATE, ''' || v_fromdate || ''', 105) AND  CONVERT(DATE, DBO.FUN_GETCURRENTDATE(), 105)';
  END IF;
  IF ((v_fromdate = '') AND (v_todate <> '')) THEN
  v_query := v_query || 'AND CONVERT(DATE, OM.ORDERDATE, 105) BETWEEN  CONVERT(DATE, ''' || v_todate || ''', 105) AND  CONVERT(DATE, DBO.FUN_GETCURRENTDATE(), 105)';
  END IF;
  IF ((v_fromdate <> '') AND (v_todate <> '')) THEN
  v_query := v_query || 'AND CONVERT(DATE, OM.ORDERDATE, 105) BETWEEN CONVERT(DATE, ''' || v_fromdate || ''', 105) AND  CONVERT(DATE, ''' || v_todate || ''', 105)';
  END IF;
  IF (v_sortbydispatchorder <> '') THEN
  v_query := v_query || ' ORDER BY  CONVERT(DATETIME, OM.ORDERDATE, 103) ' || v_sortbydispatchorder || '';
  END IF;
  EXECUTE v_query;
  RAISE NOTICE '%', (v_query);
  RETURN QUERY SELECT * FROM tmp_temp WHERE rownumber BETWEEN v_minindex AND v_maxindex;
  SELECT COUNT(rownumber) INTO v_totalcount FROM tmp_temp;
  DROP TABLE IF EXISTS tmp_temp;
  -- SET option (removed)
  END IF;
END;
$$;


--
-- Name: usp_all_keyword_report(integer, integer, integer, character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_all_keyword_report(v_cid integer DEFAULT 0, v_ctid integer DEFAULT 0, v_aid integer DEFAULT 0, v_searchitem character varying DEFAULT ''::character varying) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_count1 int;
  v_count2 int;
  v_kmid int;
  v_noofhits int;
  v_count1forlastmonth int;
  v_count2forlastmonth int;
  v_kmidforlastmonth int;
  v_noofhitsforlastmonth int;
  v_yearcurrent int;
  v_lastmonth int;
  v_hits int;
  v_keywordrate_forgold numeric(19,4);
  v_keywordrate_forplatinum numeric(19,4);
  v_symbol varchar(100);
BEGIN
  SELECT EXTRACT(YEAR FROM CAST(CURRENT_TIMESTAMP AS DATE)), EXTRACT(MONTH FROM CAST(CURRENT_TIMESTAMP AS DATE)) - 1 INTO v_yearcurrent, v_lastmonth;
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp (kmid int,
				keywordname varchar(100),
				totalnoofhits int,
				lastmonthhits int,
				averagehits int,
				goldprice numeric(19,4),
				platinumprice numeric(19,4)) ON COMMIT DROP;
  INSERT INTO tmp_temp SELECT kmid, keywordname, 0, 0, 0, 0, 0 FROM keyword_master WHERE kactive = 1;
  DROP TABLE IF EXISTS tmp_temp_totalnoofhits;
  CREATE TEMP TABLE tmp_temp_totalnoofhits ON COMMIT DROP AS SELECT ROW_NUMBER() OVER (ORDER BY keywordid ASC NULLS FIRST) AS rownumber, keywordid, noofhits FROM tblnumberofhits WHERE cid = v_cid AND ctid = v_ctid AND aid = v_aid;
  SELECT COUNT(rownumber) INTO v_count2 FROM tmp_temp_totalnoofhits;
  v_count1 := 1;
  WHILE (v_count1 <= v_count2) LOOP
  SELECT keywordid, noofhits INTO v_kmid, v_noofhits FROM tmp_temp_totalnoofhits WHERE rownumber = v_count1;
  SELECT v_totalnoofhits INTO v_hits FROM dbo.usp_averagenoofhots_of_keyword(v_ctid => v_ctid, v_aid => v_aid, v_kid => v_kmid, v_totalnoofhits => v_hits);
  SELECT v_keywordrate, v_symbol INTO v_keywordrate_forgold, v_symbol FROM dbo.usp_keywordrate_countrywise(v_cid => v_cid, v_kmid => v_kmid, v_package => 'gold', v_keywordrate => v_keywordrate_forgold, v_symbol => v_symbol);
  SELECT v_keywordrate, v_symbol INTO v_keywordrate_forplatinum, v_symbol FROM dbo.usp_keywordrate_countrywise(v_cid => v_cid, v_kmid => v_kmid, v_package => 'platinum', v_keywordrate => v_keywordrate_forplatinum, v_symbol => v_symbol);
  UPDATE tmp_temp SET totalnoofhits = v_noofhits, averagehits = v_hits, goldprice = v_keywordrate_forgold * v_hits, platinumprice = v_keywordrate_forplatinum * v_hits WHERE kmid = v_kmid;
  v_count1 := v_count1 + 1;
  END LOOP;
  DROP TABLE IF EXISTS tmp_temp_tblnumberofhitsmonthly;
  CREATE TEMP TABLE tmp_temp_tblnumberofhitsmonthly ON COMMIT DROP AS SELECT ROW_NUMBER() OVER (ORDER BY keywordid ASC NULLS FIRST) AS rownumbermonthly, keywordid, noofhits FROM tblnumberofhitsmonthly WHERE cid = v_cid AND ctid = v_ctid AND aid = v_aid AND EXTRACT(YEAR FROM CAST(hitmonth AS DATE)) = v_yearcurrent AND EXTRACT(MONTH FROM CAST(hitmonth AS DATE)) = v_lastmonth;
  SELECT COUNT(rownumbermonthly) INTO v_count2forlastmonth FROM tmp_temp_tblnumberofhitsmonthly;
  v_count1forlastmonth := 1;
  WHILE (v_count1forlastmonth <= v_count2forlastmonth) LOOP
  SELECT keywordid, noofhits INTO v_kmidforlastmonth, v_noofhitsforlastmonth FROM tmp_temp_tblnumberofhitsmonthly WHERE rownumbermonthly = v_count1forlastmonth;
  UPDATE tmp_temp SET lastmonthhits = v_noofhitsforlastmonth WHERE kmid = v_kmidforlastmonth;
  v_count1forlastmonth := v_count1forlastmonth + 1;
  END LOOP;
  DROP TABLE IF EXISTS tmp_temp_totalnoofhits;
  DROP TABLE IF EXISTS tmp_temp_tblnumberofhitsmonthly;
  IF (v_searchitem <> '') THEN
  RETURN QUERY SELECT ROW_NUMBER() OVER (ORDER BY keywordname ASC NULLS FIRST) AS rownumber, * FROM tmp_temp WHERE LOWER(RTRIM(LTRIM(keywordname))) = LOWER(RTRIM(LTRIM(v_searchitem))) ORDER BY keywordname ASC NULLS FIRST;
  ELSE
  RETURN QUERY SELECT ROW_NUMBER() OVER (ORDER BY keywordname ASC NULLS FIRST) AS rownumber, * FROM tmp_temp ORDER BY keywordname ASC NULLS FIRST;
  END IF;
  DROP TABLE IF EXISTS tmp_temp;
END;
$$;


--
-- Name: usp_all_merchantlist(integer, integer, character varying, character varying, character varying, character varying, character varying, integer, integer, character varying, integer, character varying, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_all_merchantlist(v_startrowindex integer DEFAULT 1, v_maxrows integer DEFAULT 100000, v_searchfield character varying DEFAULT ''::character varying, v_searchvalue character varying DEFAULT ''::character varying, v_fromdate character varying DEFAULT ''::character varying, v_todate character varying DEFAULT ''::character varying, v_usertype character varying DEFAULT ''::character varying, v_memtype integer DEFAULT 0, v_joiningtype integer DEFAULT 0, v_varifiedpanstatus character varying DEFAULT ''::character varying, INOUT v_totalcount integer DEFAULT 0, v_userdownlinemember character varying DEFAULT 'b1'::character varying, v_side integer DEFAULT 2) RETURNS integer
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_minindex INT;
  v_maxindex INT;
  v_condition text;
  v_queryresult text;
  v_countquery text;
  v_maxregno text;
  v_parmdefinition text;
  v_getloginid varchar(50);
BEGIN
  -- SET option (removed)
  v_condition := '';
  v_queryresult := '';
  v_countquery := '';
  v_maxregno := '';
  v_minindex := (v_startrowindex - 1) * v_maxrows + 1;
  v_maxindex := v_startrowindex * v_maxrows;
  v_queryresult := N'SELECT  TOP(' || CAST((v_startrowindex * v_maxrows) AS text) || ') ROW_NUMBER() OVER (ORDER BY MM.REGDATE DESC) AS ROWNUMBER,MM.REGNO AS REGNO,MM.PLID, MM.LOGINID AS LOGINID,
ISNULL(MM.FNAME,'''')+'' ''+ISNULL(MM.MNAME,'''')+'' ''+ISNULL(MM.LNAME,'''') AS MEMBERNAME,MM.MOBILE AS MOBILE, MS.LOGINID AS RESPOUNSERID,MS.EMAILID AS RESPOUNSEREMAILID,
ISNULL(MS.FNAME,'''')+'' ''+ISNULL(MS.MNAME,'''')+'' ''+ISNULL(MS.LNAME,'''') AS RESPOUNSERNAME,
CONVERT(VARCHAR(30),MM.REGDATE,106) AS REGDATE,ISNULL(MM.PANNO,'''') AS PANNO,MM.USERNAME as USERNAME,
ISNULL(MP.PBV,0) AS PBV,ISNULL( MM.CITYNAME,'''') AS CITYNAME, ISNULL(MM.ACCOUNTNO,'''') AS ACCOUNTNO,ISNULL(MM.BANKNAME,'''')AS BANKNAME,ISNULL(MM.BRANCHNAME,'''')AS BRANCHNAME,
ISNULL(MM.IFSCCODE,'''')AS IFSCCODE,CASE MM.ISPANVERIFIED WHEN 0 THEN ''UNVERIFIED'' WHEN 1 THEN ''VERIFIED''  END AS STATUS,
CASE MM.STATUS WHEN 0 THEN ''DEACTIVE'' WHEN 1 THEN ''ACTIVE'' END AS ACTIVESTATUS,(MP.PPV) AS PV,MM.LEFTID AS LID,MM.RIGHTID AS RID,MM.ROOTID AS ROOTID,
MP.TLBV,MP.TRBV,MP.PAIDBV,MM.ACTIVE,MM.EMAILID,ISNULL(MM.KYC_UPDATE,'''')As KYC_UPDATE,ISNULL(MM.MCODE,'''') AS MCODE,
MM.STATENAME,isnull(KYCSTATUS,0) as KYCSTATUS,isnull(MS.USERNAME,'''') as sponsername,
Isnull(PL.PASSWORD,'''') as PASSWORD,Isnull(PL.TPASSWORD,'''') as TPASSWORD,CONVERT(VARCHAR(30),MM.DOC,106) AS DOC,MM.JoiningType,MM.ADDRESS INTO #TEMP
FROM MEMBER_MASTER MM   INNER JOIN PORTAL_LOGIN PL   ON PL.REGNO=MM.REGNO LEFT JOIN VIEW_MEMBER_MASTER MS
   ON  MS.LOGINID=MM.SPONSERID
INNER JOIN VIEW_MEMBER_PERFORMANCE MP   ON MP.LOGINID=MM.LOGINID WHERE ISNULL(MM.USERNAME,'''')!=''''';
  v_parmdefinition := N'@TOTALCOUNT NVARCHAR(1000) OUTPUT';
  v_countquery := N'SELECT @TOTALCOUNT=Count(1) FROM MEMBER_MASTER MM   WHERE REGNO<>0 ';
  IF (v_memtype = 3) THEN
  v_condition := v_condition || ' AND MM.MemType = 3 ';
  END IF;
  IF (v_memtype = 2) THEN
  v_condition := v_condition || ' AND MM.MemType = 2 ';
  END IF;
  IF (v_usertype <> '') THEN
  v_condition := v_condition || ' AND MM.ACTIVE = +CONVERT(VARCHAR(20),''' || v_usertype || ''') ';
  END IF;
  IF (v_searchfield <> '' AND v_searchvalue <> '') THEN
  IF (v_searchfield = 'Panno') THEN
  v_condition := v_condition || ' AND MM.PANNO LIKE ''%' || v_searchvalue || '%'' ';
  END IF;
  IF (v_searchfield = 'LoginId') THEN
  v_condition := v_condition || ' AND MM.Username LIKE ''' || v_searchvalue || '%'' ';
  END IF;
  IF (v_searchfield = 'Membername') THEN
  v_condition := v_condition || ' AND ISNULL(MM.FNAME,'''')+'' ''+ISNULL(MM.MNAME,'''')+'' ''+ISNULL(MM.LNAME,'''') LIKE ''%' || v_searchvalue || '%'' ';
  END IF;
  IF (v_searchfield = 'Mobileno') THEN
  v_condition := v_condition || ' AND MM.mobile LIKE ''%' || v_searchvalue || '%'' ';
  END IF;
  END IF;
  IF (v_varifiedpanstatus <> '') THEN
  IF (v_varifiedpanstatus = 'NotUpdated') THEN
  v_condition := v_condition || ' AND MM.PANNO = '''' ';
  ELSE
  IF (v_varifiedpanstatus = 'UnVerified') THEN
  v_condition := v_condition || ' AND  MM.IsPanVerified = 0 ';
  ELSE
  IF (v_varifiedpanstatus = 'Verified') THEN
  v_condition := v_condition || ' AND MM.IsPanVerified = 1 ';
  END IF;
  END IF;
  END IF;
  END IF;
  IF ((v_fromdate <> '') AND (v_todate = '')) THEN
  v_condition := v_condition || ' AND CONVERT(DATE, MM.REGDATE, 105) =  CONVERT(DATE, ''' || v_fromdate || ''', 105)  ';
  END IF;
  IF ((v_fromdate = '') AND (v_todate <> '')) THEN
  v_condition := v_condition || ' AND CONVERT(DATE, MM.REGDATE, 105) =  CONVERT(DATE, ''' || v_todate || ''', 105)  ';
  END IF;
  IF ((v_fromdate = '') AND (v_todate <> '')) THEN
  v_condition := v_condition || ' AND CONVERT(DATE, MM.REGDATE, 105) <=  CONVERT(DATE, ''' || v_todate || ''', 105)  ';
  END IF;
  IF ((v_fromdate <> '') AND (v_todate = '')) THEN
  v_condition := v_condition || ' AND CONVERT(DATE, MM.REGDATE, 105) >= CONVERT(DATE, ''' || v_fromdate || ''', 105)  ';
  END IF;
  IF ((v_fromdate <> '') AND (v_todate <> '')) THEN
  v_condition := v_condition || ' AND CONVERT(DATE, MM.REGDATE, 105) BETWEEN CONVERT(DATE, ''' || v_fromdate || ''', 105) and CONVERT(DATE, ''' || v_todate || ''', 105)';
  END IF;
  IF (v_joiningtype = 2) THEN
  v_condition := v_condition || ' AND MM.JoiningType = 2';
  END IF;
  IF (v_userdownlinemember <> '') THEN
  v_getloginid := '';
  SELECT loginid INTO v_getloginid FROM member_master WHERE username = v_userdownlinemember;
  IF (v_side = 0 AND v_getloginid <> '') THEN
  SELECT COALESCE(v_maxregno || ',', '') || CAST(regno AS VARCHAR) INTO v_maxregno FROM dbo.FUN_ALL_DOWNLINE_MEMBERLIST_BINARY('' || v_getloginid || '', 1);
  IF (v_maxregno <> '') THEN
  v_condition := v_condition || ' AND MM.REGNO in (select * from SplitString(''' || v_maxregno || ''','',''))';
  END IF;
  END IF;
  IF (v_side = 1 AND v_getloginid <> '') THEN
  SELECT COALESCE(v_maxregno || ',', '') || CAST(regno AS VARCHAR) INTO v_maxregno FROM dbo.FUN_ALL_DOWNLINE_MEMBERLIST_LEFT_SIDE_COUNT('' || v_getloginid || '');
  v_condition := v_condition || ' AND MM.REGNO in (select * from SplitString(''' || v_maxregno || ''','',''))';
  END IF;
  IF (v_side = 2 AND v_getloginid <> '') THEN
  SELECT COALESCE(v_maxregno || ',', '') || CAST(regno AS VARCHAR) INTO v_maxregno FROM dbo.FUN_ALL_DOWNLINE_MEMBERLIST_RIGHT_SIDE('' || v_getloginid || '');
  v_condition := v_condition || ' AND MM.REGNO in (select * from SplitString(''' || v_maxregno || ''','',''))';
  END IF;
  END IF;
  v_queryresult := v_queryresult || v_condition || ' ;SELECT  *  FROM #TEMP WHERE ROWNUMBER BETWEEN ' || CAST(v_minindex AS text) || ' AND ' || CAST(v_maxindex AS text) || '';
  v_queryresult := v_queryresult;
  v_countquery := v_countquery || v_condition;
  EXECUTE v_queryresult;
  EXECUTE v_countquery;
  -- SET option (removed)
END;
$$;


--
-- Name: usp_all_order_list(integer, integer, character varying, character varying, character varying, character varying, character varying, character varying, bigint, integer, character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_all_order_list(v_startrowindex integer DEFAULT 1, v_maxrows integer DEFAULT 10000, v_searchfield character varying DEFAULT ''::character varying, v_searchvalue character varying DEFAULT ''::character varying, v_fromdate character varying DEFAULT ''::character varying, v_todate character varying DEFAULT ''::character varying, v_status character varying DEFAULT 'pending'::character varying, v_statustype character varying DEFAULT ''::character varying, v_branchid bigint DEFAULT 1, v_totalcount integer DEFAULT 0, v_company character varying DEFAULT ''::character varying) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_minindex INT;
  v_maxindex INT;
  v_query text;
BEGIN
  v_minindex := (v_startrowindex - 1) * v_maxrows + 1;
  v_maxindex := v_startrowindex * v_maxrows;
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp (ROWNUMBER BIGINT 
, LOGINID VARCHAR( 100) 
, NAME VARCHAR(100) 
, BRCODE VARCHAR( 50) 
, MOBILENO VARCHAR( 20) 
, ORDERID VARCHAR( 50) 
, ORDERDATE timestamp 
, ORDER_QTY INT 
, ORDER_DAP DECIMAL 
, ORDER_NETAMT DECIMAL 
, PAYMODE VARCHAR( 25) 
, CITY VARCHAR( 30) 
, TOTAL_VAT DECIMAL 
, ORDERINTSTATUS INT 
, POID BIGINT 
, SPRID BIGINT 
, PRODUCT_QTY INT 
, SINGLE_DAP DECIMAL 
, TOTAL_DAP DECIMAL 
, TOTAL_SHIP_CH DECIMAL 
, TOTAL_COST DECIMAL 
, PRODUCTTOTALVAT DECIMAL 
, VATPERCENTAGE DECIMAL 
,TOTAL_PURCHASE_COST DECIMAL
, PRODUCT_NAME varchar (100)
, PRODQTY varchar (10)
, PROUNIT VARCHAR( 50) 
, PRODCOLOR varchar (10)
, PRODSIZE varchar (10)
, PROD_IMAGES text 
, STATUS VARCHAR( 50) 
, PRODUCTINTSTATUS INT 
, PROCESSBY VARCHAR( 50) 
, PROCESSDATE timestamp 
, PROCESSREMARK VARCHAR(50) 
, INVQTY INT 
, REASON VARCHAR(100) 
, ISCANCELBYMEMBER boolean 
, ISRETURN boolean
, Address VARCHAR( 1000)
, PinCode VARCHAR (50)
, CountryName VARCHAR (50)
,JP decimal(18,0)
,BV decimal(18,0)
,COMPANYNAME varchar(100)
,pmid bigint) ON COMMIT DROP;
  v_query := 'INSERT INTO #TEMP  SELECT ROW_NUMBER() OVER (ORDER BY OM.ORDERDATE DESC) AS ROWNUMBER,
POM.LOGINID,(OM.FNAME+''''+ISNULL(OM.LNAME,'''')) AS NAME,B.CLID AS BRCODE,OM.MOBILENO,
OM.ORDERID,OM.ORDERDATE,OM.ORDER_QTY,OM.ORDER_DAP,OM.ORDER_NETAMT,OM.PAYMODE,isnull(OM.Sh_City,'''') as CITY,
OM.TOTAL_VAT,OM.INTSTATUS AS ORDERINTSTATUS,POM.POID, CONVERT(BIGINT, POM.SUBPRCODE) AS SPRID,
POM.PRODUCT_QTY, POM.SINGLE_DAP, POM.TOTAL_DAP, POM.TOTAL_SHIP_CH, POM.TOTAL_COST,
POM.TOTAL_VAT AS PRODUCTTOTALVAT,TVC.VatPercValue,POM.TOTAL_PURCHASE_COST, POM.PRODUCT_NAME, POM.PRODQTY, POM.PROUNIT, 
POM.PRODCOLOR, POM.PRODSIZE, POM.PROD_IMAGES, POM.STATUS, POM.INTSTATUS AS PRODUCTINTSTATUS,
POM.PROCESSBY, POM. PROCESSDATE, POM.PROCESSREMARK,ISNULL(POM.INVQTY,0) AS INVQTY,
POM.REASON,ISNULL(POM.ISCANCELBYMEMBER,0) AS ISCANCELBYMEMBER , ISNULL(POM.ISRETURN,0) AS ISRETURN ,isnull(OM.Address,'''') AS Address,ISNULL(OM.PinCode,'''') AS PinCode,ISNULL(IMS.CountryName,'''') AS CountryName,
isnull(OM.order_pv,0) AS JP,ISNULL(OM.order_Bv,0) AS BV,pma.COMPANYNAME,pma.PMID
FROM TBL_ORDER_MASTER OM 
LEFT JOIN TBL_PRODUCT_ORDER_MASTER POM ON POM.ORDERID = OM.ORDERID 
join PORTAL_LOGIN pl on pl.PLID=OM.BranchId JOIN TBL_CUSTOMERLOGIN B ON B.LOGINID = OM.LoginId
left join IMS_CustomerAddress IMS on IMS.Id=B.CLID
left join Portal_Master pma on pma.PMID=pl.PMID
left join IMS_SubProduct IMSP on IMSP.SPRID= POM.SubPrCode
INNER JOIN tbl_Vat_Categories TVC ON TVC.VCID=IMSP.VATCATEGORYID
WHERE OM.LOGINID=B.LOGINID AND OM.ORDERID != ''''';
  IF (v_searchfield <> '' AND v_searchvalue <> '') THEN
  IF (v_searchfield = 'MERCHANTCODE') THEN
  v_query := v_query || ' AND B.CODE=''' || v_searchvalue || '''';
  END IF;
  IF (v_searchfield = 'LOGINID') THEN
  v_query := v_query || ' AND OM.LOGINID=''' || v_searchvalue || '''';
  END IF;
  IF (v_searchfield = 'MEMBERNAME') THEN
  v_query := v_query || ' AND ISNULL(B.FNAME,'''')+'' ''+ISNULL(B.LNAME,'''') LIKE ''%' || v_searchvalue || '%''';
  END IF;
  IF (v_searchfield = 'ORDERID') THEN
  v_query := v_query || ' AND OM.ORDERID=''' || v_searchvalue || '''';
  END IF;
  END IF;
  IF (v_company <> '') THEN
  v_query := v_query || ' AND pma.PMID LIKE ''%' || v_company || '%'' ';
  END IF;
  IF ((v_fromdate <> '') AND (v_todate = '')) THEN
  v_query := v_query || ' AND CONVERT(DATE, OM.ORDERDATE, 105) BETWEEN  CONVERT(DATE, ''' || v_fromdate || ''', 105) AND  CONVERT(DATE, DBO.FUN_GETCURRENTDATE(), 105)';
  END IF;
  IF ((v_fromdate = '') AND (v_todate <> '')) THEN
  v_query := v_query || 'AND CONVERT(DATE, OM.ORDERDATE, 105) BETWEEN  CONVERT(DATE, ''' || v_todate || ''', 105) AND  CONVERT(DATE, DBO.FUN_GETCURRENTDATE(), 105)';
  END IF;
  IF ((v_fromdate <> '') AND (v_todate <> '')) THEN
  v_query := v_query || 'AND CONVERT(DATE, OM.ORDERDATE, 105) BETWEEN CONVERT(DATE, ''' || v_fromdate || ''', 105) AND  CONVERT(DATE, ''' || v_todate || ''', 105)';
  END IF;
  IF (v_status <> '') THEN
  v_query := v_query || ' AND ISNULL(OM.STATUS,'''')= ''' || v_status || '''';
  END IF;
  IF (v_statustype <> '') THEN
  IF (v_statustype = 'PENDING') THEN
  v_query := v_query || ' AND POM.STATUS=''PENDING''';
  END IF;
  IF (v_statustype = 'Completed') THEN
  v_query := v_query || ' AND POM.STATUS=''Completed''';
  END IF;
  IF (v_statustype = 'PICK') THEN
  v_query := v_query || ' AND POM.STATUS=''PICK''';
  END IF;
  IF (v_statustype = 'Dispatched') THEN
  v_query := v_query || ' AND POM.STATUS=''Dispatched''';
  END IF;
  IF (v_statustype = 'READY-TO-SHIP') THEN
  RETURN QUERY SELECT 4 AS readyship;
  v_query := v_query || ' AND POM.STATUS=''READYTOSHIP''';
  END IF;
  IF (v_statustype = 'MANIFEST') THEN
  v_query := v_query || ' AND POM.STATUS=''READYTOSHIP''';
  END IF;
  IF (v_statustype = 'Cancel') THEN
  v_query := v_query || ' AND POM.STATUS=''Cancel''';
  END IF;
  IF (v_statustype = 'RETURN') THEN
  v_query := v_query || ' AND POM.STATUS=''RETURN''';
  END IF;
  END IF;
  IF (v_branchid > 0) THEN
  v_query := v_query || ' AND pl.PLID=' || CAST(v_branchid AS VARCHAR(20)) || '';
  END IF;
  EXECUTE v_query;
  RAISE NOTICE '%', (v_query);
  RETURN QUERY SELECT * FROM tmp_temp WHERE rownumber BETWEEN v_minindex AND v_maxindex;
  SELECT COUNT(rownumber) INTO v_totalcount FROM tmp_temp;
  DROP TABLE IF EXISTS tmp_temp;
  -- SET option (removed)
END;
$$;


--
-- Name: usp_all_order_list_distributor(integer, integer, character varying, character varying, character varying, character varying, character varying, character varying, bigint, integer, character varying, character varying, bigint, character varying, integer, integer, character varying, character varying, integer, character varying, character varying, character varying, character varying, character varying, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_all_order_list_distributor(v_startrowindex integer DEFAULT 1, v_maxrows integer DEFAULT 100, v_searchfield character varying DEFAULT ''::character varying, v_searchvalue character varying DEFAULT ''::character varying, v_fromdate character varying DEFAULT ''::character varying, v_todate character varying DEFAULT ''::character varying, v_status character varying DEFAULT ''::character varying, v_statustype character varying DEFAULT ''::character varying, v_branchid bigint DEFAULT 8, v_totalcount integer DEFAULT 0, v_orderid character varying DEFAULT ''::character varying, v_company character varying DEFAULT ''::character varying, v_poid bigint DEFAULT 0, v_orderno character varying DEFAULT ''::character varying, v_mode integer DEFAULT 1, v_statusid integer DEFAULT 0, v_loginid character varying DEFAULT ''::character varying, v_sortbydispatchorder character varying DEFAULT 'desc'::character varying, v_orderstatus integer DEFAULT 0, v_statusdate character varying DEFAULT ''::character varying, v_docketno character varying DEFAULT ''::character varying, v_ddlcourier character varying DEFAULT ''::character varying, v_merchantname character varying DEFAULT ''::character varying, v_productname character varying DEFAULT ''::character varying, v_ddlcancelationtype integer DEFAULT 0) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_minindex INT;
  v_maxindex INT;
  v_query text;
  v_statusname varchar(100);
  v_statusname1 varchar(50);
  v_statusname2 varchar(50);
  v_statusname5 varchar(50);
  v_statusname6 varchar(50);
BEGIN
  v_minindex := (v_startrowindex - 1) * v_maxrows + 1;
  v_maxindex := v_startrowindex * v_maxrows;
  IF (v_mode = 1) THEN
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp (ROWNUMBER BIGINT,LOGINID VARCHAR(100) ,NAME VARCHAR(1000), 
BRCODE VARCHAR(50), MOBILENO VARCHAR(20), ORDERID VARCHAR(50) ,
ORDERDATE varchar(100), ORDER_QTY INT, ORDER_DAP DECIMAL, 
ORDER_NETAMT DECIMAL,PAYMODE VARCHAR(25), CITY VARCHAR(300), 
TOTAL_VAT DECIMAL, ORDERINTSTATUS INT, POID BIGINT, 
SPRID BIGINT,PRODUCT_QTY INT, SINGLE_DAP DECIMAL, TOTAL_DAP DECIMAL, 
TOTAL_SHIP_CH DECIMAL, TOTAL_COST DECIMAL, PRODUCTTOTALVAT DECIMAL, 
TOTAL_PURCHASE_COST DECIMAL,PRODUCT_NAME varchar (500),PRODQTY varchar (100),
PROUNIT VARCHAR( 500), PRODCOLOR varchar (100),PRODSIZE varchar (100),
PROD_IMAGES text, STATUS VARCHAR( 500), PRODUCTINTSTATUS INT ,
PROCESSBY VARCHAR(500), PROCESSDATE timestamp, PROCESSREMARK VARCHAR(500), 
INVQTY INT, REASON VARCHAR(100), ISCANCELBYMEMBER boolean, 
ISRETURN boolean,Address text,PinCode VARCHAR (50),
CountryName VARCHAR (500),JP decimal(18,0),BV decimal(18,0),
Orderno varchar(100),Approved varchar(1000),dispatchdate varchar(1000),
Producttitle varchar(200),CreatedDate varchar(200),Packed varchar(200),
Handover varchar(200),Intransit varchar(200),Picked varchar(200),
Delivered varchar(200),MLMWALLET decimal(18,2),CUSTOMERWALLET decimal(18,2)) ON COMMIT DROP;
  v_query := 'INSERT INTO #TEMP      SELECT ROW_NUMBER() OVER (ORDER BY OM.ORDERDATE asc) AS ROWNUMBER,
	ISNULL(POM.LOGINID,'''') as LOGINID,isnull(OM.FNAME+''''+ISNULL(OM.LNAME,''''),'''') AS NAME,ISNULL(B.CLID,'''') AS BRCODE,
	ISNULL( OM.MOBILENO,'''') as MOBILENO,
	ISNULL(OM.ORDERID,''''),ISNULL( CONVERT(nvarchar ,OM.ORDERDATE,100),'''') as ORDERDATE,ISNULL( POM.Product_Qty,0) as ORDER_QTY,
	ISNULL( OM.ORDER_DAP,0) as ORDER_DAP,ISNULL( OM.ORDER_NETAMT,0)as ORDER_NETAMT,ISNULL( OM.PAYMODE,'''') as PAYMODE,
	isnull(OM.Sh_City,'''') as CITY,
	ISNULL( OM.TOTAL_VAT,0) as TOTAL_VAT,ISNULL( OM.INTSTATUS,0) AS ORDERINTSTATUS,
	ISNULL( POM.POID,0) as POID,ISNULL( CONVERT(BIGINT, POM.SUBPRCODE),0) AS SPRID,
	ISNULL( POM.PRODUCT_QTY,0) as PRODUCT_QTY,ISNULL( POM.SINGLE_DAP,0) as SINGLE_DAP, 
	ISNULL( POM.TOTAL_DAP,0) as TOTAL_DAP,ISNULL( POM.TOTAL_SHIP_CH,0) as TOTAL_SHIP_CH,ISNULL( POM.TOTAL_COST,0) as TOTAL_COST,
	ISNULL(POM.TOTAL_VAT,0) AS PRODUCTTOTALVAT,ISNULL(POM.TOTAL_PURCHASE_COST,0)as TOTAL_PURCHASE_COST, 
	ISNULL(POM.PRODUCT_NAME,'''') as PRODUCT_NAME,ISNULL( POM.PRODQTY,'''') as PRODQTY, ISNULL(POM.PROUNIT,'''') as PROUNIT, 
	ISNULL(POM.PRODCOLOR,'''') as PRODCOLOR,ISNULL( POM.PRODSIZE,'''') as PRODSIZE,ISNULL( POM.PROD_IMAGES,'''') as PROD_IMAGES,
	ISNULL( POM.STATUS,'''') as STATUS,ISNULL( POM.INTSTATUS,0) AS PRODUCTINTSTATUS,
	ISNULL(POM.PROCESSBY,'''') as PROCESSBY ,ISNULL( POM. PROCESSDATE,'''') as PROCESSDATE,ISNULL( POM.PROCESSREMARK,'''') as PROCESSREMARK,
	ISNULL(POM.INVQTY,0) AS INVQTY,
	ISNULL(POM.REASON,'''') as REASON,ISNULL(POM.ISCANCELBYMEMBER,0) AS ISCANCELBYMEMBER , ISNULL(POM.ISRETURN,0) AS ISRETURN ,
	isnull(OM.Address,'''') AS Address,ISNULL(OM.PinCode,'''') AS PinCode,ISNULL(IMS.CountryName,'''') AS CountryName,
	isnull(IMSP.PV,0) AS JP,ISNULL(IMSP.BV,0) AS BV 
	,isnull(POM.Orderno,'''') as Orderno,isnull(OCS.packed,'''') as Approved ,
	isnull(OCS.packed+IMSP.ProcurementSLA,'''') as dispatchdate,ISNULL( PM.PRODUCTTITLE,'''') as PRODUCTTITLE,
	convert(varchar, OCS.CreatedDate,106),convert(varchar,OCS.Packed,106),convert(varchar,OCS.Handover,106),
	convert(varchar,OCS.Intransit,106),convert(varchar,OCS.Picked,106),convert(varchar,OCS.Delivered,106),
	isnull(PD.MLMWALLET,0) as MLMWALLET,isnull(PD.CUSTOMERWALLET,0) as CUSTOMERWALLET
	FROM TBL_ORDER_MASTER  OM   
	LEFT JOIN TBL_PRODUCT_ORDER_MASTER POM ON POM.ORDERID = OM.ORDERID 
	--LEFT join PORTAL_LOGIN pl on pl.PLID=OM.BranchId 
	JOIN TBL_CUSTOMERLOGIN B ON B.LOGINID = OM.LoginId
	left join IMS_CustomerAddress IMS on IMS.Id=B.CLID
	JOIN TBL_DISTRIBUTOR TD ON TD.DID=B.DID
	--left join Portal_Master pma on pma.PMID=pl.PMID
	left join IMS_SubProduct IMSP on IMSP.SPRID= POM.SubPrCode
	left join tbl_Order_ConfirmedStaus OCS on OCS.orderno=POM.Orderno
	LEFT JOIN IMS_MASTERPRODUCT PM  ON   IMSP.MPRID=PM.MPRID 
	LEFT join TBL_ORDERPAYMENTSDETAILS as PD on PD.ORDERID=OM.ORDERID 
	WHERE POM.INTSTATUS not in (-1,7,8) AND OM.LOGINID=B.LOGINID  and OM.ORDERID  != ''''';
  IF (v_merchantname <> '') THEN
  v_query := v_query || ' AND (PMA.COMPANYNAME)=''' || v_merchantname || '''';
  END IF;
  IF (v_productname <> '') THEN
  v_query := v_query || ' AND POM.Product_Name=''' || v_productname || '''';
  END IF;
  IF (v_orderstatus = 0) THEN
  v_query := v_query || ' AND POM.IntStatus=' || CAST(v_orderstatus AS VARCHAR(30)) || '';
  END IF;
  IF (v_orderstatus = 7) THEN
  v_query := v_query || ' AND POM.IntStatus=' || CAST(v_orderstatus AS VARCHAR(30)) || '';
  END IF;
  IF (v_orderstatus = 2) THEN
  v_query := v_query || ' AND POM.IntStatus=' || CAST(v_orderstatus AS VARCHAR(30)) || '';
  END IF;
  IF (v_orderstatus = 3) THEN
  v_query := v_query || ' AND POM.IntStatus=' || CAST(v_orderstatus AS VARCHAR(30)) || '';
  END IF;
  IF (v_searchfield <> '' AND v_searchvalue <> '') THEN
  IF (v_searchfield = 'MERCHANTCODE') THEN
  v_query := v_query || ' AND B.CODE=''' || v_searchvalue || '''';
  END IF;
  IF (v_searchfield = 'LOGINID') THEN
  v_query := v_query || ' AND OM.LOGINID=''' || v_searchvalue || '''';
  END IF;
  IF (v_searchfield = 'MEMBERNAME') THEN
  v_query := v_query || ' AND ISNULL(B.FNAME,'''')+'' ''+ISNULL(B.LNAME,'''') LIKE ''%' || v_searchvalue || '%''';
  END IF;
  IF (v_searchfield = 'ORDERID') THEN
  v_query := v_query || ' AND OM.ORDERID=''' || v_searchvalue || '''';
  END IF;
  END IF;
  IF (v_company <> '') THEN
  v_query := v_query || ' AND pma.PMID LIKE ''%' || v_company || '%'' ';
  END IF;
  IF (v_orderno <> '') THEN
  v_query := v_query || ' AND POM.Orderno = ''' || v_orderno || ''' ';
  END IF;
  IF (v_orderid <> '') THEN
  v_query := v_query || ' AND POM.OrderId = ''' || v_orderid || ''' ';
  END IF;
  IF (v_poid > 0) THEN
  v_query := v_query || ' AND POM.POID= ''' || CAST(v_poid AS VARCHAR(30)) || ''' ';
  END IF;
  IF ((v_fromdate <> '') AND (v_todate = '')) THEN
  v_query := v_query || ' AND convert(varchar, CONVERT(DATE, OM.ORDERDATE, 105) ) BETWEEN  CONVERT(DATE, ''' || v_fromdate || ''', 105) AND  CONVERT(DATE, DBO.FUN_GETCURRENTDATE(), 105)';
  END IF;
  IF ((v_fromdate = '') AND (v_todate <> '')) THEN
  v_query := v_query || 'AND CONVERT(DATE, OM.ORDERDATE, 105) BETWEEN  CONVERT(DATE, ''' || v_todate || ''', 105) AND  CONVERT(DATE, DBO.FUN_GETCURRENTDATE(), 105)';
  END IF;
  IF ((v_fromdate <> '') AND (v_todate <> '')) THEN
  v_query := v_query || 'AND CONVERT(DATE, OM.ORDERDATE, 105) BETWEEN CONVERT(DATE, ''' || v_fromdate || ''', 105) AND  CONVERT(DATE, ''' || v_todate || ''', 105)';
  END IF;
  IF (v_status <> '') THEN
  v_query := v_query || ' AND ISNULL(OM.STATUS,'''')= ''' || v_status || '''';
  END IF;
  IF (v_statustype <> '') THEN
  IF (v_statustype = 'PENDING') THEN
  v_query := v_query || ' AND POM.STATUS=''PENDING''';
  END IF;
  IF (v_statustype = 'Completed') THEN
  v_query := v_query || ' AND POM.STATUS=''Completed''';
  END IF;
  IF (v_statustype = 'PICK') THEN
  v_query := v_query || ' AND POM.STATUS=''PICK''';
  END IF;
  IF (v_statustype = 'Dispatched') THEN
  v_query := v_query || ' AND POM.STATUS=''Dispatched''';
  END IF;
  IF (v_statustype = 'READY-TO-SHIP') THEN
  v_query := v_query || ' AND POM.STATUS=''READYTOSHIP''';
  END IF;
  IF (v_statustype = 'MANIFEST') THEN
  v_query := v_query || ' AND POM.STATUS=''READYTOSHIP''';
  END IF;
  IF (v_statustype = 'Cancel') THEN
  v_query := v_query || ' AND POM.STATUS=''Cancel''';
  END IF;
  IF (v_statustype = 'RETURN') THEN
  v_query := v_query || ' AND POM.STATUS=''RETURN''';
  END IF;
  END IF;
  IF (v_branchid > 0) THEN
  v_query := v_query || ' AND TD.DID=' || CAST(v_branchid AS VARCHAR(20)) || '';
  END IF;
  RAISE NOTICE '%', (v_query);
  EXECUTE v_query;
  IF (v_sortbydispatchorder = 'desc') THEN
  RETURN QUERY SELECT * FROM tmp_temp WHERE rownumber BETWEEN v_minindex AND v_maxindex ORDER BY orderdate DESC NULLS LAST;
  ELSE
  RETURN QUERY SELECT * FROM tmp_temp WHERE rownumber BETWEEN v_minindex AND v_maxindex;
  END IF;
  SELECT COUNT(rownumber) INTO v_totalcount FROM tmp_temp;
  DROP TABLE IF EXISTS tmp_temp;
  -- SET option (removed)
  END IF;
  IF (v_mode = 2) THEN
  SELECT statusname INTO v_statusname FROM orderstatusmaster WHERE osid = v_statusid;
  UPDATE tbl_order_confirmedstaus SET packed = TO_TIMESTAMP(v_statusdate, 'DD/MM/YYYY') WHERE orderid = v_orderid AND customerid = v_loginid;
  UPDATE tbl_product_order_master SET intstatus = v_statusid, status = v_statusname WHERE poid = v_poid;
  END IF;
  IF (v_mode = 3) THEN
  SELECT statusname INTO v_statusname1 FROM orderstatusmaster WHERE osid = v_statusid;
  UPDATE tbl_order_confirmedstaus SET handover = TO_TIMESTAMP(v_statusdate, 'DD/MM/YYYY') WHERE orderid = v_orderid AND customerid = v_loginid;
  UPDATE tbl_product_order_master SET intstatus = v_statusid, status = v_statusname1 WHERE poid = v_poid;
  END IF;
  IF (v_mode = 4) THEN
  SELECT statusname INTO v_statusname2 FROM orderstatusmaster WHERE osid = v_statusid;
  UPDATE tbl_order_confirmedstaus SET intransit = TO_TIMESTAMP(v_statusdate, 'DD/MM/YYYY') WHERE orderid = v_orderid AND customerid = v_loginid;
  UPDATE tbl_product_order_master SET intstatus = v_statusid, docketno = v_docketno, cmid = v_ddlcourier WHERE poid = v_poid;
  END IF;
  IF (v_mode = 5) THEN
  SELECT statusname INTO v_statusname5 FROM orderstatusmaster WHERE osid = v_statusid;
  UPDATE tbl_order_confirmedstaus SET picked = TO_TIMESTAMP(v_statusdate, 'DD/MM/YYYY') WHERE orderid = v_orderid AND customerid = v_loginid;
  UPDATE tbl_product_order_master SET intstatus = v_statusid, status = v_statusname5 WHERE poid = v_poid;
  END IF;
  IF (v_mode = 6) THEN
  SELECT statusname INTO v_statusname6 FROM orderstatusmaster WHERE osid = v_statusid;
  UPDATE tbl_order_confirmedstaus SET delivered = TO_TIMESTAMP(v_statusdate, 'DD/MM/YYYY') WHERE orderid = v_orderid AND customerid = v_loginid;
  UPDATE tbl_product_order_master SET intstatus = v_statusid, status = v_statusname6 WHERE poid = v_poid;
  END IF;
END;
$$;


--
-- Name: usp_all_order_list_distributor_cancel(integer, integer, character varying, character varying, character varying, character varying, character varying, character varying, bigint, integer, character varying, character varying, bigint, character varying, integer, integer, character varying, character varying, integer, character varying, character varying, character varying, character varying, character varying, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_all_order_list_distributor_cancel(v_startrowindex integer DEFAULT 1, v_maxrows integer DEFAULT 100, v_searchfield character varying DEFAULT ''::character varying, v_searchvalue character varying DEFAULT ''::character varying, v_fromdate character varying DEFAULT ''::character varying, v_todate character varying DEFAULT ''::character varying, v_status character varying DEFAULT ''::character varying, v_statustype character varying DEFAULT ''::character varying, v_branchid bigint DEFAULT 1, v_totalcount integer DEFAULT 0, v_orderid character varying DEFAULT ''::character varying, v_company character varying DEFAULT ''::character varying, v_poid bigint DEFAULT 0, v_orderno character varying DEFAULT ''::character varying, v_mode integer DEFAULT 1, v_statusid integer DEFAULT 0, v_loginid character varying DEFAULT ''::character varying, v_sortbydispatchorder character varying DEFAULT 'desc'::character varying, v_orderstatus integer DEFAULT 0, v_statusdate character varying DEFAULT ''::character varying, v_docketno character varying DEFAULT ''::character varying, v_ddlcourier character varying DEFAULT ''::character varying, v_merchantname character varying DEFAULT ''::character varying, v_productname character varying DEFAULT ''::character varying, v_ddlcancelationtype integer DEFAULT 0) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_minindex INT;
  v_maxindex INT;
  v_query text;
  v_statusname varchar(100);
  v_statusname1 varchar(50);
  v_statusname2 varchar(50);
  v_statusname5 varchar(50);
  v_statusname6 varchar(50);
BEGIN
  v_minindex := (v_startrowindex - 1) * v_maxrows + 1;
  v_maxindex := v_startrowindex * v_maxrows;
  IF (v_mode = 1) THEN
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp (ROWNUMBER BIGINT,LOGINID VARCHAR(100) ,NAME VARCHAR(1000), 
BRCODE VARCHAR(50), MOBILENO VARCHAR(20), ORDERID VARCHAR(50) ,
ORDERDATE varchar(100), ORDER_QTY INT, ORDER_DAP DECIMAL, 
ORDER_NETAMT DECIMAL,PAYMODE VARCHAR(25), CITY VARCHAR(300), 
TOTAL_VAT DECIMAL, ORDERINTSTATUS INT, POID BIGINT, 
SPRID BIGINT,PRODUCT_QTY INT, SINGLE_DAP DECIMAL, TOTAL_DAP DECIMAL, 
TOTAL_SHIP_CH DECIMAL, TOTAL_COST DECIMAL, PRODUCTTOTALVAT DECIMAL, 
TOTAL_PURCHASE_COST DECIMAL,PRODUCT_NAME varchar (500),PRODQTY varchar (100),
PROUNIT VARCHAR( 500), PRODCOLOR varchar (100),PRODSIZE varchar (100),
PROD_IMAGES text, STATUS VARCHAR( 500), PRODUCTINTSTATUS INT ,
PROCESSBY VARCHAR(500), PROCESSDATE timestamp, PROCESSREMARK VARCHAR(500), 
INVQTY INT, REASON VARCHAR(100), ISCANCELBYMEMBER boolean, 
ISRETURN boolean,Address text,PinCode VARCHAR (50),
CountryName VARCHAR (500),JP decimal(18,0),BV decimal(18,0),
Orderno varchar(100),Approved varchar(1000),dispatchdate varchar(1000),
Producttitle varchar(200),CreatedDate varchar(200),Packed varchar(200),
Handover varchar(200),Intransit varchar(200),Picked varchar(200),
Delivered varchar(200),CancelReason varchar(200),Cancel_Date varchar(100)) ON COMMIT DROP;
  v_query := 'INSERT INTO #TEMP      SELECT ROW_NUMBER() OVER (ORDER BY OM.ORDERDATE asc) AS ROWNUMBER,
	ISNULL(POM.LOGINID,'''') as LOGINID,isnull(OM.FNAME+''''+ISNULL(OM.LNAME,''''),'''') AS NAME,ISNULL(B.CLID,'''') AS BRCODE,
	ISNULL( OM.MOBILENO,'''') as MOBILENO,
	ISNULL(OM.ORDERID,''''),ISNULL( CONVERT(nvarchar ,OM.ORDERDATE,100),'''') as ORDERDATE,ISNULL( POM.Product_Qty,0) as ORDER_QTY,
	ISNULL( OM.ORDER_DAP,0) as ORDER_DAP,ISNULL( OM.ORDER_NETAMT,0)as ORDER_NETAMT,ISNULL( OM.PAYMODE,'''') as PAYMODE,
	isnull(OM.Sh_City,'''') as CITY,
	ISNULL( OM.TOTAL_VAT,0) as TOTAL_VAT,ISNULL( OM.INTSTATUS,0) AS ORDERINTSTATUS,
	ISNULL( POM.POID,0) as POID,ISNULL( CONVERT(BIGINT, POM.SUBPRCODE),0) AS SPRID,
	ISNULL( POM.PRODUCT_QTY,0) as PRODUCT_QTY,ISNULL( POM.SINGLE_DAP,0) as SINGLE_DAP, 
	ISNULL( POM.TOTAL_DAP,0) as TOTAL_DAP,ISNULL( POM.TOTAL_SHIP_CH,0) as TOTAL_SHIP_CH,ISNULL( POM.TOTAL_COST,0) as TOTAL_COST,
	ISNULL(POM.TOTAL_VAT,0) AS PRODUCTTOTALVAT,ISNULL(POM.TOTAL_PURCHASE_COST,0)as TOTAL_PURCHASE_COST, 
	ISNULL(POM.PRODUCT_NAME,'''') as PRODUCT_NAME,ISNULL( POM.PRODQTY,'''') as PRODQTY, ISNULL(POM.PROUNIT,'''') as PROUNIT, 
	ISNULL(POM.PRODCOLOR,'''') as PRODCOLOR,ISNULL( POM.PRODSIZE,'''') as PRODSIZE,ISNULL( POM.PROD_IMAGES,'''') as PROD_IMAGES,
	ISNULL( POM.STATUS,'''') as STATUS,ISNULL( POM.INTSTATUS,0) AS PRODUCTINTSTATUS,
	ISNULL(POM.PROCESSBY,'''') as PROCESSBY ,ISNULL( POM. PROCESSDATE,'''') as PROCESSDATE,ISNULL( POM.PROCESSREMARK,'''') as PROCESSREMARK,
	ISNULL(POM.INVQTY,0) AS INVQTY,
	ISNULL(POM.REASON,'''') as REASON,ISNULL(POM.ISCANCELBYMEMBER,0) AS ISCANCELBYMEMBER , ISNULL(POM.ISRETURN,0) AS ISRETURN ,
	isnull(OM.Address,'''') AS Address,ISNULL(OM.PinCode,'''') AS PinCode,ISNULL(IMS.CountryName,'''') AS CountryName,
	isnull(IMSP.PV,0) AS JP,ISNULL(IMSP.BV,0) AS BV 
	,isnull(POM.Orderno,'''') as Orderno,isnull(OCS.packed,'''') as Approved ,
	isnull(OCS.packed+IMSP.ProcurementSLA,'''') as dispatchdate,ISNULL( PM.PRODUCTTITLE,'''') as PRODUCTTITLE,
	convert(varchar, OCS.CreatedDate,106),convert(varchar,OCS.Packed,106),convert(varchar,OCS.Handover,106),
	convert(varchar,OCS.Intransit,106),convert(varchar,OCS.Picked,106),convert(varchar,OCS.Delivered,106),POM.Reason as CancelReason,convert(date,CN.Cancel,110) as Cancel_Date
	FROM TBL_ORDER_MASTER  OM   
	LEFT JOIN TBL_PRODUCT_ORDER_MASTER POM ON POM.ORDERID = OM.ORDERID 
	--LEFT join PORTAL_LOGIN pl on pl.PLID=OM.BranchId 
	JOIN TBL_CUSTOMERLOGIN B ON B.LOGINID = OM.LoginId
	left join IMS_CustomerAddress IMS on IMS.Id=B.CLID
	JOIN TBL_DISTRIBUTOR TD ON TD.DID=B.DID
	--left join Portal_Master pma on pma.PMID=pl.PMID
	left join IMS_SubProduct IMSP on IMSP.SPRID= POM.SubPrCode
	left join tbl_Order_ConfirmedStaus OCS on OCS.orderno=POM.Orderno
	LEFT JOIN IMS_MASTERPRODUCT PM  ON   IMSP.MPRID=PM.MPRID 
	inner join tbl_Order_ConfirmedStaus as CN on CN.Orderid=POM.ORDERID
	WHERE (POM.INTSTATUS=7 or POM.INTSTATUS=8) AND OM.LOGINID=B.LOGINID  and OM.ORDERID  != ''''';
  IF (v_merchantname <> '') THEN
  v_query := v_query || ' AND (PMA.COMPANYNAME)=''' || v_merchantname || '''';
  END IF;
  IF (v_productname <> '') THEN
  v_query := v_query || ' AND POM.Product_Name=''' || v_productname || '''';
  END IF;
  IF (v_searchfield <> '' AND v_searchvalue <> '') THEN
  IF (v_searchfield = 'MERCHANTCODE') THEN
  v_query := v_query || ' AND B.CODE=''' || v_searchvalue || '''';
  END IF;
  IF (v_searchfield = 'LOGINID') THEN
  v_query := v_query || ' AND OM.LOGINID=''' || v_searchvalue || '''';
  END IF;
  IF (v_searchfield = 'MEMBERNAME') THEN
  v_query := v_query || ' AND ISNULL(B.FNAME,'''')+'' ''+ISNULL(B.LNAME,'''') LIKE ''%' || v_searchvalue || '%''';
  END IF;
  IF (v_searchfield = 'ORDERID') THEN
  v_query := v_query || ' AND OM.ORDERID=''' || v_searchvalue || '''';
  END IF;
  END IF;
  IF (v_company <> '') THEN
  v_query := v_query || ' AND pma.PMID LIKE ''%' || v_company || '%'' ';
  END IF;
  IF (v_orderno <> '') THEN
  v_query := v_query || ' AND POM.Orderno = ''' || v_orderno || ''' ';
  END IF;
  IF (v_orderid <> '') THEN
  v_query := v_query || ' AND POM.OrderId = ''' || v_orderid || ''' ';
  END IF;
  IF (v_poid > 0) THEN
  v_query := v_query || ' AND POM.POID= ''' || CAST(v_poid AS VARCHAR(30)) || ''' ';
  END IF;
  IF ((v_fromdate <> '') AND (v_todate = '')) THEN
  v_query := v_query || ' AND convert(varchar, CONVERT(DATE, OM.ORDERDATE, 105) ) BETWEEN  CONVERT(DATE, ''' || v_fromdate || ''', 105) AND  CONVERT(DATE, DBO.FUN_GETCURRENTDATE(), 105)';
  END IF;
  IF ((v_fromdate = '') AND (v_todate <> '')) THEN
  v_query := v_query || 'AND CONVERT(DATE, OM.ORDERDATE, 105) BETWEEN  CONVERT(DATE, ''' || v_todate || ''', 105) AND  CONVERT(DATE, DBO.FUN_GETCURRENTDATE(), 105)';
  END IF;
  IF ((v_fromdate <> '') AND (v_todate <> '')) THEN
  v_query := v_query || 'AND CONVERT(DATE, OM.ORDERDATE, 105) BETWEEN CONVERT(DATE, ''' || v_fromdate || ''', 105) AND  CONVERT(DATE, ''' || v_todate || ''', 105)';
  END IF;
  IF (v_status <> '') THEN
  v_query := v_query || ' AND ISNULL(OM.STATUS,'''')= ''' || v_status || '''';
  END IF;
  IF (v_statustype <> '') THEN
  IF (v_statustype = 'PENDING') THEN
  v_query := v_query || ' AND POM.STATUS=''PENDING''';
  END IF;
  IF (v_statustype = 'Completed') THEN
  v_query := v_query || ' AND POM.STATUS=''Completed''';
  END IF;
  IF (v_statustype = 'PICK') THEN
  v_query := v_query || ' AND POM.STATUS=''PICK''';
  END IF;
  IF (v_statustype = 'Dispatched') THEN
  v_query := v_query || ' AND POM.STATUS=''Dispatched''';
  END IF;
  IF (v_statustype = 'READY-TO-SHIP') THEN
  RETURN QUERY SELECT 4 AS readyship;
  v_query := v_query || ' AND POM.STATUS=''READYTOSHIP''';
  END IF;
  IF (v_statustype = 'MANIFEST') THEN
  v_query := v_query || ' AND POM.STATUS=''READYTOSHIP''';
  END IF;
  IF (v_statustype = 'Cancel') THEN
  v_query := v_query || ' AND POM.STATUS=''Cancel''';
  END IF;
  IF (v_statustype = 'RETURN') THEN
  v_query := v_query || ' AND POM.STATUS=''RETURN''';
  END IF;
  END IF;
  IF (v_branchid > 0) THEN
  v_query := v_query || ' AND TD.DID=' || CAST(v_branchid AS VARCHAR(20)) || '';
  END IF;
  RAISE NOTICE '%', (v_query);
  EXECUTE v_query;
  IF (v_sortbydispatchorder = 'desc') THEN
  RETURN QUERY SELECT * FROM tmp_temp WHERE rownumber BETWEEN v_minindex AND v_maxindex ORDER BY orderdate DESC NULLS LAST;
  ELSE
  RETURN QUERY SELECT * FROM tmp_temp WHERE rownumber BETWEEN v_minindex AND v_maxindex;
  END IF;
  SELECT COUNT(rownumber) INTO v_totalcount FROM tmp_temp;
  DROP TABLE IF EXISTS tmp_temp;
  -- SET option (removed)
  END IF;
  IF (v_mode = 2) THEN
  SELECT statusname INTO v_statusname FROM orderstatusmaster WHERE osid = v_statusid;
  UPDATE tbl_order_confirmedstaus SET packed = TO_TIMESTAMP(v_statusdate, 'DD/MM/YYYY') WHERE orderid = v_orderid AND customerid = v_loginid;
  UPDATE tbl_product_order_master SET intstatus = v_statusid, status = v_statusname WHERE poid = v_poid;
  END IF;
  IF (v_mode = 3) THEN
  SELECT statusname INTO v_statusname1 FROM orderstatusmaster WHERE osid = v_statusid;
  UPDATE tbl_order_confirmedstaus SET handover = TO_TIMESTAMP(v_statusdate, 'DD/MM/YYYY') WHERE orderid = v_orderid AND customerid = v_loginid;
  UPDATE tbl_product_order_master SET intstatus = v_statusid, status = v_statusname1 WHERE poid = v_poid;
  END IF;
  IF (v_mode = 4) THEN
  SELECT statusname INTO v_statusname2 FROM orderstatusmaster WHERE osid = v_statusid;
  UPDATE tbl_order_confirmedstaus SET intransit = TO_TIMESTAMP(v_statusdate, 'DD/MM/YYYY') WHERE orderid = v_orderid AND customerid = v_loginid;
  UPDATE tbl_product_order_master SET intstatus = v_statusid, docketno = v_docketno, cmid = v_ddlcourier WHERE poid = v_poid;
  END IF;
  IF (v_mode = 5) THEN
  SELECT statusname INTO v_statusname5 FROM orderstatusmaster WHERE osid = v_statusid;
  UPDATE tbl_order_confirmedstaus SET picked = TO_TIMESTAMP(v_statusdate, 'DD/MM/YYYY') WHERE orderid = v_orderid AND customerid = v_loginid;
  UPDATE tbl_product_order_master SET intstatus = v_statusid, status = v_statusname5 WHERE poid = v_poid;
  END IF;
  IF (v_mode = 6) THEN
  SELECT statusname INTO v_statusname6 FROM orderstatusmaster WHERE osid = v_statusid;
  UPDATE tbl_order_confirmedstaus SET delivered = TO_TIMESTAMP(v_statusdate, 'DD/MM/YYYY') WHERE orderid = v_orderid AND customerid = v_loginid;
  UPDATE tbl_product_order_master SET intstatus = v_statusid, status = v_statusname6 WHERE poid = v_poid;
  END IF;
END;
$$;


--
-- Name: usp_all_order_list_excel(integer, integer, character varying, character varying, character varying, character varying, character varying, character varying, bigint, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_all_order_list_excel(v_startrowindex integer DEFAULT 1, v_maxrows integer DEFAULT 100, v_searchfield character varying DEFAULT ''::character varying, v_searchvalue character varying DEFAULT ''::character varying, v_fromdate character varying DEFAULT ''::character varying, v_todate character varying DEFAULT ''::character varying, v_status character varying DEFAULT ''::character varying, v_statustype character varying DEFAULT 'all'::character varying, v_branchid bigint DEFAULT 1, v_totalcount integer DEFAULT 0) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_minindex INT;
  v_maxindex INT;
  v_query text;
BEGIN
  v_minindex := (v_startrowindex - 1) * v_maxrows + 1;
  v_maxindex := v_startrowindex * v_maxrows;
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp (ROWNUMBER BIGINT 
, LOGINID VARCHAR( 100) 
, NAME VARCHAR(100) 
, BRCODE VARCHAR( 50) 
, MOBILENO VARCHAR( 20) 
, ORDERID VARCHAR( 50) 
, ORDERDATE timestamp 
, ORDER_QTY INT 
, ORDER_DAP DECIMAL 
, ORDER_NETAMT DECIMAL 
, PAYMODE VARCHAR( 25) 
, CITY VARCHAR( 30) 
, TOTAL_VAT DECIMAL 
, ORDERINTSTATUS INT 
, POID BIGINT 
, SPRID BIGINT 
, PRODUCT_QTY INT 
, SINGLE_DAP DECIMAL 
, TOTAL_DAP DECIMAL 
, TOTAL_SHIP_CH DECIMAL 
, TOTAL_COST DECIMAL 
, PRODUCTTOTALVAT DECIMAL 
,TOTAL_PURCHASE_COST DECIMAL
, PRODUCT_NAME varchar (100)
, PRODQTY varchar (10)
, PROUNIT VARCHAR( 50) 
, PRODCOLOR varchar (10)
, PRODSIZE varchar (10)
, PROD_IMAGES text 
, STATUS VARCHAR( 50) 
, PRODUCTINTSTATUS INT 
, PROCESSBY VARCHAR( 50) 
, PROCESSDATE timestamp 
, PROCESSREMARK VARCHAR(50) 
, INVQTY INT 
, REASON VARCHAR(100) 
, ISCANCELBYMEMBER boolean 
, ISRETURN boolean
, Address VARCHAR( 1000)
, PinCode VARCHAR (50)
, CountryName VARCHAR (50)
,JP decimal(18,0)
,BV decimal(18,0)) ON COMMIT DROP;
  v_query := 'INSERT INTO #TEMP  SELECT ROW_NUMBER() OVER (ORDER BY OM.ORDERDATE DESC) AS ROWNUMBER,
POM.LOGINID,(OM.FNAME+''''+ISNULL(OM.LNAME,'''')) AS NAME,B.CLID AS BRCODE,OM.MOBILENO,
OM.ORDERID,OM.ORDERDATE,OM.ORDER_QTY,OM.ORDER_DAP,OM.ORDER_NETAMT,OM.PAYMODE,isnull(OM.Sh_City,'''') as CITY,
OM.TOTAL_VAT,OM.INTSTATUS AS ORDERINTSTATUS,POM.POID, CONVERT(BIGINT, POM.SUBPRCODE) AS SPRID,
POM.PRODUCT_QTY, POM.SINGLE_DAP, POM.TOTAL_DAP, POM.TOTAL_SHIP_CH, POM.TOTAL_COST,
POM.TOTAL_VAT AS PRODUCTTOTALVAT,POM.TOTAL_PURCHASE_COST, POM.PRODUCT_NAME, POM.PRODQTY, POM.PROUNIT, 
POM.PRODCOLOR, POM.PRODSIZE, POM.PROD_IMAGES, POM.STATUS, POM.INTSTATUS AS PRODUCTINTSTATUS,
POM.PROCESSBY, POM. PROCESSDATE, POM.PROCESSREMARK,ISNULL(POM.INVQTY,0) AS INVQTY,
POM.REASON,ISNULL(POM.ISCANCELBYMEMBER,0) AS ISCANCELBYMEMBER , ISNULL(POM.ISRETURN,0) AS ISRETURN ,isnull(OM.Address,'''') AS Address,ISNULL(OM.PinCode,'''') AS PinCode,ISNULL(IMS.CountryName,'''') AS CountryName,
isnull(IMSP.PV,0) AS JP,ISNULL(IMSP.BV,0) AS BV
FROM  TBL_PRODUCT_ORDER_MASTER POM 
LEFT JOIN TBL_ORDER_MASTER OM  ON  OM.ORDERID =POM.ORDERID 
join PORTAL_LOGIN pl on pl.PLID=OM.BranchId JOIN TBL_CUSTOMERLOGIN B ON B.LOGINID = OM.LoginId
left join IMS_CustomerAddress IMS on IMS.Id=B.CLID
left join IMS_SubProduct IMSP on IMSP.SPRID= POM.SubPrCode
WHERE OM.LOGINID=B.LOGINID AND OM.ORDERID != ''''';
  IF (v_searchfield <> '' AND v_searchvalue <> '') THEN
  IF (v_searchfield = 'MERCHANTCODE') THEN
  v_query := v_query || ' AND B.CODE=''' || v_searchvalue || '''';
  END IF;
  IF (v_searchfield = 'LOGINID') THEN
  v_query := v_query || ' AND OM.LOGINID=''' || v_searchvalue || '''';
  END IF;
  IF (v_searchfield = 'MEMBERNAME') THEN
  v_query := v_query || ' AND ISNULL(B.FNAME,'''')+'' ''+ISNULL(B.LNAME,'''') LIKE ''%' || v_searchvalue || '%''';
  END IF;
  IF (v_searchfield = 'ORDERID') THEN
  v_query := v_query || ' AND OM.ORDERID=''' || v_searchvalue || '''';
  END IF;
  END IF;
  IF ((v_fromdate <> '') AND (v_todate = '')) THEN
  v_query := v_query || ' AND CONVERT(DATE, OM.ORDERDATE, 105) BETWEEN  CONVERT(DATE, ''' || v_fromdate || ''', 105) AND  CONVERT(DATE, DBO.FUN_GETCURRENTDATE(), 105)';
  END IF;
  IF ((v_fromdate = '') AND (v_todate <> '')) THEN
  v_query := v_query || 'AND CONVERT(DATE, OM.ORDERDATE, 105) BETWEEN  CONVERT(DATE, ''' || v_todate || ''', 105) AND  CONVERT(DATE, DBO.FUN_GETCURRENTDATE(), 105)';
  END IF;
  IF ((v_fromdate <> '') AND (v_todate <> '')) THEN
  v_query := v_query || 'AND CONVERT(DATE, OM.ORDERDATE, 105) BETWEEN CONVERT(DATE, ''' || v_fromdate || ''', 105) AND  CONVERT(DATE, ''' || v_todate || ''', 105)';
  END IF;
  IF (v_status <> '') THEN
  v_query := v_query || ' AND ISNULL(OM.STATUS,'''')= ''' || v_status || '''';
  END IF;
  IF (v_statustype <> '') THEN
  IF (v_statustype = 'PENDING') THEN
  v_query := v_query || ' AND POM.STATUS=''PENDING''';
  END IF;
  IF (v_statustype = 'Completed') THEN
  v_query := v_query || ' AND POM.STATUS=''Completed''';
  END IF;
  IF (v_statustype = 'PICK') THEN
  v_query := v_query || ' AND POM.STATUS=''PICK''';
  END IF;
  IF (v_statustype = 'Dispatched') THEN
  v_query := v_query || ' AND POM.STATUS=''Dispatched''';
  END IF;
  IF (v_statustype = 'READY-TO-SHIP') THEN
  RETURN QUERY SELECT 4 AS readyship;
  v_query := v_query || ' AND POM.STATUS=''READYTOSHIP''';
  END IF;
  IF (v_statustype = 'MANIFEST') THEN
  v_query := v_query || ' AND POM.STATUS=''READYTOSHIP''';
  END IF;
  IF (v_statustype = 'Cancel') THEN
  v_query := v_query || ' AND POM.STATUS=''Cancel''';
  END IF;
  IF (v_statustype = 'RETURN') THEN
  v_query := v_query || ' AND POM.STATUS=''RETURN''';
  END IF;
  END IF;
  IF (v_branchid > 0) THEN
  v_query := v_query || ' AND pl.PLID=' || CAST(v_branchid AS VARCHAR(20)) || '';
  END IF;
  EXECUTE v_query;
  RAISE NOTICE '%', (v_query);
  RETURN QUERY SELECT * FROM tmp_temp WHERE rownumber BETWEEN v_minindex AND v_maxindex;
  SELECT COUNT(rownumber) INTO v_totalcount FROM tmp_temp;
  DROP TABLE IF EXISTS tmp_temp;
  -- SET option (removed)
END;
$$;


--
-- Name: usp_all_overall_order(integer, integer, character varying, character varying, character varying, character varying, integer, character varying, character varying, bigint, character varying, integer, integer, character varying, character varying, character varying, character varying, character varying, character varying, character varying, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_all_overall_order(v_startrowindex integer DEFAULT 1, v_maxrows integer DEFAULT 100, v_searchfield character varying DEFAULT ''::character varying, v_searchvalue character varying DEFAULT ''::character varying, v_fromdate character varying DEFAULT ''::character varying, v_todate character varying DEFAULT ''::character varying, v_totalcount integer DEFAULT 0, v_orderid character varying DEFAULT ''::character varying, v_company character varying DEFAULT ''::character varying, v_poid bigint DEFAULT 0, v_orderno character varying DEFAULT ''::character varying, v_mode integer DEFAULT 1, v_statusid integer DEFAULT 0, v_loginid character varying DEFAULT ''::character varying, v_sortbydispatchorder character varying DEFAULT ''::character varying, v_statusdate character varying DEFAULT ''::character varying, v_docketno character varying DEFAULT ''::character varying, v_ddlcourier character varying DEFAULT ''::character varying, v_merchantname character varying DEFAULT ''::character varying, v_productname character varying DEFAULT ''::character varying, v_ddlcancelationtype integer DEFAULT 0) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_minindex INT;
  v_maxindex INT;
  v_query text;
BEGIN
  v_minindex := (v_startrowindex - 1) * v_maxrows + 1;
  v_maxindex := v_startrowindex * v_maxrows;
  IF (v_mode = 1) THEN
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp (ROWNUMBER BIGINT   
, LOGINID VARCHAR(100)   
, NAME VARCHAR(1000)   
, BRCODE VARCHAR(50),
USERNAME VARCHAR(100) ,
PHONE VARCHAR(100) ,
FNAME VARCHAR(100) ,
EMAILID VARCHAR(100) 
, MOBILENO VARCHAR(20)   
, ORDERID VARCHAR( 50)   
, ORDERDATE VARCHAR(50)   
, ORDER_QTY INT   
, ORDER_DAP DECIMAL (18,2)   
, ORDER_NETAMT DECIMAL (18,2)  
, PAYMODE VARCHAR( 25)   
, CITY VARCHAR(300)   
, TOTAL_VAT DECIMAL (18,2)  
, ORDERINTSTATUS INT   
, POID BIGINT   
, SPRID BIGINT   
, PRODUCT_QTY INT   
, SINGLE_DAP DECIMAL (18,2)   
, TOTAL_DAP DECIMAL  (18,2)  
, TOTAL_SHIP_CH DECIMAL  (18,2)  
, TOTAL_COST DECIMAL (18,2)  
, PRODUCTTOTALVAT DECIMAL (18,2)   
,TOTAL_PURCHASE_COST DECIMAL (18,2)  
, PRODUCT_NAME varchar (500)  
, PRODQTY varchar (100)  
, PROUNIT VARCHAR( 500)   
, PRODCOLOR varchar (100)  
, PRODSIZE varchar (100)  
, PROD_IMAGES text   
, STATUS VARCHAR(500)   
, PRODUCTINTSTATUS INT   
, PROCESSBY VARCHAR(500)   
, PROCESSDATE timestamp   
, PROCESSREMARK VARCHAR(500)   
, INVQTY INT   
, REASON VARCHAR(100)   
, ISCANCELBYMEMBER boolean   
, ISRETURN boolean  
, ADDRESS text  
, PINCODE VARCHAR (50)  
, COUNTRYNAME VARCHAR (500)  
,JP DECIMAL(18,0)  
,BV DECIMAL(18,0)  
,COMPANYNAME VARCHAR(1000)  
,PMID BIGINT,  
SUBPRCODE VARCHAR(1000),  
APPROVED VARCHAR(1000),  
DISPATCHDATE VARCHAR(1000),  
ORDERNO VARCHAR(1000),  
COURIERNAME VARCHAR(1000),  
DOCKETNO VARCHAR(1000),  
DATEDIFF INT,  
MERCHANTNAME VARCHAR(100),  
MERCHANTMOBILE varchar(100),
FranchiseId int,
MORDERID VARCHAR(100),  
INVOICENO VARCHAR(100),  
CREATEDDATE VARCHAR(100),  
PACKED VARCHAR(100),  
HANDOVER VARCHAR(100),  
INTRANSIT VARCHAR(100),  
DELIVERED VARCHAR(100),  
CANCEL VARCHAR(100),  
OUTFORDELIVERY VARCHAR(100),  
DISTRIBUTORNAME VARCHAR(100)) ON COMMIT DROP;
  v_query := 'INSERT INTO #TEMP SELECT ROW_NUMBER() OVER (ORDER BY OM.ORDERDATE DESC) AS ROWNUMBER,  
POM.LOGINID,(OM.FNAME+''''+ISNULL(OM.LNAME,'''')) AS NAME,B.CLID AS BRCODE,B.USERNAME,B.PHONE,MM.FNAME,MM.EMAILID,OM.MOBILENO,  
OM.ORDERID,OM.ORDERDATE,OM.ORDER_QTY,OM.ORDER_DAP,OM.ORDER_NETAMT,  
(CASE WHEN OM.PAYMODE=''PAYUMONEY'' THEN ''WALLET'' ELSE OM.PAYMODE END) AS PAYMODE,  
ISNULL(OM.SH_CITY,'''') AS CITY,  
OM.TOTAL_VAT,OM.INTSTATUS AS ORDERINTSTATUS,POM.POID, CONVERT(BIGINT, POM.SUBPRCODE) AS SPRID,  
POM.PRODUCT_QTY, POM.SINGLE_DAP, POM.TOTAL_DAP, POM.TOTAL_SHIP_CH, POM.TOTAL_COST,  
POM.TOTAL_VAT AS PRODUCTTOTALVAT,POM.TOTAL_PURCHASE_COST, POM.PRODUCT_NAME, POM.PRODQTY, POM.PROUNIT,   
POM.PRODCOLOR, POM.PRODSIZE, POM.PROD_IMAGES,   
(CASE WHEN POM.STATUS=''COMPLETED'' THEN ''DELIVERED'' ELSE POM.STATUS END),   
POM.INTSTATUS AS PRODUCTINTSTATUS,  
POM.PROCESSBY, POM. PROCESSDATE, POM.PROCESSREMARK,ISNULL(POM.INVQTY,0) AS INVQTY,  
POM.REASON,ISNULL(POM.ISCANCELBYMEMBER,0) AS ISCANCELBYMEMBER , ISNULL(POM.ISRETURN,0) AS ISRETURN ,  
ISNULL(OM.ADDRESS,'''') AS ADDRESS,ISNULL(OM.PINCODE,'''') AS PINCODE,ISNULL(IMS.COUNTRYNAME,'''') AS COUNTRYNAME,  
ISNULL(IMSP.PV,0) AS JP,ISNULL(IMSP.BV,0) AS BV,PMA.COMPANYNAME,PMA.PMID,IMSP.SUBPRCODE,  
ISNULL(OCS.PACKED,'''') AS APPROVED ,  
ISNULL(OCS.PACKED+IMSP.PROCUREMENTSLA,'''') AS DISPATCHDATE,  
ISNULL(POM.ORDERNO,'''') AS ORDERNO,  
ISNULL(CM.CARRIER_NAME,'''') AS COURIERNAME,  
ISNULL(POM.DOCKETNO,'''') AS DOCKETNO,  
ISNULL(DATEDIFF(DAY,OM.ORDERDATE,OCS.DELIVERED),0) AS DATEDIFF,ISNULL(PMA.COMPANYNAME,'''') AS MERCHANTNAME,PMA.MOBILENO as MERCHANTMOBILE,PMA.Distributorid as FranchiseId,  
POM.MORDERID,POM.INVOICENO,CONVERT(VARCHAR(100),OCS.CREATEDDATE,106),CONVERT(VARCHAR(100),OCS.PACKED,106),CONVERT(VARCHAR(100),OCS.HANDOVER,106),  
CONVERT(VARCHAR(100),OCS.INTRANSIT,106),CONVERT(VARCHAR(100),OCS.DELIVERED,106),CONVERT(VARCHAR(100),OCS.CANCEL,106),CONVERT(VARCHAR(100),OCS.OUTFORDELIVERY,106),  
DM.COMPANYNAME  
FROM TBL_ORDER_MASTER OM   
LEFT JOIN TBL_PRODUCT_ORDER_MASTER POM ON POM.ORDERID = OM.ORDERID   
JOIN PORTAL_LOGIN PL ON PL.PLID=POM.PLID   
LEFT JOIN TBL_CUSTOMERLOGIN B ON B.LOGINID = OM.LOGINID  
LEFT JOIN IMS_CUSTOMERADDRESS IMS ON IMS.ID=B.CLID  
LEFT JOIN PORTAL_MASTER PMA ON PMA.PMID=PL.PMID  
LEFT JOIN IMS_SUBPRODUCT IMSP ON IMSP.SPRID= POM.SUBPRCODE  
LEFT JOIN TBL_COURIERMASTER CM ON CM.CMID=POM.CMID  
LEFT JOIN TBL_ORDER_CONFIRMEDSTAUS OCS ON OCS.ORDERNO=POM.ORDERNO   
LEFT JOIN DISTRIBUTOR_MASTER DM ON B.DID=DM.PLID  
LEFT JOIN [Db_Affiliate].[DBO].[MEMBER_MASTER] MM ON MM.USERNAME=B.USERNAME
WHERE POM.INTSTATUS>=0 ';
  IF (v_merchantname <> '') THEN
  v_query := v_query || ' AND (PMA.COMPANYNAME)=''' || v_merchantname || '''';
  END IF;
  IF (v_productname <> '') THEN
  v_productname := REPLACE(v_productname, '''', '''''');
  v_query := v_query || ' AND POM.PRODUCT_NAME=''' || v_productname || '''';
  END IF;
  IF (v_searchfield <> '' AND v_searchvalue <> '') THEN
  IF (v_searchfield = 'MERCHANTCODE') THEN
  v_query := v_query || ' AND B.CODE=''' || v_searchvalue || '''';
  END IF;
  IF (v_searchfield = 'LOGINID') THEN
  v_query := v_query || ' AND OM.LOGINID=''' || v_searchvalue || '''';
  END IF;
  IF (v_searchfield = 'MEMBERNAME') THEN
  v_query := v_query || ' AND ISNULL(B.FNAME,'''')+'' ''+ISNULL(B.LNAME,'''') LIKE ''%' || v_searchvalue || '%''';
  END IF;
  IF (v_searchfield = 'ORDERID') THEN
  v_query := v_query || ' AND OM.ORDERID=''' || v_searchvalue || '''';
  END IF;
  END IF;
  IF (v_company <> '') THEN
  v_query := v_query || ' AND PMA.PMID LIKE ''%' || v_company || '%'' ';
  END IF;
  IF (v_orderno <> '') THEN
  v_query := v_query || ' AND POM.MORDERID = ''' || v_orderno || ''' ';
  END IF;
  IF (v_orderid <> '') THEN
  v_query := v_query || ' AND POM.ORDERID = ''' || v_orderid || ''' ';
  END IF;
  IF (v_poid > 0) THEN
  v_query := v_query || ' AND POM.POID= ''' || CAST(v_poid AS VARCHAR(30)) || ''' ';
  END IF;
  IF ((v_fromdate <> '') AND (v_todate = '')) THEN
  v_query := v_query || ' AND CONVERT(VARCHAR, CONVERT(DATE, OM.ORDERDATE, 105) ) BETWEEN  CONVERT(DATE, ''' || v_fromdate || ''', 105) AND  CONVERT(DATE, DBO.FUN_GETCURRENTDATE(), 105)';
  END IF;
  IF ((v_fromdate = '') AND (v_todate <> '')) THEN
  v_query := v_query || 'AND CONVERT(DATE, OM.ORDERDATE, 105) BETWEEN  CONVERT(DATE, ''' || v_todate || ''', 105) AND  CONVERT(DATE, DBO.FUN_GETCURRENTDATE(), 105)';
  END IF;
  IF ((v_fromdate <> '') AND (v_todate <> '')) THEN
  v_query := v_query || 'AND CONVERT(DATE, OM.ORDERDATE, 105) BETWEEN CONVERT(DATE, ''' || v_fromdate || ''', 105) AND  CONVERT(DATE, ''' || v_todate || ''', 105)';
  END IF;
  IF (v_sortbydispatchorder <> '') THEN
  v_query := v_query || ' ORDER BY  CONVERT(DATETIME, OM.ORDERDATE, 103) ' || v_sortbydispatchorder || '';
  END IF;
  EXECUTE v_query;
  RAISE NOTICE '%', (v_query);
  RETURN QUERY SELECT * FROM tmp_temp WHERE rownumber BETWEEN v_minindex AND v_maxindex;
  SELECT COUNT(rownumber) INTO v_totalcount FROM tmp_temp;
  DROP TABLE IF EXISTS tmp_temp;
  -- SET option (removed)
  END IF;
END;
$$;


--
-- Name: usp_all_product_searching_autofilter_mobile(character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_all_product_searching_autofilter_mobile(v_searchfilter character varying DEFAULT 'A'::character varying) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_count INT;
  v_serchitem VARCHAR(250);
BEGIN
  -- SET option (removed)
  v_serchitem := '';
  v_serchitem := v_searchfilter;
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp (SEARCHRESULT  text,
FOMATEDRESULT  text, 
FORURL text, 
SEARCHTYPE VARCHAR(200), 
MPRID BIGINT,
CatID bigint, 
MAINCATID BIGINT,
ScatID bigint) ON COMMIT DROP;
  IF EXISTS(SELECT maincatid FROM tbl_main_category WHERE status = 1 AND ' ' || maincatname LIKE '% ' || v_serchitem || '%') THEN
  INSERT INTO tmp_temp SELECT DISTINCT (maincatname) AS serachtext, maincatname, '/shop/' || main_cat_code, 'maincategory', 0, 0, maincatid, 0 FROM tbl_main_category WHERE status = 1 AND ' ' || maincatname LIKE '% ' || v_serchitem || '%';
  END IF;
  IF EXISTS(SELECT catid FROM tbl_category WHERE status = 1 AND ' ' || catname LIKE '% ' || v_serchitem || '%') THEN
  INSERT INTO tmp_temp SELECT DISTINCT (pc.catname) AS serachtext, (pc.catname || ' in ' || LOWER(pc.catname)), '/shop/' || mpc.main_cat_code || '/' || pc.cat_code, 'category', 0, pc.catid, mpc.maincatid, 0 FROM tbl_category AS pc JOIN tbl_main_category AS mpc ON pc.maincatid = mpc.maincatid WHERE pc.status = 1 AND ' ' || pc.catname LIKE '% ' || v_serchitem || '%' AND mpc.maincatid IN (SELECT maincategoryid FROM ims_masterproduct) AND pc.totalactive > 0;
  END IF;
  IF EXISTS(SELECT subcatid FROM tbl_sub_category WHERE status = 1 AND ' ' || subcatname LIKE '%' || v_serchitem || '%') THEN
  INSERT INTO tmp_temp SELECT DISTINCT (sc.subcatname) AS serachtext, ' in ' || LOWER(pc.catname), '/shop/' || mpc.main_cat_code || '/' || pc.cat_code || '/' || sc.sub_cat_code, 'scategory', 0, sc.catid, mpc.maincatid, sc.subcatid AS scatid FROM tbl_sub_category AS sc JOIN tbl_category AS pc ON sc.catid = pc.catid JOIN tbl_main_category AS mpc ON mpc.maincatid = pc.maincatid WHERE sc.status = 1 AND pc.status = 1 AND ' ' || sc.subcatname LIKE '% ' || v_serchitem || '%' AND mpc.maincatid IN (SELECT maincategoryid FROM ims_masterproduct) AND sc.totalactive > 0;
  END IF;
  INSERT INTO tmp_temp SELECT DISTINCT (CASE WHEN pms.stockin <> 0 THEN pmm.producttitle || '' WHEN pms.color <> '' THEN pmm.producttitle || ' (' || CAST(pms.color AS VARCHAR(100)) || ' )' WHEN pms.size <> '' THEN pmm.producttitle || ' (' || CAST(pms.size AS VARCHAR(100)) || ' )' ELSE pmm.producttitle END) AS searchresult, (' in ' || LOWER(tc.catname)) AS fomatedresult, '/p/' || LOWER(REPLACE(CAST(pmm.producttitle AS VARCHAR(100)), ' ', '-')) AS forurl, 'Product' AS searchtype, pms.sprid AS mprid, pmm.catid, pmm.maincategoryid, pmm.subcategoryid AS scatid FROM ims_masterproduct AS pmm INNER JOIN ims_subproduct AS pms ON pmm.mprid = pms.mprid INNER JOIN tbl_category AS tc ON pmm.catid = tc.catid WHERE pms.isactive = 1 AND ' ' || pmm.producttitle LIKE '%' || v_serchitem || '%' AND tc.totalactive > 0 AND pms.ismerchantstatus = 5 AND pms.isverified = 1;
  RETURN QUERY SELECT DISTINCT (searchresult) AS producttitle, (fomatedresult) AS categoryin, searchtype AS producttext, (mprid) AS sprid, dbo.fun_findcount(searchresult) AS cnt, catid, maincatid, scatid FROM tmp_temp ORDER BY cnt ASC NULLS FIRST LIMIT 10;
  DROP TABLE IF EXISTS tmp_temp;
  -- SET option (removed)
END;
$$;


--
-- Name: usp_all_reseller_order_list(integer, integer, character varying, character varying, character varying, character varying, character varying, character varying, bigint, integer, character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_all_reseller_order_list(v_startrowindex integer DEFAULT 1, v_maxrows integer DEFAULT 100, v_searchfield character varying DEFAULT ''::character varying, v_searchvalue character varying DEFAULT ''::character varying, v_fromdate character varying DEFAULT ''::character varying, v_todate character varying DEFAULT ''::character varying, v_status character varying DEFAULT ''::character varying, v_statustype character varying DEFAULT 'all'::character varying, v_branchid bigint DEFAULT 1, v_totalcount integer DEFAULT 0, v_company character varying DEFAULT ''::character varying) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_minindex INT;
  v_maxindex INT;
  v_query text;
BEGIN
  v_minindex := (v_startrowindex - 1) * v_maxrows + 1;
  v_maxindex := v_startrowindex * v_maxrows;
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp (ROWNUMBER BIGINT 
, LOGINID VARCHAR( 100) 
, NAME VARCHAR(1000) 
, BRCODE VARCHAR( 50) 
, MOBILENO VARCHAR(20) 
, ORDERID VARCHAR( 50) 
, ORDERDATE timestamp 
, ORDER_QTY INT 
, ORDER_DAP DECIMAL 
, ORDER_NETAMT DECIMAL
, PAYMODE VARCHAR( 25) 
, CITY VARCHAR(300) 
, TOTAL_VAT DECIMAL 
, ORDERINTSTATUS INT 
, POID BIGINT 
, SPRID BIGINT 
, PRODUCT_QTY INT 
, SINGLE_DAP DECIMAL 
, TOTAL_DAP DECIMAL 
, TOTAL_SHIP_CH DECIMAL 
, TOTAL_COST DECIMAL 
, PRODUCTTOTALVAT DECIMAL 
,TOTAL_PURCHASE_COST DECIMAL
, PRODUCT_NAME varchar (500)
, PRODQTY varchar (100)
, PROUNIT VARCHAR( 500) 
, PRODCOLOR varchar (100)
, PRODSIZE varchar (100)
, PROD_IMAGES text 
, STATUS VARCHAR( 500) 
, PRODUCTINTSTATUS INT 
, PROCESSBY VARCHAR( 500) 
, PROCESSDATE timestamp 
, PROCESSREMARK VARCHAR(500) 
, INVQTY INT 
, REASON VARCHAR(100) 
, ISCANCELBYMEMBER boolean 
, ISRETURN boolean
, Address text
, PinCode VARCHAR (50)
, CountryName VARCHAR (500)
,JP decimal(18,0)
,BV decimal(18,0)

,pmid bigint) ON COMMIT DROP;
  v_query := 'INSERT INTO #TEMP  SELECT ROW_NUMBER() OVER (ORDER BY OM.ORDERDATE DESC) AS ROWNUMBER,
POM.LOGINID,(OM.FNAME+''''+ISNULL(OM.LNAME,'''')) AS NAME,B.CLID AS BRCODE,OM.MOBILENO,
OM.ORDERID,OM.ORDERDATE,OM.ORDER_QTY,OM.ORDER_DAP,OM.ORDER_NETAMT,OM.PAYMODE,isnull(OM.Sh_City,'''') as CITY,
OM.TOTAL_VAT,OM.INTSTATUS AS ORDERINTSTATUS,POM.POID, CONVERT(BIGINT, POM.SUBPRCODE) AS SPRID,
POM.PRODUCT_QTY, POM.SINGLE_DAP, POM.TOTAL_DAP, POM.TOTAL_SHIP_CH, POM.TOTAL_COST,
POM.TOTAL_VAT AS PRODUCTTOTALVAT,POM.TOTAL_PURCHASE_COST, POM.PRODUCT_NAME, POM.PRODQTY, POM.PROUNIT, 
POM.PRODCOLOR, POM.PRODSIZE, POM.PROD_IMAGES, POM.STATUS, POM.INTSTATUS AS PRODUCTINTSTATUS,
POM.PROCESSBY, POM. PROCESSDATE, POM.PROCESSREMARK,ISNULL(POM.INVQTY,0) AS INVQTY,
POM.REASON,ISNULL(POM.ISCANCELBYMEMBER,0) AS ISCANCELBYMEMBER , ISNULL(POM.ISRETURN,0) AS ISRETURN ,isnull(OM.Address,'''') AS Address,ISNULL(OM.PinCode,'''') AS PinCode,ISNULL(IMS.CountryName,'''') AS CountryName,
isnull(IMSP.PV,0) AS JP,ISNULL(IMSP.BV,0) AS BV,TD.DID--pma.COMPANYNAME,pma.PMID
FROM TBL_ORDER_MASTER OM 
LEFT JOIN TBL_PRODUCT_ORDER_MASTER POM ON POM.ORDERID = OM.ORDERID 
--join PORTAL_LOGIN pl on pl.PLID=OM.BranchId
 JOIN TBL_CUSTOMERLOGIN B ON B.LOGINID = OM.LoginId
JOIN TBL_DISTRIBUTOR TD ON TD.DID=B.DID
left join IMS_CustomerAddress IMS on IMS.Id=B.CLID
--left join Portal_Master pma on pma.PMID=pl.PMID
left join IMS_SubProduct IMSP on IMSP.SPRID= POM.SubPrCode
WHERE OM.LOGINID=B.LOGINID AND OM.ORDERID != ''''';
  IF (v_searchfield <> '' AND v_searchvalue <> '') THEN
  IF (v_searchfield = 'MERCHANTCODE') THEN
  v_query := v_query || ' AND B.CODE=''' || v_searchvalue || '''';
  END IF;
  IF (v_searchfield = 'LOGINID') THEN
  v_query := v_query || ' AND OM.LOGINID=''' || v_searchvalue || '''';
  END IF;
  IF (v_searchfield = 'MEMBERNAME') THEN
  v_query := v_query || ' AND ISNULL(B.FNAME,'''')+'' ''+ISNULL(B.LNAME,'''') LIKE ''%' || v_searchvalue || '%''';
  END IF;
  IF (v_searchfield = 'ORDERID') THEN
  v_query := v_query || ' AND OM.ORDERID=''' || v_searchvalue || '''';
  END IF;
  END IF;
  IF (v_company <> '') THEN
  v_query := v_query || ' AND pma.PMID LIKE ''%' || v_company || '%'' ';
  END IF;
  IF ((v_fromdate <> '') AND (v_todate = '')) THEN
  v_query := v_query || ' AND CONVERT(DATE, OM.ORDERDATE, 105) BETWEEN  CONVERT(DATE, ''' || v_fromdate || ''', 105) AND  CONVERT(DATE, DBO.FUN_GETCURRENTDATE(), 105)';
  END IF;
  IF ((v_fromdate = '') AND (v_todate <> '')) THEN
  v_query := v_query || 'AND CONVERT(DATE, OM.ORDERDATE, 105) BETWEEN  CONVERT(DATE, ''' || v_todate || ''', 105) AND  CONVERT(DATE, DBO.FUN_GETCURRENTDATE(), 105)';
  END IF;
  IF ((v_fromdate <> '') AND (v_todate <> '')) THEN
  v_query := v_query || 'AND CONVERT(DATE, OM.ORDERDATE, 105) BETWEEN CONVERT(DATE, ''' || v_fromdate || ''', 105) AND  CONVERT(DATE, ''' || v_todate || ''', 105)';
  END IF;
  IF (v_status <> '') THEN
  v_query := v_query || ' AND ISNULL(OM.STATUS,'''')= ''' || v_status || '''';
  END IF;
  IF (v_statustype <> '') THEN
  IF (v_statustype = 'PENDING') THEN
  v_query := v_query || ' AND POM.STATUS=''PENDING''';
  END IF;
  IF (v_statustype = 'Completed') THEN
  v_query := v_query || ' AND POM.STATUS=''Completed''';
  END IF;
  IF (v_statustype = 'PICK') THEN
  v_query := v_query || ' AND POM.STATUS=''PICK''';
  END IF;
  IF (v_statustype = 'Dispatched') THEN
  v_query := v_query || ' AND POM.STATUS=''Dispatched''';
  END IF;
  IF (v_statustype = 'READY-TO-SHIP') THEN
  RETURN QUERY SELECT 4 AS readyship;
  v_query := v_query || ' AND POM.STATUS=''READYTOSHIP''';
  END IF;
  IF (v_statustype = 'MANIFEST') THEN
  v_query := v_query || ' AND POM.STATUS=''READYTOSHIP''';
  END IF;
  IF (v_statustype = 'Cancel') THEN
  v_query := v_query || ' AND POM.STATUS=''Cancel''';
  END IF;
  IF (v_statustype = 'RETURN') THEN
  v_query := v_query || ' AND POM.STATUS=''RETURN''';
  END IF;
  END IF;
  IF (v_branchid > 0) THEN
  v_query := v_query || ' AND TD.DID=' || CAST(v_branchid AS VARCHAR(20)) || '';
  END IF;
  EXECUTE v_query;
  RAISE NOTICE '%', (v_query);
  RETURN QUERY SELECT * FROM tmp_temp WHERE rownumber BETWEEN v_minindex AND v_maxindex;
  SELECT COUNT(rownumber) INTO v_totalcount FROM tmp_temp;
  DROP TABLE IF EXISTS tmp_temp;
  -- SET option (removed)
END;
$$;


--
-- Name: usp_all_statement_history(character varying, integer, integer, character varying, character varying, character varying, character varying, character varying, numeric, numeric, numeric, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_all_statement_history(v_plid character varying DEFAULT ''::character varying, v_startrowindex integer DEFAULT 1, v_maxrows integer DEFAULT 10, v_searchfield character varying DEFAULT ''::character varying, v_searchvalue character varying DEFAULT ''::character varying, v_fromdate character varying DEFAULT ''::character varying, v_todate character varying DEFAULT ''::character varying, v_loginid character varying DEFAULT ''::character varying, v_total_dr numeric DEFAULT 0, v_total_cr numeric DEFAULT 0, v_totalbal numeric DEFAULT 0, v_totalcount integer DEFAULT 0) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_minindex int;
  v_maxindex int;
  v_query text;
BEGIN
  v_minindex := (v_startrowindex - 1) * v_maxrows + 1;
  v_maxindex := v_startrowindex * v_maxrows;
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp (rownumber bigint,
processID bigint,
regNo varchar(100),
processDate varchar(100),
CrDrType varchar(100),
Cr_amount decimal(18,2),
Dr_amount decimal(18,2),
remarks text,
type varchar(200),
typeID bigint,
Status boolean,
TraceNo varchar(200),
pmoid int,
old_Bal numeric(19,4),
Balance decimal(18,2),
fromloginid varchar(200)) ON COMMIT DROP;
  v_query := 'insert into #temp  select ROW_NUMBER() OVER(ORDER BY wh.processDate desc) AS rowNumber,wh.processID,wh.regNo,convert (varchar(20),wh.processDate,105) as processDate,wh.CrDrType,isnull(wh.Cr_amount,0),
          isnull(wh.Dr_amount,0),isnull(wh.remarks,''''),wh.type,wh.typeID, wh.Status,wh.TraceNo,wh.pmoid,wh.old_Bal,wh.Balance,isnull(pl.loginid,'''') as fromloginid from
          money_statements wh inner join member_master mm on mm.regno=wh.regno left join PORTAL_LOGIN pl on pl.plid=mm.plid where wh.status=1';
  IF (v_plid <> 0) THEN
  v_query := v_query || ' and  wh.TOID =''' || v_plid || ''' ';
  END IF;
  IF (v_searchfield <> '' AND v_searchvalue <> '') THEN
  IF (v_searchfield = 'loginid') THEN
  v_query := v_query || ' and pl.loginid =''' || v_searchvalue || ''' ';
  END IF;
  END IF;
  IF ((v_fromdate <> '') AND (v_todate = '')) THEN
  v_query := v_query || ' and CONVERT(date, wh.DATE) between  CONVERT(date, ''' || v_fromdate || ''') and  CONVERT(date, dbo.fun_getCurrentDate()) ';
  END IF;
  IF ((v_fromdate = '') AND (v_todate <> '')) THEN
  v_query := v_query || ' and CONVERT(date, wh.processDate) between  CONVERT(date, ''' || v_todate || ''') and  CONVERT(date, dbo.fun_getCurrentDate()) ';
  END IF;
  IF ((v_fromdate <> '') AND (v_todate <> '')) THEN
  v_query := v_query || ' and CONVERT(date, wh.processDate) between CONVERT(date, ''' || v_fromdate || ''') and  CONVERT(date, ''' || v_todate || ''') ';
  END IF;
  IF (v_loginid <> '') THEN
  v_query := v_query || ' AND ISNULL(pl.loginid,'''') LIKE ''%' || v_loginid || '%''';
  END IF;
  EXECUTE v_query;
  RETURN QUERY SELECT * FROM tmp_temp WHERE rownumber BETWEEN v_startrowindex AND v_maxindex;
  SELECT COUNT(rownumber), SUM(COALESCE(cr_amount, 0)), SUM(COALESCE(dr_amount, 0)), SUM(COALESCE(balance, 0)) INTO v_totalcount, v_total_cr, v_total_dr, v_totalbal FROM tmp_temp;
  DROP TABLE IF EXISTS tmp_temp;
  -- SET option (removed)
END;
$$;


--
-- Name: usp_all_ticket(character varying, character varying, character varying, character varying, character varying, integer, integer, integer, character varying, character varying, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_all_ticket(v_fromdate character varying DEFAULT ''::character varying, v_todate character varying DEFAULT ''::character varying, v_status character varying DEFAULT '0'::character varying, v_searchfield character varying DEFAULT '2'::character varying, v_searchvalue character varying DEFAULT ''::character varying, INOUT v_recordcount integer DEFAULT 0, v_startrowindex integer DEFAULT 1, v_maxrows integer DEFAULT 100, v_fromplid character varying DEFAULT ''::character varying, v_accounttype character varying DEFAULT '1'::character varying, v_did integer DEFAULT 0) RETURNS integer
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_minindex INT;
  v_maxindex INT;
  v_regno BIGINT;
  v_condition varchar(4000);
  v_queryresult varchar(4000);
  v_countquery varchar(4000);
  v_modestatus varchar(10);
  v_parmdefinition varchar(70);
BEGIN
  -- SET option (removed)
  v_condition := '';
  v_queryresult := '';
  v_countquery := '';
  v_modestatus := '0';
  v_minindex := (v_startrowindex - 1) * v_maxrows + 1;
  v_maxindex := v_startrowindex * v_maxrows;
  IF (v_accounttype = 1) THEN
  IF (v_did = 0) THEN
  v_queryresult := v_queryresult || (N'SELECT TOP(' || CAST((v_startrowindex * v_maxrows) AS VARCHAR(70)) || ')  ROW_NUMBER() OVER (ORDER BY TM.DATE DESC ) AS ROWNUMBER,  
  TM.MESSAGE,TM.TICKETNO,TM.CATEGORYNAME,          
  CONVERT(VARCHAR(100),TM.LASTUPDATE,100) AS LASTUPDATE,        
  CONVERT(VARCHAR(100),TM.DATE,106) AS DATE,TM.SUBJECT,TS.NAME AS STATUS,ISNULL(PL.FNAME,'''') AS NAME, PL.PHONE,      
  CONVERT(VARCHAR(100),TM.LASTUPDATE,100) AS FULLLASTUPDATE ,CONVERT(VARCHAR(100),TM.DATE,100)  AS FULLDATE    
  ,PL.USERNAME,TM.FROMPLID AS FROMPLID,TM.TMID AS TMID,TM.ACCOUNTTYPE,ISNULL(TM.FromRegNo,0) AS FromRegNo   
  INTO #TEMP FROM TBL_TICKETMASTER TM LEFT JOIN TBL_STATUSMASTER TS ON TS.ID = TM.STATUS  
  LEFT JOIN PORTAL_LOGIN PL ON PL.PLID=TM.FROMPLID WHERE TM.ACTIVE=0');
  ELSE
  v_queryresult := v_queryresult || (N'SELECT TOP(' || CAST((v_startrowindex * v_maxrows) AS VARCHAR(70)) || ')  ROW_NUMBER() OVER (ORDER BY TM.DATE DESC ) AS ROWNUMBER,  
  TM.MESSAGE,TM.TICKETNO,TM.CATEGORYNAME,          
  CONVERT(VARCHAR(100),TM.LASTUPDATE,100) AS LASTUPDATE,        
  CONVERT(VARCHAR(100),TM.DATE,106) AS DATE,TM.SUBJECT,TS.NAME AS STATUS,ISNULL(PL.FNAME,'''') AS NAME, PL.PHONE,      
  CONVERT(VARCHAR(100),TM.LASTUPDATE,100) AS FULLLASTUPDATE ,CONVERT(VARCHAR(100),TM.DATE,100)  AS FULLDATE    
  ,PL.USERNAME,TM.FROMPLID AS FROMPLID,TM.TMID AS TMID,TM.ACCOUNTTYPE,ISNULL(TM.FromRegNo,0) AS FromRegNo INTO #TEMP   
  FROM TBL_TICKETMASTER TM LEFT JOIN TBL_STATUSMASTER TS ON TS.ID = TM.STATUS  
  LEFT JOIN PORTAL_LOGIN PL ON PL.PLID=TM.FROMPLID WHERE TM.ACTIVE=0 AND PL.PLID   
  In(SELECT PLID FROM PORTAL_MASTER WHERE CID IN(SELECT CID FROM DISTRIBUTOR_MASTER WHERE PLID=' || CAST(v_did AS VARCHAR(5)) || '))');
  END IF;
  END IF;
  IF (v_accounttype = 2) THEN
  v_queryresult := v_queryresult || (N'SELECT TOP(' || CAST((v_startrowindex * v_maxrows) AS VARCHAR(70)) || ')  ROW_NUMBER() OVER (ORDER BY TM.DATE DESC ) AS ROWNUMBER,TM.MESSAGE,TM.TICKETNO,TM.CATEGORYNAME,          
  CONVERT(VARCHAR(100),TM.LASTUPDATE,100) AS LASTUPDATE,   
  CONVERT(VARCHAR(100),TM.DATE,106) AS DATE,TM.SUBJECT,TS.NAME AS STATUS,ISNULL(PL.FNAME,'''') AS NAME, PL.PHONE,      
  CONVERT(VARCHAR(100),TM.LASTUPDATE,100) AS FULLLASTUPDATE,CONVERT(VARCHAR(100),TM.DATE,100)  AS FULLDATE    
  ,PL.USERNAME,TM.FROMPLID AS FROMPLID,TM.TMID AS TMID,TM.ACCOUNTTYPE,ISNULL(TM.FromRegNo,0) AS FromRegNo,ISNULL(DM.COMPANYNAME,'''') AS COMPANYNAME  
   INTO #TEMP FROM TBL_TICKETMASTER TM LEFT JOIN TBL_STATUSMASTER TS ON TS.ID = TM.STATUS  
  LEFT JOIN TBL_CUSTOMERLOGIN PL ON PL.CLID=TM.FROMPLID   
  LEFT JOIN Distributor_MASTER DM ON PL.DID=DM.PMID  
  WHERE TM.ACTIVE=0');
  END IF;
  IF (v_accounttype = 3) THEN
  v_queryresult := v_queryresult || (N'SELECT TOP(' || CAST((v_startrowindex * v_maxrows) AS VARCHAR(70)) || ')    
  ROW_NUMBER() OVER (ORDER BY TM.DATE DESC ) AS ROWNUMBER,  
  TM.MESSAGE,TM.TICKETNO,TM.CATEGORYNAME,          
  CONVERT(VARCHAR(100),TM.LASTUPDATE,106) AS LASTUPDATE,        
  CONVERT(VARCHAR(100),TM.DATE,106) AS DATE,TM.SUBJECT,TS.NAME AS STATUS,ISNULL(PL.FNAME,'''') AS NAME, PL.PHONE,      
  CONVERT(VARCHAR(100),TM.LASTUPDATE,100) AS FULLLASTUPDATE ,CONVERT(VARCHAR(100),TM.DATE,100)  AS FULLDATE    
  ,PL.USERNAME,TM.FROMPLID AS FROMPLID,TM.TMID AS TMID,TM.ACCOUNTTYPE,ISNULL(TM.FromRegNo,0) AS FromRegNo INTO #TEMP   
  FROM TBL_TICKETMASTER TM LEFT JOIN TBL_STATUSMASTER TS ON TS.ID = TM.STATUS  
  INNER JOIN TBL_DISTRIBUTOR PL ON PL.DID=TM.FROMPLID WHERE TM.ACTIVE=0');
  END IF;
  v_parmdefinition := N'@RECORDCOUNT NVARCHAR(70) OUTPUT';
  v_countquery := N'SELECT @RECORDCOUNT= COUNT(1) from TBL_TICKETMASTER TM LEFT JOIN TBL_STATUSMASTER TS   
ON TS.ID = TM.STATUS,TBL_CUSTOMERLOGIN PL WHERE PL.CLID = TM.FROMPLID AND TM.ACTIVE=0';
  IF (v_fromdate <> '' OR v_todate <> '') THEN
  IF (v_fromdate <> '') THEN
  v_condition := v_condition || (' AND CONVERT(DATE,TM.DATE,103) >= CONVERT(Date,''' || v_fromdate || ''',103) ');
  END IF;
  IF (v_todate <> '') THEN
  v_condition := v_condition || (' AND CONVERT(DATE,TM.DATE,103) <= CONVERT(Date,''' || v_todate || ''',103) ');
  END IF;
  ELSE
  IF (v_fromdate <> '' AND v_todate <> '') THEN
  v_condition := v_condition || (' AND CONVERT(DATE,TM.DATE,103) BETWEEN CONVERT(DATE,''' || v_fromdate || ''',103) AND CONVERT(DATE,''' || v_todate || ''',103) ');
  END IF;
  END IF;
  IF (v_status <> '0') THEN
  v_condition := v_condition || (' AND TM.STATUS=' || v_status);
  END IF;
  IF (v_searchfield = '1' AND v_searchfield <> '') THEN
  IF (v_searchvalue <> '') THEN
  v_condition := v_condition || (' AND TM.TICKETNO=' || v_searchvalue);
  END IF;
  END IF;
  IF (v_searchfield = '2' AND v_searchfield <> '') THEN
  IF (v_searchvalue <> '') THEN
  v_condition := v_condition || (' AND PL.FNAME LIKE ''%' || v_searchvalue || '%'' ');
  END IF;
  END IF;
  IF (v_searchfield = '3' AND v_searchfield <> '') THEN
  IF (v_searchvalue <> '') THEN
  v_condition := v_condition || (' AND PL.USERNAME LIKE ''%' || v_searchvalue || '%'' ');
  END IF;
  END IF;
  IF (v_searchfield = '4' AND v_searchfield <> '') THEN
  IF (v_searchvalue <> '') THEN
  v_condition := v_condition || (' AND TM.CATEGORYNAME LIKE ''%' || v_searchvalue || '%'' ');
  END IF;
  END IF;
  IF (v_searchfield = '5' AND v_searchfield <> '') THEN
  IF (v_searchvalue <> '') THEN
  v_condition := v_condition || (' AND PL.PHONE LIKE ''%' || v_searchvalue || '%'' ');
  END IF;
  END IF;
  IF (v_fromplid <> '') THEN
  v_condition := v_condition || (' And TM.FROMPLID =' || v_fromplid);
  END IF;
  IF (v_accounttype <> '0') THEN
  v_condition := v_condition || (' AND TM.ACCOUNTTYPE =' || v_accounttype);
  END IF;
  v_queryresult := v_queryresult || v_condition || ' ;SELECT  *  FROM #TEMP WHERE ROWNUMBER BETWEEN   
' || CAST(v_minindex AS VARCHAR(70)) || ' AND ' || CAST(v_maxindex AS VARCHAR(70)) || '';
  v_countquery := v_countquery || v_condition;
  RAISE NOTICE '%', v_queryresult;
  EXECUTE v_queryresult;
  EXECUTE v_countquery;
  -- SET option (removed)
END;
$$;


--
-- Name: usp_all_ticket_reseller(character varying, character varying, character varying, character varying, character varying, integer, integer, integer, character varying, character varying, character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_all_ticket_reseller(v_fromdate character varying DEFAULT ''::character varying, v_todate character varying DEFAULT ''::character varying, v_status character varying DEFAULT '0'::character varying, v_searchfield character varying DEFAULT ''::character varying, v_searchvalue character varying DEFAULT ''::character varying, INOUT v_recordcount integer DEFAULT 0, v_startrowindex integer DEFAULT 1, v_maxrows integer DEFAULT 100, v_fromplid character varying DEFAULT '2'::character varying, v_accounttype character varying DEFAULT '2'::character varying, v_category character varying DEFAULT ''::character varying) RETURNS integer
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_minindex INT;
  v_maxindex INT;
  v_regno BIGINT;
  v_condition varchar(4000);
  v_queryresult varchar(4000);
  v_countquery varchar(4000);
  v_modestatus varchar(10);
  v_parmdefinition varchar(70);
BEGIN
  -- SET option (removed)
  v_condition := '';
  v_queryresult := '';
  v_countquery := '';
  v_modestatus := '0';
  v_minindex := (v_startrowindex - 1) * v_maxrows + 1;
  v_maxindex := v_startrowindex * v_maxrows;
  IF (v_accounttype = 1) THEN
  v_queryresult := v_queryresult || (N'SELECT TOP(' || CAST((v_startrowindex * v_maxrows) AS VARCHAR(70)) || ')  ROW_NUMBER() OVER (ORDER BY TM.DATE DESC ) AS ROWNUMBER,TM.MESSAGE,TM.TICKETNO,TM.CATEGORYNAME,        
		CONVERT(VARCHAR(100),TM.LASTUPDATE,106) AS LASTUPDATE,      
		CONVERT(VARCHAR(100),TM.DATE,106) AS DATE,TM.SUBJECT,TS.NAME AS STATUS,ISNULL(PL.FNAME,'''') AS NAME, PL.PHONE,    
		CONVERT(VARCHAR(100),TM.LASTUPDATE,100) AS FULLLASTUPDATE ,CONVERT(VARCHAR(100),TM.DATE,100)  AS FULLDATE  
		,PL.USERNAME,TM.FROMPLID AS FROMPLID,TM.TMID AS TMID,TM.ACCOUNTTYPE INTO #TEMP FROM TBL_TICKETMASTER TM LEFT JOIN TBL_STATUSMASTER TS ON TS.ID = TM.STATUS
		LEFT JOIN PORTAL_LOGIN PL ON PL.PLID=TM.FROMPLID inner join TBL_CUSTOMERLOGIN as Cl on cl.DID=Tm.fromplid WHERE   TM.ACTIVE=0');
  END IF;
  IF (v_accounttype = 2) THEN
  v_queryresult := v_queryresult || (N'SELECT TOP(' || CAST((v_startrowindex * v_maxrows) AS VARCHAR(70)) || ')  ROW_NUMBER() OVER (ORDER BY TM.DATE DESC ) AS ROWNUMBER,TM.MESSAGE,TM.TICKETNO,TM.CATEGORYNAME,        
		CONVERT(VARCHAR(100),TM.LASTUPDATE,106) AS LASTUPDATE,      
		CONVERT(VARCHAR(100),TM.DATE,106) AS DATE,TM.SUBJECT,TS.NAME AS STATUS,ISNULL(PL.FNAME,'''') AS NAME, PL.PHONE,    
		CONVERT(VARCHAR(100),TM.LASTUPDATE,100) AS FULLLASTUPDATE ,CONVERT(VARCHAR(100),TM.DATE,100)  AS FULLDATE  
		,PL.USERNAME,TM.FROMPLID AS FROMPLID,TM.TMID AS TMID,TM.ACCOUNTTYPE INTO #TEMP FROM TBL_TICKETMASTER TM LEFT JOIN TBL_STATUSMASTER TS ON TS.ID = TM.STATUS
		LEFT JOIN TBL_CUSTOMERLOGIN PL ON PL.CLID=TM.FROMPLID  WHERE    PL.DID=''' || v_fromplid || ''' and ACCOUNTTYPE=2  and    TM.ACTIVE=0');
  END IF;
  IF (v_accounttype = 3) THEN
  v_queryresult := v_queryresult || (N'SELECT TOP(' || CAST((v_startrowindex * v_maxrows) AS VARCHAR(70)) || ')  ROW_NUMBER() OVER (ORDER BY TM.DATE DESC ) AS ROWNUMBER,TM.MESSAGE,TM.TICKETNO,TM.CATEGORYNAME,        
		CONVERT(VARCHAR(100),TM.LASTUPDATE,106) AS LASTUPDATE,      
		CONVERT(VARCHAR(100),TM.DATE,106) AS DATE,TM.SUBJECT,TS.NAME AS STATUS,ISNULL(PL.FNAME,'''') AS NAME, PL.PHONE,    
		CONVERT(VARCHAR(100),TM.LASTUPDATE,100) AS FULLLASTUPDATE ,CONVERT(VARCHAR(100),TM.DATE,100)  AS FULLDATE  
		,PL.USERNAME,TM.FROMPLID AS FROMPLID,TM.TMID AS TMID,TM.ACCOUNTTYPE INTO #TEMP FROM TBL_TICKETMASTER TM LEFT JOIN TBL_STATUSMASTER TS ON TS.ID = TM.STATUS
		LEFT JOIN TBL_DISTRIBUTOR PL ON PL.DID=TM.FROMPLID inner join TBL_CUSTOMERLOGIN as Cl on cl.clid=Tm.fromplid  WHERE   TM.ACTIVE=0');
  END IF;
  v_parmdefinition := N'@RECORDCOUNT NVARCHAR(70) OUTPUT';
  v_countquery := N'SELECT @RECORDCOUNT= COUNT(1) from TBL_TICKETMASTER TM LEFT JOIN TBL_STATUSMASTER TS ON TS.ID = TM.STATUS,TBL_CUSTOMERLOGIN PL WHERE PL.CLID = TM.FROMPLID AND TM.ACTIVE=0';
  IF (v_status <> '0') THEN
  v_condition := v_condition || (' AND TM.STATUS=' || v_status);
  END IF;
  IF (v_searchfield = '1' AND v_searchfield <> '') THEN
  IF (v_searchvalue <> '') THEN
  v_condition := v_condition || (' AND TM.TICKETNO=' || v_searchvalue);
  END IF;
  END IF;
  IF (v_searchfield = '2' AND v_searchfield <> '') THEN
  IF (v_searchvalue <> '') THEN
  v_condition := v_condition || (' AND PL.FNAME LIKE ''%' || v_searchvalue || '%'' ');
  END IF;
  END IF;
  IF (v_searchfield = '3' AND v_searchfield <> '') THEN
  IF (v_searchvalue <> '') THEN
  v_condition := v_condition || (' AND PL.USERNAME LIKE ''%' || v_searchvalue || '%'' ');
  END IF;
  END IF;
  IF (v_searchfield = '4' AND v_searchfield <> '') THEN
  IF (v_searchvalue <> '') THEN
  v_condition := v_condition || (' AND TM.CATEGORYNAME LIKE ''%' || v_searchvalue || '%'' ');
  END IF;
  END IF;
  IF (v_searchfield = '5' AND v_searchfield <> '') THEN
  IF (v_searchvalue <> '') THEN
  v_condition := v_condition || (' AND PL.PHONE LIKE ''%' || v_searchvalue || '%'' ');
  END IF;
  END IF;
  v_queryresult := v_queryresult || v_condition || ' ;SELECT  *  FROM #TEMP WHERE ROWNUMBER BETWEEN ' || CAST(v_minindex AS VARCHAR(70)) || ' AND ' || CAST(v_maxindex AS VARCHAR(70)) || '';
  v_countquery := v_countquery || v_condition;
  RAISE NOTICE '%', v_queryresult;
  EXECUTE v_queryresult;
  EXECUTE v_countquery;
  -- SET option (removed)
END;
$$;


--
-- Name: usp_all_voucherlist(integer, integer, character varying, character varying, integer, text, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_all_voucherlist(v_startrowindex integer DEFAULT 1, v_maxrows integer DEFAULT 1000, v_searchfield character varying DEFAULT ''::character varying, v_searchvalue character varying DEFAULT ''::character varying, v_id integer DEFAULT NULL::integer, v_rolename text DEFAULT ''::text, v_totalcount integer DEFAULT 0) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_minindex INT;
  v_maxindex INT;
  v_query text;
BEGIN
  v_minindex := (v_startrowindex - 1) * v_maxrows + 1;
  v_maxindex := v_startrowindex * v_maxrows;
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp (ROWNUMBER INT,
vmid int,
CATEGORYNAME VARCHAR(100),
BRANDNAME VARCHAR(200),
 bytea text,
 MerchantName VARCHAR(200),
 OrderAmount VARCHAR(200)) ON COMMIT DROP;
  IF (v_id > 0) THEN
  v_query := 'INSERT INTO #TEMP SELECT ROW_NUMBER() OVER (ORDER BY  vm.VMID ASC),
  vm.VMID,
 ISNULL(vcm.CATEGORYNAME,'''') AS CATEGORYNAME,
 ISNULL(VM.BRANDNAME,'''') AS BRANDNAME,
 CASE WHEN VM.IMAGE<>'''' THEN VM.IMAGE ELSE '''' END AS IMAGE,
  ISNULL(vm.MerchantName,'''') AS MerchantName,
  case when sum(vom.orderamount) is null then 0 else sum(vom.orderamount) end as Total_Amount
  FROM TBL_VOUCHER_MASTER VM  
     left join TBL_VOUCHER_ORDER_MASTER as vom on vom.vmid=vm.vmid and vom.status = ''confirm''
   left join TBL_VOUCHER_CATEGORY_MASTER as vcm on vcm.vcmid=vm.vctid 
  where vm.VCTID=''' || CAST(v_id AS VARCHAR(10)) || '''
 	group by 
	vm.VMID,
	VM.BRANDNAME,
	vcm.CATEGORYNAME,
	VM.IMAGE,
	vm.MerchantName ';
  ELSE
  v_query := 'INSERT INTO #TEMP SELECT ROW_NUMBER() OVER (ORDER BY  vm.VMID ASC),
    vm.VMID,
 ISNULL(vcm.CATEGORYNAME,'''') AS CATEGORYNAME,
 ISNULL(VM.BRANDNAME,'''') AS BRANDNAME,
 CASE WHEN VM.IMAGE<>'''' THEN VM.IMAGE ELSE '''' END AS IMAGE,
  ISNULL(vm.MerchantName,'''') AS MerchantName,
 sum(Case when vom.status = ''confirm''  then vom.orderamount else 0 end) as Total_Amount
  FROM TBL_VOUCHER_MASTER VM 
Left join TBL_VOUCHER_CATEGORY_MASTER as vcm on vcm.VCMID=vm.VCTID 
Left join TBL_VOUCHER_ORDER_MASTER as vom on vom.VMID=vm.VMID 
 group by
  vm.VMID,
  vcm.CATEGORYNAME,
  VM.BRANDNAME,
  VM.IMAGE,
  vm.MerchantName ';
  END IF;
  v_query := v_query;
  IF (v_searchfield = 'BRANDNAME') THEN
  v_query := v_query || ' Having VM.BRANDNAME LIKE ''%' || v_searchvalue || '%'' ';
  END IF;
  IF (v_searchfield = 'MerchantName') THEN
  v_query := v_query || ' Having VM.MerchantName LIKE ''%' || v_searchvalue || '%'' ';
  END IF;
  IF (v_searchfield = 'CATEGORYNAME') THEN
  v_query := v_query || ' Having vcm.CATEGORYNAME LIKE ''%' || v_searchvalue || '%'' ';
  END IF;
  v_query := v_query || ' ORDER BY  VM.VMID ASC ';
  EXECUTE v_query;
  RETURN QUERY SELECT * FROM tmp_temp WHERE rownumber BETWEEN v_minindex AND v_maxindex;
  SELECT COUNT(rownumber) INTO v_totalcount FROM tmp_temp;
  DROP TABLE IF EXISTS tmp_temp;
  -- SET option (removed)
  RAISE NOTICE '%', (v_query);
END;
$$;


--
-- Name: usp_allcategorylist(character varying, character varying, character varying, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_allcategorylist(v_maincatname character varying DEFAULT 'PERSONAL CARE'::character varying, v_catname character varying DEFAULT 'MENS GROOMING'::character varying, v_prefix character varying DEFAULT 'Shaving Gels'::character varying, v_mode integer DEFAULT 2) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF (v_mode = 0) THEN
  RETURN QUERY SELECT maincatid, maincatname FROM tbl_main_category WHERE maincatname LIKE '%' || v_prefix || '%';
  END IF;
  IF (v_mode = 1) THEN
  RETURN QUERY SELECT catid, catname FROM tbl_main_category AS mc INNER JOIN tbl_category AS sbc ON sbc.maincatid = mc.maincatid WHERE maincatname = v_maincatname AND catname LIKE '%' || v_prefix || '%';
  END IF;
  IF (v_mode = 2) THEN
  RETURN QUERY SELECT subcatid, subcatname FROM tbl_main_category AS mc INNER JOIN tbl_category AS sbc ON sbc.maincatid = mc.maincatid INNER JOIN tbl_sub_category AS ssbc ON ssbc.maincatid = sbc.maincatid AND ssbc.catid = sbc.catid WHERE maincatname = v_maincatname AND sbc.catname = v_catname AND subcatname LIKE '%' || v_prefix || '%';
  END IF;
END;
$$;


--
-- Name: usp_allclubedreport(integer, integer, integer, character varying, character varying, character varying, character varying, integer, character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_allclubedreport(v_mode integer DEFAULT 0, v_startrowindex integer DEFAULT 1, v_maxrows integer DEFAULT 100, v_searchfield character varying DEFAULT ''::character varying, v_searchvalue character varying DEFAULT ''::character varying, v_fromdate character varying DEFAULT ''::character varying, v_todate character varying DEFAULT ''::character varying, v_totalcount integer DEFAULT 0, v_requestid character varying DEFAULT ''::character varying) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_minindex INT;
  v_maxindex INT;
  v_query text;
BEGIN
  v_minindex := (v_startrowindex - 1) * v_maxrows + 1;
  v_maxindex := v_startrowindex * v_maxrows;
  IF (v_mode = 0) THEN
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp (ROWNUMBER BIGINT GENERATED BY DEFAULT AS IDENTITY,
	USERNAME VARCHAR(100), 
	AMOUNT DECIMAL(18,2),	
	ACCOUNTNO VARCHAR(100),
	ACCOUNTHOLDERNAME VARCHAR(200), 
	BANKNAME VARCHAR(100),
	BRACNHNAME VARCHAR(100),        
	IFSCCODE VARCHAR(100),	
	GROUPNAME VARCHAR(100),	
	STATUS VARCHAR(100)) ON COMMIT DROP;
  v_query := 'INSERT INTO #TEMP SELECT PL.USERNAME,MWD.WITHDRAWAMOUNT,BAM.ACCOUNTNO,BAM.ACCOUNTHOLDERNAME,BAM.Bankname,
BAM.BRANCHNAME, BAM.IFSCCODE,MWD.CLUBGROUPNAME,MWD.STATUS 
FROM TBL_MERCHANT_WITHDRAWALS MWD 
LEFT JOIN BANK_ACCOUNTS_MERCHANT BAM ON  MWD.PLID=BAM.PLID
LEFT JOIN PORTAL_LOGIN PL ON MWD.PLID =PL.PLID 
WHERE  BAM.ACTIVE=1 AND BAM.ISAPROVE=1 and MWD.CLUBGROUPNAME<>'''' ';
  IF (v_searchfield = 'Username') THEN
  v_query := v_query || ' AND PL.USERNAME= ''' || v_searchvalue || ''' ';
  END IF;
  IF (v_searchfield = 'Accountholdername') THEN
  v_query := v_query || ' AND BAM.ACCOUNTHOLDERNAME= ''' || v_searchvalue || ''' ';
  END IF;
  IF (v_searchfield = 'Accountno') THEN
  v_query := v_query || ' AND BAM.ACCOUNTNO= ''' || v_searchvalue || ''' ';
  END IF;
  IF (v_searchfield = 'Ifscode') THEN
  v_query := v_query || ' AND BAM.IFSCCODE= ''' || v_searchvalue || ''' ';
  END IF;
  v_query := v_query || ' ORDER BY TMWDID DESC ';
  EXECUTE v_query;
  RETURN QUERY SELECT * FROM tmp_temp WHERE rownumber BETWEEN v_minindex AND v_maxindex;
  SELECT COUNT(rownumber) INTO v_totalcount FROM tmp_temp;
  DROP TABLE IF EXISTS tmp_temp;
  -- SET option (removed)
  END IF;
END;
$$;


--
-- Name: usp_allclubedreport_customer(integer, integer, integer, character varying, character varying, character varying, character varying, integer, character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_allclubedreport_customer(v_mode integer DEFAULT 0, v_startrowindex integer DEFAULT 1, v_maxrows integer DEFAULT 100, v_searchfield character varying DEFAULT ''::character varying, v_searchvalue character varying DEFAULT ''::character varying, v_fromdate character varying DEFAULT ''::character varying, v_todate character varying DEFAULT ''::character varying, v_totalcount integer DEFAULT 0, v_requestid character varying DEFAULT ''::character varying) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_minindex INT;
  v_maxindex INT;
  v_query text;
BEGIN
  v_minindex := (v_startrowindex - 1) * v_maxrows + 1;
  v_maxindex := v_startrowindex * v_maxrows;
  IF (v_mode = 0) THEN
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp (ROWNUMBER BIGINT GENERATED BY DEFAULT AS IDENTITY,
	USERNAME VARCHAR(100), 
	AMOUNT DECIMAL(18,2),	
	ACCOUNTNO VARCHAR(100),
	ACCOUNTHOLDERNAME VARCHAR(200), 
	BANKNAME VARCHAR(100),
	BRACNHNAME VARCHAR(100),        
	IFSCCODE VARCHAR(100),	
	GROUPNAME VARCHAR(100),	
	STATUS VARCHAR(100)) ON COMMIT DROP;
  v_query := 'INSERT INTO #TEMP SELECT PL.USERNAME,MWD.WITHDRAWALAMOUNT,BAM.ACCOUNTNO,BAM.ACCOUNTHOLDERNAME,BAM.BANKNAME,
BAM.BRANCHNAME, BAM.IFSCCODE,MWD.CLUBGROUPNAME,MWD.STATUS 
FROM TBL_CUSTOMER_TRANSFERTOBANK MWD 
LEFT JOIN TBL_CUSTOMER_BANK_ACCOUNTS BAM ON  MWD.CLID=BAM.CLID
LEFT JOIN TBL_CUSTOMERLOGIN PL ON MWD.CLID =PL.CLID 
WHERE  BAM.ACTIVE=1  AND MWD.CLUBGROUPNAME<>'''' ';
  IF (v_searchfield = 'USERNAME') THEN
  v_query := v_query || ' AND PL.USERNAME= ''' || v_searchvalue || ''' ';
  END IF;
  IF (v_searchfield = 'ACCOUNTHOLDERNAME') THEN
  v_query := v_query || ' AND BAM.ACCOUNTHOLDERNAME= ''' || v_searchvalue || ''' ';
  END IF;
  IF (v_searchfield = 'ACCOUNTNO') THEN
  v_query := v_query || ' AND BAM.ACCOUNTNO= ''' || v_searchvalue || ''' ';
  END IF;
  IF (v_searchfield = 'IFSCODE') THEN
  v_query := v_query || ' AND BAM.IFSCCODE= ''' || v_searchvalue || ''' ';
  END IF;
  v_query := v_query || ' ORDER BY TCTTB DESC ';
  EXECUTE v_query;
  RETURN QUERY SELECT * FROM tmp_temp WHERE rownumber BETWEEN v_minindex AND v_maxindex;
  SELECT COUNT(rownumber) INTO v_totalcount FROM tmp_temp;
  DROP TABLE IF EXISTS tmp_temp;
  -- SET option (removed)
  END IF;
END;
$$;


--
-- Name: usp_allclubedreport_reseller(integer, integer, integer, character varying, character varying, character varying, character varying, integer, character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_allclubedreport_reseller(v_mode integer DEFAULT 0, v_startrowindex integer DEFAULT 1, v_maxrows integer DEFAULT 100, v_searchfield character varying DEFAULT ''::character varying, v_searchvalue character varying DEFAULT ''::character varying, v_fromdate character varying DEFAULT ''::character varying, v_todate character varying DEFAULT ''::character varying, v_totalcount integer DEFAULT 0, v_requestid character varying DEFAULT ''::character varying) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_minindex INT;
  v_maxindex INT;
  v_query text;
  v_tempdid text;
  v_index INT;
  v_slice text;
  v_totalpayable DECIMAL(18,2);
BEGIN
  v_query := '';
  v_tempdid := '';
  v_index := 1;
  v_slice := '';
  v_totalpayable := 0;
  v_minindex := (v_startrowindex - 1) * v_maxrows + 1;
  v_maxindex := v_startrowindex * v_maxrows;
  IF (v_mode = 0) THEN
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp (ROWNUMBER BIGINT GENERATED BY DEFAULT AS IDENTITY,
	DID INT,
	USERNAME VARCHAR(100), 
	AMOUNT DECIMAL(18,2),	
	ACCOUNTNO VARCHAR(100),
	ACCOUNTHOLDERNAME VARCHAR(200), 
	BANKNAME VARCHAR(100),
	BRACNHNAME VARCHAR(100),        
	IFSCCODE VARCHAR(100),	
	Date VARCHAR(100),	
	STATUS int) ON COMMIT DROP;
  v_query := 'INSERT INTO #TEMP SELECT DISTINCT RCW.DID,PL.USERNAME,0,BAD.ACCOUNTNO,BAD.ACCOUNTHOLDERNAME,
BAD.BANKNAME,BAD.BRANCHNAME, BAD.IFSCCODE,RCW.PROCEESSDATE,RCW.PAIDSTATUS 
FROM TBL_RESELLER_TRANSFERTOBANK_REQUEST RCW 
LEFT JOIN BANK_ACCOUNTS_DISTRIBUTOR BAD ON RCW.DID=BAD.DID
LEFT JOIN TBL_DISTRIBUTOR PL ON RCW.DID=PL.DID 
WHERE  BAD.ACTIVE=1 AND BAD.ISAPROVE=1 AND  RCW.PAIDSTATUS=2';
  IF (v_searchfield = 'USERNAME') THEN
  v_query := v_query || ' AND PL.USERNAME= ''' || v_searchvalue || ''' ';
  END IF;
  IF (v_searchfield = 'ACCOUNTHOLDERNAME') THEN
  v_query := v_query || ' AND BAD.ACCOUNTHOLDERNAME= ''' || v_searchvalue || ''' ';
  END IF;
  IF (v_searchfield = 'ACCOUNTNO') THEN
  v_query := v_query || ' AND BAD.ACCOUNTNO= ''' || v_searchvalue || ''' ';
  END IF;
  IF (v_searchfield = 'IFSCODE') THEN
  v_query := v_query || ' AND BAD.IFSCCODE= ''' || v_searchvalue || ''' ';
  END IF;
  EXECUTE v_query;
  SELECT COALESCE(v_tempdid || ', ', '') || CAST(did AS VARCHAR) INTO v_tempdid FROM (SELECT DISTINCT did FROM tmp_temp) AS t;
  SELECT SUBSTRING(v_tempdid FROM 2 FOR LENGTH(CAST(v_tempdid AS TEXT))) INTO v_tempdid;
  v_index := 1;
  WHILE (v_index <> 0) LOOP
  SELECT POSITION(',' IN v_tempdid) INTO v_index;
  IF (v_index <> 0) THEN
  SELECT LEFT(CAST(v_tempdid AS TEXT), v_index - 1) INTO v_slice;
  ELSE
  SELECT v_tempdid INTO v_slice;
  END IF;
  v_totalpayable := 0;
  IF (v_slice <> '') THEN
  SELECT COALESCE(SUM(balance), 0) INTO v_totalpayable FROM tbl_reseller_commissionwalletstatement WHERE did = v_slice AND paid_status = 'UNPAID';
  UPDATE tmp_temp SET amount = v_totalpayable WHERE did = v_slice;
  END IF;
  SELECT RIGHT(CAST(v_tempdid AS TEXT), LENGTH(CAST(v_tempdid AS TEXT)) - v_index) INTO v_tempdid;
  IF LENGTH(CAST(v_tempdid AS TEXT)) = 0 THEN
  EXIT;
  END IF;
  END LOOP;
  RETURN QUERY SELECT * FROM tmp_temp WHERE rownumber BETWEEN v_minindex AND v_maxindex;
  SELECT COUNT(rownumber) INTO v_totalcount FROM tmp_temp;
  DROP TABLE IF EXISTS tmp_temp;
  -- SET option (removed)
  END IF;
END;
$$;


--
-- Name: usp_allmemberlist(integer, integer, character varying, character varying, character varying, character varying, character varying, character varying, character varying, character varying, text, text, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_allmemberlist(v_startrowindex integer DEFAULT 1, v_maxrows integer DEFAULT 10, v_registerfromdate character varying DEFAULT ''::character varying, v_registertodate character varying DEFAULT ''::character varying, v_purchasepackagefromdate character varying DEFAULT ''::character varying, v_purchasepackagetodate character varying DEFAULT ''::character varying, v_paymentfromdate character varying DEFAULT ''::character varying, v_paymenttodate character varying DEFAULT ''::character varying, v_paymentstatusid character varying DEFAULT ''::character varying, v_memberstatus character varying DEFAULT ''::character varying, v_memberid text DEFAULT ''::text, v_membername text DEFAULT ''::text, v_totalcount integer DEFAULT 0) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_query text;
  v_minindex INT;
  v_maxindex INT;
  v_queryresult text;
BEGIN
  v_query := '';
  v_queryresult := '';
  v_minindex := (v_startrowindex - 1) * v_maxrows + 1;
  v_maxindex := v_startrowindex * v_maxrows;
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp (ROWNUMBERS BIGINT GENERATED BY DEFAULT AS IDENTITY,
TIDID BIGINT,
REGNO BIGINT,
LOGINID VARCHAR(50),
MEMBERNAME VARCHAR(250),
PurchaseDate VARCHAR(250),
PackageName VARCHAR(250),
Amount VARCHAR(250),
MemberSTATUS VARCHAR(250),
PayMentSTATUS VARCHAR(250),
PayId Int,
Member_Unique_Id VARCHAR(250),
userName varchar(200),
MOBILE varchar(50)) ON COMMIT DROP;
  v_query := 'Insert Into #TEMP Select ISNULL(TID.TIDID,0)As TIDID,MM.RegNo,MM.LoginId,CONCAT(PL.FNAME,'' '',PL.Lname)As Name,
(Case When ISNULL(Convert(Varchar(11),Date,106),'''')='''' Then ''Not Purchased'' Else Convert(Varchar(11),Date,106) End)As 
PurchaseDate,ISNULL(KM.Title,''N/A'')As Title,ISNULL(Cast(TID.Price As text),''0'')As Price,
(Case When MM.Status=0 Then ''Pending'' Else ''Active'' End) As MemberStatus,
(Case When ISNULL(TID.Status,2)=0 Then ''Pending'' When 
ISNULL(TID.Status,2)=1 Then ''Confirmed'' Else ''Not Submitted'' End)As PaymentStatus,
ISNULL(TID.PayId,0),Member_Unique_Id,PL.userName,(''+'' + C.ISDcode + ''-'' + MM.MOBILE) as MOBILE
From Member_Master MM Left Join PORTAL_LOGIN PL On PL.PLID = MM.PLID 
LEFT JOIN Tbl_IncomeDistribution TID
LEFT JOIN Kit_Master KM ON KM.Kid=TID.KID
ON MM.RegNo=TID.RegNo INNER JOIN COUNTRY C ON MM.CID = C.CID Where MM.Regno<>0';
  IF (v_registerfromdate <> '' AND v_registertodate <> '') THEN
  v_query := v_query || ' And Convert(Date,Regdate,105)>=Convert(Date,''' || v_registerfromdate || ''',105) AND Convert(Date,Regdate,105)<=Convert(Date,''' || v_registertodate || ''',105)';
  ELSE
  IF (v_registerfromdate <> '') THEN
  v_query := v_query || ' AND Convert(Date,Regdate, 105)=Convert(Date,''' || v_registerfromdate || ''', 105)';
  ELSE
  IF (v_registertodate <> '') THEN
  v_query := v_query || ' AND Convert(Date,Regdate, 105)=Convert(Date,''' || v_registertodate || ''', 105)';
  END IF;
  END IF;
  END IF;
  IF (v_purchasepackagefromdate <> '' AND v_purchasepackagetodate <> '') THEN
  v_query := v_query || ' AND Convert(Date,TID.Date,105)>=Convert(Date,''' || v_purchasepackagefromdate || ''',105) AND Convert(Date,TID.Date,105)<=Convert(Date,''' || v_purchasepackagetodate || ''',105)';
  ELSE
  IF (v_purchasepackagefromdate <> '') THEN
  v_query := v_query || ' AND Convert(Date,TID.Date, 105)=Convert(Date,''' || v_purchasepackagefromdate || ''', 105)';
  ELSE
  IF (v_purchasepackagetodate <> '') THEN
  v_query := v_query || ' AND Convert(Date,TID.Date, 105)=Convert(Date,''' || v_purchasepackagetodate || ''', 105)';
  END IF;
  END IF;
  END IF;
  IF (v_paymentfromdate <> '' AND v_paymenttodate <> '') THEN
  v_query := v_query || ' AND Convert(Date,ChallanSubmittedDate,105)>=Convert(Date,''' || v_paymentfromdate || ''',105) AND Convert(Date,ChallanSubmittedDate,105)<=Convert(Date,''' || v_paymenttodate || ''',105)';
  ELSE
  IF (v_paymentfromdate <> '') THEN
  v_query := v_query || ' AND Convert(Date,ChallanSubmittedDate, 105)=Convert(Date,''' || v_paymentfromdate || ''', 105)';
  ELSE
  IF (v_paymenttodate <> '') THEN
  v_query := v_query || ' AND Convert(Date,ChallanSubmittedDate, 105)=Convert(Date,''' || v_paymenttodate || ''', 105)';
  END IF;
  END IF;
  END IF;
  IF (v_paymentstatusid <> '') THEN
  v_query := v_query || ' AND ISNULL(TID.Status,2)=' || CAST(v_paymentstatusid AS text) || '';
  v_query := v_query || '';
  END IF;
  IF (v_memberstatus <> '') THEN
  v_query := v_query || ' AND MM.Status=' || CAST(v_memberstatus AS text) || '';
  END IF;
  IF (v_memberid <> '') THEN
  v_query := v_query || ' AND PL.userName Like ''%' || v_memberid || '%''';
  END IF;
  IF (v_membername <> '') THEN
  v_query := v_query || ' AND CONCAT(PL.FNAME,'' '',PL.Lname) Like ''%' || v_membername || '%''';
  END IF;
  EXECUTE v_query;
  RETURN QUERY SELECT * FROM tmp_temp WHERE rownumbers BETWEEN v_minindex AND v_maxindex;
  SELECT COUNT(tidid) INTO v_totalcount FROM tmp_temp;
END;
$$;


--
-- Name: usp_allmerchantdetails(integer, integer, character varying, character varying, character varying, character varying, integer, integer, numeric, integer, integer, bigint, bigint, integer, character varying, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_allmerchantdetails(v_startrowindex integer DEFAULT 1, v_maxrows integer DEFAULT 100, v_searchfield character varying DEFAULT ''::character varying, v_searchvalue character varying DEFAULT ''::character varying, v_fromdate character varying DEFAULT ''::character varying, v_todate character varying DEFAULT ''::character varying, v_did integer DEFAULT 21, v_totalcount integer DEFAULT 0, v_totalwallet numeric DEFAULT 0, v_balance integer DEFAULT 0, v_orderbycrdeit integer DEFAULT 0, v_minamount bigint DEFAULT 0, v_maxamount bigint DEFAULT 0, v_searchkyc integer DEFAULT 0, v_searchbusinessinfo character varying DEFAULT ''::character varying, v_searchbusinesstype integer DEFAULT 0) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_minindex INT;
  v_maxindex INT;
  v_query text;
  v_tempclid text;
  v_index INT;
  v_slice text;
  v_totalpayable DECIMAL(18,2);
BEGIN
  v_tempclid := '';
  v_index := 1;
  v_slice := '';
  v_totalpayable := 0;
  v_minindex := (v_startrowindex - 1) * v_maxrows + 1;
  v_maxindex := v_startrowindex * v_maxrows;
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp (ROWNUMBER INT GENERATED BY DEFAULT AS IDENTITY,          
    DID  BIGINT,  
 NAME VARCHAR(100),               
    EMAILID  VARCHAR(100),                 
    PHONE VARCHAR(100),  
 BusinessInfo Varchar(100),  
 KycStatusText Varchar(100)) ON COMMIT DROP;
  v_query := 'INSERT INTO #TEMP SELECT PL.DID,ISNULL(PM.COMPANYNAME,ISNULL(PL.FNAME,'''')) AS NAME,PL.EMAILID,(CASE WHEN PL.PHONE='''' THEN ''Not Updated'' END)As PHONE,  
  (CASE WHEN PL.PMID=0 THEN ''Updated'' Else ''Not Updated'' END)As BusinessInfo,PL.KycStatusText FROM PORTAL_LOGIN AS  PL  
  LEFT JOIN PORTAL_MASTER PM ON PM.PLID=PL.PLID  
  WHERE PL.PLID>0';
  IF (v_searchbusinesstype > 0) THEN
  v_query := v_query || ' AND PM.BUSINESSTYPE=' || CAST(v_searchbusinesstype AS VARCHAR(100)) || ' ';
  END IF;
  IF (v_searchkyc >= 1) THEN
  v_query := v_query || ' AND PL.KYCStatusText=(Case When ' || CAST(v_searchkyc AS VARCHAR(100)) || '=1 THEN ''Approved''   
  When ' || CAST(v_searchkyc AS VARCHAR(100)) || '=2 THEN ''Rejected'' ELSE ('''')  END)';
  END IF;
  IF (v_searchkyc = 0) THEN
  v_query := v_query || ' AND (PL.KYCStatusText=''Pending'' OR PL.KYCStatusText='''')';
  END IF;
  IF (v_searchbusinessinfo = 'Updated') THEN
  v_query := v_query || ' AND PL.PMID<>0';
  END IF;
  IF (v_searchbusinessinfo = 'Not Updated') THEN
  v_query := v_query || ' AND PL.PMID=0';
  END IF;
  IF ((v_fromdate <> '') AND (v_todate = '')) THEN
  v_query := v_query || ' AND CONVERT(VARCHAR(20), D.REGISTRATIONDATE, 106) BETWEEN  CONVERT(VARCHAR(20), ''' || v_fromdate || ''', 106) AND  CONVERT(VARCHAR(20), DBO.FUN_GETCURRENTDATE(), 106)';
  END IF;
  IF ((v_fromdate = '') AND (v_todate <> '')) THEN
  v_query := v_query || 'AND CONVERT(VARCHAR(20), D.REGISTRATIONDATE, 106) BETWEEN  CONVERT(VARCHAR(20), ''' || v_todate || ''', 106) AND  CONVERT(VARCHAR(20), DBO.FUN_GETCURRENTDATE(), 106)';
  END IF;
  IF ((v_fromdate <> '') AND (v_todate <> '')) THEN
  v_query := v_query || 'AND CONVERT(VARCHAR(20), D.REGISTRATIONDATE, 106) BETWEEN CONVERT(VARCHAR(20), ''' || v_fromdate || ''', 106) AND  CONVERT(VARCHAR(20), ''' || v_todate || ''', 106)';
  END IF;
  IF (v_did > 0) THEN
  v_query := v_query || (' AND PL.PLID In(SELECT PLID FROM PORTAL_MASTER WHERE CID IN(SELECT CID FROM DISTRIBUTOR_MASTER WHERE PLID=' || CAST(v_did AS VARCHAR(5)) || '))');
  END IF;
  IF (v_searchfield = 'LOGINID') THEN
  v_query := v_query || ' AND PL.LOGINID= ''' || v_searchvalue || ''' ';
  END IF;
  IF (v_searchfield = 'NAME') THEN
  v_query := v_query || ' AND (PL.FNAME+'' ''+PL.LNAME) = ''' || v_searchvalue || ''' ';
  END IF;
  IF (v_searchfield = 'EMAILID') THEN
  v_query := v_query || ' AND PL.EMAILID = ''' || v_searchvalue || ''' ';
  END IF;
  IF (v_searchfield = 'PHONE') THEN
  v_query := v_query || ' AND PL.PHONE= ''' || v_searchvalue || ''' ';
  END IF;
  EXECUTE v_query;
  RAISE NOTICE '%', v_query;
  RETURN QUERY SELECT * FROM tmp_temp WHERE rownumber BETWEEN v_minindex AND v_maxindex;
  SELECT COUNT(rownumber) INTO v_totalcount FROM tmp_temp;
  DROP TABLE IF EXISTS tmp_temp;
  -- SET option (removed)
END;
$$;


