--
-- Name: usp_allrejectlist_merchant(integer, integer, integer, character varying, character varying, character varying, character varying, integer, character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_allrejectlist_merchant(v_mode integer DEFAULT 0, v_startrowindex integer DEFAULT 1, v_maxrows integer DEFAULT 100, v_searchfield character varying DEFAULT ''::character varying, v_searchvalue character varying DEFAULT ''::character varying, v_fromdate character varying DEFAULT ''::character varying, v_todate character varying DEFAULT ''::character varying, v_totalcount integer DEFAULT 0, v_requestid character varying DEFAULT ''::character varying) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_minindex INT;
  v_maxindex INT;
  v_query text;
BEGIN
  v_minindex := (v_startrowindex - 1) * v_maxrows + 1;
  v_maxindex := v_startrowindex * v_maxrows;
  IF (v_mode = 0) THEN
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp (ROWNUMBER BIGINT GENERATED BY DEFAULT AS IDENTITY,
	USERNAME VARCHAR(100), 
	AMOUNT DECIMAL(18,2),	
	ACCOUNTNO VARCHAR(100),
	ACCOUNTHOLDERNAME VARCHAR(200), 
	BANKNAME VARCHAR(100),
	BRACNHNAME VARCHAR(100),        
	IFSCCODE VARCHAR(100),	
	STATUS VARCHAR(100)	,
	Date varchar(100)) ON COMMIT DROP;
  v_query := 'INSERT INTO #TEMP SELECT PM.COMPANYNAME,MWD.WITHDRAWAMOUNT,BAM.ACCOUNTNO,BAM.ACCOUNTHOLDERNAME,BAM.BANKNAME,
BAM.BRANCHNAME, BAM.IFSCCODE,MWD.STATUS,isnull(MWD.DATE,'''')
FROM TBL_MERCHANT_WITHDRAWALS MWD 
LEFT JOIN BANK_ACCOUNTS_MERCHANT BAM ON  MWD.PLID=BAM.PLID
LEFT JOIN PORTAL_LOGIN PL ON MWD.PLID =PL.PLID 
LEFT JOIN PORTAL_MASTER PM ON MWD.PLID =PM.PLID 
WHERE  BAM.ACTIVE=1  AND MWD.STATUS=2 ';
  IF (v_searchfield = 'USERNAME') THEN
  v_query := v_query || ' AND PL.USERNAME= ''' || v_searchvalue || ''' ';
  END IF;
  IF (v_searchfield = 'ACCOUNTHOLDERNAME') THEN
  v_query := v_query || ' AND BAM.ACCOUNTHOLDERNAME= ''' || v_searchvalue || ''' ';
  END IF;
  IF (v_searchfield = 'ACCOUNTNO') THEN
  v_query := v_query || ' AND BAM.ACCOUNTNO= ''' || v_searchvalue || ''' ';
  END IF;
  IF (v_searchfield = 'IFSCODE') THEN
  v_query := v_query || ' AND BAM.IFSCCODE= ''' || v_searchvalue || ''' ';
  END IF;
  v_query := v_query || ' ORDER BY TMWDID DESC ';
  EXECUTE v_query;
  RETURN QUERY SELECT * FROM tmp_temp WHERE rownumber BETWEEN v_minindex AND v_maxindex;
  SELECT COUNT(rownumber) INTO v_totalcount FROM tmp_temp;
  DROP TABLE IF EXISTS tmp_temp;
  -- SET option (removed)
  END IF;
END;
$$;


--
-- Name: usp_allsubscriptionmaster(numeric, integer, text, text, integer, text, text, text, text, text, text, text, text, text, text, text, integer, text, numeric, text, character varying, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_allsubscriptionmaster(v_totalpayableamount numeric DEFAULT 0, v_paymentmode integer DEFAULT 0, v_modename text DEFAULT ''::text, v_commentorremark text DEFAULT ''::text, v_regno integer DEFAULT 0, v_imagename text DEFAULT ''::text, v_bankname text DEFAULT ''::text, v_branchname text DEFAULT ''::text, v_referencedate text DEFAULT ''::text, v_referencenumber text DEFAULT ''::text, v_walletid text DEFAULT ''::text, v_transactionpassword text DEFAULT ''::text, v_googleauthenticationcode text DEFAULT ''::text, v_allpackageid text DEFAULT ''::text, v_allpackagetype text DEFAULT ''::text, v_allpackageamount text DEFAULT ''::text, v_plid integer DEFAULT 0, v_allpackagename text DEFAULT ''::text, v_processingfee numeric DEFAULT 0.00, INOUT v_intresult text DEFAULT ''::text, INOUT v_tranids character varying DEFAULT ''::character varying, v_ispaymentgateway integer DEFAULT 1) RETURNS record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_transaction_id VARCHAR(10);
  v_lower BIGINT;
  v_upper BIGINT;
  v_isstop Int;
  v_countformultiplepurchase BigInt;
  v_service_tax_per DECIMAL(18,8);
  v_service_tax_amt DECIMAL(18,8);
  v_with_out_tax_amount DECIMAL(18,8);
BEGIN
  -- BEGIN TRAN (removed)
  BEGIN
  v_transaction_id := '';
  v_isstop := 0;
  WHILE (v_isstop = 0) LOOP
  SELECT CAST(RANDOM() * 9999999999 AS DECIMAL(10, 0)) INTO v_transaction_id;
  IF EXISTS(SELECT 1 FROM tbl_allsubscriptionmaster WHERE transaction_id = v_transaction_id AND status = 1) THEN
  v_isstop := 0;
  ELSE
  v_isstop := 1;
  END IF;
  END LOOP;
  IF (v_ispaymentgateway = 1) THEN
  v_countformultiplepurchase := 0;
  SELECT COUNT(1) INTO v_countformultiplepurchase FROM tbl_allsubscriptionmaster WHERE '~' || allpackagetype || '~' LIKE '%~1~%' AND '~' || allpackageid || '~' LIKE '%~' || CAST(v_allpackageid AS text) || '~%' AND plid = v_plid AND COALESCE(isapproved, 0) <> 2;
  IF (v_countformultiplepurchase > 0) THEN
  v_intresult := 'AlreadyPurchased';
  -- ROLLBACK (removed)
  RETURN;
  END IF;
  INSERT INTO tbl_paymenygatewaypackagepurchaselog (totalpayableamount, paymentmode, modename, commentorremark, regno, imagename, bankname, branchname, referencedate, referencenumber, walletid, transactionpassword, googleauthenticationcode, allpackageid, allpackagetype, allpackageamount, plid, allpackagename, processingfee, intresult, tranids, ispaymentgateway) VALUES (v_totalpayableamount, v_paymentmode, v_modename, v_commentorremark, v_regno, v_imagename, v_bankname, v_branchname, v_referencedate, v_referencenumber, v_walletid, v_transactionpassword, v_googleauthenticationcode, v_allpackageid, v_allpackagetype, v_allpackageamount, v_plid, v_allpackagename, v_processingfee, v_intresult, v_tranids, v_ispaymentgateway);
  IF (0 = 0) THEN
  v_intresult := 'PayYouMoney';
  v_tranids := v_transaction_id;
  -- COMMIT (removed)
  RETURN;
  END IF;
  END IF;
  IF (v_referencenumber <> '') THEN
  IF EXISTS(SELECT 1 FROM tbl_allsubscriptionmaster WHERE referencenumber = v_referencenumber AND status = 1 AND isapproved <> 2) THEN
  v_intresult := 'Reference Number Already Used.';
  -- ROLLBACK (removed)
  RETURN;
  END IF;
  END IF;
  v_service_tax_per := 0.00;
  v_service_tax_amt := 0.00;
  v_with_out_tax_amount := 0.00;
  v_with_out_tax_amount := v_totalpayableamount;
  SELECT limits INTO v_service_tax_per FROM dbo.settings WHERE caption = 'IsTaxApplicableOnPackagePrice' AND active = 1;
  v_totalpayableamount := 0;
  v_service_tax_amt := COALESCE(v_with_out_tax_amount, 0) * COALESCE(v_service_tax_per, 0);
  IF (v_service_tax_amt > 0) THEN
  v_service_tax_amt := v_service_tax_amt / 100;
  ELSE
  v_service_tax_amt := 0;
  END IF;
  v_totalpayableamount := v_with_out_tax_amount + v_service_tax_amt;
  INSERT INTO tbl_allsubscriptionmaster (totalpayableamount, paymentmode, modename, commentorremark, regno, imagename, bankname, branchname, referencedate, referencenumber, walletid, transactionpassword, googleauthenticationcode, allpackageid, allpackagetype, allpackageamount, puchasedate, isactive, status, plid, allpackagename, transaction_id, service_tax_per, service_tax, with_out_tax_amount, invoice_no, processingfee) VALUES (v_totalpayableamount, v_paymentmode, (CASE WHEN v_paymentmode = 1 THEN 'Credit Card' WHEN v_paymentmode = 2 THEN 'Debit Card' WHEN v_paymentmode = 3 THEN 'NEFT' WHEN v_paymentmode = 4 THEN 'Atm Transfer' WHEN v_paymentmode = 5 THEN 'POS Machine' WHEN v_paymentmode = 6 THEN 'IMPS' WHEN v_paymentmode = 7 THEN 'Cheque' WHEN v_paymentmode = 8 THEN 'DD' WHEN v_paymentmode = 11 THEN 'BTC' ELSE 'N/A' END), v_commentorremark, v_regno, v_imagename, v_bankname, v_branchname, v_referencedate, v_referencenumber, v_walletid, v_transactionpassword, v_googleauthenticationcode, v_allpackageid, v_allpackagetype, v_allpackageamount, dbo.FUN_GETCURRENTDATE(), 1, 1, v_plid, v_allpackagename, v_transaction_id, COALESCE(v_service_tax_per, 0.00), COALESCE(v_service_tax_amt, 0), COALESCE(v_with_out_tax_amount, 0), '', v_processingfee);
  IF (0 = 0) THEN
  v_intresult := 'Thanks for upgrading your account. As soon as your payment get confirmed your account will be activated. Please note your payment Order ID: ' || v_transaction_id;
  v_tranids := v_transaction_id;
  -- COMMIT (removed)
  RETURN;
  ELSE
  v_intresult := 'Some Error Occur While Subscribing.';
  -- ROLLBACK (removed)
  RETURN;
  END IF;
  EXCEPTION WHEN OTHERS THEN
  v_intresult := 'Some Error Occur While Subscribing.';
  -- ROLLBACK (removed)
  END;
  -- COMMIT (removed)
END;
$$;


--
-- Name: usp_allticket(character varying, character varying, character varying, character varying, character varying, integer, integer, integer, character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_allticket(v_fromdate character varying DEFAULT ''::character varying, v_todate character varying DEFAULT ''::character varying, v_status character varying DEFAULT '0'::character varying, v_searchfield character varying DEFAULT ''::character varying, v_searchvalue character varying DEFAULT ''::character varying, INOUT v_recordcount integer DEFAULT 0, v_startrowindex integer DEFAULT 1, v_maxrows integer DEFAULT 100, v_fromplid character varying DEFAULT ''::character varying) RETURNS integer
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_minindex INT;
  v_maxindex INT;
  v_regno BIGINT;
  v_condition varchar(4000);
  v_queryresult varchar(4000);
  v_countquery varchar(4000);
  v_modestatus varchar(10);
  v_parmdefinition varchar(70);
BEGIN
  -- SET option (removed)
  v_condition := '';
  v_queryresult := '';
  v_countquery := '';
  v_modestatus := '0';
  v_minindex := (v_startrowindex - 1) * v_maxrows + 1;
  v_maxindex := v_startrowindex * v_maxrows;
  v_queryresult := v_queryresult || (N'SELECT TOP(' || CAST((v_startrowindex * v_maxrows) AS VARCHAR(70)) || ')  ROW_NUMBER() OVER (ORDER BY TM.DATE DESC ) AS ROWNUMBER,TM.MESSAGE,TM.TICKETNO,TM.CATEGORYNAME,        
		CONVERT(VARCHAR(100),TM.LASTUPDATE,106) AS LASTUPDATE,      
		CONVERT(VARCHAR(100),TM.DATE,106) AS DATE,TM.SUBJECT,TS.NAME AS STATUS,ISNULL(PL.FNAME,'''') AS NAME, PL.PHONE,    
		CONVERT(VARCHAR(100),TM.LASTUPDATE,100) AS FULLLASTUPDATE ,CONVERT(VARCHAR(100),TM.DATE,100)  AS FULLDATE  
		,PL.USERNAME,TM.FROMPLID AS FROMPLID,TM.TMID AS TMID INTO #TEMP FROM TBL_TICKETMASTER TM LEFT JOIN TBL_STATUSMASTER TS ON TS.ID = TM.STATUS,TBL_CUSTOMERLOGIN PL WHERE PL.CLID = TM.FROMPLID AND TM.ACTIVE=0');
  v_parmdefinition := N'@RECORDCOUNT NVARCHAR(70) OUTPUT';
  v_countquery := N'SELECT @RECORDCOUNT= COUNT(1) FROM TBL_TICKETMASTER TM LEFT JOIN TBL_STATUSMASTER TS ON TS.ID = TM.STATUS,TBL_CUSTOMERLOGIN PL WHERE PL.CLID = TM.FROMPLID AND TM.ACTIVE=0';
  IF (v_fromdate <> '' OR v_todate <> '') THEN
  IF (v_fromdate <> '') THEN
  v_condition := v_condition || (' AND CONVERT(DATE,TM.DATE,103) >= CONVERT(Date,''' || v_fromdate || ''',103) ');
  END IF;
  IF (v_todate <> '') THEN
  v_condition := v_condition || (' AND CONVERT(DATE,TM.DATE,103) <= CONVERT(Date,''' || v_todate || ''',103) ');
  END IF;
  ELSE
  IF (v_fromdate <> '' AND v_todate <> '') THEN
  v_condition := v_condition || (' AND CONVERT(DATE,TM.DATE,103) BETWEEN CONVERT(DATE,''' || v_fromdate || ''',103) AND CONVERT(DATE,''' || v_todate || ''',103) ');
  END IF;
  END IF;
  IF (v_status <> '0') THEN
  v_condition := v_condition || (' AND TM.STATUS=' || v_status);
  END IF;
  IF (v_searchfield = '1') THEN
  v_condition := v_condition || (' AND TM.TICKETNO=' || v_searchvalue);
  END IF;
  IF (v_searchfield = '2') THEN
  v_condition := v_condition || (' AND PL.FNAME LIKE ''%' || v_searchvalue || '%'' ');
  END IF;
  IF (v_searchfield = '3') THEN
  v_condition := v_condition || (' AND PL.USERNAME LIKE ''%' || v_searchvalue || '%'' ');
  END IF;
  IF (v_searchfield = '4') THEN
  v_condition := v_condition || (' AND TM.CATEGORYNAME LIKE ''%' || v_searchvalue || '%'' ');
  END IF;
  IF (v_searchfield = '5') THEN
  v_condition := v_condition || (' AND PL.PHONE LIKE ''%' || v_searchvalue || '%'' ');
  END IF;
  IF (v_fromplid <> '') THEN
  v_condition := v_condition || (' And TM.FROMPLID =' || v_fromplid);
  END IF;
  v_queryresult := v_queryresult || v_condition || ' ;SELECT  *  FROM #TEMP WHERE ROWNUMBER BETWEEN ' || CAST(v_minindex AS VARCHAR(70)) || ' AND ' || CAST(v_maxindex AS VARCHAR(70)) || '';
  v_countquery := v_countquery || v_condition;
  RAISE NOTICE '%', v_queryresult;
  EXECUTE v_queryresult;
  EXECUTE v_countquery;
  -- SET option (removed)
END;
$$;


