-- Name: usp_allvochermaster(integer, integer, character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_allvochermaster(v_vmid integer DEFAULT 0, v_vcmid integer DEFAULT 0, v_brand character varying DEFAULT ''::character varying) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_sqlquery text;
BEGIN
  -- SET option (removed)
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp (ROWNUMBER INT,          
VMID INT,         
VCTID INT,         
BRANDNAME Varchar(100),          
bytea Varchar(100),        
DESCRIPTION text,        
TERMOFUSE text,        
INSTRUCTION text,        
DATE timestamp,        
ACTIVE INT,        
STATUS INT) ON COMMIT DROP;
  v_sqlquery := '';
  v_sqlquery := ' INSERT INTO #TEMP SELECT ROW_NUMBER() OVER(ORDER BY VMID ASC) AS         
ROWNUMBER ,VMID,VCTID,BRANDNAME,IMAGE,DESCRIPTION,        
TERMOFUSE,INSTRUCTION,DATE,ACTIVE,STATUS        
FROM TBL_VOUCHER_MASTER PDM WHERE ACTIVE=1 AND STATUS=1';
  IF (v_vmid > 0) THEN
  v_sqlquery := v_sqlquery || (' AND VMID=' || CAST(v_vmid AS VARCHAR(20)));
  END IF;
  IF (v_vcmid > 0) THEN
  v_sqlquery := v_sqlquery || (' AND VCTID=' || CAST(v_vcmid AS VARCHAR(20)));
  END IF;
  IF (v_brand <> '') THEN
  v_sqlquery := v_sqlquery || (' AND BRANDNAME Like ''%' || v_brand || '%''');
  END IF;
  EXECUTE v_sqlquery;
  RETURN QUERY SELECT * FROM tmp_temp;
  DROP TABLE IF EXISTS tmp_temp;
  -- SET option (removed)
END;
$$;


--
-- Name: usp_api_setting(integer, character varying, character varying, character varying, character varying, character varying, integer, character varying, character varying, character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_api_setting(v_plid integer, v_email character varying, v_hostname character varying, v_port character varying, v_password character varying, v_title character varying, v_check integer, INOUT v_message character varying, v_senderid character varying, v_sendername character varying) RETURNS character varying
    LANGUAGE plpgsql
    AS $$
BEGIN
  -- BEGIN TRAN (removed)
  v_message := 'Success';
  IF EXISTS(SELECT emailid FROM tbl_emailmembermaster WHERE emailid = v_email AND isdeleted = 0) THEN
  v_message := 'Email id already exist!';
  -- COMMIT (removed)
  RETURN;
  END IF;
  INSERT INTO tbl_emailmembermaster (plid, emailid, hostname, port, password, title, isactive, isdeleted, senderid, sendername) VALUES (v_plid, v_email, v_hostname, v_port, v_password, v_title, v_check, 0, v_senderid, v_sendername);
  IF (0 <> 0) THEN
  v_message := 'Some error occurred !';
  -- ROLLBACK (removed)
  RETURN;
  END IF;
  -- COMMIT (removed)
END;
$$;


