    LANGUAGE plpgsql
    AS $$
BEGIN
  -- BEGIN TRAN (removed)
  v_message := 'Success';
  UPDATE tbl_emailmembermaster SET emailid = v_email, hostname = v_hostname, port = v_port, password = v_password, title = v_title, isactive = v_check, isdeleted = 0, senderid = v_senderid, sendername = v_sendername WHERE temid = v_temid;
  IF (0 <> 0) THEN
  v_message := 'Some error occurred !';
  -- ROLLBACK (removed)
  RETURN;
  END IF;
  -- COMMIT (removed)
END;
$$;


--
-- Name: usp_approvalandnewsale(bigint, bigint, character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_approvalandnewsale(v_id bigint DEFAULT 0, v_branchid bigint DEFAULT 0, v_strresult character varying DEFAULT NULL::character varying) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_sprid BigInt;
  v_mprid BigInt;
  v_companyid int;
  v_mcid int;
  v_catid int;
  v_subcatid int;
  v_brand int;
  v_productcode varchar(50);
  v_subprcode varchar(50);
  v_prodtitle varchar(300);
  v_activefrom varchar(50);
  v_activeto varchar(50);
  v_shortdesc varchar(500);
  v_fulldesc text;
  v_isallowcoupon boolean;
  v_minorderqty int;
  v_maxorderqty int;
  v_paymode varchar(100);
  v_sellmrp decimal(18,2);
  v_discountper decimal(18,2);
  v_qty int;
  v_produnit varchar(50);
  v_color varchar(50);
  v_size varchar(50);
  v_prodimages text;
  v_allattributes text;
  v_vcid int;
  v_vatp decimal(18,2);
  v_directamt decimal(18,2);
  v_dap decimal(18,2);
  v_replacementday int;
  v_keyfeatures varchar(2000);
  v_stockin int;
  v_procurementsla int;
  v_shippingcharges decimal(18,2);
  v_cashondelivery boolean;
  v_pkg_weight_kg decimal(18,2);
  v_pkg_length_cms decimal(18,2);
  v_pkg_breadth_cms decimal(18,2);
  v_pkg_height_cms decimal(18,2);
  v_warrentyinfocare int;
  v_dealsids varchar(50);
  v_groupid varchar(50);
  v_logid BigInt;
  v_maincatid int;
  v_cid int;
  v_pricecurrency varchar(50);
  v_maxmprid bigint;
  v_count1 int;
  v_count2 int;
  v_value varchar(200);
  v_title varchar(100);
  v_itemval varchar(100);
  v_paybleamount decimal(18,2);
  v_commissionamount Decimal(18,0);
  v_lastidentity BIGINT;
  v_awk int;
BEGIN
  -- BEGIN TRAN (removed)
  BEGIN
  RAISE NOTICE '%', 'RAM';
  v_sprid := 0;
  v_mprid := 0;
  v_companyid := 0;
  v_brand := 0;
  v_activefrom := '';
  v_activeto := '';
  v_isallowcoupon := 0;
  v_minorderqty := 0;
  v_maxorderqty := 0;
  v_paymode := '';
  v_color := '';
  v_size := '';
  v_directamt := 0;
  v_keyfeatures := '';
  v_stockin := 0;
  v_procurementsla := 0;
  v_shippingcharges := 0;
  v_cashondelivery := 0;
  v_pkg_weight_kg := NULL;
  v_pkg_length_cms := NULL;
  v_pkg_breadth_cms := NULL;
  v_pkg_height_cms := NULL;
  v_warrentyinfocare := 0;
  v_dealsids := '';
  v_groupid := '';
  v_strresult := 'ok';
  IF EXISTS(SELECT * FROM excel_product WHERE id = v_id AND branchid = v_branchid) THEN
  RAISE NOTICE '%', 'A';
  SELECT mcid, cid, scid, vcid, code, producttitle, shortdescription, fulldescription, keyfeatures, unitqty, unit, stockin, productimages, sellmrp, dap, discount, dealsids, groupid, replacementday, procurementsla, cashondelivery, shippingcharges, weight_kg, length_cms, breadth_cms, height_cms, warrentyinfocare, allattribute INTO v_mcid, v_catid, v_subcatid, v_vcid, v_subprcode, v_prodtitle, v_shortdesc, v_fulldesc, v_keyfeatures, v_qty, v_produnit, v_stockin, v_prodimages, v_sellmrp, v_dap, v_discountper, v_dealsids, v_groupid, v_replacementday, v_procurementsla, v_cashondelivery, v_shippingcharges, v_pkg_weight_kg, v_pkg_length_cms, v_pkg_breadth_cms, v_pkg_height_cms, v_warrentyinfocare, v_allattributes FROM excel_product WHERE id = v_id;
  IF EXISTS(SELECT 1 FROM tbl_vat_categories WHERE vcid = v_vcid) THEN
  RAISE NOTICE '%', 'B';
  SELECT vatpercvalue INTO v_vatp FROM tbl_vat_categories WHERE vcid = v_vcid;
  END IF;
  IF EXISTS(SELECT 1 FROM ims_masterproduct WHERE REPLACE(producttitle, ' ', '') = REPLACE(v_prodtitle, ' ', '')) THEN
  RAISE NOTICE '%', 'C';
  SELECT v_mprid, maincategoryid, catid, subcategoryid, vatcategoryid INTO v_mprid, v_mcid, v_catid, v_subcatid, v_vcid FROM ims_masterproduct WHERE producttitle = v_prodtitle;
  END IF;
  RAISE NOTICE '%', 'KeyFeature Start';
  IF (COALESCE(v_keyfeatures, '') <> '') THEN
  SELECT '<ul><li>' || REPLACE(v_keyfeatures, '^', '</li><li>') || '</li></ul>' INTO v_keyfeatures;
  END IF;
  RAISE NOTICE '%', 'D';
  RAISE NOTICE '%', 'F';
  v_logid := 0;
  v_lastidentity := 0;
  SELECT maincatid INTO v_maincatid FROM tbl_category WHERE catid = v_catid;
  v_cid := 96;
  RAISE NOTICE '%', 'G';
  IF NOT EXISTS(SELECT 1 FROM ims_masterproduct WHERE REPLACE(producttitle, ' ', '') = REPLACE(v_prodtitle, ' ', '')) THEN
  RAISE NOTICE '%', 'H';
  SELECT CASE WHEN COALESCE(v_productcode, '') = '' THEN (SELECT 'SKU_' || CAST((COALESCE(MAX(mprid), 0) + 1) AS VARCHAR(100)) FROM ims_masterproduct) ELSE v_productcode END INTO v_productcode;
  RAISE NOTICE '%', 'I';
  INSERT INTO ims_masterproduct (productcode, maincategoryid, subcategoryid, brandid, producttitle, shotdescription, fulldescription, keyfeatures, minorderqty, maxorderqty, paymode, vatcategoryid, companyid, branchid, createddate, modifydate, catid) VALUES (v_productcode, v_maincatid, v_subcatid, v_brand, v_prodtitle, v_shortdesc, v_fulldesc, v_keyfeatures, v_minorderqty, v_maxorderqty, v_paymode, v_vcid, v_companyid, v_branchid, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, v_catid);
  v_maxmprid := LASTVAL();
  RAISE NOTICE '%', 'J';
  ELSE
  RAISE NOTICE '%', 'K';
  SELECT mprid INTO v_mprid FROM ims_masterproduct WHERE REPLACE(producttitle, ' ', '') = REPLACE(v_prodtitle, ' ', '');
  v_maxmprid := v_mprid;
  END IF;
  SELECT CASE WHEN COALESCE(v_subprcode, '') = '' THEN (SELECT CAST((COALESCE(MAX(sprid), 0) + 1) AS VARCHAR(100)) FROM ims_subproduct) ELSE v_subprcode END INTO v_subprcode;
  RAISE NOTICE '%', 'L';
  IF NOT EXISTS(SELECT 1 FROM ims_subproduct WHERE REPLACE(subprcode, ' ', '') = REPLACE(v_subprcode, ' ', '')) THEN
  RAISE NOTICE '%', 'M';
  INSERT INTO ims_subproduct (subprcode, mprid, qty, unit, color, size, productimages, shippingcharges, discountpercentage, vatcategoryid, actualprice, sellmrp, dap, directamount, activefrom, activeto, isallowcoupon, isactive, isverified, createddate, modifydate, replacementday, procurementsla, cashondelivery, weight_kg, length_cms, breadth_cms, height_cms, stockin, stockout, stocknet, isoutofstock, warrentyinfocare, dealsids, groupid) VALUES (v_subprcode, v_maxmprid, v_qty, v_produnit, v_color, v_size, v_prodimages, v_shippingcharges, v_discountper, v_vcid, 0, v_sellmrp, v_dap, v_directamt, v_activefrom, v_activeto, v_isallowcoupon, 1, 1, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, v_replacementday, v_procurementsla, v_cashondelivery, v_pkg_weight_kg, v_pkg_length_cms, v_pkg_breadth_cms, v_pkg_height_cms, v_stockin, 0, v_stockin, (CASE WHEN v_stockin > 0 THEN 0 ELSE 1 END), v_warrentyinfocare, v_dealsids, v_groupid);
  RAISE NOTICE '%', 'N';
  v_sprid := LASTVAL();
  SELECT subprcode INTO v_subprcode FROM ims_subproduct WHERE sprid = v_sprid;
  SELECT IDENT_CURRENT('IMS_SubProduct') INTO v_lastidentity;
  v_strresult := 'ok^Success^Your Product Added Successfully.';
  RAISE NOTICE '%', 'O';
  END IF;
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp (rowno int GENERATED BY DEFAULT AS IDENTITY,
		Value varchar(200)) ON COMMIT DROP;
  INSERT INTO tmp_temp SELECT value FROM dbo.SPLITSTRINGBYCUSTOMSYMBOL1(v_allattributes, '^') WHERE COALESCE(value, '') <> '';
  v_count1 := 1;
  SELECT COUNT(1) INTO v_count2 FROM tmp_temp;
  WHILE (v_count1 <= v_count2) LOOP
  RAISE NOTICE '%', 'FFF';
  SELECT value INTO v_value FROM tmp_temp WHERE rowno = v_count1;
  v_title := SUBSTRING(v_value FROM 1 FOR POSITION('~' IN v_value) - 1);
  v_itemval := SUBSTRING(v_value FROM POSITION('~' IN v_value) + 1 FOR LENGTH(CAST(v_value AS TEXT)));
  IF (v_value <> 'No') THEN
  v_awk := 0;
  END IF;
  SELECT maincatid INTO v_maincatid FROM dbo.tbl_category WHERE catid = v_catid;
  SELECT maincatid, catid INTO v_maincatid, v_catid FROM dbo.tbl_sub_category WHERE subcatid = v_subcatid;
  IF (COALESCE(v_subcatid, 0) <> 0) THEN
  RAISE NOTICE '%', 'subcat';
  SELECT awct_id INTO v_awk FROM tbl_attributes_with_category WHERE att_name = v_title AND sub_cat_id = COALESCE(v_subcatid, 0) OR cat_id = COALESCE(v_catid, 0) OR main_cat_id = COALESCE(v_maincatid, 0);
  ELSE
  IF (COALESCE(v_catid, 0) <> 0) THEN
  RAISE NOTICE '%', 'cat';
  SELECT awct_id INTO v_awk FROM tbl_attributes_with_category WHERE att_name = v_title AND sub_cat_id = 0 AND cat_id = COALESCE(v_catid, 0) OR main_cat_id = COALESCE(v_maincatid, 0);
  ELSE
  IF (COALESCE(v_maincatid, 0) <> 0) THEN
  RAISE NOTICE '%', 'main';
  SELECT awct_id INTO v_awk FROM tbl_attributes_with_category WHERE att_name = v_title AND sub_cat_id = 0 AND cat_id = 0 OR main_cat_id = COALESCE(v_maincatid, 0);
  END IF;
  END IF;
  END IF;
  INSERT INTO ims_masterproductattribute (sprid, title, value, showongrid, position, isactive, catid, awcid, subcatid) VALUES (v_lastidentity, v_title, v_itemval, 1, 1, 1, v_catid, v_awk, v_subcatid);
  v_count1 := v_count1 + 1;
  END LOOP;
  DROP TABLE IF EXISTS tmp_temp;
  RAISE NOTICE '%', 'G';
  RAISE NOTICE '%', v_strresult;
  DELETE FROM temp_masterproductattribute WHERE sprid = v_id;
  DELETE FROM excel_product WHERE id = v_id AND branchid = v_branchid;
  RAISE NOTICE '%', 'DElETED Row';
  -- COMMIT (removed)
  RETURN;
  END IF;
  EXCEPTION WHEN OTHERS THEN
  IF (0 <> 0) THEN
  RETURN QUERY SELECT 0 AS error;
  RAISE NOTICE '%', 'ROLLBACK';
  -- ROLLBACK (removed)
  v_strresult := 'error^error^Something Went Wrong.';
  RETURN;
  END IF;
  END;
END;
$$;


