--
-- Name: usp_approve_customer_kyc(integer, integer, character varying, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_approve_customer_kyc(v_id integer DEFAULT 7, v_kycmode integer DEFAULT 2, v_remark character varying DEFAULT 'xczvc'::character varying, INOUT v_intresult integer DEFAULT 0) RETURNS integer
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_clid BIGINT;
  v_addressproof int;
  v_pancard int;
  v_iskycapproved INT;
  v_tcntid INT;
BEGIN
  v_clid := 0;
  v_addressproof := 0;
  v_pancard := 0;
  v_iskycapproved := 0;
  IF (v_kycmode = 1) THEN
  UPDATE tbl_customer_kyc SET isaprove = 1, commentorremark = v_remark WHERE id = v_id;
  v_intresult := 1;
  END IF;
  IF (v_kycmode = 2) THEN
  UPDATE tbl_customer_kyc SET isaprove = 2, commentorremark = v_remark WHERE id = v_id;
  v_intresult := 2;
  END IF;
  SELECT clid INTO v_clid FROM tbl_customer_kyc WHERE id = v_id;
  SELECT isaprove INTO v_addressproof FROM tbl_customer_kyc WHERE clid = v_clid AND type = 'Address-Proof';
  SELECT isaprove INTO v_pancard FROM tbl_customer_kyc WHERE clid = v_clid AND type = 'Pancard-Details';
  IF (v_addressproof = 1 AND v_pancard = 1) THEN
  UPDATE tbl_customerlogin SET iskycapproved = 1 WHERE clid = v_clid;
  END IF;
  IF (v_addressproof = 2 OR v_pancard = 2) THEN
  UPDATE tbl_customerlogin SET iskycapproved = 2 WHERE clid = v_clid;
  END IF;
  SELECT iskycapproved INTO v_iskycapproved FROM tbl_customerlogin WHERE clid = v_clid;
  IF (v_iskycapproved = 1) THEN
  v_tcntid := 0;
  SELECT tcntid INTO v_tcntid FROM tbl_customer_notifications_type WHERE notificationtype = 'KYC';
  INSERT INTO dbo.tbl_customer_notifications VALUES (v_tcntid, v_clid, 'Your KYC has been approved Successfully', dbo.FUN_GETCURRENTDATE(), '', 0, 1, dbo.FUN_GETCURRENTDATE(), '', NULL);
  END IF;
END;
$$;


--
-- Name: usp_approvedarea(text, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_approvedarea(v_areaname text DEFAULT ''::text, INOUT v_intresult integer DEFAULT NULL::integer) RETURNS integer
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_slice1 text;
  v_index1 INT;
  v_index2 text;
  v_slice2 text;
  v_slice3 text;
  v_slice4 text;
  v_sarea text;
  v_ctid int;
  v_sid int;
  v_cid int;
BEGIN
  -- SET option (removed)
  v_slice1 := v_areaname;
  v_index1 := 1;
  WHILE v_index1 <> 0 LOOP
  SELECT POSITION('~' IN v_slice1) INTO v_index1;
  IF v_index1 <> -1 THEN
  IF v_index1 = 0 THEN
  v_slice2 := v_slice1;
  ELSE
  SELECT LEFT(CAST(v_slice1 AS TEXT), v_index1 - 1) INTO v_slice2;
  END IF;
  v_index2 := 1;
  SELECT POSITION('+' IN v_slice2) INTO v_index2;
  SELECT LEFT(CAST(v_slice2 AS TEXT), v_index2 - 1) INTO v_slice3;
  SELECT RIGHT(CAST(v_slice2 AS TEXT), 1) INTO v_slice4;
  IF (v_slice4 = 1) THEN
  SELECT areaname, ctid, cid, sid INTO v_sarea, v_ctid, v_cid, v_sid FROM suggestedarea_master WHERE said = v_slice3;
  IF EXISTS(SELECT areaname FROM area_master WHERE areaname = v_sarea AND cactive = 1 AND ctid = v_ctid) THEN
  UPDATE suggestedarea_master SET active = 0, isdeleted = 1 WHERE said = v_slice3;
  ELSE
  INSERT INTO area_master (cid, sid, ctid, areaname, cactive) VALUES (v_cid, v_sid, v_ctid, v_sarea, 1);
  UPDATE suggestedarea_master SET active = 0, isdeleted = 1 WHERE said = v_slice3;
  v_intresult := 1;
  END IF;
  ELSE
  IF (v_slice4 = 0) THEN
  UPDATE suggestedarea_master SET active = 0, isdeleted = 1 WHERE said = v_slice3;
  v_intresult := 1;
  END IF;
  END IF;
  END IF;
  SELECT RIGHT(CAST(v_slice1 AS TEXT), LENGTH(CAST(v_slice1 AS TEXT)) - v_index1) INTO v_slice1;
  IF LENGTH(CAST(v_slice1 AS TEXT)) = 0 THEN
  EXIT;
  END IF;
  END LOOP;
  IF (0 <> 0) THEN
  v_intresult := 2;
  -- ROLLBACK (removed)
  RETURN;
  END IF;
  -- SET option (removed)
END;
$$;


--
-- Name: usp_approvedareapaging(integer, integer, character varying, boolean, character varying, character varying, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_approvedareapaging(v_startrowindex integer, v_maxrows integer, v_orderbyfield character varying, v_asc boolean, v_searchfield character varying, v_searchvalue character varying, v_mode integer) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_recordcount int;
  v_regno bigint;
BEGIN
  -- SET option (removed)
  DROP TABLE IF EXISTS tmp_temp21;
  CREATE TEMP TABLE tmp_temp21 ON COMMIT DROP AS SELECT ROW_NUMBER() OVER (ORDER BY areaname NULLS FIRST) AS rownumber, c.cid, st.sid, city.ctid, countryname, statename, cityname, areaname, sm.active, sm.said FROM suggestedarea_master AS sm INNER JOIN city AS city ON sm.ctid = city.ctid INNER JOIN state AS st ON city.sid = st.sid INNER JOIN country AS c ON st.cid = c.cid AND sm.active = 1 AND isdeleted = 0;
  IF (v_searchfield = '') THEN
  RETURN QUERY SELECT * FROM tmp_temp21 WHERE rownumber BETWEEN v_startrowindex AND v_maxrows;
  END IF;
  DROP TABLE IF EXISTS tmp_temp21;
  -- SET option (removed)
END;
$$;


--
-- Name: usp_approvereject_customerbanktransfer(integer, integer, character varying, text, character varying, integer, character varying, integer, character varying); Type: FUNCTION; Schema: dbo; Owner: -
