    LANGUAGE plpgsql
    AS $$
BEGIN
  BEGIN
  -- BEGIN TRAN (removed)
  -- SET option (removed)
  -- SET option (removed)
  IF (v_mode = 1 AND v_clid <> 0 AND v_tranactionid <> '') THEN
