  UPDATE tbl_customer_transfertobankhistory SET ispaid = 1 WHERE transactionid = v_tranactionid AND ispaid = 0;
  ELSE
  -- COMMIT (removed)
  v_stroutput := 'INVALID';
  RETURN;
  END IF;
  END IF;
  IF (v_mode = 2 AND v_clid <> 0 AND v_tranactionid <> '') THEN
  IF EXISTS(SELECT 1 FROM dbo.tbl_customer_transfertobank WHERE transactionid = v_tranactionid AND status = 0 AND ispaid = 0 AND clid = v_clid) THEN
  RETURN QUERY SELECT 1;
  UPDATE dbo.tbl_customer_transfertobank SET status = v_mode, adminremarks = v_adminremarks, approveddate = dbo.FUN_GETCURRENTDATE(), paidtransactionid = v_paidtransactionid, paymode = v_paymode, activityby = v_activityby, ispaid = 2 WHERE transactionid = v_tranactionid AND status = 0 AND ispaid = 0 AND clid = v_clid;
  UPDATE tbl_customer_transfertobankhistory SET ispaid = 2 WHERE transactionid = v_tranactionid AND ispaid = 0;
  ELSE
  -- COMMIT (removed)
  v_stroutput := 'INVALID';
  RETURN;
  END IF;
  END IF;
  -- COMMIT (removed)
  v_stroutput := 'SUCCESS';
  EXCEPTION WHEN OTHERS THEN
  IF (0 > 0) THEN
  v_stroutput := 'Error';
  -- ROLLBACK (removed)
  RETURN;
  END IF;
  END;
END;
$$;


