--
-- Name: usp_approvesubscription(bigint, character varying, numeric, character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_approvesubscription(v_sdid bigint DEFAULT 0, v_mode character varying DEFAULT ''::character varying, v_currencyrate numeric DEFAULT 0, INOUT v_strresult character varying DEFAULT ''::character varying) RETURNS character varying
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_ctid VARCHAR(900);
  v_aid text;
  v_catid VARCHAR(900);
  v_keyid VARCHAR(900);
  v_paidamount numeric(19,4);
  v_currenrate numeric(19,4);
  v_pmid BIGINT;
  v_status smallint;
  v_introplid BIGINT;
  v_cid INT;
  v_noofmonth INT;
  v_reamincatid text;
  v_bankname text;
  v_branchname text;
  v_checkno text;
  v_depositdate text;
  v_remark text;
  v_paymenttype text;
  v_plid text;
  v_depositamount text;
BEGIN
  v_ctid := '';
  v_aid := '';
  v_catid := '';
  v_keyid := '';
  v_paidamount := 0;
  v_currenrate := 0;
  -- BEGIN TRAN (removed)
  -- SET option (removed)
  v_strresult := 'Ok';
  SELECT pmid, paidamount, COALESCE(noofmonth, 1), catid, keyid, ctid, aid, COALESCE(v_status, 0) INTO v_pmid, v_paidamount, v_noofmonth, v_catid, v_keyid, v_ctid, v_aid, v_status FROM tbl_subscription_details WHERE sdid = v_sdid;
  IF (v_status = 1) THEN
  v_strresult := 'THIS SUBSCRIPTION IS ALREADY APPROVED.';
  -- COMMIT (removed)
  RETURN;
  END IF;
  IF (v_status = 2) THEN
  v_strresult := 'THIS SUBSCRIPTION IS REJECTED.';
  -- COMMIT (removed)
  RETURN;
  END IF;
  IF (v_mode = 'Reject') THEN
  UPDATE tbl_subscription_details SET status = 2 WHERE sdid = v_sdid;
  v_strresult := 'THIS SUBSCRIPTION IS REJECTED SUCCESSFULLY.';
  -- COMMIT (removed)
  RETURN;
  END IF;
  IF (v_mode = 'Approve') THEN
  v_bankname := '';
  v_branchname := '';
  v_checkno := '';
  v_depositdate := '';
  v_remark := '';
  v_paymenttype := '';
  v_plid := '';
  v_depositamount := '';
  SELECT bankname, branchname, chequenumber, chequedate, commentorremark, mode, plid, amount INTO v_bankname, v_branchname, v_checkno, v_depositdate, v_remark, v_paymenttype, v_plid, v_depositamount FROM tbl_fundaddedapprovalmaster WHERE tfaamid = v_sdid;
  SELECT v_strresult INTO v_strresult FROM dbo.usp_addfundnew(v_plid => v_plid, v_paymenttype => v_paymenttype, v_depositamount => v_depositamount, v_checkno => v_checkno, v_depositdate => v_depositdate, v_bankname => v_bankname, v_branchname => v_branchname, v_accountnumber => '', v_couponno => '', v_fromloginid => '', v_password => '', v_reqfrom => '', v_remark => v_remark, v_fname => '', v_lname => '', v_emailid => '', v_contactno => '', v_ipaddress => '', v_amountinpound => '', v_strresult => v_strresult, v_mode => 1);
  IF (v_strresult = 'Ok') THEN
  UPDATE tbl_fundaddedapprovalmaster SET isactive = 0, status = 'Confirm' WHERE tfaamid = v_sdid;
  END IF;
  DROP TABLE IF EXISTS v_temp;
  CREATE TEMP TABLE v_temp (CATID text) ON COMMIT DROP;
  INSERT INTO v_temp SELECT catid FROM keyword_master WHERE kmid IN (SELECT value FROM dbo.SPLITSTRINGBYCOMMA(v_keyid)) EXCEPT SELECT value AS catid FROM dbo.SPLITSTRINGBYCOMMA(v_catid);
  SELECT COALESCE(v_reamincatid || ',', '') || catid INTO v_reamincatid FROM v_temp;
  UPDATE portal_master SET subcatid = v_catid, subkeyid = v_keyid, subctid = v_ctid, subaid = v_aid, expirydate = ((dbo.FUN_GETCURRENTDATE()) + (INTERVAL '1 MONTH' * v_noofmonth)), subautocatid = v_reamincatid WHERE pmid = v_pmid;
  UPDATE tbl_subscription_details SET status = 1, approvedate = dbo.FUN_GETCURRENTDATE() WHERE sdid = v_sdid;
  SELECT COALESCE(intro_refid, 0) INTO v_introplid FROM portal_login WHERE pmid = v_pmid;
  IF (v_introplid > 0) THEN
  PERFORM dbo.usp_referalincome(v_pmid => v_pmid, v_totoalamount => v_paidamount, v_currencyrate => v_currencyrate, v_intresult => 0);
  END IF;
  END IF;
  IF (0 <> 0) THEN
  v_strresult := 'SOME ERROR OCCURED, PLEASE TRY AGAIN';
  -- ROLLBACK (removed)
  RETURN;
  END IF;
  -- SET option (removed)
  -- COMMIT (removed)
END;
$$;


--
-- Name: usp_approvesuggestedkeyword(integer, integer, character varying, integer, integer, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_approvesuggestedkeyword(v_slid integer DEFAULT 0, v_catid integer DEFAULT 0, v_keywordname character varying DEFAULT ''::character varying, v_suggestedkeywordno integer DEFAULT 0, v_status integer DEFAULT 0, INOUT v_intresult integer DEFAULT NULL::integer) RETURNS integer
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_approveddate timestamp;
  v_smcid int;
  v_kactive int;
  v_scatid int;
BEGIN
  -- BEGIN TRAN (removed)
  -- SET option (removed)
  v_kactive := 1;
  v_scatid := 0;
  v_intresult := 1;
  v_approveddate := GETUTCDATE() + INTERVAL '330 MI';
  IF NOT EXISTS(SELECT keywordname FROM keyword_master WHERE keywordname = v_keywordname) THEN
  INSERT INTO tbl_sponser_approve_keyword (slid, catid, keywordname, approvedate, status) VALUES (v_slid, v_catid, v_keywordname, v_approveddate, v_status);
  INSERT INTO keyword_master (keywordname, kactive, catid, scatid) VALUES (v_keywordname, v_kactive, v_catid, v_scatid);
  UPDATE tb_sposersuggestedkeyword SET approvedate = v_approveddate, approvestatus = v_status WHERE suggest_keyword_no = v_suggestedkeywordno;
  ELSE
  UPDATE tb_sposersuggestedkeyword SET approvedate = v_approveddate, approvestatus = 3 WHERE suggest_keyword_no = v_suggestedkeywordno;
  END IF;
  IF (0 <> 0) THEN
  v_intresult := 0;
  -- ROLLBACK (removed)
  RETURN;
  END IF;
  -- SET option (removed)
  -- COMMIT (removed)
END;
$$;


--
-- Name: usp_areamaster(integer, integer, character varying, boolean, character varying, character varying, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_areamaster(v_startrowindex integer, v_maxrows integer, v_orderbyfield character varying, v_asc boolean, v_searchfield character varying, v_searchvalue character varying, v_mode integer) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_recordcount int;
  v_regno bigint;
BEGIN
  -- SET option (removed)
  DROP TABLE IF EXISTS tmp_temp12;
  CREATE TEMP TABLE tmp_temp12 ON COMMIT DROP AS SELECT ROW_NUMBER() OVER (ORDER BY c.countryname NULLS FIRST, s.statename NULLS FIRST, ci.cityname NULLS FIRST, am.areaname NULLS FIRST) AS rownumber, c.countryname, s.statename, ci.cityname, (CASE am.cactive WHEN 1 THEN 'active' WHEN 0 THEN 'Deactive' END) AS distactive, ci.ctid, am.areaname, am.aid FROM state AS s INNER JOIN country AS c ON c.cid = s.cid INNER JOIN city AS ci ON ci.sid = s.sid INNER JOIN area_master AS am ON am.ctid = ci.ctid;
  SELECT COUNT(*) INTO v_recordcount FROM tmp_temp12;
  IF (v_searchfield = 'Cuntryname') THEN
  RETURN QUERY SELECT * FROM tmp_temp12 WHERE countryname LIKE '%' || v_searchvalue || '%';
  END IF;
  IF (v_searchfield = 'cityname') THEN
  RETURN QUERY SELECT * FROM tmp_temp12 WHERE cityname LIKE '%' || v_searchvalue || '%';
  END IF;
  IF (v_searchfield = 'stateName') THEN
  RETURN QUERY SELECT * FROM tmp_temp12 WHERE statename LIKE '%' || v_searchvalue || '%';
  END IF;
  IF (v_searchfield = 'areaname') THEN
  RETURN QUERY SELECT * FROM tmp_temp12 WHERE areaname LIKE '%' || v_searchvalue || '%';
  END IF;
  IF (v_searchfield = '') THEN
  RETURN QUERY SELECT * FROM tmp_temp12 WHERE rownumber BETWEEN v_startrowindex AND v_maxrows;
  END IF;
  DROP TABLE IF EXISTS tmp_temp12;
  -- SET option (removed)
END;
$$;


--
-- Name: usp_areapaging(integer, integer, character varying, boolean, character varying, character varying, integer, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_areapaging(v_startrowindex integer, v_maxrows integer, v_orderbyfield character varying, v_asc boolean, v_searchfield character varying, v_searchvalue character varying, v_mode integer, v_intresultcount integer DEFAULT 0) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_recordcount int;
  v_regno bigint;
  v_minindex INT;
  v_maxindex INT;
  v_query text;
BEGIN
  -- SET option (removed)
  v_minindex := (v_startrowindex - 1) * v_maxrows + 1;
  v_maxindex := v_startrowindex * v_maxrows;
  DROP TABLE IF EXISTS tmp_temp12;
  CREATE TEMP TABLE tmp_temp12 ON COMMIT DROP AS SELECT ROW_NUMBER() OVER (ORDER BY am.areaname NULLS FIRST, c.countryname NULLS FIRST, s.statename NULLS FIRST, ci.cityname NULLS FIRST, s.sid NULLS FIRST) AS rownumber, c.countryname, s.statename, ci.cityname, am.areaname, am.aid, s.sid, (CASE am.cactive WHEN 1 THEN 'active' WHEN 0 THEN 'Deactive' END) AS distactive, ci.ctid FROM state AS s INNER JOIN country AS c ON c.cid = s.cid INNER JOIN city AS ci ON ci.sid = s.sid INNER JOIN area_master AS am ON am.ctid = ci.ctid WHERE am.cactive = 1;
  SELECT COUNT(*) INTO v_recordcount FROM tmp_temp12;
  IF (v_searchfield = 'countryname') THEN
  RETURN QUERY SELECT * FROM tmp_temp12 WHERE countryname LIKE '%' || v_searchvalue || '%';
  END IF;
  IF (v_searchfield = 'stateName') THEN
  RETURN QUERY SELECT * FROM tmp_temp12 WHERE statename LIKE '%' || v_searchvalue || '%';
  END IF;
  IF (v_searchfield = 'cityname') THEN
  RETURN QUERY SELECT * FROM tmp_temp12 WHERE cityname LIKE '%' || v_searchvalue || '%';
  END IF;
  IF (v_searchfield = 'areaname') THEN
  RETURN QUERY SELECT * FROM tmp_temp12 WHERE areaname LIKE '%' || v_searchvalue || '%';
  END IF;
  IF (v_searchfield = '') THEN
  RETURN QUERY SELECT * FROM tmp_temp12 WHERE rownumber BETWEEN v_minindex AND v_maxindex;
  END IF;
  SELECT COUNT(1) INTO v_intresultcount FROM tmp_temp12;
  DROP TABLE IF EXISTS tmp_temp12;
  -- SET option (removed)
END;
$$;


--
-- Name: usp_assignedtaskreport(bigint, integer, character varying, character varying, character varying, character varying, integer, integer, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_assignedtaskreport(v_plid bigint DEFAULT 0, v_mode integer DEFAULT 3, v_fromdate character varying DEFAULT ''::character varying, v_todate character varying DEFAULT ''::character varying, v_loginid character varying DEFAULT ''::character varying, v_username character varying DEFAULT ''::character varying, v_intresult integer DEFAULT 0, v_startrowindex integer DEFAULT 1, v_maxrows integer DEFAULT 100) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_query text;
  v_newusername VARCHAR(200);
  v_query2 text;
BEGIN
  IF (v_mode = 1) THEN
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp (ROWNUMBER INT ,
	DATE VARCHAR(500),
	TotalAvailableClicksForDay  text,
	TotalClicked  text,
	PreviousCarryForwardClick  text,
	PreviousRemainClick text,
	PricePerClick text,
    PreviousCarryForwardPointForClick text,
    TotalAvailableShareForDay text,
    TotalShared text,
    PreviousCarryForwardShare text,
    PreviousRemainShare  text,
    PricePerShare text,
    PreviousCarryForwardPointForShare text,
   TotalPointForBlog text,
   CreditedNoOfBlog text,
   SubmittedNoOfBlog text,
   CarryForwardNoOfBlog text,
	RemainNoOfBlog text,
	PricePerBlog text,
    TotalPointForClassified text,
	CreditedNoOfClassified text,
 	SubmittedNoOfClassified text,
    CarryForwardNoOfClassified text,
	RemainNoOfClassified text,
	PricePerClassified text,
    USERNAME text) ON COMMIT DROP;
  v_query := '';
  v_query := 'INSERT INTO #TEMP Select ROW_NUMBER()Over(Order By Date Desc)As RowNumber,Convert(varchar(100),DATE,7)As DATE,

	TotalAvailableClicksForDay,TotalClicked,PreviousCarryForwardClick,PreviousRemainClick,PricePerClick,

	PreviousCarryForwardPointForClick,TotalAvailableShareForDay,TotalShared,PreviousCarryForwardShare,PreviousRemainShare,PricePerShare,

	PreviousCarryForwardPointForShare,TotalPointForBlog,CreditedNoOfBlog,SubmittedNoOfBlog ,CarryForwardNoOfBlog,RemainNoOfBlog,PricePerBlog,

	TotalPointForClassified,CreditedNoOfClassified,SubmittedNoOfClassified,CarryForwardNoOfClassified,RemainNoOfClassified,PricePerClassified,

	PORTAL_LOGIN.USERNAME From Tbl_DailyTaskLimits inner join PORTAL_LOGIN  ON Tbl_DailyTaskLimits.PLID=PORTAL_LOGIN.PLID 

	WHERE Tbl_DailyTaskLimits.PLID>0 ';
  IF (v_fromdate <> '' AND v_todate <> '') THEN
  v_query := v_query || ' AND Convert(Date,DATE,103) BETWEEN CONVERT(DATE,''' || v_fromdate || ''',103) AND CONVERT(DATE,''' || v_todate || ''',103) ';
  END IF;
  IF (v_fromdate <> '') THEN
  v_query := v_query || ' AND Convert(Date,DATE,103)>= CONVERT(Date,''' || v_fromdate || ''',103) ';
  END IF;
  IF (v_todate <> '') THEN
  v_query := v_query || ' AND Convert(Date,DATE,103)<= CONVERT(Date,''' || v_todate || ''',103) ';
  END IF;
  IF (v_loginid <> '') THEN
  v_query := v_query || ' AND LOGINID Like ''%' || v_loginid || '%'' ';
  END IF;
  IF (v_username <> '') THEN
  IF (EXISTS(SELECT 1 FROM portal_login WHERE username = v_username)) THEN
  v_query := v_query || (' AND USERNAME LIKE ''%' || v_username || '%''');
  ELSE
  IF (EXISTS(SELECT 1 FROM portal_login_history WHERE username = v_username)) THEN
  v_newusername := '';
  SELECT (SELECT username FROM portal_login WHERE plid IN (SELECT plid FROM portal_login_history WHERE username = v_username)) INTO v_newusername;
  v_query := v_query || (' AND USERNAME LIKE ''%' || v_newusername || '%''');
  ELSE
  v_query := v_query || ' AND USERNAME LIKE ''%' || v_username || '%'' ';
  END IF;
  END IF;
  END IF;
  v_query := v_query || 'Order By Date Desc';
  EXECUTE v_query;
  RETURN QUERY SELECT * FROM tmp_temp;
  SELECT COUNT(1) INTO v_intresult FROM tbl_dailytasklimits;
  DROP TABLE IF EXISTS tmp_temp;
  END IF;
  IF (v_mode = 2) THEN
  RETURN QUERY SELECT maxnoofbusinesslistingperday - totallisting AS avaialablenoofbusinesslisting, maxnoofblogperday - totalblog AS avaialablenoofblog, maxnoofclassifiedperday - totalclassified AS avaialablenoofclassified, maxnoofclicksperdayforview - totalclicked AS previousremainlinkforclick, maxnooflinkperdayforshare - totalshared AS previousremainlinkforshare FROM tbl_datewisecommonroiaccount WHERE CAST(date AS DATE) = CAST(dbo.FUN_GETCURRENTDATE() AS DATE) LIMIT 1;
  END IF;
  IF (v_mode = 3) THEN
  DROP TABLE IF EXISTS tmp_tempdailytaskdetail;
  CREATE TEMP TABLE tmp_tempdailytaskdetail (ROWNUMBER INT GENERATED BY DEFAULT AS IDENTITY,
	DATE VARCHAR(500),
	TOTALCREDITEDADDPOINTS  text,
	MAXNOOFCLICKSPERDAYFORVIEW  text,
	TOTALCLICKED  text,
	MAXNOOFLINKPERDAYFORSHARE text,
	TOTALSHARED text,
    MAXNOOFBLOGPERDAY text,
    TOTALBLOG text,
    MAXNOOFCLASSIFIEDPERDAY text,
    TOTALCLASSIFIED text,
    MAXNOOFBUSINESSLISTINGPERDAY  text,
    TOTALLISTING text) ON COMMIT DROP;
  v_query2 := '';
  v_query2 := 'INSERT INTO #TEMPDAILYTASKDETAIL SELECT Convert(VARCHAR(50),DATE,106),TOTALCREDITEDADDPOINTS,MAXNOOFCLICKSPERDAYFORVIEW,
      TOTALCLICKED,MAXNOOFLINKPERDAYFORSHARE,TOTALSHARED,MAXNOOFBLOGPERDAY,TOTALBLOG,MAXNOOFCLASSIFIEDPERDAY,TOTALCLASSIFIED,
       MAXNOOFBUSINESSLISTINGPERDAY,TOTALLISTING FROM TBL_DATEWISECOMMONROIACCOUNT WHERE DATE<>''''';
  IF (v_fromdate <> '' AND v_todate <> '') THEN
  v_query2 := v_query2 || ' AND Convert(Date,DATE) BETWEEN CONVERT(DATE,''' || v_fromdate || ''') AND CONVERT(DATE,''' || v_todate || ''') ';
  END IF;
  IF (v_fromdate <> '') THEN
  v_query2 := v_query2 || ' AND Convert(Date,DATE)>= CONVERT(Date,''' || v_fromdate || ''') ';
  END IF;
  IF (v_todate <> '') THEN
  v_query2 := v_query2 || ' AND Convert(Date,DATE)<= CONVERT(Date,''' || v_todate || ''') ';
  END IF;
  EXECUTE v_query2;
  RETURN QUERY SELECT * FROM tmp_tempdailytaskdetail WHERE rownumber BETWEEN v_startrowindex AND v_maxrows;
  SELECT COUNT(1) INTO v_intresult FROM tmp_tempdailytaskdetail;
  DROP TABLE IF EXISTS tmp_tempdailytaskdetail;
  END IF;
END;
$$;


--
-- Name: usp_attribute_list(character varying, integer, character varying, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_attribute_list(v_type character varying DEFAULT 'Subcat'::character varying, v_id integer DEFAULT 1, v_cat_name character varying DEFAULT ''::character varying, v_totalcount integer DEFAULT 0) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_subcatid INT;
  v_catid INT;
  v_maincatid INT;
BEGIN
  IF (v_type = 'Mcat') THEN
  RETURN QUERY SELECT awct_id, main_cat_id, sub_cat_id, cat_id, att_name, att_type, tbl_attributes_with_category.ddl_id, sr_no, is_active, issearch, ismendatory, CASE WHEN tbl_attributes_with_category.ddl_id > 0 THEN tbl_ddl_master.ddl_name ELSE default_value END AS default_value FROM tbl_attributes_with_category LEFT JOIN tbl_ddl_master ON tbl_attributes_with_category.ddl_id = tbl_ddl_master.ddl_id WHERE main_cat_id = v_id AND cat_id = 0 AND sub_cat_id = 0;
  SELECT COUNT(1) INTO v_totalcount FROM tbl_attributes_with_category WHERE main_cat_id = v_id AND cat_id = 0 AND sub_cat_id = 0;
  SELECT maincatname INTO v_cat_name FROM tbl_main_category WHERE maincatid = v_id;
  END IF;
  IF (v_type = 'Cat') THEN
  SELECT maincatid INTO v_maincatid FROM tbl_category WHERE catid = v_id;
  RETURN QUERY SELECT awct_id, main_cat_id, sub_cat_id, cat_id, att_name, att_type, tbl_attributes_with_category.ddl_id, sr_no, is_active, issearch, ismendatory, CASE WHEN tbl_attributes_with_category.ddl_id > 0 THEN tbl_ddl_master.ddl_name ELSE default_value END AS default_value FROM tbl_attributes_with_category LEFT JOIN tbl_ddl_master ON tbl_attributes_with_category.ddl_id = tbl_ddl_master.ddl_id WHERE (cat_id = v_id OR (main_cat_id = v_maincatid AND cat_id = 0 AND sub_cat_id = 0)) AND sub_cat_id = 0;
  SELECT COUNT(1) INTO v_totalcount FROM tbl_attributes_with_category WHERE (cat_id = v_id OR (main_cat_id = v_maincatid AND cat_id = 0 AND sub_cat_id = 0)) AND sub_cat_id = 0;
  SELECT catname INTO v_cat_name FROM tbl_category WHERE catid = v_id;
  END IF;
  IF (v_type = 'Subcat') THEN
  SELECT maincatid, catid INTO v_maincatid, v_catid FROM dbo.tbl_sub_category WHERE subcatid = v_id;
  RETURN QUERY SELECT awct_id, main_cat_id, sub_cat_id, cat_id, att_name, att_type, tbl_attributes_with_category.ddl_id, sr_no, is_active, issearch, ismendatory, CASE WHEN tbl_attributes_with_category.ddl_id > 0 THEN tbl_ddl_master.ddl_name ELSE default_value END AS default_value FROM tbl_attributes_with_category LEFT JOIN tbl_ddl_master ON tbl_attributes_with_category.ddl_id = tbl_ddl_master.ddl_id WHERE sub_cat_id = v_id OR (cat_id = v_catid AND sub_cat_id = 0) OR (main_cat_id = v_maincatid AND cat_id = 0 AND sub_cat_id = 0);
  SELECT COUNT(1) INTO v_totalcount FROM tbl_attributes_with_category WHERE sub_cat_id = v_id OR (cat_id = v_catid AND sub_cat_id = 0) OR (main_cat_id = v_maincatid AND cat_id = 0 AND sub_cat_id = 0);
  SELECT subcatname INTO v_cat_name FROM tbl_sub_category WHERE subcatid = v_id;
  END IF;
END;
$$;


