--
-- Name: usp_auto_kyc(bigint, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_auto_kyc(v_regno bigint DEFAULT 0, v_mode integer DEFAULT 0) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_plid BIGINT;
  v_currentdate timestamp;
  v_beforedate timestamp;
  v_fname VARCHAR(100);
  v_counts INT;
  v_sno INT;
  v_counts2 int;
BEGIN
  -- BEGIN TRAN (removed)
  v_plid := 0;
  v_fname := '';
  v_counts := 0;
  v_sno := 0;
  v_counts2 := 0;
  SELECT CURRENT_TIMESTAMP, GETUTCDATE() + INTERVAL '330 MINUTE' + INTERVAL '-1 DAY' INTO v_currentdate, v_beforedate;
  SELECT COUNT(1) INTO v_counts FROM kyc_mail_alert WHERE date = TO_DATE(CURRENT_TIMESTAMP, 'DD-MM-YYYY');
  SELECT COUNT(1) INTO v_counts2 FROM businesskyc_mail_alert WHERE date = TO_DATE(CURRENT_TIMESTAMP, 'DD-MM-YYYY');
  IF (v_mode = 0) THEN
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp (PLID BIGINT,
FNAME VARCHAR(100)) ON COMMIT DROP;
  IF (v_counts = 0) THEN
  INSERT INTO tmp_temp SELECT plid, fname FROM portal_login WHERE TO_DATE(doc, 'DD-MM-YYYY') <= TO_DATE(v_beforedate, 'DD-MM-YYYY') AND intro_plid > 0 AND isreferralaccepted = 1;
  INSERT INTO kyc_mail_alert (date) VALUES (TO_DATE(v_currentdate, 'DD-MM-YYYY'));
  RETURN QUERY SELECT * FROM tmp_temp;
  DROP TABLE IF EXISTS tmp_temp;
  END IF;
  END IF;
  IF (v_mode = 1) THEN
  DROP TABLE IF EXISTS tmp_temp2;
  CREATE TEMP TABLE tmp_temp2 (PLID BIGINT,
FNAME VARCHAR(100)) ON COMMIT DROP;
  IF (v_counts2 = 0) THEN
  INSERT INTO tmp_temp2 SELECT pl.plid, pl.fname FROM portal_login AS pl INNER JOIN portal_master AS pm ON pl.plid = pm.plid WHERE pm.kycstatus = 0 AND NOT pl.plid IN (SELECT regno FROM kyc WHERE kyctype = 2);
  INSERT INTO businesskyc_mail_alert (date) VALUES (TO_DATE(v_currentdate, 'DD-MM-YYYY'));
  RETURN QUERY SELECT * FROM tmp_temp2;
  DROP TABLE IF EXISTS tmp_temp2;
  END IF;
  END IF;
  IF (0 <> 0) THEN
  -- ROLLBACK (removed)
  DROP TABLE IF EXISTS tmp_temp2;
  RETURN;
  END IF;
  -- COMMIT (removed)
END;
$$;


