--
-- Name: usp_autoupdation_reseller_commission(character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_autoupdation_reseller_commission(INOUT v_strprocessoutput character varying) RETURNS character varying
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_count INT;
  v_totalcount INT;
  v_transactionid VARCHAR(100);
  v_did INT;
  v_gstpercentage DECIMAL(18,2);
  v_invoiceno Varchar(100);
  v_currentyear int;
  v_lastyear INT;
  v_invoicecode VARCHAR(100);
  v_countno INT;
  v_companyname VARCHAR(100);
  v_countnumber VARCHAR(100);
BEGIN
  -- BEGIN TRAN (removed)
  -- SET option (removed)
  v_count := 1;
  v_totalcount := 0;
  v_transactionid := '';
  v_did := 0;
  v_gstpercentage := 0;
  v_invoiceno := '';
  v_currentyear := 0;
  v_lastyear := 0;
  v_invoicecode := '';
  v_countno := 0;
  v_companyname := '';
  v_countnumber := '';
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp (ROWNUMBER INT GENERATED BY DEFAULT AS IDENTITY,
  TRCWID INT,
  DID INT,
  TRANSACTIONID varchar(100)) ON COMMIT DROP;
  INSERT INTO tmp_temp (trcwid, did, transactionid) SELECT trcwid, did, traceno FROM tbl_reseller_commission_wallet WHERE finalupdate = 0;
  SELECT COALESCE(limits, 0) INTO v_gstpercentage FROM settings WHERE caption = 'GST PERCENTAGE';
  SELECT COUNT(1) INTO v_totalcount FROM tmp_temp;
  WHILE (v_totalcount >= v_count) LOOP
  SELECT transactionid, did INTO v_transactionid, v_did FROM tmp_temp WHERE rownumber = v_count;
  SELECT COALESCE(companyname, '') INTO v_companyname FROM distributor_master WHERE plid = v_did;
  SELECT dbo.UDF_FIRST_LETTER_FROM_WORD(v_companyname) INTO v_invoicecode;
  SELECT EXTRACT(YEAR FROM CAST(dbo.FUN_GETCURRENTDATE() AS DATE)) INTO v_currentyear;
  v_lastyear := v_currentyear + 1;
  v_lastyear := RIGHT(CAST(v_lastyear AS TEXT), 2);
  SELECT COALESCE(invoiceno, 0) INTO v_countno FROM tbl_reseller_commission_invoice_master WHERE did = v_did;
  v_countno := v_countno + 1;
  SELECT RIGHT(CAST('I000000' || CAST(v_countno AS VARCHAR(10)) AS TEXT), 10) INTO v_countnumber;
  v_invoiceno := UPPER(v_invoicecode) || '/' || CAST(v_currentyear AS VARCHAR) || '-' || CAST(v_lastyear AS VARCHAR) || '/' || v_countnumber;
  IF EXISTS(SELECT 1 FROM tbl_customer_prepaid_recharges WHERE transactionid = v_transactionid AND rechargestatus = 'SUCCESS' AND active = 1) THEN
  UPDATE tbl_reseller_commission_wallet SET finalupdate = 1, gstpercentage = v_gstpercentage, invoiceno = v_invoiceno WHERE traceno = v_transactionid AND servicetype = 1;
  UPDATE tbl_reseller_commission_invoice_master SET invoiceno = invoiceno + 1 WHERE did = v_did;
  ELSE
  IF EXISTS(SELECT 1 FROM tbl_customer_postpaid_recharges WHERE transactionid = v_transactionid) THEN
  UPDATE tbl_reseller_commission_wallet SET finalupdate = 1, gstpercentage = v_gstpercentage, invoiceno = v_invoiceno WHERE traceno = v_transactionid AND servicetype = 1;
  UPDATE tbl_reseller_commission_invoice_master SET invoiceno = invoiceno + 1 WHERE did = v_did;
  ELSE
  IF EXISTS(SELECT 1 FROM tbl_customer_dth_recharges WHERE transactionid = v_transactionid) THEN
  UPDATE tbl_reseller_commission_wallet SET finalupdate = 1, gstpercentage = v_gstpercentage, invoiceno = v_invoiceno WHERE traceno = v_transactionid AND servicetype = 1;
  UPDATE tbl_reseller_commission_invoice_master SET invoiceno = invoiceno + 1 WHERE did = v_did;
  ELSE
  IF EXISTS(SELECT 1 FROM tbl_customer_electricity_recharges WHERE transactionid = v_transactionid) THEN
  UPDATE tbl_reseller_commission_wallet SET finalupdate = 1, gstpercentage = v_gstpercentage, invoiceno = v_invoiceno WHERE traceno = v_transactionid AND servicetype = 1;
  UPDATE tbl_reseller_commission_invoice_master SET invoiceno = invoiceno + 1 WHERE did = v_did;
  ELSE
  IF EXISTS(SELECT 1 FROM tbl_customer_gas_recharges WHERE transactionid = v_transactionid) THEN
  UPDATE tbl_reseller_commission_wallet SET finalupdate = 1, gstpercentage = v_gstpercentage, invoiceno = v_invoiceno WHERE traceno = v_transactionid AND servicetype = 1;
  UPDATE tbl_reseller_commission_invoice_master SET invoiceno = invoiceno + 1 WHERE did = v_did;
  END IF;
  END IF;
  END IF;
  END IF;
  END IF;
  v_count := v_count + 1;
  END LOOP;
  DROP TABLE IF EXISTS tmp_temp;
  -- SET option (removed)
  -- COMMIT (removed)
END;
$$;


--
-- Name: usp_averagenoofhots_of_keyword(integer, integer, character varying, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_averagenoofhots_of_keyword(v_ctid integer DEFAULT 0, v_aid integer DEFAULT 0, v_kid character varying DEFAULT ''::character varying, INOUT v_totalnoofhits integer DEFAULT 0) RETURNS integer
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_prevyear date;
  v_prevmonth date;
  v_sumofnoofhits int;
  v_countofnoofhits int;
BEGIN
  SELECT CAST(CURRENT_TIMESTAMP AS DATE) + INTERVAL '-1 MONTH' INTO v_prevmonth;
  SELECT CAST(CAST(CURRENT_TIMESTAMP AS DATE) + INTERVAL '-1 MONTH' AS DATE) + INTERVAL '-1 YEAR' INTO v_prevyear;
  IF (v_ctid <> 0) THEN
  SELECT COALESCE(SUM(noofhits), 0) INTO v_sumofnoofhits FROM tblnumberofhitsmonthly WHERE keywordid = v_kid AND aid = v_aid AND ctid = v_ctid AND hitmonth BETWEEN v_prevyear AND v_prevmonth;
  SELECT COUNT(noofhits) INTO v_countofnoofhits FROM tblnumberofhitsmonthly WHERE keywordid = v_kid AND aid = v_aid AND ctid = v_ctid AND hitmonth BETWEEN v_prevyear AND v_prevmonth;
  END IF;
  IF (v_countofnoofhits = 0) THEN
  v_totalnoofhits := 0;
  ELSE
  v_totalnoofhits := v_sumofnoofhits / v_countofnoofhits;
  END IF;
END;
$$;


--
-- Name: usp_billingaddfundsdetailwithslid(character varying, character varying, character varying, character varying, character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_billingaddfundsdetailwithslid(v_slid character varying DEFAULT ''::character varying, v_datefrom character varying DEFAULT ''::character varying, v_dateto character varying DEFAULT ''::character varying, v_paymenttype character varying DEFAULT ''::character varying, v_shortby character varying DEFAULT ''::character varying) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_query text;
BEGIN
  v_query := '';
  v_query := 'select ROW_NUMBER() over(order by sf.sfdid desc) as rownumber,sf.sfdid,sf.plid,sf.Billid,(select currencysymbol
from tbl_currencymaster where cid=smd.cid) as currencysymbol,smd.loginid,(smd.fname+'' ''+smd.lname) as Name,sf.DepositDate,
sf.DepositAmount,sf.PaymentType,sf.status,(case when sf.checkstatus is null then ' || CAST(0 AS VARCHAR(10)) || ' else sf.checkstatus end)as checkstatus,
(case when sf.check_sno is null then ' || CAST(0 AS VARCHAR(10)) || ' else sf.check_sno end)as check_sno
,(case when sf.Billid is null then ' || CAST(0 AS VARCHAR(10)) || ' else sf.Billid end)as Billid from tbl_sponserfunddetails sf join
 Portal_Login smd on sf.plid=smd.plid where status=0 and PaymentType!=''manual'' and PaymentType!=''Coupon'' and PaymentType!=''ewallet''';
  IF (v_datefrom <> '' AND v_dateto <> '') THEN
  v_query := v_query || ' and sf.DepositDate between ''' || CAST(v_datefrom AS VARCHAR(200)) || ''' and ''' || CAST(v_dateto AS VARCHAR(200)) || '''';
  ELSE
  IF (v_datefrom <> '') THEN
  v_query := v_query || ' and sfDepositDate >= ''' || CAST(v_datefrom AS VARCHAR(200)) || '''';
  END IF;
  END IF;
  IF (v_paymenttype <> '') THEN
  v_query := v_query || ' and sf.PaymentType= ''' || CAST(v_paymenttype AS VARCHAR(200)) || '''';
  END IF;
  IF (v_slid <> '' AND v_slid <> '0') THEN
  v_query := v_query || ' and sf.plid=' || CAST(v_slid AS VARCHAR(10)) || '';
  END IF;
  IF (v_shortby <> '') THEN
  v_query := v_query || ' order by sf.DepositAmount ' || v_shortby || '';
  END IF;
  EXECUTE v_query;
END;
$$;


