  v_maincatid int;
  v_catid int;
  v_subcatid int;
BEGIN
  -- BEGIN TRAN (removed)
  -- SET option (removed)
  v_count := 1;
  IF (v_mode = 1) THEN
  DROP TABLE IF EXISTS tmp_maincattemp;
  CREATE TEMP TABLE tmp_maincattemp ON COMMIT DROP AS SELECT ROW_NUMBER() OVER (ORDER BY maincatid NULLS FIRST) AS rownumber, maincatid, maincatname, status, main_cat_code, COALESCE(main_cat_imgname, '') AS main_cat_imgname, sequence, COALESCE(admincharge, 0) AS admincharge, imagename, isdelete, ishot_links, ishot_menu, ishot_withitem, 0 AS totalproduct FROM tbl_main_category WHERE status = 1 AND isdelete = 0;
  SELECT COUNT(*) INTO v_total FROM tmp_maincattemp;
  WHILE (v_total >= v_count) LOOP
  SELECT maincatid INTO v_maincatid FROM tmp_maincattemp WHERE rownumber = v_count;
  SELECT v_totalcount INTO v_totalproduct FROM dbo.usp_totalproducts(v_maincatid => v_maincatid, v_catid => 0, v_subcatid => 0, v_totalcount => v_totalproduct);
  UPDATE tmp_maincattemp SET totalproduct = v_totalproduct WHERE rownumber = v_count;
  v_count := v_count + 1;
  END LOOP;
  RETURN QUERY SELECT maincatid, maincatname, status, main_cat_code, main_cat_imgname, sequence, admincharge, imagename, isdelete, ishot_links, ishot_menu, ishot_withitem, totalproduct FROM tmp_maincattemp ORDER BY sequence ASC NULLS FIRST;
  DROP TABLE IF EXISTS tmp_maincattemp;
  END IF;
  IF (v_mode = 2) THEN
  DROP TABLE IF EXISTS tmp_maincattemp1;
  CREATE TEMP TABLE tmp_maincattemp1 ON COMMIT DROP AS SELECT ROW_NUMBER() OVER (ORDER BY catid NULLS FIRST) AS rownumber, catid, maincatid, catname, status, cat_code, cat_imgname, sequence, admincharge, delieverycharge, handlingcharge, isdelete, ishot_links, ishot_menu, ishot_withitem, 0 AS totalproduct FROM tbl_category WHERE status = 1 AND isdelete = 0;
  SELECT COUNT(1) INTO v_total FROM tmp_maincattemp1;
  WHILE (v_total >= v_count) LOOP
  SELECT maincatid, catid INTO v_maincatid, v_catid FROM tmp_maincattemp1 WHERE rownumber = v_count;
  SELECT v_totalcount INTO v_totalproduct FROM dbo.usp_totalproducts(v_maincatid => v_maincatid, v_catid => v_catid, v_subcatid => 0, v_totalcount => v_totalproduct);
  UPDATE tmp_maincattemp1 SET totalproduct = v_totalproduct WHERE rownumber = v_count;
  v_count := v_count + 1;
  END LOOP;
  RETURN QUERY SELECT catid, maincatid, catname, status, cat_code, COALESCE(cat_imgname, '') AS cat_imgname, sequence, admincharge, delieverycharge, handlingcharge, isdelete, ishot_links, ishot_menu, ishot_withitem, totalproduct FROM tmp_maincattemp1 ORDER BY sequence ASC NULLS FIRST;
  DROP TABLE IF EXISTS tmp_maincattemp1;
  END IF;
  IF (v_mode = 3) THEN
  DROP TABLE IF EXISTS tmp_maincattemp2;
  CREATE TEMP TABLE tmp_maincattemp2 ON COMMIT DROP AS SELECT ROW_NUMBER() OVER (ORDER BY subcatid NULLS FIRST) AS rownumber, subcatid, catid, maincatid, subcatname, status, sub_cat_code, sub_cat_imgname, sequence, admincharge, isdelete, ishot_links, ishot_menu, ishot_withitem, 0 AS totalproduct FROM tbl_sub_category WHERE status = 1 AND isdelete = 0;
  SELECT COUNT(1) INTO v_total FROM tmp_maincattemp2;
  WHILE (v_total >= v_count) LOOP
  SELECT maincatid, catid, subcatid INTO v_maincatid, v_catid, v_subcatid FROM tmp_maincattemp2 WHERE rownumber = v_count;
  SELECT v_totalcount INTO v_totalproduct FROM dbo.usp_totalproducts(v_maincatid => v_maincatid, v_catid => v_catid, v_subcatid => v_subcatid, v_totalcount => v_totalproduct);
  UPDATE tmp_maincattemp2 SET totalproduct = v_totalproduct WHERE rownumber = v_count;
  v_count := v_count + 1;
  END LOOP;
  RETURN QUERY SELECT subcatid, catid, maincatid, subcatname, status, sub_cat_code, sub_cat_imgname, sequence, admincharge, isdelete, ishot_links, ishot_menu, ishot_withitem, totalproduct FROM tmp_maincattemp2 ORDER BY subcatid ASC NULLS FIRST;
