--

CREATE FUNCTION dbo.usp_bindadvertisement(v_cid integer DEFAULT 0, v_keywordid integer DEFAULT 0, v_catid integer DEFAULT 0, v_ctid integer DEFAULT 0) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_strquery text;
BEGIN
  -- SET option (removed)
  v_strquery := '';
  IF (v_keywordid <> 0 AND v_catid = 0 AND v_ctid <> 0) THEN
  v_strquery := 'select Top 4 (imagename) as imagename,destinationurl,smcid,pageref,pagelocation from 
               tbl_sponsor_master_campain spm   where adtype=1  and campactive=1
	           and smcid IN(select distinct(smcid) as smcid from tbl_sponsor_search 
               where searchactive=1 and keyid=' || CAST(v_keywordid AS VARCHAR(10)) || '';
  END IF;
  IF (v_keywordid <> 0 AND v_catid = 0 AND v_ctid = 0) THEN
  v_strquery := 'select Top 4 (imagename) as imagename,destinationurl,smcid,pageref,pagelocation from 
               tbl_sponsor_master_campain spm   where adtype=1  and campactive=1 
	           and smcid IN(select distinct(smcid) as smcid from tbl_sponsor_search 
               where searchactive=1 and keyid=' || CAST(v_keywordid AS VARCHAR(10)) || ')';
  END IF;
  IF (v_ctid <> 0 AND v_cid <> 0 AND (v_keywordid <> 0 OR v_catid <> 0)) THEN
  IF EXISTS(SELECT smcid FROM tbl_sponsor_search WHERE cid = v_cid AND keyid = v_keywordid AND cidforallcity = 1) THEN
  v_strquery := v_strquery || ' and ctid=' || CAST(v_ctid AS VARCHAR(10)) || ' union all select distinct(smcid) as smcid from tbl_sponsor_search where searchactive=1 
					and keyid=' || CAST(v_keywordid AS VARCHAR(10)) || ' and cid=' || CAST(v_cid AS VARCHAR(10)) || ' and cidforallcity=1) ORDER BY newid()';
  ELSE
  v_strquery := v_strquery || ' and ctid=' || CAST(v_ctid AS VARCHAR(10)) || ') ORDER BY newid()';
  END IF;
  END IF;
  EXECUTE v_strquery;
  -- SET option (removed)
END;
$$;


