--
-- Name: usp_bindadvertisementfortext_new(integer, integer, text, integer, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_bindadvertisementfortext_new(v_keywordid integer DEFAULT 0, v_catid integer DEFAULT 0, v_ctid text DEFAULT ''::text, v_cid integer DEFAULT 0, v_plid integer DEFAULT 0) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_totalrowcount bigint;
  v_startwhile bigint;
BEGIN
  -- SET option (removed)
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp (intid int GENERATED BY DEFAULT AS IDENTITY,
randaum varchar(100),
smcid int,
bid_price numeric(19,4),
imagename text,
descriptionline1 text,
destinationurl text,
Current_Amount numeric(19,4),
ctid text,
key_sp_id bigint,
keywordid bigint,
budjetperday numeric(19,4)) ON COMMIT DROP;
  IF (v_ctid = '0') THEN
  v_ctid := '';
  END IF;
  IF (v_keywordid = 0) THEN
  IF (v_ctid = '') THEN
  INSERT INTO tmp_temp SELECT '', ks.smcid, bid_price, sm.imagename, sm.descriptionline1, sm.destinationurl, e.current_amount, sm.ctid, ks.key_sp_id, ks.keywordid, sm.budjetperday FROM tbl_keyword_in_sponsorad AS ks INNER JOIN tbl_sponsor_master_campain AS sm ON sm.smcid = ks.smcid INNER JOIN product_category AS pc ON pc.catid = ks.catid INNER JOIN tbl_adsewallet AS e ON e.plid = sm.plid INNER JOIN sponsor_master_detail AS smd ON smd.smdid = sm.smid WHERE sm.cid = v_cid AND ks.status = 1 AND ks.keywordid = 0 AND ks.catid = v_catid AND sm.campactive = 1 AND pc.catactive = 1 AND ks.bid_price < e.current_amount AND sm.ctid = '0' AND COALESCE(isblock, 0) = 0;
  END IF;
  IF (v_ctid <> '') THEN
  INSERT INTO tmp_temp SELECT '', ks.smcid, bid_price, sm.imagename, sm.descriptionline1, sm.destinationurl, e.current_amount, sm.ctid, ks.key_sp_id, ks.keywordid, sm.budjetperday FROM tbl_keyword_in_sponsorad AS ks INNER JOIN tbl_sponsor_master_campain AS sm ON sm.smcid = ks.smcid INNER JOIN product_category AS pc ON pc.catid = ks.catid INNER JOIN tbl_adsewallet AS e ON e.plid = sm.plid INNER JOIN sponsor_master_detail AS smd ON smd.smdid = sm.smid WHERE sm.cid = v_cid AND ks.status = 1 AND ks.keywordid = 0 AND ks.catid = v_catid AND sm.campactive = 1 AND pc.catactive = 1 AND ks.bid_price < e.current_amount AND ',' || sm.ctid || ',' LIKE '%' || v_ctid || '%' AND COALESCE(isblock, 0) = 0;
  END IF;
  ELSE
  IF (v_ctid = '') THEN
  INSERT INTO tmp_temp SELECT '', ks.smcid, bid_price, sm.imagename, sm.descriptionline1, sm.destinationurl, e.current_amount, sm.ctid, ks.key_sp_id, ks.keywordid, sm.budjetperday FROM tbl_keyword_in_sponsorad AS ks INNER JOIN tbl_sponsor_master_campain AS sm ON sm.smcid = ks.smcid INNER JOIN keyword_master AS km ON km.kmid = ks.keywordid INNER JOIN tbl_adsewallet AS e ON e.plid = sm.plid INNER JOIN sponsor_master_detail AS smd ON smd.smdid = sm.smid WHERE sm.cid = v_cid AND ks.keywordid = v_keywordid AND ks.status = 1 AND sm.campactive = 1 AND km.kactive = 1 AND ks.bid_price < e.current_amount AND sm.ctid = '0' AND COALESCE(isblock, 0) = 0;
  END IF;
  IF (v_ctid <> '') THEN
  INSERT INTO tmp_temp SELECT '', ks.smcid, bid_price, sm.imagename, sm.descriptionline1, sm.destinationurl, e.current_amount, sm.ctid, ks.key_sp_id, ks.keywordid, sm.budjetperday FROM tbl_keyword_in_sponsorad AS ks INNER JOIN tbl_sponsor_master_campain AS sm ON sm.smcid = ks.smcid INNER JOIN keyword_master AS km ON km.kmid = ks.keywordid INNER JOIN tbl_adsewallet AS e ON e.plid = sm.plid INNER JOIN sponsor_master_detail AS smd ON smd.smdid = sm.smid WHERE sm.cid = v_cid AND ks.keywordid = v_keywordid AND ks.status = 1 AND sm.campactive = 1 AND km.kactive = 1 AND ks.bid_price < e.current_amount AND ',' || sm.ctid || ',' LIKE '%' || v_ctid || '%' AND COALESCE(isblock, 0) = 0;
  END IF;
  END IF;
  SELECT COUNT(*) INTO v_totalrowcount FROM tmp_temp;
  v_startwhile := 0;
  WHILE (v_startwhile < v_totalrowcount) LOOP
  UPDATE tmp_temp SET randaum = (SELECT RANDOM()) WHERE intid = v_startwhile + 1;
  v_startwhile := v_startwhile + 1;
  END LOOP;
  RETURN QUERY SELECT randaum, t.smcid, t.bid_price, t.imagename, t.descriptionline1, t.destinationurl, t.current_amount, t.key_sp_id, budjetperday, (SELECT COALESCE(SUM(bid_price), 0) FROM tbl_hitsonsponsorads WHERE smcid = t.smcid AND CAST(hitdate AS DATE) = CAST(dbo.fun_getCurrentDate() AS DATE)) AS bid_priceperday FROM tmp_temp AS t WHERE t.budjetperday > (SELECT COALESCE(SUM(bid_price), 0) FROM tbl_hitsonsponsorads WHERE smcid = t.smcid AND CAST(hitdate AS DATE) = CAST(dbo.fun_getCurrentDate() AS DATE)) ORDER BY t.bid_price DESC NULLS LAST, t.randaum ASC NULLS FIRST LIMIT 10;
  -- SET option (removed)
END;
$$;


--
-- Name: usp_bindadvertisementfortext_new1(integer, integer, text, integer, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_bindadvertisementfortext_new1(v_keywordid integer DEFAULT 0, v_catid integer DEFAULT 0, v_ctid text DEFAULT ''::text, v_cid integer DEFAULT 0, v_plid integer DEFAULT 0) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_citids text;
BEGIN
  -- SET option (removed)
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp (intid int GENERATED BY DEFAULT AS IDENTITY,
smcid int,
bid_price numeric(19,4),
imagename text,
descriptionline1 text,
destinationurl text,
Current_Amount numeric(19,4),
ctid text,
key_sp_id bigint,
keywordid bigint,
budjetperday numeric(19,4)) ON COMMIT DROP;
  IF (v_ctid = '0') THEN
  v_ctid := '';
  END IF;
  IF (v_keywordid = 0) THEN
  INSERT INTO tmp_temp SELECT ks.smcid, bid_price, sm.imagename, sm.descriptionline1, sm.destinationurl, e.current_amount, sm.ctid, ks.key_sp_id, ks.keywordid, sm.budjetperday FROM tbl_keyword_in_sponsorad AS ks INNER JOIN tbl_sponsor_master_campain AS sm ON sm.smcid = ks.smcid INNER JOIN product_category AS pc ON pc.catid = ks.catid INNER JOIN tbl_adsewallet AS e ON e.plid = sm.plid WHERE sm.cid = v_cid AND ks.status = 1 AND ks.keywordid = 0 AND sm.campactive = 1 AND pc.catactive = 1 AND ks.bid_price < e.current_amount;
  ELSE
  INSERT INTO tmp_temp SELECT ks.smcid, bid_price, sm.imagename, sm.descriptionline1, sm.destinationurl, e.current_amount, sm.ctid, ks.key_sp_id, ks.keywordid, sm.budjetperday FROM tbl_keyword_in_sponsorad AS ks INNER JOIN tbl_sponsor_master_campain AS sm ON sm.smcid = ks.smcid INNER JOIN keyword_master AS km ON km.kmid = ks.keywordid INNER JOIN tbl_adsewallet AS e ON e.plid = sm.plid WHERE sm.cid = v_cid AND ks.keywordid = v_keywordid AND ks.status = 1 AND sm.campactive = 1 AND km.kactive = 1 AND ks.bid_price < e.current_amount;
  END IF;
  IF (v_ctid = '') THEN
  RETURN QUERY SELECT t.smcid, t.bid_price, t.imagename, t.descriptionline1, t.destinationurl, t.current_amount, t.key_sp_id, budjetperday, (SELECT COALESCE(SUM(bid_price), 0) FROM tbl_hitsonsponsorads WHERE smcid = t.smcid AND CAST(hitdate AS DATE) = CAST(dbo.fun_getCurrentDate() AS DATE)) AS bid_priceperday FROM tmp_temp AS t WHERE t.budjetperday > (SELECT COALESCE(SUM(bid_price), 0) FROM tbl_hitsonsponsorads WHERE smcid = t.smcid AND CAST(hitdate AS DATE) = CAST(dbo.fun_getCurrentDate() AS DATE)) ORDER BY t.bid_price DESC NULLS LAST LIMIT 10;
  ELSE
  v_citids := v_ctid;
  RETURN QUERY SELECT t.smcid, t.bid_price, t.imagename, t.descriptionline1, t.destinationurl, t.current_amount, t.key_sp_id, budjetperday, (SELECT COALESCE(SUM(bid_price), 0) FROM tbl_hitsonsponsorads WHERE smcid = t.smcid AND CAST(hitdate AS DATE) = CAST(dbo.fun_getCurrentDate() AS DATE)) AS bid_priceperday FROM tmp_temp AS t WHERE t.ctid LIKE '%' || v_citids || '%' AND t.budjetperday > (SELECT COALESCE(SUM(bid_price), 0) FROM tbl_hitsonsponsorads WHERE smcid = t.smcid AND CAST(hitdate AS DATE) = CAST(dbo.fun_getCurrentDate() AS DATE)) ORDER BY t.bid_price DESC NULLS LAST LIMIT 10;
  END IF;
  -- SET option (removed)
END;
$$;


--
-- Name: usp_bindcatandkey(integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_bindcatandkey(v_plid integer DEFAULT 0) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_merchantrelatedto Int;
BEGIN
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp (ROWNUMBER INT GENERATED BY DEFAULT AS IDENTITY,  
  
 PRODUCTNAME VARCHAR(250),  
  
 PRODUCTTYPE CHAR,  
  
 CATID INT,  
  
 SCATID INT,  
  
 KMID INT) ON COMMIT DROP;
  v_merchantrelatedto := 0;
  SELECT merchantrelatedto INTO v_merchantrelatedto FROM portal_login WHERE plid = v_plid;
  INSERT INTO tmp_temp (productname, producttype, catid, scatid, kmid) SELECT LOWER(catname), 'C', catid, 0, 0 FROM product_category WHERE catactive = 1 AND categoryrelatedto = v_merchantrelatedto;
  INSERT INTO tmp_temp (productname, producttype, catid, scatid, kmid) SELECT LOWER(scatname), 'S', catid, scatid, 0 FROM product_subcategory WHERE scatactive = 1;
  INSERT INTO tmp_temp (productname, producttype, catid, scatid, kmid) SELECT LOWER(keywordname), 'K', catid, scatid, kmid FROM keyword_master WHERE kactive = 1;
  RETURN QUERY SELECT productname, producttype, (CASE WHEN producttype = 'C' THEN catid WHEN producttype = 'S' THEN scatid WHEN producttype = 'K' THEN kmid END) AS prid, catid, scatid, kmid FROM tmp_temp ORDER BY catid NULLS FIRST, producttype ASC NULLS FIRST;
  DROP TABLE IF EXISTS tmp_temp;
END;
$$;


--
-- Name: usp_bindcheckboxnoofhits(integer, text); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_bindcheckboxnoofhits(v_countryidd integer DEFAULT 0, v_cityid text DEFAULT ''::text) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_slice1 text;
  v_slice3 text;
  v_index1 INT;
  v_index2 INT;
  v_slice2 text;
  v_slice4 text;
  v_keywordid text;
  v_sid int;
  v_cid int;
  v_catid int;
  v_totalnoofhits int;
  v_noofhits int;
  v_keyword varchar(200);
  v_kmid int;
  v_limits numeric(19,4);
  v_currencysymbol varchar(50);
  v_cpc numeric(19,4);
BEGIN
  v_keywordid := '';
  v_sid := 0;
  v_cid := 0;
  v_catid := 0;
  v_totalnoofhits := 0;
  v_noofhits := 0;
  v_limits := 0;
  v_currencysymbol := '';
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp (totalnoofhits bigint,



keywordname varchar(100),



kmid int,



catid int,



cpc numeric(19,4)) ON COMMIT DROP;
  -- SET option (removed)
  IF (v_countryidd <> 0) THEN
  SELECT COALESCE(v_keywordid || ', ', '') || CAST(kmid AS VARCHAR(15)) INTO v_keywordid FROM keyword_master;
  SELECT SUBSTRING(v_keywordid FROM 2 FOR (LENGTH(CAST(v_keywordid AS TEXT)))) INTO v_slice1;
  v_index1 := 1;
  WHILE v_index1 <> 0 LOOP
  SELECT POSITION(',' IN v_slice1) INTO v_index1;
  IF v_index1 <> 0 THEN
  SELECT LEFT(CAST(v_slice1 AS TEXT), v_index1 - 1) INTO v_slice2;
  ELSE
  SELECT v_slice1 INTO v_slice2;
  END IF;
  v_noofhits := 0;
  SELECT COALESCE(SUM(noofhits), 0) INTO v_noofhits FROM tblnumberofhits WHERE keywordid = v_slice2;
  SELECT keywordname INTO v_keyword FROM keyword_master WHERE kmid = v_slice2;
  SELECT catid INTO v_catid FROM keyword_master WHERE kmid = v_slice2;
  SELECT cpc INTO v_cpc FROM tbl_cpcforcatergory WHERE catid = v_catid AND cid = v_countryidd;
  INSERT INTO tmp_temp (totalnoofhits, kmid, keywordname, catid, cpc) VALUES (v_noofhits, v_slice2, v_keyword, v_catid, v_cpc);
  v_keyword := 0;
  SELECT 0 INTO v_catid;
  SELECT 0 INTO v_cpc;
  IF (0 <> 0) THEN
  -- ROLLBACK (removed)
  RETURN;
  END IF;
  SELECT RIGHT(CAST(v_slice1 AS TEXT), LENGTH(CAST(v_slice1 AS TEXT)) - v_index1) INTO v_slice1;
  IF LENGTH(CAST(v_slice1 AS TEXT)) = 0 THEN
  EXIT;
  END IF;
  END LOOP;
  ELSE
  SELECT COALESCE(v_keywordid || ', ', '') || CAST(kmid AS VARCHAR(15)) INTO v_keywordid FROM keyword_master;
  SELECT SUBSTRING(v_keywordid FROM 2 FOR (LENGTH(CAST(v_keywordid AS TEXT)))) INTO v_slice1;
  v_index1 := 1;
  WHILE v_index1 <> 0 LOOP
  SELECT POSITION(',' IN v_slice1) INTO v_index1;
  IF v_index1 <> 0 THEN
  SELECT LEFT(CAST(v_slice1 AS TEXT), v_index1 - 1) INTO v_slice2;
  ELSE
  SELECT v_slice1 INTO v_slice2;
  END IF;
  v_index2 := 1;
  v_slice3 := v_cityid;
  v_totalnoofhits := 0;
  WHILE v_index2 <> 0 LOOP
  SELECT POSITION(',' IN v_slice3) INTO v_index2;
  IF v_index2 <> 0 THEN
  SELECT LEFT(CAST(v_slice3 AS TEXT), v_index2 - 1) INTO v_slice4;
  ELSE
  SELECT v_slice3 INTO v_slice4;
  END IF;
  SELECT SUM(noofhits) INTO v_noofhits FROM tblnumberofhits WHERE keywordid = v_slice2 AND ctid = v_slice4 AND aid = 0;
  SELECT cid INTO v_cid FROM city WHERE ctid = v_slice2;
  v_noofhits := COALESCE(v_noofhits, 0);
  v_totalnoofhits := v_totalnoofhits + v_noofhits;
  v_noofhits := 0;
  IF (0 <> 0) THEN
  -- ROLLBACK (removed)
  RETURN;
  END IF;
  SELECT RIGHT(CAST(v_slice3 AS TEXT), LENGTH(CAST(v_slice3 AS TEXT)) - v_index2) INTO v_slice3;
  IF LENGTH(CAST(v_slice3 AS TEXT)) = 0 THEN
  EXIT;
  END IF;
  END LOOP;
  SELECT keywordname INTO v_keyword FROM keyword_master WHERE kmid = v_slice2;
  SELECT catid INTO v_catid FROM keyword_master WHERE kmid = v_slice2;
  SELECT cpc INTO v_cpc FROM tbl_cpcforcatergory WHERE catid = v_catid AND cid = v_cid;
  INSERT INTO tmp_temp (totalnoofhits, kmid, keywordname, catid, cpc) VALUES (v_totalnoofhits, v_slice2, v_keyword, v_catid, v_cpc);
  v_keyword := 0;
  SELECT 0 INTO v_catid;
  SELECT 0 INTO v_cpc;
  IF (0 <> 0) THEN
  -- ROLLBACK (removed)
  RETURN;
  END IF;
  SELECT RIGHT(CAST(v_slice1 AS TEXT), LENGTH(CAST(v_slice1 AS TEXT)) - v_index1) INTO v_slice1;
  IF LENGTH(CAST(v_slice1 AS TEXT)) = 0 THEN
  EXIT;
  END IF;
  END LOOP;
  -- SET option (removed)
  END IF;
  IF (v_countryidd <> 0) THEN
  SELECT currencysymbol INTO v_currencysymbol FROM tbl_currencymaster WHERE cid = v_countryidd;
  ELSE
  SELECT currencysymbol INTO v_currencysymbol FROM tbl_currencymaster WHERE cid = v_cid;
  END IF;
  RETURN QUERY SELECT CONCAT(km.keywordname, ' <span class="noofclick" style="display:none"> (No. of Click ', COALESCE(t.totalnoofhits, 0), ' , C.P.C ', v_currencysymbol, ' ', COALESCE(t.cpc, 0.00), ') </span>') AS keywordname, km.kmid, km.catid FROM keyword_master AS km INNER JOIN tmp_temp AS t ON t.kmid = km.kmid WHERE km.kactive = 1 ORDER BY keywordname ASC NULLS FIRST;
END;
$$;


--
-- Name: usp_bindcheckboxnoofhitsdemo(integer, text, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_bindcheckboxnoofhitsdemo(v_countryid integer DEFAULT 0, v_cityid text DEFAULT ''::text, v_keywordid integer DEFAULT 0) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_slice1 text;
  v_slice3 text;
  v_index1 INT;
  v_index2 INT;
  v_slice2 text;
  v_slice4 text;
  v_sid int;
  v_cid int;
  v_catid int;
  v_totalnoofhits int;
  v_noofhits int;
  v_keyword varchar(200);
  v_kmid int;
  v_limits numeric(19,4);
  v_currencysymbol varchar(50);
  v_cpc numeric(19,4);
BEGIN
  v_sid := 0;
  v_cid := 0;
  v_catid := 0;
  v_totalnoofhits := 0;
  v_noofhits := 0;
  v_limits := 0;
  v_currencysymbol := '';
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp (totalnoofhits bigint,



keywordname varchar(100),



kmid int,



catid int,



cpc numeric(19,4)) ON COMMIT DROP;
  -- SET option (removed)
  IF (v_countryid <> 0) THEN
  SELECT SUM(noofhits) INTO v_noofhits FROM tblnumberofhits WHERE keywordid = v_keywordid AND cid = v_countryid;
  v_totalnoofhits := COALESCE(v_totalnoofhits, 0) + COALESCE(v_noofhits, 0);
  SELECT keywordname INTO v_keyword FROM keyword_master WHERE kmid = v_keywordid;
  SELECT catid INTO v_catid FROM keyword_master WHERE kmid = v_keywordid;
  SELECT cpc INTO v_cpc FROM tbl_cpcforcatergory WHERE catid = v_catid AND cid = v_countryid;
  INSERT INTO tmp_temp (totalnoofhits, kmid, keywordname, catid, cpc) VALUES (v_totalnoofhits, v_keywordid, v_keyword, v_catid, v_cpc);
  IF (0 <> 0) THEN
  -- ROLLBACK (removed)
  RETURN;
  END IF;
  ELSE
  v_index2 := 1;
  v_slice3 := v_cityid;
  v_totalnoofhits := 0;
  WHILE v_index2 <> 0 LOOP
  SELECT POSITION(',' IN v_slice3) INTO v_index2;
  IF v_index2 <> 0 THEN
  SELECT LEFT(CAST(v_slice3 AS TEXT), v_index2 - 1) INTO v_slice4;
  ELSE
  SELECT v_slice3 INTO v_slice4;
  END IF;
  SELECT SUM(noofhits) INTO v_noofhits FROM tblnumberofhits WHERE keywordid = v_keywordid AND ctid = v_slice4 AND aid = 0;
  SELECT cid INTO v_cid FROM city WHERE ctid = v_slice4;
  v_noofhits := COALESCE(v_noofhits, 0);
  v_totalnoofhits := v_totalnoofhits + v_noofhits;
  v_noofhits := 0;
  IF (0 <> 0) THEN
  -- ROLLBACK (removed)
  RETURN;
  END IF;
  SELECT RIGHT(CAST(v_slice3 AS TEXT), LENGTH(CAST(v_slice3 AS TEXT)) - v_index2) INTO v_slice3;
  IF LENGTH(CAST(v_slice3 AS TEXT)) = 0 THEN
  EXIT;
  END IF;
  END LOOP;
  SELECT keywordname INTO v_keyword FROM keyword_master WHERE kmid = v_keywordid;
  SELECT catid INTO v_catid FROM keyword_master WHERE kmid = v_keywordid;
  SELECT cpc INTO v_cpc FROM tbl_cpcforcatergory WHERE catid = v_catid AND cid = v_cid;
  INSERT INTO tmp_temp (totalnoofhits, kmid, keywordname, catid, cpc) VALUES (v_totalnoofhits, v_keywordid, v_keyword, v_catid, v_cpc);
  v_keyword := 0;
  SELECT 0 INTO v_catid;
  SELECT 0 INTO v_cpc;
  IF (0 <> 0) THEN
  -- ROLLBACK (removed)
  RETURN;
  END IF;
  -- SET option (removed)
  END IF;
  IF (v_countryid = 0) THEN
  SELECT currencysymbol INTO v_currencysymbol FROM tbl_currencymaster WHERE cid = v_cid;
  ELSE
  SELECT currencysymbol INTO v_currencysymbol FROM tbl_currencymaster WHERE cid = v_countryid;
  END IF;
  RETURN QUERY SELECT CONCAT(km.keywordname, ' (No. of Click ', COALESCE(t.totalnoofhits, 0), ' , C.P.C ', v_currencysymbol, ' ', COALESCE(t.cpc, 0), ')') AS keywordname, km.kmid, km.catid FROM keyword_master AS km INNER JOIN tmp_temp AS t ON t.kmid = km.kmid WHERE km.kactive = 1;
END;
$$;


--
-- Name: usp_bindcountry(bigint); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_bindcountry(v_plid bigint DEFAULT 3) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
BEGIN
  RETURN QUERY SELECT c.cid, c.countryname FROM country AS c JOIN tbl_customerlogin AS pl ON pl.cid = c.cid WHERE pl.clid = v_plid;
END;
$$;


--
-- Name: usp_bindcountry_customer(bigint); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_bindcountry_customer(v_plid bigint DEFAULT 6) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF (v_plid <> 0) THEN
  RETURN QUERY SELECT c.cid, c.countryname, c.isdcode FROM country AS c WHERE c.cid = v_plid;
  ELSE
  RETURN QUERY SELECT c.cid, c.countryname, c.isdcode FROM country AS c;
  END IF;
END;
$$;


--
-- Name: usp_binddashboard(integer, integer, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_binddashboard(v_did integer DEFAULT 8, v_mode integer DEFAULT 2, v_ticketstatus integer DEFAULT 0) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_totalcredited DECIMAL(18,8);
  v_withdrwal DECIMAL(18,8);
  v_balance DECIMAL(18,8);
  v_totalutilitiespurchase DECIMAL(18,8);
  v_totalproductcost DECIMAL(18,8);
  v_dt timestamp;
BEGIN
  IF (v_mode = 1) THEN
  v_totalcredited := 0.00;
  v_withdrwal := 0.00;
  v_balance := 0.00;
  SELECT COALESCE(SUM(amount), 0) INTO v_withdrwal FROM tbl_reseller_transfertobank_request WHERE transferrequest = 0 AND status = 1 AND transferid = 1 AND did = v_did;
  SELECT v_withdrwal + COALESCE(SUM(amount), 0) INTO v_withdrwal FROM tbl_reseller_transfertobank_request WHERE status = 1 AND transferid = 2 AND did = v_did;
  SELECT COALESCE(SUM(cr), 0) INTO v_totalcredited FROM tbl_reseller_commission_wallet WHERE status = 1 AND did = v_did;
  SELECT (v_totalcredited - v_withdrwal) INTO v_balance;
  RETURN QUERY SELECT (v_totalcredited) AS totalcredited, (v_withdrwal) AS totalwithdrawal, (v_balance) AS walletbalance;
  END IF;
  IF (v_mode = 2) THEN
  DROP TABLE IF EXISTS v_tablestatus;
  CREATE TEMP TABLE v_tablestatus (ROWNUMBER INT GENERATED BY DEFAULT AS IDENTITY,  
NOOFORDERS INT,  
STATUS VARCHAR(100),  
OSID INT) ON COMMIT DROP;
  INSERT INTO v_tablestatus SELECT 0, displayname, osid FROM orderstatusmaster WHERE displayondashboard <> 0 ORDER BY displayondashboard ASC NULLS FIRST;
  DROP TABLE IF EXISTS v_table;
  CREATE TEMP TABLE v_table (ROWNUMBER INT GENERATED BY DEFAULT AS IDENTITY,  
NOOFORDERS INT,  
INTSTATUS INT) ON COMMIT DROP;
  INSERT INTO v_table SELECT COUNT(1), intstatus FROM tbl_product_order_master INNER JOIN tbl_customerlogin ON tbl_product_order_master.loginid = tbl_customerlogin.loginid WHERE tbl_customerlogin.did = v_did GROUP BY intstatus;
  UPDATE t SET nooforders = t1.nooforders FROM v_tablestatus AS t INNER JOIN v_table AS t1 ON t.osid = t1.intstatus;
  RETURN QUERY SELECT status, nooforders FROM v_tablestatus;
  END IF;
  IF (v_mode = 3) THEN
  DROP TABLE IF EXISTS v_statemaster;
  CREATE TEMP TABLE v_statemaster (ROWNUMBER INT GENERATED BY DEFAULT AS IDENTITY,  
STATENAME Varchar(100),  
SID Int,  
NOofOrder Int,  
GeoLocationDetails Varchar(100),  
SCODE  Varchar(10)) ON COMMIT DROP;
  INSERT INTO v_statemaster SELECT statename, sid, 0, geolocationdetails, scode FROM state WHERE cid = 96;
  DROP TABLE IF EXISTS v_statedata;
  CREATE TEMP TABLE v_statedata (ROWNUMBER INT GENERATED BY DEFAULT AS IDENTITY,  
SID Int,  
NOofOrder Int) ON COMMIT DROP;
  INSERT INTO v_statedata SELECT sid, COUNT(1) FROM tbl_customerlogin WHERE did = v_did GROUP BY sid;
  UPDATE t1 SET nooforder = t2.nooforder FROM v_statemaster AS t1 INNER JOIN v_statedata AS t2 ON t1.sid = t2.sid;
  RETURN QUERY SELECT statename, sid, nooforder, geolocationdetails, scode FROM v_statemaster ORDER BY nooforder DESC NULLS LAST;
  END IF;
  IF (v_mode = 4) THEN
  RETURN QUERY SELECT servicename, packagename, CAST(CAST(EXTRACT(epoch FROM CAST(CAST(purchaseddate + 365 AS TIMESTAMP) AS TIMESTAMP) - CAST(CAST(dbo.FUN_GETCURRENTDATE() AS TIMESTAMP) AS TIMESTAMP)) / 86400 AS BIGINT) AS INT) AS remaindays FROM tbl_reseller_purchased_packages INNER JOIN tbl_reseller_packages ON tbl_reseller_purchased_packages.trpid = tbl_reseller_packages.trpid INNER JOIN tbl_reseller_services ON tbl_reseller_purchased_packages.trsid = tbl_reseller_services.trsid WHERE tbl_reseller_purchased_packages.did = v_did;
  END IF;
  IF (v_mode = 5) THEN
  DROP TABLE IF EXISTS v_tempcommission;
  CREATE TEMP TABLE v_tempcommission (ROWNUMBER INT GENERATED BY DEFAULT AS IDENTITY,  
TRSID INT,  
SERVICESNAME VARCHAR(100),  
TOTALCOMMISSIONRECEIVED DECIMAL(18,8)) ON COMMIT DROP;
  INSERT INTO v_tempcommission SELECT trsid, servicename, 0 FROM tbl_reseller_services WHERE active = 1;
  DROP TABLE IF EXISTS v_tempdatacommission;
  CREATE TEMP TABLE v_tempdatacommission (AMOUNT DECIMAL(18,8),  
SERVICETYPE Int) ON COMMIT DROP;
  INSERT INTO v_tempdatacommission SELECT SUM(cr), servicetype FROM tbl_reseller_commission_wallet WHERE did = v_did GROUP BY servicetype;
  UPDATE t SET totalcommissionreceived = amount FROM v_tempcommission AS t INNER JOIN v_tempdatacommission AS t1 ON t.trsid = t1.servicetype;
  RETURN QUERY SELECT rownumber, trsid, servicesname, totalcommissionreceived FROM v_tempcommission;
  END IF;
  IF (v_mode = 6) THEN
  v_totalutilitiespurchase := 0.00;
  v_totalproductcost := 0.00;
  DROP TABLE IF EXISTS v_tempcommissionall;
  CREATE TEMP TABLE v_tempcommissionall (ROWNUMBER INT GENERATED BY DEFAULT AS IDENTITY,  
TRSID INT,  
SERVICESNAME VARCHAR(100),  
TOTALUSED DECIMAL(18,8)) ON COMMIT DROP;
  INSERT INTO v_tempcommissionall SELECT trsid, servicename, 0 FROM tbl_reseller_services;
  SELECT COALESCE(SUM(rechargeamount), 0) INTO v_totalutilitiespurchase FROM tbl_customer_prepaid_recharges INNER JOIN tbl_customerlogin ON tbl_customerlogin.clid = tbl_customer_prepaid_recharges.clid WHERE rechargestatus = 'SUCCESS' AND tbl_customerlogin.did = v_did;
  SELECT v_totalutilitiespurchase + COALESCE(SUM(rechargeamount), 0) INTO v_totalutilitiespurchase FROM tbl_customer_postpaid_recharges INNER JOIN tbl_customerlogin ON tbl_customerlogin.clid = tbl_customer_postpaid_recharges.clid WHERE rechargestatus = 'SUCCESS' AND tbl_customerlogin.did = v_did;
  SELECT v_totalutilitiespurchase + COALESCE(SUM(rechargeamount), 0) INTO v_totalutilitiespurchase FROM tbl_customer_dth_recharges INNER JOIN tbl_customerlogin ON tbl_customerlogin.clid = tbl_customer_dth_recharges.clid WHERE rechargestatus = 'SUCCESS' AND tbl_customerlogin.did = v_did;
  SELECT v_totalutilitiespurchase + COALESCE(SUM(rechargeamount), 0) INTO v_totalutilitiespurchase FROM tbl_customer_electricity_recharges INNER JOIN tbl_customerlogin ON tbl_customerlogin.clid = tbl_customer_electricity_recharges.clid WHERE rechargestatus = 'SUCCESS' AND tbl_customerlogin.did = v_did;
  SELECT v_totalutilitiespurchase + COALESCE(SUM(rechargeamount), 0) INTO v_totalutilitiespurchase FROM tbl_customer_gas_recharges INNER JOIN tbl_customerlogin ON tbl_customerlogin.clid = tbl_customer_gas_recharges.clid WHERE rechargestatus = 'SUCCESS' AND tbl_customerlogin.did = v_did;
  SELECT v_totalutilitiespurchase + COALESCE(SUM(rechargeamount), 0) INTO v_totalutilitiespurchase FROM tbl_customer_insurance_recharges INNER JOIN tbl_customerlogin ON tbl_customerlogin.clid = tbl_customer_insurance_recharges.clid WHERE rechargestatus = 'SUCCESS' AND tbl_customerlogin.did = v_did;
  SELECT COALESCE(SUM(total_purchase_cost), 0) INTO v_totalproductcost FROM tbl_product_order_master INNER JOIN tbl_customerlogin ON tbl_customerlogin.loginid = tbl_product_order_master.loginid WHERE tbl_customerlogin.did = v_did AND intstatus = 6;
  UPDATE v_tempcommissionall SET totalused = v_totalutilitiespurchase WHERE trsid = 1;
  UPDATE v_tempcommissionall SET totalused = v_totalproductcost WHERE trsid = 2;
  RETURN QUERY SELECT rownumber, trsid, servicesname, totalused FROM v_tempcommissionall;
  END IF;
  IF (v_mode = 7) THEN
  IF (v_ticketstatus <> 0) THEN
  RETURN QUERY SELECT categoryname, subject, ticketno, tmid, message, name AS statusname, imagename, clid, phone, emailid FROM tbl_ticketmaster INNER JOIN tbl_customerlogin ON tbl_ticketmaster.fromplid = tbl_customerlogin.clid INNER JOIN tbl_statusmaster ON tbl_statusmaster.id = tbl_ticketmaster.status WHERE tbl_ticketmaster.accounttype = 2 AND tbl_customerlogin.did = v_did AND tbl_ticketmaster.status = v_ticketstatus LIMIT 5;
  ELSE
  RETURN QUERY SELECT categoryname, subject, ticketno, tmid, message, name AS statusname, imagename, clid, phone, emailid FROM tbl_ticketmaster INNER JOIN tbl_customerlogin ON tbl_ticketmaster.fromplid = tbl_customerlogin.clid INNER JOIN tbl_statusmaster ON tbl_statusmaster.id = tbl_ticketmaster.status WHERE tbl_ticketmaster.accounttype = 2 AND tbl_customerlogin.did = v_did LIMIT 5;
  END IF;
  END IF;
  IF (v_mode = 8) THEN
  IF EXISTS(SELECT 1 FROM tbl_distributor_prepaid_setting INNER JOIN distributor_master ON distributor_master.pmid = tbl_distributor_prepaid_setting.pmid WHERE distributor_master.plid = v_did) THEN
  RETURN QUERY SELECT credit_wallet, used_wallet, available_wallet FROM tbl_distributor_prepaid_setting INNER JOIN distributor_master ON distributor_master.pmid = tbl_distributor_prepaid_setting.pmid WHERE distributor_master.plid = v_did;
  ELSE
  RETURN QUERY SELECT CAST(0 AS DECIMAL(18, 8)) AS credit_wallet, CAST(0 AS DECIMAL(18, 8)) AS used_wallet, CAST(0 AS DECIMAL(18, 8)) AS available_wallet;
  END IF;
  END IF;
  IF (v_mode = 9) THEN
  v_dt := CURRENT_TIMESTAMP;
  RETURN QUERY SELECT CAST(TO_CHAR('19000101' + (INTERVAL '1 DAY' * ((CAST(EXTRACT(epoch FROM CAST(CAST(v_dt AS TIMESTAMP) AS TIMESTAMP) - CAST(CAST('19000101' AS TIMESTAMP) AS TIMESTAMP)) / 86400 AS BIGINT) / 7) * 7 + 7)), 'DD TMMon YYYY') AS VARCHAR(11)) AS nextpayoutdate;
  END IF;
  IF (v_mode = 10) THEN
  RETURN QUERY SELECT COALESCE(SUM(transfertobank), 0) AS transfertobank, COALESCE(SUM(availablebalance), 0) AS availablebalance FROM tbl_customerwallet INNER JOIN tbl_customerlogin ON tbl_customerlogin.clid = tbl_customerwallet.clid WHERE tbl_customerlogin.did = v_did;
  END IF;
END;
$$;


--
-- Name: usp_bindemailidlist(integer, integer, character varying, integer, character varying, integer, integer, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_bindemailidlist(v_mode integer DEFAULT 0, v_smid integer DEFAULT 0, v_emailid character varying DEFAULT ''::character varying, v_statusid integer DEFAULT 0, v_status character varying DEFAULT ''::character varying, v_intresult integer DEFAULT 0, v_pagesize integer DEFAULT 100, v_pageno integer DEFAULT 1) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_query text;
  v_minindex INT;
  v_maxindex INT;
  v_noofrec INT;
  v_diff INT;
BEGIN
  v_minindex := 0;
  v_maxindex := 0;
  v_noofrec := 0;
  v_diff := 0;
  v_minindex := ((v_pageno - 1) * v_pagesize) + 1;
  v_maxindex := (v_pageno * v_pagesize);
  IF (v_mode = 1) THEN
  DROP TABLE IF EXISTS tmp_emailidlist;
  CREATE TEMP TABLE tmp_emailidlist (ROWNUMBER INT GENERATED BY DEFAULT AS IDENTITY,

SMID INT,

EMAILID varchar(100),

STATUS varchar(100)) ON COMMIT DROP;
  v_query := 'INSERT INTO #EMAILIDLIST SELECT SMID,EMAILID,CASE WHEN ACTIVE=1 THEN ''ACTIVE'' ELSE ''DEACTIVE'' END FROM BLOGSUBSCRIPTION_MASTER WHERE ISDELETED=0';
  IF (v_emailid <> '') THEN
  v_query := v_query || ' AND EMAILID LIKE ''%' || v_emailid || '%''';
  END IF;
  IF (v_statusid = 1) THEN
  v_query := v_query || ' AND ACTIVE=1';
  ELSE
  IF (v_statusid = 2) THEN
  v_query := v_query || ' AND ACTIVE=0';
  END IF;
  END IF;
  EXECUTE v_query;
  RETURN QUERY SELECT * FROM tmp_emailidlist WHERE rownumber BETWEEN v_minindex AND v_maxindex;
  SELECT COUNT(1) INTO v_noofrec FROM tmp_emailidlist;
  SELECT (v_noofrec - ((v_noofrec / v_pagesize) * v_pagesize)) INTO v_diff;
  IF (v_noofrec > 0) THEN
  IF (v_diff > 0) THEN
  RETURN QUERY SELECT ((v_noofrec / v_pagesize) + 1) AS pages;
  ELSE
  RETURN QUERY SELECT (v_noofrec / v_pagesize) AS pages;
  END IF;
  ELSE
  RETURN QUERY SELECT 1 AS pages;
  END IF;
  DROP TABLE IF EXISTS tmp_emailidlist;
  END IF;
  IF (v_mode = 2) THEN
  IF (v_status = 'ACTIVE') THEN
  UPDATE blogsubscription_master SET active = 0 WHERE smid = v_smid;
  v_intresult := 1;
  ELSE
  UPDATE blogsubscription_master SET active = 1 WHERE smid = v_smid;
  v_intresult := 2;
  END IF;
  END IF;
  IF (v_mode = 3) THEN
  UPDATE blogsubscription_master SET active = 0, isdeleted = 1 WHERE smid = v_smid;
  v_intresult := 1;
  END IF;
  IF (v_mode = 4) THEN
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp (ROWNUMBER INT GENERATED BY DEFAULT AS IDENTITY,

SMID INT,

EMAILID varchar(100),

STATUS varchar(100)) ON COMMIT DROP;
  v_query := 'INSERT INTO #TEMP SELECT SMID,EMAILID,CASE WHEN ACTIVE=0 AND ISDELETED=1  THEN ''DELETED''END FROM BLOGSUBSCRIPTION_MASTER WHERE ISDELETED=1 AND ACTIVE=0';
  IF (v_emailid <> '') THEN
  v_query := v_query || ' AND EMAILID LIKE ''%' || v_emailid || '%''';
  END IF;
  EXECUTE v_query;
  RETURN QUERY SELECT * FROM tmp_temp WHERE rownumber BETWEEN v_minindex AND v_maxindex;
  SELECT COUNT(1) INTO v_noofrec FROM tmp_temp;
  SELECT (v_noofrec - ((v_noofrec / v_pagesize) * v_pagesize)) INTO v_diff;
  IF (v_noofrec > 0) THEN
  IF (v_diff > 0) THEN
  RETURN QUERY SELECT ((v_noofrec / v_pagesize) + 1) AS pages;
  ELSE
  RETURN QUERY SELECT (v_noofrec / v_pagesize) AS pages;
  END IF;
  ELSE
  RETURN QUERY SELECT 1 AS pages;
  END IF;
  DROP TABLE IF EXISTS tmp_temp;
  END IF;
  IF (v_mode = 5) THEN
  UPDATE blogsubscription_master SET active = 1, isdeleted = 0 WHERE smid = v_smid;
  v_intresult := 2;
  END IF;
END;
$$;


--
-- Name: usp_bindsitemapdynamic(text, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_bindsitemapdynamic(v_keywordorcategoryname text DEFAULT 'Bowling Centres'::text, v_mode integer DEFAULT 1) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_catid text;
BEGIN
  v_catid := '';
  IF (v_mode = 1) THEN
  SELECT catid INTO v_catid FROM product_category WHERE catname = v_keywordorcategoryname AND catactive = 1;
  RETURN QUERY SELECT COUNT(1) AS totalcount FROM portal_master WHERE cid = 96 AND (',' || catid || ',') LIKE '%,' || v_catid || ',%' AND active = 1 AND COALESCE(isverified, 0) = 1;
  ELSE
  IF (v_mode = 2) THEN
  SELECT kmid INTO v_catid FROM keyword_master WHERE keywordname = v_keywordorcategoryname AND kactive = 1;
  RETURN QUERY SELECT COUNT(1) AS totalcount FROM portal_master WHERE cid = 96 AND (',' || keyid || ',') LIKE '%,' || v_catid || ',%' AND active = 1 AND COALESCE(isverified, 0) = 1;
  END IF;
  END IF;
END;
$$;


--
-- Name: usp_bindstate(bigint); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_bindstate(v_cid bigint DEFAULT 96) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
BEGIN
  RETURN QUERY SELECT s.sid, s.statename, COALESCE(s.scode, '') AS scode FROM state AS s JOIN country AS c ON c.cid = s.cid WHERE s.cid = v_cid;
END;
$$;


--
-- Name: usp_bindworkinghours(integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_bindworkinghours(v_pmid integer DEFAULT 3) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
BEGIN
  RETURN QUERY SELECT id, dayid, status, openingtime, CASE WHEN COALESCE(openingtimeevening, '') <> '' THEN (closingtimeevening || ' - ' || openingtimeevening) ELSE '' END AS breaktime, closingtime, CASE WHEN dayid = 1 THEN 'Monday' WHEN dayid = 2 THEN 'Tuesday' WHEN dayid = 3 THEN 'Wednesday' WHEN dayid = 4 THEN 'Thursday' WHEN dayid = 5 THEN 'Friday' WHEN dayid = 6 THEN 'Saturday' WHEN dayid = 7 THEN 'Sunday' ELSE '' END AS officeday FROM tblopeningdate WHERE pmid = v_pmid;
END;
$$;


--
-- Name: usp_blockedmerchantlist(integer, integer, character varying, character varying, character varying, character varying, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_blockedmerchantlist(v_startrowindex integer DEFAULT 1, v_maxrows integer DEFAULT 50, v_searchfield character varying DEFAULT ''::character varying, v_searchvalue character varying DEFAULT ''::character varying, v_fromdate character varying DEFAULT ''::character varying, v_todate character varying DEFAULT ''::character varying, v_intresult integer DEFAULT 0) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_minindex int;
  v_maxindex int;
  v_query text;
BEGIN
  v_minindex := (v_startrowindex - 1) * v_maxrows + 1;
  v_maxindex := v_startrowindex * v_maxrows;
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp (ROWNUMBER BIGINT,
PLID bigint,
LOGINID varchar(150),
DOC varchar(150),
PASSWORD varchar(150),
USERNAME varchar(150),
MEMBERNAME varchar(150),
IPADDRESS  varchar(150),
EMAILID  varchar(150),
PHONE varchar(150),
iskycapproved int,
PMID  int,
Sourceid varchar(30),
Sourcejoing varchar(30),
Active int,
status int) ON COMMIT DROP;
  v_query := 'insert into #temp SELECT ROW_NUMBER() OVER(ORDER BY PL.DOC DESC) AS ROWNUMBER,PL.PLID,PL.LOGINID,PL.DOC,
			PL.PASSWORD,PL.USERNAME,ISNULL(pm.COMPANYNAME,'''') AS MEMBERNAME,isnull(PL.IPADDRESS,'''') as IPADDRESS,
			PL.EMAILID,PL.PHONE,PL.iskycapproved,isnull(PL.PMID,0) as PMID,isnull(REFRAL_ID,''''),isnull(TFS.name,''''),PL.ACTIVE,PL.status
			 from PORTAL_LOGIN PL
			 join PORTAL_MASTER pm on pm.PMID=PL.PMID 
			 left join Tbl_TrafficSource TFS on PL.SourceId=TFS.ID
			 where PL.iskycapproved=1 and  PL.status=3';
  v_query := v_query;
  IF (v_searchfield = 'EMAILID') THEN
  v_query := v_query || ' and EMAILID like ''%' || v_searchvalue || '%''';
  END IF;
  IF (v_searchfield = 'MEMBERNAME') THEN
  v_query := v_query || ' and SP_FIRSTNAME like ''%' || v_searchvalue || '%''';
  END IF;
  IF (v_searchfield = 'PHONE') THEN
  v_query := v_query || ' and PHONE like ''%' || v_searchvalue || '%''';
  END IF;
  IF (v_searchfield = 'LOGINID') THEN
  v_searchvalue := REPLACE(v_searchvalue, 'EM', '');
  v_query := v_query || ' and LOGINID like ''%' || v_searchvalue || '%''';
  END IF;
  IF (v_fromdate <> '' AND v_todate <> '') THEN
  v_query := v_query || (' And Convert(date,DOC,105) Between Convert(date,''' || v_fromdate || ''',105) And Convert(date,''' || v_todate || ''',105)');
  END IF;
  IF (v_fromdate <> '') THEN
  v_query := v_query || (' And Convert(date,DOC,105) >= Convert(date,''' || v_fromdate || ''',105)');
  END IF;
  IF (v_todate <> '') THEN
  v_query := v_query || (' And Convert(date,DOC,105) <= Convert(date,''' || v_todate || ''',105)');
  END IF;
  EXECUTE v_query;
  RETURN QUERY SELECT * FROM tmp_temp WHERE rownumber BETWEEN v_minindex AND v_maxindex ORDER BY rownumber ASC NULLS FIRST;
  SELECT COUNT(rownumber) INTO v_intresult FROM tmp_temp;
  DROP TABLE IF EXISTS tmp_temp;
  -- SET option (removed)
END;
$$;


