  v_query := 'insert into #temp SELECT ROW_NUMBER() OVER(ORDER BY PL.DOC DESC) AS ROWNUMBER,PL.DID,PL.LOGINID,PL.DOC,
			PL.PASSWORD,PL.USERNAME,ISNULL(pm.COMPANYNAME,'''') AS MEMBERNAME,isnull(PL.IPADDRESS,'''') as IPADDRESS,
			PL.EMAILID,PL.PHONE,PL.iskycapproved,isnull(PL.PMID,0) as PMID,isnull(REFRAL_ID,''''),'''',PL.ACTIVE,PL.status
			 from TBL_DISTRIBUTOR PL
			 join Distributor_MASTER pm on pm.PMID=PL.PMID 
			 
			 where PL.iskycapproved=1 and  PL.status=3';
  v_query := v_query;
  IF (v_searchfield = 'EMAILID') THEN
  v_query := v_query || ' and EMAILID like ''%' || v_searchvalue || '%''';
  END IF;
  IF (v_searchfield = 'MEMBERNAME') THEN
  v_query := v_query || ' and SP_FIRSTNAME like ''%' || v_searchvalue || '%''';
  END IF;
  IF (v_searchfield = 'PHONE') THEN
  v_query := v_query || ' and PHONE like ''%' || v_searchvalue || '%''';
  END IF;
  IF (v_fromdate <> '' AND v_todate <> '') THEN
  v_query := v_query || (' And Convert(date,DOC,105) Between Convert(date,''' || v_fromdate || ''',105) And Convert(date,''' || v_todate || ''',105)');
  END IF;
  IF (v_fromdate <> '') THEN
  v_query := v_query || (' And Convert(date,DOC,105) >= Convert(date,''' || v_fromdate || ''',105)');
  END IF;
  IF (v_todate <> '') THEN
  v_query := v_query || (' And Convert(date,DOC,105) <= Convert(date,''' || v_todate || ''',105)');
  END IF;
  EXECUTE v_query;
  RETURN QUERY SELECT * FROM tmp_temp WHERE rownumber BETWEEN v_minindex AND v_maxindex ORDER BY rownumber ASC NULLS FIRST;
  SELECT COUNT(rownumber) INTO v_intresult FROM tmp_temp;
  DROP TABLE IF EXISTS tmp_temp;
  -- SET option (removed)
END;
$$;


--
-- Name: usp_blog(integer, text, text, text, character varying, integer, integer, integer, integer, integer, text, text); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_blog(v_blogid integer DEFAULT 0, v_blogtitle text DEFAULT NULL::text, v_blogdescription text DEFAULT NULL::text, v_keywords text DEFAULT NULL::text, v_writer character varying DEFAULT NULL::character varying, v_draftstatus integer DEFAULT 0, v_publishstatus integer DEFAULT 0, v_status integer DEFAULT 0, INOUT v_maxblogid integer DEFAULT NULL::integer, INOUT v_intresult integer DEFAULT NULL::integer, v_category text DEFAULT ''::text, v_canonicalurl text DEFAULT ''::text) RETURNS record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_slice1 text;
  v_index1 INT;
  v_maxbid INT;
BEGIN
  -- BEGIN TRAN (removed)
  IF POSITION('http://office.eblaa.in//uploads/' IN v_blogdescription) <= 0 THEN
  v_blogdescription := REPLACE(v_blogdescription, 'src="/uploads/', 'src="http://office.eblaa.in/uploads/');
  END IF;
  v_intresult := 1;
  IF (v_blogid = 0) THEN
  INSERT INTO tbl_blogmaster (blogtitle, blogdescription, keywords, blogwriter, draftstatus, publishstatus, status, blogcreationdate, category, canonicalurl) VALUES (v_blogtitle, v_blogdescription, v_keywords, v_writer, v_draftstatus, v_publishstatus, v_status, CURRENT_TIMESTAMP, v_category, v_canonicalurl);
  v_maxblogid := IDENT_CURRENT('TBL_BLOGMASTER');
  v_index1 := 1;
  WHILE v_index1 <> 0 LOOP
  SELECT POSITION(',' IN v_keywords) INTO v_index1;
  IF v_index1 <> 0 THEN
  SELECT RTRIM(LTRIM(LEFT(CAST(v_keywords AS TEXT), v_index1 - 1))) INTO v_slice1;
  ELSE
  SELECT RTRIM(LTRIM((v_keywords))) INTO v_slice1;
  END IF;
  IF NOT EXISTS(SELECT blogid FROM tbl_keywordmaster WHERE blogid = v_blogid) THEN
  INSERT INTO tbl_keywordmaster (blogid, keyword, status) VALUES (v_maxblogid, v_slice1, 1);
  END IF;
  IF (0 <> 0) THEN
  v_intresult := 0;
  -- ROLLBACK (removed)
  RETURN;
  END IF;
  SELECT RIGHT(CAST(v_keywords AS TEXT), LENGTH(CAST(v_keywords AS TEXT)) - v_index1) INTO v_keywords;
  IF LENGTH(CAST(v_keywords AS TEXT)) = 0 THEN
  EXIT;
  END IF;
  END LOOP;
  ELSE
  UPDATE tbl_blogmaster SET blogtitle = v_blogtitle, blogdescription = v_blogdescription, keywords = v_keywords, blogwriter = v_writer, draftstatus = v_draftstatus, publishstatus = v_publishstatus, status = v_status, category = v_category WHERE blogid = v_blogid;
  UPDATE tbl_keywordmaster SET status = 0 WHERE blogid = v_blogid;
  v_index1 := 1;
  WHILE v_index1 <> 0 LOOP
  SELECT POSITION(',' IN v_keywords) INTO v_index1;
  IF v_index1 <> 0 THEN
  SELECT RTRIM(LTRIM(LEFT(CAST(v_keywords AS TEXT), v_index1 - 1))) INTO v_slice1;
  ELSE
  SELECT RTRIM(LTRIM((v_keywords))) INTO v_slice1;
  END IF;
  IF NOT EXISTS(SELECT status FROM tbl_keywordmaster WHERE blogid = v_blogid AND keyword = v_slice1) THEN
  INSERT INTO tbl_keywordmaster (blogid, keyword, status) VALUES (v_blogid, v_slice1, 1);
  ELSE
  UPDATE tbl_keywordmaster SET status = 1 WHERE blogid = v_blogid AND keyword = v_slice1;
  END IF;
  IF (0 <> 0) THEN
  v_intresult := 0;
  -- ROLLBACK (removed)
  RETURN;
  END IF;
  SELECT RIGHT(CAST(v_keywords AS TEXT), LENGTH(CAST(v_keywords AS TEXT)) - v_index1) INTO v_keywords;
  IF LENGTH(CAST(v_keywords AS TEXT)) = 0 THEN
  EXIT;
  END IF;
  END LOOP;
  END IF;
  IF (0 <> 0) THEN
  v_intresult := 0;
  -- ROLLBACK (removed)
  RETURN;
  END IF;
  -- COMMIT (removed)
END;
$$;


--
-- Name: usp_blog_subscriptionlogin(character varying, character varying, character varying, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_blog_subscriptionlogin(v_emailid character varying DEFAULT ''::character varying, v_ipcontry character varying DEFAULT ''::character varying, v_ipaddress character varying DEFAULT ''::character varying, INOUT v_intresult integer DEFAULT NULL::integer) RETURNS integer
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_smid BIGINT;
BEGIN
  -- SET option (removed)
  IF EXISTS(SELECT emailid FROM blogsubscription_master WHERE active = 1 AND isdeleted = 0 AND emailid = v_emailid) THEN
  v_intresult := 1;
  RAISE NOTICE '%', 1;
  RETURN;
  END IF;
  IF EXISTS(SELECT emailid FROM blogsubscription_master WHERE active = 0 AND isdeleted = 0 AND emailid = v_emailid) THEN
  v_intresult := 3;
  RAISE NOTICE '%', 3;
  RETURN;
  END IF;
  IF EXISTS(SELECT emailid FROM blogsubscription_master WHERE active = 0 AND isdeleted = 1 AND emailid = v_emailid) THEN
  SELECT smid INTO v_smid FROM blogsubscription_master WHERE RTRIM(LTRIM(emailid)) = RTRIM(LTRIM(v_emailid)) AND active = 0 AND isdeleted = 1;
  v_intresult := 4;
  UPDATE blogsubscription_master SET subscriptiondate = CURRENT_TIMESTAMP, isdeleted = 0, active = 1 WHERE smid = v_smid;
  RAISE NOTICE '%', 4;
  RETURN;
  ELSE
  v_intresult := 2;
  INSERT INTO blogsubscription_master (emailid, subscriptiondate, active, isdeleted, country_name, ipaddress) VALUES (v_emailid, CURRENT_TIMESTAMP, 0, 0, v_ipcontry, v_ipaddress);
  RAISE NOTICE '%', 2;
  RETURN;
  END IF;
  IF (0 <> 0) THEN
  v_intresult := 5;
  RETURN;
  END IF;
  -- SET option (removed)
END;
$$;


--
-- Name: usp_blogandclassifiedmanagemnt(integer, integer, text, timestamp without time zone); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_blogandclassifiedmanagemnt(v_plid integer DEFAULT 1, v_tsmid integer DEFAULT 0, INOUT v_intresultoutput text DEFAULT NULL::text, v_previousdate timestamp without time zone DEFAULT NULL::timestamp without time zone) RETURNS text
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_islooping INT;
  v_previousremainpointforclassified Decimal(10,2);
  v_previousremainpointforblog Decimal(10,2);
  v_previousremainpointforbusinesslisting Decimal(10,2);
  v_priceperblog Decimal(10,2);
  v_priceperclassified Decimal(10,2);
  v_priceperbusinesslisting Decimal(10,2);
  v_previousremainblog Decimal(10,2);
  v_previousremainclassified Decimal(10,2);
  v_previousremainbusinesslisting Decimal(10,2);
  v_pointperdayforblog Decimal(10,2);
  v_pointperdayforclassified Decimal(10,2);
  v_pointperdayforbusinesslisting Decimal(10,2);
  v_currentdatetime timestamp;
BEGIN
  BEGIN
  v_islooping := 1;
  v_previousremainpointforclassified := 0.00;
  v_previousremainpointforblog := 0.00;
  v_previousremainpointforbusinesslisting := 0.00;
  v_priceperblog := 0.00;
  v_priceperclassified := 0.00;
  v_priceperbusinesslisting := 0.00;
  v_previousremainblog := 0.00;
  v_previousremainclassified := 0.00;
  v_previousremainbusinesslisting := 0.00;
  v_pointperdayforblog := 0.00;
  v_pointperdayforclassified := 0.00;
  v_pointperdayforbusinesslisting := 0.00;
  SELECT '' INTO v_currentdatetime;
  SELECT perdaypointforblog, perdaypointforclassified, perdaypointforbusinesslisting, priceperblog, priceperclassified, priceperbusinesslisting INTO v_pointperdayforblog, v_pointperdayforclassified, v_pointperdayforbusinesslisting, v_priceperblog, v_priceperclassified, v_priceperbusinesslisting FROM tbl_datewisecommonroiaccount WHERE CAST(date AS DATE) = CAST(dbo.FUN_GETCURRENTDATE() AS DATE) LIMIT 1;
  SELECT COALESCE((CASE WHEN creditednoofblog >= submittednoofblog THEN ((creditednoofblog - submittednoofblog) + remainnoofblog) WHEN submittednoofblog > creditednoofblog THEN remainnoofblog ELSE 0 END), 0), COALESCE((CASE WHEN creditednoofclassified >= submittednoofclassified THEN ((creditednoofclassified - submittednoofclassified) + remainnoofclassified) WHEN submittednoofclassified > creditednoofclassified THEN remainnoofclassified ELSE 0 END), 0), COALESCE((CASE WHEN creditednoofbusinesslisting >= submittednoofbusinesslisting THEN ((creditednoofbusinesslisting - submittednoofbusinesslisting) + remainnoofbusinesslisting) WHEN submittednoofbusinesslisting > creditednoofbusinesslisting THEN remainnoofbusinesslisting ELSE 0 END), 0), COALESCE(previouscarryforwardpointforblog, 0), COALESCE(previouscarryforwardpointforclassified, 0), COALESCE(previouscarryforwardpointforbusinesslisting, 0) INTO v_previousremainblog, v_previousremainclassified, v_previousremainbusinesslisting, v_previousremainpointforblog, v_previousremainpointforclassified, v_previousremainpointforbusinesslisting FROM tbl_dailytasklimits WHERE plid = v_plid AND CAST(date AS DATE) = CAST(v_previousdate AS DATE) ORDER BY date DESC NULLS LAST LIMIT 1;
  SELECT (COALESCE(v_previousremainpointforblog, 0) + COALESCE(perdaypointforblog, 0)), (COALESCE(v_previousremainpointforclassified, 0) + COALESCE(perdaypointforclassified, 0)), (COALESCE(v_previousremainpointforbusinesslisting, 0) + COALESCE(perdaypointforbusinesslisting, 0)) INTO v_previousremainpointforblog, v_previousremainpointforclassified, v_previousremainpointforbusinesslisting FROM tbl_datewisecommonroiaccount WHERE CAST(date AS DATE) = CAST(dbo.FUN_GETCURRENTDATE() AS DATE) LIMIT 1;
  WHILE (v_islooping = 1 AND (v_previousremainpointforblog > 0 OR v_previousremainpointforclassified > 0 OR v_previousremainpointforbusinesslisting > 0)) LOOP
  IF (v_previousremainpointforblog >= v_priceperblog) THEN
  v_islooping := 1;
  v_previousremainpointforblog := v_previousremainpointforblog - v_priceperblog;
  v_previousremainblog := v_previousremainblog + 1;
  ELSE
  v_islooping := 0;
  END IF;
  IF (v_previousremainpointforclassified > v_priceperclassified) THEN
  v_islooping := 1;
  v_previousremainpointforclassified := v_previousremainpointforclassified - v_priceperclassified;
  v_previousremainclassified := v_previousremainclassified + 1;
  END IF;
  IF (v_previousremainpointforbusinesslisting > v_priceperbusinesslisting) THEN
  v_islooping := 1;
  v_previousremainpointforbusinesslisting := v_previousremainpointforbusinesslisting - v_priceperbusinesslisting;
  v_previousremainbusinesslisting := v_previousremainbusinesslisting + 1;
  END IF;
  END LOOP;
  UPDATE tbl_dailytasklimits SET totalpointforblog = v_pointperdayforblog, creditednoofblog = 0, submittednoofblog = 0, carryforwardnoofblog = v_previousremainblog, remainnoofblog = v_previousremainblog, priceperblog = v_priceperblog, totalpointforclassified = v_pointperdayforclassified, creditednoofclassified = 0, submittednoofclassified = 0, carryforwardnoofclassified = v_previousremainclassified, remainnoofclassified = v_previousremainclassified, priceperclassified = v_priceperclassified, totalpointforbusinesslisting = v_pointperdayforbusinesslisting, creditednoofbusinesslisting = 0, submittednoofbusinesslisting = 0, carryforwardnoofbusinesslisting = v_previousremainbusinesslisting, remainnoofbusinesslisting = v_previousremainbusinesslisting, priceperbusinesslisting = v_priceperbusinesslisting, previouscarryforwardpointforblog = v_previousremainpointforblog, previouscarryforwardpointforclassified = v_previousremainpointforclassified, previouscarryforwardpointforbusinesslisting = v_previousremainpointforbusinesslisting WHERE plid = v_plid AND status = 1 AND CAST(date AS DATE) = CAST(v_currentdatetime AS DATE);
  v_intresultoutput := 'Ok';
  RETURN;
  EXCEPTION WHEN OTHERS THEN
  v_intresultoutput := 'Cancel';
  RETURN;
  END;
END;
$$;


