--
-- Name: usp_blogcheckinguser(character varying, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_blogcheckinguser(v_email character varying DEFAULT ''::character varying, INOUT v_intresult integer DEFAULT NULL::integer) RETURNS integer
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_smid BIGINT;
BEGIN
  v_intresult := 0;
  IF EXISTS(SELECT smid FROM blogsubscription_master WHERE RTRIM(LTRIM(emailid)) = RTRIM(LTRIM(v_email)) AND active = 1) THEN
  SELECT smid INTO v_smid FROM blogsubscription_master WHERE RTRIM(LTRIM(emailid)) = RTRIM(LTRIM(v_email)) AND active = 1;
  v_intresult := 1;
  UPDATE blogsubscription_master SET active = 0, isdeleted = 1 WHERE smid = v_smid;
  RETURN;
  END IF;
  IF EXISTS(SELECT smid FROM blogsubscription_master WHERE RTRIM(LTRIM(emailid)) = RTRIM(LTRIM(v_email)) AND active = 0) THEN
  v_intresult := 3;
  RETURN;
  ELSE
  v_intresult := 2;
  RETURN;
  END IF;
END;
$$;


--
-- Name: usp_blogcommentonreview(text, text); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_blogcommentonreview(v_usertype text DEFAULT ''::text, v_blogtitle text DEFAULT ''::text) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
BEGIN
  RETURN QUERY SELECT ROW_NUMBER() OVER (ORDER BY brc.date DESC NULLS LAST) AS rownumber, bm.blogid, bm.blogtitle, br.rwid, br.reviewdesc, br.name AS reviewby, COALESCE(brc.cmid, 0) AS cmid, brc.comment, brc.name AS commentedby, (CAST(TO_CHAR(brc.date, 'DD-MM-YYYY') AS VARCHAR(20)) || ' ' || CAST(TO_CHAR(brc.date, 'HH24:MI:SS') AS VARCHAR(5))) AS date, brc.status FROM tbl_blogmaster AS bm LEFT JOIN tbl_blogreviewmaster AS br ON br.blogid = bm.blogid LEFT JOIN tbl_blogcommentswithreview AS brc ON brc.rwid = br.rwid WHERE bm.status = 1 AND publishstatus = 1 AND br.rwid <> '' AND brc.cmid <> '' ORDER BY brc.date DESC NULLS LAST;
END;
$$;


--
-- Name: usp_bloginsreviewsandcomments(character varying, integer, character varying, character varying, integer, text, character varying, character varying, character varying, character varying, character varying, integer, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_bloginsreviewsandcomments(v_blogid character varying, v_rwid integer DEFAULT 0, v_name character varying DEFAULT NULL::character varying, v_emailid character varying DEFAULT NULL::character varying, v_rate integer DEFAULT 0, v_reviewcommentdesc text DEFAULT NULL::text, v_type character varying DEFAULT NULL::character varying, v_ipaddress character varying DEFAULT NULL::character varying, v_ipcountry character varying DEFAULT NULL::character varying, v_ipstate character varying DEFAULT NULL::character varying, v_ipcity character varying DEFAULT NULL::character varying, v_intresult integer DEFAULT 0, v_subscribed integer DEFAULT 0) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_maxrwid INT;
  v_maxcmid INT;
  v_prid BIGINT;
  v_countrev INT;
  v_totalstar INT;
  v_avgrate INT;
BEGIN
  -- BEGIN TRAN (removed)
  v_subscribed := 0;
  DROP TABLE IF EXISTS tmp_tempdetailsall;
  CREATE TEMP TABLE tmp_tempdetailsall (ROWNUMBER INT GENERATED BY DEFAULT AS IDENTITY,

RCID INT,

NAME VARCHAR(200),

RCDESC text,

RORC VARCHAR(10),

RATE INT,

TOTALREVIEWS INT,

AVGRATE INT,

DATE VARCHAR(100)) ON COMMIT DROP;
  SELECT COALESCE(MAX(rwid), 0) INTO v_maxrwid FROM tbl_blogreviewmaster;
  SELECT COALESCE(MAX(cmid), 0) INTO v_maxcmid FROM tbl_blogcommentswithreview;
  IF NOT EXISTS(SELECT 1 FROM blogsubscription_master WHERE emailid = v_emailid) THEN
  IF (v_emailid <> '') THEN
  INSERT INTO blogsubscription_master (emailid, subscriptiondate, active, isdeleted, country_name, ipaddress) VALUES (v_emailid, CURRENT_TIMESTAMP, 1, 0, v_ipcountry, v_ipaddress);
  v_subscribed := 1;
  END IF;
  ELSE
  v_subscribed := 0;
  END IF;
  IF (v_type = 'R') THEN
  INSERT INTO tbl_blogreviewmaster (blogid, name, emailid, reviewtitle, reviewdesc, stars, date, status, ipaddress, ipcountry, ipstate, ipcity) VALUES (v_blogid, v_name, v_emailid, '', v_reviewcommentdesc, v_rate, CURRENT_TIMESTAMP, 1, v_ipaddress, v_ipcountry, v_ipstate, v_ipcity);
  END IF;
  IF (v_type = 'C') THEN
  INSERT INTO tbl_blogcommentswithreview (rwid, blogid, name, emailid, comment, date, status, ipaddress, ipcountry, ipstate, ipcity) VALUES (v_rwid, v_blogid, v_name, v_emailid, v_reviewcommentdesc, CURRENT_TIMESTAMP, 1, v_ipaddress, v_ipcountry, v_ipstate, v_ipcity);
  END IF;
  SELECT COUNT(rwid) INTO v_countrev FROM tbl_blogreviewmaster WHERE blogid = v_blogid AND status = 1;
  SELECT COALESCE(SUM(stars), 0) INTO v_totalstar FROM tbl_blogreviewmaster WHERE blogid = v_blogid AND status = 1;
  IF (v_countrev = 0) THEN
  v_avgrate := 0;
  END IF;
  IF (v_countrev > 0) THEN
  v_avgrate := v_totalstar / v_countrev;
  END IF;
  IF (v_type = 'R') THEN
  INSERT INTO tmp_tempdetailsall SELECT rwid, CAST(name AS VARCHAR(200)) AS name, CAST(reviewdesc AS text) AS reviewdesc, 'R', stars, v_countrev, v_avgrate, CAST(TO_CHAR(date, 'TMMon DD YYYY FMHH12:MI%p') AS VARCHAR(100)) AS date FROM tbl_blogreviewmaster WHERE rwid = v_maxrwid + 1;
  END IF;
  IF (v_type = 'C') THEN
  INSERT INTO tmp_tempdetailsall SELECT cmid, CAST(name AS VARCHAR(200)) AS name, CAST(comment AS text) AS comment, 'C', 0, v_countrev, v_avgrate, CAST(TO_CHAR(date, 'TMMon DD YYYY FMHH12:MI%p') AS VARCHAR(100)) AS date FROM tbl_blogcommentswithreview WHERE cmid = v_maxcmid + 1 ORDER BY date ASC NULLS FIRST;
  END IF;
  IF (0 <> 0) THEN
  v_intresult := 0;
  RETURN QUERY SELECT * FROM tmp_tempdetailsall;
  -- ROLLBACK (removed)
  RETURN;
  END IF;
  v_intresult := v_maxrwid + 1;
  RETURN QUERY SELECT * FROM tmp_tempdetailsall;
  -- COMMIT (removed)
END;
$$;


--
-- Name: usp_blogmaster(integer, integer, character varying, character varying, character varying, character varying, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_blogmaster(v_startrowindex integer, v_maxrows integer, v_searchfield character varying, v_searchvalue character varying, v_fromdate character varying, v_todate character varying, v_recordcount integer) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_sqlquery text;
BEGIN
  -- SET option (removed)
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp (rowNumber int,
blogid bigint,
blogtitle text,
BlogWriter varchar(100),
blogdescription text,
type varchar(20),
status varchar(20),

BlogCreationDate varchar(100)) ON COMMIT DROP;
  v_sqlquery := '';
  v_sqlquery := 'insert into #temp select ROW_NUMBER() OVER(ORDER BY blogid desc) as rowNumber, 
 blogid,blogtitle,BlogWriter,blogdescription,case draftstatus when 1 then ''Draft'' when 0 then ''Published'' end as type,case
                  status when 1 then ''Active'' when 0 then ''Inactive'' end as status,convert(varchar(20),BlogCreationDate,105) as BlogCreationDate from  tbl_BlogMaster where blogid <> '''' ';
  IF (v_fromdate = '' OR v_todate = '') THEN
  IF (v_fromdate <> '') THEN
  v_sqlquery := v_sqlquery || ' and convert(date,BlogCreationDate,105)= replace(convert(date,''' || v_fromdate || ''',105),''/'',''-'') ';
  END IF;
  IF (v_todate <> '') THEN
  v_sqlquery := v_sqlquery || ' and convert(date, BlogCreationDate,105)  =replace(convert(date,''' || v_todate || ''',105),''/'',''-'') ';
  END IF;
  END IF;
  IF (v_fromdate <> '' AND v_todate <> '') THEN
  v_sqlquery := v_sqlquery || ' and  convert(date, BlogCreationDate,105)  between  replace(convert(date,''' || v_fromdate || ''',105),''/'',''-'')  and replace(convert(date,''' || v_todate || ''',105),''/'',''-'')';
  END IF;
  IF (v_searchfield = 'blog') THEN
  v_sqlquery := v_sqlquery || ' and blogtitle like ''%' || v_searchvalue || '%''';
  END IF;
  IF (v_searchfield = 'writer') THEN
  v_sqlquery := v_sqlquery || ' and BlogWriter like ''%' || v_searchvalue || '%''';
  END IF;
  EXECUTE v_sqlquery || 'order by blogid desc';
  SELECT COUNT(*) INTO v_recordcount FROM tmp_temp;
  RETURN QUERY SELECT * FROM tmp_temp WHERE rownumber BETWEEN v_startrowindex AND v_maxrows;
  DROP TABLE IF EXISTS tmp_temp;
  RETURN QUERY SELECT v_recordcount AS recordcount;
  -- SET option (removed)
END;
$$;


--
-- Name: usp_blogsubscriptionlogin(character varying, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_blogsubscriptionlogin(v_emailid character varying DEFAULT ''::character varying, INOUT v_intresult integer DEFAULT NULL::integer) RETURNS integer
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_smid BIGINT;
BEGIN
  -- SET option (removed)
  IF EXISTS(SELECT emailid FROM blogsubscription_master WHERE active = 1 AND isdeleted = 0 AND emailid = v_emailid) THEN
  v_intresult := 1;
  RAISE NOTICE '%', 1;
  RETURN;
  END IF;
  IF EXISTS(SELECT emailid FROM blogsubscription_master WHERE active = 0 AND isdeleted = 0 AND emailid = v_emailid) THEN
  v_intresult := 3;
  RAISE NOTICE '%', 3;
  RETURN;
  END IF;
  IF EXISTS(SELECT emailid FROM blogsubscription_master WHERE active = 0 AND isdeleted = 1 AND emailid = v_emailid) THEN
  SELECT smid INTO v_smid FROM blogsubscription_master WHERE RTRIM(LTRIM(emailid)) = RTRIM(LTRIM(v_emailid)) AND active = 0 AND isdeleted = 1;
  v_intresult := 4;
  UPDATE blogsubscription_master SET subscriptiondate = CURRENT_TIMESTAMP, isdeleted = 0, active = 1 WHERE smid = v_smid;
  RAISE NOTICE '%', 4;
  RETURN;
  ELSE
  v_intresult := 2;
  INSERT INTO blogsubscription_master (emailid, subscriptiondate, active, isdeleted) VALUES (v_emailid, CURRENT_TIMESTAMP, 0, 0);
  RAISE NOTICE '%', 2;
  RETURN;
  END IF;
  IF (0 <> 0) THEN
  v_intresult := 5;
  RETURN;
  END IF;
  -- SET option (removed)
END;
$$;


--
-- Name: usp_blogtotalvists(integer, integer, text, character varying, character varying, integer, integer, integer, character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_blogtotalvists(v_startrowindex integer DEFAULT 0, v_maxrows integer DEFAULT 0, v_blogtitle text DEFAULT ''::text, v_fromdate character varying DEFAULT ''::character varying, v_todate character varying DEFAULT ''::character varying, v_recordcount integer DEFAULT 0, v_totatodayvisits integer DEFAULT 0, v_totalvisits integer DEFAULT 0, v_type character varying DEFAULT ''::character varying) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_sqlquery text;
  v_fromdate1 VARCHAR(40);
BEGIN
  -- SET option (removed)
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp (ROWNUMBER INT GENERATED BY DEFAULT AS IDENTITY,

BLOGID BIGINT,

BLOGTITLE text,

TODAYVISITS INT,

TOTALVISITS INT) ON COMMIT DROP;
  v_sqlquery := '';
  v_fromdate1 := CURRENT_TIMESTAMP;
  v_sqlquery := 'INSERT INTO #TEMP SELECT   V.BLOGID,B.BLOGTITLE,ISNULL(GRD.TODAYVISIT,''0'') AS TODAYVISITS,COUNT( V.BLOGID) AS TOTALVISITS FROM TBL_BLOGVISITIP V INNER JOIN TBL_BLOGMASTER B ON

  V.BLOGID=B.BLOGID LEFT JOIN (SELECT COUNT(V1.BLOGID) TODAYVISIT,V1.BLOGID   FROM TBL_BLOGVISITIP V1 WHERE V1.BLOGID <> '' ''   ';
  IF (v_fromdate = '' OR v_todate = '') THEN
  IF (v_fromdate = '' AND v_todate = '') THEN
  v_sqlquery := v_sqlquery || ' AND CONVERT(DATE,V1.VIEWTIME,110)= REPLACE(CONVERT(DATE,''' || v_fromdate1 || ''',103),''/'',''-'') ';
  END IF;
  IF (v_fromdate <> '') THEN
  v_sqlquery := v_sqlquery || ' AND CONVERT(DATE,V1.VIEWTIME,110)= REPLACE(CONVERT(DATE,''' || v_fromdate || ''',103),''/'',''-'') ';
  END IF;
  IF (v_todate <> '') THEN
  v_sqlquery := v_sqlquery || ' AND  CONVERT(DATE,V1.VIEWTIME,110)  =REPLACE(CONVERT(DATE,''' || v_todate || ''',103),''/'',''-'') ';
  END IF;
  END IF;
  IF (v_fromdate <> '' AND v_todate <> '') THEN
  v_sqlquery := v_sqlquery || ' AND CONVERT(DATE,V1.VIEWTIME,110)  BETWEEN  REPLACE(CONVERT(DATE,''' || v_fromdate || ''',103),''/'',''-'')  AND REPLACE(CONVERT(DATE,''' || v_todate || ''',103),''/'',''-'')';
  END IF;
  v_sqlquery := v_sqlquery || ' GROUP BY V1.BLOGID ) GRD ON GRD.BLOGID=V.BLOGID WHERE  B.PUBLISHSTATUS=1 AND B.STATUS=1 ';
  IF (v_blogtitle <> '') THEN
  v_sqlquery := v_sqlquery || (' AND B.BLOGTITLE LIKE ''%' || v_blogtitle || '%''');
  END IF;
  v_sqlquery := v_sqlquery || (' GROUP BY V.BLOGID,B.BLOGTITLE ,GRD.TODAYVISIT  ');
  IF (v_type = '') THEN
  v_sqlquery := v_sqlquery || (' ORDER BY V.BLOGID DESC');
  END IF;
  IF (v_type = 'TOTDESC') THEN
  v_sqlquery := v_sqlquery || (' ORDER BY TOTALVISITS DESC');
  END IF;
  IF (v_type = 'TOTASC') THEN
  v_sqlquery := v_sqlquery || (' ORDER BY TOTALVISITS ASC');
  END IF;
  IF (v_type = 'TODESC') THEN
  v_sqlquery := v_sqlquery || (' ORDER BY GRD.TODAYVISIT DESC');
  END IF;
  IF (v_type = 'TOASC') THEN
  v_sqlquery := v_sqlquery || (' ORDER BY GRD.TODAYVISIT ASC');
  END IF;
  EXECUTE v_sqlquery;
  SELECT COUNT(*) INTO v_recordcount FROM tmp_temp;
  RETURN QUERY SELECT * FROM tmp_temp WHERE rownumber BETWEEN v_startrowindex AND v_maxrows;
  SELECT SUM(totalvisits) INTO v_totalvisits FROM tmp_temp WHERE rownumber BETWEEN v_startrowindex AND v_maxrows;
  SELECT SUM(todayvisits) INTO v_totatodayvisits FROM tmp_temp WHERE rownumber BETWEEN v_startrowindex AND v_maxrows;
  DROP TABLE IF EXISTS tmp_temp;
  RETURN QUERY SELECT v_recordcount AS recordcount;
  -- SET option (removed)
END;
$$;


--
-- Name: usp_broadbandrecharge_details(integer, integer, integer, character varying, character varying, integer, character varying, character varying, character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_broadbandrecharge_details(v_mode integer DEFAULT 0, v_startrowindex integer DEFAULT 1, v_maxrows integer DEFAULT 100, v_fromdate character varying DEFAULT ''::character varying, v_todate character varying DEFAULT ''::character varying, v_totalcount integer DEFAULT 0, v_searchfield character varying DEFAULT ''::character varying, v_searchvalue character varying DEFAULT ''::character varying, v_status character varying DEFAULT ''::character varying) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_minindex INT;
  v_maxindex INT;
  v_query text;
BEGIN
  v_minindex := (v_startrowindex - 1) * v_maxrows + 1;
  v_maxindex := v_startrowindex * v_maxrows;
  IF (v_mode = 0) THEN
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp (ROWNUMBER BIGINT GENERATED BY DEFAULT AS IDENTITY,         
 TCPRID BIGINT,               
 CLID BIGINT,                 
 MOBILENO VARCHAR(100),         
 OPERATORTYPE VARCHAR(100),        
 RECHARGEAMOUNT DECIMAL(18,2),        
 TRANSACTIONID  VARCHAR(100),         
 RECHARGEDATE VARCHAR(100),         
 ADMINSTATUS VARCHAR(100),        
 NAME VARCHAR(100),        
 EMAILID VARCHAR(100),        
 OPERATORNAME VARCHAR(100),        
 OPERATORCODE VARCHAR(100),        
 ISANDROIDORWEB INT,        
  PaidViaCashWallet Decimal(18,8),    
PaidViaCahbackWallet Decimal(18,8),    
PaidViaKreazVoucher Int,    
PaidViaOnline Decimal(18,8)) ON COMMIT DROP;
  v_query := 'INSERT INTO #TEMP SELECT TCPR.TCBRID,TCPR.CLID,TCPR.MOBILENO,TCPR.OPERATORTYPE,        
TCPR.RECHARGEAMOUNT,TCPR.TRANSACTIONID,CAST(TCPR.RECHARGEDATE AS VARCHAR(50)) ,TCPR.RECHARGESTATUS        
,(CL.FNAME+'' ''+CL.LNAME) AS NAME,CL.EMAILID,TCPR.OPERATORNAME,TCPR.OPERATORCODE,TCPR.ISANDROIDORWEB,        
 ISNULL(CASHWALLETUSED,0),  
ISNULL(CASHBACKWALLETUSED,0),    
ISNULL(VOUCHERWALLETUSED,0),  
ISNULL(TBL_ONLINEPAYMENTHISTORY.AMOUNT,0)        
FROM TBL_CUSTOMER_BROADBAND_RECHARGES TCPR     
LEFT JOIN TBL_ORDERPAYMENT_HISTORY ON TBL_ORDERPAYMENT_HISTORY.ORDERID=TCPR.TRANSACTIONID      
LEFT JOIN TBL_ORDERONLINEREQUESTS ON TBL_ORDERONLINEREQUESTS.ORDERID=TCPR.TRANSACTIONID     
LEFT JOIN TBL_ONLINEPAYMENTHISTORY ON TBL_ONLINEPAYMENTHISTORY.REFERNECID=TBL_ORDERONLINEREQUESTS.TRANSACTIONID                         
          
LEFT JOIN TBL_CUSTOMERLOGIN CL ON CL.CLID=TCPR.CLID            
  WHERE TCPR.RECHARGESTATUS Is Not Null';
  IF ((v_fromdate <> '') AND (v_todate = '')) THEN
  v_query := v_query || ' AND CONVERT(DATE, TCPR.RECHARGEDATE, 105) BETWEEN  CONVERT(DATE, ''' || v_fromdate || ''', 105) AND  CONVERT(DATE, DBO.FUN_GETCURRENTDATE(), 105)';
  END IF;
  IF ((v_fromdate = '') AND (v_todate <> '')) THEN
  v_query := v_query || 'AND CONVERT(DATE, TCPR.RECHARGEDATE, 105) BETWEEN  CONVERT(DATE, ''' || v_todate || ''', 105) AND  CONVERT(DATE, DBO.FUN_GETCURRENTDATE(), 105)';
  END IF;
  IF ((v_fromdate <> '') AND (v_todate <> '')) THEN
  v_query := v_query || 'AND CONVERT(DATE, TCPR.RECHARGEDATE, 105) BETWEEN CONVERT(DATE, ''' || v_fromdate || ''', 105) AND  CONVERT(DATE, ''' || v_todate || ''', 105)';
  END IF;
  IF (v_searchfield = 'NAME') THEN
  v_query := v_query || ' AND (CL.FNAME+CL.LNAME) LIKE ''%' || v_searchvalue || '%'' ';
  END IF;
  IF (v_searchfield = 'PHONE') THEN
  v_query := v_query || ' AND TCPR.MOBILENO LIKE ''%' || v_searchvalue || '%'' ';
  END IF;
  IF (v_searchfield = 'EMAILID') THEN
  v_query := v_query || ' AND CL.EMAILID LIKE ''%' || v_searchvalue || '%'' ';
  END IF;
  IF (v_searchfield = 'TRANSACTIONID') THEN
  v_query := v_query || ' AND TCPR.TRANSACTIONID LIKE ''%' || v_searchvalue || '%'' ';
  END IF;
  IF (v_status <> '') THEN
  v_query := v_query || ' AND TCPR.RECHARGESTATUS =''' || v_status || ''' ';
  END IF;
  v_query := v_query || ' ORDER BY TCPR.RECHARGEDATE DESC';
  EXECUTE v_query;
  RETURN QUERY SELECT rownumber, tcprid, clid, mobileno, operatortype, rechargeamount, transactionid, rechargedate, adminstatus, name, emailid, operatorname, operatorcode, isandroidorweb, paidviacashwallet, paidviacahbackwallet, paidviakreazvoucher, paidviaonline FROM tmp_temp WHERE rownumber BETWEEN v_minindex AND v_maxindex ORDER BY rownumber ASC NULLS FIRST;
  SELECT COUNT(rownumber) INTO v_totalcount FROM tmp_temp;
  DROP TABLE IF EXISTS tmp_temp;
  -- SET option (removed)
  END IF;
END;
$$;


--
-- Name: usp_bulk_upload_pincodelist_history(integer, integer, character varying, character varying, character varying, character varying, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_bulk_upload_pincodelist_history(v_startrowindex integer DEFAULT 1, v_maxrows integer DEFAULT 100, v_fromdate character varying DEFAULT ''::character varying, v_todate character varying DEFAULT '22-09-2018'::character varying, v_requestid character varying DEFAULT ''::character varying, v_logisticpartner character varying DEFAULT 'Shivam'::character varying, v_intresult integer DEFAULT 0) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_minindex INT;
  v_maxindex INT;
  v_query text;
  v_condition text;
  v_countquery text;
BEGIN
  v_query := '';
  v_condition := '';
  v_countquery := '';
  v_minindex := (v_startrowindex - 1) * v_maxrows + 1;
  v_maxindex := v_startrowindex * v_maxrows;
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp (ROWNUMBER INT GENERATED BY DEFAULT AS IDENTITY,
LOGISTICPARTNER VARCHAR(100),
REQUESTID VARCHAR(50),
FILENAME VARCHAR(500),
TOTALUPLOADRECORD INT,
TOTALERRORRECORD INT,
UPLOADBY VARCHAR(100),
CREATED_DATE VARCHAR(100),
STATUS INT) ON COMMIT DROP;
  v_query := 'INSERT INTO #TEMP select ISNULL(TLP.NAME,''''),ISNULL(TUPE.REQUESTID,''''),
ISNULL(TUPE.EXCELFILE,''''),ISNULL(TUPE.TOTALUPLOADEDRECORDS,0),ISNULL(TUPE.TOTALERRORRECORDS,0),
ISNULL(EM.Emp_Name,''''),ISNULL(TUPE.ACTIVITYDATE,''''),TUPE.STATUS
 from TBL_UPLOADEDPINCODEEXCELLOG TUPE left join TBL_LOGISTICPARTNERS TLP 
on TUPE.TLPID=TLP.TLPID  left join Tbl_Employee_Master EM on Em.Emp_LoginID=TUPE.ACTIVITYBYUSERID WHERE 1=1';
  IF (v_fromdate <> '' AND v_todate <> '') THEN
  v_query := v_query || '  AND CONVERT(varchar(50), ACTIVITYDATE,105)  >= CONVERT(varchar(50),''' || v_fromdate || ''',105)  
 AND CONVERT(varchar(50), ACTIVITYDATE,105) <= CONVERT(varchar(50),''' || v_todate || ''',105)';
  ELSE
  IF (v_fromdate <> '') THEN
  v_query := v_query || '  AND CONVERT(varchar(50), ACTIVITYDATE,105) between  CONVERT(varchar(50),''' || v_fromdate || ''',105) AND  CONVERT(varchar(50), DBO.FUN_GETCURRENTDATE(), 105)';
  ELSE
  IF (v_todate <> '') THEN
  v_query := v_query || '  AND CONVERT(varchar(50), ACTIVITYDATE,105) between CONVERT(varchar(50),''' || v_todate || ''',105) AND  CONVERT(varchar(50), DBO.FUN_GETCURRENTDATE(), 105)';
  END IF;
  END IF;
  END IF;
  IF (v_logisticpartner <> '') THEN
  v_query := v_query || ' AND TLP.NAME=''' || v_logisticpartner || '''';
  END IF;
  IF (v_requestid <> '') THEN
  v_query := v_query || ' AND TUPE.REQUESTID=''' || v_requestid || '''';
  END IF;
  v_query := v_query || 'order by TUPE.ACTIVITYDATE desc';
  EXECUTE v_query;
  RETURN QUERY SELECT * FROM tmp_temp WHERE rownumber BETWEEN v_minindex AND v_maxindex;
  SELECT COUNT(1) INTO v_intresult FROM tmp_temp;
END;
$$;


--
-- Name: usp_bulkuploadhistory(integer, bigint, character varying, character varying, character varying, character varying, integer, integer, integer, integer, integer, integer, character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_bulkuploadhistory(v_mode integer DEFAULT 1, v_id bigint DEFAULT 0, v_fromdate character varying DEFAULT ''::character varying, v_todate character varying DEFAULT ''::character varying, v_filename character varying DEFAULT ''::character varying, v_byuserid character varying DEFAULT '5'::character varying, v_maincatid integer DEFAULT 4, v_catid integer DEFAULT 5, v_subcatid integer DEFAULT 0, v_startrowindex integer DEFAULT 1, v_maxrows integer DEFAULT 100, v_totalcount integer DEFAULT 0, v_strresult character varying DEFAULT ''::character varying) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_query text;
  v_minindex INT;
  v_maxindex INT;
BEGIN
  IF (v_mode = 1) THEN
  v_query := '';
  v_minindex := (v_startrowindex - 1) * v_maxrows + 1;
  v_maxindex := v_startrowindex * v_maxrows;
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp (ROWNUMBER BIGINT PRIMARY KEY,  
  TUIELID BIGINT,  
  ActivityByUser varchar(1000),  
  ActivityDate varchar(100),  
  ExcelFile text,  
  Status INT,  
  ActivityByUserId varchar(100),
  Companyname varchar(200)  ,
  CategoryName varchar(100),
  Categoryid int,
  SubCategoryName varchar(100),
  SubCategoryid int,
  TotalRecord int,
   SubSubCategoryName varchar(100),
   SubSubCategoryid int,
   TotalerrorRecord int) ON COMMIT DROP;
  v_query := 'INSERT INTO #TEMP select ROW_NUMBER() OVER (ORDER BY TUIELID DESC) as ROWNUMBER, TUIELID,
 ActivityByUser,convert(Date, ActivityDate,105) AS ActivityDate,
	 ExcelFile, tue.Status,ActivityByUserId,PM.COMPANYNAME,pc.CATNAME as CategoryName,pc.catid as Categoryid,
	 ps.SCATNAME as SubCategoryName, ps.SCATID as SubCategoryid, TotalRecord,
	 km.KEYWORDNAME as SubSubCategoryName ,km.KMID as SubSubCategoryid
	 ,tue.TotalerrorRecord From  Tbl_UploadedIWalletExcelLog tue   left join PRODUCT_CATEGORY pc on pc.CATID=tue.Maincategorid
	 left join PRODUCT_SUBCATEGORY ps on ps.SCATID=tue.categoryid
	 left join KEYWORD_MASTER km on km.KMID=tue.Subcategoryid
	 left join PORTAL_MASTER PM on  tue.ACTIVITYBYUSERID=PM.PLID  
	 WHERE tue.STATUS = 1';
  IF (v_filename <> '') THEN
