--
-- Name: usp_bulkuploadhistory_listing(integer, bigint, character varying, character varying, character varying, character varying, integer, integer, integer, integer, integer, integer, character varying, character varying, character varying, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_bulkuploadhistory_listing(v_mode integer DEFAULT 1, v_id bigint DEFAULT 0, v_fromdate character varying DEFAULT ''::character varying, v_todate character varying DEFAULT ''::character varying, v_filename character varying DEFAULT ''::character varying, v_byuserid character varying DEFAULT ''::character varying, v_maincatid integer DEFAULT 0, v_catid integer DEFAULT 0, v_subcatid integer DEFAULT 0, v_startrowindex integer DEFAULT 1, v_maxrows integer DEFAULT 100, v_totalcount integer DEFAULT 0, v_strresult character varying DEFAULT ''::character varying, v_merchantname character varying DEFAULT ''::character varying, v_searchvaluesubcategory character varying DEFAULT ''::character varying, v_plid integer DEFAULT 0) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_query text;
  v_minindex INT;
  v_maxindex INT;
BEGIN
  IF (v_mode = 1) THEN
  v_query := '';
  v_minindex := (v_startrowindex - 1) * v_maxrows + 1;
  v_maxindex := v_startrowindex * v_maxrows;
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp (ROWNUMBER BIGINT PRIMARY KEY,  
  TUIELID BIGINT,  
  ActivityByUser varchar(1000),  
  ActivityDate varchar(100),  
  ExcelFile text,  
  Status INT,  
  ActivityByUserId varchar(100),
  Companyname varchar(200)  ,
  CategoryName varchar(100),
  Categoryid int,
  SubCategoryName varchar(100),
  SubCategoryid int,
  TotalRecord int,
  SubSubCategoryName varchar(100),
  SubSubCategoryid int,
  TotalerrorRecord int,
  QCSTATUS INT,
  PENDINGSELLING INT,
  LISTINGCREATED INT,
  Requestid varchar(500),
  SENDTOQC Bigint,
  MerchantName VARCHAR(1000)) ON COMMIT DROP;
  v_query := 'INSERT INTO #TEMP select ROW_NUMBER() OVER (ORDER BY TUIELID DESC) as ROWNUMBER, TUIELID,
 ActivityByUser,convert(Date, ActivityDate,105) AS ActivityDate,
	 ExcelFile, tue.Status,ActivityByUserId,PM.COMPANYNAME,pc.CATNAME as CategoryName,pc.catid as Categoryid,
	 ps.SCATNAME as SubCategoryName, ps.SCATID as SubCategoryid, TotalRecord,
	 km.KEYWORDNAME as SubSubCategoryName ,km.KMID as SubSubCategoryid
	 ,tue.TotalerrorRecord,(select count(1) from IMS_SubProduct_Temp where ismerchantstatus=0 and productentry=isnull(tue.Requestid,'''')) as QCSTATUS,
	 (select count(1) from IMS_SubProduct_Temp where ismerchantstatus=5 and productentry=isnull(tue.Requestid,'''')) AS PENDINGSELLING,
	 (select count(1) from IMS_SubProduct_Temp where ismerchantstatus=2 and productentry=isnull(tue.Requestid,'''')) AS LISTINGCREATED,
	 isnull(tue.Requestid,''''),
	 (select count(1) from IMS_SubProduct_Temp where ismerchantstatus=4 and IsVerified=0 and productentry=isnull(tue.Requestid,'''')) AS SENDTOQC,
	 ISNULL((PM.COMPANYNAME),'''') as MerchantName
	 From  Tbl_UploadedIWalletExcelLog tue   left join PRODUCT_CATEGORY pc on
	 pc.CATID=tue.Maincategorid
	 left join PRODUCT_SUBCATEGORY ps on ps.SCATID=tue.categoryid
	 left join KEYWORD_MASTER km on km.KMID=tue.Subcategoryid
	 left join PORTAL_MASTER PM on  tue.ACTIVITYBYUSERID=PM.PLID  
	 left join PORTAL_LOGIN PL5 on  PL5.PLID=PM.PLID 
	 WHERE tue.STATUS = 1';
  IF (v_plid > 0) THEN
  v_query := v_query || (' AND PL5.PLID = ' || CAST(v_plid AS VARCHAR(30)));
  END IF;
  IF (v_filename <> '') THEN
  v_query := v_query || (' AND ExcelFile LIKE ''%' || v_filename || '%'' ');
  END IF;
  IF (v_byuserid <> '') THEN
  v_query := v_query || (' AND ActivityByUserId = ''' || v_byuserid || ''' ');
  END IF;
  IF (v_maincatid <> '') THEN
  v_query := v_query || (' AND pc.catid = ''' || CAST(v_maincatid AS VARCHAR(30)) || ''' ');
  END IF;
  IF (v_catid <> '') THEN
  v_query := v_query || (' AND ps.SCATID = ''' || CAST(v_catid AS VARCHAR(30)) || ''' ');
  END IF;
  IF (v_subcatid <> '') THEN
  v_query := v_query || (' AND km.KMID = ''' || CAST(v_subcatid AS VARCHAR(30)) || ''' ');
  END IF;
  IF (v_searchvaluesubcategory <> '') THEN
  v_searchvaluesubcategory := REPLACE(v_searchvaluesubcategory, '''', '''''');
  v_query := v_query || 'AND km.KEYWORDNAME LIKE''%' || v_searchvaluesubcategory || '%''';
  END IF;
  IF (v_merchantname <> '') THEN
  v_query := v_query || ' AND (PM.COMPANYNAME) LIKE ''%' || v_merchantname || '%'' ';
  END IF;
  IF ((v_fromdate <> '') AND (v_todate = '')) THEN
  v_query := v_query || 'and CONVERT(Date, ActivityDate, 105) between  CONVERT(varchar(100), ''' || v_fromdate || ''', 105) and  CONVERT(Date, dbo.fun_getCurrentDate(), 105)';
  END IF;
  IF (v_fromdate = '' AND v_todate <> '') THEN
  v_query := v_query || 'and CONVERT(Date, ActivityDate, 105) between  CONVERT(varchar(100), ''' || v_todate || ''', 105) and  CONVERT(Date, dbo.fun_getCurrentDate(), 105)';
  END IF;
  IF (v_fromdate <> '' AND v_todate <> '') THEN
  v_query := v_query || 'and CONVERT(Date, ActivityDate, 105) between  CONVERT(varchar(100), ''' || v_fromdate || ''', 105) and  CONVERT(varchar(100), ''' || v_todate || ''', 105)';
  END IF;
  -- SET option (removed)
  EXECUTE v_query;
  RETURN QUERY SELECT * FROM tmp_temp WHERE rownumber BETWEEN v_minindex AND v_maxindex;
  SELECT COUNT(1) INTO v_totalcount FROM tmp_temp;
  -- SET option (removed)
  DROP TABLE IF EXISTS tmp_temp;
  END IF;
END;
$$;


--
-- Name: usp_businesslisting(text, text, text, integer, text, character varying, character varying, character varying, integer, integer, integer, character varying, character varying, character varying, numeric, character varying, character varying, character varying, character varying, character varying, character varying, character varying, character varying, integer, integer, integer, text, character varying, bigint, character varying, character varying, character varying, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_businesslisting(v_autocatid text DEFAULT ''::text, v_keyid text DEFAULT NULL::text, v_companyname text DEFAULT ''::text, v_optid integer DEFAULT 0, v_phoneno text DEFAULT ''::text, v_building character varying DEFAULT ''::character varying, v_landmark character varying DEFAULT ''::character varying, v_comemailid character varying DEFAULT ''::character varying, v_cid integer DEFAULT 0, v_sid integer DEFAULT 0, v_ctid integer DEFAULT 0, v_aid character varying DEFAULT ''::character varying, v_yearofestable character varying DEFAULT ''::character varying, v_cperwebsite character varying DEFAULT ''::character varying, v_annualturnover numeric DEFAULT 0, v_noofemployee character varying DEFAULT ''::character varying, v_businessstatus character varying DEFAULT ''::character varying, v_cpertitle character varying DEFAULT ''::character varying, v_cperdesignation character varying DEFAULT ''::character varying, v_cpermobileno character varying DEFAULT ''::character varying, v_cperemailid character varying DEFAULT ''::character varying, v_firstname character varying DEFAULT ''::character varying, v_lastname character varying DEFAULT ''::character varying, v_accounttype integer DEFAULT 0, INOUT v_intresult integer DEFAULT NULL::integer, v_pmtid integer DEFAULT 0, v_catid text DEFAULT ''::text, v_pincode character varying DEFAULT ''::character varying, v_intro_refid bigint DEFAULT 0, v_passworduser character varying DEFAULT ''::character varying, v_username character varying DEFAULT ''::character varying, v_ipaddress character varying DEFAULT ''::character varying, v_sugessmode integer DEFAULT 0) RETURNS integer
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_catnameforupdate varchar(100);
  v_index1 int;
  v_slice1 varchar(100);
  v_pmid int;
  v_keywordname varchar(100);
  v_categoryname varchar(100);
  v_scatid int;
  v_scategoryname varchar(100);
  v_introregno bigint;
  v_check int;
  v_password varchar(100);
  v_pmid1 bigint;
  v_packagename varchar(100);
  v_confirmpayid int;
  v_currency varchar(100);
  v_plid bigint;
  v_maxpayno int;
  v_err int;
  v_loginid varchar(100);
  v_upper bigint;
  v_lower bigint;
  v_count int;
  v_random bigint;
  v_originial_aid varchar(100);
BEGIN
  -- BEGIN TRAN (removed)
  SELECT COALESCE(aid, 0) INTO v_originial_aid FROM area_master WHERE areaname = v_aid AND pincode = v_pincode AND ctid = v_ctid AND cid = v_cid;
  v_intresult := 1;
  v_loginid := v_companyname;
  SELECT MAX(pmid) INTO v_pmid1 FROM portal_login;
  v_pmid1 := v_pmid1 + 1;
  v_lower := 11111111;
  v_upper := 99999999;
  SELECT ROUND(((v_upper - v_lower - 1) * RANDOM() + v_lower), 0) INTO v_random;
  v_password := CAST(v_random AS VARCHAR);
  v_loginid := CAST(v_cperemailid AS VARCHAR(100));
  SELECT currencysymbol INTO v_currency FROM tbl_currencymaster WHERE cid = v_cid;
  IF (v_pmtid > 0) THEN
  SELECT aid INTO v_originial_aid FROM portal_master_temp WHERE pmtid = v_pmtid;
  END IF;
  INSERT INTO portal_master (optid, companyname, mobileno, cid, sid, ctid, areaname, title, url, address, business_status, accounttype, active, pmtid, catid, keyid, pincode, lankmark, ismannual, comemailid, yearofestable, annualturnover, noofemployee, doc, autocatid, aid) VALUES (v_optid, v_companyname, v_phoneno, v_cid, v_sid, v_ctid, v_aid, v_companyname, v_cperwebsite, v_landmark, v_businessstatus, v_accounttype, 1, v_pmtid, v_catid, v_keyid, v_pincode, v_landmark, v_sugessmode, v_comemailid, v_yearofestable, v_annualturnover, v_noofemployee, GETUTCDATE() + INTERVAL '330 MI', v_autocatid, v_originial_aid);
  v_pmid := IDENT_CURRENT('portal_master');
  INSERT INTO portal_login (pmid, loginid, password, active, intro_refid, currencysymbol, cid, doc, username, ipaddress, title, designation, fname, lname, phone, cper_emailid) VALUES (v_pmid, v_loginid, v_passworduser, 1, v_intro_refid, v_currency, v_cid, GETUTCDATE() + INTERVAL '330 MI', v_username, v_ipaddress, v_cpertitle, v_cperdesignation, v_firstname, v_lastname, v_cpermobileno, v_cperemailid);
  v_plid := IDENT_CURRENT('portal_login');
  INSERT INTO ewallet (plid, amount, currencysymbol, active) VALUES (v_plid, 0, v_currency, 1);
  UPDATE portal_master SET plid = v_plid WHERE pmid = v_pmid;
  SELECT 0 INTO v_err;
  IF (v_err <> 0) THEN
  v_intresult := 0;
  -- ROLLBACK (removed)
  RETURN;
  END IF;
  -- COMMIT (removed)
END;
$$;


--
-- Name: usp_businesslisting_admin(integer, integer, character varying, boolean, character varying, character varying, character varying, character varying, integer, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_businesslisting_admin(v_startrowindex integer, v_maxrows integer, v_orderbyfield character varying, v_asc boolean, v_searchfield character varying, v_searchvalue character varying, v_fromdate character varying DEFAULT ''::character varying, v_todate character varying DEFAULT ''::character varying, v_mode integer DEFAULT NULL::integer, v_recordcount integer DEFAULT NULL::integer) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_regno bigint;
  v_pmid int;
  v_sqlquery text;
BEGIN
  -- SET option (removed)
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp (rowNumber bigint,

pmtid bigint,

companyname text,

loginID varchar(150),

password varchar(100),

doc varchar(35),

countryName varchar(50)) ON COMMIT DROP;
  v_sqlquery := '';
  v_sqlquery := 'insert into #temp select ROW_NUMBER() OVER(ORDER BY PMT.request_date desc) as rowNumber,PMT.pmtid,PMT.companyname,PLT.LoginId,PLT.Password,

convert(varchar, PMT.request_date, 105) as doc,c.countryName from portal_master_temp PMT join Portal_Login_temp PLT on PLT.pmtid=PMT.pmtid

 left join country C on PMT.cid=C.CID where isnull(PMT.cid,0)>0 ';
  IF (v_searchfield = 'SelectAll') THEN
  IF (v_fromdate = '' OR v_todate = '') THEN
  IF (v_fromdate <> '') THEN
  v_sqlquery := v_sqlquery || ' and convert(date, PMT.request_date,103) = replace(convert(VARCHAR(10),''' || v_fromdate || ''',111),''/'',''-'') ';
  END IF;
  IF (v_todate <> '') THEN
  v_sqlquery := v_sqlquery || ' and convert(date, PMT.request_date,103)  =replace(convert(VARCHAR(10),''' || v_todate || ''',111),''/'',''-'') ';
  END IF;
  END IF;
  IF (v_fromdate <> '' AND v_todate <> '') THEN
  v_sqlquery := v_sqlquery || ' and convert(date, PMT.request_date,103)  between  replace(convert(VARCHAR(10),''' || v_fromdate || ''',111),''/'',''-'')   and replace(convert(VARCHAR(10),''' || v_todate || ''',111),''/'',''-'') ';
  END IF;
  EXECUTE v_sqlquery;
  SELECT COUNT(*) INTO v_recordcount FROM tmp_temp;
  RETURN QUERY SELECT * FROM tmp_temp WHERE rownumber BETWEEN v_startrowindex AND v_maxrows;
  DROP TABLE IF EXISTS tmp_temp;
  RETURN QUERY SELECT v_recordcount AS recordcount;
  -- SET option (removed)
  RETURN;
  ELSE
  IF (v_fromdate = '' OR v_todate = '') THEN
  IF (v_fromdate <> '') THEN
  v_sqlquery := v_sqlquery || ' and convert(date,PMT.request_date,103) = replace(convert(VARCHAR(10),''' || v_fromdate || ''',111),''/'',''-'') ';
  END IF;
  IF (v_todate <> '') THEN
  v_sqlquery := v_sqlquery || ' and convert(date, PMT.request_date,103)  =replace(convert(VARCHAR(10),''' || v_todate || ''',111),''/'',''-'') ';
  END IF;
  END IF;
  IF (v_fromdate <> '' AND v_todate <> '') THEN
  v_sqlquery := v_sqlquery || ' and convert(date, PMT.request_date,103)  between  replace(convert(VARCHAR(10),''' || v_fromdate || ''',111),''/'',''-'')   and replace(convert(VARCHAR(10),''' || v_todate || ''',111),''/'',''-'') ';
  END IF;
  IF (v_searchfield = 'loginid') THEN
  v_sqlquery := v_sqlquery || 'and PLT.loginid like ''%' || v_searchvalue || '%''';
  END IF;
  IF (v_searchfield = 'companyname') THEN
  v_sqlquery := v_sqlquery || 'and PMT.companyname like ''%' || v_searchvalue || '%''';
  END IF;
  IF (v_searchfield = 'countryName') THEN
  v_sqlquery := v_sqlquery || 'and c.countryName like ''%' || v_searchvalue || '%''';
  END IF;
  END IF;
  EXECUTE v_sqlquery;
  SELECT COUNT(*) INTO v_recordcount FROM tmp_temp;
  RETURN QUERY SELECT * FROM tmp_temp WHERE rownumber BETWEEN v_startrowindex AND v_maxrows;
  DROP TABLE IF EXISTS tmp_temp;
  RETURN QUERY SELECT v_recordcount AS recordcount;
  -- SET option (removed)
END;
$$;


--
-- Name: usp_businesslistingforoperators(text, integer, text, character varying, character varying, character varying, integer, character varying, character varying, character varying, character varying, character varying, numeric, character varying, character varying, character varying, character varying, character varying, character varying, character varying, character varying, integer, integer, character varying, character varying, bigint, bigint, character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_businesslistingforoperators(v_companyname text DEFAULT ''::text, v_optid integer DEFAULT 0, v_phoneno text DEFAULT ''::text, v_building character varying DEFAULT ''::character varying, v_landmark character varying DEFAULT ''::character varying, v_comemailid character varying DEFAULT ''::character varying, v_cid integer DEFAULT 0, v_statename character varying DEFAULT ''::character varying, v_cityname character varying DEFAULT ''::character varying, v_aid character varying DEFAULT ''::character varying, v_yearofestable character varying DEFAULT ''::character varying, v_cperwebsite character varying DEFAULT ''::character varying, v_annualturnover numeric DEFAULT 0, v_noofemployee character varying DEFAULT ''::character varying, v_businessstatus character varying DEFAULT ''::character varying, v_cpertitle character varying DEFAULT ''::character varying, v_cperdesignation character varying DEFAULT ''::character varying, v_cpermobileno character varying DEFAULT ''::character varying, v_cperemailid character varying DEFAULT ''::character varying, v_firstname character varying DEFAULT ''::character varying, v_lastname character varying DEFAULT ''::character varying, v_accounttype integer DEFAULT 0, INOUT v_intresult integer DEFAULT NULL::integer, v_catid character varying DEFAULT ''::character varying, v_keyid character varying DEFAULT ''::character varying, INOUT v_maxpmid bigint DEFAULT NULL::bigint, INOUT v_maxplid bigint DEFAULT NULL::bigint, v_zipcode character varying DEFAULT ''::character varying) RETURNS record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_originial_aid varchar(100);
  v_outcatid text;
  v_catnameforupdate varchar(100);
  v_index1 int;
  v_slice1 varchar(100);
  v_pmid int;
  v_keywordname varchar(100);
  v_categoryname varchar(100);
  v_scatid int;
  v_scategoryname varchar(100);
  v_introregno bigint;
  v_check int;
  v_password varchar(100);
  v_pmid1 bigint;
  v_packagename varchar(100);
  v_confirmpayid int;
  v_maxpayno int;
  v_err int;
  v_loginid varchar(100);
  v_plid bigint;
  v_currency varchar(100);
  v_sid int;
  v_ctid int;
  v_upper bigint;
  v_lower bigint;
  v_count int;
  v_random bigint;
  v_passwordnew varchar(100);
BEGIN
  -- BEGIN TRAN (removed)
  v_outcatid := NULL;
  v_sid := 0;
  v_ctid := 0;
  v_lower := 11111111;
  v_upper := 99999999;
  SELECT ROUND(((v_upper - v_lower - 1) * RANDOM() + v_lower), 0) INTO v_random;
  v_passwordnew := CAST(v_random AS VARCHAR);
  SELECT v_outcat INTO v_outcatid FROM dbo.usp_findingunique_key_cat(v_inputkey => v_keyid, v_inputcat => v_catid, v_outcat => v_outcatid);
  IF (v_keyid = '0') THEN
  v_keyid := NULL;
  END IF;
  SELECT COALESCE(sid, 0) INTO v_sid FROM state WHERE RTRIM(LTRIM(statename)) = RTRIM(LTRIM(v_statename)) AND cid = v_cid;
  SELECT COALESCE(ctid, 0) INTO v_ctid FROM city WHERE RTRIM(LTRIM(cityname)) = RTRIM(LTRIM(v_cityname)) AND cid = v_cid AND sid = v_sid;
  SELECT COALESCE(aid, 0) INTO v_originial_aid FROM area_master WHERE areaname = v_aid AND pincode = v_zipcode AND ctid = v_ctid AND cid = v_cid;
  SELECT currencysymbol INTO v_currency FROM tbl_currencymaster WHERE cid = v_cid;
  v_intresult := 1;
  v_loginid := v_companyname;
  SELECT COUNT(*) INTO v_check FROM portal_login WHERE loginid = v_companyname;
  IF (v_check >= 1) THEN
  SELECT MAX(pmid) INTO v_pmid1 FROM portal_login;
  v_pmid1 := v_pmid1 + 1;
  v_password := CAST(v_companyname AS VARCHAR(100)) || CAST(v_pmid1 AS VARCHAR(100));
  v_loginid := CAST(v_companyname AS VARCHAR(100)) || CAST(v_pmid1 AS VARCHAR(100));
  ELSE
  v_password := v_companyname;
  END IF;
  IF NOT EXISTS(SELECT loginid FROM portal_login_temp WHERE RTRIM(LTRIM(COALESCE(loginid, ''))) = RTRIM(LTRIM(v_cperemailid))) AND NOT EXISTS(SELECT loginid FROM portal_login WHERE RTRIM(LTRIM(COALESCE(loginid, ''))) = RTRIM(LTRIM(v_cperemailid))) THEN
  INSERT INTO portal_master (companyname, mobileno, cid, sid, ctid, areaname, title, url, business_status, accounttype, active, catid, keyid, pmtid, address, lankmark, comemailid, yearofestable, annualturnover, noofemployee, doc, pincode, optid, autocatid, aid) VALUES (v_companyname, v_phoneno, v_cid, v_sid, v_ctid, v_aid, v_companyname, v_cperwebsite, v_businessstatus, v_accounttype, 1, v_catid, v_keyid, 0, v_building, v_landmark, v_comemailid, v_yearofestable, v_annualturnover, v_noofemployee, dbo.fun_getCurrentDate(), v_zipcode, v_optid, v_outcatid, v_originial_aid);
  v_pmid := IDENT_CURRENT('portal_master');
  v_maxpmid := v_pmid;
  INSERT INTO portal_login (pmid, loginid, password, active, currencysymbol, cid, doc) VALUES (v_pmid, v_cperemailid, v_passwordnew, 1, v_currency, v_cid, dbo.fun_getCurrentDate());
  v_plid := IDENT_CURRENT('Portal_Login');
  v_maxplid := v_plid;
  END IF;
  SELECT 0 INTO v_err;
  IF (v_err <> 0) THEN
  v_intresult := 0;
  -- ROLLBACK (removed)
  RETURN;
  END IF;
  -- COMMIT (removed)
END;
$$;


