CREATE FUNCTION dbo.usp_businesslistingforportalpanel_new(v_companyname text DEFAULT ''::text, v_phoneno text DEFAULT ''::text, v_building character varying DEFAULT ''::character varying, v_landmark character varying DEFAULT ''::character varying, v_comemailid character varying DEFAULT ''::character varying, v_statename character varying DEFAULT ''::character varying, v_cityname character varying DEFAULT ''::character varying, v_aid character varying DEFAULT ''::character varying, v_yearofestable character varying DEFAULT ''::character varying, v_cperwebsite character varying DEFAULT ''::character varying, v_noofemployee character varying DEFAULT ''::character varying, v_catid text DEFAULT ''::text, v_pincode character varying DEFAULT ''::character varying, v_companyimage character varying DEFAULT ''::character varying, v_plid bigint DEFAULT 14, v_comdesc text DEFAULT ''::text, v_headerimagename text DEFAULT ''::text, INOUT v_strresult character varying DEFAULT ''::character varying, INOUT v_maxpmid bigint DEFAULT 0, v_keyid text DEFAULT ''::text, v_ismannual integer DEFAULT 0, v_subcatid text DEFAULT ''::text, v_pick_state character varying DEFAULT ''::character varying, v_pick_city character varying DEFAULT ''::character varying, v_pick_area character varying DEFAULT ''::character varying, v_pick_pincode character varying DEFAULT ''::character varying, v_pick_address character varying DEFAULT ''::character varying, v_pick_landmark character varying DEFAULT ''::character varying, v_gstno character varying DEFAULT ''::character varying, v_tanno character varying DEFAULT ''::character varying, v_cinno character varying DEFAULT ''::character varying, v_country character varying DEFAULT ''::character varying, v_pick_country character varying DEFAULT ''::character varying, v_classificationtypeid character varying DEFAULT ''::character varying, v_classificationdescription character varying DEFAULT ''::character varying, v_storetypeid integer DEFAULT 0, v_alldeliverypincode character varying DEFAULT ''::character varying, v_facebook character varying DEFAULT ''::character varying, v_twitter character varying DEFAULT ''::character varying, v_youtube character varying DEFAULT ''::character varying, v_linkdin character varying DEFAULT ''::character varying, v_telegram character varying DEFAULT ''::character varying, v_whatsappgrouplink character varying DEFAULT ''::character varying, v_instagram character varying DEFAULT ''::character varying, v_wechat character varying DEFAULT ''::character varying, v_distributorid integer DEFAULT 0) RETURNS record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_originial_aid VARCHAR(100);
  v_outcatid text;
  v_catnameforupdate VARCHAR(100);
  v_index1 INT;
  v_slice1 VARCHAR(100);
  v_pmid INT;
  v_keywordname VARCHAR(100);
  v_categoryname VARCHAR(100);
  v_scatid INT;
  v_scategoryname VARCHAR(100);
  v_check INT;
  v_password VARCHAR(100);
  v_err INT;
  v_loginid VARCHAR(100);
  v_currency VARCHAR(100);
  v_sid INT;
  v_ctid INT;
  v_conemaiid VARCHAR(100);
  v_accounttype INT;
  v_pmidtemp BIGINT;
  v_cid INT;
  v_cpertitle VARCHAR(100);
  v_cperdesignation VARCHAR(100);
  v_cpermobileno VARCHAR(100);
  v_firstname VARCHAR(100);
  v_lastname VARCHAR(100);
  v_sid_old INT;
  v_ctid_old INT;
  v_areaname_old VARCHAR(150);
  v_ccid INT;
  v_ctidd int;
  v_pickstatename varchar(100);
  v_pickcity varchar(100);
  v_ssid int;
  v_did int;
  v_p_country VARCHAR(1000);
  v_listingstatus INT;
  v_introplid INT;
  v_dailytotalbusinesslisting BigInt;
  v_maxnoofbusinesslistingperday BigInt;
BEGIN
  -- BEGIN TRAN (removed)
  IF EXISTS(SELECT 1 FROM portal_master WHERE REPLACE(companyname, ' ', '') = REPLACE(v_companyname, ' ', '') AND plid <> v_plid) THEN
  v_strresult := 'Already Exist';
  -- ROLLBACK (removed)
  RETURN;
  END IF;
  IF EXISTS(SELECT 1 FROM portal_master WHERE gstno = v_gstno AND plid <> v_plid) THEN
  v_strresult := 'GST Number Already Exist';
  -- ROLLBACK (removed)
  RETURN;
  END IF;
  v_outcatid := NULL;
  v_sid := 0;
  v_ctid := 0;
  v_cpertitle := '';
  v_cperdesignation := '';
  v_cpermobileno := '';
  v_firstname := '';
  v_lastname := '';
  v_pickstatename := '';
  v_pickcity := '';
  v_ssid := 0;
  v_did := 0;
  v_p_country := '';
  v_companyname := REPLACE(REPLACE(REPLACE(v_companyname, '.', ''), ',', ''), '@', '');
  SELECT cid, COALESCE(pmid, 0) INTO v_cid, v_pmidtemp FROM portal_login WHERE plid = v_plid;
  SELECT v_outcat INTO v_outcatid FROM dbo.usp_findingunique_key_cat(v_inputkey => v_keyid, v_inputcat => v_catid, v_outcat => v_outcatid);
  SELECT COALESCE(sid, 0) INTO v_sid FROM state WHERE RTRIM(LTRIM(statename)) = RTRIM(LTRIM(v_statename));
  IF (v_sid = 0) THEN
  SELECT MAX(sid) INTO v_ssid FROM state;
  v_ssid := v_ssid + 1;
  INSERT INTO state (sid, cid, statename, sactive) VALUES (v_ssid, 96, v_statename, 1);
  SELECT COALESCE(sid, 0) INTO v_sid FROM state WHERE RTRIM(LTRIM(statename)) = RTRIM(LTRIM(v_statename));
  END IF;
  SELECT COALESCE(cid, 0) INTO v_ccid FROM state WHERE RTRIM(LTRIM(statename)) = RTRIM(LTRIM(v_statename));
  SELECT COALESCE(ctid, 0) INTO v_ctid FROM city WHERE RTRIM(LTRIM(cityname)) = RTRIM(LTRIM(v_cityname));
  IF (v_ctid = 0) THEN
  SELECT MAX(ctid) INTO v_ctidd FROM city;
  v_ctidd := v_ctidd + 1;
  INSERT INTO city (ctid, cid, sid, cityname, active) VALUES (v_ctidd, v_ccid, v_sid, v_cityname, 1);
  SELECT COALESCE(ctid, 0) INTO v_ctid FROM city WHERE RTRIM(LTRIM(cityname)) = RTRIM(LTRIM(v_cityname));
  END IF;
  IF (ISNUMERIC(v_pick_state) > 0) THEN
  SELECT statename INTO v_pickstatename FROM state WHERE sid = v_pick_state;
  v_pick_state := v_pickstatename;
  ELSE
  v_pick_state := v_pick_state;
  END IF;
  IF (ISNUMERIC(v_pick_city) > 0) THEN
  SELECT cityname INTO v_pickcity FROM city WHERE ctid = v_pick_city;
  v_pick_city := v_pickcity;
  ELSE
  v_pick_city := v_pick_city;
  END IF;
  SELECT COALESCE(aid, 0) INTO v_originial_aid FROM area_master WHERE areaname = v_aid AND pincode = v_pincode AND ctid = v_ctid AND cid = v_cid;
  v_sid_old := v_sid;
  v_ctid_old := v_ctid;
  v_areaname_old := v_aid;
  IF (v_sid = 0) THEN
  v_maxpmid := 0;
  v_strresult := 'State Not Selected..!';
  -- ROLLBACK (removed)
  RETURN;
  END IF;
  SELECT loginid INTO v_conemaiid FROM portal_login WHERE plid = v_plid;
  v_strresult := 'Ok';
  v_accounttype := 0;
  IF (v_ismannual = 1) THEN
  v_aid := NULL;
  END IF;
  IF NOT EXISTS(SELECT 1 FROM portal_master WHERE plid = v_plid) THEN
  INSERT INTO portal_master (companyname, mobileno, cid, sid, ctid, areaname, title, url, business_status, active, catid, keyid, pmtid, address, companydesc, lankmark, comemailid, yearofestable, noofemployee, companyimage, doc, pincode, autocatid, aid, ismannual, plid, isverified, headerimage, subcatid, pick_state, pick_city, pick_area, pick_pincode, pick_address, pick_landmark, gstno, tanno, cinno, country, state, city, pick_country, classificationdescription, storetypeid, facebook, twitter, youtube, linkdin, telegram, whatsappgrouplink, instagram, wechat, alldeliverypincode, classificationtypeid, distributorid) VALUES (v_companyname, v_phoneno, v_cid, v_sid, v_ctid, v_aid, v_companyname, v_cperwebsite, 'YES', 1, v_catid, v_keyid, 0, v_building, v_comdesc, v_landmark, v_comemailid, v_yearofestable, v_noofemployee, v_companyimage, dbo.FUN_GETCURRENTDATE(), v_pincode, v_outcatid, v_originial_aid, v_ismannual, v_plid, 0, v_headerimagename, v_subcatid, v_pick_state, v_pick_city, v_pick_area, v_pick_pincode, v_pick_address, v_pick_landmark, v_gstno, v_tanno, v_cinno, v_country, v_statename, v_cityname, v_pick_country, v_classificationdescription, v_storetypeid, v_facebook, v_twitter, v_youtube, v_linkdin, v_telegram, v_whatsappgrouplink, v_instagram, v_wechat, v_alldeliverypincode, v_classificationtypeid, v_distributorid);
  SELECT country INTO v_p_country FROM portal_master WHERE plid = v_plid;
  SELECT COALESCE(did, 0) INTO v_did FROM portal_login WHERE plid = v_plid;
  IF (v_did = 0) THEN
  SELECT ds.did INTO v_did FROM distributor_master AS dm INNER JOIN tbl_distributor AS ds ON dm.pmid = ds.pmid WHERE dm.country = v_p_country LIMIT 1;
  UPDATE portal_login SET did = v_did WHERE plid = v_plid;
  END IF;
  v_listingstatus := 0;
  SELECT listingstatus INTO v_listingstatus FROM tbl_datewisecommonroiaccount WHERE CAST(date AS DATE) = CAST(dbo.FUN_GETCURRENTDATE() AS DATE);
  IF (v_listingstatus <> 0) THEN
  v_introplid := 0;
  SELECT COALESCE(intro_refid, 0) INTO v_introplid FROM portal_login WHERE plid = v_plid;
  IF (v_introplid > 1) THEN
  UPDATE tbl_dailytasklimits SET submittednoofbusinesslisting = submittednoofbusinesslisting + 1, remainnoofbusinesslisting = remainnoofbusinesslisting + (CASE WHEN remainnoofbusinesslisting > 0 THEN 1 ELSE 0 END) WHERE plid = v_plid AND CAST(date AS DATE) = CAST(dbo.FUN_GETCURRENTDATE() AS DATE);
  UPDATE tbl_datewisecommonroiaccount SET totallisting = COALESCE(totallisting, 0) + 1 WHERE CAST(date AS DATE) = CAST(dbo.FUN_GETCURRENTDATE() AS DATE);
  v_dailytotalbusinesslisting := 0;
  v_maxnoofbusinesslistingperday := 0;
  SELECT totallisting, maxnoofbusinesslistingperday INTO v_dailytotalbusinesslisting, v_maxnoofbusinesslistingperday FROM tbl_datewisecommonroiaccount WHERE CAST(date AS DATE) = CAST(dbo.FUN_GETCURRENTDATE() AS DATE);
  IF (v_dailytotalbusinesslisting >= v_maxnoofbusinesslistingperday) THEN
  UPDATE tbl_datewisecommonroiaccount SET listingstatus = 0 WHERE CAST(date AS DATE) = CAST(dbo.FUN_GETCURRENTDATE() AS DATE);
  END IF;
  END IF;
  END IF;
  ELSE
  UPDATE portal_master SET companyname = v_companyname, mobileno = v_phoneno, cid = v_cid, sid = v_sid, ctid = v_ctid, areaname = v_aid, title = v_companyname, url = v_cperwebsite, business_status = 'YES', active = 1, catid = v_catid, keyid = v_keyid, pmtid = 0, address = v_building, companydesc = v_comdesc, lankmark = v_landmark, comemailid = v_comemailid, yearofestable = v_yearofestable, noofemployee = v_noofemployee, companyimage = v_companyimage, pincode = v_pincode, autocatid = v_outcatid, aid = v_originial_aid, ismannual = v_ismannual, headerimage = (CASE WHEN v_headerimagename = '' THEN headerimage ELSE v_headerimagename END), subcatid = v_subcatid, isverified = 1, pick_state = v_pick_state, pick_city = v_pick_city, pick_area = v_pick_area, pick_pincode = v_pick_pincode, pick_address = v_pick_address, pick_landmark = v_pick_landmark, gstno = v_gstno, tanno = v_tanno, cinno = v_cinno, country = v_country, state = v_statename, city = v_cityname, pick_country = v_pick_country, classificationdescription = v_classificationdescription, storetypeid = v_storetypeid, facebook = v_facebook, twitter = v_twitter, youtube = v_youtube, linkdin = v_linkdin, telegram = v_telegram, whatsappgrouplink = v_whatsappgrouplink, instagram = v_instagram, wechat = v_wechat, alldeliverypincode = v_alldeliverypincode, classificationtypeid = v_classificationtypeid, distributorid = v_distributorid WHERE plid = v_plid;
  SELECT country INTO v_p_country FROM portal_master WHERE plid = v_plid;
  SELECT COALESCE(did, 0) INTO v_did FROM portal_login WHERE plid = v_plid;
  IF (v_did = 0) THEN
  SELECT ds.did INTO v_did FROM distributor_master AS dm INNER JOIN tbl_distributor AS ds ON dm.pmid = ds.pmid WHERE dm.country = v_p_country LIMIT 1;
  UPDATE portal_login SET did = v_did WHERE plid = v_plid;
  END IF;
  v_strresult := 'Updated';
  v_maxpmid := 0;
  -- COMMIT (removed)
  RETURN;
  END IF;
  v_pmid := IDENT_CURRENT('PORTAL_MASTER');
  v_maxpmid := v_pmid;
  UPDATE portal_login SET pmid = v_maxpmid WHERE plid = v_plid;
  IF (v_ismannual = 1) THEN
  INSERT INTO suggestedarea_master (cid, sid, ctid, areaname, active, isdeleted, pmtid, pmid, pincode) VALUES (v_cid, v_sid_old, v_ctid_old, v_areaname_old, 1, 0, 0, v_pmid, v_pincode);
  END IF;
  SELECT 0 INTO v_err;
  IF (v_err <> 0) THEN
  v_maxpmid := 0;
  v_strresult := 'Some Error Occured, Please Try Again..!';
  -- ROLLBACK (removed)
  RETURN;
  END IF;
  -- COMMIT (removed)
END;
$$;


