  v_index1 INT;
  v_slice1 VARCHAR(100);
  v_pmid INT;
  v_keywordname VARCHAR(100);
  v_categoryname VARCHAR(100);
  v_scatid INT;
  v_scategoryname VARCHAR(100);
  v_check INT;
  v_password VARCHAR(100);
  v_err INT;
  v_loginid VARCHAR(100);
  v_currency VARCHAR(100);
  v_sid INT;
  v_ctid INT;
  v_conemaiid VARCHAR(100);
  v_accounttype INT;
  v_pmidtemp BIGINT;
  v_cid INT;
  v_cpertitle VARCHAR(100);
  v_cperdesignation VARCHAR(100);
  v_cpermobileno VARCHAR(100);
  v_firstname VARCHAR(100);
  v_lastname VARCHAR(100);
  v_sid_old INT;
  v_ctid_old INT;
  v_areaname_old VARCHAR(150);
  v_companysid INT;
  v_companycid INT;
  v_companyctid INT;
  v_ssid Int;
  v_ctidd Int;
  v_listingstatus INT;
  v_introplid INT;
  v_dailytotalbusinesslisting BigInt;
  v_maxnoofbusinesslistingperday BigInt;
BEGIN
  -- BEGIN TRAN (removed)
  IF EXISTS(SELECT 1 FROM distributor_master WHERE REPLACE(companyname, ' ', '') = REPLACE(v_companyname, ' ', '') AND plid <> v_plid) THEN
  v_strresult := 'Already Exist';
  -- ROLLBACK (removed)
  RETURN;
  END IF;
  IF EXISTS(SELECT 1 FROM distributor_master WHERE REPLACE(gstno, ' ', '') = REPLACE(v_gstno, ' ', '') AND plid <> v_plid) THEN
  v_strresult := '2';
  -- ROLLBACK (removed)
  RETURN;
  END IF;
  IF EXISTS(SELECT 1 FROM distributor_master WHERE REPLACE(cinno, ' ', '') = REPLACE(v_cinno, ' ', '') AND plid <> v_plid) THEN
  v_strresult := '4';
  -- ROLLBACK (removed)
  RETURN;
  END IF;
  IF EXISTS(SELECT 1 FROM distributor_master WHERE REPLACE(companydetailname, ' ', '') = REPLACE(v_companyinfoname, ' ', '') AND plid <> v_plid) THEN
  v_strresult := 'Company Name Already Exist';
  -- ROLLBACK (removed)
  RETURN;
  END IF;
  v_outcatid := NULL;
  v_sid := 0;
  v_ctid := 0;
  v_cpertitle := '';
  v_cperdesignation := '';
  v_cpermobileno := '';
  v_firstname := '';
  v_lastname := '';
  v_companyname := REPLACE(REPLACE(REPLACE(v_companyname, '.', ''), ',', ''), '@', '');
  SELECT cid INTO v_cid FROM country WHERE countryname = v_country;
  SELECT cid INTO v_companycid FROM country WHERE countryname = v_companycountry;
  SELECT COALESCE(pmid, 0) INTO v_pmidtemp FROM tbl_distributor WHERE did = v_plid;
  SELECT v_outcat INTO v_outcatid FROM dbo.usp_findingunique_key_cat(v_inputkey => v_keyid, v_inputcat => v_catid, v_outcat => v_outcatid);
  SELECT COALESCE(MAX(sid), 0) INTO v_sid FROM state WHERE RTRIM(LTRIM(statename)) = RTRIM(LTRIM(v_statename)) AND cid = v_cid;
  IF (v_sid = 0) THEN
  v_ssid := 0;
  SELECT MAX(sid) INTO v_ssid FROM state;
  v_ssid := v_ssid + 1;
  INSERT INTO state (sid, cid, statename, sactive) VALUES (v_ssid, v_cid, v_statename, 1);
  SELECT COALESCE(sid, 0) INTO v_sid FROM state WHERE RTRIM(LTRIM(statename)) = RTRIM(LTRIM(v_statename)) AND cid = v_cid;
  END IF;
  SELECT COALESCE(MAX(ctid), 0) INTO v_ctid FROM city WHERE RTRIM(LTRIM(cityname)) = RTRIM(LTRIM(v_cityname)) AND cid = v_cid AND sid = v_sid;
  IF (v_ctid = 0) THEN
  v_ctidd := 0;
  SELECT MAX(ctid) INTO v_ctidd FROM city;
  v_ctidd := v_ctidd + 1;
  INSERT INTO city (ctid, cid, sid, cityname, active) VALUES (v_ctidd, v_cid, v_sid, v_cityname, 1);
  SELECT COALESCE(ctid, 0) INTO v_ctid FROM city WHERE RTRIM(LTRIM(cityname)) = RTRIM(LTRIM(v_cityname)) AND cid = v_cid AND sid = v_sid;
  END IF;
  SELECT COALESCE(MAX(sid), 0) INTO v_companysid FROM state WHERE RTRIM(LTRIM(statename)) = RTRIM(LTRIM(v_companystatename)) AND cid = v_companycid;
  IF (v_companysid = 0) THEN
  SELECT 0 INTO v_ssid;
  SELECT MAX(sid) INTO v_ssid FROM state;
  v_ssid := v_ssid + 1;
  INSERT INTO state (sid, cid, statename, sactive) VALUES (v_ssid, v_companycid, v_companystatename, 1);
  SELECT COALESCE(sid, 0) INTO v_companysid FROM state WHERE RTRIM(LTRIM(statename)) = RTRIM(LTRIM(v_companystatename)) AND cid = v_companycid;
  END IF;
  SELECT COALESCE(MAX(ctid), 0) INTO v_companyctid FROM city WHERE RTRIM(LTRIM(cityname)) = RTRIM(LTRIM(v_companycityname)) AND cid = v_companycid AND sid = v_companysid;
  IF (v_companyctid = 0) THEN
  SELECT 0 INTO v_ctidd;
  SELECT MAX(ctid) INTO v_ctidd FROM city;
  v_ctidd := v_ctidd + 1;
  INSERT INTO city (ctid, cid, sid, cityname, active) VALUES (v_ctidd, v_companycid, v_companysid, v_companycityname, 1);
  SELECT COALESCE(ctid, 0) INTO v_companyctid FROM city WHERE RTRIM(LTRIM(cityname)) = RTRIM(LTRIM(v_companycityname)) AND cid = v_companycid AND sid = v_companysid;
  END IF;
  v_companysid := COALESCE(v_companysid, 0);
  v_companyctid := COALESCE(v_companyctid, 0);
  SELECT COALESCE(aid, 0) INTO v_originial_aid FROM area_master WHERE areaname = v_aid AND pincode = v_pincode AND ctid = v_ctid AND cid = v_cid;
  v_sid_old := v_sid;
  v_ctid_old := v_ctid;
  v_areaname_old := v_aid;
  IF (v_sid = 0) THEN
  v_maxpmid := 0;
  END IF;
  IF (v_ctid = 0) THEN
  v_maxpmid := 0;
  END IF;
  SELECT loginid INTO v_conemaiid FROM distributor_login WHERE did = v_plid;
  v_strresult := 'Ok';
  v_accounttype := 0;
  IF (v_ismannual = 1) THEN
  v_aid := NULL;
  END IF;
  IF NOT EXISTS(SELECT 1 FROM distributor_master WHERE plid = v_plid) THEN
  INSERT INTO distributor_master (companyname, mobileno, cid, sid, ctid, areaname, title, url, business_status, active, catid, keyid, pmtid, address, companydesc, lankmark, comemailid, yearofestable, noofemployee, companyimage, doc, pincode, autocatid, aid, ismannual, plid, isverified, headerimage, subcatid, pick_state, pick_city, pick_area, pick_pincode, pick_address, pick_landmark, gstno, tanno, cinno, faviconicon, companydetailname, companygstin, companytan, companycin, companyaddress, companypincode, companysid, companyctid, contact_person_designation, contact_person_name, country, companycountry) VALUES (v_companyname, v_phoneno, v_cid, v_sid, v_ctid, v_aid, v_companyname, v_cperwebsite, 'YES', 1, v_catid, v_keyid, 0, v_building, v_comdesc, v_landmark, v_comemailid, v_yearofestable, v_noofemployee, v_companyimage, dbo.FUN_GETCURRENTDATE(), v_pincode, v_outcatid, v_originial_aid, v_ismannual, v_plid, 0, v_headerimagename, v_subcatid, v_pick_state, v_pick_city, v_pick_area, v_pick_pincode, v_pick_address, v_pick_landmark, v_gstno, v_tanno, v_cinno, v_faviconicon, v_companyinfoname, v_companygst, v_companytan, v_companycin, v_companyaddress, v_companypincode, v_companysid, v_companyctid, v_contactperson, v_contactpersonname, v_country, v_companycountry);
  v_listingstatus := 0;
  SELECT listingstatus INTO v_listingstatus FROM tbl_datewisecommonroiaccount WHERE CAST(date AS DATE) = CAST(dbo.FUN_GETCURRENTDATE() AS DATE);
  IF (v_listingstatus <> 0) THEN
  v_introplid := 0;
  SELECT COALESCE(intro_refid, 0) INTO v_introplid FROM tbl_distributor WHERE did = v_plid;
  IF (v_introplid > 1) THEN
  UPDATE tbl_dailytasklimits SET submittednoofbusinesslisting = submittednoofbusinesslisting + 1, remainnoofbusinesslisting = remainnoofbusinesslisting + (CASE WHEN remainnoofbusinesslisting > 0 THEN 1 ELSE 0 END) WHERE plid = v_plid AND CAST(date AS DATE) = CAST(dbo.FUN_GETCURRENTDATE() AS DATE);
  UPDATE tbl_datewisecommonroiaccount SET totallisting = COALESCE(totallisting, 0) + 1 WHERE CAST(date AS DATE) = CAST(dbo.FUN_GETCURRENTDATE() AS DATE);
  v_dailytotalbusinesslisting := 0;
  v_maxnoofbusinesslistingperday := 0;
  SELECT totallisting, maxnoofbusinesslistingperday INTO v_dailytotalbusinesslisting, v_maxnoofbusinesslistingperday FROM tbl_datewisecommonroiaccount WHERE CAST(date AS DATE) = CAST(dbo.FUN_GETCURRENTDATE() AS DATE);
  IF (v_dailytotalbusinesslisting >= v_maxnoofbusinesslistingperday) THEN
  UPDATE tbl_datewisecommonroiaccount SET listingstatus = 0 WHERE CAST(date AS DATE) = CAST(dbo.FUN_GETCURRENTDATE() AS DATE);
  END IF;
  END IF;
  END IF;
  ELSE
  UPDATE distributor_master SET companyname = v_companyname, mobileno = v_phoneno, cid = v_cid, sid = v_sid, ctid = v_ctid, areaname = v_aid, title = v_companyname, url = v_cperwebsite, business_status = 'YES', active = 1, catid = v_catid, keyid = v_keyid, pmtid = 0, address = v_building, companydesc = v_comdesc, lankmark = v_landmark, comemailid = v_comemailid, yearofestable = v_yearofestable, noofemployee = v_noofemployee, companyimage = v_companyimage, pincode = v_pincode, autocatid = v_outcatid, aid = v_originial_aid, ismannual = v_ismannual, headerimage = (CASE WHEN v_headerimagename = '' THEN headerimage ELSE v_headerimagename END), subcatid = v_subcatid, isverified = 0, pick_state = v_pick_state, pick_city = v_pick_city, pick_area = v_pick_area, pick_pincode = v_pick_pincode, pick_address = v_pick_address, pick_landmark = v_pick_landmark, gstno = v_gstno, tanno = v_tanno, cinno = v_cinno, faviconicon = v_faviconicon, companydetailname = v_companyinfoname, companyctid = v_companyctid, companycin = v_companycin, companygstin = v_companygst, companypincode = v_companypincode, companytan = v_companytan, companyaddress = v_companyaddress, companysid = v_companysid, contact_person_designation = v_contactperson, contact_person_name = v_contactpersonname, country = v_country, companycountry = v_companycountry WHERE plid = v_plid;
  v_strresult := 'Updated';
  v_maxpmid := 0;
  -- COMMIT (removed)
  RETURN;
  END IF;
  v_pmid := IDENT_CURRENT('DISTRIBUTOR_MASTER');
  v_maxpmid := v_pmid;
  UPDATE tbl_distributor SET pmid = v_maxpmid WHERE did = v_plid;
  IF (v_ismannual = 1) THEN
  INSERT INTO suggestedarea_master (cid, sid, ctid, areaname, active, isdeleted, pmtid, pmid, pincode) VALUES (v_cid, v_sid_old, v_ctid_old, v_areaname_old, 1, 0, 0, v_pmid, v_pincode);
  END IF;
  SELECT 0 INTO v_err;
  IF (v_err <> 0) THEN
  v_maxpmid := 0;
  v_strresult := 'Some Error Occured, Please Try Again..!';
  -- ROLLBACK (removed)
  RETURN;
  END IF;
  -- COMMIT (removed)
END;
$$;


--
-- Name: usp_businesslistingtemp(text, text, text, character varying, character varying, character varying, integer, character varying, character varying, character varying, character varying, character varying, numeric, character varying, character varying, character varying, character varying, character varying, character varying, character varying, character varying, integer, integer, bigint, text, character varying, integer, character varying, character varying, character varying, character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_businesslistingtemp(v_companyname text DEFAULT ''::text, v_keyid text DEFAULT ''::text, v_phoneno text DEFAULT ''::text, v_building character varying DEFAULT ''::character varying, v_landmark character varying DEFAULT ''::character varying, v_comemailid character varying DEFAULT ''::character varying, v_cid integer DEFAULT 0, v_statename character varying DEFAULT ''::character varying, v_cityname character varying DEFAULT ''::character varying, v_aid character varying DEFAULT ''::character varying, v_yearofestable character varying DEFAULT ''::character varying, v_cperwebsite character varying DEFAULT ''::character varying, v_annualturnover numeric DEFAULT 0, v_noofemployee character varying DEFAULT ''::character varying, v_businessstatus character varying DEFAULT ''::character varying, v_cpertitle character varying DEFAULT ''::character varying, v_cperdesignation character varying DEFAULT ''::character varying, v_cpermobileno character varying DEFAULT ''::character varying, v_cperemailid character varying DEFAULT ''::character varying, v_firstname character varying DEFAULT ''::character varying, v_lastname character varying DEFAULT ''::character varying, v_accounttype integer DEFAULT 0, INOUT v_intresult integer DEFAULT NULL::integer, INOUT v_pmtid bigint DEFAULT 0, v_catid text DEFAULT ''::text, v_pincode character varying DEFAULT ''::character varying, v_sugestmode integer DEFAULT 0, v_introrefid character varying DEFAULT ''::character varying, v_userpassword character varying DEFAULT ''::character varying, v_username character varying DEFAULT ''::character varying, v_ipaddress character varying DEFAULT ''::character varying) RETURNS record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_outcatid text;
  v_keywordname varchar(100);
  v_categoryname varchar(100);
  v_scatid int;
  v_scategoryname varchar(100);
  v_introregno bigint;
  v_check int;
  v_password varchar(100);
  v_pmid1 bigint;
  v_packagename varchar(100);
  v_confirmpayid int;
  v_maxpayno int;
  v_err int;
  v_loginid varchar(100);
  v_intro_ref_pmid bigint;
  v_sid int;
  v_ctid int;
  v_areaid bigint;
BEGIN
  -- BEGIN TRAN (removed)
  -- SET option (removed)
  v_outcatid := NULL;
  v_sid := 0;
  v_ctid := 0;
  SELECT v_outcat INTO v_outcatid FROM dbo.usp_findingunique_key_cat(v_inputkey => v_keyid, v_inputcat => v_catid, v_outcat => v_outcatid);
  IF (v_keyid = '0') THEN
  v_keyid := NULL;
  END IF;
  SELECT COALESCE(sid, 0) INTO v_sid FROM state WHERE RTRIM(LTRIM(statename)) = RTRIM(LTRIM(v_statename)) AND cid = v_cid;
  SELECT COALESCE(ctid, 0) INTO v_ctid FROM city WHERE RTRIM(LTRIM(cityname)) = RTRIM(LTRIM(v_cityname)) AND cid = v_cid AND sid = v_sid;
  IF (v_sugestmode = 0) THEN
  SELECT aid INTO v_areaid FROM area_master WHERE cid = v_cid AND sid = v_sid AND ctid = v_ctid AND pincode = v_pincode AND areaname = v_aid;
  ELSE
  v_areaid := NULL;
  END IF;
  IF EXISTS(SELECT pmid FROM portal_login WHERE refral_id = v_introrefid) THEN
  SELECT plid INTO v_intro_ref_pmid FROM portal_login WHERE refral_id = v_introrefid;
  ELSE
  v_intro_ref_pmid := 0;
  END IF;
  IF NOT EXISTS(SELECT loginid FROM portal_login_temp WHERE RTRIM(LTRIM(COALESCE(loginid, ''))) = RTRIM(LTRIM(v_cperemailid))) AND NOT EXISTS(SELECT loginid FROM portal_login WHERE RTRIM(LTRIM(COALESCE(loginid, ''))) = RTRIM(LTRIM(v_cperemailid))) THEN
  v_intresult := 1;
  INSERT INTO portal_master_temp (keyid, companyname, contactperson, mobileno, cid, sid, ctid, areaname, title, url, lname, business_status, accounttype, active, request_date, catid, pincode, ismannual, address, lankmark, comemailid, yearofestable, annualturnover, noofemployee, doc, autocatid, aid) VALUES (v_keyid, v_companyname, v_firstname, v_phoneno, v_cid, v_sid, v_ctid, v_aid, v_companyname, v_cperwebsite, v_lastname, v_businessstatus, v_accounttype, 0, dbo.fun_getCurrentDate(), v_catid, v_pincode, v_sugestmode, v_building, v_landmark, v_comemailid, v_yearofestable, v_annualturnover, v_noofemployee, dbo.fun_getCurrentDate(), v_outcatid, v_areaid);
  v_pmtid := IDENT_CURRENT('portal_master_temp');
  INSERT INTO portal_login_temp (pmtid, loginid, password, intro_refid, active, username, ipaddress, title, sp_firstname, sp_lastname, designation, cper_emailid, phone) VALUES (v_pmtid, v_cperemailid, v_userpassword, v_intro_ref_pmid, 0, v_username, v_ipaddress, v_cpertitle, v_firstname, v_lastname, v_cperdesignation, v_cperemailid, v_cpermobileno);
  IF (v_sugestmode = 1) THEN
  INSERT INTO suggestedarea_master (areaname, cid, sid, ctid, active, isdeleted, pmtid, pincode) VALUES (v_aid, v_cid, v_sid, v_ctid, 1, 0, v_pmtid, v_pincode);
  END IF;
  END IF;
  SELECT 0 INTO v_err;
  IF (v_err <> 0) THEN
  v_intresult := 0;
  -- ROLLBACK (removed)
  RETURN;
  END IF;
  -- SET option (removed)
  -- COMMIT (removed)
END;
$$;


--
-- Name: usp_busuness_kyc_details(integer, bigint, integer, integer, integer, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_busuness_kyc_details(v_mode integer DEFAULT 0, v_regno bigint DEFAULT 0, v_int_status integer DEFAULT 0, v_approvalstatus integer DEFAULT 0, v_isallkycapprovalstatus integer DEFAULT 0, v_kyctype integer DEFAULT 0) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_count_total_pending INT;
  v_count_total_reject INT;
  v_count_total_aproved INT;
  v_getcount INT;
BEGIN
  IF (v_mode = 1) THEN
  v_count_total_pending := 0;
  v_count_total_reject := 0;
  v_count_total_aproved := 0;
  v_getcount := 0;
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp (INT_ROW_NUMMBER INT GENERATED BY DEFAULT AS IDENTITY,
ID	INT DEFAULT(0),
REGNO	BIGINT,
TYPE	VARCHAR(200) DEFAULT(''),
bytea	VARCHAR(400) DEFAULT(''),
ISAPROVE	INT DEFAULT(0),
INT_STATUS	INT DEFAULT(0),
DTM_DATE	timestamp,
DTM_APROVE	timestamp,
COMMENTORREMARK	text  DEFAULT(''),
ISDELETED	INT DEFAULT(0),
GETMAINTYPE VARCHAR(50) DEFAULT(''),
STATUS_CLASS VARCHAR(50) DEFAULT('')) ON COMMIT DROP;
  INSERT INTO tmp_temp SELECT id, regno, type, image, COALESCE(isaprove, 0), 0, COALESCE(dtm_date, ''), COALESCE(dtm_aprove, ''), COALESCE(commentorremark, ''), COALESCE(isdeleted, 0), COALESCE(type, ''), COALESCE(isaprove, 0) FROM kyc WHERE regno = v_regno AND kyctype = 2;
  SELECT COUNT(regno) INTO v_getcount FROM kyc WHERE regno = v_regno AND kyctype = 2;
  SELECT COUNT(regno) INTO v_count_total_pending FROM kyc WHERE regno = v_regno AND isaprove = 0 AND kyctype = 2;
  SELECT COUNT(regno) INTO v_count_total_reject FROM kyc WHERE regno = v_regno AND isaprove = 2 AND kyctype = 2;
  SELECT COUNT(regno) INTO v_count_total_aproved FROM kyc WHERE regno = v_regno AND isaprove = 1 AND kyctype = 2;
  SELECT CASE WHEN COALESCE(v_count_total_reject, 0) > 0 THEN 2 WHEN COALESCE(v_count_total_pending, 0) > 0 THEN 0 ELSE 1 END INTO v_int_status;
  UPDATE tm SET id = ky.id, image = COALESCE(ky.image, 'NoImage.jpg'), isaprove = COALESCE(ky.isaprove, 0), int_status = COALESCE(v_int_status, 0), dtm_date = COALESCE(ky.dtm_date, ''), dtm_aprove = COALESCE(ky.dtm_aprove, ''), commentorremark = COALESCE(ky.commentorremark, ''), isdeleted = COALESCE(ky.isdeleted, 0), status_class = CASE WHEN COALESCE(ky.isaprove, 0) = 0 THEN 'inprocess' WHEN COALESCE(ky.isaprove, 0) = 1 THEN 'verifiy' WHEN COALESCE(ky.isaprove, 0) = 2 THEN 'reject' END FROM tmp_temp AS tm INNER JOIN kyc AS ky ON tm.getmaintype = ky.type AND ky.regno = v_regno AND ky.kyctype = 2;
  v_approvalstatus := v_count_total_aproved;
  v_isallkycapprovalstatus := (SELECT entitytype FROM tbl_businesskycdetails WHERE plid = v_regno);
  RETURN QUERY SELECT * FROM tmp_temp;
  DROP TABLE IF EXISTS tmp_temp;
  END IF;
  IF (v_mode = 2) THEN
  IF EXISTS(SELECT regno FROM kyc WHERE regno = v_regno AND kyctype = 2) THEN
  RETURN QUERY SELECT (CASE WHEN (SELECT COUNT(regno) FROM kyc WHERE regno = v_regno AND isaprove = 2 AND kyctype = 2) >= 1 THEN 'Rejected' WHEN (SELECT COUNT(regno) FROM kyc WHERE regno = v_regno AND isaprove = 0 AND kyctype = 2) >= 1 THEN 'Pending' WHEN (SELECT COUNT(regno) FROM kyc WHERE regno = v_regno AND isaprove = 1 AND kyctype = 2) >= 4 THEN 'Verified' ELSE 'Pending' END) AS kycstatus FROM member_master AS mm WHERE mm.regno IN (SELECT regno FROM kyc WHERE regno = v_regno AND kyctype = 2);
  ELSE
  RETURN QUERY SELECT 'Not Verified' AS kycstatus;
  END IF;
  END IF;
END;
$$;


--
-- Name: usp_bv_admin_clubhistory_list(integer, integer, character varying, character varying, character varying, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_bv_admin_clubhistory_list(v_startrowindex integer DEFAULT 1, v_maxrows integer DEFAULT 100, v_fromdate character varying DEFAULT ''::character varying, v_todate character varying DEFAULT ''::character varying, v_resellername character varying DEFAULT ''::character varying, v_totalcount integer DEFAULT 0) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_query text;
  v_maxregno text;
  v_query1 text;
  v_minindex INT;
  v_maxindex INT;
  v_count INT;
  v_chid INT;
  v_totoalcancelamount DECIMAL(18,2);
BEGIN
  -- SET option (removed)
  v_query := '';
  v_maxregno := '';
  v_query1 := '';
  v_count := 1;
  v_chid := 0;
  v_minindex := (v_startrowindex - 1) * v_maxrows + 1;
  v_maxindex := v_startrowindex * v_maxrows;
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp (ROWNUMBER BIGINT,
	  CHID BIGINT,
	  FILENAME VARCHAR(150),
	  DATE timestamp,
	  CLUBGROUP VARCHAR(150),
	  TOTALREQUEST INT,
	  TOTALAMOUNT DECIMAL(18,8),
	  PROCESSDATE timestamp,
	  PROCESSBY VARCHAR(50),
	  PROCESSSTATUS VARCHAR(50),
	  PROCESSIPADDRESS VARCHAR(50),
	  DATERANAGE VARCHAR(100),
	  COMPANYNAME VARCHAR(100)) ON COMMIT DROP;
  v_query := 'INSERT INTO #TEMP SELECT ROW_NUMBER()OVER(ORDER BY TRCBC.CHID DESC) AS ROWNUMBER,TRCBC.CHID,TRCBC.FILENAME,CONVERT(DATE,TRCBC.DATE,105) AS DATE,
TRCBC.CLUBGROUP,TRCBC.TOTALREQUEST,ISNULL(TRCBC.TOTALAMOUNT,0),
CONVERT(DATE,TRCBC.PROCESSDATE,105) AS PROCESSDATE,TRCBC.PROCESSBY,
(CASE WHEN TRCBC.PROCESSSTATUS=0  THEN ''PENDING'' WHEN TRCBC.PROCESSSTATUS=1 THEN ''DISTRIBUTED'' WHEN TRCBC.PROCESSSTATUS=2 THEN ''CANCELLED'' END),
TRCBC.PROCESSIPADDRESS,TRCBC.DATERANAGE,ISNULL(DM.COMPANYNAME,'''') 
FROM TBL_RESELLERWISE_CUSTOMER_BVCLUBHISTORY TRCBC   
LEFT JOIN DISTRIBUTOR_MASTER DM ON TRCBC.DID=DM.PLID
WHERE 1=1 ';
  IF (v_resellername <> '') THEN
  v_query := v_query || ' And DM.COMPANYNAME=''' || CAST(v_resellername AS VARCHAR(30)) || '''';
  END IF;
  RAISE NOTICE '%', v_query;
  EXECUTE v_query;
  SELECT COUNT(1) INTO v_totalcount FROM tmp_temp;
  SELECT COALESCE(COUNT(1), 0) INTO v_totalcount FROM tmp_temp;
  RETURN QUERY SELECT * FROM tmp_temp ORDER BY rownumber ASC NULLS FIRST;
  DROP TABLE IF EXISTS tmp_temp;
  -- SET option (removed)
END;
$$;


--
-- Name: usp_bv_club_history_resellerwise(integer, integer, character varying, character varying, character varying, character varying, integer, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_bv_club_history_resellerwise(v_startrowindex integer DEFAULT 1, v_maxrows integer DEFAULT 1000, v_fromdate character varying DEFAULT ''::character varying, v_todate character varying DEFAULT ''::character varying, v_searchfield character varying DEFAULT ''::character varying, v_searchvalue character varying DEFAULT ''::character varying, v_did integer DEFAULT 2, v_orderstatus integer DEFAULT 0) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_query text;
  v_maxregno text;
  v_query1 text;
  v_getcount INT;
  v_getwdid text;
  v_getplid BIGINT;
  v_getusername VARCHAR(100);
  v_totalrequest INT;
  v_totalamount DECIMAL(18,8);
  v_total_tansaction DECIMAL(18,8);
  v_getallcubeallwdid text;
  v_getseparatewdid text;
  v_getmaxchid INT;
  v_getaccountno VARCHAR(50);
  v_getaccountholdername VARCHAR(50);
  v_getbankname VARCHAR(50);
  v_getbranchname VARCHAR(50);
  v_getifsccode VARCHAR(50);
  v_getnetamount DECIMAL(18,8);
  v_mindate varchar(100);
  v_maxdate varchar(100);
  v_dateranage Varchar(100);
  v_getfilename VARCHAR(50);
  v_getclubgroup VARCHAR(50);
  v_getrandom1 VARCHAR(50);
  v_getrandom2 VARCHAR(50);
  v_getrandom3 VARCHAR(50);
  v_getmergrandom VARCHAR(50);
  v_getupdatestatus text;
BEGIN
  -- SET option (removed)
  v_query := '';
  v_maxregno := '';
  v_query1 := '';
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp (ROWNUMBER INT GENERATED BY DEFAULT AS IDENTITY,
 CLID INT,
 CUSTOMERNAME VARCHAR(100),
 MOBILENO VARCHAR(100),
 DATE VARCHAR(100),
 BVPERCNTAGE DECIMAL(18,2),
 BV DECIMAL(18,2),
 ORDERID VARCHAR(100),
 ORDERNO VARCHAR(100),
 ORDERSTATUS INT,
 ORDERDERCYCLESTATUS VARCHAR(100),
 BENIFICARYID VARCHAR(100),
 TYPE VARCHAR(100)) ON COMMIT DROP;
  v_query := ' INSERT INTO #TEMP SELECT CL.CLID,(CL.FNAME+'' ''+CL.LNAME) AS NAME,CL.PHONE,CONVERT(VARCHAR,TRBVM.CREATE_DATE,106) AS DATE, 
ISNULL(TRBVD.BVPERCENTAGE,0),ISNULL(TRBVD.BVALUE,0) ,ISNULL(TRBVM.ORDERID,''N/A''),ISNULL(TRBVD.ORDERNO,''N/A''),
ISNULL(POM.INTSTATUS,0),(CASE WHEN POM.INTSTATUS=0 THEN ''Pending'' WHEN POM.INTSTATUS=2 THEN ''Packed'' WHEN POM.INTSTATUS=3 THEN ''Ready for Dispatch'' 
WHEN POM.INTSTATUS=4 THEN ''Shipped'' WHEN POM.INTSTATUS=5 THEN ''Shipped'' WHEN POM.INTSTATUS=6 THEN ''Completed'' WHEN POM.INTSTATUS=7 THEN ''Cancel''
 WHEN POM.INTSTATUS=9 THEN ''Out for Delivery'' END),
ISNULL(TRUN.USERNAME,''N/A''),ISNULL(TRS.SERVICENAME,''N/A'')
FROM TBL_RESELLER_BV_PV_MASTER TRBVM  
LEFT JOIN TBL_RESELLER_BV_PV_DETAILS TRBVD ON TRBVM.COMID=TRBVD.COMID
LEFT JOIN TBL_PRODUCT_ORDER_MASTER POM ON  TRBVD.ORDERNO=POM.ORDERNO
LEFT JOIN TBL_CUSTOMERLOGIN CL ON POM.LOGINID=CL.LOGINID
LEFT JOIN TBL_RESELLER_SERVICES TRS ON TRBVD.TYPE=TRS.TRSID
LEFT JOIN TBL_REFERENCEUSERNAME TRUN ON CL.CLID=TRUN.CLID AND TRUN.STATUS=1
WHERE TRBVM.DID=''' || CAST(v_did AS VARCHAR(30)) || ''' and  TRBVD.RELEASEDSTATUS=0 ';
  IF ((v_fromdate <> '') AND (v_todate = '')) THEN
  v_query := v_query || ' AND CONVERT(DATE, TRBVM.CREATE_DATE) =  CONVERT(DATE, ''' || v_fromdate || ''')';
  END IF;
  IF ((v_fromdate = '') AND (v_todate <> '')) THEN
  v_query := v_query || ' AND CONVERT(DATE, TRBVM.CREATE_DATE) =  CONVERT(DATE, ''' || v_todate || ''') ';
  END IF;
  IF ((v_fromdate <> '') AND (v_todate <> '')) THEN
  v_query := v_query || ' AND CONVERT(DATE, TRBVM.CREATE_DATE) BETWEEN CONVERT(DATE, ''' || v_fromdate || ''') AND  CONVERT(DATE, ''' || v_todate || ''') ';
  END IF;
  IF (v_searchfield <> '' AND v_searchvalue <> '') THEN
  IF (v_searchfield = 'FULLNAME') THEN
  v_query := v_query || ' AND (CL.FANME+''''+CL.LNAME)=' || CAST(v_searchvalue AS VARCHAR(30)) || '';
  END IF;
  IF (v_searchfield = 'PHONE') THEN
  v_query := v_query || ' AND CL.PHONE=''' || CAST(v_searchvalue AS VARCHAR(30)) || '''';
  END IF;
  IF (v_searchfield = 'BENEFICIARYID') THEN
  v_query := v_query || ' AND TRUN.USERNAME=''' || CAST(v_searchvalue AS VARCHAR(30)) || '''';
  END IF;
  IF (v_searchfield = 'ORDERID') THEN
  v_query := v_query || ' AND TRBVM.ORDERID=''' || CAST(v_searchvalue AS VARCHAR(30)) || '''';
  END IF;
  END IF;
  IF (v_orderstatus <> '') THEN
  v_query := v_query || ' AND POM.INTSTATUS=''' || CAST(v_orderstatus AS VARCHAR(30)) || '''';
  END IF;
  EXECUTE v_query;
  RAISE NOTICE '%', v_query;
  EXECUTE v_query;
  DROP TABLE IF EXISTS tmp_temp1;
  CREATE TEMP TABLE tmp_temp1 (ROWNUMBER BIGINT,
	  USERNAME VARCHAR(150),
	  CLID INT,
	  CUSTOMERNAME varchar(100),
	  Orderno Varchar(100),
	  BV DECIMAL(18,8),
	  MOBILE VARCHAR(100),
	  Date Varchar(100),
	  Orderid varchar(100),
	  TYPE VARCHAR(100)) ON COMMIT DROP;
  v_query1 := 'INSERT INTO #TEMP1 SELECT ROW_NUMBER()OVER(ORDER BY (SELECT(1))) AS ROWNUMBER,
	TM.BENIFICARYID,TM.CLID,TM.CUSTOMERNAME,TM.ORDERNO,TM.BV,TM.MOBILENO,CONVERT(Varchar,Tm.DATE,106),
	TM.ORDERID,TM.TYPE FROM #TEMP TM
	 GROUP BY TM.BENIFICARYID,TM.ORDERNO,TM.CLID,TM.CUSTOMERNAME,TM.BV,TM.MOBILENO,Tm.DATE,TM.ORDERID,TM.TYPE ';
  EXECUTE v_query1;
  RAISE NOTICE '%', v_query1;
  v_getcount := 0;
  v_getwdid := '';
  v_getplid := 0;
  v_getusername := '';
  v_totalrequest := 0;
  v_totalamount := 0;
  v_total_tansaction := 0;
  v_getallcubeallwdid := '';
  v_getseparatewdid := '';
  v_getmaxchid := 0;
  v_getaccountno := '';
  v_getifsccode := '';
  v_getnetamount := 0;
  v_mindate := '';
  v_maxdate := '';
  v_dateranage := '';
  SELECT COALESCE(MAX(chid), 0) + 1 INTO v_getmaxchid FROM tbl_resellerwise_customer_bvclubhistory;
  SELECT COUNT(1) INTO v_getcount FROM tmp_temp1;
  SELECT SUM(bv) INTO v_totalamount FROM tmp_temp1;
  v_totalrequest := v_getcount;
  SELECT COUNT(1) INTO v_getcount FROM tmp_temp1;
  SELECT COUNT(DISTINCT username) INTO v_total_tansaction FROM tmp_temp1;
  SELECT MIN(date) INTO v_mindate FROM tmp_temp;
  SELECT MAX(date) INTO v_maxdate FROM tmp_temp;
  v_dateranage := v_mindate || ' To ' || v_maxdate;
  WHILE (v_getcount > 0) LOOP
  SELECT username, bv, orderno, customername INTO v_getusername, v_getnetamount, v_getplid, v_getaccountholdername FROM tmp_temp1 WHERE rownumber = v_getcount;
  SELECT COALESCE(v_getseparatewdid || ',', '') || CAST(comdid AS VARCHAR) INTO v_getseparatewdid FROM tbl_reseller_bv_pv_details WHERE orderno = v_getplid AND releasedstatus = 0 LIMIT 10000;
  INSERT INTO tbl_resellerwise_customer_downloadbvclubdata VALUES (v_getmaxchid, v_getaccountholdername, v_getnetamount, '0', '', '', '', v_getseparatewdid);
  v_getallcubeallwdid := v_getallcubeallwdid || v_getseparatewdid;
  v_getseparatewdid := '';
  v_getcount := v_getcount - 1;
  END LOOP;
  v_getfilename := '';
  v_getclubgroup := '';
  v_getrandom1 := '';
  v_getrandom2 := '';
  v_getrandom3 := '';
  v_getmergrandom := '';
  SELECT CAST(REPLACE(RANDOM(), '.', '') AS VARCHAR(50)) INTO v_getrandom1;
  SELECT CAST(REPLACE(RANDOM(), '.', '') AS VARCHAR(50)) INTO v_getrandom2;
  SELECT CAST(REPLACE(RANDOM(), '.', '') AS VARCHAR(50)) INTO v_getrandom3;
  v_getmergrandom := v_getrandom1 || v_getrandom3;
  v_getfilename := v_getmergrandom;
  v_getclubgroup := v_getrandom1 || v_getrandom3 || v_getrandom2;
  RETURN QUERY SELECT * FROM tbl_resellerwise_customer_bvclubhistory;
  INSERT INTO tbl_resellerwise_customer_bvclubhistory VALUES (v_getfilename, dbo.FUN_GETCURRENTDATE(), v_getclubgroup, v_totalrequest, v_totalamount, v_total_tansaction, dbo.FUN_GETCURRENTDATE(), v_did, 0, '', v_getallcubeallwdid, v_did, v_dateranage, 0);
  v_getupdatestatus := '';
  v_getupdatestatus := 'UPDATE TBL_RESELLER_BV_PV_DETAILS SET RELEASEDSTATUS=3 WHERE COMDID IN  (SELECT * FROM SPLITSTRING(''' || v_getallcubeallwdid || ''','',''))';
  EXECUTE v_getupdatestatus;
  RETURN QUERY SELECT v_getfilename AS filename, * FROM tmp_temp1 ORDER BY rownumber ASC NULLS FIRST;
  DROP TABLE IF EXISTS tmp_temp;
  DROP TABLE IF EXISTS tmp_temp1;
  -- SET option (removed)
END;
$$;


--
-- Name: usp_bv_distributed(integer, integer, integer, character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_bv_distributed(v_mode integer DEFAULT 1, v_comdid integer DEFAULT 2, v_status integer DEFAULT 1, v_groupno character varying DEFAULT '056390707650350961841'::character varying) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_value Varchar(100);
  v_prefix varchar(2);
BEGIN
  -- BEGIN TRAN (removed)
  -- SET option (removed)
  v_value := '';
  v_prefix := ',';
  IF (v_mode = 1) THEN
  v_value := v_prefix || (CAST(v_comdid AS VARCHAR(100)));
  UPDATE tbl_reseller_bv_pv_details SET releasedstatus = v_status, released_date = dbo.FUN_GETCURRENTDATE() WHERE comdid = v_comdid AND releasedstatus = 3;
  UPDATE tbl_resellerwise_customer_bvclubhistory SET totalreleased = totalreleased + 1, processstatus = 1 WHERE clubgroup = v_groupno;
  UPDATE tbl_resellerwise_customer_downloadbvclubdata SET status = 1 WHERE allwdid = v_value AND status = 0;
  END IF;
  IF (v_mode = 2) THEN
  v_value := v_prefix || (CAST(v_comdid AS VARCHAR(100)));
  UPDATE tbl_reseller_bv_pv_details SET releasedstatus = v_status, released_date = dbo.FUN_GETCURRENTDATE() WHERE comdid = v_comdid AND releasedstatus = 3;
  UPDATE tbl_resellerwise_customer_downloadbvclubdata SET status = 2 WHERE allwdid IN (SELECT value FROM dbo.SPLITSTRINGBYCOMMA(v_comdid)) AND status = 0;
  END IF;
  -- SET option (removed)
  -- COMMIT (removed)
END;
$$;


--
-- Name: usp_bv_reseller_clubhistory_list(integer, integer, character varying, character varying, integer, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_bv_reseller_clubhistory_list(v_startrowindex integer DEFAULT 1, v_maxrows integer DEFAULT 100, v_fromdate character varying DEFAULT ''::character varying, v_todate character varying DEFAULT ''::character varying, v_totalrecord integer DEFAULT 0, v_did integer DEFAULT 2) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_query text;
  v_maxregno text;
  v_query1 text;
  v_minindex INT;
  v_maxindex INT;
  v_count INT;
  v_totalcount INT;
  v_chid INT;
  v_totoalcancelamount DECIMAL(18,2);
BEGIN
  -- SET option (removed)
  v_query := '';
  v_maxregno := '';
  v_query1 := '';
  v_count := 1;
  v_totalcount := 0;
  v_chid := 0;
  v_minindex := (v_startrowindex - 1) * v_maxrows + 1;
  v_maxindex := v_startrowindex * v_maxrows;
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp (ROWNUMBER BIGINT,
	  CHID BIGINT,
	  FILENAME VARCHAR(150),
	  DATE timestamp,
	  CLUBGROUP VARCHAR(150),
	  TOTALREQUEST INT,
	  TOTALAMOUNT DECIMAL(18,8),
	  PROCESSDATE timestamp,
	  PROCESSBY VARCHAR(50),
	  PROCESSSTATUS VARCHAR(50),
	  PROCESSIPADDRESS VARCHAR(50),
	  DateRanage Varchar(100)) ON COMMIT DROP;
  v_query := 'INSERT INTO #TEMP SELECT ROW_NUMBER()OVER(ORDER BY CHID DESC) AS ROWNUMBER,CHID,FILENAME,CONVERT(DATE,DATE,105) AS DATE,
CLUBGROUP,TOTALREQUEST,ISNULL(TOTALAMOUNT,0),
CONVERT(DATE,PROCESSDATE,105) AS PROCESSDATE,PROCESSBY,
(CASE WHEN PROCESSSTATUS=0  THEN ''Pending'' WHEN PROCESSSTATUS=1 THEN ''Distributed'' WHEN PROCESSSTATUS=2 THEN ''Cancelled'' END),PROCESSIPADDRESS,DATERANAGE
FROM TBL_RESELLERWISE_CUSTOMER_BVCLUBHISTORY   
WHERE 1=1 and DID=''' || CAST(v_did AS VARCHAR(30)) || '''';
  RAISE NOTICE '%', v_query;
  EXECUTE v_query;
  SELECT COUNT(1) INTO v_totalcount FROM tmp_temp;
  SELECT COALESCE(COUNT(1), 0) INTO v_totalrecord FROM tmp_temp;
  RETURN QUERY SELECT * FROM tmp_temp ORDER BY rownumber ASC NULLS FIRST;
  DROP TABLE IF EXISTS tmp_temp;
  -- SET option (removed)
END;
$$;


--
-- Name: usp_bv_reseller_update(character varying, character varying, character varying, character varying, character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_bv_reseller_update(v_groupnumber character varying DEFAULT ''::character varying, v_processby character varying DEFAULT ''::character varying, v_processipaddress character varying DEFAULT '1'::character varying, INOUT v_strresult character varying DEFAULT ''::character varying, v_mode character varying DEFAULT '2'::character varying) RETURNS character varying
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_getchid INT;
  v_getallwdid text;
  v_getupdatestatus text;
BEGIN
  v_getchid := 0;
  v_getallwdid := '';
  SELECT chid INTO v_getchid FROM tbl_resellerwise_customer_bvclubhistory WHERE clubgroup = v_groupnumber;
  v_strresult := '1';
  v_getupdatestatus := '';
  IF (v_mode = 2) THEN
  SELECT RIGHT(CAST(allwdid AS TEXT), LENGTH(CAST(allwdid AS TEXT)) - 1) INTO v_getallwdid FROM tbl_resellerwise_customer_bvclubhistory WHERE chid = v_getchid;
  v_getupdatestatus := 'UPDATE TBL_RESELLER_BV_PV_DETAILS SET RELEASEDSTATUS=0 WHERE COMDID IN  (SELECT * FROM SPLITSTRING(''' || v_getallwdid || ''','',''))';
  EXECUTE v_getupdatestatus;
  UPDATE tbl_resellerwise_customer_downloadbvclubdata SET status = 2, processby = v_processby, processipaddress = v_processipaddress, processdate = dbo.FUN_GETCURRENTDATE() WHERE chid = v_getchid;
  UPDATE tbl_resellerwise_customer_bvclubhistory SET processstatus = 2, processby = v_processby, processipaddress = v_processipaddress, processdate = dbo.FUN_GETCURRENTDATE() WHERE chid = v_getchid;
  v_strresult := '1';
  END IF;
END;
$$;


--
-- Name: usp_bvrequestapprove(character varying, integer, integer, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_bvrequestapprove(v_orderno character varying DEFAULT ''::character varying, v_status integer DEFAULT 0, v_emp_id integer DEFAULT 0, INOUT v_totalcount integer DEFAULT 0) RETURNS integer
    LANGUAGE plpgsql
    AS $$
BEGIN
  -- BEGIN TRAN (removed)
  -- SET option (removed)
  IF (v_status = 1) THEN
  UPDATE tbl_resellerreleasebvdetails SET isadminrelease = 1, adminreleasedate = dbo.FUN_GETCURRENTDATE(), adminreleaserefid = v_emp_id WHERE orderno = v_orderno;
  v_totalcount := 1;
  ELSE
  UPDATE tbl_resellerreleasebvdetails SET isadminrelease = 2, adminreleasedate = dbo.FUN_GETCURRENTDATE(), adminreleaserefid = v_emp_id WHERE orderno = v_orderno;
  v_totalcount := 1;
  END IF;
  IF (0 <> 0) THEN
  v_totalcount := 0;
  -- ROLLBACK (removed)
  RETURN;
  END IF;
  -- COMMIT (removed)
  -- SET option (removed)
END;
$$;


--
-- Name: usp_campaignactive(integer, integer, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_campaignactive(v_smcid integer DEFAULT 0, v_slid integer DEFAULT 0, INOUT v_intresult integer DEFAULT NULL::integer) RETURNS integer
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_depositamount numeric(19,4);
  v_detectamount numeric(19,4);
  v_currentbalance numeric(19,4);
  v_status int;
  v_budgetperday numeric(19,4);
BEGIN
  -- BEGIN TRAN (removed)
  -- SET option (removed)
  v_depositamount := 0;
  v_detectamount := 0;
  v_currentbalance := 0;
  v_budgetperday := 0;
  SELECT SUM(COALESCE(depositamount, 0)) INTO v_depositamount FROM tbl_sponserfunddetails WHERE plid = v_slid AND status = 1;
  SELECT SUM(COALESCE(deductamount, 0)) INTO v_detectamount FROM tbl_sponserfunddetails WHERE plid = v_slid AND status = 1;
  SELECT campactive, budjetperday INTO v_status, v_budgetperday FROM tbl_sponsor_master_campain WHERE smcid = v_smcid;
  v_currentbalance := v_depositamount - v_detectamount;
  IF (v_status = 0) THEN
  UPDATE tbl_sponsor_master_campain SET campactive = 1 WHERE smcid = v_smcid;
  v_intresult := 1;
  END IF;
  IF (v_status = 1) THEN
  UPDATE tbl_sponsor_master_campain SET campactive = 0 WHERE smcid = v_smcid;
  v_intresult := 2;
  END IF;
  IF (0 <> 0) THEN
  v_intresult := 0;
  -- ROLLBACK (removed)
  RETURN;
  END IF;
  -- SET option (removed)
  -- COMMIT (removed)
END;
$$;


--
-- Name: usp_campaigncreate(character varying, integer, integer, integer, integer, character varying, character varying, character varying, character varying, text, text, numeric, integer, integer, character varying, character varying, character varying, integer, integer, character varying, integer, character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_campaigncreate(v_campaignnane character varying DEFAULT ''::character varying, v_plid integer DEFAULT 0, v_cid integer DEFAULT 0, v_pageref integer DEFAULT 0, v_pagelocation integer DEFAULT 0, v_framesize character varying DEFAULT ''::character varying, v_image character varying DEFAULT ''::character varying, v_destinationurl character varying DEFAULT ''::character varying, v_displayurl character varying DEFAULT ''::character varying, v_cityid text DEFAULT ''::text, v_keywordid text DEFAULT ''::text, v_budgetperday numeric DEFAULT 0, v_adtype integer DEFAULT 0, v_cidforallcity integer DEFAULT 0, v_heading character varying DEFAULT ''::character varying, v_descriptionline1 character varying DEFAULT ''::character varying, v_descriptionline2 character varying DEFAULT ''::character varying, v_mode integer DEFAULT 0, v_smcid integer DEFAULT 0, v_allcityofcountry character varying DEFAULT ''::character varying, v_status integer DEFAULT 0, v_strresult character varying DEFAULT NULL::character varying) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_smid int;
  v_catid text;
  v_campaincreatedate DATE;
  v_campid text;
  v_loginid varchar(300);
  v_campidappend text;
  v_campaignid int;
  v_budjetperdayedit numeric(19,4);
  v_ctidforedit text;
  v_keywordidforedit text;
  v_cidforallcityedit int;
  v_depositamount numeric(19,4);
  v_detectamount numeric(19,4);
  v_currentbalance numeric(19,4);
  v_temp text;
BEGIN
  -- BEGIN TRAN (removed)
  -- SET option (removed)
  BEGIN
  v_smid := 0;
  v_catid := '';
  v_campid := '';
  v_loginid := '';
  v_campidappend := '';
  v_campaignid := 0;
  v_budjetperdayedit := 0;
  v_ctidforedit := '';
  IF (v_smcid <> 0) THEN
  SELECT cidforallcity, budjetperday, ctid, keywordid INTO v_cidforallcityedit, v_budjetperdayedit, v_ctidforedit, v_keywordidforedit FROM tbl_sponsor_master_campain WHERE smcid = v_smcid;
  END IF;
  v_campaincreatedate := GETUTCDATE() + INTERVAL '330 MI';
  SELECT smd.smdid, pl.loginid INTO v_smid, v_loginid FROM sponsor_master_detail AS smd INNER JOIN portal_login AS pl ON smd.plid = pl.plid WHERE smd.plid = v_plid;
  v_strresult := 'ok';
  IF (v_status <> 0) THEN
  v_depositamount := 0;
  v_detectamount := 0;
  v_currentbalance := 0;
  SELECT SUM(COALESCE(depositamount, 0)) INTO v_depositamount FROM tbl_sponserfunddetails WHERE plid = v_plid AND status = 1;
  SELECT SUM(COALESCE(deductamount, 0)) INTO v_detectamount FROM tbl_sponserfunddetails WHERE plid = v_plid AND status = 1;
  v_currentbalance := v_depositamount - v_detectamount;
  IF (v_currentbalance >= v_budgetperday) THEN
  v_status := 1;
  v_strresult := 'ok';
  ELSE
  v_status := 0;
  v_strresult := 'Sorry you have insufficient balance in your account';
  END IF;
  END IF;
  IF (v_adtype = 1) THEN
  IF (v_mode = 2) THEN
  UPDATE tbl_sponsor_master_campain SET smid = v_smid, pageref = v_pageref, pagelocation = v_pagelocation, framesize = v_framesize, keywordid = (CASE WHEN v_keywordid = '0' THEN v_keywordidforedit ELSE v_keywordid END), budjetperday = (CASE WHEN v_budgetperday = 0 THEN v_budjetperdayedit ELSE v_budgetperday END), adtype = v_adtype, ctid = (CASE WHEN v_allcityofcountry = 'no' THEN (CASE WHEN v_cityid = '' THEN v_ctidforedit ELSE v_cityid END) ELSE '0' END), cidforallcity = (CASE WHEN v_allcityofcountry = 'yes' THEN (CASE WHEN v_cityid = '' THEN v_cidforallcityedit ELSE v_cityid END) ELSE v_cidforallcityedit END), displayurl = v_displayurl, destinationurl = v_destinationurl, campactive = v_status, campainname = v_campaignnane WHERE smcid = v_smcid;
  IF ((COALESCE(v_image, '')) <> '') THEN
  UPDATE tbl_sponsor_master_campain SET imagename = v_image WHERE smcid = v_smcid;
  END IF;
  ELSE
  IF (v_mode = 1) THEN
  INSERT INTO tbl_sponsor_master_campain (smid, pageref, pagelocation, framesize, keywordid, catid, budjetperday, adtype, cid, sid, ctid, cidforallcity, imagename, campaincreatedate, displayurl, destinationurl, campactive, campainname, plid, descriptionline1) VALUES (v_smid, v_pageref, v_pagelocation, v_framesize, v_keywordid, v_catid, v_budgetperday, v_adtype, v_cid, 0, (CASE WHEN v_allcityofcountry = 'yes' THEN '0' ELSE v_cityid END), (CASE WHEN v_allcityofcountry = 'yes' THEN '1' ELSE 0 END), v_image, v_campaincreatedate, v_displayurl, v_destinationurl, v_status, v_campaignnane, v_plid, v_descriptionline1);
  END IF;
  END IF;
  END IF;
  IF (v_mode = 1) THEN
  SELECT MAX(smcid) INTO v_campaignid FROM tbl_sponsor_master_campain;
  IF NOT EXISTS(SELECT 1 FROM tbl_sponsor_master WHERE plid = v_plid AND active = 1) THEN
  SELECT MAX(smcid) INTO v_campid FROM tbl_sponsor_master_campain;
  INSERT INTO tbl_sponsor_master (plid, loginid, campid, active) VALUES (v_plid, v_loginid, v_campid, 1);
  ELSE
  SELECT MAX(smcid) INTO v_campid FROM tbl_sponsor_master_campain;
  SELECT campid INTO v_campidappend FROM tbl_sponsor_master WHERE plid = v_plid;
  v_campid := v_campidappend || ',' || v_campid;
  UPDATE tbl_sponsor_master SET campid = v_campid WHERE plid = v_plid;
  END IF;
  END IF;
  IF (v_mode = 1) THEN
  INSERT INTO tbl_sponsor_update (smid, smcid, budjetperday, updatedate) VALUES (v_smid, v_campaignid, v_budgetperday, v_campaincreatedate);
  ELSE
  IF (v_mode = 2) THEN
  UPDATE tbl_sponsor_update SET budjetperday = v_budgetperday WHERE smcid = v_smcid;
  END IF;
  END IF;
  IF (v_smcid = 0) THEN
  v_smcid := v_campaignid;
  END IF;
  v_temp := '';
  IF (v_allcityofcountry = 'yes') THEN
  IF (v_keywordid <> '0') THEN
  PERFORM dbo.usp_sponsersearchinsertforallcity(v_smid => v_smid, v_smcid => v_smcid, v_pageref => v_pageref, v_pagelocation => v_pagelocation, v_cidforallcity => v_cidforallcity, v_adtype => v_adtype, v_cityid => v_cityid, v_keywordid => v_keywordid, v_intresult => 1);
  END IF;
  ELSE
  IF (v_keywordid <> '0') THEN
  PERFORM dbo.usp_sponsersearchinsert(v_smid => v_smid, v_smcid => v_smcid, v_pageref => v_pageref, v_pagelocation => v_pagelocation, v_cidforallcity => v_cidforallcity, v_adtype => v_adtype, v_cityid => v_cityid, v_keywordid => v_keywordid, v_intresult => 1);
  END IF;
  END IF;
  IF (0 <> 0) THEN
  v_strresult := 'some error occured, please refresh the page and try again !';
  -- ROLLBACK (removed)
  RETURN;
  END IF;
  -- SET option (removed)
  EXCEPTION WHEN OTHERS THEN
  RETURN QUERY SELECT sqlstate AS errornumber, 0 AS errorseverity, 0 AS errorstate, 'proc' AS errorprocedure, 0 AS errorline, sqlerrm AS errormessage;
  END;
  -- COMMIT (removed)
END;
$$;


--
-- Name: usp_campaigndetail(integer, character varying, character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_campaigndetail(v_slid integer, v_todate character varying DEFAULT ''::character varying, v_fromdate character varying DEFAULT ''::character varying) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF (v_todate = '' AND v_fromdate = '') THEN
  RETURN QUERY SELECT ROW_NUMBER() OVER (ORDER BY tsmc.smid NULLS FIRST) AS number, tsmc.smid, campainname, tsmc.imagename, budjetperday, tsmc.smcid, tsmc.keywordid, CAST(TO_CHAR(tsmc.campaincreatedate, 'DD TMMon YYYY') AS text) AS campaincreatedate, COALESCE(sfd.ads_deduct, 0) AS totaldeductamount, COALESCE(sfd.noofclicks, 0) AS noofclicks, CASE WHEN adtype = 0 THEN 'Text' WHEN adtype = 1 THEN 'Image' END AS adtype, tsmc.descriptionline1, CASE WHEN campactive = 0 THEN 'Deactive' WHEN campactive = 1 THEN 'Active' WHEN campactive = 2 THEN 'Pouse' END AS status FROM tbl_sponsor_master_campain AS tsmc INNER JOIN sponsor_master_detail AS tsm ON tsm.plid = tsmc.plid LEFT JOIN (SELECT smcid, SUM(noofhits * bid_price) AS ads_deduct, SUM(noofhits) AS noofclicks FROM tbl_keyword_in_sponsorad GROUP BY smcid) AS sfd ON tsmc.smcid = sfd.smcid WHERE tsm.plid = v_slid ORDER BY campaincreatedate DESC NULLS LAST;
  ELSE
  RETURN QUERY SELECT ROW_NUMBER() OVER (ORDER BY tsmc.smid NULLS FIRST) AS number, tsmc.smid, campainname, budjetperday, tsmc.smcid, tsmc.keywordid, tsmc.campaincreatedate, COALESCE(sfd.totaldeductamount, 0) AS totaldeductamount, COALESCE(sfd.noofclicks, 0) AS noofclicks, CASE WHEN adtype = 0 THEN 'Text' WHEN adtype = 1 THEN 'Image' END AS adtype, tsmc.descriptionline1, CASE WHEN campactive = 1 THEN 'Deactive' WHEN campactive = 0 THEN 'Active' WHEN campactive = 2 THEN 'Pouse' END AS status FROM tbl_sponsor_master_campain AS tsmc INNER JOIN sponsor_master_detail AS tsm ON tsm.plid = tsmc.plid LEFT JOIN (SELECT smcid, SUM(deductamount) AS totaldeductamount, datetime, COUNT(smcid) AS noofclicks FROM tbl_sponserfunddetails GROUP BY smcid, datetime HAVING CAST(datetime AS DATE) BETWEEN CAST(v_todate AS DATE) AND CAST(v_fromdate AS DATE)) AS sfd ON tsmc.smcid = sfd.smcid WHERE tsm.plid = v_slid ORDER BY campaincreatedate DESC NULLS LAST;
  END IF;
END;
$$;


--
-- Name: usp_campaigndetail_admin(character varying, character varying, character varying, character varying, character varying, character varying, character varying, character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_campaigndetail_admin(v_slid character varying DEFAULT ''::character varying, v_datefrom character varying DEFAULT ''::character varying, v_dateto character varying DEFAULT ''::character varying, v_camptype character varying DEFAULT ''::character varying, v_status character varying DEFAULT ''::character varying, v_sortbyclicks character varying DEFAULT ''::character varying, v_sortbycost character varying DEFAULT ''::character varying, v_cid character varying DEFAULT 96) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_query text;
BEGIN
  v_query := '';
  v_query := 'select ROW_NUMBER() over (ORDER BY tsmc.smcid desc) AS Number,pl.LoginId,campainname,budjetperday,tsmc.cid,
tsmc.smid,tsmc.smcid,tsmc.keywordid,tsmc.campaincreatedate,isnull(sfd.totaldeductamount,0) as totaldeductamount ,ISNULL(sfd.NoOfClicks,0) as NoOfClicks,
case  when adtype=0 then ' || CAST('''Text''' AS VARCHAR(50)) || ' when adtype=1 then ' || CAST('''Image''' AS VARCHAR(50)) || '  end as AdType, case
when campactive=1 then ' || CAST('''Deactive''' AS VARCHAR(50)) || ' when campactive=0 then ' || CAST('''Active''' AS VARCHAR(50)) || '
 end as Status,c.currencysymbol from tbl_sponsor_master_campain 
tsmc inner join tbl_sponsor_master tsm on tsm.plid=tsmc.smid left join 
(SELECT smcid,sum(deductamount) as totaldeductamount ,
COUNT(smcid) AS NoOfClicks FROM tbl_sponserfunddetails group by smcid) sfd on tsmc.smcid=sfd.smcid inner join 
Portal_Login pl on  pl.plid=tsmc.plid join COUNTRY c on tsmc.cid=c.CID where tsmc.smid<>0';
  IF (v_datefrom <> '' AND v_dateto <> '') THEN
  v_query := v_query || ' and convert(date,tsmc.campaincreatedate) between ''' || CAST(v_datefrom AS VARCHAR(200)) || ''' and ''' || CAST(v_dateto AS VARCHAR(200)) || '''';
  ELSE
  IF (v_datefrom <> '') THEN
  v_query := v_query || ' and convert(date,tsmc.campaincreatedate) >= ''' || CAST(v_datefrom AS VARCHAR(200)) || '''';
  END IF;
  END IF;
  IF (v_camptype <> '') THEN
  v_query := v_query || ' and adtype=''' || v_camptype || '''';
  END IF;
  IF (v_status <> '') THEN
  v_query := v_query || ' and campactive=''' || v_status || '''';
  END IF;
  IF (v_cid <> '') THEN
  v_query := v_query || ' and tsmc.cid=' || v_cid || '';
  END IF;
  IF (v_slid <> '' AND v_slid <> '0') THEN
  v_query := v_query || ' and tsmc.smid=' || CAST(v_slid AS VARCHAR(10)) || '';
  END IF;
  IF (v_sortbyclicks <> '' AND v_sortbycost <> '') THEN
  v_query := v_query || ' order by sfd.totaldeductamount,sfd.NoOfClicks ' || v_sortbycost || '';
  ELSE
  IF (v_sortbyclicks <> '') THEN
  v_query := v_query || ' order by sfd.NoOfClicks ' || v_sortbyclicks || '';
  ELSE
  IF (v_sortbycost <> '') THEN
  v_query := v_query || ' order by sfd.totaldeductamount ' || v_sortbycost || '';
  END IF;
  END IF;
  END IF;
  IF (v_sortbycost = '' AND v_sortbyclicks = '') THEN
  v_query := v_query || ' order by campaincreatedate desc';
  END IF;
  RETURN QUERY SELECT v_query;
END;
$$;


--
-- Name: usp_campaignpricemaster(integer, integer, integer, integer, integer, text, integer, integer, character varying, character varying, integer, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_campaignpricemaster(v_mode integer DEFAULT 2, v_startrowindex integer DEFAULT 1, v_maxrows integer DEFAULT 100, v_tucpmid integer DEFAULT 0, v_campaigntypeid integer DEFAULT 0, v_campaigntypename text DEFAULT ''::text, v_noofpointdeductforshare integer DEFAULT 0, v_noofpointdeductforview integer DEFAULT 0, v_status character varying DEFAULT ''::character varying, v_lastactivitydate character varying DEFAULT ''::character varying, v_intresult integer DEFAULT 0, v_recordcount integer DEFAULT 0) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
BEGIN
  -- SET option (removed)
  IF (v_mode = 1) THEN
  IF NOT EXISTS(SELECT 1 FROM tbl_usercampaignpricemaster WHERE campaigntypeid = v_campaigntypeid) THEN
  INSERT INTO tbl_usercampaignpricemaster (campaigntypeid, campaigntypename, noofpointdeductforshare, noofpointdeductforview, status, lastactivitydate) VALUES (v_campaigntypeid, v_campaigntypename, v_noofpointdeductforshare, v_noofpointdeductforview, 1, CURRENT_TIMESTAMP);
  v_intresult := 1;
  ELSE
  v_intresult := -1;
  END IF;
  END IF;
  IF (v_mode = 2) THEN
  RETURN QUERY SELECT ROW_NUMBER() OVER (ORDER BY tucpmid NULLS FIRST) AS rownunber, CAST(TO_CHAR(lastactivitydate, 'DD-MM-YYYY') AS VARCHAR(30)) AS lastactivitydate, CASE WHEN status = 1 THEN 'Active' ELSE 'Deactive' END AS status, * FROM tbl_usercampaignpricemaster;
  SELECT COUNT(1) INTO v_recordcount FROM tbl_usercampaignpricemaster;
  END IF;
  IF (v_mode = 3) THEN
  RETURN QUERY SELECT * FROM tbl_usercampaignpricemaster WHERE tucpmid = v_tucpmid;
  END IF;
  IF (v_mode = 4) THEN
  UPDATE tbl_usercampaignpricemaster SET campaigntypeid = v_campaigntypeid, campaigntypename = v_campaigntypename, noofpointdeductforview = v_noofpointdeductforview, noofpointdeductforshare = v_noofpointdeductforshare, lastactivitydate = CURRENT_TIMESTAMP WHERE tucpmid = v_tucpmid;
  v_intresult := 2;
  END IF;
  -- SET option (removed)
  IF (0 <> 0) THEN
  v_intresult := 0;
  RETURN;
  END IF;
END;
$$;


--
-- Name: usp_cancelorderandrefundamount(integer, character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_cancelorderandrefundamount(v_opdid integer DEFAULT 1, v_strresult character varying DEFAULT ''::character varying) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_ordernumber VARCHAR(150);
  v_clid INT;
  v_loginid VARCHAR(500);
  v_did INT;
  v_orderid VARCHAR(500);
  v_totalpaidamount DECIMAL(18,8);
  v_oorid INT;
  v_mlmwallet DECIMAL(18,8);
  v_customerwallet DECIMAL(18,8);
  v_remark VARCHAR(500);
  v_customerbalance DECIMAL(18,8);
  v_mlmbalance DECIMAL(18,8);
  v_beni_username varchar(80);
  v_mlmtranid varchar(150);
  v_billamount DECIMAL(18,8);
  v_distributorbalance DECIMAL(18,8);
  v_pmid INT;
BEGIN
  -- BEGIN TRAN (removed)
  v_strresult := 'Success';
  IF NOT EXISTS(SELECT 1 FROM tbl_orderpaymentsdetails WHERE opdid = v_opdid) THEN
  v_strresult := 'Order does not found!';
  -- COMMIT (removed)
  RETURN;
  END IF;
  IF EXISTS(SELECT 1 FROM tbl_orderpaymentsdetails WHERE opdid = v_opdid AND status = 2) THEN
  v_strresult := 'This order is already cancelled';
  -- COMMIT (removed)
  RETURN;
  END IF;
  v_ordernumber := '';
  v_clid := 0;
  v_loginid := '';
  v_did := 0;
  v_orderid := '';
  v_totalpaidamount := 0;
  v_customerwallet := 0;
  v_customerbalance := 0;
  v_mlmbalance := 0;
  v_beni_username := '';
  v_billamount := 0;
  v_distributorbalance := 0;
  v_pmid := 0;
  SELECT transid, mlmwallet, customerwallet, beni_username, mlmtranid INTO v_ordernumber, v_mlmwallet, v_customerwallet, v_beni_username, v_mlmtranid FROM tbl_orderpaymentsdetails WHERE opdid = v_opdid;
  SELECT loginid, orderid, oorid INTO v_loginid, v_orderid, v_oorid FROM tbl_orderonlinerequests WHERE transactionid = v_ordernumber;
  SELECT clid, did INTO v_clid, v_did FROM tbl_customerlogin WHERE loginid = v_loginid;
  SELECT pmid INTO v_pmid FROM tbl_distributor WHERE did = v_did;
  SELECT COALESCE(availablebalance, 0) INTO v_customerbalance FROM tbl_customerwallet WHERE clid = v_clid;
  v_billamount := COALESCE(v_mlmwallet, 0) + COALESCE(v_customerwallet, 0);
  UPDATE tbl_orderpaymentsdetails SET status = 2 WHERE opdid = v_opdid;
  v_remark := 'Credit against cancel order number ' || v_orderid;
  IF (v_customerwallet > 0) THEN
  UPDATE tbl_customerwallet SET availablebalance = availablebalance + v_customerwallet WHERE clid = v_clid;
  INSERT INTO tbl_customerwallet_statements (clid, processdate, crdrtype, cramt, dramt, old_balance, balance, remarks, traceno, status) VALUES (v_clid, dbo.FUN_GETCURRENTDATE(), 'Cr', v_customerwallet, 0, v_customerbalance, (v_customerbalance + v_customerwallet), v_remark, v_ordernumber, 1);
  END IF;
  IF (v_mlmwallet > 0) THEN
  IF NOT EXISTS(SELECT 1 FROM tbl_customermlmwallet WHERE clid = v_clid) THEN
  INSERT INTO tbl_customermlmwallet (clid, totalbalance, availablebalance, updateddate, active) VALUES (v_clid, 0, 0, CURRENT_TIMESTAMP, 1);
  END IF;
  SELECT COALESCE(availablebalance, 0) INTO v_mlmbalance FROM tbl_customermlmwallet WHERE clid = v_clid;
  UPDATE tbl_customermlmwallet SET availablebalance = COALESCE(availablebalance, 0) + v_mlmwallet WHERE clid = v_clid;
  INSERT INTO tbl_customermlmwallet_statements (clid, processdate, crdrtype, cramt, dramt, old_balance, balance, remarks, traceno, status, referenceusername, referencetransactionid) VALUES (v_clid, dbo.FUN_GETCURRENTDATE(), 'Cr', v_mlmwallet, 0, v_mlmbalance, (v_mlmbalance + v_mlmwallet), v_remark, v_ordernumber, 1, v_beni_username, v_mlmtranid);
  END IF;
  SELECT COALESCE(available_wallet, 0) INTO v_distributorbalance FROM tbl_distributor_prepaid_setting WHERE pmid = v_pmid;
  UPDATE tbl_distributor_prepaid_setting SET available_wallet = available_wallet + v_billamount, used_wallet = used_wallet - v_billamount WHERE pmid = v_pmid;
  RETURN QUERY SELECT v_billamount;
  INSERT INTO tbl_resellerwalletstatement (did, date, crdrtype, cr_amount, dr_amount, remarks, status, traceno, old_bal, balance, trsid) VALUES (v_did, dbo.FUN_GETCURRENTDATE(), 'Cr', v_billamount, 0, v_remark, 1, v_ordernumber, v_distributorbalance, (v_distributorbalance + v_billamount), 2);
  IF (0 > 0) THEN
  v_strresult := 'TRANSACTION DOES NOT COMPLETE!';
  -- ROLLBACK (removed)
  RETURN;
  END IF;
  -- COMMIT (removed)
END;
$$;


--
-- Name: usp_cancelsubscription(bigint, bigint, character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_cancelsubscription(v_sdid bigint, v_sessionpmid bigint, INOUT v_strresult character varying) RETURNS character varying
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_price numeric(19,4);
  v_months int;
  v_days int;
  v_perdayprice numeric(19,4);
  v_paiddays int;
  v_approvedate timestamp;
  v_refundadmount numeric(19,4);
  v_usedamount numeric(19,4);
  v_pmid bigint;
  v_plid bigint;
BEGIN
  -- BEGIN TRAN (removed)
  v_strresult := 'ok';
  IF NOT EXISTS(SELECT sdid FROM tbl_subscription_details WHERE pmid = v_sessionpmid AND sdid = v_sdid AND COALESCE(status, 0) = 1) THEN
  -- COMMIT (removed)
  v_strresult := 'Invalid Subscription !';
  RETURN;
  END IF;
  IF NOT EXISTS(SELECT sdid FROM tbl_subscription_details WHERE pmid = v_sessionpmid AND sdid = v_sdid AND COALESCE(iscanceled, 1) = 1) THEN
  -- COMMIT (removed)
  v_strresult := 'Subscription is already canceled !';
  RETURN;
  END IF;
  v_perdayprice := 0;
  SELECT price, noofmonth, approvedate, pmid INTO v_price, v_months, v_approvedate, v_pmid FROM tbl_subscription_details WHERE sdid = v_sdid;
  v_days := v_months * 30;
  v_perdayprice := v_price / v_days;
  v_paiddays := CAST(EXTRACT(epoch FROM CAST(CAST(dbo.fun_getCurrentDate() AS TIMESTAMP) AS TIMESTAMP) - CAST(CAST(v_approvedate AS TIMESTAMP) AS TIMESTAMP)) / 86400 AS BIGINT);
  IF (v_paiddays = 0) THEN
  v_paiddays := 1;
  END IF;
  IF (v_paiddays < v_days) THEN
  v_usedamount := v_paiddays * v_perdayprice;
  v_refundadmount := (v_days - v_paiddays) * v_perdayprice;
  SELECT plid INTO v_plid FROM portal_login WHERE pmid = v_pmid;
  UPDATE tbl_subscription_wallet SET current_amount = COALESCE(current_amount, 0) + v_refundadmount WHERE plid = v_plid;
  INSERT INTO tbl_subscription_wallet_history (plid, amount, crdrtype, type, remark, date, status) VALUES (v_plid, v_refundadmount, 'Cr', 'Subscription Cancel', 'Subscription Cancel', dbo.fun_getCurrentDate(), 1);
  UPDATE portal_master SET expirydate = NULL, subkeyid = '', subcatid = '', subctid = '', subaid = '', subautocatid = '' WHERE pmid = v_pmid;
  UPDATE tbl_subscription_details SET iscanceled = 1 WHERE sdid = v_sdid;
  ELSE
  -- COMMIT (removed)
  v_strresult := 'Subscription has been expired';
  RETURN;
  END IF;
  IF (0 <> 0) THEN
  -- ROLLBACK (removed)
  v_strresult := 'Some error occurred ';
  RETURN;
  END IF;
  -- COMMIT (removed)
END;
$$;


--
-- Name: usp_catdetails_datewise_totalhits(integer, integer, character varying, character varying, character varying, integer, integer, bigint, bigint, character varying, character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_catdetails_datewise_totalhits(v_startrowindex integer, v_maxrows integer, v_orderbyfield character varying, v_searchfield character varying, v_searchvalue character varying, v_cid integer DEFAULT 0, v_sid integer DEFAULT 0, v_ctid bigint DEFAULT 0, v_aid bigint DEFAULT 0, v_fromdate character varying DEFAULT ''::character varying, v_todate character varying DEFAULT ''::character varying) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_recordcount int;
  v_regno bigint;
  v_pmid int;
  v_sqlquery text;
BEGIN
  -- SET option (removed)
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp (rowNumber bigint,
countryName varchar(50),
stateName varchar(50),
cityName varchar(100),
areaName varchar(150),
category varchar(150),
TotaltHits int,
directHits int,
InDirectHits int) ON COMMIT DROP;
  IF (v_ctid > 0) THEN
  SELECT sid INTO v_sid FROM city WHERE ctid = v_ctid;
  END IF;
  IF (v_fromdate <> '' AND v_todate = '') THEN
  v_todate := v_fromdate;
  END IF;
  IF (v_fromdate = '' AND v_todate <> '') THEN
  v_fromdate := v_todate;
  END IF;
  v_sqlquery := '';
  IF (v_orderbyfield = '') THEN
  v_orderbyfield := 'grpsushil.TotaltHits desc';
  END IF;
  v_sqlquery := 'insert into #temp select  ROW_NUMBER() OVER(ORDER BY ' || v_orderbyfield || ') as rowNumber,(case when cont.countryName=''UNITED KINGDOM'' then ''UK'' when cont.countryName=''UNITED STATES'' then ''US'' else cont.countryName end) as countryName,(isnull(st.stateName,''All'')) as statename,
 (isnull(ct.cityName,''All'')) as cityname , (isnull(amt.areaname,''All'')) as areaname ,
 pc.CatName,isnull(grpsushil.TotaltHits,0) as  TotaltHits,isnull(grpsushil.directHits,0) as directHits,isnull((grpsushil.TotaltHits -grpsushil.directHits) ,0)as InDirectHits
 from Product_Category pc left join (select aid,ctid,sid,cid ,catid, (sum(noofhits)) as TotaltHits, (sum(directhits)) as directHits, ((sum(noofhits))-(sum(directhits))) as InDirectHits 
 from tblnumberofhitsdaily_cat where  cid=' || CAST(v_cid AS VARCHAR(7)) || '';
  IF (v_fromdate <> '' AND v_todate <> '') THEN
  v_sqlquery := v_sqlquery || ' and hitdate between   convert(date,''' || v_fromdate || ''',103)  and convert(date,''' || v_todate || ''',103)  ';
  END IF;
  v_sqlquery := v_sqlquery || ' and 
 sid=' || CAST(v_sid AS VARCHAR(10)) || ' and ctid=' || CAST(v_ctid AS VARCHAR(10)) || ' and aid=' || CAST(v_aid AS VARCHAR(15)) || ' group by catid,cid,sid,ctid, aid ) as grpsushil 
on pc.catid=grpsushil.catid
left join COUNTRY cont on cont.CID=isnull(grpsushil.cid,' || CAST(v_cid AS VARCHAR(10)) || ')
left join STATE st on st.SID=isnull(grpsushil.sid,' || CAST(v_sid AS VARCHAR(15)) || ')
left join CITY ct on ct.CTID=ISNULL(grpsushil.ctid,' || CAST(v_ctid AS VARCHAR(15)) || ')
left join area_master amt on amt.aid=ISNULL(grpsushil.aid,' || CAST(v_aid AS VARCHAR(20)) || ')
 where cont.cid>0  ';
  IF (v_searchfield = 'category') THEN
  v_sqlquery := v_sqlquery || ' and pc.CatName like''%' || CAST(v_searchvalue AS VARCHAR(150)) || '%''';
  END IF;
  EXECUTE v_sqlquery;
  SELECT COUNT(*) INTO v_recordcount FROM tmp_temp;
  RETURN QUERY SELECT * FROM tmp_temp WHERE rownumber BETWEEN v_startrowindex AND v_maxrows;
  DROP TABLE IF EXISTS tmp_temp;
  RETURN QUERY SELECT v_recordcount AS recordcount;
  -- SET option (removed)
END;
$$;


--
-- Name: usp_category(integer, text, integer, text, text, boolean, text, integer, integer, integer, integer, integer, integer, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_category(v_mode integer DEFAULT 0, v_searchcategory text DEFAULT ''::text, v_catid integer DEFAULT 0, v_catname text DEFAULT ''::text, v_catdesc text DEFAULT ''::text, v_catactive boolean DEFAULT true, v_catimgname text DEFAULT ''::text, v_sequence integer DEFAULT 0, v_hotlink integer DEFAULT 0, v_intresult integer DEFAULT 0, v_maincatid integer DEFAULT 0, v_startrowindex integer DEFAULT 1, v_maxrows integer DEFAULT 100, v_categoryrelatedto integer DEFAULT 0) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_minindex INT;
  v_maxindex INT;
  v_query text;
  v_condition text;
  v_countquery text;
  v_recordcount INT;
  v_parmdefinition varchar(70);
  v_name text;
  v_outputparam Int;
BEGIN
  -- BEGIN TRAN (removed)
  -- SET option (removed)
  IF (v_mode = 0) THEN
  v_query := '';
  v_condition := '';
  v_countquery := '';
  v_minindex := (v_startrowindex - 1) * v_maxrows + 1;
  v_maxindex := v_startrowindex * v_maxrows;
  v_query := 'SELECT ROW_NUMBER() OVER(ORDER BY CATNAME) AS ROWNUMBER,CATID,CATNAME AS CATNAME ,  
(CASE CATACTIVE WHEN 1 THEN ''Active'' ELSE ''Deactive'' END) AS CATACTIVE,CATIMGNAME,CATDESC,CategoryRelatedTo  
INTO #TEMP13 FROM PRODUCT_CATEGORY PC WHERE 1=1';
  v_parmdefinition := N'@INTRESULT NVARCHAR(70) OUTPUT';
  v_countquery := N'SELECT @INTRESULT= COUNT(1)FROM PRODUCT_CATEGORY Pc where 1=1';
  IF (v_searchcategory <> '') THEN
  v_searchcategory := REPLACE(v_searchcategory, '''', '''''');
  v_condition := v_condition || ('AND PC.CATNAME=''' || v_searchcategory || '''');
  END IF;
  v_query := v_query || v_condition || ' ;SELECT  *  FROM #TEMP13 WHERE ROWNUMBER BETWEEN ' || CAST(v_minindex AS VARCHAR(70)) || ' AND ' || CAST(v_maxindex AS VARCHAR(70)) || '';
  v_countquery := v_countquery || v_condition;
  RAISE NOTICE '%', v_query;
  EXECUTE v_query;
  EXECUTE v_countquery;
  v_intresult := 1;
  END IF;
  IF (v_mode = 1) THEN
  SELECT catname, catdesc INTO v_catname, v_catdesc FROM product_category WHERE catid = v_catid;
  RETURN QUERY SELECT *, v_catdesc AS catdesc FROM tbl_main_category WHERE maincatname = v_catname;
  v_intresult := 2;
  -- COMMIT (removed)
  RETURN;
  END IF;
  IF (v_mode = 2) THEN
  DROP TABLE IF EXISTS tmp_temptable;
  CREATE TEMP TABLE tmp_temptable (ROWNO INT GENERATED BY DEFAULT AS IDENTITY,  
SINGLEVALUE text) ON COMMIT DROP;
  v_name := '';
  INSERT INTO tmp_temptable SELECT value FROM dbo.SPLITSTRINGBYCUSTOMSYMBOLSHOPING(v_catname, '~');
  SELECT singlevalue INTO v_name FROM tmp_temptable;
  IF (v_catimgname = '') THEN
  SELECT catimgname INTO v_catimgname FROM product_category WHERE catid = v_catid;
  END IF;
  IF (NOT EXISTS(SELECT 1 FROM product_category WHERE catname = v_catname AND catid <> v_catid)) THEN
  UPDATE product_category SET catname = v_catname, catdesc = v_catdesc, catactive = v_catactive, catimgname = v_catimgname, categoryrelatedto = v_categoryrelatedto WHERE catid = v_catid;
  UPDATE tbl_main_category SET maincatname = v_catname, status = v_catactive, main_cat_code = dbo.REMOVESPACESANDSPECIALCHARS(v_name), sequence = (CASE WHEN v_sequence = 0 THEN sequence ELSE v_sequence END), imagename = (CASE WHEN v_catimgname = '' THEN imagename ELSE v_catimgname END), ishot_links = v_hotlink, categoryrelatedto = v_categoryrelatedto WHERE maincatid = v_catid;
  v_intresult := 3;
  -- COMMIT (removed)
  RETURN;
  ELSE
  v_intresult := 5;
  END IF;
  DROP TABLE IF EXISTS tmp_temptable;
  -- ROLLBACK (removed)
  RETURN;
  END IF;
  IF (v_mode = 3) THEN
  IF (NOT EXISTS(SELECT 1 FROM product_category WHERE catname = v_catname)) THEN
  v_outputparam := 0;
  SELECT v_intresult INTO v_outputparam FROM dbo.usp_insert_alltypecategory_new(v_id => '0', v_value => v_catname, v_type => 'MAINCATEGORY', v_varresult => '', v_intresult => v_outputparam, v_imagename => v_catimgname, v_imagesequence => v_categoryrelatedto, v_hotlink => v_hotlink);
  IF (v_outputparam = 0) THEN
  v_intresult := 0;
  -- ROLLBACK (removed)
  RETURN;
  END IF;
  INSERT INTO product_category (catname, catdesc, catactive, catimgname, gmid, categoryrelatedto) VALUES (v_catname, v_catdesc, v_catactive, v_catimgname, 0, v_categoryrelatedto);
  IF (v_outputparam = 1) THEN
  v_intresult := 4;
  -- COMMIT (removed)
  RETURN;
  END IF;
  ELSE
  v_intresult := 5;
  END IF;
  -- ROLLBACK (removed)
  RETURN;
  END IF;
  -- SET option (removed)
  -- COMMIT (removed)
END;
$$;


--
-- Name: usp_categorybind_returnploicy(integer, integer, integer, integer, character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_categorybind_returnploicy(v_days integer DEFAULT 10, v_return integer DEFAULT 1, v_refund integer DEFAULT 0, v_exchange integer DEFAULT 0, v_policyremarks character varying DEFAULT '<p><br></p>'::character varying) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
BEGIN
  RETURN QUERY WITH x AS (SELECT catname, CAST(ssc.subcatname AS text) AS subcatname, return, refund, exchange, days, policyremarks, ROW_NUMBER() OVER (PARTITION BY sc.catname ORDER BY ssc.subcatname NULLS FIRST) AS r1 FROM tbl_sub_category AS ssc INNER JOIN tbl_category AS sc ON ssc.catid = sc.catid WHERE days = v_days AND return = v_return AND refund = v_refund AND exchange = v_exchange AND policyremarks = v_policyremarks), a AS (SELECT catname, subcatname, return, refund, exchange, days, policyremarks, r1 FROM x WHERE r1 = 1), r AS (SELECT catname, subcatname, return, refund, exchange, days, policyremarks, r1 FROM a WHERE r1 = 1 UNION ALL SELECT x.catname, r.subcatname || N', ' || x.subcatname, x.return, x.refund, x.exchange, x.days, x.policyremarks, x.r1 FROM x INNER JOIN r ON r.catname = x.catname AND x.r1 = r.r1 + 1) SELECT DISTINCT catname, MAX(subcatname) AS subcatname, return, refund, exchange, days, policyremarks FROM r GROUP BY catname, return, refund, exchange, days, policyremarks ORDER BY catname DESC NULLS LAST;
END;
$$;


--
-- Name: usp_categorylist(integer, integer, character varying, character varying, character varying, integer, text); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_categorylist(v_startrowindex integer DEFAULT 1, v_maxrows integer DEFAULT 100, v_searchfield character varying DEFAULT ''::character varying, v_searchvalue character varying DEFAULT ''::character varying, v_status character varying DEFAULT '1'::character varying, v_totalcount integer DEFAULT 0, v_searchcategory text DEFAULT ''::text) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_minindex int;
  v_maxindex int;
  v_query text;
BEGIN
  v_minindex := (v_startrowindex - 1) * v_maxrows + 1;
  v_maxindex := v_startrowindex * v_maxrows;
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp (rowNumber int,
CATID bigint,
CATNAME varchar(500),
CATDESC varchar(500),
CATACTIVE varchar(100),
CATIMGNAME varchar(500)) ON COMMIT DROP;
  v_query := 'insert into #temp  select ROW_NUMBER() over (order by pc.CATID desc) as rownumber,CATID,
  isnull(CATNAME,'''') as CATNAME,isnull(CATDESC,'''') as CATDESC,(CASE CATACTIVE WHEN 1 THEN ''Active'' ELSE ''Deactive'' END) AS CATACTIVE,isnull(CATIMGNAME,'''') as CATIMGNAME
   from PRODUCT_CATEGORY pc  where 1=1';
  v_query := v_query;
  IF (v_searchfield = 'CATNAME') THEN
  v_query := v_query || ' and pc.CATNAME like ''%' || v_searchvalue || '%''';
  END IF;
  IF (v_status <> '') THEN
  v_query := v_query || ' AND pc.CATACTIVE = +CONVERT(VARCHAR(20),''' || v_status || ''') ';
  END IF;
  IF (v_searchcategory <> '') THEN
  v_searchcategory := REPLACE(v_searchcategory, '''', '''''');
  v_query := v_query || ('AND PC.CATNAME=''' || v_searchcategory || '''');
  END IF;
  EXECUTE v_query;
  RETURN QUERY SELECT * FROM tmp_temp WHERE rownumber BETWEEN v_minindex AND v_maxindex ORDER BY rownumber ASC NULLS FIRST;
  SELECT COUNT(rownumber) INTO v_totalcount FROM tmp_temp;
  DROP TABLE IF EXISTS tmp_temp;
  -- SET option (removed)
END;
$$;


--
-- Name: usp_categorywiseblogdetails(integer, integer, text, text, character varying, character varying, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_categorywiseblogdetails(v_startrowindex integer, v_maxrows integer, v_searchtype text, v_catname text, v_fromdate character varying, v_todate character varying, v_recordcount integer) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_sqlquery text;
  v_totalcount int;
  v_i int;
  v_catid1 varchar(100);
  v_kmid varchar(100);
BEGIN
  -- SET option (removed)
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp (rowNumber int GENERATED BY DEFAULT AS IDENTITY,
blogid varchar(20),
category text,
title text,
status varchar(100),
DOC varchar(200),
blogtype varchar(200)) ON COMMIT DROP;
  DROP TABLE IF EXISTS tmp_temp1;
  CREATE TEMP TABLE tmp_temp1 (rownumber int GENERATED BY DEFAULT AS IDENTITY,
catid varchar(100)) ON COMMIT DROP;
  DROP TABLE IF EXISTS tmp_temp2;
  CREATE TEMP TABLE tmp_temp2 (rownumber int GENERATED BY DEFAULT AS IDENTITY,
kmid varchar(100)) ON COMMIT DROP;
  v_sqlquery := '';
  v_sqlquery := 'insert into #temp (blogid ,category ,title,status,DOc,blogtype)  select  blogid,category, bm.BlogTitle, (case when bm.Status =1  then ''Active'' else ''Deactive'' end) as status ,
 CONVERT(VARCHAR(24),bm.BlogCreationDate,105) as DOC,(case when bm.PublishStatus =1  then ''Published'' else ''Draft'' end) as PublishStatus from tbl_blogmaster bm  where bm.Status=1  ';
  IF (v_fromdate = '' OR v_todate = '') THEN
  IF (v_fromdate <> '') THEN
  v_sqlquery := v_sqlquery || ' and convert(date, bm.BlogCreationDate,105)= replace(convert(date,''' || v_fromdate || ''',105),''/'',''-'') ';
  END IF;
  IF (v_todate <> '') THEN
  v_sqlquery := v_sqlquery || ' and convert(date, bm.BlogCreationDate,105)  =replace(convert(date,''' || v_todate || ''',105),''/'',''-'') ';
  END IF;
  END IF;
  IF (v_fromdate <> '' AND v_todate <> '') THEN
  v_sqlquery := v_sqlquery || ' and  convert(date, bm.BlogCreationDate,105)  between  replace(convert(date,''' || v_fromdate || ''',105),''/'',''-'')  and replace(convert(date,''' || v_todate || ''',105),''/'',''-'')';
  END IF;
  IF (v_searchtype = 'blogname') THEN
  v_sqlquery := v_sqlquery || ' and bm.BlogTitle like ''%' || v_catname || '%'' ';
  EXECUTE v_sqlquery || '  order by blogid desc ';
  RETURN QUERY SELECT *, COALESCE(dbo.fun_GetCategoryName(category), '-') AS catname FROM tmp_temp WHERE rownumber BETWEEN v_startrowindex AND v_maxrows;
  SELECT COUNT(*) INTO v_recordcount FROM tmp_temp;
  DROP TABLE IF EXISTS tmp_temp;
  DROP TABLE IF EXISTS tmp_temp1;
  RETURN QUERY SELECT v_recordcount AS recordcount;
  RETURN;
  END IF;
  IF (v_searchtype = 'categoryname') THEN
  INSERT INTO tmp_temp1 SELECT catid FROM product_category WHERE catname LIKE '%' || v_catname || '%';
  SELECT COUNT(*) INTO v_totalcount FROM tmp_temp1;
  v_i := 1;
  WHILE (v_i <= v_totalcount) LOOP
  SELECT catid INTO v_catid1 FROM tmp_temp1 WHERE rownumber = v_i;
  v_sqlquery := v_sqlquery || ' and ((category in(''' || CAST(v_catid1 AS text) || ''')) or (category like (''%,' || CAST(v_catid1 AS text) || ',%''))  or  (category like (''%' || CAST(v_catid1 AS text) || ',%'')) 
							or  (category like (''%,' || CAST(v_catid1 AS text) || ''')))';
  EXECUTE v_sqlquery;
  v_i := v_i + 1;
  END LOOP;
  SELECT COUNT(*) INTO v_recordcount FROM tmp_temp;
  RETURN QUERY SELECT *, COALESCE(dbo.fun_GetCategoryName(category), '-') AS catname FROM tmp_temp WHERE rownumber BETWEEN v_startrowindex AND v_maxrows;
  DROP TABLE IF EXISTS tmp_temp;
  DROP TABLE IF EXISTS tmp_temp1;
  RETURN QUERY SELECT v_recordcount AS recordcount;
  RETURN;
  END IF;
  IF (v_searchtype = '') THEN
  EXECUTE v_sqlquery || '  order by blogid desc ';
  RETURN QUERY SELECT *, COALESCE(dbo.fun_GetCategoryName(category), '-') AS catname FROM tmp_temp WHERE rownumber BETWEEN v_startrowindex AND v_maxrows;
  SELECT COUNT(*) INTO v_recordcount FROM tmp_temp;
  DROP TABLE IF EXISTS tmp_temp;
  DROP TABLE IF EXISTS tmp_temp1;
  RETURN QUERY SELECT v_recordcount AS recordcount;
  END IF;
  -- SET option (removed)
END;
$$;


--
-- Name: usp_categorywiselistingdetails(integer, integer, character varying, character varying, text, text, character varying, character varying, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_categorywiselistingdetails(v_startrowindex integer, v_maxrows integer, v_cid character varying, v_ctid character varying, v_searchtype text, v_catname text, v_fromdate character varying, v_todate character varying, v_recordcount integer) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_sqlquery text;
  v_totalcount int;
  v_i int;
  v_catid1 varchar(100);
  v_kmid varchar(100);
BEGIN
  -- SET option (removed)
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp (ROWNUMBER INT GENERATED BY DEFAULT AS IDENTITY,
PMID VARCHAR(20),
CATID text,
KEYID text,
COMPANYNAME text,
COUNTRYNAME VARCHAR(150),
CITYNAME VARCHAR(100),
ACTIVE VARCHAR(100),
DOC VARCHAR(200)) ON COMMIT DROP;
  DROP TABLE IF EXISTS tmp_temp1;
  CREATE TEMP TABLE tmp_temp1 (ROWNUMBER INT GENERATED BY DEFAULT AS IDENTITY,
CATID VARCHAR(100),
CATNAME varchar(200)) ON COMMIT DROP;
  DROP TABLE IF EXISTS tmp_temp2;
  CREATE TEMP TABLE tmp_temp2 (ROWNUMBER INT GENERATED BY DEFAULT AS IDENTITY,
KMID VARCHAR(100),
KEYWORDNAME varchar(200)) ON COMMIT DROP;
  v_sqlquery := '';
  v_sqlquery := 'INSERT INTO #TEMP (PMID ,CATID ,KEYID,COMPANYNAME,COUNTRYNAME,CITYNAME,ACTIVE,DOC)  SELECT  ISNULL(PM.PMID,''-'') AS PMID, 
PM.CATID,PM.KEYID, PM.TITLE, (CASE WHEN CNT.COUNTRYNAME=''UNITED STATES'' THEN ''US'' WHEN CNT.COUNTRYNAME=''UNITED KINGDOM'' THEN ''UK'' ELSE  CNT.COUNTRYNAME END  ) AS COUNTRYNAME, C.CITYNAME, 
(CASE WHEN PM.ACTIVE =1 
THEN ''Active'' ELSE ''BLock'' END) AS STATUS , CONVERT(VARCHAR(24),PM.DOC,105) AS DOC FROM PORTAL_MASTER PM
INNER JOIN COUNTRY CNT
ON PM.CID=CNT.CID INNER JOIN CITY C ON PM.CTID=C.CTID  ';
  IF (v_cid <> '') THEN
  v_sqlquery := v_sqlquery || (' AND C.CID LIKE ''%' || CAST(v_cid AS text) || '%''');
  END IF;
  IF (v_fromdate = '' OR v_todate = '') THEN
  IF (v_fromdate <> '') THEN
  v_sqlquery := v_sqlquery || ' AND CONVERT(DATE, PM.DOC,103)= REPLACE(CONVERT(DATE,''' || v_fromdate || ''',103),''/'',''-'') ';
  END IF;
  IF (v_todate <> '') THEN
  v_sqlquery := v_sqlquery || ' AND CONVERT(DATE, PM.DOC,103)  =REPLACE(CONVERT(DATE,''' || v_todate || ''',103),''/'',''-'') ';
  END IF;
  END IF;
  IF (v_fromdate <> '' AND v_todate <> '') THEN
  v_sqlquery := v_sqlquery || ' AND  CONVERT(DATE, PM.DOC,103)  BETWEEN  REPLACE(CONVERT(DATE,''' || v_fromdate || ''',103),''/'',''-'')  AND REPLACE(CONVERT(DATE,''' || v_todate || ''',103),''/'',''-'')';
  END IF;
  IF (v_ctid <> '') THEN
  v_sqlquery := v_sqlquery || ' AND C.CTID LIKE ''%' || v_ctid || '%''';
  END IF;
  IF (v_searchtype = 'categoryname') THEN
  INSERT INTO tmp_temp1 SELECT catid, catname FROM product_category WHERE catname LIKE '%' || v_catname || '%';
  SELECT COUNT(*) INTO v_totalcount FROM tmp_temp1;
  v_i := 1;
  WHILE (v_i <= v_totalcount) LOOP
  SELECT catid INTO v_catid1 FROM tmp_temp1 WHERE rownumber = v_i;
  v_sqlquery := v_sqlquery || ' AND ((PM.CATID IN(''' || CAST(v_catid1 AS text) || ''')) OR (PM.CATID LIKE (''%,' || CAST(v_catid1 AS text) || ',%''))  OR  (PM.CATID LIKE (''%' || CAST(v_catid1 AS text) || ',%'')) 
							OR  (PM.CATID LIKE (''%,' || CAST(v_catid1 AS text) || ''')))';
  EXECUTE v_sqlquery;
  v_i := v_i + 1;
  END LOOP;
  SELECT COUNT(*) INTO v_recordcount FROM tmp_temp;
  RETURN QUERY SELECT *, COALESCE(dbo.FUN_GETCATEGORYNAME(catid), '-') AS catname, COALESCE(dbo.FUN_GETKEYNAME(keyid), '-') AS keyname FROM tmp_temp WHERE rownumber BETWEEN v_startrowindex AND v_maxrows;
  DROP TABLE IF EXISTS tmp_temp;
  DROP TABLE IF EXISTS tmp_temp1;
  RETURN QUERY SELECT v_recordcount AS recordcount;
  -- SET option (removed)
  RETURN;
  END IF;
  IF (v_searchtype = 'keywordname') THEN
  INSERT INTO tmp_temp2 SELECT kmid, keywordname FROM keyword_master WHERE keywordname LIKE '%' || v_catname || '%';
  SELECT COUNT(*) INTO v_totalcount FROM tmp_temp2;
  v_i := 1;
  WHILE (v_i <= v_totalcount) LOOP
  SELECT kmid INTO v_kmid FROM tmp_temp2 WHERE rownumber = v_i;
  v_sqlquery := v_sqlquery || ' AND ((PM.KEYID IN(''' || CAST(v_kmid AS text) || ''')) OR (PM.KEYID LIKE (''%,' || CAST(v_kmid AS text) || ',%''))  OR  (PM.KEYID LIKE (''%' || CAST(v_kmid AS text) || ',%'')) 
							OR  (PM.KEYID LIKE (''%,' || CAST(v_kmid AS text) || ''')))';
  EXECUTE v_sqlquery;
  v_i := v_i + 1;
  END LOOP;
  SELECT COUNT(*) INTO v_recordcount FROM tmp_temp;
  RETURN QUERY SELECT *, COALESCE(dbo.FUN_GETCATEGORYNAME(catid), '-') AS catname, COALESCE(dbo.FUN_GETKEYNAME(keyid), '-') AS keyname FROM tmp_temp WHERE rownumber BETWEEN v_startrowindex AND v_maxrows;
  DROP TABLE IF EXISTS tmp_temp;
  DROP TABLE IF EXISTS tmp_temp1;
  RETURN QUERY SELECT v_recordcount AS recordcount;
  -- SET option (removed)
  RETURN;
  ELSE
  EXECUTE v_sqlquery || '  ORDER BY PM.DOC DESC';
  SELECT COUNT(*) INTO v_recordcount FROM tmp_temp;
  RETURN QUERY SELECT *, COALESCE(dbo.FUN_GETCATEGORYNAME(catid), '-') AS catname, COALESCE(dbo.FUN_GETKEYNAME(keyid), '-') AS keyname FROM tmp_temp WHERE rownumber BETWEEN v_startrowindex AND v_maxrows;
  DROP TABLE IF EXISTS tmp_temp;
  DROP TABLE IF EXISTS tmp_temp1;
  END IF;
  -- SET option (removed)
END;
$$;


--
-- Name: usp_categorywisetotalhits(integer, integer, character varying, character varying, character varying, integer, integer, bigint, bigint, character varying, character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_categorywisetotalhits(v_startrowindex integer, v_maxrows integer, v_orderbyfield character varying, v_searchfield character varying, v_searchvalue character varying, v_cid integer DEFAULT 0, v_sid integer DEFAULT 0, v_ctid bigint DEFAULT 0, v_aid bigint DEFAULT 0, v_fromdate character varying DEFAULT ''::character varying, v_todate character varying DEFAULT ''::character varying) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_recordcount int;
  v_regno bigint;
  v_pmid int;
  v_sqlquery text;
BEGIN
  -- SET option (removed)
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp (rowNumber bigint,
countryName varchar(50),
stateName varchar(50),
cityName varchar(100),
areaName varchar(150),
category varchar(150),
directHits int,
InDirectHits int,
TotaltHits int) ON COMMIT DROP;
  IF (v_ctid > 0) THEN
  SELECT sid INTO v_sid FROM city WHERE ctid = v_ctid;
  END IF;
  v_sqlquery := '';
  IF (v_orderbyfield = '') THEN
  v_orderbyfield := 'NH.noofhits Desc';
  END IF;
  v_sqlquery := 'insert into #temp select ROW_NUMBER() OVER(ORDER BY ' || v_orderbyfield || ') as rowNumber,(case when C.countryName=''UNITED KINGDOM'' then ''UK'' when C.countryName=''UNITED STATES'' then ''US'' else C.countryName end ) as countryName,isnull(S.stateName,''All'') as stateName,
 isnull(CT.cityName,''All'') as CityName,isnull(AM.areaname+''-''+AM.pincode,''All'') as areaname,CM.CatName,isnull(NH.DirectHits,0) as DirectHits ,
 (isnull(NH.noofhits,0) -isnull(NH.DirectHits,0)) as indirectHits,isnull(NH.noofhits,0) as noofhits
from Product_Category CM
left join tblnumberofhits_cat NH on NH.catId =CM.catId and NH.CID=' || CAST(v_cid AS VARCHAR(7)) || ' and  NH.sid=' || CAST(v_sid AS VARCHAR(10)) || ' 
and NH.ctid=' || CAST(v_ctid AS VARCHAR(10)) || ' and NH.aid=' || CAST(v_aid AS VARCHAR(15)) || '
join COUNTRY C on c.CID=isnull(NH.cid,' || CAST(v_cid AS VARCHAR(10)) || ')
left join state S on S.sid=isnull(NH.sid,' || CAST(v_sid AS VARCHAR(15)) || ')
left join CITY CT on CT.CTID=isnull(NH.ctid,' || CAST(v_ctid AS VARCHAR(15)) || ')
left join area_master AM on AM.aid=isnull(NH.aid,' || CAST(v_aid AS VARCHAR(20)) || ') where cm.catid>0 ';
  IF (v_searchfield = 'category') THEN
  v_sqlquery := v_sqlquery || ' and CM.CatName like''%' || CAST(v_searchvalue AS VARCHAR(150)) || '%''';
  END IF;
  EXECUTE v_sqlquery;
  SELECT COUNT(*) INTO v_recordcount FROM tmp_temp;
  RETURN QUERY SELECT * FROM tmp_temp WHERE rownumber BETWEEN v_startrowindex AND v_maxrows;
  DROP TABLE IF EXISTS tmp_temp;
  RETURN QUERY SELECT v_recordcount AS recordcount;
  -- SET option (removed)
END;
$$;


--
-- Name: usp_catname_title_detailspage(bigint); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_catname_title_detailspage(v_pmid bigint DEFAULT 0) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_catid text;
  v_catname text;
BEGIN
  RETURN QUERY SELECT title, (SELECT RTRIM(LTRIM(COALESCE(catname, ''))) FROM product_category WHERE catid IN (SELECT value FROM dbo.SPLITSTRINGBYCOMMA(pm.catid) LIMIT 1)) AS catname FROM portal_master AS pm WHERE pmid = v_pmid;
END;
$$;


--
-- Name: usp_cewalletinformation(integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_cewalletinformation(v_plid integer) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_recordcount INT;
  v_regno BIGINT;
BEGIN
  -- SET option (removed)
  DROP TABLE IF EXISTS tmp_temp89;
  CREATE TEMP TABLE tmp_temp89 ON COMMIT DROP AS SELECT ROW_NUMBER() OVER (ORDER BY mp.date DESC NULLS LAST) AS rownumber, pl.currencysymbol, (CASE WHEN mp.trantype = 'Transfer' THEN 'Credit' WHEN mp.trantype LIKE 'Redeem-%' THEN 'Credit' WHEN mp.trantype = 'Subscription' THEN 'Credit' WHEN mp.trantype = 'refral income' THEN 'Credit' WHEN mp.trantype = 'Coupon Generate' THEN 'Debit' ELSE 'N/A' END) AS traninfo, mp.amount, mp.trantype, mp.poundamount, mp.date FROM portal_login AS pl, member_perfornemce AS mp WHERE pl.plid = mp.plid AND pl.plid = v_plid;
  SELECT COUNT(*) INTO v_recordcount FROM tmp_temp89;
  RETURN QUERY SELECT * FROM tmp_temp89;
  DROP TABLE IF EXISTS tmp_temp89;
  -- SET option (removed)
END;
$$;


