--
-- Name: usp_change_or_cancel_order(bigint, integer, character varying, character varying, character varying, character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_change_or_cancel_order(v_poid bigint DEFAULT 0, v_qnty integer DEFAULT 1, v_mode character varying DEFAULT ''::character varying, v_brcode character varying DEFAULT ''::character varying, v_emp_code character varying DEFAULT ''::character varying, INOUT v_strresult character varying DEFAULT NULL::character varying) RETURNS character varying
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_invoiceno varchar(50);
  v_bv numeric(19,4);
  v_pv numeric(19,4);
  v_orid bigint;
  v_bvnew numeric(19,4);
  v_pvnew numeric(19,4);
  v_quantity int;
  v_newtotal numeric(19,4);
  v_oldtotal numeric(19,4);
BEGIN
  -- BEGIN TRAN (removed)
  v_strresult := 'ok';
  v_bv := 0;
  v_pv := 0;
  v_newtotal := 0;
  v_oldtotal := 0;
  IF (v_mode = 'Update') THEN
  v_bvnew := (v_bv / v_quantity) * v_qnty;
  v_pvnew := (v_pv / v_quantity) * v_qnty;
  v_newtotal := v_oldtotal / v_quantity * v_qnty;
  INSERT INTO tbl_order_auto_remark (emp_code, orid, brcode, created_remark, process_date) VALUES (v_emp_code, v_poid, v_brcode, 'Porduct Order ID (POID) = 
				   ' || CAST(v_poid AS VARCHAR(50)) || ' , Has Been Updated , Quantity updated to' || CAST(v_qnty AS VARCHAR(50)) || ') by Store Id = ' || v_brcode || ' , at ' || CAST(dbo.fun_getCurrentDate() AS VARCHAR(50)), dbo.fun_getCurrentDate());
  END IF;
  IF (v_mode = 'cancel') THEN
  UPDATE tbl_product_order_master SET status = 'Cancelled' WHERE poid = v_poid;
  INSERT INTO tbl_order_auto_remark (emp_code, orid, brcode, created_remark, process_date) VALUES (v_emp_code, v_poid, v_brcode, 'Porduct Order ID (POID) = ' || CAST(v_poid AS VARCHAR(50)) || ' ,
				    Has Been Cancelled by Store Id = ' || v_brcode || ' , at ' || CAST(dbo.fun_getCurrentDate() AS VARCHAR(50)), dbo.fun_getCurrentDate());
  END IF;
  IF (0 <> 0) THEN
  -- ROLLBACK (removed)
  v_strresult := 'Some error occured';
  RETURN;
  END IF;
  -- COMMIT (removed)
END;
$$;


--
-- Name: usp_changeactivestatus(integer, integer, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_changeactivestatus(v_clid integer DEFAULT 0, v_status integer DEFAULT 0, INOUT v_result integer DEFAULT 0) RETURNS integer
    LANGUAGE plpgsql
