--
-- Name: usp_changeqcstatus(character varying, character varying, character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_changeqcstatus(v_checkids character varying DEFAULT ''::character varying, v_qcstatus character varying DEFAULT ''::character varying, v_errorreason character varying DEFAULT ''::character varying) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_count1 int;
  v_count2 int;
  v_splitdata bigint;
BEGIN
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp ON COMMIT DROP AS SELECT ROW_NUMBER() OVER (ORDER BY splitdata NULLS FIRST) AS rowno, * FROM dbo.FNSPLITSTRING(v_checkids, ',');
  v_count1 := 0;
  v_count2 := 0;
  v_count1 := 1;
  SELECT COUNT(1) INTO v_count2 FROM tmp_temp;
  WHILE (v_count1 <= v_count2) LOOP
  SELECT splitdata INTO v_splitdata FROM tmp_temp WHERE rowno = v_count1;
  IF EXISTS(SELECT 1 FROM excel_product WHERE id = v_splitdata) THEN
  UPDATE excel_product SET qcstatus = v_qcstatus, errorreason = v_errorreason WHERE id = v_splitdata;
  END IF;
  v_count1 := v_count1 + 1;
  END LOOP;
  DROP TABLE IF EXISTS tmp_temp;
END;
$$;


--
-- Name: usp_chechduplicatearea(text, text, text, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_chechduplicatearea(v_aid text DEFAULT ''::text, v_area text DEFAULT ''::text, v_pincode text DEFAULT NULL::text, INOUT v_result integer DEFAULT NULL::integer) RETURNS integer
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_res int;
  v_cid bigint;
  v_sid bigint;
  v_ctid bigint;
BEGIN
  SELECT COUNT(*) INTO v_res FROM area_master WHERE areaname = v_area AND pincode = v_pincode AND cactive = 1;
  IF (v_res > 0) THEN
  UPDATE portal_master SET areaname = v_area, pincode = v_pincode, ismannual = 0 WHERE pmid = v_aid;
  UPDATE portal_master_details SET areaname = v_area, zipcode = v_pincode WHERE pmid = v_aid;
  v_result := 2;
  RAISE NOTICE '%', v_result;
  ELSE
  UPDATE portal_master SET areaname = v_area, pincode = v_pincode, ismannual = 0 WHERE pmid = v_aid;
  UPDATE portal_master_details SET areaname = v_area, zipcode = v_pincode WHERE pmid = v_aid;
  SELECT cid, sid, ctid INTO v_cid, v_sid, v_ctid FROM portal_master WHERE pmid = v_aid;
  INSERT INTO area_master (cid, sid, ctid, areaname, cactive, pincode, pmid) VALUES (v_cid, v_sid, v_ctid, v_area, 1, v_pincode, v_aid);
  v_result := 1;
  RAISE NOTICE '%', v_result;
  END IF;
END;
$$;


--
-- Name: usp_chechduplicatecatname(text, text, text, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_chechduplicatecatname(v_catid text DEFAULT ''::text, v_catname text DEFAULT ''::text, v_status text DEFAULT NULL::text, INOUT v_result integer DEFAULT NULL::integer) RETURNS integer
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_res INT;
  v_res1 INT;
  v_productcode VARCHAR(500);
BEGIN
  SELECT COUNT(km.keywordname) INTO v_res1 FROM product_category AS pc INNER JOIN keyword_master AS km ON km.catid = pc.catid WHERE pc.catactive = 1 AND km.kactive = 1 AND keywordname = RTRIM(LTRIM(v_catname));
  SELECT COUNT(1) INTO v_res FROM product_category WHERE catname = v_catname AND catactive = 1 AND catid <> v_catid;
  IF (v_res1 > 0) THEN
  v_result := 3;
  RETURN;
  ELSE
  IF (v_res > 0) THEN
  v_result := 2;
  RAISE NOTICE '%', v_result;
  RETURN;
  ELSE
  UPDATE product_category SET catname = RTRIM(LTRIM(v_catname)), catactive = v_status WHERE catid = v_catid;
  v_productcode := '';
  DROP TABLE IF EXISTS tmp_temptable;
  CREATE TEMP TABLE tmp_temptable (ROWNO INT GENERATED BY DEFAULT AS IDENTITY,
                             SINGLEVALUE VARCHAR(200)) ON COMMIT DROP;
  INSERT INTO tmp_temptable SELECT value FROM dbo.SPLITSTRINGBYCUSTOMSYMBOLSHOPING(v_catname, '~');
  SELECT singlevalue INTO v_productcode FROM tmp_temptable;
  UPDATE tbl_main_category SET main_cat_code = dbo.REMOVESPACESANDSPECIALCHARS(v_productcode) WHERE maincatid = v_catid;
  v_result := 1;
  RAISE NOTICE '%', v_result;
  END IF;
  END IF;
END;
$$;


--
-- Name: usp_check_kyc(bigint, character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_check_kyc(v_plid bigint DEFAULT 3, INOUT v_strresult character varying DEFAULT ''::character varying) RETURNS character varying
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_regno BIGINT;
  v_all_kyc_verification INT;
  v_pancard_verification INT;
  v_kyc_status VARCHAR(50);
  v_kyc_count INT;
BEGIN
  -- BEGIN TRAN (removed)
  v_regno := 0;
  v_all_kyc_verification := 0;
  v_pancard_verification := 0;
  v_kyc_status := '';
  v_kyc_count := 0;
  SELECT regno INTO v_regno FROM member_master WHERE regno = v_plid;
  SELECT COUNT(regno) INTO v_pancard_verification FROM kyc WHERE regno = v_regno AND isaprove = 1;
  SELECT CASE WHEN (SELECT COUNT(regno) FROM kyc WHERE regno = v_regno) < 4 THEN 'Pending' WHEN (SELECT COUNT(regno) FROM kyc WHERE regno = v_regno AND isaprove = 2) > 0 THEN 'Rejected' WHEN (SELECT COUNT(regno) FROM kyc WHERE regno = v_regno AND isaprove = 0) > 0 THEN 'InProcess' ELSE 'Aproved' END INTO v_kyc_status;
  IF (v_kyc_status <> 'Aproved') THEN
  v_strresult := 'Your kyc in ' || COALESCE(v_kyc_status, 'Pending');
  -- COMMIT (removed)
  RETURN;
  END IF;
  v_strresult := 'success';
  IF (0 <> 0) THEN
  v_strresult := 'error';
  -- ROLLBACK (removed)
  RETURN;
  END IF;
  -- COMMIT (removed)
END;
$$;


--
-- Name: usp_check_pincode(character varying, character varying, character varying, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_check_pincode(v_prid character varying DEFAULT 0, v_pincode character varying DEFAULT '111111'::character varying, INOUT v_stroutput character varying DEFAULT ''::character varying, INOUT v_cod integer DEFAULT 0) RETURNS record
    LANGUAGE plpgsql
    AS $$
BEGIN
  -- SET option (removed)
  IF (LENGTH(CAST(v_pincode AS TEXT)) = 6) THEN
  IF EXISTS(SELECT 1 FROM tbl_courierpincodes WHERE pincode = v_pincode) THEN
  v_stroutput := 'Delivery available at Pincode: ' || v_pincode || '';
  SELECT COALESCE(cod, 0) INTO v_cod FROM tbl_courierpincodes WHERE pincode = v_pincode LIMIT 1;
  ELSE
  v_stroutput := 'Delivery Not available at: ' || v_pincode || ' area';
  v_cod := 0;
  END IF;
  ELSE
  v_stroutput := 'Pincode should only be 6 digits';
  v_cod := 0;
  END IF;
  -- SET option (removed)
END;
$$;


--
-- Name: usp_checkall_cppoint(integer, character varying, character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_checkall_cppoint(v_mode integer DEFAULT 1, v_username character varying DEFAULT 'CO6229499'::character varying, v_strresult character varying DEFAULT ''::character varying) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_regno INT;
  v_totalcp varchar(50);
  v_name varchar(200);
  v_mobile varchar(30);
  v_email varchar(200);
BEGIN
  IF (v_mode = 1) THEN
  IF NOT EXISTS(SELECT 1 FROM tbl_customerlogin WHERE (username = v_username OR phone = v_username)) THEN
  v_strresult := 'Invalid Username !';
  RETURN;
  ELSE
  v_regno := 0;
  v_name := '';
  v_mobile := '';
  v_email := '';
  SELECT regno INTO v_regno FROM db_affiliate.dbo.member_master WHERE (username = v_username OR mobile = v_username);
  SELECT CAST(COALESCE(SUM(bv), 0) AS VARCHAR(100)) INTO v_totalcp FROM db_affiliate.dbo.tbl_repurchasedetails WHERE regno = v_regno;
  SELECT COALESCE(fname, '') INTO v_name FROM db_affiliate.dbo.member_master WHERE regno = v_regno;
  SELECT COALESCE(mobile, '') INTO v_mobile FROM db_affiliate.dbo.member_master WHERE regno = v_regno;
  SELECT COALESCE(emailid, '') INTO v_email FROM db_affiliate.dbo.member_master WHERE regno = v_regno;
  v_strresult := v_totalcp || '^' || v_name || '^' || v_mobile || '^' || v_email;
  RETURN QUERY SELECT v_strresult;
  END IF;
  END IF;
END;
$$;


