  IF v_blogtype > 0 THEN
  SELECT COUNT(blogtitle) INTO v_count FROM tbl_blogmaster WHERE RTRIM(LTRIM(blogtitle)) = RTRIM(LTRIM(v_blogtitle)) AND blogid <> v_bid AND status = 1;
  IF (v_count > 0) THEN
  v_intresult := 1;
  RAISE NOTICE '%', 1;
  RETURN;
  ELSE
  v_intresult := 0;
  RAISE NOTICE '%', 0;
  END IF;
  END IF;
END;
$$;


