CREATE FUNCTION dbo.usp_checkdupnupdatekey(v_kmid text DEFAULT ''::text, v_keywordname text DEFAULT ''::text, v_status text DEFAULT NULL::text, INOUT v_result integer DEFAULT NULL::integer) RETURNS integer
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_res INT;
  v_res1 INT;
BEGIN
  SELECT COUNT(1) INTO v_res1 FROM product_category WHERE catname = RTRIM(LTRIM(v_keywordname)) AND catactive = 1;
