  UPDATE keyword_master SET keywordname = RTRIM(LTRIM(v_keywordname)), kactive = v_status WHERE kmid = v_kmid;
  v_result := 1;
  RAISE NOTICE '%', v_result;
  END IF;
  END IF;
END;
$$;


