-- Name: usp_checking_email_click(bigint, character varying, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_checking_email_click(v_pmtid bigint DEFAULT 0, v_emailid character varying DEFAULT NULL::character varying, INOUT v_intresult integer DEFAULT NULL::integer) RETURNS integer
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_datediff int;
  v_request_date timestamp;
  v_datediffofthiscompany int;
BEGIN
  v_intresult := 0;
  IF NOT EXISTS(SELECT loginid FROM portal_login_temp WHERE pmtid = v_pmtid AND loginid = v_emailid) THEN
  v_intresult := 2;
  RETURN;
  END IF;
  IF EXISTS(SELECT * FROM portal_login WHERE loginid = v_emailid) THEN
  v_intresult := 1;
  RETURN;
  END IF;
  IF NOT EXISTS(SELECT companyname FROM portal_master_temp WHERE pmtid = v_pmtid AND active = 1) THEN
  IF EXISTS(SELECT companyname FROM portal_master_temp WHERE pmtid = v_pmtid AND active = 0) THEN
  IF NOT EXISTS(SELECT companyname FROM portal_master_temp WHERE pmtid = v_pmtid AND CAST(EXTRACT(epoch FROM CAST(CAST(dbo.fun_getCurrentDate() AS TIMESTAMP) AS TIMESTAMP) - CAST(CAST(request_date AS TIMESTAMP) AS TIMESTAMP)) / 86400 AS BIGINT) > 7) THEN
  v_intresult := 3;
  RETURN;
  ELSE
  v_intresult := 4;
  RETURN;
  END IF;
  END IF;
  v_intresult := 2;
  RETURN;
  END IF;
  v_intresult := 1;
END;
$$;


