BEGIN
  v_intresult := 0;
  IF NOT EXISTS(SELECT plid FROM portal_login WHERE RTRIM(LTRIM(loginid)) = RTRIM(LTRIM(v_loginid)) AND active = 0) THEN
  IF EXISTS(SELECT 1 FROM portal_login_temp WHERE RTRIM(LTRIM(username)) = RTRIM(LTRIM(v_username))) THEN
  v_intresult := 4;
  RETURN;
  END IF;
  IF EXISTS(SELECT plid FROM portal_login WHERE RTRIM(LTRIM(loginid)) = RTRIM(LTRIM(v_loginid)) AND active = 1) THEN
  v_intresult := 1;
  ELSE
  IF EXISTS(SELECT pltid FROM portal_login_temp WHERE RTRIM(LTRIM(loginid)) = RTRIM(LTRIM(v_loginid)) AND active = 0) THEN
  IF EXISTS(SELECT pltid FROM portal_login_temp WHERE RTRIM(LTRIM(loginid)) = RTRIM(LTRIM(v_loginid)) AND active = 0 AND CAST(EXTRACT(epoch FROM CAST(CAST(dbo.FUN_GETCURRENTDATE() AS TIMESTAMP) AS TIMESTAMP) - CAST(CAST(doc AS TIMESTAMP) AS TIMESTAMP)) / 86400 AS BIGINT) > 7) THEN
  v_intresult := 2;
  RETURN;
  ELSE
  v_intresult := 3;
  RETURN;
  END IF;
  ELSE
  IF NOT EXISTS(SELECT plid FROM portal_login WHERE RTRIM(LTRIM(loginid)) = RTRIM(LTRIM(v_loginid)) AND active = 1) THEN
  v_intresult := 0;
  ELSE
  v_intresult := 1;
  END IF;
  END IF;
  END IF;
  ELSE
  v_intresult := 1;
  END IF;
END;
$$;


