    LANGUAGE plpgsql
    AS $$
DECLARE
  v_smid bigint;
BEGIN
  v_intresult := 0;
  IF EXISTS(SELECT smid FROM subscription_master WHERE RTRIM(LTRIM(emailid)) = RTRIM(LTRIM(v_email)) AND active = 1) THEN
  SELECT smid INTO v_smid FROM subscription_master WHERE RTRIM(LTRIM(emailid)) = RTRIM(LTRIM(v_email)) AND active = 1;
