  IF EXISTS(SELECT smid FROM subscription_master WHERE RTRIM(LTRIM(emailid)) = RTRIM(LTRIM(v_email)) AND active = 0) THEN
  v_intresult := 3;
  RETURN;
  ELSE
  v_intresult := 2;
  RETURN;
  END IF;
END;
$$;


--
-- Name: usp_checkmemberindownline(character varying, character varying, character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_checkmemberindownline(v_sessionid character varying DEFAULT '0'::character varying, v_loginid character varying DEFAULT ''::character varying, INOUT v_strresult character varying DEFAULT ''::character varying) RETURNS character varying
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_parentid VARCHAR(50);
  v_bool INT;
  v_tempid VARCHAR(50);
BEGIN
  SELECT loginid INTO v_sessionid FROM member_master WHERE plid = v_sessionid;
  v_strresult := 'no';
  SELECT m.loginid INTO v_loginid FROM member_master AS m JOIN portal_login AS l ON m.plid = l.plid WHERE l.username = v_loginid;
  IF (v_sessionid = v_loginid) THEN
  v_strresult := 'yes';
  RETURN;
  END IF;
  v_tempid := v_loginid;
  v_bool := 1;
  WHILE (v_bool > 0) LOOP
  SELECT rootid INTO v_parentid FROM member_master WHERE loginid = v_tempid;
  IF (v_parentid = v_sessionid) THEN
  v_strresult := 'yes';
  EXIT;
  END IF;
  IF (v_parentid <> v_tempid) THEN
  v_tempid := v_parentid;
  ELSE
  v_bool := 0;
  END IF;
  END LOOP;
END;
$$;


