  v_mobile := '';
  v_sid := 0;
  v_statename := '';
  v_ctid := 0;
  v_cityname := '';
  v_address := '';
  v_pincode := '';
  v_panno := '';
  v_ipadd := '';
  v_epinnumber := '';
  v_nomineename := '';
  v_nomineerelation := '';
  v_sessionloginid := '';
  v_kitid := 0;
  v_strresult := '';
  v_application_formno := '';
  v_referalcode := '';
  v_introrefid := 0;
  v_sponsorids := '';
  v_placementids := '';
  v_side := 0;
  v_title := '';
  v_desigantion := '';
  v_imagename := '';
  v_userid := '';
  v_tpassword := '';
  v_intresult := -1;
  v_maxplid := 0;
  IF EXISTS(SELECT 1 FROM customer_login_temp WHERE pltid = v_plid AND active = 0 AND did = v_distributerid) THEN
  UPDATE customer_login_temp SET password = v_password1, tpassword = v_password1 WHERE pltid = v_plid AND active = 0 AND did = v_distributerid;
  SELECT COALESCE(loginid, ''), COALESCE(password, ''), COALESCE(intro_refid, ''), COALESCE(username, ''), COALESCE(currencysymbol, ''), COALESCE(cid, 0), COALESCE(ipaddress, ''), COALESCE(sp_firstname, ''), COALESCE(sp_lastname, ''), COALESCE(phone, ''), COALESCE(emailid, ''), COALESCE(refral_id, ''), COALESCE(sponserid, ''), COALESCE(placementid, ''), COALESCE(side, 0), COALESCE(title, ''), COALESCE(designation, ''), COALESCE(imagename, ''), COALESCE(spounsertype, 0), COALESCE(userid, ''), COALESCE(sid, 0), COALESCE(ctid, 0), COALESCE(cityname, ''), COALESCE(tpassword, '') INTO v_loginid, v_password, v_plidref, v_username, v_currencysymbol, v_cid, v_ipaddress, v_fname, v_lname, v_mobile, v_email, v_referalcode, v_sponsorids, v_placementids, v_side, v_title, v_desigantion, v_imagename, v_spounsertype, v_userid, v_sid, v_ctid, v_cityname, v_tpassword FROM customer_login_temp WHERE pltid = v_plid;
  SELECT currencycode INTO v_currency FROM country WHERE cid = v_cid;
  IF (v_mobile <> '') THEN
  IF NOT EXISTS(SELECT 1 FROM tbl_customerlogin WHERE phone = v_mobile AND did = v_distributerid) THEN
  INSERT INTO tbl_customerlogin (loginid, password, active, doc, currencysymbol, currency, cid, intro_refid, username, ipaddress, fname, lname, regno, referalcode, pmid, phone, imagename, designation, title, intro_plid, emailid, spounsertype, defaultlandingurl, userid, sid, ctid, cityname, tpassword, did) VALUES (v_loginid, v_password, 1, dbo.FUN_GETCURRENTDATE(), v_currencysymbol, v_currency, v_cid, v_plidref, v_username, v_ipaddress, v_fname, v_lname, v_maxplid, v_referalcode, 0, v_mobile, v_imagename, v_desigantion, v_title, v_introrefid, v_email, v_spounsertype, 1, v_userid, v_sid, v_ctid, v_cityname, v_tpassword, v_distributerid);
  v_maxplid := IDENT_CURRENT('TBL_CUSTOMERLOGIN');
  UPDATE tbl_customerlogin SET regno = v_maxplid WHERE clid = v_maxplid;
