  INSERT INTO tbl_customerlogin (loginid, password, active, doc, currencysymbol, currency, cid, intro_refid, username, ipaddress, fname, lname, regno, referalcode, pmid, phone, imagename, designation, title, intro_plid, emailid, spounsertype, defaultlandingurl, userid, sid, ctid, cityname, tpassword, did) VALUES (v_loginid, v_password, 1, dbo.FUN_GETCURRENTDATE(), v_currencysymbol, v_currency, v_cid, v_plidref, v_username, v_ipaddress, v_fname, v_lname, v_maxplid, v_referalcode, 0, v_mobile, v_imagename, v_desigantion, v_title, v_introrefid, v_email, v_spounsertype, 1, v_userid, v_sid, v_ctid, v_cityname, v_tpassword, v_distributerid);
  v_maxplid := IDENT_CURRENT('TBL_CUSTOMERLOGIN');
  UPDATE tbl_customerlogin SET regno = v_maxplid WHERE clid = v_maxplid;
  UPDATE customer_login_temp SET active = 1 WHERE pltid = v_plid;
  v_intresult := 1;
  RETURN QUERY SELECT * FROM tbl_customerlogin;
