  UPDATE customer_login_temp SET password = v_password1, tpassword = v_password1, active = 1 WHERE phone = v_mobile OR emailid = v_email AND did = v_distributerid;
  SELECT clid INTO v_maxplid FROM tbl_customerlogin WHERE phone = v_mobile OR emailid = v_email AND did = v_distributerid;
