--
-- Name: usp_checkpermission(bigint, character varying, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_checkpermission(v_userid bigint DEFAULT 0, v_pagename character varying DEFAULT ''::character varying, INOUT v_intresult integer DEFAULT 0) RETURNS integer
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_moduleid int;
  v_checkpage int;
BEGIN
  v_intresult := 0;
  SELECT id INTO v_moduleid FROM tblmenu WHERE url LIKE '%' || v_pagename || '%' AND isactive = 1 AND isdeleted = 0;
  v_moduleid := COALESCE(v_moduleid, 0);
  SELECT usermoduleid INTO v_checkpage FROM tblusermodule WHERE moduleid = v_moduleid AND userid = v_userid AND isactive = 1 AND isdeleted = 0;
  v_checkpage := COALESCE(v_checkpage, 0);
  IF (v_checkpage > 0) THEN
  v_intresult := 1;
  ELSE
  v_intresult := 0;
  END IF;
END;
$$;


