  v_maxindex := v_startrowindex * v_maxrows;
  DROP TABLE IF EXISTS tmp_temp12;
  CREATE TEMP TABLE tmp_temp12 ON COMMIT DROP AS SELECT ROW_NUMBER() OVER (ORDER BY c.countryname NULLS FIRST, s.statename NULLS FIRST, ci.cityname NULLS FIRST, s.sid NULLS FIRST, c.cid NULLS FIRST) AS rownumber, c.countryname, s.statename, ci.cityname, s.sid, c.cid, (CASE ci.active WHEN 1 THEN 'ACTIVE' WHEN 0 THEN 'DEACTIVE' END) AS distactive, ci.ctid FROM state AS s INNER JOIN country AS c ON c.cid = s.cid INNER JOIN city AS ci ON ci.sid = s.sid WHERE ci.active = 1;
  IF (v_searchfield = '') THEN
  RETURN QUERY SELECT * FROM tmp_temp12 WHERE rownumber BETWEEN v_minindex AND v_maxindex;
  SELECT COUNT(1) INTO v_recordcount FROM tmp_temp12;
  END IF;
  IF (v_searchfield = 'COUNTRYNAME') THEN
  RETURN QUERY SELECT ROW_NUMBER() OVER (ORDER BY countryname NULLS FIRST, statename NULLS FIRST, cityname NULLS FIRST) AS rownumber, * FROM tmp_temp12 WHERE countryname LIKE '%' || v_searchvalue || '%';
  SELECT COUNT(*) INTO v_recordcount FROM tmp_temp12 WHERE countryname LIKE '%' || v_searchvalue || '%';
  END IF;
  IF (v_searchfield = 'STATENAME') THEN
  RETURN QUERY SELECT ROW_NUMBER() OVER (ORDER BY countryname NULLS FIRST, statename NULLS FIRST, cityname NULLS FIRST) AS rownumber, * FROM tmp_temp12 WHERE statename LIKE '%' || v_searchvalue || '%';
  SELECT COUNT(1) INTO v_recordcount FROM tmp_temp12 WHERE statename LIKE '%' || v_searchvalue || '%';
  END IF;
  IF (v_searchfield = 'CITYNAME') THEN
  RETURN QUERY SELECT ROW_NUMBER() OVER (ORDER BY countryname NULLS FIRST, statename NULLS FIRST, cityname NULLS FIRST) AS rownumber, * FROM tmp_temp12 WHERE cityname LIKE '%' || v_searchvalue || '%';
  SELECT COUNT(1) INTO v_recordcount FROM tmp_temp12 WHERE cityname LIKE '%' || v_searchvalue || '%';
  SELECT COALESCE(v_recordcount, 0) INTO v_intresult FROM tmp_temp12;
  END IF;
  DROP TABLE IF EXISTS tmp_temp12;
  SELECT COALESCE(v_recordcount, 0) INTO v_intresult;
  -- SET option (removed)
END;
$$;


--
-- Name: usp_clearorrejectfund(integer, integer, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_clearorrejectfund(v_tfaamid integer DEFAULT 0, INOUT v_intresult integer DEFAULT 0, v_mode integer DEFAULT 1) RETURNS integer
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_sfdid BIGINT;
  v_plid BIGINT;
  v_depositamount numeric(19,4);
  v_datetime timestamp;
  v_paymenttype varchar(50);
  v_status INT;
  v_depositdate timestamp;
  v_billid INT;
  v_reqfrom varchar(50);
  v_remark text;
  v_intresultoutput text;
BEGIN
  -- BEGIN TRAN (removed)
  BEGIN
  IF (v_mode = 1) THEN
  IF (v_tfaamid <> 0) THEN
  v_sfdid := 0;
  v_plid := 0;
  v_depositamount := 0;
  v_datetime := '';
  v_paymenttype := '';
  v_status := 1;
  v_depositdate := '';
  v_billid := 0;
  v_reqfrom := 'Fund Added By You';
  v_remark := '';
  SELECT addeddate, commentorremark, mode, plid, amount, CURRENT_TIMESTAMP INTO v_depositdate, v_remark, v_paymenttype, v_plid, v_depositamount, v_datetime FROM tbl_fundaddedapprovalmaster WHERE tfaamid = v_tfaamid;
  IF (v_sfdid = 0) THEN
  INSERT INTO tbl_sponserfunddetails (plid, depositamount, datetime, paymenttype, status, depositdate, billid, reqfrom, remark) VALUES (v_plid, v_depositamount, dbo.FUN_GETCURRENTDATE(), v_paymenttype, 1, dbo.FUN_GETCURRENTDATE(), 0, v_reqfrom, v_remark);
  v_sfdid := IDENT_CURRENT('TBL_SPONSERFUNDDETAILS');
  IF NOT EXISTS(SELECT 1 FROM ewallet WHERE plid = v_plid) THEN
  INSERT INTO ewallet (plid, amount, active, referalcommission, redemption, cramount, dramount, currencysymbol, currentrefferal, currentcramount) VALUES (v_plid, v_depositamount, 1, 0.00, 0.00, v_depositamount, 0.00, '', 0, v_depositamount);
  ELSE
  UPDATE ewallet SET amount = amount + v_depositamount, cramount = cramount + v_depositamount, currentcramount = currentcramount + v_depositamount WHERE plid = v_plid;
  END IF;
  INSERT INTO tbl_accountstatement (plid, cr, dr, balance, date, commentorremark) VALUES (v_plid, v_depositamount, 0.00, (SELECT amount FROM ewallet WHERE plid = v_plid), CURRENT_TIMESTAMP, v_remark);
  UPDATE tbl_fundaddedapprovalmaster SET status = 'Approved', isactive = 0 WHERE tfaamid = v_tfaamid;
  v_intresultoutput := '';
  SELECT v_intresult INTO v_intresultoutput FROM dbo.usp_directincomedistribution(v_plid => v_plid, v_sfdid => v_sfdid, v_intresult => v_intresultoutput);
  IF (v_intresultoutput = 'CaughtError') THEN
  v_intresult := 0;
  -- ROLLBACK (removed)
  RETURN;
  END IF;
  END IF;
  END IF;
  ELSE
  IF (v_mode = 2) THEN
  UPDATE tbl_fundaddedapprovalmaster SET status = 'Rejected' WHERE tfaamid = v_tfaamid;
  END IF;
  END IF;
  v_intresult := 1;
  -- COMMIT (removed)
  RETURN;
  EXCEPTION WHEN OTHERS THEN
  v_intresult := 0;
  -- ROLLBACK (removed)
  RETURN;
  END;
  -- COMMIT (removed)
END;
$$;


--
-- Name: usp_clickmanagements(integer, integer, integer, integer, text, integer, integer, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_clickmanagements(v_mode integer DEFAULT 1, v_plid integer DEFAULT 0, v_memberplid integer DEFAULT 0, v_tatbid integer DEFAULT 0, v_strresult text DEFAULT ''::text, v_startrowindex integer DEFAULT 1, v_maxrows integer DEFAULT 50, v_totalcount integer DEFAULT 0) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_tempdatet Date;
  v_minindex INT;
  v_maxindex INT;
  v_viewpoint text;
  v_sharepoint text;
  v_fromdate timestamp;
  v_tilldate timestamp;
  v_maxlimitsforclickbyadmint BigInt;
  v_useralreadyclickedt BigInt;
  v_maxlimitsforsharebyadmint BigInt;
  v_useralreadysharedt BigInt;
  v_earnedpoint Decimal(10,2);
  v_previousremainlinkforclick BigInt;
  v_previousremainlinkforshare BigInt;
  v_amount Decimal(10,2);
  v_netamount Decimal(10,2);
  v_currentincome Decimal(10,2);
  v_tds_per double precision;
  v_tds Decimal(10,2);
  v_admincharge_per double precision;
  v_admincharge Decimal(10,2);
  v_regno BigInt;
  v_stroutputresult Int;
  v_pointperdayforview double precision;
  v_pointperdayforshare double precision;
  v_previousremainpointforclick double precision;
  v_previousremainpointforshare double precision;
  v_priceperlinkforview double precision;
  v_priceperlinkforshare double precision;
  v_previousdate timestamp;
  v_islooping Int;
  v_tempdate Date;
  v_maxlimitsforclickbyadmin BigInt;
  v_useralreadyclicked BigInt;
  v_viewstatus INT;
  v_dailytotalclicked BigInt;
  v_maxnoofclicksperdayforview BigInt;
  v_maxlimitsforsharebyadmin BigInt;
  v_useralreadyshared BigInt;
  v_sharestatus INT;
  v_dailytotalshared BigInt;
  v_maxnooflinkperdayforshare BigInt;
BEGIN
  -- SET option (removed)
  IF (v_mode = 1) THEN
  v_tempdatet := dbo.FUN_GETCURRENTDATE();
  v_minindex := (v_startrowindex - 1) * v_maxrows + 1;
  v_maxindex := v_startrowindex * v_maxrows;
  v_viewpoint := '';
  v_sharepoint := '';
  SELECT priceperlinkforview, priceperlinkforshare INTO v_viewpoint, v_sharepoint FROM tbl_datewisecommonroiaccount WHERE CAST(date AS DATE) = CAST(CURRENT_TIMESTAMP AS DATE);
  v_tilldate := dbo.FUN_GETCURRENTDATE();
  DROP TABLE IF EXISTS tmp_tablecheck;
  CREATE TEMP TABLE tmp_tablecheck (RemainNoOfHits BigInt,
PLID BigInt) ON COMMIT DROP;
  INSERT INTO tmp_tablecheck SELECT SUM(COALESCE(remainnoofhits, 0)), plid FROM tbl_usertrafficbooster GROUP BY plid HAVING SUM(COALESCE(remainnoofhits, 0)) > 0;
  INSERT INTO tmp_tablecheck SELECT SUM(COALESCE(remainnoofhits, 0)), plid FROM tbl_membersubscriptionaccount GROUP BY plid HAVING SUM(COALESCE(remainnoofhits, 0)) > 0;
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp ON COMMIT DROP AS SELECT ROW_NUMBER() OVER (ORDER BY plid NULLS FIRST) AS rownumber, *, (CAST('' AS text)) AS viewbutton, ('<b> ' || v_viewpoint || ' P</b>') AS viewpoint, (CAST('' AS text)) AS sharebutton, ('<b> ' || v_sharepoint || ' P</b>') AS sharepoint FROM tbl_addtrafficbooster WHERE ispublished = 1 AND status = 1 AND isactive = 1 AND dbo.FUN_GETCURRENTDATE() >= fromdate AND dbo.FUN_GETCURRENTDATE() <= todate AND (plid <> v_plid OR plid = (CASE WHEN v_plid = 0 THEN 0 ELSE plid END)) AND issharetype = 1 AND (plid IN (SELECT plid FROM tmp_tablecheck WHERE remainnoofhits > 0) OR plid = 0) AND isapprovedbyadmin = 1;
  SELECT v_tilldate - 30 INTO v_fromdate;
  v_maxlimitsforclickbyadmint := 0;
  v_useralreadyclickedt := 0;
  SELECT limits INTO v_maxlimitsforclickbyadmint FROM settings WHERE caption = 'Max-No-Of-Click-Per-Day';
  SELECT COUNT(1) INTO v_useralreadyclickedt FROM tbl_membertaskincomedetails WHERE activitytype = 1 AND CAST(date AS DATE) = CAST(v_tempdatet AS DATE) AND plid = v_plid;
  IF (v_useralreadyclickedt >= v_maxlimitsforclickbyadmint) THEN
  UPDATE tmp_temp SET viewpoint = '';
  END IF;
  v_maxlimitsforsharebyadmint := 0;
  v_useralreadysharedt := 0;
  SELECT limits INTO v_maxlimitsforsharebyadmint FROM settings WHERE caption = 'Max-No-Of-Share-Per-Day';
  SELECT COUNT(1) INTO v_useralreadysharedt FROM tbl_membertaskincomedetails WHERE activitytype = 2 AND CAST(date AS DATE) = CAST(v_tempdatet AS DATE) AND plid = v_plid;
  IF (v_useralreadysharedt >= v_maxlimitsforsharebyadmint) THEN
  UPDATE tmp_temp SET sharepoint = '';
  END IF;
  UPDATE tmp_temp SET viewbutton = '
<a class="btn btn-sm btn-warning" href="' || url || '" 
target="_blank"><i class="fa fa-check clicked"></i></a>' WHERE tatbid IN (SELECT tatbid FROM tbl_membertaskincomedetails WHERE CAST(date AS DATE) >= CAST(v_fromdate AS DATE) AND CAST(date AS DATE) < CAST(v_tilldate AS DATE) AND earnedamount > 0 AND plid = v_plid AND COALESCE(activitytype, 1) = 1);
  SELECT v_tilldate - 7 INTO v_fromdate;
  UPDATE tmp_temp SET sharebutton = '<dd><i class="fa fa-check shared"></i></dd>' WHERE tatbid IN (SELECT tatbid FROM tbl_membertaskincomedetails WHERE CAST(date AS DATE) >= CAST(v_fromdate AS DATE) AND CAST(date AS DATE) < CAST(v_tilldate AS DATE) AND earnedamount > 0 AND plid = v_plid AND COALESCE(activitytype, 1) = 2);
  RETURN QUERY SELECT * FROM tmp_temp WHERE rownumber BETWEEN v_minindex AND v_maxindex ORDER BY GEN_RANDOM_UUID() ASC NULLS FIRST, viewbutton NULLS FIRST, sharebutton NULLS FIRST;
  SELECT COUNT(rownumber) INTO v_totalcount FROM tmp_temp;
  DROP TABLE IF EXISTS tmp_temp;
  END IF;
  v_earnedpoint := 0;
  v_previousremainlinkforclick := 0;
  v_previousremainlinkforshare := 0;
  v_amount := 0.00;
  v_netamount := 0.00;
  v_currentincome := 0.00;
  v_tds_per := 0.00;
  v_tds := 0.00;
  v_admincharge_per := 0.00;
  v_admincharge := 0.00;
  v_regno := 0;
  v_stroutputresult := 0;
  v_pointperdayforview := 0;
  v_pointperdayforshare := 0;
  v_previousremainpointforclick := 0;
  v_previousremainpointforshare := 0;
  v_priceperlinkforview := 0.00;
  v_priceperlinkforshare := 0.00;
  v_islooping := 1;
  v_tempdate := dbo.FUN_GETCURRENTDATE();
  IF (v_mode = 2 AND v_tatbid <> 0 AND v_memberplid > 0) THEN
  BEGIN
  v_maxlimitsforclickbyadmin := 0;
  v_useralreadyclicked := 0;
  SELECT limits INTO v_maxlimitsforclickbyadmin FROM settings WHERE caption = 'Max-No-Of-Click-Per-Day';
  SELECT COUNT(1) INTO v_useralreadyclicked FROM tbl_membertaskincomedetails WHERE activitytype = 1 AND CAST(date AS DATE) = CAST(v_tempdate AS DATE) AND plid = v_memberplid;
  IF (v_useralreadyclicked >= v_maxlimitsforclickbyadmin) THEN
  v_strresult := 'Task Done For Today';
  RETURN;
  END IF;
  v_viewstatus := 0;
  SELECT viewstatus INTO v_viewstatus FROM tbl_datewisecommonroiaccount WHERE CAST(date AS DATE) = CAST(dbo.FUN_GETCURRENTDATE() AS DATE);
  IF (v_viewstatus = 0) THEN
  v_strresult := 'Task Done For Today';
  RETURN;
  END IF;
  IF EXISTS(SELECT 1 FROM tbl_membersubscriptionaccount WHERE dbo.FUN_GETCURRENTDATE() BETWEEN activationdate AND tilldate AND plid = v_memberplid) THEN
  IF NOT EXISTS(SELECT 1 FROM tbl_dailytasklimits WHERE plid = v_memberplid AND CAST(date AS DATE) = CAST(dbo.FUN_GETCURRENTDATE() AS DATE)) THEN
  SELECT perdaypointforview, perdaypointforshare, priceperlinkforview, priceperlinkforshare INTO v_pointperdayforview, v_pointperdayforshare, v_priceperlinkforview, v_priceperlinkforshare FROM tbl_datewisecommonroiaccount WHERE CAST(date AS DATE) = CAST(dbo.FUN_GETCURRENTDATE() AS DATE) LIMIT 1;
  SELECT COALESCE((CASE WHEN totalavailableclicksforday >= totalclicked THEN ((totalavailableclicksforday - totalclicked) + previousremainclick) WHEN totalclicked > totalavailableclicksforday THEN previousremainclick ELSE 0 END), 0), COALESCE((CASE WHEN totalavailableshareforday >= totalshared THEN ((totalavailableshareforday - totalshared) + previousremainshare) WHEN totalshared > totalavailableshareforday THEN previousremainshare ELSE 0 END), 0), COALESCE(previouscarryforwardpointforclick, 0), COALESCE(previouscarryforwardpointforshare, 0), date INTO v_previousremainlinkforclick, v_previousremainlinkforshare, v_previousremainpointforclick, v_previousremainpointforshare, v_previousdate FROM tbl_dailytasklimits WHERE plid = v_memberplid ORDER BY date DESC NULLS LAST LIMIT 1;
  SELECT (COALESCE(v_previousremainpointforclick, 0) + COALESCE((v_pointperdayforview - (priceperlinkforview * maxnoofclicksperdayforview)), 0)), (COALESCE(v_previousremainpointforshare, 0) + COALESCE((v_pointperdayforshare - (priceperlinkforshare * maxnooflinkperdayforshare)), 0)) INTO v_previousremainpointforclick, v_previousremainpointforshare FROM tbl_datewisecommonroiaccount WHERE CAST(date AS DATE) = CAST(dbo.FUN_GETCURRENTDATE() AS DATE) LIMIT 1;
  WHILE (v_islooping = 1 AND (v_previousremainpointforclick > 0 OR v_previousremainpointforshare > 0)) LOOP
  IF (v_previousremainpointforclick >= v_priceperlinkforview) THEN
  v_islooping := 1;
  v_previousremainpointforclick := v_previousremainpointforclick - v_priceperlinkforview;
  v_previousremainlinkforclick := v_previousremainlinkforclick + 1;
  ELSE
  v_islooping := 0;
  END IF;
  IF (v_previousremainpointforshare >= v_priceperlinkforshare) THEN
  v_islooping := 1;
  v_previousremainpointforshare := v_previousremainpointforshare - v_priceperlinkforshare;
  v_previousremainlinkforshare := v_previousremainlinkforshare + 1;
  END IF;
  END LOOP;
  INSERT INTO tbl_dailytasklimits (date, plid, tsmid, totalavailableclicksforday, priceperclick, totalclicked, status, previouscarryforwardclick, previousremainclick, totalavailableshareforday, pricepershare, totalshared, previouscarryforwardshare, previousremainshare, previouscarryforwardpointforclick, previouscarryforwardpointforshare) SELECT dbo.FUN_GETCURRENTDATE(), v_memberplid, 0, maxnoofclicksperdayforview, priceperlinkforview, 0, status, v_previousremainlinkforclick, v_previousremainlinkforclick, maxnooflinkperdayforshare, priceperlinkforshare, 0, v_previousremainlinkforshare, v_previousremainlinkforshare, v_previousremainpointforclick, v_previousremainpointforshare FROM tbl_datewisecommonroiaccount WHERE CAST(date AS DATE) = CAST(dbo.FUN_GETCURRENTDATE() AS DATE) LIMIT 1;
  IF (CAST(v_previousdate AS DATE) <> CAST(dbo.FUN_GETCURRENTDATE() AS DATE)) THEN
  PERFORM dbo.usp_blogandclassifiedmanagemnt(v_plid => v_memberplid, v_tsmid => 0, v_intresultoutput => v_strresult, v_previousdate => v_previousdate);
  IF (v_strresult <> 'Ok') THEN
  v_strresult := 'Some Error..!! Sorry.';
  RETURN;
  END IF;
  ELSE
  PERFORM dbo.usp_blogandclassifiedmanagemnt(v_plid => v_memberplid, v_tsmid => 0, v_intresultoutput => v_strresult, v_previousdate => v_tempdate);
  IF (v_strresult <> 'Ok') THEN
  v_strresult := 'Some Error..!! Sorry.';
  RETURN;
  END IF;
  END IF;
  END IF;
  ELSE
  v_strresult := 'Not Eligible For ROI..!! Sorry.';
  RETURN;
  END IF;
  SELECT COALESCE(priceperclick, 0) INTO v_earnedpoint FROM tbl_dailytasklimits WHERE CAST(date AS DATE) = CAST(dbo.FUN_GETCURRENTDATE() AS DATE) AND totalclicked < (totalavailableclicksforday + previouscarryforwardclick) AND plid = v_memberplid ORDER BY priceperclick ASC NULLS FIRST LIMIT 1;
  IF EXISTS(SELECT 1 FROM tbl_membertaskincome WHERE plid = v_memberplid) THEN
  IF NOT EXISTS(SELECT 1 FROM tbl_membertaskincomedetails WHERE tatbid = v_tatbid AND plid = v_memberplid AND CAST(date AS DATE) = CAST(dbo.FUN_GETCURRENTDATE() AS DATE) AND COALESCE(activitytype, 1) = 1) THEN
  UPDATE tbl_membertaskincome SET totalclicked = totalclicked + 1, totalearnedamount = totalearnedamount + v_earnedpoint, totalavailableamount = totalavailableamount + v_earnedpoint WHERE plid = v_memberplid;
  END IF;
  ELSE
  INSERT INTO tbl_membertaskincome (plid, totalclicked, totalearnedamount, totalwithdrawlamount, totalavailableamount, isactive, status, tsmid) VALUES (v_memberplid, 1, v_earnedpoint, 0, v_earnedpoint, 1, 1, 0);
  END IF;
  IF NOT EXISTS(SELECT 1 FROM tbl_membertaskincomedetails WHERE tatbid = v_tatbid AND plid = v_memberplid AND CAST(date AS DATE) = CAST(dbo.FUN_GETCURRENTDATE() AS DATE) AND COALESCE(activitytype, 1) = 1) THEN
  INSERT INTO tbl_membertaskincomedetails (tatbid, date, ipaddress, country, state, city, zipcode, isunique, isrepeted, earnedamount, isactive, status, plid, tsmid) VALUES (v_tatbid, dbo.FUN_GETCURRENTDATE(), '', '', '', '', '', 1, 0, v_earnedpoint, 1, 1, v_memberplid, 0);
  UPDATE tbl_addtrafficbooster SET totalnoofhits = totalnoofhits + 1, totalnoofuniquehits = totalnoofuniquehits + 1 WHERE tatbid = v_tatbid;
  UPDATE tbl_datewisecommonroiaccount SET totalclicked = COALESCE(totalclicked, 0) + 1 WHERE CAST(date AS DATE) = CAST(dbo.FUN_GETCURRENTDATE() AS DATE);
  v_dailytotalclicked := 0;
  v_maxnoofclicksperdayforview := 0;
  SELECT totalclicked, maxnoofclicksperdayforview INTO v_dailytotalclicked, v_maxnoofclicksperdayforview FROM tbl_datewisecommonroiaccount WHERE CAST(date AS DATE) = CAST(dbo.FUN_GETCURRENTDATE() AS DATE);
  IF (v_dailytotalclicked >= v_maxnoofclicksperdayforview) THEN
  UPDATE tbl_datewisecommonroiaccount SET viewstatus = 0 WHERE CAST(date AS DATE) = CAST(dbo.FUN_GETCURRENTDATE() AS DATE);
  END IF;
  IF (v_earnedpoint > 0 AND v_memberplid <> 0) THEN
  IF (v_earnedpoint <= (SELECT CAST(COALESCE(MAX(totalavailableamount), 0) AS DECIMAL(10, 2)) AS totalavailableamount FROM tbl_membertaskincome WHERE plid = v_memberplid)) THEN
  SELECT regno INTO v_regno FROM member_master WHERE plid = v_memberplid;
  SELECT ((v_earnedpoint * 1)) INTO v_amount;
  SELECT COALESCE(v_amount * v_tds_per / 100, 0) INTO v_tds;
  SELECT COALESCE(v_amount * v_admincharge_per / 100, 0) INTO v_admincharge;
  SELECT v_amount - v_tds - v_admincharge INTO v_netamount;
  UPDATE member_performance SET redeemedpoints = (redeemedpoints + COALESCE(v_netamount, 0)) WHERE regno = v_regno;
  SELECT currentincome INTO v_currentincome FROM member_performance WHERE regno = v_regno;
  INSERT INTO money_statements (regno, processdate, crdrtype, cr_amount, dr_amount, remarks, type, typeid, status, traceno, pmoid, balance, old_bal) VALUES (v_regno, dbo.FUN_GETCURRENTDATE(), 'CR', v_amount, 0, 'Redeem Earned Points', 'Redeem Earned Points', 0, 1, '', 0, COALESCE(v_currentincome, 0), COALESCE(v_currentincome, 0));
  UPDATE tbl_membertaskincome SET totalwithdrawlamount = (totalwithdrawlamount + v_earnedpoint), totalavailableamount = (totalavailableamount - v_earnedpoint) WHERE plid = v_memberplid;
  END IF;
  END IF;
  IF (v_plid > 0) THEN
  SELECT v_intresultoutput INTO v_stroutputresult FROM dbo.usp_emailsmstrafficboosteraccountmanagement(v_mode => 3, v_plid => v_plid, v_tosmsoremail => '', v_intresultoutput => v_stroutputresult, v_tatbid => v_tatbid);
  IF (v_stroutputresult = 0) THEN
  v_strresult := 'Cancel';
  RETURN;
  END IF;
  END IF;
  UPDATE tbl_dailytasklimits SET totalclicked = COALESCE(totalclicked, 0) + 1, previousremainclick = previousremainclick - (CASE WHEN totalclicked < totalavailableclicksforday THEN 0 WHEN ((previousremainclick <= previouscarryforwardclick) AND (previousremainclick >= 1)) THEN 1 ELSE 0 END) WHERE plid = v_memberplid AND CAST(date AS DATE) = CAST(dbo.FUN_GETCURRENTDATE() AS DATE);
  END IF;
  -- SET option (removed)
  v_strresult := 'Ok';
  RETURN;
  EXCEPTION WHEN OTHERS THEN
  -- SET option (removed)
  v_strresult := 'Cancel';
  RETURN;
  END;
  END IF;
  IF (v_mode = 3 AND v_tatbid <> 0 AND v_memberplid > 0) THEN
  BEGIN
  v_maxlimitsforsharebyadmin := 0;
  v_useralreadyshared := 0;
  SELECT limits INTO v_maxlimitsforsharebyadmin FROM settings WHERE caption = 'Max-No-Of-Share-Per-Day';
  SELECT COUNT(1) INTO v_useralreadyshared FROM tbl_membertaskincomedetails WHERE activitytype = 2 AND CAST(date AS DATE) = CAST(v_tempdate AS DATE) AND plid = v_memberplid;
  IF (v_useralreadyshared >= v_maxlimitsforsharebyadmin) THEN
  v_strresult := 'Task Done For Today';
  RETURN;
  END IF;
  v_sharestatus := 0;
  SELECT sharestatus INTO v_sharestatus FROM tbl_datewisecommonroiaccount WHERE CAST(date AS DATE) = CAST(dbo.FUN_GETCURRENTDATE() AS DATE);
  IF (v_sharestatus = 0) THEN
  v_strresult := 'Task Done For Today';
  RETURN;
  END IF;
  IF EXISTS(SELECT 1 FROM tbl_membersubscriptionaccount WHERE dbo.FUN_GETCURRENTDATE() BETWEEN activationdate AND tilldate AND plid = v_memberplid) THEN
  IF NOT EXISTS(SELECT 1 FROM tbl_dailytasklimits WHERE plid = v_memberplid AND CAST(date AS DATE) = CAST(dbo.FUN_GETCURRENTDATE() AS DATE)) THEN
  SELECT perdaypointforview, perdaypointforshare, priceperlinkforview, priceperlinkforshare INTO v_pointperdayforview, v_pointperdayforshare, v_priceperlinkforview, v_priceperlinkforshare FROM tbl_datewisecommonroiaccount WHERE CAST(date AS DATE) = CAST(dbo.FUN_GETCURRENTDATE() AS DATE) LIMIT 1;
  SELECT COALESCE((CASE WHEN totalavailableclicksforday >= totalclicked THEN ((totalavailableclicksforday - totalclicked) + previousremainclick) WHEN totalclicked > totalavailableclicksforday THEN previousremainclick ELSE 0 END), 0), COALESCE((CASE WHEN totalavailableshareforday >= totalshared THEN ((totalavailableshareforday - totalshared) + previousremainshare) WHEN totalshared > totalavailableshareforday THEN previousremainshare ELSE 0 END), 0), COALESCE(previouscarryforwardpointforclick, 0), COALESCE(previouscarryforwardpointforshare, 0), date INTO v_previousremainlinkforclick, v_previousremainlinkforshare, v_previousremainpointforclick, v_previousremainpointforshare, v_previousdate FROM tbl_dailytasklimits WHERE plid = v_memberplid ORDER BY date DESC NULLS LAST LIMIT 1;
  SELECT (COALESCE(v_previousremainpointforclick, 0) + COALESCE((v_pointperdayforview - (priceperlinkforview * maxnoofclicksperdayforview)), 0)), (COALESCE(v_previousremainpointforshare, 0) + COALESCE((v_pointperdayforshare - (priceperlinkforshare * maxnooflinkperdayforshare)), 0)) INTO v_previousremainpointforclick, v_previousremainpointforshare FROM tbl_datewisecommonroiaccount WHERE CAST(date AS DATE) = CAST(dbo.FUN_GETCURRENTDATE() AS DATE) LIMIT 1;
  WHILE (v_islooping = 1 AND (v_previousremainpointforclick > 0 OR v_previousremainpointforshare > 0)) LOOP
  IF (v_previousremainpointforclick >= v_priceperlinkforview) THEN
  v_islooping := 1;
  v_previousremainpointforclick := v_previousremainpointforclick - v_priceperlinkforview;
  v_previousremainlinkforclick := v_previousremainlinkforclick + 1;
  ELSE
  v_islooping := 0;
  END IF;
  IF (v_previousremainpointforshare >= v_priceperlinkforshare) THEN
  v_islooping := 1;
  v_previousremainpointforshare := v_previousremainpointforshare - v_priceperlinkforshare;
  v_previousremainlinkforshare := v_previousremainlinkforshare + 1;
  END IF;
  END LOOP;
  INSERT INTO tbl_dailytasklimits (date, plid, tsmid, totalavailableclicksforday, priceperclick, totalclicked, status, previouscarryforwardclick, previousremainclick, totalavailableshareforday, pricepershare, totalshared, previouscarryforwardshare, previousremainshare, previouscarryforwardpointforclick, previouscarryforwardpointforshare) SELECT dbo.FUN_GETCURRENTDATE(), v_memberplid, 0, maxnoofclicksperdayforview, priceperlinkforview, 0, status, v_previousremainlinkforclick, v_previousremainlinkforclick, maxnooflinkperdayforshare, priceperlinkforshare, 0, v_previousremainlinkforshare, v_previousremainlinkforshare, v_previousremainpointforclick, v_previousremainpointforshare FROM tbl_datewisecommonroiaccount WHERE CAST(date AS DATE) = CAST(dbo.FUN_GETCURRENTDATE() AS DATE) LIMIT 1;
  IF (CAST(v_previousdate AS DATE) <> CAST(dbo.FUN_GETCURRENTDATE() AS DATE)) THEN
  PERFORM dbo.usp_blogandclassifiedmanagemnt(v_plid => v_memberplid, v_tsmid => 0, v_intresultoutput => v_strresult, v_previousdate => v_previousdate);
  IF (v_strresult <> 'Ok') THEN
  v_strresult := 'Some Error..!! Sorry.';
  RETURN;
  END IF;
  ELSE
  PERFORM dbo.usp_blogandclassifiedmanagemnt(v_plid => v_memberplid, v_tsmid => 0, v_intresultoutput => v_strresult, v_previousdate => v_tempdate);
  IF (v_strresult <> 'Ok') THEN
  v_strresult := 'Some Error..!! Sorry.';
  RETURN;
  END IF;
  END IF;
  END IF;
  ELSE
  v_strresult := 'Not Eligible For ROI..!! Sorry.';
  RETURN;
  END IF;
  SELECT COALESCE(pricepershare, 0) INTO v_earnedpoint FROM tbl_dailytasklimits WHERE CAST(date AS DATE) = CAST(dbo.FUN_GETCURRENTDATE() AS DATE) AND totalshared < (totalavailableshareforday + previouscarryforwardshare) AND plid = v_memberplid ORDER BY pricepershare ASC NULLS FIRST LIMIT 1;
  IF EXISTS(SELECT 1 FROM tbl_membertaskincome WHERE plid = v_memberplid) THEN
  IF NOT EXISTS(SELECT 1 FROM tbl_membertaskincomedetails WHERE tatbid = v_tatbid AND plid = v_memberplid AND CAST(date AS DATE) = CAST(dbo.FUN_GETCURRENTDATE() AS DATE) AND COALESCE(activitytype, 1) = 2) THEN
  UPDATE tbl_membertaskincome SET totalshared = totalshared + 1, totalearnedamount = totalearnedamount + v_earnedpoint, totalavailableamount = totalavailableamount + v_earnedpoint WHERE plid = v_memberplid;
  END IF;
  ELSE
  INSERT INTO tbl_membertaskincome (plid, totalclicked, totalearnedamount, totalwithdrawlamount, totalavailableamount, isactive, status, tsmid, totalshared) VALUES (v_memberplid, 0, v_earnedpoint, 0, v_earnedpoint, 1, 1, 0, 1);
  END IF;
  IF NOT EXISTS(SELECT 1 FROM tbl_membertaskincomedetails WHERE tatbid = v_tatbid AND plid = v_memberplid AND CAST(date AS DATE) = CAST(dbo.FUN_GETCURRENTDATE() AS DATE) AND COALESCE(activitytype, 1) = 2) THEN
  INSERT INTO tbl_membertaskincomedetails (tatbid, date, ipaddress, country, state, city, zipcode, isunique, isrepeted, earnedamount, isactive, status, plid, tsmid, activitytype) VALUES (v_tatbid, dbo.FUN_GETCURRENTDATE(), '', '', '', '', '', 1, 0, v_earnedpoint, 1, 1, v_memberplid, 0, 2);
  UPDATE tbl_addtrafficbooster SET totalnoofshare = (COALESCE(totalnoofshare, 0) + 1), totalnoofuniqueshare = totalnoofuniqueshare + 1 WHERE tatbid = v_tatbid;
  UPDATE tbl_datewisecommonroiaccount SET totalshared = COALESCE(totalshared, 0) + 1 WHERE CAST(date AS DATE) = CAST(dbo.FUN_GETCURRENTDATE() AS DATE);
  v_dailytotalshared := 0;
  v_maxnooflinkperdayforshare := 0;
  SELECT totalshared, maxnooflinkperdayforshare INTO v_dailytotalshared, v_maxnooflinkperdayforshare FROM tbl_datewisecommonroiaccount WHERE CAST(date AS DATE) = CAST(dbo.FUN_GETCURRENTDATE() AS DATE);
  IF (v_dailytotalshared >= v_maxnooflinkperdayforshare) THEN
  UPDATE tbl_datewisecommonroiaccount SET sharestatus = 0 WHERE CAST(date AS DATE) = CAST(dbo.FUN_GETCURRENTDATE() AS DATE);
  END IF;
  IF (v_earnedpoint > 0 AND v_memberplid <> 0) THEN
  IF (v_earnedpoint <= (SELECT CAST(COALESCE(MAX(totalavailableamount), 0) AS DECIMAL(10, 2)) AS totalavailableamount FROM tbl_membertaskincome WHERE plid = v_memberplid)) THEN
  SELECT 0 INTO v_regno;
  SELECT regno INTO v_regno FROM member_master WHERE plid = v_memberplid;
  SELECT 0.00, 0.00, 0.00 INTO v_amount, v_netamount, v_currentincome;
  SELECT 0.00, 0.00 INTO v_tds_per, v_tds;
  SELECT 0.00, 0.00 INTO v_admincharge_per, v_admincharge;
  SELECT ((v_earnedpoint * 1)) INTO v_amount;
  SELECT COALESCE(v_amount * v_tds_per / 100, 0) INTO v_tds;
  SELECT COALESCE(v_amount * v_admincharge_per / 100, 0) INTO v_admincharge;
  SELECT v_amount - v_tds - v_admincharge INTO v_netamount;
  UPDATE member_performance SET redeemedpoints = (redeemedpoints + COALESCE(v_netamount, 0)) WHERE regno = v_regno;
  SELECT currentincome INTO v_currentincome FROM member_performance WHERE regno = v_regno;
  INSERT INTO money_statements (regno, processdate, crdrtype, cr_amount, dr_amount, remarks, type, typeid, status, traceno, pmoid, balance, old_bal) VALUES (v_regno, dbo.FUN_GETCURRENTDATE(), 'CR', v_amount, 0, 'Redeem Earned Points', 'Redeem Earned Points', 0, 1, '', 0, COALESCE(v_currentincome, 0), COALESCE(v_currentincome, 0));
  UPDATE tbl_membertaskincome SET totalwithdrawlamount = (totalwithdrawlamount + v_earnedpoint), totalavailableamount = (totalavailableamount - v_earnedpoint) WHERE plid = v_memberplid;
  END IF;
  END IF;
  IF (v_plid > 0) THEN
  SELECT 0 INTO v_stroutputresult;
  SELECT v_intresultoutput INTO v_stroutputresult FROM dbo.usp_emailsmstrafficboosteraccountmanagement(v_mode => 3, v_plid => v_plid, v_tosmsoremail => '', v_intresultoutput => v_stroutputresult, v_tatbid => v_tatbid);
  IF (v_stroutputresult = 0) THEN
  v_strresult := 'Cancel';
  RETURN;
  END IF;
  END IF;
  UPDATE tbl_dailytasklimits SET totalshared = COALESCE(totalshared, 0) + 1, previousremainshare = previousremainshare - (CASE WHEN totalshared < totalavailableshareforday THEN 0 WHEN ((previousremainshare <= previouscarryforwardshare) AND (previousremainshare >= 1)) THEN 1 ELSE 0 END) WHERE plid = v_memberplid AND CAST(date AS DATE) = CAST(dbo.FUN_GETCURRENTDATE() AS DATE);
  END IF;
  -- SET option (removed)
  v_strresult := 'Ok';
  RETURN;
  EXCEPTION WHEN OTHERS THEN
  -- SET option (removed)
  v_strresult := 'Cancel';
  RETURN;
  END;
  END IF;
END;
$$;


--
-- Name: usp_closingdate(); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_closingdate() RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_lastdayofmonth int;
  v_currentdate date;
  v_date1 int;
  v_mm int;
  v_yy int;
  v_payid bigint;
  v_query text;
  v_a varchar(100);
  v_payfrom timestamp;
  v_payto timestamp;
  v_paydate timestamp;
BEGIN
  -- BEGIN TRAN (removed)
  SELECT COALESCE(MAX(payid), 0) INTO v_payid FROM payout;
  v_payid := COALESCE(v_payid, 0);
  v_payid := v_payid + 1;
  v_currentdate := CAST(GETUTCDATE() + INTERVAL '330 MI' AS DATE);
  v_mm := EXTRACT(MONTH FROM CAST(GETUTCDATE() + INTERVAL '330 MI' AS DATE));
  v_yy := EXTRACT(YEAR FROM CAST(GETUTCDATE() + INTERVAL '330 MI' AS DATE));
  v_a := CAST(v_yy AS VARCHAR(100)) || '-' || CAST((v_mm - 1) AS VARCHAR(100)) || '-' || '15';
  v_lastdayofmonth := EXTRACT(DAY FROM CAST(0 + (INTERVAL '1 MONTH' * (CAST(EXTRACT(year FROM AGE(CAST(CAST(v_a + INTERVAL '330 MI' AS TIMESTAMP) AS TIMESTAMP), CAST(CAST('1900-01-01' AS TIMESTAMP) AS TIMESTAMP))) * 12 + EXTRACT(month FROM AGE(CAST(CAST(v_a + INTERVAL '330 MI' AS TIMESTAMP) AS TIMESTAMP), CAST(CAST('1900-01-01' AS TIMESTAMP) AS TIMESTAMP))) AS BIGINT) + 1)) + INTERVAL '-1 SECOND' AS DATE));
  v_date1 := EXTRACT(DAY FROM v_currentdate);
  IF (25 = v_date1) THEN
  IF NOT EXISTS(SELECT * FROM payout WHERE CAST(payfrom AS DATE) = CAST(v_yy AS VARCHAR(20)) || '/' || CAST(v_mm AS VARCHAR(20)) || '/' || '01' AND CAST(payto AS DATE) = CAST(v_yy AS VARCHAR(20)) || '/' || CAST(v_mm AS VARCHAR(20)) || '/' || '15') THEN
  INSERT INTO payout (payid, payfrom, payto, paydate) VALUES (v_payid, CAST(v_yy AS VARCHAR(20)) || '/' || CAST(v_mm AS VARCHAR(20)) || '/' || '01', CAST(v_yy AS VARCHAR(20)) || '/' || CAST(v_mm AS VARCHAR(20)) || '/' || '15', CAST(v_yy AS VARCHAR(20)) || '/' || CAST(v_mm AS VARCHAR(20)) || '/' || '25
  
');
  END IF;
  ELSE
  IF (10 = v_date1) THEN
  IF NOT EXISTS(SELECT * FROM payout WHERE CAST(payfrom AS DATE) = CAST(v_yy AS VARCHAR(20)) || '/' || CAST((v_mm - 1) AS VARCHAR(20)) || '/' || '16' AND CAST(payto AS DATE) = CAST(v_yy AS VARCHAR(20)) || '/' || CAST((v_mm - 1) AS VARCHAR(20)) || '/' || CAST(v_lastdayofmonth AS VARCHAR(20))) THEN
  v_mm := v_mm - 1;
  v_payfrom := CAST(v_yy AS VARCHAR(20)) || '/' || CAST((v_mm) AS VARCHAR(20)) || '/' || '16';
  v_payto := CAST(v_yy AS VARCHAR(20)) || '/' || CAST((v_mm) AS VARCHAR(20)) || '/' || CAST(v_lastdayofmonth AS VARCHAR(20));
  v_paydate := CAST(v_yy AS VARCHAR(20)) || '/' || CAST((v_mm + 1) AS VARCHAR(20)) || '/' || CAST('10' AS VARCHAR(20));
  INSERT INTO payout (payid, payfrom, payto, paydate) VALUES (v_payid, v_payfrom, v_payto, v_paydate);
  END IF;
  END IF;
  END IF;
  -- COMMIT (removed)
END;
$$;


--
-- Name: usp_clubedreport(integer, integer, integer, character varying, character varying, character varying, character varying, integer, character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_clubedreport(v_mode integer DEFAULT 0, v_startrowindex integer DEFAULT 1, v_maxrows integer DEFAULT 100, v_searchfield character varying DEFAULT ''::character varying, v_searchvalue character varying DEFAULT ''::character varying, v_fromdate character varying DEFAULT ''::character varying, v_todate character varying DEFAULT ''::character varying, v_totalcount integer DEFAULT 0, v_requestid character varying DEFAULT ''::character varying) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_minindex INT;
  v_maxindex INT;
  v_query text;
BEGIN
  v_minindex := (v_startrowindex - 1) * v_maxrows + 1;
  v_maxindex := v_startrowindex * v_maxrows;
  IF (v_mode = 0) THEN
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp (ROWNUMBER BIGINT GENERATED BY DEFAULT AS IDENTITY, 
	ACCOUNTHOLDERNAME VARCHAR(200),         
	IFSCCODE VARCHAR(100),	
	AMOUNT DECIMAL(18,2),	
	GROUPNAME VARCHAR(100),	
	STATUS VARCHAR(100)) ON COMMIT DROP;
  v_query := 'INSERT INTO #TEMP SELECT BAM.ACCOUNTHOLDERNAME,BAM.IFSCCODE,MWD.WITHDRAWAMOUNT,MWD.CLUBGROUPNAME,MWD.STATUS 
FROM TBL_MERCHANT_WITHDRAWALS MWD 
LEFT JOIN BANK_ACCOUNTS_MERCHANT BAM ON  MWD.PLID=BAM.PLID 
WHERE  BAM.ACTIVE=1 AND BAM.ISAPROVE=1 and  CLUBGROUPNAME<>'''' ';
  IF (v_searchfield <> '') THEN
  v_query := v_query || ' AND MWD.CLUBGROUPNAME= ''' || v_searchfield || ''' ';
  END IF;
  v_query := v_query || ' ORDER BY TMWDID DESC ';
  EXECUTE v_query;
  RETURN QUERY SELECT * FROM tmp_temp WHERE rownumber BETWEEN v_minindex AND v_maxindex;
  SELECT COUNT(rownumber) INTO v_totalcount FROM tmp_temp;
  DROP TABLE IF EXISTS tmp_temp;
  -- SET option (removed)
  END IF;
END;
$$;


