  v_query := 'INSERT INTO #TEMP SELECT BAM.ACCOUNTHOLDERNAME,BAM.IFSCCODE,MWD.WITHDRAWALAMOUNT,MWD.CLUBGROUPNAME,MWD.STATUS 
FROM TBL_CUSTOMER_TRANSFERTOBANK MWD 
LEFT JOIN TBL_CUSTOMER_BANK_ACCOUNTS BAM ON  MWD.clid=BAM.clid 
WHERE  BAM.ACTIVE=1 AND CLUBGROUPNAME<>'''' ';
  IF (v_searchfield <> '') THEN
  v_query := v_query || ' AND MWD.CLUBGROUPNAME= ''' || v_searchfield || ''' ';
  END IF;
  v_query := v_query || ' ORDER BY TCTTB DESC ';
  EXECUTE v_query;
  RETURN QUERY SELECT * FROM tmp_temp WHERE rownumber BETWEEN v_minindex AND v_maxindex;
  SELECT COUNT(rownumber) INTO v_totalcount FROM tmp_temp;
  DROP TABLE IF EXISTS tmp_temp;
  -- SET option (removed)
