--
-- Name: usp_clubedreport_reseller(integer, integer, integer, character varying, character varying, character varying, character varying, integer, character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_clubedreport_reseller(v_mode integer DEFAULT 0, v_startrowindex integer DEFAULT 1, v_maxrows integer DEFAULT 100, v_searchfield character varying DEFAULT ''::character varying, v_searchvalue character varying DEFAULT ''::character varying, v_fromdate character varying DEFAULT ''::character varying, v_todate character varying DEFAULT ''::character varying, v_totalcount integer DEFAULT 0, v_requestid character varying DEFAULT ''::character varying) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_minindex INT;
  v_maxindex INT;
  v_query text;
  v_tempdid text;
  v_index INT;
  v_slice text;
  v_totalpayable DECIMAL(18,2);
BEGIN
  v_query := '';
  v_tempdid := '';
  v_index := 1;
  v_slice := '';
  v_totalpayable := 0;
  v_minindex := (v_startrowindex - 1) * v_maxrows + 1;
  v_maxindex := v_startrowindex * v_maxrows;
  IF (v_mode = 0) THEN
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp (ROWNUMBER BIGINT GENERATED BY DEFAULT AS IDENTITY, 
	DID INT,
	ACCOUNTHOLDERNAME VARCHAR(200),         
	IFSCCODE VARCHAR(100),	
	AMOUNT DECIMAL(18,2),	
	GROUPNAME VARCHAR(100),	
	STATUS VARCHAR(100)) ON COMMIT DROP;
  v_query := 'INSERT INTO #TEMP SELECT DISTINCT RCW.DID,BAD.ACCOUNTHOLDERNAME,BAD.IFSCCODE,0,RCW.CLUBGROUPNAME,RCW.PAID_STATUS 
FROM TBL_RESELLER_COMMISSIONWALLETSTATEMENT RCW  
LEFT JOIN BANK_ACCOUNTS_DISTRIBUTOR BAD ON  RCW.DID=BAD.DID 
WHERE  BAD.ACTIVE=1 AND BAD.ISAPROVE=1 and  CLUBGROUPNAME<>''''  ';
  IF (v_searchfield <> '') THEN
  v_query := v_query || ' AND RCW.CLUBGROUPNAME= ''' || v_searchfield || ''' ';
  END IF;
  EXECUTE v_query;
  SELECT COALESCE(v_tempdid || ', ', '') || CAST(did AS VARCHAR) INTO v_tempdid FROM (SELECT DISTINCT did FROM tmp_temp) AS t;
  SELECT SUBSTRING(v_tempdid FROM 2 FOR LENGTH(CAST(v_tempdid AS TEXT))) INTO v_tempdid;
  v_index := 1;
  WHILE (v_index <> 0) LOOP
  SELECT POSITION(',' IN v_tempdid) INTO v_index;
  IF (v_index <> 0) THEN
  SELECT LEFT(CAST(v_tempdid AS TEXT), v_index - 1) INTO v_slice;
  ELSE
  SELECT v_tempdid INTO v_slice;
  END IF;
  v_totalpayable := 0;
  IF (v_slice <> '') THEN
  SELECT COALESCE(SUM(balance), 0) INTO v_totalpayable FROM tbl_reseller_commissionwalletstatement WHERE did = v_slice AND paid_status = 'Unpaid';
  UPDATE tmp_temp SET amount = v_totalpayable WHERE did = v_slice;
  END IF;
  SELECT RIGHT(CAST(v_tempdid AS TEXT), LENGTH(CAST(v_tempdid AS TEXT)) - v_index) INTO v_tempdid;
  IF LENGTH(CAST(v_tempdid AS TEXT)) = 0 THEN
  EXIT;
  END IF;
  END LOOP;
  RETURN QUERY SELECT * FROM tmp_temp WHERE rownumber BETWEEN v_minindex AND v_maxindex;
  SELECT COUNT(rownumber) INTO v_totalcount FROM tmp_temp;
  DROP TABLE IF EXISTS tmp_temp;
  -- SET option (removed)
  END IF;
END;
$$;


--
-- Name: usp_clubhistory(character varying, character varying, character varying, character varying, character varying, character varying, character varying, character varying, character varying, integer, integer, integer, character varying, numeric, numeric, character varying, integer, numeric, character varying, integer, numeric, numeric, numeric, numeric, character varying, character varying, character varying, character varying, character varying, character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_clubhistory(v_withdrawalfromdate character varying DEFAULT ''::character varying, v_withdrawaltodate character varying DEFAULT ''::character varying, v_loginid character varying DEFAULT ''::character varying, v_phone character varying DEFAULT ''::character varying, v_accountno character varying DEFAULT ''::character varying, v_ifsccode character varying DEFAULT ''::character varying, v_accountholdername character varying DEFAULT ''::character varying, v_bankname character varying DEFAULT ''::character varying, v_branchname character varying DEFAULT ''::character varying, v_startrowindex integer DEFAULT 1, v_maxrows integer DEFAULT 10000, v_mode integer DEFAULT 1, v_username character varying DEFAULT 'USER2'::character varying, v_totalwithdrawalpoints numeric DEFAULT 0, v_totalpayableamount numeric DEFAULT 0, v_status character varying DEFAULT ''::character varying, v_recordcount integer DEFAULT 0, v_sumwithdrawalamt numeric DEFAULT 0, v_userdownlinemember character varying DEFAULT ''::character varying, v_side integer DEFAULT 0, v_totaltds numeric DEFAULT 0, v_totaladminc numeric DEFAULT 0, v_sumwithdrawlpoints1 numeric DEFAULT 0, v_totalamt numeric DEFAULT 0, v_orderbydate character varying DEFAULT ''::character varying, v_processby character varying DEFAULT ''::character varying, v_processipaddress character varying DEFAULT ''::character varying, v_searchfield character varying DEFAULT ''::character varying, v_searchvalue character varying DEFAULT ''::character varying, v_select_bank character varying DEFAULT 'ICICI'::character varying) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_query text;
  v_maxregno text;
  v_query1 text;
  v_getcount INT;
  v_getwdid text;
  v_getplid BIGINT;
  v_getusername VARCHAR(100);
  v_totalrequest INT;
  v_totalamount DECIMAL(18,8);
  v_total_tansaction DECIMAL(18,8);
  v_getallcubeallwdid text;
  v_getseparatewdid text;
  v_getmaxchid INT;
  v_getaccountno VARCHAR(50);
  v_getaccountholdername VARCHAR(50);
  v_getbankname VARCHAR(50);
  v_getbranchname VARCHAR(50);
  v_getifsccode VARCHAR(50);
  v_getnetamount DECIMAL(18,8);
  v_getfilename VARCHAR(50);
  v_getclubgroup VARCHAR(50);
  v_getrandom1 VARCHAR(50);
  v_getrandom2 VARCHAR(50);
  v_getrandom3 VARCHAR(50);
  v_getmergrandom VARCHAR(50);
  v_getupdatestatus text;
  v_companyaccountnumber VARCHAR(50);
BEGIN
  -- SET option (removed)
  v_query := '';
  v_maxregno := '';
  v_query1 := '';
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp (USERNAME VARCHAR(150),
	  CLID INT,
	  GROSSAMOUNT DECIMAL(18,8),
	  ADMINCHARGE DECIMAL(18,8),
	  TDS DECIMAL(18,8),
	  NETAMOUNT DECIMAL(18,8),
	  ACCOUNTNO VARCHAR(50),
	  ACCOUNTHOLDERNAME VARCHAR(50),
	  BANKNAME VARCHAR(50),
	  BRANCHNAME VARCHAR(50),
	  IFSCCODE VARCHAR(50),
	  STATUS VARCHAR(50)) ON COMMIT DROP;
  v_query := 'INSERT INTO #TEMP Select (CL.FName +'' ''+ CL.LNAME) USERNAME,CL.CLID,(ISNULL(CTB.WITHDRAWALAMOUNT,0)) AS GROSSAMOUNT,
(CAST(CTB.ADMINCHARGES AS DECIMAL(18,8)))AS ADMINCHARGE,(CAST(CTB.TDS AS DECIMAL(18,8)))AS TDS,
(ISNULL(CTB.WITHDRAWALAMOUNT,0)) AS NETAMOUNT,
CBT.ACCOUNTNO,CBT.ACCOUNTHOLDERNAME,''' || v_select_bank || '''  AS BANKNAME,CBT.BRANCHNAME,ISNULL(CBT.IFSCCODE,''''),CTB.STATUS
from TBL_CUSTOMER_TRANSFERTOBANK CTB
INNER JOIN TBL_CUSTOMERLOGIN CL ON CL.CLID=CTB.CLID 
INNER JOIN TBL_CUSTOMER_BANK_ACCOUNTS CBT ON CTB.CLID=CBT.CLID	
where CTB.STATUS=0 and CTB.ISPAID=0 ';
  IF (v_withdrawalfromdate <> '' AND v_withdrawaltodate <> '') THEN
  v_query := v_query || ' AND CONVERT(VARCHAR(12),CTB.WITHDRAWALDATE,105) BETWEEN CONVERT(VARCHAR(12),''' || v_withdrawalfromdate || ''') AND CONVERT(VARCHAR(12),''' || v_withdrawaltodate || ''',105) ';
  ELSE
  IF (v_withdrawalfromdate <> '') THEN
  v_query := v_query || ' AND CONVERT(VARCHAR(12),CTB.WITHDRAWALDATE,105)= CONVERT(VARCHAR(12),''' || v_withdrawalfromdate || ''',105)';
  ELSE
  IF (v_withdrawaltodate <> '') THEN
  v_query := v_query || ' AND CONVERT(VARCHAR(12),CTB.WITHDRAWALDATE,105)= CONVERT(VARCHAR(12),''' || v_withdrawaltodate || ''',105) ';
  END IF;
  END IF;
  END IF;
  RAISE NOTICE '%', v_query;
  EXECUTE v_query;
  DROP TABLE IF EXISTS tmp_temp1;
  CREATE TEMP TABLE tmp_temp1 (ROWNUMBER BIGINT,
	  USERNAME VARCHAR(150),
	   CLID INT,
