  v_query1 := 'INSERT INTO #TEMP1 SELECT ROW_NUMBER()OVER(ORDER BY (SELECT(1))) AS ROWNUMBER,TM.USERNAME,TM.CLID,TM.ACCOUNTNO,
	TM.ACCOUNTHOLDERNAME,TM.BANKNAME,TM.BRANCHNAME,ISNULL(TM.IFSCCODE,'''') AS IFSCCODE,STATUS,
	(SELECT SUM(GROSSAMOUNT) FROM #TEMP WHERE USERNAME=TM.USERNAME) AS GROSSAMOUNT,
	(SELECT SUM(ADMINCHARGE) FROM #TEMP WHERE USERNAME=TM.USERNAME) AS ADMINCHARGE,
	(SELECT SUM(TDS) FROM #TEMP WHERE USERNAME=TM.USERNAME) AS TDS,
	(SELECT SUM(NETAMOUNT) FROM #TEMP WHERE USERNAME=TM.USERNAME) AS NETAMOUNT   FROM #TEMP TM
	 GROUP BY TM.USERNAME,TM.CLID,TM.ACCOUNTNO,TM.ACCOUNTHOLDERNAME,TM.BANKNAME,TM.BRANCHNAME,ISNULL(TM.IFSCCODE,''''),TM.STATUS ';
  EXECUTE v_query1;
