  v_totalrequest := v_getcount;
  SELECT COUNT(1) INTO v_getcount FROM tmp_temp1;
  WHILE (v_getcount > 0) LOOP
  SELECT username, accountno, accountholdername, bankname, branchname, ifsccode, netamount, clid INTO v_getusername, v_getaccountno, v_getaccountholdername, v_getbankname, v_getbranchname, v_getifsccode, v_getnetamount, v_getplid FROM tmp_temp1 WHERE rownumber = v_getcount;
  SELECT COALESCE(v_getseparatewdid || ',', '') || CAST(tcttb AS VARCHAR) INTO v_getseparatewdid FROM tbl_customer_transfertobank WHERE clid = v_getplid AND status = 0 LIMIT 10000;
  INSERT INTO tbl_customer_downloadclubdata VALUES (v_getmaxchid, v_getaccountholdername, v_getifsccode, v_getaccountno, v_getnetamount, '0', '', '', '', v_getseparatewdid);
  v_getallcubeallwdid := v_getallcubeallwdid || v_getseparatewdid;
  v_getseparatewdid := '';
  v_getcount := v_getcount - 1;
  END LOOP;
  v_getfilename := '';
  v_getclubgroup := '';
  v_getrandom1 := '';
  v_getrandom2 := '';
  v_getrandom3 := '';
  v_getmergrandom := '';
  SELECT CAST(REPLACE(RANDOM(), '.', '') AS VARCHAR(50)) INTO v_getrandom1;
  SELECT CAST(REPLACE(RANDOM(), '.', '') AS VARCHAR(50)) INTO v_getrandom2;
  SELECT CAST(REPLACE(RANDOM(), '.', '') AS VARCHAR(50)) INTO v_getrandom3;
