  v_getfilename := v_getmergrandom;
  v_getclubgroup := v_getrandom1 || v_getrandom3 || v_getrandom2;
  INSERT INTO tbl_customer_clubhistory VALUES (v_getfilename, dbo.FUN_GETCURRENTDATE(), v_getclubgroup, v_getbankname, v_totalrequest, v_totalamount, v_total_tansaction, '', '', 0, '', v_getallcubeallwdid);
  v_getupdatestatus := '';
  v_getupdatestatus := 'UPDATE TBL_CUSTOMER_TRANSFERTOBANK SET STATUS=3 WHERE TCTTB IN  (SELECT * FROM SPLITSTRING(''' || v_getallcubeallwdid || ''','',''))';
