  v_recordcount := v_getcount;
  v_totalpayableamount := 0;
  v_totalwithdrawalpoints := 0;
  v_companyaccountnumber := '';
  SELECT COALESCE(accountno, '') INTO v_companyaccountnumber FROM tbl_admin_bankdetails WHERE status = 1 AND active = 1;
  RETURN QUERY SELECT v_getfilename AS filename, v_companyaccountnumber AS draccountno, * FROM tmp_temp1 ORDER BY rownumber ASC NULLS FIRST;
  DROP TABLE IF EXISTS tmp_temp;
  DROP TABLE IF EXISTS tmp_temp1;
  -- SET option (removed)
END;
$$;


