CREATE FUNCTION dbo.usp_clubhistory_reseller(v_withdrawalfromdate character varying DEFAULT ''::character varying, v_withdrawaltodate character varying DEFAULT ''::character varying, v_loginid character varying DEFAULT ''::character varying, v_phone character varying DEFAULT ''::character varying, v_accountno character varying DEFAULT ''::character varying, v_ifsccode character varying DEFAULT ''::character varying, v_accountholdername character varying DEFAULT ''::character varying, v_bankname character varying DEFAULT ''::character varying, v_branchname character varying DEFAULT ''::character varying, v_startrowindex integer DEFAULT 1, v_maxrows integer DEFAULT 10000, v_mode integer DEFAULT 1, v_username character varying DEFAULT ''::character varying, v_totalwithdrawalpoints numeric DEFAULT 0, v_totalpayableamount numeric DEFAULT 0, v_status character varying DEFAULT ''::character varying, v_recordcount integer DEFAULT 0, v_sumwithdrawalamt numeric DEFAULT 0, v_userdownlinemember character varying DEFAULT ''::character varying, v_side integer DEFAULT 0, v_totaltds numeric DEFAULT 0, v_totaladminc numeric DEFAULT 0, v_sumwithdrawlpoints1 numeric DEFAULT 0, v_totalamt numeric DEFAULT 0, v_orderbydate character varying DEFAULT ''::character varying, v_processby character varying DEFAULT ''::character varying, v_processipaddress character varying DEFAULT ''::character varying, v_searchfield character varying DEFAULT ''::character varying, v_searchvalue character varying DEFAULT ''::character varying, v_select_bank character varying DEFAULT 'ICICIC'::character varying) RETURNS SETOF record
