	  ADMINCHARGE DECIMAL(18,8),
	  TDS DECIMAL(18,8),
	  NETAMOUNT DECIMAL(18,8),
	  ACCOUNTNO VARCHAR(50),
	  ACCOUNTHOLDERNAME VARCHAR(50),
	  BANKNAME VARCHAR(50),
	  BRANCHNAME VARCHAR(50),
	  IFSCCODE VARCHAR(50),
	  STATUS VARCHAR(50)) ON COMMIT DROP;
  v_query := 'INSERT INTO #TEMP SELECT DISTINCT (CL.FNAME +'' ''+ CL.LNAME) USERNAME,CL.DID,(ISNULL(CTB.AMOUNT,0)) AS GROSSAMOUNT,
0 AS ADMINCHARGE,0 AS TDS,(ISNULL(CTB.AMOUNT,0)) AS NETAMOUNT,
CBT.ACCOUNTNO,CBT.ACCOUNTHOLDERNAME,''' || v_select_bank || '''  AS BANKNAME,CBT.BRANCHNAME,ISNULL(CBT.IFSCCODE,''''),CTB.PAIDSTATUS
FROM TBL_RESELLER_TRANSFERTOBANK_REQUEST CTB
