  SELECT COALESCE(v_getseparatewdid || ',', '') || CAST(trtbwid AS VARCHAR) INTO v_getseparatewdid FROM tbl_reseller_transfertobank_request WHERE did = v_getplid AND paidstatus = 0 LIMIT 10000;
  INSERT INTO tbl_reseller_downloadclubdata VALUES (v_getmaxchid, v_getaccountholdername, v_getifsccode, v_getaccountno, v_getnetamount, '0', '', '', '', v_getseparatewdid);
