BEGIN
  -- BEGIN TRAN (removed)
  RETURN QUERY SELECT ROW_NUMBER() OVER (ORDER BY tvrcsid NULLS FIRST) AS rownumber, tvrcsid, trcs.operatorname, commission, surcharge, (CASE WHEN trcs.active = 1 THEN 'ACTIVE' ELSE 'DEACTIVE' END) AS active, (CASE WHEN dpcs.updateddate = NULL THEN REPLACE(CAST(TO_CHAR(trcs.createdate, 'DD TMMon YYYY') AS VARCHAR(11)), ' ', '-') || ' ' || STUFF(RIGHT(CAST(CAST(TO_CHAR(CURRENT_TIMESTAMP, 'TMMon DD YYYY FMHH12:MI%p') AS VARCHAR(30)) AS TEXT), 7), 6, 0, ' ') ELSE REPLACE(CAST(TO_CHAR(dpcs.updateddate, 'DD TMMon YYYY') AS VARCHAR(11)), ' ', '-') || ' ' || STUFF(RIGHT(CAST(CAST(TO_CHAR(CURRENT_TIMESTAMP, 'TMMon DD YYYY FMHH12:MI%p') AS VARCHAR(30)) AS TEXT), 7), 6, 0, ' ') END) AS createdate, COALESCE(dpcs.package1commission, 0) AS package1commission, COALESCE(dpcs.package2commission, 0) AS package2commission, COALESCE(dpcs.package3commission, 0) AS package3commission, COALESCE(dpcs.package4commission, 0) AS package4commission, COALESCE(dpcs.adminsurcharge, 0) AS adminsurchargepack1, COALESCE(dpcs.addsurcharepackage2, 0) AS adminsurchargepack2, COALESCE(dpcs.addsurcharepackage3, 0) AS adminsurchargepack3, COALESCE(dpcs.addsurcharepackage4, 0) AS adminsurchargepack4, COALESCE(dpcs.actualpercentagepack1, 0) AS actualpercentagepack1, COALESCE(dpcs.actualpercentagepack2, 0) AS actualpercentagepack2, COALESCE(dpcs.actualpercentagepack3, 0) AS actualpercentagepack3, COALESCE(dpcs.actualpercentagepack4, 0) AS actualpercentagepack4, COALESCE(tv.vendorcode, 'N/A') AS vendorcode FROM tbl_vendor_recharge_commission_structure AS trcs LEFT JOIN tbl_default_package_commission_settings AS dpcs ON trcs.operatorname = dpcs.operatorname LEFT JOIN tbl_vendors AS tv ON trcs.tvid = tv.tvid WHERE trcs.servicename = v_operatorname AND trcs.active = 1;
  -- SET option (removed)
  -- COMMIT (removed)
END;
$$;


--
-- Name: usp_commission_productwise(character varying, integer, integer, integer, integer, character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_commission_productwise(v_did character varying DEFAULT 0, v_recordcount integer DEFAULT 0, v_intresult integer DEFAULT 0, v_startrowindex integer DEFAULT 1, v_maxrows integer DEFAULT 1000, v_productname character varying DEFAULT ''::character varying) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_category text;
  v_subcategory text;
  v_query text;
  v_minindex INT;
  v_maxindex INT;
BEGIN
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp (ROWNUMBER BIGINT,
	ProductTitle varchar(500),
	MPRID BIGINT,
	newbv DECIMAL(10,2),
	newcashback DECIMAL(10,2),
	ModifyDate varchar(50)) ON COMMIT DROP;
  v_category := '';
  v_subcategory := '';
  v_query := '';
  v_minindex := (v_startrowindex - 1) * v_maxrows + 1;
  v_maxindex := v_startrowindex * v_maxrows;
  v_query := 'INSERT INTO #TEMP SELECT ROW_NUMBER() over (order by IM.MPRID desc) as ROWNUMBER,ISNULL(IM.ProductTitle,'''') AS ProductTitle,isnull(IM.MPRID,0) as MPRID 
	,(case when tcs.modify_date=''1900-01-01 00:00:00.000''  THEN  isnull(sm.bv,0) else isnull(tcs.bv,0)End),
	(case when tcs.modify_date=''1900-01-01 00:00:00.000''  THEN  isnull(sm.Cashback_Per,0) else isnull(tcs.Cashback_Per,0)End),
	 (CASE  WHEN tcs.modify_date=''1900-01-01 00:00:00.000'' THEN ''N.A'' ELSE ISNULL(tcs.modify_date,'''') End) FROM  IMS_MasterProduct IM
     left join IMS_SubProduct sm on im.MPRID=sm.MPRID
	  left join Tbl_DISTRIBUTOR_Comm_ProductWise tcs on tcs.SPRID=sm.SPRID  and tcs.DID = ' || v_did || ' where 1=1';
  IF (v_productname <> '') THEN
  v_productname := REPLACE(v_productname, '''', '''''');
  v_query := v_query || ' and IM.ProductTitle =''' || v_productname || '''';
  END IF;
  EXECUTE v_query;
  RETURN QUERY SELECT * FROM tmp_temp WHERE rownumber BETWEEN v_minindex AND v_maxindex;
  SELECT COUNT(1) INTO v_recordcount FROM tmp_temp;
  DROP TABLE IF EXISTS tmp_temp;
END;
$$;


--
-- Name: usp_compaindetail(integer, integer, character varying, boolean, character varying, character varying, date, date, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_compaindetail(v_startrowindex integer, v_maxrows integer, v_orderbyfield character varying, v_asc boolean, v_searchfield character varying, v_searchvalue character varying, v_todate date DEFAULT NULL::date, v_fromdate date DEFAULT NULL::date, v_mode integer DEFAULT NULL::integer) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_recordcount int;
  v_regno bigint;
BEGIN
  -- SET option (removed)
  DROP TABLE IF EXISTS tmp_temp42;
  CREATE TEMP TABLE tmp_temp42 ON COMMIT DROP AS SELECT ROW_NUMBER() OVER (ORDER BY smc.smcid DESC NULLS LAST) AS rownumber, smc.smcid, smc.campainname, sm.loginid, smc.framesize, smc.budjetperday, smc.adtype, smc.campaincreatedate, smc.campainapprovedate, smc.keywordid, cty.countryname, smc.ctid, (CASE WHEN smc.campactive = 1 THEN 'active' ELSE 'Deactive' END) AS active FROM tbl_sponsor_master_campain AS smc JOIN tbl_sponsor_master AS sm ON smc.smid = sm.smid INNER JOIN country AS cty ON smc.cid = cty.cid;
  SELECT COUNT(*) INTO v_recordcount FROM tmp_temp42;
