  IF (v_todate <> '' AND v_fromdate <> '') THEN
  RETURN QUERY SELECT * FROM tmp_temp42 WHERE campaincreatedate BETWEEN v_todate AND v_fromdate;
  END IF;
  IF (v_searchfield = '') THEN
  RETURN QUERY SELECT * FROM tmp_temp42 WHERE rownumber BETWEEN v_startrowindex AND v_maxrows;
  END IF;
  DROP TABLE IF EXISTS tmp_temp42;
  -- SET option (removed)
END;
$$;


--
-- Name: usp_contactpasswordchange(bigint, character varying, character varying, character varying, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_contactpasswordchange(v_plid bigint, v_oldpass character varying, v_newpass character varying, v_confpass character varying, INOUT v_intresult integer) RETURNS integer
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_reg BIGINT;
  v_err INT;
BEGIN
  v_reg := 0;
  IF EXISTS(SELECT clid FROM tbl_customerlogin WHERE clid = v_plid) THEN
  UPDATE tbl_customerlogin SET password = v_newpass WHERE clid = v_plid;
  IF (v_reg > 0) THEN
  v_intresult := 3;
  RETURN;
  END IF;
  v_intresult := 1;
  ELSE
  v_intresult := 2;
  END IF;
  SELECT 0 INTO v_err;
  IF (v_err <> 0) THEN
  v_intresult := 4;
  END IF;
END;
$$;


