-- Name: usp_count_product(character varying, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_count_product(v_merchant character varying DEFAULT ''::character varying, v_data integer DEFAULT 0) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_query text;
BEGIN
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp (row int GENERATED BY DEFAULT AS IDENTITY,
Producttitle text,
Countdata int) ON COMMIT DROP;
  v_query := 'insert into #temp select ProductTitle, Count(ProductTitle) 
from IMS_MASTERPRODUCT  PM LEFT JOIN  IMS_SUBPRODUCT SM ON PM.MPRID=SM.MPRID 
LEFT JOIN PORTAL_login PL ON PL.PLID= PM.BranchId where  SM.ISVERIFIED=1 ';
  IF (v_merchant <> '') THEN
  v_query := v_query || ' AND PL.LOGINID= ''' || v_merchant || ''' ';
  END IF;
  v_query := v_query || ' Group By ProductTitle';
  EXECUTE v_query;
  SELECT COUNT(row) INTO v_data FROM tmp_temp;
  RETURN QUERY SELECT v_data;
  DROP TABLE IF EXISTS tmp_temp;
END;
$$;


--
-- Name: usp_country_wise_default_kewyword_price(character varying, character varying, integer, character varying, character varying, character varying, character varying, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_country_wise_default_kewyword_price(v_type character varying DEFAULT ''::character varying, v_mode character varying DEFAULT ''::character varying, v_cid integer DEFAULT 0, v_keyword_default_price character varying DEFAULT ''::character varying, v_keyword_default_min_price character varying DEFAULT ''::character varying, v_category_default_price character varying DEFAULT ''::character varying, v_category_default_min_price character varying DEFAULT ''::character varying, v_intresult integer DEFAULT 0) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
BEGIN
  v_intresult := 0;
  IF (v_type = 'keyword') THEN
  IF (v_mode = 'pageload') THEN
  RETURN QUERY SELECT ROW_NUMBER() OVER (ORDER BY c.countryname ASC NULLS FIRST) AS number, cpp.cid, c.countryname, c.currencycode, COALESCE(cpp.keyword_default_min_price, 0.00) AS keyword_default_min_price, (COALESCE(cpp.keyword_default_price, 0.00)) AS keyword_default_price FROM tbl_countrywise_package_price AS cpp INNER JOIN country AS c ON cpp.cid = c.cid;
  END IF;
  IF (v_mode = 'update') THEN
  UPDATE tbl_countrywise_package_price SET keyword_default_min_price = v_keyword_default_min_price, keyword_default_price = v_keyword_default_price WHERE cid = v_cid;
  v_intresult := 1;
  END IF;
  END IF;
  IF (v_type = 'category') THEN
  IF (v_mode = 'pageload') THEN
  RETURN QUERY SELECT ROW_NUMBER() OVER (ORDER BY c.countryname ASC NULLS FIRST) AS number, cpp.cid, c.countryname, c.currencycode, (COALESCE(cpp.category_default_min_price, 0.00)) AS category_default_min_price, (COALESCE(cpp.category_default_price, 0.00)) AS category_default_price FROM tbl_countrywise_package_price AS cpp INNER JOIN country AS c ON cpp.cid = c.cid;
  END IF;
  IF (v_mode = 'update') THEN
  UPDATE tbl_countrywise_package_price SET category_default_min_price = v_category_default_min_price, category_default_price = v_category_default_price WHERE cid = v_cid;
  v_intresult := 1;
  END IF;
  END IF;
END;
$$;


