CREATE FUNCTION dbo.usp_countrywithcurrency(v_countryname character varying, v_currencyname character varying, v_currencycode character varying, v_currencysymbol character varying, v_cid integer, v_flag bytea, v_valueinpound integer DEFAULT 0, INOUT v_intresult integer DEFAULT NULL::integer) RETURNS integer
    LANGUAGE plpgsql
    AS $$
BEGIN
  -- BEGIN TRAN (removed)
  IF NOT EXISTS(SELECT cactive FROM country WHERE cid = v_cid) THEN
  INSERT INTO country (countryname, cactive, flag, currencyname, currencysymbol, currencycode) VALUES (v_countryname, 1, v_flag, v_currencyname, v_currencysymbol, v_currencycode);
  ELSE
  UPDATE country SET flag = v_flag WHERE cid = v_cid;
  END IF;
  IF (0 <> 0) THEN
  -- COMMIT (removed)
  v_intresult := 0;
  RETURN;
  END IF;
  v_intresult := 1;
  -- COMMIT (removed)
END;
$$;


--
-- Name: usp_coupon_list(character varying, character varying, integer, integer, bigint); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_coupon_list(v_fromdate character varying DEFAULT ''::character varying, v_todate character varying DEFAULT ''::character varying, v_pageno integer DEFAULT 1, v_pagesize integer DEFAULT 30, v_plid bigint DEFAULT NULL::bigint) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_minindex int;
  v_maxindex int;
  v_recordcount int;
  v_amount numeric(19,4);
  v_currencysymbol varchar(20);
  v_totalamount numeric(19,4);
  v_sqlquery text;
BEGIN
  -- SET option (removed)
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp (rowNumber bigint,
cpid bigint,
coupon_number varchar(50),
amount numeric(19,4),
status varchar(15),
currencysymbol varchar(10),
generatedate  varchar(25),
remark text) ON COMMIT DROP;
  v_minindex := 0;
  v_maxindex := 0;
  v_sqlquery := '';
  v_minindex := ((v_pageno - 1) * v_pagesize) + 1;
  v_maxindex := (v_pageno * v_pagesize);
  v_sqlquery := 'insert into #temp  select ROW_NUMBER() over(order by generatedate  desc) as rownumber,cpid,coupon_number, amount, 
            (case when status=1 then ''Unused''  when status=0 then ''Used''  when status=2 then ''Deleted'' end) as status ,currencysymbol, generatedate, remark  from coupon_master where 
			plid=' || CAST(v_plid AS VARCHAR(20));
  IF (v_fromdate <> '') THEN
  v_sqlquery := v_sqlquery || ' and convert(date, generatedate,103) = convert(date,''' || v_fromdate || ''',103) ';
  END IF;
  IF (v_todate <> '') THEN
  v_sqlquery := v_sqlquery || ' and convert(date, generatedate,103)  =convert(date,''' || v_todate || ''',103) ';
  END IF;
  IF (v_fromdate <> '' AND v_todate <> '') THEN
  v_sqlquery := v_sqlquery || ' and convert(date, generatedate,103)  between  convert(date,''' || v_fromdate || ''',103)  and convert(date,''' || v_todate || ''',103)';
  END IF;
  EXECUTE v_sqlquery;
  SELECT COUNT(*) INTO v_recordcount FROM tmp_temp;
  RETURN QUERY SELECT *, v_recordcount AS recordcount FROM tmp_temp WHERE rownumber BETWEEN v_minindex AND v_maxindex;
  DROP TABLE IF EXISTS tmp_temp;
  -- SET option (removed)
END;
$$;


--
-- Name: usp_couponsearch(bigint); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_couponsearch(v_plid bigint) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_recordcount int;
  v_regno bigint;
BEGIN
  -- SET option (removed)
  DROP TABLE IF EXISTS tmp_temp89;
  CREATE TEMP TABLE tmp_temp89 ON COMMIT DROP AS SELECT ROW_NUMBER() OVER (ORDER BY cm.generatedate DESC NULLS LAST) AS rownumber, CAST(TO_CHAR(generatedate, 'DD-MM-YYYY') AS VARCHAR(30)) AS generatedate, amount, coupon_number, c.countryname AS countryname, cm.currencysymbol AS currencysymbol, cm.usedby AS usedby, (CASE status WHEN 1 THEN 'Active' WHEN 0 THEN 'Deactive/Used' END) AS status FROM coupon_master AS cm, country AS c WHERE c.cid = cm.cid AND cm.plid = v_plid;
  SELECT COUNT(*) INTO v_recordcount FROM tmp_temp89;
  RETURN QUERY SELECT * FROM tmp_temp89;
  DROP TABLE IF EXISTS tmp_temp89;
  -- SET option (removed)
END;
$$;


--
-- Name: usp_courier_master(integer, integer, character varying, character varying, character varying, character varying, character varying, character varying, character varying, character varying, character varying, integer, integer, character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_courier_master(v_cmid integer DEFAULT 0, v_carrier_id integer DEFAULT 0, v_carrier_name character varying DEFAULT ''::character varying, v_address character varying DEFAULT ''::character varying, v_contactno character varying DEFAULT ''::character varying, v_website_url character varying DEFAULT ''::character varying, v_track_url character varying DEFAULT ''::character varying, v_alt_contact character varying DEFAULT ''::character varying, v_logo character varying DEFAULT ''::character varying, v_email_id character varying DEFAULT ''::character varying, v_contact_person character varying DEFAULT ''::character varying, v_active integer DEFAULT 0, v_mode integer DEFAULT 1, v_strresult character varying DEFAULT NULL::character varying) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_maxid INT;
BEGIN
  -- BEGIN TRAN (removed)
  -- SET option (removed)
  IF (v_mode = 1) THEN
  v_maxid := 0;
  SELECT MAX(cmid) + 1 INTO v_maxid FROM tbl_couriermaster;
  IF EXISTS(SELECT cmid FROM tbl_couriermaster WHERE cmid = v_cmid) THEN
  UPDATE tbl_couriermaster SET carrier_name = v_carrier_name, address = v_address, contactno = v_contactno, website_url = v_website_url, track_url = v_track_url, alt_contact = v_alt_contact, logo = v_logo, email_id = v_email_id, contact_person = v_contact_person, active = v_active WHERE cmid = v_cmid;
  v_strresult := 'Update';
  ELSE
  INSERT INTO tbl_couriermaster (carrier_id, carrier_name, address, contactno, website_url, track_url, alt_contact, logo, email_id, contact_person, active, create_date) VALUES (v_maxid, v_carrier_name, v_address, v_contactno, v_website_url, v_track_url, v_alt_contact, v_logo, v_email_id, v_contact_person, v_active, dbo.FUN_GETCURRENTDATE());
  v_strresult := 'Add';
  END IF;
  END IF;
  IF (v_mode = 2) THEN
  DELETE FROM tbl_couriermaster WHERE cmid = v_cmid;
  v_strresult := 'SUCCESS';
  END IF;
  IF (v_mode = 3) THEN
  RETURN QUERY SELECT * FROM tbl_couriermaster;
  END IF;
  IF (0 <> 0) THEN
  v_strresult := 'Error';
  -- ROLLBACK (removed)
  RETURN;
  END IF;
  -- COMMIT (removed)
  -- SET option (removed)
END;
$$;


--
-- Name: usp_courier_order_report(integer, integer, character varying, character varying, character varying, character varying, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_courier_order_report(v_startrowindex integer DEFAULT 1, v_maxrows integer DEFAULT 100, v_fromdate character varying DEFAULT ''::character varying, v_todate character varying DEFAULT ''::character varying, v_requestid character varying DEFAULT ''::character varying, v_merchantname character varying DEFAULT ''::character varying, v_intresult integer DEFAULT 0) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_minindex INT;
  v_maxindex INT;
  v_query text;
  v_condition text;
  v_countquery text;
BEGIN
  v_query := '';
  v_condition := '';
  v_countquery := '';
  v_minindex := (v_startrowindex - 1) * v_maxrows + 1;
  v_maxindex := v_startrowindex * v_maxrows;
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp (ROWNUMBER INT GENERATED BY DEFAULT AS IDENTITY,
Name Varchar(100),
REQUESTID VARCHAR(100),
EXCELFILE VARCHAR(500),
TOTALUPLOADEDRECORDS INT,
TOTALERRORRECORDS INT,
ACTIVITYBYUSERID INT,
ACTIVITYDATE varchar(50),
STATUS INT) ON COMMIT DROP;
  v_query := 'INSERT INTO #TEMP select isnull(pl.COMPANYNAME,'''') as name,isnull(UCE.REQUESTID,'''') as REQUESTID,isnull(UCE.EXCELFILE,'''') as EXCELFILE,
isnull(UCE.TOTALUPLOADEDRECORDS,0) as TOTALUPLOADEDRECORDS ,
isnull(UCE.TOTALERRORRECORDS,0) as TOTALERRORRECORDS,isnull(UCE.ACTIVITYBYUSERID,0) as ACTIVITYBYUSERID,
ISNULL(ACTIVITYDATE,'''') AS ACTIVITYDATE,ISNULL(UCE.STATUS,0) AS STATUS 
FROM TBL_UPLOADED_COURIER_EXCELLOG UCE LEFT JOIN PORTAL_MASTER PL ON PL.PLID=UCE.PLID WHERE 1=1';
  IF (v_fromdate <> '' AND v_todate <> '') THEN
  v_query := v_query || '  AND CONVERT(varchar(50), ACTIVITYDATE,105)  >= CONVERT(varchar(50),''' || v_fromdate || ''',105)  
 AND CONVERT(varchar(50), ACTIVITYDATE,105) <= CONVERT(varchar(50),''' || v_todate || ''',105)';
  ELSE
  IF (v_fromdate <> '') THEN
  v_query := v_query || '  AND CONVERT(varchar(50), ACTIVITYDATE,105) between  CONVERT(varchar(50),''' || v_fromdate || ''',105) AND  CONVERT(varchar(50), DBO.FUN_GETCURRENTDATE(), 105)';
  ELSE
  IF (v_todate <> '') THEN
  v_query := v_query || '  AND CONVERT(varchar(50), ACTIVITYDATE,105) between CONVERT(varchar(50),''' || v_todate || ''',105) AND  CONVERT(varchar(50), DBO.FUN_GETCURRENTDATE(), 105)';
  END IF;
  END IF;
  END IF;
  IF (v_merchantname <> '') THEN
  v_query := v_query || ' AND (PL.COMPANYNAME)=''' || v_merchantname || '''';
  END IF;
  IF (v_requestid <> '') THEN
  v_query := v_query || ' AND UCE.REQUESTID=''' || v_requestid || '''';
  END IF;
  v_query := v_query || 'order by UCE.ACTIVITYDATE desc';
  EXECUTE v_query;
  RETURN QUERY SELECT * FROM tmp_temp WHERE rownumber BETWEEN v_minindex AND v_maxindex;
  SELECT COUNT(1) INTO v_intresult FROM tmp_temp;
END;
$$;


--
-- Name: usp_courier_services(integer, integer, integer, character varying, integer, character varying, integer, integer, integer, character varying, character varying, character varying, character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_courier_services(v_tcsid integer DEFAULT 0, v_mode integer DEFAULT 2, v_tlpid integer DEFAULT 0, v_couriername character varying DEFAULT ''::character varying, v_active integer DEFAULT 0, v_strresult character varying DEFAULT ''::character varying, v_totalcount integer DEFAULT 0, v_startrowindex integer DEFAULT 1, v_maxrows integer DEFAULT 10, v_searchfield character varying DEFAULT ''::character varying, v_searchvalue character varying DEFAULT ''::character varying, v_fromdate character varying DEFAULT ''::character varying, v_todate character varying DEFAULT ''::character varying) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_minindex int;
  v_maxindex int;
  v_query text;
BEGIN
  -- BEGIN TRAN (removed)
  v_minindex := (v_startrowindex - 1) * v_maxrows + 1;
  v_maxindex := v_startrowindex * v_maxrows;
  IF (v_mode = 1) THEN
  IF EXISTS(SELECT 1 FROM dbo.tbl_courierservices WHERE courierservice = v_couriername AND tcsid <> v_tcsid) THEN
  v_strresult := 'Courier Service Already Exist';
  RAISE NOTICE '%', v_strresult;
  -- COMMIT (removed)
  RETURN;
  END IF;
  IF NOT EXISTS(SELECT 1 FROM tbl_courierservices WHERE tcsid = v_tcsid) THEN
  RAISE NOTICE '%', 'a';
  INSERT INTO dbo.tbl_courierservices (tlpid, courierservice, createddate, active) VALUES (v_tlpid, v_couriername, CURRENT_TIMESTAMP, v_active);
  v_strresult := 'Inserted';
  ELSE
  UPDATE dbo.tbl_courierservices SET tlpid = v_tlpid, courierservice = v_couriername, createddate = CURRENT_TIMESTAMP, active = v_active WHERE tcsid = v_tcsid;
  v_strresult := 'Updated';
  END IF;
  END IF;
  IF (v_mode = 2) THEN
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp (ROWNUMBER BIGINT 
    ,name VARCHAR(500) 
	,COURIERSERVICE VARCHAR(500)
	,CREATEDDATE timestamp
	,ACTIVE INT) ON COMMIT DROP;
  v_query := 'INSERT INTO #TEMP SELECT tcs.TCSID,lp.name,tcs.COURIERSERVICE,tcs.CREATEDDATE,tcs.ACTIVE from dbo.TBL_COURIERSERVICES tcs left join TBL_LOGISTICPARTNERS lp on lp.tlpid=tcs.tlpid where 1=1';
  IF (v_searchfield = 'name') THEN
  v_query := v_query || ' AND lp.name LIKE ''%' || v_searchvalue || '%'' ';
  END IF;
  IF (v_searchfield = 'COURIERSERVICE') THEN
  v_query := v_query || 'AND tcs.COURIERSERVICE LIKE ''%' || v_searchvalue || '%''';
  END IF;
  IF ((v_fromdate <> '') AND (v_todate = '')) THEN
  v_query := v_query || ' AND CONVERT(DATE, tcs.CREATEDDATE, 105) BETWEEN  CONVERT(DATE, ''' || v_fromdate || ''', 105) AND  CONVERT(DATE, DBO.FUN_GETCURRENTDATE(), 105)';
  END IF;
  IF ((v_fromdate = '') AND (v_todate <> '')) THEN
  v_query := v_query || 'AND CONVERT(DATE, tcs.CREATEDDATE, 105) BETWEEN  CONVERT(DATE, ''' || v_todate || ''', 105) AND  CONVERT(DATE, DBO.FUN_GETCURRENTDATE(), 105)';
  END IF;
  IF ((v_fromdate <> '') AND (v_todate <> '')) THEN
  v_query := v_query || 'AND CONVERT(DATE, tcs.CREATEDDATE, 105) BETWEEN CONVERT(DATE, ''' || v_fromdate || ''', 105) AND  CONVERT(DATE, ''' || v_todate || ''', 105)';
  END IF;
  RAISE NOTICE '%', v_query;
  EXECUTE v_query;
  RETURN QUERY SELECT * FROM tmp_temp WHERE rownumber BETWEEN v_minindex AND v_maxindex ORDER BY rownumber ASC NULLS FIRST;
  SELECT COUNT(rownumber) INTO v_totalcount FROM tmp_temp;
  DROP TABLE IF EXISTS tmp_temp;
  -- SET option (removed)
  END IF;
  IF (v_mode = 3) THEN
  RETURN QUERY SELECT tlpid, courierservice, active FROM dbo.tbl_courierservices WHERE tcsid = v_tcsid;
  END IF;
  IF (0 <> 0) THEN
  v_strresult := 'Some Error Occoured !';
  -- ROLLBACK (removed)
  RETURN;
  END IF;
  -- COMMIT (removed)
END;
$$;


--
-- Name: usp_courierchallan(character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_courierchallan(v_invoiceno character varying DEFAULT 'EB/18-19/000001'::character varying) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
BEGIN
  RETURN QUERY SELECT DISTINCT dc.invoiceno, dc.orderid, dc.challanno, CAST(dc.challandate AS VARCHAR(100)) AS challandate, dc.docketno, inv.customername, inv.address, inv.city, CAST(inv.pincode AS VARCHAR(100)) AS pincode, inv.mobile, (COALESCE(lcp.name, '')) AS shippedby, pm.companyname, pm.pick_address, pm.pick_landmark, pm.pick_state, pm.pick_city, pm.pick_area, pm.pick_pincode, inv.paymode, tsb.subcatname, tmc.maincatname, pm.gstno FROM tbl_deliverychallan AS dc LEFT JOIN tbl_invoicedetailsmaster AS inv ON dc.invoiceno = inv.invoiceno LEFT JOIN tbl_logisticpartners AS lcp ON dc.tlpid = lcp.tlpid LEFT JOIN portal_master AS pm ON inv.plid = pm.plid LEFT JOIN ims_subproduct AS ims ON inv.product_code = ims.sprid LEFT JOIN ims_masterproduct AS imp ON ims.mprid = imp.mprid LEFT JOIN tbl_sub_category AS tsb ON imp.subcategoryid = tsb.subcatid LEFT JOIN tbl_main_category AS tmc ON imp.maincategoryid = tmc.maincatid WHERE dc.invoiceno = v_invoiceno;
END;
$$;


--
-- Name: usp_courierweekly_report(integer, integer, integer, character varying, character varying, character varying, character varying, integer, character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_courierweekly_report(v_mode integer DEFAULT 0, v_startrowindex integer DEFAULT 1, v_maxrows integer DEFAULT 100, v_searchfield character varying DEFAULT ''::character varying, v_searchvalue character varying DEFAULT ''::character varying, v_fromdate character varying DEFAULT ''::character varying, v_todate character varying DEFAULT ''::character varying, v_totalcount integer DEFAULT 0, v_requestid character varying DEFAULT ''::character varying) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_minindex INT;
  v_maxindex INT;
  v_query text;
BEGIN
  v_minindex := (v_startrowindex - 1) * v_maxrows + 1;
  v_maxindex := v_startrowindex * v_maxrows;
  IF (v_mode = 0) THEN
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp (ROWNUMBER INT GENERATED BY DEFAULT AS IDENTITY, 
	TUWID INT,       
	ACTIVITYBYUSERID BIGINT,         
	EXCELFILE text,	
	REQUESTID VARCHAR(500),	
	TOTALUPLOADRECORDS INT,	
	TOTALERRORRECORDS INT,			
    STATUS INT,				
    ACTIVITYDATE timestamp) ON COMMIT DROP;
  v_query := 'INSERT INTO #TEMP SELECT TUWID,ISNULL(ACTIVITYBYUSERID,0) AS ACTIVITYBYUSERID,ISNULL(EXCELFILE,'''') AS EXCELFILE,ISNULL(REQUESTID,'''') AS REQUESTID,
     ISNULL(TOTALUPLOADRECORDS,0) AS TOTALUPLOADRECORDS,ISNULL(TOTALERRORRECORDS,0) AS TOTALERRORRECORDS,STATUS,ACTIVITYDATE
	 FROM TBL_UPLOAD_WEEKLY_REPORT CWS   WHERE 1=1 ';
  IF ((v_fromdate <> '') AND (v_todate = '')) THEN
  v_query := v_query || ' AND CONVERT(DATE, ACTIVITYDATE, 105) BETWEEN  CONVERT(DATE, ''' || v_fromdate || ''', 105) AND  CONVERT(DATE, DBO.FUN_GETCURRENTDATE(), 105)';
  END IF;
  IF ((v_fromdate = '') AND (v_todate <> '')) THEN
  v_query := v_query || 'AND CONVERT(DATE, ACTIVITYDATE, 105) BETWEEN  CONVERT(DATE, ''' || v_todate || ''', 105) AND  CONVERT(DATE, DBO.FUN_GETCURRENTDATE(), 105)';
  END IF;
  IF ((v_fromdate <> '') AND (v_todate <> '')) THEN
  v_query := v_query || 'AND CONVERT(DATE, ACTIVITYDATE, 105) BETWEEN CONVERT(DATE, ''' || v_fromdate || ''', 105) AND  CONVERT(DATE, ''' || v_todate || ''', 105)';
  END IF;
  IF (v_searchfield <> '') THEN
  v_query := v_query || ' AND REQUESTID= ''' || v_searchfield || ''' ';
  END IF;
  v_query := v_query || ' Order by CONVERT(DATE, ACTIVITYDATE, 105) Desc ';
  EXECUTE v_query;
  RETURN QUERY SELECT * FROM tmp_temp WHERE rownumber BETWEEN v_minindex AND v_maxindex;
  SELECT COUNT(rownumber) INTO v_totalcount FROM tmp_temp;
  DROP TABLE IF EXISTS tmp_temp;
  -- SET option (removed)
  END IF;
  IF (v_mode = 1) THEN
  DROP TABLE IF EXISTS tmp_temp1;
  CREATE TEMP TABLE tmp_temp1 (ROWNUMBER INT GENERATED BY DEFAULT AS IDENTITY,        
	TCWRID INT,         
	DOCKETNO VARCHAR(500),	
	WEIGHT VARCHAR(500),	
    ACTIVE INT,				
    CREATEDDATE timestamp,
	REQUESTID VARCHAR(50),
	PICKUP_CHARGES DECIMAL(18,2),
	DELIVERYCHARHES DECIMAL(18,2),
	TAXCHARGES DECIMAL(18,2),
	TOTAL_AMOUNT DECIMAL(18,2),
	FUELCHARGE DECIMAL(18,2)) ON COMMIT DROP;
  v_query := 'INSERT INTO #TEMP1 SELECT TCWRID,ISNULL(DOCKETNO,'''') AS DOCKETNO,ISNULL(WEIGHT,'''') AS WEIGHT,
     ISNULL(ACTIVE,0) AS ACTIVE,CREATEDDATE,REQUESTID,PICKUP_CHARGES,DELIVERYCHARHES,TAXCHARGES,TOTAL_AMOUNT,FuelTax
	 FROM TBL_COURIERWEEKLYREPORTS CWS   WHERE 1=1 ';
  IF ((v_fromdate <> '') AND (v_todate = '')) THEN
  v_query := v_query || ' AND CONVERT(DATE, CREATEDDATE, 105) BETWEEN  CONVERT(DATE, ''' || v_fromdate || ''', 105) AND  CONVERT(DATE, DBO.FUN_GETCURRENTDATE(), 105)';
  END IF;
  IF ((v_fromdate = '') AND (v_todate <> '')) THEN
  v_query := v_query || 'AND CONVERT(DATE, CREATEDDATE, 105) BETWEEN  CONVERT(DATE, ''' || v_todate || ''', 105) AND  CONVERT(DATE, DBO.FUN_GETCURRENTDATE(), 105)';
  END IF;
  IF ((v_fromdate <> '') AND (v_todate <> '')) THEN
  v_query := v_query || 'AND CONVERT(DATE, CREATEDDATE, 105) BETWEEN CONVERT(DATE, ''' || v_fromdate || ''', 105) AND  CONVERT(DATE, ''' || v_todate || ''', 105)';
  END IF;
  IF (v_searchfield <> '') THEN
  v_query := v_query || ' AND DOCKETNO= ''' || v_searchfield || ''' ';
  END IF;
  IF (v_requestid <> '') THEN
  v_query := v_query || ' AND REQUESTID= ''' || v_requestid || ''' ';
  END IF;
  EXECUTE v_query;
  RETURN QUERY SELECT * FROM tmp_temp1 WHERE rownumber BETWEEN v_minindex AND v_maxindex;
  SELECT COUNT(rownumber) INTO v_totalcount FROM tmp_temp1;
  DROP TABLE IF EXISTS tmp_temp1;
  -- SET option (removed)
  END IF;
END;
$$;


--
-- Name: usp_create_customer_recharge_claims(integer, integer, character varying, text, character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_create_customer_recharge_claims(v_mode integer DEFAULT 0, v_clid integer DEFAULT 0, v_transactionid character varying DEFAULT ''::character varying, v_remarks text DEFAULT ''::text, INOUT v_strresult character varying DEFAULT ''::character varying) RETURNS character varying
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_mobileno VARCHAR(20);
  v_rechargertype VARCHAR(100);
BEGIN
  -- BEGIN TRAN (removed)
  -- SET option (removed)
  v_mobileno := '';
  v_rechargertype := '';
  IF (v_mode = 1) THEN
  IF NOT EXISTS(SELECT 1 FROM tbl_customer_postpaid_recharges WHERE transactionid = v_transactionid AND active = 1) THEN
  v_strresult := '1';
  -- COMMIT (removed)
  RETURN;
  END IF;
  IF EXISTS(SELECT 1 FROM tbl_customer_recharge_claims WHERE transid = v_transactionid AND isactive = 1) THEN
  v_strresult := '2';
  -- COMMIT (removed)
  RETURN;
  END IF;
  IF NOT EXISTS(SELECT 1 FROM tbl_customer_recharge_claims WHERE transid = v_transactionid AND isactive = 1) THEN
  IF EXISTS(SELECT 1 FROM tbl_customer_postpaid_recharges WHERE transactionid = v_transactionid AND active = 1) THEN
  SELECT mobileno, operatortype INTO v_mobileno, v_rechargertype FROM tbl_customer_postpaid_recharges WHERE transactionid = v_transactionid AND active = 1;
  INSERT INTO tbl_customer_recharge_claims (clid, transid, mobileno, remarks, recharge_type, isclamied, clamieddate, adminstatus, createddate, isactive) VALUES (v_clid, v_transactionid, v_mobileno, v_remarks, v_rechargertype, 1, dbo.FUN_GETCURRENTDATE(), 'PENDING', dbo.FUN_GETCURRENTDATE(), 1);
  v_strresult := 'OK';
  END IF;
  END IF;
  END IF;
  -- SET option (removed)
  IF (0 <> 0) THEN
  v_strresult := 'ERROR^SOME ERROR OCCURED';
  -- ROLLBACK (removed)
  RETURN;
  END IF;
  -- COMMIT (removed)
END;
$$;


--
-- Name: usp_create_new_pin(integer, character varying, character varying, character varying, numeric, numeric, numeric, numeric, numeric, numeric, numeric, integer, integer, text, integer, text, character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_create_new_pin(v_kid integer DEFAULT 0, v_mode character varying DEFAULT ''::character varying, v_kittype character varying DEFAULT ''::character varying, v_title character varying DEFAULT ''::character varying, v_amount numeric DEFAULT 0.00, v_dap numeric DEFAULT 0.00, v_pv numeric DEFAULT 0.00, v_bv numeric DEFAULT 0.00, v_distamount numeric DEFAULT 0.00, v_directincome numeric DEFAULT 0.00, v_storecommission numeric DEFAULT 0.00, v_roi integer DEFAULT 0, v_noofmonth integer DEFAULT 0, v_image text DEFAULT ''::text, v_status integer DEFAULT 0, v_allfeatureid text DEFAULT ''::text, INOUT v_strresult character varying DEFAULT ''::character varying) RETURNS character varying
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_newkid INT;
  v_prcode VARCHAR(100);
  v_maxprid INT;
  v_lower BIGINT;
  v_upper BIGINT;
  v_random BIGINT;
BEGIN
  v_strresult := 'SUCCESS';
  SELECT COALESCE(MAX(kid), 0) + 1 INTO v_newkid FROM kit_master;
  SELECT COALESCE(MAX(kid), 0) + 1 INTO v_maxprid FROM kit_master;
  v_lower := 1111;
  v_upper := 9999;
  SELECT ROUND(((v_upper - v_lower - 1) * RANDOM() + v_lower), 0) INTO v_random;
  v_prcode := 'PR' || CAST(v_random AS VARCHAR(20)) || CAST(v_maxprid AS VARCHAR(12));
  IF (v_mode = 'ADD') THEN
  IF (v_kittype = 'AGENCY PIN') THEN
  SELECT 'AG' || RIGHT(CAST('000' || CAST(v_newkid AS VARCHAR) AS TEXT), 4) INTO v_prcode;
  END IF;
  IF (v_kittype = 'JOINING PIN') THEN
  SELECT 'JN' || RIGHT(CAST('000' || CAST(v_newkid AS VARCHAR) AS TEXT), 4) INTO v_prcode;
  END IF;
  INSERT INTO kit_master (kid, pcode, title, type, amount, dap, pv, bv, distamount, vatinper, cmgamount, directincome, binaryincome, epin_commission, status, roi, noofmonth, image) VALUES (v_newkid, v_prcode, v_title, v_kittype, v_amount, v_dap, v_pv, v_bv, v_distamount, 0, 0, v_directincome, 0, v_storecommission, v_status, v_roi, v_noofmonth, v_image);
  v_kid := IDENT_CURRENT('KIT_MASTER');
  END IF;
  IF (v_mode = 'UPDATE') THEN
  UPDATE kit_master SET title = v_title, amount = v_amount, dap = v_dap, pv = v_pv, bv = v_bv, distamount = v_distamount, epin_commission = v_storecommission, directincome = v_directincome, image = (CASE WHEN v_image = '' THEN image ELSE v_image END), roi = v_roi, noofmonth = v_noofmonth, status = v_status WHERE kid = v_kid;
  v_strresult := 'UPDATE';
  END IF;
  IF (0 <> 0) THEN
  v_strresult := 'ERROR OCCURED !';
  ELSE
  PERFORM dbo.usp_managekitfeaturemaster(v_featureshortexplanation => '', v_featurebreifexplanation => '', v_kitid => v_kid, v_allfeatureid => v_allfeatureid, v_status => 1, v_mode => 2, v_addedbyuserid => 0, v_tfmid => 0, v_quantity => 0);
  END IF;
END;
$$;


--
-- Name: usp_create_new_reseller_wallettype(integer, character varying, numeric, integer, integer, character varying, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_create_new_reseller_wallettype(v_rwtid integer DEFAULT 0, v_walletname character varying DEFAULT ''::character varying, v_maxused numeric DEFAULT 0, v_isreturn integer DEFAULT 0, v_pmid integer DEFAULT 0, INOUT v_strresult character varying DEFAULT ''::character varying, v_did integer DEFAULT 0) RETURNS character varying
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_walletid INT;
BEGIN
  IF (v_rwtid > 0) THEN
  IF EXISTS(SELECT 1 FROM tbl_reseller_wallettype WHERE walletname = v_walletname AND rwtid <> v_rwtid AND pmid = v_pmid) THEN
  v_strresult := 'THIS WALLET NAME ALREADY ASIGNED.PLEASE FILL ANOTHER WALLETNAME.';
  ELSE
  UPDATE tbl_reseller_wallettype SET walletname = v_walletname, isreturn = v_isreturn, maxuseper = v_maxused WHERE rwtid = v_rwtid;
  v_strresult := 'Update';
  END IF;
  ELSE
  IF EXISTS(SELECT 1 FROM tbl_reseller_wallettype WHERE walletname = v_walletname AND rwtid <> v_rwtid AND pmid = v_pmid) THEN
  v_strresult := 'THIS WALLET NAME ALREADY ASIGNED.PLEASE FILL ANOTHER WALLETNAME.';
  ELSE
  v_walletid := 0;
  SELECT COALESCE(MAX(walletid), 0) INTO v_walletid FROM tbl_reseller_wallettype WHERE pmid = v_pmid;
  INSERT INTO tbl_reseller_wallettype (pmid, walletid, walletname, isreturn, maxuseper, status) VALUES (v_pmid, (v_walletid + 1), v_walletname, v_isreturn, v_maxused, 1);
  v_strresult := 'Add';
  END IF;
  END IF;
END;
$$;


--
-- Name: usp_createbilling(character varying, integer, character varying, character varying, character varying, character varying, character varying, integer, integer, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_createbilling(v_businessname character varying DEFAULT ''::character varying, v_slid integer DEFAULT 0, v_contactname character varying DEFAULT ''::character varying, v_phonenumber character varying DEFAULT ''::character varying, v_address character varying DEFAULT ''::character varying, v_city character varying DEFAULT ''::character varying, v_postalcode character varying DEFAULT ''::character varying, v_state integer DEFAULT 0, v_country integer DEFAULT 0, INOUT v_intresult integer DEFAULT NULL::integer) RETURNS integer
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_slid1 BIGINT;
  v_businessname1 VARCHAR(300);
  v_contactname1 VARCHAR(100);
  v_phonenumber1 VARCHAR(20);
  v_address1 VARCHAR(200);
  v_city1 VARCHAR(100);
  v_postalcode1 VARCHAR(20);
  v_state1 INT;
  v_country1 INT;
  v_billingstatus1 INT;
  v_date VARCHAR(100);
  v_recentbillinginformation INT;
BEGIN
  v_businessname1 := '';
  v_contactname1 := '';
  v_phonenumber1 := '';
  v_address1 := '';
  v_city1 := '';
  v_postalcode1 := '';
  v_state1 := 0;
  v_country1 := 0;
  v_billingstatus1 := 0;
  v_recentbillinginformation := 0;
  -- SET option (removed)
  -- BEGIN TRAN (removed)
  IF EXISTS(SELECT plid FROM tbl_sponserbilling WHERE plid = v_slid) THEN
  v_intresult := 1;
  SELECT plid, businessname, contactname, phonenumber, address, city, postalcode, sid, cid, billingstatus, date, recentbillinginformation INTO v_slid1, v_businessname1, v_contactname1, v_phonenumber1, v_address1, v_city1, v_postalcode1, v_state1, v_country1, v_billingstatus1, v_date, v_recentbillinginformation FROM tbl_sponserbilling WHERE plid = v_slid;
  INSERT INTO tbl_sponserbillinghistory (plid, businessname, contactname, phonenumber, address, city, postalcode, sid, cid, billingstatus, date, recentbillinginformation) VALUES (v_slid1, v_businessname1, v_contactname1, v_phonenumber1, v_address1, v_city1, v_postalcode1, v_state1, v_country1, v_billingstatus1, v_date, v_recentbillinginformation);
  UPDATE tbl_sponserbilling SET businessname = v_businessname, contactname = v_contactname, phonenumber = v_phonenumber, address = v_address, city = v_city, postalcode = v_postalcode, sid = v_state, cid = v_country, date = GETUTCDATE() WHERE plid = v_slid;
  END IF;
  IF NOT EXISTS(SELECT plid FROM tbl_sponserbilling WHERE plid = v_slid) THEN
  v_intresult := 2;
  INSERT INTO tbl_sponserbilling (plid, businessname, contactname, phonenumber, address, city, postalcode, sid, cid, billingstatus, date, recentbillinginformation) VALUES (v_slid, v_businessname, v_contactname, v_phonenumber, v_address, v_city, v_postalcode, v_state, v_country, 1, GETUTCDATE(), 1);
  END IF;
  IF (0 <> 0) THEN
  v_intresult := 0;
  -- ROLLBACK (removed)
  RETURN;
  END IF;
  -- COMMIT (removed)
  -- SET option (removed)
END;
$$;


--
-- Name: usp_createcanonicalforlisting(bigint, text); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_createcanonicalforlisting(v_pmid bigint, v_currenturl text) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_canonicalurl text;
BEGIN
  SELECT COALESCE(canonicalurl, '') INTO v_canonicalurl FROM portal_master WHERE pmid = v_pmid;
  IF (v_canonicalurl = '') THEN
  UPDATE portal_master SET canonicalurl = v_currenturl WHERE pmid = v_pmid;
  END IF;
  SELECT COALESCE(canonicalurl, '') INTO v_canonicalurl FROM portal_master WHERE pmid = v_pmid;
  RETURN QUERY SELECT pd.companyimage, p.pmid, COALESCE(title, '') AS title, p.mobileno, (CASE WHEN p.address IS NULL OR p.address = '' THEN '' ELSE p.address || ',' END + CASE WHEN p.areaname IS NULL OR p.areaname = '' THEN '' ELSE p.areaname || ',' END + CASE WHEN ct.cityname IS NULL OR ct.cityname = '' THEN '' ELSE ct.cityname || ',' END + CASE WHEN st.statename IS NULL OR st.statename = '' THEN '' ELSE st.statename || ',' END + CASE WHEN pd.zipcode IS NULL OR pd.zipcode = '' THEN '' ELSE pd.zipcode END) AS address, p.areaname, p.companyname, accounttype, coun.countryname, * FROM portal_master AS p, portal_master_details AS pd, city AS ct INNER JOIN country AS coun ON ct.cid = coun.cid INNER JOIN state AS st ON st.sid = ct.sid WHERE p.pmid = pd.pmid AND p.active = 1 AND p.ctid = ct.ctid AND p.pmid = v_pmid;
END;
$$;


