--
-- Name: usp_cursor_insertcity2(); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_cursor_insertcity2() RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_ctid int;
  v_statename varchar(100);
  v_sid int;
  v_cid int;
  v_maxctid int;
  v_citynamename varchar(50);
  cr_ciryname CURSOR FOR SELECT DISTINCT state, city FROM dummy WHERE city <> '' ORDER BY city ASC NULLS FIRST;
BEGIN
  OPEN cr_ciryname;
  FETCH cr_ciryname INTO v_statename,v_citynamename;
  WHILE (found) LOOP
  SELECT sid, cid INTO v_sid, v_cid FROM state WHERE statename = v_statename;
  SELECT MAX(ctid) INTO v_maxctid FROM city;
  IF NOT EXISTS(SELECT * FROM city WHERE cid = v_cid AND sid = v_sid AND cityname = v_citynamename) THEN
  INSERT INTO city VALUES (v_maxctid + 1, v_cid, v_sid, v_citynamename, 1);
  UPDATE dummy SET status = 1 WHERE state = v_statename AND country = 'United States';
  ELSE
  UPDATE dummy SET status = 1 WHERE state = v_statename AND country = 'United States';
  END IF;
  IF (0 <> 0) THEN
  -- ROLLBACK (removed)
  CLOSE cr_ciryname;
  -- DEALLOCATE (removed)
  RETURN;
  END IF;
  FETCH cr_ciryname INTO v_statename,v_citynamename;
  END LOOP;
  CLOSE cr_ciryname;
  -- DEALLOCATE (removed)
END;
$$;


--
-- Name: usp_cursor_updatelocality(); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_cursor_updatelocality() RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_ctid int;
  v_statename varchar(100);
  v_sid int;
  v_cid int;
  v_maxctid int;
  v_postcode varchar(25);
  v_locality varchar(150);
  v_citynamename varchar(50);
  cr_ciryname CURSOR FOR SELECT DISTINCT postcode, locality FROM dummy;
BEGIN
  -- SET option (removed)
  OPEN cr_ciryname;
  FETCH cr_ciryname INTO v_postcode,v_locality;
  WHILE (found) LOOP
  SELECT state, city INTO v_statename, v_citynamename FROM dummy WHERE postcode = v_postcode AND locality = v_locality AND status = 0 LIMIT 1;
  SELECT sid, cid INTO v_sid, v_cid FROM state WHERE statename = v_statename;
  SELECT sid, ctid INTO v_sid, v_ctid FROM city WHERE cityname = v_citynamename AND sid = v_sid;
  UPDATE area_master SET sid = v_sid, ctid = v_ctid WHERE pincode = v_postcode AND areaname = v_locality;
  UPDATE dummy SET status = 1 WHERE postcode = v_postcode AND locality = v_locality;
  IF (0 <> 0) THEN
  -- ROLLBACK (removed)
  CLOSE cr_ciryname;
  -- DEALLOCATE (removed)
  RETURN;
  END IF;
  FETCH cr_ciryname INTO v_postcode,v_locality;
  END LOOP;
  CLOSE cr_ciryname;
  -- DEALLOCATE (removed)
  -- SET option (removed)
END;
$$;


--
-- Name: usp_customer_clubhistory_list(integer, integer, character varying, character varying, character varying, character varying, character varying, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_customer_clubhistory_list(v_startrowindex integer DEFAULT 1, v_maxrows integer DEFAULT 100, v_fromdate character varying DEFAULT ''::character varying, v_todate character varying DEFAULT ''::character varying, v_status character varying DEFAULT ''::character varying, v_searchfield character varying DEFAULT ''::character varying, v_searchvalue character varying DEFAULT ''::character varying, v_totalrecord integer DEFAULT 0) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_query text;
  v_maxregno text;
  v_query1 text;
  v_minindex INT;
  v_maxindex INT;
  v_count INT;
  v_totalcount INT;
  v_chid INT;
  v_totoalcancelamount DECIMAL(18,2);
BEGIN
  -- SET option (removed)
  v_query := '';
  v_maxregno := '';
  v_query1 := '';
  v_count := 1;
  v_totalcount := 0;
  v_chid := 0;
  v_minindex := (v_startrowindex - 1) * v_maxrows + 1;
  v_maxindex := v_startrowindex * v_maxrows;
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp (ROWNUMBER BIGINT,
	  CHID BIGINT,
	  FILENAME VARCHAR(150),
	  DATE timestamp,
	  CLUBGROUP VARCHAR(150),
	  TOTALREQUEST INT,
	  TOTALAMOUNT DECIMAL(18,8),
	  TOTAL_TANSACTION DECIMAL(18,8),
	  PROCESSDATE timestamp,
	  PROCESSBY VARCHAR(50),
	  PROCESSSTATUS VARCHAR(50),
	  PROCESSIPADDRESS VARCHAR(50),
	  BANKNAME VARCHAR(200),
	  TOTALPAID INT,
	  TOTALREJECT INT,
	  TRANSACTION_NO INT,
	  CANCELAMOUNT DECIMAL(18,2)) ON COMMIT DROP;
  v_query := 'INSERT INTO #TEMP SELECT ROW_NUMBER()OVER(ORDER BY CHID DESC) AS ROWNUMBER,CHID,FILENAME,CONVERT(DATE,DATE,105) AS DATE,
CLUBGROUP,TOTALREQUEST,TOTALAMOUNT,TOTAL_TANSACTION,
CONVERT(DATE,PROCESSDATE,105) AS PROCESSDATE,PROCESSBY,PROCESSSTATUS,PROCESSIPADDRESS,BANKNAME,
(SELECT ISNULL(COUNT(DISTINCT CLID),0)  FROM TBL_CUSTOMER_TRANSFERTOBANK  WHERE  STATUS=1 AND TCTTB IN  (SELECT * FROM SPLITSTRING(ALLWDID,'',''))) AS TOTALPAID,
(SELECT ISNULL(COUNT(DISTINCT CLID),0)  FROM TBL_CUSTOMER_TRANSFERTOBANK  WHERE  STATUS=2 AND TCTTB IN  (SELECT * FROM SPLITSTRING(ALLWDID,'',''))) AS TOTALREJECT,
(SELECT ISNULL(COUNT(1),0)  FROM TBL_CUSTOMER_TRANSFERTOBANK  WHERE   TCTTB IN  (SELECT * FROM SPLITSTRING(ALLWDID,'',''))) AS TRANSACTION_NO,0
FROM TBL_CUSTOMER_CLUBHISTORY WHERE 1=1 ';
  RAISE NOTICE '%', v_query;
  EXECUTE v_query;
  SELECT COUNT(1) INTO v_totalcount FROM tmp_temp;
  WHILE (v_totalcount >= v_count) LOOP
  SELECT chid INTO v_chid FROM tmp_temp WHERE rownumber = v_count;
  SELECT COALESCE(SUM(amount), 0) INTO v_totoalcancelamount FROM tbl_customer_downloadclubdata WHERE status = 2 AND chid = v_chid;
  UPDATE tmp_temp SET cancelamount = v_totoalcancelamount WHERE chid = v_chid;
  v_count := v_count + 1;
  END LOOP;
  SELECT COALESCE(COUNT(1), 0) INTO v_totalrecord FROM tmp_temp;
  RETURN QUERY SELECT * FROM tmp_temp ORDER BY rownumber ASC NULLS FIRST;
  DROP TABLE IF EXISTS tmp_temp;
  -- SET option (removed)
END;
$$;


--
-- Name: usp_customer_dth_recharge_requests(integer, character varying, character varying, character varying, character varying, character varying, numeric, character varying, character varying, character varying, character varying, character varying, character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_customer_dth_recharge_requests(v_clid integer DEFAULT 0, v_mobileno character varying DEFAULT ''::character varying, v_operatortype character varying DEFAULT ''::character varying, v_operatorname character varying DEFAULT ''::character varying, v_operatorcode character varying DEFAULT ''::character varying, v_operatorservice character varying DEFAULT ''::character varying, v_rechargeamount numeric DEFAULT 0, v_successurl character varying DEFAULT ''::character varying, v_failureurl character varying DEFAULT ''::character varying, v_inprocessurl character varying DEFAULT ''::character varying, v_cancelledurl character varying DEFAULT ''::character varying, INOUT v_transactionid character varying DEFAULT ''::character varying, INOUT v_stroutput character varying DEFAULT ''::character varying) RETURNS record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_customerwalletamount DECIMAL(18,2);
  v_transid VARCHAR(50);
  v_loginid VARCHAR(50);
  v_admincommission DECIMAL(18,2);
  v_adminsurcharge DECIMAL(18,2);
  v_did INT;
  v_trpid INT;
BEGIN
  BEGIN
  -- BEGIN TRAN (removed)
  v_customerwalletamount := 0;
  IF (v_clid <> 0) THEN
  IF (v_mobileno = '') THEN
  v_transactionid := '';
  v_stroutput := 'Mobile no should not be blank';
  -- COMMIT (removed)
  END IF;
  IF (v_operatortype = '') THEN
  v_transactionid := '';
  v_stroutput := 'Please select operator type';
  -- COMMIT (removed)
  RETURN;
  END IF;
  IF (v_rechargeamount = 0) THEN
  v_transactionid := '';
  v_stroutput := 'Please enter recharge amount';
  -- COMMIT (removed)
  RETURN;
  END IF;
  IF (v_rechargeamount < 0) THEN
  v_transactionid := '';
  v_stroutput := 'Please enter valid recharge amount';
  -- COMMIT (removed)
  RETURN;
  END IF;
  IF (v_clid <> 0 AND v_mobileno <> '') THEN
  IF EXISTS(SELECT 1 FROM tbl_customerlogin WHERE clid = v_clid AND active = 1) THEN
  SELECT COALESCE(availablebalance, 0) INTO v_customerwalletamount FROM tbl_customerwallet WHERE clid = v_clid;
  v_transid := '';
  v_loginid := '';
  v_transid := CAST(CAST(GEN_RANDOM_UUID() AS BYTEA(5)) AS BIGINT) % 1000000000 + 1000000000;
  INSERT INTO dbo.tbl_customer_dth_recharges (clid, mobileno, operatortype, operatorname, operatorcode, operatorservice, rechargeamount, transactionid, successurl, failureurl, inprocessurl, cancelledurl) VALUES (v_clid, v_mobileno, v_operatortype, v_operatorname, v_operatorcode, v_operatorservice, v_rechargeamount, v_transid, v_successurl, v_failureurl, v_inprocessurl, v_cancelledurl);
  v_admincommission := 0;
  v_adminsurcharge := 0;
  v_did := 0;
  v_trpid := 0;
  SELECT did INTO v_did FROM tbl_customerlogin WHERE clid = v_clid;
  SELECT trpid INTO v_trpid FROM tbl_reseller_purchased_packages WHERE did = v_did AND active = 1;
  IF EXISTS(SELECT 1 FROM tbl_reseller_wise_package_commission_settings WHERE did = v_did AND operatorcode = v_operatorcode) THEN
  IF (v_trpid = 1) THEN
  SELECT COALESCE(package1commission, 0) INTO v_admincommission FROM tbl_reseller_wise_package_commission_settings WHERE did = v_did AND operatorcode = v_operatorcode;
  END IF;
  IF (v_trpid = 2) THEN
  SELECT COALESCE(package2commission, 0) INTO v_admincommission FROM tbl_reseller_wise_package_commission_settings WHERE did = v_did AND operatorcode = v_operatorcode;
  END IF;
  IF (v_trpid = 3) THEN
  SELECT COALESCE(package3commission, 0) INTO v_admincommission FROM tbl_reseller_wise_package_commission_settings WHERE did = v_did AND operatorcode = v_operatorcode;
  END IF;
  IF (v_trpid = 4) THEN
  SELECT COALESCE(package4commission, 0) INTO v_admincommission FROM tbl_reseller_wise_package_commission_settings WHERE did = v_did AND operatorcode = v_operatorcode;
  END IF;
  SELECT COALESCE(adminsurcharge, 0) INTO v_adminsurcharge FROM tbl_reseller_wise_package_commission_settings WHERE did = v_did AND operatorcode = v_operatorcode;
  ELSE
  IF (v_trpid = 1) THEN
  SELECT COALESCE(package1commission, 0) INTO v_admincommission FROM tbl_default_package_commission_settings WHERE operatorcode = v_operatorcode;
  END IF;
  IF (v_trpid = 2) THEN
  SELECT COALESCE(package2commission, 0) INTO v_admincommission FROM tbl_default_package_commission_settings WHERE operatorcode = v_operatorcode;
  END IF;
  IF (v_trpid = 3) THEN
  SELECT COALESCE(package3commission, 0) INTO v_admincommission FROM tbl_default_package_commission_settings WHERE operatorcode = v_operatorcode;
  END IF;
  IF (v_trpid = 4) THEN
  SELECT COALESCE(package4commission, 0) INTO v_admincommission FROM tbl_default_package_commission_settings WHERE operatorcode = v_operatorcode;
  END IF;
  SELECT COALESCE(adminsurcharge, 0) INTO v_adminsurcharge FROM tbl_default_package_commission_settings WHERE operatorcode = v_operatorcode;
  END IF;
  UPDATE dbo.tbl_customer_dth_recharges SET admincommission = v_admincommission, adminsurcharge = v_adminsurcharge WHERE clid = v_clid AND operatorcode = v_operatorcode AND transactionid = v_transid;
  v_transactionid := v_transid;
  v_stroutput := 'SUCCESS';
  -- COMMIT (removed)
  END IF;
  END IF;
  END IF;
  EXCEPTION WHEN OTHERS THEN
  IF (0 <> 0) THEN
  PERFORM dbo.sp_errorlog();
  v_transactionid := '';
  v_stroutput := 'Error in request';
  -- ROLLBACK (removed)
  END IF;
  END;
END;
$$;


