--
-- Name: usp_customer_enquiry(character varying, character varying, integer, integer, integer, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_customer_enquiry(v_fromdate character varying DEFAULT ''::character varying, v_todate character varying DEFAULT ''::character varying, v_startrowindex integer DEFAULT 1, v_maxrows integer DEFAULT 100, v_totalcount integer DEFAULT 0, v_plid integer DEFAULT 0) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_minindex INT;
  v_maxindex INT;
  v_query varchar(4000);
BEGIN
  v_minindex := 1;
  v_maxindex := 100;
  v_minindex := (v_startrowindex - 1) * v_maxrows + 1;
  v_maxindex := v_startrowindex * v_maxrows;
  -- BEGIN TRAN (removed)
  BEGIN
  v_query := '';
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp (ROWNUMBER BIGINT GENERATED BY DEFAULT AS IDENTITY,      
  PIID INT,    
  CCEMAILID VARCHAR(200),  
  CCNAME VARCHAR(100),  
  MAILDATE timestamp,  
  MESSAGE text,  
  MOBILE VARCHAR(20)) ON COMMIT DROP;
  v_query := 'INSERT INTO #TEMP SELECT PIID,CCEMAILID,CCNAME,MAILDATE,MESSAGE,MOBILE FROM PORTAL_INBOX WHERE 1=1  ';
  IF (v_fromdate <> '' AND v_todate = '') THEN
  v_query := v_query || (' And Convert(Date,MAILDATE) >= Convert(Date,''' || v_fromdate || ''') ');
  END IF;
  IF (v_fromdate = '' AND v_todate <> '') THEN
  v_query := v_query || (' And Convert(Date,MAILDATE) <= Convert(Date,''' || v_todate || ''') ');
  END IF;
  IF (v_fromdate <> '' AND v_todate <> '') THEN
  v_query := v_query || (' And Convert(Date,MAILDATE) Between Convert(Date,''' || v_fromdate || ''') And Convert(Date,''' || v_todate || ''') ');
  END IF;
  v_query := v_query || (' Order by MAILDATE Desc');
  RAISE NOTICE '%', v_query;
  EXECUTE v_query;
  RETURN QUERY SELECT * FROM tmp_temp WHERE rownumber BETWEEN v_minindex AND v_maxindex;
  SELECT COUNT(1) INTO v_totalcount FROM tmp_temp;
  DROP TABLE IF EXISTS tmp_temp;
  EXCEPTION WHEN OTHERS THEN
  PERFORM dbo.sp_errorlog();
  IF (0 > 0) THEN
  -- ROLLBACK (removed)
  END IF;
  RETURN;
  END;
  IF (0 <> 0) THEN
  v_totalcount := 0;
  -- ROLLBACK (removed)
  RETURN;
  ELSE
  -- COMMIT (removed)
  END IF;
END;
$$;


