  SELECT COALESCE(adminsurcharge, 0) INTO v_adminsurcharge FROM tbl_reseller_wise_package_commission_settings WHERE did = v_did AND operatorcode = v_operatorcode;
  ELSE
  IF (v_trpid = 1) THEN
  SELECT COALESCE(package1commission, 0) INTO v_admincommission FROM tbl_default_package_commission_settings WHERE operatorcode = v_operatorcode;
  END IF;
  IF (v_trpid = 2) THEN
  SELECT COALESCE(package2commission, 0) INTO v_admincommission FROM tbl_default_package_commission_settings WHERE operatorcode = v_operatorcode;
  END IF;
  IF (v_trpid = 3) THEN
  SELECT COALESCE(package3commission, 0) INTO v_admincommission FROM tbl_default_package_commission_settings WHERE operatorcode = v_operatorcode;
  END IF;
  IF (v_trpid = 4) THEN
  SELECT COALESCE(package4commission, 0) INTO v_admincommission FROM tbl_default_package_commission_settings WHERE operatorcode = v_operatorcode;
  END IF;
  SELECT COALESCE(adminsurcharge, 0) INTO v_adminsurcharge FROM tbl_default_package_commission_settings WHERE operatorcode = v_operatorcode;
  END IF;
  UPDATE dbo.tbl_customer_gas_recharges SET admincommission = v_admincommission, adminsurcharge = v_adminsurcharge WHERE clid = v_clid AND operatorcode = v_operatorcode AND transactionid = v_transid;
  v_transactionid := v_transid;
  v_stroutput := 'SUCCESS';
  -- COMMIT (removed)
  END IF;
  END IF;
  END IF;
  EXCEPTION WHEN OTHERS THEN
  IF (0 <> 0) THEN
  PERFORM dbo.sp_errorlog();
  v_transactionid := '';
  v_stroutput := 'Error in request';
  -- ROLLBACK (removed)
  END IF;
  END;
END;
$$;


--
-- Name: usp_customer_landline_recharge_requests(integer, character varying, character varying, character varying, character varying, character varying, numeric, character varying, character varying, character varying, character varying, character varying, character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_customer_landline_recharge_requests(v_clid integer DEFAULT 0, v_mobileno character varying DEFAULT ''::character varying, v_operatortype character varying DEFAULT ''::character varying, v_operatorname character varying DEFAULT ''::character varying, v_operatorcode character varying DEFAULT ''::character varying, v_operatorservice character varying DEFAULT ''::character varying, v_rechargeamount numeric DEFAULT 0, v_successurl character varying DEFAULT ''::character varying, v_failureurl character varying DEFAULT ''::character varying, v_inprocessurl character varying DEFAULT ''::character varying, v_cancelledurl character varying DEFAULT ''::character varying, INOUT v_transactionid character varying DEFAULT ''::character varying, INOUT v_stroutput character varying DEFAULT ''::character varying) RETURNS record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_customerwalletamount DECIMAL(18,2);
  v_transid VARCHAR(50);
  v_loginid VARCHAR(50);
BEGIN
  BEGIN
  -- BEGIN TRAN (removed)
  v_customerwalletamount := 0;
  IF (v_clid <> 0) THEN
  IF (v_mobileno = '') THEN
  v_transactionid := '';
  v_stroutput := 'MOBILE NO SHOULD NOT BE BLANK';
  -- COMMIT (removed)
  END IF;
  IF (v_operatortype = '') THEN
  v_transactionid := '';
  v_stroutput := 'PLEASE SELECT OPERATOR TYPE';
  -- COMMIT (removed)
  RETURN;
  END IF;
  IF (v_rechargeamount = 0) THEN
  v_transactionid := '';
  v_stroutput := 'PLEASE ENTER RECHARGE AMOUNT';
  -- COMMIT (removed)
  RETURN;
  END IF;
  IF (v_rechargeamount < 0) THEN
  v_transactionid := '';
  v_stroutput := 'PLEASE ENTER VALID RECHARGE AMOUNT';
  -- COMMIT (removed)
  RETURN;
  END IF;
  IF (v_clid <> 0 AND v_mobileno <> '') THEN
  IF EXISTS(SELECT 1 FROM tbl_customerlogin WHERE clid = v_clid AND active = 1) THEN
  SELECT COALESCE(availablebalance, 0) INTO v_customerwalletamount FROM tbl_customerwallet WHERE clid = v_clid;
  IF (v_customerwalletamount < v_rechargeamount) THEN
  v_transactionid := '';
  v_stroutput := 'INSUFFICIENT AMOUNT IN WALLET';
  -- COMMIT (removed)
  RETURN;
  END IF;
  v_transid := '';
  v_loginid := '';
  v_transid := CAST(CAST(GEN_RANDOM_UUID() AS BYTEA(5)) AS BIGINT) % 1000000000 + 1000000000;
  INSERT INTO dbo.tbl_customer_landline_recharges (clid, mobileno, operatortype, operatorname, operatorcode, operatorservice, rechargeamount, transactionid, successurl, failureurl, inprocessurl, cancelledurl) VALUES (v_clid, v_mobileno, v_operatortype, v_operatorname, v_operatorcode, v_operatorservice, v_rechargeamount, v_transid, v_successurl, v_failureurl, v_inprocessurl, v_cancelledurl);
  v_transactionid := v_transid;
  v_stroutput := 'SUCCESS';
  -- COMMIT (removed)
  END IF;
  END IF;
  END IF;
  EXCEPTION WHEN OTHERS THEN
  IF (0 <> 0) THEN
  PERFORM dbo.sp_errorlog();
  v_transactionid := '';
  v_stroutput := 'ERROR IN REQUEST';
  -- ROLLBACK (removed)
  END IF;
  END;
END;
$$;


--
-- Name: usp_customer_make_order(character varying, character varying, text, character varying, character varying, character varying, character varying, character varying, character varying, character varying, character varying, text, character varying, character varying, character varying, character varying, character varying, character varying, character varying, character varying, character varying, integer, integer, character varying, character varying, numeric, numeric, numeric, character varying, character varying, integer, character varying, numeric, numeric, numeric); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_customer_make_order(v_orderid character varying DEFAULT ''::character varying, v_loginid character varying DEFAULT ''::character varying, v_product text DEFAULT ''::text, v_fname character varying DEFAULT ''::character varying, v_lname character varying DEFAULT ''::character varying, v_address11 character varying DEFAULT ''::character varying, v_towncity character varying DEFAULT ''::character varying, v_postalcode character varying DEFAULT ''::character varying, v_emails character varying DEFAULT ''::character varying, v_mobile character varying DEFAULT ''::character varying, v_paymode character varying DEFAULT ''::character varying, v_paymentremark text DEFAULT ''::text, v_ordertype character varying DEFAULT ''::character varying, v_sh_fname character varying DEFAULT ''::character varying, v_sh_lname character varying DEFAULT ''::character varying, v_sh_address11 character varying DEFAULT ''::character varying, v_sh_towncity character varying DEFAULT ''::character varying, v_sh_postalcode character varying DEFAULT ''::character varying, v_sh_emails character varying DEFAULT ''::character varying, v_sh_mobile character varying DEFAULT ''::character varying, v_strresult character varying DEFAULT ''::character varying, v_distributorid integer DEFAULT 1, v_iscouponapplyed integer DEFAULT 0, v_username character varying DEFAULT ''::character varying, v_transactionpassword character varying DEFAULT ''::character varying, v_sumbv numeric DEFAULT 0, v_jp numeric DEFAULT 0, v_netorder numeric DEFAULT 0, v_usernameewallet character varying DEFAULT ''::character varying, v_transactionpasswordewallet character varying DEFAULT ''::character varying, v_plid integer DEFAULT 0, v_stockistusername character varying DEFAULT ''::character varying, v_sumcashback numeric DEFAULT 0.00, v_payableforpurchase numeric DEFAULT 0.00, v_order_activationpv numeric DEFAULT 0.00) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_orderidtemp VARCHAR(200);
  v_replacementday INT;
  v_ordercode VARCHAR(5);
  v_qty INT;
  v_prcode VARCHAR(50);
  v_prodqty VARCHAR(50);
  v_produnit VARCHAR(50);
  v_prodcolor VARCHAR(50);
  v_prodsize VARCHAR(50);
  v_prodimages text;
  v_product_name VARCHAR(250);
  v_singl_dap numeric(19,4);
  v_total_dap numeric(19,4);
  v_clid int;
  v_countrow INT;
  v_countnewrow INT;
  v_value text;
  v_idx INT;
  v_orid BIGINT;
  v_total_qty INT;
  v_total_price numeric(19,4);
  v_total_paid_product_price numeric(19,4);
  v_maxpoid BIGINT;
  v_getcoupondiscoutvalue numeric(19,4);
  v_city VARCHAR(150);
  v_pv numeric(19,4);
  v_totalpv numeric(19,4);
  v_bv numeric(19,4);
  v_totalbv numeric(19,4);
  v_currentdate timestamp;
  v_defaultecombrcode VARCHAR(30);
  v_sh_charge numeric(19,4);
  v_total_sh_charge numeric(19,4);
  v_vcid numeric(19,4);
  v_vat numeric(19,4);
  v_totalvat numeric(19,4);
  v_total_single_price numeric(19,4);
  v_total_order_price numeric(19,4);
  v_actualprice numeric(19,4);
  v_total_single_purchasecost numeric(19,4);
  v_subprcode VARCHAR(30);
  v_fromplid bigint;
  v_total_single_dap numeric(19,4);
  v_prid_new BIGINT;
  v_singlebv numeric(19,4);
  v_mprefix varchar(1);
  v_stockin INT;
  v_stockout INT;
  v_stocknet INT;
  v_isoutofstock boolean;
  v_merchantid int;
  v_orderstatus int;
  v_orderstatusvalue varchar(100);
  v_did INT;
  v_trpid INT;
  v_adminpackagecommision DECIMAL(18,2);
  v_resellerpackagecommisssion DECIMAL(18,2);
  v_kyccount INT;
  v_custusername VARCHAR(100);
  v_count INT;
  v_row INT;
  v_sprid BIGINT;
  v_branchid BIGINT;
  v_matchbranchid BIGINT;
  v_branchid_temp BIGINT;
  v_qntycount INT;
  v_childcount INT;
  v_rowcountchild INT;
  v_maincatid INT;
  v_subcatid INT;
  v_catid INT;
  v_totalproductcost DECIMAL(18,2);
  v_totalproductshipping DECIMAL(18,2);
  v_totalproductpayable DECIMAL(18,2);
  v_totalproductbv DECIMAL(10,2);
  v_totalproductpv DECIMAL(10,2);
  v_totalproductcashback DECIMAL(10,2);
  v_totalproductactivationpv DECIMAL(10,2);
  v_offerid int;
  v_orderno VARCHAR(6);
  v_chars char(88);
  v_referalcode text;
  v_intcontinue INT;
  v_morderid VARCHAR(6);
  v_chars1 char(88);
  v_referalcode1 text;
  v_intcontinue1 INT;
  v_tcntid INT;
  v_mordercount INT;
  v_mtemporderid VARCHAR(100);
BEGIN
  -- BEGIN TRAN (removed)
  v_orderidtemp := '';
  v_replacementday := 0;
  v_ordercode := '';
  v_singl_dap := 0;
  v_total_dap := 0;
  v_clid := 0;
  v_countrow := 0;
  v_countnewrow := 0;
  v_total_qty := 0;
  v_total_price := 0;
  v_total_paid_product_price := 0;
  v_getcoupondiscoutvalue := 0;
  v_pv := 0;
  v_totalpv := 0;
  v_bv := 0;
  v_totalbv := 0;
  v_sh_charge := 0;
  v_total_sh_charge := 0;
  v_vcid := 0;
  v_vat := 0;
  v_totalvat := 0;
  v_total_single_price := 0;
  v_total_order_price := 0;
  v_actualprice := 0;
  v_total_single_purchasecost := 0;
  v_fromplid := 0;
  v_total_single_dap := 0;
  v_singlebv := 0;
  v_mprefix := 'M';
  v_stockin := 0;
  v_stockout := 0;
  v_stocknet := 0;
  v_isoutofstock := 0;
  v_merchantid := 0;
  v_orderstatus := 0;
  v_did := 0;
  v_trpid := 0;
  v_adminpackagecommision := 0;
  v_resellerpackagecommisssion := 0;
  v_kyccount := 0;
  v_custusername := '';
  SELECT COALESCE(username, '') INTO v_custusername FROM tbl_customerlogin WHERE loginid = v_loginid;
  SELECT COUNT(1) INTO v_kyccount FROM db_affiliate.dbo.member_master WHERE kycstatus = 2 AND regno = (SELECT regno FROM db_affiliate.dbo.member_master WHERE username = v_custusername);
  v_kyccount := 1;
  IF (v_netorder > 20000) THEN
  IF (v_kyccount < 1) THEN
  v_strresult := 'Your KYC is Pending !';
  -- COMMIT (removed)
  RETURN;
  END IF;
  END IF;
  SELECT clid, COALESCE(did, 0) INTO v_clid, v_did FROM tbl_customerlogin WHERE loginid = v_loginid;
  SELECT COALESCE(trpid, 0) INTO v_trpid FROM tbl_reseller_purchased_packages WHERE did = v_did LIMIT 1;
  DROP TABLE IF EXISTS tmp_temp1;
  CREATE TEMP TABLE tmp_temp1 ON COMMIT DROP AS SELECT LEFT(CAST(value AS TEXT), POSITION('^' IN value) - 1) AS sprid, SUBSTRING(value FROM POSITION('^' IN value) + 1 FOR LENGTH(CAST(value AS TEXT))) AS qty, COALESCE((SELECT branchid FROM ims_masterproduct AS pm INNER JOIN ims_subproduct AS sp ON sp.mprid = pm.mprid WHERE sp.sprid = LEFT(CAST(value AS TEXT), POSITION('^' IN value) - 1)), 0) AS branchid FROM SPLITSTRINGBYCUSTOMSYMBOL1(v_product, '|');
  DROP TABLE IF EXISTS tmp_temp2;
  CREATE TEMP TABLE tmp_temp2 ON COMMIT DROP AS SELECT ROW_NUMBER() OVER (ORDER BY branchid ASC NULLS FIRST) AS rowno, DENSE_RANK() OVER (ORDER BY branchid NULLS FIRST) AS denserank, * FROM tmp_temp1;
  v_count := 1;
  SELECT MAX(denserank) INTO v_countrow FROM tmp_temp2;
  WHILE (v_count <= 1) LOOP
  v_row := 0;
  v_sprid := 0;
  v_branchid := 0;
  v_matchbranchid := 0;
  v_total_dap := 0;
  v_singl_dap := 0;
  v_total_qty := 0;
  v_total_qty := 0;
  v_total_dap := 0;
  v_total_sh_charge := 0;
  v_total_order_price := 0;
  v_totalvat := 0;
  v_branchid_temp := 0;
  v_qntycount := 0;
  SELECT branchid INTO v_branchid_temp FROM tmp_temp2 WHERE denserank = v_count LIMIT 1;
  RETURN QUERY SELECT v_count AS counts, v_countrow AS countrow, v_branchid_temp AS branchid_temp;
  SELECT v_strresult INTO v_orderid FROM dbo.getorderid(v_strresult => v_orderid);
  SELECT 'OD' INTO v_ordercode;
  v_orderid := v_ordercode || v_orderid;
  IF NOT EXISTS(SELECT 1 FROM tbl_order_master WHERE orderid = v_orderid) THEN
  v_orderidtemp := v_orderidtemp || ',' || v_orderid;
  v_qntycount := 0;
  SELECT SUM(CAST(qty AS INT)) INTO v_qntycount FROM tmp_temp2;
  IF (v_paymode = 'COD') THEN
  v_orderstatus := 0;
  v_orderstatusvalue := 'Pending';
  ELSE
  v_orderstatus := -1;
  v_orderstatusvalue := 'Hold';
  END IF;
  INSERT INTO tbl_order_master (loginid, orderid, ordertype, orderdate, order_qty, order_dap, total_vat, total_ship_ch, order_netamt, order_pv, order_bv, paymode, paytransid, payremark, fname, lname, mobileno, emailid, address, pincode, city, sh_fname, sh_lname, sh_mobileno, sh_emailid, sh_address, sh_pincode, sh_city, totalacceptedamt, totalrejectedamt, branchid, emp_code, status, intstatus, description, isbvdist, order_cashback, order_activationpv) VALUES (v_loginid, v_orderid, v_ordertype, dbo.FUN_GETCURRENTDATE(), v_qntycount, 0, 0, 0, 0, v_jp, v_sumbv, v_paymode, '', v_paymentremark, v_fname, v_lname, v_mobile, v_emails, v_address11, v_postalcode, v_sh_towncity, v_sh_fname, v_sh_lname, v_sh_mobile, v_sh_emails, v_sh_address11, v_sh_postalcode, v_towncity, 0, 0, 0, '', v_orderstatusvalue, v_orderstatus, 'Order is pending', 0, v_sumcashback, v_order_activationpv);
  v_childcount := 0;
  v_rowcountchild := 0;
  v_maincatid := 0;
  v_subcatid := 0;
  v_catid := 0;
  SELECT MIN(rowno) INTO v_rowcountchild FROM tmp_temp2;
  SELECT MAX(rowno) INTO v_childcount FROM tmp_temp2;
  RETURN QUERY SELECT v_rowcountchild AS childcountminxx, v_childcount AS childmaxyyy;
  WHILE (v_rowcountchild <= v_childcount) LOOP
  SELECT sprid, qty INTO v_prcode, v_qty FROM tmp_temp2 WHERE rowno = v_rowcountchild;
  SELECT dap, qty, unit, color, size, productimages, COALESCE(shippingcharges, 0), vatcategoryid, actualprice, subprcode, replacementday, stockin, stockout, stocknet, isoutofstock INTO v_singl_dap, v_prodqty, v_produnit, v_prodcolor, v_prodsize, v_prodimages, v_sh_charge, v_vcid, v_actualprice, v_subprcode, v_replacementday, v_stockin, v_stockout, v_stocknet, v_isoutofstock FROM ims_subproduct WHERE sprid = v_prcode;
  SELECT COALESCE(branchid, 0), COALESCE(maincategoryid, 0), COALESCE(subcategoryid, 0), COALESCE(catid, 0) INTO v_merchantid, v_maincatid, v_subcatid, v_catid FROM ims_masterproduct WHERE mprid IN (SELECT mprid FROM ims_subproduct WHERE sprid = v_prcode);
  IF (v_trpid = 5) THEN
  SELECT COALESCE(admincommissison, 0), COALESCE(actualcommpackage1, 0) INTO v_adminpackagecommision, v_resellerpackagecommisssion FROM tbl_prodouct_packagewise_commission WHERE maincatid = v_maincatid AND cattid = v_catid AND subcatid = v_subcatid;
  END IF;
  IF (v_trpid = 6) THEN
  SELECT COALESCE(admincommissison, 0), COALESCE(actualcommpackage2, 0) INTO v_adminpackagecommision, v_resellerpackagecommisssion FROM tbl_prodouct_packagewise_commission WHERE maincatid = v_maincatid AND cattid = v_catid AND subcatid = v_subcatid;
  END IF;
  IF (v_trpid = 7) THEN
  SELECT COALESCE(admincommissison, 0), COALESCE(actualcommpackage3, 0) INTO v_adminpackagecommision, v_resellerpackagecommisssion FROM tbl_prodouct_packagewise_commission WHERE maincatid = v_maincatid AND cattid = v_catid AND subcatid = v_subcatid;
  END IF;
  IF (v_trpid = 8) THEN
  SELECT COALESCE(admincommissison, 0), COALESCE(actualcommpackage4, 0) INTO v_adminpackagecommision, v_resellerpackagecommisssion FROM tbl_prodouct_packagewise_commission WHERE maincatid = v_maincatid AND cattid = v_catid AND subcatid = v_subcatid;
  END IF;
  IF (v_stockin < v_qty) THEN
  v_strresult := 'Stock Unavailable';
  -- COMMIT (removed)
  RETURN;
  END IF;
  SELECT producttitle INTO v_product_name FROM ims_masterproduct WHERE mprid = (SELECT mprid FROM ims_subproduct WHERE sprid = v_prcode);
  SELECT COALESCE(vatpercvalue, 0) INTO v_vat FROM tbl_vat_categories WHERE vcid = v_vcid;
  v_totalproductcost := 0;
  v_totalproductshipping := 0;
  v_totalproductpayable := 0;
  v_totalproductbv := 0;
  v_totalproductpv := 0;
  v_totalproductcashback := 0;
  v_totalproductactivationpv := 0.00;
  SELECT bv INTO v_totalproductbv FROM ims_subproduct WHERE mprid = (SELECT mprid FROM ims_subproduct WHERE sprid = v_prcode);
  SELECT pv INTO v_totalproductpv FROM ims_subproduct WHERE mprid = (SELECT mprid FROM ims_subproduct WHERE sprid = v_prcode);
  SELECT cashback_per INTO v_totalproductcashback FROM ims_subproduct WHERE mprid = (SELECT mprid FROM ims_subproduct WHERE sprid = v_prcode);
  SELECT activationpv_per INTO v_totalproductactivationpv FROM ims_subproduct WHERE mprid = (SELECT mprid FROM ims_subproduct WHERE sprid = v_prcode);
  v_offerid := 0;
  SELECT offer_mst_id INTO v_offerid FROM tbl_offer_on_product WHERE sprid = v_prcode AND CURRENT_TIMESTAMP BETWEEN offer_start AND offer_end;
  IF (COALESCE(v_offerid, 0) <> 0) THEN
  v_singl_dap := (SELECT offer_price / ((100 + v_vat) / 100) FROM tbl_offer_on_product WHERE sprid = v_prcode);
  END IF;
  v_total_dap := v_singl_dap * v_qty;
  v_totalproductshipping := v_sh_charge * v_qty;
  v_totalproductcost := v_total_dap + v_totalproductshipping;
  v_vat := (v_total_dap * v_vat) / 100;
  v_totalproductpayable := v_totalproductcost + v_vat;
  v_total_single_dap := v_total_single_dap + v_total_dap;
  v_total_sh_charge := v_total_sh_charge + v_totalproductshipping;
  v_total_order_price := v_total_order_price + v_totalproductpayable;
  v_total_qty := v_total_qty + v_qty;
  v_totalvat := v_totalvat + v_vat;
  v_totalproductbv := v_totalproductbv * v_qty;
  v_totalproductpv := v_totalproductpv * v_qty;
  v_totalproductcashback := v_totalproductcashback * v_qty;
  v_totalproductactivationpv := COALESCE(v_totalproductactivationpv, 0) * v_qty;
  v_orderno := '';
  v_referalcode := '';
  v_intcontinue := 0;
  SELECT 0 INTO v_intcontinue;
  v_chars := N'8123456789';
  WHILE (v_intcontinue = 0) LOOP
  v_orderno := SUBSTRING(v_chars FROM CAST((RANDOM() * LENGTH(CAST(v_chars AS TEXT))) AS INT) + 1 FOR 1) || SUBSTRING(v_chars FROM CAST((RANDOM() * LENGTH(CAST(v_chars AS TEXT))) AS INT) + 1 FOR 1) || SUBSTRING(v_chars FROM CAST((RANDOM() * LENGTH(CAST(v_chars AS TEXT))) AS INT) + 1 FOR 1) || SUBSTRING(v_chars FROM CAST((RANDOM() * LENGTH(CAST(v_chars AS TEXT))) AS INT) + 1 FOR 1) || SUBSTRING(v_chars FROM CAST((RANDOM() * LENGTH(CAST(v_chars AS TEXT))) AS INT) + 1 FOR 1) || SUBSTRING(v_chars FROM CAST((RANDOM() * LENGTH(CAST(v_chars AS TEXT))) AS INT) + 1 FOR 1) || SUBSTRING(v_chars FROM CAST((RANDOM() * LENGTH(CAST(v_chars AS TEXT))) AS INT) + 1 FOR 1) || SUBSTRING(v_chars FROM CAST((RANDOM() * LENGTH(CAST(v_chars AS TEXT))) AS INT) + 1 FOR 1);
  IF EXISTS(SELECT 1 FROM tbl_product_order_master WHERE orderno = v_orderno) THEN
  v_intcontinue := 0;
  ELSE
  IF (LENGTH(CAST(v_orderno AS TEXT)) < 6) THEN
  v_intcontinue := 0;
  ELSE
  IF ((SELECT SUBSTRING(v_orderno FROM 1 FOR 1)) <= 0) THEN
  v_intcontinue := 0;
  ELSE
  v_intcontinue := 1;
  END IF;
  END IF;
  END IF;
  END LOOP;
  v_morderid := '';
  v_referalcode1 := '';
  v_intcontinue1 := 0;
  SELECT 0 INTO v_intcontinue1;
  v_chars1 := N'8123456789';
  WHILE (v_intcontinue1 = 0) LOOP
  v_morderid := SUBSTRING(v_chars1 FROM CAST((RANDOM() * LENGTH(CAST(v_chars1 AS TEXT))) AS INT) + 1 FOR 1) || SUBSTRING(v_chars1 FROM CAST((RANDOM() * LENGTH(CAST(v_chars1 AS TEXT))) AS INT) + 1 FOR 1) || SUBSTRING(v_chars1 FROM CAST((RANDOM() * LENGTH(CAST(v_chars1 AS TEXT))) AS INT) + 1 FOR 1) || SUBSTRING(v_chars1 FROM CAST((RANDOM() * LENGTH(CAST(v_chars1 AS TEXT))) AS INT) + 1 FOR 1) || SUBSTRING(v_chars1 FROM CAST((RANDOM() * LENGTH(CAST(v_chars1 AS TEXT))) AS INT) + 1 FOR 1) || SUBSTRING(v_chars1 FROM CAST((RANDOM() * LENGTH(CAST(v_chars1 AS TEXT))) AS INT) + 1 FOR 1) || SUBSTRING(v_chars1 FROM CAST((RANDOM() * LENGTH(CAST(v_chars1 AS TEXT))) AS INT) + 1 FOR 1) || SUBSTRING(v_chars1 FROM CAST((RANDOM() * LENGTH(CAST(v_chars1 AS TEXT))) AS INT) + 1 FOR 1);
  IF EXISTS(SELECT 1 FROM tbl_product_order_master WHERE morderid = v_morderid AND plid = v_merchantid) THEN
  v_intcontinue1 := 0;
  ELSE
  IF (LENGTH(CAST(v_morderid AS TEXT)) < 6) THEN
  v_intcontinue1 := 0;
  ELSE
  IF ((SELECT SUBSTRING(v_morderid FROM 1 FOR 1)) <= 0) THEN
  v_intcontinue1 := 0;
  ELSE
  v_intcontinue1 := 1;
  END IF;
  END IF;
  END IF;
  END LOOP;
  v_tcntid := 0;
  SELECT tcntid INTO v_tcntid FROM tbl_customer_notifications_type WHERE notificationtype = 'ORDERS';
  INSERT INTO tbl_customer_notifications VALUES (v_tcntid, v_clid, 'We have received an order of ' || v_product_name || '.', dbo.FUN_GETCURRENTDATE(), v_orderno, 0, 0, dbo.FUN_GETCURRENTDATE(), v_orderid, NULL);
  INSERT INTO tbl_merchant_notifications VALUES (v_tcntid, v_merchantid, 'We have received an order of ' || v_product_name || '.', dbo.FUN_GETCURRENTDATE(), v_orderno, 0, 0, dbo.FUN_GETCURRENTDATE(), v_orderid, NULL);
  INSERT INTO tbl_product_order_master (loginid, orderid, subprcode, product_qty, single_dap, total_dap, total_ship_ch, total_cost, total_vat, total_pv, total_bv, total_purchase_cost, total_payble_vat, product_name, prodqty, prounit, prodcolor, prodsize, prod_images, status, intstatus, replacementday, orderno, plid, admincommission, resellercommission, order_cashback, order_activationpv) VALUES (v_loginid, v_orderid, v_prcode, v_qty, v_singl_dap, v_total_dap, v_totalproductshipping, v_totalproductcost, v_vat, v_totalproductpv, v_totalproductbv, v_totalproductpayable, v_vat, v_product_name, v_prodqty, v_produnit, v_prodcolor, v_prodsize, v_prodimages, v_orderstatusvalue, v_orderstatus, v_replacementday, v_orderno, v_merchantid, v_adminpackagecommision, v_resellerpackagecommisssion, v_totalproductcashback, v_totalproductactivationpv);
  v_mordercount := 0;
  v_mtemporderid := '';
  SELECT COUNT(1) INTO v_mordercount FROM tbl_product_order_master WHERE orderid = v_orderid AND plid = v_merchantid AND morderid <> '';
  IF (v_mordercount > 0) THEN
  SELECT morderid INTO v_mtemporderid FROM tbl_product_order_master WHERE orderid = v_orderid AND plid = v_merchantid AND morderid <> '';
  UPDATE tbl_product_order_master SET morderid = v_mtemporderid WHERE orderid = v_orderid AND plid = v_merchantid;
  ELSE
  UPDATE tbl_product_order_master SET morderid = v_mprefix || CAST(v_merchantid AS VARCHAR(30)) || CAST(v_morderid AS VARCHAR(30)) WHERE orderid = v_orderid AND plid = v_merchantid;
  END IF;
  INSERT INTO tbl_order_confirmedstaus (customerid, merchantid, orderid, orderno, createddate, status, date) VALUES (v_loginid, v_branchid_temp, v_orderid, v_orderno, dbo.FUN_GETCURRENTDATE(), -1, dbo.FUN_GETCURRENTDATE());
  v_rowcountchild := v_rowcountchild + 1;
  END LOOP;
  UPDATE tbl_order_master SET order_qty = v_total_qty, order_dap = v_total_single_dap, total_ship_ch = v_total_sh_charge, order_netamt = v_total_order_price, total_vat = v_totalvat WHERE orderid = v_orderid;
  ELSE
  RAISE NOTICE '%', 'ELSE CONDITION';
  END IF;
  v_count := v_count + 1;
  END LOOP;
  v_strresult := v_orderidtemp || '^add';
  DROP TABLE IF EXISTS tmp_temp2;
  DROP TABLE IF EXISTS tmp_temp1;
  IF (0 <> 0) THEN
  -- ROLLBACK (removed)
  v_strresult := 'Some error occured';
  RETURN;
  END IF;
  -- COMMIT (removed)
END;
$$;


--
-- Name: usp_customer_make_voucher_order(character varying, character varying, numeric, character varying, character varying, integer, integer, numeric, integer, character varying, character varying, character varying, character varying, character varying, character varying, numeric, numeric, numeric, character varying); Type: FUNCTION; Schema: dbo; Owner: -
