CREATE FUNCTION dbo.usp_customer_make_voucher_order(v_loginid character varying, INOUT v_orderid character varying DEFAULT ''::character varying, v_denominantion numeric DEFAULT NULL::numeric, v_pguid character varying DEFAULT NULL::character varying, v_productcode character varying DEFAULT NULL::character varying, v_vmid integer DEFAULT NULL::integer, v_dmid integer DEFAULT NULL::integer, v_orderamount numeric DEFAULT NULL::numeric, v_orderqty integer DEFAULT NULL::integer, v_fname character varying DEFAULT NULL::character varying, v_lname character varying DEFAULT NULL::character varying, v_mobile character varying DEFAULT NULL::character varying, v_emailid character varying DEFAULT NULL::character varying, v_address character varying DEFAULT NULL::character varying, v_pincode character varying DEFAULT NULL::character varying, v_bv numeric DEFAULT NULL::numeric, v_redeemcashback numeric DEFAULT NULL::numeric, v_receivablecashback numeric DEFAULT NULL::numeric, INOUT v_strresult character varying DEFAULT ''::character varying) RETURNS record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_kyccount INT;
  v_cusmobile VARCHAR(100);
BEGIN
  -- BEGIN TRAN (removed)
  v_kyccount := 0;
  v_cusmobile := '';
  SELECT COALESCE(phone, '') INTO v_cusmobile FROM tbl_customerlogin WHERE loginid = v_loginid;
  SELECT COUNT(1) INTO v_kyccount FROM db_kreazlife.dbo.tbl_memberkycdetails WHERE approve = 1 AND regno = (SELECT regno FROM db_kreazlife.dbo.member_master WHERE mobile = v_cusmobile);
  IF (v_orderamount > 10000) THEN
  IF (v_kyccount < 4) THEN
  v_strresult := 'Your KYC is Pending !';
  -- COMMIT (removed)
  RETURN;
  END IF;
  END IF;
  SELECT v_strresult INTO v_orderid FROM dbo.getvoucherorderid(v_strresult => v_orderid);
  v_orderid := 'EV-OD' || v_orderid;
  IF NOT EXISTS(SELECT 1 FROM tbl_voucher_order_master WHERE orderid = v_orderid) THEN
  INSERT INTO tbl_voucher_order_master (loginid, orderid, orderdatetime, denominantion, pguid, productcode, vmid, vcid, dmid, orderamount, orderqty, fname, lname, mobile, emailid, address, pincode, status, intstatus, description, bv, redeemcashback, receivablecashback, active) VALUES (v_loginid, v_orderid, dbo.FUN_GETCURRENTDATE(), v_denominantion, v_pguid, v_productcode, v_vmid, 0, v_dmid, v_orderamount, v_orderqty, v_fname, v_lname, v_mobile, v_emailid, v_address, v_pincode, 'Hold', -1, 'Order Is Attemted', v_bv, v_redeemcashback, v_receivablecashback, 1);
  -- COMMIT (removed)
  v_strresult := 'success';
  RETURN;
  ELSE
  -- COMMIT (removed)
  v_strresult := 'Order Id Already Exists';
  RETURN;
  END IF;
  IF (0 <> 0) THEN
  -- ROLLBACK (removed)
  v_strresult := 'Some error occured';
  RETURN;
  END IF;
  -- COMMIT (removed)
END;
$$;


--
-- Name: usp_customer_postpaid_recharge_requests(integer, character varying, character varying, character varying, character varying, character varying, numeric, character varying, character varying, character varying, character varying, character varying, character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_customer_postpaid_recharge_requests(v_clid integer DEFAULT 0, v_mobileno character varying DEFAULT ''::character varying, v_operatortype character varying DEFAULT ''::character varying, v_operatorname character varying DEFAULT ''::character varying, v_operatorcode character varying DEFAULT ''::character varying, v_operatorservice character varying DEFAULT ''::character varying, v_rechargeamount numeric DEFAULT 0, v_successurl character varying DEFAULT ''::character varying, v_failureurl character varying DEFAULT ''::character varying, v_inprocessurl character varying DEFAULT ''::character varying, v_cancelledurl character varying DEFAULT ''::character varying, INOUT v_transactionid character varying DEFAULT ''::character varying, INOUT v_stroutput character varying DEFAULT ''::character varying) RETURNS record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_customerwalletamount DECIMAL(18,2);
  v_transid VARCHAR(50);
  v_loginid VARCHAR(50);
  v_admincommission DECIMAL(18,2);
  v_adminsurcharge DECIMAL(18,2);
  v_did INT;
  v_trpid INT;
BEGIN
  BEGIN
  -- BEGIN TRAN (removed)
  v_customerwalletamount := 0;
  IF (v_clid <> 0) THEN
  IF (v_mobileno = '') THEN
  v_transactionid := '';
  v_stroutput := 'Mobile no should not be blank';
  -- COMMIT (removed)
  END IF;
  IF (v_operatortype = '') THEN
  v_transactionid := '';
  v_stroutput := 'Please select operator type';
  -- COMMIT (removed)
  RETURN;
  END IF;
  IF (v_rechargeamount = 0) THEN
  v_transactionid := '';
  v_stroutput := 'Please enter recharge amount';
  -- COMMIT (removed)
  RETURN;
  END IF;
  IF (v_rechargeamount < 0) THEN
  v_transactionid := '';
  v_stroutput := 'Please enter valid recharge amount';
  -- COMMIT (removed)
  RETURN;
  END IF;
  IF (v_clid <> 0 AND v_mobileno <> '') THEN
  IF EXISTS(SELECT 1 FROM tbl_customerlogin WHERE clid = v_clid AND active = 1) THEN
  SELECT COALESCE(availablebalance, 0) INTO v_customerwalletamount FROM tbl_customerwallet WHERE clid = v_clid;
  v_transid := '';
  v_loginid := '';
  v_transid := CAST(CAST(GEN_RANDOM_UUID() AS BYTEA(5)) AS BIGINT) % 1000000000 + 1000000000;
  INSERT INTO dbo.tbl_customer_postpaid_recharges (clid, mobileno, operatortype, operatorname, operatorcode, operatorservice, rechargeamount, transactionid, successurl, failureurl, inprocessurl, cancelledurl) VALUES (v_clid, v_mobileno, v_operatortype, v_operatorname, v_operatorcode, v_operatorservice, v_rechargeamount, v_transid, v_successurl, v_failureurl, v_inprocessurl, v_cancelledurl);
  v_admincommission := 0;
  v_adminsurcharge := 0;
  v_did := 0;
  v_trpid := 0;
  SELECT did INTO v_did FROM tbl_customerlogin WHERE clid = v_clid;
  SELECT trpid INTO v_trpid FROM tbl_reseller_purchased_packages WHERE did = v_did AND active = 1;
  IF EXISTS(SELECT 1 FROM tbl_reseller_wise_package_commission_settings WHERE did = v_did AND operatorcode = v_operatorcode) THEN
  IF (v_trpid = 1) THEN
  SELECT COALESCE(package1commission, 0) INTO v_admincommission FROM tbl_reseller_wise_package_commission_settings WHERE did = v_did AND operatorcode = v_operatorcode;
  END IF;
  IF (v_trpid = 2) THEN
  SELECT COALESCE(package2commission, 0) INTO v_admincommission FROM tbl_reseller_wise_package_commission_settings WHERE did = v_did AND operatorcode = v_operatorcode;
  END IF;
  IF (v_trpid = 3) THEN
  SELECT COALESCE(package3commission, 0) INTO v_admincommission FROM tbl_reseller_wise_package_commission_settings WHERE did = v_did AND operatorcode = v_operatorcode;
  END IF;
  IF (v_trpid = 4) THEN
  SELECT COALESCE(package4commission, 0) INTO v_admincommission FROM tbl_reseller_wise_package_commission_settings WHERE did = v_did AND operatorcode = v_operatorcode;
  END IF;
  SELECT COALESCE(adminsurcharge, 0) INTO v_adminsurcharge FROM tbl_reseller_wise_package_commission_settings WHERE did = v_did AND operatorcode = v_operatorcode;
  ELSE
  IF (v_trpid = 1) THEN
  SELECT COALESCE(package1commission, 0) INTO v_admincommission FROM tbl_default_package_commission_settings WHERE operatorcode = v_operatorcode;
  END IF;
  IF (v_trpid = 2) THEN
  SELECT COALESCE(package2commission, 0) INTO v_admincommission FROM tbl_default_package_commission_settings WHERE operatorcode = v_operatorcode;
  END IF;
  IF (v_trpid = 3) THEN
  SELECT COALESCE(package3commission, 0) INTO v_admincommission FROM tbl_default_package_commission_settings WHERE operatorcode = v_operatorcode;
  END IF;
  IF (v_trpid = 4) THEN
  SELECT COALESCE(package4commission, 0) INTO v_admincommission FROM tbl_default_package_commission_settings WHERE operatorcode = v_operatorcode;
  END IF;
  SELECT COALESCE(adminsurcharge, 0) INTO v_adminsurcharge FROM tbl_default_package_commission_settings WHERE operatorcode = v_operatorcode;
  END IF;
  UPDATE dbo.tbl_customer_postpaid_recharges SET admincommission = v_admincommission, adminsurcharge = v_adminsurcharge WHERE clid = v_clid AND operatorcode = v_operatorcode AND transactionid = v_transid;
  v_transactionid := v_transid;
  v_stroutput := 'SUCCESS';
  -- COMMIT (removed)
  END IF;
  END IF;
  END IF;
  EXCEPTION WHEN OTHERS THEN
  IF (0 <> 0) THEN
  PERFORM dbo.sp_errorlog();
  v_transactionid := '';
  v_stroutput := 'Error in request';
  -- ROLLBACK (removed)
  END IF;
  END;
END;
$$;


