  SELECT COALESCE(availablebalance, 0) INTO v_customerwalletamount FROM tbl_customerwallet WHERE clid = v_clid;
  v_transid := '';
  v_loginid := '';
  v_transid := CAST(CAST(GEN_RANDOM_UUID() AS BYTEA(5)) AS BIGINT) % 1000000000 + 1000000000;
  INSERT INTO dbo.tbl_customer_prepaid_recharges (clid, mobileno, operatortype, operatorname, operatorcode, operatorservice, rechargeamount, transactionid, successurl, failureurl, inprocessurl, cancelledurl) VALUES (v_clid, v_mobileno, v_operatortype, v_operatorname, v_operatorcode, v_operatorservice, v_rechargeamount, v_transid, v_successurl, v_failureurl, v_inprocessurl, v_cancelledurl);
