  IF EXISTS(SELECT 1 FROM tbl_default_package_commission_settings WHERE operatorcode = v_operatorcode) THEN
  SELECT COALESCE(commission, 0), COALESCE(surcharge, 0) INTO v_admincommission, v_adminsurcharge FROM tbl_vendor_recharge_commission_structure WHERE operatorcode = v_operatorcode;
  IF (v_trpid = 1) THEN
  SELECT COALESCE(actualpercentagepack1, 0), COALESCE(adminsurcharge, 0) INTO v_resellercommision, v_resellersurcharge FROM tbl_default_package_commission_settings WHERE operatorcode = v_operatorcode;
