--
-- Name: usp_customer_recharge_requests_mobile(integer, character varying, character varying, character varying, character varying, character varying, numeric, character varying, character varying, character varying, character varying, character varying, character varying, character varying, numeric, numeric); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_customer_recharge_requests_mobile(v_clid integer DEFAULT 0, v_mobileno character varying DEFAULT ''::character varying, v_operatortype character varying DEFAULT ''::character varying, v_operatorname character varying DEFAULT ''::character varying, v_operatorcode character varying DEFAULT ''::character varying, v_operatorservice character varying DEFAULT ''::character varying, v_rechargeamount numeric DEFAULT 0, v_successurl character varying DEFAULT ''::character varying, v_failureurl character varying DEFAULT ''::character varying, v_inprocessurl character varying DEFAULT ''::character varying, v_cancelledurl character varying DEFAULT ''::character varying, INOUT v_transactionid character varying DEFAULT ''::character varying, INOUT v_stroutput character varying DEFAULT ''::character varying, v_servicetype character varying DEFAULT ''::character varying, INOUT v_getshoppingwallet numeric DEFAULT 0, INOUT v_getdistributorbalance numeric DEFAULT 0) RETURNS record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_customerwalletamount DECIMAL(18,2);
  v_did INT;
  v_shoppingwallet DECIMAL(18,8);
  v_pmid int;
  v_distributorbalance decimal(18,8);
  v_billamount DECIMAL(18,8);
  v_orderid VARCHAR(500);
  v_totalpaidamount DECIMAL(18,8);
  v_oorid INT;
  v_packageamount decimal(18,2);
  v_adminsurcharge decimal(18,2);
  v_trpid int;
  v_packagename varchar(150);
  v_defaultvalue int;
  v_transid VARCHAR(50);
  v_loginid VARCHAR(50);
BEGIN
  BEGIN
  -- BEGIN TRAN (removed)
  v_customerwalletamount := 0;
  v_did := 0;
  v_shoppingwallet := 0;
  v_pmid := 0;
  v_distributorbalance := 0;
  v_billamount := 0;
  v_orderid := '';
  v_totalpaidamount := 0;
  v_packageamount := 0;
  v_adminsurcharge := 0;
  v_trpid := 0;
  v_packagename := '';
  v_defaultvalue := 0;
  IF (v_operatortype = 'MOBILE') THEN
  v_operatortype := 'PREPAID';
  END IF;
  SELECT did INTO v_did FROM tbl_customerlogin WHERE clid = v_clid;
  SELECT trpid INTO v_trpid FROM tbl_reseller_purchased_packages WHERE did = v_did;
  SELECT packagename INTO v_packagename FROM tbl_reseller_packages;
  IF EXISTS(SELECT 1 FROM tbl_reseller_wise_package_commission_settings WHERE did = v_did) THEN
  v_defaultvalue := 2;
  ELSE
  v_defaultvalue := 1;
  END IF;
  IF (v_packagename = 'Free' AND v_defaultvalue = 1) THEN
  SELECT package1commission, adminsurcharge INTO v_packageamount, v_adminsurcharge FROM tbl_default_package_commission_settings WHERE operatorname = v_operatorname AND operatorcode = v_operatorcode AND providername = v_operatortype;
  ELSE
  IF (v_packagename = 'Package 1' AND v_defaultvalue = 2) THEN
  SELECT package1commission, adminsurcharge INTO v_packageamount, v_adminsurcharge FROM tbl_reseller_wise_package_commission_settings WHERE operatorname = v_operatorname AND operatorcode = v_operatorcode AND providername = v_operatortype AND did = v_did;
  ELSE
  IF (v_packagename = 'Package 2' AND v_defaultvalue = 2) THEN
  SELECT package2commission, adminsurcharge INTO v_packageamount, v_adminsurcharge FROM tbl_reseller_wise_package_commission_settings WHERE operatorname = v_operatorname AND operatorcode = v_operatorcode AND providername = v_operatortype AND did = v_did;
  ELSE
  IF (v_packagename = 'Package 3' AND v_defaultvalue = 2) THEN
  SELECT package3commission, adminsurcharge INTO v_packageamount, v_adminsurcharge FROM tbl_reseller_wise_package_commission_settings WHERE operatorname = v_operatorname AND operatorcode = v_operatorcode AND providername = v_operatortype AND did = v_did;
  ELSE
  v_packageamount := 0;
  v_adminsurcharge := 0;
  END IF;
  END IF;
  END IF;
  END IF;
  v_getshoppingwallet := v_shoppingwallet;
  v_getdistributorbalance := v_distributorbalance;
  v_transid := '';
  v_loginid := '';
  v_transid := CAST(CAST(GEN_RANDOM_UUID() AS BYTEA(5)) AS BIGINT) % 1000000000 + 1000000000;
  v_transactionid := v_transid;
  IF (v_clid <> 0) THEN
  IF (v_mobileno = '') THEN
  v_transactionid := '';
  v_stroutput := 'Mobile no should not be blank';
  -- COMMIT (removed)
  END IF;
  IF (v_operatortype = '') THEN
  v_transactionid := '';
  v_stroutput := 'Please select operator type';
  -- COMMIT (removed)
  RETURN;
  END IF;
  IF (v_rechargeamount = 0) THEN
  v_transactionid := '';
  v_stroutput := 'Please enter recharge amount';
  -- COMMIT (removed)
  RETURN;
  END IF;
  IF (v_rechargeamount < 0) THEN
  v_transactionid := '';
  v_stroutput := 'Please enter valid recharge amount';
  -- COMMIT (removed)
  RETURN;
  END IF;
  SELECT pmid INTO v_pmid FROM tbl_distributor WHERE did = v_did;
  SELECT COALESCE(available_wallet, 0) INTO v_distributorbalance FROM tbl_distributor_prepaid_setting WHERE pmid = v_pmid;
  SELECT COALESCE(availablebalance, 0) INTO v_shoppingwallet FROM tbl_customerwallet WHERE clid = v_clid;
  IF (v_clid <> 0 AND v_mobileno <> '') THEN
  IF EXISTS(SELECT 1 FROM tbl_customerlogin WHERE clid = v_clid AND active = 1) THEN
  SELECT COALESCE(availablebalance, 0) INTO v_customerwalletamount FROM tbl_customerwallet WHERE clid = v_clid;
  IF (v_operatortype = 'DTH') THEN
  INSERT INTO dbo.tbl_customer_dth_recharges (clid, mobileno, operatortype, operatorname, operatorcode, operatorservice, rechargeamount, transactionid, successurl, failureurl, inprocessurl, cancelledurl, isandroidorweb, admincommission, adminsurcharge) VALUES (v_clid, v_mobileno, v_operatortype, v_operatorname, v_operatorcode, v_operatorservice, v_rechargeamount, v_transid, v_successurl, v_failureurl, v_inprocessurl, v_cancelledurl, 1, v_packageamount, v_adminsurcharge);
  ELSE
  IF (v_operatortype = 'ELECTRICITY') THEN
  INSERT INTO dbo.tbl_customer_electricity_recharges (clid, mobileno, operatortype, operatorname, operatorcode, operatorservice, rechargeamount, transactionid, successurl, failureurl, inprocessurl, cancelledurl, isandroidorweb, admincommission, adminsurcharge) VALUES (v_clid, v_mobileno, v_operatortype, v_operatorname, v_operatorcode, v_operatorservice, v_rechargeamount, v_transid, v_successurl, v_failureurl, v_inprocessurl, v_cancelledurl, 1, v_packageamount, v_adminsurcharge);
  ELSE
  IF (v_operatortype = 'GAS') THEN
  INSERT INTO dbo.tbl_customer_gas_recharges (clid, mobileno, operatortype, operatorname, operatorcode, operatorservice, rechargeamount, transactionid, successurl, failureurl, inprocessurl, cancelledurl, isandroidorweb, admincommission, adminsurcharge) VALUES (v_clid, v_mobileno, v_operatortype, v_operatorname, v_operatorcode, v_operatorservice, v_rechargeamount, v_transid, v_successurl, v_failureurl, v_inprocessurl, v_cancelledurl, 1, v_packageamount, v_adminsurcharge);
  ELSE
  IF (v_operatortype = 'POSTPAID') THEN
  INSERT INTO dbo.tbl_customer_postpaid_recharges (clid, mobileno, operatortype, operatorname, operatorcode, operatorservice, rechargeamount, transactionid, successurl, failureurl, inprocessurl, cancelledurl, isandroidorweb, admincommission, adminsurcharge) VALUES (v_clid, v_mobileno, v_operatortype, v_operatorname, v_operatorcode, v_operatorservice, v_rechargeamount, v_transid, v_successurl, v_failureurl, v_inprocessurl, v_cancelledurl, 1, v_packageamount, v_adminsurcharge);
  ELSE
  IF (v_operatortype = 'PREPAID') THEN
  INSERT INTO dbo.tbl_customer_prepaid_recharges (clid, mobileno, operatortype, operatorname, operatorcode, operatorservice, rechargeamount, transactionid, successurl, failureurl, inprocessurl, cancelledurl, isandroidorweb, admincommission, adminsurcharge) VALUES (v_clid, v_mobileno, v_operatortype, v_operatorname, v_operatorcode, v_operatorservice, v_rechargeamount, v_transid, v_successurl, v_failureurl, v_inprocessurl, v_cancelledurl, 1, v_packageamount, v_adminsurcharge);
  ELSE
  v_transid := '';
  END IF;
  END IF;
  END IF;
  END IF;
  END IF;
  v_getshoppingwallet := v_shoppingwallet;
  v_getdistributorbalance := v_distributorbalance;
  v_stroutput := 'SUCCESS';
  -- COMMIT (removed)
  END IF;
  END IF;
  END IF;
  EXCEPTION WHEN OTHERS THEN
  IF (0 <> 0) THEN
  PERFORM dbo.sp_errorlog();
  v_transactionid := '';
  v_stroutput := 'Error in request';
  -- ROLLBACK (removed)
  END IF;
  END;
END;
$$;


--
-- Name: usp_customer_socialregistration(character varying, character varying, character varying, integer, character varying, character varying, character varying, character varying, character varying, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_customer_socialregistration(v_emailid character varying DEFAULT ''::character varying, v_fname character varying DEFAULT ''::character varying, v_lname character varying DEFAULT ''::character varying, v_did integer DEFAULT 0, v_password character varying DEFAULT ''::character varying, v_ip character varying DEFAULT ''::character varying, v_loginid character varying DEFAULT ''::character varying, v_counrty character varying DEFAULT ''::character varying, INOUT v_intresult character varying DEFAULT ''::character varying, v_issociallogin integer DEFAULT 0) RETURNS character varying
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_duplicateemailid INT;
  v_cid INT;
  v_regno INT;
BEGIN
  -- BEGIN TRAN (removed)
  v_duplicateemailid := 0;
  v_cid := 0;
  v_regno := 0;
  SELECT (SELECT COUNT(1) FROM tbl_customerlogin WHERE emailid = v_emailid AND did = v_did) INTO v_duplicateemailid;
  IF (v_duplicateemailid > 0) THEN
  v_intresult := '1';
  -- COMMIT (removed)
  RETURN;
  ELSE
  IF EXISTS(SELECT COALESCE(cid, '96') FROM country WHERE countryname = v_counrty AND cactive = 1) THEN
  IF (v_cid = 0) THEN
  SELECT COALESCE(cid, '96') INTO v_cid FROM country WHERE countryname = v_counrty AND cactive = 1;
  END IF;
  ELSE
  IF (v_cid = 0) THEN
  v_cid := 96;
  END IF;
  END IF;
  INSERT INTO customer_login_temp (loginid, password, active, doc, cid, ipaddress, emailid, userid, did, refral_id) VALUES (v_loginid, v_password, 1, dbo.FUN_GETCURRENTDATE(), v_cid, v_ip, v_emailid, v_loginid, v_did, v_loginid);
  INSERT INTO tbl_customerlogin (pmid, loginid, password, tpassword, active, doc, cid, ipaddress, fname, lname, emailid, userid, did, issociallogin, intro_plid, currency) VALUES (0, v_loginid, v_password, v_password, 1, dbo.FUN_GETCURRENTDATE(), v_cid, v_ip, v_fname, v_lname, v_emailid, v_loginid, v_did, v_issociallogin, 0, 'INR');
  SELECT IDENT_CURRENT('TBL_CUSTOMERLOGIN') INTO v_regno;
  UPDATE tbl_customerlogin SET regno = v_regno WHERE clid = v_regno;
  v_intresult := '2';
  -- COMMIT (removed)
  END IF;
  IF (0 > 0) THEN
  v_intresult := '0';
  -- ROLLBACK (removed)
  RETURN;
  END IF;
END;
$$;


--
-- Name: usp_customer_transfer_bank_history(integer, integer, character varying, character varying, character varying, character varying, integer, integer, character varying, bigint, bigint); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_customer_transfer_bank_history(v_startrowindex integer DEFAULT 1, v_maxrows integer DEFAULT 100, v_searchfield character varying DEFAULT ''::character varying, v_searchvalue character varying DEFAULT ''::character varying, v_fromdate character varying DEFAULT ''::character varying, v_todate character varying DEFAULT ''::character varying, v_totalcount integer DEFAULT 0, v_mode integer DEFAULT 0, v_requestid character varying DEFAULT ''::character varying, v_plid bigint DEFAULT 0, v_sumofdata bigint DEFAULT 0) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_minindex int;
  v_maxindex int;
  v_query text;
BEGIN
  v_minindex := (v_startrowindex - 1) * v_maxrows + 1;
  v_maxindex := v_startrowindex * v_maxrows;
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp (ROWNUMBER int GENERATED BY DEFAULT AS IDENTITY, 
	TCTTB BIGINT,       
	FNAME varchar(500),      
	PHONE varchar(500),	
	EMAILID varchar(500),	
	WITHDRAWALAMOUNT DECIMAL(18,2),	
	TRANSACTIONID varchar(500),	
	WITHDRAWALDATE timestamp,
	ACCOUNTHOLDERNAME varchar(500),	
	ACCOUNTNO varchar(500),
	BANKNAME varchar(500),	
	IFSC varchar(500),
	Loginid varchar(50),
	CLID BIGINT,
	Status int,
	BRANCHNAME VARCHAR(50),
	RESELLERNAME VARCHAR(100)) ON COMMIT DROP;
  v_query := 'insert into #temp SELECT CTB.TCTTB,CL.FNAME,CL.PHONE,CL.EMAILID,CTBH.WITHDRAWALAMOUNT,CTBH.TRANSACTIONID,CTB.WITHDRAWALDATE,CTBH.ACCOUNTHOLDERNAME,CTBH.ACCOUNTNO,CTBH.BANKNAME,
CTBH.IFSC,CL.Loginid,CTB.CLID,CTB.Status,CTBH.BRANCHNAME,DM.COMPANYNAME
 FROM TBL_CUSTOMER_TRANSFERTOBANK CTB  
 JOIN TBL_CUSTOMER_TRANSFERTOBANKHISTORY CTBH ON CTB.TRANSACTIONID=CTBH.TRANSACTIONID
LEFT JOIN TBL_CUSTOMERLOGIN CL ON CL.CLID=CTB.CLID 
LEFT JOIN DISTRIBUTOR_MASTER DM ON CL.DID=DM.PLID
WHERE CTB.Status=0 AND CTB.ISPAID=0 ';
  IF ((v_fromdate <> '') AND (v_todate = '')) THEN
  v_query := v_query || ' AND CONVERT(DATE, CTB.WITHDRAWALDATE, 105) BETWEEN  CONVERT(DATE, ''' || v_fromdate || ''', 105) AND  CONVERT(DATE, DBO.FUN_GETCURRENTDATE(), 105)';
  END IF;
  IF ((v_fromdate = '') AND (v_todate <> '')) THEN
  v_query := v_query || 'AND CONVERT(DATE, CTB.WITHDRAWALDATE, 105) BETWEEN  CONVERT(DATE, ''' || v_todate || ''', 105) AND  CONVERT(DATE, DBO.FUN_GETCURRENTDATE(), 105)';
  END IF;
  IF ((v_fromdate <> '') AND (v_todate <> '')) THEN
  v_query := v_query || 'AND CONVERT(DATE, CTB.WITHDRAWALDATE, 105) BETWEEN CONVERT(DATE, ''' || v_fromdate || ''', 105) AND  CONVERT(DATE, ''' || v_todate || ''', 105)';
  END IF;
  IF (v_searchfield = 'PHONE') THEN
  v_query := v_query || ' AND PL.PHONE= ''' || v_searchvalue || ''' ';
  END IF;
  IF (v_searchfield = 'EMAILID') THEN
  v_query := v_query || ' AND PL.EMAILID= ''' || v_searchvalue || ''' ';
  END IF;
  IF (v_searchfield = 'TRANSACTIONID') THEN
  v_query := v_query || ' AND CTBH.TRANSACTIONID= ''' || v_searchvalue || ''' ';
  END IF;
  v_query := v_query || ' ORDER BY CTB.WITHDRAWALDATE DESC';
  EXECUTE v_query;
  RAISE NOTICE '%', v_query;
  RETURN QUERY SELECT * FROM tmp_temp WHERE rownumber BETWEEN v_minindex AND v_maxindex;
  IF (v_mode = 1) THEN
  SELECT COUNT(rownumber) INTO v_totalcount FROM tmp_temp;
  INSERT INTO tbl_downloaded_bank_excel_customer_history (accountholdername, bankname, accountno, ifsccode, branchname, payoutamount, downloadeddate, requestid) SELECT accountholdername, bankname, accountno, ifsc, branchname, withdrawalamount, dbo.FUN_GETCURRENTDATE(), v_requestid FROM tmp_temp;
  INSERT INTO tbl_downloaded_bank_excel_customer VALUES (v_plid, '', v_requestid, v_totalcount, 0, 1, dbo.FUN_GETCURRENTDATE());
  END IF;
  SELECT COALESCE(COUNT(rownumber), 0) INTO v_totalcount FROM tmp_temp;
  SELECT COALESCE(SUM(withdrawalamount), 0) INTO v_sumofdata FROM tmp_temp;
  DROP TABLE IF EXISTS tmp_temp;
  -- SET option (removed)
END;
$$;


--
-- Name: usp_customer_transfertobank(bigint, numeric, character varying, character varying, character varying, character varying, character varying, character varying, character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_customer_transfertobank(v_clid bigint DEFAULT 31, v_amount numeric DEFAULT 100, v_accountholdername character varying DEFAULT 'Ashish Kumar sharma'::character varying, v_accountno character varying DEFAULT '100030514454'::character varying, v_bankname character varying DEFAULT 'State Bank Of India'::character varying, v_branchname character varying DEFAULT 'Noida'::character varying, v_ifsc character varying DEFAULT 'SBIN0005936'::character varying, INOUT v_stroutput character varying DEFAULT ''::character varying, INOUT v_transactionid character varying DEFAULT ''::character varying) RETURNS record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_loginid VARCHAR(50);
  v_availablebalance DECIMAL(18,2);
  v_transid VARCHAR(50);
  v_tcttbid INT;
  v_oldbalance DECIMAL(18,2);
BEGIN
  BEGIN
  -- BEGIN TRAN (removed)
  -- SET option (removed)
  -- SET option (removed)
  IF (v_amount <= 0) THEN
  v_stroutput := 'Invalid Amount';
  -- COMMIT (removed)
  RETURN;
  END IF;
  IF (v_accountno = '' OR v_bankname = '' OR v_ifsc = '') THEN
  v_stroutput := 'Invalid Bank Details';
  -- COMMIT (removed)
  RETURN;
  END IF;
  v_loginid := '';
  v_availablebalance := 0;
  v_transid := '';
  v_tcttbid := 0;
  IF (v_clid > 0) THEN
  IF EXISTS(SELECT 1 FROM dbo.tbl_customerlogin WHERE clid = v_clid AND active = 1) THEN
  IF EXISTS(SELECT 1 FROM dbo.tbl_customerwallet WHERE clid = v_clid) THEN
  SELECT loginid INTO v_loginid FROM dbo.tbl_customerlogin WHERE clid = v_clid;
  SELECT COALESCE(availablebalance, 0) INTO v_availablebalance FROM dbo.tbl_customerwallet WHERE clid = v_clid;
  IF (v_availablebalance > 0 AND v_amount <= v_availablebalance) THEN
  v_transid := CAST(CAST(GEN_RANDOM_UUID() AS BYTEA(5)) AS BIGINT) % 1000000000 + 1000000000;
  IF EXISTS(SELECT 1 FROM dbo.tbl_customer_transfertobank WHERE transactionid = v_transid) THEN
  v_transid := CAST(CAST(GEN_RANDOM_UUID() AS BYTEA(5)) AS BIGINT) % 1000000000 + 1000000000;
  END IF;
  INSERT INTO dbo.tbl_customer_transfertobank (clid, loginid, crdrtype, withdrawalamount, admincharges, tds, payableamount, withdrawaldate, status, remarkes, transactionid, adminremarks, approveddate, processing_fees, ispaid, paiddate) VALUES (v_clid, v_loginid, 'DR', v_amount, 0, 0, v_amount, dbo.FUN_GETCURRENTDATE(), 0, '', v_transid, '', dbo.FUN_GETCURRENTDATE(), 0.00, 0, dbo.FUN_GETCURRENTDATE());
  v_tcttbid := IDENT_CURRENT('DBO.TBL_CUSTOMER_TRANSFERTOBANK');
  INSERT INTO dbo.tbl_customer_transfertobankhistory (tcttbid, clid, withdrawalamount, withdrawaldate, accountholdername, accountno, bankname, branchname, ifsc, transactionid) VALUES (v_tcttbid, v_clid, v_amount, dbo.FUN_GETCURRENTDATE(), v_accountholdername, v_accountno, v_bankname, v_branchname, v_ifsc, v_transid);
  v_oldbalance := 0;
  SELECT COALESCE(availablebalance, 0) INTO v_oldbalance FROM tbl_customerwallet WHERE clid = v_clid AND loginid = v_loginid;
  UPDATE tbl_customerwallet SET transfertobank = (COALESCE(transfertobank, 0) + v_amount), totalbalance = (COALESCE(availablebalance, 0) - v_amount), availablebalance = (COALESCE(availablebalance, 0) - v_amount), updateddate = dbo.FUN_GETCURRENTDATE() WHERE clid = v_clid AND loginid = v_loginid;
  INSERT INTO tbl_customerwallet_statements (clid, processdate, crdrtype, cramt, dramt, old_balance, balance, remarks, traceno, status) VALUES (v_clid, dbo.FUN_GETCURRENTDATE(), 'DR', 0.00, v_amount, v_oldbalance, (v_oldbalance - v_amount), 'Wallet Deduct For Transfer To Bank For Amount: ''' || CAST(v_amount AS VARCHAR(50)) || '''', v_transid, 1);
  IF NOT EXISTS(SELECT 1 FROM tbl_customer_bank_accounts WHERE ifsccode = v_ifsc AND active = 1) THEN
  INSERT INTO tbl_customer_bank_accounts (clid, accountholdername, accountno, bankname, branchname, ifsccode, active, create_date) VALUES (v_clid, v_accountholdername, v_accountno, v_bankname, v_branchname, v_ifsc, 1, dbo.FUN_GETCURRENTDATE());
  END IF;
  ELSE
  v_stroutput := 'Insufficient Balance';
  -- COMMIT (removed)
  RETURN;
  END IF;
  ELSE
  v_stroutput := 'Insufficient Balance';
  -- COMMIT (removed)
  RETURN;
  END IF;
  ELSE
  v_stroutput := 'Invalid customer';
  -- COMMIT (removed)
  RETURN;
  END IF;
  -- COMMIT (removed)
  v_stroutput := 'Success';
  v_transactionid := v_transid;
  END IF;
  EXCEPTION WHEN OTHERS THEN
  IF (0 > 0) THEN
  v_stroutput := 'Error';
  PERFORM dbo.sp_errorlog();
  -- ROLLBACK (removed)
  RETURN;
  END IF;
  END;
END;
$$;


--
-- Name: usp_customer_withdrawalhistory_report(integer, integer, character varying, character varying, character varying, character varying, character varying, character varying, integer, numeric, numeric, numeric, character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_customer_withdrawalhistory_report(v_startrowindex integer DEFAULT 1, v_maxrows integer DEFAULT 100, v_searchfield character varying DEFAULT ''::character varying, v_searchvalue character varying DEFAULT ''::character varying, v_fromdate character varying DEFAULT ''::character varying, v_todate character varying DEFAULT ''::character varying, v_transactiontype character varying DEFAULT ''::character varying, v_status character varying DEFAULT ''::character varying, INOUT v_totalcount integer DEFAULT 0, INOUT v_totalwithdrawal numeric DEFAULT 0, INOUT v_totaltds numeric DEFAULT 0, INOUT v_totaladmincharges numeric DEFAULT 0, v_orderbydate character varying DEFAULT ''::character varying) RETURNS record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_minindex INT;
  v_maxindex INT;
  v_condition text;
  v_condition1 varchar(500);
  v_queryresult text;
  v_countquery text;
  v_tdsquery text;
  v_adminchargequery text;
  v_totalamount text;
  v_maxregno text;
  v_parmdefinition text;
  v_parmdefinition1 text;
  v_parmdefinitiontds text;
  v_parmdefinitionadmincharge text;
BEGIN
  v_condition := '';
  v_condition1 := '';
  v_queryresult := '';
  v_countquery := '';
  v_tdsquery := '';
  v_adminchargequery := '';
  v_totalamount := '';
  v_maxregno := '';
  v_minindex := (v_startrowindex - 1) * v_maxrows + 1;
  v_maxindex := v_startrowindex * v_maxrows;
  v_queryresult := 'SELECT ROW_NUMBER() OVER(ORDER BY TW.TCTTB desc) AS ROWNUMBER, ISNULL(MM.USERNAME,'''') AS USERNAME,ISNULL(MM.FNAME,'''')+''''+ ISNULL(MM.LNAME,'''') AS NAME,
	ISNULL(TW.CRDRTYPE,'''') AS CRDRTYPE,ISNULL(TW.WITHDRAWALAMOUNT,0) AS WITHDRAWALAMT,
	ISNULL(TW.ADMINCHARGES,0) AS ADMINCHARGE, ISNULL(TW.TDS,0) AS TDS,ISNULL(TW.STATUS,'''')AS STATUS,
	 ISNULL(MM.EMAILID,'''') AS EMAILID, ISNULL(MM.Phone,'''') AS MOBILE, ISNULL(MM.PANNO,'''') AS PANNO,
	ISNULL(TW.WITHDRAWALDATE,'''') AS DATE,ISNULL(WH.ACCOUNTHOLDERNAME,'''') AS ACCOUNTHOLDERNAME,ISNULL(WH.ACCOUNTNO,'''') AS ACCOUNTNO,
	ISNULL(WH.BANKNAME,'''') AS BANKNAME,ISNULL(WH.BRANCHNAME,'''') AS BRANCHNAME,ISNULL(WH.IFSC,'''') AS IFSC,ISNULL(TP.PAYMODE,'''') as Paymode,DM.COMPANYNAME as RESELLERNAME
	INTO #TEMPWIHTHDRAWALHISTORY FROM TBL_CUSTOMER_TRANSFERTOBANK TW 
	INNER JOIN TBL_CUSTOMER_TRANSFERTOBANKHISTORY WH ON TW.TCTTB=WH.TCTTBID
	INNER JOIN TBL_CUSTOMERLOGIN MM ON TW.CLID=MM.CLID
	LEFT JOIN TBL_PAYMODE TP ON TW.PAYMODE=TP.PMOID
	LEFT JOIN DISTRIBUTOR_MASTER DM ON MM.DID=DM.PLID
	 WHERE TW.STATUS IN (1,3) ';
  v_parmdefinition := N'@TOTALCOUNT NVARCHAR(1000) OUTPUT';
  v_countquery := N'SELECT @TOTALCOUNT =COUNT(1) FROM TBL_CUSTOMER_TRANSFERTOBANK TW INNER JOIN TBL_CUSTOMERLOGIN MM ON TW.CLID=MM.CLID  WHERE 1=1 AND TW.STATUS IN (1,3)';
  v_parmdefinition1 := N' @TOTALWITHDRAWAL NVARCHAR(1000) OUTPUT';
  v_totalamount := N'SELECT @TOTALWITHDRAWAL= ISNULL(SUM(CAST(TW.WITHDRAWALAMOUNT AS DECIMAL(18,8))),0)  FROM  TBL_CUSTOMER_TRANSFERTOBANK TW  
	INNER JOIN TBL_CUSTOMER_TRANSFERTOBANKHISTORY WH ON TW.TCTTB=WH.TCTTBID INNER JOIN TBL_CUSTOMERLOGIN MM ON TW.CLID=MM.CLID WHERE 1=1 AND TW.STATUS IN (1,3)';
  v_parmdefinitiontds := N' @TOTALTDS NVARCHAR(1000) OUTPUT';
  v_tdsquery := N'SELECT @TOTALTDS= ISNULL(SUM(CAST(TW.TDS AS DECIMAL(18,8))),0)  FROM  TBL_CUSTOMER_TRANSFERTOBANK TW   
	INNER JOIN TBL_CUSTOMER_TRANSFERTOBANKHISTORY WH ON TW.TCTTB=WH.TCTTBID INNER JOIN TBL_CUSTOMERLOGIN MM ON TW.CLID=MM.CLID WHERE 1=1  AND TW.STATUS IN (1.3)';
  v_parmdefinitionadmincharge := N' @TOTALADMINCHARGES NVARCHAR(1000) OUTPUT';
  v_adminchargequery := N'SELECT @TOTALADMINCHARGES= ISNULL(SUM(CAST(TW.ADMINCHARGES AS DECIMAL(18,8))),0)  FROM  TBL_CUSTOMER_TRANSFERTOBANK TW  
	INNER JOIN TBL_CUSTOMER_TRANSFERTOBANKHISTORY WH ON TW.TCTTB=WH.TCTTBID INNER JOIN TBL_CUSTOMERLOGIN MM ON TW.CLID=MM.CLID WHERE 1=1 AND TW.STATUS IN (1,3)';
  IF (v_searchfield = 'USERNAME') THEN
  v_condition := v_condition || ' AND MM.USERNAME = ''' || CAST(v_searchvalue AS VARCHAR(100)) || ''' ';
  END IF;
  IF (v_searchfield = 'NAME') THEN
  v_condition := v_condition || ' AND ISNULL(MM.FNAME,'''')+''''+ISNULL(MM.LNAME,'''') = ''' || CAST(v_searchvalue AS VARCHAR(100)) || ''' ';
  END IF;
  IF (v_transactiontype <> '') THEN
  v_condition := v_condition || ' AND TW.CRDRTYPE = ''' || CAST(v_transactiontype AS VARCHAR(100)) || ''' ';
  END IF;
  IF (v_status <> '') THEN
  v_condition := v_condition || ' AND TW.STATUS = ''' || CAST(v_status AS VARCHAR(100)) || ''' ';
  END IF;
  IF ((v_fromdate <> '') AND (v_todate = '')) THEN
  v_condition := v_condition || ' AND CONVERT(VARCHAR(15), TW.DATE, 105) =  CONVERT(VARCHAR(15), ''' || v_fromdate || ''', 105) ';
  END IF;
  IF ((v_fromdate = '') AND (v_todate <> '')) THEN
  v_condition := v_condition || ' AND CONVERT(VARCHAR(15),TW.DATE, 105) =  CONVERT(VARCHAR(15), ''' || v_todate || ''', 105) ';
  END IF;
  IF ((v_fromdate <> '') AND (v_todate <> '')) THEN
  v_condition := v_condition || ' AND CONVERT(VARCHAR(15), TW.DATE, 105) BETWEEN CONVERT(VARCHAR(15), ''' || v_fromdate || ''', 105) AND CONVERT(VARCHAR(15), ''' || v_todate || ''', 105)';
  END IF;
  IF (v_orderbydate = 'ASC') THEN
  v_condition1 := v_condition1 || ' ORDER BY DATE ASC';
  ELSE
  v_condition1 := v_condition1 || ' ORDER BY DATE DESC';
  END IF;
  v_queryresult := v_queryresult || v_condition || v_condition1 || ' ;SELECT  *  FROM #TEMPWIHTHDRAWALHISTORY WHERE ROWNUMBER BETWEEN ' || CAST(v_minindex AS text) || ' AND ' || CAST(v_maxindex AS text) || ' ' || v_condition1 || '';
  v_countquery := v_countquery || v_condition;
  v_totalamount := v_totalamount || v_condition;
  v_adminchargequery := v_adminchargequery || v_condition;
  v_tdsquery := v_tdsquery || v_condition;
  EXECUTE v_queryresult;
  RAISE NOTICE '%', v_queryresult;
  EXECUTE v_totalamount;
  EXECUTE v_tdsquery;
  EXECUTE v_adminchargequery;
  EXECUTE v_countquery;
END;
$$;


--
-- Name: usp_customermlmwallet(integer, integer, character varying, character varying, character varying, character varying, integer, integer, numeric, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_customermlmwallet(v_startrowindex integer DEFAULT 1, v_maxrows integer DEFAULT 100, v_searchfield character varying DEFAULT ''::character varying, v_searchvalue character varying DEFAULT ''::character varying, v_fromdate character varying DEFAULT ''::character varying, v_todate character varying DEFAULT ''::character varying, v_did integer DEFAULT 8, v_totalcount integer DEFAULT 0, v_totalwallet numeric DEFAULT 0, v_balance integer DEFAULT 1) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_minindex int;
  v_maxindex int;
  v_query text;
BEGIN
  v_minindex := (v_startrowindex - 1) * v_maxrows + 1;
  v_maxindex := v_startrowindex * v_maxrows;
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp (rownumber int GENERATED BY DEFAULT AS IDENTITY,        
	CLID BIGINT,         
	UPDATEDDATE  varchar(500),	
    TOTALBALANCE DECIMAL(18,2),
	AVAILABLEBALANCE	DECIMAL(18,2),
    DID  BIGINT,
	NAME varchar(500),				         
    EMAILID  varchar(500),						         
    PHONE varchar(500),
	LOGINID varchar(500)) ON COMMIT DROP;
  v_query := 'insert into #temp SELECT isnull(CW.CLID,0),ISNULL(CONVERT(VARCHAR(20), CW.UPDATEDDATE),''N/A'') AS UPDATEDDATE,
		 isnull(CW.TOTALBALANCE,0),isnull(CW.AVAILABLEBALANCE,0),isnull(CL.DID,0),isnull((CL.FNAME+CL.LNAME),''N/A'') AS NAME,isnull(CL.EMAILID,''''),isnull(CL.PHONE,''''),ISNULL(CL.LOGINID,'''')
		 FROM TBL_CUSTOMERLOGIN CL   inner JOIN TBL_CUSTOMERMLMWALLET CW on CL.CLID=CW.CLID WHERE 1=1';
  IF ((v_fromdate <> '') AND (v_todate = '')) THEN
  v_query := v_query || ' AND CONVERT(VARCHAR(20), CW.UPDATEDDATE, 106) BETWEEN  CONVERT(VARCHAR(20), ''' || v_fromdate || ''', 106) AND  CONVERT(VARCHAR(20), DBO.FUN_GETCURRENTDATE(), 106)';
  END IF;
  IF ((v_fromdate = '') AND (v_todate <> '')) THEN
  v_query := v_query || 'AND CONVERT(VARCHAR(20), CW.UPDATEDDATE, 106) BETWEEN  CONVERT(VARCHAR(20), ''' || v_todate || ''', 106) AND  CONVERT(VARCHAR(20), DBO.FUN_GETCURRENTDATE(), 106)';
  END IF;
  IF ((v_fromdate <> '') AND (v_todate <> '')) THEN
  v_query := v_query || 'AND CONVERT(VARCHAR(20), CW.UPDATEDDATE, 106) BETWEEN CONVERT(VARCHAR(20), ''' || v_fromdate || ''', 106) AND  CONVERT(VARCHAR(20), ''' || v_todate || ''', 106)';
  END IF;
  IF (v_did > 0) THEN
  v_query := v_query || ' AND cl.did=' || CAST(v_did AS VARCHAR(20)) || '';
  END IF;
  IF (v_searchfield = 'LOGINID') THEN
  v_query := v_query || ' AND CL.LOGINID= ''' || v_searchvalue || ''' ';
  END IF;
  IF (v_searchfield = 'NAME') THEN
  v_query := v_query || ' AND (CL.FNAME+'' ''+CL.LNAME) = ''' || v_searchvalue || ''' ';
  END IF;
  IF (v_searchfield = 'Emailid') THEN
  v_query := v_query || ' AND CL.EMAILID = ''' || v_searchvalue || ''' ';
  END IF;
  IF (v_searchfield = 'PHONE') THEN
  v_query := v_query || ' AND CL.PHONE= ''' || v_searchvalue || ''' ';
  END IF;
  IF (v_balance = 2) THEN
  v_query := v_query || 'order by CW.AVAILABLEBALANCE desc';
  END IF;
  IF (v_balance = 1) THEN
  v_query := v_query || 'order by CW.AVAILABLEBALANCE asc';
  END IF;
  RAISE NOTICE '%', v_query;
  EXECUTE v_query;
  RETURN QUERY SELECT * FROM tmp_temp WHERE rownumber BETWEEN v_minindex AND v_maxindex;
  SELECT COUNT(rownumber) INTO v_totalcount FROM tmp_temp;
  SELECT COALESCE(SUM(availablebalance), 0) INTO v_totalwallet FROM tmp_temp;
  DROP TABLE IF EXISTS tmp_temp;
  -- SET option (removed)
END;
$$;


--
-- Name: usp_customermlmwallet_statement(integer, integer, character varying, character varying, character varying, character varying, integer, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_customermlmwallet_statement(v_startrowindex integer DEFAULT 1, v_maxrows integer DEFAULT 100, v_searchfield character varying DEFAULT ''::character varying, v_searchvalue character varying DEFAULT ''::character varying, v_fromdate character varying DEFAULT ''::character varying, v_todate character varying DEFAULT ''::character varying, v_did integer DEFAULT 0, v_totalcount integer DEFAULT 0) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_minindex int;
  v_maxindex int;
  v_query text;
BEGIN
  v_minindex := (v_startrowindex - 1) * v_maxrows + 1;
  v_maxindex := v_startrowindex * v_maxrows;
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp (rownumber int GENERATED BY DEFAULT AS IDENTITY,        
	CLID BIGINT,         
	PROCESSDATE  timestamp,	
	CRDRTYPE varchar(50),	
	CRAMT DECIMAL(18,8),				
    DRAMT DECIMAL(18,8),				
    OLD_BALANCE DECIMAL(18,8),
	BALANCE	DECIMAL(18,8),
	REMARKS varchar(500),				
    TRACENO varchar(500),							         
    DID  BIGINT,
	NAME varchar(500),				         
    EMAILID  varchar(500),						         
    PHONE varchar(500)	,
	LOGINID varchar(200),
	ReferenceUsername varchar(100)) ON COMMIT DROP;
  v_query := 'insert into #temp SELECT CWS.CLID,REPLACE(format(PROCESSDATE,''yyyy/MM/dd hh:mm:ss'') ,''/'',''-'') AS PROCESSDATE,
	 CRDRTYPE,CRAMT,DRAMT,OLD_BALANCE,BALANCE,REMARKS,TRACENO,CL.DID,(CL.FNAME+CL.LNAME) AS NAME,CL.EMAILID,CL.PHONE,CL.LOGINID,CWS.ReferenceUsername
	 FROM dbo.TBL_CUSTOMERMLMWALLET_STATEMENTS CWS  
	 inner JOIN TBL_CUSTOMERLOGIN CL ON CWS.CLID=CL.CLID WHERE 1=1 ';
  RAISE NOTICE '%', v_query;
  IF ((v_fromdate <> '') AND (v_todate = '')) THEN
  v_query := v_query || ' AND CONVERT(DATE, CWS.PROCESSDATE, 105) BETWEEN  CONVERT(DATE, ''' || v_fromdate || ''', 105) AND  CONVERT(DATE, DBO.FUN_GETCURRENTDATE(), 105)';
  END IF;
  IF ((v_fromdate = '') AND (v_todate <> '')) THEN
  v_query := v_query || 'AND CONVERT(DATE, CWS.PROCESSDATE, 105) BETWEEN  CONVERT(DATE, ''' || v_todate || ''', 105) AND  CONVERT(DATE, DBO.FUN_GETCURRENTDATE(), 105)';
  END IF;
  IF ((v_fromdate <> '') AND (v_todate <> '')) THEN
  v_query := v_query || 'AND CONVERT(DATE, CWS.PROCESSDATE, 105) BETWEEN CONVERT(DATE, ''' || v_fromdate || ''', 105) AND  CONVERT(DATE, ''' || v_todate || ''', 105)';
  END IF;
  IF (v_did > 0) THEN
  v_query := v_query || ' AND cl.did=' || CAST(v_did AS VARCHAR(20)) || '';
  END IF;
  IF (v_searchfield = 'LOGINID') THEN
  v_query := v_query || ' AND CL.LOGINID= ''' || v_searchvalue || ''' ';
  END IF;
  IF (v_searchfield = 'EMAILID') THEN
  v_query := v_query || ' AND CL.EMAILID= ''' || v_searchvalue || ''' ';
  END IF;
  IF (v_searchfield = 'NAME') THEN
  v_query := v_query || ' AND (CL.FNAME+'' ''+CL.LNAME) = ''' || v_searchvalue || ''' ';
  END IF;
  IF (v_searchfield = 'PHONE') THEN
  v_query := v_query || ' AND CL.PHONE= ''' || v_searchvalue || ''' ';
  END IF;
  IF (v_searchfield = 'Transationid') THEN
  v_query := v_query || ' AND TRACENO= ''' || v_searchvalue || ''' ';
  END IF;
  IF (v_searchfield = 'ReferenceUsername') THEN
  v_query := v_query || ' AND ReferenceUsername= ''' || v_searchvalue || ''' ';
  END IF;
  EXECUTE v_query;
  RETURN QUERY SELECT * FROM tmp_temp WHERE rownumber BETWEEN v_minindex AND v_maxindex;
  SELECT COUNT(rownumber) INTO v_totalcount FROM tmp_temp;
  DROP TABLE IF EXISTS tmp_temp;
  -- SET option (removed)
END;
$$;


--
-- Name: usp_customermlmwalletstatement(integer, integer, character varying, character varying, character varying, integer, character varying, character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_customermlmwalletstatement(v_startrowindex integer DEFAULT 1, v_maxrows integer DEFAULT 100, v_fromdate character varying DEFAULT ''::character varying, v_todate character varying DEFAULT ''::character varying, v_transactionid character varying DEFAULT ''::character varying, v_totalcount integer DEFAULT 0, v_clid character varying DEFAULT '82'::character varying, v_type character varying DEFAULT 'Cr'::character varying) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_minindex INT;
  v_maxindex INT;
  v_query text;
BEGIN
  BEGIN
  v_minindex := (v_startrowindex - 1) * v_maxrows + 1;
  v_maxindex := v_startrowindex * v_maxrows;
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp (ROW_NUMBER int,
DATE timestamp,
TransactionID VARCHAR(100),
Type VARCHAR(100),
AMOUNT DECIMAL(18,2),
Balance DECIMAL(18,2)) ON COMMIT DROP;
  v_query := 'INSERT INTO #Temp select ROW_NUMBER() over(order by cmwsid desc) as ROW_NUMBER,PROCESSDATE as  Date,TraceNo  as TransactionID,CrDrType as Type,
			case when CrDrType=''Cr'' then CRAMT  when CrDrType=''Dr'' then DRAMT end as AMOUNT,Balance  FROM TBL_CUSTOMERMLMWALLET_STATEMENTS where CLID=cast(''' || v_clid || ''' as int) ';
  RAISE NOTICE '%', v_query;
  IF (v_transactionid <> '') THEN
  v_query := v_query || ' And TraceNo = ''' || v_transactionid || '''';
  END IF;
  IF (v_type <> '') THEN
  v_query := v_query || ' And CrDrType = ''' || v_type || '''';
  END IF;
  IF ((v_fromdate <> '') AND (v_fromdate = '')) THEN
  v_query := v_query || ' AND CONVERT(DATE, PROCESSDATE) =  CONVERT(DATE, ''' || v_fromdate || ''')';
  END IF;
  IF ((v_fromdate = '') AND (v_todate <> '')) THEN
  v_query := v_query || ' AND CONVERT(DATE, PROCESSDATE) =  CONVERT(DATE, ''' || v_todate || ''') ';
  END IF;
  IF ((v_fromdate <> '') AND (v_todate <> '')) THEN
  v_query := v_query || ' AND CONVERT(DATE, PROCESSDATE) BETWEEN CONVERT(DATE, ''' || v_fromdate || ''') AND  CONVERT(DATE, ''' || v_todate || ''') ';
  END IF;
  EXECUTE v_query;
  RETURN QUERY SELECT * FROM tmp_temp WHERE row_number BETWEEN v_minindex AND v_maxindex;
  SELECT COUNT(row_number) INTO v_totalcount FROM tmp_temp;
  DROP TABLE IF EXISTS tmp_temp;
  -- SET option (removed)
  EXCEPTION WHEN OTHERS THEN
  PERFORM dbo.sp_errorlog();
  IF (0 > 0) THEN
  -- ROLLBACK (removed)
  END IF;
  RETURN;
  END;
END;
$$;


