CREATE FUNCTION dbo.usp_customerpanelacceptance(v_sponser character varying DEFAULT ''::character varying, v_plid bigint DEFAULT 0, INOUT v_result character varying DEFAULT ''::character varying) RETURNS character varying
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_loginid VARCHAR(100);
  v_password VARCHAR(100);
  v_currencysymbol VARCHAR(50);
  v_spounsertype int;
  v_cid INT;
  v_plidref VARCHAR(100);
  v_username VARCHAR(100);
  v_ipaddress VARCHAR(100);
  v_intromemid text;
  v_placementmemid VARCHAR(50);
  v_placementregnoside smallint;
  v_fname VARCHAR(100);
  v_mname VARCHAR(100);
  v_lname VARCHAR(100);
  v_gender smallint;
  v_dob VARCHAR(50);
  v_email VARCHAR(100);
  v_mobile VARCHAR(20);
  v_sid INT;
  v_statename VARCHAR(250);
  v_ctid INT;
  v_cityname VARCHAR(200);
  v_address text;
  v_pincode VARCHAR(20);
  v_panno VARCHAR(100);
  v_trpassword VARCHAR(100);
  v_ipadd VARCHAR(100);
  v_epinnumber VARCHAR(100);
  v_nomineename VARCHAR(100);
  v_nomineerelation VARCHAR(100);
  v_sessionloginid VARCHAR(50);
  v_kitid Int;
  v_strresult VARCHAR(200);
  v_application_formno text;
  v_referalcode varchar(10);
  v_introrefid Int;
  v_sponsorids text;
  v_placementids text;
  v_side Int;
  v_title text;
  v_desigantion text;
  v_imagename text;
BEGIN
  -- BEGIN TRAN (removed)
  v_result := 'success';
  IF EXISTS(SELECT 1 FROM member_master WHERE plid = v_plid AND COALESCE(iscustomerpanelaccepted, 0) = 1) THEN
  v_result := 'Your account is already linked to the customer panel !';
  -- COMMIT (removed)
  RETURN;
  END IF;
  IF EXISTS(SELECT 1 FROM member_master WHERE plid = v_plid) THEN
  UPDATE member_master SET iscustomerpanelaccepted = 1, customerpanelaccepteddate = dbo.FUN_GETCURRENTDATE() WHERE plid = v_plid;
  UPDATE portal_login SET iscustomerpanelaccepted = 1, customerpanelaccepteddate = dbo.FUN_GETCURRENTDATE() WHERE plid = v_plid;
  ELSE
  v_spounsertype := 0;
  v_intromemid := '';
  v_placementmemid := '';
  v_placementregnoside := 0;
  v_fname := '';
  v_mname := '';
  v_lname := '';
  v_gender := 0;
  v_dob := '';
  v_email := '';
  v_mobile := '';
  v_sid := 0;
  v_statename := '';
  v_ctid := 0;
  v_cityname := '';
  v_address := '';
  v_pincode := '';
  v_panno := '';
  v_trpassword := '';
  v_ipadd := '';
  v_epinnumber := '';
  v_nomineename := '';
  v_nomineerelation := '';
  v_sessionloginid := '';
  v_kitid := 0;
  v_strresult := '';
  v_application_formno := '';
  v_referalcode := '';
  v_introrefid := 0;
  v_sponsorids := '';
  v_placementids := '';
  v_side := 0;
  v_title := '';
  v_desigantion := '';
  v_imagename := '';
  SELECT loginid, password, password, intro_refid, username, currencysymbol, cid, ipaddress, COALESCE(sp_firstname, ''), COALESCE(sp_lastname, ''), phone, loginid, COALESCE(refral_id, ''), sponserid, placementid, side, title, designation, imagename, COALESCE(spounsertype, 0) INTO v_loginid, v_password, v_trpassword, v_plidref, v_username, v_currencysymbol, v_cid, v_ipaddress, v_fname, v_lname, v_mobile, v_email, v_referalcode, v_sponsorids, v_placementids, v_side, v_title, v_desigantion, v_imagename, v_spounsertype FROM portal_login_temp WHERE username = (SELECT username FROM portal_login WHERE plid = v_plid) LIMIT 1;
  SELECT v_strresult INTO v_strresult FROM dbo.usp_insert_member_master(v_maxplid => v_plid, v_intromemid => v_intromemid, v_placementmemid => v_placementmemid, v_placementregnoside => v_placementregnoside, v_username => v_username, v_fname => v_fname, v_mname => v_mname, v_lname => v_lname, v_gender => v_gender, v_dob => v_dob, v_email => v_email, v_mobile => v_mobile, v_sid => v_sid, v_statename => v_statename, v_ctid => v_ctid, v_cityname => v_cityname, v_cid => v_cid, v_address => v_address, v_pincode => v_pincode, v_panno => v_panno, v_password => v_password, v_trpassword => v_trpassword, v_ipadd => v_ipadd, v_epinnumber => v_epinnumber, v_nomineename => v_nomineename, v_nomineerelation => v_nomineerelation, v_sessionloginid => v_sessionloginid, v_kitid => v_kitid, v_strresult => v_strresult, v_application_formno => v_application_formno, v_loginid => v_loginid);
  UPDATE member_master SET iscustomerpanelaccepted = 1, customerpanelaccepteddate = dbo.FUN_GETCURRENTDATE() WHERE plid = v_plid;
  UPDATE portal_login SET iscustomerpanelaccepted = 1, customerpanelaccepteddate = dbo.FUN_GETCURRENTDATE() WHERE plid = v_plid;
  END IF;
  IF (0 <> 0) THEN
  -- ROLLBACK (removed)
  v_result := 'Some error occurred, Please try again !';
  RETURN;
  END IF;
  -- COMMIT (removed)
END;
$$;


--
-- Name: usp_customerpasscode(integer, bigint, integer, character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_customerpasscode(v_clid integer DEFAULT 1, v_passcode bigint DEFAULT 9378, v_mode integer DEFAULT 2, INOUT v_stroutput character varying DEFAULT ''::character varying) RETURNS character varying
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_oldpasscode BIGINT;
BEGIN
  -- BEGIN TRAN (removed)
  IF (v_mode = 1) THEN
  IF EXISTS(SELECT 1 FROM tbl_customerlogin WHERE clid = v_clid) THEN
  IF NOT EXISTS(SELECT 1 FROM tbl_customerpasscodes WHERE clid = v_clid AND active = 1) THEN
  INSERT INTO tbl_customerpasscodes (clid, passcode, createddate, active) VALUES (v_clid, v_passcode, dbo.FUN_GETCURRENTDATE(), 1);
  v_stroutput := 'SUCCESS';
  -- COMMIT (removed)
  ELSE
  v_stroutput := 'PASSCODE ALREADY ADDED';
  -- COMMIT (removed)
  RETURN;
  END IF;
  ELSE
  v_stroutput := 'INVALID USER';
  -- COMMIT (removed)
  RETURN;
  END IF;
  END IF;
  IF (v_mode = 2) THEN
  IF EXISTS(SELECT 1 FROM tbl_customerlogin WHERE clid = v_clid) THEN
  v_oldpasscode := 0;
  IF EXISTS(SELECT 1 FROM tbl_customerpasscodes WHERE clid = v_clid AND active = 1) THEN
  SELECT passcode INTO v_oldpasscode FROM tbl_customerpasscodes WHERE clid = v_clid AND active = 1;
  UPDATE tbl_customerpasscodes SET passcode = v_passcode WHERE clid = v_clid;
  INSERT INTO tbl_customerpasscodes_history (clid, oldpasscode, newpasscode, createddate, active) VALUES (v_clid, v_oldpasscode, v_passcode, dbo.FUN_GETCURRENTDATE(), 1);
  v_stroutput := 'SUCCESS';
  -- COMMIT (removed)
  END IF;
  ELSE
  v_stroutput := 'INVALID USER';
  -- COMMIT (removed)
  RETURN;
  END IF;
  END IF;
END;
$$;


