  v_desigantion Varchar(100);
  v_imagename Varchar(200);
  v_userid Varchar(20);
  v_tpassword Varchar(200);
BEGIN
  BEGIN
  -- SET option (removed)
  -- SET option (removed)
  -- BEGIN TRAN (removed)
  v_spounsertype := 0;
  v_intromemid := '';
  v_placementmemid := '';
  v_placementregnoside := 0;
  v_fname := '';
  v_mname := '';
  v_lname := '';
  v_gender := 0;
  v_dob := '';
  v_email := '';
  v_mobile := '';
  v_sid := 0;
  v_statename := '';
  v_ctid := 0;
  v_cityname := '';
  v_address := '';
  v_pincode := '';
  v_panno := '';
  v_ipadd := '';
  v_epinnumber := '';
  v_nomineename := '';
  v_nomineerelation := '';
  v_sessionloginid := '';
  v_kitid := 0;
  v_strresult := '';
  v_application_formno := '';
  v_referalcode := '';
  v_introrefid := 0;
  v_sponsorids := '';
  v_placementids := '';
  v_side := 0;
  v_title := '';
  v_desigantion := '';
  v_imagename := '';
  v_userid := '';
  v_tpassword := '';
  v_intresult := -1;
  IF EXISTS(SELECT 1 FROM customer_login_temp WHERE pltid = v_plid AND active = 0 AND did = v_distributerid AND reference_regno = v_ref_regno) THEN
  SELECT loginid, password, intro_refid, username, currencysymbol, cid, ipaddress, COALESCE(sp_firstname, ''), COALESCE(sp_lastname, ''), phone, emailid, COALESCE(refral_id, ''), sponserid, placementid, side, title, designation, imagename, COALESCE(spounsertype, 0), userid, sid, ctid, cityname, tpassword INTO v_loginid, v_password, v_plidref, v_username, v_currencysymbol, v_cid, v_ipaddress, v_fname, v_lname, v_mobile, v_email, v_referalcode, v_sponsorids, v_placementids, v_side, v_title, v_desigantion, v_imagename, v_spounsertype, v_userid, v_sid, v_ctid, v_cityname, v_tpassword FROM customer_login_temp WHERE pltid = v_plid;
  SELECT currencycode INTO v_currency FROM country WHERE cid = v_cid;
  IF NOT EXISTS(SELECT clid FROM tbl_customerlogin WHERE phone = v_mobile) THEN
  SELECT clid INTO v_introrefid FROM tbl_customerlogin WHERE phone = v_mobile;
  INSERT INTO tbl_customerlogin (loginid, password, active, doc, currencysymbol, currency, cid, intro_refid, username, ipaddress, fname, lname, regno, referalcode, pmid, phone, imagename, designation, title, intro_plid, emailid, spounsertype, defaultlandingurl, userid, sid, ctid, cityname, tpassword, did, reference_username, reference_regno) VALUES (v_loginid, v_password, 1, dbo.FUN_GETCURRENTDATE(), v_currencysymbol, v_currency, v_cid, v_plidref, v_username, v_ipaddress, v_fname, v_lname, v_maxplid, v_referalcode, 0, v_mobile, v_imagename, v_desigantion, v_title, v_introrefid, v_email, v_spounsertype, 1, v_userid, v_sid, v_ctid, v_cityname, v_tpassword, v_distributerid, v_ref_username, v_ref_regno);
  v_maxplid := IDENT_CURRENT('TBL_CUSTOMERLOGIN');
  UPDATE tbl_customerlogin SET regno = v_maxplid WHERE clid = v_maxplid;
  UPDATE customer_login_temp SET active = 1 WHERE pltid = v_plid;
  v_intresult := 1;
  ELSE
  SELECT phone INTO v_mobile FROM customer_login_temp WHERE pltid = v_plid;
  UPDATE tbl_customerlogin SET did = v_distributerid WHERE phone = v_mobile AND reference_regno = v_ref_regno;
  v_intresult := 1;
  END IF;
  ELSE
  SELECT phone INTO v_mobile FROM customer_login_temp WHERE pltid = v_plid;
  UPDATE tbl_customerlogin SET did = v_distributerid WHERE phone = v_mobile;
  v_intresult := 2;
  END IF;
  -- SET option (removed)
  -- COMMIT (removed)
  RETURN;
  EXCEPTION WHEN OTHERS THEN
  RETURN QUERY SELECT sqlerrm;
  RETURN QUERY SELECT 0;
  IF 0 > 0 THEN
  -- ROLLBACK (removed)
  END IF;
  RETURN;
  END;
END;
$$;


