--
-- Name: usp_customerticket(character varying, character varying, character varying, character varying, character varying, integer, integer, integer, character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_customerticket(v_fromdate character varying DEFAULT ''::character varying, v_todate character varying DEFAULT ''::character varying, v_status character varying DEFAULT '0'::character varying, v_searchfield character varying DEFAULT ''::character varying, v_searchvalue character varying DEFAULT ''::character varying, INOUT v_recordcount integer DEFAULT 0, v_startrowindex integer DEFAULT 1, v_maxrows integer DEFAULT 100, v_fromplid character varying DEFAULT ''::character varying) RETURNS integer
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_minindex INT;
  v_maxindex INT;
  v_regno BIGINT;
  v_condition varchar(4000);
  v_queryresult varchar(4000);
  v_countquery varchar(4000);
  v_modestatus varchar(10);
  v_parmdefinition varchar(70);
BEGIN
  -- SET option (removed)
  v_condition := '';
  v_queryresult := '';
  v_countquery := '';
  v_modestatus := '0';
  v_minindex := (v_startrowindex - 1) * v_maxrows + 1;
  v_maxindex := v_startrowindex * v_maxrows;
  v_queryresult := v_queryresult || (N'SELECT TOP(' || CAST((v_startrowindex * v_maxrows) AS VARCHAR(70)) || ')  ROW_NUMBER() OVER (ORDER BY TM.DATE DESC ) AS ROWNUMBER,TM.MESSAGE,TM.TICKETNO,TM.CATEGORYNAME,        
		CONVERT(VARCHAR(100),TM.LASTUPDATE,106) AS LASTUPDATE,      
		CONVERT(VARCHAR(100),TM.DATE,106) AS DATE,TM.SUBJECT,TS.NAME AS STATUS,ISNULL(PL.FNAME,'''') AS NAME, PL.PHONE,    
		CONVERT(VARCHAR(100),TM.LASTUPDATE,100) AS FULLLASTUPDATE ,CONVERT(VARCHAR(100),TM.DATE,100)  AS FULLDATE  
		,PL.USERNAME,TM.FROMPLID AS FROMPLID,TM.TMID AS TMID INTO #TEMP FROM TBL_TICKETMASTERMEMBER TM LEFT JOIN TBL_STATUSMASTER TS ON TS.ID = TM.STATUS,TBL_CUSTOMERLOGIN PL WHERE PL.CLID = TM.FROMPLID AND TM.ACTIVE=0');
  v_parmdefinition := N'@RECORDCOUNT NVARCHAR(70) OUTPUT';
  v_countquery := N'SELECT @RECORDCOUNT= COUNT(1) from TBL_TICKETMASTERMEMBER TM LEFT JOIN TBL_STATUSMASTER TS ON TS.ID = TM.STATUS,TBL_CUSTOMERLOGIN PL WHERE PL.CLID = TM.FROMPLID AND TM.ACTIVE=0';
  IF (v_fromdate <> '' OR v_todate <> '') THEN
  IF (v_fromdate <> '') THEN
  v_condition := v_condition || (' AND CONVERT(DATE,TM.DATE,103) >= CONVERT(Date,''' || v_fromdate || ''',103) ');
  END IF;
  IF (v_todate <> '') THEN
  v_condition := v_condition || (' AND CONVERT(DATE,TM.DATE,103) <= CONVERT(Date,''' || v_todate || ''',103) ');
  END IF;
  ELSE
  IF (v_fromdate <> '' AND v_todate <> '') THEN
  v_condition := v_condition || (' AND CONVERT(DATE,TM.DATE,103) BETWEEN CONVERT(DATE,''' || v_fromdate || ''',103) AND CONVERT(DATE,''' || v_todate || ''',103) ');
  END IF;
  END IF;
  IF (v_status <> '0') THEN
  v_condition := v_condition || (' AND TM.STATUS=' || v_status);
  END IF;
  IF (v_searchfield = '1') THEN
  v_condition := v_condition || (' AND TM.TICKETNO=' || v_searchvalue);
  END IF;
  IF (v_searchfield = '2') THEN
  v_condition := v_condition || (' AND PL.FNAME LIKE ''%' || v_searchvalue || '%'' ');
  END IF;
  IF (v_searchfield = '3') THEN
  v_condition := v_condition || (' AND PL.USERNAME LIKE ''%' || v_searchvalue || '%'' ');
  END IF;
  IF (v_searchfield = '4') THEN
  v_condition := v_condition || (' AND TM.CATEGORYNAME LIKE ''%' || v_searchvalue || '%'' ');
  END IF;
  IF (v_searchfield = '5') THEN
  v_condition := v_condition || (' AND PL.PHONE LIKE ''%' || v_searchvalue || '%'' ');
  END IF;
  IF (v_fromplid <> '') THEN
  v_condition := v_condition || (' And TM.FROMPLID =' || v_fromplid);
  END IF;
  v_queryresult := v_queryresult || v_condition || ' ;SELECT  *  FROM #TEMP WHERE ROWNUMBER BETWEEN ' || CAST(v_minindex AS VARCHAR(70)) || ' AND ' || CAST(v_maxindex AS VARCHAR(70)) || '';
  v_countquery := v_countquery || v_condition;
  RAISE NOTICE '%', v_queryresult;
  EXECUTE v_queryresult;
  EXECUTE v_countquery;
  -- SET option (removed)
END;
$$;


--
-- Name: usp_customerwallet(integer, integer, character varying, character varying, character varying, character varying, integer, integer, numeric, integer, integer, bigint, bigint); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_customerwallet(v_startrowindex integer DEFAULT 1, v_maxrows integer DEFAULT 100, v_searchfield character varying DEFAULT ''::character varying, v_searchvalue character varying DEFAULT ''::character varying, v_fromdate character varying DEFAULT ''::character varying, v_todate character varying DEFAULT ''::character varying, v_did integer DEFAULT 1, v_totalcount integer DEFAULT 0, v_totalwallet numeric DEFAULT 0, v_balance integer DEFAULT 2, v_orderbycrdeit integer DEFAULT 0, v_minamount bigint DEFAULT 0, v_maxamount bigint DEFAULT 0) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_minindex INT;
  v_maxindex INT;
  v_query text;
  v_tempclid text;
  v_index INT;
  v_slice text;
  v_totalpayable DECIMAL(18,2);
BEGIN
  v_tempclid := '';
  v_index := 1;
  v_slice := '';
  v_totalpayable := 0;
  v_minindex := (v_startrowindex - 1) * v_maxrows + 1;
  v_maxindex := v_startrowindex * v_maxrows;
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp (ROWNUMBER INT GENERATED BY DEFAULT AS IDENTITY,          
 CLID BIGINT,           
 UPDATEDDATE  VARCHAR(500),   
 ADDMONEY DECIMAL(18,2),      
    TRANSFERTOBANK DECIMAL(18,2),      
    TOTALBALANCE DECIMAL(18,2),  
 AVAILABLEBALANCE DECIMAL(18,2),  
    DID  BIGINT,  
 NAME VARCHAR(500),               
    EMAILID  VARCHAR(500),                 
    PHONE VARCHAR(500),  
 LOGINID VARCHAR(500),  
 CASHBACK DECIMAL(18,2),  
 RETURNS DECIMAL(18,2),  
 TOTALSHOPING DECIMAL(18,2),  
 RESELLERNAME VARCHAR(100)) ON COMMIT DROP;
  v_query := 'INSERT INTO #TEMP SELECT ISNULL(CW.CLID,0),ISNULL(CONVERT(VARCHAR(20), 
  CW.UPDATEDDATE),'''') AS UPDATEDDATE,  
   ISNULL(CW.ADDMONEY,0),ISNULL(CW.TRANSFERTOBANK,0),ISNULL(CW.TOTALBALANCE,0),
   ISNULL(CW.AVAILABLEBALANCE,0),ISNULL(CL.DID,0),  
   ISNULL((CL.FNAME+CL.LNAME),'''') AS NAME,ISNULL(CL.EMAILID,''''),
   ISNULL(CL.PHONE,''''),ISNULL(CL.LOGINID,''''),0,0,0,  
   DM.COMPANYNAME  
   FROM TBL_CUSTOMERLOGIN CL     
   LEFT JOIN TBL_CUSTOMERWALLET CW ON CL.CLID=CW.CLID  
   LEFT JOIN DISTRIBUTOR_MASTER DM ON CL.DID=DM.PLID  
   WHERE 1=1 ';
  IF ((v_fromdate <> '') AND (v_todate = '')) THEN
  v_query := v_query || ' AND CONVERT(VARCHAR(20), CW.UPDATEDDATE, 106) BETWEEN  CONVERT(VARCHAR(20), ''' || v_fromdate || ''', 106) AND  CONVERT(VARCHAR(20), DBO.FUN_GETCURRENTDATE(), 106)';
  END IF;
  IF ((v_fromdate = '') AND (v_todate <> '')) THEN
  v_query := v_query || 'AND CONVERT(VARCHAR(20), CW.UPDATEDDATE, 106) BETWEEN  CONVERT(VARCHAR(20), ''' || v_todate || ''', 106) AND  CONVERT(VARCHAR(20), DBO.FUN_GETCURRENTDATE(), 106)';
  END IF;
  IF ((v_fromdate <> '') AND (v_todate <> '')) THEN
  v_query := v_query || 'AND CONVERT(VARCHAR(20), CW.UPDATEDDATE, 106) BETWEEN CONVERT(VARCHAR(20), ''' || v_fromdate || ''', 106) AND  CONVERT(VARCHAR(20), ''' || v_todate || ''', 106)';
  END IF;
  IF (v_did > 0) THEN
  v_query := v_query || ' AND CL.DID=' || CAST(v_did AS VARCHAR(20)) || '';
  END IF;
  IF (v_searchfield = 'LOGINID') THEN
  v_query := v_query || ' AND CL.LOGINID= ''' || v_searchvalue || ''' ';
  END IF;
  IF (v_searchfield = 'NAME') THEN
  v_query := v_query || ' AND (CL.FNAME+'' ''+CL.LNAME) = ''' || v_searchvalue || ''' ';
  END IF;
  IF (v_searchfield = 'EMAILID') THEN
  v_query := v_query || ' AND CL.EMAILID = ''' || v_searchvalue || ''' ';
  END IF;
  IF (v_searchfield = 'PHONE') THEN
  v_query := v_query || ' AND CL.PHONE= ''' || v_searchvalue || ''' ';
  END IF;
  IF (v_balance = 2) THEN
  v_query := v_query || 'ORDER BY CW.AVAILABLEBALANCE DESC';
  END IF;
  IF (v_balance = 1) THEN
  v_query := v_query || 'ORDER BY CW.AVAILABLEBALANCE ASC';
  END IF;
  IF (v_orderbycrdeit = 1) THEN
  v_query := v_query || 'ORDER BY CW.AVAILABLEBALANCE ASC';
  END IF;
  IF (v_orderbycrdeit = 2) THEN
  v_query := v_query || 'ORDER BY CW.AVAILABLEBALANCE DESC';
  END IF;
  EXECUTE v_query;
  RAISE NOTICE '%', v_query;
  SELECT COALESCE(v_tempclid || ', ', '') || CAST(loginid AS VARCHAR) INTO v_tempclid FROM (SELECT DISTINCT loginid FROM tmp_temp) AS t;
  SELECT SUBSTRING(v_tempclid FROM 2 FOR LENGTH(CAST(v_tempclid AS TEXT))) INTO v_tempclid;
  v_index := 1;
  WHILE (v_index <> 0) LOOP
  SELECT POSITION(',' IN v_tempclid) INTO v_index;
  IF (v_index <> 0) THEN
  SELECT LEFT(CAST(v_tempclid AS TEXT), v_index - 1) INTO v_slice;
  ELSE
  SELECT v_tempclid INTO v_slice;
  END IF;
  v_totalpayable := 0;
  IF (v_slice <> '') THEN
  SELECT COALESCE(SUM(pom.total_purchase_cost), 0) INTO v_totalpayable FROM tbl_product_order_master AS pom LEFT JOIN tbl_order_master AS om ON pom.orderid = om.orderid WHERE pom.loginid = LTRIM(RTRIM(v_slice)) AND om.paymode = 'payumoney' AND pom.intstatus IN (0, 1, 2, 3, 4, 5, 6, 9);
  UPDATE tmp_temp SET totalshoping = v_totalpayable WHERE loginid = LTRIM(RTRIM(v_slice));
  END IF;
  SELECT RIGHT(CAST(v_tempclid AS TEXT), LENGTH(CAST(v_tempclid AS TEXT)) - v_index) INTO v_tempclid;
  IF LENGTH(CAST(v_tempclid AS TEXT)) = 0 THEN
  EXIT;
  END IF;
  END LOOP;
  IF ((v_minamount > 0) AND (v_maxamount > 0)) THEN
  RETURN QUERY SELECT * FROM tmp_temp WHERE rownumber BETWEEN v_minindex AND v_maxindex AND (addmoney + cashback + returns) - (transfertobank + totalshoping) >= v_minamount AND (addmoney + cashback + returns) - (transfertobank + totalshoping) >= v_maxamount;
  ELSE
  RETURN QUERY SELECT * FROM tmp_temp WHERE rownumber BETWEEN v_minindex AND v_maxindex;
  END IF;
  SELECT COUNT(rownumber) INTO v_totalcount FROM tmp_temp;
  SELECT COALESCE(SUM(availablebalance), 0) INTO v_totalwallet FROM tmp_temp;
  DROP TABLE IF EXISTS tmp_temp;
  -- SET option (removed)
END;
$$;


--
-- Name: usp_customerwallet_statement(integer, integer, character varying, character varying, character varying, character varying, integer, integer, character varying, integer, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_customerwallet_statement(v_startrowindex integer DEFAULT 1, v_maxrows integer DEFAULT 100, v_searchfield character varying DEFAULT ''::character varying, v_searchvalue character varying DEFAULT ''::character varying, v_fromdate character varying DEFAULT ''::character varying, v_todate character varying DEFAULT ''::character varying, v_did integer DEFAULT 0, v_totalcount integer DEFAULT 0, v_transationid character varying DEFAULT ''::character varying, v_kycstatus integer DEFAULT 6, v_crdrlist integer DEFAULT 0) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_minindex INT;
  v_maxindex INT;
  v_query text;
BEGIN
  v_minindex := (v_startrowindex - 1) * v_maxrows + 1;
  v_maxindex := v_startrowindex * v_maxrows;
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp (rownumber int GENERATED BY DEFAULT AS IDENTITY,        
	CLID BIGINT,         
	PROCESSDATE  varchar(100),	
	CRDRTYPE varchar(50),	
	CRAMT DECIMAL(18,8),				
    DRAMT DECIMAL(18,8),				
    OLD_BALANCE DECIMAL(18,8),
	BALANCE	DECIMAL(18,8),
	REMARKS varchar(500),				
    TRACENO varchar(500),							         
    STATUS INT,									
    DID  BIGINT,
	NAME varchar(500),				         
    EMAILID  varchar(500),						         
    PHONE varchar(500)	,
    LOGINID varchar(200),
	RESELLERNAME varchar(100)) ON COMMIT DROP;
  v_query := 'INSERT INTO #TEMP SELECT ISNULL(CWS.CLID,0),
				REPLACE(CONVERT(VARCHAR(11), PROCESSDATE, 106), '' '', ''-'') +'' ''+STUFF(RIGHT( CONVERT(VARCHAR,PROCESSDATE,100 ) ,7), 6, 0, '' '')AS PROCESSDATE,
				ISNULL(CRDRTYPE,'''') AS CRDRTYPE,ISNULL(CRAMT,0) AS CRAMT,ISNULL(DRAMT,0) AS DRAMT,ISNULL(OLD_BALANCE,0) AS BALANCE,
				ISNULL(BALANCE,0) AS BALANCE,ISNULL(REMARKS,'''') AS REMARKS,ISNULL(TRACENO,'''')  AS TRACENO,
				ISNULL(STATUS,0)  AS STATUS,ISNULL(CL.DID,0)  AS DID,(CL.FNAME+CL.LNAME) AS NAME,
				ISNULL(CL.EMAILID,'''')  AS EMAILID,ISNULL(CL.PHONE,'''')  AS PHONE,
				ISNULL(CL.LOGINID,'''')  AS LOGINID, DM.COMPANYNAME
				FROM TBL_CUSTOMERWALLET_STATEMENTS CWS  
				LEFT JOIN TBL_CUSTOMERLOGIN CL ON CWS.CLID=CL.CLID 
				LEFT JOIN DISTRIBUTOR_MASTER DM ON CL.DID=DM.PLID
				WHERE 1=1 ';
  IF (v_kycstatus <> 6) THEN
  v_query := v_query || ' AND STATUS= ''' || CAST(v_kycstatus AS VARCHAR(200)) || ''' ';
  END IF;
  IF ((v_fromdate <> '') AND (v_todate = '')) THEN
  v_query := v_query || ' AND CONVERT(DATE, CWS.PROCESSDATE, 105) BETWEEN  CONVERT(DATE, ''' || v_fromdate || ''', 105) AND  CONVERT(DATE, DBO.FUN_GETCURRENTDATE(), 105)';
  END IF;
  IF ((v_fromdate = '') AND (v_todate <> '')) THEN
  v_query := v_query || 'AND CONVERT(DATE, CWS.PROCESSDATE, 105) BETWEEN  CONVERT(DATE, ''' || v_todate || ''', 105) AND  CONVERT(DATE, DBO.FUN_GETCURRENTDATE(), 105)';
  END IF;
  IF ((v_fromdate <> '') AND (v_todate <> '')) THEN
  v_query := v_query || 'AND CONVERT(DATE, CWS.PROCESSDATE, 105) BETWEEN CONVERT(DATE, ''' || v_fromdate || ''', 105) AND  CONVERT(DATE, ''' || v_todate || ''', 105)';
  END IF;
  IF (v_did > 0) THEN
  v_query := v_query || ' AND CL.DID=' || CAST(v_did AS VARCHAR(20)) || '';
  END IF;
  IF (v_searchfield = 'LOGINID') THEN
  v_query := v_query || ' AND CL.LOGINID= ''' || v_searchvalue || ''' ';
  END IF;
  IF (v_searchfield = 'EMAILID') THEN
  v_query := v_query || ' AND CL.EMAILID= ''' || v_searchvalue || ''' ';
  END IF;
  IF (v_transationid <> '') THEN
  v_query := v_query || ' AND TRACENO= ''' || v_transationid || ''' ';
  END IF;
  IF (v_searchfield = 'NAME') THEN
  v_query := v_query || ' AND (CL.FNAME+'' ''+CL.LNAME) = ''' || v_searchvalue || ''' ';
  END IF;
  IF (v_searchfield = 'PHONE') THEN
  v_query := v_query || ' AND CL.PHONE= ''' || v_searchvalue || ''' ';
  END IF;
  IF (v_crdrlist = 1) THEN
  v_query := v_query || ' AND CRDRTYPE= ''CR'' ';
  ELSE
  IF (v_crdrlist = 2) THEN
  v_query := v_query || ' AND CRDRTYPE= ''DR'' ';
  END IF;
  END IF;
  v_query := v_query || ' ORDER BY CONVERT(DATE,PROCESSDATE,106) DESC ';
  EXECUTE v_query;
  RAISE NOTICE '%', v_query;
  RETURN QUERY SELECT * FROM tmp_temp WHERE rownumber BETWEEN v_minindex AND v_maxindex;
  SELECT COUNT(rownumber) INTO v_totalcount FROM tmp_temp;
  DROP TABLE IF EXISTS tmp_temp;
  -- SET option (removed)
END;
$$;


--
-- Name: usp_customerwalletsused_track(character varying, numeric, numeric, numeric, numeric, numeric); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_customerwalletsused_track(v_transid character varying DEFAULT 'MOBBP-202008211745569858'::character varying, v_mlmwalletused numeric DEFAULT 0, v_customerwalletused numeric DEFAULT 0, v_voucherused numeric DEFAULT 0, v_onlineamount numeric DEFAULT 10, v_codpayment numeric DEFAULT 0) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_oorid Int;
  v_orderid Varchar(200);
BEGIN
  BEGIN
  -- BEGIN TRAN (removed)
  IF (v_transid <> '') THEN
  IF (v_onlineamount > 0) THEN
  v_oorid := 0;
  v_orderid := '';
  SELECT oorid, orderid INTO v_oorid, v_orderid FROM tbl_orderonlinerequests WHERE transactionid = v_transid;
  INSERT INTO dbo.tbl_rechargeonlinepaymentsdetails (oorid, orderid, paymentdate, transid, mlmwallet, mlmtranid, beni_username, customerwallet, onlineamount, status, voucherused, codpayment) VALUES (v_oorid, v_orderid, dbo.FUN_GETCURRENTDATE(), v_transid, v_mlmwalletused, '', '', v_customerwalletused, v_onlineamount, 1, v_voucherused, v_codpayment);
  END IF;
  -- COMMIT (removed)
  RETURN;
  END IF;
  -- COMMIT (removed)
  RETURN;
  EXCEPTION WHEN OTHERS THEN
  RAISE NOTICE '%', sqlerrm;
  IF (0 <> 0) THEN
  PERFORM dbo.sp_errorlog();
  -- ROLLBACK (removed)
  RETURN;
  END IF;
  END;
END;
$$;


--
-- Name: usp_daily_reseller_commission(integer, integer, character varying, character varying, character varying, integer, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_daily_reseller_commission(v_startrowindex integer DEFAULT 1, v_maxrows integer DEFAULT 100, v_fromdate character varying DEFAULT ''::character varying, v_todate character varying DEFAULT ''::character varying, v_did character varying DEFAULT '1048'::character varying, v_totalcount integer DEFAULT 0, v_servicetype integer DEFAULT 2) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_minindex INT;
  v_maxindex INT;
  v_query text;
  v_count INT;
  v_total INT;
  v_tempdid INT;
  v_tempdate VARCHAR(100);
  v_tempshopcr DECIMAL(18,2);
  v_temputilitycr DECIMAL(18,2);
BEGIN
  BEGIN
  v_count := 1;
  v_total := 0;
  v_tempdid := 0;
  v_tempdate := '';
  v_tempshopcr := 0;
  v_temputilitycr := 0;
  v_minindex := (v_startrowindex - 1) * v_maxrows + 1;
  v_maxindex := v_startrowindex * v_maxrows;
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp (ROWNUMBER INT GENERATED BY DEFAULT AS IDENTITY,
DID INT,
DATE varchar(100),
SHOPPINGCOMISSION DECIMAL(18,4),
UTILITYCOMMISSION DECIMAL(18,2),
TOTALAMOUNT  DECIMAL(18,2)) ON COMMIT DROP;
  v_query := 'INSERT INTO #TEMP SELECT DID,CONVERT(VARCHAR,TRANSDATE,106),0,0,0 FROM 
TBL_RESELLER_COMMISSION_WALLET WHERE DID=''' || CAST(v_did AS VARCHAR(30)) || ''' and FINALUPDATE=1 ';
  IF ((v_fromdate <> '') AND (v_fromdate = '')) THEN
  v_query := v_query || ' AND CONVERT(DATE, RM.ORDERDATE) =  CONVERT(DATE, ''' || v_fromdate || ''')';
  END IF;
  IF ((v_fromdate = '') AND (v_todate <> '')) THEN
  v_query := v_query || ' AND CONVERT(DATE, RM.ORDERDATE) =  CONVERT(DATE, ''' || v_todate || ''') ';
  END IF;
  IF ((v_fromdate <> '') AND (v_todate <> '')) THEN
  v_query := v_query || ' AND CONVERT(DATE, RM.ORDERDATE) BETWEEN CONVERT(DATE, ''' || v_fromdate || ''') AND  CONVERT(DATE, ''' || v_todate || ''') ';
  END IF;
  IF (v_servicetype <> '') THEN
  v_query := v_query || ' AND SERVICETYPE=''' || CAST(v_servicetype AS VARCHAR(30)) || '''';
  END IF;
  v_query := v_query || ' GROUP BY DID, CONVERT(VARCHAR,TRANSDATE,106) ';
  v_query := v_query || ' Order BY CONVERT(VARCHAR,TRANSDATE,106) DESC';
  RAISE NOTICE '%', v_query;
  EXECUTE v_query;
  SELECT COUNT(1) INTO v_total FROM tmp_temp;
  WHILE (v_count <= v_total) LOOP
  SELECT CAST(TO_CHAR(date, 'DD TMMon YYYY') AS VARCHAR(30)), did INTO v_tempdate, v_tempdid FROM tmp_temp WHERE rownumber = v_count;
  SELECT COALESCE(SUM(cr), 0) INTO v_temputilitycr FROM tbl_reseller_commission_wallet WHERE did = v_tempdid AND CAST(TO_CHAR(transdate, 'DD TMMon YYYY') AS VARCHAR(30)) = CAST(TO_CHAR(v_tempdate, 'DD TMMon YYYY') AS VARCHAR(30)) AND servicetype = 1;
  SELECT COALESCE(SUM(cr), 0) INTO v_tempshopcr FROM tbl_reseller_commission_wallet WHERE did = v_tempdid AND CAST(TO_CHAR(transdate, 'DD TMMon YYYY') AS VARCHAR(30)) = CAST(TO_CHAR(v_tempdate, 'DD TMMon YYYY') AS VARCHAR(30)) AND servicetype = 2;
  UPDATE tmp_temp SET shoppingcomission = v_tempshopcr, utilitycommission = v_temputilitycr, totalamount = (v_tempshopcr + v_temputilitycr) WHERE rownumber = v_count;
  v_count := v_count + 1;
  END LOOP;
  RETURN QUERY SELECT * FROM tmp_temp WHERE rownumber BETWEEN v_minindex AND v_maxindex;
  SELECT COUNT(1) INTO v_totalcount FROM tmp_temp;
  DROP TABLE IF EXISTS tmp_temp;
  -- SET option (removed)
  EXCEPTION WHEN OTHERS THEN
  PERFORM dbo.sp_errorlog();
  IF (0 > 0) THEN
  -- ROLLBACK (removed)
  END IF;
  RETURN;
  END;
END;
$$;


