--
-- Name: usp_dailyreseller_commissionreport(integer, integer, character varying, character varying, character varying, integer, character varying, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_dailyreseller_commissionreport(v_startrowindex integer DEFAULT 1, v_maxrows integer DEFAULT 100, v_fromdate character varying DEFAULT ''::character varying, v_todate character varying DEFAULT ''::character varying, v_invoiceno character varying DEFAULT ''::character varying, v_totalcount integer DEFAULT 0, v_did character varying DEFAULT '2'::character varying, v_ddltype integer DEFAULT 1) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_minindex INT;
  v_maxindex INT;
  v_query text;
BEGIN
  BEGIN
  v_minindex := (v_startrowindex - 1) * v_maxrows + 1;
  v_maxindex := v_startrowindex * v_maxrows;
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp (DATE timestamp,
TotalAmount decimal(18,4),
Commission DECIMAL(18,2),
Relased int,
ISDistributed int,
PROCESSTYPE INT) ON COMMIT DROP;
  v_query := 'INSERT INTO #Temp SELECT  convert(Date, RM.OrderDate) as DATE,isnull(sum(PM.Total_Purchase_Cost),0) as TotalAmount,
			isnull( sum(PM.Total_BV),0) as Commission,isnull(RRD.ISADMINRELEASE,0) as Relased,isnull(RRD.ISRESELLERRELEASE,0) as ISDistributed,
			RRD.PROCESSTYPE
			FROM [DBO].[TBL_MERCHANT_COMMISSIONINVOICES]  as MC
			inner join [DBO].[TBL_MERCHANT_COMMISSIONINVOICES_DETAILS] as MCD on MC.ORDERID=MCD.ORDERID 
			inner join TBL_PRODUCT_ORDER_MASTER as PM on PM.Orderno=MCD.ORDERNO
			inner join tbl_order_master as RM  on RM.OrderID=MCD.ORDERID
			left join orderstatusmaster  as OS on PM.IntStatus=OS.OSID
			inner join TBL_CUSTOMERLOGIN as CL on Cl.loginid=PM.LoginID 
			inner join TBL_RESELLERRELEASEBVDETAILS as RRD on RRD.ORDERNO= PM.Orderno
			where  CL.DID=cast(''' || v_did || ''' as int) ';
  IF (v_invoiceno <> '') THEN
  v_query := v_query || ' And PM.InvoiceNo = ''' || v_invoiceno || '''';
  END IF;
  IF ((v_fromdate <> '') AND (v_fromdate = '')) THEN
  v_query := v_query || ' AND CONVERT(DATE, RM.OrderDate) =  CONVERT(DATE, ''' || v_fromdate || ''')';
  END IF;
  IF ((v_fromdate = '') AND (v_todate <> '')) THEN
  v_query := v_query || ' AND CONVERT(DATE, RM.OrderDate) =  CONVERT(DATE, ''' || v_todate || ''') ';
  END IF;
  IF ((v_fromdate <> '') AND (v_todate <> '')) THEN
  v_query := v_query || ' AND CONVERT(DATE, RM.OrderDate) BETWEEN CONVERT(DATE, ''' || v_fromdate || ''') AND  CONVERT(DATE, ''' || v_todate || ''') ';
  END IF;
  IF (v_ddltype <> '') THEN
  v_query := v_query || ' AND RRD.PROCESSTYPE=''' || CAST(v_ddltype AS VARCHAR(30)) || '''';
  END IF;
  v_query := v_query || '  group by convert(Date, RM.OrderDate),RRD.ISRESELLERRELEASE,RRD.ISADMINRELEASE,RRD.PROCESSTYPE   
			order by convert(Date, RM.OrderDate) desc';
  RAISE NOTICE '%', v_query;
  EXECUTE v_query;
  RETURN QUERY SELECT * FROM tmp_temp;
  SELECT COUNT(1) INTO v_totalcount FROM tmp_temp;
  DROP TABLE IF EXISTS tmp_temp;
  -- SET option (removed)
  EXCEPTION WHEN OTHERS THEN
  PERFORM dbo.sp_errorlog();
  IF (0 > 0) THEN
  -- ROLLBACK (removed)
  END IF;
  RETURN;
  END;
END;
$$;


--
-- Name: usp_dailysalesgraph(integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_dailysalesgraph(v_did integer DEFAULT 1) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_count int;
BEGIN
  v_count := 0;
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp (SALES decimal(18,2),
		Date VARCHAR(50),
		COLOR VARCHAR(50)) ON COMMIT DROP;
  INSERT INTO tmp_temp SELECT SUM(om.order_netamt) AS sales, CAST(om.orderdate AS DATE) AS loginid, '#0796B3' AS color FROM tbl_order_master AS om INNER JOIN tbl_customerlogin AS cl ON om.loginid = cl.loginid LEFT JOIN orderstatusmaster AS os ON om.intstatus = os.osid WHERE cl.did = v_did AND NOT om.intstatus IN (7, 8) GROUP BY CAST(om.orderdate AS DATE) ORDER BY CAST(om.orderdate AS DATE) DESC NULLS LAST LIMIT 10;
  SELECT COUNT(1) INTO v_count FROM tmp_temp;
  IF (v_count < 10) THEN
  WHILE (v_count < 10) LOOP
  INSERT INTO tmp_temp (sales, date, color) VALUES (0, '', '#0796B3');
  v_count := v_count + 1;
  END LOOP;
  END IF;
  RETURN QUERY SELECT * FROM tmp_temp;
  DROP TABLE IF EXISTS tmp_temp;
END;
$$;


--
-- Name: usp_dashboard_order_summary(integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_dashboard_order_summary(v_did integer DEFAULT 2) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
BEGIN
  -- BEGIN TRAN (removed)
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp (DATE VARCHAR(100),
NAME VARCHAR(100),
TYPE VARCHAR(100),
AMOUNT DECIMAL(18,2),
STATUS VARCHAR(100)) ON COMMIT DROP;
  INSERT INTO tmp_temp SELECT CAST(TO_CHAR(tcpr.rechargedate, 'DD TMMon YYYY') AS VARCHAR(100)), (cl.fname || ' ' || cl.lname), 'Prepaid Recharge', tcpr.rechargeamount, rechargestatus FROM tbl_customer_prepaid_recharges AS tcpr INNER JOIN tbl_customerlogin AS cl ON tcpr.clid = cl.clid WHERE cl.did = v_did AND tcpr.rechargestatus <> 'NULL' AND tcpr.rechargestatus <> 'ERROR' ORDER BY CAST(TO_CHAR(tcpr.rechargedate, 'DD TMMon YYYY') AS VARCHAR(100)) DESC NULLS LAST LIMIT 5;
  INSERT INTO tmp_temp SELECT CAST(TO_CHAR(tcpr.rechargedate, 'DD TMMon YYYY') AS VARCHAR(100)), (cl.fname || ' ' || cl.lname), 'Postpaid Recharge', tcpr.rechargeamount, rechargestatus FROM tbl_customer_postpaid_recharges AS tcpr INNER JOIN tbl_customerlogin AS cl ON tcpr.clid = cl.clid WHERE cl.did = v_did AND tcpr.rechargestatus <> 'NULL' AND tcpr.rechargestatus <> 'ERROR' ORDER BY CAST(TO_CHAR(tcpr.rechargedate, 'DD TMMon YYYY') AS VARCHAR(100)) DESC NULLS LAST LIMIT 5;
  INSERT INTO tmp_temp SELECT CAST(TO_CHAR(tcpr.rechargedate, 'DD TMMon YYYY') AS VARCHAR(100)), (cl.fname || ' ' || cl.lname), 'DTH Recharge', tcpr.rechargeamount, rechargestatus FROM tbl_customer_dth_recharges AS tcpr INNER JOIN tbl_customerlogin AS cl ON tcpr.clid = cl.clid WHERE cl.did = v_did AND tcpr.rechargestatus <> 'NULL' AND tcpr.rechargestatus <> 'ERROR' ORDER BY CAST(TO_CHAR(tcpr.rechargedate, 'DD TMMon YYYY') AS VARCHAR(100)) DESC NULLS LAST LIMIT 5;
  INSERT INTO tmp_temp SELECT CAST(TO_CHAR(tcpr.rechargedate, 'DD TMMon YYYY') AS VARCHAR(100)), (cl.fname || ' ' || cl.lname), 'Electricity  Recharge', tcpr.rechargeamount, rechargestatus FROM tbl_customer_electricity_recharges AS tcpr INNER JOIN tbl_customerlogin AS cl ON tcpr.clid = cl.clid WHERE cl.did = v_did AND tcpr.rechargestatus <> 'NULL' AND tcpr.rechargestatus <> 'ERROR' ORDER BY CAST(TO_CHAR(tcpr.rechargedate, 'DD TMMon YYYY') AS VARCHAR(100)) DESC NULLS LAST LIMIT 5;
  INSERT INTO tmp_temp SELECT CAST(TO_CHAR(tcpr.rechargedate, 'DD TMMon YYYY') AS VARCHAR(100)), (cl.fname || ' ' || cl.lname), 'GAS Recharge', tcpr.rechargeamount, rechargestatus FROM tbl_customer_gas_recharges AS tcpr INNER JOIN tbl_customerlogin AS cl ON tcpr.clid = cl.clid WHERE cl.did = v_did AND tcpr.rechargestatus <> 'NULL' AND tcpr.rechargestatus <> 'ERROR' ORDER BY CAST(TO_CHAR(tcpr.rechargedate, 'DD TMMon YYYY') AS VARCHAR(100)) DESC NULLS LAST LIMIT 5;
  INSERT INTO tmp_temp SELECT CAST(TO_CHAR(om.orderdate, 'DD TMMon YYYY') AS VARCHAR(100)), (cl.fname || ' ' || cl.lname), 'Order', om.order_netamt, os.statusname FROM tbl_order_master AS om INNER JOIN tbl_customerlogin AS cl ON om.loginid = cl.loginid LEFT JOIN orderstatusmaster AS os ON om.intstatus = os.osid WHERE cl.did = v_did AND om.intstatus IN (0, 1, 2, 3, 4, 5, 6) ORDER BY CAST(TO_CHAR(om.orderdate, 'DD TMMon YYYY') AS VARCHAR(100)) DESC NULLS LAST LIMIT 5;
  RETURN QUERY SELECT ROW_NUMBER() OVER (ORDER BY date DESC NULLS LAST) AS row, * FROM tmp_temp ORDER BY date DESC NULLS LAST LIMIT 5;
  -- COMMIT (removed)
END;
$$;


--
-- Name: usp_dashboard_walletbalance(numeric, numeric, numeric, numeric, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_dashboard_walletbalance(INOUT v_totalcomission numeric DEFAULT 0, INOUT v_withdrwal numeric DEFAULT 0, INOUT v_rewards numeric DEFAULT 0, INOUT v_balance numeric DEFAULT 0, v_did integer DEFAULT 0) RETURNS record
    LANGUAGE plpgsql
    AS $$
BEGIN
  -- SET option (removed)
  SELECT COALESCE(SUM(cr), 0) INTO v_totalcomission FROM tbl_reseller_commission_wallet WHERE did = v_did AND finalupdate = 1;
  SELECT COALESCE(SUM(amount), 0) INTO v_withdrwal FROM tbl_reseller_transfertobank_request WHERE did = v_did AND transferrequest = 1 AND transferid = 2;
  SELECT COALESCE(SUM(amount), 0) INTO v_rewards FROM tbl_reseller_transfertobank_request WHERE did = v_did AND transferrequest = 1 AND transferid = 1;
  v_balance := v_totalcomission - (v_withdrwal + v_rewards);
  -- SET option (removed)
END;
$$;


