--
-- Name: usp_datacardrecharge_details(integer, integer, integer, character varying, character varying, integer, character varying, character varying, character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_datacardrecharge_details(v_mode integer DEFAULT 0, v_startrowindex integer DEFAULT 1, v_maxrows integer DEFAULT 100, v_fromdate character varying DEFAULT ''::character varying, v_todate character varying DEFAULT ''::character varying, v_totalcount integer DEFAULT 0, v_searchfield character varying DEFAULT ''::character varying, v_searchvalue character varying DEFAULT ''::character varying, v_status character varying DEFAULT ''::character varying) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_minindex INT;
  v_maxindex INT;
  v_query text;
BEGIN
  v_minindex := (v_startrowindex - 1) * v_maxrows + 1;
  v_maxindex := v_startrowindex * v_maxrows;
  IF (v_mode = 0) THEN
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp (ROWNUMBER BIGINT GENERATED BY DEFAULT AS IDENTITY,         
 TCPRID BIGINT,               
 CLID BIGINT,                 
 MOBILENO VARCHAR(100),         
 OPERATORTYPE VARCHAR(100),        
 RECHARGEAMOUNT DECIMAL(18,2),        
 TRANSACTIONID  VARCHAR(100),         
 RECHARGEDATE VARCHAR(100),         
 ADMINSTATUS VARCHAR(100),        
 NAME VARCHAR(100),        
 EMAILID VARCHAR(100),        
 OPERATORNAME VARCHAR(100),        
 OPERATORCODE VARCHAR(100),        
 ISANDROIDORWEB INT,        
 PaidViaCashWallet Decimal(18,8),    
PaidViaCahbackWallet Decimal(18,8),    
PaidViaKreazVoucher Int,    
PaidViaOnline Decimal(18,8)) ON COMMIT DROP;
  v_query := 'INSERT INTO #TEMP SELECT TCPR.TCDCRID,TCPR.CLID,TCPR.MOBILENO,TCPR.OPERATORTYPE,        
TCPR.RECHARGEAMOUNT,TCPR.TRANSACTIONID,CAST(TCPR.RECHARGEDATE AS VARCHAR(50)) ,TCPR.RECHARGESTATUS        
,(CL.FNAME+'' ''+CL.LNAME) AS NAME,CL.EMAILID,TCPR.OPERATORNAME,TCPR.OPERATORCODE,TCPR.ISANDROIDORWEB,        
  ISNULL(CASHWALLETUSED,0),  
ISNULL(CASHBACKWALLETUSED,0),    
ISNULL(VOUCHERWALLETUSED,0),  
ISNULL(TBL_ONLINEPAYMENTHISTORY.AMOUNT,0)        
FROM TBL_CUSTOMER_DATACARD_RECHARGES TCPR          
LEFT JOIN TBL_ORDERPAYMENT_HISTORY ON TBL_ORDERPAYMENT_HISTORY.ORDERID=TCPR.TRANSACTIONID      
LEFT JOIN TBL_ORDERONLINEREQUESTS ON TBL_ORDERONLINEREQUESTS.ORDERID=TCPR.TRANSACTIONID     
LEFT JOIN TBL_ONLINEPAYMENTHISTORY ON TBL_ONLINEPAYMENTHISTORY.REFERNECID=TBL_ORDERONLINEREQUESTS.TRANSACTIONID                              
LEFT JOIN TBL_CUSTOMERLOGIN CL ON CL.CLID=TCPR.CLID        
       
  WHERE TCPR.RECHARGESTATUS Is Not Null ';
  IF ((v_fromdate <> '') AND (v_todate = '')) THEN
  v_query := v_query || ' AND CONVERT(DATE, TCPR.RECHARGEDATE, 105) BETWEEN  CONVERT(DATE, ''' || v_fromdate || ''', 105) AND  CONVERT(DATE, DBO.FUN_GETCURRENTDATE(), 105)';
  END IF;
  IF ((v_fromdate = '') AND (v_todate <> '')) THEN
  v_query := v_query || 'AND CONVERT(DATE, TCPR.RECHARGEDATE, 105) BETWEEN  CONVERT(DATE, ''' || v_todate || ''', 105) AND  CONVERT(DATE, DBO.FUN_GETCURRENTDATE(), 105)';
  END IF;
  IF ((v_fromdate <> '') AND (v_todate <> '')) THEN
  v_query := v_query || 'AND CONVERT(DATE, TCPR.RECHARGEDATE, 105) BETWEEN CONVERT(DATE, ''' || v_fromdate || ''', 105) AND  CONVERT(DATE, ''' || v_todate || ''', 105)';
  END IF;
  IF (v_searchfield = 'NAME') THEN
  v_query := v_query || ' AND (CL.FNAME+CL.LNAME) LIKE ''%' || v_searchvalue || '%'' ';
  END IF;
  IF (v_searchfield = 'PHONE') THEN
  v_query := v_query || ' AND TCPR.MOBILENO LIKE ''%' || v_searchvalue || '%'' ';
  END IF;
  IF (v_searchfield = 'EMAILID') THEN
  v_query := v_query || ' AND CL.EMAILID LIKE ''%' || v_searchvalue || '%'' ';
  END IF;
  IF (v_searchfield = 'TRANSACTIONID') THEN
  v_query := v_query || ' AND TCPR.TRANSACTIONID LIKE ''%' || v_searchvalue || '%'' ';
  END IF;
  IF (v_status <> '') THEN
  v_query := v_query || ' AND TCPR.RECHARGESTATUS =''' || v_status || ''' ';
  END IF;
  v_query := v_query || ' ORDER BY TCPR.RECHARGEDATE DESC';
  EXECUTE v_query;
  RETURN QUERY SELECT rownumber, tcprid, clid, mobileno, operatortype, rechargeamount, transactionid, rechargedate, adminstatus, name, emailid, operatorname, operatorcode, isandroidorweb, paidviacashwallet, paidviacahbackwallet, paidviakreazvoucher, paidviaonline FROM tmp_temp WHERE rownumber BETWEEN v_minindex AND v_maxindex ORDER BY rownumber ASC NULLS FIRST;
  SELECT COUNT(rownumber) INTO v_totalcount FROM tmp_temp;
  DROP TABLE IF EXISTS tmp_temp;
  -- SET option (removed)
  END IF;
END;
$$;


--
-- Name: usp_datasearch(character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_datasearch(v_serchitem character varying DEFAULT 'A'::character varying) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_count INT;
BEGIN
  -- SET option (removed)
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp (SEARCHRESULT  text,
FOMATEDRESULT  text, 
FORURL text, 
SEARCHTYPE VARCHAR(200), 
MPRID BIGINT) ON COMMIT DROP;
  IF EXISTS(SELECT maincatid FROM tbl_main_category WHERE status = 1 AND ' ' || maincatname LIKE '% ' || v_serchitem || '%') THEN
  INSERT INTO tmp_temp SELECT DISTINCT (maincatname) AS serachtext, maincatname, '/shop/' || main_cat_code, 'maincategory', 0 FROM tbl_main_category WHERE status = 1 AND ' ' || maincatname LIKE '% ' || v_serchitem || '%';
  END IF;
  IF EXISTS(SELECT catid FROM tbl_category WHERE status = 1 AND ' ' || catname LIKE '% ' || v_serchitem || '%') THEN
  INSERT INTO tmp_temp SELECT DISTINCT (pc.catname) AS serachtext, (pc.catname || CONCAT('<font style="color:#2874f0; font-weight: 500;padding-left: 5px;">', ' in ' || LOWER(pc.catname) || '</font>')), '/shop/' || mpc.main_cat_code || '/' || pc.cat_code, 'category', 0 FROM tbl_category AS pc JOIN tbl_main_category AS mpc ON pc.maincatid = mpc.maincatid WHERE pc.status = 1 AND ' ' || pc.catname LIKE '% ' || v_serchitem || '%' AND mpc.maincatid IN (SELECT maincategoryid FROM ims_masterproduct) AND pc.totalactive > 0 GROUP BY pc.catname, mpc.main_cat_code, pc.cat_code, mpc.maincatname;
  END IF;
  IF EXISTS(SELECT subcatid FROM tbl_sub_category WHERE status = 1 AND ' ' || subcatname LIKE '%' || v_serchitem || '%') THEN
  INSERT INTO tmp_temp SELECT DISTINCT (sc.subcatname) AS serachtext, (sc.subcatname || CONCAT('<font style="color:#2874f0; font-weight: 500;padding-left: 5px;">', ' in ' || LOWER(pc.catname) || '</font>')), '/shop/' || mpc.main_cat_code || '/' || pc.cat_code || '/' || sc.sub_cat_code, 'scategory', 0 FROM tbl_sub_category AS sc JOIN tbl_category AS pc ON sc.catid = pc.catid JOIN tbl_main_category AS mpc ON mpc.maincatid = pc.maincatid WHERE sc.status = 1 AND pc.status = 1 AND ' ' || sc.subcatname LIKE '% ' || v_serchitem || '%' AND mpc.maincatid IN (SELECT maincategoryid FROM ims_masterproduct) AND sc.totalactive > 0;
  END IF;
  INSERT INTO tmp_temp SELECT DISTINCT (CASE WHEN pms.stockin <> 0 THEN pmm.producttitle || '' WHEN pms.color <> '' THEN pmm.producttitle || ' (' || CAST(pms.color AS VARCHAR(100)) || ' )' WHEN pms.size <> '' THEN pmm.producttitle || ' (' || CAST(pms.size AS VARCHAR(100)) || ' )' ELSE pmm.producttitle END) AS searchresult, (pmm.producttitle || CONCAT('<font style="color:#2874f0; font-weight: 500;padding-left: 5px;">', ' in ' || LOWER(tc.catname) || '</font>')) AS fomatedresult, '/p/' || LOWER(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(CAST(pmm.producttitle AS VARCHAR(100)), ' ', '-'), '/', '-'), '|', '-'), ':', ''), '&', '-'), '%', '')) AS forurl, 'Product' AS searchtype, pms.sprid AS mprid FROM ims_masterproduct AS pmm INNER JOIN ims_subproduct AS pms ON pmm.mprid = pms.mprid INNER JOIN tbl_category AS tc ON pmm.catid = tc.catid WHERE pms.isactive = 1 AND ' ' || pmm.producttitle LIKE '%' || v_serchitem || '%' AND tc.totalactive > 0 AND pms.ismerchantstatus = 5 AND pms.isverified = 1;
  RETURN QUERY SELECT DISTINCT searchresult, fomatedresult, forurl, searchtype AS serachtext, mprid, dbo.fun_findcount(searchresult) AS cnt FROM tmp_temp ORDER BY cnt ASC NULLS FIRST LIMIT 10;
  DROP TABLE IF EXISTS tmp_temp;
  -- SET option (removed)
END;
$$;


--
-- Name: usp_datasearch_mobile(character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_datasearch_mobile(v_searchfilter character varying DEFAULT 'A'::character varying) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_count INT;
  v_serchitem VARCHAR(250);
BEGIN
  -- SET option (removed)
  v_serchitem := '';
  v_serchitem := v_searchfilter;
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp (SEARCHRESULT  text,
FOMATEDRESULT  text, 
FORURL text, 
SEARCHTYPE VARCHAR(200), 
MPRID BIGINT) ON COMMIT DROP;
  IF EXISTS(SELECT maincatid FROM tbl_main_category WHERE status = 1 AND ' ' || maincatname LIKE '% ' || v_serchitem || '%') THEN
  INSERT INTO tmp_temp SELECT DISTINCT (maincatname) AS serachtext, maincatname, '/shop/' || main_cat_code, 'maincategory', 0 FROM tbl_main_category WHERE status = 1 AND ' ' || maincatname LIKE '% ' || v_serchitem || '%';
  END IF;
  IF EXISTS(SELECT catid FROM tbl_category WHERE status = 1 AND ' ' || catname LIKE '% ' || v_serchitem || '%') THEN
  INSERT INTO tmp_temp SELECT DISTINCT (pc.catname) AS serachtext, (pc.catname || ' in ' || LOWER(pc.catname)), '/shop/' || mpc.main_cat_code || '/' || pc.cat_code, 'category', 0 FROM tbl_category AS pc JOIN tbl_main_category AS mpc ON pc.maincatid = mpc.maincatid WHERE pc.status = 1 AND ' ' || pc.catname LIKE '% ' || v_serchitem || '%' AND mpc.maincatid IN (SELECT maincategoryid FROM ims_masterproduct) AND pc.totalactive > 0 GROUP BY pc.catname, mpc.main_cat_code, pc.cat_code, mpc.maincatname;
  END IF;
  IF EXISTS(SELECT subcatid FROM tbl_sub_category WHERE status = 1 AND ' ' || subcatname LIKE '%' || v_serchitem || '%') THEN
  INSERT INTO tmp_temp SELECT DISTINCT (sc.subcatname) AS serachtext, ' in ' || LOWER(pc.catname), '/shop/' || mpc.main_cat_code || '/' || pc.cat_code || '/' || sc.sub_cat_code, 'scategory', 0 FROM tbl_sub_category AS sc JOIN tbl_category AS pc ON sc.catid = pc.catid JOIN tbl_main_category AS mpc ON mpc.maincatid = pc.maincatid WHERE sc.status = 1 AND pc.status = 1 AND ' ' || sc.subcatname LIKE '% ' || v_serchitem || '%' AND mpc.maincatid IN (SELECT maincategoryid FROM ims_masterproduct) AND sc.totalactive > 0;
  END IF;
  INSERT INTO tmp_temp SELECT DISTINCT (CASE WHEN pms.stockin <> 0 THEN pmm.producttitle || '' WHEN pms.color <> '' THEN pmm.producttitle || ' (' || CAST(pms.color AS VARCHAR(100)) || ' )' WHEN pms.size <> '' THEN pmm.producttitle || ' (' || CAST(pms.size AS VARCHAR(100)) || ' )' ELSE pmm.producttitle END) AS searchresult, (' in ' || LOWER(tc.catname)) AS fomatedresult, '/p/' || LOWER(REPLACE(CAST(pmm.producttitle AS VARCHAR(100)), ' ', '-')) AS forurl, 'Product' AS searchtype, pms.sprid AS mprid FROM ims_masterproduct AS pmm INNER JOIN ims_subproduct AS pms ON pmm.mprid = pms.mprid INNER JOIN tbl_category AS tc ON pmm.catid = tc.catid WHERE pms.isactive = 1 AND ' ' || pmm.producttitle LIKE '%' || v_serchitem || '%' AND tc.totalactive > 0 AND pms.ismerchantstatus = 5 AND pms.isverified = 1;
  RETURN QUERY SELECT DISTINCT (searchresult) AS producttitle, (fomatedresult) AS categoryin, searchtype AS producttext, (mprid) AS sprid, dbo.fun_findcount(searchresult) AS cnt FROM tmp_temp ORDER BY cnt ASC NULLS FIRST LIMIT 10;
  DROP TABLE IF EXISTS tmp_temp;
  -- SET option (removed)
END;
$$;


--
-- Name: usp_dateofjoining(timestamp without time zone, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_dateofjoining(v_doc timestamp without time zone, INOUT v_intresult integer) RETURNS integer
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_ist timestamp;
  v_dd varchar(10);
  v_lastdayofthemonth INT;
  v_ddcurrent int;
  v_payto timestamp;
  v_mm varchar(10);
  v_yy varchar(10);
  v_date VARCHAR(100);
  v_date1 VARCHAR(100);
  v_date2 VARCHAR(100);
BEGIN
  v_intresult := 0;
  v_lastdayofthemonth := EXTRACT(DAY FROM CAST(0 + (INTERVAL '1 MONTH' * (CAST(EXTRACT(year FROM AGE(CAST(CAST(CURRENT_TIMESTAMP AS TIMESTAMP) AS TIMESTAMP), CAST(CAST('1900-01-01' AS TIMESTAMP) AS TIMESTAMP))) * 12 + EXTRACT(month FROM AGE(CAST(CAST(CURRENT_TIMESTAMP AS TIMESTAMP) AS TIMESTAMP), CAST(CAST('1900-01-01' AS TIMESTAMP) AS TIMESTAMP))) AS BIGINT) + 1)) + INTERVAL '-1 SECOND' AS DATE));
  v_ist := GETUTCDATE() + INTERVAL '330 MI';
  v_ddcurrent := EXTRACT(DAY FROM v_ist);
  v_dd := EXTRACT(DAY FROM v_doc);
  v_mm := EXTRACT(MONTH FROM v_ist);
  v_yy := EXTRACT(YEAR FROM v_ist);
  IF (v_mm < 10) THEN
  v_mm := '0' || v_mm;
  END IF;
  IF (10 <= v_ddcurrent AND v_ddcurrent <= 25) THEN
  IF (CAST(v_yy AS VARCHAR(10)) || '-' || CAST(v_mm AS VARCHAR(10)) || '-' || '01' <= CAST(CAST(v_doc AS DATE) AS VARCHAR(100)) AND CAST(CAST(v_doc AS DATE) AS VARCHAR(100)) <= CAST(v_yy AS VARCHAR(10)) || '-' || CAST(v_mm AS VARCHAR(10)) || '-' || '15') THEN
  v_intresult := 1;
  ELSE
  v_intresult := 2;
  END IF;
  ELSE
  IF (26 <= v_ddcurrent OR v_ddcurrent < 10) THEN
  IF (26 <= v_ddcurrent AND v_ddcurrent <= 31) THEN
  IF (CAST(v_yy AS VARCHAR(10)) || '-' || CAST(v_mm AS VARCHAR(10)) || '-' || '16' <= CAST(CAST(v_doc AS DATE) AS VARCHAR(100)) AND CAST(CAST(v_doc AS DATE) AS VARCHAR(100)) <= CAST(v_yy AS VARCHAR(10)) || '-' || CAST(v_mm AS VARCHAR(10)) || '-' || '31') THEN
  v_intresult := 1;
  ELSE
  v_intresult := 3;
  END IF;
  ELSE
  IF (1 <= v_ddcurrent AND v_ddcurrent < 10) THEN
  v_mm := v_mm - 1;
  IF (v_mm < 10) THEN
  v_mm := '0' || v_mm;
  END IF;
  v_date := CAST(v_yy AS VARCHAR(10)) || '-' || CAST(v_mm AS VARCHAR(10)) || '-' || '16';
  v_date1 := CAST(v_yy AS VARCHAR(10)) || '-' || CAST(v_mm AS VARCHAR(10)) || '-' || '31';
  v_date2 := CAST(CAST(v_doc AS DATE) AS VARCHAR(100));
  IF (CAST(v_yy AS VARCHAR(10)) || '-' || CAST(v_mm AS VARCHAR(10)) || '-' || '16' <= CAST(CAST(v_doc AS DATE) AS VARCHAR(100)) AND CAST(CAST(v_doc AS DATE) AS VARCHAR(100)) <= CAST(v_yy AS VARCHAR(10)) || '-' || CAST(v_mm AS VARCHAR(10)) || '-' || '31') THEN
  v_intresult := 1;
  ELSE
  v_intresult := 3;
  END IF;
  END IF;
  END IF;
  END IF;
  END IF;
END;
$$;


--
-- Name: usp_datewise_listing_report(integer, integer, character varying, boolean, character varying, character varying, character varying, character varying, integer, character varying, character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_datewise_listing_report(v_startrowindex integer, v_maxrows integer, v_orderbyfield character varying, v_asc boolean, v_searchfield character varying, v_searchvalue character varying, v_fromdate character varying, v_todate character varying, v_mode integer, v_cid character varying, v_ctid character varying) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_recordcount int;
  v_minlistdate date;
  v_maxlistdate date;
  v_vrealfree int;
  v_vrealpaid int;
  v_voprfree int;
  v_voprpaid int;
  v_uvrealfree int;
  v_uvrealpaid int;
  v_uvoprfree int;
  v_uvoprpaid int;
BEGIN
  -- SET option (removed)
  DROP TABLE IF EXISTS tmp_temp_portal_master;
  CREATE TEMP TABLE tmp_temp_portal_master ON COMMIT DROP AS SELECT doc, optid, isverified, expirydate FROM portal_master WHERE pmid = 0;
  IF (v_ctid <> '') THEN
  IF (v_fromdate = '' OR v_todate = '') THEN
  IF (v_fromdate = '' AND v_todate <> '') THEN
  INSERT INTO tmp_temp_portal_master SELECT doc, optid, isverified, expirydate FROM portal_master WHERE COALESCE(ctid, 0) = v_ctid AND (TO_DATE(doc, 'MM-DD-YYYY') <= REPLACE(TO_DATE(v_todate, 'DD/MM/YYYY'), '/', '-'));
  ELSE
  IF (v_fromdate <> '' AND v_todate = '') THEN
  INSERT INTO tmp_temp_portal_master SELECT doc, optid, isverified, expirydate FROM portal_master WHERE COALESCE(ctid, 0) = v_ctid AND (TO_DATE(doc, 'MM-DD-YYYY') >= REPLACE(TO_DATE(v_fromdate, 'DD/MM/YYYY'), '/', '-'));
  ELSE
  INSERT INTO tmp_temp_portal_master SELECT doc, optid, isverified, expirydate FROM portal_master WHERE COALESCE(ctid, 0) = v_ctid;
  END IF;
  END IF;
  ELSE
  IF (v_fromdate <> '' AND v_todate <> '') THEN
  INSERT INTO tmp_temp_portal_master SELECT doc, optid, isverified, expirydate FROM portal_master WHERE COALESCE(ctid, 0) = v_ctid AND (TO_DATE(doc, 'MM-DD-YYYY')) BETWEEN v_fromdate AND v_todate;
  ELSE
  IF (v_fromdate <> '' AND v_todate = '') THEN
  INSERT INTO tmp_temp_portal_master SELECT doc, optid, isverified, expirydate FROM portal_master WHERE COALESCE(ctid, 0) = v_ctid AND (TO_DATE(doc, 'MM-DD-YYYY')) >= v_fromdate;
  ELSE
  IF (v_fromdate = '' AND v_todate <> '') THEN
  INSERT INTO tmp_temp_portal_master SELECT doc, optid, isverified, expirydate FROM portal_master WHERE COALESCE(ctid, 0) = v_ctid AND (TO_DATE(doc, 'MM-DD-YYYY')) <= v_todate;
  ELSE
  INSERT INTO tmp_temp_portal_master SELECT doc, optid, isverified, expirydate FROM portal_master WHERE COALESCE(ctid, 0) = v_ctid AND (TO_DATE(doc, 'MM-DD-YYYY') BETWEEN REPLACE(TO_DATE(v_fromdate, 'DD/MM/YYYY'), '/', '-') AND REPLACE(TO_DATE(v_todate, 'DD/MM/YYYY'), '/', '-'));
  END IF;
  END IF;
  END IF;
  END IF;
  ELSE
  IF (v_cid <> '') THEN
  IF (v_fromdate = '' OR v_todate = '') THEN
  IF (v_fromdate = '' AND v_todate <> '') THEN
  INSERT INTO tmp_temp_portal_master SELECT doc, optid, isverified, expirydate FROM portal_master WHERE COALESCE(cid, 0) = v_cid AND (TO_DATE(doc, 'MM-DD-YYYY') <= REPLACE(TO_DATE(v_todate, 'DD/MM/YYYY'), '/', '-'));
  ELSE
  IF (v_fromdate <> '' AND v_todate = '') THEN
  INSERT INTO tmp_temp_portal_master SELECT doc, optid, isverified, expirydate FROM portal_master WHERE COALESCE(cid, 0) = v_cid AND (TO_DATE(doc, 'MM-DD-YYYY') >= REPLACE(TO_DATE(v_fromdate, 'DD/MM/YYYY'), '/', '-'));
  ELSE
  INSERT INTO tmp_temp_portal_master SELECT doc, optid, isverified, expirydate FROM portal_master WHERE COALESCE(cid, 0) = v_cid;
  END IF;
  END IF;
  ELSE
  INSERT INTO tmp_temp_portal_master SELECT doc, optid, isverified, expirydate FROM portal_master WHERE COALESCE(cid, 0) = v_cid AND (TO_DATE(doc, 'MM-DD-YYYY') BETWEEN REPLACE(TO_DATE(v_fromdate, 'DD/MM/YYYY'), '/', '-') AND REPLACE(TO_DATE(v_todate, 'DD/MM/YYYY'), '/', '-'));
  END IF;
  ELSE
  IF (v_fromdate = '' OR v_todate = '') THEN
  IF (v_fromdate = '' AND v_todate <> '') THEN
  INSERT INTO tmp_temp_portal_master SELECT doc, optid, isverified, expirydate FROM portal_master WHERE (TO_DATE(doc, 'MM-DD-YYYY') <= REPLACE(TO_DATE(v_todate, 'DD/MM/YYYY'), '/', '-'));
  ELSE
  IF (v_fromdate <> '' AND v_todate = '') THEN
  INSERT INTO tmp_temp_portal_master SELECT doc, optid, isverified, expirydate FROM portal_master WHERE (TO_DATE(doc, 'MM-DD-YYYY') >= REPLACE(TO_DATE(v_fromdate, 'DD/MM/YYYY'), '/', '-'));
  ELSE
  INSERT INTO tmp_temp_portal_master SELECT doc, optid, isverified, expirydate FROM portal_master;
  END IF;
  END IF;
  ELSE
  INSERT INTO tmp_temp_portal_master SELECT doc, optid, isverified, expirydate FROM portal_master WHERE (TO_DATE(doc, 'MM-DD-YYYY') BETWEEN REPLACE(TO_DATE(v_fromdate, 'DD/MM/YYYY'), '/', '-') AND REPLACE(TO_DATE(v_todate, 'DD/MM/YYYY'), '/', '-'));
  END IF;
  END IF;
  END IF;
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp (listingdate date) ON COMMIT DROP;
  INSERT INTO tmp_temp (listingdate) SELECT DISTINCT CAST(COALESCE(doc, '') AS DATE) FROM tmp_temp_portal_master WHERE CAST(COALESCE(doc, '') AS DATE) <> '1900-01-01';
  DROP TABLE IF EXISTS tmp_tempresult;
  CREATE TEMP TABLE tmp_tempresult (rowNumber int GENERATED BY DEFAULT AS IDENTITY,
listingdate date,
VRealFree int default(0),
VRealPaid int default(0),
VOprFree int default(0),
VOprPaid int default(0),
UVRealFree int default(0),
UVRealPaid int default(0),
UVOprFree int default(0),
UVOprPaid int default(0),
total int default(0)) ON COMMIT DROP;
  SELECT MIN(listingdate) INTO v_minlistdate FROM tmp_temp;
  SELECT MAX(listingdate) INTO v_maxlistdate FROM tmp_temp;
  WHILE (v_maxlistdate >= v_minlistdate) LOOP
  IF EXISTS(SELECT 1 FROM tmp_temp WHERE listingdate = v_maxlistdate) THEN
  SELECT COUNT(1) INTO v_vrealfree FROM tmp_temp_portal_master WHERE COALESCE(optid, 0) = 0 AND isverified = 1 AND COALESCE(expirydate, '1900-01-01 00:00:00.000') = '1900-01-01 00:00:00.000' AND (TO_DATE(doc, 'MM-DD-YYYY') = REPLACE(TO_DATE(v_maxlistdate, 'DD/MM/YYYY'), '/', '-'));
  SELECT COUNT(1) INTO v_vrealpaid FROM tmp_temp_portal_master WHERE COALESCE(optid, 0) = 0 AND isverified = 1 AND COALESCE(expirydate, '1900-01-01 00:00:00.000') <> '1900-01-01 00:00:00.000' AND (TO_DATE(doc, 'MM-DD-YYYY') = REPLACE(TO_DATE(v_maxlistdate, 'DD/MM/YYYY'), '/', '-'));
  SELECT COUNT(1) INTO v_voprfree FROM tmp_temp_portal_master WHERE COALESCE(optid, 0) > 0 AND isverified = 1 AND COALESCE(expirydate, '1900-01-01 00:00:00.000') = '1900-01-01 00:00:00.000' AND (TO_DATE(doc, 'MM-DD-YYYY') = REPLACE(TO_DATE(v_maxlistdate, 'DD/MM/YYYY'), '/', '-'));
  SELECT COUNT(1) INTO v_voprpaid FROM tmp_temp_portal_master WHERE COALESCE(optid, 0) = 0 AND isverified = 1 AND COALESCE(expirydate, '1900-01-01 00:00:00.000') <> '1900-01-01 00:00:00.000' AND (TO_DATE(doc, 'MM-DD-YYYY') = REPLACE(TO_DATE(v_maxlistdate, 'DD/MM/YYYY'), '/', '-'));
  SELECT COUNT(1) INTO v_uvrealfree FROM tmp_temp_portal_master WHERE COALESCE(optid, 0) = 0 AND isverified = 0 AND COALESCE(expirydate, '1900-01-01 00:00:00.000') = '1900-01-01 00:00:00.000' AND (TO_DATE(doc, 'MM-DD-YYYY') = REPLACE(TO_DATE(v_maxlistdate, 'DD/MM/YYYY'), '/', '-'));
  SELECT COUNT(1) INTO v_uvrealpaid FROM tmp_temp_portal_master WHERE COALESCE(optid, 0) = 0 AND isverified = 0 AND COALESCE(expirydate, '1900-01-01 00:00:00.000') <> '1900-01-01 00:00:00.000' AND (TO_DATE(doc, 'MM-DD-YYYY') = REPLACE(TO_DATE(v_maxlistdate, 'DD/MM/YYYY'), '/', '-'));
  SELECT COUNT(1) INTO v_uvoprfree FROM tmp_temp_portal_master WHERE COALESCE(optid, 0) > 0 AND isverified = 0 AND COALESCE(expirydate, '1900-01-01 00:00:00.000') = '1900-01-01 00:00:00.000' AND (TO_DATE(doc, 'MM-DD-YYYY') = REPLACE(TO_DATE(v_maxlistdate, 'DD/MM/YYYY'), '/', '-'));
  SELECT COUNT(1) INTO v_uvoprpaid FROM tmp_temp_portal_master WHERE COALESCE(optid, 0) = 0 AND isverified = 0 AND COALESCE(expirydate, '1900-01-01 00:00:00.000') <> '1900-01-01 00:00:00.000' AND (TO_DATE(doc, 'MM-DD-YYYY') = REPLACE(TO_DATE(v_maxlistdate, 'DD/MM/YYYY'), '/', '-'));
  INSERT INTO tmp_tempresult VALUES (v_maxlistdate, v_vrealfree, v_vrealpaid, v_voprfree, v_voprpaid, v_uvrealfree, v_uvrealpaid, v_uvoprfree, v_uvoprpaid, v_vrealfree + v_vrealpaid + v_voprfree + v_voprpaid + v_uvrealfree + v_uvrealpaid + v_uvoprfree + v_uvoprpaid);
  END IF;
  v_maxlistdate := v_maxlistdate + INTERVAL '-1 DAY';
  END LOOP;
  SELECT COUNT(*) INTO v_recordcount FROM tmp_tempresult;
  RETURN QUERY SELECT * FROM tmp_tempresult WHERE rownumber BETWEEN v_startrowindex AND v_maxrows;
  RETURN QUERY SELECT v_recordcount AS recordcount;
  DROP TABLE IF EXISTS tmp_tempresult;
  DROP TABLE IF EXISTS tmp_temp;
  DROP TABLE IF EXISTS tmp_temp_portal_master;
  -- SET option (removed)
END;
$$;


--
-- Name: usp_deactivatevisitor(integer, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_deactivatevisitor(v_vmid integer, INOUT v_intresult integer) RETURNS integer
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_active int;
BEGIN
  -- SET option (removed)
  SELECT active INTO v_active FROM visitor_master WHERE vmid = v_vmid;
  IF (v_active = 1) THEN
  UPDATE visitor_master SET active = 0, delete_or_deactivedate = CURRENT_TIMESTAMP WHERE vmid = v_vmid;
  UPDATE visitor_login SET active = 0;
  v_intresult := 1;
  ELSE
  IF (v_active = 0) THEN
  UPDATE visitor_master SET active = 1, delete_or_deactivedate = NULL WHERE vmid = v_vmid;
  UPDATE visitor_login SET active = 1;
  v_intresult := 2;
  END IF;
  END IF;
  -- SET option (removed)
END;
$$;


--
-- Name: usp_deactivatinglekeyword(integer, integer, integer, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_deactivatinglekeyword(v_kmid integer DEFAULT 0, v_smcid integer DEFAULT 0, v_status integer DEFAULT 0, INOUT v_intresult integer DEFAULT NULL::integer) RETURNS integer
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_keywordid text;
  v_previousstatus int;
BEGIN
  -- BEGIN TRAN (removed)
  SELECT searchactive INTO v_previousstatus FROM tbl_sponsor_search WHERE smcid = v_smcid AND keyid = v_kmid;
  IF (v_previousstatus = 1) THEN
  UPDATE tbl_sponsor_search SET searchactive = 0 WHERE smcid = v_smcid AND keyid = v_kmid;
  v_intresult := 0;
  ELSE
  IF (v_previousstatus = 0) THEN
  UPDATE tbl_sponsor_search SET searchactive = 1 WHERE smcid = v_smcid AND keyid = v_kmid;
  v_intresult := 1;
  END IF;
  END IF;
  SELECT COALESCE(v_keywordid || ',', '') || CAST(keyid AS VARCHAR(15)) INTO v_keywordid FROM (SELECT DISTINCT keyid FROM tbl_sponsor_search WHERE smcid = v_smcid AND searchactive = 1) AS newtbl_sponser;
  UPDATE tbl_sponsor_master_campain SET keywordid = v_keywordid WHERE smcid = v_smcid;
  IF (0 <> 0) THEN
  v_intresult := 0;
  -- ROLLBACK (removed)
  END IF;
  -- COMMIT (removed)
END;
$$;


--
-- Name: usp_deactive_attribute_list(integer, integer, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_deactive_attribute_list(v_startrowindex integer DEFAULT 1, v_maxrows integer DEFAULT 100, v_totalcount integer DEFAULT 0) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_minindex INT;
  v_maxindex INT;
  v_query text;
  v_queryresult VARCHAR(500);
  v_total INT;
  v_count INT;
  v_tempdid Int;
  v_categoryname text;
BEGIN
  v_queryresult := '';
  v_total := 0;
  v_count := 1;
  v_tempdid := 0;
  v_categoryname := '';
  v_minindex := (v_startrowindex - 1) * v_maxrows + 1;
  v_maxindex := v_startrowindex * v_maxrows;
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp (ROWNUMBER BIGINT GENERATED BY DEFAULT AS IDENTITY,
DDID INT,
NAME VARCHAR(100),
DESCRIPTION VARCHAR(500),
STATUS INT,
CATEGORY text) ON COMMIT DROP;
  v_query := ' INSERT INTO #TEMP SELECT DDID,NAME,DESCRIPTION,STATUS,'''' FROM TBL_DROPDOWN  
 WHERE STATUS=0 ';
  EXECUTE v_query;
  SELECT COUNT(*) INTO v_total FROM tmp_temp;
  DROP TABLE IF EXISTS tmp_demotemp;
  CREATE TEMP TABLE tmp_demotemp (Rownumber int GENERATED BY DEFAULT AS IDENTITY not null,subcatid int) ON COMMIT DROP;
  WHILE (v_total >= v_count) LOOP
  SELECT ddid INTO v_tempdid FROM tmp_temp WHERE rownumber = v_count;
  INSERT INTO tmp_demotemp SELECT sub_cat_id FROM tbl_attributes_with_category WHERE ddl_id = v_tempdid;
  SELECT COALESCE(v_categoryname || ',', '') || COALESCE(tsc.subcatname, '') INTO v_categoryname FROM tmp_demotemp AS dm LEFT JOIN tbl_sub_category AS tsc ON dm.subcatid = tsc.subcatid;
  v_categoryname := SUBSTRING(v_categoryname FROM 2 FOR LENGTH(CAST(v_categoryname AS TEXT)));
  UPDATE tmp_temp SET category = v_categoryname WHERE rownumber = v_count;
  v_categoryname := '';
  TRUNCATE TABLE tmp_demotemp;
  v_count := v_count + 1;
  END LOOP;
  RETURN QUERY SELECT * FROM tmp_temp WHERE rownumber BETWEEN v_minindex AND v_maxindex;
  SELECT COUNT(rownumber) INTO v_totalcount FROM tmp_temp;
  DROP TABLE IF EXISTS tmp_temp;
  DROP TABLE IF EXISTS tmp_demotemp;
  -- SET option (removed)
END;
$$;


--
-- Name: usp_deactive_product_list(integer, integer, character varying, character varying, character varying, character varying, character varying, integer, character varying, character varying, character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_deactive_product_list(v_startrowindex integer DEFAULT 1, v_maxrows integer DEFAULT 1000, v_searchfield character varying DEFAULT ''::character varying, v_searchvalue character varying DEFAULT ''::character varying, v_fromdate character varying DEFAULT ''::character varying, v_todate character varying DEFAULT ''::character varying, v_company character varying DEFAULT '1'::character varying, v_totalcount integer DEFAULT 0, v_searchvaluesubcategory character varying DEFAULT ''::character varying, v_merchantname character varying DEFAULT ''::character varying, v_productname character varying DEFAULT ''::character varying) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_minindex INT;
  v_maxindex INT;
  v_query text;
  v_catecode INT;
BEGIN
  v_minindex := (v_startrowindex - 1) * v_maxrows + 1;
  v_maxindex := v_startrowindex * v_maxrows;
  DROP TABLE IF EXISTS tmp_productlisttemp;
  CREATE TEMP TABLE tmp_productlisttemp (ROWNUMBER BIGINT GENERATED BY DEFAULT AS IDENTITY




,MPRID BIGINT 
,PRODUCTCODE VARCHAR( 50) 
,SUBPRCODE VARCHAR( 50) 
,PRODUCTTITLE VARCHAR( 300) 
,MAINCATNAME VARCHAR( 250) 
,QTY INT 
,UNIT VARCHAR( 50) 
,PRODUCTIMAGES VARCHAR( 1000) 
,MerchantName VARCHAR( 1000) 
,EMAILID VARCHAR( 100) 
,PHONE VARCHAR( 100) 
,SELLMRP DECIMAL 
,DAP DECIMAL 
,SPRID BIGINT 
,ISACTIVE boolean  ,
PROCUREMENTSLA INT,
REPLACEMENTDAY INT,
SHIPPINGCHARGES DECIMAL(18,2),
CASHONDELIVERY boolean,
WEIGHT_KG DECIMAL(18,2),
LENGTH_CMS DECIMAL(18,2),
BREADTH_CMS DECIMAL(18,2),
HEIGHT_CMS DECIMAL(18,2)
,MVAT DECIMAL 
,DEALSIDS VARCHAR(100)
,STOCKINQTY INT 
,STOCKOUTQTY INT 
,STOCKNETQTY INT 
,ISSTOCK boolean 
,VATTITLE VARCHAR(100) 
,PRODUCTCOUNT INT,
BV DECIMAL(18,2),
JP DECIMAL(18,2),
pmid bigint,
Title varchar(1000),
Value varchar(1000),
COMPANYNAME VARCHAR(100),
CreatedDate varchar(100),
ModifyDate varchar(100),
ismerchantstatus int,
Discountpercentage decimal,
Subcategory varchar(500)) ON COMMIT DROP;
  v_query := 'INSERT INTO #PRODUCTLISTTEMP SELECT PM.MPRID,PM.PRODUCTCODE,SM.SUBPRCODE,PM.PRODUCTTITLE, MC.MAINCATNAME,SM.QTY,SM.UNIT,
SM.PRODUCTIMAGES,ISNULL((PMA.COMPANYNAME),'''') as MerchantName,ISNULL(PL.EMAILID,'''') AS EMAILID,ISNULL(PL.PHONE,'''')AS PHONE,
SM.SELLMRP,SM.DAP,SM.SPRID,SM.ISACTIVE,ISNULL(SM.PROCUREMENTSLA,0),ISNULL(SM.REPLACEMENTDAY,0),
CONVERT(DECIMAL(18,2),SM.SHIPPINGCHARGES),ISNULL(SM.CASHONDELIVERY,0),ISNULL(SM.WEIGHT_KG,0),ISNULL(SM.LENGTH_CMS,0),ISNULL(SM.BREADTH_CMS,0),ISNULL(SM.HEIGHT_CMS,0),
CONVERT(DECIMAL(18,0),ISNULL(V.VATPERCVALUE,0)) AS MVAT, ISNULL(SM.DEALSIDS,'''')
,ISNULL(SM.STOCKIN,0),ISNULL(SM.STOCKOUT,0),ISNULL(SM.STOCKNET,0),CONVERT(BIT, (CASE WHEN ISNULL(SM.STOCKNET,0) <= 0 THEN 0 ELSE 1 END)) AS ISSTOCK,V.VATTITLE,0 AS PRODUCTCOUNT,isnull(SM.BV,0) as BV ,
isnull(SM.PV,0) as JP,pma.PMID,'''' as Title,'''' as Value,PMA.COMPANYNAME,isnull(SM.CreatedDate,''''),isnull(SM.ModifyDate,''''),
isnull(SM.ismerchantstatus,0),isnull(SM.DiscountPercentage,0) as DiscountPercentage,isnull(km.subcatname,'''') AS Subcategory
FROM IMS_MASTERPRODUCT PM INNER JOIN IMS_SUBPRODUCT SM ON SM.MPRID=PM.MPRID 
INNER JOIN TBL_MAIN_CATEGORY MC ON MC.MAINCATID =PM.MAINCATEGORYID			 
LEFT  JOIN TBL_VAT_CATEGORIES V ON V.VCID = PM.VATCATEGORYID 
LEFT  JOIN PORTAL_LOGIN PL ON PL.PLID= PM.BranchId
left join Portal_Master pma on pma.PMID=pl.PMID
 LEFT join tbl_sub_category km on PM.SubCategoryId=km.subcatid
WHERE PM.MPRID >0  and SM.IsVerified=3';
  IF (v_company <> '') THEN
  v_query := v_query || ' AND pma.PMID LIKE ''%' || v_company || '%'' ';
  END IF;
  IF (v_merchantname <> '') THEN
  v_query := v_query || ' AND (PMA.COMPANYNAME) LIKE ''%' || v_merchantname || '%'' ';
  END IF;
  IF (v_searchvaluesubcategory <> '') THEN
  v_searchvaluesubcategory := REPLACE(v_searchvaluesubcategory, '''', '''''');
  v_query := v_query || 'AND km.subcatname LIKE''%' || v_searchvaluesubcategory || '%''';
  END IF;
  IF (v_searchfield = 'EMAILID') THEN
  v_query := v_query || ' AND PL.Emailid LIKE ''%' || v_searchvalue || '%'' ';
  END IF;
  IF (v_productname <> '') THEN
  v_productname := REPLACE(v_productname, '''', '''''');
  v_query := v_query || ' and PM.ProductTitle =''' || v_productname || '''';
  END IF;
  IF (v_searchfield = 'PHONE') THEN
  v_query := v_query || ' AND PL.PHONE LIKE ''%' || v_searchvalue || '%'' ';
  END IF;
  IF (v_searchfield = 'PRODUCTTITLE') THEN
  v_query := v_query || ' AND PM.PRODUCTTITLE LIKE ''%' || v_searchvalue || '%'' ';
  END IF;
  IF (v_searchfield = 'MAINCATNAME') THEN
  v_query := v_query || ' AND MC.MAINCATNAME LIKE ''%' || v_searchvalue || '%'' ';
  END IF;
  IF (v_fromdate = '' OR v_todate = '') THEN
  IF (v_fromdate <> '') THEN
  v_query := v_query || ' AND CONVERT(DATE, SM.ModifyDate,103) >= REPLACE(CONVERT(DATE,''' || v_fromdate || ''',103),''/'',''-'') ';
  END IF;
  IF (v_todate <> '') THEN
  v_query := v_query || ' AND CONVERT(DATE, SM.ModifyDate,103)  <=REPLACE(CONVERT(DATE,''' || v_todate || ''',103),''/'',''-'') ';
  END IF;
  END IF;
  IF (v_fromdate <> '' AND v_todate <> '') THEN
  v_query := v_query || '  AND  CONVERT(DATE, SM.ModifyDate,103)  BETWEEN  REPLACE(CONVERT(DATE,''' || v_fromdate || ''',103),''/'',''-'')  AND REPLACE(CONVERT(DATE,''' || v_todate || ''',103),''/'',''-'')';
  END IF;
  v_query := v_query || ' ORDER BY  PM.MPRID DESC ';
  EXECUTE v_query;
  RAISE NOTICE '%', v_query;
  RETURN QUERY SELECT * FROM tmp_productlisttemp WHERE rownumber BETWEEN v_minindex AND v_maxindex;
  SELECT COUNT(rownumber) INTO v_totalcount FROM tmp_productlisttemp;
  DROP TABLE IF EXISTS tmp_productlisttemp;
  -- SET option (removed)
END;
$$;


--
-- Name: usp_deactive_products(integer, integer, character varying, character varying, character varying, character varying, integer, character varying, character varying, character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_deactive_products(v_startrowindex integer DEFAULT 1, v_maxrows integer DEFAULT 100, v_searchfield character varying DEFAULT ''::character varying, v_searchvalue character varying DEFAULT ''::character varying, v_fromdate character varying DEFAULT ''::character varying, v_todate character varying DEFAULT ''::character varying, v_totalcount integer DEFAULT 0, v_searchvaluesubcategory character varying DEFAULT ''::character varying, v_merchantname character varying DEFAULT ''::character varying, v_productname character varying DEFAULT ''::character varying) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_minindex int;
  v_maxindex int;
  v_query text;
  v_catecode INT;
BEGIN
  v_minindex := (v_startrowindex - 1) * v_maxrows + 1;
  v_maxindex := v_startrowindex * v_maxrows;
  DROP TABLE IF EXISTS tmp_productlisttemp;
  CREATE TEMP TABLE tmp_productlisttemp (ROWNUMBER BIGINT GENERATED BY DEFAULT AS IDENTITY 
	,MPRID BIGINT 
	,PRODUCTCODE VARCHAR( 50) 
	,SUBPRCODE VARCHAR( 50) 
	,PRODUCTTITLE VARCHAR( 300) 
	,MAINCATNAME VARCHAR( 250) 
	,QTY INT 
	,UNIT VARCHAR( 50) 
	,PRODUCTIMAGES VARCHAR( 1000) 
	,SELLMRP DECIMAL 
	,DAP DECIMAL 
	,SPRID BIGINT 
	,ISACTIVE boolean
	,PROCUREMENTSLA INT
	,REPLACEMENTDAY INT
	,SHIPPINGCHARGES DECIMAL(18,2)
	,CASHONDELIVERY boolean
	,WEIGHT_KG DECIMAL(18,2)
	,LENGTH_CMS DECIMAL(18,2)
	,BREADTH_CMS DECIMAL(18,2)
	,HEIGHT_CMS DECIMAL(18,2)
	,MVAT DECIMAL 
	,DEALSIDS VARCHAR(100)
	,STOCKINQTY INT 
	,STOCKOUTQTY INT 
	,STOCKNETQTY INT 
	,ISSTOCK boolean 
	,VATTITLE VARCHAR(100) 
	,PRODUCTCOUNT INT
	,ISVERIFIED INT,
	CreatedDate timestamp,
    ModifyDate timestamp,
    ismerchantstatus int,
    Discountpercentage decimal,
    Subcategory varchar(500)
	,MerchantName VARCHAR( 1000) 
   ,EMAILID VARCHAR( 100) 
   ,PHONE VARCHAR( 100)
    ,BV DECIMAL(18,2),
     JP DECIMAL(18,2)) ON COMMIT DROP;
  v_query := 'INSERT INTO #PRODUCTLISTTEMP SELECT PM.MPRID,PM.PRODUCTCODE,SM.SUBPRCODE,PM.PRODUCTTITLE, MC.MAINCATNAME,SM.QTY,SM.UNIT,SM.ProductImages,
    SM.SELLMRP,SM.DAP,SM.SPRID,SM.ISACTIVE,ISNULL(SM.PROCUREMENTSLA,0),ISNULL(SM.REPLACEMENTDAY,0),
	CONVERT(DECIMAL(18,2),SM.SHIPPINGCHARGES),ISNULL(SM.CASHONDELIVERY,0),ISNULL(SM.WEIGHT_KG,0),ISNULL(SM.LENGTH_CMS,0),ISNULL(SM.BREADTH_CMS,0),ISNULL(SM.HEIGHT_CMS,0),
	CONVERT(DECIMAL(18,0),ISNULL(V.VATPERCVALUE,0)) AS MVAT, ISNULL(SM.DEALSIDS,'''')
	,ISNULL(SM.STOCKIN,0),ISNULL(SM.STOCKOUT,0),ISNULL(SM.STOCKNET,0),CONVERT(BIT, (CASE WHEN ISNULL(SM.STOCKNET,0) <= 0 THEN 0 ELSE 1 END)) AS ISSTOCK,V.VATTITLE,
	0 AS PRODUCTCOUNT,SM.ISVERIFIED,
	isnull(SM.CreatedDate,''''),isnull(SM.ModifyDate,''''),
    isnull(SM.ismerchantstatus,0),isnull(SM.DiscountPercentage,0) as DiscountPercentage,isnull(km.subcatname,'''') AS Subcategory,
	ISNULL((PMA.COMPANYNAME),'''') as MerchantName,ISNULL(PL.EMAILID,'''') AS EMAILID,ISNULL(PL.PHONE,'''')AS PHONE,isnull(SM.BV,0) as BV ,isnull(SM.PV,0) as JP
    FROM IMS_MASTERPRODUCT PM 
    INNER JOIN IMS_SUBPRODUCT SM ON SM.MPRID=PM.MPRID 
    INNER JOIN TBL_MAIN_CATEGORY MC ON MC.MAINCATID =PM.MAINCATEGORYID			 
	LEFT  JOIN TBL_VAT_CATEGORIES V ON V.VCID = PM.VATCATEGORYID 
	LEFT join tbl_sub_category km on PM.SubCategoryId=km.subcatid
	LEFT  JOIN PORTAL_LOGIN PL ON PL.PLID= PM.BranchId
	left join Portal_Master pma on pma.PMID=pl.PMID
	WHERE  SM.IsVerified=3';
  IF ((v_searchfield <> '') AND (v_searchvalue <> '')) THEN
  IF (v_searchfield = 'PRODUCTTITLE') THEN
  v_query := v_query || ' And  PM.PRODUCTTITLE  LIKE''%' || v_searchvalue || '%''';
  END IF;
  IF (v_searchfield = 'MAINCATNAME') THEN
  v_query := v_query || ' And MC.MAINCATNAME LIKE ''%' || v_searchvalue || '%''';
  END IF;
  END IF;
  IF (v_merchantname <> '') THEN
  v_query := v_query || ' AND (PMA.COMPANYNAME) LIKE ''%' || v_merchantname || '%'' ';
  END IF;
  IF (v_productname <> '') THEN
  v_productname := REPLACE(v_productname, '''', '''''');
  v_query := v_query || ' and PM.ProductTitle =''' || v_productname || '''';
  END IF;
  IF (v_searchvaluesubcategory <> '') THEN
  v_searchvaluesubcategory := REPLACE(v_searchvaluesubcategory, '''', '''''');
  v_query := v_query || 'AND (km.subcatname) LIKE''%' || v_searchvaluesubcategory || '%''';
  END IF;
  IF (v_fromdate = '' OR v_todate = '') THEN
  IF (v_fromdate <> '') THEN
  v_query := v_query || ' AND CONVERT(DATE, SM.ModifyDate,103) >= REPLACE(CONVERT(DATE,''' || v_fromdate || ''',103),''/'',''-'') ';
  END IF;
  IF (v_todate <> '') THEN
  v_query := v_query || ' AND CONVERT(DATE, SM.ModifyDate,103)  <=REPLACE(CONVERT(DATE,''' || v_todate || ''',103),''/'',''-'') ';
  END IF;
  END IF;
  IF (v_fromdate <> '' AND v_todate <> '') THEN
  v_query := v_query || '  AND  CONVERT(DATE, SM.ModifyDate,103)  BETWEEN  REPLACE(CONVERT(DATE,''' || v_fromdate || ''',103),''/'',''-'')  AND REPLACE(CONVERT(DATE,''' || v_todate || ''',103),''/'',''-'')';
  END IF;
  v_query := v_query || ' ORDER BY PM.ModifyDate Desc ';
  EXECUTE v_query;
  RETURN QUERY SELECT * FROM tmp_productlisttemp WHERE rownumber BETWEEN v_minindex AND v_maxindex ORDER BY rownumber ASC NULLS FIRST;
  SELECT COUNT(rownumber) INTO v_totalcount FROM tmp_productlisttemp;
  DROP TABLE IF EXISTS tmp_productlisttemp;
  -- SET option (removed)
END;
$$;


--
-- Name: usp_deactiveattributelist(integer, character varying, character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_deactiveattributelist(v_mode integer DEFAULT 0, v_attrbuteid character varying DEFAULT ''::character varying, INOUT v_strout character varying DEFAULT ''::character varying) RETURNS character varying
    LANGUAGE plpgsql
    AS $$
BEGIN
  -- BEGIN TRAN (removed)
  IF (v_attrbuteid = '') THEN
  v_strout := 'ID IS NOT MATCHED';
  -- COMMIT (removed)
  RETURN;
  END IF;
  IF (v_attrbuteid <> '') THEN
  IF (v_mode = 1) THEN
  UPDATE tbl_dropdown SET status = 0, modifyon = CURRENT_TIMESTAMP WHERE ddid = v_attrbuteid;
  UPDATE tbl_attributes_with_category SET is_active = 0 WHERE ddl_id = v_attrbuteid;
  v_strout := 'OK';
  ELSE
  UPDATE tbl_dropdown SET status = 1, modifyon = CURRENT_TIMESTAMP WHERE ddid = v_attrbuteid;
  UPDATE tbl_attributes_with_category SET is_active = 1 WHERE ddl_id = v_attrbuteid;
  v_strout := 'OK';
  END IF;
  END IF;
  IF (0 <> 0) THEN
  v_strout := 'ERROR OCCURRED  PLEASE TRY LATER';
  -- ROLLBACK (removed)
  RETURN;
  END IF;
  -- COMMIT (removed)
END;
$$;


--
-- Name: usp_deal_details(character varying, integer, integer, character varying, character varying, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_deal_details(v_plid character varying DEFAULT ''::character varying, v_startrowindex integer DEFAULT 1, v_maxrows integer DEFAULT 100, v_fromdate character varying DEFAULT ''::character varying, v_todate character varying DEFAULT ''::character varying, v_recordcount integer DEFAULT 0) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_pmid VARCHAR(50);
  v_sqlquery text;
BEGIN
  v_pmid := '0';
  SELECT pmid INTO v_pmid FROM portal_master WHERE plid = v_plid;
  -- SET option (removed)
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp (ROWNUMBER INT,
ID BIGINT,
ACTIVESTATUS VARCHAR(20),
IMAGENAME VARCHAR(250),
TITLE VARCHAR(100),
CREATEDATE DATE,
FROMDATE DATE,
EXPIRYDATE DATE,
OFFER VARCHAR(200),
DESCRIPTIONS text,
Responses Int) ON COMMIT DROP;
  v_sqlquery := '';
  v_sqlquery := ' INSERT INTO #TEMP SELECT ROW_NUMBER() OVER(ORDER BY DEALID Desc) AS ROWNUMBER ,DEALID,
CASE WHEN ISNULL(ACTIVE,0)=1 THEN (CASE ISNULL(VERIFY,0) WHEN 1 THEN ''Active'' WHEN 2 Then ''Rejected'' ELSE ''Inactive'' END) ELSE ''Deactive'' END AS STATUS,
LEFT(IMAGES, CHARINDEX ('','', IMAGES + '','') - 1) AS IMAGE ,TITLE,CAST(CREATEDATE AS DATE) AS CREATEDATE,
CAST(FROMTIME AS DATE) AS FROMTIME,CAST(TOTIME AS DATE) AS TOTIME,
CASE ISNULL(STARTPRICE,0) WHEN 0 THEN OFFER ELSE OFFER + '' STARTING FROM '' + CONVERT(VARCHAR(20),STARTPRICE)
END AS REWARD,DESCRIPTION,(select Count(1) From PORTAL_DEAL_INBOX where Dealid in (PDM.DEALID)) as Responses
FROM PORTAL_DEAL_MASTER PDM WHERE (ISNULL(ACTIVE,0) IN (0,1)) AND  (ISNULL(VERIFY,0) IN (0,1,2))';
  IF (v_pmid <> '') THEN
  v_sqlquery := v_sqlquery || (' AND PMID=' || v_pmid || '');
  END IF;
  IF (v_fromdate = '' OR v_todate = '') THEN
  IF (v_fromdate <> '') THEN
  v_sqlquery := v_sqlquery || ' AND CONVERT(DATE,CREATEDATE,103) => REPLACE(CONVERT(DATE,''' || v_fromdate || ''',103),''/'',''-'') ';
  END IF;
  IF (v_todate <> '') THEN
  v_sqlquery := v_sqlquery || ' AND CONVERT(DATE, CREATEDATE,103) <= REPLACE(CONVERT(DATE,''' || v_todate || ''',103),''/'',''-'') ';
  END IF;
  END IF;
  IF (v_fromdate <> '' AND v_todate <> '') THEN
  v_sqlquery := v_sqlquery || ' AND  CONVERT(DATE,CREATEDATE,103)  BETWEEN  REPLACE(CONVERT(DATE,''' || v_fromdate || ''',103),''/'',''-'')
		                             AND REPLACE(CONVERT(DATE,''' || v_todate || ''',103),''/'',''-'')';
  END IF;
  EXECUTE v_sqlquery;
  SELECT COUNT(id) INTO v_recordcount FROM tmp_temp;
  RETURN QUERY SELECT rownumber, id, activestatus, imagename, title, CAST(TO_CHAR(createdate, 'DD TMMon YYYY') AS VARCHAR(11)) AS createdate, CAST(TO_CHAR(fromdate, 'DD TMMon YYYY') AS VARCHAR(11)) AS fromdate, CAST(TO_CHAR(expirydate, 'DD TMMon YYYY') AS VARCHAR(11)) AS expirydate, offer, descriptions, responses FROM tmp_temp WHERE rownumber BETWEEN v_startrowindex AND v_maxrows;
  IF (0 <> 0) THEN
  v_recordcount := 0;
  END IF;
  DROP TABLE IF EXISTS tmp_temp;
  RETURN QUERY SELECT v_recordcount AS recordcount;
  -- SET option (removed)
END;
$$;


--
-- Name: usp_dealsforyou(text, integer, integer, integer, integer, integer, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_dealsforyou(v_ipaddress text DEFAULT ''::text, v_plid integer DEFAULT 0, v_maincatid integer DEFAULT 0, v_catid integer DEFAULT 0, v_scatid integer DEFAULT 0, v_productid integer DEFAULT 0, INOUT v_intresult integer DEFAULT 0) RETURNS integer
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_currentdatetime timestamp;
BEGIN
  v_intresult := 0;
  v_currentdatetime := dbo.FUN_GETCURRENTDATE();
  IF NOT EXISTS(SELECT 1 FROM tbl_dealsforyou WHERE (plid = (CASE WHEN v_plid = 0 THEN plid ELSE v_plid END) OR ipaddress = (CASE WHEN v_ipaddress = '' THEN ipaddress ELSE v_ipaddress END)) AND maincatid = v_maincatid AND catid = v_catid AND scatid = v_scatid AND productid = v_productid) THEN
  IF (v_scatid <> 0) THEN
  SELECT maincatid, catid INTO v_maincatid, v_catid FROM tbl_sub_category WHERE subcatid = v_scatid;
  ELSE
  IF (v_catid <> 0) THEN
  SELECT maincatid INTO v_maincatid FROM tbl_category WHERE catid = v_catid;
  ELSE
  IF (v_productid <> 0) THEN
  SELECT maincategoryid, subcategoryid INTO v_maincatid, v_scatid FROM ims_masterproduct WHERE mprid = v_productid;
  END IF;
  END IF;
  END IF;
  INSERT INTO tbl_dealsforyou (ipaddress, plid, maincatid, catid, scatid, lastviewdate, status, isactive, productid) VALUES (v_ipaddress, v_plid, v_maincatid, v_catid, v_scatid, v_currentdatetime, 1, 1, v_productid);
  v_intresult := 1;
  ELSE
  UPDATE tbl_dealsforyou SET plid = (CASE WHEN v_plid = 0 THEN plid ELSE v_plid END), ipaddress = (CASE WHEN v_ipaddress = '' THEN ipaddress ELSE v_ipaddress END) WHERE (plid = (CASE WHEN v_plid = 0 THEN plid ELSE v_plid END) OR ipaddress = (CASE WHEN v_ipaddress = '' THEN ipaddress ELSE v_ipaddress END)) AND maincatid = v_maincatid AND catid = v_catid AND scatid = v_scatid AND productid = v_productid;
  v_intresult := 1;
  END IF;
END;
$$;


--
-- Name: usp_dealslist_qa(character varying, character varying, integer, integer, bigint); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_dealslist_qa(v_fromdate character varying DEFAULT ''::character varying, v_todate character varying DEFAULT ''::character varying, v_pageno integer DEFAULT 1, v_pagesize integer DEFAULT 30, v_optid bigint DEFAULT NULL::bigint) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_minindex int;
  v_maxindex int;
  v_recordcount int;
  v_amount numeric(19,4);
  v_currencysymbol varchar(20);
  v_totalamount numeric(19,4);
  v_sqlquery text;
BEGIN
  -- SET option (removed)
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp (rowNumber bigint,
lwq_id bigint,
title text,
offer text,
LoginId varchar(100),
countryName varchar(25),
date  varchar(25),
optID varchar(100)) ON COMMIT DROP;
  v_minindex := 0;
  v_maxindex := 0;
  v_sqlquery := '';
  v_minindex := ((v_pageno - 1) * v_pagesize) + 1;
  v_maxindex := (v_pageno * v_pagesize);
  v_sqlquery := 'insert into #temp  select ROW_NUMBER() over(order by LW.date  desc) as rownumber,lw.dealid as lwq_id,dm.title,dm.offer,pl.LoginId,C.countryName,convert(varchar(11),LW.date,106) as date,OM2.loginid as optID from tbl_dealsWithQA LW
left join portal_deal_master dm on dm.dealid=LW.dealid
left join portal_master Pm on dm.pmid=PM.pmid  
left join portal_login PL on Pm.pmid=PL.pmid 
left join COUNTRY C on C.CID=PL.cid 
left join tbl_operator_master OM2 on OM2.optid=Pm.optid where LW.status=0 and isnull(dm.verify,0)=0 and  LW.optid=' || CAST(v_optid AS VARCHAR(20));
  IF (v_fromdate <> '') THEN
  v_sqlquery := v_sqlquery || ' and convert(date, lw.date,103) = convert(date,''' || v_fromdate || ''',103) ';
  END IF;
  IF (v_todate <> '') THEN
  v_sqlquery := v_sqlquery || ' and convert(date, lw.date,103)  =convert(date,''' || v_todate || ''',103) ';
  END IF;
  IF (v_fromdate <> '' AND v_todate <> '') THEN
  v_sqlquery := v_sqlquery || ' and convert(date, lw.date,103)  between  convert(date,''' || v_fromdate || ''',103)  and convert(date,''' || v_todate || ''',103)';
  END IF;
  EXECUTE v_sqlquery;
  SELECT COUNT(*) INTO v_recordcount FROM tmp_temp;
  RETURN QUERY SELECT *, v_recordcount AS recordcount FROM tmp_temp WHERE rownumber BETWEEN v_minindex AND v_maxindex;
  DROP TABLE IF EXISTS tmp_temp;
  -- SET option (removed)
END;
$$;


--
-- Name: usp_dealslistprocess_qa(character varying, character varying, integer, integer, bigint); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_dealslistprocess_qa(v_fromdate character varying DEFAULT ''::character varying, v_todate character varying DEFAULT ''::character varying, v_pageno integer DEFAULT 1, v_pagesize integer DEFAULT 30, v_optid bigint DEFAULT NULL::bigint) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_minindex int;
  v_maxindex int;
  v_recordcount int;
  v_amount numeric(19,4);
  v_currencysymbol varchar(20);
  v_totalamount numeric(19,4);
  v_sqlquery text;
BEGIN
  -- SET option (removed)
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp (rowNumber bigint,
lwq_id bigint,
title text,
offer text,
LoginId varchar(100),
countryName varchar(25),
date  varchar(25),
optID varchar(100)) ON COMMIT DROP;
  v_minindex := 0;
  v_maxindex := 0;
  v_sqlquery := '';
  v_minindex := ((v_pageno - 1) * v_pagesize) + 1;
  v_maxindex := (v_pageno * v_pagesize);
  v_sqlquery := 'insert into #temp  select ROW_NUMBER() over(order by LW.date  desc) as rownumber,lw.dealid as lwq_id,dm.title,dm.offer,pl.LoginId,C.countryName,convert(varchar(11),LW.date,106) as date,OM2.loginid as optID from tbl_dealsWithQA LW
left join portal_deal_master dm on dm.dealid=LW.dealid
left join portal_master Pm on dm.pmid=PM.pmid  
left join portal_login PL on Pm.pmid=PL.pmid 
left join COUNTRY C on C.CID=PL.cid 
left join tbl_operator_master OM2 on OM2.optid=Pm.optid where   dm.verify=2 and  LW.optid=' || CAST(v_optid AS VARCHAR(20));
  IF (v_fromdate <> '') THEN
  v_sqlquery := v_sqlquery || ' and convert(date, lw.date,103) = convert(date,''' || v_fromdate || ''',103) ';
  END IF;
  IF (v_todate <> '') THEN
  v_sqlquery := v_sqlquery || ' and convert(date, lw.date,103)  =convert(date,''' || v_todate || ''',103) ';
  END IF;
  IF (v_fromdate <> '' AND v_todate <> '') THEN
  v_sqlquery := v_sqlquery || ' and convert(date, lw.date,103)  between  convert(date,''' || v_fromdate || ''',103)  and convert(date,''' || v_todate || ''',103)';
  END IF;
  EXECUTE v_sqlquery;
  SELECT COUNT(*) INTO v_recordcount FROM tmp_temp;
  RETURN QUERY SELECT *, v_recordcount AS recordcount FROM tmp_temp WHERE rownumber BETWEEN v_minindex AND v_maxindex;
  DROP TABLE IF EXISTS tmp_temp;
  -- SET option (removed)
END;
$$;


--
-- Name: usp_debitfranchiseinvicta(character varying, text, numeric, text, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_debitfranchiseinvicta(v_username character varying DEFAULT ''::character varying, v_remark text DEFAULT NULL::text, v_amount numeric DEFAULT 0, INOUT v_result text DEFAULT NULL::text, v_eid integer DEFAULT 0) RETURNS text
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_did INT;
  v_available DECIMAL(18,8);
  v_pmid INT;
  v_oldbalance DECIMAL(18,8);
BEGIN
  -- BEGIN TRAN (removed)
  BEGIN
  v_did := 0;
  v_available := 0;
  v_pmid := 0;
  v_oldbalance := 0;
  SELECT did INTO v_did FROM tbl_distributor WHERE emailid = v_username;
  SELECT available INTO v_oldbalance FROM tbl_invictawallet WHERE did = v_did;
  UPDATE tbl_invictawallet SET available = available - v_amount, used = used + v_amount WHERE did = v_did;
  SELECT available INTO v_available FROM tbl_invictawallet WHERE did = v_did;
  INSERT INTO tbl_invictawallet_statement (date, did, type, amount, oldbalance, remark, particular, transid, eid) VALUES (dbo.FUN_GETCURRENTDATE(), v_did, 'Dr', v_amount, v_oldbalance, '', 'DEBITED BY ADMIN', GEN_RANDOM_UUID(), v_eid);
  v_result := 'SUCCESS';
  EXCEPTION WHEN OTHERS THEN
  PERFORM dbo.sp_errorlog();
  IF (0 > 0) THEN
  -- ROLLBACK (removed)
  END IF;
  RETURN;
  END;
  IF (0 <> 0) THEN
  -- ROLLBACK (removed)
  v_result := 'SOME ERROR OCCURED';
  RETURN;
  END IF;
  -- COMMIT (removed)
END;
$$;


--
-- Name: usp_default_package_commission_settings(integer, numeric, numeric, numeric, numeric, numeric, integer, character varying, numeric, numeric, numeric); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_default_package_commission_settings(v_tvrcsid integer DEFAULT 2, v_pack1 numeric DEFAULT 0.1, v_pack2 numeric DEFAULT 0.3, v_pack3 numeric DEFAULT 4, v_pack4 numeric DEFAULT 5, v_admincharge numeric DEFAULT 0, v_userid integer DEFAULT 1, v_result character varying DEFAULT ''::character varying, v_admincharge2 numeric DEFAULT 0, v_admincharge3 numeric DEFAULT 0, v_admincharge4 numeric DEFAULT 0) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_operatorname VARCHAR(100);
  v_operatorcode VARCHAR(100);
  v_providername VARCHAR(100);
  v_providercode VARCHAR(100);
  v_actualcommission DECIMAL(18,2);
  v_actualpercentagepack1 Decimal(18,2);
  v_actualpercentagepack2 Decimal(18,2);
  v_actualpercentagepack3 Decimal(18,2);
  v_actualpercentagepack4 Decimal(18,2);
BEGIN
  -- BEGIN TRAN (removed)
  v_operatorname := '';
  v_operatorcode := '';
  v_providername := '';
  v_providercode := '';
  v_actualcommission := 0;
  v_actualpercentagepack1 := 0;
  v_actualpercentagepack2 := 0;
  v_actualpercentagepack3 := 0;
  v_actualpercentagepack4 := 0;
  IF (v_tvrcsid = 0) THEN
  v_result := 'DATA IS NOT EXISTS';
  RETURN;
  -- COMMIT (removed)
  END IF;
  SELECT operatorname, operatorcode, servicename, COALESCE(commission, 0) INTO v_operatorname, v_operatorcode, v_providername, v_actualcommission FROM tbl_vendor_recharge_commission_structure WHERE tvrcsid = v_tvrcsid;
  IF (v_operatorname <> '' AND v_providername <> '') THEN
  RETURN QUERY SELECT v_actualcommission;
  v_actualpercentagepack1 := (v_actualcommission * v_pack1) / 100;
  v_actualpercentagepack2 := (v_actualcommission * v_pack2) / 100;
  v_actualpercentagepack3 := (v_actualcommission * v_pack3) / 100;
  v_actualpercentagepack4 := (v_actualcommission * v_pack4) / 100;
  RETURN QUERY SELECT v_actualpercentagepack1, v_actualpercentagepack2, v_actualpercentagepack3, v_actualpercentagepack4;
  IF NOT EXISTS(SELECT 1 FROM tbl_default_package_commission_settings WHERE operatorname = v_operatorname AND providername = v_providername) THEN
  INSERT INTO tbl_default_package_commission_settings (operatorname, operatorcode, providername, providercode, package1commission, package2commission, package3commission, package4commission, adminsurcharge, active, createddate, createdby, status, addsurcharepackage2, addsurcharepackage3, addsurcharepackage4, actualpercentagepack1, actualpercentagepack2, actualpercentagepack3, actualpercentagepack4) VALUES (v_operatorname, v_operatorcode, v_providername, v_providercode, v_pack1, v_pack2, v_pack3, v_pack4, v_admincharge, 1, dbo.FUN_GETCURRENTDATE(), v_userid, 1, v_admincharge2, v_admincharge3, v_admincharge4, v_actualpercentagepack1, v_actualpercentagepack2, v_actualpercentagepack3, v_actualpercentagepack4);
  v_result := '1';
  ELSE
  INSERT INTO tbl_default_package_commission_settings_history SELECT * FROM tbl_default_package_commission_settings WHERE operatorname = v_operatorname AND providername = v_providername;
  UPDATE tbl_default_package_commission_settings SET operatorname = v_operatorname, operatorcode = v_operatorcode, providername = v_providername, providercode = v_providercode, package1commission = v_pack1, package2commission = v_pack2, package3commission = v_pack3, package4commission = v_pack4, adminsurcharge = v_admincharge, updateddate = dbo.FUN_GETCURRENTDATE(), updatedby = v_userid, addsurcharepackage2 = v_admincharge2, addsurcharepackage3 = v_admincharge3, addsurcharepackage4 = v_admincharge4, actualpercentagepack1 = v_actualpercentagepack1, actualpercentagepack2 = v_actualpercentagepack2, actualpercentagepack3 = v_actualpercentagepack3, actualpercentagepack4 = v_actualpercentagepack4 WHERE operatorname = v_operatorname AND providername = v_providername;
  v_result := '2';
  END IF;
  END IF;
  -- COMMIT (removed)
  IF (0 <> 0) THEN
  PERFORM dbo.sp_errorlog();
  v_result := 'ERROR IN REQUEST';
  -- ROLLBACK (removed)
  END IF;
END;
$$;


