--

CREATE FUNCTION dbo.usp_delblogcanonical(v_blogid bigint DEFAULT 0, INOUT v_strresult integer DEFAULT NULL::integer) RETURNS integer
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF EXISTS(SELECT blogid FROM tbl_blogmaster WHERE blogid = v_blogid AND status = 1 AND publishstatus = 1) THEN
  IF EXISTS(SELECT canonicalurl FROM tbl_blogmaster WHERE blogid = v_blogid) THEN
  UPDATE tbl_blogmaster SET canonicalurl = (CASE WHEN canonicalurl = '' THEN '' ELSE canonicalurl END) WHERE blogid = v_blogid;
  v_strresult := 1;
  ELSE
  v_strresult := 2;
  END IF;
  ELSE
  v_strresult := 3;
  END IF;
END;
$$;


