CREATE FUNCTION dbo.usp_delenq(v_piid text DEFAULT ''::text, INOUT v_result integer DEFAULT NULL::integer) RETURNS integer
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_already int;
BEGIN
  v_already := 0;
  SELECT COUNT(*) INTO v_already FROM portal_inbox WHERE active = 1 AND piid = v_piid;
  IF (v_already > 0) THEN
  UPDATE portal_inbox SET active = 0, remarkdate = CURRENT_TIMESTAMP WHERE piid = v_piid;
  v_result := 1;
  RAISE NOTICE '%', v_result;
  ELSE
  v_result := 2;
  END IF;
END;
$$;


