CREATE FUNCTION dbo.usp_deletegeneratedcoupon(v_cpid bigint, INOUT v_strresult character varying) RETURNS character varying
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_cpidstatus INT;
  v_couponcode VARCHAR(100);
  v_plid BIGINT;
  v_amount numeric(19,4);
BEGIN
  -- BEGIN TRAN (removed)
  SELECT status, coupon_number, plid, amount INTO v_cpidstatus, v_couponcode, v_plid, v_amount FROM coupon_master WHERE cpid = v_cpid;
  v_strresult := 'ok';
  IF (v_cpidstatus = 0) THEN
  -- COMMIT (removed)
  v_strresult := 'This Coupon is already redeemed';
  RETURN;
  END IF;
  IF (v_cpidstatus = 2) THEN
  -- COMMIT (removed)
  v_strresult := 'This Coupon is already deleted';
  RETURN;
  END IF;
  UPDATE coupon_master SET status = 2 WHERE cpid = v_cpid;
  INSERT INTO member_perfornemce (plid, amount, active, trantype, date) VALUES (v_plid, v_amount, 1, 'Delete Coupon - ' || v_couponcode, dbo.FUN_GETCURRENTDATE());
  UPDATE ewallet SET amount = COALESCE(amount, 0) + v_amount, cramount = COALESCE(cramount, 0) + v_amount WHERE plid = v_plid;
  IF (0 <> 0) THEN
  -- ROLLBACK (removed)
  v_strresult := 'Error Occured';
  RETURN;
  END IF;
  -- COMMIT (removed)
END;
$$;


