--
-- Name: usp_deleteproduct(bigint, character varying, character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_deleteproduct(v_pmid bigint, v_imagename character varying, INOUT v_strresult character varying) RETURNS character varying
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_delimage varchar(200);
  v_maxrowno int;
  v_delrowno int;
  v_temp2 text;
BEGIN
  v_delimage := v_imagename;
  SELECT imagename INTO v_imagename FROM portalmember_photogallery WHERE pmid = v_pmid;
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp ON COMMIT DROP AS SELECT ROW_NUMBER() OVER (ORDER BY value NULLS FIRST) AS rownumber, * FROM dbo.SPLITSTRINGBYCOMMA(v_imagename);
  SELECT MAX(rownumber) INTO v_maxrowno FROM tmp_temp;
  SELECT rownumber INTO v_delrowno FROM tmp_temp WHERE value = v_delimage;
  DELETE FROM tmp_temp WHERE value = v_delimage;
  SELECT COALESCE(v_temp2 || ',', '') || CAST(RTRIM(LTRIM(value)) AS VARCHAR(100)) INTO v_temp2 FROM tmp_temp;
  UPDATE portalmember_photogallery SET imagename = v_temp2 WHERE pmid = v_pmid;
  v_strresult := 'Image deleted sucessfully';
  DROP TABLE IF EXISTS tmp_temp;
END;
$$;


--
-- Name: usp_deleteqcproduct(character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_deleteqcproduct(v_checkids character varying DEFAULT ''::character varying) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_count1 int;
  v_count2 int;
  v_splitdata bigint;
BEGIN
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp ON COMMIT DROP AS SELECT ROW_NUMBER() OVER (ORDER BY splitdata NULLS FIRST) AS rowno, * FROM dbo.FNSPLITSTRING(v_checkids, ',');
  v_count1 := 0;
  v_count2 := 0;
  v_count1 := 1;
  SELECT COUNT(1) INTO v_count2 FROM tmp_temp;
  WHILE (v_count1 <= v_count2) LOOP
  SELECT splitdata INTO v_splitdata FROM tmp_temp WHERE rowno = v_count1;
  IF EXISTS(SELECT 1 FROM excel_product WHERE id = v_splitdata) THEN
  DELETE FROM excel_product WHERE id = v_splitdata;
  END IF;
  v_count1 := v_count1 + 1;
  END LOOP;
  DROP TABLE IF EXISTS tmp_temp;
END;
$$;


--
-- Name: usp_deletesingleproduct(bigint, character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_deletesingleproduct(v_sprid bigint DEFAULT 2, INOUT v_stroutput character varying DEFAULT ''::character varying) RETURNS character varying
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_mprid BIGINT;
  v_subproductcode VARCHAR(100);
  v_tsprid BIGINT;
  v_tmprid BIGINT;
  v_tsubproductcode VARCHAR(100);
BEGIN
  -- BEGIN TRAN (removed)
  v_subproductcode := '';
  v_tsubproductcode := '';
  SELECT mprid, subprcode INTO v_mprid, v_subproductcode FROM ims_subproduct WHERE sprid = v_sprid;
  SELECT sprid, mprid, subprcode INTO v_tsprid, v_tmprid, v_tsubproductcode FROM ims_subproduct_temp WHERE subprcode = v_subproductcode;
  DELETE FROM ims_masterproduct_temp WHERE mprid = v_tmprid;
  DELETE FROM ims_subproduct_temp WHERE sprid = v_tsprid AND mprid = v_mprid;
  DELETE FROM ims_masterproductattribute_temp WHERE sprid = v_tsprid;
  DELETE FROM ims_masterproduct WHERE mprid = v_mprid;
  DELETE FROM ims_subproduct WHERE sprid = v_sprid AND mprid = v_mprid;
  DELETE FROM ims_masterproductattribute WHERE sprid = v_sprid;
  v_stroutput := 'success';
  -- COMMIT (removed)
  RETURN;
  IF (0 <> 0) THEN
  v_stroutput := 'Some Error Occoured !';
  -- ROLLBACK (removed)
  RETURN;
  END IF;
  -- COMMIT (removed)
END;
$$;


--
-- Name: usp_delivery_report(integer, integer, integer, character varying, character varying, character varying, character varying, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_delivery_report(v_did integer DEFAULT 0, v_startrowindex integer DEFAULT 1, v_maxrows integer DEFAULT 100, v_searchfield character varying DEFAULT ''::character varying, v_searchvalue character varying DEFAULT ''::character varying, v_fromdate character varying DEFAULT '2022-06-03'::character varying, v_todate character varying DEFAULT '2022-06-04'::character varying, v_totalcount integer DEFAULT 0) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_minindex INT;
  v_maxindex INT;
  v_query text;
BEGIN
  v_minindex := (v_startrowindex - 1) * v_maxrows + 1;
  v_maxindex := v_startrowindex * v_maxrows;
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp (ROWNUMBER BIGINT,
IDID INT,
DID INT,
DATE VARCHAR(200),
ORDERAMOUNT DECIMAL(18,8),
ORDERNO VARCHAR(200),
DELIVERYCHARGE DECIMAL(18,8),
RECEIVEDAMOUNT DECIMAL(18,8),
PAYMENTTYPE VARCHAR(200),
DELIVERYDATE VARCHAR(200),
PAIDAMOUNTMARCHENT DECIMAL(18,8),
PAIDMARCHENTTYPE VARCHAR(200),
MARCHENTDATE VARCHAR(200),
MARCHENTNAME VARCHAR(500)) ON COMMIT DROP;
  v_query := 'INSERT INTO #TEMP SELECT ROW_NUMBER() OVER(ORDER BY IDID DESC) AS ROWNUMBER,IDID,DID,DATE,ORDERAMOUNT,ORDERNO,DELIVERYCHARGE,RECEIVEDAMOUNT,
PAYMENTTYPE,DELIVERYDATE,PAIDAMOUNTMARCHENT,PAIDMARCHENTTYPE,MARCHENTDATE, ISNULL(DM.COMPANYNAME,'''') As MARCHENTNAME FROM TBL_INSERT_DATA B       
INNER JOIN DISTRIBUTOR_MASTER DM ON B.DID=DM.PLID        
WHERE 1=1  ';
  IF (v_searchfield <> '' AND v_searchvalue <> '') THEN
  IF (v_searchfield = 'Marchentname') THEN
  v_query := v_query || ' AND DM.COMPANYNAME=''' || v_searchvalue || '''';
  END IF;
  IF (v_searchfield = 'MEMBERNAME') THEN
  v_query := v_query || ' AND ISNULL(B.FNAME,'''')+'' ''+ISNULL(B.LNAME,'''') LIKE ''%' || v_searchvalue || '%''';
  END IF;
  IF (v_searchfield = 'ORDERID') THEN
  v_query := v_query || ' AND ORDERNO=''' || v_searchvalue || '''';
  END IF;
  END IF;
  IF (v_did > 0) THEN
  v_query := v_query || ' AND B.DID= ''' || CAST(v_did AS VARCHAR(30)) || ''' ';
  END IF;
  IF ((v_fromdate <> '') AND (v_todate = '')) THEN
  v_query := v_query || ' AND CONVERT(VARCHAR, CONVERT(DATE, B.DATE, 105) ) BETWEEN  CONVERT(DATE, ''' || v_fromdate || ''', 105) AND  CONVERT(DATE, DBO.FUN_GETCURRENTDATE(), 105)';
  END IF;
  IF ((v_fromdate = '') AND (v_todate <> '')) THEN
  v_query := v_query || 'AND CONVERT(DATE, B.DATE, 105) BETWEEN  CONVERT(DATE, ''' || v_todate || ''', 105) AND  CONVERT(DATE, DBO.FUN_GETCURRENTDATE(), 105)';
  END IF;
  IF ((v_fromdate <> '') AND (v_todate <> '')) THEN
  v_query := v_query || 'AND CONVERT(DATE, B.DATE, 105) BETWEEN CONVERT(DATE, ''' || v_fromdate || ''') AND  CONVERT(DATE, ''' || v_todate || ''')';
  END IF;
  RAISE NOTICE '%', v_query;
  EXECUTE v_query;
  RETURN QUERY SELECT * FROM tmp_temp WHERE rownumber BETWEEN v_minindex AND v_maxindex;
  SELECT COUNT(rownumber) INTO v_totalcount FROM tmp_temp;
  DROP TABLE IF EXISTS tmp_temp;
  -- SET option (removed)
END;
$$;


