--
-- Name: usp_demapped_attribute(text, character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_demapped_attribute(v_awcid text DEFAULT '12,'::text, INOUT v_strout character varying DEFAULT ''::character varying) RETURNS character varying
    LANGUAGE plpgsql
    AS $$
BEGIN
  -- SET option (removed)
  IF (v_awcid <> '') THEN
  INSERT INTO tbl_attributes_with_category_history (awct_id, main_cat_id, sub_cat_id, cat_id, att_name, att_type, ddl_id, default_value, sr_no, is_active, ismendatory, issearch, createdate) SELECT awct_id, main_cat_id, sub_cat_id, cat_id, att_name, att_type, ddl_id, default_value, sr_no, is_active, ismendatory, issearch, dbo.FUN_GETCURRENTDATE() FROM tbl_attributes_with_category WHERE awct_id IN (SELECT value FROM SPLITSTRINGBYCOMMA(v_awcid));
  DELETE FROM tbl_attributes_with_category WHERE awct_id IN (SELECT value FROM SPLITSTRINGBYCOMMA(v_awcid));
  v_strout := 'ok';
  ELSE
  v_strout := 'ID NOT MAPPED';
  END IF;
  -- SET option (removed)
END;
$$;


