CREATE FUNCTION dbo.usp_deselective_attribute(v_selectiveawcid text DEFAULT '12,'::text, v_deselectiveawcid text DEFAULT '12,'::text, INOUT v_strout character varying DEFAULT ''::character varying) RETURNS character varying
    LANGUAGE plpgsql
    AS $$
BEGIN
  -- SET option (removed)
  IF (v_selectiveawcid <> '' OR v_deselectiveawcid <> '') THEN
  IF v_selectiveawcid <> '' THEN
  UPDATE tbl_attributes_with_category SET isselectiveattr = 1 WHERE awct_id IN (SELECT value FROM SPLITSTRINGBYCOMMA(v_selectiveawcid));
  END IF;
  IF v_deselectiveawcid <> '' THEN
  UPDATE tbl_attributes_with_category SET isselectiveattr = 0 WHERE awct_id IN (SELECT value FROM SPLITSTRINGBYCOMMA(v_deselectiveawcid));
  END IF;
  v_strout := 'ok';
  ELSE
  v_strout := 'ID NOT MAPPED';
  END IF;
  -- SET option (removed)
END;
$$;


--
-- Name: usp_direct_member(integer, integer, integer, character varying, character varying, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_direct_member(v_regno integer DEFAULT 0, v_startrowindex integer DEFAULT 1, v_maxrows integer DEFAULT 10, v_searchfield character varying DEFAULT ''::character varying, v_searchvalue character varying DEFAULT ''::character varying, v_totalcount integer DEFAULT 0) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_minindex INT;
  v_maxindex INT;
  v_query text;
BEGIN
  v_minindex := (v_startrowindex - 1) * v_maxrows + 1;
  v_maxindex := v_startrowindex * v_maxrows;
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp (ROWNUMBER INT,

LOGINID VARCHAR(50),

MEMNAME VARCHAR(250),

REGDATE VARCHAR(250),

UPDATEDATE VARCHAR(250),

TLBV DECIMAL(18,3),

TRBV DECIMAL(18,3),

CLBV DECIMAL(18,3),

CRBV DECIMAL(18,3),

PAIDBV DECIMAL(18,3),

PBV DECIMAL(18,3),

STATUS VARCHAR(30),

PPV DECIMAL(18,3),

GPV DECIMAL(18,3)) ON COMMIT DROP;
  v_query := 'INSERT INTO #TEMP SELECT ROW_NUMBER() OVER (ORDER BY MM.DOC DESC),MM.LOGINID, ISNULL(MM.FNAME,'''')+''''+ISNULL(MM.LNAME,''''),

CONVERT(VARCHAR(30),MM.DOC,106),CASE WHEN MM.ACTIVE=1 THEN CONVERT(VARCHAR(30),MM.DOC,106) ELSE '''' END,

ISNULL(MP.TLBV,0) AS TLBV,ISNULL(MP.TRBV,0) AS TRBV,ISNULL(MP.TLBV,0)-ISNULL(MP.PAIDBV,0) AS CLBV,ISNULL(MP.TRBV,0)-ISNULL(MP.PAIDBV,0) AS CRBV,

ISNULL(MP.PAIDBV,0) AS PAIDBV,ISNULL(MP.PBV,0)+ISNULL(MP.GIVEBV,0) AS PBV, CASE ISNULL(MM.ACTIVE,0) WHEN 1 THEN ''ACTIVE'' ELSE ''INACTIVE'' END AS STATUS,

ISNULL(MP.PPV,0) AS PPV,ISNULL(MP.GPV,0) AS GPV

FROM PORTAL_LOGIN MM INNER JOIN  MEMBER_PERFORMANCE MP ON MP.LOGINID=MM.LOGINID WHERE MM.RegNo=''' || CAST(v_regno AS VARCHAR(50)) || '''';
  IF (v_searchfield <> '' AND v_searchvalue <> '') THEN
  IF (v_searchfield = 'NAME') THEN
  v_query := v_query || ' AND ISNULL(MM.FNAME,'''')+'' ''+ISNULL(MM.MNAME,'''')+'' ''+ISNULL(MM.LNAME,'''') LIKE ''%' || v_searchvalue || '%''';
  END IF;
  END IF;
  IF (v_searchfield = 'LOGINID') THEN
  v_query := v_query || ' AND MM.LOGINID LIKE ''%' || v_searchvalue || '%''';
  END IF;
  RETURN QUERY SELECT v_query;
  EXECUTE v_query;
  RETURN QUERY SELECT * FROM tmp_temp WHERE rownumber BETWEEN v_minindex AND v_maxindex;
  SELECT COUNT(rownumber) INTO v_totalcount FROM tmp_temp;
  DROP TABLE IF EXISTS tmp_temp;
  -- SET option (removed)
END;
$$;


--
-- Name: usp_direct_tree_list(character varying, integer, integer, character varying, character varying, character varying, character varying, integer, integer, character varying, character varying, character varying, integer, integer, character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_direct_tree_list(v_loginid character varying DEFAULT 'ANAVEXCHANGE'::character varying, v_startrowindex integer DEFAULT 1, v_maxrows integer DEFAULT 50, v_searchfield character varying DEFAULT ''::character varying, v_searchvalue character varying DEFAULT ''::character varying, v_fromdate character varying DEFAULT ''::character varying, v_todate character varying DEFAULT ''::character varying, v_levenumber integer DEFAULT 0, INOUT v_totalcount integer DEFAULT 0, v_username character varying DEFAULT ''::character varying, v_emailid character varying DEFAULT ''::character varying, v_sponserid character varying DEFAULT ''::character varying, v_referraltype integer DEFAULT 0, v_checkadminside integer DEFAULT 1, v_mobile character varying DEFAULT ''::character varying) RETURNS integer
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_minindex INT;
  v_maxindex INT;
  v_query text;
  v_query1 text;
BEGIN
  SELECT loginid INTO v_loginid FROM member_master WHERE username = v_loginid;
  v_minindex := (v_startrowindex - 1) * v_maxrows + 1;
  v_maxindex := v_startrowindex * v_maxrows;
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp (ROWNUMBER INT GENERATED BY DEFAULT AS IDENTITY,
   LOGINID VARCHAR(30),
   SPONSERID VARCHAR(30),
   ROOTID VARCHAR(30),
   EMPLEVEL INT,
   NAME VARCHAR(100),
   MOBILE VARCHAR(50),
   CITYNAME VARCHAR(100),
   REGDATE timestamp,
   STATUS VARCHAR(50),
   EMAILID VARCHAR(200),
   DOC timestamp,
   TLBV DECIMAL(10,2),
   CLBV DECIMAL(10,2),
   TRBV DECIMAL(10,2),
   CRBV DECIMAL(10,2),
   PAIDBV DECIMAL(10,2),
   USERNAME VARCHAR(200)) ON COMMIT DROP;
  v_query := 'INSERT INTO #TEMP  SELECT * FROM [FUN_ALL_DOWNLINE_MEMBERLIST](''' || v_loginid || ''',0) ';
  IF (v_searchvalue <> '') THEN
  SELECT loginid INTO v_loginid FROM member_master WHERE emailid LIKE '%' || v_searchvalue || '%';
  v_query := v_query || ' WHERE LOGINID = ''' || (CAST(v_loginid AS VARCHAR(50))) || '''';
  END IF;
  v_query := v_query || ' WHERE  EMPLEVEL >=0';
  IF (v_levenumber > 0) THEN
  v_query := v_query || ' AND  EMPLEVEL = ' || CAST(v_levenumber AS VARCHAR(10));
  END IF;
  IF (v_fromdate <> '' AND v_todate <> '') THEN
  v_query := v_query || ' AND CONVERT(DATE,REGDATE)>=Convert(Date,''' || v_fromdate || ''') AND  CONVERT(DATE,REGDATE)<= Convert(Date,''' || v_todate || ''') ';
  ELSE
  IF (v_fromdate <> '') THEN
  v_query := v_query || ' AND CONVERT(DATE,REGDATE)=Convert(Date,''' || v_fromdate || ''')';
  ELSE
  IF (v_todate <> '') THEN
  v_query := v_query || ' AND CONVERT(DATE,REGDATE)=Convert(Date,''' || v_todate || ''')';
  END IF;
  END IF;
  END IF;
  EXECUTE v_query;
  v_query1 := '';
  IF (v_checkadminside = 1) THEN
  v_query1 := 'SELECT  #TEMP.ROWNUMBER,#TEMP.EMPLEVEL,
					 M1.LOGINID,(M1.FNAME+'' ''+ISNULL(M1.LNAME,'''')) AS NAME,M1.STATUS,
					 M1.EMAILID AS EMAILID,
					 (''+'' +C.ISDCODE +''- ''+M1.MOBILE) AS MOBILE,
		             (CONVERT(VARCHAR(50),M1.REGDATE,106)) AS REGDATE,M1.DOC,M1.ACTIVE,M1.USERNAME,ISNULL(M1.IMAGENAME,'''')AS IMAGENAME,
				     M2.LOGINID AS SPLOGINID,(M2.FNAME+'' ''+ISNULL(M2.LNAME,'''')) AS SPNAME,M2.EMAILID  AS SPEMAILID,(''+'' +C.ISDCODE +''- ''+M2.MOBILE) AS SPMOBILE,
				     (CONVERT(VARCHAR(50), M2.REGDATE,106)) AS SPREGDATE ,M2.USERNAME AS SPUSERNAME, C.ISDCODE ,C.COUNTRYNAME FROM #TEMP  
				     JOIN MEMBER_MASTER M1 ON M1.LOGINID=#TEMP.LOGINID 
				     LEFT JOIN MEMBER_MASTER M2 ON M1.SPONSERID=M2.LOGINID
				     LEFT JOIN COUNTRY C ON C.CID=M1.CID  WHERE ROWNUMBER 
					 BETWEEN ' || CAST(v_startrowindex AS VARCHAR(10)) || ' AND ' || CAST(v_maxrows AS VARCHAR(10)) || ' ';
  ELSE
  v_query1 := 'SELECT #TEMP.ROWNUMBER,#TEMP.EMPLEVEL,
					M1.LOGINID,(M1.FNAME+'' ''+ISNULL(M1.LNAME,'''')) AS NAME,   
				    M1.STATUS,M1.EMAILID AS EMAILID,
					(''+'' +C.ISDCODE +''- ''+M1.MOBILE) AS MOBILE,
		            (CONVERT(VARCHAR(50),M1.REGDATE,106)) AS REGDATE,
					M1.DOC,M1.ACTIVE,
					M1.USERNAME,
					ISNULL(M1.IMAGENAME,'''')AS IMAGENAME,
				    M2.LOGINID AS SPLOGINID,
					(M2.FNAME+'' ''+ISNULL(M2.LNAME,'''')) AS SPNAME,
					M2.EMAILID  AS SPEMAILID,
					(''+'' +C.ISDCODE +''- ''+M2.MOBILE) AS SPMOBILE,
				    (CONVERT(VARCHAR(50), M2.REGDATE,106)) AS SPREGDATE ,
					M2.USERNAME AS SPUSERNAME, 
					C.ISDCODE ,
					C.COUNTRYNAME FROM #TEMP  
					JOIN MEMBER_MASTER M1 ON M1.LOGINID=#TEMP.LOGINID 
				    LEFT JOIN MEMBER_MASTER M2 ON M1.SPONSERID=M2.LOGINID
				    LEFT JOIN COUNTRY C ON C.CID=M1.CID  WHERE ROWNUMBER 
				    BETWEEN ' || CAST(v_minindex AS VARCHAR(10)) || ' AND ' || CAST(v_maxindex AS VARCHAR(10)) || ' ';
  END IF;
  IF (v_username <> '') THEN
  v_query1 := v_query1 || (' AND M1.USERNAME LIKE ''%' || v_username || '%''');
  END IF;
  IF (v_mobile <> '') THEN
  v_query1 := v_query1 || (' AND M1.MOBILE LIKE ''%' || v_mobile || '%''');
  END IF;
  IF (v_emailid <> '') THEN
  v_query1 := v_query1 || (' AND M1.EMAILID LIKE ''%' || v_emailid || '%''');
  END IF;
  IF (v_sponserid <> '') THEN
  v_query1 := v_query1 || (' AND M2.USERNAME LIKE ''%' || v_sponserid || '%''');
  END IF;
  IF (v_referraltype <> 0) THEN
  IF (v_referraltype = 1) THEN
  v_query1 := v_query1 || (' AND ISNULL(M2.IsReferralAccepted,0)=1');
  ELSE
  IF (v_referraltype = 2) THEN
  v_query1 := v_query1 || (' AND ISNULL(M2.IsMerchantPanelAccepted,0)=1');
  ELSE
  IF (v_referraltype = 3) THEN
  v_query1 := v_query1 || (' AND ISNULL(M2.IsCustomerPanelAccepted,0)=1');
  END IF;
  END IF;
  END IF;
  END IF;
  v_query1 := v_query1 || (' Order By #TEMP.ROWNUMBER Asc');
  EXECUTE v_query1;
  SELECT COUNT(rownumber) INTO v_totalcount FROM tmp_temp;
  DROP TABLE IF EXISTS tmp_temp;
  -- SET option (removed)
END;
$$;


--
-- Name: usp_directincomedistribution(integer, integer, text); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_directincomedistribution(v_plid integer DEFAULT 0, v_sfdid integer DEFAULT 0, INOUT v_intresult text DEFAULT ''::text) RETURNS text
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_directincomepercentageforfreemember double precision;
  v_directincomepercentageforpaidmember double precision;
  v_isactiveuser Int;
  v_parentplid Int;
  v_regno Int;
  v_fromregno Int;
  v_addedfundamount Decimal(10,2);
  v_totalcommission Decimal(10,2);
  v_commissionpercentage Decimal(10,2);
  v_date Date;
  v_status Int;
  v_isactive Int;
  v_isrequestedforwithdrawal Int;
  v_requesteddate Date;
  v_iswithdrawl Int;
  v_withdrawldate Date;
BEGIN
  -- BEGIN TRAN (removed)
  BEGIN
  -- SET option (removed)
  v_directincomepercentageforfreemember := 0.00;
  v_directincomepercentageforpaidmember := 0.00;
  v_isactiveuser := 0;
  v_parentplid := 0;
  SELECT limits INTO v_directincomepercentageforfreemember FROM settings WHERE caption = 'Customers Referral Bonus';
  SELECT limits INTO v_directincomepercentageforpaidmember FROM settings WHERE caption = 'Active Customers Referral Bonus';
  v_regno := 0;
  v_fromregno := 0;
  v_addedfundamount := 0.00;
  v_totalcommission := 0.00;
  v_commissionpercentage := 0.00;
  v_date := CURRENT_TIMESTAMP;
  v_status := 1;
  v_isactive := 1;
  v_isrequestedforwithdrawal := 0;
  v_requesteddate := NULL;
  v_iswithdrawl := 0;
  v_withdrawldate := NULL;
  SELECT active, regno, plid INTO v_isactiveuser, v_regno, v_parentplid FROM member_master WHERE regno = (SELECT introregno FROM member_master WHERE plid = v_plid);
  SELECT depositamount, (CASE WHEN v_isactiveuser = 0 THEN ((depositamount * v_directincomepercentageforfreemember) / 100) WHEN v_isactiveuser = 1 THEN ((depositamount * v_directincomepercentageforpaidmember) / 100) ELSE 0.00 END), (CASE WHEN v_isactiveuser = 0 THEN v_directincomepercentageforfreemember WHEN v_isactiveuser = 1 THEN v_directincomepercentageforpaidmember ELSE 0.00 END) INTO v_addedfundamount, v_totalcommission, v_commissionpercentage FROM tbl_sponserfunddetails WHERE sfdid = v_sfdid;
  SELECT regno INTO v_fromregno FROM member_master WHERE plid = v_plid;
  INSERT INTO direct_income (regno, fromregno, addedfundamount, totalcommission, commissionpercentage, date, status, isactive, isrequestedforwithdrawal, requesteddate, iswithdrawl, withdrawldate) VALUES (v_regno, v_fromregno, v_addedfundamount, v_totalcommission, v_commissionpercentage, v_date, v_status, v_isactive, v_isrequestedforwithdrawal, v_requesteddate, v_iswithdrawl, v_withdrawldate);
  IF (0 = 0) THEN
  v_intresult := 'Try';
  -- SET option (removed)
  -- COMMIT (removed)
  ELSE
  v_intresult := 'CaughtError';
  -- SET option (removed)
  -- ROLLBACK (removed)
  END IF;
  RETURN;
  EXCEPTION WHEN OTHERS THEN
  v_intresult := 'CaughtError';
  -- SET option (removed)
  -- ROLLBACK (removed)
  RETURN;
  END;
END;
$$;


--
-- Name: usp_displayaddfunddetails(bigint, bigint); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_displayaddfunddetails(v_plid bigint, v_sfdid bigint) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF EXISTS(SELECT plid FROM tbl_addfundbillingdetails WHERE plid = v_plid) THEN
  RETURN QUERY SELECT afd.businessname, afd.contactname, afd.phonenumber, afd.address, afd.city, afd.postalcode, CAST(TO_CHAR(sfd.depositdate, 'DD-MM-YYYY') AS VARCHAR(10)) AS depositdate, sfd.paymenttype, CONCAT(pl2.currencysymbol, ' ', sfd.depositamount) AS depositamount, sfd.check_sno, CAST(TO_CHAR(sfd.fundapprovedate, 'DD-MM-YYYY') AS VARCHAR(10)) AS fundapprovedate, sfd.plid, (CASE WHEN sfd.status = 1 THEN 'Approved' WHEN sfd.status = 0 THEN 'Pending' WHEN sfd.status = 2 THEN 'Rejected' END) AS billingstatus, CAST(TO_CHAR(sfd.datetime, 'DD-MM-YYYY') AS VARCHAR(10)) AS requesteddate, s.statename, c.countryname, sfd.checkstatus, ckd.accountno, ckd.bankname, ckd.branchname, CONCAT(pl2.currencysymbol, ' ', ckd.checkamount) AS checkamount, CAST(TO_CHAR(ckd.checkdate, 'DD-MM-YYYY') AS VARCHAR(10)) AS checkdate, sfd.rejectreview, pl.loginid FROM tbl_addfundbillingdetails AS afd LEFT JOIN state AS s ON afd.sid = s.sid JOIN country AS c ON afd.cid = c.cid LEFT JOIN tbl_sponserfunddetails AS sfd ON sfd.sfdid = afd.sfdid LEFT JOIN tbl_sponsercheckdetails AS ckd ON ckd.chk_sno = sfd.check_sno LEFT JOIN portal_login AS pl ON pl.plid = sfd.fromplid INNER JOIN portal_login AS pl2 ON pl2.plid = sfd.plid WHERE afd.plid = v_plid AND afd.sfdid = v_sfdid;
  END IF;
END;
$$;


--
-- Name: usp_dist_bv_common(character varying, date, numeric, numeric, integer, character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_dist_bv_common(v_loginid character varying DEFAULT ''::character varying, v_date date DEFAULT NULL::date, v_bv numeric DEFAULT 0, v_pv numeric DEFAULT 0, v_kid integer DEFAULT 0, INOUT v_strresult character varying DEFAULT ''::character varying) RETURNS character varying
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_bool boolean;
  v_toid VARCHAR(30);
  v_childid VARCHAR(30);
  v_lid VARCHAR(30);
  v_rid VARCHAR(30);
  v_toactive INT;
  v_tdbv numeric(19,4);
  v_uplineid text;
  v_spid VARCHAR(30);
  v_regno BIGINT;
  v_cappinglimits Decimal(10,2);
BEGIN
  -- BEGIN TRAN (removed)
  BEGIN
  -- SET option (removed)
  v_bool := 0;
  v_toid := '0';
  v_childid := '';
  v_lid := '';
  v_rid := '';
  v_toactive := 0;
  v_tdbv := 0;
  v_uplineid := '';
  v_spid := '';
  v_regno := 0;
  v_cappinglimits := 0.00;
  v_strresult := 'ok';
  v_bool := 1;
  v_childid := v_loginid;
  v_uplineid := '';
  SELECT COALESCE(sponserid, '0'), regno INTO v_spid, v_regno FROM member_master WHERE loginid = v_loginid;
  v_cappinglimits := COALESCE(((v_bv * 50) / 100), 0.00);
  UPDATE member_performance SET pbv = COALESCE(pbv, 0) + v_bv, ppv = COALESCE(ppv, 0) + v_pv, cappinglimit = v_cappinglimits WHERE loginid = v_loginid;
  WHILE (v_bool = 1) LOOP
  v_toid := '0';
  SELECT COALESCE(rootid, '0') INTO v_toid FROM member_master WHERE loginid = v_childid;
  IF (v_toid = '') THEN
  v_toid := '0';
  END IF;
  SELECT COALESCE(active, 0), COALESCE(leftid, '0'), COALESCE(rightid, '0') INTO v_toactive, v_lid, v_rid FROM member_master WHERE loginid = v_toid;
  IF (v_toid <> '0') THEN
  IF (v_childid = v_lid) THEN
  UPDATE member_performance SET tlbv = COALESCE(tlbv, 0) + v_bv, clbv = COALESCE(clbv, 0) + v_bv, tlpv = COALESCE(tlpv, 0) + v_pv, clpv = COALESCE(clpv, 0) + v_pv WHERE loginid = v_toid;
  IF (v_toid = v_spid) THEN
  UPDATE member_performance SET dlbv = COALESCE(dlbv, 0) + v_bv WHERE loginid = v_toid;
  END IF;
  END IF;
  IF (v_childid = v_rid) THEN
  UPDATE member_performance SET trbv = COALESCE(trbv, 0) + v_bv, crbv = COALESCE(crbv, 0) + v_bv, trpv = COALESCE(trpv, 0) + v_pv, crpv = COALESCE(crpv, 0) + v_pv WHERE loginid = v_toid;
  IF (v_toid = v_spid) THEN
  UPDATE member_performance SET drbv = COALESCE(drbv, 0) + v_bv WHERE loginid = v_toid;
  END IF;
  END IF;
  v_tdbv := v_tdbv + v_bv;
  v_uplineid := v_uplineid || ',' || v_toid;
  ELSE
  IF (v_toid <> '0' AND v_toactive = 0) THEN
  IF (v_childid = v_lid) THEN
  IF (v_toid = v_spid) THEN
  UPDATE member_performance SET dlbv = COALESCE(dlbv, 0) + v_bv WHERE loginid = v_toid;
  END IF;
  END IF;
  IF (v_childid = v_rid) THEN
  IF (v_toid = v_spid) THEN
  UPDATE member_performance SET drbv = COALESCE(drbv, 0) + v_bv WHERE loginid = v_toid;
  END IF;
  END IF;
  END IF;
  END IF;
  IF (v_toid = v_childid) THEN
  v_bool := 0;
  END IF;
  v_childid := v_toid;
  IF (v_toid = '0' OR v_toid = '') THEN
  v_bool := 0;
  END IF;
  END LOOP;
  v_uplineid := STUFF(v_uplineid, 1, 1, '');
  IF (v_loginid <> '') THEN
  INSERT INTO tbl_binaryincomedistribution (type, typeid, bv, tdbv, uplineid, date, loginid, kid) VALUES ('', 0, v_bv, v_tdbv, v_uplineid, v_date, v_loginid, v_kid);
  END IF;
  IF (0 <> 0) THEN
  v_strresult := '' || 0;
  -- ROLLBACK (removed)
  RETURN;
  END IF;
  -- SET option (removed)
  EXCEPTION WHEN OTHERS THEN
  -- SET option (removed)
  v_strresult := '_Error_line=' || COALESCE(CAST(0 AS VARCHAR(50)), '');
  -- ROLLBACK (removed)
  RETURN;
  END;
  -- COMMIT (removed)
END;
$$;


--
-- Name: usp_distributebvdetails(character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_distributebvdetails(v_groupname character varying DEFAULT ''::character varying) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_getallwdid text;
BEGIN
  -- BEGIN TRAN (removed)
  -- SET option (removed)
  v_getallwdid := '';
  IF (v_groupname = '') THEN
  -- COMMIT (removed)
  RETURN;
  END IF;
  SELECT RIGHT(CAST(allwdid AS TEXT), LENGTH(CAST(allwdid AS TEXT)) - 1) INTO v_getallwdid FROM tbl_resellerwise_customer_bvclubhistory WHERE clubgroup = v_groupname;
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp (ROWNUMBER INT GENERATED BY DEFAULT AS IDENTITY,
USERNAME VARCHAR(100),
AMOUNT DECIMAL(18,2),
ORDERID VARCHAR(100),
BV DECIMAL(18,2),
PV DECIMAL(18,2),
TRANSACTIONID VARCHAR(100),
ORDERSTATUS VARCHAR(100),
ORDERDATE VARCHAR(100),
CONFORMATIONDATE VARCHAR(100),
COMDID INT) ON COMMIT DROP;
  INSERT INTO tmp_temp (username, amount, orderid, bv, pv, transactionid, orderstatus, orderdate, conformationdate, comdid) SELECT COALESCE(trun.username, ''), COALESCE(pom.total_purchase_cost, 0), COALESCE(pom.orderid, ''), bvalue, 0, '', (CASE WHEN pom.intstatus = 0 THEN 'Pending' WHEN pom.intstatus = 2 THEN 'Packed' WHEN pom.intstatus = 3 THEN 'Ready for Dispatch' WHEN pom.intstatus = 4 THEN 'Shipped' WHEN pom.intstatus = 5 THEN 'Shipped' WHEN pom.intstatus = 6 THEN 'Completed' WHEN pom.intstatus = 7 THEN 'Cancel' WHEN pom.intstatus = 9 THEN 'Out for Delivery' END), CAST(TO_CHAR(create_date, 'DD TMMon YYYY') AS VARCHAR(30)), '', trbvd.comdid FROM tbl_reseller_bv_pv_details AS trbvd LEFT JOIN tbl_product_order_master AS pom ON trbvd.orderno = pom.orderno LEFT JOIN tbl_customerlogin AS cl ON pom.loginid = cl.loginid LEFT JOIN tbl_referenceusername AS trun ON cl.clid = trun.clid AND trun.status = 1 WHERE comdid IN (SELECT value FROM dbo.SPLITSTRINGBYCOMMA(v_getallwdid)) AND trbvd.releasedstatus = 3;
  RETURN QUERY SELECT * FROM tmp_temp;
  -- SET option (removed)
  -- COMMIT (removed)
END;
$$;


