--
-- Name: usp_distribution_commission_structure(integer, integer, bigint, numeric, character varying, character varying, numeric, numeric, numeric, numeric, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_distribution_commission_structure(v_startrowindex integer DEFAULT 1, v_maxrows integer DEFAULT 1000, v_subsubcatid bigint DEFAULT 5, v_admincommission numeric DEFAULT 10, v_empid character varying DEFAULT '0'::character varying, v_did character varying DEFAULT '2'::character varying, v_bv numeric DEFAULT 0, v_cashback numeric DEFAULT 6, v_newbv numeric DEFAULT 5, v_newcashback numeric DEFAULT 55, INOUT v_strresult integer DEFAULT 0) RETURNS integer
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF NOT EXISTS(SELECT subsubcatid FROM tbl_distributor_commission_structure WHERE subsubcatid = v_subsubcatid AND did = v_did) THEN
  INSERT INTO tbl_distributor_commission_structure (subsubcatid, admincomm, bv_default, bv, cashback_default, cashback, createddate, modifydate, emp_id, did) VALUES (v_subsubcatid, v_admincommission, v_bv, v_newbv, v_cashback, v_newcashback, dbo.FUN_GETCURRENTDATE(), dbo.FUN_GETCURRENTDATE(), v_empid, v_did);
  v_strresult := 1;
  ELSE
  INSERT INTO tbl_distributor_commission_structure_history (dcsid, subsubcatid, admincomm, bv_default, bv, cashback_default, cashback, createddate, modifydate, emp_id, did) SELECT * FROM tbl_distributor_commission_structure WHERE subsubcatid = v_subsubcatid;
  UPDATE tbl_distributor_commission_structure SET admincomm = v_admincommission, bv_default = v_bv, bv = v_newbv, cashback_default = v_cashback, cashback = v_newcashback, modifydate = dbo.FUN_GETCURRENTDATE(), emp_id = v_empid, did = v_did WHERE subsubcatid = v_subsubcatid;
  v_strresult := 2;
  END IF;
END;
$$;


