--
-- Name: usp_distributor_paymode_setting(integer, integer, character varying, character varying, character varying, character varying, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_distributor_paymode_setting(v_startrowindex integer DEFAULT 1, v_maxrows integer DEFAULT 100, v_fromdate character varying DEFAULT ''::character varying, v_todate character varying DEFAULT ''::character varying, v_searchfiel character varying DEFAULT ''::character varying, v_searchvalue character varying DEFAULT ''::character varying, v_totalcount integer DEFAULT 0) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_minindex INT;
  v_maxindex INT;
  v_query text;
BEGIN
  -- SET option (removed)
  v_minindex := (v_startrowindex - 1) * v_maxrows + 1;
  v_maxindex := v_startrowindex * v_maxrows;
  DROP TABLE IF EXISTS tmp_managedistributorlist;
  CREATE TEMP TABLE tmp_managedistributorlist (ROWNUMBER BIGINT,
	DID INT,
	NAME VARCHAR(150),
	Total_Member BIGINT,
	Email_Id VARCHAR(200),
	Contact VARCHAR(200),
	Address VARCHAR(1000),
	DB_NAME  VARCHAR(200),
	URL VARCHAR(50),
	REGISTRATIONDATE VARCHAR(200),
	MDPID bigint,
	PMID bigint,
	MDistributorID bigint,
	Percentage int) ON COMMIT DROP;
  v_query := 'INSERT INTO #MANAGEDISTRIBUTORLIST SELECT ROW_NUMBER() OVER (ORDER BY d.DID DESC) AS ROWNUMBER,d.DID,ISNULL(d.NAME,'''') AS NAME ,ISNULL(d.Total_Member,0) AS Total_Member,ISNULL(d.Email_Id,'''') AS Email_Id,
ISNULL(d.Contact,'''') AS Contact,ISNULL(d.Address,'''')AS Address ,
ISNULL(d.DB_NAME,'''') AS DB_NAME,ISNULL(d.URL,'''') AS URL,
isnull(d.REGISTRATIONDATE,'''') as REGISTRATIONDATE, isnull(MDP.MDPID,0) as MDPID,isnull(MDP.PMID,0) as PMID,isnull(MDP.DID,0) AS MDistributorID,isnull(MDP.Percentage,0) as Percentage

FROM TBL_DISTRIBUTOR d left join  tbl_Map_Distributor_Paymode MDP on MDP.DID=d.DID where 1=1 ';
  IF ((v_searchfiel <> '') AND (v_searchvalue <> '')) THEN
  IF (v_searchfiel = 'USERNAME') THEN
  v_query := v_query || ' And EM.EMP_NAME like ''%' || v_searchvalue || '%''';
  END IF;
  END IF;
  IF ((v_fromdate <> '') AND (v_todate = '')) THEN
  v_query := v_query || ' AND CONVERT(DATE, AL.LOGINDATETIME, 105) BETWEEN  CONVERT(DATE, ''' || v_fromdate || ''', 105) AND  CONVERT(DATE, DBO.FUN_GETCURRENTDATE(), 105) ';
  END IF;
  IF ((v_fromdate = '') AND (v_todate <> '')) THEN
  v_query := v_query || ' AND CONVERT(DATE, AL.LOGINDATETIME, 105) BETWEEN  CONVERT(DATE, ''' || v_todate || ''', 105) AND  CONVERT(DATE, DBO.FUN_GETCURRENTDATE(), 105) ';
  END IF;
  IF ((v_fromdate <> '') AND (v_todate <> '')) THEN
  v_query := v_query || ' AND CONVERT(DATE, AL.LOGINDATETIME, 105) BETWEEN CONVERT(DATE, ''' || v_fromdate || ''', 105) AND  CONVERT(DATE, ''' || v_todate || ''', 105) ';
  END IF;
  EXECUTE v_query;
  RETURN QUERY SELECT * FROM tmp_managedistributorlist WHERE rownumber BETWEEN v_minindex AND v_maxindex;
  SELECT COUNT(rownumber) INTO v_totalcount FROM tmp_managedistributorlist;
  DROP TABLE IF EXISTS tmp_managedistributorlist;
  -- SET option (removed)
END;
$$;


--
-- Name: usp_distributordiscount(integer, integer, integer, character varying, character varying, numeric, numeric, integer, character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_distributordiscount(v_distributorid integer DEFAULT 0, v_mode integer DEFAULT 0, v_plid integer DEFAULT 0, v_username character varying DEFAULT ''::character varying, v_transactionpassword character varying DEFAULT ''::character varying, v_jc numeric DEFAULT 0.00, v_iwallet numeric DEFAULT 0.00, v_callingtype integer DEFAULT 0, INOUT v_stroutput character varying DEFAULT ''::character varying) RETURNS character varying
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_query text;
  v_regno INT;
  v_mobile Varchar(20);
  v_otp Varchar(10);
  v_iswhile Int;
  v_noofminute Int;
  v_previousotpdateandtime timestamp;
  v_amountforuse Decimal(18,8);
  v_reference_regno BIGINT;
  v_available_fund DECIMAL(18,8);
  v_availablecoinwallet DECIMAL(18,8);
  v_availablecommissionwallet DECIMAL(18,8);
BEGIN
  v_query := '';
  v_regno := 0;
  v_mobile := '';
  v_otp := '';
  v_iswhile := 1;
  v_noofminute := 0;
  v_amountforuse := 0.00;
  WHILE (v_iswhile = 1) LOOP
  SELECT CAST((RANDOM() * 1000000) AS DECIMAL(6)) INTO v_otp;
  IF (LENGTH(CAST(v_otp AS TEXT)) = 6) THEN
  v_iswhile := 0;
  ELSE
  v_iswhile := 1;
  END IF;
  END LOOP;
  BEGIN
  IF (v_callingtype = 0) THEN
  v_stroutput := 'Invalid Call.';
  RETURN;
  ELSE
  IF (v_callingtype = 2) THEN
  IF (v_transactionpassword = '') THEN
  v_stroutput := 'OTP Is Blank';
  RETURN;
  END IF;
  IF EXISTS(SELECT 1 FROM tbl_shoppingotpmaster WHERE plid = v_plid AND active = 1 AND status = 1 AND otp = v_transactionpassword AND mode = v_mode AND username = v_username) THEN
  SELECT MAX(datetime), COALESCE(MAX(amountforuse), 0.00) INTO v_previousotpdateandtime, v_amountforuse FROM tbl_shoppingotpmaster WHERE plid = v_plid AND active = 1 AND status = 1 AND otp = v_transactionpassword AND mode = v_mode AND username = v_username LIMIT 1;
  ELSE
  v_previousotpdateandtime := NULL;
  END IF;
  IF (v_previousotpdateandtime IS NULL) THEN
  v_stroutput := 'Invalid OTP';
  RETURN;
  END IF;
  SELECT CAST(AGE(CAST(CAST(dbo.FUN_GETCURRENTDATE() AS TIMESTAMP) AS TIMESTAMP), CAST(CAST(v_previousotpdateandtime AS TIMESTAMP) AS TIMESTAMP)) AS BIGINT) INTO v_noofminute;
  IF (v_noofminute > 5) THEN
  v_stroutput := 'Your OTP Expired try again';
  RETURN;
  END IF;
  IF ((CASE WHEN v_mode = 2 THEN v_jc WHEN v_mode = 3 THEN v_iwallet ELSE 0 END) <> v_amountforuse) THEN
  v_stroutput := 'OTP Does Not Match For Requested Amount';
  RETURN;
  END IF;
  END IF;
  END IF;
  IF (v_mode = 2) THEN
  v_query := '';
  IF (v_username <> '') THEN
  v_regno := 0;
  IF EXISTS(SELECT 1 FROM db_mlmsoftware.dbo.portal_login WHERE username = v_username AND active = 1) THEN
  SELECT regno INTO v_regno FROM db_mlmsoftware.dbo.portal_login WHERE username = v_username AND active = 1;
  ELSE
  SELECT 0 INTO v_regno;
  END IF;
  IF (v_regno = 0) THEN
  v_stroutput := 'Invalid Username.';
  RETURN;
  END IF;
  SELECT mobile INTO v_mobile FROM db_mlmsoftware.dbo.member_master WHERE regno = v_regno;
  IF (v_mobile = '') THEN
  v_stroutput := 'Invalid Mobile Number.';
  RETURN;
  END IF;
  v_query := 'SELECT ' || CAST(0.00000000 AS VARCHAR(30)) || ' AS EWALLETCONSUMEPER,' || CAST(0.00000000 AS VARCHAR(30)) || ' AS COINWALLETCONSUMEPER,      
                ' || CAST(0.00000000 AS VARCHAR(30)) || ' AS COMMISSIONWALLETCONSUMEPER,TOTALAVAILABLESHOPPINGPOINTS AS POINTREDEEMPERCENT
				,(''' || v_mobile || ''')As Mobile,(''' || v_otp || ''')As OTP,
				(''success'')As StrOutPut FROM       
       [Db_MLMSoftware].[DBO].MEMBER_PERFORMANCE   WHERE       
       REGNO =' || CAST(v_regno AS VARCHAR(10));
  EXECUTE v_query;
  END IF;
  ELSE
  IF (v_mode = 3) THEN
  v_query := '';
  IF (v_username <> '') THEN
  v_regno := 0;
  IF EXISTS(SELECT 1 FROM db_mlmsoftware.dbo.portal_login WHERE username = v_username AND active = 1) THEN
  SELECT regno INTO v_regno FROM db_mlmsoftware.dbo.portal_login WHERE username = v_username AND active = 1;
  ELSE
  SELECT 0 INTO v_regno;
  END IF;
  IF (v_regno = 0) THEN
  v_stroutput := 'Invalid Username.';
  RETURN;
  END IF;
  v_reference_regno := 0;
  v_available_fund := 0.00;
  v_availablecoinwallet := 0.00;
  v_availablecommissionwallet := 0.00;
  v_reference_regno := v_regno;
  SELECT mobile INTO v_mobile FROM db_mlmsoftware.dbo.member_master WHERE regno = v_reference_regno;
  IF (v_mobile = '') THEN
  v_stroutput := 'Invalid Mobile Number.';
  RETURN;
  END IF;
  SELECT available_fund, availablecoinwallet, availablecommissionwallet INTO v_available_fund, v_availablecoinwallet, v_availablecommissionwallet FROM db_mlmsoftware.dbo.member_performance WHERE regno = v_reference_regno;
  v_query := 'SELECT ' || CAST(v_available_fund AS VARCHAR(30)) || ' AS EWALLETCONSUMEPER,' || CAST(v_availablecoinwallet AS VARCHAR(30)) || ' AS COINWALLETCONSUMEPER,      
                ' || CAST(v_availablecommissionwallet AS VARCHAR(30)) || ' AS COMMISSIONWALLETCONSUMEPER,
				(0.00000000) AS POINTREDEEMPERCENT,(''' || v_mobile || ''')As Mobile,(''' || v_otp || ''')As OTP,
				(''success'')As StrOutPut FROM       
       [Db_MLMSoftware].[DBO].MEMBER_PERFORMANCE   WHERE       
       REGNO =' || CAST(v_regno AS VARCHAR(10));
  EXECUTE v_query;
  END IF;
  END IF;
  END IF;
  v_stroutput := 'success';
  IF (v_callingtype = 1) THEN
  UPDATE tbl_shoppingotpmaster SET active = 0 WHERE plid = v_plid AND username = v_username AND mode = v_mode;
  INSERT INTO tbl_shoppingotpmaster (plid, username, amountforuse, mode, otp, status, active, datetime) VALUES (v_plid, v_username, (CASE WHEN v_mode = 2 THEN v_jc WHEN v_mode = 3 THEN v_iwallet ELSE 0 END), v_mode, v_otp, 1, 1, dbo.FUN_GETCURRENTDATE());
  END IF;
  EXCEPTION WHEN OTHERS THEN
  v_stroutput := 'Wallet under maintainance try later.';
  RETURN;
  END;
END;
$$;


--
-- Name: usp_distributorprepaid_setting(integer, integer, character varying, character varying, character varying, character varying, integer, character varying, numeric, numeric, numeric); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_distributorprepaid_setting(v_startrowindex integer DEFAULT 1, v_maxrows integer DEFAULT 100, v_fromdate character varying DEFAULT ''::character varying, v_todate character varying DEFAULT ''::character varying, v_searchfiel character varying DEFAULT '.'::character varying, v_searchvalue character varying DEFAULT ''::character varying, v_totalcount integer DEFAULT 0, v_did character varying DEFAULT ''::character varying, v_totalcredit numeric DEFAULT 0, v_totaldebit numeric DEFAULT 0, v_availableamount numeric DEFAULT 0) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_minindex INT;
  v_maxindex INT;
  v_query text;
BEGIN
  -- SET option (removed)
  v_minindex := (v_startrowindex - 1) * v_maxrows + 1;
  v_maxindex := v_startrowindex * v_maxrows;
  DROP TABLE IF EXISTS tmp_managedistributorlist;
  CREATE TEMP TABLE tmp_managedistributorlist (ROWNUMBER BIGINT,
	NAME VARCHAR(150),
	Email_Id VARCHAR(200),
	Contact VARCHAR(200),
	DPSID bigint,
	DID Bigint,
	credit_wallet decimal(18,2),
	Used_wallet decimal(18,2),
	Available_wallet decimal(18,2),
	CreatedDate timestamp,
	Status int,
	Emp_ID  Bigint) ON COMMIT DROP;
  v_query := 'INSERT INTO #MANAGEDISTRIBUTORLIST SELECT ROW_NUMBER() OVER (ORDER BY DPS.DPSID DESC) AS ROWNUMBER,ISNULL(dm.companyname,'''') AS NAME ,ISNULL(DL.EmailId,'''') AS Email_Id,
ISNULL(DL.PHONE,'''') AS ContactNo,ISNULL(DPS.DPSID,0)AS DPSID,ISNULL(DL.DID,0)AS DID,ISNULL(DPS.credit_wallet,0)AS credit_wallet ,ISNULL(DPS.Used_wallet,0)AS Used_wallet ,
ISNULL(DPS.Available_wallet,0)AS Available_wallet ,ISNULL(DPS.CreatedDate,0)AS CreatedDate ,ISNULL(DPS.Status,0)AS Status ,
ISNULL(DPS.Emp_ID,0)AS Emp_ID
FROM TBL_DISTRIBUTOR DL left join tbl_Distributor_prepaid_setting DPS ON  DL.Pmid=DPS.PMID 
left join DISTRIBUTOR_master dm on dm.pmid=DL.pmid 
where  DL.Active=1 and iskycapproved=1 and DL.Status=1 ';
  IF ((v_searchfiel <> '') AND (v_searchvalue <> '')) THEN
  IF (v_searchfiel = 'Company Name') THEN
  v_query := v_query || ' And dm.companyname like ''%' || v_searchvalue || '%''';
  END IF;
  END IF;
  IF ((v_searchfiel <> '') AND (v_searchvalue <> '')) THEN
  IF (v_searchfiel = 'Email ID') THEN
  v_query := v_query || ' And DL.EmailId = ''' || v_searchvalue || '''';
  RAISE NOTICE '%', v_query;
  END IF;
  END IF;
  IF ((v_searchfiel <> '') AND (v_searchvalue <> '')) THEN
  IF (v_searchfiel = 'Mobile No.') THEN
  v_query := v_query || ' And DL.PHONE = ''' || v_searchvalue || '''';
  RAISE NOTICE '%', v_query;
  END IF;
  END IF;
  IF ((v_fromdate <> '') AND (v_todate = '')) THEN
  v_query := v_query || ' AND CONVERT(DATE, DPS.CreatedDate, 105) =  CONVERT(DATE, ''' || v_fromdate || ''', 105) ';
  END IF;
  IF ((v_fromdate = '') AND (v_todate <> '')) THEN
  v_query := v_query || ' AND CONVERT(DATE, DPS.CreatedDate, 105) =  CONVERT(DATE, ''' || v_todate || ''', 105)';
  END IF;
  IF ((v_fromdate <> '') AND (v_todate <> '')) THEN
  v_query := v_query || ' AND CONVERT(DATE, DPS.CreatedDate, 105) BETWEEN CONVERT(DATE, ''' || v_fromdate || ''', 105) AND  CONVERT(DATE, ''' || v_todate || ''', 105) ';
  END IF;
  RAISE NOTICE '%', v_query;
  EXECUTE v_query;
  RETURN QUERY SELECT * FROM tmp_managedistributorlist WHERE rownumber BETWEEN v_minindex AND v_maxindex;
  SELECT SUM(credit_wallet) INTO v_totalcredit FROM tmp_managedistributorlist WHERE rownumber BETWEEN v_minindex AND v_maxindex;
  SELECT SUM(used_wallet) INTO v_totaldebit FROM tmp_managedistributorlist WHERE rownumber BETWEEN v_minindex AND v_maxindex;
  SELECT SUM(available_wallet) INTO v_availableamount FROM tmp_managedistributorlist WHERE rownumber BETWEEN v_minindex AND v_maxindex;
  SELECT COUNT(rownumber) INTO v_totalcount FROM tmp_managedistributorlist;
  DROP TABLE IF EXISTS tmp_managedistributorlist;
  -- SET option (removed)
END;
$$;


