-- Name: usp_distributorprepaid_setting_insertupdate(bigint, bigint, numeric, numeric, numeric, integer, bigint, integer, character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_distributorprepaid_setting_insertupdate(v_did bigint DEFAULT 0, v_dpsid bigint DEFAULT 1, v_credit_wallet numeric DEFAULT NULL::numeric, v_used_wallet numeric DEFAULT 0, v_available_wallet numeric DEFAULT 0, v_status integer DEFAULT 1, v_emp_id bigint DEFAULT 1, v_mode integer DEFAULT 1, INOUT v_strresult character varying DEFAULT ''::character varying) RETURNS character varying
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_maxid INT;
BEGIN
  -- BEGIN TRAN (removed)
  -- SET option (removed)
  IF (v_mode = 1) THEN
  v_maxid := 0;
  IF EXISTS(SELECT 1 FROM tbl_distributor_prepaid_setting WHERE pmid = v_did) THEN
  INSERT INTO tbl_distributor_prepaid_setting_history SELECT * FROM tbl_distributor_prepaid_setting WHERE dpsid = v_dpsid;
  UPDATE tbl_distributor_prepaid_setting SET credit_wallet = COALESCE(credit_wallet, 0) + v_credit_wallet, available_wallet = COALESCE(available_wallet, 0) + v_credit_wallet, status = v_status WHERE pmid = v_did;
  v_strresult := 'Update';
  ELSE
  INSERT INTO tbl_distributor_prepaid_setting (pmid, credit_wallet, used_wallet, available_wallet, createddate, status, emp_id) VALUES (v_did, v_credit_wallet, v_used_wallet, v_credit_wallet, CURRENT_TIMESTAMP, v_status, v_emp_id);
  v_strresult := 'Add';
  END IF;
  END IF;
  IF (0 <> 0) THEN
  v_strresult := 'Error';
  -- ROLLBACK (removed)
  RETURN;
  END IF;
  -- COMMIT (removed)
  -- SET option (removed)
END;
$$;


