CREATE FUNCTION dbo.usp_downloaded_excel_history(v_startrowindex integer DEFAULT 1, v_maxrows integer DEFAULT 100, v_orderid character varying DEFAULT ''::character varying, v_docketno character varying DEFAULT ''::character varying, v_fromdate character varying DEFAULT ''::character varying, v_todate character varying DEFAULT ''::character varying, v_totalcount integer DEFAULT 0, v_invoiceno character varying DEFAULT ''::character varying) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_minindex INT;
  v_maxindex INT;
  v_query text;
BEGIN
  v_minindex := (v_startrowindex - 1) * v_maxrows + 1;
  v_maxindex := v_startrowindex * v_maxrows;
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp (ROWNUMBER INT GENERATED BY DEFAULT AS IDENTITY, 
	ORDERID VARCHAR(100),  
	ITEM_NAME text, 
	CUSTOMER_NAME VARCHAR(500), 
    SHIPPING_ADD1 VARCHAR(1000),  
	SHIPPING_PINCODE VARCHAR(50),     
	SHIPPING_MOBILENO  VARCHAR(50),        
	COLLECTABLE_AMOUNT decimal(18,2),
	INVOICENO VARCHAR(500),	
	PAYMODE VARCHAR(50),
	DOCKETNO VARCHAR(500), 	
	UPLOADED_DATE timestamp) ON COMMIT DROP;
  v_query := 'INSERT INTO #TEMP select ORDERID,ITEM_NAME,CUSTOMER_NAME,SHIPPING_ADD1,SHIPPING_PINCODE,SHIPPING_MOBILENO,COLLECTABLE_AMOUNT 
 ,INVOICENO,PAYMODE,DOCKETNO,UPLOADED_DATE from TBL_DOWNLOADED_COURIERPARTNER_EXCEL WHERE 1=1 ';
  IF ((v_fromdate <> '') AND (v_todate = '')) THEN
