    LANGUAGE plpgsql
    AS $$
DECLARE
  v_minindex int;
  v_maxindex int;
  v_final_sqlquery text;
  v_direct_query text;
  v_level_query text;
BEGIN
  v_minindex := (v_startrowindex - 1) * v_maxrows + 1;
