  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp (rownumber bigint,
LIID bigint,
OPID varchar(100),
FROMID varchar(100),
TOID varchar(100),
AMOUNT decimal(18,2),
