ACTIVE boolean,
ISSKIP int,
kit_price numeric(19,4),
comm_per numeric(19,4),
tds_amt decimal(18,2),
tds_per numeric(19,4),
admin_amt decimal(18,2),
admin_per numeric(19,4),
member_active int,
fullName varchar(200),
fromloginid varchar(200),
tologinid varchar(200)) ON COMMIT DROP;
  v_final_sqlquery := '';
  v_direct_query := '';
  v_level_query := '';
  IF (COALESCE(v_incometype, '') = 'downline') THEN
  v_level_query := ' select ROW_NUMBER() OVER(ORDER BY wh.DATE desc) AS rowNumber,wh.LIID,wh.OPID,wh.FROMID,wh.TOID,
isnull(wh.AMOUNT,0),isnull(wh.INCOME,0),wh.LEVEL,wh.TYPE,wh.DATE,isnull(wh.REMARK,0),wh.PAYID,wh.STATUS,wh.ACTIVE,
wh.ISSKIP,wh.kit_price,wh.comm_per,wh.tds_amt,wh.tds_per,wh.admin_amt,wh.admin_per,isnull(wh.member_active,''''), 
 mm.FName+'' ''+isnull(mm.LName,'''') as fullName,isnull(pl.loginid,'''') as fromloginid,isnull(pl1.loginid,'''') as tologinid
  from LEVEL_INCOME wh inner join member_master mm on mm.loginid=wh.FROMID left join PORTAL_LOGIN pl on pl.plid=mm.plid 
 left join member_master mm1 on mm1.loginid=wh.TOID left join PORTAL_LOGIN pl1 on pl1.plid=mm1.plid where wh.status=1';
  ELSE
  IF (COALESCE(v_incometype, '') = 'direct') THEN
  v_direct_query := 'select ROW_NUMBER() OVER(ORDER BY di.DATE desc) AS rowNumber,di.DIID,di.OPID,di.FROMID,di.TOID,
isnull(di.AMOUNT,0),isnull(di.INCOME,0),di.LEVEL,di.TYPE,di.DATE,isnull(di.REMARK,0),di.PAYID,di.STATUS,
di.ACTIVE,di.ISSKIP,di.kit_price,di.comm_per,di.tds_amt,di.tds_per,di.admin_amt,di.admin_per,
isnull(di.member_active,''''), mm.FName+'' ''+isnull(mm.LName,'''') as fullName,isnull(pl.loginid,'''') as fromloginid,
isnull(pl1.loginid,'''') as tologinid from directIncomes di inner join member_master mm on mm.loginid=di.FROMID
 left join PORTAL_LOGIN pl on pl.plid=mm.plid left join member_master mm1 on mm1.loginid=di.TOID left join 
 PORTAL_LOGIN pl1 on pl1.plid=mm1.plid where di.status=1';
  ELSE
  v_direct_query := 'select ROW_NUMBER() OVER(ORDER BY wh.DATE desc) AS rowNumber,wh.LIID,wh.OPID,wh.FROMID,
wh.TOID,isnull(wh.AMOUNT,0),isnull(wh.INCOME,0),wh.LEVEL,wh.TYPE,wh.DATE,isnull(wh.REMARK,0),wh.PAYID,wh.STATUS,wh.ACTIVE,wh.ISSKIP,
wh.kit_price,wh.comm_per,wh.tds_amt,wh.tds_per,wh.admin_amt,wh.admin_per,isnull(wh.member_active,''''), 
 mm.FName+'' ''+isnull(mm.LName,'''') as fullName,isnull(pl.loginid,'''') as fromloginid,isnull(pl1.loginid,'''') as tologinid from LEVEL_INCOME wh 
 inner join member_master mm on mm.loginid=wh.FROMID left join PORTAL_LOGIN pl on pl.plid=mm.plid 
 left join member_master mm1 on mm1.loginid=wh.TOID left join PORTAL_LOGIN pl1 on pl1.plid=mm1.plid where wh.status=1';
  v_level_query := ' select ROW_NUMBER() OVER(ORDER BY di.DATE desc) AS rowNumber,di.DIID,di.OPID,di.FROMID,di.TOID,
 isnull(di.AMOUNT,0),isnull(di.INCOME,0),di.LEVEL,di.TYPE,di.DATE,isnull(di.REMARK,0),di.PAYID,di.STATUS,di.ACTIVE,
 di.ISSKIP,di.kit_price,di.comm_per,di.tds_amt,di.tds_per,di.admin_amt,di.admin_per,isnull(di.member_active,''''), 
 mm.FName+'' ''+isnull(mm.LName,'''') as fullName,isnull(pl.loginid,'''') as fromloginid,isnull(pl1.loginid,'''') as tologinid
  from directIncomes di inner join member_master mm on mm.loginid=di.FROMID left join PORTAL_LOGIN pl on pl.plid=mm.plid 
 left join member_master mm1 on mm1.loginid=di.TOID left join PORTAL_LOGIN pl1 on pl1.plid=mm1.plid where di.status=1 ';
  END IF;
  END IF;
  IF (v_plid <> '') THEN
  v_direct_query := v_direct_query || ' and  pl.loginid =''' || v_plid || ''' ';
  v_level_query := v_level_query || ' and  pl.loginid =''' || v_plid || ''' ';
  END IF;
  IF (v_searchfield <> '' AND v_searchvalue <> '') THEN
  IF (v_searchfield = 'loginid') THEN
  v_direct_query := v_direct_query || ' and pl.loginid LIKE ''%' || v_searchvalue || '%''';
  v_level_query := v_level_query || ' and pl.loginid LIKE ''%' || v_searchvalue || '%''';
  END IF;
  IF (v_searchfield = 'tologinid') THEN
  v_direct_query := v_direct_query || ' and pl1.loginid LIKE ''%' || v_searchvalue || '%''';
  v_level_query := v_level_query || ' and pl1.loginid LIKE ''%' || v_searchvalue || '%''';
  END IF;
  END IF;
  IF ((v_fromdate <> '') AND (v_todate = '')) THEN
  v_direct_query := v_direct_query || ' and CONVERT(date, DATE, 105) between  CONVERT(date, ''' || v_fromdate || ''') and  CONVERT(date, dbo.fun_getCurrentDate()) ';
  v_level_query := v_level_query || ' and CONVERT(date, wh.DATE, 105) between  CONVERT(date, ''' || v_fromdate || ''') and  CONVERT(date, dbo.fun_getCurrentDate()) ';
  END IF;
  IF ((v_fromdate = '') AND (v_todate <> '')) THEN
  v_direct_query := v_direct_query || ' and CONVERT(date, DATE, 105) between  CONVERT(date, ''' || v_todate || ''') and  CONVERT(date, dbo.fun_getCurrentDate()) ';
  v_level_query := v_level_query || ' and CONVERT(date, DATE, 105) between  CONVERT(date, ''' || v_todate || ''') and  CONVERT(date, dbo.fun_getCurrentDate()) ';
  END IF;
  IF ((v_fromdate <> '') AND (v_todate <> '')) THEN
  v_direct_query := v_direct_query || ' and CONVERT(date, DATE) between CONVERT(date, ''' || v_fromdate || ''') and  CONVERT(date, ''' || v_todate || ''') ';
  v_level_query := v_level_query || ' and CONVERT(date, DATE) between CONVERT(date, ''' || v_fromdate || ''') and  CONVERT(date, ''' || v_todate || ''') ';
  END IF;
  IF (v_fromloginid <> '') THEN
  v_direct_query := v_direct_query || ' AND ISNULL(pl.loginid,'''') LIKE ''%' || v_fromloginid || '%''';
  v_level_query := v_level_query || ' AND ISNULL(pl.loginid,'''') LIKE ''%' || v_fromloginid || '%''';
  END IF;
  IF (v_tologinid <> '') THEN
  v_direct_query := v_direct_query || ' AND ISNULL(pl1.loginid,'''') LIKE ''%' || v_tologinid || '%''';
  v_level_query := v_level_query || ' AND ISNULL(pl1.loginid,'''') LIKE ''%' || v_tologinid || '%''';
  END IF;
  IF (COALESCE(v_incometype, '') = 'downline') THEN
  v_final_sqlquery := v_level_query;
  ELSE
  IF (COALESCE(v_incometype, '') = 'direct') THEN
  v_final_sqlquery := v_direct_query;
  ELSE
  v_final_sqlquery := v_level_query || ' union ' || v_direct_query;
  END IF;
  END IF;
  EXECUTE 'insert into #temp  ' || v_final_sqlquery;
  DROP TABLE IF EXISTS tmp_temp_1;
  CREATE TEMP TABLE tmp_temp_1 ON COMMIT DROP AS SELECT ROW_NUMBER() OVER (ORDER BY date ASC NULLS FIRST) AS rownumber, liid, opid, fromid, toid, amount, income, level, type, date, remark, payid, status, active, isskip, kit_price, comm_per, tds_amt, tds_per, admin_amt, admin_per, member_active, fullname, fromloginid, tologinid FROM tmp_temp;
  RETURN QUERY SELECT * FROM tmp_temp_1 WHERE rownumber BETWEEN v_startrowindex AND v_maxrows;
  SELECT COUNT(rownumber), SUM(COALESCE(amount, 0)), SUM(COALESCE(tds_amt, 0)), SUM(COALESCE(admin_amt, 0)), SUM(COALESCE(income, 0)) INTO v_totalcount, v_total_earn_amt, v_total_tds_amt, v_total_admin_chrg, v_total_payable_amt FROM tmp_temp;
  DROP TABLE IF EXISTS tmp_temp;
  -- SET option (removed)
END;
$$;


--
-- Name: usp_earningspointsmanagement(integer, integer, numeric, text, text); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_earningspointsmanagement(v_mode integer DEFAULT 1, v_plid integer DEFAULT 0, v_point numeric DEFAULT 0.00, v_date text DEFAULT ''::text, v_intoutputresult text DEFAULT ''::text) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_regno Int;
  v_amount Decimal(10,2);
  v_netamount Decimal(10,2);
  v_currentincome Decimal(10,2);
  v_tds_per double precision;
  v_tds Decimal(10,2);
  v_admincharge_per double precision;
  v_admincharge Decimal(10,2);
BEGIN
  v_regno := 0;
  SELECT regno INTO v_regno FROM member_master WHERE plid = v_plid;
  IF (v_mode = 1) THEN
  RETURN QUERY SELECT ROW_NUMBER() OVER (ORDER BY date DESC NULLS LAST) AS sno, CAST(TO_CHAR(date, 'DD TMMon YYYY') AS VARCHAR(11)) AS date, ('N/A') AS url, COALESCE(SUM(earnedamount), 0) AS amount, ('Credited In Cash Wallet') AS status FROM tbl_membertaskincomedetails WHERE isactive = 1 AND plid = v_plid GROUP BY date, isactive HAVING COALESCE(SUM(earnedamount), 0) > 0;
  END IF;
  IF (v_mode = 2) THEN
  RETURN QUERY SELECT ROW_NUMBER() OVER (ORDER BY date DESC NULLS LAST) AS sno, CAST(TO_CHAR(v_date, 'DD TMMon YYYY') AS VARCHAR(11)) AS date, url, COALESCE(earnedamount, 0) AS amount, ('Credited In Cash Wallet') AS status, (CASE WHEN COALESCE(activitytype, 1) = 1 THEN 'Viewed' WHEN COALESCE(activitytype, 1) = 2 THEN 'Shared' WHEN COALESCE(activitytype, 1) = 3 THEN 'Blog' WHEN COALESCE(activitytype, 1) = 4 THEN 'Classified' WHEN COALESCE(activitytype, 1) = 5 THEN 'Business Listing' END) AS activitytype FROM tbl_membertaskincomedetails AS tmti INNER JOIN tbl_addtrafficbooster AS tatbid ON tmti.tatbid = tatbid.tatbid WHERE tmti.isactive = 1 AND tmti.plid = v_plid AND CAST(date AS DATE) = CAST(v_date AS DATE);
  ELSE
  IF (v_mode = 3) THEN
  IF (v_point <= (SELECT CAST(COALESCE(MAX(totalavailableamount), 0) AS BIGINT) AS totalavailableamount FROM tbl_membertaskincome WHERE plid = v_plid)) THEN
  v_amount := 0.00;
  v_netamount := 0.00;
  v_currentincome := 0.00;
  v_tds_per := 0.00;
  v_tds := 0.00;
  v_admincharge_per := 0.00;
  v_admincharge := 0.00;
  SELECT ((v_point * 1)) INTO v_amount;
  SELECT COALESCE(v_amount * v_tds_per / 100, 0) INTO v_tds;
  SELECT COALESCE(v_amount * v_admincharge_per / 100, 0) INTO v_admincharge;
  SELECT v_amount - v_tds - v_admincharge INTO v_netamount;
  UPDATE member_performance SET currentincome = currentincome + v_netamount WHERE regno = v_regno;
  SELECT currentincome INTO v_currentincome FROM member_performance WHERE regno = v_regno;
  INSERT INTO money_statements (regno, processdate, crdrtype, cr_amount, dr_amount, remarks, type, typeid, status, traceno, pmoid, balance, old_bal) VALUES (v_regno, dbo.FUN_GETCURRENTDATE(), 'CR', v_amount, 0, 'Redeem Earned Points', 'Redeem Earned Points', 0, 1, '', 0, COALESCE(v_currentincome, 0), COALESCE(v_currentincome - v_netamount, 0));
  UPDATE tbl_membertaskincome SET totalwithdrawlamount = (totalwithdrawlamount + v_point), totalavailableamount = (totalavailableamount - v_point) WHERE plid = v_plid;
  v_intoutputresult := 'Point Redeemed Successfully !!!';
  ELSE
  v_intoutputresult := 'You Do Not Have Sufficient Point For Redeem. Sorry !!!';
  END IF;
  ELSE
  IF (v_mode = 4) THEN
  IF (v_point <= (SELECT CAST(COALESCE(MAX(totalavailableamount), 0) AS BIGINT) AS totalavailableamount FROM tbl_membertaskincome WHERE plid = v_plid)) THEN
  INSERT INTO tbl_usertrafficbooster (ttbid, plid, purchaseddate, isactive, isgiven, activationdate, activatetilldate, remainnoofhits, paymentmode, paymentmodename, paymentstatus, bankname, branchname, referenceno, referencedate, commentorremark, noofdaysvalidity, noofhits, flushnoofhits) VALUES (0, v_plid, CURRENT_TIMESTAMP, 1, 1, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP + INTERVAL '30 DAY', v_point, 0, '', 1, '', '', '', '', 'Use Earned Points', 30, v_point, 0);
  UPDATE tbl_membertaskincome SET totalwithdrawlamount = (totalwithdrawlamount + v_point), totalavailableamount = (totalavailableamount - v_point) WHERE plid = v_plid;
  v_intoutputresult := 'Point Used Successfully !!!';
  ELSE
  v_intoutputresult := 'You Do Not Have Sufficient Point For Use. Sorry !!!';
  END IF;
  END IF;
  END IF;
  END IF;
END;
$$;


