--
-- Name: usp_editbusinesslisting(character varying, integer, character varying, character varying, character varying, character varying, character varying, character varying, character varying, character varying, character varying, character varying, character varying, character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_editbusinesslisting(v_companydesc character varying DEFAULT ''::character varying, v_pmid integer DEFAULT 0, v_phoneno character varying DEFAULT ''::character varying, v_building character varying DEFAULT ''::character varying, v_landmark character varying DEFAULT ''::character varying, v_comemailid character varying DEFAULT ''::character varying, v_statename character varying DEFAULT ''::character varying, v_cityname character varying DEFAULT ''::character varying, v_aid character varying DEFAULT ''::character varying, v_yearofestable character varying DEFAULT ''::character varying, v_cperwebsite character varying DEFAULT ''::character varying, v_noofemployee character varying DEFAULT '0'::character varying, v_zipcode character varying DEFAULT ''::character varying, INOUT v_strresult character varying DEFAULT NULL::character varying) RETURNS character varying
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_sid int;
  v_ctid int;
  v_cid int;
BEGIN
  v_sid := 0;
  v_ctid := 0;
  v_cid := 0;
  SELECT cid INTO v_cid FROM portal_master WHERE pmid = v_pmid;
  SELECT COALESCE(sid, 0) INTO v_sid FROM state WHERE RTRIM(LTRIM(statename)) = RTRIM(LTRIM(v_statename)) AND cid = v_cid;
  SELECT COALESCE(ctid, 0) INTO v_ctid FROM city WHERE RTRIM(LTRIM(cityname)) = RTRIM(LTRIM(v_cityname)) AND cid = v_cid;
  -- BEGIN TRAN (removed)
  v_strresult := 'Your company profile updated sucessfully';
  UPDATE portal_master SET mobileno = v_phoneno, sid = v_sid, ctid = v_ctid, areaname = v_aid, url = v_cperwebsite, address = v_landmark, companydesc = v_companydesc WHERE pmid = v_pmid;
  UPDATE portal_master_details SET mobileno = v_phoneno, building = v_building, lankmark = v_landmark, comemailid = v_comemailid, cid = v_cid, sid = v_sid, ctid = v_ctid, areaname = v_aid, cperwebsite = v_cperwebsite, yearofestable = v_yearofestable, noofemployee = v_noofemployee, zipcode = v_zipcode WHERE pmid = v_pmid;
  IF (0 <> 0) THEN
  v_strresult := 'There is some error in the page!!!!';
  -- ROLLBACK (removed)
  RETURN;
  END IF;
  -- COMMIT (removed)
END;
$$;


--
-- Name: usp_editbusinesslisting_new(text, character varying, integer, character varying, character varying, character varying, character varying, character varying, character varying, character varying, character varying, character varying, character varying, character varying, character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_editbusinesslisting_new(v_companyname text DEFAULT ''::text, v_companydesc character varying DEFAULT ''::character varying, v_pmid integer DEFAULT 0, v_phoneno character varying DEFAULT ''::character varying, v_building character varying DEFAULT ''::character varying, v_landmark character varying DEFAULT ''::character varying, v_comemailid character varying DEFAULT ''::character varying, v_statename character varying DEFAULT ''::character varying, v_cityname character varying DEFAULT ''::character varying, v_aid character varying DEFAULT ''::character varying, v_yearofestable character varying DEFAULT ''::character varying, v_cperwebsite character varying DEFAULT ''::character varying, v_noofemployee character varying DEFAULT '0'::character varying, v_zipcode character varying DEFAULT ''::character varying, INOUT v_strresult character varying DEFAULT NULL::character varying) RETURNS character varying
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_sid int;
  v_ctid int;
  v_cid int;
  v_originial_aid varchar(100);
  v_isverified int;
BEGIN
  -- BEGIN TRAN (removed)
  v_sid := 0;
  v_ctid := 0;
  v_cid := 0;
  SELECT cid INTO v_cid FROM portal_master WHERE pmid = v_pmid;
  SELECT COALESCE(sid, 0) INTO v_sid FROM state WHERE RTRIM(LTRIM(statename)) = RTRIM(LTRIM(v_statename)) AND cid = v_cid;
  SELECT COALESCE(ctid, 0) INTO v_ctid FROM city WHERE RTRIM(LTRIM(cityname)) = RTRIM(LTRIM(v_cityname)) AND cid = v_cid AND sid = v_sid;
  SELECT COALESCE(aid, 0) INTO v_originial_aid FROM area_master WHERE areaname = v_aid AND pincode = v_zipcode AND ctid = v_ctid AND cid = v_cid;
  IF (v_sid = 0) THEN
  v_strresult := 'State Not Selected !';
  -- ROLLBACK (removed)
  RETURN;
  END IF;
  IF (v_ctid = 0) THEN
  v_strresult := 'City Not Selected !';
  -- ROLLBACK (removed)
  RETURN;
  END IF;
  v_strresult := 'ok';
  SELECT COALESCE(isverified, 0) INTO v_isverified FROM portal_master WHERE pmid = v_pmid;
  IF (v_isverified = 2) THEN
  UPDATE portal_master SET isverified = 0 WHERE pmid = v_pmid;
  END IF;
  UPDATE portal_master SET title = v_companyname, companyname = v_companyname, sid = v_sid, ctid = v_ctid, areaname = v_aid, url = v_cperwebsite, companydesc = v_companydesc, mobileno = v_phoneno, address = v_building, lankmark = v_landmark, comemailid = v_comemailid, cid = v_cid, yearofestable = v_yearofestable, noofemployee = v_noofemployee, pincode = v_zipcode, aid = v_originial_aid WHERE pmid = v_pmid;
  IF (0 <> 0) THEN
  v_strresult := 'Some error occured,Please try again !';
  -- ROLLBACK (removed)
  RETURN;
  END IF;
  -- COMMIT (removed)
END;
$$;


--
-- Name: usp_editcontactdetails(bigint, character varying, character varying, character varying, character varying, character varying, character varying, integer, text, text, text, integer, integer, integer, integer, text, text, text); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_editcontactdetails(v_plid bigint DEFAULT 1, v_cpertitle character varying DEFAULT ''::character varying, v_cperdesignation character varying DEFAULT ''::character varying, v_cpermobileno character varying DEFAULT ''::character varying, v_cperemailid character varying DEFAULT ''::character varying, v_firstname character varying DEFAULT ''::character varying, v_lastname character varying DEFAULT ''::character varying, INOUT v_intresult integer DEFAULT 0, v_username text DEFAULT ''::text, v_dob text DEFAULT ''::text, v_fatherormothername text DEFAULT ''::text, v_gender integer DEFAULT 0, v_highestqualification integer DEFAULT 0, v_mode integer DEFAULT 2, v_isverified integer DEFAULT 1, v_idtype text DEFAULT ''::text, v_idrefno text DEFAULT ''::text, v_panno text DEFAULT ''::text) RETURNS integer
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_getduplicate_mobile INT;
  v_getduplicate_emailid INT;
  v_getduplicate_username text;
  v_oldusername text;
  v_oldmobile text;
  v_oldemail text;
  v_pancard_count INT;
BEGIN
  -- BEGIN TRAN (removed)
  -- SET option (removed)
  IF (COALESCE(v_intresult, 0) > 1) THEN
  -- COMMIT (removed)
  RETURN;
  END IF;
  v_getduplicate_mobile := 0;
  v_getduplicate_emailid := 0;
  v_getduplicate_username := '';
  IF (v_cpermobileno <> '') THEN
  SELECT COUNT(1) INTO v_getduplicate_mobile FROM tbl_customerlogin WHERE phone = v_cpermobileno;
  v_intresult := (CASE WHEN v_getduplicate_mobile > 0 THEN 7 ELSE 0 END);
  END IF;
  IF (v_cperemailid <> '') THEN
  SELECT COUNT(1) INTO v_getduplicate_emailid FROM tbl_customerlogin WHERE emailid = v_cperemailid;
  v_intresult := (CASE WHEN v_getduplicate_emailid > 0 THEN 6 ELSE 0 END);
  END IF;
  SELECT COUNT(1) INTO v_getduplicate_username FROM tbl_customerlogin WHERE username = v_username AND clid <> v_plid;
  IF (v_getduplicate_username = 0) THEN
  SELECT COUNT(1) INTO v_getduplicate_username FROM tbl_customerlogin WHERE username = v_username AND clid <> v_plid;
  END IF;
  IF (COALESCE(v_intresult, 0) = 6) THEN
  v_intresult := 6;
  -- ROLLBACK (removed)
  RETURN;
  END IF;
  IF (COALESCE(v_intresult, 0) = 7) THEN
  v_intresult := 7;
  -- ROLLBACK (removed)
  RETURN;
  END IF;
  SELECT COUNT(1) INTO v_getduplicate_mobile FROM portal_login_temp WHERE phone = v_cpermobileno AND active = 0;
  SELECT COUNT(1) INTO v_getduplicate_emailid FROM portal_login_temp WHERE loginid = v_cperemailid AND active = 0;
  SELECT COUNT(1) INTO v_getduplicate_username FROM portal_login_temp WHERE username = v_username AND active = 0;
  IF (v_getduplicate_username = 0) THEN
  SELECT COUNT(1) INTO v_getduplicate_username FROM tbl_customerlogin WHERE username = v_username AND clid <> v_plid;
  END IF;
  IF (COALESCE(v_intresult, 0) > 0) THEN
  -- COMMIT (removed)
  RETURN;
  END IF;
  v_oldusername := '';
  v_oldmobile := '';
  v_oldemail := '';
  SELECT username, phone, emailid INTO v_oldusername, v_oldmobile, v_oldemail FROM tbl_customerlogin WHERE clid = v_plid;
  IF (v_panno <> '') THEN
  v_pancard_count := 0;
  SELECT COUNT(pancardno) INTO v_pancard_count FROM bank_accounts WHERE pancardno = v_panno AND regno <> (SELECT regno FROM portal_login WHERE plid = v_plid);
  IF (COALESCE(v_pancard_count, 0) > 3) THEN
  v_intresult := 3;
  -- COMMIT (removed)
  RETURN;
  END IF;
  END IF;
  IF (v_mode = 1) THEN
  IF (v_idtype = '' AND v_idrefno = '' AND v_panno = '' AND v_dob = '') THEN
  v_intresult := (CASE WHEN COALESCE(v_firstname, '') = '' THEN 2 WHEN COALESCE(v_username, '') = '' THEN 8 ELSE 0 END);
  END IF;
  INSERT INTO portal_login_history SELECT title, fname, lname, phone, designation, emailid, username, loginid, dob, fatherormothername, gender, highestqualification, idtype, idrefno, panno, plid, dbo.FUN_GETCURRENTDATE() FROM portal_login WHERE plid = v_plid;
  UPDATE tbl_customerlogin SET title = (CASE WHEN v_cpertitle = '' THEN title ELSE v_cpertitle END), fname = (CASE WHEN v_firstname = '' THEN fname ELSE v_firstname END), lname = (CASE WHEN v_lastname = '' THEN lname ELSE v_lastname END), designation = (CASE WHEN v_cperdesignation = '' THEN designation ELSE v_cperdesignation END), username = (CASE WHEN v_username = '' THEN username ELSE v_username END), loginid = loginid, dob = (CASE WHEN v_dob = '' THEN dob ELSE v_dob END), fatherormothername = (CASE WHEN v_fatherormothername = '' THEN fatherormothername ELSE v_fatherormothername END), gender = (CASE WHEN v_gender = '' THEN gender ELSE v_gender END), highestqualification = (CASE WHEN v_highestqualification = '' THEN highestqualification ELSE v_highestqualification END), idtype = (CASE WHEN v_idtype = '' THEN idtype ELSE v_idtype END), idrefno = (CASE WHEN v_idrefno = '' THEN idrefno ELSE v_idrefno END), panno = (CASE WHEN v_panno = '' THEN panno ELSE v_panno END) WHERE clid = v_plid;
  IF (v_panno <> '') THEN
  UPDATE bank_accounts SET pancardno = v_panno WHERE active = 1 AND regno = (SELECT regno FROM member_master WHERE plid = v_plid);
  END IF;
