CREATE FUNCTION dbo.usp_editnewssearch(v_startrowindex integer, v_maxrows integer, v_orderbyfield character varying, v_asc boolean, v_searchfield character varying, v_searchvalue character varying, v_mode integer) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_recordcount int;
  v_regno bigint;
BEGIN
  -- SET option (removed)
  DROP TABLE IF EXISTS tmp_temp12;
  CREATE TEMP TABLE tmp_temp12 ON COMMIT DROP AS SELECT ROW_NUMBER() OVER (ORDER BY newsid DESC NULLS LAST) AS rownumber, newsid, news, newsdate FROM dbo.eventnews WHERE activeflag = 1;
  SELECT COUNT(*) INTO v_recordcount FROM tmp_temp12;
  IF (v_searchfield = 'news') THEN
  RETURN QUERY SELECT * FROM tmp_temp12 WHERE news LIKE '%' || v_searchvalue || '%';
  END IF;
  IF (v_searchfield = '') THEN
  RETURN QUERY SELECT * FROM tmp_temp12 WHERE rownumber BETWEEN v_startrowindex AND v_maxrows;
  END IF;
  DROP TABLE IF EXISTS tmp_temp12;
  -- SET option (removed)
END;
$$;


