--

CREATE FUNCTION dbo.usp_editpackage(v_kid integer DEFAULT 0) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_allselectedfeatureid text;
BEGIN
  v_allselectedfeatureid := '';
  SELECT COALESCE(v_allselectedfeatureid || ',', '') || CAST(tfmid AS VARCHAR) INTO v_allselectedfeatureid FROM tbl_kit_featuremaster WHERE kid = v_kid AND isactive = 1 AND isdeleted = 0;
  IF (v_allselectedfeatureid <> '') THEN
  v_allselectedfeatureid := SUBSTRING(v_allselectedfeatureid FROM 2 FOR LENGTH(CAST(v_allselectedfeatureid AS TEXT)));
  END IF;
  RETURN QUERY SELECT kid, title, (CASE WHEN image = '' THEN 'NoImage.jpg' WHEN image = NULL THEN 'NoImage.jpg' ELSE image END) AS image, type, CAST(amount AS DECIMAL(10, 2)) AS amount, CAST(pv AS DECIMAL(10, 2)) AS pv, roi, noofmonth, status, (v_allselectedfeatureid) AS allselectedfeatureid FROM kit_master WHERE kid = v_kid;
END;
$$;


--
-- Name: usp_electricityrecharges_details(integer, integer, integer, character varying, character varying, integer, character varying, character varying, character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_electricityrecharges_details(v_mode integer DEFAULT 0, v_startrowindex integer DEFAULT 1, v_maxrows integer DEFAULT 100, v_fromdate character varying DEFAULT ''::character varying, v_todate character varying DEFAULT ''::character varying, v_totalcount integer DEFAULT 0, v_searchfield character varying DEFAULT ''::character varying, v_searchvalue character varying DEFAULT ''::character varying, v_status character varying DEFAULT ''::character varying) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_minindex INT;
  v_maxindex INT;
  v_query text;
BEGIN
  v_minindex := (v_startrowindex - 1) * v_maxrows + 1;
  v_maxindex := v_startrowindex * v_maxrows;
  IF (v_mode = 0) THEN
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp (ROWNUMBER BIGINT GENERATED BY DEFAULT AS IDENTITY,   
 TCPRID BIGINT,         
 CLID BIGINT,           
 MOBILENO VARCHAR(100),   
 OPERATORTYPE VARCHAR(100),  
 RECHARGEAMOUNT DECIMAL(18,2),  
 TRANSACTIONID  VARCHAR(100),   
 RECHARGEDATE VARCHAR(100),   
 ADMINSTATUS VARCHAR(100),  
 NAME VARCHAR(100),  
 EMAILID VARCHAR(100),  
 OPERATORNAME VARCHAR(100),  
 OPERATORCODE VARCHAR(100),  
 ISANDROIDORWEB INT,  
  CASHWALLET DECIMAL(18,2),  
 VOUCHER DECIMAL(18,2),  
 ONLINEAMOUNT DECIMAL(18,2)) ON COMMIT DROP;
  v_query := 'INSERT INTO #TEMP SELECT TCPR.TCERID,TCPR.CLID,TCPR.MOBILENO,TCPR.OPERATORTYPE,  
 TCPR.RECHARGEAMOUNT,TCPR.TRANSACTIONID,CAST(TCPR.RECHARGEDATE AS VARCHAR(50)) ,TCPR.RECHARGESTATUS  
 ,(CL.FNAME+'' ''+CL.LNAME) AS NAME,CL.EMAILID,TCPR.OPERATORNAME,TCPR.OPERATORCODE,TCPR.ISANDROIDORWEB,  
  ISNUll(0,0),ISNULL(0,0),ISNULL(0,0)  
 FROM TBL_CUSTOMER_ELECTRICITY_RECHARGES TCPR      
  LEFT JOIN TBL_CUSTOMERLOGIN CL ON CL.CLID=TCPR.CLID   
  WHERE TCPR.RECHARGESTATUS Is Not Null';
  IF ((v_fromdate <> '') AND (v_todate = '')) THEN
  v_query := v_query || ' AND CONVERT(DATE, TCPR.RECHARGEDATE, 105) BETWEEN  CONVERT(DATE, ''' || v_fromdate || ''', 105) AND  CONVERT(DATE, DBO.FUN_GETCURRENTDATE(), 105)';
  END IF;
  IF ((v_fromdate = '') AND (v_todate <> '')) THEN
  v_query := v_query || 'AND CONVERT(DATE, TCPR.RECHARGEDATE, 105) BETWEEN  CONVERT(DATE, ''' || v_todate || ''', 105) AND  CONVERT(DATE, DBO.FUN_GETCURRENTDATE(), 105)';
  END IF;
  IF ((v_fromdate <> '') AND (v_todate <> '')) THEN
  v_query := v_query || 'AND CONVERT(DATE, TCPR.RECHARGEDATE, 105) BETWEEN CONVERT(DATE, ''' || v_fromdate || ''', 105) AND  CONVERT(DATE, ''' || v_todate || ''', 105)';
  END IF;
  IF (v_searchfield = 'NAME') THEN
  v_query := v_query || ' AND (CL.FNAME+CL.LNAME) LIKE ''%' || v_searchvalue || '%'' ';
  END IF;
  IF (v_searchfield = 'PHONE') THEN
  v_query := v_query || ' AND TCPR.MOBILENO LIKE ''%' || v_searchvalue || '%'' ';
  END IF;
  IF (v_searchfield = 'EMAILID') THEN
  v_query := v_query || ' AND CL.EMAILID LIKE ''%' || v_searchvalue || '%'' ';
  END IF;
  IF (v_searchfield = 'TRANSACTIONID') THEN
  v_query := v_query || ' AND TCPR.TRANSACTIONID LIKE ''%' || v_searchvalue || '%'' ';
  END IF;
  IF (v_status <> '') THEN
  v_query := v_query || ' AND TCPR.RECHARGESTATUS =''' || v_status || ''' ';
  END IF;
  v_query := v_query || ' ORDER BY TCPR.RECHARGEDATE DESC';
  EXECUTE v_query;
  RETURN QUERY SELECT rownumber, tcprid, clid, mobileno, operatortype, rechargeamount, transactionid, rechargedate, adminstatus, name, emailid, operatorname, operatorcode, isandroidorweb, cashwallet, voucher, onlineamount FROM tmp_temp WHERE rownumber BETWEEN v_minindex AND v_maxindex ORDER BY rownumber ASC NULLS FIRST;
  SELECT COUNT(rownumber) INTO v_totalcount FROM tmp_temp;
  DROP TABLE IF EXISTS tmp_temp;
  -- SET option (removed)
  END IF;
END;
$$;


--
-- Name: usp_email_modify(integer, integer, character varying, integer, character varying); Type: FUNCTION; Schema: dbo; Owner: -
