CREATE FUNCTION dbo.usp_email_modify(v_tmcemid integer, v_plid integer, v_email character varying, v_check integer, INOUT v_message character varying) RETURNS character varying
    LANGUAGE plpgsql
    AS $$
BEGIN
  -- BEGIN TRAN (removed)
