  IF EXISTS(SELECT email FROM tbl_member_customer_email WHERE email = v_email) THEN
  v_message := 'Email id already exist!';
  -- COMMIT (removed)
  RETURN;
  END IF;
  UPDATE tbl_member_customer_email SET email = v_email, isactive = v_check WHERE tmcemid = v_tmcemid;
  IF (0 <> 0) THEN
  v_message := 'Some error occurred !';
  -- ROLLBACK (removed)
  RETURN;
  END IF;
  -- COMMIT (removed)
END;
$$;


