  v_result := 'Insert';
  ELSE
  UPDATE tbl_companysettings SET companysendmailemailid = v_companysendmailemailid, companymailserver = v_companymailserver, companymailpassowrd = v_companymailpassowrd, companymailserverport = v_companymailserverport, companyinfoemailid = v_companysendmailemailid, companysupportemailid = v_companysendmailemailid, companynoreplyemailid = v_companysendmailemailid WHERE pmid = v_pmid;
  v_result := 'Update';
  END IF;
  ELSE
