--
-- Name: usp_emailapisetting(character varying, character varying, character varying, text, character varying, character varying, character varying, character varying, integer, integer, integer, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_emailapisetting(v_username character varying DEFAULT ''::character varying, v_title character varying DEFAULT ''::character varying, v_emailid character varying DEFAULT ''::character varying, v_hostname text DEFAULT ''::text, v_port character varying DEFAULT ''::character varying, v_password character varying DEFAULT ''::character varying, v_senderid character varying DEFAULT ''::character varying, v_sendername character varying DEFAULT ''::character varying, v_temid integer DEFAULT 0, v_isactive integer DEFAULT 1, v_mode integer DEFAULT 0, v_intresult integer DEFAULT 0) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF (v_mode = 1) THEN
  RETURN QUERY SELECT pl.username, temm.temid, temm.title, temm.emailid, temm.hostname, temm.port, temm.password, temm.senderid, temm.sendername, temm.isactive FROM tbl_emailmembermaster AS temm INNER JOIN portal_login AS pl ON temm.temid = pl.pmid WHERE pl.username LIKE '%' || v_username || '%';
  v_intresult := 1;
  END IF;
  IF (v_mode = 2) THEN
  UPDATE tbl_emailmembermaster SET title = v_title, emailid = v_emailid, hostname = v_hostname, port = v_port, password = v_password, senderid = v_senderid, sendername = v_sendername, isactive = v_isactive WHERE temid = v_temid;
  v_intresult := 3;
  IF (0 <> 0) THEN
  v_intresult := 0;
  RETURN;
  END IF;
  END IF;
END;
$$;


--
-- Name: usp_emailcampaignmaster(integer, integer, text, character varying, character varying, character varying, integer, integer, text, character varying, character varying, integer, integer, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_emailcampaignmaster(v_plid integer, v_fromemail integer DEFAULT 0, v_toemail text DEFAULT NULL::text, v_msgsubject character varying DEFAULT NULL::character varying, v_message character varying DEFAULT NULL::character varying, v_attachment character varying DEFAULT ''::character varying, v_mailtype integer DEFAULT 0, INOUT v_intresult integer DEFAULT NULL::integer, v_campaignname text DEFAULT ''::text, v_campaigndate character varying DEFAULT ''::character varying, v_campaigntime character varying DEFAULT ''::character varying, v_issendemail integer DEFAULT 3, v_tecmid integer DEFAULT 0, v_mode integer DEFAULT 0) RETURNS integer
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_frommail VARCHAR(100);
  v_intresultoutput Int;
BEGIN
  IF (v_mode = 1) THEN
  -- BEGIN TRAN (removed)
  v_frommail := '';
  SELECT emailid INTO v_frommail FROM tbl_emailmembermaster WHERE temid = v_fromemail;
  IF (v_issendemail = 1) THEN
  IF (v_mailtype = 1) THEN
  v_intresult := 1;
  INSERT INTO tbl_sendmailhistory (plid, fromemail, toemail, senddate, subject, body, isactive, isdeleted, attachment, mailtype) VALUES (v_plid, v_frommail, v_toemail, dbo.FUN_GETCURRENTDATE(), v_msgsubject, v_message, 1, 0, v_attachment, v_mailtype);
  INSERT INTO tbl_emailcampaignmaster (emailfromtemid, plid, emailto, subject, message, attachment, campaignname, campaigndate, campaigntime, createddate, ismailsent, isactive, status, isdeleted) VALUES (v_fromemail, v_plid, v_toemail, v_msgsubject, v_message, v_attachment, v_campaignname, v_campaigndate, v_campaigntime, dbo.FUN_GETCURRENTDATE(), 1, 1, 1, 0);
  ELSE
  IF (v_mailtype = 2) THEN
  v_intresult := 1;
  INSERT INTO tbl_sendmailhistory (plid, fromemail, toemail, senddate, subject, body, isactive, isdeleted, attachment, mailtype) VALUES (v_plid, v_frommail, v_toemail, dbo.FUN_GETCURRENTDATE(), v_msgsubject, v_message, 1, 0, v_attachment, v_mailtype);
  END IF;
  END IF;
  v_intresultoutput := 0;
  SELECT v_intresultoutput INTO v_intresultoutput FROM dbo.usp_emailsmstrafficboosteraccountmanagement(v_mode => 1, v_plid => v_plid, v_tosmsoremail => v_toemail, v_intresultoutput => v_intresultoutput);
  IF (v_intresultoutput = 0) THEN
  v_intresult := 0;
  -- ROLLBACK (removed)
  RETURN;
  END IF;
  v_intresult := 2;
  ELSE
  IF (v_issendemail = 0) THEN
  INSERT INTO tbl_emailcampaignmaster (emailfromtemid, plid, emailto, subject, message, attachment, campaignname, campaigndate, campaigntime, createddate, ismailsent, isactive, status, isdeleted) VALUES (v_fromemail, v_plid, v_toemail, v_msgsubject, v_message, v_attachment, v_campaignname, v_campaigndate, v_campaigntime, dbo.FUN_GETCURRENTDATE(), 0, 1, 1, 0);
  END IF;
  END IF;
  IF (0 <> 0) THEN
  v_intresult := 0;
  -- ROLLBACK (removed)
  RETURN;
  END IF;
  v_intresult := 1;
  -- COMMIT (removed)
  END IF;
  IF (v_mode = 2) THEN
  IF EXISTS(SELECT 1 FROM tbl_emailcampaignmaster WHERE ismailsent = 1 AND tecmid = v_tecmid) THEN
  v_intresult := 4;
  ELSE
  UPDATE tbl_emailcampaignmaster SET emailfromtemid = v_fromemail, emailto = v_toemail, subject = v_msgsubject, message = v_message, attachment = (CASE WHEN v_attachment = '' THEN attachment ELSE v_attachment END), campaignname = v_campaignname, campaigndate = v_campaigndate, campaigntime = v_campaigntime, ismailsent = (CASE WHEN v_issendemail = 3 THEN 0 ELSE v_issendemail END) WHERE tecmid = v_tecmid;
  v_intresult := 3;
  END IF;
  END IF;
END;
$$;


--
-- Name: usp_emailpackmaster(integer, character varying, text, integer, numeric, numeric, numeric, bigint, bigint, integer, integer, numeric); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_emailpackmaster(v_mode integer DEFAULT 1, v_packagename character varying DEFAULT ''::character varying, v_packagefeaturedescription text DEFAULT ''::text, v_isactive integer DEFAULT 0, v_amount numeric DEFAULT 0.00, v_totalamount numeric DEFAULT 0.00, v_st numeric DEFAULT 0.00, v_noofemail bigint DEFAULT 0, v_noofdaysvalidity bigint DEFAULT 0, v_intresult integer DEFAULT 0, v_tepmid integer DEFAULT 0, v_bvpercentage numeric DEFAULT 0.00) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF (v_mode = 1) THEN
  RETURN QUERY SELECT ROW_NUMBER() OVER (ORDER BY tepmid NULLS FIRST) AS rownumber, tepmid, packagename, packagefeaturedescription, (CASE WHEN isactive = 1 THEN 'Active' ELSE 'Deactive' END) AS isactive, amount, totalamount, st, noofemail, noofdaysvalidity, bvpercentage FROM tbl_emailpackmaster;
  v_intresult := 1;
  END IF;
  IF (v_mode = 2) THEN
  INSERT INTO tbl_emailpackmaster (packagename, packagefeaturedescription, isactive, amount, totalamount, st, noofemail, noofdaysvalidity, bvpercentage) VALUES (v_packagename, v_packagefeaturedescription, v_isactive, v_amount, v_totalamount, v_st, v_noofemail, v_noofdaysvalidity, v_bvpercentage);
  v_intresult := 2;
  END IF;
  IF (v_mode = 3) THEN
  UPDATE tbl_emailpackmaster SET packagename = v_packagename, packagefeaturedescription = v_packagefeaturedescription, isactive = v_isactive, amount = v_amount, totalamount = v_totalamount, st = v_st, noofemail = v_noofemail, noofdaysvalidity = v_noofdaysvalidity, bvpercentage = v_bvpercentage WHERE tepmid = v_tepmid;
  v_intresult := 3;
  END IF;
  IF (0 <> 0) THEN
  v_intresult := 0;
  RETURN;
  END IF;
END;
$$;


