--

CREATE FUNCTION dbo.usp_fillarea(v_aid text) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_recordcount int;
  v_regno bigint;
  v_index1 INT;
  v_slice2 text;
  v_areaname varchar(100);
  v_slice1 text;
  v_index3 INT;
  v_index4 INT;
  v_slice3 text;
  v_slice4 text;
  v_index2 INT;
BEGIN
  -- SET option (removed)
  DROP TABLE IF EXISTS tmp_temp111;
  CREATE TEMP TABLE tmp_temp111 (areaname varchar(100)) ON COMMIT DROP;
  v_slice1 := v_aid;
  v_index3 := 1;
  WHILE v_index3 <> 0 LOOP
  SELECT POSITION(',' IN v_slice1) INTO v_index3;
  IF v_index3 <> 0 THEN
  SELECT LEFT(CAST(v_slice1 AS TEXT), v_index3 - 1) INTO v_slice2;
  ELSE
  v_slice2 := v_slice1;
  END IF;
  SELECT areaname INTO v_areaname FROM area_master WHERE aid = v_slice2;
  INSERT INTO tmp_temp111 (areaname) VALUES (v_areaname);
  SELECT RIGHT(CAST(v_slice1 AS TEXT), LENGTH(CAST(v_slice1 AS TEXT)) - v_index3) INTO v_slice1;
  IF LENGTH(CAST(v_slice1 AS TEXT)) = 0 THEN
  EXIT;
  END IF;
  END LOOP;
  RETURN QUERY SELECT areaname FROM tmp_temp111;
  DROP TABLE IF EXISTS tmp_temp111;
  -- SET option (removed)
END;
$$;


