    LANGUAGE plpgsql
    AS $$
BEGIN
  v_intresult := 0;
  IF (v_mode = 'category') THEN
  SELECT catid, catname INTO v_catid, v_outcatname FROM product_category WHERE RTRIM(LTRIM(catname)) = v_sendvalue;
  v_intresult := 1;
  END IF;
  IF (v_mode = 'keyword') THEN
  SELECT kmid, keywordname INTO v_kmid, v_outkeywordname FROM keyword_master WHERE RTRIM(LTRIM(keywordname)) = v_sendvalue;
  v_intresult := 1;
  END IF;
END;
$$;


