END;
$$;


--
-- Name: usp_generatecanonicalforblog(bigint, text, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_generatecanonicalforblog(v_blogid bigint, v_newcan text DEFAULT ''::text, INOUT v_strresult integer DEFAULT NULL::integer) RETURNS integer
    LANGUAGE plpgsql
    AS $$
BEGIN
  UPDATE tbl_blogmaster SET canonicalurl = (CASE WHEN canonicalurl = '' THEN v_newcan ELSE canonicalurl END) WHERE blogid = v_blogid;
  v_strresult := 1;
END;
$$;


--
-- Name: usp_generateloginid(character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_generateloginid(INOUT v_loginid character varying) RETURNS character varying
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_upper bigint;
  v_lower bigint;
  v_count int;
  v_random bigint;
BEGIN
  v_lower := 11111111;
  v_upper := 99999999;
  SELECT ROUND(((v_upper - v_lower - 1) * RANDOM() + v_lower), 0) INTO v_random;
  v_loginid := CAST(v_random AS VARCHAR);
  SELECT COUNT(*) INTO v_count FROM visitor_login WHERE loginid = v_loginid;
  WHILE (v_count > 0) LOOP
  SELECT ROUND(((v_upper - v_lower - 1) * RANDOM() + v_lower), 0) INTO v_random;
  v_loginid := CAST(v_random AS VARCHAR);
  RETURN;
  END LOOP;
END;
$$;


--
-- Name: usp_generatememberloginid(character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

