  v_loginid := CAST(v_random AS VARCHAR);
  SELECT COUNT(*) INTO v_count FROM member_master WHERE loginid = v_loginid;
  WHILE (v_count > 0) LOOP
  SELECT ROUND(((v_upper - v_lower - 1) * RANDOM() + v_lower), 0) INTO v_random;
  v_loginid := CAST(v_random AS VARCHAR);
  RETURN;
  END LOOP;
END;
$$;


--
-- Name: usp_generatemerchant_invoices(integer, character varying, character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_generatemerchant_invoices(v_plid integer DEFAULT 1, v_orderid character varying DEFAULT ''::character varying, INOUT v_stroutput character varying DEFAULT ''::character varying) RETURNS character varying
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_tmciid INT;
  v_orderno VARCHAR(100);
  v_taxableamount DECIMAL(18,2);
  v_admincharges DECIMAL(18,2);
  v_handlingcharges DECIMAL(18,2);
  v_fixedcharges DECIMAL(18,2);
  v_shippingcharges DECIMAL(18,2);
  v_commcgstrate DECIMAL(18,2);
  v_commcgstamount DECIMAL(18,2);
  v_commsgstrate DECIMAL(18,2);
  v_commsgstamount DECIMAL(18,2);
  v_commigstrate DECIMAL(18,2);
  v_commigstamount DECIMAL(18,2);
  v_shipcgstrate DECIMAL(18,2);
  v_shipcgstamount DECIMAL(18,2);
  v_shipsgstrate DECIMAL(18,2);
  v_shipsgstamount DECIMAL(18,2);
  v_shipigstrate DECIMAL(18,2);
  v_shipigstamount DECIMAL(18,2);
  v_totalcommamount DECIMAL(18,2);
  v_totalshipamount DECIMAL(18,2);
  v_currentyear VARCHAR(10);
  v_nextyear VARCHAR(10);
  v_sprid BIGINT;
  v_companygstno VARCHAR(20);
  v_merchantgstno VARCHAR(20);
  v_docketno VARCHAR(100);
  v_customershippingcharges DECIMAL(18,2);
  v_commissioninvoiceno VARCHAR(100);
  v_lastcommissioninvoiceno INT;
  v_shippinginvoiceno VARCHAR(100);
  v_lastshippinginvoiceno INT;
  v_loopcount INT;
  v_totalrecords INT;
  v_comminvoicelastdigit INT;
  v_commtmciid INT;
  v_shipinvoicelastdigit INT;
  v_shiptmsiid INT;
BEGIN
  -- BEGIN TRAN (removed)
  -- SET option (removed)
  IF (v_plid <> 0 AND v_orderid <> '') THEN
  v_tmciid := 0;
  v_orderno := '';
  v_taxableamount := 0;
  v_handlingcharges := 0;
  v_fixedcharges := 0;
  v_shippingcharges := 0;
  v_commcgstrate := 0;
  v_commcgstamount := 0;
  v_commsgstrate := 0;
  v_commsgstamount := 0;
  v_commigstrate := 0;
  v_commigstamount := 0;
  v_shipcgstrate := 0;
  v_shipcgstamount := 0;
  v_shipsgstrate := 0;
  v_shipsgstamount := 0;
  v_shipigstrate := 0;
  v_shipigstamount := 0;
  v_totalcommamount := 0;
  v_totalshipamount := 0;
  v_currentyear := '';
  v_nextyear := '';
  v_sprid := 0;
  v_companygstno := '';
  v_merchantgstno := '';
  v_docketno := '';
  v_customershippingcharges := 0;
  DROP TABLE IF EXISTS tmp_processorders;
  CREATE TEMP TABLE tmp_processorders (ROWNUMBER INT GENERATED BY DEFAULT AS IDENTITY NOT NULL,  
  ORDERNO VARCHAR(100)) ON COMMIT DROP;
  INSERT INTO tmp_processorders SELECT tpom.orderno FROM dbo.tbl_product_order_master AS tpom WHERE tpom.orderid = v_orderid AND tpom.plid = v_plid AND tpom.intstatus = 6 AND NOT tpom.orderno IN (SELECT tmcid.orderno FROM dbo.tbl_merchant_commissioninvoices_details AS tmcid WHERE tmcid.orderid = v_orderid AND tmcid.plid = v_plid);
  SELECT COALESCE(gstno, '') INTO v_companygstno FROM tbl_company;
  IF (v_companygstno = 0) THEN
  v_companygstno := '07';
  END IF;
  SELECT COALESCE(gstno, '') INTO v_merchantgstno FROM portal_master WHERE plid = v_plid;
  IF (v_merchantgstno <> '' AND v_companygstno <> '' AND (LEFT(CAST(v_merchantgstno AS TEXT), 2) = LEFT(CAST(v_companygstno AS TEXT), 2))) THEN
  v_commcgstrate := 9;
  v_commsgstrate := 9;
  v_commigstrate := 0;
  v_shipcgstrate := 9;
  v_shipsgstrate := 9;
  v_shipigstrate := 0;
  ELSE
  v_commcgstrate := 0;
  v_commsgstrate := 0;
  v_commigstrate := 18;
  v_shipcgstrate := 0;
  v_shipsgstrate := 0;
  v_shipigstrate := 18;
  END IF;
  v_commissioninvoiceno := '';
  v_lastcommissioninvoiceno := 0;
  SELECT EXTRACT(YEAR FROM CAST(dbo.FUN_GETCURRENTDATE() AS DATE)) INTO v_currentyear;
  SELECT EXTRACT(YEAR FROM CAST(dbo.FUN_GETCURRENTDATE() AS DATE)) + 1 INTO v_nextyear;
  SELECT COALESCE(MAX(invoicelastdigit), 0) INTO v_lastcommissioninvoiceno FROM dbo.tbl_merchant_commissioninvoices;
  v_commissioninvoiceno := NUMBER_TO_STR(v_lastcommissioninvoiceno + 1, 'COCOMM/' || RIGHT(CAST(v_currentyear AS TEXT), 2) || '-' || RIGHT(CAST(v_nextyear AS TEXT), 2) || '/' || '000000');
  v_shippinginvoiceno := '';
  v_lastshippinginvoiceno := 0;
  SELECT COALESCE(MAX(invoicelastdigit), 0) INTO v_lastshippinginvoiceno FROM dbo.tbl_merchant_shippinginvoices;
  v_shippinginvoiceno := NUMBER_TO_STR(v_lastshippinginvoiceno + 1, 'COSHIP/' || RIGHT(CAST(v_currentyear AS TEXT), 2) || '-' || RIGHT(CAST(v_nextyear AS TEXT), 2) || '/' || '000000');
  v_loopcount := 1;
  v_totalrecords := 0;
  SELECT COUNT(1) INTO v_totalrecords FROM tmp_processorders;
  WHILE (v_loopcount <= v_totalrecords) LOOP
  SELECT COALESCE(orderno, '') INTO v_orderno FROM tmp_processorders WHERE rownumber = v_loopcount;
  SELECT COALESCE(subprcode, ''), COALESCE(docketno, '') INTO v_sprid, v_docketno FROM dbo.tbl_product_order_master WHERE orderno = v_orderno;
  SELECT COALESCE(total_purchase_cost, 0) INTO v_taxableamount FROM dbo.tbl_product_order_master WHERE orderno = v_orderno;
  SELECT COALESCE(v_taxableamount * v_commcgstrate / 100, 0), COALESCE(v_taxableamount * v_commsgstrate / 100, 0), COALESCE(v_taxableamount * v_commigstrate / 100, 0) INTO v_commcgstamount, v_commsgstamount, v_commigstamount;
  SELECT COALESCE(admincharge, 0), COALESCE(handlingcharge, 0), COALESCE(fixedfee, 0) INTO v_admincharges, v_handlingcharges, v_fixedcharges FROM dbo.ims_subproduct WHERE sprid = v_sprid;
  SELECT COALESCE(total_ship_ch, 0) INTO v_customershippingcharges FROM dbo.tbl_product_order_master WHERE subprcode = v_sprid AND orderid = v_orderid;
  SELECT COALESCE(pickup_charges + deliverycharhes + taxcharges + fueltax, 0) INTO v_shippingcharges FROM tbl_courierweeklyreports WHERE docketno = v_docketno;
  IF (v_shippingcharges > 0) THEN
  SELECT COALESCE(v_shippingcharges * v_shipcgstrate / 100, 0), COALESCE(v_shippingcharges * v_shipsgstrate / 100, 0), COALESCE(v_shippingcharges * v_shipigstrate / 100, 0) INTO v_shipcgstamount, v_shipsgstamount, v_shipigstamount;
  END IF;
  v_comminvoicelastdigit := 0;
  v_commtmciid := 0;
  SELECT COALESCE(MAX(invoicelastdigit), 0) INTO v_comminvoicelastdigit FROM dbo.tbl_merchant_commissioninvoices;
  IF (v_loopcount = 1) THEN
  INSERT INTO dbo.tbl_merchant_commissioninvoices (plid, orderid, orderno, invoiceno, invoicelastdigit, invoicedate, createddate) VALUES (v_plid, v_orderid, '', v_commissioninvoiceno, v_comminvoicelastdigit + 1, dbo.FUN_GETCURRENTDATE(), dbo.FUN_GETCURRENTDATE());
  SELECT IDENT_CURRENT('[DBO].[TBL_MERCHANT_COMMISSIONINVOICES]') INTO v_commtmciid;
  ELSE
  SELECT COALESCE(MAX(tmciid), 0) INTO v_commtmciid FROM dbo.tbl_merchant_commissioninvoices;
  END IF;
  INSERT INTO dbo.tbl_merchant_commissioninvoices_details (plid, tmciid, orderid, orderno, taxableamount, admincharges, handlingcharges, fixedcharges, cgstrate, cgstamount, sgstrate, sgstamount, igstrate, igstamount, totalamount, createddate) VALUES (v_plid, v_commtmciid, v_orderid, v_orderno, v_taxableamount, v_admincharges, v_handlingcharges, v_fixedcharges, v_commcgstrate, v_commcgstamount, v_commsgstrate, v_commsgstamount, v_commigstrate, v_commigstamount, v_totalcommamount, dbo.FUN_GETCURRENTDATE());
  v_shipinvoicelastdigit := 0;
  v_shiptmsiid := 0;
  SELECT COALESCE(MAX(invoicelastdigit), 0) INTO v_shipinvoicelastdigit FROM dbo.tbl_merchant_shippinginvoices;
  IF (v_loopcount = 1) THEN
  INSERT INTO dbo.tbl_merchant_shippinginvoices (plid, orderid, orderno, invoiceno, invoicelastdigit, invoicedate, createddate) VALUES (v_plid, v_orderid, '', v_shippinginvoiceno, v_shipinvoicelastdigit + 1, dbo.FUN_GETCURRENTDATE(), dbo.FUN_GETCURRENTDATE());
  SELECT IDENT_CURRENT('[DBO].[TBL_MERCHANT_SHIPPINGINVOICES]') INTO v_shiptmsiid;
  ELSE
  SELECT COALESCE(MAX(tmsiid), 0) INTO v_shiptmsiid FROM dbo.tbl_merchant_shippinginvoices;
  END IF;
  INSERT INTO dbo.tbl_merchant_shippinginvoices_details (plid, tmsiid, orderid, orderno, taxableamount, shippingcharges, cgstrate, cgstamount, sgstrate, sgstamount, igstrate, igstamount, totalamount, createddate) VALUES (v_plid, v_shiptmsiid, v_orderid, v_orderno, v_taxableamount, v_shippingcharges, v_shipcgstrate, v_shipcgstamount, v_shipsgstrate, v_shipsgstamount, v_shipigstrate, v_shipigstamount, v_totalshipamount, dbo.FUN_GETCURRENTDATE());
  v_loopcount := v_loopcount + 1;
  END LOOP;
  v_stroutput := 'SUCCESS';
  DROP TABLE IF EXISTS tmp_processorders;
  ELSE
  v_stroutput := 'Invalid Attempts';
  -- COMMIT (removed)
  RETURN;
  END IF;
  -- SET option (removed)
  -- COMMIT (removed)
END;
$$;


--
-- Name: usp_generatereferal(integer, character varying, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_generatereferal(v_plid integer DEFAULT 0, v_referallink character varying DEFAULT NULL::character varying, INOUT v_intresult integer DEFAULT NULL::integer) RETURNS integer
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF NOT EXISTS(SELECT refral_id FROM portal_login WHERE refral_id = v_referallink) THEN
  v_intresult := 1;
  UPDATE portal_login SET refral_id = v_referallink WHERE plid = v_plid;
  ELSE
  v_intresult := 0;
  RETURN;
  END IF;
  IF (0 <> 0) THEN
  v_intresult := 0;
  -- ROLLBACK (removed)
  RETURN;
  END IF;
END;
$$;


--
-- Name: usp_genereate_merchant_payouts(character varying, character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_genereate_merchant_payouts(v_payoutdate character varying DEFAULT '2022-06-09'::character varying, INOUT v_stroutput character varying DEFAULT ''::character varying) RETURNS character varying
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_dayname VARCHAR(50);
  v_prevpayid INT;
  v_payid INT;
  v_totalpayamount DECIMAL(18,2);
  v_totaltds DECIMAL(18,2);
  v_totaladmincharge DECIMAL(18,2);
BEGIN
  BEGIN
  -- BEGIN TRAN (removed)
  -- SET option (removed)
  -- SET option (removed)
  IF (v_payoutdate <> '') THEN
  v_dayname := '';
  SELECT TO_CHAR(CAST(CAST(v_payoutdate AS DATE) AS TIMESTAMP), 'TMDay') INTO v_dayname;
  IF (UPPER(v_dayname) = 'MONDAY') THEN
  DROP TABLE IF EXISTS tmp_payoutdata;
  CREATE TEMP TABLE tmp_payoutdata (ROWNUMBER INT GENERATED BY DEFAULT AS IDENTITY NOT NULL,  
    PLID BIGINT,  
    PAYABLEAMOUNT DECIMAL(18,2),  
    ACID INT,  
    ADMINCHARGE DECIMAL(18,2),  
    TDS_PER DECIMAL(18,2),  
    TDS DECIMAL(18,2),  
    SETTLEMENTDATE timestamp) ON COMMIT DROP;
  INSERT INTO tmp_payoutdata SELECT DISTINCT settlements.plid, SUM(settlements.balance), COALESCE(bank.acid, 0), 0, 0, 0, settlements.createdate FROM dbo.tbl_merchant_wallet_statements AS settlements LEFT JOIN dbo.bank_accounts_merchant AS bank ON settlements.plid = bank.plid WHERE settlements.status = 1 AND UPPER(settlements.crdrtype) = 'CR' AND bank.isaprove = 1 GROUP BY settlements.plid, bank.acid, settlements.createdate;
  UPDATE tmp_payoutdata SET tds_per = (SELECT limits FROM dbo.settings WHERE caption = 'GST Percentage');
  UPDATE tmp_payoutdata SET admincharge = (SELECT SUM(commissions) FROM dbo.tbl_merchant_settlement_commissions AS comm WHERE comm.plid = tmp_payoutdata.plid);
  UPDATE tmp_payoutdata SET tds = (SELECT SUM(taxdeductions) FROM dbo.tbl_merchant_settlement_commissions AS comm WHERE comm.plid = tmp_payoutdata.plid);
  IF EXISTS(SELECT 1 FROM tmp_payoutdata) THEN
  v_prevpayid := 0;
  v_payid := 0;
  v_totalpayamount := 0;
  v_totaltds := 0;
  v_totaladmincharge := 0;
  IF EXISTS(SELECT 1 FROM tbl_merchant_payout) THEN
  SELECT MAX(payid) INTO v_prevpayid FROM tbl_merchant_payout;
  v_payid := v_prevpayid + 1;
  ELSE
  v_payid := 1;
  END IF;
  SELECT SUM(tmp_payoutdata.payableamount), SUM(tmp_payoutdata.tds), SUM(tmp_payoutdata.admincharge) INTO v_totalpayamount, v_totaltds, v_totaladmincharge FROM tmp_payoutdata;
  INSERT INTO dbo.tbl_merchant_payout (payid, paydate, payfrom, payto, payoutamount, tds, admincharge, acitve) VALUES (v_payid, dbo.FUN_GETCURRENTDATE(), '', '', v_totalpayamount, v_totaltds, v_totaladmincharge, 1);
  INSERT INTO dbo.tbl_merchant_withdrawals (payid, plid, type, crdrtype, withdrawamount, admincharge, tds, paybleamount, date, status, remarks, tds_per, admicharge_per, acid, createddate) SELECT v_payid, tmp_payoutdata.plid, '', 'DR', tmp_payoutdata.payableamount, tmp_payoutdata.admincharge, tmp_payoutdata.tds, tmp_payoutdata.payableamount, NULL, '0', '', tmp_payoutdata.tds_per, 0, tmp_payoutdata.acid, dbo.FUN_GETCURRENTDATE() FROM tmp_payoutdata;
  INSERT INTO tbl_merchant_wallet_statements (particular, crdrtype, amount, balance, active, createdate, plid) SELECT 'DEBIT WALLET WITH AMOUNT ' || CAST(payableamount AS VARCHAR(50)) || ' AGAINST PAYOUT ON ' || CAST(v_payoutdate AS VARCHAR(50)) || '', 'DR', tmp_payoutdata.payableamount, 0, 1, dbo.FUN_GETCURRENTDATE(), tmp_payoutdata.plid FROM tmp_payoutdata;
  UPDATE tbl_merchant_wallet_statements SET status = 0 WHERE tbl_merchant_wallet_statements.createdate IN (SELECT settlementdate FROM tmp_payoutdata WHERE status = 1);
  END IF;
  END IF;
  -- COMMIT (removed)
  v_stroutput := 'SUCCESS';
  END IF;
  EXCEPTION WHEN OTHERS THEN
  IF (0 > 0) THEN
  PERFORM dbo.sp_errorlog();
  -- ROLLBACK (removed)
  END IF;
  END;
END;
$$;


--
-- Name: usp_get_adsewalletamt(integer, integer, character varying, boolean, text, character varying, character varying, integer, character varying, character varying, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_get_adsewalletamt(v_startrowindex integer DEFAULT 1, v_maxrows integer DEFAULT 10, v_orderbyfield character varying DEFAULT NULL::character varying, v_asc boolean DEFAULT NULL::boolean, v_loginids text DEFAULT ''::text, v_fromdate character varying DEFAULT NULL::character varying, v_todate character varying DEFAULT NULL::character varying, v_mode integer DEFAULT 0, v_crdrtype character varying DEFAULT ''::character varying, v_wallettype character varying DEFAULT 'PPC'::character varying, v_recordcount integer DEFAULT NULL::integer) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_sqlquery text;
  v_minrow BIGINT;
  v_maxrow BIGINT;
BEGIN
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp (ROWNUMBER BIGINT,
		LOGINID varchar(100),
		CURRENCYSYMBOL VARCHAR(50),
		SFDID BIGINT,
		PLID BIGINT,
		DEPOSITAMOUNT numeric(19,4),
		DEPOSITDATE DATE,
		REMARK text,
		CRDRTYPE VARCHAR(10),
		WALLETTYPE VARCHAR(25)) ON COMMIT DROP;
  v_sqlquery := '';
  IF (v_wallettype = 'PPC') THEN
  v_sqlquery := 'INSERT INTO #TEMP SELECT ROW_NUMBER() OVER(ORDER BY SFD.DEPOSITDATE DESC) AS ROWNUMBER,PL.LOGINID,PL.CURRENCYSYMBOL,SFD.SFDID,SFD.PLID,
			ISNULL(SFD.DEPOSITAMOUNT,0.00) AS DEPOSITAMOUNT,ISNULL(CONVERT(DATE,SFD.DEPOSITDATE,105),'''') AS DEPOSITDATE, ISNULL(SFD.REMARK,'''') AS REMARK ,SFD.CRDRTYPE,''PPC Wallet''
			FROM TBL_SPONSERFUNDDETAILS SFD INNER JOIN PORTAL_LOGIN PL ON PL.PLID=SFD.PLID INNER JOIN TBL_ADSEWALLET TAW ON TAW.PLID=PL.PLID WHERE PL.ACTIVE=1 AND SFD.REQFROM=''Admin''';
  END IF;
  IF (v_wallettype = 'SUBS_WALLET') THEN
  v_sqlquery := 'INSERT INTO #TEMP SELECT ROW_NUMBER() OVER(ORDER BY SFD.DATE DESC) AS ROWNUMBER,PL.LOGINID,PL.CURRENCYSYMBOL,SFD.SWHID,SFD.PLID,
	ISNULL(SFD.AMOUNT,0.00) AS DEPOSITAMOUNT,ISNULL(CONVERT(DATE,SFD.DATE,105),'''') AS DEPOSITDATE, ISNULL(SFD.REMARK,'''') AS REMARK ,SFD.CRDRTYPE,''Subscription Wallet'' AS WALLETTYPE
	FROM TBL_SUBSCRIPTION_WALLET_HISTORY SFD INNER JOIN PORTAL_LOGIN PL ON PL.PLID=SFD.PLID  WHERE PL.ACTIVE=1 ';
  END IF;
  IF (v_crdrtype <> '') THEN
  v_sqlquery := v_sqlquery || ' AND SFD.CRDRTYPE = ''' || v_crdrtype || '''';
  END IF;
  IF ((v_fromdate <> '') AND (v_todate = '')) THEN
  v_sqlquery := v_sqlquery || ' AND CONVERT(DATE, SFD.DEPOSITDATE, 105) BETWEEN  CONVERT(DATE, ''' || v_fromdate || ''', 105) AND  CONVERT(DATE, DBO.FUN_GETCURRENTDATE(), 105)';
  END IF;
  IF ((v_fromdate = '') AND (v_todate <> '')) THEN
  v_sqlquery := v_sqlquery || 'AND CONVERT(DATE, SFD.DEPOSITDATE, 105) BETWEEN  CONVERT(DATE, ''' || v_todate || ''', 105) AND  CONVERT(DATE, DBO.FUN_GETCURRENTDATE(), 105)';
  END IF;
  IF ((v_fromdate <> '') AND (v_todate <> '')) THEN
  v_sqlquery := v_sqlquery || 'AND CONVERT(DATE, SFD.DEPOSITDATE, 105) BETWEEN  CONVERT(DATE, ''' || v_fromdate || ''', 105) AND  CONVERT(DATE, ''' || v_todate || ''', 105)';
  END IF;
  IF (v_loginids <> '') THEN
  v_sqlquery := v_sqlquery || ' AND PL.LOGINID LIKE ''%' || v_loginids || '%''';
  END IF;
  IF (v_wallettype = 'SUBS_WALLET') THEN
  v_sqlquery := v_sqlquery || ' ORDER BY SFD.DATE DESC';
  ELSE
  v_sqlquery := v_sqlquery || ' ORDER BY SFD.DEPOSITDATE DESC';
  END IF;
  EXECUTE v_sqlquery;
  RETURN QUERY SELECT * FROM tmp_temp WHERE rownumber BETWEEN v_startrowindex AND v_maxrows;
  SELECT COUNT(*) INTO v_recordcount FROM tmp_temp;
END;
$$;


--
-- Name: usp_get_all_bv_report(integer, integer, character varying, character varying, character varying, character varying, integer, integer, integer, integer, character varying, numeric); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_get_all_bv_report(v_startrowindex integer DEFAULT 1, v_maxrows integer DEFAULT 1000, v_fromdate character varying DEFAULT ''::character varying, v_todate character varying DEFAULT ''::character varying, v_searchfield character varying DEFAULT ''::character varying, v_searchvalue character varying DEFAULT ''::character varying, v_did integer DEFAULT 2, v_orderstatus integer DEFAULT 0, v_totalcount integer DEFAULT 0, v_totalmember integer DEFAULT 0, v_dateranage character varying DEFAULT ''::character varying, v_totalbv numeric DEFAULT 0) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_minindex INT;
  v_maxindex INT;
  v_query text;
  v_condition text;
  v_countquery text;
  v_trpid INT;
  v_mindate VARCHAR(100);
  v_maxdate VARCHAR(100);
BEGIN
  -- BEGIN TRAN (removed)
  -- SET option (removed)
  v_condition := '';
  v_countquery := '';
  v_trpid := 0;
  v_mindate := '';
  v_maxdate := '';
  v_minindex := (v_startrowindex - 1) * v_maxrows + 1;
  v_maxindex := v_startrowindex * v_maxrows;
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp (ROWNUMBER INT GENERATED BY DEFAULT AS IDENTITY,
 CUSTOMERNAME VARCHAR(100),
 MOBILENO VARCHAR(100),
 DATE VARCHAR(100),
 BVPERCNTAGE DECIMAL(18,2),
 BV DECIMAL(18,2),
 ORDERID VARCHAR(100),
 ORDERNO VARCHAR(100),
 ORDERSTATUS INT,
 ORDERDERCYCLESTATUS VARCHAR(100),
 BENIFICARYID VARCHAR(100),
 TYPE VARCHAR(100)) ON COMMIT DROP;
  v_query := ' INSERT INTO #TEMP SELECT (CL.FNAME+'' ''+CL.LNAME) AS NAME,CL.PHONE,CONVERT(VARCHAR,TRBVM.CREATE_DATE,106) AS DATE, 
ISNULL(TRBVD.BVPERCENTAGE,0),ISNULL(TRBVD.BVALUE,0) ,ISNULL(TRBVM.ORDERID,''N/A''),ISNULL(TRBVD.ORDERNO,''N/A''),
ISNULL(POM.INTSTATUS,0),(CASE WHEN POM.INTSTATUS in (0,2,3,4,5) THEN ''Pending'' WHEN POM.INTSTATUS=6 THEN ''Completed'' WHEN POM.INTSTATUS=7 THEN ''Cancelled''
 WHEN POM.INTSTATUS=9 THEN ''Out for Delivery'' END),
ISNULL(TRUN.USERNAME,''N/A''),ISNULL(TRS.SERVICENAME,''N/A'')
FROM TBL_RESELLER_BV_PV_MASTER TRBVM  
LEFT JOIN TBL_RESELLER_BV_PV_DETAILS TRBVD ON TRBVM.COMID=TRBVD.COMID
LEFT JOIN TBL_PRODUCT_ORDER_MASTER POM ON  TRBVD.ORDERNO=POM.ORDERNO
LEFT JOIN TBL_CUSTOMERLOGIN CL ON POM.LOGINID=CL.LOGINID
LEFT JOIN TBL_RESELLER_SERVICES TRS ON TRBVD.TYPE=TRS.TRSID
LEFT JOIN TBL_REFERENCEUSERNAME TRUN ON CL.CLID=TRUN.CLID AND TRUN.STATUS=1
WHERE TRBVM.DID=''' || CAST(v_did AS VARCHAR(30)) || ''' and  TRBVD.RELEASEDSTATUS=0 ';
  IF ((v_fromdate <> '') AND (v_todate = '')) THEN
  v_query := v_query || ' AND CONVERT(DATE, TRBVM.CREATE_DATE) =  CONVERT(DATE, ''' || v_fromdate || ''')';
  END IF;
  IF ((v_fromdate = '') AND (v_todate <> '')) THEN
  v_query := v_query || ' AND CONVERT(DATE, TRBVM.CREATE_DATE) =  CONVERT(DATE, ''' || v_todate || ''') ';
  END IF;
  IF ((v_fromdate <> '') AND (v_todate <> '')) THEN
  v_query := v_query || ' AND CONVERT(DATE, TRBVM.CREATE_DATE) BETWEEN CONVERT(DATE, ''' || v_fromdate || ''') AND  CONVERT(DATE, ''' || v_todate || ''') ';
  END IF;
  IF (v_searchfield <> '' AND v_searchvalue <> '') THEN
  IF (v_searchfield = 'FULLNAME') THEN
  v_query := v_query || ' AND (CL.FANME+''''+CL.LNAME)=' || CAST(v_searchvalue AS VARCHAR(30)) || '';
  END IF;
  IF (v_searchfield = 'PHONE') THEN
  v_query := v_query || ' AND CL.PHONE=''' || CAST(v_searchvalue AS VARCHAR(30)) || '''';
  END IF;
  IF (v_searchfield = 'BENEFICIARYID') THEN
  v_query := v_query || ' AND TRUN.USERNAME=''' || CAST(v_searchvalue AS VARCHAR(30)) || '''';
  END IF;
  IF (v_searchfield = 'ORDERID') THEN
  v_query := v_query || ' AND TRBVM.ORDERID=''' || CAST(v_searchvalue AS VARCHAR(30)) || '''';
  END IF;
  END IF;
  IF (v_orderstatus <> '') THEN
  v_query := v_query || ' AND POM.INTSTATUS=''' || CAST(v_orderstatus AS VARCHAR(30)) || '''';
  END IF;
  EXECUTE v_query;
  RAISE NOTICE '%', v_query;
  RETURN QUERY SELECT * FROM tmp_temp WHERE rownumber BETWEEN v_minindex AND v_maxindex;
  SELECT COUNT(rownumber), COUNT(DISTINCT benificaryid), COALESCE(SUM(bv), 0), MIN(date), MAX(date) INTO v_totalcount, v_totalmember, v_totalbv, v_mindate, v_maxdate FROM tmp_temp;
  SELECT v_mindate || ' To ' || v_maxdate INTO v_dateranage;
  DROP TABLE IF EXISTS tmp_temp;
  -- COMMIT (removed)
END;
$$;


--
-- Name: usp_get_all_category_with_image_mobile(); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_get_all_category_with_image_mobile() RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_query varchar(5000);
  v_dynamicurl varchar(100);
  v_query12 varchar(5000);
  v_query13 varchar(5000);
  v_count int;
  v_maincatid int;
  v_productimage varchar(500);
BEGIN
  v_query := '';
  v_dynamicurl := '';
  SELECT merchantimagepath INTO v_dynamicurl FROM tbl_company;
  v_query12 := '';
  v_query13 := '';
  DROP TABLE IF EXISTS tmp_temp1;
  CREATE TEMP TABLE tmp_temp1 (rowNumber bigint,Maincatid int,MainCatName varchar(100)) ON COMMIT DROP;
  v_query12 := 'insert into #temp1 select  ROW_NUMBER() over (order by Maincatid asc) as rowNumber,Maincatid,MainCatName from tbl_main_category  where status=1 and totalactive>0 ';
  EXECUTE v_query12;
  v_count := 0;
  v_maincatid := 0;
  v_productimage := '';
  SELECT COUNT(1) INTO v_count FROM tmp_temp1;
  WHILE (v_count > 0) LOOP
  SELECT maincatid INTO v_maincatid FROM tmp_temp1 WHERE rownumber = v_count;
  RETURN QUERY SELECT ROW_NUMBER() OVER (ORDER BY sc.catid ASC NULLS FIRST) AS rowno, sc.catid, sc.maincatid, sc.catname, CASE WHEN POSITION('^' IN COALESCE(sc.cat_imgname, '')) > 0 THEN (LEFT(CAST(v_dynamicurl || COALESCE(sc.cat_imgname, '') AS TEXT), POSITION('^' IN v_dynamicurl || COALESCE(sc.cat_imgname, '')) + 0)) ELSE v_dynamicurl || COALESCE(sc.cat_imgname, '') || '^' END AS productimage, mc.maincatname FROM tbl_main_category AS mc JOIN tbl_category AS sc ON sc.maincatid = mc.maincatid WHERE sc.status = 1 AND sc.totalactive > 0 AND sc.maincatid = v_maincatid;
  v_productimage := '';
  v_count := v_count - 1;
  END LOOP;
  DROP TABLE IF EXISTS tmp_temp1;
END;
$$;


