RESELLERNAME VARCHAR(100),
CustomerName Varchar(100),
Orderid Varchar(100),
OrderNo VARCHAR(50),
AMOUNT DECIMAL(18,2),
COMMISSION DECIMAL(18,2),
DATE VARCHAR(100),
Status VARCHAR(100)) ON COMMIT DROP;
