  v_query := 'INSERT INTO #TEMP SELECT isnull(DM.companyname,''''), (TC.FNAME+'' ''+TC.LNAME),ISNULL(POM.ORDERID,''''),ISNULL(POM.ORDERNO,''''),
ISNULL(POM.TOTAL_PURCHASE_COST,0),ISNULL(POM.RESELLERCOMMISSION,0),ISNULL(OM.ORDERDATE,''''),
