RESELLERNAME VARCHAR(100)) ON COMMIT DROP;
  END IF;
  v_query := 'INSERT INTO #TEMP SELECT TCPR.TCPRID,TCPR.CLID,(CL.FNAME+'' ''+CL.LNAME),TCPR.MOBILENO,TCPR.OPERATORTYPE,  
TCPR.OPERATORNAME,TCPR.OPERATORSERVICE,TCPR.RECHARGEAMOUNT,TCPR.RECHARGESTATUS,TCPR.TRANSACTIONID,  
TCPR.RECHARGEDATE,TCPR.ISANDROIDORWEB,TCPR.ADMINCOMMISSION,TCPR.ADMINSURCHARGE,
ISNULL(DM.COMPANYNAME,'''') FROM TBL_CUSTOMER_POSTPAID_RECHARGES TCPR    
LEFT JOIN TBL_CUSTOMERLOGIN CL ON CL.CLID=TCPR.CLID  
LEFT JOIN DISTRIBUTOR_MASTER DM ON CL.DID=DM.PLID  
WHERE  TCPR.RECHARGESTATUS=''SUCCESS'' AND TCPR.ADMINCOMMISSION>0';
  v_query := v_query || ' INSERT INTO #TEMP SELECT TCPR.TCPRID,TCPR.CLID,(CL.FNAME+'' ''+CL.LNAME),TCPR.MOBILENO,TCPR.OPERATORTYPE,  
TCPR.OPERATORNAME,TCPR.OPERATORSERVICE,TCPR.RECHARGEAMOUNT,TCPR.RECHARGESTATUS,TCPR.TRANSACTIONID,TCPR.RECHARGEDATE,TCPR.ISANDROIDORWEB,  
TCPR.ADMINCOMMISSION,TCPR.ADMINSURCHARGE,ISNULL(DM.COMPANYNAME,'''') FROM   
TBL_CUSTOMER_PREPAID_RECHARGES TCPR    
LEFT JOIN TBL_CUSTOMERLOGIN CL ON CL.CLID=TCPR.CLID  
LEFT JOIN DISTRIBUTOR_MASTER DM ON CL.DID=DM.PLID  
WHERE  TCPR.RECHARGESTATUS=''SUCCESS'' AND TCPR.ADMINCOMMISSION>0 ';
  v_query := v_query || ' INSERT INTO #TEMP SELECT TCDR.TCDRID,TCDR.CLID,(CL.FNAME+'' ''+CL.LNAME),TCDR.MOBILENO,TCDR.OPERATORTYPE,  
TCDR.OPERATORNAME,TCDR.OPERATORSERVICE,TCDR.RECHARGEAMOUNT,TCDR.RECHARGESTATUS,TCDR.TRANSACTIONID,TCDR.RECHARGEDATE,  
TCDR.ISANDROIDORWEB,TCDR.ADMINCOMMISSION,TCDR.ADMINSURCHARGE,ISNULL(DM.COMPANYNAME,'''')  
FROM TBL_CUSTOMER_DTH_RECHARGES TCDR   
LEFT JOIN TBL_CUSTOMERLOGIN CL ON CL.CLID=TCDR.CLID  
LEFT JOIN DISTRIBUTOR_MASTER DM ON CL.DID=DM.PLID  
WHERE TCDR.RECHARGESTATUS=''SUCCESS'' AND TCDR.ADMINCOMMISSION>0';
  v_query := v_query || ' INSERT INTO #TEMP SELECT TCER.TCERID,TCER.CLID,(CL.FNAME+'' ''+CL.LNAME),TCER.MOBILENO,TCER.OPERATORTYPE,  
TCER.OPERATORNAME,TCER.OPERATORSERVICE,TCER.RECHARGEAMOUNT,TCER.RECHARGESTATUS,TCER.TRANSACTIONID,TCER.RECHARGEDATE,TCER.ISANDROIDORWEB  
,TCER.ADMINCOMMISSION,TCER.ADMINSURCHARGE,ISNULL(DM.COMPANYNAME,'''')  
FROM TBL_CUSTOMER_ELECTRICITY_RECHARGES TCER  
LEFT JOIN TBL_CUSTOMERLOGIN CL ON CL.CLID=TCER.CLID  
LEFT JOIN DISTRIBUTOR_MASTER DM ON CL.DID=DM.PLID  
WHERE  TCER.RECHARGESTATUS=''SUCCESS''  AND TCER.ADMINCOMMISSION>0';
  v_query := v_query || ' INSERT INTO #TEMP SELECT TCGR.TCGRID,TCGR.CLID,(CL.FNAME+'' ''+CL.LNAME),TCGR.MOBILENO,TCGR.OPERATORTYPE,  
TCGR.OPERATORNAME,TCGR.OPERATORSERVICE,TCGR.RECHARGEAMOUNT,TCGR.RECHARGESTATUS,TCGR.TRANSACTIONID,TCGR.RECHARGEDATE,TCGR.ISANDROIDORWEB,  
TCGR.ADMINCOMMISSION,TCGR.ADMINSURCHARGE,ISNULL(DM.COMPANYNAME,'''')  
FROM TBL_CUSTOMER_GAS_RECHARGES TCGR   
LEFT JOIN  TBL_CUSTOMERLOGIN CL ON CL.CLID=TCGR.CLID   
LEFT JOIN DISTRIBUTOR_MASTER DM ON CL.DID=DM.PLID  
WHERE TCGR.RECHARGESTATUS=''SUCCESS'' AND TCGR.ADMINCOMMISSION>0';
  v_query := v_query || ' INSERT INTO #TEMP SELECT TCIR.TCIRID,TCIR.CLID,(CL.FNAME+'' ''+CL.LNAME),TCIR.MOBILENO,TCIR.OPERATORTYPE,  
TCIR.OPERATORNAME,TCIR.OPERATORSERVICE,TCIR.RECHARGEAMOUNT,TCIR.RECHARGESTATUS,TCIR.TRANSACTIONID,TCIR.RECHARGEDATE,TCIR.ISANDROIDORWEB,  
TCIR.ADMINCOMMISSION,TCIR.ADMINSURCHARGE,ISNULL(DM.COMPANYNAME,'''')  
FROM TBL_CUSTOMER_INSURANCE_RECHARGES TCIR   
LEFT JOIN  TBL_CUSTOMERLOGIN CL ON CL.CLID=TCIR.CLID   
LEFT JOIN DISTRIBUTOR_MASTER DM ON CL.DID=DM.PLID  
WHERE TCIR.RECHARGESTATUS=''SUCCESS'' AND TCIR.ADMINCOMMISSION>0';
  v_query := v_query || ' INSERT INTO #TEMP SELECT TCLR.TCLRID,TCLR.CLID,(CL.FNAME+'' ''+CL.LNAME),TCLR.MOBILENO,TCLR.OPERATORTYPE,  
TCLR.OPERATORNAME,TCLR.OPERATORSERVICE,TCLR.RECHARGEAMOUNT,TCLR.RECHARGESTATUS,TCLR.TRANSACTIONID,TCLR.RECHARGEDATE,TCLR.ISANDROIDORWEB,  
TCLR.ADMINCOMMISSION,TCLR.ADMINSURCHARGE,ISNULL(DM.COMPANYNAME,'''')  
FROM TBL_CUSTOMER_LANDLINE_RECHARGES TCLR   
LEFT JOIN  TBL_CUSTOMERLOGIN CL ON CL.CLID=TCLR.CLID   
LEFT JOIN DISTRIBUTOR_MASTER DM ON CL.DID=DM.PLID  
WHERE TCLR.RECHARGESTATUS=''SUCCESS'' AND TCLR.ADMINCOMMISSION>0';
  EXECUTE v_query;
  v_query := '';
  v_query := 'SELECT ROWNUMBER,ID,CLID,NAME,MOBILENO,OPERATORTYPE,OPERRATORNAME,OPERATORSERVICE,AMOUNT,STATUS,TRANSACTIONID,RECHARGEDATE,  
ISANDROIDORWEB,COMMISSION,SURCHRAGE,RESELLERNAME INTO #MAINDATA FROM #TEMP WHERE 1=1 ';
  IF ((v_fromdate <> '') AND (v_todate = '')) THEN
  v_condition := v_condition || (' AND CONVERT(DATE,RECHARGEDATE,105) BETWEEN  CONVERT(DATE, ''' || v_fromdate || ''',105) AND  CONVERT(DATE, DBO.FUN_GETCURRENTDATE(),105)');
  END IF;
  IF ((v_fromdate = '') AND (v_todate <> '')) THEN
  v_condition := v_condition || ('AND CONVERT(DATE, RECHARGEDATE, 105) BETWEEN  CONVERT(DATE, ''' || v_todate || ''', 105) AND  CONVERT(DATE, DBO.FUN_GETCURRENTDATE(), 105)');
  END IF;
  IF ((v_fromdate <> '') AND (v_todate <> '')) THEN
