  v_condition := v_condition || ' AND TRANSACTIONID LIKE ''%' || v_searchvalue || '%'' ';
  END IF;
  IF (v_searchfield = 'NAME') THEN
  v_condition := v_condition || ' AND NAME LIKE ''%' || v_searchvalue || '%'' ';
  END IF;
  END IF;
  v_condition := v_condition || ' ORDER BY CONVERT(DATE,RECHARGEDATE,105) DESC  ';
  v_query := v_query || v_condition || ' ;SELECT  *  FROM #MAINDATA WHERE ROWNUMBER BETWEEN ' || CAST(v_minindex AS VARCHAR(70)) || ' AND ' || CAST(v_maxindex AS VARCHAR(70)) || 'ORDER BY CONVERT(DATE,RECHARGEDATE,105) DESC';
  v_parmdefinition := N'@TOTALCOUNT NVARCHAR(70) OUTPUT';
  v_countquery := ' ;SELECT @TOTALCOUNT=COUNT(1) FROM #TEMP ';
  EXECUTE v_countquery;
  EXECUTE v_query;
  RAISE NOTICE '%', v_query;
  DROP TABLE IF EXISTS tmp_temp;
  -- SET option (removed)
  -- COMMIT (removed)
END;
$$;


--
-- Name: usp_get_approve_and_reject_keyword(character varying, character varying, character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_get_approve_and_reject_keyword(v_datefrom character varying DEFAULT ''::character varying, v_dateto character varying DEFAULT ''::character varying, v_mode character varying DEFAULT ''::character varying) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_queryforapprove text;
  v_queryforreject text;
BEGIN
  v_queryforapprove := '';
  v_queryforreject := '';
  v_queryforapprove := ' select  ROW_NUMBER() over(order by sak.sakid desc) as rownumber,pc.CatName, sak.keywordname,sak.approvedate,sl.loginid,



(CASE WHEN sak.status=0 then ' || CAST('''Pending''' AS VARCHAR(50)) || ' when sak.status=1 then ' || CAST('''Active''' AS VARCHAR(50)) || ' 



when sak.status=2 then ' || CAST('''Rejected''' AS VARCHAR(50)) || ' when 



sak.status=3 then ' || CAST('''Already Exist''' AS VARCHAR(50)) || ' end) 



AS  status from tbl_sponser_approve_keyword sak join Product_Category pc on sak.catid=pc.catId join sponsor_login sl



on sak.slid=sl.slid';
  v_queryforreject := 'select  ROW_NUMBER() over(order by suggest_keyword_no desc) as rownumber,suggest_keyword_no,keywordname,isnull(suggesteddate,0)as suggesteddate,



isnull(approvedate,0)as approvedate,(CASE WHEN approvestatus=0 then ' || CAST('''Pending''' AS VARCHAR(50)) || ' when approvestatus=1 then ' || CAST('''Active''' AS VARCHAR(50)) || ' 

when approvestatus=2  then ' || CAST('''Rejected''' AS VARCHAR(50)) || ' when approvestatus=3 then ' || CAST('''Already Exist''' AS VARCHAR(50)) || ' end) AS  status,



(case when rejectedreason is null then ' || CAST('''No Reason''' AS VARCHAR(50)) || ' when rejectedreason='''' then ' || CAST('''No Reason''' AS VARCHAR(50)) || ' else rejectedreason end)as rejectedreason,



sl.loginid from tb_sposersuggestedkeyword join sponsor_login sl on tb_sposersuggestedkeyword.slid=sl.slid  where approvestatus=2';
  IF (v_mode = 'A') THEN
  IF (v_datefrom <> '' AND v_dateto <> '') THEN
  v_queryforapprove := v_queryforapprove || ' where convert(date,sak.approvedate) between ''' || CAST(v_datefrom AS VARCHAR(200)) || ''' and ''' || CAST(v_dateto AS VARCHAR(200)) || '''';
  ELSE
  IF (v_datefrom <> '') THEN
  v_queryforapprove := v_queryforapprove || ' where convert(date,sak.approvedate) >= ''' || CAST(v_datefrom AS VARCHAR(200)) || '''';
  END IF;
  END IF;
  EXECUTE v_queryforapprove;
  ELSE
  IF (v_datefrom <> '' AND v_dateto <> '') THEN
  v_queryforreject := v_queryforreject || ' and convert(date,approvedate) between ''' || CAST(v_datefrom AS VARCHAR(200)) || ''' and ''' || CAST(v_dateto AS VARCHAR(200)) || '''';
  ELSE
  IF (v_datefrom <> '') THEN
  v_queryforreject := v_queryforreject || ' and convert(date,approvedate) >= ''' || CAST(v_datefrom AS VARCHAR(200)) || '''';
  END IF;
  END IF;
  EXECUTE v_queryforreject;
  END IF;
END;
$$;


--
-- Name: usp_get_approve_funds(character varying, character varying, character varying, character varying, character varying, character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_get_approve_funds(v_slid character varying DEFAULT ''::character varying, v_datefrom character varying DEFAULT ''::character varying, v_dateto character varying DEFAULT ''::character varying, v_status character varying DEFAULT '0'::character varying, v_paymenttype character varying DEFAULT ''::character varying, v_shortby character varying DEFAULT ''::character varying) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_query text;
BEGIN
  v_query := '';
  v_query := 'select  ROW_NUMBER() over(order by sf.sfdid desc) as rownumber,sf.plid,sf.sfdid,smd.loginid,(smd.fname+'' ''+smd.lname) as Name
,(CASE WHEN FundApproveDate IS not NULL THEN convert(varchar(10),FundApproveDate, 101) ELSE ''-''  END) AS  FundApproveDate,sf.DepositAmount ,
(case when sf.PaymentType is null then ''-'' else sf.PaymentType end) as PaymentType,sf.status
,(case when sf.billid is null then ' || CAST(0 AS VARCHAR(10)) || ' else sf.billid end) as Billid,
(case when sf.check_sno is null then ' || CAST(0 AS VARCHAR(10)) || ' else sf.check_sno end)as check_sno,
(case when sf.checkstatus is null then ' || CAST(0 AS VARCHAR(10)) || ' else sf.checkstatus end)as checkstatus,cm.currencysymbol,
(case when sf.RejectReview is null then ' || CAST('''No reason mentioned''' AS VARCHAR(100)) || ' when sf.RejectReview='''' then 
' || CAST('''No reason mentioned''' AS VARCHAR(100)) || ' else sf.RejectReview end) as RejectReview
 from tbl_sponserfunddetails sf join Portal_Login smd
 on sf.plid=smd.plid join tbl_currencymaster cm on smd.cid=cm.CID  where sf.DepositAmount is not null and sf.PaymentType!=''manual'' and sf.PaymentType!=''Coupon'' and sf.PaymentType!=''ewallet''';
  IF (v_datefrom <> '' AND v_dateto <> '') THEN
  v_query := v_query || '  and convert(date,FundApproveDate) between ''' || CAST(v_datefrom AS VARCHAR(200)) || ''' and ''' || CAST(v_dateto AS VARCHAR(200)) || ''' and sf.status=' || v_status || '';
  ELSE
  IF (v_datefrom <> '') THEN
  v_query := v_query || ' and convert(date,FundApproveDate) >= ''' || CAST(v_datefrom AS VARCHAR(200)) || ''' and sf.status=' || v_status || '';
  END IF;
  END IF;
  IF (v_paymenttype <> '') THEN
  v_query := v_query || ' and sf.PaymentType= ''' || CAST(v_paymenttype AS VARCHAR(200)) || ''' and sf.status=' || v_status || '';
  END IF;
  IF (v_slid <> '' AND v_slid <> '0') THEN
  v_query := v_query || ' and sf.plid=' || CAST(v_slid AS VARCHAR(10)) || ' and sf.status=' || v_status || '';
  END IF;
  IF (v_status <> '') THEN
  v_query := v_query || ' and sf.status=' || v_status || '';
  END IF;
  IF (v_shortby <> '') THEN
  v_query := v_query || ' and sf.status=' || v_status || ' order by sf.DepositAmount ' || v_shortby || '';
  END IF;
  EXECUTE v_query;
END;
$$;


--
-- Name: usp_get_bvdetails(integer, integer, integer, character varying, character varying, integer, character varying, character varying, character varying, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_get_bvdetails(v_mode integer DEFAULT 0, v_startrowindex integer DEFAULT 1, v_maxrows integer DEFAULT 100, v_fromdate character varying DEFAULT ''::character varying, v_todate character varying DEFAULT ''::character varying, v_totalcount integer DEFAULT 0, v_searchfield character varying DEFAULT ''::character varying, v_searchvalue character varying DEFAULT ''::character varying, v_status character varying DEFAULT ''::character varying, v_did integer DEFAULT 2) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_minindex INT;
  v_maxindex INT;
  v_query text;
  v_totaldata INT;
  v_count INT;
  v_temporderno VARCHAR(100);
  v_tempprocesstype INT;
  v_orderid VARCHAR(100);
  v_orderamount DECIMAL(18,2);
  v_customername VARCHAR(100);
BEGIN
  v_totaldata := 0;
  v_count := 1;
  v_temporderno := '';
  v_tempprocesstype := 0;
  v_orderid := '';
  v_customername := '';
  v_minindex := (v_startrowindex - 1) * v_maxrows + 1;
  v_maxindex := v_startrowindex * v_maxrows;
  IF (v_mode = 0) THEN
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp (ROWNUMBER BIGINT GENERATED BY DEFAULT AS IDENTITY,
	DID INT,
	ORDERNO VARCHAR(100),
	ORDER_BV DECIMAL(18,2),
	PROCESSTYPE INT,
	RESELLERNAME VARCHAR(100), 
	CUSTOMERNAME VARCHAR(100),       
	ORDERID VARCHAR(100),         
	ORDER_NETAMT DECIMAL(18,2),	
	ORDERDATE VARCHAR(100)) ON COMMIT DROP;
  v_query := 'INSERT INTO #TEMP SELECT RRB.DID,RRB.ORDERNO,RRB.ORDERBV,
RRB.PROCESSTYPE,TD.COMPANYNAME,'''','''',0,RRB.PROCESSDATE 
FROM TBL_RESELLERRELEASEBVDETAILS RRB
LEFT JOIN DISTRIBUTOR_MASTER TD ON RRB.DID=TD.PLID
WHERE RRB.STATUS=1 and RRB.ORDERBV>0 ';
  IF ((v_fromdate <> '') AND (v_todate = '')) THEN
  v_query := v_query || ' AND CONVERT(DATE, RRB.PROCESSDATE, 105) BETWEEN  CONVERT(DATE, ''' || v_fromdate || ''', 105) AND  CONVERT(DATE, DBO.FUN_GETCURRENTDATE(), 105)';
  END IF;
  IF ((v_fromdate = '') AND (v_todate <> '')) THEN
  v_query := v_query || 'AND CONVERT(DATE, RRB.PROCESSDATE, 105) BETWEEN  CONVERT(DATE, ''' || v_todate || ''', 105) AND  CONVERT(DATE, DBO.FUN_GETCURRENTDATE(), 105)';
  END IF;
  IF ((v_fromdate <> '') AND (v_todate <> '')) THEN
  v_query := v_query || 'AND CONVERT(DATE, RRB.PROCESSDATE, 105) BETWEEN CONVERT(DATE, ''' || v_fromdate || ''', 105) AND  CONVERT(DATE, ''' || v_todate || ''', 105)';
  END IF;
  IF (v_searchfield = 'NAME') THEN
  v_query := v_query || ' AND (CL.FNAME+CL.LNAME) LIKE ''%' || v_searchvalue || '%'' ';
  END IF;
  IF (v_searchfield = 'ORDERID') THEN
  v_query := v_query || ' AND OM.ORDERID LIKE ''%' || v_searchvalue || '%'' ';
  END IF;
  v_query := v_query || ' AND RRB.DID=''' || CAST(v_did AS VARCHAR(30)) || '''';
  v_query := v_query || ' ORDER BY RRB.PROCESSDATE DESC';
  EXECUTE v_query;
  RAISE NOTICE '%', v_query;
  SELECT COUNT(1) INTO v_totaldata FROM tmp_temp;
  WHILE (v_totaldata >= v_count) LOOP
  SELECT orderno, processtype INTO v_temporderno, v_tempprocesstype FROM tmp_temp WHERE rownumber = v_count;
  IF EXISTS(SELECT 1 FROM tbl_product_order_master WHERE orderno = v_temporderno AND NOT intstatus IN (7, 8)) THEN
  SELECT pom.orderid, pom.total_purchase_cost, (cl.fname || ' ' || cl.lname) INTO v_orderid, v_orderamount, v_customername FROM tbl_product_order_master AS pom LEFT JOIN tbl_customerlogin AS cl ON pom.loginid = cl.loginid WHERE orderno = v_temporderno;
  ELSE
  IF EXISTS(SELECT 1 FROM tbl_customer_postpaid_recharges WHERE transactionid = v_temporderno) THEN
  SELECT tcpr.transactionid, tcpr.rechargeamount, (cl.fname || ' ' || cl.lname) INTO v_orderid, v_orderamount, v_customername FROM tbl_customer_postpaid_recharges AS tcpr LEFT JOIN tbl_customerlogin AS cl ON tcpr.clid = cl.clid WHERE transactionid = v_temporderno;
  ELSE
  IF EXISTS(SELECT 1 FROM tbl_customer_prepaid_recharges WHERE transactionid = v_temporderno) THEN
  SELECT tcpr.transactionid, tcpr.rechargeamount, (cl.fname || ' ' || cl.lname) INTO v_orderid, v_orderamount, v_customername FROM tbl_customer_prepaid_recharges AS tcpr LEFT JOIN tbl_customerlogin AS cl ON tcpr.clid = cl.clid WHERE transactionid = v_temporderno;
  ELSE
  IF EXISTS(SELECT 1 FROM tbl_customer_dth_recharges WHERE transactionid = v_temporderno) THEN
  SELECT tcdr.transactionid, tcdr.rechargeamount, (cl.fname || ' ' || cl.lname) INTO v_orderid, v_orderamount, v_customername FROM tbl_customer_dth_recharges AS tcdr LEFT JOIN tbl_customerlogin AS cl ON tcdr.clid = cl.clid WHERE transactionid = v_temporderno;
  ELSE
  IF EXISTS(SELECT 1 FROM tbl_customer_electricity_recharges WHERE transactionid = v_temporderno) THEN
  SELECT tcpr.transactionid, tcpr.rechargeamount, (cl.fname || ' ' || cl.lname) INTO v_orderid, v_orderamount, v_customername FROM tbl_customer_electricity_recharges AS tcpr LEFT JOIN tbl_customerlogin AS cl ON tcpr.clid = cl.clid WHERE transactionid = v_temporderno;
  ELSE
  IF EXISTS(SELECT 1 FROM tbl_customer_gas_recharges WHERE transactionid = v_temporderno) THEN
  SELECT tcgr.transactionid, tcgr.rechargeamount, (cl.fname || ' ' || cl.lname) INTO v_orderid, v_orderamount, v_customername FROM tbl_customer_gas_recharges AS tcgr LEFT JOIN tbl_customerlogin AS cl ON tcgr.clid = cl.clid WHERE transactionid = v_temporderno;
  END IF;
  END IF;
  END IF;
  END IF;
  END IF;
  END IF;
  UPDATE tmp_temp SET customername = v_customername, orderid = v_orderid, order_netamt = v_orderamount WHERE rownumber = v_count AND orderno = v_temporderno;
  v_count := v_count + 1;
  END LOOP;
  RETURN QUERY SELECT * FROM tmp_temp WHERE rownumber BETWEEN v_minindex AND v_maxindex;
  SELECT COUNT(rownumber) INTO v_totalcount FROM tmp_temp;
  DROP TABLE IF EXISTS tmp_temp;
  -- SET option (removed)
  END IF;
END;
$$;


--
-- Name: usp_get_cashbackdetails(integer, integer, integer, character varying, character varying, integer, character varying, character varying, character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_get_cashbackdetails(v_mode integer DEFAULT 0, v_startrowindex integer DEFAULT 1, v_maxrows integer DEFAULT 100, v_fromdate character varying DEFAULT ''::character varying, v_todate character varying DEFAULT ''::character varying, v_totalcount integer DEFAULT 0, v_searchfield character varying DEFAULT ''::character varying, v_searchvalue character varying DEFAULT ''::character varying, v_status character varying DEFAULT ''::character varying) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_minindex INT;
  v_maxindex INT;
  v_query text;
BEGIN
  v_minindex := (v_startrowindex - 1) * v_maxrows + 1;
  v_maxindex := v_startrowindex * v_maxrows;
  IF (v_mode = 0) THEN
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp (ROWNUMBER BIGINT GENERATED BY DEFAULT AS IDENTITY,
	RESELLERNAME VARCHAR(100), 
	CUSTOMERNAME VARCHAR(100),       
	ORDERID VARCHAR(100),         
	TOTAL_PURCHASE_COST DECIMAL(18,2),	
	ORDERDATE VARCHAR(100),
	CASHBACK DECIMAL(18,2)) ON COMMIT DROP;
  v_query := 'INSERT INTO #TEMP SELECT DM.COMPANYNAME,(CL.FNAME+'' ''+CL.LNAME),POM.ORDERID,POM.TOTAL_PURCHASE_COST,
  OM.ORDERDATE,ISNULL(TDCS.CASHBACK,0)
 FROM TBL_DISTRIBUTOR_COMMISSION_STRUCTURE TDCS
INNER JOIN IMS_MASTERPRODUCT IMP ON TDCS.SUBSUBCATID=IMP.SUBCATEGORYID  
INNER JOIN TBL_PRODUCT_ORDER_MASTER POM ON IMP.MPRID=POM.SUBPRCODE 
INNER JOIN TBL_CUSTOMERLOGIN CL ON POM.LOGINID=CL.LOGINID
INNER JOIN TBL_ORDER_MASTER OM ON POM.ORDERID=OM.ORDERID
LEFT JOIN DISTRIBUTOR_MASTER DM ON CL.DID=DM.PMID
WHERE POM.INTSTATUS=6 ';
  IF ((v_fromdate <> '') AND (v_todate = '')) THEN
  v_query := v_query || ' AND CONVERT(DATE, OM.ORDERDATE, 105) BETWEEN  CONVERT(DATE, ''' || v_fromdate || ''', 105) AND  CONVERT(DATE, DBO.FUN_GETCURRENTDATE(), 105)';
  END IF;
  IF ((v_fromdate = '') AND (v_todate <> '')) THEN
  v_query := v_query || 'AND CONVERT(DATE, OM.ORDERDATE, 105) BETWEEN  CONVERT(DATE, ''' || v_todate || ''', 105) AND  CONVERT(DATE, DBO.FUN_GETCURRENTDATE(), 105)';
  END IF;
  IF ((v_fromdate <> '') AND (v_todate <> '')) THEN
  v_query := v_query || 'AND CONVERT(DATE, OM.ORDERDATE, 105) BETWEEN CONVERT(DATE, ''' || v_fromdate || ''', 105) AND  CONVERT(DATE, ''' || v_todate || ''', 105)';
  END IF;
  IF (v_searchfield = 'NAME') THEN
  v_query := v_query || ' AND (CL.FNAME+CL.LNAME) LIKE ''%' || v_searchvalue || '%'' ';
  END IF;
  IF (v_searchfield = 'ORDERID') THEN
  v_query := v_query || ' AND OM.ORDERID LIKE ''%' || v_searchvalue || '%'' ';
  END IF;
  v_query := v_query || ' ORDER BY OM.ORDERDATE DESC';
  EXECUTE v_query;
  RAISE NOTICE '%', v_query;
  RETURN QUERY SELECT * FROM tmp_temp WHERE rownumber BETWEEN v_minindex AND v_maxindex;
  SELECT COUNT(rownumber) INTO v_totalcount FROM tmp_temp;
  DROP TABLE IF EXISTS tmp_temp;
  -- SET option (removed)
  END IF;
END;
$$;


--
-- Name: usp_get_category_prodcut_count(); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_get_category_prodcut_count() RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
BEGIN
  RETURN QUERY SELECT vc.vcid, vc.branchid, vc.vattitle, vc.vatpercvalue, vc.active, COUNT(ps.subprcode) AS prodcount, CONCAT(vc.vattitle, '(' || CAST(ROUND(vc.vatpercvalue, 2) AS VARCHAR(50)) || '% )') AS vatnewtitle FROM tbl_vat_categories AS vc LEFT JOIN ims_subproduct AS ps ON ps.vatcategoryid = vc.vcid AND COALESCE(ps.isactive, 0) = 1 WHERE COALESCE(vc.active, 0) = 1 GROUP BY vc.vcid, vc.branchid, vc.vattitle, vc.vatpercvalue, vc.active ORDER BY vatpercvalue ASC NULLS FIRST;
END;
$$;


--
-- Name: usp_get_cofig_data(character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_get_cofig_data(v_config_name character varying DEFAULT NULL::character varying) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF (COALESCE(v_config_name, '') <> '') THEN
  RETURN QUERY SELECT config_name AS text, config_value AS value, config_description AS description FROM configuration_master WHERE config_name IN (SELECT item FROM dbo.SPLITSTRING(v_config_name, ','));
  ELSE
  RETURN QUERY SELECT config_name AS text, config_value AS value, config_description AS description FROM configuration_master WHERE is_active = 1;
  END IF;
END;
$$;


--
-- Name: usp_get_commission_report_admin(integer, bigint, integer, integer, integer, integer, character varying, character varying, character varying, character varying, character varying, character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_get_commission_report_admin(v_mode integer DEFAULT 1, v_plid bigint DEFAULT 0, v_recordcount integer DEFAULT 0, v_intresult integer DEFAULT 0, v_startrowindex integer DEFAULT 1, v_maxrows integer DEFAULT 99999, v_catname character varying DEFAULT ''::character varying, v_subcatname character varying DEFAULT ''::character varying, v_orderby character varying DEFAULT ''::character varying, v_searchsubsubcategory character varying DEFAULT ''::character varying, v_searchsubcategory character varying DEFAULT ''::character varying, v_searchcategory character varying DEFAULT ' '::character varying) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_category text;
  v_subcategory text;
  v_query text;
  v_minindex INT;
  v_maxindex INT;
  v_query1 text;
BEGIN
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp (ROWNUMBER BIGINT GENERATED BY DEFAULT AS IDENTITY ,
	CATNAME varchar(500),
	SUBCATNAME varchar(500),
	ADMINCHARGE DECIMAL(10,2),
	DELIEVERYCHARGE DECIMAL(10,2),
	HANDLINGCHARGE DECIMAL(10,2),
	FixedFee DECIMAL(10,2),
	SubSubCatName varchar(500),
	SUBCATID int,
	BVPER DECIMAL(10,2),
	cashback_Per DECIMAL(10,2),
	newbv DECIMAL(10,2),
	newcashback DECIMAL(10,2),
	return int,
	REFUND int,
	EXCHANGE int) ON COMMIT DROP;
  v_category := '';
  v_subcategory := '';
  v_query := '';
  IF (v_mode = 1) THEN
  v_minindex := (v_startrowindex - 1) * v_maxrows + 1;
  v_maxindex := v_startrowindex * v_maxrows;
  IF (v_plid > 0) THEN
  SELECT subcategory INTO v_subcategory FROM tbl_merchantcat_subcat_keywordmaster WHERE plid = v_plid AND isactive = 1 AND isdeleted = 0;
  END IF;
  v_query := 'INSERT INTO #TEMP SELECT  TMC.MAINCATNAME,TC.CATNAME,ISNULL(km.ADMINCHARGE,0) AS ADMINCHARGE,ISNULL(km.DELIEVERYCHARGE,0) AS DELIEVERYCHARGE,
	ISNULL(km.HANDLINGCHARGE,0) AS HANDLINGCHARGE,ISNULL(km.FixedFee,0) AS FixedFee,(km.SubCatName)AS SubSubCatName,ISNULL(km.SUBCATID,0) AS SUBCATID,
	ISNULL(km.BVPER,0) AS BVPER ,ISNULL(km.cashback_Per,0) AS cashback_Per, isnull(tcs.bv,0) as newbv,isnull(tcs.cashback,0) as newcashback
	,ISNULL(km.[RETURN],0) as [RETURN],ISNULL(km.REFUND,0) as REFUND,ISNULL(km.EXCHANGE,0) as EXCHANGE  FROM 
	TBL_MAIN_CATEGORY TMC INNER JOIN TBL_CATEGORY TC ON TMC.MAINCATID = TC.MAINCATID 
    inner join 	tbl_sub_category km on TC.CatId=km.CatId
	left join tbl_Distributor_Commission_Structure tcs on tcs.SubSubCatID= km.SUBCATID
	 WHERE  TC.STATUS=1 AND TMC.STATUS = 1 ';
  IF (v_searchsubsubcategory <> '') THEN
  v_searchsubsubcategory := REPLACE(v_searchsubsubcategory, '', '');
  v_query := v_query || 'AND km.subcatname=''' || v_searchsubsubcategory || '''';
  END IF;
  IF (v_searchsubcategory <> '') THEN
  v_searchsubcategory := REPLACE(v_searchsubcategory, '''', '''''');
  v_query := v_query || 'AND TC.CATNAME =''' || v_searchsubcategory || '''';
  END IF;
  IF (v_searchcategory <> '') THEN
  v_searchcategory := REPLACE(v_searchcategory, '''', '''''');
  v_query := v_query || 'AND TMC.MAINCATNAME =''' || v_searchcategory || '''';
  END IF;
  RAISE NOTICE '%', v_query;
  EXECUTE v_query;
  RETURN QUERY SELECT * FROM tmp_temp WHERE rownumber IN (SELECT MIN(rownumber) FROM tmp_temp GROUP BY subcatid) AND rownumber BETWEEN v_minindex AND v_maxindex;
  SELECT COUNT(1) INTO v_recordcount FROM tmp_temp;
  DROP TABLE IF EXISTS tmp_temp;
  END IF;
  IF (v_mode = 2) THEN
  v_query := 'INSERT INTO #TEMP SELECT TMC.MAINCATNAME,TC.CATNAME,ISNULL(km.ADMINCHARGE,0) AS ADMINCHARGE,ISNULL(km.DELIEVERYCHARGE,0) AS DELIEVERYCHARGE,
	ISNULL(km.HANDLINGCHARGE,0) AS HANDLINGCHARGE,ISNULL(km.FixedFee,0) AS FixedFee, (km.SubCatName)AS SubSubCatName FROM TBL_MAIN_CATEGORY TMC INNER JOIN TBL_CATEGORY TC ON TMC.MAINCATID = TC.MAINCATID 
	inner join 	tbl_sub_category km on TC.MAINCATID=km.MainCatId WHERE 
	TC.STATUS=1 AND TMC.STATUS = 1 ';
  IF (v_catname <> '') THEN
  v_query := v_query || (' AND TMC.MAINCATNAME LIKE ''%' || v_catname || '%''');
  END IF;
  IF (v_subcatname <> '') THEN
  v_query := v_query || (' AND TC.CATNAME LIKE ''%' || v_subcatname || '%''');
  END IF;
  RETURN QUERY SELECT v_query;
  EXECUTE v_query;
  v_query1 := '';
  v_query1 := v_query1 || ('SELECT * FROM #TEMP WHERE ROWNUMBER BETWEEN ''' || CAST(v_startrowindex AS VARCHAR) || ''' AND ''' || CAST(v_maxrows AS VARCHAR) || ''' ');
  IF (v_orderby <> '') THEN
  IF (v_orderby = 'ADMINCHARGEASC') THEN
  v_query1 := v_query1 || (' ORDER BY ADMINCHARGE ASC');
  ELSE
  IF (v_orderby = 'ADMINCHARGEDESC') THEN
  v_query1 := v_query1 || (' ORDER BY ADMINCHARGE DESC');
  ELSE
  IF (v_orderby = 'DELIEVERYCHARGEASC') THEN
  v_query1 := v_query1 || (' ORDER BY DELIEVERYCHARGE ASC');
  ELSE
  IF (v_orderby = 'DELIEVERYCHARGEDESC') THEN
  v_query1 := v_query1 || (' ORDER BY DELIEVERYCHARGE DESC');
  ELSE
  IF (v_orderby = 'HANDLINGCHARGEASC') THEN
  v_query1 := v_query1 || (' ORDER BY HANDLINGCHARGE ASC');
  ELSE
  IF (v_orderby = 'HANDLINGCHARGEDESC') THEN
  v_query1 := v_query1 || (' ORDER BY HANDLINGCHARGE DESC');
  END IF;
  END IF;
  END IF;
  END IF;
  END IF;
  END IF;
  ELSE
  v_query1 := v_query1 || (' ORDER BY CATNAME,SUBCATNAME');
  END IF;
  EXECUTE v_query1;
  RETURN QUERY SELECT v_query1;
  RETURN QUERY SELECT COUNT(1) AS recordcount FROM tmp_temp;
  DROP TABLE IF EXISTS tmp_temp;
  END IF;
END;
$$;


--
-- Name: usp_get_commsionamount(character varying, integer, numeric, numeric); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_get_commsionamount(v_orderid character varying DEFAULT 'OD390330954'::character varying, v_plid integer DEFAULT 0, INOUT v_totalcommsion numeric DEFAULT 0, INOUT v_totalcommsionwithgst numeric DEFAULT 0) RETURNS record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_count INT;
  v_totalcount INT;
  v_gstpercentage Decimal(18,2);
BEGIN
  -- BEGIN TRAN (removed)
  -- SET option (removed)
  v_count := 1;
  v_totalcount := 0;
  v_gstpercentage := 0;
  SELECT COALESCE(limits, 0) INTO v_gstpercentage FROM settings WHERE sid = 22;
  DROP TABLE IF EXISTS tmp_tbl_commsiontemp;
  CREATE TEMP TABLE tmp_tbl_commsiontemp (ROWNUMBER INT GENERATED BY DEFAULT AS IDENTITY,TAXABLEAMOUNT DECIMAL(18,2),ADMINCHARGES DECIMAL(18,2),HANDLINGCHARGES DECIMAL(18,2),
FIXEDCHARGES DECIMAL(18,2),SHIPPINGCHARGES DECIMAL(18,2)) ON COMMIT DROP;
  INSERT INTO tmp_tbl_commsiontemp SELECT DISTINCT tmcd.taxableamount, tmcd.admincharges, tmcd.handlingcharges, tmcd.fixedcharges, tms.shippingcharges FROM tbl_merchant_commissioninvoices_details AS tmcd INNER JOIN tbl_merchant_shippinginvoices_details AS tms ON tmcd.orderid = tms.orderid WHERE tmcd.orderid = v_orderid AND tmcd.plid = v_plid;
  SELECT COUNT(1) INTO v_totalcount FROM tmp_tbl_commsiontemp;
  v_totalcommsion := 0;
  v_totalcommsionwithgst := 0;
  WHILE (v_count <= v_totalcount) LOOP
  SELECT v_totalcommsion + ((((taxableamount * admincharges) / 100) + handlingcharges + ((taxableamount * fixedcharges) / 100) + shippingcharges)) INTO v_totalcommsion FROM tmp_tbl_commsiontemp WHERE rownumber = v_count;
  v_count := v_count + 1;
  END LOOP;
  SELECT ((v_totalcommsion * v_gstpercentage) / 100) INTO v_totalcommsionwithgst;
  DROP TABLE IF EXISTS tmp_tbl_commsiontemp;
  -- SET option (removed)
  -- COMMIT (removed)
END;
$$;


--
-- Name: usp_get_companydetails(); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_get_companydetails() RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
BEGIN
  RETURN QUERY SELECT COALESCE(name, 'N/A') AS name, COALESCE(mobile, 'N/A') AS mobile, COALESCE(landline, 'N/A') AS landline, COALESCE(emailid, 'N/A') AS emailid, COALESCE(address_1, 'N/A') AS address, COALESCE(gstno, 'N/A') AS gstno, 'N/A' AS cin, 'N/A' AS pan FROM dbo.tbl_company;
END;
$$;


--
-- Name: usp_get_ctid_fromcountrystatecity(character varying, character varying, character varying, integer, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_get_ctid_fromcountrystatecity(v_ctname character varying DEFAULT ''::character varying, v_statename character varying DEFAULT ''::character varying, v_countryname character varying DEFAULT ''::character varying, INOUT v_ctid integer DEFAULT NULL::integer, INOUT v_intresult integer DEFAULT NULL::integer) RETURNS record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_cid int;
  v_sid int;
BEGIN
  v_intresult := 1;
  v_ctid := 0;
  SELECT cid INTO v_cid FROM country WHERE countryname = v_countryname;
  IF (v_statename = 'delhi ncr') THEN
  SELECT COALESCE(sid, 0) INTO v_sid FROM state WHERE statename = 'delhi/ncr';
  ELSE
  SELECT COALESCE(sid, 0) INTO v_sid FROM state WHERE statename = v_statename;
  END IF;
  SELECT COALESCE(ctid, 0) INTO v_ctid FROM city WHERE cityname = v_ctname AND sid = v_sid AND cid = v_cid;
END;
$$;


--
-- Name: usp_get_customer_allrecharge_reports(integer, integer, integer, character varying, character varying, character varying, character varying, character varying, character varying, integer, integer, character varying, character varying, character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_get_customer_allrecharge_reports(v_mode integer DEFAULT 1, v_startrowindex integer DEFAULT 1, v_maxrows integer DEFAULT 100, v_fromdate character varying DEFAULT ''::character varying, v_todate character varying DEFAULT ''::character varying, v_searchfield character varying DEFAULT ''::character varying, v_searchvalue character varying DEFAULT ''::character varying, v_status character varying DEFAULT '1'::character varying, v_clid character varying DEFAULT '33'::character varying, v_did integer DEFAULT 0, INOUT v_totalcount integer DEFAULT 0, v_rechargetype character varying DEFAULT ''::character varying, v_operatorwise character varying DEFAULT ''::character varying, v_transid character varying DEFAULT ''::character varying) RETURNS integer
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_minindex INT;
  v_maxindex INT;
  v_query text;
  v_condition text;
  v_countquery text;
  v_parmdefinition varchar(70);
BEGIN
  -- BEGIN TRAN (removed)
  -- SET option (removed)
  v_condition := '';
  v_countquery := '';
  v_minindex := (v_startrowindex - 1) * v_maxrows + 1;
  v_maxindex := v_startrowindex * v_maxrows;
  IF (v_mode = 1) THEN
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp (ROWNUMBER BIGINT GENERATED BY DEFAULT AS IDENTITY,    
ID BIGINT,    
CLID BIGINT,    
NAME VARCHAR(100),    
MOBILENO VARCHAR(100),    
OPERATORTYPE VARCHAR(100),    
OPERRATORNAME VARCHAR(100),    
OPERATORSERVICE VARCHAR(100),    
AMOUNT DECIMAL(18,2),    
STATUS VARCHAR(100),    
TRANSACTIONID VARCHAR(100),    
RECHARGEDATE VARCHAR(100),    
ISANDROIDORWEB INT,    
MLMWALLET DECIMAL(18,2),    
CUSTOMERWALLET DECIMAL(18,2),    
PAYUMONEY DECIMAL(18,2),    
REMARKS VARCHAR(500)) ON COMMIT DROP;
  END IF;
  v_query := 'INSERT INTO #TEMP SELECT TCPR.TCPRID,TCPR.CLID,(CL.FNAME+'' ''+CL.LNAME),
TCPR.MOBILENO,TCPR.OPERATORTYPE,    
TCPR.OPERATORNAME,TCPR.OPERATORSERVICE,TCPR.RECHARGEAMOUNT,TCPR.RECHARGESTATUS,
TCPR.TRANSACTIONID,    
TCPR.RECHARGEDATE,TCPR.ISANDROIDORWEB,ISNULL(TROP.MLMWALLET,0) as MLMWALLET,
ISNULL(TROP.CUSTOMERWALLET,0) AS CUSTOMERWALLET,    
ISNULL(TROP.ONLINEAMOUNT,0) AS PAYUMONEY,ISNULL(TCPR.RESPONSEREMARKS,'''') FROM 
TBL_CUSTOMER_POSTPAID_RECHARGES TCPR     
LEFT JOIN TBL_CUSTOMERLOGIN CL ON CL.CLID=TCPR.CLID    
LEFT JOIN TBL_RECHARGEONLINEPAYMENTSDETAILS TROP ON TCPR.TRANSACTIONID=TROP.TRANSID    
WHERE ISNULL(TCPR.RECHARGESTATUS,0)=''' || CAST(v_status AS VARCHAR(100)) || '''    
AND TCPR.CLID=''' || CAST(v_clid AS VARCHAR(100)) || ''' ';
  v_query := v_query || ' INSERT INTO #TEMP SELECT TCPR.TCPRID,TCPR.CLID,(CL.FNAME+'' ''+CL.LNAME),TCPR.MOBILENO,TCPR.OPERATORTYPE,    
TCPR.OPERATORNAME,TCPR.OPERATORSERVICE,TCPR.RECHARGEAMOUNT,TCPR.RECHARGESTATUS,TCPR.TRANSACTIONID,TCPR.RECHARGEDATE,TCPR.ISANDROIDORWEB,    
ISNULL(TROP.MLMWALLET,0) AS MLMWALLET,ISNULL(TROP.CUSTOMERWALLET,0) AS CUSTOMERWALLET,    
ISNULL(TROP.ONLINEAMOUNT,0) AS PAYUMONEY,ISNULL(TCPR.RESPONSEREMARKS,'''')  FROM     
TBL_CUSTOMER_PREPAID_RECHARGES TCPR      
LEFT JOIN TBL_CUSTOMERLOGIN CL ON CL.CLID=TCPR.CLID     
LEFT JOIN TBL_RECHARGEONLINEPAYMENTSDETAILS TROP ON TCPR.TRANSACTIONID=TROP.TRANSID    
WHERE ISNULL(TCPR.RECHARGESTATUS,0)=''' || CAST(v_status AS VARCHAR(100)) || '''     
AND TCPR.CLID=''' || CAST(v_clid AS VARCHAR(100)) || ''' ';
  v_query := v_query || ' INSERT INTO #TEMP SELECT TCDCR.TCDCRID,TCDCR.CLID,(CL.FNAME+'' ''+CL.LNAME),TCDCR.MOBILENO,TCDCR.OPERATORTYPE,    
TCDCR.OPERATORNAME,TCDCR.OPERATORSERVICE,TCDCR.RECHARGEAMOUNT,TCDCR.RECHARGESTATUS,TCDCR.TRANSACTIONID,TCDCR.RECHARGEDATE,TCDCR.ISANDROIDORWEB,    
ISNULL(TROP.MLMWALLET,0) AS MLMWALLET,ISNULL(TROP.CUSTOMERWALLET,0) AS CUSTOMERWALLET,    
ISNULL(TROP.ONLINEAMOUNT,0) AS PAYUMONEY,ISNULL(TCDCR.RESPONSEREMARKS,'''')    
FROM TBL_CUSTOMER_DATACARD_RECHARGES TCDCR     
LEFT JOIN TBL_CUSTOMERLOGIN CL ON CL.CLID=TCDCR.CLID     
LEFT JOIN TBL_RECHARGEONLINEPAYMENTSDETAILS TROP ON TCDCR.TRANSACTIONID=TROP.TRANSID    
WHERE ISNULL(TCDCR.RECHARGESTATUS,0)=''' || CAST(v_status AS VARCHAR(100)) || '''     
AND TCDCR.CLID=''' || CAST(v_clid AS VARCHAR(100)) || ''' ';
  v_query := v_query || ' INSERT INTO #TEMP SELECT TCWR.TCWRID,TCWR.CLID,(CL.FNAME+'' ''+CL.LNAME),TCWR.MOBILENO,TCWR.OPERATORTYPE,    
TCWR.OPERATORNAME,TCWR.OPERATORSERVICE,TCWR.RECHARGEAMOUNT,TCWR.RECHARGESTATUS,TCWR.TRANSACTIONID,TCWR.RECHARGEDATE,TCWR.ISANDROIDORWEB,    
ISNULL(TROP.MLMWALLET,0) AS MLMWALLET,ISNULL(TROP.CUSTOMERWALLET,0) AS CUSTOMERWALLET,    
ISNULL(TROP.ONLINEAMOUNT,0) AS PAYUMONEY,ISNULL(TCWR.RESPONSEREMARKS,'''')    
FROM TBL_CUSTOMER_WATER_RECHARGES TCWR     
LEFT JOIN TBL_CUSTOMERLOGIN CL ON CL.CLID=TCWR.CLID     
LEFT JOIN TBL_RECHARGEONLINEPAYMENTSDETAILS TROP ON TCWR.TRANSACTIONID=TROP.TRANSID    
WHERE ISNULL(TCWR.RECHARGESTATUS,0)=''' || CAST(v_status AS VARCHAR(100)) || '''     
AND TCWR.CLID=''' || CAST(v_clid AS VARCHAR(100)) || ''' ';
  v_query := v_query || ' INSERT INTO #TEMP SELECT TCBR.TCBRID,TCBR.CLID,(CL.FNAME+'' ''+CL.LNAME),TCBR.MOBILENO,TCBR.OPERATORTYPE,    
TCBR.OPERATORNAME,TCBR.OPERATORSERVICE,TCBR.RECHARGEAMOUNT,TCBR.RECHARGESTATUS,TCBR.TRANSACTIONID,TCBR.RECHARGEDATE,TCBR.ISANDROIDORWEB,    
ISNULL(TROP.MLMWALLET,0) AS MLMWALLET,ISNULL(TROP.CUSTOMERWALLET,0) AS CUSTOMERWALLET,    
ISNULL(TROP.ONLINEAMOUNT,0) AS PAYUMONEY,ISNULL(TCBR.RESPONSEREMARKS,'''')    
FROM TBL_CUSTOMER_BROADBAND_RECHARGES TCBR     
LEFT JOIN TBL_CUSTOMERLOGIN CL ON CL.CLID=TCBR.CLID     
LEFT JOIN TBL_RECHARGEONLINEPAYMENTSDETAILS TROP ON TCBR.TRANSACTIONID=TROP.TRANSID    
WHERE ISNULL(TCBR.RECHARGESTATUS,0)=''' || CAST(v_status AS VARCHAR(100)) || '''     
AND TCBR.CLID=''' || CAST(v_clid AS VARCHAR(100)) || ''' ';
  v_query := v_query || ' INSERT INTO #TEMP SELECT TCDR.TCDRID,TCDR.CLID,(CL.FNAME+'' ''+CL.LNAME),TCDR.MOBILENO,TCDR.OPERATORTYPE,    
TCDR.OPERATORNAME,TCDR.OPERATORSERVICE,TCDR.RECHARGEAMOUNT,TCDR.RECHARGESTATUS,TCDR.TRANSACTIONID,TCDR.RECHARGEDATE,TCDR.ISANDROIDORWEB,    
ISNULL(TROP.MLMWALLET,0) AS MLMWALLET,ISNULL(TROP.CUSTOMERWALLET,0) AS CUSTOMERWALLET,    
ISNULL(TROP.ONLINEAMOUNT,0) AS PAYUMONEY,isnull(TCDR.RESPONSEREMARKS,'''')    
FROM TBL_CUSTOMER_DTH_RECHARGES TCDR     
LEFT JOIN TBL_CUSTOMERLOGIN CL ON CL.CLID=TCDR.CLID     
LEFT JOIN TBL_RECHARGEONLINEPAYMENTSDETAILS TROP ON TCDR.TRANSACTIONID=TROP.TRANSID    
WHERE ISNULL(TCDR.RECHARGESTATUS,0)=''' || CAST(v_status AS VARCHAR(100)) || '''     
AND TCDR.CLID=''' || CAST(v_clid AS VARCHAR(100)) || ''' ';
  v_query := v_query || ' INSERT INTO #TEMP SELECT TCER.TCERID,TCER.CLID,(CL.FNAME+'' ''+CL.LNAME),TCER.MOBILENO,TCER.OPERATORTYPE,    
TCER.OPERATORNAME,TCER.OPERATORSERVICE,TCER.RECHARGEAMOUNT,TCER.RECHARGESTATUS,TCER.TRANSACTIONID,TCER.RECHARGEDATE,TCER.ISANDROIDORWEB,      
ISNULL(TROP.MLMWALLET,0) AS MLMWALLET,ISNULL(TROP.CUSTOMERWALLET,0) AS CUSTOMERWALLET,    
ISNULL(TROP.ONLINEAMOUNT,0) AS PAYUMONEY,isnull(TCER.RESPONSEREMARKS,'''')    
FROM TBL_CUSTOMER_ELECTRICITY_RECHARGES TCER    
LEFT JOIN TBL_CUSTOMERLOGIN CL ON CL.CLID=TCER.CLID    
LEFT JOIN TBL_RECHARGEONLINEPAYMENTSDETAILS TROP ON TCER.TRANSACTIONID=TROP.TRANSID    
WHERE ISNULL(TCER.RECHARGESTATUS,0)=''' || CAST(v_status AS VARCHAR(100)) || '''    
AND TCER.CLID=''' || CAST(v_clid AS VARCHAR(100)) || ''' ';
  v_query := v_query || ' INSERT INTO #TEMP SELECT TCGR.TCGRID,TCGR.CLID,(CL.FNAME+'' ''+CL.LNAME),TCGR.MOBILENO,TCGR.OPERATORTYPE,    
TCGR.OPERATORNAME,TCGR.OPERATORSERVICE,TCGR.RECHARGEAMOUNT,TCGR.RECHARGESTATUS,TCGR.TRANSACTIONID,TCGR.RECHARGEDATE,TCGR.ISANDROIDORWEB,     
ISNULL(TROP.MLMWALLET,0) AS MLMWALLET,ISNULL(TROP.CUSTOMERWALLET,0) AS CUSTOMERWALLET,    
ISNULL(TROP.ONLINEAMOUNT,0) AS PAYUMONEY,ISNULL(TCGR.RESPONSEREMARKS,'''')    
FROM TBL_CUSTOMER_GAS_RECHARGES TCGR    
LEFT JOIN  TBL_CUSTOMERLOGIN CL ON CL.CLID=TCGR.CLID     
LEFT JOIN TBL_RECHARGEONLINEPAYMENTSDETAILS TROP ON TCGR.TRANSACTIONID=TROP.TRANSID    
WHERE ISNULL(TCGR.RECHARGESTATUS,0)=''' || CAST(v_status AS VARCHAR(100)) || '''     
AND TCGR.CLID=''' || CAST(v_clid AS VARCHAR(100)) || ''' ';
  v_query := v_query || ' INSERT INTO #TEMP SELECT TCGR.TCIRID,TCGR.CLID,(CL.FNAME+'' ''+CL.LNAME),TCGR.MOBILENO,TCGR.OPERATORTYPE,    
TCGR.OPERATORNAME,TCGR.OPERATORSERVICE,TCGR.RECHARGEAMOUNT,TCGR.RECHARGESTATUS,TCGR.TRANSACTIONID,TCGR.RECHARGEDATE,TCGR.ISANDROIDORWEB,    
ISNULL(TROP.MLMWALLET,0) AS MLMWALLET,ISNULL(TROP.CUSTOMERWALLET,0) AS CUSTOMERWALLET,    
ISNULL(TROP.ONLINEAMOUNT,0) AS PAYUMONEY,ISNULL(TCGR.RESPONSEREMARKS,'''')    
FROM TBL_CUSTOMER_INSURANCE_RECHARGES TCGR    
LEFT JOIN  TBL_CUSTOMERLOGIN CL ON CL.CLID=TCGR.CLID     
LEFT JOIN TBL_RECHARGEONLINEPAYMENTSDETAILS TROP ON TCGR.TRANSACTIONID=TROP.TRANSID    
WHERE ISNULL(TCGR.RECHARGESTATUS,0)=''' || CAST(v_status AS VARCHAR(100)) || '''    
AND TCGR.CLID=''' || CAST(v_clid AS VARCHAR(100)) || ''' ';
  EXECUTE v_query;
  RAISE NOTICE '%', v_query;
  v_query := '';
  v_query := 'SELECT ROWNUMBER,ID,CLID,NAME,MOBILENO,OPERATORTYPE,OPERRATORNAME,OPERATORSERVICE,AMOUNT,STATUS,TRANSACTIONID,RECHARGEDATE,ISANDROIDORWEB,MLMWALLET,CUSTOMERWALLET,PAYUMONEY,REMARKS  INTO #MAINDATA FROM #TEMP WHERE 1=1 ';
  IF ((v_fromdate <> '') AND (v_todate = '')) THEN
  v_condition := v_condition || (' AND CONVERT(DATE,RECHARGEDATE,105) BETWEEN  CONVERT(DATE, ''' || v_fromdate || ''',105) AND  CONVERT(DATE, DBO.FUN_GETCURRENTDATE(),105)');
  END IF;
  IF ((v_fromdate = '') AND (v_todate <> '')) THEN
  v_condition := v_condition || ('AND CONVERT(DATE, RECHARGEDATE, 105) BETWEEN  CONVERT(DATE, ''' || v_todate || ''', 105) AND  CONVERT(DATE, DBO.FUN_GETCURRENTDATE(), 105)');
  END IF;
  IF ((v_fromdate <> '') AND (v_todate <> '')) THEN
  v_condition := v_condition || ('AND CONVERT(DATE, RECHARGEDATE, 105) BETWEEN  CONVERT(DATE, ''' || v_fromdate || ''', 105) AND  CONVERT(DATE, ''' || v_todate || ''', 105)');
  END IF;
  IF (v_rechargetype <> '') THEN
  v_condition := v_condition || ' AND OPERATORTYPE LIKE ''%' || v_rechargetype || '%'' ';
  END IF;
  IF (v_operatorwise <> '') THEN
  v_condition := v_condition || ' AND OPERRATORNAME LIKE ''%' || v_operatorwise || '%'' ';
  END IF;
  IF (v_transid <> '') THEN
  v_condition := v_condition || ' AND TRANSACTIONID LIKE ''%' || v_transid || '%'' ';
  END IF;
  v_condition := v_condition || ' ORDER BY CONVERT(VARCHAR,RECHARGEDATE,105) DESC  ';
  v_query := v_query || v_condition || ' ;SELECT  *  FROM #MAINDATA WHERE ROWNUMBER BETWEEN ' || CAST(v_minindex AS VARCHAR(70)) || ' AND ' || CAST(v_maxindex AS VARCHAR(70)) || ' ORDER BY CONVERT(VARCHAR,RECHARGEDATE,105) DESC ';
  v_parmdefinition := N'@TOTALCOUNT NVARCHAR(70) OUTPUT';
  v_countquery := ' ;SELECT @TOTALCOUNT=COUNT(1) FROM #TEMP ';
  EXECUTE v_countquery;
  EXECUTE v_query;
  RAISE NOTICE '%', v_query;
  DROP TABLE IF EXISTS tmp_temp;
  -- SET option (removed)
  -- COMMIT (removed)
END;
$$;


--
-- Name: usp_get_customerbvdetails(integer, integer, integer, character varying, character varying, integer, character varying, character varying, character varying, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_get_customerbvdetails(v_mode integer DEFAULT 0, v_startrowindex integer DEFAULT 1, v_maxrows integer DEFAULT 100, v_fromdate character varying DEFAULT ''::character varying, v_todate character varying DEFAULT ''::character varying, v_totalcount integer DEFAULT 0, v_searchfield character varying DEFAULT ''::character varying, v_searchvalue character varying DEFAULT ''::character varying, v_status character varying DEFAULT ''::character varying, v_clid integer DEFAULT 1) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_minindex INT;
  v_maxindex INT;
  v_query text;
BEGIN
  v_minindex := (v_startrowindex - 1) * v_maxrows + 1;
  v_maxindex := v_startrowindex * v_maxrows;
  IF (v_mode = 0) THEN
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp (ROWNUMBER BIGINT GENERATED BY DEFAULT AS IDENTITY,
	RESELLERNAME VARCHAR(100), 
	CUSTOMERNAME VARCHAR(100),       
	ORDERID VARCHAR(100),         
	ORDER_NETAMT DECIMAL(18,2),	
	ORDERDATE VARCHAR(100),
	ORDER_BV DECIMAL(18,2),
	Relased int,
	ISDistributed int) ON COMMIT DROP;
  v_query := 'INSERT INTO #TEMP SELECT DM.COMPANYNAME,(CL.FNAME+'' ''+CL.LNAME),POM.ORDERID,
 POM.Total_Purchase_Cost,OM.ORDERDATE,POM.Total_BV,isnull(RRD.ISADMINRELEASE,0) as Relased,
 isnull(RRD.ISRESELLERRELEASE,0) as ISDistributed
FROM TBL_PRODUCT_ORDER_MASTER POM
Left join tbl_order_master OM ON POM.OrderId=OM.OrderID
LEFT JOIN TBL_CUSTOMERLOGIN CL ON POM.LOGINID=CL.LOGINID
LEFT JOIN DISTRIBUTOR_MASTER DM ON CL.DID=DM.PMID
INNER JOIN TBL_RESELLERRELEASEBVDETAILS AS RRD ON RRD.ORDERNO= POM.ORDERNO
WHERE OM.INTSTATUS=6 and CL.Clid=''' || CAST(v_clid AS VARCHAR(30)) || '''';
  IF ((v_fromdate <> '') AND (v_todate = '')) THEN
  v_query := v_query || ' AND CONVERT(DATE, OM.ORDERDATE, 105) BETWEEN  CONVERT(DATE, ''' || v_fromdate || ''', 105) AND  CONVERT(DATE, DBO.FUN_GETCURRENTDATE(), 105)';
  END IF;
  IF ((v_fromdate = '') AND (v_todate <> '')) THEN
  v_query := v_query || 'AND CONVERT(DATE, OM.ORDERDATE, 105) BETWEEN  CONVERT(DATE, ''' || v_todate || ''', 105) AND  CONVERT(DATE, DBO.FUN_GETCURRENTDATE(), 105)';
  END IF;
  IF ((v_fromdate <> '') AND (v_todate <> '')) THEN
  v_query := v_query || 'AND CONVERT(DATE, OM.ORDERDATE, 105) BETWEEN CONVERT(DATE, ''' || v_fromdate || ''', 105) AND  CONVERT(DATE, ''' || v_todate || ''', 105)';
  END IF;
  IF (v_searchfield = 'NAME') THEN
  v_query := v_query || ' AND (CL.FNAME+CL.LNAME) LIKE ''%' || v_searchvalue || '%'' ';
  END IF;
  IF (v_searchfield = 'ORDERID') THEN
  v_query := v_query || ' AND POM.ORDERID LIKE ''%' || v_searchvalue || '%'' ';
  END IF;
  v_query := v_query || ' ORDER BY OM.ORDERDATE DESC';
  EXECUTE v_query;
  RAISE NOTICE '%', v_query;
  RETURN QUERY SELECT * FROM tmp_temp WHERE rownumber BETWEEN v_minindex AND v_maxindex;
  SELECT COUNT(rownumber) INTO v_totalcount FROM tmp_temp;
  DROP TABLE IF EXISTS tmp_temp;
  -- SET option (removed)
  END IF;
END;
$$;


--
-- Name: usp_get_customertotalbv(integer, numeric, numeric); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_get_customertotalbv(v_clid integer DEFAULT 1, v_totalbv numeric DEFAULT 0, v_releasedbv numeric DEFAULT 0) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_minindex INT;
  v_maxindex INT;
  v_query text;
BEGIN
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp (ROWNUMBER BIGINT GENERATED BY DEFAULT AS IDENTITY,
	RESELLERNAME VARCHAR(100), 
	CUSTOMERNAME VARCHAR(100),       
	ORDERID VARCHAR(100),         
	ORDER_NETAMT DECIMAL(18,2),	
	ORDERDATE VARCHAR(100),
	ORDER_BV DECIMAL(18,2),
	Relased int,
	ISDistributed int) ON COMMIT DROP;
  v_query := 'INSERT INTO #TEMP SELECT DM.COMPANYNAME,(CL.FNAME+'' ''+CL.LNAME),POM.ORDERID,
 POM.Total_Purchase_Cost,OM.ORDERDATE,POM.Total_BV,isnull(RRD.ISADMINRELEASE,0) as Relased,
 isnull(RRD.ISRESELLERRELEASE,0) as ISDistributed
FROM TBL_PRODUCT_ORDER_MASTER POM
Left join tbl_order_master OM ON POM.OrderId=OM.OrderID
LEFT JOIN TBL_CUSTOMERLOGIN CL ON POM.LOGINID=CL.LOGINID
LEFT JOIN DISTRIBUTOR_MASTER DM ON CL.DID=DM.PMID
INNER JOIN TBL_RESELLERRELEASEBVDETAILS AS RRD ON RRD.ORDERNO= POM.ORDERNO
WHERE OM.INTSTATUS=6 and CL.Clid=''' || CAST(v_clid AS VARCHAR(30)) || '''';
  EXECUTE v_query;
  RAISE NOTICE '%', v_query;
  RETURN QUERY SELECT 1;
  SELECT COALESCE(SUM(order_bv), 0), COALESCE(SUM(relased), 0) INTO v_totalbv, v_releasedbv FROM tmp_temp;
  DROP TABLE IF EXISTS tmp_temp;
  -- SET option (removed)
END;
$$;


--
-- Name: usp_get_emailauthentication(integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_get_emailauthentication(v_did integer DEFAULT 8) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
BEGIN
  RETURN QUERY SELECT COALESCE(tcs.companyredirect, '') AS companyurl, COALESCE(dm.companyname, '') AS companyname, COALESCE(tcs.companysupportemailid, '') AS companysupportemailid, COALESCE(dm.companyimage, '') AS companyimage, COALESCE(tcs.companyfacebooklink, '') AS companyfacebooklink, COALESCE(tcs.companygooglepluslink, '') AS companygooglepluslink, COALESCE(tcs.companytwitterlink, '') AS companytwitterlink, COALESCE(tcs.companypinterestlink, '') AS companypinterestlink, COALESCE(tcs.companylinkedinlink, '') AS companylinkedinlink, COALESCE(tcs.companyinfoemailid, '') AS companyinfoemailid FROM distributor_master AS dm LEFT JOIN tbl_companysettings AS tcs ON tcs.pmid = dm.plid WHERE tcs.pmid = v_did;
END;
$$;


