--
-- Name: usp_get_franchisee_referalcommission_deatils(integer, integer, integer, integer, character varying, character varying, character varying, character varying, integer, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_get_franchisee_referalcommission_deatils(v_id integer DEFAULT 0, v_type integer DEFAULT 0, v_startrowindex integer DEFAULT 1, v_maxrows integer DEFAULT 100, v_searchfield character varying DEFAULT ''::character varying, v_searchvalue character varying DEFAULT ''::character varying, v_fromdate character varying DEFAULT ''::character varying, v_todate character varying DEFAULT ''::character varying, v_totalcount integer DEFAULT 0, v_did integer DEFAULT 0) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_gstamount DECIMAL(18,2);
  v_minindex INT;
  v_maxindex INT;
  v_query text;
BEGIN
  v_gstamount := 0;
  v_minindex := (v_startrowindex - 1) * v_maxrows + 1;
  v_maxindex := v_startrowindex * v_maxrows;
  SELECT COALESCE(limits, 0) INTO v_gstamount FROM settings WHERE sid = 22;
  DROP TABLE IF EXISTS tmp_merchantinvoices;
  CREATE TEMP TABLE tmp_merchantinvoices (ROWNUMBER INT GENERATED BY DEFAULT AS IDENTITY,    
EMAILID Varchar(100),    
DATE timestamp,    
MERCHANTNAME VARCHAR(500),    
MERCHANTEMAILID VARCHAR(150),    
GROSSAMOUNT DECIMAL(18,8),    
MERCHANTPACKAGE VARCHAR(500),    
COMM_PER  DECIMAL(18,8),    
COMMISSION DECIMAL(18,8),    
Wallet VARCHAR(50),    
ExchangeStatus Varchar(100)) ON COMMIT DROP;
  v_query := ' INSERT INTO #MERCHANTINVOICES SELECT TD.EMAILID,RC.DATE,PL1.FNAME AS MERCHANTNAME,PL1.EMAILID AS MERCHANTEMAILID,    
RC.GROSSAMOUNT,MP.NAME AS MERCHANTPACKAGE,RC.COMM_PER,    
(CASE WHEN RC.COIN>0 THEN RC.COIN WHEN RC.FIETCURRENCY>0 THEN RC.FIETCURRENCY ELSE 0.00 END)As COMMISSION,    
Wallet,(CASE WHEN IsCreditedOnExchange=1 THEN ''Credited'' WHEN IsCreditedOnExchange=2 THEN ''Rejected'' Else ''Pending'' END)As ExchangeStatus    
FROM TBL_REFERALCOMMISSION AS RC          
INNER JOIN TBL_DISTRIBUTOR AS TD ON RC.TOID=TD.LOGINID    
LEFT JOIN TBL_MERCHANTPACKEAGES AS MP ON MP.MPID=RC.PACKAGEID        
LEFT JOIN PORTAL_LOGIN AS PL1 ON RC.FROMID=PL1.LOGINID    
WHERE RC.STATUS=1 AND RC.DID<>0';
  IF (v_did <> 0) THEN
  v_query := v_query || (' AND RC.DID=' || CAST(v_did AS VARCHAR(10)));
  END IF;
  IF (v_did <> 0) THEN
  v_query := v_query || (' AND PL1.DID=' || CAST(v_did AS VARCHAR(10)));
  END IF;
  IF (v_searchfield = 'EMAIL') THEN
  v_query := v_query || (' AND PL1.EMAILID=''' || v_searchvalue || '''');
  END IF;
  IF (v_searchfield = 'Package') THEN
  v_query := v_query || (' AND MP.NAME=''' || v_searchvalue || '''');
  END IF;
  IF (v_fromdate <> '' AND v_todate = '') THEN
  v_query := v_query || (' AND CONVERT(DATE,RC.DATE,105) = CONVERT(DATE,''' || v_fromdate || ''',105) ');
  END IF;
  IF (v_fromdate = '' AND v_todate <> '') THEN
  v_query := v_query || (' AND CONVERT(DATE,RC.DATE,105) = CONVERT(DATE,''' || v_todate || ''',105) ');
  END IF;
  IF (v_fromdate <> '' AND v_todate <> '') THEN
  v_query := v_query || (' AND CONVERT(DATE,RC.DATE,105) BETWEEN CONVERT(DATE,''' || v_fromdate || ''',105) AND CONVERT(DATE,''' || v_todate || ''',105)');
  END IF;
  RAISE NOTICE '%', v_query;
  EXECUTE v_query;
  RETURN QUERY SELECT DISTINCT * FROM tmp_merchantinvoices WHERE rownumber BETWEEN v_minindex AND v_maxindex;
  SELECT COUNT(rownumber) INTO v_totalcount FROM tmp_merchantinvoices;
  DROP TABLE IF EXISTS tmp_merchantinvoices;
END;
$$;


--
-- Name: usp_get_incomplete_kyc(integer, integer, character varying, character varying, character varying, character varying, character varying, integer, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_get_incomplete_kyc(v_startrowindex integer DEFAULT 1, v_maxrows integer DEFAULT 100, v_name character varying DEFAULT ''::character varying, v_mobile character varying DEFAULT ''::character varying, v_email character varying DEFAULT ''::character varying, v_fromdate character varying DEFAULT ''::character varying, v_todate character varying DEFAULT ''::character varying, v_recordcount integer DEFAULT 0, v_merchantrelatedto integer DEFAULT 0) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_query text;
  v_count INT;
  v_regno INT;
BEGIN
  v_query := '';
  v_count := 0;
  v_regno := 0;
  DROP TABLE IF EXISTS tmp_temptable;
  CREATE TEMP TABLE tmp_temptable (ROWNUMBER INT GENERATED BY DEFAULT AS IDENTITY,    
REGNO INT,    
NAME VARCHAR(2000),    
COMPNAYNAME VARCHAR (2000),    
MOBILE VARCHAR(200),    
EMAILID VARCHAR(1000),    
REQUESTDATE VARCHAR(50),    
ENTITYTYPE INT,    
CATID VARCHAR(8000),    
ISKYCPPROVED INT,    
RELEATEDTO INT) ON COMMIT DROP;
  v_query := 'INSERT INTO #TEMPTABLE SELECT DISTINCT PL.PLID,PL.USERNAME,    
ISNULL(PM.COMPANYNAME,'''')COMPANYNAME,PL.PHONE,PL.EMAILID,ISNULL(CONVERT(VARCHAR(20),PM.DOC,103),''N/A'')DOC,     
ISNULL(BKD.EntityType,0)EntityType,ISNULL(PM.CATID,'''')CATID,PL.iskycapproved,ISNULL(PL.MerchantRelatedTo,0) AS RELEATEDTO FROM   
PORTAL_LOGIN PL LEFT JOIN PORTAL_MASTER PM ON PL.PLID=PM.PLID    
LEFT JOIN Tbl_BusinessKycDetails BKD ON BKD.PLID= PL.PLID WHERE PL.iskycapproved <>1';
  IF (v_name <> '') THEN
  v_query := v_query || (' AND PM.COMPANYNAME LIKE ''%' || v_name || '%''');
  END IF;
  IF (v_mobile <> '') THEN
  v_query := v_query || ' AND PHONE LIKE ''%' || v_mobile || '%''';
  END IF;
  IF (v_email <> '') THEN
  v_query := v_query || ' AND EMAILID LIKE ''%' || v_email || '%''';
  END IF;
  IF (v_fromdate <> '' AND v_todate <> '') THEN
  v_query := v_query || '  AND CONVERT(VARCHAR(20), PM.DOC)  >= CONVERT(VARCHAR(20),''' || v_fromdate || ''')      
 AND CONVERT(VARCHAR(20), PM.DOC) <= CONVERT(VARCHAR(20),''' || v_todate || ''')';
  ELSE
  IF (v_fromdate <> '') THEN
  v_query := v_query || '  AND CONVERT(VARCHAR(20), PM.DOC) = CONVERT(VARCHAR(20),''' || v_fromdate || ''')';
  ELSE
  IF (v_todate <> '') THEN
  v_query := v_query || '  AND CONVERT(VARCHAR(20), PM.DOC) = CONVERT(VARCHAR(20),''' || v_todate || ''')';
  END IF;
  END IF;
  END IF;
  EXECUTE v_query;
  RETURN QUERY SELECT rownumber, regno, name, compnayname, mobile, emailid, requestdate, entitytype, catid, iskycpproved, releatedto FROM tmp_temptable WHERE rownumber BETWEEN v_startrowindex AND v_maxrows;
  SELECT COUNT(1) INTO v_recordcount FROM tmp_temptable;
  DROP TABLE IF EXISTS tmp_temptable;
END;
$$;


--
-- Name: usp_get_kycstatusbyregno(integer, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_get_kycstatusbyregno(v_regno integer DEFAULT 0, v_int_total_count integer DEFAULT 0) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF EXISTS(SELECT regno FROM kyc WHERE regno = v_regno) THEN
  RETURN QUERY SELECT (CASE WHEN (SELECT COUNT(regno) FROM kyc WHERE regno = v_regno AND isaprove = 2) >= 1 THEN 'Rejected' WHEN (SELECT COUNT(regno) FROM kyc WHERE regno = v_regno AND isaprove = 0) >= 1 THEN 'Pending' WHEN (SELECT COUNT(regno) FROM kyc WHERE regno = v_regno AND isaprove = 1) >= 4 THEN 'Verified' ELSE 'Pending' END) AS kycstatus FROM member_master AS mm WHERE mm.regno IN (SELECT regno FROM kyc WHERE regno = v_regno);
  ELSE
  RETURN QUERY SELECT 'Not Verified' AS kycstatus;
  END IF;
END;
$$;


--
-- Name: usp_get_lastrecord_customer_bank_history(integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_get_lastrecord_customer_bank_history(v_tcttbid integer DEFAULT 0) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_clid BIGINT;
BEGIN
  BEGIN
  SELECT clid INTO v_clid FROM tbl_customer_transfertobankhistory WHERE tcttbid = v_tcttbid;
  RETURN QUERY SELECT CAST(TO_CHAR(wh.withdrawaldate, 'DD-MM-YYYY') AS VARCHAR(50)) AS date, cl.username, cl.phone, wh.withdrawalamount AS withdrawlpoints, COALESCE(wh.accountholdername, '') AS accountholdername, COALESCE(wh.accountno, '') AS accountno, COALESCE(wh.bankname, '') AS bankname, COALESCE(wh.branchname, '') AS branchname, COALESCE(wh.ifsc, '') AS ifsc, wh.ispaid AS status FROM tbl_customer_transfertobankhistory AS wh LEFT JOIN tbl_customerlogin AS cl ON cl.clid = wh.clid WHERE wh.clid = v_clid AND wh.tcttbid <> v_tcttbid AND wh.ispaid <> 0 ORDER BY wh.withdrawaldate DESC NULLS LAST LIMIT 10;
  EXCEPTION WHEN OTHERS THEN
  PERFORM dbo.sp_errorlog();
  IF (0 > 0) THEN
  -- ROLLBACK (removed)
  END IF;
  RETURN;
  END;
END;
$$;


--
-- Name: usp_get_latest_products(integer, integer, integer, character varying, text, integer, integer, integer, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_get_latest_products(v_maincatid integer DEFAULT 0, v_catid integer DEFAULT 0, v_subcatid integer DEFAULT 0, v_sorting character varying DEFAULT ''::character varying, v_querystring text DEFAULT ''::text, v_pageno integer DEFAULT 1, v_noofrows integer DEFAULT 100, v_totalcount integer DEFAULT 0, v_did integer DEFAULT 1) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
BEGIN
  BEGIN
  DROP TABLE IF EXISTS tmp_trendingproductsdata;
  CREATE TEMP TABLE tmp_trendingproductsdata ON COMMIT DROP AS SELECT DISTINCT pm.producttitle, CAST(pm.mprid AS BIGINT) AS mprid, COALESCE(CAST(pm.maincategoryid AS BIGINT), 0) AS maincategoryid, CAST(pm.subcategoryid AS BIGINT) AS subcategoryid, pm.shotdescription, pm.keyfeatures, CAST(pm.catid AS BIGINT) AS catid, pms.discountpercentage, CAST(pms.sprid AS BIGINT) AS sprid, pms.subprcode, pms.productimages, pms.actualprice, pms.sellmrp, pms.dap, COALESCE(tmc.main_cat_code, '') AS main_cat_code, COALESCE(tsb.sub_cat_code, '') AS sub_cat_code, COALESCE(c.cat_code, '') AS cat_code, CAST(0 AS BIGINT) AS rowno, '' AS productcode, '' AS fulldescription, 0 AS masterproductattriubuteid, '' AS attributetitle, '' AS attributevalue, 0 AS ratingstar, '' AS dealsids, pm.createddate AS createddate, pm.modifydate AS modifydate, 0 AS replacementday, 0 AS procurementsla, CAST(0 AS BIT) AS cashondelivery, CAST(0 AS DECIMAL(18, 8)) AS shippingcharges, 0 AS stockin, 0 AS stockout, 0 AS stocknet, CAST(0 AS BIT) AS isoutofstock, (CASE WHEN COALESCE(CAST(pms.bv AS DECIMAL(18, 8)), 0) = 0 THEN ((COALESCE(CAST((pms.dap + (pms.dap * vc.vatpercvalue) / 100) AS DECIMAL(18, 2)), 0) * COALESCE(tsb.bvper, 0)) / 100) ELSE pms.bv END) AS bv, (CASE WHEN COALESCE(CAST(pms.activationpv_per AS DECIMAL(18, 8)), 0) = 0 THEN ((COALESCE(CAST((pms.dap + (pms.dap * vc.vatpercvalue) / 100) AS DECIMAL(18, 2)), 0) * COALESCE(tsb.activationpv_per, 0)) / 100) ELSE pms.activationpv_per END) AS activationpv, (CASE WHEN COALESCE(CAST(pms.pv AS DECIMAL(18, 8)), 0) = 0 THEN ((COALESCE(CAST((pms.dap + (pms.dap * vc.vatpercvalue) / 100) AS DECIMAL(18, 2)), 0) * COALESCE(tsb.redeemcashback_per, 0)) / 100) ELSE pms.pv END) AS pv, (CASE WHEN COALESCE(CAST(pms.cashback_per AS DECIMAL(18, 8)), 0) = 0 THEN ((COALESCE(CAST((pms.dap + (pms.dap * vc.vatpercvalue) / 100) AS DECIMAL(18, 2)), 0) * COALESCE(tsb.cashback_per, 0)) / 100) ELSE pms.cashback_per END) AS cashback, CAST((pms.dap + (pms.dap * vc.vatpercvalue) / 100) AS DECIMAL(18, 2)) AS includingtax, pms.prskucode, pms.activationpv_per FROM ims_masterproduct AS pm LEFT OUTER JOIN ims_subproduct AS pms ON pms.mprid = pm.mprid LEFT OUTER JOIN ims_masterproductattribute AS pa ON pa.sprid = pms.sprid LEFT OUTER JOIN tbl_category AS c ON pm.catid = c.catid LEFT OUTER JOIN portal_login AS br ON br.plid = pm.branchid LEFT OUTER JOIN tbl_sub_category AS tsb ON pm.subcategoryid = tsb.subcatid LEFT OUTER JOIN tbl_main_category AS tmc ON tsb.maincatid = tmc.maincatid LEFT OUTER JOIN tbl_product_wise_bv_pv_setting AS tpwbvs ON tmc.maincatid = tpwbvs.maincatid AND tsb.subcatid = tpwbvs.subcatid AND c.catid = tpwbvs.catid LEFT OUTER JOIN tbl_customerlogin AS tcl ON tpwbvs.did = tcl.did LEFT OUTER JOIN tbl_vat_categories AS vc ON pms.vatcategoryid = vc.vcid WHERE br.active = 1 AND pms.isactive = 1 AND pms.isverified = 1 AND COALESCE(isverified, 0) = 1 AND tsb.status = 1 AND tmc.status = 1 AND br.status = 1 ORDER BY pm.createddate DESC NULLS LAST LIMIT 30;
  RETURN QUERY SELECT * FROM tmp_trendingproductsdata ORDER BY GEN_RANDOM_UUID() NULLS FIRST;
  v_totalcount := 30;
  -- SET option (removed)
  EXCEPTION WHEN OTHERS THEN
  v_totalcount := 0;
  END;
END;
$$;


--
-- Name: usp_get_latest_products_mobile(integer, integer, integer, character varying, text, integer, integer, integer, integer, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_get_latest_products_mobile(v_maincatid integer DEFAULT 0, v_catid integer DEFAULT 0, v_subcatid integer DEFAULT 0, v_sorting character varying DEFAULT ''::character varying, v_querystring text DEFAULT ''::text, v_pageno integer DEFAULT 1, v_noofrows integer DEFAULT 100, v_totalcount integer DEFAULT 0, v_did integer DEFAULT 1, v_getclid integer DEFAULT 0) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_dynamicurl varchar(100);
  v_merchantproductlargeimage varchar(250);
BEGIN
  BEGIN
  v_dynamicurl := '';
  v_merchantproductlargeimage := '';
  SELECT merchantimagepath, merchantproductlargeimage INTO v_dynamicurl, v_merchantproductlargeimage FROM tbl_company;
  DROP TABLE IF EXISTS tmp_trendingproductsdata;
  CREATE TEMP TABLE tmp_trendingproductsdata ON COMMIT DROP AS SELECT DISTINCT pm.producttitle AS producttitle, COALESCE(CAST(pm.maincategoryid AS BIGINT), 0) AS maincategoryid, CAST(pm.subcategoryid AS BIGINT) AS subcategoryid, CAST(pm.catid AS BIGINT) AS catid, pms.discountpercentage AS discountpercentage, CAST(pms.sprid AS BIGINT) AS sprid, pms.subprcode AS productcode, (pms.productimages) AS productimages, pms.sellmrp AS sellmrp, pms.dap, 0 AS ratingstar, pm.createddate AS createdate, CAST(0 AS DECIMAL) AS shippingcharges, CAST(0 AS BIT) AS isoutofstock, COALESCE(dcs.bv, 0) AS bv, COALESCE(dcs.cashback, 0) AS cashback FROM ims_masterproduct AS pm LEFT OUTER JOIN ims_subproduct AS pms ON pms.mprid = pm.mprid LEFT OUTER JOIN ims_masterproductattribute AS pa ON pa.sprid = pms.sprid LEFT OUTER JOIN tbl_category AS c ON pm.catid = c.catid LEFT OUTER JOIN portal_login AS br ON br.plid = pm.branchid LEFT OUTER JOIN tbl_sub_category AS tsb ON pm.subcategoryid = tsb.subcatid LEFT OUTER JOIN tbl_main_category AS tmc ON tsb.maincatid = tmc.maincatid LEFT OUTER JOIN tbl_distributor_commission_structure AS dcs ON dcs.subsubcatid = tsb.subcatid AND dcs.did = v_did WHERE br.active = 1 AND pms.isactive = 1 AND pms.isverified = 1 AND COALESCE(isverified, 0) = 1 AND tsb.status = 1 AND tmc.status = 1 AND br.status = 1 ORDER BY pm.createddate DESC NULLS LAST LIMIT 30;
  RETURN QUERY SELECT (SELECT CASE WHEN COALESCE(COUNT(1), 0) > 0 THEN 1 ELSE 0 END FROM tbl_wishlist WHERE sprid = tm.sprid AND loginid = v_getclid AND status = 1) AS wishcount, v_dynamicurl AS baseurl, * FROM tmp_trendingproductsdata AS tm ORDER BY GEN_RANDOM_UUID() NULLS FIRST;
  v_totalcount := 30;
  -- SET option (removed)
  EXCEPTION WHEN OTHERS THEN
  v_totalcount := 0;
  END;
END;
$$;


--
-- Name: usp_get_latest_products_mobile_backup26122018(integer, integer, integer, character varying, text, integer, integer, integer, integer, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_get_latest_products_mobile_backup26122018(v_maincatid integer DEFAULT 0, v_catid integer DEFAULT 0, v_subcatid integer DEFAULT 0, v_sorting character varying DEFAULT ''::character varying, v_querystring text DEFAULT ''::text, v_pageno integer DEFAULT 1, v_noofrows integer DEFAULT 100, v_totalcount integer DEFAULT 0, v_did integer DEFAULT 1, v_getclid integer DEFAULT 0) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_dynamicurl varchar(100);
  v_merchantproductlargeimage varchar(250);
BEGIN
  BEGIN
  v_dynamicurl := '';
  v_merchantproductlargeimage := '';
  SELECT merchantimagepath, merchantproductlargeimage INTO v_dynamicurl, v_merchantproductlargeimage FROM tbl_company;
  DROP TABLE IF EXISTS tmp_trendingproductsdata;
  CREATE TEMP TABLE tmp_trendingproductsdata ON COMMIT DROP AS SELECT DISTINCT pm.producttitle, CAST(pm.mprid AS BIGINT) AS mprid, COALESCE(CAST(pm.maincategoryid AS BIGINT), 0) AS maincategoryid, CAST(pm.subcategoryid AS BIGINT) AS subcategoryid, pm.shotdescription, pm.keyfeatures, CAST(pm.catid AS BIGINT) AS catid, pms.discountpercentage, CAST(pms.sprid AS BIGINT) AS sprid, pms.subprcode, (pms.productimages) AS productimages, pms.actualprice, pms.sellmrp, pms.dap, COALESCE(tmc.main_cat_code, '') AS main_cat_code, COALESCE(tsb.sub_cat_code, '') AS sub_cat_code, COALESCE(c.cat_code, '') AS cat_code, CAST(0 AS BIGINT) AS rowno, '' AS productcode, '' AS fulldescription, 0 AS masterproductattriubuteid, '' AS attributetitle, '' AS attributevalue, 0 AS ratingstar, '' AS dealsids, pm.createddate AS createddate, pm.modifydate AS modifydate, 0 AS replacementday, 0 AS procurementsla, CAST(0 AS BIT) AS cashondelivery, CAST(0 AS DECIMAL) AS shippingcharges, 0 AS stockin, 0 AS stockout, 0 AS stocknet, CAST(0 AS BIT) AS isoutofstock, CAST(0 AS DECIMAL) AS bv, CAST(0 AS DECIMAL) AS pv FROM ims_masterproduct AS pm LEFT OUTER JOIN ims_subproduct AS pms ON pms.mprid = pm.mprid LEFT OUTER JOIN ims_masterproductattribute AS pa ON pa.sprid = pms.sprid LEFT OUTER JOIN tbl_category AS c ON pm.catid = c.catid LEFT OUTER JOIN portal_login AS br ON br.plid = pm.branchid LEFT OUTER JOIN tbl_sub_category AS tsb ON pm.subcategoryid = tsb.subcatid LEFT OUTER JOIN tbl_main_category AS tmc ON tsb.maincatid = tmc.maincatid WHERE br.active = 1 AND pms.isactive = 1 AND pms.isverified = 1 AND COALESCE(isverified, 0) = 1 AND tsb.status = 1 AND tmc.status = 1 AND br.status = 1 ORDER BY pm.createddate DESC NULLS LAST LIMIT 30;
  RETURN QUERY SELECT (SELECT CASE WHEN COALESCE(COUNT(1), 0) > 0 THEN 1 ELSE 0 END FROM tbl_wishlist WHERE sprid = tm.sprid AND loginid = v_getclid AND status = 1) AS wishcount, v_dynamicurl AS baseurl, * FROM tmp_trendingproductsdata AS tm ORDER BY GEN_RANDOM_UUID() NULLS FIRST;
  v_totalcount := 30;
  -- SET option (removed)
  EXCEPTION WHEN OTHERS THEN
  v_totalcount := 0;
  END;
END;
$$;


--
-- Name: usp_get_member_details(bigint); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_get_member_details(v_regno bigint DEFAULT 0) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
BEGIN
  RETURN QUERY SELECT pl.regno, COALESCE(mm.mobile, '') AS contact, COALESCE(mm.accountno, '') AS accountno, COALESCE(mm.ifsccode, '') AS ifsccode, COALESCE(mm.bankname, '') AS bankname, COALESCE(mm.branchname, '') AS branchname, COALESCE(mm.fath_hus_name, '') AS fath_hus_name, COALESCE(mm.address, '') AS address, COALESCE(mm.statename, '') AS statename, COALESCE(mm.cityname, '') AS cityname, COALESCE(mm.pincode, '') AS pincode, COALESCE(mm.active, '') AS active, COALESCE(mm.panno, '') AS panno, (CASE WHEN mm.is_profile_status = 0 THEN 'Pending' WHEN mm.is_profile_status = 1 THEN 'Approved' WHEN mm.is_profile_status = 2 THEN 'Rejected' END) AS profilestatus, COALESCE(pl.username, '') AS username, COALESCE(pl.title, '') AS title, COALESCE(pl.fname, '') AS fname, COALESCE(pl.lname, '') AS lname, pl.loginid, COALESCE(pl.password, '') AS password, COALESCE(pl.designation, '') AS designation, COALESCE(pl.emailid, '') AS emailid, COALESCE(sb.businessname, '') AS businessname, COALESCE(sb.contactname, '') AS contactname, COALESCE(sb.phonenumber, '') AS phonenumber, COALESCE(sb.cid, '') AS cid, COALESCE(sb.sid, '') AS sid, COALESCE(sb.city, '') AS city, COALESCE(sb.address, '') AS baddress, sb.billid FROM member_master AS mm INNER JOIN portal_login AS pl ON mm.plid = pl.plid LEFT JOIN tbl_sponserbilling AS sb ON mm.plid = sb.plid WHERE mm.regno = v_regno;
END;
$$;


--
-- Name: usp_get_member_downlinelist_side_wise(character varying, integer, integer, text, text, text, text, integer, integer, integer, numeric, numeric, character varying, character varying, character varying, character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_get_member_downlinelist_side_wise(v_loginid character varying DEFAULT '1000001'::character varying, v_startrowindex integer DEFAULT 2, v_maxrows integer DEFAULT 100, v_searchfield text DEFAULT 'FNAME'::text, v_searchvalue text DEFAULT 'AshuToshSinghAwapal'::text, v_fromdate text DEFAULT ''::text, v_todate text DEFAULT ''::text, v_levenumber integer DEFAULT 0, v_side integer DEFAULT 1, v_totalcount integer DEFAULT 0, v_totallrbv numeric DEFAULT 0, v_totallrincome numeric DEFAULT 0, v_name character varying DEFAULT ''::character varying, v_username character varying DEFAULT ''::character varying, v_emailid character varying DEFAULT ''::character varying, v_sponserid character varying DEFAULT ''::character varying) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_minindex INT;
  v_maxindex INT;
  v_query text;
BEGIN
  v_minindex := (v_startrowindex - 1) * v_maxrows + 1;
  v_maxindex := v_startrowindex * v_maxrows;
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp (ROWNUMBER INT PRIMARY KEY,
LOGINID text,
SPONSERID text,
ROOTID text,
EMPLEVEL INT,
NAME text,
MOBILE text,
CITYNAME text,
REGDATE text,
STATUS  text,
EMAILID text,
DOC text,
TLBV numeric(19,4),
CLBV numeric(19,4),
TRBV numeric(19,4),
CRBV numeric(19,4),
PAIDBV numeric(19,4),
USERNAME text,
KITPRICE numeric(19,4) DEFAULT(0),
KITNAME VARCHAR(50),
INCOME numeric(19,4),
REGNO INT,
SIDE INT,
SPOUNSER_USERNAME VARCHAR(500),
ROOT_USERNAME VARCHAR(500),
LCOUNT INT,
RCOUNT INT) ON COMMIT DROP;
  -- CREATE INDEX (skipped)
  IF (v_side = 0) THEN
  v_query := 'INSERT INTO #TEMP  SELECT ROW_NUMBER() OVER(ORDER BY REGDATE ASC) AS ROWNUMBER,*  FROM FUN_ALL_DOWNLINE_MEMBERLIST(''' || v_loginid || ''') WHERE LOGINID!= '''' ';
  END IF;
  IF (v_side = 1) THEN
  v_query := 'INSERT INTO #TEMP  SELECT ROW_NUMBER() OVER(ORDER BY REGDATE ASC) AS ROWNUMBER,*  FROM FUN_ALL_DOWNLINE_MEMBERLIST_LEFT_SIDE_WITHLRCOUNT(''' || v_loginid || ''') WHERE LOGINID!='''' ';
  END IF;
  IF (v_side = 2) THEN
  v_query := 'INSERT INTO #TEMP  SELECT ROW_NUMBER() OVER(ORDER BY REGDATE ASC) AS ROWNUMBER,*  FROM FUN_ALL_DOWNLINE_MEMBERLIST_RIGHT_SIDE_WITH_LRCOUNT(''' || v_loginid || ''') WHERE LOGINID!='''' ';
  END IF;
  IF (v_searchfield <> '' AND v_searchvalue <> '') THEN
  IF (v_searchfield = 'FNAME') THEN
  v_query := v_query || ' AND NAME LIKE ''%' || v_searchvalue || '%''';
  END IF;
  IF (v_searchfield = 'LOGINID') THEN
  v_query := v_query || ' AND USERNAME LIKE ''%' || v_searchvalue || '%'' ';
  END IF;
  IF (v_searchfield = 'PNAME') THEN
  v_query := v_query || ' AND  ROOT_USERNAME LIKE ''%' || v_searchvalue || '%'' ';
  END IF;
  IF (v_searchfield = 'SNAME') THEN
  v_query := v_query || ' AND SPOUNSER_USERNAME LIKE ''%' || v_searchvalue || '%'' ';
  END IF;
  END IF;
  IF (v_name <> '') THEN
  v_query := v_query || ' AND NAME LIKE ''%' || v_name || '%''';
  END IF;
  IF (v_username <> '') THEN
  v_query := v_query || ' AND  USERNAME LIKE ''%' || v_username || '%'' ';
  END IF;
  IF (v_emailid <> '') THEN
  v_query := v_query || ' AND  EMAILID LIKE ''%' || v_emailid || '%'' ';
  END IF;
  IF (v_sponserid <> '') THEN
  v_query := v_query || ' AND  SPOUNSER_USERNAME LIKE ''%' || v_sponserid || '%'' ';
  END IF;
  IF (v_levenumber > 0) THEN
  v_query := v_query || ' AND EMPLEVEL = ' || CAST(v_levenumber AS VARCHAR(10));
  END IF;
  IF ((v_fromdate <> '') AND (v_todate = '')) THEN
  v_query := v_query || ' and convert(varchar(20),REGDATE,105) >=  ''' || v_fromdate || '''';
  END IF;
  IF ((v_fromdate = '') AND (v_todate <> '')) THEN
  v_query := v_query || ' and convert(varchar(20), REGDATE.DATE,105) <=  ''' || v_todate || '''';
  END IF;
  IF ((v_fromdate <> '') AND (v_todate <> '')) THEN
  v_query := v_query || ' and convert(varchar(20), REGDATE,105) between  ''' || v_fromdate || ''' and  ''' || v_todate || '''';
  END IF;
  v_query := v_query || '   OPTION ( MAXRECURSION 0 )';
  EXECUTE v_query;
  RETURN QUERY SELECT * FROM tmp_temp WHERE rownumber BETWEEN v_startrowindex AND v_maxrows;
  SELECT COUNT(rownumber) INTO v_totalcount FROM tmp_temp;
  RETURN QUERY SELECT COUNT(rownumber) AS totalcount FROM tmp_temp;
  IF (v_side = 1) THEN
  SELECT COALESCE(SUM(kitprice), 0) INTO v_totallrbv FROM FUN_ALL_DOWNLINE_MEMBERLIST_LEFT_SIDE('' || v_loginid || '') WHERE kitprice <> 1000;
  SELECT COALESCE(SUM(income), 0) INTO v_totallrincome FROM FUN_ALL_DOWNLINE_MEMBERLIST_LEFT_SIDE('' || v_loginid || '') WHERE kitprice <> 1000;
  END IF;
  IF (v_side = 2) THEN
  SELECT COALESCE(SUM(kitprice), 0) INTO v_totallrbv FROM FUN_ALL_DOWNLINE_MEMBERLIST_RIGHT_SIDE('' || v_loginid || '') WHERE kitprice <> 1000;
  SELECT COALESCE(SUM(income), 0) INTO v_totallrincome FROM FUN_ALL_DOWNLINE_MEMBERLIST_RIGHT_SIDE('' || v_loginid || '') WHERE kitprice <> 1000;
  END IF;
  DROP TABLE IF EXISTS tmp_temp;
  -- SET option (removed)
END;
$$;


--
-- Name: usp_get_merchant_cofig_data(character varying, integer, character varying, character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_get_merchant_cofig_data(v_flag character varying DEFAULT NULL::character varying, v_merchant_id integer DEFAULT NULL::integer, v_value character varying DEFAULT NULL::character varying, INOUT v_out_data character varying DEFAULT NULL::character varying) RETURNS character varying
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_type varchar(10);
  v_cashbackvalue decimal(18,2);
  v_amount decimal(18,2);
  v_cashback_amount decimal(18,2);
BEGIN
  IF (v_flag = 'Cashback') THEN
  SELECT cash_back_type, cash_back_value INTO v_type, v_cashbackvalue FROM dbo.merchant_configuration WHERE merchant_id = v_merchant_id LIMIT 1;
  v_amount := CAST(v_value AS DECIMAL(18, 2));
  IF (v_type = 'P') THEN
  v_cashback_amount := v_amount * (v_cashbackvalue / 100);
  ELSE
  IF (v_type = 'F') THEN
  v_cashback_amount := v_cashbackvalue;
  ELSE
  v_cashback_amount := 0;
  END IF;
  END IF;
  v_out_data := CAST(v_cashback_amount AS VARCHAR) || '^' || CAST(v_cashbackvalue AS VARCHAR) || '^' || CAST(v_type AS VARCHAR);
  END IF;
END;
$$;


--
-- Name: usp_get_merchant_list(integer, integer, character varying, boolean, character varying, character varying, character varying, character varying, text, text, character varying, character varying, character varying, character varying, integer, character varying, character varying, character varying, character varying, integer, integer, integer, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_get_merchant_list(v_startrowindex integer DEFAULT 1, v_maxrows integer DEFAULT 50, v_orderbyfield character varying DEFAULT ''::character varying, v_asc boolean DEFAULT true, v_searchfield character varying DEFAULT ''::character varying, v_searchvalue character varying DEFAULT ''::character varying, v_cid character varying DEFAULT ''::character varying, v_ctid character varying DEFAULT ''::character varying, v_catid text DEFAULT ''::text, v_keyid text DEFAULT ''::text, v_fromdate character varying DEFAULT ''::character varying, v_todate character varying DEFAULT ''::character varying, v_type character varying DEFAULT 'APPROVE'::character varying, v_isverified character varying DEFAULT ''::character varying, v_mode integer DEFAULT 1, v_prop character varying DEFAULT '0'::character varying, v_pmfromdate character varying DEFAULT ''::character varying, v_pmtodate character varying DEFAULT ''::character varying, v_status character varying DEFAULT ''::character varying, v_intresult integer DEFAULT 0, v_totalunique integer DEFAULT 0, v_totalitem integer DEFAULT 0, v_merchantrelatedto integer DEFAULT 0) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_recordcount INT;
  v_regno BIGINT;
  v_pmid INT;
  v_isroll VARCHAR(50);
  v_sqlquery text;
  v_minindex INT;
  v_maxindex INT;
BEGIN
  -- SET option (removed)
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp (ROWNUMBER BIGINT,      
PLID bigint,      
LOGINID varchar(150),      
DOC varchar(150),      
PASSWORD varchar(150),      
USERNAME varchar(150),      
MEMBERNAME varchar(150),      
IPADDRESS  varchar(150),      
EMAILID  varchar(150),      
PHONE VARCHAR(150),      
ISKYCAPPROVED INT,      
PMID  INT,      
SOURCEID VARCHAR(30),      
SOURCEJOING VARCHAR(30),      
ACTIVE INT,      
STATUS INT,      
NAME VARCHAR(150),      
ADDRESS VARCHAR(500),      
RELEATEDTO INT,    
AffiliateUserId Varchar(100),    
Package Varchar(100)) ON COMMIT DROP;
  v_sqlquery := '';
  v_minindex := (v_startrowindex - 1) * v_maxrows + 1;
  v_maxindex := v_startrowindex * v_maxrows;
  IF (v_type = '') THEN
  v_sqlquery := 'INSERT INTO #TEMP SELECT ROW_NUMBER() OVER(ORDER BY DOC DESC) AS ROWNUMBER,PLID,LOGINID,DOC,      
   PASSWORD,USERNAME,ISNULL(FNAME,'''')+''''+ISNULL(LNAME,'''') AS MEMBERNAME,ISNULL(IPADDRESS,'''') AS IPADDRESS,      
   EMAILID,PHONE,ISKYCAPPROVED,ISNULL(PMID,0) AS PMID,ISNULL(REFRAL_ID,''''),ISNULL(TFS.NAME,'''') ,PL.ACTIVE,PL.STATUS,ISNULL(PL.FNAME,'''') AS NAME,'''',    
   ISNULL(PL.MERCHANTRELATEDTO,0) AS RELEATEDTO,ISNULL(MMA.USERNAME,''N/A'') AS AffiliateId,ISNULL(SUBSCRIPTIONHEADING,''N/A'')    
   FROM PORTAL_LOGIN PL       
   LEFT JOIN TBL_TRAFFICSOURCE TFS ON PL.SOURCEID=TFS.ID      
   LEFT JOIN [Db_Affiliate].[DBO].[MEMBER_MASTER] MM ON MMA.USERNAME=PL.AffiliateUserId LEFT JOIN [Db_Affiliate].[DBO].[TBL_SUBSCRIPTIONMASTER] TSM  
   ON MMA.KID=TSM.TSMID    
   WHERE 1=1 ';
  ELSE
  v_sqlquery := 'INSERT INTO #TEMP SELECT ROW_NUMBER() OVER(ORDER BY PL.DOC DESC) AS ROWNUMBER,PL.PLID,PL.LOGINID,PL.DOC,      
   PL.PASSWORD,PL.USERNAME,ISNULL(PM.COMPANYNAME,'''') AS MEMBERNAME,ISNULL(PL.IPADDRESS,'''') AS IPADDRESS,      
   PL.EMAILID,PL.PHONE,PL.ISKYCAPPROVED,ISNULL(PL.PMID,0) AS PMID,ISNULL(PL.REFRAL_ID,''''),ISNULL(TFS.NAME,''''),PL.ACTIVE,PL.STATUS,      
   ISNULL(PL.FNAME,'''') AS NAME,ISNULL(CIT.CITYNAME,'''') AS ADDRESS,ISNULL(PL.MERCHANTRELATEDTO,0) AS RELEATEDTO,    
   ISNULL(MMA.USERNAME,''N/A'') AS AffiliateId,ISNULL(SUBSCRIPTIONHEADING,''N/A'')    
    FROM PORTAL_LOGIN PL      
    JOIN PORTAL_MASTER PM ON PM.PMID=PL.PMID       
    LEFT JOIN TBL_TRAFFICSOURCE TFS ON PL.SOURCEID=TFS.ID      
    LEFT JOIN CITY CIT ON PM.CTID=CIT.CTID      
 LEFT JOIN [Db_Affiliate].[DBO].[MEMBER_MASTER] MMA ON MMA.USERNAME=PL.AffiliateUserId LEFT JOIN [Db_Affiliate].[DBO].[TBL_SUBSCRIPTIONMASTER] TSM ON MMA.KID=TSM.TSMID      
    WHERE PL.ISKYCAPPROVED=1 AND  PL.STATUS=1 AND PL.ACTIVE=1 ';
  END IF;
  IF (v_merchantrelatedto > 0) THEN
  v_sqlquery := v_sqlquery || ' AND PL.MERCHANTRELATEDTO= ''' || CAST(v_merchantrelatedto AS VARCHAR(50)) || '''';
  END IF;
  IF (v_searchfield = 'EMAILID') THEN
  v_sqlquery := v_sqlquery || ' AND EMAILID LIKE ''%' || v_searchvalue || '%''';
  END IF;
  IF (v_type = '') THEN
  IF (v_searchfield = 'MEMBERNAME') THEN
  v_sqlquery := v_sqlquery || ' AND (FNAME+LNAME) LIKE ''%' || v_searchvalue || '%''';
  END IF;
  ELSE
  IF (v_searchfield = 'MEMBERNAME') THEN
  v_sqlquery := v_sqlquery || ' AND PM.COMPANYNAME LIKE ''%' || v_searchvalue || '%''';
  END IF;
  END IF;
  IF (v_searchfield = 'PHONE') THEN
  v_sqlquery := v_sqlquery || ' AND PHONE LIKE ''%' || v_searchvalue || '%''';
  END IF;
  IF (v_searchfield = 'LOGINID') THEN
  v_searchvalue := REPLACE(v_searchvalue, 'EM', '');
  v_sqlquery := v_sqlquery || ' AND LOGINID LIKE ''%' || v_searchvalue || '%''';
  END IF;
  IF (v_fromdate <> '' AND v_todate <> '') THEN
  v_sqlquery := v_sqlquery || (' AND CONVERT(DATE,PL.DOC,105) BETWEEN CONVERT(DATE,''' || v_fromdate || ''',105) AND CONVERT(DATE,''' || v_todate || ''',105)');
  END IF;
  IF (v_fromdate <> '') THEN
  v_sqlquery := v_sqlquery || (' AND CONVERT(DATE,PL.DOC,105) >= CONVERT(DATE,''' || v_fromdate || ''',105)');
  END IF;
  IF (v_todate <> '') THEN
  v_sqlquery := v_sqlquery || (' AND CONVERT(DATE,PL.DOC,105) <= CONVERT(DATE,''' || v_todate || ''',105)');
  END IF;
  IF (v_type = '') THEN
  IF (v_status <> '') THEN
  IF (v_status = 'APPROVE') THEN
  v_sqlquery := v_sqlquery || ' AND ISKYCAPPROVED=1';
  END IF;
  IF (v_status = 'PENDING') THEN
  v_sqlquery := v_sqlquery || ' AND ISKYCAPPROVED=0';
  END IF;
  END IF;
  END IF;
  EXECUTE v_sqlquery;
  RAISE NOTICE '%', (v_sqlquery);
  SELECT COUNT(1) INTO v_recordcount FROM tmp_temp;
  SELECT COUNT(COALESCE(rownumber, 0)) INTO v_intresult FROM tmp_temp;
  RETURN QUERY SELECT * FROM tmp_temp WHERE rownumber BETWEEN v_minindex AND v_maxindex;
  DROP TABLE IF EXISTS tmp_totalunique;
  CREATE TEMP TABLE tmp_totalunique (TOTALRECORD INT) ON COMMIT DROP;
  INSERT INTO tmp_totalunique SELECT COUNT(producttitle) FROM ims_masterproduct AS pm LEFT JOIN ims_subproduct AS sm ON pm.mprid = sm.mprid LEFT JOIN portal_login AS pl ON pl.plid = pm.branchid WHERE sm.isverified = 1 GROUP BY producttitle;
  SELECT COUNT(totalrecord) INTO v_totalunique FROM tmp_totalunique;
  SELECT COUNT(1) INTO v_totalitem FROM ims_subproduct AS sm LEFT JOIN ims_masterproduct AS pm ON sm.mprid = pm.mprid LEFT JOIN portal_login AS pl ON pl.plid = pm.branchid WHERE sm.isverified = 1;
  DROP TABLE IF EXISTS tmp_temp;
  DROP TABLE IF EXISTS tmp_totalunique;
  -- SET option (removed)
END;
$$;


--
-- Name: usp_get_merchant_notifications(bigint, character varying, character varying, character varying, character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_get_merchant_notifications(v_plid bigint DEFAULT 1, INOUT v_message character varying DEFAULT 'NO REVIEWS'::character varying, v_fromdate character varying DEFAULT ''::character varying, v_todate character varying DEFAULT ''::character varying, v_notificationtype character varying DEFAULT ''::character varying) RETURNS character varying
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_minindex INT;
  v_maxindex INT;
  v_query text;
BEGIN
  v_query := 'select TMNID,TMN.TMNTID,TMN.PLID,NOTIFICATIONDESCRIPTION,CONVERT(varchar(50),NOTIFICATIONDATE,107) as NOTIFICATIONDATE,REFERENCEID,ISREAD,
TMN.ACTIVE,ISNULL(Prod_Images,'''')  AS Prod_Images,CONVERT(varchar(50),TMN.CREATEDATE+7,107) as Expecteddelivery,
  ISNULL(POM.OrderId,'''') AS OrderId,ISNULL(POM.STATUS,'''') AS STATUS,ISNULL(POM.INTSTATUS,0) AS INTSTATUS,NOTIFICATIONTYPE,ISNULL(Product_Qty,0) AS Product_Qty,
  isnull(Product_Name,'''') AS Product_Name,ISNULL(POM.Status,'''') AS OrderStatus  from TBL_MERCHANT_NOTIFICATIONS TMN 
  left join tbl_product_order_master POM on POM.Orderno=TMN.REFERENCEID
 left join TBL_MERCHANT_NOTIFICATIONS_TYPE MNT ON MNT.TMNTID=TMN.TMNTID  WHERE  TMN.ACTIVE=1  ';
  IF ((v_fromdate <> '') AND (v_todate = '')) THEN
  v_query := v_query || ' AND convert(varchar, CONVERT(DATE, TMN.NOTIFICATIONDATE, 105) ) BETWEEN  CONVERT(DATE, ''' || v_fromdate || ''', 105) AND  CONVERT(DATE, DBO.FUN_GETCURRENTDATE(), 105)';
  END IF;
  IF ((v_fromdate = '') AND (v_todate <> '')) THEN
  v_query := v_query || 'AND CONVERT(DATE, TMN.NOTIFICATIONDATE, 105) BETWEEN  CONVERT(DATE, ''' || v_todate || ''', 105) AND  CONVERT(DATE, DBO.FUN_GETCURRENTDATE(), 105)';
  END IF;
  IF ((v_fromdate <> '') AND (v_todate <> '')) THEN
  v_query := v_query || 'AND CONVERT(DATE, TMN.NOTIFICATIONDATE, 105) BETWEEN CONVERT(DATE, ''' || v_fromdate || ''', 105) AND  CONVERT(DATE, ''' || v_todate || ''', 105)';
  END IF;
  IF (v_notificationtype <> '') THEN
  v_query := v_query || ' AND MNT.NOTIFICATIONTYPE=''' || v_notificationtype || '''';
  END IF;
  IF (v_plid > 0) THEN
  v_query := v_query || ' AND TMN.PLID=' || CAST(v_plid AS VARCHAR(20)) || '';
  END IF;
  IF ((v_fromdate = '') AND (v_todate = '')) THEN
  v_query := v_query || ' ' || 'order by NOTIFICATIONDATE desc';
  END IF;
  EXECUTE v_query;
  -- SET option (removed)
END;
$$;


--
-- Name: usp_get_merchantallinvoices(integer, integer, integer, character varying, character varying, character varying, character varying, character varying, integer, integer, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_get_merchantallinvoices(v_plid integer DEFAULT 36, v_startrowindex integer DEFAULT 1, v_maxrows integer DEFAULT 50, v_invoiceno character varying DEFAULT ''::character varying, v_orderid character varying DEFAULT ''::character varying, v_invoicetype character varying DEFAULT ''::character varying, v_fromdate character varying DEFAULT ''::character varying, v_todate character varying DEFAULT ''::character varying, v_totalcount integer DEFAULT 0, v_did integer DEFAULT 0, v_searchbusinesstype integer DEFAULT 0) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_gstamount DECIMAL(18,2);
  v_minindex INT;
  v_maxindex INT;
  v_query text;
BEGIN
  v_gstamount := 0;
  v_minindex := (v_startrowindex - 1) * v_maxrows + 1;
  v_maxindex := v_startrowindex * v_maxrows;
  SELECT COALESCE(limits, 0) INTO v_gstamount FROM settings WHERE sid = 22;
  DROP TABLE IF EXISTS tmp_merchantinvoices;
  CREATE TEMP TABLE tmp_merchantinvoices (ROWNUMBER INT GENERATED BY DEFAULT AS IDENTITY NOT NULL,  
  TEMPDATETIME timestamp,  
  TMCIID INT,  
  TMSIID INT,  
  INVOICETYPE VARCHAR(50),  
  ORDERID VARCHAR(100),  
  INVOICENO VARCHAR(100),  
  INVOICEDATE VARCHAR(50),  
  ACTIVE INT,  
  TOTALAMOUNT Decimal(18,2),  
  MerchantName VARCHAR(100),  
  MerchantEmailId VARCHAR(100)) ON COMMIT DROP;
  IF (v_did = 0) THEN
  INSERT INTO tmp_merchantinvoices SELECT DISTINCT CAST(invoicedate AS TIMESTAMP), COALESCE(invoice.tmciid, 0) AS tmciid, 0 AS tmsiid, 'COMMISSION' AS invoicetype, COALESCE(invoice.orderid, '') AS orderid, COALESCE(invoice.invoiceno, '') AS invoiceno, CAST(TO_CHAR(COALESCE(invoice.invoicedate, ''), 'TMMon DD YYYY FMHH12:MI%p') AS VARCHAR(30)) AS invoicedate, COALESCE(invoice.active, 0) AS active, ((tmc.taxableamount * tmc.admincharges) / 100 + tmc.handlingcharges + (tmc.taxableamount * tmc.fixedcharges) / 100) + (((tmc.taxableamount * tmc.admincharges) / 100 + tmc.handlingcharges + (tmc.taxableamount * tmc.fixedcharges) / 100) * (tmc.cgstrate + tmc.sgstrate + tmc.igstrate)) / 100, '', '' FROM dbo.tbl_merchant_commissioninvoices AS invoice LEFT JOIN dbo.tbl_merchant_commissioninvoices_details AS tmc ON invoice.tmciid = tmc.tmciid WHERE invoice.plid = v_plid ORDER BY CAST(invoicedate AS TIMESTAMP) DESC NULLS LAST;
  ELSE
  IF (v_did <> 0) THEN
  IF (v_searchbusinesstype = 0) THEN
  INSERT INTO tmp_merchantinvoices SELECT DISTINCT CAST(invoicedate AS TIMESTAMP), COALESCE(invoice.tmciid, 0) AS tmciid, 0 AS tmsiid, 'COMMISSION' AS invoicetype, COALESCE(invoice.orderid, '') AS orderid, COALESCE(invoice.invoiceno, '') AS invoiceno, CAST(TO_CHAR(COALESCE(invoice.invoicedate, ''), 'TMMon DD YYYY FMHH12:MI%p') AS VARCHAR(30)) AS invoicedate, COALESCE(invoice.active, 0) AS active, ((tmc.taxableamount * tmc.admincharges) / 100 + tmc.handlingcharges + (tmc.taxableamount * tmc.fixedcharges) / 100) + (((tmc.taxableamount * tmc.admincharges) / 100 + tmc.handlingcharges + (tmc.taxableamount * tmc.fixedcharges) / 100) * (tmc.cgstrate + tmc.sgstrate + tmc.igstrate)) / 100, COALESCE(pm.companyname, COALESCE(pl.fname, '')), pl.emailid FROM dbo.tbl_merchant_commissioninvoices AS invoice LEFT JOIN dbo.tbl_merchant_commissioninvoices_details AS tmc ON invoice.tmciid = tmc.tmciid LEFT JOIN portal_login AS pl ON pl.plid = invoice.plid LEFT JOIN portal_master AS pm ON pm.plid = pl.plid WHERE pl.plid IN (SELECT plid FROM portal_master WHERE cid IN (SELECT cid FROM distributor_master WHERE plid = v_did)) ORDER BY CAST(invoicedate AS TIMESTAMP) DESC NULLS LAST;
  ELSE
  INSERT INTO tmp_merchantinvoices SELECT DISTINCT CAST(invoicedate AS TIMESTAMP), COALESCE(invoice.tmciid, 0) AS tmciid, 0 AS tmsiid, 'COMMISSION' AS invoicetype, COALESCE(invoice.orderid, '') AS orderid, COALESCE(invoice.invoiceno, '') AS invoiceno, CAST(TO_CHAR(COALESCE(invoice.invoicedate, ''), 'TMMon DD YYYY FMHH12:MI%p') AS VARCHAR(30)) AS invoicedate, COALESCE(invoice.active, 0) AS active, ((tmc.taxableamount * tmc.admincharges) / 100 + tmc.handlingcharges + (tmc.taxableamount * tmc.fixedcharges) / 100) + (((tmc.taxableamount * tmc.admincharges) / 100 + tmc.handlingcharges + (tmc.taxableamount * tmc.fixedcharges) / 100) * (tmc.cgstrate + tmc.sgstrate + tmc.igstrate)) / 100, COALESCE(pm.companyname, COALESCE(pl.fname, '')), pl.emailid FROM dbo.tbl_merchant_commissioninvoices AS invoice LEFT JOIN dbo.tbl_merchant_commissioninvoices_details AS tmc ON invoice.tmciid = tmc.tmciid LEFT JOIN portal_login AS pl ON pl.plid = invoice.plid LEFT JOIN portal_master AS pm ON pm.plid = pl.plid WHERE pl.plid IN (SELECT plid FROM portal_master WHERE cid IN (SELECT cid FROM distributor_master WHERE plid = v_did)) AND pm.businesstype = v_searchbusinesstype ORDER BY CAST(invoicedate AS TIMESTAMP) DESC NULLS LAST;
  END IF;
  END IF;
  END IF;
  IF (v_invoiceno <> '') THEN
  RETURN QUERY SELECT DISTINCT * FROM tmp_merchantinvoices WHERE invoiceno = v_invoiceno AND rownumber BETWEEN v_minindex AND v_maxindex ORDER BY tempdatetime DESC NULLS LAST;
  SELECT COUNT(rownumber) INTO v_totalcount FROM tmp_merchantinvoices;
  RETURN;
  END IF;
  IF (v_orderid <> '') THEN
  RETURN QUERY SELECT DISTINCT * FROM tmp_merchantinvoices WHERE orderid = v_orderid AND rownumber BETWEEN v_minindex AND v_maxindex ORDER BY tempdatetime DESC NULLS LAST;
  SELECT COUNT(rownumber) INTO v_totalcount FROM tmp_merchantinvoices;
  RETURN;
  END IF;
  IF (v_invoicetype <> '') THEN
  RETURN QUERY SELECT DISTINCT * FROM tmp_merchantinvoices WHERE invoicetype = v_invoicetype AND rownumber BETWEEN v_minindex AND v_maxindex ORDER BY tempdatetime DESC NULLS LAST;
  SELECT COUNT(rownumber) INTO v_totalcount FROM tmp_merchantinvoices;
  RETURN;
  ELSE
  RETURN QUERY SELECT DISTINCT *, CAST(invoicedate AS TIMESTAMP) AS d FROM tmp_merchantinvoices WHERE rownumber BETWEEN v_minindex AND v_maxindex ORDER BY tempdatetime DESC NULLS LAST;
  SELECT COUNT(rownumber) INTO v_totalcount FROM tmp_merchantinvoices;
  RETURN;
  END IF;
  DROP TABLE IF EXISTS tmp_merchantinvoices;
END;
$$;


--
-- Name: usp_get_merchantallinvoices_admin(integer, character varying, character varying, character varying, character varying, character varying, character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_get_merchantallinvoices_admin(v_plid integer DEFAULT 9, v_merchantname character varying DEFAULT ''::character varying, v_invoiceno character varying DEFAULT ''::character varying, v_orderid character varying DEFAULT ''::character varying, v_invoicetype character varying DEFAULT ''::character varying, v_fromdate character varying DEFAULT ''::character varying, v_todate character varying DEFAULT ''::character varying) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_gstamount DECIMAL(18,2);
BEGIN
  v_gstamount := 0;
  SELECT COALESCE(limits, 0) INTO v_gstamount FROM settings WHERE sid = 22;
  DROP TABLE IF EXISTS tmp_merchantinvoices;
  CREATE TEMP TABLE tmp_merchantinvoices (ROWNUMBER INT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  TMCIID INT,
  TMSIID INT,
  INVOICETYPE VARCHAR(50),
  ORDERID VARCHAR(100),
  INVOICENO VARCHAR(100),
  INVOICEDATE VARCHAR(50),
  ACTIVE INT,
  TOTALAMOUNT Decimal(18,2),
  MERCHANTNAME VARCHAR(50)) ON COMMIT DROP;
  INSERT INTO tmp_merchantinvoices SELECT DISTINCT COALESCE(invoice.tmciid, 0) AS tmciid, 0 AS tmsiid, 'COMMISSION' AS invoicetype, COALESCE(invoice.orderid, '') AS orderid, COALESCE(invoice.invoiceno, '') AS invoiceno, CAST(TO_CHAR(COALESCE(invoice.invoicedate, ''), 'TMMon DD YYYY FMHH12:MI%p') AS VARCHAR(30)) AS invoicedate, COALESCE(invoice.active, 0) AS active, ((tmc.taxableamount * tmc.admincharges) / 100 + tmc.handlingcharges + (tmc.taxableamount * tmc.fixedcharges) / 100) + (((tmc.taxableamount * tmc.admincharges) / 100 + tmc.handlingcharges + (tmc.taxableamount * tmc.fixedcharges) / 100) * v_gstamount) / 100, (SELECT companyname FROM portal_master WHERE plid = invoice.plid) AS merchantname FROM dbo.tbl_merchant_commissioninvoices AS invoice LEFT JOIN dbo.tbl_merchant_commissioninvoices_details AS tmc ON invoice.tmciid = tmc.tmciid;
  INSERT INTO tmp_merchantinvoices SELECT DISTINCT 0 AS tmciid, COALESCE(invoice.tmsiid, 0) AS tmsiid, 'SHIPPING' AS invoicetype, COALESCE(invoice.orderid, '') AS orderid, COALESCE(invoice.invoiceno, '') AS invoiceno, CAST(TO_CHAR(COALESCE(invoice.invoicedate, ''), 'TMMon DD YYYY FMHH12:MI%p') AS VARCHAR(30)) AS invoicedate, COALESCE(invoice.active, 0) AS active, (tmc.shippingcharges + (tmc.shippingcharges * v_gstamount) / 100), (SELECT companyname FROM portal_master WHERE plid = invoice.plid) AS merchantname FROM dbo.tbl_merchant_shippinginvoices AS invoice LEFT JOIN dbo.tbl_merchant_shippinginvoices_details AS tmc ON invoice.tmsiid = tmc.tmsiid;
  IF (v_merchantname <> '') THEN
  RETURN QUERY SELECT DISTINCT * FROM tmp_merchantinvoices WHERE merchantname = v_merchantname ORDER BY invoicedate ASC NULLS FIRST;
  END IF;
  IF (v_invoiceno <> '') THEN
  RETURN QUERY SELECT DISTINCT * FROM tmp_merchantinvoices WHERE invoiceno = v_invoiceno ORDER BY invoicedate ASC NULLS FIRST;
  END IF;
  IF (v_orderid <> '') THEN
  RETURN QUERY SELECT DISTINCT * FROM tmp_merchantinvoices WHERE orderid = v_orderid ORDER BY invoicedate ASC NULLS FIRST;
  END IF;
  IF (v_invoicetype <> '') THEN
  RETURN QUERY SELECT DISTINCT * FROM tmp_merchantinvoices WHERE invoicetype = v_invoicetype ORDER BY invoicedate ASC NULLS FIRST;
  ELSE
  RETURN QUERY SELECT DISTINCT * FROM tmp_merchantinvoices ORDER BY invoicedate DESC NULLS LAST;
  END IF;
  DROP TABLE IF EXISTS tmp_merchantinvoices;
END;
$$;


