--
-- Name: usp_get_merchantcommissioninvoices_details(integer, character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_get_merchantcommissioninvoices_details(v_plid integer DEFAULT 1, v_invoiceno character varying DEFAULT 'EBCOMM/18-19/000001'::character varying) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF (v_plid <> 0 AND v_invoiceno <> '') THEN
  RETURN QUERY SELECT SUM(COALESCE(tmcd.taxableamount, 0)) OVER () AS taxableamount, SUM(COALESCE((tmcd.taxableamount * tmcd.admincharges) / 100, 0)) OVER () AS admincharges, SUM(COALESCE(tmcd.handlingcharges, 0)) OVER () AS handlingcharges, SUM(COALESCE((tmcd.taxableamount * tmcd.fixedcharges) / 100, 0)) OVER () AS fixedcharges, COALESCE(tmcd.cgstrate, 0) AS cgstrate, COALESCE(tmcd.cgstamount, 0) AS cgstamount, COALESCE(tmcd.sgstrate, 0) AS sgstrate, COALESCE(tmcd.sgstamount, 0) AS sgstamount, COALESCE(tmcd.igstrate, 0) AS igstrate, COALESCE(tmcd.igstamount, 0) AS igstamount, COALESCE(tmcd.totalamount, 0) AS totalamount, COALESCE(tmcd.active, 0) AS active, CAST(TO_CHAR(COALESCE(tmcd.createddate, ''), 'TMMon DD YYYY FMHH12:MI%p') AS VARCHAR(30)) AS createddate FROM dbo.tbl_merchant_commissioninvoices_details AS tmcd INNER JOIN dbo.tbl_merchant_commissioninvoices AS tmc ON tmcd.tmciid = tmc.tmciid WHERE tmcd.plid = v_plid AND tmc.invoiceno = v_invoiceno LIMIT 1;
  END IF;
END;
$$;


