--
-- Name: usp_get_merchantpackages(integer, integer, integer, character varying, character varying, character varying, character varying, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_get_merchantpackages(v_plid integer DEFAULT 1, v_startrowindex integer DEFAULT 1, v_maxrows integer DEFAULT 100, v_searchfield character varying DEFAULT ''::character varying, v_searchvalue character varying DEFAULT ''::character varying, v_fromdate character varying DEFAULT ''::character varying, v_todate character varying DEFAULT ''::character varying, v_totalcount integer DEFAULT 0) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_gstamount DECIMAL(18,2);
  v_minindex INT;
  v_maxindex INT;
  v_query text;
  v_entitytype int;
BEGIN
  v_gstamount := 0;
  v_minindex := (v_startrowindex - 1) * v_maxrows + 1;
  v_maxindex := v_startrowindex * v_maxrows;
  SELECT COALESCE(limits, 0) INTO v_gstamount FROM settings WHERE sid = 22;
  DROP TABLE IF EXISTS tmp_merchantinvoices;
  CREATE TEMP TABLE tmp_merchantinvoices (ROWNUMBER INT GENERATED BY DEFAULT AS IDENTITY,
NAME varchar(150),
DISCRIPTION varchar(150),
ACTIVATIONDAYS int,
NO_OF_PRODUCT int,
NO_OF_SERVICE int,
ISDEALS int,
ISTRAILPACKAGE int,
STATUS int,
AMOUNT decimal(18,2),
MPID int) ON COMMIT DROP;
  v_entitytype := 0;
  SELECT COALESCE(entitytype, 0) INTO v_entitytype FROM tbl_businesskycdetails WHERE plid = v_plid;
  v_query := ' insert into  #MERCHANTINVOICES select
             NAME,DISCRIPTION,ACTIVATIONDAYS,NO_OF_PRODUCT,NO_OF_SERVICE,ISDEALS,ISTRAILPACKAGE,STATUS,AMOUNT,MPID
			 from TBL_MERCHANTPACKEAGES  where STATUS=1 ';
  IF (v_entitytype = 1) THEN
  v_query := v_query || (' and ISBUSSINESSPACKAGES=0 ');
  END IF;
  IF (v_entitytype = 2) THEN
  v_query := v_query || (' and ISBUSSINESSPACKAGES=1 ');
  END IF;
  IF (v_searchfield <> '') THEN
  IF (v_searchfield = 'Email') THEN
  v_query := v_query || (' and PL.EMAILID=''' || v_searchvalue || '''');
  END IF;
  IF (v_searchfield = 'Phone') THEN
  v_query := v_query || (' and PL.PHONE=''' || v_searchvalue || '''');
  END IF;
  END IF;
  IF (v_fromdate <> '' AND v_todate = '') THEN
  v_query := v_query || (' AND Convert(Date,PL.DOC,105) = CONVERT(DATE,''' || v_fromdate || ''',105) ');
  END IF;
  IF (v_fromdate = '' AND v_todate <> '') THEN
  v_query := v_query || (' AND Convert(Date,PL.DOC,105) = CONVERT(DATE,''' || v_todate || ''',105) ');
  END IF;
  IF (v_fromdate <> '' AND v_todate <> '') THEN
  v_query := v_query || (' AND Convert(Date,PL.DOC,105) BETWEEN CONVERT(DATE,''' || v_fromdate || ''',105) AND CONVERT(DATE,''' || v_todate || ''',105)');
  END IF;
  RAISE NOTICE '%', v_query;
  EXECUTE v_query;
  RETURN QUERY SELECT DISTINCT * FROM tmp_merchantinvoices WHERE rownumber BETWEEN v_minindex AND v_maxindex;
  SELECT COUNT(rownumber) INTO v_totalcount FROM tmp_merchantinvoices;
  DROP TABLE IF EXISTS tmp_merchantinvoices;
END;
$$;


