USERNAME varchar(150),
MEMBERNAME varchar(150),
EMAILID  varchar(150),
PHONE varchar(150),
Active int,
status int,
Name varchar(150),
ADDRESS varchar(500)) ON COMMIT DROP;
  v_query := ' insert into  #MERCHANTINVOICES
              select ROW_NUMBER() OVER(ORDER BY PL.DOC DESC) AS ROWNUMBER,PL.PLID,PL.LOGINID,PL.DOC,
			  PL.USERNAME,ISNULL(pm.COMPANYNAME,'''') AS MEMBERNAME,
