			  LEFT JOIN CITY CIT ON PM.CTID=CIT.CTID  
			  where PL.INTRO_REFID=''' || CAST(v_plid AS VARCHAR(10)) || ''' and PL.SourceId=2   and pl.PLID not in (select PLID from TBL_MERCHANT_PURCHASED_PACKAGES) ';
