 Title,case activeFlag when 0 then ''Inactive'' when 1 then ''Active'' end as status 
 from eventNews where type=3';
  EXECUTE v_query;
  RETURN QUERY SELECT * FROM tmp_temp WHERE rownumber BETWEEN v_minindex AND v_maxindex;
