$$;


--
-- Name: usp_get_offer_list(character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_get_offer_list(v_sprids character varying) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_tag_line varchar(300);
  v_offer_line varchar(300);
BEGIN
  v_tag_line := 'Don''t be slow our Price are low';
  RETURN QUERY SELECT opid, product_id, product_name, offer_mst_id, offer_title, TO_CHAR(offer_start, 'DD-MM-YYYY') AS offer_start, TO_CHAR(offer_end, 'DD-MM-YYYY') AS offer_end, TO_CHAR(offer_start, 'HH12:MI:SS tt') AS start_time, TO_CHAR(offer_end, 'HH12:MI:SS tt') AS end_time, is_active, inserted_on, offer_price, offer_dis_percentage, sp.sprid, v_tag_line AS tag_line, (mp.producttitle || ', You can buy in offer only on ' || CAST(offer.offer_price AS VARCHAR)) AS offer_desciption FROM tbl_offer_on_product AS offer RIGHT JOIN ims_subproduct AS sp ON offer.sprid = sp.sprid INNER JOIN ims_masterproduct AS mp ON mp.mprid = sp.mprid WHERE mp.mprid IN (SELECT value FROM SPLITSTRINGBYCUSTOMSYMBOL1(v_sprids, ',')) AND CURRENT_TIMESTAMP BETWEEN offer.offer_start AND offer.offer_end;
END;
$$;


--
-- Name: usp_get_offer_products(integer, integer, integer, character varying, text, integer, integer, integer, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_get_offer_products(v_maincatid integer DEFAULT 0, v_catid integer DEFAULT 0, v_subcatid integer DEFAULT 0, v_sorting character varying DEFAULT ''::character varying, v_querystring text DEFAULT ''::text, v_pageno integer DEFAULT 1, v_noofrows integer DEFAULT 100, v_totalcount integer DEFAULT 0, v_did integer DEFAULT 1) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
BEGIN
  BEGIN
  DROP TABLE IF EXISTS tmp_trendingproductsdata;
  CREATE TEMP TABLE tmp_trendingproductsdata ON COMMIT DROP AS SELECT DISTINCT pm.producttitle, CAST(pm.mprid AS BIGINT) AS mprid, COALESCE(CAST(pm.maincategoryid AS BIGINT), 0) AS maincategoryid, CAST(pm.subcategoryid AS BIGINT) AS subcategoryid, pm.shotdescription, pm.keyfeatures, CAST(pm.catid AS BIGINT) AS catid, pms.discountpercentage, CAST(pms.sprid AS BIGINT) AS sprid, pms.subprcode, pms.productimages, pms.actualprice, pms.sellmrp, pms.dap, COALESCE(tmc.main_cat_code, '') AS main_cat_code, COALESCE(tsb.sub_cat_code, '') AS sub_cat_code, COALESCE(c.cat_code, '') AS cat_code, CAST(0 AS BIGINT) AS rowno, '' AS productcode, '' AS fulldescription, 0 AS masterproductattriubuteid, '' AS attributetitle, '' AS attributevalue, 0 AS ratingstar, '' AS dealsids, pm.createddate AS createddate, pm.modifydate AS modifydate, 0 AS replacementday, 0 AS procurementsla, CAST(0 AS BIT) AS cashondelivery, CAST(0 AS DECIMAL(18, 8)) AS shippingcharges, 0 AS stockin, 0 AS stockout, 0 AS stocknet, CAST(0 AS BIT) AS isoutofstock, (CASE WHEN COALESCE(CAST(pms.bv AS DECIMAL(18, 8)), 0) = 0 THEN ((COALESCE(CAST((pms.dap + (pms.dap * vc.vatpercvalue) / 100) AS DECIMAL(18, 2)), 0) * COALESCE(tsb.bvper, 0)) / 100) ELSE pms.bv END) AS bv, (CASE WHEN COALESCE(CAST(pms.activationpv_per AS DECIMAL(18, 8)), 0) = 0 THEN ((COALESCE(CAST((pms.dap + (pms.dap * vc.vatpercvalue) / 100) AS DECIMAL(18, 2)), 0) * COALESCE(tsb.activationpv_per, 0)) / 100) ELSE pms.activationpv_per END) AS activationpv, (CASE WHEN COALESCE(CAST(pms.pv AS DECIMAL(18, 8)), 0) = 0 THEN ((COALESCE(CAST((pms.dap + (pms.dap * vc.vatpercvalue) / 100) AS DECIMAL(18, 2)), 0) * COALESCE(tsb.redeemcashback_per, 0)) / 100) ELSE pms.pv END) AS pv, (CASE WHEN COALESCE(CAST(pms.cashback_per AS DECIMAL(18, 8)), 0) = 0 THEN ((COALESCE(CAST((pms.dap + (pms.dap * vc.vatpercvalue) / 100) AS DECIMAL(18, 2)), 0) * COALESCE(tsb.cashback_per, 0)) / 100) ELSE pms.cashback_per END) AS cashback, CAST((pms.dap + (pms.dap * vc.vatpercvalue) / 100) AS DECIMAL(18, 2)) AS includingtax, pms.prskucode, pms.activationpv_per FROM ims_masterproduct AS pm LEFT OUTER JOIN ims_subproduct AS pms ON pms.mprid = pm.mprid INNER JOIN tbl_offer_on_product AS op ON op.sprid = pms.sprid AND CURRENT_TIMESTAMP BETWEEN op.offer_start AND op.offer_end LEFT OUTER JOIN ims_masterproductattribute AS pa ON pa.sprid = pms.sprid LEFT OUTER JOIN tbl_category AS c ON pm.catid = c.catid LEFT OUTER JOIN portal_login AS br ON br.plid = pm.branchid LEFT OUTER JOIN tbl_sub_category AS tsb ON pm.subcategoryid = tsb.subcatid LEFT OUTER JOIN tbl_main_category AS tmc ON tsb.maincatid = tmc.maincatid LEFT OUTER JOIN tbl_product_wise_bv_pv_setting AS tpwbvs ON tmc.maincatid = tpwbvs.maincatid AND tsb.subcatid = tpwbvs.subcatid AND c.catid = tpwbvs.catid LEFT OUTER JOIN tbl_customerlogin AS tcl ON tpwbvs.did = tcl.did LEFT OUTER JOIN tbl_vat_categories AS vc ON pms.vatcategoryid = vc.vcid WHERE br.active = 1 AND pms.isactive = 1 AND pms.isverified = 1 AND COALESCE(isverified, 0) = 1 AND tsb.status = 1 AND tmc.status = 1 AND br.status = 1 ORDER BY pm.createddate DESC NULLS LAST LIMIT 30;
  RETURN QUERY SELECT * FROM tmp_trendingproductsdata ORDER BY GEN_RANDOM_UUID() NULLS FIRST;
  v_totalcount := 30;
  -- SET option (removed)
  EXCEPTION WHEN OTHERS THEN
  v_totalcount := 0;
  END;
END;
$$;


--
-- Name: usp_get_overall_bvdetails(integer, integer, integer, character varying, character varying, integer, character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_get_overall_bvdetails(v_mode integer DEFAULT 0, v_startrowindex integer DEFAULT 1, v_maxrows integer DEFAULT 100, v_fromdate character varying DEFAULT ''::character varying, v_todate character varying DEFAULT ''::character varying, v_totalcount integer DEFAULT 0, v_searchvalue character varying DEFAULT ''::character varying) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_minindex INT;
  v_maxindex INT;
  v_query text;
  v_count INT;
  v_totaldata INT;
  v_tempdid INT;
  v_totalreleasd DECIMAL(18,2);
  v_totaldistributed DECIMAL(18,2);
BEGIN
  v_count := 1;
  v_totaldata := 0;
  v_tempdid := 0;
  v_minindex := (v_startrowindex - 1) * v_maxrows + 1;
  v_maxindex := v_startrowindex * v_maxrows;
  IF (v_mode = 0) THEN
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp (ROWNUMBER BIGINT GENERATED BY DEFAULT AS IDENTITY,
	DID INT,
	RESELLERNAME VARCHAR(100), 
	TOTALBV DECIMAL(18,2),
	TOTALRELEASED DECIMAL(18,2),
	TOTALDISTRIBUTED DECIMAL(18,2),
	TOTALPENDINGBV Decimal(18,2)) ON COMMIT DROP;
  v_query := 'INSERT INTO #TEMP SELECT RRB.DID,DM.COMPANYNAME,SUM(RRB.ORDERBV),0,0,0
			 FROM TBL_RESELLERRELEASEBVDETAILS RRB
			 LEFT JOIN DISTRIBUTOR_MASTER DM ON RRB.DID=DM.PMID
             WHERE STATUS=1 ';
  IF (v_searchvalue <> '') THEN
  v_query := v_query || ' AND DM.COMPANYNAME LIKE ''%' || v_searchvalue || '%'' ';
  END IF;
  v_query := v_query || ' GROUP BY RRB.DID,DM.COMPANYNAME ';
  EXECUTE v_query;
  RAISE NOTICE '%', v_query;
  SELECT COUNT(1) INTO v_totaldata FROM tmp_temp;
  WHILE (v_totaldata >= v_count) LOOP
  SELECT did INTO v_tempdid FROM tmp_temp WHERE rownumber = v_count;
  SELECT COALESCE(SUM(orderbv), 0) INTO v_totalreleasd FROM tbl_resellerreleasebvdetails WHERE did = v_tempdid AND isadminrelease = 1;
  SELECT COALESCE(SUM(orderbv), 0) INTO v_totaldistributed FROM tbl_resellerreleasebvdetails WHERE did = v_tempdid AND isresellerrelease = 2;
  UPDATE tmp_temp SET totalreleased = v_totalreleasd, totaldistributed = v_totaldistributed, totalpendingbv = (totalbv - (v_totalreleasd + v_totaldistributed)) WHERE did = v_tempdid;
  v_count := v_count + 1;
  END LOOP;
  RETURN QUERY SELECT * FROM tmp_temp WHERE rownumber BETWEEN v_minindex AND v_maxindex;
  SELECT COUNT(rownumber) INTO v_totalcount FROM tmp_temp;
  DROP TABLE IF EXISTS tmp_temp;
  -- SET option (removed)
  END IF;
END;
$$;


