--
-- Name: usp_get_posted_blog(integer, integer, integer, character varying, character varying, integer, integer, character varying, character varying, character varying, integer, integer, integer, integer, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_get_posted_blog(v_plid integer DEFAULT 0, v_startrowindex integer DEFAULT 1, v_maxrows integer DEFAULT 100, v_fromdate character varying DEFAULT ''::character varying, v_todate character varying DEFAULT ''::character varying, v_ddlstatus integer DEFAULT 1, v_intresult integer DEFAULT 0, v_loginid character varying DEFAULT ''::character varying, v_username character varying DEFAULT ''::character varying, v_name character varying DEFAULT ''::character varying, v_mode integer DEFAULT 0, v_tsbmid integer DEFAULT 0, v_isadmin integer DEFAULT 0, v_bytype integer DEFAULT 2, v_ddltopic integer DEFAULT 0) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_regno Int;
  v_query text;
  v_minindex INT;
  v_maxindex INT;
  v_newusername varchar(200);
BEGIN
  IF (v_mode = 0) THEN
  v_regno := 0;
  v_query := '';
  v_minindex := (v_startrowindex - 1) * v_maxrows + 1;
  v_maxindex := v_startrowindex * v_maxrows;
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp (RowNumber BIGINT GENERATED BY DEFAULT AS IDENTITY,
	TSBMID INT,
	PLID int,
	REGNO int,
	Title text,
	Introduction text,	
	Description text,
	Conclusion text,
	PostedDate text,
	TTMID int,
	Status VARCHAR(200),
	ApprovalStatus VARCHAR(200),
	ActivityDate date,
	AccuracyPercentage decimal,
	IsEditPossible varchar(100),
	IsDeletePossible varchar(100),
	IsDeactivatePossible varchar(100),
	TopicName text,
	loginid varchar(500),
	username varchar(500),
	fullname varchar(500),
	Remark text,
	IsResubmitted	int,
	LastUpdated	Varchar(50),
	EarnedPoints Decimal(10,2)) ON COMMIT DROP;
  v_query := 'Insert Into #TEMP Select TSBM.TSBMID,TSBM.PLID,TSBM.REGNO,TSBM.Title,
Introduction,Description,Conclusion,CONVERT(nvarchar(200),TSBM.PostedDate,106),
TSBM.TTMID,(Case When TSBM.Status=1 Then ''Active'' When TSBM.Status=2 Then ''Deactivated'' 
When TSBM.Status=0 Then ''Deleted'' End)As Status,
(Case When TSBM.IsViewedByAdmin = 0 Then ''In Review'' Else (Case When TSBM.ApprovalStatus=1 Then ''Approved'' When (TSBM.ApprovalStatus=2 And TSBM.IsResubmitted = 0) Then ''Rejected''
When (TSBM.ApprovalStatus=2 And TSBM.IsResubmitted = 1) Then ''In Review''
When TSBM.ApprovalStatus=3 Then ''On Hold'' WHEN TSBM.ApprovalStatus=0 THEN ''Pending'' END) END) As ApprovalStatus,Convert(Varchar(11),ActivityDate,106)As ActivityDate,AccuracyPercentage,
(Case When (ApprovalStatus=0 And IsResubmitted = 0) Then ''Yes'' When ApprovalStatus=2 Then ''Yes'' When ApprovalStatus=3 Then ''No'' Else ''No'' End) As IsEditPossible,
(Case When (ApprovalStatus=2 And IsResubmitted = 0) Then ''Yes'' Else ''No'' End) As IsDeletePossible,
(Case When (ApprovalStatus=0  And IsResubmitted = 0) Then ''Yes'' When (ApprovalStatus=2  And IsResubmitted = 0) Then ''Yes'' 
When (ApprovalStatus = 3) Then ''No'' Else ''No'' End) As IsDeactivatePossible,
TTM.TopicName, isnull(pl.loginid,''''),isnull(pl.username,''''),isnull(pl.FNAME,'''')+'' ''+isnull(pl.Lname,'''') as fullname,Isnull(TSBM.Remark,'''') As Remark,
TSBM.IsResubmitted,Isnull(Convert(Varchar(12),TSBM.LastUpdated,106),'''') As LastUpdated,Isnull(TMTID.EarnedAmount,0.00) As EarnedPoints
From Tbl_SubmitedBlogMaster TSBM INNER JOIN Tbl_TopicMaster TTM
ON TSBM.TTMID=TTM.TTMID left join portal_login pl on pl.plid=TSBM.PLID 
Left Join Tbl_MemberTaskIncomeDetails TMTID ON TMTID.TATBID = TSBM.TSBMID and TMTID.ActivityType=3 And TMTID.PLID=TSBM.PLID WHERE  TSBM.Status!=0';
  IF (v_plid <> 0) THEN
  v_query := v_query || (' And TSBM.PLID = ' || CAST(v_plid AS VARCHAR(50)) || ' ');
  END IF;
  IF (v_fromdate <> '' AND v_todate <> '') THEN
  v_query := v_query || (' And Convert(date,TSBM.PostedDate) Between Convert(date,''' || v_fromdate || ''') And Convert(date,''' || v_todate || ''')');
  ELSE
  IF (v_fromdate <> '') THEN
  v_query := v_query || (' And Convert(date,TSBM.PostedDate)= Convert(date,''' || v_fromdate || ''')');
  ELSE
  IF (v_todate <> '') THEN
  v_query := v_query || (' And Convert(date,TSBM.PostedDate) = Convert(date,''' || v_todate || ''')');
  END IF;
  END IF;
  END IF;
  IF (v_ddlstatus <> 0 AND NOT v_ddlstatus IN (4, 5)) THEN
  v_query := v_query || (' And TSBM.ApprovalStatus = ' || CAST(v_ddlstatus AS VARCHAR(50)) || ' ');
  END IF;
  IF (v_ddlstatus <> 0 AND v_ddlstatus IN (4, 5)) THEN
  IF (v_ddlstatus = 4) THEN
  v_query := v_query || (' And TSBM.Status = ' || CAST(1 AS VARCHAR(50)) || ' ');
  END IF;
  IF (v_ddlstatus = 5) THEN
  v_query := v_query || (' And TSBM.Status = ' || CAST(2 AS VARCHAR(50)) || ' ');
  END IF;
  END IF;
  IF (v_ddltopic > 0) THEN
  v_query := v_query || (' And TSBM.TTMID = ' || CAST(v_ddltopic AS VARCHAR(50)) || ' ');
  END IF;
  IF (v_bytype <> 2) THEN
  v_query := v_query || (' And TSBM.IsResubmitted = ' || CAST(v_bytype AS VARCHAR(10)) || ' ');
  END IF;
  IF (v_loginid <> '') THEN
  v_query := v_query || (' And isnull(pl.loginid,'''') LIKE ''%' || v_loginid || '%''');
  END IF;
  IF (v_username <> '') THEN
  IF (EXISTS(SELECT 1 FROM portal_login WHERE username = v_username)) THEN
  v_query := v_query || (' AND PL.USERNAME LIKE ''%' || v_username || '%''');
  ELSE
  IF (EXISTS(SELECT 1 FROM portal_login_history WHERE username = v_username)) THEN
  v_newusername := '';
  SELECT (SELECT username FROM portal_login WHERE plid IN (SELECT plid FROM portal_login_history WHERE username = v_username)) INTO v_newusername;
  v_query := v_query || (' AND PL.USERNAME LIKE ''%' || v_newusername || '%''');
  ELSE
  v_query := v_query || ' AND PL.USERNAME LIKE ''%' || v_username || '%'' ';
  END IF;
  END IF;
  END IF;
  IF (v_name <> '') THEN
  v_query := v_query || ' AND ISNULL(TTM.TopicName,'''') LIKE ''%' || v_name || '%''';
  END IF;
  v_query := v_query || ' order by TSBM.TSBMID desc';
  RAISE NOTICE '%', v_query;
  EXECUTE v_query;
  IF (v_isadmin = 0) THEN
  RETURN QUERY SELECT * FROM tmp_temp WHERE rownumber BETWEEN v_minindex AND v_maxindex;
  ELSE
  RETURN QUERY SELECT * FROM tmp_temp WHERE rownumber BETWEEN v_startrowindex AND v_maxrows;
  END IF;
  SELECT COUNT(COALESCE(plid, 0)) INTO v_intresult FROM tmp_temp;
  DROP TABLE IF EXISTS tmp_temp;
  END IF;
  IF (v_mode = 1) THEN
  RETURN QUERY SELECT ttm.topicname, tsbm.title, tsbm.introduction, tsbm.description, tsbm.conclusion, tsbm.remark FROM tbl_submitedblogmaster AS tsbm INNER JOIN tbl_topicmaster AS ttm ON tsbm.ttmid = ttm.ttmid WHERE tsbm.tsbmid = v_tsbmid;
  END IF;
END;
$$;


--
-- Name: usp_get_posted_classified(integer, integer, integer, character varying, character varying, integer, integer, character varying, character varying, character varying, integer, integer, integer, integer, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_get_posted_classified(v_plid integer DEFAULT 0, v_startrowindex integer DEFAULT 1, v_maxrows integer DEFAULT 100, v_fromdate character varying DEFAULT ''::character varying, v_todate character varying DEFAULT ''::character varying, v_ddlstatus integer DEFAULT 0, v_intresult integer DEFAULT 0, v_loginid character varying DEFAULT ''::character varying, v_username character varying DEFAULT ''::character varying, v_name character varying DEFAULT ''::character varying, v_mode integer DEFAULT 0, v_tscmid integer DEFAULT 0, v_isadmin integer DEFAULT 0, v_bytype integer DEFAULT 2, v_ddltopic integer DEFAULT 0) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_regno Int;
  v_query text;
  v_minindex INT;
  v_maxindex INT;
  v_newusername varchar(200);
BEGIN
  IF (v_mode = 0) THEN
  v_regno := 0;
  v_query := '';
  v_minindex := (v_startrowindex - 1) * v_maxrows + 1;
  v_maxindex := v_startrowindex * v_maxrows;
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp (RowNumber BIGINT GENERATED BY DEFAULT AS IDENTITY,
	TSCMID INT,
	PLID int,
	REGNO int,
	Title text,
	Description text,
	PostedDate text,
	TTMID int,
	Status VARCHAR(200),
	ApprovalStatus VARCHAR(200),
	ActivityDate date,
	AccuracyPercentage decimal,
	IsEditPossible varchar(100),
	IsDeletePossible varchar(100),
	IsDeactivatePossible varchar(100),
	TopicName text,
	loginid varchar(500),
	username varchar(500),
	fullname varchar(500),
	Remark text,
	FullTitle text,
	IsResubmitted	int,
	LastUpdated	Varchar(50),
	EarnedPoints Decimal(10,2)) ON COMMIT DROP;
  v_query := 'Insert Into #TEMP Select TSCM.TSCMID,TSCM.PLID,TSCM.REGNO,Case When TSCM.Title = Substring(TSCM.Title,0,20) Then TSCM.Title
Else Substring(TSCM.Title,0,20) +''<a class="More_View" id="''+TSCM.Title+''" style="cursor:pointer;">...More</a>'' End,
Description,CONVERT(Nvarchar(200), TSCM.PostedDate,106),TSCM.TTMID,(Case When TSCM.Status=1 Then ''Active'' When TSCM.Status=2 Then ''Deactivated'' 
When TSCM.Status=0 Then ''Deleted'' End)As Status,
(Case When TSCM.IsViewedByAdmin = 0 Then ''In Review'' Else (Case When TSCM.ApprovalStatus=1 Then ''Approved'' When (TSCM.ApprovalStatus=2 And TSCM.IsResubmitted = 0) Then ''Rejected''
When (TSCM.ApprovalStatus=2 And TSCM.IsResubmitted = 1) Then ''In Review''
When TSCM.ApprovalStatus=3 Then ''On Hold'' WHEN TSCM.ApprovalStatus=0 THEN ''Pending'' END) End) As ApprovalStatus,
Convert(Varchar(11),ActivityDate,106)As ActivityDate,AccuracyPercentage,
(Case When (ApprovalStatus=0 And IsResubmitted = 0) Then ''Yes'' When ApprovalStatus=2 Then ''Yes'' When ApprovalStatus=3 Then ''No'' Else ''No'' End) As IsEditPossible,
(Case When (ApprovalStatus=2 And IsResubmitted = 0) Then ''Yes'' Else ''No'' End) As IsDeletePossible,
(Case When (ApprovalStatus=0  And IsResubmitted = 0) Then ''Yes'' When (ApprovalStatus=2  And IsResubmitted = 0) Then ''Yes'' 
When (ApprovalStatus = 3) Then ''No'' Else ''No'' End) As IsDeactivatePossible,
Case When TTM.TopicName = Substring(TTM.TopicName,0,50) Then TopicName
Else Substring(TTM.TopicName,0,50) +''<a class="More_View_Topic" id="''+TTM.TopicName+''" style="cursor:pointer;">...More</a>'' End,isnull(pl.loginid,''''),
isnull(pl.username,''''),isnull(pl.FNAME,'''')+'' ''+isnull(pl.Lname,'''') as fullname,Isnull(TSCM.Remark,'''') As Remark,TSCM.Title As FullTitle,
TSCM.IsResubmitted,Isnull(Convert(Varchar(12),TSCM.LastUpdated,106),'''') As LastUpdated,
Isnull(TMTID.EarnedAmount,0.00) As EarnedPoints From Tbl_SubmitedClassifiedMaster TSCM INNER JOIN Tbl_TopicMaster TTM
ON TSCM.TTMID=TTM.TTMID left join portal_login pl on pl.plid=TSCM.PLID 
Left Join Tbl_MemberTaskIncomeDetails TMTID ON TMTID.TATBID = TSCM.TSCMID and TMTID.ActivityType=4 WHERE TSCM.Status!=0';
  IF (v_plid <> 0) THEN
  v_query := v_query || (' And TSCM.PLID = ' || CAST(v_plid AS VARCHAR(50)) || ' ');
  END IF;
  IF (v_fromdate <> '' AND v_todate <> '') THEN
  v_query := v_query || (' And Convert(date,TSCM.PostedDate) Between Convert(date,''' || v_fromdate || ''') And Convert(date,''' || v_todate || ''')');
  ELSE
  IF (v_fromdate <> '') THEN
  v_query := v_query || (' And Convert(date,TSCM.PostedDate) = Convert(date,''' || v_fromdate || ''')');
  ELSE
  IF (v_todate <> '') THEN
  v_query := v_query || (' And Convert(date,TSCM.PostedDate) = Convert(date,''' || v_todate || ''')');
  END IF;
  END IF;
  END IF;
  IF (v_bytype <> 2) THEN
  v_query := v_query || (' And TSCM.IsResubmitted = ' || CAST(v_bytype AS VARCHAR(10)) || ' ');
  END IF;
  IF (v_loginid <> '') THEN
  v_query := v_query || (' And isnull(pl.loginid,'''') LIKE ''%' || v_loginid || '%''');
  END IF;
  IF (v_username <> '') THEN
  IF (EXISTS(SELECT 1 FROM portal_login WHERE username = v_username)) THEN
  v_query := v_query || (' AND USERNAME LIKE ''%' || v_username || '%''');
  ELSE
  IF (EXISTS(SELECT 1 FROM portal_login_history WHERE username = v_username)) THEN
  v_newusername := '';
  SELECT (SELECT username FROM portal_login WHERE plid IN (SELECT plid FROM portal_login_history WHERE username = v_username)) INTO v_newusername;
  v_query := v_query || (' AND USERNAME LIKE ''%' || v_newusername || '%''');
  ELSE
  v_query := v_query || ' AND USERNAME LIKE ''%' || v_username || '%'' ';
  END IF;
  END IF;
  END IF;
  IF (v_name <> '') THEN
  v_query := v_query || ' AND ISNULL(TTM.TopicName,'''') LIKE ''%' || v_name || '%''';
  END IF;
  IF (v_ddlstatus <> 0 AND NOT v_ddlstatus IN (4, 5)) THEN
  v_query := v_query || (' And TSCM.ApprovalStatus = ' || CAST(v_ddlstatus AS VARCHAR(50)) || ' ');
  END IF;
  IF (v_ddlstatus <> 0 AND v_ddlstatus IN (4, 5)) THEN
  IF (v_ddlstatus = 4) THEN
  v_query := v_query || (' And TSCM.Status = ' || CAST(1 AS VARCHAR(50)) || ' ');
  END IF;
  IF (v_ddlstatus = 5) THEN
  v_query := v_query || (' And TSCM.Status = ' || CAST(2 AS VARCHAR(50)) || ' ');
  END IF;
  END IF;
  IF (v_ddltopic > 0) THEN
  v_query := v_query || (' And TSCM.TTMID = ' || CAST(v_ddltopic AS VARCHAR(50)) || ' ');
  END IF;
  v_query := v_query || ' order by TSCM.TSCMID desc';
  EXECUTE v_query;
  IF (v_isadmin = 0) THEN
  RETURN QUERY SELECT * FROM tmp_temp WHERE rownumber BETWEEN v_minindex AND v_maxindex;
  ELSE
  RETURN QUERY SELECT * FROM tmp_temp WHERE rownumber BETWEEN v_startrowindex AND v_maxrows;
  END IF;
  SELECT COUNT(rownumber) INTO v_intresult FROM tmp_temp;
  DROP TABLE IF EXISTS tmp_temp;
  END IF;
  IF (v_mode = 1) THEN
  RETURN QUERY SELECT ttm.topicname, tscm.title, tscm.description, tscm.remark FROM tbl_submitedclassifiedmaster AS tscm INNER JOIN tbl_topicmaster AS ttm ON tscm.ttmid = ttm.ttmid WHERE tscm.tscmid = v_tscmid;
  END IF;
END;
$$;


--
-- Name: usp_get_prodouctwise_bv_pv_setting(integer, integer, character varying, character varying, integer, integer, character varying, character varying, character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_get_prodouctwise_bv_pv_setting(v_startrowindex integer DEFAULT 1, v_maxrows integer DEFAULT 1000, v_fromdate character varying DEFAULT ''::character varying, v_todate character varying DEFAULT ''::character varying, v_did integer DEFAULT 1, v_totalcount integer DEFAULT 0, v_maincatid character varying DEFAULT ''::character varying, v_catid character varying DEFAULT ''::character varying, v_subcatid character varying DEFAULT ''::character varying) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_minindex INT;
  v_maxindex INT;
  v_query text;
  v_condition text;
  v_countquery text;
  v_trpid INT;
BEGIN
  -- BEGIN TRAN (removed)
  -- SET option (removed)
  v_condition := '';
  v_countquery := '';
  v_trpid := 0;
  v_minindex := (v_startrowindex - 1) * v_maxrows + 1;
  v_maxindex := v_startrowindex * v_maxrows;
  SELECT COALESCE(trpid, 0) INTO v_trpid FROM tbl_reseller_purchased_packages WHERE did = v_did AND trsid = 2;
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp (ROWNUMBER INT GENERATED BY DEFAULT AS IDENTITY,
 MAINCATID INT,
 MAINCATNAME VARCHAR(100),
 CATID INT,
 CATNAME VARCHAR(100),
 SUBCATID INT,
 SUBCATNAME VARCHAR(100),
 COMMISSION DECIMAL(18,2),
 BV DECIMAL(18,2),
 PV DECIMAL(18,2)) ON COMMIT DROP;
  v_query := ' INSERT INTO #TEMP Select distinct TPPC.maincatid,TMC.MainCatName,Tppc.CATTID,TC.CatName,
TPPC.SUBCATID,TSC.SubCatName,
(CASE WHEN ''' || CAST(v_trpid AS VARCHAR(30)) || '''=5 THEN TPPC.ACTUALCOMMPACKAGE1 WHEN  ''' || CAST(v_trpid AS VARCHAR(30)) || '''=6 
THEN TPPC.ACTUALCOMMPACKAGE2 WHEN  ''' || CAST(v_trpid AS VARCHAR(30)) || '''=7 
THEN TPPC.ACTUALCOMMPACKAGE3 WHEN  ''' || CAST(v_trpid AS VARCHAR(30)) || '''=8 THEN TPPC.ACTUALCOMMPACKAGE4 END),
ISNULL(TPWBV.BV,0),ISNULL(TPWBV.PV,0)
from TBL_PRODOUCT_PACKAGEWISE_COMMISSION  TPPC
LEFT JOIN tbl_Main_Category TMC ON TPPC.MAINCATID=TMC.MAINCATID
LEFT JOIN tbl_Category TC ON TPPC.CATTID=TC.CatId
LEFT JOIN tbl_Sub_Category TSC ON TPPC.SUBCATID=tsc.SUBCATID
LEFT JOIN TBL_PRODUCT_WISE_BV_PV_SETTING TPWBV ON TPPC.MAINCATID=TPWBV.Maincatid and TPPC.CATTID=TPWBV.catid
 and TPPC.SUBCATID=TPWBV.SUBCATID and TPWBV.DID=''' || CAST(v_did AS VARCHAR(30)) || ''' 
LEFT JOIN TBL_RESELLER_PURCHASED_PACKAGES TRPP ON TPWBV.DID=TRPP.DID 
where 1=1 ';
  IF (v_maincatid <> '') THEN
  v_query := v_query || (' and TMC.MainCatName=''' || CAST(v_maincatid AS VARCHAR(30)) || '''');
  END IF;
  IF (v_catid <> '') THEN
  v_query := v_query || (' and TC.CatName=''' || CAST(v_catid AS VARCHAR(30)) || '''');
  END IF;
  IF (v_subcatid <> '') THEN
  v_query := v_query || (' and TSC.SubCatName=''' || CAST(v_subcatid AS VARCHAR(30)) || '''');
  END IF;
  EXECUTE v_query;
  RAISE NOTICE '%', v_query;
  RETURN QUERY SELECT * FROM tmp_temp WHERE rownumber BETWEEN v_minindex AND v_maxindex ORDER BY rownumber ASC NULLS FIRST;
  SELECT COUNT(rownumber) INTO v_totalcount FROM tmp_temp;
  DROP TABLE IF EXISTS tmp_temp;
  -- COMMIT (removed)
END;
$$;


--
-- Name: usp_get_product_commisssion(integer, integer, character varying, character varying, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_get_product_commisssion(v_startrowindex integer DEFAULT 1, v_maxrows integer DEFAULT 100, v_fromdate character varying DEFAULT ''::character varying, v_todate character varying DEFAULT ''::character varying, v_totalcount integer DEFAULT 0) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_minindex INT;
  v_maxindex INT;
  v_query text;
BEGIN
  -- BEGIN TRAN (removed)
  -- SET option (removed)
  v_query := '';
  v_minindex := (v_startrowindex - 1) * v_maxrows + 1;
  v_maxindex := v_startrowindex * v_maxrows;
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp (ROWNUMBER INT GENERATED BY DEFAULT AS IDENTITY,
MAINCATID INT,
CATID INT,
SUBCATID INT,
MAINCATNAME VARCHAR(100),
CATNAME VARCHAR(100),
SUBCATNAME VARCHAR(100),
ADMINCOMMISSION DECIMAL(18,2),
Package1 DECIMAL(18,2),
Package2 DECIMAL(18,2),
Package3 DECIMAL(18,2),
Package4 DECIMAL(18,2),
ACTUALCOMMISSION1 DECIMAL(18,2),
ACTUALCOMMISSION2 DECIMAL(18,2),
ACTUALCOMMISSION3 DECIMAL(18,2),
ACTUALCOMMISSION4 DECIMAL(18,2),
Status Varchar(100),
LastDate Varchar(100)) ON COMMIT DROP;
  v_query := ' INSERT INTO #TEMP SELECT TSC.MAINCATID,TSC.CATID,TSC.SUBCATID,TMC.MAINCATNAME,TC.CATNAME,TSC.SUBCATNAME,ISNULL(TSC.AdminCharge,0),
ISNULL(TPPC.PACKAGECOMMISION1,0),ISNULL(TPPC.PACKAGECOMMISION2,0),ISNULL(TPPC.PACKAGECOMMISION3,0),
ISNULL(TPPC.PACKAGECOMMISION4,0),ISNULL(TPPC.ACTUALCOMMPACKAGE1,0),ISNULL(TPPC.ACTUALCOMMPACKAGE2,0),ISNULL(TPPC.ACTUALCOMMPACKAGE3,0),
ISNULL(TPPC.ACTUALCOMMPACKAGE4,0),iif(TSC.Status=1,''Active'',''Deactive''),isnull(CONVERT(varchar,TPPC.UPDATEDATE,106),'''')
FROM TBL_SUB_CATEGORY TSC
LEFT JOIN TBL_MAIN_CATEGORY TMC ON TSC.MAINCATID=TMC.MAINCATID
LEFT JOIN TBL_CATEGORY TC ON TSC.CATID=TC.CATID
LEFT JOIN TBL_PRODOUCT_PACKAGEWISE_COMMISSION TPPC ON TSC.SUBCATID=TPPC.SUBCATID ';
  EXECUTE v_query;
  RAISE NOTICE '%', v_query;
  RETURN QUERY SELECT * FROM tmp_temp WHERE rownumber BETWEEN v_minindex AND v_maxindex;
  SELECT COUNT(rownumber) INTO v_totalcount FROM tmp_temp;
  DROP TABLE IF EXISTS tmp_temp;
  -- SET option (removed)
  -- COMMIT (removed)
END;
$$;


--
-- Name: usp_get_recentlyvieweditems(integer, text, character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_get_recentlyvieweditems(v_mode integer DEFAULT 1, v_sprid text DEFAULT '69,57,15'::text, v_stroutput character varying DEFAULT ''::character varying) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_data_string VARCHAR(1000);
  v_result varchar(1000);
  v_cookiessprid text;
BEGIN
  IF (v_mode = 1) THEN
  v_result := '';
  v_cookiessprid := '';
  IF (v_sprid <> '') THEN
  v_data_string := v_sprid;
  v_data_string := REPLACE(v_data_string, '|', ',');
  SELECT v_result || col || ',' INTO v_result FROM (SELECT DISTINCT t.c.value('.', 'text') AS col FROM (SELECT CAST('<A>' || REPLACE(v_data_string, ',', '</A><A>') || '</A>' AS XML) AS col1) AS data INNER JOIN LATERAL col1.nodes('/A') AS t(c) ON TRUE) AS data;
  SELECT LEFT(CAST(v_result AS TEXT), LENGTH(CAST(v_result AS TEXT)) - 1) INTO v_cookiessprid;
  END IF;
  DROP TABLE IF EXISTS tmp_recentlyviewproductsdata;
  CREATE TEMP TABLE tmp_recentlyviewproductsdata ON COMMIT DROP AS SELECT DISTINCT pm.producttitle, CAST(pm.mprid AS BIGINT) AS mprid, COALESCE(CAST(pm.maincategoryid AS BIGINT), 0) AS maincategoryid, CAST(pm.subcategoryid AS BIGINT) AS subcategoryid, pm.shotdescription, pm.keyfeatures, CAST(pm.catid AS BIGINT) AS catid, pms.discountpercentage, CAST(pms.sprid AS BIGINT) AS sprid, pms.subprcode, pms.productimages, pms.actualprice, pms.sellmrp, pms.dap, COALESCE(tmc.main_cat_code, '') AS main_cat_code, COALESCE(tsb.sub_cat_code, '') AS sub_cat_code, COALESCE(c.cat_code, '') AS cat_code, CAST(0 AS BIGINT) AS rowno, '' AS productcode, '' AS fulldescription, 0 AS masterproductattriubuteid, '' AS attributetitle, '' AS attributevalue, 0 AS ratingstar, '' AS dealsids, pm.createddate AS createddate, pm.modifydate AS modifydate, 0 AS replacementday, 0 AS procurementsla, CAST(0 AS BIT) AS cashondelivery, CAST(0 AS DECIMAL) AS shippingcharges, 0 AS stockin, 0 AS stockout, 0 AS stocknet, CAST(0 AS BIT) AS isoutofstock, (CASE WHEN COALESCE(CAST(pms.bv AS DECIMAL), 0) = 0 THEN ((COALESCE(CAST((pms.dap + (pms.dap * vc.vatpercvalue) / 100) AS DECIMAL(18, 2)), 0) * COALESCE(tsb.bvper, 0)) / 100) ELSE pms.bv END) AS bv, (CASE WHEN COALESCE(CAST(pms.activationpv_per AS DECIMAL), 0) = 0 THEN ((COALESCE(CAST((pms.dap + (pms.dap * vc.vatpercvalue) / 100) AS DECIMAL(18, 2)), 0) * COALESCE(tsb.activationpv_per, 0)) / 100) ELSE pms.activationpv_per END) AS activationpv, (CASE WHEN COALESCE(CAST(pms.pv AS DECIMAL), 0) = 0 THEN ((COALESCE(CAST((pms.dap + (pms.dap * vc.vatpercvalue) / 100) AS DECIMAL(18, 2)), 0) * COALESCE(tsb.redeemcashback_per, 0)) / 100) ELSE pms.pv END) AS pv, (CASE WHEN COALESCE(CAST(pms.cashback_per AS DECIMAL), 0) = 0 THEN ((COALESCE(CAST((pms.dap + (pms.dap * vc.vatpercvalue) / 100) AS DECIMAL(18, 2)), 0) * COALESCE(tsb.cashback_per, 0)) / 100) ELSE pms.cashback_per END) AS cashback, CAST((pms.dap + (pms.dap * vc.vatpercvalue) / 100) AS DECIMAL(18, 2)) AS includingtax, pms.prskucode, pms.activationpv_per FROM ims_masterproduct AS pm LEFT OUTER JOIN ims_subproduct AS pms ON pms.mprid = pm.mprid LEFT OUTER JOIN ims_masterproductattribute AS pa ON pa.sprid = pms.sprid LEFT OUTER JOIN tbl_category AS c ON pm.catid = c.catid LEFT OUTER JOIN portal_login AS br ON br.plid = pm.branchid LEFT OUTER JOIN tbl_sub_category AS tsb ON pm.subcategoryid = tsb.subcatid LEFT OUTER JOIN tbl_main_category AS tmc ON tsb.maincatid = tmc.maincatid LEFT OUTER JOIN tbl_vat_categories AS vc ON pms.vatcategoryid = vc.vcid WHERE pms.isactive = 1 AND pms.isverified = 1 AND COALESCE(isverified, 0) = 1 AND tsb.status = 1 AND tmc.status = 1 AND br.status = 1 AND pms.sprid IN (SELECT value FROM dbo.SPLITSTRINGBYCOMMA(v_cookiessprid)) LIMIT 30;
  RETURN QUERY SELECT * FROM tmp_recentlyviewproductsdata;
  v_stroutput := 'SUCCESS';
  END IF;
END;
$$;


--
-- Name: usp_get_recentlyvieweditems_mobile(integer, text, character varying, integer, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_get_recentlyvieweditems_mobile(v_mode integer DEFAULT 1, v_sprid text DEFAULT '21501,21502'::text, v_stroutput character varying DEFAULT ''::character varying, v_getclid integer DEFAULT 0, v_did integer DEFAULT 0) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_data_string VARCHAR(1000);
  v_result varchar(1000);
  v_cookiessprid text;
  v_dynamicurl varchar(100);
  v_merchantproductlargeimage varchar(250);
BEGIN
  IF (v_mode = 1) THEN
  v_result := '';
  v_cookiessprid := '';
  v_dynamicurl := '';
  v_merchantproductlargeimage := '';
  SELECT merchantimagepath, merchantproductlargeimage INTO v_dynamicurl, v_merchantproductlargeimage FROM tbl_company;
  IF (v_sprid <> '') THEN
  v_data_string := v_sprid;
  v_data_string := REPLACE(v_data_string, '|', ',');
  SELECT v_result || col || ',' INTO v_result FROM (SELECT DISTINCT t.c.value('.', 'text') AS col FROM (SELECT CAST('<A>' || REPLACE(v_data_string, ',', '</A><A>') || '</A>' AS XML) AS col1) AS data INNER JOIN LATERAL col1.nodes('/A') AS t(c) ON TRUE) AS data;
  SELECT LEFT(CAST(v_result AS TEXT), LENGTH(CAST(v_result AS TEXT)) - 1) INTO v_cookiessprid;
  END IF;
  DROP TABLE IF EXISTS tmp_recentlyviewproductsdata;
  CREATE TEMP TABLE tmp_recentlyviewproductsdata ON COMMIT DROP AS SELECT DISTINCT pm.producttitle AS producttitle, COALESCE(CAST(pm.maincategoryid AS BIGINT), 0) AS maincategoryid, CAST(pm.subcategoryid AS BIGINT) AS subcategoryid, CAST(pm.catid AS BIGINT) AS catid, pms.discountpercentage AS discountpercentage, CAST(pms.sprid AS BIGINT) AS sprid, pms.subprcode AS productcode, (pms.productimages) AS productimages, pms.sellmrp AS sellmrp, pms.dap, 0 AS ratingstar, pm.createddate AS createdate, CAST(0 AS DECIMAL) AS shippingcharges, CAST(0 AS BIT) AS isoutofstock, COALESCE(dcs.bv, 0) AS bv, COALESCE(dcs.cashback, 0) AS cashback FROM ims_masterproduct AS pm LEFT OUTER JOIN ims_subproduct AS pms ON pms.mprid = pm.mprid LEFT OUTER JOIN ims_masterproductattribute AS pa ON pa.sprid = pms.sprid LEFT OUTER JOIN tbl_category AS c ON pm.catid = c.catid LEFT OUTER JOIN portal_login AS br ON br.plid = pm.branchid LEFT OUTER JOIN tbl_sub_category AS tsb ON pm.subcategoryid = tsb.subcatid LEFT OUTER JOIN tbl_main_category AS tmc ON tsb.maincatid = tmc.maincatid LEFT OUTER JOIN tbl_distributor_commission_structure AS dcs ON dcs.subsubcatid = tsb.subcatid AND dcs.did = v_did WHERE pms.isactive = 1 AND pms.isverified = 1 AND COALESCE(isverified, 0) = 1 AND tsb.status = 1 AND tmc.status = 1 AND br.status = 1 AND pms.sprid IN (SELECT value FROM dbo.SPLITSTRINGBYCOMMA(v_cookiessprid)) LIMIT 30;
  RETURN QUERY SELECT (SELECT CASE WHEN COALESCE(COUNT(1), 0) > 0 THEN 1 ELSE 0 END FROM tbl_wishlist WHERE sprid = tm.sprid AND loginid = v_getclid AND status = 1) AS wishcount, v_dynamicurl AS baseurl, * FROM tmp_recentlyviewproductsdata AS tm;
  v_stroutput := 'SUCCESS';
  END IF;
END;
$$;


