--
-- Name: usp_get_referalcommission_deatils(integer, integer, integer, integer, character varying, character varying, character varying, character varying, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_get_referalcommission_deatils(v_id integer DEFAULT 1, v_type integer DEFAULT 2, v_startrowindex integer DEFAULT 1, v_maxrows integer DEFAULT 100, v_searchfield character varying DEFAULT ''::character varying, v_searchvalue character varying DEFAULT ''::character varying, v_fromdate character varying DEFAULT ''::character varying, v_todate character varying DEFAULT ''::character varying, v_totalcount integer DEFAULT 0) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_gstamount DECIMAL(18,2);
  v_minindex INT;
  v_maxindex INT;
  v_query text;
BEGIN
  v_gstamount := 0;
  v_minindex := (v_startrowindex - 1) * v_maxrows + 1;
  v_maxindex := v_startrowindex * v_maxrows;
  SELECT COALESCE(limits, 0) INTO v_gstamount FROM settings WHERE sid = 22;
  DROP TABLE IF EXISTS tmp_merchantinvoices;
  CREATE TEMP TABLE tmp_merchantinvoices (ROWNUMBER INT GENERATED BY DEFAULT AS IDENTITY,
DATE timestamp,
FranchiseName varchar(500),
FranchiseEmailID varchar(150),
FranchiseAddress varchar(150),
MerchantName varchar(500),
MerchantEmailid varchar(150),
GROSSAMOUNT decimal(18,8),
FranchisePackage varchar(500),
MerchantPackage varchar(500),
COMM_PER  decimal(18,8),
COIN varchar(500),
FIETCURRENCY varchar(500)) ON COMMIT DROP;
  v_query := ' insert into #MERCHANTINVOICES select RC.DATE,D.NAME as FranchiseName,D.EMAILID as FranchiseEmailID,D.Address as FranchiseAddress,
			   PL.FNAME as MerchantName,PL.EMAILID as MerchantEmailid,
			   RC.GROSSAMOUNT,RP.PACKAGENAME as FranchisePackage,MP.NAME as MerchantPackage,RC.COMM_PER,RC.COIN,RC.FIETCURRENCY
			   from TBL_REFERALCOMMISSION as RC 
			   left join TBL_DISTRIBUTOR as D on RC.TOID=D.LOGINID and RC.TYPE=1
			   left join PORTAL_LOGIN as PL on RC.TOID=PL.LOGINID and RC.TYPE=2
			   left join TBL_RESELLER_PACKAGES as RP on RP.TRPID=RC.PACKAGEID and RC.TYPE=1
			   left join TBL_MERCHANTPACKEAGES as MP on MP.MPID=RC.PACKAGEID and RC.TYPE=2
			    left join TBL_DISTRIBUTOR as D1 on RC.FROMID=D1.LOGINID and RC.TYPE=1
			   left join PORTAL_LOGIN as PL1 on RC.FROMID=PL1.LOGINID and RC.TYPE=2
			   where MP.STATUS=1 ';
  IF (v_type = 2) THEN
  IF (v_id <> 0) THEN
  v_query := v_query || (' and PL1.PLID=' || CAST(v_id AS VARCHAR(10)));
  END IF;
  END IF;
  IF (v_type = 1) THEN
  IF (v_id <> 0) THEN
  v_query := v_query || (' and D1.DID=' || CAST(v_id AS VARCHAR(10)));
  END IF;
  END IF;
  IF (v_searchfield <> '') THEN
  IF (v_searchfield = 'Email') THEN
  v_query := v_query || (' and PL.EMAILID=''' || v_searchvalue || '''');
  END IF;
  IF (v_searchfield = 'Phone') THEN
  v_query := v_query || (' and PL.PHONE=''' || v_searchvalue || '''');
  END IF;
  END IF;
  IF (v_fromdate <> '' AND v_todate = '') THEN
  v_query := v_query || (' AND Convert(Date,RC.DATE,105) = CONVERT(DATE,''' || v_fromdate || ''',105) ');
  END IF;
  IF (v_fromdate = '' AND v_todate <> '') THEN
  v_query := v_query || (' AND Convert(Date,RC.DATE,105) = CONVERT(DATE,''' || v_todate || ''',105) ');
  END IF;
  IF (v_fromdate <> '' AND v_todate <> '') THEN
  v_query := v_query || (' AND Convert(Date,RC.DATE,105) BETWEEN CONVERT(DATE,''' || v_fromdate || ''',105) AND CONVERT(DATE,''' || v_todate || ''',105)');
  END IF;
  RAISE NOTICE '%', v_query;
  EXECUTE v_query;
  RETURN QUERY SELECT DISTINCT * FROM tmp_merchantinvoices WHERE rownumber BETWEEN v_minindex AND v_maxindex;
  SELECT COUNT(rownumber) INTO v_totalcount FROM tmp_merchantinvoices;
  DROP TABLE IF EXISTS tmp_merchantinvoices;
END;
$$;


--
-- Name: usp_get_reselleer_features(integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_get_reselleer_features(v_sid integer DEFAULT 0) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_serviceid INT;
BEGIN
  v_serviceid := 0;
  RETURN QUERY SELECT trsid, trpid, (CASE WHEN webhosting = 1 THEN '<span class="fa fa-check" style="font-size:20px" aria-hidden="true"></span>' ELSE '<span class="fa fa-close" style="font-size:20px" aria-hidden="true"></span>' END) AS webhosting, (CASE WHEN freemarketingtool = 1 THEN '<span class="fa fa-check" style="font-size:20px" aria-hidden="true"></span>' ELSE '<span class="fa fa-close" style="font-size:20px" aria-hidden="true"></span>' END) AS freemarketingtool, (CASE WHEN multichannelsales = 1 THEN '<span class="fa fa-check" style="font-size:20px" aria-hidden="true"></span>' ELSE '<span class="fa fa-close" style="font-size:20px" aria-hidden="true"></span>' END) AS multichannelsales, (CASE WHEN whitelabelbranding = 1 THEN '<span class="fa fa-check" style="font-size:20px" aria-hidden="true"></span>' ELSE '<span class="fa fa-close" style="font-size:20px" aria-hidden="true"></span>' END) AS whitelabelbranding, (CASE WHEN ddos = 1 THEN '<span class="fa fa-check" style="font-size:20px" aria-hidden="true"></span>' ELSE '<span class="fa fa-close" style="font-size:20px" aria-hidden="true"></span>' END) AS ddos, (CASE WHEN antivirus = 1 THEN '<span class="fa fa-check" style="font-size:20px" aria-hidden="true"></span>' ELSE '<span class="fa fa-close" style="font-size:20px" aria-hidden="true"></span>' END) AS antivirus, (CASE WHEN seotools = 1 THEN '<span class="fa fa-check" style="font-size:20px" aria-hidden="true"></span>' ELSE '<span class="fa fa-close" style="font-size:20px" aria-hidden="true"></span>' END) AS seotools, (CASE WHEN smotool = 1 THEN '<span class="fa fa-check" style="font-size:20px" aria-hidden="true"></span>' ELSE '<span class="fa fa-close" style="font-size:20px" aria-hidden="true"></span>' END) AS smotool, (CASE WHEN autobackup = 1 THEN '<span class="fa fa-check" style="font-size:20px" aria-hidden="true"></span>' ELSE '<span class="fa fa-close" style="font-size:20px" aria-hidden="true"></span>' END) AS autobackup, (CASE WHEN livechat = 1 THEN '<span class="fa fa-check" style="font-size:20px" aria-hidden="true"></span>' ELSE '<span class="fa fa-close" style="font-size:20px" aria-hidden="true"></span>' END) AS livechat, (CASE WHEN logodesign = 1 THEN '<span class="fa fa-check" style="font-size:20px" aria-hidden="true"></span>' ELSE '<span class="fa fa-close" style="font-size:20px" aria-hidden="true"></span>' END) AS logodesign, (CASE WHEN websiteskin = 1 THEN '<span class="fa fa-check" style="font-size:20px" aria-hidden="true"></span>' ELSE '<span class="fa fa-close" style="font-size:20px" aria-hidden="true"></span>' END) AS websiteskin, (CASE WHEN androidapp = 1 THEN '<span class="fa fa-check" style="font-size:20px" aria-hidden="true"></span>' ELSE '<span class="fa fa-close" style="font-size:20px" aria-hidden="true"></span>' END) AS androidapp, (CASE WHEN storage = '' THEN 'N/A' ELSE storage END) AS storage, (CASE WHEN discountcoupongen = '' THEN 'N/A' ELSE discountcoupongen END) AS discountcoupongen, CAST((CASE WHEN "user" = 0 THEN '0' ELSE CAST("user" AS VARCHAR(10)) END) AS VARCHAR(10)) AS "user", CAST((CASE WHEN targetaudience = 0 THEN '0' ELSE CAST(targetaudience AS VARCHAR(10)) END) AS VARCHAR(10)) AS targetaudience, CAST((CASE WHEN newcustomers = 0 THEN '0' ELSE CAST(newcustomers AS VARCHAR(10)) END) AS VARCHAR(10)) AS newcustomers, (CASE WHEN onlinedatastorage = '' THEN 'N/A' ELSE onlinedatastorage END) AS onlinedatastorage, CAST((CASE WHEN emailstorage = 0 THEN '0' ELSE CAST(emailstorage AS VARCHAR(10)) END) AS VARCHAR(10)) AS emailstorage, CAST((CASE WHEN transactionalsms = 0 THEN '0' ELSE CAST(transactionalsms AS VARCHAR(10)) END) AS VARCHAR(10)) AS transactionalsms, (CASE WHEN multiplepaymentgateway = '' THEN 'N/A' ELSE multiplepaymentgateway END) AS multiplepaymentgateway FROM tbl_reseller_packages WHERE trsid IN (SELECT trsid FROM tbl_reseller_services WHERE trsid = v_sid AND active = 1) AND active = 1;
END;
$$;


--
-- Name: usp_get_reselleer_services(integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_get_reselleer_services(v_deafultservices integer) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
BEGIN
  RETURN QUERY SELECT * FROM tbl_reseller_services WHERE active = 1;
  SELECT trsid INTO v_deafultservices FROM tbl_reseller_services WHERE active = 1 ORDER BY trsid NULLS FIRST LIMIT 1;
  RETURN;
END;
$$;


--
-- Name: usp_get_reseller_commissioninvoices_details(integer, character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_get_reseller_commissioninvoices_details(v_did integer DEFAULT 2, v_invoiceno character varying DEFAULT 'Comm/19-20/000001'::character varying) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
BEGIN
  -- SET option (removed)
  IF (v_did <> 0 AND v_invoiceno <> '') THEN
  RETURN QUERY SELECT COALESCE(cr, 0) AS amount, COALESCE(gstpercentage, 0) AS gstpercentage, (cr + (cr * gstpercentage) / 100) AS totalamount, (cr * gstpercentage) / 100 AS gstamount, CASE WHEN servicetype = 1 THEN 'UTILITY COMMISISON' ELSE 'Prodouct Commission' END AS description FROM tbl_reseller_commission_wallet WHERE did = v_did AND invoiceno = v_invoiceno LIMIT 1;
  -- SET option (removed)
  END IF;
END;
$$;


--
-- Name: usp_get_reseller_companydetails(integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_get_reseller_companydetails(v_did integer DEFAULT 2) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
BEGIN
  -- SET option (removed)
  RETURN QUERY SELECT COALESCE(companyname, '') AS name, COALESCE(mobileno, '') AS mobile, COALESCE('', '') AS landline, COALESCE(emailid, '') AS emailid, COALESCE(dm.address || ' ' || ct.cityname || '' || st.statename || '' || cu.countryname || dm.pincode, '') AS address, COALESCE(dm.gstno, '') AS gstno, dm.cinno AS cin, tbd.panno AS pan, COALESCE(dm.companyimage, 'No-logo.png') AS brandlogo, COALESCE(dm.companydetailname, '') AS companyname FROM distributor_master AS dm LEFT JOIN tbl_distributor AS td ON dm.plid = td.did LEFT JOIN tbl_businesskycdetails_distributor AS tbd ON dm.plid = tbd.did LEFT JOIN state AS st ON dm.sid = st.sid LEFT JOIN city AS ct ON dm.catid = ct.ctid LEFT JOIN country AS cu ON dm.cid = cu.cid WHERE td.did = v_did;
  -- SET option (removed)
END;
$$;


--
-- Name: usp_get_reseller_list(integer, integer, character varying, boolean, character varying, character varying, character varying, character varying, text, text, character varying, character varying, character varying, character varying, integer, character varying, character varying, character varying, character varying, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_get_reseller_list(v_startrowindex integer DEFAULT 1, v_maxrows integer DEFAULT 50, v_orderbyfield character varying DEFAULT 'ID'::character varying, v_asc boolean DEFAULT true, v_searchfield character varying DEFAULT ''::character varying, v_searchvalue character varying DEFAULT ''::character varying, v_cid character varying DEFAULT ''::character varying, v_ctid character varying DEFAULT ''::character varying, v_catid text DEFAULT ''::text, v_keyid text DEFAULT ''::text, v_fromdate character varying DEFAULT ''::character varying, v_todate character varying DEFAULT ''::character varying, v_type character varying DEFAULT 'APPROVE'::character varying, v_isverified character varying DEFAULT ''::character varying, v_mode integer DEFAULT 1, v_prop character varying DEFAULT '0'::character varying, v_pmfromdate character varying DEFAULT ''::character varying, v_pmtodate character varying DEFAULT ''::character varying, v_status character varying DEFAULT 'APPROVE'::character varying, v_intresult integer DEFAULT 0) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_recordcount INT;
  v_regno BIGINT;
  v_pmid INT;
  v_isroll VARCHAR(50);
  v_sqlquery text;
  v_minindex INT;
  v_maxindex INT;
BEGIN
  -- SET option (removed)
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp (ROWNUMBER BIGINT,
DID bigint,
LOGINID varchar(150),
DOC varchar(150),
PASSWORD varchar(150),
USERNAME varchar(150),
MEMBERNAME varchar(150),
IPADDRESS  varchar(150),
EMAILID  varchar(150),
PHONE varchar(150),
iskycapproved int,
PMID  int,
Sourceid varchar(30),
Sourcejoing varchar(30),
Active int,
status int) ON COMMIT DROP;
  v_sqlquery := '';
  v_minindex := (v_startrowindex - 1) * v_maxrows + 1;
  v_maxindex := v_startrowindex * v_maxrows;
  IF (v_type = '') THEN
  v_sqlquery := 'INSERT INTO #TEMP SELECT ROW_NUMBER() OVER(ORDER BY DOC DESC) AS ROWNUMBER,DID,LOGINID,DOC,
			PASSWORD,USERNAME,ISNULL(FNAME,'''')+''''+ISNULL(LNAME,'''') AS MEMBERNAME,isnull(IPADDRESS,'''') as IPADDRESS,
			EMAILID,PHONE,iskycapproved,isnull(PMID,0) as PMID,isnull(REFRAL_ID,''''),'''' ,PL.ACTIVE,isnull(PL.status,1)
			from TBL_DISTRIBUTOR PL where 1=1';
  ELSE
  v_sqlquery := 'INSERT INTO #TEMP SELECT ROW_NUMBER() OVER(ORDER BY PL.DOC DESC) AS ROWNUMBER,PL.DID,PL.LOGINID,PL.DOC,
			PL.PASSWORD,PL.USERNAME,ISNULL(pm.COMPANYNAME,'''') AS MEMBERNAME,isnull(PL.IPADDRESS,'''') as IPADDRESS,
			PL.EMAILID,PL.PHONE,PL.iskycapproved,isnull(PL.PMID,0) as PMID,isnull(PL.REFRAL_ID,''''),'''',PL.ACTIVE,isnull(PL.status,1)
			 from TBL_DISTRIBUTOR PL
			 join Distributor_MASTER pm on pm.PMID=PL.PMID 
			
			 where PL.iskycapproved=1 and  PL.status=1';
  END IF;
  IF (v_searchfield = 'EMAILID') THEN
  v_sqlquery := v_sqlquery || ' and EMAILID like ''%' || v_searchvalue || '%''';
  END IF;
  IF (v_type = '') THEN
  IF (v_searchfield = 'MEMBERNAME') THEN
  v_sqlquery := v_sqlquery || ' and (FNAME+LNAME) like ''%' || v_searchvalue || '%''';
  END IF;
  ELSE
  IF (v_searchfield = 'MEMBERNAME') THEN
  v_sqlquery := v_sqlquery || ' and pm.COMPANYNAME like ''%' || v_searchvalue || '%''';
  END IF;
  END IF;
  IF (v_searchfield = 'PHONE') THEN
  v_sqlquery := v_sqlquery || ' and PHONE like ''%' || v_searchvalue || '%''';
  END IF;
  IF (v_fromdate <> '' AND v_todate <> '') THEN
  v_sqlquery := v_sqlquery || (' And Convert(date,PL.DOC,105) Between Convert(date,''' || v_fromdate || ''',105) And Convert(date,''' || v_todate || ''',105)');
  END IF;
  IF (v_fromdate <> '') THEN
  v_sqlquery := v_sqlquery || (' And Convert(date,PL.DOC,105) >= Convert(date,''' || v_fromdate || ''',105)');
  END IF;
  IF (v_todate <> '') THEN
  v_sqlquery := v_sqlquery || (' And Convert(date,PL.DOC,105) <= Convert(date,''' || v_todate || ''',105)');
  END IF;
  IF (v_type = '') THEN
  IF (v_status <> '') THEN
  IF (v_status = 'APPROVE') THEN
  v_sqlquery := v_sqlquery || ' AND iskycapproved=1';
  END IF;
  IF (v_status = 'PENDING') THEN
  v_sqlquery := v_sqlquery || ' AND iskycapproved=0';
  END IF;
  END IF;
  END IF;
  EXECUTE v_sqlquery;
  RAISE NOTICE '%', (v_sqlquery);
  SELECT COUNT(1) INTO v_recordcount FROM tmp_temp;
  SELECT COUNT(COALESCE(rownumber, 0)) INTO v_intresult FROM tmp_temp;
  RETURN QUERY SELECT * FROM tmp_temp WHERE rownumber BETWEEN v_minindex AND v_maxindex;
  DROP TABLE IF EXISTS tmp_temp;
  -- SET option (removed)
END;
$$;


