--
-- Name: usp_get_resellerdatabyurl(character varying, character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_get_resellerdatabyurl(v_url character varying DEFAULT 'http://localhost:31994/reseller/41488652'::character varying, v_loginid character varying DEFAULT '27841246'::character varying) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF (v_loginid <> '') THEN
  IF EXISTS(SELECT 1 FROM tbl_distributor WHERE loginid = v_loginid) THEN
  RETURN QUERY SELECT COALESCE(dl.did, 0) AS did, COALESCE(dm.companyname, '') AS companyname, COALESCE(dm.url, '') AS companyurl, COALESCE(dm.faviconicon, '') AS companyfaviconicon, COALESCE(dm.title, '') AS companytitle, COALESCE(dm.companyimage, '') AS companylogo, COALESCE(tcs.companysendmailemailid, '') AS companyinfoemailid, COALESCE(dm.mobileno, '') AS companycontact, COALESCE(tcs.companyinfoemailid, '') AS companyinfoemailid, COALESCE(tcs.companysupportemailid, '') AS companysupportemailid, COALESCE(tcs.companysendmailemailid, '') AS companysendmailemailid, COALESCE(tcs.companynoreplyemailid, '') AS noreplymail, COALESCE(tcs.companymailserver, '') AS companymailserver, COALESCE(tcs.companymailpassowrd, '') AS companymailpassword, CAST(COALESCE(tcs.companymailserverport, '') AS INT) AS companymailserverport, COALESCE(tcs.companyresellerurl, '') AS companyresellerurl, COALESCE(tcs.companymerchanturl, '') AS companymerchanturl, COALESCE(tcs.companyadminurlforimage, '') AS adminurlforimage, COALESCE(tcs.companyapiurl, '') AS companyapiurl, COALESCE(tcs.companyadvertisement, '') AS companyadvertisement, COALESCE(tcs.companyservices, '') AS companyservices, COALESCE(tcs.companycurrency, '') AS companycurrency, COALESCE(tcs.companyoauthurl, '') AS companyoauthurl, COALESCE(tcs.companyvalidurl, '') AS companyvalidurl, COALESCE(tcs.companyscope, '') AS companyscope, COALESCE(tcs.companyclientid, '') AS companyclientid, COALESCE(tcs.companyredirect, '') AS companyredirect, COALESCE(tcs.companylogout, '') AS companylogout, COALESCE(dl.loginid, '') AS resellerloginid, COALESCE(tcs.companyfacebookclientid, '') AS facebookclientid, COALESCE(tcs.companyfacebookclientsecret, '') AS facebookclientsecret, COALESCE(tcs.companyfacebooklink, '') AS companyfacebooklink, COALESCE(tcs.companygooglepluslink, '') AS companygooglepluslink, COALESCE(tcs.companytwitterlink, '') AS companytwitterlink, COALESCE(tcs.companypinterestlink, '') AS companypinterestlink, COALESCE(tcs.companylinkedinlink, '') AS companylinkedinlink, COALESCE(tcs.smsapi, '') AS smsapi, COALESCE(tcs.dedicatedproducturl, '') AS dedicatedproducturl, COALESCE(tcs.pmid, '') AS pmid, COALESCE(dm.address || ', ' || s.statename || ', ' || dm.pincode || ', India', '') AS companyaddress, COALESCE(tcs.bvshows, 0) AS productbvintstatus, COALESCE(tcs.pvshows, 0) AS productpvintstatus, COALESCE(tcs.utilitybv, 0) AS utilitybvintstatus, COALESCE(tcs.utilitypv, 0) AS utilitypvintstatus, COALESCE(tv.remark, '') AS playstorelink FROM distributor_master AS dm LEFT JOIN tbl_distributor AS dl ON dm.plid = dl.did LEFT JOIN tbl_companysettings AS tcs ON dm.pmid = tcs.pmid LEFT JOIN state AS s ON dm.sid = s.sid LEFT JOIN tbl_version AS tv ON dm.plid = tv.did WHERE (dl.loginid = v_loginid);
  END IF;
  END IF;
  IF (v_url <> '' AND v_loginid = '') THEN
  IF EXISTS(SELECT 1 FROM distributor_master WHERE url = v_url) THEN
  RETURN QUERY SELECT COALESCE(dl.did, 0) AS did, COALESCE(dm.companyname, '') AS companyname, COALESCE(dm.url, '') AS companyurl, COALESCE(dm.faviconicon, '') AS companyfaviconicon, COALESCE(dm.title, '') AS companytitle, COALESCE(dm.companyimage, '') AS companylogo, COALESCE(tcs.companysendmailemailid, '') AS companyinfoemailid, COALESCE(dm.mobileno, '') AS companycontact, COALESCE(tcs.companyinfoemailid, '') AS companyinfoemailid, COALESCE(tcs.companysupportemailid, '') AS companysupportemailid, COALESCE(tcs.companysendmailemailid, '') AS companysendmailemailid, COALESCE(tcs.companynoreplyemailid, '') AS noreplymail, COALESCE(tcs.companymailserver, '') AS companymailserver, COALESCE(tcs.companymailpassowrd, '') AS companymailpassword, CAST(COALESCE(tcs.companymailserverport, '') AS INT) AS companymailserverport, COALESCE(tcs.companyresellerurl, '') AS companyresellerurl, COALESCE(tcs.companymerchanturl, '') AS companymerchanturl, COALESCE(tcs.companyadminurlforimage, '') AS adminurlforimage, COALESCE(tcs.companyapiurl, '') AS companyapiurl, COALESCE(tcs.companyadvertisement, '') AS companyadvertisement, COALESCE(tcs.companyservices, '') AS companyservices, COALESCE(tcs.companycurrency, '') AS companycurrency, COALESCE(tcs.companyoauthurl, '') AS companyoauthurl, COALESCE(tcs.companyvalidurl, '') AS companyvalidurl, COALESCE(tcs.companyscope, '') AS companyscope, COALESCE(tcs.companyclientid, '') AS companyclientid, COALESCE(tcs.companyredirect, '') AS companyredirect, COALESCE(tcs.companylogout, '') AS companylogout, COALESCE(dl.loginid, '') AS resellerloginid, COALESCE(tcs.companyfacebookclientid, '') AS facebookclientid, COALESCE(tcs.companyfacebookclientsecret, '') AS facebookclientsecret, COALESCE(tcs.companyfacebooklink, '') AS companyfacebooklink, COALESCE(tcs.companygooglepluslink, '') AS companygooglepluslink, COALESCE(tcs.companytwitterlink, '') AS companytwitterlink, COALESCE(tcs.companypinterestlink, '') AS companypinterestlink, COALESCE(tcs.companylinkedinlink, '') AS companylinkedinlink, COALESCE(tcs.smsapi, '') AS smsapi, COALESCE(tcs.dedicatedproducturl, '') AS dedicatedproducturl, COALESCE(tcs.pmid, '') AS pmid, COALESCE(dm.address || ', ' || s.statename || ', ' || dm.pincode || ', India', '') AS companyaddress, COALESCE(tcs.bvshows, 0) AS productbvintstatus, COALESCE(tcs.pvshows, 0) AS productpvintstatus, COALESCE(tcs.utilitybv, 0) AS utilitybvintstatus, COALESCE(tcs.utilitypv, 0) AS utilitypvintstatus, COALESCE(tv.remark, '') AS playstorelink FROM distributor_master AS dm LEFT JOIN tbl_distributor AS dl ON dm.plid = dl.did LEFT JOIN tbl_companysettings AS tcs ON dm.pmid = tcs.pmid LEFT JOIN state AS s ON dm.sid = s.sid LEFT JOIN tbl_version AS tv ON dm.plid = tv.did WHERE dm.url = v_url;
  END IF;
  END IF;
END;
$$;


--
-- Name: usp_get_resellerpurchasedpackge(bigint); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_get_resellerpurchasedpackge(v_did bigint DEFAULT 18) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_rdid INT;
  v_trpid INT;
  v_purchaseddate timestamp;
  v_active boolean;
  v_createdate timestamp;
  v_status INT;
  v_invoiceno VARCHAR(100);
  v_trsid INT;
  v_packagename VARCHAR(100);
  v_packageamount decimal;
BEGIN
  -- SET option (removed)
  INSERT INTO tbl_reseller_purchased_packages (did, trpid, purchaseddate, active, createdate, status, invoiceno, trsid) VALUES (v_did, v_trpid, v_purchaseddate, v_active, v_createdate, v_status, v_invoiceno, v_trsid);
  RETURN QUERY SELECT rp.packagename, rp.packageamount FROM tbl_reseller_purchased_packages AS rpp INNER JOIN tbl_reseller_packages AS rp ON rpp.trpid = rp.trpid WHERE rpp.did = 18;
  SELECT rp.packagename, rp.packageamount INTO v_packagename, v_packageamount FROM tbl_reseller_packages AS rp INNER JOIN tbl_reseller_purchased_packages AS rpp ON rpp.trpid = rp.trpid WHERE rpp.did = 18;
  RETURN QUERY SELECT v_packagename || ' (' || CAST(v_packageamount AS VARCHAR(100)) || ')' AS purchaseddetails;
  RETURN QUERY SELECT * FROM tbl_reseller_packages ORDER BY trpid DESC NULLS LAST;
END;
$$;


--
-- Name: usp_get_resellersetting(integer, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_get_resellersetting(v_did integer DEFAULT 1, v_output integer DEFAULT 0) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_iskyc INT;
  v_businessinfo INT;
  v_isaggrement INT;
  v_issetting INT;
  v_iswallet INT;
BEGIN
  -- BEGIN TRAN (removed)
  v_did := 1;
  -- SET option (removed)
  v_iskyc := 0;
  v_businessinfo := 0;
  v_isaggrement := 0;
  v_issetting := 0;
  v_iswallet := 0;
  IF (v_did = 0) THEN
  -- COMMIT (removed)
  RETURN;
  END IF;
  IF (v_did > 0) THEN
  SELECT COUNT(1) INTO v_iskyc FROM tbl_distributor WHERE did = v_did AND iskycapproved = 1 AND status = 1;
  SELECT COUNT(1) INTO v_businessinfo FROM distributor_master WHERE plid = v_did;
  SELECT COUNT(1) INTO v_isaggrement FROM tbl_agreement_details_distributor WHERE did = v_did AND status = 1;
  SELECT COUNT(1) INTO v_iswallet FROM tbl_distributor_prepaid_setting WHERE pmid IN (SELECT pmid FROM distributor_master WHERE plid = v_did) AND available_wallet >= 10000;
  SELECT COUNT(1) INTO v_issetting FROM tbl_companysettings WHERE companysendmailemailid <> '' AND companymailpassowrd <> '' AND companymailserverport <> '' AND companypgmerchantkey <> '' AND companypgsalt <> '' AND smsapi <> '' AND pmid IN (SELECT pmid FROM distributor_master WHERE plid = v_did);
  RETURN QUERY SELECT v_iskyc, v_businessinfo, v_isaggrement, v_iswallet, v_issetting;
  IF (v_iskyc = 1 AND v_businessinfo = 1 AND v_isaggrement = 1 AND v_iswallet = 1 AND v_issetting = 1) THEN
  v_output := 1;
  ELSE
  v_output := 0;
  END IF;
  IF (v_did = 1) THEN
  v_output := 1;
  END IF;
  END IF;
  -- SET option (removed)
  -- COMMIT (removed)
END;
$$;


