--
-- Name: usp_get_resellerwise_allrecharge_reports(integer, integer, integer, character varying, character varying, integer, character varying, character varying, character varying, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_get_resellerwise_allrecharge_reports(v_mode integer DEFAULT 1, v_startrowindex integer DEFAULT 1, v_maxrows integer DEFAULT 100, v_fromdate character varying DEFAULT ''::character varying, v_todate character varying DEFAULT ''::character varying, INOUT v_totalcount integer DEFAULT 0, v_searchfield character varying DEFAULT ''::character varying, v_searchvalue character varying DEFAULT ''::character varying, v_status character varying DEFAULT ''::character varying, v_did integer DEFAULT 8) RETURNS integer
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_minindex INT;
  v_maxindex INT;
  v_query text;
  v_condition text;
  v_countquery text;
  v_parmdefinition varchar(70);
BEGIN
  -- BEGIN TRAN (removed)
  -- SET option (removed)
  v_condition := '';
  v_countquery := '';
  v_minindex := (v_startrowindex - 1) * v_maxrows + 1;
  v_maxindex := v_startrowindex * v_maxrows;
  IF (v_mode = 1) THEN
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp (ROWNUMBER BIGINT GENERATED BY DEFAULT AS IDENTITY,
ID BIGINT,
CLID BIGINT,
NAME VARCHAR(100),
MOBILENO VARCHAR(100),
OPERATORTYPE VARCHAR(100),
OPERRATORNAME VARCHAR(100),
OPERATORSERVICE VARCHAR(100),
AMOUNT DECIMAL(18,2),
STATUS VARCHAR(100),
TRANSACTIONID VARCHAR(100),
RECHARGEDATE VARCHAR(100),
ISANDROIDORWEB INT,
MLMWALLET DECIMAL(18,2),
CUSWTOMERWALLET DECIMAL(18,2),
ONLINEAMOUNT DECIMAL(18,2),
REMARKS VARCHAR(1000)) ON COMMIT DROP;
  END IF;
  v_query := 'INSERT INTO #TEMP SELECT TCPR.TCPRID,TCPR.CLID,(CL.FNAME+'' ''+CL.LNAME),TCPR.MOBILENO,TCPR.OPERATORTYPE,
TCPR.OPERATORNAME,TCPR.OPERATORSERVICE,TCPR.RECHARGEAMOUNT,TCPR.RECHARGESTATUS,TCPR.TRANSACTIONID,
TCPR.RECHARGEDATE,TCPR.ISANDROIDORWEB, ISNUll(TROP.MLMWALLET,0),ISNULL(TROP.CUSTOMERWALLET,0),ISNULL(TROP.OnlineAmount,0),
ISNULL(TCPR.RESPONSEREMARKS,'''')
FROM TBL_CUSTOMER_POSTPAID_RECHARGES TCPR
LEFT JOIN TBL_CUSTOMERLOGIN CL ON CL.CLID=TCPR.CLID
LEFT JOIN TBL_RECHARGEONLINEPAYMENTSDETAILS TROP ON TCPR.TRANSACTIONID=TROP.TRANSID
 WHERE 1=1 and TCPR.RECHARGESTATUS!=''NULL'' and  CL.DID=''' || CAST(v_did AS VARCHAR(30)) || '''';
  v_query := v_query || ' INSERT INTO #TEMP SELECT TCPR.TCPRID,TCPR.CLID,(CL.FNAME+'' ''+CL.LNAME),TCPR.MOBILENO,TCPR.OPERATORTYPE,
TCPR.OPERATORNAME,TCPR.OPERATORSERVICE,TCPR.RECHARGEAMOUNT,TCPR.RECHARGESTATUS,TCPR.TRANSACTIONID,TCPR.RECHARGEDATE,TCPR.ISANDROIDORWEB,
ISNUll(TROP.MLMWALLET,0),ISNULL(TROP.CUSTOMERWALLET,0),ISNULL(TROP.OnlineAmount,0),
ISNULL(TCPR.RESPONSEREMARKS,'''')
FROM TBL_CUSTOMER_PREPAID_RECHARGES TCPR  
LEFT JOIN TBL_CUSTOMERLOGIN CL ON CL.CLID=TCPR.CLID
LEFT JOIN TBL_RECHARGEONLINEPAYMENTSDETAILS TROP ON TCPR.TRANSACTIONID=TROP.TRANSID
 WHERE 1=1 and TCPR.RECHARGESTATUS!=''NULL'' and  CL.DID=''' || CAST(v_did AS VARCHAR(30)) || '''';
  v_query := v_query || ' INSERT INTO #TEMP SELECT TCDR.TCDRID,TCDR.CLID,(CL.FNAME+'' ''+CL.LNAME),TCDR.MOBILENO,TCDR.OPERATORTYPE,
TCDR.OPERATORNAME,TCDR.OPERATORSERVICE,TCDR.RECHARGEAMOUNT,TCDR.RECHARGESTATUS,TCDR.TRANSACTIONID,TCDR.RECHARGEDATE,TCDR.ISANDROIDORWEB,
ISNUll(TROP.MLMWALLET,0),ISNULL(TROP.CUSTOMERWALLET,0),ISNULL(TROP.OnlineAmount,0),
ISNULL(TCDR.RESPONSEREMARKS,'''')
FROM TBL_CUSTOMER_DTH_RECHARGES TCDR  
LEFT JOIN TBL_CUSTOMERLOGIN CL ON CL.CLID=TCDR.CLID
LEFT JOIN TBL_RECHARGEONLINEPAYMENTSDETAILS TROP ON TCDR.TRANSACTIONID=TROP.TRANSID
 WHERE 1=1 and TCDR.RECHARGESTATUS!=''NULL'' and CL.DID=''' || CAST(v_did AS VARCHAR(30)) || '''';
  v_query := v_query || ' INSERT INTO #TEMP SELECT TCER.TCERID,TCER.CLID,(CL.FNAME+'' ''+CL.LNAME),TCER.MOBILENO,TCER.OPERATORTYPE,
TCER.OPERATORNAME,TCER.OPERATORSERVICE,TCER.RECHARGEAMOUNT,TCER.RECHARGESTATUS,TCER.TRANSACTIONID,TCER.RECHARGEDATE,TCER.ISANDROIDORWEB,
ISNUll(TROP.MLMWALLET,0),ISNULL(TROP.CUSTOMERWALLET,0),ISNULL(TROP.OnlineAmount,0),
ISNULL(TCER.RESPONSEREMARKS,'''')
FROM TBL_CUSTOMER_ELECTRICITY_RECHARGES TCER
LEFT JOIN TBL_CUSTOMERLOGIN CL ON CL.CLID=TCER.CLID
LEFT JOIN TBL_RECHARGEONLINEPAYMENTSDETAILS TROP ON TCER.TRANSACTIONID=TROP.TRANSID
 WHERE 1=1 and TCER.RECHARGESTATUS!=''NULL'' and CL.DID=''' || CAST(v_did AS VARCHAR(30)) || '''';
  v_query := v_query || ' INSERT INTO #TEMP SELECT TCGR.TCGRID,TCGR.CLID,(CL.FNAME+'' ''+CL.LNAME),TCGR.MOBILENO,TCGR.OPERATORTYPE,
TCGR.OPERATORNAME,TCGR.OPERATORSERVICE,TCGR.RECHARGEAMOUNT,TCGR.RECHARGESTATUS,TCGR.TRANSACTIONID,TCGR.RECHARGEDATE,TCGR.ISANDROIDORWEB,
ISNUll(TROP.MLMWALLET,0),ISNULL(TROP.CUSTOMERWALLET,0),ISNULL(TROP.OnlineAmount,0),
ISNULL(TCGR.RESPONSEREMARKS,'''')
FROM TBL_CUSTOMER_GAS_RECHARGES TCGR
LEFT JOIN  TBL_CUSTOMERLOGIN CL ON CL.CLID=TCGR.CLID
LEFT JOIN TBL_RECHARGEONLINEPAYMENTSDETAILS TROP ON TCGR.TRANSACTIONID=TROP.TRANSID
 WHERE 1=1 and TCGR.RECHARGESTATUS!=''NULL'' and CL.DID=''' || CAST(v_did AS VARCHAR(30)) || '''';
  EXECUTE v_query;
  v_query := '';
  v_query := 'SELECT ROWNUMBER,ID,CLID,NAME,MOBILENO,OPERATORTYPE,OPERRATORNAME,OPERATORSERVICE,AMOUNT,STATUS,TRANSACTIONID,RECHARGEDATE,ISANDROIDORWEB,MLMWALLET,CUSWTOMERWALLET,ONLINEAMOUNT,REMARKS  INTO #MAINDATA FROM #TEMP WHERE 1=1 ';
  IF ((v_fromdate <> '') AND (v_todate = '')) THEN
  v_condition := v_condition || (' AND CONVERT(DATE,RECHARGEDATE,105) BETWEEN  CONVERT(DATE, ''' || v_fromdate || ''',105) AND  CONVERT(DATE, DBO.FUN_GETCURRENTDATE(),105)');
  END IF;
  IF ((v_fromdate = '') AND (v_todate <> '')) THEN
  v_condition := v_condition || ('AND CONVERT(DATE, RECHARGEDATE, 105) BETWEEN  CONVERT(DATE, ''' || v_todate || ''', 105) AND  CONVERT(DATE, DBO.FUN_GETCURRENTDATE(), 105)');
  END IF;
  IF ((v_fromdate <> '') AND (v_todate <> '')) THEN
  v_condition := v_condition || ('AND CONVERT(DATE, RECHARGEDATE, 105) BETWEEN  CONVERT(DATE, ''' || v_fromdate || ''', 105) AND  CONVERT(DATE, ''' || v_todate || ''', 105)');
  END IF;
  IF (v_searchfield <> '' AND v_searchvalue <> '') THEN
  IF (v_searchfield = 'PHONE') THEN
  v_condition := v_condition || ' AND MOBILENO LIKE ''%' || v_searchvalue || '%'' ';
  END IF;
  IF (v_searchfield = 'OPERRATORNAME') THEN
  v_condition := v_condition || ' AND OPERRATORNAME LIKE ''%' || v_searchvalue || '%'' ';
  END IF;
  IF (v_searchfield = 'MOBILENO') THEN
  v_condition := v_condition || ' AND MOBILENO LIKE ''%' || v_searchvalue || '%'' ';
  END IF;
  IF (v_searchfield = 'TRANSACTIONID') THEN
  v_condition := v_condition || ' AND TRANSACTIONID LIKE ''%' || v_searchvalue || '%'' ';
  END IF;
  IF (v_searchfield = 'NAME') THEN
  v_condition := v_condition || ' AND NAME LIKE ''%' || v_searchvalue || '%'' ';
  END IF;
  END IF;
  IF (v_status = 'FAILED') THEN
  v_condition := v_condition || ' AND (STATUS=''FAILED'' OR STATUS=''ERROR'')  ';
  END IF;
  IF (v_status <> '' AND v_status <> 'FAILED') THEN
  v_condition := v_condition || ' AND STATUS like ''' || v_status || ''' ';
  END IF;
  v_condition := v_condition || ' ORDER BY CONVERT(DATE,RECHARGEDATE,105) DESC  ';
  v_query := v_query || v_condition || ' ;SELECT ROW_NUMBER() OVER (ORDER BY CLID DESC ) ROW,  *  FROM #MAINDATA WHERE ROWNUMBER BETWEEN ' || CAST(v_minindex AS VARCHAR(70)) || ' AND ' || CAST(v_maxindex AS VARCHAR(70)) || '  ORDER BY CONVERT(DATE,RECHARGEDATE,105) DESC';
  v_parmdefinition := N'@TOTALCOUNT NVARCHAR(70) OUTPUT';
  v_countquery := ' ;SELECT @TOTALCOUNT=COUNT(1) FROM #TEMP ';
  EXECUTE v_countquery;
  EXECUTE v_query;
  RAISE NOTICE '%', v_query;
  DROP TABLE IF EXISTS tmp_temp;
  -- SET option (removed)
  -- COMMIT (removed)
END;
$$;


--
-- Name: usp_get_resellerwisepurchasepackage(integer, integer, integer, character varying, character varying, integer, character varying, character varying, character varying, integer, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_get_resellerwisepurchasepackage(v_mode integer DEFAULT 0, v_startrowindex integer DEFAULT 1, v_maxrows integer DEFAULT 100, v_fromdate character varying DEFAULT ''::character varying, v_todate character varying DEFAULT ''::character varying, v_totalcount integer DEFAULT 0, v_searchfield character varying DEFAULT ''::character varying, v_searchvalue character varying DEFAULT ''::character varying, v_status character varying DEFAULT ''::character varying, v_ddlservice integer DEFAULT 0, v_ddlpackage integer DEFAULT 0) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_minindex INT;
  v_maxindex INT;
  v_query text;
  v_gstpercentage decimal(18,2);
BEGIN
  v_gstpercentage := 0;
  v_minindex := (v_startrowindex - 1) * v_maxrows + 1;
  v_maxindex := v_startrowindex * v_maxrows;
  SELECT COALESCE(limits, 18.00) INTO v_gstpercentage FROM settings WHERE caption = 'GST Percentage';
  IF (v_mode = 0) THEN
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp (ROWNUMBER BIGINT GENERATED BY DEFAULT AS IDENTITY, 
	COMPANYNAME VARCHAR(100),
	SERVICENAME VARCHAR(100),
	PACKAGENAME VARCHAR(100),
	AMOUNT DECIMAL(18,2),
	PURCHASEDATE VARCHAR(100),
	GSTAMOUNT DECIMAL(18,2),
	INVOICENUMBER VARCHAR(100),
	DISCOUNT DECIMAL(18,2),
	DID INT,
	TRSID INT) ON COMMIT DROP;
  v_query := 'INSERT INTO #TEMP SELECT ISNULL(DM.COMPANYNAME,''''),ISNULL(TRS.SERVICENAME,''''),
ISNULL(RP.PACKAGENAME,''''),ISNULL(TRPI.Amount,0),
 CONVERT(VARCHAR(100),RPP.PURCHASEDDATE,106),
ISNULL(TRPI.Amount*''' || CAST(v_gstpercentage AS VARCHAR(30)) || ''',0)/100,
ISNULL(RPP.INVOICENO,''''),ISNULL(TRA.DISCOUNT,0),ISNULL(RPP.DID,0),
ISNULL(RPP.TRSID,0)
FROM TBL_RESELLER_PURCHASED_PACKAGES RPP
LEFT JOIN TBL_RESELLER_PACKAGES RP ON RPP.TRPID=RP.TRPID
LEFT JOIN DISTRIBUTOR_MASTER DM ON RPP.DID=DM.PLID
LEFT JOIN TBL_RESELLER_SERVICES TRS ON RP.TRSID=TRS.TRSID 
LEFT JOIN TBL_RESELLERPURCHASEDPACKAGES_BY_ADMIN TRA ON  RPP.DID=TRA.DID AND RPP.TRPID=TRA.TRPID AND TRA.Active=1
LEFT JOIN TBL_RESELLER_PACKAGE_INVOICE TRPI ON RPP.INVOICENO=TRPI.INVOICENUMBER
where RPP.ACTIVE=1  and DM.ACTIVE=1 ';
  IF ((v_fromdate <> '') AND (v_todate = '')) THEN
  v_query := v_query || ' AND CONVERT(DATE, RPP.CREATEDATE, 105) BETWEEN  CONVERT(DATE, ''' || v_fromdate || ''', 105) AND  CONVERT(DATE, DBO.FUN_GETCURRENTDATE(), 105)';
  END IF;
  IF ((v_fromdate = '') AND (v_todate <> '')) THEN
  v_query := v_query || 'AND CONVERT(DATE, RPP.CREATEDATE, 105) BETWEEN  CONVERT(DATE, ''' || v_todate || ''', 105) AND  CONVERT(DATE, DBO.FUN_GETCURRENTDATE(), 105)';
  END IF;
  IF ((v_fromdate <> '') AND (v_todate <> '')) THEN
  v_query := v_query || 'AND CONVERT(DATE, RPP.CREATEDATE, 105) BETWEEN CONVERT(DATE, ''' || v_fromdate || ''', 105) AND  CONVERT(DATE, ''' || v_todate || ''', 105)';
  END IF;
  IF (v_ddlservice > 0) THEN
  v_query := v_query || '  AND TRS.TRSID =''' || CAST(v_ddlservice AS VARCHAR) || '''';
  END IF;
  IF (v_ddlpackage > 0) THEN
  v_query := v_query || '  AND RPP.TRPID =''' || CAST(v_ddlpackage AS VARCHAR) || '''';
  END IF;
  v_query := v_query || ' ORDER BY RPP.CREATEDATE DESC';
  EXECUTE v_query;
  RAISE NOTICE '%', v_query;
  RETURN QUERY SELECT * FROM tmp_temp WHERE rownumber BETWEEN v_minindex AND v_maxindex;
  SELECT COUNT(rownumber) INTO v_totalcount FROM tmp_temp;
  DROP TABLE IF EXISTS tmp_temp;
  -- SET option (removed)
  END IF;
END;
$$;


--
-- Name: usp_get_sponsorlist(character varying, character varying, character varying, character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_get_sponsorlist(v_datefrom character varying DEFAULT ''::character varying, v_dateto character varying DEFAULT ''::character varying, v_status character varying DEFAULT ''::character varying, v_cid character varying DEFAULT ''::character varying) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_query text;
BEGIN
  v_query := '';
  v_query := 'select  ROW_NUMBER() over(order by sl.slid desc) as rownumber,smd.slid,sl.loginid,(smd.fname+'' ''+smd.lname) as

 Name,sl.password,smd.cid

,(case when sl.active=1 then ' || CAST('''Active''' AS VARCHAR(50)) || '  when sl.active=0 then ' || CAST('''Pending''' AS VARCHAR(50)) || ' 

else ' || CAST('''Deactive''' AS VARCHAR(50)) || ' end)as active

,(case when smd.Remark is null then ' || CAST('''No Remark''' AS VARCHAR(50)) || '

 when smd.Remark='''' then ' || CAST('''No Remark''' AS VARCHAR(50)) || ' else smd.Remark end)as Remark,

 (CASE WHEN smd.DOC IS not NULL THEN convert(varchar(10),smd.DOC, 101) ELSE ''-''  END) AS  DOC,

 (CASE WHEN smd.registerdate IS not NULL THEN convert(varchar(10),smd.registerdate, 101) ELSE ''-''  END) AS  registerdate

 from sponsor_login as sl join sponsor_master_detail smd on sl.slid=smd.slid where smd.slid<>0';
  IF (v_datefrom <> '' AND v_dateto <> '') THEN
  v_query := v_query || ' and convert(date,smd.DOC) between ''' || CAST(v_datefrom AS VARCHAR(200)) || ''' and ''' || CAST(v_dateto AS VARCHAR(200)) || '''';
  ELSE
  IF (v_datefrom <> '') THEN
  v_query := v_query || ' and convert(date,smd.DOC) >= ''' || CAST(v_datefrom AS VARCHAR(200)) || '''';
  END IF;
  END IF;
  IF (v_status <> '') THEN
  v_query := v_query || ' and sl.active=''' || v_status || '''';
  END IF;
  IF (v_cid <> '') THEN
  v_query := v_query || ' and smd.cid=''' || v_cid || '''';
  END IF;
  EXECUTE v_query;
END;
$$;


--
-- Name: usp_get_stock_in_store_list(integer, integer, character varying, character varying, character varying, character varying, integer, bigint); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_get_stock_in_store_list(v_startrowindex integer DEFAULT 1, v_maxrows integer DEFAULT 1000, v_fromdate character varying DEFAULT ''::character varying, v_todate character varying DEFAULT ''::character varying, v_searchfiel character varying DEFAULT ''::character varying, v_searchvalue character varying DEFAULT ''::character varying, v_totalcount integer DEFAULT 0, v_branchid bigint DEFAULT 1) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_minindex INT;
  v_maxindex INT;
  v_query text;
BEGIN
  -- SET option (removed)
  v_minindex := (v_startrowindex - 1) * v_maxrows + 1;
  v_maxindex := v_startrowindex * v_maxrows;
  DROP TABLE IF EXISTS tmp_stock_in_store_list;
  CREATE TEMP TABLE tmp_stock_in_store_list (ROWNUMBER BIGINT,
	SPRID BIGINT ,
	CATEGORYNAME VARCHAR(150),
	PRODUCTNAME VARCHAR(150),
	GST  decimal(18,8),
	STOCKIN int,
	STOCKOUT int,
	STOCKNET int,
	SELLMRP decimal(18,8),
	DAP decimal(18,8),
	MERCHANTNAME varchar(250),
	Discountpercentage decimal,
	Subcategory varchar(200),
	ProductImages varchar(1000),
	SubPrCode varchar(1000),
	Title varchar(1000),
	Value varchar(1000)) ON COMMIT DROP;
  v_query := 'INSERT INTO #STOCK_IN_STORE_LIST SELECT ROW_NUMBER() OVER(ORDER BY IST.SPRID ) AS ROWNUMBER,IST.SPRID, 
ISNULL(TMC.MAINCATNAME,'''') AS CATEGORYNAME, ISNULL(IM.PRODUCTTITLE,'''') AS PRODUCTNAME,ISNULL(TVC.VATPERCVALUE,0) AS GST,
ISNULL(IST.STOCKIN,0) AS STOCKIN,ISNULL(IST.STOCKOUT,0) AS STOCKOUT,ISNULL(IST.STOCKNET,0) AS STOCKNET,
ISNULL(IST.SELLMRP,0) AS SELLMRP ,ISNULL(IST.DAP,0) AS DAP,ISNULL((PL.FNAME+PL.LNAME),'''') AS MERCHANTNAME,
isnull(DiscountPercentage,0),isnull(km.KEYWORDNAME,'''') as Subcategory,isnull(IST.ProductImages,'''') as ProductImages,isnull(IST.SubPrCode,'''') as SubPrCode,isnull(IMA.Title,'''') as Title,isnull(IMA.Value,'''') as Value FROM IMS_SUBPRODUCT IST 
JOIN IMS_MASTERPRODUCT IM ON IM.MPRID=IST.MPRID 
JOIN TBL_MAIN_CATEGORY TMC ON TMC.MAINCATID=IM.MainCategoryId
JOIN TBL_VAT_CATEGORIES TVC ON TVC.VCID=IM.VATCATEGORYID
JOIN PORTAL_LOGIN PL ON PL.PLID=IM.BRANCHID
 join KEYWORD_MASTER km on IM.SubCategoryId=km.KMID
 left join IMS_MASTERPRODUCTATTRIBUTE IMA ON IMA.SPRID=IST.SPRID
 WHERE 1=1 ';
  IF ((v_searchfiel <> '') AND (v_searchvalue <> '')) THEN
  IF (v_searchfiel = 'PRODUCTNAME') THEN
  v_query := v_query || ' And IM.PRODUCTTITLE like ''%' || v_searchvalue || '%''';
  END IF;
  IF (v_searchfiel = 'CATEGORYNAME') THEN
  v_query := v_query || ' And TMC.MAINCATNAME like ''%' || v_searchvalue || '%''';
  END IF;
  IF (v_searchfiel = 'RANGE') THEN
  v_query := v_query || ' And IST.STOCKIN<=' || CAST(v_searchvalue AS VARCHAR(50)) || '';
  END IF;
  IF (v_searchfiel = 'MERCHANTNAME') THEN
  v_query := v_query || ' And ISNULL((PL.FNAME+PL.LNAME),'''') like ''%' || v_searchvalue || '%''';
  END IF;
  END IF;
  IF (v_branchid > 0) THEN
  v_query := v_query || ' AND  IM.BRANCHID=' || CAST(v_branchid AS VARCHAR(50)) || '';
  END IF;
  EXECUTE v_query;
  RETURN QUERY SELECT * FROM tmp_stock_in_store_list WHERE rownumber BETWEEN v_minindex AND v_maxindex;
  SELECT COUNT(rownumber) INTO v_totalcount FROM tmp_stock_in_store_list;
  DROP TABLE IF EXISTS tmp_stock_in_store_list;
  -- SET option (removed)
END;
$$;


--
-- Name: usp_get_suggest_similarkeyword_byslid(integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_get_suggest_similarkeyword_byslid(v_slid integer DEFAULT 0) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
BEGIN
  RETURN QUERY SELECT ROW_NUMBER() OVER (ORDER BY ssk.sskid DESC NULLS LAST) AS rownumber, ssk.slid, pc.catname, km.keywordname, ssk.suggestdate, (CASE WHEN ssk.status = 0 THEN 'Pending' WHEN ssk.status = 1 THEN 'Active' WHEN ssk.status = 2 THEN 'Rejected' WHEN ssk.status = 3 THEN 'Already Exist' END) AS status FROM tbl_suggest_similar_keyword AS ssk JOIN product_category AS pc ON ssk.catid = pc.catid JOIN keyword_master AS km ON ssk.kmid = km.kmid WHERE ssk.slid = v_slid;
END;
$$;


--
-- Name: usp_get_suggested_similar_keyword(character varying, character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_get_suggested_similar_keyword(v_datefrom character varying DEFAULT ''::character varying, v_dateto character varying DEFAULT ''::character varying) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_query text;
BEGIN
  v_query := '';
  v_query := 'select  ROW_NUMBER() over(order by ssk.sskid desc) as rownumber,ssk.slid,ssk.loginid,



pc.catname, km.keywordname,ssk.suggestdate,



(case when ssk.status=0 then ' || CAST('''Pending''' AS VARCHAR(50)) || ' when ssk.status=1 then ' || CAST('''Active''' AS VARCHAR(50)) || ' 



when ssk.status=2 then ' || CAST('''Rejected''' AS VARCHAR(50)) || ' when



ssk.status=3 then ' || CAST('''Already Exist''' AS VARCHAR(50)) || ' end) as status from tbl_suggest_similar_keyword ssk join  Product_Category pc on ssk.catid=pc.catId join keyword_master km on ssk.kmid=km.kmid ';
  IF (v_datefrom <> '' AND v_dateto <> '') THEN
  v_query := v_query || ' where convert(date,ssk.suggestdate) between ''' || CAST(v_datefrom AS VARCHAR(200)) || ''' and ''' || CAST(v_dateto AS VARCHAR(200)) || '''';
  ELSE
  IF (v_datefrom <> '') THEN
  v_query := v_query || ' where convert(date,ssk.suggestdate) >= ''' || CAST(v_datefrom AS VARCHAR(200)) || '''';
  END IF;
  END IF;
  EXECUTE v_query;
END;
$$;


--
-- Name: usp_get_supervalueoffers_products(integer, integer, integer, character varying, character varying, integer, integer, integer, character varying, integer, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_get_supervalueoffers_products(v_maincatid integer DEFAULT 0, v_catid integer DEFAULT 0, v_subcatid integer DEFAULT 0, v_sorting character varying DEFAULT ''::character varying, v_querystring character varying DEFAULT ''::character varying, v_pageno integer DEFAULT 1, v_noofrows integer DEFAULT 100, v_plid integer DEFAULT 0, v_ipaddress character varying DEFAULT ''::character varying, v_totalcount integer DEFAULT 0, v_did integer DEFAULT 1) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_mindiscount DECIMAL(18,2);
  v_maxdiscount DECIMAL(18,2);
BEGIN
  BEGIN
  v_mindiscount := NULL;
  v_maxdiscount := NULL;
  SELECT CASE WHEN COALESCE(v_maxdiscount, 0) = 0 THEN MAX(discountpercentage) ELSE v_maxdiscount END, CASE WHEN COALESCE(v_mindiscount, 0) = 0 THEN MIN(discountpercentage) ELSE v_mindiscount END INTO v_maxdiscount, v_mindiscount FROM ims_subproduct WHERE discountpercentage > 0;
  DROP TABLE IF EXISTS tmp_supervalueoffersproductsdata;
  CREATE TEMP TABLE tmp_supervalueoffersproductsdata ON COMMIT DROP AS SELECT DISTINCT pm.producttitle, CAST(pm.mprid AS BIGINT) AS mprid, COALESCE(CAST(pm.maincategoryid AS BIGINT), 0) AS maincategoryid, CAST(pm.subcategoryid AS BIGINT) AS subcategoryid, pm.shotdescription, pm.keyfeatures, CAST(pm.catid AS BIGINT) AS catid, pms.discountpercentage, CAST(pms.sprid AS BIGINT) AS sprid, pms.subprcode, pms.productimages, pms.actualprice, pms.sellmrp, pms.dap, COALESCE(tmc.main_cat_code, '') AS main_cat_code, COALESCE(tsb.sub_cat_code, '') AS sub_cat_code, COALESCE(c.cat_code, '') AS cat_code, CAST(0 AS BIGINT) AS rowno, '' AS productcode, '' AS fulldescription, 0 AS masterproductattriubuteid, '' AS attributetitle, '' AS attributevalue, 0 AS ratingstar, '' AS dealsids, pm.createddate AS createddate, pm.modifydate AS modifydate, 0 AS replacementday, 0 AS procurementsla, CAST(0 AS BIT) AS cashondelivery, CAST(0 AS DECIMAL) AS shippingcharges, 0 AS stockin, 0 AS stockout, 0 AS stocknet, CAST(0 AS BIT) AS isoutofstock, (CASE WHEN COALESCE(CAST(pms.bv AS DECIMAL), 0) = 0 THEN ((COALESCE(CAST((pms.dap + (pms.dap * vc.vatpercvalue) / 100) AS DECIMAL(18, 2)), 0) * COALESCE(tsb.bvper, 0)) / 100) ELSE pms.bv END) AS bv, (CASE WHEN COALESCE(CAST(pms.activationpv_per AS DECIMAL), 0) = 0 THEN ((COALESCE(CAST((pms.dap + (pms.dap * vc.vatpercvalue) / 100) AS DECIMAL(18, 2)), 0) * COALESCE(tsb.activationpv_per, 0)) / 100) ELSE pms.activationpv_per END) AS activationpv, (CASE WHEN COALESCE(CAST(pms.pv AS DECIMAL), 0) = 0 THEN ((COALESCE(CAST((pms.dap + (pms.dap * vc.vatpercvalue) / 100) AS DECIMAL(18, 2)), 0) * COALESCE(tsb.redeemcashback_per, 0)) / 100) ELSE pms.pv END) AS pv, (CASE WHEN COALESCE(CAST(pms.cashback_per AS DECIMAL), 0) = 0 THEN ((COALESCE(CAST((pms.dap + (pms.dap * vc.vatpercvalue) / 100) AS DECIMAL(18, 2)), 0) * COALESCE(tsb.cashback_per, 0)) / 100) ELSE pms.cashback_per END) AS cashback, CAST((pms.dap + (pms.dap * vc.vatpercvalue) / 100) AS DECIMAL(18, 2)) AS includingtax, pms.prskucode FROM ims_masterproduct AS pm LEFT OUTER JOIN ims_subproduct AS pms ON pms.mprid = pm.mprid LEFT OUTER JOIN ims_masterproductattribute AS pa ON pa.sprid = pms.sprid LEFT OUTER JOIN tbl_category AS c ON pm.catid = c.catid LEFT OUTER JOIN portal_login AS br ON br.plid = pm.branchid LEFT OUTER JOIN tbl_sub_category AS tsb ON pm.subcategoryid = tsb.subcatid LEFT OUTER JOIN tbl_main_category AS tmc ON tsb.maincatid = tmc.maincatid LEFT OUTER JOIN tbl_product_wise_bv_pv_setting AS tpwbvs ON tmc.maincatid = tpwbvs.maincatid AND tsb.subcatid = tpwbvs.subcatid AND c.catid = tpwbvs.catid LEFT OUTER JOIN tbl_customerlogin AS tcl ON tpwbvs.did = tcl.did LEFT OUTER JOIN tbl_vat_categories AS vc ON pms.vatcategoryid = vc.vcid WHERE pms.isactive = 1 AND pms.isverified = 1 AND COALESCE(isverified, 0) = 1 AND tsb.status = 1 AND tmc.status = 1 AND br.status = 1 AND pms.discountpercentage > 0;
  RETURN QUERY SELECT * FROM (SELECT *, ROW_NUMBER() OVER (PARTITION BY catid ORDER BY sprid DESC NULLS LAST) AS rn FROM tmp_supervalueoffersproductsdata) AS a WHERE rn = 1 ORDER BY discountpercentage DESC NULLS LAST LIMIT 12;
  DROP TABLE IF EXISTS tmp_supervalueoffersproductsdata;
  v_totalcount := 30;
  -- SET option (removed)
  EXCEPTION WHEN OTHERS THEN
  v_totalcount := 0;
  END;
END;
$$;


--
-- Name: usp_get_supervalueoffers_products_mobile(integer, integer, integer, character varying, character varying, integer, integer, integer, character varying, integer, integer, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_get_supervalueoffers_products_mobile(v_maincatid integer DEFAULT 0, v_catid integer DEFAULT 0, v_subcatid integer DEFAULT 0, v_sorting character varying DEFAULT ''::character varying, v_querystring character varying DEFAULT ''::character varying, v_pageno integer DEFAULT 1, v_noofrows integer DEFAULT 100, v_plid integer DEFAULT 0, v_ipaddress character varying DEFAULT ''::character varying, v_totalcount integer DEFAULT 0, v_did integer DEFAULT 1, v_getclid integer DEFAULT 0) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_dynamicurl varchar(100);
  v_merchantproductlargeimage varchar(250);
  v_mindiscount DECIMAL(18,2);
  v_maxdiscount DECIMAL(18,2);
BEGIN
  BEGIN
  v_dynamicurl := '';
  v_merchantproductlargeimage := '';
  SELECT merchantimagepath, merchantproductlargeimage INTO v_dynamicurl, v_merchantproductlargeimage FROM tbl_company;
  v_mindiscount := NULL;
  v_maxdiscount := NULL;
  SELECT CASE WHEN COALESCE(v_maxdiscount, 0) = 0 THEN MAX(discountpercentage) ELSE v_maxdiscount END, CASE WHEN COALESCE(v_mindiscount, 0) = 0 THEN MIN(discountpercentage) ELSE v_mindiscount END INTO v_maxdiscount, v_mindiscount FROM ims_subproduct WHERE discountpercentage > 0;
  DROP TABLE IF EXISTS tmp_supervalueoffersproductsdata;
  CREATE TEMP TABLE tmp_supervalueoffersproductsdata ON COMMIT DROP AS SELECT DISTINCT pm.producttitle AS producttitle, COALESCE(CAST(pm.maincategoryid AS BIGINT), 0) AS maincategoryid, CAST(pm.subcategoryid AS BIGINT) AS subcategoryid, CAST(pm.catid AS BIGINT) AS catid, pms.discountpercentage AS discountpercentage, CAST(pms.sprid AS BIGINT) AS sprid, pms.subprcode AS productcode, (pms.productimages) AS productimages, pms.sellmrp AS sellmrp, pms.dap, 0 AS ratingstar, pm.createddate AS createdate, CAST(0 AS DECIMAL) AS shippingcharges, CAST(0 AS BIT) AS isoutofstock, COALESCE(dcs.bv, 0) AS bv, COALESCE(dcs.cashback, 0) AS cashback FROM ims_masterproduct AS pm LEFT OUTER JOIN ims_subproduct AS pms ON pms.mprid = pm.mprid LEFT OUTER JOIN ims_masterproductattribute AS pa ON pa.sprid = pms.sprid LEFT OUTER JOIN tbl_category AS c ON pm.catid = c.catid LEFT OUTER JOIN portal_login AS br ON br.plid = pm.branchid LEFT OUTER JOIN tbl_sub_category AS tsb ON pm.subcategoryid = tsb.subcatid LEFT OUTER JOIN tbl_main_category AS tmc ON tsb.maincatid = tmc.maincatid LEFT OUTER JOIN tbl_distributor_commission_structure AS dcs ON dcs.subsubcatid = tsb.subcatid AND dcs.did = v_did WHERE pms.isactive = 1 AND pms.isverified = 1 AND COALESCE(isverified, 0) = 1 AND tsb.status = 1 AND tmc.status = 1 AND br.status = 1 AND pms.discountpercentage > 5 LIMIT 700;
  RETURN QUERY SELECT (SELECT CASE WHEN COALESCE(COUNT(1), 0) > 0 THEN 1 ELSE 0 END FROM tbl_wishlist WHERE sprid = a.sprid AND loginid = v_getclid AND status = 1) AS wishcount, v_dynamicurl AS baseurl, * FROM (SELECT *, ROW_NUMBER() OVER (PARTITION BY catid ORDER BY sprid DESC NULLS LAST) AS rn FROM tmp_supervalueoffersproductsdata) AS a WHERE rn = 1 ORDER BY discountpercentage DESC NULLS LAST LIMIT 10;
  DROP TABLE IF EXISTS tmp_supervalueoffersproductsdata;
  v_totalcount := 30;
  -- SET option (removed)
  EXCEPTION WHEN OTHERS THEN
  v_totalcount := 0;
  END;
END;
$$;


