--
-- Name: usp_get_top_achievers_list(); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_get_top_achievers_list() RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
BEGIN
  RETURN QUERY SELECT (SELECT COUNT(*) FROM FUN_ALL_DOWNLINE_MEMBERLIST(mm.loginid, 0)) AS membercount, COALESCE(pl.imagename, '') AS imagename, COALESCE(mm.fname, '') || ' ' || COALESCE(mm.mname, '') || ' ' || COALESCE(mm.lname, '') AS name, pl.username FROM member_master AS mm LEFT JOIN portal_login AS pl ON pl.plid = mm.plid WHERE intro_plid > 0 AND (SELECT COUNT(DISTINCT (loginid)) FROM FUN_ALL_DOWNLINE_MEMBERLIST(mm.loginid, 1)) > 0 ORDER BY (SELECT COUNT(DISTINCT (loginid)) FROM FUN_ALL_DOWNLINE_MEMBERLIST(mm.loginid, 1)) DESC NULLS LAST LIMIT 10;
END;
$$;


--
-- Name: usp_get_trending_products(integer, integer, integer, character varying, text, integer, integer, integer, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_get_trending_products(v_maincatid integer DEFAULT 0, v_catid integer DEFAULT 0, v_subcatid integer DEFAULT 0, v_sorting character varying DEFAULT ''::character varying, v_querystring text DEFAULT ''::text, v_pageno integer DEFAULT 1, v_noofrows integer DEFAULT 100, v_totalcount integer DEFAULT 0, v_did integer DEFAULT 1) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
BEGIN
  BEGIN
  DROP TABLE IF EXISTS tmp_trendingproductsdata;
  CREATE TEMP TABLE tmp_trendingproductsdata ON COMMIT DROP AS SELECT DISTINCT pm.producttitle, CAST(pm.mprid AS BIGINT) AS mprid, COALESCE(CAST(pm.maincategoryid AS BIGINT), 0) AS maincategoryid, CAST(pm.subcategoryid AS BIGINT) AS subcategoryid, pm.shotdescription, pm.keyfeatures, CAST(pm.catid AS BIGINT) AS catid, pms.discountpercentage, CAST(pms.sprid AS BIGINT) AS sprid, pms.subprcode, pms.productimages, pms.actualprice, pms.sellmrp, pms.dap, COALESCE(tmc.main_cat_code, '') AS main_cat_code, COALESCE(tsb.sub_cat_code, '') AS sub_cat_code, COALESCE(c.cat_code, '') AS cat_code, CAST(0 AS BIGINT) AS rowno, '' AS productcode, '' AS fulldescription, 0 AS masterproductattriubuteid, '' AS attributetitle, '' AS attributevalue, 0 AS ratingstar, '' AS dealsids, pm.createddate AS createddate, pm.modifydate AS modifydate, 0 AS replacementday, 0 AS procurementsla, CAST(0 AS BIT) AS cashondelivery, CAST(0 AS DECIMAL(18, 2)) AS shippingcharges, 0 AS stockin, 0 AS stockout, 0 AS stocknet, CAST(0 AS BIT) AS isoutofstock, (CASE WHEN COALESCE(CAST(pms.bv AS DECIMAL(18, 2)), 0) = 0 THEN ((COALESCE(CAST((pms.dap + (pms.dap * vc.vatpercvalue) / 100) AS DECIMAL(18, 2)), 0) * COALESCE(tsb.bvper, 0)) / 100) ELSE pms.bv END) AS bv, (CASE WHEN COALESCE(CAST(pms.activationpv_per AS DECIMAL(18, 2)), 0) = 0 THEN ((COALESCE(CAST((pms.dap + (pms.dap * vc.vatpercvalue) / 100) AS DECIMAL(18, 2)), 0) * COALESCE(tsb.activationpv_per, 0)) / 100) ELSE pms.activationpv_per END) AS activationpv, (CASE WHEN COALESCE(CAST(pms.pv AS DECIMAL(18, 2)), 0) = 0 THEN ((COALESCE(CAST((pms.dap + (pms.dap * vc.vatpercvalue) / 100) AS DECIMAL(18, 2)), 0) * COALESCE(tsb.redeemcashback_per, 0)) / 100) ELSE pms.pv END) AS pv, (CASE WHEN COALESCE(CAST(pms.cashback_per AS DECIMAL(18, 2)), 0) = 0 THEN ((COALESCE(CAST((pms.dap + (pms.dap * vc.vatpercvalue) / 100) AS DECIMAL(18, 2)), 0) * COALESCE(tsb.cashback_per, 0)) / 100) ELSE pms.cashback_per END) AS cashback, COALESCE(CAST((pms.dap + (pms.dap * vc.vatpercvalue) / 100) AS DECIMAL(18, 2)), 0) AS includingtax, pms.prskucode, pms.activationpv_per FROM ims_masterproduct AS pm LEFT OUTER JOIN ims_subproduct AS pms ON pms.mprid = pm.mprid LEFT OUTER JOIN ims_masterproductattribute AS pa ON pa.sprid = pms.sprid LEFT OUTER JOIN tbl_category AS c ON pm.catid = c.catid LEFT OUTER JOIN portal_login AS br ON br.plid = pm.branchid LEFT OUTER JOIN tbl_sub_category AS tsb ON pm.subcategoryid = tsb.subcatid LEFT OUTER JOIN tbl_main_category AS tmc ON tsb.maincatid = tmc.maincatid LEFT OUTER JOIN tbl_product_wise_bv_pv_setting AS tpwbvs ON tmc.maincatid = tpwbvs.maincatid AND tsb.subcatid = tpwbvs.subcatid AND c.catid = tpwbvs.catid LEFT OUTER JOIN tbl_customerlogin AS tcl ON tpwbvs.did = tcl.did LEFT OUTER JOIN tbl_vat_categories AS vc ON pms.vatcategoryid = vc.vcid WHERE br.active = 1 AND pms.isactive = 1 AND pms.isverified = 1 AND tsb.status = 1 AND tmc.status = 1 AND br.status = 1 ORDER BY pm.createddate DESC NULLS LAST LIMIT 700;
  RETURN QUERY SELECT * FROM (SELECT *, ROW_NUMBER() OVER (PARTITION BY catid ORDER BY sprid DESC NULLS LAST) AS rn FROM tmp_trendingproductsdata) AS a WHERE rn = 1 ORDER BY GEN_RANDOM_UUID() DESC NULLS LAST LIMIT 12;
  v_totalcount := 10;
  -- SET option (removed)
  EXCEPTION WHEN OTHERS THEN
  v_totalcount := 0;
  END;
END;
$$;


