  SELECT merchantimagepath, merchantproductlargeimage INTO v_dynamicurl, v_merchantproductlargeimage FROM tbl_company;
  DROP TABLE IF EXISTS tmp_trendingproductsdata;
  CREATE TEMP TABLE tmp_trendingproductsdata ON COMMIT DROP AS SELECT DISTINCT pm.producttitle AS producttitle, COALESCE(CAST(pm.maincategoryid AS BIGINT), 0) AS maincategoryid, CAST(pm.subcategoryid AS BIGINT) AS subcategoryid, CAST(pm.catid AS BIGINT) AS catid, pms.discountpercentage AS discountpercentage, CAST(pms.sprid AS BIGINT) AS sprid, pms.subprcode AS productcode, (pms.productimages) AS productimages, pms.sellmrp AS sellmrp, pms.dap, 0 AS ratingstar, pm.createddate AS createdate, CAST(0 AS DECIMAL) AS shippingcharges, CAST(0 AS BIT) AS isoutofstock, CAST(0 AS DECIMAL) AS bv, CAST(0 AS DECIMAL) AS pv FROM ims_masterproduct AS pm LEFT OUTER JOIN ims_subproduct AS pms ON pms.mprid = pm.mprid LEFT OUTER JOIN ims_masterproductattribute AS pa ON pa.sprid = pms.sprid LEFT OUTER JOIN tbl_category AS c ON pm.catid = c.catid LEFT OUTER JOIN portal_login AS br ON br.plid = pm.branchid LEFT OUTER JOIN tbl_sub_category AS tsb ON pm.subcategoryid = tsb.subcatid LEFT OUTER JOIN tbl_main_category AS tmc ON tsb.maincatid = tmc.maincatid WHERE br.active = 1 AND pms.isactive = 1 AND pms.isverified = 1 AND COALESCE(isverified, 0) = 1 AND tsb.status = 1 AND tmc.status = 1 AND br.status = 1 ORDER BY pm.createddate DESC NULLS LAST LIMIT 30;
  RETURN QUERY SELECT (SELECT CASE WHEN COALESCE(COUNT(1), 0) > 0 THEN 1 ELSE 0 END FROM tbl_wishlist WHERE sprid = tm.sprid AND loginid = v_getclid AND status = 1) AS wishcount, v_dynamicurl AS baseurl, * FROM tmp_trendingproductsdata AS tm ORDER BY GEN_RANDOM_UUID() NULLS FIRST;
  v_totalcount := 10;
  -- SET option (removed)
  EXCEPTION WHEN OTHERS THEN
  v_totalcount := 0;
  END;
END;
$$;


--
-- Name: usp_get_trending_products_mobile_backup26122018(integer, integer, integer, character varying, text, integer, integer, integer, integer, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_get_trending_products_mobile_backup26122018(v_maincatid integer DEFAULT 1011, v_catid integer DEFAULT 1054, v_subcatid integer DEFAULT 0, v_sorting character varying DEFAULT ''::character varying, v_querystring text DEFAULT ''::text, v_pageno integer DEFAULT 1, v_noofrows integer DEFAULT 100, v_totalcount integer DEFAULT 0, v_did integer DEFAULT 1, v_getclid integer DEFAULT 0) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_dynamicurl varchar(100);
  v_merchantproductlargeimage varchar(250);
BEGIN
  BEGIN
  v_dynamicurl := '';
  v_merchantproductlargeimage := '';
  SELECT merchantimagepath, merchantproductlargeimage INTO v_dynamicurl, v_merchantproductlargeimage FROM tbl_company;
  DROP TABLE IF EXISTS tmp_trendingproductsdata;
  CREATE TEMP TABLE tmp_trendingproductsdata ON COMMIT DROP AS SELECT DISTINCT pm.producttitle, CAST(pm.mprid AS BIGINT) AS mprid, COALESCE(CAST(pm.maincategoryid AS BIGINT), 0) AS maincategoryid, CAST(pm.subcategoryid AS BIGINT) AS subcategoryid, pm.shotdescription, pm.keyfeatures, CAST(pm.catid AS BIGINT) AS catid, pms.discountpercentage, CAST(pms.sprid AS BIGINT) AS sprid, pms.subprcode, (pms.productimages) AS productimages, pms.actualprice, pms.sellmrp, pms.dap, COALESCE(tmc.main_cat_code, '') AS main_cat_code, COALESCE(tsb.sub_cat_code, '') AS sub_cat_code, COALESCE(c.cat_code, '') AS cat_code, CAST(0 AS BIGINT) AS rowno, '' AS productcode, '' AS fulldescription, 0 AS masterproductattriubuteid, '' AS attributetitle, '' AS attributevalue, 0 AS ratingstar, '' AS dealsids, pm.createddate AS createddate, pm.modifydate AS modifydate, 0 AS replacementday, 0 AS procurementsla, CAST(0 AS BIT) AS cashondelivery, CAST(0 AS DECIMAL) AS shippingcharges, 0 AS stockin, 0 AS stockout, 0 AS stocknet, CAST(0 AS BIT) AS isoutofstock, CAST(0 AS DECIMAL) AS bv, CAST(0 AS DECIMAL) AS pv FROM ims_masterproduct AS pm LEFT OUTER JOIN ims_subproduct AS pms ON pms.mprid = pm.mprid LEFT OUTER JOIN ims_masterproductattribute AS pa ON pa.sprid = pms.sprid LEFT OUTER JOIN tbl_category AS c ON pm.catid = c.catid LEFT OUTER JOIN portal_login AS br ON br.plid = pm.branchid LEFT OUTER JOIN tbl_sub_category AS tsb ON pm.subcategoryid = tsb.subcatid LEFT OUTER JOIN tbl_main_category AS tmc ON tsb.maincatid = tmc.maincatid WHERE br.active = 1 AND pms.isactive = 1 AND pms.isverified = 1 AND COALESCE(isverified, 0) = 1 AND tsb.status = 1 AND tmc.status = 1 AND br.status = 1 ORDER BY pm.createddate DESC NULLS LAST LIMIT 30;
  RETURN QUERY SELECT (SELECT CASE WHEN COALESCE(COUNT(1), 0) > 0 THEN 1 ELSE 0 END FROM tbl_wishlist WHERE sprid = tm.sprid AND loginid = v_getclid AND status = 1) AS wishcount, v_dynamicurl AS baseurl, * FROM tmp_trendingproductsdata AS tm ORDER BY GEN_RANDOM_UUID() NULLS FIRST;
  v_totalcount := 10;
  -- SET option (removed)
  EXCEPTION WHEN OTHERS THEN
  v_totalcount := 0;
  END;
END;
$$;


--
-- Name: usp_get_utiliteswise_bv_pv_setting(integer, integer, character varying, character varying, integer, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_get_utiliteswise_bv_pv_setting(v_startrowindex integer DEFAULT 1, v_maxrows integer DEFAULT 1000, v_fromdate character varying DEFAULT ''::character varying, v_todate character varying DEFAULT ''::character varying, v_did integer DEFAULT 2, v_totalcount integer DEFAULT 0) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_minindex INT;
  v_maxindex INT;
  v_query text;
  v_condition text;
  v_countquery text;
  v_trpid INT;
BEGIN
  -- BEGIN TRAN (removed)
  -- SET option (removed)
  v_condition := '';
  v_countquery := '';
  v_trpid := 0;
  v_minindex := (v_startrowindex - 1) * v_maxrows + 1;
  v_maxindex := v_startrowindex * v_maxrows;
  SELECT COALESCE(trpid, 0) INTO v_trpid FROM tbl_reseller_purchased_packages WHERE did = v_did AND trsid = 1;
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp (ROWNUMBER INT GENERATED BY DEFAULT AS IDENTITY,
 TVRCSID INT,
 OperatorName Varchar(100),
 COMMISSION DECIMAL(18,2),
 BV DECIMAL(18,2),
 PV DECIMAL(18,2)) ON COMMIT DROP;
  v_query := ' INSERT INTO #TEMP Select distinct TVRCS.TVRCSID,TVRCS.OPERATORNAME,
(CASE WHEN ''' || CAST(v_trpid AS VARCHAR(30)) || '''=1 THEN isnull(DPCS.ActualPercentagePack1,0) WHEN ''' || CAST(v_trpid AS VARCHAR(30)) || '''=2 THEN isnull(DPCS.ActualPercentagePack2,0) 
 WHEN ''' || CAST(v_trpid AS VARCHAR(30)) || '''=3 THEN isnull(DPCS.ActualPercentagePack3,0) WHEN ''' || CAST(v_trpid AS VARCHAR(30)) || '''=4 THEN isnull(DPCS.ActualPercentagePack4,0) END),
ISNULL(TUWBV.BV,0),ISNULL(TUWBV.PV,0)  from TBL_VENDOR_RECHARGE_COMMISSION_STRUCTURE TVRCS
LEFT JOIN TBL_DEFAULT_PACKAGE_COMMISSION_SETTINGS DPCS ON TVRCS.OPERATORNAME=DPCS.OPERATORNAME
LEFT JOIN TBL_UTILITIES_WISE_BV_PV_SETTING TUWBV ON TVRCS.TVRCSID=TUWBV.TVRCSID and  TUWBV.DID=''' || CAST(v_did AS VARCHAR(30)) || ''' 
LEFT JOIN TBL_RESELLER_PURCHASED_PACKAGES TRPP ON TUWBV.DID=TRPP.DID  ';
  EXECUTE v_query;
  RAISE NOTICE '%', v_query;
  RETURN QUERY SELECT * FROM tmp_temp WHERE rownumber BETWEEN v_minindex AND v_maxindex;
  SELECT COUNT(rownumber) INTO v_totalcount FROM tmp_temp;
  DROP TABLE IF EXISTS tmp_temp;
  -- COMMIT (removed)
END;
$$;


--
-- Name: usp_getaccesstoken(character varying, text, character varying, character varying, character varying, text, text, text); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_getaccesstoken(v_email character varying DEFAULT ''::character varying, v_token text DEFAULT ''::text, v_name character varying DEFAULT ''::character varying, v_country character varying DEFAULT ''::character varying, v_mobile character varying DEFAULT ''::character varying, v_idtoken text DEFAULT ''::text, v_refreshtoken text DEFAULT ''::text, v_sessionid text DEFAULT ''::text) RETURNS void
    LANGUAGE plpgsql
    AS $$
BEGIN
  UPDATE dbo.tokenhistory SET status = 0 WHERE emailid = v_email;
  INSERT INTO dbo.tokenhistory (date, emailid, token, status, name, country, mobile, idtoken, refreshtoken, sessionid) VALUES (dbo.FUN_GETCURRENTDATE(), v_email, v_token, 1, v_name, v_country, v_mobile, v_idtoken, v_refreshtoken, v_sessionid);
END;
$$;


