--
-- Name: usp_getall_affiliate_request(integer, integer, bigint, bigint, bigint, character varying, character varying, character varying, character varying, integer, integer, character varying, character varying, character varying, character varying, integer, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_getall_affiliate_request(v_startrowindex integer DEFAULT 1, v_maxrows integer DEFAULT 1000, v_mprid bigint DEFAULT 0, v_sprid bigint DEFAULT 0, v_branchid bigint DEFAULT 0, v_cat_code character varying DEFAULT ''::character varying, v_searchfield character varying DEFAULT ''::character varying, v_searchvalue character varying DEFAULT ''::character varying, v_status character varying DEFAULT ''::character varying, v_totalcount integer DEFAULT 0, v_isstock integer DEFAULT 0, v_formdate character varying DEFAULT ''::character varying, v_todate character varying DEFAULT ''::character varying, v_stockin character varying DEFAULT ''::character varying, v_productname character varying DEFAULT ''::character varying, v_categoryrelatedto integer DEFAULT 0, v_did integer DEFAULT 0) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_minindex INT;
  v_maxindex INT;
  v_query text;
  v_catecode INT;
BEGIN
  v_minindex := (v_startrowindex - 1) * v_maxrows + 1;
  v_maxindex := v_startrowindex * v_maxrows;
  DROP TABLE IF EXISTS tmp_productlisttemp;
  CREATE TEMP TABLE tmp_productlisttemp (ROWNUMBER BIGINT GENERATED BY DEFAULT AS IDENTITY                    




,MPRID BIGINT                     
,PRODUCTCODE VARCHAR( 50)                     
,SUBPRCODE VARCHAR( 50)                     
,PRODUCTTITLE VARCHAR( 300)   
,PRODUCTNAME varchar(500)
,MAINCATNAME VARCHAR( 250)                     
,QTY INT                     
,UNIT VARCHAR( 50)                     
,PRODUCTIMAGES VARCHAR( 1000)                     
,MERCHANTNAME VARCHAR( 1000)                     
,EMAILID VARCHAR( 100)                     
,PHONE VARCHAR( 100)                     
,SELLMRP DECIMAL(18,2)                     
,DAP DECIMAL(18,2)                     
,SPRID BIGINT                     
,ISACTIVE boolean  ,                    
PROCUREMENTSLA INT,                    
REPLACEMENTDAY INT,                    
SHIPPINGCHARGES DECIMAL(18,2),                    
CASHONDELIVERY boolean,                    
WEIGHT_KG DECIMAL(18,2),                    
LENGTH_CMS DECIMAL(18,2),                    
BREADTH_CMS DECIMAL(18,2),                    
HEIGHT_CMS DECIMAL(18,2)                    
,MVAT DECIMAL                     
,DEALSIDS VARCHAR(100)                    
,STOCKINQTY INT                     
,STOCKOUTQTY INT                     
,STOCKNETQTY INT                     
,ISSTOCK boolean                     
,VATTITLE VARCHAR(100)                     
,PRODUCTCOUNT INT,                    
BV DECIMAL(18,2),                    
JP DECIMAL(18,2),                    
ISVERIFIED INT,                    
SUBCATEGORY VARCHAR(500),                    
DISCOUNTPERCENTAGE DECIMAL(18,2),                    
CREATEDDATE VARCHAR(100),                    
MODIFYDATE VARCHAR(100),                
PrSKUCODE Varchar(100),        
IS_OFFER boolean,    
IS_AFFILIATE boolean,    
BONUS_TYPE varchar(10),    
BONUS_VALUE decimal(18,2),    
REDEEM_AFTER_DAYS int ,  
STATUS varchar(10),  
REMARK varchar(500),  
ABPID int) ON COMMIT DROP;
  v_query := 'INSERT INTO #PRODUCTLISTTEMP SELECT 
PM.MPRID,
PM.PRODUCTCODE,
SM.SUBPRCODE,
PM.PRODUCTTITLE,
REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(PM.PRODUCTTITLE,'' '',''_''),''/'',''_''),''|'',''_''),'':'',''''),''.'',''''),''%'','''') as PRODUCTNAME,  
MC.MAINCATNAME,
SM.QTY,
SM.UNIT,
SM.PRODUCTIMAGES,                    
ISNULL((PL.FNAME+PL.LNAME),'''') AS MERCHANTNAME,
ISNULL(PL.EMAILID,'''') AS EMAILID,
ISNULL(PL.PHONE,'''') AS PHONE,                    
SM.SELLMRP,        
iif(OOP.OPID is null,
SM.DAP,OOP.Offer_DAP) as DAP,        
SM.SPRID,SM.ISACTIVE,ISNULL(SM.PROCUREMENTSLA,0),ISNULL(SM.REPLACEMENTDAY,0),                    
CONVERT(DECIMAL(18,2),SM.SHIPPINGCHARGES),ISNULL(SM.CASHONDELIVERY,0),ISNULL(SM.WEIGHT_KG,0),ISNULL(SM.LENGTH_CMS,0),ISNULL(SM.BREADTH_CMS,0),ISNULL(SM.HEIGHT_CMS,0),                    
CONVERT(DECIMAL(18,0),ISNULL(V.VATPERCVALUE,0)) AS MVAT, ISNULL(SM.DEALSIDS,'''')                    
,ISNULL(SM.STOCKIN,0),ISNULL(SM.STOCKOUT,0),ISNULL(SM.STOCKNET,0),CONVERT(BIT, (CASE WHEN ISNULL(SM.STOCKNET,0) <= 0 THEN 0 ELSE 1 END)) AS ISSTOCK,V.VATTITLE,0 AS PRODUCTCOUNT,                    
ISNULL(SM.BV,0) AS BV,ISNULL(SM.PV,0) AS JP,SM.ISVERIFIED AS ISVERIFIED,ISNULL(KM.SUBCATNAME,'''') ,                
iif(OOP.OPID is null, ISNULL(DISCOUNTPERCENTAGE,0),[dbo].[FUN_GET_DISCOUNT_PERCENTAGE](SM.SELLMRP,OOP.Offer_DAP))as DISCOUNTPERCENTAGE,ISNULL(CONVERT(DATE,SM.CREATEDDATE,105),''''),                
ISNULL(CONVERT(DATE,SM.MODIFYDATE,105),''''),SM.PrSKUCODE,        
iif(OOP.OPID is null,0,1)as IS_OFFER ,    
iif(ABP.SPRID is null,0,1) as IS_AFFILIATE,    
ISNULL(ABP.BONUS_TYPE,'''')AS BONUS_TYPE,ISNULL(ABP.BONUS_VALUE,0),ISNULL(ABP.REDEEM_AFTER_DAYS,0),Cast(ABP.STATUS as varchar),ABP.REMARK ,ABP.ABPID 
FROM AFFILIATE_BONUS_ON_PRODUCT ABP
INNER JOIN IMS_SUBPRODUCT SM ON SM.SPRID=ABP.SPRID 
INNER join IMS_MASTERPRODUCT PM ON SM.MPRID=PM.MPRID 
INNER JOIN TBL_MAIN_CATEGORY MC ON MC.MAINCATID =PM.MAINCATEGORYID                        
inner  JOIN TBL_VAT_CATEGORIES V ON V.VCID = PM.VATCATEGORYID                     
inner  JOIN PORTAL_LOGIN PL ON PL.PLID= PM.BRANCHID         
JOIN TBL_SUB_CATEGORY KM ON PM.SUBCATEGORYID=KM.SUBCATID                 
LEFT JOIN TBL_OFFER_ON_PRODUCT OOP ON OOP.SPRID=SM.SPRID  and getdate() between OOP.Offer_start and OOP.Offer_End     
WHERE  SM.ISVERIFIED IN (0,1,2,3) ';
  IF (v_status <> '') THEN
  v_query := v_query || ' AND SM.ISVERIFIED =' || CAST(v_status AS VARCHAR(20));
  END IF;
  IF (v_searchfield = 'EMAILID') THEN
  v_query := v_query || ' AND PL.EMAILID LIKE ''%' || v_searchvalue || '%'' ';
  END IF;
  IF (v_searchfield = 'MERCHANTNAME') THEN
  v_query := v_query || ' AND (PL.FNAME+PL.LNAME) LIKE ''%' || v_searchvalue || '%'' ';
  END IF;
  IF (v_searchfield = 'PHONE') THEN
  v_query := v_query || ' AND PL.PHONE LIKE ''%' || v_searchvalue || '%'' ';
  END IF;
  IF (v_searchfield = 'PRODUCTTITLE') THEN
  v_query := v_query || ' AND PM.ProductTitle LIKE ''%' || v_searchvalue || '%'' ';
  END IF;
  IF (v_searchfield = 'MAINCATNAME') THEN
  v_query := v_query || ' AND MC.MAINCATNAME LIKE ''%' || v_searchvalue || '%'' ';
  END IF;
  IF (v_productname <> '') THEN
  v_query := v_query || ' AND PM.ProductTitle Like ''%' || v_productname || '%''';
  END IF;
  IF ((v_formdate <> '') AND (v_todate = '')) THEN
  v_query := v_query || (' AND CONVERT(DATE,SM.CREATEDDATE,105) BETWEEN CONVERT(VARCHAR(100),''' || v_formdate || ''',105) AND  CONVERT(DATE, DBO.FUN_GETCURRENTDATE(), 105)');
  END IF;
  IF ((v_todate <> '') AND (v_formdate = '')) THEN
  v_query := v_query || (' AND CONVERT(DATE,SM.CREATEDDATE,105) BETWEEN CONVERT(VARCHAR(100),''' || v_todate || ''',105) AND  CONVERT(DATE, DBO.FUN_GETCURRENTDATE(), 105) ');
  END IF;
  IF (v_formdate <> '' AND v_todate <> '') THEN
  v_query := v_query || (' AND CONVERT(DATE,SM.CREATEDDATE,105) BETWEEN CONVERT(VARCHAR(100),''' || v_formdate || ''',105) AND CONVERT(VARCHAR(100),''' || v_todate || ''',105) ');
  END IF;
  IF (v_branchid > 0) THEN
  v_query := v_query || ' AND PM.BranchId=' || CAST(v_branchid AS VARCHAR(50));
  END IF;
  IF (v_mprid > 0) THEN
  v_query := v_query || ' AND PM.MPRID =' || CAST(v_mprid AS VARCHAR(20));
  END IF;
  IF (v_sprid > 0) THEN
  v_query := v_query || ' AND SM.SPRID =' || CAST(v_sprid AS VARCHAR(20));
  END IF;
  IF (v_cat_code <> '') THEN
  v_catecode := 0;
  SELECT catid INTO v_catecode FROM tbl_category WHERE cat_code = v_cat_code;
  IF (v_catecode > 0) THEN
  v_query := v_query || ' AND PM.CATID =' || CAST(v_catecode AS VARCHAR(20));
  ELSE
  SELECT subcatid INTO v_catecode FROM tbl_sub_category WHERE sub_cat_code = v_cat_code;
  v_query := v_query || ' AND PM.SUBCATEGORYID =' || CAST(v_catecode AS VARCHAR(20));
  END IF;
  END IF;
  IF (v_stockin = '0') THEN
  v_query := v_query || ' AND  SM.STOCKNET<=5';
  END IF;
  IF (v_stockin > '0') THEN
  v_query := v_query || ' AND  SM.STOCKNET>0';
  END IF;
  IF (v_isstock = 1) THEN
  v_query := v_query || ' ORDER BY  SM.STOCKNET ASC ';
  ELSE
  IF (v_isstock = 2) THEN
  v_query := v_query || ' ORDER BY  SM.STOCKNET DESC ';
  ELSE
  v_query := v_query || ' ORDER BY  PM.MPRID DESC ';
  END IF;
  END IF;
  RAISE NOTICE '%', v_query;
  EXECUTE v_query;
  RETURN QUERY SELECT * FROM tmp_productlisttemp WHERE rownumber BETWEEN v_minindex AND v_maxindex;
  SELECT COUNT(rownumber) INTO v_totalcount FROM tmp_productlisttemp;
  DROP TABLE IF EXISTS tmp_productlisttemp;
  -- SET option (removed)
END;
$$;


--
-- Name: usp_getall_distinct_product(integer, integer, bigint, bigint, bigint, character varying, character varying, character varying, character varying, integer, integer, integer, character varying, character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_getall_distinct_product(v_startrowindex integer DEFAULT 1, v_maxrows integer DEFAULT 1000, v_mprid bigint DEFAULT 0, v_sprid bigint DEFAULT 0, v_branchid bigint DEFAULT 0, v_cat_code character varying DEFAULT ''::character varying, v_searchfield character varying DEFAULT ''::character varying, v_searchvalue character varying DEFAULT ''::character varying, v_company character varying DEFAULT ''::character varying, v_status integer DEFAULT 1, v_totalcount integer DEFAULT 0, v_isstock integer DEFAULT 0, v_productname character varying DEFAULT ''::character varying, v_merchantname character varying DEFAULT 'Prem Gift Palace'::character varying) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_minindex INT;
  v_maxindex INT;
  v_query text;
  v_catecode INT;
  v_minstock int;
  v_maxstock int;
BEGIN
  v_minindex := (v_startrowindex - 1) * v_maxrows + 1;
  v_maxindex := v_startrowindex * v_maxrows;
  DROP TABLE IF EXISTS tmp_productlisttemp;
  CREATE TEMP TABLE tmp_productlisttemp (ROWNUMBER BIGINT GENERATED BY DEFAULT AS IDENTITY
,MPRID BIGINT 
,PRODUCTCODE VARCHAR( 50) 
,SUBPRCODE VARCHAR( 50) 
,PRODUCTTITLE VARCHAR( 300) 
,MAINCATNAME VARCHAR( 250) 
,QTY INT 
,UNIT VARCHAR( 50) 
,PRODUCTIMAGES VARCHAR( 1000) 
,MerchantName VARCHAR( 1000) 
,EMAILID VARCHAR( 100) 
,PHONE VARCHAR( 100) 
,SELLMRP DECIMAL 
,DAP DECIMAL 
,SPRID BIGINT 
,ISACTIVE boolean  ,
PROCUREMENTSLA INT,
REPLACEMENTDAY INT,
SHIPPINGCHARGES DECIMAL(18,2),
CASHONDELIVERY boolean,
WEIGHT_KG DECIMAL(18,2),
LENGTH_CMS DECIMAL(18,2),
BREADTH_CMS DECIMAL(18,2),
HEIGHT_CMS DECIMAL(18,2)
,MVAT DECIMAL 
,DEALSIDS VARCHAR(100)
,STOCKINQTY INT 
,STOCKOUTQTY INT 
,STOCKNETQTY INT 
,ISSTOCK boolean 
,VATTITLE VARCHAR(100) 
,PRODUCTCOUNT INT,
BV DECIMAL(18,2),
JP DECIMAL(18,2),
pmid bigint,
COMPANYNAME VARCHAR(100),
STOCKIN int,
STOCKOUT int,
STOCKNET int,
SUBCATID int,
ADMINCHARGE decimal(18,2),
DELIEVERYCHARGE decimal(18,2),
HANDLINGCHARGE decimal(18,2),
FixedFee decimal(18,2),
cashback_Per decimal(18,2),
ismerchantstatus int) ON COMMIT DROP;
  v_query := 'INSERT INTO #PRODUCTLISTTEMP SELECT PM.MPRID,PM.PRODUCTCODE,SM.SUBPRCODE,PM.PRODUCTTITLE, 
MC.MAINCATNAME,SM.QTY,SM.UNIT,SM.PRODUCTIMAGES,ISNULL((PL.FNAME+PL.LNAME),'''') as MerchantName,ISNULL(PL.EMAILID,'''') AS EMAILID,ISNULL(PL.PHONE,'''') AS PHONE,
SM.SELLMRP,SM.DAP,SM.SPRID,SM.ISACTIVE,ISNULL(SM.PROCUREMENTSLA,0),ISNULL(SM.REPLACEMENTDAY,0),
CONVERT(DECIMAL(18,2),SM.SHIPPINGCHARGES),ISNULL(SM.CASHONDELIVERY,0),ISNULL(SM.WEIGHT_KG,0),ISNULL(SM.LENGTH_CMS,0),
ISNULL(SM.BREADTH_CMS,0),ISNULL(SM.HEIGHT_CMS,0),
CONVERT(DECIMAL(18,0),ISNULL(V.VATPERCVALUE,0)) AS MVAT, ISNULL(SM.DEALSIDS,'''')
,ISNULL(SM.STOCKIN,0),ISNULL(SM.STOCKOUT,0),ISNULL(SM.STOCKNET,0),CONVERT(BIT, (CASE WHEN ISNULL(SM.STOCKNET,0) <= 0 THEN 0 ELSE 1 END)) AS ISSTOCK,
V.VATTITLE,0 AS PRODUCTCOUNT,isnull(SM.BV,0) as BV ,
isnull(SM.PV,0) as JP,pma.PMID,PMA.COMPANYNAME,
ISNULL(SM.STOCKIN,0) AS STOCKIN,ISNULL(SM.STOCKOUT,0) AS STOCKOUT,ISNULL(SM.STOCKNET,0) AS STOCKNET,0,
ISNULL(SM.AdminCharge,0) AS AdminCharge,ISNULL(SM.DelieveryCharge,0) AS DelieveryCharge,ISNULL(SM.HandlingCharge,0) AS HandlingCharge,
ISNULL(SM.FixedFee,0) AS FixedFee,ISNULL(SM.cashback_Per,0) AS cashback_Per,isnull(SM.ismerchantstatus,0) as ismerchantstatus
FROM IMS_MASTERPRODUCT PM INNER JOIN IMS_SUBPRODUCT SM ON SM.MPRID=PM.MPRID 
INNER JOIN TBL_MAIN_CATEGORY MC ON MC.MAINCATID =PM.MAINCATEGORYID	
LEFT  JOIN TBL_VAT_CATEGORIES V ON V.VCID = PM.VATCATEGORYID 
LEFT  JOIN PORTAL_LOGIN PL ON PL.PLID= PM.BranchId
left join Portal_Master pma on pma.PMID=pl.PMID
WHERE PM.MPRID >0 AND  SM.ISVERIFIED=1';
  SELECT MIN(stocknet) INTO v_minstock FROM ims_subproduct;
  SELECT MAX(stocknet) INTO v_maxstock FROM ims_subproduct;
  IF (v_status > 0) THEN
  v_query := v_query || ' AND SM.ISACTIVE =' || CAST(v_status AS VARCHAR(20));
  END IF;
  IF (v_merchantname <> '') THEN
  v_query := v_query || ' AND PMA.COMPANYNAME= ''' || v_merchantname || ''' ';
  END IF;
  IF (v_company <> '') THEN
  v_query := v_query || ' AND pma.PMID LIKE ''%' || v_company || '%'' ';
  END IF;
  IF (v_searchfield = 'EMAILID') THEN
  v_query := v_query || ' AND PL.Emailid LIKE ''%' || v_searchvalue || '%'' ';
  END IF;
  IF (v_searchfield = 'MerchantName') THEN
  v_query := v_query || ' AND pma.COMPANYNAME LIKE ''%' || v_searchvalue || '%'' ';
  END IF;
  IF (v_searchfield = 'PHONE') THEN
  v_query := v_query || ' AND PL.PHONE LIKE ''%' || v_searchvalue || '%'' ';
  END IF;
  IF (v_productname <> '') THEN
  v_productname := REPLACE(v_productname, '''', '''''');
  v_query := v_query || ' and PM.ProductTitle =''' || v_productname || '''';
  END IF;
  IF (v_searchfield = 'PRODUCTTITLE') THEN
  v_query := v_query || ' AND PM.PRODUCTTITLE LIKE ''%' || v_searchvalue || '%'' ';
  END IF;
  IF (v_searchfield = 'MAINCATNAME') THEN
  v_query := v_query || ' AND MC.MAINCATNAME LIKE ''%' || v_searchvalue || '%'' ';
  END IF;
  IF (v_mprid > 0) THEN
  v_query := v_query || ' AND PM.MPRID =' || CAST(v_mprid AS VARCHAR(20));
  END IF;
  IF (v_sprid > 0) THEN
  v_query := v_query || ' AND SM.SPRID =' || CAST(v_sprid AS VARCHAR(20));
  END IF;
  EXECUTE v_query;
  RETURN QUERY SELECT * FROM tmp_productlisttemp WHERE rownumber IN (SELECT MIN(rownumber) FROM tmp_productlisttemp GROUP BY producttitle);
  SELECT COUNT(rownumber) INTO v_totalcount FROM tmp_productlisttemp WHERE rownumber IN (SELECT MIN(rownumber) FROM tmp_productlisttemp GROUP BY producttitle);
  DROP TABLE IF EXISTS tmp_productlisttemp;
  -- SET option (removed)
END;
$$;


--
-- Name: usp_getall_excelproductlist(integer, integer, bigint, character varying, character varying, integer, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_getall_excelproductlist(v_startrowindex integer DEFAULT 1, v_maxrows integer DEFAULT 100, v_branchid bigint DEFAULT 1, v_searchfield character varying DEFAULT ''::character varying, v_searchvalue character varying DEFAULT ''::character varying, v_status integer DEFAULT '-1'::integer, v_totalcount integer DEFAULT 0) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_minindex int;
  v_maxindex int;
  v_query text;
  v_catecode int;
BEGIN
  v_minindex := (v_startrowindex - 1) * v_maxrows + 1;
  v_maxindex := v_startrowindex * v_maxrows;
  DROP TABLE IF EXISTS tmp_productlisttemp;
  CREATE TEMP TABLE tmp_productlisttemp (rowNumber bigint GENERATED BY DEFAULT AS IDENTITY,
   Id bigint ,
   MCID bigint ,
   CID bigint ,
   SCID bigint ,
   VCID bigint ,
   Code varchar( 100) ,
   ProductTitle varchar( 200) ,
   ShortDescription varchar( 2000) ,
   FullDescription varchar( 2000) ,
   KeyFeatures varchar( 500) ,
   UnitQty int ,
   Unit varchar( 50) ,
   StockIn int ,
   ProductImages varchar( 500) ,
   SellMRP decimal(18,2) ,
   DAP decimal(18,2),
   Discount decimal(18,2),
   DealsIds varchar( 2000) ,
   GroupId varchar( 50) ,
   ReplacementDay int ,
   ProcurementSLA int ,
   CashOnDelivery boolean ,
   ShippingCharges decimal(18,2),
   Weight_kg decimal(18,2),
   Length_cms decimal(18,2),
   Breadth_cms decimal(18,2),
   Height_cms decimal(18,2),
   ErrorReason varchar( 200) ,
   BranchId bigint ,
   CreatedDate timestamp ,
   WarrentyInfoCare int ,
   QCStatus int ,
   BranchName varchar( 50) ,
   MasterCategoryName varchar( 50) ,
   CategoryName varchar( 50) ,
   SubCategoryName varchar( 50) ,
   VatCategoryName varchar( 50) ,
   VatValue decimal(18,2)) ON COMMIT DROP;
  v_query := 'insert into #ProductListTemp  SELECT e.Id,e.MCID,e.CID,e.SCID,ISNULL(e.VCID,0),e.Code,e.ProductTitle,e.ShortDescription,e.FullDescription,e.KeyFeatures,
			e.UnitQty,e.Unit,e.StockIn,e.ProductImages,e.SellMRP,e.DAP,e.Discount,e.DealsIds,e.GroupId,e.ReplacementDay,e.ProcurementSLA,e.CashOnDelivery,e.ShippingCharges,
			e.Weight_kg,e.Length_cms,e.Breadth_cms,e.Height_cms,e.ErrorReason,e.BranchId,e.CreatedDate,e.WarrentyInfoCare,e.QCStatus,
			(b.FNAME+'' ''+b.LNAME),mc.maincatname,c.catname,sc.subcatname,v.vatTitle,ISNULL(v.vatPercValue,0)
			FROM EXCEL_Product e 
			LEFT JOIN PORTAL_LOGIN b on b.PLID = e.BranchId
			LEFT JOIN tbl_main_category mc on mc.maincatid = e.MCID
			LEFT JOIN tbl_category c on c.catid = e.CID
			LEFT JOIN tbl_Sub_category sc on sc.subcatid = e.SCID
			LEFT JOIN tbl_Vat_Categories v on v.vcid = e.VCID
			where e.Id >0  and 
			 (' || CAST(v_status AS VARCHAR(50)) || ' = -1 OR e.QCStatus=' || CAST(v_status AS VARCHAR(50)) || ')' || ' and  (' || CAST(v_branchid AS VARCHAR(50)) || ' = 1 OR e.BranchId=' || CAST(v_branchid AS VARCHAR(50)) || ')';
  v_query := v_query || ' order by  e.Id desc ';
  EXECUTE v_query;
  RETURN QUERY SELECT * FROM tmp_productlisttemp WHERE rownumber BETWEEN v_minindex AND v_maxindex;
  SELECT COUNT(rownumber) INTO v_totalcount FROM tmp_productlisttemp;
  DROP TABLE IF EXISTS tmp_productlisttemp;
  -- SET option (removed)
END;
$$;


--
-- Name: usp_getall_field_details(integer, integer, integer, integer, integer, integer, text); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_getall_field_details(v_startrowindex integer DEFAULT 1, v_maxrows integer DEFAULT 100, v_catid integer DEFAULT 0, v_totalcount integer DEFAULT 0, v_intresult integer DEFAULT 0, v_mode integer DEFAULT 1, v_id text DEFAULT ''::text) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_count Int;
  v_start Int;
  v_temptfmid Int;
BEGIN
  IF (v_mode = 1) THEN
  RETURN QUERY SELECT ROW_NUMBER() OVER (ORDER BY tf.tfmid NULLS FIRST) AS rownumber, COALESCE(tcf.tcfmid, 0) AS tcfmid, tf.tfmid, fieldname, divid, fieldtype, tf.defaultvalue, tf.status, tf.active, ismandatory, (CASE WHEN (COALESCE((SELECT 'CHECKED' FROM tbl_categoryfieldmaster WHERE tf.tfmid = tfmid AND active = 1 AND status = 1 AND catid = v_catid), 'false') = 'false' AND tf.ismandatory = 0) THEN 'false' ELSE 'CHECKED' END) AS checked FROM tbl_fieldmaster AS tf LEFT JOIN tbl_categoryfieldmaster AS tcf ON tf.tfmid = tcf.tfmid AND catid = v_catid;
  RETURN QUERY SELECT COUNT(1) AS recordcount FROM tbl_fieldmaster AS tf LEFT JOIN tbl_categoryfieldmaster AS tcf ON tf.tfmid = tcf.tfmid;
  ELSE
  IF (v_mode = 2) THEN
  v_count := 0;
  v_start := 1;
  v_temptfmid := 0;
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp (Rownumber int GENERATED BY DEFAULT AS IDENTITY,
		ID Int) ON COMMIT DROP;
  INSERT INTO tmp_temp SELECT value FROM dbo.SPLITSTRINGBYCUSTOMSYMBOL1(v_id, ',');
  SELECT COUNT(1) INTO v_count FROM tmp_temp;
  IF EXISTS(SELECT 1 FROM tbl_categoryfieldmaster WHERE catid = v_catid) THEN
  UPDATE tbl_categoryfieldmaster SET active = 0, status = 0 WHERE catid = v_catid;
  END IF;
  WHILE (v_start <= v_count) LOOP
  SELECT id INTO v_temptfmid FROM tmp_temp WHERE rownumber = v_start;
  IF EXISTS(SELECT 1 FROM tbl_categoryfieldmaster WHERE tfmid = v_temptfmid AND catid = v_catid) THEN
  UPDATE tbl_categoryfieldmaster SET active = 1, status = 1 WHERE tfmid = v_temptfmid AND catid = v_catid;
  ELSE
  INSERT INTO tbl_categoryfieldmaster (tfmid, catid, defaultvalue, assigneddate, updateddate, status, active) VALUES (v_temptfmid, v_catid, '', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 1, 1);
  END IF;
  v_start := v_start + (1);
  END LOOP;
  SELECT 2 INTO v_intresult;
  END IF;
  END IF;
END;
$$;


--
-- Name: usp_getall_homepagebannerlist(integer, integer, character varying, character varying, character varying, character varying, integer, integer, character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_getall_homepagebannerlist(v_startrowindex integer DEFAULT 1, v_maxrows integer DEFAULT 1000, v_searchfield character varying DEFAULT ''::character varying, v_searchvalue character varying DEFAULT ''::character varying, v_fromdate character varying DEFAULT ''::character varying, v_todate character varying DEFAULT ''::character varying, v_mode integer DEFAULT 0, v_recordcount integer DEFAULT 0, v_orderby character varying DEFAULT ''::character varying) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_sqlquery text;
  v_minindex INT;
  v_maxindex INT;
BEGIN
  -- SET option (removed)
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp (ROWNUMBER BIGINT GENERATED BY DEFAULT AS IDENTITY,
brId INT,
Title VARCHAR(200),
Url VARCHAR(200),
Status INT,
CreateDate timestamp) ON COMMIT DROP;
  v_sqlquery := '';
  v_minindex := (v_startrowindex - 1) * v_maxrows + 1;
  v_maxindex := v_startrowindex * v_maxrows;
  v_sqlquery := 'INSERT INTO #TEMP SELECT brId, Title, Url, Status, CreateDate FROM tbl_HomePageBanners
                   WHERE Status = 0 or Status = 1';
  IF (v_fromdate = '' OR v_todate = '') THEN
  IF (v_fromdate <> '') THEN
  v_sqlquery := v_sqlquery || ' AND CONVERT(DATE, CreateDate,103) >= REPLACE(CONVERT(DATE,''' || v_fromdate || ''',103),''/'',''-'') ';
  END IF;
  IF (v_todate <> '') THEN
  v_sqlquery := v_sqlquery || ' AND CONVERT(DATE, CreateDate,103)  <=REPLACE(CONVERT(DATE,''' || v_todate || ''',103),''/'',''-'') ';
  END IF;
  END IF;
  IF (v_fromdate <> '' AND v_todate <> '') THEN
  v_sqlquery := v_sqlquery || '  AND  CONVERT(DATE, CreateDate,103)  BETWEEN  REPLACE(CONVERT(DATE,''' || v_fromdate || ''',103),''/'',''-'')  AND REPLACE(CONVERT(DATE,''' || v_todate || ''',103),''/'',''-'')';
  END IF;
  IF (v_searchfield = 'Title') THEN
  v_sqlquery := v_sqlquery || ' AND Title LIKE ''%' || v_searchvalue || '%'' ';
  END IF;
  IF (v_orderby = 'DESC') THEN
  v_sqlquery := v_sqlquery || ('  ORDER BY brId ' || v_orderby || ' ');
  END IF;
  IF (v_orderby = 'ASC') THEN
  v_sqlquery := v_sqlquery || ('  ORDER BY brId ' || v_orderby || '  ');
  END IF;
  EXECUTE v_sqlquery;
  RAISE NOTICE '%', v_sqlquery;
  SELECT COUNT(rownumber) INTO v_recordcount FROM tmp_temp;
  SELECT COUNT(1) INTO v_recordcount FROM tmp_temp;
  RETURN QUERY SELECT * FROM tmp_temp WHERE rownumber BETWEEN v_startrowindex AND v_maxrows;
  DROP TABLE IF EXISTS tmp_temp;
  -- SET option (removed)
END;
$$;


--
-- Name: usp_getall_productlist(integer, integer, bigint, bigint, bigint, character varying, character varying, character varying, integer, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_getall_productlist(v_startrowindex integer DEFAULT 1, v_maxrows integer DEFAULT 1000, v_mprid bigint DEFAULT 0, v_sprid bigint DEFAULT 0, v_branchid bigint DEFAULT 0, v_cat_code character varying DEFAULT ''::character varying, v_searchfield character varying DEFAULT ''::character varying, v_searchvalue character varying DEFAULT ''::character varying, v_status integer DEFAULT 0, v_totalcount integer DEFAULT 0) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_minindex INT;
  v_maxindex INT;
  v_query text;
  v_catecode INT;
BEGIN
  v_minindex := (v_startrowindex - 1) * v_maxrows + 1;
  v_maxindex := v_startrowindex * v_maxrows;
  DROP TABLE IF EXISTS tmp_productlisttemp;
  CREATE TEMP TABLE tmp_productlisttemp (ROWNUMBER BIGINT GENERATED BY DEFAULT AS IDENTITY




,MPRID BIGINT 
,PRODUCTCODE VARCHAR( 50) 
,SUBPRCODE VARCHAR( 50) 
,PRODUCTTITLE VARCHAR( 300) 
,MAINCATNAME VARCHAR( 250) 
,QTY INT 
,UNIT VARCHAR( 50) 
,PRODUCTIMAGES VARCHAR( 1000) 
,MerchantName VARCHAR( 1000) 
,EMAILID VARCHAR( 100) 
,PHONE VARCHAR( 100) 
,SELLMRP DECIMAL 
,DAP DECIMAL 
,SPRID BIGINT 
,ISACTIVE boolean  ,
PROCUREMENTSLA INT,
REPLACEMENTDAY INT,
SHIPPINGCHARGES DECIMAL(18,2),
CASHONDELIVERY boolean,
WEIGHT_KG DECIMAL(18,2),
LENGTH_CMS DECIMAL(18,2),
BREADTH_CMS DECIMAL(18,2),
HEIGHT_CMS DECIMAL(18,2)
,MVAT DECIMAL 
,DEALSIDS VARCHAR(100)
,STOCKINQTY INT 
,STOCKOUTQTY INT 
,STOCKNETQTY INT 
,ISSTOCK boolean 
,VATTITLE VARCHAR(100) 
,PRODUCTCOUNT INT,
BV DECIMAL(18,2),
JP DECIMAL(18,2),
IsVerified int,
Subcategory varchar(500),
Discountpercentage decimal,
CreatedDate timestamp,
ModifyDate timestamp) ON COMMIT DROP;
  v_query := 'INSERT INTO #PRODUCTLISTTEMP SELECT PM.MPRID,PM.PRODUCTCODE,SM.SUBPRCODE,PM.PRODUCTTITLE, MC.MAINCATNAME,SM.QTY,SM.UNIT,SM.PRODUCTIMAGES,
ISNULL((PL.FNAME+PL.LNAME),'''') as MerchantName,ISNULL(PL.EMAILID,'''') AS EMAILID,ISNULL(PL.PHONE,'''') AS PHONE,
SM.SELLMRP,SM.DAP,SM.SPRID,SM.ISACTIVE,ISNULL(SM.PROCUREMENTSLA,0),ISNULL(SM.REPLACEMENTDAY,0),
CONVERT(DECIMAL(18,2),SM.SHIPPINGCHARGES),ISNULL(SM.CASHONDELIVERY,0),ISNULL(SM.WEIGHT_KG,0),ISNULL(SM.LENGTH_CMS,0),ISNULL(SM.BREADTH_CMS,0),ISNULL(SM.HEIGHT_CMS,0),
CONVERT(DECIMAL(18,0),ISNULL(V.VATPERCVALUE,0)) AS MVAT, ISNULL(SM.DEALSIDS,'''')
,ISNULL(SM.STOCKIN,0),ISNULL(SM.STOCKOUT,0),ISNULL(SM.STOCKNET,0),CONVERT(BIT, (CASE WHEN ISNULL(SM.STOCKNET,0) <= 0 THEN 0 ELSE 1 END)) AS ISSTOCK,V.VATTITLE,0 AS PRODUCTCOUNT,
ISNULL(SM.BV,0) AS BV,ISNULL(SM.PV,0) AS JP,SM.IsVerified AS IsVerified,isnull(km.subcatname,'''') ,isnull(DiscountPercentage,0),isnull(SM.CreatedDate,''''),isnull(SM.ModifyDate,'''')
FROM IMS_MASTERPRODUCT PM INNER JOIN IMS_SUBPRODUCT SM ON SM.MPRID=PM.MPRID 
INNER JOIN TBL_MAIN_CATEGORY MC ON MC.MAINCATID =PM.MAINCATEGORYID			 
LEFT  JOIN TBL_VAT_CATEGORIES V ON V.VCID = PM.VATCATEGORYID 
LEFT  JOIN PORTAL_LOGIN PL ON PL.PLID= PM.BranchId join tbl_sub_category km on PM.SubCategoryId=km.subcatid
WHERE PM.MPRID >0 ';
  IF (v_status > 0) THEN
  v_query := v_query || ' AND SM.ISACTIVE =' || CAST(v_status AS VARCHAR(20));
  END IF;
  IF (v_searchfield = 'EMAILID') THEN
  v_query := v_query || ' AND PL.Emailid LIKE ''%' || v_searchvalue || '%'' ';
  END IF;
  IF (v_searchfield = 'MerchantName') THEN
  v_query := v_query || ' AND (PL.FNAME+PL.LNAME) LIKE ''%' || v_searchvalue || '%'' ';
  END IF;
  IF (v_searchfield = 'PHONE') THEN
  v_query := v_query || ' AND PL.PHONE LIKE ''%' || v_searchvalue || '%'' ';
  END IF;
  IF (v_searchfield = 'PRODUCTTITLE') THEN
  v_query := v_query || ' AND PM.PRODUCTTITLE LIKE ''%' || v_searchvalue || '%'' ';
  END IF;
  IF (v_searchfield = 'MAINCATNAME') THEN
  v_query := v_query || ' AND MC.MAINCATNAME LIKE ''%' || v_searchvalue || '%'' ';
  END IF;
  IF (v_branchid > 0) THEN
  v_query := v_query || ' AND(' || CAST(v_branchid AS VARCHAR(50)) || ' = 1 OR PM.BranchId=' || CAST(v_branchid AS VARCHAR(50)) || ')';
  END IF;
  IF (v_mprid > 0) THEN
  v_query := v_query || ' AND PM.MPRID =' || CAST(v_mprid AS VARCHAR(20));
  END IF;
  IF (v_sprid > 0) THEN
  v_query := v_query || ' AND SM.SPRID =' || CAST(v_sprid AS VARCHAR(20));
  END IF;
  IF (v_cat_code <> '') THEN
  v_catecode := 0;
  SELECT catid INTO v_catecode FROM tbl_category WHERE cat_code = v_cat_code;
  IF (v_catecode > 0) THEN
  v_query := v_query || ' AND PM.CATID =' || CAST(v_catecode AS VARCHAR(20));
  ELSE
  SELECT subcatid INTO v_catecode FROM tbl_sub_category WHERE sub_cat_code = v_cat_code;
  v_query := v_query || ' AND PM.SUBCATEGORYID =' || CAST(v_catecode AS VARCHAR(20));
  END IF;
  END IF;
  v_query := v_query || ' ORDER BY  PM.MPRID DESC ';
  EXECUTE v_query;
  RETURN QUERY SELECT * FROM tmp_productlisttemp WHERE rownumber BETWEEN v_minindex AND v_maxindex;
  SELECT COUNT(rownumber) INTO v_totalcount FROM tmp_productlisttemp;
  DROP TABLE IF EXISTS tmp_productlisttemp;
  -- SET option (removed)
END;
$$;


--
-- Name: usp_getall_productlist_admin(integer, integer, character varying, character varying, integer, integer, integer, text, character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_getall_productlist_admin(v_startrowindex integer DEFAULT 1, v_maxrows integer DEFAULT 100, v_searchfield character varying DEFAULT ''::character varying, v_searchvalue character varying DEFAULT ''::character varying, v_totalcount integer DEFAULT 0, v_intresult integer DEFAULT 0, v_mode integer DEFAULT 2, v_id text DEFAULT '59'::text, v_remark character varying DEFAULT ''::character varying) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_minindex int;
  v_maxindex int;
  v_query text;
  v_catecode INT;
  v_sprid BigInt;
  v_mprid BigInt;
  v_branchid BigInt;
  v_companyid int;
  v_catid int;
  v_subcatid int;
  v_brand int;
  v_productcode varchar(50);
  v_subprcode varchar(50);
  v_prodtitle varchar(300);
  v_activefrom varchar(50);
  v_activeto varchar(50);
  v_shortdesc varchar(500);
  v_fulldesc text;
  v_isallowcoupon boolean;
  v_minorderqty int;
  v_maxorderqty int;
  v_paymode varchar(100);
  v_sellmrp decimal(18,2);
  v_discountper decimal(18,2);
  v_qty int;
  v_produnit varchar(50);
  v_color varchar(50);
  v_size varchar(50);
  v_prodimages text;
  v_allattributes text;
  v_vcid int;
  v_vatp decimal(18,2);
  v_directamt decimal(18,2);
  v_dap decimal(18,2);
  v_replacementday int;
  v_keyfeatures varchar(2000);
  v_stockin int;
  v_procurementsla int;
  v_shippingcharges decimal(18,2);
  v_cashondelivery boolean;
  v_pkg_weight_kg decimal(18,2);
  v_pkg_length_cms decimal(18,2);
  v_pkg_breadth_cms decimal(18,2);
  v_pkg_height_cms decimal(18,2);
  v_warrentyinfocare int;
  v_dealsids varchar(50);
  v_groupid varchar(50);
  v_strresult varchar(200);
  v_ywillrece decimal(18,4);
  v_ismerchantstatus int;
  v_productentry varchar(100);
  v_random varchar(50);
  v_fullfillment int;
  v_procurementtype int;
  v_hsn varchar(100);
  v_luxurycess decimal(18,4);
  v_manufacturingdetail varchar(1000);
  v_importerdetail varchar(1000);
  v_packerdetail varchar(1000);
  v_specification text;
  v_countryorigin int;
  v_getsprid int;
  v_prskucode Varchar(100);
  v_bv decimal(18,4);
  v_pv decimal(18,4);
  v_cashback_per decimal(18,4);
  v_activationpv decimal(18,4);
  v_title varchar(200);
  v_value varchar(200);
  v_query12 varchar(5000);
  v_count int;
  v_addattributeget varchar(300);
  v_mpaid bigint;
BEGIN
  IF (v_mode = 1) THEN
  v_minindex := (v_startrowindex - 1) * v_maxrows + 1;
  v_maxindex := v_startrowindex * v_maxrows;
  DROP TABLE IF EXISTS tmp_productlisttemp;
  CREATE TEMP TABLE tmp_productlisttemp (ROWNUMBER BIGINT GENERATED BY DEFAULT AS IDENTITY   
 ,MPRID BIGINT   
 ,PRODUCTCODE VARCHAR( 50)   
 ,SUBPRCODE VARCHAR( 50)   
 ,PRODUCTTITLE VARCHAR( 300)   
 ,MAINCATNAME VARCHAR( 250)   
 ,QTY INT   
 ,UNIT VARCHAR( 50)   
 ,PRODUCTIMAGES VARCHAR( 1000)   
 ,SELLMRP DECIMAL   
 ,DAP DECIMAL   
 ,SPRID BIGINT   
 ,ISACTIVE boolean  
 ,PROCUREMENTSLA INT  
 ,REPLACEMENTDAY INT  
 ,SHIPPINGCHARGES DECIMAL(18,2)  
 ,CASHONDELIVERY boolean  
 ,WEIGHT_KG DECIMAL(18,2)  
 ,LENGTH_CMS DECIMAL(18,2)  
 ,BREADTH_CMS DECIMAL(18,2)  
 ,HEIGHT_CMS DECIMAL(18,2)  
 ,MVAT DECIMAL   
 ,DEALSIDS VARCHAR(100)  
 ,STOCKINQTY INT   
 ,STOCKOUTQTY INT   
 ,STOCKNETQTY INT   
 ,ISSTOCK boolean   
 ,VATTITLE VARCHAR(100)   
 ,PRODUCTCOUNT INT  
 ,ISVERIFIED INT) ON COMMIT DROP;
  v_query := 'INSERT INTO #PRODUCTLISTTEMP SELECT PM.MPRID,PM.PRODUCTCODE,SM.SUBPRCODE,PM.PRODUCTTITLE, MC.MAINCATNAME,SM.QTY,SM.UNIT,SM.ProductImages,  
    SM.SELLMRP,SM.DAP,SM.SPRID,SM.ISACTIVE,ISNULL(SM.PROCUREMENTSLA,0),ISNULL(SM.REPLACEMENTDAY,0),  
 CONVERT(DECIMAL(18,2),SM.SHIPPINGCHARGES),ISNULL(SM.CASHONDELIVERY,0),ISNULL(SM.WEIGHT_KG,0),ISNULL(SM.LENGTH_CMS,0),ISNULL(SM.BREADTH_CMS,0),ISNULL(SM.HEIGHT_CMS,0),  
 CONVERT(DECIMAL(18,0),ISNULL(V.VATPERCVALUE,0)) AS MVAT, ISNULL(SM.DEALSIDS,'''')  
 ,ISNULL(SM.STOCKIN,0),ISNULL(SM.STOCKOUT,0),ISNULL(SM.STOCKNET,0),CONVERT(BIT, (CASE WHEN ISNULL(SM.STOCKNET,0) <= 0 THEN 0 ELSE 1 END)) AS ISSTOCK,V.VATTITLE,  
 0 AS PRODUCTCOUNT,SM.ISVERIFIED  
    FROM IMS_MASTERPRODUCT PM   
    INNER JOIN IMS_SUBPRODUCT SM ON SM.MPRID=PM.MPRID   
    INNER JOIN TBL_MAIN_CATEGORY MC ON MC.MAINCATID =PM.MAINCATEGORYID      
 LEFT  JOIN TBL_VAT_CATEGORIES V ON V.VCID = PM.VATCATEGORYID   
 WHERE PM.MPRID >0  and  SM.ISVERIFIED=1 and SM.ismerchantstatus=5';
  IF (v_id = 'Verified') THEN
  v_query := v_query || ' AND SM.ISVERIFIED=1 ';
  END IF;
  IF (v_id = 'Unverified') THEN
  v_query := v_query || ' AND SM.ISVERIFIED=0';
