  v_sprid := 0;
  v_mprid := 0;
  v_branchid := 0;
  v_companyid := 0;
  v_catid := 0;
  v_subcatid := 0;
  v_brand := 0;
  v_productcode := '';
  v_subprcode := '';
  v_prodtitle := '';
  v_activefrom := '';
  v_activeto := '';
  v_shortdesc := '';
  v_fulldesc := '';
  v_isallowcoupon := 0;
  v_minorderqty := 0;
  v_maxorderqty := 0;
  v_paymode := '';
  v_sellmrp := 0;
  v_discountper := 0;
  v_qty := 0;
  v_produnit := '';
  v_color := '';
  v_size := '';
  v_prodimages := '';
  v_allattributes := '';
  v_vcid := 0;
  v_vatp := 0;
  v_directamt := 0;
  v_dap := 100;
  v_replacementday := 0;
  v_keyfeatures := '';
  v_stockin := 0;
  v_procurementsla := 0;
  v_shippingcharges := 0;
  v_cashondelivery := 0;
  v_pkg_weight_kg := NULL;
  v_pkg_length_cms := NULL;
  v_pkg_breadth_cms := NULL;
  v_pkg_height_cms := NULL;
  v_warrentyinfocare := 0;
  v_dealsids := '';
  v_groupid := '';
  v_strresult := '';
  v_ywillrece := 0;
  v_ismerchantstatus := 0;
  v_productentry := '';
  v_random := '';
  v_fullfillment := 0;
  v_procurementtype := 0;
  v_getsprid := 0;
  SELECT productcode, subcategoryid, brandid, producttitle, shotdescription, fulldescription, minorderqty, maxorderqty, paymode, vatcategoryid, companyid, branchid, catid, '', keyfeatures INTO v_productcode, v_subcatid, v_branchid, v_prodtitle, v_shortdesc, v_fulldesc, v_minorderqty, v_maxorderqty, v_paymode, v_vcid, v_companyid, v_branchid, v_catid, v_allattributes, v_keyfeatures FROM ims_masterproduct_temp WHERE mprid = v_id;
  SELECT subprcode, qty, unit, stockin, productimages, sellmrp, dap, dealsids, groupid, replacementday, procurementsla, cashondelivery, shippingcharges, discountpercentage, weight_kg, length_cms, breadth_cms, height_cms, warrentyinfocare, ywillrece, 5, productentry, puidno, fullfilmentby, procurementtype, hsn, luxurycess, manufacturerdetails, importerdetails, packerdetails, countryorigin, sprid INTO v_subprcode, v_qty, v_produnit, v_stockin, v_prodimages, v_sellmrp, v_dap, v_dealsids, v_groupid, v_replacementday, v_procurementsla, v_cashondelivery, v_shippingcharges, v_discountper, v_pkg_weight_kg, v_pkg_length_cms, v_pkg_breadth_cms, v_pkg_height_cms, v_warrentyinfocare, v_ywillrece, v_ismerchantstatus, v_productentry, v_random, v_fullfillment, v_procurementtype, v_hsn, v_luxurycess, v_manufacturingdetail, v_importerdetail, v_packerdetail, v_countryorigin, v_getsprid FROM ims_subproduct_temp WHERE mprid = v_id;
  v_title := '';
  v_value := '';
  v_query12 := '';
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp (rowNumber int,MPAID bigint) ON COMMIT DROP;
  v_query12 := 'insert into #temp SELECT  ROW_NUMBER() over (order by MPAID desc) as rowNumber,MPAID  from IMS_MasterProductAttribute_Temp  where sprid=' || CAST(v_getsprid AS VARCHAR(20));
  EXECUTE v_query12;
  v_count := 0;
  v_addattributeget := '';
  v_mpaid := 0;
  SELECT COUNT(1) INTO v_count FROM tmp_temp;
  WHILE (v_count > 0) LOOP
  SELECT mpaid INTO v_mpaid FROM tmp_temp WHERE rownumber = v_count;
  SELECT title, value INTO v_title, v_value FROM ims_masterproductattribute_temp WHERE mpaid = v_mpaid;
  v_addattributeget := v_addattributeget || v_title || '~' || v_value || '^';
  v_title := '';
  v_value := '';
  v_count := v_count - 1;
  END LOOP;
  DROP TABLE IF EXISTS tmp_temp;
  v_allattributes := v_addattributeget;
  SELECT v_strresult INTO v_strresult FROM dbo.ims_usp_createproduct_temp_movetoready(v_sprid => v_sprid, v_mprid => v_mprid, v_branchid => v_branchid, v_companyid => v_companyid, v_catid => v_catid, v_subcatid => v_subcatid, v_brand => v_brand, v_productcode => v_productcode, v_subprcode => v_subprcode, v_prodtitle => v_prodtitle, v_activefrom => v_activefrom, v_activeto => v_activeto, v_shortdesc => v_shortdesc, v_fulldesc => v_fulldesc, v_isallowcoupon => v_isallowcoupon, v_minorderqty => v_minorderqty, v_maxorderqty => v_maxorderqty, v_paymode => v_paymode, v_sellmrp => v_sellmrp, v_discountper => v_discountper, v_qty => v_qty, v_produnit => v_produnit, v_color => v_color, v_size => v_size, v_prodimages => v_prodimages, v_allattributes => v_allattributes, v_vcid => v_vcid, v_vatp => v_vatp, v_directamt => v_directamt, v_dap => v_dap, v_replacementday => v_replacementday, v_keyfeatures => v_keyfeatures, v_stockin => v_stockin, v_procurementsla => v_procurementsla, v_shippingcharges => v_shippingcharges, v_cashondelivery => v_cashondelivery, v_pkg_weight_kg => v_pkg_weight_kg, v_pkg_length_cms => v_pkg_length_cms, v_pkg_breadth_cms => v_pkg_breadth_cms, v_pkg_height_cms => v_pkg_height_cms, v_warrentyinfocare => v_warrentyinfocare, v_dealsids => v_dealsids, v_groupid => v_groupid, v_strresult => v_strresult, v_ywillrece => v_ywillrece, v_ismerchantstatus => v_ismerchantstatus, v_productentry => v_productentry, v_random => v_random, v_fullfillment => v_fullfillment, v_procurementtype => v_procurementtype, v_hsn => v_hsn, v_luxurycess => v_luxurycess, v_manufacturingdetail => v_manufacturingdetail, v_importerdetail => v_importerdetail, v_packerdetail => v_packerdetail, v_countryorigin => v_countryorigin);
  IF (v_strresult = 'Your Product Added Ready List Successfully.') THEN
  v_intresult := 2;
  ELSE
  v_intresult := 5;
  END IF;
  UPDATE ims_subproduct_temp SET ismerchantstatus = 5, rejectremark = v_remark WHERE mprid IN (SELECT value FROM dbo.SPLITSTRINGBYCUSTOMSYMBOL1(v_id, ','));
  SELECT 2 INTO v_intresult;
  ELSE
  IF (v_mode = 4) THEN
  UPDATE ims_subproduct SET isverified = 0, rejectremark = v_remark WHERE mprid IN (SELECT value FROM dbo.SPLITSTRINGBYCUSTOMSYMBOL1(v_id, ','));
  SELECT 2 INTO v_intresult;
  ELSE
  IF (v_mode = 3) THEN
  UPDATE ims_subproduct SET isverified = 2, rejectremark = v_remark WHERE mprid IN (SELECT value FROM dbo.SPLITSTRINGBYCUSTOMSYMBOL1(v_id, ','));
  SELECT 3 INTO v_intresult;
  ELSE
