  END IF;
  END IF;
  END IF;
  END IF;
END;
$$;


--
-- Name: usp_getall_productlist_bulk(integer, integer, bigint, bigint, bigint, character varying, character varying, character varying, integer, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_getall_productlist_bulk(v_startrowindex integer DEFAULT 1, v_maxrows integer DEFAULT 1000, v_mprid bigint DEFAULT 0, v_sprid bigint DEFAULT 0, v_branchid bigint DEFAULT 0, v_cat_code character varying DEFAULT ''::character varying, v_searchfield character varying DEFAULT ''::character varying, v_searchvalue character varying DEFAULT ''::character varying, v_status integer DEFAULT 0, v_totalcount integer DEFAULT 0) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_minindex INT;
  v_maxindex INT;
  v_query text;
  v_catecode INT;
BEGIN
  v_minindex := (v_startrowindex - 1) * v_maxrows + 1;
  v_maxindex := v_startrowindex * v_maxrows;
  DROP TABLE IF EXISTS tmp_productlisttemp;
  CREATE TEMP TABLE tmp_productlisttemp (ROWNUMBER BIGINT GENERATED BY DEFAULT AS IDENTITY




,MPRID BIGINT 
,PRODUCTCODE VARCHAR( 50) 
,SUBPRCODE VARCHAR( 50) 
,PRODUCTTITLE VARCHAR( 300) 
,MAINCATNAME VARCHAR( 250) 
,QTY INT 
,UNIT VARCHAR( 50) 
,PRODUCTIMAGES VARCHAR( 1000) 
,MerchantName VARCHAR( 1000) 
,EMAILID VARCHAR( 100) 
,PHONE VARCHAR( 100) 
,SELLMRP DECIMAL 
,DAP DECIMAL 
,SPRID BIGINT 
,ISACTIVE boolean  ,
PROCUREMENTSLA INT,
REPLACEMENTDAY INT,
SHIPPINGCHARGES DECIMAL(18,2),
CASHONDELIVERY boolean,
WEIGHT_KG DECIMAL(18,2),
LENGTH_CMS DECIMAL(18,2),
BREADTH_CMS DECIMAL(18,2),
HEIGHT_CMS DECIMAL(18,2)
,MVAT DECIMAL 
,DEALSIDS VARCHAR(100)
,STOCKINQTY INT 
,STOCKOUTQTY INT 
,STOCKNETQTY INT 
,ISSTOCK boolean 
,VATTITLE VARCHAR(100) 
,PRODUCTCOUNT INT,
BV DECIMAL(18,2),
JP DECIMAL(18,2),
IsVerified int,
Subcategory varchar(500),
Discountpercentage decimal,
CreatedDate timestamp,
ModifyDate timestamp,
RequestId VARCHAR(100)) ON COMMIT DROP;
  v_query := 'INSERT INTO #PRODUCTLISTTEMP SELECT PM.MPRID,PM.PRODUCTCODE,SM.SUBPRCODE,PM.PRODUCTTITLE, MC.MAINCATNAME,SM.QTY,SM.UNIT,SM.PRODUCTIMAGES,
ISNULL((PL.FNAME+PL.LNAME),'''') as MerchantName,ISNULL(PL.EMAILID,'''') AS EMAILID,ISNULL(PL.PHONE,'''') AS PHONE,
SM.SELLMRP,SM.DAP,SM.SPRID,SM.ISACTIVE,ISNULL(SM.PROCUREMENTSLA,0),ISNULL(SM.REPLACEMENTDAY,0),
CONVERT(DECIMAL(18,2),SM.SHIPPINGCHARGES),ISNULL(SM.CASHONDELIVERY,0),ISNULL(SM.WEIGHT_KG,0),ISNULL(SM.LENGTH_CMS,0),ISNULL(SM.BREADTH_CMS,0),ISNULL(SM.HEIGHT_CMS,0),
CONVERT(DECIMAL(18,0),ISNULL(V.VATPERCVALUE,0)) AS MVAT, ISNULL(SM.DEALSIDS,'''')
,ISNULL(SM.STOCKIN,0),ISNULL(SM.STOCKOUT,0),ISNULL(SM.STOCKNET,0),CONVERT(BIT, (CASE WHEN ISNULL(SM.STOCKNET,0) <= 0 THEN 0 ELSE 1 END)) AS ISSTOCK,V.VATTITLE,0 AS PRODUCTCOUNT,
ISNULL(SM.BV,0) AS BV,ISNULL(SM.PV,0) AS JP,SM.IsVerified AS IsVerified,isnull(km.subcatname,'''') ,isnull(DiscountPercentage,0),isnull(SM.CreatedDate,''''),isnull(SM.ModifyDate,''''),isnull(SM.productentry,'''')
FROM IMS_MASTERPRODUCT_temp PM INNER JOIN IMS_SUBPRODUCT_temp SM ON SM.MPRID=PM.MPRID 
INNER JOIN TBL_MAIN_CATEGORY MC ON MC.MAINCATID =PM.MAINCATEGORYID			 
LEFT  JOIN TBL_VAT_CATEGORIES V ON V.VCID = PM.VATCATEGORYID 
LEFT  JOIN PORTAL_LOGIN PL ON PL.PLID= PM.BranchId join tbl_sub_category km on PM.SubCategoryId=km.subcatid
WHERE  1=1 and SM.productentry!=''Single'' ';
  IF (v_status > 0) THEN
  v_query := v_query || ' AND SM.ISACTIVE =' || CAST(v_status AS VARCHAR(20));
  END IF;
  IF (v_searchfield = 'EMAILID') THEN
  v_query := v_query || ' AND PL.Emailid LIKE ''%' || v_searchvalue || '%'' ';
  END IF;
  IF (v_searchfield = 'MerchantName') THEN
  v_query := v_query || ' AND (PL.FNAME+PL.LNAME) LIKE ''%' || v_searchvalue || '%'' ';
  END IF;
  IF (v_searchfield = 'PHONE') THEN
  v_query := v_query || ' AND PL.PHONE LIKE ''%' || v_searchvalue || '%'' ';
  END IF;
  IF (v_searchfield = 'PRODUCTTITLE') THEN
  v_query := v_query || ' AND PM.PRODUCTTITLE LIKE ''%' || v_searchvalue || '%'' ';
  END IF;
  IF (v_searchfield = 'MAINCATNAME') THEN
  v_query := v_query || ' AND MC.MAINCATNAME LIKE ''%' || v_searchvalue || '%'' ';
  END IF;
  IF (v_branchid > 0) THEN
  v_query := v_query || ' AND(' || CAST(v_branchid AS VARCHAR(50)) || ' = 1 OR PM.BranchId=' || CAST(v_branchid AS VARCHAR(50)) || ')';
  END IF;
  IF (v_mprid > 0) THEN
  v_query := v_query || ' AND PM.MPRID =' || CAST(v_mprid AS VARCHAR(20));
  END IF;
  IF (v_sprid > 0) THEN
  v_query := v_query || ' AND SM.SPRID =' || CAST(v_sprid AS VARCHAR(20));
  END IF;
  IF (v_cat_code <> '') THEN
  v_catecode := 0;
  SELECT catid INTO v_catecode FROM tbl_category WHERE cat_code = v_cat_code;
  IF (v_catecode > 0) THEN
  v_query := v_query || ' AND PM.CATID =' || CAST(v_catecode AS VARCHAR(20));
  ELSE
  SELECT subcatid INTO v_catecode FROM tbl_sub_category WHERE sub_cat_code = v_cat_code;
  v_query := v_query || ' AND PM.SUBCATEGORYID =' || CAST(v_catecode AS VARCHAR(20));
  END IF;
  END IF;
  v_query := v_query || ' ORDER BY  PM.MPRID DESC ';
  EXECUTE v_query;
  RETURN QUERY SELECT * FROM tmp_productlisttemp WHERE rownumber BETWEEN v_minindex AND v_maxindex;
  SELECT COUNT(rownumber) INTO v_totalcount FROM tmp_productlisttemp;
  DROP TABLE IF EXISTS tmp_productlisttemp;
  -- SET option (removed)
END;
$$;


--
-- Name: usp_getall_productlist_single(integer, integer, bigint, bigint, bigint, character varying, character varying, character varying, character varying, character varying, integer, integer, integer, integer, character varying, character varying, character varying, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_getall_productlist_single(v_startrowindex integer DEFAULT 1, v_maxrows integer DEFAULT 1000, v_mprid bigint DEFAULT 0, v_sprid bigint DEFAULT 0, v_branchid bigint DEFAULT 3, v_cat_code character varying DEFAULT ''::character varying, v_searchfield character varying DEFAULT ''::character varying, v_searchvalue character varying DEFAULT ''::character varying, v_fromdate character varying DEFAULT ''::character varying, v_todate character varying DEFAULT ''::character varying, v_status integer DEFAULT '-1'::integer, v_totalcount integer DEFAULT 0, v_subcatid integer DEFAULT 0, v_isverified integer DEFAULT 0, v_searchvaluesubcategory character varying DEFAULT ''::character varying, v_merchantname character varying DEFAULT ''::character varying, v_productname character varying DEFAULT ''::character varying, v_plid integer DEFAULT 0) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_minindex INT;
  v_maxindex INT;
  v_query text;
  v_catecode INT;
BEGIN
  v_minindex := (v_startrowindex - 1) * v_maxrows + 1;
  v_maxindex := v_startrowindex * v_maxrows;
  DROP TABLE IF EXISTS tmp_productlisttemp;
  CREATE TEMP TABLE tmp_productlisttemp (ROWNUMBER BIGINT GENERATED BY DEFAULT AS IDENTITY




,MPRID BIGINT 
,PRODUCTCODE VARCHAR( 50) 
,SUBPRCODE VARCHAR( 50) 
,PRODUCTTITLE VARCHAR( 300) 
,MAINCATNAME VARCHAR( 250) 
,QTY INT 
,UNIT VARCHAR( 50) 
,PRODUCTIMAGES VARCHAR( 1000) 
,MerchantName VARCHAR( 1000) 
,EMAILID VARCHAR( 100) 
,PHONE VARCHAR( 100) 
,SELLMRP DECIMAL(18,2) 
,DAP DECIMAL(18,2) 
,SPRID BIGINT 
,ISACTIVE boolean  ,
PROCUREMENTSLA INT,
REPLACEMENTDAY INT,
SHIPPINGCHARGES DECIMAL(18,2),
CASHONDELIVERY boolean,
WEIGHT_KG DECIMAL(18,2),
LENGTH_CMS DECIMAL(18,2),
BREADTH_CMS DECIMAL(18,2),
HEIGHT_CMS DECIMAL(18,2)
,MVAT DECIMAL 
,DEALSIDS VARCHAR(100)
,STOCKINQTY INT 
,STOCKOUTQTY INT 
,STOCKNETQTY INT 
,ISSTOCK boolean 
,VATTITLE VARCHAR(100) 
,PRODUCTCOUNT INT,
BV DECIMAL(18,2),
JP DECIMAL(18,2),
IsVerified int,
Subcategory varchar(500),
Discountpercentage decimal(18,2),
CreatedDate timestamp,
ModifyDate timestamp,
ismerchantstatus int,
COMPANYNAME VARCHAR(500),
RejectRemark varchar(500)) ON COMMIT DROP;
  v_query := 'INSERT INTO #PRODUCTLISTTEMP SELECT PM.MPRID,PM.PRODUCTCODE,SM.SUBPRCODE,PM.PRODUCTTITLE, MC.MAINCATNAME,SM.QTY,SM.UNIT,SM.PRODUCTIMAGES,
ISNULL((PM5.COMPANYNAME),'''') as MerchantName,ISNULL(PL.EMAILID,'''') AS EMAILID,ISNULL(PL.PHONE,'''') AS PHONE,
SM.SELLMRP,SM.DAP,SM.SPRID,SM.ISACTIVE,ISNULL(SM.PROCUREMENTSLA,0),ISNULL(SM.REPLACEMENTDAY,0),
CONVERT(DECIMAL(18,2),SM.SHIPPINGCHARGES),ISNULL(SM.CASHONDELIVERY,0),ISNULL(SM.WEIGHT_KG,0),ISNULL(SM.LENGTH_CMS,0),ISNULL(SM.BREADTH_CMS,0),ISNULL(SM.HEIGHT_CMS,0),
CONVERT(DECIMAL(18,2),ISNULL(V.VATPERCVALUE,0)) AS MVAT, ISNULL(SM.DEALSIDS,'''')
,ISNULL(SM.STOCKIN,0),ISNULL(SM.STOCKOUT,0),ISNULL(SM.STOCKNET,0),CONVERT(BIT, (CASE WHEN ISNULL(SM.STOCKNET,0) <= 0 THEN 0 ELSE 1 END)) AS ISSTOCK,V.VATTITLE,0 AS PRODUCTCOUNT,
ISNULL(SM.BV,0) AS BV,ISNULL(SM.PV,0) AS JP,SM.IsVerified AS IsVerified,isnull(km.subcatname,'''') ,isnull(DiscountPercentage,0),
isnull(SM.CreatedDate,''''),isnull(SM.ModifyDate,''''),isnull(SM.ismerchantstatus,0),ISNULL(PM5.COMPANYNAME,''''),Isnull(SM.Rejectremark,'''')
FROM IMS_MASTERPRODUCT PM    
INNER JOIN  IMS_SUBPRODUCT SM ON SM.MPRID=PM.MPRID  
INNER JOIN TBL_MAIN_CATEGORY MC ON MC.MAINCATID =PM.MAINCATEGORYID			 
LEFT  JOIN TBL_VAT_CATEGORIES V ON V.VCID = PM.VATCATEGORYID 
LEFT  JOIN PORTAL_LOGIN PL ON PL.PLID= PM.BranchId join tbl_sub_category km on PM.SubCategoryId=km.subcatid
LEFT JOIN PORTAL_MASTER PM5 ON PM5.PMID= PL.PMID
WHERE (PM.MPRID >0) and SM.productentry=''Single'' ';
  IF (v_plid > 0) THEN
  v_query := v_query || ' AND PL.PLID = ' || CAST(v_plid AS VARCHAR(20));
  END IF;
  IF (v_status >= 0) THEN
  v_query := v_query || ' AND isnull(SM.ismerchantstatus,0) =' || CAST(v_status AS VARCHAR(20));
  END IF;
  IF (v_isverified < 0) THEN
  v_query := v_query || ' AND isnull(SM.IsVerified,0) =' || CAST(v_isverified AS VARCHAR(20));
  END IF;
  IF (v_fromdate = '' OR v_todate = '') THEN
  IF (v_fromdate <> '') THEN
  v_query := v_query || ' AND CONVERT(DATE, SM.ModifyDate,103) >= REPLACE(CONVERT(DATE,''' || v_fromdate || ''',103),''/'',''-'') ';
  END IF;
  IF (v_todate <> '') THEN
  v_query := v_query || ' AND CONVERT(DATE, SM.ModifyDate,103)  <=REPLACE(CONVERT(DATE,''' || v_todate || ''',103),''/'',''-'') ';
  END IF;
  END IF;
  IF (v_fromdate <> '' AND v_todate <> '') THEN
  v_query := v_query || '  AND  CONVERT(DATE, SM.ModifyDate,103)  BETWEEN  REPLACE(CONVERT(DATE,''' || v_fromdate || ''',103),''/'',''-'')  AND REPLACE(CONVERT(DATE,''' || v_todate || ''',103),''/'',''-'')';
  END IF;
  IF (v_productname <> '') THEN
  v_productname := REPLACE(v_productname, '''', '''''');
  v_query := v_query || ' and PM.ProductTitle =''' || v_productname || '''';
  END IF;
  IF (v_merchantname <> '') THEN
  v_query := v_query || ' AND (PM5.COMPANYNAME) LIKE ''%' || v_merchantname || '%'' ';
  END IF;
  IF (v_searchvalue <> '') THEN
  v_query := v_query || ' AND sm.SUBPRCODE LIKE ''%' || v_searchvalue || '%'' ';
  END IF;
  IF (v_searchvaluesubcategory <> '') THEN
  v_searchvaluesubcategory := REPLACE(v_searchvaluesubcategory, '''', '''''');
  v_query := v_query || 'AND km.subcatname LIKE''%' || v_searchvaluesubcategory || '%''';
  END IF;
  IF (v_branchid > 0) THEN
  v_query := v_query || ' AND PM.BranchId=' || CAST(v_branchid AS VARCHAR(50));
  END IF;
  IF (v_mprid > 0) THEN
  v_query := v_query || ' AND PM.MPRID =' || CAST(v_mprid AS VARCHAR(20));
  END IF;
  IF (v_sprid > 0) THEN
  v_query := v_query || ' AND SM.SPRID =' || CAST(v_sprid AS VARCHAR(20));
  END IF;
  IF (v_cat_code <> '') THEN
  v_catecode := 0;
  SELECT catid INTO v_catecode FROM tbl_category WHERE cat_code = v_cat_code;
  IF (v_catecode > 0) THEN
  v_query := v_query || ' AND PM.CATID =' || CAST(v_catecode AS VARCHAR(20));
  ELSE
  SELECT subcatid INTO v_catecode FROM tbl_sub_category WHERE sub_cat_code = v_cat_code;
  v_query := v_query || ' AND PM.SUBCATEGORYID =' || CAST(v_catecode AS VARCHAR(20));
  END IF;
  END IF;
  IF (v_subcatid <> '') THEN
  v_query := v_query || ' AND km.subcatid =' || CAST(v_subcatid AS VARCHAR(20));
  END IF;
  v_query := v_query || ' ORDER BY  PM.MPRID DESC ';
  RAISE NOTICE '%', (v_query);
  EXECUTE v_query;
  RETURN QUERY SELECT * FROM tmp_productlisttemp WHERE rownumber BETWEEN v_minindex AND v_maxindex;
  SELECT COUNT(rownumber) INTO v_totalcount FROM tmp_productlisttemp;
  DROP TABLE IF EXISTS tmp_productlisttemp;
  -- SET option (removed)
END;
$$;


--
-- Name: usp_getall_productlist_single_temp(integer, integer, bigint, bigint, bigint, character varying, character varying, character varying, character varying, character varying, integer, integer, integer, integer, character varying, character varying, character varying, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_getall_productlist_single_temp(v_startrowindex integer DEFAULT 1, v_maxrows integer DEFAULT 1000, v_mprid bigint DEFAULT 0, v_sprid bigint DEFAULT 0, v_branchid bigint DEFAULT 2, v_cat_code character varying DEFAULT ''::character varying, v_searchfield character varying DEFAULT ''::character varying, v_searchvalue character varying DEFAULT ''::character varying, v_fromdate character varying DEFAULT ''::character varying, v_todate character varying DEFAULT ''::character varying, v_status integer DEFAULT '-1'::integer, v_totalcount integer DEFAULT 0, v_subcatid integer DEFAULT 0, v_isverified integer DEFAULT 0, v_searchvaluesubcategory character varying DEFAULT ''::character varying, v_merchantname character varying DEFAULT ''::character varying, v_productname character varying DEFAULT ''::character varying, v_plid integer DEFAULT 0) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_minindex INT;
  v_maxindex INT;
  v_query text;
  v_catecode INT;
BEGIN
  v_minindex := (v_startrowindex - 1) * v_maxrows + 1;
  v_maxindex := v_startrowindex * v_maxrows;
  DROP TABLE IF EXISTS tmp_productlisttemp;
  CREATE TEMP TABLE tmp_productlisttemp (ROWNUMBER BIGINT GENERATED BY DEFAULT AS IDENTITY            
,MPRID BIGINT         
,PRODUCTCODE VARCHAR( 50)         
,SUBPRCODE VARCHAR( 50)         
,PRODUCTTITLE VARCHAR( 300)         
,MAINCATNAME VARCHAR( 250)         
,QTY INT         
,UNIT VARCHAR( 50)         
,PRODUCTIMAGES VARCHAR( 1000)         
,MerchantName VARCHAR( 1000)         
,EMAILID VARCHAR( 100)         
,PHONE VARCHAR( 100)         
,SELLMRP DECIMAL         
,DAP DECIMAL         
,SPRID BIGINT         
,ISACTIVE boolean  ,        
PROCUREMENTSLA INT,        
REPLACEMENTDAY INT,        
SHIPPINGCHARGES DECIMAL(18,2),        
CASHONDELIVERY boolean,        
WEIGHT_KG DECIMAL(18,2),        
LENGTH_CMS DECIMAL(18,2),        
BREADTH_CMS DECIMAL(18,2),        
HEIGHT_CMS DECIMAL(18,2)        
,MVAT DECIMAL         
,DEALSIDS VARCHAR(100)        
,STOCKINQTY INT         
,STOCKOUTQTY INT         
,STOCKNETQTY INT         
,ISSTOCK boolean         
,VATTITLE VARCHAR(100)         
,PRODUCTCOUNT INT,        
BV DECIMAL(18,2),        
JP DECIMAL(18,2),        
IsVerified int,        
Subcategory varchar(500),        
Discountpercentage decimal,        
CreatedDate timestamp,        
ModifyDate timestamp,        
ismerchantstatus int,        
COMPANYNAME VARCHAR(500),        
RejectRemark varchar(500) ,    
is_Offer_available boolean) ON COMMIT DROP;
  v_query := 'INSERT INTO #PRODUCTLISTTEMP SELECT PM.MPRID,PM.PRODUCTCODE,SM.SUBPRCODE,PM.PRODUCTTITLE, MC.MAINCATNAME,SM.QTY,SM.UNIT,SM.PRODUCTIMAGES,        
ISNULL((PM5.COMPANYNAME),'''') as MerchantName,ISNULL(PL.EMAILID,'''') AS EMAILID,ISNULL(PL.PHONE,'''') AS PHONE,        
SM.SELLMRP,SM.DAP,SM.SPRID,SM.ISACTIVE,ISNULL(SM.PROCUREMENTSLA,0),ISNULL(SM.REPLACEMENTDAY,0),        
CONVERT(DECIMAL(18,2),SM.SHIPPINGCHARGES),ISNULL(SM.CASHONDELIVERY,0),ISNULL(SM.WEIGHT_KG,0),ISNULL(SM.LENGTH_CMS,0),ISNULL(SM.BREADTH_CMS,0),ISNULL(SM.HEIGHT_CMS,0),        
CONVERT(DECIMAL(18,0),ISNULL(V.VATPERCVALUE,0)) AS MVAT, ISNULL(SM.DEALSIDS,'''')        
,ISNULL(SM.STOCKIN,0),ISNULL(SM.STOCKOUT,0),ISNULL(SM.STOCKNET,0),CONVERT(BIT, (CASE WHEN ISNULL(SM.STOCKNET,0) <= 0 THEN 0 ELSE 1 END)) AS ISSTOCK,V.VATTITLE,0 AS PRODUCTCOUNT,        
ISNULL(SM.BV,0) AS BV,ISNULL(SM.PV,0) AS JP,SM.IsVerified AS IsVerified,isnull(km.subcatname,'''') ,isnull(DiscountPercentage,0),        
isnull(SM.CreatedDate,''''),isnull(SM.ModifyDate,''''),isnull(SM.ismerchantstatus,0),ISNULL(PM5.COMPANYNAME,''''),Isnull(SM.Rejectremark,'''') ,    
(case when offer.OPID is not null then 1 else 0 end) is_Offer_available    
    
FROM IMS_MASTERPRODUCT_TEMP PM            
INNER JOIN  IMS_SUBPRODUCT_TEMP SM ON SM.MPRID=PM.MPRID          
INNER JOIN TBL_MAIN_CATEGORY MC ON MC.MAINCATID =PM.MAINCATEGORYID            
LEFT  JOIN TBL_VAT_CATEGORIES V ON V.VCID = PM.VATCATEGORYID         
LEFT  JOIN PORTAL_LOGIN PL ON PL.PLID= PM.BranchId join tbl_sub_category km on PM.SubCategoryId=km.subcatid        
LEFT JOIN PORTAL_MASTER PM5 ON PM5.PMID= PL.PMID     
LEFT JOIN TBL_OFFER_ON_PRODUCT Offer ON SM.SPRID= offer.PRODUCT_ID and getdate() between offer.Offer_start and offer.Offer_End   
WHERE (PM.MPRID >0) and SM.productentry=''Single'' ';
  IF (v_plid > 0) THEN
  v_query := v_query || ' AND PL.PLID = ' || CAST(v_plid AS VARCHAR(20));
  END IF;
  IF (v_status >= 0) THEN
  v_query := v_query || ' AND isnull(SM.ismerchantstatus,0) =' || CAST(v_status AS VARCHAR(20));
  END IF;
  IF (v_isverified < 0) THEN
  v_query := v_query || ' AND isnull(SM.IsVerified,0) =' || CAST(v_isverified AS VARCHAR(20));
  END IF;
  IF (v_fromdate = '' OR v_todate = '') THEN
  IF (v_fromdate <> '') THEN
  v_query := v_query || ' AND CONVERT(DATE, SM.ModifyDate,103) >= REPLACE(CONVERT(DATE,''' || v_fromdate || ''',103),''/'',''-'') ';
  END IF;
  IF (v_todate <> '') THEN
  v_query := v_query || ' AND CONVERT(DATE, SM.ModifyDate,103)  <=REPLACE(CONVERT(DATE,''' || v_todate || ''',103),''/'',''-'') ';
  END IF;
  END IF;
  IF (v_fromdate <> '' AND v_todate <> '') THEN
  v_query := v_query || '  AND  CONVERT(DATE, SM.ModifyDate,103)  BETWEEN  REPLACE(CONVERT(DATE,''' || v_fromdate || ''',103),''/'',''-'')  AND REPLACE(CONVERT(DATE,''' || v_todate || ''',103),''/'',''-'')';
  END IF;
  IF (v_productname <> '') THEN
  v_productname := REPLACE(v_productname, '''', '''''');
  v_query := v_query || ' and PM.ProductTitle =''' || v_productname || '''';
  END IF;
  IF (v_merchantname <> '') THEN
  v_query := v_query || ' AND (PM5.COMPANYNAME) LIKE ''%' || v_merchantname || '%'' ';
  END IF;
  IF (v_searchvalue <> '') THEN
  v_query := v_query || ' AND sm.SUBPRCODE LIKE ''%' || v_searchvalue || '%'' ';
  END IF;
  IF (v_searchvaluesubcategory <> '') THEN
  v_searchvaluesubcategory := REPLACE(v_searchvaluesubcategory, '''', '''''');
  v_query := v_query || 'AND km.subcatname LIKE''%' || v_searchvaluesubcategory || '%''';
  END IF;
  IF (v_branchid > 0) THEN
  v_query := v_query || ' AND PM.BranchId=' || CAST(v_branchid AS VARCHAR(50));
  END IF;
  IF (v_mprid > 0) THEN
  v_query := v_query || ' AND PM.MPRID =' || CAST(v_mprid AS VARCHAR(20));
  END IF;
  IF (v_sprid > 0) THEN
  v_query := v_query || ' AND SM.SPRID =' || CAST(v_sprid AS VARCHAR(20));
  END IF;
  IF (v_cat_code <> '') THEN
  v_catecode := 0;
  SELECT catid INTO v_catecode FROM tbl_category WHERE cat_code = v_cat_code;
  IF (v_catecode > 0) THEN
  v_query := v_query || ' AND PM.CATID =' || CAST(v_catecode AS VARCHAR(20));
  ELSE
  SELECT subcatid INTO v_catecode FROM tbl_sub_category WHERE sub_cat_code = v_cat_code;
  v_query := v_query || ' AND PM.SUBCATEGORYID =' || CAST(v_catecode AS VARCHAR(20));
  END IF;
  END IF;
  IF (v_subcatid <> '') THEN
  v_query := v_query || ' AND km.subcatid =' || CAST(v_subcatid AS VARCHAR(20));
  END IF;
  v_query := v_query || ' ORDER BY  PM.MPRID DESC ';
  RAISE NOTICE '%', (v_query);
  EXECUTE v_query;
  RETURN QUERY SELECT * FROM tmp_productlisttemp WHERE rownumber BETWEEN v_minindex AND v_maxindex ORDER BY rownumber ASC NULLS FIRST;
  SELECT COUNT(rownumber) INTO v_totalcount FROM tmp_productlisttemp;
  DROP TABLE IF EXISTS tmp_productlisttemp;
  -- SET option (removed)
END;
$$;


--
-- Name: usp_getall_productlist_withbv(integer, integer, bigint, bigint, bigint, character varying, character varying, character varying, character varying, integer, integer, integer, character varying, character varying, character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_getall_productlist_withbv(v_startrowindex integer DEFAULT 1, v_maxrows integer DEFAULT 100, v_mprid bigint DEFAULT 0, v_sprid bigint DEFAULT 0, v_branchid bigint DEFAULT 0, v_cat_code character varying DEFAULT ''::character varying, v_searchfield character varying DEFAULT ''::character varying, v_searchvalue character varying DEFAULT ''::character varying, v_company character varying DEFAULT ''::character varying, v_status integer DEFAULT 1, v_totalcount integer DEFAULT 0, v_isstock integer DEFAULT 0, v_productname character varying DEFAULT ''::character varying, v_searchvaluesubcategory character varying DEFAULT ''::character varying, v_merchantname character varying DEFAULT 'Prem Gift Palace'::character varying) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_minindex INT;
  v_maxindex INT;
  v_query text;
  v_catecode INT;
  v_minstock int;
  v_maxstock int;
BEGIN
  v_minindex := (v_startrowindex - 1) * v_maxrows + 1;
  v_maxindex := v_startrowindex * v_maxrows;
  DROP TABLE IF EXISTS tmp_productlisttemp;
  CREATE TEMP TABLE tmp_productlisttemp (ROWNUMBER BIGINT GENERATED BY DEFAULT AS IDENTITY




,MPRID BIGINT 
,PRODUCTCODE VARCHAR( 50) 
,SUBPRCODE VARCHAR( 50) 
,PRODUCTTITLE VARCHAR( 300) 
,MAINCATNAME VARCHAR( 250) 
,QTY INT 
,UNIT VARCHAR( 50) 
,PRODUCTIMAGES VARCHAR( 1000) 
,MerchantName VARCHAR( 1000) 
,EMAILID VARCHAR( 100) 
,PHONE VARCHAR( 100) 
,SELLMRP DECIMAL 
,DAP DECIMAL 
,SPRID BIGINT 
,ISACTIVE boolean  ,
PROCUREMENTSLA INT,
REPLACEMENTDAY INT,
SHIPPINGCHARGES DECIMAL(18,2),
CASHONDELIVERY boolean,
WEIGHT_KG DECIMAL(18,2),
LENGTH_CMS DECIMAL(18,2),
BREADTH_CMS DECIMAL(18,2),
HEIGHT_CMS DECIMAL(18,2)
,MVAT DECIMAL 
,DEALSIDS VARCHAR(100)
,STOCKINQTY INT 
,STOCKOUTQTY INT 
,STOCKNETQTY INT 
,ISSTOCK boolean 
,VATTITLE VARCHAR(100) 
,PRODUCTCOUNT INT,
BV DECIMAL(18,2),
JP DECIMAL(18,2),
pmid bigint,
COMPANYNAME VARCHAR(100),
STOCKIN int,
STOCKOUT int,
STOCKNET int,
SUBCATID int,
ADMINCHARGE decimal(18,2),
DELIEVERYCHARGE decimal(18,2),
HANDLINGCHARGE decimal(18,2),
FixedFee decimal(18,2),
cashback_Per decimal(18,2)) ON COMMIT DROP;
  v_query := 'INSERT INTO #PRODUCTLISTTEMP SELECT PM.MPRID,PM.PRODUCTCODE,SM.SUBPRCODE,PM.PRODUCTTITLE, 
MC.MAINCATNAME,SM.QTY,SM.UNIT,SM.PRODUCTIMAGES,ISNULL((PMA.COMPANYNAME),'''') as MerchantName,ISNULL(PL.EMAILID,'''') AS EMAILID,ISNULL(PL.PHONE,'''') AS PHONE,
SM.SELLMRP,SM.DAP,SM.SPRID,SM.ISACTIVE,ISNULL(SM.PROCUREMENTSLA,0),ISNULL(SM.REPLACEMENTDAY,0),
CONVERT(DECIMAL(18,2),SM.SHIPPINGCHARGES),ISNULL(SM.CASHONDELIVERY,0),ISNULL(SM.WEIGHT_KG,0),ISNULL(SM.LENGTH_CMS,0),
ISNULL(SM.BREADTH_CMS,0),ISNULL(SM.HEIGHT_CMS,0),
CONVERT(DECIMAL(18,0),ISNULL(V.VATPERCVALUE,0)) AS MVAT, ISNULL(SM.DEALSIDS,'''')
,ISNULL(SM.STOCKIN,0),ISNULL(SM.STOCKOUT,0),ISNULL(SM.STOCKNET,0),CONVERT(BIT, (CASE WHEN ISNULL(SM.STOCKNET,0) <= 0 THEN 0 ELSE 1 END)) AS ISSTOCK,
V.VATTITLE,0 AS PRODUCTCOUNT,isnull(dcpw.BV,0) as BV ,
isnull(dcpw.PV,0) as JP,pma.PMID,PMA.COMPANYNAME,
ISNULL(SM.STOCKIN,0) AS STOCKIN,ISNULL(SM.STOCKOUT,0) AS STOCKOUT,ISNULL(SM.STOCKNET,0) AS STOCKNET,0,
ISNULL(SM.AdminCharge,0) AS AdminCharge,ISNULL(SM.DelieveryCharge,0) AS DelieveryCharge,ISNULL(SM.HandlingCharge,0) AS HandlingCharge,ISNULL(SM.FixedFee,0) AS FixedFee,ISNULL(SM.cashback_Per,0) AS cashback_Per
FROM IMS_MASTERPRODUCT PM INNER JOIN IMS_SUBPRODUCT SM ON SM.MPRID=PM.MPRID 
INNER JOIN TBL_MAIN_CATEGORY MC ON MC.MAINCATID =PM.MAINCATEGORYID			 
LEFT  JOIN TBL_VAT_CATEGORIES V ON V.VCID = PM.VATCATEGORYID 
LEFT  JOIN PORTAL_LOGIN PL ON PL.PLID= PM.BranchId
left join Portal_Master pma on pma.PMID=pl.PMID
 left join Tbl_DISTRIBUTOR_Comm_ProductWise dcpw on dcpw.sprid=SM.SPRID
WHERE PM.MPRID >0 and SM.ISVERIFIED=1 ';
  SELECT MIN(stocknet) INTO v_minstock FROM ims_subproduct;
  SELECT MAX(stocknet) INTO v_maxstock FROM ims_subproduct;
  IF (v_status > 0) THEN
  v_query := v_query || ' AND SM.ISACTIVE =' || CAST(v_status AS VARCHAR(20));
  END IF;
  IF (v_company <> '') THEN
  v_query := v_query || ' AND pma.PMID LIKE ''%' || v_company || '%'' ';
  END IF;
  IF (v_searchfield = 'EMAILID') THEN
  v_query := v_query || ' AND PL.Emailid LIKE ''%' || v_searchvalue || '%'' ';
  END IF;
  IF (v_searchfield = 'MerchantName') THEN
  v_query := v_query || ' AND pma.COMPANYNAME LIKE ''%' || v_searchvalue || '%'' ';
  END IF;
  IF (v_searchfield = 'PHONE') THEN
  v_query := v_query || ' AND PL.PHONE LIKE ''%' || v_searchvalue || '%'' ';
  END IF;
  IF (v_productname <> '') THEN
  v_productname := REPLACE(v_productname, '''', '''''');
  v_query := v_query || ' and PM.ProductTitle =''' || v_productname || '''';
  END IF;
  IF (v_searchfield = 'PRODUCTTITLE') THEN
  v_query := v_query || ' AND PM.PRODUCTTITLE LIKE ''%' || v_searchvalue || '%'' ';
  END IF;
  IF (v_searchfield = 'MAINCATNAME') THEN
  v_query := v_query || ' AND MC.MAINCATNAME LIKE ''%' || v_searchvalue || '%'' ';
  END IF;
  IF (v_merchantname <> '') THEN
  v_query := v_query || ' AND (PMA.COMPANYNAME) LIKE ''%' || v_merchantname || '%'' ';
  END IF;
  IF (v_searchvaluesubcategory <> '') THEN
  v_searchvaluesubcategory := REPLACE(v_searchvaluesubcategory, '''', '''''');
  v_query := v_query || 'AND MC.MAINCATNAME LIKE''%' || v_searchvaluesubcategory || '%''';
  END IF;
  IF (v_branchid > 0) THEN
  v_query := v_query || ' AND(' || CAST(v_branchid AS VARCHAR(50)) || ' = 1 OR PM.BranchId=' || CAST(v_branchid AS VARCHAR(50)) || ')';
  END IF;
  IF (v_mprid > 0) THEN
  v_query := v_query || ' AND PM.MPRID =' || CAST(v_mprid AS VARCHAR(20));
  END IF;
  IF (v_sprid > 0) THEN
  v_query := v_query || ' AND SM.SPRID =' || CAST(v_sprid AS VARCHAR(20));
  END IF;
  IF (v_cat_code <> '') THEN
  v_catecode := 0;
  SELECT catid INTO v_catecode FROM tbl_category WHERE cat_code = v_cat_code;
  IF (v_catecode > 0) THEN
  v_query := v_query || ' AND PM.CATID =' || CAST(v_catecode AS VARCHAR(20));
  ELSE
  SELECT subcatid INTO v_catecode FROM tbl_sub_category WHERE sub_cat_code = v_cat_code;
  v_query := v_query || ' AND PM.SUBCATEGORYID =' || CAST(v_catecode AS VARCHAR(20));
  END IF;
  END IF;
  IF (v_isstock = 1) THEN
  v_query := v_query || ' ORDER BY  SM.STOCKNET asc ';
  ELSE
  IF (v_isstock = 2) THEN
  v_query := v_query || ' ORDER BY  SM.STOCKNET DESC ';
  ELSE
  v_query := v_query || ' ORDER BY  PM.MPRID DESC ';
  END IF;
  END IF;
  EXECUTE v_query;
  RAISE NOTICE '%', (v_query);
  RETURN QUERY SELECT * FROM tmp_productlisttemp WHERE rownumber BETWEEN v_minindex AND v_maxindex;
  SELECT COUNT(rownumber) INTO v_totalcount FROM tmp_productlisttemp;
  DROP TABLE IF EXISTS tmp_productlisttemp;
  -- SET option (removed)
END;
$$;


--
-- Name: usp_getall_productlist_withbv_dashboard(integer, integer, bigint, bigint, bigint, character varying, character varying, character varying, character varying, integer, integer, integer, character varying, character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_getall_productlist_withbv_dashboard(v_startrowindex integer DEFAULT 1, v_maxrows integer DEFAULT 1000, v_mprid bigint DEFAULT 0, v_sprid bigint DEFAULT 0, v_branchid bigint DEFAULT 0, v_cat_code character varying DEFAULT ''::character varying, v_searchfield character varying DEFAULT ''::character varying, v_searchvalue character varying DEFAULT ''::character varying, v_company character varying DEFAULT ''::character varying, v_status integer DEFAULT 1, v_totalcount integer DEFAULT 0, v_isstock integer DEFAULT 0, v_productname character varying DEFAULT ''::character varying, v_merchantname character varying DEFAULT ''::character varying) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_minindex INT;
  v_maxindex INT;
  v_query text;
  v_catecode INT;
  v_minstock int;
  v_maxstock int;
BEGIN
  v_minindex := (v_startrowindex - 1) * v_maxrows + 1;
  v_maxindex := v_startrowindex * v_maxrows;
  DROP TABLE IF EXISTS tmp_productlisttemp;
  CREATE TEMP TABLE tmp_productlisttemp (ROWNUMBER BIGINT GENERATED BY DEFAULT AS IDENTITY




,MPRID BIGINT 
,PRODUCTCODE VARCHAR( 50) 
,SUBPRCODE VARCHAR( 50) 
,PRODUCTTITLE VARCHAR( 300) 
,MAINCATNAME VARCHAR( 250) 
,QTY INT 
,UNIT VARCHAR( 50) 
,PRODUCTIMAGES VARCHAR( 1000) 
,MerchantName VARCHAR( 1000) 
,EMAILID VARCHAR( 100) 
,PHONE VARCHAR( 100) 
,SELLMRP DECIMAL 
,DAP DECIMAL 
,SPRID BIGINT 
,ISACTIVE boolean  ,
PROCUREMENTSLA INT,
REPLACEMENTDAY INT,
SHIPPINGCHARGES DECIMAL(18,2),
CASHONDELIVERY boolean,
WEIGHT_KG DECIMAL(18,2),
LENGTH_CMS DECIMAL(18,2),
BREADTH_CMS DECIMAL(18,2),
HEIGHT_CMS DECIMAL(18,2)
,MVAT DECIMAL 
,DEALSIDS VARCHAR(100)
,STOCKINQTY INT 
,STOCKOUTQTY INT 
,STOCKNETQTY INT 
,ISSTOCK boolean 
,VATTITLE VARCHAR(100) 
,PRODUCTCOUNT INT,
BV DECIMAL(18,2),
JP DECIMAL(18,2),
pmid bigint,
COMPANYNAME VARCHAR(100),
STOCKIN int,
STOCKOUT int,
STOCKNET int,
SUBCATID int,
ADMINCHARGE decimal(18,2),
DELIEVERYCHARGE decimal(18,2),
HANDLINGCHARGE decimal(18,2),
FixedFee decimal(18,2),
cashback_Per decimal(18,2),
ismerchantstatus int) ON COMMIT DROP;
  IF EXISTS(SELECT 1 FROM ims_masterproduct WHERE producttitle = v_productname) THEN
  v_query := 'INSERT INTO #PRODUCTLISTTEMP SELECT PM.MPRID,PM.PRODUCTCODE,SM.SUBPRCODE,PM.PRODUCTTITLE, 
MC.MAINCATNAME,SM.QTY,SM.UNIT,SM.PRODUCTIMAGES,ISNULL((PL.FNAME+PL.LNAME),'''') as MerchantName,ISNULL(PL.EMAILID,'''') AS EMAILID,ISNULL(PL.PHONE,'''') AS PHONE,
SM.SELLMRP,SM.DAP,SM.SPRID,SM.ISACTIVE,ISNULL(SM.PROCUREMENTSLA,0),ISNULL(SM.REPLACEMENTDAY,0),
CONVERT(DECIMAL(18,2),SM.SHIPPINGCHARGES),ISNULL(SM.CASHONDELIVERY,0),ISNULL(SM.WEIGHT_KG,0),ISNULL(SM.LENGTH_CMS,0),
ISNULL(SM.BREADTH_CMS,0),ISNULL(SM.HEIGHT_CMS,0),
CONVERT(DECIMAL(18,0),ISNULL(V.VATPERCVALUE,0)) AS MVAT, ISNULL(SM.DEALSIDS,'''')
,ISNULL(SM.STOCKIN,0),ISNULL(SM.STOCKOUT,0),ISNULL(SM.STOCKNET,0),CONVERT(BIT, (CASE WHEN ISNULL(SM.STOCKNET,0) <= 0 THEN 0 ELSE 1 END)) AS ISSTOCK,
V.VATTITLE,0 AS PRODUCTCOUNT,isnull(SM.BV,0) as BV ,
isnull(SM.PV,0) as JP,pma.PMID,PMA.COMPANYNAME,
ISNULL(SM.STOCKIN,0) AS STOCKIN,ISNULL(SM.STOCKOUT,0) AS STOCKOUT,ISNULL(SM.STOCKNET,0) AS STOCKNET,0,
ISNULL(SM.AdminCharge,0) AS AdminCharge,ISNULL(SM.DelieveryCharge,0) AS DelieveryCharge,ISNULL(SM.HandlingCharge,0) AS HandlingCharge,
ISNULL(SM.FixedFee,0) AS FixedFee,ISNULL(SM.cashback_Per,0) AS cashback_Per,isnull(SM.ismerchantstatus,0) as ismerchantstatus
FROM IMS_MASTERPRODUCT PM INNER JOIN IMS_SUBPRODUCT SM ON SM.MPRID=PM.MPRID 
INNER JOIN TBL_MAIN_CATEGORY MC ON MC.MAINCATID =PM.MAINCATEGORYID	
LEFT  JOIN TBL_VAT_CATEGORIES V ON V.VCID = PM.VATCATEGORYID 
LEFT  JOIN PORTAL_LOGIN PL ON PL.PLID= PM.BranchId
left join Portal_Master pma on pma.PMID=pl.PMID
WHERE PM.MPRID >0';
  ELSE
  v_query := 'INSERT INTO #PRODUCTLISTTEMP SELECT PM.MPRID,PM.PRODUCTCODE,SM.SUBPRCODE,PM.PRODUCTTITLE, 
MC.MAINCATNAME,SM.QTY,SM.UNIT,SM.PRODUCTIMAGES,ISNULL((PL.FNAME+PL.LNAME),'''') as MerchantName,ISNULL(PL.EMAILID,'''') AS EMAILID,ISNULL(PL.PHONE,'''') AS PHONE,
SM.SELLMRP,SM.DAP,SM.SPRID,SM.ISACTIVE,ISNULL(SM.PROCUREMENTSLA,0),ISNULL(SM.REPLACEMENTDAY,0),
CONVERT(DECIMAL(18,2),SM.SHIPPINGCHARGES),ISNULL(SM.CASHONDELIVERY,0),ISNULL(SM.WEIGHT_KG,0),ISNULL(SM.LENGTH_CMS,0),
ISNULL(SM.BREADTH_CMS,0),ISNULL(SM.HEIGHT_CMS,0),
CONVERT(DECIMAL(18,0),ISNULL(V.VATPERCVALUE,0)) AS MVAT, ISNULL(SM.DEALSIDS,'''')
,ISNULL(SM.STOCKIN,0),ISNULL(SM.STOCKOUT,0),ISNULL(SM.STOCKNET,0),CONVERT(BIT, (CASE WHEN ISNULL(SM.STOCKNET,0) <= 0 THEN 0 ELSE 1 END)) AS ISSTOCK,
V.VATTITLE,0 AS PRODUCTCOUNT,isnull(SM.BV,0) as BV ,
isnull(SM.PV,0) as JP,pma.PMID,PMA.COMPANYNAME,
ISNULL(SM.STOCKIN,0) AS STOCKIN,ISNULL(SM.STOCKOUT,0) AS STOCKOUT,ISNULL(SM.STOCKNET,0) AS STOCKNET,0,
ISNULL(SM.AdminCharge,0) AS AdminCharge,ISNULL(SM.DelieveryCharge,0) AS DelieveryCharge,ISNULL(SM.HandlingCharge,0) AS HandlingCharge,
ISNULL(SM.FixedFee,0) AS FixedFee,ISNULL(SM.cashback_Per,0) AS cashback_Per,isnull(SM.ismerchantstatus,0) as ismerchantstatus
FROM IMS_MASTERPRODUCT_Temp PM INNER JOIN IMS_SUBPRODUCT_temp SM ON SM.MPRID=PM.MPRID 
INNER JOIN TBL_MAIN_CATEGORY MC ON MC.MAINCATID =PM.MAINCATEGORYID	
LEFT  JOIN TBL_VAT_CATEGORIES V ON V.VCID = PM.VATCATEGORYID 
LEFT  JOIN PORTAL_LOGIN PL ON PL.PLID= PM.BranchId
left join Portal_Master pma on pma.PMID=pl.PMID
WHERE PM.MPRID >0';
  END IF;
  SELECT MIN(stocknet) INTO v_minstock FROM ims_subproduct;
  SELECT MAX(stocknet) INTO v_maxstock FROM ims_subproduct;
  IF (v_status > 0) THEN
  v_query := v_query || ' AND SM.ISACTIVE =' || CAST(v_status AS VARCHAR(20));
  END IF;
  IF (v_merchantname <> '') THEN
  v_query := v_query || ' AND (PL.FNAME+PL.LNAME) LIKE ''%' || v_merchantname || '%'' ';
  END IF;
  IF (v_company <> '') THEN
  v_query := v_query || ' AND pma.PMID LIKE ''%' || v_company || '%'' ';
  END IF;
  IF (v_searchfield = 'EMAILID') THEN
  v_query := v_query || ' AND PL.Emailid LIKE ''%' || v_searchvalue || '%'' ';
  END IF;
  IF (v_searchfield = 'MerchantName') THEN
  v_query := v_query || ' AND pma.COMPANYNAME LIKE ''%' || v_searchvalue || '%'' ';
  END IF;
  IF (v_searchfield = 'PHONE') THEN
  v_query := v_query || ' AND PL.PHONE LIKE ''%' || v_searchvalue || '%'' ';
  END IF;
  IF (v_productname <> '') THEN
  v_productname := REPLACE(v_productname, '''', '''''');
  v_query := v_query || ' and PM.ProductTitle =''' || v_productname || '''';
  END IF;
  IF (v_searchfield = 'PRODUCTTITLE') THEN
  v_query := v_query || ' AND PM.PRODUCTTITLE LIKE ''%' || v_searchvalue || '%'' ';
  END IF;
  IF (v_searchfield = 'MAINCATNAME') THEN
  v_query := v_query || ' AND MC.MAINCATNAME LIKE ''%' || v_searchvalue || '%'' ';
  END IF;
  IF (v_branchid > 0) THEN
  v_query := v_query || ' AND(' || CAST(v_branchid AS VARCHAR(50)) || ' = 1 OR PM.BranchId=' || CAST(v_branchid AS VARCHAR(50)) || ')';
  END IF;
  IF (v_mprid > 0) THEN
  v_query := v_query || ' AND PM.MPRID =' || CAST(v_mprid AS VARCHAR(20));
  END IF;
  IF (v_sprid > 0) THEN
  v_query := v_query || ' AND SM.SPRID =' || CAST(v_sprid AS VARCHAR(20));
  END IF;
  IF (v_cat_code <> '') THEN
  v_catecode := 0;
  SELECT catid INTO v_catecode FROM tbl_category WHERE cat_code = v_cat_code;
  IF (v_catecode > 0) THEN
  v_query := v_query || ' AND PM.CATID =' || CAST(v_catecode AS VARCHAR(20));
  ELSE
  SELECT subcatid INTO v_catecode FROM tbl_sub_category WHERE sub_cat_code = v_cat_code;
  v_query := v_query || ' AND PM.SUBCATEGORYID =' || CAST(v_catecode AS VARCHAR(20));
  END IF;
  END IF;
  IF (v_isstock = 1) THEN
  v_query := v_query || ' ORDER BY  SM.STOCKNET asc ';
  ELSE
  IF (v_isstock = 2) THEN
  v_query := v_query || ' ORDER BY  SM.STOCKNET DESC ';
  ELSE
  v_query := v_query || ' ORDER BY  PM.MPRID DESC ';
  END IF;
  END IF;
  EXECUTE v_query;
  RETURN QUERY SELECT * FROM tmp_productlisttemp WHERE rownumber BETWEEN v_minindex AND v_maxindex;
  SELECT COUNT(rownumber) INTO v_totalcount FROM tmp_productlisttemp;
  DROP TABLE IF EXISTS tmp_productlisttemp;
  -- SET option (removed)
END;
$$;


--
-- Name: usp_getall_productreadylist(integer, integer, bigint, bigint, bigint, character varying, character varying, character varying, character varying, integer, integer, character varying, character varying, character varying, character varying, integer, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_getall_productreadylist(v_startrowindex integer DEFAULT 1, v_maxrows integer DEFAULT 1000, v_mprid bigint DEFAULT 0, v_sprid bigint DEFAULT 0, v_branchid bigint DEFAULT 0, v_cat_code character varying DEFAULT ''::character varying, v_searchfield character varying DEFAULT ''::character varying, v_searchvalue character varying DEFAULT ''::character varying, v_status character varying DEFAULT ''::character varying, v_totalcount integer DEFAULT 0, v_isstock integer DEFAULT 0, v_formdate character varying DEFAULT ''::character varying, v_todate character varying DEFAULT ''::character varying, v_stockin character varying DEFAULT ''::character varying, v_productname character varying DEFAULT ''::character varying, v_categoryrelatedto integer DEFAULT 0, v_did integer DEFAULT 0) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_minindex INT;
  v_maxindex INT;
  v_query text;
  v_catecode INT;
BEGIN
  v_minindex := (v_startrowindex - 1) * v_maxrows + 1;
  v_maxindex := v_startrowindex * v_maxrows;
  DROP TABLE IF EXISTS tmp_productlisttemp;
  CREATE TEMP TABLE tmp_productlisttemp (ROWNUMBER BIGINT GENERATED BY DEFAULT AS IDENTITY                




,MPRID BIGINT                 
,PRODUCTCODE VARCHAR( 50)                 
,SUBPRCODE VARCHAR( 50)                 
,PRODUCTTITLE VARCHAR( 300)                 
,MAINCATNAME VARCHAR( 250)                 
,QTY INT                 
,UNIT VARCHAR( 50)                 
,PRODUCTIMAGES VARCHAR( 1000)                 
,MERCHANTNAME VARCHAR( 1000)                 
,EMAILID VARCHAR( 100)                 
,PHONE VARCHAR( 100)                 
,SELLMRP DECIMAL(18,2)                 
,DAP DECIMAL(18,2)                 
,SPRID BIGINT                 
,ISACTIVE boolean  ,                
PROCUREMENTSLA INT,                
REPLACEMENTDAY INT,                
SHIPPINGCHARGES DECIMAL(18,2),                
CASHONDELIVERY boolean,                
WEIGHT_KG DECIMAL(18,2),                
LENGTH_CMS DECIMAL(18,2),                
BREADTH_CMS DECIMAL(18,2),                
HEIGHT_CMS DECIMAL(18,2)                
,MVAT DECIMAL                 
,DEALSIDS VARCHAR(100)                
,STOCKINQTY INT                 
,STOCKOUTQTY INT                 
,STOCKNETQTY INT                 
,ISSTOCK boolean                 
,VATTITLE VARCHAR(100)                 
,PRODUCTCOUNT INT,                
BV DECIMAL(18,2),                
JP DECIMAL(18,2),                
ISVERIFIED INT,                
SUBCATEGORY VARCHAR(500),                
DISCOUNTPERCENTAGE DECIMAL(18,2),                
CREATEDDATE VARCHAR(100),                
MODIFYDATE VARCHAR(100),            
PrSKUCODE Varchar(100),    
IS_OFFER boolean) ON COMMIT DROP;
  v_query := 'INSERT INTO #PRODUCTLISTTEMP SELECT PM.MPRID,PM.PRODUCTCODE,SM.SUBPRCODE,PM.PRODUCTTITLE, MC.MAINCATNAME,SM.QTY,SM.UNIT,SM.PRODUCTIMAGES,                
ISNULL((PL.FNAME+PL.LNAME),'''') AS MERCHANTNAME,ISNULL(PL.EMAILID,'''') AS EMAILID,ISNULL(PL.PHONE,'''') AS PHONE,                
SM.SELLMRP,    
iif(OOP.OPID is null,SM.DAP,OOP.Offer_DAP) as DAP,    
SM.SPRID,SM.ISACTIVE,ISNULL(SM.PROCUREMENTSLA,0),ISNULL(SM.REPLACEMENTDAY,0),                
CONVERT(DECIMAL(18,2),SM.SHIPPINGCHARGES),ISNULL(SM.CASHONDELIVERY,0),ISNULL(SM.WEIGHT_KG,0),ISNULL(SM.LENGTH_CMS,0),ISNULL(SM.BREADTH_CMS,0),ISNULL(SM.HEIGHT_CMS,0),                
CONVERT(DECIMAL(18,0),ISNULL(V.VATPERCVALUE,0)) AS MVAT, ISNULL(SM.DEALSIDS,'''')                
,ISNULL(SM.STOCKIN,0),ISNULL(SM.STOCKOUT,0),ISNULL(SM.STOCKNET,0),CONVERT(BIT, (CASE WHEN ISNULL(SM.STOCKNET,0) <= 0 THEN 0 ELSE 1 END)) AS ISSTOCK,V.VATTITLE,0 AS PRODUCTCOUNT,                
ISNULL(SM.BV,0) AS BV,ISNULL(SM.PV,0) AS JP,SM.ISVERIFIED AS ISVERIFIED,ISNULL(KM.SUBCATNAME,'''') ,            
iif(OOP.OPID is null, ISNULL(DISCOUNTPERCENTAGE,0),[dbo].[FUN_GET_DISCOUNT_PERCENTAGE](SM.SELLMRP,OOP.Offer_DAP))as DISCOUNTPERCENTAGE,ISNULL(CONVERT(DATE,SM.CREATEDDATE,105),''''),            
ISNULL(CONVERT(DATE,SM.MODIFYDATE,105),''''),SM.PrSKUCODE,    
iif(OOP.OPID is null,0,1)as IS_OFFER    
FROM IMS_MASTERPRODUCT PM INNER JOIN IMS_SUBPRODUCT SM ON SM.MPRID=PM.MPRID                 
INNER JOIN TBL_MAIN_CATEGORY MC ON MC.MAINCATID =PM.MAINCATEGORYID                    
LEFT  JOIN TBL_VAT_CATEGORIES V ON V.VCID = PM.VATCATEGORYID                 
LEFT  JOIN PORTAL_LOGIN PL ON PL.PLID= PM.BRANCHID     
JOIN TBL_SUB_CATEGORY KM ON PM.SUBCATEGORYID=KM.SUBCATID             
LEFT JOIN TBL_OFFER_ON_PRODUCT OOP ON OOP.SPRID=SM.SPRID  and getdate() between OOP.Offer_start and OOP.Offer_End     
WHERE  SM.ISVERIFIED IN (0,1,2,3) AND SM.ISMERCHANTSTATUS=5 ';
  IF (v_status <> '') THEN
  v_query := v_query || ' AND SM.ISVERIFIED =' || CAST(v_status AS VARCHAR(20));
  END IF;
  IF (v_searchfield = 'EMAILID') THEN
  v_query := v_query || ' AND PL.EMAILID LIKE ''%' || v_searchvalue || '%'' ';
  END IF;
  IF (v_searchfield = 'MERCHANTNAME') THEN
  v_query := v_query || ' AND (PL.FNAME+PL.LNAME) LIKE ''%' || v_searchvalue || '%'' ';
  END IF;
  IF (v_searchfield = 'PHONE') THEN
  v_query := v_query || ' AND PL.PHONE LIKE ''%' || v_searchvalue || '%'' ';
  END IF;
  IF (v_searchfield = 'PRODUCTTITLE') THEN
  v_query := v_query || ' AND PM.ProductTitle LIKE ''%' || v_searchvalue || '%'' ';
  END IF;
  IF (v_searchfield = 'MAINCATNAME') THEN
  v_query := v_query || ' AND MC.MAINCATNAME LIKE ''%' || v_searchvalue || '%'' ';
  END IF;
  IF (v_productname <> '') THEN
  v_query := v_query || ' AND PM.ProductTitle Like ''%' || v_productname || '%''';
  END IF;
  IF ((v_formdate <> '') AND (v_todate = '')) THEN
  v_query := v_query || (' AND CONVERT(DATE,SM.CREATEDDATE,105) BETWEEN CONVERT(VARCHAR(100),''' || v_formdate || ''',105) AND  CONVERT(DATE, DBO.FUN_GETCURRENTDATE(), 105)');
  END IF;
  IF ((v_todate <> '') AND (v_formdate = '')) THEN
  v_query := v_query || (' AND CONVERT(DATE,SM.CREATEDDATE,105) BETWEEN CONVERT(VARCHAR(100),''' || v_todate || ''',105) AND  CONVERT(DATE, DBO.FUN_GETCURRENTDATE(), 105) ');
  END IF;
  IF (v_formdate <> '' AND v_todate <> '') THEN
  v_query := v_query || (' AND CONVERT(DATE,SM.CREATEDDATE,105) BETWEEN CONVERT(VARCHAR(100),''' || v_formdate || ''',105) AND CONVERT(VARCHAR(100),''' || v_todate || ''',105) ');
  END IF;
  IF (v_branchid > 0) THEN
  v_query := v_query || ' AND PM.BranchId=' || CAST(v_branchid AS VARCHAR(50));
  END IF;
  IF (v_mprid > 0) THEN
  v_query := v_query || ' AND PM.MPRID =' || CAST(v_mprid AS VARCHAR(20));
  END IF;
  IF (v_sprid > 0) THEN
  v_query := v_query || ' AND SM.SPRID =' || CAST(v_sprid AS VARCHAR(20));
  END IF;
  IF (v_cat_code <> '') THEN
  v_catecode := 0;
  SELECT catid INTO v_catecode FROM tbl_category WHERE cat_code = v_cat_code;
  IF (v_catecode > 0) THEN
  v_query := v_query || ' AND PM.CATID =' || CAST(v_catecode AS VARCHAR(20));
  ELSE
  SELECT subcatid INTO v_catecode FROM tbl_sub_category WHERE sub_cat_code = v_cat_code;
  v_query := v_query || ' AND PM.SUBCATEGORYID =' || CAST(v_catecode AS VARCHAR(20));
  END IF;
  END IF;
  IF (v_stockin = '0') THEN
  v_query := v_query || ' AND  SM.STOCKNET<=5';
  END IF;
  IF (v_stockin > '0') THEN
  v_query := v_query || ' AND  SM.STOCKNET>0';
  END IF;
  IF (v_isstock = 1) THEN
  v_query := v_query || ' ORDER BY  SM.STOCKNET ASC ';
  ELSE
  IF (v_isstock = 2) THEN
  v_query := v_query || ' ORDER BY  SM.STOCKNET DESC ';
  ELSE
  v_query := v_query || ' ORDER BY  PM.MPRID DESC ';
  END IF;
  END IF;
  RAISE NOTICE '%', v_query;
  EXECUTE v_query;
  RETURN QUERY SELECT * FROM tmp_productlisttemp WHERE rownumber BETWEEN v_minindex AND v_maxindex;
  SELECT COUNT(rownumber) INTO v_totalcount FROM tmp_productlisttemp;
  DROP TABLE IF EXISTS tmp_productlisttemp;
  -- SET option (removed)
END;
$$;


--
-- Name: usp_getall_productreadylist_f(integer, integer, bigint, bigint, bigint, character varying, character varying, character varying, character varying, integer, integer, character varying, character varying, character varying, character varying, integer, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_getall_productreadylist_f(v_startrowindex integer DEFAULT 1, v_maxrows integer DEFAULT 10000, v_mprid bigint DEFAULT 0, v_sprid bigint DEFAULT 0, v_branchid bigint DEFAULT 0, v_cat_code character varying DEFAULT ''::character varying, v_searchfield character varying DEFAULT ''::character varying, v_searchvalue character varying DEFAULT ''::character varying, v_status character varying DEFAULT ''::character varying, v_totalcount integer DEFAULT 0, v_isstock integer DEFAULT 0, v_formdate character varying DEFAULT ''::character varying, v_todate character varying DEFAULT ''::character varying, v_stockin character varying DEFAULT ''::character varying, v_productname character varying DEFAULT ''::character varying, v_categoryrelatedto integer DEFAULT 1, v_did integer DEFAULT 0) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_minindex INT;
  v_maxindex INT;
  v_query text;
  v_catecode INT;
BEGIN
  v_minindex := (v_startrowindex - 1) * v_maxrows + 1;
  v_maxindex := v_startrowindex * v_maxrows;
  DROP TABLE IF EXISTS tmp_productlisttemp;
  CREATE TEMP TABLE tmp_productlisttemp (ROWNUMBER BIGINT GENERATED BY DEFAULT AS IDENTITY    




,MPRID BIGINT     
,PRODUCTCODE VARCHAR( 50)     
,SUBPRCODE VARCHAR( 50)     
,PRODUCTTITLE VARCHAR( 300)     
,MAINCATNAME VARCHAR( 250)     
,QTY INT     
,UNIT VARCHAR( 50)     
,PRODUCTIMAGES VARCHAR( 1000)
,Name Varchar(500)
,MerchantName VARCHAR( 1000)     
,EMAILID VARCHAR( 100)     
,PHONE VARCHAR( 100)     
,SELLMRP DECIMAL     
,DAP DECIMAL(10,2)     
,SPRID BIGINT     
,ISACTIVE boolean  ,    
PROCUREMENTSLA INT,    
REPLACEMENTDAY INT,    
SHIPPINGCHARGES DECIMAL(18,2),    
CASHONDELIVERY boolean,    
WEIGHT_KG DECIMAL(18,2),    
LENGTH_CMS DECIMAL(18,2),    
BREADTH_CMS DECIMAL(18,2),    
HEIGHT_CMS DECIMAL(18,2)    
,MVAT DECIMAL     
,DEALSIDS VARCHAR(100)    
,STOCKINQTY INT     
,STOCKOUTQTY INT     
,STOCKNETQTY INT     
,ISSTOCK boolean     
,VATTITLE VARCHAR(100)     
,PRODUCTCOUNT INT,    
BV DECIMAL(18,2),    
JP DECIMAL(18,2),    
IsVerified int,    
Subcategory varchar(500),    
Discountpercentage decimal(10,2),    
CreatedDate varchar(100),    
ModifyDate varchar(100)) ON COMMIT DROP;
  v_query := 'INSERT INTO #PRODUCTLISTTEMP SELECT PM.MPRID,PM.PRODUCTCODE,SM.SUBPRCODE,PM.PRODUCTTITLE, MC.MAINCATNAME,SM.QTY,SM.UNIT,SM.PRODUCTIMAGES,ISNULL((PL.FNAME+PL.LNAME),''''),     
ISNULL((PMA.COMPANYNAME),'''') AS MERCHANTNAME,ISNULL(PL.EMAILID,'''') AS EMAILID,ISNULL(PL.PHONE,'''') AS PHONE,    
SM.SELLMRP,SM.DAP,SM.SPRID,SM.ISACTIVE,ISNULL(SM.PROCUREMENTSLA,0),ISNULL(SM.REPLACEMENTDAY,0),    
CONVERT(DECIMAL(18,2),SM.SHIPPINGCHARGES),ISNULL(SM.CASHONDELIVERY,0),ISNULL(SM.WEIGHT_KG,0),ISNULL(SM.LENGTH_CMS,0),ISNULL(SM.BREADTH_CMS,0),ISNULL(SM.HEIGHT_CMS,0),    
CONVERT(DECIMAL(18,0),ISNULL(V.VATPERCVALUE,0)) AS MVAT, ISNULL(SM.DEALSIDS,'''')    
,ISNULL(SM.STOCKIN,0),ISNULL(SM.STOCKOUT,0),ISNULL(SM.STOCKNET,0),CONVERT(BIT, (CASE WHEN ISNULL(SM.STOCKNET,0) <= 0 THEN 0 ELSE 1 END)) AS ISSTOCK,V.VATTITLE,0 AS PRODUCTCOUNT,    
ISNULL(SM.BV,0) AS BV,ISNULL(SM.PV,0) AS JP,SM.ISVERIFIED AS ISVERIFIED,ISNULL(KM.SUBCATNAME,'''') ,ISNULL(DISCOUNTPERCENTAGE,0),    
ISNULL(CONVERT(DATE,SM.CREATEDDATE,105),''''),ISNULL(CONVERT(DATE,SM.MODIFYDATE,105),'''')    
FROM IMS_MASTERPRODUCT PM INNER JOIN IMS_SUBPRODUCT SM ON SM.MPRID=PM.MPRID     
INNER JOIN TBL_MAIN_CATEGORY MC ON MC.MAINCATID =PM.MAINCATEGORYID        
LEFT JOIN TBL_VAT_CATEGORIES V ON V.VCID = PM.VATCATEGORYID     
LEFT JOIN PORTAL_LOGIN PL ON PL.PLID= PM.BRANCHID JOIN TBL_SUB_CATEGORY KM ON PM.SUBCATEGORYID=KM.SUBCATID    
LEFT JOIN PORTAL_MASTER PMA ON PMA.PMID=PL.PMID    
WHERE  SM.ISVERIFIED IN (0,1,2,3) AND SM.ISMERCHANTSTATUS=5 ';
  IF (v_status <> '') THEN
  v_query := v_query || ' AND SM.ISVERIFIED =' || CAST(v_status AS VARCHAR(20));
  END IF;
  IF (v_searchfield = 'EMAILID') THEN
  v_query := v_query || ' AND PL.EMAILID LIKE ''%' || v_searchvalue || '%'' ';
  END IF;
  IF (v_searchfield = 'MERCHANTNAME') THEN
  v_query := v_query || ' AND ISNULL((PMA.COMPANYNAME),'''') LIKE ''%' || v_searchvalue || '%'' ';
  END IF;
  IF (v_searchfield = 'PHONE') THEN
  v_query := v_query || ' AND PL.PHONE LIKE ''%' || v_searchvalue || '%'' ';
  END IF;
  IF (v_searchfield = 'PRODUCTTITLE') THEN
  v_query := v_query || ' AND PM.PRODUCTTITLE LIKE ''%' || v_searchvalue || '%'' ';
  END IF;
  IF (v_searchfield = 'MAINCATNAME') THEN
  v_query := v_query || ' AND MC.MAINCATNAME LIKE ''%' || v_searchvalue || '%'' ';
  END IF;
  IF (v_productname <> '') THEN
  v_productname := REPLACE(v_productname, '''', '''''');
  v_query := v_query || ' AND PM.PRODUCTTITLE =''' || v_productname || '''';
  END IF;
  IF ((v_formdate <> '') AND (v_todate = '')) THEN
  v_query := v_query || (' AND CONVERT(DATE,SM.CREATEDDATE,105) BETWEEN CONVERT(VARCHAR(100),''' || v_formdate || ''',105) AND  CONVERT(DATE, DBO.FUN_GETCURRENTDATE(), 105)');
  END IF;
  IF ((v_todate <> '') AND (v_formdate = '')) THEN
  v_query := v_query || (' AND CONVERT(DATE,SM.CREATEDDATE,105) BETWEEN CONVERT(VARCHAR(100),''' || v_todate || ''',105) AND  CONVERT(DATE, DBO.FUN_GETCURRENTDATE(), 105) ');
  END IF;
  IF (v_formdate <> '' AND v_todate <> '') THEN
  v_query := v_query || (' AND CONVERT(DATE,SM.CREATEDDATE,105) BETWEEN CONVERT(VARCHAR(100),''' || v_formdate || ''',105) AND CONVERT(VARCHAR(100),''' || v_todate || ''',105) ');
  END IF;
  IF (v_branchid > 0) THEN
  v_query := v_query || ' AND PM.BRANCHID=' || CAST(v_branchid AS VARCHAR(50));
  END IF;
  IF (v_did > 0) THEN
  v_query := v_query || (' AND PL.PLID In(SELECT PLID FROM PORTAL_MASTER WHERE CID IN(SELECT CID FROM DISTRIBUTOR_MASTER WHERE PLID=' || CAST(v_did AS VARCHAR(5)) || '))');
  END IF;
  IF (v_mprid > 0) THEN
  v_query := v_query || ' AND PM.MPRID =' || CAST(v_mprid AS VARCHAR(20));
  END IF;
  IF (v_sprid > 0) THEN
  v_query := v_query || ' AND SM.SPRID =' || CAST(v_sprid AS VARCHAR(20));
  END IF;
  IF (v_cat_code <> '') THEN
  v_catecode := 0;
  SELECT catid INTO v_catecode FROM tbl_category WHERE cat_code = v_cat_code;
  IF (v_catecode > 0) THEN
  v_query := v_query || ' AND PM.CATID =' || CAST(v_catecode AS VARCHAR(20));
  ELSE
  SELECT subcatid INTO v_catecode FROM tbl_sub_category WHERE sub_cat_code = v_cat_code;
  v_query := v_query || ' AND PM.SUBCATEGORYID =' || CAST(v_catecode AS VARCHAR(20));
  END IF;
  END IF;
  IF (v_stockin = '0') THEN
  v_query := v_query || ' AND  SM.STOCKNET<=5';
  END IF;
  IF (v_stockin > '0') THEN
  v_query := v_query || ' AND  SM.STOCKNET>0';
  END IF;
  IF (v_isstock = 1) THEN
  v_query := v_query || ' ORDER BY  SM.STOCKNET ASC ';
  ELSE
  IF (v_isstock = 2) THEN
  v_query := v_query || ' ORDER BY  SM.STOCKNET DESC ';
  ELSE
  v_query := v_query || ' ORDER BY  PM.MPRID DESC ';
  END IF;
  END IF;
  EXECUTE v_query;
  RETURN QUERY SELECT * FROM tmp_productlisttemp WHERE rownumber BETWEEN v_minindex AND v_maxindex;
  SELECT COUNT(rownumber) INTO v_totalcount FROM tmp_productlisttemp;
  DROP TABLE IF EXISTS tmp_productlisttemp;
  -- SET option (removed)
END;
$$;


--
-- Name: usp_getall_productreadylist_for_affiliate(integer, integer, bigint, bigint, bigint, character varying, character varying, character varying, character varying, integer, integer, character varying, character varying, character varying, character varying, integer, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_getall_productreadylist_for_affiliate(v_startrowindex integer DEFAULT 1, v_maxrows integer DEFAULT 1000, v_mprid bigint DEFAULT 0, v_sprid bigint DEFAULT 0, v_branchid bigint DEFAULT 0, v_cat_code character varying DEFAULT ''::character varying, v_searchfield character varying DEFAULT ''::character varying, v_searchvalue character varying DEFAULT ''::character varying, v_status character varying DEFAULT ''::character varying, v_totalcount integer DEFAULT 0, v_isstock integer DEFAULT 0, v_formdate character varying DEFAULT ''::character varying, v_todate character varying DEFAULT ''::character varying, v_stockin character varying DEFAULT ''::character varying, v_productname character varying DEFAULT ''::character varying, v_categoryrelatedto integer DEFAULT 0, v_did integer DEFAULT 0) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_minindex INT;
  v_maxindex INT;
  v_query text;
  v_catecode INT;
BEGIN
  v_minindex := (v_startrowindex - 1) * v_maxrows + 1;
  v_maxindex := v_startrowindex * v_maxrows;
  DROP TABLE IF EXISTS tmp_productlisttemp;
  CREATE TEMP TABLE tmp_productlisttemp (ROWNUMBER BIGINT GENERATED BY DEFAULT AS IDENTITY                  




,MPRID BIGINT                   
,PRODUCTCODE VARCHAR( 50)                   
,SUBPRCODE VARCHAR( 50)                   
,PRODUCTTITLE VARCHAR( 300)                   
,MAINCATNAME VARCHAR( 250)                   
,QTY INT                   
,UNIT VARCHAR( 50)                   
,PRODUCTIMAGES VARCHAR( 1000)                   
,MERCHANTNAME VARCHAR( 1000)                   
,EMAILID VARCHAR( 100)                   
,PHONE VARCHAR( 100)                   
,SELLMRP DECIMAL(18,2)                   
,DAP DECIMAL(18,2)                   
,SPRID BIGINT                   
,ISACTIVE boolean  ,                  
PROCUREMENTSLA INT,                  
REPLACEMENTDAY INT,                  
SHIPPINGCHARGES DECIMAL(18,2),                  
CASHONDELIVERY boolean,                  
WEIGHT_KG DECIMAL(18,2),                  
LENGTH_CMS DECIMAL(18,2),                  
BREADTH_CMS DECIMAL(18,2),                  
HEIGHT_CMS DECIMAL(18,2)                  
,MVAT DECIMAL                   
,DEALSIDS VARCHAR(100)                  
,STOCKINQTY INT                   
,STOCKOUTQTY INT                   
,STOCKNETQTY INT                   
,ISSTOCK boolean                   
,VATTITLE VARCHAR(100)                   
,PRODUCTCOUNT INT,                  
BV DECIMAL(18,2),                  
JP DECIMAL(18,2),                  
ISVERIFIED INT,                  
SUBCATEGORY VARCHAR(500),                  
DISCOUNTPERCENTAGE DECIMAL(18,2),                  
CREATEDDATE VARCHAR(100),                  
MODIFYDATE VARCHAR(100),              
PrSKUCODE Varchar(100),   
IS_AFFILIATE_ENABLE boolean,
IS_OFFER boolean,  
IS_AFFILIATE boolean,  
BONUS_TYPE varchar(10),  
BONUS_VALUE decimal(18,2),  
REDEEM_AFTER_DAYS int ,
STATUS varchar(10),
REMARK varchar(500),
ABPID int) ON COMMIT DROP;
  v_query := 'INSERT INTO #PRODUCTLISTTEMP SELECT PM.MPRID,PM.PRODUCTCODE,SM.SUBPRCODE,PM.PRODUCTTITLE, MC.MAINCATNAME,SM.QTY,SM.UNIT,SM.PRODUCTIMAGES,                  
ISNULL((PL.FNAME+PL.LNAME),'''') AS MERCHANTNAME,ISNULL(PL.EMAILID,'''') AS EMAILID,ISNULL(PL.PHONE,'''') AS PHONE,                  
SM.SELLMRP,      
iif(OOP.OPID is null,SM.DAP,OOP.Offer_DAP) as DAP,      
SM.SPRID,SM.ISACTIVE,ISNULL(SM.PROCUREMENTSLA,0),ISNULL(SM.REPLACEMENTDAY,0),                  
CONVERT(DECIMAL(18,2),SM.SHIPPINGCHARGES),ISNULL(SM.CASHONDELIVERY,0),ISNULL(SM.WEIGHT_KG,0),ISNULL(SM.LENGTH_CMS,0),ISNULL(SM.BREADTH_CMS,0),ISNULL(SM.HEIGHT_CMS,0),                  
CONVERT(DECIMAL(18,0),ISNULL(V.VATPERCVALUE,0)) AS MVAT, ISNULL(SM.DEALSIDS,'''')                  
,ISNULL(SM.STOCKIN,0),ISNULL(SM.STOCKOUT,0),ISNULL(SM.STOCKNET,0),CONVERT(BIT, (CASE WHEN ISNULL(SM.STOCKNET,0) <= 0 THEN 0 ELSE 1 END)) AS ISSTOCK,V.VATTITLE,0 AS PRODUCTCOUNT,                  
ISNULL(SM.BV,0) AS BV,ISNULL(SM.PV,0) AS JP,SM.ISVERIFIED AS ISVERIFIED,ISNULL(KM.SUBCATNAME,'''') ,              
iif(OOP.OPID is null, ISNULL(DISCOUNTPERCENTAGE,0),[dbo].[FUN_GET_DISCOUNT_PERCENTAGE](SM.SELLMRP,OOP.Offer_DAP))as DISCOUNTPERCENTAGE,ISNULL(CONVERT(DATE,SM.CREATEDDATE,105),''''),              
ISNULL(CONVERT(DATE,SM.MODIFYDATE,105),''''),SM.PrSKUCODE, 
isnull(ABP.Is_active,0) as IS_Affiliate_Enable,
iif(OOP.OPID is null,0,1)as IS_OFFER ,  
iif(ABP.SPRID is null,0,1) as IS_AFFILIATE,  
ISNULL(ABP.BONUS_TYPE,'''')AS BONUS_TYPE,ISNULL(ABP.BONUS_VALUE,0),ISNULL(ABP.REDEEM_AFTER_DAYS,0),Cast(ABP.STATUS as varchar),ABP.REMARK,
ABP.ABPID
FROM IMS_MASTERPRODUCT PM INNER JOIN IMS_SUBPRODUCT SM ON SM.MPRID=PM.MPRID                   
INNER JOIN TBL_MAIN_CATEGORY MC ON MC.MAINCATID =PM.MAINCATEGORYID                      
LEFT  JOIN TBL_VAT_CATEGORIES V ON V.VCID = PM.VATCATEGORYID                   
LEFT  JOIN PORTAL_LOGIN PL ON PL.PLID= PM.BRANCHID       
JOIN TBL_SUB_CATEGORY KM ON PM.SUBCATEGORYID=KM.SUBCATID               
LEFT JOIN TBL_OFFER_ON_PRODUCT OOP ON OOP.SPRID=SM.SPRID  and getdate() between OOP.Offer_start and OOP.Offer_End   
LEFT JOIN AFFILIATE_BONUS_ON_PRODUCT ABP ON ABP.SPRID=SM.SPRID  
WHERE  SM.ISVERIFIED IN (0,1,2,3) AND SM.ISMERCHANTSTATUS=5 ';
  IF (v_status <> '') THEN
  v_query := v_query || ' AND SM.ISVERIFIED =' || CAST(v_status AS VARCHAR(20));
  END IF;
  IF (v_searchfield = 'EMAILID') THEN
  v_query := v_query || ' AND PL.EMAILID LIKE ''%' || v_searchvalue || '%'' ';
  END IF;
  IF (v_searchfield = 'MERCHANTNAME') THEN
  v_query := v_query || ' AND (PL.FNAME+PL.LNAME) LIKE ''%' || v_searchvalue || '%'' ';
  END IF;
  IF (v_searchfield = 'PHONE') THEN
  v_query := v_query || ' AND PL.PHONE LIKE ''%' || v_searchvalue || '%'' ';
  END IF;
  IF (v_searchfield = 'PRODUCTTITLE') THEN
  v_query := v_query || ' AND PM.ProductTitle LIKE ''%' || v_searchvalue || '%'' ';
  END IF;
  IF (v_searchfield = 'MAINCATNAME') THEN
  v_query := v_query || ' AND MC.MAINCATNAME LIKE ''%' || v_searchvalue || '%'' ';
  END IF;
  IF (v_productname <> '') THEN
  v_query := v_query || ' AND PM.ProductTitle Like ''%' || v_productname || '%''';
  END IF;
  IF ((v_formdate <> '') AND (v_todate = '')) THEN
  v_query := v_query || (' AND CONVERT(DATE,SM.CREATEDDATE,105) BETWEEN CONVERT(VARCHAR(100),''' || v_formdate || ''',105) AND  CONVERT(DATE, DBO.FUN_GETCURRENTDATE(), 105)');
  END IF;
  IF ((v_todate <> '') AND (v_formdate = '')) THEN
  v_query := v_query || (' AND CONVERT(DATE,SM.CREATEDDATE,105) BETWEEN CONVERT(VARCHAR(100),''' || v_todate || ''',105) AND  CONVERT(DATE, DBO.FUN_GETCURRENTDATE(), 105) ');
  END IF;
  IF (v_formdate <> '' AND v_todate <> '') THEN
  v_query := v_query || (' AND CONVERT(DATE,SM.CREATEDDATE,105) BETWEEN CONVERT(VARCHAR(100),''' || v_formdate || ''',105) AND CONVERT(VARCHAR(100),''' || v_todate || ''',105) ');
  END IF;
  IF (v_branchid > 0) THEN
  v_query := v_query || ' AND PM.BranchId=' || CAST(v_branchid AS VARCHAR(50));
  END IF;
  IF (v_mprid > 0) THEN
  v_query := v_query || ' AND PM.MPRID =' || CAST(v_mprid AS VARCHAR(20));
  END IF;
  IF (v_sprid > 0) THEN
  v_query := v_query || ' AND SM.SPRID =' || CAST(v_sprid AS VARCHAR(20));
  END IF;
  IF (v_cat_code <> '') THEN
  v_catecode := 0;
  SELECT catid INTO v_catecode FROM tbl_category WHERE cat_code = v_cat_code;
  IF (v_catecode > 0) THEN
  v_query := v_query || ' AND PM.CATID =' || CAST(v_catecode AS VARCHAR(20));
  ELSE
  SELECT subcatid INTO v_catecode FROM tbl_sub_category WHERE sub_cat_code = v_cat_code;
  v_query := v_query || ' AND PM.SUBCATEGORYID =' || CAST(v_catecode AS VARCHAR(20));
  END IF;
  END IF;
  IF (v_stockin = '0') THEN
  v_query := v_query || ' AND  SM.STOCKNET<=5';
  END IF;
  IF (v_stockin > '0') THEN
  v_query := v_query || ' AND  SM.STOCKNET>0';
  END IF;
  IF (v_isstock = 1) THEN
  v_query := v_query || ' ORDER BY  SM.STOCKNET ASC ';
  ELSE
  IF (v_isstock = 2) THEN
  v_query := v_query || ' ORDER BY  SM.STOCKNET DESC ';
  ELSE
  v_query := v_query || ' ORDER BY  PM.MPRID DESC ';
  END IF;
  END IF;
  RAISE NOTICE '%', v_query;
  EXECUTE v_query;
  RETURN QUERY SELECT * FROM tmp_productlisttemp WHERE rownumber BETWEEN v_minindex AND v_maxindex;
  SELECT COUNT(rownumber) INTO v_totalcount FROM tmp_productlisttemp;
  DROP TABLE IF EXISTS tmp_productlisttemp;
  -- SET option (removed)
END;
$$;


--
-- Name: usp_getall_productreadylist_reseller(integer, integer, bigint, bigint, bigint, character varying, character varying, character varying, character varying, integer, integer, character varying, character varying, character varying, character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_getall_productreadylist_reseller(v_startrowindex integer DEFAULT 1, v_maxrows integer DEFAULT 1000, v_mprid bigint DEFAULT 0, v_sprid bigint DEFAULT 0, v_branchid bigint DEFAULT 8, v_cat_code character varying DEFAULT ''::character varying, v_searchfield character varying DEFAULT ''::character varying, v_searchvalue character varying DEFAULT ''::character varying, v_status character varying DEFAULT ''::character varying, v_totalcount integer DEFAULT 0, v_isstock integer DEFAULT 0, v_formdate character varying DEFAULT ''::character varying, v_todate character varying DEFAULT ''::character varying, v_stockin character varying DEFAULT ''::character varying, v_productname character varying DEFAULT ''::character varying) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_minindex INT;
  v_maxindex INT;
  v_query text;
  v_catecode INT;
BEGIN
  v_minindex := (v_startrowindex - 1) * v_maxrows + 1;
  v_maxindex := v_startrowindex * v_maxrows;
  DROP TABLE IF EXISTS tmp_productlisttemp;
  CREATE TEMP TABLE tmp_productlisttemp (ROWNUMBER BIGINT GENERATED BY DEFAULT AS IDENTITY




,MPRID BIGINT 
,PRODUCTCODE VARCHAR( 50) 
,SUBPRCODE VARCHAR( 50) 
,PRODUCTTITLE VARCHAR( 300) 
,MAINCATNAME VARCHAR( 250) 
,QTY INT 
,UNIT VARCHAR( 50) 
,PRODUCTIMAGES VARCHAR( 1000) 
,MerchantName VARCHAR( 1000) 
,EMAILID VARCHAR( 100) 
,PHONE VARCHAR( 100) 
,SELLMRP DECIMAL 
,DAP DECIMAL 
,SPRID BIGINT 
,ISACTIVE boolean  ,
PROCUREMENTSLA INT,
REPLACEMENTDAY INT,
SHIPPINGCHARGES DECIMAL(18,2),
CASHONDELIVERY boolean,
WEIGHT_KG DECIMAL(18,2),
LENGTH_CMS DECIMAL(18,2),
BREADTH_CMS DECIMAL(18,2),
HEIGHT_CMS DECIMAL(18,2)
,MVAT DECIMAL 
,DEALSIDS VARCHAR(100)
,STOCKINQTY INT 
,STOCKOUTQTY INT 
,STOCKNETQTY INT 
,ISSTOCK boolean 
,VATTITLE VARCHAR(100) 
,PRODUCTCOUNT INT,
BV DECIMAL(18,2),
JP DECIMAL(18,2),
IsVerified int,
Subcategory varchar(500),
Discountpercentage decimal,
CreatedDate varchar(100),
ModifyDate varchar(100)) ON COMMIT DROP;
  v_query := 'INSERT INTO #PRODUCTLISTTEMP SELECT PM.MPRID,PM.PRODUCTCODE,SM.SUBPRCODE,PM.PRODUCTTITLE, MC.MAINCATNAME,SM.QTY,SM.UNIT,SM.PRODUCTIMAGES,
ISNULL((PL.FNAME+PL.LNAME),'''') as MerchantName,ISNULL(PL.EMAILID,'''') AS EMAILID,ISNULL(PL.PHONE,'''') AS PHONE,
SM.SELLMRP,SM.DAP,SM.SPRID,SM.ISACTIVE,ISNULL(SM.PROCUREMENTSLA,0),ISNULL(SM.REPLACEMENTDAY,0),
CONVERT(DECIMAL(18,2),SM.SHIPPINGCHARGES),ISNULL(SM.CASHONDELIVERY,0),ISNULL(SM.WEIGHT_KG,0),ISNULL(SM.LENGTH_CMS,0),ISNULL(SM.BREADTH_CMS,0),ISNULL(SM.HEIGHT_CMS,0),
CONVERT(DECIMAL(18,0),ISNULL(V.VATPERCVALUE,0)) AS MVAT, ISNULL(SM.DEALSIDS,'''')
,ISNULL(SM.STOCKIN,0),ISNULL(SM.STOCKOUT,0),ISNULL(SM.STOCKNET,0),CONVERT(BIT, (CASE WHEN ISNULL(SM.STOCKNET,0) <= 0 THEN 0 ELSE 1 END)) AS ISSTOCK,V.VATTITLE,0 AS PRODUCTCOUNT,
ISNULL(SM.BV,0) AS BV,ISNULL(SM.PV,0) AS JP,SM.IsVerified AS IsVerified,isnull(km.subcatname,'''') ,isnull(DiscountPercentage,0),isnull(convert(date,SM.CreatedDate,105),''''),isnull(convert(date,SM.ModifyDate,105),'''')
FROM IMS_MASTERPRODUCT PM INNER JOIN IMS_SUBPRODUCT SM ON SM.MPRID=PM.MPRID 
INNER JOIN TBL_MAIN_CATEGORY MC ON MC.MAINCATID =PM.MAINCATEGORYID			 
LEFT  JOIN TBL_VAT_CATEGORIES V ON V.VCID = PM.VATCATEGORYID 
LEFT  JOIN PORTAL_LOGIN PL ON PL.PLID= PM.BranchId join tbl_sub_category km on PM.SubCategoryId=km.subcatid
WHERE  SM.IsVerified in (0,1,2,3) and SM.ismerchantstatus=5 ';
  IF (v_status <> '') THEN
  v_query := v_query || ' AND SM.IsVerified =' || CAST(v_status AS VARCHAR(20));
  END IF;
  IF (v_searchfield = 'EMAILID') THEN
  v_query := v_query || ' AND PL.Emailid LIKE ''%' || v_searchvalue || '%'' ';
  END IF;
  IF (v_searchfield = 'MerchantName') THEN
  v_query := v_query || ' AND (PL.FNAME+PL.LNAME) LIKE ''%' || v_searchvalue || '%'' ';
  END IF;
  IF (v_searchfield = 'PHONE') THEN
  v_query := v_query || ' AND PL.PHONE LIKE ''%' || v_searchvalue || '%'' ';
  END IF;
  IF (v_searchfield = 'PRODUCTTITLE') THEN
  v_query := v_query || ' AND PM.PRODUCTTITLE LIKE ''%' || v_searchvalue || '%'' ';
  END IF;
  IF (v_searchfield = 'MAINCATNAME') THEN
  v_query := v_query || ' AND MC.MAINCATNAME LIKE ''%' || v_searchvalue || '%'' ';
  END IF;
  IF (v_productname <> '') THEN
  v_productname := REPLACE(v_productname, '''', '''''');
  v_query := v_query || ' and PM.ProductTitle =''' || v_productname || '''';
  END IF;
  IF ((v_formdate <> '') AND (v_todate = '')) THEN
  v_query := v_query || (' AND CONVERT(date,SM.CreatedDate,105) between CONVERT(VARCHAR(100),''' || v_formdate || ''',105) and  CONVERT(Date, dbo.fun_getCurrentDate(), 105)');
  END IF;
  IF ((v_todate <> '') AND (v_formdate = '')) THEN
  v_query := v_query || (' AND CONVERT(date,SM.CreatedDate,105) between CONVERT(VARCHAR(100),''' || v_todate || ''',105) and  CONVERT(Date, dbo.fun_getCurrentDate(), 105) ');
  END IF;
  IF (v_formdate <> '' AND v_todate <> '') THEN
  v_query := v_query || (' AND CONVERT(date,SM.CreatedDate,105) BETWEEN CONVERT(VARCHAR(100),''' || v_formdate || ''',105) AND CONVERT(VARCHAR(100),''' || v_todate || ''',105) ');
  END IF;
  IF (v_branchid > 0) THEN
  v_query := v_query || ' AND   PM.BranchId in (select PLID from portal_login where did= ''' || CAST(v_branchid AS VARCHAR(50)) || ''')   ';
  END IF;
  IF (v_mprid > 0) THEN
  v_query := v_query || ' AND PM.MPRID =' || CAST(v_mprid AS VARCHAR(20));
  END IF;
  IF (v_sprid > 0) THEN
  v_query := v_query || ' AND SM.SPRID =' || CAST(v_sprid AS VARCHAR(20));
  END IF;
  IF (v_cat_code <> '') THEN
  v_catecode := 0;
  SELECT catid INTO v_catecode FROM tbl_category WHERE cat_code = v_cat_code;
  IF (v_catecode > 0) THEN
  v_query := v_query || ' AND PM.CATID =' || CAST(v_catecode AS VARCHAR(20));
  ELSE
  SELECT subcatid INTO v_catecode FROM tbl_sub_category WHERE sub_cat_code = v_cat_code;
  v_query := v_query || ' AND PM.SUBCATEGORYID =' || CAST(v_catecode AS VARCHAR(20));
  END IF;
  END IF;
  IF (v_stockin = '0') THEN
  v_query := v_query || ' AND  SM.STOCKNET<=5';
  END IF;
  IF (v_stockin > '0') THEN
  v_query := v_query || ' AND  SM.STOCKNET>0';
  END IF;
  IF (v_isstock = 1) THEN
  v_query := v_query || ' ORDER BY  SM.STOCKNET asc ';
  ELSE
  IF (v_isstock = 2) THEN
  v_query := v_query || ' ORDER BY  SM.STOCKNET DESC ';
  ELSE
  v_query := v_query || ' ORDER BY  PM.MPRID DESC ';
  END IF;
  END IF;
  EXECUTE v_query;
  RETURN QUERY SELECT * FROM tmp_productlisttemp WHERE rownumber BETWEEN v_minindex AND v_maxindex;
  SELECT COUNT(rownumber) INTO v_totalcount FROM tmp_productlisttemp;
  DROP TABLE IF EXISTS tmp_productlisttemp;
  -- SET option (removed)
END;
$$;


--
-- Name: usp_getall_status_productlist(integer, integer, bigint, bigint, bigint, character varying, character varying, character varying, character varying, character varying, integer, integer, integer, integer, character varying, character varying, character varying, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_getall_status_productlist(v_startrowindex integer DEFAULT 1, v_maxrows integer DEFAULT 1000, v_mprid bigint DEFAULT 0, v_sprid bigint DEFAULT 0, v_branchid bigint DEFAULT 0, v_cat_code character varying DEFAULT ''::character varying, v_searchfield character varying DEFAULT ''::character varying, v_searchvalue character varying DEFAULT ''::character varying, v_fromdate character varying DEFAULT ''::character varying, v_todate character varying DEFAULT ''::character varying, v_status integer DEFAULT 5, v_totalcount integer DEFAULT 0, v_subcatid integer DEFAULT 0, v_isverified integer DEFAULT 0, v_searchvaluesubcategory character varying DEFAULT ''::character varying, v_merchantname character varying DEFAULT ''::character varying, v_productname character varying DEFAULT ''::character varying, v_did integer DEFAULT 0) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_minindex INT;
  v_maxindex INT;
  v_query text;
  v_catecode INT;
BEGIN
  v_minindex := (v_startrowindex - 1) * v_maxrows + 1;
  v_maxindex := v_startrowindex * v_maxrows;
  DROP TABLE IF EXISTS tmp_productlisttemp;
  CREATE TEMP TABLE tmp_productlisttemp (ROWNUMBER BIGINT GENERATED BY DEFAULT AS IDENTITY




,MPRID BIGINT 
,PRODUCTCODE VARCHAR( 50) 
,SUBPRCODE VARCHAR( 50) 
,PRODUCTTITLE VARCHAR( 300) 
,MAINCATNAME VARCHAR( 250) 
,QTY INT 
,UNIT VARCHAR( 50) 
,PRODUCTIMAGES VARCHAR( 1000) 
,MerchantName VARCHAR( 1000) 
,EMAILID VARCHAR( 100) 
,PHONE VARCHAR( 100) 
,SELLMRP DECIMAL 
,DAP DECIMAL 
,SPRID BIGINT 
,ISACTIVE boolean  ,
PROCUREMENTSLA INT,
REPLACEMENTDAY INT,
SHIPPINGCHARGES DECIMAL(18,2),
CASHONDELIVERY boolean,
WEIGHT_KG DECIMAL(18,2),
LENGTH_CMS DECIMAL(18,2),
BREADTH_CMS DECIMAL(18,2),
HEIGHT_CMS DECIMAL(18,2)
,MVAT DECIMAL 
,DEALSIDS VARCHAR(100)
,STOCKINQTY INT 
,STOCKOUTQTY INT 
,STOCKNETQTY INT 
,ISSTOCK boolean 
,VATTITLE VARCHAR(100) 
,PRODUCTCOUNT INT,
BV DECIMAL(18,2),
JP DECIMAL(18,2),
IsVerified int,
Subcategory varchar(500),
Discountpercentage decimal,
CreatedDate timestamp,
ModifyDate timestamp,
ismerchantstatus int,
DID int) ON COMMIT DROP;
  v_query := 'INSERT INTO #PRODUCTLISTTEMP SELECT PM.MPRID,PM.PRODUCTCODE,SM.SUBPRCODE,PM.PRODUCTTITLE, MC.MAINCATNAME,SM.QTY,SM.UNIT,SM.PRODUCTIMAGES,
ISNULL((PMA.COMPANYNAME),'''') as MerchantName,ISNULL(PL.EMAILID,'''') AS EMAILID,ISNULL(PL.PHONE,'''') AS PHONE,
SM.SELLMRP,SM.DAP,SM.SPRID,SM.ISACTIVE,ISNULL(SM.PROCUREMENTSLA,0),ISNULL(SM.REPLACEMENTDAY,0),
CONVERT(DECIMAL(18,2),SM.SHIPPINGCHARGES),ISNULL(SM.CASHONDELIVERY,0),ISNULL(SM.WEIGHT_KG,0),ISNULL(SM.LENGTH_CMS,0),ISNULL(SM.BREADTH_CMS,0),ISNULL(SM.HEIGHT_CMS,0),
CONVERT(DECIMAL(18,0),ISNULL(V.VATPERCVALUE,0)) AS MVAT, ISNULL(SM.DEALSIDS,'''')
,ISNULL(SM.STOCKIN,0),ISNULL(SM.STOCKOUT,0),ISNULL(SM.STOCKNET,0),CONVERT(BIT, (CASE WHEN ISNULL(SM.STOCKNET,0) <= 0 THEN 0 ELSE 1 END)) AS ISSTOCK,V.VATTITLE,0 AS PRODUCTCOUNT,
ISNULL(SM.BV,0) AS BV,ISNULL(SM.PV,0) AS JP,SM.IsVerified AS IsVerified,isnull(km.subcatname,'''') ,isnull(DiscountPercentage,0),isnull(SM.CreatedDate,''''),isnull(SM.ModifyDate,''''),isnull(SM.ismerchantstatus,0),isnull(PL.DID,0) as DID
FROM IMS_MASTERPRODUCT_temp PM INNER JOIN IMS_SUBPRODUCT_temp SM ON SM.MPRID=PM.MPRID 
INNER JOIN TBL_MAIN_CATEGORY MC ON MC.MAINCATID =PM.MAINCATEGORYID			 
LEFT  JOIN TBL_VAT_CATEGORIES V ON V.VCID = PM.VATCATEGORYID 
LEFT  JOIN PORTAL_LOGIN PL ON PL.PLID= PM.BranchId 
join tbl_sub_category km on PM.SubCategoryId=km.subcatid
LEFT  JOIN Portal_Master pma on pma.PMID=pl.PMID
WHERE (PM.MPRID >0) ';
  IF (v_status >= 0) THEN
  v_query := v_query || ' AND isnull(SM.ismerchantstatus,0) =' || CAST(v_status AS VARCHAR(20));
  END IF;
  IF (v_isverified >= 0) THEN
  v_query := v_query || ' AND isnull(SM.IsVerified,0) =' || CAST(v_isverified AS VARCHAR(20));
  END IF;
  IF (v_merchantname <> '') THEN
  v_query := v_query || ' AND (PMA.COMPANYNAME) LIKE ''%' || v_merchantname || '%'' ';
  END IF;
  IF (v_fromdate = '' OR v_todate = '') THEN
  IF (v_fromdate <> '') THEN
  v_query := v_query || ' AND CONVERT(DATE, SM.ModifyDate,103) >= REPLACE(CONVERT(DATE,''' || v_fromdate || ''',103),''/'',''-'') ';
  END IF;
  IF (v_todate <> '') THEN
  v_query := v_query || ' AND CONVERT(DATE, SM.ModifyDate,103)  <=REPLACE(CONVERT(DATE,''' || v_todate || ''',103),''/'',''-'') ';
  END IF;
  END IF;
  IF (v_fromdate <> '' AND v_todate <> '') THEN
  v_query := v_query || '  AND  CONVERT(DATE, SM.ModifyDate,103)  BETWEEN  REPLACE(CONVERT(DATE,''' || v_fromdate || ''',103),''/'',''-'')  AND REPLACE(CONVERT(DATE,''' || v_todate || ''',103),''/'',''-'')';
  END IF;
  IF (v_searchvaluesubcategory <> '') THEN
  v_searchvaluesubcategory := REPLACE(v_searchvaluesubcategory, '''', '''''');
  v_query := v_query || 'AND km.subcatname LIKE''%' || v_searchvaluesubcategory || '%''';
  END IF;
  IF (v_searchfield = 'PRODUCTTITLE') THEN
  v_query := v_query || ' AND PM.PRODUCTTITLE LIKE ''%' || v_searchvalue || '%'' ';
  END IF;
  IF (v_searchfield = 'Subcategory') THEN
  v_query := v_query || ' AND km.subcatname LIKE ''%' || v_searchvalue || '%'' ';
  END IF;
  IF (v_productname <> '') THEN
  v_productname := REPLACE(v_productname, '''', '''''');
  v_query := v_query || ' and PM.ProductTitle =''' || v_productname || '''';
  END IF;
  IF (v_did > 0) THEN
  v_query := v_query || ' AND  PL.DID=' || CAST(v_did AS VARCHAR(50)) || '';
  END IF;
  IF (v_subcatid <> '') THEN
  v_query := v_query || ' AND km.subcatid =' || CAST(v_subcatid AS VARCHAR(20));
  END IF;
  v_query := v_query || ' ORDER BY  PM.MPRID DESC ';
  EXECUTE v_query;
  RETURN QUERY SELECT * FROM tmp_productlisttemp WHERE rownumber BETWEEN v_minindex AND v_maxindex;
  SELECT COUNT(rownumber) INTO v_totalcount FROM tmp_productlisttemp;
  DROP TABLE IF EXISTS tmp_productlisttemp;
  -- SET option (removed)
END;
$$;


--
-- Name: usp_getall_status_productlist_f(integer, integer, bigint, bigint, bigint, character varying, character varying, character varying, character varying, character varying, integer, integer, integer, integer, character varying, character varying, character varying, integer, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_getall_status_productlist_f(v_startrowindex integer DEFAULT 1, v_maxrows integer DEFAULT 1000, v_mprid bigint DEFAULT 0, v_sprid bigint DEFAULT 0, v_branchid bigint DEFAULT 0, v_cat_code character varying DEFAULT ''::character varying, v_searchfield character varying DEFAULT ''::character varying, v_searchvalue character varying DEFAULT ''::character varying, v_fromdate character varying DEFAULT ''::character varying, v_todate character varying DEFAULT ''::character varying, v_status integer DEFAULT 5, v_totalcount integer DEFAULT 0, v_subcatid integer DEFAULT 0, v_isverified integer DEFAULT 0, v_searchvaluesubcategory character varying DEFAULT ''::character varying, v_merchantname character varying DEFAULT ''::character varying, v_productname character varying DEFAULT ''::character varying, v_did integer DEFAULT 0, v_categoryrelatedto integer DEFAULT 0) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_minindex INT;
  v_maxindex INT;
  v_query text;
  v_catecode INT;
BEGIN
  v_minindex := (v_startrowindex - 1) * v_maxrows + 1;
  v_maxindex := v_startrowindex * v_maxrows;
  DROP TABLE IF EXISTS tmp_productlisttemp;
  CREATE TEMP TABLE tmp_productlisttemp (ROWNUMBER BIGINT GENERATED BY DEFAULT AS IDENTITY  




,MPRID BIGINT   
,PRODUCTCODE VARCHAR( 50)   
,SUBPRCODE VARCHAR( 50)   
,PRODUCTTITLE VARCHAR( 300)   
,MAINCATNAME VARCHAR( 250)   
,QTY INT   
,UNIT VARCHAR( 50)   
,PRODUCTIMAGES VARCHAR( 1000)   
,MerchantName VARCHAR( 1000)   
,EMAILID VARCHAR( 100)   
,PHONE VARCHAR( 100)   
,SELLMRP DECIMAL   
,DAP DECIMAL   
,SPRID BIGINT   
,ISACTIVE boolean  ,  
PROCUREMENTSLA INT,  
REPLACEMENTDAY INT,  
SHIPPINGCHARGES DECIMAL(18,2),  
CASHONDELIVERY boolean,  
WEIGHT_KG DECIMAL(18,2),  
LENGTH_CMS DECIMAL(18,2),  
BREADTH_CMS DECIMAL(18,2),  
HEIGHT_CMS DECIMAL(18,2)  
,MVAT DECIMAL   
,DEALSIDS VARCHAR(100)  
,STOCKINQTY INT   
,STOCKOUTQTY INT   
,STOCKNETQTY INT   
,ISSTOCK boolean   
,VATTITLE VARCHAR(100)   
,PRODUCTCOUNT INT,  
BV DECIMAL(18,2),  
JP DECIMAL(18,2),  
IsVerified int,  
Subcategory varchar(500),  
Discountpercentage decimal,  
CreatedDate timestamp,  
ModifyDate timestamp,  
ismerchantstatus int,  
DID int) ON COMMIT DROP;
  v_query := 'INSERT INTO #PRODUCTLISTTEMP SELECT PM.MPRID,PM.PRODUCTCODE,SM.SUBPRCODE,PM.PRODUCTTITLE, MC.MAINCATNAME,SM.QTY,SM.UNIT,SM.PRODUCTIMAGES,  
ISNULL((PMA.COMPANYNAME),'''') as MerchantName,ISNULL(PL.EMAILID,'''') AS EMAILID,ISNULL(PL.PHONE,'''') AS PHONE,  
SM.SELLMRP,SM.DAP,SM.SPRID,SM.ISACTIVE,ISNULL(SM.PROCUREMENTSLA,0),ISNULL(SM.REPLACEMENTDAY,0),  
CONVERT(DECIMAL(18,2),SM.SHIPPINGCHARGES),ISNULL(SM.CASHONDELIVERY,0),ISNULL(SM.WEIGHT_KG,0),ISNULL(SM.LENGTH_CMS,0),ISNULL(SM.BREADTH_CMS,0),ISNULL(SM.HEIGHT_CMS,0),  
CONVERT(DECIMAL(18,0),ISNULL(V.VATPERCVALUE,0)) AS MVAT, ISNULL(SM.DEALSIDS,'''')  
,ISNULL(SM.STOCKIN,0),ISNULL(SM.STOCKOUT,0),ISNULL(SM.STOCKNET,0),CONVERT(BIT, (CASE WHEN ISNULL(SM.STOCKNET,0) <= 0 THEN 0 ELSE 1 END)) AS ISSTOCK,V.VATTITLE,0 AS PRODUCTCOUNT,  
ISNULL(SM.BV,0) AS BV,ISNULL(SM.PV,0) AS JP,SM.IsVerified AS IsVerified,isnull(km.subcatname,'''') ,isnull(DiscountPercentage,0),isnull(SM.CreatedDate,''''),isnull(SM.ModifyDate,''''),isnull(SM.ismerchantstatus,0),isnull(PL.DID,0) as DID  
FROM IMS_MASTERPRODUCT_temp PM INNER JOIN IMS_SUBPRODUCT_temp SM ON SM.MPRID=PM.MPRID   
INNER JOIN TBL_MAIN_CATEGORY MC ON MC.MAINCATID =PM.MAINCATEGORYID      
LEFT  JOIN TBL_VAT_CATEGORIES V ON V.VCID = PM.VATCATEGORYID   
LEFT  JOIN PORTAL_LOGIN PL ON PL.PLID= PM.BRANCHID   
JOIN TBL_SUB_CATEGORY KM ON PM.SUBCATEGORYID=KM.SUBCATID  
LEFT  JOIN PORTAL_MASTER PMA ON PMA.PMID=PL.PMID  
WHERE (PM.MPRID >0) ';
  IF (v_categoryrelatedto > 0) THEN
  v_query := v_query || ' AND MC.CATEGORYRELATEDTO=' || CAST(v_categoryrelatedto AS VARCHAR(10));
  END IF;
  IF (v_status >= 0) THEN
  v_query := v_query || ' AND isnull(SM.ismerchantstatus,0) =' || CAST(v_status AS VARCHAR(20));
  END IF;
  IF (v_isverified >= 0) THEN
  v_query := v_query || ' AND isnull(SM.IsVerified,0) =' || CAST(v_isverified AS VARCHAR(20));
  END IF;
  IF (v_merchantname <> '') THEN
  v_query := v_query || ' AND (PMA.COMPANYNAME) LIKE ''%' || v_merchantname || '%'' ';
  END IF;
  IF (v_fromdate = '' OR v_todate = '') THEN
  IF (v_fromdate <> '') THEN
  v_query := v_query || ' AND CONVERT(DATE, SM.ModifyDate,103) >= REPLACE(CONVERT(DATE,''' || v_fromdate || ''',103),''/'',''-'') ';
  END IF;
  IF (v_todate <> '') THEN
  v_query := v_query || ' AND CONVERT(DATE, SM.ModifyDate,103)  <=REPLACE(CONVERT(DATE,''' || v_todate || ''',103),''/'',''-'') ';
  END IF;
  END IF;
  IF (v_fromdate <> '' AND v_todate <> '') THEN
  v_query := v_query || '  AND  CONVERT(DATE, SM.ModifyDate,103)  BETWEEN  REPLACE(CONVERT(DATE,''' || v_fromdate || ''',103),''/'',''-'')  AND REPLACE(CONVERT(DATE,''' || v_todate || ''',103),''/'',''-'')';
  END IF;
  IF (v_searchvaluesubcategory <> '') THEN
  v_searchvaluesubcategory := REPLACE(v_searchvaluesubcategory, '''', '''''');
  v_query := v_query || 'AND km.subcatname LIKE''%' || v_searchvaluesubcategory || '%''';
  END IF;
  IF (v_searchfield = 'PRODUCTTITLE') THEN
  v_query := v_query || ' AND PM.PRODUCTTITLE LIKE ''%' || v_searchvalue || '%'' ';
  END IF;
  IF (v_searchfield = 'Subcategory') THEN
  v_query := v_query || ' AND km.subcatname LIKE ''%' || v_searchvalue || '%'' ';
  END IF;
  IF (v_productname <> '') THEN
  v_productname := REPLACE(v_productname, '''', '''''');
  v_query := v_query || ' and PM.ProductTitle =''' || v_productname || '''';
  END IF;
  IF (v_did > 0) THEN
  v_query := v_query || (' AND PL.PLID In(SELECT PLID FROM PORTAL_MASTER WHERE CID IN(SELECT CID FROM DISTRIBUTOR_MASTER WHERE PLID=' || CAST(v_did AS VARCHAR(5)) || '))');
  END IF;
  IF (v_subcatid <> '') THEN
  v_query := v_query || ' AND km.subcatid =' || CAST(v_subcatid AS VARCHAR(20));
  END IF;
  v_query := v_query || ' ORDER BY  PM.MPRID DESC ';
  EXECUTE v_query;
  RETURN QUERY SELECT * FROM tmp_productlisttemp WHERE rownumber BETWEEN v_minindex AND v_maxindex;
  SELECT COUNT(rownumber) INTO v_totalcount FROM tmp_productlisttemp;
  DROP TABLE IF EXISTS tmp_productlisttemp;
  -- SET option (removed)
END;
$$;


--
-- Name: usp_getallcustomerrechareges(); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_getallcustomerrechareges() RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
BEGIN
  RETURN QUERY SELECT prepaid.clid, prepaid.transactionid, prepaid.rechargeamount, prepaid.rechargedate, prepaid.rechargestatus, prepaid.operatortype FROM dbo.tbl_customer_prepaid_recharges AS prepaid WHERE CAST(prepaid.rechargedate AS DATE) BETWEEN CAST(CURRENT_TIMESTAMP - 1 AS DATE) AND CAST(CURRENT_TIMESTAMP AS DATE) AND (prepaid.rechargestatus = 'PENDING' OR prepaid.rechargestatus = 'SUCCESS') UNION ALL SELECT postpaid.clid, postpaid.transactionid, postpaid.rechargeamount, postpaid.rechargedate, postpaid.rechargestatus, postpaid.operatortype FROM dbo.tbl_customer_postpaid_recharges AS postpaid WHERE CAST(postpaid.rechargedate AS DATE) BETWEEN CAST(CURRENT_TIMESTAMP - 1 AS DATE) AND CAST(CURRENT_TIMESTAMP AS DATE) AND (postpaid.rechargestatus = 'PENDING' OR postpaid.rechargestatus = 'SUCCESS') UNION ALL SELECT dth.clid, dth.transactionid, dth.rechargeamount, dth.rechargedate, dth.rechargestatus, dth.operatortype FROM dbo.tbl_customer_dth_recharges AS dth WHERE CAST(dth.rechargedate AS DATE) BETWEEN CAST(CURRENT_TIMESTAMP - 1 AS DATE) AND CAST(CURRENT_TIMESTAMP AS DATE) AND (dth.rechargestatus = 'PENDING' OR dth.rechargestatus = 'SUCCESS') UNION ALL SELECT gas.clid, gas.transactionid, gas.rechargeamount, gas.rechargedate, gas.rechargestatus, gas.operatortype FROM dbo.tbl_customer_gas_recharges AS gas WHERE CAST(gas.rechargedate AS DATE) BETWEEN CAST(CURRENT_TIMESTAMP - 1 AS DATE) AND CAST(CURRENT_TIMESTAMP AS DATE) AND (gas.rechargestatus = 'PENDING' OR gas.rechargestatus = 'SUCCESS') UNION ALL SELECT electricity.clid, electricity.transactionid, electricity.rechargeamount, electricity.rechargedate, electricity.rechargestatus, electricity.operatortype FROM dbo.tbl_customer_electricity_recharges AS electricity WHERE CAST(electricity.rechargedate AS DATE) BETWEEN CAST(CURRENT_TIMESTAMP - 1 AS DATE) AND CAST(CURRENT_TIMESTAMP AS DATE) AND (electricity.rechargestatus = 'PENDING' OR electricity.rechargestatus = 'SUCCESS') UNION ALL SELECT insurance.clid, insurance.transactionid, insurance.rechargeamount, insurance.rechargedate, insurance.rechargestatus, insurance.operatortype FROM dbo.tbl_customer_insurance_recharges AS insurance WHERE CAST(insurance.rechargedate AS DATE) BETWEEN CAST(CURRENT_TIMESTAMP - 1 AS DATE) AND CAST(CURRENT_TIMESTAMP AS DATE) AND (insurance.rechargestatus = 'PENDING' OR insurance.rechargestatus = 'SUCCESS');
END;
$$;


--
-- Name: usp_getalldetailby_username_resellerid(character varying, character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_getalldetailby_username_resellerid(v_username character varying DEFAULT '63281916'::character varying, v_resellerid character varying DEFAULT 'abc9-tg89-rt7y-7485'::character varying) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF (v_username <> '') THEN
  RETURN QUERY SELECT mm.userid, mm.emailid, mm.phone, od.orderid, pr.product_name AS productname, pr.product_qty AS quantity, CAST(pr.single_dap AS DECIMAL(18, 2)) AS sellcost, CAST(pr.total_vat AS DECIMAL(18, 2)) AS gst, pr.status, CAST(sp.discountpercentage AS DECIMAL(18, 2)) AS "discount %", CAST(od.order_bv AS DECIMAL(18, 2)) AS bv, CAST((pr.single_dap * pr.product_qty) AS DECIMAL(18, 2)) AS totalamount, CAST(TO_CHAR(orderdate, 'MM-DD-YYYY') AS VARCHAR(10)) AS date, mm.loginid AS memberid FROM tbl_order_master AS od INNER JOIN tbl_product_order_master AS pr ON od.orderid = pr.orderid INNER JOIN tbl_customerlogin AS mm ON od.loginid = mm.loginid INNER JOIN ims_subproduct AS sp ON sp.sprid = pr.subprcode INNER JOIN distributor_master AS dm ON dm.pmid = mm.did WHERE mm.userid = v_username AND dm.apikey = v_resellerid;
  END IF;
END;
$$;


--
-- Name: usp_getallpaymentgateways(); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_getallpaymentgateways() RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
BEGIN
  RETURN QUERY SELECT tpgid, gatewayname, active, createddate FROM tbl_paymentgateways;
END;
$$;


--
-- Name: usp_getallrespounser_data(integer, integer, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_getallrespounser_data(v_plid integer DEFAULT 0, v_smcid integer DEFAULT 0, v_mode integer DEFAULT 0) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_returnvalues text;
  v_cid bigint;
  v_currencycode text;
BEGIN
  SELECT plid INTO v_plid FROM tbl_sponsor_master_campain WHERE smcid = v_smcid;
  SELECT cid INTO v_cid FROM portal_login WHERE plid = v_plid;
  SELECT currencycode INTO v_currencycode FROM country WHERE cid = v_cid;
  IF (v_mode = 0) THEN
  IF NOT EXISTS(SELECT * FROM tbl_sponsor_master_campain WHERE smcid = v_smcid AND plid = v_plid) THEN
  v_returnvalues := 'not Match';
  ELSE
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp ON COMMIT DROP AS SELECT cpc.cpcidforcategory, c.catname, k.keywordname, cpc.catid, COALESCE(k.kmid, 0) AS kmid, k.scatid, cpc.cpc, con.currencycode, 0 AS matchtype FROM tbl_cpcforcatergory AS cpc INNER JOIN product_category AS c ON c.catid = cpc.catid LEFT JOIN keyword_master AS k ON k.kmid = cpc.keyword_id INNER JOIN country AS con ON cpc.cid = con.cid WHERE con.cid = v_cid AND c.catactive = 1 AND k.kactive = 1 ORDER BY c.catid NULLS FIRST, COALESCE(k.kmid, 0) ASC NULLS FIRST;
  UPDATE tmp_temp SET matchtype = 1 WHERE catid IN (SELECT catid FROM tbl_keyword_in_sponsorad WHERE smcid = v_smcid AND keywordid = 0) AND kmid = 0;
  UPDATE tmp_temp SET matchtype = 1 WHERE kmid IN (SELECT keywordid FROM tbl_keyword_in_sponsorad WHERE smcid = v_smcid AND keywordid > 0) AND kmid > 0;
  RETURN QUERY SELECT * FROM tmp_temp ORDER BY catid NULLS FIRST, kmid ASC NULLS FIRST;
  END IF;
  ELSE
  IF (v_mode = 1) THEN
  RETURN QUERY SELECT CASE (COALESCE(km.keywordname, '')) WHEN '' THEN pc.catname WHEN km.keywordname THEN km.keywordname END AS keywordname, COALESCE(ks.key_price, 0.00) AS key_price, COALESCE(ks.bid_price, 0.00) AS bid_price, ks.key_sp_id, ks.smcid, ks.keywordid, ks.status, ks.catid, COALESCE(currencycode, '') AS currencycode FROM tbl_keyword_in_sponsorad AS ks LEFT JOIN keyword_master AS km ON km.kmid = ks.keywordid INNER JOIN product_category AS pc ON pc.catid = ks.catid LEFT JOIN country AS country ON country.cid = v_cid WHERE ks.smcid = v_smcid AND km.kactive = 1 ORDER BY ks.catid NULLS FIRST, keywordname ASC NULLS FIRST;
  END IF;
  END IF;
END;
$$;


--
-- Name: usp_getallticketlist(integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_getallticketlist(v_clid integer DEFAULT 2159) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
BEGIN
  -- BEGIN TRAN (removed)
  -- SET option (removed)
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp ON COMMIT DROP AS SELECT tmid, ticketno, CAST(TO_CHAR(date, 'DD TMMon YYYY') AS VARCHAR(11)) AS createdate, categoryname, CAST(TO_CHAR(lastupdate, 'DD TMMon YYYY') AS VARCHAR(20)) AS lastupdatedate, subject, sm.name AS status FROM tbl_ticketmaster AS tm INNER JOIN tbl_statusmaster AS sm ON sm.id = tm.status WHERE fromplid = v_clid AND accounttype = 2;
  RETURN QUERY SELECT ROW_NUMBER() OVER (ORDER BY tmid DESC NULLS LAST) AS number, * FROM tmp_temp ORDER BY TO_DATE(lastupdatedate, 'DD-MM-YYYY') DESC NULLS LAST;
  -- SET option (removed)
  -- COMMIT (removed)
END;
$$;


--
-- Name: usp_getapprovedproductlist(integer, integer, bigint, bigint, bigint, character varying, character varying, character varying, integer, integer, integer, character varying, character varying, character varying, character varying, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_getapprovedproductlist(v_startrowindex integer DEFAULT 1, v_maxrows integer DEFAULT 1000, v_mprid bigint DEFAULT 0, v_sprid bigint DEFAULT 0, v_branchid bigint DEFAULT 0, v_cat_code character varying DEFAULT ''::character varying, v_searchfield character varying DEFAULT ''::character varying, v_searchvalue character varying DEFAULT ''::character varying, v_status integer DEFAULT 1, v_totalcount integer DEFAULT 0, v_isverfied integer DEFAULT 0, v_searchvaluesubcategory character varying DEFAULT ''::character varying, v_searchvaluetitle character varying DEFAULT ''::character varying, v_merchantname character varying DEFAULT ''::character varying, v_productname character varying DEFAULT ''::character varying, v_did integer DEFAULT 0) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_minindex INT;
  v_maxindex INT;
  v_query text;
  v_catecode INT;
BEGIN
  v_minindex := (v_startrowindex - 1) * v_maxrows + 1;
  v_maxindex := v_startrowindex * v_maxrows;
  DROP TABLE IF EXISTS tmp_productlisttemp;
  CREATE TEMP TABLE tmp_productlisttemp (ROWNUMBER BIGINT GENERATED BY DEFAULT AS IDENTITY
,MPRID BIGINT 
,PRODUCTCODE VARCHAR( 50) 
,SUBPRCODE VARCHAR( 50) 
,PRODUCTTITLE VARCHAR( 300) 
,MAINCATNAME VARCHAR( 250) 
,QTY INT 
,UNIT VARCHAR( 50) 
,PRODUCTIMAGES VARCHAR( 1000) 
,MERCHANTNAME VARCHAR( 1000) 
,EMAILID VARCHAR( 100) 
,PHONE VARCHAR( 100) 
,SELLMRP DECIMAL(18,2) 
,DAP DECIMAL(18,2) 
,SPRID BIGINT 
,ISACTIVE boolean  ,
PROCUREMENTSLA INT,
REPLACEMENTDAY INT,
SHIPPINGCHARGES DECIMAL(18,2),
CASHONDELIVERY boolean,
WEIGHT_KG DECIMAL(18,2),
LENGTH_CMS DECIMAL(18,2),
BREADTH_CMS DECIMAL(18,2),
HEIGHT_CMS DECIMAL(18,2)
,MVAT DECIMAL 
,DEALSIDS VARCHAR(100)
,STOCKINQTY INT 
,STOCKOUTQTY INT 
,STOCKNETQTY INT 
,ISSTOCK boolean 
,VATTITLE VARCHAR(100) 
,PRODUCTCOUNT INT,
BV DECIMAL(18,2),
JP DECIMAL(18,2),
Rejectremark varchar(500),
Subcategory varchar(200),
Discountpercentage decimal(18,2),
productentry varchar(200),
DID int) ON COMMIT DROP;
  v_query := 'INSERT INTO #PRODUCTLISTTEMP SELECT isnull(PM.MPRID,0),isnull(PM.PRODUCTCODE,''''),isnull(SM.SUBPRCODE,''''),isnull(PM.PRODUCTTITLE,''''), isnull(MC.MAINCATNAME,''''),isnull(SM.QTY,0),isnull(SM.UNIT,''''),isnull(SM.PRODUCTIMAGES,''''),
ISNULL((PMA.COMPANYNAME),'''') AS MERCHANTNAME,ISNULL(PL.EMAILID,'''') AS EMAILID,ISNULL(PL.PHONE,'''') AS PHONE,
isnull(SM.SELLMRP,0),isnull(SM.DAP,0),isnull(SM.SPRID,0),isnull(SM.ISACTIVE,0),ISNULL(SM.PROCUREMENTSLA,0),ISNULL(SM.REPLACEMENTDAY,0),
CONVERT(DECIMAL(18,2),SM.SHIPPINGCHARGES),ISNULL(SM.CASHONDELIVERY,0),ISNULL(SM.WEIGHT_KG,0),ISNULL(SM.LENGTH_CMS,0),ISNULL(SM.BREADTH_CMS,0),ISNULL(SM.HEIGHT_CMS,0),
CONVERT(DECIMAL(18,0),ISNULL(V.VATPERCVALUE,0)) AS MVAT, ISNULL(SM.DEALSIDS,'''')
,ISNULL(SM.STOCKIN,0),ISNULL(SM.STOCKOUT,0),ISNULL(SM.STOCKNET,0),CONVERT(BIT, (CASE WHEN ISNULL(SM.STOCKNET,0) <= 0 THEN 0 ELSE 1 END)) AS ISSTOCK,V.VATTITLE,0 AS PRODUCTCOUNT,
ISNULL(SM.BV,0) AS BV,ISNULL(SM.PV,0) AS JP,SM.Rejectremark,isnull(km.subcatname,''''),isnull(DiscountPercentage,0),isnull(SM.productentry,'''') AS productentry,isnull(PL.DID,0) as DID
FROM IMS_MASTERPRODUCT_Temp PM INNER JOIN IMS_SUBPRODUCT_Temp SM ON SM.MPRID=PM.MPRID 
INNER JOIN TBL_MAIN_CATEGORY MC ON MC.MAINCATID =PM.MAINCATEGORYID			 
LEFT  JOIN TBL_VAT_CATEGORIES V ON V.VCID = PM.VATCATEGORYID 
LEFT  JOIN PORTAL_LOGIN PL ON PL.PLID= PM.BRANCHID
Left join tbl_sub_category km on PM.SubCategoryId=km.subcatid
left join Portal_Master pma on pma.PMID=pl.PMID
WHERE PM.MPRID >0 ';
  IF (v_status > 0) THEN
  v_query := v_query || ' AND SM.ISACTIVE =' || CAST(v_status AS VARCHAR(20));
  END IF;
  IF (v_searchfield = 'EMAILID') THEN
  v_query := v_query || ' AND PL.EMAILID LIKE ''%' || v_searchvalue || '%'' ';
  END IF;
  IF (v_searchfield = 'MERCHANTNAME') THEN
  v_query := v_query || ' AND (PMA.COMPANYNAME) LIKE ''%' || v_searchvalue || '%'' ';
  END IF;
  IF (v_searchfield = 'productentry') THEN
  v_query := v_query || ' AND SM.productentry LIKE ''%' || v_searchvalue || '%'' ';
  END IF;
  IF (v_searchfield = 'PHONE') THEN
  v_query := v_query || ' AND PL.PHONE LIKE ''%' || v_searchvalue || '%'' ';
  END IF;
  IF (v_searchfield <> '') THEN
  v_query := v_query || 'AND km.subcatname LIKE''%' || v_searchfield || '%''';
  END IF;
  IF (v_searchvalue <> '') THEN
  v_query := v_query || 'AND PM.PRODUCTTITLE LIKE''%' || v_searchvalue || '%''';
  END IF;
  IF (v_merchantname <> '') THEN
  v_query := v_query || ' AND PMA.COMPANYNAME LIKE ''%' || v_merchantname || '%'' ';
  END IF;
  IF (v_searchvaluesubcategory <> '') THEN
  v_searchvaluesubcategory := REPLACE(v_searchvaluesubcategory, '''', '''''');
  v_query := v_query || 'AND km.subcatname LIKE''%' || v_searchvaluesubcategory || '%''';
  END IF;
  IF (v_searchvaluetitle <> '') THEN
  v_query := v_query || 'AND PM.PRODUCTTITLE LIKE''%' || v_searchvaluetitle || '%''';
  END IF;
  IF (v_productname <> '') THEN
  v_productname := REPLACE(v_productname, '''', '''''');
  v_query := v_query || ' and PM.ProductTitle =''' || v_productname || '''';
  END IF;
  IF (v_branchid > 0) THEN
  v_query := v_query || ' AND(' || CAST(v_branchid AS VARCHAR(50)) || ' = 1 OR PM.BRANCHID=' || CAST(v_branchid AS VARCHAR(50)) || ')';
  END IF;
  IF (v_did > 0) THEN
  v_query := v_query || ' AND  PL.DID=' || CAST(v_did AS VARCHAR(50)) || '';
  END IF;
  IF (v_mprid > 0) THEN
  v_query := v_query || ' AND PM.MPRID =' || CAST(v_mprid AS VARCHAR(20));
  END IF;
  IF (v_sprid > 0) THEN
  v_query := v_query || ' AND SM.SPRID =' || CAST(v_sprid AS VARCHAR(20));
  END IF;
  IF (v_cat_code <> '') THEN
  v_catecode := 0;
  SELECT catid INTO v_catecode FROM tbl_category WHERE cat_code = v_cat_code;
  IF (v_catecode > 0) THEN
  v_query := v_query || ' AND PM.CATID =' || CAST(v_catecode AS VARCHAR(20));
  ELSE
  SELECT subcatid INTO v_catecode FROM tbl_sub_category WHERE sub_cat_code = v_cat_code;
  v_query := v_query || ' AND PM.SUBCATEGORYID =' || CAST(v_catecode AS VARCHAR(20));
  END IF;
  END IF;
  IF (v_isverfied >= 0) THEN
  v_query := v_query || ' AND SM.ismerchantstatus =' || CAST(4 AS VARCHAR(20));
  END IF;
  v_query := v_query || ' ORDER BY  PM.MPRID DESC ';
  EXECUTE v_query;
  RETURN QUERY SELECT * FROM tmp_productlisttemp WHERE rownumber BETWEEN v_minindex AND v_maxindex;
  SELECT COUNT(rownumber) INTO v_totalcount FROM tmp_productlisttemp;
  DROP TABLE IF EXISTS tmp_productlisttemp;
  -- SET option (removed)
END;
$$;


--
-- Name: usp_getapprovedproductlist1(integer, integer, bigint, bigint, bigint, character varying, character varying, character varying, integer, integer, integer, character varying, character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_getapprovedproductlist1(v_startrowindex integer DEFAULT 1, v_maxrows integer DEFAULT 1000, v_mprid bigint DEFAULT 0, v_sprid bigint DEFAULT 0, v_branchid bigint DEFAULT 0, v_cat_code character varying DEFAULT ''::character varying, v_searchfield character varying DEFAULT ''::character varying, v_searchvalue character varying DEFAULT ' '::character varying, v_status integer DEFAULT 1, v_totalcount integer DEFAULT 0, v_isverfied integer DEFAULT 1, v_searchvaluesubcategory character varying DEFAULT ''::character varying, v_searchvaluetitle character varying DEFAULT ''::character varying) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_minindex INT;
  v_maxindex INT;
  v_query text;
  v_catecode INT;
BEGIN
  v_minindex := (v_startrowindex - 1) * v_maxrows + 1;
  v_maxindex := v_startrowindex * v_maxrows;
  DROP TABLE IF EXISTS tmp_productlisttemp;
  CREATE TEMP TABLE tmp_productlisttemp (ROWNUMBER BIGINT GENERATED BY DEFAULT AS IDENTITY
,MPRID BIGINT 
,PRODUCTCODE VARCHAR( 50) 
,SUBPRCODE VARCHAR( 50) 
,PRODUCTTITLE VARCHAR( 300) 
,MAINCATNAME VARCHAR( 250) 
,QTY INT 
,UNIT VARCHAR( 50) 
,PRODUCTIMAGES VARCHAR( 1000) 
,MERCHANTNAME VARCHAR( 1000) 
,EMAILID VARCHAR( 100) 
,PHONE VARCHAR( 100) 
,SELLMRP DECIMAL 
,DAP DECIMAL 
,SPRID BIGINT 
,ISACTIVE boolean  ,
PROCUREMENTSLA INT,
REPLACEMENTDAY INT,
SHIPPINGCHARGES DECIMAL(18,2),
CASHONDELIVERY boolean,
WEIGHT_KG DECIMAL(18,2),
LENGTH_CMS DECIMAL(18,2),
BREADTH_CMS DECIMAL(18,2),
HEIGHT_CMS DECIMAL(18,2)
,MVAT DECIMAL 
,DEALSIDS VARCHAR(100)
,STOCKINQTY INT 
,STOCKOUTQTY INT 
,STOCKNETQTY INT 
,ISSTOCK boolean 
,VATTITLE VARCHAR(100) 
,PRODUCTCOUNT INT,
BV DECIMAL(18,2),
JP DECIMAL(18,2),
Rejectremark varchar(500),
Subcategory varchar(200),
Discountpercentage decimal,
productentry varchar(200),
ismerchantstatus int,
CreatedDate Varchar(100),
ModifyDate varchar(100)) ON COMMIT DROP;
  v_query := 'INSERT INTO #PRODUCTLISTTEMP SELECT isnull(PM.MPRID,0) as MPRID,isnull(PM.PRODUCTCODE,0) as PRODUCTCODE,
isnull(SM.SUBPRCODE,'''') as SUBPRCODE,isnull(PM.PRODUCTTITLE,'''') as PRODUCTTITLE , isnull(MC.MAINCATNAME,'''') as MAINCATNAME,isnull(SM.QTY,0) as QTY,isnull(SM.UNIT,'''') as UNIT,isnull(SM.PRODUCTIMAGES,'''') as PRODUCTIMAGES,
ISNULL((PL.FNAME+PL.LNAME),'''') AS MERCHANTNAME,ISNULL(PL.EMAILID,'''') AS EMAILID,ISNULL(PL.PHONE,'''') AS PHONE,
isnull(SM.SELLMRP,0) as SELLMRP ,isnull(SM.DAP,0) as DAP ,isnull(SM.SPRID,0) as SPRID,isnull(SM.ISACTIVE,0) as ISACTIVE,ISNULL(SM.PROCUREMENTSLA,0),ISNULL(SM.REPLACEMENTDAY,0),
CONVERT(DECIMAL(18,2),SM.SHIPPINGCHARGES),ISNULL(SM.CASHONDELIVERY,0),ISNULL(SM.WEIGHT_KG,0),ISNULL(SM.LENGTH_CMS,0),ISNULL(SM.BREADTH_CMS,0),ISNULL(SM.HEIGHT_CMS,0),
CONVERT(DECIMAL(18,0),ISNULL(V.VATPERCVALUE,0)) AS MVAT, ISNULL(SM.DEALSIDS,'''')
,ISNULL(SM.STOCKIN,0),ISNULL(SM.STOCKOUT,0),ISNULL(SM.STOCKNET,0),CONVERT(BIT, (CASE WHEN ISNULL(SM.STOCKNET,0) <= 0 THEN 0 ELSE 1 END)) AS ISSTOCK,V.VATTITLE,0 AS PRODUCTCOUNT,
ISNULL(SM.BV,0) AS BV,ISNULL(SM.PV,0) AS JP,isnull(SM.Rejectremark,'''') as Rejectremark,isnull(km.subcatname,''''),isnull(DiscountPercentage,0),isnull(SM.productentry,'''') AS productentry,isnull(SM.ismerchantstatus,0),
isnull(SM.CreatedDate,''''),isnull(SM.ModifyDate,'''')
FROM IMS_MASTERPRODUCT_Temp PM INNER JOIN IMS_SUBPRODUCT_Temp SM ON SM.MPRID=PM.MPRID 
INNER JOIN TBL_MAIN_CATEGORY MC ON MC.MAINCATID =PM.MAINCATEGORYID			 
LEFT  JOIN TBL_VAT_CATEGORIES V ON V.VCID = PM.VATCATEGORYID 
LEFT  JOIN PORTAL_LOGIN PL ON PL.PLID= PM.BRANCHID
Left join tbl_sub_category km on PM.SubCategoryId=km.subcatid
WHERE PM.MPRID >0 ';
  IF (v_searchfield <> '') THEN
  v_query := v_query || ' AND SM.productentry=''' || v_searchfield || ''' ';
  END IF;
  IF (v_branchid > 0) THEN
  v_query := v_query || ' AND PM.BranchId=' || CAST(v_branchid AS VARCHAR(50)) || '';
  END IF;
  IF (v_searchvalue <> '') THEN
  v_query := v_query || ' AND SM.SUBPRCODE=''' || v_searchvalue || ''' ';
  END IF;
  IF (v_searchvaluesubcategory <> '') THEN
  v_searchvaluesubcategory := REPLACE(v_searchvaluesubcategory, '''', '''''');
  v_query := v_query || 'AND km.subcatname =''' || v_searchvaluesubcategory || '''';
  END IF;
  IF (v_searchvaluetitle <> '') THEN
  v_searchvaluetitle := REPLACE(v_searchvaluetitle, '''', '''''');
  v_query := v_query || ' and PM.ProductTitle =''' || v_searchvaluetitle || '''';
  END IF;
  v_query := v_query || ' ORDER BY  PM.MPRID DESC ';
  EXECUTE v_query;
  RETURN QUERY SELECT * FROM tmp_productlisttemp WHERE rownumber BETWEEN v_minindex AND v_maxindex;
  SELECT COUNT(rownumber) INTO v_totalcount FROM tmp_productlisttemp;
  DROP TABLE IF EXISTS tmp_productlisttemp;
  -- SET option (removed)
END;
$$;


--
-- Name: usp_getapprovedproductlist_bak(integer, integer, bigint, bigint, bigint, character varying, character varying, character varying, integer, integer, integer, character varying, character varying, numeric, numeric, numeric, numeric); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_getapprovedproductlist_bak(v_startrowindex integer DEFAULT 1, v_maxrows integer DEFAULT 1000, v_mprid bigint DEFAULT 0, v_sprid bigint DEFAULT 0, v_branchid bigint DEFAULT 5, v_cat_code character varying DEFAULT ''::character varying, v_searchfield character varying DEFAULT ''::character varying, v_searchvalue character varying DEFAULT ''::character varying, v_status integer DEFAULT 1, v_totalcount integer DEFAULT 0, v_isverfied integer DEFAULT 2, v_searchvaluesubcategory character varying DEFAULT ''::character varying, v_searchvaluetitle character varying DEFAULT ''::character varying, v_searchvaluemrpfrom numeric DEFAULT 0, v_searchvaluemrptto numeric DEFAULT 0, v_searchvaluediscount numeric DEFAULT 0, v_searchvaluedap numeric DEFAULT 0) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_minindex INT;
  v_maxindex INT;
  v_query text;
  v_catecode INT;
BEGIN
  v_minindex := (v_startrowindex - 1) * v_maxrows + 1;
  v_maxindex := v_startrowindex * v_maxrows;
  DROP TABLE IF EXISTS tmp_productlisttemp;
  CREATE TEMP TABLE tmp_productlisttemp (ROWNUMBER BIGINT GENERATED BY DEFAULT AS IDENTITY
,MPRID BIGINT 
,PRODUCTCODE VARCHAR( 50) 
,SUBPRCODE VARCHAR( 50) 
,PRODUCTTITLE VARCHAR( 300) 
,MAINCATNAME VARCHAR( 250) 
,QTY INT 
,UNIT VARCHAR( 50) 
,PRODUCTIMAGES VARCHAR( 1000) 
,MERCHANTNAME VARCHAR( 1000) 
,EMAILID VARCHAR( 100) 
,PHONE VARCHAR( 100) 
,SELLMRP DECIMAL 
,DAP DECIMAL 
,SPRID BIGINT 
,ISACTIVE boolean  ,
PROCUREMENTSLA INT,
REPLACEMENTDAY INT,
SHIPPINGCHARGES DECIMAL(18,2),
CASHONDELIVERY boolean,
WEIGHT_KG DECIMAL(18,2),
LENGTH_CMS DECIMAL(18,2),
BREADTH_CMS DECIMAL(18,2),
HEIGHT_CMS DECIMAL(18,2)
,MVAT DECIMAL 
,DEALSIDS VARCHAR(100)
,STOCKINQTY INT 
,STOCKOUTQTY INT 
,STOCKNETQTY INT 
,ISSTOCK boolean 
,VATTITLE VARCHAR(100) 
,PRODUCTCOUNT INT,
BV DECIMAL(18,2),
JP DECIMAL(18,2),
Rejectremark varchar(500),
Subcategory varchar(200),
Discountpercentage DECIMAL(18,2)) ON COMMIT DROP;
  v_query := 'INSERT INTO #PRODUCTLISTTEMP SELECT PM.MPRID,PM.PRODUCTCODE,SM.SUBPRCODE,PM.PRODUCTTITLE, MC.MAINCATNAME,SM.QTY,SM.UNIT,SM.PRODUCTIMAGES,
ISNULL((PL.FNAME+PL.LNAME),'''') AS MERCHANTNAME,ISNULL(PL.EMAILID,'''') AS EMAILID,ISNULL(PL.PHONE,'''') AS PHONE,
SM.SELLMRP,SM.DAP,SM.SPRID,SM.ISACTIVE,ISNULL(SM.PROCUREMENTSLA,0),ISNULL(SM.REPLACEMENTDAY,0),
CONVERT(DECIMAL(18,2),SM.SHIPPINGCHARGES),ISNULL(SM.CASHONDELIVERY,0),ISNULL(SM.WEIGHT_KG,0),ISNULL(SM.LENGTH_CMS,0),ISNULL(SM.BREADTH_CMS,0),ISNULL(SM.HEIGHT_CMS,0),
CONVERT(DECIMAL(18,0),ISNULL(V.VATPERCVALUE,0)) AS MVAT, ISNULL(SM.DEALSIDS,'''')
,ISNULL(SM.STOCKIN,0),ISNULL(SM.STOCKOUT,0),ISNULL(SM.STOCKNET,0),CONVERT(BIT, (CASE WHEN ISNULL(SM.STOCKNET,0) <= 0 THEN 0 ELSE 1 END)) AS ISSTOCK,V.VATTITLE,0 AS PRODUCTCOUNT,
ISNULL(SM.BV,0) AS BV,ISNULL(SM.PV,0) AS JP,SM.Rejectremark,km.subcatname,isnull(DiscountPercentage,0)
FROM IMS_MASTERPRODUCT PM INNER JOIN IMS_SUBPRODUCT SM ON SM.MPRID=PM.MPRID 
INNER JOIN TBL_MAIN_CATEGORY MC ON MC.MAINCATID =PM.MAINCATEGORYID			 
LEFT  JOIN TBL_VAT_CATEGORIES V ON V.VCID = PM.VATCATEGORYID 
LEFT  JOIN PORTAL_LOGIN PL ON PL.PLID= PM.BRANCHID
Left join tbl_sub_category km on PM.SubCategoryId=km.subcatid
WHERE PM.MPRID >0 ';
  IF (v_status > 0) THEN
  v_query := v_query || ' AND SM.ISACTIVE =' || CAST(v_status AS VARCHAR(20));
  END IF;
  IF (v_searchfield = 'EMAILID') THEN
  v_query := v_query || ' AND PL.EMAILID LIKE ''%' || v_searchvalue || '%'' ';
  END IF;
  IF (v_searchfield = 'MERCHANTNAME') THEN
  v_query := v_query || ' AND (PL.FNAME+PL.LNAME) LIKE ''%' || v_searchvalue || '%'' ';
  END IF;
  IF (v_searchfield = 'PHONE') THEN
  v_query := v_query || ' AND PL.PHONE LIKE ''%' || v_searchvalue || '%'' ';
  END IF;
  IF (v_searchfield = 'PRODUCTTITLE') THEN
  v_query := v_query || ' AND PM.PRODUCTTITLE LIKE ''%' || v_searchvalue || '%'' ';
  END IF;
  IF (v_searchfield = 'MAINCATNAME') THEN
  v_query := v_query || ' AND MC.MAINCATNAME LIKE ''%' || v_searchvalue || '%'' ';
  END IF;
  IF (v_searchvaluesubcategory <> '') THEN
  v_query := v_query || 'AND km.subcatname LIKE''%' || v_searchvaluesubcategory || '%''';
  END IF;
  IF (v_searchvaluetitle <> '') THEN
  v_query := v_query || 'AND PM.PRODUCTTITLE LIKE''%' || v_searchvaluetitle || '%''';
  END IF;
  IF (v_branchid > 0) THEN
  v_query := v_query || ' AND(' || CAST(v_branchid AS VARCHAR(50)) || ' = 1 OR PM.BRANCHID=' || CAST(v_branchid AS VARCHAR(50)) || ')';
  END IF;
  IF (v_mprid > 0) THEN
  v_query := v_query || ' AND PM.MPRID =' || CAST(v_mprid AS VARCHAR(20));
  END IF;
  IF (v_sprid > 0) THEN
  v_query := v_query || ' AND SM.SPRID =' || CAST(v_sprid AS VARCHAR(20));
  END IF;
  IF (v_cat_code <> '') THEN
  v_catecode := 0;
  SELECT catid INTO v_catecode FROM tbl_category WHERE cat_code = v_cat_code;
  IF (v_catecode > 0) THEN
  v_query := v_query || ' AND PM.CATID =' || CAST(v_catecode AS VARCHAR(20));
  ELSE
  SELECT subcatid INTO v_catecode FROM tbl_sub_category WHERE sub_cat_code = v_cat_code;
  v_query := v_query || ' AND PM.SUBCATEGORYID =' || CAST(v_catecode AS VARCHAR(20));
  END IF;
  END IF;
  IF (v_isverfied >= 0) THEN
  v_query := v_query || ' AND SM.ISVERIFIED =' || CAST(v_isverfied AS VARCHAR(20));
  END IF;
  v_query := v_query || ' ORDER BY  PM.MPRID DESC ';
  EXECUTE v_query;
  RETURN QUERY SELECT v_query;
  RETURN QUERY SELECT * FROM tmp_productlisttemp WHERE rownumber BETWEEN v_minindex AND v_maxindex;
  SELECT COUNT(rownumber) INTO v_totalcount FROM tmp_productlisttemp;
  DROP TABLE IF EXISTS tmp_productlisttemp;
  -- SET option (removed)
END;
$$;


--
-- Name: usp_getapprovedproductlist_f(integer, integer, bigint, bigint, bigint, character varying, character varying, character varying, integer, integer, integer, character varying, character varying, character varying, character varying, integer, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_getapprovedproductlist_f(v_startrowindex integer DEFAULT 1, v_maxrows integer DEFAULT 1000, v_mprid bigint DEFAULT 0, v_sprid bigint DEFAULT 0, v_branchid bigint DEFAULT 0, v_cat_code character varying DEFAULT ''::character varying, v_searchfield character varying DEFAULT ''::character varying, v_searchvalue character varying DEFAULT ''::character varying, v_status integer DEFAULT 1, v_totalcount integer DEFAULT 0, v_isverfied integer DEFAULT 0, v_searchvaluesubcategory character varying DEFAULT ''::character varying, v_searchvaluetitle character varying DEFAULT ''::character varying, v_merchantname character varying DEFAULT ''::character varying, v_productname character varying DEFAULT ''::character varying, v_did integer DEFAULT 0, v_categoryrelatedto integer DEFAULT 0) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_minindex INT;
  v_maxindex INT;
  v_query text;
  v_catecode INT;
BEGIN
  v_minindex := (v_startrowindex - 1) * v_maxrows + 1;
  v_maxindex := v_startrowindex * v_maxrows;
  DROP TABLE IF EXISTS tmp_productlisttemp;
  CREATE TEMP TABLE tmp_productlisttemp (ROWNUMBER BIGINT GENERATED BY DEFAULT AS IDENTITY    
,MPRID BIGINT     
,PRODUCTCODE VARCHAR( 50)     
,SUBPRCODE VARCHAR( 50)     
,PRODUCTTITLE VARCHAR( 300)     
,MAINCATNAME VARCHAR( 250)     
,QTY INT     
,UNIT VARCHAR( 50)     
,PRODUCTIMAGES VARCHAR( 1000)     
,MERCHANTNAME VARCHAR( 1000)     
,EMAILID VARCHAR( 100)     
,PHONE VARCHAR( 100)     
,SELLMRP DECIMAL     
,DAP DECIMAL     
,SPRID BIGINT     
,ISACTIVE boolean  ,    
PROCUREMENTSLA INT,    
REPLACEMENTDAY INT,    
SHIPPINGCHARGES DECIMAL(18,2),    
CASHONDELIVERY boolean,    
WEIGHT_KG DECIMAL(18,2),    
LENGTH_CMS DECIMAL(18,2),    
BREADTH_CMS DECIMAL(18,2),    
HEIGHT_CMS DECIMAL(18,2)    
,MVAT DECIMAL     
,DEALSIDS VARCHAR(100)    
,STOCKINQTY INT     
,STOCKOUTQTY INT     
,STOCKNETQTY INT     
,ISSTOCK boolean     
,VATTITLE VARCHAR(100)     
,PRODUCTCOUNT INT,    
BV DECIMAL(18,2),    
JP DECIMAL(18,2),    
Rejectremark varchar(500),    
Subcategory varchar(200),    
Discountpercentage decimal,    
productentry varchar(200),    
DID int) ON COMMIT DROP;
  v_query := 'INSERT INTO #PRODUCTLISTTEMP SELECT isnull(PM.MPRID,0),isnull(PM.PRODUCTCODE,''''),isnull(SM.SUBPRCODE,''''),isnull(PM.PRODUCTTITLE,''''), isnull(MC.MAINCATNAME,''''),isnull(SM.QTY,0),isnull(SM.UNIT,''''),isnull(SM.PRODUCTIMAGES,''''),    
ISNULL((PMA.COMPANYNAME),'''') AS MERCHANTNAME,ISNULL(PL.EMAILID,'''') AS EMAILID,ISNULL(PL.PHONE,'''') AS PHONE,    
isnull(SM.SELLMRP,0),isnull(SM.DAP,0),isnull(SM.SPRID,0),isnull(SM.ISACTIVE,0),ISNULL(SM.PROCUREMENTSLA,0),ISNULL(SM.REPLACEMENTDAY,0),    
CONVERT(DECIMAL(18,2),SM.SHIPPINGCHARGES),ISNULL(SM.CASHONDELIVERY,0),ISNULL(SM.WEIGHT_KG,0),ISNULL(SM.LENGTH_CMS,0),ISNULL(SM.BREADTH_CMS,0),ISNULL(SM.HEIGHT_CMS,0),    
CONVERT(DECIMAL(18,0),ISNULL(V.VATPERCVALUE,0)) AS MVAT, ISNULL(SM.DEALSIDS,'''')    
,ISNULL(SM.STOCKIN,0),ISNULL(SM.STOCKOUT,0),ISNULL(SM.STOCKNET,0),CONVERT(BIT, (CASE WHEN ISNULL(SM.STOCKNET,0) <= 0 THEN 0 ELSE 1 END)) AS ISSTOCK,V.VATTITLE,0 AS PRODUCTCOUNT,    
ISNULL(SM.BV,0) AS BV,ISNULL(SM.PV,0) AS JP,SM.Rejectremark,isnull(km.subcatname,''''),isnull(DiscountPercentage,0),isnull(SM.productentry,'''') AS productentry,isnull(PL.DID,0) as DID    
FROM IMS_MASTERPRODUCT_Temp PM INNER JOIN IMS_SUBPRODUCT_Temp SM ON SM.MPRID=PM.MPRID     
INNER JOIN TBL_MAIN_CATEGORY MC ON MC.MAINCATID =PM.MAINCATEGORYID        
LEFT  JOIN TBL_VAT_CATEGORIES V ON V.VCID = PM.VATCATEGORYID     
LEFT  JOIN PORTAL_LOGIN PL ON PL.PLID= PM.BRANCHID    
LEFT JOIN TBL_SUB_CATEGORY KM ON PM.SUBCATEGORYID=KM.SUBCATID    
LEFT JOIN PORTAL_MASTER PMA ON PMA.PMID=PL.PMID    
WHERE PM.MPRID >0 ';
  IF (v_status > 0) THEN
  v_query := v_query || ' AND SM.ISACTIVE =' || CAST(v_status AS VARCHAR(20));
  END IF;
  IF (v_searchfield = 'EMAILID') THEN
  v_query := v_query || ' AND PL.EMAILID LIKE ''%' || v_searchvalue || '%'' ';
  END IF;
  IF (v_searchfield = 'MERCHANTNAME') THEN
  v_query := v_query || ' AND (PMA.COMPANYNAME) LIKE ''%' || v_searchvalue || '%'' ';
  END IF;
  IF (v_searchfield = 'productentry') THEN
  v_query := v_query || ' AND SM.productentry LIKE ''%' || v_searchvalue || '%'' ';
  END IF;
  IF (v_searchfield = 'PHONE') THEN
  v_query := v_query || ' AND PL.PHONE LIKE ''%' || v_searchvalue || '%'' ';
  END IF;
  IF (v_searchfield <> '') THEN
  v_query := v_query || 'AND km.subcatname LIKE''%' || v_searchfield || '%''';
  END IF;
  IF (v_searchvalue <> '') THEN
  v_query := v_query || 'AND PM.PRODUCTTITLE LIKE''%' || v_searchvalue || '%''';
  END IF;
  IF (v_merchantname <> '') THEN
  v_query := v_query || ' AND PMA.COMPANYNAME LIKE ''%' || v_merchantname || '%'' ';
  END IF;
  IF (v_searchvaluesubcategory <> '') THEN
  v_searchvaluesubcategory := REPLACE(v_searchvaluesubcategory, '''', '''''');
  v_query := v_query || 'AND km.subcatname LIKE''%' || v_searchvaluesubcategory || '%''';
  END IF;
  IF (v_searchvaluetitle <> '') THEN
  v_query := v_query || 'AND PM.PRODUCTTITLE LIKE''%' || v_searchvaluetitle || '%''';
  END IF;
  IF (v_productname <> '') THEN
  v_productname := REPLACE(v_productname, '''', '''''');
  v_query := v_query || ' and PM.ProductTitle =''' || v_productname || '''';
  END IF;
  IF (v_branchid > 0) THEN
  v_query := v_query || ' AND(' || CAST(v_branchid AS VARCHAR(50)) || ' = 1 OR PM.BRANCHID=' || CAST(v_branchid AS VARCHAR(50)) || ')';
  END IF;
  IF (v_did > 0) THEN
  v_query := v_query || (' AND PL.PLID In(SELECT PLID FROM PORTAL_MASTER WHERE CID IN(SELECT CID FROM DISTRIBUTOR_MASTER WHERE PLID=' || CAST(v_did AS VARCHAR(5)) || '))');
  END IF;
  IF (v_mprid > 0) THEN
  v_query := v_query || ' AND PM.MPRID =' || CAST(v_mprid AS VARCHAR(20));
  END IF;
  IF (v_sprid > 0) THEN
  v_query := v_query || ' AND SM.SPRID =' || CAST(v_sprid AS VARCHAR(20));
  END IF;
  IF (v_cat_code <> '') THEN
  v_catecode := 0;
  SELECT catid INTO v_catecode FROM tbl_category WHERE cat_code = v_cat_code;
  IF (v_catecode > 0) THEN
  v_query := v_query || ' AND PM.CATID =' || CAST(v_catecode AS VARCHAR(20));
  ELSE
  SELECT subcatid INTO v_catecode FROM tbl_sub_category WHERE sub_cat_code = v_cat_code;
  v_query := v_query || ' AND PM.SUBCATEGORYID =' || CAST(v_catecode AS VARCHAR(20));
  END IF;
  END IF;
  IF (v_isverfied >= 0) THEN
  v_query := v_query || ' AND SM.ismerchantstatus =' || CAST(4 AS VARCHAR(20));
  END IF;
  v_query := v_query || ' ORDER BY  PM.MPRID DESC ';
  EXECUTE v_query;
  RETURN QUERY SELECT * FROM tmp_productlisttemp WHERE rownumber BETWEEN v_minindex AND v_maxindex;
  SELECT COUNT(rownumber) INTO v_totalcount FROM tmp_productlisttemp;
  DROP TABLE IF EXISTS tmp_productlisttemp;
  -- SET option (removed)
END;
$$;


--
-- Name: usp_getapprovedproductlist_readytolist(integer, integer, bigint, bigint, bigint, character varying, character varying, character varying, integer, integer, integer, character varying, character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_getapprovedproductlist_readytolist(v_startrowindex integer DEFAULT 1, v_maxrows integer DEFAULT 50, v_mprid bigint DEFAULT 0, v_sprid bigint DEFAULT 0, v_branchid bigint DEFAULT 1, v_cat_code character varying DEFAULT ''::character varying, v_searchfield character varying DEFAULT ''::character varying, v_searchvalue character varying DEFAULT ''::character varying, v_status integer DEFAULT 1, v_totalcount integer DEFAULT 0, v_isverfied integer DEFAULT 2, v_searchvaluesubcategory character varying DEFAULT ''::character varying, v_searchvaluetitle character varying DEFAULT ''::character varying) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_minindex INT;
  v_maxindex INT;
  v_query text;
  v_catecode INT;
BEGIN
  v_minindex := (v_startrowindex - 1) * v_maxrows + 1;
  v_maxindex := v_startrowindex * v_maxrows;
  DROP TABLE IF EXISTS tmp_productlisttemp;
  CREATE TEMP TABLE tmp_productlisttemp (ROWNUMBER BIGINT GENERATED BY DEFAULT AS IDENTITY
,MPRID BIGINT 
,PRODUCTCODE VARCHAR( 50) 
,SUBPRCODE VARCHAR( 50) 
,PRODUCTTITLE VARCHAR( 300) 
,MAINCATNAME VARCHAR( 250) 
,QTY INT 
,UNIT VARCHAR( 50) 
,PRODUCTIMAGES VARCHAR( 1000) 
,MERCHANTNAME VARCHAR( 1000) 
,EMAILID VARCHAR( 100) 
,PHONE VARCHAR( 100) 
,SELLMRP DECIMAL 
,DAP DECIMAL 
,SPRID BIGINT 
,ISACTIVE boolean  ,
PROCUREMENTSLA INT,
REPLACEMENTDAY INT,
SHIPPINGCHARGES DECIMAL(18,2),
CASHONDELIVERY boolean,
WEIGHT_KG DECIMAL(18,2),
LENGTH_CMS DECIMAL(18,2),
BREADTH_CMS DECIMAL(18,2),
HEIGHT_CMS DECIMAL(18,2)
,MVAT DECIMAL 
,DEALSIDS VARCHAR(100)
,STOCKINQTY INT 
,STOCKOUTQTY INT 
,STOCKNETQTY INT 
,ISSTOCK boolean 
,VATTITLE VARCHAR(100) 
,PRODUCTCOUNT INT,
BV DECIMAL(18,2),
JP DECIMAL(18,2),
Rejectremark varchar(500),
Subcategory varchar(200),
Discountpercentage decimal,
ismerchantstatus int) ON COMMIT DROP;
  v_query := 'INSERT INTO #PRODUCTLISTTEMP SELECT PM.MPRID,PM.PRODUCTCODE,SM.SUBPRCODE,PM.PRODUCTTITLE, MC.MAINCATNAME,SM.QTY,SM.UNIT,SM.PRODUCTIMAGES,
ISNULL((PL.FNAME+PL.LNAME),'''') AS MERCHANTNAME,ISNULL(PL.EMAILID,'''') AS EMAILID,ISNULL(PL.PHONE,'''') AS PHONE,
SM.SELLMRP,SM.DAP,SM.SPRID,SM.ISACTIVE,ISNULL(SM.PROCUREMENTSLA,0),ISNULL(SM.REPLACEMENTDAY,0),
CONVERT(DECIMAL(18,2),SM.SHIPPINGCHARGES),ISNULL(SM.CASHONDELIVERY,0),ISNULL(SM.WEIGHT_KG,0),ISNULL(SM.LENGTH_CMS,0),ISNULL(SM.BREADTH_CMS,0),ISNULL(SM.HEIGHT_CMS,0),
CONVERT(DECIMAL(18,0),ISNULL(V.VATPERCVALUE,0)) AS MVAT, ISNULL(SM.DEALSIDS,'''')
,ISNULL(SM.STOCKIN,0),ISNULL(SM.STOCKOUT,0),ISNULL(SM.STOCKNET,0),CONVERT(BIT, (CASE WHEN ISNULL(SM.STOCKNET,0) <= 0 THEN 0 ELSE 1 END)) AS ISSTOCK,V.VATTITLE,0 AS PRODUCTCOUNT,
ISNULL(SM.BV,0) AS BV,ISNULL(SM.PV,0) AS JP,SM.Rejectremark,km.subcatname,isnull(DiscountPercentage,0),isnull(sm.ismerchantstatus,0)
FROM IMS_MASTERPRODUCT_Temp PM INNER JOIN IMS_SUBPRODUCT_Temp SM ON SM.MPRID=PM.MPRID 
INNER JOIN TBL_MAIN_CATEGORY MC ON MC.MAINCATID =PM.MAINCATEGORYID			 
LEFT  JOIN TBL_VAT_CATEGORIES V ON V.VCID = PM.VATCATEGORYID 
LEFT  JOIN PORTAL_LOGIN PL ON PL.PLID= PM.BRANCHID
Left join tbl_sub_category km on PM.SubCategoryId=km.subcatid
WHERE PM.MPRID >0 ';
  IF (v_status > 0) THEN
  v_query := v_query || ' AND SM.ISACTIVE =' || CAST(v_status AS VARCHAR(20));
  END IF;
  IF (v_searchfield = 'EMAILID') THEN
  v_query := v_query || ' AND PL.EMAILID LIKE ''%' || v_searchvalue || '%'' ';
  END IF;
  IF (v_searchfield = 'MERCHANTNAME') THEN
  v_query := v_query || ' AND (PL.FNAME+PL.LNAME) LIKE ''%' || v_searchvalue || '%'' ';
  END IF;
  IF (v_searchfield = 'PHONE') THEN
  v_query := v_query || ' AND PL.PHONE LIKE ''%' || v_searchvalue || '%'' ';
  END IF;
  IF (v_searchfield <> '') THEN
  v_query := v_query || 'AND km.subcatname LIKE''%' || v_searchfield || '%''';
  END IF;
  IF (v_searchvalue <> '') THEN
  v_query := v_query || 'AND PM.PRODUCTTITLE LIKE''%' || v_searchvalue || '%''';
  END IF;
  IF (v_searchfield = 'PRODUCTTITLE') THEN
  v_query := v_query || ' AND PM.PRODUCTTITLE LIKE ''%' || v_searchvalue || '%'' ';
  END IF;
  IF (v_searchfield = 'MAINCATNAME') THEN
  v_query := v_query || ' AND MC.MAINCATNAME LIKE ''%' || v_searchvalue || '%'' ';
  END IF;
  IF (v_searchvaluesubcategory <> '') THEN
  v_query := v_query || 'AND km.subcatname LIKE''%' || v_searchvaluesubcategory || '%''';
  END IF;
  IF (v_searchvaluetitle <> '') THEN
  v_query := v_query || 'AND PM.PRODUCTTITLE LIKE''%' || v_searchvaluetitle || '%''';
  END IF;
  IF (v_branchid > 0) THEN
  v_query := v_query || ' AND PM.BRANCHID =' || CAST(v_branchid AS VARCHAR(20));
  END IF;
  IF (v_mprid > 0) THEN
  v_query := v_query || ' AND PM.MPRID =' || CAST(v_mprid AS VARCHAR(20));
  END IF;
  IF (v_sprid > 0) THEN
  v_query := v_query || ' AND SM.SPRID =' || CAST(v_sprid AS VARCHAR(20));
  END IF;
  IF (v_cat_code <> '') THEN
  v_catecode := 0;
  SELECT catid INTO v_catecode FROM tbl_category WHERE cat_code = v_cat_code;
  IF (v_catecode > 0) THEN
  v_query := v_query || ' AND PM.CATID =' || CAST(v_catecode AS VARCHAR(20));
  ELSE
  SELECT subcatid INTO v_catecode FROM tbl_sub_category WHERE sub_cat_code = v_cat_code;
  v_query := v_query || ' AND PM.SUBCATEGORYID =' || CAST(v_catecode AS VARCHAR(20));
  END IF;
  END IF;
  IF (v_isverfied >= 0) THEN
  v_query := v_query || ' AND SM.ismerchantstatus =' || CAST(5 AS VARCHAR(20));
  END IF;
  v_query := v_query || ' ORDER BY  PM.MPRID DESC ';
  EXECUTE v_query;
  RETURN QUERY SELECT * FROM tmp_productlisttemp WHERE rownumber BETWEEN v_minindex AND v_maxindex;
  SELECT COUNT(rownumber) INTO v_totalcount FROM tmp_productlisttemp;
  DROP TABLE IF EXISTS tmp_productlisttemp;
  -- SET option (removed)
END;
$$;


--
-- Name: usp_getarealistoncity(text); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_getarealistoncity(v_ctid text DEFAULT '-8'::text) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
BEGIN
  RETURN QUERY SELECT aid, (areaname || '(' || pincode || ')') AS areaname FROM area_master WHERE cactive = 1 AND ctid IN (v_ctid) ORDER BY areaname ASC NULLS FIRST;
END;
$$;


--
-- Name: usp_getarealistonmultiplecity(text); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_getarealistonmultiplecity(v_ctid text) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
BEGIN
  RETURN QUERY SELECT am.aid, (am.areaname || '(' || am.pincode || ')') AS areaname, c.cityname FROM area_master AS am, city AS c WHERE am.ctid = c.ctid AND am.cactive = 1 AND am.ctid IN (SELECT value FROM dbo.SPLITSTRINGBYCOMMA(v_ctid)) ORDER BY c.cityname ASC NULLS FIRST;
END;
$$;


--
-- Name: usp_getatributorlist_mobile(integer, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_getatributorlist_mobile(v_subcatid integer DEFAULT 1570, v_mode integer DEFAULT 1) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_query12 varchar(5000);
  v_query13 varchar(5000);
  v_count int;
  v_addattributeget varchar(300);
  v_title1 varchar(50);
BEGIN
  IF (v_mode = 2) THEN
  RETURN QUERY SELECT DISTINCT title FROM ims_masterproductattribute WHERE subcatid = v_subcatid;
  ELSE
  v_query12 := '';
  v_query13 := '';
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp (title varchar(50),subcatid bigint) ON COMMIT DROP;
  v_query12 := 'insert into #temp select  distinct title,subcatid from IMS_MASTERPRODUCTATTRIBUTE  where subcatid=' || CAST(v_subcatid AS VARCHAR(10)) || ' and IsActive=1 ';
  EXECUTE v_query12;
  DROP TABLE IF EXISTS tmp_tempaqw;
  CREATE TEMP TABLE tmp_tempaqw (title varchar(50),rowNumber int) ON COMMIT DROP;
  v_query13 := 'insert into #tempaqw select  title,ROW_NUMBER() over (order by title asc) as rowNumber from #temp where subcatid=' || CAST(v_subcatid AS VARCHAR(10)) || '';
  EXECUTE v_query13;
  v_count := 0;
  v_addattributeget := '';
  v_title1 := '';
  SELECT COUNT(1) INTO v_count FROM tmp_tempaqw;
  WHILE (v_count > 0) LOOP
  SELECT title INTO v_title1 FROM tmp_tempaqw WHERE rownumber = v_count;
  RETURN QUERY SELECT DISTINCT title, value FROM ims_masterproductattribute WHERE title = v_title1 AND isactive = 1 AND value <> '0' AND value <> '' AND subcatid = v_subcatid;
  v_count := v_count - 1;
  END LOOP;
  DROP TABLE IF EXISTS tmp_temp;
  DROP TABLE IF EXISTS tmp_tempaqw;
  END IF;
END;
$$;


--
-- Name: usp_getattributebycatid(integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_getattributebycatid(v_catid integer DEFAULT 0) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
BEGIN
  RETURN QUERY SELECT DISTINCT CAST(0 AS BIGINT) AS mpaid, CAST(0 AS BIGINT) AS sprid, title, value, showongrid, position, isactive, catid, awcid, subcatid FROM ims_masterproductattribute WHERE isactive = 1 AND subcatid IN (SELECT catid FROM tbl_sub_category WHERE catid = v_catid);
END;
$$;


--
-- Name: usp_getattributebymaincatid(integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_getattributebymaincatid(v_maincatid integer DEFAULT 1012) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
BEGIN
  RETURN QUERY SELECT DISTINCT CAST(0 AS BIGINT) AS mpaid, CAST(0 AS BIGINT) AS sprid, title, value, showongrid, position, isactive, catid, awcid, subcatid FROM ims_masterproductattribute WHERE isactive = 1 AND catid IN (SELECT catid FROM tbl_category WHERE maincatid = v_maincatid) AND value <> '';
END;
$$;


--
-- Name: usp_getattributebysubcatid(integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_getattributebysubcatid(v_subcatid integer DEFAULT 1570) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
BEGIN
  RETURN QUERY SELECT DISTINCT CAST(0 AS BIGINT) AS mpaid, CAST(0 AS BIGINT) AS sprid, title, value, showongrid, position, isactive, catid, awcid, subcatid FROM ims_masterproductattribute WHERE isactive = 1 AND subcatid = v_subcatid AND value <> '' AND value = LTRIM(RTRIM(value));
END;
$$;


--
-- Name: usp_getattributebysubcatid_mobile(integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_getattributebysubcatid_mobile(v_subcatid integer DEFAULT 42) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
BEGIN
  RETURN QUERY SELECT DISTINCT CAST(0 AS BIGINT) AS mpaid, CAST(0 AS BIGINT) AS sprid, title, value, showongrid, position, isactive, catid, awcid, subcatid FROM ims_masterproductattribute WHERE isactive = 1 AND subcatid = v_subcatid;
END;
$$;


--
-- Name: usp_getattributelist(integer, integer, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_getattributelist(v_maincatid integer DEFAULT 1, v_catid integer DEFAULT 9, v_subcatid integer DEFAULT 11) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
BEGIN
  RETURN QUERY SELECT ddl_id, parent_ddl_id, ddl_name, ddl_name_id, ddl_text, ddl_value, isactive, create_date, maincategoryid, subcategoryid, categoryid FROM tbl_ddl_master AS ddm LEFT JOIN tbl_main_category AS mcat ON mcat.maincatid = ddm.maincategoryid LEFT JOIN tbl_category AS cat ON cat.catid = ddm.categoryid LEFT JOIN tbl_sub_category AS scat ON scat.subcatid = ddm.subcategoryid WHERE mcat.maincatid = v_maincatid OR mcat.maincatid IN (SELECT maincatid FROM tbl_category WHERE catid = v_catid) OR mcat.maincatid IN (SELECT maincatid FROM tbl_sub_category WHERE subcatid = v_subcatid);
  RETURN QUERY SELECT ddl_id, parent_ddl_id, ddl_name, ddl_name_id, ddl_text FROM tbl_ddl_master AS ddm LEFT JOIN tbl_main_category AS mcat ON mcat.maincatid = ddm.maincategoryid LEFT JOIN tbl_category AS cat ON cat.catid = ddm.categoryid LEFT JOIN tbl_sub_category AS scat ON scat.subcatid = ddm.subcategoryid WHERE mcat.maincatid = v_maincatid OR mcat.maincatid IN (SELECT maincatid FROM tbl_category WHERE catid = v_catid) OR mcat.maincatid IN (SELECT maincatid FROM tbl_sub_category WHERE subcatid = v_subcatid);
END;
$$;


--
-- Name: usp_getattributelistbycategory(character varying, integer, character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_getattributelistbycategory(v_type character varying DEFAULT 'subcat'::character varying, v_id integer DEFAULT 1380, v_cat_name character varying DEFAULT ''::character varying) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_subcatid int;
  v_catid int;
  v_maincatid int;
BEGIN
  IF (v_type = 'mcat') THEN
  RETURN QUERY SELECT awct_id, main_cat_id, sub_cat_id, cat_id, att_name, att_type, ddl_id, default_value, sr_no, is_active, ismendatory, issearch, isselectiveattr FROM tbl_attributes_with_category WHERE main_cat_id = v_id AND cat_id = 0 AND sub_cat_id = 0 AND is_active = 1;
  END IF;
  IF (v_type = 'cat') THEN
  SELECT maincatid INTO v_maincatid FROM tbl_category WHERE catid = v_id;
  RETURN QUERY SELECT awct_id, main_cat_id, sub_cat_id, cat_id, att_name, att_type, ddl_id, default_value, sr_no, is_active, ismendatory, issearch, isselectiveattr FROM tbl_attributes_with_category WHERE ((cat_id = v_id AND sub_cat_id = 0 AND main_cat_id = v_maincatid) OR (main_cat_id = v_maincatid AND cat_id = 0 AND sub_cat_id = 0)) AND is_active = 1;
  END IF;
  IF (v_type = 'subcat') THEN
  SELECT maincatid, catid INTO v_maincatid, v_catid FROM dbo.tbl_sub_category WHERE subcatid = v_id;
  RETURN QUERY SELECT awct_id, main_cat_id, sub_cat_id, cat_id, att_name, att_type, ddl_id, default_value, sr_no, is_active, ismendatory, issearch, isselectiveattr FROM tbl_attributes_with_category WHERE ((sub_cat_id = v_id OR (cat_id = v_catid AND sub_cat_id = 0)) OR (main_cat_id = v_maincatid AND cat_id = 0 AND sub_cat_id = 0)) AND is_active = 1;
  END IF;
END;
$$;


--
-- Name: usp_getattributor_alllist_mobile(integer, integer, integer, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_getattributor_alllist_mobile(v_mode integer DEFAULT 1, v_maincatid integer DEFAULT 1011, v_catid integer DEFAULT 1053, v_subcatid integer DEFAULT 1371) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_query12 text;
  v_query13 varchar(5000);
  v_getddl_id text;
  v_count int;
  v_addattributeget varchar(300);
  v_title1 varchar(50);
  v_ddid int;
  v_datacount int;
  v_getcontent text;
BEGIN
  IF (v_mode = 2) THEN
  RETURN QUERY SELECT DISTINCT title FROM ims_masterproductattribute;
  ELSE
  v_query12 := '';
  v_query13 := '';
  v_getddl_id := '';
  SELECT COALESCE(v_getddl_id || ',', '') || CAST(ddl_id AS VARCHAR) INTO v_getddl_id FROM tbl_attributes_with_category WHERE main_cat_id = v_maincatid AND cat_id = v_catid AND sub_cat_id = v_subcatid;
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp (title varchar(50)) ON COMMIT DROP;
  v_query12 := 'insert into #temp select distinct (NAME) as title from TBL_DROPDOWN where status=1 and ddid in (select * from SplitString(''' || v_getddl_id || ''','',''))';
  EXECUTE v_query12;
  DROP TABLE IF EXISTS tmp_tempaqw;
  CREATE TEMP TABLE tmp_tempaqw (title varchar(50),rowNumber int) ON COMMIT DROP;
  v_query13 := 'insert into #tempaqw select  title,ROW_NUMBER() over (order by title asc) as rowNumber from #temp where title !=''''';
  EXECUTE v_query13;
  v_count := 0;
  v_addattributeget := '';
  v_title1 := '';
  v_ddid := 0;
  v_datacount := 0;
  v_getcontent := '';
  SELECT COUNT(1) INTO v_count FROM tmp_tempaqw;
  WHILE (v_count > 0) LOOP
  SELECT title INTO v_title1 FROM tmp_tempaqw WHERE rownumber = v_count;
  SELECT ddid INTO v_ddid FROM tbl_dropdown WHERE name = v_title1 AND status = 1 LIMIT 1;
  IF (v_ddid > 0) THEN
  SELECT COALESCE(COUNT(1), 0) INTO v_datacount FROM ims_masterproductattribute WHERE catid = v_catid AND subcatid = v_subcatid AND title = v_title1 AND value <> '';
  IF (v_datacount > 0) THEN
  IF (v_title1 <> '') THEN
  DROP TABLE IF EXISTS tmp_temp12;
  CREATE TEMP TABLE tmp_temp12 ON COMMIT DROP AS SELECT DISTINCT value FROM ims_masterproductattribute WHERE catid = v_catid AND subcatid = v_subcatid AND title = v_title1 AND value <> '';
  END IF;
  IF (v_title1 <> '') THEN
  RETURN QUERY SELECT LTRIM(v_title1) AS title, LTRIM(value) AS value FROM tmp_temp12 WHERE value <> '';
  END IF;
  v_getcontent := '';
  v_datacount := 0;
  DROP TABLE IF EXISTS tmp_temp12;
  END IF;
  END IF;
  v_count := v_count - 1;
  END LOOP;
  DROP TABLE IF EXISTS tmp_temp;
  DROP TABLE IF EXISTS tmp_tempaqw;
  END IF;
END;
$$;


--
-- Name: usp_getavailableadpoints(character varying, character varying, integer, integer, integer, integer, integer, character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_getavailableadpoints(v_loginid character varying, v_password character varying, v_cid integer, v_ctid integer, v_catid integer, v_scatid integer, INOUT v_currentpoints integer, INOUT v_strresult character varying) RETURNS record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_plid bigint;
  v_cidtemp int;
  v_currency varchar(10);
BEGIN
  -- BEGIN TRAN (removed)
  v_plid := 0;
  v_currentpoints := 0;
  SELECT plid, COALESCE(cid, 0), currency INTO v_plid, v_cidtemp, v_currency FROM portal_login WHERE loginid = v_loginid AND password = v_password;
  IF (v_plid = 0) THEN
  v_strresult := 'error^Invalid Id or Password';
  -- COMMIT (removed)
  RETURN;
  END IF;
  IF (v_cidtemp <> v_cid) THEN
  v_strresult := 'error^Invalid Id or Password for current country';
  -- COMMIT (removed)
  RETURN;
  END IF;
  IF (v_scatid > 0) THEN
  SELECT catid INTO v_catid FROM product_subcategory WHERE scatid = v_scatid;
  END IF;
  SELECT COALESCE(remain_ads, 0) INTO v_currentpoints FROM tbl_memberadsdetails WHERE plid = v_plid AND ctid = v_ctid AND catid = v_catid;
  v_strresult := 'success^' || CAST(v_currentpoints AS VARCHAR(20));
  IF (0 <> 0) THEN
  v_strresult := 'error^some error occured';
  END IF;
  -- COMMIT (removed)
END;
$$;


--
-- Name: usp_getblogreviewsandcomments(character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_getblogreviewsandcomments(v_blogid character varying) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_count INT;
  v_count1 INT;
  v_rwid INT;
  v_countrev INT;
  v_totalstar INT;
  v_avgrate INT;
BEGIN
  DROP TABLE IF EXISTS tmp_tempdetailsall;
  CREATE TEMP TABLE tmp_tempdetailsall (ROWNUMBER INT GENERATED BY DEFAULT AS IDENTITY,

RCID INT,

NAME VARCHAR(200),

TITLE VARCHAR(100),

RCDESC text,

RORC VARCHAR(10),

RATE INT,

TOTALREVIEWS INT,

AVGRATE INT,

DATE VARCHAR(100)) ON COMMIT DROP;
  SELECT COUNT(rwid) INTO v_countrev FROM tbl_blogreviewmaster WHERE blogid = v_blogid AND status = 1;
  SELECT COALESCE(SUM(stars), 0) INTO v_totalstar FROM tbl_blogreviewmaster WHERE blogid = v_blogid AND status = 1;
  IF (v_countrev = 0) THEN
  v_avgrate := 0;
  END IF;
  IF (v_countrev > 0) THEN
  v_avgrate := v_totalstar / v_countrev;
  END IF;
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp ON COMMIT DROP AS SELECT ROW_NUMBER() OVER (ORDER BY date ASC NULLS FIRST) AS r1, rwid, CAST(name AS VARCHAR(200)) AS name, CAST(reviewtitle AS VARCHAR(200)) AS reviewtitle, CAST(reviewdesc AS text) AS reviewdesc, stars, CAST(TO_CHAR(date, 'TMMon DD YYYY FMHH12:MI%p') AS VARCHAR(100)) AS date FROM tbl_blogreviewmaster WHERE status = 1 AND blogid = v_blogid ORDER BY date ASC NULLS FIRST;
  v_count := 1;
  SELECT COUNT(rwid) INTO v_count1 FROM tmp_temp;
  WHILE (v_count <= v_count1) LOOP
  INSERT INTO tmp_tempdetailsall SELECT rwid, name, reviewtitle, reviewdesc, 'R', stars, v_countrev, v_avgrate, date FROM tmp_temp WHERE r1 = v_count;
  SELECT rwid INTO v_rwid FROM tmp_temp WHERE r1 = v_count;
  INSERT INTO tmp_tempdetailsall SELECT cmid, name, '', comment, 'C', 0, v_countrev, v_avgrate, CAST(TO_CHAR(date, 'TMMon DD YYYY FMHH12:MI%p') AS VARCHAR(100)) AS date FROM tbl_blogcommentswithreview WHERE status = 1 AND rwid = v_rwid ORDER BY date ASC NULLS FIRST;
  v_count := v_count + 1;
  END LOOP;
  DROP TABLE IF EXISTS tmp_temp;
  RETURN QUERY SELECT * FROM tmp_tempdetailsall;
  DROP TABLE IF EXISTS tmp_tempdetailsall;
END;
$$;


--
-- Name: usp_getbranch(); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_getbranch() RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_rowcount INT;
  v_start INT;
  v_bremp INT;
  v_brcod VARCHAR(20);
BEGIN
  v_start := 1;
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp ON COMMIT DROP AS SELECT brcode, brname, 0 AS empcount FROM tbl_branch_master;
  DROP TABLE IF EXISTS tmp_tempempbr;
  CREATE TEMP TABLE tmp_tempempbr ON COMMIT DROP AS SELECT ROW_NUMBER() OVER (ORDER BY brcode NULLS FIRST) AS rownumber, COUNT(emp_id) AS empcount, brcode FROM tbl_employee_master GROUP BY brcode;
  SELECT rownumber INTO v_rowcount FROM tmp_tempempbr;
  WHILE v_start <= v_rowcount LOOP
  SELECT empcount, brcode INTO v_bremp, v_brcod FROM tmp_tempempbr WHERE rownumber = v_start;
  UPDATE tmp_temp SET empcount = v_bremp WHERE brcode = v_brcod;
  v_start := v_start + 1;
  END LOOP;
  RETURN QUERY SELECT * FROM tmp_temp;
  DROP TABLE IF EXISTS tmp_temp;
  DROP TABLE IF EXISTS tmp_tempempbr;
END;
$$;


--
-- Name: usp_getbranchlist(character varying, character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_getbranchlist(v_brcode character varying, v_mode character varying) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF (v_mode = 'all') THEN
  RETURN QUERY SELECT bm.brid, bm.brcode, bm.brname, bm.statename, cm.com_title, bm.braddress, bm.com_code, bt.brtype_name, bm.brtid, COALESCE(bm.current_balance, 0) AS current_balance FROM tbl_branch_master AS bm LEFT JOIN tbl_branch_type AS bt ON bm.brtid = bt.brtid LEFT JOIN tbl_companymaster AS cm ON bm.com_code = cm.com_code WHERE COALESCE(bm.active, 1) = 1 ORDER BY bm.brid ASC NULLS FIRST;
  END IF;
  IF (v_mode = 'brwise') THEN
  RETURN QUERY SELECT bm.brid, bm.brcode, bm.brname, bm.statename, cm.com_title, bm.braddress, bm.com_code, bt.brtype_name, bm.brtid, COALESCE(bm.current_balance, 0) AS current_balance FROM tbl_branch_master AS bm LEFT JOIN tbl_branch_type AS bt ON bm.brtid = bt.brtid LEFT JOIN tbl_companymaster AS cm ON bm.com_code = cm.com_code WHERE bm.brcode = v_brcode AND COALESCE(bm.active, 1) = 1 ORDER BY bm.brid ASC NULLS FIRST;
  END IF;
  IF (v_mode = 'dumplist') THEN
  RETURN QUERY SELECT bm.brid, bm.brcode, bm.brname, bm.statename, cm.com_title, bm.braddress, bm.com_code, bt.brtype_name, bm.brtid, COALESCE(bm.current_balance, 0) AS current_balance FROM tbl_branch_master AS bm LEFT JOIN tbl_branch_type AS bt ON bm.brtid = bt.brtid LEFT JOIN tbl_companymaster AS cm ON bm.com_code = cm.com_code WHERE COALESCE(bt.is_add_stock_from_vendor, 0) = 1 AND COALESCE(bm.active, 1) = 1 ORDER BY bm.brid ASC NULLS FIRST;
  END IF;
END;
$$;


