--
-- Name: usp_getcanonical_list(integer, integer, character varying, character varying, character varying, character varying, character varying, text, text, character varying, character varying, character varying, integer, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_getcanonical_list(v_startrowindex integer DEFAULT 0, v_maxrows integer DEFAULT 0, v_orderbyfield character varying DEFAULT NULL::character varying, v_searchfield character varying DEFAULT NULL::character varying, v_searchvalue character varying DEFAULT NULL::character varying, v_cid character varying DEFAULT ''::character varying, v_ctid character varying DEFAULT ''::character varying, v_catid text DEFAULT ''::text, v_keyid text DEFAULT ''::text, v_fromdate character varying DEFAULT ''::character varying, v_todate character varying DEFAULT ''::character varying, v_type character varying DEFAULT ''::character varying, v_pageno integer DEFAULT 1, v_pagesize integer DEFAULT 30) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_recordcount int;
  v_regno bigint;
  v_pmid int;
  v_isroll varchar(50);
  v_minindex int;
  v_maxindex int;
  v_sqlquery text;
BEGIN
  -- SET option (removed)
  v_minindex := 0;
  v_maxindex := 0;
  v_minindex := ((v_pageno - 1) * v_pagesize) + 1;
  v_maxindex := (v_pageno * v_pagesize);
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp (rowNumber bigint,
pmid bigint,
canonicalUrl text,
canonicalUrlformobile text) ON COMMIT DROP;
  v_sqlquery := '';
  v_sqlquery := ' insert into #temp select ROW_NUMBER() OVER(ORDER BY PM.pmid desc) as rowNumber,PM.pmid,
 lower(''http://qlook.bz/business-details/''+replace(replace(replace(replace(replace(replace(replace(REPLACE(rtrim(ltrim(replace (PM.title,''.'','''')))+'' ''+
 rtrim(ltrim(PC.CatName))+'' in ''+rtrim(ltrim(ct.cityName)) +''-in-''+ rtrim(ltrim(C.countryName))+''-''+
 CONVERT(varchar(50), PM.pmid),'' '',''-''),''&'',''and''),''/'',''-''),''|'',''-''),''#'',''-''),''*'',''-''),'':'',''-''),''+'',''plus'')) as companyname,
 lower(''http://m.qlook.bz/business-details/''+replace(replace(replace(replace(replace(replace(replace(REPLACE(rtrim(ltrim(replace (PM.title,''.'','''')))+'' ''+
 rtrim(ltrim(PC.CatName))+'' in ''+rtrim(ltrim(ct.cityName)) +''-in-''+ rtrim(ltrim(C.countryName))+''-''+
 CONVERT(varchar(50), PM.pmid),'' '',''-''),''&'',''and''),''/'',''-''),''|'',''-''),''#'',''-''),''*'',''-''),'':'',''-''),''+'',''plus'')) as companyname
 from portal_master PM left join country C on pm.cid=c.CID
 left join Portal_Login PL  on pl.pmid=PM.Pmid
 left join CITY ct on PM.ctid=CT.CTID 
 left join Product_Category PC ON PC.catId= CONVERT (int, SUBSTRING((PM.catid+'',''),0,Convert(int,CHARINDEX('','',(PM.catid+'','')))))  
 where isnull(PM.pmid,0)>0 and isnull(PM.title,'''')<>'''' and isnull(PC.CatName,'''')<>'''' and isnull(ct.cityName,'''')<>'''' 
 and isnull(C.countryName,'''')<>'''' and isnull(PM.isverified,0)=1 ';
  IF (v_cid <> '') THEN
  v_sqlquery := v_sqlquery || (' and convert(varchar(100),PM.cid)=' || CAST(v_cid AS VARCHAR(100)) || ' ');
  END IF;
  IF (v_ctid <> '') THEN
  v_sqlquery := v_sqlquery || (' and ((convert(varchar(100),PM.ctid)=' || CAST(v_ctid AS VARCHAR(100)) || ') or 
	                     ('',''+ISNULL(PM.subctid,'''')+'','' like ''%,' || CAST(v_ctid AS text) || ',%'')) ');
  END IF;
  IF (v_catid <> '') THEN
  v_sqlquery := v_sqlquery || (' and (('',''+ISNULL(PM.catid,'''')+'','' like ''%,' || CAST(v_catid AS text) || ',%'') or 
	                     ('',''+ISNULL(PM.subcatid,'''')+'','' like ''%,' || CAST(v_catid AS text) || ',%'')) ');
  END IF;
  IF (v_keyid <> '') THEN
  v_sqlquery := v_sqlquery || (' and (('',''+ISNULL(PM.keyid,'''')+'','' like ''%,' || CAST(v_keyid AS text) || ',%'') or 
	                     ('',''+ISNULL(PM.subkeyid,'''')+'','' like ''%,' || CAST(v_keyid AS text) || ',%'')) ');
  END IF;
  IF (v_fromdate = '' OR v_todate = '') THEN
  IF (v_fromdate <> '') THEN
  v_sqlquery := v_sqlquery || ' and (convert(date, PM.doc,103)>=convert(date,''' || v_fromdate || ''',103)) ';
  END IF;
  IF (v_todate <> '') THEN
  v_sqlquery := v_sqlquery || ' and (convert(date, PM.doc,103)<=convert(date,''' || v_todate || ''',103)) ';
  END IF;
  END IF;
  IF (v_fromdate <> '' AND v_todate <> '') THEN
  v_sqlquery := v_sqlquery || '  and (convert(date, PM.doc,103)  between  convert(date,''' || v_fromdate || ''',103)  and convert(date,''' || v_todate || ''',103)) ';
  END IF;
  IF (v_searchfield = 'loginid') THEN
  v_sqlquery := v_sqlquery || ' and pl.loginid like ''%' || v_searchvalue || '%'' ';
  END IF;
  IF (v_searchfield = 'companyname') THEN
  v_sqlquery := v_sqlquery || ' and pm.companyname like ''%' || v_searchvalue || '%'' ';
  END IF;
  IF (v_searchfield = 'pmid') THEN
  v_sqlquery := v_sqlquery || ' and pm.pmid like ''%' || v_searchvalue || '%'' ';
  END IF;
  v_sqlquery := v_sqlquery || ' ORDER BY PM.pmid desc ';
  EXECUTE v_sqlquery;
  SELECT COUNT(*) INTO v_recordcount FROM tmp_temp;
  RETURN QUERY SELECT * FROM tmp_temp WHERE rownumber BETWEEN v_minindex AND v_maxindex ORDER BY rownumber ASC NULLS FIRST;
  RETURN QUERY SELECT v_recordcount AS recordcount;
  DROP TABLE IF EXISTS tmp_temp;
  -- SET option (removed)
END;
$$;


--
-- Name: usp_getcartlist_mobile(integer, integer, character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_getcartlist_mobile(v_clid integer DEFAULT 0, v_did integer DEFAULT 0, v_sessionid character varying DEFAULT ''::character varying) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_dynamicurl varchar(100);
BEGIN
  v_dynamicurl := '';
  SELECT merchantimagepath INTO v_dynamicurl FROM tbl_company;
  RETURN QUERY SELECT ROW_NUMBER() OVER (ORDER BY twl.clid DESC NULLS LAST) AS rownumber, pmm.producttitle, pmm.shotdescription, CASE WHEN POSITION('^' IN pms.productimages) > 0 THEN (LEFT(CAST(v_dynamicurl || pms.productimages AS TEXT), POSITION('^' IN v_dynamicurl || pms.productimages) + 0)) ELSE v_dynamicurl || pms.productimages || '^' END AS productimages, (pms.dap) AS dap, twl.sprid, COALESCE(dcs.bv, 0) AS bv, COALESCE(dcs.cashback, 0) AS cashback, v_did AS did, pms.discountpercentage, pms.sellmrp, twl.qty, (pms.shippingcharges) AS shippingcharges, vc.vatpercvalue, (((pms.dap) * vc.vatpercvalue) / 100) AS gst, ((((pms.dap) * vc.vatpercvalue) / 100) + (pms.dap) + (pms.shippingcharges)) AS total, twl.sessionid, (SELECT value FROM ims_masterproductattribute WHERE sprid = pms.sprid AND title = 'Color') AS color, (SELECT value FROM ims_masterproductattribute WHERE sprid = pms.sprid AND title = 'Size') AS size, twl.tatcid FROM ims_subproduct AS pms INNER JOIN ims_masterproduct AS pmm ON pms.mprid = pmm.mprid INNER JOIN tbl_addtocart AS twl ON twl.sprid = pms.sprid AND twl.status = 1 LEFT JOIN tbl_vat_categories AS vc ON vc.vcid = pms.vatcategoryid LEFT OUTER JOIN tbl_sub_category AS tsb ON pmm.subcategoryid = tsb.subcatid LEFT OUTER JOIN tbl_distributor_commission_structure AS dcs ON dcs.subsubcatid = tsb.subcatid AND dcs.did = v_did WHERE twl.status = 1 AND (twl.clid = v_clid OR twl.sessionid = v_sessionid) ORDER BY twl.tatcid DESC NULLS LAST;
END;
$$;


--
-- Name: usp_getcatandkey_selected(text, text); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_getcatandkey_selected(v_catid text, v_keyid text) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
BEGIN
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp (rownumber int GENERATED BY DEFAULT AS IDENTITY,
			productname varchar(100), 
			producttype char,
			catid int,
			kmid int) ON COMMIT DROP;
  INSERT INTO tmp_temp (productname, producttype, catid, kmid) SELECT LOWER(catname), 'c', catid, 0 FROM product_category WHERE catactive = 1 AND catid IN (SELECT value FROM dbo.SPLITSTRINGBYCOMMA(v_catid));
  INSERT INTO tmp_temp (productname, producttype, catid, kmid) SELECT LOWER(keywordname), 'k', catid, kmid FROM keyword_master WHERE kactive = 1 AND kmid IN (SELECT value FROM dbo.SPLITSTRINGBYCOMMA(v_keyid));
  RETURN QUERY SELECT productname, producttype, (CASE WHEN producttype = 'c' THEN catid WHEN producttype = 'k' THEN kmid END) AS prid, catid, kmid FROM tmp_temp ORDER BY catid NULLS FIRST, producttype ASC NULLS FIRST;
  DROP TABLE IF EXISTS tmp_temp;
END;
$$;


--
-- Name: usp_getcategorylist(); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_getcategorylist() RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_ulr varchar(150);
BEGIN
  v_ulr := '';
  SELECT mainimagepath INTO v_ulr FROM tbl_company;
  RETURN QUERY SELECT maincatid, maincatname, v_ulr || category_icon AS icon, (v_ulr || main_cat_imgname) AS imageicon, totalactive FROM tbl_main_category WHERE status = 1 AND totalactive > 0;
END;
$$;


--
-- Name: usp_getcitystate(integer, character varying, character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_getcitystate(v_cid integer DEFAULT 96, v_city character varying DEFAULT 'Noida'::character varying, v_state character varying DEFAULT 'Uttar Pradesh'::character varying) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_citystate VARCHAR(200);
  v_ctid INT;
  v_sid INT;
BEGIN
  v_citystate := '';
  IF (v_cid = 96) THEN
  IF (v_city IN ('delhi', 'new delhi', 'old delhi')) THEN
  v_city := 'New Delhi';
  END IF;
  IF (v_city IN ('New Delhi', 'delhi', 'old delhi', 'Noida', 'Ghaziabad', 'Faridabad', 'Gurgaon', 'Greater Noida')) THEN
  v_state := 'Delhi/NCR';
  END IF;
  END IF;
  IF EXISTS(SELECT 1 FROM state WHERE statename = v_state AND sactive = 1 AND cid = v_cid) THEN
  SELECT sid INTO v_sid FROM state WHERE statename = v_state AND sactive = 1 AND cid = v_cid;
  IF EXISTS(SELECT 1 FROM city WHERE cityname = v_city AND sid = v_sid AND cid = v_cid AND active = 1) THEN
  v_citystate := v_city || ',' || v_state;
  END IF;
  END IF;
  RETURN QUERY SELECT v_citystate;
END;
$$;


--
-- Name: usp_getcommissionreport(integer, bigint, integer, integer, integer, integer, character varying, character varying, character varying, character varying, character varying, character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_getcommissionreport(v_mode integer DEFAULT 1, v_plid bigint DEFAULT 0, v_recordcount integer DEFAULT 0, v_intresult integer DEFAULT 0, v_startrowindex integer DEFAULT 1, v_maxrows integer DEFAULT 1000, v_catname character varying DEFAULT ''::character varying, v_subcatname character varying DEFAULT ''::character varying, v_orderby character varying DEFAULT ''::character varying, v_searchsubsubcategory character varying DEFAULT ''::character varying, v_searchsubcategory character varying DEFAULT ''::character varying, v_searchcategory character varying DEFAULT ' '::character varying) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_category text;
  v_subcategory text;
  v_query text;
  v_minindex INT;
  v_maxindex INT;
  v_query1 text;
BEGIN
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp (ROWNUMBER BIGINT GENERATED BY DEFAULT AS IDENTITY ,
	CATNAME varchar(500),
	SUBCATNAME varchar(500),
	ADMINCHARGE DECIMAL(10,2),
	DELIEVERYCHARGE DECIMAL(10,2),
	HANDLINGCHARGE DECIMAL(10,2),
	FixedFee DECIMAL(10,2),
	SubSubCatName varchar(500),
	SUBCATID int,
	BVPER DECIMAL(10,2),
	cashback_Per DECIMAL(10,2),
	newbv DECIMAL(10,2),
	newcashback DECIMAL(10,2),
	return int,
	REFUND int,
	EXCHANGE int) ON COMMIT DROP;
  v_category := '';
  v_subcategory := '';
  v_query := '';
  IF (v_mode = 1) THEN
  v_minindex := (v_startrowindex - 1) * v_maxrows + 1;
  v_maxindex := v_startrowindex * v_maxrows;
  IF (v_plid > 0) THEN
  SELECT subcategory INTO v_subcategory FROM tbl_merchantcat_subcat_keywordmaster WHERE plid = v_plid AND isactive = 1 AND isdeleted = 0;
  END IF;
  IF (v_subcategory = '') THEN
  v_subcategory := 0;
  ELSE
  v_subcategory := v_subcategory;
  END IF;
  v_query := 'INSERT INTO #TEMP SELECT  TMC.MAINCATNAME,TC.CATNAME,ISNULL(km.ADMINCHARGE,0) AS ADMINCHARGE,ISNULL(km.DELIEVERYCHARGE,0) AS DELIEVERYCHARGE,
	ISNULL(km.HANDLINGCHARGE,0) AS HANDLINGCHARGE,ISNULL(km.FixedFee,0) AS FixedFee,(km.SubCatName)AS SubSubCatName,ISNULL(km.SUBCATID,0) AS SUBCATID,
	ISNULL(km.BVPER,0) AS BVPER ,ISNULL(km.cashback_Per,0) AS cashback_Per, isnull(tcs.bv,0) as newbv,isnull(tcs.cashback,0) as newcashback
	,ISNULL(km.[RETURN],0) as [RETURN],ISNULL(km.REFUND,0) as REFUND,ISNULL(km.EXCHANGE,0) as EXCHANGE  FROM 
	TBL_MAIN_CATEGORY TMC INNER JOIN TBL_CATEGORY TC ON TMC.MAINCATID = TC.MAINCATID 
    inner join 	tbl_sub_category km on TC.CatId=km.CatId
	left join tbl_Distributor_Commission_Structure tcs on tcs.SubSubCatID= km.SUBCATID
	 WHERE TC.STATUS=1 AND TMC.STATUS = 1 and km.catid in (' || v_subcategory || ')';
  IF (v_searchsubsubcategory <> '') THEN
  v_searchsubsubcategory := REPLACE(v_searchsubsubcategory, '', '');
  v_query := v_query || 'AND km.subcatname=''' || v_searchsubsubcategory || '''';
  END IF;
  IF (v_searchsubcategory <> '') THEN
  v_searchsubcategory := REPLACE(v_searchsubcategory, '''', '''''');
  v_query := v_query || 'AND TC.CATNAME =''' || v_searchsubcategory || '''';
  END IF;
  IF (v_searchcategory <> '') THEN
  v_searchcategory := REPLACE(v_searchcategory, '''', '''''');
  v_query := v_query || 'AND TMC.MAINCATNAME =''' || v_searchcategory || '''';
  END IF;
  RAISE NOTICE '%', v_query;
  EXECUTE v_query;
  RETURN QUERY SELECT * FROM tmp_temp WHERE rownumber IN (SELECT MIN(rownumber) FROM tmp_temp GROUP BY subcatid) AND rownumber BETWEEN v_minindex AND v_maxindex;
  SELECT COUNT(1) INTO v_recordcount FROM tmp_temp;
  DROP TABLE IF EXISTS tmp_temp;
  END IF;
  IF (v_mode = 2) THEN
  v_query := 'INSERT INTO #TEMP SELECT TMC.MAINCATNAME,TC.CATNAME,ISNULL(km.ADMINCHARGE,0) AS ADMINCHARGE,ISNULL(km.DELIEVERYCHARGE,0) AS DELIEVERYCHARGE,
	ISNULL(km.HANDLINGCHARGE,0) AS HANDLINGCHARGE,ISNULL(km.FixedFee,0) AS FixedFee, (km.SubCatName)AS SubSubCatName FROM TBL_MAIN_CATEGORY TMC INNER JOIN TBL_CATEGORY TC ON TMC.MAINCATID = TC.MAINCATID 
	inner join 	tbl_sub_category km on TC.MAINCATID=km.MainCatId WHERE 
	TC.STATUS=1 AND TMC.STATUS = 1 ';
  IF (v_catname <> '') THEN
  v_query := v_query || (' AND TMC.MAINCATNAME LIKE ''%' || v_catname || '%''');
  END IF;
  IF (v_subcatname <> '') THEN
  v_query := v_query || (' AND TC.CATNAME LIKE ''%' || v_subcatname || '%''');
  END IF;
  RETURN QUERY SELECT v_query;
  EXECUTE v_query;
  v_query1 := '';
  v_query1 := v_query1 || ('SELECT * FROM #TEMP WHERE ROWNUMBER BETWEEN ''' || CAST(v_startrowindex AS VARCHAR) || ''' AND ''' || CAST(v_maxrows AS VARCHAR) || ''' ');
  IF (v_orderby <> '') THEN
  IF (v_orderby = 'ADMINCHARGEASC') THEN
  v_query1 := v_query1 || (' ORDER BY ADMINCHARGE ASC');
  ELSE
  IF (v_orderby = 'ADMINCHARGEDESC') THEN
  v_query1 := v_query1 || (' ORDER BY ADMINCHARGE DESC');
  ELSE
  IF (v_orderby = 'DELIEVERYCHARGEASC') THEN
  v_query1 := v_query1 || (' ORDER BY DELIEVERYCHARGE ASC');
  ELSE
  IF (v_orderby = 'DELIEVERYCHARGEDESC') THEN
  v_query1 := v_query1 || (' ORDER BY DELIEVERYCHARGE DESC');
  ELSE
  IF (v_orderby = 'HANDLINGCHARGEASC') THEN
  v_query1 := v_query1 || (' ORDER BY HANDLINGCHARGE ASC');
  ELSE
  IF (v_orderby = 'HANDLINGCHARGEDESC') THEN
  v_query1 := v_query1 || (' ORDER BY HANDLINGCHARGE DESC');
  END IF;
  END IF;
  END IF;
  END IF;
  END IF;
  END IF;
  ELSE
  v_query1 := v_query1 || (' ORDER BY CATNAME,SUBCATNAME');
  END IF;
  EXECUTE v_query1;
  RETURN QUERY SELECT v_query1;
  RETURN QUERY SELECT COUNT(1) AS recordcount FROM tmp_temp;
  DROP TABLE IF EXISTS tmp_temp;
  END IF;
END;
$$;


--
-- Name: usp_getcommissionreport_admin(integer, bigint, integer, integer, integer, integer, character varying, character varying, character varying, character varying, character varying, character varying, character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_getcommissionreport_admin(v_mode integer DEFAULT 1, v_plid bigint DEFAULT 8, v_recordcount integer DEFAULT 0, v_intresult integer DEFAULT 0, v_startrowindex integer DEFAULT 1, v_maxrows integer DEFAULT 500, v_catname character varying DEFAULT ''::character varying, v_subcatname character varying DEFAULT ''::character varying, v_orderby character varying DEFAULT ''::character varying, v_searchsubsubcategory character varying DEFAULT ''::character varying, v_searchsubcategory character varying DEFAULT ''::character varying, v_searchcategory character varying DEFAULT 'Eye Wear'::character varying, v_did character varying DEFAULT ''::character varying) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_query2 text;
  v_category text;
  v_subcategory text;
  v_query text;
  v_minindex INT;
  v_maxindex INT;
  v_query1 text;
BEGIN
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp (ROWNUMBER BIGINT GENERATED BY DEFAULT AS IDENTITY,
	CATNAME varchar(500),
	SUBCATNAME varchar(500),
	ADMINCHARGE DECIMAL(10,2),
	DELIEVERYCHARGE DECIMAL(10,2),
	HANDLINGCHARGE DECIMAL(10,2),
	FixedFee DECIMAL(10,2),
	SubSubCatName varchar(500),
	SUBCATID int,
	BVPER DECIMAL(10,2),
	cashback_Per DECIMAL(10,2),
	newbv DECIMAL(10,2),
	newcashback DECIMAL(10,2),
	ModifyDate varchar(500)) ON COMMIT DROP;
  DROP TABLE IF EXISTS tmp_temp1;
  CREATE TEMP TABLE tmp_temp1 (ROWNUMBER1 BIGINT GENERATED BY DEFAULT AS IDENTITY,
	ROWNUMBER BIGINT ,
	CATNAME varchar(500),
	SUBCATNAME varchar(500),
	ADMINCHARGE DECIMAL(10,2),
	DELIEVERYCHARGE DECIMAL(10,2),
	HANDLINGCHARGE DECIMAL(10,2),
	FixedFee DECIMAL(10,2),
	SubSubCatName varchar(500),
	SUBCATID int,
	BVPER DECIMAL(10,2),
	cashback_Per DECIMAL(10,2),
	newbv DECIMAL(10,2),
	newcashback DECIMAL(10,2),
	ModifyDate varchar(500)) ON COMMIT DROP;
  v_query2 := '';
  v_category := '';
  v_subcategory := '';
  v_query := '';
  IF (v_mode = 1) THEN
  v_minindex := (v_startrowindex - 1) * v_maxrows + 1;
  v_maxindex := v_startrowindex * v_maxrows;
  SELECT subcategory INTO v_subcategory FROM tbl_merchantcat_subcat_keywordmaster WHERE plid = v_plid AND isactive = 1 AND isdeleted = 0;
  v_query := 'INSERT INTO #TEMP SELECT TMC.MAINCATNAME,TC.CATNAME,ISNULL(km.ADMINCHARGE,0) AS ADMINCHARGE,ISNULL(km.DELIEVERYCHARGE,0) AS DELIEVERYCHARGE,
	ISNULL(km.HANDLINGCHARGE,0) AS HANDLINGCHARGE,ISNULL(km.FixedFee,0) AS FixedFee,(km.SubCatName)AS SubSubCatName,ISNULL(km.SUBCATID,0) AS SUBCATID,
	ISNULL(km.BVPER,0) AS BVPER ,ISNULL(km.cashback_Per,0) AS cashback_Per, isnull(tcs.bv,0) as newbv,isnull(tcs.cashback,0) as newcashback,isnull(tcs.ModifyDate,'''')  FROM 
	TBL_MAIN_CATEGORY TMC INNER JOIN TBL_CATEGORY TC ON TMC.MAINCATID = TC.MAINCATID 
    inner join 	tbl_sub_category km on TC.MAINCATID=km.MainCatId
	left join tbl_Distributor_Commission_Structure tcs on tcs.SubSubCatID= km.SUBCATID where 1=1 ';
  IF (v_searchsubsubcategory <> '') THEN
  v_searchsubsubcategory := REPLACE(v_searchsubsubcategory, '''', '''''');
  v_query := v_query || 'AND km.subcatname LIKE''%' || v_searchsubsubcategory || '%''';
  END IF;
  IF (v_searchsubcategory <> '') THEN
  v_searchsubcategory := REPLACE(v_searchsubcategory, '''', '''''');
  v_query := v_query || 'AND TC.CATNAME LIKE''%' || v_searchsubcategory || '%''';
  END IF;
  IF (v_searchcategory <> '') THEN
  v_searchcategory := REPLACE(v_searchcategory, '''', '''''');
  v_query := v_query || 'AND TMC.MAINCATNAME LIKE''%' || v_searchcategory || '%''';
  END IF;
  IF (v_did <> '') THEN
  v_query := v_query || 'AND tcs.DID =''' || v_did || '''';
  END IF;
  RAISE NOTICE '%', v_query;
  EXECUTE v_query;
  v_query2 := 'insert into #temp1 SELECT * FROM #TEMP WHERE  ROWNUMBER In(Select MIN(ROWNUMBER) From #TEMP Group By SUBCATID)';
  EXECUTE v_query2;
  RETURN QUERY SELECT * FROM tmp_temp1 WHERE rownumber1 BETWEEN v_minindex AND v_maxindex;
  SELECT COUNT(rownumber1) INTO v_recordcount FROM tmp_temp1;
  DROP TABLE IF EXISTS tmp_temp;
  END IF;
  IF (v_mode = 2) THEN
  v_query := 'INSERT INTO #TEMP SELECT TMC.MAINCATNAME,TC.CATNAME,ISNULL(km.ADMINCHARGE,0) AS ADMINCHARGE,ISNULL(km.DELIEVERYCHARGE,0) AS DELIEVERYCHARGE,
	ISNULL(km.HANDLINGCHARGE,0) AS HANDLINGCHARGE,ISNULL(km.FixedFee,0) AS FixedFee, (km.SubCatName)AS SubSubCatName FROM TBL_MAIN_CATEGORY TMC INNER JOIN TBL_CATEGORY TC ON TMC.MAINCATID = TC.MAINCATID 
	inner join 	tbl_sub_category km on TC.MAINCATID=km.MainCatId WHERE 
	TC.STATUS=1 AND TMC.STATUS = 1 ';
  IF (v_catname <> '') THEN
  v_query := v_query || (' AND TMC.MAINCATNAME LIKE ''%' || v_catname || '%''');
  END IF;
  IF (v_subcatname <> '') THEN
  v_query := v_query || (' AND TC.CATNAME LIKE ''%' || v_subcatname || '%''');
  END IF;
  RETURN QUERY SELECT v_query;
  EXECUTE v_query;
  v_query1 := '';
  v_query1 := v_query1 || ('SELECT * FROM #TEMP WHERE ROWNUMBER BETWEEN ''' || CAST(v_startrowindex AS VARCHAR) || ''' AND ''' || CAST(v_maxrows AS VARCHAR) || ''' ');
  IF (v_orderby <> '') THEN
  IF (v_orderby = 'ADMINCHARGEASC') THEN
  v_query1 := v_query1 || (' ORDER BY ADMINCHARGE ASC');
  ELSE
  IF (v_orderby = 'ADMINCHARGEDESC') THEN
  v_query1 := v_query1 || (' ORDER BY ADMINCHARGE DESC');
  ELSE
  IF (v_orderby = 'DELIEVERYCHARGEASC') THEN
  v_query1 := v_query1 || (' ORDER BY DELIEVERYCHARGE ASC');
  ELSE
  IF (v_orderby = 'DELIEVERYCHARGEDESC') THEN
  v_query1 := v_query1 || (' ORDER BY DELIEVERYCHARGE DESC');
  ELSE
  IF (v_orderby = 'HANDLINGCHARGEASC') THEN
  v_query1 := v_query1 || (' ORDER BY HANDLINGCHARGE ASC');
  ELSE
  IF (v_orderby = 'HANDLINGCHARGEDESC') THEN
  v_query1 := v_query1 || (' ORDER BY HANDLINGCHARGE DESC');
  END IF;
  END IF;
  END IF;
  END IF;
  END IF;
  END IF;
  ELSE
  v_query1 := v_query1 || (' ORDER BY CATNAME,SUBCATNAME');
  END IF;
  EXECUTE v_query1;
  RETURN QUERY SELECT v_query1;
  RETURN QUERY SELECT COUNT(1) AS recordcount FROM tmp_temp;
  DROP TABLE IF EXISTS tmp_temp;
  END IF;
END;
$$;


--
-- Name: usp_getcommissionreport_resseler(integer, bigint, integer, integer, integer, integer, character varying, character varying, character varying, character varying, character varying, character varying, character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_getcommissionreport_resseler(v_mode integer DEFAULT 1, v_plid bigint DEFAULT 1, v_recordcount integer DEFAULT 0, v_intresult integer DEFAULT 0, v_startrowindex integer DEFAULT 1, v_maxrows integer DEFAULT 1000, v_catname character varying DEFAULT ''::character varying, v_subcatname character varying DEFAULT ''::character varying, v_orderby character varying DEFAULT ''::character varying, v_searchsubsubcategory character varying DEFAULT ''::character varying, v_searchsubcategory character varying DEFAULT ''::character varying, v_searchcategory character varying DEFAULT ''::character varying, v_did character varying DEFAULT '7'::character varying) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_category text;
  v_subcategory text;
  v_query text;
  v_minindex INT;
  v_maxindex INT;
  v_query1 text;
BEGIN
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp (ROWNUMBER BIGINT GENERATED BY DEFAULT AS IDENTITY,
	CATNAME varchar(500),
	SUBCATNAME varchar(500),
	ADMINCHARGE DECIMAL(10,2),
	DELIEVERYCHARGE DECIMAL(10,2),
	HANDLINGCHARGE DECIMAL(10,2),
	FixedFee DECIMAL(10,2),
	SubSubCatName varchar(500),
	SUBCATID int,
	BVPER DECIMAL(10,2),
	cashback_Per DECIMAL(10,2),
	newbv DECIMAL(10,2),
	newcashback DECIMAL(10,2),
	ModifyDate varchar(500)) ON COMMIT DROP;
  v_category := '';
  v_subcategory := '';
  v_query := '';
  IF (v_mode = 1) THEN
  v_minindex := (v_startrowindex - 1) * v_maxrows + 1;
  v_maxindex := v_startrowindex * v_maxrows;
  SELECT subcategory INTO v_subcategory FROM tbl_merchantcat_subcat_keywordmaster WHERE plid = v_plid AND isactive = 1 AND isdeleted = 0;
  v_query := 'INSERT INTO #TEMP SELECT TMC.MAINCATNAME,TC.CATNAME,ISNULL(km.ADMINCHARGE,0) AS ADMINCHARGE,ISNULL(km.DELIEVERYCHARGE,0) AS DELIEVERYCHARGE,
	ISNULL(km.HANDLINGCHARGE,0) AS HANDLINGCHARGE,ISNULL(km.FixedFee,0) AS FixedFee,(km.SubCatName)AS SubSubCatName,ISNULL(km.SUBCATID,0) AS SUBCATID,
	ISNULL(km.BVPER,0) AS BVPER ,ISNULL(km.cashback_Per,0) AS cashback_Per, isnull(tcs.bv,0) as newbv,isnull(tcs.cashback,0) as newcashback,isnull(tcs.ModifyDate,'''')  FROM 
	TBL_MAIN_CATEGORY TMC INNER JOIN TBL_CATEGORY TC ON TMC.MAINCATID = TC.MAINCATID 
    inner join 	tbl_sub_category km on TC.MAINCATID=km.MainCatId
	left join tbl_Distributor_Commission_Structure tcs on tcs.SubSubCatID= km.SUBCATID
	 WHERE 
	TC.CATID IN (SELECT VALUE FROM  DBO.SPLITSTRINGBYCUSTOMSYMBOL1(''' || v_subcategory || ''','','') ) 
	AND TC.STATUS=1 AND TMC.STATUS = 1 ';
  IF (v_searchsubsubcategory <> '') THEN
  v_searchsubsubcategory := REPLACE(v_searchsubsubcategory, '''', '''''');
  v_query := v_query || 'AND km.subcatname LIKE''%' || v_searchsubsubcategory || '%''';
  END IF;
  IF (v_searchsubcategory <> '') THEN
  v_searchsubcategory := REPLACE(v_searchsubcategory, '''', '''''');
  v_query := v_query || 'AND TC.CATNAME LIKE''%' || v_searchsubcategory || '%''';
  END IF;
  IF (v_searchcategory <> '') THEN
  v_searchcategory := REPLACE(v_searchcategory, '''', '''''');
  v_query := v_query || 'AND TMC.MAINCATNAME LIKE''%' || v_searchcategory || '%''';
  END IF;
  IF (v_did <> '') THEN
  v_query := v_query || 'AND tcs.DID LIKE''%' || v_did || '%''';
  END IF;
  EXECUTE v_query;
  RETURN QUERY SELECT v_query;
  RETURN QUERY SELECT * FROM tmp_temp;
  DROP TABLE IF EXISTS tmp_temp;
  END IF;
  IF (v_mode = 2) THEN
  v_query := 'INSERT INTO #TEMP SELECT TMC.MAINCATNAME,TC.CATNAME,ISNULL(km.ADMINCHARGE,0) AS ADMINCHARGE,ISNULL(km.DELIEVERYCHARGE,0) AS DELIEVERYCHARGE,
	ISNULL(km.HANDLINGCHARGE,0) AS HANDLINGCHARGE,ISNULL(km.FixedFee,0) AS FixedFee, (km.SubCatName)AS SubSubCatName FROM TBL_MAIN_CATEGORY TMC INNER JOIN TBL_CATEGORY TC ON TMC.MAINCATID = TC.MAINCATID 
	inner join 	tbl_sub_category km on TC.MAINCATID=km.MainCatId WHERE 
	TC.STATUS=1 AND TMC.STATUS = 1 ';
  IF (v_catname <> '') THEN
  v_query := v_query || (' AND TMC.MAINCATNAME LIKE ''%' || v_catname || '%''');
  END IF;
  IF (v_subcatname <> '') THEN
  v_query := v_query || (' AND TC.CATNAME LIKE ''%' || v_subcatname || '%''');
  END IF;
  RETURN QUERY SELECT v_query;
  EXECUTE v_query;
  v_query1 := '';
  v_query1 := v_query1 || ('SELECT * FROM #TEMP WHERE ROWNUMBER BETWEEN ''' || CAST(v_startrowindex AS VARCHAR) || ''' AND ''' || CAST(v_maxrows AS VARCHAR) || ''' ');
  IF (v_orderby <> '') THEN
  IF (v_orderby = 'ADMINCHARGEASC') THEN
  v_query1 := v_query1 || (' ORDER BY ADMINCHARGE ASC');
  ELSE
  IF (v_orderby = 'ADMINCHARGEDESC') THEN
  v_query1 := v_query1 || (' ORDER BY ADMINCHARGE DESC');
  ELSE
  IF (v_orderby = 'DELIEVERYCHARGEASC') THEN
  v_query1 := v_query1 || (' ORDER BY DELIEVERYCHARGE ASC');
  ELSE
  IF (v_orderby = 'DELIEVERYCHARGEDESC') THEN
  v_query1 := v_query1 || (' ORDER BY DELIEVERYCHARGE DESC');
  ELSE
  IF (v_orderby = 'HANDLINGCHARGEASC') THEN
  v_query1 := v_query1 || (' ORDER BY HANDLINGCHARGE ASC');
  ELSE
  IF (v_orderby = 'HANDLINGCHARGEDESC') THEN
  v_query1 := v_query1 || (' ORDER BY HANDLINGCHARGE DESC');
  END IF;
  END IF;
  END IF;
  END IF;
  END IF;
  END IF;
  ELSE
  v_query1 := v_query1 || (' ORDER BY CATNAME,SUBCATNAME');
  END IF;
  EXECUTE v_query1;
  DROP TABLE IF EXISTS tmp_temp;
  END IF;
END;
$$;


--
-- Name: usp_getcompanydetails(character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_getcompanydetails(v_resellerloginid character varying DEFAULT '87927897'::character varying) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_did int;
  v_pmid int;
  v_companyresellerurl Varchar(100);
  v_companyapiurl varchar(100);
BEGIN
  v_did := 0;
  v_pmid := 0;
  v_companyresellerurl := '';
  v_companyapiurl := '';
  SELECT did, pmid INTO v_did, v_pmid FROM tbl_distributor WHERE loginid = v_resellerloginid;
  SELECT COALESCE(companyresellerurl, ''), COALESCE(apiurl, '') INTO v_companyresellerurl, v_companyapiurl FROM tbl_companysettings WHERE pmid = v_pmid;
  RETURN QUERY SELECT v_did AS did, (SELECT COALESCE(companyname, '') FROM distributor_master WHERE pmid = v_pmid) AS name, (SELECT COALESCE(mobileno, '') FROM distributor_master WHERE pmid = v_pmid) AS mobile, (SELECT COALESCE(companyinfoemailid, '') FROM tbl_companysettings WHERE pmid = v_pmid) AS emailid, (v_companyresellerurl || '/Company_Logo/' || (SELECT COALESCE(companyimage, '') FROM distributor_master WHERE pmid = v_pmid)) AS logo, (v_companyresellerurl || '/Company_Logo/' || (SELECT COALESCE(companyimage, '') FROM distributor_master WHERE pmid = v_pmid)) AS favicon, v_companyapiurl AS companyapiurl, 'http://services.eblaa.in/' AS companyrechargeurl, '' AS currency, (SELECT COALESCE(companygooglepluslink, '') FROM tbl_companysettings WHERE pmid = v_pmid) AS googleplussettings, (SELECT COALESCE(companyfacebooklink, '') FROM tbl_companysettings WHERE pmid = v_pmid) AS facebooksetting, (SELECT COALESCE(companytwitterlink, '') FROM tbl_companysettings WHERE pmid = v_pmid) AS socialurl, '' AS companyaddress, v_pmid AS pmid, '' AS merchantid, '' AS merchantkey, '' AS colorprimary, '' AS colorprimarydark, '' AS coloraccent, v_resellerloginid AS resellerloginid, (SELECT COALESCE(url, '') FROM distributor_master WHERE pmid = v_pmid) AS companyurl, 'http://store.eblaa.in/' AS companywebviewurl FROM tbl_company LIMIT 1;
END;
$$;


--
-- Name: usp_getcompanyprofiledetails(bigint); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_getcompanyprofiledetails(v_pmid bigint DEFAULT 10028) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF NOT EXISTS(SELECT 1 FROM tbl_companysettings WHERE pmid = v_pmid) THEN
  RETURN QUERY SELECT '' AS companyinfoemailid, '' AS companysupportemailid, '' AS companysendmailemailid, '' AS companynoreplyemailid, '' AS companymailserver, '' AS companymailpassowrd, '' AS companymailserverport, '' AS companyaffiliateurl, '' AS companyresellerurl, '' AS companymerchanturl, '' AS companyadminurl, '' AS companyapiurl, '' AS companyadvertisement, '' AS companyservices, '' AS companycurrency, '' AS companyoauthurl, '' AS companyvalidurl, '' AS companyscope, '' AS companyclientid, '' AS companyredirect, '' AS companylogout, '' AS companyfacebookclientid, '' AS companyfacebookclientsecret, '' AS companypgmerchantkey, '' AS companypgsalt, '' AS smsapi, '' AS dedicatedproducturl, CAST(0 AS DECIMAL(18, 2)) AS transationpayumoneyrate;
  ELSE
  RETURN QUERY SELECT COALESCE(companyinfoemailid, '') AS companyinfoemailid, COALESCE(companysupportemailid, '') AS companysupportemailid, COALESCE(companysendmailemailid, '') AS companysendmailemailid, COALESCE(companynoreplyemailid, '') AS companynoreplyemailid, COALESCE(companymailserver, '') AS companymailserver, COALESCE(companymailpassowrd, '') AS companymailpassowrd, COALESCE(companymailserverport, '') AS companymailserverport, COALESCE(companyaffiliateurl, '') AS companyaffiliateurl, COALESCE(companyresellerurl, '') AS companyresellerurl, COALESCE(companymerchanturl, '') AS companymerchanturl, COALESCE(companyadminurlforimage, '') AS companyadminurl, COALESCE(companyapiurl, '') AS companyapiurl, COALESCE(companyadvertisement, '') AS companyadvertisement, COALESCE(companyservices, '') AS companyservices, COALESCE(companycurrency, '') AS companycurrency, COALESCE(companyoauthurl, '') AS companyoauthurl, COALESCE(companyvalidurl, '') AS companyvalidurl, COALESCE(companyscope, '') AS companyscope, COALESCE(companyclientid, '') AS companyclientid, COALESCE(companyredirect, '') AS companyredirect, COALESCE(companylogout, '') AS companylogout, COALESCE(companyfacebookclientid, '') AS companyfacebookclientid, COALESCE(companyfacebookclientsecret, '') AS companyfacebookclientsecret, COALESCE(companypgmerchantkey, '') AS companypgmerchantkey, COALESCE(companypgsalt, '') AS companypgsalt, COALESCE(smsapi, '') AS smsapi, COALESCE(dedicatedproducturl, ''), COALESCE(CAST(transationpayumoneyrate AS DECIMAL(18, 2)), 0) AS transationpayumoneyrate FROM tbl_companysettings WHERE pmid = v_pmid;
  END IF;
END;
$$;


--
-- Name: usp_getcontactdetails(bigint); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_getcontactdetails(v_plid bigint DEFAULT 1) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
BEGIN
  RETURN QUERY SELECT username, COALESCE(pmid, 0) AS pmid, clid, title, fname, lname, (CASE WHEN phone = '' THEN '' WHEN COALESCE(phone, '') = '' THEN '' ELSE ('+' || c.isdcode || ' ' || phone) END) AS phonewithcode, phone, designation, emailid AS cper_emailid, loginid, password, imagename, c.countryname, phone, COALESCE(tbl_customerlogin.intro_plid, 0) AS intro_plid, CASE WHEN dob = '1900-01-01' THEN '' ELSE COALESCE(CAST(TO_CHAR(dob, 'MM/DD/YYYY') AS VARCHAR(30)), '') END AS dob, COALESCE(fatherormothername, '') AS fatherormothername, COALESCE(gender, 0) AS gender, COALESCE(highestqualification, 0) AS highestqualification FROM tbl_customerlogin INNER JOIN country AS c ON c.cid = tbl_customerlogin.cid WHERE clid = v_plid;
END;
$$;


--
-- Name: usp_getcontactdetails_mobile(bigint, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_getcontactdetails_mobile(v_plid bigint DEFAULT 1, v_pmid integer DEFAULT 0) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_geturl varchar(100);
  v_companyredirect varchar(100);
BEGIN
  v_geturl := '';
  v_companyredirect := '';
  SELECT profileimagepath INTO v_geturl FROM tbl_company;
  SELECT COALESCE(companyredirect, '') INTO v_companyredirect FROM tbl_companysettings WHERE pmid = v_pmid;
  RETURN QUERY SELECT username, COALESCE(pmid, 0) AS pmid, clid, title, fname, lname, (CASE WHEN phone = '' THEN '' WHEN COALESCE(phone, '') = '' THEN '' ELSE ('+' || c.isdcode || ' ' || phone) END) AS phonewithcode, phone, designation, emailid AS cper_emailid, loginid, password, 'https://shop.sohunginfotech.com/Member_Image/' || imagename, c.countryname, phone, COALESCE(tbl_customerlogin.intro_plid, 0) AS intro_plid, CASE WHEN dob = '1900-01-01' THEN '' ELSE COALESCE(CAST(TO_CHAR(dob, 'MM/DD/YYYY') AS VARCHAR(30)), '') END AS dob, COALESCE(fatherormothername, '') AS fatherormothername, COALESCE(gender, 0) AS gender, COALESCE(highestqualification, 0) AS highestqualification, loginid FROM tbl_customerlogin INNER JOIN country AS c ON c.cid = tbl_customerlogin.cid WHERE clid = v_plid AND did = v_pmid;
END;
$$;


