--
-- Name: usp_getcountofcatandsubcat(); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_getcountofcatandsubcat() RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_count1 int;
  v_count2 int;
  v_count3 int;
  v_count4 int;
  v_catid int;
  v_countval int;
  v_subcatid int;
BEGIN
  DROP TABLE IF EXISTS tmp_tempcounts;
  CREATE TEMP TABLE tmp_tempcounts (tcid int GENERATED BY DEFAULT AS IDENTITY,
type varchar(30),
typeID int,
countval int) ON COMMIT DROP;
  DROP TABLE IF EXISTS tmp_tempcat;
  CREATE TEMP TABLE tmp_tempcat ON COMMIT DROP AS SELECT ROW_NUMBER() OVER (ORDER BY catid ASC NULLS FIRST) AS catrow, catid FROM tbl_category WHERE status = 1 AND isdelete = 0 ORDER BY catid ASC NULLS FIRST;
  v_count1 := 1;
  SELECT COUNT(1) INTO v_count2 FROM tmp_tempcat;
  WHILE (v_count1 <= v_count2) LOOP
  SELECT catid INTO v_catid FROM tmp_tempcat WHERE catrow = v_count1;
  SELECT COUNT(1) INTO v_countval FROM ims_masterproduct AS pm INNER JOIN ims_subproduct AS ps ON ps.mprid = pm.mprid WHERE pm.maincategoryid = v_catid AND pm.subcategoryid = 0 AND ps.isactive = 1;
  INSERT INTO tmp_tempcounts (type, typeid, countval) VALUES ('cat', v_catid, v_countval);
  DROP TABLE IF EXISTS tmp_tempsubcat;
  CREATE TEMP TABLE tmp_tempsubcat ON COMMIT DROP AS SELECT ROW_NUMBER() OVER (ORDER BY subcatid ASC NULLS FIRST) AS subcatrow, subcatid FROM tbl_sub_category WHERE catid = v_catid AND status = 1 AND isdelete = 0 ORDER BY subcatid ASC NULLS FIRST;
  v_count3 := 1;
  SELECT COUNT(1) INTO v_count4 FROM tmp_tempsubcat;
  WHILE (v_count3 <= v_count4) LOOP
  SELECT subcatid INTO v_subcatid FROM tmp_tempsubcat WHERE subcatrow = v_count3;
  SELECT COUNT(1) INTO v_countval FROM ims_masterproduct AS pm INNER JOIN ims_subproduct AS ps ON ps.mprid = pm.mprid WHERE pm.subcategoryid = v_subcatid AND ps.isactive = 1;
  INSERT INTO tmp_tempcounts (type, typeid, countval) VALUES ('subcat', v_subcatid, v_countval);
  v_count3 := v_count3 + 1;
  END LOOP;
  DROP TABLE IF EXISTS tmp_tempsubcat;
  v_count1 := v_count1 + 1;
  END LOOP;
  DROP TABLE IF EXISTS tmp_tempcat;
  RETURN QUERY SELECT * FROM tmp_tempcounts;
  DROP TABLE IF EXISTS tmp_tempcounts;
END;
$$;


--
-- Name: usp_getcountofmaincat(); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_getcountofmaincat() RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_count1 int;
  v_count2 int;
  v_count3 int;
  v_count4 int;
  v_catid int;
  v_maincatid int;
  v_countval int;
  v_subcatid int;
  v_prcode varchar(100);
  v_maincatidnew int;
BEGIN
  DROP TABLE IF EXISTS tmp_tempcounts;
  CREATE TEMP TABLE tmp_tempcounts (tcid int GENERATED BY DEFAULT AS IDENTITY,
		type varchar(30),
		typeID int,
		countval int) ON COMMIT DROP;
  DROP TABLE IF EXISTS tmp_tempcatmain;
  CREATE TEMP TABLE tmp_tempcatmain ON COMMIT DROP AS SELECT ROW_NUMBER() OVER (ORDER BY maincatid ASC NULLS FIRST) AS maincatrow, maincatid FROM tbl_main_category WHERE status = 1 AND isdelete = 0 ORDER BY maincatid ASC NULLS FIRST;
  v_count1 := 1;
  SELECT COUNT(maincatrow) INTO v_count2 FROM tmp_tempcatmain;
  WHILE (v_count1 <= v_count2) LOOP
  SELECT maincatid INTO v_maincatid FROM tmp_tempcatmain WHERE maincatrow = v_count1;
  DROP TABLE IF EXISTS tmp_tempsubcat;
  CREATE TEMP TABLE tmp_tempsubcat ON COMMIT DROP AS SELECT ROW_NUMBER() OVER (ORDER BY maincategoryid ASC NULLS FIRST) AS maincatrow, productcode, maincategoryid FROM ims_masterproduct WHERE maincategoryid = v_maincatid ORDER BY maincategoryid ASC NULLS FIRST;
  v_count3 := 1;
  SELECT COUNT(1) INTO v_count4 FROM tmp_tempsubcat;
  WHILE (v_count3 <= v_count4) LOOP
  SELECT productcode, maincategoryid INTO v_prcode, v_maincatidnew FROM tmp_tempsubcat WHERE maincatrow = v_count3;
  SELECT COUNT(sprid) INTO v_countval FROM ims_subproduct WHERE subprcode = v_prcode AND isactive = 1;
  INSERT INTO tmp_tempcounts (type, typeid, countval) VALUES ('maincat', v_maincatidnew, v_countval);
  v_count3 := v_count3 + 1;
  END LOOP;
  DROP TABLE IF EXISTS tmp_tempsubcat;
  v_count1 := v_count1 + 1;
  END LOOP;
  DROP TABLE IF EXISTS tmp_tempcatmain;
  RETURN QUERY SELECT * FROM tmp_tempcounts;
  DROP TABLE IF EXISTS tmp_tempcounts;
END;
$$;


--
-- Name: usp_getcountrywiselogs1(character varying, character varying, integer, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_getcountrywiselogs1(v_fromdate character varying, v_todate character varying, v_fromindex integer DEFAULT 0, v_toindex integer DEFAULT 50) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_count int;
  v_count1 int;
  v_sumsessions bigint;
  v_cntryname varchar(100);
  v_sumpagevisit bigint;
  v_sumuniquevisit bigint;
  v_recordcount int;
  v_sumtotalvisitor double precision;
  v_ttlvisitpercent int;
  v_overallvisit double precision;
BEGIN
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp ON COMMIT DROP AS SELECT country, state, city, ipaddress, sessioncount, pagecount FROM tbl_visitorhistory WHERE NOT COALESCE(country, '') IN ('', '-') AND COALESCE(country, '') = '';
  IF (v_fromdate = '' OR v_todate = '') THEN
  IF (v_fromdate = '' AND v_todate <> '') THEN
  INSERT INTO tmp_temp SELECT country, state, city, ipaddress, sessioncount, pagecount FROM tbl_visitorhistory WHERE (TO_DATE(date, 'DD/MM/YYYY') <= TO_DATE(v_todate, 'DD/MM/YYYY')) AND (NOT COALESCE(country, '') IN ('', '-'));
  ELSE
  IF (v_fromdate <> '' AND v_todate = '') THEN
  INSERT INTO tmp_temp SELECT country, state, city, ipaddress, sessioncount, pagecount FROM tbl_visitorhistory WHERE (TO_DATE(date, 'DD/MM/YYYY') >= TO_DATE(v_fromdate, 'DD/MM/YYYY')) AND (NOT COALESCE(country, '') IN ('', '-'));
  ELSE
  INSERT INTO tmp_temp SELECT country, state, city, ipaddress, sessioncount, pagecount FROM tbl_visitorhistory WHERE (NOT COALESCE(country, '') IN ('', '-'));
  END IF;
  END IF;
  ELSE
  INSERT INTO tmp_temp SELECT country, state, city, ipaddress, sessioncount, pagecount FROM tbl_visitorhistory WHERE (TO_DATE(date, 'DD/MM/YYYY') BETWEEN TO_DATE(v_fromdate, 'DD/MM/YYYY') AND TO_DATE(v_todate, 'DD/MM/YYYY')) AND (NOT COALESCE(country, '') IN ('', '-'));
  END IF;
  DROP TABLE IF EXISTS tmp_tempdetails;
  CREATE TEMP TABLE tmp_tempdetails (rowid int GENERATED BY DEFAULT AS IDENTITY,
   countryname varchar(100),
   ttlvisit int default(0),
   unqvisit int default(0),
   pagevisit int default(0),
   sessionscnt int default(0),
   visitpercent double precision default(0)) ON COMMIT DROP;
  DROP TABLE IF EXISTS tmp_tempfinal;
  CREATE TEMP TABLE tmp_tempfinal (rownumber int GENERATED BY DEFAULT AS IDENTITY,
   countryname varchar(100),
   ttlvisit int default(0),
   unqvisit int default(0),
   pagevisit int default(0),
   sessionscnt int default(0),
   visitpercent double precision default(0)) ON COMMIT DROP;
  INSERT INTO tmp_tempdetails (countryname) SELECT DISTINCT country FROM tmp_temp ORDER BY country NULLS FIRST;
  v_count := v_fromindex;
  SELECT (SELECT MAX(rowid) FROM tmp_tempdetails) INTO v_count1;
  SELECT COUNT(1) INTO v_overallvisit FROM tmp_temp;
  WHILE (v_count <= v_count1) LOOP
  IF EXISTS(SELECT 1 FROM tmp_tempdetails WHERE rowid = v_count) THEN
  SELECT countryname INTO v_cntryname FROM tmp_tempdetails WHERE rowid = v_count;
  SELECT COUNT(1) INTO v_sumtotalvisitor FROM tmp_temp WHERE country = v_cntryname;
  SELECT SUM(sessioncount) INTO v_sumsessions FROM tmp_temp WHERE country = v_cntryname;
  SELECT SUM(pagecount) INTO v_sumpagevisit FROM tmp_temp WHERE country = v_cntryname;
  SELECT COUNT(DISTINCT ipaddress) INTO v_sumuniquevisit FROM tmp_temp WHERE country = v_cntryname;
  UPDATE tmp_tempdetails SET ttlvisit = v_sumtotalvisitor, unqvisit = v_sumuniquevisit, pagevisit = v_sumpagevisit, sessionscnt = v_sumsessions, visitpercent = ROUND(((v_sumtotalvisitor / v_overallvisit) * 100), 2) WHERE rowid = v_count;
  END IF;
  v_count := v_count + 1;
  END LOOP;
  INSERT INTO tmp_tempfinal (countryname, ttlvisit, unqvisit, pagevisit, sessionscnt, visitpercent) SELECT countryname, ttlvisit, unqvisit, pagevisit, sessionscnt, visitpercent FROM tmp_tempdetails ORDER BY ttlvisit DESC NULLS LAST;
  RETURN QUERY SELECT * FROM tmp_tempfinal WHERE rownumber BETWEEN v_fromindex AND v_toindex;
  SELECT COUNT(*) INTO v_recordcount FROM tmp_tempfinal;
  RETURN QUERY SELECT v_recordcount AS recordcount;
  DROP TABLE IF EXISTS tmp_tempdetails;
  DROP TABLE IF EXISTS tmp_temp;
  DROP TABLE IF EXISTS tmp_tempfinal;
END;
$$;


--
-- Name: usp_getcourierdatalist(integer, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_getcourierdatalist(v_mode integer DEFAULT 1, v_status integer DEFAULT 3) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_count INT;
  v_totalcount INT;
  v_invoiceno varchar(100);
  v_productname text;
  v_invoicevalue Decimal(18,3);
  v_totalitem int;
BEGIN
  -- SET option (removed)
  IF (v_mode = 1) THEN
  v_count := 1;
  v_totalcount := 0;
  v_totalitem := 0;
  DROP TABLE IF EXISTS tmp_courierdatatemp;
  CREATE TEMP TABLE tmp_courierdatatemp (ROWNUMBER INT GENERATED BY DEFAULT AS IDENTITY,
ORDERID VARCHAR(100),
ITEM_NAME text,
NO_OF_PIECE INT,
CUSTOMER_NAME VARCHAR(100),
SHIPPING_ADD1 VARCHAR(1000),
SHIPPING_ADD2 VARCHAR(1000),
SHIPPING_CITY VARCHAR(100),
SHIPPING_STATE VARCHAR(100),
SHIPPING_PINCODE VARCHAR(100),
SHIPPING_MOBILENO VARCHAR(100),
INVOICE_VALUE DECIMAL(18,2),
COLLECTABLE_AMOUNT DECIMAL(18,2),
DOCKETNO VARCHAR(100),
WEIGHT VARCHAR(100),
STATUS VARCHAR(500),
TYPE_OF_SERVICE VARCHAR(500),
INVOICENO VARCHAR(100),
PAYMODE varchar(100)) ON COMMIT DROP;
  INSERT INTO tmp_courierdatatemp SELECT DISTINCT pom.orderid, '', 0, (fname || '' || lname), address, 'N/A', om.city, '', om.pincode, om.mobileno, 0, 0, pom.docketno, '', '', '', pom.invoiceno, om.paymode FROM tbl_product_order_master AS pom LEFT JOIN tbl_order_master AS om ON pom.orderid = om.orderid WHERE pom.intstatus = v_status;
  SELECT COUNT(*) INTO v_totalcount FROM tmp_courierdatatemp;
  RETURN QUERY SELECT * FROM tmp_courierdatatemp;
  WHILE (v_totalcount >= v_count) LOOP
  v_invoiceno := '';
  v_productname := '';
  SELECT invoiceno INTO v_invoiceno FROM tmp_courierdatatemp WHERE rownumber = v_count;
  SELECT COALESCE(v_productname || ',', '') || CAST(product_name AS VARCHAR(1000)) INTO v_productname FROM tbl_product_order_master WHERE invoiceno = v_invoiceno;
  v_productname := SUBSTRING(v_productname FROM 2 FOR LENGTH(CAST(v_productname AS TEXT)));
  SELECT SUM(total_purchase_cost), SUM(CAST(product_qty AS INT)) INTO v_invoicevalue, v_totalitem FROM tbl_product_order_master WHERE invoiceno = v_invoiceno;
  UPDATE tmp_courierdatatemp SET item_name = v_productname, invoice_value = ROUND(v_invoicevalue, 0), collectable_amount = ROUND(v_invoicevalue, 0), no_of_piece = v_totalitem WHERE rownumber = v_count;
  v_count := v_count + 1;
  END LOOP;
  INSERT INTO tbl_downloaded_courierpartner_excel (orderid, item_name, no_of_piece, customer_name, shipping_add1, shipping_add2, shipping_city, shipping_state, shipping_pincode, shipping_mobileno, invoice_value, collectable_amount, docketno, weight, status, type_of_service, invoiceno, paymode, uploaded_date) SELECT orderid, item_name, no_of_piece, customer_name, shipping_add1, shipping_add2, shipping_city, shipping_state, shipping_pincode, shipping_mobileno, invoice_value, collectable_amount, docketno, weight, status, type_of_service, invoiceno, paymode, dbo.FUN_GETCURRENTDATE() FROM tmp_courierdatatemp;
  RETURN QUERY SELECT * FROM tmp_courierdatatemp;
  DROP TABLE IF EXISTS tmp_courierdatatemp;
  END IF;
  -- SET option (removed)
END;
$$;


--
-- Name: usp_getcourierdatalist_merchand(integer, integer, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_getcourierdatalist_merchand(v_mode integer DEFAULT 1, v_status integer DEFAULT 3, v_branchid integer DEFAULT 2) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_count INT;
  v_totalcount INT;
  v_invoiceno varchar(100);
  v_productname text;
  v_invoicevalue Decimal(18,3);
  v_totalitem int;
BEGIN
  -- SET option (removed)
  IF (v_mode = 1) THEN
  v_count := 1;
  v_totalcount := 0;
  v_totalitem := 0;
  DROP TABLE IF EXISTS tmp_courierdatatemp;
  CREATE TEMP TABLE tmp_courierdatatemp (ROWNUMBER INT GENERATED BY DEFAULT AS IDENTITY,      
ORDERID VARCHAR(100),      
ITEM_NAME text,      
NO_OF_PIECE INT,      
CUSTOMER_NAME VARCHAR(100),      
SHIPPING_ADD1 VARCHAR(1000),      
SHIPPING_ADD2 VARCHAR(1000),      
SHIPPING_CITY VARCHAR(100),      
SHIPPING_STATE VARCHAR(100),      
SHIPPING_PINCODE VARCHAR(100),      
SHIPPING_MOBILENO VARCHAR(100),      
INVOICE_VALUE DECIMAL(18,2),      
COLLECTABLE_AMOUNT DECIMAL(18,2),      
DOCKETNO VARCHAR(100),      
WEIGHT VARCHAR(100),      
CurrentSTATUS VARCHAR(500),      
TYPE_OF_SERVICE VARCHAR(500),      
INVOICENO VARCHAR(100),      
PAYMODE varchar(100),      
OrderNO varchar(200)) ON COMMIT DROP;
  INSERT INTO tmp_courierdatatemp SELECT DISTINCT pom.orderid, product_name AS item_name, 0, (om.fname || '' || om.lname), address, 'N/A', om.city, '', om.pincode, om.mobileno, 0, 0, '' AS docketno, '', pom.status, '', pom.invoiceno, om.paymode, pom.orderno FROM tbl_product_order_master AS pom LEFT JOIN tbl_order_master AS om ON pom.orderid = om.orderid LEFT JOIN portal_login AS pl ON pl.plid = pom.plid WHERE pl.plid = v_branchid AND NOT pom.intstatus IN (6, 0, 7, 8, 9, -1) AND pom.intstatus = v_status;
  SELECT COUNT(1) INTO v_totalcount FROM tmp_courierdatatemp;
  WHILE (v_totalcount >= v_count) LOOP
  v_invoiceno := '';
  v_productname := '';
  SELECT invoiceno INTO v_invoiceno FROM tmp_courierdatatemp WHERE rownumber = v_count;
  SELECT total_purchase_cost, CAST(product_qty AS INT) INTO v_invoicevalue, v_totalitem FROM tbl_product_order_master WHERE invoiceno = v_invoiceno;
  UPDATE tmp_courierdatatemp SET invoice_value = ROUND(v_invoicevalue, 0), collectable_amount = ROUND(v_invoicevalue, 0), no_of_piece = v_totalitem WHERE rownumber = v_count;
  v_count := v_count + 1;
  END LOOP;
  INSERT INTO tbl_downloaded_courierpartner_excel (orderid, item_name, no_of_piece, customer_name, shipping_add1, shipping_add2, shipping_city, shipping_state, shipping_pincode, shipping_mobileno, invoice_value, collectable_amount, docketno, weight, status, type_of_service, invoiceno, paymode, uploaded_date) SELECT orderid, item_name, no_of_piece, customer_name, shipping_add1, shipping_add2, shipping_city, shipping_state, shipping_pincode, shipping_mobileno, invoice_value, collectable_amount, docketno, weight, currentstatus, type_of_service, invoiceno, paymode, dbo.FUN_GETCURRENTDATE() FROM tmp_courierdatatemp;
  RETURN QUERY SELECT * FROM tmp_courierdatatemp;
  DROP TABLE IF EXISTS tmp_courierdatatemp;
  END IF;
  -- SET option (removed)
END;
$$;


--
-- Name: usp_getcurrentadswalletbalance(bigint); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_getcurrentadswalletbalance(v_plid bigint) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_currencysymbol varchar(10);
  v_current_amount numeric(19,4);
BEGIN
  SELECT currencysymbol INTO v_currencysymbol FROM portal_login WHERE plid = v_plid;
  IF EXISTS(SELECT plid FROM tbl_adsewallet WHERE plid = v_plid) THEN
  SELECT current_amount INTO v_current_amount FROM tbl_adsewallet WHERE plid = v_plid;
  ELSE
  v_current_amount := 0;
  END IF;
  RETURN QUERY SELECT v_currencysymbol AS currencysymbol, v_current_amount AS current_amount;
END;
$$;


--
-- Name: usp_getcurrentsubscriptiondetails(bigint); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_getcurrentsubscriptiondetails(v_pmid bigint) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
BEGIN
  RETURN QUERY SELECT sdid, dbo.fun_GetCategoryName(catid) AS catlist, dbo.fun_GetkeyName(keyid) AS keylist, dbo.fun_Getstate(ctid) AS statelist, dbo.fun_Getcity(ctid) AS citylist, dbo.fun_GetareaName(aid) AS arealist, noofmonth, CAST(TO_CHAR(subscriptiondate, 'DD-MM-YYYY') AS VARCHAR(27)) AS startdate, CAST(TO_CHAR(subscriptiondate + (INTERVAL '1 MONTH' * noofmonth), 'DD-MM-YYYY') AS VARCHAR(27)) AS expiredate FROM tbl_subscription_details WHERE pmid = v_pmid ORDER BY sdid DESC NULLS LAST LIMIT 1;
END;
$$;


--
-- Name: usp_getcurrentsubscriptionwalletbalance(bigint, numeric); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_getcurrentsubscriptionwalletbalance(v_plid bigint, v_current_amount numeric) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_currencysymbol varchar(10);
  v_total_amount numeric(19,4);
BEGIN
  SELECT currencysymbol INTO v_currencysymbol FROM portal_login WHERE plid = v_plid;
  IF EXISTS(SELECT plid FROM tbl_subscription_wallet WHERE plid = v_plid) THEN
  SELECT current_amount, total_amount INTO v_current_amount, v_total_amount FROM tbl_subscription_wallet WHERE plid = v_plid;
  ELSE
  v_current_amount := 0;
  END IF;
  RETURN QUERY SELECT v_currencysymbol AS currencysymbol, COALESCE(v_current_amount, 0) AS current_amount, COALESCE(v_total_amount, 0) AS total_amount;
END;
$$;


--
-- Name: usp_getcustomer_address(bigint, character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_getcustomer_address(v_plid bigint DEFAULT 27, v_message character varying DEFAULT 'YOU HAVE NO ADDRES'::character varying) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
BEGIN
  BEGIN
  RETURN QUERY SELECT ica.pincode, ica.countryname, ica.phoneno1, ica.shortaddress, ica.landmark, ica.villagename, ica.cityname, ica.statename, ica.districtname, ica.phoneno2, ica.id, ica.cname, ica.addresstype1, tcl.username, ica.countryid FROM ims_customeraddress AS ica LEFT JOIN tbl_customerlogin AS tcl ON ica.touserid = tcl.clid WHERE touserid = v_plid ORDER BY createddate DESC NULLS LAST;
  EXCEPTION WHEN OTHERS THEN
  v_message := 'YOU HAVE NO ADDRESS RECORD';
  END;
END;
$$;


--
-- Name: usp_getcustomerbankdetails_resellercustomer(integer, character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_getcustomerbankdetails_resellercustomer(v_clid integer DEFAULT 6, v_stroutput character varying DEFAULT ''::character varying) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
BEGIN
  BEGIN
  IF (v_clid > 0) THEN
  IF NOT EXISTS(SELECT 1 FROM tbl_customerlogin WHERE clid = v_clid) THEN
  v_stroutput := 'Invalid customer';
  RETURN;
  ELSE
  IF EXISTS(SELECT 1 FROM tbl_customer_bank_accounts WHERE clid = v_clid AND active = 1) THEN
  IF ((SELECT COUNT(1) FROM tbl_customer_bank_accounts WHERE clid = v_clid AND active = 1) > 0) THEN
  RETURN QUERY SELECT tbl_customer_bank_accounts.clid AS clid, COALESCE(cl.phone, '') AS mobileno, COALESCE(accountholdername, '') AS accountholdername, COALESCE(accountno, '') AS accountno, COALESCE(bankname, '') AS bankname, COALESCE(branchname, '') AS branchname, COALESCE(ifsccode, '') AS ifsccode FROM tbl_customer_bank_accounts INNER JOIN tbl_customerlogin AS cl ON tbl_customer_bank_accounts.clid = cl.clid WHERE tbl_customer_bank_accounts.clid = v_clid AND tbl_customer_bank_accounts.active = 1;
  v_stroutput := 'Success';
  ELSE
  v_stroutput := 'Account details not approved';
  RETURN;
  END IF;
  ELSE
  v_stroutput := 'Account details not found';
  RETURN;
  END IF;
  END IF;
  END IF;
  EXCEPTION WHEN OTHERS THEN
  IF (0 <> 0) THEN
  v_stroutput := 'Error';
  RETURN;
  END IF;
  END;
END;
$$;


