--

CREATE FUNCTION dbo.usp_getcustomerdetails_by_rech_transid(v_transid character varying DEFAULT '1172044079'::character varying) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_clid INT;
  v_rechamount DECIMAL(18,2);
  v_name VARCHAR(100);
  v_emailid VARCHAR(100);
  v_mobileno VARCHAR(50);
  v_operatorcode VARCHAR(100);
BEGIN
  -- SET option (removed)
  IF (v_transid <> '') THEN
  v_clid := 0;
  v_rechamount := 0;
  v_name := '';
  v_emailid := '';
  v_mobileno := '';
  v_operatorcode := '';
  IF EXISTS(SELECT 1 FROM dbo.tbl_customer_postpaid_recharges WHERE transactionid = v_transid) THEN
  SELECT COALESCE(clid, 0), COALESCE(rechargeamount, ''), COALESCE(mobileno, ''), COALESCE(operatortype, '') INTO v_clid, v_rechamount, v_mobileno, v_operatorcode FROM dbo.tbl_customer_postpaid_recharges WHERE transactionid = v_transid;
  RETURN QUERY SELECT COALESCE(fname, '') || ' ' || COALESCE(lname, '') AS name, COALESCE(emailid, '') AS emailid, COALESCE(clid, 0) AS clid, v_mobileno AS mobileno, v_rechamount AS amount, v_operatorcode AS operatorcode FROM dbo.tbl_customerlogin WHERE clid = v_clid;
  END IF;
  IF EXISTS(SELECT 1 FROM dbo.tbl_customer_prepaid_recharges WHERE transactionid = v_transid) THEN
  SELECT COALESCE(clid, 0), COALESCE(rechargeamount, ''), COALESCE(mobileno, ''), COALESCE(operatortype, '') INTO v_clid, v_rechamount, v_mobileno, v_operatorcode FROM dbo.tbl_customer_prepaid_recharges WHERE transactionid = v_transid;
  RETURN QUERY SELECT COALESCE(fname, '') || ' ' || COALESCE(lname, '') AS name, COALESCE(emailid, '') AS emailid, COALESCE(clid, 0) AS clid, v_mobileno AS mobileno, v_rechamount AS amount, v_operatorcode AS operatorcode FROM dbo.tbl_customerlogin WHERE clid = v_clid;
  END IF;
  IF EXISTS(SELECT 1 FROM dbo.tbl_customer_dth_recharges WHERE transactionid = v_transid) THEN
  SELECT COALESCE(clid, 0), COALESCE(rechargeamount, ''), COALESCE(mobileno, ''), COALESCE(operatortype, '') INTO v_clid, v_rechamount, v_mobileno, v_operatorcode FROM dbo.tbl_customer_dth_recharges WHERE transactionid = v_transid;
  RETURN QUERY SELECT COALESCE(fname, '') || ' ' || COALESCE(lname, '') AS name, COALESCE(emailid, '') AS emailid, COALESCE(clid, 0) AS clid, v_mobileno AS mobileno, v_rechamount AS amount, v_operatorcode AS operatorcode FROM dbo.tbl_customerlogin WHERE clid = v_clid;
  END IF;
  IF EXISTS(SELECT 1 FROM dbo.tbl_customer_electricity_recharges WHERE transactionid = v_transid) THEN
  SELECT COALESCE(clid, 0), COALESCE(rechargeamount, ''), COALESCE(mobileno, ''), COALESCE(operatortype, '') INTO v_clid, v_rechamount, v_mobileno, v_operatorcode FROM dbo.tbl_customer_electricity_recharges WHERE transactionid = v_transid;
  RETURN QUERY SELECT COALESCE(fname, '') || ' ' || COALESCE(lname, '') AS name, COALESCE(emailid, '') AS emailid, COALESCE(clid, 0) AS clid, v_mobileno AS mobileno, v_rechamount AS amount, v_operatorcode AS operatorcode FROM dbo.tbl_customerlogin WHERE clid = v_clid;
  END IF;
  IF EXISTS(SELECT 1 FROM dbo.tbl_customer_gas_recharges WHERE transactionid = v_transid) THEN
  SELECT COALESCE(clid, 0), COALESCE(rechargeamount, ''), COALESCE(mobileno, ''), COALESCE(operatortype, '') INTO v_clid, v_rechamount, v_mobileno, v_operatorcode FROM dbo.tbl_customer_gas_recharges WHERE transactionid = v_transid;
  RETURN QUERY SELECT COALESCE(fname, '') || ' ' || COALESCE(lname, '') AS name, COALESCE(emailid, '') AS emailid, COALESCE(clid, 0) AS clid, v_mobileno AS mobileno, v_rechamount AS amount, v_operatorcode AS operatorcode FROM dbo.tbl_customerlogin WHERE clid = v_clid;
  END IF;
  IF EXISTS(SELECT 1 FROM dbo.tbl_customer_insurance_recharges WHERE transactionid = v_transid) THEN
  SELECT COALESCE(clid, 0), COALESCE(rechargeamount, ''), COALESCE(mobileno, ''), COALESCE(operatortype, '') INTO v_clid, v_rechamount, v_mobileno, v_operatorcode FROM dbo.tbl_customer_insurance_recharges WHERE transactionid = v_transid;
  RETURN QUERY SELECT COALESCE(fname, '') || ' ' || COALESCE(lname, '') AS name, COALESCE(emailid, '') AS emailid, COALESCE(clid, 0) AS clid, v_mobileno AS mobileno, v_rechamount AS amount, v_operatorcode AS operatorcode FROM dbo.tbl_customerlogin WHERE clid = v_clid;
  END IF;
  END IF;
END;
$$;


