--
-- Name: usp_getcustomerkycstatus(integer, character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_getcustomerkycstatus(v_clid integer DEFAULT 1, INOUT v_stroutput character varying DEFAULT ''::character varying) RETURNS character varying
    LANGUAGE plpgsql
    AS $$
BEGIN
  BEGIN
  IF (v_clid <> 0) THEN
  IF NOT EXISTS(SELECT 1 FROM tbl_customerlogin WHERE clid = v_clid) THEN
  v_stroutput := 'Invalid customer';
  RETURN;
  ELSE
  IF EXISTS(SELECT 1 FROM tbl_customer_kyc WHERE clid = v_clid) THEN
  IF ((SELECT COUNT(1) FROM tbl_customer_kyc WHERE clid = v_clid) > 1) THEN
  IF (EXISTS(SELECT 1 FROM tbl_customer_kyc WHERE clid = v_clid AND isaprove = 1)) THEN
  v_stroutput := 'Approved';
  RETURN;
  ELSE
  v_stroutput := 'Not approved';
  RETURN;
  END IF;
  ELSE
  v_stroutput := 'KYC not submitted';
  RETURN;
  END IF;
  ELSE
  v_stroutput := 'KYC not submitted';
  RETURN;
  END IF;
  END IF;
  END IF;
  EXCEPTION WHEN OTHERS THEN
  IF (0 <> 0) THEN
  v_stroutput := 'Error';
  RETURN;
  END IF;
  END;
END;
$$;


--
-- Name: usp_getcustomerpreviousrecharges(integer, character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_getcustomerpreviousrecharges(v_clid integer DEFAULT 1, v_operatorservicetype character varying DEFAULT 'MOBILE'::character varying) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF (v_clid <> 0) THEN
  IF (v_operatorservicetype = 'MOBILE') THEN
  RETURN QUERY SELECT COALESCE(clid, 0) AS clid, COALESCE(mobileno, '') AS mobileno, COALESCE(operatortype, '') AS operatortype, COALESCE(operatorname, '') AS operatorname, COALESCE(operatorcode, '') AS operatorcode, COALESCE(operatorservice, '') AS operatorservice, COALESCE(rechargeamount, 0) AS rechargeamount, REPLACE(CAST(TO_CHAR(rechargedate, 'DD TMMon YYYY') AS VARCHAR(11)), ' ', '-') || ' ' || STUFF(RIGHT(CAST(CAST(TO_CHAR(rechargedate, 'TMMon DD YYYY FMHH12:MI%p') AS VARCHAR(30)) AS TEXT), 7), 6, 0, ' ') AS rechargedate, COALESCE(rechargestatus, '') AS rechargestatus, responsedate, COALESCE(responseremarks, '') AS responseremarks, COALESCE(transactionid, '') AS transactionid, COALESCE(apitransactionid, '') AS apitransactionid FROM dbo.tbl_customer_prepaid_recharges WHERE clid = v_clid AND rechargestatus = 'SUCCESS' LIMIT 3;
  END IF;
  IF (v_operatorservicetype = 'POSTPAID') THEN
  RETURN QUERY SELECT COALESCE(clid, 0) AS clid, COALESCE(mobileno, '') AS mobileno, COALESCE(operatortype, '') AS operatortype, COALESCE(operatorname, '') AS operatorname, COALESCE(operatorcode, '') AS operatorcode, COALESCE(operatorservice, '') AS operatorservice, COALESCE(rechargeamount, 0) AS rechargeamount, REPLACE(CAST(TO_CHAR(rechargedate, 'DD TMMon YYYY') AS VARCHAR(11)), ' ', '-') || ' ' || STUFF(RIGHT(CAST(CAST(TO_CHAR(rechargedate, 'TMMon DD YYYY FMHH12:MI%p') AS VARCHAR(30)) AS TEXT), 7), 6, 0, ' ') AS rechargedate, COALESCE(rechargestatus, '') AS rechargestatus, responsedate, COALESCE(responseremarks, '') AS responseremarks, COALESCE(transactionid, '') AS transactionid, COALESCE(apitransactionid, '') AS apitransactionid FROM dbo.tbl_customer_postpaid_recharges WHERE clid = v_clid AND rechargestatus = 'SUCCESS' LIMIT 3;
  END IF;
  IF (v_operatorservicetype = 'GAS') THEN
  RETURN QUERY SELECT COALESCE(clid, 0) AS clid, COALESCE(mobileno, '') AS mobileno, COALESCE(operatortype, '') AS operatortype, COALESCE(operatorname, '') AS operatorname, COALESCE(operatorcode, '') AS operatorcode, COALESCE(operatorservice, '') AS operatorservice, COALESCE(rechargeamount, 0) AS rechargeamount, REPLACE(CAST(TO_CHAR(rechargedate, 'DD TMMon YYYY') AS VARCHAR(11)), ' ', '-') || ' ' || STUFF(RIGHT(CAST(CAST(TO_CHAR(rechargedate, 'TMMon DD YYYY FMHH12:MI%p') AS VARCHAR(30)) AS TEXT), 7), 6, 0, ' ') AS rechargedate, COALESCE(rechargestatus, '') AS rechargestatus, responsedate, COALESCE(responseremarks, '') AS responseremarks, COALESCE(transactionid, '') AS transactionid, COALESCE(apitransactionid, '') AS apitransactionid FROM dbo.tbl_customer_gas_recharges WHERE clid = v_clid AND rechargestatus = 'SUCCESS' LIMIT 3;
  END IF;
  IF (v_operatorservicetype = 'ELECTRICITY') THEN
  RETURN QUERY SELECT COALESCE(clid, 0) AS clid, COALESCE(mobileno, '') AS mobileno, COALESCE(operatortype, '') AS operatortype, COALESCE(operatorname, '') AS operatorname, COALESCE(operatorcode, '') AS operatorcode, COALESCE(operatorservice, '') AS operatorservice, COALESCE(rechargeamount, 0) AS rechargeamount, REPLACE(CAST(TO_CHAR(rechargedate, 'DD TMMon YYYY') AS VARCHAR(11)), ' ', '-') || ' ' || STUFF(RIGHT(CAST(CAST(TO_CHAR(rechargedate, 'TMMon DD YYYY FMHH12:MI%p') AS VARCHAR(30)) AS TEXT), 7), 6, 0, ' ') AS rechargedate, COALESCE(rechargestatus, '') AS rechargestatus, responsedate, COALESCE(responseremarks, '') AS responseremarks, COALESCE(transactionid, '') AS transactionid, COALESCE(apitransactionid, '') AS apitransactionid FROM dbo.tbl_customer_electricity_recharges WHERE clid = v_clid AND rechargestatus = 'SUCCESS' LIMIT 3;
  END IF;
  IF (v_operatorservicetype = 'DTH') THEN
  RETURN QUERY SELECT COALESCE(clid, 0) AS clid, COALESCE(mobileno, '') AS mobileno, COALESCE(operatortype, '') AS operatortype, COALESCE(operatorname, '') AS operatorname, COALESCE(operatorcode, '') AS operatorcode, COALESCE(operatorservice, '') AS operatorservice, COALESCE(rechargeamount, 0) AS rechargeamount, REPLACE(CAST(TO_CHAR(rechargedate, 'DD TMMon YYYY') AS VARCHAR(11)), ' ', '-') || ' ' || STUFF(RIGHT(CAST(CAST(TO_CHAR(rechargedate, 'TMMon DD YYYY FMHH12:MI%p') AS VARCHAR(30)) AS TEXT), 7), 6, 0, ' ') AS rechargedate, COALESCE(rechargestatus, '') AS rechargestatus, responsedate, COALESCE(responseremarks, '') AS responseremarks, COALESCE(transactionid, '') AS transactionid, COALESCE(apitransactionid, '') AS apitransactionid FROM dbo.tbl_customer_dth_recharges WHERE clid = v_clid AND rechargestatus = 'SUCCESS' LIMIT 3;
  END IF;
  END IF;
END;
$$;


