CREATE FUNCTION dbo.usp_getcustomerreviews(v_loginid character varying DEFAULT '23238815'::character varying, v_message character varying DEFAULT 'NO REVIEWS'::character varying) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
BEGIN
  BEGIN
  RETURN QUERY SELECT rwid, pmid, name, emailid, reviewtitle, reviewdesc, stars, date, status, productimages, mp.producttitle FROM tbl_reviewmaster AS rm LEFT JOIN ims_subproduct AS sp ON sp.mprid = rm.pmid LEFT JOIN ims_masterproduct AS mp ON mp.mprid = sp.mprid WHERE emailid = v_loginid;
