--
-- Name: usp_getcustomerticketslist(integer, integer, integer, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_getcustomerticketslist(v_startrowindex integer DEFAULT 1, v_maxrows integer DEFAULT 100, v_clid integer DEFAULT 0, v_totalcount integer DEFAULT 0) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_minindex INT;
  v_maxindex INT;
  v_query text;
BEGIN
  v_minindex := (v_startrowindex - 1) * v_maxrows + 1;
  v_maxindex := v_startrowindex * v_maxrows;
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp (NUMBER bigint GENERATED BY DEFAULT AS IDENTITY,
TMID int,
TICKETNO VARCHAR(100),
CREATEDATE VARCHAR(100),
CATEGORYNAME VARCHAR(100),
LASTUPDATEDATE VARCHAR(100),
SUBJECT  VARCHAR(100),
STATUS VARCHAR(100)) ON COMMIT DROP;
  v_query := 'INSERT INTO #Temp SELECT 
TMID,TICKETNO,CONVERT(VARCHAR(11),DATE,106)AS CREATEDATE,CATEGORYNAME, CONVERT(VARCHAR(20),LASTUPDATE,106) AS LASTUPDATEDATE,
SUBJECT,SM.Name AS STATUS FROM TBL_TICKETMASTER TM INNER JOIN TBL_STATUSMASTER SM
ON SM.ID=TM.STATUS Where FROMPLID=''' || CAST(v_clid AS VARCHAR(30)) || ''' and ACCOUNTTYPE=2 ORDER BY DATE DESC  ';
  EXECUTE v_query;
  RAISE NOTICE '%', v_query;
  RETURN QUERY SELECT * FROM tmp_temp WHERE number BETWEEN v_minindex AND v_maxindex;
  SELECT COUNT(number) INTO v_totalcount FROM tmp_temp;
  DROP TABLE IF EXISTS tmp_temp;
  -- SET option (removed)
END;
$$;


--
-- Name: usp_getcustomerwallet(integer, character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_getcustomerwallet(v_clid integer DEFAULT 1, v_stroutput character varying DEFAULT ''::character varying) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF (v_clid > 0) THEN
  IF EXISTS(SELECT COUNT(1) FROM tbl_customerlogin WHERE clid = v_clid) THEN
  IF ((SELECT COUNT(1) FROM tbl_customerwallet WHERE clid = v_clid) > 0) THEN
  RETURN QUERY SELECT COALESCE(availablebalance, 0.00) AS availablebalance FROM tbl_customerwallet WHERE clid = v_clid;
  v_stroutput := 'SUCCESS';
  ELSE
  RETURN QUERY SELECT 0.00 AS availablebalance;
  v_stroutput := 'SUCCESS';
  END IF;
  ELSE
  v_stroutput := 'Invalid customer';
  RETURN;
  END IF;
  END IF;
END;
$$;


--
-- Name: usp_getcustomerwallet_statements(integer, integer, integer, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_getcustomerwallet_statements(v_clid integer DEFAULT 1, v_startrowindex integer DEFAULT 1, v_maxrows integer DEFAULT 20, v_totalcount integer DEFAULT 0) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_minindex INT;
  v_maxindex INT;
  v_query text;
BEGIN
  v_query := '';
  v_minindex := (v_startrowindex - 1) * v_maxrows + 1;
  v_maxindex := v_startrowindex * v_maxrows;
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp (ROWNUMBER BIGINT GENERATED BY DEFAULT AS IDENTITY, 
	CLID BIGINT,       
	PROCESSDATE varchar(100),         
	CRDRTYPE VARCHAR(100),	
	CRAMT DECIMAL(18,2),
	DRAMT DECIMAL(18,2),
	OLD_BALANCE   DECIMAL(18,2),	
	BALANCE DECIMAL(18,2),	
	REMARKS VARCHAR(100),
	TRACENO VARCHAR(100),
	STATUS int,
	TCWSID int) ON COMMIT DROP;
  IF (v_clid <> 0) THEN
  v_query := 'INSERT INTO #TEMP SELECT STATEMENTS.CLID,
	 REPLACE(CONVERT(VARCHAR(11), STATEMENTS.PROCESSDATE, 106), '' '', ''-'') +'' ''+STUFF(RIGHT( CONVERT(VARCHAR,STATEMENTS.PROCESSDATE,100 ) ,7), 6, 0, '' '') PROCESSDATE,	 
	 STATEMENTS.CRDRTYPE,STATEMENTS.CRAMT,STATEMENTS.DRAMT,STATEMENTS.OLD_BALANCE,STATEMENTS.BALANCE,
	 STATEMENTS.REMARKS,STATEMENTS.TRACENO,
	 (CASE WHEN TRANSBANK.TRANSACTIONID=STATEMENTS.TRACENO THEN TRANSBANK.STATUS ELSE STATEMENTS.STATUS END) AS STATUS,STATEMENTS.TCWSID
	 --STATUS
	 FROM TBL_CUSTOMERWALLET_STATEMENTS STATEMENTS   
	 LEFT JOIN DBO.TBL_CUSTOMER_TRANSFERTOBANK TRANSBANK 
	 ON STATEMENTS.TRACENO=TRANSBANK.TRANSACTIONID
	 WHERE STATEMENTS.CLID=''' || CAST(v_clid AS VARCHAR(100)) || '''
	 ORDER BY STATEMENTS.PROCESSDATE DESC';
  EXECUTE v_query;
  RETURN QUERY SELECT * FROM tmp_temp WHERE rownumber BETWEEN v_minindex AND v_maxindex;
  SELECT COUNT(rownumber) INTO v_totalcount FROM tmp_temp;
  DROP TABLE IF EXISTS tmp_temp;
  END IF;
END;
$$;


