--
-- Name: usp_getddlmaster(character varying, integer, character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_getddlmaster(v_type character varying, v_id integer, v_cat_name character varying) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_subcatid int;
  v_catid int;
  v_maincatid int;
BEGIN
  IF (v_type = 'mcat') THEN
  RETURN QUERY SELECT ddl_id, parent_ddl_id, ddl_name, ddl_name_id, ddl_text, ddl_value, isactive, create_date, maincategoryid, subcategoryid, categoryid, title FROM tbl_ddl_master WHERE maincategoryid = v_id AND categoryid = 0 AND subcategoryid = 0;
  END IF;
  IF (v_type = 'cat') THEN
  SELECT maincatid INTO v_maincatid FROM tbl_category WHERE catid = v_id;
  RETURN QUERY SELECT ddl_id, parent_ddl_id, ddl_name, ddl_name_id, ddl_text, ddl_value, isactive, create_date, maincategoryid, subcategoryid, categoryid, title FROM tbl_ddl_master WHERE (categoryid = v_id AND subcategoryid = 0 AND maincategoryid = v_maincatid) OR (maincategoryid = v_maincatid AND categoryid = 0 AND subcategoryid = 0);
  END IF;
  IF (v_type = 'subcat') THEN
  SELECT maincatid, catid INTO v_maincatid, v_catid FROM dbo.tbl_sub_category WHERE subcatid = v_id;
  RETURN QUERY SELECT ddl_id, parent_ddl_id, ddl_name, ddl_name_id, ddl_text, ddl_value, isactive, create_date, maincategoryid, subcategoryid, categoryid, title FROM tbl_ddl_master WHERE subcategoryid = v_id OR (categoryid = v_catid AND subcategoryid = 0) OR (maincategoryid = v_maincatid AND categoryid = 0 AND subcategoryid = 0);
  END IF;
END;
$$;


