  RETURN QUERY SELECT pr.product_name AS name, pr.product_qty AS quantity, pr.total_bv AS bv, total_cost AS amount, pr.total_payble_vat AS gst, CAST(TO_CHAR(om.orderdate, 'MM-DD-YYYY') AS VARCHAR(20)) AS orderdate, pr.status AS orderstatus, pr.orderno AS orderid, d.userid AS resellerid FROM tbl_product_order_master AS pr INNER JOIN tbl_order_master AS om ON om.orderid = pr.orderid INNER JOIN tbl_customerlogin AS cl ON pr.loginid = cl.loginid INNER JOIN tbl_distributor AS d ON d.did = cl.did WHERE cl.userid = v_username;
