--
-- Name: usp_getdetails_reseller_wallettype(integer, integer, character varying, character varying, character varying, integer, character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_getdetails_reseller_wallettype(v_startrowindex integer DEFAULT 1, v_maxrows integer DEFAULT 100, v_fromdate character varying DEFAULT ''::character varying, v_todate character varying DEFAULT ''::character varying, v_walletname character varying DEFAULT ''::character varying, v_totalcount integer DEFAULT 0, v_pmid character varying DEFAULT '10'::character varying) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_minindex INT;
  v_maxindex INT;
  v_query text;
BEGIN
  BEGIN
  v_minindex := (v_startrowindex - 1) * v_maxrows + 1;
  v_maxindex := v_startrowindex * v_maxrows;
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp (ROW_NUMBER int,
DATE timestamp,
WALLETNAME VARCHAR(100),
MAXUSEPER decimal(18,8),
ISRETURN  VARCHAR(100),
RWTID int) ON COMMIT DROP;
  v_query := 'INSERT INTO #Temp select ROW_NUMBER() over(order by RWTID desc) as ROW_NUMBER,LAST_MODIFIED as Date,WALLETNAME,MAXUSEPER,case when ISRETURN=1 then ''Allowed'' else ''Not Allowed'' end as ISRETURN,
			RWTID  FROM TBL_RESELLER_WALLETTYPE where PMID=cast(''' || v_pmid || ''' as int) ';
  IF (v_walletname <> '') THEN
  v_query := v_query || ' And WALLETNAME = ''' || v_walletname || '''';
  END IF;
  RAISE NOTICE '%', v_query;
  IF ((v_fromdate <> '') AND (v_fromdate = '')) THEN
  v_query := v_query || ' AND CONVERT(DATE, LAST_MODIFIED) =  CONVERT(DATE, ''' || v_fromdate || ''')';
  END IF;
  IF ((v_fromdate = '') AND (v_todate <> '')) THEN
  v_query := v_query || ' AND CONVERT(DATE, LAST_MODIFIED) =  CONVERT(DATE, ''' || v_todate || ''') ';
  END IF;
  IF ((v_fromdate <> '') AND (v_todate <> '')) THEN
  v_query := v_query || ' AND CONVERT(DATE, LAST_MODIFIED) BETWEEN CONVERT(DATE, ''' || v_fromdate || ''') AND  CONVERT(DATE, ''' || v_todate || ''') ';
  END IF;
  EXECUTE v_query;
  RETURN QUERY SELECT * FROM tmp_temp WHERE row_number BETWEEN v_minindex AND v_maxindex;
  SELECT COUNT(row_number) INTO v_totalcount FROM tmp_temp;
  DROP TABLE IF EXISTS tmp_temp;
  -- SET option (removed)
  EXCEPTION WHEN OTHERS THEN
  PERFORM dbo.sp_errorlog();
  IF (0 > 0) THEN
  -- ROLLBACK (removed)
  END IF;
  RETURN;
  END;
END;
$$;


--
-- Name: usp_getdetailsresellerwalletrequest(integer, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_getdetailsresellerwalletrequest(v_rwrid integer DEFAULT 0, v_pmid integer DEFAULT 0) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
BEGIN
  RETURN QUERY SELECT CAST(TO_CHAR(rw.date, 'DD-MM-YYYY') AS VARCHAR(10)) AS requestdate, dm.companyname || '(' || td.userid || ')' AS username, dm.mobileno, dm.comemailid AS email, rw.amount, rw.bankname, rw."ifsc code" AS ifsccode, rw.sys_tranid AS tranno, rw.image AS image, CASE WHEN rw.paymode = 1 THEN 'Bank' WHEN rw.paymode = 9 THEN 'DD' WHEN rw.paymode = 10 THEN 'Cheque' WHEN rw.paymode = 11 THEN 'NEFT' WHEN rw.paymode = 12 THEN 'RTGS' END AS paymode, CASE WHEN rw.status = 1 THEN 'Pending' WHEN rw.status = 2 THEN 'Approved' WHEN rw.status = 3 THEN 'Rejected' END AS status, rw.mem_remark AS comremark, rw.rwrid, rw.pmid FROM tbl_resellerwalletrequest AS rw INNER JOIN tbl_distributor AS td ON rw.pmid = td.pmid INNER JOIN distributor_master AS dm ON dm.pmid = rw.pmid LEFT JOIN tbl_employee_master AS em ON em.emp_id = rw.status_update_from WHERE rw.rwrid = v_rwrid AND rw.pmid = v_pmid;
END;
$$;


