--
-- Name: usp_getemailid(bigint, character varying, character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_getemailid(v_pmid bigint, v_mode character varying, INOUT v_strresult character varying) RETURNS character varying
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_optid int;
  v_loginid varchar(200);
BEGIN
  v_strresult := '';
  IF (v_mode = 'verify') THEN
  SELECT COALESCE(optid, 0) INTO v_optid FROM portal_master WHERE pmid = v_pmid;
  END IF;
  IF (v_optid = 0) THEN
  SELECT loginid INTO v_loginid FROM portal_login WHERE pmid = v_pmid;
  v_strresult := v_loginid;
  RETURN;
  END IF;
  IF (v_mode = 'panel') THEN
  SELECT COALESCE(loginid, '') INTO v_loginid FROM portal_login WHERE plid = v_pmid;
  v_strresult := v_loginid;
  RETURN;
  END IF;
  IF (0 <> 0) THEN
  v_strresult := '';
  RETURN;
  END IF;
END;
$$;


