ipdeatils varchar(200)) ON COMMIT DROP;
  v_sqlquery := '';
  v_sqlquery := 'insert into #temp select ROW_NUMBER() OVER(ORDER BY tt.maildate desc) as rowNumber,  tt.piid,tt.pmid,pm.title,tt.ccname,tt.ccemailid,tt.message, (convert(varchar(20),tt.maildate,105)+'' ''+convert(varchar(20),tt.maildate,108)) as maildate
,

tt.remark,(convert(varchar(20),tt.remarkdate,105)+'' ''+convert(varchar(20),tt.remarkdate,108)) as remarkdate,tt.ipaddress,(''City: ''+tt.ipcity+'',State: ''+tt.ipstate+'',Country : ''+tt.ipcountry) as ipdeatils  

FROM portal_inbox tt INNER JOIN  (SELECT pmid, MAX(maildate) AS MaxDateTime  FROM portal_inbox  GROUP BY pmid) groupedtt 

ON tt.pmid = groupedtt.pmid AND tt.maildate = groupedtt.MaxDateTime inner join portal_master pm on pm.pmid=tt.pmid ';
  IF (v_fromdate = '' OR v_todate = '') THEN
  IF (v_fromdate <> '') THEN
  v_sqlquery := v_sqlquery || ' and convert(date,tt.maildate,103)= replace(convert(date,''' || v_fromdate || ''',103),''/'',''-'') ';
  END IF;
  IF (v_todate <> '') THEN
  v_sqlquery := v_sqlquery || ' and convert(date, tt.maildate,103)  =replace(convert(date,''' || v_todate || ''',103),''/'',''-'') ';
  END IF;
  END IF;
  IF (v_fromdate <> '' AND v_todate <> '') THEN
  v_sqlquery := v_sqlquery || ' and  convert(date, tt.maildate,103)  between  replace(convert(date,''' || v_fromdate || ''',103),''/'',''-'')  and replace(convert(date,''' || v_todate || ''',103),''/'',''-'')';
  END IF;
  IF (v_searchfield = 'business') THEN
  v_sqlquery := v_sqlquery || ' and pm.title like ''%' || v_searchvalue || '%''';
  END IF;
  EXECUTE v_sqlquery;
  SELECT COUNT(*) INTO v_recordcount FROM tmp_temp;
  RETURN QUERY SELECT * FROM tmp_temp WHERE rownumber BETWEEN v_startrowindex AND v_maxrows;
  DROP TABLE IF EXISTS tmp_temp;
  RETURN QUERY SELECT v_recordcount AS recordcount;
  -- SET option (removed)
END;
$$;


--
-- Name: usp_getenquirydetailsbypmid(bigint, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_getenquirydetailsbypmid(v_pmid bigint DEFAULT 0, v_piid integer DEFAULT 0) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF (v_pmid > 0) THEN
  RETURN QUERY SELECT ROW_NUMBER() OVER (ORDER BY piid DESC NULLS LAST) AS rownumber, piid, ccname, mobile, ccemailid, message, (ipcity || ',' || ipstate || ',' || ipcountry) AS address, (CAST(TO_CHAR(maildate, 'DD-MM-YYYY') AS VARCHAR(24))) AS maildate, remark, pmid FROM portal_inbox WHERE pmid = v_pmid AND active = 1 ORDER BY piid DESC NULLS LAST;
  END IF;
  IF (v_piid <> '') THEN
  RETURN QUERY SELECT piid, ccname, mobile, ccemailid, message, (ipcity || ' , ' || ipstate || ' , ' || ipcountry) AS address, (CAST(TO_CHAR(maildate, 'DD-MM-YYYY') AS VARCHAR(24))) AS maildate, COALESCE(remark, '-') AS remark, pmid FROM portal_inbox WHERE piid = v_piid ORDER BY piid DESC NULLS LAST;
  END IF;
END;
$$;


--
-- Name: usp_getewalletdetails(bigint); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_getewalletdetails(v_plid bigint) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_recordcount int;
  v_amount numeric(19,4);
  v_currencysymbol varchar(20);
  v_totalamount numeric(19,4);
  v_sqlquery text;
BEGIN
  v_sqlquery := '';
  SELECT amount, currencysymbol, (referalcommission + redemption + cramount) INTO v_amount, v_currencysymbol, v_totalamount FROM ewallet WHERE plid = v_plid;
  SELECT currencysymbol INTO v_currencysymbol FROM portal_login WHERE plid = v_plid;
  RETURN QUERY SELECT v_recordcount AS recordcount, COALESCE(v_amount, 0) AS currentamouunt, v_currencysymbol AS currencysymbol, COALESCE(v_totalamount, 0) AS totalamount;
END;
$$;


--
-- Name: usp_getfavdealslist(integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_getfavdealslist(v_plid integer DEFAULT 0) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
BEGIN
  RETURN QUERY SELECT pdm.dealid, (SELECT COUNT(rwid) FROM tbl_reviewmasterdeal WHERE dealid = sa.dealsid) AS reviewcount, (SELECT dbo.FINDTOTALREATING_DEAL(sa.dealsid)) AS review, COALESCE(pdm.title, '') AS title, COALESCE(pdm.offer, '') AS offer, COALESCE(pdm.images, '') AS images, COALESCE(pdm.description, '') AS description, COALESCE(pdm.discount, '') AS discount, COALESCE(pdm.startprice, '') AS startprice, COALESCE(pdm.fromtime, '') AS fromtime, COALESCE(pdm.totime, '') AS totime, COALESCE(pdm.terms, '') AS terms, COALESCE(pdm.highlights, '') AS highlights, COALESCE(CAST(TO_CHAR(pdm.createdate, 'DD TMMon YYYY') AS VARCHAR(11)), '') AS createdate, COALESCE(pdm.active, '') AS active, COALESCE(pdm.verify, '') AS verify, COALESCE(CAST(TO_CHAR(approveddate, 'DD TMMon YYYY') AS VARCHAR(11)), '') AS approveddate, COALESCE(CAST(TO_CHAR(pdm.rejectdate, 'DD TMMon YYYY') AS VARCHAR(11)), '') AS rejectdate, COALESCE(pdm.rejectreason, '') AS rejectreason, REPLACE(REPLACE(dbo.GENRATINGDEALLISTINGSURL(pdm.dealid), '/', '/'), '''', '+opos') AS url FROM portal_deal_master AS pdm INNER JOIN saved_ad AS sa ON pdm.dealid = sa.dealsid WHERE sa.plid = v_plid AND pdm.active = 1 AND pdm.verify = 1 AND CAST(CURRENT_TIMESTAMP AS DATE) BETWEEN CAST(pdm.fromtime AS DATE) AND CAST(pdm.totime AS DATE);
END;
$$;


--
-- Name: usp_getfavlistingsofmember(bigint, integer, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_getfavlistingsofmember(v_plid bigint, v_pageno integer DEFAULT 1, v_pagesize integer DEFAULT 30) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_minindex INT;
  v_maxindex INT;
  v_noofrec INT;
BEGIN
  -- SET option (removed)
  v_minindex := 0;
  v_maxindex := 0;
  v_noofrec := 0;
  v_minindex := ((v_pageno - 1) * v_pagesize) + 1;
  v_maxindex := (v_pageno * v_pagesize);
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp (ROWNUMBER INT GENERATED BY DEFAULT AS IDENTITY,
   ACTIVE INT,
   COMPANYNAME VARCHAR(500),
   COMPANYIMAGE VARCHAR(500),
   PMID BIGINT,
   TITLE VARCHAR(500),
   MOBILENO VARCHAR(100),
   WEBSITEURL VARCHAR(100),
   COMPANYDESC text,
   ADDRESS text,
   ACCOUNTTYPE INT,
   COMEMAILID VARCHAR(300),
   YEAROFESTABLE VARCHAR(50),
   COMPLETEADDRESS text,
   URL text,
   ALLKEYWORD text,
   AVGRATING INT,
   TOTALREVIEWS INT) ON COMMIT DROP;
  INSERT INTO tmp_temp SELECT COALESCE(p.active, 0), p.companyname, p.companyimage, p.pmid, p.title, p.mobileno, COALESCE(p.url, '') AS websiteurl, p.companydesc, COALESCE(p.address, 'N/A') AS address, p.accounttype, p.comemailid, p.yearofestable, (p.address || ',' || CASE WHEN p.lankmark IS NULL THEN '-' WHEN p.lankmark = '' THEN '-' ELSE p.lankmark END || ',' || p.areaname || ',' || ct.cityname || ',' || p.pincode) AS completeaddress, COALESCE(CASE COALESCE(p.active, 0) WHEN 1 THEN (LOWER('../business-details/' || REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(RTRIM(LTRIM(REPLACE(p.title, '.', ''))) || ' ' || RTRIM(LTRIM(pc.catname)) || ' IN ' || RTRIM(LTRIM(ct.cityname)) || '-IN-' || RTRIM(LTRIM(c.countryname)) || '-' || CAST(p.pmid AS VARCHAR(50)), ' ', '-'), '&', 'and'), '/', '-'), '|', '-'), '#', '-'), '*', '-'), ':', '-'), '+', 'plus'))) WHEN 0 THEN '#' END, '') AS url, dbo.BINDINGKEYWORDLIST(p.pmid) AS allkeyword, dbo.FINDTOTALREATING(p.pmid) AS avgrating, (SELECT COUNT(rwid) FROM tbl_reviewmaster WHERE pmid = p.pmid AND status = 1 AND reviewtype = 1) AS totalreviews FROM portal_master AS p INNER JOIN saved_ad AS tp ON p.pmid = tp.pmid LEFT JOIN country AS c ON p.cid = c.cid LEFT JOIN portal_login AS pl ON pl.pmid = p.pmid LEFT JOIN city AS ct ON p.ctid = ct.ctid LEFT JOIN product_category AS pc ON pc.catid = CAST(SUBSTRING((p.catid || ',') FROM 0 FOR CAST(POSITION(',' IN (p.catid || ',')) AS INT)) AS INT) WHERE COALESCE(p.pmid, 0) > 0 AND tp.plid = v_plid;
  SELECT COUNT(1) INTO v_noofrec FROM tmp_temp;
  RETURN QUERY SELECT *, v_noofrec AS noofrec FROM tmp_temp WHERE rownumber BETWEEN v_minindex AND v_maxindex;
  DROP TABLE IF EXISTS tmp_temp;
  -- SET option (removed)
END;
$$;


--
-- Name: usp_getfundreports(integer, integer, character varying, boolean, character varying, character varying, character varying, character varying, character varying, character varying, character varying, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_getfundreports(v_startrowindex integer DEFAULT 0, v_maxrows integer DEFAULT 100, v_orderbyfield character varying DEFAULT ''::character varying, v_asc boolean DEFAULT false, v_searchfield character varying DEFAULT ''::character varying, v_searchvalue character varying DEFAULT ''::character varying, v_cid character varying DEFAULT ''::character varying, v_fromdate character varying DEFAULT ''::character varying, v_todate character varying DEFAULT ''::character varying, v_reqtype character varying DEFAULT ''::character varying, v_mode character varying DEFAULT ''::character varying, v_recordcount integer DEFAULT 0) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_regno BIGINT;
  v_sqlquery text;
  v_modestatus varchar(10);
BEGIN
  -- SET option (removed)
  v_sqlquery := '';
  v_modestatus := '0';
  DROP TABLE IF EXISTS tmp_newtemp;
  CREATE TEMP TABLE tmp_newtemp (ROWNUMBER Int,
RECORDDATE timestamp,
LOGINID VARCHAR(200),
REQTITLE VARCHAR(100),
REQTYPE VARCHAR(100),
PAYMODE VARCHAR(100),
CURRENCYSYMBOL VARCHAR(10),
PAIDAMOUNT numeric(19,4),
COUNTRY VARCHAR(50),
RECORDID BIGINT,
CHECKSTATUS VARCHAR(20) DEFAULT(''),
PLID BIGINT DEFAULT(0),
CHECK_SNO VARCHAR(50) DEFAULT(''),
BILLID VARCHAR DEFAULT(''),
UserName text) ON COMMIT DROP;
  v_sqlquery := '';
  IF (v_mode = 'PENDING') THEN
  v_modestatus := '0';
  END IF;
  IF (v_mode = 'PENDING') THEN
  v_sqlquery := 'INSERT INTO #NEWTEMP Select ROW_NUMBER() OVER(ORDER BY TFAAMID DESC) AS ROWNUMBER,
Convert(Varchar(11),AddedDate,106)As AddedDate,
PL.LOGINID,
(''Add Fund''),
(''Add Fund''),
Mode,
''Rs'',
ISNULL(Amount,0.00)As Amount,
''India'',
TFAAMID,
Status,
Tbl_FundAddedApprovalMaster.PLID
,(Case When ChequeNumber='''' Then ''N/A'' Else ChequeNumber End)As ChequeNumber,
1,
PL.USERNAME
From Tbl_FundAddedApprovalMaster INNER JOIN PORTAL_LOGIN PL ON PL.PLID=Tbl_FundAddedApprovalMaster.PLID
Where Tbl_FundAddedApprovalMaster.IsActive=1 ';
  IF (v_orderbyfield = 'DATEDESC') THEN
  v_sqlquery := v_sqlquery || ' ORDER BY AddedDate DESC ';
  END IF;
  IF (v_orderbyfield = 'DATEASC') THEN
  v_sqlquery := v_sqlquery || ' ORDER BY AddedDate ASC ';
  END IF;
  RAISE NOTICE '%', v_sqlquery;
  EXECUTE v_sqlquery;
  RETURN QUERY SELECT * FROM tmp_newtemp;
  SELECT COUNT(*) INTO v_recordcount FROM tmp_newtemp;
  RETURN QUERY SELECT v_recordcount AS recordcount;
  DROP TABLE IF EXISTS tmp_newtemp;
  -- SET option (removed)
  END IF;
END;
$$;


--
-- Name: usp_getfundreports_withdrawal(integer, integer, character varying, boolean, character varying, character varying, character varying, character varying, character varying, character varying, character varying, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_getfundreports_withdrawal(v_startrowindex integer, v_maxrows integer, v_orderbyfield character varying, v_asc boolean, v_searchfield character varying, v_searchvalue character varying, v_cid character varying DEFAULT ''::character varying, v_fromdate character varying DEFAULT ''::character varying, v_todate character varying DEFAULT ''::character varying, v_reqtype character varying DEFAULT NULL::character varying, v_mode character varying DEFAULT NULL::character varying, v_recordcount integer DEFAULT NULL::integer) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_regno bigint;
  v_sqlquery text;
  v_modestatus varchar(10);
BEGIN
  -- SET option (removed)
  v_sqlquery := '';
  v_modestatus := '0';
  DROP TABLE IF EXISTS tmp_newtemp;
  CREATE TEMP TABLE tmp_newtemp (recorddate timestamp,
loginid varchar(200),
reqTitle varchar(100),
reqType varchar(100),
payMode varchar(100),
currencySymbol varchar(10),
paidamount numeric(19,4),
country varchar(50),
recordid bigint,
checkstatus varchar(20) default(''),
plid bigint default(0),
check_sno varchar(50) default(''),
billid varchar default('')) ON COMMIT DROP;
  v_sqlquery := '';
  IF (v_mode = 'pending') THEN
  v_modestatus := '0';
  END IF;
  IF (v_mode = 'approved') THEN
  v_modestatus := '1';
  END IF;
  IF (v_mode = 'rejected') THEN
  v_modestatus := '2';
  END IF;
  IF (v_reqtype = 'subs' OR v_reqtype = '') THEN
  v_sqlquery := 'insert into #newtemp select tsd.subscriptiondate as subscriptiondate,pl.LoginId,''Subscription'' as reqTitle,''Subscription'' as reqType,
                 tsd.paymode,c.currencycode as currencysymbol,ISNULL(tsd.paidamount,0) as paidamount,
				 (case when C.countryName=''UNITED STATES'' then ''US'' when C.countryName=''UNITED KINGDOM'' then ''UK'' else  C.countryName end  ) as country,
				 tsd.sdid,'''' as checkstatus,0 as plid,'''' as check_sno,'''' as billid
				 from tbl_subscription_details tsd inner join  portal_master pm on  pm.pmid=tsd.pmid 
			     inner join Portal_Login pl on pm.pmid=pl.PMID inner join  COUNTRY c on pm.cid=c.CID inner join city ct on pm.ctid=ct.CTID
			     where isnull(tsd.status,0)=' || v_modestatus || '  and ISNULL(tsd.isdeleted,0)=0 and isnull(tsd.OnlinePayStauts,''confirm'')=''confirm'' ';
  IF (v_cid <> '') THEN
  v_sqlquery := v_sqlquery || ' and convert(varchar(50),C.cid)=' || CAST(v_cid AS VARCHAR(50)) || ' ';
  END IF;
  IF (v_fromdate = '' OR v_todate = '') THEN
  IF (v_fromdate = '' AND v_todate <> '') THEN
  v_sqlquery := v_sqlquery || ' and convert(varchar(50), tsd.subscriptiondate,103)<=convert(varchar(50),''' || v_todate || ''',103) ';
  END IF;
  IF (v_fromdate <> '' AND v_todate = '') THEN
  v_sqlquery := v_sqlquery || ' and convert(varchar(50), tsd.subscriptiondate,103)>=convert(varchar(50),''' || v_fromdate || ''',103) ';
  END IF;
  ELSE
  v_sqlquery := v_sqlquery || ' and convert(varchar(50), tsd.subscriptiondate,103)  between  convert(varchar(50),''' || v_fromdate || ''',103) 
			                       and convert(varchar(50),''' || v_todate || ''',103) ';
  END IF;
  IF (v_searchfield = 'loginid') THEN
  v_sqlquery := v_sqlquery || ' and pl.LoginId like ''%' || v_searchvalue || '%'' ';
  END IF;
  EXECUTE v_sqlquery;
  END IF;
  v_sqlquery := '';
  IF (v_reqtype = 'ppc' OR v_reqtype = '') THEN
  v_sqlquery := ' insert into #newtemp select sf.DepositDate,smd.loginid,''PPC Wallet'' as reqTtitle,''ppc'' as reqType,sf.PaymentType,
	                 (select currencysymbol from tbl_currencymaster where cid=smd.cid) as currencysymbol,sf.DepositAmount  as paidamount,
		 (select case when countryName=''UNITED STATES'' then ''US'' when countryName=''UNITED KINGDOM'' then ''UK'' else  countryName end 
		 from country  where cid=smd.cid) as country,
		 sf.sfdid,(case when sf.checkstatus is null then ' || CAST(0 AS VARCHAR(10)) || ' else sf.checkstatus end)as checkstatus,sf.plid,
		 (case when sf.check_sno is null then ' || CAST(0 AS VARCHAR(10)) || ' else sf.check_sno end)as check_sno,
         (case when sf.Billid is null then ' || CAST(0 AS VARCHAR(10)) || ' else sf.Billid end)as Billid from tbl_sponserfunddetails sf join 
         Portal_Login smd on sf.plid=smd.plid 
		 where isnull(sf.status,0)=' || v_modestatus || ' and isnull(FundType,''ppc'')=''ppc'' and (ISNULL(PaymentType,'''') not in (''manual'',''Coupon'',''ewallet''))  
		 ';
  IF (v_cid <> '') THEN
  v_sqlquery := v_sqlquery || ' and convert(varchar(50),smd.cid)=' || CAST(v_cid AS VARCHAR(50)) || ' ';
  END IF;
  IF (v_fromdate = '' OR v_todate = '') THEN
  IF (v_fromdate = '' AND v_todate <> '') THEN
  v_sqlquery := v_sqlquery || ' and convert(varchar(50), sf.DepositDate,103)<=convert(varchar(50),''' || v_todate || ''',103) ';
  END IF;
  IF (v_fromdate <> '' AND v_todate = '') THEN
  v_sqlquery := v_sqlquery || ' and convert(varchar(50), sf.DepositDate,103)>=convert(varchar(50),''' || v_fromdate || ''',103) ';
  END IF;
  ELSE
  v_sqlquery := v_sqlquery || ' and convert(varchar(50), sf.DepositDate,103)  between  convert(varchar(50),''' || v_fromdate || ''',103) 
			                       and convert(varchar(50),''' || v_todate || ''',103) ';
  END IF;
  IF (v_searchfield = 'loginid') THEN
  v_sqlquery := v_sqlquery || ' and smd.loginid like ''%' || v_searchvalue || '%'' ';
  END IF;
  EXECUTE v_sqlquery;
  END IF;
  IF (v_reqtype = 'subs_wallet' OR v_reqtype = '') THEN
  v_sqlquery := ' insert into #newtemp select sf.DateTime,smd.loginid,''Subs Wallet'' as reqTitle,''subs_wallet'' as reqType,sf.PaymentType,
	                 (select currencysymbol from tbl_currencymaster where cid=smd.cid) as currencysymbol,sf.DepositAmount  as paidamount,
		 (select case when countryName=''UNITED STATES'' then ''US'' when countryName=''UNITED KINGDOM'' then ''UK'' else  countryName end 
		 from country  where cid=smd.cid) as country,
		 sf.sfdid,(case when sf.checkstatus is null then ' || CAST(0 AS VARCHAR(10)) || ' else sf.checkstatus end)as checkstatus,sf.plid,
		 (case when sf.check_sno is null then ' || CAST(0 AS VARCHAR(10)) || ' else sf.check_sno end)as check_sno,
         (case when sf.Billid is null then ' || CAST(0 AS VARCHAR(10)) || ' else sf.Billid end)as Billid from tbl_sponserfunddetails sf join 
         Portal_Login smd on sf.plid=smd.plid 
		 where isnull(sf.status,0)=' || v_modestatus || ' and isnull(FundType,''ppc'')=''subs_wallet'' and (ISNULL(PaymentType,'''') not in (''manual'',''Coupon'',''ewallet''))  
		 ';
  IF (v_cid <> '') THEN
  v_sqlquery := v_sqlquery || ' and convert(varchar(50),smd.cid)=' || CAST(v_cid AS VARCHAR(50)) || ' ';
  END IF;
  IF (v_fromdate = '' OR v_todate = '') THEN
  IF (v_fromdate = '' AND v_todate <> '') THEN
  v_sqlquery := v_sqlquery || ' and convert(varchar(50), sf.DepositDate,103)<=convert(varchar(50),''' || v_todate || ''',103) ';
  END IF;
  IF (v_fromdate <> '' AND v_todate = '') THEN
  v_sqlquery := v_sqlquery || ' and convert(varchar(50), sf.DepositDate,103)>=convert(varchar(50),''' || v_fromdate || ''',103) ';
  END IF;
  ELSE
  v_sqlquery := v_sqlquery || ' and convert(varchar(50), sf.DepositDate,103)  between  convert(varchar(50),''' || v_fromdate || ''',103) 
			                       and convert(varchar(50),''' || v_todate || ''',103) ';
  END IF;
  IF (v_searchfield = 'loginid') THEN
  v_sqlquery := v_sqlquery || ' and smd.loginid like ''%' || v_searchvalue || '%'' ';
  END IF;
  EXECUTE v_sqlquery;
  END IF;
  IF (v_reqtype = 'withdrawal') THEN
  v_sqlquery := ' insert into #newtemp select sf.date,smd.loginid,''withdrawal'' as reqTitle,''withdrawal'' as reqType,sf.paymode,
	                 (select currencysymbol from tbl_currencymaster where cid=smd.cid) as currencysymbol,sf.amount  as paidamount,
		 (select case when countryName=''UNITED STATES'' then ''US'' when countryName=''UNITED KINGDOM'' then ''UK'' else  countryName end 
		 from country  where cid=smd.cid) as country,
		 sf.WHID,'''' as checkstatus,sf.plid,
		'''' as check_sno,
         '''' as Billid from withdrawal_history sf join 
         Portal_Login smd on sf.plid=smd.plid
		 where sf.status=''' || v_mode || ''' and isnull(TranType,''withdrawal'')=''withdrawal''  
		 ';
  IF (v_cid <> '') THEN
  v_sqlquery := v_sqlquery || ' and convert(varchar(50),smd.cid)=' || CAST(v_cid AS VARCHAR(50)) || ' ';
  END IF;
  IF (v_fromdate = '' OR v_todate = '') THEN
  IF (v_fromdate = '' AND v_todate <> '') THEN
  v_sqlquery := v_sqlquery || ' and convert(varchar(50), sf.amount,103)<=convert(varchar(50),''' || v_todate || ''',103) ';
  END IF;
  IF (v_fromdate <> '' AND v_todate = '') THEN
  v_sqlquery := v_sqlquery || ' and convert(varchar(50), sf.amount,103)>=convert(varchar(50),''' || v_fromdate || ''',103) ';
  END IF;
  ELSE
  v_sqlquery := v_sqlquery || ' and convert(varchar(50), sf.amount,103)  between  convert(varchar(50),''' || v_fromdate || ''',103) 
			                       and convert(varchar(50),''' || v_todate || ''',103) ';
  END IF;
  IF (v_searchfield = 'loginid') THEN
  v_sqlquery := v_sqlquery || ' and smd.loginid like ''%' || v_searchvalue || '%'' ';
  END IF;
  EXECUTE v_sqlquery;
  END IF;
  SELECT COUNT(*) INTO v_recordcount FROM tmp_newtemp;
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp ON COMMIT DROP AS SELECT 0 AS rownumber, * FROM tmp_newtemp WHERE recordid = -1;
  IF (v_orderbyfield = 'datedesc') THEN
  INSERT INTO tmp_temp SELECT ROW_NUMBER() OVER (ORDER BY recorddate DESC NULLS LAST), * FROM tmp_newtemp ORDER BY recorddate DESC NULLS LAST;
  END IF;
  IF (v_orderbyfield = 'dateasc') THEN
  INSERT INTO tmp_temp SELECT ROW_NUMBER() OVER (ORDER BY recorddate ASC NULLS FIRST), * FROM tmp_newtemp ORDER BY recorddate ASC NULLS FIRST;
  END IF;
  RETURN QUERY SELECT * FROM tmp_temp WHERE rownumber BETWEEN v_startrowindex AND v_maxrows;
  RETURN QUERY SELECT v_recordcount AS recordcount;
  DROP TABLE IF EXISTS tmp_temp;
  DROP TABLE IF EXISTS tmp_newtemp;
  -- SET option (removed)
END;
$$;


--
-- Name: usp_getinvoice_list(integer, integer, character varying, character varying, character varying, character varying, character varying, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_getinvoice_list(v_startrowindex integer DEFAULT 1, v_maxrows integer DEFAULT 100, v_searchfield character varying DEFAULT ''::character varying, v_searchvalue character varying DEFAULT ''::character varying, v_fromdate character varying DEFAULT ''::character varying, v_todate character varying DEFAULT ''::character varying, v_invoicetype character varying DEFAULT ''::character varying, v_totalcount integer DEFAULT 0) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_minindex INT;
  v_maxindex INT;
  v_query text;
  v_queryresult VARCHAR(500);
BEGIN
  v_queryresult := '';
  v_minindex := (v_startrowindex - 1) * v_maxrows + 1;
  v_maxindex := v_startrowindex * v_maxrows;
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp (ROWNUMBER BIGINT GENERATED BY DEFAULT AS IDENTITY,
INVOICENO VARCHAR(50),
ORDERNO VARCHAR(50),
CREATEDATE timestamp,
DISPATCHEDDATE timestamp,
NOOFITEM INT ,
TOTALAMOUNT numeric(19,4),
STATUS VARCHAR(50)) ON COMMIT DROP;
  v_query := ' INSERT INTO #TEMP SELECT INVNO,ORDERID,CREATE_DATE,ISNULL(DISPATCH_DATE,'' ''),INV_QTY,INV_NETAMT,STATUS
FROM TBL_INVOICE_MASTER WHERE ORDERID=''' || v_invoicetype || '''';
  EXECUTE v_query;
  RETURN QUERY SELECT * FROM tmp_temp WHERE rownumber BETWEEN v_minindex AND v_maxindex;
  SELECT COUNT(rownumber) INTO v_totalcount FROM tmp_temp;
  DROP TABLE IF EXISTS tmp_temp;
  -- SET option (removed)
END;
$$;


