    LANGUAGE plpgsql
    AS $$
DECLARE
  v_query text;
BEGIN
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp (UserName text) ON COMMIT DROP;
  IF EXISTS(SELECT 1 FROM area_master WHERE cid = v_cid AND pincode LIKE '' || v_keyupvalue || '%') THEN
  INSERT INTO tmp_temp SELECT ((am.pincode || ',' || am.areaname || ',' || ct.cityname || ',' || st.statename)) FROM area_master AS am INNER JOIN city AS ct ON am.ctid = ct.ctid INNER JOIN state AS st ON st.sid = ct.sid AND am.pincode LIKE '' || v_keyupvalue || '%' AND am.cid = v_cid ORDER BY am.areaname NULLS FIRST LIMIT 15;
  END IF;
  RETURN QUERY SELECT * FROM tmp_temp;
  DROP TABLE IF EXISTS tmp_temp;
END;
$$;


