--
-- Name: usp_getlogsdatewisevisitors(integer, integer, character varying, character varying, bigint, bigint, bigint, bigint, bigint); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_getlogsdatewisevisitors(v_fromindex integer DEFAULT 1, v_toindex integer DEFAULT 50, v_fromdate character varying DEFAULT ''::character varying, v_todate character varying DEFAULT ''::character varying, v_totalvisit bigint DEFAULT 0, v_totalallvisit bigint DEFAULT 0, v_totalallunique bigint DEFAULT 0, v_totalallpages bigint DEFAULT 0, v_totalallsessioncnt bigint DEFAULT 0) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_count int;
  v_count1 int;
  v_sumsessions bigint;
  v_date varchar(50);
  v_sumpagevisit bigint;
  v_sumuniquevisit bigint;
  v_sumtotalvisitor double precision;
  v_ttlvisitpercent int;
  v_overallvisit double precision;
  v_diffipall int;
  v_diffipbeforetoday int;
  v_allvist int;
  v_allunique int;
  v_allpages int;
  v_allssns int;
  v_total int;
BEGIN
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp ON COMMIT DROP AS SELECT country, state, city, ipaddress, sessioncount, pagecount, CAST(date AS DATE) AS date FROM tbl_visitorhistory WHERE COALESCE(date, '') <> '' AND COALESCE(date, '') = '';
  IF (v_fromdate = '' OR v_todate = '') THEN
  IF (v_fromdate = '' AND v_todate <> '') THEN
  INSERT INTO tmp_temp SELECT country, state, city, ipaddress, sessioncount, pagecount, CAST(date AS DATE) AS date FROM tbl_visitorhistory WHERE (TO_DATE(date, 'DD-MM-YYYY') <= TO_DATE(v_todate, 'DD-MM-YYYY')) AND (COALESCE(date, '') <> '');
  ELSE
  IF (v_fromdate <> '' AND v_todate = '') THEN
  INSERT INTO tmp_temp SELECT country, state, city, ipaddress, sessioncount, pagecount, CAST(date AS DATE) AS date FROM tbl_visitorhistory WHERE (TO_DATE(date, 'DD-MM-YYYY') >= TO_DATE(v_fromdate, 'DD-MM-YYYY')) AND (COALESCE(date, '') <> '');
  ELSE
  INSERT INTO tmp_temp SELECT country, state, city, ipaddress, sessioncount, pagecount, CAST(date AS DATE) AS date FROM tbl_visitorhistory WHERE (COALESCE(date, '') <> '');
  END IF;
  END IF;
  ELSE
  INSERT INTO tmp_temp SELECT country, state, city, ipaddress, sessioncount, pagecount, CAST(date AS DATE) AS date FROM tbl_visitorhistory WHERE (TO_DATE(date, 'DD-MM-YYYY') BETWEEN TO_DATE(v_fromdate, 'DD-MM-YYYY') AND TO_DATE(v_todate, 'DD-MM-YYYY')) AND (COALESCE(date, '') <> '');
  END IF;
  DROP TABLE IF EXISTS tmp_tempdetails;
  CREATE TEMP TABLE tmp_tempdetails (ROWNUMBER Bigint  GENERATED BY DEFAULT AS IDENTITY,
DATE DATE,
TTLVISIT INT DEFAULT(0),
UNQVISIT INT DEFAULT(0),
PAGEVISIT INT DEFAULT(0),
SESSIONSCNT INT DEFAULT(0),
VISITPERCENT double precision DEFAULT(0)) ON COMMIT DROP;
  INSERT INTO tmp_tempdetails (date) SELECT DISTINCT date FROM tmp_temp ORDER BY date DESC NULLS LAST;
  v_count := v_fromindex;
  SELECT v_toindex INTO v_count1;
  SELECT COUNT(1) INTO v_overallvisit FROM tmp_temp;
  WHILE (v_count <= v_count1) LOOP
  IF EXISTS(SELECT 1 FROM tmp_tempdetails WHERE rownumber = v_count) THEN
  SELECT COALESCE(date, '') INTO v_date FROM tmp_tempdetails WHERE rownumber = v_count;
  SELECT COUNT(1) INTO v_sumtotalvisitor FROM tmp_temp WHERE date = v_date;
  SELECT SUM(sessioncount) INTO v_sumsessions FROM tmp_temp WHERE date = v_date;
  SELECT SUM(pagecount) INTO v_sumpagevisit FROM tmp_temp WHERE date = v_date;
  SELECT COUNT(DISTINCT ipaddress) INTO v_diffipall FROM tbl_visitorhistory WHERE CAST(date AS DATE) <= v_date;
  SELECT COUNT(DISTINCT ipaddress) INTO v_diffipbeforetoday FROM tbl_visitorhistory WHERE CAST(date AS DATE) < v_date;
  v_sumuniquevisit := v_diffipall - v_diffipbeforetoday;
  UPDATE tmp_tempdetails SET ttlvisit = v_sumtotalvisitor, unqvisit = v_sumuniquevisit, pagevisit = v_sumpagevisit, sessionscnt = v_sumsessions, visitpercent = ROUND(((v_sumtotalvisitor / v_overallvisit) * 100), 2) WHERE rownumber = v_count;
  END IF;
  v_count := v_count + 1;
  END LOOP;
  RETURN QUERY SELECT *, CAST(TO_CHAR(date, 'DD-MM-YYYY') AS VARCHAR(50)) AS visitedate FROM tmp_tempdetails WHERE rownumber BETWEEN v_fromindex AND v_toindex;
  SELECT COALESCE(COUNT(1), 0) INTO v_total FROM tmp_tempdetails;
  v_totalvisit := v_total;
  SELECT COALESCE(SUM(ttlvisit), 0) INTO v_allvist FROM tmp_tempdetails WHERE rownumber BETWEEN v_fromindex AND v_toindex;
  v_totalallvisit := v_allvist;
  SELECT COALESCE(SUM(unqvisit), 0) INTO v_allunique FROM tmp_tempdetails WHERE rownumber BETWEEN v_fromindex AND v_toindex;
  v_totalallunique := v_allunique;
  SELECT COALESCE(SUM(pagevisit), 0) INTO v_allpages FROM tmp_tempdetails WHERE rownumber BETWEEN v_fromindex AND v_toindex;
  v_totalallpages := v_allpages;
  SELECT COALESCE(SUM(sessionscnt), 0) INTO v_allssns FROM tmp_tempdetails WHERE rownumber BETWEEN v_fromindex AND v_toindex;
  v_totalallsessioncnt := v_allssns;
  DROP TABLE IF EXISTS tmp_tempdetails;
  DROP TABLE IF EXISTS tmp_temp;
END;
$$;


--
-- Name: usp_getmapcategorydata(integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_getmapcategorydata(v_ddid integer DEFAULT 1) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
BEGIN
  -- BEGIN TRAN (removed)
  IF (v_ddid > 0) THEN
  DROP TABLE IF EXISTS tmp_mapeddata;
  CREATE TEMP TABLE tmp_mapeddata (ID INT GENERATED BY DEFAULT AS IDENTITY,MAINCATGORY VARCHAR(500),CATEGORY VARCHAR(500),SUBCATEGORY VARCHAR(500)) ON COMMIT DROP;
  INSERT INTO tmp_mapeddata SELECT tm.maincatname, tc.catname, tsc.subcatname FROM tbl_attributes_with_category AS tawc LEFT JOIN tbl_sub_category AS tsc ON tawc.sub_cat_id = tsc.subcatid LEFT JOIN tbl_category AS tc ON tawc.cat_id = tc.catid LEFT JOIN tbl_main_category AS tm ON tawc.main_cat_id = tm.maincatid WHERE tawc.ddl_id = v_ddid AND is_active = 1 ORDER BY subcatname ASC NULLS FIRST;
  RETURN QUERY SELECT * FROM tmp_mapeddata;
  DROP TABLE IF EXISTS tmp_mapeddata;
  END IF;
  -- COMMIT (removed)
END;
$$;


--
-- Name: usp_getmaster(integer, character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_getmaster(v_id integer DEFAULT 0, v_master character varying DEFAULT ''::character varying) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
BEGIN
  -- SET option (removed)
  IF (v_master = 'state' AND v_id = 0) THEN
  RETURN QUERY SELECT * FROM state WHERE sactive = 1 ORDER BY statename NULLS FIRST;
  END IF;
  IF (v_master = 'role' AND v_id = 0) THEN
  RETURN QUERY SELECT * FROM tblrole WHERE isactive = 1 AND isdeleted = 0 AND associatedtoid = 10101 AND roleid <> 1 ORDER BY associatedtoid DESC NULLS LAST;
  END IF;
  IF (v_master = 'Branchrole' AND v_id = 0) THEN
  RETURN QUERY SELECT * FROM tblrole WHERE isactive = 1 AND isdeleted = 0 AND associatedtoid = 101 ORDER BY rid ASC NULLS FIRST;
  END IF;
  IF (v_master = 'alluserwithRole' AND v_id = 0) THEN
  RETURN QUERY SELECT ROW_NUMBER() OVER (ORDER BY u.createdon DESC NULLS LAST) AS rownumber, COALESCE(c.countryname, '-') AS countryname, u.userid, r.rolename, u.username, (CASE WHEN u.isactive = 1 THEN 'active' WHEN u.isactive = 0 THEN 'Deactive' END) AS status, u.password, r.rolename FROM tbluser AS u LEFT JOIN country AS c ON u.countryid = c.cid INNER JOIN tblrole AS r ON r.roleid = u.roleid AND u.username <> 'admin' AND u.associatedtoid = 10101 ORDER BY u.createdon DESC NULLS LAST;
  END IF;
  -- SET option (removed)
END;
$$;


--
-- Name: usp_getmatrixtable(integer, integer, character varying, boolean, character varying, character varying, character varying, character varying, integer, integer, integer, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_getmatrixtable(v_startrowindex integer, v_maxrows integer, v_orderbyfield character varying, v_asc boolean, v_searchfield character varying, v_searchvalue character varying, v_fromdate character varying DEFAULT NULL::character varying, v_todate character varying DEFAULT NULL::character varying, v_mode integer DEFAULT NULL::integer, v_regno integer DEFAULT NULL::integer, v_level integer DEFAULT NULL::integer, v_distyoe integer DEFAULT NULL::integer) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_recordcount int;
  v_query text;
BEGIN
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp (rownumber int,
kitDesc text,
LoginId text,
name text,
mobile text,
cityName text,
spid int,

spName text,
Regdate text,
level int ,
ctid int,
introRegNo int,
parentRegNo int) ON COMMIT DROP;
  IF (v_mode = 23) THEN
  v_query := 'insert into #temp select ROW_NUMBER() OVER(ORDER BY M1.regno  asc ) as rowNumber,  (k.kitDesc+'' (''+CONVERT(varchar(20),convert(int,K.kitprice))+'')'') as kitDesc,M1.LoginId,(M1.FName+'' ''+M1.lname) as name,M1.mobile,c.cityName,M2.LoginId as
 spid,M2.FName as spName,    
    convert(varchar(50),M1.Regdate,106) as Regdate, L.level,M1.ctid, M1.introRegNo,L.parentRegNo                                                                    
  from Member_Master M1,Member_Master M2,levelEntry L,CITY c,kit_master k where M1.regNo=L.childRegNo and                                                                  
   M1.introRegNo=M2.regNo and  L.parentRegNo=' || CAST(v_regno AS VARCHAR(10)) || ' and m1.ctid=c.CTID and M1.KID=k.kid  ';
  END IF;
  IF (v_searchfield = 'loginid') THEN
  v_query := v_query || ' and M1.LoginId like ''%' || v_searchvalue || '%''';
  END IF;
  IF (v_searchfield = 'name') THEN
  v_query := v_query || ' and (M1.FName+'' ''+isnull(M1.LName,'''')) like ''%' || v_searchvalue || '%''';
  END IF;
  IF (v_searchfield = 'spName') THEN
  v_query := v_query || ' and (M1.FName+'' ''+isnull(M1.LName,''''))  like ''%' || v_searchvalue || '%''';
  END IF;
  IF (v_searchfield = 'mobile') THEN
  v_query := v_query || ' and M1.mobile like ''%' || v_searchvalue || '%''';
  END IF;
  IF (v_fromdate <> '') THEN
  v_query := v_query || ' and convert(date,M1.Regdate,105)>=CONVERT(date, ''' || v_fromdate || ''', 105)';
  END IF;
  IF (v_todate <> '') THEN
  v_query := v_query || ' and convert(date,M1.Regdate,105)<=CONVERT(date, ''' || v_todate || ''', 105)';
  END IF;
  IF (v_level > 0) THEN
  IF (v_distyoe = 0) THEN
  v_query := v_query || ' and L.level=' || CAST(v_level AS VARCHAR(10));
  v_query := v_query || ' and L.parentRegNo=' || CAST(v_regno AS VARCHAR(10));
  ELSE
  IF (v_distyoe = 1) THEN
  v_query := v_query || ' and L.level=' || CAST(v_level AS VARCHAR(10));
  v_query := v_query || ' and  M1.introRegNo=' || CAST(v_regno AS VARCHAR(10));
  ELSE
  v_query := v_query || ' and L.level=' || CAST(v_level AS VARCHAR(10));
  v_query := v_query || ' and  M1.introRegNo!=' || CAST(v_regno AS VARCHAR(10));
  END IF;
  END IF;
  END IF;
  v_query := v_query || '  order bY L.level asc ';
  EXECUTE v_query;
  RETURN QUERY SELECT * FROM tmp_temp WHERE rownumber BETWEEN v_startrowindex AND v_maxrows;
  SELECT COUNT(1) INTO v_recordcount FROM tmp_temp;
  RETURN QUERY SELECT v_recordcount AS recordcount;
  DROP TABLE IF EXISTS tmp_temp;
END;
$$;


--
-- Name: usp_getmember_payout(integer, integer, character varying, integer, character varying, character varying, integer, integer, character varying, character varying, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_getmember_payout(v_startrowindex integer DEFAULT 1, v_maxrows integer DEFAULT 100, v_orderbyfield character varying DEFAULT 0, v_asc integer DEFAULT 0, v_searchfield character varying DEFAULT ''::character varying, v_searchvalue character varying DEFAULT ''::character varying, v_mode integer DEFAULT 0, v_regno integer DEFAULT 0, v_active character varying DEFAULT ''::character varying, v_paydate character varying DEFAULT ''::character varying, v_payid integer DEFAULT 1) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_recordcount int;
  v_query text;
  v_totalpairincome numeric(19,4);
  v_totaldirectincome numeric(19,4);
  v_totallevelincome numeric(19,4);
  v_totalsinglelegstepincome numeric(19,4);
  v_totalsilverclubincome numeric(19,4);
  v_totalrewardincome numeric(19,4);
  v_totaladmincharge numeric(19,4);
  v_totaltdscharge numeric(19,4);
  v_totaltotalincome numeric(19,4);
  v_totalnetpayable numeric(19,4);
BEGIN
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp (rownumber int,
 	 USERNAME varchar(100),
     Name varchar(100),
     BINARYINCOME numeric(19,4),
     PAYBLEAMOUNT numeric(19,4),
     TDS numeric(19,4)) ON COMMIT DROP;
  v_query := '';
  v_query := 'insert into #temp select ROW_NUMBER() over(order by mp.PAYID asc) as rownumber,USERNAME,(isnull(FNAME,'''')+''''+isnull(LNAME,'''')) as Name,
	 isnull(mp.BINARYINCOME,0) as BINARYINCOME,isnull(mp.PAYBLEAMOUNT,0) as PAYBLEAMOUNT,isnull(mp.TDS,0) as TDS
	 from PORTAL_LOGIN pl left join MEMBER_PAYOUT mp on mp.REGNO=pl.RegNo left join PAYOUT p on p.PAYID=mp.PAYID where mp.PAYID >0  ';
  IF (v_searchfield = 'name') THEN
  v_query := v_query || ' and pl.FName like ''%' || v_searchvalue || '%''';
  ELSE
  IF (v_searchfield = 'USERNAME') THEN
  v_query := v_query || ' and pl.USERNAME like ''%' || v_searchvalue || '%''';
  END IF;
  END IF;
  IF (v_active = '0') THEN
  v_query := v_query || ' and mp.active=0';
  END IF;
  IF (v_active = '1') THEN
  v_query := v_query || ' and mp.active=1';
  END IF;
  IF (v_payid > 0) THEN
  v_query := v_query || ' and mp.payid  = ' || CAST(v_payid AS VARCHAR(20));
  END IF;
  IF (v_paydate <> '') THEN
  v_query := v_query || ' and convert(date,p.payto,105)=CONVERT(date, ''' || v_paydate || ''', 105)';
  END IF;
  IF (v_regno > 0) THEN
  v_query := v_query || ' and pl.regno=' || CAST(v_regno AS VARCHAR(20));
  END IF;
  EXECUTE v_query;
  SELECT COUNT(rownumber) INTO v_recordcount FROM tmp_temp;
  RETURN QUERY SELECT (v_recordcount) AS recordcount, * FROM tmp_temp WHERE rownumber BETWEEN v_startrowindex AND v_maxrows;
END;
$$;


--
-- Name: usp_getmemberprofilesponsor(text); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_getmemberprofilesponsor(v_loginid text) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_sponserid text;
  v_sponsername text;
BEGIN
  v_sponserid := '';
  v_sponsername := '';
  v_sponserid := (SELECT sponserid FROM member_master WHERE loginid = v_loginid);
  SELECT username INTO v_sponserid FROM member_master WHERE loginid = v_sponserid;
  v_sponsername := (SELECT fname || ' ' || lname FROM member_master WHERE member_master.loginid = v_sponserid);
  RETURN QUERY SELECT mm.regno, mm.loginid, mm.username, (CASE WHEN v_sponserid = '' THEN 'N/A' WHEN COALESCE(v_sponserid, '') = '' THEN 'N/A' ELSE v_sponserid END) AS sponserid, (CASE WHEN v_sponsername = '' THEN 'N/A' WHEN COALESCE(v_sponsername, '') = '' THEN 'N/A' ELSE v_sponsername END) AS sponsername, mm.fname, COALESCE(mm.lname, '') AS lname, ('+ ' || c.isdcode || ' - ' || mm.mobile) AS mobilefull, mm.mobile, mm.emailid, mm.dob, mm.gender, mm.pincode, mm.address, mm.ctid, mm.cityname, mm.bankname, mm.ifsccode, mm.accountno, mm.branchname, mm.imagename, CAST(TO_CHAR(mm.regdate, 'DD-MM-YYYY') AS VARCHAR(30)) AS regdate, COALESCE(nomname, '') AS name, mm.ifsccode AS ifsccode, mm.panno AS panno, mm.sid, mm.statename, mm.cid, c.countryname, (CASE WHEN mm.active = 1 THEN 'Paid' ELSE 'Free' END) AS status, (CASE WHEN COALESCE(mm.side, '') = '' THEN 'N/A' WHEN mm.side = 1 THEN 'Left' ELSE 'Right' END) AS side, mm.nomrel AS relation, COALESCE(mm.panno, '') AS panno, COALESCE(mm.ispanverified, 0) AS ispanverified, mm.challanimage FROM member_master AS mm INNER JOIN country AS c ON mm.cid = c.cid WHERE loginid = v_loginid;
END;
$$;


--
-- Name: usp_getmerchantexcel(integer, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_getmerchantexcel(v_mode integer DEFAULT 1, v_status integer DEFAULT 3) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_count INT;
  v_totalcount INT;
  v_invoiceno varchar(100);
  v_productname text;
  v_invoicevalue Decimal(18,3);
  v_totalitem int;
BEGIN
  -- SET option (removed)
  IF (v_mode = 1) THEN
  v_count := 1;
  v_totalcount := 0;
  v_totalitem := 0;
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp (ROWNUMBER INT GENERATED BY DEFAULT AS IDENTITY,
ITEM_NAME text,
NO_OF_PIECE INT,
PERSON_NAME VARCHAR(100),
MOBILENO VARCHAR(500),
EMAIL VARCHAR(100),
INVOICE_VALUE DECIMAL(18,2),
COLLECTABLE_AMOUNT DECIMAL(18,2),
DOCKETNO VARCHAR(100),
INVOICENO VARCHAR(100),
State varchar(300),
City varchar(300),
Area varchar(500),
Pincode varchar(100),
Address varchar(1000),
Orderdate varchar(100),
ORDERID varchar(100)) ON COMMIT DROP;
  INSERT INTO tmp_temp SELECT DISTINCT '', 0, pm.companyname, pm.mobileno, pl.emailid, 0, 0, pom.docketno, pom.invoiceno, pm.pick_state, pm.pick_city, pm.pick_area, pm.pick_pincode, pm.pick_address, CAST(TO_CHAR(om.orderdate, 'DD TMMon YYYY') AS VARCHAR(50)), pom.orderid FROM tbl_product_order_master AS pom LEFT JOIN tbl_order_master AS om ON pom.orderid = om.orderid LEFT JOIN portal_master AS pm ON pm.plid = pom.plid LEFT JOIN portal_login AS pl ON pl.plid = pm.plid WHERE pom.intstatus = v_status;
  SELECT COUNT(*) INTO v_totalcount FROM tmp_temp;
  WHILE (v_totalcount >= v_count) LOOP
  v_invoiceno := '';
  v_productname := '';
  SELECT invoiceno INTO v_invoiceno FROM tmp_temp WHERE rownumber = v_count;
  SELECT COALESCE(v_productname || ',', '') || CAST(product_name AS VARCHAR(1000)) INTO v_productname FROM tbl_product_order_master WHERE invoiceno = v_invoiceno;
  v_productname := SUBSTRING(v_productname FROM 2 FOR LENGTH(CAST(v_productname AS TEXT)));
  SELECT SUM(total_purchase_cost), SUM(CAST(product_qty AS INT)) INTO v_invoicevalue, v_totalitem FROM tbl_product_order_master WHERE invoiceno = v_invoiceno;
  UPDATE tmp_temp SET item_name = v_productname, invoice_value = ROUND(v_invoicevalue, 0), collectable_amount = ROUND(v_invoicevalue, 0), no_of_piece = v_totalitem WHERE rownumber = v_count;
  v_count := v_count + 1;
  END LOOP;
  RETURN QUERY SELECT * FROM tmp_temp;
  DROP TABLE IF EXISTS tmp_temp;
  END IF;
  -- SET option (removed)
END;
$$;


--
-- Name: usp_getmerchantwallet(integer, character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_getmerchantwallet(v_plid integer DEFAULT 1, v_stroutput character varying DEFAULT ''::character varying) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF (v_plid > 0) THEN
  IF EXISTS(SELECT COUNT(1) FROM portal_login WHERE plid = v_plid) THEN
  IF ((SELECT COUNT(1) FROM merchant_payout WHERE plid = v_plid) > 0) THEN
  RETURN QUERY SELECT COALESCE(completeorderamount, 0.00) - COALESCE(admincharge, 0.00) AS availablebalance FROM merchant_payout WHERE plid = v_plid;
  v_stroutput := 'SUCCESS';
  ELSE
  RETURN QUERY SELECT 0.00 AS availablebalance;
  v_stroutput := 'SUCCESS';
  END IF;
  ELSE
  v_stroutput := 'Invalid customer';
  RETURN;
  END IF;
  END IF;
END;
$$;


