--
-- Name: usp_getnotifications(bigint, character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_getnotifications(v_clid bigint DEFAULT 1, v_message character varying DEFAULT 'NO REVIEWS'::character varying) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
BEGIN
  BEGIN
  RETURN QUERY SELECT tcnid, tcntid, clid, notificationdescription, REPLACE(CAST(TO_CHAR(notificationdate, 'DD TMMon YYYY') AS VARCHAR(11)), ' ', '-') || ' ' || STUFF(RIGHT(CAST(CAST(TO_CHAR(notificationdate, 'TMMon DD YYYY FMHH12:MI%p') AS VARCHAR(30)) AS TEXT), 7), 6, 0, ' ') AS notificationdate, referenceid, isread, tcn.active, COALESCE(prod_images, '') AS prod_images, CAST(TO_CHAR(createdate + 7, 'TMMon DD, YYYY') AS VARCHAR(50)) AS expecteddelivery, COALESCE(pom.orderid, '') AS orderid, COALESCE(pom.status, '') AS status, COALESCE(pom.intstatus, 0) AS intstatus, COALESCE(product_name, '') AS product_name, COALESCE(pom.poid, 0) AS poid, COALESCE(tm.tmid, 0) AS tmid FROM dbo.tbl_customer_notifications AS tcn LEFT JOIN tbl_product_order_master AS pom ON pom.orderno = tcn.referenceid LEFT JOIN tbl_ticketmaster AS tm ON tcn.referenceid = tm.ticketno WHERE clid = v_clid AND tcn.active = 1 ORDER BY TO_DATE(notificationdate, 'DD TMMon YYYY') DESC NULLS LAST;
  EXCEPTION WHEN OTHERS THEN
  v_message := 'NO REVIEWS';
  END;
END;
$$;


--
-- Name: usp_getorder_list_mobile(integer, character varying, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_getorder_list_mobile(v_clid integer DEFAULT 2250, v_mode character varying DEFAULT 'all'::character varying, v_status integer DEFAULT 0) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_loginid varchar(100);
BEGIN
  v_loginid := '';
  SELECT loginid INTO v_loginid FROM tbl_customerlogin WHERE clid = v_clid;
  IF (v_mode = 'all') THEN
  RETURN QUERY SELECT orderid, ordertype, CAST(TO_CHAR(orderdate, 'DD TMMon YYYY') AS VARCHAR(50)) AS orderdate, order_qty, order_dap, total_ship_ch, order_netamt, total_vat, order_pv, order_bv, paymode, fname, mobileno, emailid, address, pincode, sh_city, status, intstatus FROM tbl_order_master WHERE loginid = v_loginid AND NOT intstatus IN (-1) ORDER BY orid DESC NULLS LAST;
  ELSE
  IF (v_mode = 'open') THEN
  RETURN QUERY SELECT orderid, ordertype, CAST(TO_CHAR(orderdate, 'DD TMMon YYYY') AS VARCHAR(50)) AS orderdate, order_qty, order_dap, total_ship_ch, order_netamt, total_vat, order_pv, order_bv, paymode, fname, mobileno, emailid, address, pincode, sh_city, status, intstatus FROM tbl_order_master WHERE loginid = v_loginid AND intstatus IN (0, 1, 2, 3, 4, 5) ORDER BY orid DESC NULLS LAST;
  ELSE
  RETURN QUERY SELECT orderid, ordertype, CAST(TO_CHAR(orderdate, 'DD TMMon YYYY') AS VARCHAR(50)) AS orderdate, order_qty, order_dap, total_ship_ch, order_netamt, total_vat, order_pv, order_bv, paymode, fname, mobileno, emailid, address, pincode, sh_city, status, intstatus FROM tbl_order_master WHERE loginid = v_loginid AND intstatus = v_status ORDER BY orid DESC NULLS LAST;
  END IF;
  END IF;
END;
$$;


