END;
$$;


--
-- Name: usp_getorderinvoice(text, character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_getorderinvoice(v_orderno text DEFAULT '984686,837276,'::text, INOUT v_strresult character varying DEFAULT ''::character varying) RETURNS character varying
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_invoice VARCHAR(100);
  v_orderid VARCHAR(100);
  v_morderid VARCHAR(500);
  v_loginid VARCHAR(100);
  v_invoicecode VARCHAR(10);
  v_currentyear VARCHAR(100);
  v_nextyear VARCHAR(100);
  v_countno VARCHAR(100);
  v_paymode VARCHAR(200);
  v_plid INT;
  v_index INT;
  v_ordernumber VARCHAR(50);
  v_orid INT;
  v_poid INT;
  v_orderdate timestamp;
  v_sprid INT;
  v_quantity INT;
  v_customername VARCHAR(100);
  v_emailid VARCHAR(100);
  v_mobile VARCHAR(100);
  v_address VARCHAR(1000);
  v_country VARCHAR(100);
  v_state VARCHAR(500);
  v_city VARCHAR(100);
  v_pincode VARCHAR(25);
  v_allorderno text;
  v_product_name text;
  v_lastchallanno VARCHAR(50);
  v_fixedexp VARCHAR(100);
  v_docketno VARCHAR(50);
BEGIN
  -- BEGIN TRAN (removed)
  -- SET option (removed)
  v_paymode := '';
  v_plid := 0;
  v_index := 1;
  v_allorderno := '';
  v_product_name := '';
  v_allorderno := v_orderno;
  SELECT COALESCE(symbol, ''), startyear, endyear, lastdigit INTO v_invoicecode, v_currentyear, v_nextyear, v_countno FROM tbl_invoice_details_master WHERE status = 1;
  v_countno := v_countno || 1;
  v_currentyear := RIGHT(CAST(v_currentyear AS TEXT), 2);
  v_nextyear := RIGHT(CAST(v_nextyear AS TEXT), 2);
  SELECT RIGHT(CAST('000000' || CAST(v_countno AS VARCHAR(6)) AS TEXT), 6) INTO v_countno;
  v_invoice := v_invoicecode || '/' || v_currentyear || '-' || v_nextyear || '/' || v_countno;
  WHILE (v_index <> 0) LOOP
  SELECT POSITION(',' IN v_orderno) INTO v_index;
  IF (v_index <> '') THEN
  SELECT LEFT(CAST(v_orderno AS TEXT), v_index - 1) INTO v_ordernumber;
  ELSE
  SELECT v_orderno INTO v_ordernumber;
  END IF;
  SELECT product_name INTO v_product_name FROM tbl_product_order_master WHERE orderno = v_ordernumber;
  UPDATE tbl_customer_notifications SET isread = 0, active = 1, isreaddate = NULL, notificationdescription = 'Your Order containing ' || v_product_name || ' that you ordered  is packed by the merchant and is ready for the shipment.', notificationdate = dbo.FUN_GETCURRENTDATE() WHERE referenceid = v_ordernumber;
  IF EXISTS(SELECT 1 FROM tbl_product_order_master WHERE orderno = v_ordernumber) THEN
  IF (v_ordernumber <> '') THEN
  SELECT poid, COALESCE(orderid, ''), COALESCE(morderid, ''), loginid, subprcode, plid, product_qty INTO v_poid, v_orderid, v_morderid, v_loginid, v_sprid, v_plid, v_quantity FROM tbl_product_order_master WHERE orderno = v_ordernumber;
  SELECT paymode, orid, orderdate, (fname || ' ' || lname), emailid, mobileno, address, 'INDIA', '', sh_city, pincode INTO v_paymode, v_orid, v_orderdate, v_customername, v_emailid, v_mobile, v_address, v_country, v_state, v_city, v_pincode FROM tbl_order_master WHERE orderid = v_orderid;
  UPDATE tbl_product_order_master SET intstatus = 2, status = 'PACKED', invoiceno = v_invoice WHERE orderno = v_ordernumber;
  UPDATE tbl_order_confirmedstaus SET packed = dbo.FUN_GETCURRENTDATE() WHERE orderno = v_ordernumber;
  INSERT INTO tbl_invoicedetailsmaster (orid, poid, plid, invoiceno, orderid, orderno, morderid, customername, emailid, mobile, invoicename, order_date, address, country, state, city, pincode, intstatus, invoice_date, product_code, quantity, paymode) VALUES (v_orid, v_poid, v_plid, v_invoice, v_orderid, v_ordernumber, v_morderid, v_customername, v_emailid, v_mobile, (v_orderid || '.PDF'), v_orderdate, v_address, v_country, v_state, v_city, v_pincode, 2, dbo.FUN_GETCURRENTDATE(), v_sprid, v_quantity, v_paymode);
  END IF;
  END IF;
  SELECT RIGHT(CAST(v_orderno AS TEXT), LENGTH(CAST(v_orderno AS TEXT)) - v_index) INTO v_orderno;
  IF LENGTH(CAST(v_orderno AS TEXT)) = 0 THEN
  EXIT;
  END IF;
  END LOOP;
  v_fixedexp := 'DC';
  SELECT COALESCE(MAX(challanno), 0) INTO v_lastchallanno FROM tbl_deliverychallan;
  v_lastchallanno := SUBSTRING(v_lastchallanno FROM 3 FOR LENGTH(CAST(v_lastchallanno AS TEXT)));
  v_lastchallanno := v_lastchallanno || 1;
  SELECT RIGHT(CAST('000000' || CAST(v_lastchallanno AS VARCHAR(6)) AS TEXT), 6) INTO v_lastchallanno;
  SELECT (v_fixedexp || v_lastchallanno) INTO v_lastchallanno;
  IF NOT EXISTS(SELECT 1 FROM tbl_deliverychallan WHERE invoiceno = v_invoice) THEN
  IF NOT EXISTS(SELECT 1 FROM tbl_deliverychallan WHERE challanno = v_lastchallanno) THEN
  INSERT INTO tbl_deliverychallan (tlpid, invoiceno, orderid, challanno, challandate, docketno, createddate, active) VALUES (1, v_invoice, v_orderid, v_lastchallanno, dbo.FUN_GETCURRENTDATE(), '', dbo.FUN_GETCURRENTDATE(), 1);
  ELSE
  -- ROLLBACK (removed)
  v_strresult := 'CHALLAN NO ALREADY EXISTS';
  RETURN;
  END IF;
  ELSE
  -- ROLLBACK (removed)
  v_strresult := 'INVOICE NO ALREADY EXISTS';
  RETURN;
  END IF;
  UPDATE tbl_invoice_details_master SET lastdigit = lastdigit + 1 WHERE status = 1;
  UPDATE tbl_docketno SET isused = 1, challanno = v_lastchallanno, orderno = v_allorderno WHERE docketno = v_docketno;
  UPDATE tbl_invoicedetailsmaster SET tracking_no = v_docketno WHERE invoiceno = v_invoice;
  UPDATE tbl_product_order_master SET docketno = v_docketno WHERE invoiceno = v_invoice;
  -- SET option (removed)
  IF (0 <> 0) THEN
  -- ROLLBACK (removed)
  v_strresult := 'SOME ERROR OCCURED';
  RETURN;
  END IF;
  -- COMMIT (removed)
END;
$$;


--
-- Name: usp_getorderscount(bigint, integer, integer, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_getorderscount(v_plid bigint DEFAULT 2, v_intstatus integer DEFAULT 4, v_categoryrelatedto integer DEFAULT 1, v_did integer DEFAULT 0) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF (v_did = 0) THEN
  IF (v_intstatus = 4) THEN
  v_categoryrelatedto := 2;
  END IF;
  RETURN QUERY SELECT COUNT(DISTINCT orderid) FROM tbl_product_order_master AS pom INNER JOIN ims_subproduct AS imsp ON imsp.sprid = pom.subprcode INNER JOIN ims_masterproduct AS pm ON imsp.mprid = pm.mprid INNER JOIN tbl_main_category AS mc ON mc.maincatid = pm.maincategoryid INNER JOIN portal_login AS pl ON pl.plid = pom.plid WHERE pom.plid = v_plid AND intstatus = v_intstatus AND mc.categoryrelatedto = v_categoryrelatedto;
  ELSE
  IF (v_did <> 0) THEN
  RETURN QUERY SELECT COUNT(DISTINCT orderid) FROM tbl_product_order_master AS pom INNER JOIN ims_subproduct AS imsp ON imsp.sprid = pom.subprcode INNER JOIN ims_masterproduct AS pm ON imsp.mprid = pm.mprid INNER JOIN tbl_main_category AS mc ON mc.maincatid = pm.maincategoryid INNER JOIN portal_login AS pl ON pl.plid = pom.plid WHERE pom.plid = v_plid AND intstatus = v_intstatus AND mc.categoryrelatedto = v_categoryrelatedto AND pl.plid IN (SELECT plid FROM portal_master WHERE cid IN (SELECT cid FROM distributor_master WHERE plid = v_did));
  END IF;
  END IF;
END;
$$;


--
-- Name: usp_getpacksrecordforcitycategoryforfeaturedad(integer, integer, numeric); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_getpacksrecordforcitycategoryforfeaturedad(v_ctid integer, v_catid integer, v_packageprice numeric DEFAULT 0) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_cid int;
  v_basicprice numeric(19,4);
  v_silverprice numeric(19,4);
  v_currencysymbol varchar(20);
BEGIN
  IF NOT EXISTS(SELECT 1 FROM product_category WHERE catid = v_catid) THEN
  SELECT catid INTO v_catid FROM product_subcategory WHERE scatid = v_catid;
  END IF;
  SELECT cid INTO v_cid FROM city WHERE ctid = v_ctid;
  SELECT currencysymbol INTO v_currencysymbol FROM country WHERE cid = v_cid;
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp ON COMMIT DROP AS SELECT packageprice FROM tbl_package_master WHERE cid = v_cid AND packid = 1;
  IF EXISTS(SELECT 1 FROM tbl_packs_updated_prices WHERE ctid = v_ctid AND catid = v_catid AND status = 1) THEN
  SELECT basicpackprice INTO v_basicprice FROM tbl_packs_updated_prices WHERE ctid = v_ctid AND catid = v_catid AND status = 1;
  UPDATE tmp_temp SET packageprice = v_basicprice;
  END IF;
  SELECT packageprice INTO v_packageprice FROM tmp_temp;
  RETURN QUERY SELECT packageprice, v_currencysymbol AS currencysymbol FROM tmp_temp;
  DROP TABLE IF EXISTS tmp_temp;
END;
$$;


--
-- Name: usp_getpaymentdetail(integer, integer, integer, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_getpaymentdetail(v_slid integer DEFAULT 0, v_checkstatus integer DEFAULT 0, v_sfdid integer DEFAULT 0, v_chksno integer DEFAULT 0) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_currency varchar(30);
BEGIN
  v_currency := '';
  SELECT currencysymbol INTO v_currency FROM tbl_currencymaster WHERE cid = (SELECT cid FROM sponsor_master_detail WHERE plid = v_slid);
  IF (v_checkstatus = 0) THEN
  RETURN QUERY SELECT (v_currency) AS currencysymbol, depositamount, (CASE WHEN NOT fundapprovedate IS NULL THEN CAST(TO_CHAR(fundapprovedate, 'MM/DD/YYYY') AS VARCHAR(10)) ELSE '-' END) AS fundapprovedate, paymenttype, (CASE WHEN status = 0 THEN 'Pending' WHEN status = 1 THEN 'Approved' WHEN status = 2 THEN 'Rejected' END) AS status, depositdate, (CASE WHEN rejectreview IS NULL THEN 'No reason mentioned' WHEN rejectreview = '' THEN 'No reason mentioned' ELSE rejectreview END) AS rejectreview, (CASE WHEN NOT datetime IS NULL THEN CAST(TO_CHAR(datetime, 'MM/DD/YYYY') AS VARCHAR(10)) ELSE '-' END) AS requesteddate FROM tbl_sponserfunddetails WHERE plid = v_slid AND sfdid = v_sfdid;
  END IF;
  IF (v_checkstatus = 1) THEN
  RETURN QUERY SELECT (v_currency) AS currencysymbol, checknumber, checkdate, bankname, branchname, accountno, checkamount, (CASE WHEN COALESCE(sfd.status, 0) = 0 THEN 'Pending' WHEN COALESCE(sfd.status, 0) = 1 THEN 'Approved' WHEN COALESCE(sfd.status, 0) = 2 THEN 'Rejected' END) AS status, (CASE WHEN sfd.rejectreview IS NULL THEN 'No Reason' WHEN sfd.rejectreview = '' THEN 'No Reason' ELSE sfd.rejectreview END) AS rejectreason, (CASE WHEN NOT sfd.fundapprovedate IS NULL THEN CAST(TO_CHAR(sfd.fundapprovedate, 'MM/DD/YYYY') AS VARCHAR(10)) ELSE '-' END) AS fundapprovedate FROM tbl_sponsercheckdetails JOIN tbl_sponserfunddetails AS sfd ON sfd.check_sno = tbl_sponsercheckdetails.chk_sno WHERE chk_sno = v_chksno AND sfd.plid = v_slid;
  END IF;
  IF (0 > 0) THEN
  RETURN;
  END IF;
END;
$$;


--
-- Name: usp_getpayoutstatementonpayid(character varying, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_getpayoutstatementonpayid(v_loginid character varying DEFAULT ''::character varying, v_payid integer DEFAULT 0) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF (v_loginid <> '') THEN
  IF (v_payid > 0) THEN
  RETURN QUERY SELECT ROW_NUMBER() OVER (ORDER BY mp.loginid NULLS FIRST) AS rownumber, mp.mpid, mp.loginid, mm.fname || ' ' || COALESCE(mm.lname, '') AS fname, COALESCE(mm.fath_hus_name, '') AS fath_hus_name, mm.address, mm.statename, mm.cityname, mm.mobile, CAST(TO_CHAR(mm.regdate, 'DD-MM-YYYY') AS VARCHAR(50)) AS regdate, mm.panno, CASE mm.ispanverified WHEN 0 THEN 'UnVerified' WHEN 1 THEN 'Verified' END AS ispanverified, mp.olbv, mp.orbv, mp.crbv, mp.clbv, mp.tlbv, mp.trbv, mp.matchbv, mp.paidbv, mp.flushbv, mp.cflbv, mp.cfrbv, CAST(TO_CHAR(p.payfrom, 'DD-MM-YYYY') AS VARCHAR(30)) AS payfrom, CAST(TO_CHAR(p.payto, 'DD-MM-YYYY') AS VARCHAR(30)) AS payto, mp.binaryincome, COALESCE(mp.directincome, 0) AS directincome, COALESCE(mp.levelincome, 0) AS levelincome, mp.totalincome, COALESCE(mp.oldincome, 0) AS oldincome, mp.paybleamount, mp.payid, COALESCE(bk.accountholdername, '') AS accountholdername, COALESCE(bk.accountno, '') AS accountno, COALESCE(bk.bankname, '') AS bankname, COALESCE(bk.ifsccode, '') AS ifsccode, COALESCE(mp.tds, 0) AS tds, COALESCE(mp.admincharge, 0) AS admincharge, COALESCE(mp.repurchase, 0) AS repurchase FROM member_payout AS mp INNER JOIN payout AS p ON p.payid = mp.payid INNER JOIN member_master AS mm ON mm.loginid = mp.loginid LEFT JOIN bank_accounts AS bk ON mp.regno = bk.regno WHERE mp.loginid = v_loginid AND mp.payid = v_payid;
  ELSE
  RETURN QUERY SELECT ROW_NUMBER() OVER (ORDER BY mp.loginid NULLS FIRST) AS rownumber, mp.mpid, mp.loginid, mm.fname || ' ' || COALESCE(mm.lname, '') AS fname, mm.lname, COALESCE(mm.fath_hus_name, '') AS fath_hus_name, mm.address, mm.statename, mm.cityname, mm.mobile, CAST(TO_CHAR(mm.regdate, 'DD-MM-YYYY') AS VARCHAR(50)) AS regdate, mm.panno, CASE mm.ispanverified WHEN 0 THEN 'UnVerified' WHEN 1 THEN 'Verified' END AS ispanverified, mp.olbv, mp.orbv, mp.crbv, mp.clbv, mp.tlbv, mp.trbv, mp.matchbv, mp.paidbv, mp.flushbv, mp.cflbv, mp.cfrbv, CAST(TO_CHAR(p.payfrom, 'DD-MM-YYYY') AS VARCHAR(30)) AS payfrom, CAST(TO_CHAR(p.payto, 'DD-MM-YYYY') AS VARCHAR(30)) AS payto, mp.binaryincome, COALESCE(mp.directincome, 0) AS directincome, COALESCE(mp.levelincome, 0) AS levelincome, mp.totalincome, COALESCE(mp.oldincome, 0) AS oldincome, mp.paybleamount, mp.payid, COALESCE(bk.accountholdername, '') AS accountholdername, COALESCE(bk.accountno, '') AS accountno, COALESCE(bk.bankname, '') AS bankname, COALESCE(bk.ifsccode, '') AS ifsccode, COALESCE(mp.tds, 0) AS tds, COALESCE(mp.admincharge, 0) AS admincharge, COALESCE(mp.repurchase, 0) AS repurchase FROM member_payout AS mp INNER JOIN payout AS p ON p.payid = mp.payid INNER JOIN member_master AS mm ON mm.loginid = mp.loginid LEFT JOIN bank_accounts AS bk ON mp.regno = bk.regno WHERE mp.loginid = v_loginid;
  END IF;
  ELSE
  IF (v_payid > 0) THEN
  RETURN QUERY SELECT ROW_NUMBER() OVER (ORDER BY mp.loginid NULLS FIRST) AS rownumber, mp.mpid, mp.loginid, mm.fname, COALESCE(mm.fath_hus_name, '') AS fath_hus_name, mm.address, mm.statename, mm.cityname, mm.mobile, CAST(TO_CHAR(mm.regdate, 'DD-MM-YYYY') AS VARCHAR(50)) AS regdate, mm.panno, CASE mm.ispanverified WHEN 0 THEN 'UnVerified' WHEN 1 THEN 'Verified' END AS ispanverified, mp.olbv, mp.orbv, mp.crbv, mp.clbv, mp.tlbv, mp.trbv, mp.matchbv, mp.paidbv, mp.flushbv, mp.cflbv, mp.cfrbv, CAST(TO_CHAR(p.payfrom, 'DD-MM-YYYY') AS VARCHAR(30)) AS payfrom, CAST(TO_CHAR(p.payto, 'DD-MM-YYYY') AS VARCHAR(30)) AS payto, mp.binaryincome, COALESCE(mp.directincome, 0) AS directincome, COALESCE(mp.levelincome, 0) AS levelincome, mp.totalincome, COALESCE(mp.oldincome, 0) AS oldincome, mp.paybleamount, mp.payid, COALESCE(bk.accountholdername, '') AS accountholdername, COALESCE(bk.accountno, '') AS accountno, COALESCE(bk.bankname, '') AS bankname, COALESCE(bk.ifsccode, '') AS ifsccode FROM member_payout AS mp INNER JOIN payout AS p ON p.payid = mp.payid INNER JOIN member_master AS mm ON mm.loginid = mp.loginid LEFT JOIN bank_accounts AS bk ON mp.regno = bk.regno WHERE mp.payid = v_payid;
  ELSE
  RETURN QUERY SELECT ROW_NUMBER() OVER (ORDER BY mp.loginid NULLS FIRST) AS rownumber, mp.mpid, mp.loginid, mm.fname, COALESCE(mm.fath_hus_name, '') AS fath_hus_name, mm.address, mm.statename, mm.cityname, mm.mobile, CAST(TO_CHAR(mm.regdate, 'DD-MM-YYYY') AS VARCHAR(50)) AS regdate, mm.panno, CASE mm.ispanverified WHEN 0 THEN 'UnVerified' WHEN 1 THEN 'Verified' END AS ispanverified, mp.olbv, mp.orbv, mp.crbv, mp.clbv, mp.tlbv, mp.trbv, mp.matchbv, mp.paidbv, mp.flushbv, mp.cflbv, mp.cfrbv, CAST(TO_CHAR(p.payfrom, 'DD-MM-YYYY') AS VARCHAR(30)) AS payfrom, CAST(TO_CHAR(p.payto, 'DD-MM-YYYY') AS VARCHAR(30)) AS payto, mp.binaryincome, COALESCE(mp.directincome, 0) AS directincome, COALESCE(mp.levelincome, 0) AS levelincome, mp.totalincome, COALESCE(mp.oldincome, 0) AS oldincome, mp.paybleamount, mp.payid, COALESCE(bk.accountholdername, '') AS accountholdername, COALESCE(bk.accountno, '') AS accountno, COALESCE(bk.bankname, '') AS bankname, COALESCE(bk.ifsccode, '') AS ifsccode FROM member_payout AS mp INNER JOIN payout AS p ON p.payid = mp.payid INNER JOIN member_master AS mm ON mm.loginid = mp.loginid LEFT JOIN bank_accounts AS bk ON mp.regno = bk.regno;
  END IF;
  END IF;
END;
$$;


