--
-- Name: usp_getproductdatasearch(character varying, bigint); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_getproductdatasearch(v_serchitem character varying, v_branchid bigint DEFAULT 1) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_count int;
BEGIN
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp (fomatedResult text,
searchResult text,
forurl text,
searchtype varchar(200),
MPRID bigint,
SPRID bigint) ON COMMIT DROP;
  INSERT INTO tmp_temp SELECT CASE WHEN pms.qty <> 0 THEN pmm.producttitle || ' (' || CAST(pms.qty AS VARCHAR(100)) || ' ' || pms.unit || ' )' WHEN pms.color <> '' THEN pmm.producttitle || ' (' || CAST(pms.color AS VARCHAR(100)) || ' )' WHEN pms.size <> '' THEN pmm.producttitle || ' (' || CAST(pms.size AS VARCHAR(100)) || ' )' ELSE pmm.producttitle END, pmm.producttitle, CAST(pms.sprid AS VARCHAR(100)), 'Product', pmm.mprid, pms.sprid FROM ims_masterproduct AS pmm INNER JOIN ims_subproduct AS pms ON pmm.mprid = pms.mprid WHERE pms.isactive = 1 AND (v_branchid = 1 OR pmm.branchid = v_branchid) AND ' ' || pmm.producttitle LIKE '%' || v_serchitem || '%';
  RETURN QUERY SELECT DISTINCT searchresult, fomatedresult, forurl, searchtype AS serachtext, mprid, sprid, dbo.fun_findcount(searchresult) AS cnt FROM tmp_temp ORDER BY cnt ASC NULLS FIRST LIMIT 20;
  DROP TABLE IF EXISTS tmp_temp;
END;
$$;


