  RETURN QUERY SELECT DISTINCT searchresult, fomatedresult, forurl, searchtype AS serachtext, mprid, dbo.fun_findcount(searchresult) AS cnt FROM tmp_temp ORDER BY cnt ASC NULLS FIRST LIMIT 20;
