  RETURN QUERY SELECT DISTINCT searchresult, fomatedresult, forurl, searchtype AS serachtext, mprid, dbo.fun_findcount(searchresult) AS cnt FROM tmp_temp ORDER BY cnt ASC NULLS FIRST LIMIT 20;
  ELSE
  INSERT INTO tmp_temp SELECT (pmm.producttitle || '' || '(' || pms.subprcode || ')') AS producttitle, (pmm.producttitle || '' || '(' || pms.subprcode || ')') AS producttitle, CAST(pms.sprid AS VARCHAR(100)), 'Product', pmm.mprid FROM ims_masterproduct_temp AS pmm INNER JOIN ims_subproduct_temp AS pms ON pmm.mprid = pms.mprid WHERE ' ' || pmm.producttitle LIKE '%' || v_serchitem || '%' OR ' ' || pms.subprcode LIKE '%' || v_serchitem || '%';
  RETURN QUERY SELECT DISTINCT searchresult, fomatedresult, forurl, searchtype AS serachtext, mprid, dbo.fun_findcount(searchresult) AS cnt FROM tmp_temp ORDER BY cnt ASC NULLS FIRST LIMIT 20;
  END IF;
  DROP TABLE IF EXISTS tmp_temp;
END;
$$;


