--
-- Name: usp_getproductreviewsandcomments(integer, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_getproductreviewsandcomments(v_pmid integer DEFAULT 0, v_reviewtype integer DEFAULT 0) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_count INT;
  v_count1 INT;
  v_rwid INT;
  v_countrev INT;
  v_totalstar INT;
  v_avgrate INT;
BEGIN
  DROP TABLE IF EXISTS tmp_tempdetailsall;
  CREATE TEMP TABLE tmp_tempdetailsall (ROWNUMBER INT GENERATED BY DEFAULT AS IDENTITY,
RCID INT,
NAME VARCHAR(200),
TITLE VARCHAR(100),
RCDESC text,
RORC VARCHAR(10),
RATE INT,
TOTALREVIEWS INT,
AVGRATE INT,
DATE VARCHAR(100)) ON COMMIT DROP;
  SELECT COUNT(rwid) INTO v_countrev FROM tbl_reviewmaster WHERE pmid = v_pmid AND status = 1;
  SELECT COALESCE(SUM(stars), 0) INTO v_totalstar FROM tbl_reviewmaster WHERE pmid = v_pmid AND reviewtype = v_reviewtype AND status = 1;
  IF (v_countrev = 0) THEN
  v_avgrate := 0;
  END IF;
  IF (v_countrev > 0) THEN
  v_avgrate := v_totalstar / v_countrev;
  END IF;
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp ON COMMIT DROP AS SELECT ROW_NUMBER() OVER (ORDER BY date ASC NULLS FIRST) AS r1, rwid, CAST(name AS VARCHAR(200)) AS name, CAST(reviewtitle AS VARCHAR(200)) AS reviewtitle, CAST(reviewdesc AS text) AS reviewdesc, stars, CAST(TO_CHAR(date, 'TMMon DD YYYY FMHH12:MI%p') AS VARCHAR(100)) AS date FROM tbl_reviewmaster WHERE status = 1 AND pmid = v_pmid ORDER BY date ASC NULLS FIRST;
  v_count := 1;
  SELECT COUNT(rwid) INTO v_count1 FROM tmp_temp;
  WHILE (v_count <= v_count1) LOOP
  INSERT INTO tmp_tempdetailsall SELECT rwid, name, reviewtitle, reviewdesc, 'r', stars, v_countrev, v_avgrate, date FROM tmp_temp WHERE r1 = v_count;
  SELECT rwid INTO v_rwid FROM tmp_temp WHERE r1 = v_count;
  INSERT INTO tmp_tempdetailsall SELECT cmid, name, '', comment, 'c', 0, v_countrev, v_avgrate, CAST(TO_CHAR(date, 'TMMon DD YYYY FMHH12:MI%p') AS VARCHAR(100)) AS date FROM tbl_commentswithreview WHERE status = 1 AND rwid = v_rwid ORDER BY date ASC NULLS FIRST;
  v_count := v_count + 1;
  END LOOP;
  DROP TABLE IF EXISTS tmp_temp;
  RETURN QUERY SELECT * FROM tmp_tempdetailsall;
  DROP TABLE IF EXISTS tmp_tempdetailsall;
END;
$$;


