--
-- Name: usp_getproductspridbyattributes(text, character varying, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_getproductspridbyattributes(v_producttitle text DEFAULT 'Dhilon Creations New Cocktail Georgette Mini Party Dresses'::text, v_color character varying DEFAULT 'RED'::character varying, v_mode integer DEFAULT 0) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
BEGIN
  DROP TABLE IF EXISTS tmp_productsdata;
  CREATE TEMP TABLE tmp_productsdata (ROWNUMBER INT GENERATED BY DEFAULT AS IDENTITY NOT NULL,  
  SPRID BIGINT,  
  COLOR VARCHAR(200),  
  SIZE VARCHAR(200),  
  ISACTIVE INT) ON COMMIT DROP;
  IF (v_producttitle <> '') THEN
  INSERT INTO tmp_productsdata SELECT DISTINCT COALESCE(sprid, 0), '', '', isactive FROM ims_masterproductattribute WHERE sprid IN (SELECT sprid FROM ims_subproduct WHERE mprid IN (SELECT mprid FROM ims_masterproduct WHERE producttitle = v_producttitle) AND isactive = 1 AND isverified = 1);
  UPDATE tmp_productsdata SET color = (SELECT COALESCE(value, '') FROM ims_masterproductattribute WHERE title LIKE '%COLOR%' AND value <> '' AND sprid = tmp_productsdata.sprid);
  UPDATE tmp_productsdata SET size = (SELECT COALESCE(value, '') FROM ims_masterproductattribute WHERE title LIKE '%SIZE%' AND value <> '' AND sprid = tmp_productsdata.sprid);
  END IF;
  IF (v_mode = 1) THEN
  IF (v_color <> '') THEN
  RETURN QUERY SELECT rownumber, COALESCE(sprid, 0) AS sprid, COALESCE(color, '') AS color, COALESCE(size, '') AS size, isactive FROM tmp_productsdata WHERE color = v_color ORDER BY size ASC NULLS FIRST;
  ELSE
  RETURN QUERY SELECT REPLACE(color, ' ', '') AS color, sprid, isactive FROM tmp_productsdata ORDER BY sprid ASC NULLS FIRST;
  END IF;
  ELSE
  IF (v_color <> '') THEN
  RETURN QUERY SELECT rownumber, COALESCE(sprid, 0) AS sprid, COALESCE(REPLACE(color, ' ', ''), '') AS color, COALESCE(REPLACE(size, ' ', ''), '') AS size, isactive FROM tmp_productsdata WHERE color = v_color AND size <> '' ORDER BY size ASC NULLS FIRST;
  ELSE
  RETURN QUERY SELECT REPLACE(color, ' ', '') AS color, REPLACE(size, ' ', '') AS size, sprid, isactive FROM tmp_productsdata ORDER BY sprid ASC NULLS FIRST;
  END IF;
  END IF;
  DROP TABLE IF EXISTS tmp_productsdata;
END;
$$;


--
-- Name: usp_getproductspridbyattributes_mobile(text, character varying, bigint); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_getproductspridbyattributes_mobile(v_producttitle text DEFAULT 'Elecant Running Shoes For Men Navy, Green'::text, v_color character varying DEFAULT 'Maroon'::character varying, v_mprid bigint DEFAULT 21564) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
BEGIN
  DROP TABLE IF EXISTS tmp_productsdata;
  CREATE TEMP TABLE tmp_productsdata (ROWNUMBER INT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  SPRID BIGINT,
  COLOR VARCHAR(200),
  SIZE VARCHAR(200),
  ISACTIVE INT,
  ColorCode varchar(50)) ON COMMIT DROP;
  IF (v_producttitle <> '') THEN
  INSERT INTO tmp_productsdata SELECT DISTINCT COALESCE(sprid, 0), '', '', isactive, '' FROM ims_masterproductattribute WHERE sprid IN (SELECT sprid FROM ims_subproduct WHERE mprid IN (SELECT mprid FROM ims_masterproduct WHERE producttitle IN (SELECT producttitle FROM ims_masterproduct WHERE mprid = v_mprid)) AND isactive = 1 AND isverified = 1);
  UPDATE tmp_productsdata SET color = (SELECT COALESCE(value, '') FROM ims_masterproductattribute WHERE title = 'COLOR' AND sprid = tmp_productsdata.sprid);
  UPDATE tmp_productsdata SET size = (SELECT COALESCE(value, '') FROM ims_masterproductattribute WHERE title = 'SIZE' AND sprid = tmp_productsdata.sprid);
  UPDATE tmp_productsdata SET colorcode = (SELECT COALESCE(colorcode, '') FROM tbl_hexacolrcode WHERE colorname = REPLACE(tmp_productsdata.color, ' ', ''));
  END IF;
  IF (v_color <> '') THEN
  RETURN QUERY SELECT rownumber, COALESCE(sprid, 0) AS sprid, COALESCE(color, '') AS color, COALESCE(size, '') AS size, isactive, colorcode FROM tmp_productsdata WHERE color = v_color ORDER BY sprid DESC NULLS LAST;
  ELSE
  RETURN QUERY SELECT COALESCE(color, '') AS color, sprid, isactive, colorcode FROM tmp_productsdata ORDER BY sprid ASC NULLS FIRST;
  END IF;
  DROP TABLE IF EXISTS tmp_productsdata;
END;
$$;


--
-- Name: usp_getproductspridbyattributes_mobile1(text, character varying, bigint); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_getproductspridbyattributes_mobile1(v_producttitle text DEFAULT 'Elecant Running Shoes For Men Navy, Green'::text, v_color character varying DEFAULT 'Maroon'::character varying, v_mprid bigint DEFAULT 21564) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_getsprid bigint;
  v_getimageurl varchar(500);
  v_ulr varchar(150);
  v_countint int;
  v_merchantproductlargeimage varchar(250);
BEGIN
  DROP TABLE IF EXISTS tmp_productsdata;
  CREATE TEMP TABLE tmp_productsdata (ROWNUMBER INT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  SPRID BIGINT,
  COLOR VARCHAR(200),
  SIZE VARCHAR(200),
  ISACTIVE INT,
  ColorCode varchar(50)) ON COMMIT DROP;
  IF (v_producttitle <> '') THEN
  INSERT INTO tmp_productsdata SELECT DISTINCT COALESCE(sprid, 0), '', '', isactive, '' FROM ims_masterproductattribute WHERE sprid IN (SELECT sprid FROM ims_subproduct WHERE mprid IN (SELECT mprid FROM ims_masterproduct WHERE producttitle IN (SELECT producttitle FROM ims_masterproduct WHERE mprid = v_mprid)) AND isactive = 1 AND isverified = 1);
  UPDATE tmp_productsdata SET color = (SELECT COALESCE(value, '') FROM ims_masterproductattribute WHERE title = 'COLOR' AND sprid = tmp_productsdata.sprid);
  UPDATE tmp_productsdata SET size = (SELECT COALESCE(value, '') FROM ims_masterproductattribute WHERE title = 'SIZE' AND sprid = tmp_productsdata.sprid);
  UPDATE tmp_productsdata SET colorcode = (SELECT COALESCE(colorcode, '') FROM tbl_hexacolrcode WHERE colorname = REPLACE(tmp_productsdata.color, ' ', ''));
  END IF;
  IF (v_producttitle <> '') THEN
  v_getsprid := 0;
  v_getimageurl := '';
  v_ulr := '';
  v_countint := 0;
  v_merchantproductlargeimage := '';
  SELECT sprid INTO v_getsprid FROM tmp_productsdata WHERE color = v_color LIMIT 1;
  SELECT merchantimagepath, merchantproductlargeimage INTO v_ulr, v_merchantproductlargeimage FROM tbl_company;
  SELECT productimages INTO v_getimageurl FROM ims_subproduct WHERE sprid = v_getsprid;
  RETURN QUERY SELECT rownumber, v_merchantproductlargeimage AS productlargeimage, COALESCE(sprid, 0) AS sprid, COALESCE(color, '') AS color, COALESCE(size, '') AS size, isactive, colorcode, v_ulr AS baseurl, v_getimageurl AS productimages FROM tmp_productsdata WHERE color = v_color ORDER BY sprid DESC NULLS LAST;
  ELSE
  RETURN QUERY SELECT v_merchantproductlargeimage AS productlargeimage, COALESCE(color, '') AS color, sprid, isactive, colorcode, v_ulr || v_getimageurl AS productimages FROM tmp_productsdata ORDER BY sprid ASC NULLS FIRST;
  END IF;
  DROP TABLE IF EXISTS tmp_productsdata;
END;
$$;


--
-- Name: usp_getproductspridbyattributes_temp(text, character varying, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_getproductspridbyattributes_temp(v_producttitle text DEFAULT 'Chiller Party Baby Girl Mini Frocks, Extra Soft Baby Pink & Turquoise (Pack of 2)'::text, v_color character varying DEFAULT 'Multicolor'::character varying, v_mode integer DEFAULT 1) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
BEGIN
  DROP TABLE IF EXISTS tmp_productsdata;
  CREATE TEMP TABLE tmp_productsdata (ROWNUMBER INT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  SPRID BIGINT,
  COLOR VARCHAR(200),
  SIZE VARCHAR(200),
  ISACTIVE INT) ON COMMIT DROP;
  IF (v_producttitle <> '') THEN
  INSERT INTO tmp_productsdata SELECT DISTINCT COALESCE(sprid, 0), '', '', isactive FROM ims_masterproductattribute_temp WHERE sprid IN (SELECT sprid FROM ims_subproduct_temp WHERE mprid IN (SELECT mprid FROM ims_masterproduct_temp WHERE producttitle = v_producttitle) AND isactive = 1 AND isverified = 0 AND ismerchantstatus <> 0);
  UPDATE tmp_productsdata SET color = (SELECT COALESCE(value, '') FROM ims_masterproductattribute_temp WHERE title = 'COLOR' AND sprid = tmp_productsdata.sprid);
  UPDATE tmp_productsdata SET size = (SELECT COALESCE(value, '') FROM ims_masterproductattribute_temp WHERE title = 'SIZE' AND sprid = tmp_productsdata.sprid);
  END IF;
  IF (v_mode = 1) THEN
  IF (v_color <> '') THEN
  RETURN QUERY SELECT rownumber, COALESCE(sprid, 0) AS sprid, COALESCE(REPLACE(color, ' ', ''), '') AS color, COALESCE(REPLACE(size, ' ', ''), '') AS size, isactive FROM tmp_productsdata WHERE color = v_color AND size <> '';
  ELSE
  RETURN QUERY SELECT REPLACE(color, ' ', '') AS color, sprid, isactive FROM tmp_productsdata ORDER BY sprid ASC NULLS FIRST;
  END IF;
  ELSE
  IF (v_color <> '') THEN
  RETURN QUERY SELECT rownumber, COALESCE(sprid, 0) AS sprid, COALESCE(REPLACE(color, ' ', ''), '') AS color, COALESCE(REPLACE(size, ' ', ''), '') AS size, isactive FROM tmp_productsdata WHERE color = v_color AND size <> '';
  ELSE
  RETURN QUERY SELECT REPLACE(size, ' ', '') AS size, sprid, isactive FROM tmp_productsdata ORDER BY sprid ASC NULLS FIRST;
  END IF;
  END IF;
  DROP TABLE IF EXISTS tmp_productsdata;
END;
$$;


--
-- Name: usp_getpurchasedkitreports(integer, integer, integer, character varying, boolean, character varying, character varying, character varying, character varying, character varying, integer, character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_getpurchasedkitreports(v_startrowindex integer DEFAULT 1, v_maxrows integer DEFAULT 100, v_reqfield integer DEFAULT 0, v_orderbyfield character varying DEFAULT ''::character varying, v_asc boolean DEFAULT false, v_searchfield character varying DEFAULT ''::character varying, v_searchvalue character varying DEFAULT ''::character varying, v_fromdate character varying DEFAULT ''::character varying, v_todate character varying DEFAULT ''::character varying, v_mode character varying DEFAULT '0'::character varying, v_recordcount integer DEFAULT 0, v_status character varying DEFAULT ''::character varying) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_regno BIGINT;
  v_sqlquery text;
  v_modestatus varchar(10);
BEGIN
  -- SET option (removed)
  v_sqlquery := '';
  v_modestatus := '0';
  v_sqlquery := '';
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp (Rownumber Int GENERATED BY DEFAULT AS IDENTITY,
Date Date,
Loginid text,
USERNAME text,
REGNO INT,
Kid Int,
KitName text,
PayMode text,
Amount Decimal(10,2),
Status Varchar(20),
Phone varchar(30)) ON COMMIT DROP;
  v_sqlquery := v_sqlquery || (' INSERT INTO #TEMP SELECT TID.DATE,PL.LOGINID,PL.USERNAME,TID.REGNO,Km.KID,KM.TITLE AS KITNAME,
(CASE WHEN MM.PAYMENTMODE=2 THEN ''Online Banking'' WHEN MM.PAYMENTMODE=3 THEN ''DD'' WHEN MM.PAYMENTMODE=4 THEN ''Cheque''
 WHEN MM.PAYMENTMODE=5 THEN ''Cash'' WHEN MM.PAYMENTMODE=6 THEN ''NEFT'' Else ''N/A'' END) AS PAYMENTMODE,
TID.PRICE AS AMOUNT,(CASE WHEN TID.ISACTIVE = 1 THEN ''Cleared''  WHEN TID.ISACTIVE = 0 THEN ''Pending'' END) AS STATUS, 
(''+''+C.ISDCODE + ''- ''+PL.PHONE) AS Phone 
FROM TBL_INCOMEDISTRIBUTION TID INNER JOIN PORTAL_LOGIN PL ON TID.REGNO = PL.REGNO INNER JOIN KIT_MASTER KM ON KM.KID=TID.KID
 INNER JOIN MEMBER_MASTER MM ON TID.REGNO = MM.REGNO INNER JOIN COUNTRY C ON C.CID= PL.CID WHERE PL.ACTIVE = 1 ');
  IF (v_reqfield = 2) THEN
  v_sqlquery := v_sqlquery || ' AND PAYMENTMODE = 2 ';
  END IF;
  IF (v_reqfield = 3) THEN
  v_sqlquery := v_sqlquery || ' AND PAYMENTMODE = 3 ';
  END IF;
  IF (v_reqfield = 4) THEN
  v_sqlquery := v_sqlquery || ' AND PAYMENTMODE = 4 ';
  END IF;
  IF (v_reqfield = 5) THEN
  v_sqlquery := v_sqlquery || ' AND PAYMENTMODE = 5 ';
  END IF;
  IF (v_reqfield = 6) THEN
  v_sqlquery := v_sqlquery || ' AND PAYMENTMODE = 6 ';
  END IF;
  IF (v_fromdate <> '' OR v_todate <> '') THEN
  IF (v_fromdate <> '') THEN
  v_sqlquery := v_sqlquery || (' AND CONVERT(DATE,TID.DATE,103) >= CONVERT(DATE,''' || v_fromdate || ''',103) ');
  END IF;
  IF (v_todate <> '') THEN
  v_sqlquery := v_sqlquery || (' AND CONVERT(DATE,TID.DATE,103) <= CONVERT(DATE,''' || v_todate || ''',103) ');
  END IF;
  ELSE
  IF (v_fromdate <> '' AND v_todate <> '') THEN
  v_sqlquery := v_sqlquery || (' AND CONVERT(DATE,TID.DATE,103) BETWEEN CONVERT(DATE,''' || v_fromdate || ''',103) AND CONVERT(DATE,''' || v_todate || ''',103) ');
  END IF;
  END IF;
  IF (v_searchvalue = 'LOGINID') THEN
  v_sqlquery := v_sqlquery || (' AND PL.LOGINID LIKE ''%' || v_searchfield || '%'' ');
  END IF;
  IF (v_searchvalue = 'USERNAME') THEN
  v_sqlquery := v_sqlquery || (' AND PL.USERNAME LIKE ''%' || v_searchfield || '%'' ');
  END IF;
  IF (v_searchvalue = 'Phone') THEN
  v_sqlquery := v_sqlquery || (' AND  MM.MOBILE LIKE ''%' || v_searchfield || '%'' ');
  END IF;
  IF (v_searchvalue = 'Kit') THEN
  v_sqlquery := v_sqlquery || (' AND  TID.KID = CONVERT(INT,''' || v_searchfield || ''',103) ');
  END IF;
  IF (v_status = 'Pending') THEN
  v_sqlquery := v_sqlquery || (' AND  TID.ISACTIVE = 0 ');
  END IF;
  IF (v_status = 'Cleared') THEN
  v_sqlquery := v_sqlquery || (' AND  TID.ISACTIVE =  1 ');
  END IF;
  IF (v_orderbyfield = 'datedesc') THEN
  v_sqlquery := v_sqlquery || ' ORDER BY TID.DATE DESC ';
  END IF;
  IF (v_orderbyfield = 'dateasc') THEN
  v_sqlquery := v_sqlquery || ' ORDER BY TID.DATE ASC ';
  END IF;
  EXECUTE v_sqlquery;
  RETURN QUERY SELECT * FROM tmp_temp WHERE rownumber BETWEEN v_startrowindex AND v_maxrows;
  SELECT COUNT(*) INTO v_recordcount FROM tmp_temp;
  RETURN QUERY SELECT v_recordcount AS recordcount;
  DROP TABLE IF EXISTS tmp_temp;
  -- SET option (removed)
END;
$$;


--
-- Name: usp_getpurchasedpackaged_history(integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_getpurchasedpackaged_history(v_did integer DEFAULT 1030) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
BEGIN
  -- BEGIN TRAN (removed)
  IF (v_did > 0) THEN
  RETURN QUERY SELECT ROW_NUMBER() OVER (ORDER BY did NULLS FIRST) AS rownumber, did, packagename, CAST(TO_CHAR(purchaseddate, 'DD TMMon YYYY') AS VARCHAR(30)) AS purchasedate, trp.packageamount, invoiceno, trs.servicename FROM tbl_reseller_purchased_packages AS trpph LEFT JOIN tbl_reseller_packages AS trp ON trpph.trpid = trp.trpid LEFT JOIN tbl_reseller_services AS trs ON trp.trsid = trs.trsid WHERE did = v_did AND istrial <> 1;
  END IF;
  -- COMMIT (removed)
END;
$$;


--
-- Name: usp_getpurchasepackage(integer, integer, integer, character varying, character varying, integer, character varying, character varying, character varying, integer, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_getpurchasepackage(v_mode integer DEFAULT 0, v_startrowindex integer DEFAULT 1, v_maxrows integer DEFAULT 100, v_fromdate character varying DEFAULT ''::character varying, v_todate character varying DEFAULT ''::character varying, v_totalcount integer DEFAULT 0, v_searchfield character varying DEFAULT ''::character varying, v_searchvalue character varying DEFAULT ''::character varying, v_status character varying DEFAULT ''::character varying, v_ddlservice integer DEFAULT 0, v_ddlpackage integer DEFAULT 0) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_minindex INT;
  v_maxindex INT;
  v_query text;
BEGIN
  v_minindex := (v_startrowindex - 1) * v_maxrows + 1;
  v_maxindex := v_startrowindex * v_maxrows;
  IF (v_mode = 0) THEN
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp (ROWNUMBER BIGINT GENERATED BY DEFAULT AS IDENTITY, 
	COMPANYNAME VARCHAR(100),
	TRPPBAID INT,
	SERVICENAME VARCHAR(100),
	PACKAGENAME VARCHAR(100),
	AMOUNT DECIMAL(18,2),
	DISCOUNT DECIMAL(18,2),
	PAYMODE VARCHAR(100),
	BANKNAME VARCHAR(100),
	BRANCHNAME VARCHAR(100),
	CHALLANIMAGE VARCHAR(100),
	REFERENCENO VARCHAR(100),
	REFERENCEDATE VARCHAR(100),
	IFSCCODE VARCHAR(100),
	PURCHASEDATE VARCHAR(100),
	REMARKS VARCHAR(100)) ON COMMIT DROP;
  v_query := 'INSERT INTO #TEMP Select DM.COMPANYNAME,TRPP.TRPPBAID,TRS.SERVICENAME,RP.PACKAGENAME,TRPP.AMOUNT,
TRPP.DISCOUNT,TP.PAYMODE,TRPP.BANKNAME,TRPP.BRANCHNAME,TRPP.CHALLANIMAGE,TRPP.REFERENCENO,
TRPP.REFERENCEDATE,TRPP.IFSCCODE,TRPP.PURCHASEDATE,TRPP.REMARKS 
from TBL_RESELLERPURCHASEDPACKAGES_BY_ADMIN TRPP
LEFT JOIN DISTRIBUTOR_MASTER DM ON TRPP.DID=DM.PMID
LEFT JOIN TBL_RESELLER_SERVICES TRS ON TRPP.STID=TRS.TRSID
LEFT JOIN TBL_RESELLER_PACKAGES RP ON TRPP.TRPID=RP.TRPID
LEFT JOIN TBL_PAYMODE TP ON TRPP.PMOID=TP.PMOID
WHERE TRPP.ACTIVE=1 ';
  IF ((v_fromdate <> '') AND (v_todate = '')) THEN
  v_query := v_query || ' AND CONVERT(DATE, TRPP.PURCHASEDATE, 105) BETWEEN  CONVERT(DATE, ''' || v_fromdate || ''', 105) AND  CONVERT(DATE, DBO.FUN_GETCURRENTDATE(), 105)';
  END IF;
  IF ((v_fromdate = '') AND (v_todate <> '')) THEN
  v_query := v_query || 'AND CONVERT(DATE, TCPR.RECHARGEDATE, 105) BETWEEN  CONVERT(DATE, ''' || v_todate || ''', 105) AND  CONVERT(DATE, DBO.FUN_GETCURRENTDATE(), 105)';
  END IF;
  IF ((v_fromdate <> '') AND (v_todate <> '')) THEN
  v_query := v_query || 'AND CONVERT(DATE, TRPP.PURCHASEDATE, 105) BETWEEN CONVERT(DATE, ''' || v_fromdate || ''', 105) AND  CONVERT(DATE, ''' || v_todate || ''', 105)';
  END IF;
  IF (v_ddlservice > 0) THEN
  v_query := v_query || '  AND TRPP.STID =''' || CAST(v_ddlservice AS VARCHAR) || '''';
  END IF;
  IF (v_ddlpackage > 0) THEN
  v_query := v_query || '  AND RPP.TRPID =''' || CAST(v_ddlpackage AS VARCHAR) || '''';
  END IF;
  v_query := v_query || ' ORDER BY TRPP.PURCHASEDATE DESC';
  EXECUTE v_query;
  RAISE NOTICE '%', v_query;
  RETURN QUERY SELECT * FROM tmp_temp WHERE rownumber BETWEEN v_minindex AND v_maxindex;
  SELECT COUNT(rownumber) INTO v_totalcount FROM tmp_temp;
  DROP TABLE IF EXISTS tmp_temp;
  -- SET option (removed)
  END IF;
END;
$$;


--
-- Name: usp_getrechargedata(character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_getrechargedata(v_uniqueaccountnumber character varying DEFAULT ''::character varying) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
BEGIN
  BEGIN
  IF EXISTS(SELECT 1 FROM tbl_customer_prepaid_recharges WHERE transactionid = v_uniqueaccountnumber AND COALESCE(rechargestatus, -1) = -1) THEN
  RETURN QUERY SELECT ('MOBILEPREPAID') AS type, operatorcode, rechargeamount, mobileno, ('NA') AS storeid, ('') AS stdcode, ('') AS circle, ('') AS accountno FROM tbl_customer_prepaid_recharges WHERE transactionid = v_uniqueaccountnumber AND COALESCE(rechargestatus, -1) = -1;
  END IF;
  IF EXISTS(SELECT 1 FROM tbl_customer_postpaid_recharges WHERE transactionid = v_uniqueaccountnumber AND COALESCE(rechargestatus, -1) = -1) THEN
  RETURN QUERY SELECT ('MOBILEPOSTPAID') AS type, operatorcode, rechargeamount, mobileno, ('NA') AS storeid, ('') AS stdcode, ('') AS circle, ('') AS accountno FROM tbl_customer_postpaid_recharges WHERE transactionid = v_uniqueaccountnumber AND COALESCE(rechargestatus, -1) = -1;
  ELSE
  IF EXISTS(SELECT 1 FROM tbl_customer_datacard_recharges WHERE transactionid = v_uniqueaccountnumber AND COALESCE(rechargestatus, -1) = -1) THEN
  RETURN QUERY SELECT ('DATACARD') AS type, operatorcode, rechargeamount, mobileno, ('NA') AS storeid, ('') AS stdcode, ('') AS circle, ('') AS accountno FROM tbl_customer_datacard_recharges WHERE transactionid = v_uniqueaccountnumber AND COALESCE(rechargestatus, -1) = -1;
  ELSE
  IF EXISTS(SELECT 1 FROM tbl_customer_dth_recharges WHERE transactionid = v_uniqueaccountnumber AND COALESCE(rechargestatus, -1) = -1) THEN
  RETURN QUERY SELECT ('DTH') AS type, operatorcode, rechargeamount, mobileno, ('NA') AS storeid, ('') AS stdcode, ('') AS circle, ('') AS accountno FROM tbl_customer_dth_recharges WHERE transactionid = v_uniqueaccountnumber AND COALESCE(rechargestatus, -1) = -1;
  ELSE
  IF EXISTS(SELECT 1 FROM tbl_customer_landline_recharges WHERE transactionid = v_uniqueaccountnumber AND COALESCE(rechargestatus, -1) = -1) THEN
  RETURN QUERY SELECT ('LANDLINE') AS type, operatorcode, rechargeamount, mobileno, ('NA') AS storeid, stdcode, circle, accountno FROM tbl_customer_landline_recharges WHERE transactionid = v_uniqueaccountnumber AND COALESCE(rechargestatus, -1) = -1;
  ELSE
  IF EXISTS(SELECT 1 FROM tbl_customer_electricity_recharges WHERE transactionid = v_uniqueaccountnumber AND COALESCE(rechargestatus, -1) = -1) THEN
  RETURN QUERY SELECT ('ELECTRICITY') AS type, operatorcode, rechargeamount, mobileno, ('NA') AS storeid, apibody FROM tbl_customer_electricity_recharges WHERE transactionid = v_uniqueaccountnumber AND COALESCE(rechargestatus, -1) = -1;
  ELSE
  IF EXISTS(SELECT 1 FROM tbl_customer_water_recharges WHERE transactionid = v_uniqueaccountnumber AND COALESCE(rechargestatus, -1) = -1) THEN
  RETURN QUERY SELECT ('WATER') AS type, operatorcode, rechargeamount, mobileno, ('NA') AS storeid, apibody FROM tbl_customer_water_recharges WHERE transactionid = v_uniqueaccountnumber AND COALESCE(rechargestatus, -1) = -1;
  ELSE
  IF EXISTS(SELECT 1 FROM tbl_customer_gas_recharges WHERE transactionid = v_uniqueaccountnumber AND COALESCE(rechargestatus, -1) = -1) THEN
  RETURN QUERY SELECT ('GAS') AS type, operatorcode, rechargeamount, mobileno, ('NA') AS storeid, apibody FROM tbl_customer_gas_recharges WHERE transactionid = v_uniqueaccountnumber AND COALESCE(rechargestatus, -1) = -1;
  ELSE
  IF EXISTS(SELECT 1 FROM tbl_customer_broadband_recharges WHERE transactionid = v_uniqueaccountnumber AND COALESCE(rechargestatus, -1) = -1) THEN
  RETURN QUERY SELECT ('BROADBAND') AS type, operatorcode, rechargeamount, mobileno, ('NA') AS storeid, apibody FROM tbl_customer_broadband_recharges WHERE transactionid = v_uniqueaccountnumber AND COALESCE(rechargestatus, -1) = -1;
  END IF;
  END IF;
  END IF;
  END IF;
  END IF;
  END IF;
  END IF;
  END IF;
  EXCEPTION WHEN OTHERS THEN
  NULL;
  END;
END;
$$;


