--
-- Name: usp_getrecords(bigint, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_getrecords(v_regno bigint, v_mode integer) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF (v_mode = 28) THEN
  RETURN QUERY SELECT id, ('../SlideImages/' || imagename) AS imagename, imagename AS im, description FROM slideshowtable WHERE type = 1 AND active = 1;
  END IF;
  IF (v_mode = 29) THEN
  RETURN QUERY SELECT id, ('../SlideImages/' || imagename) AS imagename, imagename AS im, description FROM slideshowtable WHERE type = 2 AND active = 1;
  END IF;
  IF (v_mode = 30) THEN
  RETURN QUERY SELECT id, ('../SlideImages/' || imagename) AS imagename, imagename AS im, description FROM slideshowtable WHERE type = 3 AND active = 1;
  END IF;
  IF (v_mode = 40) THEN
  RETURN QUERY SELECT id, ('../SlideImages/' || imagename) AS imagename, imagename AS im, description FROM slideshowtable WHERE type = 4 AND active = 1;
  END IF;
  IF (v_mode = 31) THEN
  RETURN QUERY SELECT payid, ('Payout No-' || CAST(payid AS VARCHAR(5))) AS payname FROM payout;
  END IF;
  IF (v_mode = 32) THEN
  RETURN QUERY SELECT id, ('SlideImages/' || imagename) AS imagename, imagename AS im, description FROM slideshowtable WHERE type = 1 AND active = 1;
  END IF;
  IF (v_mode = 33) THEN
  RETURN QUERY SELECT id, ('SlideImages/' || imagename) AS imagename, imagename AS im, description FROM slideshowtable WHERE type = 2 AND active = 1;
  END IF;
  IF (v_mode = 34) THEN
  RETURN QUERY SELECT id, ('SlideImages/' || imagename) AS imagename, imagename AS im, description FROM slideshowtable WHERE type = 3 AND active = 1;
  END IF;
END;
$$;


--
-- Name: usp_getrelatedlist(integer, integer, integer, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_getrelatedlist(v_maincatid integer DEFAULT 0, v_catid integer DEFAULT 0, v_subcatid integer DEFAULT 0, v_did integer DEFAULT NULL::integer) RETURNS void
    LANGUAGE plpgsql
    AS $$
BEGIN
  DROP TABLE IF EXISTS tmp_trendingproductsdatanotuse;
  CREATE TEMP TABLE tmp_trendingproductsdatanotuse ON COMMIT DROP AS SELECT DISTINCT ROW_NUMBER() OVER (ORDER BY pm.mprid NULLS FIRST) AS rowno, pm.productcode, pm.maincategoryid, pm.subcategoryid, pm.producttitle, pm.catid, pms.sprid, pms.subprcode, pms.isoutofstock, pms.productimages, pms.shippingcharges, pms.discountpercentage, pms.sellmrp, pms.dap, pms.createddate, COALESCE(pms.cashondelivery, 0) AS cashondelivery, pa.mpaid AS masterproductattriubuteid, COALESCE(dcs.bv, 0) AS bv, COALESCE(dcs.cashback, 0) AS cashback FROM ims_masterproduct AS pm LEFT OUTER JOIN ims_subproduct AS pms ON pms.mprid = pm.mprid LEFT OUTER JOIN ims_masterproductattribute AS pa ON pa.sprid = pms.sprid LEFT OUTER JOIN tbl_category AS c ON pa.catid = c.catid LEFT OUTER JOIN portal_login AS br ON br.plid = pm.branchid LEFT OUTER JOIN tbl_sub_category AS tsb ON pm.subcategoryid = tsb.subcatid LEFT OUTER JOIN tbl_distributor_commission_structure AS dcs ON dcs.subsubcatid = tsb.subcatid AND dcs.did = v_did WHERE br.active = 1 AND pms.isactive = 1 AND pms.isverified = 1 AND br.status = 1 AND COALESCE(isverified, 0) = 1 AND (pm.maincategoryid = v_maincatid OR pm.catid = v_catid OR pm.subcategoryid = v_subcatid);
  INSERT INTO tmp_trendingproductsdata SELECT * FROM tmp_trendingproductsdatanotuse AS tm WHERE rowno IN (SELECT MIN(rowno) FROM tmp_trendingproductsdatanotuse GROUP BY producttitle) LIMIT 50;
  DROP TABLE IF EXISTS tmp_trendingproductsdatanotuse;
END;
$$;


--
-- Name: usp_getreseller_services(integer, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_getreseller_services(v_mode integer DEFAULT 2, v_did integer DEFAULT 1048) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
BEGIN
  -- SET option (removed)
  IF (v_mode = 1) THEN
  RETURN QUERY SELECT trsid, servicename FROM tbl_reseller_services WHERE active = 1;
  END IF;
  IF (v_mode = 2) THEN
  RETURN QUERY SELECT COALESCE(trp.packagename, 'N/A') AS packagename, trs.servicename FROM tbl_reseller_purchased_packages AS trpp LEFT JOIN tbl_reseller_packages AS trp ON trpp.trpid = trp.trpid LEFT JOIN tbl_reseller_services AS trs ON trpp.trsid = trs.trsid WHERE trpp.did = v_did;
  END IF;
  -- SET option (removed)
END;
$$;


--
-- Name: usp_getsalereports(character varying, character varying, character varying, bigint); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_getsalereports(v_monthyear character varying DEFAULT ''::character varying, v_searchfield character varying DEFAULT ''::character varying, v_searchtype character varying DEFAULT ''::character varying, v_branchid bigint DEFAULT 0) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_query text;
BEGIN
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp (MonthAndYear varchar(50),

order_cost numeric(19,4)) ON COMMIT DROP;
  v_query := 'insert into #temp SELECT CONVERT(CHAR(2), CSO.OrderDate, 103)+'' ''+CONVERT(CHAR(4), CSO.OrderDate, 100)  as MonthAndYear,CSP.total_cost

 from tbl_product_order_master CSP inner join tbl_order_master CSO  on CSO.orderID=CSP.orderID  where CSO.orid>0 and CSO.BranchId = ' || CAST(v_branchid AS VARCHAR(50));
  IF (v_searchfield <> 'Saleswise') THEN
  IF (v_searchfield = 'Productwise') THEN
  v_query := v_query || ' and CSP.SubPrCode=''' || v_searchtype || '''';
  END IF;
  IF (v_searchfield = 'Branchwise') THEN
  v_query := v_query || ' and CSO.brcode=''' || v_searchtype || '''';
  END IF;
  END IF;
  IF (v_monthyear <> '') THEN
  v_query := v_query || ' and CONVERT(CHAR(3), CSP.order_date, 100) + CONVERT(CHAR(4), CSP.order_date, 120)=''' || v_monthyear || '''';
  END IF;
  EXECUTE v_query;
  RETURN QUERY SELECT monthandyear, SUM(order_cost) AS order_cost FROM tmp_temp GROUP BY monthandyear ORDER BY monthandyear ASC NULLS FIRST;
  DROP TABLE IF EXISTS tmp_temp;
  -- SET option (removed)
END;
$$;


--
-- Name: usp_getsalesreport(integer, integer, integer, character varying, boolean, character varying, character varying, character varying, character varying, character varying, integer, character varying, character varying, character varying, character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_getsalesreport(v_startrowindex integer DEFAULT 1, v_maxrows integer DEFAULT 100, v_reqfield integer DEFAULT 0, v_orderbyfield character varying DEFAULT ''::character varying, v_asc boolean DEFAULT false, v_searchfield character varying DEFAULT ''::character varying, v_searchvalue character varying DEFAULT ''::character varying, v_fromdate character varying DEFAULT ''::character varying, v_todate character varying DEFAULT ''::character varying, v_mode character varying DEFAULT '0'::character varying, v_recordcount integer DEFAULT 0, v_status character varying DEFAULT ''::character varying, v_loginid character varying DEFAULT ''::character varying, v_username character varying DEFAULT ''::character varying, v_mobile character varying DEFAULT ''::character varying) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_regno BIGINT;
  v_sqlquery text;
  v_modestatus varchar(10);
BEGIN
  -- SET option (removed)
  v_sqlquery := '';
  v_modestatus := '0';
  v_sqlquery := '';
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp (Rownumber Int GENERATED BY DEFAULT AS IDENTITY,
TSMID int,
Price decimal(18,2),
IsActive int,
Status int,
TTSID int,
Discount decimal(18,2),
NetPayable decimal(18,2),
invoice_num varchar(200),
service_tax decimal(18,2),
service_tax_per decimal(18,2),
payble_amt decimal(18,2),
TMSAID bigint,
username varchar(150),
emailid varchar(150),
fullname varchar(150),
phone varchar(50)) ON COMMIT DROP;
  v_sqlquery := v_sqlquery || (' INSERT INTO #TEMP SELECT TID.TSMID,isnull(TID.Price,0),TID.IsActive,TID.Status,TID.TTSID,isnull(TID.Discount,0) AS Discount,isnull(TID.NetPayable,0),
isnull(TID.invoice_num,''''),isnull(TID.service_tax,0),isnull(TID.service_tax_per,0),isnull(TID.payble_amt,0),msa.TMSAID,isnull(pl.username,''''),isnull(pl.emailid,''''),
isnull(pl.FNAME,'''')+'' ''+isnull(pl.Lname,'''') as fullname, isnull(pl.phone,0) FROM Tbl_MemberSubscriptionAccount msa inner join Tbl_SubscriptionMaster TID   on TID.TSMID=msa.TSMID
 inner join portal_login pl on pl.plid=msa.Plid ');
  IF (v_searchvalue = 'LOGINID') THEN
  v_sqlquery := v_sqlquery || (' AND PL.emailid LIKE ''%' || v_searchfield || '%'' ');
  END IF;
  IF (v_searchvalue = 'USERNAME') THEN
  v_sqlquery := v_sqlquery || (' AND PL.USERNAME LIKE ''%' || v_searchfield || '%'' ');
  END IF;
  IF (v_searchvalue = 'Phone') THEN
  v_sqlquery := v_sqlquery || (' AND  pl.phone LIKE ''%' || v_searchfield || '%'' ');
  END IF;
  IF (v_loginid <> '') THEN
  v_sqlquery := v_sqlquery || ' AND ISNULL(PL.emailid,'''') LIKE ''%' || v_loginid || '%''';
  END IF;
  IF (v_username <> '') THEN
  v_sqlquery := v_sqlquery || ' AND ISNULL(PL.USERNAME,'''') LIKE ''%' || v_username || '%''';
  END IF;
  IF (v_mobile <> '') THEN
  v_sqlquery := v_sqlquery || ' AND ISNULL(pl.phone,'''') LIKE ''%' || v_mobile || '%''';
  END IF;
  EXECUTE v_sqlquery;
  RETURN QUERY SELECT * FROM tmp_temp WHERE rownumber BETWEEN v_startrowindex AND v_maxrows;
  SELECT COUNT(*) INTO v_recordcount FROM tmp_temp;
  RETURN QUERY SELECT v_recordcount AS recordcount;
  DROP TABLE IF EXISTS tmp_temp;
  -- SET option (removed)
END;
$$;


--
-- Name: usp_getsalessummary_merchant_dashboard(integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_getsalessummary_merchant_dashboard(v_regno integer DEFAULT 1) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
