	SALEAMOUNT DECIMAL(18,2),
	COLOR VARCHAR(50)) ON COMMIT DROP;
  INSERT INTO tmp_tempsalesummary VALUES (CAST(CAST(dbo.FUN_GETCURRENTDATE() - 1 AS DATE) AS VARCHAR), 0, '#FF9E01');
  INSERT INTO tmp_tempsalesummary VALUES (CAST(CAST(dbo.FUN_GETCURRENTDATE() - 2 AS DATE) AS VARCHAR), 0, '#FF9E01');
  INSERT INTO tmp_tempsalesummary VALUES (CAST(CAST(dbo.FUN_GETCURRENTDATE() - 3 AS DATE) AS VARCHAR), 0, '#FF9E01');
  INSERT INTO tmp_tempsalesummary VALUES (CAST(CAST(dbo.FUN_GETCURRENTDATE() - 4 AS DATE) AS VARCHAR), 0, '#FF9E01');
  INSERT INTO tmp_tempsalesummary VALUES (CAST(CAST(dbo.FUN_GETCURRENTDATE() - 5 AS DATE) AS VARCHAR), 0, '#FF9E01');
  INSERT INTO tmp_tempsalesummary VALUES (CAST(CAST(dbo.FUN_GETCURRENTDATE() - 6 AS DATE) AS VARCHAR), 0, '#FF9E01');
  INSERT INTO tmp_tempsalesummary VALUES (CAST(CAST(dbo.FUN_GETCURRENTDATE() - 7 AS DATE) AS VARCHAR), 0, '#FF9E01');
  INSERT INTO tmp_tempsalesummary VALUES (CAST(CAST(dbo.FUN_GETCURRENTDATE() - 8 AS DATE) AS VARCHAR), 0, '#FF9E01');
  INSERT INTO tmp_tempsalesummary VALUES (CAST(CAST(dbo.FUN_GETCURRENTDATE() - 9 AS DATE) AS VARCHAR), 0, '#FF9E01');
  INSERT INTO tmp_tempsalesummary VALUES (CAST(CAST(dbo.FUN_GETCURRENTDATE() - 10 AS DATE) AS VARCHAR), 0, '#FF9E01');
  UPDATE tmp_tempsalesummary SET saledate = CAST(CAST(dbo.FUN_GETCURRENTDATE() - 1 AS DATE) AS VARCHAR), saleamount = (SELECT COALESCE(SUM(order_netamt), 0) FROM tbl_order_master WHERE CAST(orderdate AS DATE) = CAST(dbo.FUN_GETCURRENTDATE() - 1 AS DATE) AND intstatus = 6 AND intstatus <> 7 AND intstatus <> 8) WHERE CAST(saledate AS DATE) = CAST(dbo.FUN_GETCURRENTDATE() - 1 AS DATE);
  UPDATE tmp_tempsalesummary SET saledate = CAST(CAST(dbo.FUN_GETCURRENTDATE() - 2 AS DATE) AS VARCHAR), saleamount = (SELECT COALESCE(SUM(order_netamt), 0) FROM tbl_order_master WHERE CAST(orderdate AS DATE) = CAST(dbo.FUN_GETCURRENTDATE() - 2 AS DATE) AND intstatus = 6 AND intstatus <> 7 AND intstatus <> 8) WHERE CAST(saledate AS DATE) = CAST(dbo.FUN_GETCURRENTDATE() - 2 AS DATE);
  UPDATE tmp_tempsalesummary SET saledate = CAST(CAST(dbo.FUN_GETCURRENTDATE() - 3 AS DATE) AS VARCHAR), saleamount = (SELECT COALESCE(SUM(order_netamt), 0) FROM tbl_order_master WHERE CAST(orderdate AS DATE) = CAST(dbo.FUN_GETCURRENTDATE() - 3 AS DATE) AND intstatus = 6 AND intstatus <> 7 AND intstatus <> 8) WHERE CAST(saledate AS DATE) = CAST(dbo.FUN_GETCURRENTDATE() - 3 AS DATE);
  UPDATE tmp_tempsalesummary SET saledate = CAST(CAST(dbo.FUN_GETCURRENTDATE() - 4 AS DATE) AS VARCHAR), saleamount = (SELECT COALESCE(SUM(order_netamt), 0) FROM tbl_order_master WHERE CAST(orderdate AS DATE) = CAST(dbo.FUN_GETCURRENTDATE() - 4 AS DATE) AND intstatus = 6 AND intstatus <> 7 AND intstatus <> 8) WHERE CAST(saledate AS DATE) = CAST(dbo.FUN_GETCURRENTDATE() - 4 AS DATE);
  UPDATE tmp_tempsalesummary SET saledate = CAST(CAST(dbo.FUN_GETCURRENTDATE() - 5 AS DATE) AS VARCHAR), saleamount = (SELECT COALESCE(SUM(order_netamt), 0) FROM tbl_order_master WHERE CAST(orderdate AS DATE) = CAST(dbo.FUN_GETCURRENTDATE() - 5 AS DATE) AND intstatus = 6 AND intstatus <> 7 AND intstatus <> 8) WHERE CAST(saledate AS DATE) = CAST(dbo.FUN_GETCURRENTDATE() - 5 AS DATE);
  UPDATE tmp_tempsalesummary SET saledate = CAST(CAST(dbo.FUN_GETCURRENTDATE() - 6 AS DATE) AS VARCHAR), saleamount = (SELECT COALESCE(SUM(order_netamt), 0) FROM tbl_order_master WHERE CAST(orderdate AS DATE) = CAST(dbo.FUN_GETCURRENTDATE() - 6 AS DATE) AND intstatus = 6 AND intstatus <> 7 AND intstatus <> 8) WHERE CAST(saledate AS DATE) = CAST(dbo.FUN_GETCURRENTDATE() - 6 AS DATE);
  UPDATE tmp_tempsalesummary SET saledate = CAST(CAST(dbo.FUN_GETCURRENTDATE() - 7 AS DATE) AS VARCHAR), saleamount = (SELECT COALESCE(SUM(order_netamt), 0) FROM tbl_order_master WHERE CAST(orderdate AS DATE) = CAST(dbo.FUN_GETCURRENTDATE() - 7 AS DATE) AND intstatus = 6 AND intstatus <> 7 AND intstatus <> 8) WHERE CAST(saledate AS DATE) = CAST(dbo.FUN_GETCURRENTDATE() - 7 AS DATE);
  UPDATE tmp_tempsalesummary SET saledate = CAST(CAST(dbo.FUN_GETCURRENTDATE() - 8 AS DATE) AS VARCHAR), saleamount = (SELECT COALESCE(SUM(order_netamt), 0) FROM tbl_order_master WHERE CAST(orderdate AS DATE) = CAST(dbo.FUN_GETCURRENTDATE() - 8 AS DATE) AND intstatus = 6 AND intstatus <> 7 AND intstatus <> 8) WHERE CAST(saledate AS DATE) = CAST(dbo.FUN_GETCURRENTDATE() - 8 AS DATE);
  UPDATE tmp_tempsalesummary SET saledate = CAST(CAST(dbo.FUN_GETCURRENTDATE() - 9 AS DATE) AS VARCHAR), saleamount = (SELECT COALESCE(SUM(order_netamt), 0) FROM tbl_order_master WHERE CAST(orderdate AS DATE) = CAST(dbo.FUN_GETCURRENTDATE() - 9 AS DATE) AND intstatus = 6 AND intstatus <> 7 AND intstatus <> 8) WHERE CAST(saledate AS DATE) = CAST(dbo.FUN_GETCURRENTDATE() - 9 AS DATE);
  UPDATE tmp_tempsalesummary SET saledate = CAST(CAST(dbo.FUN_GETCURRENTDATE() - 10 AS DATE) AS VARCHAR), saleamount = (SELECT COALESCE(SUM(order_netamt), 0) FROM tbl_order_master WHERE CAST(orderdate AS DATE) = CAST(dbo.FUN_GETCURRENTDATE() - 10 AS DATE) AND intstatus = 6 AND intstatus <> 7 AND intstatus <> 8) WHERE CAST(saledate AS DATE) = CAST(dbo.FUN_GETCURRENTDATE() - 10 AS DATE);
  RETURN QUERY SELECT * FROM tmp_tempsalesummary;
