  INSERT INTO tmp_selerlist VALUES ('Commission (Including GST)', COALESCE((v_addmisioncomsion + (v_addmisioncomsion * v_gst) / 100), 0), COALESCE((v_addmisioncomsion + (v_addmisioncomsion * v_gst) / 100), 0), COALESCE((v_addmisioncomsion + (v_addmisioncomsion * v_gst) / 100), 0), COALESCE((v_addmisioncomsion + (v_addmisioncomsion * v_gst) / 100), 0));
  INSERT INTO tmp_selerlist VALUES ('Shiping Charge', COALESCE(v_deliverycharge, 0), COALESCE(v_deliverycharge, 0), COALESCE(v_deliverycharge, 0), COALESCE(v_deliverycharge, 0));
  INSERT INTO tmp_selerlist VALUES ('Shiping GST(%)', COALESCE((v_deliverycharge * v_gst) / 100, 0), COALESCE((v_deliverycharge * v_gst) / 100, 0), COALESCE((v_deliverycharge * v_gst) / 100, 0), COALESCE((v_deliverycharge * v_gst) / 100, 0));
  INSERT INTO tmp_selerlist VALUES ('Shiping Fee (Including GST)', COALESCE((v_deliverycharge + (v_deliverycharge * v_gst) / 100), 0), COALESCE((v_deliverycharge + (v_deliverycharge * v_gst) / 100), 0), COALESCE((v_deliverycharge + (v_deliverycharge * v_gst) / 100), 0), COALESCE((v_deliverycharge + (v_deliverycharge * v_gst) / 100), 0));
  INSERT INTO tmp_selerlist VALUES ('Fixed Fee Charge', COALESCE(v_fixedcomssion, 0), COALESCE(v_fixedcomssion, 0), COALESCE(v_fixedcomssion, 0), COALESCE(v_fixedcomssion, 0));
  INSERT INTO tmp_selerlist VALUES ('Fixed GST(%)', COALESCE((v_fixedcomssion * v_gst) / 100, 0), COALESCE((v_fixedcomssion * v_gst) / 100, 0), COALESCE((v_fixedcomssion * v_gst) / 100, 0), COALESCE((v_fixedcomssion * v_gst) / 100, 0));
  INSERT INTO tmp_selerlist VALUES ('Fixed Fee (Including GST)', COALESCE((v_fixedcomssion + (v_fixedcomssion * v_gst) / 100), 0), COALESCE((v_fixedcomssion + (v_fixedcomssion * v_gst) / 100), 0), COALESCE((v_fixedcomssion + (v_fixedcomssion * v_gst) / 100), 0), COALESCE((v_fixedcomssion + (v_fixedcomssion * v_gst) / 100), 0));
  INSERT INTO tmp_selerlist VALUES ('Handling Fee Charge', COALESCE(v_handlingcharge, 0), COALESCE(v_handlingcharge, 0), COALESCE(v_handlingcharge, 0), COALESCE(v_handlingcharge, 0));
  INSERT INTO tmp_selerlist VALUES ('Handling GST(%)', COALESCE((v_handlingcharge * v_gst) / 100, 0), COALESCE((v_handlingcharge * v_gst) / 100, 0), COALESCE((v_handlingcharge * v_gst) / 100, 0), COALESCE((v_handlingcharge * v_gst) / 100, 0));
  INSERT INTO tmp_selerlist VALUES ('Handling Fee (Including GST)', COALESCE((v_handlingcharge + (v_handlingcharge * v_gst) / 100), 0), COALESCE((v_handlingcharge + (v_handlingcharge * v_gst) / 100), 0), COALESCE((v_handlingcharge + (v_handlingcharge * v_gst) / 100), 0), COALESCE((v_handlingcharge + (v_handlingcharge * v_gst) / 100), 0));
  INSERT INTO tmp_selerlist VALUES ('Settlement Value', (COALESCE(v_selingprice + v_localcharge - (v_addmisioncomsion + (v_addmisioncomsion * v_gst) / 100) - (v_deliverycharge + (v_deliverycharge * v_gst) / 100) - (v_fixedcomssion + (v_fixedcomssion * v_gst) / 100) - (v_handlingcharge + (v_handlingcharge * v_gst) / 100), 0)), (COALESCE(v_selingprice + v_zonalcharge - (v_addmisioncomsion + (v_addmisioncomsion * v_gst) / 100) - (v_deliverycharge + (v_deliverycharge * v_gst) / 100) - (v_fixedcomssion + (v_fixedcomssion * v_gst) / 100) - (v_handlingcharge + (v_handlingcharge * v_gst) / 100), 0)), (COALESCE(v_selingprice + v_metro - (v_addmisioncomsion + (v_addmisioncomsion * v_gst) / 100) - (v_deliverycharge + (v_deliverycharge * v_gst) / 100) - (v_fixedcomssion + (v_fixedcomssion * v_gst) / 100) - (v_handlingcharge + (v_handlingcharge * v_gst) / 100), 0)), (COALESCE(v_selingprice + v_nationalcharge - (v_addmisioncomsion + (v_addmisioncomsion * v_gst) / 100) - (v_deliverycharge + (v_deliverycharge * v_gst) / 100) - (v_fixedcomssion + (v_fixedcomssion * v_gst) / 100) - (v_handlingcharge + (v_handlingcharge * v_gst) / 100), 0)));
  RETURN QUERY SELECT * FROM tmp_selerlist;
  DROP TABLE IF EXISTS tmp_selerlist;
  END IF;
  -- SET option (removed)
  IF (0 <> 0) THEN
  -- ROLLBACK (removed)
  RETURN;
  END IF;
  -- COMMIT (removed)
END;
$$;


