--
-- Name: usp_getsettmelntreport(integer, integer, integer, integer, character varying, character varying, integer, character varying, character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_getsettmelntreport(v_mode integer DEFAULT 1, v_startrowindex integer DEFAULT 1, v_maxrows integer DEFAULT 100, v_plid integer DEFAULT 1015, v_fromdate character varying DEFAULT ''::character varying, v_todate character varying DEFAULT ''::character varying, INOUT v_totalcount integer DEFAULT 0, v_orderid character varying DEFAULT ''::character varying, v_invoiceno character varying DEFAULT ''::character varying) RETURNS integer
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_minindex INT;
  v_maxindex INT;
  v_query text;
  v_condition text;
  v_countquery text;
  v_gstpercentage DECIMAL(18,2);
  v_parmdefinition text;
BEGIN
  -- BEGIN TRAN (removed)
  v_condition := '';
  v_countquery := '';
  v_gstpercentage := 0;
  v_minindex := (v_startrowindex - 1) * v_maxrows + 1;
  v_maxindex := v_startrowindex * v_maxrows;
  -- SET option (removed)
  IF (v_mode = 1) THEN
  IF (v_orderid = '') THEN
  -- COMMIT (removed)
  v_totalcount := 0;
  RETURN;
  END IF;
  IF (v_invoiceno = '') THEN
  -- COMMIT (removed)
  v_totalcount := 0;
  RETURN;
  END IF;
  SELECT COALESCE(limits, 0) INTO v_gstpercentage FROM settings WHERE caption = 'GST PERCENTAGE' AND active = 1 AND sid = 22;
  v_query := N'SELECT ROW_NUMBER() OVER(ORDER BY POM.POID ASC ) AS ROWNUMBER,POM.INVOICENO, POM.ORDERID,POM.ORDERNO, POM.TOTAL_PURCHASE_COST as ProductActualAmount ,CONVERT(VARCHAR,OCS.INTRANSIT,106) AS DISPATCHDATE,
INTSTATUS,Cast(((POM.TOTAL_PURCHASE_COST*SP.ADMINCHARGE)/100)+sp.HandlingCharge+TMS.SHIPPINGCHARGES+((POM.TOTAL_PURCHASE_COST*SP.FixedFee)/100)as decimal(18,2)) as Marketplacefee,
Cast((((POM.TOTAL_PURCHASE_COST*SP.ADMINCHARGE)/100)+sp.HandlingCharge+((POM.TOTAL_PURCHASE_COST*SP.FixedFee)/100))*(TMCS.CGSTRATE+TMCS.SGSTRATE+TMCS.IGSTRATE)/100 as decimal(18,2)) as Totalgst
 INTO #TEMP FROM TBL_PRODUCT_ORDER_MASTER POM  
LEFT JOIN TBL_ORDER_CONFIRMEDSTAUS OCS ON POM.ORDERNO=OCS.ORDERNO
INNER JOIN IMS_SUBPRODUCT SP ON POM.SUBPRCODE=SP.SPRID
INNER JOIN TBL_MERCHANT_SHIPPINGINVOICES_DETAILS TMS ON POM.ORDERNO=TMS.ORDERNO 
INNER JOIN TBL_MERCHANT_COMMISSIONINVOICES_DETAILS TMCS ON POM.ORDERNO=TMCS.ORDERNO 
WHERE POM.ORDERID=''' || CAST(v_orderid AS VARCHAR) || ''' AND
POM.INVOICENO=''' || CAST(v_invoiceno AS VARCHAR) || '''';
  v_parmdefinition := N'@TOTALCOUNT NVARCHAR(1000) OUTPUT';
  v_countquery := N'SELECT @TOTALCOUNT=COUNT(1) FROM TBL_PRODUCT_ORDER_MASTER POM   
INNER JOIN TBL_ORDER_CONFIRMEDSTAUS OC   ON POM.ORDERNO=OC.ORDERNO WHERE POM.PLID<>0 AND POM.ORDERID=''' || CAST(v_orderid AS VARCHAR) || ''' AND POM.INVOICENO=''' || CAST(v_invoiceno AS VARCHAR) || '''';
  IF ((v_fromdate <> '') AND (v_todate = '')) THEN
  v_query := v_query || ' AND CONVERT(DATE, OCS.INTRANSIT, 105) BETWEEN  CONVERT(DATE, ''' || v_fromdate || ''', 105) AND  CONVERT(DATE, DBO.FUN_GETCURRENTDATE(), 105)';
  END IF;
  IF ((v_fromdate = '') AND (v_todate <> '')) THEN
  v_query := v_query || 'AND CONVERT(DATE, OCS.INTRANSIT, 105) BETWEEN  CONVERT(DATE, ''' || v_todate || ''', 105) AND  CONVERT(DATE, DBO.FUN_GETCURRENTDATE(), 105)';
  END IF;
  IF ((v_fromdate <> '') AND (v_todate <> '')) THEN
  v_query := v_query || 'AND CONVERT(DATE,OCS.INTRANSIT, 105) BETWEEN CONVERT(DATE, ''' || v_fromdate || ''', 105) AND  CONVERT(DATE, ''' || v_todate || ''', 105)';
  END IF;
  IF (v_plid > 0) THEN
  v_condition := v_condition || ' AND POM.PLID=' || CAST(v_plid AS VARCHAR(30)) || '';
  END IF;
  v_query := v_query || v_condition || ' ;SELECT  *  FROM #TEMP WHERE ROWNUMBER BETWEEN ' || CAST(v_minindex AS text) || ' AND ' || CAST(v_maxindex AS text) || '';
  v_query := v_query;
  v_countquery := v_countquery || v_condition;
  EXECUTE v_query;
  EXECUTE v_countquery;
  RAISE NOTICE '%', v_query;
  RAISE NOTICE '%', v_totalcount;
  -- SET option (removed)
  END IF;
  -- COMMIT (removed)
END;
$$;


--
-- Name: usp_getsettmelntreport_admin(integer, integer, integer, integer, character varying, character varying, integer, character varying, character varying, character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_getsettmelntreport_admin(v_mode integer DEFAULT 1, v_startrowindex integer DEFAULT 1, v_maxrows integer DEFAULT 100, v_plid integer DEFAULT 0, v_fromdate character varying DEFAULT ''::character varying, v_todate character varying DEFAULT ''::character varying, INOUT v_totalcount integer DEFAULT 0, v_merchantname character varying DEFAULT ''::character varying, v_searchfield character varying DEFAULT ''::character varying, v_searchvalue character varying DEFAULT ''::character varying) RETURNS integer
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_minindex INT;
  v_maxindex INT;
  v_query text;
  v_condition text;
  v_countquery text;
  v_gstpercentage decimal(18,2);
  v_parmdefinition text;
BEGIN
  -- BEGIN TRAN (removed)
  v_condition := '';
  v_countquery := '';
  v_gstpercentage := 0;
  v_minindex := (v_startrowindex - 1) * v_maxrows + 1;
  v_maxindex := v_startrowindex * v_maxrows;
  -- SET option (removed)
  IF (v_mode = 1) THEN
  SELECT COALESCE(limits, 0) INTO v_gstpercentage FROM settings WHERE caption = 'GST Percentage' AND active = 1;
  v_query := N'SELECT ROW_NUMBER() OVER(ORDER BY POID ASC ) AS ROWNUMBER, POM.ORDERID as ORDERID,POM.ORDERNO as ORDERNO,
isnull(SINGLE_DAP,0) as ProductActualAmount,ISNULL((POM.SINGLE_DAP*SP.ADMINCHARGE)/100,0)  AS ADMINCHARGE,
sp.DelieveryCharge,sp.HandlingCharge,SP.FixedFee,
(ISNULL((POM.SINGLE_DAP*SP.ADMINCHARGE)/100,0)*''' || CAST(v_gstpercentage AS VARCHAR(20)) || '''/100) as admingst, 
(sp.DelieveryCharge*''' || CAST(v_gstpercentage AS VARCHAR(20)) || '''/100) as DeleveryGSt,
(sp.HandlingCharge*''' || CAST(v_gstpercentage AS VARCHAR(20)) || '''/100) as HandlingGSt,
(sp.FixedFee*''' || CAST(v_gstpercentage AS VARCHAR(20)) || '''/100) as FixedFeeGSt,
((((POM.SINGLE_DAP*SP.ADMINCHARGE)/100)+sp.DelieveryCharge+sp.HandlingCharge+sp.FixedFee)*''' || CAST(v_gstpercentage AS VARCHAR(20)) || '''/100) as Totalgst,
(((POM.SINGLE_DAP*SP.ADMINCHARGE)/100)+sp.DelieveryCharge+sp.HandlingCharge+sp.FixedFee) as Marketplacefee,
POM.STATUS as Status,
convert(varchar(100),OC.Delivered,106) as Completeddate,
convert(varchar(100),OM.OrderDate,106) as OrderDate,OM.BranchId,
isnull(pm.companyname,'''')as Name,
isnull(pl.Emailid,'''')as Emailid,
isnull(pl.Phone,'''')as Phone,
(select Loginid from portal_login where plid=pom.plid) as Loginid  INTO #TEMP
FROM TBL_PRODUCT_ORDER_MASTER POM  
INNER JOIN TBL_ORDER_MASTER OM ON POM.ORDERID=OM.ORDERID
left join portal_login pl on pl.plid=pom.plid
left join portal_master pm on pm.plid=pl.plid
INNER JOIN IMS_SUBPRODUCT SP ON POM.SUBPRCODE=SP.SPRID
Inner JOIN tbl_Order_ConfirmedStaus OC ON POM.Orderno=OC.orderno
WHERE  POM.IntStatus=6 ';
  v_parmdefinition := N'@TOTALCOUNT NVARCHAR(1000) OUTPUT';
  v_countquery := N'SELECT @TOTALCOUNT=Count(1) FROM TBL_PRODUCT_ORDER_MASTER POM   
Inner JOIN tbl_Order_ConfirmedStaus OC ON POM.Orderno=OC.orderno WHERE POM.PLID<>0 ';
  IF ((v_fromdate <> '') AND (v_todate = '')) THEN
  v_condition := v_condition || ' AND CONVERT(VARCHAR, CONVERT(DATE, OC.Delivered, 105)) BETWEEN  CONVERT(DATE, ''' || v_fromdate || ''', 105) AND  CONVERT(DATE, DBO.FUN_GETCURRENTDATE(), 105)';
  END IF;
  IF ((v_fromdate = '') AND (v_todate <> '')) THEN
  v_condition := v_condition || ' AND CONVERT(DATE, OC.Delivered, 105) BETWEEN  CONVERT(DATE, ''' || v_todate || ''', 105) AND  CONVERT(DATE, DBO.FUN_GETCURRENTDATE(), 105)';
  END IF;
  IF ((v_fromdate <> '') AND (v_todate <> '')) THEN
  v_condition := v_condition || 'AND CONVERT(DATE,  OC.Delivered, 105) BETWEEN CONVERT(DATE, ''' || v_fromdate || ''', 105) AND  CONVERT(DATE, ''' || v_todate || ''', 105)';
  END IF;
  IF (v_plid > 0) THEN
  v_condition := v_condition || ' AND POM.PLID=' || CAST(v_plid AS VARCHAR(30)) || '';
  END IF;
  IF (v_merchantname <> '') THEN
  v_query := v_query || ' AND PM.COMPANYNAME=''' || v_merchantname || '''';
  END IF;
  IF (v_searchfield = 'EMAILID') THEN
  v_query := v_query || ' AND PL.EMAILID= ''' || v_searchvalue || ''' ';
  END IF;
  IF (v_searchfield = 'LOGINID') THEN
  v_query := v_query || ' AND PL.LOGINID= ''' || v_searchvalue || ''' ';
  END IF;
  IF (v_searchfield = 'PHONE') THEN
  v_query := v_query || ' AND PL.PHONE= ''' || v_searchvalue || ''' ';
  END IF;
  v_query := v_query || v_condition || ' ;SELECT  *  FROM #TEMP WHERE ROWNUMBER BETWEEN ' || CAST(v_minindex AS text) || ' AND ' || CAST(v_maxindex AS text) || '';
  v_query := v_query;
  v_countquery := v_countquery || v_condition;
  EXECUTE v_query;
  EXECUTE v_countquery;
  RAISE NOTICE '%', v_query;
  -- SET option (removed)
  END IF;
  -- COMMIT (removed)
END;
$$;


--
-- Name: usp_getshoppingcartdata(integer, character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_getshoppingcartdata(v_clid integer DEFAULT 994, v_sessionid character varying DEFAULT '3s2vmbom5e1tbt4j2kdp1shq'::character varying) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF (v_clid <> 0) THEN
  RETURN QUERY SELECT cart.sprid AS sprid, mainpr.producttitle AS prtitle, CAST(ROUND(CASE WHEN COALESCE(offer.product_id, '') <> '' THEN offer.offer_price * cart.qty ELSE (COALESCE(CAST(((subpr.dap + (subpr.dap * vc.vatpercvalue) / 100) * cart.qty) AS DECIMAL(18, 8)), 0)) END, 2) AS DECIMAL) AS paybleamount, subpr.productimages AS images, cart.qty AS quantity, cart.qty * subpr.bv AS bv, subpr.activationpv_per AS pv, subpr.cashback_per AS cashback, CASE WHEN COALESCE(offer.product_id, '') <> '' THEN offer.offer_dap ELSE COALESCE(subpr.dap, 0) END AS productrealamount, CAST(ROUND(CASE WHEN COALESCE(offer.product_id, '') <> '' THEN (offer.offer_price) / ((100 + vc.vatpercvalue) / 100) ELSE COALESCE(subpr.dap, 0) END, 2) AS DECIMAL) AS dap, offer.product_id, vc.vatpercvalue FROM dbo.tbl_addtocart AS cart INNER JOIN dbo.ims_subproduct AS subpr ON subpr.sprid = cart.sprid INNER JOIN dbo.ims_masterproduct AS mainpr ON mainpr.mprid = subpr.mprid LEFT OUTER JOIN tbl_sub_category AS tsb ON mainpr.subcategoryid = tsb.subcatid LEFT JOIN tbl_vat_categories AS vc ON subpr.vatcategoryid = vc.vcid LEFT JOIN tbl_offer_on_product AS offer ON offer.sprid = subpr.sprid AND CURRENT_TIMESTAMP BETWEEN offer.offer_start AND offer.offer_end WHERE (cart.clid = v_clid OR cart.sessionid = v_sessionid) AND cart.status = 1;
  UPDATE tbl_addtocart SET clid = v_clid WHERE sessionid = v_sessionid;
  END IF;
  IF (v_clid = 0 AND v_sessionid <> '') THEN
  RETURN QUERY SELECT cart.sprid AS sprid, mainpr.producttitle AS prtitle, CAST(ROUND(CASE WHEN COALESCE(offer.product_id, '') <> '' THEN offer.offer_price * cart.qty ELSE (COALESCE(CAST(((subpr.dap + (subpr.dap * vc.vatpercvalue) / 100) * cart.qty) AS DECIMAL(18, 8)), 0)) END, 2) AS DECIMAL) AS paybleamount, subpr.productimages AS images, cart.qty AS quantity, cart.qty * subpr.bv AS bv, subpr.activationpv_per AS pv, subpr.cashback_per AS cashback, COALESCE(subpr.dap, 0) AS productrealamount, CAST(ROUND(COALESCE(subpr.dap, 0), 2) AS DECIMAL) AS dap FROM dbo.tbl_addtocart AS cart INNER JOIN dbo.ims_subproduct AS subpr ON subpr.sprid = cart.sprid INNER JOIN dbo.ims_masterproduct AS mainpr ON mainpr.mprid = subpr.mprid LEFT OUTER JOIN tbl_sub_category AS tsb ON mainpr.subcategoryid = tsb.subcatid LEFT JOIN tbl_vat_categories AS vc ON subpr.vatcategoryid = vc.vcid LEFT JOIN tbl_offer_on_product AS offer ON offer.sprid = subpr.sprid AND CURRENT_TIMESTAMP BETWEEN offer.offer_start AND offer.offer_end WHERE cart.sessionid = CAST(v_sessionid AS VARCHAR(100)) AND cart.status = 1;
  END IF;
END;
$$;


--
-- Name: usp_getshoppingcartitems(bigint, character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_getshoppingcartitems(v_clid bigint DEFAULT 0, v_sessionid character varying DEFAULT ''::character varying) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF (v_clid = 0 AND v_sessionid <> '') THEN
  RETURN QUERY SELECT COALESCE(sprid, 0) AS sprid, COALESCE(clid, 0) AS clid, COALESCE(qty, 0) AS qty FROM dbo.tbl_addtocart WHERE sessionid = v_sessionid AND status = 1;
  END IF;
  IF (v_clid > 0) THEN
  RETURN QUERY SELECT COALESCE(sprid, 0) AS sprid, COALESCE(clid, 0) AS clid, COALESCE(qty, 0) AS qty FROM dbo.tbl_addtocart WHERE clid = v_clid AND status = 1;
  END IF;
END;
$$;


--
-- Name: usp_getshoppingcartitemscount(bigint, character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_getshoppingcartitemscount(v_clid bigint DEFAULT 0, v_sessionid character varying DEFAULT ''::character varying) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF (v_clid = 0 AND v_sessionid <> '') THEN
  RETURN QUERY SELECT COUNT(1) FROM dbo.tbl_addtocart WHERE sessionid = v_sessionid AND status = 1;
  END IF;
  IF (v_clid > 0) THEN
  RETURN QUERY SELECT COUNT(1) FROM dbo.tbl_addtocart WHERE clid = v_clid AND status = 1;
  END IF;
END;
$$;


--
-- Name: usp_getstate_city_list_mobile(bigint, bigint, character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_getstate_city_list_mobile(v_sid bigint DEFAULT 1, v_mode bigint DEFAULT 1, v_pincode character varying DEFAULT ''::character varying) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_geturl varchar(100);
  v_merchantkycimage varchar(100);
  v_merchantticketimage varchar(100);
  v_getsubcstid varchar(50);
  v_query text;
  v_pmid int;
BEGIN
  v_geturl := '';
  v_merchantkycimage := '';
  v_merchantticketimage := '';
  SELECT profileimagepath, merchantkycimage, merchantticketimage INTO v_geturl, v_merchantkycimage, v_merchantticketimage FROM tbl_company;
  IF (v_mode = 1) THEN
  RETURN QUERY SELECT sid, cid, statename FROM state WHERE sid <> 0 AND sactive = 1 AND cid = 96;
  END IF;
  IF (v_mode = 2) THEN
  RETURN QUERY SELECT ctid, cid, sid, cityname FROM city WHERE sid = v_sid;
  END IF;
  IF (v_mode = 3) THEN
  RETURN QUERY SELECT (SELECT cityname FROM city WHERE ctid = am.ctid) AS cityname, (SELECT statename FROM state WHERE sid = am.sid) AS statename, * FROM area_master AS am WHERE am.pincode = v_pincode;
  END IF;
  IF (v_mode = 4) THEN
  RETURN QUERY SELECT ksid, id AS entityid, name, icon, url, status, matchname FROM tbl_kycstatus WHERE id = v_sid AND status = 1;
  END IF;
  IF (v_mode = 5) THEN
  RETURN QUERY SELECT k.id AS singleid, v_merchantkycimage || image, * FROM kyc AS k RIGHT JOIN tbl_kycstatus AS ks ON ks.matchname = k.type WHERE k.regno = v_sid AND kyctype = 2;
  END IF;
  IF (v_mode = 6) THEN
  RETURN QUERY SELECT CAST(TO_CHAR(doi, 'MM-DD-YYYY') AS VARCHAR(100)) AS doi, panno, entitytype, type FROM tbl_businesskycdetails WHERE plid = v_sid;
  END IF;
  IF (v_mode = 7) THEN
  RETURN QUERY SELECT * FROM bank_accounts_merchant WHERE active = 1 AND plid = v_sid;
  END IF;
  IF (v_mode = 8) THEN
  RETURN QUERY SELECT v_merchantkycimage || image AS img, * FROM kyc WHERE id = v_sid;
  END IF;
  IF (v_mode = 9) THEN
  IF (v_pincode = 'Director-Pancard-Details') THEN
  v_pincode := 'Pancard-Details';
  END IF;
  RETURN QUERY SELECT k.id AS singleid, v_merchantkycimage || image, (SELECT panno FROM tbl_businesskycdetails WHERE plid = v_sid AND type = v_pincode) AS pancard, * FROM kyc AS k WHERE k.regno = v_sid AND k.type = v_pincode;
  END IF;
  IF (v_mode = 10) THEN
  v_getsubcstid := '';
  v_pmid := 0;
  SELECT pmid INTO v_pmid FROM portal_login WHERE plid = v_sid;
  IF (v_pmid > 0) THEN
  SELECT subcatid INTO v_getsubcstid FROM portal_master WHERE pmid = v_pmid;
  IF (v_getsubcstid <> '') THEN
  v_query := 'select * from tbl_category  where catid in (' || v_getsubcstid || ')';
  EXECUTE v_query;
  END IF;
  END IF;
  END IF;
  IF (v_mode = 11) THEN
  RETURN QUERY SELECT ROW_NUMBER() OVER (ORDER BY lastupdate DESC NULLS LAST) AS number, tmid, ticketno, CAST(TO_CHAR(date, 'DD TMMon YYYY') AS VARCHAR(11)) AS createdate, categoryname, CAST(TO_CHAR(lastupdate, 'DD TMMon YYYY') AS VARCHAR(20)) AS lastupdatedate, subject, sm.name AS status, COALESCE(fromregno, 0) AS byadmin, v_merchantticketimage || tmimage AS image FROM tbl_ticketmaster AS tm INNER JOIN tbl_statusmaster AS sm ON sm.id = tm.status WHERE fromplid = v_sid AND accounttype = 1;
  END IF;
  IF (v_mode = 12) THEN
  RETURN QUERY SELECT trm.message, CAST(TO_CHAR(trm.date, 'TMMon DD YYYY FMHH12:MI%p') AS VARCHAR(30)) AS date, trm.trmid, trm.adminuser, (image) AS imageurl, (CASE WHEN fromtype = 2 THEN 'Me' ELSE 'Support' END) AS fromtype, v_merchantticketimage || tmimage AS image FROM tbl_ticketreply_merchant AS trm LEFT OUTER JOIN tbl_ticketmaster AS tm ON trm.tmid = tm.tmid WHERE tm.tmid = v_sid;
  END IF;
  IF (v_mode = 13) THEN
  RETURN QUERY SELECT ROW_NUMBER() OVER (ORDER BY lastupdate DESC NULLS LAST) AS number, tmid, ticketno, CAST(TO_CHAR(date, 'DD TMMon YYYY') AS VARCHAR(11)) AS createdate, categoryname, CAST(TO_CHAR(lastupdate, 'DD TMMon YYYY') AS VARCHAR(20)) AS lastupdatedate, subject, sm.name AS status, v_merchantticketimage || tmimage AS image FROM tbl_ticketmaster AS tm INNER JOIN tbl_statusmaster AS sm ON sm.id = tm.status WHERE tmid = v_sid AND accounttype = 1;
  END IF;
  IF (v_mode = 14) THEN
  SELECT COALESCE(pmid, 0) INTO v_pmid FROM portal_login WHERE plid = v_sid;
  RETURN QUERY SELECT COALESCE(COUNT(1), 0) AS countno FROM portal_master WHERE pmid = v_pmid;
  END IF;
  IF (v_mode = 15) THEN
  RETURN QUERY SELECT * FROM tbl_main_category WHERE status = 1 AND totalactive > 0;
  END IF;
  IF (v_mode = 16) THEN
  RETURN QUERY SELECT * FROM tbl_category WHERE status = 1 AND totalactive > 0 AND maincatid = v_sid;
  END IF;
END;
$$;


--
-- Name: usp_getstate_city_list_mobile_customer(bigint, bigint, character varying, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_getstate_city_list_mobile_customer(v_sid bigint DEFAULT 1, v_mode bigint DEFAULT 1, v_pincode character varying DEFAULT ''::character varying, v_did integer DEFAULT 0) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_geturl varchar(100);
  v_merchantkycimage varchar(100);
  v_merchantticketimage varchar(100);
  v_getsubcstid varchar(50);
  v_query text;
  v_pmid int;
BEGIN
  v_geturl := '';
  v_merchantkycimage := '';
  v_merchantticketimage := '';
  SELECT profileimagepath, kycimage, ticketimage INTO v_geturl, v_merchantkycimage, v_merchantticketimage FROM tbl_company;
  IF (v_mode = 1) THEN
  RETURN QUERY SELECT sid, cid, statename FROM state WHERE sid <> 0 AND sactive = 1 AND cid = 96;
  END IF;
  IF (v_mode = 2) THEN
  RETURN QUERY SELECT ctid, cid, sid, cityname FROM city WHERE sid = v_sid;
  END IF;
  IF (v_mode = 3) THEN
  RETURN QUERY SELECT * FROM area_master WHERE pincode = v_pincode;
  END IF;
  IF (v_mode = 4) THEN
  RETURN QUERY SELECT ksid, id AS entityid, name, icon, url, status, matchname FROM tbl_kycstatus WHERE id = v_sid AND status = 1;
  END IF;
  IF (v_mode = 5) THEN
  RETURN QUERY SELECT k.id AS singleid, v_merchantkycimage || image, * FROM tbl_customer_kyc AS k WHERE k.clid = v_sid AND kyctype = 2;
  END IF;
  IF (v_mode = 6) THEN
  RETURN QUERY SELECT CAST(TO_CHAR(doi, 'MM-DD-YYYY') AS VARCHAR(100)) AS doi, panno, entitytype, type FROM tbl_customerkycdetails WHERE clid = v_sid;
  END IF;
  IF (v_mode = 7) THEN
  RETURN QUERY SELECT * FROM bank_accounts_merchant WHERE active = 1 AND plid = v_sid;
  END IF;
  IF (v_mode = 8) THEN
  RETURN QUERY SELECT v_merchantkycimage || image AS img, * FROM tbl_customer_kyc WHERE id = v_sid;
  END IF;
  IF (v_mode = 9) THEN
  RETURN QUERY SELECT k.id AS singleid, v_merchantkycimage || image, * FROM tbl_customer_kyc AS k WHERE k.clid = v_sid AND k.type = v_pincode;
  END IF;
  IF (v_mode = 10) THEN
  v_getsubcstid := '';
  v_pmid := 0;
  SELECT pmid INTO v_pmid FROM portal_login WHERE plid = v_sid;
  IF (v_pmid > 0) THEN
  SELECT subcatid INTO v_getsubcstid FROM portal_master WHERE pmid = v_pmid;
  IF (v_getsubcstid <> '') THEN
  v_query := 'select * from tbl_category  where catid in (' || v_getsubcstid || ')';
  EXECUTE v_query;
  END IF;
  END IF;
  END IF;
  IF (v_mode = 11) THEN
  RETURN QUERY SELECT ROW_NUMBER() OVER (ORDER BY lastupdate DESC NULLS LAST) AS number, tmid, ticketno, CAST(TO_CHAR(date, 'DD TMMon YYYY') AS VARCHAR(11)) AS createdate, categoryname, CAST(TO_CHAR(lastupdate, 'DD TMMon YYYY') AS VARCHAR(20)) AS lastupdatedate, subject, sm.name AS status, COALESCE(fromregno, 0) AS byadmin, v_merchantticketimage || tmimage AS image FROM tbl_ticketmaster AS tm INNER JOIN tbl_statusmaster AS sm ON sm.id = tm.status WHERE fromplid = v_sid AND accounttype = 1;
  END IF;
  IF (v_mode = 12) THEN
  RETURN QUERY SELECT trm.message, CAST(TO_CHAR(trm.date, 'TMMon DD YYYY FMHH12:MI%p') AS VARCHAR(30)) AS date, trm.trmid, trm.adminuser, (image) AS imageurl, (CASE WHEN fromtype = 2 THEN 'Me' ELSE 'Support' END) AS fromtype, v_merchantticketimage || tmimage AS image FROM tbl_ticketreply_merchant AS trm LEFT OUTER JOIN tbl_ticketmaster AS tm ON trm.tmid = tm.tmid WHERE tm.tmid = v_sid;
  END IF;
  IF (v_mode = 13) THEN
  RETURN QUERY SELECT ROW_NUMBER() OVER (ORDER BY lastupdate DESC NULLS LAST) AS number, tmid, ticketno, CAST(TO_CHAR(date, 'DD TMMon YYYY') AS VARCHAR(11)) AS createdate, categoryname, CAST(TO_CHAR(lastupdate, 'DD TMMon YYYY') AS VARCHAR(20)) AS lastupdatedate, subject, sm.name AS status, v_merchantticketimage || tmimage AS image FROM tbl_ticketmaster AS tm INNER JOIN tbl_statusmaster AS sm ON sm.id = tm.status WHERE tmid = v_sid AND accounttype = 1;
  END IF;
  IF (v_mode = 14) THEN
  SELECT COALESCE(pmid, 0) INTO v_pmid FROM portal_login WHERE plid = v_sid;
  RETURN QUERY SELECT COALESCE(COUNT(1), 0) AS countno FROM portal_master WHERE pmid = v_pmid;
  END IF;
  IF (v_mode = 15) THEN
  RETURN QUERY SELECT * FROM tbl_main_category WHERE status = 1 AND totalactive > 0;
  END IF;
  IF (v_mode = 16) THEN
  RETURN QUERY SELECT * FROM tbl_category WHERE status = 1 AND totalactive > 0 AND maincatid = v_sid;
  END IF;
  IF (v_mode = 17) THEN
  DELETE FROM ims_customeraddress WHERE id = v_sid;
  END IF;
  IF (v_mode = 18) THEN
  UPDATE tbl_addtocart SET qty = CAST(v_pincode AS INT) WHERE tatcid = v_sid;
  END IF;
  IF (v_mode = 19) THEN
  IF NOT EXISTS(SELECT 1 FROM tbl_customerlogin WHERE phone = v_pincode AND did = v_did) THEN
  UPDATE tbl_customerlogin SET phone = v_pincode WHERE clid = v_sid AND did = v_did;
  UPDATE customer_login_temp SET phone = v_pincode, active = 0 WHERE phone = v_pincode AND did = v_did AND active = 1;
  END IF;
  END IF;
  IF (v_mode = 20) THEN
  IF NOT EXISTS(SELECT 1 FROM tbl_customerlogin WHERE emailid = v_pincode AND did = v_did) THEN
  UPDATE tbl_customerlogin SET emailid = v_pincode WHERE clid = v_sid AND did = v_did;
  UPDATE customer_login_temp SET emailid = v_pincode, active = 0 WHERE phone = v_pincode AND did = v_did AND active = 1;
  END IF;
  END IF;
  IF (v_mode = 21) THEN
  IF (v_sid = 0) THEN
  DELETE FROM tbl_addtocart WHERE sessionid = v_pincode;
  ELSE
  IF (v_sid > 0) THEN
  DELETE FROM tbl_addtocart WHERE clid = v_sid;
  END IF;
  END IF;
  END IF;
  IF (v_mode = 22) THEN
  DELETE FROM tbl_wishlist WHERE regno = v_sid;
  END IF;
END;
$$;


