CREATE FUNCTION dbo.usp_getsubscriptiondetails(v_regno integer DEFAULT 1, v_tasmid integer DEFAULT 0, v_plid integer DEFAULT 1) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
BEGIN
  RETURN QUERY SELECT CAST(tasm.puchasedate AS VARCHAR(19)) AS date, tasmid, pl.fname, COALESCE(pl.lname, '') AS lname, pl.username, tasm.regno, (pl.loginid) AS email, pl.phone, (CASE WHEN tasm.modename = ' ' THEN 'N/A' ELSE tasm.modename END) AS modename, (CASE WHEN tasm.bankname = '' THEN 'N/A' ELSE tasm.bankname END) AS bankname, (CASE WHEN tasm.branchname = '' THEN 'N/A' ELSE tasm.branchname END) AS branchname, (CASE WHEN tasm.referencedate = '' THEN 'N/A' ELSE tasm.referencedate END) AS referencedate, (CASE WHEN tasm.referencenumber = '' THEN 'N/A' ELSE tasm.referencenumber END) AS referencenumber, tasm.allpackagename, tasm.puchasedate, tasm.allpackageamount, tasm.totalpayableamount, tasm.commentorremark, COALESCE(tasm.processingfee, 0.00) AS processingfee, tasm.imagename AS imagename, (CASE WHEN tasm.isapproved = 1 THEN 'Cleared' ELSE 'Pending' END) AS status, allpackageid, CAST(service_tax AS DECIMAL(10, 2)) AS service_tax, CAST(with_out_tax_amount AS DECIMAL(10, 2)) AS with_out_tax_amount, invoice_no, CAST(service_tax_per AS DECIMAL(10, 2)) AS service_tax_per, transaction_id FROM tbl_allsubscriptionmaster AS tasm INNER JOIN portal_login AS pl ON tasm.regno = pl.plid WHERE tasmid = v_tasmid;
END;
$$;


