--
-- Name: usp_getsuggestkeyword(character varying, character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_getsuggestkeyword(v_datefrom character varying DEFAULT ''::character varying, v_dateto character varying DEFAULT ''::character varying) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_query text;
BEGIN
  v_query := '';
  v_query := 'select  ROW_NUMBER() over(order by ssk.suggest_keyword_no desc) as rownumber,ssk.suggest_keyword_no,ssk.keywordname,

ssk.suggesteddate,sl.slid,sl.loginid from tb_sposersuggestedkeyword ssk join sponsor_master_detail sl on ssk.slid=sl.slid where approvestatus=0';
  IF (v_datefrom <> '' AND v_dateto <> '') THEN
  v_query := v_query || ' and convert(date,ssk.suggesteddate) between ''' || CAST(v_datefrom AS VARCHAR(200)) || ''' and ''' || CAST(v_dateto AS VARCHAR(200)) || '''';
  ELSE
  IF (v_datefrom <> '') THEN
  v_query := v_query || ' and convert(date,ssk.suggesteddate) >= ''' || CAST(v_datefrom AS VARCHAR(200)) || '''';
  END IF;
  END IF;
  EXECUTE v_query;
END;
$$;


--
-- Name: usp_gettitleandcategory(bigint, integer, text, text, text, character varying, bigint); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_gettitleandcategory(v_pmid bigint DEFAULT 0, v_cid integer DEFAULT 0, v_titleinput text DEFAULT ''::text, INOUT v_titleoutput text DEFAULT ''::text, INOUT v_catnameoutput text DEFAULT ''::text, INOUT v_cityname character varying DEFAULT ''::character varying, INOUT v_pmidout bigint DEFAULT NULL::bigint) RETURNS record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_catid text;
  v_indexofcomma INT;
  v_autocatid text;
BEGIN
  v_titleinput := COALESCE(v_titleinput, '');
  IF (COALESCE(v_pmid, 0) = 0) THEN
  SELECT pmid INTO v_pmid FROM portal_master WHERE title = v_titleinput AND cid = v_cid;
  END IF;
  SELECT pm.catid, COALESCE(pm.autocatid, ''), pm.title, COALESCE(c.cityname, '') INTO v_catid, v_autocatid, v_titleoutput, v_cityname FROM portal_master AS pm LEFT JOIN city AS c ON pm.ctid = c.ctid WHERE pm.pmid = v_pmid;
  SELECT catid, COALESCE(autocatid, ''), title INTO v_catid, v_autocatid, v_titleoutput FROM portal_master WHERE pmid = v_pmid;
  DROP TABLE IF EXISTS tmp_tempfirst;
  CREATE TEMP TABLE tmp_tempfirst (ROWNUMBER INT GENERATED BY DEFAULT AS IDENTITY,

VALUE text) ON COMMIT DROP;
  IF (v_catid <> '') THEN
  INSERT INTO tmp_tempfirst SELECT * FROM dbo.SPLITSTRINGBYCOMMA(v_catid);
  END IF;
  SELECT COALESCE(RTRIM(LTRIM(COALESCE(catname, ''))), '') INTO v_catnameoutput FROM product_category WHERE catid = (SELECT value FROM tmp_tempfirst WHERE rownumber = 1);
  IF (v_catid = '' OR v_catid = '0' OR NOT EXISTS(SELECT COALESCE(RTRIM(LTRIM(COALESCE(catname, ''))), '') FROM product_category WHERE catid = (SELECT value FROM tmp_tempfirst WHERE rownumber = 1))) THEN
  v_indexofcomma := CAST(POSITION(',' IN v_autocatid) AS INT);
  IF (v_indexofcomma = 0) THEN
  v_catid := v_autocatid;
  ELSE
  v_catid := SUBSTRING(v_autocatid FROM 0 FOR v_indexofcomma);
  END IF;
  INSERT INTO tmp_tempfirst VALUES (v_catid);
  END IF;
  SELECT COALESCE(RTRIM(LTRIM(catname)), '') INTO v_catnameoutput FROM product_category WHERE catid = (SELECT value FROM tmp_tempfirst WHERE rownumber = 1);
  DROP TABLE IF EXISTS tmp_tempfirst;
  v_pmidout := v_pmid;
END;
$$;


--
-- Name: usp_gettitleandcategory_deal(bigint, integer, text); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_gettitleandcategory_deal(v_dealid bigint DEFAULT 0, v_cid integer DEFAULT 0, v_titleinput text DEFAULT NULL::text) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_catid text;
  v_indexofcomma int;
  v_autocatid text;
  v_titleoutput text;
  v_catnameoutput text;
  v_cityname varchar(100);
BEGIN
  v_titleinput := COALESCE(v_titleinput, '');
  IF (COALESCE(v_dealid, 0) = 0) THEN
  SELECT pdm.dealid INTO v_dealid FROM portal_deal_master AS pdm INNER JOIN portal_master AS pm ON pm.pmid = pdm.pmid WHERE pdm.title = v_titleinput AND pm.cid = v_cid;
  END IF;
  SELECT pm.catid, COALESCE(pm.autocatid, ''), pdm.title, COALESCE(c.cityname, '') INTO v_catid, v_autocatid, v_titleoutput, v_cityname FROM portal_master AS pm INNER JOIN portal_deal_master AS pdm ON pm.pmid = pdm.pmid LEFT JOIN city AS c ON pm.ctid = c.ctid WHERE pdm.dealid = v_dealid;
  SELECT pm.catid, COALESCE(pm.autocatid, ''), pdm.title INTO v_catid, v_autocatid, v_titleoutput FROM portal_master AS pm INNER JOIN portal_deal_master AS pdm ON pm.pmid = pdm.pmid WHERE pdm.dealid = v_dealid;
  v_catid := COALESCE(v_catid, '');
  v_autocatid := COALESCE(v_autocatid, '');
  DROP TABLE IF EXISTS tmp_tempfirst;
  CREATE TEMP TABLE tmp_tempfirst (rownumber int GENERATED BY DEFAULT AS IDENTITY,
Value text) ON COMMIT DROP;
  IF (v_catid <> '') THEN
  INSERT INTO tmp_tempfirst SELECT * FROM dbo.SPLITSTRINGBYCOMMA(v_catid);
  END IF;
  SELECT COALESCE(RTRIM(LTRIM(COALESCE(catname, ''))), '') INTO v_catnameoutput FROM product_category WHERE catid = (SELECT value FROM tmp_tempfirst WHERE rownumber = 1);
  IF (v_catid = '' OR v_catid = '0' OR NOT EXISTS(SELECT COALESCE(RTRIM(LTRIM(COALESCE(catname, ''))), '') FROM product_category WHERE catid = (SELECT value FROM tmp_tempfirst WHERE rownumber = 1))) THEN
  v_indexofcomma := CAST(POSITION(',' IN v_autocatid) AS INT);
  IF (v_indexofcomma = 0) THEN
  v_catid := v_autocatid;
  ELSE
  v_catid := SUBSTRING(v_autocatid FROM 0 FOR v_indexofcomma);
  END IF;
  INSERT INTO tmp_tempfirst VALUES (v_catid);
  END IF;
  SELECT COALESCE(RTRIM(LTRIM(catname)), '') INTO v_catnameoutput FROM product_category WHERE catid = (SELECT value FROM tmp_tempfirst WHERE rownumber = 1);
  DROP TABLE IF EXISTS tmp_tempfirst;
  RETURN QUERY SELECT v_titleoutput AS title, v_catnameoutput AS categoryname, v_cityname AS cityname, v_dealid AS dealid;
END;
$$;


--
-- Name: usp_gettitledesccanonblog(bigint, text); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_gettitledesccanonblog(v_id bigint, v_currenturl text) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_canonicalurl text;
BEGIN
  SELECT COALESCE(canonicalurl, '') INTO v_canonicalurl FROM tbl_blogmaster WHERE blogid = v_id;
  IF (v_canonicalurl = '') THEN
  UPDATE tbl_blogmaster SET canonicalurl = v_currenturl WHERE blogid = v_id;
  END IF;
  SELECT COALESCE(canonicalurl, '') INTO v_canonicalurl FROM tbl_blogmaster WHERE blogid = v_id;
  RETURN QUERY SELECT blogtitle, blogdescription, keywords, (UPPER(LEFT(CAST(blogwriter AS TEXT), 1)) || LOWER(SUBSTRING(blogwriter FROM 2 FOR LENGTH(CAST(blogwriter AS TEXT))))) AS blogwriter, CAST(TO_CHAR(blogcreationdate, 'DD TMMon YYYY') AS VARCHAR(13)) AS dd, v_canonicalurl AS canonurl, title, metadescription, metakeywords FROM tbl_blogmaster WHERE status = 1 AND publishstatus = 1 AND blogid = v_id;
END;
$$;


