--
-- Name: usp_getunapprovedbusinesslisting(integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_getunapprovedbusinesslisting(v_pmid integer) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_catid text;
  v_ctid text;
  v_totalcategory text;
  v_totalcity text;
BEGIN
  SELECT catid, ctid INTO v_catid, v_ctid FROM portal_master_temp WHERE pmtid = v_pmid;
  SELECT COALESCE(v_totalcategory || ', ', '') || catname INTO v_totalcategory FROM product_category WHERE catid IN (SELECT value FROM dbo.SPLITSTRINGBYCOMMA(v_catid));
  SELECT COALESCE(v_totalcity || ', ', '') || cityname INTO v_totalcity FROM city WHERE ctid IN (SELECT value FROM dbo.SPLITSTRINGBYCOMMA(v_ctid));
  RETURN QUERY SELECT pmt.pmtid, pmt.companyname, ('../CompanyImage/' || COALESCE(pmt.companyimage, '')) AS companyimage, CASE pmt.yearofestable WHEN 0 THEN 'N/A' ELSE CAST(pmt.yearofestable AS VARCHAR(30)) END AS yearofestable, COALESCE(pmt.url, 'N/A') AS url, pmt.request_date AS doc, (plt.title || ' ' || pmt.contactperson || ' ' || COALESCE(pmt.lname, '')) AS name, (plt.phone) AS cpermobileno, plt.loginid, plt.password, COALESCE(plt.designation, 'N/A') AS cperdesignation, COALESCE(s.statename, 'N/A') AS statename, COALESCE(c.countryname, 'N/A') AS countryname, COALESCE(ct.cityname, 'N/A') AS cityname, (pmt.areaname || '-' || pmt.pincode) AS areaname, COALESCE(pmt.address, 'N/A') AS building, COALESCE(pmt.lankmark, 'N/A') AS lankmark, COALESCE(plt.cper_emailid, 'N/A') AS comemailid, COALESCE(pmt.noofemployee, 'N/A') AS noofemployee, pmt.mobileno AS companymob, COALESCE(v_totalcategory, '-') AS totalcategory, COALESCE(v_totalcity, '-') AS totalcity FROM portal_master_temp AS pmt LEFT JOIN portal_login_temp AS plt ON pmt.pmtid = plt.pmtid LEFT JOIN state AS s ON pmt.sid = s.sid LEFT JOIN country AS c ON pmt.cid = c.cid LEFT JOIN city AS ct ON pmt.ctid = ct.ctid WHERE pmt.pmtid = v_pmid;
END;
$$;


--
-- Name: usp_getwalletcurrentbalance(character varying, character varying, integer, numeric, character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_getwalletcurrentbalance(v_loginid character varying, v_password character varying, v_cid integer, v_currentbalance numeric, v_strresult character varying) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_plid bigint;
  v_cidtemp int;
  v_currency varchar(10);
BEGIN
  -- BEGIN TRAN (removed)
  v_plid := 0;
  v_currentbalance := 0;
  SELECT plid, COALESCE(cid, 0), currencysymbol INTO v_plid, v_cidtemp, v_currency FROM portal_login WHERE loginid = v_loginid AND password = v_password;
  RETURN QUERY SELECT * FROM portal_login;
  IF (v_plid = 0) THEN
  v_strresult := 'error^Invalid Id or Password';
  -- COMMIT (removed)
  RETURN;
  END IF;
  IF (v_cidtemp <> v_cid) THEN
  v_strresult := 'error^Invalid Id or Password for current country';
  -- COMMIT (removed)
  RETURN;
  END IF;
  SELECT COALESCE(amount, 0) INTO v_currentbalance FROM ewallet WHERE plid = v_plid;
  v_strresult := 'success^' || CAST(v_currentbalance AS VARCHAR(20)) || '^' || v_currency;
  IF (0 <> 0) THEN
  v_strresult := 'error^some error occured';
  END IF;
  -- COMMIT (removed)
END;
$$;


