--
-- Name: usp_getworkinghours(bigint); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_getworkinghours(v_pmid bigint DEFAULT 1) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_opentime VARCHAR(25);
  v_closetime VARCHAR(25);
  v_openeveningtime VARCHAR(25);
  v_closeeveningtime VARCHAR(25);
  v_id BIGINT;
  v_opentimeint VARCHAR(10);
  v_closetimeint VARCHAR(10);
  v_openeveningtimeint VARCHAR(10);
  v_closeeveningtimeint VARCHAR(10);
  v_isclosed INT;
  v_rowcount INT;
  cr_opentime CURSOR FOR SELECT COALESCE(openingtime, ''), COALESCE(closingtime, ''), COALESCE(openingtimeevening, ''), COALESCE(closingtimeevening, ''), id FROM tblopeningdate WHERE pmid = v_pmid ORDER BY dayid ASC NULLS FIRST;
BEGIN
  -- BEGIN TRAN (removed)
  DROP TABLE IF EXISTS tmp_temp_workinghours;
  CREATE TEMP TABLE tmp_temp_workinghours (ID BIGINT,  
OPENTIME VARCHAR(10),  
CLOSETIME  VARCHAR(10),  
OPENTIMEEVENING VARCHAR(10),  
CLOSETIMEEVENING VARCHAR(10),  
ISCLOSED INT) ON COMMIT DROP;
  OPEN cr_opentime;
  FETCH cr_opentime INTO v_opentime, v_closetime,v_openeveningtime,v_closeeveningtime,v_id;
  WHILE (found) LOOP
  v_isclosed := 0;
  v_opentimeint := '0';
  v_closetimeint := '0';
  v_openeveningtimeint := '0';
  v_closeeveningtimeint := '0';
  IF (POSITION('AM' IN v_opentime) > 0 OR POSITION('PM' IN v_opentime) > 0) THEN
  v_opentimeint := RTRIM(LTRIM(CAST(EXTRACT(epoch FROM CAST(CAST(v_opentime AS TIMESTAMP) AS TIMESTAMP) - CAST(CAST('1900-01-01' AS TIMESTAMP) AS TIMESTAMP)) / 60 AS BIGINT)));
  END IF;
  IF (POSITION('AM' IN v_closetime) > 0 OR POSITION('PM' IN v_closetime) > 0) THEN
  v_closetimeint := RTRIM(LTRIM(CAST(EXTRACT(epoch FROM CAST(CAST(v_closetime AS TIMESTAMP) AS TIMESTAMP) - CAST(CAST('1900-01-01' AS TIMESTAMP) AS TIMESTAMP)) / 60 AS BIGINT)));
  END IF;
  IF (POSITION('AM' IN v_openeveningtime) > 0 OR POSITION('PM' IN v_openeveningtime) > 0) THEN
  v_openeveningtimeint := RTRIM(LTRIM(CAST(EXTRACT(epoch FROM CAST(CAST(v_openeveningtime AS TIMESTAMP) AS TIMESTAMP) - CAST(CAST('1900-01-01' AS TIMESTAMP) AS TIMESTAMP)) / 60 AS BIGINT)));
  END IF;
  IF (POSITION('AM' IN v_closeeveningtime) > 0 OR POSITION('PM' IN v_closeeveningtime) > 0) THEN
  v_closeeveningtimeint := RTRIM(LTRIM(CAST(EXTRACT(epoch FROM CAST(CAST(v_closeeveningtime AS TIMESTAMP) AS TIMESTAMP) - CAST(CAST('1900-01-01' AS TIMESTAMP) AS TIMESTAMP)) / 60 AS BIGINT)));
  END IF;
  IF (v_opentimeint = '0' AND v_closetimeint = '0') THEN
  v_isclosed := 1;
  END IF;
  INSERT INTO tmp_temp_workinghours VALUES (v_id, v_opentimeint, v_closetimeint, v_openeveningtimeint, v_closeeveningtimeint, v_isclosed);
  IF (0 < 0) THEN
  CLOSE cr_opentime;
  -- DEALLOCATE (removed)
  DROP TABLE IF EXISTS tmp_temp_workinghours;
  -- ROLLBACK (removed)
  -- COMMIT (removed)
  END IF;
  FETCH cr_opentime INTO v_opentime, v_closetime,v_openeveningtime,v_closeeveningtime,v_id;
  END LOOP;
  CLOSE cr_opentime;
  -- DEALLOCATE (removed)
  SELECT COUNT(id) INTO v_rowcount FROM tmp_temp_workinghours;
  WHILE (v_rowcount < 7) LOOP
  v_rowcount := v_rowcount + 1;
  INSERT INTO tmp_temp_workinghours VALUES (v_rowcount, 0, 0, 0, 0, 1);
  END LOOP;
  RETURN QUERY SELECT * FROM tmp_temp_workinghours;
  -- COMMIT (removed)
END;
$$;


