    LANGUAGE plpgsql
    AS $$
BEGIN
  IF EXISTS(SELECT 1 FROM distributor_master WHERE pmid = v_pmid) THEN
  IF NOT EXISTS(SELECT 1 FROM tbl_companysettings WHERE pmid = v_pmid) THEN
