  v_result := 'Insert';
  ELSE
  UPDATE tbl_companysettings SET companyoauthurl = v_companyauthourl, companyvalidurl = v_companyvalidurl, companyclientid = v_companyclientid, companyscope = v_companyscope, companylogout = v_companylogout, companyredirect = v_companyredirect WHERE pmid = v_pmid;
