  END IF;
  ELSE
  v_result := 'Invalid Distributor';
  END IF;
END;
$$;


--
-- Name: usp_holiday_management(integer, text, integer, integer, integer, character varying, integer, integer, character varying, date, text, character varying, character varying, character varying, integer, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_holiday_management(v_mode integer DEFAULT 0, v_sliceforholiday text DEFAULT ''::text, v_brid integer DEFAULT 0, v_userid integer DEFAULT 0, v_hldid integer DEFAULT 0, v_holidaydata character varying DEFAULT ''::character varying, v_holidayid integer DEFAULT 0, v_holidaygroupid integer DEFAULT 0, v_holidayname character varying DEFAULT ''::character varying, v_holidaydate date DEFAULT NULL::date, v_description text DEFAULT ''::text, v_shiftgroupname character varying DEFAULT ''::character varying, v_shiftgroupcode character varying DEFAULT ''::character varying, v_allids character varying DEFAULT ''::character varying, v_intresult integer DEFAULT 0, v_recordcount integer DEFAULT 0) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
BEGIN
  -- SET option (removed)
  IF (v_mode = 1) THEN
  IF (v_holidayid = 0) THEN
  IF NOT EXISTS(SELECT 1 FROM tbl_add_holiday WHERE CAST(TO_CHAR(holidaydate, 'DD TMMon YYYY') AS VARCHAR(11)) = CAST(TO_CHAR(v_holidaydate, 'DD TMMon YYYY') AS VARCHAR(11)) AND status = 1 AND holidayname = v_holidayname) THEN
  RETURN QUERY SELECT CAST(TO_CHAR(v_holidaydate, 'DD TMMon YYYY') AS VARCHAR(11)) AS hldate;
  INSERT INTO tbl_add_holiday (holidayname, holidaydate, description, createddate, status, createdby) VALUES (v_holidayname, CAST(v_holidaydate AS DATE), v_description, CURRENT_TIMESTAMP, 1, 1);
  v_intresult := 1;
  ELSE
  v_intresult := 3;
  END IF;
  ELSE
  IF EXISTS(SELECT 1 FROM tbl_add_holiday WHERE holidaydate = v_holidaydate AND status = 1 AND holidayid = v_holidayid) THEN
  UPDATE tbl_add_holiday SET holidayname = v_holidayname, holidaydate = v_holidaydate, description = v_description, updatedby = 1, updateddate = CURRENT_TIMESTAMP WHERE holidayid = v_holidayid;
  v_intresult := 2;
  ELSE
  v_intresult := 3;
  END IF;
  END IF;
  END IF;
  IF (v_mode = 2) THEN
  RETURN QUERY SELECT holidayid, ROW_NUMBER() OVER (ORDER BY createddate ASC NULLS FIRST) AS number, holidayname, (CASE WHEN holidaydate = '1900-01-01' THEN 'N/A' ELSE CAST(TO_CHAR(holidaydate, 'MM/DD/YYYY') AS VARCHAR(11)) END) AS holidaydate, (CASE WHEN LENGTH(CAST(description AS TEXT)) > 12 THEN LEFT(CAST(description AS TEXT), 12) || '...' ELSE description END) AS description, (description) AS tooltipdescription FROM tbl_add_holiday WHERE status = 1;
  END IF;
  -- SET option (removed)
  IF (0 <> 0) THEN
  v_intresult := 0;
  RETURN;
  END IF;
END;
$$;


