--
-- Name: usp_ins_portal_deal_master(character varying, character varying, text, integer, integer, character varying, character varying, text, text, bigint, text, character varying, character varying, integer, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_ins_portal_deal_master(v_title character varying DEFAULT ''::character varying, v_offer character varying DEFAULT ''::character varying, v_desc text DEFAULT ''::text, v_discount integer DEFAULT 0, v_startprice integer DEFAULT 0, v_dealfrom character varying DEFAULT ''::character varying, v_dealto character varying DEFAULT ''::character varying, v_terms text DEFAULT ''::text, v_highlight text DEFAULT ''::text, v_pmid bigint DEFAULT 0, v_images text DEFAULT ''::text, INOUT v_currdealid character varying DEFAULT ''::character varying, INOUT v_strresult character varying DEFAULT ''::character varying, v_mode integer DEFAULT 1, v_dealid integer DEFAULT 0) RETURNS record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_portalmasterid int;
  v_newoptid INT;
BEGIN
  v_portalmasterid := 0;
  SELECT pmid INTO v_portalmasterid FROM portal_master WHERE plid = v_pmid;
  IF (v_mode = 1) THEN
  -- BEGIN TRAN (removed)
  v_newoptid := 0;
  v_strresult := 'OK';
  v_dealfrom := CAST(CAST(v_dealfrom AS DATE) AS VARCHAR(500)) || ' 00:00:00.000';
  v_dealto := CAST(CAST(v_dealto AS DATE) AS VARCHAR(500)) || ' 23:59:59.999';
  INSERT INTO portal_deal_master (pmid, title, offer, description, discount, startprice, fromtime, totime, terms, highlights, createdate, verify, active, images) VALUES (v_portalmasterid, v_title, v_offer, v_desc, v_discount, v_startprice, v_dealfrom, v_dealto, v_terms, v_highlight, dbo.FUN_GETCURRENTDATE(), 0, 0, v_images);
  v_currdealid := IDENT_CURRENT('PORTAL_DEAL_MASTER');
  SELECT optid INTO v_newoptid FROM tbl_operator_master WHERE LOWER(usertype) = LOWER('Eblaa QA') AND COALESCE(lastdealstatus, 0) = 0 AND status = 1 AND isactiveforq = 1;
  IF (v_newoptid = 0) THEN
  UPDATE tbl_operator_master SET lastdealstatus = 0;
  SELECT optid INTO v_newoptid FROM tbl_operator_master WHERE LOWER(usertype) = LOWER('Eblaa QA') AND COALESCE(lastdealstatus, 0) = 0 AND status = 1 AND isactiveforq = 1;
  END IF;
  INSERT INTO tbl_dealswithqa (dealid, optid, date, status) VALUES (v_currdealid, v_newoptid, dbo.FUN_GETCURRENTDATE(), 0);
  UPDATE tbl_operator_master SET lastdealstatus = 1 WHERE optid = v_newoptid AND LOWER(usertype) = LOWER('Eblaa QA');
  IF (0 <> 0) THEN
  -- ROLLBACK (removed)
  v_strresult := 'Some Error Occured.!!!';
  RETURN;
  END IF;
  -- COMMIT (removed)
  END IF;
  IF (v_mode = 2) THEN
  UPDATE portal_deal_master SET title = v_title, offer = v_offer, description = v_desc, discount = v_discount, startprice = v_startprice, fromtime = v_dealfrom, totime = v_dealto, terms = v_terms, highlights = v_highlight, images = (CASE WHEN v_images = '' THEN images ELSE v_images END) WHERE dealid = v_dealid;
  v_strresult := 'Deal Updated Successfully !';
  END IF;
END;
$$;


