--
-- Name: usp_insert_alltypecategory_new(integer, text, character varying, text, integer, text, integer, integer, text, numeric, integer, numeric, numeric, integer, integer, integer, integer, integer, text, numeric, numeric, numeric, numeric); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_insert_alltypecategory_new(v_id integer DEFAULT 0, v_value text DEFAULT ''::text, v_type character varying DEFAULT 'SUBCATEGORY'::character varying, INOUT v_varresult text DEFAULT ''::text, INOUT v_intresult integer DEFAULT 0, v_imagename text DEFAULT ''::text, v_imagesequence integer DEFAULT 0, v_hotlink integer DEFAULT 0, v_catimgnamemobile text DEFAULT ''::text, v_admincharge numeric DEFAULT 0, v_delieverycharge integer DEFAULT 0, v_handlingcharge numeric DEFAULT 0, v_fixedfee numeric DEFAULT 0, v_gst integer DEFAULT 0, v_isreturn integer DEFAULT 1, v_isrefund integer DEFAULT 1, v_isexchange integer DEFAULT 0, v_days integer DEFAULT 0, v_remarks text DEFAULT ''::text, v_businessvolume numeric DEFAULT 0, v_redeemcashback numeric DEFAULT 0, v_receivablecashback numeric DEFAULT 0, v_activationpointvalue numeric DEFAULT 0) RETURNS record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_maincatid INT;
  v_count1 INT;
  v_count2 INT;
  v_singleval VARCHAR(200);
  v_maxid INT;
  v_sequence INT;
  v_maincount INT;
  v_catcount INT;
  v_subcatcount INT;
  v_totalcount INT;
BEGIN
  -- BEGIN TRAN (removed)
  v_intresult := 0;
  DROP TABLE IF EXISTS tmp_temptable;
  CREATE TEMP TABLE tmp_temptable (ROWNO INT GENERATED BY DEFAULT AS IDENTITY,          
SINGLEVALUE text) ON COMMIT DROP;
  INSERT INTO tmp_temptable SELECT value FROM dbo.SPLITSTRINGBYCUSTOMSYMBOLSHOPING(v_value, '~');
  v_varresult := 'Invalid attempt';
  v_count1 := 1;
  SELECT COUNT(1) INTO v_count2 FROM tmp_temptable;
  IF (v_count2 > 0) THEN
  v_varresult := 'ok^';
  END IF;
  WHILE (v_count1 <= v_count2) LOOP
  SELECT singlevalue INTO v_singleval FROM tmp_temptable WHERE rowno = v_count1;
  SELECT COUNT(1) INTO v_maincount FROM tbl_main_category WHERE maincatname = v_singleval AND isdelete = 0;
  SELECT COUNT(1) INTO v_catcount FROM tbl_category WHERE catname = v_singleval AND isdelete = 0 AND maincatid = v_id;
  SELECT COUNT(1) INTO v_subcatcount FROM tbl_sub_category WHERE subcatname = v_singleval AND isdelete = 0 AND catid = v_id AND maincatid = v_id;
  v_totalcount := v_maincount + v_catcount + v_subcatcount;
  IF (v_totalcount > 0) THEN
  v_varresult := v_varresult || ('|0|0~');
  END IF;
  IF (v_type = 'MAINCATEGORY' AND v_totalcount = 0) THEN
  IF (v_imagesequence <> 0) THEN
  v_sequence := v_imagesequence;
  END IF;
  SELECT COALESCE(MAX(sequence), 0) + 1 INTO v_sequence FROM tbl_main_category;
  INSERT INTO tbl_main_category (maincatname, main_cat_code, status, sequence, category_icon, ishot_links, main_cat_imgname, categoryrelatedto) VALUES (v_singleval, dbo.REMOVESPACESANDSPECIALCHARS(v_singleval), 1, v_sequence, v_imagename, v_hotlink, v_catimgnamemobile, v_imagesequence);
  SELECT COALESCE(MAX(maincatid), 0) INTO v_maxid FROM tbl_main_category;
  v_varresult := v_varresult || (v_singleval || '|' || CAST(v_maxid AS VARCHAR(50)) || '|1~');
  UPDATE tbl_main_category SET main_cat_code = main_cat_code || '-' || CAST(v_maxid AS VARCHAR(200)), categoryrelatedto = v_imagesequence WHERE maincatid = v_maxid;
  v_intresult := 1;
  END IF;
  IF (v_type = 'CATEGORY' AND v_totalcount = 0) THEN
