CREATE FUNCTION dbo.usp_insert_alltypecategory_new_bak_11092018(v_id integer DEFAULT 0, v_value text DEFAULT 'Health'::text, v_type character varying DEFAULT 'MAINCATEGORY'::character varying, INOUT v_varresult text DEFAULT ''::text, INOUT v_intresult integer DEFAULT 0, v_imagename text DEFAULT ''::text, v_imagesequence integer DEFAULT 0, v_hotlink integer DEFAULT 0, v_admincharge numeric DEFAULT 0, v_delieverycharge integer DEFAULT 0, v_handlingcharge numeric DEFAULT 0, v_fixedfee numeric DEFAULT 0, v_gst integer DEFAULT 0) RETURNS record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_maincatid INT;
  v_count1 INT;
  v_count2 INT;
  v_singleval VARCHAR(200);
  v_maxid INT;
  v_sequence INT;
  v_maincount INT;
  v_catcount INT;
  v_subcatcount INT;
  v_totalcount INT;
BEGIN
  -- BEGIN TRAN (removed)
  v_intresult := 0;
  DROP TABLE IF EXISTS tmp_temptable;
  CREATE TEMP TABLE tmp_temptable (ROWNO INT GENERATED BY DEFAULT AS IDENTITY,
SINGLEVALUE text) ON COMMIT DROP;
  INSERT INTO tmp_temptable SELECT value FROM dbo.SPLITSTRINGBYCUSTOMSYMBOLSHOPING(v_value, '~');
  v_varresult := 'Invalid attempt';
  v_count1 := 1;
  SELECT COUNT(1) INTO v_count2 FROM tmp_temptable;
  IF (v_count2 > 0) THEN
  v_varresult := 'ok^';
  END IF;
  WHILE (v_count1 <= v_count2) LOOP
  SELECT singlevalue INTO v_singleval FROM tmp_temptable WHERE rowno = v_count1;
  SELECT COUNT(1) INTO v_maincount FROM tbl_main_category WHERE maincatname = v_singleval AND isdelete = 0;
  SELECT COUNT(1) INTO v_catcount FROM tbl_category WHERE catname = v_singleval AND isdelete = 0 AND maincatid = v_id;
  SELECT COUNT(1) INTO v_subcatcount FROM tbl_sub_category WHERE subcatname = v_singleval AND isdelete = 0 AND catid = v_id AND maincatid = v_id;
  v_totalcount := v_maincount + v_catcount + v_subcatcount;
  IF (v_totalcount > 0) THEN
  v_varresult := v_varresult || ('|0|0~');
  END IF;
  IF (v_type = 'MAINCATEGORY' AND v_totalcount = 0) THEN
  IF (v_imagesequence <> 0) THEN
  v_sequence := v_imagesequence;
  END IF;
  SELECT COALESCE(MAX(sequence), 0) + 1 INTO v_sequence FROM tbl_main_category;
  INSERT INTO tbl_main_category (maincatname, main_cat_code, status, sequence, imagename, ishot_links) VALUES (v_singleval, dbo.REMOVESPACESANDSPECIALCHARS(v_singleval), 1, v_sequence, v_imagename, v_hotlink);
  SELECT COALESCE(MAX(maincatid), 0) INTO v_maxid FROM tbl_main_category;
  v_varresult := v_varresult || (v_singleval || '|' || CAST(v_maxid AS VARCHAR(50)) || '|1~');
  UPDATE tbl_main_category SET main_cat_code = main_cat_code || '-' || CAST(v_maxid AS VARCHAR(200)) WHERE maincatid = v_maxid;
  v_intresult := 1;
  END IF;
  IF (v_type = 'CATEGORY' AND v_totalcount = 0) THEN
  SELECT COALESCE(MAX(sequence), 0) + 1 INTO v_sequence FROM tbl_category WHERE maincatid = v_id;
  INSERT INTO tbl_category (maincatid, catname, cat_code, status, sequence, admincharge, delieverycharge, handlingcharge, fixedfee) VALUES (v_id, v_singleval, dbo.REMOVESPACESANDSPECIALCHARS(v_singleval), 1, v_sequence, v_admincharge, v_delieverycharge, v_handlingcharge, v_fixedfee);
  SELECT COALESCE(MAX(catid), 0) INTO v_maxid FROM tbl_category;
  v_varresult := v_varresult || (v_singleval || '|' || CAST(v_maxid AS VARCHAR(50)) || '|1~');
  UPDATE tbl_category SET cat_code = cat_code || '-' || CAST(v_maxid AS VARCHAR(200)) WHERE catid = v_maxid;
  v_intresult := 1;
  END IF;
  IF (v_type = 'SUBCATEGORY' AND v_totalcount = 0) THEN
  SELECT COALESCE(MAX(sequence), 0) + 1 INTO v_sequence FROM tbl_sub_category WHERE catid = v_id;
  SELECT COALESCE((maincatid), 0), COALESCE(admincharge, 0), COALESCE(delieverycharge, 0), COALESCE(handlingcharge, 0), COALESCE(fixedfee, 0) INTO v_maincatid, v_admincharge, v_delieverycharge, v_handlingcharge, v_fixedfee FROM tbl_category WHERE catid = v_id;
  INSERT INTO tbl_sub_category (catid, maincatid, subcatname, sub_cat_code, status, sequence, admincharge, delieverycharge, handlingcharge, fixedfee, gstgroup) VALUES (v_id, v_maincatid, v_singleval, dbo.REMOVESPACESANDSPECIALCHARS(v_singleval), 1, v_sequence, v_admincharge, v_delieverycharge, v_handlingcharge, v_fixedfee, v_gst);
  SELECT COALESCE(MAX(subcatid), 0) INTO v_maxid FROM tbl_sub_category;
  v_varresult := v_varresult || (v_singleval || '|' || CAST(v_maxid AS VARCHAR(50)) || '|1~');
  UPDATE tbl_sub_category SET sub_cat_code = sub_cat_code || '-' || CAST(v_maxid AS VARCHAR(200)) WHERE subcatid = v_maxid;
  v_intresult := 1;
  END IF;
  v_count1 := v_count1 + 1;
  END LOOP;
  DROP TABLE IF EXISTS tmp_temptable;
  IF (0 <> 0) THEN
  v_intresult := 0;
  -- ROLLBACK (removed)
  RETURN;
  END IF;
  -- COMMIT (removed)
END;
$$;


