CREATE FUNCTION dbo.usp_insert_category_content_master(v_tccmid integer DEFAULT 0, v_catid integer DEFAULT 0, v_description text DEFAULT ' '::text, v_heading text DEFAULT ''::text, v_seotitle text DEFAULT ''::text, v_seokeyword text DEFAULT ''::text, v_seodescription text DEFAULT ''::text, v_isactive integer DEFAULT 0, INOUT v_intresult integer DEFAULT 0, v_mode integer DEFAULT 4, v_subcatid integer DEFAULT 0, v_kmid integer DEFAULT 0, v_startrowindex integer DEFAULT 1, v_maxrows integer DEFAULT 100, v_fromdate character varying DEFAULT ''::character varying, v_todate character varying DEFAULT ''::character varying, v_searchcategory text DEFAULT ''::text) RETURNS integer
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_minindex INT;
  v_maxindex INT;
  v_query text;
  v_condition text;
  v_countquery text;
  v_recordcount INT;
  v_parmdefinition varchar(70);
BEGIN
  -- SET option (removed)
  v_intresult := 0;
  IF (v_mode = 0) THEN
  IF EXISTS(SELECT 1 FROM tbl_category_content_master WHERE catid = v_catid AND tccmid <> v_tccmid) THEN
  v_intresult := 4;
  RAISE NOTICE '%', v_intresult;
  RETURN;
  END IF;
  IF NOT EXISTS(SELECT 1 FROM tbl_category_content_master WHERE catid = v_catid) THEN
  INSERT INTO tbl_category_content_master (catid, description, heading, seotitle, seokeyword, seodescription, isactive, lastmodified) VALUES (v_catid, v_description, v_heading, v_seotitle, v_seokeyword, v_seodescription, v_isactive, CURRENT_TIMESTAMP);
  v_intresult := 1;
  RAISE NOTICE '%', v_intresult;
  ELSE
  UPDATE tbl_category_content_master SET description = v_description, heading = v_heading, seotitle = v_seotitle, seokeyword = v_seokeyword, seodescription = v_seodescription, isactive = v_isactive WHERE catid = v_catid;
  v_intresult := 2;
  END IF;
  END IF;
  IF (v_mode = 1) THEN
  IF NOT EXISTS(SELECT 1 FROM tbl_e_com_category_content_master WHERE catid = v_catid) THEN
  INSERT INTO tbl_e_com_category_content_master (catid, description, heading, seotitle, seokeyword, seodescription, isactive, lastmodified) VALUES (v_catid, v_description, v_heading, v_seotitle, v_seokeyword, v_seodescription, v_isactive, CURRENT_TIMESTAMP);
  ELSE
  UPDATE tbl_e_com_category_content_master SET description = v_description, heading = v_heading, seotitle = v_seotitle, seokeyword = v_seokeyword, seodescription = v_seodescription, isactive = v_isactive WHERE catid = v_catid;
  END IF;
  v_intresult := 1;
  END IF;
  IF (v_mode = 2) THEN
  IF NOT EXISTS(SELECT 1 FROM tbl_e_com_sub_category_content_master WHERE catid = v_catid AND subcatid = v_subcatid) THEN
  INSERT INTO tbl_e_com_sub_category_content_master (catid, subcatid, description, heading, seotitle, seokeyword, seodescription, isactive, lastmodified) VALUES (v_catid, v_subcatid, v_description, v_heading, v_seotitle, v_seokeyword, v_seodescription, v_isactive, CURRENT_TIMESTAMP);
  ELSE
  UPDATE tbl_e_com_sub_category_content_master SET description = v_description, heading = v_heading, seotitle = v_seotitle, seokeyword = v_seokeyword, seodescription = v_seodescription, isactive = v_isactive WHERE catid = v_catid AND subcatid = v_subcatid;
  END IF;
  v_intresult := 1;
  END IF;
  IF (v_mode = 3) THEN
  IF NOT EXISTS(SELECT 1 FROM tbl_e_com_keyword_content_master WHERE catid = v_catid AND subcatid = v_subcatid AND kmid = v_kmid) THEN
  INSERT INTO tbl_e_com_keyword_content_master (catid, subcatid, kmid, description, heading, seotitle, seokeyword, seodescription, isactive, lastmodified) VALUES (v_catid, v_subcatid, v_kmid, v_description, v_heading, v_seotitle, v_seokeyword, v_seodescription, v_isactive, CURRENT_TIMESTAMP);
  ELSE
  UPDATE tbl_e_com_keyword_content_master SET description = v_description, heading = v_heading, seotitle = v_seotitle, seokeyword = v_seokeyword, seodescription = v_seodescription, isactive = v_isactive WHERE catid = v_catid AND subcatid = v_subcatid AND kmid = v_kmid;
  END IF;
  v_intresult := 1;
  END IF;
  IF (v_mode = 4) THEN
  v_query := '';
  v_condition := '';
  v_countquery := '';
  v_minindex := (v_startrowindex - 1) * v_maxrows + 1;
  v_maxindex := v_startrowindex * v_maxrows;
  v_query := 'SELECT ROW_NUMBER() OVER(ORDER BY CCM.TCCMID) AS ROWNUMBER,CCM.TCCMID,CCM.CATID,TMC.MainCatName,CCM.DESCRIPTION,
(CASE CCM.ISACTIVE WHEN 1 THEN ''Active'' ELSE ''Inactive'' END) AS ACTIVE,CCM.STATUS,CCM.LASTMODIFIED,CCM.Heading,CCM.SeoTitle,CCM.SeoKeyword,CCM.SeoDescription
INTO #TEMP13 FROM TBL_CATEGORY_CONTENT_MASTER CCM LEFT JOIN tbl_Main_Category TMC ON CCM.CATID=TMC.MAINCATID where 1=1';
  IF (v_searchcategory <> '') THEN
  v_searchcategory := REPLACE(v_searchcategory, '''', '''''');
  v_query := v_query || ('AND TMC.MainCatName=''' || v_searchcategory || '''');
  END IF;
  IF ((v_fromdate <> '') AND (v_todate = '')) THEN
  v_query := v_query || ' AND CONVERT(DATE, CCM.LASTMODIFIED, 105) BETWEEN  CONVERT(DATE, ''' || v_fromdate || ''', 105) AND  CONVERT(DATE, DBO.FUN_GETCURRENTDATE(), 105)';
  END IF;
  IF ((v_fromdate = '') AND (v_todate <> '')) THEN
  v_query := v_query || 'AND CONVERT(DATE, CCM.LASTMODIFIED, 105) BETWEEN  CONVERT(DATE, ''' || v_todate || ''', 105) AND  CONVERT(DATE, DBO.FUN_GETCURRENTDATE(), 105)';
  END IF;
  IF ((v_fromdate <> '') AND (v_todate <> '')) THEN
  v_query := v_query || 'AND CONVERT(DATE, CCM.LASTMODIFIED, 105) BETWEEN CONVERT(DATE, ''' || v_fromdate || ''', 105) AND  CONVERT(DATE, ''' || v_todate || ''', 105)';
  END IF;
  v_parmdefinition := N'@INTRESULT NVARCHAR(70) OUTPUT';
  v_countquery := N'SELECT @INTRESULT= COUNT(1)FROM TBL_CATEGORY_CONTENT_MASTER CCM where 1=1';
  v_query := v_query || v_condition || ' ;SELECT  *  FROM #TEMP13 WHERE ROWNUMBER BETWEEN ' || CAST(v_minindex AS VARCHAR(70)) || ' AND ' || CAST(v_maxindex AS VARCHAR(70)) || '';
  v_countquery := v_countquery || v_condition;
  RAISE NOTICE '%', v_query;
  EXECUTE v_query;
  EXECUTE v_countquery;
  END IF;
  -- SET option (removed)
END;
$$;


