CREATE FUNCTION dbo.usp_insert_member_master(v_maxplid integer DEFAULT 1030, v_intromemid character varying DEFAULT '79853847'::character varying, v_placementmemid character varying DEFAULT '79853847'::character varying, v_placementregnoside smallint DEFAULT 3, v_username character varying DEFAULT 'Ashish'::character varying, v_fname character varying DEFAULT ''::character varying, v_mname character varying DEFAULT ''::character varying, v_lname character varying DEFAULT ''::character varying, v_gender smallint DEFAULT 0, v_dob character varying DEFAULT ''::character varying, v_email character varying DEFAULT 'monikajuneja@awapal.com'::character varying, v_mobile character varying DEFAULT '9582105254'::character varying, v_sid integer DEFAULT 0, v_statename character varying DEFAULT ''::character varying, v_ctid integer DEFAULT 0, v_cityname character varying DEFAULT ''::character varying, v_cid integer DEFAULT 96, v_address character varying DEFAULT ''::character varying, v_pincode character varying DEFAULT ''::character varying, v_panno character varying DEFAULT ''::character varying, v_password character varying DEFAULT 'User@123'::character varying, v_trpassword character varying DEFAULT 'User@123'::character varying, v_ipadd character varying DEFAULT ''::character varying, v_epinnumber character varying DEFAULT ''::character varying, v_nomineename character varying DEFAULT ''::character varying, v_nomineerelation character varying DEFAULT ''::character varying, v_sessionloginid character varying DEFAULT ''::character varying, v_kitid integer DEFAULT 0, v_strresult character varying DEFAULT ''::character varying, v_application_formno character varying DEFAULT ''::character varying, v_loginid character varying DEFAULT '46397136'::character varying, v_userid character varying DEFAULT '46397136'::character varying, v_atc_walletaddress character varying DEFAULT ''::character varying, v_atcuserid character varying DEFAULT ''::character varying) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_lower INT;
  v_upper INT;
  v_random INT;
  v_parentregno BIGINT;
  v_introregno BIGINT;
  v_placementregno BIGINT;
  v_kid INT;
  v_kitprice numeric(19,4);
  v_status INT;
  v_active INT;
  v_statusp INT;
  v_activep INT;
  v_year text;
  v_month text;
  v_day text;
  v_uniquenumber text;
  v_eightdigitsequenceno BigInt;
  v_referralincome Decimal(10,2);
  v_old_bal Decimal(10,2);
  v_parent_regno INT;
  v_balance Decimal(10,2);
  v_sponserloginid text;
  v_strresult2 text;
BEGIN
  -- BEGIN TRAN (removed)
  -- SET option (removed)
  IF (v_intromemid <> '') THEN
  SELECT loginid INTO v_intromemid FROM member_master WHERE plid IN (SELECT plid FROM portal_login WHERE username = v_intromemid);
  END IF;
  v_strresult := 'ok^0';
  v_introregno := 0;
  v_status := 0;
  v_active := 0;
  v_placementregno := 0;
  IF (v_intromemid <> '') THEN
  SELECT regno INTO v_introregno FROM member_master WHERE loginid = v_intromemid;
  SELECT regno INTO v_placementregno FROM member_master WHERE loginid = v_placementmemid;
  ELSE
  v_intromemid := 0;
  v_placementmemid := 0;
  END IF;
  IF (v_mobile = '') THEN
  v_strresult := 'Error^Mobile no can not be empty.';
  -- COMMIT (removed)
  RETURN;
  END IF;
  IF (v_username = '') THEN
  v_strresult := 'Error^User name can not be empty.';
  -- COMMIT (removed)
  RETURN;
  END IF;
  IF (v_password = '') THEN
  v_strresult := 'Error^Password can not be empty.';
  -- COMMIT (removed)
  RETURN;
  END IF;
  IF EXISTS(SELECT 1 FROM member_master WHERE loginid = v_loginid) THEN
  v_strresult := 'Error^Member already exists on the behlf of user name.';
  -- COMMIT (removed)
  RETURN;
  END IF;
  IF (v_dob = '') THEN
  v_dob := NULL;
  END IF;
  v_ctid := 0;
  SELECT statename INTO v_statename FROM state WHERE sid = v_sid;
  v_year := '';
  v_month := '';
  v_day := '';
  v_uniquenumber := '';
  v_eightdigitsequenceno := 0;
  SELECT COALESCE(RIGHT(CAST(member_unique_id AS TEXT), 8), 10000000) INTO v_eightdigitsequenceno FROM member_master WHERE regno = (SELECT MAX(regno) FROM member_master);
  v_eightdigitsequenceno := v_eightdigitsequenceno + 1;
  SELECT EXTRACT(YEAR FROM CAST(CURRENT_TIMESTAMP AS DATE)) INTO v_year;
  SELECT CASE WHEN LENGTH(CAST(EXTRACT(MONTH FROM CAST(CURRENT_TIMESTAMP AS DATE)) AS TEXT)) < 2 THEN '0' || CAST(EXTRACT(MONTH FROM CAST(CURRENT_TIMESTAMP AS DATE)) AS text) ELSE CAST(EXTRACT(MONTH FROM CAST(CURRENT_TIMESTAMP AS DATE)) AS text) END INTO v_month;
