CREATE FUNCTION dbo.usp_insert_update_delete_tbl_keyword_in_sponsorad(v_smcid integer DEFAULT 0, v_keywordid integer DEFAULT 0, v_key_sp_id integer DEFAULT 0, v_plid integer DEFAULT 0, v_catid integer DEFAULT 0, INOUT v_intresult integer DEFAULT 0) RETURNS integer
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_err int;
  v_getcitid bigint;
  v_getkeyprice numeric(19,4);
  v_countryid bigint;
BEGIN
  -- BEGIN TRAN (removed)
  SELECT cid INTO v_countryid FROM portal_login WHERE plid = v_plid;
  SELECT cpc INTO v_getkeyprice FROM tbl_cpcforcatergory WHERE catid = v_catid AND cid = v_countryid;
  IF NOT EXISTS(SELECT * FROM tbl_keyword_in_sponsorad WHERE smcid = v_smcid AND keywordid = v_keywordid AND catid = v_catid) THEN
  INSERT INTO tbl_keyword_in_sponsorad (smcid, keywordid, key_price, bid_price, date, status, catid) VALUES (v_smcid, v_keywordid, v_getkeyprice, v_getkeyprice, dbo.fun_getCurrentDate(), 1, v_catid);
  v_intresult := 1;
  ELSE
  IF (v_key_sp_id = 0) THEN
  UPDATE tbl_keyword_in_sponsorad SET smcid = v_smcid, keywordid = v_keywordid, key_price = v_getkeyprice, bid_price = v_getkeyprice, date = dbo.fun_getCurrentDate(), status = 1 WHERE smcid = v_smcid AND keywordid = v_keywordid AND catid = v_catid;
  v_intresult := 1;
  ELSE
  UPDATE tbl_keyword_in_sponsorad SET status = 0 WHERE smcid = v_smcid AND keywordid = v_keywordid AND catid = v_catid;
  v_intresult := 2;
  END IF;
  END IF;
  SELECT 0 INTO v_err;
  IF (v_err <> 0) THEN
  v_intresult := 0;
  -- ROLLBACK (removed)
  RETURN;
  END IF;
  SELECT 0 INTO v_err;
  IF (v_err <> 0) THEN
  v_intresult := 0;
  -- ROLLBACK (removed)
  RETURN;
  END IF;
  -- COMMIT (removed)
END;
$$;


