CREATE FUNCTION dbo.usp_insert_update_referrallink(v_filename character varying, v_url text, v_mode character varying, v_rlid integer, v_active integer) RETURNS void
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF (v_mode = 'add') THEN
  INSERT INTO referral_link (title, image, url, date, active) VALUES ('Title', 'th.jpg', v_url, CURRENT_TIMESTAMP, CAST(v_active AS BIT));
  ELSE
  UPDATE referral_link SET url = v_url, image = (CASE WHEN '' || v_filename || '' = '' THEN image ELSE '' || v_filename || '' END), active = CAST(v_active AS BIT) WHERE rlid = v_rlid;
  END IF;
END;
$$;


