--
-- Name: usp_insertarea(character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_insertarea(v_country character varying) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_state varchar(50);
  v_cid INT;
  v_maxsid int;
  v_aid bigint;
  v_areaname varchar(50);
  v_pincode varchar(25);
  v_sid int;
  v_city varchar(50);
  v_ctid int;
  cr_area CURSOR FOR SELECT region2, region3, locality, postcode FROM locationtemp;
BEGIN
  -- BEGIN TRAN (removed)
  v_cid := 0;
  SELECT cid INTO v_cid FROM country WHERE countryname = v_country;
  IF (v_cid = 0) THEN
  RETURN;
  END IF;
  OPEN cr_area;
  FETCH cr_area INTO v_state,v_city,v_areaname,v_pincode;
  WHILE (found) LOOP
  SELECT sid INTO v_sid FROM state WHERE statename = v_state AND cid = v_cid;
  SELECT ctid INTO v_ctid FROM city WHERE cityname = v_city AND cid = v_cid AND sid = v_sid;
  IF EXISTS(SELECT aid FROM area_master WHERE areaname = v_areaname AND sid = v_sid AND v_pincode = pincode) THEN
  UPDATE area_master SET ctid = v_ctid WHERE areaname = v_areaname AND sid = v_sid AND v_pincode = pincode AND cid = v_cid;
  END IF;
  FETCH cr_area INTO v_state,v_city,v_areaname,v_pincode;
  END LOOP;
  CLOSE cr_area;
  -- DEALLOCATE (removed)
  IF (0 <> 0) THEN
  CLOSE cr_area;
  -- DEALLOCATE (removed)
  -- ROLLBACK (removed)
  RETURN;
  END IF;
  -- COMMIT (removed)
END;
$$;


--
-- Name: usp_insertbankdetais(bigint, character varying, character varying, character varying, character varying, character varying, character varying, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_insertbankdetais(v_plid bigint, v_holdername character varying DEFAULT ''::character varying, v_acountno character varying DEFAULT ''::character varying, v_bankname character varying DEFAULT ''::character varying, v_branchname character varying DEFAULT ''::character varying, v_iesccode character varying DEFAULT ''::character varying, v_pancard character varying DEFAULT ''::character varying, INOUT v_strresult integer DEFAULT 0) RETURNS integer
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_regno BIGINT;
  v_dtndate timestamp;
  v_pancard_count INT;
BEGIN
  -- BEGIN TRAN (removed)
  v_regno := 0;
  v_pancard_count := 0;
  BEGIN
  SELECT regno INTO v_regno FROM member_master WHERE plid = v_plid;
  SELECT dtm_date INTO v_dtndate FROM bank_accounts WHERE regno = v_regno AND active = 1;
  IF (v_pancard = '') THEN
  SELECT panno INTO v_pancard FROM portal_login WHERE plid = v_plid;
  END IF;
  IF EXISTS(SELECT regno FROM bank_accounts WHERE regno = v_regno) THEN
  v_strresult := 2;
  UPDATE bank_accounts SET active = 0 WHERE regno = v_regno AND active = 1;
  INSERT INTO bank_accounts (regno, accountholdername, accountno, bankname, branchname, ifsccode, active, dtm_date, dtm_update_date, pancardno) VALUES (v_regno, v_holdername, v_acountno, v_bankname, v_branchname, v_iesccode, 1, v_dtndate, dbo.FUN_GETCURRENTDATE(), v_pancard);
  UPDATE member_master SET bankname = v_bankname, branchname = v_branchname, accountno = v_acountno, ifsccode = v_iesccode, panno = v_pancard WHERE regno = v_regno;
  END IF;
  IF NOT EXISTS(SELECT regno FROM bank_accounts WHERE regno = v_regno) THEN
  v_strresult := 1;
  INSERT INTO bank_accounts (regno, accountholdername, accountno, bankname, branchname, ifsccode, active, dtm_date, dtm_update_date, pancardno) VALUES (v_regno, v_holdername, v_acountno, v_bankname, v_branchname, v_iesccode, 1, dbo.FUN_GETCURRENTDATE(), '', v_pancard);
  UPDATE member_master SET bankname = v_bankname, branchname = v_branchname, accountno = v_acountno, ifsccode = v_iesccode, panno = v_pancard WHERE regno = v_regno;
  END IF;
  EXCEPTION WHEN OTHERS THEN
  PERFORM dbo.sp_errorlog();
  IF (0 > 0) THEN
  -- ROLLBACK (removed)
  END IF;
  RETURN;
  END;
  IF (0 <> 0) THEN
  v_strresult := 'Error';
  -- ROLLBACK (removed)
  RETURN;
  END IF;
  -- COMMIT (removed)
  -- SET option (removed)
END;
$$;


