  v_intresult := 1;
  END IF;
  IF NOT EXISTS(SELECT did FROM bank_accounts_distributor WHERE did = v_plid) THEN
  INSERT INTO bank_accounts_distributor (did, accountholdername, accountno, bankname, branchname, ifsccode, active, dtm_date, dtm_update_date, pancardno, cancelled_cheque_img, address, state, city, kyctype, isaprove, commentorremark) VALUES (v_plid, v_holdername, v_acountno, v_bankname, v_branchname, v_iesccode, 1, dbo.FUN_GETCURRENTDATE(), '', '', v_cancelled_cheque_img, v_address, v_state, v_city, v_kyctype, 0, '');
  v_intresult := 2;
  END IF;
  IF (0 <> 0) THEN
  v_intresult := 0;
  -- ROLLBACK (removed)
  RETURN;
  END IF;
  -- COMMIT (removed)
  -- SET option (removed)
END;
$$;


