--
-- Name: usp_insertbulkproduct(bigint, xml); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_insertbulkproduct(v_branchid bigint DEFAULT 0, v_xmlproductlist xml DEFAULT NULL::xml) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_i int;
  v_rowcount int;
  v_mcid bigint;
  v_cid bigint;
  v_scid bigint;
  v_vcid bigint;
  v_vattitle varchar(50);
  v_code varchar( 100);
  v_title varchar( 200);
  v_shortdesc varchar( 2000);
  v_fulldesc varchar( 2000);
  v_keyfeatures varchar( 500);
  v_unitqty int;
  v_unit varchar( 50);
  v_stockin int;
  v_images varchar( 500);
  v_mrp decimal;
  v_dap decimal;
  v_discount decimal;
  v_deal varchar( 2000);
  v_groupname varchar( 50);
  v_replacement int;
  v_procsla int;
  v_cod boolean;
  v_shippcharge decimal;
  v_weight_kg decimal;
  v_length_cms decimal;
  v_breadth_cms decimal;
  v_height_cms decimal;
  v_errorreason varchar( 2000);
  v_warrinfo int;
  v_allattributes text;
  v_pricecurrency varchar(50);
  v_maxmprid bigint;
  v_count1 int;
  v_count2 int;
  v_value varchar(200);
  v_itemval varchar(100);
  v_paybleamount decimal(18,2);
  v_commissionamount Decimal(18,0);
  v_lastidentity BIGINT;
  v_countimage1 int;
  v_countimage2 int;
  v_splitdata varchar(50);
  v_dealid int;
  v_groupid int;
  v_awk int;
  v_totalcolumncount int;
  v_totalrowscount int;
  v_totalerrorcount int;
  v_totalrepeatcount int;
  v_totalwarningcount int;
  v_totalsuccesscount int;
BEGIN
  DROP TABLE IF EXISTS tmp_tmp;
  CREATE TEMP TABLE tmp_tmp (SNo smallint GENERATED BY DEFAULT AS IDENTITY,MCID BigInt,CID BigInt,SCID BigInt,Vat varchar(50),Code varchar(100),Title varchar(200),
	ShortDesc varchar(2000),FullDesc varchar(2000),KeyFeatures varchar(500),UnitQty int,Unit varchar(50),StockIn int,Images varchar(500),MRP decimal(18,2),
	DAP decimal(18,2),Discount decimal(18,2),Deal varchar(50),GroupName varchar(50),Replacement int,ProcSLA int,COD boolean,ShippCharge decimal(18,2),
	Weight_kg decimal(18,2),Length_cms decimal(18,2),Breadth_cms decimal(18,2),Height_cms decimal(18,2),WarrInfo Int,
	AllAttributes text,ErrorReason text) ON COMMIT DROP;
  INSERT INTO tmp_tmp (mcid, cid, scid, vat, code, title, shortdesc, fulldesc, keyfeatures, unitqty, unit, stockin, images, mrp, dap, discount, deal, groupname, replacement, procsla, cod, shippcharge, weight_kg, length_cms, breadth_cms, height_cms, warrinfo, allattributes, errorreason) SELECT t.c.value('./MCID[1]', 'bigint'), t.c.value('./CID[1]', 'bigint'), t.c.value('./SCID[1]', 'bigint'), t.c.value('./Vat[1]', 'varchar(50)'), t.c.value('./Code[1]', 'varchar(100)'), t.c.value('./Title[1]', 'varchar(200)'), t.c.value('./ShortDesc[1]', 'varchar(2000)'), t.c.value('./FullDesc[1]', 'varchar(2000)'), t.c.value('./KeyFeatures[1]', 'varchar(500)'), t.c.value('./UnitQty[1]', 'int'), t.c.value('./Unit[1]', 'varchar(50)'), t.c.value('./StockIn[1]', 'int'), t.c.value('./Images[1]', 'varchar(500)'), t.c.value('./MRP[1]', 'decimal(18,2)'), t.c.value('./DAP[1]', 'decimal(18,2)'), t.c.value('./Discount[1]', 'decimal(18,2)'), t.c.value('./Deal[1]', 'varchar(50)'), t.c.value('./GroupName[1]', 'varchar(50)'), t.c.value('./Replacement[1]', 'int'), t.c.value('./ProcSLA[1]', 'int'), t.c.value('./COD[1]', 'bit'), t.c.value('./ShippCharge[1]', 'decimal(18,2)'), t.c.value('./Weight_kg[1]', 'decimal(18,2)'), t.c.value('./Length_cms[1]', 'decimal(18,2)'), t.c.value('./Breadth_cms[1]', 'decimal(18,2)'), t.c.value('./Height_cms[1]', 'decimal(18,2)'), t.c.value('./WarrInfo[1]', 'int'), t.c.value('./AllAttributes[1]', 'varchar(2000)'), t.c.value('./ErrorReason[1]', 'varchar(2000)') FROM v_xmlproductlist.NODES('/Product/Tr') AS t(c);
  v_i := 1;
  v_rowcount := (SELECT COUNT(*) FROM tmp_tmp);
  v_mcid := NULL;
  v_cid := NULL;
  v_scid := NULL;
  v_vcid := NULL;
  v_vattitle := NULL;
  v_code := NULL;
  v_title := NULL;
  v_shortdesc := NULL;
  v_fulldesc := NULL;
  v_keyfeatures := NULL;
  v_unitqty := NULL;
  v_unit := NULL;
  v_stockin := NULL;
  v_images := NULL;
  v_mrp := NULL;
  v_dap := NULL;
  v_discount := NULL;
  v_deal := NULL;
  v_groupname := NULL;
  v_replacement := NULL;
  v_procsla := NULL;
  v_cod := NULL;
  v_shippcharge := NULL;
  v_weight_kg := NULL;
  v_length_cms := NULL;
  v_breadth_cms := NULL;
  v_height_cms := NULL;
  v_errorreason := '';
  v_warrinfo := 0;
  v_allattributes := '';
  v_lastidentity := 0;
  WHILE (v_i <= v_rowcount) LOOP
  v_lastidentity := 0;
  SELECT mcid, cid, scid, vat, code, title, shortdesc, fulldesc, keyfeatures, unitqty, unit, stockin, images, mrp, dap, discount, deal, groupname, replacement, procsla, cod, shippcharge, weight_kg, length_cms, breadth_cms, height_cms, warrinfo, allattributes INTO v_mcid, v_cid, v_scid, v_vattitle, v_code, v_title, v_shortdesc, v_fulldesc, v_keyfeatures, v_unitqty, v_unit, v_stockin, v_images, v_mrp, v_dap, v_discount, v_deal, v_groupname, v_replacement, v_procsla, v_cod, v_shippcharge, v_weight_kg, v_length_cms, v_breadth_cms, v_height_cms, v_warrinfo, v_allattributes FROM tmp_tmp WHERE sno = v_i;
  IF NOT EXISTS(SELECT 1 FROM tbl_vat_categories WHERE vattitle = v_vattitle) THEN
  v_errorreason := v_errorreason || '^' || 'ER100';
  ELSE
  SELECT vcid INTO v_vcid FROM tbl_vat_categories WHERE vattitle = v_vattitle AND branchid = v_branchid;
  END IF;
  IF (COALESCE(v_code, '') = '') THEN
  v_errorreason := v_errorreason || '^' || 'ER103';
  END IF;
  IF EXISTS(SELECT 1 FROM ims_subproduct WHERE subprcode = v_code) THEN
  v_errorreason := v_errorreason || '^' || 'ER104';
  END IF;
  IF EXISTS(SELECT 1 FROM excel_product WHERE code = v_code) THEN
  v_errorreason := v_errorreason || '^' || 'ER104';
  END IF;
  IF (COALESCE(v_stockin, 0) = 0) THEN
  v_errorreason := v_errorreason || '^' || 'ER106';
  END IF;
  IF (COALESCE(v_stockin, 0) < 0) THEN
  v_errorreason := v_errorreason || '^' || 'ER105';
  END IF;
  IF (COALESCE(v_images, '') = '') THEN
  v_errorreason := v_errorreason || '^' || 'ER107-' || v_images;
  END IF;
  IF (COALESCE(v_images, '') <> '') THEN
  DROP TABLE IF EXISTS tmp_tempimages;
  CREATE TEMP TABLE tmp_tempimages ON COMMIT DROP AS SELECT ROW_NUMBER() OVER (ORDER BY splitdata NULLS FIRST) AS rowno, * FROM dbo.FNSPLITSTRING(v_images, '^');
  v_countimage1 := 0;
  v_countimage2 := 0;
  v_countimage1 := 1;
  SELECT COUNT(1) INTO v_countimage2 FROM tmp_tempimages;
  IF (v_countimage2 > 5) THEN
  v_errorreason := v_errorreason || '^' || 'ER108';
  END IF;
  WHILE (v_countimage1 <= v_countimage2) LOOP
  v_splitdata := '';
  SELECT splitdata INTO v_splitdata FROM tmp_tempimages WHERE rowno = v_countimage1;
  IF (COALESCE(v_splitdata, '') <> '' AND POSITION('.jpg' IN v_splitdata) > 0) THEN
  v_splitdata := '';
  END IF;
  IF (COALESCE(v_splitdata, '') <> '' AND POSITION('.png' IN v_splitdata) > 0) THEN
  v_splitdata := '';
  END IF;
  IF (COALESCE(v_splitdata, '') = '') THEN
  v_errorreason := v_errorreason || '^' || 'ER109';
  END IF;
  v_countimage1 := v_countimage1 + 1;
  END LOOP;
  DROP TABLE IF EXISTS tmp_tempimages;
  END IF;
  RAISE NOTICE '%', 'Product Sell MRP';
  IF (COALESCE(v_mrp, 0) = 0) THEN
  v_errorreason := v_errorreason || '^' || 'ER110';
  END IF;
  RAISE NOTICE '%', 'Product Sell DAP';
  IF (COALESCE(v_dap, 0) = 0) THEN
  v_errorreason := v_errorreason || '^' || 'ER111';
  END IF;
  RAISE NOTICE '%', 'Product Sell Discount';
  IF (COALESCE(v_discount, 0) = 0) THEN
  v_errorreason := v_errorreason || '^' || 'ER112';
  END IF;
  RAISE NOTICE '%', 'Product Sell MRP Is Not Less than DAP';
  IF (COALESCE(v_mrp, 0) < COALESCE(v_dap, 0)) THEN
  v_errorreason := v_errorreason || '^' || 'ER128';
  END IF;
  IF (COALESCE(v_groupname, '') = '') THEN
  IF EXISTS(SELECT 1 FROM tbl_pincodegroup WHERE groupname = v_groupname AND isactive = 1 AND touserid = v_branchid AND tousertype = 'Branch') THEN
  v_errorreason := v_errorreason || '^' || 'ER114';
  END IF;
  END IF;
  RAISE NOTICE '%', 'Replacement Day';
  IF (CAST(COALESCE(v_replacement, '0') AS INT) < 1) THEN
  v_errorreason := v_errorreason || '^' || 'ER115';
  END IF;
  IF (CAST(COALESCE(v_procsla, '0') AS INT) < 1) THEN
  v_errorreason := v_errorreason || '^' || 'ER117';
  END IF;
  IF (CAST(COALESCE(v_weight_kg, 0) AS INT) < 0) THEN
  v_errorreason := v_errorreason || '^' || 'ER118';
  END IF;
  IF (COALESCE(v_length_cms, 0) < 0) THEN
  v_errorreason := v_errorreason || '^' || 'ER119';
  END IF;
  IF (COALESCE(v_breadth_cms, 0) < 0) THEN
  v_errorreason := v_errorreason || '^' || 'ER120';
  END IF;
  IF (COALESCE(v_height_cms, 0) < 0) THEN
  v_errorreason := v_errorreason || '^' || 'ER121';
  END IF;
  IF (COALESCE(v_warrinfo, 0) < 1) THEN
  v_errorreason := v_errorreason || '^' || 'ER122';
  END IF;
  IF (COALESCE(v_branchid, 0) = 0) THEN
  v_errorreason := v_errorreason || '^' || 'ER129';
  END IF;
  IF (COALESCE(v_unitqty, 0) < 1) THEN
  v_errorreason := v_errorreason || '^' || 'ER127';
  END IF;
  RAISE NOTICE '%', 'Successfully Have not any error';
  IF (COALESCE(v_errorreason, '') = '') THEN
  v_dealid := NULL;
  v_groupid := NULL;
  SELECT id INTO v_dealid FROM tbl_deals WHERE name = v_deal;
  SELECT id INTO v_groupid FROM tbl_pincodegroup WHERE groupname = v_groupname AND isactive = 1 AND touserid = v_branchid AND tousertype = 'Branch';
  INSERT INTO excel_product (mcid, cid, scid, vcid, code, producttitle, shortdescription, fulldescription, keyfeatures, unitqty, unit, stockin, productimages, sellmrp, dap, discount, dealsids, groupid, replacementday, procurementsla, cashondelivery, shippingcharges, weight_kg, length_cms, breadth_cms, height_cms, errorreason, warrentyinfocare, branchid, createddate, qcstatus, allattribute) VALUES (v_mcid, v_cid, v_scid, v_vcid, v_code, v_title, v_shortdesc, v_fulldesc, v_keyfeatures, v_unitqty, v_unit, v_stockin, v_images, v_mrp, v_dap, v_discount, v_dealid, v_groupid, v_replacement, v_procsla, v_cod, v_shippcharge, v_weight_kg, v_length_cms, v_breadth_cms, v_height_cms, v_errorreason, v_warrinfo, v_branchid, CURRENT_TIMESTAMP, 0, v_allattributes);
  SELECT IDENT_CURRENT('EXCEl_PRODUCT') INTO v_lastidentity;
  RAISE NOTICE '%', '---- Last Identity ' || CAST(v_lastidentity AS VARCHAR(50)) || '------------ start ' || CAST(v_i AS VARCHAR(50)) || ' --------------------';
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp (rowno int GENERATED BY DEFAULT AS IDENTITY,
				Value varchar(200)) ON COMMIT DROP;
  INSERT INTO tmp_temp SELECT value FROM dbo.SPLITSTRINGBYCUSTOMSYMBOL1(v_allattributes, '^') WHERE COALESCE(value, '') <> '';
  v_count1 := 1;
  SELECT COUNT(1) INTO v_count2 FROM tmp_temp;
  WHILE (v_count1 <= v_count2) LOOP
  RAISE NOTICE '%', 'FFF';
  SELECT value INTO v_value FROM tmp_temp WHERE rowno = v_count1;
  v_title := SUBSTRING(v_value FROM 1 FOR POSITION('~' IN v_value) - 1);
  v_itemval := SUBSTRING(v_value FROM POSITION('~' IN v_value) + 1 FOR LENGTH(CAST(v_value AS TEXT)));
  IF (v_value <> 'No') THEN
  v_awk := 0;
  END IF;
  SELECT maincatid INTO v_mcid FROM dbo.tbl_category WHERE catid = v_cid;
  SELECT maincatid, catid INTO v_mcid, v_cid FROM dbo.tbl_sub_category WHERE subcatid = v_scid;
  IF (COALESCE(v_scid, 0) <> 0) THEN
  RAISE NOTICE '%', 'subcat';
  SELECT awct_id INTO v_awk FROM tbl_attributes_with_category WHERE att_name = v_title AND sub_cat_id = COALESCE(v_scid, 0) OR cat_id = COALESCE(v_cid, 0) OR main_cat_id = COALESCE(v_mcid, 0);
  ELSE
  IF (COALESCE(v_cid, 0) <> 0) THEN
  RAISE NOTICE '%', 'cat';
  SELECT awct_id INTO v_awk FROM tbl_attributes_with_category WHERE att_name = v_title AND sub_cat_id = 0 AND cat_id = COALESCE(v_cid, 0) OR main_cat_id = COALESCE(v_mcid, 0);
  ELSE
  IF (COALESCE(v_mcid, 0) <> 0) THEN
  RAISE NOTICE '%', 'main';
  SELECT awct_id INTO v_awk FROM tbl_attributes_with_category WHERE att_name = v_title AND sub_cat_id = 0 AND cat_id = 0 OR main_cat_id = COALESCE(v_mcid, 0);
  END IF;
  END IF;
  END IF;
  INSERT INTO temp_masterproductattribute (sprid, title, value, showongrid, position, isactive, catid, awcid, subcatid) VALUES (v_lastidentity, v_title, v_itemval, 1, 1, 1, v_cid, v_awk, v_scid);
  v_count1 := v_count1 + 1;
  END LOOP;
  DROP TABLE IF EXISTS tmp_temp;
  RAISE NOTICE '%', '--------------- end ' || CAST(v_i AS VARCHAR(50)) || ' ---------------------';
  UPDATE excel_product SET errorreason = v_errorreason WHERE id = v_lastidentity;
  ELSE
  UPDATE tmp_tmp SET errorreason = v_errorreason WHERE sno = v_i;
  END IF;
  v_errorreason := '';
  v_i := v_i + 1;
  END LOOP;
  RAISE NOTICE '%', 'D';
  v_totalcolumncount := 0;
  v_totalrowscount := 0;
  v_totalerrorcount := 0;
  v_totalrepeatcount := 0;
  v_totalwarningcount := 0;
  v_totalsuccesscount := 0;
  SELECT COUNT(*) INTO v_totalcolumncount FROM tempdb.sys.columns WHERE object_id = OBJECT_ID('tempdb..#TMP');
  SELECT COUNT(*) INTO v_totalrowscount FROM tmp_tmp;
  SELECT COUNT(*) INTO v_totalerrorcount FROM tmp_tmp WHERE errorreason <> '';
  SELECT COUNT(*) INTO v_totalsuccesscount FROM tmp_tmp WHERE errorreason = '';
  RAISE NOTICE '%', 'E';
  RETURN QUERY SELECT * FROM tmp_tmp;
  RETURN QUERY SELECT v_totalcolumncount AS totalcolumncount, v_totalrowscount AS totalrowscount, v_totalerrorcount AS totalerrorcount, v_totalsuccesscount AS totalsuccesscount, v_totalrepeatcount AS totalrepeatcount;
  RETURN QUERY SELECT errorcode, errordescription FROM errorcodehandleing;
  DROP TABLE IF EXISTS tmp_tmp;
END;
$$;


--
-- Name: usp_insertcatcpc(integer, text, numeric, integer, integer, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_insertcatcpc(v_catid integer DEFAULT 0, v_scatname text DEFAULT ''::text, v_cpc numeric DEFAULT 0, v_status integer DEFAULT 0, v_cid integer DEFAULT 0, INOUT v_intresult integer DEFAULT NULL::integer) RETURNS integer
    LANGUAGE plpgsql
    AS $$
BEGIN
  -- BEGIN TRAN (removed)
  IF EXISTS(SELECT * FROM tbl_cpcforcatergory WHERE catid = v_catid AND cid = v_cid) THEN
  UPDATE tbl_cpcforcatergory SET catid = v_catid, catname = v_scatname, cpc = v_cpc, status = v_status, cid = v_cid WHERE catid = v_catid AND cid = v_cid;
  ELSE
  INSERT INTO tbl_cpcforcatergory (catid, catname, cpc, status, cid) VALUES (v_catid, v_scatname, v_cpc, v_status, v_cid);
  END IF;
  IF (0 > 0) THEN
  -- ROLLBACK (removed)
  v_intresult := 0;
  RETURN;
  END IF;
  v_intresult := 1;
  -- COMMIT (removed)
END;
$$;


--
-- Name: usp_insertcontactenquiry(text, text, text, integer, text, character varying, integer, integer, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_insertcontactenquiry(v_name text, v_mob text, v_e_mail text, v_country integer, v_message text, v_dof character varying, v_status integer DEFAULT 0, v_department integer DEFAULT NULL::integer, INOUT v_intresult integer DEFAULT NULL::integer) RETURNS integer
    LANGUAGE plpgsql
    AS $$
BEGIN
  INSERT INTO website_enquiry (name, mobile, e_mail, cid, your_message, enquirydate, active, department) VALUES (v_name, v_mob, v_e_mail, v_country, v_message, CURRENT_TIMESTAMP, 1, v_department);
  v_intresult := 1;
END;
$$;


--
-- Name: usp_insertdata(integer, character varying, numeric, character varying, numeric, numeric, character varying, character varying, numeric, character varying, character varying, character varying, character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_insertdata(v_did integer DEFAULT 0, v_date character varying DEFAULT ''::character varying, v_orderamount numeric DEFAULT 0, v_orderid character varying DEFAULT ''::character varying, v_deliverycharge numeric DEFAULT 0, v_receivedamount numeric DEFAULT 0, v_paymenttype character varying DEFAULT ''::character varying, v_deliverydate character varying DEFAULT ''::character varying, v_paidamountmarchent numeric DEFAULT 0, v_paidmarchenttype character varying DEFAULT ''::character varying, v_marchentdate character varying DEFAULT ''::character varying, v_orderno character varying DEFAULT ''::character varying, INOUT v_intresult character varying DEFAULT ''::character varying) RETURNS character varying
