--
-- Name: usp_insertkyc_merchant_mobile(bigint, character varying, text, integer, integer, character varying, integer, character varying, character varying, character varying, character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_insertkyc_merchant_mobile(v_plid bigint DEFAULT 0, v_type character varying DEFAULT ''::character varying, v_image text DEFAULT ''::text, v_id integer DEFAULT 0, v_mode integer DEFAULT 1, INOUT v_strresult character varying DEFAULT ''::character varying, v_kyctype integer DEFAULT 0, v_addresstype character varying DEFAULT ''::character varying, v_addresstypenumber character varying DEFAULT 'dasdasf4543'::character varying, v_panno character varying DEFAULT ''::character varying, v_doi character varying DEFAULT ''::character varying) RETURNS character varying
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_count INT;
  v_countcheck int;
  v_tbkdid int;
BEGIN
  -- BEGIN TRAN (removed)
  v_count := 0;
  v_countcheck := 0;
  v_strresult := 'error';
  IF (v_type = 'Director-Pancard-Details') THEN
  v_type := 'Pancard-Details';
  END IF;
  SELECT COUNT(1) INTO v_countcheck FROM kyc WHERE regno = v_plid;
  SELECT COUNT(1) INTO v_count FROM kyc WHERE regno = v_plid AND type = v_type;
  IF (v_plid = 0) THEN
  v_strresult := 'error';
  -- COMMIT (removed)
  RETURN;
  END IF;
  IF (v_countcheck = 0) THEN
  IF (v_kyctype = 0) THEN
  v_strresult := 'Please Select Entity Type First !';
  -- COMMIT (removed)
  RETURN;
  END IF;
  END IF;
  IF (v_countcheck = 0) THEN
  IF (v_type <> 'Pancard-Details' AND v_type <> 'Director-Pancard-Details') THEN
  v_strresult := 'Please Enter Pancard Details First !';
  -- COMMIT (removed)
  RETURN;
  ELSE
  IF (v_type <> 'Director-Pancard-Details' AND v_type <> 'Pancard-Details') THEN
  v_strresult := 'Please Enter Pancard Details First !';
  -- COMMIT (removed)
  RETURN;
  END IF;
  END IF;
  END IF;
  IF (v_count = 1 AND v_mode = 0) THEN
  v_strresult := 'error';
  -- COMMIT (removed)
  RETURN;
  END IF;
  IF (v_count = 0 AND v_mode = 1) THEN
  INSERT INTO kyc (regno, type, image, isaprove, isdeleted, lastupdateddate, isfirsttimeorafterrejection, dtm_date, kyctype, addresstype, addressnumber) VALUES (v_plid, v_type, v_image, 0, 0, dbo.FUN_GETCURRENTDATE(), 1, dbo.FUN_GETCURRENTDATE(), 2, v_addresstype, v_addresstypenumber);
  v_strresult := 'Successfully Upload';
  END IF;
  IF (v_count >= 0 AND v_mode = 1) THEN
  IF (v_image <> '') THEN
  UPDATE kyc SET lastupdateddate = dbo.FUN_GETCURRENTDATE(), isfirsttimeorafterrejection = 2, image = v_image, addressnumber = v_addresstypenumber, isdeleted = 0, isaprove = 0, kyctype = 2, addresstype = v_addresstype WHERE regno = v_plid AND type = v_type;
  INSERT INTO kyc_history (regno, type, image, lastupdateddate, addresstype, addressnumber) VALUES (v_plid, v_type, v_image, dbo.FUN_GETCURRENTDATE(), v_addresstype, v_addresstypenumber);
  END IF;
  v_strresult := 'Successfully Upload';
  v_tbkdid := 0;
  IF (v_type = 'Pancard-Details') THEN
  IF NOT EXISTS(SELECT 1 FROM tbl_businesskycdetails WHERE plid = v_plid AND type = v_type) THEN
  INSERT INTO tbl_businesskycdetails (plid, entitytype, panno, doi, active, status, type) VALUES (v_plid, v_kyctype, v_panno, v_doi, 1, 1, v_type);
  v_strresult := 'Successfully Upload';
  -- COMMIT (removed)
  RETURN;
  ELSE
  SELECT COALESCE(tbkdid, 0) INTO v_tbkdid FROM tbl_businesskycdetails WHERE plid = v_plid AND type = v_type AND active = 1;
  UPDATE tbl_businesskycdetails SET entitytype = (CASE WHEN v_kyctype = 0 THEN entitytype ELSE v_kyctype END), panno = (CASE WHEN v_panno = '' THEN panno ELSE v_panno END), doi = (CASE WHEN v_doi = '' THEN doi ELSE (CASE WHEN v_doi = '' THEN NULL ELSE v_doi END) END), type = v_type WHERE plid = v_plid AND tbkdid = v_tbkdid;
  INSERT INTO tbl_businesskycdetails_history (plid, entitytype, panno, doi, type, lastupdateddate) VALUES (v_plid, v_kyctype, v_panno, v_doi, v_type, dbo.FUN_GETCURRENTDATE());
  v_strresult := 'Successfully Upload';
  -- COMMIT (removed)
  RETURN;
  END IF;
  END IF;
  IF (v_type = 'Company-Pancard-Details') THEN
  IF NOT EXISTS(SELECT 1 FROM tbl_businesskycdetails WHERE plid = v_plid AND type = v_type) THEN
  INSERT INTO tbl_businesskycdetails (plid, entitytype, panno, doi, active, status, type) VALUES (v_plid, v_kyctype, v_panno, v_doi, 1, 1, v_type);
  v_strresult := 'Successfully Upload';
  -- COMMIT (removed)
  RETURN;
  ELSE
  SELECT COALESCE(tbkdid, 0) INTO v_tbkdid FROM tbl_businesskycdetails WHERE plid = v_plid AND type = v_type AND active = 1;
  UPDATE tbl_businesskycdetails SET entitytype = (CASE WHEN v_kyctype = 0 THEN entitytype ELSE v_kyctype END), panno = (CASE WHEN v_panno = '' THEN panno ELSE v_panno END), doi = (CASE WHEN v_doi = '' THEN doi ELSE (CASE WHEN v_doi = '' THEN NULL ELSE v_doi END) END), type = v_type WHERE plid = v_plid AND tbkdid = v_tbkdid;
  INSERT INTO tbl_businesskycdetails_history (plid, entitytype, panno, doi, type, lastupdateddate) VALUES (v_plid, v_kyctype, v_panno, v_doi, v_type, dbo.FUN_GETCURRENTDATE());
  v_strresult := 'Successfully Upload';
  -- COMMIT (removed)
  RETURN;
  END IF;
  END IF;
  END IF;
  UPDATE kyc SET addressnumber = v_addresstypenumber, addresstype = v_addresstype WHERE regno = v_plid AND type = v_type;
  IF (0 <> 0) THEN
  v_strresult := 'Successfully Upload';
  -- ROLLBACK (removed)
  RETURN;
  END IF;
  -- COMMIT (removed)
END;
$$;


