--
-- Name: usp_insertnewcity(character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_insertnewcity(v_country character varying) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_state varchar(50);
  v_cid INT;
  v_maxsid int;
  v_city varchar(50);
  v_maxctid int;
  v_sid int;
  cr_state CURSOR FOR SELECT DISTINCT region2 FROM locationtemp;
  cr_city CURSOR FOR SELECT DISTINCT region3 FROM locationtemp WHERE region2 = v_state;
BEGIN
  -- BEGIN TRAN (removed)
  v_cid := 0;
  SELECT cid INTO v_cid FROM country WHERE countryname = v_country;
  IF (v_cid = 0) THEN
  RETURN;
  END IF;
  OPEN cr_state;
  FETCH cr_state INTO v_state;
  WHILE (found) LOOP
  SELECT COALESCE(sid, 0) INTO v_sid FROM state WHERE statename = v_state;
  IF (v_sid > 0) THEN
  OPEN cr_city;
  FETCH cr_city INTO v_city;
  WHILE (found) LOOP
  SELECT COALESCE(MAX(ctid), 0) INTO v_maxctid FROM city;
  v_maxctid := v_maxctid + 1;
  IF NOT EXISTS(SELECT ctid FROM city WHERE sid = v_sid AND cityname = v_city) THEN
  INSERT INTO city (ctid, sid, cid, cityname, active) VALUES (v_maxctid, v_sid, v_cid, v_city, 1);
  END IF;
  FETCH cr_city INTO v_city;
  END LOOP;
  CLOSE cr_city;
  -- DEALLOCATE (removed)
  IF (0 <> 0) THEN
  CLOSE cr_city;
  -- DEALLOCATE (removed)
  CLOSE cr_state;
  -- DEALLOCATE (removed)
  -- ROLLBACK (removed)
  RETURN;
  END IF;
  END IF;
  SELECT COALESCE(MAX(ctid), 0) INTO v_maxctid FROM city;
  v_maxctid := v_maxctid + 1;
  FETCH cr_state INTO v_state;
  END LOOP;
  CLOSE cr_state;
  -- DEALLOCATE (removed)
  IF (0 <> 0) THEN
  CLOSE cr_state;
  -- DEALLOCATE (removed)
  -- ROLLBACK (removed)
  RETURN;
  END IF;
  -- COMMIT (removed)
END;
$$;


