--
-- Name: usp_insertoperatordetails(text, text, character varying, character varying, character varying, integer, character varying, character varying, bigint, text); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_insertoperatordetails(v_loginid text DEFAULT ''::text, v_password text DEFAULT ''::text, v_name character varying DEFAULT ''::character varying, v_usertype character varying DEFAULT ''::character varying, v_photo character varying DEFAULT ''::character varying, v_status integer DEFAULT 0, INOUT v_strresult character varying DEFAULT NULL::character varying, v_mode character varying DEFAULT ''::character varying, v_optid bigint DEFAULT 0, INOUT v_oldimage text DEFAULT NULL::text) RETURNS record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_maxoptid bigint;
  v_newimage text;
  v_oldphoto text;
BEGIN
  v_newimage := '';
  v_oldphoto := '';
  IF (v_mode = 'New') THEN
  SELECT COALESCE(MAX(optid), 0) INTO v_maxoptid FROM tbl_operator_master;
  IF EXISTS(SELECT loginid FROM tbl_operator_master WHERE loginid = v_loginid) THEN
  v_strresult := 2;
  v_oldimage := '';
  RETURN;
  ELSE
  INSERT INTO tbl_operator_master (optid, loginid, password, name, usertype, photo, status, cod) VALUES (v_maxoptid + 1, v_loginid, v_password, v_name, v_usertype, v_photo, v_status, CURRENT_TIMESTAMP);
  v_strresult := 1;
  v_oldimage := '';
  END IF;
  END IF;
  IF (v_mode = 'edit') THEN
  IF EXISTS(SELECT loginid FROM tbl_operator_master WHERE loginid = v_loginid AND optid <> v_optid) THEN
  v_strresult := 2;
  v_oldimage := '';
  RETURN;
  ELSE
  SELECT photo INTO v_oldphoto FROM tbl_operator_master WHERE optid = v_optid;
  UPDATE tbl_operator_master SET loginid = v_loginid, password = v_password, name = v_name, usertype = v_usertype, photo = v_photo, status = v_status WHERE optid = v_optid;
  SELECT photo INTO v_newimage FROM tbl_operator_master WHERE optid = v_optid;
  IF (v_oldphoto <> v_newimage) THEN
  v_oldimage := v_oldphoto;
  ELSE
  v_oldimage := '';
  END IF;
  v_strresult := 3;
  END IF;
  END IF;
END;
$$;


