CREATE FUNCTION dbo.usp_insertupdatewishlist_mobile(v_loginid character varying, v_sprid bigint, INOUT v_strresult integer DEFAULT 0, v_status character varying DEFAULT ''::character varying, v_uidno character varying DEFAULT ''::character varying) RETURNS integer
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_regno bigint;
  v_regnumber int;
BEGIN
  -- BEGIN TRAN (removed)
  v_strresult := 1;
  SELECT regno INTO v_regno FROM member_login WHERE loginid = v_loginid;
