  v_regnumber := 0;
  IF NOT EXISTS(SELECT 1 FROM tbl_wishlist WHERE sprid = v_sprid AND loginid = v_loginid AND status = 1) THEN
  SELECT regno INTO v_regnumber FROM tbl_customerlogin WHERE clid = v_loginid;
  IF (v_regnumber > 0) THEN
  INSERT INTO tbl_wishlist (regno, sprid, date, status, loginid) VALUES (v_regnumber, v_sprid, dbo.fun_getCurrentDate(), 1, v_loginid);
  END IF;
  ELSE
  v_strresult := 2;
  END IF;
  END IF;
  IF (v_status = '1') THEN
  UPDATE tbl_wishlist SET status = 1 WHERE loginid = v_loginid AND sprid = v_sprid;
  v_strresult := 3;
  ELSE
  DELETE FROM tbl_wishlist WHERE loginid = v_loginid AND sprid = v_sprid;
  v_strresult := 4;
  END IF;
  IF (0 <> 0) THEN
  -- ROLLBACK (removed)
  v_strresult := 'Some Error occured';
  RETURN;
  END IF;
  -- COMMIT (removed)
END;
$$;


