--
-- Name: usp_insreviewsandcomments(bigint, integer, character varying, character varying, integer, text, character varying, integer, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_insreviewsandcomments(v_pmid bigint DEFAULT 0, v_rwid integer DEFAULT 0, v_name character varying DEFAULT ''::character varying, v_emailid character varying DEFAULT ''::character varying, v_rate integer DEFAULT 0, v_reviewcommentdesc text DEFAULT ''::text, v_type character varying DEFAULT ''::character varying, v_intresult integer DEFAULT NULL::integer, v_reviewtype integer DEFAULT 0) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_maxrwid INT;
  v_maxcmid INT;
  v_prid BIGINT;
  v_countrev INT;
  v_totalstar INT;
  v_avgrate INT;
BEGIN
  -- BEGIN TRAN (removed)
  DROP TABLE IF EXISTS tmp_tempdetailsall;
  CREATE TEMP TABLE tmp_tempdetailsall (ROWNUMBER INT GENERATED BY DEFAULT AS IDENTITY,  
RCID INT,  
NAME VARCHAR(200),  
RCDESC text,  
RORC VARCHAR(10),  
RATE INT,  
TOTALREVIEWS INT,  
AVGRATE INT,  
DATE VARCHAR(100)) ON COMMIT DROP;
  SELECT COALESCE(MAX(rwid), 0) INTO v_maxrwid FROM tbl_reviewmaster;
  SELECT COALESCE(MAX(cmid), 0) INTO v_maxcmid FROM tbl_commentswithreview;
  IF (v_type = 'R') THEN
  INSERT INTO tbl_reviewmaster (pmid, name, emailid, reviewtitle, reviewdesc, stars, date, status, reviewtype) VALUES (v_pmid, v_name, v_emailid, '', v_reviewcommentdesc, v_rate, CURRENT_TIMESTAMP, 1, v_reviewtype);
  END IF;
  IF (v_type = 'C') THEN
  INSERT INTO tbl_commentswithreview (rwid, pmid, name, emailid, comment, date, status) VALUES (v_rwid, v_pmid, v_name, v_emailid, v_reviewcommentdesc, CURRENT_TIMESTAMP, 1);
  END IF;
  SELECT COUNT(rwid) INTO v_countrev FROM tbl_reviewmaster WHERE pmid = v_pmid AND status = 1;
  SELECT COALESCE(SUM(stars), 0) INTO v_totalstar FROM tbl_reviewmaster WHERE pmid = v_pmid AND status = 1;
  IF (v_countrev = 0) THEN
  v_avgrate := 0;
  END IF;
  IF (v_countrev > 0) THEN
  v_avgrate := v_totalstar / v_countrev;
  END IF;
  IF (v_type = 'R') THEN
  INSERT INTO tmp_tempdetailsall SELECT rwid, CAST(name AS VARCHAR(200)) AS name, CAST(reviewdesc AS text) AS reviewdesc, 'R', stars, v_countrev, v_avgrate, CAST(TO_CHAR(date, 'TMMon DD YYYY FMHH12:MI%p') AS VARCHAR(100)) AS date FROM tbl_reviewmaster WHERE rwid = v_maxrwid + 1;
  END IF;
  IF (v_type = 'C') THEN
  INSERT INTO tmp_tempdetailsall SELECT cmid, CAST(name AS VARCHAR(200)) AS name, CAST(comment AS text) AS comment, 'C', 0, v_countrev, v_avgrate, CAST(TO_CHAR(date, 'TMMon DD YYYY FMHH12:MI%p') AS VARCHAR(100)) AS date FROM tbl_commentswithreview WHERE cmid = v_maxcmid + 1 ORDER BY date ASC NULLS FIRST;
  END IF;
  IF (0 <> 0) THEN
  v_intresult := 0;
  RETURN QUERY SELECT * FROM tmp_tempdetailsall;
  -- ROLLBACK (removed)
  RETURN;
  END IF;
  v_intresult := v_maxrwid + 1;
  RETURN QUERY SELECT * FROM tmp_tempdetailsall;
  -- COMMIT (removed)
END;
$$;


