--
-- Name: usp_invoice_details(character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_invoice_details(v_invoiceno character varying) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
BEGIN
  RETURN QUERY SELECT invno, orderid, CAST(TO_CHAR(create_date, 'DD-MM-YYYY') AS VARCHAR(30)) AS create_date, status, shipmethod, COALESCE(carrier_id, '') AS carrierid, COALESCE(noofboxes, '') AS noofboxes, COALESCE(weightinkg, '') AS weightinkg, COALESCE(carrier_by, '') AS carrierby, COALESCE(carrier_contact, '') AS carriercontact, CAST(TO_CHAR(COALESCE(dispatch_date, ''), 'DD-MM-YYYY') AS VARCHAR(30)) AS dispatcheddate, CAST(TO_CHAR(COALESCE(delivere_date, ''), 'DD-MM-YYYY') AS VARCHAR(30)) AS deliverydate, COALESCE(paymode, '') AS paymode, COALESCE(recieved_by, '') AS recievedby, COALESCE(remark, '') AS remark, inv_dap, total_ship_ch, inv_netamt, total_vat FROM tbl_invoice_master WHERE invno = v_invoiceno;
  RETURN QUERY SELECT im.invno, im.subprcode AS sprid, (SELECT subprcode FROM ims_subproduct WHERE sprid = CAST(im.subprcode AS BIGINT)) AS subprcode, im.product_name, im.product_qty, im.single_dap, im.total_dap, im.total_ship_ch, im.total_cost, im.total_vat, COALESCE(ps.unit, '') AS wunit FROM tbl_product_inv_master AS im LEFT JOIN ims_subproduct AS ps ON ps.subprcode = im.subprcode WHERE invno = v_invoiceno;
END;
$$;


--
-- Name: usp_invoice_details_for_print(character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_invoice_details_for_print(v_invoiceno character varying) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_invno VARCHAR(50);
  v_create_date timestamp;
  v_paymode VARCHAR(100);
  v_orderno VARCHAR(50);
  v_inv_dap numeric(19,4);
  v_total_ship_ch numeric(19,4);
  v_inv_netamt numeric(19,4);
  v_total_vat numeric(19,4);
  v_branchid BIGINT;
  v_maayasmobile VARCHAR(50);
  v_maayasemail VARCHAR(50);
BEGIN
  v_invno := '';
  v_paymode := '';
  v_orderno := '';
  v_inv_dap := 0;
  v_total_ship_ch := 0;
  v_inv_netamt := 0;
  v_total_vat := 0;
  v_branchid := 0;
  v_maayasmobile := '';
  v_maayasemail := '';
  SELECT invno, create_date, paymode, orderid, inv_dap, total_ship_ch, inv_netamt, total_vat INTO v_invno, v_create_date, v_paymode, v_orderno, v_inv_dap, v_total_ship_ch, v_inv_netamt, v_total_vat FROM tbl_invoice_master WHERE invno = v_invoiceno;
  RETURN QUERY SELECT fname, lname, mobileno, address, emailid, om.pincode, city, sh_fname, sh_lname, sh_mobileno, sh_emailid, sh_address, sh_pincode, sh_city, orderdate, v_invno AS invno, v_create_date AS create_date, v_paymode AS paymode, v_orderno AS orderid, v_inv_dap AS inv_dap, v_total_ship_ch AS total_ship_ch, v_inv_netamt AS inv_netamt, v_total_vat AS total_vat, om.order_qty FROM tbl_order_master AS om WHERE orderid = v_orderno;
  SELECT phone, emailid INTO v_maayasmobile, v_maayasemail FROM portal_login WHERE plid = 1;
  RETURN QUERY SELECT ('') AS maayasmobile, ('') AS maayasemail, ('') AS companytitle, ('') AS businessname, ('') AS regno, ('') AS vatno, ('') AS panno, ('') AS gstno, ('') AS cstno, ('') AS code, ('') AS merchantcode, ('') AS name, ('') AS merchantname, ('') AS imagename, ('') AS merchantlogo, ('') AS merchantemail, ('') AS merchantmobile, ('') AS pincode, ('') AS shortaddress, ('') AS landmark, ('') AS cityname, ('') AS countryname, ('') AS phoneno1, ('') AS phoneno2, ('') AS email1, ('') AS email2, ('') AS faxno1, ('') AS faxno2;
  RETURN QUERY SELECT im.invno, im.subprcode AS sprid, im.product_name, im.product_qty, im.single_dap, im.total_dap, im.total_ship_ch, im.total_cost, im.total_vat, COALESCE(ps.unit, '') AS wunit, ps.productimages, ps.subprcode FROM tbl_product_inv_master AS im LEFT JOIN ims_subproduct AS ps ON ps.sprid = im.subprcode WHERE invno = v_invoiceno;
END;
$$;


--
-- Name: usp_invoicelist(integer, integer, character varying, character varying, character varying, character varying, bigint, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_invoicelist(v_startrowindex integer DEFAULT 1, v_maxrows integer DEFAULT 100, v_searchfield character varying DEFAULT ''::character varying, v_searchvalue character varying DEFAULT ''::character varying, v_fromdate character varying DEFAULT ''::character varying, v_todate character varying DEFAULT ''::character varying, v_branchid bigint DEFAULT 1, v_totalcount integer DEFAULT 0) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_query text;
BEGIN
  v_query := '';
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp (ROWNUMBER BIGINT GENERATED BY DEFAULT AS IDENTITY,
 INVOICENO VARCHAR(50),
 ORDERNO VARCHAR(50),
 CREATEDATE timestamp,
 DISPATCHEDDATE varchar(100),
 NOOFITEM INT ,
 TOTALAMOUNT numeric(19,4),
 STATUS VARCHAR(50),
 USERNAME varchar(500),
 LOGINID varchar(500)) ON COMMIT DROP;
  v_query := 'INSERT INTO #TEMP SELECT INV.INVNO,INV.ORDERID,INV.CREATE_DATE,ISNULL(CONVERT(VARCHAR(15),INV.DISPATCH_DATE,105),''N/A'')AS DISPATCH_DATE,INV.INV_QTY,INV.INV_NETAMT,
 INV.STATUS,PL.USERNAME,PL.LOGINID  FROM TBL_INVOICE_MASTER INV LEFT OUTER JOIN TBL_ORDER_MASTER OM ON OM.ORDERID = INV.ORDERID INNER JOIN PORTAL_LOGIN PL ON
 PL.PLID=OM.BRANCHID WHERE INV.ORDERID != '''' ';
  IF (v_searchfield <> '') THEN
  IF (v_searchfield = 'LOGINID') THEN
  v_query := v_query || (' AND PL.LOGINID LIKE ''%' || v_searchvalue || '%''');
  END IF;
  IF (v_searchfield = 'USERNAME') THEN
  v_query := v_query || (' AND PL.USERNAME LIKE ''%' || v_searchvalue || '%''');
  END IF;
  IF (v_searchfield = 'PHONE') THEN
  v_query := v_query || (' AND PL.PHONE LIKE ''%' || v_searchvalue || '%''');
  END IF;
  END IF;
  IF ((v_fromdate <> '') AND (v_todate = '')) THEN
  v_query := v_query || ' AND CONVERT(DATE, INV.CREATE_DATE, 105) BETWEEN  CONVERT(DATE, ''' || v_fromdate || ''', 105) AND  CONVERT(DATE, DBO.FUN_GETCURRENTDATE(), 105)';
  END IF;
  IF ((v_fromdate = '') AND (v_todate <> '')) THEN
  v_query := v_query || 'AND CONVERT(DATE, INV.CREATE_DATE, 105) BETWEEN  CONVERT(DATE, ''' || v_todate || ''', 105) AND  CONVERT(DATE, DBO.FUN_GETCURRENTDATE(), 105)';
  END IF;
  IF ((v_fromdate <> '') AND (v_todate <> '')) THEN
  v_query := v_query || 'AND CONVERT(DATE, INV.CREATE_DATE, 105) BETWEEN CONVERT(DATE, ''' || v_fromdate || ''', 105) AND  CONVERT(DATE, ''' || v_todate || ''', 105)';
  END IF;
  v_query := v_query || ' ORDER BY  INV.CREATE_DATE DESC ';
  EXECUTE v_query;
  RETURN QUERY SELECT * FROM tmp_temp WHERE rownumber BETWEEN v_startrowindex AND v_maxrows;
  SELECT COUNT(rownumber) INTO v_totalcount FROM tmp_temp;
  DROP TABLE IF EXISTS tmp_temp;
  -- SET option (removed)
END;
$$;


--
-- Name: usp_ipn_recharge_status_mobile(character varying, numeric, character varying, numeric, character varying, character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_ipn_recharge_status_mobile(v_ordernumber character varying DEFAULT ''::character varying, v_status numeric DEFAULT 0, v_opref character varying DEFAULT ''::character varying, v_msg numeric DEFAULT 0, v_usertxn character varying DEFAULT ''::character varying, INOUT v_strresult character varying DEFAULT ''::character varying) RETURNS character varying
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_clid INT;
  v_loginid VARCHAR(500);
  v_did INT;
  v_shoppingwallet DECIMAL(18,8);
  v_pmid int;
  v_distributorbalance decimal(18,8);
  v_billamount DECIMAL(18,8);
  v_orderid VARCHAR(500);
  v_totalpaidamount DECIMAL(18,8);
  v_oorid INT;
  v_mobileno VARCHAR(20);
  v_rechargetype VARCHAR(100);
  v_getrechargestatus varchar(100);
  v_remark VARCHAR(600);
BEGIN
  -- BEGIN TRAN (removed)
  v_strresult := 'ok';
  v_clid := 0;
  v_loginid := '';
  v_did := 0;
  v_pmid := 0;
  v_distributorbalance := 0;
  v_billamount := 0;
  v_orderid := '';
  v_totalpaidamount := 0;
  v_oorid := 0;
  v_mobileno := '';
  v_rechargetype := '';
  v_getrechargestatus := '';
  IF NOT EXISTS(SELECT 1 FROM dbo.tbl_customer_postpaid_recharges WHERE transactionid = v_ordernumber AND rechargestatus = 'PENDING') AND NOT EXISTS(SELECT 1 FROM dbo.tbl_customer_dth_recharges WHERE transactionid = v_ordernumber AND rechargestatus = 'PENDING') AND NOT EXISTS(SELECT 1 FROM dbo.tbl_customer_prepaid_recharges WHERE transactionid = v_ordernumber AND rechargestatus = 'PENDING') AND NOT EXISTS(SELECT 1 FROM dbo.tbl_customer_electricity_recharges WHERE transactionid = v_ordernumber AND rechargestatus = 'PENDING') AND NOT EXISTS(SELECT 1 FROM dbo.tbl_customer_gas_recharges WHERE transactionid = v_ordernumber AND rechargestatus = 'PENDING') THEN
  v_strresult := 'Invalid Transaction Id!';
  -- COMMIT (removed)
  RETURN;
  END IF;
  IF EXISTS(SELECT 1 FROM dbo.tbl_customer_postpaid_recharges WHERE transactionid = v_ordernumber AND rechargestatus = 'PENDING') THEN
  v_rechargetype := 'POSTPAID';
  END IF;
  IF EXISTS(SELECT 1 FROM dbo.tbl_customer_dth_recharges WHERE transactionid = v_ordernumber AND rechargestatus = 'PENDING') THEN
  v_rechargetype := 'DTH';
  END IF;
  IF EXISTS(SELECT 1 FROM dbo.tbl_customer_prepaid_recharges WHERE transactionid = v_ordernumber AND rechargestatus = 'PENDING') THEN
  v_rechargetype := 'PREPAID';
  END IF;
  IF EXISTS(SELECT 1 FROM dbo.tbl_customer_electricity_recharges WHERE transactionid = v_ordernumber AND rechargestatus = 'PENDING') THEN
  v_rechargetype := 'ELECTRICITY';
  END IF;
  IF EXISTS(SELECT 1 FROM dbo.tbl_customer_gas_recharges WHERE transactionid = v_ordernumber AND rechargestatus = 'PENDING') THEN
  v_rechargetype := 'GAS';
  END IF;
  IF (v_rechargetype = 'POSTPAID') THEN
  SELECT clid, rechargeamount, mobileno, rechargestatus INTO v_clid, v_billamount, v_mobileno, v_getrechargestatus FROM dbo.tbl_customer_postpaid_recharges WHERE transactionid = v_ordernumber;
  END IF;
  IF (v_rechargetype = 'DTH') THEN
  SELECT clid, rechargeamount, mobileno, rechargestatus INTO v_clid, v_billamount, v_mobileno, v_getrechargestatus FROM dbo.tbl_customer_dth_recharges WHERE transactionid = v_ordernumber;
  END IF;
  IF (v_rechargetype = 'PREPAID') THEN
  SELECT clid, rechargeamount, mobileno, rechargestatus INTO v_clid, v_billamount, v_mobileno, v_getrechargestatus FROM dbo.tbl_customer_prepaid_recharges WHERE transactionid = v_ordernumber;
  END IF;
  IF (v_rechargetype = 'ELECTRICITY') THEN
  SELECT clid, rechargeamount, mobileno, rechargestatus INTO v_clid, v_billamount, v_mobileno, v_getrechargestatus FROM dbo.tbl_customer_electricity_recharges WHERE transactionid = v_ordernumber;
  END IF;
  IF (v_rechargetype = 'GAS') THEN
  SELECT clid, rechargeamount, mobileno, rechargestatus INTO v_clid, v_billamount, v_mobileno, v_getrechargestatus FROM dbo.tbl_customer_gas_recharges WHERE transactionid = v_ordernumber;
  END IF;
  SELECT clid, did, loginid INTO v_clid, v_did, v_loginid FROM tbl_customerlogin WHERE clid = v_clid;
  SELECT COALESCE(availablebalance, 0) INTO v_shoppingwallet FROM tbl_customerwallet WHERE clid = v_clid;
  SELECT pmid INTO v_pmid FROM tbl_distributor WHERE did = v_did;
  SELECT COALESCE(available_wallet, 0) INTO v_distributorbalance FROM tbl_distributor_prepaid_setting WHERE pmid = v_pmid;
  v_remark := '';
  IF (v_getrechargestatus = 'PENDING' AND v_billamount > 0 AND v_status = 'FAILURE') THEN
  IF (v_rechargetype = 'POSTPAID') THEN
  v_remark := 'Wallet credited against refund for POSTPAID RECHARGE on ' || CAST(v_mobileno AS VARCHAR(20)) || ' with transaction id ' || v_ordernumber;
  END IF;
  IF (v_rechargetype = 'PREPAID') THEN
  v_remark := 'Wallet credited against refund for PREPAID RECHARGE on ' || CAST(v_mobileno AS VARCHAR(20)) || ' with transaction id ' || v_ordernumber;
  END IF;
  IF (v_rechargetype = 'DTH') THEN
  v_remark := 'Wallet credited against refund for DTH RECHARGE on ' || CAST(v_mobileno AS VARCHAR(20)) || ' with transaction id ' || v_ordernumber;
  END IF;
  IF (v_rechargetype = 'GAS') THEN
  v_remark := 'Wallet credited against refund for RECHARGE on ' || CAST(v_mobileno AS VARCHAR(20)) || ' with transaction id ' || v_ordernumber;
  END IF;
  IF (v_rechargetype = 'ELECTRICITY') THEN
  v_remark := 'Wallet credited against refund for ELECTRICITY RECHARGE on ' || CAST(v_mobileno AS VARCHAR(20)) || ' with transaction id ' || v_ordernumber;
  END IF;
  UPDATE tbl_customerwallet SET availablebalance = availablebalance + v_billamount WHERE clid = v_clid;
  INSERT INTO tbl_customerwallet_statements (clid, processdate, crdrtype, cramt, dramt, old_balance, balance, remarks, traceno, status) VALUES (v_clid, dbo.FUN_GETCURRENTDATE(), 'CR', v_billamount, 0, v_shoppingwallet, (v_shoppingwallet + v_billamount), v_remark, v_ordernumber, 1);
  UPDATE tbl_distributor_prepaid_setting SET available_wallet = available_wallet + v_billamount, used_wallet = used_wallet + v_billamount WHERE pmid = v_pmid;
  INSERT INTO tbl_resellerwalletstatement (did, date, crdrtype, cr_amount, dr_amount, remarks, status, traceno, old_bal, balance) VALUES (v_did, dbo.FUN_GETCURRENTDATE(), 'CR', v_billamount, 0, v_remark, 1, v_ordernumber, v_distributorbalance, (v_distributorbalance + v_billamount));
  v_strresult := 'SUCCESS';
  END IF;
  -- COMMIT (removed)
END;
$$;


--
-- Name: usp_jewriacashpointdetails(integer, integer, numeric, character varying, character varying, character varying, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_jewriacashpointdetails(v_distributorid integer DEFAULT 1, v_mode integer DEFAULT 2, v_jp numeric DEFAULT 2.80, v_usernamejc character varying DEFAULT ''::character varying, v_transactionpasswordjc character varying DEFAULT ''::character varying, INOUT v_strresult character varying DEFAULT ''::character varying, v_plid integer DEFAULT 0) RETURNS character varying
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_query text;
  v_regno INT;
  v_noofminute Int;
  v_previousotpdateandtime timestamp;
  v_amountforuse Decimal(18,8);
BEGIN
  -- BEGIN TRAN (removed)
  v_query := '';
  IF (v_mode = 2) THEN
  IF (v_usernamejc <> '' AND v_transactionpasswordjc <> '') THEN
  v_regno := 0;
  IF EXISTS(SELECT 1 FROM db_mlmsoftware.dbo.portal_login WHERE username = v_usernamejc AND active = 1) THEN
  SELECT regno INTO v_regno FROM db_mlmsoftware.dbo.portal_login WHERE username = v_usernamejc AND active = 1;
  ELSE
  SELECT 0 INTO v_regno;
  END IF;
  v_noofminute := 0;
  v_amountforuse := 0.00;
  IF (v_transactionpasswordjc = '') THEN
  -- COMMIT (removed)
  v_strresult := 'JC Point OTP Is Blank';
  RETURN;
  END IF;
  IF EXISTS(SELECT 1 FROM tbl_shoppingotpmaster WHERE plid = v_plid AND active = 1 AND status = 1 AND otp = v_transactionpasswordjc AND mode = 2 AND username = v_usernamejc) THEN
  SELECT MAX(datetime), COALESCE(MAX(amountforuse), 0.00) INTO v_previousotpdateandtime, v_amountforuse FROM tbl_shoppingotpmaster WHERE plid = v_plid AND active = 1 AND status = 1 AND otp = v_transactionpasswordjc AND mode = 2 AND username = v_usernamejc LIMIT 1;
  ELSE
  v_previousotpdateandtime := NULL;
  END IF;
  IF (v_previousotpdateandtime IS NULL) THEN
  -- COMMIT (removed)
  v_strresult := 'Invalid JC Point OTP';
  RETURN;
  END IF;
  SELECT CAST(AGE(CAST(CAST(dbo.FUN_GETCURRENTDATE() AS TIMESTAMP) AS TIMESTAMP), CAST(CAST(v_previousotpdateandtime AS TIMESTAMP) AS TIMESTAMP)) AS BIGINT) INTO v_noofminute;
  IF (v_noofminute > 5) THEN
  -- COMMIT (removed)
  v_strresult := 'Your JC Point OTP Expired try again';
  RETURN;
  END IF;
  IF (v_jp <> v_amountforuse) THEN
  -- COMMIT (removed)
  v_strresult := 'JC Point OTP Does Not Match For Requested Amount';
  RETURN;
  END IF;
  v_query := 'SELECT (0.00000000) AS EWALLETCONSUMEPER,(0.00000000) AS COINWALLETCONSUMEPER,      
    (0.00000000) AS COMMISSIONWALLETCONSUMEPER,TOTALAVAILABLESHOPPINGPOINTS AS POINTREDEEMPERCENT FROM       
    [Db_MLMSoftware].[DBO].MEMBER_PERFORMANCE   WHERE 
	TOTALAVAILABLESHOPPINGPOINTS>=' || CAST(v_jp AS VARCHAR(100)) || '     
    AND REGNO =' || CAST(v_regno AS VARCHAR(10));
  v_strresult := 'success';
  EXECUTE v_query;
  -- COMMIT (removed)
  RETURN;
  END IF;
  -- COMMIT (removed)
  v_strresult := 'Otp Can Not Be Blank.';
  RETURN;
  END IF;
  -- COMMIT (removed)
  v_strresult := 'Invalid Call';
  RETURN;
END;
$$;


--
-- Name: usp_keyword(integer, integer, integer, integer, integer, integer, text, text, integer, text, integer, integer, numeric, integer, numeric, numeric, numeric, numeric, integer, character varying, character varying, character varying, integer, integer, integer, integer, text, numeric, numeric); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_keyword(v_mode integer DEFAULT 0, v_sequence integer DEFAULT 0, v_intresult integer DEFAULT 0, v_catid integer DEFAULT 0, v_scatid integer DEFAULT 0, v_kmid integer DEFAULT 0, v_keywordname text DEFAULT ''::text, v_keyworddesc text DEFAULT ''::text, v_keywordactive integer DEFAULT 1, v_keywordimgname text DEFAULT ''::text, v_startrowindex integer DEFAULT 1, v_maxrows integer DEFAULT 100, v_admincommission numeric DEFAULT 0, v_delieverycharges integer DEFAULT 0, v_handlingcharges numeric DEFAULT 0, v_fixedfee numeric DEFAULT 0, v_businessvolume numeric DEFAULT 0, v_activationpointvalue numeric DEFAULT 0, v_gst integer DEFAULT 0, v_searchsubsubcategory character varying DEFAULT ''::character varying, v_searchsubcategory character varying DEFAULT ''::character varying, v_searchcategory character varying DEFAULT ''::character varying, v_isreturn integer DEFAULT 0, v_isrefund integer DEFAULT 0, v_isexchange integer DEFAULT 0, v_days integer DEFAULT 0, v_remarks text DEFAULT ''::text, v_redeemcashback numeric DEFAULT 0.00, v_receivablecashback numeric DEFAULT 0.00) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_minindex INT;
  v_maxindex INT;
  v_query text;
  v_condition text;
  v_countquery text;
  v_parmdefinition varchar(70);
  v_name text;
  v_subcatid INT;
  v_outputparam Int;
BEGIN
  -- BEGIN TRAN (removed)
  -- SET option (removed)
  v_intresult := 0;
  IF (v_mode = 0) THEN
  v_query := '';
  v_condition := '';
  v_countquery := '';
  v_minindex := (v_startrowindex - 1) * v_maxrows + 1;
  v_maxindex := v_startrowindex * v_maxrows;
  v_query := 'SELECT ROW_NUMBER() OVER(ORDER BY KM.KEYWORDNAME) AS ROWNUMBER,KM.KMID,KM.KEYWORDNAME AS KEYWORDNAME ,          
(CASE KACTIVE WHEN 1 THEN ''Active'' ELSE ''Deactive'' END) AS KACTIVE,PC.CATNAME,PSC.SCATNAME,          
ISNULL(TSC.AdminCharge,0) AS ADMINCHARGE,ISNULL(TSC.DelieveryCharge,0) AS DelieveryCharge,          
ISNULL(TSC.HandlingCharge,0) AS HandlingCharge,ISNULL(TSC.FixedFee,0) AS FixedFee,    
ISNULL(TSC.[RETURN],0) As [RETURN],ISNULL(TSC.REFUND,0) As REFUND,ISNULL(TSC.EXCHANGE,0) As EXCHANGE,    
ACTIVATIONPV_PER INTO #TEMP13 FROM KEYWORD_MASTER KM INNER JOIN PRODUCT_CATEGORY PC ON KM.CATID = PC.CATID          
INNER JOIN PRODUCT_SUBCATEGORY PSC ON PSC.SCATID = KM.SCATID           
Left Join TBL_SUB_CATEGORY TSC ON TSC.SUBCATID=KM.KMID where 1=1';
  v_parmdefinition := N'@INTRESULT NVARCHAR(70) OUTPUT';
  v_countquery := N'SELECT @INTRESULT= COUNT(1)FROM KEYWORD_MASTER KM INNER JOIN PRODUCT_CATEGORY PC ON     
KM.CATID = PC.CATID INNER JOIN PRODUCT_SUBCATEGORY PSC ON PSC.SCATID = KM.SCATID           
Left Join TBL_SUB_CATEGORY TSC ON TSC.SUBCATID=KM.KMID where 1=1';
  IF (v_isreturn = 1) THEN
  v_condition := v_condition || ' AND  TSC.RETURN=1';
  END IF;
  IF (v_isreturn = 2) THEN
  v_condition := v_condition || ' AND  TSC.REFUND=1';
  END IF;
  IF (v_isreturn = 3) THEN
  v_condition := v_condition || ' AND  TSC.EXCHANGE=1';
  END IF;
  IF (v_searchsubsubcategory <> '') THEN
  v_searchsubsubcategory := REPLACE(v_searchsubsubcategory, '''', '''''');
  v_condition := v_condition || ('AND KM.KEYWORDNAME=''' || v_searchsubsubcategory || '''');
  END IF;
  IF (v_searchsubcategory <> '') THEN
  v_searchsubcategory := REPLACE(v_searchsubcategory, '''', '''''');
  v_condition := v_condition || ('AND PSC.SCATNAME=''' || v_searchsubcategory || '''');
  END IF;
  IF (v_searchcategory <> '') THEN
  v_searchcategory := REPLACE(v_searchcategory, '''', '''''');
  v_condition := v_condition || ('AND PC.CATNAME=''' || v_searchcategory || '''');
  END IF;
  v_query := v_query || v_condition || ' ;SELECT  *  FROM #TEMP13 WHERE ROWNUMBER BETWEEN ' || CAST(v_minindex AS VARCHAR(70)) || ' AND ' || CAST(v_maxindex AS VARCHAR(70)) || ' Order By ROWNUMBER ASC';
  v_countquery := v_countquery || v_condition;
  RAISE NOTICE '%', v_query;
  EXECUTE v_query;
  EXECUTE v_countquery;
  -- SET option (removed)
  END IF;
  IF (v_mode = 1) THEN
  RETURN QUERY SELECT km.kmid, km.keywordname, km.kactive, km.catid, km.scatid, COALESCE(tsc.admincharge, 0) AS admincharge, COALESCE(tsc.delieverycharge, 0) AS delieverycharge, COALESCE(tsc.handlingcharge, 0) AS handlingcharge, COALESCE(tsc.fixedfee, 0) AS fixedfee, COALESCE(bvper, 0) AS bvper, COALESCE(tsc.return, 0) AS isreturn, COALESCE(tsc.refund, 0) AS refund, COALESCE(tsc.exchange, 0) AS exchange, COALESCE(tsc.days, 0) AS days, COALESCE(tsc.gstgroup, 0) AS gstgroup, COALESCE(tsc.policyremarks, '') AS policyremarks, COALESCE(redeemcashback_per, 0) AS redeemcashback_per, COALESCE(cashback_per, 0) AS cashback_per, activationpv_per FROM keyword_master AS km LEFT JOIN tbl_sub_category AS tsc ON tsc.subcatid = km.kmid WHERE kmid = v_kmid;
  v_intresult := 2;
  -- COMMIT (removed)
  RETURN;
  END IF;
  IF (v_mode = 2) THEN
  DROP TABLE IF EXISTS tmp_temptable;
  CREATE TEMP TABLE tmp_temptable (ROWNO INT GENERATED BY DEFAULT AS IDENTITY,          
SINGLEVALUE text) ON COMMIT DROP;
  v_name := '';
  v_subcatid := 0;
  INSERT INTO tmp_temptable SELECT value FROM dbo.SPLITSTRINGBYCUSTOMSYMBOLSHOPING(v_keywordname, '~');
  SELECT singlevalue INTO v_name FROM tmp_temptable;
  IF (NOT EXISTS(SELECT 1 FROM keyword_master WHERE keywordname = v_keywordname AND catid = v_catid AND scatid = v_scatid AND kmid <> v_kmid)) THEN
  UPDATE keyword_master SET keywordname = v_keywordname, kactive = v_keywordactive, catid = v_catid, scatid = v_scatid WHERE kmid = v_kmid;
  UPDATE tbl_sub_category SET subcatname = v_keywordname, status = v_keywordactive, sub_cat_code = dbo.REMOVESPACESANDSPECIALCHARS(v_name), sequence = v_sequence, admincharge = v_admincommission, delieverycharge = v_delieverycharges, handlingcharge = v_handlingcharges, fixedfee = v_fixedfee, bvper = v_businessvolume, activationpv_per = v_activationpointvalue, gstgroup = v_gst, catid = v_scatid, maincatid = v_catid, return = v_isreturn, refund = v_isrefund, exchange = v_isexchange, days = v_days, policyremarks = v_remarks, redeemcashback_per = v_redeemcashback, cashback_per = v_receivablecashback WHERE subcatid = v_kmid;
  v_intresult := 3;
  -- COMMIT (removed)
  RETURN;
  ELSE
  v_intresult := 5;
  END IF;
  DROP TABLE IF EXISTS tmp_temptable;
  -- COMMIT (removed)
  RETURN;
  END IF;
  IF (v_mode = 3) THEN
  IF (NOT EXISTS(SELECT 1 FROM keyword_master WHERE keywordname = v_keywordname AND catid = v_catid AND scatid = v_scatid)) THEN
  v_outputparam := 0;
  SELECT v_intresult INTO v_outputparam FROM dbo.usp_insert_alltypecategory_new(v_id => v_scatid, v_value => v_keywordname, v_type => 'SUBCATEGORY', v_varresult => '', v_intresult => v_outputparam, v_imagename => '', v_imagesequence => v_sequence, v_hotlink => 0, v_catimgnamemobile => '', v_admincharge => v_admincommission, v_delieverycharge => v_delieverycharges, v_handlingcharge => v_handlingcharges, v_fixedfee => v_fixedfee, v_gst => v_gst, v_isreturn => v_isreturn, v_isrefund => v_isrefund, v_isexchange => v_isexchange, v_days => v_days, v_remarks => v_remarks, v_businessvolume => v_businessvolume, v_redeemcashback => v_redeemcashback, v_receivablecashback => v_receivablecashback, v_activationpointvalue => v_activationpointvalue);
  IF (v_outputparam = 0) THEN
  v_intresult := 0;
  -- ROLLBACK (removed)
  RETURN;
  END IF;
  INSERT INTO keyword_master (keywordname, kactive, catid, scatid) VALUES (v_keywordname, v_keywordactive, v_catid, v_scatid);
  v_intresult := 4;
  ELSE
  v_intresult := 5;
  END IF;
  END IF;
  -- SET option (removed)
  -- COMMIT (removed)
END;
$$;


