--
-- Name: usp_keyword_category_price_country_wise_default(character varying, integer, character varying, character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_keyword_category_price_country_wise_default(v_type character varying DEFAULT 'KEYWORD'::character varying, v_cid integer DEFAULT 0, v_keywordname character varying DEFAULT ''::character varying, v_categoryname character varying DEFAULT ''::character varying) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_count INT;
  v_count1 INT;
  v_kmid BIGINT;
  v_cidnew INT;
  v_keyword_default_price numeric(19,4);
  v_keyword_default_min_price numeric(19,4);
  v_isdefault VARCHAR(10);
  v_catid INT;
  v_cat_default_price numeric(19,4);
  v_cat_default_min_price numeric(19,4);
  v_query text;
  v_currencycode VARCHAR(10);
BEGIN
  v_query := '';
  SELECT currencycode INTO v_currencycode FROM country WHERE cid = v_cid;
  SELECT symbol, cid INTO v_currencycode, v_cid FROM settings WHERE caption = 'Active Country';
  IF (v_type = 'KEYWORD') THEN
  v_isdefault := 'YES';
  DROP TABLE IF EXISTS tmp_updatetable;
  CREATE TEMP TABLE tmp_updatetable (ROWNUMBER INT GENERATED BY DEFAULT AS IDENTITY,
				KMID BIGINT,
				CID INT,
				KEYWORD_DEFAULT_PRICE numeric(19,4),
				KEYWORD_DEFAULT_MIN_PRICE numeric(19,4)) ON COMMIT DROP;
  INSERT INTO tmp_updatetable SELECT kmid, cid, keywordprice, COALESCE(minkeywordprice, 0) FROM tbl_update_keyword_and_category_price_cwise_packagetype WHERE type = v_type;
  IF (v_keywordname <> '') THEN
  DROP TABLE IF EXISTS tmp_temp1;
  CREATE TEMP TABLE tmp_temp1 ON COMMIT DROP AS SELECT ROW_NUMBER() OVER (ORDER BY k_m.keywordname ASC NULLS FIRST) AS rownumber, COALESCE(cm.groupname, 'N/A') AS groupname, k_m.*, tccc.*, v_isdefault AS isdefault FROM keyword_master AS k_m INNER JOIN tbl_countrywise_package_price AS tccc ON 1 = 1 LEFT JOIN product_category AS pc ON pc.catid = k_m.catid LEFT JOIN tbl_categorygroupmaster AS cm ON cm.gmid = pc.gmid WHERE tccc.cid = v_cid AND RTRIM(LTRIM(k_m.keywordname)) = LTRIM(RTRIM(v_keywordname));
  v_count := 1;
  SELECT COUNT(rownumber) INTO v_count1 FROM tmp_updatetable;
  WHILE (v_count <= v_count1) LOOP
  SELECT kmid, cid, keyword_default_price, keyword_default_min_price INTO v_kmid, v_cidnew, v_keyword_default_price, v_keyword_default_min_price FROM tmp_updatetable WHERE rownumber = v_count;
  UPDATE tmp_temp1 SET keyword_default_price = v_keyword_default_price, keyword_default_min_price = v_keyword_default_min_price, isdefault = 'NO' WHERE kmid = v_kmid AND cid = v_cidnew;
  v_count := v_count + 1;
  END LOOP;
  RETURN QUERY SELECT *, v_currencycode AS currencycode FROM tmp_temp1 ORDER BY keywordname ASC NULLS FIRST;
  DROP TABLE IF EXISTS tmp_temp1;
  ELSE
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp ON COMMIT DROP AS SELECT ROW_NUMBER() OVER (ORDER BY k_m.keywordname ASC NULLS FIRST) AS rownumber, COALESCE(cm.groupname, 'N/A') AS groupname, k_m.*, tccc.*, v_isdefault AS isdefault FROM keyword_master AS k_m INNER JOIN tbl_countrywise_package_price AS tccc ON 1 = 1 LEFT JOIN product_category AS pc ON pc.catid = k_m.catid LEFT JOIN tbl_categorygroupmaster AS cm ON cm.gmid = pc.gmid WHERE tccc.cid = v_cid AND kactive = 1;
  v_count := 1;
  SELECT COUNT(rownumber) INTO v_count1 FROM tmp_updatetable;
  WHILE (v_count <= v_count1) LOOP
  SELECT kmid, cid, keyword_default_price, keyword_default_min_price INTO v_kmid, v_cidnew, v_keyword_default_price, v_keyword_default_min_price FROM tmp_updatetable WHERE rownumber = v_count;
  UPDATE tmp_temp SET keyword_default_price = v_keyword_default_price, keyword_default_min_price = v_keyword_default_min_price, isdefault = 'NO' WHERE kmid = v_kmid AND cid = v_cidnew;
  v_count := v_count + 1;
  END LOOP;
  RETURN QUERY SELECT *, v_currencycode AS currencycode FROM tmp_temp ORDER BY keywordname ASC NULLS FIRST;
  DROP TABLE IF EXISTS tmp_temp;
  END IF;
  DROP TABLE IF EXISTS tmp_updatetable;
  END IF;
  IF (v_type = 'CATEGORY') THEN
  v_isdefault := 'YES';
  DROP TABLE IF EXISTS tmp_temp_cat;
  CREATE TEMP TABLE tmp_temp_cat (ROWNUMBER INT GENERATED BY DEFAULT AS IDENTITY,
				CATID INT ,
				GROUPNAME text,
				CATNAME VARCHAR(100),
				CID INT,
				CATEGORY_DEFAULT_PRICE numeric(19,4),
				CATEGORY_DEFAULT_MIN_PRICE numeric(19,4),
				ISDEFAULT VARCHAR(10)) ON COMMIT DROP;
  DROP TABLE IF EXISTS tmp_updatetable_cat;
  CREATE TEMP TABLE tmp_updatetable_cat (ROWNUMBER INT GENERATED BY DEFAULT AS IDENTITY,
				CATID BIGINT,
				CID INT,
				CAT_DEFAULT_PRICE numeric(19,4),
				CAT_DEFAULT_MIN_PRICE numeric(19,4)) ON COMMIT DROP;
  INSERT INTO tmp_updatetable_cat SELECT catid, cid, COALESCE(catprice, 0), COALESCE(mincatprice, 0) FROM tbl_update_keyword_and_category_price_cwise_packagetype WHERE type = v_type;
  IF (v_categoryname <> '') THEN
  v_query := 'INSERT INTO #TEMP_CAT(CATID,GROUPNAME ,CATNAME,CID,CATEGORY_DEFAULT_PRICE,CATEGORY_DEFAULT_MIN_PRICE,ISDEFAULT) SELECT CATID,
							CGM.GROUPNAME, CATNAME,CID,CATEGORY_DEFAULT_PRICE,CATEGORY_DEFAULT_MIN_PRICE,''' || CAST(v_isdefault AS VARCHAR(10)) || ''' FROM
							  PRODUCT_CATEGORY PC INNER JOIN TBL_COUNTRYWISE_PACKAGE_PRICE TCCC ON 1=1 left join TBL_CATEGORYGROUPMASTER CGM ON(CGM.GMID=PC.GMID) WHERE TCCC.CID=''' || CAST(v_cid AS VARCHAR(10)) || ''' AND CATACTIVE=1 
							 AND PC.GMID=1  AND RTRIM(LTRIM(CATNAME))=''' || v_categoryname || ''' ';
  ELSE
  v_query := 'INSERT INTO #TEMP_CAT(CATID,GROUPNAME,CATNAME,CID,CATEGORY_DEFAULT_PRICE,CATEGORY_DEFAULT_MIN_PRICE,ISDEFAULT) SELECT CATID,
							CGM.GROUPNAME,CATNAME,CID,CATEGORY_DEFAULT_PRICE, CATEGORY_DEFAULT_MIN_PRICE,''' || CAST(v_isdefault AS VARCHAR(10)) || ''' FROM PRODUCT_CATEGORY PC
							 INNER JOIN TBL_COUNTRYWISE_PACKAGE_PRICE TCCC ON 1=1 left join TBL_CATEGORYGROUPMASTER CGM ON(CGM.GMID=PC.GMID) WHERE TCCC.CID=''' || CAST(v_cid AS VARCHAR(10)) || ''' AND CATACTIVE=1 AND PC.GMID=1';
  END IF;
  EXECUTE v_query;
  v_count := 1;
  SELECT COUNT(rownumber) INTO v_count1 FROM tmp_updatetable_cat;
  WHILE (v_count <= v_count1) LOOP
  SELECT catid, cid, cat_default_price, cat_default_min_price INTO v_catid, v_cidnew, v_cat_default_price, v_cat_default_min_price FROM tmp_updatetable_cat WHERE rownumber = v_count;
  UPDATE tmp_temp_cat SET category_default_price = v_cat_default_price, category_default_min_price = v_cat_default_min_price, isdefault = 'NO' WHERE catid = v_catid AND cid = v_cidnew;
  v_count := v_count + 1;
  END LOOP;
  RETURN QUERY SELECT *, v_currencycode AS currencycode FROM tmp_temp_cat;
  DROP TABLE IF EXISTS tmp_temp_cat;
  DROP TABLE IF EXISTS tmp_updatetable_cat;
  END IF;
END;
$$;


--
-- Name: usp_keyword_price(character varying, character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_keyword_price(v_areaid character varying DEFAULT ''::character varying, v_keywordid character varying DEFAULT ''::character varying) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_comma1 varchar(300);
  v_comma2 varchar(300);
  v_slice1 varchar(300);
  v_slice2 varchar(300);
  v_index1 int;
  v_index2 int;
  v_count1 int;
  v_count2 int;
  v_ctid int;
  v_noofhits int;
  v_price double precision;
BEGIN
  v_count1 := 0;
  v_count2 := 0;
  v_ctid := 0;
  v_noofhits := 0;
  v_price := 0.00;
  v_comma1 := v_keywordid;
  v_index1 := 1;
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp (keyid int,



keyprice double precision) ON COMMIT DROP;
  WHILE v_index1 <> 0 LOOP
  SELECT POSITION(',' IN v_comma1) INTO v_index1;
  IF v_index1 <> 0 THEN
  SELECT LEFT(CAST(v_comma1 AS TEXT), v_index1 - 1) INTO v_slice1;
  ELSE
  SELECT v_comma1 INTO v_slice1;
  END IF;
  v_index2 := 1;
  v_comma2 := v_areaid;
  WHILE v_index2 <> 0 LOOP
  SELECT POSITION(',' IN v_comma2) INTO v_index2;
  IF v_index2 <> 0 THEN
  SELECT LEFT(CAST(v_comma2 AS TEXT), v_index2 - 1) INTO v_slice2;
  ELSE
  SELECT v_comma2 INTO v_slice2;
  END IF;
  SELECT ctid INTO v_ctid FROM area_master WHERE aid = v_slice2;
  IF EXISTS(SELECT keywordid FROM tblnumberofhits WHERE keywordid = v_slice1 AND ctid = v_ctid AND aid = v_slice2) THEN
  SELECT COALESCE(noofhits, 0) INTO v_noofhits FROM tblnumberofhits WHERE keywordid = v_slice1 AND ctid = v_ctid AND aid = v_slice2;
  v_price := v_price + v_noofhits * 0.10;
  ELSE
  v_price := v_price + 0;
  END IF;
  SELECT RIGHT(CAST(v_comma2 AS TEXT), LENGTH(CAST(v_comma2 AS TEXT)) - v_index2) INTO v_comma2;
  IF LENGTH(CAST(v_comma2 AS TEXT)) = 0 THEN
  EXIT;
  END IF;
  END LOOP;
  INSERT INTO tmp_temp (keyid, keyprice) VALUES (v_slice1, v_price);
  v_price := 0.00;
  SELECT RIGHT(CAST(v_comma1 AS TEXT), LENGTH(CAST(v_comma1 AS TEXT)) - v_index1) INTO v_comma1;
  IF LENGTH(CAST(v_comma1 AS TEXT)) = 0 THEN
  EXIT;
  END IF;
  END LOOP;
  RETURN QUERY SELECT * FROM tmp_temp;
  DROP TABLE IF EXISTS tmp_temp;
END;
$$;


--
-- Name: usp_keyworddetails(integer, timestamp without time zone); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_keyworddetails(v_smcid integer DEFAULT 0, v_date timestamp without time zone DEFAULT NULL::timestamp without time zone) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_slice1 text;
  v_index1 INT;
  v_slice2 text;
  v_query text;
  v_catid int;
  v_cpc numeric(19,4);
  v_keywordid text;
  v_noofclicks bigint;
  v_keywordname varchar(200);
  v_status varchar(50);
  v_imagename varchar(100);
  v_currencysymbol varchar(50);
  v_cid int;
BEGIN
  -- SET option (removed)
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp (rownumber int GENERATED BY DEFAULT AS IDENTITY,
kmid int,
keywordname varchar(200),
noofclicks int,
LIMITS numeric(19,4),
total numeric(19,4),
Status varchar(20),
imagename varchar(100),
smcid int) ON COMMIT DROP;
  SELECT COALESCE(v_keywordid || ', ', '') || CAST(keyid AS VARCHAR(15)) INTO v_keywordid FROM (SELECT DISTINCT keyid FROM tbl_sponsor_search WHERE smcid = v_smcid) AS newtbl_sponser;
  v_slice1 := v_keywordid;
  v_index1 := 1;
  WHILE v_index1 <> 0 LOOP
  SELECT POSITION(',' IN v_slice1) INTO v_index1;
  IF v_index1 <> 0 THEN
  SELECT LEFT(CAST(v_slice1 AS TEXT), v_index1 - 1) INTO v_slice2;
  ELSE
  SELECT v_slice1 INTO v_slice2;
  END IF;
  SELECT catid, keywordname INTO v_catid, v_keywordname FROM keyword_master WHERE kmid = v_slice2;
  SELECT cid INTO v_cid FROM tbl_sponsor_master_campain WHERE smcid = v_smcid;
  SELECT cpc INTO v_cpc FROM tbl_cpcforcatergory WHERE catid = v_catid AND cid = v_cid;
  v_cpc := COALESCE(v_cpc, 0);
  SELECT COUNT(smcid) INTO v_noofclicks FROM tbl_sponserfunddetails WHERE smcid = v_smcid AND kmid = v_slice2 AND CAST(datetime AS DATE) = CAST(v_date AS DATE);
  SELECT (CASE WHEN searchactive = 1 THEN 'Active' WHEN searchactive = 0 THEN 'Deactive' END) INTO v_status FROM tbl_sponsor_search WHERE smcid = v_smcid AND keyid = v_slice2;
  SELECT cm.currencysymbol INTO v_currencysymbol FROM tbl_sponsor_search AS tss JOIN tbl_currencymaster AS cm ON tss.cid = cm.cid WHERE smcid = v_smcid AND keyid = v_slice2;
  IF (v_status = 'Active') THEN
  v_imagename := '../Icon/ic.png';
  ELSE
  v_imagename := '../images/ok.png';
  END IF;
  INSERT INTO tmp_temp (kmid, keywordname, noofclicks, limits, total, status, smcid, imagename) VALUES (v_slice2, v_keywordname, v_noofclicks, v_cpc, (v_noofclicks * v_cpc), v_status, v_smcid, v_imagename);
  IF (0 <> 0) THEN
  RETURN;
  END IF;
  SELECT RIGHT(CAST(v_slice1 AS TEXT), LENGTH(CAST(v_slice1 AS TEXT)) - v_index1) INTO v_slice1;
  IF LENGTH(CAST(v_slice1 AS TEXT)) = 0 THEN
  EXIT;
  END IF;
  -- SET option (removed)
  END LOOP;
  IF EXISTS(SELECT 1 FROM tbl_sponsor_search WHERE smcid = v_smcid) THEN
  RETURN QUERY SELECT DISTINCT (kmid), keywordname, noofclicks, limits, total, status, rownumber, smcid, imagename, v_currencysymbol AS currencysymbol FROM tmp_temp ORDER BY rownumber ASC NULLS FIRST;
  END IF;
END;
$$;


