CREATE FUNCTION dbo.usp_keywordpaging(v_startrowindex integer DEFAULT 1, v_maxrows integer DEFAULT 100, v_orderbyfield character varying DEFAULT ''::character varying, v_asc boolean DEFAULT true, v_searchfield character varying DEFAULT ''::character varying, v_searchvalue character varying DEFAULT ''::character varying, v_mode integer DEFAULT 0, v_recordcount integer DEFAULT 0) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_sqlquery text;
BEGIN
  -- SET option (removed)
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp (rowNumber int,
kmid bigint,
GroupName varchar(150),
CatName varchar(150),
keywordname varchar(100),
kActive varchar(15)) ON COMMIT DROP;
  v_sqlquery := '';
  v_sqlquery := 'insert into #temp select  ROW_NUMBER() over(order by pc.CatName,km.keywordname) as rownumber ,km.kmid ,CM.GroupName, pc.CatName,km.keywordname, kActive
 from   Product_Category as pc inner join keyword_master as km on km.catid=pc.catid 
 left join TBL_CATEGORYGROUPMASTER CM ON CM.GMID=PC.GMID where PC.CATACTIVE=1 and pc.GMID=1  and km.kactive=1  ';
  IF (v_searchfield = 'categoryname') THEN
  v_sqlquery := v_sqlquery || (' and pc.CatName like ''%' || v_searchvalue || '%''');
  END IF;
  IF (v_searchfield = 'keywordname') THEN
  v_sqlquery := v_sqlquery || ' and km.keywordname like ''%' || v_searchvalue || '%''';
  END IF;
  IF (v_searchfield = 'groupname') THEN
  v_sqlquery := v_sqlquery || ' and km.keywordname like ''%' || v_searchvalue || '%''';
  END IF;
  EXECUTE v_sqlquery;
  SELECT COUNT(*) INTO v_recordcount FROM tmp_temp;
  RETURN QUERY SELECT * FROM tmp_temp WHERE rownumber BETWEEN v_startrowindex AND v_maxrows;
  DROP TABLE IF EXISTS tmp_temp;
  RETURN QUERY SELECT v_recordcount AS recordcount;
  -- SET option (removed)
END;
$$;


