--
-- Name: usp_keywordsuggestionlists(integer, integer, character varying, character varying, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_keywordsuggestionlists(v_startrowindex integer, v_maxrows integer, v_fromdate character varying, v_todate character varying, v_recordcount integer) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_sqlquery text;
BEGIN
  -- SET option (removed)
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp (rowNumber int,
ksid bigint,
UserId varchar(150),
suggestedDate timestamp,
Keyword varchar(150)) ON COMMIT DROP;
  v_sqlquery := '';
  v_sqlquery := 'insert into #temp select ROW_NUMBER() OVER(ORDER BY ks.pmid desc) as rowNumber, ks.ksid ,pl.loginid,ks.suggestiondate,ks.keyword
   from tbl_keywordsuggestions ks inner join portal_login pl on ks.pmid=pl.pmid where ks.status=0 ';
  IF (v_fromdate = '' OR v_todate = '') THEN
  IF (v_fromdate <> '' AND v_todate = '') THEN
  v_sqlquery := v_sqlquery || (' and (CONVERT(date,ks.suggestiondate,103) >= CONVERT(date,''' || v_fromdate || ''',103)) ');
  END IF;
  IF (v_fromdate = '' AND v_todate <> '') THEN
  v_sqlquery := v_sqlquery || (' and (CONVERT(date,ks.suggestiondate,103) <= CONVERT(date,''' || v_todate || ''',103)) ');
  END IF;
  ELSE
  v_sqlquery := v_sqlquery || (' and (CONVERT(date,ks.suggestiondate,103) between CONVERT(date,''' || v_fromdate || ''',103) and CONVERT(date,''' || v_todate || ''',103)) ');
  END IF;
  EXECUTE v_sqlquery;
  SELECT COUNT(*) INTO v_recordcount FROM tmp_temp;
  RETURN QUERY SELECT * FROM tmp_temp WHERE rownumber BETWEEN v_startrowindex AND v_maxrows;
  DROP TABLE IF EXISTS tmp_temp;
  -- SET option (removed)
END;
$$;


