--
-- Name: usp_keywordwise_datewisetotalhits(integer, integer, character varying, character varying, character varying, integer, integer, bigint, bigint, character varying, character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_keywordwise_datewisetotalhits(v_startrowindex integer, v_maxrows integer, v_orderbyfield character varying, v_searchfield character varying, v_searchvalue character varying, v_cid integer DEFAULT 0, v_sid integer DEFAULT 0, v_ctid bigint DEFAULT 0, v_aid bigint DEFAULT 0, v_fromdate character varying DEFAULT ''::character varying, v_todate character varying DEFAULT ''::character varying) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_recordcount int;
  v_regno bigint;
  v_pmid int;
  v_sqlquery text;
BEGIN
  -- SET option (removed)
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp (rowNumber bigint,
countryName varchar(50),
stateName varchar(50),
cityName varchar(100),
areaName varchar(150),
keyword varchar(150),
category varchar(150),
TotaltHits int,
directHits int,
InDirectHits int) ON COMMIT DROP;
  IF (v_ctid > 0) THEN
  SELECT sid INTO v_sid FROM city WHERE ctid = v_ctid;
  END IF;
  IF (v_fromdate <> '' AND v_todate = '') THEN
  v_todate := v_fromdate;
  END IF;
  IF (v_fromdate = '' AND v_todate <> '') THEN
  v_fromdate := v_todate;
  END IF;
  v_sqlquery := '';
  IF (v_orderbyfield = '') THEN
  v_orderbyfield := 'grpdhm.TotaltHits desc';
  END IF;
  v_sqlquery := 'insert into #temp select  ROW_NUMBER() OVER(ORDER BY ' || v_orderbyfield || ') as rowNumber,(case when cont.countryName=''UNITED KINGDOM'' then ''UK'' when cont.countryName=''UNITED STATES'' then ''US'' else cont.countryName end) as countryName ,(isnull(st.stateName,''All'')) as statename,
 (isnull(ct.cityName,''All'')) as cityname , (isnull(amt.areaname,''All'')) as areaname , km.keywordname ,
 pc.CatName,isnull(grpdhm.TotaltHits,0) as  TotaltHits,isnull(grpdhm.directHits,0) as directHits,isnull((grpdhm.TotaltHits -grpdhm.directHits) ,0)as InDirectHits
 from keyword_master km left join (select aid,ctid,sid,cid ,keywordid, (sum(noofhits)) as TotaltHits, (sum(directhits)) as directHits, ((sum(noofhits))-(sum(directhits))) as InDirectHits 
 from tblnumberofhitsdaily where  cid=' || CAST(v_cid AS VARCHAR(7)) || '';
  IF (v_fromdate <> '' AND v_todate <> '') THEN
  v_sqlquery := v_sqlquery || ' and hitdate between   convert(date,''' || v_fromdate || ''',103)  and convert(date,''' || v_todate || ''',103)  ';
  END IF;
  v_sqlquery := v_sqlquery || ' and 
 sid=' || CAST(v_sid AS VARCHAR(10)) || ' and ctid=' || CAST(v_ctid AS VARCHAR(10)) || ' and aid=' || CAST(v_aid AS VARCHAR(15)) || ' group by keywordid,cid,sid,ctid, aid ) as grpdhm  
on km.kmid=grpdhm.keywordid
inner join Product_Category pc on km.catid=pc.catId
left join COUNTRY cont on cont.CID=isnull(grpdhm.cid,' || CAST(v_cid AS VARCHAR(10)) || ')
left join STATE st on st.SID=isnull(grpdhm.sid,' || CAST(v_sid AS VARCHAR(15)) || ')
left join CITY ct on ct.CTID=ISNULL(grpdhm.ctid,' || CAST(v_ctid AS VARCHAR(15)) || ')
left join area_master amt on amt.aid=ISNULL(grpdhm.aid,' || CAST(v_aid AS VARCHAR(20)) || ')
 where cont.cid>0  ';
  IF (v_searchfield = 'Keyword') THEN
  v_sqlquery := v_sqlquery || ' and km.keywordname like''%' || '' || CAST(v_searchvalue AS VARCHAR(150)) || '' || '%''';
  END IF;
  IF (v_searchfield = 'category') THEN
  v_sqlquery := v_sqlquery || ' and pc.CatName like''%' || '' || CAST(v_searchvalue AS VARCHAR(150)) || '' || '%''';
  END IF;
  EXECUTE v_sqlquery;
  SELECT COUNT(*) INTO v_recordcount FROM tmp_temp;
  RETURN QUERY SELECT * FROM tmp_temp WHERE rownumber BETWEEN v_startrowindex AND v_maxrows;
  DROP TABLE IF EXISTS tmp_temp;
  RETURN QUERY SELECT v_recordcount AS recordcount;
  -- SET option (removed)
END;
$$;


--
-- Name: usp_keywordwisetotalhits(integer, integer, character varying, character varying, character varying, integer, integer, bigint, bigint, character varying, character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_keywordwisetotalhits(v_startrowindex integer, v_maxrows integer, v_orderbyfield character varying, v_searchfield character varying, v_searchvalue character varying, v_cid integer DEFAULT 0, v_sid integer DEFAULT 0, v_ctid bigint DEFAULT 0, v_aid bigint DEFAULT 0, v_fromdate character varying DEFAULT ''::character varying, v_todate character varying DEFAULT ''::character varying) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_recordcount int;
  v_regno bigint;
  v_pmid int;
  v_sqlquery text;
BEGIN
  -- SET option (removed)
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp (rowNumber bigint,
countryName varchar(50),
stateName varchar(50),
cityName varchar(100),
areaName varchar(150),
category varchar(150),
keyword varchar(150),
directHits int,
InDirectHits int,
TotaltHits int) ON COMMIT DROP;
  IF (v_ctid > 0) THEN
  SELECT sid INTO v_sid FROM city WHERE ctid = v_ctid;
  END IF;
  v_sqlquery := '';
  IF (v_orderbyfield = '') THEN
  v_orderbyfield := 'NH.noofhits Desc';
  END IF;
  v_sqlquery := 'insert into #temp select ROW_NUMBER() OVER(ORDER BY ' || v_orderbyfield || ') as rowNumber,(case when C.countryName=''UNITED KINGDOM'' then ''UK'' when C.countryName=''UNITED STATES'' then ''US'' else C.countryName end) as countryName,isnull(S.stateName,''All'') as stateName,
 isnull(CT.cityName,''All'') as CityName,isnull(AM.areaname+''-''+AM.pincode,''All'') as areaname,CM.CatName,KM.keywordname,isnull(NH.DirectHits,0) as DirectHits ,
 (isnull(NH.noofhits,0) -isnull(NH.DirectHits,0)) as indirectHits,isnull(NH.noofhits,0) as noofhits
from keyword_master KM
left join tblnumberofhits NH on NH.keywordid =KM.kmid and NH.CID=' || CAST(v_cid AS VARCHAR(7)) || ' and  NH.sid=' || CAST(v_sid AS VARCHAR(10)) || ' 
and NH.ctid=' || CAST(v_ctid AS VARCHAR(10)) || ' and NH.aid=' || CAST(v_aid AS VARCHAR(15)) || '
join COUNTRY C on c.CID=isnull(NH.cid,' || CAST(v_cid AS VARCHAR(10)) || ')
join Product_Category CM on KM.catid=CM.catId
left join state S on S.sid=isnull(NH.sid,' || CAST(v_sid AS VARCHAR(15)) || ')
left join CITY CT on CT.CTID=isnull(NH.ctid,' || CAST(v_ctid AS VARCHAR(15)) || ')
left join area_master AM on AM.aid=isnull(NH.aid,' || CAST(v_aid AS VARCHAR(20)) || ') where KM.kmid>0 ';
  IF (v_searchfield = 'Keyword') THEN
  v_sqlquery := v_sqlquery || ' and KM.keywordname like''%' || '' || CAST(v_searchvalue AS VARCHAR(150)) || '' || '%''';
  END IF;
  IF (v_searchfield = 'category') THEN
  v_sqlquery := v_sqlquery || ' and CM.CatName like''%' || '' || CAST(v_searchvalue AS VARCHAR(150)) || '' || '%''';
  END IF;
  EXECUTE v_sqlquery;
  SELECT COUNT(*) INTO v_recordcount FROM tmp_temp;
  RETURN QUERY SELECT * FROM tmp_temp WHERE rownumber BETWEEN v_startrowindex AND v_maxrows;
  DROP TABLE IF EXISTS tmp_temp;
  RETURN QUERY SELECT v_recordcount AS recordcount;
  -- SET option (removed)
END;
$$;


--
-- Name: usp_kitboxmanagement(integer, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_kitboxmanagement(v_mode integer DEFAULT 1, v_plid integer DEFAULT 68) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_regno Int;
  v_servicetaxpercentage Decimal(10,2);
  v_count Int;
  v_totalcount Int;
  v_allfeaturelist text;
  v_kid Int;
BEGIN
  v_regno := 0;
  SELECT plid INTO v_regno FROM member_master WHERE plid = v_plid;
  -- SET option (removed)
  IF (v_mode = 1) THEN
  v_servicetaxpercentage := 0.00;
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp (RowNumber Int GENERATED BY DEFAULT AS IDENTITY,

Kid Int,

bytea text,

KitCode text,

Title text,

Amount Decimal(10,2),

ServiceTax Decimal(10,2),

PayableAmount  Decimal(10,2),

PV Decimal(10,2),

ROI INT,

NoOfMonth Int,

AllFeatureList text,

BoxColor text) ON COMMIT DROP;
  SELECT COALESCE(limits, 0) INTO v_servicetaxpercentage FROM settings WHERE caption = 'IsTaxApplicableOnPackagePrice';
  INSERT INTO tmp_temp SELECT kid, image, pcode, title, amount, ((amount * v_servicetaxpercentage) / 100), (amount + ((amount * v_servicetaxpercentage) / 100)), pv, roi, noofmonth, '', 'yellow' FROM kit_master WHERE status = 1 ORDER BY amount ASC NULLS FIRST;
  v_count := 1;
  v_totalcount := 0;
  v_allfeaturelist := '';
  v_kid := 0;
  SELECT COUNT(1) INTO v_totalcount FROM tmp_temp;
  WHILE (v_count <= v_totalcount) LOOP
  SELECT kid INTO v_kid FROM tmp_temp WHERE rownumber = v_count;
  SELECT COALESCE(v_allfeaturelist || ',', '') || featureshortexplanation INTO v_allfeaturelist FROM tbl_feature_master WHERE tfmid IN (SELECT tfmid FROM tbl_kit_featuremaster WHERE isactive = 1 AND isdeleted = 0 AND kid = v_kid) AND isactive = 1 AND isdeleted = 0;
  IF (v_allfeaturelist <> '') THEN
  v_allfeaturelist := SUBSTRING(v_allfeaturelist FROM 2 FOR LENGTH(CAST(v_allfeaturelist AS TEXT)));
  END IF;
  UPDATE tmp_temp SET allfeaturelist = v_allfeaturelist WHERE rownumber = v_count;
  v_allfeaturelist := '';
  v_count := v_count + 1;
  END LOOP;
  UPDATE tmp_temp SET boxcolor = 'green' WHERE kid IN (SELECT kid FROM tbl_incomedistribution WHERE regno = v_regno AND status = 1);
  RETURN QUERY SELECT * FROM tmp_temp ORDER BY rownumber ASC NULLS FIRST;
  DROP TABLE IF EXISTS tmp_temp;
  END IF;
  -- SET option (removed)
END;
$$;


--
-- Name: usp_kyc_approval_history(integer, bigint, bigint, character varying, integer, character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_kyc_approval_history(v_mode integer DEFAULT 2, v_id bigint DEFAULT 0, v_plid bigint DEFAULT 13, v_remark character varying DEFAULT ''::character varying, v_isapprove integer DEFAULT 1, INOUT v_stresult character varying DEFAULT ''::character varying) RETURNS character varying
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_count int;
  v_type varchar(500);
  v_image text;
  v_addresstype text;
  v_addressnumber text;
  v_accountholdername VARCHAR(500);
  v_accountno VARCHAR(300);
  v_bankname VARCHAR(500);
  v_branchname VARCHAR(500);
  v_ifsccode VARCHAR(1000);
  v_active INT;
  v_imagebank text;
  v_address text;
  v_state VARCHAR(200);
  v_city VARCHAR(500);
  v_kyctype INT;
BEGIN
  -- BEGIN TRAN (removed)
  v_count := 0;
  v_type := '';
  v_image := '';
  v_addresstype := '';
  v_addressnumber := '';
  v_accountholdername := '';
  v_accountno := '';
  v_bankname := '';
  v_branchname := '';
  v_ifsccode := '';
  v_active := 0;
  v_imagebank := '';
  v_address := '';
  v_state := '';
  v_city := '';
  SELECT type, image, addresstype, addressnumber INTO v_type, v_image, v_addresstype, v_addressnumber FROM kyc WHERE id = v_id AND regno = v_plid;
  SELECT accountholdername, accountno, bankname, branchname, ifsccode, active, cancelled_cheque_img, address, state, city, kyctype INTO v_accountholdername, v_accountno, v_bankname, v_branchname, v_ifsccode, v_active, v_imagebank, v_address, v_state, v_city, v_kyctype FROM bank_accounts_merchant WHERE plid = v_plid AND active = 1;
  IF (v_mode = 1) THEN
  INSERT INTO kyc_approval_history (regno, type, image, isaprove, commentorremark, lastupdateddate, addresstype, addressnumber) VALUES (v_plid, v_type, v_image, v_isapprove, v_remark, dbo.FUN_GETCURRENTDATE(), v_addresstype, v_addressnumber);
  v_stresult := '';
  END IF;
  IF (v_mode = 2) THEN
  INSERT INTO merchant_bank_approval_history (plid, accountholdername, accountno, bankname, branchname, ifsccode, active, last_modified_date, cancelled_cheque_img, address, state, city, kyctype, isaprove, commentorremark) VALUES (v_plid, v_accountholdername, v_accountno, v_bankname, v_branchname, v_ifsccode, v_active, dbo.FUN_GETCURRENTDATE(), v_imagebank, v_address, v_state, v_city, v_kyctype, v_isapprove, v_remark);
  v_stresult := '';
  END IF;
  -- COMMIT (removed)
END;
$$;


--
-- Name: usp_landlinerecharge_details(integer, integer, integer, character varying, character varying, integer, character varying, character varying, character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_landlinerecharge_details(v_mode integer DEFAULT 0, v_startrowindex integer DEFAULT 1, v_maxrows integer DEFAULT 100, v_fromdate character varying DEFAULT ''::character varying, v_todate character varying DEFAULT ''::character varying, v_totalcount integer DEFAULT 0, v_searchfield character varying DEFAULT ''::character varying, v_searchvalue character varying DEFAULT ''::character varying, v_status character varying DEFAULT ''::character varying) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_minindex INT;
  v_maxindex INT;
  v_query text;
BEGIN
  v_minindex := (v_startrowindex - 1) * v_maxrows + 1;
  v_maxindex := v_startrowindex * v_maxrows;
  IF (v_mode = 0) THEN
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp (ROWNUMBER BIGINT GENERATED BY DEFAULT AS IDENTITY,         
 TCPRID BIGINT,               
 CLID BIGINT,                 
 MOBILENO VARCHAR(100),         
 OPERATORTYPE VARCHAR(100),        
 RECHARGEAMOUNT DECIMAL(18,2),        
 TRANSACTIONID  VARCHAR(100),         
 RECHARGEDATE VARCHAR(100),         
 ADMINSTATUS VARCHAR(100),        
 NAME VARCHAR(100),        
 EMAILID VARCHAR(100),        
 OPERATORNAME VARCHAR(100),        
 OPERATORCODE VARCHAR(100),        
 ISANDROIDORWEB INT,        
  PaidViaCashWallet Decimal(18,8),    
PaidViaCahbackWallet Decimal(18,8),    
PaidViaKreazVoucher Int,    
PaidViaOnline Decimal(18,8)) ON COMMIT DROP;
  v_query := 'INSERT INTO #TEMP SELECT TCPR.TCLRID,TCPR.CLID,TCPR.MOBILENO,TCPR.OPERATORTYPE,        
TCPR.RECHARGEAMOUNT,TCPR.TRANSACTIONID,CAST(TCPR.RECHARGEDATE AS VARCHAR(50)) ,TCPR.RECHARGESTATUS        
,(CL.FNAME+'' ''+CL.LNAME) AS NAME,CL.EMAILID,TCPR.OPERATORNAME,TCPR.OPERATORCODE,  
TCPR.ISANDROIDORWEB,        
  ISNULL(CASHWALLETUSED,0),  
ISNULL(CASHBACKWALLETUSED,0),    
ISNULL(VOUCHERWALLETUSED,0),  
ISNULL(TBL_ONLINEPAYMENTHISTORY.AMOUNT,0)     
FROM TBL_CUSTOMER_LANDLINE_RECHARGES TCPR          
 LEFT JOIN TBL_ORDERPAYMENT_HISTORY ON TBL_ORDERPAYMENT_HISTORY.ORDERID=TCPR.TRANSACTIONID      
LEFT JOIN TBL_ORDERONLINEREQUESTS ON TBL_ORDERONLINEREQUESTS.ORDERID=TCPR.TRANSACTIONID     
LEFT JOIN TBL_ONLINEPAYMENTHISTORY ON TBL_ONLINEPAYMENTHISTORY.REFERNECID=TBL_ORDERONLINEREQUESTS.TRANSACTIONID                         
       
LEFT JOIN TBL_CUSTOMERLOGIN CL ON CL.CLID=TCPR.CLID        
       
  WHERE TCPR.RECHARGESTATUS Is Not Null';
  IF ((v_fromdate <> '') AND (v_todate = '')) THEN
  v_query := v_query || ' AND CONVERT(DATE, TCPR.RECHARGEDATE, 105) BETWEEN  CONVERT(DATE, ''' || v_fromdate || ''', 105) AND  CONVERT(DATE, DBO.FUN_GETCURRENTDATE(), 105)';
  END IF;
  IF ((v_fromdate = '') AND (v_todate <> '')) THEN
  v_query := v_query || 'AND CONVERT(DATE, TCPR.RECHARGEDATE, 105) BETWEEN  CONVERT(DATE, ''' || v_todate || ''', 105) AND  CONVERT(DATE, DBO.FUN_GETCURRENTDATE(), 105)';
  END IF;
  IF ((v_fromdate <> '') AND (v_todate <> '')) THEN
  v_query := v_query || 'AND CONVERT(DATE, TCPR.RECHARGEDATE, 105) BETWEEN CONVERT(DATE, ''' || v_fromdate || ''', 105) AND  CONVERT(DATE, ''' || v_todate || ''', 105)';
  END IF;
  IF (v_searchfield = 'NAME') THEN
  v_query := v_query || ' AND (CL.FNAME+CL.LNAME) LIKE ''%' || v_searchvalue || '%'' ';
  END IF;
  IF (v_searchfield = 'PHONE') THEN
  v_query := v_query || ' AND TCPR.MOBILENO LIKE ''%' || v_searchvalue || '%'' ';
  END IF;
  IF (v_searchfield = 'EMAILID') THEN
  v_query := v_query || ' AND CL.EMAILID LIKE ''%' || v_searchvalue || '%'' ';
  END IF;
  IF (v_searchfield = 'TRANSACTIONID') THEN
  v_query := v_query || ' AND TCPR.TRANSACTIONID LIKE ''%' || v_searchvalue || '%'' ';
  END IF;
  IF (v_status <> '') THEN
  v_query := v_query || ' AND TCPR.RECHARGESTATUS =''' || v_status || ''' ';
  END IF;
  v_query := v_query || ' ORDER BY TCPR.RECHARGEDATE DESC';
  EXECUTE v_query;
  RETURN QUERY SELECT rownumber, tcprid, clid, mobileno, operatortype, rechargeamount, transactionid, rechargedate, adminstatus, name, emailid, operatorname, operatorcode, isandroidorweb, paidviacashwallet, paidviacahbackwallet, paidviakreazvoucher, paidviaonline FROM tmp_temp WHERE rownumber BETWEEN v_minindex AND v_maxindex ORDER BY rownumber ASC NULLS FIRST;
  SELECT COUNT(rownumber) INTO v_totalcount FROM tmp_temp;
  DROP TABLE IF EXISTS tmp_temp;
  -- SET option (removed)
  END IF;
END;
$$;


--
-- Name: usp_lastlogin(integer, integer, integer, integer, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_lastlogin(v_mode integer DEFAULT 0, v_pmid integer DEFAULT 0, v_reg integer DEFAULT 0, v_vid integer DEFAULT 0, INOUT v_intresult integer DEFAULT NULL::integer) RETURNS integer
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_format_time timestamp;
BEGIN
  v_intresult := 1;
  SELECT CAST(TO_CHAR(dbo.fun_getCurrentDate(), 'TMMon DD YYYY FMHH12:MI%p') AS VARCHAR(30)) INTO v_format_time;
  IF (v_mode = 1) THEN
  v_intresult := 3;
  END IF;
  IF (v_mode = 2) THEN
  UPDATE portal_login SET lastlogin = v_format_time WHERE plid = v_pmid;
  v_intresult := 4;
  END IF;
  IF (v_mode = 3) THEN
  UPDATE visitor_login SET lastlogin = v_format_time WHERE vid = v_vid;
  v_intresult := 5;
  END IF;
  IF (0 <> 0) THEN
  v_intresult := 0;
  RETURN;
  END IF;
END;
$$;


--
-- Name: usp_latestblogbind(); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_latestblogbind() RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_blogid Int;
  v_totalcomment Int;
BEGIN
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp (CANONICALURL text,

BLOGID text,

BLOGTITLE  text,

BLOGDESCRIPTION  text,

PostedBy text,

Month  text,

Date  text,

TotalComment text) ON COMMIT DROP;
  INSERT INTO tmp_temp SELECT canonicalurl, bm.blogid, (UPPER(LEFT(CAST(bm.blogtitle AS TEXT), 1)) || LOWER(SUBSTRING(bm.blogtitle FROM 2 FOR LENGTH(CAST(bm.blogtitle AS TEXT))))) AS blogtitle, bm.blogdescription, (UPPER(LEFT(CAST(bm.blogwriter AS TEXT), 1)) || LOWER(SUBSTRING(bm.blogwriter FROM 2 FOR LENGTH(CAST(bm.blogwriter AS TEXT))))) AS blogwriter, CAST(TO_CHAR(CURRENT_TIMESTAMP, 'TMMon DD YYYY FMHH12:MI%p') AS CHAR(3)), CAST(EXTRACT(MONTH FROM CURRENT_TIMESTAMP) AS VARCHAR(3)), 0 FROM tbl_blogmaster AS bm LEFT JOIN (SELECT blogid, COALESCE(SUM(stars), 0) / COUNT(rwid) AS avg FROM tbl_blogreviewmaster GROUP BY blogid) AS br ON bm.blogid = br.blogid WHERE bm.status = 1 AND bm.publishstatus = 1 ORDER BY bm.blogid DESC NULLS LAST LIMIT 1;
  v_blogid := 0;
  v_totalcomment := 0;
  SELECT blogid INTO v_blogid FROM tmp_temp;
  SELECT COUNT(1) INTO v_totalcomment FROM tbl_blogreviewmaster WHERE blogid = v_blogid;
  UPDATE tmp_temp SET totalcomment = v_totalcomment;
  RETURN QUERY SELECT * FROM tmp_temp;
END;
$$;


--
-- Name: usp_latitude(bigint, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_latitude(v_maxpmid bigint DEFAULT 0, v_intresult integer DEFAULT NULL::integer) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
BEGIN
  v_intresult := 0;
  IF EXISTS(SELECT pmtid FROM portal_master WHERE pmid = v_maxpmid) THEN
  RETURN QUERY SELECT (p.areaname) AS areaname, (c.cityname || ' ' || p.areaname) AS address, (p.companyname || ' ' || p.address || ' ' || p.areaname || ' ' || c.cityname || ' ' || s.statename || ' ' || coun.countryname) AS description, (c.cityname) AS cityname, (s.statename) AS statename, (coun.countryname) AS countryname FROM portal_master AS p INNER JOIN city AS c ON p.ctid = c.ctid INNER JOIN state AS s ON c.sid = s.sid INNER JOIN country AS coun ON s.cid = coun.cid WHERE p.pmid = v_maxpmid AND p.active = 1;
  v_intresult := 1;
  END IF;
END;
$$;


--
-- Name: usp_level_income(character varying, bigint, integer, integer, character varying, character varying, character varying, character varying, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_level_income(v_loginid character varying DEFAULT ''::character varying, v_regno bigint DEFAULT NULL::bigint, v_startrowindex integer DEFAULT 1, v_maxrows integer DEFAULT 10, v_searchfield character varying DEFAULT ''::character varying, v_searchvalue character varying DEFAULT ''::character varying, v_fromdate character varying DEFAULT ''::character varying, v_todate character varying DEFAULT ''::character varying, v_totalcount integer DEFAULT 0) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_minindex int;
  v_maxindex int;
  v_query text;
BEGIN
  v_minindex := (v_startrowindex - 1) * v_maxrows + 1;
  v_maxindex := v_startrowindex * v_maxrows;
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp (rownumber bigint,
regNo bigint,
LoginId varchar(100),
date varchar(200),
userName varchar(100),
Income decimal(18,8),
Amount decimal(18,8),
Remark text,
status int) ON COMMIT DROP;
  v_query := 'insert into #temp  select ROW_NUMBER() OVER(ORDER BY li.date desc) AS rowNumber,mm.regNo,mm.loginId,convert (varchar(20),li.date,105) as date,mm.userName ,li.Income,li.Amount,li.Remark,
li.status 
from Level_Income li
inner join member_master mm 
on li.regNo=mm.regNo where  li.status=0';
  IF (COALESCE(v_regno, 0) > 0) THEN
  v_query := v_query || 'and mm.regNo= ' || CAST(v_regno AS VARCHAR(50));
  END IF;
  IF ((v_fromdate <> '') AND (v_todate = '')) THEN
  v_query := v_query || ' and convert(date,li.date,105) between  CONVERT(date, ''' || v_fromdate || ''', 105) and  CONVERT(date, dbo.fun_getCurrentDate(), 105)';
  END IF;
  IF ((v_fromdate = '') AND (v_todate <> '')) THEN
  RETURN QUERY SELECT 1;
  v_query := v_query || ' and convert(date,li.date,105) between  CONVERT(date, ''' || v_todate || ''', 105) and  CONVERT(date, ''' || v_todate || ''', 105)';
  END IF;
  IF ((v_fromdate <> '') AND (v_todate <> '')) THEN
  v_query := v_query || ' and convert(date, li.date,105) between  CONVERT(date, ''' || v_fromdate || ''', 105) and  CONVERT(date, ''' || v_todate || ''', 105)';
  END IF;
  EXECUTE v_query;
  RETURN QUERY SELECT * FROM tmp_temp WHERE rownumber BETWEEN v_minindex AND v_maxindex;
  SELECT COUNT(rownumber) INTO v_totalcount FROM tmp_temp;
  DROP TABLE IF EXISTS tmp_temp;
  -- SET option (removed)
END;
$$;


--
-- Name: usp_level_income_slab(integer, integer, numeric); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_level_income_slab(v_mode integer DEFAULT 1, v_intresult integer DEFAULT 0, v_totalincomepercent numeric DEFAULT 0) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
BEGIN
  -- SET option (removed)
  IF (v_mode = 1) THEN
  RETURN QUERY SELECT ROW_NUMBER() OVER (ORDER BY lisid NULLS FIRST) AS rownumber, * FROM level_income_slab;
  RETURN QUERY SELECT SUM(income) AS totalincome FROM level_income_slab;
  SELECT SUM(income) INTO v_totalincomepercent FROM level_income_slab;
  END IF;
  IF (v_mode = 2) THEN
  RETURN QUERY SELECT ROW_NUMBER() OVER (ORDER BY tlisid NULLS FIRST) AS rownumber, * FROM task_level_income_slab;
  RETURN QUERY SELECT SUM(income) AS totalincome FROM task_level_income_slab;
  END IF;
  -- SET option (removed)
  IF (0 <> 0) THEN
  v_intresult := 0;
  RETURN;
  END IF;
END;
$$;


--
-- Name: usp_level_income_slab_master(integer, numeric, integer, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_level_income_slab_master(v_mode integer, v_income numeric, v_lisid integer, INOUT v_intresult integer) RETURNS integer
    LANGUAGE plpgsql
    AS $$
