--
-- Name: usp_locationinfo(integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_locationinfo(v_pmid integer DEFAULT 3) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
BEGIN
  RETURN QUERY SELECT COALESCE(areaname, 'N/A') AS areaname, COALESCE(cityname, 'N/A') AS cityname, COALESCE(longitude, 'N/A') AS longitude, COALESCE(latitude, 'N/A') AS latitude, COALESCE(discription, 'N/A') AS discription FROM locations WHERE pmid = v_pmid;
END;
$$;


--
-- Name: usp_log(integer, integer, integer, integer, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_log(v_cid integer DEFAULT 0, v_sid integer DEFAULT 0, v_ctid integer DEFAULT 0, v_active integer DEFAULT 0, INOUT v_intresult integer DEFAULT NULL::integer) RETURNS integer
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_count int;
BEGIN
  SELECT COUNT(*) INTO v_count FROM most_popularcity WHERE ctid = v_ctid AND sid = v_sid AND cid = v_cid;
  IF (v_count >= 1) THEN
  SELECT count INTO v_count FROM most_popularcity WHERE ctid = v_ctid;
  v_count := v_count + 1;
  UPDATE most_popularcity SET count = v_count WHERE ctid = v_ctid;
  v_intresult := 1;
  ELSE
  INSERT INTO most_popularcity VALUES (v_cid, v_sid, v_ctid, 1, v_active);
  v_intresult := 1;
  END IF;
  IF (0 <> 0) THEN
  v_intresult := 0;
  END IF;
END;
$$;


--
-- Name: usp_logincheck(text, text, character varying, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_logincheck(v_userid text, v_userpass text, INOUT v_strresult character varying, INOUT v_slid integer) RETURNS record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_active int;
BEGIN
  v_strresult := '';
  IF EXISTS(SELECT 1 FROM sponsor_login WHERE loginid = v_userid AND password = v_userpass) THEN
  SELECT active INTO v_active FROM sponsor_login WHERE loginid = v_userid AND password = v_userpass;
  IF (v_active = 0) THEN
  v_slid := 0;
  v_strresult := 'Your account is not active. Please active your account from the verification mail that we sent you on your registered email ID.';
  RETURN;
  ELSE
  IF (v_active = 2) THEN
  v_slid := 0;
  v_strresult := 'Your account has been deactivated by admin. For more details, please contact to our admin department.';
  RETURN;
  ELSE
  SELECT slid INTO v_slid FROM sponsor_login WHERE loginid = v_userid AND password = v_userpass;
  IF (v_active = 1) THEN
  v_strresult := 'Active User';
  END IF;
  RETURN;
  END IF;
  END IF;
  ELSE
  v_slid := 0;
  v_strresult := 'Invalid user id or password';
  RETURN;
  END IF;
END;
$$;


--
-- Name: usp_logindetails(integer, integer, character varying, boolean, character varying, character varying, character varying, character varying, integer, integer, character varying, character varying, text, character varying, character varying, character varying, integer, integer, character varying, integer, integer, integer, character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_logindetails(v_startrowindex integer DEFAULT 1, v_maxrows integer DEFAULT 1000, v_orderbyfield character varying DEFAULT ''::character varying, v_asc boolean DEFAULT false, v_searchfield character varying DEFAULT ''::character varying, v_searchvalue character varying DEFAULT ''::character varying, v_fromdate character varying DEFAULT ''::character varying, v_todate character varying DEFAULT ''::character varying, v_mode integer DEFAULT 0, v_recordcount integer DEFAULT 0, v_cid character varying DEFAULT ''::character varying, v_accnttype character varying DEFAULT ''::character varying, v_usertype text DEFAULT ''::text, v_eggagetypes character varying DEFAULT ''::character varying, v_orderby character varying DEFAULT ''::character varying, v_mobile character varying DEFAULT ''::character varying, v_isdownload integer DEFAULT 0, v_userid integer DEFAULT 0, v_qualification character varying DEFAULT ''::character varying, v_gender integer DEFAULT 0, v_did integer DEFAULT 0, v_balance integer DEFAULT 0, v_kycstatus character varying DEFAULT ''::character varying) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_sqlquery text;
  v_minindex INT;
  v_maxindex INT;
  v_newusername varchar(200);
BEGIN
  -- SET option (removed)
  DROP TABLE IF EXISTS tmp_temp66;
  CREATE TEMP TABLE tmp_temp66 (ROWNUMBER BIGINT GENERATED BY DEFAULT AS IDENTITY,
REFRAL_ID VARCHAR(150),
LOGINID VARCHAR(150),
USERNAME VARCHAR(150),
NAME VARCHAR(150),
PHONE VARCHAR(150),
PLID BIGINT,
DOC VARCHAR(200),
ACCOUNTTYPE VARCHAR(50),
COUNTRY VARCHAR(100),
JOINEDVIA text,
STATUS VARCHAR(100),
IPADDRESS VARCHAR(100),
ENGAGEDIN VARCHAR(50),
ENGTOOLTIP VARCHAR(100),
FULLNAME VARCHAR(500),
Emailid varchar(100),
Reference_Username varchar(100),
DID INT,
clid bigint,
ISKYCAPPROVED INT,
Orderamount decimal(18,2),
URL VARCHAR(500),
ResellerName varchar(250),
Account varchar(250),
Active Int,
COMPANYURL VARCHAR(100),
Resellerid Varchar(100)) ON COMMIT DROP;
  v_sqlquery := '';
  v_minindex := (v_startrowindex - 1) * v_maxrows + 1;
  v_maxindex := v_startrowindex * v_maxrows;
  v_sqlquery := 'INSERT INTO #TEMP66 SELECT ISNULL(PL2.USERNAME,''-'') AS REFRAL_ID,PL1.LOGINID,
   ISNULL(PL1.USERNAME,''-'') AS USERNAME,ISNULL(PL1.ISSOCIALLOGIN,'''') AS NAME,
   isnull(PL1.PHONE,'''') as PHONE,PL1.CLID,  FORMAT(PL1.DOC,''dd-MMM-yyyy hh:mm:ss tt'')  AS DOC, CASE ISNULL(PL1.QPAYREGNO,0) WHEN 0 THEN ''QLOOK'' ELSE ''QPAY'' END AS ACCOUNTTYPE,
   (CASE WHEN C.COUNTRYNAME=''UNITED STATES'' THEN ''US'' WHEN C.COUNTRYNAME=''UNITED KINGDOM'' THEN ''UK'' ELSE  C.COUNTRYNAME END  ) AS COUNTRYNAME,
    (Case When PL1.IPADDRESS=''By Admin'' Then ''Admin'' When isnull(PL1.SpounserType,0)=0 Then ''Direct'' When PL1.SpounserType=2 Then ''Member Referrals'' When PL1.SpounserType=1 Then ''Customer Referrals'' END) As JoinedVia,
	--(Case When PL1.IPADDRESS=''By Admin'' Then ''Admin'' When PL1.INTRO_REFID=0 Then ''Direct'' When PL1.INTRO_REFID>0 Then ''Customer Referrals'' END) As JoinedVia,
   (CASE PL1.ACTIVE WHEN 1 THEN ''Active'' WHEN 0 THEN ''Deactive'' END)AS STATUS,ISNULL(PL1.IPADDRESS,''-'') AS IPADDRESS,
   CASE WHEN (ISNULL(PL1.PMID,0)=0 AND ISNULL(PL1.INTRO_PLID,0)=0 AND ISNULL(SMD.SMDID,0)=0) THEN ''None'' 
   WHEN (ISNULL(PL1.PMID,0)<>0 AND ISNULL(PL1.INTRO_PLID,0)=0 AND ISNULL(SMD.SMDID,0)=0) THEN ''BL'' 
   WHEN (ISNULL(PL1.PMID,0)=0 AND ISNULL(PL1.INTRO_PLID,0)<>0 AND ISNULL(SMD.SMDID,0)=0) THEN ''RP'' 
   WHEN (ISNULL(PL1.PMID,0)=0 AND ISNULL(PL1.INTRO_PLID,0)=0 AND ISNULL(SMD.SMDID,0)<>0) THEN ''PPC''
   WHEN (ISNULL(PL1.PMID,0)<>0 AND ISNULL(PL1.INTRO_PLID,0)<>0 AND ISNULL(SMD.SMDID,0)=0) THEN ''BL, RP''
   WHEN (ISNULL(PL1.PMID,0)<>0 AND ISNULL(PL1.INTRO_PLID,0)=0 AND ISNULL(SMD.SMDID,0)<>0) THEN ''BL, PPC''
   WHEN (ISNULL(PL1.PMID,0)=0 AND ISNULL(PL1.INTRO_PLID,0)<>0 AND ISNULL(SMD.SMDID,0)<>0) THEN ''RP, PPC''
   WHEN (ISNULL(PL1.PMID,0)<>0 AND ISNULL(PL1.INTRO_PLID,0)<>0 AND ISNULL(SMD.SMDID,0)<>0) THEN ''BL, RP, PPC'' END AS ENGAGEDIN,
   CASE WHEN (ISNULL(PL1.PMID,0)=0 AND ISNULL(PL1.INTRO_PLID,0)=0 AND ISNULL(SMD.SMDID,0)=0) THEN ''None'' 
   WHEN (ISNULL(PL1.PMID,0)<>0 AND ISNULL(PL1.INTRO_PLID,0)=0 AND ISNULL(SMD.SMDID,0)=0) THEN ''Bussiness Listing'' 
   WHEN (ISNULL(PL1.PMID,0)=0 AND ISNULL(PL1.INTRO_PLID,0)<>0 AND ISNULL(SMD.SMDID,0)=0) THEN ''Referral Program'' 
   WHEN (ISNULL(PL1.PMID,0)=0 AND ISNULL(PL1.INTRO_PLID,0)=0 AND ISNULL(SMD.SMDID,0)<>0) THEN ''Pay Per Click''
   WHEN (ISNULL(PL1.PMID,0)<>0 AND ISNULL(PL1.INTRO_PLID,0)<>0 AND ISNULL(SMD.SMDID,0)=0) THEN ''Bussiness Listing, Referral Program''
   WHEN (ISNULL(PL1.PMID,0)<>0 AND ISNULL(PL1.INTRO_PLID,0)=0 AND ISNULL(SMD.SMDID,0)<>0) THEN ''Bussiness Listing, Pay Per Click''
  WHEN (ISNULL(PL1.PMID,0)=0 AND ISNULL(PL1.INTRO_PLID,0)<>0 AND ISNULL(SMD.SMDID,0)<>0) THEN ''Referral Program, Pay Per Click''
   WHEN (ISNULL(PL1.PMID,0)<>0 AND ISNULL(PL1.INTRO_PLID,'''')<>0 AND ISNULL(SMD.SMDID,0)<>0) THEN ''Bussiness Listing, Referral Program, Pay Per Click'' end as engtooltip,
   ISNULL(PL1.FNAME,'''') +'' ''+ISNULL(PL1.LNAME,'''') AS NAME,PL1.EMAILID,ISNULL(PL1.Reference_Username,'''') AS Reference_Username,
   ISNULL(PL1.DID,0) AS DID,pl1.clid,
   ISNULL(PL1.ISKYCAPPROVED,0) AS ISKYCAPPROVED,
  isnull((select sum(Total_Purchase_Cost) from tbl_product_order_master where loginid=PL1.loginid and intstatus=6),0) as Orderamount,
   (CASE WHEN PL1.DID>1 THEN DM.URL  ELSE  '''' END) AS URL,isnull(DM.COMPANYNAME,'''') as ResellerName,
  (CASE WHEN PL1.DID>1 THEN ''Affiliate'' WHEN PL1.ISSOCIALLOGIN=1 THEN ''Facebook'' WHEN PL1.ISSOCIALLOGIN=2 THEN ''Google+'' ELSE  ''Direct'' END  ) AS Account,PL1.ACTIVE,
  ISNULL(TCM.Companyredirect,'''') ,ISNULL(TD.LOGINID,'''')
   FROM TBL_CUSTOMERLOGIN PL1 LEFT JOIN PORTAL_MASTER PM ON PM.PMID=ISNULL(PL1.PMID,0)
   LEFT JOIN TBL_DISTRIBUTOR TD ON TD.DID=PL1.DID
   LEFT JOIN Distributor_MASTER DM ON DM.PMID=TD.PMID
   LEFT JOIN SPONSOR_MASTER_DETAIL SMD ON SMD.PLID=PL1.CLID
   LEFT JOIN TBL_CUSTOMERLOGIN PL2 ON PL2.CLID=PL1.INTRO_REFID JOIN
   COUNTRY C ON C.CID=PL1.CID LEFT JOIN MEMBER_MASTER MM ON MM.PLID=PL1.CLID 
   LEFT JOIN  TBL_COMPANYSETTINGS TCM ON TD.DID= TCM.PMID
   WHERE PL1.ACTIVE>=0 ';
  IF (v_fromdate = '' OR v_todate = '') THEN
  IF (v_fromdate <> '') THEN
  v_sqlquery := v_sqlquery || ' AND CONVERT(DATE, PL1.DOC,103) >= REPLACE(CONVERT(DATE,''' || v_fromdate || ''',103),''/'',''-'') ';
  END IF;
  IF (v_todate <> '') THEN
  v_sqlquery := v_sqlquery || ' AND CONVERT(DATE, PL1.DOC,103)  <=REPLACE(CONVERT(DATE,''' || v_todate || ''',103),''/'',''-'') ';
  END IF;
  END IF;
  IF (v_fromdate <> '' AND v_todate <> '') THEN
  v_sqlquery := v_sqlquery || '  AND  CONVERT(DATE, PL1.DOC,103)  BETWEEN  REPLACE(CONVERT(DATE,''' || v_fromdate || ''',103),''/'',''-'')  AND REPLACE(CONVERT(DATE,''' || v_todate || ''',103),''/'',''-'')';
  END IF;
  IF (v_mobile <> '') THEN
  v_sqlquery := v_sqlquery || (' AND PL1.PHONE =''' || v_mobile || ''' ');
  END IF;
  IF (v_searchfield = 'Emailid') THEN
  v_sqlquery := v_sqlquery || ' AND PL1.Emailid LIKE ''%' || v_searchvalue || '%'' ';
  END IF;
  IF (v_searchfield = 'NAME') THEN
  v_sqlquery := v_sqlquery || ' AND (PL1.FNAME+PL1.LNAME) LIKE ''%' || v_searchvalue || '%'' ';
  END IF;
  IF (v_searchfield = 'PHONE') THEN
  v_sqlquery := v_sqlquery || ' AND PL1.PHONE LIKE ''%' || v_searchvalue || '%'' ';
  END IF;
  IF (v_searchfield = 'SourceID') THEN
  v_sqlquery := v_sqlquery || ' AND PL1.LOGINID LIKE ''%' || v_searchvalue || '%'' ';
  END IF;
  IF (v_searchfield = 'LOGINID') THEN
  v_sqlquery := v_sqlquery || ' AND PL1.LOGINID LIKE ''%' || v_searchvalue || '%'' ';
  END IF;
  IF (v_searchfield = 'REFERAL') THEN
  v_sqlquery := v_sqlquery || ' AND PL2.LOGINID LIKE ''%' || v_searchvalue || '%'' ';
  END IF;
  IF (v_searchfield = 'USERNAME') THEN
  IF (EXISTS(SELECT 1 FROM portal_login WHERE username = v_searchvalue)) THEN
  v_sqlquery := v_sqlquery || (' AND PL1.USERNAME LIKE ''%' || v_searchvalue || '%''');
  ELSE
  IF (EXISTS(SELECT 1 FROM portal_login_history WHERE username = v_searchvalue)) THEN
  v_newusername := '';
  SELECT (SELECT username FROM portal_login WHERE plid IN (SELECT plid FROM portal_login_history WHERE username = v_searchvalue)) INTO v_newusername;
  v_sqlquery := v_sqlquery || (' AND PL1.USERNAME LIKE ''%' || v_newusername || '%''');
  ELSE
  v_sqlquery := v_sqlquery || ' AND PL1.USERNAME LIKE ''%' || v_searchvalue || '%'' ';
  END IF;
  END IF;
  END IF;
  IF (v_did > 0) THEN
  v_sqlquery := v_sqlquery || ' AND PL1.DID=' || CAST(v_did AS VARCHAR(20)) || '';
  END IF;
  IF (v_kycstatus <> '') THEN
  v_sqlquery := v_sqlquery || ' AND PL1.ISKYCAPPROVED=' || CAST(v_kycstatus AS VARCHAR(20)) || '';
  END IF;
  IF (v_balance = 2) THEN
  v_sqlquery := v_sqlquery || ' ORDER BY ORDERAMOUNT DESC';
  END IF;
  IF (v_balance = 1) THEN
  v_sqlquery := v_sqlquery || ' ORDER BY ORDERAMOUNT ASC';
  END IF;
  IF (v_orderby = 'DESC') THEN
  v_sqlquery := v_sqlquery || ('  ORDER BY PL1.DOC ' || v_orderby || ' ');
  END IF;
  IF (v_orderby = 'ASC') THEN
  v_sqlquery := v_sqlquery || ('  ORDER BY PL1.DOC ' || v_orderby || '  ');
  END IF;
  EXECUTE v_sqlquery;
  RAISE NOTICE '%', v_sqlquery;
  IF (v_accnttype <> '') THEN
  RETURN QUERY SELECT * FROM tmp_temp66 WHERE account = v_accnttype ORDER BY rownumber ASC NULLS FIRST;
  ELSE
  RETURN QUERY SELECT * FROM tmp_temp66 WHERE rownumber BETWEEN v_minindex AND v_maxindex ORDER BY rownumber ASC NULLS FIRST;
  END IF;
  SELECT COUNT(rownumber) INTO v_recordcount FROM tmp_temp66;
  SELECT COUNT(1) INTO v_recordcount FROM tmp_temp66;
  IF (v_isdownload = 0) THEN
  RETURN QUERY SELECT * FROM tmp_temp66 WHERE rownumber BETWEEN v_startrowindex AND v_maxrows;
  ELSE
  RETURN QUERY SELECT rownumber AS "s.no.", TO_DATE(doc, 'DD TMMon YYYY') AS "reg.date", username AS "user name", loginid AS "email id", fullname AS name, ipaddress AS ip, joinedvia AS "joined via", status AS status, engagedin AS "engagged in" FROM tmp_temp66;
  INSERT INTO tbl_exceltrackingreport (report_name, file_name, type, download_by, download_date) VALUES ('All Member', 'AllMember-List.xls', 1, v_userid, CURRENT_TIMESTAMP);
  END IF;
  DROP TABLE IF EXISTS tmp_temp66;
  -- SET option (removed)
END;
$$;


--
-- Name: usp_loginportal_dealmaster(integer, integer, integer, integer, integer, character varying, character varying, character varying, character varying, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_loginportal_dealmaster(v_startrowindex integer, v_maxrows integer, v_cid integer, v_status integer, v_verify integer, v_fromdate character varying, v_todate character varying, v_searchfield character varying, v_searchvalue character varying, v_recordcount integer) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_sqlquery text;
BEGIN
  -- SET option (removed)
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp (rowNumber int,
dealid bigint,
pmid bigint,
loginid varchar(200),
dealtitle varchar(300),
exptime varchar(10),
country varchar(50),
activestatus varchar(30),
verifystatus varchar(30)) ON COMMIT DROP;
  v_sqlquery := '';
  v_sqlquery := 'insert into #temp select ROW_NUMBER() over (order by pdm.fromtime) as rowNumber,pdm.dealid, pl.PMID,pl.LoginId,pdm.title, exptime=convert(varchar(10),
 pdm.totime,105),cn.countryName,  case pdm.active when 1 then ''Active'' when 0 then ''Deactive'' else ''Inactive'' end as active,
case pdm.verify when 1 then ''V'' when 0 then ''U'' else ''U'' end as verify from 
Portal_Login pl inner join portal_deal_master pdm on pl.PMID=pdm.pmid inner join COUNTRY cn on cn.CID=pl.cid';
  IF (v_cid <> '') THEN
  v_sqlquery := v_sqlquery || (' and ('',''+convert(varchar(50),pl.cid)+'','') like  ''%,' || '' || CAST(v_cid AS text) || '' || ',%''');
  END IF;
  IF (v_fromdate = '' OR v_todate = '') THEN
  IF (v_fromdate <> '') THEN
  v_sqlquery := v_sqlquery || ' and convert(varchar(10), pdm.fromtime,103) = convert(varchar(10),''' || v_fromdate || ''',103) ';
  END IF;
  IF (v_todate <> '') THEN
  v_sqlquery := v_sqlquery || ' and convert(date, pdm.totime,103)  =convert(date,''' || v_todate || ''',103) ';
  END IF;
  END IF;
  IF (v_fromdate <> '' AND v_todate <> '') THEN
  v_sqlquery := v_sqlquery || ' and convert(date, fromtime,103)  between  convert(date,''' || v_fromdate || ''',103)  and convert(date,''' || v_todate || ''',103)';
  END IF;
  IF (v_searchfield = 'loginid') THEN
  v_sqlquery := v_sqlquery || ' and pl.loginid like ''%' || v_searchvalue || '%''';
  END IF;
  IF (v_searchfield = 'title') THEN
  v_sqlquery := v_sqlquery || ' and pdm.title like ''%' || v_searchvalue || '%''';
  END IF;
  EXECUTE v_sqlquery;
  SELECT COUNT(*) INTO v_recordcount FROM tmp_temp;
  RETURN QUERY SELECT * FROM tmp_temp WHERE rownumber BETWEEN v_startrowindex AND v_maxrows;
  IF (0 <> 0) THEN
  v_recordcount := 0;
  END IF;
  DROP TABLE IF EXISTS tmp_temp;
  RETURN QUERY SELECT v_recordcount AS recordcount;
  -- SET option (removed)
END;
$$;


--
-- Name: usp_logistic_partners(integer, integer, character varying, character varying, character varying, character varying, character varying, character varying, character varying, character varying, character varying, character varying, character varying, character varying, integer, character varying, character varying, character varying, character varying, character varying, character varying, character varying, character varying, character varying, character varying, integer, integer, integer, character varying, character varying, character varying, character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_logistic_partners(v_tlpid integer DEFAULT 0, v_mode integer DEFAULT 2, v_name character varying DEFAULT ''::character varying, v_emailid character varying DEFAULT ''::character varying, v_contactperson character varying DEFAULT ''::character varying, v_contactpersonmobile character varying DEFAULT ''::character varying, v_phone character varying DEFAULT ''::character varying, v_gstin character varying DEFAULT ''::character varying, v_pan character varying DEFAULT ''::character varying, v_region character varying DEFAULT ''::character varying, v_state character varying DEFAULT ''::character varying, v_city character varying DEFAULT ''::character varying, v_pincode character varying DEFAULT ''::character varying, v_address character varying DEFAULT ''::character varying, v_active integer DEFAULT 0, v_accountholdername character varying DEFAULT ' '::character varying, v_accountno character varying DEFAULT ''::character varying, v_ifsccode character varying DEFAULT ''::character varying, v_bankname character varying DEFAULT ''::character varying, v_branchname character varying DEFAULT ''::character varying, v_bankaddress character varying DEFAULT ''::character varying, v_bank_state character varying DEFAULT ''::character varying, v_bank_city character varying DEFAULT ''::character varying, v_bank_image character varying DEFAULT ''::character varying, v_strresult character varying DEFAULT ''::character varying, v_totalcount integer DEFAULT 0, v_startrowindex integer DEFAULT 1, v_maxrows integer DEFAULT 10, v_searchfield character varying DEFAULT ''::character varying, v_searchvalue character varying DEFAULT ''::character varying, v_fromdate character varying DEFAULT ''::character varying, v_todate character varying DEFAULT ''::character varying) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_minindex int;
  v_maxindex int;
  v_query text;
BEGIN
  -- BEGIN TRAN (removed)
  v_minindex := (v_startrowindex - 1) * v_maxrows + 1;
  v_maxindex := v_startrowindex * v_maxrows;
  IF (v_mode = 1) THEN
  IF (LENGTH(CAST(v_pincode AS TEXT)) < 6) THEN
  v_strresult := 'Enter Valid Pincode ';
  RAISE NOTICE '%', v_strresult;
  -- COMMIT (removed)
  RETURN;
  END IF;
  IF EXISTS(SELECT 1 FROM tbl_logisticpartners WHERE panno = v_pan AND tlpid <> v_tlpid) THEN
  v_strresult := 'PAN Number Already Exist';
  RAISE NOTICE '%', v_strresult;
  -- COMMIT (removed)
  RETURN;
  END IF;
  IF EXISTS(SELECT 1 FROM tbl_logisticpartners WHERE gstin = v_gstin AND tlpid <> v_tlpid) THEN
  v_strresult := 'GSTIN Number Already Exist';
  RAISE NOTICE '%', v_strresult;
  -- COMMIT (removed)
  RETURN;
  END IF;
  IF EXISTS(SELECT 1 FROM tbl_logisticpartners WHERE name = v_name AND tlpid <> v_tlpid) THEN
  v_strresult := 'Name Already Exist';
  RAISE NOTICE '%', v_strresult;
  -- COMMIT (removed)
  RETURN;
  END IF;
  IF EXISTS(SELECT 1 FROM tbl_logisticpartners WHERE emailid = v_emailid AND tlpid <> v_tlpid) THEN
  v_strresult := 'Email-Id Already Exist';
  RAISE NOTICE '%', v_strresult;
  -- COMMIT (removed)
  RETURN;
  END IF;
  IF EXISTS(SELECT 1 FROM tbl_logisticpartners WHERE phone = v_phone AND tlpid <> v_tlpid) THEN
  v_strresult := 'Phone Already Exist';
  RAISE NOTICE '%', v_strresult;
  -- COMMIT (removed)
  RETURN;
  END IF;
  IF EXISTS(SELECT 1 FROM tbl_logisticpartners WHERE contactpersonname = v_contactperson AND tlpid <> v_tlpid) THEN
  v_strresult := 'Contact Person Name Already Exist';
  RAISE NOTICE '%', v_strresult;
  -- COMMIT (removed)
  RETURN;
  END IF;
  IF EXISTS(SELECT 1 FROM tbl_logisticpartners WHERE contactpersonmobile = v_contactpersonmobile AND tlpid <> v_tlpid) THEN
  v_strresult := 'Contact Person Mobile Already Exist';
  RAISE NOTICE '%', v_strresult;
  -- COMMIT (removed)
  RETURN;
  END IF;
  IF NOT EXISTS(SELECT 1 FROM tbl_logisticpartners WHERE tlpid = v_tlpid) THEN
  RAISE NOTICE '%', 'a';
  INSERT INTO tbl_logisticpartners (name, emailid, phone, address, contactpersonname, contactpersonmobile, gstin, panno, city, state, region, pincode, accountholdername, accountno, ifsccode, bankname, branchname, bankaddress, bankstate, bankcity, cancelledchequeimage, createddate, active) VALUES (v_name, v_emailid, v_phone, v_address, v_contactperson, v_contactpersonmobile, v_gstin, v_pan, v_city, v_state, v_region, v_pincode, v_accountholdername, v_accountno, v_ifsccode, v_bankname, v_branchname, v_bankaddress, v_bank_state, v_bank_city, v_bank_image, CURRENT_TIMESTAMP, v_active);
  v_strresult := 'Inserted';
  ELSE
  UPDATE tbl_logisticpartners SET name = v_name, emailid = v_emailid, phone = v_phone, address = v_address, contactpersonname = v_contactperson, contactpersonmobile = v_contactpersonmobile, gstin = v_gstin, panno = v_pan, city = v_city, state = v_state, region = v_region, pincode = v_pincode, accountholdername = v_accountholdername, accountno = v_accountno, ifsccode = v_ifsccode, bankname = v_bankname, branchname = v_bankname, bankaddress = v_bankaddress, bankstate = v_bank_state, bankcity = v_bank_city, cancelledchequeimage = v_bank_image, createddate = CURRENT_TIMESTAMP, active = v_active WHERE tlpid = v_tlpid;
  v_strresult := 'Updated';
  END IF;
  END IF;
  IF (v_mode = 2) THEN
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp (ROWNUMBER BIGINT 
    ,NAME VARCHAR(200) 
	,EMAILID VARCHAR(200) 
	,PHONE VARCHAR(200) 
	,ADDRESS text 
	,CONTACTPERSONNAME VARCHAR(500) 
	,CONTACTPERSONMOBILE VARCHAR(500) 
	,GSTIN VARCHAR(100) 
	,PANNO VARCHAR(200) 
	,CITY VARCHAR(500) 
	,STATE VARCHAR(200) 
	,REGION VARCHAR(200) 
	,PINCODE VARCHAR(200)
	,ACCOUNTHOLDERNAME VARCHAR(200)
	,ACCOUNTNO VARCHAR(200)
	,IFSCCODE VARCHAR(200)
	,BANKNAME VARCHAR(300)
	,BRANCHNAME VARCHAR(300)
	,BANKADDRESS VARCHAR(300)
	,BANKSTATE VARCHAR(300)
	,BANKCITY VARCHAR(300)
	,CANCELLEDCHEQUEIMAGE text 
	,CREATEDDATE timestamp
	,ACTIVE INT) ON COMMIT DROP;
  v_query := 'INSERT INTO #TEMP SELECT * from TBL_LOGISTICPARTNERS where 1=1';
  IF (v_searchfield = 'NAME') THEN
  v_query := v_query || ' AND EMAILID LIKE ''%' || v_searchvalue || '%'' ';
  END IF;
  IF (v_searchfield = 'EMAILID') THEN
  v_query := v_query || 'AND EMAILID LIKE ''%' || v_searchvalue || '%''';
  END IF;
  IF (v_searchfield = 'PHONE') THEN
  v_query := v_query || 'AND PHONE LIKE ''%' || v_searchvalue || '%''';
  END IF;
  IF ((v_fromdate <> '') AND (v_todate = '')) THEN
  v_query := v_query || ' AND CONVERT(DATE, CREATEDDATE, 105) BETWEEN  CONVERT(DATE, ''' || v_fromdate || ''', 105) AND  CONVERT(DATE, DBO.FUN_GETCURRENTDATE(), 105)';
  END IF;
  IF ((v_fromdate = '') AND (v_todate <> '')) THEN
  v_query := v_query || 'AND CONVERT(DATE, CREATEDDATE, 105) BETWEEN  CONVERT(DATE, ''' || v_todate || ''', 105) AND  CONVERT(DATE, DBO.FUN_GETCURRENTDATE(), 105)';
  END IF;
  IF ((v_fromdate <> '') AND (v_todate <> '')) THEN
  v_query := v_query || 'AND CONVERT(DATE, CREATEDDATE, 105) BETWEEN CONVERT(DATE, ''' || v_fromdate || ''', 105) AND  CONVERT(DATE, ''' || v_todate || ''', 105)';
  END IF;
  RAISE NOTICE '%', v_query;
  EXECUTE v_query;
  RETURN QUERY SELECT * FROM tmp_temp WHERE rownumber BETWEEN v_minindex AND v_maxindex ORDER BY rownumber ASC NULLS FIRST;
  SELECT COUNT(rownumber) INTO v_totalcount FROM tmp_temp;
  DROP TABLE IF EXISTS tmp_temp;
  -- SET option (removed)
  END IF;
  IF (v_mode = 3) THEN
  RETURN QUERY SELECT name, emailid, phone, address, contactpersonname, contactpersonmobile, gstin, panno, city, state, region, pincode, accountholdername, accountno, ifsccode, bankname, branchname, bankaddress, bankstate, bankcity, cancelledchequeimage, active FROM tbl_logisticpartners WHERE tlpid = v_tlpid;
  END IF;
  IF (0 <> 0) THEN
  v_strresult := 'Some Error Occoured !';
  -- ROLLBACK (removed)
  RETURN;
  END IF;
  -- COMMIT (removed)
END;
$$;


--
-- Name: usp_madepaymentall(text, character varying, timestamp without time zone, character varying, character varying, text, text, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_madepaymentall(v_acids text DEFAULT ''::text, v_paymentmode character varying DEFAULT ''::character varying, v_paydate timestamp without time zone DEFAULT NULL::timestamp without time zone, v_refno character varying DEFAULT ''::character varying, v_bankname character varying DEFAULT ''::character varying, v_regno text DEFAULT ''::text, v_amount text DEFAULT ''::text, v_intresult integer DEFAULT NULL::integer) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_slice1 text;
  v_slice3 text;
  v_index1 INT;
  v_index2 INT;
  v_slice2 text;
  v_slice4 text;
  v_sid int;
  v_cid int;
  v_catid int;
BEGIN
  v_sid := 0;
  v_cid := 0;
  v_catid := 0;
  v_intresult := 1;
  -- SET option (removed)
  v_slice1 := v_regno;
  v_slice3 := v_amount;
  v_index1 := 1;
  v_index2 := 2;
  WHILE v_index1 <> 0 AND v_index2 <> 0 LOOP
  SELECT POSITION(',' IN v_slice1) INTO v_index1;
  SELECT POSITION(',' IN v_slice3) INTO v_index2;
  IF v_index1 <> 0 AND v_index2 <> 0 THEN
  SELECT LEFT(CAST(v_slice1 AS TEXT), v_index1 - 1) INTO v_slice2;
  SELECT LEFT(CAST(v_slice3 AS TEXT), v_index2 - 1) INTO v_slice4;
  ELSE
  SELECT v_slice1 INTO v_slice2;
  SELECT v_slice3 INTO v_slice4;
  END IF;
  RETURN QUERY SELECT v_slice2 AS slice2, v_slice4 AS slice4;
  IF (0 <> 0) THEN
  v_intresult := 2;
  -- ROLLBACK (removed)
  RETURN;
  END IF;
  SELECT RIGHT(CAST(v_slice3 AS TEXT), LENGTH(CAST(v_slice3 AS TEXT)) - v_index2) INTO v_slice3;
  SELECT RIGHT(CAST(v_slice1 AS TEXT), LENGTH(CAST(v_slice1 AS TEXT)) - v_index1) INTO v_slice1;
  IF LENGTH(CAST(v_slice1 AS TEXT)) = 0 AND LENGTH(CAST(v_slice3 AS TEXT)) = 0 THEN
  EXIT;
  END IF;
  END LOOP;
  IF (0 <> 0) THEN
  v_intresult := 2;
  -- ROLLBACK (removed)
  RETURN;
  END IF;
END;
$$;


--
-- Name: usp_mainpagelimitedcategory(integer, integer, character varying, character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_mainpagelimitedcategory(v_cid integer, v_records integer, v_cityname character varying, v_state character varying) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_ctid INT;
  v_sid INT;
  v_count INT;
  v_diff INT;
  v_catcount INT;
  v_catcurr INT;
  v_catid INT;
  v_catname VARCHAR(100);
  v_countryname VARCHAR(50);
  v_viewallurl VARCHAR(100);
  v_catimage VARCHAR(50);
BEGIN
  v_ctid := 0;
  v_sid := 0;
  SELECT countryname INTO v_countryname FROM country WHERE cid = v_cid;
  IF (v_cid = 96) THEN
  IF (v_cityname IN ('Delhi', 'New delhi', 'Old Delhi')) THEN
  v_cityname := 'New Delhi';
  END IF;
  IF (v_cityname IN ('New Delhi', 'delhi', 'old delhi', 'Noida', 'Ghaziabad', 'Faridabad', 'Gurgaon', 'Greater Noida')) THEN
  v_state := 'Delhi/NCR';
  END IF;
  END IF;
  IF EXISTS(SELECT 1 FROM state WHERE statename = v_state AND sactive = 1) THEN
  SELECT sid INTO v_sid FROM state WHERE statename = v_state AND sactive = 1;
  IF EXISTS(SELECT 1 FROM city WHERE cityname = v_cityname AND active = 1) THEN
  SELECT ctid INTO v_ctid FROM city WHERE cityname = v_cityname AND sid = v_sid AND active = 1;
  END IF;
  END IF;
  DROP TABLE IF EXISTS tmp_cattemp;
  CREATE TEMP TABLE tmp_cattemp ON COMMIT DROP AS SELECT ROW_NUMBER() OVER (ORDER BY GEN_RANDOM_UUID() NULLS FIRST) AS rno, catid FROM product_category WHERE catid IN (1397, 378, 26, 1067) AND catactive = 1 ORDER BY GEN_RANDOM_UUID() NULLS FIRST LIMIT 4;
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp (ROWNUMBER INT GENERATED BY DEFAULT AS IDENTITY,
	DEALID INT,
	CATNAME VARCHAR(100),
	TITLE VARCHAR(200),
	DESCRIPTION text,
	DISCOUNT INT,
	OFFER text,
	LOCATION VARCHAR(100),
	CATICONE VARCHAR(100),
	URL VARCHAR(500),
	VIEWALLURL VARCHAR(200),
	bytea VARCHAR(200)) ON COMMIT DROP;
  SELECT COUNT(catid) INTO v_catcount FROM tmp_cattemp;
  v_catcurr := 1;
  WHILE (v_catcurr <= v_catcount) LOOP
  v_count := 0;
  v_diff := 0;
  SELECT catid INTO v_catid FROM tmp_cattemp WHERE rno = v_catcurr;
  SELECT catname INTO v_catname FROM product_category WHERE catid = v_catid AND catactive = 1;
  v_viewallurl := 'deals/' || REPLACE(LOWER(RTRIM(LTRIM(v_countryname))), ' ', '-') || '/' || REPLACE(LOWER(RTRIM(LTRIM(v_catname))), ' ', '-');
  v_catimage := REPLACE(LOWER(RTRIM(LTRIM(v_catname))), ' ', '-') || '.png';
  INSERT INTO tmp_temp SELECT pdm.dealid, v_catname AS catname, pdm.title, pdm.description, COALESCE(pdm.discount, 0) AS discount, CASE COALESCE(pdm.startprice, 0) WHEN 0 THEN pdm.offer ELSE pdm.offer || ' Starting from ' || CAST(pdm.startprice AS VARCHAR(20)) END AS offer, CASE COALESCE(am.areaname, '') WHEN '' THEN ct.cityname ELSE am.areaname || ', ' || ct.cityname END AS location, v_catimage AS caticone, REPLACE(REPLACE(dbo.GENRATINGDEALLISTINGSURL(pdm.dealid), '/', ''), '/', '') AS url, v_viewallurl AS viewallurl, COALESCE(CASE WHEN pdm.images LIKE '%,%' THEN (LEFT(CAST(pdm.images AS TEXT), POSITION(',' IN pdm.images) - 1)) ELSE pdm.images END, '') AS image FROM portal_master AS pm INNER JOIN portal_deal_master AS pdm ON pm.pmid = pdm.pmid LEFT JOIN city AS ct ON ct.ctid = pm.ctid LEFT JOIN area_master AS am ON am.pincode = pm.pincode AND am.areaname = pm.areaname WHERE pm.cid = v_cid AND (',' || COALESCE(pm.subctid, '') || ',') LIKE '%,' || CAST(v_ctid AS VARCHAR(50)) || ',%' AND (((',' || COALESCE(pm.catid, '') || ',') LIKE '%,' || CAST(v_catid AS VARCHAR(50)) || ',%') OR ((',' || COALESCE(pm.autocatid, '') || ',') LIKE '%,' || CAST(v_catid AS VARCHAR(50)) || ',%')) AND pdm.active = 1 AND pdm.verify = 1 AND pm.active = 1 AND pm.isverified = 1 AND (NOT pdm.dealid IN (SELECT dealid FROM tmp_temp)) ORDER BY GEN_RANDOM_UUID() NULLS FIRST LIMIT v_records;
  SELECT COUNT(1) INTO v_count FROM tmp_temp WHERE catname = v_catname;
  IF (v_count < v_records) THEN
  v_diff := v_records - v_count;
  ELSE
  v_diff := 0;
  END IF;
  INSERT INTO tmp_temp SELECT pdm.dealid, v_catname, pdm.title, pdm.description, COALESCE(pdm.discount, 0) AS discount, CASE COALESCE(pdm.startprice, 0) WHEN 0 THEN pdm.offer ELSE pdm.offer || ' Starting from ' || CAST(pdm.startprice AS VARCHAR(20)) END AS offer, CASE COALESCE(am.areaname, '') WHEN '' THEN ct.cityname ELSE am.areaname || ', ' || ct.cityname END AS location, v_catimage AS caticone, REPLACE(REPLACE(dbo.GENRATINGDEALLISTINGSURL(pdm.dealid), '/', ''), '/', '') AS url, v_viewallurl AS viewallurl, COALESCE(CASE WHEN pdm.images LIKE '%,%' THEN (LEFT(CAST(pdm.images AS TEXT), POSITION(',' IN pdm.images) - 1)) ELSE pdm.images END, '') AS image FROM portal_master AS pm INNER JOIN portal_deal_master AS pdm ON pm.pmid = pdm.pmid LEFT JOIN city AS ct ON ct.ctid = pm.ctid LEFT JOIN area_master AS am ON am.pincode = pm.pincode AND am.areaname = pm.areaname WHERE pm.cid = v_cid AND COALESCE(pm.ctid, 0) = v_ctid AND pdm.active = 1 AND pdm.verify = 1 AND pm.active = 1 AND pm.isverified = 1 AND (((',' || COALESCE(pm.catid, '') || ',') LIKE '%,' || CAST(v_catid AS VARCHAR(50)) || ',%') OR ((',' || COALESCE(pm.autocatid, '') || ',') LIKE '%,' || CAST(v_catid AS VARCHAR(50)) || ',%')) AND (NOT pdm.dealid IN (SELECT dealid FROM tmp_temp)) ORDER BY GEN_RANDOM_UUID() NULLS FIRST LIMIT v_diff;
  SELECT COUNT(1) INTO v_count FROM tmp_temp WHERE catname = v_catname;
  IF (v_count < v_records) THEN
  v_diff := v_records - v_count;
  ELSE
  v_diff := 0;
  END IF;
  INSERT INTO tmp_temp SELECT pdm.dealid, v_catname, pdm.title, pdm.description, COALESCE(pdm.discount, 0) AS discount, CASE COALESCE(pdm.startprice, 0) WHEN 0 THEN pdm.offer ELSE pdm.offer || ' Starting from ' || CAST(pdm.startprice AS VARCHAR(20)) END AS offer, CASE COALESCE(am.areaname, '') WHEN '' THEN ct.cityname ELSE am.areaname || ', ' || ct.cityname END AS location, v_catimage AS caticone, REPLACE(REPLACE(dbo.GENRATINGDEALLISTINGSURL(pdm.dealid), '/', ''), '/', '') AS url, v_viewallurl AS viewallurl, COALESCE(CASE WHEN pdm.images LIKE '%,%' THEN (LEFT(CAST(pdm.images AS TEXT), POSITION(',' IN pdm.images) - 1)) ELSE pdm.images END, '') AS image FROM portal_master AS pm INNER JOIN portal_deal_master AS pdm ON pm.pmid = pdm.pmid LEFT JOIN city AS ct ON ct.ctid = pm.ctid LEFT JOIN area_master AS am ON am.pincode = pm.pincode AND am.areaname = pm.areaname WHERE pm.cid = v_cid AND pdm.active = 1 AND pdm.verify = 1 AND pm.active = 1 AND pm.isverified = 1 AND (((',' || COALESCE(pm.catid, '') || ',') LIKE '%,' || CAST(v_catid AS VARCHAR(50)) || ',%') OR ((',' || COALESCE(pm.autocatid, '') || ',') LIKE '%,' || CAST(v_catid AS VARCHAR(50)) || ',%')) AND (NOT pdm.dealid IN (SELECT dealid FROM tmp_temp)) ORDER BY GEN_RANDOM_UUID() NULLS FIRST LIMIT v_diff;
  v_catcurr := v_catcurr + 1;
  END LOOP;
  RETURN QUERY SELECT * FROM tmp_temp ORDER BY rownumber ASC NULLS FIRST;
  DROP TABLE IF EXISTS tmp_temp;
END;
$$;


--
-- Name: usp_maintainotpsession(integer, integer, character varying, character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_maintainotpsession(v_otpno integer DEFAULT 12345, v_uidn0 integer DEFAULT 1435, v_mode character varying DEFAULT 'check'::character varying, INOUT v_intresult character varying DEFAULT ''::character varying) RETURNS character varying
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_sessiontime int;
  v_getminute int;
BEGIN
  v_sessiontime := 10;
  v_getminute := 0;
  v_intresult := '';
  IF (v_mode = 'send') THEN
  IF NOT EXISTS(SELECT 1 FROM tbl_maintainceotpsession WHERE uidno = v_uidn0 AND otp = v_otpno AND active = 1) THEN
  INSERT INTO tbl_maintainceotpsession VALUES (v_uidn0, v_otpno, 1, 1, dbo.FUN_GETCURRENTDATE());
  v_intresult := 'success';
  END IF;
  END IF;
  SELECT CAST(EXTRACT(epoch FROM CAST(CAST(dbo.FUN_GETCURRENTDATE() AS TIMESTAMP) AS TIMESTAMP) - CAST(CAST(datetime AS TIMESTAMP) AS TIMESTAMP)) / 60 AS BIGINT) INTO v_getminute FROM tbl_maintainceotpsession WHERE uidno = v_uidn0 AND otp = v_otpno;
  IF (v_mode = 'sessioncheck') THEN
  IF EXISTS(SELECT 1 FROM tbl_maintainceotpsession WHERE uidno = v_uidn0 AND otp = v_otpno AND active = 1) THEN
  UPDATE tbl_maintainceotpsession SET status = 0, active = 0 WHERE uidno = v_uidn0 AND otp = v_otpno;
  v_intresult := 'success';
  ELSE
  v_intresult := 'WrongOTP';
  END IF;
  END IF;
  IF (v_mode = 'check') THEN
  IF EXISTS(SELECT 1 FROM tbl_maintainceotpsession WHERE uidno = v_uidn0 AND otp = v_otpno AND active = 1) THEN
  UPDATE tbl_maintainceotpsession SET status = 0, active = 0 WHERE uidno = v_uidn0 AND otp = v_otpno;
  v_intresult := 'success';
  ELSE
  v_intresult := 'WrongOTP';
  END IF;
  END IF;
END;
$$;


