    LANGUAGE plpgsql
    AS $$
DECLARE
  v_sessiontime int;
  v_getminute int;
BEGIN
  v_sessiontime := 10;
  v_getminute := 0;
  v_intresult := '';
  IF (v_mode = 'send') THEN
  UPDATE tbl_maintainceotpsession_mlmwallet_mobile SET status = 0 WHERE clid = v_clid;
  IF NOT EXISTS(SELECT 1 FROM tbl_maintainceotpsession_mlmwallet_mobile WHERE clid = v_clid AND otp = v_otpno AND status = 1) THEN
  INSERT INTO tbl_maintainceotpsession_mlmwallet_mobile VALUES (v_clid, v_amount, v_mlmusername, v_mlmmobile, v_otpno, 1, dbo.FUN_GETCURRENTDATE());
  v_intresult := 'success';
