  SELECT CAST(EXTRACT(epoch FROM CAST(CAST(dbo.FUN_GETCURRENTDATE() AS TIMESTAMP) AS TIMESTAMP) - CAST(CAST(datetime AS TIMESTAMP) AS TIMESTAMP)) / 60 AS BIGINT) INTO v_getminute FROM tbl_maintainceotpsession_mlmwallet_mobile WHERE clid = v_clid AND otp = v_otpno AND status = 1;
  IF (v_mode = 'sessioncheck') THEN
  IF EXISTS(SELECT 1 FROM tbl_maintainceotpsession_mlmwallet_mobile WHERE clid = v_clid AND otp = v_otpno AND status = 1) THEN
  UPDATE tbl_maintainceotpsession_mlmwallet_mobile SET status = 0 WHERE clid = v_clid AND otp = v_otpno;
  v_intresult := 'success';
  ELSE
  v_intresult := 'WrongOTP';
  END IF;
  END IF;
END;
$$;


--
-- Name: usp_maintainrechargehistory(integer, bigint, character varying, character varying, numeric, text, numeric, character varying, text, character varying, character varying, character varying, character varying, numeric, numeric, numeric, numeric, numeric, integer, character varying, character varying, character varying, character varying, character varying, character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_maintainrechargehistory(v_mode integer DEFAULT 3, v_plid bigint DEFAULT 0, v_mobile character varying DEFAULT ''::character varying, v_operator character varying DEFAULT ''::character varying, v_amount numeric DEFAULT 0, v_api_refid text DEFAULT ''::text, v_api_balance numeric DEFAULT 0, v_api_errorcode character varying DEFAULT ''::character varying, v_api_remark text DEFAULT ''::text, v_api_reqid character varying DEFAULT ''::character varying, v_api_status character varying DEFAULT ''::character varying, INOUT v_strresult character varying DEFAULT ''::character varying, v_opcode character varying DEFAULT '0'::character varying, v_jppointredeempercentage numeric DEFAULT 0.00, v_ewalletredeempercentage numeric DEFAULT 0.00, v_bvpercentage numeric DEFAULT 0.00, v_discount numeric DEFAULT 0.00, v_netpayableamount numeric DEFAULT 0.00, v_isdiscountapplicabale integer DEFAULT 0, v_usernamejc character varying DEFAULT ''::character varying, v_transactionpasswordjc character varying DEFAULT ''::character varying, v_usernameewallet character varying DEFAULT ''::character varying, v_transactionpasswordewallet character varying DEFAULT ''::character varying, v_paymode character varying DEFAULT ''::character varying, v_ordernumber character varying DEFAULT ''::character varying) RETURNS character varying
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_ewallettransactionid Varchar(100);
  v_jcpointtransactionid Varchar(100);
  v_db_name VARCHAR(100);
  v_ref_regno VARCHAR(10);
  v_stroutput varchar(100);
  v_transactionidout varchar(100);
  v_parmdefinition text;
  v_querysql text;
  v_regno Int;
BEGIN
  IF (v_mode = 1) THEN
  -- BEGIN TRAN (removed)
  v_ewallettransactionid := '';
  v_jcpointtransactionid := '';
  IF (v_api_errorcode = '1000' OR v_api_errorcode = '1010') THEN
  IF (v_netpayableamount > 0) THEN
  v_db_name := '';
  v_ref_regno := '';
  SELECT db_name INTO v_db_name FROM tbl_distributor WHERE did = 1;
  SELECT regno INTO v_ref_regno FROM db_kyabol.dbo.member_master WHERE username = v_usernameewallet;
  v_stroutput := '';
  v_transactionidout := '';
  v_parmdefinition := N'@StrOutPut Nvarchar(100) OUTPUT,@TransactionIdOut Nvarchar(100) OUTPUT';
  v_querysql := '';
  v_querysql := 'EXEC [' || v_db_name || '].[DBO].[USP_SHOPING_TRANSACTION_DEBIT] ' || CAST(v_ref_regno AS VARCHAR(10)) || ',        
   ' || CAST(v_netpayableamount AS VARCHAR(20)) || ',''' || v_ordernumber || ''',@StrOutPut Out,@TransactionIdOut Out,1';
  EXECUTE v_querysql;
  IF (v_stroutput <> 'success') THEN
  v_strresult := v_stroutput;
  -- COMMIT (removed)
  RETURN;
  END IF;
  v_ewallettransactionid := v_transactionidout;
  END IF;
  IF (v_isdiscountapplicabale = 1 AND v_discount > 0) THEN
  v_transactionidout := '';
  v_regno := 0;
  IF EXISTS(SELECT 1 FROM cryptoadmincom.dbo.portal_login WHERE username = v_usernamejc AND active = 1) THEN
  SELECT regno INTO v_regno FROM cryptoadmincom.dbo.portal_login WHERE username = v_usernamejc AND active = 1;
  ELSE
  SELECT 0 INTO v_regno;
  END IF;
  v_querysql := 'EXEC [CRYPTOADMINCOM].[DBO].[USP_SHOPING_TRANSACTION_DEBIT] ' || CAST(v_ref_regno AS VARCHAR(10)) || ',        
   ' || CAST(v_discount AS VARCHAR(20)) || ',''' || v_ordernumber || ''',@StrOutPut Out,@TransactionIdOut Out,1';
  EXECUTE v_querysql;
  IF (v_stroutput <> 'success') THEN
  v_strresult := v_stroutput;
  -- COMMIT (removed)
  RETURN;
  END IF;
  v_jcpointtransactionid := v_transactionidout;
  END IF;
  END IF;
  INSERT INTO tbl_rechargehistory (plid, dateandtime, mobilenumber, operator, amount, api_refid, api_balance, api_errorcode, api_remark, api_reqid, api_status, status, opcode, isamountrefunded, jppointredeempercentage, ewalletredeempercentage, bvpercentage, discount, netpayableamount, isdiscountapplicabale, ewallettransactionid, jcpointtransactionid, usernamejc, transactionpasswordjc, usernameewallet, transactionpasswordewallet, paymode, ordernumber) VALUES (v_plid, dbo.FUN_GETCURRENTDATE(), v_mobile, v_operator, v_amount, v_api_refid, v_api_balance, v_api_errorcode, v_api_remark, v_api_reqid, v_api_status, (CASE WHEN v_api_errorcode = '1000' THEN 1 WHEN v_api_errorcode = '1010' THEN 2 ELSE 3 END), v_opcode, 0, v_jppointredeempercentage, v_ewalletredeempercentage, v_bvpercentage, v_discount, v_netpayableamount, v_isdiscountapplicabale, v_ewallettransactionid, v_jcpointtransactionid, v_usernamejc, v_transactionpasswordjc, v_usernameewallet, v_transactionpasswordewallet, v_paymode, v_ordernumber);
  v_strresult := 'success';
  IF (0 <> 0) THEN
  -- ROLLBACK (removed)
  v_strresult := 'Error occured';
  RETURN;
  END IF;
  -- COMMIT (removed)
  END IF;
END;
$$;


--
-- Name: usp_makingsessionof_area_city(text, integer, bigint, character varying, character varying, character varying, character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_makingsessionof_area_city(v_citynameparam text, v_cid integer DEFAULT 0, INOUT v_ctid bigint DEFAULT 0, INOUT v_cityname character varying DEFAULT ''::character varying, INOUT v_areaname character varying DEFAULT ''::character varying, INOUT v_statename character varying DEFAULT ''::character varying, INOUT v_pincode character varying DEFAULT ''::character varying) RETURNS record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_valuecount INT;
  v_statenametemp VARCHAR(100);
  v_citynametemp VARCHAR(100);
  v_areanametemp VARCHAR(100);
  v_pincodetemp VARCHAR(100);
  v_findareaid BIGINT;
BEGIN
  v_statenametemp := '';
  v_citynametemp := '';
  v_areanametemp := '';
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp (ID INT GENERATED BY DEFAULT AS IDENTITY,  
 TEMPVALUE VARCHAR(100)) ON COMMIT DROP;
  SELECT COUNT(*) INTO v_valuecount FROM dbo.SPLITSTRINGBYCOMMA(v_citynameparam);
  IF (v_valuecount = 4) THEN
  INSERT INTO tmp_temp SELECT * FROM dbo.SPLITSTRINGBYCOMMA(v_citynameparam);
  SELECT tempvalue INTO v_statenametemp FROM tmp_temp WHERE id = 4;
  SELECT tempvalue INTO v_citynametemp FROM tmp_temp WHERE id = 3;
  SELECT tempvalue INTO v_areanametemp FROM tmp_temp WHERE id = 2;
  SELECT tempvalue INTO v_pincodetemp FROM tmp_temp WHERE id = 1;
  IF EXISTS(SELECT pincode FROM area_master WHERE pincode = v_pincodetemp) AND EXISTS(SELECT areaname FROM area_master WHERE areaname = v_areanametemp) AND EXISTS(SELECT cityname FROM city WHERE cityname = v_citynametemp) AND EXISTS(SELECT statename FROM state WHERE statename = v_statenametemp) THEN
  SELECT RTRIM(LTRIM(s.statename)), c.ctid, RTRIM(LTRIM(c.cityname)), RTRIM(LTRIM(am.areaname)), am.pincode INTO v_statename, v_ctid, v_cityname, v_areaname, v_pincode FROM area_master AS am INNER JOIN city AS c ON am.ctid = c.ctid INNER JOIN state AS s ON c.sid = s.sid WHERE am.pincode = v_pincodetemp AND am.areaname = v_areanametemp AND c.cityname = v_citynametemp AND s.statename = v_statenametemp;
  ELSE
  IF EXISTS(SELECT cityname FROM city WHERE cityname = v_citynametemp) THEN
  SELECT RTRIM(LTRIM(c.ctid)), RTRIM(LTRIM(c.cityname)), RTRIM(LTRIM(s.statename)) INTO v_ctid, v_cityname, v_statename FROM city AS c INNER JOIN state AS s ON c.sid = s.sid WHERE RTRIM(LTRIM(LOWER(c.cityname))) = RTRIM(LTRIM(LOWER(v_citynametemp))) AND c.cid = v_cid LIMIT 1;
  ELSE
  IF EXISTS(SELECT cityname FROM city WHERE cityname = v_cityname) THEN
  SELECT RTRIM(LTRIM(c.ctid)), RTRIM(LTRIM(c.cityname)), RTRIM(LTRIM(s.statename)) INTO v_ctid, v_cityname, v_statename FROM city AS c INNER JOIN state AS s ON c.sid = s.sid WHERE RTRIM(LTRIM(LOWER(c.cityname))) = RTRIM(LTRIM(LOWER(v_citynametemp))) AND c.cid = v_cid LIMIT 1;
  ELSE
  IF NOT EXISTS(SELECT pincode FROM area_master WHERE pincode = v_pincodetemp) AND NOT EXISTS(SELECT areaname FROM area_master WHERE areaname = v_areanametemp) AND NOT EXISTS(SELECT cityname FROM city WHERE cityname = v_citynametemp) AND NOT EXISTS(SELECT statename FROM state WHERE statename = v_statenametemp) THEN
  v_ctid := 0;
  v_cityname := '';
  v_statename := '';
  ELSE
  v_ctid := 0;
  v_cityname := '';
  v_statename := '';
  END IF;
  END IF;
  END IF;
  END IF;
  ELSE
  IF (v_valuecount = 3) THEN
  INSERT INTO tmp_temp SELECT * FROM dbo.SPLITSTRINGBYCOMMA(v_citynameparam);
  SELECT tempvalue INTO v_statenametemp FROM tmp_temp WHERE id = 3;
  SELECT tempvalue INTO v_citynametemp FROM tmp_temp WHERE id = 2;
  SELECT tempvalue INTO v_areanametemp FROM tmp_temp WHERE id = 1;
  IF EXISTS(SELECT areaname FROM area_master WHERE areaname = v_areanametemp) AND EXISTS(SELECT cityname FROM city WHERE cityname = v_citynametemp) AND EXISTS(SELECT statename FROM state WHERE statename = v_statenametemp) THEN
  SELECT RTRIM(LTRIM(s.statename)), c.ctid, RTRIM(LTRIM(c.cityname)), RTRIM(LTRIM(am.areaname)) INTO v_statename, v_ctid, v_cityname, v_areaname FROM area_master AS am INNER JOIN city AS c ON am.ctid = c.ctid INNER JOIN state AS s ON c.sid = s.sid WHERE am.areaname = v_areanametemp AND c.cityname = v_citynametemp AND s.statename = v_statenametemp;
  ELSE
  IF EXISTS(SELECT cityname FROM city WHERE cityname = v_citynametemp) THEN
  SELECT RTRIM(LTRIM(c.ctid)), RTRIM(LTRIM(c.cityname)), RTRIM(LTRIM(s.statename)) INTO v_ctid, v_cityname, v_statename FROM city AS c INNER JOIN state AS s ON c.sid = s.sid WHERE RTRIM(LTRIM(LOWER(c.cityname))) = RTRIM(LTRIM(LOWER(v_citynametemp))) AND c.cid = v_cid LIMIT 1;
  ELSE
  IF NOT EXISTS(SELECT areaname FROM area_master WHERE areaname = v_areanametemp) AND NOT EXISTS(SELECT cityname FROM city WHERE cityname = v_citynametemp) AND NOT EXISTS(SELECT statename FROM state WHERE statename = v_statenametemp) THEN
  v_ctid := 0;
  v_cityname := '';
  v_statename := '';
  ELSE
  v_ctid := 0;
  v_cityname := '';
  v_statename := '';
  END IF;
  END IF;
  END IF;
  ELSE
  IF (v_valuecount = 2) THEN
  INSERT INTO tmp_temp SELECT * FROM dbo.SPLITSTRINGBYCOMMA(v_citynameparam);
  SELECT tempvalue INTO v_statenametemp FROM tmp_temp WHERE id = 2;
  SELECT tempvalue INTO v_citynametemp FROM tmp_temp WHERE id = 1;
  IF EXISTS(SELECT cityname FROM city WHERE cityname = v_citynametemp) AND EXISTS(SELECT statename FROM state WHERE statename = v_statenametemp) THEN
  SELECT RTRIM(LTRIM(s.statename)), c.ctid, RTRIM(LTRIM(c.cityname)) INTO v_statename, v_ctid, v_cityname FROM city AS c INNER JOIN state AS s ON c.sid = s.sid WHERE c.cityname = v_citynametemp AND s.statename = v_statenametemp;
  ELSE
  IF EXISTS(SELECT cityname FROM city WHERE cityname = v_citynametemp) AND NOT EXISTS(SELECT statename FROM state WHERE statename = v_statenametemp) THEN
  SELECT RTRIM(LTRIM(c.ctid)), RTRIM(LTRIM(c.cityname)), RTRIM(LTRIM(s.statename)) INTO v_ctid, v_cityname, v_statename FROM city AS c INNER JOIN state AS s ON c.sid = s.sid WHERE RTRIM(LTRIM(LOWER(c.cityname))) = RTRIM(LTRIM(LOWER(v_citynametemp))) AND c.cid = v_cid LIMIT 1;
  ELSE
  IF NOT EXISTS(SELECT cityname FROM city WHERE cityname = v_citynametemp) AND EXISTS(SELECT statename FROM state WHERE statename = v_statenametemp) THEN
  SELECT RTRIM(LTRIM(c.ctid)), RTRIM(LTRIM(c.cityname)), RTRIM(LTRIM(s.statename)) INTO v_ctid, v_cityname, v_statename FROM state AS s INNER JOIN city AS c ON s.sid = c.sid WHERE RTRIM(LTRIM(LOWER(s.statename))) = RTRIM(LTRIM(LOWER(v_statenametemp))) AND s.cid = v_cid LIMIT 1;
  ELSE
  IF NOT EXISTS(SELECT cityname FROM city WHERE cityname = v_citynametemp) AND NOT EXISTS(SELECT statename FROM state WHERE statename = v_statenametemp) THEN
  v_ctid := 0;
  v_cityname := '';
  v_statename := '';
  END IF;
  END IF;
  END IF;
  END IF;
  ELSE
  IF (v_valuecount = 1) THEN
  IF EXISTS(SELECT areaname FROM area_master WHERE areaname = v_citynameparam) AND EXISTS(SELECT cityname FROM city WHERE cityname = v_citynameparam) THEN
  SELECT RTRIM(LTRIM(ctid)) INTO v_ctid FROM city WHERE cityname = v_citynameparam AND cid = v_cid LIMIT 1;
  SELECT cityname, statename INTO v_cityname, v_statename FROM city AS c INNER JOIN state AS s ON c.sid = s.sid WHERE c.ctid = v_ctid AND c.cid = v_cid;
  ELSE
  IF EXISTS(SELECT areaname FROM area_master WHERE areaname = v_citynameparam) AND NOT EXISTS(SELECT cityname FROM city WHERE cityname = v_citynameparam) THEN
  SELECT aid INTO v_findareaid FROM area_master WHERE areaname = v_citynameparam AND cid = v_cid LIMIT 1;
  SELECT RTRIM(LTRIM(areaname)), RTRIM(LTRIM(c.ctid)), RTRIM(LTRIM(c.cityname)), RTRIM(LTRIM(s.statename)) INTO v_areaname, v_ctid, v_cityname, v_statename FROM area_master AS am INNER JOIN city AS c ON am.ctid = c.ctid INNER JOIN state AS s ON c.sid = s.sid WHERE am.aid = v_findareaid AND am.cid = v_cid;
  ELSE
  IF NOT EXISTS(SELECT areaname FROM area_master WHERE areaname = v_citynameparam) AND EXISTS(SELECT cityname FROM city WHERE cityname = v_citynameparam) THEN
  SELECT RTRIM(LTRIM(ctid)) INTO v_ctid FROM city WHERE cityname = v_citynameparam AND cid = v_cid LIMIT 1;
  SELECT cityname, statename INTO v_cityname, v_statename FROM city AS c INNER JOIN state AS s ON c.sid = s.sid WHERE c.ctid = v_ctid AND c.cid = v_cid;
  ELSE
  IF EXISTS(SELECT pincode FROM area_master WHERE pincode = v_citynameparam) THEN
  SELECT RTRIM(LTRIM(s.statename)), c.ctid, RTRIM(LTRIM(c.cityname)), RTRIM(LTRIM(am.areaname)), am.pincode INTO v_statename, v_ctid, v_cityname, v_areaname, v_pincode FROM area_master AS am INNER JOIN city AS c ON am.ctid = c.ctid INNER JOIN state AS s ON c.sid = s.sid WHERE am.pincode = v_citynameparam;
  ELSE
  v_ctid := 96;
  v_cityname := v_citynameparam;
  v_statename := v_citynameparam;
  END IF;
  END IF;
  END IF;
  END IF;
  END IF;
  END IF;
  END IF;
  END IF;
  DROP TABLE IF EXISTS tmp_temp;
END;
$$;


--
-- Name: usp_manage_add_item(integer, bigint, character varying, integer, character varying, character varying, integer, integer, integer, character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_manage_add_item(v_mode integer DEFAULT 3, v_plid bigint DEFAULT 2, v_strresult character varying DEFAULT ''::character varying, v_totalcount integer DEFAULT 0, v_fromdate character varying DEFAULT ''::character varying, v_todate character varying DEFAULT ''::character varying, v_startrowindex integer DEFAULT 1, v_maxrows integer DEFAULT 100, v_toilid integer DEFAULT 6, v_alltoilid character varying DEFAULT '7,6,'::character varying) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_minindex INT;
  v_maxindex INT;
  v_query varchar(4000);
BEGIN
  v_minindex := 1;
  v_maxindex := 100;
  v_minindex := (v_startrowindex - 1) * v_maxrows + 1;
  v_maxindex := v_startrowindex * v_maxrows;
  -- BEGIN TRAN (removed)
  BEGIN
  IF (v_mode = 2) THEN
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp (ROWNUMBER BIGINT,                            
  TOILID Int,  
  ItemName  Varchar(200),   
  ItemCode  Varchar(200),   
  SellingPrice  Decimal(18,8),   
  CPoints Decimal(10,2),                        
  STATUS VARCHAR(100)) ON COMMIT DROP;
  v_query := '';
  v_query := 'Insert Into #Temp Select ROW_NUMBER() Over(Order By TOILID DESC),TOILID,ItemName,ItemCode,SellingPrice,                            
  CPoints,STATUS From TBL_Offline_Item_List WHERE PLID = ' || CAST(v_plid AS VARCHAR) || ' AND STATUS=1';
  IF (v_fromdate <> '' AND v_todate = '') THEN
  v_query := v_query || (' And Convert(Date,AddedDateTime) >= Convert(Date,''' || v_fromdate || ''') ');
  END IF;
  IF (v_fromdate = '' AND v_todate <> '') THEN
  v_query := v_query || (' And Convert(Date,AddedDateTime) <= Convert(Date,''' || v_todate || ''') ');
  END IF;
  IF (v_fromdate <> '' AND v_todate <> '') THEN
  v_query := v_query || (' And Convert(Date,AddedDateTime) Between Convert(Date,''' || v_fromdate || ''') And Convert(Date,''' || v_todate || ''') ');
  END IF;
  v_query := v_query || (' Order By AddedDateTime Desc');
  EXECUTE v_query;
  RETURN QUERY SELECT * FROM tmp_temp WHERE rownumber BETWEEN v_minindex AND v_maxindex;
  SELECT COUNT(1) INTO v_totalcount FROM tmp_temp;
  DROP TABLE IF EXISTS tmp_temp;
  v_strresult := 'success';
  END IF;
  IF (v_mode = 1) THEN
  RETURN QUERY SELECT ROW_NUMBER() OVER (ORDER BY toilid DESC NULLS LAST) AS rownumber, toilid, itemname, itemcode, sellingprice, cpoints, CAST(status AS VARCHAR(10)) AS status FROM tbl_offline_item_list WHERE toilid = v_toilid;
  END IF;
  IF (v_mode = 3) THEN
  RETURN QUERY SELECT ROW_NUMBER() OVER (ORDER BY toilid DESC NULLS LAST) AS rownumber, toilid, itemname, itemcode, sellingprice, cpoints, CAST(status AS VARCHAR(10)) AS status FROM tbl_offline_item_list WHERE toilid IN (SELECT value FROM SPLITSTRINGBYCOMMA(v_alltoilid));
  END IF;
  EXCEPTION WHEN OTHERS THEN
  RETURN QUERY SELECT sqlerrm;
  PERFORM dbo.sp_errorlog();
  IF (0 > 0) THEN
  -- ROLLBACK (removed)
  END IF;
  RETURN;
  END;
  IF (0 <> 0) THEN
  RETURN QUERY SELECT sqlerrm;
  v_strresult := 'ERROR';
  -- ROLLBACK (removed)
  RETURN;
  ELSE
  -- COMMIT (removed)
  END IF;
END;
$$;


--
-- Name: usp_manage_admin_secutiry_key(bigint, character varying, character varying, character varying, integer, character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_manage_admin_secutiry_key(v_emp_id bigint, v_mode character varying, v_sms character varying, v_gakey character varying, v_activekey integer, INOUT v_strresult character varying) RETURNS character varying
    LANGUAGE plpgsql
    AS $$
BEGIN
  -- BEGIN TRAN (removed)
  IF (v_mode = 'add') THEN
  UPDATE admin_security_key SET status = 0 WHERE emp_id = v_emp_id;
  INSERT INTO admin_security_key (emp_id, sms, gakey, activekey, date, status) VALUES (v_emp_id, v_sms, v_gakey, v_activekey, dbo.FUN_GETCURRENTDATE(), 1);
  END IF;
  IF (v_mode = 'reset') THEN
  UPDATE admin_security_key SET status = 0 WHERE emp_id = v_emp_id;
  END IF;
  IF (0 <> 0) THEN
  v_strresult := 'Please try again !';
  -- ROLLBACK (removed)
  RETURN;
  END IF;
  v_strresult := 'ok';
  -- COMMIT (removed)
END;
$$;


--
-- Name: usp_manage_affiliate_share(integer, integer, character varying, integer, character varying, integer, integer, character varying, character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_manage_affiliate_share(v_share_by_id integer DEFAULT NULL::integer, v_share_to_id integer DEFAULT NULL::integer, v_link character varying DEFAULT NULL::character varying, v_sprid integer DEFAULT NULL::integer, v_remark character varying DEFAULT NULL::character varying, v_mode integer DEFAULT NULL::integer, v_complete_flag integer DEFAULT NULL::integer, v_order_id character varying DEFAULT NULL::character varying, INOUT v_message character varying DEFAULT NULL::character varying) RETURNS character varying
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_share_to_name VARCHAR(250);
  v_bonus_type VARCHAR(10);
  v_bonus_value DECIMAL(18,2);
  v_redeem_days int;
  v_ready_for_redeem_on timestamp;
  v_p_sale_price decimal(10,2);
  v_qty int;
  v_affiliate_amount decimal(18,2);
  v_sale_price decimal(18,2);
  v_admin_receive decimal(18,2);
  v_user_receive decimal(18,2);
  v_admin_percentage decimal(18,2);
BEGIN
  IF NOT EXISTS(SELECT 1 FROM tbl_customerlogin WHERE clid = v_share_to_id) THEN
  v_message := 'ok^Invalid Share to id';
  RETURN;
  END IF;
  IF NOT EXISTS(SELECT 1 FROM tbl_customerlogin WHERE clid = v_share_by_id) AND v_mode <> 3 THEN
  v_message := 'ok^Invalid Affilate user';
  RETURN;
  END IF;
  IF NOT EXISTS(SELECT 1 FROM ims_subproduct WHERE sprid = v_sprid) THEN
  v_message := 'ok^Product not available';
  RETURN;
  END IF;
  IF NOT EXISTS(SELECT 1 FROM affiliate_bonus_on_product WHERE sprid = v_sprid) THEN
  v_message := 'Faild^Share Bonus Not available';
  RETURN;
  END IF;
  IF (v_mode = 1) THEN
  v_share_to_name := (SELECT fname FROM tbl_customerlogin WHERE clid = v_share_to_id LIMIT 1);
  SELECT bonus_type, bonus_value, redeem_after_days INTO v_bonus_type, v_bonus_value, v_redeem_days FROM affiliate_bonus_on_product WHERE sprid = v_sprid;
  IF EXISTS(SELECT 1 FROM affiliate_share_link_info WHERE share_by_id = v_share_by_id AND share_to_id = v_share_to_id AND sprid = v_sprid AND complete_flag <> 3) THEN
  UPDATE affiliate_share_link_info SET share_by_id = v_share_by_id, share_to_id = v_share_to_id, share_to_name = v_share_to_name, link = v_link, bonus_type = v_bonus_type, bonus_value = v_bonus_value, sprid = v_sprid, last_updated_on = CURRENT_TIMESTAMP, complete_flag = v_complete_flag, remark = v_remark, order_id = v_order_id WHERE share_by_id = v_share_by_id AND share_to_id = v_share_to_id AND sprid = v_sprid AND complete_flag <> 3;
  ELSE
  INSERT INTO affiliate_share_link_info (share_by_id, share_to_id, share_to_name, link, bonus_type, bonus_value, sprid, created_on, last_updated_on, complete_flag, remark, order_id) VALUES (v_share_by_id, v_share_to_id, v_share_to_name, v_link, v_bonus_type, v_bonus_value, v_sprid, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, v_complete_flag, v_remark, v_order_id);
  END IF;
  v_message := 'ok^Save successfully!';
  ELSE
  IF (v_mode = 2) THEN
  IF EXISTS(SELECT 1 FROM affiliate_share_link_info WHERE share_by_id = v_share_by_id AND share_to_id = v_share_to_id AND sprid = v_sprid AND complete_flag <> 3) THEN
  SELECT pom.product_qty INTO v_qty FROM affiliate_share_link_info AS asl INNER JOIN tbl_product_order_master AS pom ON pom.subprcode = asl.sprid WHERE pom.orderid = v_order_id;
  UPDATE affiliate_share_link_info SET last_updated_on = CURRENT_TIMESTAMP, complete_flag = v_complete_flag, remark = v_remark, qty = v_qty, order_id = v_order_id WHERE share_by_id = v_share_by_id AND share_to_id = v_share_to_id AND sprid = v_sprid AND complete_flag <> 3;
  END IF;
  ELSE
  IF (v_mode = 3) THEN
  IF EXISTS(SELECT 1 FROM affiliate_share_link_info WHERE share_to_id = v_share_to_id AND sprid = v_sprid AND complete_flag <> 3) THEN
  IF EXISTS(SELECT 1 FROM affiliate_share_link_info WHERE share_to_id = v_share_to_id AND sprid = v_sprid AND complete_flag = 3 AND order_id = v_order_id) THEN
  v_message := 'OK^Already Obtained';
  RETURN;
  END IF;
  IF EXISTS(SELECT 1 FROM affiliate_bonus_on_product WHERE sprid = v_sprid) THEN
  SELECT bonus_type, bonus_value, redeem_after_days INTO v_bonus_type, v_bonus_value, v_redeem_days FROM affiliate_bonus_on_product WHERE sprid = v_sprid;
  v_ready_for_redeem_on := CURRENT_TIMESTAMP + (INTERVAL '1 DAY' * v_redeem_days);
  v_admin_percentage := (SELECT config_value FROM configuration_master WHERE config_name LIKE '%Admin_Affiliate_Charge%');
  IF (v_bonus_type = 'P') THEN
  v_sale_price := (SELECT sellmrp FROM ims_subproduct WHERE sprid = v_sprid);
  v_affiliate_amount := (v_sale_price * v_bonus_value) / 100;
  ELSE
  v_affiliate_amount := v_bonus_value;
  END IF;
  v_admin_receive := (v_affiliate_amount * v_admin_percentage) / 100;
  v_user_receive := v_affiliate_amount - v_admin_receive;
  UPDATE affiliate_share_link_info SET bonus_type = v_bonus_type, bonus_value = v_affiliate_amount * qty, complete_flag = v_complete_flag, remark = v_remark, ready_for_redeem_on = v_ready_for_redeem_on, redeem_flag = 0, admin_receive_amt = v_admin_receive * qty, user_receive_amt = v_user_receive * qty WHERE share_to_id = v_share_to_id AND sprid = v_sprid AND complete_flag <> 3;
  v_message := 'OK^COMPLETED';
  ELSE
  v_message := 'Faild^Share Bonus Not available';
  END IF;
  ELSE
  v_message := 'OK^Invalid Request';
  END IF;
  ELSE
  v_message := 'Error^No action';
  END IF;
  END IF;
  END IF;
END;
$$;


--
-- Name: usp_manage_attributes_witdcategory(character varying, integer, integer, character varying, character varying, integer, character varying, boolean, boolean, boolean, boolean, character varying, character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_manage_attributes_witdcategory(v_type character varying, v_id integer, v_awct_id integer, v_att_name character varying, v_att_type character varying, v_select_ddlid integer, v_att_default_value character varying, v_ismendatory boolean DEFAULT false, v_issearch boolean DEFAULT false, v_isactive boolean DEFAULT false, v_isselective boolean DEFAULT NULL::boolean, v_mode character varying DEFAULT NULL::character varying, INOUT v_strresult character varying DEFAULT NULL::character varying) RETURNS character varying
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_max_awctid BIGINT;
  v_subcatid INT;
  v_is_active boolean;
  v_srno INT;
  v_catid INT;
  v_maincatid INT;
BEGIN
  -- BEGIN TRAN (removed)
  IF NOT v_att_type IN ('Text', 'TextArea', 'Checkbox', 'Select', 'Color') THEN
  v_strresult := 'Error^Some Rrror Occured...!!!';
  -- COMMIT (removed)
  RETURN;
  END IF;
  v_max_awctid := 0;
  IF (v_mode = 'Add') THEN
  IF (v_att_type <> 'Select') THEN
  v_select_ddlid := 0;
  END IF;
  IF (v_att_type = 'Color') THEN
  v_att_default_value := '';
  END IF;
  IF (v_att_type = 'Select') THEN
  IF (v_select_ddlid <= 0) THEN
  v_strresult := 'Error^Select Dropdown List Item !';
  -- COMMIT (removed)
  RETURN;
  END IF;
  v_att_default_value := '';
  END IF;
  IF (v_att_type = 'Checkbox') THEN
  IF NOT v_att_default_value IN ('Yes', 'No') THEN
  v_att_default_value := '';
  END IF;
  END IF;
  IF (v_type = 'Mcat') THEN
  v_maincatid := 0;
  SELECT maincatid INTO v_maincatid FROM tbl_main_category WHERE maincatid = v_id;
  IF (v_maincatid <= 0) THEN
  v_strresult := 'Error^Some Error Occured...!!!';
  -- COMMIT (removed)
  RETURN;
  END IF;
  v_awct_id := 0;
  SELECT awct_id, COALESCE(is_active, 1) INTO v_awct_id, v_is_active FROM tbl_attributes_with_category WHERE main_cat_id = v_id AND att_name = v_att_name;
  IF (v_awct_id > 0 AND v_is_active = 1) THEN
  v_strresult := 'Error^Attribute Name Already Exists...!!!';
  -- COMMIT (removed)
  RETURN;
  END IF;
  IF EXISTS(SELECT ddl_id FROM tbl_attributes_with_category WHERE is_active = 1 AND main_cat_id = v_id AND ddl_id = v_select_ddlid AND main_cat_id = v_maincatid AND cat_id = v_catid) THEN
  -- COMMIT (removed)
  v_strresult := 'This Dropdown Name Already Exists...!!!';
  RETURN;
  END IF;
  IF (v_awct_id = 0) THEN
  SELECT COALESCE(MAX(sr_no), 0) + 1 INTO v_srno FROM tbl_attributes_with_category WHERE main_cat_id = v_id;
  SELECT COALESCE(MAX(awct_id), 0) + 1 INTO v_max_awctid FROM tbl_attributes_with_category;
  INSERT INTO tbl_attributes_with_category (awct_id, main_cat_id, sub_cat_id, cat_id, att_name, att_type, ddl_id, default_value, sr_no, is_active, ismendatory, issearch) VALUES (v_max_awctid, v_id, 0, 0, v_att_name, v_att_type, v_select_ddlid, v_att_default_value, v_srno, v_isactive, v_ismendatory, v_issearch);
  UPDATE tbl_ddl_master SET maincategoryid = v_id, subcategoryid = 0, categoryid = 0 WHERE ddl_id = v_select_ddlid;
  UPDATE tbl_ddl_master SET maincategoryid = v_id, subcategoryid = 0, categoryid = 0 WHERE parent_ddl_id = v_select_ddlid;
  v_strresult := 'Success^' || CAST(v_max_awctid AS VARCHAR(20));
  -- COMMIT (removed)
  RETURN;
  END IF;
  IF (v_awct_id > 0 AND v_is_active = 1) THEN
  UPDATE tbl_attributes_with_category SET is_active = v_isactive, att_type = v_att_type, ddl_id = v_select_ddlid, default_value = v_att_default_value, att_name = v_att_name, ismendatory = v_ismendatory, issearch = v_issearch WHERE awct_id = v_awct_id;
  v_strresult := 'Update^' || CAST(v_max_awctid AS VARCHAR(20));
  -- COMMIT (removed)
  RETURN;
  END IF;
  END IF;
  IF (v_type = 'SUBCAT') THEN
  v_subcatid := 0;
  SELECT maincatid, catid, subcatid INTO v_maincatid, v_catid, v_subcatid FROM tbl_sub_category WHERE subcatid = v_id;
  IF (v_subcatid <= 0) THEN
  v_strresult := 'Error^Some Error Occured...!!!';
  -- COMMIT (removed)
  RETURN;
  END IF;
  v_awct_id := 0;
  SELECT awct_id, COALESCE(is_active, 1) INTO v_awct_id, v_is_active FROM tbl_attributes_with_category WHERE sub_cat_id = v_id AND att_name = v_att_name;
  IF (v_awct_id > 0 AND v_is_active = 1) THEN
  v_strresult := 'Attribute Name Already Exists...!!!';
  -- COMMIT (removed)
  RETURN;
  END IF;
  IF EXISTS(SELECT ddl_id FROM tbl_attributes_with_category WHERE is_active = 1 AND sub_cat_id = v_id AND ddl_id = v_select_ddlid AND main_cat_id = v_maincatid AND cat_id = v_catid) THEN
  -- COMMIT (removed)
  v_strresult := 'error^This Dropdown Name Already Exists...!!!';
  RETURN;
  END IF;
  IF (v_awct_id = 0) THEN
  SELECT maincatid, catid INTO v_maincatid, v_catid FROM dbo.tbl_sub_category WHERE subcatid = v_id;
  SELECT COALESCE(MAX(sr_no), 0) + 1 INTO v_srno FROM tbl_attributes_with_category WHERE sub_cat_id = v_id;
  SELECT COALESCE(MAX(awct_id), 0) + 1 INTO v_max_awctid FROM tbl_attributes_with_category;
