--
-- Name: usp_manage_offer(character varying, integer, character varying, character varying, integer, character varying, character varying, boolean, numeric, numeric, character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_manage_offer(v_flag character varying, v_product_id integer DEFAULT 0, v_product_name character varying DEFAULT ''::character varying, v_offer_title character varying DEFAULT ''::character varying, v_offer_mst_id integer DEFAULT 0, v_offer_start character varying DEFAULT ''::character varying, v_offer_end character varying DEFAULT ''::character varying, v_is_active boolean DEFAULT NULL::boolean, v_offer_price numeric DEFAULT 0, v_offer_discount_per numeric DEFAULT 0, v_out_result character varying DEFAULT NULL::character varying) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_sourcetable varchar(100);
  v_v_offer_mst_id int;
  v_v_sprid int;
  v_offer_dap decimal(10,2);
  v_vat decimal(10,2);
BEGIN
  v_v_offer_mst_id := v_offer_mst_id;
  SELECT detail_source_tbl, offer_title INTO v_sourcetable, v_offer_title FROM tbl_offer_mst WHERE offerid = v_v_offer_mst_id LIMIT 1;
  IF (v_flag = 'ADD_OFFER') THEN
  IF (COALESCE(v_product_id, '') = '' OR (SELECT COUNT(1) FROM ims_subproduct WHERE sprid = v_product_id AND ismerchantstatus <> 5) > 0) THEN
  v_out_result := 'alert^Alert^Product Not available Or Not Active';
  RETURN;
  END IF;
  v_v_sprid := v_product_id;
  v_vat := (SELECT vc.vatpercvalue FROM dbo.ims_subproduct AS sub INNER JOIN tbl_vat_categories AS vc ON vc.vcid = sub.vatcategoryid WHERE sub.sprid = v_v_sprid);
  IF EXISTS(SELECT 1 FROM tbl_offer_on_product WHERE product_id = v_product_id AND offer_mst_id = v_offer_mst_id) THEN
  UPDATE tbl_offer_on_product SET product_id = COALESCE(v_product_id, (SELECT product_id FROM tbl_offer_on_product WHERE product_id = v_product_id AND offer_mst_id = v_offer_mst_id)), product_name = COALESCE(v_product_name, (SELECT product_name FROM tbl_offer_on_product WHERE product_id = v_product_id AND offer_mst_id = v_offer_mst_id)), offer_mst_id = COALESCE(v_offer_mst_id, (SELECT offer_mst_id FROM tbl_offer_on_product WHERE product_id = v_product_id AND offer_mst_id = v_offer_mst_id)), offer_title = COALESCE(v_offer_title, (SELECT offer_title FROM tbl_offer_on_product WHERE product_id = v_product_id AND offer_mst_id = v_offer_mst_id)), offer_start = COALESCE(v_offer_start, (SELECT offer_start FROM tbl_offer_on_product WHERE product_id = v_product_id AND offer_mst_id = v_offer_mst_id)), offer_end = COALESCE(v_offer_end, (SELECT offer_end FROM tbl_offer_on_product WHERE product_id = v_product_id AND offer_mst_id = v_offer_mst_id)), is_active = COALESCE(v_is_active, (SELECT is_active FROM tbl_offer_on_product WHERE product_id = v_product_id AND offer_mst_id = v_offer_mst_id)), offer_price = COALESCE(v_offer_price, (SELECT offer_price FROM tbl_offer_on_product WHERE product_id = v_product_id AND offer_mst_id = v_offer_mst_id)), offer_dis_percentage = COALESCE(v_offer_discount_per, (SELECT offer_dis_percentage FROM tbl_offer_on_product WHERE product_id = v_product_id AND offer_mst_id = v_offer_mst_id)) WHERE product_id = v_product_id AND offer_mst_id = v_offer_mst_id;
  UPDATE tbl_offer_on_product SET offer_dap = (offer_price / ((100 + v_vat) / 100)) WHERE product_id = v_product_id AND offer_mst_id = v_offer_mst_id;
  v_out_result := 'ok^Success^Updated Successfully!';
  ELSE
  v_offer_dap := (v_offer_price / ((100 + v_vat) / 100));
  INSERT INTO tbl_offer_on_product (product_id, product_name, offer_mst_id, offer_title, offer_start, offer_end, is_active, inserted_on, offer_price, offer_dis_percentage, sprid, offer_dap) VALUES (v_product_id, '', v_offer_mst_id, v_offer_title, v_offer_start, v_offer_end, v_is_active, CURRENT_TIMESTAMP, v_offer_price, v_offer_discount_per, v_v_sprid, v_offer_dap);
  v_out_result := 'ok^success^Offer Added Successfully!';
  END IF;
  ELSE
  IF (v_flag = 'Single_Offer_data') THEN
  RETURN QUERY SELECT opid, product_id, product_name, offer_mst_id, offer_title, TO_CHAR(offer_start, 'YYYY-MM-DD') AS offer_start, TO_CHAR(offer_end, 'YYYY-MM-DD') AS offer_end, TO_CHAR(offer_start, 'HH12:MI:SS tt') AS start_time, TO_CHAR(offer_end, 'HH12:MI:SS tt') AS end_time, is_active, inserted_on, offer_price, offer_dis_percentage FROM tbl_offer_on_product AS offer RIGHT JOIN ims_subproduct AS sub ON sub.sprid = offer.product_id WHERE sub.sprid = v_product_id;
  END IF;
  END IF;
END;
$$;


