--
-- Name: usp_manage_product_resellercommission(character varying, character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_manage_product_resellercommission(v_orderno character varying DEFAULT ''::character varying, INOUT v_strresult character varying DEFAULT ''::character varying) RETURNS character varying
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_resellercommission DECIMAL(18,2);
  v_totalpurchasecost DECIMAL(18,2);
  v_did INT;
  v_orderid VARCHAR(100);
  v_gstpercentage DECIMAL(18,2);
  v_invoiceno Varchar(100);
  v_currentyear int;
  v_lastyear INT;
  v_invoicecode VARCHAR(100);
  v_countno INT;
  v_companyname VARCHAR(100);
  v_countnumber VARCHAR(100);
  v_resellerloginid VARCHAR(10);
BEGIN
  -- BEGIN TRAN (removed)
  -- SET option (removed)
  v_totalpurchasecost := 0;
  v_did := 0;
  v_orderid := '';
  v_gstpercentage := 0;
  v_invoiceno := '';
  v_currentyear := 0;
  v_lastyear := 0;
  v_invoicecode := '';
  v_countno := 0;
  v_companyname := '';
  v_countnumber := '';
  v_resellerloginid := '';
  IF (v_orderno = '') THEN
  v_strresult := 'NOT EXISTS';
  -- COMMIT (removed)
  RETURN;
  END IF;
  SELECT COALESCE(limits, 0) INTO v_gstpercentage FROM settings WHERE caption = 'GST PERCENTAGE';
  SELECT COALESCE(did, 0) INTO v_did FROM tbl_customerlogin WHERE loginid IN (SELECT COALESCE(loginid, '') FROM tbl_product_order_master WHERE orderno = v_orderno AND intstatus = 6);
  SELECT COALESCE(resellercommission, 0), COALESCE(total_purchase_cost, 0), COALESCE(orderid, '') INTO v_resellercommission, v_totalpurchasecost, v_orderid FROM tbl_product_order_master WHERE orderno = v_orderno AND intstatus = 6;
  SELECT COALESCE(loginid, '') INTO v_resellerloginid FROM tbl_distributor WHERE did = v_did;
  SELECT COALESCE(companyname, '') INTO v_companyname FROM distributor_master WHERE plid = v_did;
  SELECT dbo.UDF_FIRST_LETTER_FROM_WORD(v_companyname) INTO v_invoicecode;
  SELECT EXTRACT(YEAR FROM CAST(dbo.FUN_GETCURRENTDATE() AS DATE)) INTO v_currentyear;
  v_lastyear := v_currentyear + 1;
  v_lastyear := RIGHT(CAST(v_lastyear AS TEXT), 2);
  SELECT COALESCE(invoiceno, 0) INTO v_countno FROM tbl_reseller_commission_invoice_master WHERE did = v_did;
  v_countno := v_countno + 1;
  SELECT RIGHT(CAST('I00' || CAST(v_countno AS VARCHAR(10)) AS TEXT), 10) INTO v_countnumber;
  v_invoiceno := 'R-' || UPPER(v_resellerloginid) || '/' || CAST(v_currentyear AS VARCHAR) || '-' || CAST(v_lastyear AS VARCHAR) || '/' || v_countnumber;
  IF (v_did > 0) THEN
  INSERT INTO tbl_reseller_commission_wallet (did, crtype, totalamount, commissionpercentage, cr, dr, traceno, remarks, servicetype, status, transdate, finalupdate, gstpercentage, invoiceno) VALUES (v_did, 'CR', v_totalpurchasecost, v_resellercommission, (v_totalpurchasecost * v_resellercommission) / 100, 0, v_orderno, 'Wallet credited against Order on Orderid:- ' || v_orderid || '', 2, 1, dbo.FUN_GETCURRENTDATE(), 1, v_gstpercentage, v_invoiceno);
  UPDATE tbl_reseller_commission_invoice_master SET invoiceno = invoiceno + 1 WHERE did = v_did;
  END IF;
  -- SET option (removed)
  IF (0 > 0) THEN
  v_strresult := 'ERROR';
  -- ROLLBACK (removed)
  RETURN;
  END IF;
  -- COMMIT (removed)
END;
$$;


