--
-- Name: usp_managereferal(integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_managereferal(v_plid integer DEFAULT 1) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
BEGIN
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp (RowNumber Int GENERATED BY DEFAULT AS IDENTITY,

TLPMID Int,

PageName text,

PreviewURL text,

PageURL text,

IsDefault Int) ON COMMIT DROP;
  INSERT INTO tmp_temp SELECT tlpmid, pagename, previewurl, REPLACE(REPLACE(pageurl, '{referralcode}/', ''), '{refrralid}', ''), 0 FROM tbl_landingpagemaster WHERE isactive = 1 AND isdeleted = 0;
  UPDATE tmp_temp SET isdefault = 1 WHERE tlpmid = (SELECT tlpmid FROM portal_login WHERE plid = v_plid);
  RETURN QUERY SELECT * FROM tmp_temp;
END;
$$;


--
-- Name: usp_manageresellercommission(character varying, integer, character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_manageresellercommission(v_orderno character varying DEFAULT ''::character varying, v_issettlementprocess integer DEFAULT 0, v_strresult character varying DEFAULT ''::character varying) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_orderstatus INT;
  v_orderbv DECIMAL(18,8);
  v_did INT;
  v_loginid VARCHAR(20);
  v_mode INT;
  v_orderid VARCHAR(50);
  v_balance DECIMAL(18,8);
BEGIN
  -- BEGIN TRAN (removed)
  v_strresult := 'SUCCESS';
  v_orderbv := 0;
  v_did := 0;
  v_loginid := '';
  v_mode := 0;
  v_orderid := '';
  SELECT intstatus, total_bv, loginid, orderid INTO v_orderstatus, v_orderbv, v_loginid, v_orderid FROM tbl_product_order_master WHERE orderno = v_orderno;
  SELECT did INTO v_did FROM tbl_customerlogin WHERE loginid = v_loginid;
  IF (v_orderstatus = 0) THEN
  v_mode := 1;
  ELSE
  IF (v_orderstatus = 7 OR v_orderstatus = 8) THEN
  v_mode := 3;
  END IF;
  END IF;
  IF (v_issettlementprocess = 1) THEN
  v_mode := 2;
  END IF;
  IF (v_did = 0) THEN
  v_strresult := 'RESELLER DOES NOT EXISTS';
  -- COMMIT (removed)
  RETURN;
  END IF;
  IF (v_mode = 1) THEN
  IF NOT EXISTS(SELECT 1 FROM tbl_resellerreleasebvdetails WHERE orderno = v_orderno AND status = 1 AND did = v_did) THEN
  IF NOT EXISTS(SELECT 1 FROM tbl_resellercommission WHERE did = v_did) THEN
  INSERT INTO tbl_resellercommission (did, date, holdcommission, pendingcommission, releasecommission, totalcommission, status, lastupdateon, lastupdatedby) VALUES (v_did, dbo.FUN_GETCURRENTDATE(), 0, v_orderbv, 0, v_orderbv, 1, dbo.FUN_GETCURRENTDATE(), 1);
  INSERT INTO tbl_resellerreleasebvdetails (did, orderno, processdate, orderbv, status) VALUES (v_did, v_orderno, dbo.FUN_GETCURRENTDATE(), v_orderbv, 1);
  ELSE
  UPDATE tbl_resellercommission SET pendingcommission = COALESCE(pendingcommission, 0) + v_orderbv, totalcommission = COALESCE(totalcommission, 0) + v_orderbv WHERE did = v_did;
  INSERT INTO tbl_resellerreleasebvdetails (did, orderno, processdate, orderbv, status) VALUES (v_did, v_orderno, dbo.FUN_GETCURRENTDATE(), v_orderbv, 1);
  END IF;
  END IF;
  END IF;
  IF (v_mode = 2) THEN
  IF NOT EXISTS(SELECT 1 FROM tbl_resellerreleasebvdetails WHERE status = 2 AND did = did AND orderno = v_orderno) THEN
  v_balance := 0;
  UPDATE tbl_resellercommission SET pendingcommission = COALESCE(pendingcommission, 0) - v_orderbv, holdcommission = COALESCE(holdcommission, 0) + v_orderbv WHERE did = v_did;
  UPDATE tbl_resellerreleasebvdetails SET status = 2 WHERE did = v_did AND orderno = v_orderno;
  SELECT holdcommission INTO v_balance FROM tbl_resellercommission WHERE did = v_did;
  INSERT INTO tbl_reseller_commissionwalletstatement (did, date, crdrtype, cr_amount, dr_amount, remarks, status, traceno, old_bal, balance) VALUES (v_did, dbo.FUN_GETCURRENTDATE(), 'CR', v_orderbv, 0, 'Commission credit against order number ' || v_orderid, 0, v_orderno, (v_balance - v_orderbv), v_balance);
  END IF;
  END IF;
  IF (v_mode = 3) THEN
  RETURN QUERY SELECT 3;
  IF NOT EXISTS(SELECT 1 FROM tbl_resellerreleasebvdetails WHERE status = 3 AND did = did AND orderno = v_orderno) THEN
  UPDATE tbl_resellercommission SET pendingcommission = COALESCE(pendingcommission, 0) - v_orderbv, totalcommission = COALESCE(totalcommission, 0) - v_orderbv WHERE did = v_did;
  UPDATE tbl_resellerreleasebvdetails SET status = 3 WHERE did = v_did AND orderno = v_orderno;
  END IF;
  END IF;
  IF (0 > 0) THEN
  v_strresult := 'ERROR';
  -- ROLLBACK (removed)
  RETURN;
  END IF;
  -- COMMIT (removed)
END;
$$;


--
-- Name: usp_managesubscription(integer, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_managesubscription(v_mode integer DEFAULT 2, v_plid integer DEFAULT 0) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_iscameviareferrallink Int;
  v_isdiscountapplicable Int;
BEGIN
  v_iscameviareferrallink := 0;
  v_isdiscountapplicable := 0;
  SELECT COALESCE(MAX(introregno), 0) INTO v_iscameviareferrallink FROM member_master WHERE plid = v_plid;
  IF (v_iscameviareferrallink <> 0 AND v_iscameviareferrallink <> 1) THEN
  v_isdiscountapplicable := 1;
  END IF;
  IF (v_mode = 1) THEN
  RETURN QUERY SELECT kid, pcode, title, image, type, CAST(amount AS DECIMAL(10, 2)) AS amount, dap, pv, bv, distamount, vatinper, cmgamount, directincome, binaryincome, epin_commission, status, roi, noofmonth, noofcities, noofkeywords FROM kit_master WHERE status = 1 ORDER BY amount ASC NULLS FIRST;
  ELSE
  IF (v_mode = 2) THEN
  RETURN QUERY SELECT tepmid, packagename, packagefeaturedescription, isactive, amount, st, totalamount, noofemail, noofdaysvalidity FROM tbl_emailpackmaster WHERE isactive = 1 ORDER BY amount ASC NULLS FIRST;
  ELSE
  IF (v_mode = 3) THEN
  RETURN QUERY SELECT tspmid, packagename, packagefeaturedescription, isactive, amount, totalamount, st, noofsms, noofdaysvalidity FROM tbl_smspackmaster WHERE isactive = 1 ORDER BY amount ASC NULLS FIRST;
  ELSE
  IF (v_mode = 4) THEN
  IF (v_isdiscountapplicable = 0) THEN
  RETURN QUERY SELECT tsmid, subscriptionheading, subscriptiondetails, noofdaysforactivation, issmslimits, noofsms, isemaillimits, noofemail, iswhatsuplimits, noofwhatsupmessage, isnoofwebsitelimits, noofwebsiteselection, isleadlandingpagelimits, noofleadlandingpage, isdiscountapplicable, commentorremark, isactive, status, istrailsubscription, ttsid, price, (0.00) AS discount, (price) AS netpayable FROM tbl_subscriptionmaster WHERE isactive = 1 AND istrailsubscription = 0 AND status = 1 ORDER BY price ASC NULLS FIRST;
  ELSE
  RETURN QUERY SELECT tsmid, subscriptionheading, subscriptiondetails, noofdaysforactivation, issmslimits, noofsms, isemaillimits, noofemail, iswhatsuplimits, noofwhatsupmessage, isnoofwebsitelimits, noofwebsiteselection, isleadlandingpagelimits, noofleadlandingpage, isdiscountapplicable, commentorremark, isactive, status, istrailsubscription, ttsid, price, discount, netpayable FROM tbl_subscriptionmaster WHERE isactive = 1 AND istrailsubscription = 0 AND status = 1 ORDER BY price ASC NULLS FIRST;
  END IF;
  ELSE
  IF (v_mode = 5) THEN
  RETURN QUERY SELECT twupmid, packagename, packagefeaturedescription, isactive, amount, totalamount, st, noofmessages, noofdaysvalidity FROM tbl_whatsuppackmaster WHERE isactive = 1 ORDER BY amount ASC NULLS FIRST;
  ELSE
  IF (v_mode = 6) THEN
  RETURN QUERY SELECT ttbid, packagename, packagefeaturedescription, isactive, amount, totalamount, st, noofdaysvalidity, (CAST(noofhits AS text)) AS noofhits FROM tbl_trafficbooster WHERE isactive = 1 ORDER BY amount ASC NULLS FIRST;
  END IF;
  END IF;
  END IF;
  END IF;
  END IF;
  END IF;
END;
$$;


--
-- Name: usp_managesubscriptionmaster(integer, integer, integer, integer, integer, integer, character varying, character varying, character varying, character varying, character varying, character varying, character varying, character varying, numeric, character varying, character varying, character varying, character varying, character varying, character varying, character varying, character varying, integer, character varying, integer, integer, character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_managesubscriptionmaster(v_mode integer DEFAULT 1, v_plid integer DEFAULT 1, v_startrowindex integer DEFAULT 1, v_maxrows integer DEFAULT 100, v_reqfield integer DEFAULT 0, v_asc integer DEFAULT 1, v_orderbyfield character varying DEFAULT ''::character varying, v_searchfield character varying DEFAULT ''::character varying, v_searchvalue character varying DEFAULT ''::character varying, v_fromdate character varying DEFAULT ''::character varying, v_todate character varying DEFAULT ''::character varying, v_username character varying DEFAULT ''::character varying, v_purchagedate character varying DEFAULT ''::character varying, v_allpackagename character varying DEFAULT ''::character varying, v_totalpayableamount numeric DEFAULT 0.00, v_paymentmode character varying DEFAULT ''::character varying, v_bankname character varying DEFAULT ''::character varying, v_branchname character varying DEFAULT ''::character varying, v_referencenumber character varying DEFAULT ''::character varying, v_referencedate character varying DEFAULT ''::character varying, v_status character varying DEFAULT ''::character varying, v_loginid character varying DEFAULT ''::character varying, v_transid character varying DEFAULT ''::character varying, v_recordcount integer DEFAULT 0, v_mobile character varying DEFAULT ''::character varying, v_isdownload integer DEFAULT 0, v_userid integer DEFAULT 0, v_package character varying DEFAULT ''::character varying) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_regno BIGINT;
  v_sqlquery text;
  v_modestatus varchar(10);
  v_newusername VARCHAR(200);
BEGIN
  -- SET option (removed)
  v_sqlquery := '';
  v_modestatus := '0';
  v_sqlquery := '';
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp (Rownumber Int GENERATED BY DEFAULT AS IDENTITY,LoginID varchar(100),
TASMID VArchar(200),
TotalPayableAmount decimal(10,2),
PaymentMode varchar(400),
ModeName varchar(200),
CommentORRemark text,
RegNo Varchar(200),
ImageName text,
BankName varchar(200),
BranchName varchar(200),
ReferenceDate Varchar(100),
ReferenceNumber varchar(50),
WalletId varchar(50),
TransactionPassword varchar(100),
GoogleAuthenticationCode varchar(100),
ShortAllPackageName varchar(100),
AllPackageName varchar(100),
PuchaseDate Varchar(30),
AllPackageId varchar(100),
AllPackageType varchar(100),
AllPackageAmount varchar(50),
Status varchar(50),
Transaction_id varchar(250),
invoice_no varchar(50),
MOBILE varchar(50),
USERNAME varchar(500)) ON COMMIT DROP;
  IF (v_mode = 1) THEN
  v_sqlquery := v_sqlquery || ('INSERT INTO #TEMP Select PL.LoginID,TASMID,TotalPayableAmount,
	(Case When PaymentMode='''' Then ''N/A'' Else PaymentMode End)As PaymentMode,
	(Case When ModeName='''' Then ''N/A'' Else ModeName End)As ModeName,CommentORRemark,TASM.RegNo,
	TASM.ImageName,(Case When BankName='''' Then ''N/A'' Else BankName End)As BankName,
	(Case When BranchName='''' Then ''N/A'' Else BranchName End)As BranchName,
	(Case When ReferenceDate='''' Then ''N/A'' Else Convert(Varchar(11),ReferenceDate,106) End)As ReferenceDate,
	(Case When ReferenceNumber='''' Then ''N/A'' Else ReferenceNumber End)As ReferenceNumber,
	WalletId,TransactionPassword,GoogleAuthenticationCode,
	(Case When Len(AllPackageName)>30 Then SUBSTRING(AllPackageName,0,30) + ''... '' Else AllPackageName   End) as  ShortAllPackageName,AllPackageName,
	Convert(VARCHAR(19),PuchaseDate)As PuchaseDate,AllPackageId,AllPackageType,AllPackageAmount,
	(Case When TASM.IsApproved=1 Then ''Cleared'' When TASM.IsApproved=2 Then ''Rejected'' WHEN  ISNULL(TASM.IsApproved,0)=0  THEN''Pending'' End)As Status,
	isnull(TASM.Transaction_id,'''') as Transaction_id,isnull(TASM.invoice_no,''''),ISNULL(pl.phone,''''),pl.username
	From Tbl_AllSubscriptionMaster TASM Inner Join Portal_Login Pl On Pl.PLID=TASM.PLID Where Pl.Status=1 ');
  IF (v_reqfield <> 0) THEN
  v_sqlquery := v_sqlquery || (' AND PaymentMode = ' || CAST(v_reqfield AS VARCHAR) || ' ');
  END IF;
  IF (v_fromdate <> '' OR v_todate <> '') THEN
  IF (v_fromdate <> '') THEN
  v_sqlquery := v_sqlquery || (' AND CONVERT(DATE,TASM.PuchaseDate,103) >= CONVERT(Date,''' || v_fromdate || ''',103) ');
  END IF;
  IF (v_todate <> '') THEN
  v_sqlquery := v_sqlquery || (' AND CONVERT(DATE,TASM.PuchaseDate,103) <= CONVERT(Date,''' || v_todate || ''',103) ');
  END IF;
  ELSE
  IF (v_fromdate <> '' AND v_todate <> '') THEN
  v_sqlquery := v_sqlquery || (' AND CONVERT(DATE,TASM.PuchaseDate,103) BETWEEN CONVERT(DATE,''' || v_fromdate || ''',103) AND CONVERT(DATE,''' || v_todate || ''',103) ');
  END IF;
  END IF;
  IF (v_searchvalue = 'email') THEN
  IF (v_searchfield <> '') THEN
  v_sqlquery := v_sqlquery || (' AND PL.LoginID LIKE ''%' || v_searchfield || '%'' ');
  END IF;
  END IF;
  IF (v_searchvalue = 'transid') THEN
  IF (v_searchfield <> '') THEN
  v_sqlquery := v_sqlquery || (' AND TASM.Transaction_id LIKE ''%' || v_searchfield || '%'' ');
  END IF;
  END IF;
  IF (v_searchvalue = 'username') THEN
  IF (v_searchfield <> '') THEN
  IF (EXISTS(SELECT 1 FROM portal_login WHERE username = v_searchvalue)) THEN
  v_sqlquery := v_sqlquery || (' AND PL.USERNAME LIKE ''%' || v_searchfield || '%''');
  ELSE
  IF (EXISTS(SELECT 1 FROM portal_login_history WHERE username = v_searchfield)) THEN
  v_newusername := '';
  SELECT (SELECT username FROM portal_login WHERE plid IN (SELECT plid FROM portal_login_history WHERE username = v_searchfield)) INTO v_newusername;
  v_sqlquery := v_sqlquery || (' AND PL.USERNAME LIKE ''%' || v_newusername || '%''');
  ELSE
  v_sqlquery := v_sqlquery || ' AND PL.USERNAME LIKE ''%' || v_searchfield || '%'' ';
  END IF;
  END IF;
  END IF;
  END IF;
  IF (v_orderbyfield = 'datedesc') THEN
  v_sqlquery := v_sqlquery || ' ORDER BY TASM.PuchaseDate DESC ';
  END IF;
  IF (v_orderbyfield = 'dateasc') THEN
  v_sqlquery := v_sqlquery || ' ORDER BY TASM.PuchaseDate ASC ';
  END IF;
  IF (v_status <> '') THEN
  v_sqlquery := v_sqlquery || (' AND iSNULL(TASM.IsApproved,''0'') = ''' || v_status || ''' ');
  END IF;
  IF (v_loginid <> '') THEN
  v_sqlquery := v_sqlquery || ' AND ISNULL(pl.LoginID,'''') LIKE ''%' || v_loginid || '%''';
  END IF;
  IF (v_mobile <> '') THEN
  v_sqlquery := v_sqlquery || ' AND ISNULL(Pl.PHONE,'''') LIKE ''%' || v_mobile || '%''';
  END IF;
  IF (v_paymentmode <> '') THEN
  v_sqlquery := v_sqlquery || (' AND TASM.PaymentMode = ' || CAST(v_paymentmode AS VARCHAR) || ' ');
  END IF;
  IF (v_package <> '') THEN
  v_sqlquery := v_sqlquery || ' AND ISNULL(+''~''+ AllPackageName +''~'','''') LIKE ''%~' || v_package || '~%''';
  END IF;
  v_sqlquery := v_sqlquery || ' order by TASM.PuchaseDate desc';
  EXECUTE v_sqlquery;
  IF (v_isdownload = 0) THEN
  RETURN QUERY SELECT * FROM tmp_temp WHERE rownumber BETWEEN v_startrowindex AND v_maxrows;
  ELSE
  RETURN QUERY SELECT rownumber AS "s.no.", referencedate AS date, transaction_id AS "order id", loginid AS "email id", shortallpackagename AS package, totalpayableamount AS amount, modename AS "payment mode", status AS details FROM tmp_temp;
  INSERT INTO tbl_exceltrackingreport (report_name, file_name, type, download_by, download_date) VALUES ('Received Payment', 'ReceivedPayment_List.xls', 1, v_userid, CURRENT_TIMESTAMP);
  END IF;
  SELECT COUNT(1) INTO v_recordcount FROM tmp_temp;
  RETURN QUERY SELECT v_recordcount AS recordcount;
  DROP TABLE IF EXISTS tmp_temp;
  -- SET option (removed)
  END IF;
  IF (v_mode = 2) THEN
  RETURN QUERY SELECT ROW_NUMBER() OVER (ORDER BY tasmid DESC NULLS LAST) AS sno, pl.username, tasmid, totalpayableamount, paymentmode, modename, commentorremark, tasm.regno, tasm.imagename, bankname, branchname, referencedate, referencenumber, walletid, transactionpassword, googleauthenticationcode, REPLACE(allpackagename, '~', ',') AS allpackagename, CAST(TO_CHAR(puchasedate, 'DD TMMon YYYY') AS VARCHAR(11)) AS puchasedate, allpackageid, allpackagetype, allpackageamount, (CASE WHEN tasm.isapproved = 1 THEN 'Cleared' WHEN tasm.isapproved = 2 THEN 'Rejected' ELSE 'Pending' END) AS status FROM tbl_allsubscriptionmaster AS tasm INNER JOIN portal_login AS pl ON pl.plid = tasm.plid WHERE pl.status = 1 AND tasm.plid = v_plid;
  END IF;
END;
$$;


--
-- Name: usp_managesystemenquiry(character varying, text, text, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_managesystemenquiry(v_mobile character varying DEFAULT ''::character varying, v_emailid text DEFAULT ''::text, v_lookingfor text DEFAULT ''::text, INOUT v_intresult integer DEFAULT 0) RETURNS integer
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_name text;
  v_message text;
  v_status Int;
  v_isactive Int;
BEGIN
  -- BEGIN TRAN (removed)
  BEGIN
  v_name := 'N/A';
  v_message := 'N/A';
  v_status := 1;
  v_isactive := 1;
  INSERT INTO tbl_systemenquiry (name, mobile, emailid, lookingfor, message, status, isactive) VALUES (v_name, v_mobile, v_emailid, v_lookingfor, v_message, v_status, v_isactive);
  v_intresult := 1;
  -- COMMIT (removed)
  RETURN;
  EXCEPTION WHEN OTHERS THEN
  v_intresult := 0;
  -- ROLLBACK (removed)
  RETURN;
  END;
  -- COMMIT (removed)
END;
$$;


