--
-- Name: usp_managetrafficbooster(integer, integer, integer, integer, text, integer, text, text, integer, integer, integer, integer, integer, text, text, text, integer, bigint, text, text, integer, integer, integer, integer, integer, integer, integer, integer, integer, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_managetrafficbooster(v_mode integer DEFAULT 1, v_tatbid integer DEFAULT 137, v_plid integer DEFAULT 0, v_urltype integer DEFAULT 0, v_url text DEFAULT ''::text, v_tvhmid integer DEFAULT 0, v_fromdate text DEFAULT ''::text, v_todate text DEFAULT ''::text, v_ispublished integer DEFAULT 0, v_issaved integer DEFAULT 0, v_isactive integer DEFAULT 0, v_status integer DEFAULT 0, v_intresultoutput integer DEFAULT 0, v_sharesource text DEFAULT ''::text, v_imgname text DEFAULT ''::text, v_targatedcity text DEFAULT ''::text, v_campaigntype integer DEFAULT 0, v_noofclicks bigint DEFAULT 0, v_title text DEFAULT ''::text, v_description text DEFAULT ''::text, v_city integer DEFAULT 0, v_category integer DEFAULT 0, v_keyword integer DEFAULT 0, v_startrowindex integer DEFAULT 1, v_maxrows integer DEFAULT 100, v_catid integer DEFAULT 0, v_kid integer DEFAULT 0, v_ctid integer DEFAULT 0, v_intresult integer DEFAULT 0, v_targetedcountry integer DEFAULT 0) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_query1 text;
  v_minindex INT;
  v_maxindex INT;
BEGIN
  IF (v_mode = 1) THEN
  DROP TABLE IF EXISTS tmp_temp1;
  CREATE TEMP TABLE tmp_temp1 (RowNumber BigInt,
TATBID int,
PLID int,
URLType text,
City text,
Category text,
Keyword text,
URL text,
TVHMID int,
FromDate text,
ToDate text,
IsPublished int,
IsSaved Int,
IsActive int,
Status int,
ActualStatus Varchar(100),
AddedDate Varchar(100),
TotalNoOfHits Bigint,
TotalNoOfUniqueHits Bigint,
CampaignType Varchar(500),
TargetedAudience Varchar(500),
SaveStatus Varchar(500),
NoOfClicks BigInt,
TotalNoOfShare BigInt,
Title text,
Description text,
CATID int,
KID int,
CTID int,
CID int,
TargetedID int,
Utype int) ON COMMIT DROP;
  v_query1 := '';
  v_minindex := (v_startrowindex - 1) * v_maxrows + 1;
  v_maxindex := v_startrowindex * v_maxrows;
  v_query1 := v_query1 || (' INSERT INTO #Temp1 SELECT ROW_NUMBER()OVER(ORDER BY TATBID DESC) AS ROWNUMBER,TATBID,PLID,
(Case When UrlType=1 Then ''Business Listing'' 
When UrlType=2 Then ''Deals'' 
When UrlType=3 Then ''Landing Page'' 
When UrlType=4 Then ''External URL''
When UrlType=5 Then ''Images''
When UrlType=6 Then ''Video'' End)As URLType,
(CASE WHEN ISNULL(CITYNAME,'''')='''' THEN ''N/A'' ELSE (CITYNAME) END)AS CITY,
(CASE WHEN ISNULL(CATNAME,'''')='''' THEN ''N/A'' ELSE (CATNAME) END)AS CATEGORY,
IsNull(KEYWORDNAME,''N/A'')as Keyword,URL,TATB.TVHMID,
Convert(Varchar(11),FromDate,105)As FromDate,
Convert(Varchar(11),ToDate,105)As ToDate,
ISPUBLISHED,ISSAVED,TATB.ISACTIVE,TATB.STATUS,
(CASE WHEN ISPUBLISHED=1 THEN ''PUBLISHED'' ELSE ''SAVE'' END)AS ACTUALSTATUS,
CONVERT(VARCHAR(11),ADDEDDATE,105)AS ADDEDDATE,
TOTALNOOFHITS,TOTALNOOFUNIQUEHITS,
(Case IsNull(CampaignType,0) When 0 Then ''N/A'' When 1 Then ''Share''  When 2 Then ''View'' When 3 Then ''View & Share'' Else ''N/A'' End) As CampaignType,
(Case When Isnull(TargetedCity,'''') != '''' Then ''Selected City'' When Isnull(TargetedCountry,'''')=''96'' Then ''Entire Country'' Else ''N/A'' End) As TargetedAudience,
(Case When IsPublished=1 THEN ''Published'' When(IsSaved=1 and IsPublished=0) Then ''Saved'' End) As SaveStatus,NoOfClicks,TotalNoOfShare,TATB.Title,TATB.Description,TATB.CATID,TATB.KID,TATB.CTID,(CampaignType) as CID,(TargetedCity) as TargetedID,(URLType
) as Utype
FROM TBL_ADDTRAFFICBOOSTER TATB LEFT JOIN City C On C.CTID=TATB.CTID
LEFT JOIN KEYWORD_MASTER KM ON KM.KMID=TATB.KID
LEFT JOIN PRODUCT_CATEGORY PC ON Pc.CATID=TATB.CATID
Where TATB.IsActive=1 AND Cast(PLID as Varchar(20))=' || CAST(v_plid AS VARCHAR(20)) || ' AND IsShareType=1');
  IF (v_fromdate <> '' AND v_todate <> '') THEN
  v_query1 := v_query1 || (' And Convert(Varchar,AddedDate,105) Between ''' || v_fromdate || ''' And ''' || v_todate || '''');
  ELSE
  IF (v_fromdate <> '' OR v_todate <> '') THEN
  IF (v_fromdate <> '') THEN
  v_query1 := v_query1 || (' And Convert(Varchar,AddedDate,105) = ''' || v_fromdate || ''' ');
  END IF;
  IF (v_todate <> '') THEN
  v_query1 := v_query1 || (' And Convert(Varchar,AddedDate,105) = ''' || v_todate || ''' ');
  END IF;
  END IF;
  END IF;
  IF (v_url <> '') THEN
  v_query1 := v_query1 || (' AND URL Like ''%' || v_url || '%''');
  END IF;
  IF (v_catid <> 0) THEN
  v_query1 := v_query1 || (' AND TATB.CATID=' || CAST(v_catid AS text) || '');
  END IF;
  IF (v_kid <> 0) THEN
  v_query1 := v_query1 || (' AND TATB.KID=' || CAST(v_kid AS text) || '');
  END IF;
  IF (v_ctid <> 0) THEN
  v_query1 := v_query1 || (' AND TATB.CTID=' || CAST(v_ctid AS text) || '');
  END IF;
  IF (v_tatbid > 0) THEN
  v_query1 := v_query1 || (' AND TATBID=' || CAST(v_tatbid AS text) || '');
  END IF;
  EXECUTE v_query1;
  RETURN QUERY SELECT * FROM tmp_temp1 WHERE rownumber BETWEEN v_startrowindex AND v_maxrows;
  RETURN QUERY SELECT COUNT(1) AS totalrows FROM tmp_temp1;
  DROP TABLE IF EXISTS tmp_temp1;
  ELSE
  IF (v_mode = 2) THEN
  BEGIN
  INSERT INTO tbl_addtrafficbooster (plid, urltype, url, tvhmid, fromdate, todate, ispublished, issaved, isactive, status, addeddate, catid, kid, ctid, noofclicks, campaigntype, sharesource, targetedcountry, targetedcity, targetedarea, imagename, isapprovedbyadmin, title, description) VALUES (v_plid, v_urltype, v_url, v_tvhmid, TO_DATE(v_fromdate, 'DD-MM-YYYY'), TO_DATE(v_todate, 'DD-MM-YYYY'), v_ispublished, v_issaved, v_isactive, v_status, CURRENT_TIMESTAMP, v_catid, v_kid, v_ctid, v_noofclicks, v_campaigntype, v_sharesource, v_targetedcountry, v_targatedcity, '', v_imgname, 1, v_title, v_description);
  v_intresultoutput := 1;
  v_intresult := 1;
  RETURN;
  EXCEPTION WHEN OTHERS THEN
  v_intresultoutput := 0;
  v_intresult := 0;
  RETURN;
  END;
  ELSE
  IF (v_mode = 3) THEN
  BEGIN
  UPDATE tbl_addtrafficbooster SET plid = v_plid, urltype = v_urltype, url = v_url, tvhmid = v_tvhmid, fromdate = v_fromdate, todate = v_todate, catid = v_catid, kid = v_kid, ctid = v_ctid, ispublished = v_ispublished, issaved = v_issaved, isactive = v_isactive, status = v_status, addeddate = CURRENT_TIMESTAMP, noofclicks = v_noofclicks, campaigntype = v_campaigntype, sharesource = v_sharesource, targetedcountry = v_targetedcountry, targetedcity = (CASE WHEN v_targatedcity = '0' THEN targetedcity ELSE v_targatedcity END), targetedarea = '', imagename = (CASE WHEN v_imgname = '' THEN imagename ELSE v_imgname END), isapprovedbyadmin = 1, title = v_title, description = v_description WHERE tatbid = v_tatbid;
  v_intresultoutput := 2;
  v_intresult := 2;
  RETURN;
  EXCEPTION WHEN OTHERS THEN
  v_intresultoutput := 0;
  v_intresult := 0;
  RETURN;
  END;
  END IF;
  END IF;
  END IF;
END;
$$;


--
-- Name: usp_manageusersmsemailhitsaccount(integer, integer, character varying, integer, integer, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_manageusersmsemailhitsaccount(v_mode integer DEFAULT 1, v_plid integer DEFAULT 2532, v_loginid character varying DEFAULT ''::character varying, v_startrowindex integer DEFAULT 1, v_maxrows integer DEFAULT 100, v_intresult integer DEFAULT 0) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_totalquentity BigInt;
  v_remainquentity BigInt;
  v_flushquentity BigInt;
  v_query text;
  v_query1 text;
BEGIN
  -- SET option (removed)
  v_totalquentity := 0;
  v_remainquentity := 0;
  v_flushquentity := 0;
  v_query := '';
  v_query1 := '';
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp (RowNumber Int GENERATED BY DEFAULT AS IDENTITY,
PLID Int,
TotalCredited BigInt,
TotalUsed BigInt,
TotalRemain BigInt,
TotalFlush BigInt,
LOGINID Varchar(100) Default(''),
UserStatus varchar(100) Default('')) ON COMMIT DROP;
  IF (v_mode = 1) THEN
  v_query := 'Insert Into #Temp Select PLID,ISNULL(SUM(AllocatedNoOfSms),0),
ISNULL((SUM(AllocatedNoOfSms)-SUM(RemainNoOfSMS)),0),ISNULL(SUM(RemainNoOfSMS),0),
ISNULL(SUM(FlushNoOFSMS),0),''N/A'',''N/A'' 
From Tbl_MemberSubscriptionAccount Group By PLID Having PLID<>0';
  IF (v_plid <> 0) THEN
  v_query := v_query || 'AND PLID=' || CAST(v_plid AS VARCHAR(10)) || '';
  END IF;
  EXECUTE v_query;
  SELECT SUM(COALESCE((noofsms), 0)), SUM(COALESCE(remainnoofsms, 0)), SUM(COALESCE(flushnoofsms, 0)) INTO v_totalquentity, v_remainquentity, v_flushquentity FROM tmp_temp AS temp INNER JOIN tbl_usersmspackmaster AS tutbm ON temp.plid = tutbm.plid;
  UPDATE temp SET totalcredited = temp.totalcredited + COALESCE((v_totalquentity), 0), totalused = temp.totalused + COALESCE(((v_totalquentity) - (v_remainquentity)), 0), totalremain = temp.totalremain + COALESCE((v_remainquentity), 0), totalflush = temp.totalflush + COALESCE((v_flushquentity), 0) FROM tmp_temp AS temp INNER JOIN tbl_usersmspackmaster AS tuspm ON temp.plid = tuspm.plid;
  END IF;
  IF (v_mode = 2) THEN
  v_query := 'Insert Into #Temp Select PLID,ISNULL(SUM(AllocatedNoOfEmail),0),ISNULL((SUM(AllocatedNoOfEmail)-SUM(RemainNoOfEmail)),0),
ISNULL(SUM(RemainNoOfEmail),0),ISNULL(SUM(FlushNoOFEmail),0),''N/A'',''N/A'' From Tbl_MemberSubscriptionAccount Group By PLID Having PLID<>0';
  IF (v_plid <> 0) THEN
  v_query := v_query || 'AND PLID=' || CAST(v_plid AS VARCHAR(10)) || '';
  END IF;
  EXECUTE v_query;
  SELECT SUM(COALESCE((noofemail), 0)), SUM(COALESCE(remainnoofemail, 0)), SUM(COALESCE(flushnoofemail, 0)) INTO v_totalquentity, v_remainquentity, v_flushquentity FROM tmp_temp AS temp INNER JOIN tbl_useremailpackmaster AS tutbm ON temp.plid = tutbm.plid;
  UPDATE temp SET totalcredited = temp.totalcredited + COALESCE((v_totalquentity), 0), totalused = temp.totalused + COALESCE(((v_totalquentity) - (v_remainquentity)), 0), totalremain = temp.totalremain + COALESCE((v_remainquentity), 0), totalflush = temp.totalflush + COALESCE((v_flushquentity), 0) FROM tmp_temp AS temp INNER JOIN tbl_useremailpackmaster AS tuepm ON temp.plid = tuepm.plid;
  END IF;
  IF (v_mode = 3) THEN
  v_query := 'Insert Into #Temp Select PLID,ISNULL(SUM(AllocatedNoOfWhatsUpMessage),0),
ISNULL((SUM(AllocatedNoOfWhatsUpMessage)-SUM(RemainNoOfWhatsUpMessage)),0),
ISNULL(SUM(RemainNoOfWhatsUpMessage),0),ISNULL(SUM(FlushNoOFWhatsUpMessage),0),''N/A'',''N/A'' 
From Tbl_MemberSubscriptionAccount
Group By PLID Having PLID<>0';
  IF (v_plid <> 0) THEN
  v_query := v_query || 'AND PLID=' || CAST(v_plid AS VARCHAR(10)) || '';
  END IF;
  EXECUTE v_query;
  SELECT SUM(COALESCE((noofmessages), 0)), SUM(COALESCE(remainnoofmessages, 0)), SUM(COALESCE(flushnoofwhatsupmessage, 0)) INTO v_totalquentity, v_remainquentity, v_flushquentity FROM tmp_temp AS temp INNER JOIN tbl_userwhatsapppackmaster AS tutbm ON temp.plid = tutbm.plid;
  UPDATE temp SET totalcredited = temp.totalcredited + COALESCE((v_totalquentity), 0), totalused = temp.totalused + COALESCE(((v_totalquentity) - (v_remainquentity)), 0), totalremain = temp.totalremain + COALESCE((v_remainquentity), 0), totalflush = temp.totalflush + COALESCE((v_flushquentity), 0) FROM tmp_temp AS temp INNER JOIN tbl_userwhatsapppackmaster AS tuwpm ON temp.plid = tuwpm.plid;
  END IF;
  IF (v_mode = 4) THEN
  v_query := 'Insert Into #Temp Select PLID,ISNULL(SUM(AllocatedNoOfHits),0),
ISNULL((SUM(AllocatedNoOfHits)-SUM(RemainNoOfHits)),0),
ISNULL(SUM(RemainNoOfHits),0),ISNULL(SUM(FlushNoOFHits),0),''N/A'',''N/A'' 
From Tbl_MemberSubscriptionAccount Group By PLID Having PLID<>0';
  IF (v_plid <> 0) THEN
  v_query := v_query || 'AND PLID=' || CAST(v_plid AS VARCHAR(10)) || '';
  END IF;
  EXECUTE v_query;
  SELECT SUM(COALESCE((noofhits), 0)), SUM(COALESCE(remainnoofhits, 0)), SUM(COALESCE(flushnoofhits, 0)) INTO v_totalquentity, v_remainquentity, v_flushquentity FROM tmp_temp AS temp INNER JOIN tbl_usertrafficbooster AS tutbm ON temp.plid = tutbm.plid;
  UPDATE temp SET totalcredited = temp.totalcredited + COALESCE(v_totalquentity, 0), totalused = temp.totalused + COALESCE(((v_totalquentity) - (v_remainquentity)), 0), totalremain = temp.totalremain + COALESCE((v_remainquentity), 0), totalflush = temp.totalflush + COALESCE((v_flushquentity), 0) FROM tmp_temp AS temp INNER JOIN tbl_usertrafficbooster AS tutbm ON temp.plid = tutbm.plid;
  END IF;
  UPDATE temp SET loginid = COALESCE(pl.loginid, 'N/A'), userstatus = COALESCE((CASE WHEN pl.active = 1 THEN 'Active' ELSE 'InActive' END), 'N/A') FROM tmp_temp AS temp INNER JOIN portal_login AS pl ON pl.plid = temp.plid WHERE COALESCE(temp.plid, 0) <> 0;
  v_query1 := 'Select * From #Temp ';
  IF (v_startrowindex <> 0 AND v_maxrows <> 0) THEN
  v_query1 := v_query1 || ' Where RowNumber Between ''' || CAST(v_startrowindex AS VARCHAR) || ''' And ''' || CAST(v_maxrows AS VARCHAR) || '''';
  END IF;
  IF (v_loginid <> '') THEN
  v_query1 := v_query1 || ' And LOGINID Like ''%' || v_loginid || '%'' ';
  END IF;
  EXECUTE v_query1;
  RETURN QUERY SELECT COUNT(1) AS totalrows FROM tmp_temp;
  SELECT COALESCE(COUNT(1), 0) INTO v_intresult FROM tmp_temp;
  DROP TABLE IF EXISTS tmp_temp;
  -- SET option (removed)
END;
$$;


--
-- Name: usp_mannualinstantipnnotification(integer, integer, character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_mannualinstantipnnotification(v_trhid integer DEFAULT 0, v_empid integer DEFAULT 0, INOUT v_stroutput character varying DEFAULT ''::character varying) RETURNS character varying
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_req_id VARCHAR(100);
  v_plid INT;
BEGIN
  BEGIN
  v_req_id := '';
  v_plid := 0;
  SELECT api_reqid, plid INTO v_req_id, v_plid FROM tbl_rechargehistory WHERE trhid = v_trhid;
  IF EXISTS(SELECT 1 FROM tbl_rechargehistory WHERE trhid = v_trhid AND status = 1) THEN
  v_stroutput := 'Recharge Successed.';
  ELSE
  IF EXISTS(SELECT 1 FROM tbl_rechargehistory WHERE trhid = v_trhid AND status = 4) THEN
  v_stroutput := 'Already Refunded.';
  END IF;
  END IF;
  INSERT INTO tbl_rechargemannualipnresponse (activitybyempid, activitydateandtime, req_id, plid, trhid) VALUES (v_empid, dbo.FUN_GETCURRENTDATE(), v_req_id, v_plid, v_trhid);
  v_stroutput := 'Success';
  EXCEPTION WHEN OTHERS THEN
  v_stroutput := 'Error';
  END;
END;
$$;


--
-- Name: usp_manual_location(integer, integer, character varying, boolean, character varying, character varying, integer, integer, character varying, character varying, character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_manual_location(v_startrowindex integer, v_maxrows integer, v_orderbyfield character varying, v_asc boolean, v_searchfield character varying, v_searchvalue character varying, v_mode integer, v_recordcount integer, v_cid character varying, v_fromdate character varying, v_todate character varying) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_sqlquery text;
BEGIN
  -- SET option (removed)
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp (rowNumber int,
aid bigint,
companyname varchar(150),
doc varchar(150),
countryName varchar(150),
stateName varchar(100),
cityName varchar(150),
areaname varchar(200),
pincode varchar(150)) ON COMMIT DROP;
  v_sqlquery := '';
  v_sqlquery := 'insert into #temp select ROW_NUMBER() OVER(ORDER BY pm.pmid desc) as rowNumber, pm.pmid,pm.companyname,(convert(varchar(20),pm.doc,105)+'' ''+(convert(varchar(5),pm.doc,108))) as doc,isnull((case when C.countryName=''UNITED STATES'' 
 then ''US'' when C.countryName=''UNITED KINGDOM'' then ''UK'' else  C.countryName end  ),''-'') as countryName ,
isnull(s.stateName,''-'') as statename,isnull(ct.cityName,''-'') as cityname,isnull(pm.areaname,''-'') as  areaname,pm.pincode from 
portal_master pm  inner join 
 CITY ct on ct.ctid=pm.ctid left join STATE  s on s.SID=pm.sid left join
  COUNTRY c on c.cid=pm.cid where pm.ismannual=1 ';
  IF (v_fromdate = '' OR v_todate = '') THEN
  IF (v_fromdate <> '') THEN
  v_sqlquery := v_sqlquery || ' and convert(date,pm.doc,103)= replace(convert(date,''' || v_fromdate || ''',103),''/'',''-'') ';
  END IF;
