--
-- Name: usp_mapdistributor_paymode_setting(character varying, integer, integer, integer, integer, numeric, character varying, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_mapdistributor_paymode_setting(v_mode character varying DEFAULT 'update'::character varying, v_did integer DEFAULT 1, v_pmid integer DEFAULT 1, v_mdpid integer DEFAULT 1, v_active integer DEFAULT 1, v_percentage numeric DEFAULT 0, v_stresult character varying DEFAULT ''::character varying, v_empid integer DEFAULT 1) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_count int;
  v_addattributeget varchar(300);
  v_pmidtemp int;
  v_query12 text;
  v_pm_code varchar(50);
BEGIN
  -- BEGIN TRAN (removed)
  v_count := 0;
  v_addattributeget := '';
  v_pmidtemp := 0;
  v_query12 := '';
  v_pm_code := '';
  IF (v_mode = 'add') THEN
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp (rowNumber int,PMID int,PM_Code varchar(100)) ON COMMIT DROP;
  v_query12 := 'insert into #temp SELECT  ROW_NUMBER() over (order by PMID ASC) as rowNumber,PMID,PM_Code  from Pay_Mode ';
  EXECUTE v_query12;
  SELECT COUNT(1) INTO v_count FROM tmp_temp;
  IF NOT EXISTS(SELECT 1 FROM tbl_map_distributor_paymode WHERE did = v_did) THEN
  WHILE (v_count > 0) LOOP
  SELECT pmid, pm_code INTO v_pmidtemp, v_pm_code FROM tmp_temp WHERE rownumber = v_count;
  INSERT INTO tbl_map_distributor_paymode VALUES (v_pmidtemp, v_did, 0, dbo.FUN_GETCURRENTDATE(), NULL, 0, 1);
  v_pmidtemp := 0;
  v_pm_code := '';
  v_count := v_count - 1;
  END LOOP;
  END IF;
  DROP TABLE IF EXISTS tmp_temp;
  END IF;
  IF (v_mode = 'update') THEN
  IF EXISTS(SELECT 1 FROM tbl_map_distributor_paymode WHERE mdpid = v_mdpid AND pmid = v_pmid AND did = v_did AND percentage = v_percentage) THEN
  UPDATE tbl_map_distributor_paymode SET percentage = v_percentage, modifydate = CURRENT_TIMESTAMP, active = v_active, emp_id = v_empid WHERE mdpid = v_mdpid AND pmid = v_pmid AND did = v_did;
  ELSE
  INSERT INTO tbl_map_distributor_paymode_history (mdpid, pmid, did, percentage, createddate, modifydate, emp_id, active) SELECT mdpid, pmid, did, percentage, createddate, modifydate, emp_id, active FROM tbl_map_distributor_paymode WHERE mdpid = v_mdpid AND pmid = v_pmid AND did = v_did;
  UPDATE tbl_map_distributor_paymode SET percentage = v_percentage, modifydate = CURRENT_TIMESTAMP, active = v_active, emp_id = v_empid WHERE mdpid = v_mdpid AND pmid = v_pmid AND did = v_did;
  END IF;
  v_stresult := 'update successfully data!';
  RETURN QUERY SELECT v_stresult;
  END IF;
  -- COMMIT (removed)
END;
$$;


--
-- Name: usp_master_commission(integer, integer, integer, character varying, character varying, integer, character varying, character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_master_commission(v_mode integer DEFAULT 0, v_startrowindex integer DEFAULT 1, v_maxrows integer DEFAULT 100, v_fromdate character varying DEFAULT ''::character varying, v_todate character varying DEFAULT ''::character varying, v_totalcount integer DEFAULT 0, v_searchfield character varying DEFAULT ''::character varying, v_searchvalue character varying DEFAULT ''::character varying) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_minindex INT;
  v_maxindex INT;
  v_query text;
BEGIN
  v_minindex := (v_startrowindex - 1) * v_maxrows + 1;
  v_maxindex := v_startrowindex * v_maxrows;
  IF (v_mode = 0) THEN
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp (ROWNUMBER BIGINT GENERATED BY DEFAULT AS IDENTITY, 
	TVRCSID INT,       
	OPERATORNAME VARCHAR(100),      
	OPERATORCODE VARCHAR(100),	
	SERVICENAME VARCHAR(100),
	BILLTYPE VARCHAR(100),
	COMMISSION DECIMAL(18,2),
	SURCHARGE DECIMAL(18,2),
	STATUS INT,
	CREATEDATE VARCHAR(100),
	ACTIVE Varchar(100),
	VENDORNAME varchar(100),
	TVID INT,
	VENDORCODE VARCHAR(100),
	Rank INT) ON COMMIT DROP;
  v_query := 'INSERT INTO #TEMP SELECT TRCS.TVRCSID,TRCS.OPERATORNAME,TRCS.OPERATORCODE,TRCS.SERVICENAME,TRCS.BILLTYPE,
TRCS.COMMISSION,TRCS.SURCHARGE,TRCS.STATUS,TRCS.CREATEDATE,
(Case When TRCS.ACTIVE=1 Then ''Active'' ELSE ''Deactive'' END),TV.VENDORNAME,TRCS.TVID,TV.VENDORCODE,
Dense_rank() OVER (order by SERVICENAME desc ) 
FROM TBL_VENDOR_RECHARGE_COMMISSION_STRUCTURE TRCS 
LEFT JOIN TBL_VENDORS TV   ON TRCS.TVID=TV.TVID 
WHERE 1=1 ';
  IF ((v_fromdate <> '') AND (v_todate = '')) THEN
  v_query := v_query || ' AND CONVERT(DATE, TRCS.CREATEDATE, 105) BETWEEN  CONVERT(DATE, ''' || v_fromdate || ''', 105) AND  CONVERT(DATE, DBO.FUN_GETCURRENTDATE(), 105)';
  END IF;
  IF ((v_fromdate = '') AND (v_todate <> '')) THEN
  v_query := v_query || 'AND CONVERT(DATE, TRCS.CREATEDATE, 105) BETWEEN  CONVERT(DATE, ''' || v_todate || ''', 105) AND  CONVERT(DATE, DBO.FUN_GETCURRENTDATE(), 105)';
  END IF;
  IF ((v_fromdate <> '') AND (v_todate <> '')) THEN
  v_query := v_query || 'AND CONVERT(DATE, TRCS.CREATEDATE, 105) BETWEEN CONVERT(DATE, ''' || v_fromdate || ''', 105) AND  CONVERT(DATE, ''' || v_todate || ''', 105)';
  END IF;
  IF (v_searchfield = 'SERVICENAME') THEN
  v_query := v_query || ' AND TRCS.SERVICENAME LIKE ''%' || v_searchvalue || '%'' ';
  END IF;
  IF (v_searchfield = 'OPERATORNAME') THEN
  v_query := v_query || ' AND TRCS.OPERATORNAME LIKE ''%' || v_searchvalue || '%'' ';
  END IF;
  IF (v_searchfield = 'VENDORNAME') THEN
  v_query := v_query || ' AND TV.VENDORNAME LIKE ''%' || v_searchvalue || '%'' ';
  END IF;
  EXECUTE v_query;
  RAISE NOTICE '%', v_query;
  RETURN QUERY SELECT * FROM tmp_temp WHERE rownumber BETWEEN v_minindex AND v_maxindex ORDER BY rank ASC NULLS FIRST;
  SELECT COUNT(rownumber) INTO v_totalcount FROM tmp_temp;
  DROP TABLE IF EXISTS tmp_temp;
  -- SET option (removed)
  END IF;
END;
$$;


--
-- Name: usp_master_pincode_area_city_state(character varying, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_master_pincode_area_city_state(v_keyupvalue character varying DEFAULT ''::character varying, v_cid integer DEFAULT 0) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_query text;
BEGIN
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp (UserName text) ON COMMIT DROP;
  IF EXISTS(SELECT 1 FROM city WHERE cid = v_cid AND cityname LIKE '' || v_keyupvalue || '%' AND active = 1) THEN
  INSERT INTO tmp_temp SELECT (ct.cityname || ',' || st.statename) FROM city AS ct INNER JOIN state AS st ON ct.sid = st.sid AND ct.cityname LIKE '' || v_keyupvalue || '%' AND ct.cid = v_cid AND ct.active = 1 ORDER BY ct.cityname NULLS FIRST LIMIT 20;
  END IF;
  IF EXISTS(SELECT 1 FROM state WHERE cid = v_cid AND statename LIKE '' || v_keyupvalue || '%' AND sactive = 1) THEN
  INSERT INTO tmp_temp SELECT (ct.cityname || ',' || st.statename) FROM state AS st INNER JOIN city AS ct ON st.sid = ct.sid AND st.statename LIKE '' || v_keyupvalue || '%' AND st.cid = v_cid AND ct.active = 1 ORDER BY ct.cityname NULLS FIRST LIMIT 20;
  END IF;
  IF EXISTS(SELECT 1 FROM area_master WHERE cid = v_cid AND pincode LIKE '' || v_keyupvalue || '%' AND cactive = 1) THEN
  INSERT INTO tmp_temp SELECT ((CASE COALESCE(am.pincode, '') WHEN '' THEN '' ELSE am.pincode || ',' END) + am.areaname || ',' || ct.cityname || ',' || st.statename) FROM area_master AS am INNER JOIN city AS ct ON am.ctid = ct.ctid INNER JOIN state AS st ON st.sid = ct.sid AND am.pincode LIKE '' || v_keyupvalue || '%' AND am.cid = v_cid AND am.cactive = 1 ORDER BY am.areaname NULLS FIRST LIMIT 20;
  END IF;
  IF EXISTS(SELECT 1 FROM area_master WHERE cid = v_cid AND areaname LIKE '' || v_keyupvalue || '%' AND cactive = 1) THEN
  INSERT INTO tmp_temp SELECT ((CASE COALESCE(am.pincode, '') WHEN '' THEN '' ELSE am.pincode || ',' END) + am.areaname || ',' || ct.cityname || ',' || st.statename) FROM area_master AS am INNER JOIN city AS ct ON am.ctid = ct.ctid INNER JOIN state AS st ON st.sid = ct.sid AND am.areaname LIKE '' || v_keyupvalue || '%' AND am.cid = v_cid AND am.cactive = 1 ORDER BY am.areaname NULLS FIRST LIMIT 20;
  END IF;
  RETURN QUERY SELECT *, REPLACE(username, v_keyupvalue, '<span style="color:red">' || v_keyupvalue || '</span>') AS username2 FROM tmp_temp;
  DROP TABLE IF EXISTS tmp_temp;
END;
$$;


--
-- Name: usp_master_pincode_area_city_state_m(character varying, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_master_pincode_area_city_state_m(v_keyupvalue character varying DEFAULT 'a'::character varying, v_cid integer DEFAULT 96) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_query text;
BEGIN
  DROP TABLE IF EXISTS v_tbllocation;
  CREATE TEMP TABLE v_tbllocation (LOCATION VARCHAR(150),
FOMATEDLOCATION VARCHAR(200),
AREANAME VARCHAR(200)) ON COMMIT DROP;
  IF EXISTS(SELECT 1 FROM city WHERE cid = v_cid AND cityname LIKE '' || v_keyupvalue || '%' AND active = 1) THEN
  INSERT INTO v_tbllocation SELECT (ct.cityname || ',' || st.statename), (ct.cityname || ',' || st.statename), '' FROM city AS ct INNER JOIN state AS st ON ct.sid = st.sid AND ct.cityname LIKE '' || v_keyupvalue || '%' AND ct.cid = v_cid AND ct.active = 1 ORDER BY ct.cityname NULLS FIRST LIMIT 20;
  END IF;
  IF EXISTS(SELECT 1 FROM state WHERE cid = v_cid AND statename LIKE '' || v_keyupvalue || '%' AND sactive = 1) THEN
  INSERT INTO v_tbllocation SELECT (ct.cityname || ',' || st.statename), (ct.cityname || ',' || st.statename), '' FROM state AS st INNER JOIN city AS ct ON st.sid = ct.sid AND st.statename LIKE '' || v_keyupvalue || '%' AND st.cid = v_cid AND ct.active = 1 ORDER BY ct.cityname NULLS FIRST LIMIT 20;
  END IF;
  IF EXISTS(SELECT 1 FROM area_master WHERE cid = v_cid AND pincode LIKE '' || v_keyupvalue || '%' AND cactive = 1) THEN
  INSERT INTO v_tbllocation SELECT ((CASE COALESCE(am.pincode, '') WHEN '' THEN '' ELSE am.pincode || ',' END) + am.areaname || ',' || ct.cityname || ',' || st.statename), ((CASE COALESCE(am.pincode, '') WHEN '' THEN '' ELSE am.pincode || ',' END) + am.areaname), ',' || '<span class=''cssStateAndCity''>' || ct.cityname || ',' || st.statename || '</span>' FROM area_master AS am INNER JOIN city AS ct ON am.ctid = ct.ctid INNER JOIN state AS st ON st.sid = ct.sid AND am.pincode LIKE '' || v_keyupvalue || '%' AND am.cid = v_cid AND am.cactive = 1 ORDER BY am.areaname NULLS FIRST LIMIT 20;
  END IF;
  IF EXISTS(SELECT 1 FROM area_master WHERE cid = v_cid AND areaname LIKE '' || v_keyupvalue || '%' AND cactive = 1) THEN
  INSERT INTO v_tbllocation SELECT ((CASE COALESCE(am.pincode, '') WHEN '' THEN '' ELSE am.pincode || ',' END) + am.areaname || ',' || ct.cityname || ',' || st.statename), ((CASE COALESCE(am.pincode, '') WHEN '' THEN '' ELSE am.pincode || ',' END) + am.areaname), ',' || '<span class=''cssStateAndCity''>' || ct.cityname || ',' || st.statename || '</span>' FROM area_master AS am INNER JOIN city AS ct ON am.ctid = ct.ctid INNER JOIN state AS st ON st.sid = ct.sid AND am.areaname LIKE '' || v_keyupvalue || '%' AND am.cid = v_cid AND am.cactive = 1 ORDER BY am.areaname NULLS FIRST LIMIT 20;
  END IF;
  RETURN QUERY SELECT location, REPLACE(fomatedlocation, v_keyupvalue, '<span class=''cssHighLightedSearch''>' || v_keyupvalue || '</span>') || areaname AS fomatedlocation FROM v_tbllocation;
END;
$$;


--
-- Name: usp_masterprocedure(integer, integer, integer, integer, integer, integer, integer, integer, integer, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_masterprocedure(v_regno integer DEFAULT 1, INOUT v_allordercount integer DEFAULT 0, INOUT v_pendingcount integer DEFAULT 0, INOUT v_confirmcount integer DEFAULT 0, INOUT v_packcount integer DEFAULT 0, v_mode integer DEFAULT 1, INOUT v_neworder integer DEFAULT 0, INOUT v_completed integer DEFAULT 0, INOUT v_intransit integer DEFAULT 0, INOUT v_allactiveproduct integer DEFAULT 0) RETURNS record
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF (v_mode = 1) THEN
  SELECT COUNT(DISTINCT orderid) INTO v_allordercount FROM tbl_product_order_master WHERE plid = v_regno;
  SELECT COUNT(DISTINCT orderid) INTO v_confirmcount FROM tbl_product_order_master WHERE intstatus = 6 AND plid = v_regno;
  SELECT COUNT(DISTINCT orderid) INTO v_pendingcount FROM tbl_product_order_master AS om WHERE intstatus = 0 AND plid = v_regno;
  SELECT COUNT(DISTINCT orderid) INTO v_packcount FROM tbl_product_order_master WHERE intstatus = 3 AND plid = v_regno;
  SELECT COUNT(DISTINCT orderid) INTO v_neworder FROM tbl_product_order_master WHERE plid = v_regno AND intstatus = 0;
  SELECT COUNT(DISTINCT orderid) INTO v_completed FROM tbl_product_order_master WHERE plid = v_regno AND intstatus = 6;
  SELECT COUNT(DISTINCT orderid) INTO v_intransit FROM tbl_product_order_master WHERE plid = v_regno AND intstatus = 4;
  SELECT COUNT(1) INTO v_allactiveproduct FROM ims_masterproduct AS pm INNER JOIN ims_subproduct AS sm ON sm.mprid = pm.mprid INNER JOIN tbl_main_category AS mc ON mc.maincatid = pm.maincategoryid LEFT JOIN tbl_vat_categories AS v ON v.vcid = pm.vatcategoryid LEFT JOIN portal_login AS pl ON pl.plid = pm.branchid JOIN tbl_sub_category AS km ON pm.subcategoryid = km.subcatid WHERE pm.mprid > 0 AND sm.isverified = 1 AND sm.ismerchantstatus = 5 AND pl.plid = v_regno;
  END IF;
END;
$$;


--
-- Name: usp_member_cprequest_to_marchent(integer, integer, character varying, character varying, character varying, character varying, integer, character varying, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_member_cprequest_to_marchent(v_startrowindex integer DEFAULT 1, v_maxrows integer DEFAULT 100, v_searchfield character varying DEFAULT ''::character varying, v_searchvalue character varying DEFAULT ''::character varying, v_fromdate character varying DEFAULT ''::character varying, v_todate character varying DEFAULT ''::character varying, v_totalcount integer DEFAULT 0, v_status character varying DEFAULT ''::character varying, v_plid integer DEFAULT NULL::integer) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_minindex INT;
  v_maxindex INT;
  v_query text;
BEGIN
  v_minindex := (v_startrowindex - 1) * v_maxrows + 1;
  v_maxindex := v_startrowindex * v_maxrows;
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp (ROWNUMBER INT GENERATED BY DEFAULT AS IDENTITY,         
  RDID int,        
  MEMBERNAME VARCHAR(500),         
  ORDERNUMBER VARCHAR(100),         
  USERNAME VARCHAR(100),             
  CPOINT_AMOUNT  DECIMAL(10,2),                
  REMARK VARCHAR(1000),         
  REQUEST_DATE VARCHAR(100),         
  PLID int,        
  STATUS VARCHAR(50),    
  BILL_AMOUNT decimal(18,2),    
  BILL_IMAGE varchar(500)) ON COMMIT DROP;
  v_query := 'INSERT INTO #TEMP select rdt.RDID,mm.FNAME,rdt.ORDERNO,rdt.USERNAME,rdt.BV,RDT.Remark,rdt.ORDERDATE,rdt.MERCHANTID,(Case when rdt.Isprocess=0 then''Request'' when rdt.IsProcess=1 then ''Process'' when rdt.IsProcess=2 then ''Reject'' else ''''
  
    
  end )  ,rdt.BILL_AMOUNT, rdt.BILL_IMAGE       
 from [db_affiliate].[dbo].[TBL_REPURCHASEDETAILS_TEMP_] rdt        
 inner join [db_affiliate].[dbo].[Member_Master] mm on mm.UserName=rdt.Username WHERE rdt.bv>0';
  IF ((v_fromdate <> '') AND (v_todate = '')) THEN
  v_query := v_query || ' AND CONVERT(DATE, rdt.ORDERDATE, 105) BETWEEN  CONVERT(DATE, ''' || v_fromdate || ''', 105) AND  CONVERT(DATE, DBO.FUN_GETCURRENTDATE(), 105)';
  END IF;
  IF ((v_fromdate = '') AND (v_todate <> '')) THEN
  v_query := v_query || 'AND CONVERT(DATE, rdt.ORDERDATE, 105) BETWEEN  CONVERT(DATE, ''' || v_todate || ''', 105) AND  CONVERT(DATE, DBO.FUN_GETCURRENTDATE(), 105)';
  END IF;
  IF ((v_fromdate <> '') AND (v_todate <> '')) THEN
  v_query := v_query || 'AND CONVERT(DATE, rdt.ORDERDATE, 105) BETWEEN CONVERT(DATE, ''' || v_fromdate || ''', 105) AND  CONVERT(DATE, ''' || v_todate || ''', 105)';
  END IF;
  IF (v_status <> '') THEN
  v_query := v_query || ' AND rdt.ISProcess=''' || v_status || ''' ';
  END IF;
  IF (v_plid > 0) THEN
  v_query := v_query || ' AND rdt.MERCHANTID=' || CAST(v_plid AS VARCHAR) || '';
  END IF;
  v_query := v_query || ' order by orderdate desc ';
  EXECUTE v_query;
  RAISE NOTICE '%', v_query;
  RETURN QUERY SELECT * FROM tmp_temp WHERE rownumber BETWEEN v_minindex AND v_maxindex;
  SELECT COUNT(rownumber) INTO v_totalcount FROM tmp_temp;
  DROP TABLE IF EXISTS tmp_temp;
  -- SET option (removed)
END;
$$;


--
-- Name: usp_member_earning_history(integer, integer, integer, character varying, character varying, character varying, character varying, integer, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_member_earning_history(v_plid integer DEFAULT 1, v_startrowindex integer DEFAULT 1, v_maxrows integer DEFAULT 100, v_searchfield character varying DEFAULT ''::character varying, v_searchvalue character varying DEFAULT ''::character varying, v_fromdate character varying DEFAULT ''::character varying, v_todate character varying DEFAULT ''::character varying, v_totalcount integer DEFAULT 0, v_mode integer DEFAULT 1) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_minindex INT;
  v_maxindex INT;
  v_query text;
  v_startdate timestamp;
  v_tilldate timestamp;
  v_daybydaydate timestamp;
  v_earnedmatchingpoints numeric(19,4);
  v_earneddirectpoints numeric(19,4);
  v_earnedlevelpoints numeric(19,4);
  v_earnedtasklevelpoints numeric(19,4);
  v_totalearnedpoints numeric(19,4);
  v_payid BigInt;
BEGIN
  v_query := '';
  v_minindex := (v_startrowindex - 1) * v_maxrows + 1;
  v_maxindex := v_startrowindex * v_maxrows;
  DROP TABLE IF EXISTS tmp_tempdetails;
  CREATE TEMP TABLE tmp_tempdetails (ROWNUMBER BigInt GENERATED BY DEFAULT AS IDENTITY,
EarnedDate Date,
MatchingBv numeric(19,4),
EarnedPoints numeric(19,4),
FromUserName text,
IncomeType  text,
Payid Int) ON COMMIT DROP;
  IF (v_mode = 1) THEN
  v_startdate := '2017-03-01';
  v_tilldate := '';
  v_daybydaydate := '';
  v_payid := 0;
  SELECT dbo.FUN_GETCURRENTDATE() INTO v_tilldate;
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp (ROWNUMBER BigInt GENERATED BY DEFAULT AS IDENTITY,
EarnedDate Date,
EarnedMatchingPoints numeric(19,4),
EarnedDirectPoints numeric(19,4),
EarnedLevelPoints numeric(19,4),
EarnedTaskLevelPoints numeric(19,4),
TotalEarnedPoints numeric(19,4),
Status text,
PayId Int) ON COMMIT DROP;
  WHILE (v_startdate < v_tilldate) LOOP
  v_daybydaydate := v_startdate;
  SELECT COALESCE(MAX(payid), 0) INTO v_payid FROM payout WHERE CAST(payto AS DATE) = CAST(v_daybydaydate AS DATE);
  INSERT INTO tmp_temp SELECT v_daybydaydate, 0, 0, 0, 0, 0, 'Credited In E-Wallet', v_payid;
  IF (v_payid <> 0) THEN
  SELECT COALESCE(binaryincome, 0.00), COALESCE(levelincome, 0.00), COALESCE(tasklevelincome, 0.00) INTO v_earnedmatchingpoints, v_earnedlevelpoints, v_earnedtasklevelpoints FROM member_payout WHERE regno = (SELECT regno FROM member_master WHERE plid = v_plid) AND payid = v_payid;
  END IF;
  SELECT COALESCE(SUM(amount), 0.00) INTO v_earneddirectpoints FROM directincomes WHERE toid = (SELECT loginid FROM member_master WHERE plid = v_plid) AND CAST(date AS DATE) = CAST(v_daybydaydate AS DATE) AND status = 1 AND active = 1;
  SELECT COALESCE((v_earnedmatchingpoints + v_earneddirectpoints + v_totalearnedpoints + v_earnedlevelpoints + v_earnedtasklevelpoints), 0.00) INTO v_totalearnedpoints;
  UPDATE tmp_temp SET earnedmatchingpoints = COALESCE(v_earnedmatchingpoints, 0), earneddirectpoints = v_earneddirectpoints, totalearnedpoints = v_totalearnedpoints, earnedlevelpoints = COALESCE(v_earnedlevelpoints, 0), earnedtasklevelpoints = COALESCE(v_earnedtasklevelpoints, 0) WHERE CAST(earneddate AS DATE) = CAST(v_daybydaydate AS DATE);
  v_earnedmatchingpoints := 0.00;
  v_earneddirectpoints := 0.00;
  v_totalearnedpoints := 0.00;
  v_earnedlevelpoints := 0.00;
  v_earnedtasklevelpoints := 0.00;
  v_startdate := v_startdate + 1;
  END LOOP;
  IF ((v_fromdate <> '') AND (v_todate = '')) THEN
  v_query := v_query || ' AND CONVERT(DATE, DATE) BETWEEN  CONVERT(DATE, ''' || v_fromdate || ''') AND  CONVERT(DATE, DBO.FUN_GETCURRENTDATE()) ';
  END IF;
  IF ((v_fromdate = '') AND (v_todate <> '')) THEN
  v_query := v_query || ' AND CONVERT(DATE,DATE) BETWEEN  CONVERT(DATE, ''' || v_todate || ''') AND  CONVERT(DATE, DBO.FUN_GETCURRENTDATE()) ';
  END IF;
  IF ((v_fromdate <> '') AND (v_todate <> '')) THEN
  v_query := v_query || ' AND CONVERT(DATE,DATE) BETWEEN CONVERT(DATE, ''' || v_fromdate || ''') AND  CONVERT(DATE, ''' || v_todate || ''') ';
  END IF;
  EXECUTE v_query;
  RETURN QUERY SELECT * FROM tmp_temp WHERE rownumber BETWEEN v_startrowindex AND v_maxrows AND (earnedmatchingpoints > 0 OR earneddirectpoints > 0 OR totalearnedpoints > 0);
  SELECT COUNT(rownumber) INTO v_totalcount FROM tmp_temp WHERE (earnedmatchingpoints > 0 OR earneddirectpoints > 0 OR totalearnedpoints > 0);
  DROP TABLE IF EXISTS tmp_temp;
  -- SET option (removed)
  END IF;
  IF (v_mode = 2) THEN
  SELECT COALESCE(MAX(payid), 0) INTO v_payid FROM payout WHERE CAST(payto AS DATE) = CAST(v_fromdate AS DATE);
  INSERT INTO tmp_tempdetails SELECT v_fromdate, 0.00, amount, mm.username, 'Referral Income', 0 FROM directincomes AS di INNER JOIN member_master AS mm ON mm.loginid = di.fromid WHERE toid = (SELECT loginid FROM member_master WHERE plid = v_plid) AND CAST(date AS DATE) = CAST(v_fromdate AS DATE) AND di.status = 1 AND di.active = 1;
  RETURN QUERY SELECT * FROM tmp_tempdetails;
  END IF;
  IF (v_mode = 3) THEN
  SELECT COALESCE(MAX(payid), 0) INTO v_payid FROM payout WHERE CAST(payto AS DATE) = CAST(v_fromdate AS DATE);
  INSERT INTO tmp_tempdetails SELECT v_fromdate, amount, income, mm.username, type, li.payid FROM level_income AS li INNER JOIN member_master AS mm ON mm.loginid = li.fromid WHERE toid = (SELECT loginid FROM member_master WHERE plid = v_plid) AND CAST(date AS DATE) = CAST(v_fromdate AS DATE) AND li.status = 1 AND li.active = 1 AND li.isskip = 0 AND COALESCE(levelincometype, 0) = 1;
  RETURN QUERY SELECT * FROM tmp_tempdetails;
  END IF;
  IF (v_mode = 4) THEN
  SELECT COALESCE(MAX(payid), 0) INTO v_payid FROM payout WHERE CAST(payto AS DATE) = CAST(v_fromdate AS DATE);
  INSERT INTO tmp_tempdetails SELECT v_fromdate, amount, income, mm.username, type, li.payid FROM level_income AS li INNER JOIN member_master AS mm ON mm.loginid = li.fromid WHERE toid = (SELECT loginid FROM member_master WHERE plid = v_plid) AND CAST(date AS DATE) = CAST(v_fromdate AS DATE) AND li.status = 1 AND li.active = 1 AND li.isskip = 0 AND COALESCE(levelincometype, 0) = 2;
  RETURN QUERY SELECT * FROM tmp_tempdetails;
  END IF;
END;
$$;


--
-- Name: usp_member_get_member_downlinelist_side_wise(character varying, integer, integer, text, text, text, text, integer, integer, integer, numeric, numeric, character varying, character varying, character varying, character varying, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_member_get_member_downlinelist_side_wise(v_loginid character varying DEFAULT ''::character varying, v_startrowindex integer DEFAULT 0, v_maxrows integer DEFAULT 0, v_searchfield text DEFAULT ''::text, v_searchvalue text DEFAULT ''::text, v_fromdate text DEFAULT ''::text, v_todate text DEFAULT ''::text, v_levenumber integer DEFAULT 0, v_side integer DEFAULT 1, v_totalcount integer DEFAULT 0, v_totallrbv numeric DEFAULT 0, v_totallrincome numeric DEFAULT 0, v_name character varying DEFAULT ''::character varying, v_username character varying DEFAULT ''::character varying, v_emailid character varying DEFAULT ''::character varying, v_sponserid character varying DEFAULT ''::character varying, v_checkadminside integer DEFAULT 0) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_minindex INT;
  v_maxindex INT;
  v_query text;
BEGIN
  v_minindex := (v_startrowindex - 1) * v_maxrows + 1;
  v_maxindex := v_startrowindex * v_maxrows;
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp (ROWNUMBER INT PRIMARY KEY,
LOGINID text,
SPONSERID text,
ROOTID text,
EMPLEVEL INT,
NAME text,
MOBILE text,
CITYNAME text,
REGDATE text,
STATUS  text,
EMAILID text,
DOC text,
TLBV numeric(19,4),
CLBV numeric(19,4),
TRBV numeric(19,4),
CRBV numeric(19,4),
PAIDBV numeric(19,4),
USERNAME text,
KITPRICE numeric(19,4) DEFAULT(0),
KITNAME VARCHAR(50),
INCOME numeric(19,4),
REGNO INT,
SIDE INT,
SPOUNSER_USERNAME VARCHAR(500),
ROOT_USERNAME VARCHAR(500),
LCOUNT INT,
RCOUNT INT) ON COMMIT DROP;
  SELECT loginid INTO v_loginid FROM member_master WHERE username = v_loginid;
  -- CREATE INDEX (skipped)
  IF (v_side = 0) THEN
  v_query := 'INSERT INTO #TEMP  SELECT ROW_NUMBER() OVER(ORDER BY REGDATE ASC) AS ROWNUMBER,*  FROM FUN_ALL_DOWNLINE_MEMBERLIST(''' || v_loginid || ''') WHERE LOGINID!= '''' ';
  END IF;
  IF (v_side = 1) THEN
  v_query := 'INSERT INTO #TEMP  SELECT ROW_NUMBER() OVER(ORDER BY REGDATE ASC) AS ROWNUMBER,*  FROM FUN_ALL_DOWNLINE_MEMBERLIST_LEFT_SIDE_WITHLRCOUNT(''' || v_loginid || ''') WHERE LOGINID!='''' ';
  END IF;
  IF (v_side = 2) THEN
  v_query := 'INSERT INTO #TEMP  SELECT ROW_NUMBER() OVER(ORDER BY REGDATE ASC) AS ROWNUMBER,*  FROM FUN_ALL_DOWNLINE_MEMBERLIST_RIGHT_SIDE_WITH_LRCOUNT(''' || v_loginid || ''') WHERE LOGINID!='''' ';
  END IF;
  IF (v_searchfield <> '' AND v_searchvalue <> '') THEN
  IF (v_searchfield = 'FNAME') THEN
  v_query := v_query || ' AND NAME LIKE ''%' || v_searchvalue || '%''';
  END IF;
  IF (v_searchfield = 'LOGINID') THEN
  v_query := v_query || ' AND USERNAME LIKE ''%' || v_searchvalue || '%'' ';
  END IF;
  IF (v_searchfield = 'PNAME') THEN
  v_query := v_query || ' AND  ROOT_USERNAME LIKE ''%' || v_searchvalue || '%'' ';
  END IF;
  IF (v_searchfield = 'SNAME') THEN
  v_query := v_query || ' AND SPOUNSER_USERNAME LIKE ''%' || v_searchvalue || '%'' ';
  END IF;
  END IF;
  IF (v_name <> '') THEN
  v_query := v_query || ' AND NAME LIKE ''%' || v_name || '%''';
  END IF;
  IF (v_username <> '') THEN
  v_query := v_query || ' AND  USERNAME LIKE ''%' || v_username || '%'' ';
  END IF;
  IF (v_emailid <> '') THEN
  v_query := v_query || ' AND  EMAILID LIKE ''%' || v_emailid || '%'' ';
  END IF;
  IF (v_sponserid <> '') THEN
  v_query := v_query || ' AND  SPOUNSER_USERNAME LIKE ''%' || v_sponserid || '%'' ';
  END IF;
  IF (v_levenumber > 0) THEN
  v_query := v_query || ' AND EMPLEVEL = ' || CAST(v_levenumber AS VARCHAR(10));
  END IF;
  IF ((v_fromdate <> '') AND (v_todate = '')) THEN
  v_query := v_query || ' AND CONVERT(VARCHAR(20),REGDATE,105) >=  ''' || v_fromdate || '''';
  END IF;
  IF ((v_fromdate = '') AND (v_todate <> '')) THEN
  v_query := v_query || ' and convert(varchar(20), REGDATE.DATE,105) <=  ''' || v_todate || '''';
  END IF;
  IF ((v_fromdate <> '') AND (v_todate <> '')) THEN
  v_query := v_query || ' and convert(varchar(20), REGDATE,105) between  ''' || v_fromdate || ''' and  ''' || v_todate || '''';
  END IF;
  v_query := v_query || '   OPTION ( MAXRECURSION 0 )';
  EXECUTE v_query;
  IF (v_side = 2) THEN
  IF (v_checkadminside = 1) THEN
  RETURN QUERY SELECT * FROM tmp_temp WHERE rownumber BETWEEN v_startrowindex AND v_maxrows;
  ELSE
  RETURN QUERY SELECT * FROM tmp_temp WHERE rownumber BETWEEN v_minindex AND v_maxindex;
  END IF;
  ELSE
  RETURN QUERY SELECT * FROM tmp_temp;
  END IF;
  IF (v_side = 1) THEN
  IF (v_checkadminside = 1) THEN
  RETURN QUERY SELECT * FROM tmp_temp WHERE rownumber BETWEEN v_startrowindex AND v_maxrows;
  ELSE
  RETURN QUERY SELECT * FROM tmp_temp WHERE rownumber BETWEEN v_minindex AND v_maxindex;
  END IF;
  ELSE
  RETURN QUERY SELECT * FROM tmp_temp;
  END IF;
  SELECT COUNT(rownumber) INTO v_totalcount FROM tmp_temp;
  IF (v_side = 1) THEN
  SELECT COALESCE(SUM(kitprice), 0) INTO v_totallrbv FROM FUN_ALL_DOWNLINE_MEMBERLIST_LEFT_SIDE('' || v_loginid || '') WHERE kitprice <> 1000;
  SELECT COALESCE(SUM(income), 0) INTO v_totallrincome FROM FUN_ALL_DOWNLINE_MEMBERLIST_LEFT_SIDE('' || v_loginid || '') WHERE kitprice <> 1000;
  END IF;
  IF (v_side = 2) THEN
  SELECT COALESCE(SUM(kitprice), 0) INTO v_totallrbv FROM FUN_ALL_DOWNLINE_MEMBERLIST_RIGHT_SIDE('' || v_loginid || '') WHERE kitprice <> 1000;
  SELECT COALESCE(SUM(income), 0) INTO v_totallrincome FROM FUN_ALL_DOWNLINE_MEMBERLIST_RIGHT_SIDE('' || v_loginid || '') WHERE kitprice <> 1000;
  END IF;
  DROP TABLE IF EXISTS tmp_temp;
  -- SET option (removed)
END;
$$;


