--
-- Name: usp_membercontactpasswordchange(bigint, character varying, character varying, character varying, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_membercontactpasswordchange(v_plid bigint DEFAULT 1, v_oldpass character varying DEFAULT NULL::character varying, v_newpass character varying DEFAULT NULL::character varying, v_confpass character varying DEFAULT NULL::character varying, INOUT v_intresult integer DEFAULT NULL::integer) RETURNS integer
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_reg BIGINT;
  v_err INT;
BEGIN
  v_reg := 0;
  IF EXISTS(SELECT 1 FROM member_login WHERE regno = v_plid AND password = v_oldpass) THEN
  UPDATE member_login SET password = v_newpass WHERE regno = v_plid;
  v_intresult := 1;
  ELSE
  v_intresult := 2;
  END IF;
  SELECT 0 INTO v_err;
  IF (v_err <> 0) THEN
  v_intresult := 4;
  END IF;
END;
$$;


--
-- Name: usp_membergetcontactdetails(bigint); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_membergetcontactdetails(v_plid bigint DEFAULT 1) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
BEGIN
  RETURN QUERY SELECT username, CAST(COALESCE(member_master.regno, 0) AS INT) AS pmid, CAST(COALESCE(member_master.regno, 0) AS INT) AS plid, title, fname, lname, (CASE WHEN mobile = '' THEN '' WHEN COALESCE(mobile, '') = '' THEN '' ELSE ('+' || c.isdcode || ' ' || mobile) END) AS phonewithcode, (mobile) AS phone, designation, member_master.emailid AS cper_emailid, member_master.loginid, password, imagename, c.countryname, phone, CAST(COALESCE(member_master.introregno, 0) AS BIGINT) AS intro_plid, CASE WHEN dob = '1900-01-01' THEN '' ELSE CAST(TO_CHAR(dob, 'MM/DD/YYYY') AS VARCHAR(30)) END AS dob, (fath_hus_name) AS fatherormothername, CAST(COALESCE(gender, 0) AS INT) AS gender, COALESCE(highestqualification, 0) AS highestqualification FROM member_master INNER JOIN member_login ON member_master.regno = member_login.regno INNER JOIN country AS c ON c.cid = member_master.cid WHERE plid = v_plid;
END;
$$;


--
-- Name: usp_memberjoin_temp(character varying, character varying, character varying, integer, integer, bigint, character varying, character varying, integer, character varying, character varying, text, integer, character varying, integer, character varying, character varying, character varying, character varying, text, text, integer, integer, text, text, text, text, integer, integer, integer, integer, text, text, text); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_memberjoin_temp(v_loginid character varying DEFAULT 'kumarashish0371@gmail.com'::character varying, v_password character varying DEFAULT ''::character varying, v_username character varying DEFAULT '9582105254'::character varying, INOUT v_intresult integer DEFAULT 0, v_mode integer DEFAULT 0, v_qpayregno bigint DEFAULT 0, v_currencysymbol character varying DEFAULT ''::character varying, v_country character varying DEFAULT 'India'::character varying, INOUT v_plid integer DEFAULT 0, v_referrelcode character varying DEFAULT ''::character varying, v_ipaddress character varying DEFAULT '::1'::character varying, v_mobileno text DEFAULT ''::text, v_distributerid integer DEFAULT 11, v_ref_username character varying DEFAULT ''::character varying, v_ref_regno integer DEFAULT 0, v_address character varying DEFAULT ''::character varying, v_statename character varying DEFAULT ''::character varying, v_ctname character varying DEFAULT ''::character varying, v_pincode character varying DEFAULT ''::character varying, v_sponsorids text DEFAULT ''::text, v_placementids text DEFAULT ''::text, v_side integer DEFAULT 0, v_title integer DEFAULT 0, v_firstname text DEFAULT ''::text, v_lastname text DEFAULT ''::text, v_desigantion text DEFAULT ''::text, v_imagename text DEFAULT ''::text, v_modeforjoining integer DEFAULT 0, v_cid integer DEFAULT 0, v_sid integer DEFAULT 0, v_ctid integer DEFAULT 0, v_atc_walletaddress text DEFAULT ''::text, v_cityname text DEFAULT ''::text, v_atcuserid text DEFAULT ''::text) RETURNS record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_err INT;
  v_plidref INT;
  v_spounsertype INT;
  v_username_count INT;
  v_duplicate_mobile INT;
  v_duplicateemailid_count INT;
  v_chars char(88);
  v_referalcode text;
  v_intcontinue INT;
  v_userid text;
BEGIN
  v_modeforjoining := 0;
  IF EXISTS(SELECT COALESCE(cid, '96') FROM country WHERE countryname = v_country AND cactive = 1) THEN
  SELECT COALESCE(cid, '96') INTO v_cid FROM country WHERE countryname = v_country AND cactive = 1;
  ELSE
  v_cid := 96;
  END IF;
  v_spounsertype := 0;
  v_placementids := v_sponsorids;
  v_intresult := 0;
  v_username_count := 0;
  v_duplicate_mobile := 0;
  v_duplicateemailid_count := 0;
  DROP TABLE IF EXISTS tmp_tb1;
  CREATE TEMP TABLE tmp_tb1 ON COMMIT DROP AS SELECT ROW_NUMBER() OVER (ORDER BY item NULLS FIRST) AS row, item FROM dbo.SPLITSTRING(v_username, '');
  v_referalcode := '';
  v_intcontinue := 0;
  v_chars := N'0123456789';
  WHILE (v_intcontinue = 0) LOOP
  v_referalcode := SUBSTRING(v_chars FROM CAST((RANDOM() * LENGTH(CAST(v_chars AS TEXT))) AS INT) + 1 FOR 1) || SUBSTRING(v_chars FROM CAST((RANDOM() * LENGTH(CAST(v_chars AS TEXT))) AS INT) + 1 FOR 1) || SUBSTRING(v_chars FROM CAST((RANDOM() * LENGTH(CAST(v_chars AS TEXT))) AS INT) + 1 FOR 1) || SUBSTRING(v_chars FROM CAST((RANDOM() * LENGTH(CAST(v_chars AS TEXT))) AS INT) + 1 FOR 1) || SUBSTRING(v_chars FROM CAST((RANDOM() * LENGTH(CAST(v_chars AS TEXT))) AS INT) + 1 FOR 1) || SUBSTRING(v_chars FROM CAST((RANDOM() * LENGTH(CAST(v_chars AS TEXT))) AS INT) + 1 FOR 1);
  IF EXISTS(SELECT 1 FROM customer_login_temp WHERE refral_id = v_referalcode) THEN
  v_intcontinue := 0;
  ELSE
  IF (LENGTH(CAST(v_referalcode AS TEXT)) < 6) THEN
  v_intcontinue := 0;
  ELSE
  IF ((SELECT SUBSTRING(v_referalcode FROM 1 FOR 1)) <= 0) THEN
  v_intcontinue := 0;
  ELSE
  v_intcontinue := 1;
  END IF;
  END IF;
  END IF;
  END LOOP;
  v_userid := '';
  SELECT 0 INTO v_intcontinue;
  v_chars := N'8123456789';
  WHILE (v_intcontinue = 0) LOOP
  v_userid := SUBSTRING(v_chars FROM CAST((RANDOM() * LENGTH(CAST(v_chars AS TEXT))) AS INT) + 1 FOR 1) || SUBSTRING(v_chars FROM CAST((RANDOM() * LENGTH(CAST(v_chars AS TEXT))) AS INT) + 1 FOR 1) || SUBSTRING(v_chars FROM CAST((RANDOM() * LENGTH(CAST(v_chars AS TEXT))) AS INT) + 1 FOR 1) || SUBSTRING(v_chars FROM CAST((RANDOM() * LENGTH(CAST(v_chars AS TEXT))) AS INT) + 1 FOR 1) || SUBSTRING(v_chars FROM CAST((RANDOM() * LENGTH(CAST(v_chars AS TEXT))) AS INT) + 1 FOR 1) || SUBSTRING(v_chars FROM CAST((RANDOM() * LENGTH(CAST(v_chars AS TEXT))) AS INT) + 1 FOR 1) || SUBSTRING(v_chars FROM CAST((RANDOM() * LENGTH(CAST(v_chars AS TEXT))) AS INT) + 1 FOR 1) || SUBSTRING(v_chars FROM CAST((RANDOM() * LENGTH(CAST(v_chars AS TEXT))) AS INT) + 1 FOR 1);
  IF EXISTS(SELECT 1 FROM customer_login_temp WHERE userid = v_userid) THEN
  v_intcontinue := 0;
  ELSE
  IF (LENGTH(CAST(v_userid AS TEXT)) < 8) THEN
  v_intcontinue := 0;
  ELSE
  IF ((SELECT SUBSTRING(v_userid FROM 1 FOR 1)) <= 0) THEN
  v_intcontinue := 0;
  ELSE
  v_intcontinue := 1;
  END IF;
  END IF;
  END IF;
  END LOOP;
  IF (v_mobileno <> '') THEN
  SELECT COUNT(1) INTO v_duplicate_mobile FROM tbl_customerlogin WHERE phone = v_mobileno AND did = v_distributerid;
  IF (COALESCE(v_duplicate_mobile, 0) > 0) THEN
  v_intresult := 6;
  RETURN;
  END IF;
  IF NOT EXISTS(SELECT 1 FROM customer_login_temp WHERE phone = v_mobileno AND did = v_distributerid) THEN
  INSERT INTO customer_login_temp (loginid, password, active, doc, currencysymbol, cid, intro_refid, username, ipaddress, refral_id, phone, sponserid, placementid, side, imagename, designation, title, sp_firstname, sp_lastname, spounsertype, userid, emailid, sid, ctid, did, reference_username, reference_regno) VALUES (v_userid, v_password, 0, dbo.FUN_GETCURRENTDATE(), v_currencysymbol, v_cid, v_plidref, v_username, v_ipaddress, v_referalcode, v_mobileno, v_sponsorids, v_placementids, v_side, v_imagename, v_desigantion, v_title, (CASE WHEN COALESCE(v_firstname, '') = '' THEN (SELECT item FROM tmp_tb1 WHERE row = 1) ELSE v_firstname END), (CASE WHEN COALESCE(v_lastname, '') = '' THEN (SELECT item FROM tmp_tb1 WHERE row = 2) ELSE v_lastname END), v_spounsertype, v_userid, v_loginid, v_sid, v_ctid, v_distributerid, v_ref_username, v_ref_regno);
  v_plid := IDENT_CURRENT('CUSTOMER_LOGIN_TEMP');
  v_intresult := 1;
  ELSE
  SELECT pltid INTO v_plid FROM customer_login_temp WHERE phone = v_mobileno AND did = v_distributerid;
  v_intresult := 1;
  END IF;
  END IF;
  IF (v_loginid <> '') THEN
  SELECT COUNT(1) INTO v_duplicateemailid_count FROM tbl_customerlogin WHERE emailid = v_loginid AND did = v_distributerid;
  IF (COALESCE(v_duplicateemailid_count, 0) > 0) THEN
  v_intresult := 2;
  RETURN;
  END IF;
  IF NOT EXISTS(SELECT 1 FROM customer_login_temp WHERE emailid = v_loginid AND did = v_distributerid) THEN
  INSERT INTO customer_login_temp (loginid, password, active, doc, currencysymbol, cid, intro_refid, username, ipaddress, refral_id, phone, sponserid, placementid, side, imagename, designation, title, sp_firstname, sp_lastname, spounsertype, userid, emailid, sid, ctid, did, reference_username, reference_regno) VALUES (v_userid, v_password, 0, dbo.FUN_GETCURRENTDATE(), v_currencysymbol, v_cid, v_plidref, v_username, v_ipaddress, v_referalcode, v_mobileno, v_sponsorids, v_placementids, v_side, v_imagename, v_desigantion, v_title, (CASE WHEN COALESCE(v_firstname, '') = '' THEN (SELECT item FROM tmp_tb1 WHERE row = 1) ELSE v_firstname END), (CASE WHEN COALESCE(v_lastname, '') = '' THEN (SELECT item FROM tmp_tb1 WHERE row = 2) ELSE v_lastname END), v_spounsertype, v_userid, v_loginid, v_sid, v_ctid, v_distributerid, v_ref_username, v_ref_regno);
  v_plid := IDENT_CURRENT('CUSTOMER_LOGIN_TEMP');
  v_intresult := 1;
  ELSE
  SELECT pltid INTO v_plid FROM customer_login_temp WHERE emailid = v_loginid;
  v_intresult := 1;
  END IF;
  END IF;
  DROP TABLE IF EXISTS tmp_tb1;
  IF (0 <> 0) THEN
  v_intresult := 0;
  RETURN;
  END IF;
END;
$$;


--
-- Name: usp_membersubscriptionaccount(integer, integer, character varying, character varying, character varying, character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_membersubscriptionaccount(v_startrowindex integer DEFAULT 1, v_maxrows integer DEFAULT 50, v_activationdate character varying DEFAULT ''::character varying, v_tilldate character varying DEFAULT ''::character varying, v_activitydate character varying DEFAULT ''::character varying, v_username character varying DEFAULT ''::character varying) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_query text;
  v_minindex INT;
  v_maxindex INT;
  v_queryresult text;
BEGIN
  v_query := '';
  v_queryresult := '';
  v_minindex := (v_startrowindex - 1) * v_maxrows + 1;
  v_maxindex := v_startrowindex * v_maxrows;
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp (RowNumber BIGINT GENERATED BY DEFAULT AS IDENTITY,
TMSAID BIGINT,
ActivityDate Varchar(15),
ActivationDate Varchar(15),
TillDate Varchar(15),
LOGINID Varchar(500),
NoOfDaysForActivation INT,
AllocatedNoOfEmail BIGINT,
AllocatedNoOfSms BIGINT,
AllocatedNoOfWhatsUpMessage BIGINT,
RemainNoOfEmail BIGINT,
RemainNoOfSMS BIGINT,
RemainNoOfWhatsUpMessage BIGINT,
Status varchar(50),
SubscriptionName VarChar(500),
AllocatedNoOfHits BigInt) ON COMMIT DROP;
  v_query := 'Insert Into #TEMP Select TMSAID,CONVERT(Varchar(12),TMSA.ActivityDate,106) as ActivityDate,
CONVERT(Varchar(12),ActivationDate,106) as ActivationDate,
CONVERT(Varchar(12),TillDate,106) as TillDate,Pl.LOGINID,TSM.NoOfDaysForActivation,AllocatedNoOfEmail,
AllocatedNoOfSms,AllocatedNoOfWhatsUpMessage,RemainNoOfEmail,RemainNoOfSMS,RemainNoOfWhatsUpMessage,
(Case When TSM.Status = 1 Then ''Active'' Else ''Deactive'' End) as Status,TSM.SubscriptionHeading,
TMSA.AllocatedNoOfHits From Tbl_MemberSubscriptionAccount TMSA Inner Join PORTAL_LOGIN Pl On 
Pl.PLID = TMSA.PLID Inner Join Tbl_SubscriptionMaster TSM On TMSA.TSMID= TSM.TSMID Where Pl.ACTIVE = 1 ';
  IF (v_activationdate <> '' OR v_tilldate <> '' OR v_activitydate <> '') THEN
  v_query := v_query || ' And Convert(Date,ActivationDate,105)= Convert(Date,''' || v_activationdate || ''',105) OR Convert(Date,TillDate,105) = Convert(Date,''' || v_tilldate || ''',105) OR Convert(Date,ActivityDate,105) = Convert(Date,''' || v_activitydate || ''',105)';
  END IF;
  IF (v_username <> '') THEN
  v_query := v_query || ' And Pl.Loginid Like ''%' || v_username || '%'' ';
  END IF;
  EXECUTE v_query;
  RETURN QUERY SELECT * FROM tmp_temp WHERE rownumber BETWEEN v_startrowindex AND v_maxrows;
  RETURN QUERY SELECT COUNT(tmsaid) AS totalcount FROM tmp_temp;
END;
$$;


--
-- Name: usp_merchant_clubhistory_list(integer, integer, character varying, character varying, character varying, character varying, character varying, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_merchant_clubhistory_list(v_startrowindex integer DEFAULT 1, v_maxrows integer DEFAULT 100, v_fromdate character varying DEFAULT ''::character varying, v_todate character varying DEFAULT ''::character varying, v_status character varying DEFAULT ''::character varying, v_searchfield character varying DEFAULT ''::character varying, v_searchvalue character varying DEFAULT ''::character varying, v_totalrecord integer DEFAULT 0) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_query text;
  v_maxregno text;
  v_query1 text;
  v_minindex INT;
  v_maxindex INT;
  v_count INT;
  v_totalcount INT;
  v_chid INT;
  v_totoalcancelamount DECIMAL(18,2);
BEGIN
  -- SET option (removed)
  v_query := '';
  v_maxregno := '';
  v_query1 := '';
  v_count := 1;
  v_totalcount := 0;
  v_chid := 0;
  v_minindex := (v_startrowindex - 1) * v_maxrows + 1;
  v_maxindex := v_startrowindex * v_maxrows;
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp (ROWNUMBER BIGINT,
	   CHID BIGINT,
	  FILENAME VARCHAR(150),
	  DATE timestamp,
	  CLUBGROUP VARCHAR(150),
	  TOTALREQUEST INT,
	  TOTALAMOUNT DECIMAL(18,8),
	  TOTAL_TANSACTION DECIMAL(18,8),
	  PROCESSDATE timestamp,
	  PROCESSBY VARCHAR(50),
	  PROCESSSTATUS VARCHAR(50),
	  PROCESSIPADDRESS VARCHAR(50),
	  BANKNAME VARCHAR(200),
	  TOTALPAID INT,
	  TOTALREJECT INT,
	  TRANSACTION_NO INT,
	  CANCELAMOUNT DECIMAL(18,2)) ON COMMIT DROP;
  v_query := 'INSERT INTO #TEMP Select row_number()over(order by CHID desc) as RowNumber,CHID,FileName,convert(date,Date,105) as Date,
ClubGroup,TotalRequest,TotalAmount,Total_tansaction,
convert(date,ProcessDate,105) as ProcessDate,ProcessBy,ProcessStatus,ProcessIPAddress,BankName,
(select isnull(COUNT(distinct PLID),0)  from TBL_MERCHANT_WITHDRAWALS  where  status=1 and TMWDID in  (select * from SplitString(AllWDID,'',''))) as TotalPaid,
(select isnull(COUNT(distinct Plid),0)  from TBL_MERCHANT_WITHDRAWALS  where  status=2 and TMWDID in  (select * from SplitString(AllWDID,'',''))) as TotalReject,0,0
from TBL_MERCHANT_CLUBHISTORY WHERE 1=1 ';
  RAISE NOTICE '%', v_query;
  EXECUTE v_query;
  SELECT COUNT(1) INTO v_totalcount FROM tmp_temp;
  WHILE (v_totalcount >= v_count) LOOP
  SELECT chid INTO v_chid FROM tmp_temp WHERE rownumber = v_count;
  SELECT COALESCE(SUM(amount), 0) INTO v_totoalcancelamount FROM tbl_merchant_downloadclubdata WHERE status = 2 AND chid = v_chid;
  UPDATE tmp_temp SET cancelamount = v_totoalcancelamount WHERE chid = v_chid;
  v_count := v_count + 1;
  END LOOP;
  SELECT COALESCE(COUNT(1), 0) INTO v_totalrecord FROM tmp_temp;
  RETURN QUERY SELECT * FROM tmp_temp ORDER BY rownumber ASC NULLS FIRST;
  DROP TABLE IF EXISTS tmp_temp;
  -- SET option (removed)
END;
$$;


--
-- Name: usp_merchant_faq(integer, integer, character varying, boolean, character varying, character varying, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_merchant_faq(v_startrowindex integer, v_maxrows integer, v_orderbyfield character varying, v_asc boolean, v_searchfield character varying, v_searchvalue character varying, v_mode integer) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_recordcount int;
  v_regno bigint;
BEGIN
  -- SET option (removed)
  DROP TABLE IF EXISTS tmp_temp12;
  CREATE TEMP TABLE tmp_temp12 ON COMMIT DROP AS SELECT ROW_NUMBER() OVER (ORDER BY fmq.fmqid DESC NULLS LAST) AS rownumber, fmq.fmqid, fmq.fmcid, fmq.faqque, fmq.faqans, fmc.categoryname, (CASE WHEN fmq.active = 1 THEN 'Active' ELSE 'Deactive' END) AS active FROM faq_merchant_quesans AS fmq INNER JOIN faq_merchant_category AS fmc ON fmc.fmcid = fmq.fmcid WHERE fmc.active = 1;
  IF (v_searchfield = '') THEN
  RETURN QUERY SELECT * FROM tmp_temp12 WHERE rownumber BETWEEN v_startrowindex AND v_maxrows;
  END IF;
  DROP TABLE IF EXISTS tmp_temp12;
  -- SET option (removed)
END;
$$;


--
-- Name: usp_merchant_fund_request(integer, bigint, character varying, numeric, character varying, integer, character varying, character varying, character varying, character varying, character varying, character varying, character varying, integer, character varying, character varying, integer, integer, character varying, character varying, integer, numeric, numeric); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_merchant_fund_request(v_mode integer DEFAULT 3, v_regno bigint DEFAULT 54, v_type character varying DEFAULT 'Cr'::character varying, v_amount numeric DEFAULT 100.00, v_remark character varying DEFAULT ''::character varying, v_paymentmode integer DEFAULT 10, v_paymentmodename character varying DEFAULT 'Cheque'::character varying, v_challanimage character varying DEFAULT 'ChallenImg_765433.jpg'::character varying, v_bankname character varying DEFAULT 'AXIS BANK'::character varying, v_branchname character varying DEFAULT ''::character varying, v_referencenumber character varying DEFAULT '1234567890ASD'::character varying, v_referencedate character varying DEFAULT '27-10-2021'::character varying, v_strresult character varying DEFAULT ''::character varying, v_totalcount integer DEFAULT 0, v_fromdate character varying DEFAULT ''::character varying, v_todate character varying DEFAULT ''::character varying, v_startrowindex integer DEFAULT 1, v_maxrows integer DEFAULT 100, v_ifsccode character varying DEFAULT ''::character varying, v_transactionid character varying DEFAULT ''::character varying, v_bankid integer DEFAULT 1, v_cppoint numeric DEFAULT 100, v_totalcppoint numeric DEFAULT 0) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_minindex INT;
  v_maxindex INT;
  v_query varchar(4000);
  v_quer varchar(4000);
BEGIN
  v_minindex := 1;
  v_maxindex := 100;
  v_minindex := (v_startrowindex - 1) * v_maxrows + 1;
  v_maxindex := v_startrowindex * v_maxrows;
  -- BEGIN TRAN (removed)
  BEGIN
  IF (v_mode = 1) THEN
  IF (v_referencenumber <> '') THEN
  IF EXISTS(SELECT 1 FROM tbl_merchant_fund_request WHERE referencenumber = v_referencenumber AND COALESCE(isverifiedbyadmin, 0) <> 2) THEN
  v_strresult := 'ReferenceUsed';
  -- COMMIT (removed)
  RETURN;
  END IF;
  END IF;
  RETURN QUERY SELECT 'Me';
  RETURN QUERY SELECT v_regno, v_type, v_amount, v_regno, dbo.FUN_GETCURRENTDATE(), '', 1, 1, 2, v_paymentmode, v_paymentmodename, v_challanimage, v_bankname, v_branchname, v_referencenumber, CAST(v_referencedate AS DATE), v_remark, v_ifsccode, 1, '', '', '', 0, GEN_RANDOM_UUID(), v_bankid, v_cppoint;
  INSERT INTO tbl_merchant_fund_request (regno, type, amount, byuser, date, remark, status, active, generatedby, paymentmode, paymentmodename, challanimage, bankname, branchname, referencenumber, referencedate, remarkbymember, ifsccode, isrequesteddata, btcaddress, btcuserid, btclabelname, bitcoinamount, transactionid, bankid, cppoint) VALUES (v_regno, v_type, v_amount, v_regno, dbo.FUN_GETCURRENTDATE(), '', 1, 1, 2, v_paymentmode, v_paymentmodename, v_challanimage, v_bankname, v_branchname, v_referencenumber, CAST(v_referencedate AS DATE), v_remark, v_ifsccode, 1, '', '', '', 0, GEN_RANDOM_UUID(), v_bankid, v_cppoint);
  v_strresult := 'Success';
  ELSE
  IF (v_mode = 2) THEN
  v_query := '';
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp (ROWNUMBER BIGINT GENERATED BY DEFAULT AS IDENTITY,                        
  TFHID BIGINT,                        
  REGNO BIGINT,                        
  TYPE VARCHAR(1000),                        
  AMOUNT DECIMAL(18,8),                        
  DATE VARCHAR(50),                        
  BYUSER BIGINT,                        
  REMARK text,                        
  STATUS VARCHAR(100),       
  USERNAME VARCHAR(1000),                        
  EMAILID VARCHAR(1000),                        
  FULLNAME VARCHAR(1000),           
  BYUSERFULLNAME VARCHAR(1000),                        
  BYUSERNAME VARCHAR(1000),                        
  GENERATEDBY INT,                        
  PAYMENTMODE INT,                        
  PAYMENTMODENAME VARCHAR(100),                        
  CHALLANIMAGE text,                        
  BANKNAME VARCHAR(500),                        
  BRANCHNAME text,                        
  REFERENCENUMBER text,                        
  REFERENCEDATE VARCHAR(50),                        
  REMARKBYMEMBER VARCHAR(1000),                        
  APPROVEDONDATE VARCHAR(100),                        
  IsVerifiedByAdmin Int,                        
  TransactionId varchar(200),                        
  CPPOINT DECIMAL(18,8)) ON COMMIT DROP;
  v_query := ' Insert Into #Temp Select TFH.TFHID,TFH.RegNo,TFH.Type,IsNull(TFH.Amount,0) As Amount,                        
  (CASE WHEN TFH.Date = ''1900-01-01 00:00:00.000'' THEN '''' ELSE Convert(Varchar(19),TFH.Date) End) As Date,                        
  TFH.ByUser,TFH.Remark,(Case When IsNull(TFH.Status,0) = 1 Then ''Active'' Else ''Deactive'' End) As Status,                         
  MM.COMPANYNAME AS USERNAME,IsNull(MM.COMEMAILID,'''') As EMAILID,(IsNull('''','''') +'' '' +IsNull('''','''') +'' ''+                        
   IsNull('''','''')) As FullName,(Select IsNull('''',''Admin'') +'' '' +IsNull('''','''') +'' ''+                         
   IsNull('''','''') From Db_Affiliate.DBO.MEMBER_MASTER Where RegNo = TFH.ByUser) As ByUserFullName,ISnull((Select COMPANYNAME From                         
   PORTAL_MASTER   Where PLID = TFH.ByUser),''Admin'') As ByUsername, GeneratedBy,                        
   Isnull(TFH.PaymentMode,0) As PaymentMode,Isnull(TFH.PaymentModeName,'''') As PaymentModeName,                        
  Isnull(TFH.ChallanImage,'''') As ChallanImage,Isnull(TFH.BankName,'''') As BankName,                        
  Isnull(TFH.BranchName,'''') As BranchName,Isnull(TFH.ReferenceNumber,''N/A'') As ReferenceNumber,                        
  (CASE WHEN TFH.ReferenceDate = ''1900-01-01 00:00:00.000'' THEN ''N/A'' ELSE Convert(Varchar(11),TFH.ReferenceDate)                        
   End) As ReferenceDate,  Isnull(RemarkByMember,'''') As RemarkByMember,Convert(Varchar(19),                        
   Isnull(ApprovedOnDate,NULL))As ApprovedOnDate, IsNull(IsVerifiedByAdmin,0) As IsVerifiedByAdmin,                        
   TFH.TransactionId,ISNULL(TFH.CPPOINT,0) AS CPPOINT                        
  From TBL_MERCHANT_FUND_REQUEST TFH   JOIN PORTAL_LOGIN PL                               
  ON PL.PLID = TFH.REGNO INNER JOIN PORTAL_MASTER MM ON PL.PLID=MM.PLID Where TFH.Type = ''CR'' AND IsRequestedData=1 AND                        
  PL.PLID = ' || CAST(v_regno AS VARCHAR) || '';
  IF (v_fromdate <> '' AND v_todate = '') THEN
  v_query := v_query || (' And Convert(Date,TFH.Date) >= Convert(Date,''' || v_fromdate || ''') ');
  END IF;
  IF (v_fromdate = '' AND v_todate <> '') THEN
  v_query := v_query || (' And Convert(Date,TFH.Date) <= Convert(Date,''' || v_todate || ''') ');
  END IF;
  IF (v_fromdate <> '' AND v_todate <> '') THEN
  v_query := v_query || (' And Convert(Date,TFH.Date) Between Convert(Date,''' || v_fromdate || ''') And Convert(Date,''' || v_todate || ''') ');
  END IF;
  v_query := v_query || (' Order by TFH.DATE Desc');
  RAISE NOTICE '%', v_query;
  EXECUTE v_query;
  RETURN QUERY SELECT * FROM tmp_temp WHERE rownumber BETWEEN v_minindex AND v_maxindex;
  SELECT COUNT(1) INTO v_totalcount FROM tmp_temp;
  DROP TABLE IF EXISTS tmp_temp;
  v_strresult := 'success';
  ELSE
  IF (v_mode = 3) THEN
  v_quer := '';
  DROP TABLE IF EXISTS tmp_temptd;
  CREATE TEMP TABLE tmp_temptd (ROWNUMBER BIGINT GENERATED BY DEFAULT AS IDENTITY,                  
  TFHID BIGINT,                  
  REGNO BIGINT,                  
  TYPE  varchar(50),                  
  AMOUNT DECIMAL(18,2),                  
  DATE timestamp,                  
  REMARK text,             
  USERNAME varchar(100),                  
  EMAILID varchar(100),                  
  MOBILE varchar(30),                  
  MESSAGE text,                
  NAME VARCHAR(100)) ON COMMIT DROP;
  v_quer := 'INSERT INTO #TEMPTD SELECT TFH.TFHID,TFH.REGNO,TFH.TYPE,ISNULL(TFH.AMOUNT,0) AS AMOUNT,ISNULL(TFH.DATE,'''') AS DATE,                  
 TFH.REMARK,CL.USERNAME AS USERNAME,ISNULL(CL.EMAILID,'''') AS EMAILID,ISNULL(CL.MOBILE,'''') AS MOBILE,                
 ISNULL(TFH.P_TYPE,'''') AS MESSAGE ,ISNULL(CL.FNAME,'''') AS NAME                
  FROM TBL_MERCHANT_FUND_HISTORY TFH   INNER JOIN DB_AFFILIATE.DBO.MEMBER_MASTER CL   ON                         
  CL.REGNO = TFH.BYUSER WHERE TFH.TYPE=''Dr'' ';
  IF (v_regno > 0) THEN
  v_quer := v_quer || (' AND  TFH.REGNO=' || CAST(v_regno AS VARCHAR(10)) || '');
  END IF;
  IF (v_fromdate <> '' AND v_todate = '') THEN
  v_quer := v_quer || (' AND CONVERT(DATE,TFH.DATE,105) >= CONVERT(DATE,''' || v_fromdate || ''',105) ');
  END IF;
  IF (v_fromdate = '' AND v_todate <> '') THEN
  v_quer := v_quer || (' AND CONVERT(DATE,TFH.DATE,105) <= CONVERT(DATE,''' || v_todate || ''',105) ');
  END IF;
  IF (v_fromdate <> '' AND v_todate <> '') THEN
  v_quer := v_quer || (' AND CONVERT(DATE,TFH.DATE,15) BETWEEN CONVERT(DATE,''' || v_fromdate || ''',105) AND CONVERT(DATE,''' || v_todate || ''',105) ');
  END IF;
  v_quer := v_quer || (' Order by TFH.DATE Desc');
  EXECUTE v_quer;
  RAISE NOTICE '%', v_quer;
  RETURN QUERY SELECT * FROM tmp_temptd WHERE rownumber BETWEEN v_minindex AND v_maxindex ORDER BY rownumber ASC NULLS FIRST;
  SELECT COUNT(1) INTO v_totalcount FROM tmp_temptd;
  SELECT COALESCE(SUM(amount), 0) INTO v_totalcppoint FROM tmp_temptd;
  DROP TABLE IF EXISTS tmp_temptd;
  END IF;
  END IF;
  END IF;
  EXCEPTION WHEN OTHERS THEN
  PERFORM dbo.sp_errorlog();
  IF (0 > 0) THEN
  -- ROLLBACK (removed)
  END IF;
  RETURN;
  END;
  IF (0 <> 0) THEN
  RETURN QUERY SELECT sqlerrm;
  v_strresult := 'ERROR';
  -- ROLLBACK (removed)
  RETURN;
  ELSE
  -- COMMIT (removed)
  END IF;
END;
$$;


--
-- Name: usp_merchant_ordertransactions(integer, integer, character varying, character varying, integer, character varying, character varying, integer, bigint, character varying, integer, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_merchant_ordertransactions(v_startrowindex integer DEFAULT 1, v_maxrows integer DEFAULT 100, v_fromdate character varying DEFAULT ''::character varying, v_todate character varying DEFAULT ''::character varying, v_mode integer DEFAULT 1, v_orderid character varying DEFAULT ''::character varying, v_invoiceno character varying DEFAULT ''::character varying, v_totalcount integer DEFAULT 0, v_plid bigint DEFAULT 36, v_status character varying DEFAULT ''::character varying, v_did integer DEFAULT 0, v_searchbusinesstype integer DEFAULT 0) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_minindex INT;
  v_maxindex INT;
  v_query text;
BEGIN
  v_minindex := (v_startrowindex - 1) * v_maxrows + 1;
  v_maxindex := v_startrowindex * v_maxrows;
  IF (v_mode = 1) THEN
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp (ROWNUMBER BIGINT GENERATED BY DEFAULT AS IDENTITY,      
TMORID INT,      
INVOICENO VARCHAR(100),      
INVOICEDATE VARCHAR(100),      
ORDERID VARCHAR(100),      
DISPATCHDATE VARCHAR(100),      
DELIVERYDATE VARCHAR(100),      
DUEDATE VARCHAR(100),      
INVOICEAMOUNT DECIMAL(18,2),      
STATUS Varchar(100),      
MerchantName VARCHAR(100),      
MerchantEmailId VARCHAR(100)) ON COMMIT DROP;
  v_query := 'INSERT INTO #TEMP SELECT TMORID,INVOICENO,      
REPLACE(CONVERT(VARCHAR(11), INVOICEDATE, 106), '' '', ''-''),ORDERID,      
REPLACE(CONVERT(VARCHAR(11), DISPATCHDATE, 106), '' '', ''-''),      
REPLACE(CONVERT(VARCHAR(11), (CASE WHEN DELIVERYDATE IS NULL THEN '''' ELSE DELIVERYDATE END), 106), '' '', ''-''),      
REPLACE(CONVERT(VARCHAR(11), (CASE WHEN DUEDATE IS NULL THEN '''' ELSE DUEDATE END), 106), '' '', ''-''),      
INVOICEAMOUNT,TBL_MERCHANT_ORDERTRANSACTIONS.STATUS,      
ISNULL(PM.COMPANYNAME,ISNULL(PL.FNAME,'''')),PL.EMAILID FROM  TBL_MERCHANT_ORDERTRANSACTIONS         
LEFT JOIN PORTAL_LOGIN PL ON PL.PLID=TBL_MERCHANT_ORDERTRANSACTIONS.PLID       
LEFT JOIN PORTAL_MASTER PM ON PM.PLID=PL.PLID WHERE 1=1';
  IF (v_searchbusinesstype > 0) THEN
  v_query := v_query || ' AND PM.BUSINESSTYPE=' || CAST(v_searchbusinesstype AS VARCHAR(100)) || ' ';
  END IF;
  IF ((v_fromdate <> '') AND (v_todate = '')) THEN
  v_query := v_query || ' AND CONVERT(VARCHAR, CONVERT(DATE, INVOICEDATE, 105) ) BETWEEN  CONVERT(DATE, ''' || v_fromdate || ''', 105) AND  CONVERT(DATE, DBO.FUN_GETCURRENTDATE(), 105)';
  END IF;
  IF ((v_fromdate = '') AND (v_todate <> '')) THEN
  v_query := v_query || 'AND CONVERT(DATE, INVOICEDATE, 105) BETWEEN  CONVERT(DATE, ''' || v_todate || ''', 105) AND  CONVERT(DATE, DBO.FUN_GETCURRENTDATE(), 105)';
  END IF;
  IF ((v_fromdate <> '') AND (v_todate <> '')) THEN
  v_query := v_query || 'AND CONVERT(DATE, INVOICEDATE, 105) BETWEEN CONVERT(DATE, ''' || v_fromdate || ''', 105) AND  CONVERT(DATE, ''' || v_todate || ''', 105)';
  END IF;
  IF (v_invoiceno <> '') THEN
  v_query := v_query || 'AND INVOICENO=''' || CAST(v_invoiceno AS VARCHAR(100)) || ''' ';
  END IF;
  IF (v_orderid <> '') THEN
  v_query := v_query || 'AND ORDERID=''' || CAST(v_orderid AS VARCHAR(100)) || ''' ';
  END IF;
  IF (v_status <> '') THEN
  v_query := v_query || ' AND TBL_MERCHANT_ORDERTRANSACTIONS.STATUS= ''' || CAST(v_status AS VARCHAR(100)) || ''' ';
  END IF;
  IF (v_plid > 0) THEN
  v_query := v_query || ' AND TBL_MERCHANT_ORDERTRANSACTIONS.PLID= ' || CAST(v_plid AS VARCHAR(100)) || '';
  END IF;
  IF (v_did > 0) THEN
  v_query := v_query || ' AND PL.PLID IN(SELECT PLID FROM PORTAL_MASTER WHERE CID IN(SELECT CID FROM DISTRIBUTOR_MASTER WHERE PLID=' || CAST(v_did AS VARCHAR(50)) || '))';
  END IF;
  v_query := v_query || ' ORDER BY CONVERT(DATETIME, INVOICEDATE) DESC';
  EXECUTE v_query;
  RETURN QUERY SELECT ROW_NUMBER() OVER (ORDER BY CAST(invoicedate AS TIMESTAMP) DESC NULLS LAST) AS rownumber, tmorid, invoiceno, invoicedate, orderid, (CASE WHEN dispatchdate = '01-Jan-1900' THEN 'N/A' ELSE dispatchdate END) AS dispatchdate, (CASE WHEN deliverydate = '01-Jan-1900' THEN 'N/A' ELSE deliverydate END) AS deliverydate, (CASE WHEN duedate = '01-Jan-1900' THEN 'N/A' ELSE duedate END) AS duedate, invoiceamount, status, merchantname, merchantemailid FROM tmp_temp WHERE rownumber BETWEEN v_minindex AND v_maxindex;
  SELECT COUNT(rownumber) INTO v_totalcount FROM tmp_temp;
  DROP TABLE IF EXISTS tmp_temp;
  -- SET option (removed)
  END IF;
END;
$$;


--
-- Name: usp_merchant_ordertransactions_admin(integer, integer, character varying, character varying, integer, character varying, character varying, integer, character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_merchant_ordertransactions_admin(v_startrowindex integer DEFAULT 1, v_maxrows integer DEFAULT 100, v_fromdate character varying DEFAULT ''::character varying, v_todate character varying DEFAULT ''::character varying, v_mode integer DEFAULT 1, v_searchfield character varying DEFAULT ''::character varying, v_searchvalue character varying DEFAULT ''::character varying, v_totalcount integer DEFAULT 0, v_merchantname character varying DEFAULT ''::character varying) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_minindex INT;
  v_maxindex INT;
  v_query text;
BEGIN
  v_minindex := (v_startrowindex - 1) * v_maxrows + 1;
  v_maxindex := v_startrowindex * v_maxrows;
  IF (v_mode = 1) THEN
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp (ROWNUMBER BIGINT GENERATED BY DEFAULT AS IDENTITY,
TMORID INT,
INVOICENO VARCHAR(100),
INVOICEDATE VARCHAR(100),
ORDERID VARCHAR(100),
DISPATCHDATE VARCHAR(100),
DELIVERYDATE VARCHAR(100),
DUEDATE VARCHAR(100),
INVOICEAMOUNT DECIMAL(18,2),
STATUS Varchar(100),
COMPANYNAME varchar(200),
PHONE varchar(200),
EMAILID varchar(200)) ON COMMIT DROP;
  v_query := 'INSERT INTO #TEMP  SELECT TMORID,INVOICENO,Convert(DATE,INVOICEDATE,105),ORDERID,CONVERT(DATE,DISPATCHDATE,105),
CONVERT(DATE,DELIVERYDATE,105),CONVERT(DATE,DUEDATE,105),
INVOICEAMOUNT,MOT.STATUS,ISNULL(PM.COMPANYNAME,''''),ISNULL(PL.PHONE,''''),ISNULL(PL.EMAILID,'''') FROM  TBL_MERCHANT_ORDERTRANSACTIONS MOT LEFT JOIN PORTAL_LOGIN PL ON MOT.PLID=PL.PLID
LEFT JOIN PORTAL_MASTER PM ON PM.PLID=PL.PLID  WHERE 1=1 ';
  IF ((v_fromdate <> '') AND (v_todate = '')) THEN
  v_query := v_query || ' AND CONVERT(VARCHAR, CONVERT(DATE, INVOICEDATE, 105) ) BETWEEN  CONVERT(DATE, ''' || v_fromdate || ''', 105) AND  CONVERT(DATE, DBO.FUN_GETCURRENTDATE(), 105)';
  END IF;
  IF ((v_fromdate = '') AND (v_todate <> '')) THEN
  v_query := v_query || 'AND CONVERT(DATE, INVOICEDATE, 105) BETWEEN  CONVERT(DATE, ''' || v_todate || ''', 105) AND  CONVERT(DATE, DBO.FUN_GETCURRENTDATE(), 105)';
  END IF;
  IF ((v_fromdate <> '') AND (v_todate <> '')) THEN
  v_query := v_query || 'AND CONVERT(DATE, INVOICEDATE, 105) BETWEEN CONVERT(DATE, ''' || v_fromdate || ''', 105) AND  CONVERT(DATE, ''' || v_todate || ''', 105)';
  END IF;
  IF (v_merchantname <> '') THEN
  v_query := v_query || ' AND PM.COMPANYNAME= ''' || v_merchantname || ''' ';
  END IF;
  IF (v_searchfield = 'EMAILID') THEN
  v_query := v_query || ' AND EMAILID= ''' || v_searchvalue || ''' ';
  END IF;
  IF (v_searchfield = 'PHONE') THEN
  v_query := v_query || ' AND PHONE= ''' || v_searchvalue || ''' ';
  END IF;
  IF (v_searchfield = 'ORDERID') THEN
  v_query := v_query || ' AND ORDERID= ''' || v_searchvalue || ''' ';
  END IF;
  IF (v_searchfield = 'INVOICENO') THEN
  v_query := v_query || ' AND INVOICENO= ''' || v_searchvalue || ''' ';
  END IF;
  v_query := v_query || ' Order By INVOICEDATE Desc';
  EXECUTE v_query;
  RAISE NOTICE '%', (v_query);
  RETURN QUERY SELECT rownumber, tmorid, invoiceno, invoicedate, orderid, (CASE WHEN dispatchdate = '1900-01-01' THEN 'N/A' ELSE dispatchdate END) AS dispatchdate, (CASE WHEN deliverydate = '1900-01-01' THEN 'N/A' ELSE deliverydate END) AS deliverydate, (CASE WHEN duedate = '1900-01-01' THEN 'N/A' ELSE duedate END) AS duedate, invoiceamount, status, companyname, phone, emailid FROM tmp_temp WHERE rownumber BETWEEN v_minindex AND v_maxindex;
  SELECT COUNT(rownumber) INTO v_totalcount FROM tmp_temp;
  DROP TABLE IF EXISTS tmp_temp;
  -- SET option (removed)
  END IF;
END;
$$;


--
-- Name: usp_merchant_payoutreport(integer, integer, character varying, character varying, character varying, character varying, integer, bigint, character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_merchant_payoutreport(v_startrowindex integer DEFAULT 1, v_maxrows integer DEFAULT 100, v_searchfield character varying DEFAULT ''::character varying, v_searchvalue character varying DEFAULT ''::character varying, v_fromdate character varying DEFAULT ''::character varying, v_todate character varying DEFAULT ''::character varying, v_totalcount integer DEFAULT 0, v_plid bigint DEFAULT 0, v_status character varying DEFAULT ''::character varying) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_minindex INT;
  v_maxindex INT;
  v_query text;
BEGIN
  v_minindex := (v_startrowindex - 1) * v_maxrows + 1;
  v_maxindex := v_startrowindex * v_maxrows;
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp (ROWNUMBER INT GENERATED BY DEFAULT AS IDENTITY, 
	ACCOUNTHOLDERNAME VARCHAR(500), 
    PAYDATE timestamp, 
	PAYOUTAMOUNT DECIMAL (10,2),     
	ACCOUNTNO  VARCHAR(50),        
	TRANS_ID VARCHAR(100),	
	DATE VARCHAR(100),	
	STATUS VARCHAR(50),
	BANKNAME VARCHAR(50),
	IFSCCODE VARCHAR(50),
	BRANCHNAME VARCHAR(50)) ON COMMIT DROP;
  v_query := 'INSERT INTO #TEMP SELECT BAM.ACCOUNTHOLDERNAME,MP.PAYDATE,(MW.PAYBLEAMOUNT)as PAYOUTAMOUNT,BAM.ACCOUNTNO,MW.TRANS_ID,CONVERT(VARCHAR,MW.DATE,106) AS DATE,MW.STATUS,BAM.BANKNAME,BAM.IFSCCODE,BAM.BRANCHNAME FROM TBL_MERCHANT_PAYOUT MP 
LEFT JOIN TBL_MERCHANT_WITHDRAWALS MW ON MW.PAYID=MP.PAYID
LEFT JOIN BANK_ACCOUNTS_MERCHANT BAM ON BAM.ACID=MW.ACID WHERE 1=1 ';
  IF ((v_fromdate <> '') AND (v_todate = '')) THEN
  v_query := v_query || ' AND CONVERT(DATE, DATE, 105) BETWEEN  CONVERT(DATE, ''' || v_fromdate || ''', 105) AND  CONVERT(DATE, DBO.FUN_GETCURRENTDATE(), 105)';
  END IF;
  IF ((v_fromdate = '') AND (v_todate <> '')) THEN
  v_query := v_query || 'AND CONVERT(DATE, DATE, 105) BETWEEN  CONVERT(DATE, ''' || v_todate || ''', 105) AND  CONVERT(DATE, DBO.FUN_GETCURRENTDATE(), 105)';
  END IF;
  IF ((v_fromdate <> '') AND (v_todate <> '')) THEN
  v_query := v_query || 'AND CONVERT(DATE, DATE, 105) BETWEEN CONVERT(DATE, ''' || v_fromdate || ''', 105) AND  CONVERT(DATE, ''' || v_todate || ''', 105)';
  END IF;
  IF (v_plid > 0) THEN
  v_query := v_query || ' AND MW.PLID= ' || CAST(v_plid AS VARCHAR(100)) || '';
  END IF;
  IF (v_searchfield <> '') THEN
  v_query := v_query || ' AND BAM.ACCOUNTNO= ''' || v_searchfield || ''' ';
  END IF;
  IF (v_searchvalue <> '') THEN
  v_query := v_query || ' AND MW.TRANS_ID= ''' || v_searchvalue || ''' ';
  END IF;
  IF (v_status <> '') THEN
  v_query := v_query || ' AND MW.STATUS=''' || v_status || ''' ';
  END IF;
  v_query := v_query || ' Order By  CONVERT(VARCHAR,MW.DATE,106) desc ';
  EXECUTE v_query;
  RAISE NOTICE '%', v_query;
  RETURN QUERY SELECT * FROM tmp_temp WHERE rownumber BETWEEN v_minindex AND v_maxindex;
  SELECT COUNT(rownumber) INTO v_totalcount FROM tmp_temp;
  DROP TABLE IF EXISTS tmp_temp;
  -- SET option (removed)
END;
$$;


--
-- Name: usp_merchant_purchase_packages(integer, integer, character varying, character varying, character varying, character varying, character varying, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_merchant_purchase_packages(v_startrowindex integer DEFAULT 1, v_maxrows integer DEFAULT 1000, v_searchfield character varying DEFAULT ''::character varying, v_searchvalue character varying DEFAULT ''::character varying, v_fromdate character varying DEFAULT ''::character varying, v_todate character varying DEFAULT ''::character varying, v_merchantname character varying DEFAULT ''::character varying, v_totalcount integer DEFAULT 0) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_minindex INT;
  v_maxindex INT;
  v_query text;
  v_tempplid text;
  v_index INT;
  v_slice text;
  v_totalpayable DECIMAL(18,2);
  v_totalpaid DECIMAL(18,2);
BEGIN
  v_tempplid := '';
  v_index := 1;
  v_slice := '';
  v_totalpayable := 0;
  v_totalpaid := 0;
  v_minindex := (v_startrowindex - 1) * v_maxrows + 1;
  v_maxindex := v_startrowindex * v_maxrows;
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp (ROWNUMBER INT GENERATED BY DEFAULT AS IDENTITY,        
	PLID BIGINT,
	NAME VARCHAR(500),				         
    PHONE VARCHAR(500),
	EMAILID  VARCHAR(500),
	PACKAGESNAME  VARCHAR(500),
	AMOUNT DECIMAL(18,2),
	PURCHASEDDATE timestamp,
	ACTIVATIONDAYS int,
	Wallet1 DECIMAL(18,2),
	Wallet2 DECIMAL(18,2)) ON COMMIT DROP;
  v_query := 'INSERT INTO #TEMP SELECT DISTINCT PL.PLID,isnull(PM.COMPANYNAME,''''),isnull(PL.PHONE,''''),isnull(PL.EMAILID,''''),MP.NAME as PACKAGESNAME,
			MP.AMOUNT,MPP.PURCHASEDDATE,MP.ACTIVATIONDAYS,OD.MLMWALLET,OD.CUSTOMERWALLET
			FROM TBL_MERCHANTPACKEAGES  as MP
			inner join TBL_MERCHANT_PURCHASED_PACKAGES as MPP on MPP.PMID=MP.MPID
			inner join TBL_MERCHANTPACKAGEPURCHASE_ONLINEREQUESTS as OP on OP.PLID=MPP.PLID
			inner join  TBL_ORDERPAYMENTSDETAILS as OD on OD.TRANSID=OP.TRANSACTIONID
			LEFT JOIN PORTAL_LOGIN PL ON MPP.PLID=PL.PLID
			LEFT JOIN PORTAL_MASTER PM ON PM.PLID=MPP.PLID 
			WHERE  1=1';
  IF ((v_fromdate <> '') AND (v_todate = '')) THEN
  v_query := v_query || ' AND CONVERT(DATE, CREATEDATE, 105) BETWEEN  CONVERT(DATE, ''' || v_fromdate || ''', 105) AND  CONVERT(DATE, DBO.FUN_GETCURRENTDATE(), 105)';
  END IF;
  IF ((v_fromdate = '') AND (v_todate <> '')) THEN
  v_query := v_query || 'AND CONVERT(DATE, CREATEDATE, 105) BETWEEN  CONVERT(DATE, ''' || v_todate || ''', 105) AND  CONVERT(DATE, DBO.FUN_GETCURRENTDATE(), 105)';
  END IF;
  IF ((v_fromdate <> '') AND (v_todate <> '')) THEN
  v_query := v_query || 'AND CONVERT(DATE, CREATEDATE, 105) BETWEEN CONVERT(DATE, ''' || v_fromdate || ''', 105) AND  CONVERT(DATE, ''' || v_todate || ''', 105)';
  END IF;
  IF (v_merchantname <> '') THEN
  v_query := v_query || ' AND PM.COMPANYNAME=''' || v_merchantname || '''';
  END IF;
  IF (v_searchfield = 'EMAILID') THEN
  v_query := v_query || ' AND PL.EMAILID= ''' || v_searchvalue || ''' ';
  END IF;
  IF (v_searchfield = 'LOGINID') THEN
  v_query := v_query || ' AND PL.LOGINID= ''' || v_searchvalue || ''' ';
  END IF;
  IF (v_searchfield = 'PHONE') THEN
  v_query := v_query || ' AND PL.PHONE= ''' || v_searchvalue || ''' ';
  END IF;
  EXECUTE v_query;
  RETURN QUERY SELECT * FROM tmp_temp WHERE rownumber BETWEEN v_minindex AND v_maxindex;
  SELECT COUNT(rownumber) INTO v_totalcount FROM tmp_temp;
  DROP TABLE IF EXISTS tmp_temp;
  -- SET option (removed)
END;
$$;


--
-- Name: usp_merchant_settlement(bigint); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_merchant_settlement(INOUT v_totalcount bigint DEFAULT 0) RETURNS bigint
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_gstpercentage DECIMAL(18,2);
  v_plid INT;
BEGIN
  -- BEGIN TRAN (removed)
  -- SET option (removed)
  v_gstpercentage := 0;
  v_plid := 1;
  SELECT COALESCE(limits, 0) INTO v_gstpercentage FROM settings WHERE caption = 'GST PERCENTAGE' AND active = 1;
  INSERT INTO tbl_merchant_settlement SELECT COALESCE(invoice.invoiceno, '') AS invoiceno, pom.orderid AS orderid, pom.orderno AS orderno, COALESCE(single_dap, 0) AS productactualamount, COALESCE((pom.single_dap * sp.admincharge) / 100, 0) AS admincharge, sp.delieverycharge, sp.handlingcharge, sp.fixedfee, (COALESCE((pom.single_dap * sp.admincharge) / 100, 0) * v_gstpercentage) / 100 AS admingst, (sp.delieverycharge * v_gstpercentage) / 100 AS deleverygst, (sp.handlingcharge * v_gstpercentage) / 100 AS handlinggst, (sp.fixedfee * v_gstpercentage / 100) AS fixedfeegst, ((((pom.single_dap * sp.admincharge) / 100) + sp.delieverycharge + sp.handlingcharge + sp.fixedfee) * v_gstpercentage) / 100 AS totalgst, (((pom.single_dap * sp.admincharge) / 100) + sp.delieverycharge + sp.handlingcharge + sp.fixedfee) AS marketplacefee, pom.status AS status, CAST(TO_CHAR(oc.delivered, 'DD TMMon YYYY') AS VARCHAR(100)) AS completeddate, CAST(TO_CHAR(om.orderdate, 'DD TMMon YYYY') AS VARCHAR(100)) AS orderdate, om.branchid, 0, dbo.FUN_GETCURRENTDATE() FROM tbl_product_order_master AS pom INNER JOIN tbl_order_master AS om ON pom.orderid = om.orderid LEFT JOIN portal_login AS pl ON pl.plid = pom.plid LEFT JOIN portal_master AS pm ON pm.plid = pl.plid INNER JOIN ims_subproduct AS sp ON pom.subprcode = sp.sprid INNER JOIN tbl_order_confirmedstaus AS oc ON pom.orderno = oc.orderno LEFT JOIN tbl_merchant_commissioninvoices AS invoice ON pl.plid = invoice.plid WHERE pom.intstatus = 6 AND NOT pom.orderno IN (SELECT orderno FROM tbl_merchant_settlement);
  SELECT COUNT(*) INTO v_totalcount FROM tbl_merchant_settlement WHERE paidstautus = 0;
  IF (0 <> 0) THEN
  -- ROLLBACK (removed)
  v_totalcount := 0;
  RETURN;
  END IF;
  -- SET option (removed)
  -- COMMIT (removed)
END;
$$;


--
-- Name: usp_merchant_settlement_commission(integer, integer, character varying, character varying, character varying, character varying, integer, bigint, integer, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_merchant_settlement_commission(v_startrowindex integer DEFAULT 1, v_maxrows integer DEFAULT 100, v_searchfield character varying DEFAULT ''::character varying, v_searchvalue character varying DEFAULT ''::character varying, v_fromdate character varying DEFAULT ''::character varying, v_todate character varying DEFAULT ''::character varying, v_totalcount integer DEFAULT 0, v_plid bigint DEFAULT 36, v_did integer DEFAULT 0, v_searchbusinesstype integer DEFAULT 0) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_minindex INT;
  v_maxindex INT;
  v_query text;
BEGIN
  v_minindex := (v_startrowindex - 1) * v_maxrows + 1;
  v_maxindex := v_startrowindex * v_maxrows;
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp (ROWNUMBER INT GENERATED BY DEFAULT AS IDENTITY ,  
 TMSCID BIGINT,   
 DUEDATE VARCHAR(500),        
 INVOICENO VARCHAR(500),   
 INVOICEDATE VARCHAR(200),   
 ORDERID VARCHAR(500),  
 GROSSAMOUNT DECIMAL(18,8),  
 COMMISSIONS DECIMAL(18,8),   
 TAXDEDUCTIONS DECIMAL(18,8),  
 NETPAYABLE DECIMAL(18,8),   
 STATUS INT,  
 ACTIVE INT,  
 CREATEDATE VARCHAR(200),  
 CUSTOMERINVOICE varchar(100),   
MerchantName VARCHAR(100),  
MerchantEmailId VARCHAR(100)) ON COMMIT DROP;
  v_query := 'INSERT INTO #TEMP SELECT MSC.TMSCID,  
 REPLACE(CONVERT(VARCHAR(11), MSC.DUEDATE, 106), '' '', ''-'') ,  
 MSC.INVOICENO,MSC.INVOICEDATE,MSC.ORDERID,MSC.GROSSAMOUNT,MSC.COMMISSIONS,MSC.TAXDEDUCTIONS,  
 MSC.NETPAYABLE,MSC.STATUS,MSC.ACTIVE,MSC.CREATEDATE,MOT.INVOICENO,  
 ISNULL(PM.COMPANYNAME,ISNULL(PL.FNAME,'''')),PL.EMAILID   FROM TBL_MERCHANT_SETTLEMENT_COMMISSIONS MSC  
 LEFT JOIN TBL_MERCHANT_ORDERTRANSACTIONS MOT ON MSC.TMORID=MOT.TMORID  
 LEFT JOIN PORTAL_LOGIN PL ON PL.PLID=MOT.PLID   
 LEFT JOIN PORTAL_MASTER PM ON PM.PLID=PL.PLID   
 WHERE 1=1 ';
  IF (v_searchbusinesstype > 0) THEN
  v_query := v_query || ' AND PM.BUSINESSTYPE=' || CAST(v_searchbusinesstype AS VARCHAR(100)) || ' ';
  END IF;
  IF ((v_fromdate <> '') AND (v_todate = '')) THEN
  v_query := v_query || ' AND CONVERT(DATE, MSC.DUEDATE, 105) BETWEEN  CONVERT(DATE, ''' || v_fromdate || ''', 105) AND  CONVERT(DATE, DBO.FUN_GETCURRENTDATE(), 105)';
  END IF;
  IF ((v_fromdate = '') AND (v_todate <> '')) THEN
  v_query := v_query || 'AND CONVERT(DATE, MSC.DUEDATE, 105) BETWEEN  CONVERT(DATE, ''' || v_todate || ''', 105) AND  CONVERT(DATE, DBO.FUN_GETCURRENTDATE(), 105)';
  END IF;
  IF ((v_fromdate <> '') AND (v_todate <> '')) THEN
  v_query := v_query || 'AND CONVERT(DATE,MSC.DUEDATE, 105) BETWEEN CONVERT(DATE, ''' || v_fromdate || ''', 105) AND  CONVERT(DATE, ''' || v_todate || ''', 105)';
  END IF;
  IF (v_searchfield <> '') THEN
  v_query := v_query || ' AND MSC.INVOICENO= ''' || v_searchfield || ''' ';
  END IF;
  IF (v_searchvalue <> '') THEN
  v_query := v_query || ' AND MSC.ORDERID= ''' || v_searchvalue || ''' ';
  END IF;
  IF (v_plid > 0) THEN
  v_query := v_query || ' AND MSC.PLID= ' || CAST(v_plid AS VARCHAR(100)) || '';
  END IF;
  IF (v_did > 0) THEN
  v_query := v_query || (' AND PL.PLID In(SELECT PLID FROM PORTAL_MASTER WHERE CID IN(SELECT CID FROM DISTRIBUTOR_MASTER WHERE PLID=' || CAST(v_did AS VARCHAR(5)) || '))');
  END IF;
  v_query := v_query || ' ORDER BY CONVERT(DATETIME,MSC.INVOICEDATE) DESC ';
  EXECUTE v_query;
  RAISE NOTICE '%', v_query;
  RETURN QUERY SELECT * FROM tmp_temp WHERE rownumber BETWEEN v_minindex AND v_maxindex;
  SELECT COUNT(rownumber) INTO v_totalcount FROM tmp_temp;
  DROP TABLE IF EXISTS tmp_temp;
  -- SET option (removed)
END;
$$;


