    LANGUAGE plpgsql
    AS $$
DECLARE
  v_minindex int;
  v_maxindex int;
  v_query text;
BEGIN
  v_minindex := (v_startrowindex - 1) * v_maxrows + 1;
  v_maxindex := v_startrowindex * v_maxrows;
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp (ROWNUMBER int GENERATED BY DEFAULT AS IDENTITY ,
	TMSCID bigint, 
	DUEDATE varchar(500),      
	INVOICENO varchar(500),	
	INVOICEDATE varchar(200), 
	ORDERID varchar(500),
	GROSSAMOUNT DECIMAL(18,8),
	COMMISSIONS DECIMAL(18,8),	
	TAXDEDUCTIONS DECIMAL(18,8),
	NETPAYABLE DECIMAL(18,8),	
	STATUS INT,
	ACTIVE INT,
	CREATEDATE varchar(200),
	COMPANYNAME varchar(200),
	PHONE varchar(200),
	EMAILID varchar(200),
	CUSTOMERINVOICE varchar(100)) ON COMMIT DROP;
  v_query := 'insert into #temp select MSC.TMSCID,MSC.DUEDATE,MSC.INVOICENO,MSC.INVOICEDATE,MSC.ORDERID,MSC.GROSSAMOUNT,MSC.COMMISSIONS,MSC.TAXDEDUCTIONS,MSC.NETPAYABLE,MSC.STATUS,MSC.ACTIVE,
 MSC.CREATEDATE,ISNULL(PM.COMPANYNAME,''''),ISNULL(PL.PHONE,''''),ISNULL(PL.EMAILID,''''),MOT.INVOICENO   FROM TBL_MERCHANT_SETTLEMENT_COMMISSIONS MSC LEFT JOIN PORTAL_LOGIN PL ON MSC.Plid=PL.PLID
 Left join TBL_MERCHANT_ORDERTRANSACTIONS MOT ON MSC.TMORID=MOT.TMORID
 LEFT JOIN PORTAL_MASTER PM ON PM.PLID=PL.PLID WHERE 1=1 ';
  IF ((v_fromdate <> '') AND (v_todate = '')) THEN
  v_query := v_query || ' AND CONVERT(DATE, DUEDATE, 105) BETWEEN  CONVERT(DATE, ''' || v_fromdate || ''', 105) AND  CONVERT(DATE, DBO.FUN_GETCURRENTDATE(), 105)';
  END IF;
  IF ((v_fromdate = '') AND (v_todate <> '')) THEN
  v_query := v_query || 'AND CONVERT(DATE, DUEDATE, 105) BETWEEN  CONVERT(DATE, ''' || v_todate || ''', 105) AND  CONVERT(DATE, DBO.FUN_GETCURRENTDATE(), 105)';
  END IF;
  IF ((v_fromdate <> '') AND (v_todate <> '')) THEN
  v_query := v_query || 'AND CONVERT(DATE,DUEDATE, 105) BETWEEN CONVERT(DATE, ''' || v_fromdate || ''', 105) AND  CONVERT(DATE, ''' || v_todate || ''', 105)';
  END IF;
  IF ((v_frominvoicedate <> '') AND (v_toinvoicedate = '')) THEN
  v_query := v_query || ' AND CONVERT(DATE, MSC.INVOICEDATE, 105) BETWEEN  CONVERT(DATE, ''' || v_frominvoicedate || ''', 105) AND  CONVERT(DATE, DBO.FUN_GETCURRENTDATE(), 105)';
  END IF;
  IF ((v_frominvoicedate = '') AND (v_toinvoicedate <> '')) THEN
  v_query := v_query || 'AND CONVERT(DATE, MSC.INVOICEDATE, 105) BETWEEN  CONVERT(DATE, ''' || v_toinvoicedate || ''', 105) AND  CONVERT(DATE, DBO.FUN_GETCURRENTDATE(), 105)';
  END IF;
  IF ((v_frominvoicedate <> '') AND (v_toinvoicedate <> '')) THEN
  v_query := v_query || 'AND CONVERT(DATE,MSC.INVOICEDATE, 105) BETWEEN CONVERT(DATE, ''' || v_fromdate || ''', 105) AND  CONVERT(DATE, ''' || v_toinvoicedate || ''', 105)';
  END IF;
  IF (v_searchfield <> '') THEN
  v_query := v_query || ' AND EMAILID= ''' || v_searchfield || ''' ';
  END IF;
  IF (v_searchvalue <> '') THEN
  v_query := v_query || ' AND INVOICENO= ''' || v_searchvalue || ''' ';
  END IF;
  IF (v_merchantname <> '') THEN
  v_query := v_query || ' AND COMPANYNAME= ''' || v_merchantname || ''' ';
  END IF;
  v_query := v_query || ' Order By  MSC.CREATEDATE  Desc';
  EXECUTE v_query;
  RETURN QUERY SELECT * FROM tmp_temp WHERE rownumber BETWEEN v_minindex AND v_maxindex;
  SELECT COUNT(rownumber) INTO v_totalcount FROM tmp_temp;
  DROP TABLE IF EXISTS tmp_temp;
  -- SET option (removed)
END;
$$;


--
