--
-- Name: usp_merchant_statement_summary(integer, character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_merchant_statement_summary(v_plid integer DEFAULT 1015, v_date character varying DEFAULT ''::character varying) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_month VARCHAR(100);
  v_year VARCHAR(100);
  v_count INT;
  v_totalcount INT;
  v_templid INT;
  v_admincommssion DECIMAL(18,2);
  v_fixedfee DECIMAL(18,2);
  v_handling DECIMAL(18,2);
  v_shipping DECIMAL(18,2);
  v_cgstrate DECIMAL(18,2);
  v_sgstrate DECIMAL(18,2);
  v_igstrate DECIMAL(18,2);
  v_cgst DECIMAL(18,2);
  v_sgst DECIMAL(18,2);
  v_igst DECIMAL(18,2);
BEGIN
  -- BEGIN TRAN (removed)
  -- SET option (removed)
  v_month := '';
  v_year := '';
  v_count := 1;
  v_totalcount := 0;
  v_templid := 0;
  v_admincommssion := 0;
  v_fixedfee := 0;
  v_handling := 0;
  v_shipping := 0;
  v_sgstrate := 0;
  v_igstrate := 0;
  v_cgst := 0;
  v_sgst := 0;
  v_igst := 0;
  IF (v_date = '') THEN
  v_date := dbo.FUN_GETCURRENTDATE();
  END IF;
  SELECT EXTRACT(MONTH FROM CAST(v_date AS DATE)), EXTRACT(YEAR FROM CAST(v_date AS DATE)) INTO v_month, v_year;
  DROP TABLE IF EXISTS tmp_statement_summary_temp;
  CREATE TEMP TABLE tmp_statement_summary_temp (ROWNUMBER INT GENERATED BY DEFAULT AS IDENTITY,
 SALEAMOUNT DECIMAL(18,2),
 REFUNDS DECIMAL(18,2),
 ADMINCOMSSION DECIMAL(18,2),
 FIXEDFEE DECIMAL(18,2),
 SHIPINGFEE DECIMAL(18,2),
 HANDLING DECIMAL(18,2),
 SGST DECIMAL(18,2),
 CGST DECIMAL(18,2),
 IGST DECIMAL(18,2),
 PLID INT) ON COMMIT DROP;
  INSERT INTO tmp_statement_summary_temp SELECT DISTINCT SUM(msc.grossamount) OVER (), 0, SUM(msc.commissions) OVER (), 0, 0, 0, 0, 0, 0, plid FROM tbl_merchant_settlement_commissions AS msc WHERE msc.plid = v_plid AND v_month = EXTRACT(MONTH FROM CAST(msc.createdate AS DATE)) AND v_year = EXTRACT(YEAR FROM CAST(msc.createdate AS DATE));
  DROP TABLE IF EXISTS tmp_comssiontemp;
  CREATE TEMP TABLE tmp_comssiontemp (ROWNUMBER INT GENERATED BY DEFAULT AS IDENTITY,
PLID INT) ON COMMIT DROP;
  INSERT INTO tmp_comssiontemp SELECT DISTINCT plid FROM tmp_statement_summary_temp;
  SELECT COUNT(1) INTO v_totalcount FROM tmp_comssiontemp;
  WHILE (v_totalcount >= v_count) LOOP
  SELECT COALESCE(plid, 0) INTO v_templid FROM tmp_comssiontemp WHERE rownumber = v_count;
  SELECT ((SUM(taxableamount) OVER () * admincharges) / 100), ((SUM(taxableamount) OVER () * fixedcharges) / 100), SUM(handlingcharges) OVER (), COALESCE(cgstrate, 0), COALESCE(sgstrate, 0), COALESCE(igstrate, 0) INTO v_admincommssion, v_fixedfee, v_handling, v_cgstrate, v_sgstrate, v_igstrate FROM tbl_merchant_commissioninvoices_details WHERE plid = v_templid AND v_month = EXTRACT(MONTH FROM CAST(createddate AS DATE)) AND v_year = EXTRACT(YEAR FROM CAST(createddate AS DATE));
  SELECT SUM(shippingcharges) OVER () INTO v_shipping FROM tbl_merchant_shippinginvoices_details WHERE plid = v_templid AND v_month = EXTRACT(MONTH FROM CAST(createddate AS DATE)) AND v_year = EXTRACT(YEAR FROM CAST(createddate AS DATE));
  IF (v_cgstrate > 0) THEN
  SELECT ((v_admincommssion + v_fixedfee + v_handling + v_shipping) * v_cgstrate) / 100 INTO v_cgst;
  END IF;
  IF (v_sgstrate > 0) THEN
  SELECT ((v_admincommssion + v_fixedfee + v_handling + v_shipping) * v_sgstrate) / 100 INTO v_sgst;
  END IF;
  IF (v_igstrate > 0) THEN
  SELECT ((v_admincommssion + v_fixedfee + v_handling + v_shipping) * v_igstrate) / 100 INTO v_igst;
  END IF;
  UPDATE tmp_statement_summary_temp SET admincomssion = COALESCE(v_admincommssion, 0), fixedfee = COALESCE(v_fixedfee, 0), handling = COALESCE(v_handling, 0), shipingfee = COALESCE(v_shipping, 0), cgst = COALESCE(v_cgst, 0), sgst = COALESCE(v_sgst, 0), igst = COALESCE(v_igst, 0) WHERE plid = v_templid;
  v_count := v_count + 1;
  END LOOP;
  RETURN QUERY SELECT * FROM tmp_statement_summary_temp;
  DROP TABLE IF EXISTS tmp_statement_summary_temp;
  DROP TABLE IF EXISTS tmp_comssiontemp;
  -- SET option (removed)
  -- COMMIT (removed)
END;
$$;


--
-- Name: usp_merchant_wallet_statement(integer, integer, character varying, character varying, character varying, character varying, character varying, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_merchant_wallet_statement(v_startrowindex integer DEFAULT 1, v_maxrows integer DEFAULT 1000, v_searchfield character varying DEFAULT ''::character varying, v_searchvalue character varying DEFAULT ''::character varying, v_fromdate character varying DEFAULT ''::character varying, v_todate character varying DEFAULT ''::character varying, v_merchantname character varying DEFAULT ''::character varying, v_totalcount integer DEFAULT 0) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_minindex INT;
  v_maxindex INT;
  v_query text;
  v_tempplid text;
  v_index INT;
  v_slice text;
  v_totalpayable DECIMAL(18,2);
  v_totalpaid DECIMAL(18,2);
BEGIN
  v_tempplid := '';
  v_index := 1;
  v_slice := '';
  v_totalpayable := 0;
  v_totalpaid := 0;
  v_minindex := (v_startrowindex - 1) * v_maxrows + 1;
  v_maxindex := v_startrowindex * v_maxrows;
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp (ROWNUMBER INT GENERATED BY DEFAULT AS IDENTITY,        
	PLID BIGINT,
	NAME VARCHAR(500),				         
    EMAILID  VARCHAR(500),						         
    PHONE VARCHAR(500),
	PAYABLE DECIMAL(18,2),
	PAID DECIMAL(18,2),
	BALANCE DECIMAL (18,2)) ON COMMIT DROP;
  v_query := 'INSERT INTO #TEMP SELECT DISTINCT PM.PLID, PM.COMPANYNAME,PL.PHONE,PL.EMAILID,0,0,0
FROM TBL_MERCHANT_SETTLEMENT_COMMISSIONS MWS 
LEFT JOIN PORTAL_LOGIN PL ON MWS.PLID=PL.PLID
LEFT JOIN PORTAL_MASTER PM ON PM.PLID=MWS.PLID 
WHERE  1=1';
  IF ((v_fromdate <> '') AND (v_todate = '')) THEN
  v_query := v_query || ' AND CONVERT(DATE, CREATEDATE, 105) BETWEEN  CONVERT(DATE, ''' || v_fromdate || ''', 105) AND  CONVERT(DATE, DBO.FUN_GETCURRENTDATE(), 105)';
  END IF;
  IF ((v_fromdate = '') AND (v_todate <> '')) THEN
  v_query := v_query || 'AND CONVERT(DATE, CREATEDATE, 105) BETWEEN  CONVERT(DATE, ''' || v_todate || ''', 105) AND  CONVERT(DATE, DBO.FUN_GETCURRENTDATE(), 105)';
  END IF;
  IF ((v_fromdate <> '') AND (v_todate <> '')) THEN
  v_query := v_query || 'AND CONVERT(DATE, CREATEDATE, 105) BETWEEN CONVERT(DATE, ''' || v_fromdate || ''', 105) AND  CONVERT(DATE, ''' || v_todate || ''', 105)';
  END IF;
  IF (v_merchantname <> '') THEN
  v_query := v_query || ' AND PM.COMPANYNAME=''' || v_merchantname || '''';
  END IF;
  IF (v_searchfield = 'EMAILID') THEN
  v_query := v_query || ' AND PL.EMAILID= ''' || v_searchvalue || ''' ';
  END IF;
  IF (v_searchfield = 'LOGINID') THEN
  v_query := v_query || ' AND PL.LOGINID= ''' || v_searchvalue || ''' ';
  END IF;
  IF (v_searchfield = 'PHONE') THEN
  v_query := v_query || ' AND PL.PHONE= ''' || v_searchvalue || ''' ';
  END IF;
  EXECUTE v_query;
  SELECT COALESCE(v_tempplid || ', ', '') || CAST(plid AS VARCHAR) INTO v_tempplid FROM (SELECT DISTINCT plid FROM tmp_temp) AS t;
  SELECT SUBSTRING(v_tempplid FROM 2 FOR LENGTH(CAST(v_tempplid AS TEXT))) INTO v_tempplid;
  v_index := 1;
  WHILE (v_index <> 0) LOOP
  SELECT POSITION(',' IN v_tempplid) INTO v_index;
  IF (v_index <> 0) THEN
  SELECT LEFT(CAST(v_tempplid AS TEXT), v_index - 1) INTO v_slice;
  ELSE
  SELECT v_tempplid INTO v_slice;
  END IF;
  v_totalpayable := 0;
  v_totalpaid := 0;
  IF (v_slice <> '') THEN
  SELECT COALESCE(SUM(netpayable), 0) INTO v_totalpayable FROM tbl_merchant_settlement_commissions WHERE plid = v_slice;
  SELECT COALESCE(SUM(withdrawamount), 0) INTO v_totalpaid FROM tbl_merchant_withdrawals WHERE plid = v_slice AND paid_status = 'PAID';
  UPDATE tmp_temp SET payable = v_totalpayable, paid = v_totalpaid, balance = (v_totalpayable - v_totalpaid) WHERE plid = v_slice;
  END IF;
  SELECT RIGHT(CAST(v_tempplid AS TEXT), LENGTH(CAST(v_tempplid AS TEXT)) - v_index) INTO v_tempplid;
  IF LENGTH(CAST(v_tempplid AS TEXT)) = 0 THEN
  EXIT;
  END IF;
  END LOOP;
  RETURN QUERY SELECT * FROM tmp_temp WHERE rownumber BETWEEN v_minindex AND v_maxindex;
  SELECT COUNT(rownumber) INTO v_totalcount FROM tmp_temp;
  DROP TABLE IF EXISTS tmp_temp;
  -- SET option (removed)
END;
$$;


--
-- Name: usp_merchant_wallet_statements(integer, integer, character varying, character varying, character varying, character varying, integer, bigint, numeric); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_merchant_wallet_statements(v_startrowindex integer DEFAULT 1, v_maxrows integer DEFAULT 100, v_searchfield character varying DEFAULT ''::character varying, v_searchvalue character varying DEFAULT ''::character varying, v_fromdate character varying DEFAULT ''::character varying, v_todate character varying DEFAULT ''::character varying, v_totalcount integer DEFAULT 0, v_plid bigint DEFAULT 0, v_totalbalnace numeric DEFAULT 0) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_minindex int;
  v_maxindex int;
  v_query text;
BEGIN
  v_minindex := (v_startrowindex - 1) * v_maxrows + 1;
  v_maxindex := v_startrowindex * v_maxrows;
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp (ROWNUMBER int GENERATED BY DEFAULT AS IDENTITY ,
	TMWSID bigint, 
	PARTICULAR varchar(500),      
	CRDRTYPE varchar(50),	
	AMOUNT DECIMAL(18,8),
	BALANCE DECIMAL(18,8),	
	ACTIVE INT,
	CREATEDATE varchar(200)) ON COMMIT DROP;
  v_query := 'insert into #temp select TMWSID,PARTICULAR,CRDRTYPE,AMOUNT,BALANCE,ACTIVE,CREATEDATE  FROM TBL_MERCHANT_WALLET_STATEMENTS WHERE 1=1 ';
  IF ((v_fromdate <> '') AND (v_todate = '')) THEN
  v_query := v_query || ' AND CONVERT(DATE, CREATEDATE, 105) BETWEEN  CONVERT(DATE, ''' || v_fromdate || ''', 105) AND  CONVERT(DATE, DBO.FUN_GETCURRENTDATE(), 105)';
  END IF;
  IF ((v_fromdate = '') AND (v_todate <> '')) THEN
  v_query := v_query || 'AND CONVERT(DATE, CREATEDATE, 105) BETWEEN  CONVERT(DATE, ''' || v_todate || ''', 105) AND  CONVERT(DATE, DBO.FUN_GETCURRENTDATE(), 105)';
  END IF;
  IF ((v_fromdate <> '') AND (v_todate <> '')) THEN
  v_query := v_query || 'AND CONVERT(DATE,CREATEDATE, 105) BETWEEN CONVERT(DATE, ''' || v_fromdate || ''', 105) AND  CONVERT(DATE, ''' || v_todate || ''', 105)';
  END IF;
  IF (v_plid > 0) THEN
  v_query := v_query || ' AND Plid= ' || CAST(v_plid AS VARCHAR(100)) || '';
  END IF;
  v_query := v_query || ' Order by Convert(Date,CREATEDATE,105) desc ';
  EXECUTE v_query;
  RETURN QUERY SELECT * FROM tmp_temp WHERE rownumber BETWEEN v_minindex AND v_maxindex;
  SELECT COALESCE(SUM(balance), 0) INTO v_totalbalnace FROM tbl_merchant_wallet_statements WHERE plid = v_plid AND status = 1;
  SELECT COUNT(rownumber) INTO v_totalcount FROM tmp_temp;
  DROP TABLE IF EXISTS tmp_temp;
  -- SET option (removed)
END;
$$;


