CREATE FUNCTION dbo.usp_merchantcat_subcat_keywordmaster(v_mode integer DEFAULT 0, v_plid bigint DEFAULT 0, v_tmcskmid bigint DEFAULT 0, v_category text DEFAULT ''::text, v_subcategory text DEFAULT ''::text, v_keyword text DEFAULT ''::text, INOUT v_strresult character varying DEFAULT ''::character varying) RETURNS character varying
    LANGUAGE plpgsql
    AS $$
BEGIN
  -- BEGIN TRAN (removed)
  IF (v_mode = 1) THEN
  IF NOT EXISTS(SELECT 1 FROM tbl_merchantcat_subcat_keywordmaster WHERE plid = v_plid) THEN
  INSERT INTO tbl_merchantcat_subcat_keywordmaster (plid, category, subcategory, keyword, addeddate, modifieddate, isactive, isdeleted) VALUES (v_plid, v_category, v_subcategory, v_keyword, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 1, 0);
  v_strresult := 'Successfully set the selected Category/Subcategory or Keyword.';
  ELSE
  UPDATE tbl_merchantcat_subcat_keywordmaster SET category = v_category, subcategory = v_subcategory, keyword = v_keyword, modifieddate = CURRENT_TIMESTAMP WHERE plid = v_plid;
  v_strresult := 'Successfully set the selected Category/Subcategory or Keyword.';
  END IF;
  END IF;
  IF (0 <> 0) THEN
  -- ROLLBACK (removed)
  v_strresult := 'Some error occured ! Please try later.';
  ELSE
  -- COMMIT (removed)
  END IF;
END;
$$;


--
-- Name: usp_merchantdashboard_orderscount(integer, integer, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_merchantdashboard_orderscount(v_regno integer DEFAULT 1, INOUT v_cancelledorders integer DEFAULT 0, INOUT v_returnorders integer DEFAULT 0) RETURNS record
    LANGUAGE plpgsql
    AS $$
BEGIN
  -- SET option (removed)
  SELECT COUNT(DISTINCT orderid) INTO v_cancelledorders FROM tbl_product_order_master WHERE plid = v_regno AND intstatus = 7;
  SELECT COUNT(DISTINCT orderid) INTO v_returnorders FROM tbl_product_order_master WHERE plid = v_regno AND intstatus = 8;
  -- SET option (removed)
END;
$$;


--
-- Name: usp_merchantdetails(integer, integer, character varying, character varying, character varying, character varying, integer, integer, numeric, integer, integer, bigint, bigint, integer, character varying, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_merchantdetails(v_startrowindex integer DEFAULT 1, v_maxrows integer DEFAULT 100, v_searchfield character varying DEFAULT ''::character varying, v_searchvalue character varying DEFAULT ''::character varying, v_fromdate character varying DEFAULT ''::character varying, v_todate character varying DEFAULT ''::character varying, v_did integer DEFAULT 11, v_totalcount integer DEFAULT 0, v_totalwallet numeric DEFAULT 0, v_balance integer DEFAULT 2, v_orderbycrdeit integer DEFAULT 0, v_minamount bigint DEFAULT 0, v_maxamount bigint DEFAULT 0, v_searchkyc integer DEFAULT 0, v_searchbusinessinfo character varying DEFAULT ''::character varying, v_searchbusinesstype integer DEFAULT 0) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_minindex INT;
  v_maxindex INT;
  v_query text;
  v_tempclid text;
  v_index INT;
  v_slice text;
  v_totalpayable DECIMAL(18,2);
BEGIN
  v_tempclid := '';
  v_index := 1;
  v_slice := '';
  v_totalpayable := 0;
  v_minindex := (v_startrowindex - 1) * v_maxrows + 1;
  v_maxindex := v_startrowindex * v_maxrows;
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp (ROWNUMBER INT GENERATED BY DEFAULT AS IDENTITY,          
    DID  BIGINT,  
 NAME VARCHAR(100),               
    EMAILID  VARCHAR(100),                 
    PHONE VARCHAR(100),  
 BusinessInfo Varchar(100),  
 KycStatusText Varchar(100)) ON COMMIT DROP;
  v_query := 'INSERT INTO #TEMP SELECT PL.DID,ISNULL(PM.COMPANYNAME,ISNULL(PL.FNAME,'''')) AS NAME,PL.EMAILID,(CASE WHEN PL.PHONE='''' THEN ''Not Updated'' END)As PHONE,  
  (CASE WHEN PL.PMID=0 THEN ''Not Updated'' Else ''Updated'' END)As BusinessInfo,PL.KycStatusText FROM TBL_DISTRIBUTOR AS D   
  INNER JOIN PORTAL_LOGIN AS  PL ON D.DID=PL.DID  
  LEFT JOIN PORTAL_MASTER PM ON PM.PLID=PL.PLID  
  WHERE PL.PLID NOT IN (SELECT PLID FROM TBL_MERCHANT_PURCHASED_PACKAGES)  ';
  IF (v_searchbusinesstype > 0) THEN
  v_query := v_query || ' AND PM.BUSINESSTYPE=' || CAST(v_searchbusinesstype AS VARCHAR(100)) || ' ';
  END IF;
  IF (v_searchkyc >= 1) THEN
  v_query := v_query || ' AND PL.KYCStatusText=(Case When ' || CAST(v_searchkyc AS VARCHAR(100)) || '=1 THEN ''Approved''   
  When ' || CAST(v_searchkyc AS VARCHAR(100)) || '=2 THEN ''Rejected'' ELSE ('''')  END)';
  END IF;
  IF (v_searchkyc = 0) THEN
  v_query := v_query || ' AND (PL.KYCStatusText=''Pending'' OR PL.KYCStatusText='''')';
  END IF;
  IF (v_searchbusinessinfo = 'Updated') THEN
  v_query := v_query || ' AND PL.PMID<>0';
  END IF;
  IF (v_searchbusinessinfo = 'Not Updated') THEN
  v_query := v_query || ' AND PL.PMID=0';
  END IF;
  IF ((v_fromdate <> '') AND (v_todate = '')) THEN
  v_query := v_query || ' AND CONVERT(VARCHAR(20), D.REGISTRATIONDATE, 106) BETWEEN  CONVERT(VARCHAR(20), ''' || v_fromdate || ''', 106) AND  CONVERT(VARCHAR(20), DBO.FUN_GETCURRENTDATE(), 106)';
  END IF;
  IF ((v_fromdate = '') AND (v_todate <> '')) THEN
  v_query := v_query || 'AND CONVERT(VARCHAR(20), D.REGISTRATIONDATE, 106) BETWEEN  CONVERT(VARCHAR(20), ''' || v_todate || ''', 106) AND  CONVERT(VARCHAR(20), DBO.FUN_GETCURRENTDATE(), 106)';
  END IF;
  IF ((v_fromdate <> '') AND (v_todate <> '')) THEN
  v_query := v_query || 'AND CONVERT(VARCHAR(20), D.REGISTRATIONDATE, 106) BETWEEN CONVERT(VARCHAR(20), ''' || v_fromdate || ''', 106) AND  CONVERT(VARCHAR(20), ''' || v_todate || ''', 106)';
  END IF;
  IF (v_did > 0) THEN
  v_query := v_query || ' AND PL.DID=' || CAST(v_did AS VARCHAR(20)) || '';
  END IF;
  IF (v_searchfield = 'LOGINID') THEN
  v_query := v_query || ' AND PL.LOGINID= ''' || v_searchvalue || ''' ';
  END IF;
  IF (v_searchfield = 'NAME') THEN
  v_query := v_query || ' AND (PL.FNAME+'' ''+PL.LNAME) = ''' || v_searchvalue || ''' ';
  END IF;
  IF (v_searchfield = 'EMAILID') THEN
  v_query := v_query || ' AND PL.EMAILID = ''' || v_searchvalue || ''' ';
  END IF;
  IF (v_searchfield = 'PHONE') THEN
  v_query := v_query || ' AND PL.PHONE= ''' || v_searchvalue || ''' ';
  END IF;
  EXECUTE v_query;
  RAISE NOTICE '%', v_query;
  RETURN QUERY SELECT * FROM tmp_temp WHERE rownumber BETWEEN v_minindex AND v_maxindex;
  SELECT COUNT(rownumber) INTO v_totalcount FROM tmp_temp;
  DROP TABLE IF EXISTS tmp_temp;
  -- SET option (removed)
END;
$$;


--
-- Name: usp_merchantdetails_active(integer, integer, character varying, character varying, character varying, character varying, integer, integer, numeric, integer, integer, bigint, bigint, integer, character varying, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_merchantdetails_active(v_startrowindex integer DEFAULT 1, v_maxrows integer DEFAULT 100, v_searchfield character varying DEFAULT ''::character varying, v_searchvalue character varying DEFAULT ''::character varying, v_fromdate character varying DEFAULT ''::character varying, v_todate character varying DEFAULT ''::character varying, v_did integer DEFAULT 0, v_totalcount integer DEFAULT 0, v_totalwallet numeric DEFAULT 0, v_balance integer DEFAULT 2, v_orderbycrdeit integer DEFAULT 0, v_minamount bigint DEFAULT 0, v_maxamount bigint DEFAULT 0, v_searchkyc integer DEFAULT 0, v_searchbusinessinfo character varying DEFAULT ''::character varying, v_searchbusinesstype integer DEFAULT 0) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_minindex INT;
  v_maxindex INT;
  v_query text;
  v_tempclid text;
  v_index INT;
  v_slice text;
  v_totalpayable DECIMAL(18,2);
BEGIN
  v_tempclid := '';
  v_index := 1;
  v_slice := '';
  v_totalpayable := 0;
  v_minindex := (v_startrowindex - 1) * v_maxrows + 1;
  v_maxindex := v_startrowindex * v_maxrows;
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp (ROWNUMBER INT GENERATED BY DEFAULT AS IDENTITY,          
    DID  BIGINT,  
 NAME VARCHAR(500),               
    EMAILID  VARCHAR(500),                 
    PHONE VARCHAR(500),  
 PackagesName VARCHAR(500),  
 Amount decimal(18,2),     
 BusinessInfo Varchar(100),  
 KycStatusText Varchar(100)) ON COMMIT DROP;
  v_query := 'INSERT INTO #TEMP SELECT PL.DID,ISNULL(PM.COMPANYNAME,ISNULL(PL.FNAME,'''')) AS NAME,PL.EMAILID,(CASE WHEN PL.PHONE='''' THEN ''Not Updated'' END)As PHONE,MP.NAME,MP.AMOUNT,  
  (CASE WHEN PL.PMID=0 THEN ''Updated'' Else ''Not Updated'' END)As BusinessInfo,PL.KycStatusText FROM TBL_DISTRIBUTOR AS D   
    INNER JOIN PORTAL_LOGIN AS  PL ON D.DID=PL.DID  
    INNER JOIN TBL_MERCHANT_PURCHASED_PACKAGES AS MPP ON MPP.PLID=PL.PLID  
    INNER JOIN TBL_MERCHANTPACKEAGES AS MP ON MP.MPID=MPP.PMID  
    LEFT JOIN PORTAL_MASTER PM ON PM.PLID=PL.PLID  
   WHERE 1=1 ';
  IF (v_searchbusinesstype > 0) THEN
  v_query := v_query || ' AND PM.BUSINESSTYPE=' || CAST(v_searchbusinesstype AS VARCHAR(100)) || ' ';
  END IF;
  IF (v_searchkyc >= 1) THEN
  v_query := v_query || ' AND PL.KYCStatusText=(Case When ' || CAST(v_searchkyc AS VARCHAR(100)) || '=1 THEN ''Approved''   
  When ' || CAST(v_searchkyc AS VARCHAR(100)) || '=2 THEN ''Rejected'' ELSE ('''')  END)';
  END IF;
  IF (v_searchkyc = 0) THEN
  v_query := v_query || ' AND (PL.KYCStatusText=''Pending'' OR PL.KYCStatusText='''')';
  END IF;
  IF (v_searchbusinessinfo = 'Updated') THEN
  v_query := v_query || ' AND PL.PMID<>0';
  END IF;
  IF (v_searchbusinessinfo = 'Not Updated') THEN
  v_query := v_query || ' AND PL.PMID=0';
  END IF;
  IF ((v_fromdate <> '') AND (v_todate = '')) THEN
  v_query := v_query || ' AND CONVERT(VARCHAR(20), D.REGISTRATIONDATE, 106) BETWEEN  CONVERT(VARCHAR(20), ''' || v_fromdate || ''', 106) AND  CONVERT(VARCHAR(20), DBO.FUN_GETCURRENTDATE(), 106)';
  END IF;
  IF ((v_fromdate = '') AND (v_todate <> '')) THEN
  v_query := v_query || 'AND CONVERT(VARCHAR(20), D.REGISTRATIONDATE, 106) BETWEEN  CONVERT(VARCHAR(20), ''' || v_todate || ''', 106) AND  CONVERT(VARCHAR(20), DBO.FUN_GETCURRENTDATE(), 106)';
  END IF;
  IF ((v_fromdate <> '') AND (v_todate <> '')) THEN
  v_query := v_query || 'AND CONVERT(VARCHAR(20), D.REGISTRATIONDATE, 106) BETWEEN CONVERT(VARCHAR(20), ''' || v_fromdate || ''', 106) AND  CONVERT(VARCHAR(20), ''' || v_todate || ''', 106)';
  END IF;
  IF (v_did > 0) THEN
  v_query := v_query || ' AND PL.DID=' || CAST(v_did AS VARCHAR(20)) || '';
  END IF;
  IF (v_searchfield = 'LOGINID') THEN
  v_query := v_query || ' AND PL.LOGINID= ''' || v_searchvalue || ''' ';
  END IF;
  IF (v_searchfield = 'NAME') THEN
  v_query := v_query || ' AND (PL.FNAME+'' ''+PL.LNAME) = ''' || v_searchvalue || ''' ';
  END IF;
  IF (v_searchfield = 'EMAILID') THEN
  v_query := v_query || ' AND PL.EMAILID = ''' || v_searchvalue || ''' ';
  END IF;
  IF (v_searchfield = 'PHONE') THEN
  v_query := v_query || ' AND PL.PHONE= ''' || v_searchvalue || ''' ';
  END IF;
  EXECUTE v_query;
  RAISE NOTICE '%', v_query;
  RETURN QUERY SELECT * FROM tmp_temp WHERE rownumber BETWEEN v_minindex AND v_maxindex;
  SELECT COUNT(rownumber) INTO v_totalcount FROM tmp_temp;
  DROP TABLE IF EXISTS tmp_temp;
  -- SET option (removed)
END;
$$;


--
-- Name: usp_merchantlogindetails(integer, integer, character varying, boolean, character varying, character varying, character varying, character varying, integer, integer, character varying, character varying, text, character varying, character varying, character varying, integer, integer, integer, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_merchantlogindetails(v_startrowindex integer DEFAULT 1, v_maxrows integer DEFAULT 5, v_orderbyfield character varying DEFAULT 'ID'::character varying, v_asc boolean DEFAULT true, v_searchfield character varying DEFAULT '0'::character varying, v_searchvalue character varying DEFAULT ''::character varying, v_fromdate character varying DEFAULT ''::character varying, v_todate character varying DEFAULT ''::character varying, v_mode integer DEFAULT 0, v_recordcount integer DEFAULT 0, v_cid character varying DEFAULT ''::character varying, v_accnttype character varying DEFAULT ''::character varying, v_usertype text DEFAULT '0'::text, v_eggagetypes character varying DEFAULT ''::character varying, v_orderby character varying DEFAULT ''::character varying, v_mobile character varying DEFAULT ''::character varying, v_isdownload integer DEFAULT 0, v_userid integer DEFAULT 0, v_qualification integer DEFAULT 0, v_gender integer DEFAULT 0) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_sqlquery text;
  v_minindex INT;
  v_maxindex INT;
  v_newusername varchar(200);
BEGIN
  -- SET option (removed)
  DROP TABLE IF EXISTS tmp_temp66;
  CREATE TEMP TABLE tmp_temp66 (ROWNUMBER BIGINT,
REFRAL_ID VARCHAR(150),
LOGINID VARCHAR(150),
USERNAME VARCHAR(150),
NAME VARCHAR(150),
PHONE VARCHAR(150),
PLID BIGINT,
DOC VARCHAR(200),
ACCOUNTTYPE VARCHAR(50),
COUNTRY VARCHAR(100),
JOINEDVIA text,
STATUS VARCHAR(100),
IPADDRESS VARCHAR(100),
ENGAGEDIN VARCHAR(50),
ENGTOOLTIP VARCHAR(100),
FULLNAME VARCHAR(500),
Emailid varchar(100),
Reference_Username varchar(100),
DID INT) ON COMMIT DROP;
  v_sqlquery := '';
  v_minindex := (v_startrowindex - 1) * v_maxrows + 1;
  v_maxindex := v_startrowindex * v_maxrows;
  v_sqlquery := 'INSERT INTO #TEMP66 SELECT ROW_NUMBER() OVER (ORDER BY PL1.DOC DESC) AS ROWNUMBER,ISNULL(PL2.USERNAME,''-'') AS REFRAL_ID,PL1.LOGINID,ISNULL(PL1.USERNAME,''-'') AS USERNAME,ISNULL(TD.NAME,'''') AS NAME,PL1.PHONE,
   PL1.CLID,  FORMAT(PL1.DOC,''dd-MMM-yyyy hh:mm:ss tt'')  AS DOC, CASE ISNULL(PL1.QPAYREGNO,0) WHEN 0 THEN ''QLOOK'' ELSE ''QPAY'' END AS ACCOUNTTYPE,
   (CASE WHEN C.COUNTRYNAME=''UNITED STATES'' THEN ''US'' WHEN C.COUNTRYNAME=''UNITED KINGDOM'' THEN ''UK'' ELSE  C.COUNTRYNAME END  ) AS COUNTRYNAME,
    (Case When PL1.IPADDRESS=''By Admin'' Then ''Admin'' When isnull(PL1.SpounserType,0)=0 Then ''Direct'' When PL1.SpounserType=2 Then ''Member Referrals'' When PL1.SpounserType=1 Then ''Customer Referrals'' END) As JoinedVia,
	--(Case When PL1.IPADDRESS=''By Admin'' Then ''Admin'' When PL1.INTRO_REFID=0 Then ''Direct'' When PL1.INTRO_REFID>0 Then ''Customer Referrals'' END) As JoinedVia,
   (CASE PL1.ACTIVE WHEN 1 THEN ''Active'' WHEN 0 THEN ''Deactive'' END)AS STATUS,ISNULL(PL1.IPADDRESS,''-'') AS IPADDRESS,
   CASE WHEN (ISNULL(PL1.PMID,0)=0 AND ISNULL(PL1.INTRO_PLID,0)=0 AND ISNULL(SMD.SMDID,0)=0) THEN ''None'' 
   WHEN (ISNULL(PL1.PMID,0)<>0 AND ISNULL(PL1.INTRO_PLID,0)=0 AND ISNULL(SMD.SMDID,0)=0) THEN ''BL'' 
   WHEN (ISNULL(PL1.PMID,0)=0 AND ISNULL(PL1.INTRO_PLID,0)<>0 AND ISNULL(SMD.SMDID,0)=0) THEN ''RP'' 
   WHEN (ISNULL(PL1.PMID,0)=0 AND ISNULL(PL1.INTRO_PLID,0)=0 AND ISNULL(SMD.SMDID,0)<>0) THEN ''PPC''
   WHEN (ISNULL(PL1.PMID,0)<>0 AND ISNULL(PL1.INTRO_PLID,0)<>0 AND ISNULL(SMD.SMDID,0)=0) THEN ''BL, RP''
   WHEN (ISNULL(PL1.PMID,0)<>0 AND ISNULL(PL1.INTRO_PLID,0)=0 AND ISNULL(SMD.SMDID,0)<>0) THEN ''BL, PPC''
   WHEN (ISNULL(PL1.PMID,0)=0 AND ISNULL(PL1.INTRO_PLID,0)<>0 AND ISNULL(SMD.SMDID,0)<>0) THEN ''RP, PPC''
   WHEN (ISNULL(PL1.PMID,0)<>0 AND ISNULL(PL1.INTRO_PLID,0)<>0 AND ISNULL(SMD.SMDID,0)<>0) THEN ''BL, RP, PPC'' END AS ENGAGEDIN,
   CASE WHEN (ISNULL(PL1.PMID,0)=0 AND ISNULL(PL1.INTRO_PLID,0)=0 AND ISNULL(SMD.SMDID,0)=0) THEN ''None'' 
   WHEN (ISNULL(PL1.PMID,0)<>0 AND ISNULL(PL1.INTRO_PLID,0)=0 AND ISNULL(SMD.SMDID,0)=0) THEN ''Bussiness Listing'' 
   WHEN (ISNULL(PL1.PMID,0)=0 AND ISNULL(PL1.INTRO_PLID,0)<>0 AND ISNULL(SMD.SMDID,0)=0) THEN ''Referral Program'' 
   WHEN (ISNULL(PL1.PMID,0)=0 AND ISNULL(PL1.INTRO_PLID,0)=0 AND ISNULL(SMD.SMDID,0)<>0) THEN ''Pay Per Click''
   WHEN (ISNULL(PL1.PMID,0)<>0 AND ISNULL(PL1.INTRO_PLID,0)<>0 AND ISNULL(SMD.SMDID,0)=0) THEN ''Bussiness Listing, Referral Program''
   WHEN (ISNULL(PL1.PMID,0)<>0 AND ISNULL(PL1.INTRO_PLID,0)=0 AND ISNULL(SMD.SMDID,0)<>0) THEN ''Bussiness Listing, Pay Per Click''
  WHEN (ISNULL(PL1.PMID,0)=0 AND ISNULL(PL1.INTRO_PLID,0)<>0 AND ISNULL(SMD.SMDID,0)<>0) THEN ''Referral Program, Pay Per Click''
   WHEN (ISNULL(PL1.PMID,0)<>0 AND ISNULL(PL1.INTRO_PLID,'''')<>0 AND ISNULL(SMD.SMDID,0)<>0) THEN ''Bussiness Listing, Referral Program, Pay Per Click'' end as engtooltip,
   ISNULL(PL1.FNAME,'''') +'' ''+ISNULL(PL1.LNAME,'''') AS NAME,PL1.EMAILID,ISNULL(PL1.Reference_Username,'''') AS Reference_Username,
   ISNULL(PL1.DID,0) AS DID 
   FROM TBL_CUSTOMERLOGIN PL1 LEFT JOIN PORTAL_MASTER PM ON PM.PMID=ISNULL(PL1.PMID,0)
   LEFT JOIN TBL_DISTRIBUTOR TD ON TD.DID=PL1.DID
   LEFT JOIN SPONSOR_MASTER_DETAIL SMD ON SMD.PLID=PL1.CLID
   LEFT JOIN TBL_CUSTOMERLOGIN PL2 ON PL2.CLID=PL1.INTRO_REFID JOIN
   COUNTRY C ON C.CID=PL1.CID LEFT JOIN MEMBER_MASTER MM ON MM.PLID=PL1.CLID  WHERE PL1.ACTIVE>=0 ';
  IF (v_fromdate = '' OR v_todate = '') THEN
  IF (v_fromdate <> '') THEN
  v_sqlquery := v_sqlquery || ' AND CONVERT(DATE, PL1.DOC,103) >= REPLACE(CONVERT(DATE,''' || v_fromdate || ''',103),''/'',''-'') ';
  END IF;
  IF (v_todate <> '') THEN
  v_sqlquery := v_sqlquery || ' AND CONVERT(DATE, PL1.DOC,103)  <=REPLACE(CONVERT(DATE,''' || v_todate || ''',103),''/'',''-'') ';
  END IF;
  END IF;
  IF (v_fromdate <> '' AND v_todate <> '') THEN
  v_sqlquery := v_sqlquery || '  AND  CONVERT(DATE, PL1.DOC,103)  BETWEEN  REPLACE(CONVERT(DATE,''' || v_fromdate || ''',103),''/'',''-'')  AND REPLACE(CONVERT(DATE,''' || v_todate || ''',103),''/'',''-'')';
  END IF;
  IF (v_mobile <> '') THEN
  v_sqlquery := v_sqlquery || (' AND PL1.PHONE =''' || v_mobile || ''' ');
  END IF;
  IF (v_searchfield = 'Emailid') THEN
  v_sqlquery := v_sqlquery || ' AND PL1.Emailid LIKE ''%' || v_searchvalue || '%'' ';
  END IF;
  IF (v_searchfield = 'FULLNAME') THEN
  v_sqlquery := v_sqlquery || ' AND (PL1.FNAME+PL1.LNAME) LIKE ''%' || v_searchvalue || '%'' ';
  END IF;
  IF (v_searchfield = 'PHONE') THEN
  v_sqlquery := v_sqlquery || ' AND PL1.PHONE LIKE ''%' || v_searchvalue || '%'' ';
  END IF;
  IF (v_searchfield = 'SourceID') THEN
  v_sqlquery := v_sqlquery || ' AND PL1.Reference_Username LIKE ''%' || v_searchvalue || '%'' ';
  END IF;
  IF (v_searchfield = 'REFERAL') THEN
  v_sqlquery := v_sqlquery || ' AND PL2.LOGINID LIKE ''%' || v_searchvalue || '%'' ';
  END IF;
  IF (v_searchfield = 'USERNAME') THEN
  IF (EXISTS(SELECT 1 FROM portal_login WHERE username = v_searchvalue)) THEN
  v_sqlquery := v_sqlquery || (' AND PL1.USERNAME LIKE ''%' || v_searchvalue || '%''');
  ELSE
  IF (EXISTS(SELECT 1 FROM portal_login_history WHERE username = v_searchvalue)) THEN
  v_newusername := '';
  SELECT (SELECT username FROM portal_login WHERE plid IN (SELECT plid FROM portal_login_history WHERE username = v_searchvalue)) INTO v_newusername;
  v_sqlquery := v_sqlquery || (' AND PL1.USERNAME LIKE ''%' || v_newusername || '%''');
  ELSE
  v_sqlquery := v_sqlquery || ' AND PL1.USERNAME LIKE ''%' || v_searchvalue || '%'' ';
  END IF;
  END IF;
  END IF;
  IF (v_cid <> '') THEN
  v_sqlquery := v_sqlquery || (' AND C.CID =' || v_cid || ' ');
  END IF;
  IF (v_qualification <> '0') THEN
  v_sqlquery := v_sqlquery || (' AND PL1.HIGHESTQUALIFICATION =' || CAST(v_qualification AS VARCHAR(30)) || ' ');
  END IF;
  IF (v_gender <> '0') THEN
  v_sqlquery := v_sqlquery || (' AND PL1.GENDER =' || CAST(v_gender AS VARCHAR(30)) || ' ');
  END IF;
  IF (v_usertype <> '') THEN
  IF (v_usertype = 'ByAdmin') THEN
  v_sqlquery := v_sqlquery || (' AND PL1.IPADDRESS=''By Admin''');
  END IF;
  IF (v_usertype = 'Direct') THEN
  v_sqlquery := v_sqlquery || (' AND (PL1.INTRO_REFID=0 OR PL1.INTRO_REFID=1)');
  END IF;
  IF (v_usertype = 'CustomerReferrals') THEN
  v_sqlquery := v_sqlquery || (' AND PL1.INTRO_REFID>1');
  END IF;
  IF (v_usertype = 'ActiveCustomerReferrals') THEN
  v_sqlquery := v_sqlquery || (' AND PL1.INTRO_REFID IN(Select PLID From Tbl_AllSubscriptionMaster Where ISNULL(IsApproved,0)=1 AND ''~''+AllPackageType+''~'' Like ''%~1~%'')');
  END IF;
  END IF;
  IF (v_eggagetypes <> '') THEN
  IF (v_eggagetypes = 'BL') THEN
  v_sqlquery := v_sqlquery || (' AND (ISNULL(PL1.PMID,0)<>0 AND ISNULL(PL1.INTRO_PLID,0)=0 AND ISNULL(SMD.SMDID,0)=0) ');
  END IF;
  IF (v_eggagetypes = 'RP') THEN
  v_sqlquery := v_sqlquery || (' AND (ISNULL(PL1.PMID,0)=0 AND ISNULL(PL1.INTRO_PLID,0)<>0 AND ISNULL(SMD.SMDID,0)=0) ');
  END IF;
  IF (v_eggagetypes = 'PPC') THEN
  v_sqlquery := v_sqlquery || (' AND (ISNULL(PL1.PMID,0)=0 AND ISNULL(PL1.INTRO_PLID,0)=0 AND ISNULL(SMD.SMDID,0)<>0) ');
  END IF;
  IF (v_eggagetypes = 'BL, RP') THEN
  v_sqlquery := v_sqlquery || (' AND (ISNULL(PL1.PMID,0)<>0 AND ISNULL(PL1.INTRO_PLID,0)<>0 AND ISNULL(SMD.SMDID,0)=0) ');
  END IF;
  IF (v_eggagetypes = 'BL, PPC') THEN
  v_sqlquery := v_sqlquery || (' AND (ISNULL(PL1.PMID,0)<>0 AND ISNULL(PL1.INTRO_PLID,0)=0 AND ISNULL(SMD.SMDID,0)<>0) ');
  END IF;
  IF (v_eggagetypes = 'RP, PPC') THEN
  v_sqlquery := v_sqlquery || (' AND (ISNULL(PL1.PMID,0)=0 AND ISNULL(PL1.INTRO_PLID,0)<>0 AND ISNULL(SMD.SMDID,0)<>0) ');
  END IF;
  IF (v_eggagetypes = 'BL, RP, PPC') THEN
  v_sqlquery := v_sqlquery || (' AND (ISNULL(PL1.PMID,0)<>0 AND ISNULL(PL1.INTRO_PLID,0)<>0 AND ISNULL(SMD.SMDID,0)<>0) ');
  END IF;
  END IF;
  IF (v_orderby = 'DESC') THEN
  v_sqlquery := v_sqlquery || ('  ORDER BY PL1.DOC ' || v_orderby || ' ');
  END IF;
  IF (v_orderby = 'ASC') THEN
  v_sqlquery := v_sqlquery || ('  ORDER BY PL1.DOC  ');
  END IF;
  EXECUTE v_sqlquery;
  RETURN QUERY SELECT * FROM tmp_temp66 WHERE rownumber BETWEEN v_minindex AND v_maxindex;
  SELECT COUNT(rownumber) INTO v_recordcount FROM tmp_temp66;
  SELECT COUNT(1) INTO v_recordcount FROM tmp_temp66;
  IF (v_isdownload = 0) THEN
  RETURN QUERY SELECT * FROM tmp_temp66 WHERE rownumber BETWEEN v_startrowindex AND v_maxrows;
  ELSE
  RETURN QUERY SELECT rownumber AS "s.no.", TO_DATE(doc, 'DD TMMon YYYY') AS "reg.date", username AS "user name", loginid AS "email id", fullname AS name, ipaddress AS ip, joinedvia AS "joined via", status AS status, engagedin AS "engagged in" FROM tmp_temp66;
  INSERT INTO tbl_exceltrackingreport (report_name, file_name, type, download_by, download_date) VALUES ('All Member', 'AllMember-List.xls', 1, v_userid, CURRENT_TIMESTAMP);
  END IF;
  DROP TABLE IF EXISTS tmp_temp66;
  -- SET option (removed)
END;
$$;


--
-- Name: usp_merchantpackagepurchase_onlinerequests(bigint, integer, character varying, character varying, character varying, character varying, character varying, character varying, character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_merchantpackagepurchase_onlinerequests(v_plid bigint DEFAULT 0, v_pmid integer DEFAULT 0, v_source character varying DEFAULT ''::character varying, v_successurl character varying DEFAULT ''::character varying, v_failureurl character varying DEFAULT ''::character varying, v_inprocessurl character varying DEFAULT ''::character varying, v_cancelledurl character varying DEFAULT ''::character varying, v_stroutput character varying DEFAULT ''::character varying, v_transactionid character varying DEFAULT ''::character varying) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_amount DECIMAL(18,2);
  v_gstpercentage DECIMAL(18,2);
  v_gstamount DECIMAL(18,2);
  v_transid VARCHAR(50);
BEGIN
  BEGIN
  -- BEGIN TRAN (removed)
  v_amount := 0;
  v_gstpercentage := 0;
  v_gstamount := 0;
  IF (v_plid <> 0) THEN
  IF EXISTS(SELECT 1 FROM portal_login WHERE plid = v_plid) THEN
  v_transid := '';
  v_transid := CAST(CAST(GEN_RANDOM_UUID() AS BYTEA(5)) AS BIGINT) % 1000000000 + 1000000000;
  RETURN QUERY SELECT v_transid;
  IF EXISTS(SELECT 1 FROM dbo.tbl_merchantpackeages WHERE mpid = v_pmid AND status = 1) THEN
  SELECT COALESCE(limits, 0) INTO v_gstpercentage FROM settings WHERE caption = 'GST Percentage' AND active = 1;
  SELECT COALESCE(amount, 0) INTO v_amount FROM dbo.tbl_merchantpackeages WHERE mpid = v_pmid AND status = 1;
  IF (v_amount > 0) THEN
  v_gstamount := (v_amount * v_gstpercentage) / 100;
  v_amount := v_amount + v_gstamount;
  END IF;
  END IF;
  IF (v_amount = 0) THEN
  v_stroutput := 'Amount should be greater than zero.';
  -- COMMIT (removed)
  RETURN;
  END IF;
  IF (v_amount < 0) THEN
  v_stroutput := 'Amount should be positive.';
  -- COMMIT (removed)
  RETURN;
  END IF;
  IF EXISTS(SELECT 1 FROM dbo.tbl_merchantpackagepurchase_onlinerequests WHERE transactionid = v_transid) THEN
  v_stroutput := 'Error';
  -- ROLLBACK (removed)
  RETURN;
  ELSE
  INSERT INTO dbo.tbl_merchantpackagepurchase_onlinerequests (plid, mpid, amount, paymentmode, transactionid, source, successurl, failureurl, inprocessurl, cancelledurl, purchasedate, status, createdate, active) VALUES (v_plid, v_pmid, v_amount, 'ONLINE', v_transid, v_source, v_successurl, v_failureurl, v_inprocessurl, v_cancelledurl, dbo.FUN_GETCURRENTDATE(), 0, dbo.FUN_GETCURRENTDATE(), 1);
  v_stroutput := 'Success';
  v_transactionid := v_transid;
  -- COMMIT (removed)
  END IF;
  ELSE
  v_stroutput := 'Invalid Merchant.';
  -- COMMIT (removed)
  RETURN;
  END IF;
  END IF;
  EXCEPTION WHEN OTHERS THEN
  IF (0 <> 0) THEN
  v_stroutput := 'Error';
  -- ROLLBACK (removed)
  RETURN;
  END IF;
  END;
END;
$$;


--
-- Name: usp_merchantpanelacceptance(character varying, bigint, character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_merchantpanelacceptance(v_sponser character varying DEFAULT ''::character varying, v_plid bigint DEFAULT 5, INOUT v_result character varying DEFAULT ''::character varying) RETURNS character varying
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_loginid VARCHAR(100);
  v_password VARCHAR(100);
  v_currencysymbol VARCHAR(50);
  v_spounsertype int;
  v_cid INT;
  v_plidref VARCHAR(100);
  v_username VARCHAR(100);
  v_ipaddress VARCHAR(100);
  v_intromemid text;
  v_placementmemid VARCHAR(50);
  v_placementregnoside smallint;
  v_fname VARCHAR(100);
  v_mname VARCHAR(100);
  v_lname VARCHAR(100);
  v_gender smallint;
  v_dob VARCHAR(50);
  v_email VARCHAR(100);
  v_mobile VARCHAR(20);
  v_sid INT;
  v_statename VARCHAR(250);
  v_ctid INT;
  v_cityname VARCHAR(200);
  v_address text;
  v_pincode VARCHAR(20);
  v_panno VARCHAR(100);
  v_trpassword VARCHAR(100);
  v_ipadd VARCHAR(100);
  v_epinnumber VARCHAR(100);
  v_nomineename VARCHAR(100);
  v_nomineerelation VARCHAR(100);
  v_sessionloginid VARCHAR(50);
  v_kitid Int;
  v_strresult VARCHAR(200);
  v_application_formno text;
  v_referalcode varchar(10);
  v_introrefid Int;
  v_sponsorids text;
  v_placementids text;
  v_side Int;
  v_title text;
  v_desigantion text;
  v_imagename text;
BEGIN
  -- BEGIN TRAN (removed)
  v_result := 'success';
  IF EXISTS(SELECT 1 FROM member_master WHERE plid = v_plid AND COALESCE(ismerchantpanelaccepted, 0) = 1) THEN
  v_result := 'Your account is already linked to the customer panel !';
  -- COMMIT (removed)
  RETURN;
  END IF;
  IF EXISTS(SELECT 1 FROM member_master WHERE plid = v_plid) THEN
  UPDATE member_master SET ismerchantpanelaccepted = 1, merchantpanelaccepteddate = dbo.FUN_GETCURRENTDATE() WHERE plid = v_plid;
  UPDATE portal_login SET ismerchantpanelaccepted = 1, merchantpanelaccepteddate = dbo.FUN_GETCURRENTDATE() WHERE plid = v_plid;
  ELSE
  v_spounsertype := 0;
  v_intromemid := '';
  v_placementmemid := '';
  v_placementregnoside := 0;
  v_fname := '';
  v_mname := '';
  v_lname := '';
  v_gender := 0;
  v_dob := '';
  v_email := '';
  v_mobile := '';
  v_sid := 0;
  v_statename := '';
  v_ctid := 0;
  v_cityname := '';
  v_address := '';
  v_pincode := '';
  v_panno := '';
  v_trpassword := '';
  v_ipadd := '';
  v_epinnumber := '';
  v_nomineename := '';
  v_nomineerelation := '';
  v_sessionloginid := '';
  v_kitid := 1;
  v_strresult := '';
  v_application_formno := '';
  v_referalcode := '';
  v_introrefid := 0;
  v_sponsorids := '';
  v_placementids := '';
  v_side := 0;
  v_title := '';
  v_desigantion := '';
  v_imagename := '';
  SELECT loginid, password, password, intro_refid, username, currencysymbol, cid, ipaddress, COALESCE(sp_firstname, ''), COALESCE(sp_lastname, ''), phone, loginid, COALESCE(refral_id, ''), sponserid, placementid, side, title, designation, imagename, COALESCE(spounsertype, 0) INTO v_loginid, v_password, v_trpassword, v_plidref, v_username, v_currencysymbol, v_cid, v_ipaddress, v_fname, v_lname, v_mobile, v_email, v_referalcode, v_sponsorids, v_placementids, v_side, v_title, v_desigantion, v_imagename, v_spounsertype FROM portal_login_temp WHERE phone = (SELECT phone FROM portal_login WHERE plid = v_plid) LIMIT 1;
  SELECT v_strresult INTO v_strresult FROM dbo.usp_insert_member_master(v_maxplid => v_plid, v_intromemid => v_intromemid, v_placementmemid => v_placementmemid, v_placementregnoside => v_placementregnoside, v_username => v_username, v_fname => v_fname, v_mname => v_mname, v_lname => v_lname, v_gender => v_gender, v_dob => v_dob, v_email => v_email, v_mobile => v_mobile, v_sid => v_sid, v_statename => v_statename, v_ctid => v_ctid, v_cityname => v_cityname, v_cid => v_cid, v_address => v_address, v_pincode => v_pincode, v_panno => v_panno, v_password => v_password, v_trpassword => v_trpassword, v_ipadd => v_ipadd, v_epinnumber => v_epinnumber, v_nomineename => v_nomineename, v_nomineerelation => v_nomineerelation, v_sessionloginid => v_sessionloginid, v_kitid => v_kitid, v_strresult => v_strresult, v_application_formno => v_application_formno, v_loginid => v_loginid);
  UPDATE member_master SET ismerchantpanelaccepted = 1, merchantpanelaccepteddate = dbo.FUN_GETCURRENTDATE() WHERE plid = v_plid;
  UPDATE portal_login SET ismerchantpanelaccepted = 1, merchantpanelaccepteddate = dbo.FUN_GETCURRENTDATE() WHERE plid = v_plid;
  END IF;
  IF (0 <> 0) THEN
  -- ROLLBACK (removed)
  v_result := 'Some error occurred, Please try again !';
  RETURN;
  END IF;
  -- COMMIT (removed)
END;
$$;


