--
-- Name: usp_merchantsettalment_report(character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_merchantsettalment_report(INOUT v_strresult character varying DEFAULT ''::character varying) RETURNS character varying
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_currentdate timestamp;
  v_totalcount INT;
  v_count INT;
  v_tempoederid VARCHAR(100);
  v_tempplid VARCHAR(100);
  v_index INT;
  v_slice text;
  v_stroutput VARCHAR(250);
  v_duedate VARCHAR(100);
  v_invoiceamount DECIMAL(18,2);
  v_tempinvoicetemp VARCHAR(100);
  v_tmorid INT;
  v_orderno text;
  v_strresult_reseller_comssion varchar(100);
  v_commissionvalue DECIMAL(18,2);
  v_grossamount DECIMAL(18,2);
  v_taxdeductionamount DECIMAL(18,2);
  v_netpayable DECIMAL(18,2);
  v_totalcommsionwithgst DECIMAL(18,2);
  v_commsioncount INT;
  v_co_count INT;
  v_cominvoiceorderid VARCHAR(100);
  v_tempplid1 INT;
  v_invoiceno VARCHAR(100);
  v_invoicedate VARCHAR(100);
  v_twcount INT;
  v_totalwcount INT;
  v_plidwallet VARCHAR(100);
  v_amount DECIMAL(18,2);
  v_balance Decimal(18,2);
  v_tmscid INT;
  v_orderid VARCHAR(100);
BEGIN
  -- BEGIN TRAN (removed)
  v_currentdate := '';
  v_totalcount := 0;
  v_count := 1;
  v_tempoederid := '';
  v_index := 1;
  v_slice := '';
  v_stroutput := '';
  v_duedate := '';
  v_invoiceamount := 0;
  v_tempinvoicetemp := '';
  v_tmorid := 0;
  SELECT dbo.FUN_GETCURRENTDATE() INTO v_currentdate;
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp (ROWNUMBER INT GENERATED BY DEFAULT AS IDENTITY,  
PLID BIGINT,  
ORDERID VARCHAR(100)) ON COMMIT DROP;
  DROP TABLE IF EXISTS tmp_tbl_merchant_ordertransaction;
  CREATE TEMP TABLE tmp_tbl_merchant_ordertransaction ON COMMIT DROP AS SELECT ROW_NUMBER() OVER (ORDER BY tmorid NULLS FIRST) AS rownumber, * FROM tbl_merchant_ordertransactions WHERE TO_DATE(duedate, 'DD/MM/YYYY') < TO_DATE(v_currentdate, 'DD/MM/YYYY') AND active = 1;
  SELECT COUNT(1) INTO v_totalcount FROM tmp_tbl_merchant_ordertransaction;
  WHILE (v_totalcount >= v_count) LOOP
  SELECT COALESCE(orderid, ''), duedate, invoiceamount, invoiceno, tmorid INTO v_tempoederid, v_duedate, v_invoiceamount, v_tempinvoicetemp, v_tmorid FROM tmp_tbl_merchant_ordertransaction WHERE rownumber = v_count;
  SELECT COALESCE(v_tempplid || ',', '') || CAST(plid AS VARCHAR) INTO v_tempplid FROM tbl_product_order_master WHERE orderid = v_tempoederid;
  v_index := 1;
  WHILE (v_index <> 0) LOOP
  SELECT POSITION(',' IN v_tempplid) INTO v_index;
  IF (v_index <> 0) THEN
  SELECT LEFT(CAST(v_tempplid AS TEXT), v_index - 1) INTO v_slice;
  ELSE
  SELECT v_tempplid INTO v_slice;
  END IF;
  IF (v_slice <> '') THEN
  SELECT v_stroutput INTO v_stroutput FROM dbo.usp_generatemerchant_invoices(v_plid => v_slice, v_orderid => v_tempoederid, v_stroutput => v_stroutput);
  END IF;
  SELECT RIGHT(CAST(v_tempplid AS TEXT), LENGTH(CAST(v_tempplid AS TEXT)) - v_index) INTO v_tempplid;
  IF LENGTH(CAST(v_tempplid AS TEXT)) = 0 THEN
  EXIT;
  END IF;
  END LOOP;
  v_orderno := '';
  v_strresult_reseller_comssion := '';
  SELECT COALESCE(v_orderno || ',', '') || CAST(orderno AS VARCHAR) INTO v_orderno FROM tbl_product_order_master WHERE invoiceno = v_tempinvoicetemp;
  v_index := 1;
  v_slice := '';
  WHILE (v_index <> 0) LOOP
  SELECT POSITION(',' IN v_orderno) INTO v_index;
  IF (v_index <> 0) THEN
  SELECT LEFT(CAST(v_orderno AS TEXT), v_index - 1) INTO v_slice;
  ELSE
  SELECT v_orderno INTO v_slice;
  END IF;
  IF (v_slice <> '') THEN
  SELECT v_strresult INTO v_strresult_reseller_comssion FROM dbo.usp_manageresellercommission(v_orderno => v_slice, v_issettlementprocess => 1, v_strresult => v_strresult_reseller_comssion);
  END IF;
  SELECT RIGHT(CAST(v_orderno AS TEXT), LENGTH(CAST(v_orderno AS TEXT)) - v_index) INTO v_orderno;
  IF LENGTH(CAST(v_orderno AS TEXT)) = 0 THEN
  EXIT;
  END IF;
  END LOOP;
  UPDATE tbl_merchant_ordertransactions SET active = 0 WHERE orderid = v_tempoederid AND invoiceno = v_tempinvoicetemp;
  v_commissionvalue := 0;
  v_grossamount := 0;
  v_taxdeductionamount := 0;
  v_netpayable := 0;
  v_totalcommsionwithgst := 0;
  v_commsioncount := 0;
  v_co_count := 0;
  v_tempplid1 := 0;
  v_invoiceno := '';
  v_invoicedate := '';
  DROP TABLE IF EXISTS tmp_temp_commissioninvoice;
  CREATE TEMP TABLE tmp_temp_commissioninvoice (ROWNUMBER INT GENERATED BY DEFAULT AS IDENTITY,  
INVOICENO VARCHAR(100),  
INVOICEDATE VARCHAR(100),  
PLID INT) ON COMMIT DROP;
  INSERT INTO tmp_temp_commissioninvoice SELECT COALESCE(invoiceno, ''), COALESCE(invoicedate, ''), COALESCE(plid, 0) FROM tbl_merchant_commissioninvoices WHERE orderid = v_tempoederid;
  SELECT COUNT(1) INTO v_commsioncount FROM tmp_temp_commissioninvoice;
  WHILE (v_commsioncount >= v_co_count) LOOP
  SELECT 0, 0, 0, 0, 0 INTO v_tempplid1, v_netpayable, v_grossamount, v_commissionvalue, v_totalcommsionwithgst;
  SELECT COALESCE(plid, 0), invoiceno, invoicedate INTO v_tempplid1, v_invoiceno, v_invoicedate FROM tmp_temp_commissioninvoice WHERE rownumber = v_co_count;
  IF (v_tempplid1 > 0) THEN
  SELECT COALESCE(SUM(tcd.taxableamount), 0), COALESCE(SUM(cgstamount + sgstamount + igstamount), 0) INTO v_grossamount, v_taxdeductionamount FROM tbl_merchant_commissioninvoices_details AS tcd INNER JOIN tbl_merchant_commissioninvoices AS tcm ON tcd.tmciid = tcm.tmciid WHERE tcd.orderid = v_tempoederid AND tcd.plid = v_tempplid1;
  IF (v_tempoederid <> '') THEN
  SELECT v_totalcommsion, v_totalcommsionwithgst INTO v_commissionvalue, v_totalcommsionwithgst FROM dbo.usp_get_commsionamount(v_orderid => v_tempoederid, v_plid => v_tempplid1, v_totalcommsion => v_commissionvalue, v_totalcommsionwithgst => v_totalcommsionwithgst);
  END IF;
  v_netpayable := v_grossamount - (v_commissionvalue + v_totalcommsionwithgst);
  IF NOT EXISTS(SELECT 1 FROM tbl_merchant_settlement_commissions WHERE invoiceno = v_invoiceno) THEN
  INSERT INTO tbl_merchant_settlement_commissions (duedate, invoiceno, invoicedate, orderid, grossamount, commissions, taxdeductions, netpayable, status, active, createdate, plid, tmorid) VALUES (v_duedate, v_invoiceno, v_invoicedate, v_tempoederid, v_grossamount, v_commissionvalue, v_totalcommsionwithgst, v_netpayable, 1, 1, dbo.FUN_GETCURRENTDATE(), v_tempplid1, v_tmorid);
  END IF;
  END IF;
  v_co_count := v_co_count + 1;
  END LOOP;
  DROP TABLE IF EXISTS tmp_temp_commissioninvoice;
  v_count := v_count + 1;
  END LOOP;
  DROP TABLE IF EXISTS tmp_temp, tmp_tbl_merchant_ordertransaction;
  v_twcount := 1;
  v_totalwcount := 0;
  v_plidwallet := '';
  v_amount := 0;
  v_balance := 0;
  v_tmscid := 0;
  DROP TABLE IF EXISTS tmp_temp_wallet;
  CREATE TEMP TABLE tmp_temp_wallet (ROWNUMBER INT GENERATED BY DEFAULT AS IDENTITY,  
PLID INT) ON COMMIT DROP;
  DROP TABLE IF EXISTS tmp_temp_resellerwallettable;
  CREATE TEMP TABLE tmp_temp_resellerwallettable (ROWNUMBER INT GENERATED BY DEFAULT AS IDENTITY,  
ORDERID VARCHAR(100)) ON COMMIT DROP;
  INSERT INTO tmp_temp_resellerwallettable SELECT DISTINCT COALESCE(orderid, '') FROM tbl_merchant_settlement_commissions WHERE status = 1;
  INSERT INTO tmp_temp_wallet SELECT DISTINCT plid FROM tbl_merchant_settlement_commissions WHERE status = 1;
  SELECT COUNT(*) INTO v_totalwcount FROM tmp_temp_wallet;
  WHILE (v_totalwcount >= v_twcount) LOOP
  SELECT COALESCE(plid, 0) INTO v_plidwallet FROM tmp_temp_wallet WHERE rownumber = v_twcount;
  SELECT COALESCE(SUM(netpayable), 0) INTO v_amount FROM tbl_merchant_settlement_commissions WHERE plid = v_plidwallet AND status = 1;
  SELECT COALESCE(balance, 0) INTO v_balance FROM tbl_merchant_wallet_statements WHERE plid = v_plidwallet AND status = 1;
  INSERT INTO tbl_merchant_wallet_statements (particular, crdrtype, amount, balance, active, createdate, plid) VALUES ('CREDIT IN WALLET AGAINST SETTLEMENT ' || CAST(dbo.FUN_GETCURRENTDATE() AS VARCHAR(100)), 'CR', v_amount, (v_amount + v_balance), 1, dbo.FUN_GETCURRENTDATE(), v_plidwallet);
  v_twcount := v_twcount + 1;
  UPDATE tbl_merchant_settlement_commissions SET status = 0 WHERE plid = v_plidwallet;
  END LOOP;
  DROP TABLE IF EXISTS tmp_temp_wallet;
  v_orderid := '';
  v_totalwcount := 0;
  v_twcount := 1;
  v_orderno := '';
  SELECT COUNT(*) INTO v_totalwcount FROM tmp_temp_resellerwallettable;
  WHILE (v_totalwcount >= v_twcount) LOOP
  SELECT COALESCE(orderid, '') INTO v_orderid FROM tmp_temp_resellerwallettable WHERE rownumber = v_twcount;
  SELECT COALESCE(v_orderno || ',', '') || CAST(orderno AS VARCHAR) INTO v_orderno FROM tbl_product_order_master WHERE orderid = v_orderid AND intstatus = 6;
  v_index := 1;
  v_slice := '';
  WHILE (v_index <> 0) LOOP
  SELECT POSITION(',' IN v_orderno) INTO v_index;
  IF (v_index <> 0) THEN
  SELECT LEFT(CAST(v_orderno AS TEXT), v_index - 1) INTO v_slice;
  ELSE
  SELECT v_orderno INTO v_slice;
  END IF;
  IF (v_slice <> '') THEN
  SELECT v_strresult INTO v_strresult_reseller_comssion FROM dbo.usp_manage_product_resellercommission(v_orderno => v_slice, v_strresult => v_strresult_reseller_comssion);
  END IF;
  SELECT RIGHT(CAST(v_orderno AS TEXT), LENGTH(CAST(v_orderno AS TEXT)) - v_index) INTO v_orderno;
  IF LENGTH(CAST(v_orderno AS TEXT)) = 0 THEN
  EXIT;
  END IF;
  END LOOP;
  v_twcount := v_twcount + 1;
  END LOOP;
  DROP TABLE IF EXISTS tmp_temp_resellerwallettable;
  IF (0 <> 0) THEN
  -- ROLLBACK (removed)
  v_strresult := 'ERROR^' || 0;
  RETURN;
  END IF;
  -- COMMIT (removed)
END;
$$;


--
-- Name: usp_merchnat_withdrawalhistory_report(integer, integer, character varying, character varying, character varying, character varying, character varying, character varying, integer, numeric, numeric, numeric, character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_merchnat_withdrawalhistory_report(v_startrowindex integer DEFAULT 1, v_maxrows integer DEFAULT 100, v_searchfield character varying DEFAULT ''::character varying, v_searchvalue character varying DEFAULT ''::character varying, v_fromdate character varying DEFAULT ''::character varying, v_todate character varying DEFAULT ''::character varying, v_transactiontype character varying DEFAULT ''::character varying, v_status character varying DEFAULT ''::character varying, INOUT v_totalcount integer DEFAULT 0, INOUT v_totalwithdrawal numeric DEFAULT 0, INOUT v_totaltds numeric DEFAULT 0, INOUT v_totaladmincharges numeric DEFAULT 0, v_orderbydate character varying DEFAULT ''::character varying) RETURNS record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_minindex INT;
  v_maxindex INT;
  v_condition text;
  v_condition1 varchar(500);
  v_queryresult text;
  v_countquery text;
  v_tdsquery text;
  v_adminchargequery text;
  v_totalamount text;
  v_maxregno text;
  v_parmdefinition text;
  v_parmdefinition1 text;
  v_parmdefinitiontds text;
  v_parmdefinitionadmincharge text;
BEGIN
  v_condition := '';
  v_condition1 := '';
  v_queryresult := '';
  v_countquery := '';
  v_tdsquery := '';
  v_adminchargequery := '';
  v_totalamount := '';
  v_maxregno := '';
  v_minindex := (v_startrowindex - 1) * v_maxrows + 1;
  v_maxindex := v_startrowindex * v_maxrows;
  v_queryresult := 'SELECT ROW_NUMBER() OVER(ORDER BY TW.TMWDID desc) AS ROWNUMBER, ISNULL(PM.COMPANYNAME,'''') AS USERNAME,
ISNULL(MM.FNAME,'''')+''''+ ISNULL(MM.LNAME,'''') AS NAME,
ISNULL(TW.CRDRTYPE,'''') AS CRDRTYPE,ISNULL(TW.WITHDRAWAMOUNT,0) AS WITHDRAWALAMT,
ISNULL(TW.ADMINCHARGE,0) AS ADMINCHARGE, ISNULL(TW.TDS,0) AS TDS,ISNULL(TW.STATUS,'''')AS STATUS,
ISNULL(MM.EMAILID,'''') AS EMAILID, ISNULL(MM.Phone,'''') AS MOBILE, ISNULL(MM.PANNO,'''') AS PANNO,
ISNULL(TW.DATE,'''') AS DATE,ISNULL(WH.ACCOUNTHOLDERNAME,'''') AS ACCOUNTHOLDERNAME,
ISNULL(WH.ACCOUNTNO,'''') AS ACCOUNTNO,
ISNULL(WH.BANKNAME,'''') AS BANKNAME,ISNULL(WH.BRANCHNAME,'''') AS BRANCHNAME,ISNULL(WH.IFSCCODE,'''') AS IFSC,
ISNULL(TP.PAYMODE,'''') as Paymode
INTO #TEMPWIHTHDRAWALHISTORY FROM TBL_MERCHANT_WITHDRAWALS TW 
INNER JOIN BANK_ACCOUNTS_MERCHANT WH ON TW.PLID=WH.PLID
INNER JOIN PORTAL_LOGIN MM ON TW.PLID=MM.PLID
LEFT JOIN TBL_PAYMODE TP ON TW.PAYMODE=TP.PMOID
INNER JOIN PORTAL_MASTER PM ON TW.PLID=PM.PLID
WHERE TW.STATUS IN (1,3) ';
  v_parmdefinition := N'@TOTALCOUNT NVARCHAR(1000) OUTPUT';
  v_countquery := N'SELECT @TOTALCOUNT =COUNT(1) FROM TBL_MERCHANT_WITHDRAWALS TW  WHERE 1=1 AND TW.STATUS IN (1,3) ';
  v_parmdefinition1 := N' @TOTALWITHDRAWAL NVARCHAR(1000) OUTPUT';
  v_totalamount := N'SELECT @TOTALWITHDRAWAL= ISNULL(SUM(CAST(TW.WITHDRAWAMOUNT AS DECIMAL(18,8))),0)  FROM  TBL_MERCHANT_WITHDRAWALS TW  
	WHERE 1=1 AND TW.STATUS IN (1,3) ';
  v_parmdefinitiontds := N' @TOTALTDS NVARCHAR(1000) OUTPUT';
  v_tdsquery := N'SELECT @TOTALTDS= ISNULL(SUM(CAST(TW.TDS AS DECIMAL(18,8))),0)  FROM  TBL_MERCHANT_WITHDRAWALS TW   
	 WHERE 1=1  AND TW.STATUS IN (1.3) ';
  v_parmdefinitionadmincharge := N' @TOTALADMINCHARGES NVARCHAR(1000) OUTPUT';
  v_adminchargequery := N'SELECT @TOTALADMINCHARGES= ISNULL(SUM(CAST(TW.ADMINCHARGE AS DECIMAL(18,8))),0)  FROM  TBL_MERCHANT_WITHDRAWALS TW  
	 WHERE 1=1 AND TW.STATUS IN (1,3) ';
  IF (v_searchfield = 'USERNAME') THEN
  v_condition := v_condition || ' AND MM.USERNAME = ''' || CAST(v_searchvalue AS VARCHAR(100)) || ''' ';
  END IF;
  IF (v_searchfield = 'NAME') THEN
  v_condition := v_condition || ' AND ISNULL(MM.FNAME,'''')+''''+ISNULL(MM.LNAME,'''') = ''' || CAST(v_searchvalue AS VARCHAR(100)) || ''' ';
  END IF;
  IF (v_transactiontype <> '') THEN
  v_condition := v_condition || ' AND TW.CRDRTYPE = ''' || CAST(v_transactiontype AS VARCHAR(100)) || ''' ';
  END IF;
  IF (v_status <> '') THEN
  v_condition := v_condition || ' AND TW.STATUS = ''' || CAST(v_status AS VARCHAR(100)) || ''' ';
  END IF;
  IF ((v_fromdate <> '') AND (v_todate = '')) THEN
  v_condition := v_condition || ' AND CONVERT(VARCHAR(15), TW.DATE, 105) =  CONVERT(VARCHAR(15), ''' || v_fromdate || ''', 105) ';
  END IF;
  IF ((v_fromdate = '') AND (v_todate <> '')) THEN
  v_condition := v_condition || ' AND CONVERT(VARCHAR(15),TW.DATE, 105) =  CONVERT(VARCHAR(15), ''' || v_todate || ''', 105) ';
  END IF;
  IF ((v_fromdate <> '') AND (v_todate <> '')) THEN
  v_condition := v_condition || ' AND CONVERT(VARCHAR(15), TW.DATE, 105) BETWEEN CONVERT(VARCHAR(15), ''' || v_fromdate || ''', 105) AND CONVERT(VARCHAR(15), ''' || v_todate || ''', 105)';
  END IF;
  IF (v_orderbydate = 'ASC') THEN
  v_condition1 := v_condition1 || ' ORDER BY DATE ASC';
  ELSE
  v_condition1 := v_condition1 || ' ORDER BY DATE DESC';
  END IF;
  v_queryresult := v_queryresult || v_condition || v_condition1 || ' ;SELECT  *  FROM #TEMPWIHTHDRAWALHISTORY WHERE ROWNUMBER BETWEEN ' || CAST(v_minindex AS text) || ' AND ' || CAST(v_maxindex AS text) || ' ' || v_condition1 || '';
  v_countquery := v_countquery || v_condition;
  v_totalamount := v_totalamount || v_condition;
  v_adminchargequery := v_adminchargequery || v_condition;
  v_tdsquery := v_tdsquery || v_condition;
  EXECUTE v_queryresult;
  RAISE NOTICE '%', v_queryresult;
  EXECUTE v_totalamount;
  EXECUTE v_tdsquery;
  EXECUTE v_adminchargequery;
  EXECUTE v_countquery;
END;
$$;


--
-- Name: usp_mobile_modify(integer, integer, character varying, integer, character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_mobile_modify(v_tmcsmid integer, v_plid integer, v_mobile character varying, v_check integer, INOUT v_message character varying) RETURNS character varying
    LANGUAGE plpgsql
    AS $$
BEGIN
  -- BEGIN TRAN (removed)
  v_message := 'Success';
  IF EXISTS(SELECT mobile FROM tbl_member_customer_mobile WHERE mobile = v_mobile) THEN
  v_message := 'Mobile id already exist!';
  -- COMMIT (removed)
  RETURN;
  END IF;
  UPDATE tbl_member_customer_mobile SET mobile = v_mobile, isactive = v_check WHERE tmcsmid = v_tmcsmid;
  IF (0 <> 0) THEN
  v_message := 'Some error occurred !';
  -- ROLLBACK (removed)
  RETURN;
  END IF;
  -- COMMIT (removed)
END;
$$;


--
-- Name: usp_mobile_registarion_msg(character varying, character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_mobile_registarion_msg(v_mobile character varying DEFAULT ''::character varying, INOUT v_strresult character varying DEFAULT 0) RETURNS character varying
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_start varchar(50);
  v_end varchar(50);
BEGIN
  SELECT SUBSTRING(phone FROM 1 FOR 2), SUBSTRING(phone FROM 9 FOR 2) INTO v_start, v_end FROM tbl_customerlogin WHERE phone = v_mobile;
  v_strresult := ' Mobile NO ''' || v_start || '''XXXXXX''' || v_end || '';
  -- SET option (removed)
END;
$$;


--
-- Name: usp_monthlysubscription(bigint, integer, character varying, integer, text, text, text, text, text, integer, text, numeric, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_monthlysubscription(v_plid bigint DEFAULT 0, v_paymentmode integer DEFAULT 0, v_paymentmodename character varying DEFAULT ''::character varying, v_paymentstatus integer DEFAULT 0, v_bankname text DEFAULT ''::text, v_branchname text DEFAULT ''::text, v_referenceno text DEFAULT ''::text, v_referencedate text DEFAULT ''::text, v_commentorremark text DEFAULT ''::text, v_tsmid integer DEFAULT 0, v_pakcage_name text DEFAULT ''::text, v_package_amt numeric DEFAULT 0, INOUT v_intresult integer DEFAULT 0) RETURNS integer
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_activationdate timestamp;
  v_startfrom INt;
  v_upto Int;
  v_tempregno Int;
  v_totalcreditedaddpoints BigInt;
  v_regno BIGINT;
  v_strresult VARCHAR(100);
  v_respouse_code text;
  v_introplid BIGINT;
BEGIN
  -- BEGIN TRAN (removed)
  -- SET option (removed)
  BEGIN
  v_startfrom := 0;
  v_upto := 0;
  v_activationdate := CAST(dbo.FUN_GETCURRENTDATE() AS DATE);
  INSERT INTO tbl_membersubscriptionaccount (plid, noofdaysforactivation, activationdate, tilldate, tsmid, allocatednoofsms, remainnoofsms, allocatednoofemail, remainnoofemail, allocatednoofwhatsupmessage, remainnoofwhatsupmessage, paymentmode, paymentmodename, paymentstatus, bankname, branchname, referenceno, referencedate, activitydate, isactive, status, commentorremark, noofkeyword, noofcity, allocatednoofhits, remainnoofhits) SELECT v_plid, noofdaysforactivation, CAST(v_activationdate AS DATE), CAST((v_activationdate + noofdaysforactivation) AS DATE), tsmid, noofsms, noofsms, noofemail, noofemail, noofwhatsupmessage, noofwhatsupmessage, v_paymentmode, v_paymentmodename, (CASE WHEN v_paymentmode = 1 THEN 1 WHEN v_paymentmode = 2 THEN 1 WHEN v_paymentmode = 3 THEN 1 WHEN v_paymentmode = 4 THEN 1 WHEN v_paymentmode = 5 THEN 1 WHEN v_paymentmode = 6 THEN 1 WHEN v_paymentmode = 7 THEN 1 WHEN v_paymentmode = 8 THEN 1 WHEN v_paymentmode = 9 THEN 1 WHEN v_paymentmode = 10 THEN 1 WHEN v_paymentmode = 11 THEN 1 END), v_bankname, v_branchname, v_referenceno, v_referencedate, CURRENT_TIMESTAMP, (CASE WHEN v_paymentmode = 1 THEN 1 WHEN v_paymentmode = 2 THEN 1 WHEN v_paymentmode = 3 THEN 1 WHEN v_paymentmode = 4 THEN 1 WHEN v_paymentmode = 5 THEN 1 WHEN v_paymentmode = 6 THEN 1 WHEN v_paymentmode = 7 THEN 1 WHEN v_paymentmode = 8 THEN 1 WHEN v_paymentmode = 9 THEN 1 WHEN v_paymentmode = 10 THEN 1 WHEN v_paymentmode = 11 THEN 1 ELSE 1 END), 1, v_commentorremark, noofkeywords, noofcities, noofhits, noofhits FROM tbl_subscriptionmaster WHERE istrailsubscription = 0 AND status = 1 AND tsmid = v_tsmid LIMIT 1;
  IF NOT EXISTS(SELECT 1 FROM tbl_memberroiaccount WHERE plid = v_plid) THEN
  v_tempregno := 0;
  v_totalcreditedaddpoints := 0;
  SELECT regno INTO v_tempregno FROM portal_login WHERE plid = v_plid;
  INSERT INTO tbl_memberroiaccount (regno, plid, tsmid, totalcreditedaddpoints, maxnoofclicksperdayforview, priceperlinkforview, maxnooflinkperdayforshare, priceperlinkforshare, maxnoofblogperday, priceperblog, maxnoofclassifiedperday, priceperclassified, lastupdateddate, status, maxpointforview, maxpointforshare, maxpointforblog, maxpointforclassified, perdaypointforblog, perdaypointforclassified, perdaypointforview, perdaypointforshare) SELECT v_tempregno, v_plid, tsmid, totalcreditedaddpoints, maxnoofclicksperdayforview, priceperlinkforview, maxnooflinkperdayforshare, priceperlinkforshare, maxnoofblogperday, priceperblog, maxnoofclassifiedperday, priceperclassified, dbo.FUN_GETCURRENTDATE(), 1, maxpointforview, maxpointforshare, maxpointforblog, maxpointforclaassified, pointperdayforblog, pointperdayforclassified, pointperdayforview, pointperdayforshare FROM tbl_roimaster WHERE tsmid = v_tsmid;
  SELECT totalcreditedaddpoints INTO v_totalcreditedaddpoints FROM tbl_roimaster WHERE tsmid = v_tsmid;
  UPDATE member_performance SET totaltaskpoints = COALESCE(totaltaskpoints, 0) + v_totalcreditedaddpoints WHERE regno = v_tempregno;
  END IF;
  v_regno := 0;
  v_strresult := '';
  v_respouse_code := '';
  v_introplid := 0;
  SELECT intro_plid INTO v_introplid FROM portal_login WHERE plid = v_plid;
  IF (COALESCE(v_introplid, 0) > 0) THEN
  SELECT regno INTO v_regno FROM member_master WHERE plid = v_plid;
  UPDATE member_master SET active = 1 WHERE regno = v_regno;
  INSERT INTO tbl_tempdirectincomedistribution VALUES (v_regno, v_tsmid, v_package_amt, CURRENT_TIMESTAMP, 1, 1);
  v_strresult := 'Ok';
  IF (v_strresult <> 'Ok') THEN
  v_intresult := 0;
  -- ROLLBACK (removed)
  RETURN;
  END IF;
  END IF;
  IF (0 = 0) THEN
  v_intresult := 1;
  -- COMMIT (removed)
  RETURN;
  ELSE
  v_intresult := 0;
  -- ROLLBACK (removed)
  RETURN;
  END IF;
  EXCEPTION WHEN OTHERS THEN
  v_intresult := 0;
  -- ROLLBACK (removed)
  RETURN;
  END;
  -- SET option (removed)
  -- COMMIT (removed)
END;
$$;


--
-- Name: usp_multipleapproveandnewsale(character varying, bigint, character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_multipleapproveandnewsale(v_checkids character varying DEFAULT ''::character varying, v_branchid bigint DEFAULT 0, INOUT v_strresult character varying DEFAULT NULL::character varying) RETURNS character varying
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_count1 int;
  v_count2 int;
  v_splitdata bigint;
BEGIN
  DROP TABLE IF EXISTS tmp_temp2;
  CREATE TEMP TABLE tmp_temp2 ON COMMIT DROP AS SELECT ROW_NUMBER() OVER (ORDER BY splitdata NULLS FIRST) AS rowno, * FROM dbo.FNSPLITSTRING(v_checkids, ',');
  v_count1 := 0;
  v_count2 := 0;
  v_count1 := 1;
  SELECT COUNT(1) INTO v_count2 FROM tmp_temp2;
  WHILE (v_count1 <= v_count2) LOOP
  SELECT splitdata INTO v_splitdata FROM tmp_temp2 WHERE rowno = v_count1;
  SELECT v_strresult INTO v_strresult FROM dbo.usp_approvalandnewsale(v_id => v_splitdata, v_branchid => v_branchid, v_strresult => v_strresult);
  v_count1 := v_count1 + 1;
  END LOOP;
  DROP TABLE IF EXISTS tmp_temp2;
END;
$$;


--
-- Name: usp_multipleimageforproduct(integer, integer, character varying, character varying, character varying, character varying, character varying, character varying, integer, character varying, bigint, bigint, bigint, bigint, bigint, bigint); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_multipleimageforproduct(v_startrowindex integer DEFAULT 1, v_maxrows integer DEFAULT 100, v_searchfield character varying DEFAULT ''::character varying, v_searchvalue character varying DEFAULT ''::character varying, v_fromdate character varying DEFAULT ''::character varying, v_todate character varying DEFAULT ''::character varying, v_imagename character varying DEFAULT ''::character varying, v_url character varying DEFAULT ''::character varying, v_mode integer DEFAULT 3, v_stroutput character varying DEFAULT ''::character varying, v_totalrecord bigint DEFAULT 0, v_maincatid bigint DEFAULT 0, v_catid bigint DEFAULT 0, v_subcatid bigint DEFAULT 0, v_groupid bigint DEFAULT 0, v_plid bigint DEFAULT 1) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_query text;
  v_minindex INT;
  v_maxindex INT;
  v_uploadeddate timestamp;
BEGIN
  -- BEGIN TRAN (removed)
  BEGIN
  DROP TABLE IF EXISTS tmp_multipleimageforproduct;
  CREATE TEMP TABLE tmp_multipleimageforproduct (ROWNUMBER bigint ,
IMAGENAME varchar(200),
URL varchar(200),
GROUPID bigint) ON COMMIT DROP;
  DROP TABLE IF EXISTS tmp_multipleimageforproductgroup;
  CREATE TEMP TABLE tmp_multipleimageforproductgroup (ROWNUMBER1 bigint GENERATED BY DEFAULT AS IDENTITY,
UPLOADEDDATE varchar(200),
MAINCATID bigint,
CATID  bigint,
SUBCATID bigint,
GROUPID bigint,
TotalImageUploaded bigint,
categoryname varchar(100),
subcategoryname varchar(100),
subsubcategoryname varchar(100)) ON COMMIT DROP;
  v_query := '';
  v_minindex := (v_startrowindex - 1) * v_maxrows + 1;
  v_maxindex := v_startrowindex * v_maxrows;
  IF (v_mode = 1) THEN
  IF EXISTS(SELECT 1 FROM tbl_productupload_image WHERE groupid = v_groupid) THEN
  SELECT uploadeddate INTO v_uploadeddate FROM tbl_productupload_image WHERE groupid = v_groupid;
  v_stroutput := 'ADD';
  INSERT INTO tbl_productupload_image (imagename, url, status, active, maincatid, catid, subcatid, groupid, plid, uploadeddate) VALUES (v_imagename, v_url, 1, 1, v_maincatid, v_catid, v_subcatid, v_groupid, v_plid, v_uploadeddate);
  ELSE
  v_stroutput := 'ADD';
  INSERT INTO tbl_productupload_image (imagename, url, status, active, maincatid, catid, subcatid, groupid, plid, uploadeddate) VALUES (v_imagename, v_url, 1, 1, v_maincatid, v_catid, v_subcatid, v_groupid, v_plid, dbo.FUN_GETCURRENTDATE());
  END IF;
  END IF;
  IF (v_mode = 2) THEN
  IF (v_groupid <> 0) THEN
  INSERT INTO tmp_multipleimageforproduct SELECT ROW_NUMBER() OVER (ORDER BY puid DESC NULLS LAST) AS rownumber, imagename, url, groupid FROM tbl_productupload_image WHERE groupid = v_groupid AND plid = v_plid;
  RETURN QUERY SELECT * FROM tmp_multipleimageforproduct WHERE groupid = v_groupid AND rownumber BETWEEN v_minindex AND v_maxindex;
  SELECT COUNT(1) INTO v_totalrecord FROM tmp_multipleimageforproduct WHERE groupid = v_groupid;
  ELSE
  INSERT INTO tmp_multipleimageforproduct SELECT ROW_NUMBER() OVER (ORDER BY puid DESC NULLS LAST) AS rownumber, imagename, url, groupid FROM tbl_productupload_image WHERE plid = v_plid;
  RETURN QUERY SELECT * FROM tmp_multipleimageforproduct WHERE rownumber BETWEEN v_minindex AND v_maxindex;
  SELECT COUNT(1) INTO v_totalrecord FROM tmp_multipleimageforproduct;
  END IF;
  END IF;
  IF (v_mode = 3) THEN
  IF (v_plid <> 0) THEN
  v_query := 'insert into #MULTIPLEIMAGEFORPRODUCTGROUP select  
			convert(varchar,(FORMAT(convert(datetime,UPLOADEDDATE,101),''MM/dd/yyyy HH:mm'')),101) as UPLOADEDDATE,ISNULL(MAINCATID,0) as MAINCATID,
			isnull(pc.CATID,0) as CATID,isnull(SUBCATID,0) as SUBCATID,isnull(GROUPID,0) as GROUPID,
			Count(1)As TotalImageUploaded ,isnull(pc.CATNAME,'''') as CATNAME,isnull(ps.SCATNAME,'''') as SCATNAME,isnull(km.KEYWORDNAME,'''') as KEYWORDNAME 
			From TBL_PRODUCTUPLOAD_IMAGE tue 
			  left join PRODUCT_CATEGORY pc on pc.CATID=tue.MAINCATID
	 left join PRODUCT_SUBCATEGORY ps on ps.SCATID=tue.CATID
	 left join KEYWORD_MASTER km on km.KMID=tue.SUBCATID  where plid=' || CAST(v_plid AS VARCHAR(30)) || '';
  ELSE
  v_query := 'insert into #MULTIPLEIMAGEFORPRODUCTGROUP select  ROW_NUMBER() OVER(ORDER BY GROUPID DESC) AS ROWNUMBER1,
	convert(varchar,(FORMAT(convert(datetime,UPLOADEDDATE,101),''MM/dd/yyyy HH:mm'')),101) as UPLOADEDDATE,
	ISNULL(MAINCATID,0) as MAINCATID,isnull(pc.CATID,0) as CATID,isnull(SUBCATID,0) as SUBCATID,isnull(GROUPID,0) as GROUPID,
			Count(1)As TotalImageUploaded ,isnull(pc.CATNAME,'''') as CATNAME,isnull(ps.SCATNAME,'''') as SCATNAME,isnull(km.KEYWORDNAME,'''') as KEYWORDNAME From TBL_PRODUCTUPLOAD_IMAGE tue 
			  left join PRODUCT_CATEGORY pc on pc.CATID=tue.MAINCATID
	 left join PRODUCT_SUBCATEGORY ps on ps.SCATID=tue.CATID
	 left join KEYWORD_MASTER km on km.KMID=tue.SUBCATID  where 1=1 ';
  END IF;
  IF (v_searchfield = 'MAINCATID' AND v_maincatid <> 0) THEN
  v_query := v_query || ' AND MAINCATID=' || v_maincatid || '';
  END IF;
  IF (v_searchfield = 'CATID' AND v_catid <> 0) THEN
  v_query := v_query || ' AND CATID=' || v_catid || '';
  END IF;
  IF (v_searchfield = 'SUBCATID' AND v_subcatid <> 0) THEN
  v_query := v_query || ' AND SUBCATID=' || v_subcatid || '';
  END IF;
  IF ((v_fromdate <> '') AND (v_todate = '')) THEN
  v_query := v_query || ' AND CONVERT(DATE, UPLOADEDDATE, 105) BETWEEN  CONVERT(DATE, ''' || v_fromdate || ''', 105) AND  CONVERT(DATE, DBO.FUN_GETCURRENTDATE(), 105)';
  END IF;
  IF ((v_fromdate = '') AND (v_todate <> '')) THEN
  v_query := v_query || ' AND CONVERT(DATE, UPLOADEDDATE, 105) BETWEEN  CONVERT(DATE, ''' || v_todate || ''', 105) AND  CONVERT(DATE, DBO.FUN_GETCURRENTDATE(), 105)';
  END IF;
  IF ((v_fromdate <> '') AND (v_todate <> '')) THEN
  v_query := v_query || ' AND CONVERT(DATE, UPLOADEDDATE, 105) BETWEEN CONVERT(DATE, ''' || v_fromdate || ''', 105) AND  CONVERT(DATE, ''' || v_todate || ''', 105)';
  END IF;
  v_query := v_query || ' Group By convert(varchar,(FORMAT(convert(datetime,UPLOADEDDATE,101),''MM/dd/yyyy HH:mm'')),101),MAINCATID,pc.CATID,SUBCATID,GROUPID,pc.CATNAME ,
		ps.SCATNAME,km.KEYWORDNAME order by UPLOADEDDATE desc';
  EXECUTE v_query;
  RAISE NOTICE '%', (v_query);
  RETURN QUERY SELECT * FROM tmp_multipleimageforproductgroup WHERE rownumber1 BETWEEN v_minindex AND v_maxindex;
  SELECT COUNT(1) INTO v_totalrecord FROM tmp_multipleimageforproductgroup;
  DROP TABLE IF EXISTS tmp_multipleimageforproductgroup;
  END IF;
  DROP TABLE IF EXISTS tmp_multipleimageforproduct;
  IF (0 <> 0) THEN
  v_stroutput := 'Some Eroor Occurs.';
  -- ROLLBACK (removed)
  RETURN;
  END IF;
  -- COMMIT (removed)
  EXCEPTION WHEN OTHERS THEN
  IF (0 <> 0) THEN
  v_stroutput := 'Some Eroor Occurs.';
  -- ROLLBACK (removed)
  RETURN;
  END IF;
  END;
END;
$$;


--
-- Name: usp_netbanking_statement(integer, integer, character varying, character varying, character varying, character varying, integer, character varying, integer, character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_netbanking_statement(v_startrowindex integer DEFAULT 1, v_maxrows integer DEFAULT 1000, v_searchfield character varying DEFAULT ''::character varying, v_searchvalue character varying DEFAULT ''::character varying, v_fromdate character varying DEFAULT ''::character varying, v_todate character varying DEFAULT ''::character varying, v_totalcount integer DEFAULT 0, v_resselername character varying DEFAULT ''::character varying, v_mode integer DEFAULT 0, v_resellerid character varying DEFAULT ''::character varying) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_minindex int;
  v_maxindex int;
  v_query text;
BEGIN
  v_minindex := (v_startrowindex - 1) * v_maxrows + 1;
  v_maxindex := v_startrowindex * v_maxrows;
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp (rownumber int GENERATED BY DEFAULT AS IDENTITY,        
	ORDERDATE timestamp,         
	NETAMOUNT  decimal(18,8),	
	Remark varchar(500),	
	WALLET decimal(18,8),
	TYPE varchar(50),			
    AMOUNT decimal(18,8),					
    CustomerName varchar(250),
	EMAILID	varchar(250),
	PHONE varchar(250),				
    DistributorName varchar(250)) ON COMMIT DROP;
  IF (v_mode = 0) THEN
  v_query := 'insert into #temp 
select isnull(cdn.ORDERDATE,'''') as ORDERDATE,isnull(cdn.NETAMOUNT,0) as NETAMOUNT,isnull(cdn.Remark+cdn.ORDERNO,'''') as Remark,isnull(cdn.WALLET,0)  as WALLET
,isnull(cdn.TYPE,'''')  as TYPE,isnull(cdn.AMOUNT,0) as AMOUNT,isnull((cl.FNAME + cl.LNAME),'''') as CustomerName,isnull(cl.EMAILID,'''') as EMAILID,isnull(cl.PHONE,'''') as PHONE,
isnull((dl.FNAME + dl.LNAME),'''') as DistributorName from  tbl_transaction_CDN cdn left join TBL_CUSTOMERLOGIN cl on cl.CLID=cdn.PLID
left join TBL_DISTRIBUTOR Dl on dl.DID=cdn.FROMPLID where 1=1 ';
  END IF;
  IF (v_mode = 1) THEN
  v_query := 'insert into #temp 
select isnull(cdn.ORDERDATE,'''') as ORDERDATE,isnull(cdn.NETAMOUNT,0) as NETAMOUNT,isnull(cdn.Remark+cdn.ORDERNO,'''') as Remark,isnull(cdn.WALLET,0)  as WALLET
,isnull(cdn.TYPE,'''')  as TYPE,isnull(cdn.AMOUNT,0) as AMOUNT,isnull((cl.FNAME + cl.LNAME),'''') as CustomerName,isnull(cl.EMAILID,'''') as EMAILID,isnull(cl.PHONE,'''') as PHONE,
isnull((dl.FNAME + dl.LNAME),'''') as DistributorName from  tbl_transaction_SSPW cdn left join TBL_CUSTOMERLOGIN cl on cl.CLID=cdn.PLID
left join TBL_DISTRIBUTOR Dl on dl.DID=cdn.FROMPLID where 1=1';
  END IF;
  IF (v_mode = 2) THEN
  v_query := 'insert into #temp 
select isnull(cdn.ORDERDATE,'''') as ORDERDATE,isnull(cdn.NETAMOUNT,0) as NETAMOUNT,isnull(cdn.Remark+cdn.ORDERNO,'''') as Remark,isnull(cdn.WALLET,0)  as WALLET
,isnull(cdn.TYPE,'''')  as TYPE,isnull(cdn.AMOUNT,0) as AMOUNT,isnull((cl.FNAME + cl.LNAME),'''') as CustomerName,isnull(cl.EMAILID,'''') as EMAILID,isnull(cl.PHONE,'''') as PHONE,
isnull((dl.FNAME + dl.LNAME),'''') as DistributorName from  tbl_transaction_COD cdn left join TBL_CUSTOMERLOGIN cl on cl.CLID=cdn.PLID
left join TBL_DISTRIBUTOR Dl on dl.DID=cdn.FROMPLID where 1=1';
  END IF;
  IF (v_mode = 3) THEN
  v_query := 'insert into #temp 
select isnull(cdn.ORDERDATE,'''') as ORDERDATE,isnull(cdn.NETAMOUNT,0) as NETAMOUNT,isnull(cdn.Remark+cdn.ORDERNO,'''') as Remark,isnull(cdn.WALLET,0)  as WALLET
,isnull(cdn.TYPE,'''')  as TYPE,isnull(cdn.AMOUNT,0) as AMOUNT,isnull((cl.FNAME + cl.LNAME),'''') as CustomerName,isnull(cl.EMAILID,'''') as EMAILID,isnull(cl.PHONE,'''') as PHONE,
isnull((dl.FNAME + dl.LNAME),'''') as DistributorName from  tbl_transaction_PayU cdn left join TBL_CUSTOMERLOGIN cl on cl.CLID=cdn.PLID
left join TBL_DISTRIBUTOR Dl on dl.DID=cdn.FROMPLID where 1=1';
  END IF;
  IF (v_mode = 4) THEN
  v_query := 'insert into #temp 
select isnull(cdn.ORDERDATE,'''') as ORDERDATE,isnull(cdn.NETAMOUNT,0) as NETAMOUNT,isnull(cdn.Remark+cdn.ORDERNO,'''') as Remark,isnull(cdn.WALLET,0)  as WALLET
,isnull(cdn.TYPE,'''')  as TYPE,isnull(cdn.AMOUNT,0) as AMOUNT,isnull((cl.FNAME + cl.LNAME),'''') as CustomerName,isnull(cl.EMAILID,'''') as EMAILID,isnull(cl.PHONE,'''') as PHONE,
isnull((dl.FNAME + dl.LNAME),'''') as DistributorName from  tbl_transaction_SHOPPING cdn left join TBL_CUSTOMERLOGIN cl on cl.CLID=cdn.PLID
left join TBL_DISTRIBUTOR Dl on dl.DID=cdn.FROMPLID where 1=1 ';
  END IF;
  IF (v_mode = 5) THEN
  v_query := 'insert into #temp 
select isnull(cdn.ORDERDATE,'''') as ORDERDATE,isnull(cdn.NETAMOUNT,0) as NETAMOUNT,isnull(cdn.Remark+cdn.ORDERNO,'''') as Remark,isnull(cdn.WALLET,0)  as WALLET
,isnull(cdn.TYPE,'''')  as TYPE,isnull(cdn.AMOUNT,0) as AMOUNT,isnull((cl.FNAME + cl.LNAME),'''') as CustomerName,isnull(cl.EMAILID,'''') as EMAILID,isnull(cl.PHONE,'''') as PHONE,
isnull((dl.FNAME + dl.LNAME),'''') as DistributorName from  tbl_transaction_COMMISSION cdn left join TBL_CUSTOMERLOGIN cl on cl.CLID=cdn.PLID
left join TBL_DISTRIBUTOR Dl on dl.DID=cdn.FROMPLID where 1=1 ';
  END IF;
  IF (v_mode = 6) THEN
  v_query := 'insert into #temp 
select isnull(cdn.ORDERDATE,'''') as ORDERDATE,isnull(cdn.NETAMOUNT,0) as NETAMOUNT,isnull(cdn.Remark+cdn.ORDERNO,'''') as Remark,isnull(cdn.WALLET,0)  as WALLET
,isnull(cdn.TYPE,'''')  as TYPE,isnull(cdn.AMOUNT,0) as AMOUNT,isnull((cl.FNAME + cl.LNAME),'''') as CustomerName,isnull(cl.EMAILID,'''') as EMAILID,isnull(cl.PHONE,'''') as PHONE,
isnull((dl.FNAME + dl.LNAME),'''') as DistributorName from  tbl_transaction_COIN cdn left join TBL_CUSTOMERLOGIN cl on cl.CLID=cdn.PLID
left join TBL_DISTRIBUTOR Dl on dl.DID=cdn.FROMPLID where 1=1 ';
  END IF;
  IF (v_mode = 7) THEN
  v_query := 'insert into #temp 
select isnull(cdn.ORDERDATE,'''') as ORDERDATE,isnull(cdn.NETAMOUNT,0) as NETAMOUNT,isnull(cdn.Remark+cdn.ORDERNO,'''') as Remark,isnull(cdn.WALLET,0)  as WALLET
,isnull(cdn.TYPE,'''')  as TYPE,isnull(cdn.AMOUNT,0) as AMOUNT,isnull((cl.FNAME + cl.LNAME),'''') as CustomerName,isnull(cl.EMAILID,'''') as EMAILID,isnull(cl.PHONE,'''') as PHONE,
isnull((dl.FNAME + dl.LNAME),'''') as DistributorName from  tbl_transaction_iwallet cdn left join TBL_CUSTOMERLOGIN cl on cl.CLID=cdn.PLID
left join TBL_DISTRIBUTOR Dl on dl.DID=cdn.FROMPLID where 1=1';
  END IF;
  IF (v_fromdate <> '' AND v_todate = '') THEN
  v_query := v_query || (' AND CONVERT(DATE,cdn.ORDERDATE) >= CONVERT(DATE,''' || v_fromdate || ''') ');
  END IF;
  IF (v_fromdate = '' AND v_todate <> '') THEN
  v_query := v_query || (' AND CONVERT(DATE,cdn.ORDERDATE) <= CONVERT(DATE,''' || v_todate || ''') ');
  END IF;
  IF (v_fromdate <> '' AND v_todate <> '') THEN
  v_query := v_query || (' AND CONVERT(DATE,cdn.ORDERDATE) BETWEEN CONVERT(DATE,''' || v_fromdate || ''') AND CONVERT(DATE,''' || v_todate || ''')');
  END IF;
  IF (v_searchfield = 'EMAILID') THEN
  v_query := v_query || ' AND cl.EMAILID LIKE ''%' || v_searchvalue || '%'' ';
  END IF;
  IF (v_searchfield = 'CustomerName') THEN
  v_query := v_query || ' AND (cl.FNAME + cl.LNAME) LIKE ''%' || v_searchvalue || '%'' ';
  END IF;
  IF (v_searchfield = 'PHONE') THEN
  v_query := v_query || ' AND cl.PHONE LIKE ''%' || v_searchvalue || '%'' ';
  END IF;
  IF (v_resselername <> '') THEN
  v_query := v_query || ' and (dl.FNAME + dl.LNAME) =''' || v_resselername || '''';
  END IF;
  IF (v_resellerid <> '') THEN
  v_query := v_query || ' and  dl.DID =''' || v_resellerid || '''';
  END IF;
  EXECUTE v_query;
  RETURN QUERY SELECT * FROM tmp_temp WHERE rownumber BETWEEN v_minindex AND v_maxindex;
  SELECT COUNT(rownumber) INTO v_totalcount FROM tmp_temp;
  DROP TABLE IF EXISTS tmp_temp;
  -- SET option (removed)
END;
$$;


--
-- Name: usp_new_member_get_member_downlinelist_side_wise(character varying, integer, integer, text, text, text, text, integer, integer, integer, numeric, numeric, character varying, character varying, character varying, character varying, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_new_member_get_member_downlinelist_side_wise(v_loginid character varying DEFAULT ''::character varying, v_startrowindex integer DEFAULT 0, v_maxrows integer DEFAULT 0, v_searchfield text DEFAULT ''::text, v_searchvalue text DEFAULT ''::text, v_fromdate text DEFAULT ''::text, v_todate text DEFAULT ''::text, v_levenumber integer DEFAULT 0, v_side integer DEFAULT 0, v_totalcount integer DEFAULT 0, v_totallrbv numeric DEFAULT 0, v_totallrincome numeric DEFAULT 0, v_name character varying DEFAULT ''::character varying, v_username character varying DEFAULT ''::character varying, v_emailid character varying DEFAULT ''::character varying, v_sponserid character varying DEFAULT ''::character varying, v_checkadminside integer DEFAULT 0) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_query text;
  v_minindex INT;
  v_maxindex INT;
BEGIN
  v_query := '';
  v_minindex := (v_startrowindex - 1) * v_maxrows + 1;
  v_maxindex := v_startrowindex * v_maxrows;
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp (ROWNUMBER INT GENERATED BY DEFAULT AS IDENTITY,
LOGINID text,
SPONSERID text,
ROOTID text,
EMPLEVEL INT,
NAME text,
MOBILE text,
CITYNAME text,
REGDATE text,
STATUS  text,
EMAILID text,
DOC text,
TLBV numeric(19,4),
CLBV numeric(19,4),
TRBV numeric(19,4),
CRBV numeric(19,4),
PAIDBV numeric(19,4),
USERNAME text,
KITPRICE numeric(19,4) DEFAULT(0),
KITNAME VARCHAR(50),
INCOME numeric(19,4),
REGNO INT,
SIDE INT,
SPOUNSER_USERNAME VARCHAR(500),
ROOT_USERNAME VARCHAR(500),
LCOUNT INT,
RCOUNT INT) ON COMMIT DROP;
  SELECT loginid INTO v_loginid FROM member_master WHERE username = v_loginid;
  -- CREATE INDEX (skipped)
  IF (v_side = 0 OR v_side = 1) THEN
  v_query := 'INSERT INTO #TEMP Select * FROM [FUN_ALL_DOWNLINE_MEMBERLIST_LEFT_SIDE_WITHLRCOUNT](''' || v_loginid || ''')  WHERE LOGINID!= '''' ';
  IF (v_searchfield <> '' AND v_searchvalue <> '') THEN
  IF (v_searchfield = 'FNAME') THEN
  v_query := v_query || ' AND NAME LIKE ''%' || v_searchvalue || '%''';
  END IF;
  IF (v_searchfield = 'LOGINID') THEN
  v_query := v_query || ' AND USERNAME LIKE ''%' || v_searchvalue || '%'' ';
  END IF;
  IF (v_searchfield = 'PNAME') THEN
  v_query := v_query || ' AND  ROOT_USERNAME LIKE ''%' || v_searchvalue || '%'' ';
  END IF;
  IF (v_searchfield = 'SNAME') THEN
  v_query := v_query || ' AND SPOUNSER_USERNAME LIKE ''%' || v_searchvalue || '%'' ';
  END IF;
  END IF;
  IF (v_name <> '') THEN
  v_query := v_query || ' AND NAME LIKE ''%' || v_name || '%''';
  END IF;
  IF (v_username <> '') THEN
  v_query := v_query || ' AND  USERNAME LIKE ''%' || v_username || '%'' ';
  END IF;
  IF (v_emailid <> '') THEN
  v_query := v_query || ' AND  EMAILID LIKE ''%' || v_emailid || '%'' ';
  END IF;
  IF (v_sponserid <> '') THEN
  v_query := v_query || ' AND  SPOUNSER_USERNAME LIKE ''%' || v_sponserid || '%'' ';
  END IF;
  IF (v_levenumber > 0) THEN
  v_query := v_query || ' AND EMPLEVEL = ' || CAST(v_levenumber AS VARCHAR(10));
  END IF;
  IF (v_fromdate <> '' AND v_todate <> '') THEN
  v_query := v_query || ' AND CONVERT(DATE,REGDATE)>=CONVERT(DATE,''' || v_fromdate || ''') AND CONVERT(DATE,REGDATE)<=CONVERT(DATE,''' || v_todate || ''')';
  ELSE
  IF (v_fromdate <> '') THEN
  v_query := v_query || ' AND CONVERT(DATE,REGDATE)=CONVERT(DATE,''' || v_fromdate || ''')';
  ELSE
  IF (v_todate <> '') THEN
  v_query := v_query || ' AND CONVERT(DATE,REGDATE)=CONVERT(DATE,''' || v_todate || ''')';
  END IF;
  END IF;
  END IF;
  v_query := v_query || ' OPTION(MAXRECURSION 0)';
  EXECUTE v_query;
  END IF;
  IF (v_checkadminside = 1) THEN
  RETURN QUERY SELECT rownumber, loginid, sponserid, rootid, emplevel, (CASE WHEN name = '' THEN 'Not Updated' ELSE name END) AS name, mobile, cityname, regdate, status, emailid, doc, tlbv, clbv, trbv, crbv, paidbv, username, kitprice, kitname, income, regno, side, spounser_username, root_username, lcount, rcount FROM tmp_temp;
  ELSE
  RETURN QUERY SELECT rownumber, loginid, sponserid, rootid, emplevel, (CASE WHEN name = '' THEN 'Not Updated' ELSE name END) AS name, mobile, cityname, regdate, status, emailid, doc, tlbv, clbv, trbv, crbv, paidbv, username, kitprice, kitname, income, regno, side, spounser_username, root_username, lcount, rcount FROM tmp_temp WHERE rownumber BETWEEN v_minindex AND v_maxindex;
  END IF;
  SELECT COUNT(rownumber) INTO v_totalcount FROM tmp_temp;
  DROP TABLE IF EXISTS tmp_temp;
  -- SET option (removed)
END;
$$;


--
-- Name: usp_new_order_details(integer, integer, character varying, character varying, character varying, character varying, character varying, character varying, bigint, integer, character varying, bigint, character varying, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_new_order_details(v_startrowindex integer DEFAULT 1, v_maxrows integer DEFAULT 100, v_searchfield character varying DEFAULT ''::character varying, v_searchvalue character varying DEFAULT ''::character varying, v_fromdate character varying DEFAULT ''::character varying, v_todate character varying DEFAULT ''::character varying, v_status character varying DEFAULT ''::character varying, v_statustype character varying DEFAULT ''::character varying, v_branchid bigint DEFAULT 1, v_totalcount integer DEFAULT 0, v_company character varying DEFAULT ''::character varying, v_poid bigint DEFAULT 0, v_productname character varying DEFAULT ''::character varying, v_mode integer DEFAULT 1) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_minindex INT;
  v_maxindex INT;
  v_query text;
BEGIN
  v_minindex := (v_startrowindex - 1) * v_maxrows + 1;
  v_maxindex := v_startrowindex * v_maxrows;
  IF (v_mode = 1) THEN
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp (ROWNUMBER BIGINT 
, LOGINID VARCHAR( 100) 
, NAME VARCHAR(1000) 
, BRCODE VARCHAR( 50) 
, MOBILENO VARCHAR(20) 
, ORDERID VARCHAR(50) 
, ORDERDATE VARCHAR(50)
, ORDER_QTY INT 
, ORDER_DAP DECIMAL 
, ORDER_NETAMT DECIMAL
, PAYMODE VARCHAR( 25) 
, CITY VARCHAR(300) 
, TOTAL_VAT DECIMAL 
, ORDERINTSTATUS INT 
, POID BIGINT 
, SPRID BIGINT 
, PRODUCT_QTY INT 
, SINGLE_DAP DECIMAL 
, TOTAL_DAP DECIMAL 
, TOTAL_SHIP_CH DECIMAL 
, TOTAL_COST DECIMAL 
, PRODUCTTOTALVAT DECIMAL 
,TOTAL_PURCHASE_COST DECIMAL
, PRODUCT_NAME varchar (500)
, PRODQTY varchar (100)
, PROUNIT VARCHAR( 500) 
, PRODCOLOR varchar (100)
, PRODSIZE varchar (100)
, PROD_IMAGES text 
, STATUS VARCHAR( 500) 
, PRODUCTINTSTATUS INT 
, PROCESSBY VARCHAR( 500) 
, PROCESSDATE timestamp 
, PROCESSREMARK VARCHAR(500) 
, INVQTY INT 
, REASON VARCHAR(100) 
, ISCANCELBYMEMBER boolean 
, ISRETURN boolean
, Address text
, PinCode VARCHAR (50)
, CountryName VARCHAR (500)
,JP decimal(18,0)
,BV decimal(18,0)
,SubPrCode varchar(1000),
Approved varchar(1000),
dispatchdate varchar(1000),
ProcurementSLA int,
Orderno varchar(1000),
couriername varchar(1000),
DocketNO varchar(1000),
DateDiff int,
CreatedDate varchar(200),
Packed varchar(200),
Handover varchar(200),
Intransit varchar(200),
Picked varchar(200),
Delivered varchar(200)) ON COMMIT DROP;
  v_query := 'INSERT INTO #TEMP  SELECT ROW_NUMBER() OVER (ORDER BY OM.ORDERDATE DESC) AS ROWNUMBER,
POM.LOGINID,(OM.FNAME+''''+ISNULL(OM.LNAME,'''')) AS NAME,B.CLID AS BRCODE,OM.MOBILENO,
OM.ORDERID,CONVERT(varchar(50) ,OM.ORDERDATE,106),OM.ORDER_QTY,OM.ORDER_DAP,OM.ORDER_NETAMT,OM.PAYMODE,isnull(OM.Sh_City,'''') as CITY,
OM.TOTAL_VAT,OM.INTSTATUS AS ORDERINTSTATUS,POM.POID, CONVERT(BIGINT, POM.SUBPRCODE) AS SPRID,
POM.PRODUCT_QTY, POM.SINGLE_DAP, POM.TOTAL_DAP, POM.TOTAL_SHIP_CH, POM.TOTAL_COST,
POM.TOTAL_VAT AS PRODUCTTOTALVAT,POM.TOTAL_PURCHASE_COST, POM.PRODUCT_NAME, POM.PRODQTY, POM.PROUNIT, 
POM.PRODCOLOR, POM.PRODSIZE, POM.PROD_IMAGES, POM.STATUS, POM.INTSTATUS AS PRODUCTINTSTATUS,
POM.PROCESSBY, POM. PROCESSDATE, POM.PROCESSREMARK,ISNULL(POM.INVQTY,0) AS INVQTY,
POM.REASON,ISNULL(POM.ISCANCELBYMEMBER,0) AS ISCANCELBYMEMBER , ISNULL(POM.ISRETURN,0) AS ISRETURN ,isnull(OM.Address,'''') AS Address,ISNULL(OM.PinCode,'''') AS PinCode,ISNULL(IMS.CountryName,'''') AS CountryName,
isnull(IMSP.PV,0) AS JP,ISNULL(IMSP.BV,0) AS BV,IMSP.SubPrCode,isnull(OCS.Packed,'''') as Approved ,isnull(OCS.Packed+IMSP.ProcurementSLA,'''') as dispatchdate,IMSP.ProcurementSLA,isnull(OCS.orderno,'''') as Orderno,
ISNULL(CM.Carrier_Name,'''') AS couriername,isnull(POM.DocketNO,'''') AS DocketNO,isnull(DATEDIFF(DAY,OM.ORDERDATE,OCS.Delivered),0) AS DateDiff
,convert(varchar, OCS.CreatedDate,106),convert(varchar,OCS.Packed,106),convert(varchar,OCS.Handover,106),
convert(varchar,OCS.Intransit,106),convert(varchar,OCS.Picked,106),convert(varchar,OCS.Delivered,106)
FROM TBL_ORDER_MASTER OM 
LEFT JOIN TBL_PRODUCT_ORDER_MASTER POM ON POM.ORDERID = OM.ORDERID 
--join PORTAL_LOGIN pl on pl.PLID=OM.BranchId 
JOIN TBL_CUSTOMERLOGIN B ON B.LOGINID = OM.LoginId
left join IMS_CustomerAddress IMS on IMS.Id=B.CLID
--left join Portal_Master pma on pma.PMID=pl.PMID
JOIN TBL_DISTRIBUTOR TD ON TD.DID=B.DID
left join IMS_SubProduct IMSP on IMSP.SPRID= POM.SubPrCode
left join tbl_couriermaster CM on CM.CMID=POM.CMID
left join tbl_Order_ConfirmedStaus OCS on OCS.ORDERno=POM.ORDERno
WHERE OM.LOGINID=B.LOGINID AND OM.ORDERID != ''''';
  IF (v_searchfield <> '' AND v_searchvalue <> '') THEN
  IF (v_searchfield = 'MERCHANTCODE') THEN
  v_query := v_query || ' AND B.CODE=''' || v_searchvalue || '''';
  END IF;
  IF (v_searchfield = 'LOGINID') THEN
  v_query := v_query || ' AND OM.LOGINID=''' || v_searchvalue || '''';
  END IF;
  IF (v_searchfield = 'MEMBERNAME') THEN
  v_query := v_query || ' AND ISNULL(B.FNAME,'''')+'' ''+ISNULL(B.LNAME,'''') LIKE ''%' || v_searchvalue || '%''';
  END IF;
  IF (v_searchfield = 'ORDERID') THEN
  v_query := v_query || ' AND OM.ORDERID=''' || v_searchvalue || '''';
  END IF;
  END IF;
  IF (v_company <> '') THEN
  v_query := v_query || ' AND pma.PMID LIKE ''%' || v_company || '%'' ';
  END IF;
  IF (v_poid > 0) THEN
  v_query := v_query || ' AND POM.POID= ''' || CAST(v_poid AS VARCHAR(30)) || ''' ';
  END IF;
  IF ((v_fromdate <> '') AND (v_todate = '')) THEN
  v_query := v_query || ' AND convert(varchar, CONVERT(DATE, OM.ORDERDATE, 105) ) BETWEEN  CONVERT(DATE, ''' || v_fromdate || ''', 105) AND  CONVERT(DATE, DBO.FUN_GETCURRENTDATE(), 105)';
  RETURN QUERY SELECT v_query;
  END IF;
  IF ((v_fromdate = '') AND (v_todate <> '')) THEN
  v_query := v_query || 'AND CONVERT(DATE, OM.ORDERDATE, 105) BETWEEN  CONVERT(DATE, ''' || v_todate || ''', 105) AND  CONVERT(DATE, DBO.FUN_GETCURRENTDATE(), 105)';
  END IF;
  IF ((v_fromdate <> '') AND (v_todate <> '')) THEN
  v_query := v_query || 'AND CONVERT(DATE, OM.ORDERDATE, 105) BETWEEN CONVERT(DATE, ''' || v_fromdate || ''', 105) AND  CONVERT(DATE, ''' || v_todate || ''', 105)';
  END IF;
  IF (v_status <> '') THEN
  v_query := v_query || ' AND ISNULL(OM.STATUS,'''')= ''' || v_status || '''';
  END IF;
  IF (v_statustype <> '') THEN
  IF (v_statustype = 'PENDING') THEN
  v_query := v_query || ' AND POM.STATUS=''PENDING''';
  END IF;
  IF (v_statustype = 'Completed') THEN
  v_query := v_query || ' AND POM.STATUS=''Completed''';
  END IF;
  IF (v_statustype = 'PICK') THEN
  v_query := v_query || ' AND POM.STATUS=''PICK''';
  END IF;
  IF (v_statustype = 'Dispatched') THEN
  v_query := v_query || ' AND POM.STATUS=''Dispatched''';
  END IF;
  IF (v_statustype = 'READY-TO-SHIP') THEN
  RETURN QUERY SELECT 4 AS readyship;
  v_query := v_query || ' AND POM.STATUS=''READYTOSHIP''';
  END IF;
  IF (v_statustype = 'MANIFEST') THEN
  v_query := v_query || ' AND POM.STATUS=''READYTOSHIP''';
  END IF;
  IF (v_statustype = 'Cancel') THEN
  v_query := v_query || ' AND POM.STATUS=''Cancel''';
  END IF;
  IF (v_statustype = 'RETURN') THEN
  v_query := v_query || ' AND POM.STATUS=''RETURN''';
  END IF;
  END IF;
  IF (v_branchid > 0) THEN
  v_query := v_query || ' AND TD.DID=' || CAST(v_branchid AS VARCHAR(20)) || '';
  END IF;
  EXECUTE v_query;
  RAISE NOTICE '%', (v_query);
  RETURN QUERY SELECT * FROM tmp_temp WHERE rownumber BETWEEN v_minindex AND v_maxindex;
  SELECT COUNT(rownumber) INTO v_totalcount FROM tmp_temp;
  DROP TABLE IF EXISTS tmp_temp;
  -- SET option (removed)
  END IF;
  IF (v_mode = 2) THEN
  UPDATE tbl_product_order_master SET status = 'Created', intstatus = 1 WHERE poid = v_poid;
  END IF;
END;
$$;


--
-- Name: usp_new_order_list(integer, integer, character varying, character varying, character varying, character varying, character varying, character varying, bigint, integer, character varying, character varying, bigint, character varying, integer, integer, character varying, character varying, integer, character varying, character varying, character varying, character varying, character varying, integer, integer, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_new_order_list(v_startrowindex integer DEFAULT 1, v_maxrows integer DEFAULT 50, v_searchfield character varying DEFAULT ''::character varying, v_searchvalue character varying DEFAULT ''::character varying, v_fromdate character varying DEFAULT ''::character varying, v_todate character varying DEFAULT ''::character varying, v_status character varying DEFAULT ''::character varying, v_statustype character varying DEFAULT ''::character varying, v_branchid bigint DEFAULT 2, v_totalcount integer DEFAULT 0, v_orderid character varying DEFAULT ''::character varying, v_company character varying DEFAULT ''::character varying, v_poid bigint DEFAULT 0, v_orderno character varying DEFAULT ''::character varying, v_mode integer DEFAULT 1, v_statusid integer DEFAULT 0, v_loginid character varying DEFAULT ''::character varying, v_sortbydispatchorder character varying DEFAULT 'DESC'::character varying, v_orderstatus integer DEFAULT 7, v_statusdate character varying DEFAULT ''::character varying, v_docketno character varying DEFAULT ''::character varying, v_ddlcourier character varying DEFAULT ''::character varying, v_merchantname character varying DEFAULT ''::character varying, v_productname character varying DEFAULT ''::character varying, v_ddlcancelationtype integer DEFAULT 0, v_categoryrelatedto integer DEFAULT 0, v_did integer DEFAULT 0) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_minindex INT;
  v_maxindex INT;
  v_query text;
BEGIN
  v_minindex := (v_startrowindex - 1) * v_maxrows + 1;
  v_maxindex := v_startrowindex * v_maxrows;
  IF (v_mode = 1) THEN
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp (ROWNUMBER BIGINT GENERATED BY DEFAULT AS IDENTITY,                      
LOGINID VARCHAR(100) ,                      
NAME VARCHAR(1000),                       
FULLNAME VARCHAR(1000),            
BRCODE VARCHAR(50),                       
MOBILENO VARCHAR(20),            
EMAILID VARCHAR(100),            
ORDERID VARCHAR(50) ,                      
ORDERDATE varchar(100),                       
ORDER_QTY INT,                       
ORDER_DAP DECIMAL (18,2),                       
ORDER_NETAMT DECIMAL (18,2),                      
PAYMODE VARCHAR(25),                       
CITY VARCHAR(300),                       
TOTAL_VAT DECIMAL (18,2),                       
ORDERINTSTATUS INT,                       
POID BIGINT,                       
SPRID BIGINT,                       
PRODUCT_QTY INT,                       
SINGLE_DAP DECIMAL (18,2),                       
TOTAL_DAP DECIMAL (18,2),                       
TOTAL_SHIP_CH DECIMAL (18,2),                       
TOTAL_COST DECIMAL (18,2),                       
PRODUCTTOTALVAT DECIMAL (18,2),                       
TOTAL_PURCHASE_COST DECIMAL (18,2),                      
PRODUCT_NAME varchar (500),                      
PRODQTY varchar (100),                      
PROUNIT VARCHAR( 500),                       
PRODCOLOR varchar (100),                      
PRODSIZE varchar (100),                      
PROD_IMAGES text,                       
STATUS VARCHAR( 500),                       
PRODUCTINTSTATUS INT ,                      
PROCESSBY VARCHAR(500),                       
PROCESSDATE timestamp,                       
PROCESSREMARK VARCHAR(500),                       
INVQTY INT,                       
REASON VARCHAR(100),                       
ISCANCELBYMEMBER boolean,                       
ISRETURN boolean,                      
Address text,                      
PinCode VARCHAR (50),                      
CountryName VARCHAR (500),                      
JP decimal(18,0),                      
BV decimal(18,0),                      
COMPANYNAME varchar(1000),                      
pmid bigint,                
Orderno varchar(100),                      
Approved varchar(1000),                      
dispatchdate varchar(1000),                      
Producttitle varchar(200),                      
CreatedDate varchar(200),                      
Packed varchar(200),                      
Handover varchar(200),                      
Intransit varchar(200),                      
Picked varchar(200),                      
Delivered varchar(200),                      
Morderid varchar(100),                      
Invoiceno varchar(100),                      
merchantname varchar(1000),                      
CancelledType Int,                      
Canceldate varchar(100),                      
Distributorname varchar(100),                    
PrSKUCODE Varchar(100),                  
PaidViaCashWallet Decimal(18,8),                  
PaidViaCahbackWallet Decimal(18,8),                  
PaidViaKreazVoucher Int,                  
PaidViaOnline Decimal(18,8),    
CODPAYMENT Decimal(18,8)) ON COMMIT DROP;
  v_query := 'INSERT INTO #TEMP SELECT                       
ISNULL(POM.LOGINID,'''') AS LOGINID,isnull(OM.FNAME+''''+ISNULL(OM.LNAME,''''),'''') AS NAME,isnull(MM.FNAME+''''+ISNULL(MM.LNAME,''''),'''') AS FULLNAME,ISNULL(B.CLID,'''') AS BRCODE,                      
ISNULL( OM.MOBILENO,'''') AS MOBILENO,ISNULL(OM.EmailID,'''') AS EMAILID,                      
ISNULL(OM.ORDERID,''''),ISNULL( CONVERT(nvarchar ,OM.ORDERDATE,100),'''') AS ORDERDATE,ISNULL( POM.Product_Qty,0) AS ORDER_QTY,                      
ISNULL( OM.ORDER_DAP,0) AS ORDER_DAP,ISNULL( OM.ORDER_NETAMT,0)AS ORDER_NETAMT,                      
(CASE WHEN OM.PAYMODE=''Payumoney'' THEN ''Wallet'' ELSE OM.PAYMODE END) AS PAYMODE,                      
isnull(OM.Sh_City,'''') AS CITY,                      
ISNULL( OM.TOTAL_VAT,0) AS TOTAL_VAT,ISNULL( OM.INTSTATUS,0) AS ORDERINTSTATUS,                      
ISNULL( POM.POID,0) as POID,ISNULL( CONVERT(BIGINT, POM.SUBPRCODE),0) AS SPRID,                      
ISNULL( POM.PRODUCT_QTY,0) AS PRODUCT_QTY,ISNULL( POM.SINGLE_DAP,0) AS SINGLE_DAP,                       
ISNULL( POM.TOTAL_DAP,0) AS TOTAL_DAP,ISNULL( POM.TOTAL_SHIP_CH,0) AS TOTAL_SHIP_CH,ISNULL( POM.TOTAL_COST,0) AS TOTAL_COST,                   
ISNULL(POM.TOTAL_VAT,0) AS PRODUCTTOTALVAT,ISNULL(POM.TOTAL_PURCHASE_COST,0)as TOTAL_PURCHASE_COST,                       
ISNULL(POM.PRODUCT_NAME,'''') AS PRODUCT_NAME,ISNULL( POM.PRODQTY,'''') as PRODQTY, ISNULL(POM.PROUNIT,'''') AS PROUNIT,                       
ISNULL(POM.PRODCOLOR,'''') AS PRODCOLOR,ISNULL( POM.PRODSIZE,'''') As PRODSIZE,ISNULL(IMSP.ProductImages,'''') AS PROD_IMAGES,                      
ISNULL( POM.STATUS,'''') AS STATUS,ISNULL( POM.INTSTATUS,0) AS PRODUCTINTSTATUS,                      
ISNULL(POM.PROCESSBY,'''') AS PROCESSBY ,ISNULL( POM. PROCESSDATE,'''') as PROCESSDATE,    
ISNULL( POM.PROCESSREMARK,'''') as PROCESSREMARK,                      
ISNULL(POM.INVQTY,0) AS INVQTY,ISNULL(POM.REASON,'''') AS REASON,ISNULL(POM.ISCANCELBYMEMBER,0) AS ISCANCELBYMEMBER,     
ISNULL(POM.ISRETURN,0) AS ISRETURN,ISNULL(OM.Address,'''') AS Address,ISNULL(OM.PinCode,'''') AS PinCode,    
ISNULL(IMS.CountryName,'''') AS CountryName,ISNULL(IMSP.PV,0) AS JP,ISNULL(IMSP.BV,0) AS BV,    
ISNULL( pma.COMPANYNAME,'''') as COMPANYNAME,                       
ISNULL( PMA.PMID,0) AS PMID,ISNULL(POM.Orderno,'''') AS ORDERNO,ISNULL(OCS.PACKED,'''') AS APPROVED ,                      
ISNULL(OCS.PACKED+IMSP.PROCUREMENTSLA,'''') AS DISPATCHDATE,ISNULL( PM.PRODUCTTITLE,'''') as PRODUCTTITLE,                      
CONVERT(VARCHAR, OCS.CREATEDDATE,106),CONVERT(VARCHAR,OCS.PACKED,106),CONVERT(VARCHAR,OCS.HANDOVER,106),                      
CONVERT(VARCHAR,OCS.INTRANSIT,106),CONVERT(VARCHAR,OCS.PICKED,106),CONVERT(VARCHAR,OCS.DELIVERED,106),POM.MORDERID,                      
POM.INVOICENO,ISNULL( PMA.COMPANYNAME,'''') AS MERCHANTNAME,CANCELLATIONTYPE,CONVERT(VARCHAR,OCS.CANCEL,106),                      
DM.COMPANYNAME,IMSP.PRSKUCODE,CASHWALLETUSED,CASHBACKWALLETUSED,VOUCHERWALLETUSED,    
ISNULL(TBL_ONLINEPAYMENTHISTORY.AMOUNT,0),CODPAYMENT                  
FROM TBL_ORDER_MASTER OM                    
LEFT JOIN TBL_ORDERPAYMENT_HISTORY ON TBL_ORDERPAYMENT_HISTORY.ORDERID=OM.ORDERID                    
LEFT JOIN TBL_ORDERONLINEREQUESTS ON TBL_ORDERONLINEREQUESTS.ORDERID=OM.ORDERID                   
LEFT JOIN TBL_ONLINEPAYMENTHISTORY ON TBL_ONLINEPAYMENTHISTORY.REFERNECID=TBL_ORDERONLINEREQUESTS.TRANSACTIONID                   
LEFT JOIN TBL_PRODUCT_ORDER_MASTER POM ON POM.ORDERID = OM.ORDERID                       
LEFT JOIN PORTAL_LOGIN PL ON PL.PLID=POM.PLID                       
LEFT JOIN TBL_CUSTOMERLOGIN B ON B.LOGINID = OM.LOGINID       
LEFT JOIN IMS_CUSTOMERADDRESS IMS ON IMS.ID=B.CLID                      
LEFT JOIN PORTAL_MASTER PMA ON PMA.PMID=PL.PMID                      
LEFT JOIN IMS_SUBPRODUCT IMSP ON IMSP.SPRID= POM.SUBPRCODE                      
LEFT JOIN TBL_ORDER_CONFIRMEDSTAUS OCS ON OCS.ORDERNO=POM.ORDERNO                      
LEFT JOIN IMS_MASTERPRODUCT PM  ON IMSP.MPRID=PM.MPRID                       
LEFT JOIN DISTRIBUTOR_MASTER DM ON B.DID=DM.PLID            
LEFT JOIN [db_affiliate].[Dbo].[MEMBER_MASTER] AS MM ON MM.USERNAME=B.USERNAME                     
WHERE 1=1 ';
  IF (v_merchantname <> '') THEN
  v_query := v_query || ' AND (PMA.COMPANYNAME)=''' || v_merchantname || '''';
  END IF;
  IF (v_productname <> '') THEN
  v_productname := REPLACE(v_productname, '''', '''''');
  v_query := v_query || ' AND POM.Product_Name=''' || v_productname || '''';
  END IF;
  IF (v_orderstatus = 0) THEN
  v_query := v_query || ' AND POM.INTSTATUS=' || CAST(v_orderstatus AS VARCHAR(30)) || '';
  END IF;
  IF (v_orderstatus = 7) THEN
  v_query := v_query || ' AND POM.INTSTATUS=' || CAST(v_orderstatus AS VARCHAR(30)) || '';
  END IF;
  IF (v_orderstatus = 8) THEN
  v_query := v_query || ' AND POM.INTSTATUS=' || CAST(v_orderstatus AS VARCHAR(30)) || '';
  END IF;
  IF (v_orderstatus = 2) THEN
  v_query := v_query || ' AND POM.INTSTATUS=' || CAST(v_orderstatus AS VARCHAR(30)) || '';
  END IF;
  IF (v_orderstatus = 3) THEN
  v_query := v_query || ' AND POM.INTSTATUS=' || CAST(v_orderstatus AS VARCHAR(30)) || '';
  END IF;
  IF (v_searchfield <> '' AND v_searchvalue <> '') THEN
  IF (v_searchfield = 'MERCHANTCODE') THEN
  v_query := v_query || ' AND B.CODE=''' || v_searchvalue || '''';
  END IF;
  IF (v_searchfield = 'LOGINID') THEN
  v_query := v_query || ' AND OM.LOGINID=''' || v_searchvalue || '''';
  END IF;
  IF (v_searchfield = 'MEMBERNAME') THEN
  v_query := v_query || ' AND ISNULL(B.FNAME,'''')+'' ''+ISNULL(B.LNAME,'''') LIKE ''%' || v_searchvalue || '%''';
  END IF;
  IF (v_searchfield = 'ORDERID') THEN
  v_query := v_query || ' AND OM.ORDERID=''' || v_searchvalue || '''';
  END IF;
  END IF;
  IF (v_company <> '') THEN
  v_query := v_query || ' AND pma.PMID LIKE ''%' || v_company || '%'' ';
  END IF;
  IF (v_orderno <> '') THEN
  v_query := v_query || ' AND POM.Morderid = ''' || v_orderno || ''' ';
  END IF;
  IF (v_orderid <> '') THEN
  v_query := v_query || ' AND POM.OrderId = ''' || v_orderid || ''' ';
  END IF;
  IF (v_poid > 0) THEN
  v_query := v_query || ' AND POM.POID= ''' || CAST(v_poid AS VARCHAR(30)) || ''' ';
  END IF;
  IF ((v_fromdate <> '') AND (v_todate = '')) THEN
  v_query := v_query || ' AND convert(varchar, CONVERT(DATE, OM.ORDERDATE, 105) ) BETWEEN  CONVERT(DATE, ''' || v_fromdate || ''', 105) AND  CONVERT(DATE, DBO.FUN_GETCURRENTDATE(), 105)';
  END IF;
  IF ((v_fromdate = '') AND (v_todate <> '')) THEN
  v_query := v_query || 'AND CONVERT(DATE, OM.ORDERDATE, 105) BETWEEN  CONVERT(DATE, ''' || v_todate || ''', 105) AND  CONVERT(DATE, DBO.FUN_GETCURRENTDATE(), 105)';
  END IF;
  IF ((v_fromdate <> '') AND (v_todate <> '')) THEN
  v_query := v_query || 'AND CONVERT(DATE, OM.ORDERDATE, 105) BETWEEN CONVERT(DATE, ''' || v_fromdate || ''', 105) AND  CONVERT(DATE, ''' || v_todate || ''', 105)';
  END IF;
  IF (v_status <> '') THEN
  v_query := v_query || ' AND ISNULL(OM.STATUS,'''')= ''' || v_status || '''';
  END IF;
  IF (v_statustype <> '') THEN
  IF (v_statustype = 'PENDING') THEN
  v_query := v_query || ' AND POM.STATUS=''PENDING''';
  END IF;
  IF (v_statustype = 'Completed') THEN
  v_query := v_query || ' AND POM.STATUS=''Completed''';
  END IF;
  IF (v_statustype = 'PICK') THEN
  v_query := v_query || ' AND POM.STATUS=''PICK''';
  END IF;
  IF (v_statustype = 'Dispatched') THEN
  v_query := v_query || ' AND POM.STATUS=''Dispatched''';
  END IF;
  IF (v_statustype = 'READY-TO-SHIP') THEN
  v_query := v_query || ' AND POM.STATUS=''READYTOSHIP''';
  END IF;
  IF (v_statustype = 'MANIFEST') THEN
  v_query := v_query || ' AND POM.STATUS=''READYTOSHIP''';
  END IF;
  IF (v_statustype = 'Cancel') THEN
  v_query := v_query || ' AND POM.STATUS=''Cancel''';
  END IF;
  IF (v_statustype = 'Refund') THEN
  v_query := v_query || ' AND POM.STATUS=''Refund''';
  END IF;
  END IF;
  IF (v_ddlcancelationtype > 0) THEN
  v_query := v_query || ' AND CancellationType=' || CAST(v_ddlcancelationtype AS VARCHAR(20)) || '';
  END IF;
  IF (v_branchid > 0) THEN
  v_query := v_query || ' AND PL.PLID=' || CAST(v_branchid AS VARCHAR(20)) || '';
  END IF;
  IF (v_sortbydispatchorder <> '') THEN
  v_query := v_query || ' ORDER BY  CONVERT(DATETIME, OM.ORDERDATE, 103)' || v_sortbydispatchorder || '';
  ELSE
  v_query := v_query || ' ORDER BY  CONVERT(DATETIME, OM.ORDERDATE, 103) Desc';
  END IF;
  EXECUTE v_query;
  RAISE NOTICE '%', (v_query);
  RETURN QUERY SELECT * FROM tmp_temp WHERE rownumber BETWEEN v_minindex AND v_maxindex;
  SELECT COUNT(DISTINCT orderid) INTO v_totalcount FROM tmp_temp;
  DROP TABLE IF EXISTS tmp_temp;
  -- SET option (removed)
  END IF;
END;
$$;


--
-- Name: usp_new_order_list_complete(integer, integer, character varying, character varying, character varying, character varying, character varying, character varying, bigint, integer, character varying, bigint, character varying, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_new_order_list_complete(v_startrowindex integer DEFAULT 1, v_maxrows integer DEFAULT 100, v_searchfield character varying DEFAULT ''::character varying, v_searchvalue character varying DEFAULT ''::character varying, v_fromdate character varying DEFAULT ''::character varying, v_todate character varying DEFAULT ''::character varying, v_status character varying DEFAULT ''::character varying, v_statustype character varying DEFAULT ''::character varying, v_branchid bigint DEFAULT 1, v_totalcount integer DEFAULT 0, v_company character varying DEFAULT ''::character varying, v_poid bigint DEFAULT 13231, v_productname character varying DEFAULT ''::character varying, v_mode integer DEFAULT 1) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_minindex INT;
  v_maxindex INT;
  v_query text;
BEGIN
  v_minindex := (v_startrowindex - 1) * v_maxrows + 1;
  v_maxindex := v_startrowindex * v_maxrows;
  IF (v_mode = 1) THEN
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp (ROWNUMBER BIGINT             
, LOGINID VARCHAR( 100)             
, NAME VARCHAR(1000)        
,FULLNAME VARCHAR(1000)         
, BRCODE VARCHAR( 50)             
, MOBILENO VARCHAR(20),    
EMAILID VARCHAR(100)             
, ORDERID VARCHAR(50)             
, ORDERDATE VARCHAR(50)            
, ORDER_QTY INT             
, ORDER_DAP DECIMAL             
, ORDER_NETAMT DECIMAL            
, PAYMODE VARCHAR( 25)             
, CITY VARCHAR(300)             
, TOTAL_VAT DECIMAL             
, ORDERINTSTATUS INT             
, POID BIGINT             
, SPRID BIGINT             
, PRODUCT_QTY INT             
, SINGLE_DAP DECIMAL             
, TOTAL_DAP DECIMAL             
, TOTAL_SHIP_CH DECIMAL             
, TOTAL_COST DECIMAL             
, PRODUCTTOTALVAT DECIMAL             
,TOTAL_PURCHASE_COST DECIMAL            
, PRODUCT_NAME varchar (500)            
, PRODQTY varchar (100)            
, PROUNIT VARCHAR( 500)             
, PRODCOLOR varchar (100)            
, PRODSIZE varchar (100)            
, PROD_IMAGES text             
, STATUS VARCHAR( 500)             
, PRODUCTINTSTATUS INT             
, PROCESSBY VARCHAR( 500)             
, PROCESSDATE timestamp             
, PROCESSREMARK VARCHAR(500)             
, INVQTY INT             
, REASON VARCHAR(100)             
, ISCANCELBYMEMBER boolean             
, ISRETURN boolean            
, Address text            
, PinCode VARCHAR (50)            
, CountryName VARCHAR (500)            
,JP decimal(18,0)            
,BV decimal(18,0)            
,COMPANYNAME varchar(1000)            
,pmid bigint,            
SubPrCode varchar(1000),            
Approved varchar(1000),            
DispatchDate varchar(1000),            
ProcurementSLA int,            
Orderno varchar(1000),            
couriername varchar(1000),            
DocketNO varchar(1000),            
DateDiff int,            
CreatedDate varchar(200),            
Packed varchar(200),            
Handover varchar(200),            
Intransit varchar(200),            
Picked varchar(200),            
Delivered varchar(200),            
Morderid varchar(200),            
Outfordelivery varchar(200),          
PaidViaCashWallet Decimal(18,8),          
PaidViaCahbackWallet Decimal(18,8),          
PaidViaKreazVoucher Int,          
PaidViaOnline Decimal(18,8),        
RefundDate varchar(50),        
RefundDateTime varchar(1000),        
RefundFileImage varchar(1000),        
DESCRIPTIONS varchar(1000)) ON COMMIT DROP;
  v_query := 'INSERT INTO #TEMP  SELECT ROW_NUMBER() OVER (ORDER BY OM.ORDERDATE DESC) AS ROWNUMBER,            
POM.LOGINID,(OM.FNAME+''''+ISNULL(OM.LNAME,'''')) AS NAME,isnull(MM.FNAME+''''+ISNULL(MM.LNAME,''''),'''') AS FULLNAME,ISNULL(OM.EmailID,'''') AS EMAILID, B.CLID AS BRCODE,OM.MOBILENO,            
OM.ORDERID,CONVERT(varchar(50) ,OM.ORDERDATE,106),OM.ORDER_QTY,OM.ORDER_DAP,OM.ORDER_NETAMT,            
(CASE WHEN OM.PAYMODE=''payumoney'' THEN ''Wallet'' ELSE OM.PAYMODE END) as PAYMODE,            
ISNULL(OM.Sh_City,'''') as CITY,            
OM.TOTAL_VAT,OM.INTSTATUS AS ORDERINTSTATUS,POM.POID, CONVERT(BIGINT, POM.SUBPRCODE) AS SPRID,            
POM.PRODUCT_QTY, POM.SINGLE_DAP, POM.TOTAL_DAP, POM.TOTAL_SHIP_CH, POM.TOTAL_COST,            
POM.TOTAL_VAT AS PRODUCTTOTALVAT,POM.TOTAL_PURCHASE_COST, POM.PRODUCT_NAME, POM.PRODQTY, POM.PROUNIT,             
POM.PRODCOLOR, POM.PRODSIZE, POM.PROD_IMAGES,             
(Case WHEN POM.STATUS=''Completed'' Then ''Delivered'' ELSe POM.STATUS END),            
POM.INTSTATUS AS PRODUCTINTSTATUS,            
POM.PROCESSBY, POM. PROCESSDATE, POM.PROCESSREMARK,ISNULL(POM.INVQTY,0) AS INVQTY,            
POM.REASON,ISNULL(POM.ISCANCELBYMEMBER,0) AS ISCANCELBYMEMBER , ISNULL(POM.ISRETURN,0) AS ISRETURN ,isnull(OM.Address,'''') AS Address,ISNULL(OM.PinCode,'''') AS PinCode,ISNULL(IMS.CountryName,'''') AS CountryName,            
ISNULL(IMSP.PV,0) AS JP,ISNULL(IMSP.BV,0) AS BV,PMA.COMPANYNAME,PMA.PMID,IMSP.SUBPRCODE,ISNULL(OCS.PACKED,'''') AS APPROVED ,ISNULL(OCS.PACKED+IMSP.PROCUREMENTSLA,'''') AS DISPATCHDATE,ISNULL(IMSP.PROCUREMENTSLA,0),ISNULL(OCS.ORDERNO,'''') AS ORDERNO,    
  
    
    
    
      
        
        
        
        
ISNULL(CM.CARRIER_NAME,'''') AS COURIERNAME,ISNULL(POM.DOCKETNO,'''') AS DOCKETNO,ISNULL(DATEDIFF(DAY,OM.ORDERDATE,OCS.DELIVERED),0) AS DATEDIFF            
,CONVERT(VARCHAR, OCS.CREATEDDATE,106),CONVERT(VARCHAR,OCS.PACKED,106),CONVERT(VARCHAR,OCS.HANDOVER,106),            
CONVERT(VARCHAR,OCS.INTRANSIT,106),CONVERT(VARCHAR,OCS.PICKED,106),          
CONVERT(VARCHAR,OCS.DELIVERED,106),ISNULL(POM.MORDERID,'''') AS MORDERID,          
CONVERT(VARCHAR,OCS.OUTFORDELIVERY,106),          
ISNULL(CASHWALLETUSED,0),        
ISNULL(CASHBACKWALLETUSED,0),          
ISNULL(VOUCHERWALLETUSED,0),        
ISNULL(TBL_ONLINEPAYMENTHISTORY.AMOUNT,0),CONVERT(varchar(50) ,ISNULL(OCS.RefundDate,''1900-01-01''),106) AS RefundDate,ISNULL(OCS.RefundDate,''1900-01-01'') As RefundDateTime,ISNULL(OCS.RefundFileImage,'''') As  RefundFileImage,ISNULL(OM.DESCRIPTION,''''
  
    
    
    
      
) AS DESCRIPTIONS         
FROM TBL_ORDER_MASTER OM           
LEFT JOIN TBL_ORDERPAYMENT_HISTORY ON TBL_ORDERPAYMENT_HISTORY.ORDERID=OM.ORDERID            
LEFT JOIN TBL_ORDERONLINEREQUESTS ON TBL_ORDERONLINEREQUESTS.ORDERID=OM.ORDERID           
LEFT JOIN TBL_ONLINEPAYMENTHISTORY ON TBL_ONLINEPAYMENTHISTORY.REFERNECID=TBL_ORDERONLINEREQUESTS.TRANSACTIONID             
LEFT JOIN TBL_PRODUCT_ORDER_MASTER POM ON POM.ORDERID = OM.ORDERID             
JOIN PORTAL_LOGIN PL ON PL.PLID=POM.PLID JOIN TBL_CUSTOMERLOGIN B ON B.LOGINID = OM.LOGINID            
LEFT JOIN IMS_CUSTOMERADDRESS IMS ON IMS.ID=B.CLID            
LEFT JOIN PORTAL_MASTER PMA ON PMA.PMID=PL.PMID            
LEFT JOIN IMS_SUBPRODUCT IMSP ON IMSP.SPRID= POM.SUBPRCODE            
LEFT JOIN TBL_COURIERMASTER CM ON CM.CMID=POM.CMID            
LEFT JOIN TBL_ORDER_CONFIRMEDSTAUS OCS ON OCS.ORDERNO=POM.ORDERNO       
LEFT JOIN [Db_Affiliate].[Dbo].[MEMBER_MASTER] AS MM ON MM.USERNAME=B.USERNAME          
WHERE OM.LOGINID=B.LOGINID AND OM.ORDERID != ''''';
  RAISE NOTICE '%', v_query;
  IF (v_searchfield <> '' AND v_searchvalue <> '') THEN
  IF (v_searchfield = 'MERCHANTCODE') THEN
  v_query := v_query || ' AND B.CODE=''' || v_searchvalue || '''';
  END IF;
  IF (v_searchfield = 'LOGINID') THEN
  v_query := v_query || ' AND OM.LOGINID=''' || v_searchvalue || '''';
  END IF;
  IF (v_searchfield = 'MEMBERNAME') THEN
  v_query := v_query || ' AND ISNULL(B.FNAME,'''')+'' ''+ISNULL(B.LNAME,'''') LIKE ''%' || v_searchvalue || '%''';
  END IF;
  IF (v_searchfield = 'ORDERID') THEN
  v_query := v_query || ' AND OM.ORDERID=''' || v_searchvalue || '''';
  END IF;
  END IF;
  IF (v_company <> '') THEN
  v_query := v_query || ' AND pma.PMID LIKE ''%' || v_company || '%'' ';
  END IF;
  IF (v_poid > 0) THEN
  v_query := v_query || ' AND POM.POID= ''' || CAST(v_poid AS VARCHAR(30)) || ''' ';
  END IF;
  IF ((v_fromdate <> '') AND (v_todate = '')) THEN
  v_query := v_query || ' AND convert(varchar, CONVERT(DATE, OM.ORDERDATE, 105) ) BETWEEN  CONVERT(DATE, ''' || v_fromdate || ''', 105) AND  CONVERT(DATE, DBO.FUN_GETCURRENTDATE(), 105)';
  END IF;
  IF ((v_fromdate = '') AND (v_todate <> '')) THEN
  v_query := v_query || 'AND CONVERT(DATE, OM.ORDERDATE, 105) BETWEEN  CONVERT(DATE, ''' || v_todate || ''', 105) AND  CONVERT(DATE, DBO.FUN_GETCURRENTDATE(), 105)';
  END IF;
  IF ((v_fromdate <> '') AND (v_todate <> '')) THEN
  v_query := v_query || 'AND CONVERT(DATE, OM.ORDERDATE, 105) BETWEEN CONVERT(DATE, ''' || v_fromdate || ''', 105) AND  CONVERT(DATE, ''' || v_todate || ''', 105)';
  END IF;
  IF (v_status <> '') THEN
  v_query := v_query || ' AND ISNULL(OM.STATUS,'''')= ''' || v_status || '''';
  END IF;
  IF (v_statustype <> '') THEN
  IF (v_statustype = 'PENDING') THEN
  v_query := v_query || ' AND POM.STATUS=''PENDING''';
  END IF;
  IF (v_statustype = 'Completed') THEN
  v_query := v_query || ' AND POM.STATUS=''Completed''';
  END IF;
  IF (v_statustype = 'PICK') THEN
  v_query := v_query || ' AND POM.STATUS=''PICK''';
  END IF;
  IF (v_statustype = 'Dispatched') THEN
  v_query := v_query || ' AND POM.STATUS=''Dispatched''';
  END IF;
  IF (v_statustype = 'READY-TO-SHIP') THEN
  RETURN QUERY SELECT 4 AS readyship;
  v_query := v_query || ' AND POM.STATUS=''READYTOSHIP''';
  END IF;
  IF (v_statustype = 'MANIFEST') THEN
  v_query := v_query || ' AND POM.STATUS=''READYTOSHIP''';
  END IF;
  IF (v_statustype = 'Cancel') THEN
  v_query := v_query || ' AND POM.STATUS=''Cancel''';
  END IF;
  IF (v_statustype = 'Refund') THEN
  v_query := v_query || ' AND POM.STATUS=''Refund''';
  END IF;
  END IF;
  IF (v_branchid > 0) THEN
  v_query := v_query || ' AND pl.PLID=' || CAST(v_branchid AS VARCHAR(20)) || '';
  END IF;
  EXECUTE v_query;
  RAISE NOTICE '%', (v_query);
  RETURN QUERY SELECT * FROM tmp_temp WHERE rownumber BETWEEN v_minindex AND v_maxindex;
  SELECT COUNT(rownumber) INTO v_totalcount FROM tmp_temp;
  DROP TABLE IF EXISTS tmp_temp;
  -- SET option (removed)
  END IF;
  IF (v_mode = 2) THEN
  UPDATE tbl_product_order_master SET status = 'Created', intstatus = 1 WHERE poid = v_poid;
  END IF;
END;
$$;


--
-- Name: usp_new_order_list_distributor(integer, integer, character varying, character varying, character varying, character varying, character varying, character varying, bigint, integer, character varying, character varying, bigint, character varying, integer, integer, character varying, character varying, integer, character varying, character varying, character varying, character varying, character varying, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_new_order_list_distributor(v_startrowindex integer DEFAULT 1, v_maxrows integer DEFAULT 100, v_searchfield character varying DEFAULT ''::character varying, v_searchvalue character varying DEFAULT ''::character varying, v_fromdate character varying DEFAULT ''::character varying, v_todate character varying DEFAULT ''::character varying, v_status character varying DEFAULT ''::character varying, v_statustype character varying DEFAULT ''::character varying, v_branchid bigint DEFAULT 1, v_totalcount integer DEFAULT 0, v_orderid character varying DEFAULT ''::character varying, v_company character varying DEFAULT ''::character varying, v_poid bigint DEFAULT 10445, v_orderno character varying DEFAULT ''::character varying, v_mode integer DEFAULT 2, v_statusid integer DEFAULT 0, v_loginid character varying DEFAULT ''::character varying, v_sortbydispatchorder character varying DEFAULT ''::character varying, v_orderstatus integer DEFAULT 0, v_statusdate character varying DEFAULT ''::character varying, v_docketno character varying DEFAULT ''::character varying, v_ddlcourier character varying DEFAULT ''::character varying, v_merchantname character varying DEFAULT ''::character varying, v_productname character varying DEFAULT ''::character varying, v_ddlcancelationtype integer DEFAULT 0) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_minindex INT;
  v_maxindex INT;
  v_query text;
  v_statusname varchar(100);
  v_statusname1 varchar(50);
  v_statusname2 varchar(50);
  v_statusname5 varchar(50);
  v_statusname6 varchar(50);
BEGIN
  v_minindex := (v_startrowindex - 1) * v_maxrows + 1;
  v_maxindex := v_startrowindex * v_maxrows;
  IF (v_mode = 1) THEN
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp (ROWNUMBER BIGINT,
LOGINID VARCHAR(100) ,
NAME VARCHAR(1000), 
BRCODE VARCHAR(50), 
MOBILENO VARCHAR(20), 
ORDERID VARCHAR(50) ,
ORDERDATE varchar(100), 
ORDER_QTY INT, 
ORDER_DAP DECIMAL, 
ORDER_NETAMT DECIMAL,
PAYMODE VARCHAR(25), 
CITY VARCHAR(300), 
TOTAL_VAT DECIMAL, 
ORDERINTSTATUS INT, 
POID BIGINT, 
SPRID BIGINT, 
PRODUCT_QTY INT, 
SINGLE_DAP DECIMAL, 
TOTAL_DAP DECIMAL, 
TOTAL_SHIP_CH DECIMAL, 
TOTAL_COST DECIMAL, 
PRODUCTTOTALVAT DECIMAL, 
TOTAL_PURCHASE_COST DECIMAL,
PRODUCT_NAME varchar (500),
PRODQTY varchar (100),
PROUNIT VARCHAR( 500), 
PRODCOLOR varchar (100),
PRODSIZE varchar (100),
PROD_IMAGES text, 
STATUS VARCHAR( 500), 
PRODUCTINTSTATUS INT ,
PROCESSBY VARCHAR(500), 
PROCESSDATE timestamp, 
PROCESSREMARK VARCHAR(500), 
INVQTY INT, 
REASON VARCHAR(100), 
ISCANCELBYMEMBER boolean, 
ISRETURN boolean,
Address text,
PinCode VARCHAR (50),
CountryName VARCHAR (500),
JP decimal(18,0),
BV decimal(18,0),
Orderno varchar(100),
Approved varchar(1000),
dispatchdate varchar(1000),
Producttitle varchar(200),
CreatedDate varchar(200),
Packed varchar(200),
Handover varchar(200),
Intransit varchar(200),
Picked varchar(200),
Delivered varchar(200),MLMWALLET decimal(18,2),CUSTOMERWALLET decimal(18,2),InvoiceNo varchar(300)) ON COMMIT DROP;
  IF (v_sortbydispatchorder = 'sortbyorderasc') THEN
  v_query := 'INSERT INTO #TEMP      SELECT ROW_NUMBER() OVER (ORDER BY OM.ORDERDATE asc) AS ROWNUMBER,
ISNULL(POM.LOGINID,'''') as LOGINID,isnull(OM.FNAME+''''+ISNULL(OM.LNAME,''''),'''') AS NAME,ISNULL(B.CLID,'''') AS BRCODE,
ISNULL( OM.MOBILENO,'''') as MOBILENO,
ISNULL(OM.ORDERID,''''),ISNULL( CONVERT(nvarchar ,OM.ORDERDATE,100),'''') as ORDERDATE,ISNULL( POM.Product_Qty,0) as ORDER_QTY,
ISNULL( OM.ORDER_DAP,0) as ORDER_DAP,ISNULL( OM.ORDER_NETAMT,0)as ORDER_NETAMT,ISNULL( OM.PAYMODE,'''') as PAYMODE,
isnull(OM.Sh_City,'''') as CITY,
ISNULL( OM.TOTAL_VAT,0) as TOTAL_VAT,ISNULL( OM.INTSTATUS,0) AS ORDERINTSTATUS,
ISNULL( POM.POID,0) as POID,ISNULL( CONVERT(BIGINT, POM.SUBPRCODE),0) AS SPRID,
ISNULL( POM.PRODUCT_QTY,0) as PRODUCT_QTY,ISNULL( POM.SINGLE_DAP,0) as SINGLE_DAP, 
ISNULL( POM.TOTAL_DAP,0) as TOTAL_DAP,ISNULL( POM.TOTAL_SHIP_CH,0) as TOTAL_SHIP_CH,ISNULL( POM.TOTAL_COST,0) as TOTAL_COST,
ISNULL(POM.TOTAL_VAT,0) AS PRODUCTTOTALVAT,ISNULL(POM.TOTAL_PURCHASE_COST,0)as TOTAL_PURCHASE_COST, 
ISNULL(POM.PRODUCT_NAME,'''') as PRODUCT_NAME,ISNULL( POM.PRODQTY,'''') as PRODQTY, ISNULL(POM.PROUNIT,'''') as PROUNIT, 
ISNULL(POM.PRODCOLOR,'''') as PRODCOLOR,ISNULL( POM.PRODSIZE,'''') as PRODSIZE,ISNULL( POM.PROD_IMAGES,'''') as PROD_IMAGES,
ISNULL( POM.STATUS,'''') as STATUS,ISNULL( POM.INTSTATUS,0) AS PRODUCTINTSTATUS,
ISNULL(POM.PROCESSBY,'''') as PROCESSBY ,ISNULL( POM. PROCESSDATE,'''') as PROCESSDATE,ISNULL( POM.PROCESSREMARK,'''') as PROCESSREMARK,
ISNULL(POM.INVQTY,0) AS INVQTY,
ISNULL(POM.REASON,'''') as REASON,ISNULL(POM.ISCANCELBYMEMBER,0) AS ISCANCELBYMEMBER , ISNULL(POM.ISRETURN,0) AS ISRETURN ,
isnull(OM.Address,'''') AS Address,ISNULL(OM.PinCode,'''') AS PinCode,ISNULL(IMS.CountryName,'''') AS CountryName,
isnull(IMSP.PV,0) AS JP,ISNULL(IMSP.BV,0) AS BV, 
,isnull(POM.Orderno,'''') as Orderno,isnull(OCS.packed,'''') as Approved ,
isnull(OCS.packed+IMSP.ProcurementSLA,'''') as dispatchdate,ISNULL( PM.PRODUCTTITLE,'''') as PRODUCTTITLE,
convert(varchar, OCS.CreatedDate,106),convert(varchar,OCS.Packed,106),convert(varchar,OCS.Handover,106),
convert(varchar,OCS.Intransit,106),convert(varchar,OCS.Picked,106),convert(varchar,OCS.Delivered,106),
	isnull(PD.MLMWALLET,0) as MLMWALLET,isnull(PD.CUSTOMERWALLET,0) as CUSTOMERWALLET,POM.InvoiceNo
FROM TBL_ORDER_MASTER  OM   
LEFT JOIN TBL_PRODUCT_ORDER_MASTER POM ON POM.ORDERID = OM.ORDERID 
--LEFT join PORTAL_LOGIN pl on pl.PLID=OM.BranchId 
JOIN TBL_CUSTOMERLOGIN B ON B.LOGINID = OM.LoginId
left join IMS_CustomerAddress IMS on IMS.Id=B.CLID
JOIN TBL_DISTRIBUTOR TD ON TD.DID=B.DID
--left join Portal_Master pma on pma.PMID=pl.PMID
left join IMS_SubProduct IMSP on IMSP.SPRID= POM.SubPrCode
left join tbl_Order_ConfirmedStaus OCS on OCS.orderno=POM.Orderno
LEFT JOIN IMS_MASTERPRODUCT PM  ON   IMSP.MPRID=PM.MPRID 
LEFT join TBL_ORDERPAYMENTSDETAILS as PD on PD.ORDERID=OM.ORDERID 
WHERE OM.LOGINID=B.LOGINID  and OM.ORDERID  != ''''';
  ELSE
  v_query := 'INSERT INTO #TEMP      SELECT ROW_NUMBER() OVER (ORDER BY OM.ORDERDATE desc) AS ROWNUMBER,
ISNULL(POM.LOGINID,'''') as LOGINID,isnull(OM.FNAME+''''+ISNULL(OM.LNAME,''''),'''') AS NAME,ISNULL(B.CLID,'''') AS BRCODE,
ISNULL( OM.MOBILENO,'''') as MOBILENO,
ISNULL(OM.ORDERID,''''),ISNULL( CONVERT(nvarchar ,OM.ORDERDATE,100),'''') as ORDERDATE,ISNULL( POM.Product_Qty,0) as ORDER_QTY,
ISNULL( OM.ORDER_DAP,0) as ORDER_DAP,ISNULL( OM.ORDER_NETAMT,0)as ORDER_NETAMT,ISNULL( OM.PAYMODE,'''') as PAYMODE,
isnull(OM.Sh_City,'''') as CITY,
ISNULL( OM.TOTAL_VAT,0) as TOTAL_VAT,ISNULL( OM.INTSTATUS,0) AS ORDERINTSTATUS,
ISNULL( POM.POID,0) as POID,ISNULL( CONVERT(BIGINT, POM.SUBPRCODE),0) AS SPRID,
ISNULL( POM.PRODUCT_QTY,0) as PRODUCT_QTY,ISNULL( POM.SINGLE_DAP,0) as SINGLE_DAP, 
ISNULL( POM.TOTAL_DAP,0) as TOTAL_DAP,ISNULL( POM.TOTAL_SHIP_CH,0) as TOTAL_SHIP_CH,ISNULL( POM.TOTAL_COST,0) as TOTAL_COST,
ISNULL(POM.TOTAL_VAT,0) AS PRODUCTTOTALVAT,ISNULL(POM.TOTAL_PURCHASE_COST,0)as TOTAL_PURCHASE_COST, 
ISNULL(POM.PRODUCT_NAME,'''') as PRODUCT_NAME,ISNULL( POM.PRODQTY,'''') as PRODQTY, ISNULL(POM.PROUNIT,'''') as PROUNIT, 
ISNULL(POM.PRODCOLOR,'''') as PRODCOLOR,ISNULL( POM.PRODSIZE,'''') as PRODSIZE,ISNULL( POM.PROD_IMAGES,'''') as PROD_IMAGES,
ISNULL( POM.STATUS,'''') as STATUS,ISNULL( POM.INTSTATUS,0) AS PRODUCTINTSTATUS,
ISNULL(POM.PROCESSBY,'''') as PROCESSBY ,ISNULL( POM. PROCESSDATE,'''') as PROCESSDATE,ISNULL( POM.PROCESSREMARK,'''') as PROCESSREMARK,
ISNULL(POM.INVQTY,0) AS INVQTY,
ISNULL(POM.REASON,'''') as REASON,ISNULL(POM.ISCANCELBYMEMBER,0) AS ISCANCELBYMEMBER , ISNULL(POM.ISRETURN,0) AS ISRETURN ,
isnull(OM.Address,'''') AS Address,ISNULL(OM.PinCode,'''') AS PinCode,ISNULL(IMS.CountryName,'''') AS CountryName,
isnull(IMSP.PV,0) AS JP,ISNULL(IMSP.BV,0) AS BV, 
isnull(POM.Orderno,'''') as Orderno,isnull(OCS.packed,'''') as Approved ,
isnull(OCS.packed+IMSP.ProcurementSLA,'''') as dispatchdate,ISNULL( PM.PRODUCTTITLE,'''') as PRODUCTTITLE
,convert(varchar, OCS.CreatedDate,106),convert(varchar,OCS.Packed,106),convert(varchar,OCS.Handover,106),
convert(varchar,OCS.Intransit,106),convert(varchar,OCS.Picked,106),convert(varchar,OCS.Delivered,106),
	isnull(PD.MLMWALLET,0) as MLMWALLET,isnull(PD.CUSTOMERWALLET,0) as CUSTOMERWALLET,POM.InvoiceNo
FROM TBL_ORDER_MASTER  OM   
LEFT JOIN TBL_PRODUCT_ORDER_MASTER POM ON POM.ORDERID = OM.ORDERID 
--join PORTAL_LOGIN pl on pl.PLID=OM.BranchId 
JOIN TBL_CUSTOMERLOGIN B ON B.LOGINID = OM.LoginId
left join IMS_CustomerAddress IMS on IMS.Id=B.CLID
JOIN TBL_DISTRIBUTOR TD ON TD.DID=B.DID
--left join Portal_Master pma on pma.PMID=pl.PMID
left join IMS_SubProduct IMSP on IMSP.SPRID= POM.SubPrCode
left join tbl_Order_ConfirmedStaus OCS on OCS.orderno=POM.orderno
left JOIN IMS_MASTERPRODUCT PM  ON   IMSP.MPRID=PM.MPRID 
left join TBL_ORDERPAYMENTSDETAILS as PD on PD.ORDERID=OM.ORDERID 
WHERE OM.LOGINID=B.LOGINID AND OM.ORDERID  != ''''';
  END IF;
  IF (v_merchantname <> '') THEN
  v_query := v_query || ' AND (PMA.COMPANYNAME)=''' || v_merchantname || '''';
  END IF;
  IF (v_productname <> '') THEN
  v_query := v_query || ' AND POM.Product_Name=''' || v_productname || '''';
  END IF;
  IF (v_orderstatus = 0) THEN
  v_query := v_query || ' AND POM.IntStatus=' || CAST(v_orderstatus AS VARCHAR(30)) || '';
  END IF;
  IF (v_orderstatus = 7) THEN
  v_query := v_query || ' AND POM.IntStatus=' || CAST(v_orderstatus AS VARCHAR(30)) || '';
  END IF;
  IF (v_orderstatus = 2) THEN
  v_query := v_query || ' AND POM.IntStatus=' || CAST(v_orderstatus AS VARCHAR(30)) || '';
  END IF;
  IF (v_orderstatus = 3) THEN
  v_query := v_query || ' AND POM.IntStatus=' || CAST(v_orderstatus AS VARCHAR(30)) || '';
  END IF;
  IF (v_searchfield <> '' AND v_searchvalue <> '') THEN
  IF (v_searchfield = 'MERCHANTCODE') THEN
  v_query := v_query || ' AND B.CODE=''' || v_searchvalue || '''';
  END IF;
  IF (v_searchfield = 'LOGINID') THEN
  v_query := v_query || ' AND OM.LOGINID=''' || v_searchvalue || '''';
  END IF;
  IF (v_searchfield = 'MEMBERNAME') THEN
  v_query := v_query || ' AND ISNULL(B.FNAME,'''')+'' ''+ISNULL(B.LNAME,'''') LIKE ''%' || v_searchvalue || '%''';
  END IF;
  IF (v_searchfield = 'ORDERID') THEN
  v_query := v_query || ' AND OM.ORDERID=''' || v_searchvalue || '''';
  END IF;
  END IF;
  IF (v_company <> '') THEN
  v_query := v_query || ' AND pma.PMID LIKE ''%' || v_company || '%'' ';
  END IF;
  IF (v_orderno <> '') THEN
  v_query := v_query || ' AND POM.Orderno = ''' || v_orderno || ''' ';
  END IF;
  IF (v_orderid <> '') THEN
  v_query := v_query || ' AND POM.OrderId = ''' || v_orderid || ''' ';
  END IF;
  IF (v_poid > 0) THEN
  v_query := v_query || ' AND POM.POID= ''' || CAST(v_poid AS VARCHAR(30)) || ''' ';
  END IF;
  IF ((v_fromdate <> '') AND (v_todate = '')) THEN
  v_query := v_query || ' AND convert(varchar, CONVERT(DATE, OM.ORDERDATE, 105) ) BETWEEN  CONVERT(DATE, ''' || v_fromdate || ''', 105) AND  CONVERT(DATE, DBO.FUN_GETCURRENTDATE(), 105)';
  END IF;
  IF ((v_fromdate = '') AND (v_todate <> '')) THEN
  v_query := v_query || 'AND CONVERT(DATE, OM.ORDERDATE, 105) BETWEEN  CONVERT(DATE, ''' || v_todate || ''', 105) AND  CONVERT(DATE, DBO.FUN_GETCURRENTDATE(), 105)';
  END IF;
  IF ((v_fromdate <> '') AND (v_todate <> '')) THEN
  v_query := v_query || 'AND CONVERT(DATE, OM.ORDERDATE, 105) BETWEEN CONVERT(DATE, ''' || v_fromdate || ''', 105) AND  CONVERT(DATE, ''' || v_todate || ''', 105)';
  END IF;
  IF (v_status <> '') THEN
  v_query := v_query || ' AND ISNULL(OM.STATUS,'''')= ''' || v_status || '''';
  END IF;
  IF (v_statustype <> '') THEN
  IF (v_statustype = 'PENDING') THEN
  v_query := v_query || ' AND POM.STATUS=''PENDING''';
  END IF;
  IF (v_statustype = 'Completed') THEN
  v_query := v_query || ' AND POM.STATUS=''Completed''';
  END IF;
  IF (v_statustype = 'PICK') THEN
  v_query := v_query || ' AND POM.STATUS=''PICK''';
  END IF;
  IF (v_statustype = 'Dispatched') THEN
  v_query := v_query || ' AND POM.STATUS=''Dispatched''';
  END IF;
  IF (v_statustype = 'READY-TO-SHIP') THEN
  v_query := v_query || ' AND POM.STATUS=''READYTOSHIP''';
  END IF;
  IF (v_statustype = 'MANIFEST') THEN
  v_query := v_query || ' AND POM.STATUS=''READYTOSHIP''';
  END IF;
  IF (v_statustype = 'Cancel') THEN
  v_query := v_query || ' AND POM.STATUS=''Cancel''';
  END IF;
  IF (v_statustype = 'RETURN') THEN
  v_query := v_query || ' AND POM.STATUS=''RETURN''';
  END IF;
  END IF;
  IF (v_branchid > 0) THEN
  v_query := v_query || ' AND TD.DID=' || CAST(v_branchid AS VARCHAR(20)) || '';
  END IF;
  EXECUTE v_query;
  RAISE NOTICE '%', (v_query);
  RETURN QUERY SELECT * FROM tmp_temp WHERE rownumber BETWEEN v_minindex AND v_maxindex;
  SELECT COUNT(rownumber) INTO v_totalcount FROM tmp_temp;
  DROP TABLE IF EXISTS tmp_temp;
  -- SET option (removed)
  END IF;
  IF (v_mode = 2) THEN
  SELECT statusname INTO v_statusname FROM orderstatusmaster WHERE osid = v_statusid;
  UPDATE tbl_order_confirmedstaus SET packed = TO_TIMESTAMP(v_statusdate, 'DD/MM/YYYY') WHERE orderid = v_orderid AND customerid = v_loginid;
  UPDATE tbl_product_order_master SET intstatus = v_statusid, status = v_statusname WHERE poid = v_poid;
  END IF;
  IF (v_mode = 3) THEN
  SELECT statusname INTO v_statusname1 FROM orderstatusmaster WHERE osid = v_statusid;
  UPDATE tbl_order_confirmedstaus SET handover = TO_TIMESTAMP(v_statusdate, 'DD/MM/YYYY') WHERE orderid = v_orderid AND customerid = v_loginid;
  UPDATE tbl_product_order_master SET intstatus = v_statusid, status = v_statusname1 WHERE poid = v_poid;
  END IF;
  IF (v_mode = 4) THEN
  SELECT statusname INTO v_statusname2 FROM orderstatusmaster WHERE osid = v_statusid;
  UPDATE tbl_order_confirmedstaus SET intransit = TO_TIMESTAMP(v_statusdate, 'DD/MM/YYYY') WHERE orderid = v_orderid AND customerid = v_loginid;
  UPDATE tbl_product_order_master SET intstatus = v_statusid, docketno = v_docketno, cmid = v_ddlcourier WHERE poid = v_poid;
  END IF;
  IF (v_mode = 5) THEN
  SELECT statusname INTO v_statusname5 FROM orderstatusmaster WHERE osid = v_statusid;
  UPDATE tbl_order_confirmedstaus SET picked = TO_TIMESTAMP(v_statusdate, 'DD/MM/YYYY') WHERE orderid = v_orderid AND customerid = v_loginid;
  UPDATE tbl_product_order_master SET intstatus = v_statusid, status = v_statusname5 WHERE poid = v_poid;
  END IF;
  IF (v_mode = 6) THEN
  SELECT statusname INTO v_statusname6 FROM orderstatusmaster WHERE osid = v_statusid;
  UPDATE tbl_order_confirmedstaus SET delivered = TO_TIMESTAMP(v_statusdate, 'DD/MM/YYYY') WHERE orderid = v_orderid AND customerid = v_loginid;
  UPDATE tbl_product_order_master SET intstatus = v_statusid, status = v_statusname6 WHERE poid = v_poid;
  END IF;
END;
$$;


--
-- Name: usp_new_order_list_f(integer, integer, character varying, character varying, character varying, character varying, character varying, character varying, bigint, integer, character varying, character varying, bigint, character varying, integer, integer, character varying, character varying, integer, character varying, character varying, character varying, character varying, character varying, integer, integer, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_new_order_list_f(v_startrowindex integer DEFAULT 1, v_maxrows integer DEFAULT 100, v_searchfield character varying DEFAULT ''::character varying, v_searchvalue character varying DEFAULT ''::character varying, v_fromdate character varying DEFAULT ''::character varying, v_todate character varying DEFAULT ''::character varying, v_status character varying DEFAULT ''::character varying, v_statustype character varying DEFAULT ''::character varying, v_branchid bigint DEFAULT 2, v_totalcount integer DEFAULT 0, v_orderid character varying DEFAULT ''::character varying, v_company character varying DEFAULT ''::character varying, v_poid bigint DEFAULT 0, v_orderno character varying DEFAULT ''::character varying, v_mode integer DEFAULT 1, v_statusid integer DEFAULT 0, v_loginid character varying DEFAULT ''::character varying, v_sortbydispatchorder character varying DEFAULT 'DESC'::character varying, v_orderstatus integer DEFAULT 8, v_statusdate character varying DEFAULT ''::character varying, v_docketno character varying DEFAULT ''::character varying, v_ddlcourier character varying DEFAULT ''::character varying, v_merchantname character varying DEFAULT ''::character varying, v_productname character varying DEFAULT ''::character varying, v_ddlcancelationtype integer DEFAULT 0, v_categoryrelatedto integer DEFAULT 1, v_did integer DEFAULT 0) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_minindex INT;
  v_maxindex INT;
  v_query text;
BEGIN
  v_minindex := (v_startrowindex - 1) * v_maxrows + 1;
  v_maxindex := v_startrowindex * v_maxrows;
  IF (v_mode = 1) THEN
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp (ROWNUMBER BIGINT GENERATED BY DEFAULT AS IDENTITY,          
LOGINID VARCHAR(100) ,          
NAME VARCHAR(1000),           
BRCODE VARCHAR(50),           
MOBILENO VARCHAR(20),           
ORDERID VARCHAR(50) ,          
ORDERDATE varchar(100),           
ORDER_QTY INT,           
ORDER_DAP DECIMAL (18,2),           
ORDER_NETAMT DECIMAL (18,2),          
PAYMODE VARCHAR(25),           
CITY VARCHAR(300),           
TOTAL_VAT DECIMAL (18,2),           
ORDERINTSTATUS INT,           
POID BIGINT,           
SPRID BIGINT,           
PRODUCT_QTY INT,           
SINGLE_DAP DECIMAL (18,2),           
TOTAL_DAP DECIMAL (18,2),           
TOTAL_SHIP_CH DECIMAL (18,2),           
TOTAL_COST DECIMAL (18,2),           
PRODUCTTOTALVAT DECIMAL (18,2),           
TOTAL_PURCHASE_COST DECIMAL (18,2),          
PRODUCT_NAME varchar (500),          
PRODQTY varchar (100),          
PROUNIT VARCHAR( 500),           
PRODCOLOR varchar (100),          
PRODSIZE varchar (100),          
PROD_IMAGES text,           
STATUS VARCHAR( 500),           
PRODUCTINTSTATUS INT ,          
PROCESSBY VARCHAR(500),           
PROCESSDATE timestamp,           
PROCESSREMARK VARCHAR(500),           
INVQTY INT,           
REASON VARCHAR(100),           
ISCANCELBYMEMBER boolean,           
ISRETURN boolean,          
Address text,          
PinCode VARCHAR (50),          
CountryName VARCHAR (500),          
JP decimal(18,0),          
BV decimal(18,0),          
COMPANYNAME varchar(1000),          
Pmid bigint,          
Orderno varchar(100),          
Approved varchar(1000),          
DispatchDate varchar(1000),          
Producttitle varchar(200),          
CreatedDate varchar(200),          
Packed varchar(200),          
Handover varchar(200),          
Intransit varchar(200),          
Picked varchar(200),          
Delivered varchar(200),          
Morderid varchar(100),          
Invoiceno varchar(100),          
merchantname varchar(100),          
merchantemailid varchar(100),          
merchantmobile varchar(100),          
CancelledType int,          
Canceldate varchar(100),          
Distributorname varchar(100),          
Remarks Varchar(200),          
ReturnDate varchar(200),          
ExchangeDate varchar(200),          
RefundedRemark varchar(200),          
RefundedDate varchar(200),          
ALLIMAGES Varchar(100),          
INVAmount Decimal(18,8),          
EURAmount Decimal(18,8),          
INVPer Decimal(18,8),          
EURPer Decimal(18,8) ,  
FULLNAME varchar(100),          
EMAILID varchar(100)) ON COMMIT DROP;
  v_query := 'INSERT INTO #TEMP SELECT           
ISNULL(POM.LOGINID,'''') as LOGINID,isnull(OM.FNAME+''''+ISNULL(OM.LNAME,''''),'''') AS NAME,ISNULL(B.CLID,'''') AS BRCODE,          
ISNULL( OM.MOBILENO,'''') as MOBILENO,          
ISNULL(OM.ORDERID,''''),ISNULL( CONVERT(nvarchar ,OM.ORDERDATE,100),'''') as ORDERDATE,ISNULL( POM.Product_Qty,0) as ORDER_QTY,          
ISNULL( OM.ORDER_DAP,0) as ORDER_DAP,ISNULL( OM.ORDER_NETAMT,0)as ORDER_NETAMT,          
(CASE WHEN OM.PAYMODE=''payumoney'' THEN ''Wallet'' ELSE OM.PAYMODE END) as PAYMODE,          
isnull(OM.Sh_City,'''') as CITY,          
ISNULL( OM.TOTAL_VAT,0) as TOTAL_VAT,ISNULL( OM.INTSTATUS,0) AS ORDERINTSTATUS,          
ISNULL( POM.POID,0) as POID,ISNULL( CONVERT(BIGINT, POM.SUBPRCODE),0) AS SPRID,          
ISNULL( POM.PRODUCT_QTY,0) as PRODUCT_QTY,ISNULL( POM.SINGLE_DAP,0) as SINGLE_DAP,           
ISNULL( POM.TOTAL_DAP,0) as TOTAL_DAP,ISNULL( POM.TOTAL_SHIP_CH,0) as TOTAL_SHIP_CH,ISNULL( POM.TOTAL_COST,0) as TOTAL_COST,          
ISNULL(POM.TOTAL_VAT,0) AS PRODUCTTOTALVAT,ISNULL(POM.TOTAL_PURCHASE_COST,0)as TOTAL_PURCHASE_COST,           
ISNULL(POM.PRODUCT_NAME,'''') as PRODUCT_NAME,ISNULL( POM.PRODQTY,'''') as PRODQTY, ISNULL(POM.PROUNIT,'''') as PROUNIT,           
ISNULL(POM.PRODCOLOR,'''') as PRODCOLOR,ISNULL( POM.PRODSIZE,'''') as PRODSIZE,ISNULL(IMSP.ProductImages,'''') as PROD_IMAGES,          
ISNULL( POM.STATUS,'''') as STATUS,ISNULL( POM.INTSTATUS,0) AS PRODUCTINTSTATUS,          
ISNULL(POM.PROCESSBY,'''') as PROCESSBY ,ISNULL( POM. PROCESSDATE,'''') as PROCESSDATE,ISNULL( POM.PROCESSREMARK,'''') as PROCESSREMARK,          
ISNULL(POM.INVQTY,0) AS INVQTY,          
ISNULL(POM.REASON,'''') as REASON,ISNULL(POM.ISCANCELBYMEMBER,0) AS ISCANCELBYMEMBER , ISNULL(POM.ISRETURN,0) AS ISRETURN ,          
ISNULL(OM.ADDRESS,'''') AS ADDRESS,ISNULL(OM.PINCODE,'''') AS PINCODE,ISNULL(IMS.COUNTRYNAME,'''') AS COUNTRYNAME,          
ISNULL(IMSP.PV,0) AS JP,ISNULL(IMSP.BV,0) AS BV,ISNULL( PMA.COMPANYNAME,'''') AS COMPANYNAME,           
ISNULL( PMA.PMID,0) AS PMID,ISNULL(POM.ORDERNO,'''') AS ORDERNO,ISNULL(OCS.PACKED,'''') AS APPROVED ,          
ISNULL(OCS.PACKED+IMSP.PROCUREMENTSLA,'''') AS DISPATCHDATE,ISNULL( PM.PRODUCTTITLE,'''') AS PRODUCTTITLE,          
CONVERT(VARCHAR, OCS.CREATEDDATE,106),CONVERT(VARCHAR,OCS.PACKED,106),CONVERT(VARCHAR,OCS.HANDOVER,106),          
CONVERT(VARCHAR,OCS.INTRANSIT,106),CONVERT(VARCHAR,OCS.PICKED,106),CONVERT(VARCHAR,OCS.DELIVERED,106),POM.MORDERID,          
POM.INVOICENO,ISNULL( PMA.COMPANYNAME,'''') AS MERCHANTNAME,          
ISNULL(PL.EMAILID,'''') AS EMAILID,ISNULL(PL.PHONE,'''') AS PHONE,CANCELLATIONTYPE,CONVERT(VARCHAR,OCS.CANCEL,106),          
DM.COMPANYNAME,0 As REMARKS,OCS.RETURNDATE,OCS.EXCHANGEDATE,OCS.ACTIONREMARKS,OCS.REFUNDDATE,OCS.ALLIMAGES,          
0 As INVAmount,0 As EURAmount,0 As INVPer,0 As EURPer,ISNULL( MM.FNAME,'''') as FULLNAME,ISNULL( MM.EmailID,'''') as EMAILID          
FROM TBL_ORDER_MASTER  OM             
LEFT JOIN TBL_PRODUCT_ORDER_MASTER POM ON POM.ORDERID = OM.ORDERID           
LEFT JOIN PORTAL_LOGIN PL ON PL.PLID=POM.PLID           
LEFT JOIN TBL_CUSTOMERLOGIN B ON B.LOGINID = OM.LOGINID          
LEFT JOIN IMS_CUSTOMERADDRESS IMS ON IMS.ID=B.CLID          
LEFT JOIN PORTAL_MASTER PMA ON PMA.PMID=PL.PMID          
LEFT JOIN IMS_SUBPRODUCT IMSP ON IMSP.SPRID= POM.SUBPRCODE          
LEFT JOIN TBL_ORDER_CONFIRMEDSTAUS OCS ON OCS.ORDERNO=POM.ORDERNO          
LEFT JOIN IMS_MASTERPRODUCT PM  ON IMSP.MPRID=PM.MPRID           
INNER JOIN TBL_MAIN_CATEGORY MC ON MC.MAINCATID=PM.MAINCATEGORYID          
LEFT JOIN DISTRIBUTOR_MASTER DM ON B.DID=DM.PLID  
LEFT JOIN [Db_Affiliate].[Dbo].[MEMBER_MASTER] AS MM ON MM.USERNAME=B.USERNAME  
WHERE 1=1  ';
  IF (v_merchantname <> '') THEN
  v_query := v_query || ' AND (PMA.COMPANYNAME)=''' || v_merchantname || '''';
  END IF;
  IF (v_productname <> '') THEN
  v_productname := REPLACE(v_productname, '''', '''''');
  v_query := v_query || ' AND POM.PRODUCT_NAME=''' || v_productname || '''';
  END IF;
  IF (v_poid = 0) THEN
  IF (v_orderstatus = 0) THEN
  v_query := v_query || ' AND POM.INTSTATUS=' || CAST(v_orderstatus AS VARCHAR(30)) || '';
  END IF;
  IF (v_orderstatus = 7) THEN
  v_query := v_query || ' AND POM.INTSTATUS=' || CAST(v_orderstatus AS VARCHAR(30)) || '';
  END IF;
  IF (v_orderstatus = 8) THEN
  v_query := v_query || ' AND POM.INTSTATUS=' || CAST(v_orderstatus AS VARCHAR(30)) || '';
  END IF;
  IF (v_orderstatus = 9) THEN
  v_query := v_query || ' AND POM.INTSTATUS=' || CAST(v_orderstatus AS VARCHAR(30)) || '';
  END IF;
  IF (v_orderstatus = 10) THEN
  v_query := v_query || ' AND POM.INTSTATUS=' || CAST(v_orderstatus AS VARCHAR(30)) || '';
  END IF;
  IF (v_orderstatus = 2) THEN
  v_query := v_query || ' AND POM.INTSTATUS=' || CAST(v_orderstatus AS VARCHAR(30)) || '';
  END IF;
  IF (v_orderstatus = 3) THEN
  v_query := v_query || ' AND POM.INTSTATUS=' || CAST(v_orderstatus AS VARCHAR(30)) || '';
  END IF;
  END IF;
  IF (v_searchfield <> '' AND v_searchvalue <> '') THEN
  IF (v_searchfield = 'MERCHANTCODE') THEN
  v_query := v_query || ' AND B.CODE=''' || v_searchvalue || '''';
  END IF;
  IF (v_searchfield = 'LOGINID') THEN
  v_query := v_query || ' AND OM.LOGINID=''' || v_searchvalue || '''';
  END IF;
  IF (v_searchfield = 'MEMBERNAME') THEN
  v_query := v_query || ' AND ISNULL(B.FNAME,'''')+'' ''+ISNULL(B.LNAME,'''') LIKE ''%' || v_searchvalue || '%''';
  END IF;
  IF (v_searchfield = 'ORDERID') THEN
  v_query := v_query || ' AND OM.ORDERID=''' || v_searchvalue || '''';
  END IF;
  END IF;
  IF (v_company <> '') THEN
  v_query := v_query || ' AND PMA.PMID LIKE ''%' || v_company || '%'' ';
  END IF;
  IF (v_orderno <> '') THEN
  v_query := v_query || ' AND POM.MORDERID = ''' || v_orderno || ''' ';
  END IF;
  IF (v_orderid <> '') THEN
  v_query := v_query || ' AND POM.ORDERID = ''' || v_orderid || ''' ';
  END IF;
  IF (v_poid > 0) THEN
  v_query := v_query || ' AND POM.POID= ''' || CAST(v_poid AS VARCHAR(30)) || ''' ';
  END IF;
  IF ((v_fromdate <> '') AND (v_todate = '')) THEN
  v_query := v_query || ' AND CONVERT(VARCHAR, CONVERT(DATE, OM.ORDERDATE, 105) ) BETWEEN  CONVERT(DATE, ''' || v_fromdate || ''', 105) AND  CONVERT(DATE, DBO.FUN_GETCURRENTDATE(), 105)';
  END IF;
  IF ((v_fromdate = '') AND (v_todate <> '')) THEN
  v_query := v_query || 'AND CONVERT(DATE, OM.ORDERDATE, 105) BETWEEN  CONVERT(DATE, ''' || v_todate || ''', 105) AND  CONVERT(DATE, DBO.FUN_GETCURRENTDATE(), 105)';
  END IF;
  IF ((v_fromdate <> '') AND (v_todate <> '')) THEN
  v_query := v_query || 'AND CONVERT(DATE, OM.ORDERDATE, 105) BETWEEN CONVERT(DATE, ''' || v_fromdate || ''', 105) AND  CONVERT(DATE, ''' || v_todate || ''', 105)';
  END IF;
  IF (v_status <> '') THEN
  v_query := v_query || ' AND ISNULL(OM.STATUS,'''')= ''' || v_status || '''';
  END IF;
  IF (v_statustype <> '') THEN
  IF (v_statustype = 'PENDING') THEN
  v_query := v_query || ' AND POM.STATUS=''PENDING''';
  END IF;
  IF (v_statustype = 'Completed') THEN
  v_query := v_query || ' AND POM.STATUS=''Completed''';
  END IF;
  IF (v_statustype = 'PICK') THEN
  v_query := v_query || ' AND POM.STATUS=''PICK''';
  END IF;
  IF (v_statustype = 'DISPATCHED') THEN
  v_query := v_query || ' AND POM.STATUS=''Dispatched''';
  END IF;
  IF (v_statustype = 'READY-TO-SHIP') THEN
  v_query := v_query || ' AND POM.STATUS=''READYTOSHIP''';
  END IF;
  IF (v_statustype = 'MANIFEST') THEN
  v_query := v_query || ' AND POM.STATUS=''READYTOSHIP''';
  END IF;
  IF (v_statustype = 'Cancel') THEN
  v_query := v_query || ' AND POM.STATUS=''CANCEL''';
  END IF;
  IF (v_statustype = 'RETURN') THEN
  v_query := v_query || ' AND POM.STATUS=''RETURN''';
  END IF;
  IF (v_statustype = 'EXCHANGE') THEN
  v_query := v_query || ' AND POM.STATUS=''EXCHANGE''';
  END IF;
  IF (v_statustype = 'REFUND') THEN
  v_query := v_query || ' AND POM.STATUS=''REFUND''';
  END IF;
  END IF;
  IF (v_ddlcancelationtype > 0) THEN
  v_query := v_query || ' AND CANCELLATIONTYPE=' || CAST(v_ddlcancelationtype AS VARCHAR(20)) || '';
  END IF;
  IF (v_branchid > 0) THEN
  v_query := v_query || ' AND PL.PLID=' || CAST(v_branchid AS VARCHAR(20)) || '';
  END IF;
  IF (v_did > 0) THEN
  v_query := v_query || (' AND PL.PLID In(SELECT PLID FROM PORTAL_MASTER WHERE CID IN(SELECT CID FROM DISTRIBUTOR_MASTER WHERE PLID=' || CAST(v_did AS VARCHAR(5)) || '))');
  END IF;
  IF (v_sortbydispatchorder <> '') THEN
  v_query := v_query || ' ORDER BY  CONVERT(DATETIME, OM.ORDERDATE, 103)' || v_sortbydispatchorder || '';
  ELSE
  v_query := v_query || ' ORDER BY  CONVERT(DATETIME, OM.ORDERDATE, 103) Desc';
  END IF;
  RAISE NOTICE '%', v_query;
  EXECUTE v_query;
  DROP TABLE IF EXISTS tmp_tempcod;
  CREATE TEMP TABLE tmp_tempcod (ORDERNUMBERN VARCHAR(100),        
MYCODTRANSACTIONID VARCHAR(500),        
ORDERIDN Varchar(100)) ON COMMIT DROP;
  INSERT INTO tmp_tempcod SELECT ordernumber, mycodtransactionid, '' FROM tbl_payment_gateway_call_login WHERE mycodtransactionid <> '' GROUP BY ordernumber, mycodtransactionid;
  UPDATE t1 SET orderidn = t2.orderid FROM tmp_tempcod AS t1 INNER JOIN tbl_orderonlinerequests AS t2 ON t1.ordernumbern = t2.transactionid;
  RETURN QUERY SELECT rownumber, loginid, name, brcode, mobileno, orderid, orderdate, order_qty, order_dap, order_netamt, paymode, city, total_vat, orderintstatus, poid, sprid, product_qty, single_dap, total_dap, total_ship_ch, total_cost, producttotalvat, total_purchase_cost, product_name, prodqty, prounit, prodcolor, prodsize, prod_images, status, productintstatus, processby, processdate, processremark, invqty, reason, iscancelbymember, isreturn, address, pincode, countryname, jp, bv, companyname, pmid, orderno, approved, dispatchdate, producttitle, createddate, packed, handover, intransit, picked, delivered, morderid, invoiceno, merchantname, merchantemailid, merchantmobile, cancelledtype, canceldate, distributorname, remarks, returndate, exchangedate, refundedremark, refundeddate, allimages, invamount, euramount, invper, eurper, COALESCE(mycodtransactionid, '') AS mycodtransactionid, fullname, emailid FROM tmp_temp LEFT JOIN tmp_tempcod ON tmp_tempcod.orderidn = tmp_temp.orderid WHERE rownumber BETWEEN v_minindex AND v_maxindex;
  DROP TABLE IF EXISTS tmp_tempcod;
  SELECT COUNT(DISTINCT orderid) INTO v_totalcount FROM tmp_temp;
  DROP TABLE IF EXISTS tmp_temp;
  -- SET option (removed)
  END IF;
END;
$$;


--
-- Name: usp_newacceptreferralprogram(character varying, bigint, character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_newacceptreferralprogram(v_sponser character varying DEFAULT ''::character varying, v_plid bigint DEFAULT 0, INOUT v_result character varying DEFAULT ''::character varying) RETURNS character varying
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_loginid VARCHAR(100);
  v_password VARCHAR(100);
  v_currencysymbol VARCHAR(50);
  v_spounsertype int;
  v_cid INT;
  v_plidref VARCHAR(100);
  v_username VARCHAR(100);
  v_ipaddress VARCHAR(100);
  v_intromemid text;
  v_placementmemid VARCHAR(50);
  v_placementregnoside smallint;
  v_fname VARCHAR(100);
  v_mname VARCHAR(100);
  v_lname VARCHAR(100);
  v_gender smallint;
  v_dob VARCHAR(50);
  v_email VARCHAR(100);
  v_mobile VARCHAR(20);
  v_sid INT;
  v_statename VARCHAR(250);
  v_ctid INT;
  v_cityname VARCHAR(200);
  v_address text;
  v_pincode VARCHAR(20);
  v_panno VARCHAR(100);
  v_trpassword VARCHAR(100);
  v_ipadd VARCHAR(100);
  v_epinnumber VARCHAR(100);
  v_nomineename VARCHAR(100);
  v_nomineerelation VARCHAR(100);
  v_sessionloginid VARCHAR(50);
  v_kitid Int;
  v_strresult VARCHAR(200);
  v_application_formno text;
  v_referalcode varchar(10);
  v_introrefid Int;
  v_sponsorids text;
  v_placementids text;
  v_side Int;
  v_title text;
  v_desigantion text;
  v_imagename text;
  v_resultacceptreferralprogram text;
BEGIN
  -- BEGIN TRAN (removed)
  v_result := 'success';
  IF EXISTS(SELECT 1 FROM member_master WHERE plid = v_plid AND COALESCE(isreferralaccepted, 0) = 1) THEN
  v_result := 'Your account is already activated in referral program !';
  -- COMMIT (removed)
  RETURN;
  END IF;
  IF (v_sponser <> '') THEN
  IF NOT EXISTS(SELECT 1 FROM member_master WHERE username = v_sponser AND COALESCE(isreferralaccepted, 0) = 0) THEN
  v_result := 'Invalid Referral code !';
  -- COMMIT (removed)
  RETURN;
  END IF;
  END IF;
  IF EXISTS(SELECT 1 FROM member_master WHERE plid = v_plid) THEN
  UPDATE member_master SET isreferralaccepted = 1, referralaccepteddate = dbo.FUN_GETCURRENTDATE() WHERE plid = v_plid;
  UPDATE portal_login SET isreferralaccepted = 1, referralaccepteddate = dbo.FUN_GETCURRENTDATE() WHERE plid = v_plid;
  ELSE
  v_spounsertype := 0;
  v_intromemid := '';
  v_placementmemid := '';
  v_placementregnoside := 0;
  v_fname := '';
  v_mname := '';
  v_lname := '';
  v_gender := 0;
  v_dob := '';
  v_email := '';
  v_mobile := '';
  v_sid := 0;
  v_statename := '';
  v_ctid := 0;
  v_cityname := '';
  v_address := '';
  v_pincode := '';
  v_panno := '';
  v_trpassword := '';
  v_ipadd := '';
  v_epinnumber := '';
  v_nomineename := '';
  v_nomineerelation := '';
  v_sessionloginid := '';
  v_kitid := 0;
  v_strresult := '';
  v_application_formno := '';
  v_referalcode := '';
  v_introrefid := 0;
  v_sponsorids := '';
  v_placementids := '';
  v_side := 0;
  v_title := '';
  v_desigantion := '';
  v_imagename := '';
  SELECT loginid, password, password, intro_refid, username, currencysymbol, cid, ipaddress, COALESCE(sp_firstname, ''), COALESCE(sp_lastname, ''), phone, loginid, COALESCE(refral_id, ''), sponserid, placementid, side, title, designation, imagename, COALESCE(spounsertype, 0) INTO v_loginid, v_password, v_trpassword, v_plidref, v_username, v_currencysymbol, v_cid, v_ipaddress, v_fname, v_lname, v_mobile, v_email, v_referalcode, v_sponsorids, v_placementids, v_side, v_title, v_desigantion, v_imagename, v_spounsertype FROM portal_login_temp WHERE username = (SELECT username FROM portal_login WHERE plid = v_plid) LIMIT 1;
  SELECT v_strresult INTO v_strresult FROM dbo.usp_insert_member_master(v_maxplid => v_plid, v_intromemid => v_intromemid, v_placementmemid => v_placementmemid, v_placementregnoside => v_placementregnoside, v_username => v_username, v_fname => v_fname, v_mname => v_mname, v_lname => v_lname, v_gender => v_gender, v_dob => v_dob, v_email => v_email, v_mobile => v_mobile, v_sid => v_sid, v_statename => v_statename, v_ctid => v_ctid, v_cityname => v_cityname, v_cid => v_cid, v_address => v_address, v_pincode => v_pincode, v_panno => v_panno, v_password => v_password, v_trpassword => v_trpassword, v_ipadd => v_ipadd, v_epinnumber => v_epinnumber, v_nomineename => v_nomineename, v_nomineerelation => v_nomineerelation, v_sessionloginid => v_sessionloginid, v_kitid => v_kitid, v_strresult => v_strresult, v_application_formno => v_application_formno, v_loginid => v_loginid);
  SELECT v_result INTO v_result FROM dbo.usp_acceptreferralprogram(v_sponser => '', v_plid => v_resultacceptreferralprogram, v_result => v_result);
  UPDATE member_master SET isreferralaccepted = 1, referralaccepteddate = dbo.FUN_GETCURRENTDATE() WHERE plid = v_plid;
  UPDATE portal_login SET isreferralaccepted = 1, referralaccepteddate = dbo.FUN_GETCURRENTDATE() WHERE plid = v_plid;
  END IF;
  IF (0 <> 0) THEN
  -- ROLLBACK (removed)
  v_result := 'Some error occurred, Please try again !';
  RETURN;
  END IF;
  -- COMMIT (removed)
END;
$$;


--
-- Name: usp_newmaster_foremail(integer, integer, character varying, character varying, character varying, integer, integer, integer, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_newmaster_foremail(v_mode integer DEFAULT 1, v_isgiven integer DEFAULT 2, v_requestedby character varying DEFAULT ''::character varying, v_fromdate character varying DEFAULT ''::character varying, v_todate character varying DEFAULT ''::character varying, v_pageno integer DEFAULT 1, v_pagesize integer DEFAULT 100, v_tuepmid integer DEFAULT 0, v_intresult integer DEFAULT 0) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_query text;
  v_minindex INT;
  v_maxindex INT;
  v_noofrec INT;
  v_diff INT;
BEGIN
  v_minindex := 0;
  v_maxindex := 0;
  v_noofrec := 0;
  v_diff := 0;
  v_minindex := ((v_pageno - 1) * v_pagesize) + 1;
  v_maxindex := (v_pageno * v_pagesize);
  IF (v_mode = 1) THEN
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp (ROWNUMBER INT,
		TUEPMID INT,
		PURCHASEDDATE varchar(100),
		PACKAGENAME varchar(100),
		PACKAGEFEATUREDESCRIPTION varchar(100),
		AMOUNT varchar(20),
		COMPANYNAME varchar(100),
		ISGIVEN INT,
		LOGINID VarChar(200)) ON COMMIT DROP;
  v_query := ' INSERT INTO #TEMP SELECT ROW_NUMBER() OVER(ORDER BY PURCHASEDDATE DESC)AS ROWNUMBER,
	TUEPMID,CONVERT(VARCHAR(11),PURCHASEDDATE,106)AS PURCHASEDDATE,PACKAGENAME,	
	(CASE WHEN PACKAGEFEATUREDESCRIPTION='''' THEN ''N/A'' ELSE 
	PACKAGEFEATUREDESCRIPTION END)
	AS PACKAGEFEATUREDESCRIPTION,AMOUNT,COMPANYNAME,ISGIVEN,PL.LOGINID
	FROM TBL_USEREMAILPACKMASTER TUEPM INNER JOIN TBL_EMAILPACKMASTER TEPM ON 
	TUEPM.TEPMID=TEPM.TEPMID INNER JOIN PORTAL_MASTER PM ON PM.PLID=TUEPM.PLID
	Inner Join Portal_Login Pl On Pl.Plid=PM.PLID WHERE TUEPMID>0 ';
  IF (v_isgiven <> 2) THEN
  v_query := v_query || (' AND ISGIVEN = ' || CAST(v_isgiven AS VARCHAR(2)) || ' ');
  END IF;
  IF (v_requestedby <> '') THEN
  v_query := v_query || (' AND PL.LOGINID LIKE ''%' || v_requestedby || '%'' ');
  END IF;
  IF (v_fromdate <> '' OR v_todate <> '') THEN
  IF (v_fromdate <> '') THEN
  v_query := v_query || (' AND CONVERT(DATE,PURCHASEDDATE,103) >= CONVERT(DATE,''' || v_fromdate || ''',103) ');
  END IF;
  IF (v_todate <> '') THEN
  v_query := v_query || (' AND CONVERT(DATE,PURCHASEDDATE,103) <= CONVERT(DATE,''' || v_todate || ''',103) ');
  END IF;
  ELSE
  IF (v_fromdate <> '' AND v_todate <> '') THEN
  v_query := v_query || (' AND CONVERT(DATE,PURCHASEDDATE,103) BETWEEN CONVERT(DATE,''' || v_fromdate || ''',103) 
AND CONVERT(DATE,''' || v_todate || ''',103) ');
  END IF;
  END IF;
  EXECUTE v_query;
  RETURN QUERY SELECT rownumber, tuepmid, CAST(TO_CHAR(purchaseddate, 'DD TMMon YYYY') AS VARCHAR(11)) AS purchaseddate, packagename, (CASE WHEN packagefeaturedescription = '' THEN 'N/A' ELSE packagefeaturedescription END) AS packagefeaturedescription, amount, companyname, (CASE WHEN isgiven = 0 THEN 'Not Given' ELSE 'Given' END) AS isgiven, loginid FROM tmp_temp WHERE rownumber BETWEEN v_minindex AND v_maxindex;
  SELECT COUNT(1) INTO v_noofrec FROM tmp_temp;
  SELECT (v_noofrec - ((v_noofrec / v_pagesize) * v_pagesize)) INTO v_diff;
  IF (v_noofrec > 0) THEN
  IF (v_diff > 0) THEN
  RETURN QUERY SELECT ((v_noofrec / v_pagesize) + 1) AS pages;
  ELSE
  RETURN QUERY SELECT (v_noofrec / v_pagesize) AS pages;
  END IF;
  ELSE
  RETURN QUERY SELECT 1 AS pages;
  END IF;
  DROP TABLE IF EXISTS tmp_temp;
  END IF;
  IF (v_mode = 2) THEN
  UPDATE tbl_useremailpackmaster SET isgiven = (CASE WHEN isgiven = 0 THEN 1 END) WHERE tuepmid = v_tuepmid;
  v_intresult := 1;
  END IF;
END;
$$;


--
-- Name: usp_newmaster_forsms(integer, integer, character varying, character varying, character varying, integer, integer, integer, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_newmaster_forsms(v_mode integer DEFAULT 1, v_isgiven integer DEFAULT 2, v_requestedby character varying DEFAULT ''::character varying, v_fromdate character varying DEFAULT ''::character varying, v_todate character varying DEFAULT ''::character varying, v_pageno integer DEFAULT 1, v_pagesize integer DEFAULT 100, v_tuspmid integer DEFAULT 0, v_intresult integer DEFAULT 0) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_query text;
  v_minindex INT;
  v_maxindex INT;
  v_noofrec INT;
  v_diff INT;
BEGIN
  v_minindex := 0;
  v_maxindex := 0;
  v_noofrec := 0;
  v_diff := 0;
  v_minindex := ((v_pageno - 1) * v_pagesize) + 1;
  v_maxindex := (v_pageno * v_pagesize);
  IF (v_mode = 1) THEN
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp (ROWNUMBER INT,
		TUSPMID INT,
		PURCHASEDDATE varchar(100),
		PACKAGENAME varchar(100),
		PACKAGEFEATUREDESCRIPTION varchar(100),
		AMOUNT varchar(20),
		COMPANYNAME varchar(100),
		ISGIVEN INT,
		LOGINID VarChar(200)) ON COMMIT DROP;
  v_query := ' INSERT INTO #TEMP SELECT ROW_NUMBER() OVER(ORDER BY PURCHASEDDATE DESC)AS ROWNUMBER,
TUSPMID,CONVERT(VARCHAR(11),PURCHASEDDATE,106) AS PURCHASEDDATE,
PACKAGENAME,(CASE WHEN PACKAGEFEATUREDESCRIPTION='''' THEN ''N/A'' ELSE 
PACKAGEFEATUREDESCRIPTION END)AS PACKAGEFEATUREDESCRIPTION,
AMOUNT,COMPANYNAME,ISGIVEN,PL.LOGINID FROM TBL_USERSMSPACKMASTER TUSPM INNER JOIN 
TBL_SMSPACKMASTER TSPM	ON TUSPM.TSPMID=TSPM.TSPMID INNER JOIN 
 PORTAL_MASTER PM ON PM.PLID=TUSPM.PLID Inner Join Portal_Login Pl On Pl.Plid=PM.PLID  WHERE  TUSPMID>0 ';
  IF (v_isgiven <> 2) THEN
  v_query := v_query || (' AND ISGIVEN = ' || CAST(v_isgiven AS VARCHAR(2)) || ' ');
  END IF;
  IF (v_requestedby <> '') THEN
  v_query := v_query || (' AND PL.LOGINID LIKE ''%' || v_requestedby || '%'' ');
  END IF;
  IF (v_fromdate <> '' OR v_todate <> '') THEN
  IF (v_fromdate <> '') THEN
  v_query := v_query || (' AND CONVERT(DATE,PURCHASEDDATE,103) >= CONVERT(DATE,''' || v_fromdate || ''',103) ');
  END IF;
  IF (v_todate <> '') THEN
  v_query := v_query || (' AND CONVERT(DATE,PURCHASEDDATE,103) <= CONVERT(DATE,''' || v_todate || ''',103) ');
  END IF;
  ELSE
  IF (v_fromdate <> '' AND v_todate <> '') THEN
  v_query := v_query || ('  AND CONVERT(DATE,PURCHASEDDATE,103) BETWEEN CONVERT(DATE,''' || v_fromdate || ''',103) AND CONVERT(DATE,''' || v_todate || ''',103) ');
  END IF;
  END IF;
  EXECUTE v_query;
  RETURN QUERY SELECT rownumber, tuspmid, CAST(TO_CHAR(purchaseddate, 'DD TMMon YYYY') AS VARCHAR(11)) AS purchaseddate, packagename, (CASE WHEN packagefeaturedescription = '' THEN 'N/A' ELSE packagefeaturedescription END) AS packagefeaturedescription, amount, companyname, (CASE WHEN isgiven = 0 THEN 'Not Given' ELSE 'Given' END) AS isgiven, loginid FROM tmp_temp WHERE rownumber BETWEEN v_minindex AND v_maxindex;
  SELECT COUNT(1) INTO v_noofrec FROM tmp_temp;
  SELECT (v_noofrec - ((v_noofrec / v_pagesize) * v_pagesize)) INTO v_diff;
  IF (v_noofrec > 0) THEN
  IF (v_diff > 0) THEN
  RETURN QUERY SELECT ((v_noofrec / v_pagesize) + 1) AS pages;
  ELSE
  RETURN QUERY SELECT (v_noofrec / v_pagesize) AS pages;
  END IF;
  ELSE
  RETURN QUERY SELECT 1 AS pages;
  END IF;
  DROP TABLE IF EXISTS tmp_temp;
  END IF;
  IF (v_mode = 2) THEN
  UPDATE tbl_usersmspackmaster SET isgiven = (CASE WHEN isgiven = 0 THEN 1 WHEN isgiven = 1 THEN 0 END) WHERE tuspmid = v_tuspmid;
  v_intresult := 1;
  END IF;
END;
$$;


--
-- Name: usp_noof_hits_find_keyword_id_and_exists(character varying, integer, integer, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_noof_hits_find_keyword_id_and_exists(v_keywordname character varying, INOUT v_kmid integer, INOUT v_intresult integer, INOUT v_catid integer) RETURNS record
    LANGUAGE plpgsql
    AS $$
BEGIN
  v_intresult := 0;
  IF EXISTS(SELECT kmid FROM keyword_master WHERE LTRIM(RTRIM(keywordname)) = v_keywordname) AND NOT EXISTS(SELECT catid FROM product_category WHERE LTRIM(RTRIM(catname)) = v_keywordname) THEN
  SELECT kmid INTO v_kmid FROM keyword_master WHERE LTRIM(RTRIM(keywordname)) = v_keywordname;
  v_intresult := 1;
  v_catid := 0;
  END IF;
  IF NOT EXISTS(SELECT kmid FROM keyword_master WHERE LTRIM(RTRIM(keywordname)) = v_keywordname) AND EXISTS(SELECT catid FROM product_category WHERE LTRIM(RTRIM(catname)) = v_keywordname) THEN
  SELECT catid INTO v_catid FROM product_category WHERE LTRIM(RTRIM(catname)) = v_keywordname;
  v_intresult := 1;
  v_kmid := 0;
  END IF;
  IF (0 > 0) THEN
  v_intresult := 2;
  RETURN;
  END IF;
END;
$$;


--
-- Name: usp_noofhits(integer, integer, character varying, integer, character varying, character varying, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_noofhits(v_keyid integer DEFAULT 0, v_ctid integer DEFAULT 0, v_areaname character varying DEFAULT ''::character varying, INOUT v_intresult integer DEFAULT 0, v_ipaddress character varying DEFAULT NULL::character varying, v_pincode character varying DEFAULT ''::character varying, INOUT v_cidin integer DEFAULT 0) RETURNS record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_aid INT;
  v_cid INT;
  v_sid INT;
  v_catid INT;
  v_scatid INT;
  v_rowcount INT;
BEGIN
  -- SET option (removed)
  v_intresult := 0;
  IF (v_ctid <> 0 AND v_areaname <> '') THEN
  IF EXISTS(SELECT aid FROM area_master WHERE LTRIM(RTRIM(areaname)) = v_areaname AND ctid = v_ctid) THEN
  IF (v_pincode = '') THEN
  DROP TABLE IF EXISTS tmp_tempareaid;
  CREATE TEMP TABLE tmp_tempareaid (ROWNUMBER INT GENERATED BY DEFAULT AS IDENTITY,

					AREAIDTEMP INT) ON COMMIT DROP;
  INSERT INTO tmp_tempareaid SELECT aid FROM area_master WHERE ctid = v_ctid AND areaname = v_areaname;
  SELECT COUNT(rownumber) INTO v_rowcount FROM tmp_tempareaid;
