--

CREATE FUNCTION dbo.usp_noofhitsfinaly(v_yearcurrent integer DEFAULT 0, INOUT v_intresult integer DEFAULT 0) RETURNS integer
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_sid int;
  v_pctid int;
  v_keywordid int;
  v_keywordrate numeric(19,4);
  v_noofhits bigint;
  v_symbol varchar(100);
  v_totalnoofhits bigint;
  v_price numeric(19,4);
  v_areaname VARCHAR(100);
  v_mhid bigint;
  v_cid int;
  v_ctid int;
  v_aid int;
  v_totalhits int;
  v_catid varchar(100);
  v_totalcount int;
  v_avghits int;
  dailykeywird CURSOR FOR SELECT mhid FROM tblnumberofhitsmonthly WHERE EXTRACT(YEAR FROM CAST(hitmonth AS DATE)) = v_yearcurrent;
BEGIN
  -- BEGIN TRAN (removed)
  -- SET option (removed)
  v_intresult := 0;
  DROP TABLE IF EXISTS tmp_temp111;
  CREATE TEMP TABLE tmp_temp111 (keywordid int NULL,

	cid int NULL,

	sid int NULL,

	ctid int NULL,

	aid int NULL,

	catid int NULL,

	scatid int NULL,

	active boolean NULL,

	noofhits bigint NULL,

	hitmonth date NULL) ON COMMIT DROP;
  OPEN dailykeywird;
  FETCH dailykeywird INTO v_mhid;
  WHILE FOUND LOOP
  v_totalhits := 0;
  IF EXISTS(SELECT mhid FROM tblnumberofhitsmonthly WHERE mhid = v_mhid AND status = 1) THEN
  SELECT cid, sid, ctid, aid, keywordid, catid INTO v_cid, v_sid, v_ctid, v_aid, v_keywordid, v_catid FROM tblnumberofhitsmonthly WHERE mhid = v_mhid;
  DROP TABLE IF EXISTS tmp_temp2;
