--
-- Name: usp_operator_all_report(bigint, character varying, character varying, character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_operator_all_report(v_optid bigint DEFAULT 0, v_fromdate character varying DEFAULT ''::character varying, v_todate character varying DEFAULT ''::character varying, v_monthval character varying DEFAULT ''::character varying) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_sqlquery text;
  v_count int;
  v_count1 int;
  v_date varchar(100);
  v_unverified int;
  v_verified int;
  v_process int;
  v_oprator bigint;
BEGIN
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp (rowNumber int,
optid bigint,
date varchar(100),
logintime varchar(100),
logouttime varchar(100),
totallistings bigint,
unverified bigint,
verified bigint,
process bigint) ON COMMIT DROP;
  v_sqlquery := '';
  v_sqlquery := ' insert into #temp select ROW_NUMBER() over (order by convert(date,doc) desc) as rownumber ,pm.optid,
              convert(varchar(20),doc,106) as date,isnull((convert(varchar(20),logintime,105)+'' ''+convert(varchar(8),logintime,108)),''-'') as logintime,
			  isnull((convert(varchar(20),logouttime,105)+'' ''+convert(varchar(8),logouttime,108)),''-'') as logouttime,COUNT(1) as totallistings,
			  0 as unverified,0 as verified,0 as process from portal_master pm left join tbl_operator_report omr 
			  on convert(varchar(20),omr.logintime,105)=convert(varchar(20),pm.doc,105) and ISNULL(omr.optid,0)=ISNULL(pm.optid,0)
			  where ISNULL(pm.optid,0)<>0  and ISNULL(doc,'''')<>'''' ';
  IF (v_optid <> '') THEN
  v_sqlquery := v_sqlquery || (' and pm.optid = ' || CAST(v_optid AS VARCHAR(20)) || ' ');
  END IF;
  IF (v_monthval <> '') THEN
  v_sqlquery := v_sqlquery || (' and convert(varchar(7), doc, 126)= ''' || v_monthval || ''' ');
  END IF;
  v_sqlquery := v_sqlquery || (' group by convert(date,doc),convert(varchar(20),doc,106),(convert(varchar(20),logintime,105)+'' ''+convert(varchar(8),logintime,108)),
		     	   isnull((convert(varchar(20),logouttime,105)+'' ''+convert(varchar(8),logouttime,108)),''-''),pm.optid  ');
  EXECUTE v_sqlquery;
  SELECT COUNT(1) INTO v_count1 FROM tmp_temp;
  v_count := 1;
  WHILE (v_count <= v_count1) LOOP
  SELECT date, optid INTO v_date, v_oprator FROM tmp_temp WHERE rownumber = v_count;
  SELECT COUNT(1) INTO v_unverified FROM portal_master WHERE COALESCE(isverified, 0) = 0 AND CAST(TO_CHAR(doc, 'DD TMMon YYYY') AS VARCHAR(20)) = v_date AND COALESCE(optid, 0) = v_oprator;
  SELECT COUNT(1) INTO v_verified FROM portal_master WHERE COALESCE(isverified, 0) = 1 AND CAST(TO_CHAR(doc, 'DD TMMon YYYY') AS VARCHAR(20)) = v_date AND COALESCE(optid, 0) = v_oprator;
  SELECT COUNT(1) INTO v_process FROM portal_master WHERE COALESCE(isverified, 0) = 2 AND CAST(TO_CHAR(doc, 'DD TMMon YYYY') AS VARCHAR(20)) = v_date AND COALESCE(optid, 0) = v_oprator;
  UPDATE tmp_temp SET unverified = v_unverified, verified = v_verified, process = v_process WHERE rownumber = v_count;
  v_count := v_count + 1;
  END LOOP;
  RETURN QUERY SELECT * FROM tmp_temp;
  DROP TABLE IF EXISTS tmp_temp;
END;
$$;


--
-- Name: usp_operator_overall_report_admin(integer, integer, character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_operator_overall_report_admin(v_startrowindex integer, v_maxrows integer, v_month character varying) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_sqlquery text;
  v_count int;
  v_count1 int;
  v_unverified int;
  v_verified int;
  v_process int;
  v_oprator bigint;
  v_recordcount int;
  v_totallisting int;
  v_totalverified int;
  v_totalunverified int;
  v_totalinprocess int;
BEGIN
  -- SET option (removed)
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp (rowNumber int,
optid bigint,
optname varchar(100),
totallistings bigint,
unverified bigint,
verified bigint,
process bigint) ON COMMIT DROP;
  v_sqlquery := '';
  v_sqlquery := ' insert into #temp select ROW_NUMBER() over (order by ISNULL(om.loginid,'''') asc) as rownumber,pm.optid,ISNULL(om.loginid,'''') as optname,
                 COUNT(1) as totallistings,0 as unverified,0 as verified,0 as process 
                 from portal_master pm left join tbl_operator_report omr 
                 on convert(varchar(20),omr.logintime,105)=convert(varchar(20),pm.doc,105) and ISNULL(omr.optid,0)=ISNULL(pm.optid,0)
                 left join tbl_operator_master om on ISNULL(om.optid,0)=ISNULL(pm.optid,0)
                 where ISNULL(pm.optid,0)<>0  and ISNULL(doc,'''')<>'''' ';
  IF (v_month <> '') THEN
  v_sqlquery := v_sqlquery || (' and CONVERT(varchar(7),doc,126)= ''' || v_month || ''' ');
  END IF;
  v_sqlquery := v_sqlquery || (' group by pm.optid,ISNULL(om.loginid,'''')  ');
  EXECUTE v_sqlquery;
  v_count1 := v_maxrows;
  v_count := v_startrowindex;
  WHILE (v_count <= v_count1) LOOP
  IF EXISTS(SELECT 1 FROM tmp_temp WHERE rownumber = v_count) THEN
  SELECT optid INTO v_oprator FROM tmp_temp WHERE rownumber = v_count;
  IF (v_month <> '') THEN
  SELECT COUNT(1) INTO v_unverified FROM portal_master WHERE COALESCE(isverified, 0) = 0 AND CAST(TO_CHAR(doc, 'YYYY-MM-DDTHH24:MI:SS.US') AS VARCHAR(7)) = v_month AND COALESCE(optid, 0) = v_oprator;
  SELECT COUNT(1) INTO v_verified FROM portal_master WHERE COALESCE(isverified, 0) = 1 AND CAST(TO_CHAR(doc, 'YYYY-MM-DDTHH24:MI:SS.US') AS VARCHAR(7)) = v_month AND COALESCE(optid, 0) = v_oprator;
  SELECT COUNT(1) INTO v_process FROM portal_master WHERE COALESCE(isverified, 0) = 2 AND CAST(TO_CHAR(doc, 'YYYY-MM-DDTHH24:MI:SS.US') AS VARCHAR(7)) = v_month AND COALESCE(optid, 0) = v_oprator;
  ELSE
  SELECT COUNT(1) INTO v_unverified FROM portal_master WHERE COALESCE(isverified, 0) = 0 AND COALESCE(optid, 0) = v_oprator;
  SELECT COUNT(1) INTO v_verified FROM portal_master WHERE COALESCE(isverified, 0) = 1 AND COALESCE(optid, 0) = v_oprator;
  SELECT COUNT(1) INTO v_process FROM portal_master WHERE COALESCE(isverified, 0) = 2 AND COALESCE(optid, 0) = v_oprator;
  END IF;
  UPDATE tmp_temp SET unverified = v_unverified, verified = v_verified, process = v_process WHERE rownumber = v_count;
  END IF;
  v_count := v_count + 1;
  END LOOP;
  RETURN QUERY SELECT * FROM tmp_temp WHERE rownumber BETWEEN v_startrowindex AND v_maxrows;
  SELECT COUNT(1) INTO v_recordcount FROM tmp_temp;
  SELECT SUM(totallistings) INTO v_totallisting FROM tmp_temp WHERE rownumber BETWEEN v_startrowindex AND v_maxrows;
  SELECT SUM(verified) INTO v_totalverified FROM tmp_temp WHERE rownumber BETWEEN v_startrowindex AND v_maxrows;
  SELECT SUM(unverified) INTO v_totalunverified FROM tmp_temp WHERE rownumber BETWEEN v_startrowindex AND v_maxrows;
  SELECT SUM(process) INTO v_totalinprocess FROM tmp_temp WHERE rownumber BETWEEN v_startrowindex AND v_maxrows;
  RETURN QUERY SELECT v_recordcount AS total, v_totallisting AS totallistings, v_totalverified AS totalverified, v_totalunverified AS totalunverified, v_totalinprocess AS totalprocess;
  DROP TABLE IF EXISTS tmp_temp;
  -- SET option (removed)
END;
$$;


--
-- Name: usp_operator_process_listings(character varying, character varying, integer, integer, bigint); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_operator_process_listings(v_fromdate character varying DEFAULT ''::character varying, v_todate character varying DEFAULT ''::character varying, v_pageno integer DEFAULT 1, v_pagesize integer DEFAULT 30, v_optid bigint DEFAULT NULL::bigint) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_minindex int;
  v_maxindex int;
  v_recordcount int;
  v_amount numeric(19,4);
  v_currencysymbol varchar(20);
  v_totalamount numeric(19,4);
  v_sqlquery text;
BEGIN
  -- SET option (removed)
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp (rowNumber bigint,
LoginId varchar(100),
companyname text,
Password varchar(50),
message text,
countryname varchar(25),
doc  varchar(50),
qaname varchar(100)) ON COMMIT DROP;
  v_minindex := 0;
  v_maxindex := 0;
  v_sqlquery := '';
  v_minindex := ((v_pageno - 1) * v_pagesize) + 1;
  v_maxindex := (v_pageno * v_pagesize);
  v_sqlquery := ' insert into #temp select ROW_NUMBER() over(order by pm.doc  desc) as rownumber,pl.LoginId,pm.companyname,pl.Password,ulm.message,
                  (case c.countryname when ''UNITED STATES'' then ''US'' when ''UNITED KINGDOM'' then ''UK'' else c.countryname end) as countryname,
				  pm.doc,ISNULL(om.name,'''') as qaname
				  from portal_master pm join Portal_Login pl on pl.PMID=pm.pmid join COUNTRY c on c.cid=pm.cid
				  join unvarifiedlisting_master ulm on ulm.pmid=pm.pmid 
				  left join tbl_ListingsWithQA la on la.pmid=pm.pmid
				  left join tbl_operator_master om on om.optid=la.optid
				  where ISNULL(pm.optid,0)!=0 and ISNULL(pm.isverified,0)=2 and ulm.status=1 and ISNULL(pm.optid,0)=' || CAST(v_optid AS VARCHAR(20));
  IF (v_fromdate <> '') THEN
  v_sqlquery := v_sqlquery || ' and (convert(date, pm.doc,103) >= convert(date,''' || v_fromdate || ''',103)) ';
  END IF;
  IF (v_todate <> '') THEN
  v_sqlquery := v_sqlquery || ' and (convert(date, lpm.doc,103)<=convert(date,''' || v_todate || ''',103)) ';
  END IF;
  IF (v_fromdate <> '' AND v_todate <> '') THEN
  v_sqlquery := v_sqlquery || ' and (convert(date, pm.doc,103)  between  convert(date,''' || v_fromdate || ''',103)  and convert(date,''' || v_todate || ''',103)) ';
  END IF;
  EXECUTE v_sqlquery;
  SELECT COUNT(*) INTO v_recordcount FROM tmp_temp;
  RETURN QUERY SELECT *, v_recordcount AS recordcount FROM tmp_temp WHERE rownumber BETWEEN v_minindex AND v_maxindex;
  DROP TABLE IF EXISTS tmp_temp;
  -- SET option (removed)
END;
$$;


