  v_sqlquery text;
BEGIN
  -- SET option (removed)
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp (rowNumber bigint,
LoginId varchar(100),
companyname text,
Password varchar(50),
countryname varchar(25),
doc  varchar(50),
qaname varchar(100),
