  v_maxindex := (v_pageno * v_pagesize);
  v_sqlquery := 'insert into #temp  select ROW_NUMBER() over(order by pm.doc  desc) as rownumber,pl.LoginId,pm.companyname,pl.Password,
                  (case c.countryname when ''UNITED STATES'' then ''US'' when ''UNITED KINGDOM'' then ''UK'' else c.countryname end) as countryname,
				  CONVERT(varchar(50),pm.doc,106) as doc,ISNULL(om.name,'''') as qaname,ISNULL(CONVERT(varchar(50),la.verify_date,106),'''') as verifydate
                  from portal_master pm join Portal_Login pl on pl.PMID=pm.pmid
                  join COUNTRY c on c.cid=pm.cid
                  left join tbl_ListingsWithQA la on la.pmid=pm.pmid
                  left join tbl_operator_master om on om.optid=la.optid
                  where ISNULL(pm.optid,0)!=0 and ISNULL(pm.isverified,0)=1 and ISNULL(pm.optid,0)=' || CAST(v_optid AS VARCHAR(20));
  IF (v_fromdate <> '') THEN
  v_sqlquery := v_sqlquery || ' and (convert(date, pm.doc,103) >= convert(date,''' || v_fromdate || ''',103)) ';
  END IF;
  IF (v_todate <> '') THEN
  v_sqlquery := v_sqlquery || ' and (convert(date, lpm.doc,103)<=convert(date,''' || v_todate || ''',103)) ';
  END IF;
  IF (v_fromdate <> '' AND v_todate <> '') THEN
  v_sqlquery := v_sqlquery || ' and (convert(date, pm.doc,103)  between  convert(date,''' || v_fromdate || ''',103)  and convert(date,''' || v_todate || ''',103)) ';
  END IF;
  EXECUTE v_sqlquery;
  SELECT COUNT(*) INTO v_recordcount FROM tmp_temp;
  RETURN QUERY SELECT *, v_recordcount AS recordcount FROM tmp_temp WHERE rownumber BETWEEN v_minindex AND v_maxindex;
  DROP TABLE IF EXISTS tmp_temp;
