--
-- Name: usp_operatordailyreport(integer, integer, character varying, character varying, character varying, character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_operatordailyreport(v_startrowindex integer, v_maxrows integer, v_fromdate character varying, v_todate character varying, v_month character varying, v_operator character varying) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_sqlquery text;
  v_count int;
  v_count1 int;
  v_date varchar(100);
  v_unverified int;
  v_verified int;
  v_process int;
  v_oprator bigint;
  v_recordcount int;
  v_totallisting int;
  v_totalverified int;
  v_totalunverified int;
  v_totalinprocess int;
BEGIN
  -- SET option (removed)
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp (rowNumber int,
optid bigint,
optname varchar(100),
date varchar(100),
logintime varchar(100),
logouttime varchar(100),
totallistings bigint,
unverified bigint,
verified bigint,
process bigint) ON COMMIT DROP;
  v_sqlquery := '';
  v_sqlquery := ' insert into #temp select ROW_NUMBER() over (order by convert(date,doc) desc) as rownumber ,pm.optid,ISNULL(om.loginid,'''') as optname,
              convert(varchar(20),doc,106) as date,isnull((convert(varchar(20),logintime,105)+'' ''+convert(varchar(8),logintime,108)),''-'') as logintime,
			  isnull((convert(varchar(20),logouttime,105)+'' ''+convert(varchar(8),logouttime,108)),''-'') as logouttime,COUNT(1) as totallistings,
			  0 as unverified,0 as verified,0 as process from portal_master pm left join tbl_operator_report omr 
			  on convert(varchar(20),omr.logintime,105)=convert(varchar(20),pm.doc,105) and ISNULL(omr.optid,0)=ISNULL(pm.optid,0)
			  left join tbl_operator_master om on ISNULL(om.optid,0)=ISNULL(pm.optid,0)
			  where ISNULL(pm.optid,0)<>0  and ISNULL(doc,'''')<>'''' ';
  IF (v_operator <> '') THEN
  v_sqlquery := v_sqlquery || (' and pm.optid = ' || CAST(v_operator AS VARCHAR(20)) || ' ');
  END IF;
  IF (v_fromdate <> '') THEN
  v_sqlquery := v_sqlquery || ' and convert(date,doc,103)=convert(date,''' || v_fromdate || ''',103) ';
  END IF;
  IF (v_month <> '') THEN
  v_sqlquery := v_sqlquery || (' and convert(varchar(7), doc, 126)= ''' || v_month || ''' ');
  END IF;
  v_sqlquery := v_sqlquery || (' group by convert(date,doc),convert(varchar(20),doc,106),(convert(varchar(20),logintime,105)+'' ''+convert(varchar(8),logintime,108)),
		     	   isnull((convert(varchar(20),logouttime,105)+'' ''+convert(varchar(8),logouttime,108)),''-''),pm.optid,ISNULL(om.loginid,'''')  ');
  EXECUTE v_sqlquery;
  v_count1 := v_maxrows;
  v_count := v_startrowindex;
  WHILE (v_count <= v_count1) LOOP
  IF EXISTS(SELECT 1 FROM tmp_temp WHERE rownumber = v_count) THEN
  SELECT date, optid INTO v_date, v_oprator FROM tmp_temp WHERE rownumber = v_count;
  SELECT COUNT(1) INTO v_unverified FROM portal_master WHERE COALESCE(isverified, 0) = 0 AND CAST(TO_CHAR(doc, 'DD TMMon YYYY') AS VARCHAR(20)) = v_date AND COALESCE(optid, 0) = v_oprator;
  SELECT COUNT(1) INTO v_verified FROM portal_master WHERE COALESCE(isverified, 0) = 1 AND CAST(TO_CHAR(doc, 'DD TMMon YYYY') AS VARCHAR(20)) = v_date AND COALESCE(optid, 0) = v_oprator;
  SELECT COUNT(1) INTO v_process FROM portal_master WHERE COALESCE(isverified, 0) = 2 AND CAST(TO_CHAR(doc, 'DD TMMon YYYY') AS VARCHAR(20)) = v_date AND COALESCE(optid, 0) = v_oprator;
  UPDATE tmp_temp SET unverified = v_unverified, verified = v_verified, process = v_process WHERE rownumber = v_count;
  END IF;
  v_count := v_count + 1;
  END LOOP;
  RETURN QUERY SELECT * FROM tmp_temp WHERE rownumber BETWEEN v_startrowindex AND v_maxrows;
  SELECT COUNT(1) INTO v_recordcount FROM tmp_temp;
  SELECT SUM(totallistings) INTO v_totallisting FROM tmp_temp WHERE rownumber BETWEEN v_startrowindex AND v_maxrows;
  SELECT SUM(verified) INTO v_totalverified FROM tmp_temp WHERE rownumber BETWEEN v_startrowindex AND v_maxrows;
  SELECT SUM(unverified) INTO v_totalunverified FROM tmp_temp WHERE rownumber BETWEEN v_startrowindex AND v_maxrows;
  SELECT SUM(process) INTO v_totalinprocess FROM tmp_temp WHERE rownumber BETWEEN v_startrowindex AND v_maxrows;
  RETURN QUERY SELECT v_recordcount AS total, v_totallisting AS totallistings, v_totalverified AS totalverified, v_totalunverified AS totalunverified, v_totalinprocess AS totalprocess;
  DROP TABLE IF EXISTS tmp_temp;
  -- SET option (removed)
END;
$$;


--
-- Name: usp_operatorreport(integer, integer, character varying, boolean, character varying, character varying, character varying, character varying, integer, integer, character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_operatorreport(v_startrowindex integer, v_maxrows integer, v_orderbyfield character varying, v_asc boolean, v_searchfield character varying, v_searchvalue character varying, v_fromdate character varying, v_todate character varying, v_mode integer, v_recordcount integer, v_operator character varying) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_sqlquery text;
BEGIN
  -- SET option (removed)
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp (rowNumber int,
operatername varchar(100),
title varchar(150),
LoginId varchar(150),
username varchar(100),
doc varchar(200),
cityName varchar(100),
country varchar(100)) ON COMMIT DROP;
  v_sqlquery := '';
  v_sqlquery := 'insert into #temp select ROW_NUMBER() OVER(ORDER BY pmd.doc desc) as rowNumber, pm.operatorname,pm.title,p.LoginId,p.username,
 CONVERT(VARCHAR(10),CAST(pmd.doc as DATE),103) as doc,ct.cityName,(case when c.countryname=''UNITED STATES'' then ''US'' when c.countryname=''UNITED KINGDOM'' then ''UK'' else c.countryname end) as countryName from Portal_Login p
  left join portal_master pm on p.PMID=pm.pmid left join portal_master_details pmd on pmd.pmid=pm.pmid  left join CITY ct on ct.ctid=pm.ctid left join country c on c.cid=pm.cid where pm.operatorname <> '' '' ';
  IF (v_operator <> '') THEN
  v_sqlquery := v_sqlquery || (' and pm.operatorname like ''%' || v_operator || '%''');
  END IF;
  IF (v_fromdate = '' OR v_todate = '') THEN
  IF (v_fromdate <> '') THEN
  v_sqlquery := v_sqlquery || ' and  CONVERT(date,pmd.DOC,110)= replace(convert(date,''' || v_fromdate || ''',103),''/'',''-'') ';
  END IF;
  IF (v_todate <> '') THEN
  v_sqlquery := v_sqlquery || ' and CONVERT(date,pmd.DOC,110)  =replace(convert(date,''' || v_todate || ''',103),''/'',''-'') ';
  END IF;
  END IF;
  IF (v_fromdate <> '' AND v_todate <> '') THEN
  v_sqlquery := v_sqlquery || ' and CONVERT(date,pmd.DOC,110)  between  replace(convert(date,''' || v_fromdate || ''',103),''/'',''-'')  and replace(convert(date,''' || v_todate || ''',103),''/'',''-'')';
  END IF;
  IF (v_searchfield = 'loginid') THEN
  v_sqlquery := v_sqlquery || ' and p.loginid like ''%' || v_searchvalue || '%''';
  END IF;
  IF (v_searchfield = 'business') THEN
  v_sqlquery := v_sqlquery || ' and pm.title like ''%' || v_searchvalue || '%''';
  END IF;
  IF (v_searchfield = 'username') THEN
  v_sqlquery := v_sqlquery || ' and p.username like ''%' || v_searchvalue || '%''';
  END IF;
  EXECUTE v_sqlquery;
  SELECT COUNT(*) INTO v_recordcount FROM tmp_temp;
  RETURN QUERY SELECT * FROM tmp_temp WHERE rownumber BETWEEN v_startrowindex AND v_maxrows;
  DROP TABLE IF EXISTS tmp_temp;
  RETURN QUERY SELECT v_recordcount AS recordcount;
  -- SET option (removed)
END;
$$;


--
-- Name: usp_operatortargetreport(integer, integer, character varying, character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_operatortargetreport(v_startrowindex integer, v_maxrows integer, v_fromdate character varying, v_todate character varying) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_sqlquery text;
  v_count int;
  v_count1 int;
  v_unverified int;
  v_oprator bigint;
  v_targetlist double precision;
  v_achievedlist double precision;
  v_recordcount int;
BEGIN
  -- SET option (removed)
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp (rowNumber int,
optid bigint,
optname varchar(100),
workingdays int,
targetlist int,
achievedlist int,
percachieved double precision) ON COMMIT DROP;
  v_sqlquery := '';
  v_sqlquery := ' insert into #temp select ROW_NUMBER() over (order by ISNULL(om.loginid,'''') asc) as rownumber,omr.optid,ISNULL(om.loginid,'''') as optname,
                 COUNT(orid) as workdays,SUM(ISNULL(omr.dailytarget,0)) as target,0,0
                 from tbl_operator_report omr left join tbl_operator_master om on ISNULL(om.optid,0)=ISNULL(omr.optid,0)
                 where ISNULL(omr.optid,0)<>0  and ISNULL(omr.logintime,'''')<>'''' and ISNULL(usertype,'''')=''Operator'' and ISNULL(totallisting,0)>0 ';
  IF (v_fromdate = '' OR v_todate = '') THEN
  IF (v_fromdate <> '' AND v_todate = '') THEN
  v_sqlquery := v_sqlquery || (' and CONVERT(date,logintime,103)>=CONVERT(date,''' || v_fromdate || ''',103)  ');
  ELSE
  IF (v_fromdate = '' AND v_todate <> '') THEN
  v_sqlquery := v_sqlquery || (' and CONVERT(date,logintime,103)<=CONVERT(date,''' || v_todate || ''',103)  ');
  END IF;
  END IF;
  ELSE
  v_sqlquery := v_sqlquery || (' and (CONVERT(date,logintime,103) between CONVERT(date,''' || v_fromdate || ''',103) and CONVERT(date,''' || v_todate || ''',103))  ');
  END IF;
  v_sqlquery := v_sqlquery || (' group by omr.optid,ISNULL(om.loginid,'''') having SUM(ISNULL(omr.dailytarget,0))>0  ');
  EXECUTE v_sqlquery;
  v_count1 := v_maxrows;
  v_count := v_startrowindex;
  WHILE (v_count <= v_count1) LOOP
  IF EXISTS(SELECT 1 FROM tmp_temp WHERE rownumber = v_count) THEN
  SELECT optid, targetlist INTO v_oprator, v_targetlist FROM tmp_temp WHERE rownumber = v_count;
  IF (v_fromdate = '' OR v_todate = '') THEN
  IF (v_fromdate <> '' AND v_todate = '') THEN
  SELECT COUNT(1) INTO v_achievedlist FROM portal_master WHERE COALESCE(optid, 0) = v_oprator AND COALESCE(isverified, 0) <> 3 AND COALESCE(doc, '') <> '' AND TO_DATE(doc, 'DD/MM/YYYY') >= TO_DATE(v_fromdate, 'DD/MM/YYYY');
  ELSE
  IF (v_fromdate = '' AND v_todate <> '') THEN
  SELECT COUNT(1) INTO v_achievedlist FROM portal_master WHERE COALESCE(optid, 0) = v_oprator AND COALESCE(isverified, 0) <> 3 AND COALESCE(doc, '') <> '' AND TO_DATE(doc, 'DD/MM/YYYY') <= TO_DATE(v_todate, 'DD/MM/YYYY');
  ELSE
  SELECT COUNT(1) INTO v_achievedlist FROM portal_master WHERE COALESCE(optid, 0) = v_oprator AND COALESCE(isverified, 0) <> 3 AND COALESCE(doc, '') <> '';
  END IF;
  END IF;
  ELSE
  SELECT COUNT(1) INTO v_achievedlist FROM portal_master WHERE COALESCE(optid, 0) = v_oprator AND COALESCE(isverified, 0) <> 3 AND COALESCE(doc, '') <> '' AND (TO_DATE(doc, 'DD/MM/YYYY') BETWEEN TO_DATE(v_fromdate, 'DD/MM/YYYY') AND TO_DATE(v_todate, 'DD/MM/YYYY'));
  END IF;
  UPDATE tmp_temp SET achievedlist = v_achievedlist, percachieved = ROUND(((v_achievedlist / v_targetlist) * 100), 2) WHERE rownumber = v_count;
  END IF;
  v_count := v_count + 1;
  END LOOP;
  RETURN QUERY SELECT * FROM tmp_temp WHERE rownumber BETWEEN v_startrowindex AND v_maxrows;
  SELECT COUNT(1) INTO v_recordcount FROM tmp_temp;
  RETURN QUERY SELECT v_recordcount AS total;
  DROP TABLE IF EXISTS tmp_temp;
  -- SET option (removed)
END;
$$;


--
-- Name: usp_order_invoice(character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_order_invoice(v_orderid character varying DEFAULT 'SI/18-19/000009'::character varying) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
BEGIN
  RETURN QUERY SELECT ROW_NUMBER() OVER (ORDER BY invm.orid NULLS FIRST) AS rownumber, invm.orid, invm.poid, invm.orderid, invm.orderno, invm.morderid, invm.paymode, invm.remark, invm.order_date, COALESCE(invm.customername, '') AS name, COALESCE(invm.address, '') AS billadd, COALESCE(invm.city, '') AS city, COALESCE(invm.pincode, '') AS pincode, invm.emailid, invm.mobile, invm.invoiceno, invm.invoice_date, invm.quantity, COALESCE(pom.companyname, '') AS companyname, COALESCE(pom.pick_state, '') AS pick_state, COALESCE(pom.pick_city, '') AS pick_city, COALESCE(pom.pick_area, '') AS pick_area, COALESCE(pom.pick_pincode, '') AS pick_pincode, COALESCE(pom.pick_address, '') AS pick_address, COALESCE(pom.gstno, '') AS gstno, pm.product_name, pm.total_cost, total_vat, total_purchase_cost, COALESCE(vc.vattitle, '') AS vattitle, COALESCE(vc.vatpercvalue, 0) AS vatpercvalue, pm.total_dap, pm.total_ship_ch, (SELECT panno FROM tbl_businesskycdetails WHERE type = 'Pancard-Details' AND plid = pl.plid) AS panno, COALESCE(dm.companyimage, 'No-logo.png') AS brandlogo, COALESCE(dm.companydetailname, '') AS companyfullname, imsp.prskucode, imsp.sprid FROM tbl_invoicedetailsmaster AS invm LEFT JOIN portal_login AS pl ON invm.plid = pl.plid LEFT JOIN portal_master AS pom ON pl.plid = pom.plid LEFT JOIN tbl_product_order_master AS pm ON invm.orderno = pm.orderno LEFT JOIN tbl_customerlogin AS cl ON pm.loginid = cl.loginid LEFT JOIN distributor_master AS dm ON cl.did = dm.plid LEFT JOIN ims_subproduct AS imsp ON imsp.sprid = invm.product_code LEFT JOIN tbl_vat_categories AS vc ON vc.vcid = imsp.vatcategoryid WHERE invm.invoiceno = v_orderid;
END;
$$;


--
-- Name: usp_order_list_complete(integer, integer, character varying, character varying, character varying, character varying, character varying, character varying, bigint, integer, character varying, bigint); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_order_list_complete(v_startrowindex integer DEFAULT 1, v_maxrows integer DEFAULT 100, v_searchfield character varying DEFAULT ''::character varying, v_searchvalue character varying DEFAULT ''::character varying, v_fromdate character varying DEFAULT ''::character varying, v_todate character varying DEFAULT ''::character varying, v_status character varying DEFAULT ''::character varying, v_statustype character varying DEFAULT ''::character varying, v_branchid bigint DEFAULT 1, v_totalcount integer DEFAULT 0, v_company character varying DEFAULT ''::character varying, v_poid bigint DEFAULT 0) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_minindex INT;
  v_maxindex INT;
  v_query text;
BEGIN
  v_minindex := (v_startrowindex - 1) * v_maxrows + 1;
  v_maxindex := v_startrowindex * v_maxrows;
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp (ROWNUMBER BIGINT 
, LOGINID VARCHAR( 100) 
, NAME VARCHAR(1000) 
, BRCODE VARCHAR( 50) 
, MOBILENO VARCHAR(20) 
, ORDERID VARCHAR( 50) 
, ORDERDATE timestamp 
, ORDER_QTY INT 
, ORDER_DAP DECIMAL 
, ORDER_NETAMT DECIMAL
, PAYMODE VARCHAR( 25) 
, CITY VARCHAR(300) 
, TOTAL_VAT DECIMAL 
, ORDERINTSTATUS INT 
, POID BIGINT 
, SPRID BIGINT 
, PRODUCT_QTY INT 
, SINGLE_DAP DECIMAL 
, TOTAL_DAP DECIMAL 
, TOTAL_SHIP_CH DECIMAL 
, TOTAL_COST DECIMAL 
, PRODUCTTOTALVAT DECIMAL 
,TOTAL_PURCHASE_COST DECIMAL
, PRODUCT_NAME varchar (500)
, PRODQTY varchar (100)
, PROUNIT VARCHAR( 500) 
, PRODCOLOR varchar (100)
, PRODSIZE varchar (100)
, PROD_IMAGES text 
, STATUS VARCHAR( 500) 
, PRODUCTINTSTATUS INT 
, PROCESSBY VARCHAR( 500) 
, PROCESSDATE timestamp 
, PROCESSREMARK VARCHAR(500) 
, INVQTY INT 
, REASON VARCHAR(100) 
, ISCANCELBYMEMBER boolean 
, ISRETURN boolean
, Address text
, PinCode VARCHAR (50)
, CountryName VARCHAR (500)
,JP decimal(18,0)
,BV decimal(18,0)
,COMPANYNAME varchar(1000)
,pmid bigint,
SubPrCode varchar(1000),
Approved varchar(1000),
dispatchdate varchar(1000)) ON COMMIT DROP;
  v_query := 'INSERT INTO #TEMP  SELECT ROW_NUMBER() OVER (ORDER BY OM.ORDERDATE DESC) AS ROWNUMBER,
POM.LOGINID,(OM.FNAME+''''+ISNULL(OM.LNAME,'''')) AS NAME,B.CLID AS BRCODE,OM.MOBILENO,
OM.ORDERID,OM.ORDERDATE,OM.ORDER_QTY,OM.ORDER_DAP,OM.ORDER_NETAMT,OM.PAYMODE,isnull(OM.Sh_City,'''') as CITY,
OM.TOTAL_VAT,OM.INTSTATUS AS ORDERINTSTATUS,POM.POID, CONVERT(BIGINT, POM.SUBPRCODE) AS SPRID,
POM.PRODUCT_QTY, POM.SINGLE_DAP, POM.TOTAL_DAP, POM.TOTAL_SHIP_CH, POM.TOTAL_COST,
POM.TOTAL_VAT AS PRODUCTTOTALVAT,POM.TOTAL_PURCHASE_COST, POM.PRODUCT_NAME, POM.PRODQTY, POM.PROUNIT, 
POM.PRODCOLOR, POM.PRODSIZE, POM.PROD_IMAGES, POM.STATUS, POM.INTSTATUS AS PRODUCTINTSTATUS,
POM.PROCESSBY, POM. PROCESSDATE, POM.PROCESSREMARK,ISNULL(POM.INVQTY,0) AS INVQTY,
POM.REASON,ISNULL(POM.ISCANCELBYMEMBER,0) AS ISCANCELBYMEMBER , ISNULL(POM.ISRETURN,0) AS ISRETURN ,isnull(OM.Address,'''') AS Address,ISNULL(OM.PinCode,'''') AS PinCode,ISNULL(IMS.CountryName,'''') AS CountryName,
isnull(IMSP.PV,0) AS JP,ISNULL(IMSP.BV,0) AS BV,pma.COMPANYNAME,pma.PMID,IMSP.SubPrCode,isnull(OCS.Approved,'''') as Approved ,isnull(OCS.Approved+IMSP.ProcurementSLA,'''') as dispatchdate
FROM TBL_ORDER_MASTER OM 
LEFT JOIN TBL_PRODUCT_ORDER_MASTER POM ON POM.ORDERID = OM.ORDERID 
join PORTAL_LOGIN pl on pl.PLID=OM.BranchId JOIN TBL_CUSTOMERLOGIN B ON B.LOGINID = OM.LoginId
left join IMS_CustomerAddress IMS on IMS.Id=B.CLID
left join Portal_Master pma on pma.PMID=pl.PMID
left join IMS_SubProduct IMSP on IMSP.SPRID= POM.SubPrCode
left join tbl_Order_ConfirmedStaus OCS on OCS.ORDERID=POM.ORDERID';
  IF ((v_fromdate <> '') AND (v_todate = '')) THEN
  v_query := v_query || ' AND CONVERT(DATE, OM.ORDERDATE, 105) BETWEEN  CONVERT(DATE, ''' || v_fromdate || ''', 105) AND  CONVERT(DATE, DBO.FUN_GETCURRENTDATE(), 105)';
  END IF;
  IF ((v_fromdate = '') AND (v_todate <> '')) THEN
  v_query := v_query || 'AND CONVERT(DATE, OM.ORDERDATE, 105) BETWEEN  CONVERT(DATE, ''' || v_todate || ''', 105) AND  CONVERT(DATE, DBO.FUN_GETCURRENTDATE(), 105)';
  END IF;
  IF ((v_fromdate <> '') AND (v_todate <> '')) THEN
  v_query := v_query || 'AND CONVERT(DATE, OM.ORDERDATE, 105) BETWEEN CONVERT(DATE, ''' || v_fromdate || ''', 105) AND  CONVERT(DATE, ''' || v_todate || ''', 105)';
  END IF;
  IF (v_branchid > 0) THEN
  v_query := v_query || ' AND pl.PLID=' || CAST(v_branchid AS VARCHAR(20)) || '';
  END IF;
  EXECUTE v_query;
  RAISE NOTICE '%', (v_query);
  RETURN QUERY SELECT * FROM tmp_temp WHERE rownumber BETWEEN v_minindex AND v_maxindex;
  SELECT COUNT(rownumber) INTO v_totalcount FROM tmp_temp;
  DROP TABLE IF EXISTS tmp_temp;
  -- SET option (removed)
END;
$$;


--
-- Name: usp_order_list_complete_new(integer, integer, character varying, character varying, character varying, character varying, character varying, character varying, bigint, integer, character varying, character varying, character varying, character varying, character varying, character varying, character varying, integer, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_order_list_complete_new(v_startrowindex integer DEFAULT 1, v_maxrows integer DEFAULT 100, v_searchfield character varying DEFAULT ''::character varying, v_searchvalue character varying DEFAULT ''::character varying, v_fromdate character varying DEFAULT ''::character varying, v_todate character varying DEFAULT ''::character varying, v_status character varying DEFAULT ''::character varying, v_statustype character varying DEFAULT '1'::character varying, v_branchid bigint DEFAULT 0, v_totalcount integer DEFAULT 0, v_fromreadyfordispatch character varying DEFAULT ''::character varying, v_toreadyfordispatch character varying DEFAULT ''::character varying, v_orderid character varying DEFAULT ''::character varying, v_orderno character varying DEFAULT ''::character varying, v_merchantname character varying DEFAULT ''::character varying, v_productname character varying DEFAULT ''::character varying, v_loginid character varying DEFAULT ''::character varying, v_categoryrelatedto integer DEFAULT 0, v_did integer DEFAULT 0) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_minindex INT;
  v_maxindex INT;
  v_query text;
BEGIN
  v_minindex := (v_startrowindex - 1) * v_maxrows + 1;
  v_maxindex := v_startrowindex * v_maxrows;
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp (ROWNUMBER BIGINT                 
, LOGINID VARCHAR( 100)                 
, NAME VARCHAR(1000)                 
, BRCODE VARCHAR( 50)                 
, MOBILENO VARCHAR(20)                 
, ORDERID VARCHAR(50)                 
, ORDERDATE VARCHAR(100)                 
, ORDER_QTY INT                 
, ORDER_DAP DECIMAL(18,2)                 
, ORDER_NETAMT DECIMAL (18,2)                 
, PAYMODE VARCHAR( 25)                 
, CITY VARCHAR(300)                 
, TOTAL_VAT DECIMAL (18,2)                 
, ORDERINTSTATUS INT                 
, POID BIGINT                 
, SPRID BIGINT                 
, PRODUCT_QTY INT                 
, SINGLE_DAP DECIMAL (18,2)                  
, TOTAL_DAP DECIMAL  (18,2)                 
, TOTAL_SHIP_CH DECIMAL (18,2)                  
, TOTAL_COST DECIMAL  (18,2)                 
, PRODUCTTOTALVAT DECIMAL  (18,2)                 
,TOTAL_PURCHASE_COST DECIMAL (18,2)                 
, PRODUCT_NAME varchar (500)                
, PRODQTY varchar (100)                
, PROUNIT VARCHAR( 500)                 
, PRODCOLOR varchar (100)                
, PRODSIZE varchar (100)                
, PROD_IMAGES text                 
, STATUS VARCHAR( 500)                 
, PRODUCTINTSTATUS INT                 
, PROCESSBY VARCHAR( 500)                 
, PROCESSDATE timestamp                 
, PROCESSREMARK VARCHAR(500)                 
, INVQTY INT                 
, REASON VARCHAR(100)                 
, ISCANCELBYMEMBER boolean                 
, ISRETURN boolean                
, Address text                
, PinCode VARCHAR (50)                
, CountryName VARCHAR (500)                
,JP decimal(18,0)                
,BV decimal(18,0)                
,COMPANYNAME varchar(1000)                
,pmid bigint,                
SubPrCode varchar(1000),                
Approved varchar(1000),                
dispatchdate varchar(1000),                
OrderNo varchar(1000),                
couriername varchar(1000),                
DocketNO varchar(1000),                
DateDiff int,                
MERCHANTNAME varchar(100),                
Morderid varchar(100),                
Invoiceno varchar(100),                
Distributorname varchar(100),              
PrSKUCODE Varchar(100),            
PaidViaCashWallet Decimal(18,8),                
PaidViaCahbackWallet Decimal(18,8),                
PaidViaKreazVoucher Int,                
PaidViaOnline Decimal(18,8),  
CODPAYMENT Decimal(18,8),
RefundDate varchar(50),          
RefundDateTime varchar(1000),          
RefundFileImage varchar(1000),          
DESCRIPTIONS varchar(1000),  
FULLNAME varchar(100),          
EMAILID varchar(100)) ON COMMIT DROP;
  v_query := 'INSERT INTO #TEMP  SELECT ROW_NUMBER() OVER (ORDER BY OM.ORDERDATE DESC) AS ROWNUMBER,                
POM.LOGINID,(OM.FNAME+''''+ISNULL(OM.LNAME,'''')) AS NAME,B.CLID AS BRCODE,OM.MOBILENO,                
OM.ORDERID,REPLACE(CONVERT(VARCHAR(11), OM.ORDERDATE, 106), '' '', ''-'') +'' ''+STUFF(RIGHT( CONVERT(VARCHAR,OM.ORDERDATE,100 ) ,7), 6, 0, '' '')                
ORDERDATE,OM.ORDER_QTY,OM.ORDER_DAP,OM.ORDER_NETAMT,                
(CASE WHEN OM.PAYMODE=''payumoney'' THEN ''Wallet'' ELSE OM.PAYMODE END) as PAYMODE,                
isnull(OM.Sh_City,'''') as CITY,                
OM.TOTAL_VAT,OM.INTSTATUS AS ORDERINTSTATUS,POM.POID, CONVERT(BIGINT, POM.SUBPRCODE) AS SPRID,                
POM.PRODUCT_QTY, POM.SINGLE_DAP, POM.TOTAL_DAP, POM.TOTAL_SHIP_CH, POM.TOTAL_COST,                
POM.TOTAL_VAT AS PRODUCTTOTALVAT,POM.TOTAL_PURCHASE_COST, POM.PRODUCT_NAME, POM.PRODQTY, POM.PROUNIT,                 
POM.PRODCOLOR, POM.PRODSIZE, POM.PROD_IMAGES,                 
(CASE WHEN POM.STATUS=''COMPLETED'' THEN ''Delivered'' Else POM.STATUS END),                 
POM.INTSTATUS AS PRODUCTINTSTATUS,                
POM.PROCESSBY, POM. PROCESSDATE, POM.PROCESSREMARK,ISNULL(POM.INVQTY,0) AS INVQTY,                
POM.REASON,ISNULL(POM.ISCANCELBYMEMBER,0) AS ISCANCELBYMEMBER , ISNULL(POM.ISRETURN,0) AS ISRETURN 
,ISNULL(OM.Address,'''') AS Address,ISNULL(OM.PinCode,'''') AS PinCode,ISNULL(IMS.CountryName,'''') AS CountryName,                
ISNULL(IMSP.PV,0) AS JP,ISNULL(IMSP.BV,0) AS BV,PMA.COMPANYNAME,PMA.PMID,IMSP.SubPrCode,ISNULL(OCS.Packed,'''') as Approved ,isnull(OCS.Packed+IMSP.ProcurementSLA,'''') as dispatchdate,isnull(POM.OrderNo,'''') as OrderNo,                
ISNULL(CM.Carrier_Name,'''') AS COURIERNAME,ISNULL(POM.DocketNO,'''') AS DocketNO,isnull(DATEDIFF(DAY,OM.ORDERDATE,OCS.Delivered),0) AS DateDiff,isnull(pma.COMPANYNAME,'''') AS MERCHANTNAME,POM.Morderid,POM.InvoiceNo,                
DM.COMPANYNAME,IMSP.PrSKUCODE,CASHWALLETUSED,CASHBACKWALLETUSED,VOUCHERWALLETUSED,  
ISNULL(TBL_ONLINEPAYMENTHISTORY.AMOUNT,0),CODPAYMENT,
CONVERT(VARCHAR(50) ,ISNULL(OCS.RefundDate,''1900-01-01''),106) AS RefundDate,
ISNULL(OCS.RefundDate,''1900-01-01'') As RefundDateTime,
ISNULL(OCS.RefundFileImage,'''') As  RefundFileImage,ISNULL(OM.DESCRIPTION,'''') AS DESCRIPTIONS,ISNULL( MM.FNAME,'''') as FULLNAME,ISNULL( MM.EmailID,'''') as EMAILID                
FROM TBL_ORDER_MASTER OM              
LEFT JOIN TBL_ORDERPAYMENT_HISTORY ON TBL_ORDERPAYMENT_HISTORY.ORDERID=OM.ORDERID              
LEFT JOIN TBL_ORDERONLINEREQUESTS ON TBL_ORDERONLINEREQUESTS.ORDERID=OM.ORDERID             
LEFT JOIN TBL_ONLINEPAYMENTHISTORY ON TBL_ONLINEPAYMENTHISTORY.REFERNECID=TBL_ORDERONLINEREQUESTS.TRANSACTIONID                  
LEFT JOIN TBL_PRODUCT_ORDER_MASTER POM ON POM.ORDERID = OM.ORDERID                 
JOIN PORTAL_LOGIN PL ON PL.PLID=POM.PLID                 
LEFT JOIN TBL_CUSTOMERLOGIN B ON B.LOGINID = OM.LOGINID                
LEFT JOIN IMS_CUSTOMERADDRESS IMS ON IMS.ID=B.CLID                
LEFT JOIN PORTAL_MASTER PMA ON PMA.PMID=PL.PMID                
LEFT JOIN IMS_SUBPRODUCT IMSP ON IMSP.SPRID= POM.SUBPRCODE                
LEFT JOIN TBL_COURIERMASTER CM ON CM.CMID=POM.CMID                
LEFT JOIN TBL_ORDER_CONFIRMEDSTAUS OCS ON OCS.ORDERNO=POM.ORDERNO                 
LEFT JOIN DISTRIBUTOR_MASTER DM ON B.DID=DM.PLID   
LEFT JOIN [Db_Affiliate].[Dbo].[MEMBER_MASTER] AS MM ON MM.USERNAME=B.USERNAME  
WHERE 1=1 ';
  IF (v_statustype = 1) THEN
  v_query := v_query || ' AND POM.INTSTATUS IN (4,9) ';
  ELSE
  IF (v_statustype = 2) THEN
  v_query := v_query || ' AND POM.INTSTATUS=5 ';
  ELSE
  IF (v_statustype = 3) THEN
  v_query := v_query || ' AND POM.INTSTATUS=6 ';
  ELSE
  IF (v_statustype = 10) THEN
  v_query := v_query || ' AND POM.INTSTATUS=10 ';
  END IF;
  END IF;
  END IF;
  END IF;
  IF ((v_fromdate <> '') AND (v_todate = '')) THEN
  v_query := v_query || ' AND CONVERT(DATE, OM.ORDERDATE, 105) BETWEEN  CONVERT(DATE, ''' || v_fromdate || ''', 105) AND  CONVERT(DATE, DBO.FUN_GETCURRENTDATE(), 105)';
  END IF;
  IF ((v_fromdate = '') AND (v_todate <> '')) THEN
  v_query := v_query || 'AND CONVERT(DATE, OM.ORDERDATE, 105) BETWEEN  CONVERT(DATE, ''' || v_todate || ''', 105) AND  CONVERT(DATE, DBO.FUN_GETCURRENTDATE(), 105)';
  END IF;
  IF ((v_fromdate <> '') AND (v_todate <> '')) THEN
  v_query := v_query || 'AND CONVERT(DATE, OM.ORDERDATE, 105) BETWEEN CONVERT(DATE, ''' || v_fromdate || ''', 105) AND  CONVERT(DATE, ''' || v_todate || ''', 105)';
  END IF;
  IF ((v_fromreadyfordispatch <> '') AND (v_toreadyfordispatch = '')) THEN
  v_query := v_query || ' AND CONVERT(DATE, OCS.Packed, 105) BETWEEN  CONVERT(DATE, ''' || v_fromreadyfordispatch || ''', 105) AND  CONVERT(DATE, DBO.FUN_GETCURRENTDATE(), 105)';
  END IF;
  IF ((v_fromreadyfordispatch = '') AND (v_toreadyfordispatch <> '')) THEN
  v_query := v_query || 'AND CONVERT(DATE, OCS.Packed, 105) BETWEEN  CONVERT(DATE, ''' || v_todate || ''', 105) AND  CONVERT(DATE, DBO.FUN_GETCURRENTDATE(), 105)';
  END IF;
  IF ((v_fromreadyfordispatch <> '') AND (v_toreadyfordispatch <> '')) THEN
  v_query := v_query || 'AND CONVERT(DATE, OCS.Packed, 105) BETWEEN CONVERT(DATE, ''' || v_fromreadyfordispatch || ''', 105) AND  CONVERT(DATE, ''' || v_toreadyfordispatch || ''', 105)';
  END IF;
  IF (v_merchantname <> '') THEN
  v_query := v_query || ' AND (pma.COMPANYNAME) LIKE ''%' || v_merchantname || '%'' ';
  END IF;
  IF (v_productname <> '') THEN
  v_productname := REPLACE(v_productname, '''', '''''');
  v_query := v_query || ' and POM.PRODUCT_NAME =''' || v_productname || '''';
  END IF;
  IF (v_orderid <> '') THEN
  v_query := v_query || ' AND POM.ORDERID LIKE ''%' || v_orderid || '%'' ';
  END IF;
  IF (v_status <> '') THEN
  v_query := v_query || ' AND POM.IntStatus=' || v_status || '';
  END IF;
  IF (v_orderno <> '') THEN
  v_query := v_query || ' AND POM.Morderid LIKE ''%' || v_orderno || '%'' ';
  END IF;
  IF (v_branchid > 0) THEN
  v_query := v_query || ' AND pl.PLID=' || CAST(v_branchid AS VARCHAR(20)) || '';
  END IF;
  IF (v_loginid <> '') THEN
  v_query := v_query || ' AND B.loginid=' || CAST(v_loginid AS VARCHAR(20)) || '';
  END IF;
  EXECUTE v_query;
  RAISE NOTICE '%', (v_query);
  RETURN QUERY SELECT * FROM tmp_temp WHERE rownumber BETWEEN v_minindex AND v_maxindex ORDER BY rownumber ASC NULLS FIRST;
  SELECT COUNT(DISTINCT orderid) INTO v_totalcount FROM tmp_temp;
  DROP TABLE IF EXISTS tmp_temp;
  -- SET option (removed)
END;
$$;


--
-- Name: usp_order_list_distributor(integer, integer, character varying, character varying, character varying, character varying, character varying, character varying, bigint, integer, character varying, character varying, character varying, character varying, character varying, character varying, character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_order_list_distributor(v_startrowindex integer DEFAULT 1, v_maxrows integer DEFAULT 100, v_searchfield character varying DEFAULT ''::character varying, v_searchvalue character varying DEFAULT ''::character varying, v_fromdate character varying DEFAULT ''::character varying, v_todate character varying DEFAULT ''::character varying, v_status character varying DEFAULT ''::character varying, v_statustype character varying DEFAULT '1'::character varying, v_branchid bigint DEFAULT 1048, v_totalcount integer DEFAULT 0, v_fromreadyfordispatch character varying DEFAULT ''::character varying, v_toreadyfordispatch character varying DEFAULT ''::character varying, v_orderid character varying DEFAULT ''::character varying, v_orderno character varying DEFAULT ''::character varying, v_merchantname character varying DEFAULT ''::character varying, v_productname character varying DEFAULT ''::character varying, v_loginid character varying DEFAULT ''::character varying) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_minindex INT;
  v_maxindex INT;
  v_query text;
BEGIN
  v_minindex := (v_startrowindex - 1) * v_maxrows + 1;
  v_maxindex := v_startrowindex * v_maxrows;
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp (ROWNUMBER BIGINT 
, LOGINID VARCHAR( 100) 
, NAME VARCHAR(1000) 
, BRCODE VARCHAR( 50) 
, MOBILENO VARCHAR(20) 
, ORDERID VARCHAR( 50) 
, ORDERDATE timestamp 
, ORDER_QTY INT 
, ORDER_DAP DECIMAL 
, ORDER_NETAMT DECIMAL
, PAYMODE VARCHAR( 25) 
, CITY VARCHAR(300) 
, TOTAL_VAT DECIMAL 
, ORDERINTSTATUS INT 
, POID BIGINT 
, SPRID BIGINT 
, PRODUCT_QTY INT 
, SINGLE_DAP DECIMAL 
, TOTAL_DAP DECIMAL 
, TOTAL_SHIP_CH DECIMAL 
, TOTAL_COST DECIMAL 
, PRODUCTTOTALVAT DECIMAL 
,TOTAL_PURCHASE_COST DECIMAL
, PRODUCT_NAME varchar (500)
, PRODQTY varchar (100)
, PROUNIT VARCHAR( 500) 
, PRODCOLOR varchar (100)
, PRODSIZE varchar (100)
, PROD_IMAGES text 
, STATUS VARCHAR( 500) 
, PRODUCTINTSTATUS INT 
, PROCESSBY VARCHAR( 500) 
, PROCESSDATE timestamp 
, PROCESSREMARK VARCHAR(500) 
, INVQTY INT 
, REASON VARCHAR(100) 
, ISCANCELBYMEMBER boolean 
, ISRETURN boolean
, Address text
, PinCode VARCHAR (50)
, CountryName VARCHAR (500)
,JP decimal(18,0)
,BV decimal(18,0),
SubPrCode varchar(1000),
Approved varchar(1000),
dispatchdate varchar(1000),
OrderNo varchar(1000),
couriername varchar(1000),
DocketNO varchar(1000),
DateDiff int,
Commission decimal(18,2),
BVPERCENTAGE DECIMAL(18,2),
Invoiceno varchar(200)) ON COMMIT DROP;
  IF (v_statustype = 1) THEN
  v_query := 'INSERT INTO #TEMP  SELECT ROW_NUMBER() OVER (ORDER BY OM.ORDERDATE DESC) AS ROWNUMBER,
POM.LOGINID,(OM.FNAME+''''+ISNULL(OM.LNAME,'''')) AS NAME,B.CLID AS BRCODE,OM.MOBILENO,
OM.ORDERID,OM.ORDERDATE,OM.ORDER_QTY,OM.ORDER_DAP,OM.ORDER_NETAMT,OM.PAYMODE,isnull(OM.Sh_City,'''') as CITY,
OM.TOTAL_VAT,OM.INTSTATUS AS ORDERINTSTATUS,POM.POID, CONVERT(BIGINT, POM.SUBPRCODE) AS SPRID,
POM.PRODUCT_QTY, POM.SINGLE_DAP, POM.TOTAL_DAP, POM.TOTAL_SHIP_CH, POM.TOTAL_COST,
POM.TOTAL_VAT AS PRODUCTTOTALVAT,POM.TOTAL_PURCHASE_COST, POM.PRODUCT_NAME, POM.PRODQTY, POM.PROUNIT, 
POM.PRODCOLOR, POM.PRODSIZE, POM.PROD_IMAGES, POM.STATUS, POM.INTSTATUS AS PRODUCTINTSTATUS,
POM.PROCESSBY, POM. PROCESSDATE, POM.PROCESSREMARK,ISNULL(POM.INVQTY,0) AS INVQTY,
POM.REASON,ISNULL(POM.ISCANCELBYMEMBER,0) AS ISCANCELBYMEMBER , ISNULL(POM.ISRETURN,0) AS ISRETURN ,isnull(OM.Address,'''') AS Address,ISNULL(OM.PinCode,'''') AS PinCode,ISNULL(IMS.CountryName,'''') AS CountryName,
isnull(IMSP.PV,0) AS JP,ISNULL(IMSP.BV,0) AS BV,IMSP.SubPrCode,isnull(OCS.Packed,'''') as Approved ,isnull(OCS.Packed+IMSP.ProcurementSLA,'''') as dispatchdate,isnull(POM.OrderNo,'''') as OrderNo,
ISNULL(CM.Carrier_Name,'''') AS couriername,isnull(POM.DocketNO,'''') AS DocketNO,isnull(DATEDIFF(DAY,OM.ORDERDATE,OCS.Delivered),0) AS DateDiff,
ISNULL(POM.RESELLERCOMMISSION,0),ISNULL(TRBVD.BVPERCENTAGE,0),POM.Invoiceno
FROM TBL_ORDER_MASTER OM 
LEFT JOIN TBL_PRODUCT_ORDER_MASTER POM ON POM.ORDERID = OM.ORDERID 
--join PORTAL_LOGIN pl on pl.PLID=OM.BranchId 
JOIN TBL_CUSTOMERLOGIN B ON B.LOGINID = OM.LoginId
left join IMS_CustomerAddress IMS on IMS.Id=B.CLID
--left join Portal_Master pma on pma.PMID=pl.PMID
left join IMS_SubProduct IMSP on IMSP.SPRID= POM.SubPrCode
left join tbl_couriermaster CM on CM.CMID=POM.CMID
JOIN TBL_DISTRIBUTOR TD ON TD.DID=B.DID
left join tbl_Order_ConfirmedStaus OCS on OCS.orderno=POM.orderno 
LEFT JOIN TBL_RESELLER_BV_PV_DETAILS TRBVD ON POM.ORDERNO=TRBVD.ORDERNO
where POM.IntStatus in (4,9)';
  END IF;
  IF (v_statustype = 2) THEN
  v_query := 'INSERT INTO #TEMP  SELECT ROW_NUMBER() OVER (ORDER BY OM.ORDERDATE DESC) AS ROWNUMBER,
POM.LOGINID,(OM.FNAME+''''+ISNULL(OM.LNAME,'''')) AS NAME,B.CLID AS BRCODE,OM.MOBILENO,
OM.ORDERID,OM.ORDERDATE,OM.ORDER_QTY,OM.ORDER_DAP,OM.ORDER_NETAMT,OM.PAYMODE,isnull(OM.Sh_City,'''') as CITY,
OM.TOTAL_VAT,OM.INTSTATUS AS ORDERINTSTATUS,POM.POID, CONVERT(BIGINT, POM.SUBPRCODE) AS SPRID,
POM.PRODUCT_QTY, POM.SINGLE_DAP, POM.TOTAL_DAP, POM.TOTAL_SHIP_CH, POM.TOTAL_COST,
POM.TOTAL_VAT AS PRODUCTTOTALVAT,POM.TOTAL_PURCHASE_COST, POM.PRODUCT_NAME, POM.PRODQTY, POM.PROUNIT, 
POM.PRODCOLOR, POM.PRODSIZE, POM.PROD_IMAGES, POM.STATUS, POM.INTSTATUS AS PRODUCTINTSTATUS,
POM.PROCESSBY, POM. PROCESSDATE, POM.PROCESSREMARK,ISNULL(POM.INVQTY,0) AS INVQTY,
POM.REASON,ISNULL(POM.ISCANCELBYMEMBER,0) AS ISCANCELBYMEMBER , ISNULL(POM.ISRETURN,0) AS ISRETURN ,isnull(OM.Address,'''') AS Address,ISNULL(OM.PinCode,'''') AS PinCode,ISNULL(IMS.CountryName,'''') AS CountryName,
isnull(IMSP.PV,0) AS JP,ISNULL(IMSP.BV,0) AS BV,IMSP.SubPrCode,isnull(OCS.Packed,'''') as Approved ,isnull(OCS.Packed+IMSP.ProcurementSLA,'''') as dispatchdate,isnull(POM.OrderNo,'''') as OrderNo,
ISNULL(CM.Carrier_Name,'''') AS couriername,isnull(POM.DocketNO,'''') AS DocketNO,isnull(DATEDIFF(DAY,OM.ORDERDATE,OCS.Delivered),0) AS DateDiff,
ISNULL(POM.RESELLERCOMMISSION,0),ISNULL(TRBVD.BVPERCENTAGE,0),POM.Invoiceno
FROM TBL_ORDER_MASTER OM 
LEFT JOIN TBL_PRODUCT_ORDER_MASTER POM ON POM.ORDERID = OM.ORDERID 
--join PORTAL_LOGIN pl on pl.PLID=OM.BranchId 
JOIN TBL_CUSTOMERLOGIN B ON B.LOGINID = OM.LoginId
left join IMS_CustomerAddress IMS on IMS.Id=B.CLID
--left join Portal_Master pma on pma.PMID=pl.PMID
left join IMS_SubProduct IMSP on IMSP.SPRID= POM.SubPrCode
left join tbl_couriermaster CM on CM.CMID=POM.CMID
JOIN TBL_DISTRIBUTOR TD ON TD.DID=B.DID
left join tbl_Order_ConfirmedStaus OCS on OCS.orderno=POM.orderno 
LEFT JOIN TBL_RESELLER_BV_PV_DETAILS TRBVD ON POM.ORDERNO=TRBVD.ORDERNO
WHERE  POM.IntStatus=5';
  END IF;
  IF (v_statustype = 3) THEN
  v_query := 'INSERT INTO #TEMP  SELECT ROW_NUMBER() OVER (ORDER BY OM.ORDERDATE DESC) AS ROWNUMBER,
POM.LOGINID,(OM.FNAME+''''+ISNULL(OM.LNAME,'''')) AS NAME,B.CLID AS BRCODE,OM.MOBILENO,
OM.ORDERID,OM.ORDERDATE,OM.ORDER_QTY,OM.ORDER_DAP,OM.ORDER_NETAMT,OM.PAYMODE,isnull(OM.Sh_City,'''') as CITY,
OM.TOTAL_VAT,OM.INTSTATUS AS ORDERINTSTATUS,POM.POID, CONVERT(BIGINT, POM.SUBPRCODE) AS SPRID,
POM.PRODUCT_QTY, POM.SINGLE_DAP, POM.TOTAL_DAP, POM.TOTAL_SHIP_CH, POM.TOTAL_COST,
POM.TOTAL_VAT AS PRODUCTTOTALVAT,POM.TOTAL_PURCHASE_COST, POM.PRODUCT_NAME, POM.PRODQTY, POM.PROUNIT, 
POM.PRODCOLOR, POM.PRODSIZE, POM.PROD_IMAGES, POM.STATUS, POM.INTSTATUS AS PRODUCTINTSTATUS,
POM.PROCESSBY, POM. PROCESSDATE, POM.PROCESSREMARK,ISNULL(POM.INVQTY,0) AS INVQTY,
POM.REASON,ISNULL(POM.ISCANCELBYMEMBER,0) AS ISCANCELBYMEMBER , ISNULL(POM.ISRETURN,0) AS ISRETURN ,isnull(OM.Address,'''') AS Address,ISNULL(OM.PinCode,'''') AS PinCode,ISNULL(IMS.CountryName,'''') AS CountryName,
isnull(IMSP.PV,0) AS JP,ISNULL(IMSP.BV,0) AS BV,IMSP.SubPrCode,isnull(OCS.Packed,'''') as Approved ,isnull(OCS.Packed+IMSP.ProcurementSLA,'''') as dispatchdate,isnull(POM.OrderNo,'''') as OrderNo,
ISNULL(CM.Carrier_Name,'''') AS couriername,isnull(POM.DocketNO,'''') AS DocketNO,
isnull(DATEDIFF(day,(case when OCS.CreatedDate=''1900-01-01 00:00:00.000'' then Getdate() else OCS.CreatedDate end),
(case when OCS.Delivered=''1900-01-01 00:00:00.000'' then OCS.CreatedDate else OCS.Delivered end)),0) AS DateDiff,
ISNULL(POM.RESELLERCOMMISSION,0),ISNULL(TRBVD.BVPERCENTAGE,0),POM.Invoiceno
FROM TBL_ORDER_MASTER OM 
LEFT JOIN TBL_PRODUCT_ORDER_MASTER POM ON POM.ORDERID = OM.ORDERID 
--join PORTAL_LOGIN pl on pl.PLID=OM.BranchId 
JOIN TBL_CUSTOMERLOGIN B ON B.LOGINID = OM.LoginId
left join IMS_CustomerAddress IMS on IMS.Id=B.CLID
--left join Portal_Master pma on pma.PMID=pl.PMID
left join IMS_SubProduct IMSP on IMSP.SPRID= POM.SubPrCode
left join tbl_couriermaster CM on CM.CMID=POM.CMID
JOIN TBL_DISTRIBUTOR TD ON TD.DID=B.DID
left join tbl_Order_ConfirmedStaus OCS on OCS.orderno=POM.orderno 
LEFT JOIN TBL_RESELLER_BV_PV_DETAILS TRBVD ON POM.ORDERNO=TRBVD.ORDERNO
WHERE  POM.IntStatus=6';
  END IF;
  IF ((v_fromdate <> '') AND (v_todate = '')) THEN
  v_query := v_query || ' AND CONVERT(DATE, OM.ORDERDATE, 105) BETWEEN  CONVERT(DATE, ''' || v_fromdate || ''', 105) AND  CONVERT(DATE, DBO.FUN_GETCURRENTDATE(), 105)';
  END IF;
  IF ((v_fromdate = '') AND (v_todate <> '')) THEN
  v_query := v_query || 'AND CONVERT(DATE, OM.ORDERDATE, 105) BETWEEN  CONVERT(DATE, ''' || v_todate || ''', 105) AND  CONVERT(DATE, DBO.FUN_GETCURRENTDATE(), 105)';
  END IF;
  IF ((v_fromdate <> '') AND (v_todate <> '')) THEN
  v_query := v_query || 'AND CONVERT(DATE, OM.ORDERDATE, 105) BETWEEN CONVERT(DATE, ''' || v_fromdate || ''', 105) AND  CONVERT(DATE, ''' || v_todate || ''', 105)';
  END IF;
  IF ((v_fromreadyfordispatch <> '') AND (v_toreadyfordispatch = '')) THEN
  v_query := v_query || ' AND CONVERT(DATE, OCS.Packed, 105) BETWEEN  CONVERT(DATE, ''' || v_fromreadyfordispatch || ''', 105) AND  CONVERT(DATE, DBO.FUN_GETCURRENTDATE(), 105)';
  END IF;
  IF ((v_fromreadyfordispatch = '') AND (v_toreadyfordispatch <> '')) THEN
  v_query := v_query || 'AND CONVERT(DATE, OCS.Packed, 105) BETWEEN  CONVERT(DATE, ''' || v_todate || ''', 105) AND  CONVERT(DATE, DBO.FUN_GETCURRENTDATE(), 105)';
  END IF;
  IF ((v_fromreadyfordispatch <> '') AND (v_toreadyfordispatch <> '')) THEN
  v_query := v_query || 'AND CONVERT(DATE, OCS.Packed, 105) BETWEEN CONVERT(DATE, ''' || v_fromreadyfordispatch || ''', 105) AND  CONVERT(DATE, ''' || v_toreadyfordispatch || ''', 105)';
  END IF;
  IF (v_productname <> '') THEN
  v_productname := REPLACE(v_productname, '''', '''''');
  v_query := v_query || ' and POM.PRODUCT_NAME =''' || v_productname || '''';
  END IF;
  IF (v_orderid <> '') THEN
  v_query := v_query || ' AND POM.ORDERID LIKE ''%' || v_orderid || '%'' ';
  END IF;
  IF (v_status <> '') THEN
  v_query := v_query || ' AND POM.IntStatus=' || v_status || '';
  END IF;
  IF (v_orderno <> '') THEN
  v_query := v_query || ' AND POM.Orderno LIKE ''%' || v_orderno || '%'' ';
  END IF;
  IF (v_branchid > 0) THEN
  v_query := v_query || ' AND td.did=' || CAST(v_branchid AS VARCHAR(20)) || '';
  END IF;
  IF (v_loginid <> '') THEN
  v_query := v_query || ' AND B.loginid=' || CAST(v_loginid AS VARCHAR(20)) || '';
  END IF;
  EXECUTE v_query;
  RAISE NOTICE '%', (v_query);
  RETURN QUERY SELECT * FROM tmp_temp WHERE rownumber BETWEEN v_minindex AND v_maxindex;
  SELECT COUNT(rownumber) INTO v_totalcount FROM tmp_temp;
  DROP TABLE IF EXISTS tmp_temp;
  -- SET option (removed)
END;
$$;


--
-- Name: usp_orderdetails(character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_orderdetails(v_orderid character varying DEFAULT 'OD768899042'::character varying) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
BEGIN
  RETURN QUERY SELECT o.orderid, o.loginid, ('') AS custname, o.orderdate, o.order_qty, o.order_dap, o.total_ship_ch, o.order_netamt, o.total_vat, o.order_bv, (o.fname || ' ' || COALESCE(o.lname, '')) AS name, o.mobileno, o.emailid, o.address, o.pincode, o.city, (o.sh_fname || ' ' || COALESCE(o.sh_lname, '')) AS sh_name, o.sh_mobileno, o.sh_emailid, o.sh_address, o.sh_pincode, o.sh_city, o.paymode, o.paytransid, o.payremark, o.status, o.intstatus, COALESCE(0, 0) AS brcode, o.description, o.isbvdist, COALESCE(0, 0) AS walletused, COALESCE(o.order_bv, 0) AS order_bv, COALESCE(o.order_pv, 0) AS order_pv FROM tbl_order_master AS o LEFT JOIN portal_login AS m ON o.loginid = m.loginid WHERE o.orderid = v_orderid;
  RETURN QUERY SELECT po.subprcode, po.product_qty, po.single_dap, po.total_dap, po.total_ship_ch, po.total_cost, po.total_vat, po.total_bv, po.product_name, po.prodqty, po.prounit, po.prodcolor, po.prodsize, po.prod_images, po.status, po.intstatus, COALESCE(po.processby, '') AS processby, po.processdate, COALESCE(po.processremark, '') AS processremark, COALESCE(po.invqty, 0) AS invqty, COALESCE('', '') AS wunit, COALESCE(imsp.pv, 0) AS jp, COALESCE(imsp.bv, 0) AS bv FROM tbl_product_order_master AS po LEFT JOIN tbl_product_master_sub AS ps ON ps.subprcode = po.subprcode LEFT JOIN ims_subproduct AS imsp ON imsp.sprid = po.subprcode WHERE orderid = v_orderid AND COALESCE(isdeleted, 0) = 0;
  RETURN QUERY SELECT ROW_NUMBER() OVER (ORDER BY date DESC NULLS LAST) AS rowno, date, remark, brcode, emp_code FROM tbl_ordernotes WHERE orderid = v_orderid AND active = 1 ORDER BY rowno DESC NULLS LAST;
END;
$$;


--
-- Name: usp_orderdetails_for_invoice(character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_orderdetails_for_invoice(v_orderid character varying DEFAULT 'EBLAA283211311'::character varying) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
BEGIN
  RETURN QUERY SELECT pom.subprcode, pom.product_name, pom.prodqty, pom.product_qty, pom.invqty, pom.prounit, pom.single_dap, pom.total_dap, pom.total_ship_ch, pom.total_cost, pom.total_vat, om.paymode, COALESCE(imsp.pv, 0) AS jp, COALESCE(imsp.bv, 0) AS bv FROM tbl_product_order_master AS pom INNER JOIN tbl_order_master AS om ON pom.orderid = om.orderid LEFT JOIN ims_subproduct AS imsp ON imsp.sprid = pom.subprcode WHERE om.orderid = v_orderid AND pom.product_qty - pom.invqty > 0;
END;
$$;


--
-- Name: usp_orderhistory(integer, character varying, character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_orderhistory(v_plid integer DEFAULT 13, v_orderno character varying DEFAULT '436914'::character varying, v_strresult character varying DEFAULT ''::character varying) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_gstpercentage numeric(19,4);
BEGIN
  -- BEGIN TRAN (removed)
  -- SET option (removed)
  v_gstpercentage := 0;
  v_strresult := 'ok';
  IF (v_orderno = '') THEN
  -- COMMIT (removed)
  v_strresult := 'Order Number is Not Exits.';
  RETURN;
  END IF;
  IF (v_plid = 0) THEN
  -- COMMIT (removed)
  v_strresult := 'Merchant Not Exists.';
  RETURN;
  END IF;
  SELECT COALESCE(limits, 0) INTO v_gstpercentage FROM settings WHERE caption = 'GST Percentage' AND active = 1;
  RETURN QUERY SELECT ROW_NUMBER() OVER (ORDER BY om.orderdate DESC NULLS LAST) AS rownumber, pom.loginid, (om.fname || '' || COALESCE(om.lname, '')) AS name, b.clid AS brcode, om.mobileno, om.orderid, CAST(TO_CHAR(om.orderdate, 'DD TMMon YYYY') AS VARCHAR(50)) AS orderdate, om.order_qty, om.order_dap, om.order_netamt, om.paymode, COALESCE(om.sh_city, '') AS city, om.total_vat, om.intstatus AS orderintstatus, pom.poid, CAST(pom.subprcode AS BIGINT) AS sprid, pom.product_qty, pom.single_dap, ((pom.single_dap * imsp.admincharge) / 100) AS admincharge, pom.total_dap, pom.total_ship_ch, pom.total_cost, pom.total_vat AS producttotalvat, pom.total_purchase_cost, pom.product_name, pom.prodqty, pom.prounit, pom.prodcolor, pom.prodsize, pom.prod_images, pom.status, pom.intstatus AS productintstatus, pom.processby, pom.processdate, pom.processremark, COALESCE(pom.invqty, 0) AS invqty, pom.reason, COALESCE(pom.iscancelbymember, 0) AS iscancelbymember, COALESCE(pom.isreturn, 0) AS isreturn, COALESCE(om.address, '') AS address, COALESCE(om.pincode, '') AS pincode, COALESCE(ims.countryname, '') AS countryname, COALESCE(imsp.pv, 0) AS jp, COALESCE(imsp.bv, 0) AS bv, pma.companyname, pma.pmid, imsp.subprcode, COALESCE(ocs.packed, '') AS approved, COALESCE(ocs.packed + imsp.procurementsla, '') AS dispatchdate, imsp.procurementsla, COALESCE(ocs.orderno, '') AS orderno, COALESCE(cm.carrier_name, '') AS couriername, COALESCE(pom.docketno, '') AS docketno, COALESCE(CAST(EXTRACT(epoch FROM CAST(CAST(ocs.delivered AS TIMESTAMP) AS TIMESTAMP) - CAST(CAST(om.orderdate AS TIMESTAMP) AS TIMESTAMP)) / 86400 AS BIGINT), 0) AS datediff, CAST(TO_CHAR(ocs.createddate, 'DD TMMon YYYY') AS VARCHAR(30)) AS createddate, CAST(TO_CHAR(ocs.packed, 'DD TMMon YYYY') AS VARCHAR(30)) AS packed, CAST(TO_CHAR(ocs.handover, 'DD TMMon YYYY') AS VARCHAR(30)) AS handover, CAST(TO_CHAR(ocs.intransit, 'DD TMMon YYYY') AS VARCHAR(30)) AS intransit, CAST(TO_CHAR(ocs.picked, 'DD TMMon YYYY') AS VARCHAR(30)) AS picked, CAST(TO_CHAR(ocs.delivered, 'DD TMMon YYYY') AS VARCHAR(30)) AS delivered, ((((pom.single_dap * imsp.admincharge) / 100) + imsp.delieverycharge + imsp.handlingcharge + imsp.fixedfee) * v_gstpercentage / 100) AS totalgst, (((pom.single_dap * imsp.admincharge) / 100) + imsp.delieverycharge + imsp.handlingcharge + imsp.fixedfee) AS marketplacefee, COALESCE((pom.single_dap * imsp.admincharge) / 100, 0) AS admincharge, imsp.delieverycharge, imsp.handlingcharge, imsp.fixedfee, COALESCE((pom.single_dap * imsp.admincharge) / 100, 0) * v_gstpercentage / 100 AS admingst, (imsp.delieverycharge * v_gstpercentage / 100) AS deleverygst, (imsp.handlingcharge * v_gstpercentage / 100) AS handlinggst, (imsp.fixedfee * v_gstpercentage / 100) AS fixedfeegst, imsp.admincharge AS adminchargepercentage FROM tbl_order_master AS om LEFT JOIN tbl_product_order_master AS pom ON pom.orderid = om.orderid JOIN portal_login AS pl ON pl.plid = om.branchid JOIN tbl_customerlogin AS b ON b.loginid = om.loginid LEFT JOIN ims_customeraddress AS ims ON ims.id = b.clid LEFT JOIN portal_master AS pma ON pma.pmid = pl.pmid LEFT JOIN ims_subproduct AS imsp ON imsp.sprid = pom.subprcode LEFT JOIN tbl_couriermaster AS cm ON cm.cmid = pom.cmid LEFT JOIN tbl_order_confirmedstaus AS ocs ON ocs.orderno = pom.orderno LEFT JOIN merchant_payout AS mp ON pom.plid = mp.plid WHERE pl.plid = v_plid AND pom.orderno = v_orderno;
  v_strresult := 'ok';
  -- SET option (removed)
  -- COMMIT (removed)
END;
$$;


--
-- Name: usp_orderonlinerequests(integer, numeric, character varying, character varying, character varying, character varying, character varying, character varying, character varying, character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_orderonlinerequests(v_clid integer DEFAULT 0, v_amount numeric DEFAULT 0, v_orderid character varying DEFAULT ''::character varying, v_source character varying DEFAULT ''::character varying, v_successurl character varying DEFAULT ''::character varying, v_failureurl character varying DEFAULT ''::character varying, v_inprocessurl character varying DEFAULT ''::character varying, v_cancelledurl character varying DEFAULT ''::character varying, INOUT v_stroutput character varying DEFAULT ''::character varying, INOUT v_transactionid character varying DEFAULT ''::character varying) RETURNS record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_transid VARCHAR(50);
  v_loginid VARCHAR(50);
BEGIN
  BEGIN
  -- BEGIN TRAN (removed)
  IF (v_amount = 0) THEN
  v_stroutput := 'Amount should be greater than zero.';
  -- COMMIT (removed)
  RETURN;
  END IF;
  IF (v_amount < 0) THEN
  v_stroutput := 'Amount should be greater than zero.';
  -- COMMIT (removed)
  RETURN;
  END IF;
  IF (v_clid <> 0) THEN
  IF EXISTS(SELECT 1 FROM tbl_customerlogin WHERE clid = v_clid) THEN
  v_transid := '';
  v_loginid := '';
  IF (v_source <> 'Recharge') THEN
  v_transid := CAST(CAST(GEN_RANDOM_UUID() AS BYTEA(5)) AS BIGINT) % 1000000000 + 1000000000;
  ELSE
  v_transid := v_orderid;
  END IF;
  SELECT COALESCE(loginid, '') INTO v_loginid FROM tbl_customerlogin WHERE clid = v_clid;
  IF EXISTS(SELECT 1 FROM tbl_orderonlinerequests WHERE transactionid = v_transid) THEN
  v_stroutput := 'Error';
  -- ROLLBACK (removed)
  RETURN;
  ELSE
  INSERT INTO tbl_orderonlinerequests (clid, loginid, orderid, transactionid, amount, processdatetime, source, successurl, failureurl, inprocessurl, cancelledurl, status, active) VALUES (v_clid, v_loginid, v_orderid, v_transid, v_amount, dbo.FUN_GETCURRENTDATE(), v_source, v_successurl, v_failureurl, v_inprocessurl, v_cancelledurl, 0, 1);
  v_stroutput := 'Success';
  v_transactionid := v_transid;
  -- COMMIT (removed)
  END IF;
  ELSE
  v_stroutput := 'Invalid customer.';
  -- COMMIT (removed)
  RETURN;
  END IF;
  END IF;
  EXCEPTION WHEN OTHERS THEN
  IF (0 <> 0) THEN
  v_stroutput := 'Error';
  -- ROLLBACK (removed)
  RETURN;
  END IF;
  END;
END;
$$;


