CREATE FUNCTION dbo.usp_orderpaymentrequestapprove(v_orderid character varying DEFAULT ''::character varying, v_status integer DEFAULT 0, INOUT v_totalcount integer DEFAULT 0) RETURNS integer
    LANGUAGE plpgsql
    AS $$
BEGIN
  -- BEGIN TRAN (removed)
  -- SET option (removed)
  IF (v_status = 1) THEN
  UPDATE tbl_orderpaymentsdetails SET status = v_status WHERE orderid = v_orderid;
  v_totalcount := 1;
  ELSE
  UPDATE tbl_orderpaymentsdetails SET status = v_status WHERE orderid = v_orderid;
  v_totalcount := 1;
  END IF;
  IF (0 <> 0) THEN
  v_totalcount := 0;
  -- ROLLBACK (removed)
  RETURN;
  END IF;
  -- COMMIT (removed)
  -- SET option (removed)
END;
$$;


--
-- Name: usp_orderpaymentsdetails_reseller(integer, integer, character varying, character varying, character varying, character varying, integer, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_orderpaymentsdetails_reseller(v_startrowindex integer DEFAULT 1, v_maxrows integer DEFAULT 100, v_searchfield character varying DEFAULT ''::character varying, v_searchvalue character varying DEFAULT ''::character varying, v_fromdate character varying DEFAULT ''::character varying, v_todate character varying DEFAULT ''::character varying, v_did integer DEFAULT 8, v_totalcount integer DEFAULT 0) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_minindex INT;
  v_maxindex INT;
  v_query text;
BEGIN
  v_minindex := (v_startrowindex - 1) * v_maxrows + 1;
  v_maxindex := v_startrowindex * v_maxrows;
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp (ROWNUMBER INT,        
	DATE  timestamp,	
	CUSTOMERID VARCHAR(500),				         
    ORDERID  VARCHAR(500),						         
    TRANSID VARCHAR(500),
	CUSTOMERWALLET DECIMAL(18,2),
	MLMWALLET DECIMAL(18,2),
	STATUS VARCHAR(50),
	AMOUNT DECIMAL(18,2),
	ONLINEPAYMENT Decimal(18,2)) ON COMMIT DROP;
  v_query := 'INSERT INTO #TEMP SELECT ROW_NUMBER() OVER(ORDER BY PD.PAYMENTDATE DESC) AS ROWNUMBER,PD.PAYMENTDATE AS DATE,CL.LOGINID AS CUSTOMERID,
	 PD.ORDERID,PD.TRANSID,PD.CUSTOMERWALLET,PD.MLMWALLET,
	 CASE WHEN PD.STATUS=1 THEN ''APPROVED'' WHEN PD.STATUS=2 THEN ''REJECTED'' END AS STATUS ,OM.ORDER_NETAMT AS AMOUNT,
	 ISNULL(PD.OnlinePayment,0)
	 FROM TBL_ORDERPAYMENTSDETAILS AS PD
	 INNER JOIN TBL_ORDER_MASTER AS OM ON PD.ORDERID=OM.ORDERID
	 INNER JOIN TBL_CUSTOMERLOGIN AS CL ON CL.LOGINID=OM.LOGINID WHERE 1=1 and OM.INTSTATUS=6';
  IF ((v_fromdate <> '') AND (v_todate = '')) THEN
  v_query := v_query || ' AND CONVERT(VARCHAR(20), PD.PAYMENTDATE, 106) BETWEEN  CONVERT(VARCHAR(20), ''' || v_fromdate || ''', 106) AND  CONVERT(VARCHAR(20), DBO.FUN_GETCURRENTDATE(), 106)';
  END IF;
  IF ((v_fromdate = '') AND (v_todate <> '')) THEN
  v_query := v_query || 'AND CONVERT(VARCHAR(20), PD.PAYMENTDATE, 106) BETWEEN  CONVERT(VARCHAR(20), ''' || v_todate || ''', 106) AND  CONVERT(VARCHAR(20), DBO.FUN_GETCURRENTDATE(), 106)';
  END IF;
  IF ((v_fromdate <> '') AND (v_todate <> '')) THEN
  v_query := v_query || 'AND CONVERT(VARCHAR(20), PD.PAYMENTDATE, 106) BETWEEN CONVERT(VARCHAR(20), ''' || v_fromdate || ''', 106) AND  CONVERT(VARCHAR(20), ''' || v_todate || ''', 106)';
  END IF;
  IF (v_did > 0) THEN
  v_query := v_query || ' AND CL.DID=' || CAST(v_did AS VARCHAR(20)) || '';
  END IF;
  IF (v_searchfield = 'LOGINID') THEN
  v_query := v_query || ' AND CL.LOGINID= ''' || v_searchvalue || ''' ';
  END IF;
  IF (v_searchfield = 'NAME') THEN
  v_query := v_query || ' AND (CL.FNAME+'' ''+CL.LNAME) = ''' || v_searchvalue || ''' ';
  END IF;
  IF (v_searchfield = 'EMAILID') THEN
  v_query := v_query || ' AND CL.EMAILID = ''' || v_searchvalue || ''' ';
  END IF;
  IF (v_searchfield = 'PHONE') THEN
  v_query := v_query || ' AND CL.PHONE= ''' || v_searchvalue || ''' ';
  END IF;
  EXECUTE v_query;
  RETURN QUERY SELECT * FROM tmp_temp WHERE rownumber BETWEEN v_minindex AND v_maxindex;
  SELECT COUNT(rownumber) INTO v_totalcount FROM tmp_temp;
  DROP TABLE IF EXISTS tmp_temp;
  -- SET option (removed)
END;
$$;


--
-- Name: usp_orderpaymentsdetails_reseller_admin(integer, integer, character varying, character varying, character varying, character varying, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_orderpaymentsdetails_reseller_admin(v_startrowindex integer DEFAULT 1, v_maxrows integer DEFAULT 100, v_searchfield character varying DEFAULT ''::character varying, v_searchvalue character varying DEFAULT ''::character varying, v_fromdate character varying DEFAULT ''::character varying, v_todate character varying DEFAULT ''::character varying, v_totalcount integer DEFAULT 0) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_minindex int;
  v_maxindex int;
  v_query text;
BEGIN
  v_minindex := (v_startrowindex - 1) * v_maxrows + 1;
  v_maxindex := v_startrowindex * v_maxrows;
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp (ROWNUMBER int,        
	Date  timestamp,	
	CustomerID varchar(500),				         
    ORDERID  varchar(500),						         
    TRANSID varchar(500),
	CUSTOMERWALLET decimal(18,2),
	MLMWALLET decimal(18,2),
	Status varchar(50),
	Amount decimal(18,2),
	Resellername varchar(100),
	ResellerID varchar(50)) ON COMMIT DROP;
  v_query := 'insert into #temp select ROW_NUMBER() over(order by PD.PAYMENTDATE desc) as ROWNUMBER,PD.PAYMENTDATE as Date,CL.LOGINID as CustomerID,PD.ORDERID,PD.TRANSID,PD.CUSTOMERWALLET,PD.MLMWALLET,
				case when PD.STATUS=1 then ''Approved'' when PD.STATUS=2 then ''Rejected'' end as Status ,OM.Order_NetAmt as Amount,DM.FNAME as Resellername,DM.USERID as ResellerID
				from TBL_ORDERPAYMENTSDETAILS as PD
				inner join tbl_order_master as OM on PD.ORDERID=OM.ORDERID
				inner join tbl_customerlogin as CL on CL.loginid=OM.Loginid 
				inner join TBL_DISTRIBUTOR as DM on DM.DID=CL.DID
				WHERE 1=1';
  IF ((v_fromdate <> '') AND (v_todate = '')) THEN
  v_query := v_query || ' AND CONVERT(VARCHAR(20), PD.PAYMENTDATE, 106) BETWEEN  CONVERT(VARCHAR(20), ''' || v_fromdate || ''', 106) AND  CONVERT(VARCHAR(20), DBO.FUN_GETCURRENTDATE(), 106)';
  END IF;
  IF ((v_fromdate = '') AND (v_todate <> '')) THEN
  v_query := v_query || 'AND CONVERT(VARCHAR(20), PD.PAYMENTDATE, 106) BETWEEN  CONVERT(VARCHAR(20), ''' || v_todate || ''', 106) AND  CONVERT(VARCHAR(20), DBO.FUN_GETCURRENTDATE(), 106)';
  END IF;
  IF ((v_fromdate <> '') AND (v_todate <> '')) THEN
  v_query := v_query || 'AND CONVERT(VARCHAR(20), PD.PAYMENTDATE, 106) BETWEEN CONVERT(VARCHAR(20), ''' || v_fromdate || ''', 106) AND  CONVERT(VARCHAR(20), ''' || v_todate || ''', 106)';
  END IF;
  IF (v_searchfield = 'LOGINID') THEN
  v_query := v_query || ' AND DM.USERID= ''' || v_searchvalue || ''' ';
  END IF;
  IF (v_searchfield = 'NAME') THEN
  v_query := v_query || ' AND (DM.FNAME+'' ''+DM.LNAME) = ''' || v_searchvalue || ''' ';
  END IF;
  IF (v_searchfield = 'Emailid') THEN
  v_query := v_query || ' AND DM.EMAILID = ''' || v_searchvalue || ''' ';
  END IF;
  IF (v_searchfield = 'PHONE') THEN
  v_query := v_query || ' AND DM.PHONE= ''' || v_searchvalue || ''' ';
  END IF;
  EXECUTE v_query;
  RETURN QUERY SELECT * FROM tmp_temp WHERE rownumber BETWEEN v_minindex AND v_maxindex;
  SELECT COUNT(rownumber) INTO v_totalcount FROM tmp_temp;
  DROP TABLE IF EXISTS tmp_temp;
  -- SET option (removed)
END;
$$;


--
-- Name: usp_outofstockhitsdata(bigint, bigint, bigint, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_outofstockhitsdata(v_sprid bigint DEFAULT 7, v_mprid bigint DEFAULT 7, v_plid bigint DEFAULT 1, v_intresult integer DEFAULT 0) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_noofattempts int;
BEGIN
  -- SET option (removed)
  v_noofattempts := 1;
  IF NOT EXISTS(SELECT 1 FROM tbl_outofstockhitsdata WHERE sprid = v_sprid AND mprid = v_mprid AND plid = v_plid) THEN
  RETURN QUERY SELECT 1;
  INSERT INTO tbl_outofstockhitsdata (sprid, mprid, plid, status, noofattempts, addeddate, modifydate) VALUES (v_sprid, v_mprid, v_plid, 1, v_noofattempts, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  v_intresult := 1;
  ELSE
  RETURN QUERY SELECT 2;
  UPDATE tbl_outofstockhitsdata SET modifydate = CURRENT_TIMESTAMP, noofattempts = noofattempts + v_noofattempts WHERE sprid = v_sprid AND mprid = v_mprid AND plid = v_plid;
  v_intresult := 1;
  END IF;
  -- SET option (removed)
END;
$$;


--
-- Name: usp_outsourcecustomer(integer, integer, character varying, character varying, integer, character varying, character varying, character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_outsourcecustomer(v_fromindex integer DEFAULT 1, v_toindex integer DEFAULT 50, v_fromdate character varying DEFAULT ''::character varying, v_todate character varying DEFAULT ''::character varying, v_totalrecord integer DEFAULT 0, v_country character varying DEFAULT 'India'::character varying, v_state character varying DEFAULT ''::character varying, v_city character varying DEFAULT ''::character varying) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_query text;
  v_minindex INT;
  v_maxindex INT;
BEGIN
  -- SET option (removed)
  v_query := '';
  v_minindex := (v_fromindex - 1) * v_toindex + 1;
  v_maxindex := v_fromindex * v_toindex;
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp (RowNumber Bigint GENERATED BY DEFAULT AS IDENTITY,
OSID int,
DID int,
TOKENID int,
PREVIOUSURL varchar(100),
IPADDRESS varchar(100),
CREATE_DATE timestamp,
state varchar(100),
city varchar(100),
country varchar(100)) ON COMMIT DROP;
  v_query := 'SELECT OSID,DID,TOKENID,PREVIOUSURL,IPADDRESS,CAST(CREATE_DATE AS DATETIME) ,isnull(state,''''),isnull(city,''''),
isnull(country,'''')
FROM TBL_OTHERSITESOURE_LOG WHERE STATUS=1';
  IF (v_fromdate <> '' AND v_todate <> '') THEN
  v_query := v_query || ' and Convert(date,CREATE_DATE,105) between CONVERT(DATE, ''' || v_fromdate || ''',105) and convert(DATE,''' || v_todate || ''',105)';
  ELSE
  IF (v_fromdate <> '') THEN
  v_query := v_query || ' and Convert(date,CREATE_DATE,105)=CONVERT(DATE, ''' || v_fromdate || ''',105)';
  ELSE
  IF (v_todate <> '') THEN
  v_query := v_query || ' and Convert(date,CREATE_DATE,103)=CONVERT(DATE, ''' || v_todate || ''',105)';
  END IF;
  END IF;
  END IF;
  IF (v_country <> '') THEN
  v_query := v_query || ' and country=''' || v_country || '''';
  END IF;
  IF (v_state <> '') THEN
  v_query := v_query || ' and state=''' || v_state || '''';
  END IF;
  IF (v_city <> '') THEN
  v_query := v_query || ' and city=''' || v_city || '''';
  END IF;
  v_query := ' insert into #temp ' || v_query || ' order By CREATE_DATE Desc';
  EXECUTE v_query;
  RETURN QUERY SELECT rownumber, osid, did, tokenid, previousurl, ipaddress, CAST(create_date AS TIMESTAMP) AS create_date, state, city, country FROM tmp_temp WHERE rownumber BETWEEN v_minindex AND v_maxindex;
  SELECT COUNT(rownumber) INTO v_totalrecord FROM tmp_temp;
  DROP TABLE IF EXISTS tmp_temp;
  -- SET option (removed)
END;
$$;


--
-- Name: usp_overall_order(integer, integer, character varying, character varying, character varying, character varying, character varying, character varying, bigint, integer, character varying, character varying, character varying, character varying, numeric, numeric); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_overall_order(v_startrowindex integer DEFAULT 1, v_maxrows integer DEFAULT 100, v_searchfield character varying DEFAULT ''::character varying, v_searchvalue character varying DEFAULT ''::character varying, v_fromdate character varying DEFAULT ''::character varying, v_todate character varying DEFAULT ''::character varying, v_status character varying DEFAULT ''::character varying, v_statustype character varying DEFAULT ''::character varying, v_branchid bigint DEFAULT 0, v_totalcount integer DEFAULT 0, v_company character varying DEFAULT ''::character varying, v_merchantname character varying DEFAULT ''::character varying, v_productname character varying DEFAULT ''::character varying, v_orderno character varying DEFAULT ''::character varying, v_totaljp numeric DEFAULT 0, v_totalbv numeric DEFAULT 0) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_minindex INT;
  v_maxindex INT;
  v_query text;
BEGIN
  v_minindex := (v_startrowindex - 1) * v_maxrows + 1;
  v_maxindex := v_startrowindex * v_maxrows;
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp (ROWNUMBER BIGINT 
, LOGINID VARCHAR( 100) 
, NAME VARCHAR(1000) 
, BRCODE VARCHAR( 50) 
, MOBILENO VARCHAR(20) 
, ORDERID VARCHAR( 50) 
, ORDERDATE timestamp 
, ORDER_QTY INT 
, ORDER_DAP DECIMAL 
, ORDER_NETAMT DECIMAL
, PAYMODE VARCHAR( 25) 
, CITY VARCHAR(300) 
, TOTAL_VAT DECIMAL 
, ORDERINTSTATUS INT 
, POID BIGINT 
, SPRID BIGINT 
, PRODUCT_QTY INT 
, SINGLE_DAP DECIMAL 
, TOTAL_DAP DECIMAL 
, TOTAL_SHIP_CH DECIMAL 
, TOTAL_COST DECIMAL 
, PRODUCTTOTALVAT DECIMAL 
,TOTAL_PURCHASE_COST DECIMAL
, PRODUCT_NAME varchar (500)
, PRODQTY varchar (100)
, PROUNIT VARCHAR( 500) 
, PRODCOLOR varchar (100)
, PRODSIZE varchar (100)
, PROD_IMAGES text 
, STATUS VARCHAR( 500) 
, PRODUCTINTSTATUS INT 
, PROCESSBY VARCHAR( 500) 
, PROCESSDATE timestamp 
, PROCESSREMARK VARCHAR(500) 
, INVQTY INT 
, REASON VARCHAR(100) 
, ISCANCELBYMEMBER boolean 
, ISRETURN boolean
, Address text
, PinCode VARCHAR (50)
, CountryName VARCHAR (500)
,JP decimal(18,0)
,BV decimal(18,0)
,COMPANYNAME varchar(1000)
,pmid bigint
,orderjp decimal(18,0)
,orderbv decimal(18,0)) ON COMMIT DROP;
  v_query := 'INSERT INTO #TEMP  SELECT ROW_NUMBER() OVER (ORDER BY OM.ORDERDATE DESC) AS ROWNUMBER,
POM.LOGINID,(OM.FNAME+''''+ISNULL(OM.LNAME,'''')) AS NAME,B.CLID AS BRCODE,OM.MOBILENO,
OM.ORDERID,OM.ORDERDATE,OM.ORDER_QTY,OM.ORDER_DAP,OM.ORDER_NETAMT,OM.PAYMODE,isnull(OM.Sh_City,'''') as CITY,
OM.TOTAL_VAT,OM.INTSTATUS AS ORDERINTSTATUS,POM.POID, CONVERT(BIGINT, POM.SUBPRCODE) AS SPRID,
POM.PRODUCT_QTY, POM.SINGLE_DAP, POM.TOTAL_DAP, POM.TOTAL_SHIP_CH, POM.TOTAL_COST,
POM.TOTAL_VAT AS PRODUCTTOTALVAT,POM.TOTAL_PURCHASE_COST, POM.PRODUCT_NAME, POM.PRODQTY, POM.PROUNIT, 
POM.PRODCOLOR, POM.PRODSIZE, POM.PROD_IMAGES, POM.STATUS, POM.INTSTATUS AS PRODUCTINTSTATUS,
POM.PROCESSBY, POM. PROCESSDATE, POM.PROCESSREMARK,ISNULL(POM.INVQTY,0) AS INVQTY,
POM.REASON,ISNULL(POM.ISCANCELBYMEMBER,0) AS ISCANCELBYMEMBER , ISNULL(POM.ISRETURN,0) AS ISRETURN ,isnull(OM.Address,'''') AS Address,ISNULL(OM.PinCode,'''') AS PinCode,ISNULL(IMS.CountryName,'''') AS CountryName,
isnull(IMSP.PV,0) AS JP,ISNULL(IMSP.BV,0) AS BV,pma.COMPANYNAME,pma.PMID,ISNULL(OM.Order_PV,0) as orderjp,isnull(OM.Order_BV,0) as orderbv
FROM TBL_ORDER_MASTER OM 
LEFT JOIN TBL_PRODUCT_ORDER_MASTER POM ON POM.ORDERID = OM.ORDERID 
join PORTAL_LOGIN pl on pl.PLID=OM.BranchId JOIN TBL_CUSTOMERLOGIN B ON B.LOGINID = OM.LoginId
left join IMS_CustomerAddress IMS on IMS.Id=B.CLID
left join Portal_Master pma on pma.PMID=pl.PMID
left join IMS_SubProduct IMSP on IMSP.SPRID= POM.SubPrCode
WHERE OM.LOGINID=B.LOGINID ';
  IF (v_searchfield <> '' AND v_searchvalue <> '') THEN
  IF (v_searchfield = 'MERCHANTCODE') THEN
  v_query := v_query || ' AND B.CODE=''' || v_searchvalue || '''';
  END IF;
  IF (v_searchfield = 'LOGINID') THEN
  v_query := v_query || ' AND OM.LOGINID=''' || v_searchvalue || '''';
  END IF;
  IF (v_searchfield = 'MEMBERNAME') THEN
  v_query := v_query || ' AND ISNULL(B.FNAME,'''')+'' ''+ISNULL(B.LNAME,'''') LIKE ''%' || v_searchvalue || '%''';
  END IF;
  IF (v_searchfield = 'ORDERID') THEN
  v_query := v_query || ' AND OM.ORDERID=''' || v_searchvalue || '''';
  END IF;
  END IF;
  IF (v_company <> '') THEN
  v_query := v_query || ' AND pma.PMID LIKE ''%' || v_company || '%'' ';
  END IF;
  IF (v_merchantname <> '') THEN
  v_query := v_query || ' AND (pma.COMPANYNAME) LIKE ''%' || v_merchantname || '%'' ';
  END IF;
  IF (v_productname <> '') THEN
  v_productname := REPLACE(v_productname, '''', '''''');
  v_query := v_query || ' and POM.PRODUCT_NAME =''' || v_productname || '''';
  END IF;
  IF ((v_fromdate <> '') AND (v_todate = '')) THEN
  v_query := v_query || ' AND CONVERT(DATE, OM.ORDERDATE, 105) BETWEEN  CONVERT(DATE, ''' || v_fromdate || ''', 105) AND  CONVERT(DATE, DBO.FUN_GETCURRENTDATE(), 105)';
  END IF;
  IF ((v_fromdate = '') AND (v_todate <> '')) THEN
  v_query := v_query || 'AND CONVERT(DATE, OM.ORDERDATE, 105) BETWEEN  CONVERT(DATE, ''' || v_todate || ''', 105) AND  CONVERT(DATE, DBO.FUN_GETCURRENTDATE(), 105)';
  END IF;
  IF ((v_fromdate <> '') AND (v_todate <> '')) THEN
  v_query := v_query || 'AND CONVERT(DATE, OM.ORDERDATE, 105) BETWEEN CONVERT(DATE, ''' || v_fromdate || ''', 105) AND  CONVERT(DATE, ''' || v_todate || ''', 105)';
  END IF;
  IF (v_status <> '') THEN
  v_query := v_query || ' AND ISNULL(OM.STATUS,'''')= ''' || v_status || '''';
  END IF;
  IF (v_statustype <> '') THEN
  IF (v_statustype = 'PENDING') THEN
  v_query := v_query || ' AND POM.STATUS=''PENDING''';
  END IF;
  IF (v_statustype = 'Completed') THEN
  v_query := v_query || ' AND POM.STATUS=''Completed''';
  END IF;
  IF (v_statustype = 'PICK') THEN
  v_query := v_query || ' AND POM.STATUS=''PICK''';
  END IF;
  IF (v_statustype = 'Dispatched') THEN
  v_query := v_query || ' AND POM.STATUS=''Dispatched''';
  END IF;
  IF (v_statustype = 'READY-TO-SHIP') THEN
  RETURN QUERY SELECT 4 AS readyship;
  v_query := v_query || ' AND POM.STATUS=''READYTOSHIP''';
  END IF;
  IF (v_statustype = 'MANIFEST') THEN
  v_query := v_query || ' AND POM.STATUS=''READYTOSHIP''';
  END IF;
  IF (v_statustype = 'Cancel') THEN
  v_query := v_query || ' AND POM.STATUS=''Cancel''';
  END IF;
  IF (v_statustype = 'RETURN') THEN
  v_query := v_query || ' AND POM.STATUS=''RETURN''';
  END IF;
  END IF;
  IF (v_orderno <> '') THEN
  v_query := v_query || ' AND POM.OrderId = ''' || v_orderno || ''' ';
  END IF;
  IF (v_branchid > 0) THEN
  v_query := v_query || ' AND pl.PLID=' || CAST(v_branchid AS VARCHAR(20)) || '';
  END IF;
  EXECUTE v_query;
  RAISE NOTICE '%', (v_query);
  RETURN QUERY SELECT * FROM tmp_temp WHERE rownumber BETWEEN v_minindex AND v_maxindex;
  SELECT SUM(jp) INTO v_totaljp FROM tmp_temp;
  SELECT SUM(bv) INTO v_totalbv FROM tmp_temp;
  SELECT COUNT(rownumber) INTO v_totalcount FROM tmp_temp;
  DROP TABLE IF EXISTS tmp_temp;
  -- SET option (removed)
END;
$$;


--
-- Name: usp_packegeblogclassifiedmaster(integer, integer, integer, integer, text, text, text, character varying, character varying, character varying, character varying, text, integer, integer, integer, integer, integer, character varying, integer, integer, text, text, text, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_packegeblogclassifiedmaster(v_mode integer DEFAULT 2, v_ttmid integer DEFAULT 0, v_startrowindex integer DEFAULT 1, v_maxrows integer DEFAULT 100, v_topicname text DEFAULT ''::text, v_topicinstruction text DEFAULT ''::text, v_accuracytip text DEFAULT ''::text, v_posteddate character varying DEFAULT ''::character varying, v_fromdate character varying DEFAULT ''::character varying, v_todate character varying DEFAULT ''::character varying, v_topictypeid character varying DEFAULT '0'::character varying, v_topictypename text DEFAULT ''::text, v_totalnoofpost integer DEFAULT 0, v_totalnoofapproval integer DEFAULT 0, v_totalnoofrejection integer DEFAULT 0, v_minnoofword integer DEFAULT 0, v_maxnoofword integer DEFAULT 0, v_status character varying DEFAULT '-1'::character varying, v_intresult integer DEFAULT 0, v_recordcount integer DEFAULT 0, v_topicintroduction text DEFAULT ''::text, v_topicdescription text DEFAULT ''::text, v_topicconclusion text DEFAULT ''::text, v_totalnoofrequirement integer DEFAULT 0) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_query text;
  v_oldnoreq BigInt;
  v_oldremain Bigint;
  v_difference BigInt;
  v_newnoreq BigInt;
  v_newremain BigInt;
BEGIN
  -- SET option (removed)
  IF (v_mode = 1) THEN
  INSERT INTO tbl_topicmaster (topicname, postinginstruction, accuracytips, posteddate, usercanviewfromdate, usercanviewtilldate, topictypeid, topictypename, totalnoofposting, totalnoofapproval, totalnoofrejection, minnoofwords, maxnoofwords, status, noofrequirement, instructionforintroduction, instructionfordescription, instructionforconclusion, isactive, totalremainposting) VALUES (v_topicname, v_topicinstruction, v_accuracytip, CURRENT_TIMESTAMP, v_fromdate, v_todate, v_topictypeid, v_topictypename, v_totalnoofpost, v_totalnoofapproval, v_totalnoofrejection, v_minnoofword, v_maxnoofword, 1, v_totalnoofrequirement, v_topicintroduction, v_topicdescription, v_topicconclusion, 1, v_totalnoofrequirement);
  v_intresult := 1;
  END IF;
  IF (v_mode = 2) THEN
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp (Rownunber Int,
	TTMID Int,
	TopicTypeID int ,
	ShortTopicName text,
	TopicName text,
	PostingInstruction text,
	AccuracyTips text,
	PostedDate varchar(200),
	UserCanViewFromdate varchar(200),
	UserCanViewTilldate varchar(200),
	TopicTypeName varchar(500),
	TotalNoOfApproval Varchar(500),
	TotalNoOfPosting varchar(500),
	TotalNoOfRejection varchar(500),
	MinNoOfWords  varchar(500),	
	MaxNoOfWords  varchar(500),
	Status varchar(50),
	NoOfRequirement varchar(50),
	PostIntroduction text,
	PostDescription  text,	
	PostConclusion  text) ON COMMIT DROP;
  v_query := '';
  v_query := 'insert into  #Temp  select ROW_NUMBER() over(order by TTMID)as Rownunber,TTMID,TopicTypeID,
         (Case When Len(TopicName)>15 Then SUBSTRING(TopicName,0,15) + ''... '' Else TopicName   End) as  ShortTopicName,TopicName,PostingInstruction,AccuracyTips,
    case  when PostedDate=''1900-01-01'' then ''N/A'' ELSE ( CONVERT(varchar(50), PostedDate,101) ) end as PostedDate,
    case  when UserCanViewFromdate=''1900-01-01'' then ''N/A'' ELSE ( CONVERT(varchar(500), UserCanViewFromdate,101) ) end as UserCanViewFromdate,
    case  when UserCanViewTilldate=''1900-01-01'' then ''N/A'' ELSE ( CONVERT(varchar(500), UserCanViewTilldate,101) ) end as UserCanViewTilldate,
	TopicTypeName,TotalNoOfApproval,TotalNoOfPosting,TotalNoOfRejection,MinNoOfWords,MaxNoOfWords ,case When IsActive =1 then ''Active''
	 Else ''Deactive'' End IsActive,NoOfRequirement,InstructionForIntroduction,InstructionForDescription,InstructionForConclusion  from Tbl_TopicMaster Where TopicTypeId!=0 and status=1 ';
  IF (v_posteddate <> '') THEN
  v_query := v_query || (' AND CONVERT(DATE,PostedDate,103) = CONVERT(Date,''' || v_posteddate || ''',103) ');
  END IF;
  IF (v_fromdate <> '') THEN
  v_query := v_query || (' AND CONVERT(DATE,UserCanViewFromdate,103) >= CONVERT(Date,''' || v_fromdate || ''',103) ');
  END IF;
  IF (v_todate <> '') THEN
  v_query := v_query || (' AND CONVERT(DATE,UserCanViewTilldate,103) <= CONVERT(Date,''' || v_todate || ''',103)');
  END IF;
  IF (v_status <> '-1') THEN
  v_query := v_query || (' AND IsActive = ''' || v_status || ''' ');
  END IF;
  IF (v_topictypeid <> '0') THEN
  v_query := v_query || (' AND TOPICTYPEID = ''' || v_topictypeid || ''' ');
  END IF;
  IF (v_topictypename <> '') THEN
  v_query := v_query || ' AND TOPICTypeNAME LIKE ''%' || v_topictypename || '%''';
  END IF;
  IF (v_topicname <> '') THEN
  v_query := v_query || ' AND TOPICNAME LIKE ''%' || v_topicname || '%''';
  END IF;
  IF (v_ttmid <> '0') THEN
  v_query := v_query || (' AND TTMID = ''' || CAST(v_ttmid AS VARCHAR) || ''' ');
  END IF;
  EXECUTE v_query;
  RETURN QUERY SELECT * FROM tmp_temp WHERE rownunber BETWEEN v_startrowindex AND v_maxrows;
  SELECT COUNT(1) INTO v_recordcount FROM tmp_temp;
  DROP TABLE IF EXISTS tmp_temp;
  END IF;
  IF (v_mode = 3) THEN
  v_oldnoreq := 0;
  v_oldremain := 0;
  v_difference := 0;
  v_newnoreq := 0;
  v_newremain := 0;
  SELECT noofrequirement, totalremainposting INTO v_oldnoreq, v_oldremain FROM tbl_topicmaster WHERE ttmid = v_ttmid;
  IF (v_totalnoofrequirement >= v_oldnoreq) THEN
  v_difference := v_totalnoofrequirement - v_oldnoreq;
  v_newnoreq := v_oldnoreq + v_difference;
  v_newremain := v_oldremain + v_difference;
  ELSE
  v_difference := v_oldnoreq - v_totalnoofrequirement;
  v_newnoreq := v_oldnoreq - v_difference;
  v_newremain := v_oldremain - v_difference;
  END IF;
  UPDATE tbl_topicmaster SET topicname = v_topicname, postinginstruction = v_topicinstruction, accuracytips = v_accuracytip, usercanviewfromdate = v_fromdate, usercanviewtilldate = v_todate, topictypeid = v_topictypeid, topictypename = v_topictypename, totalnoofposting = v_totalnoofpost, minnoofwords = v_minnoofword, maxnoofwords = v_maxnoofword, instructionfordescription = v_topicdescription, instructionforintroduction = v_topicintroduction, instructionforconclusion = v_topicconclusion, noofrequirement = v_newnoreq, totalremainposting = v_newremain WHERE ttmid = v_ttmid;
  v_intresult := 2;
  END IF;
  IF (v_mode = 4) THEN
  UPDATE tbl_topicmaster SET status = 0 WHERE ttmid = v_ttmid;
  v_intresult := 4;
  END IF;
  -- SET option (removed)
  IF (0 <> 0) THEN
  v_intresult := 0;
  RETURN;
  END IF;
END;
$$;


--
-- Name: usp_pagelog(integer, integer, character varying, character varying, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_pagelog(v_fromindex integer DEFAULT 1, v_toindex integer DEFAULT 50, v_fromdate character varying DEFAULT ''::character varying, v_todate character varying DEFAULT ''::character varying, v_totalrecord integer DEFAULT 0) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_query text;
  v_minindex INT;
  v_maxindex INT;
BEGIN
  -- SET option (removed)
  v_query := '';
  v_minindex := (v_fromindex - 1) * v_toindex + 1;
  v_maxindex := v_fromindex * v_toindex;
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp (RowNumber Bigint GENERATED BY DEFAULT AS IDENTITY,
pagelogid int,
page_name varchar(200),
total_visit int,
unique_id int,
Createdate timestamp) ON COMMIT DROP;
  v_query := 'select pagelogid,page_name,total_visit,unique_id,Createdate from tbl_pagelog where status=1';
  IF (v_fromdate <> '' AND v_todate <> '') THEN
  v_query := v_query || ' and Convert(date,Createdate,105) between CONVERT(DATE, ''' || v_fromdate || ''',105) and convert(DATE,''' || v_todate || ''',105)';
  ELSE
  IF (v_fromdate <> '') THEN
  v_query := v_query || ' and Convert(date,Createdate,105)=CONVERT(DATE, ''' || v_fromdate || ''',105)';
  ELSE
  IF (v_todate <> '') THEN
  v_query := v_query || ' and Convert(date,Createdate,103)=CONVERT(DATE, ''' || v_todate || ''',105)';
  END IF;
  END IF;
  END IF;
  v_query := ' insert into #temp ' || v_query || ' order By Createdate Desc';
  EXECUTE v_query;
  RETURN QUERY SELECT rownumber, pagelogid, page_name, total_visit, unique_id, (createdate) AS date FROM tmp_temp WHERE rownumber BETWEEN v_minindex AND v_maxindex;
  SELECT COUNT(rownumber) INTO v_totalrecord FROM tmp_temp;
  DROP TABLE IF EXISTS tmp_temp;
  -- SET option (removed)
END;
$$;


--
-- Name: usp_pagelogdetailslist(character varying, integer, integer, character varying, character varying, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_pagelogdetailslist(v_pageid character varying DEFAULT '2'::character varying, v_fromindex integer DEFAULT 1, v_toindex integer DEFAULT 50, v_fromdate character varying DEFAULT ''::character varying, v_todate character varying DEFAULT ''::character varying, v_totalrecord integer DEFAULT 0) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_query text;
  v_minindex INT;
  v_maxindex INT;
BEGIN
  -- SET option (removed)
  v_query := '';
  v_minindex := (v_fromindex - 1) * v_toindex + 1;
  v_maxindex := v_fromindex * v_toindex;
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp (RowNumber Bigint GENERATED BY DEFAULT AS IDENTITY,
Date varchar(100),
Country varchar(200),
State varchar(200),
City varchar(200),
Source varchar(100),
Ip varchar(100)) ON COMMIT DROP;
  v_query := 'select Convert(varchar(11),log_date,106)as Date,Country,State,City,Sourse,ip_address from tbl_pagelog_description where pagelogid=' || v_pageid || '';
  IF (v_fromdate <> '' AND v_todate <> '') THEN
  v_query := v_query || ' and log_date between ''' || v_fromdate || ''' and ''' || v_todate || '''';
  ELSE
  IF (v_fromdate <> '') THEN
  v_query := v_query || ' and Convert(Date,log_date)=''' || v_fromdate || '''';
  ELSE
  IF (v_todate <> '') THEN
  v_query := v_query || ' and Convert(Date,log_date)=''' || v_todate || '''';
  END IF;
  END IF;
  END IF;
  v_query := ' insert into #temp ' || v_query || ' order By log_date Desc';
  EXECUTE v_query;
  RETURN QUERY SELECT rownumber, CAST(TO_CHAR(date, 'DD TMMon YYYY') AS VARCHAR(11)) AS date, country, state, city, source, ip FROM tmp_temp WHERE rownumber BETWEEN v_minindex AND v_maxindex;
  SELECT COUNT(rownumber) INTO v_totalrecord FROM tmp_temp;
  DROP TABLE IF EXISTS tmp_temp;
  -- SET option (removed)
END;
$$;


--
-- Name: usp_pay_approve(bigint, numeric, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_pay_approve(v_preqid bigint, v_refferel_ratio numeric DEFAULT 0.00, INOUT v_intresult integer DEFAULT NULL::integer) RETURNS integer
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_index INT;
  v_plid INT;
  v_slicepayid VARCHAR(500);
  v_pprice numeric(19,4);
  v_pmid INT;
  v_totalamount numeric(19,4);
  v_intro_refid BIGINT;
  v_qpayregno BIGINT;
  v_limits1 numeric(19,4);
  v_currencysymbol VARCHAR(100);
  v_limits2 numeric(19,4);
  v_referalincome numeric(19,4);
  v_count INT;
BEGIN
  -- BEGIN TRAN (removed)
  v_index := 1;
  v_plid := 0;
  v_intresult := 1;
  SELECT plid, packprice INTO v_plid, v_pprice FROM tbl_packrequestsdetails WHERE preqid = v_preqid;
  SELECT COALESCE(intro_plid, 0) INTO v_intro_refid FROM portal_login WHERE plid = v_plid;
  IF (v_intro_refid > 0) THEN
  SELECT COALESCE(qpayregno, 0), COALESCE(currency, '') INTO v_qpayregno, v_currencysymbol FROM portal_login WHERE plid = v_intro_refid;
  IF (v_qpayregno > 0) THEN
  SELECT COALESCE(limits, 0) INTO v_limits1 FROM settings WHERE clubcond = 'qpay';
  v_referalincome := v_refferel_ratio * (v_pprice * v_limits1 / 100);
  INSERT INTO member_perfornemce (plid, childpmid, amount, date, active, trantype, cpmmision_percentage) VALUES (v_intro_refid, v_plid, v_referalincome, dbo.FUN_GETCURRENTDATE(), 1, 'referral_income', v_limits1);
  IF EXISTS(SELECT plid FROM ewallet WHERE plid = v_intro_refid) THEN
  UPDATE ewallet SET amount = COALESCE(amount, 0) + COALESCE(v_referalincome, 0), referalcommission = COALESCE(referalcommission, 0) + COALESCE(v_referalincome, 0), currentrefferal = COALESCE(currentrefferal, 0) + COALESCE(v_referalincome, 0) WHERE plid = v_intro_refid;
  ELSE
  INSERT INTO ewallet (plid, amount, active, referalcommission, currencysymbol, currentrefferal) VALUES (v_intro_refid, v_referalincome, 1, v_referalincome, v_currencysymbol, v_referalincome);
  END IF;
  ELSE
  SELECT COALESCE(limits, 0) INTO v_limits2 FROM settings WHERE clubcond = 'nonQpay';
  v_referalincome := v_refferel_ratio * (v_pprice * v_limits2 / 100);
  INSERT INTO member_perfornemce (plid, childpmid, amount, date, active, trantype, cpmmision_percentage) VALUES (v_intro_refid, v_plid, v_referalincome, dbo.FUN_GETCURRENTDATE(), 1, 'referral_income', v_limits2);
  IF EXISTS(SELECT plid FROM ewallet WHERE plid = v_intro_refid) THEN
  UPDATE ewallet SET amount = COALESCE(amount, 0) + COALESCE(v_referalincome, 0), referalcommission = COALESCE(referalcommission, 0) + COALESCE(v_referalincome, 0), currentrefferal = COALESCE(currentrefferal, 0) + COALESCE(v_referalincome, 0) WHERE plid = v_intro_refid;
  ELSE
  INSERT INTO ewallet (plid, amount, active, referalcommission, currencysymbol, currentrefferal) VALUES (v_intro_refid, v_referalincome, 1, v_referalincome, v_currencysymbol, v_referalincome);
  END IF;
  END IF;
  END IF;
  IF (0 <> 0) THEN
  -- ROLLBACK (removed)
  v_intresult := 0;
  RETURN;
  END IF;
  -- COMMIT (removed)
END;
$$;


--
-- Name: usp_pay_mode(character varying, character varying, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_pay_mode(v_did character varying DEFAULT ''::character varying, v_status character varying DEFAULT ''::character varying, v_mode integer DEFAULT NULL::integer) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_minindex INT;
  v_maxindex INT;
  v_query text;
BEGIN
  -- SET option (removed)
  DROP TABLE IF EXISTS tmp_pay;
  CREATE TEMP TABLE tmp_pay (PMID int,
	Pm_Code varchar(100),
	DID bigint,
	Percentage decimal,
	Active int,
	MDPID bigint) ON COMMIT DROP;
  -- BEGIN TRAN (removed)
  IF (v_mode = 1) THEN
  v_query := 'INSERT INTO #PAY select PM.PMID,Pm_Code,mdp.DID,MDP.Percentage,mdp.Active,MDP.MDPID from Pay_Mode PM inner join tbl_Map_Distributor_Paymode MDP on MDP.pmid=pm.pmid ';
  END IF;
  IF (v_mode = 2) THEN
  RETURN QUERY SELECT pmid, pm_code FROM pay_mode;
  END IF;
END;
$$;


--
-- Name: usp_paybypayumoney(integer, text, text); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_paybypayumoney(v_plid integer DEFAULT 0, v_amount text DEFAULT ''::text, v_commentorremark text DEFAULT ''::text) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_title text;
  v_modename text;
  v_name text;
  v_email text;
  v_mobile text;
  v_orderid text;
BEGIN
  v_title := 'Add Fund In Wallet';
  v_modename := 'Online Banking';
  v_name := '';
  v_email := '';
  v_mobile := '';
  v_orderid := '';
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp (PLID Int,

Name text,

Payamount text,

Product text,

Email text,

Mobile text,

PaymentMode text,

CommentORRemark text,

OrderId text) ON COMMIT DROP;
  SELECT CAST(RANDOM() * 99999 AS DECIMAL(5, 0)) INTO v_orderid;
  SELECT username, loginid, (CASE WHEN phone = '' THEN '9809090909' ELSE phone END) INTO v_name, v_email, v_mobile FROM portal_login WHERE plid = v_plid;
  INSERT INTO tmp_temp VALUES (v_plid, v_name, v_amount, v_title, v_email, v_mobile, v_modename, v_commentorremark, v_orderid);
  RETURN QUERY SELECT plid, name, payamount, product, email, mobile, paymentmode, commentorremark, orderid FROM tmp_temp;
  INSERT INTO payyoumonerypaymenthistory SELECT *, 0, 1, 0 FROM tmp_temp;
  DROP TABLE IF EXISTS tmp_temp;
END;
$$;


--
-- Name: usp_paybypayumoneypackage(integer, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_paybypayumoneypackage(v_regno integer DEFAULT 0, v_kitid integer DEFAULT 0) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_servicetax Decimal(10,2);
  v_amount Decimal(10,2);
  v_title text;
  v_paymentmode text;
  v_modename text;
  v_commentorremark text;
  v_challanimage text;
  v_name text;
  v_email text;
  v_mobile text;
BEGIN
  v_servicetax := 0.00;
  v_amount := 0.00;
  v_paymentmode := '2';
  v_modename := 'Net Banking';
  v_commentorremark := 'Pay You Money';
  v_challanimage := '';
  v_name := '';
  v_email := '';
  v_mobile := '';
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp (Regno Int,

Name text,

Payamount text,

Product text,

Email text,

Mobile text,

PackageId text,

PackageIdForRegistration text,

PaymentMode text,

ModeName text,

CommentORRemark text,

ChallanImage text) ON COMMIT DROP;
  SELECT COALESCE(limits, 0) INTO v_servicetax FROM settings WHERE caption = 'IsTaxApplicableOnPackagePrice';
  SELECT (amount + ((amount * v_servicetax) / 100)), title INTO v_amount, v_title FROM kit_master WHERE kid = v_kitid;
  SELECT (fname || ' ' || mname || ' ' || lname), emailid, mobile INTO v_name, v_email, v_mobile FROM member_master WHERE regno = v_regno;
  INSERT INTO tmp_temp VALUES (v_regno, v_name, v_amount, v_title, v_email, v_mobile, v_kitid, v_kitid, v_paymentmode, v_modename, v_commentorremark, v_challanimage);
  RETURN QUERY SELECT regno, name, payamount, product, email, mobile, packageid, packageidforregistration, paymentmode, modename, commentorremark, challanimage FROM tmp_temp;
  INSERT INTO payyoumonerypaymenthistory SELECT *, 0, 1, 0 FROM tmp_temp;
  DROP TABLE IF EXISTS tmp_temp;
END;
$$;


--
-- Name: usp_paylater(bigint, text, text, text, text, numeric, integer, numeric, character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_paylater(v_pmid bigint DEFAULT 0, v_ctid text DEFAULT ''::text, v_aid text DEFAULT ''::text, v_catid text DEFAULT ''::text, v_keyid text DEFAULT ''::text, v_totalprice numeric DEFAULT 0, v_noofmonth integer DEFAULT 1, v_finalprice numeric DEFAULT 0, INOUT v_strresult character varying DEFAULT NULL::character varying) RETURNS character varying
    LANGUAGE plpgsql
    AS $$
BEGIN
  v_strresult := '';
  IF NOT EXISTS(SELECT pmid FROM tbl_latersubscription WHERE pmid = v_pmid) THEN
  INSERT INTO tbl_latersubscription (pmid, ctid, aid, catid, keyid, price, saveddate, status, noofmonths, totalprice) VALUES (v_pmid, v_ctid, v_aid, v_catid, v_keyid, v_totalprice, CURRENT_TIMESTAMP, 1, v_noofmonth, v_finalprice);
  v_strresult := 'Record Inserted sucessfully';
  RETURN;
  ELSE
  UPDATE tbl_latersubscription SET ctid = v_ctid, aid = v_aid, catid = v_catid, keyid = v_keyid, price = v_totalprice, saveddate = CURRENT_TIMESTAMP, status = 1, noofmonths = v_noofmonth, totalprice = v_finalprice WHERE pmid = v_pmid;
  v_strresult := 'Record updated sucessfully';
  RETURN;
  END IF;
  IF (0 > 0) THEN
  v_strresult := 'Error  while saving the record';
  RETURN;
  END IF;
END;
$$;


--
-- Name: usp_payment_approve1(bigint, integer, character varying, numeric, text, character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_payment_approve1(v_preqid bigint, v_clearmode integer, v_admin_user character varying, v_refferel_ratio numeric DEFAULT 0.00, v_admin_remark text DEFAULT ''::text, INOUT v_strresult character varying DEFAULT NULL::character varying) RETURNS character varying
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_ok int;
BEGIN
  -- BEGIN TRAN (removed)
  v_ok := 0;
  v_strresult := 'reject';
  IF EXISTS(SELECT 1 FROM tbl_packrequestsdetails WHERE preqid = v_preqid AND status = 0) THEN
  PERFORM dbo.acceptrejectpackrequests(v_preqid => v_preqid, v_mode => v_clearmode, v_admin_user => v_admin_user, v_admin_remarks => v_admin_remark, v_strresult => '');
  IF (v_clearmode = 1) THEN
  v_strresult := 'approve';
  PERFORM dbo.usp_pay_approve(v_preqid => v_preqid, v_refferel_ratio => v_refferel_ratio, v_intresult => v_ok);
  END IF;
  ELSE
  v_strresult := 'Pack already approved/rejected or does not exists';
  END IF;
  IF (0 <> 0) THEN
  -- ROLLBACK (removed)
  v_strresult := 'error';
  RETURN;
  END IF;
  -- COMMIT (removed)
END;
$$;


--
-- Name: usp_paymentapprove_resellerwalletrequest(integer, integer, character varying, character varying, numeric, integer, integer, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_paymentapprove_resellerwalletrequest(v_rwrid integer DEFAULT 8, v_pmid integer DEFAULT 8, v_remark character varying DEFAULT ''::character varying, v_date character varying DEFAULT '23-01-2020'::character varying, v_amount numeric DEFAULT 5000, v_status integer DEFAULT 2, v_emp_id integer DEFAULT 1, INOUT v_totalcount integer DEFAULT 0) RETURNS integer
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_maxid INT;
  v_did INT;
  v_dpsid INT;
  v_used_wallet DECIMAL (18,8);
  v_old_bal decimal(18,8);
  v_balance decimal(18,8);
  v_tranid varchar(500);
BEGIN
  -- BEGIN TRAN (removed)
  -- SET option (removed)
  v_maxid := 0;
  v_did := 0;
  v_dpsid := 0;
  v_used_wallet := 0;
  v_old_bal := 0;
  v_balance := 0;
  v_tranid := '';
  SELECT used_wallet, dpsid INTO v_used_wallet, v_dpsid FROM tbl_distributor_prepaid_setting WHERE pmid = v_pmid;
  IF (v_status = 2) THEN
  IF EXISTS(SELECT 1 FROM tbl_distributor_prepaid_setting WHERE pmid = v_pmid) THEN
  INSERT INTO tbl_distributor_prepaid_setting_history SELECT * FROM tbl_distributor_prepaid_setting WHERE dpsid = 8;
  UPDATE tbl_distributor_prepaid_setting SET credit_wallet = COALESCE(credit_wallet, 0) + v_amount, available_wallet = COALESCE(available_wallet, 0) + v_amount, status = v_status WHERE dpsid = v_dpsid;
  v_totalcount := 1;
  ELSE
  INSERT INTO tbl_distributor_prepaid_setting (pmid, credit_wallet, used_wallet, available_wallet, createddate, status, emp_id) VALUES (v_pmid, v_amount, v_used_wallet, v_amount, CURRENT_TIMESTAMP, v_status, v_emp_id);
  v_totalcount := 1;
  END IF;
  END IF;
  SELECT available_wallet INTO v_balance FROM tbl_distributor_prepaid_setting WHERE pmid = v_pmid;
  SELECT did INTO v_did FROM tbl_distributor WHERE pmid = v_pmid;
  SELECT sys_tranid INTO v_tranid FROM tbl_resellerwalletrequest WHERE pmid = v_pmid AND rwrid = v_rwrid;
  INSERT INTO tbl_resellerwalletstatement (did, date, crdrtype, cr_amount, dr_amount, remarks, status, traceno, old_bal, balance, trsid) VALUES (v_did, dbo.FUN_GETCURRENTDATE(), 'Cr', v_amount, 0, 'Amount has been credited against this transID-' || v_tranid, 1, v_tranid, (v_balance - v_amount), v_balance, 1);
  UPDATE tbl_resellerwalletrequest SET status = v_status, admin_remark = v_remark, actiondate = TO_TIMESTAMP(v_date, 'DD-MM-YYYY') WHERE pmid = v_pmid AND rwrid = v_rwrid;
  v_totalcount := 1;
  IF (0 <> 0) THEN
  v_totalcount := '0';
  -- ROLLBACK (removed)
  RETURN;
  END IF;
  -- COMMIT (removed)
  -- SET option (removed)
END;
$$;


--
-- Name: usp_paymentgatewaymaster(integer, character varying, character varying, character varying, character varying, character varying, character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_paymentgatewaymaster(v_mode integer DEFAULT 2, v_ordernumber character varying DEFAULT '1554906229'::character varying, v_source character varying DEFAULT 'Checkout'::character varying, v_successurl character varying DEFAULT ''::character varying, v_failureurl character varying DEFAULT ''::character varying, v_inprocessurl character varying DEFAULT ''::character varying, v_canceledurl character varying DEFAULT ''::character varying) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_loginid VARCHAR(100);
  v_clid INT;
  v_did INT;
  v_tpgclid INT;
  v_intamount DECIMAL(10,2);
  v_order_cashback Decimal(10,2);
  v_order_pv Decimal(10,2);
  v_order_bv Decimal(10,2);
  v_jppoints DECIMAL(18,8);
  v_companyname VARCHAR(500);
  v_compnaylogo VARCHAR(600);
  v_pmid INT;
  v_apibaseurl VARCHAR(1500);
  v_companypgmerchantkey VARCHAR(150);
  v_companypgsalt VARCHAR(150);
  v_shoppingwallet DECIMAL(18,8);
  v_resellerwallet DECIMAL(18,8);
  v_apiurl text;
  v_smsapi text;
  v_compnayname VARCHAR(150);
  v_transationpayumoneyrate DECIMAL(18,2);
  v_realorderid Varchar(100);
  v_israzorpayactive Int;
  v_razorpayrate Decimal(10,2);
  v_razorpaydatakey Varchar(100);
  v_is_payu_active boolean;
  v_payu_rate decimal(10,2);
  v_payu_datakey varchar(500);
  v_payu_saltkey varchar(500);
  v_plid int;
BEGIN
  v_loginid := '';
  v_clid := 0;
  v_did := 0;
  v_tpgclid := 0;
  v_intamount := 0.00;
  v_order_cashback := 0.00;
  v_order_pv := 0.00;
  v_order_bv := 0.00;
  v_jppoints := 0.00;
  v_companyname := '';
  v_compnaylogo := '';
  v_pmid := 0;
  v_companypgmerchantkey := '';
  v_companypgsalt := '';
  v_shoppingwallet := 0;
  v_resellerwallet := 0;
  v_apiurl := '';
  v_smsapi := '';
  v_transationpayumoneyrate := 0;
  v_realorderid := '';
  v_israzorpayactive := 0;
  v_razorpayrate := 0.00;
  v_razorpaydatakey := '';
  v_is_payu_active := 0;
  v_payu_rate := 0.00;
  v_payu_datakey := '';
  v_payu_saltkey := '';
  INSERT INTO tbl_payment_gateway_call_login (mode, ordernumber, source, successurl, failureurl, inprocessurl, canceledurl, status, active, activitydateandtime, isrespoded, noofattempts) VALUES (v_mode, v_ordernumber, v_source, v_successurl, v_failureurl, v_inprocessurl, v_canceledurl, 1, 1, dbo.FUN_GETCURRENTDATE(), 0, 0);
  SELECT IDENT_CURRENT('TBL_PAYMENT_GATEWAY_CALL_LOGIN') INTO v_tpgclid;
  SELECT loginid INTO v_loginid FROM tbl_orderonlinerequests WHERE transactionid = v_ordernumber;
  SELECT clid, did INTO v_clid, v_did FROM tbl_customerlogin WHERE loginid = v_loginid;
  SELECT COALESCE(availablebalance, 0) INTO v_shoppingwallet FROM tbl_customerwallet WHERE clid = v_clid;
  SELECT COALESCE(totalbalance, 0) INTO v_resellerwallet FROM tbl_customercommissionwallet WHERE clid = v_clid;
  v_did := 1;
  IF (v_source = 'CHECKOUT') THEN
  SELECT loginid INTO v_loginid FROM tbl_orderonlinerequests WHERE transactionid = v_ordernumber AND status = 0;
  SELECT clid INTO v_clid FROM tbl_customerlogin WHERE loginid = v_loginid;
  SELECT successurl, failureurl, inprocessurl, cancelledurl, amount, 0, orderid INTO v_successurl, v_failureurl, v_inprocessurl, v_canceledurl, v_intamount, v_jppoints, v_realorderid FROM tbl_orderonlinerequests WHERE transactionid = v_ordernumber;
  SELECT order_pv, order_cashback, order_bv INTO v_order_pv, v_order_cashback, v_order_bv FROM tbl_order_master WHERE orderid = v_realorderid;
  IF (v_mode = 1) THEN
  RETURN QUERY SELECT pm_code, name, currency, did, percentage FROM tbl_map_distributor_paymode INNER JOIN pay_mode ON pay_mode.pmid = tbl_map_distributor_paymode.pmid WHERE did = v_did AND pay_mode.active = 1 AND tbl_map_distributor_paymode.active = 1 ORDER BY pay_mode.pmid ASC NULLS FIRST;
  END IF;
  IF (v_mode = 2) THEN
  v_did := 1;
  SELECT pmid INTO v_pmid FROM tbl_distributor WHERE did = v_did;
  SELECT COALESCE(companyname, ''), COALESCE(companyimage, '') INTO v_companyname, v_compnaylogo FROM distributor_master WHERE pmid = v_pmid;
  SELECT COALESCE(apiurl, ''), COALESCE(companypgmerchantkey, ''), COALESCE(companypgsalt, ''), COALESCE(apiurl, ''), COALESCE(smsapi, ''), COALESCE(transationpayumoneyrate, 0), israzorpayactive, razorpayrate, razorpaydatakey, is_payu_active, payu_rate, payu_datakey, payu_saltkey INTO v_apibaseurl, v_companypgmerchantkey, v_companypgsalt, v_apiurl, v_smsapi, v_transationpayumoneyrate, v_israzorpayactive, v_razorpayrate, v_razorpaydatakey, v_is_payu_active, v_payu_rate, v_payu_datakey, v_payu_saltkey FROM tbl_companysettings WHERE tcsid = v_pmid;
  SELECT COALESCE(companyname, '') INTO v_compnayname FROM distributor_master WHERE pmid = v_pmid;
  RETURN QUERY SELECT (CASE WHEN username = '' THEN 'N/A' ELSE username END) AS username, (CASE WHEN fname = '' THEN 'N/A' ELSE fname END) AS name, phone, (CASE WHEN emailid = '' THEN 'N/A' ELSE emailid END) AS emailid, (v_intamount) AS amount, (v_jppoints) AS jppoints, (v_successurl) AS successurl, (v_failureurl) AS failureurl, (v_inprocessurl) AS inprocessurl, (v_canceledurl) AS cancelledurl, v_companyname AS companyname, v_compnaylogo AS companylogo, v_apibaseurl AS apibaseurl, v_companypgmerchantkey AS companypgmerchantkey, v_companypgsalt AS companypgsalt, v_shoppingwallet AS shoppingwallet, v_resellerwallet AS resellerwallet, v_apiurl AS apiurl, v_smsapi AS smsapi, v_pmid AS pmid, v_compnayname AS compnayname, v_transationpayumoneyrate AS transationpayumoneyrate, v_order_pv AS order_pv, v_order_cashback AS order_cashback, v_order_bv AS order_bv, (v_israzorpayactive) AS israzorpayactive, (v_razorpayrate) AS razorpayrate, (v_razorpaydatakey) AS razorpaydatakey, v_is_payu_active AS is_payu_active, v_payu_rate AS payu_rate, v_payu_datakey AS payu_datakey, v_payu_saltkey AS payu_saltkey FROM tbl_customerlogin WHERE loginid = v_loginid AND did = v_did;
  UPDATE tbl_payment_gateway_call_login SET successurl = v_successurl, failureurl = v_failureurl, inprocessurl = v_inprocessurl, canceledurl = v_canceledurl WHERE tpgclid = v_tpgclid;
  END IF;
  IF (v_mode = 3) THEN
  RETURN QUERY SELECT walletid, walletname, maxuseper, isreturn FROM tbl_reseller_wallettype WHERE pmid = 1;
  END IF;
  ELSE
  IF (v_source = 'ADD MONEY') THEN
  SELECT loginid INTO v_loginid FROM tbl_addmoneyrequests WHERE transactionid = v_ordernumber AND status = 0;
  SELECT clid INTO v_clid FROM tbl_customerlogin WHERE loginid = v_loginid;
  SELECT successurl, failureurl, inprocessurl, cancelledurl, amount, 0 INTO v_successurl, v_failureurl, v_inprocessurl, v_canceledurl, v_intamount, v_jppoints FROM tbl_addmoneyrequests WHERE transactionid = v_ordernumber;
  IF (v_mode = 1) THEN
  RETURN QUERY SELECT pm_code, name, currency, did, percentage FROM tbl_map_distributor_paymode INNER JOIN pay_mode ON pay_mode.pmid = tbl_map_distributor_paymode.pmid WHERE did = v_did AND pay_mode.active = 1 AND tbl_map_distributor_paymode.active = 1 ORDER BY pay_mode.pmid ASC NULLS FIRST;
  END IF;
  IF (v_mode = 2) THEN
  SELECT pmid INTO v_pmid FROM tbl_distributor WHERE did = v_did;
  SELECT COALESCE(companyname, ''), COALESCE(companyimage, '') INTO v_companyname, v_compnaylogo FROM distributor_master WHERE pmid = v_pmid;
  SELECT COALESCE(apiurl, ''), COALESCE(companypgmerchantkey, ''), COALESCE(companypgsalt, ''), COALESCE(apiurl, ''), COALESCE(smsapi, ''), COALESCE(transationpayumoneyrate, 0), israzorpayactive, razorpayrate, razorpaydatakey INTO v_apibaseurl, v_companypgmerchantkey, v_companypgsalt, v_apiurl, v_smsapi, v_transationpayumoneyrate, v_israzorpayactive, v_razorpayrate, v_razorpaydatakey FROM tbl_companysettings;
  SELECT COALESCE(companyname, '') INTO v_compnayname FROM distributor_master WHERE pmid = v_pmid;
  RETURN QUERY SELECT (CASE WHEN username = '' THEN 'N/A' ELSE username END) AS username, (CASE WHEN fname = '' THEN 'N/A' ELSE fname END) AS name, phone, (CASE WHEN emailid = '' THEN 'N/A' ELSE emailid END) AS emailid, (v_intamount) AS amount, (v_jppoints) AS jppoints, (v_successurl) AS successurl, (v_failureurl) AS failureurl, (v_inprocessurl) AS inprocessurl, (v_canceledurl) AS cancelledurl, v_companyname AS companyname, v_compnaylogo AS companylogo, v_apibaseurl AS apibaseurl, v_companypgmerchantkey AS companypgmerchantkey, v_companypgsalt AS companypgsalt, v_shoppingwallet AS shoppingwallet, v_resellerwallet AS resellerwallet, v_apiurl AS apiurl, v_smsapi AS smsapi, v_pmid AS pmid, v_compnayname AS compnayname, v_transationpayumoneyrate AS transationpayumoneyrate, (v_israzorpayactive) AS israzorpayactive, (v_razorpayrate) AS razorpayrate, (v_razorpaydatakey) AS razorpaydatakey FROM tbl_customerlogin WHERE loginid = v_loginid AND did = v_did;
  UPDATE tbl_payment_gateway_call_login SET successurl = v_successurl, failureurl = v_failureurl, inprocessurl = v_inprocessurl, canceledurl = v_canceledurl WHERE tpgclid = v_tpgclid;
  END IF;
  ELSE
  IF (v_source = 'RESELLER PACKAGE') THEN
  SELECT successurl, failureurl, inprocessurl, cancelledurl, amount INTO v_successurl, v_failureurl, v_inprocessurl, v_canceledurl, v_intamount FROM dbo.tbl_resellerpackagepurchase_onlinerequests WHERE transactionid = v_ordernumber;
  IF (v_mode = 5) THEN
  SELECT pmid INTO v_pmid FROM tbl_distributor WHERE did = v_did;
  SELECT COALESCE(companyname, ''), COALESCE(companyimage, '') INTO v_companyname, v_compnaylogo FROM distributor_master WHERE pmid = v_pmid;
  SELECT COALESCE(apiurl, ''), COALESCE(companypgmerchantkey, ''), COALESCE(companypgsalt, ''), COALESCE(apiurl, ''), COALESCE(smsapi, ''), COALESCE(transationpayumoneyrate, 0), israzorpayactive, razorpayrate, razorpaydatakey INTO v_apibaseurl, v_companypgmerchantkey, v_companypgsalt, v_apiurl, v_smsapi, v_transationpayumoneyrate, v_israzorpayactive, v_razorpayrate, v_razorpaydatakey FROM tbl_companysettings;
  SELECT COALESCE(companyname, '') INTO v_compnayname FROM distributor_master WHERE pmid = v_pmid;
  RETURN QUERY SELECT (CASE WHEN username = '' THEN 'N/A' ELSE username END) AS username, (CASE WHEN fname = '' THEN 'N/A' ELSE fname END) AS name, phone, (CASE WHEN emailid = '' THEN 'N/A' ELSE emailid END) AS emailid, (v_intamount) AS amount, (v_jppoints) AS jppoints, (v_successurl) AS successurl, (v_failureurl) AS failureurl, (v_inprocessurl) AS inprocessurl, (v_canceledurl) AS cancelledurl, v_companyname AS companyname, v_compnaylogo AS companylogo, v_apibaseurl AS apibaseurl, v_companypgmerchantkey AS companypgmerchantkey, v_companypgsalt AS companypgsalt, v_shoppingwallet AS shoppingwallet, v_resellerwallet AS resellerwallet, v_apiurl AS apiurl, v_smsapi AS smsapi, v_pmid AS pmid, v_compnayname AS compnayname, v_transationpayumoneyrate AS transationpayumoneyrate, (v_israzorpayactive) AS israzorpayactive, (v_razorpayrate) AS razorpayrate, (v_razorpaydatakey) AS razorpaydatakey FROM tbl_distributor WHERE did = v_did;
  UPDATE tbl_payment_gateway_call_login SET successurl = v_successurl, failureurl = v_failureurl, inprocessurl = v_inprocessurl, canceledurl = v_canceledurl WHERE tpgclid = v_tpgclid;
  END IF;
  ELSE
  IF (v_source = 'MERCHANT PACKAGE') THEN
  v_plid := 0;
  SELECT successurl, failureurl, inprocessurl, cancelledurl, amount, plid INTO v_successurl, v_failureurl, v_inprocessurl, v_canceledurl, v_intamount, v_plid FROM dbo.tbl_merchantpackagepurchase_onlinerequests WHERE transactionid = v_ordernumber AND status = 0;
  IF (v_mode = 5) THEN
