  RETURN QUERY SELECT (CASE WHEN username = '' THEN 'N/A' ELSE username END) AS username, (CASE WHEN fname = '' THEN 'N/A' ELSE fname END) AS name, phone, (CASE WHEN emailid = '' THEN 'N/A' ELSE emailid END) AS emailid, (v_intamount) AS amount, (v_jppoints) AS jppoints, (v_successurl) AS successurl, (v_failureurl) AS failureurl, (v_inprocessurl) AS inprocessurl, (v_canceledurl) AS cancelledurl, v_companyname AS companyname, v_compnaylogo AS companylogo, v_apibaseurl AS apibaseurl, v_companypgmerchantkey AS companypgmerchantkey, v_companypgsalt AS companypgsalt, v_shoppingwallet AS shoppingwallet, v_resellerwallet AS resellerwallet, v_apiurl AS apiurl, v_smsapi AS smsapi, v_pmid AS pmid, v_compnayname AS compnayname FROM tbl_customerlogin WHERE loginid = v_loginid AND did = v_did;
  UPDATE tbl_payment_gateway_call_login_mobile SET successurl = v_successurl, failureurl = v_failureurl, inprocessurl = v_inprocessurl, canceledurl = v_canceledurl WHERE tpgclid = v_tpgclid;
  END IF;
  END IF;
  END IF;
  END IF;
END;
$$;


--
-- Name: usp_paymentmanagement(integer, text, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_paymentmanagement(v_tasmid integer DEFAULT 0, v_remarks text DEFAULT ''::text, INOUT v_intresult integer DEFAULT 0) RETURNS integer
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_plid BigInt;
  v_paymentmode Int;
  v_paymentmodename varchar(300);
  v_paymentstatus Int;
  v_bankname text;
  v_branchname text;
  v_referenceno text;
  v_referencedate text;
  v_commentorremark text;
  v_regno Int;
  v_allpackagetype text;
  v_allpackageid text;
  v_allpackageprice text;
  v_slice1 text;
  v_slice2 text;
  v_slice3 text;
  v_slice4 text;
  v_slice5 text;
  v_slice6 text;
  v_index1 Int;
  v_index2 Int;
  v_index3 Int;
  v_stroutputformonthlysubscription Int;
  v_stroutputforsmsboostersubscription text;
  v_stroutputforemailboostersubscription text;
  v_stroutputforwhatsappboostersubscription text;
  v_stroutputformanagepackage text;
  v_stroutputfortrafficboostersubscription text;
  v_invoice_no VARCHAR(100);
  v_year VARCHAR(20);
BEGIN
  -- BEGIN TRAN (removed)
  BEGIN
  v_plid := 0;
  v_paymentmode := 0;
  v_paymentmodename := '';
  v_paymentstatus := 0;
  v_bankname := '';
  v_branchname := '';
  v_referenceno := '';
  v_referencedate := '';
  v_commentorremark := '';
  v_regno := 0;
  v_allpackagetype := '';
  v_allpackageid := '';
  v_allpackageprice := '';
  SELECT allpackagetype, allpackageid, allpackageamount, plid, paymentmode, modename, status, bankname, branchname, referencenumber, referencedate, commentorremark INTO v_allpackagetype, v_allpackageid, v_allpackageprice, v_plid, v_paymentmode, v_paymentmodename, v_paymentstatus, v_bankname, v_branchname, v_referenceno, v_referencedate, v_commentorremark FROM tbl_allsubscriptionmaster WHERE tasmid = v_tasmid;
  SELECT regno INTO v_regno FROM member_master WHERE plid = v_plid;
  v_slice1 := '';
  v_slice2 := '';
  v_slice3 := '';
  v_slice4 := '';
  v_slice5 := '';
  v_slice6 := '';
  v_index1 := 1;
  v_index2 := 1;
  v_index3 := 1;
  SELECT v_allpackagetype, v_allpackageid, v_allpackageprice INTO v_slice1, v_slice3, v_slice5;
  WHILE v_index1 <> 0 AND v_index2 <> 0 AND v_index3 <> 0 LOOP
  SELECT POSITION('~' IN v_slice1) INTO v_index1;
  SELECT POSITION('~' IN v_slice3) INTO v_index2;
  SELECT POSITION('~' IN v_slice5) INTO v_index3;
  IF v_index1 <> 0 AND v_index2 <> 0 AND v_index3 <> 0 THEN
  SELECT LEFT(CAST(v_slice1 AS TEXT), v_index1 - 1) INTO v_slice2;
  SELECT LEFT(CAST(v_slice3 AS TEXT), v_index2 - 1) INTO v_slice4;
  SELECT LEFT(CAST(v_slice5 AS TEXT), v_index3 - 1) INTO v_slice6;
  ELSE
  SELECT v_slice1 INTO v_slice2;
  SELECT v_slice3 INTO v_slice4;
  SELECT v_slice5 INTO v_slice6;
  END IF;
  IF (v_slice2 = 1) THEN
  v_stroutputformonthlysubscription := 0;
  SELECT v_intresult INTO v_stroutputformonthlysubscription FROM dbo.usp_monthlysubscription(v_plid => v_plid, v_paymentmode => v_paymentmode, v_paymentmodename => v_paymentmodename, v_paymentstatus => v_paymentstatus, v_bankname => v_bankname, v_branchname => v_branchname, v_referenceno => v_referenceno, v_referencedate => v_referencedate, v_commentorremark => v_commentorremark, v_tsmid => v_slice4, v_pakcage_name => 'Monthly Subscription', v_package_amt => v_slice6, v_intresult => v_stroutputformonthlysubscription);
  IF (v_stroutputformonthlysubscription = 0) THEN
  -- ROLLBACK (removed)
  RETURN;
  END IF;
  END IF;
  IF (v_slice2 = 2) THEN
  SELECT v_strresult INTO v_stroutputforsmsboostersubscription FROM dbo.sp_purchasesmsoremailpackage(v_plid => v_plid, v_packamount => v_slice6, v_packid => v_slice4, v_mode => 'Purchased SMS Pack', v_paymentmode => v_paymentmode, v_paymentmodename => v_paymentmodename, v_paymentstatus => v_paymentstatus, v_bankname => v_bankname, v_branchname => v_branchname, v_referenceno => v_referenceno, v_referencedate => v_referencedate, v_commentorremark => v_commentorremark, v_strresult => v_stroutputforsmsboostersubscription);
  IF (v_stroutputforsmsboostersubscription <> 'ok') THEN
  -- ROLLBACK (removed)
  RETURN;
  END IF;
  END IF;
  IF (v_slice2 = 3) THEN
  SELECT v_strresult INTO v_stroutputforemailboostersubscription FROM dbo.sp_purchasesmsoremailpackage(v_plid => v_plid, v_packamount => v_slice6, v_packid => v_slice4, v_mode => 'Purchased Email Pack', v_paymentmode => v_paymentmode, v_paymentmodename => v_paymentmodename, v_paymentstatus => v_paymentstatus, v_bankname => v_bankname, v_branchname => v_branchname, v_referenceno => v_referenceno, v_referencedate => v_referencedate, v_commentorremark => v_commentorremark, v_strresult => v_stroutputforemailboostersubscription);
  IF (v_stroutputforemailboostersubscription <> 'ok') THEN
  -- ROLLBACK (removed)
  RETURN;
  END IF;
  END IF;
  IF (v_slice2 = 4) THEN
  SELECT v_strresult INTO v_stroutputforemailboostersubscription FROM dbo.sp_purchasesmsoremailpackage(v_plid => v_plid, v_packamount => v_slice6, v_packid => v_slice4, v_mode => 'Whatsapp SMS Pack', v_paymentmode => v_paymentmode, v_paymentmodename => v_paymentmodename, v_paymentstatus => v_paymentstatus, v_bankname => v_bankname, v_branchname => v_branchname, v_referenceno => v_referenceno, v_referencedate => v_referencedate, v_commentorremark => v_commentorremark, v_strresult => v_stroutputforemailboostersubscription);
  IF (v_stroutputforwhatsappboostersubscription <> 'ok') THEN
  -- ROLLBACK (removed)
  RETURN;
  END IF;
  END IF;
  IF (v_slice2 = 5) THEN
  SELECT v_intresult INTO v_stroutputformanagepackage FROM dbo.usp_managepackage(v_packageidforregistration => v_slice4, v_paymentmode => v_paymentmode, v_modename => v_paymentmodename, v_commentorremark => v_commentorremark, v_regno => v_regno, v_imagename => '', v_intresult => v_stroutputformanagepackage, v_ispayitforward => 0, v_bankname => v_bankname, v_branchname => v_branchname, v_referencedate => v_referencedate, v_referencenumber => v_referenceno);
  IF (v_stroutputformanagepackage <> 'success') THEN
  -- ROLLBACK (removed)
  RETURN;
  END IF;
  END IF;
  IF (v_slice2 = 6) THEN
  SELECT v_strresult INTO v_stroutputfortrafficboostersubscription FROM dbo.sp_purchasesmsoremailpackage(v_plid => v_plid, v_packamount => v_slice6, v_packid => v_slice4, v_mode => 'Traffic Booster Pack', v_paymentmode => v_paymentmode, v_paymentmodename => v_paymentmodename, v_paymentstatus => v_paymentstatus, v_bankname => v_bankname, v_branchname => v_branchname, v_referenceno => v_referenceno, v_referencedate => v_referencedate, v_commentorremark => v_commentorremark, v_strresult => v_stroutputfortrafficboostersubscription);
  IF (v_stroutputfortrafficboostersubscription <> 'ok') THEN
  -- ROLLBACK (removed)
  RETURN;
  END IF;
  END IF;
  SELECT RIGHT(CAST(v_slice1 AS TEXT), LENGTH(CAST(v_slice1 AS TEXT)) - v_index1) INTO v_slice1;
  SELECT RIGHT(CAST(v_slice3 AS TEXT), LENGTH(CAST(v_slice3 AS TEXT)) - v_index2) INTO v_slice3;
  SELECT RIGHT(CAST(v_slice5 AS TEXT), LENGTH(CAST(v_slice5 AS TEXT)) - v_index3) INTO v_slice5;
  IF LENGTH(CAST(v_slice1 AS TEXT)) = 0 OR LENGTH(CAST(v_slice3 AS TEXT)) = 0 OR LENGTH(CAST(v_slice5 AS TEXT)) = 0 THEN
  EXIT;
  END IF;
  END LOOP;
  IF (0 = 0) THEN
  v_invoice_no := '';
  SELECT (CASE WHEN (EXTRACT(MONTH FROM CAST(dbo.FUN_GETCURRENTDATE() AS DATE))) <= 3 THEN SUBSTRING(CAST(EXTRACT(YEAR FROM CAST(dbo.FUN_GETCURRENTDATE() AS DATE)) - 1 AS VARCHAR(4)) FROM 3 FOR 4) || '-' || CAST(EXTRACT(YEAR FROM CAST(dbo.FUN_GETCURRENTDATE() AS DATE)) % 100 AS VARCHAR(4)) ELSE SUBSTRING(CAST(EXTRACT(YEAR FROM CAST(dbo.FUN_GETCURRENTDATE() AS DATE)) AS VARCHAR(4)) FROM 3 FOR 4) || '-' || CAST((EXTRACT(YEAR FROM CAST(dbo.FUN_GETCURRENTDATE() AS DATE)) % 100) + 1 AS VARCHAR(4)) END) INTO v_year;
  SELECT RIGHT(CAST(COALESCE(CASE WHEN POSITION('/' IN invoice_no) > 0 THEN RIGHT(CAST(invoice_no AS TEXT), POSITION('/' IN REVERSE(invoice_no)) - 1) END, 'I0000') AS TEXT), LENGTH(CAST(COALESCE(CASE WHEN POSITION('/' IN invoice_no) > 0 THEN RIGHT(CAST(invoice_no AS TEXT), POSITION('/' IN REVERSE(invoice_no)) - 1) END, 'I0000') AS TEXT)) - 1) INTO v_invoice_no FROM tbl_allsubscriptionmaster WHERE COALESCE(invoice_no, '') <> '' ORDER BY CAST(RIGHT(CAST(COALESCE(CASE WHEN POSITION('/' IN invoice_no) > 0 THEN RIGHT(CAST(invoice_no AS TEXT), POSITION('/' IN REVERSE(invoice_no)) - 1) END, 'I0000') AS TEXT), LENGTH(CAST(COALESCE(CASE WHEN POSITION('/' IN invoice_no) > 0 THEN RIGHT(CAST(invoice_no AS TEXT), POSITION('/' IN REVERSE(invoice_no)) - 1) END, 'I0000') AS TEXT)) - 1) AS BIGINT) DESC NULLS LAST LIMIT 1;
  IF (COALESCE(v_invoice_no, '') = '') THEN
  v_invoice_no := '0001';
  ELSE
  v_invoice_no := CAST(v_invoice_no AS BIGINT) + 1;
  v_invoice_no := CASE WHEN LENGTH(CAST(v_invoice_no AS TEXT)) = 1 THEN '000' || v_invoice_no WHEN LENGTH(CAST(v_invoice_no AS TEXT)) = 2 THEN '00' || v_invoice_no WHEN LENGTH(CAST(v_invoice_no AS TEXT)) = 3 THEN '0' || v_invoice_no ELSE v_invoice_no END;
  END IF;
  v_invoice_no := 'EBPL/' || v_year || '/I' || v_invoice_no;
  v_intresult := 1;
  UPDATE tbl_allsubscriptionmaster SET isapproved = 1, invoice_no = v_invoice_no, commentorremark = v_remarks, approvaldate = dbo.FUN_GETCURRENTDATE() WHERE tasmid = v_tasmid;
  -- COMMIT (removed)
  RETURN;
  ELSE
  v_intresult := 0;
  -- ROLLBACK (removed)
  RETURN;
  END IF;
  EXCEPTION WHEN OTHERS THEN
  v_intresult := 0;
  -- ROLLBACK (removed)
  RETURN;
  END;
  -- COMMIT (removed)
END;
$$;


--
-- Name: usp_paymentmanagement1(integer, text, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_paymentmanagement1(v_tasmid integer DEFAULT 1, v_remarks text DEFAULT NULL::text, INOUT v_intresult integer DEFAULT 0) RETURNS integer
    LANGUAGE plpgsql
    AS $$
BEGIN
  -- BEGIN TRAN (removed)
  BEGIN
  UPDATE tbl_allsubscriptionmaster SET isapproved = 2, commentorremark = v_remarks WHERE tasmid = v_tasmid;
  v_intresult := 1;
  -- COMMIT (removed)
  RETURN;
  EXCEPTION WHEN OTHERS THEN
  v_intresult := 0;
  -- ROLLBACK (removed)
  RETURN;
  END;
  -- COMMIT (removed)
END;
$$;


--
-- Name: usp_paymentmanagement_payment_gateway(text, text, text, text, text, text, text, text, text, text, text, integer, text, character varying, character varying, character varying, character varying, character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_paymentmanagement_payment_gateway(v_name text DEFAULT ''::text, v_address text DEFAULT ''::text, v_contactno text DEFAULT ''::text, v_cityname text DEFAULT ''::text, v_emailid text DEFAULT ''::text, v_state text DEFAULT ''::text, v_amount text DEFAULT ''::text, v_country text DEFAULT ''::text, v_remark text DEFAULT ''::text, v_pincode text DEFAULT ''::text, v_orderid text DEFAULT ''::text, v_paymentstatus integer DEFAULT 0, v_refernecid text DEFAULT ''::text, INOUT v_strresult character varying DEFAULT ''::character varying, INOUT v_successurl character varying DEFAULT ''::character varying, INOUT v_failureurl character varying DEFAULT ''::character varying, INOUT v_inprocessurl character varying DEFAULT ''::character varying, INOUT v_canceledurl character varying DEFAULT ''::character varying) RETURNS record
    LANGUAGE plpgsql
    AS $$
BEGIN
  BEGIN
  SELECT '', '/', '/', '/', '/' INTO v_strresult, v_successurl, v_failureurl, v_inprocessurl, v_canceledurl;
  IF EXISTS(SELECT 1 FROM tbl_onlinepaymenthistory WHERE orderid = v_orderid OR refernecid = v_refernecid) THEN
  IF NOT EXISTS(SELECT 1 FROM tbl_onlinepaymenthistory WHERE orderid = v_orderid AND paymentstatus = 0) THEN
  v_strresult := 'AlreadyDone';
  RETURN;
  END IF;
  IF NOT EXISTS(SELECT 1 FROM tbl_onlinepaymenthistory WHERE refernecid = v_refernecid AND paymentstatus = 0) THEN
  v_strresult := 'AlreadyDone';
  RETURN;
  END IF;
  END IF;
  SELECT successurl, failureurl, inprocessurl, canceledurl INTO v_successurl, v_failureurl, v_inprocessurl, v_canceledurl FROM tbl_payment_gateway_call_login WHERE ordernumber = v_refernecid;
  IF EXISTS(SELECT 1 FROM tbl_onlinepaymenthistory WHERE orderid = v_orderid AND paymentstatus = 0) THEN
  UPDATE tbl_onlinepaymenthistory SET paymentstatus = v_paymentstatus, responsedatetime = dbo.FUN_GETCURRENTDATE() WHERE orderid = v_orderid;
  v_strresult := 'updated';
  ELSE
  INSERT INTO tbl_onlinepaymenthistory (name, address, contactno, cityname, emailid, state, amount, country, remark, pincode, orderid, paymentstatus, refernecid) VALUES (v_name, v_address, v_contactno, v_cityname, v_emailid, v_state, v_amount, v_country, v_remark, v_pincode, v_orderid, v_paymentstatus, v_refernecid);
  v_strresult := 'inserted';
  END IF;
  EXCEPTION WHEN OTHERS THEN
  v_strresult := 'error';
  END;
END;
$$;


--
-- Name: usp_paymentmanagement_payment_gateway_mobile(text, text, text, text, text, text, text, text, text, text, text, integer, text, character varying, character varying, character varying, character varying, character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_paymentmanagement_payment_gateway_mobile(v_name text DEFAULT ''::text, v_address text DEFAULT ''::text, v_contactno text DEFAULT ''::text, v_cityname text DEFAULT ''::text, v_emailid text DEFAULT ''::text, v_state text DEFAULT ''::text, v_amount text DEFAULT ''::text, v_country text DEFAULT ''::text, v_remark text DEFAULT ''::text, v_pincode text DEFAULT ''::text, v_orderid text DEFAULT ''::text, v_paymentstatus integer DEFAULT 0, v_refernecid text DEFAULT ''::text, INOUT v_strresult character varying DEFAULT ''::character varying, INOUT v_successurl character varying DEFAULT ''::character varying, INOUT v_failureurl character varying DEFAULT ''::character varying, INOUT v_inprocessurl character varying DEFAULT ''::character varying, INOUT v_canceledurl character varying DEFAULT ''::character varying) RETURNS record
    LANGUAGE plpgsql
    AS $$
BEGIN
  BEGIN
  SELECT '', '', '', '', '' INTO v_strresult, v_successurl, v_failureurl, v_inprocessurl, v_canceledurl;
  SELECT successurl, failureurl, inprocessurl, canceledurl INTO v_successurl, v_failureurl, v_inprocessurl, v_canceledurl FROM tbl_payment_gateway_call_login_mobile WHERE ordernumber = v_refernecid;
  IF EXISTS(SELECT 1 FROM tbl_onlinepaymenthistory_mobile WHERE orderid = v_orderid) THEN
  UPDATE tbl_onlinepaymenthistory_mobile SET paymentstatus = v_paymentstatus WHERE orderid = v_orderid;
  ELSE
  IF EXISTS(SELECT 1 FROM tbl_onlinepaymenthistory_mobile WHERE refernecid = v_refernecid) THEN
  UPDATE tbl_onlinepaymenthistory_mobile SET paymentstatus = v_paymentstatus WHERE refernecid = v_refernecid;
  ELSE
  INSERT INTO tbl_onlinepaymenthistory_mobile (name, address, contactno, cityname, emailid, state, amount, country, remark, pincode, orderid, paymentstatus, refernecid) VALUES (v_name, v_address, v_contactno, v_cityname, v_emailid, v_state, v_amount, v_country, v_remark, v_pincode, v_orderid, v_paymentstatus, v_refernecid);
  END IF;
  END IF;
  v_strresult := 'success';
  EXCEPTION WHEN OTHERS THEN
  v_strresult := 'error';
  END;
END;
$$;


--
-- Name: usp_paymentmanagementupdatestatus_payment_gateway_mobile(text, text, integer, text, character varying, text); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_paymentmanagementupdatestatus_payment_gateway_mobile(v_remark text DEFAULT ''::text, v_orderid text DEFAULT ''::text, v_paymentstatus integer DEFAULT 0, v_refernecid text DEFAULT ''::text, INOUT v_strresult character varying DEFAULT NULL::character varying, v_hashcode text DEFAULT ''::text) RETURNS character varying
    LANGUAGE plpgsql
    AS $$
BEGIN
  BEGIN
  UPDATE tbl_onlinepaymenthistory_mobile SET paymentstatus = v_paymentstatus, remark = v_remark, hashcode = v_hashcode WHERE orderid = v_orderid;
  v_strresult := 'success';
  EXCEPTION WHEN OTHERS THEN
  v_strresult := 'error';
  END;
END;
$$;


--
-- Name: usp_paymentmethod(integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_paymentmethod(v_pmid integer DEFAULT 3) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_ptmid text;
BEGIN
  v_ptmid := '';
  SELECT COALESCE(ptmid, '') INTO v_ptmid FROM portal_master WHERE pmid = v_pmid;
  IF (v_ptmid <> '') THEN
  RETURN QUERY SELECT ptmid, paymentmathod, paymentlogo, mathodcode FROM dbo.SPLITSTRINGBYCOMMA(v_ptmid) JOIN tbl_paymentmaster AS tpm ON tpm.ptmid = value;
  END IF;
END;
$$;


--
-- Name: usp_payoutreport(integer, integer, integer, character varying, character varying, integer, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_payoutreport(v_mode integer DEFAULT 1, v_startrowindex integer DEFAULT 1, v_maxrows integer DEFAULT 100, v_fromdate character varying DEFAULT ''::character varying, v_todate character varying DEFAULT '14-08-2018'::character varying, v_plid integer DEFAULT 1, INOUT v_totalcount integer DEFAULT 0) RETURNS integer
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_minindex INT;
  v_maxindex INT;
  v_query text;
  v_condition text;
  v_countquery text;
  v_parmdefinition text;
BEGIN
  v_condition := '';
  v_countquery := '';
  v_minindex := (v_startrowindex - 1) * v_maxrows + 1;
  v_maxindex := v_startrowindex * v_maxrows;
  IF (v_mode = 1) THEN
  IF (v_plid <> 0) THEN
  v_query := N'SELECT ROW_NUMBER() OVER(ORDER BY MPID) AS ROWNUMBER,(Case WHen PL.USERNAME='''' Then ''N/A'' ELSE PL.USERNAME END) as USERNAME,MP.PLID,MP.LOGINID,
MP.PAYID,MPM.PAYDATE,MPM.PAYFROM,MPM.PAYTO,
MP.NEWORDERAMOUNT,MP.DISPATCHORDERAMOUNT,MP.CANCELORDERAMOUNT,MP.COMPLETEORDERAMOUNT,
MP.ADMINCHARGE,(MP.COMPLETEORDERAMOUNT-MP.ADMINCHARGE) AS PAYAMOUNT INTO #TEMP
FROM MERCHANT_PAYOUT MP
LEFT JOIN MERCHANT_PAYOUT_MASTER MPM ON  MP.PAYID=MPM.PAYID
LEFT JOIN  PORTAL_LOGIN PL ON MP.PLID=PL.PLID
WHERE 1=1 ';
  v_parmdefinition := N'@TOTALCOUNT NVARCHAR(1000) OUTPUT';
  v_countquery := N'SELECT @TOTALCOUNT=Count(1) FROM MERCHANT_PAYOUT MP   WHERE MP.PLID<>0 ';
  END IF;
  IF ((v_fromdate <> '') AND (v_todate = '')) THEN
  v_condition := v_condition || ' AND CONVERT(VARCHAR, CONVERT(DATE, MPM.PAYDATE, 105) ) BETWEEN  CONVERT(DATE, ''' || v_fromdate || ''', 105) AND  CONVERT(DATE, DBO.FUN_GETCURRENTDATE(), 105)';
  END IF;
  IF ((v_fromdate = '') AND (v_todate <> '')) THEN
  v_condition := v_condition || ' AND CONVERT(DATE, MPM.PAYDATE, 105) BETWEEN  CONVERT(DATE, ''' || v_todate || ''', 105) AND  CONVERT(DATE, DBO.FUN_GETCURRENTDATE(), 105)';
  END IF;
  IF ((v_fromdate <> '') AND (v_todate <> '')) THEN
  v_condition := v_condition || 'AND CONVERT(DATE,  MPM.PAYDATE, 105) BETWEEN CONVERT(DATE, ''' || v_fromdate || ''', 105) AND  CONVERT(DATE, ''' || v_todate || ''', 105)';
  END IF;
  IF (v_plid > 0) THEN
  v_condition := v_condition || ' AND MP.PLID=' || CAST(v_plid AS VARCHAR(30)) || '';
  END IF;
  v_query := v_query || v_condition || ' ;SELECT  *  FROM #TEMP WHERE ROWNUMBER BETWEEN ' || CAST(v_minindex AS text) || ' AND ' || CAST(v_maxindex AS text) || '';
  v_query := v_query;
  v_countquery := v_countquery || v_condition;
  EXECUTE v_query;
  EXECUTE v_countquery;
  RAISE NOTICE '%', v_countquery;
  RAISE NOTICE '%', v_query;
  -- SET option (removed)
  END IF;
END;
$$;


--
-- Name: usp_payoutreport_admin(integer, integer, character varying, character varying, character varying, character varying, integer, character varying, integer, character varying, bigint, text); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_payoutreport_admin(v_startrowindex integer DEFAULT 1, v_maxrows integer DEFAULT 100, v_searchfield character varying DEFAULT ''::character varying, v_searchvalue character varying DEFAULT ''::character varying, v_fromdate character varying DEFAULT ''::character varying, v_todate character varying DEFAULT ''::character varying, v_totalcount integer DEFAULT 0, v_merchantname character varying DEFAULT ''::character varying, v_mode integer DEFAULT 0, v_requestid character varying DEFAULT ''::character varying, v_plid bigint DEFAULT 1, v_filename text DEFAULT ''::text) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_minindex INT;
  v_maxindex INT;
  v_query text;
  v_accountholdername VARCHAR(500);
  v_bankname VARCHAR(500);
  v_accountno VARCHAR(500);
  v_ifsccode VARCHAR(500);
  v_branchname VARCHAR(500);
  v_amount DECIMAL(18,8);
BEGIN
  v_minindex := (v_startrowindex - 1) * v_maxrows + 1;
  v_maxindex := v_startrowindex * v_maxrows;
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp (ROWNUMBER INT GENERATED BY DEFAULT AS IDENTITY, 
	COMPANYNAME VARCHAR(100),  
	EMAILID VARCHAR(50), 
	ACCOUNTHOLDERNAME VARCHAR(500), 
    PAYDATE VARCHAR(50),  
	PAYOUTAMOUNT DECIMAL (10,2),     
	ACCOUNTNO  VARCHAR(50),        
	TRANS_ID VARCHAR(100),	
	DATE VARCHAR(50), 	
	STATUS VARCHAR(50),
	BANKNAME VARCHAR(50),
	IFSCCODE VARCHAR(50),
	BRANCHNAME VARCHAR(50),
	ACCOUNTTYPE INT,
	TMWDID BIGINT,
	Phone varchar(100),
	Plid INT) ON COMMIT DROP;
  v_query := 'INSERT INTO #TEMP SELECT PM.COMPANYNAME,PL.EMAILID,BAM.ACCOUNTHOLDERNAME,MP.PAYDATE,(MW.PAYBLEAMOUNT)AS PAYOUTAMOUNT,
 BAM.ACCOUNTNO,MW.TRANS_ID,ISNULL(CONVERT(VARCHAR(100),MW.DATE),''''),MW.STATUS,
BAM.BANKNAME,BAM.IFSCCODE,BAM.BRANCHNAME,MBA.BANKACCOUNTTYPEID,MW.TMWDID,
PL.PHONE,PL.PLID FROM TBL_MERCHANT_PAYOUT MP 
LEFT JOIN TBL_MERCHANT_WITHDRAWALS MW ON MW.PAYID=MP.PAYID
LEFT JOIN BANK_ACCOUNTS_MERCHANT BAM ON BAM.ACID=MW.ACID
LEFT JOIN PORTAL_LOGIN PL ON PL.PLID=BAM.PLID
LEFT JOIN TBL_MERCHANT_BANKACCOUNTTYPE MBA ON BAM.ACCOUNTTYPE=MBA.TMBATID
LEFT JOIN PORTAL_MASTER PM ON PM.PLID=PL.PLID WHERE MW.status=0 ';
  IF ((v_fromdate <> '') AND (v_todate = '')) THEN
  v_query := v_query || ' AND CONVERT(DATE, PAYDATE, 105) BETWEEN  CONVERT(DATE, ''' || v_fromdate || ''', 105) AND  CONVERT(DATE, DBO.FUN_GETCURRENTDATE(), 105)';
  END IF;
  IF ((v_fromdate = '') AND (v_todate <> '')) THEN
  v_query := v_query || 'AND CONVERT(DATE, PAYDATE, 105) BETWEEN  CONVERT(DATE, ''' || v_todate || ''', 105) AND  CONVERT(DATE, DBO.FUN_GETCURRENTDATE(), 105)';
  END IF;
  IF ((v_fromdate <> '') AND (v_todate <> '')) THEN
  v_query := v_query || 'AND CONVERT(DATE, PAYDATE, 105) BETWEEN CONVERT(DATE, ''' || v_fromdate || ''', 105) AND  CONVERT(DATE, ''' || v_todate || ''', 105)';
  END IF;
  IF (v_merchantname <> '') THEN
  v_query := v_query || ' AND PM.COMPANYNAME= ''' || v_merchantname || ''' ';
  END IF;
  IF (v_searchfield = 'EMAILID') THEN
  v_query := v_query || ' AND PL.EMAILID= ''' || v_searchvalue || ''' ';
  END IF;
  IF (v_searchfield = 'ACCOUNTNO') THEN
  v_query := v_query || ' AND BAM.ACCOUNTNO= ''' || v_searchvalue || ''' ';
  END IF;
  IF (v_searchfield = 'IFSCCODE') THEN
  v_query := v_query || ' AND BAM.IFSCCODE= ''' || v_searchvalue || ''' ';
  END IF;
  IF (v_searchfield = 'BANKNAME') THEN
  v_query := v_query || ' AND BAM.BANKNAME= ''' || v_searchvalue || ''' ';
  END IF;
  IF (v_plid <> 0) THEN
  v_query := v_query || ' AND PL.PLID= ''' || CAST(v_plid AS VARCHAR(30)) || ''' ';
  END IF;
  EXECUTE v_query;
  RETURN QUERY SELECT * FROM tmp_temp WHERE rownumber BETWEEN v_minindex AND v_maxindex;
  IF (v_mode = 1) THEN
  SELECT COUNT(rownumber) INTO v_totalcount FROM tmp_temp;
  INSERT INTO tbl_downloaded_bank_excel_history (accountholdername, bankname, accountno, ifsccode, branchname, payoutamount, downloadeddate, requestid) SELECT accountholdername, bankname, accountno, ifsccode, branchname, payoutamount, dbo.FUN_GETCURRENTDATE(), v_requestid FROM tmp_temp;
  INSERT INTO tbl_downloaded_bank_excel VALUES (v_plid, v_filename, v_requestid, v_totalcount, 0, 1, dbo.FUN_GETCURRENTDATE());
  END IF;
  SELECT COUNT(rownumber) INTO v_totalcount FROM tmp_temp;
  DROP TABLE IF EXISTS tmp_temp;
  -- SET option (removed)
END;
$$;


--
-- Name: usp_payoutreport_reseller_admin(integer, integer, character varying, character varying, character varying, character varying, integer, character varying, integer, character varying, bigint, text); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_payoutreport_reseller_admin(v_startrowindex integer DEFAULT 1, v_maxrows integer DEFAULT 100, v_searchfield character varying DEFAULT ''::character varying, v_searchvalue character varying DEFAULT ''::character varying, v_fromdate character varying DEFAULT ''::character varying, v_todate character varying DEFAULT ''::character varying, v_totalcount integer DEFAULT 0, v_merchantname character varying DEFAULT ''::character varying, v_mode integer DEFAULT 0, v_requestid character varying DEFAULT ''::character varying, v_plid bigint DEFAULT 0, v_filename text DEFAULT ''::text) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_minindex INT;
  v_maxindex INT;
  v_query text;
  v_accountholdername VARCHAR(500);
  v_bankname VARCHAR(500);
  v_accountno VARCHAR(500);
  v_ifsccode VARCHAR(500);
  v_branchname VARCHAR(500);
  v_amount DECIMAL(18,8);
  v_tempdid text;
  v_index INT;
  v_slice text;
  v_totalpayable DECIMAL(18,2);
BEGIN
  v_tempdid := '';
  v_index := 1;
  v_slice := '';
  v_totalpayable := 0;
  v_minindex := (v_startrowindex - 1) * v_maxrows + 1;
  v_maxindex := v_startrowindex * v_maxrows;
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp (ROWNUMBER INT GENERATED BY DEFAULT AS IDENTITY, 
	DID INT,
	COMPANYNAME VARCHAR(100),  
	EMAILID VARCHAR(50), 
	ACCOUNTHOLDERNAME VARCHAR(500), 
	ACCOUNTNO  VARCHAR(50), 
	BANKNAME VARCHAR(50),
	IFSCCODE VARCHAR(50),
	BRANCHNAME VARCHAR(50),       
	STATUS int,
	PAYOUTAMOUNT DECIMAL (10,2), 
	RCWSID BIGINT,
	DATE varchar(100),
	Phone varchar(100),
	FNAME varchar(100)) ON COMMIT DROP;
  v_query := 'INSERT INTO #TEMP SELECT RTR.DID,DM.COMPANYNAME,TD.EMAILID,BAD.ACCOUNTHOLDERNAME,
 BAD.ACCOUNTNO,BAD.BANKNAME,BAD.IFSCCODE,BAD.BRANCHNAME,RTR.PaidStatus,
 RTR.AMOUNT,RTR.TRTBWID,RTR.CREATE_DATE,TD.PHONE,(TD.FNAME+''''+TD.LNAME)
 FROM TBL_RESELLER_TRANSFERTOBANK_REQUEST RTR
 LEFT JOIN DISTRIBUTOR_MASTER DM ON RTR.DID=DM.PLID
 LEFT JOIN TBL_DISTRIBUTOR TD ON RTR.DID=TD.DID
 LEFT JOIN BANK_ACCOUNTS_DISTRIBUTOR BAD ON RTR.DID=BAD.DID
 WHERE BAD.ACTIVE=1 AND BAD.ISAPROVE=1 and RTR.TRANSFERID=1 and RTR.PaidStatus=0 ';
  IF ((v_fromdate <> '') AND (v_todate = '')) THEN
  v_query := v_query || ' AND CONVERT(DATE, CREATE_DATE, 105) BETWEEN  CONVERT(DATE, ''' || v_fromdate || ''', 105) AND  CONVERT(DATE, DBO.FUN_GETCURRENTDATE(), 105)';
  END IF;
  IF ((v_fromdate = '') AND (v_todate <> '')) THEN
  v_query := v_query || 'AND CONVERT(DATE, CREATE_DATE, 105) BETWEEN  CONVERT(DATE, ''' || v_todate || ''', 105) AND  CONVERT(DATE, DBO.FUN_GETCURRENTDATE(), 105)';
  END IF;
  IF ((v_fromdate <> '') AND (v_todate <> '')) THEN
  v_query := v_query || 'AND CONVERT(DATE, CREATE_DATE, 105) BETWEEN CONVERT(DATE, ''' || v_fromdate || ''', 105) AND  CONVERT(DATE, ''' || v_todate || ''', 105)';
  END IF;
  IF (v_merchantname <> '') THEN
  v_query := v_query || ' AND DM.COMPANYNAME= ''' || v_merchantname || ''' ';
  END IF;
  IF (v_searchfield = 'EMAILID') THEN
  v_query := v_query || ' AND TD.EMAILID= ''' || v_searchvalue || ''' ';
  END IF;
  IF (v_searchfield = 'ACCOUNTNO') THEN
  v_query := v_query || ' AND BAD.ACCOUNTNO= ''' || v_searchvalue || ''' ';
  END IF;
  IF (v_searchfield = 'IFSCCODE') THEN
  v_query := v_query || ' AND BAD.IFSCCODE= ''' || v_searchvalue || ''' ';
  END IF;
  IF (v_searchfield = 'BANKNAME') THEN
  v_query := v_query || ' AND BAD.BANKNAME= ''' || v_searchvalue || ''' ';
  END IF;
  v_query := v_query || ' ';
  EXECUTE v_query;
  SELECT COALESCE(v_tempdid || ', ', '') || CAST(did AS VARCHAR) INTO v_tempdid FROM (SELECT DISTINCT did FROM tmp_temp) AS t;
  SELECT SUBSTRING(v_tempdid FROM 2 FOR LENGTH(CAST(v_tempdid AS TEXT))) INTO v_tempdid;
  v_index := 1;
  RETURN QUERY SELECT * FROM tmp_temp WHERE rownumber BETWEEN v_minindex AND v_maxindex;
  IF (v_mode = 1) THEN
  SELECT COUNT(rownumber) INTO v_totalcount FROM tmp_temp;
  END IF;
  SELECT COUNT(rownumber) INTO v_totalcount FROM tmp_temp;
  DROP TABLE IF EXISTS tmp_temp;
  -- SET option (removed)
END;
$$;


--
-- Name: usp_payyou_setting(character varying, character varying, character varying, bigint, numeric); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_payyou_setting(v_companypgmerchantkey character varying DEFAULT ''::character varying, v_companypgsalt character varying DEFAULT ''::character varying, INOUT v_result character varying DEFAULT NULL::character varying, v_pmid bigint DEFAULT 0, v_payutransationrate numeric DEFAULT 0) RETURNS character varying
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF EXISTS(SELECT 1 FROM distributor_master WHERE pmid = v_pmid) THEN
  IF NOT EXISTS(SELECT 1 FROM tbl_companysettings WHERE pmid = v_pmid) THEN
  INSERT INTO tbl_companysettings (companypgmerchantkey, companypgsalt, pmid, transationpayumoneyrate) VALUES (v_companypgmerchantkey, v_companypgsalt, v_pmid, v_payutransationrate);
  v_result := 'Insert';
  ELSE
  UPDATE tbl_companysettings SET companypgmerchantkey = v_companypgmerchantkey, companypgsalt = v_companypgsalt, transationpayumoneyrate = v_payutransationrate WHERE pmid = v_pmid;
  v_result := 'Update';
  END IF;
  ELSE
  v_result := 'Invalid Distributor';
  END IF;
END;
$$;


--
-- Name: usp_pdfupload(text, integer, integer, character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_pdfupload(v_pdfname text DEFAULT ''::text, v_pmid integer DEFAULT NULL::integer, INOUT v_intresult integer DEFAULT NULL::integer, v_title character varying DEFAULT NULL::character varying) RETURNS integer
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_err int;
  v_count int;
BEGIN
  -- BEGIN TRAN (removed)
  v_intresult := 0;
  SELECT COUNT(*) INTO v_count FROM pdfupload WHERE pmid = v_pmid;
  IF (v_count = 0) THEN
  INSERT INTO pdfupload (pmid, pdfname, title, active) VALUES (v_pmid, v_pdfname, v_title, 1);
  ELSE
  UPDATE pdfupload SET pdfname = v_pdfname, title = v_title WHERE pmid = v_pmid;
  END IF;
  IF (v_err <> 0) THEN
  v_intresult := 0;
  -- ROLLBACK (removed)
  RETURN;
  END IF;
  v_intresult := 1;
  -- COMMIT (removed)
END;
$$;


--
-- Name: usp_pending_listings_qa(character varying, character varying, integer, integer, bigint, character varying, character varying, character varying, character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_pending_listings_qa(v_fromdate character varying DEFAULT ''::character varying, v_todate character varying DEFAULT ''::character varying, v_pageno integer DEFAULT 1, v_pagesize integer DEFAULT 30, v_optid bigint DEFAULT NULL::bigint, v_type character varying DEFAULT NULL::character varying, v_operatorname character varying DEFAULT NULL::character varying, v_category character varying DEFAULT NULL::character varying, v_keyword character varying DEFAULT NULL::character varying) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_minindex int;
  v_maxindex int;
  v_recordcount int;
  v_amount numeric(19,4);
  v_currencysymbol varchar(20);
  v_totalamount numeric(19,4);
  v_sqlquery text;
BEGIN
  -- SET option (removed)
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp (rowNumber bigint,
lwq_id bigint,
title text,
LoginId varchar(100),
countryName varchar(25),
date  varchar(25),
optID varchar(100)) ON COMMIT DROP;
  v_minindex := 0;
  v_maxindex := 0;
  v_sqlquery := '';
  v_minindex := ((v_pageno - 1) * v_pagesize) + 1;
  v_maxindex := (v_pageno * v_pagesize);
  v_sqlquery := 'insert into #temp  select ROW_NUMBER() over(order by LW.date  desc) as rownumber,lw.lwq_id,Pm.title,pl.LoginId,C.countryName,LW.date,OM2.loginid as optID from tbl_ListingsWithQA LW
inner join portal_master Pm on LW.pmid=PM.pmid 
left join portal_login PL on Pm.pmid=PL.pmid 
left join tbl_operator_master OM on OM.optid=Pm.optid
left join COUNTRY C on C.CID=PL.cid 
left join tbl_operator_master OM2 on OM2.optid=Pm.optid where pm.isverified=0 and  LW.optid=' || CAST(v_optid AS VARCHAR(20));
  IF (v_category <> '') THEN
  v_sqlquery := v_sqlquery || 'and (catid in (CONVERT(text,' || v_category || ')) or catid like (''%,''+CONVERT(text,' || v_category || ')+'',%'') 
                     or catid like (CONVERT(text,' || v_category || ')+'',%'')  or catid like (''%,''+CONVERT(text, ' || v_category || ')))  and ISNULL(catid,'''') <> '''' ';
  END IF;
  IF (v_keyword <> '') THEN
  v_sqlquery := v_sqlquery || 'and (keyid in (CONVERT(text,' || v_keyword || ')) or keyid like (''%,''+CONVERT(text,' || v_keyword || ')+'',%'') 
                     or keyid like (CONVERT(text,' || v_keyword || ')+'',%'')  or keyid like (''%,''+CONVERT(text, ' || v_keyword || ')))  and ISNULL(keyid,'''') <> '''' ';
  END IF;
  IF (v_fromdate <> '') THEN
  v_sqlquery := v_sqlquery || ' and convert(date, lw.date,103) = convert(date,''' || v_fromdate || ''',103) ';
  END IF;
  IF (v_todate <> '') THEN
  v_sqlquery := v_sqlquery || ' and convert(date, lw.date,103)  =convert(date,''' || v_todate || ''',103) ';
  END IF;
  IF (v_fromdate <> '' AND v_todate <> '') THEN
  v_sqlquery := v_sqlquery || ' and convert(date, lw.date,103)  between  convert(date,''' || v_fromdate || ''',103)  and convert(date,''' || v_todate || ''',103)';
  END IF;
  IF (v_type = 'r') THEN
  v_sqlquery := v_sqlquery || ' and isnull(pm.optid,0)=0 ';
  END IF;
  IF (v_type = 'o') THEN
  v_sqlquery := v_sqlquery || ' and isnull(pm.optid,0)>0 ';
  END IF;
  IF (v_operatorname <> 0) THEN
  v_sqlquery := v_sqlquery || ' and isnull(pm.optid,0)=' || v_operatorname;
  END IF;
  EXECUTE v_sqlquery;
  SELECT COUNT(*) INTO v_recordcount FROM tmp_temp;
  RETURN QUERY SELECT *, v_recordcount AS recordcount FROM tmp_temp WHERE rownumber BETWEEN v_minindex AND v_maxindex;
  DROP TABLE IF EXISTS tmp_temp;
  -- SET option (removed)
END;
$$;


