--
-- Name: usp_pendingbusinesslistings(integer, integer, character varying, boolean, character varying, character varying, character varying, character varying, character varying, character varying, character varying, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_pendingbusinesslistings(v_startrowindex integer, v_maxrows integer, v_orderbyfield character varying, v_asc boolean, v_searchfield character varying, v_searchvalue character varying, v_cid character varying DEFAULT ''::character varying, v_ctid character varying DEFAULT ''::character varying, v_fromdate character varying DEFAULT ''::character varying, v_todate character varying DEFAULT ''::character varying, v_type character varying DEFAULT ''::character varying, v_mode integer DEFAULT NULL::integer) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_recordcount int;
  v_isroll varchar(50);
  v_cramt numeric(19,4);
  v_sqlquery text;
BEGIN
  -- SET option (removed)
  v_sqlquery := '';
  v_isroll := 'normal';
  IF (v_orderbyfield = '') THEN
  v_orderbyfield := 'PMT.request_date desc';
  END IF;
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp (rowNumber bigint,
pmtid bigint,
companyname text,
loginID varchar(150),
doc timestamp,
countryName varchar(50),
ipaddress varchar(50)) ON COMMIT DROP;
  v_sqlquery := 'insert into #temp select ROW_NUMBER() over(order by ' || v_orderbyfield || ') as rowNumber,PMT.pmtid,PMT.companyname,isnull(PLT.LoginId,''-''),
	 	  PMT.request_date as doc,(case when C.countryName=''UNITED STATES'' then ''US'' when C.countryName=''UNITED KINGDOM'' then ''UK'' else  C.countryName end  ) as countryName,PLT.ipaddress from portal_master_temp PMT
left join Portal_Login_temp PLT on PMT.pmtid=PLT.pmtid
 left join country C on PMT.cid=C.CID where isnull(PMT.cid,0)>0  and PMT.active=0  ';
  IF (v_cid <> '') THEN
  v_sqlquery := v_sqlquery || (' and ('',''+convert(varchar(50),PMT.cid)+'','') like  ''%,' || '' || CAST(v_cid AS text) || '' || ',%''');
  END IF;
  IF (v_fromdate <> '') THEN
  v_sqlquery := v_sqlquery || ' and convert(date, PMT.request_date,103) = convert(date,''' || v_fromdate || ''',103) ';
  END IF;
  IF (v_todate <> '') THEN
  v_sqlquery := v_sqlquery || ' and convert(date, PMT.request_date,103)  =convert(date,''' || v_todate || ''',103) ';
  END IF;
  IF (v_type = 'Referral') THEN
  v_sqlquery := v_sqlquery || 'and PLT.intro_refid >0';
  END IF;
  IF (v_fromdate <> '' AND v_todate <> '') THEN
  v_sqlquery := v_sqlquery || ' and convert(date, PMT.request_date,103)  between  convert(date,''' || v_fromdate || ''',103)  and convert(date,''' || v_todate || ''',103)';
  END IF;
  IF (v_searchfield = 'loginid') THEN
  v_sqlquery := v_sqlquery || ' and PLT.loginid like ''%' || v_searchvalue || '%''';
  END IF;
  IF (v_searchfield = 'username') THEN
  v_sqlquery := v_sqlquery || ' and PLT.username like ''%' || v_searchvalue || '%''';
  END IF;
  IF (v_searchfield = 'introid') THEN
  v_sqlquery := v_sqlquery || ' and PLT.intro_refid like ''%' || v_searchvalue || '%''';
  END IF;
  IF (v_searchfield = 'business') THEN
  v_sqlquery := v_sqlquery || ' and PMT.companyname like ''%' || v_searchvalue || '%''';
  END IF;
  EXECUTE v_sqlquery;
  SELECT COUNT(*) INTO v_recordcount FROM tmp_temp;
  RETURN QUERY SELECT * FROM tmp_temp WHERE rownumber BETWEEN v_startrowindex AND v_maxrows;
  DROP TABLE IF EXISTS tmp_temp;
  RETURN QUERY SELECT v_recordcount AS recordcount;
END;
$$;


--
-- Name: usp_pendingkyc(integer, integer, character varying, character varying, character varying, integer, integer, character varying, character varying, character varying, character varying, character varying, integer, character varying, character varying, integer, integer, integer, integer, integer, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_pendingkyc(v_startrowindex integer DEFAULT 1, v_maxrows integer DEFAULT 100, v_name character varying DEFAULT ''::character varying, v_mobile character varying DEFAULT ''::character varying, v_email character varying DEFAULT ''::character varying, v_freeorpaid integer DEFAULT 1, v_recordcount integer DEFAULT 0, v_fromdate character varying DEFAULT ''::character varying, v_todate character varying DEFAULT ''::character varying, v_submittedfromdate character varying DEFAULT ''::character varying, v_submittedtodate character varying DEFAULT ''::character varying, v_orderby character varying DEFAULT 'desc'::character varying, v_isfirsttimeorafterrejectionparam integer DEFAULT 0, v_lastupdateddatebyuserfromdate character varying DEFAULT ''::character varying, v_lastupdateddatebyusertodate character varying DEFAULT ''::character varying, v_profilestatusparam integer DEFAULT 2, v_kycstatusparam integer DEFAULT 0, v_mode integer DEFAULT 2, v_index integer DEFAULT 0, v_regnum integer DEFAULT 0, v_businesskycstatus integer DEFAULT '-1'::integer) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_count INT;
  v_regno INT;
  v_idproof INT;
  v_photograph INT;
  v_pancarddetails INT;
  v_bankpassbook INT;
  v_kycdate VARCHAR(50);
  v_isfirsttimeorafterrejection Int;
  v_lastupdateddatebyuser timestamp;
  v_profilestatus INT;
  v_kycstatus INT;
  v_photographimg VARCHAR(100);
  v_idproofimg VARCHAR(100);
  v_pancarddetailsimg VARCHAR(100);
  v_bankpassbookimg VARCHAR(100);
  v_query text;
  v_newusername varchar(200);
  v_companydeed INT;
  v_partnershipdeed INT;
  v_addressproof INT;
  v_incorporationcertificate INT;
  v_memorandumofassociationproof INT;
  v_pancarddetails2 INT;
  v_companydeedimg text;
  v_partnershipdeedimg text;
  v_addressproofimg text;
  v_incorporationcertificateimg text;
  v_memorandumofassociationproofimg text;
  v_pancarddetailsimg2 text;
  v_newusername2 varchar(200);
  v_entitytype INT;
  v_bankdetailscount Int;
BEGIN
  v_count := 0;
  v_regno := 0;
  v_idproof := 0;
  v_photograph := 0;
  v_pancarddetails := 0;
  v_bankpassbook := 0;
  v_kycdate := '';
  v_isfirsttimeorafterrejection := 0;
  v_profilestatus := 0;
  v_kycstatus := 0;
  v_query := '';
  IF (v_mode = 1) THEN
  IF (v_index = 4) THEN
  RETURN QUERY SELECT image FROM kyc WHERE regno = v_regnum AND type = 'Pancard-Details';
  END IF;
  IF (v_index = 5) THEN
  RETURN QUERY SELECT image FROM kyc WHERE regno = v_regnum AND type = 'photograph';
  END IF;
  IF (v_index = 6) THEN
  RETURN QUERY SELECT image FROM kyc WHERE regno = v_regnum AND type = 'IDProof';
  END IF;
  IF (v_index = 7) THEN
  RETURN QUERY SELECT image FROM kyc WHERE regno = v_regnum AND type = 'bank-passbook';
  END IF;
  RETURN;
  ELSE
  IF (v_mode = 0) THEN
  DROP TABLE IF EXISTS tmp_portallogin;
  CREATE TEMP TABLE tmp_portallogin (ROWNUMBER INT GENERATED BY DEFAULT AS IDENTITY,
REGNO INT,
NAME VARCHAR(100),
MOBILE VARCHAR(20),
EMAILID VARCHAR(100),
IsFirstTimeOrAfterRejection Int,
KYCDATE VARCHAR(50),
LASTUPDATEDDATEBYUSER timestamp,
PROFILESTATUS INT,
KYCSTATUS INT,
ISIDPROOF INT,
ISPHOTOGRAPH INT,
ISPANCARDDETAILS INT,
ISBANKPASSBOOK INT,
PHOTOGRAPH VARCHAR(100),
IDPROOF VARCHAR(100),
