  ELSE
  IF (v_submittedtodate <> '') THEN
  v_query := v_query || '  AND CONVERT(DATE, LASTUPDATEDDATEBYUSER,105) = CONVERT(DATE,''' || v_submittedtodate || ''',105)';
  END IF;
  END IF;
  END IF;
  IF (v_fromdate <> '' AND v_todate <> '') THEN
  v_query := v_query || '  AND CONVERT(DATE, KYCDATE)  >= CONVERT(DATE,''' || v_fromdate || ''')  
 AND CONVERT(DATE, KYCDATE) <= CONVERT(DATE,''' || v_todate || ''')';
  ELSE
  IF (v_fromdate <> '') THEN
  v_query := v_query || '  AND CONVERT(DATE, KYCDATE) = CONVERT(DATE,''' || v_fromdate || ''')';
  ELSE
  IF (v_todate <> '') THEN
  v_query := v_query || '  AND CONVERT(DATE, KYCDATE) = CONVERT(DATE,''' || v_todate || ''')';
  END IF;
  END IF;
  END IF;
  IF (v_isfirsttimeorafterrejectionparam <> 0) THEN
  v_query := v_query || '  AND IsFirstTimeOrAfterRejection=' || CAST(v_isfirsttimeorafterrejectionparam AS VARCHAR(100)) || '';
  END IF;
  IF (v_businesskycstatus <> '-1') THEN
  v_query := v_query || '  AND PM.ISVERIFIED=' || CAST(v_businesskycstatus AS VARCHAR(100)) || '';
  END IF;
  IF (v_kycstatusparam <> '2') THEN
  v_query := v_query || '  AND #PORTALLOGIN2.KYCSTATUS=' || CAST(v_kycstatusparam AS VARCHAR(100)) || '';
  END IF;
  IF (v_orderby = 'ASC') THEN
  v_query := v_query || (' ORDER BY LASTUPDATEDDATEBYUSER ASC');
  ELSE
  v_query := v_query || (' ORDER BY #PORTALLOGIN2.plid DESC');
  END IF;
  EXECUTE v_query;
  RETURN QUERY SELECT rownumber, regno, name, mobile, emailid, isfirsttimeorafterrejection, CAST(TO_CHAR(lastupdateddatebyuser, 'DD TMMon YYYY HH24:MI:SS:US') AS VARCHAR(20)) AS lastupdateddatebyuser, profilestatus, kycstatus, iscompanydeed, ispancarddetails, ispartnershipdeed, isaddressproof, ismemorandumofassociationproof, isincorporationcertificate, companydeed, partnershipdeed, pancarddetails, incorporationcertificate, memorandumofassociationproof, addressproof, businessname, COALESCE(entitype, '') AS entitype FROM tmp_templogin2 WHERE rownumber BETWEEN v_startrowindex AND v_maxrows;
  SELECT COUNT(1) INTO v_recordcount FROM tmp_templogin2;
  DROP TABLE IF EXISTS tmp_portallogin2;
  DROP TABLE IF EXISTS tmp_templogin2;
  END IF;
  END IF;
  END IF;
END;
$$;


--
-- Name: usp_pendingkyc_reseller(integer, integer, character varying, character varying, character varying, integer, integer, character varying, character varying, character varying, character varying, character varying, integer, character varying, character varying, integer, integer, integer, integer, integer, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_pendingkyc_reseller(v_startrowindex integer DEFAULT 1, v_maxrows integer DEFAULT 100, v_name character varying DEFAULT ''::character varying, v_mobile character varying DEFAULT ''::character varying, v_email character varying DEFAULT ''::character varying, v_freeorpaid integer DEFAULT '-1'::integer, v_recordcount integer DEFAULT 0, v_fromdate character varying DEFAULT ''::character varying, v_todate character varying DEFAULT ''::character varying, v_submittedfromdate character varying DEFAULT ''::character varying, v_submittedtodate character varying DEFAULT ''::character varying, v_orderby character varying DEFAULT 'desc'::character varying, v_isfirsttimeorafterrejectionparam integer DEFAULT 0, v_lastupdateddatebyuserfromdate character varying DEFAULT ''::character varying, v_lastupdateddatebyusertodate character varying DEFAULT ''::character varying, v_profilestatusparam integer DEFAULT 0, v_kycstatusparam integer DEFAULT 2, v_mode integer DEFAULT 2, v_index integer DEFAULT 0, v_regnum integer DEFAULT 0, v_businesskycstatus integer DEFAULT '-1'::integer) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
