  v_entitytype INT;
  v_bankdetailscount Int;
BEGIN
  v_count := 0;
  v_regno := 0;
  v_idproof := 0;
  v_photograph := 0;
  v_pancarddetails := 0;
  v_bankpassbook := 0;
  v_kycdate := '';
  v_isfirsttimeorafterrejection := 0;
  v_profilestatus := 0;
  v_kycstatus := 0;
  v_kycbankstatus := 0;
  v_productpackage := '';
  v_utilitypackage := '';
  v_travelpackage := '';
  v_dealspackage := '';
  v_query := '';
  v_softwareurl := '';
  SELECT COALESCE(software_url, '') INTO v_softwareurl FROM tbl_company LIMIT 1;
  IF (v_mode = 1) THEN
  IF (v_index = 4) THEN
  RETURN QUERY SELECT image FROM kyc WHERE regno = v_regnum AND type = 'Pancard-Details';
  END IF;
  IF (v_index = 5) THEN
  RETURN QUERY SELECT image FROM kyc_distributor WHERE regno = v_regnum AND type = 'photograph';
  END IF;
  IF (v_index = 6) THEN
  RETURN QUERY SELECT image FROM kyc_distributor WHERE regno = v_regnum AND type = 'IDProof';
  END IF;
  IF (v_index = 7) THEN
  RETURN QUERY SELECT image FROM kyc_distributor WHERE regno = v_regnum AND type = 'bank-passbook';
  END IF;
  RETURN;
  ELSE
  IF (v_mode = 0) THEN
  DROP TABLE IF EXISTS tmp_portallogin;
  CREATE TEMP TABLE tmp_portallogin (ROWNUMBER INT GENERATED BY DEFAULT AS IDENTITY,
REGNO INT,
NAME VARCHAR(100),
MOBILE VARCHAR(20),
EMAILID VARCHAR(100),
IsFirstTimeOrAfterRejection Int,
KYCDATE VARCHAR(50),
LASTUPDATEDDATEBYUSER timestamp,
PROFILESTATUS INT,
KYCSTATUS INT,
ISIDPROOF INT,
ISPHOTOGRAPH INT,
ISPANCARDDETAILS INT,
ISBANKPASSBOOK INT,
PHOTOGRAPH VARCHAR(100),
IDPROOF VARCHAR(100),
PANCARDDETAILS VARCHAR(100),
BANKPASSBOOK VARCHAR(100)) ON COMMIT DROP;
  v_query := 'INSERT INTO #PORTALLOGIN SELECT REGNO,(USERNAME) AS NAME,
ISNULL(PHONE,''''),EMAILID,0,'''','''',0,0,0,0,0,0,'''','''','''','''' 
FROM TBL_DISTRIBUTOR WHERE Status=1 ';
  IF (v_name <> '') THEN
  IF (EXISTS(SELECT 1 FROM tbl_distributor WHERE username = v_name)) THEN
  v_query := v_query || (' AND USERNAME LIKE ''%' || v_name || '%''');
  ELSE
  IF (EXISTS(SELECT 1 FROM distributor_login_history WHERE username = v_name)) THEN
  v_newusername := '';
  SELECT (SELECT username FROM distributor_login WHERE did IN (SELECT did FROM distributor_login_history WHERE username = v_name)) INTO v_newusername;
  v_query := v_query || (' AND USERNAME LIKE ''%' || v_newusername || '%''');
  ELSE
  v_query := v_query || ' AND USERNAME LIKE ''%' || v_name || '%'' ';
  END IF;
  END IF;
  END IF;
  IF (v_mobile <> '') THEN
  v_query := v_query || ' AND PHONE LIKE ''%' || v_mobile || '%''';
  END IF;
  IF (v_email <> '') THEN
  v_query := v_query || ' AND EMAILID LIKE ''%' || v_email || '%''';
  END IF;
  IF (v_freeorpaid = 0) THEN
  v_query := v_query || ' AND DID NOT IN (Select PLID From Tbl_AllSubscriptionMaster Where ISNULL(IsApproved,0)=1)';
  END IF;
  IF (v_freeorpaid = 0) THEN
  v_query := v_query || ' AND DID IN (Select PLID From Tbl_AllSubscriptionMaster Where ISNULL(IsApproved,0)=1)';
  END IF;
  EXECUTE v_query;
  SELECT COUNT(regno) INTO v_count FROM tmp_portallogin;
  WHILE (v_count > 0) LOOP
  SELECT 0, 0, 0, 0, 0 INTO v_idproof, v_photograph, v_pancarddetails, v_bankpassbook, v_regno;
  SELECT regno INTO v_regno FROM tmp_portallogin WHERE rownumber = v_count;
  SELECT COALESCE(MAX(isaprove), 3) INTO v_idproof FROM kyc_distributor WHERE type = 'IDPROOF' AND regno = v_regno;
  SELECT COALESCE(MAX(isaprove), 3) INTO v_photograph FROM kyc_distributor WHERE type = 'PHOTOGRAPH' AND regno = v_regno;
  SELECT COALESCE(MAX(isaprove), 3) INTO v_pancarddetails FROM kyc_distributor WHERE type = 'PANCARD-DETAILS' AND regno = v_regno;
  SELECT COALESCE(MAX(isaprove), 3) INTO v_bankpassbook FROM kyc_distributor WHERE type = 'BANK-PASSBOOK' AND regno = v_regno;
  SELECT MAX(COALESCE(CAST(dtm_date AS DATE), '')) INTO v_kycdate FROM kyc_distributor WHERE regno = v_regno;
  SELECT COUNT(1) INTO v_isfirsttimeorafterrejection FROM kyc_distributor WHERE COALESCE(isfirsttimeorafterrejection, 0) = 2;
  SELECT MAX(COALESCE(CAST(lastupdateddate AS TIMESTAMP), '')) INTO v_lastupdateddatebyuser FROM kyc_distributor WHERE regno = v_regno;
  SELECT COALESCE(is_profile_status, 0) INTO v_profilestatus FROM member_master WHERE regno = v_regno;
  SELECT COUNT(1) INTO v_kycstatus FROM kyc_distributor WHERE regno = v_regno AND COALESCE(isaprove, 0) = 1;
  SELECT COUNT(1) INTO v_kycbankstatus FROM bank_accounts_distributor WHERE did = v_regno AND isaprove = 1;
  SELECT '' || v_softwareurl || '/Kyc_Images/' || image INTO v_photographimg FROM kyc_distributor WHERE type = 'IDPROOF' AND regno = v_regno;
  SELECT '' || v_softwareurl || '/Kyc_Images/' || image INTO v_idproofimg FROM kyc_distributor WHERE type = 'IDPROOF' AND regno = v_regno;
  SELECT '' || v_softwareurl || '/Kyc_Images/' || image INTO v_pancarddetailsimg FROM kyc_distributor WHERE type = 'PANCARD-DETAILS' AND regno = v_regno;
  SELECT '' || v_softwareurl || '/Kyc_Images/' || image INTO v_bankpassbookimg FROM kyc_distributor WHERE type = 'BANK-PASSBOOK' AND regno = v_regno;
  SELECT (CASE WHEN v_kycstatus = 4 THEN 1 ELSE 0 END) INTO v_kycstatus;
  SELECT (CASE WHEN v_isfirsttimeorafterrejection > 0 THEN 1 ELSE 0 END) INTO v_isfirsttimeorafterrejection;
  IF (v_idproof = 1 AND v_photograph = 1 AND v_pancarddetails = 1 AND v_bankpassbook = 1) THEN
  DELETE FROM tmp_portallogin WHERE rownumber = v_count;
  ELSE
  UPDATE tmp_portallogin SET isidproof = v_idproof, isphotograph = v_photograph, ispancarddetails = v_pancarddetails, isbankpassbook = v_bankpassbook, kycdate = v_kycdate, isfirsttimeorafterrejection = v_isfirsttimeorafterrejection, lastupdateddatebyuser = v_lastupdateddatebyuser, profilestatus = v_profilestatus, kycstatus = v_kycstatus, photograph = v_photographimg, idproof = v_idproofimg, pancarddetails = v_pancarddetailsimg, bankpassbook = v_bankpassbookimg WHERE rownumber = v_count;
  END IF;
  v_count := v_count - 1;
  END LOOP;
  v_query := '';
  DROP TABLE IF EXISTS tmp_templogin;
  CREATE TEMP TABLE tmp_templogin (ROWNUMBER INT GENERATED BY DEFAULT AS IDENTITY,
REGNO INT,
NAME VARCHAR(500),
MOBILE VARCHAR(500),
EMAILID VARCHAR(500),
IsFirstTimeOrAfterRejection VARCHAR(500),
LASTUPDATEDDATEBYUSER VARCHAR(500),
PROFILESTATUS VARCHAR(500),
KYCSTATUS VARCHAR(500),
ISPHOTOGRAPH VARCHAR(500),
ISPANCARDDETAILS VARCHAR(500),
ISBANKPASSBOOK VARCHAR(500),
ISIDPROOF VARCHAR(500),
PHOTOGRAPH VARCHAR(100),
IDPROOF VARCHAR(100),
PANCARDDETAILS VARCHAR(100),
BANKPASSBOOK VARCHAR(100)) ON COMMIT DROP;
  v_query := 'INSERT INTO #TEMPLOGIN SELECT REGNO,NAME,MOBILE,EMAILID,
(CASE WHEN IsFirstTimeOrAfterRejection=0 Then ''New KYC'' ELSE ''Rejected KYC'' END)As IsFirstTimeOrAfterRejection,
 LASTUPDATEDDATEBYUSER,
(CASE WHEN PROFILESTATUS=0 THEN ''Pending'' WHEN PROFILESTATUS=2 THEN ''<i class="fa fa-times" aria-hidden="true"></i>'' ELSE ''<i class="fa fa-check" aria-hidden="true"></i>'' END) AS PROFILESTATUS,
(CASE WHEN KYCSTATUS=0 THEN ''Not Uploaded'' WHEN KYCSTATUS=2 THEN ''Pending'' WHEN KYCSTATUS=3 THEN ''Rejected'' ELSE ''Approved'' END) AS KYCSTATUS,
(CASE WHEN ISPHOTOGRAPH=3 THEN ''Pending'' WHEN ISPHOTOGRAPH=0 THEN ''<i class="fa fa-times" aria-hidden="true"></i>'' ELSE ''<i class="fa fa-check" aria-hidden="true"></i><i class="fa fa-list-alt" aria-hidden="true"></i>'' END) AS ISPHOTOGRAPH,
(CASE WHEN ISPANCARDDETAILS=3 THEN ''Pending'' WHEN ISPANCARDDETAILS=0 THEN ''<i class="fa fa-times" aria-hidden="true"></i>'' ELSE ''<i class="fa fa-check" aria-hidden="true"></i><i class="fa fa-list-alt" aria-hidden="true"></i>'' END)
 AS ISPANCARDDETAILS,
(CASE WHEN ISBANKPASSBOOK=3 THEN ''Pending'' WHEN ISBANKPASSBOOK=0 THEN ''<i class="fa fa-times" aria-hidden="true"></i>'' ELSE ''<i class="fa fa-check" aria-hidden="true"></i><i class="fa fa-list-alt" aria-hidden="true"></i>'' END) AS ISBANKPASSBOOK,
(CASE WHEN ISIDPROOF=3 THEN ''Pending'' WHEN ISIDPROOF=0 THEN ''<i class="fa fa-times" aria-hidden="true"></i>'' ELSE ''<i class="fa fa-check" aria-hidden="true"></i><i class="fa fa-list-alt" aria-hidden="true"></i>'' END) AS ISIDPROOF,
PHOTOGRAPH,IDPROOF,PANCARDDETAILS,BANKPASSBOOK
FROM #PORTALLOGIN WHERE REGNO<>0 ';
  IF (v_lastupdateddatebyuserfromdate <> '' AND v_lastupdateddatebyusertodate <> '') THEN
  v_query := v_query || '  AND CONVERT(DATE, LASTUPDATEDDATEBYUSER)  >= CONVERT(DATE,''' || v_lastupdateddatebyuserfromdate || ''')  
 AND CONVERT(DATE, LASTUPDATEDDATEBYUSER) <= CONVERT(DATE,''' || v_lastupdateddatebyusertodate || ''')';
  ELSE
  IF (v_lastupdateddatebyuserfromdate <> '') THEN
  v_query := v_query || '  AND CONVERT(DATE, LASTUPDATEDDATEBYUSER) = CONVERT(DATE,''' || v_lastupdateddatebyuserfromdate || ''')';
  ELSE
  IF (v_lastupdateddatebyusertodate <> '') THEN
  v_query := v_query || ' AND CONVERT(DATE, LASTUPDATEDDATEBYUSER) = CONVERT(DATE,''' || v_lastupdateddatebyusertodate || ''')';
  END IF;
  END IF;
  END IF;
  IF (v_submittedfromdate <> '' AND v_submittedtodate <> '') THEN
  v_query := v_query || '  AND CONVERT(DATE, LASTUPDATEDDATEBYUSER)  >= CONVERT(DATE,''' || v_submittedfromdate || ''')  
 AND CONVERT(DATE, LASTUPDATEDDATEBYUSER) <= CONVERT(DATE,''' || v_submittedtodate || ''')';
  ELSE
  IF (v_submittedfromdate <> '') THEN
  v_query := v_query || '  AND CONVERT(DATE, LASTUPDATEDDATEBYUSER) = CONVERT(DATE,''' || v_submittedfromdate || ''')';
  ELSE
  IF (v_submittedtodate <> '') THEN
  v_query := v_query || '  AND CONVERT(DATE, LASTUPDATEDDATEBYUSER) = CONVERT(DATE,''' || v_submittedtodate || ''')';
  END IF;
  END IF;
  END IF;
  IF (v_fromdate <> '' AND v_todate <> '') THEN
  v_query := v_query || '  AND CONVERT(DATE, KYCDATE)  >= CONVERT(DATE,''' || v_fromdate || ''')  
 AND CONVERT(DATE, KYCDATE) <= CONVERT(DATE,''' || v_todate || ''')';
  ELSE
  IF (v_fromdate <> '') THEN
  v_query := v_query || '  AND CONVERT(DATE, KYCDATE) = CONVERT(DATE,''' || v_fromdate || ''')';
  ELSE
  IF (v_todate <> '') THEN
  v_query := v_query || '  AND CONVERT(DATE, KYCDATE) = CONVERT(DATE,''' || v_todate || ''')';
  END IF;
  END IF;
  END IF;
  IF (v_isfirsttimeorafterrejectionparam <> 0) THEN
  v_query := v_query || '  AND IsFirstTimeOrAfterRejection=' || CAST(v_isfirsttimeorafterrejectionparam AS VARCHAR(100)) || '';
  END IF;
  IF (v_profilestatusparam <> 2) THEN
  v_query := v_query || '  AND PROFILESTATUS=' || CAST(v_profilestatusparam AS VARCHAR(100)) || '';
  END IF;
  IF (v_kycstatusparam <> 2) THEN
  v_query := v_query || '  AND KYCSTATUS=' || CAST(v_kycstatusparam AS VARCHAR(100)) || '';
  END IF;
  IF (v_orderby = 'ASC') THEN
  v_query := v_query || (' ORDER BY LASTUPDATEDDATEBYUSER ASC');
  ELSE
  v_query := v_query || (' ORDER BY LASTUPDATEDDATEBYUSER DESC');
  END IF;
  EXECUTE v_query;
  RETURN QUERY SELECT rownumber, regno, name, mobile, emailid, isfirsttimeorafterrejection, CAST(TO_CHAR(lastupdateddatebyuser, 'DD TMMon YYYY HH24:MI:SS:US') AS VARCHAR(20)) AS lastupdateddatebyuser, profilestatus, kycstatus, isphotograph, ispancarddetails, isbankpassbook, isidproof, photograph, idproof, pancarddetails, bankpassbook FROM tmp_templogin WHERE rownumber BETWEEN v_startrowindex AND v_maxrows;
  SELECT COUNT(1) INTO v_recordcount FROM tmp_portallogin;
  DROP TABLE IF EXISTS tmp_portallogin;
  DROP TABLE IF EXISTS tmp_templogin;
  ELSE
  IF (v_mode = 2) THEN
  v_companydeed := 0;
  v_partnershipdeed := 0;
  v_addressproof := 0;
  v_incorporationcertificate := 0;
  v_memorandumofassociationproof := 0;
  v_pancarddetails2 := 0;
  v_companydeedimg := '';
  v_partnershipdeedimg := '';
  v_addressproofimg := '';
  v_incorporationcertificateimg := '';
  v_memorandumofassociationproofimg := '';
  v_pancarddetailsimg2 := '';
  DROP TABLE IF EXISTS tmp_portallogin2;
  CREATE TEMP TABLE tmp_portallogin2 (ROWNUMBER INT GENERATED BY DEFAULT AS IDENTITY,
REGNO INT,
NAME VARCHAR(100),
MOBILE VARCHAR(20),
EMAILID VARCHAR(100),
IsFirstTimeOrAfterRejection Int,
KYCDATE VARCHAR(50),
LASTUPDATEDDATEBYUSER timestamp,
PROFILESTATUS INT,
KYCSTATUS INT,
ISCOMPANYDEED INT,
ISPARTNERSHIPDEED INT,
ISPANCARDDETAILS INT,
ISADDRESSPROOF INT,
ISINCORPORATIONCERTIFICATE INT,
ISMEMORANDUMOFASSOCIATIONPROOF INT,
COMPANYDEED VARCHAR(100),
PARTNERSHIPDEED VARCHAR(100),
PANCARDDETAILS VARCHAR(100),
ADDRESSPROOF VARCHAR(100),
INCORPORATIONCERTIFICATE VARCHAR(100),
MEMORANDUMOFASSOCIATIONPROOF VARCHAR(100),
Businessname varchar(100),
Entitype int,
PACKAGENAME Varchar(100),
ProductPackge Varchar(100),
TravelPackage Varchar(100),
DealsPackage Varchar(100)) ON COMMIT DROP;
  v_query := '';
  v_query := 'INSERT INTO #PORTALLOGIN2 SELECT DISTINCT REGNO,(USERNAME) AS NAME,
ISNULL(PHONE,''''),EMAILID,0,'''','''',0,0,0,0,0,0,0,0,'''','''','''','''','''','''','''','''', 
'''','''','''',''''
FROM TBL_DISTRIBUTOR TD
 WHERE TD.Status=1 ';
  IF (v_name <> '') THEN
  IF (EXISTS(SELECT 1 FROM tbl_distributor WHERE username = v_name)) THEN
  v_query := v_query || (' AND USERNAME LIKE ''%' || v_name || '%''');
  ELSE
  IF (EXISTS(SELECT 1 FROM distributor_login_history WHERE username = v_name)) THEN
  v_newusername2 := '';
  SELECT (SELECT username FROM distributor_login WHERE did IN (SELECT did FROM distributor_login_history WHERE username = v_name)) INTO v_newusername2;
  v_query := v_query || (' AND USERNAME LIKE ''%' || v_newusername2 || '%''');
  ELSE
  v_query := v_query || ' AND USERNAME LIKE ''%' || v_name || '%'' ';
  END IF;
  END IF;
  END IF;
  IF (v_mobile <> '') THEN
  v_query := v_query || ' AND PHONE LIKE ''%' || v_mobile || '%''';
  END IF;
  IF (v_email <> '') THEN
  v_query := v_query || ' AND EMAILID LIKE ''%' || v_email || '%''';
  END IF;
  IF (v_freeorpaid = 0) THEN
  v_query := v_query || ' AND PLID NOT IN (Select PLID From Tbl_AllSubscriptionMaster Where ISNULL(IsApproved,0)=1)';
  END IF;
  IF (v_freeorpaid = 0) THEN
  v_query := v_query || ' AND PLID IN (Select PLID From Tbl_AllSubscriptionMaster Where ISNULL(IsApproved,0)=1)';
  END IF;
  RAISE NOTICE '%', v_query;
  EXECUTE v_query;
  SELECT COUNT(regno) INTO v_count FROM tmp_portallogin2;
  WHILE (v_count > 0) LOOP
  SELECT 0, 0, 0, 0, '', 0, 0, 0 INTO v_pancarddetails2, v_regno, v_companydeed, v_partnershipdeed, v_kycdate, v_addressproof, v_incorporationcertificate, v_memorandumofassociationproof;
  SELECT regno INTO v_regno FROM tmp_portallogin2 WHERE rownumber = v_count;
  SELECT COALESCE(MAX(isaprove), 3) INTO v_companydeed FROM kyc_distributor WHERE type = 'Deed' AND regno = v_regno;
  SELECT COALESCE(MAX(isaprove), 3) INTO v_partnershipdeed FROM kyc_distributor WHERE type = 'Partnership-Deed' AND regno = v_regno;
  SELECT COALESCE(MAX(isaprove), 3) INTO v_pancarddetails2 FROM kyc_distributor WHERE type = 'Pancard-Details' AND regno = v_regno;
  SELECT COALESCE(MAX(isaprove), 3) INTO v_addressproof FROM kyc_distributor WHERE type = 'Address-Proof' AND regno = v_regno;
  SELECT COALESCE(MAX(isaprove), 3) INTO v_memorandumofassociationproof FROM kyc_distributor WHERE type = 'Memorandum-Of-Association' AND regno = v_regno;
  SELECT COALESCE(MAX(isaprove), 3) INTO v_incorporationcertificate FROM kyc_distributor WHERE type = 'Incorporation-Certificate' AND regno = v_regno;
  SELECT MAX(COALESCE(CAST(dtm_date AS DATE), '')) INTO v_kycdate FROM kyc_distributor WHERE regno = v_regno;
  SELECT COUNT(1) INTO v_isfirsttimeorafterrejection FROM kyc_distributor WHERE COALESCE(isfirsttimeorafterrejection, 0) = 2;
  SELECT MAX(COALESCE(CAST(registrationdate AS TIMESTAMP), '')) INTO v_lastupdateddatebyuser FROM tbl_distributor WHERE did = v_regno;
  SELECT COALESCE(is_profile_status, 0) INTO v_profilestatus FROM member_master WHERE regno = v_regno;
  SELECT COUNT(1) INTO v_kycstatus FROM kyc_distributor WHERE regno = v_regno AND COALESCE(isaprove, 0) = 1;
  SELECT COUNT(1) INTO v_kycbankstatus FROM bank_accounts_distributor WHERE did = v_regno AND isaprove = 1;
  SELECT '' || v_softwareurl || '/Kyc_Images/' || image INTO v_companydeedimg FROM kyc_distributor WHERE type = 'Deed' AND regno = v_regno;
  SELECT '' || v_softwareurl || '/Kyc_Images/' || image INTO v_partnershipdeedimg FROM kyc_distributor WHERE type = 'Partnership-Deed' AND regno = v_regno;
  SELECT '' || v_softwareurl || '/Kyc_Images/' || image INTO v_addressproofimg FROM kyc_distributor WHERE type = 'Address' AND regno = v_regno;
  SELECT '' || v_softwareurl || '/Kyc_Images/' || image INTO v_incorporationcertificateimg FROM kyc_distributor WHERE type = 'Incorporation-Certificate' AND regno = v_regno;
  SELECT '' || v_softwareurl || '/Kyc_Images/' || image INTO v_memorandumofassociationproofimg FROM kyc_distributor WHERE type = 'Memorandum-Of-Association' AND regno = v_regno;
  SELECT '' || v_softwareurl || '/Kyc_Images/' || image INTO v_pancarddetailsimg2 FROM kyc_distributor WHERE type = 'Pancard-Details' AND regno = v_regno;
  v_entitytype := 0;
  v_bankdetailscount := 0;
  v_entitytype := (SELECT DISTINCT COALESCE(entitytype, 0) FROM tbl_businesskycdetails_distributor WHERE did = v_regno);
  SELECT COUNT(1) INTO v_bankdetailscount FROM bank_accounts_distributor WHERE did = v_regno AND active = 1;
  IF (v_entitytype = 1 AND v_bankdetailscount = 1) THEN
  SELECT (CASE WHEN v_kycstatus = 2 THEN 1 ELSE 0 END) INTO v_kycstatus;
  END IF;
  IF (v_entitytype = 2) THEN
  SELECT (CASE WHEN v_kycstatus = 3 THEN 1 ELSE 0 END) INTO v_kycstatus;
  END IF;
  IF (v_entitytype = 3 AND v_bankdetailscount = 1) THEN
  SELECT (CASE WHEN v_kycstatus = 6 THEN 1 ELSE 0 END) INTO v_kycstatus;
  END IF;
  IF (v_entitytype = 4) THEN
  SELECT (CASE WHEN v_kycstatus = 4 THEN 1 ELSE 0 END) INTO v_kycstatus;
  END IF;
  IF (v_entitytype = 5) THEN
  SELECT (CASE WHEN v_kycstatus = 3 THEN 1 ELSE 0 END) INTO v_kycstatus;
  END IF;
  RAISE NOTICE '%', v_entitytype;
  SELECT (CASE WHEN v_isfirsttimeorafterrejection > 0 THEN 1 ELSE 0 END) INTO v_isfirsttimeorafterrejection;
  SELECT COALESCE(trp.packagename, '') INTO v_utilitypackage FROM tbl_reseller_purchased_packages AS trpp LEFT JOIN tbl_reseller_packages AS trp ON trpp.trpid = trp.trpid WHERE trpp.did = v_regno AND trpp.trsid = 1;
  SELECT COALESCE(trp.packagename, '') INTO v_productpackage FROM tbl_reseller_purchased_packages AS trpp LEFT JOIN tbl_reseller_packages AS trp ON trpp.trpid = trp.trpid WHERE trpp.did = v_regno AND trpp.trsid = 2;
  SELECT COALESCE(trp.packagename, '') INTO v_travelpackage FROM tbl_reseller_purchased_packages AS trpp LEFT JOIN tbl_reseller_packages AS trp ON trpp.trpid = trp.trpid WHERE trpp.did = v_regno AND trpp.trsid = 3;
  SELECT COALESCE(trp.packagename, '') INTO v_dealspackage FROM tbl_reseller_purchased_packages AS trpp LEFT JOIN tbl_reseller_packages AS trp ON trpp.trpid = trp.trpid WHERE trpp.did = v_regno AND trpp.trsid = 4;
  IF (v_pancarddetails2 = 1 AND v_companydeed = 1 AND v_partnershipdeed = 1 AND v_addressproof = 1 AND v_incorporationcertificate = 1 AND v_memorandumofassociationproof = 1) THEN
  DELETE FROM tmp_portallogin2 WHERE rownumber = v_count;
  ELSE
  UPDATE tmp_portallogin2 SET iscompanydeed = v_companydeed, ispartnershipdeed = v_partnershipdeed, ispancarddetails = v_pancarddetails2, isaddressproof = v_addressproof, isincorporationcertificate = v_incorporationcertificate, ismemorandumofassociationproof = v_memorandumofassociationproof, kycdate = v_kycdate, isfirsttimeorafterrejection = v_isfirsttimeorafterrejection, lastupdateddatebyuser = v_lastupdateddatebyuser, profilestatus = v_profilestatus, kycstatus = v_kycstatus, companydeed = v_companydeedimg, partnershipdeed = v_partnershipdeedimg, pancarddetails = v_pancarddetailsimg2, addressproof = v_addressproofimg, incorporationcertificate = v_incorporationcertificateimg, memorandumofassociationproof = v_memorandumofassociationproofimg, entitype = v_entitytype, packagename = v_utilitypackage, productpackge = v_productpackage, travelpackage = v_travelpackage, dealspackage = v_dealspackage WHERE rownumber = v_count;
  END IF;
  v_count := v_count - 1;
  END LOOP;
  DROP TABLE IF EXISTS tmp_templogin2;
  CREATE TEMP TABLE tmp_templogin2 (ROWNUMBER INT GENERATED BY DEFAULT AS IDENTITY,
REGNO INT,
NAME VARCHAR(500),
MOBILE VARCHAR(500),
EMAILID VARCHAR(500),
IsFirstTimeOrAfterRejection VARCHAR(500),
LASTUPDATEDDATEBYUSER VARCHAR(500),
PROFILESTATUS VARCHAR(500),
KYCSTATUS VARCHAR(500),
ISCOMPANYDEED VARCHAR(500),
ISPANCARDDETAILS VARCHAR(500),
ISADDRESSPROOF VARCHAR(500),
ISINCORPORATIONCERTIFICATE VARCHAR(500),
ISMEMORANDUMOFASSOCIATIONPROOF VARCHAR(500),
ISPARTNERSHIPDEED VARCHAR(500),
COMPANYDEED VARCHAR(100),
PARTNERSHIPDEED VARCHAR(100),
PANCARDDETAILS VARCHAR(100),
ADDRESSPROOF VARCHAR(100),
INCORPORATIONCERTIFICATE VARCHAR(100),
MEMORANDUMOFASSOCIATIONPROOF VARCHAR(100),
Businessname varchar(100),
Entitype varchar(100),
PACKAGENAME VARCHAR(100),
ProductPackge Varchar(100),
TravelPackage Varchar(100),
DealsPackage Varchar(100)) ON COMMIT DROP;
  v_query := '';
  v_query := 'INSERT INTO #TEMPLOGIN2 SELECT REGNO,NAME,MOBILE,EMAILID,
(CASE WHEN IsFirstTimeOrAfterRejection=0 Then ''New KYC'' ELSE ''Rejected KYC'' END)As IsFirstTimeOrAfterRejection,convert(varchar,LASTUPDATEDDATEBYUSER,106),

(CASE WHEN PROFILESTATUS=0 THEN ''Pending'' WHEN PROFILESTATUS=2 THEN ''<i class="fa fa-times" aria-hidden="true"></i>'' 
ELSE ''<i class="fa fa-check" aria-hidden="true"></i>'' END) AS PROFILESTATUS,

(CASE WHEN #PORTALLOGIN2.KYCSTATUS=0 THEN ''Pending'' ELSE ''Approved'' END) AS KYCSTATUS,

(CASE WHEN ISCOMPANYDEED=3 THEN ''N/A'' WHEN ISCOMPANYDEED=0 THEN ''Pending'' WHEN ISCOMPANYDEED=2 THEN ''<i class="fa fa-times" aria-hidden="true"></i>'' 
ELSE ''<i class="fa fa-check" aria-hidden="true"></i><i class="fa fa-list-alt" aria-hidden="true"></i>'' END) AS ISCOMPANYDEED,

(CASE WHEN ISPANCARDDETAILS=3 THEN ''N/A'' WHEN ISPANCARDDETAILS=0 THEN ''Pending'' WHEN  ISPANCARDDETAILS=2  THEN ''<i class="fa fa-times" aria-hidden="true"></i>''
 ELSE ''<i class="fa fa-check" aria-hidden="true"></i><i class="fa fa-list-alt" aria-hidden="true"></i>'' END)AS ISPANCARDDETAILS,

(CASE WHEN ISADDRESSPROOF=3 THEN ''N/A'' WHEN ISADDRESSPROOF=0 THEN ''Pending'' WHEN  ISADDRESSPROOF=2 THEN ''<i class="fa fa-times" aria-hidden="true"></i>'' 
ELSE ''<i class="fa fa-check" aria-hidden="true"></i><i class="fa fa-list-alt" aria-hidden="true"></i>'' END) AS ISADDRESSPROOF,

(CASE WHEN ISINCORPORATIONCERTIFICATE=3 THEN ''N/A'' WHEN ISINCORPORATIONCERTIFICATE=0 THEN ''Pending'' 
 WHEN ISINCORPORATIONCERTIFICATE=2 THEN ''<i class="fa fa-times" aria-hidden="true"></i>''
 ELSE ''<i class="fa fa-check" aria-hidden="true"></i><i class="fa fa-list-alt" aria-hidden="true"></i>'' END) AS ISINCORPORATIONCERTIFICATE,

(CASE WHEN ISMEMORANDUMOFASSOCIATIONPROOF=3 THEN ''N/A'' WHEN ISMEMORANDUMOFASSOCIATIONPROOF=0 THEN ''Pending''
 WHEN  ISMEMORANDUMOFASSOCIATIONPROOF=2
THEN ''<i class="fa fa-times" aria-hidden="true"></i>'' ELSE ''<i class="fa fa-check" aria-hidden="true">
</i><i class="fa fa-list-alt" aria-hidden="true"></i>'' END) AS ISMEMORANDUMOFASSOCIATIONPROOF,

(CASE WHEN ISPARTNERSHIPDEED=3 THEN ''N/A'' WHEN ISPARTNERSHIPDEED=0 THEN ''Pending''
 WHEN  ISPARTNERSHIPDEED=2  THEN ''<i class="fa fa-times" aria-hidden="true"></i>'' ELSE ''<i class="fa fa-check" aria-hidden="true"></i>
<i class="fa fa-list-alt" aria-hidden="true"></i>'' END) AS 
ISPARTNERSHIPDEED,COMPANYDEED ,PARTNERSHIPDEED ,PANCARDDETAILS ,ADDRESSPROOF ,INCORPORATIONCERTIFICATE,MEMORANDUMOFASSOCIATIONPROOF,PM.COMPANYNAME,
(case When isnull(Entitype,0)=1 Then ''Sole Proprietor'' When isnull(Entitype,0)=3 Then ''Company'' End),PACKAGENAME,ProductPackge,TravelPackage,DealsPackage
FROM #PORTALLOGIN2 LEFT JOIN Distributor_MASTER PM ON PM.PLID= #PORTALLOGIN2.REGNO WHERE REGNO<>0  ';
  IF (v_lastupdateddatebyuserfromdate <> '' AND v_lastupdateddatebyusertodate <> '') THEN
  v_query := v_query || '  AND CONVERT(varchar(50), LASTUPDATEDDATEBYUSER,105)  >= CONVERT(varchar(50),''' || v_lastupdateddatebyuserfromdate || ''',105)  
 AND CONVERT(varchar(50), LASTUPDATEDDATEBYUSER,105) <= CONVERT(varchar(50),''' || v_lastupdateddatebyusertodate || ''',105)';
  ELSE
  IF (v_lastupdateddatebyuserfromdate <> '') THEN
  v_query := v_query || '  AND CONVERT(varchar(50), LASTUPDATEDDATEBYUSER,105) = CONVERT(varchar(50),''' || v_lastupdateddatebyuserfromdate || ''',105)';
  ELSE
  IF (v_lastupdateddatebyusertodate <> '') THEN
  v_query := v_query || ' AND CONVERT(varchar(50), LASTUPDATEDDATEBYUSER,105) = CONVERT(varchar(50),''' || v_lastupdateddatebyusertodate || ''',105)';
  END IF;
  END IF;
  END IF;
  IF (v_submittedfromdate <> '' AND v_submittedtodate <> '') THEN
  v_query := v_query || '  AND CONVERT(DATE, LASTUPDATEDDATEBYUSER)  >= CONVERT(DATE,''' || v_submittedfromdate || ''')  
 AND CONVERT(DATE,LASTUPDATEDDATEBYUSER) <= CONVERT(DATE,''' || v_submittedtodate || ''')';
  ELSE
  IF (v_submittedfromdate <> '') THEN
  v_query := v_query || '  AND CONVERT(DATE, LASTUPDATEDDATEBYUSER) = CONVERT(DATE,''' || v_submittedfromdate || ''')';
  ELSE
  IF (v_submittedtodate <> '') THEN
  v_query := v_query || '  AND CONVERT(DATE, LASTUPDATEDDATEBYUSER) = CONVERT(DATE,''' || v_submittedtodate || ''')';
  END IF;
  END IF;
  END IF;
  IF (v_fromdate <> '' AND v_todate <> '') THEN
  v_query := v_query || '  AND CONVERT(varchar(50), KYCDATE,105) >= CONVERT(varchar(50),''' || v_fromdate || ''',105)  
 AND CONVERT(varchar(50), KYCDATE,105) <= CONVERT(varchar(50),''' || v_todate || ''',105)';
  ELSE
  IF (v_fromdate <> '') THEN
  v_query := v_query || '  AND CONVERT(varchar(50), KYCDATE,105) = CONVERT(varchar(50),''' || v_fromdate || ''',105)';
  ELSE
  IF (v_todate <> '') THEN
  v_query := v_query || '  AND CONVERT(varchar(50), KYCDATE,105) = CONVERT(varchar(50),''' || v_todate || ''',105)';
  END IF;
  END IF;
  END IF;
  IF (v_isfirsttimeorafterrejectionparam <> 0) THEN
  v_query := v_query || '  AND IsFirstTimeOrAfterRejection=' || CAST(v_isfirsttimeorafterrejectionparam AS VARCHAR(100)) || '';
  END IF;
  IF (v_businesskycstatus <> '-1') THEN
  v_query := v_query || '  AND PM.ISVERIFIED=' || CAST(v_businesskycstatus AS VARCHAR(100)) || '';
  END IF;
  IF (v_kycstatusparam <> '2') THEN
  v_query := v_query || '  AND #PORTALLOGIN2.KYCSTATUS=' || CAST(v_kycstatusparam AS VARCHAR(100)) || '';
  END IF;
  IF (v_orderby = 'ASC') THEN
  v_query := v_query || (' ORDER BY LASTUPDATEDDATEBYUSER ASC');
  ELSE
  v_query := v_query || (' ORDER BY LASTUPDATEDDATEBYUSER DESC');
  END IF;
  EXECUTE v_query;
  RAISE NOTICE '%', v_query;
  RETURN QUERY SELECT rownumber, regno, name, mobile, emailid, isfirsttimeorafterrejection, CAST(TO_CHAR(lastupdateddatebyuser, 'DD TMMon YYYY HH24:MI:SS:US') AS VARCHAR(20)) AS lastupdateddatebyuser, profilestatus, kycstatus, iscompanydeed, ispancarddetails, ispartnershipdeed, isaddressproof, ismemorandumofassociationproof, isincorporationcertificate, companydeed, partnershipdeed, pancarddetails, incorporationcertificate, memorandumofassociationproof, addressproof, businessname, COALESCE(entitype, '') AS entitype, packagename, productpackge, travelpackage, dealspackage FROM tmp_templogin2 WHERE rownumber BETWEEN v_startrowindex AND v_maxrows;
  SELECT COUNT(1) INTO v_recordcount FROM tmp_templogin2;
  DROP TABLE IF EXISTS tmp_portallogin2;
  DROP TABLE IF EXISTS tmp_templogin2;
  END IF;
  END IF;
  END IF;
END;
$$;


--
-- Name: usp_performancelist(integer, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_performancelist(v_pageno integer DEFAULT 1, v_pagesize integer DEFAULT 30) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_minindex int;
  v_maxindex int;
  v_recordcount int;
  v_amount numeric(19,4);
  v_currencysymbol varchar(20);
  v_totalamount numeric(19,4);
  v_sqlquery text;
BEGIN
  -- SET option (removed)
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp (rowNumber bigint,
logintime text,
totallisting text,
totalVerified  text) ON COMMIT DROP;
  v_minindex := 0;
  v_maxindex := 0;
  v_sqlquery := '';
  v_minindex := ((v_pageno - 1) * v_pagesize) + 1;
  v_maxindex := (v_pageno * v_pagesize);
  v_sqlquery := 'insert into #temp  select ROW_NUMBER() over(order by logintime  desc) as rownumber,logintime ,totallisting,totalVerified from tbl_operator_report';
  EXECUTE v_sqlquery;
  SELECT COUNT(*) INTO v_recordcount FROM tmp_temp;
  RETURN QUERY SELECT *, v_recordcount AS recordcount FROM tmp_temp WHERE rownumber BETWEEN v_minindex AND v_maxindex;
  DROP TABLE IF EXISTS tmp_temp;
  -- SET option (removed)
END;
$$;


--
-- Name: usp_pickadminuserrights(integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_pickadminuserrights(v_empid integer) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_active boolean;
  v_count1 INT;
  v_count2 INT;
  v_mid INT;
  v_sid INT;
  v_isedit INT;
  v_submenuchecked INT;
  v_submenuedit INT;
  v_emproles VARCHAR(300);
  v_rolename VARCHAR(25);
  v_roleno INT;
  v_totalrolecount INT;
  v_rid INT;
  v_totalmenurole INT;
  v_menurole INT;
  v_menuroleno INT;
  v_isdelete smallint;
  v_isedit_t smallint;
  v_isdelete_t smallint;
  v_roles text;
BEGIN
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp (ROWNUMBER INT GENERATED BY DEFAULT AS IDENTITY,
		RID INT,
		MID INT,
		SID INT,
		ISEDIT smallint,
		ISDELETE smallint) ON COMMIT DROP;
  v_count2 := 1;
  v_isedit := 0;
  v_submenuchecked := 0;
  v_submenuedit := 0;
  SELECT totalroles INTO v_roles FROM tbl_employee_master WHERE emp_id = v_empid;
  DROP TABLE IF EXISTS tmp_tbl_roles;
  CREATE TEMP TABLE tmp_tbl_roles ON COMMIT DROP AS SELECT DISTINCT ROW_NUMBER() OVER (ORDER BY value NULLS FIRST) AS roleno, value FROM dbo.SPLITSTRINGBYCUSTOMSYMBOL1(v_roles, '^');
  SELECT COUNT(value) INTO v_totalrolecount FROM tmp_tbl_roles;
  v_roleno := 1;
  WHILE (v_roleno <= v_totalrolecount) LOOP
  SELECT value INTO v_rolename FROM tmp_tbl_roles WHERE roleno = v_roleno;
  v_rid := 0;
  v_totalmenurole := 0;
  SELECT rid INTO v_rid FROM tbl_rolemaster WHERE rolename = v_rolename AND status = 1;
  DROP TABLE IF EXISTS tmp_temp_submenurole;
  CREATE TEMP TABLE tmp_temp_submenurole ON COMMIT DROP AS SELECT ROW_NUMBER() OVER (ORDER BY id NULLS FIRST) AS rolenos, id, mid, sid, isedit, isdelete FROM tbl_submenurole WHERE rid = v_rid AND active = 1 AND status = 1;
  SELECT COUNT(id) INTO v_totalmenurole FROM tmp_temp_submenurole;
  v_menuroleno := 1;
  WHILE (v_menuroleno <= v_totalmenurole) LOOP
  v_menurole := 0;
  SELECT id, mid, sid, isedit, isdelete INTO v_menurole, v_mid, v_sid, v_isedit, v_isdelete FROM tmp_temp_submenurole WHERE rolenos = v_menuroleno;
  IF (v_menurole > 0) THEN
  IF NOT EXISTS(SELECT rid FROM tmp_temp WHERE mid = v_mid AND sid = v_sid) THEN
  INSERT INTO tmp_temp (rid, mid, sid, isedit, isdelete) VALUES (v_rid, v_mid, v_sid, v_isedit, v_isdelete);
  ELSE
  SELECT isedit, isdelete INTO v_isedit_t, v_isdelete_t FROM tmp_temp WHERE mid = v_mid AND sid = v_sid;
  IF (v_isedit_t = 0) THEN
  IF (v_isedit > 0) THEN
  UPDATE tmp_temp SET isedit = v_isedit WHERE mid = v_mid AND sid = v_sid;
  END IF;
  END IF;
  IF (v_isdelete_t = 0) THEN
  IF (v_isdelete_t > 0) THEN
  UPDATE tmp_temp SET isdelete = v_isdelete WHERE mid = v_mid AND sid = v_sid;
  END IF;
  END IF;
  END IF;
  END IF;
  v_menuroleno := v_menuroleno + 1;
  END LOOP;
  v_roleno := v_roleno + 1;
  DROP TABLE IF EXISTS tmp_temp_submenurole;
  END LOOP;
  RETURN QUERY SELECT t.rownumber, t.mid, mm.title AS mainmenutitle, mm.herf AS mainhref, mm.aiclass, mm.bclass, mm.displayorder, COALESCE(t.sid, 0) AS sid, COALESCE(sm.title, '') AS submenutitle, COALESCE(sm.herf, '') AS subhref, sm.displayorder AS siddisplayorder, COALESCE(t.isedit, 0) AS isedit, COALESCE(t.isdelete, 0) AS isdelete, 1 AS active, t.rid FROM tmp_temp AS t LEFT JOIN tbl_mainmenu AS mm ON mm.mid = t.mid LEFT JOIN tbl_submenu AS sm ON sm.sid = t.sid WHERE mm.status = 1 AND sm.status = 1 ORDER BY displayorder ASC NULLS FIRST, mid ASC NULLS FIRST, siddisplayorder ASC NULLS FIRST;
  DROP TABLE IF EXISTS tmp_tbl_roles;
  DROP TABLE IF EXISTS tmp_temp;
END;
$$;


--
-- Name: usp_pinverification(character varying, character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_pinverification(v_pincode character varying DEFAULT ''::character varying, INOUT v_strresult character varying DEFAULT ''::character varying) RETURNS character varying
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_state varchar(200);
BEGIN
  v_state := '';
  SELECT st.statename INTO v_state FROM area_master AS am INNER JOIN state AS st ON st.sid = am.sid WHERE am.pincode = v_pincode;
  v_strresult := v_state;
  -- SET option (removed)
END;
$$;


--
-- Name: usp_popupnews(integer, text, character varying, text, integer, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_popupnews(v_newsid integer DEFAULT 0, v_news text DEFAULT 'a'::text, v_mode character varying DEFAULT 'a'::character varying, v_title text DEFAULT 's'::text, INOUT v_intresult integer DEFAULT 0, v_active integer DEFAULT 1) RETURNS integer
    LANGUAGE plpgsql
    AS $$
BEGIN
  -- BEGIN TRAN (removed)
  IF (v_mode = 'Update') THEN
  UPDATE eventnews SET activeflag = v_active, news = v_news, title = v_title WHERE newsid = v_newsid;
  v_intresult := 2;
  ELSE
  INSERT INTO eventnews (news, newsdate, activeflag, type, title) VALUES (v_news, dbo.fun_getCurrentDate(), v_active, 3, v_title);
  v_intresult := 1;
  END IF;
  IF (0 <> 0) THEN
  -- ROLLBACK (removed)
  v_intresult := 0;
  RETURN;
  END IF;
  -- COMMIT (removed)
END;
$$;


--
-- Name: usp_portal_deal_in_city(character varying, integer, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_portal_deal_in_city(v_cityname character varying DEFAULT 'New Delhi'::character varying, v_cid integer DEFAULT 0, v_dealid integer DEFAULT 0) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_countrecord INT;
  v_city BIGINT;
BEGIN
  -- SET option (removed)
  IF (v_cityname = '-' OR v_cityname = '') THEN
  v_cityname := 'New Delhi';
  END IF;
  v_cityname := 'New Delhi';
  SELECT COALESCE(ctid, 0), cid INTO v_city, v_cid FROM city WHERE cityname = v_cityname;
  DROP TABLE IF EXISTS tmp_tempdeal;
  CREATE TEMP TABLE tmp_tempdeal (DEALID Int,
PMID BIGINT,
TITLE  VARCHAR(250),
IMAGES  VARCHAR(250),
DESCRIPTION  text,
URL  VARCHAR(250),
REWARD  VARCHAR(450),
STARTPRICE INT,
MINAMOUNT  INT,
IMAGEURL  VARCHAR(450)) ON COMMIT DROP;
  INSERT INTO tmp_tempdeal SELECT dealid, dm.pmid, dm.title, dm.images, dm.description, REPLACE(REPLACE(dbo.GENRATINGDEALLISTINGSURL(dm.dealid), '/', '/'), '''', '+opos') AS url, CASE COALESCE(dm.startprice, 0) WHEN 0 THEN dm.offer ELSE dm.offer || ' Starting from ' || CAST(dm.startprice AS VARCHAR(20)) END AS reward, dm.startprice, (CASE WHEN dm.startprice > 0 THEN dm.startprice ELSE 0 END) AS minamount, COALESCE(CASE WHEN dm.images LIKE '%,%' THEN (LEFT(CAST('/DealsThumble_Images/' || dm.images AS TEXT), POSITION(',' IN '/DealsThumble_Images/' || dm.images) - 1)) ELSE '/DealsThumble_Images/' || dm.images END, '') AS imageurl FROM portal_master AS p INNER JOIN portal_deal_master AS dm ON dm.pmid = p.pmid, city AS ct INNER JOIN country AS coun ON ct.cid = coun.cid INNER JOIN state AS st ON st.sid = ct.sid WHERE p.active = 1 AND p.ctid = ct.ctid AND NOT dm.dealid IN (v_dealid) AND dm.active = 1 AND dm.verify = 1 AND CAST(CURRENT_TIMESTAMP AS DATE) BETWEEN fromtime AND totime AND images <> '' AND p.ctid = v_city AND p.accounttype = 1 AND COALESCE(startprice, 0) > 0 ORDER BY GEN_RANDOM_UUID() NULLS FIRST LIMIT 10;
  INSERT INTO tmp_tempdeal SELECT dealid, dm.pmid, dm.title, dm.images, dm.description, REPLACE(REPLACE(dbo.GENRATINGDEALLISTINGSURL(dm.dealid), '/', '/'), '''', '+OPOS') AS url, CASE COALESCE(dm.startprice, 0) WHEN 0 THEN dm.offer ELSE dm.offer || ' Starting from ' || CAST(dm.startprice AS VARCHAR(20)) END AS reward, dm.startprice, (CASE WHEN dm.startprice > 0 THEN dm.startprice ELSE 0 END) AS minamount, COALESCE(CASE WHEN dm.images LIKE '%,%' THEN (LEFT(CAST('/DealsThumble_Images/' || dm.images AS TEXT), POSITION(',' IN '/DealsThumble_Images' || dm.images) - 1)) ELSE '/DealsThumble_Images/' || dm.images END, '') AS imageurl FROM portal_master AS p INNER JOIN portal_deal_master AS dm ON dm.pmid = p.pmid, city AS ct INNER JOIN country AS coun ON ct.cid = coun.cid INNER JOIN state AS st ON st.sid = ct.sid WHERE p.active = 1 AND p.ctid = ct.ctid AND NOT dm.dealid IN (v_dealid) AND dm.active = 1 AND dm.verify = 1 AND CAST(CURRENT_TIMESTAMP AS DATE) BETWEEN fromtime AND totime AND images <> '' AND p.ctid = v_city AND p.accounttype = 0 AND COALESCE(startprice, 0) > 0 ORDER BY GEN_RANDOM_UUID() NULLS FIRST LIMIT 10;
  SELECT COUNT(pmid) INTO v_countrecord FROM tmp_tempdeal;
  IF (v_countrecord <= 0) THEN
  INSERT INTO tmp_tempdeal SELECT dealid, dm.pmid, dm.title, dm.images, dm.description, REPLACE(REPLACE(dbo.GENRATINGDEALLISTINGSURL(dm.dealid), '/', '/'), '''', '+opos') AS url, CASE COALESCE(dm.startprice, 0) WHEN 0 THEN dm.offer ELSE dm.offer || ' Starting from ' || CAST(dm.startprice AS VARCHAR(20)) END AS reward, dm.startprice, (CASE WHEN dm.startprice > 0 THEN dm.startprice ELSE 0 END) AS minamount, COALESCE(CASE WHEN dm.images LIKE '%,%' THEN (LEFT(CAST('/DealsThumble_Images/' || dm.images AS TEXT), POSITION(',' IN '/DealsThumble_Images/' || dm.images) - 1)) ELSE '/DealsThumble_Images/' || dm.images END, '') AS imageurl FROM portal_master AS p INNER JOIN portal_deal_master AS dm ON dm.pmid = p.pmid, city AS ct INNER JOIN country AS coun ON ct.cid = coun.cid INNER JOIN state AS st ON st.sid = ct.sid WHERE p.active = 1 AND p.ctid = ct.ctid AND NOT dm.dealid IN (v_dealid) AND dm.active = 1 AND dm.verify = 1 AND CAST(CURRENT_TIMESTAMP AS DATE) BETWEEN fromtime AND totime AND images <> '' AND p.ctid = v_city AND p.accounttype = 1 AND COALESCE(startprice, 0) > 0 ORDER BY GEN_RANDOM_UUID() NULLS FIRST LIMIT 10;
  INSERT INTO tmp_tempdeal SELECT dealid, dm.pmid, dm.title, dm.images, dm.description, REPLACE(REPLACE(dbo.GENRATINGDEALLISTINGSURL(dm.dealid), '/', '/'), '''', '+opos') AS url, CASE COALESCE(dm.startprice, 0) WHEN 0 THEN dm.offer ELSE dm.offer || ' Starting from ' || CAST(dm.startprice AS VARCHAR(20)) END AS reward, dm.startprice, (CASE WHEN dm.startprice > 0 THEN dm.startprice ELSE 0 END) AS minamount, COALESCE(CASE WHEN dm.images LIKE '%,%' THEN (LEFT(CAST('/DealsThumble_Images/' || dm.images AS TEXT), POSITION(',' IN '/DealsThumble_Images/' || dm.images) - 1)) ELSE '/DealsThumble_Images/' || dm.images END, '') AS imageurl FROM portal_master AS p INNER JOIN portal_deal_master AS dm ON dm.pmid = p.pmid, city AS ct INNER JOIN country AS coun ON ct.cid = coun.cid INNER JOIN state AS st ON st.sid = ct.sid WHERE p.active = 1 AND p.ctid = ct.ctid AND NOT dm.dealid IN (v_dealid) AND dm.active = 1 AND dm.verify = 1 AND CAST(CURRENT_TIMESTAMP AS DATE) BETWEEN fromtime AND totime AND images <> '' AND p.ctid = v_city AND p.accounttype = 0 AND COALESCE(startprice, 0) > 0 ORDER BY GEN_RANDOM_UUID() NULLS FIRST LIMIT 10;
  END IF;
  RETURN QUERY SELECT * FROM tmp_tempdeal;
  DROP TABLE IF EXISTS tmp_tempdeal;
