  INSERT INTO v_tblaid (dealid, position, ifpintype) SELECT pdm.dealid, 4, tmp.ifpintype FROM portal_master AS pm INNER JOIN portal_deal_master AS pdm ON pm.pmid = pdm.pmid INNER JOIN tmp_tempareaid AS tmp ON (',' || pm.aid || ',') LIKE '%,' || CAST(tmp.areaidtemp AS VARCHAR(100)) || ',%' WHERE pm.cid = v_cid AND (',' || pm.autocatid || ',') LIKE '%,' || v_catid || ',%' AND pm.active = 1 AND COALESCE(pm.isverified, 0) = 1 AND pdm.active = 1 AND COALESCE(pdm.verify, 0) = 1 AND NOT pdm.dealid IN (SELECT dealid FROM v_tblaid) AND (dbo.fun_getCurrentDate() BETWEEN pdm.fromtime AND pdm.totime);
  INSERT INTO tmp_tempdealid (dealid, srno, position, ifpintype) SELECT dealid, ROW_NUMBER() OVER (ORDER BY dbo.myrandom_gen_replace1(dealid, v_randnumber) NULLS FIRST) AS srno, position, ifpintype FROM v_tblaid ORDER BY ifpintype ASC NULLS FIRST, position ASC NULLS FIRST;
