  INSERT INTO tmp_tempdealid (srno, dealid) SELECT ROW_NUMBER() OVER (ORDER BY dbo.myrandom_gen_replace1(pdm.dealid, v_randnumber) NULLS FIRST) AS srno, pdm.dealid FROM portal_master AS pm INNER JOIN portal_deal_master AS pdm ON pm.pmid = pdm.pmid WHERE pm.cid = v_cid AND (',' || pm.subautocatid || ',') LIKE '%,' || v_catid || ',%' AND pm.active = 1 AND COALESCE(pm.isverified, 0) = 1 AND pdm.active = 1 AND COALESCE(pdm.verify, 0) = 1 AND pm.expirydate >= dbo.fun_getCurrentDate() AND (dbo.fun_getCurrentDate() BETWEEN pdm.fromtime AND pdm.totime) AND NOT pdm.dealid IN (SELECT dealid FROM tmp_tempdealid);
