  INSERT INTO tmp_tempdealid (dealid, srno, position, ifpintype) SELECT dealid, ROW_NUMBER() OVER (ORDER BY dbo.myrandom_gen_replace1(dealid, v_randnumber) NULLS FIRST) AS srno, position, ifpintype FROM v_tblaid ORDER BY ifpintype ASC NULLS FIRST, position ASC NULLS FIRST;
  END IF;
  IF (v_city = 0 AND v_aid = '') THEN
