  END IF;
  END IF;
  END IF;
  SELECT COUNT(*) INTO v_noofrec FROM tmp_tempdealid;
  IF (v_sortby = '') THEN
  RETURN QUERY SELECT p.dealid, p.title, p.images, p.description, COALESCE(p.discount, 0) AS discount, CASE COALESCE(p.startprice, 0) WHEN 0 THEN p.offer ELSE p.offer || ' Starting from ' || CAST(p.startprice AS VARCHAR(20)) END AS offer, CASE COALESCE(am.areaname, '') WHEN '' THEN ct.cityname ELSE am.areaname || ', ' || ct.cityname END AS location, dbo.genratingdeallistingsurl(p.dealid) AS url, v_noofrec AS noofrec FROM portal_deal_master AS p INNER JOIN tmp_tempdealid AS tp ON p.dealid = tp.dealid LEFT JOIN portal_master AS pm ON pm.pmid = p.pmid LEFT JOIN city AS ct ON ct.ctid = pm.ctid LEFT JOIN area_master AS am ON am.pincode = pm.pincode AND am.areaname = pm.areaname WHERE tp.rownumber BETWEEN v_minindex AND v_maxindex ORDER BY rownumber ASC NULLS FIRST;
