--
-- Name: usp_portallogin(character varying, character varying, character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_portallogin(v_username character varying DEFAULT ''::character varying, v_password character varying DEFAULT ''::character varying, v_ipaddress character varying DEFAULT ''::character varying) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_plid BIGINT;
BEGIN
  -- BEGIN TRAN (removed)
  v_plid := 0;
  SELECT plid INTO v_plid FROM portal_login WHERE loginid = v_username AND password = v_password;
  IF (v_plid = 0) THEN
  SELECT plid INTO v_plid FROM portal_login WHERE username = v_username AND password = v_password;
  END IF;
  UPDATE portal_login SET lastlogin = dbo.FUN_GETCURRENTDATE() WHERE loginid = v_username AND password = v_password;
  UPDATE tbl_loginhistory SET status = 0 WHERE plid = v_plid;
  INSERT INTO tbl_loginhistory (plid, date, ipaddress, status) VALUES (v_plid, dbo.FUN_GETCURRENTDATE(), v_ipaddress, 1);
  IF EXISTS(SELECT 1 FROM portal_login WHERE loginid = v_username AND password = v_password) THEN
  RETURN QUERY SELECT CAST(pl.plid AS BIGINT) AS plid, CAST(COALESCE(pl.pmid, 0) AS BIGINT) AS pmid, CAST(COALESCE(smd.smdid, 0) AS BIGINT) AS smdid, pl.loginid, (COALESCE(pl.fname, '') || ' ' || COALESCE(pl.lname, '')) AS name, COALESCE(pl.username, pl.loginid) AS username, CAST(pl.cid AS BIGINT) AS cid FROM portal_login AS pl LEFT JOIN sponsor_master_detail AS smd ON pl.plid = smd.plid WHERE pl.loginid = v_username AND pl.password = v_password AND pl.active = 1;
  ELSE
  IF EXISTS(SELECT 1 FROM portal_login WHERE username = v_username AND password = v_password) THEN
  RETURN QUERY SELECT CAST(pl.plid AS BIGINT) AS plid, CAST(COALESCE(pl.pmid, 0) AS BIGINT) AS pmid, CAST(COALESCE(smd.smdid, 0) AS BIGINT) AS smdid, pl.loginid, (COALESCE(pl.fname, '') || ' ' || COALESCE(pl.lname, '')) AS name, COALESCE(pl.username, pl.loginid) AS username, CAST(pl.cid AS BIGINT) AS cid FROM portal_login AS pl LEFT JOIN sponsor_master_detail AS smd ON pl.plid = smd.plid WHERE pl.username = v_username AND pl.password = v_password AND pl.active = 1;
  END IF;
  END IF;
  -- COMMIT (removed)
END;
$$;


