  RETURN QUERY SELECT CAST(pl.did AS BIGINT) AS did, CAST(COALESCE(pl.pmid, 0) AS BIGINT) AS pmid, CAST(COALESCE(smd.smdid, 0) AS BIGINT) AS smdid, pl.loginid, (COALESCE(pl.fname, '') || ' ' || COALESCE(pl.lname, '')) AS name, COALESCE(pl.username, pl.loginid) AS username, CAST(pl.cid AS BIGINT) AS cid FROM tbl_distributor AS pl LEFT JOIN sponsor_master_detail AS smd ON pl.did = smd.plid WHERE pl.username = v_username AND pl.password = v_password AND pl.active = 1;
  ELSE
  IF EXISTS(SELECT 1 FROM tbl_distributor WHERE emailid = v_username AND password = v_password) THEN
  RETURN QUERY SELECT CAST(pl.did AS BIGINT) AS did, CAST(COALESCE(pl.pmid, 0) AS BIGINT) AS pmid, CAST(COALESCE(smd.smdid, 0) AS BIGINT) AS smdid, pl.loginid, (COALESCE(pl.fname, '') || ' ' || COALESCE(pl.lname, '')) AS name, COALESCE(pl.username, pl.loginid) AS username, CAST(pl.cid AS BIGINT) AS cid FROM tbl_distributor AS pl LEFT JOIN sponsor_master_detail AS smd ON pl.did = smd.plid WHERE pl.emailid = v_username AND pl.password = v_password AND pl.active = 1;
