  INSERT INTO tmp_temppmid (pmid, srno, position, ifpintype) SELECT pmid, ROW_NUMBER() OVER (ORDER BY dbo.myrandom_gen_replace1(v_randnumber, pmid) NULLS FIRST) AS srno, position, ifpintype FROM v_tblaid ORDER BY ifpintype ASC NULLS FIRST, position ASC NULLS FIRST;
