  INSERT INTO tmp_temppmid (srno, pmid) SELECT ROW_NUMBER() OVER (ORDER BY dbo.myrandom_gen_replace1(v_randnumber, pmid) NULLS FIRST) AS srno, pmid FROM portal_master WHERE cid = v_cid AND title LIKE '%' || v_searchtext || '%' AND (',' || subctid || ',') LIKE '%,' || v_city || ',%' AND active = 1 AND COALESCE(isverified, 0) = 1 AND expirydate >= dbo.fun_getCurrentDate();
