  INSERT INTO v_tblaid (pmid, position, ifpintype) SELECT pm.pmid, 1, tmp.ifpintype FROM portal_master AS pm INNER JOIN tmp_tempareaid AS tmp ON (',' || pm.subaid || ',') LIKE '%,' || CAST(tmp.areaidtemp AS VARCHAR(100)) || ',%' WHERE cid = v_cid AND title LIKE '%' || v_searchtext || '%' AND active = 1 AND COALESCE(isverified, 0) = 1 AND expirydate >= dbo.fun_getCurrentDate();
