  INSERT INTO tmp_temppmid (pmid, srno, position, ifpintype) SELECT pmid, ROW_NUMBER() OVER (ORDER BY dbo.myrandom_gen_replace1(v_randnumber, pmid) NULLS FIRST) AS srno, position, ifpintype FROM v_tblaid ORDER BY ifpintype ASC NULLS FIRST, position ASC NULLS FIRST;
  END IF;
  IF (v_city = 0 AND v_aid = '') THEN
  IF (v_cid <> 0) THEN
  INSERT INTO tmp_temppmid (srno, pmid) SELECT ROW_NUMBER() OVER (ORDER BY dbo.myrandom_gen_replace1(v_randnumber, pmid) NULLS FIRST) AS srno, pmid FROM portal_master WHERE cid = v_cid AND title LIKE '%' || v_searchtext || '%' AND COALESCE(isverified, 0) = 1 AND active = 1 AND expirydate >= dbo.fun_getCurrentDate();
