  INSERT INTO v_tblaid (pmid, position) SELECT pmid, 1 FROM portal_master WHERE cid = v_cid AND (',' || subcatid || ',') LIKE '%,' || v_catid || ',%' AND (',' || subaid || ',') LIKE '%,' || v_areaid || ',%' AND active = 1 AND COALESCE(isverified, 0) = 1 AND expirydate >= dbo.fun_getCurrentDate();
  INSERT INTO v_tblaid (pmid, position) SELECT pmid, 2 FROM portal_master WHERE cid = v_cid AND (',' || catid || ',') LIKE '%,' || v_catid || ',%' AND (',' || aid || ',') LIKE '%,' || v_areaid || ',%' AND active = 1 AND COALESCE(isverified, 0) = 1 AND NOT pmid IN (SELECT pmid FROM v_tblaid);
  INSERT INTO v_tblaid (pmid, position) SELECT pmid, 3 FROM portal_master WHERE cid = v_cid AND (',' || subautocatid || ',') LIKE '%,' || v_catid || ',%' AND (',' || subaid || ',') LIKE '%,' || v_areaid || ',%' AND expirydate >= dbo.fun_getCurrentDate() AND active = 1 AND COALESCE(isverified, 0) = 1 AND NOT pmid IN (SELECT pmid FROM v_tblaid);
