  v_i6 := v_i6 + 1;
  END LOOP;
  INSERT INTO tmp_temppmid (pmid, srno, position) SELECT DISTINCT pmid, ROW_NUMBER() OVER (ORDER BY dbo.myrandom_gen_replace1(v_randnumber, pmid) NULLS FIRST) AS srno, position FROM v_tblaid ORDER BY position ASC NULLS FIRST;
  END IF;
  IF (v_city = 0 AND v_aid = '') THEN
  IF (v_cid <> 0) THEN
  INSERT INTO tmp_temppmid (srno, pmid) SELECT ROW_NUMBER() OVER (ORDER BY dbo.myrandom_gen_replace1(v_randnumber, pmid) NULLS FIRST) AS srno, pmid FROM portal_master WHERE cid = v_cid AND (',' || subcatid || ',') LIKE '%,' || v_catid || ',%' AND active = 1 AND COALESCE(isverified, 0) = 1 AND expirydate >= dbo.fun_getCurrentDate();
  INSERT INTO tmp_temppmid (srno, pmid) SELECT ROW_NUMBER() OVER (ORDER BY dbo.myrandom_gen_replace1(v_randnumber, pmid) NULLS FIRST) AS srno, pmid FROM portal_master WHERE cid = v_cid AND (',' || catid || ',') LIKE '%,' || v_catid || ',%' AND active = 1 AND COALESCE(isverified, 0) = 1 AND NOT pmid IN (SELECT pmid FROM tmp_temppmid);
