  INSERT INTO tmp_temppmid (srno, pmid) SELECT ROW_NUMBER() OVER (ORDER BY dbo.myrandom_gen_replace1(v_randnumber, pmid) NULLS FIRST) AS srno, pmid FROM portal_master WHERE cid = v_cid AND (',' || autocatid || ',') LIKE '%,' || v_catid || ',%' AND active = 1 AND COALESCE(isverified, 0) = 1 AND NOT pmid IN (SELECT pmid FROM tmp_temppmid);
  END IF;
  END IF;
  END IF;
  SELECT COUNT(*) INTO v_noofrec FROM tmp_temppmid;
  RETURN QUERY SELECT rownumber, p.companyimage, p.pmid, p.title, COALESCE(p.companydesc, '') AS description, p.mobileno, COALESCE(p.url, '') AS websiteurl, COALESCE(p.address, 'N/A') AS address, p.accounttype, p.comemailid, p.yearofestable, (p.address || ',' || CASE WHEN p.lankmark IS NULL THEN '-' WHEN p.lankmark = '' THEN '-' ELSE p.lankmark END || ',' || p.areaname || ',' || c.cityname || ',' || p.pincode) AS completeaddress, dbo.genratingurl(p.pmid) AS url, v_noofrec AS noofrec, dbo.bindingkeywordlist(p.pmid) AS allkeyword, dbo.findtotalreating(p.pmid) AS avgrating, (SELECT COUNT(rwid) FROM tbl_reviewmaster WHERE pmid = p.pmid AND status = 1) AS totalreviews FROM portal_master AS p, tmp_temppmid AS tp, city AS c WHERE p.pmid = tp.pmid AND p.ctid = c.ctid AND tp.rownumber BETWEEN v_minindex AND v_maxindex;
  DROP TABLE IF EXISTS tmp_temppmid;
  DROP TABLE IF EXISTS tmp_tempareaid;
  -- SET option (removed)
END;
$$;


