--
-- Name: usp_portalmaster_searching_new(character varying, character varying, character varying, integer, integer, character varying, integer, integer, integer, character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_portalmaster_searching_new(v_mode character varying DEFAULT ''::character varying, v_searchtype character varying DEFAULT ''::character varying, v_catid character varying DEFAULT ''::character varying, v_cid integer DEFAULT 0, v_city integer DEFAULT 0, v_aid character varying DEFAULT ''::character varying, v_pageno integer DEFAULT 1, v_pagesize integer DEFAULT 100, v_randnumber integer DEFAULT 4, v_searchtext character varying DEFAULT ''::character varying) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_maxrow int;
  v_startrowindex int;
  v_areaid bigint;
  v_rowcount int;
  v_noofrec int;
  v_diff int;
  v_minindex int;
  v_maxindex int;
  v_i INT;
  v_countrecord int;
  v_newcatid int;
  v_i1 INT;
  v_countrecord4 int;
  v_newcatid4 int;
  v_i2 INT;
  v_countrecord99 int;
  v_newcatid99 int;
  v_i3 INT;
  v_i4 INT;
BEGIN
  -- SET option (removed)
  v_maxrow := (v_pageno * v_pagesize) - 0;
  v_startrowindex := (v_pageno - 1) * v_pagesize + 1;
  v_minindex := 0;
  v_maxindex := 0;
  v_minindex := ((v_pageno - 1) * v_pagesize) + 1;
  v_maxindex := (v_pageno * v_pagesize);
  DROP TABLE IF EXISTS tmp_tempareaid;
  CREATE TEMP TABLE tmp_tempareaid (rowNumber int GENERATED BY DEFAULT AS IDENTITY,
areaidtemp int) ON COMMIT DROP;
  INSERT INTO tmp_tempareaid SELECT aid FROM area_master WHERE cid = v_cid AND ctid = v_city AND areaname = v_aid;
  SELECT COUNT(rownumber) INTO v_rowcount FROM tmp_tempareaid;
  DROP TABLE IF EXISTS v_temp;
  CREATE TEMP TABLE v_temp (id int GENERATED BY DEFAULT AS IDENTITY,
rowNumber bigint ,
CompanyImage text,
pmid bigint,
title varchar(200),
mobileno varchar(200),
address text,
accounttype int,
comemailid varchar(100),
yearofestable int,
completeaddress text) ON COMMIT DROP;
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp (rowNumber bigint ,
CompanyImage text,
pmid bigint,
title varchar(200),
mobileno varchar(200),
address text,
accounttype int,
comemailid varchar(100),
