--
-- Name: usp_portalmaster_searching_paidlisting(character varying, character varying, integer, character varying, character varying, character varying, integer, integer, integer, text); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_portalmaster_searching_paidlisting(v_mode character varying DEFAULT 'PaidListing'::character varying, v_searchtype character varying DEFAULT ''::character varying, v_cid integer DEFAULT 96, v_ctid character varying DEFAULT 0, v_aid character varying DEFAULT ''::character varying, v_pincode character varying DEFAULT ''::character varying, v_pageno integer DEFAULT 1, v_pagesize integer DEFAULT 30, v_randnumber integer DEFAULT 940, v_searchtext text DEFAULT ''::text) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_areaid VARCHAR(50);
  v_rowcount INT;
  v_noofrec INT;
  v_diff INT;
  v_minindex INT;
  v_maxindex INT;
  v_count INT;
  v_searchtypeint INT;
  v_city text;
BEGIN
  -- SET option (removed)
  v_minindex := 0;
  v_maxindex := 0;
  v_count := 0;
  v_minindex := ((v_pageno - 1) * v_pagesize) + 1;
  v_maxindex := (v_pageno * v_pagesize);
  v_city := v_ctid;
  DROP TABLE IF EXISTS tmp_tempareaid;
  CREATE TEMP TABLE tmp_tempareaid (ROWNUMBER INT GENERATED BY DEFAULT AS IDENTITY,
	AREAIDTEMP INT,
	IFPINTYPE smallint) ON COMMIT DROP;
  IF (v_pincode <> '') THEN
  INSERT INTO tmp_tempareaid SELECT aid, 1 FROM area_master WHERE cid = v_cid AND ctid = v_city AND areaname = v_aid AND COALESCE(pincode, '') = v_pincode;
  END IF;
  INSERT INTO tmp_tempareaid SELECT aid, 2 FROM area_master WHERE cid = v_cid AND ctid = v_city AND areaname = v_aid AND COALESCE(pincode, '') <> v_pincode;
  SELECT COUNT(rownumber) INTO v_rowcount FROM tmp_tempareaid;
  DROP TABLE IF EXISTS tmp_temppmid;
  CREATE TEMP TABLE tmp_temppmid (ROWNUMBER INT GENERATED BY DEFAULT AS IDENTITY,
	PMID BIGINT,
	SRNO INT,
	POSITION INT,
	IFPINTYPE smallint) ON COMMIT DROP;
  DROP TABLE IF EXISTS v_tblaid;
  CREATE TEMP TABLE v_tblaid (PMID BIGINT,
	 POSITION INT,
	 IFPINTYPE smallint DEFAULT(0)) ON COMMIT DROP;
  IF (v_mode = 'PaidListing') THEN
  IF (v_city <> 0 AND v_aid = '') THEN
  INSERT INTO tmp_temppmid (srno, pmid) SELECT ROW_NUMBER() OVER (ORDER BY dbo.MYRANDOM_GEN_REPLACE1(v_randnumber, pmid) NULLS FIRST) AS srno, pmid FROM portal_master WHERE cid = v_cid AND (',' || subctid || ',') LIKE '%,' || v_city || ',%' AND active = 1 AND COALESCE(isverified, 0) = 1 AND expirydate >= GETUTCDATE();
  INSERT INTO tmp_temppmid (srno, pmid) SELECT ROW_NUMBER() OVER (ORDER BY dbo.MYRANDOM_GEN_REPLACE1(v_randnumber, pmid) NULLS FIRST) AS srno, pmid FROM portal_master WHERE cid = v_cid AND (',' || CAST(ctid AS VARCHAR(50)) || ',') LIKE '%,' || v_city || ',%' AND active = 1 AND COALESCE(isverified, 0) = 1 AND NOT pmid IN (SELECT pmid FROM tmp_temppmid);
  END IF;
  IF (v_city <> 0 AND v_aid <> '') THEN
  INSERT INTO v_tblaid (pmid, position, ifpintype) SELECT pm.pmid, 1, tmp.ifpintype FROM portal_master AS pm INNER JOIN tmp_tempareaid AS tmp ON (',' || pm.subaid || ',') LIKE '%,' || CAST(tmp.areaidtemp AS VARCHAR(100)) || ',%' WHERE pm.cid = v_cid AND pm.active = 1 AND COALESCE(pm.isverified, 0) = 1 AND pm.expirydate >= GETUTCDATE();
  INSERT INTO v_tblaid (pmid, position, ifpintype) SELECT pm.pmid, 2, tmp.ifpintype FROM portal_master AS pm INNER JOIN tmp_tempareaid AS tmp ON (',' || pm.aid || ',') LIKE '%,' || CAST(tmp.areaidtemp AS VARCHAR(100)) || ',%' WHERE pm.cid = v_cid AND pm.active = 1 AND COALESCE(pm.isverified, 0) = 1 AND NOT pm.pmid IN (SELECT pmid FROM v_tblaid);
  INSERT INTO tmp_temppmid (pmid, srno, position, ifpintype) SELECT pmid, ROW_NUMBER() OVER (ORDER BY dbo.MYRANDOM_GEN_REPLACE1(v_randnumber, pmid) NULLS FIRST) AS srno, position, ifpintype FROM v_tblaid ORDER BY ifpintype ASC NULLS FIRST, position ASC NULLS FIRST;
  END IF;
  IF (v_city = 0 AND v_aid = '') THEN
  IF (v_cid <> 0) THEN
  INSERT INTO tmp_temppmid (srno, pmid) SELECT ROW_NUMBER() OVER (ORDER BY dbo.MYRANDOM_GEN_REPLACE1(v_randnumber, pmid) NULLS FIRST) AS srno, pmid FROM portal_master WHERE cid = v_cid AND active = 1 AND COALESCE(isverified, 0) = 1 AND expirydate >= GETUTCDATE();
  INSERT INTO tmp_temppmid (srno, pmid) SELECT ROW_NUMBER() OVER (ORDER BY dbo.MYRANDOM_GEN_REPLACE1(v_randnumber, pmid) NULLS FIRST) AS srno, pmid FROM portal_master WHERE cid = v_cid AND active = 1 AND COALESCE(isverified, 0) = 1 AND NOT pmid IN (SELECT pmid FROM tmp_temppmid);
  END IF;
  END IF;
  SELECT COUNT(pmid) INTO v_count FROM tmp_temppmid;
  IF (v_count = 0) THEN
  v_searchtype := 'C';
  END IF;
  END IF;
  SELECT COUNT(rownumber) INTO v_noofrec FROM tmp_temppmid;
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp (PMID Int) ON COMMIT DROP;
  INSERT INTO tmp_temp SELECT pmid FROM tbl_subscription_details ORDER BY GEN_RANDOM_UUID() NULLS FIRST;
  RETURN QUERY SELECT rownumber, ('https://jewria.com/Company_Logo/' || p.companyimage) AS companyimage, p.pmid, p.title, p.mobileno, p.url, p.comemailid, (p.areaname || ', ' || c.cityname || ', ' || p.pincode) AS completeaddress, dbo.GENRATINGURL(p.pmid) AS detailsurl, v_noofrec AS noofrec, dbo.FINDTOTALREATING(p.pmid) AS avgrating, (SELECT COUNT(rwid) FROM tbl_reviewmaster WHERE pmid = p.pmid AND status = 1 AND reviewtype = 1) AS totalreviews, (SUBSTRING(p.companydesc FROM 1 FOR 175)) AS companydesc FROM portal_master AS p, tmp_temppmid AS tp, city AS c WHERE p.pmid = tp.pmid AND p.ctid = c.ctid AND tp.rownumber BETWEEN v_minindex AND v_maxindex AND p.pmid IN (SELECT pmid FROM tmp_temp) LIMIT 4;
  DROP TABLE IF EXISTS tmp_temppmid;
  DROP TABLE IF EXISTS tmp_tempareaid;
  DROP TABLE IF EXISTS tmp_temp;
  -- SET option (removed)
END;
$$;


--
-- Name: usp_portalmaster_searching_sanjay2(character varying, character varying, character varying, integer, integer, character varying, integer, integer, integer, character varying); Type: FUNCTION; Schema: dbo; Owner: -
