CREATE FUNCTION dbo.usp_portalmaster_searching_sanjay2(v_mode character varying DEFAULT ''::character varying, v_searchtype character varying DEFAULT ''::character varying, v_catid character varying DEFAULT ''::character varying, v_cid integer DEFAULT 0, v_city integer DEFAULT 0, v_aid character varying DEFAULT ''::character varying, v_pageno integer DEFAULT 1, v_pagesize integer DEFAULT 10, v_randnumber integer DEFAULT 4, v_searchtext character varying DEFAULT ''::character varying) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_areaid bigint;
  v_rowcount int;
  v_noofrec int;
  v_diff int;
  v_minindex int;
  v_maxindex int;
  v_i INT;
  v_countrecord int;
  v_newcatid int;
  v_i1 INT;
  v_countrecord4 int;
  v_newcatid4 int;
  v_i2 INT;
  v_countrecord99 int;
  v_newcatid99 int;
  v_i3 INT;
  v_i4 INT;
BEGIN
  -- SET option (removed)
  v_minindex := 0;
  v_maxindex := 0;
  v_minindex := ((v_pageno - 1) * v_pagesize) + 1;
  v_maxindex := (v_pageno * v_pagesize);
