areaidtemp int) ON COMMIT DROP;
  INSERT INTO tmp_tempareaid SELECT aid FROM area_master WHERE cid = v_cid AND ctid = v_city AND areaname = v_aid;
  SELECT COUNT(rownumber) INTO v_rowcount FROM tmp_tempareaid;
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp (rowNumber bigint ,
CompanyImage text,
pmid bigint,
title varchar(200),
mobileno varchar(200),
address text,
accounttype int,
comemailid varchar(100),
yearofestable int,
