  END IF;
  ELSE
  IF (v_mode = 'c') THEN
  IF (v_city <> 0 AND v_aid = '') THEN
  INSERT INTO tmp_temp (rownumber, companyimage, pmid, title, mobileno, address, accounttype, comemailid, yearofestable, completeaddress) SELECT DISTINCT ROW_NUMBER() OVER (ORDER BY dbo.myrandom_gen_replace_sanjay1(v_randnumber, p.pmid) NULLS FIRST) AS rownumber, p.companyimage, p.pmid, p.title, p.mobileno, COALESCE(p.address, 'N/A') AS address, p.accounttype, p.comemailid, p.yearofestable, (p.address || ',' || CASE WHEN p.lankmark IS NULL THEN '-' WHEN p.lankmark = '' THEN '-' ELSE p.lankmark END || ',' || p.areaname || ',' || c.cityname || ',' || p.pincode) AS completeaddress FROM portal_master AS p INNER JOIN city AS c ON p.ctid = c.ctid WHERE p.active = 1 AND p.isverified = 1 AND ((p.catid IN ('' || CAST(v_catid AS text) || '')) OR (p.catid LIKE ('%,' || CAST(v_catid AS text) || ',%')) OR (p.catid LIKE ('%' || CAST(v_catid AS text) || ',%')) OR (p.catid LIKE ('%,' || CAST(v_catid AS text) || ''))) AND ((p.ctid = v_city)) ORDER BY p.accounttype DESC NULLS LAST, p.title NULLS FIRST;
  END IF;
  IF (v_city <> 0 AND v_aid <> '') THEN
  v_i4 := 1;
  WHILE (v_i4 <= v_rowcount) LOOP
  SELECT areaidtemp INTO v_areaid FROM tmp_tempareaid WHERE rownumber = v_i4;
  IF (v_i4 <= 1) THEN
  IF NOT EXISTS(SELECT pmid FROM tmp_temp WHERE pmid = (SELECT pmid FROM tmp_temp ORDER BY rownumber DESC NULLS LAST LIMIT 1)) THEN
  INSERT INTO tmp_temp (rownumber, companyimage, pmid, title, mobileno, address, accounttype, comemailid, yearofestable, completeaddress) SELECT DISTINCT ROW_NUMBER() OVER (ORDER BY dbo.myrandom_gen_replace_sanjay1(v_randnumber, p.pmid) NULLS FIRST) AS rownumber, p.companyimage, p.pmid, p.title, p.mobileno, COALESCE(p.address, 'N/A') AS address, p.accounttype, p.comemailid, p.yearofestable, (p.address || ',' || CASE WHEN p.lankmark IS NULL THEN '-' WHEN p.lankmark = '' THEN '-' ELSE p.lankmark END || ',' || p.areaname || ',' || c.cityname || ',' || p.pincode) AS completeaddress FROM portal_master AS p INNER JOIN city AS c ON p.ctid = c.ctid WHERE p.active = 1 AND p.isverified = 1 AND ((p.catid IN ('' || CAST(v_catid AS text) || '')) OR (p.catid LIKE ('%,' || CAST(v_catid AS text) || ',%')) OR (p.catid LIKE ('%' || CAST(v_catid AS text) || ',%')) OR (p.catid LIKE ('%,' || CAST(v_catid AS text) || ''))) AND ((p.ctid = v_city)) AND ((p.areaname LIKE '' || v_aid || '%')) ORDER BY p.accounttype DESC NULLS LAST, p.title NULLS FIRST;
  END IF;
  ELSE
  IF NOT EXISTS(SELECT pmid FROM tmp_temp WHERE pmid = (SELECT pmid FROM tmp_temp ORDER BY rownumber DESC NULLS LAST LIMIT 1)) THEN
  INSERT INTO tmp_temp (rownumber, companyimage, pmid, title, mobileno, address, accounttype, comemailid, yearofestable, completeaddress) SELECT DISTINCT ROW_NUMBER() OVER (ORDER BY dbo.myrandom_gen_replace_sanjay1(v_randnumber, p.pmid) NULLS FIRST) AS rownumber, p.companyimage, p.pmid, p.title, p.mobileno, COALESCE(p.address, 'N/A') AS address, p.accounttype, p.comemailid, p.yearofestable, (p.address || ',' || CASE WHEN p.lankmark IS NULL THEN '-' WHEN p.lankmark = '' THEN '-' ELSE p.lankmark END || ',' || p.areaname || ',' || c.cityname || ',' || p.pincode) AS completeaddress FROM portal_master AS p INNER JOIN city AS c ON p.ctid = c.ctid WHERE p.active = 1 AND p.isverified = 1 AND ((p.catid IN ('' || CAST(v_catid AS text) || '')) OR (p.catid LIKE ('%,' || CAST(v_catid AS text) || ',%')) OR (p.catid LIKE ('%' || CAST(v_catid AS text) || ',%')) OR (p.catid LIKE ('%,' || CAST(v_catid AS text) || ''))) AND ((p.ctid = v_city)) ORDER BY p.accounttype DESC NULLS LAST, p.title NULLS FIRST;
  END IF;
  END IF;
  v_i4 := v_i4 + 1;
  END LOOP;
  END IF;
  IF (v_city = 0 AND v_aid = '') THEN
  IF (v_cid <> 0) THEN
  INSERT INTO tmp_temp (rownumber, companyimage, pmid, title, mobileno, address, accounttype, comemailid, yearofestable, completeaddress) SELECT DISTINCT ROW_NUMBER() OVER (ORDER BY dbo.myrandom_gen_replace_sanjay1(v_randnumber, p.pmid) NULLS FIRST) AS rownumber, p.companyimage, p.pmid, p.title, p.mobileno, COALESCE(p.address, 'N/A') AS address, p.accounttype, p.comemailid, p.yearofestable, (p.address || ',' || CASE WHEN p.lankmark IS NULL THEN '-' WHEN p.lankmark = '' THEN '-' ELSE p.lankmark END || ',' || p.areaname || ',' || c.cityname || ',' || p.pincode) AS completeaddress FROM portal_master AS p INNER JOIN city AS c ON p.ctid = c.ctid WHERE p.active = 1 AND p.isverified = 1 AND p.cid = v_cid AND ((p.catid IN ('' || CAST(v_catid AS text) || '')) OR (p.catid LIKE ('%,' || CAST(v_catid AS text) || ',%')) OR (p.catid LIKE ('%' || CAST(v_catid AS text) || ',%')) OR (p.catid LIKE ('%,' || CAST(v_catid AS text) || ''))) ORDER BY p.accounttype DESC NULLS LAST, p.title NULLS FIRST;
  END IF;
  END IF;
  END IF;
  END IF;
  END IF;
  SELECT COUNT(*) INTO v_noofrec FROM tmp_temp;
  RETURN QUERY SELECT dbo.myrandom_gen_replace_sanjay1(v_randnumber, pmid) AS sr, rownumber, companyimage, pmid, title, mobileno, address, accounttype, comemailid, (CASE CAST(yearofestable AS VARCHAR(30)) WHEN '0' THEN 'N/A' ELSE CAST(yearofestable AS VARCHAR(30)) END) AS yearofestable, dbo.genratingurl(pmid) AS url, v_noofrec AS noofrec, dbo.bindingkeywordlist(pmid) AS allkeyword, dbo.findtotalreating(pmid) AS totalreview, completeaddress FROM tmp_temp WHERE rownumber BETWEEN v_minindex AND v_maxindex;
  DROP TABLE IF EXISTS tmp_temp;
  -- SET option (removed)
END;
$$;


