--
-- Name: usp_portalsearch(integer, integer, character varying, boolean, character varying, character varying, character varying, character varying, character varying, integer, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_portalsearch(v_startrowindex integer, v_maxrows integer, v_orderbyfield character varying, v_asc boolean, v_searchfield character varying, v_searchvalue character varying, v_cid character varying DEFAULT ''::character varying, v_fromdate character varying DEFAULT ''::character varying, v_todate character varying DEFAULT ''::character varying, v_mode integer DEFAULT NULL::integer, v_recordcount integer DEFAULT NULL::integer) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_regno bigint;
  v_sqlquery text;
BEGIN
  -- SET option (removed)
  v_sqlquery := '';
  IF (v_orderbyfield = '') THEN
  v_orderbyfield := 'tsd.subscriptiondate desc';
  END IF;
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp (rowNumber bigint,
pmid bigint,
companyname text,
loginID varchar(150),
status varchar(100),
totalprice numeric(19,4),
paidamount numeric(19,4), 
noofmonth int,
paymode varchar(50),
subscriptiondate date,
sdid bigint,
countryName varchar(100),
CID int,
currencysymbol varchar(400)) ON COMMIT DROP;
  v_sqlquery := 'insert into #temp select ROW_NUMBER() OVER(order by ' || v_orderbyfield || ') as rowNumber,pm.pmid,pm.companyname,pl.LoginId,
(case tsd.active when 1 then ''Active'' when 2 then ''Rejected'' end ) as status,tsd.totalprice,tsd.paidamount,tsd.noofmonth,tsd.paymode,tsd.subscriptiondate,
tsd.sdid,(case when C.countryName=''UNITED STATES'' then ''US'' when C.countryName=''UNITED KINGDOM'' then ''UK'' else  C.countryName end  ) as countryName,c.CID,cm.currencysymbol
from tbl_subscription_details tsd, portal_master pm,Portal_Login pl,country c,tbl_currencymaster cm where  
pm.pmid=pl.PMID and c.CID=cm.CID and pm.pmid=tsd.pmid and c.CID=tsd.cid and (tsd.active=1 or tsd.active=2) ';
  IF (v_cid <> '') THEN
  v_sqlquery := v_sqlquery || ' and ('',''+convert(varchar(50),C.cid)+'','') like  ''%,' || '' || CAST(v_cid AS text) || '' || ',%''';
  END IF;
  IF (v_fromdate <> '' AND v_todate <> '') THEN
  v_sqlquery := v_sqlquery || ' and convert(date, tsd.subscriptiondate)  between  convert(varchar(10),''' || v_fromdate || ''',103)  and convert(varchar(10),''' || v_todate || ''',103)';
  END IF;
  IF (v_searchfield = '1') THEN
  v_sqlquery := v_sqlquery || ' and pl.LoginId like ''%' || v_searchvalue || '%''';
  END IF;
  IF (v_searchfield = '2') THEN
  v_sqlquery := v_sqlquery || ' and pm.companyname like ''%' || v_searchvalue || '%''';
  END IF;
  EXECUTE v_sqlquery;
  SELECT COUNT(*) INTO v_recordcount FROM tmp_temp;
  RETURN QUERY SELECT * FROM tmp_temp WHERE rownumber BETWEEN v_startrowindex AND v_maxrows;
  DROP TABLE IF EXISTS tmp_temp;
  RETURN QUERY SELECT v_recordcount AS recordcount;
  -- SET option (removed)
END;
$$;


--
-- Name: usp_postpaidrecharge_details(integer, integer, integer, character varying, character varying, integer, character varying, character varying, character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_postpaidrecharge_details(v_mode integer DEFAULT 0, v_startrowindex integer DEFAULT 1, v_maxrows integer DEFAULT 100, v_fromdate character varying DEFAULT ''::character varying, v_todate character varying DEFAULT ''::character varying, v_totalcount integer DEFAULT 0, v_searchfield character varying DEFAULT ''::character varying, v_searchvalue character varying DEFAULT ''::character varying, v_status character varying DEFAULT ''::character varying) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_minindex INT;
  v_maxindex INT;
  v_query text;
BEGIN
  v_minindex := (v_startrowindex - 1) * v_maxrows + 1;
  v_maxindex := v_startrowindex * v_maxrows;
  IF (v_mode = 0) THEN
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp (ROWNUMBER BIGINT GENERATED BY DEFAULT AS IDENTITY,       
 TCPRID BIGINT,             
 CLID BIGINT,               
 MOBILENO VARCHAR(100),       
 OPERATORTYPE VARCHAR(100),      
 RECHARGEAMOUNT DECIMAL(18,2),      
 TRANSACTIONID  VARCHAR(100),       
 RECHARGEDATE VARCHAR(100),       
 ADMINSTATUS VARCHAR(100),      
 NAME VARCHAR(100),      
 EMAILID VARCHAR(100),      
 OPERATORNAME VARCHAR(100),      
 OPERATORCODE VARCHAR(100),      
 ISANDROIDORWEB INT,      
 PaidViaCashWallet Decimal(18,8),    
PaidViaCahbackWallet Decimal(18,8),    
PaidViaKreazVoucher Int,    
PaidViaOnline Decimal(18,8)) ON COMMIT DROP;
  v_query := 'INSERT INTO #TEMP SELECT TCPR.TCPRID,TCPR.CLID,TCPR.MOBILENO,TCPR.OPERATORTYPE,      
 TCPR.RECHARGEAMOUNT,TCPR.TRANSACTIONID,CAST(TCPR.RECHARGEDATE AS VARCHAR(50)) ,TCPR.RECHARGESTATUS      
 ,(CL.FNAME+'' ''+CL.LNAME) AS NAME,CL.EMAILID,TCPR.OPERATORNAME,TCPR.OPERATORCODE,TCPR.ISANDROIDORWEB,      
  ISNULL(CASHWALLETUSED,0),  
ISNULL(CASHBACKWALLETUSED,0),    
ISNULL(VOUCHERWALLETUSED,0),  
ISNULL(TBL_ONLINEPAYMENTHISTORY.AMOUNT,0)        
 FROM TBL_CUSTOMER_POSTPAID_RECHARGES TCPR     
 LEFT JOIN TBL_ORDERPAYMENT_HISTORY ON TBL_ORDERPAYMENT_HISTORY.ORDERID=TCPR.TRANSACTIONID      
LEFT JOIN TBL_ORDERONLINEREQUESTS ON TBL_ORDERONLINEREQUESTS.ORDERID=TCPR.TRANSACTIONID     
LEFT JOIN TBL_ONLINEPAYMENTHISTORY ON TBL_ONLINEPAYMENTHISTORY.REFERNECID=TBL_ORDERONLINEREQUESTS.TRANSACTIONID                         
       
 LEFT JOIN TBL_CUSTOMERLOGIN CL ON CL.CLID=TCPR.CLID        
  WHERE TCPR.RECHARGESTATUS Is Not Null ';
  IF ((v_fromdate <> '') AND (v_todate = '')) THEN
  v_query := v_query || ' AND CONVERT(DATE, TCPR.RECHARGEDATE, 105) BETWEEN  CONVERT(DATE, ''' || v_fromdate || ''', 105) AND  CONVERT(DATE, DBO.FUN_GETCURRENTDATE(), 105)';
  END IF;
  IF ((v_fromdate = '') AND (v_todate <> '')) THEN
  v_query := v_query || 'AND CONVERT(DATE, TCPR.RECHARGEDATE, 105) BETWEEN  CONVERT(DATE, ''' || v_todate || ''', 105) AND  CONVERT(DATE, DBO.FUN_GETCURRENTDATE(), 105)';
  END IF;
  IF ((v_fromdate <> '') AND (v_todate <> '')) THEN
  v_query := v_query || 'AND CONVERT(DATE, TCPR.RECHARGEDATE, 105) BETWEEN CONVERT(DATE, ''' || v_fromdate || ''', 105) AND  CONVERT(DATE, ''' || v_todate || ''', 105)';
  END IF;
  IF (v_searchfield = 'NAME') THEN
  v_query := v_query || ' AND (CL.FNAME+CL.LNAME) LIKE ''%' || v_searchvalue || '%'' ';
  END IF;
  IF (v_searchfield = 'PHONE') THEN
  v_query := v_query || ' AND TCPR.MOBILENO LIKE ''%' || v_searchvalue || '%'' ';
  END IF;
  IF (v_searchfield = 'EMAILID') THEN
  v_query := v_query || ' AND CL.EMAILID LIKE ''%' || v_searchvalue || '%'' ';
  END IF;
  IF (v_searchfield = 'TRANSACTIONID') THEN
  v_query := v_query || ' AND TCPR.TRANSACTIONID LIKE ''%' || v_searchvalue || '%'' ';
  END IF;
  IF (v_status <> '') THEN
  v_query := v_query || ' AND TCPR.RECHARGESTATUS like ''%' || v_status || '%'' ';
  END IF;
  v_query := v_query || ' ORDER BY TCPR.RECHARGEDATE DESC';
  EXECUTE v_query;
  RAISE NOTICE '%', v_query;
  RETURN QUERY SELECT rownumber, tcprid, clid, mobileno, operatortype, rechargeamount, transactionid, rechargedate, (CASE WHEN adminstatus = 'FAILURE' THEN 'FAILED' ELSE adminstatus END) AS adminstatus, name, emailid, operatorname, operatorcode, isandroidorweb, paidviacashwallet, paidviacahbackwallet, paidviakreazvoucher, paidviaonline FROM tmp_temp WHERE rownumber BETWEEN v_minindex AND v_maxindex ORDER BY rownumber ASC NULLS FIRST;
  SELECT COUNT(rownumber) INTO v_totalcount FROM tmp_temp;
  DROP TABLE IF EXISTS tmp_temp;
  -- SET option (removed)
  END IF;
END;
$$;


