--
-- Name: usp_prepaidrecharge_details(integer, integer, integer, character varying, character varying, integer, character varying, character varying, character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_prepaidrecharge_details(v_mode integer DEFAULT 0, v_startrowindex integer DEFAULT 1, v_maxrows integer DEFAULT 100, v_fromdate character varying DEFAULT ''::character varying, v_todate character varying DEFAULT ''::character varying, v_totalcount integer DEFAULT 0, v_searchfield character varying DEFAULT ''::character varying, v_searchvalue character varying DEFAULT ''::character varying, v_status character varying DEFAULT ''::character varying) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_minindex INT;
  v_maxindex INT;
  v_query text;
BEGIN
  v_minindex := (v_startrowindex - 1) * v_maxrows + 1;
  v_maxindex := v_startrowindex * v_maxrows;
  IF (v_mode = 0) THEN
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp (ROWNUMBER BIGINT GENERATED BY DEFAULT AS IDENTITY,       
 TCPRID BIGINT,             
 CLID BIGINT,               
 MOBILENO VARCHAR(100),       
 OPERATORTYPE VARCHAR(100),      
 RECHARGEAMOUNT DECIMAL(18,2),      
 TRANSACTIONID  VARCHAR(100),       
 RECHARGEDATE VARCHAR(100),       
 ADMINSTATUS VARCHAR(100),      
 NAME VARCHAR(100),      
 EMAILID VARCHAR(100),      
 OPERATORNAME VARCHAR(100),      
 OPERATORCODE VARCHAR(100),      
 ISANDROIDORWEB INT,      
 PaidViaCashWallet Decimal(18,8),    
PaidViaCahbackWallet Decimal(18,8),    
PaidViaKreazVoucher Int,    
PaidViaOnline Decimal(18,8)) ON COMMIT DROP;
  v_query := 'INSERT INTO #TEMP SELECT TCPR.TCPRID,TCPR.CLID,TCPR.MOBILENO,TCPR.OPERATORTYPE,      
TCPR.RECHARGEAMOUNT,TCPR.TRANSACTIONID,CAST(TCPR.RECHARGEDATE AS VARCHAR(50)) ,TCPR.RECHARGESTATUS      
,(CL.FNAME+'' ''+CL.LNAME) AS NAME,CL.EMAILID,TCPR.OPERATORNAME,TCPR.OPERATORCODE,TCPR.ISANDROIDORWEB,      
 ISNULL(CASHWALLETUSED,0),  
ISNULL(CASHBACKWALLETUSED,0),    
ISNULL(VOUCHERWALLETUSED,0),  
ISNULL(TBL_ONLINEPAYMENTHISTORY.AMOUNT,0)       
FROM TBL_CUSTOMER_PREPAID_RECHARGES TCPR    
LEFT JOIN TBL_ORDERPAYMENT_HISTORY ON TBL_ORDERPAYMENT_HISTORY.ORDERID=TCPR.TRANSACTIONID      
LEFT JOIN TBL_ORDERONLINEREQUESTS ON TBL_ORDERONLINEREQUESTS.ORDERID=TCPR.TRANSACTIONID     
LEFT JOIN TBL_ONLINEPAYMENTHISTORY ON TBL_ONLINEPAYMENTHISTORY.REFERNECID=TBL_ORDERONLINEREQUESTS.TRANSACTIONID                         
LEFT JOIN TBL_CUSTOMERLOGIN CL ON CL.CLID=TCPR.CLID       
WHERE TCPR.RECHARGESTATUS Is Not Null';
  IF ((v_fromdate <> '') AND (v_todate = '')) THEN
  v_query := v_query || ' AND CONVERT(DATE, TCPR.RECHARGEDATE, 105) BETWEEN  CONVERT(DATE, ''' || v_fromdate || ''', 105) AND  CONVERT(DATE, DBO.FUN_GETCURRENTDATE(), 105)';
  END IF;
  IF ((v_fromdate = '') AND (v_todate <> '')) THEN
  v_query := v_query || 'AND CONVERT(DATE, TCPR.RECHARGEDATE, 105) BETWEEN  CONVERT(DATE, ''' || v_todate || ''', 105) AND  CONVERT(DATE, DBO.FUN_GETCURRENTDATE(), 105)';
  END IF;
  IF ((v_fromdate <> '') AND (v_todate <> '')) THEN
  v_query := v_query || 'AND CONVERT(DATE, TCPR.RECHARGEDATE, 105) BETWEEN CONVERT(DATE, ''' || v_fromdate || ''', 105) AND  CONVERT(DATE, ''' || v_todate || ''', 105)';
  END IF;
  IF (v_searchfield = 'NAME') THEN
  v_query := v_query || ' AND (CL.FNAME+CL.LNAME) LIKE ''%' || v_searchvalue || '%'' ';
  END IF;
  IF (v_searchfield = 'PHONE') THEN
  v_query := v_query || ' AND TCPR.MOBILENO LIKE ''%' || v_searchvalue || '%'' ';
  END IF;
  IF (v_searchfield = 'EMAILID') THEN
  v_query := v_query || ' AND CL.EMAILID LIKE ''%' || v_searchvalue || '%'' ';
  END IF;
  IF (v_searchfield = 'TRANSACTIONID') THEN
  v_query := v_query || ' AND TCPR.TRANSACTIONID LIKE ''%' || v_searchvalue || '%'' ';
  END IF;
  IF (v_status <> '') THEN
  v_query := v_query || ' AND TCPR.RECHARGESTATUS =''' || v_status || ''' ';
  END IF;
  v_query := v_query || ' ORDER BY TCPR.RECHARGEDATE DESC';
  EXECUTE v_query;
  RETURN QUERY SELECT rownumber, tcprid, clid, mobileno, operatortype, rechargeamount, transactionid, rechargedate, adminstatus, name, emailid, operatorname, operatorcode, isandroidorweb, paidviacashwallet, paidviacahbackwallet, paidviakreazvoucher, paidviaonline FROM tmp_temp WHERE rownumber BETWEEN v_minindex AND v_maxindex ORDER BY rownumber ASC NULLS FIRST;
  SELECT COUNT(rownumber) INTO v_totalcount FROM tmp_temp;
  DROP TABLE IF EXISTS tmp_temp;
  -- SET option (removed)
  END IF;
END;
$$;


--
-- Name: usp_printinvoice(integer, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_printinvoice(v_plid integer DEFAULT 0, v_sfdid integer DEFAULT 0) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_businessname text;
  v_username text;
  v_emailid text;
BEGIN
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp (RowNumber Int GENERATED BY DEFAULT AS IDENTITY,
TRANSID text,
timestamp text,
BusinessName text,
UserName text,
EmailId text,
PaymentMode text,
Amount text,
FundType text) ON COMMIT DROP;
  v_businessname := '';
  v_username := '';
  v_emailid := '';
  INSERT INTO tmp_temp SELECT transid, CAST(TO_CHAR(datetime, 'DD TMMon YYYY') AS VARCHAR(11)), '', '', '', paymenttype, CAST(depositamount AS VARCHAR(11)), fundtype FROM tbl_sponserfunddetails WHERE sfdid = v_sfdid AND plid = v_plid;
  SELECT companyname INTO v_businessname FROM portal_master WHERE plid = v_plid;
  SELECT username, loginid INTO v_username, v_emailid FROM portal_login WHERE plid = v_plid;
  UPDATE tmp_temp SET businessname = v_businessname, username = v_username, emailid = v_emailid;
  RETURN QUERY SELECT * FROM tmp_temp;
END;
$$;


--
-- Name: usp_processlist_qa(character varying, character varying, integer, integer, bigint); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_processlist_qa(v_fromdate character varying DEFAULT ''::character varying, v_todate character varying DEFAULT ''::character varying, v_pageno integer DEFAULT 1, v_pagesize integer DEFAULT 30, v_optid bigint DEFAULT NULL::bigint) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_minindex int;
  v_maxindex int;
  v_recordcount int;
  v_amount numeric(19,4);
  v_currencysymbol varchar(20);
  v_totalamount numeric(19,4);
  v_sqlquery text;
BEGIN
  -- SET option (removed)
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp (rowNumber bigint,
lwq_id bigint,
title text,
LoginId varchar(100),
countryName varchar(25),
date  varchar(25),
optID varchar(100)) ON COMMIT DROP;
  v_minindex := 0;
  v_maxindex := 0;
  v_sqlquery := '';
  v_minindex := ((v_pageno - 1) * v_pagesize) + 1;
  v_maxindex := (v_pageno * v_pagesize);
  v_sqlquery := 'insert into #temp  select ROW_NUMBER() over(order by LW.date  desc) as rownumber,lw.lwq_id,Pm.title,pl.LoginId,C.countryName,LW.date,OM2.loginid as optID from tbl_ListingsWithQA LW
left join portal_master Pm on LW.pmid=PM.pmid  
left join portal_login PL on Pm.pmid=PL.pmid 
left join tbl_operator_master OM on OM.optid=Pm.optid
left join COUNTRY C on C.CID=PL.cid 
left join tbl_operator_master OM2 on OM2.optid=Pm.optid where pm.isverified=2  and  LW.optid=' || CAST(v_optid AS VARCHAR(20));
  IF (v_fromdate <> '') THEN
  v_sqlquery := v_sqlquery || ' and convert(date, lw.date,103) = convert(date,''' || v_fromdate || ''',103) ';
  END IF;
  IF (v_todate <> '') THEN
  v_sqlquery := v_sqlquery || ' and convert(date, lw.date,103)  =convert(date,''' || v_todate || ''',103) ';
  END IF;
  IF (v_fromdate <> '' AND v_todate <> '') THEN
  v_sqlquery := v_sqlquery || ' and convert(date, lw.date,103)  between  convert(date,''' || v_fromdate || ''',103)  and convert(date,''' || v_todate || ''',103)';
  END IF;
  EXECUTE v_sqlquery;
  SELECT COUNT(*) INTO v_recordcount FROM tmp_temp;
  RETURN QUERY SELECT *, v_recordcount AS recordcount FROM tmp_temp WHERE rownumber BETWEEN v_minindex AND v_maxindex;
  DROP TABLE IF EXISTS tmp_temp;
  -- SET option (removed)
END;
$$;


--
-- Name: usp_product_detailing(character varying, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_product_detailing(v_prcode character varying DEFAULT '196'::character varying, v_did integer DEFAULT 0) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_sqlqueryfet text;
  v_sqlquery text;
  v_queryaddstringpmid VARCHAR(100);
  v_finalfetquery text;
  v_finalquery text;
  v_sellprice numeric(19,4);
  v_payableamt numeric(19,4);
  v_images text;
  v_discount numeric(19,4);
  v_sprid BIGINT;
  v_a varchar(5000);
  v_newprcode VARCHAR(100);
  v_rowcount INT;
  v_noofrec INT;
  v_diff INT;
  v_minindex INT;
  v_maxindex INT;
  v_count INT;
  v_searchtypeint INT;
  v_startfetind INT;
  v_endfetind INT;
BEGIN
  -- SET option (removed)
  v_queryaddstringpmid := '';
  v_a := '';
  v_minindex := 0;
  v_maxindex := 0;
  v_count := 0;
  DROP TABLE IF EXISTS tmp_tempprid;
  CREATE TEMP TABLE tmp_tempprid (ROWNUMBER  INT GENERATED BY DEFAULT AS IDENTITY,                        
 MPRID BIGINT,                        
 SPRID BIGINT,                        
 NEWPRCODE text,                        
 PRODTITLE text,                        
 SHORTDESC text ,                        
 FULLDESC text,                        
 PRODIMAGES text,                        
 SELLMRP numeric(19,4),                        
 PAYBLEAMOUNT numeric(19,4),                        
 DISCOUNT numeric(19,4),                        
 MAINCATID INT,                        
 CATID INT,                        
 SUBCATID INT,                        
 KEYFEATURES text,                        
 SOLDBY text,                        
 SELLERRATING text,                        
 PROCUREMENTSLA INT,                        
 REPLACEMENTDAY INT,                        
 SHIPPINGCHARGES DECIMAL(18,2),                        
 DISCOUNTPERCENTAGE DECIMAL(18,2),                        
 CASHONDELIVERY boolean,                        
 WEIGHT_KG DECIMAL(18,2),                        
 LENGTH_CMS DECIMAL(18,2),                        
 BREADTH_CMS DECIMAL(18,2),                        
 HEIGHT_CMS DECIMAL(18,2),                        
 ISOUTOFSTOCK boolean ,                        
 BV DECIMAL(18,2),              
 ActivationPV DECIMAL(18,2),                        
 PV DECIMAL(18,2),                   
 CASHBACK DECIMAL(18,2),                        
 Plid bigint,                        
 Sellercity text,                        
 Specification text,                        
 EXCHANGE INT,                        
 return INT,                        
 INCLUDINGTAX DECIMAL(18,2),                
 PrSKUCODE text,          
 ACTIVATIONPV_PER DECIMAL(18,2),      
 IS_OFFER_ACTIVE boolean ,   
 IS_AFFILIATE boolean,
 IS_AFFILIATE_ENABLE boolean) ON COMMIT DROP;
  IF (v_did > 0) THEN
  INSERT INTO tmp_tempprid SELECT pmm.mprid, pms.sprid AS sprid, pmm.productcode, pmm.producttitle, pmm.shotdescription, pmm.fulldescription, COALESCE(pms.productimages, 'default-product-image.png') AS prodimages, pms.sellmrp AS sellmrp, pms.dap AS paybleamount, pms.discountpercentage AS discount, pmm.maincategoryid, pmm.catid, pmm.subcategoryid, REPLACE(REPLACE(REPLACE(pmm.keyfeatures, '<ul><li>', ''), '</li></ul>', ''), '</li><li>', '^') AS keyfeatures, pm.companyname AS soldby, '4.8/5' AS sellerrating, COALESCE(pms.procurementsla, 0), COALESCE(pms.replacementday, 0), CAST(pms.shippingcharges AS DECIMAL(18, 2)), CAST(discountpercentage AS DECIMAL(18, 2)), COALESCE(pms.cashondelivery, 0), COALESCE(pms.weight_kg, 0), COALESCE(pms.length_cms, 0), COALESCE(pms.breadth_cms, 0), COALESCE(pms.height_cms, 0), pms.isoutofstock, (CASE WHEN COALESCE(CAST(pms.bv AS DECIMAL(18, 2)), 0) = 0 THEN ((COALESCE(CAST((pms.dap + (pms.dap * vc.vatpercvalue) / 100) AS DECIMAL(18, 2)), 0) * COALESCE(tsc.bvper, 0)) / 100) ELSE pms.bv END) AS bv, (CASE WHEN COALESCE(CAST(pms.activationpv_per AS DECIMAL(18, 2)), 0) = 0 THEN ((COALESCE(CAST((pms.dap + (pms.dap * vc.vatpercvalue) / 100) AS DECIMAL(18, 2)), 0) * COALESCE(tsc.activationpv_per, 0)) / 100) ELSE pms.activationpv_per END) AS activationpv, (CASE WHEN COALESCE(CAST(pms.pv AS DECIMAL(18, 2)), 0) = 0 THEN ((COALESCE(CAST((pms.dap + (pms.dap * vc.vatpercvalue) / 100) AS DECIMAL(18, 2)), 0) * COALESCE(tsc.redeemcashback_per, 0)) / 100) ELSE pms.pv END) AS pv, (CASE WHEN COALESCE(CAST(pms.cashback_per AS DECIMAL(18, 2)), 0) = 0 THEN ((COALESCE(CAST((pms.dap + (pms.dap * vc.vatpercvalue) / 100) AS DECIMAL(18, 2)), 0) * COALESCE(tsc.cashback_per, 0)) / 100) ELSE pms.cashback_per END) AS cashback, pmm.branchid, c.cityname, pms.specification, COALESCE(tsc.exchange, 0) AS exchange, COALESCE(tsc.return, 0) AS return, CAST((pms.dap + (pms.dap * vc.vatpercvalue) / 100) AS DECIMAL(18, 2)) AS includingtax, pms.prskucode, pms.activationpv_per, CASE WHEN offer.product_id IS NULL THEN 0 ELSE 1 END AS is_offer, CASE WHEN abp.abpid IS NULL THEN 0 ELSE 1 END AS is_affiliate, COALESCE(abp.is_active, 0) AS is_affiliate_enable FROM ims_masterproduct AS pmm INNER JOIN ims_subproduct AS pms ON pms.mprid = pmm.mprid INNER JOIN tbl_sub_category AS tsc ON tsc.subcatid = pmm.subcategoryid INNER JOIN portal_login AS br ON br.plid = pmm.branchid LEFT JOIN portal_master AS pm ON br.plid = pm.plid LEFT JOIN city AS c ON pm.ctid = c.ctid LEFT JOIN tbl_distributor_comm_productwise AS dpw ON dpw.sprid = pms.sprid AND dpw.did = v_did LEFT JOIN tbl_vat_categories AS vc ON pms.vatcategoryid = vc.vcid LEFT JOIN tbl_offer_on_product AS offer ON pms.sprid = offer.sprid LEFT JOIN affiliate_bonus_on_product AS abp ON abp.sprid = pms.sprid WHERE CAST(pms.sprid AS VARCHAR(100)) = v_prcode;
  ELSE
  INSERT INTO tmp_tempprid SELECT pmm.mprid, pms.sprid AS sprid, pmm.productcode, pmm.producttitle, pmm.shotdescription, pmm.fulldescription, COALESCE(pms.productimages, 'default-product-image.png') AS prodimages, pms.sellmrp AS sellmrp, pms.dap AS paybleamount, pms.discountpercentage AS discount, pmm.maincategoryid, pmm.catid, pmm.subcategoryid, REPLACE(REPLACE(REPLACE(pmm.keyfeatures, '<ul><li>', ''), '</li></ul>', ''), '</li><li>', '^') AS keyfeatures, pm.companyname AS soldby, '4.8/5' AS sellerrating, COALESCE(pms.procurementsla, 0), COALESCE(pms.replacementday, 0), CAST(pms.shippingcharges AS DECIMAL(18, 2)), CAST(discountpercentage AS DECIMAL(18, 2)), COALESCE(pms.cashondelivery, 0), COALESCE(pms.weight_kg, 0), COALESCE(pms.length_cms, 0), COALESCE(pms.breadth_cms, 0), COALESCE(pms.height_cms, 0), pms.isoutofstock, (CASE WHEN COALESCE(CAST(pms.bv AS DECIMAL(18, 2)), 0) = 0 THEN ((COALESCE(CAST((pms.dap + (pms.dap * vc.vatpercvalue) / 100) AS DECIMAL(18, 2)), 0) * COALESCE(tsc.bvper, 0)) / 100) ELSE pms.bv END) AS bv, (CASE WHEN COALESCE(CAST(pms.activationpv_per AS DECIMAL(18, 2)), 0) = 0 THEN ((COALESCE(CAST((pms.dap + (pms.dap * vc.vatpercvalue) / 100) AS DECIMAL(18, 2)), 0) * COALESCE(tsc.activationpv_per, 0)) / 100) ELSE pms.activationpv_per END) AS activationpv, (CASE WHEN COALESCE(CAST(pms.pv AS DECIMAL(18, 2)), 0) = 0 THEN ((COALESCE(CAST((pms.dap + (pms.dap * vc.vatpercvalue) / 100) AS DECIMAL(18, 2)), 0) * COALESCE(tsc.redeemcashback_per, 0)) / 100) ELSE pms.pv END) AS pv, (CASE WHEN COALESCE(CAST(pms.cashback_per AS DECIMAL(18, 2)), 0) = 0 THEN ((COALESCE(CAST((pms.dap + (pms.dap * vc.vatpercvalue) / 100) AS DECIMAL(18, 2)), 0) * COALESCE(tsc.cashback_per, 0)) / 100) ELSE pms.cashback_per END) AS cashback, pmm.branchid, c.cityname, pms.specification, COALESCE(tsc.exchange, 0) AS exchange, COALESCE(tsc.return, 0) AS return, CAST(CEIL((pms.dap + (pms.dap * vc.vatpercvalue) / 100)) AS DECIMAL(18, 2)) AS includingtax, pms.prskucode, pms.activationpv_per, CASE WHEN offer.product_id IS NULL THEN 0 ELSE 1 END AS is_offer, CASE WHEN abp.abpid IS NULL THEN 0 ELSE 1 END AS is_affiliate, COALESCE(abp.is_active, 0) AS is_affiliate_enable FROM ims_masterproduct AS pmm INNER JOIN ims_subproduct AS pms ON pms.mprid = pmm.mprid INNER JOIN tbl_sub_category AS tsc ON tsc.subcatid = pmm.subcategoryid INNER JOIN portal_login AS br ON br.plid = pmm.branchid LEFT JOIN portal_master AS pm ON br.plid = pm.plid LEFT JOIN city AS c ON pm.ctid = c.ctid LEFT JOIN tbl_vat_categories AS vc ON pms.vatcategoryid = vc.vcid LEFT JOIN tbl_offer_on_product AS offer ON pms.sprid = offer.sprid LEFT JOIN affiliate_bonus_on_product AS abp ON abp.sprid = pms.sprid WHERE CAST(pms.sprid AS VARCHAR(100)) = v_prcode;
  END IF;
  RETURN QUERY SELECT * FROM tmp_tempprid;
  DROP TABLE IF EXISTS tmp_tempprid;
  -- SET option (removed)
END;
$$;


--
-- Name: usp_product_detailing_mobile(character varying, integer, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_product_detailing_mobile(v_prcode character varying DEFAULT '10144'::character varying, v_did integer DEFAULT 8, v_clid integer DEFAULT 0) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_sqlqueryfet text;
  v_sqlquery text;
  v_queryaddstringpmid VARCHAR(100);
  v_finalfetquery text;
  v_finalquery text;
  v_sellprice numeric(19,4);
  v_payableamt numeric(19,4);
  v_images text;
  v_discount numeric(19,4);
  v_sprid BIGINT;
  v_getloginid varchar(50);
  v_newprcode VARCHAR(100);
  v_rowcount INT;
  v_noofrec INT;
  v_diff INT;
  v_minindex INT;
  v_maxindex INT;
  v_count INT;
  v_searchtypeint INT;
  v_startfetind INT;
  v_endfetind INT;
  v_dynamicurl varchar(100);
  v_merchantproductlargeimage varchar(250);
  v_companyfacebooklink varchar(250);
  v_companygooglepluslink varchar(250);
  v_companytwitterlink varchar(250);
  v_companypinterestlink varchar(250);
  v_companylinkedinlink varchar(250);
BEGIN
  -- SET option (removed)
  v_queryaddstringpmid := '';
  v_getloginid := '';
  v_minindex := 0;
  v_maxindex := 0;
  v_count := 0;
  SELECT loginid INTO v_getloginid FROM tbl_customerlogin WHERE clid = v_clid;
  v_dynamicurl := '';
  v_merchantproductlargeimage := '';
  v_companyfacebooklink := '';
  v_companygooglepluslink := '';
  v_companytwitterlink := '';
  v_companypinterestlink := '';
  v_companylinkedinlink := '';
  SELECT companyredirect, companyredirect, companyredirect, companyredirect, companyredirect INTO v_companyfacebooklink, v_companygooglepluslink, v_companytwitterlink, v_companypinterestlink, v_companylinkedinlink FROM tbl_companysettings WHERE pmid = v_did;
  SELECT software_url INTO v_dynamicurl FROM tbl_company;
  DROP TABLE IF EXISTS tmp_tempprid;
  CREATE TEMP TABLE tmp_tempprid (MPRID BIGINT,
	SPRID BIGINT,
	NEWPRCODE VARCHAR(250),
	PRODTITLE VARCHAR(250),
	SHORTDESC text ,
	FULLDESC text,
	SELLMRP numeric(19,4),
	PAYBLEAMOUNT numeric(19,4),
	DISCOUNT numeric(19,4),
	MAINCATID INT,
	CATID INT,
	SUBCATID INT,
	SOLDBY VARCHAR(100),
	SELLERRATING VARCHAR(100),
	SHIPPINGCHARGES DECIMAL(18,2),
	DISCOUNTPERCENTAGE DECIMAL(18,2),
	CASHONDELIVERY boolean,
	ISOUTOFSTOCK boolean ,
	BV DECIMAL(18,2),
	PV DECIMAL(18,2),
	Plid bigint,
	wishproduct int,
	facebookURL VARCHAR(500),
	twitterURL VARCHAR(500),
	Googleplus VARCHAR(500),
	Pinterest VARCHAR(500),
	Linkedinlink VARCHAR(500),
	membercount int) ON COMMIT DROP;
  IF (v_did > 0) THEN
  INSERT INTO tmp_tempprid SELECT pmm.mprid, pms.sprid AS sprid, pmm.productcode, pmm.producttitle, pmm.shotdescription, pmm.fulldescription, pms.sellmrp AS sellmrp, pms.dap AS paybleamount, pms.discountpercentage AS discount, pmm.maincategoryid, pmm.catid, pmm.subcategoryid, pm.companyname AS soldby, '4.8/5' AS sellerrating, CAST(pms.shippingcharges AS DECIMAL(18, 2)), CAST(discountpercentage AS DECIMAL(18, 2)), COALESCE(pms.cashondelivery, 0) AS cashondelivery, pms.isoutofstock, COALESCE(dcs.bv, 0) AS bv, COALESCE(dcs.cashback, 0) AS cashback, pmm.branchid, (SELECT COALESCE(COUNT(1), 0) FROM tbl_wishlist WHERE sprid = pms.sprid AND loginid = v_clid AND status = 1) AS wishproduct, '' || v_companyfacebooklink || '/p/' || REPLACE(pmm.producttitle, ' ', '-') || '/' AS facebookurl, '' || v_companytwitterlink || '/p/' || REPLACE(pmm.producttitle, ' ', '-') || '/' AS twitterurl, '' || v_companygooglepluslink || '/p/' || REPLACE(pmm.producttitle, ' ', '-') || '/' AS googleplus, '' || v_companypinterestlink || '/p/' || REPLACE(pmm.producttitle, ' ', '-') || '/' AS pinterest, '' || v_companylinkedinlink || '/p/' || REPLACE(pmm.producttitle, ' ', '-') || '/' AS linkedinlink, 0 AS membercount FROM ims_masterproduct AS pmm INNER JOIN ims_subproduct AS pms ON pms.mprid = pmm.mprid INNER JOIN portal_login AS br ON br.plid = pmm.branchid LEFT JOIN portal_master AS pm ON br.plid = pm.plid LEFT OUTER JOIN tbl_sub_category AS tsb ON pmm.subcategoryid = tsb.subcatid LEFT OUTER JOIN tbl_distributor_commission_structure AS dcs ON dcs.subsubcatid = tsb.subcatid AND dcs.did = v_did WHERE CAST(pms.sprid AS VARCHAR(100)) = v_prcode;
  ELSE
  INSERT INTO tmp_tempprid SELECT pmm.mprid, pms.sprid AS sprid, pmm.productcode, pmm.producttitle, pmm.shotdescription, pmm.fulldescription, pms.sellmrp AS sellmrp, pms.dap AS paybleamount, pms.discountpercentage AS discount, pmm.maincategoryid, pmm.catid, pmm.subcategoryid, pm.companyname AS soldby, '4.8/5' AS sellerrating, CAST(pms.shippingcharges AS DECIMAL(18, 2)), CAST(discountpercentage AS DECIMAL(18, 2)), COALESCE(pms.cashondelivery, 0) AS cashondelivery, pms.isoutofstock, COALESCE(dcs.bv, 0) AS bv, COALESCE(dcs.cashback, 0) AS cashback, pmm.branchid, (SELECT COALESCE(COUNT(1), 0) FROM tbl_wishlist WHERE sprid = pms.sprid AND loginid = v_clid AND status = 1) AS wishproduct, '' || v_companyfacebooklink || '/p/' || REPLACE(pmm.producttitle, ' ', '-') || '/' AS facebookurl, '' || v_companytwitterlink || '/p/' || REPLACE(pmm.producttitle, ' ', '-') || '/' AS twitterurl, '' || v_companygooglepluslink || '/p/' || REPLACE(pmm.producttitle, ' ', '-') || '/' AS googleplus, '' || v_companypinterestlink || '/p/' || REPLACE(pmm.producttitle, ' ', '-') || '/' AS pinterest, '' || v_companylinkedinlink || '/p/' || REPLACE(pmm.producttitle, ' ', '-') || '/' AS linkedinlink, 0 AS membercount FROM ims_masterproduct AS pmm INNER JOIN ims_subproduct AS pms ON pms.mprid = pmm.mprid INNER JOIN portal_login AS br ON br.plid = pmm.branchid LEFT JOIN portal_master AS pm ON br.plid = pm.plid LEFT OUTER JOIN tbl_sub_category AS tsb ON pmm.subcategoryid = tsb.subcatid LEFT OUTER JOIN tbl_distributor_commission_structure AS dcs ON dcs.subsubcatid = tsb.subcatid AND dcs.did = v_did WHERE CAST(pms.sprid AS VARCHAR(100)) = v_prcode;
  END IF;
  RETURN QUERY SELECT * FROM tmp_tempprid;
  DROP TABLE IF EXISTS tmp_tempprid;
  -- SET option (removed)
END;
$$;


--
-- Name: usp_product_detailing_mobile_imageonly(character varying, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_product_detailing_mobile_imageonly(v_prcode character varying DEFAULT '2'::character varying, v_did integer DEFAULT 0) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_sqlqueryfet text;
  v_sqlquery text;
  v_queryaddstringpmid VARCHAR(100);
  v_finalfetquery text;
  v_finalquery text;
  v_sellprice numeric(19,4);
  v_payableamt numeric(19,4);
  v_images text;
  v_discount numeric(19,4);
  v_sprid BIGINT;
  v_newprcode VARCHAR(100);
  v_rowcount INT;
  v_noofrec INT;
  v_diff INT;
  v_minindex INT;
  v_maxindex INT;
  v_count INT;
  v_searchtypeint INT;
  v_startfetind INT;
  v_endfetind INT;
  v_imagedata text;
  v_mprid1 int;
  v_sprid1 int;
  v_ulr varchar(150);
  v_colorname varchar(150);
  v_sizename varchar(150);
  v_producttitle varchar(500);
  v_merchantproductlargeimage varchar(250);
BEGIN
  -- SET option (removed)
  v_queryaddstringpmid := '';
  v_minindex := 0;
  v_maxindex := 0;
  v_count := 0;
  DROP TABLE IF EXISTS tmp_tempprid;
  CREATE TEMP TABLE tmp_tempprid (MPRID BIGINT,
	SPRID BIGINT,
	PRODIMAGES text) ON COMMIT DROP;
  IF (v_did > 0) THEN
  INSERT INTO tmp_tempprid SELECT pmm.mprid, pms.sprid AS sprid, COALESCE(pms.productimages, 'default-product-image.png') AS prodimages FROM ims_masterproduct AS pmm INNER JOIN ims_subproduct AS pms ON pms.mprid = pmm.mprid LEFT JOIN portal_login AS br ON br.plid = pmm.branchid LEFT OUTER JOIN tbl_sub_category AS tsb ON pmm.subcategoryid = tsb.subcatid LEFT OUTER JOIN tbl_distributor_commission_structure AS dcs ON dcs.subsubcatid = tsb.subcatid AND dcs.did = v_did WHERE CAST(pms.sprid AS VARCHAR(100)) = v_prcode;
  ELSE
  INSERT INTO tmp_tempprid SELECT pmm.mprid, pms.sprid AS sprid, COALESCE(pms.productimages, 'default-product-image.png') AS prodimages FROM ims_masterproduct AS pmm INNER JOIN ims_subproduct AS pms ON pms.mprid = pmm.mprid LEFT JOIN portal_login AS br ON br.plid = pmm.branchid WHERE CAST(pms.sprid AS VARCHAR(100)) = v_prcode;
  END IF;
  DROP TABLE IF EXISTS tmp_temppridsplitstring;
  CREATE TEMP TABLE tmp_temppridsplitstring (MPRID BIGINT,
	SPRID BIGINT,
	PRODIMAGES text) ON COMMIT DROP;
  v_imagedata := '';
  v_mprid1 := 0;
  v_sprid1 := 0;
  SELECT mprid, sprid, prodimages INTO v_mprid1, v_sprid1, v_imagedata FROM tmp_tempprid;
  INSERT INTO tmp_temppridsplitstring SELECT v_mprid1 AS mprid, v_sprid1 AS sprid, * FROM SPLITSTRING(v_imagedata, '^');
  v_ulr := '';
  v_colorname := '';
  v_sizename := '';
  v_producttitle := '';
  v_merchantproductlargeimage := '';
  SELECT merchantimagepath, merchantproductlargeimage INTO v_ulr, v_merchantproductlargeimage FROM tbl_company;
  SELECT value INTO v_colorname FROM ims_masterproductattribute WHERE title = 'Color' AND sprid = v_mprid1;
  SELECT value INTO v_sizename FROM ims_masterproductattribute WHERE title = 'Size' AND sprid = v_mprid1;
  SELECT producttitle INTO v_producttitle FROM ims_masterproduct WHERE mprid = v_mprid1;
  IF (v_colorname <> '') THEN
  PERFORM dbo.usp_getproductspridbyattributes_mobile1(v_producttitle => v_producttitle, v_color => v_colorname, v_mprid => v_mprid1);
  END IF;
  RETURN QUERY SELECT ROW_NUMBER() OVER (ORDER BY mprid NULLS FIRST) AS rowno, v_merchantproductlargeimage AS productlargeimage, mprid, sprid, v_ulr AS baseurl, prodimages AS productimages, v_colorname AS color, v_sizename AS size FROM tmp_temppridsplitstring;
  DROP TABLE IF EXISTS tmp_temppridsplitstring;
  DROP TABLE IF EXISTS tmp_tempprid;
  -- SET option (removed)
END;
$$;


--
-- Name: usp_product_package_commission_settings(integer, integer, integer, numeric, numeric, numeric, numeric, integer, character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_product_package_commission_settings(v_maincatid integer DEFAULT 0, v_catid integer DEFAULT 0, v_subcatid integer DEFAULT 0, v_pack1 numeric DEFAULT 0, v_pack2 numeric DEFAULT 0, v_pack3 numeric DEFAULT 0, v_pack4 numeric DEFAULT 0, v_userid integer DEFAULT 1, INOUT v_result character varying DEFAULT ''::character varying) RETURNS character varying
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_actualcommission DECIMAL(18,2);
  v_actualpercentagepack1 DECIMAL(18,2);
  v_actualpercentagepack2 DECIMAL(18,2);
  v_actualpercentagepack3 DECIMAL(18,2);
  v_actualpercentagepack4 DECIMAL(18,2);
BEGIN
  -- BEGIN TRAN (removed)
  v_actualcommission := 0;
  v_actualpercentagepack1 := 0;
  v_actualpercentagepack2 := 0;
  v_actualpercentagepack3 := 0;
  v_actualpercentagepack4 := 0;
  IF (v_subcatid = 0) THEN
  v_result := 'DATA IS NOT EXISTS';
  RETURN;
  -- COMMIT (removed)
  END IF;
  SELECT COALESCE(admincharge, 0) INTO v_actualcommission FROM tbl_sub_category WHERE subcatid = v_subcatid;
  IF (v_maincatid <> 0 AND v_catid <> 0 AND v_subcatid <> 0) THEN
  v_actualpercentagepack1 := v_pack1;
  v_actualpercentagepack2 := v_pack2;
  v_actualpercentagepack3 := v_pack3;
  v_actualpercentagepack4 := v_pack4;
  IF NOT EXISTS(SELECT 1 FROM tbl_prodouct_packagewise_commission WHERE maincatid = v_maincatid AND cattid = v_catid AND subcatid = v_subcatid) THEN
  INSERT INTO tbl_prodouct_packagewise_commission (maincatid, cattid, subcatid, admincommissison, actualcommpackage1, actualcommpackage2, actualcommpackage3, actualcommpackage4, packagecommision1, packagecommision2, packagecommision3, packagecommision4, active, createdate, createdby, updatedate, updatedby) VALUES (v_maincatid, v_catid, v_subcatid, v_actualcommission, v_actualpercentagepack1, v_actualpercentagepack2, v_actualpercentagepack3, v_actualpercentagepack4, v_pack1, v_pack2, v_pack3, v_pack4, 1, dbo.FUN_GETCURRENTDATE(), v_userid, dbo.FUN_GETCURRENTDATE(), v_userid);
  v_result := '1';
  ELSE
  INSERT INTO tbl_prodouct_packagewise_commission_history SELECT * FROM tbl_prodouct_packagewise_commission WHERE maincatid = v_maincatid AND cattid = v_catid AND subcatid = v_subcatid;
  UPDATE tbl_prodouct_packagewise_commission SET actualcommpackage1 = v_actualpercentagepack1, actualcommpackage2 = v_actualpercentagepack2, actualcommpackage3 = v_actualpercentagepack3, actualcommpackage4 = v_actualpercentagepack4, packagecommision1 = v_pack1, packagecommision2 = v_pack2, packagecommision3 = v_pack3, packagecommision4 = v_pack4, updatedate = dbo.FUN_GETCURRENTDATE(), updatedby = v_userid WHERE maincatid = v_maincatid AND cattid = v_catid AND subcatid = v_subcatid;
  v_result := '2';
  END IF;
  END IF;
  -- COMMIT (removed)
  IF (0 <> 0) THEN
  PERFORM dbo.sp_errorlog();
  v_result := 'ERROR IN REQUEST';
  -- ROLLBACK (removed)
  END IF;
END;
$$;


--
-- Name: usp_productcategary(integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_productcategary(v_mode integer DEFAULT 2) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_totalcount INT;
  v_count INT;
  v_value VARCHAR(100);
BEGIN
  v_totalcount := 0;
  v_count := 1;
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp ON COMMIT DROP AS SELECT ROW_NUMBER() OVER (ORDER BY pmid NULLS FIRST) AS id, catid FROM portal_master WHERE active = 1 AND COALESCE(isverified, 0) = 1;
  SELECT COUNT(1) INTO v_totalcount FROM tmp_temp;
  DROP TABLE IF EXISTS tmp_temp1;
  CREATE TEMP TABLE tmp_temp1 (VALUE INT) ON COMMIT DROP;
  WHILE (v_totalcount >= v_count) LOOP
  v_value := '';
  SELECT catid INTO v_value FROM tmp_temp WHERE id = v_count;
  INSERT INTO tmp_temp1 SELECT value FROM SPLITSTRINGBYCOMMA(v_value);
  v_count := v_count + 1;
  END LOOP;
  RETURN QUERY SELECT (catid) AS kmid, (catname) AS keywordname FROM product_category WHERE catactive = 1 AND categoryrelatedto = v_mode AND catid IN (SELECT value FROM tmp_temp1 GROUP BY value);
  DROP TABLE IF EXISTS tmp_temp;
  DROP TABLE IF EXISTS tmp_temp1;
END;
$$;


--
-- Name: usp_productcategory(character varying, boolean, character varying, integer, character varying, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_productcategory(v_catname character varying DEFAULT ''::character varying, v_catstatus boolean DEFAULT NULL::boolean, v_catimage character varying DEFAULT ''::character varying, v_catid integer DEFAULT 0, v_mode character varying DEFAULT ''::character varying, INOUT v_intresult integer DEFAULT NULL::integer) RETURNS integer
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_temp int;
  v_order int;
BEGIN
  v_temp := 0;
  v_order := 0;
  IF (v_mode = 'update') THEN
  v_intresult := 1;
  UPDATE product_category SET catname = v_catname, catactive = v_catstatus WHERE catid = v_catid;
  UPDATE tbl_searching_panel SET categoryname = v_catname WHERE catid = v_catid;
  UPDATE tbl_freeaccountsearching_panel SET categoryname = v_catname WHERE catid = v_catid;
  IF (v_catimage <> '') THEN
  UPDATE product_category SET catimgname = v_catimage WHERE catid = v_catid;
  ELSE
  v_intresult := 1;
  UPDATE product_category SET catname = v_catname, catactive = v_catstatus WHERE catid = v_catid;
  UPDATE tbl_freeaccountsearching_panel SET categoryname = v_catname WHERE catid = v_catid;
  UPDATE tbl_searching_panel SET categoryname = v_catname WHERE catid = v_catid;
  END IF;
  END IF;
  IF (v_mode = 'save') THEN
  IF EXISTS(SELECT catname FROM product_category WHERE catname = v_catname AND catactive = 1) THEN
  v_intresult := 0;
  RETURN;
  ELSE
  v_intresult := 1;
  INSERT INTO product_category (catname, catactive, catimgname) VALUES (v_catname, v_catstatus, v_catimage);
  END IF;
  IF (0 <> 0) THEN
  v_intresult := 2;
  RETURN;
  END IF;
  END IF;
END;
$$;


