-- Name: usp_profilekycrejectiondetails(integer, integer, integer, text, text, text, integer, integer, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_profilekycrejectiondetails(v_mode integer DEFAULT 0, v_startrowindex integer DEFAULT 1, v_maxrows integer DEFAULT 100, v_regno text DEFAULT ''::text, v_type text DEFAULT ''::text, v_description text DEFAULT ''::text, v_userid integer DEFAULT 0, v_kyctype integer DEFAULT 1, v_intresult integer DEFAULT 0) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
BEGIN
  -- SET option (removed)
  IF (v_mode = 1) THEN
  INSERT INTO tbl_profilekycrejectiondetails (regno, type, date, description, status, userid, kyctype) VALUES (v_regno, v_type, dbo.FUN_GETCURRENTDATE(), v_description, 1, v_userid, v_kyctype);
  v_intresult := 1;
  END IF;
  IF (v_mode = 2) THEN
  RETURN QUERY SELECT tp.*, username FROM tbl_profilekycrejectiondetails AS tp INNER JOIN tbluser ON tp.userid = tbluser.userid WHERE regno = v_regno AND kyctype = v_kyctype ORDER BY date DESC NULLS LAST;
  END IF;
  IF (v_mode = 3) THEN
  RETURN QUERY SELECT CAST(TO_CHAR(activitydate, 'DD TMMon YYYY') AS VARCHAR(200)) AS date, CASE WHEN plh.highestqualification = 0 THEN 'N/A' ELSE ql.name END AS qualifiction, plh.* FROM portal_login_history AS plh LEFT JOIN tblqualification AS ql ON (ql.qid = plh.highestqualification) WHERE plid = v_regno ORDER BY activitydate DESC NULLS LAST;
  END IF;
  -- SET option (removed)
END;
$$;


--
-- Name: usp_promosandadvertisementdetails(integer, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_promosandadvertisementdetails(v_mode integer DEFAULT 0, v_plid integer DEFAULT 0) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF (v_mode = 1) THEN
  RETURN QUERY SELECT COALESCE(maxnoofclicksperdayforview, 0) AS maxnoofclicksperdayforview, COALESCE(maxnooflinkperdayforshare, 0) AS asmaxnooflinkperdayforshare, COALESCE(maxnoofblogperday, 0) AS maxnoofblogperday, COALESCE(maxnoofclassifiedperday, 0) AS maxnoofclassifiedperday, COALESCE(maxnoofbusinesslistingperday, 0) AS maxnoofbusinesslistingperday FROM tbl_datewisecommonroiaccount WHERE CAST(date AS DATE) = CAST(CURRENT_TIMESTAMP AS DATE);
  END IF;
  IF (v_mode = 2) THEN
  IF (v_plid <> 0) THEN
  RETURN QUERY SELECT COALESCE(totalclicked, 0) AS totalclicked, COALESCE(totalshared, 0) AS totalshared, COALESCE(submittednoofblog, 0) AS submittednoofblog, COALESCE(submittednoofclassified, 0) AS submittednoofclassified, COALESCE(submittednoofbusinesslisting, 0) AS submittednoofbusinesslisting FROM tbl_dailytasklimits WHERE CAST(date AS DATE) = CAST(CURRENT_TIMESTAMP AS DATE) AND plid = 7714;
  ELSE
  RETURN QUERY SELECT 0 AS totalclicked, 0 AS totalshared, 0 AS submittednoofblog, 0 AS submittednoofclassified, 0 AS submittednoofbusinesslisting FROM tbl_dailytasklimits WHERE CAST(date AS DATE) = CAST(CURRENT_TIMESTAMP AS DATE) AND plid = v_plid;
  END IF;
  END IF;
  IF (v_mode = 3) THEN
  RETURN QUERY SELECT limits, caption FROM settings WHERE caption = 'Max-No-Of-Click-Per-Day' OR caption = 'Max-No-Of-Share-Per-Day';
  END IF;
END;
$$;


--
-- Name: usp_purchase_package(integer, integer, integer, integer, numeric, numeric, integer, character varying, character varying, character varying, character varying, character varying, character varying, character varying, character varying, integer, numeric, numeric); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_purchase_package(v_mode integer DEFAULT 1, v_resellerid integer DEFAULT 0, v_serviceid integer DEFAULT 0, v_packageid integer DEFAULT 0, v_amount numeric DEFAULT 0, v_discount numeric DEFAULT 0, v_paymode integer DEFAULT 0, v_ifsccode character varying DEFAULT ''::character varying, v_branchaddress character varying DEFAULT ''::character varying, v_bankname character varying DEFAULT ''::character varying, v_referencename character varying DEFAULT ''::character varying, v_date character varying DEFAULT ''::character varying, v_commentremark character varying DEFAULT ''::character varying, v_challanimage character varying DEFAULT ''::character varying, INOUT v_strresult character varying DEFAULT ''::character varying, v_trppbaid integer DEFAULT 0, v_gstamount numeric DEFAULT 0, v_totalamount numeric DEFAULT 0) RETURNS character varying
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_invoiceno VARCHAR(100);
  v_currentyear VARCHAR(100);
  v_nextyear VARCHAR(100);
  v_countno VARCHAR(100);
  v_invoicecode VARCHAR(10);
  v_lastdigit INT;
  v_packagename VARCHAR(100);
  v_packageamount DECIMAL(18,2);
  v_gstpercentage DECIMAL(18,2);
  v_did INT;
BEGIN
  -- BEGIN TRAN (removed)
  v_invoiceno := '';
  v_invoicecode := 'PP';
  v_lastdigit := 0;
  v_packagename := '';
  v_packageamount := 0;
  v_gstpercentage := 0;
  v_did := 0;
  IF (v_mode = 1) THEN
  SELECT COALESCE(plid, 0) INTO v_did FROM distributor_master WHERE pmid = v_resellerid;
  IF EXISTS(SELECT 1 FROM tbl_resellerpurchasedpackages_by_admin WHERE did = v_did AND active = 1 AND stid = v_serviceid) THEN
  UPDATE tbl_resellerpurchasedpackages_by_admin SET active = 0 WHERE did = v_did;
  END IF;
  INSERT INTO tbl_resellerpurchasedpackages_by_admin (did, stid, trpid, amount, discount, pmoid, bankname, branchname, challanimage, referenceno, referencedate, ifsccode, purchasedate, remarks, createddate, active, gstamount, totalamount) VALUES (v_did, v_serviceid, v_packageid, v_amount, v_discount, v_paymode, v_bankname, v_branchaddress, v_challanimage, v_referencename, v_date, v_ifsccode, dbo.FUN_GETCURRENTDATE(), v_commentremark, dbo.FUN_GETCURRENTDATE(), 1, v_gstamount, v_totalamount);
  SELECT RIGHT(CAST(EXTRACT(YEAR FROM CAST(dbo.FUN_GETCURRENTDATE() AS DATE)) AS TEXT), 2), RIGHT(CAST(EXTRACT(YEAR FROM CAST(dbo.FUN_GETCURRENTDATE() AS DATE)) AS TEXT), 2) + 1 INTO v_currentyear, v_nextyear;
  SELECT COALESCE(MAX(invoicecode), 0) INTO v_countno FROM tbl_reseller_package_invoice WHERE status = 1;
  v_countno := v_countno || 1;
  v_lastdigit := v_countno;
  v_currentyear := RIGHT(CAST(v_currentyear AS TEXT), 2);
  v_nextyear := RIGHT(CAST(v_nextyear AS TEXT), 2);
  SELECT RIGHT(CAST('000000' || CAST(v_countno AS VARCHAR(6)) AS TEXT), 6) INTO v_countno;
  v_invoiceno := v_invoicecode || '/' || v_currentyear || '-' || v_nextyear || '/' || v_countno;
  SELECT COALESCE(limits, 0) INTO v_gstpercentage FROM settings WHERE caption = 'GST PERCENTAGE';
  SELECT COALESCE(packagename, ''), COALESCE(packageamount, 0) INTO v_packagename, v_packageamount FROM tbl_reseller_packages WHERE trpid = v_packageid;
  IF EXISTS(SELECT 1 FROM tbl_reseller_package_invoice WHERE did = v_did AND status = 1 AND trsid = v_serviceid) THEN
  UPDATE tbl_reseller_package_invoice SET status = 0 WHERE did = v_did AND trsid = v_serviceid;
  END IF;
  INSERT INTO dbo.tbl_reseller_package_invoice (did, transactionid, invoicenumber, invoicename, packagename, amount, gstpercentage, gstamount, totalamount, paymode, status, invoicecode, invoicedate, packageid, discount, trsid) VALUES (v_did, '', v_invoiceno, 'IN' || v_countno || '.pdf', v_packagename, v_packageamount, v_gstpercentage, (v_packageamount * v_gstpercentage) / 100, (((v_packageamount + ((v_packageamount * v_gstpercentage) / 100)) - (v_packageamount * v_discount) / 100)), v_paymode, 1, v_lastdigit, dbo.FUN_GETCURRENTDATE(), v_packageid, ((v_packageamount * v_discount) / 100), v_serviceid);
  IF NOT EXISTS(SELECT 1 FROM tbl_reseller_purchased_packages WHERE did = v_did AND trsid = v_serviceid) THEN
  INSERT INTO tbl_reseller_purchased_packages (did, trpid, purchaseddate, active, createdate, status, invoiceno, trsid) VALUES (v_did, v_packageid, v_date, 1, dbo.FUN_GETCURRENTDATE(), 1, v_invoiceno, v_serviceid);
  ELSE
  INSERT INTO tbl_reseller_purchased_packages_history (trpphid, did, trpid, purchaseddate, active, createdate, status, invoiceno, historydate) (SELECT trppid, did, trpid, purchaseddate, active, createdate, status, invoiceno, dbo.FUN_GETCURRENTDATE() FROM tbl_reseller_purchased_packages WHERE did = v_did AND trsid = v_serviceid);
  UPDATE tbl_reseller_purchased_packages SET trpid = v_packageid, purchaseddate = v_date, invoiceno = v_invoiceno WHERE did = v_did AND trsid = v_serviceid;
  END IF;
  v_strresult := '1';
  END IF;
  IF (0 <> 0) THEN
  v_strresult := 'ERROR OCCURRED. PLEASE TRY LATER';
  -- ROLLBACK (removed)
  RETURN;
  END IF;
  -- COMMIT (removed)
END;
$$;


--
-- Name: usp_purchase_package_invoice(character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_purchase_package_invoice(v_invoiceno character varying DEFAULT 'PP/19-20/000006'::character varying) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
BEGIN
  RETURN QUERY SELECT ROW_NUMBER() OVER (ORDER BY rpi.rpid NULLS FIRST) AS rownumber, rpi.rpid, rpi.did, COALESCE(rpi.transactionid, 'N/A') AS transactionid, rpi.invoicenumber, rpi.packagename, rpi.amount, rpi.gstamount, rpi.gstpercentage, rpi.totalamount, rpi.paymode, CAST(rpi.invoicedate AS VARCHAR(30)) AS invoicedate, COALESCE(dm.companyname, '') AS companyname, COALESCE(dm.address, '') AS address, td.phone, td.emailid, COALESCE(c.cityname, '') AS cityname, dm.pincode, COALESCE(rpi.discount, 0) AS discount, COALESCE(dm.companyimage, 'No-logo.png') AS brandlogo, COALESCE(dm.companydetailname, '') AS companyfullname FROM tbl_reseller_package_invoice AS rpi LEFT JOIN distributor_master AS dm ON rpi.did = dm.plid LEFT JOIN tbl_distributor AS td ON rpi.did = td.did LEFT JOIN city AS c ON dm.ctid = c.ctid WHERE rpi.invoicenumber = v_invoiceno AND rpi.status = 1;
END;
$$;


--
-- Name: usp_purchase_package_invoice_reseller_history(character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_purchase_package_invoice_reseller_history(v_invoiceno character varying DEFAULT ''::character varying) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
BEGIN
  RETURN QUERY SELECT ROW_NUMBER() OVER (ORDER BY rpi.rpid NULLS FIRST) AS rownumber, rpi.rpid, rpi.did, COALESCE(rpi.transactionid, 'N/A') AS transactionid, rpi.invoicenumber, rpi.packagename, rpi.amount, rpi.gstamount, rpi.gstpercentage, rpi.totalamount, rpi.paymode, CAST(rpi.invoicedate AS VARCHAR(30)) AS invoicedate, COALESCE(dm.companyname, '') AS companyname, COALESCE(dm.address, '') AS address, td.phone, td.emailid, COALESCE(c.cityname, '') AS cityname, dm.pincode, COALESCE(rpi.discount, 0) AS discount FROM tbl_reseller_package_invoice AS rpi LEFT JOIN distributor_master AS dm ON rpi.did = dm.plid LEFT JOIN tbl_distributor AS td ON rpi.did = td.did LEFT JOIN city AS c ON dm.ctid = c.ctid WHERE rpi.invoicenumber = v_invoiceno;
END;
$$;


--
-- Name: usp_purchase_voucher(integer, integer, character varying, character varying, text, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_purchase_voucher(v_startrowindex integer DEFAULT 1, v_maxrows integer DEFAULT 1000, v_searchfield character varying DEFAULT ''::character varying, v_searchvalue character varying DEFAULT ''::character varying, v_rolename text DEFAULT ''::text, INOUT v_totalcount integer DEFAULT 0) RETURNS integer
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_minindex INT;
  v_maxindex INT;
  v_query text;
BEGIN
  v_minindex := (v_startrowindex - 1) * v_maxrows + 1;
  v_maxindex := v_startrowindex * v_maxrows;
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp (ROWNUMBER INT,

LoginId INT,
OrderId VARCHAR(100),
OrderDateTime VARCHAR(200),
DenoMination VARCHAR(50),

 OrderAmount numeric(19,4),
 OrderQty int,
 Mobile VARCHAR(10),
 EMAILID VARCHAR(100),
 STATUS VARCHAR(20),
 USERNAME varchar(20)) ON COMMIT DROP;
  v_query := 'INSERT INTO #TEMP SELECT ROW_NUMBER() OVER (ORDER BY  VOM.LOGINID ASC) as ROWNO, VOM.OrderDateTime,VOM.OrderAmount,VOM.OrderQty,VOM.MOBILE,VOM.EMAILID,VOM.OrderId,
 VOM.DenoMinaNtion,VOM.Status,CL.USERNAME

  FROM TBL_VOUCHER_ORDER_MASTER VOM 
left JOIN tbl_customerlogin CL ON VOM.LOGINID=CL.LOGINID';
END;
$$;


--
-- Name: usp_pv_admin_clubhistory_list(integer, integer, character varying, character varying, character varying, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_pv_admin_clubhistory_list(v_startrowindex integer DEFAULT 1, v_maxrows integer DEFAULT 100, v_fromdate character varying DEFAULT ''::character varying, v_todate character varying DEFAULT ''::character varying, v_resellername character varying DEFAULT ''::character varying, v_totalrecord integer DEFAULT 0) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_query text;
  v_maxregno text;
  v_query1 text;
  v_minindex INT;
  v_maxindex INT;
  v_count INT;
  v_totalcount INT;
  v_chid INT;
  v_totoalcancelamount DECIMAL(18,2);
BEGIN
  -- SET option (removed)
  v_query := '';
  v_maxregno := '';
  v_query1 := '';
  v_count := 1;
  v_totalcount := 0;
  v_chid := 0;
  v_minindex := (v_startrowindex - 1) * v_maxrows + 1;
  v_maxindex := v_startrowindex * v_maxrows;
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp (ROWNUMBER BIGINT,
	  CHID BIGINT,
	  FILENAME VARCHAR(150),
	  DATE timestamp,
	  CLUBGROUP VARCHAR(150),
	  TOTALREQUEST INT,
	  TOTALAMOUNT DECIMAL(18,8),
	  PROCESSDATE timestamp,
	  PROCESSBY VARCHAR(50),
	  PROCESSSTATUS VARCHAR(50),
	  PROCESSIPADDRESS VARCHAR(50),
	  DateRanage Varchar(100),
	  COMPANYNAME VARCHAR(100)) ON COMMIT DROP;
  v_query := 'INSERT INTO #TEMP SELECT ROW_NUMBER()OVER(ORDER BY TRCPC.CHID DESC) AS ROWNUMBER,TRCPC.CHID,TRCPC.FILENAME,CONVERT(DATE,TRCPC.DATE,105) AS DATE,
TRCPC.CLUBGROUP,TRCPC.TOTALREQUEST,ISNULL(TRCPC.TOTALAMOUNT,0),
CONVERT(DATE,TRCPC.PROCESSDATE,105) AS PROCESSDATE,TRCPC.PROCESSBY,
(CASE WHEN TRCPC.PROCESSSTATUS=0  THEN ''Pending'' WHEN TRCPC.PROCESSSTATUS=1 THEN ''Distributed'' WHEN TRCPC.PROCESSSTATUS=2 THEN ''Cancelled'' END),
TRCPC.PROCESSIPADDRESS,TRCPC.DATERANAGE,ISNULL(DM.COMPANYNAME,'''') 
FROM TBL_RESELLERWISE_CUSTOMER_PVCLUBHISTORY TRCPC   
LEFT JOIN DISTRIBUTOR_MASTER DM ON TRCPC.DID=DM.PLID
WHERE 1=1 ';
  IF (v_resellername <> '') THEN
  v_query := v_query || ' And DM.COMPANYNAME=''' || CAST(v_resellername AS VARCHAR(30)) || '''';
  END IF;
  RAISE NOTICE '%', v_query;
  EXECUTE v_query;
  SELECT COUNT(1) INTO v_totalcount FROM tmp_temp;
  SELECT COALESCE(COUNT(1), 0) INTO v_totalrecord FROM tmp_temp;
  RETURN QUERY SELECT * FROM tmp_temp ORDER BY rownumber ASC NULLS FIRST;
  DROP TABLE IF EXISTS tmp_temp;
  -- SET option (removed)
END;
$$;


--
-- Name: usp_pv_club_history_resellerwise(integer, integer, character varying, character varying, character varying, character varying, integer, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_pv_club_history_resellerwise(v_startrowindex integer DEFAULT 1, v_maxrows integer DEFAULT 1000, v_fromdate character varying DEFAULT ''::character varying, v_todate character varying DEFAULT ''::character varying, v_searchfield character varying DEFAULT ''::character varying, v_searchvalue character varying DEFAULT ''::character varying, v_did integer DEFAULT 2, v_orderstatus integer DEFAULT 0) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_query text;
  v_maxregno text;
  v_query1 text;
  v_getcount INT;
  v_getwdid text;
  v_getplid BIGINT;
  v_getusername VARCHAR(100);
  v_totalrequest INT;
  v_totalamount DECIMAL(18,8);
  v_total_tansaction DECIMAL(18,8);
  v_getallcubeallwdid text;
  v_getseparatewdid text;
  v_getmaxchid INT;
  v_getaccountno VARCHAR(50);
  v_getaccountholdername VARCHAR(50);
  v_getbankname VARCHAR(50);
  v_getbranchname VARCHAR(50);
  v_getifsccode VARCHAR(50);
  v_getnetamount DECIMAL(18,8);
  v_mindate varchar(100);
  v_maxdate varchar(100);
  v_dateranage Varchar(100);
  v_getfilename VARCHAR(50);
  v_getclubgroup VARCHAR(50);
  v_getrandom1 VARCHAR(50);
  v_getrandom2 VARCHAR(50);
  v_getrandom3 VARCHAR(50);
  v_getmergrandom VARCHAR(50);
  v_getupdatestatus text;
BEGIN
  -- SET option (removed)
  v_query := '';
  v_maxregno := '';
  v_query1 := '';
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp (ROWNUMBER INT GENERATED BY DEFAULT AS IDENTITY,
 CLID INT,
 CUSTOMERNAME VARCHAR(100),
 MOBILENO VARCHAR(100),
 DATE VARCHAR(100),
 PVPERCNTAGE DECIMAL(18,2),
 PV DECIMAL(18,2),
 ORDERID VARCHAR(100),
 ORDERNO VARCHAR(100),
 ORDERSTATUS INT,
 ORDERDERCYCLESTATUS VARCHAR(100),
 BENIFICARYID VARCHAR(100),
 TYPE VARCHAR(100)) ON COMMIT DROP;
  v_query := ' INSERT INTO #TEMP SELECT CL.CLID,(CL.FNAME+'' ''+CL.LNAME) AS NAME,CL.PHONE,CONVERT(VARCHAR,TRBVM.CREATE_DATE,106) AS DATE, 
ISNULL(TRBVD.PVPERCENTAGE,0),ISNULL(TRBVD.PVALUE,0) ,ISNULL(TRBVM.ORDERID,''N/A''),ISNULL(TRBVD.ORDERNO,''N/A''),
ISNULL(POM.INTSTATUS,0),(CASE WHEN POM.INTSTATUS=0 THEN ''Pending'' WHEN POM.INTSTATUS=2 THEN ''Packed'' WHEN POM.INTSTATUS=3 THEN ''Ready for Dispatch'' 
WHEN POM.INTSTATUS=4 THEN ''Shipped'' WHEN POM.INTSTATUS=5 THEN ''Shipped'' WHEN POM.INTSTATUS=6 THEN ''Completed'' WHEN POM.INTSTATUS=7 THEN ''Cancel''
 WHEN POM.INTSTATUS=9 THEN ''Out for Delivery'' END),
ISNULL(TRUN.USERNAME,''N/A''),ISNULL(TRS.SERVICENAME,''N/A'')
FROM TBL_RESELLER_BV_PV_MASTER TRBVM  
LEFT JOIN TBL_RESELLER_BV_PV_DETAILS TRBVD ON TRBVM.COMID=TRBVD.COMID
LEFT JOIN TBL_PRODUCT_ORDER_MASTER POM ON  TRBVD.ORDERNO=POM.ORDERNO
LEFT JOIN TBL_CUSTOMERLOGIN CL ON POM.LOGINID=CL.LOGINID
LEFT JOIN TBL_RESELLER_SERVICES TRS ON TRBVD.TYPE=TRS.TRSID
LEFT JOIN TBL_REFERENCEUSERNAME TRUN ON CL.CLID=TRUN.CLID AND TRUN.STATUS=1
WHERE TRBVM.DID=''' || CAST(v_did AS VARCHAR(30)) || ''' and TRBVD.RELEASED_PVSTATUS=0 ';
  IF ((v_fromdate <> '') AND (v_todate = '')) THEN
  v_query := v_query || ' AND CONVERT(DATE, TRBVM.CREATE_DATE) =  CONVERT(DATE, ''' || v_fromdate || ''')';
  END IF;
  IF ((v_fromdate = '') AND (v_todate <> '')) THEN
  v_query := v_query || ' AND CONVERT(DATE, TRBVM.CREATE_DATE) =  CONVERT(DATE, ''' || v_todate || ''') ';
  END IF;
  IF ((v_fromdate <> '') AND (v_todate <> '')) THEN
  v_query := v_query || ' AND CONVERT(DATE, TRBVM.CREATE_DATE) BETWEEN CONVERT(DATE, ''' || v_fromdate || ''') AND  CONVERT(DATE, ''' || v_todate || ''') ';
  END IF;
  IF (v_searchfield <> '' AND v_searchvalue <> '') THEN
  IF (v_searchfield = 'FULLNAME') THEN
  v_query := v_query || ' AND (CL.FANME+''''+CL.LNAME)=' || CAST(v_searchvalue AS VARCHAR(30)) || '';
  END IF;
  IF (v_searchfield = 'PHONE') THEN
  v_query := v_query || ' AND CL.PHONE=''' || CAST(v_searchvalue AS VARCHAR(30)) || '''';
  END IF;
  IF (v_searchfield = 'BENEFICIARYID') THEN
  v_query := v_query || ' AND TRUN.USERNAME=''' || CAST(v_searchvalue AS VARCHAR(30)) || '''';
  END IF;
  IF (v_searchfield = 'ORDERID') THEN
  v_query := v_query || ' AND TRBVM.ORDERID=''' || CAST(v_searchvalue AS VARCHAR(30)) || '''';
  END IF;
  END IF;
  IF (v_orderstatus <> '') THEN
  v_query := v_query || ' AND POM.INTSTATUS=''' || CAST(v_orderstatus AS VARCHAR(30)) || '''';
  END IF;
  EXECUTE v_query;
  RAISE NOTICE '%', v_query;
  EXECUTE v_query;
  DROP TABLE IF EXISTS tmp_temp1;
  CREATE TEMP TABLE tmp_temp1 (ROWNUMBER BIGINT,
	  USERNAME VARCHAR(150),
	  CLID INT,
	  CUSTOMERNAME varchar(100),
	  Orderno Varchar(100),
	  PV DECIMAL(18,8),
	  MOBILE VARCHAR(100),
	  Date Varchar(100),
	  Orderid varchar(100),
	  TYPE VARCHAR(100)) ON COMMIT DROP;
  v_query1 := 'INSERT INTO #TEMP1 SELECT ROW_NUMBER()OVER(ORDER BY (SELECT(1))) AS ROWNUMBER,
	TM.BENIFICARYID,TM.CLID,TM.CUSTOMERNAME,TM.ORDERNO,TM.PV,TM.MOBILENO,CONVERT(Varchar,Tm.DATE,106),
	TM.ORDERID,TM.TYPE FROM #TEMP TM
	 GROUP BY TM.BENIFICARYID,TM.ORDERNO,TM.CLID,TM.CUSTOMERNAME,TM.PV,TM.MOBILENO,Tm.DATE,TM.ORDERID,TM.TYPE ';
  EXECUTE v_query1;
  RAISE NOTICE '%', v_query1;
  v_getcount := 0;
  v_getwdid := '';
  v_getplid := 0;
  v_getusername := '';
  v_totalrequest := 0;
  v_totalamount := 0;
  v_total_tansaction := 0;
  v_getallcubeallwdid := '';
  v_getseparatewdid := '';
  v_getmaxchid := 0;
  v_getaccountno := '';
  v_getifsccode := '';
  v_getnetamount := 0;
  v_mindate := '';
  v_maxdate := '';
  v_dateranage := '';
  SELECT COALESCE(MAX(chid), 0) + 1 INTO v_getmaxchid FROM tbl_resellerwise_customer_pvclubhistory;
  SELECT COUNT(1) INTO v_getcount FROM tmp_temp1;
  SELECT SUM(pv) INTO v_totalamount FROM tmp_temp1;
  v_totalrequest := v_getcount;
  SELECT COUNT(1) INTO v_getcount FROM tmp_temp1;
  SELECT COUNT(DISTINCT username) INTO v_total_tansaction FROM tmp_temp1;
  SELECT MIN(date) INTO v_mindate FROM tmp_temp;
  SELECT MAX(date) INTO v_maxdate FROM tmp_temp;
  v_dateranage := v_mindate || ' To ' || v_maxdate;
  WHILE (v_getcount > 0) LOOP
  SELECT username, pv, orderno, customername INTO v_getusername, v_getnetamount, v_getplid, v_getaccountholdername FROM tmp_temp1 WHERE rownumber = v_getcount;
  SELECT COALESCE(v_getseparatewdid || ',', '') || CAST(comdid AS VARCHAR) INTO v_getseparatewdid FROM tbl_reseller_bv_pv_details WHERE orderno = v_getplid AND released_pvstatus = 0 LIMIT 10000;
  INSERT INTO tbl_resellerwise_customer_download_pvclubdata VALUES (v_getmaxchid, v_getaccountholdername, v_getnetamount, '0', '', '', '', v_getseparatewdid);
  v_getallcubeallwdid := v_getallcubeallwdid || v_getseparatewdid;
  v_getseparatewdid := '';
  v_getcount := v_getcount - 1;
  END LOOP;
  v_getfilename := '';
  v_getclubgroup := '';
  v_getrandom1 := '';
  v_getrandom2 := '';
  v_getrandom3 := '';
  v_getmergrandom := '';
  SELECT CAST(REPLACE(RANDOM(), '.', '') AS VARCHAR(50)) INTO v_getrandom1;
  SELECT CAST(REPLACE(RANDOM(), '.', '') AS VARCHAR(50)) INTO v_getrandom2;
  SELECT CAST(REPLACE(RANDOM(), '.', '') AS VARCHAR(50)) INTO v_getrandom3;
  v_getmergrandom := v_getrandom1 || v_getrandom3;
  v_getfilename := v_getmergrandom;
  v_getclubgroup := v_getrandom1 || v_getrandom3 || v_getrandom2;
  INSERT INTO tbl_resellerwise_customer_pvclubhistory VALUES (v_getfilename, dbo.FUN_GETCURRENTDATE(), v_getclubgroup, v_totalrequest, v_totalamount, v_total_tansaction, dbo.FUN_GETCURRENTDATE(), v_did, 0, '', v_getallcubeallwdid, v_did, v_dateranage, 0);
  v_getupdatestatus := '';
  v_getupdatestatus := 'UPDATE TBL_RESELLER_BV_PV_DETAILS SET RELEASED_PVSTATUS=3 WHERE COMDID IN  (SELECT * FROM SPLITSTRING(''' || v_getallcubeallwdid || ''','',''))';
  EXECUTE v_getupdatestatus;
  RETURN QUERY SELECT v_getfilename AS filename, * FROM tmp_temp1 ORDER BY rownumber ASC NULLS FIRST;
  DROP TABLE IF EXISTS tmp_temp;
  DROP TABLE IF EXISTS tmp_temp1;
  -- SET option (removed)
END;
$$;


--
-- Name: usp_pv_distributed(integer, integer, integer, character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_pv_distributed(v_mode integer DEFAULT 1, v_comdid integer DEFAULT 2, v_status integer DEFAULT 1, v_groupno character varying DEFAULT ''::character varying) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_value Varchar(100);
  v_prefix varchar(2);
BEGIN
  -- BEGIN TRAN (removed)
  -- SET option (removed)
  v_value := '';
  v_prefix := ',';
  IF (v_mode = 1) THEN
  v_value := v_prefix || (CAST(v_comdid AS VARCHAR(100)));
  UPDATE tbl_reseller_bv_pv_details SET released_pvstatus = v_status, released_pvdate = dbo.FUN_GETCURRENTDATE() WHERE comdid = v_comdid AND released_pvstatus = 3;
  UPDATE tbl_resellerwise_customer_pvclubhistory SET totalreleased = totalreleased + 1, processstatus = 1 WHERE clubgroup = v_groupno;
  UPDATE tbl_resellerwise_customer_download_pvclubdata SET status = 1 WHERE allwdid = v_value AND status = 0;
  END IF;
  IF (v_mode = 2) THEN
  v_value := v_prefix || (CAST(v_comdid AS VARCHAR(100)));
  UPDATE tbl_reseller_bv_pv_details SET released_pvstatus = v_status, released_pvdate = dbo.FUN_GETCURRENTDATE() WHERE comdid = v_comdid AND released_pvstatus = 3;
  UPDATE tbl_resellerwise_customer_download_pvclubdata SET status = 2 WHERE allwdid IN (SELECT value FROM dbo.SPLITSTRINGBYCOMMA(v_comdid)) AND status = 0;
  END IF;
  -- SET option (removed)
  -- COMMIT (removed)
END;
$$;


--
-- Name: usp_pv_reseller_clubhistory_list(integer, integer, character varying, character varying, integer, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_pv_reseller_clubhistory_list(v_startrowindex integer DEFAULT 1, v_maxrows integer DEFAULT 100, v_fromdate character varying DEFAULT ''::character varying, v_todate character varying DEFAULT ''::character varying, v_totalrecord integer DEFAULT 0, v_did integer DEFAULT 2) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_query text;
  v_maxregno text;
  v_query1 text;
  v_minindex INT;
  v_maxindex INT;
  v_count INT;
  v_totalcount INT;
  v_chid INT;
  v_totoalcancelamount DECIMAL(18,2);
BEGIN
  -- SET option (removed)
  v_query := '';
  v_maxregno := '';
  v_query1 := '';
  v_count := 1;
  v_totalcount := 0;
  v_chid := 0;
  v_minindex := (v_startrowindex - 1) * v_maxrows + 1;
  v_maxindex := v_startrowindex * v_maxrows;
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp (ROWNUMBER BIGINT,
	  CHID BIGINT,
	  FILENAME VARCHAR(150),
	  DATE timestamp,
	  CLUBGROUP VARCHAR(150),
	  TOTALREQUEST INT,
	  TOTALAMOUNT DECIMAL(18,8),
	  PROCESSDATE timestamp,
	  PROCESSBY VARCHAR(50),
	  PROCESSSTATUS VARCHAR(50),
	  PROCESSIPADDRESS VARCHAR(50),
	  DateRanage Varchar(100)) ON COMMIT DROP;
  v_query := 'INSERT INTO #TEMP SELECT ROW_NUMBER()OVER(ORDER BY CHID DESC) AS ROWNUMBER,CHID,FILENAME,CONVERT(DATE,DATE,105) AS DATE,
CLUBGROUP,TOTALREQUEST,ISNULL(TOTALAMOUNT,0),
CONVERT(DATE,PROCESSDATE,105) AS PROCESSDATE,PROCESSBY,
(CASE WHEN PROCESSSTATUS=0  THEN ''Pending'' WHEN PROCESSSTATUS=1 THEN ''Distributed'' WHEN PROCESSSTATUS=2 THEN ''Cancelled'' END),PROCESSIPADDRESS,DATERANAGE
FROM TBL_RESELLERWISE_CUSTOMER_PVCLUBHISTORY   
WHERE 1=1 and DID=''' || CAST(v_did AS VARCHAR(30)) || '''';
  RAISE NOTICE '%', v_query;
  EXECUTE v_query;
  SELECT COUNT(1) INTO v_totalcount FROM tmp_temp;
  SELECT COALESCE(COUNT(1), 0) INTO v_totalrecord FROM tmp_temp;
  RETURN QUERY SELECT * FROM tmp_temp ORDER BY rownumber ASC NULLS FIRST;
  DROP TABLE IF EXISTS tmp_temp;
  -- SET option (removed)
END;
$$;


--
-- Name: usp_pv_reseller_update(character varying, character varying, character varying, character varying, character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_pv_reseller_update(v_groupnumber character varying DEFAULT ''::character varying, v_processby character varying DEFAULT ''::character varying, v_processipaddress character varying DEFAULT '1'::character varying, INOUT v_strresult character varying DEFAULT ''::character varying, v_mode character varying DEFAULT '2'::character varying) RETURNS character varying
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_getchid INT;
  v_getallwdid text;
  v_getupdatestatus text;
BEGIN
  v_getchid := 0;
  v_getallwdid := '';
  SELECT chid INTO v_getchid FROM tbl_resellerwise_customer_pvclubhistory WHERE clubgroup = v_groupnumber;
  v_strresult := '1';
  v_getupdatestatus := '';
  IF (v_mode = 2) THEN
  SELECT RIGHT(CAST(allwdid AS TEXT), LENGTH(CAST(allwdid AS TEXT)) - 1) INTO v_getallwdid FROM tbl_resellerwise_customer_pvclubhistory WHERE chid = v_getchid;
  v_getupdatestatus := 'UPDATE TBL_RESELLER_BV_PV_DETAILS SET Released_PvStatus=0 WHERE COMDID IN  (SELECT * FROM SPLITSTRING(''' || v_getallwdid || ''','',''))';
  EXECUTE v_getupdatestatus;
  UPDATE tbl_resellerwise_customer_download_pvclubdata SET status = 2, processby = v_processby, processipaddress = v_processipaddress, processdate = dbo.FUN_GETCURRENTDATE() WHERE chid = v_getchid;
  UPDATE tbl_resellerwise_customer_pvclubhistory SET processstatus = 2, processby = v_processby, processipaddress = v_processipaddress, processdate = dbo.FUN_GETCURRENTDATE() WHERE chid = v_getchid;
  v_strresult := '1';
  END IF;
END;
$$;


--
-- Name: usp_qa_all_report(bigint, character varying, character varying, character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_qa_all_report(v_optid bigint DEFAULT 0, v_fromdate character varying DEFAULT ''::character varying, v_todate character varying DEFAULT ''::character varying, v_monthval character varying DEFAULT ''::character varying) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_sqlquery text;
  v_count int;
  v_count1 int;
  v_date varchar(100);
  v_unverified int;
  v_verified int;
  v_process int;
  v_oprator bigint;
  v_recordcount int;
  v_totallisting int;
  v_totalverified int;
  v_totalunverified int;
  v_totalinprocess int;
BEGIN
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp (rowNumber int,
qaid bigint,
qaname varchar(100),
date varchar(100),
logintime varchar(100),
logouttime varchar(100),
totallistings bigint,
unverified bigint,
verified bigint,
process bigint) ON COMMIT DROP;
  v_sqlquery := '';
  v_sqlquery := ' insert into #temp select ROW_NUMBER() over (order by convert(date,la.date) desc) as rownumber,la.optid as qaid,ISNULL(om.name,'''') as qaname,
                 CONVERT(varchar(50),date,106) as date,
                 isnull((convert(varchar(20),logintime,105)+'' ''+convert(varchar(8),logintime,108)),''-'') as logintime,
                 isnull((convert(varchar(20),logouttime,105)+'' ''+convert(varchar(8),logouttime,108)),''-'') as logouttime,
				 COUNT(la.pmid) as totallistings,0 as unverified,0 as verified, 0 as process
                 from  tbl_ListingsWithQA la left join tbl_operator_report omr 
                 on convert(varchar(20),omr.logintime,105)=convert(varchar(20),la.date,105) and ISNULL(omr.optid,0)=ISNULL(la.optid,0)
                 left join tbl_operator_master om on ISNULL(om.optid,0)=ISNULL(la.optid,0)
                 where ISNULL(la.date,'''')<>'''' ';
  IF (v_optid <> '') THEN
  v_sqlquery := v_sqlquery || (' and la.optid = ' || CAST(v_optid AS VARCHAR(20)) || ' ');
  END IF;
  IF (v_monthval <> '') THEN
  v_sqlquery := v_sqlquery || (' and convert(varchar(7), la.date, 126)= ''' || v_monthval || ''' ');
  END IF;
  v_sqlquery := v_sqlquery || (' group by convert(date,la.date),CONVERT(varchar(50),date,106),isnull((convert(varchar(20),logintime,105)+'' ''+convert(varchar(8),logintime,108)),''-''),
                   ISNULL(om.name,''''),isnull((convert(varchar(20),logouttime,105)+'' ''+convert(varchar(8),logouttime,108)),''-''),la.optid  ');
  EXECUTE v_sqlquery;
  SELECT COUNT(1) INTO v_count1 FROM tmp_temp;
  v_count := 1;
  WHILE (v_count <= v_count1) LOOP
  IF EXISTS(SELECT 1 FROM tmp_temp WHERE rownumber = v_count) THEN
  SELECT date, qaid INTO v_date, v_oprator FROM tmp_temp WHERE rownumber = v_count;
  SELECT COUNT(1) INTO v_unverified FROM tbl_listingswithqa AS la, portal_master AS pm WHERE COALESCE(pm.pmid, 0) = COALESCE(la.pmid, 0) AND COALESCE(pm.isverified, 0) = 0 AND CAST(TO_CHAR(la.date, 'DD TMMon YYYY') AS VARCHAR(50)) = v_date AND COALESCE(la.optid, 0) = v_oprator;
  SELECT COUNT(1) INTO v_verified FROM tbl_listingswithqa AS la, portal_master AS pm WHERE COALESCE(pm.pmid, 0) = COALESCE(la.pmid, 0) AND COALESCE(pm.isverified, 0) = 1 AND CAST(TO_CHAR(la.date, 'DD TMMon YYYY') AS VARCHAR(50)) = v_date AND COALESCE(la.optid, 0) = v_oprator;
  SELECT COUNT(1) INTO v_process FROM tbl_listingswithqa AS la, portal_master AS pm WHERE COALESCE(pm.pmid, 0) = COALESCE(la.pmid, 0) AND COALESCE(pm.isverified, 0) = 2 AND CAST(TO_CHAR(la.date, 'DD TMMon YYYY') AS VARCHAR(50)) = v_date AND COALESCE(la.optid, 0) = v_oprator;
  UPDATE tmp_temp SET unverified = v_unverified, verified = v_verified, process = v_process WHERE rownumber = v_count;
  END IF;
  v_count := v_count + 1;
  END LOOP;
  RETURN QUERY SELECT * FROM tmp_temp;
END;
$$;


--
-- Name: usp_qad_transactionid(character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_qad_transactionid(INOUT v_inresultout character varying) RETURNS character varying
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_random bigint;
  v_upper bigint;
  v_lower bigint;
  v_count int;
  v_id int;
  v_intresult2 varchar(20);
  v_intresult varchar(100);
BEGIN
  v_id := 0;
  WHILE (v_id = 0) LOOP
  v_lower := 11111111;
  v_upper := 99999999;
  SELECT ROUND(((v_upper - v_lower - 1) * RANDOM() + v_lower), 0) INTO v_random;
  v_intresult := CAST(v_random AS VARCHAR);
  v_intresult2 := v_intresult || 'QAD2';
  v_id := 1;
  SELECT COUNT(*) INTO v_count FROM tbl_packrequestsdetails WHERE transection_id = v_intresult2;
  IF EXISTS(SELECT 1 FROM tbl_packrequestsdetails WHERE transection_id = v_intresult2) THEN
  v_id := 0;
  END IF;
  IF (LENGTH(CAST(v_intresult2 AS TEXT)) <> 12) THEN
  v_id := 0;
  END IF;
  IF (v_id = 1) THEN
  v_inresultout := v_intresult2;
  IF (0 <> 0) THEN
  v_intresult2 := 2;
  -- ROLLBACK (removed)
  RETURN;
  END IF;
  END IF;
  END LOOP;
END;
$$;


--
-- Name: usp_qpaymemberlogindetails(integer, integer, character varying, boolean, character varying, character varying, character varying, character varying, integer, integer, character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_qpaymemberlogindetails(v_startrowindex integer, v_maxrows integer, v_orderbyfield character varying, v_asc boolean, v_searchfield character varying, v_searchvalue character varying, v_fromdate character varying, v_todate character varying, v_mode integer, v_recordcount integer, v_cid character varying) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_sqlquery text;
BEGIN
  -- SET option (removed)
  DROP TABLE IF EXISTS tmp_temp66;
  CREATE TEMP TABLE tmp_temp66 (rowNumber int,
refral_id varchar(150),
password varchar(150),
LoginId varchar(150),
doc varchar(24),
username varchar(100),
plid bigint,
country varchar(100),
active varchar(20)) ON COMMIT DROP;
  v_sqlquery := '';
  v_sqlquery := 'insert into #temp66 select ROW_NUMBER() OVER(ORDER BY doc desc) as rowNumber,isnull(refral_id,''-'') as refral_id,
	password,LoginId,convert(varchar(24),doc,105) as doc,isnull(username,''-'') as username,plid,
	(case when C.countryName=''UNITED STATES'' then ''US'' when C.countryName=''UNITED KINGDOM'' then ''UK'' else  C.countryName end  ) as countryName,
	(case when Active=1 then ''Active''else ''Deactive'' end) as  Active
	from Portal_Login left join country c on c.cid=Portal_Login.cid where active=1 and qpayregno>0 ';
  IF (v_cid <> '') THEN
  v_sqlquery := v_sqlquery || (' and c.cid =' || v_cid || ' ');
  END IF;
  IF (v_fromdate = '' OR v_todate = '') THEN
  IF (v_fromdate <> '') THEN
  v_sqlquery := v_sqlquery || ' and convert(VARCHAR(24),doc,105)= replace(convert(VARCHAR(10),''' || v_fromdate || ''',111),''/'',''-'') ';
  END IF;
  IF (v_todate <> '') THEN
  v_sqlquery := v_sqlquery || ' and convert(VARCHAR(24),doc,105)  = replace(convert(VARCHAR(10),''' || v_todate || ''',111),''/'',''-'') ';
  END IF;
  END IF;
  IF (v_fromdate <> '' AND v_todate <> '') THEN
  v_sqlquery := v_sqlquery || ' and  convert(VARCHAR(24),doc,105)  between  replace(convert(VARCHAR(10),''' || v_fromdate || ''',111),''/'',''-'')  and replace(convert(VARCHAR(10),''' || v_todate || ''',111),''/'',''-'')';
  END IF;
  IF (v_searchfield = 'loginid') THEN
  v_sqlquery := v_sqlquery || ' and loginid like ''%' || v_searchvalue || '%''';
  END IF;
  IF (v_searchfield = 'referal') THEN
  v_sqlquery := v_sqlquery || ' and refral_id like ''%' || v_searchvalue || '%''';
  END IF;
  IF (v_searchfield = 'username') THEN
  v_sqlquery := v_sqlquery || ' and username like ''%' || v_searchvalue || '%''';
  END IF;
  IF (v_searchfield = 'country') THEN
  v_sqlquery := v_sqlquery || ' and c.countryName like ''%' || v_searchvalue || '%''';
  END IF;
  EXECUTE v_sqlquery || ' order by doc desc';
  SELECT COUNT(*) INTO v_recordcount FROM tmp_temp66;
  RETURN QUERY SELECT * FROM tmp_temp66 WHERE rownumber BETWEEN v_startrowindex AND v_maxrows;
  DROP TABLE IF EXISTS tmp_temp66;
  RETURN QUERY SELECT v_recordcount AS recordcount;
  -- SET option (removed)
END;
$$;


--
-- Name: usp_recentlyvieweditems(integer, bigint, character varying, character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_recentlyvieweditems(v_mode integer DEFAULT 3, v_sprid bigint DEFAULT 0, v_sessionid character varying DEFAULT ''::character varying, v_stroutput character varying DEFAULT ''::character varying) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
BEGIN
  -- BEGIN TRAN (removed)
  IF (v_mode = 1) THEN
  IF (v_sprid <> 0 AND v_sessionid <> '' AND v_mode = 1) THEN
  IF EXISTS(SELECT 1 FROM tbl_temprecentlyvieweditems WHERE sessionid = v_sessionid AND sprid = v_sprid) THEN
  v_stroutput := 'ALREADY';
  -- COMMIT (removed)
  RETURN;
  ELSE
  INSERT INTO tbl_temprecentlyvieweditems (sprid, sessionid, createddate, active) VALUES (v_sprid, v_sessionid, dbo.FUN_GETCURRENTDATE(), 1);
  v_stroutput := 'SUCCESS';
  -- COMMIT (removed)
  END IF;
  END IF;
  END IF;
  IF (v_mode = 2) THEN
  DELETE FROM tbl_temprecentlyvieweditems WHERE sessionid <> v_sessionid;
  v_stroutput := 'SUCCESS';
  -- COMMIT (removed)
  END IF;
  IF (v_mode = 3) THEN
  RETURN QUERY SELECT ROW_NUMBER() OVER (ORDER BY mprid NULLS FIRST) AS rowno, COALESCE(mprid, 0) AS mprid, productcode, producttitle, COALESCE(shotdescription, '') AS shotdescription, fulldescription, prodview.sprid, productimages, discountpercentage, sellmrp, dap, masterproductattriubuteid, attributetitle, attributevalue, keyfeatures, CAST(dbo.FUN_GETRATINGOFSUBPRODUCT(prodview.sprid) AS INT) AS ratingstar, CAST(maincategoryid AS BIGINT) AS maincategoryid, CAST(subcategoryid AS BIGINT) AS subcategoryid, CAST(catid AS BIGINT) AS catid, dealsids, prodview.createddate, modifydate, replacementday, procurementsla, cashondelivery, shippingcharges, stockin, stockout, stocknet, isoutofstock, CAST(bv AS DECIMAL(18, 2)) AS bv, CAST(pv AS DECIMAL(18, 2)) AS pv, main_cat_code, sub_cat_code, cat_code FROM ims_view_allproductdeals AS prodview INNER JOIN tbl_temprecentlyvieweditems AS recentprod ON prodview.sprid = recentprod.sprid ORDER BY CAST(recentprod.createddate AS DATE) DESC NULLS LAST LIMIT 20;
  v_stroutput := 'SUCCESS';
  -- COMMIT (removed)
  END IF;
  IF (0 <> 0) THEN
  v_stroutput := 'ERROR';
  -- ROLLBACK (removed)
  RETURN;
  END IF;
END;
$$;


--
-- Name: usp_recharge_comm_structure(integer, integer, integer, numeric, numeric, numeric, integer, integer, character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_recharge_comm_structure(v_startrowindex integer DEFAULT 1, v_maxrows integer DEFAULT 100, v_trcsid integer DEFAULT 0, v_commissonpercentage numeric DEFAULT 0, v_redeemewalletpercenatge numeric DEFAULT 0, v_earnbvpercentage numeric DEFAULT 0, v_mode integer DEFAULT 2, v_totalcount integer DEFAULT 0, v_name character varying DEFAULT ''::character varying) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_minindex INT;
  v_maxindex INT;
  v_query text;
BEGIN
  v_minindex := (v_startrowindex - 1) * v_maxrows + 1;
  v_maxindex := v_startrowindex * v_maxrows;
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp (ROWNUMBER BIGINT GENERATED BY DEFAULT AS IDENTITY,
TRCSID INT,
PROVIDERNAME VARCHAR(500),
PROVIDERIMAGE VARCHAR(500),
PROVIDERCODE VARCHAR(100),
COMMISSION DECIMAL(18,2),
REDEEMEWALLETPERCENATGE DECIMAL(18,2),
EARNBVPERCENTAGE DECIMAL(18,2),
STATUS INT) ON COMMIT DROP;
  IF (v_mode = 1) THEN
  IF EXISTS(SELECT trcsid FROM tbl_recharge_commission_structure WHERE trcsid = v_trcsid) THEN
  INSERT INTO tbl_recharge_commission_structure_history SELECT trcsid, providerimage, providername, providercode, commission, status, redeemewalletpercenatge, earnbvpercentage, createdate, active FROM tbl_recharge_commission_structure WHERE trcsid = v_trcsid;
  UPDATE tbl_recharge_commission_structure SET commission = v_commissonpercentage, redeemewalletpercenatge = v_redeemewalletpercenatge, earnbvpercentage = v_earnbvpercentage WHERE trcsid = v_trcsid;
  END IF;
  ELSE
  IF (v_mode = 2) THEN
  v_query := 'INSERT INTO #TEMP   SELECT TRCS.TRCSID,TRCS.PROVIDERNAME,ISNULL(TRCS.PROVIDERIMAGE,''''),TRCS.PROVIDERCODE,TRCS.COMMISSION,
TRCS.REDEEMEWALLETPERCENATGE,TRCS.EARNBVPERCENTAGE,TRCS.STATUS 
FROM TBL_RECHARGE_COMMISSION_STRUCTURE TRCS   WHERE 1=1';
  IF (v_name <> '') THEN
  v_query := v_query || ' And TRCS.PROVIDERNAME =''' || v_name || '''';
  END IF;
  END IF;
  END IF;
  EXECUTE v_query;
  RAISE NOTICE '%', v_query;
  RETURN QUERY SELECT * FROM tmp_temp WHERE rownumber BETWEEN v_minindex AND v_maxindex;
  SELECT COUNT(rownumber) INTO v_totalcount FROM tmp_temp;
  DROP TABLE IF EXISTS tmp_temp;
  -- SET option (removed)
END;
$$;


--
-- Name: usp_rechargemaster(character varying, character varying, integer, character varying, integer, character varying, numeric, character varying, character varying, character varying, character varying, character varying, integer, integer, integer, numeric, character varying, character varying, character varying, text); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_rechargemaster(v_type character varying DEFAULT ''::character varying, v_uniqueaccountnumber character varying DEFAULT ''::character varying, v_operatorid integer DEFAULT NULL::integer, v_operatorname character varying DEFAULT ''::character varying, v_ciecleid integer DEFAULT 0, v_circlename character varying DEFAULT ''::character varying, v_amount numeric DEFAULT 0.00, v_clienttransactionid character varying DEFAULT ''::character varying, v_successurl character varying DEFAULT ''::character varying, v_failureurl character varying DEFAULT ''::character varying, v_inprocessurl character varying DEFAULT ''::character varying, v_cancelurl character varying DEFAULT ''::character varying, v_clid integer DEFAULT 0, v_did integer DEFAULT 0, v_isandroidorweb integer DEFAULT 0, v_admincommission numeric DEFAULT 0.00, INOUT v_strouput character varying DEFAULT ''::character varying, v_stdcode character varying DEFAULT ''::character varying, v_accountno character varying DEFAULT ''::character varying, v_apibody text DEFAULT ''::text) RETURNS character varying
    LANGUAGE plpgsql
    AS $$
BEGIN
  BEGIN
  IF (v_type = 'MOBILEPREPAID') THEN
  INSERT INTO tbl_customer_prepaid_recharges (clid, mobileno, operatortype, operatorname, operatorcode, operatorservice, rechargeamount, rechargedate, rechargestatus, responsedate, responseremarks, transactionid, apitransactionid, successurl, failureurl, inprocessurl, cancelledurl, createdate, active, isandroidorweb, admincommission, adminsurcharge, resellercommission, resellersurcharge) VALUES (v_clid, v_uniqueaccountnumber, v_type, v_operatorname, v_operatorid, v_type, v_amount, dbo.FUN_GETCURRENTDATE(), NULL, NULL, NULL, v_clienttransactionid, NULL, v_successurl, v_failureurl, v_inprocessurl, v_cancelurl, dbo.FUN_GETCURRENTDATE(), 1, v_isandroidorweb, v_admincommission, 0, 0, 0);
  END IF;
  IF (v_type = 'MOBILEPOSTPAID') THEN
  INSERT INTO tbl_customer_postpaid_recharges (clid, mobileno, operatortype, operatorname, operatorcode, operatorservice, rechargeamount, rechargedate, rechargestatus, responsedate, responseremarks, transactionid, apitransactionid, successurl, failureurl, inprocessurl, cancelledurl, createdate, active, isandroidorweb, admincommission, adminsurcharge, resellercommission, resellersurcharge) VALUES (v_clid, v_uniqueaccountnumber, v_type, v_operatorname, v_operatorid, v_type, v_amount, dbo.FUN_GETCURRENTDATE(), NULL, NULL, NULL, v_clienttransactionid, NULL, v_successurl, v_failureurl, v_inprocessurl, v_cancelurl, dbo.FUN_GETCURRENTDATE(), 1, v_isandroidorweb, v_admincommission, 0, 0, 0);
  ELSE
  IF (v_type = 'DATACARD') THEN
  INSERT INTO tbl_customer_datacard_recharges (clid, mobileno, operatortype, operatorname, operatorcode, operatorservice, rechargeamount, rechargedate, rechargestatus, responsedate, responseremarks, transactionid, apitransactionid, successurl, failureurl, inprocessurl, cancelledurl, createdate, active, isandroidorweb, admincommission, adminsurcharge, resellercommission, resellersurcharge) VALUES (v_clid, v_uniqueaccountnumber, v_type, v_operatorname, v_operatorid, v_type, v_amount, dbo.FUN_GETCURRENTDATE(), NULL, NULL, NULL, v_clienttransactionid, NULL, v_successurl, v_failureurl, v_inprocessurl, v_cancelurl, dbo.FUN_GETCURRENTDATE(), 1, v_isandroidorweb, v_admincommission, 0, 0, 0);
  ELSE
  IF (v_type = 'DTH') THEN
  INSERT INTO tbl_customer_dth_recharges (clid, mobileno, operatortype, operatorname, operatorcode, operatorservice, rechargeamount, rechargedate, rechargestatus, responsedate, responseremarks, transactionid, apitransactionid, successurl, failureurl, inprocessurl, cancelledurl, createdate, active, isandroidorweb, admincommission, adminsurcharge, resellercommission, resellersurcharge) VALUES (v_clid, v_uniqueaccountnumber, v_type, v_operatorname, v_operatorid, v_type, v_amount, dbo.FUN_GETCURRENTDATE(), NULL, NULL, NULL, v_clienttransactionid, NULL, v_successurl, v_failureurl, v_inprocessurl, v_cancelurl, dbo.FUN_GETCURRENTDATE(), 1, v_isandroidorweb, v_admincommission, 0, 0, 0);
  ELSE
  IF (v_type = 'LANDLINE') THEN
  INSERT INTO tbl_customer_landline_recharges (clid, mobileno, operatortype, operatorname, operatorcode, operatorservice, rechargeamount, rechargedate, rechargestatus, responsedate, responseremarks, transactionid, apitransactionid, successurl, failureurl, inprocessurl, cancelledurl, createdate, active, isandroidorweb, admincommission, adminsurcharge, resellercommission, resellersurcharge, stdcode, accountno, circle) VALUES (v_clid, v_uniqueaccountnumber, v_type, v_operatorname, v_operatorid, v_type, v_amount, dbo.FUN_GETCURRENTDATE(), NULL, NULL, NULL, v_clienttransactionid, NULL, v_successurl, v_failureurl, v_inprocessurl, v_cancelurl, dbo.FUN_GETCURRENTDATE(), 1, v_isandroidorweb, v_admincommission, 0, 0, 0, v_stdcode, v_accountno, v_circlename);
  ELSE
  IF (v_type = 'ELECTRICITY') THEN
  INSERT INTO tbl_customer_electricity_recharges (clid, mobileno, operatortype, operatorname, operatorcode, operatorservice, rechargeamount, rechargedate, rechargestatus, responsedate, responseremarks, transactionid, apitransactionid, successurl, failureurl, inprocessurl, cancelledurl, createdate, active, isandroidorweb, admincommission, adminsurcharge, resellercommission, resellersurcharge, apibody) VALUES (v_clid, v_uniqueaccountnumber, v_type, v_operatorname, v_operatorid, v_type, v_amount, dbo.FUN_GETCURRENTDATE(), NULL, NULL, NULL, v_clienttransactionid, NULL, v_successurl, v_failureurl, v_inprocessurl, v_cancelurl, dbo.FUN_GETCURRENTDATE(), 1, v_isandroidorweb, v_admincommission, 0, 0, 0, v_apibody);
  ELSE
  IF (v_type = 'WATER') THEN
  INSERT INTO tbl_customer_water_recharges (clid, mobileno, operatortype, operatorname, operatorcode, operatorservice, rechargeamount, rechargedate, rechargestatus, responsedate, responseremarks, transactionid, apitransactionid, successurl, failureurl, inprocessurl, cancelledurl, createdate, active, isandroidorweb, admincommission, adminsurcharge, resellercommission, resellersurcharge, apibody) VALUES (v_clid, v_uniqueaccountnumber, v_type, v_operatorname, v_operatorid, v_type, v_amount, dbo.FUN_GETCURRENTDATE(), NULL, NULL, NULL, v_clienttransactionid, NULL, v_successurl, v_failureurl, v_inprocessurl, v_cancelurl, dbo.FUN_GETCURRENTDATE(), 1, v_isandroidorweb, v_admincommission, 0, 0, 0, v_apibody);
  ELSE
  IF (v_type = 'GAS') THEN
  INSERT INTO tbl_customer_gas_recharges (clid, mobileno, operatortype, operatorname, operatorcode, operatorservice, rechargeamount, rechargedate, rechargestatus, responsedate, responseremarks, transactionid, apitransactionid, successurl, failureurl, inprocessurl, cancelledurl, createdate, active, isandroidorweb, admincommission, adminsurcharge, resellercommission, resellersurcharge, apibody) VALUES (v_clid, v_uniqueaccountnumber, v_type, v_operatorname, v_operatorid, v_type, v_amount, dbo.FUN_GETCURRENTDATE(), NULL, NULL, NULL, v_clienttransactionid, NULL, v_successurl, v_failureurl, v_inprocessurl, v_cancelurl, dbo.FUN_GETCURRENTDATE(), 1, v_isandroidorweb, v_admincommission, 0, 0, 0, v_apibody);
  ELSE
  IF (v_type = 'BROADBAND') THEN
  INSERT INTO tbl_customer_broadband_recharges (clid, mobileno, operatortype, operatorname, operatorcode, operatorservice, rechargeamount, rechargedate, rechargestatus, responsedate, responseremarks, transactionid, apitransactionid, successurl, failureurl, inprocessurl, cancelledurl, createdate, active, isandroidorweb, admincommission, adminsurcharge, resellercommission, resellersurcharge, apibody) VALUES (v_clid, v_uniqueaccountnumber, v_type, v_operatorname, v_operatorid, v_type, v_amount, dbo.FUN_GETCURRENTDATE(), NULL, NULL, NULL, v_clienttransactionid, NULL, v_successurl, v_failureurl, v_inprocessurl, v_cancelurl, dbo.FUN_GETCURRENTDATE(), 1, v_isandroidorweb, v_admincommission, 0, 0, 0, v_apibody);
  END IF;
  END IF;
  END IF;
  END IF;
  END IF;
  END IF;
  END IF;
  END IF;
  v_strouput := 'success';
  EXCEPTION WHEN OTHERS THEN
  v_strouput := 'error';
  END;
END;
$$;


--
-- Name: usp_referalincome(integer, numeric, numeric, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_referalincome(v_pmid integer DEFAULT 0, v_totoalamount numeric DEFAULT 0, v_currencyrate numeric DEFAULT 0, INOUT v_intresult integer DEFAULT 0) RETURNS integer
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_referalincome numeric(19,4);
  v_intro_refid BIGINT;
  v_intropmid BIGINT;
  v_qpayregno BIGINT;
  v_income numeric(19,4);
  v_amount numeric(19,4);
  v_cramount numeric(19,4);
  v_earnedreffral numeric(19,4);
BEGIN
  -- BEGIN TRAN (removed)
  -- SET option (removed)
  v_intresult := 0;
  SELECT COALESCE(intro_refid, 0) INTO v_intro_refid FROM portal_login WHERE pmid = v_pmid;
  IF v_intro_refid > 0 THEN
  SELECT COALESCE(qpayregno, 0) INTO v_qpayregno FROM portal_login WHERE plid = v_intro_refid;
  IF v_qpayregno > 0 THEN
  v_referalincome := v_totoalamount * 20 / 100;
  v_referalincome := v_referalincome * v_currencyrate;
  INSERT INTO member_perfornemce (plid, childpmid, cpmmision_percentage, amount, qpayregno, refincome, date, active, trantype) VALUES (v_intropmid, v_pmid, 20, v_referalincome, v_qpayregno, v_referalincome, CURRENT_TIMESTAMP, 1, 'REFERRAL INCOME');
  IF EXISTS(SELECT plid FROM ewallet WHERE plid = v_intropmid) THEN
  SELECT amount, cramount, referalcommission INTO v_amount, v_cramount, v_earnedreffral FROM ewallet WHERE plid = v_intropmid;
  v_income := v_amount + v_referalincome;
  v_cramount := v_cramount + v_referalincome;
  v_earnedreffral := v_earnedreffral + v_referalincome;
  UPDATE ewallet SET amount = v_income, cramount = v_cramount, referalcommission = v_referalincome WHERE plid = v_intropmid;
  ELSE
  INSERT INTO ewallet (plid, amount, active) VALUES (v_intropmid, v_referalincome, 1);
  END IF;
  v_intresult := 3;
  ELSE
  v_referalincome := v_totoalamount * 10 / 100;
  v_referalincome := v_referalincome * v_currencyrate;
  INSERT INTO member_perfornemce (plid, childpmid, cpmmision_percentage, amount, qpayregno, refincome, date, active, trantype) VALUES (v_intropmid, v_pmid, 10, v_referalincome, 0, v_referalincome, CURRENT_TIMESTAMP, 1, 'REFERRAL INCOME');
  IF EXISTS(SELECT plid FROM ewallet WHERE plid = v_intropmid) THEN
  SELECT amount, cramount, referalcommission INTO v_amount, v_cramount, v_earnedreffral FROM ewallet WHERE plid = v_intropmid;
  v_income := v_amount + v_referalincome;
  v_cramount := v_cramount + v_referalincome;
  v_earnedreffral := v_earnedreffral + v_referalincome;
  UPDATE ewallet SET amount = v_income, cramount = v_cramount, referalcommission = v_referalincome WHERE plid = v_intropmid;
  ELSE
  INSERT INTO ewallet (plid, amount, active, referalcommission) VALUES (v_intropmid, v_referalincome, 1, v_referalincome);
  END IF;
  v_intresult := 3;
  END IF;
  END IF;
  IF (0 > 0) THEN
  v_intresult := 2;
  -- ROLLBACK (removed)
  RETURN;
  END IF;
  -- SET option (removed)
  -- COMMIT (removed)
END;
$$;


--
-- Name: usp_referral_signup_temp(character varying, character varying, character varying, integer, integer, bigint, character varying, character varying, integer, character varying, character varying, character varying, character varying, character varying, integer, integer, character varying, character varying, character varying, character varying, integer, integer, integer, integer, character varying, character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_referral_signup_temp(v_loginid character varying DEFAULT 'support@awapal.com'::character varying, v_password character varying DEFAULT '12345'::character varying, v_username character varying DEFAULT 'ANAVEXCHANGE'::character varying, INOUT v_intresult integer DEFAULT 0, v_mode integer DEFAULT 0, v_qpayregno bigint DEFAULT 0, v_currencysymbol character varying DEFAULT ''::character varying, v_country character varying DEFAULT ''::character varying, INOUT v_plid integer DEFAULT 0, v_referrelcode character varying DEFAULT ''::character varying, v_ipaddress character varying DEFAULT ''::character varying, v_mobileno character varying DEFAULT '7827739166'::character varying, v_sponsorids character varying DEFAULT ''::character varying, v_placementids character varying DEFAULT ''::character varying, v_side integer DEFAULT 0, v_title integer DEFAULT 0, v_firstname character varying DEFAULT ''::character varying, v_lastname character varying DEFAULT ''::character varying, v_desigantion character varying DEFAULT ''::character varying, v_imagename character varying DEFAULT ''::character varying, v_modeforjoining integer DEFAULT 0, v_cid integer DEFAULT 0, v_sid integer DEFAULT 0, v_ctid integer DEFAULT 0, v_cityname character varying DEFAULT ''::character varying, v_transactionpassword character varying DEFAULT ''::character varying) RETURNS record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_regnoref INT;
  v_spounsertype INT;
  v_username_count INT;
  v_duplicate_mobile INT;
  v_duplicateemailid_count INT;
  v_chars char(88);
  v_referalcode VARCHAR(20);
  v_intcontinue INT;
  v_userid VARCHAR(100);
  v_strresult Varchar(200);
  v_intromemid Varchar(200);
  v_placementmemid Varchar(200);
  v_placementregnoside INT;
BEGIN
  -- BEGIN TRAN (removed)
  -- SET option (removed)
  -- SET option (removed)
  v_spounsertype := 0;
  v_placementids := v_sponsorids;
  v_intresult := 0;
  v_username_count := 0;
  v_duplicate_mobile := 0;
  v_duplicateemailid_count := 0;
  SELECT COUNT(1) INTO v_username_count FROM member_master WHERE username = v_username;
  IF (COALESCE(v_username_count, 0) > 0) THEN
  v_intresult := 5;
  -- ROLLBACK (removed)
  RETURN;
  ELSE
  IF EXISTS(SELECT 1 FROM member_master WHERE username = v_referrelcode AND COALESCE(v_referrelcode, '') <> '') THEN
  SELECT regno, loginid, loginid, COALESCE(defaultsponserside, 3) INTO v_regnoref, v_sponsorids, v_placementids, v_side FROM member_master WHERE username = v_referrelcode;
  ELSE
  IF (v_sponsorids <> '' AND v_side > 0) THEN
  v_referrelcode := v_sponsorids;
  IF EXISTS(SELECT 1 FROM member_master WHERE username = v_referrelcode AND COALESCE(v_referrelcode, '') <> '') THEN
  SELECT regno, loginid, loginid INTO v_regnoref, v_sponsorids, v_placementids FROM member_master WHERE username = v_referrelcode;
  END IF;
  ELSE
  SELECT loginid, regno, loginid, COALESCE(defaultsponserside, 3) INTO v_sponsorids, v_regnoref, v_placementids, v_side FROM member_master WHERE plid = 1;
  END IF;
  END IF;
  v_spounsertype := 0;
  IF (COALESCE(v_regnoref, 0) = 0) THEN
  v_spounsertype := 0;
  ELSE
  SELECT CASE WHEN COALESCE(active, 0) = 0 THEN 1 ELSE 2 END INTO v_spounsertype FROM member_master WHERE regno = v_regnoref;
  END IF;
  IF EXISTS(SELECT COALESCE(cid, '96') FROM country WHERE countryname = v_country AND cactive = 1) THEN
  IF (v_cid = 0) THEN
  SELECT COALESCE(cid, '96') INTO v_cid FROM country WHERE countryname = v_country AND cactive = 1;
  END IF;
  ELSE
  IF (v_cid = 0) THEN
  v_cid := 96;
  END IF;
  END IF;
  IF (v_mode = 0) THEN
  IF NOT EXISTS(SELECT 1 FROM member_master WHERE username = v_username) THEN
  DROP TABLE IF EXISTS tmp_tb1;
  CREATE TEMP TABLE tmp_tb1 ON COMMIT DROP AS SELECT ROW_NUMBER() OVER (ORDER BY item NULLS FIRST) AS row, item FROM dbo.SPLITSTRING(v_username, '');
  v_referalcode := '';
  v_intcontinue := 0;
  v_chars := N'0123456789';
  WHILE (v_intcontinue = 0) LOOP
  v_referalcode := SUBSTRING(v_chars FROM CAST((RANDOM() * LENGTH(CAST(v_chars AS TEXT))) AS INT) + 1 FOR 1) || SUBSTRING(v_chars FROM CAST((RANDOM() * LENGTH(CAST(v_chars AS TEXT))) AS INT) + 1 FOR 1) || SUBSTRING(v_chars FROM CAST((RANDOM() * LENGTH(CAST(v_chars AS TEXT))) AS INT) + 1 FOR 1) || SUBSTRING(v_chars FROM CAST((RANDOM() * LENGTH(CAST(v_chars AS TEXT))) AS INT) + 1 FOR 1) || SUBSTRING(v_chars FROM CAST((RANDOM() * LENGTH(CAST(v_chars AS TEXT))) AS INT) + 1 FOR 1) || SUBSTRING(v_chars FROM CAST((RANDOM() * LENGTH(CAST(v_chars AS TEXT))) AS INT) + 1 FOR 1);
  IF EXISTS(SELECT 1 FROM portal_login_temp WHERE refral_id = v_referalcode) THEN
  v_intcontinue := 0;
  ELSE
  IF (LENGTH(CAST(v_referalcode AS TEXT)) < 6) THEN
  v_intcontinue := 0;
  ELSE
  IF ((SELECT SUBSTRING(v_referalcode FROM 1 FOR 1)) <= 0) THEN
  v_intcontinue := 0;
  ELSE
  v_intcontinue := 1;
  END IF;
  END IF;
  END IF;
  END LOOP;
  v_userid := '';
  SELECT 0 INTO v_intcontinue;
  v_chars := N'8123456789';
  WHILE (v_intcontinue = 0) LOOP
  v_userid := SUBSTRING(v_chars FROM CAST((RANDOM() * LENGTH(CAST(v_chars AS TEXT))) AS INT) + 1 FOR 1) || SUBSTRING(v_chars FROM CAST((RANDOM() * LENGTH(CAST(v_chars AS TEXT))) AS INT) + 1 FOR 1) || SUBSTRING(v_chars FROM CAST((RANDOM() * LENGTH(CAST(v_chars AS TEXT))) AS INT) + 1 FOR 1) || SUBSTRING(v_chars FROM CAST((RANDOM() * LENGTH(CAST(v_chars AS TEXT))) AS INT) + 1 FOR 1) || SUBSTRING(v_chars FROM CAST((RANDOM() * LENGTH(CAST(v_chars AS TEXT))) AS INT) + 1 FOR 1) || SUBSTRING(v_chars FROM CAST((RANDOM() * LENGTH(CAST(v_chars AS TEXT))) AS INT) + 1 FOR 1) || SUBSTRING(v_chars FROM CAST((RANDOM() * LENGTH(CAST(v_chars AS TEXT))) AS INT) + 1 FOR 1) || SUBSTRING(v_chars FROM CAST((RANDOM() * LENGTH(CAST(v_chars AS TEXT))) AS INT) + 1 FOR 1);
  IF EXISTS(SELECT 1 FROM portal_login_temp WHERE userid = v_userid) THEN
  v_intcontinue := 0;
  ELSE
  IF (LENGTH(CAST(v_userid AS TEXT)) < 8) THEN
  v_intcontinue := 0;
  ELSE
  IF ((SELECT SUBSTRING(v_userid FROM 1 FOR 1)) <= 0) THEN
  v_intcontinue := 0;
  ELSE
  v_intcontinue := 1;
  END IF;
  END IF;
  END IF;
  END LOOP;
  v_strresult := '';
  v_intromemid := '';
  v_placementmemid := '';
  v_placementregnoside := 0;
  v_intromemid := v_sponsorids;
  v_placementmemid := v_sponsorids;
  IF (v_regnoref <> 0) THEN
  SELECT (CASE WHEN v_side <> 0 THEN v_side WHEN communityside = 1 THEN 1 WHEN communityside = 2 THEN 2 ELSE 3 END) INTO v_placementregnoside FROM portal_login WHERE plid = v_regnoref;
  END IF;
  SELECT v_strresult INTO v_strresult FROM dbo.usp_insert_member_master(v_maxplid => v_regnoref, v_intromemid => v_intromemid, v_placementmemid => v_placementmemid, v_placementregnoside => v_placementregnoside, v_username => v_username, v_fname => v_firstname, v_mname => '', v_lname => v_lastname, v_gender => 0, v_dob => NULL, v_email => v_loginid, v_mobile => v_mobileno, v_sid => v_sid, v_statename => '', v_ctid => v_ctid, v_cityname => v_cityname, v_cid => v_cid, v_address => '', v_pincode => '', v_panno => '', v_password => v_password, v_trpassword => v_transactionpassword, v_ipadd => v_ipaddress, v_epinnumber => '', v_nomineename => '', v_nomineerelation => '', v_sessionloginid => '', v_kitid => 0, v_strresult => v_strresult, v_application_formno => '', v_loginid => v_loginid, v_userid => v_userid, v_atc_walletaddress => v_referrelcode);
  v_intresult := 1;
  -- COMMIT (removed)
  RETURN;
  END IF;
  END IF;
  END IF;
  IF (0 <> 0) THEN
  v_intresult := 0;
  -- ROLLBACK (removed)
  RETURN;
  END IF;
  -- SET option (removed)
  -- COMMIT (removed)
END;
$$;


--
-- Name: usp_referralcustomerlist(integer, integer, integer, integer, character varying, character varying, character varying, character varying, character varying, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_referralcustomerlist(v_plid integer DEFAULT 0, v_startrowindex integer DEFAULT 1, v_maxrows integer DEFAULT 100, v_totalcount integer DEFAULT 0, v_fromdate character varying DEFAULT ''::character varying, v_todate character varying DEFAULT ''::character varying, v_username character varying DEFAULT ''::character varying, v_emailid character varying DEFAULT 'vinay1@awapal.com'::character varying, v_phone character varying DEFAULT ''::character varying, v_checkadminside integer DEFAULT 1) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_query text;
  v_minindex INT;
  v_maxindex INT;
BEGIN
  v_query := '';
  v_minindex := (v_startrowindex - 1) * v_maxrows + 1;
  v_maxindex := v_startrowindex * v_maxrows;
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp (RowNumber BIGINT GENERATED BY DEFAULT AS IDENTITY,
	PLID INT,
	LOGINID VARCHAR(1000),
	USERNAME VARCHAR(1000),
	FULLNAME VARCHAR(1000),
	FNAME VARCHAR(1000),
	LNAME VARCHAR(1000),
	PHONE VARCHAR(100),
	EMAILID VARCHAR(1000),
	REGNO INT,
	STATUS VARCHAR(50),
	REGDATE VARCHAR(100)) ON COMMIT DROP;
  v_query := 'Insert Into #TEMP SELECT PLID ,LOGINID ,USERNAME , (FNAME + '' ''+ IsNull(LNAME,'''')) AS FULLNAME,FNAME ,IsNull(LNAME,'''') As LName ,
	(Case When IsNull(PHONE,'''') = '''' Then ''N/A'' Else ''+ '' + Cast(C.ISDCODE As Varchar) + '' - ''+ PL.PHONE End) As Phone ,	
	EMAILID ,REGNO ,(Case When Active=1 Then ''Active'' Else ''Deactive'' End) As Status,
	CONVERT(VARCHAR(11),DOC,106) AS REGDATE FROM  PORTAL_LOGIN PL LEFT JOIN COUNTRY C ON C.CID = PL.CID  
	WHERE INTRO_REFID = ' || CAST(v_plid AS VARCHAR) || ' 
	AND ISNULL(ISREFERRALACCEPTED,0)=0 ';
  IF (v_fromdate <> '' AND v_todate <> '') THEN
  v_query := v_query || (' AND CONVERT(DATE,PL.DOC,103) BETWEEN CONVERT(DATE,''' || v_fromdate || ''',103) AND CONVERT(DATE,''' || v_todate || ''',103)');
  END IF;
  IF (v_fromdate <> '') THEN
  v_query := v_query || (' AND CONVERT(DATE,PL.DOC,103) >= CONVERT(DATE,''' || v_fromdate || ''',103)');
  END IF;
  IF (v_todate <> '') THEN
  v_query := v_query || (' AND CONVERT(DATE,PL.DOC,103) <= CONVERT(DATE,''' || v_todate || ''',103)');
  END IF;
  IF (v_username <> '') THEN
  v_query := v_query || (' AND PL.USERNAME LIKE ''%' || v_username || '%'' ');
  END IF;
  IF (v_emailid <> '') THEN
  v_query := v_query || (' AND PL.EMAILID LIKE ''%' || v_emailid || '%'' ');
  END IF;
  IF (v_phone <> '') THEN
  v_query := v_query || (' AND PL.PHONE LIKE ''%' || v_phone || '%'' ');
  END IF;
  EXECUTE v_query;
  IF (v_checkadminside = 1) THEN
  RETURN QUERY SELECT * FROM tmp_temp WHERE rownumber BETWEEN v_startrowindex AND v_maxrows;
  ELSE
  RETURN QUERY SELECT * FROM tmp_temp WHERE rownumber BETWEEN v_minindex AND v_maxindex;
  END IF;
  SELECT COUNT(rownumber) INTO v_totalcount FROM tmp_temp;
  DROP TABLE IF EXISTS tmp_temp;
END;
$$;


--
-- Name: usp_referraluseramount(integer, integer, character varying, boolean, character varying, character varying, character varying, character varying, integer, integer, character varying, character varying, character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_referraluseramount(v_startrowindex integer, v_maxrows integer, v_orderbyfield character varying, v_asc boolean, v_searchfield character varying, v_searchvalue character varying, v_fromdate character varying, v_todate character varying, v_mode integer, v_recordcount integer, v_cid character varying, v_usertpe character varying DEFAULT ''::character varying, v_amountorder character varying DEFAULT ''::character varying) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_sqlquery text;
  v_introplid bigint;
  v_orderbydateoramount varchar(50);
BEGIN
  -- SET option (removed)
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp (rowNumber int,
ipaddress varchar(100),
PLID bigint,
loginID varchar(150),
username varchar(100),
doc varchar(200),
refral_id varchar(150),
Active varchar(15),
country varchar(100),
Amount varchar(100),
Amount1 varchar(100),
qpayqlook varchar(100)) ON COMMIT DROP;
  DROP TABLE IF EXISTS tmp_temp1;
  CREATE TEMP TABLE tmp_temp1 (Amount varchar(100),
PLID bigint) ON COMMIT DROP;
  v_sqlquery := '';
  v_orderbydateoramount := '';
  IF (v_amountorder <> '') THEN
  IF (v_amountorder = 'asc') THEN
  v_orderbydateoramount := ' order by t2.amount asc ';
  END IF;
  IF (v_amountorder = 'desc') THEN
  v_orderbydateoramount := ' order by t2.amount desc ';
  END IF;
  ELSE
  v_orderbydateoramount := ' order by pl.doc desc ';
  END IF;
  INSERT INTO tmp_temp1 SELECT SUM(m.amount) AS amount, m.plid FROM portal_login AS l INNER JOIN member_perfornemce AS m ON l.plid = m.plid WHERE m.trantype = 'Referral Income' GROUP BY m.plid;
  v_sqlquery := 'insert into #temp select ROW_NUMBER() over(' || v_orderbydateoramount || ') as rowNumber,pl.ipaddress,pl.plid,pl.LoginId,isnull(pl.username,''-'') as username,
               convert(varchar(15),ISNULL(pl.DOC,''''),105) as doc,isnull(a2.LoginId,''-'') as refral_id,(case when pl.Active=1 then ''Active''else ''Deactive'' end) as  Active,
			   (case when c.countryName=''UNITED STATES'' then ''US'' when c.countryName=''UNITED KINGDOM'' then ''UK'' else  c.countryName end  ) as countryName,
			   isnull(t2.Amount,0.00),isnull(t2.Amount,0.00),(case when isnull(pl.qpayregno,0)= 0 then ''Qlook'' else ''Qpay'' end  ) as qpayqlook
			   from Portal_Login pl left join #temp1 t2 on pl.plid=t2.PLID Left join  (select refral_id,PLID from Portal_Login  where Active=1 ) as b on b.PLID=pl.intro_refid
			   left join Portal_Login a2 on a2.plid=pl.intro_refid left join COUNTRY c on c.CID=pl.cid where ISNULL(pl.refral_id,'''')!='''' ';
  IF (v_cid <> '') THEN
  v_sqlquery := v_sqlquery || (' and c.cid =' || v_cid || ' ');
  END IF;
  IF (v_fromdate = '' OR v_todate = '') THEN
  IF (v_fromdate <> '') THEN
  v_sqlquery := v_sqlquery || ' and convert(date,pl.doc,103)>=replace(convert(date,''' || v_fromdate || ''',103),''/'',''-'') ';
  END IF;
  IF (v_todate <> '') THEN
  v_sqlquery := v_sqlquery || ' and convert(date, pl.doc,103)<=replace(convert(date,''' || v_todate || ''',103),''/'',''-'') ';
  END IF;
  END IF;
  IF (v_fromdate <> '' AND v_todate <> '') THEN
  v_sqlquery := v_sqlquery || ' and  convert(date, pl.doc,103)  between  replace(convert(date,''' || v_fromdate || ''',103),''/'',''-'')  and replace(convert(date,''' || v_todate || ''',103),''/'',''-'')';
  END IF;
  IF (v_searchfield = 'loginid') THEN
  v_sqlquery := v_sqlquery || ' and pl.loginid like ''%' || v_searchvalue || '%''';
  END IF;
  IF (v_searchfield = 'referal') THEN
  v_sqlquery := v_sqlquery || ' and pl.refral_id like ''%' || v_searchvalue || '%''';
  END IF;
  IF (v_searchfield = 'username') THEN
  v_sqlquery := v_sqlquery || ' and pl.username like ''%' || v_searchvalue || '%''';
  END IF;
  IF (v_usertpe <> '') THEN
  IF (v_usertpe = 'qlook') THEN
  v_sqlquery := v_sqlquery || ' and ISNULL(pl.qpayregno,0)=0 ';
  END IF;
  IF (v_usertpe = 'qpay') THEN
  v_sqlquery := v_sqlquery || ' and ISNULL(pl.qpayregno,0)>0 ';
  END IF;
  END IF;
  EXECUTE v_sqlquery;
  SELECT COUNT(*) INTO v_recordcount FROM tmp_temp;
  RETURN QUERY SELECT * FROM tmp_temp WHERE rownumber BETWEEN v_startrowindex AND v_maxrows;
  DROP TABLE IF EXISTS tmp_temp1;
  DROP TABLE IF EXISTS tmp_temp;
  RETURN QUERY SELECT v_recordcount AS recordcount;
  -- SET option (removed)
END;
$$;


--
-- Name: usp_referraluserlist(integer, integer, character varying, boolean, character varying, character varying, date, date, integer, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_referraluserlist(v_startrowindex integer, v_maxrows integer, v_orderbyfield character varying, v_asc boolean, v_searchfield character varying, v_searchvalue character varying, v_txttodate date DEFAULT NULL::date, v_txtfromdate date DEFAULT NULL::date, v_mode integer DEFAULT NULL::integer, v_recordcount integer DEFAULT NULL::integer) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_regno bigint;
BEGIN
  -- SET option (removed)
  DROP TABLE IF EXISTS tmp_tempsushil;
  CREATE TEMP TABLE tmp_tempsushil ON COMMIT DROP AS SELECT ROW_NUMBER() OVER (ORDER BY doc DESC NULLS LAST) AS rownumber, a.plid, a.loginid, a.password, CAST(a.doc AS DATE) AS doc, COALESCE(a.refral_id, '-') AS refral_id, (b.refral_id) AS intro_refid, (CASE WHEN active = 1 THEN 'Active' ELSE 'Deactive' END) AS active FROM portal_login AS a LEFT JOIN (SELECT refral_id, plid FROM portal_login WHERE active = 1) AS b ON b.plid = a.intro_refid WHERE active = 1 AND a.intro_refid <> '' ORDER BY doc DESC NULLS LAST;
  IF (v_searchfield = 'loginid') THEN
  SELECT (SELECT COUNT(a.rownumber) FROM (SELECT * FROM tmp_tempsushil WHERE loginid LIKE '%' || v_searchvalue || '%') AS a) INTO v_recordcount;
  RETURN QUERY SELECT * FROM tmp_tempsushil WHERE loginid LIKE '%' || v_searchvalue || '%';
  RETURN;
  END IF;
  IF (v_searchfield = 'referal') THEN
  RETURN QUERY SELECT * FROM tmp_tempsushil WHERE refral_id LIKE '%' || v_searchvalue || '%';
  SELECT (SELECT COUNT(a.rownumber) FROM (SELECT * FROM tmp_tempsushil WHERE refral_id LIKE '%' || v_searchvalue || '%') AS a) INTO v_recordcount;
  RETURN;
  END IF;
  IF (v_txttodate <> '' AND v_txtfromdate <> '') THEN
  RETURN QUERY SELECT * FROM tmp_tempsushil WHERE doc BETWEEN v_txttodate AND v_txtfromdate;
  SELECT (SELECT COUNT(a.rownumber) FROM (SELECT * FROM tmp_tempsushil WHERE doc BETWEEN v_txttodate AND v_txtfromdate) AS a) INTO v_recordcount;
  RETURN;
  END IF;
  IF (v_searchfield = 'introreferal') THEN
  SELECT (SELECT COUNT(a.rownumber) FROM (SELECT * FROM tmp_tempsushil WHERE intro_refid LIKE '%' || v_searchvalue || '%') AS a) INTO v_recordcount;
  RETURN QUERY SELECT * FROM tmp_tempsushil WHERE intro_refid LIKE '%' || v_searchvalue || '%';
  RETURN;
  END IF;
  IF (v_searchfield = '') THEN
  RETURN QUERY SELECT * FROM tmp_tempsushil WHERE rownumber BETWEEN v_startrowindex AND v_maxrows;
  SELECT (SELECT COUNT(a.rownumber) FROM (SELECT * FROM tmp_tempsushil) AS a) INTO v_recordcount;
  RETURN;
  END IF;
  DROP TABLE IF EXISTS tmp_tempsushil;
  -- SET option (removed)
END;
$$;


