CREATE FUNCTION dbo.usp_refraldetails_new(v_fromdate character varying DEFAULT ''::character varying, v_todate character varying DEFAULT ''::character varying, v_pageno integer DEFAULT 1, v_pagesize integer DEFAULT 30, v_plid bigint DEFAULT NULL::bigint) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
