--
-- Name: usp_register_admin(integer, integer, character varying, boolean, character varying, character varying, character varying, character varying, character varying, integer, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_register_admin(v_startrowindex integer, v_maxrows integer, v_orderbyfield character varying, v_asc boolean, v_searchfield character varying, v_searchvalue character varying, v_cid character varying DEFAULT ''::character varying, v_fromdate character varying DEFAULT ''::character varying, v_todate character varying DEFAULT ''::character varying, v_mode integer DEFAULT NULL::integer, v_recordcount integer DEFAULT NULL::integer) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_pmid int;
  v_sqlquery text;
BEGIN
  -- SET option (removed)
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp (rowNumber bigint,

PLID bigint,

userName varchar(100),

loginID varchar(150),

password varchar(100),

doc varchar(35),

countryName varchar(50)) ON COMMIT DROP;
  v_sqlquery := '';
  v_sqlquery := 'insert into #temp select ROW_NUMBER() OVER(ORDER BY PL.DOC desc) as rowNumber,PL.PLID,isnull(PL.userName,'''') as userName,PL.loginID,PL.password,

 convert(varchar, PL.DOC, 105) as doc,C.countryName from COUNTRY C join Portal_Login PL on PL.cid=C.CID

 where PL.Active=0 and isnull(PL.cid,0)>0';
  IF (v_cid <> '') THEN
  v_sqlquery := v_sqlquery || (' and ('',''+convert(varchar(50),PL.cid)+'','') like  ''%,' || '' || CAST(v_cid AS text) || '' || ',%''');
  END IF;
  IF (v_fromdate = '' OR v_todate = '') THEN
  IF (v_fromdate <> '') THEN
  v_sqlquery := v_sqlquery || ' and convert(date, PL.doc,103) =replace(convert(VARCHAR(10),''' || v_fromdate || ''',111),''/'',''-'') ';
  END IF;
  IF (v_todate <> '') THEN
  v_sqlquery := v_sqlquery || ' and convert(date, PL.doc,103)  =replace(convert(VARCHAR(10),''' || v_todate || ''',111),''/'',''-'') ';
  END IF;
  END IF;
  IF (v_fromdate <> '' AND v_todate <> '') THEN
  v_sqlquery := v_sqlquery || ' and convert(date, PL.doc,103)  between  replace(convert(VARCHAR(10),''' || v_fromdate || ''',111),''/'',''-'')  and replace(convert(VARCHAR(10),''' || v_todate || ''',111),''/'',''-'')';
  END IF;
  IF (v_searchfield = 'loginid') THEN
  v_sqlquery := v_sqlquery || 'and PL.loginID like ''%' || v_searchvalue || '%''';
  END IF;
  IF (v_searchfield = 'countryName') THEN
  v_sqlquery := v_sqlquery || 'and C.countryName like ''%' || v_searchvalue || '%''';
  END IF;
  IF (v_searchfield = 'userName') THEN
  v_sqlquery := v_sqlquery || 'and PL.userName like ''%' || v_searchvalue || '%''';
  END IF;
  EXECUTE v_sqlquery;
  SELECT COUNT(*) INTO v_recordcount FROM tmp_temp;
  RETURN QUERY SELECT * FROM tmp_temp WHERE rownumber BETWEEN v_startrowindex AND v_maxrows;
  DROP TABLE IF EXISTS tmp_temp;
  RETURN QUERY SELECT v_recordcount AS recordcount;
  -- SET option (removed)
END;
$$;


--
-- Name: usp_register_admin_new(integer, integer, character varying, boolean, character varying, character varying, character varying, character varying, character varying, integer, integer, character varying, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_register_admin_new(v_startrowindex integer DEFAULT 1, v_maxrows integer DEFAULT 100, v_orderbyfield character varying DEFAULT ''::character varying, v_asc boolean DEFAULT false, v_searchfield character varying DEFAULT ''::character varying, v_searchvalue character varying DEFAULT ''::character varying, v_cid character varying DEFAULT ''::character varying, v_fromdate character varying DEFAULT ''::character varying, v_todate character varying DEFAULT ''::character varying, v_mode integer DEFAULT 0, v_recordcount integer DEFAULT 0, v_mobile character varying DEFAULT ''::character varying, v_orderby integer DEFAULT 1) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_pmid INT;
  v_sqlquery text;
  v_minindex INT;
  v_maxindex INT;
  v_newusername varchar(200);
BEGIN
  -- SET option (removed)
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp (ROWNUMBER BIGINT GENERATED BY DEFAULT AS IDENTITY,
PLID BIGINT,
USERNAME VARCHAR(200),
LOGINID VARCHAR(200),
PASSWORD VARCHAR(200),
DOC VARCHAR(50),
COUNTRYNAME VARCHAR(100),
JOINEDVIA VARCHAR(2000),
IPADDRESS VARCHAR(100),
NAME VARCHAR(200),
MOBILE  VARCHAR(50),
Email varchar(500)) ON COMMIT DROP;
  v_sqlquery := '';
  v_minindex := (v_startrowindex - 1) * v_maxrows + 1;
  v_maxindex := v_startrowindex * v_maxrows;
  v_sqlquery := 'INSERT INTO #TEMP SELECT PL.PLTID,ISNULL(PL.USERNAME,'''') AS USERNAME,PL.LOGINID,PL.PASSWORD,
                 FORMAT(PL.DOC,''dd-MMM-yyyy hh:mm:ss tt'') AS DOC,(CASE WHEN C.COUNTRYNAME=''UNITED STATES'' THEN ''US'' WHEN C.COUNTRYNAME=''UNITED KINGDOM'' THEN ''UK'' 
				 ELSE  C.COUNTRYNAME END  ) AS COUNTRYNAME,
				 (Case When PL.IPADDRESS=''By Admin'' Then ''Admin'' When PL.INTRO_REFID=0 Then ''Direct'' When PL.INTRO_REFID>0 Then ''Customer Referrals'' END) As JoinedVia
				 ,ISNULL(PL.IPADDRESS,''-'') AS IPADDRESS,ISNULL(SP_FIRSTNAME+SP_LASTNAME,'''' )AS FULLNAME,PL.PHONE,PL.EmailId
				  FROM COUNTRY C JOIN CUSTOMER_LOGIN_TEMP PL ON PL.CID=C.CID 
				 WHERE PL.ACTIVE=0 AND ISNULL(PL.CID,0)>0';
  IF (v_cid <> '') THEN
  v_sqlquery := v_sqlquery || (' AND ('',''+CONVERT(VARCHAR(50),PL.CID)+'','') LIKE  ''%,' || '' || CAST(v_cid AS text) || '' || ',%''');
  END IF;
  IF (v_fromdate = '' OR v_todate = '') THEN
  IF (v_fromdate <> '') THEN
  v_sqlquery := v_sqlquery || ' AND CONVERT(DATE, PL.DOC,103) >= REPLACE(CONVERT(DATE,''' || v_fromdate || ''',103),''/'',''-'') ';
  END IF;
  IF (v_todate <> '') THEN
