                 FORMAT(PL.DOC,''dd-MMM-yyyy hh:mm:ss tt'') AS DOC,(CASE WHEN C.COUNTRYNAME=''UNITED STATES'' THEN ''US'' WHEN C.COUNTRYNAME=''UNITED KINGDOM'' THEN ''UK'' 
