				 ,ISNULL(PL.IPADDRESS,''-'') AS IPADDRESS,ISNULL(SP_FIRSTNAME,'''')+''  ''+ISNULL(SP_LASTNAME,'''' )AS FULLNAME,PL.PHONE,PL.EmailId,TD.DID
				  FROM COUNTRY C JOIN CUSTOMER_LOGIN_TEMP PL ON PL.CID=C.CID 
				  join TBL_DISTRIBUTOR TD ON TD.DID=PL.DID
				 WHERE PL.ACTIVE=0 AND ISNULL(PL.CID,0)>0';
  IF (v_cid <> '') THEN
  v_sqlquery := v_sqlquery || (' AND ('',''+CONVERT(VARCHAR(50),PL.CID)+'','') LIKE  ''%,' || '' || CAST(v_cid AS text) || '' || ',%''');
  END IF;
  IF (v_fromdate = '' OR v_todate = '') THEN
  IF (v_fromdate <> '') THEN
  v_sqlquery := v_sqlquery || ' AND CONVERT(DATE, PL.DOC,103) >= REPLACE(CONVERT(DATE,''' || v_fromdate || ''',103),''/'',''-'') ';
  END IF;
  IF (v_todate <> '') THEN
  v_sqlquery := v_sqlquery || ' AND CONVERT(DATE, PL.DOC,103)  <=REPLACE(CONVERT(DATE,''' || v_todate || ''',103),''/'',''-'') ';
  END IF;
  END IF;
  IF (v_fromdate <> '' AND v_todate <> '') THEN
  v_sqlquery := v_sqlquery || '  AND  CONVERT(DATE, PL.DOC,103)  BETWEEN  REPLACE(CONVERT(DATE,''' || v_fromdate || ''',103),''/'',''-'')  AND REPLACE(CONVERT(DATE,''' || v_todate || ''',103),''/'',''-'')';
  END IF;
  IF (v_mobile <> '') THEN
  v_sqlquery := v_sqlquery || 'AND PL.PHONE LIKE ''%' || v_mobile || '%''';
  END IF;
  IF (v_searchfield = 'LOGINID') THEN
  v_sqlquery := v_sqlquery || 'AND PL.LOGINID LIKE ''%' || v_searchvalue || '%''';
  END IF;
  IF (v_searchfield = 'REFERAL') THEN
  v_sqlquery := v_sqlquery || ' AND PL.LOGINID LIKE ''%' || v_searchvalue || '%'' ';
  END IF;
  IF (v_searchfield = 'COUNTRYNAME') THEN
  v_sqlquery := v_sqlquery || 'AND C.COUNTRYNAME LIKE ''%' || v_searchvalue || '%''';
  END IF;
  IF (v_searchfield = 'USERNAME') THEN
  IF (EXISTS(SELECT 1 FROM customer_login_temp WHERE username = v_searchvalue)) THEN
  v_sqlquery := v_sqlquery || (' AND PL.USERNAME LIKE ''%' || v_searchvalue || '%''');
  ELSE
  IF (EXISTS(SELECT 1 FROM portal_login_history WHERE username = v_searchvalue)) THEN
  v_newusername := '';
  SELECT (SELECT username FROM tbl_customerlogin WHERE clid IN (SELECT plid FROM portal_login_history WHERE username = v_searchvalue)) INTO v_newusername;
  v_sqlquery := v_sqlquery || (' AND PL.USERNAME LIKE ''%' || v_newusername || '%''');
  ELSE
  v_sqlquery := v_sqlquery || ' AND PL.USERNAME LIKE ''%' || v_searchvalue || '%'' ';
  END IF;
  END IF;
  END IF;
  IF (v_searchfield = 'Email') THEN
  v_sqlquery := v_sqlquery || ' AND PL.EmailId = ''' || v_searchvalue || ''' ';
  END IF;
  IF (v_searchfield = 'MOBILE') THEN
  v_sqlquery := v_sqlquery || ' AND PL.PHONE= ''' || v_searchvalue || ''' ';
  END IF;
  IF (v_did > 0) THEN
  v_sqlquery := v_sqlquery || ' AND TD.DID =' || CAST(v_did AS VARCHAR(30)) || ' ';
  END IF;
  IF (v_orderby = 0) THEN
  v_sqlquery := v_sqlquery || '  ORDER BY   PL.DOC DESC  ';
  END IF;
  IF (v_orderby = 1) THEN
  v_sqlquery := v_sqlquery || '  ORDER BY   PL.DOC  ASC';
  END IF;
  IF (v_orderby = 2) THEN
  v_sqlquery := v_sqlquery || '  ORDER BY   PL.DOC DESC  ';
  END IF;
  EXECUTE v_sqlquery;
  RETURN QUERY SELECT * FROM tmp_temp WHERE rownumber BETWEEN v_minindex AND v_maxindex;
  SELECT COUNT(rownumber) INTO v_recordcount FROM tmp_temp;
  DROP TABLE IF EXISTS tmp_temp;
  -- SET option (removed)
END;
$$;


