--
-- Name: usp_relatedblog(bigint); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_relatedblog(v_id bigint DEFAULT 1) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_i INT;
  v_totalcount INT;
  v_catid INT;
  v_catid1 text;
  v_slice1 text;
  v_index1 INT;
  v_slice2 text;
  v_totalcount1 INT;
  v_i1 INT;
  v_blogid BIGINT;
  v_category VARCHAR(100);
  v_blogtitle VARCHAR(500);
  v_blogwriter VARCHAR(100);
  v_dat VARCHAR(100);
  v_canonicalurl text;
BEGIN
  v_i := 0;
  v_slice1 := '';
  v_index1 := 1;
  v_slice2 := '';
  v_canonicalurl := '';
  DROP TABLE IF EXISTS tmp_temp1;
  CREATE TEMP TABLE tmp_temp1 (ROWNUMBER INT GENERATED BY DEFAULT AS IDENTITY,

		CATID BIGINT) ON COMMIT DROP;
  DROP TABLE IF EXISTS tmp_temp2;
  CREATE TEMP TABLE tmp_temp2 (ROWNUMBER INT GENERATED BY DEFAULT AS IDENTITY,

	BLOGID BIGINT,

	CATEGORY text,

	BLOGTITLE text,

	CANONICALURL text,

	BLOGWRITER text,

	DAT text) ON COMMIT DROP;
  DROP TABLE IF EXISTS tmp_temp3;
  CREATE TEMP TABLE tmp_temp3 (ROWNUMBER INT GENERATED BY DEFAULT AS IDENTITY,

	BLOGID BIGINT,

	CATEGORY text,

	BLOGTITLE text,

	CANONICALURL text,

	BLOGWRITER text,

	DAT text) ON COMMIT DROP;
  SELECT COALESCE(category, '') INTO v_catid1 FROM tbl_blogmaster WHERE blogid = v_id;
  IF (v_catid1 <> '') THEN
  SELECT v_catid1 INTO v_slice1;
  WHILE v_index1 <> 0 LOOP
  SELECT POSITION(',' IN v_slice1) INTO v_index1;
  IF v_index1 <> 0 THEN
  SELECT LEFT(CAST(v_slice1 AS TEXT), v_index1 - 1) INTO v_slice2;
  ELSE
  SELECT v_slice1 INTO v_slice2;
  END IF;
  IF (v_slice2 <> 0) THEN
  INSERT INTO tmp_temp1 (catid) VALUES (v_slice2);
  END IF;
  SELECT RIGHT(CAST(v_slice1 AS TEXT), LENGTH(CAST(v_slice1 AS TEXT)) - v_index1) INTO v_slice1;
  IF LENGTH(CAST(v_slice1 AS TEXT)) = 0 THEN
  EXIT;
  END IF;
  END LOOP;
  END IF;
  SELECT COUNT(*) INTO v_totalcount FROM tmp_temp1;
  v_i := 1;
  WHILE (v_i <= v_totalcount) LOOP
  SELECT catid INTO v_catid FROM tmp_temp1 WHERE rownumber = v_i;
  INSERT INTO tmp_temp2 SELECT blogid, category, (UPPER(LEFT(CAST(blogtitle AS TEXT), 1)) || LOWER(SUBSTRING(blogtitle FROM 2 FOR LENGTH(CAST(blogtitle AS TEXT))))) AS blogtitle, canonicalurl, (UPPER(LEFT(CAST(blogwriter AS TEXT), 1)) || LOWER(SUBSTRING(blogwriter FROM 2 FOR LENGTH(CAST(blogwriter AS TEXT))))) AS blogwriter, CAST(TO_CHAR(blogcreationdate, 'DD TMMon YYYY') AS VARCHAR(13)) AS dat FROM tbl_blogmaster WHERE status = 1 AND publishstatus = 1 AND draftstatus = 0 AND ((category IN (CAST(v_catid AS text))) OR (category LIKE ('%,' || CAST(v_catid AS text) || ',%')) OR (category LIKE ('%' || CAST(v_catid AS text) || ',%')) OR (category LIKE ('%,' || CAST(v_catid AS text))));
  v_i := v_i + 1;
  END LOOP;
  SELECT COUNT(*) INTO v_totalcount1 FROM tmp_temp2;
  v_i1 := 1;
  WHILE (v_i1 <= v_totalcount1) LOOP
  SELECT blogid, category, blogtitle, blogwriter, dat, canonicalurl INTO v_blogid, v_category, v_blogtitle, v_blogwriter, v_dat, v_canonicalurl FROM tmp_temp2 WHERE rownumber = v_i1;
  IF NOT EXISTS(SELECT blogid FROM tmp_temp3 WHERE blogid = v_blogid) THEN
  INSERT INTO tmp_temp3 (blogid, category, blogtitle, canonicalurl, blogwriter, dat) VALUES (v_blogid, v_category, v_blogtitle, v_canonicalurl, v_blogwriter, v_dat);
  END IF;
  v_i1 := v_i1 + 1;
  END LOOP;
  RETURN QUERY SELECT * FROM tmp_temp3 WHERE blogid <> v_id ORDER BY blogid DESC NULLS LAST LIMIT 7;
  DROP TABLE IF EXISTS tmp_temp1;
  DROP TABLE IF EXISTS tmp_temp2;
  DROP TABLE IF EXISTS tmp_temp3;
END;
$$;


--
-- Name: usp_releasedbv(character varying, character varying, character varying, character varying, character varying, character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_releasedbv(v_fromdate character varying DEFAULT '2018-11-14'::character varying, v_todate character varying DEFAULT ''::character varying, v_memberid character varying DEFAULT ''::character varying, v_orderid character varying DEFAULT ''::character varying, v_loginid character varying DEFAULT ''::character varying, v_did character varying DEFAULT '2'::character varying) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_query text;
  v_intcontinue int;
  v_batchid varchar(200);
  v_chars varchar(200);
BEGIN
  v_query := '';
  v_intcontinue := 0;
  v_batchid := '';
  v_chars := '';
  SELECT 0 INTO v_intcontinue;
  v_chars := N'8123456789';
  WHILE (v_intcontinue = 0) LOOP
  v_batchid := SUBSTRING(v_chars FROM CAST((RANDOM() * LENGTH(CAST(v_chars AS TEXT))) AS INT) + 1 FOR 1) || SUBSTRING(v_chars FROM CAST((RANDOM() * LENGTH(CAST(v_chars AS TEXT))) AS INT) + 1 FOR 1) || SUBSTRING(v_chars FROM CAST((RANDOM() * LENGTH(CAST(v_chars AS TEXT))) AS INT) + 1 FOR 1) || SUBSTRING(v_chars FROM CAST((RANDOM() * LENGTH(CAST(v_chars AS TEXT))) AS INT) + 1 FOR 1) || SUBSTRING(v_chars FROM CAST((RANDOM() * LENGTH(CAST(v_chars AS TEXT))) AS INT) + 1 FOR 1) || SUBSTRING(v_chars FROM CAST((RANDOM() * LENGTH(CAST(v_chars AS TEXT))) AS INT) + 1 FOR 1) || SUBSTRING(v_chars FROM CAST((RANDOM() * LENGTH(CAST(v_chars AS TEXT))) AS INT) + 1 FOR 1) || SUBSTRING(v_chars FROM CAST((RANDOM() * LENGTH(CAST(v_chars AS TEXT))) AS INT) + 1 FOR 1);
  v_intcontinue := 1;
  END LOOP;
  v_query := '  select distinct PM.ORDERNO,PM.Total_Purchase_Cost as Amount,cast((CM.BVRate * PM.Total_BV) as decimal(18,2)) as  BV,
	                CONVERT(varchar(10), OM.orderdate,110) as OrderDate,isnull(cast (OM.PayidforwordAffiliateID as varchar(20)),'''') as UserName,''' || v_batchid || ''' as BatchID from tbl_order_master   as OM
					inner join tbl_product_order_master as PM on OM.OrderID=PM.OrderId
					inner join TBL_CUSTOMERLOGIN as CL on CL.Loginid=om.loginid
					inner join TBL_DISTRIBUTOR as dm on dm.DID=cl.DID
					inner join TBL_COMPANYSETTINGS as CM on CM.pmid=dm.pmid
					where OM.IsBVDist=0 and om.IntStatus=6 and cl.DID=' || v_did || '';
  IF (v_fromdate <> '' AND v_todate <> '') THEN
  v_query := v_query || ' AND CONVERT(DATE, OM.OrderDate) BETWEEN CONVERT(DATE, ''' || v_fromdate || ''') AND  CONVERT(DATE, ''' || v_todate || ''')';
  END IF;
  IF ((v_fromdate <> '') AND (v_todate = '')) THEN
  v_query := v_query || ' AND CONVERT(DATE, OM.OrderDate) =  CONVERT(DATE, ''' || v_fromdate || ''')';
  END IF;
  IF ((v_fromdate = '') AND (v_todate <> '')) THEN
  v_query := v_query || ' AND CONVERT(DATE, OM.OrderDate) =  CONVERT(DATE, ''' || v_todate || ''') ';
  END IF;
  IF (v_memberid <> '') THEN
  v_query := v_query || ('   and OM.PayidforwordAffiliateID=' || v_memberid || '');
  END IF;
  IF (v_orderid <> '') THEN
  v_query := v_query || ('   and OM.OrderID=''' || v_orderid || '''');
  END IF;
  IF (v_loginid <> '') THEN
  v_query := v_query || ('   and OM.LoginId=''' || v_loginid || '''');
  END IF;
  EXECUTE v_query;
END;
$$;


--
-- Name: usp_releasedbv_updatestatus(character varying, character varying, character varying, character varying, character varying, character varying, character varying, integer, character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_releasedbv_updatestatus(v_fromdate character varying DEFAULT '2018-11-13'::character varying, v_todate character varying DEFAULT ''::character varying, v_memberid character varying DEFAULT ''::character varying, v_orderid character varying DEFAULT ''::character varying, v_loginid character varying DEFAULT ''::character varying, v_batchid character varying DEFAULT ''::character varying, v_ip_address character varying DEFAULT ''::character varying, v_did integer DEFAULT 2, INOUT v_spout character varying DEFAULT ''::character varying) RETURNS character varying
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_query text;
  v_selectquery text;
  v_count int;
  v_inc int;
  v_order_no varchar(50);
  v_bvrate decimal(18,8);
  v_relasedbv decimal(18,8);
BEGIN
  BEGIN
  -- SET option (removed)
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp (Rownumber int GENERATED BY DEFAULT AS IDENTITY,
orderno varchar(50),
RelasedBV decimal(18,2)) ON COMMIT DROP;
  v_query := '';
  v_selectquery := '';
  v_count := 0;
  v_inc := 1;
  v_order_no := '';
  v_bvrate := 0;
  v_relasedbv := 0;
  v_query := ' UPDATE tbl_order_master SET IsBVDist=1 WHERE  IsBVDist=0 and IntStatus=6  ';
  v_selectquery := 'insert into #temp  select PM.ORDERNO,isnull(PM.Total_BV,0) as  RelasedBV from tbl_order_master as OM
	inner join tbl_product_order_master as PM on OM.OrderID=PM.OrderId
	inner join TBL_CUSTOMERLOGIN as CL on Cl.loginid=PM.LoginID 
	where IsBVDist=0 and OM.IntStatus=6 and cl.DID=' || CAST(v_did AS VARCHAR) || '';
  IF (v_fromdate <> '' AND v_todate <> '') THEN
  v_query := v_query || ' AND CONVERT(DATE, OrderDate) BETWEEN CONVERT(DATE, ''' || v_fromdate || ''') AND  CONVERT(DATE, ''' || v_todate || ''')';
  v_selectquery := v_selectquery || ' AND CONVERT(DATE, OM.OrderDate) BETWEEN CONVERT(DATE, ''' || v_fromdate || ''') AND  CONVERT(DATE, ''' || v_todate || ''')';
  END IF;
  IF ((v_fromdate <> '') AND (v_todate = '')) THEN
  v_query := v_query || ' AND CONVERT(DATE, OrderDate) =  CONVERT(DATE, ''' || v_fromdate || ''')';
  v_selectquery := v_selectquery || ' AND CONVERT(DATE, OM.OrderDate) =  CONVERT(DATE, ''' || v_fromdate || ''')';
  END IF;
  IF ((v_fromdate = '') AND (v_todate <> '')) THEN
  v_query := v_query || ' AND CONVERT(DATE, OrderDate) =  CONVERT(DATE, ''' || v_todate || ''') ';
  v_selectquery := v_selectquery || ' AND CONVERT(DATE, OM.OrderDate) =  CONVERT(DATE, ''' || v_todate || ''') ';
  END IF;
  IF (v_memberid <> '') THEN
  v_query := v_query || ('   and PayidforwordAffiliateID=' || v_memberid || '');
  v_selectquery := v_selectquery || ('   and OM.PayidforwordAffiliateID=' || v_memberid || '');
  END IF;
  IF (v_orderid <> '') THEN
  v_query := v_query || ('   and OrderID=''' || v_orderid || '''');
  v_selectquery := v_selectquery || ('   and OM.OrderID=''' || v_orderid || '''');
  END IF;
  IF (v_loginid <> '') THEN
  v_query := v_query || ('   and LoginId=''' || v_loginid || '''');
  v_selectquery := v_selectquery || ('   and OM.LoginId=''' || v_loginid || '''');
  END IF;
  EXECUTE v_selectquery;
  EXECUTE v_query;
  SELECT COALESCE(CAST(bvrate AS DECIMAL(18, 2)), 0) INTO v_bvrate FROM tbl_companysettings WHERE pmid = v_did;
  SELECT COALESCE(COUNT(1), 0) INTO v_count FROM tmp_temp;
  WHILE (v_inc <= v_count) LOOP
  SELECT orderno, relasedbv INTO v_order_no, v_relasedbv FROM tmp_temp WHERE rownumber = v_inc;
  UPDATE tbl_resellerreleasebvdetails SET isresellerrelease = 1, resellerreleasebatch = v_batchid, ipaddress_reseller = v_ip_address, resellerreleasedate = dbo.FUN_GETCURRENTDATE(), rateofbv = v_bvrate, releasebv = v_relasedbv WHERE orderno = v_order_no;
  v_inc := v_inc + 1;
  v_spout := 'success';
  END LOOP;
  DROP TABLE IF EXISTS tmp_temp;
  -- SET option (removed)
  EXCEPTION WHEN OTHERS THEN
  PERFORM dbo.sp_errorlog();
  v_spout := 'error';
  IF (0 > 0) THEN
  -- ROLLBACK (removed)
  END IF;
  RETURN;
  END;
END;
$$;


