--
-- Name: usp_removecartaftershopping(integer, bigint, integer, character varying, character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_removecartaftershopping(v_tkpmid integer DEFAULT 0, v_regno bigint DEFAULT 0, v_mode integer DEFAULT 0, INOUT v_stroutput character varying DEFAULT ''::character varying, v_uidno character varying DEFAULT ''::character varying) RETURNS character varying
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF (v_mode = 1) THEN
  IF EXISTS(SELECT 1 FROM dbo.tbl_addtocart WHERE status = 1 AND (sessionid = v_uidno OR clid = v_regno)) THEN
  UPDATE dbo.tbl_addtocart SET status = 0, createddate = dbo.FUN_GETCURRENTDATE() WHERE status = 1 AND sprid = v_tkpmid AND (sessionid = v_uidno OR clid = v_regno);
  v_stroutput := 'SUCCESS';
  ELSE
  v_stroutput := 'Item does not exists in your cart';
  END IF;
  END IF;
END;
$$;


--
-- Name: usp_removeexpiredads(bigint); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_removeexpiredads(v_plid bigint) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_count int;
  v_count1 int;
  v_remain_ads int;
  v_expirydate timestamp;
  v_madsid bigint;
BEGIN
  -- BEGIN TRAN (removed)
  IF EXISTS(SELECT 1 FROM tbl_memberadsdetails WHERE plid = v_plid AND status = 1) THEN
  DROP TABLE IF EXISTS tmp_tempsibglerec;
  CREATE TEMP TABLE tmp_tempsibglerec ON COMMIT DROP AS SELECT ROW_NUMBER() OVER (ORDER BY madsid ASC NULLS FIRST) AS rno, madsid, exprdate, remain_ads FROM tbl_memberadsdetails WHERE plid = v_plid AND status = 1 ORDER BY madsid ASC NULLS FIRST;
  v_count := 1;
  SELECT COUNT(1) INTO v_count1 FROM tmp_tempsibglerec;
  WHILE (v_count <= v_count1) LOOP
  SELECT COALESCE(remain_ads, 0), COALESCE(exprdate, 0), madsid INTO v_remain_ads, v_expirydate, v_madsid FROM tmp_tempsibglerec WHERE rno = v_count;
  IF (v_expirydate <= dbo.fun_getCurrentDate()) THEN
  UPDATE tbl_memberadsdetails SET expired_ads = COALESCE(expired_ads, 0) + v_remain_ads, remain_ads = 0 WHERE madsid = v_madsid;
  END IF;
  v_count := v_count + 1;
  END LOOP;
  DROP TABLE IF EXISTS tmp_tempsibglerec;
  END IF;
  IF (0 <> 0) THEN
  -- ROLLBACK (removed)
  RETURN;
  END IF;
  -- COMMIT (removed)
END;
$$;


--
-- Name: usp_reseller_bv_pv_commission(character varying, character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_reseller_bv_pv_commission(v_orderno character varying DEFAULT ''::character varying, INOUT v_strresult character varying DEFAULT ''::character varying) RETURNS character varying
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_orderstatus INT;
  v_orderbv DECIMAL(18,8);
  v_did INT;
  v_loginid VARCHAR(20);
  v_mode INT;
  v_orderid VARCHAR(50);
  v_subprcode VARCHAR(100);
  v_maincatid INT;
  v_subcatid INT;
  v_catid INT;
  v_bv DECIMAL(18,2);
  v_pv DECIMAL(18,2);
  v_comid INT;
  v_realcommission DECIMAL(18,2);
  v_totalpurchasecost DECIMAL(18,2);
BEGIN
  -- BEGIN TRAN (removed)
  v_orderbv := 0;
  v_did := 0;
  v_loginid := '';
  v_mode := 0;
  v_orderid := '';
  v_subprcode := '';
  v_maincatid := 0;
  v_subcatid := 0;
  v_catid := 0;
  v_bv := 0;
  v_pv := 0;
  v_comid := 0;
  v_realcommission := 0;
  v_totalpurchasecost := 0;
  SELECT COALESCE(intstatus, 0), COALESCE(loginid, ''), COALESCE(orderid, ''), COALESCE(subprcode, 0), COALESCE(total_purchase_cost, 0) INTO v_orderstatus, v_loginid, v_orderid, v_subprcode, v_totalpurchasecost FROM tbl_product_order_master WHERE orderno = v_orderno;
  SELECT COALESCE(did, 0) INTO v_did FROM tbl_customerlogin WHERE loginid = v_loginid;
  SELECT COALESCE(maincategoryid, 0), COALESCE(subcategoryid, 0), COALESCE(catid, 0) INTO v_maincatid, v_subcatid, v_catid FROM ims_masterproduct WHERE mprid IN (SELECT mprid FROM ims_subproduct WHERE sprid = v_subprcode);
  SELECT COALESCE(bv, 0), COALESCE(pv, 0), COALESCE(commission, 0) INTO v_bv, v_pv, v_realcommission FROM tbl_product_wise_bv_pv_setting WHERE maincatid = v_maincatid AND subcatid = v_subcatid AND catid = v_catid AND did = v_did;
  IF NOT EXISTS(SELECT 1 FROM tbl_reseller_bv_pv_master WHERE orderid = v_orderid) THEN
  INSERT INTO tbl_reseller_bv_pv_master (orderid, totalcommission, totalbv, totalpv, status, type, did, create_date) VALUES (v_orderid, v_realcommission, v_bv, v_pv, 1, 2, v_did, dbo.FUN_GETCURRENTDATE());
  ELSE
  UPDATE tbl_reseller_bv_pv_master SET totalbv = (totalbv + v_bv), totalpv = (totalpv + v_pv), totalcommission = (totalcommission + v_realcommission) WHERE orderid = v_orderid;
  END IF;
  SELECT MAX(comid) INTO v_comid FROM tbl_reseller_bv_pv_master;
  IF NOT EXISTS(SELECT 1 FROM tbl_reseller_bv_pv_details WHERE orderno = v_orderno) THEN
  INSERT INTO tbl_reseller_bv_pv_details (comid, orderno, commissionpercentage, commissionvalue, bvpercentage, bvalue, pvpercentage, pvalue, status, type, releasedstatus, create_date) VALUES (v_comid, v_orderno, v_realcommission, (v_totalpurchasecost * v_realcommission) / 100, v_bv, (v_totalpurchasecost * v_bv) / 100, v_pv, (v_totalpurchasecost * v_pv) / 100, 1, 2, 0, dbo.FUN_GETCURRENTDATE());
  END IF;
  IF (0 > 0) THEN
  v_strresult := 'ERROR';
  -- ROLLBACK (removed)
  RETURN;
  END IF;
  -- COMMIT (removed)
END;
$$;


--
-- Name: usp_reseller_clubhistory_list(integer, integer, character varying, character varying, character varying, character varying, character varying, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_reseller_clubhistory_list(v_startrowindex integer DEFAULT 1, v_maxrows integer DEFAULT 100, v_fromdate character varying DEFAULT ''::character varying, v_todate character varying DEFAULT ''::character varying, v_status character varying DEFAULT ''::character varying, v_searchfield character varying DEFAULT ''::character varying, v_searchvalue character varying DEFAULT ''::character varying, v_totalrecord integer DEFAULT 0) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_query text;
  v_maxregno text;
  v_query1 text;
  v_minindex INT;
  v_maxindex INT;
BEGIN
  -- SET option (removed)
  v_query := '';
  v_maxregno := '';
  v_query1 := '';
  v_minindex := (v_startrowindex - 1) * v_maxrows + 1;
  v_maxindex := v_startrowindex * v_maxrows;
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp (ROWNUMBER BIGINT,
	  FILENAME VARCHAR(150),
	  DATE timestamp,
	  CLUBGROUP VARCHAR(150),
	  TOTALREQUEST INT,
	  TOTALAMOUNT DECIMAL(18,8),
	  TOTAL_TANSACTION DECIMAL(18,8),
	  PROCESSDATE timestamp,
	  PROCESSBY VARCHAR(50),
	  PROCESSSTATUS VARCHAR(50),
	  PROCESSIPADDRESS VARCHAR(50),
	  BANKNAME VARCHAR(200),
	  TOTALPAID INT,
	  TOTALREJECT INT,
	  TRANSACTION_NO INT) ON COMMIT DROP;
  v_query := 'INSERT INTO #TEMP Select row_number()over(order by CHID desc) as RowNumber,FileName,convert(date,Date,105) as Date,
ClubGroup,TotalRequest,TotalAmount,Total_tansaction,
convert(date,ProcessDate,105) as ProcessDate,ProcessBy,ProcessStatus,ProcessIPAddress,BankName,
(select isnull(COUNT(distinct DID),0)  from TBL_RESELLER_TRANSFERTOBANK_REQUEST  where  status=1 and TRTBWID in  (select * from SplitString(AllWDID,'',''))) as TotalPaid,
(select isnull(COUNT(distinct DID),0)  from TBL_RESELLER_TRANSFERTOBANK_REQUEST  where  status=2 and TRTBWID in  (select * from SplitString(AllWDID,'',''))) as TotalReject,0
from TBL_RESELLER_CLUBHISTORY WHERE 1=1 ';
  RAISE NOTICE '%', v_query;
  EXECUTE v_query;
  SELECT COALESCE(COUNT(1), 0) INTO v_totalrecord FROM tmp_temp;
  RETURN QUERY SELECT * FROM tmp_temp ORDER BY rownumber ASC NULLS FIRST;
  DROP TABLE IF EXISTS tmp_temp;
  -- SET option (removed)
END;
$$;


--
-- Name: usp_reseller_comission_available(integer, numeric, numeric, numeric, numeric); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_reseller_comission_available(v_did integer DEFAULT 8, INOUT v_totalbalance numeric DEFAULT 0, INOUT v_withdrwal numeric DEFAULT 0, INOUT v_balance numeric DEFAULT 0, INOUT v_credit numeric DEFAULT 0) RETURNS record
    LANGUAGE plpgsql
    AS $$
BEGIN
  -- BEGIN TRAN (removed)
  -- SET option (removed)
  SELECT COALESCE(SUM(cr), 0) INTO v_totalbalance FROM tbl_reseller_commission_wallet WHERE did = v_did AND status = 1 AND finalupdate = 1;
  IF (v_totalbalance > 0) THEN
  SELECT COALESCE(SUM(amount), 0) INTO v_withdrwal FROM tbl_reseller_transfertobank_request WHERE transferrequest = 0 AND status = 1 AND transferid = 1 AND did = v_did;
  SELECT COALESCE(SUM(amount), 0) INTO v_credit FROM tbl_reseller_transfertobank_request WHERE status = 1 AND transferid = 2 AND did = v_did;
  v_balance := (v_totalbalance - (v_withdrwal + v_credit));
  ELSE
  v_withdrwal := 0;
  v_credit := 0;
  v_balance := 0;
  END IF;
  RAISE NOTICE '%', v_totalbalance;
  RAISE NOTICE '%', v_withdrwal;
  RAISE NOTICE '%', v_balance;
  RAISE NOTICE '%', v_credit;
  -- SET option (removed)
  IF (0 <> 0) THEN
  -- ROLLBACK (removed)
  RETURN;
  END IF;
  -- COMMIT (removed)
END;
$$;


--
-- Name: usp_reseller_comission_transfertobank(integer, integer, numeric, numeric, integer, numeric, character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_reseller_comission_transfertobank(v_mode integer DEFAULT 1, v_did integer DEFAULT 2, v_availableamount numeric DEFAULT 5, v_withdrwal numeric DEFAULT 0, v_transferid integer DEFAULT 1, v_amount numeric DEFAULT 10, INOUT v_strresult character varying DEFAULT ''::character varying) RETURNS character varying
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_tdspercentage DECIMAL(18,2);
  v_tdsamount DECIMAL(18,2);
  v_gstpercentage Decimal(18,2);
  v_gstamount DECIMAL(18,2);
  v_finalamount DECIMAL(18,2);
BEGIN
  -- BEGIN TRAN (removed)
  -- SET option (removed)
  v_tdspercentage := 0;
  v_tdsamount := 0;
  v_gstpercentage := 0;
  v_gstamount := 0;
  v_finalamount := 0;
  SELECT COALESCE(limits, 0) INTO v_tdspercentage FROM settings WHERE caption = 'TDSPERCENTAGE' AND active = 1;
  SELECT COALESCE(limits, 0) INTO v_gstpercentage FROM settings WHERE caption = 'GST Percentage' AND active = 1;
  IF (v_mode = 1) THEN
  IF (v_availableamount < v_amount) THEN
  v_strresult := 'Transfer Amount Can not higher Then Available Amount';
  -- COMMIT (removed)
  RETURN;
  END IF;
  SELECT (v_amount * v_gstpercentage) / 100 INTO v_gstamount;
  SELECT v_amount - v_gstamount INTO v_finalamount;
  SELECT (v_finalamount * v_tdspercentage) / 100 INTO v_tdsamount;
  SELECT v_finalamount - v_tdsamount INTO v_finalamount;
  IF (v_transferid = 2) THEN
  INSERT INTO tbl_resellerwalletrequest (pmid, amount, date, paymode, bankname, branchname, referance_id, referance_date, image, mem_remark, admin_remark, actiondate, sys_tranid, status_update_from, status, "ifsc code", bankid, gstpercenatage, gstamount, tdsamount, tdspercentage, finalamount) VALUES (v_did, v_amount, dbo.FUN_GETCURRENTDATE(), 0, '', '', '', '', '', '', NULL, dbo.FUN_GETCURRENTDATE(), GEN_RANDOM_UUID(), 0, 1, '', '', v_gstpercentage, v_gstamount, v_tdsamount, v_tdspercentage, v_finalamount);
  END IF;
  INSERT INTO tbl_reseller_transfertobank_request (did, availablebalance, withdrwal, transferid, amount, transferrequest, status, create_date, tds, tdspercentage, gstpercenatage, gstamount, finalamount) VALUES (v_did, v_availableamount, v_withdrwal, v_transferid, v_amount, 0, 1, dbo.FUN_GETCURRENTDATE(), v_tdsamount, v_tdspercentage, v_gstpercentage, v_gstamount, v_finalamount);
  v_strresult := 'INSERT';
  END IF;
  -- SET option (removed)
  IF (0 <> 0) THEN
  v_strresult := 'ERROR OCCURED';
  -- ROLLBACK (removed)
  RETURN;
  END IF;
  -- COMMIT (removed)
END;
$$;


--
-- Name: usp_reseller_commission_gstinvoice_report(integer, integer, character varying, character varying, integer, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_reseller_commission_gstinvoice_report(v_startrowindex integer DEFAULT 1, v_maxrows integer DEFAULT 100, v_fromdate character varying DEFAULT ''::character varying, v_todate character varying DEFAULT ''::character varying, v_did integer DEFAULT 2, v_totalcount integer DEFAULT 0) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_minindex INT;
  v_maxindex INT;
  v_query text;
BEGIN
  -- BEGIN TRAN (removed)
  v_minindex := 0;
  v_maxindex := 0;
  v_query := '';
  v_minindex := (v_startrowindex - 1) * v_maxrows + 1;
  v_maxindex := v_startrowindex * v_maxrows;
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp (ROWNUMBER INT GENERATED BY DEFAULT AS IDENTITY,
INVOICENO VARCHAR(100) ,
AMOUNT DECIMAL(18,2),
INVOICEDATE VARCHAR(100),
SERVICENAME VARCHAR(100)) ON COMMIT DROP;
  v_query := 'INSERT INTO #TEMP SELECT ISNULL(TRCW.INVOICENO,''''),ISNULL((TRCW.CR+ (TRCW.CR*TRCW.GSTPERCENTAGE)/100),0),
CONVERT(VARCHAR,TRCW.TRANSDATE,106),TRS.SERVICENAME FROM TBL_RESELLER_COMMISSION_WALLET TRCW
LEFT JOIN TBL_RESELLER_SERVICES TRS ON TRCW.SERVICETYPE=TRS.TRSID 
 WHERE DID=''' || CAST(v_did AS VARCHAR(30)) || ''' and INVOICENO<>''''  ';
  IF ((v_fromdate <> '') AND (v_fromdate = '')) THEN
  v_query := v_query || ' AND CONVERT(DATE, TRCW.TRANSDATE) =  CONVERT(DATE, ''' || v_fromdate || ''')';
  END IF;
  IF ((v_fromdate = '') AND (v_todate <> '')) THEN
  v_query := v_query || ' AND CONVERT(DATE, TRCW.TRANSDATE) =  CONVERT(DATE, ''' || v_todate || ''') ';
  END IF;
  IF ((v_fromdate <> '') AND (v_todate <> '')) THEN
  v_query := v_query || ' AND CONVERT(DATE, TRCW.TRANSDATE) BETWEEN CONVERT(DATE, ''' || v_fromdate || ''') AND  CONVERT(DATE, ''' || v_todate || ''') ';
  END IF;
  v_query := v_query || '  ORDER BY CONVERT(VARCHAR(100),TRCW.TRANSDATE,106) DESC ';
  EXECUTE v_query;
  RAISE NOTICE '%', v_query;
  RETURN QUERY SELECT * FROM tmp_temp WHERE rownumber BETWEEN v_minindex AND v_maxindex;
  SELECT COUNT(rownumber) INTO v_totalcount FROM tmp_temp;
  DROP TABLE IF EXISTS tmp_temp;
  -- SET option (removed)
  PERFORM dbo.sp_errorlog();
  IF (0 > 0) THEN
  -- ROLLBACK (removed)
  END IF;
  RETURN;
  -- COMMIT (removed)
END;
$$;


--
-- Name: usp_reseller_commission_report(integer, integer, character varying, character varying, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_reseller_commission_report(v_startrowindex integer DEFAULT 1, v_maxrows integer DEFAULT 100, v_fromdate character varying DEFAULT ''::character varying, v_todate character varying DEFAULT ''::character varying, v_totalcount integer DEFAULT 0) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_minindex INT;
  v_maxindex INT;
  v_query text;
  v_count INT;
  v_total INT;
  v_tempdid INT;
  v_tempshopcr DECIMAL(18,2);
  v_temputilitycr DECIMAL(18,2);
  v_totaltransfertobank DECIMAL(18,2);
  v_totalwithdrwal Decimal(18,2);
BEGIN
  -- BEGIN TRAN (removed)
  v_count := 1;
  v_total := 0;
  v_tempdid := 0;
  v_tempshopcr := 0;
  v_temputilitycr := 0;
  v_totaltransfertobank := 0;
  v_totalwithdrwal := 0;
  v_minindex := (v_startrowindex - 1) * v_maxrows + 1;
  v_maxindex := v_startrowindex * v_maxrows;
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp (ROWNUMBER BIGINT GENERATED BY DEFAULT AS IDENTITY,
DID INT,
RESELLERNAME VARCHAR(100),
RESELLERID VARCHAR(100),
UTILITYCOMISSION DECIMAL(18,2),
SHOPPINGCOMMISSION DECIMAL(18,2),
WITHDRWAL DECIMAL(18,2),
TRANSFERTOBANK DECIMAL(18,2),
BALANACE DECIMAL(18,2)) ON COMMIT DROP;
  v_query := 'INSERT INTO #TEMP SELECT DID,ISNULL(DM.COMPANYNAME,''N/A''),ISNULL(TD.LOGINID,''N/A''),0,0,0,0,0 FROM 
TBL_DISTRIBUTOR TD LEFT JOIN Distributor_MASTER DM ON TD.DID= DM.PLID WHERE TD.Status=1 ';
  EXECUTE v_query;
  SELECT COUNT(1) INTO v_total FROM tmp_temp;
  WHILE (v_count <= v_total) LOOP
  SELECT did INTO v_tempdid FROM tmp_temp WHERE rownumber = v_count;
  SELECT COALESCE(SUM(cr), 0) INTO v_temputilitycr FROM tbl_reseller_commission_wallet WHERE did = v_tempdid AND servicetype = 1;
  SELECT COALESCE(SUM(cr), 0) INTO v_tempshopcr FROM tbl_reseller_commission_wallet WHERE did = v_tempdid AND servicetype = 2;
  SELECT COALESCE(SUM(amount), 0) INTO v_totaltransfertobank FROM tbl_reseller_transfertobank_request WHERE did = v_tempdid AND transferid = 1;
  SELECT COALESCE(SUM(amount), 0) INTO v_totalwithdrwal FROM tbl_reseller_transfertobank_request WHERE did = v_tempdid AND transferid = 2;
  UPDATE tmp_temp SET shoppingcommission = v_tempshopcr, utilitycomission = v_temputilitycr, transfertobank = v_totaltransfertobank, withdrwal = v_totalwithdrwal, balanace = ((v_tempshopcr + v_temputilitycr) - (v_totaltransfertobank + v_totalwithdrwal)) WHERE rownumber = v_count;
  v_count := v_count + 1;
  END LOOP;
  RAISE NOTICE '%', v_query;
  RETURN QUERY SELECT * FROM tmp_temp WHERE rownumber BETWEEN v_minindex AND v_maxindex;
  SELECT COUNT(1) INTO v_totalcount FROM tmp_temp;
  -- COMMIT (removed)
END;
$$;


--
-- Name: usp_reseller_commission_tds_report(integer, integer, character varying, character varying, integer, integer, character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_reseller_commission_tds_report(v_startrowindex integer DEFAULT 1, v_maxrows integer DEFAULT 100, v_fromdate character varying DEFAULT '2019-04-06'::character varying, v_todate character varying DEFAULT ''::character varying, v_did integer DEFAULT 2, v_totalcount integer DEFAULT 0, v_status character varying DEFAULT '1'::character varying) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_minindex INT;
  v_maxindex INT;
  v_query text;
BEGIN
  -- BEGIN TRAN (removed)
  v_minindex := (v_startrowindex - 1) * v_maxrows + 1;
  v_maxindex := v_startrowindex * v_maxrows;
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp (ROWNUMBER INT GENERATED BY DEFAULT AS IDENTITY,
DID INT ,
TRANSDATE VARCHAR(100),
COMPANYNAME VARCHAR(100),
AMOUNT DECIMAL(18,2),
TDSPERCENTAGE DECIMAL(18,2),
TDS DECIMAL(18,2),
TRANSFERID DECIMAL(18,2),
PAIDSTATUS VARCHAR(100)) ON COMMIT DROP;
  v_query := 'INSERT INTO #TEMP SELECT TRTR.DID,CONVERT(varchar(50),TRTR.CREATE_DATE,106),ISNULL(DM.COMPANYNAME,''N/A''),
ISNULL(AMOUNT,0),ISNULL(TRTR.TDSPERCENTAGE,0),ISNULL(TRTR.TDS,0),TRTR.TRANSFERID,
(CASE WHEN PAIDSTATUS=1 THEN ''PAID'' ELSE ''UNPAID'' END)
FROM TBL_RESELLER_TRANSFERTOBANK_REQUEST TRTR
LEFT JOIN Distributor_MASTER DM ON TRTR.did=DM.PLID
WHERE DID=''' || CAST(v_did AS VARCHAR(30)) || '''  ';
  IF ((v_fromdate <> '') AND (v_fromdate = '')) THEN
  v_query := v_query || ' AND CONVERT(DATE, CREATE_DATE) =  CONVERT(DATE, ''' || v_fromdate || ''')';
