  v_query := v_query || ' AND CONVERT(DATE, CREATE_DATE) BETWEEN CONVERT(DATE, ''' || v_fromdate || ''') AND  CONVERT(DATE, ''' || v_todate || ''') ';
  END IF;
  IF (v_status <> '') THEN
  v_query := v_query || ' AND TRTR.PAIDSTATUS=''' || CAST(v_status AS VARCHAR(1)) || '''';
  END IF;
  EXECUTE v_query;
  RAISE NOTICE '%', v_query;
  RETURN QUERY SELECT ROW_NUMBER() OVER (ORDER BY rownumber DESC NULLS LAST) AS row, * FROM tmp_temp WHERE rownumber BETWEEN v_minindex AND v_maxindex ORDER BY transdate DESC NULLS LAST;
  SELECT COUNT(rownumber) INTO v_totalcount FROM tmp_temp;
  DROP TABLE IF EXISTS tmp_temp;
  -- SET option (removed)
  PERFORM dbo.sp_errorlog();
  IF (0 > 0) THEN
  -- ROLLBACK (removed)
  END IF;
  RETURN;
  -- COMMIT (removed)
END;
$$;


