--
-- Name: usp_reseller_commissionreport(integer, integer, character varying, character varying, character varying, integer, character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_reseller_commissionreport(v_startrowindex integer DEFAULT 1, v_maxrows integer DEFAULT 100, v_fromdate character varying DEFAULT ''::character varying, v_todate character varying DEFAULT ''::character varying, v_invoiceno character varying DEFAULT ''::character varying, v_totalcount integer DEFAULT 0, v_did character varying DEFAULT '2'::character varying) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_minindex INT;
  v_maxindex INT;
  v_query text;
BEGIN
  BEGIN
  v_minindex := (v_startrowindex - 1) * v_maxrows + 1;
  v_maxindex := v_startrowindex * v_maxrows;
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp (ROW_NUMBER int,
DATE timestamp,
InvoiceNo varchar(100),
OrderNo varchar(100),
Quantity int,
TotalAmount decimal(18,4),
Status varchar(100),
Commission DECIMAL(18,2),
PROCESSDATE timestamp,
RATEOFBV DECIMAL(18,2),
ORDERBV DECIMAL(18,2),
RELEASEBV DECIMAL(18,2),
ISRESELLERRELEASE int,
RESELLERRELEASEBATCH varchar(100),
OrderID varchar(100),
Product_Name varchar(150)) ON COMMIT DROP;
  v_query := 'INSERT INTO #Temp SELECT  ROW_NUMBER() over(order by PM.POID desc) as ROW_NUMBER,  RM.OrderDate as DATE,MC.INVOICENO as InvoiceNo,
			PM.Orderno as OrderNo,PM.Product_Qty as Quantity,PM.Total_Purchase_Cost as TotalAmount,
			case when PM.intstatus=0 then ''Pending'' when PM.intstatus=-1 then ''Hold'' else OS.Statusname end as Status,PM.Total_BV as Commission
			,RRD.PROCESSDATE,isnull(RRD.RATEOFBV,0) as RATEOFBV,isnull(RRD.ORDERBV,0) as ORDERBV,
			isnull(RRD.RELEASEBV,0) as RELEASEBV,isnull(RRD.ISRESELLERRELEASE,0) as ISRESELLERRELEASE ,isnull(RRD.RESELLERRELEASEBATCH,'''') as RESELLERRELEASEBATCH,RM.OrderID,PM.Product_Name
			FROM [DBO].[TBL_MERCHANT_COMMISSIONINVOICES]  as MC
			inner join [DBO].[TBL_MERCHANT_COMMISSIONINVOICES_DETAILS] as MCD on MC.ORDERID=MCD.ORDERID 
			inner join TBL_PRODUCT_ORDER_MASTER as PM on PM.Orderno=MCD.ORDERNO
			inner join tbl_order_master as RM  on RM.OrderID=MCD.ORDERID
			left join orderstatusmaster  as OS on PM.IntStatus=OS.OSID
			inner join TBL_CUSTOMERLOGIN as CL on Cl.loginid=PM.LoginID 
			inner join TBL_RESELLERRELEASEBVDETAILS as RRD on RRD.ORDERNO= PM.Orderno
			where  CL.DID=cast(''' || v_did || ''' as int) ';
  RAISE NOTICE '%', v_query;
  IF (v_invoiceno <> '') THEN
  v_query := v_query || ' And PM.InvoiceNo = ''' || v_invoiceno || '''';
  END IF;
  IF ((v_fromdate <> '') AND (v_fromdate = '')) THEN
  v_query := v_query || ' AND CONVERT(DATE, RM.OrderDate) =  CONVERT(DATE, ''' || v_fromdate || ''')';
  END IF;
  IF ((v_fromdate = '') AND (v_todate <> '')) THEN
  v_query := v_query || ' AND CONVERT(DATE, RM.OrderDate) =  CONVERT(DATE, ''' || v_todate || ''') ';
  END IF;
  IF ((v_fromdate <> '') AND (v_todate <> '')) THEN
  v_query := v_query || ' AND CONVERT(DATE, RM.OrderDate) BETWEEN CONVERT(DATE, ''' || v_fromdate || ''') AND  CONVERT(DATE, ''' || v_todate || ''') ';
  END IF;
  EXECUTE v_query;
  RETURN QUERY SELECT * FROM tmp_temp WHERE row_number BETWEEN v_minindex AND v_maxindex;
  SELECT COUNT(row_number) INTO v_totalcount FROM tmp_temp;
  DROP TABLE IF EXISTS tmp_temp;
  -- SET option (removed)
  EXCEPTION WHEN OTHERS THEN
  PERFORM dbo.sp_errorlog();
  IF (0 > 0) THEN
  -- ROLLBACK (removed)
  END IF;
  RETURN;
  END;
END;
$$;


