  v_query := 'INSERT INTO #Temp select ROW_NUMBER() over(order by RCWSID desc) as ROW_NUMBER,Date,TraceNo  as TransactionID,CrDrType as Type,
			case when CrDrType=''Cr'' then Cr_amount  when CrDrType=''Dr'' then Dr_amount end as AMOUNT,Balance  FROM TBL_RESELLER_COMMISSIONWALLETSTATEMENT where DID=cast(''' || v_did || ''' as int) ';
  RAISE NOTICE '%', v_query;
  IF (v_transactionid <> '') THEN
  v_query := v_query || ' And TraceNo = ''' || v_transactionid || '''';
  END IF;
  IF ((v_fromdate <> '') AND (v_fromdate = '')) THEN
  v_query := v_query || ' AND CONVERT(DATE, DATE) =  CONVERT(DATE, ''' || v_fromdate || ''')';
  END IF;
  IF ((v_fromdate = '') AND (v_todate <> '')) THEN
  v_query := v_query || ' AND CONVERT(DATE, DATE) =  CONVERT(DATE, ''' || v_todate || ''') ';
  END IF;
  IF ((v_fromdate <> '') AND (v_todate <> '')) THEN
  v_query := v_query || ' AND CONVERT(DATE, DATE) BETWEEN CONVERT(DATE, ''' || v_fromdate || ''') AND  CONVERT(DATE, ''' || v_todate || ''') ';
  END IF;
  EXECUTE v_query;
  RETURN QUERY SELECT * FROM tmp_temp WHERE row_number BETWEEN v_minindex AND v_maxindex;
  SELECT COUNT(row_number) INTO v_totalcount FROM tmp_temp;
  DROP TABLE IF EXISTS tmp_temp;
  -- SET option (removed)
  EXCEPTION WHEN OTHERS THEN
  PERFORM dbo.sp_errorlog();
  IF (0 > 0) THEN
  -- ROLLBACK (removed)
  END IF;
  RETURN;
  END;
END;
$$;


--
-- Name: usp_reseller_dailycommission_report(integer, integer, character varying, character varying, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_reseller_dailycommission_report(v_startrowindex integer DEFAULT 1, v_maxrows integer DEFAULT 100, v_fromdate character varying DEFAULT ''::character varying, v_todate character varying DEFAULT ''::character varying, v_totalcount integer DEFAULT 0) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_minindex INT;
  v_maxindex INT;
  v_query text;
  v_count INT;
  v_total INT;
  v_tempdid INT;
  v_tempdate VARCHAR(100);
  v_tempshopcr DECIMAL(18,2);
  v_temputilitycr DECIMAL(18,2);
  v_totaltransfertobank DECIMAL(18,2);
  v_totalwithdrwal Decimal(18,2);
  v_companyname VARCHAR(100);
BEGIN
  BEGIN
  v_count := 1;
  v_total := 0;
  v_tempdid := 0;
  v_tempdate := '';
  v_tempshopcr := 0;
  v_temputilitycr := 0;
  v_totaltransfertobank := 0;
  v_totalwithdrwal := 0;
  v_companyname := '';
  v_minindex := (v_startrowindex - 1) * v_maxrows + 1;
  v_maxindex := v_startrowindex * v_maxrows;
  DROP TABLE IF EXISTS tmp_temp1;
  CREATE TEMP TABLE tmp_temp1 (ROWNUMBER BIGINT GENERATED BY DEFAULT AS IDENTITY,
DID INT,
DATE VARCHAR(100)) ON COMMIT DROP;
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp (ROWNUMBER BIGINT GENERATED BY DEFAULT AS IDENTITY,
DID INT,
COMPANNAME VARCHAR(100),
DATE VARCHAR(100),
SHOPPINGCOMISSION DECIMAL(18,4),
UTILITYCOMMISSION DECIMAL(18,2),
WITHDRWAL DECIMAL(18,2),
TRANSFERTOBANK DECIMAL(18,2),
TOTALAMOUNT  DECIMAL(18,2)) ON COMMIT DROP;
  v_query := 'INSERT INTO #TEMP1 SELECT TRCW.DID,CONVERT(VARCHAR,TRANSDATE,106) FROM 
TBL_RESELLER_COMMISSION_WALLET TRCW WHERE 1=1 and FINALUPDATE=1';
  v_query := v_query || ('INSERT INTO #TEMP1 SELECT TRCW.DID,CONVERT(VARCHAR,CREATE_DATE,106) FROM 
TBL_RESELLER_TRANSFERTOBANK_REQUEST TRCW  WHERE 1=1 ');
  EXECUTE v_query;
  v_query := '';
  v_query := 'INSERT INTO #TEMP SELECT DISTINCT  DID,'''',CONVERT(VARCHAR,DATE,106),0,0,0,0,0 FROM #TEMP1  WHERE 1=1 ';
  IF ((v_fromdate <> '') AND (v_todate = '')) THEN
  v_query := v_query || ' AND CONVERT(DATE, DATE,103) =  CONVERT(DATE, ''' || v_fromdate || ''',103)';
  END IF;
  IF ((v_fromdate = '') AND (v_todate <> '')) THEN
  v_query := v_query || ' AND CONVERT(DATE, DATE,103) =  CONVERT(DATE, ''' || v_todate || ''',103) ';
  END IF;
  IF ((v_fromdate <> '') AND (v_todate <> '')) THEN
  v_query := v_query || ' AND CONVERT(DATE, DATE,103) BETWEEN CONVERT(DATE, ''' || v_fromdate || ''',103) AND  CONVERT(DATE, ''' || v_todate || ''',103) ';
  END IF;
  v_query := v_query || ' GROUP BY DID, CONVERT(VARCHAR,DATE,106) ';
  EXECUTE v_query;
  RAISE NOTICE '%', v_query;
  SELECT COUNT(1) INTO v_total FROM tmp_temp;
  WHILE (v_count <= v_total) LOOP
  SELECT CAST(TO_CHAR(date, 'DD TMMon YYYY') AS VARCHAR(30)), did INTO v_tempdate, v_tempdid FROM tmp_temp WHERE rownumber = v_count;
  SELECT COALESCE(companyname, '') INTO v_companyname FROM distributor_master WHERE plid = v_tempdid;
  SELECT COALESCE(SUM(cr), 0) INTO v_temputilitycr FROM tbl_reseller_commission_wallet WHERE did = v_tempdid AND CAST(TO_CHAR(transdate, 'DD TMMon YYYY') AS VARCHAR(30)) = CAST(TO_CHAR(v_tempdate, 'DD TMMon YYYY') AS VARCHAR(30)) AND servicetype = 1;
  SELECT COALESCE(SUM(cr), 0) INTO v_tempshopcr FROM tbl_reseller_commission_wallet WHERE did = v_tempdid AND CAST(TO_CHAR(transdate, 'DD TMMon YYYY') AS VARCHAR(30)) = CAST(TO_CHAR(v_tempdate, 'DD TMMon YYYY') AS VARCHAR(30)) AND servicetype = 2;
  SELECT COALESCE(SUM(amount), 0) INTO v_totaltransfertobank FROM tbl_reseller_transfertobank_request WHERE did = v_tempdid AND transferid = 1 AND CAST(TO_CHAR(create_date, 'DD TMMon YYYY') AS VARCHAR(30)) = CAST(TO_CHAR(v_tempdate, 'DD TMMon YYYY') AS VARCHAR(30));
  SELECT COALESCE(SUM(amount), 0) INTO v_totalwithdrwal FROM tbl_reseller_transfertobank_request WHERE did = v_tempdid AND transferid = 2 AND CAST(TO_CHAR(create_date, 'DD TMMon YYYY') AS VARCHAR(30)) = CAST(TO_CHAR(v_tempdate, 'DD TMMon YYYY') AS VARCHAR(30));
  UPDATE tmp_temp SET shoppingcomission = v_tempshopcr, utilitycommission = v_temputilitycr, withdrwal = v_totalwithdrwal, transfertobank = v_totaltransfertobank, totalamount = ((v_tempshopcr + v_temputilitycr) - (v_totalwithdrwal + v_totaltransfertobank)), companname = v_companyname WHERE rownumber = v_count;
  v_count := v_count + 1;
  END LOOP;
  RETURN QUERY SELECT * FROM tmp_temp WHERE rownumber BETWEEN v_minindex AND v_maxindex;
  SELECT COALESCE(COUNT(1), 0) INTO v_totalcount FROM tmp_temp;
  DROP TABLE IF EXISTS tmp_temp;
  DROP TABLE IF EXISTS tmp_temp1;
  -- SET option (removed)
  EXCEPTION WHEN OTHERS THEN
  PERFORM dbo.sp_errorlog();
  IF (0 > 0) THEN
  -- ROLLBACK (removed)
  END IF;
  RETURN;
  END;
END;
$$;


--
-- Name: usp_reseller_faq(integer, integer, character varying, boolean, character varying, character varying, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_reseller_faq(v_startrowindex integer, v_maxrows integer, v_orderbyfield character varying, v_asc boolean, v_searchfield character varying, v_searchvalue character varying, v_mode integer) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_recordcount int;
  v_regno bigint;
BEGIN
  -- SET option (removed)
  DROP TABLE IF EXISTS tmp_temp12;
  CREATE TEMP TABLE tmp_temp12 ON COMMIT DROP AS SELECT ROW_NUMBER() OVER (ORDER BY frq.frqid DESC NULLS LAST) AS rownumber, frq.frqid, frq.frcid, frq.faqque, frq.faqans, frc.categoryname, (CASE WHEN frq.active = 1 THEN 'Active' ELSE 'Deactive' END) AS active FROM faq_reseller_quesans AS frq INNER JOIN faq_reseller_category AS frc ON frc.frcid = frq.frcid WHERE frc.active = 1;
