END;
$$;


--
-- Name: usp_reseller_get_bvdetails(integer, integer, integer, character varying, character varying, integer, character varying, character varying, character varying, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_reseller_get_bvdetails(v_mode integer DEFAULT 0, v_startrowindex integer DEFAULT 1, v_maxrows integer DEFAULT 100, v_fromdate character varying DEFAULT ''::character varying, v_todate character varying DEFAULT ''::character varying, v_totalcount integer DEFAULT 0, v_searchfield character varying DEFAULT ''::character varying, v_searchvalue character varying DEFAULT ''::character varying, v_status character varying DEFAULT ''::character varying, v_did integer DEFAULT 0) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_minindex INT;
  v_maxindex INT;
  v_query text;
BEGIN
  v_minindex := (v_startrowindex - 1) * v_maxrows + 1;
  v_maxindex := v_startrowindex * v_maxrows;
  IF (v_mode = 0) THEN
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp (ROWNUMBER BIGINT GENERATED BY DEFAULT AS IDENTITY,
	ORDERID VARCHAR(100),
	TOTAL_PURCHASE_COST DECIMAL(18,2),  
	TOTAL_BV DECIMAL(18,2),         
	ORDERDATE VARCHAR(100),	
	RELASED INT,
	ISDISTRIBUTED INT,
	MEMEBERID varchar(100)) ON COMMIT DROP;
  v_query := 'INSERT INTO #TEMP SELECT DISTINCT OM.ORDERID,OM.ORDER_NETAMT,OM.ORDER_BV,OM.ORDERDATE,
ISNULL(RRD.ISADMINRELEASE,0) AS RELASED,ISNULL(RRD.ISRESELLERRELEASE,0) AS ISDISTRIBUTED,
ISNULL(TRU.USERNAME,''N/A'') FROM TBL_ORDER_MASTER OM
INNER JOIN TBL_CUSTOMERLOGIN CL ON OM.LOGINID=CL.LOGINID
LEFT JOIN TBL_PRODUCT_ORDER_MASTER POM ON OM.ORDERID=POM.ORDERID
INNER JOIN TBL_RESELLERRELEASEBVDETAILS AS RRD ON RRD.ORDERNO= POM.ORDERNO
LEFT JOIN TBL_REFERENCEUSERNAME  TRU ON CL.CLID=TRU.CLID
WHERE POM.INTSTATUS=6 AND CL.DID=''' || CAST(v_did AS VARCHAR(30)) || ''' ';
  IF ((v_fromdate <> '') AND (v_todate = '')) THEN
  v_query := v_query || ' AND CONVERT(DATE, OM.ORDERDATE, 105) BETWEEN  CONVERT(DATE, ''' || v_fromdate || ''', 105) AND  CONVERT(DATE, DBO.FUN_GETCURRENTDATE(), 105)';
  END IF;
  IF ((v_fromdate = '') AND (v_todate <> '')) THEN
  v_query := v_query || 'AND CONVERT(DATE, OM.ORDERDATE, 105) BETWEEN  CONVERT(DATE, ''' || v_todate || ''', 105) AND  CONVERT(DATE, DBO.FUN_GETCURRENTDATE(), 105)';
  END IF;
  IF ((v_fromdate <> '') AND (v_todate <> '')) THEN
  v_query := v_query || 'AND CONVERT(DATE, OM.ORDERDATE, 105) BETWEEN CONVERT(DATE, ''' || v_fromdate || ''', 105) AND  CONVERT(DATE, ''' || v_todate || ''', 105)';
  END IF;
  v_query := v_query || ' ORDER BY OM.ORDERDATE DESC';
  EXECUTE v_query;
  RAISE NOTICE '%', v_query;
  RETURN QUERY SELECT * FROM tmp_temp WHERE rownumber BETWEEN v_minindex AND v_maxindex;
  SELECT COUNT(rownumber) INTO v_totalcount FROM tmp_temp;
  DROP TABLE IF EXISTS tmp_temp;
  -- SET option (removed)
  END IF;
END;
$$;


--
-- Name: usp_reseller_get_utilities_bvdetails(integer, integer, integer, character varying, character varying, integer, character varying, character varying, character varying, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_reseller_get_utilities_bvdetails(v_mode integer DEFAULT 0, v_startrowindex integer DEFAULT 1, v_maxrows integer DEFAULT 100, v_fromdate character varying DEFAULT ''::character varying, v_todate character varying DEFAULT ''::character varying, v_totalcount integer DEFAULT 0, v_searchfield character varying DEFAULT ''::character varying, v_searchvalue character varying DEFAULT ''::character varying, v_status character varying DEFAULT ''::character varying, v_did integer DEFAULT 1) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_minindex INT;
  v_maxindex INT;
  v_query text;
  v_count INT;
  v_totaldata INT;
  v_transactionid VARCHAR(100);
  v_clid INT;
  v_username VARCHAR(100);
  v_mobile VARCHAR(100);
  v_name VARCHAR(100);
BEGIN
  v_count := 1;
  v_totaldata := 0;
  v_transactionid := '';
  v_clid := 0;
  v_username := '';
  v_mobile := '';
  v_name := '';
  v_minindex := (v_startrowindex - 1) * v_maxrows + 1;
  v_maxindex := v_startrowindex * v_maxrows;
  IF (v_mode = 0) THEN
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp (ROWNUMBER BIGINT GENERATED BY DEFAULT AS IDENTITY,
	CUSTOMERNAME VARCHAR(100),
	MOBILENO VARCHAR(100),
	DATE VARCHAR(100),
	TOTAL_BV DECIMAL(18,2), 
	MEMBERID VARCHAR(100),        
	RELASED INT,
	ISDISTRIBUTED INT,
	TRANSACTIONID VARCHAR(100)) ON COMMIT DROP;
  v_query := 'INSERT INTO #TEMP SELECT '''','''',RRD.PROCESSDATE,RRD.ORDERBV,'''', 
 ISNULL(RRD.ISADMINRELEASE,0) AS RELASED,ISNULL(RRD.ISRESELLERRELEASE,0) AS ISDISTRIBUTED,
 RRD.ORDERNO
 FROM TBL_RESELLERRELEASEBVDETAILS RRD
 WHERE PROCESSTYPE=2 AND RRD.DID=''' || CAST(v_did AS VARCHAR(30)) || ''' ';
  IF ((v_fromdate <> '') AND (v_todate = '')) THEN
  v_query := v_query || ' AND CONVERT(DATE, RRD.PROCESSDATE, 105) BETWEEN  CONVERT(DATE, ''' || v_fromdate || ''', 105) AND  CONVERT(DATE, DBO.FUN_GETCURRENTDATE(), 105)';
  END IF;
  IF ((v_fromdate = '') AND (v_todate <> '')) THEN
  v_query := v_query || 'AND CONVERT(DATE, RRD.PROCESSDATE, 105) BETWEEN  CONVERT(DATE, ''' || v_todate || ''', 105) AND  CONVERT(DATE, DBO.FUN_GETCURRENTDATE(), 105)';
  END IF;
  IF ((v_fromdate <> '') AND (v_todate <> '')) THEN
  v_query := v_query || 'AND CONVERT(DATE, RRD.PROCESSDATE, 105) BETWEEN CONVERT(DATE, ''' || v_fromdate || ''', 105) AND  CONVERT(DATE, ''' || v_todate || ''', 105)';
  END IF;
  v_query := v_query || ' ORDER BY RRD.PROCESSDATE DESC';
  EXECUTE v_query;
  SELECT COUNT(*) INTO v_totaldata FROM tmp_temp;
  WHILE (v_totaldata >= v_count) LOOP
  SELECT COALESCE(transactionid, '') INTO v_transactionid FROM tmp_temp WHERE rownumber = v_count;
  IF EXISTS(SELECT 1 FROM tbl_customer_postpaid_recharges WHERE transactionid = v_transactionid) THEN
  SELECT COALESCE(clid, 0) INTO v_clid FROM tbl_customer_postpaid_recharges WHERE transactionid = v_transactionid;
  ELSE
  IF EXISTS(SELECT 1 FROM tbl_customer_prepaid_recharges WHERE transactionid = v_transactionid) THEN
  SELECT COALESCE(clid, 0) INTO v_clid FROM tbl_customer_prepaid_recharges WHERE transactionid = v_transactionid;
  ELSE
  IF EXISTS(SELECT 1 FROM tbl_customer_dth_recharges WHERE transactionid = v_transactionid) THEN
  SELECT COALESCE(clid, 0) INTO v_clid FROM tbl_customer_dth_recharges WHERE transactionid = v_transactionid;
  ELSE
  IF EXISTS(SELECT 1 FROM tbl_customer_electricity_recharges WHERE transactionid = v_transactionid) THEN
  SELECT COALESCE(clid, 0) INTO v_clid FROM tbl_customer_electricity_recharges WHERE transactionid = v_transactionid;
  ELSE
  IF EXISTS(SELECT 1 FROM tbl_customer_gas_recharges WHERE transactionid = v_transactionid) THEN
  SELECT COALESCE(clid, 0) INTO v_clid FROM tbl_customer_electricity_recharges WHERE transactionid = v_transactionid;
  END IF;
  END IF;
  END IF;
  END IF;
  END IF;
  IF (v_clid > 0) THEN
  SELECT (fname || '' || lname), COALESCE(phone, '') INTO v_name, v_mobile FROM tbl_customerlogin WHERE clid = v_clid AND active = 1 AND did = v_did;
  SELECT COALESCE(username, '') INTO v_username FROM tbl_referenceusername WHERE clid = v_clid AND status = 1;
  END IF;
  UPDATE tmp_temp SET memberid = v_username, customername = v_name, mobileno = v_mobile WHERE rownumber = v_count AND transactionid = v_transactionid;
  v_count := v_count + 1;
  END LOOP;
  RETURN QUERY SELECT * FROM tmp_temp WHERE rownumber BETWEEN v_minindex AND v_maxindex;
  SELECT COUNT(rownumber) INTO v_totalcount FROM tmp_temp;
  DROP TABLE IF EXISTS tmp_temp;
  -- SET option (removed)
  END IF;
END;
$$;


--
-- Name: usp_reseller_gst_details(integer, integer, integer, character varying, character varying, character varying, character varying, integer, numeric, numeric, character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_reseller_gst_details(v_mode integer DEFAULT 0, v_startrowindex integer DEFAULT 1, v_maxrows integer DEFAULT 100, v_fromdate character varying DEFAULT ''::character varying, v_todate character varying DEFAULT ''::character varying, v_searchfield character varying DEFAULT ''::character varying, v_searchvalue character varying DEFAULT ''::character varying, v_totalcount integer DEFAULT 0, v_totalgstamount numeric DEFAULT 0, v_totalorderamount numeric DEFAULT 0, v_resellername character varying DEFAULT ''::character varying) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_minindex INT;
  v_maxindex INT;
  v_query text;
BEGIN
  v_minindex := (v_startrowindex - 1) * v_maxrows + 1;
  v_maxindex := v_startrowindex * v_maxrows;
  IF (v_mode = 0) THEN
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp (ROWNUMBER BIGINT GENERATED BY DEFAULT AS IDENTITY, 
	LOGINID VARCHAR(100),
	ORDERID VARCHAR(100),
	ORDERAMOUNT DECIMAL(18,2),
	GSTAMOUNT DECIMAL(18,2),
	GSTPERCENTAGE DECIMAL(18,2),
	CUSTOMERNAME VARCHAR(100),
	RESELLERNAME VARCHAR(100),
	ORDERDATE VARCHAR(100)) ON COMMIT DROP;
  v_query := 'INSERT INTO #TEMP SELECT OM.LOGINID, OM.ORDERID,OM.ORDER_DAP,OM.TOTAL_VAT,CAST((OM.TOTAL_VAT*100)/OM.ORDER_DAP AS DECIMAL(18,2))
AS GSTPERCENTAGE,ISNULL((CL.FNAME+''''+CL.LNAME),'''') AS NAME,ISNULL(DM.COMPANYNAME,'''') RESELLERNAME,OM.ORDERDATE FROM TBL_ORDER_MASTER OM
LEFT JOIN TBL_CUSTOMERLOGIN CL ON OM.LOGINID=CL.LOGINID
LEFT JOIN DISTRIBUTOR_MASTER DM ON CL.DID=DM.PLID
WHERE CL.DID>0 and OM.IntStatus=6';
  IF ((v_fromdate <> '') AND (v_todate = '')) THEN
  v_query := v_query || ' AND CONVERT(DATE, OM.ORDERDATE, 105) BETWEEN  CONVERT(DATE, ''' || v_fromdate || ''', 105) AND  CONVERT(DATE, DBO.FUN_GETCURRENTDATE(), 105)';
  END IF;
  IF ((v_fromdate = '') AND (v_todate <> '')) THEN
  v_query := v_query || 'AND CONVERT(DATE, OM.ORDERDATE, 105) BETWEEN  CONVERT(DATE, ''' || v_todate || ''', 105) AND  CONVERT(DATE, DBO.FUN_GETCURRENTDATE(), 105)';
  END IF;
  IF ((v_fromdate <> '') AND (v_todate <> '')) THEN
  v_query := v_query || 'AND CONVERT(DATE, OM.ORDERDATE, 105) BETWEEN CONVERT(DATE, ''' || v_fromdate || ''', 105) AND  CONVERT(DATE, ''' || v_todate || ''', 105)';
  END IF;
  IF (v_searchfield = 'CustomerName') THEN
  v_query := v_query || ' AND (CL.FNAME+CL.LNAME) LIKE ''%' || v_searchvalue || '%'' ';
  END IF;
  IF (v_searchfield = 'Loginid') THEN
  v_query := v_query || ' AND OM.LOGINID LIKE ''%' || v_searchvalue || '%'' ';
  END IF;
  IF (v_searchfield = 'Orderid') THEN
  v_query := v_query || ' AND OM.Orderid LIKE ''%' || v_searchvalue || '%'' ';
  END IF;
  IF (v_resellername <> '') THEN
  v_query := v_query || ' AND DM.COMPANYNAME LIKE ''%' || v_resellername || '%'' ';
  END IF;
  v_query := v_query || ' ORDER BY OM.ORDERDATE DESC';
  EXECUTE v_query;
  RETURN QUERY SELECT * FROM tmp_temp WHERE rownumber BETWEEN v_minindex AND v_maxindex;
  SELECT COUNT(rownumber) INTO v_totalcount FROM tmp_temp;
  SELECT SUM(gstamount), SUM(orderamount) INTO v_totalgstamount, v_totalorderamount FROM tmp_temp;
  DROP TABLE IF EXISTS tmp_temp;
  -- SET option (removed)
  END IF;
END;
$$;


--
-- Name: usp_reseller_packages_details(integer, integer, integer, character varying, character varying, integer, character varying, character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_reseller_packages_details(v_mode integer DEFAULT 0, v_startrowindex integer DEFAULT 1, v_maxrows integer DEFAULT 100, v_fromdate character varying DEFAULT ''::character varying, v_todate character varying DEFAULT ''::character varying, v_totalcount integer DEFAULT 0, v_searchfield character varying DEFAULT ''::character varying, v_searchvalue character varying DEFAULT ''::character varying) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_minindex INT;
  v_maxindex INT;
  v_query text;
BEGIN
  v_minindex := (v_startrowindex - 1) * v_maxrows + 1;
  v_maxindex := v_startrowindex * v_maxrows;
  IF (v_mode = 0) THEN
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp (ROWNUMBER BIGINT GENERATED BY DEFAULT AS IDENTITY, 
	TRPID INT,       
	TRSID INT,   
	SERVICENAME VARCHAR(100),      
	PACKAGENAME VARCHAR(100),	
	PACKAGEAMOUNT DECIMAL(18,2),
	PACKAGEFEATURES  text,	
	CREATEDATE VARCHAR(100),
	STATUS VARCHAR(100)) ON COMMIT DROP;
  v_query := 'INSERT INTO #TEMP SELECT  TRP.TRPID,TRP.TRSID,TRS.SERVICENAME,TRP.PACKAGENAME,
 TRP.PACKAGEAMOUNT,TRP.PACKAGEFEATURES,TRP.CREATEDATE,
 (CASE WHEN TRP.ACTIVE=1 THEN ''ACTIVE'' ELSE ''INACTIVE'' END)
  FROM TBL_RESELLER_PACKAGES TRP  
LEFT JOIN TBL_RESELLER_SERVICES TRS ON TRP.TRSID=TRS.TRSID
WHERE 1=1 ';
  IF ((v_fromdate <> '') AND (v_todate = '')) THEN
  v_query := v_query || ' AND CONVERT(DATE, TRP.CREATEDATE, 105) BETWEEN  CONVERT(DATE, ''' || v_fromdate || ''', 105) AND  CONVERT(DATE, DBO.FUN_GETCURRENTDATE(), 105)';
  END IF;
  IF ((v_fromdate = '') AND (v_todate <> '')) THEN
  v_query := v_query || 'AND CONVERT(DATE, TRP.CREATEDATE, 105) BETWEEN  CONVERT(DATE, ''' || v_todate || ''', 105) AND  CONVERT(DATE, DBO.FUN_GETCURRENTDATE(), 105)';
  END IF;
  IF ((v_fromdate <> '') AND (v_todate <> '')) THEN
  v_query := v_query || 'AND CONVERT(DATE, TRP.CREATEDATE, 105) BETWEEN CONVERT(DATE, ''' || v_fromdate || ''', 105) AND  CONVERT(DATE, ''' || v_todate || ''', 105)';
  END IF;
  IF (v_searchvalue <> '') THEN
  v_query := v_query || ' AND TRP.PACKAGENAME LIKE ''%' || v_searchvalue || '%'' ';
  END IF;
  v_query := v_query || ' ORDER BY TRP.CREATEDATE DESC';
  EXECUTE v_query;
  RAISE NOTICE '%', v_query;
  RETURN QUERY SELECT * FROM tmp_temp WHERE rownumber BETWEEN v_minindex AND v_maxindex;
  SELECT COUNT(rownumber) INTO v_totalcount FROM tmp_temp;
  DROP TABLE IF EXISTS tmp_temp;
  -- SET option (removed)
  END IF;
END;
$$;


--
-- Name: usp_reseller_packages_details_byid(integer, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_reseller_packages_details_byid(v_trpid integer DEFAULT 0, v_trsid integer DEFAULT 0) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
BEGIN
  RETURN QUERY SELECT trpid, trsid, packagename, packageamount, packagefeatures, active, CAST(TO_CHAR(createdate, 'DD/MM/YYYY') AS VARCHAR(30)), webhosting, freemarketingtool, multichannelsales, whitelabelbranding, storage, discountcoupongen, "user", targetaudience, newcustomers, onlinedatastorage, ddos, antivirus, emailstorage, seotools, smotool, autobackup, livechat, transactionalsms, logodesign, websiteskin, androidapp, multiplepaymentgateway, istrial FROM tbl_reseller_packages WHERE trpid = v_trpid AND trsid = v_trsid AND active = 1;
END;
$$;


--
-- Name: usp_reseller_pakages(integer, character varying, character varying, date, date, character varying, date, character varying, date); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_reseller_pakages(v_did integer DEFAULT 1, INOUT v_productpackagename character varying DEFAULT ''::character varying, INOUT v_utilitiespackagename character varying DEFAULT ''::character varying, INOUT v_productaggrgatedate date DEFAULT NULL::date, INOUT v_utilitylastdate date DEFAULT NULL::date, INOUT v_travelpackagename character varying DEFAULT ''::character varying, INOUT v_travelaggrgatedate date DEFAULT NULL::date, INOUT v_dealspackagename character varying DEFAULT ''::character varying, INOUT v_dealsaggrgatedate date DEFAULT NULL::date) RETURNS record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_trpid INT;
  v_trpid1 INT;
  v_trpid2 INT;
  v_trpid3 INT;
  v_utilityproductlastdate Date;
  v_productlastdate Date;
  v_travellastdate Date;
  v_dealslastdate Date;
BEGIN
  -- BEGIN TRAN (removed)
  -- SET option (removed)
  v_trpid := 0;
  v_trpid1 := 0;
  v_trpid2 := 0;
  v_trpid3 := 0;
  SELECT COALESCE(trpid, 0), TO_DATE(purchaseddate, 'DD TMMon YYYY') INTO v_trpid, v_utilityproductlastdate FROM tbl_reseller_purchased_packages WHERE did = v_did AND trsid = 1;
  SELECT COALESCE(trpid, 0), TO_DATE(purchaseddate, 'DD TMMon YYYY') INTO v_trpid1, v_productlastdate FROM tbl_reseller_purchased_packages WHERE did = v_did AND trsid = 2;
  SELECT COALESCE(trpid, 0), TO_DATE(purchaseddate, 'DD TMMon YYYY') INTO v_trpid2, v_travellastdate FROM tbl_reseller_purchased_packages WHERE did = v_did AND trsid = 3;
  SELECT COALESCE(trpid, 0), TO_DATE(purchaseddate, 'DD TMMon YYYY') INTO v_trpid3, v_dealslastdate FROM tbl_reseller_purchased_packages WHERE did = v_did AND trsid = 4;
  IF (v_trpid > 0) THEN
  SELECT COALESCE(packagename, 'N/A') INTO v_utilitiespackagename FROM tbl_reseller_packages WHERE trpid = v_trpid;
  SELECT v_utilityproductlastdate + INTERVAL '1 YEAR' INTO v_utilitylastdate;
  v_utilitylastdate := TO_DATE(v_utilitylastdate, 'DD/MM/YYYY');
  END IF;
  IF (v_trpid1 > 0) THEN
  SELECT COALESCE(packagename, 'N/A') INTO v_productpackagename FROM tbl_reseller_packages WHERE trpid = v_trpid1;
  SELECT v_productlastdate + INTERVAL '1 YEAR' INTO v_productaggrgatedate;
  v_productaggrgatedate := TO_DATE(v_productaggrgatedate, 'TMMon DD, YYYY');
  END IF;
  IF (v_trpid2 > 0) THEN
  SELECT COALESCE(packagename, 'N/A') INTO v_travelpackagename FROM tbl_reseller_packages WHERE trpid = v_trpid2;
  SELECT v_productlastdate + INTERVAL '1 YEAR' INTO v_travelaggrgatedate;
  v_travelaggrgatedate := TO_DATE(v_travelaggrgatedate, 'DD/MM/YYYY');
  END IF;
  IF (v_trpid3 > 0) THEN
  SELECT COALESCE(packagename, 'N/A') INTO v_dealspackagename FROM tbl_reseller_packages WHERE trpid = v_trpid3;
  SELECT v_dealslastdate + INTERVAL '1 YEAR' INTO v_dealsaggrgatedate;
  v_dealsaggrgatedate := TO_DATE(v_dealsaggrgatedate, 'DD/MM/YYYY');
  END IF;
  RAISE NOTICE '%', v_productaggrgatedate;
  -- SET option (removed)
  -- COMMIT (removed)
END;
$$;


--
-- Name: usp_reseller_paymode(integer, integer, character varying, character varying, character varying, character varying, integer, character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_reseller_paymode(v_startrowindex integer DEFAULT 1, v_maxrows integer DEFAULT 100, v_fromdate character varying DEFAULT ''::character varying, v_todate character varying DEFAULT ''::character varying, v_searchfiel character varying DEFAULT ''::character varying, v_searchvalue character varying DEFAULT ''::character varying, v_totalcount integer DEFAULT 0, v_distributorname character varying DEFAULT ''::character varying) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_minindex INT;
  v_maxindex INT;
  v_query text;
BEGIN
  -- SET option (removed)
  v_minindex := (v_startrowindex - 1) * v_maxrows + 1;
  v_maxindex := v_startrowindex * v_maxrows;
  DROP TABLE IF EXISTS tmp_managedistributorlist;
  CREATE TEMP TABLE tmp_managedistributorlist (ROWNUMBER BIGINT,
	DID INT,
	NAME VARCHAR(150),
	Total_Member BIGINT,
	Email_Id VARCHAR(200),
	Contact VARCHAR(200),
	Address VARCHAR(1000),
	DB_NAME  VARCHAR(200),
	URL VARCHAR(50),
	REGISTRATIONDATE VARCHAR(200)) ON COMMIT DROP;
  v_query := 'INSERT INTO #MANAGEDISTRIBUTORLIST SELECT ROW_NUMBER() OVER (ORDER BY td.DID DESC) AS ROWNUMBER,DID,ISNULL(dm.companyname,'''') AS NAME ,ISNULL(0.000,0) AS Total_Member,ISNULL(EMAILID,'''') AS Email_Id,
ISNULL(td.PHONE,'''') AS Contact,ISNULL('''','''')AS Address ,
ISNULL(td.DB_NAME,'''') AS DB_NAME,ISNULL(td.URL,'''') AS URL,
isnull(td.REGISTRATIONDATE,'''') as REGISTRATIONDATE
FROM TBL_DISTRIBUTOR td left join distributor_master dm on dm.pmid=td.pmid
where td.active=1 and td.iskycapproved=1 and td.STATUS=1 ';
  IF ((v_searchfiel <> '') AND (v_searchvalue <> '')) THEN
  IF (v_searchfiel = 'USERNAME') THEN
  v_query := v_query || ' And EM.EMP_NAME like ''%' || v_searchvalue || '%''';
  END IF;
  END IF;
  IF (v_distributorname <> '') THEN
  v_query := v_query || ' AND (dm.COMPANYNAME) LIKE ''%' || v_distributorname || '%'' ';
  END IF;
  IF ((v_fromdate <> '') AND (v_todate = '')) THEN
  v_query := v_query || ' AND CONVERT(DATE, AL.LOGINDATETIME, 105) BETWEEN  CONVERT(DATE, ''' || v_fromdate || ''', 105) AND  CONVERT(DATE, DBO.FUN_GETCURRENTDATE(), 105) ';
  END IF;
  IF ((v_fromdate = '') AND (v_todate <> '')) THEN
  v_query := v_query || ' AND CONVERT(DATE, AL.LOGINDATETIME, 105) BETWEEN  CONVERT(DATE, ''' || v_todate || ''', 105) AND  CONVERT(DATE, DBO.FUN_GETCURRENTDATE(), 105) ';
  END IF;
  IF ((v_fromdate <> '') AND (v_todate <> '')) THEN
  v_query := v_query || ' AND CONVERT(DATE, AL.LOGINDATETIME, 105) BETWEEN CONVERT(DATE, ''' || v_fromdate || ''', 105) AND  CONVERT(DATE, ''' || v_todate || ''', 105) ';
  END IF;
  EXECUTE v_query;
  RETURN QUERY SELECT * FROM tmp_managedistributorlist WHERE rownumber BETWEEN v_minindex AND v_maxindex;
  SELECT COUNT(rownumber) INTO v_totalcount FROM tmp_managedistributorlist;
  DROP TABLE IF EXISTS tmp_managedistributorlist;
  -- SET option (removed)
END;
$$;


--
-- Name: usp_reseller_paymode_setting(character varying, integer, integer, integer, integer, numeric, character varying, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_reseller_paymode_setting(v_mode character varying DEFAULT ''::character varying, v_did integer DEFAULT 0, v_pmid integer DEFAULT 1, v_mdpid integer DEFAULT 1, v_active integer DEFAULT 0, v_percentage numeric DEFAULT 0, v_stresult character varying DEFAULT ''::character varying, v_empid integer DEFAULT 1) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_count int;
  v_addattributeget varchar(300);
  v_pmidtemp int;
  v_query12 text;
  v_pm_code varchar(50);
BEGIN
  -- BEGIN TRAN (removed)
  v_count := 0;
  v_addattributeget := '';
  v_pmidtemp := 0;
  v_query12 := '';
  v_pm_code := '';
  IF (v_mode = 'add') THEN
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp (rowNumber int,PMID int,PM_Code varchar(100)) ON COMMIT DROP;
  v_query12 := 'insert into #temp SELECT  ROW_NUMBER() over (order by PMID ASC) as rowNumber,PMID,PM_Code  from Pay_Mode ';
  EXECUTE v_query12;
  SELECT COUNT(1) INTO v_count FROM tmp_temp;
  IF NOT EXISTS(SELECT 1 FROM tbl_distributor_paymode_setting WHERE did = v_did) THEN
  WHILE (v_count > 0) LOOP
  SELECT pmid, pm_code INTO v_pmidtemp, v_pm_code FROM tmp_temp WHERE rownumber = v_count;
  INSERT INTO tbl_distributor_paymode_setting VALUES (v_pmidtemp, v_did, 0, dbo.FUN_GETCURRENTDATE(), NULL, 0, 1);
  v_pmidtemp := 0;
  v_pm_code := '';
  v_stresult := 'Update';
  v_count := v_count - 1;
  END LOOP;
  END IF;
  DROP TABLE IF EXISTS tmp_temp;
  END IF;
  IF (v_mode = 'update') THEN
  RAISE NOTICE '%', 11;
  UPDATE tbl_distributor_paymode_setting SET percentage = v_percentage, modifydate = CURRENT_TIMESTAMP, active = v_active, emp_id = v_empid WHERE pmid = v_pmid AND did = v_did;
  RAISE NOTICE '%', 12;
  v_stresult := 'Update';
  RETURN QUERY SELECT v_stresult;
  END IF;
  -- COMMIT (removed)
END;
$$;


