--
-- Name: usp_reseller_topup_request(integer, numeric, character varying, character varying, character varying, character varying, date, character varying, text, integer, character varying, character varying, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_reseller_topup_request(v_pmid integer DEFAULT 0, v_amount numeric DEFAULT NULL::numeric, v_paymode character varying DEFAULT NULL::character varying, v_bankname character varying DEFAULT NULL::character varying, v_branch_name character varying DEFAULT NULL::character varying, v_referance_id character varying DEFAULT NULL::character varying, v_referance_date date DEFAULT NULL::date, v_image character varying DEFAULT NULL::character varying, v_mem_remark text DEFAULT NULL::text, v_status integer DEFAULT NULL::integer, v_ifsc_code character varying DEFAULT NULL::character varying, INOUT v_result character varying DEFAULT NULL::character varying, v_banknameid integer DEFAULT 0) RETURNS character varying
    LANGUAGE plpgsql
    AS $$
BEGIN
  -- BEGIN TRAN (removed)
  BEGIN
  IF EXISTS(SELECT 1 FROM tbl_resellerwalletrequest WHERE referance_id = v_referance_id) THEN
  v_result := 'Referance Already Exists';
  -- ROLLBACK (removed)
  RETURN;
  END IF;
  IF (v_amount <= 0) THEN
  v_result := 'Invalid Amount requested!';
  -- ROLLBACK (removed)
  RETURN;
  END IF;
  INSERT INTO tbl_resellerwalletrequest (pmid, amount, date, paymode, bankname, branchname, referance_id, referance_date, image, mem_remark, admin_remark, actiondate, sys_tranid, status_update_from, status, "ifsc code", bankid) VALUES (v_pmid, v_amount, dbo.FUN_GETCURRENTDATE(), v_paymode, v_bankname, v_branch_name, v_referance_id, v_referance_date, v_image, v_mem_remark, NULL, dbo.FUN_GETCURRENTDATE(), GEN_RANDOM_UUID(), 0, 1, v_ifsc_code, v_banknameid);
  v_result := 'success';
  EXCEPTION WHEN OTHERS THEN
  PERFORM dbo.sp_errorlog();
