--
-- Name: usp_reseller_transfer_request(integer, integer, character varying, character varying, character varying, integer, integer, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_reseller_transfer_request(v_startrowindex integer DEFAULT 1, v_maxrows integer DEFAULT 100, v_fromdate character varying DEFAULT ''::character varying, v_todate character varying DEFAULT ''::character varying, v_transactionid character varying DEFAULT ''::character varying, v_did integer DEFAULT 2, v_transferid integer DEFAULT 1, v_totalcount integer DEFAULT 0) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_minindex INT;
  v_maxindex INT;
  v_query text;
BEGIN
  BEGIN
  v_minindex := (v_startrowindex - 1) * v_maxrows + 1;
  v_maxindex := v_startrowindex * v_maxrows;
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp (ROWNUMBER  INT GENERATED BY DEFAULT AS IDENTITY,
DATE VARCHAR(100),
AMOUNT DECIMAL(18,2),
TYPE VARCHAR(100),
STATUS VARCHAR(100)) ON COMMIT DROP;
  v_query := 'INSERT INTO #TEMP SELECT CONVERT(DATETIME,CREATE_DATE,106),AMOUNT,
            (CASE WHEN TRANSFERID=1 THEN ''BANK TRANSFER'' WHEN TRANSFERID=2 THEN ''PREPAID WALLET'' END ),
          (CASE WHEN TRANSFERREQUEST=0 THEN ''PENDING'' WHEN TRANSFERREQUEST=1 THEN ''APPROVED'' WHEN TRANSFERREQUEST=2 THEN ''REJECTED'' END) 
		   FROM TBL_RESELLER_TRANSFERTOBANK_REQUEST WHERE DID=''' || CAST(v_did AS VARCHAR(12)) || '''  ';
  IF ((v_fromdate <> '') AND (v_fromdate = '')) THEN
  v_query := v_query || ' AND CONVERT(DATE, CREATE_DATE) =  CONVERT(DATE, ''' || v_fromdate || ''')';
  END IF;
  IF ((v_fromdate = '') AND (v_todate <> '')) THEN
  v_query := v_query || ' AND CONVERT(DATE, CREATE_DATE) =  CONVERT(DATE, ''' || v_todate || ''') ';
  END IF;
  IF ((v_fromdate <> '') AND (v_todate <> '')) THEN
  v_query := v_query || ' AND CONVERT(DATE, CREATE_DATE) BETWEEN CONVERT(DATE, ''' || v_fromdate || ''') AND  CONVERT(DATE, ''' || v_todate || ''') ';
  END IF;
  IF (v_transferid > 0) THEN
  v_query := v_query || ' AND TRANSFERID=''' || CAST(v_transferid AS VARCHAR(30)) || ''' ';
  END IF;
  EXECUTE v_query;
  RAISE NOTICE '%', v_query;
  RETURN QUERY SELECT * FROM tmp_temp WHERE rownumber BETWEEN v_minindex AND v_maxindex;
  SELECT COUNT(rownumber) INTO v_totalcount FROM tmp_temp;
  DROP TABLE IF EXISTS tmp_temp;
  -- SET option (removed)
  EXCEPTION WHEN OTHERS THEN
  PERFORM dbo.sp_errorlog();
  IF (0 > 0) THEN
  -- ROLLBACK (removed)
  END IF;
  RETURN;
  END;
END;
$$;


