--
-- Name: usp_reseller_wallet(bigint, bigint, bigint, integer, integer, character varying, integer, integer, integer, character varying, integer, character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_reseller_wallet(v_rwid bigint DEFAULT 0, v_pmid bigint DEFAULT 0, v_walletid bigint DEFAULT 2, v_status integer DEFAULT 0, v_modifyby integer DEFAULT 0, v_result character varying DEFAULT ''::character varying, v_mode integer DEFAULT 2, v_startrowindex integer DEFAULT 1, v_maxrows integer DEFAULT 100, v_mobileno character varying DEFAULT ''::character varying, v_totalcount integer DEFAULT 0, v_comapnyname character varying DEFAULT ''::character varying) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_query text;
  v_minindex int;
  v_maxindex int;
BEGIN
  -- BEGIN TRAN (removed)
  BEGIN
  IF (v_mode = 1) THEN
  SELECT pmid INTO v_pmid FROM distributor_master WHERE mobileno = v_mobileno;
  IF (v_pmid = NULL OR v_pmid = '') THEN
  v_result := 'This Number does not exist.';
  ELSE
  IF EXISTS(SELECT 1 FROM tbl_resellergateway WHERE pmid = v_pmid AND walletid = v_walletid) THEN
  UPDATE tbl_resellergateway SET walletid = v_walletid, lastmodified = dbo.FUN_GETCURRENTDATE(), modifyby = v_modifyby, status = v_status WHERE rwid = v_rwid;
  v_result := 'Update';
  ELSE
  INSERT INTO tbl_resellergateway (pmid, walletid, status) VALUES (v_pmid, v_walletid, v_status);
  v_result := 'Insert';
  END IF;
  END IF;
  END IF;
  IF (v_mode = 2) THEN
  v_minindex := (v_startrowindex - 1) * v_maxrows + 1;
  v_maxindex := v_startrowindex * v_maxrows;
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp (ROWNUMBER BIGINT,
  COMPANYNAME VARCHAR(500),
  MOBILENO VARCHAR(15),
  WALLETNAME VARCHAR(50),
  STATUSS VARCHAR(50),
  RWID varchar(10)) ON COMMIT DROP;
  v_query := ' INSERT INTO #TEMP SELECT ROW_NUMBER() OVER( ORDER BY D.DOC DESC) AS ROWNUMBER, D.COMPANYNAME,D.MOBILENO,case when R.WalletID=1 then ''MLM'' when R.walletid=2 
then''Customer'' when R.walletid=3 then ''Online'' when R.walletid=4 then ''COD'' End WALLETNAME,  CASE WHEN R.STATUS=0 THEN ''ACTIVE'' WHEN R.STATUS=1 THEN ''DEACTIVE''   END STATUSS,R.RWID  FROM tbl_ResellerGateWay R
INNER JOIN Distributor_MASTER AS D ON D.PMID=R.PMID where 1=1';
  IF (v_mobileno <> '') THEN
  v_query := v_query || ('And D.MOBILENO=''' || v_mobileno || '''');
  END IF;
  IF (v_comapnyname <> '') THEN
  v_query := v_query || ('And D.COMPANYNAME=''' || v_comapnyname || '''');
  END IF;
  IF (v_walletid <> 0) THEN
  v_query := v_query || ('And R.WalletID= ''' || CAST(v_walletid AS VARCHAR) || '''');
  RAISE NOTICE '%', v_query;
  END IF;
  EXECUTE v_query;
  RETURN QUERY SELECT * FROM tmp_temp WHERE rownumber BETWEEN v_minindex AND v_maxindex;
  SELECT COUNT(rownumber) INTO v_totalcount FROM tmp_temp;
  DROP TABLE IF EXISTS tmp_temp;
  END IF;
  IF (v_mode = 3) THEN
  RETURN QUERY SELECT r.walletid, CAST(r.rwid AS VARCHAR) AS rwid, d.mobileno, r.status FROM tbl_resellergateway AS r INNER JOIN distributor_master AS d ON d.pmid = r.pmid WHERE r.rwid = v_rwid;
  END IF;
  EXCEPTION WHEN OTHERS THEN
  IF (0 > 0) THEN
  v_result := sqlerrm;
  END IF;
  -- ROLLBACK (removed)
  RETURN;
  END;
  -- COMMIT (removed)
END;
$$;


--
-- Name: usp_reseller_wise_customer_clubhistory_list(integer, integer, character varying, character varying, character varying, character varying, character varying, integer, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_reseller_wise_customer_clubhistory_list(v_startrowindex integer DEFAULT 1, v_maxrows integer DEFAULT 100, v_fromdate character varying DEFAULT ''::character varying, v_todate character varying DEFAULT ''::character varying, v_status character varying DEFAULT ''::character varying, v_searchfield character varying DEFAULT ''::character varying, v_searchvalue character varying DEFAULT ''::character varying, v_totalrecord integer DEFAULT 0, v_did integer DEFAULT 0) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_query text;
  v_maxregno text;
  v_query1 text;
  v_minindex INT;
  v_maxindex INT;
  v_count INT;
  v_totalcount INT;
  v_chid INT;
  v_totoalcancelamount DECIMAL(18,2);
BEGIN
  -- SET option (removed)
  v_query := '';
  v_maxregno := '';
  v_query1 := '';
  v_count := 1;
  v_totalcount := 0;
  v_chid := 0;
  v_minindex := (v_startrowindex - 1) * v_maxrows + 1;
  v_maxindex := v_startrowindex * v_maxrows;
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp (ROWNUMBER BIGINT,
	  CHID BIGINT,
	  FILENAME VARCHAR(150),
	  DATE timestamp,
	  CLUBGROUP VARCHAR(150),
	  TOTALREQUEST INT,
	  TOTALAMOUNT DECIMAL(18,8),
	  TOTAL_TANSACTION DECIMAL(18,8),
	  PROCESSDATE timestamp,
	  PROCESSBY VARCHAR(50),
	  PROCESSSTATUS VARCHAR(50),
	  PROCESSIPADDRESS VARCHAR(50),
	  BANKNAME VARCHAR(200),
	  TOTALPAID INT,
	  TOTALREJECT INT,
	  TRANSACTION_NO INT,
	  CANCELAMOUNT DECIMAL(18,2)) ON COMMIT DROP;
  v_query := 'INSERT INTO #TEMP SELECT ROW_NUMBER()OVER(ORDER BY CHID DESC) AS ROWNUMBER,CHID,FILENAME,CONVERT(DATE,DATE,105) AS DATE,
CLUBGROUP,TOTALREQUEST,TOTALAMOUNT,TOTAL_TANSACTION,
CONVERT(DATE,PROCESSDATE,105) AS PROCESSDATE,PROCESSBY,PROCESSSTATUS,PROCESSIPADDRESS,BANKNAME,
(SELECT ISNULL(COUNT(DISTINCT CLID),0)  FROM TBL_CUSTOMER_TRANSFERTOBANK  WHERE  STATUS=1 AND TCTTB IN  (SELECT * FROM SPLITSTRING(ALLWDID,'',''))) AS TOTALPAID,
(SELECT ISNULL(COUNT(DISTINCT CLID),0)  FROM TBL_CUSTOMER_TRANSFERTOBANK  WHERE  STATUS=2 AND TCTTB IN  (SELECT * FROM SPLITSTRING(ALLWDID,'',''))) AS TOTALREJECT,
(SELECT ISNULL(COUNT(1),0)  FROM TBL_CUSTOMER_TRANSFERTOBANK  WHERE   TCTTB IN  (SELECT * FROM SPLITSTRING(ALLWDID,'',''))) AS TRANSACTION_NO,0
FROM TBL_RESELLERWISE_CUSTOMER_CLUBHISTORY 
WHERE 1=1 and DID=''' || CAST(v_did AS VARCHAR(30)) || '''';
  RAISE NOTICE '%', v_query;
  EXECUTE v_query;
  SELECT COUNT(1) INTO v_totalcount FROM tmp_temp;
  WHILE (v_totalcount >= v_count) LOOP
  SELECT chid INTO v_chid FROM tmp_temp WHERE rownumber = v_count;
  SELECT COALESCE(SUM(amount), 0) INTO v_totoalcancelamount FROM tbl_customer_downloadclubdata WHERE status = 2 AND chid = v_chid;
  UPDATE tmp_temp SET cancelamount = v_totoalcancelamount WHERE chid = v_chid;
  v_count := v_count + 1;
  END LOOP;
  SELECT COALESCE(COUNT(1), 0) INTO v_totalrecord FROM tmp_temp;
  RETURN QUERY SELECT * FROM tmp_temp ORDER BY rownumber ASC NULLS FIRST;
  DROP TABLE IF EXISTS tmp_temp;
  -- SET option (removed)
END;
$$;


--
-- Name: usp_reseller_withdrawalhistory_report(integer, integer, character varying, character varying, character varying, character varying, character varying, character varying, integer, numeric, numeric, numeric, character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_reseller_withdrawalhistory_report(v_startrowindex integer DEFAULT 1, v_maxrows integer DEFAULT 100, v_searchfield character varying DEFAULT ''::character varying, v_searchvalue character varying DEFAULT ''::character varying, v_fromdate character varying DEFAULT ''::character varying, v_todate character varying DEFAULT ''::character varying, v_transactiontype character varying DEFAULT ''::character varying, v_status character varying DEFAULT ''::character varying, INOUT v_totalcount integer DEFAULT 0, INOUT v_totalwithdrawal numeric DEFAULT 0, INOUT v_totaltds numeric DEFAULT 0, INOUT v_totaladmincharges numeric DEFAULT 0, v_orderbydate character varying DEFAULT 'ASC'::character varying) RETURNS record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_minindex INT;
  v_maxindex INT;
  v_condition text;
  v_condition1 varchar(500);
  v_queryresult text;
  v_countquery text;
  v_tdsquery text;
  v_adminchargequery text;
  v_totalamount text;
  v_maxregno text;
  v_parmdefinition text;
  v_parmdefinition1 text;
  v_parmdefinitiontds text;
  v_parmdefinitionadmincharge text;
BEGIN
  v_condition := '';
  v_condition1 := '';
  v_queryresult := '';
  v_countquery := '';
  v_tdsquery := '';
  v_adminchargequery := '';
  v_totalamount := '';
  v_maxregno := '';
  v_minindex := (v_startrowindex - 1) * v_maxrows + 1;
  v_maxindex := v_startrowindex * v_maxrows;
  v_queryresult := 'SELECT ROW_NUMBER() OVER(ORDER BY TW.TRTBWID desc) AS ROWNUMBER, ISNULL(MM.Fname+''''+MM.LNAME,'''') AS USERNAME,
ISNULL(MM.FNAME,'''')+''''+ ISNULL(MM.LNAME,'''') AS NAME,
'''' AS CRDRTYPE,ISNULL(TW.AMOUNT,0) AS WITHDRAWALAMT,
0 AS ADMINCHARGE, 0 AS TDS,ISNULL(TW.PAIDSTATUS,'''')AS STATUS,
ISNULL(MM.EMAILID,'''') AS EMAILID, ISNULL(MM.Phone,'''') AS MOBILE, ISNULL(MM.PANNO,'''') AS PANNO,
ISNULL(TW.PROCEESSDATE,'''') AS DATE,ISNULL(WH.ACCOUNTHOLDERNAME,'''') AS ACCOUNTHOLDERNAME,
ISNULL(WH.ACCOUNTNO,'''') AS ACCOUNTNO,
ISNULL(WH.BANKNAME,'''') AS BANKNAME,ISNULL(WH.BRANCHNAME,'''') AS BRANCHNAME,ISNULL(WH.IFSCCODE,'''') AS IFSC,
ISNULL(TP.PAYMODE,'''') as Paymode
INTO #TEMPWIHTHDRAWALHISTORY 
FROM TBL_RESELLER_TRANSFERTOBANK_REQUEST TW 
INNER JOIN BANK_ACCOUNTS_DISTRIBUTOR WH ON TW.DID=WH.DID
INNER JOIN TBL_DISTRIBUTOR MM ON TW.DID=MM.DID
LEFT JOIN TBL_PAYMODE TP ON TW.PAYMODE=TP.PMOID
WHERE TW.PAIDSTATUS IN (1,3) ';
  v_parmdefinition := N'@TOTALCOUNT NVARCHAR(1000) OUTPUT';
  v_countquery := N'SELECT @TOTALCOUNT =COUNT(1) FROM TBL_RESELLER_TRANSFERTOBANK_REQUEST TW  WHERE 1=1 AND TW.PAIDSTATUS IN (1,3) ';
  v_parmdefinition1 := N' @TOTALWITHDRAWAL NVARCHAR(1000) OUTPUT';
  v_totalamount := N'SELECT @TOTALWITHDRAWAL= ISNULL(SUM(CAST(TW.AMOUNT AS DECIMAL(18,8))),0)  FROM  TBL_RESELLER_TRANSFERTOBANK_REQUEST TW  
	WHERE 1=1 AND TW.PAIDSTATUS IN (1,3) ';
  v_parmdefinitiontds := N' @TOTALTDS NVARCHAR(1000) OUTPUT';
  v_tdsquery := N'SELECT @TOTALTDS= 0  FROM  TBL_RESELLER_TRANSFERTOBANK_REQUEST TW   
	 WHERE 1=1  AND TW.PAIDSTATUS IN (1.3) ';
  v_parmdefinitionadmincharge := N' @TOTALADMINCHARGES NVARCHAR(1000) OUTPUT';
  v_adminchargequery := N'SELECT @TOTALADMINCHARGES=0  FROM  TBL_RESELLER_TRANSFERTOBANK_REQUEST TW  
	 WHERE 1=1 AND TW.PAIDSTATUS IN (1,3) ';
  IF (v_searchfield = 'USERNAME') THEN
  v_condition := v_condition || ' AND MM.USERNAME = ''' || CAST(v_searchvalue AS VARCHAR(100)) || ''' ';
  END IF;
  IF (v_searchfield = 'NAME') THEN
  v_condition := v_condition || ' AND ISNULL(MM.FNAME,'''')+''''+ISNULL(MM.LNAME,'''') = ''' || CAST(v_searchvalue AS VARCHAR(100)) || ''' ';
  END IF;
  IF (v_transactiontype <> '') THEN
  v_condition := v_condition || ' AND TW.CRDRTYPE = ''' || CAST(v_transactiontype AS VARCHAR(100)) || ''' ';
  END IF;
  IF (v_status <> '') THEN
  v_condition := v_condition || ' AND TW.PAIDSTATUS = ''' || CAST(v_status AS VARCHAR(100)) || ''' ';
  END IF;
  IF ((v_fromdate <> '') AND (v_todate = '')) THEN
  v_condition := v_condition || ' AND CONVERT(VARCHAR(15), TW.PROCEESSDATE, 105) =  CONVERT(VARCHAR(15), ''' || v_fromdate || ''', 105) ';
  END IF;
  IF ((v_fromdate = '') AND (v_todate <> '')) THEN
  v_condition := v_condition || ' AND CONVERT(VARCHAR(15),TW.PROCEESSDATE, 105) =  CONVERT(VARCHAR(15), ''' || v_todate || ''', 105) ';
  END IF;
  IF ((v_fromdate <> '') AND (v_todate <> '')) THEN
  v_condition := v_condition || ' AND CONVERT(VARCHAR(15), TW.PROCEESSDATE, 105) BETWEEN CONVERT(VARCHAR(15), ''' || v_fromdate || ''', 105) AND CONVERT(VARCHAR(15), ''' || v_todate || ''', 105)';
  END IF;
  v_queryresult := v_queryresult || v_condition || v_condition1 || ' ;SELECT  *  FROM #TEMPWIHTHDRAWALHISTORY WHERE ROWNUMBER BETWEEN ' || CAST(v_minindex AS text) || ' AND ' || CAST(v_maxindex AS text) || ' ' || v_condition1 || '';
  v_countquery := v_countquery || v_condition;
  v_totalamount := v_totalamount || v_condition;
  v_adminchargequery := v_adminchargequery || v_condition;
  v_tdsquery := v_tdsquery || v_condition;
  EXECUTE v_queryresult;
  RAISE NOTICE '%', v_queryresult;
  EXECUTE v_totalamount;
  EXECUTE v_tdsquery;
  EXECUTE v_adminchargequery;
  EXECUTE v_countquery;
END;
$$;


--
-- Name: usp_resellerbvrequest_admin(integer, integer, character varying, character varying, integer, character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_resellerbvrequest_admin(v_startrowindex integer DEFAULT 1, v_maxrows integer DEFAULT 100, v_fromdate character varying DEFAULT ''::character varying, v_todate character varying DEFAULT ''::character varying, v_totalcount integer DEFAULT 0, v_type character varying DEFAULT ''::character varying) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_minindex INT;
  v_maxindex INT;
  v_query text;
BEGIN
  BEGIN
  v_minindex := (v_startrowindex - 1) * v_maxrows + 1;
  v_maxindex := v_startrowindex * v_maxrows;
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp (ROWNUMBER int ,
ACCOUNTNO VARCHAR(100),
PHONE VARCHAR(100),
EMAILID VARCHAR(100),
InvoiceNo VARCHAR(100),
ORDERNO VARCHAR(100),
AMOUNT DECIMAL(18,2),
Commission DECIMAL(18,2),
Status varchar(30)) ON COMMIT DROP;
  v_query := 'INSERT INTO #Temp select distinct ROW_NUMBER() over(order by BV.processDate Desc) as ROWNUMBER,BK.ACCOUNTNO,dm.PHONE,dm.EMAILID,pm.InvoiceNo,PM.ORDERNO,PM.Total_Purchase_Cost as Amount,
			cast((CM.BVRate * PM.Total_BV) as decimal(18,2)) as  Commission,
			case when BV.ISADMINRELEASE=0 then ''Pending'' when BV.ISADMINRELEASE=1 then ''Approved'' end as Status
			from tbl_order_master   as OM
			inner join tbl_product_order_master as PM on OM.OrderID=PM.OrderId
			inner join TBL_CUSTOMERLOGIN as CL on CL.Loginid=om.loginid
			inner join TBL_DISTRIBUTOR as dm on dm.DID=cl.DID
			inner join TBL_COMPANYSETTINGS as CM on CM.pmid=dm.pmid
			inner join BANK_ACCOUNTS_DISTRIBUTOR as BK on BK.DID=dm.DID
			inner join TBL_RESELLERRELEASEBVDETAILS as BV on BV.ORDERNO=PM.Orderno 
			where 1=1 and PM.intstatus=6  
			';
  IF (v_type <> '') THEN
  v_query := v_query || ' And BV.ISADMINRELEASE = ''' || v_type || '''';
  END IF;
  IF ((v_fromdate <> '') AND (v_fromdate = '')) THEN
  v_query := v_query || ' AND CONVERT(DATE, OM.ORDERDATE) =  CONVERT(DATE, ''' || v_fromdate || ''')';
  END IF;
  IF ((v_fromdate = '') AND (v_todate <> '')) THEN
  v_query := v_query || ' AND CONVERT(DATE, OM.ORDERDATE) =  CONVERT(DATE, ''' || v_todate || ''') ';
  END IF;
  IF ((v_fromdate <> '') AND (v_todate <> '')) THEN
  v_query := v_query || ' AND CONVERT(DATE, OM.ORDERDATE) BETWEEN CONVERT(DATE, ''' || v_fromdate || ''') AND  CONVERT(DATE, ''' || v_todate || ''') ';
  END IF;
  v_query := v_query || ' group by  BK.ACCOUNTNO,dm.PHONE,dm.EMAILID,pm.InvoiceNo,PM.ORDERNO,PM.Total_Purchase_Cost,
			cast((CM.BVRate * PM.Total_BV) as decimal(18,2)),BV.processDate,BV.ISADMINRELEASE';
  RAISE NOTICE '%', v_query;
  EXECUTE v_query;
  RETURN QUERY SELECT * FROM tmp_temp WHERE rownumber BETWEEN v_minindex AND v_maxindex;
  SELECT COUNT(rownumber) INTO v_totalcount FROM tmp_temp;
  DROP TABLE IF EXISTS tmp_temp;
  -- SET option (removed)
  EXCEPTION WHEN OTHERS THEN
  PERFORM dbo.sp_errorlog();
  IF (0 > 0) THEN
  -- ROLLBACK (removed)
  END IF;
  RETURN;
  END;
END;
$$;


--
-- Name: usp_resellerpackagepurchase_onlinerequests(bigint, integer, character varying, character varying, character varying, character varying, character varying, character varying, character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_resellerpackagepurchase_onlinerequests(v_did bigint DEFAULT 0, v_trpid integer DEFAULT 0, v_source character varying DEFAULT ''::character varying, v_successurl character varying DEFAULT ''::character varying, v_failureurl character varying DEFAULT ''::character varying, v_inprocessurl character varying DEFAULT ''::character varying, v_cancelledurl character varying DEFAULT ''::character varying, v_stroutput character varying DEFAULT ''::character varying, v_transactionid character varying DEFAULT ''::character varying) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_amount DECIMAL(18,2);
  v_gstpercentage DECIMAL(18,2);
  v_gstamount DECIMAL(18,2);
  v_transid VARCHAR(50);
BEGIN
  BEGIN
  -- BEGIN TRAN (removed)
  v_amount := 0;
  v_gstpercentage := 0;
  v_gstamount := 0;
  IF (v_did <> 0) THEN
  IF EXISTS(SELECT 1 FROM tbl_distributor WHERE did = v_did) THEN
  v_transid := '';
  v_transid := CAST(CAST(GEN_RANDOM_UUID() AS BYTEA(5)) AS BIGINT) % 1000000000 + 1000000000;
  RETURN QUERY SELECT v_transid;
  IF EXISTS(SELECT 1 FROM dbo.tbl_reseller_packages WHERE trpid = v_trpid AND active = 1) THEN
  SELECT COALESCE(limits, 0) INTO v_gstpercentage FROM settings WHERE caption = 'GST Percentage' AND active = 1;
  SELECT COALESCE(packageamount, 0) INTO v_amount FROM dbo.tbl_reseller_packages WHERE trpid = v_trpid AND active = 1;
  IF (v_amount > 0) THEN
  v_gstamount := (v_amount * v_gstpercentage) / 100;
  v_amount := v_amount + v_gstamount;
  END IF;
  END IF;
  IF (v_amount = 0) THEN
  v_stroutput := 'Amount should be greater than zero.';
  -- COMMIT (removed)
  RETURN;
  END IF;
  IF (v_amount < 0) THEN
  v_stroutput := 'Amount should be positive.';
  -- COMMIT (removed)
  RETURN;
  END IF;
  IF EXISTS(SELECT 1 FROM dbo.tbl_resellerpackagepurchase_onlinerequests WHERE transactionid = v_transid) THEN
  v_stroutput := 'Error';
  -- ROLLBACK (removed)
  RETURN;
  ELSE
  INSERT INTO dbo.tbl_resellerpackagepurchase_onlinerequests (did, trpid, amount, paymentmode, transactionid, source, successurl, failureurl, inprocessurl, cancelledurl, purchasedate, status, createdate, active) VALUES (v_did, v_trpid, v_amount, 'ONLINE', v_transid, v_source, v_successurl, v_failureurl, v_inprocessurl, v_cancelledurl, dbo.FUN_GETCURRENTDATE(), 0, dbo.FUN_GETCURRENTDATE(), 1);
  v_stroutput := 'Success';
  v_transactionid := v_transid;
  -- COMMIT (removed)
  END IF;
  ELSE
  v_stroutput := 'Invalid Reseller.';
  -- COMMIT (removed)
  RETURN;
  END IF;
  END IF;
  EXCEPTION WHEN OTHERS THEN
  IF (0 <> 0) THEN
  v_stroutput := 'Error';
  -- ROLLBACK (removed)
  RETURN;
  END IF;
  END;
END;
$$;


--
-- Name: usp_resellerwalletrequest_details(character varying, character varying, integer, integer, character varying, character varying, integer, integer, numeric, numeric, integer, numeric); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_resellerwalletrequest_details(v_fromdate character varying DEFAULT ''::character varying, v_todate character varying DEFAULT ''::character varying, v_maxrows integer DEFAULT 100, v_startrowindex integer DEFAULT 1, v_searchfield character varying DEFAULT ''::character varying, v_searchvaluefield character varying DEFAULT ''::character varying, v_paymode integer DEFAULT 0, v_status integer DEFAULT 0, v_fromamount numeric DEFAULT 0, v_toamount numeric DEFAULT 0, v_totalcount integer DEFAULT 0, v_totalamount numeric DEFAULT 0) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_minindex INT;
  v_maxindex INT;
  v_query text;
BEGIN
  BEGIN
  v_query := '';
  v_minindex := (v_startrowindex - 1) * v_maxrows + 1;
  v_maxindex := v_startrowindex * v_maxrows;
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp (ROWNUMBER int,
	RequestDate varchar(10),
	USERNAME VARCHAR(100),
	MOBILENO varchar(30),
	AMOUNT decimal(18,2),
	Paymode VARCHAR(100),
	Status VARCHAR(100),
	ActionBY VARCHAR(1000),
	RWRID int,
	PMID int) ON COMMIT DROP;
  v_query := 'INSERT INTO #TEMP   select  ROW_NUMBER() over(order by RW.RWRID desc) as ROWNUMBER, convert(varchar(10),RW.DATE,105) as RequestDate,DM.COMPANYNAME +''('' + TD.USERID +'')'' as USERNAME,DM.MOBILENO,RW.AMOUNT,
case when RW.PAYMODE=1 then ''Bank'' when RW.PAYMODE=9 then ''DD'' when RW.PAYMODE=10 then ''Cheque'' when RW.PAYMODE=11 then ''NEFT'' when RW.PAYMODE=12 then ''RTGS'' when RW.PAYMODE=13 then ''IMPS'' end as Paymode,
case when RW.STATUS=1 then ''Pending'' when RW.STATUS=2 then ''Approved'' when RW.STATUS=3 then ''Rejected'' end as Status,
ISNULL(EM.Emp_LoginID,''N/A'') as ActionBY,RW.RWRID,RW.PMID from  TBL_RESELLERWALLETREQUEST as RW 
inner join TBL_DISTRIBUTOR as TD on RW.PMID=TD.PMID
inner join Distributor_MASTER as DM on DM.PMID=RW.PMID
left join  Tbl_Employee_Master  as Em on Em.Emp_ID=RW.STATUS_UPDATE_FROM  where 1=1 ';
  IF (v_status = 0) THEN
  v_query := v_query || ('AND RW.STATUS=1');
  END IF;
  IF (v_searchfield <> '' AND v_searchfield = 'Mobile No.') THEN
  IF (v_searchvaluefield <> '') THEN
  v_query := v_query || ('AND DM.MOBILENO=''' || v_searchvaluefield || '''');
  END IF;
  END IF;
  IF (v_searchfield <> '' AND v_searchfield = 'Company Name') THEN
  IF (v_searchvaluefield <> '') THEN
  v_query := v_query || ('AND DM.COMPANYNAME like ''%' || v_searchvaluefield || '%''');
  END IF;
  END IF;
  IF (v_paymode <> 0) THEN
  v_query := v_query || ('AND RW.PAYMODE =''' || CAST(v_paymode AS VARCHAR(10)) || '''');
  END IF;
  IF (v_status <> 0) THEN
  v_query := v_query || ('AND RW.STATUS =''' || CAST(v_status AS VARCHAR(10)) || '''');
  END IF;
  IF (v_fromamount <> 0 AND v_toamount = 0) THEN
  v_query := v_query || (' AND RW.AMOUNT = ''' || CAST(v_fromamount AS VARCHAR(50)) || ''' ');
  END IF;
  RAISE NOTICE '%', v_query;
  IF (v_fromamount = 0 AND v_toamount <> 0) THEN
  v_query := v_query || (' AND RW.AMOUNT = ''' || CAST(v_toamount AS VARCHAR(50)) || ''' ');
  END IF;
  IF (v_fromamount <> 0 AND v_toamount <> 0) THEN
  v_query := v_query || (' AND RW.AMOUNT BETWEEN ''' || CAST(v_fromamount AS VARCHAR(50)) || ''' AND ''' || CAST(v_toamount AS VARCHAR(50)) || '''');
  END IF;
  IF (v_fromdate <> '' AND v_todate = '') THEN
  v_query := v_query || (' AND Convert(Date,RW.Date,105) = CONVERT(DATE,''' || v_fromdate || ''',105) ');
  END IF;
  IF (v_fromdate = '' AND v_todate <> '') THEN
  v_query := v_query || (' AND Convert(Date,RW.Date,105) = CONVERT(DATE,''' || v_todate || ''',105) ');
  END IF;
  IF (v_fromdate <> '' AND v_todate <> '') THEN
  v_query := v_query || (' AND Convert(Date,RW.Date,105) BETWEEN CONVERT(DATE,''' || v_fromdate || ''',105) AND CONVERT(DATE,''' || v_todate || ''',105)');
  END IF;
  EXECUTE v_query;
  SELECT COUNT(1) INTO v_totalcount FROM tmp_temp;
  RETURN QUERY SELECT * FROM tmp_temp WHERE rownumber BETWEEN v_minindex AND v_maxindex;
  SELECT SUM(amount) INTO v_totalamount FROM tmp_temp WHERE rownumber BETWEEN v_minindex AND v_maxindex;
  DROP TABLE IF EXISTS tmp_temp;
  EXCEPTION WHEN OTHERS THEN
  PERFORM dbo.sp_errorlog();
  IF (0 > 0) THEN
  RETURN;
  END IF;
  END;
END;
$$;


--
-- Name: usp_resellerwalletstatement(integer, integer, character varying, character varying, character varying, integer, character varying, character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_resellerwalletstatement(v_startrowindex integer DEFAULT 1, v_maxrows integer DEFAULT 100, v_fromdate character varying DEFAULT ''::character varying, v_todate character varying DEFAULT ''::character varying, v_transactionid character varying DEFAULT ''::character varying, v_totalcount integer DEFAULT 0, v_did character varying DEFAULT '2'::character varying, v_type character varying DEFAULT ''::character varying) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_minindex INT;
  v_maxindex INT;
  v_query text;
BEGIN
  BEGIN
  v_minindex := (v_startrowindex - 1) * v_maxrows + 1;
  v_maxindex := v_startrowindex * v_maxrows;
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp (ROW_NUMBER int,
DATE timestamp,
TransactionID VARCHAR(100),
Type VARCHAR(100),
AMOUNT DECIMAL(18,2),
Balance DECIMAL(18,2),
MEM_REMARK varchar(500)) ON COMMIT DROP;
  v_query := 'INSERT INTO #Temp select ROW_NUMBER() over(order by RWSID desc) as ROW_NUMBER,Date,TraceNo  as TransactionID,CrDrType as Type,
			case when CrDrType=''Cr'' then Cr_amount  when CrDrType=''Dr'' then Dr_amount end as AMOUNT,Balance,Remarks as MEM_REMARK FROM TBL_RESELLERWALLETSTATEMENT where DID=cast(''' || v_did || ''' as int) ';
  RAISE NOTICE '%', v_query;
  IF (v_transactionid <> '') THEN
  v_query := v_query || ' And TraceNo = ''' || v_transactionid || '''';
  END IF;
  IF (v_type <> '') THEN
  v_query := v_query || ' And CrDrType = ''' || v_type || '''';
  END IF;
  IF ((v_fromdate <> '') AND (v_fromdate = '')) THEN
  v_query := v_query || ' AND CONVERT(DATE, DATE) =  CONVERT(DATE, ''' || v_fromdate || ''')';
  END IF;
  IF ((v_fromdate = '') AND (v_todate <> '')) THEN
  v_query := v_query || ' AND CONVERT(DATE, DATE) =  CONVERT(DATE, ''' || v_todate || ''') ';
  END IF;
  IF ((v_fromdate <> '') AND (v_todate <> '')) THEN
  v_query := v_query || ' AND CONVERT(DATE, DATE) BETWEEN CONVERT(DATE, ''' || v_fromdate || ''') AND  CONVERT(DATE, ''' || v_todate || ''') ';
  END IF;
  EXECUTE v_query;
  RETURN QUERY SELECT * FROM tmp_temp WHERE row_number BETWEEN v_minindex AND v_maxindex;
  SELECT COUNT(row_number) INTO v_totalcount FROM tmp_temp;
  DROP TABLE IF EXISTS tmp_temp;
  -- SET option (removed)
  EXCEPTION WHEN OTHERS THEN
  PERFORM dbo.sp_errorlog();
  IF (0 > 0) THEN
  -- ROLLBACK (removed)
  END IF;
  RETURN;
  END;
END;
$$;


--
-- Name: usp_resellerwalletstatement_admin(integer, integer, character varying, character varying, character varying, integer, character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_resellerwalletstatement_admin(v_startrowindex integer DEFAULT 1, v_maxrows integer DEFAULT 100, v_fromdate character varying DEFAULT ''::character varying, v_todate character varying DEFAULT ''::character varying, v_username character varying DEFAULT ''::character varying, v_totalcount integer DEFAULT 0, v_type character varying DEFAULT ''::character varying) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_minindex INT;
  v_maxindex INT;
  v_query text;
BEGIN
  BEGIN
  v_minindex := (v_startrowindex - 1) * v_maxrows + 1;
  v_maxindex := v_startrowindex * v_maxrows;
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp (ROW_NUMBER int,
DATE timestamp,
CompanyName VARCHAR(100),
EMAILID VARCHAR(100),
PHONE VARCHAR(100),
TransactionID VARCHAR(100),
Type VARCHAR(100),
AMOUNT DECIMAL(18,2),
Balance DECIMAL(18,2)) ON COMMIT DROP;
  v_query := 'INSERT INTO #Temp select ROW_NUMBER() over(order by RWSID desc) as ROW_NUMBER,Date,DM.companyname+''(''+ d.LOGINID +'')'' as CompanyName,d.EMAILID,D.PHONE,TraceNo  as TransactionID,CrDrType as Type,
			case when CrDrType=''Cr'' then Cr_amount  when CrDrType=''Dr'' then Dr_amount end as AMOUNT,Balance  FROM TBL_RESELLERWALLETSTATEMENT as RS
			inner join  TBL_DISTRIBUTOR as D on D.DID=rs.DID
			inner join Distributor_MASTER as DM on DM.PMID=D.PMID 
			 where 1=1  ';
  RAISE NOTICE '%', v_query;
  IF (v_username <> '') THEN
  v_query := v_query || ' And D.LOGINID = ''' || v_username || '''';
  END IF;
  IF (v_type <> '') THEN
  v_query := v_query || ' And CrDrType = ''' || v_type || '''';
  END IF;
  IF ((v_fromdate <> '') AND (v_fromdate = '')) THEN
  v_query := v_query || ' AND CONVERT(DATE, DATE) =  CONVERT(DATE, ''' || v_fromdate || ''')';
  END IF;
  IF ((v_fromdate = '') AND (v_todate <> '')) THEN
  v_query := v_query || ' AND CONVERT(DATE, DATE) =  CONVERT(DATE, ''' || v_todate || ''') ';
  END IF;
  IF ((v_fromdate <> '') AND (v_todate <> '')) THEN
  v_query := v_query || ' AND CONVERT(DATE, DATE) BETWEEN CONVERT(DATE, ''' || v_fromdate || ''') AND  CONVERT(DATE, ''' || v_todate || ''') ';
  END IF;
  EXECUTE v_query;
  RETURN QUERY SELECT * FROM tmp_temp WHERE row_number BETWEEN v_minindex AND v_maxindex;
  SELECT COUNT(row_number) INTO v_totalcount FROM tmp_temp;
  DROP TABLE IF EXISTS tmp_temp;
  -- SET option (removed)
  EXCEPTION WHEN OTHERS THEN
  PERFORM dbo.sp_errorlog();
  IF (0 > 0) THEN
  -- ROLLBACK (removed)
  END IF;
  RETURN;
  END;
END;
$$;


--
-- Name: usp_resellerwise_customer_transfer_bank_history(integer, integer, character varying, character varying, character varying, character varying, integer, integer, character varying, bigint, bigint, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_resellerwise_customer_transfer_bank_history(v_startrowindex integer DEFAULT 1, v_maxrows integer DEFAULT 100, v_searchfield character varying DEFAULT ''::character varying, v_searchvalue character varying DEFAULT ''::character varying, v_fromdate character varying DEFAULT ''::character varying, v_todate character varying DEFAULT ''::character varying, v_totalcount integer DEFAULT 0, v_mode integer DEFAULT 0, v_requestid character varying DEFAULT ''::character varying, v_plid bigint DEFAULT 0, v_sumofdata bigint DEFAULT 0, v_did integer DEFAULT 0) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_minindex int;
  v_maxindex int;
  v_query text;
BEGIN
  v_minindex := (v_startrowindex - 1) * v_maxrows + 1;
  v_maxindex := v_startrowindex * v_maxrows;
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp (ROWNUMBER int GENERATED BY DEFAULT AS IDENTITY, 
	TCTTB BIGINT,       
	FNAME varchar(500),      
	PHONE varchar(500),	
	EMAILID varchar(500),	
	WITHDRAWALAMOUNT DECIMAL(18,2),	
	TRANSACTIONID varchar(500),	
	WITHDRAWALDATE timestamp,
	ACCOUNTHOLDERNAME varchar(500),	
	ACCOUNTNO varchar(500),
	BANKNAME varchar(500),	
	IFSC varchar(500),
	Loginid varchar(50),
	CLID BIGINT,
	Status int,
	BRANCHNAME VARCHAR(50),
	RESELLERNAME VARCHAR(100)) ON COMMIT DROP;
  v_query := 'INSERT INTO #TEMP SELECT CTB.TCTTB,CL.FNAME,CL.PHONE,CL.EMAILID,CTBH.WITHDRAWALAMOUNT,CTBH.TRANSACTIONID,CTB.WITHDRAWALDATE,CTBH.ACCOUNTHOLDERNAME,CTBH.ACCOUNTNO,CTBH.BANKNAME,
CTBH.IFSC,CL.LOGINID,CTB.CLID,CTB.STATUS,CTBH.BRANCHNAME,DM.COMPANYNAME
 FROM TBL_CUSTOMER_TRANSFERTOBANK CTB  
 JOIN TBL_CUSTOMER_TRANSFERTOBANKHISTORY CTBH ON CTB.TRANSACTIONID=CTBH.TRANSACTIONID
LEFT JOIN TBL_CUSTOMERLOGIN CL ON CL.CLID=CTB.CLID 
LEFT JOIN DISTRIBUTOR_MASTER DM ON CL.DID=DM.PLID
WHERE CTB.STATUS=0 AND CTB.ISPAID=0 ';
  IF ((v_fromdate <> '') AND (v_todate = '')) THEN
  v_query := v_query || ' AND CONVERT(DATE, CTB.WITHDRAWALDATE, 105) BETWEEN  CONVERT(DATE, ''' || v_fromdate || ''', 105) AND  CONVERT(DATE, DBO.FUN_GETCURRENTDATE(), 105)';
  END IF;
  IF ((v_fromdate = '') AND (v_todate <> '')) THEN
  v_query := v_query || 'AND CONVERT(DATE, CTB.WITHDRAWALDATE, 105) BETWEEN  CONVERT(DATE, ''' || v_todate || ''', 105) AND  CONVERT(DATE, DBO.FUN_GETCURRENTDATE(), 105)';
  END IF;
  IF ((v_fromdate <> '') AND (v_todate <> '')) THEN
  v_query := v_query || 'AND CONVERT(DATE, CTB.WITHDRAWALDATE, 105) BETWEEN CONVERT(DATE, ''' || v_fromdate || ''', 105) AND  CONVERT(DATE, ''' || v_todate || ''', 105)';
  END IF;
  IF (v_searchfield = 'PHONE') THEN
  v_query := v_query || ' AND PL.PHONE= ''' || v_searchvalue || ''' ';
  END IF;
  IF (v_searchfield = 'EMAILID') THEN
  v_query := v_query || ' AND PL.EMAILID= ''' || v_searchvalue || ''' ';
  END IF;
  IF (v_searchfield = 'TRANSACTIONID') THEN
  v_query := v_query || ' AND CTBH.TRANSACTIONID= ''' || v_searchvalue || ''' ';
  END IF;
  IF (v_did > 0) THEN
  v_query := v_query || ' AND CL.DID= ''' || CAST(v_did AS VARCHAR(30)) || ''' ';
  END IF;
  v_query := v_query || ' ORDER BY CTB.WITHDRAWALDATE DESC';
  EXECUTE v_query;
  RAISE NOTICE '%', v_query;
  RETURN QUERY SELECT * FROM tmp_temp WHERE rownumber BETWEEN v_minindex AND v_maxindex;
  IF (v_mode = 1) THEN
  SELECT COUNT(rownumber) INTO v_totalcount FROM tmp_temp;
  INSERT INTO tbl_downloaded_bank_excel_customer_history (accountholdername, bankname, accountno, ifsccode, branchname, payoutamount, downloadeddate, requestid) SELECT accountholdername, bankname, accountno, ifsc, branchname, withdrawalamount, dbo.FUN_GETCURRENTDATE(), v_requestid FROM tmp_temp;
  INSERT INTO tbl_downloaded_bank_excel_customer VALUES (v_plid, '', v_requestid, v_totalcount, 0, 1, dbo.FUN_GETCURRENTDATE());
  END IF;
  SELECT COALESCE(COUNT(rownumber), 0) INTO v_totalcount FROM tmp_temp;
  SELECT COALESCE(SUM(withdrawalamount), 0) INTO v_sumofdata FROM tmp_temp;
  DROP TABLE IF EXISTS tmp_temp;
  -- SET option (removed)
END;
$$;


--
-- Name: usp_resellerwise_customer_withdrawalhistory_report(integer, integer, character varying, character varying, character varying, character varying, character varying, character varying, integer, numeric, numeric, numeric, character varying, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_resellerwise_customer_withdrawalhistory_report(v_startrowindex integer DEFAULT 1, v_maxrows integer DEFAULT 100, v_searchfield character varying DEFAULT ''::character varying, v_searchvalue character varying DEFAULT ''::character varying, v_fromdate character varying DEFAULT ''::character varying, v_todate character varying DEFAULT ''::character varying, v_transactiontype character varying DEFAULT ''::character varying, v_status character varying DEFAULT ''::character varying, INOUT v_totalcount integer DEFAULT 0, INOUT v_totalwithdrawal numeric DEFAULT 0, INOUT v_totaltds numeric DEFAULT 0, INOUT v_totaladmincharges numeric DEFAULT 0, v_orderbydate character varying DEFAULT ''::character varying, v_did integer DEFAULT 0) RETURNS record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_minindex INT;
  v_maxindex INT;
  v_condition text;
  v_condition1 varchar(500);
  v_queryresult text;
  v_countquery text;
  v_tdsquery text;
  v_adminchargequery text;
  v_totalamount text;
  v_maxregno text;
  v_parmdefinition text;
  v_parmdefinition1 text;
  v_parmdefinitiontds text;
  v_parmdefinitionadmincharge text;
BEGIN
  v_condition := '';
  v_condition1 := '';
  v_queryresult := '';
  v_countquery := '';
  v_tdsquery := '';
  v_adminchargequery := '';
  v_totalamount := '';
  v_maxregno := '';
  v_minindex := (v_startrowindex - 1) * v_maxrows + 1;
  v_maxindex := v_startrowindex * v_maxrows;
  v_queryresult := 'SELECT ROW_NUMBER() OVER(ORDER BY TW.TCTTB desc) AS ROWNUMBER, ISNULL(MM.USERNAME,'''') AS USERNAME,ISNULL(MM.FNAME,'''')+''''+ ISNULL(MM.LNAME,'''') AS NAME,
	ISNULL(TW.CRDRTYPE,'''') AS CRDRTYPE,ISNULL(TW.WITHDRAWALAMOUNT,0) AS WITHDRAWALAMT,
	ISNULL(TW.ADMINCHARGES,0) AS ADMINCHARGE, ISNULL(TW.TDS,0) AS TDS,ISNULL(TW.STATUS,'''')AS STATUS,
	 ISNULL(MM.EMAILID,'''') AS EMAILID, ISNULL(MM.Phone,'''') AS MOBILE, ISNULL(MM.PANNO,'''') AS PANNO,
	ISNULL(TW.WITHDRAWALDATE,'''') AS [DATE],ISNULL(WH.ACCOUNTHOLDERNAME,'''') AS ACCOUNTHOLDERNAME,ISNULL(WH.ACCOUNTNO,'''') AS ACCOUNTNO,
	ISNULL(WH.BANKNAME,'''') AS BANKNAME,ISNULL(WH.BRANCHNAME,'''') AS BRANCHNAME,ISNULL(WH.IFSC,'''') AS IFSC,ISNULL(TP.PAYMODE,'''') as Paymode,DM.COMPANYNAME as RESELLERNAME
	INTO #TEMPWIHTHDRAWALHISTORY FROM TBL_CUSTOMER_TRANSFERTOBANK TW 
	INNER JOIN TBL_CUSTOMER_TRANSFERTOBANKHISTORY WH ON TW.TCTTB=WH.TCTTBID
	INNER JOIN TBL_CUSTOMERLOGIN MM ON TW.CLID=MM.CLID
	LEFT JOIN TBL_PAYMODE TP ON TW.PAYMODE=TP.PMOID
	LEFT JOIN DISTRIBUTOR_MASTER DM ON MM.DID=DM.PLID
	 WHERE TW.STATUS IN (1,3) ';
  v_parmdefinition := N'@TOTALCOUNT NVARCHAR(1000) OUTPUT';
  v_countquery := N'SELECT @TOTALCOUNT =COUNT(1) FROM TBL_CUSTOMER_TRANSFERTOBANK TW INNER JOIN TBL_CUSTOMERLOGIN MM ON TW.CLID=MM.CLID  WHERE 1=1 AND TW.STATUS IN (1,3)';
  v_parmdefinition1 := N' @TOTALWITHDRAWAL NVARCHAR(1000) OUTPUT';
  v_totalamount := N'SELECT @TOTALWITHDRAWAL= ISNULL(SUM(CAST(TW.WITHDRAWALAMOUNT AS DECIMAL(18,8))),0)  FROM  TBL_CUSTOMER_TRANSFERTOBANK TW  
	INNER JOIN TBL_CUSTOMER_TRANSFERTOBANKHISTORY WH ON TW.TCTTB=WH.TCTTBID INNER JOIN TBL_CUSTOMERLOGIN MM ON TW.CLID=MM.CLID WHERE 1=1 AND TW.STATUS IN (1,3)';
  v_parmdefinitiontds := N' @TOTALTDS NVARCHAR(1000) OUTPUT';
  v_tdsquery := N'SELECT @TOTALTDS= ISNULL(SUM(CAST(TW.TDS AS DECIMAL(18,8))),0)  FROM  TBL_CUSTOMER_TRANSFERTOBANK TW   
	INNER JOIN TBL_CUSTOMER_TRANSFERTOBANKHISTORY WH ON TW.TCTTB=WH.TCTTBID INNER JOIN TBL_CUSTOMERLOGIN MM ON TW.CLID=MM.CLID WHERE 1=1  AND TW.STATUS IN (1.3)';
  v_parmdefinitionadmincharge := N' @TOTALADMINCHARGES NVARCHAR(1000) OUTPUT';
  v_adminchargequery := N'SELECT @TOTALADMINCHARGES= ISNULL(SUM(CAST(TW.ADMINCHARGES AS DECIMAL(18,8))),0)  FROM  TBL_CUSTOMER_TRANSFERTOBANK TW  
	INNER JOIN TBL_CUSTOMER_TRANSFERTOBANKHISTORY WH ON TW.TCTTB=WH.TCTTBID INNER JOIN TBL_CUSTOMERLOGIN MM ON TW.CLID=MM.CLID WHERE 1=1 AND TW.STATUS IN (1,3)';
  IF (v_searchfield = 'USERNAME') THEN
  v_condition := v_condition || ' AND MM.USERNAME = ''' || CAST(v_searchvalue AS VARCHAR(100)) || ''' ';
  END IF;
  IF (v_searchfield = 'NAME') THEN
  v_condition := v_condition || ' AND ISNULL(MM.FNAME,'''')+''''+ISNULL(MM.LNAME,'''') = ''' || CAST(v_searchvalue AS VARCHAR(100)) || ''' ';
  END IF;
  IF (v_transactiontype <> '') THEN
  v_condition := v_condition || ' AND TW.CRDRTYPE = ''' || CAST(v_transactiontype AS VARCHAR(100)) || ''' ';
  END IF;
  IF (v_status <> '') THEN
  v_condition := v_condition || ' AND TW.STATUS = ''' || CAST(v_status AS VARCHAR(100)) || ''' ';
  END IF;
  IF ((v_fromdate <> '') AND (v_todate = '')) THEN
  v_condition := v_condition || ' AND CONVERT(VARCHAR(15), TW.WITHDRAWALDATE, 105) =  CONVERT(VARCHAR(15), ''' || v_fromdate || ''', 105) ';
  END IF;
  IF ((v_fromdate = '') AND (v_todate <> '')) THEN
  v_condition := v_condition || ' AND CONVERT(VARCHAR(15),TW.WITHDRAWALDATE, 105) =  CONVERT(VARCHAR(15), ''' || v_todate || ''', 105) ';
  END IF;
  IF ((v_fromdate <> '') AND (v_todate <> '')) THEN
  v_condition := v_condition || ' AND CONVERT(VARCHAR(15), TW.WITHDRAWALDATE, 105) BETWEEN CONVERT(VARCHAR(15), ''' || v_fromdate || ''', 105) AND CONVERT(VARCHAR(15), ''' || v_todate || ''', 105)';
  END IF;
  IF (v_did > 0) THEN
  v_condition := v_condition || ' AND MM.DID=''' || CAST(v_did AS VARCHAR(30)) || '''';
  END IF;
  IF (v_orderbydate = 'ASC') THEN
  v_condition1 := v_condition1 || ' ORDER BY DATE ASC';
  ELSE
  v_condition1 := v_condition1 || ' ORDER BY DATE DESC';
  END IF;
  v_queryresult := v_queryresult || v_condition || v_condition1 || ' ;SELECT  *  FROM #TEMPWIHTHDRAWALHISTORY WHERE ROWNUMBER BETWEEN ' || CAST(v_minindex AS text) || ' AND ' || CAST(v_maxindex AS text) || ' ' || v_condition1 || '';
  v_countquery := v_countquery || v_condition;
  v_totalamount := v_totalamount || v_condition;
  v_adminchargequery := v_adminchargequery || v_condition;
  v_tdsquery := v_tdsquery || v_condition;
  EXECUTE v_queryresult;
  RAISE NOTICE '%', v_queryresult;
  EXECUTE v_totalamount;
  EXECUTE v_tdsquery;
  EXECUTE v_adminchargequery;
  EXECUTE v_countquery;
END;
$$;


--
-- Name: usp_resetpassord(character varying, character varying, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_resetpassord(v_logid character varying DEFAULT ''::character varying, v_passowrd character varying DEFAULT NULL::character varying, INOUT v_intresult integer DEFAULT NULL::integer) RETURNS integer
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_plid bigint;
BEGIN
  v_intresult := 0;
  IF EXISTS(SELECT plid FROM portal_login WHERE RTRIM(LTRIM(loginid)) = RTRIM(LTRIM(v_logid)) AND active = 1 AND RTRIM(LTRIM(password)) = v_passowrd) THEN
  v_intresult := 3;
  RETURN;
  END IF;
  IF EXISTS(SELECT plid FROM portal_login WHERE RTRIM(LTRIM(loginid)) = RTRIM(LTRIM(v_logid)) AND active = 1) THEN
  SELECT plid INTO v_plid FROM portal_login WHERE RTRIM(LTRIM(loginid)) = RTRIM(LTRIM(v_logid)) AND active = 1;
  UPDATE portal_login SET password = v_passowrd WHERE plid = v_plid;
  v_intresult := 1;
  RETURN;
  ELSE
  v_intresult := 2;
  RETURN;
  END IF;
END;
$$;


--
-- Name: usp_resselerlogindetails(integer, integer, character varying, boolean, character varying, character varying, character varying, character varying, integer, integer, character varying, character varying, text, character varying, character varying, character varying, integer, integer, integer, integer, bigint); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_resselerlogindetails(v_startrowindex integer DEFAULT 1, v_maxrows integer DEFAULT 100, v_orderbyfield character varying DEFAULT ''::character varying, v_asc boolean DEFAULT false, v_searchfield character varying DEFAULT ''::character varying, v_searchvalue character varying DEFAULT ''::character varying, v_fromdate character varying DEFAULT ''::character varying, v_todate character varying DEFAULT ''::character varying, v_mode integer DEFAULT 0, v_recordcount integer DEFAULT 0, v_cid character varying DEFAULT ''::character varying, v_accnttype character varying DEFAULT ''::character varying, v_usertype text DEFAULT '0'::text, v_eggagetypes character varying DEFAULT ''::character varying, v_orderby character varying DEFAULT ''::character varying, v_mobile character varying DEFAULT ''::character varying, v_isdownload integer DEFAULT 0, v_userid integer DEFAULT 0, v_qualification integer DEFAULT 0, v_gender integer DEFAULT 0, v_did bigint DEFAULT 1) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_sqlquery text;
  v_minindex INT;
  v_maxindex INT;
  v_newusername varchar(200);
BEGIN
  -- SET option (removed)
  DROP TABLE IF EXISTS tmp_temp66;
  CREATE TEMP TABLE tmp_temp66 (ROWNUMBER BIGINT,
REFRAL_ID VARCHAR(150),
LOGINID VARCHAR(150),
USERNAME VARCHAR(150),
NAME VARCHAR(150),
PHONE VARCHAR(150),
PLID BIGINT,
DOC VARCHAR(200),
ACCOUNTTYPE VARCHAR(50),
COUNTRY VARCHAR(100),
JOINEDVIA text,
STATUS VARCHAR(100),
IPADDRESS VARCHAR(100),
ENGAGEDIN VARCHAR(50),
ENGTOOLTIP VARCHAR(100),
FULLNAME VARCHAR(500),
Emailid varchar(100),
Reference_Username varchar(100),
DID INT,
CustomerWallet decimal(18,2),
MLMWallet decimal(18,2)) ON COMMIT DROP;
  v_sqlquery := '';
  v_minindex := (v_startrowindex - 1) * v_maxrows + 1;
  v_maxindex := v_startrowindex * v_maxrows;
  v_sqlquery := 'INSERT INTO #TEMP66 SELECT ROW_NUMBER() OVER (ORDER BY PL1.DOC DESC) AS ROWNUMBER,ISNULL(PL2.USERNAME,''-'') AS REFRAL_ID,PL1.LOGINID,ISNULL(PL1.USERNAME,''-'') AS USERNAME,ISNULL(TD.NAME,'''') AS NAME,ISNULL(PL1.PHONE,'''') as PHONE,
   PL1.CLID,  FORMAT(PL1.DOC,''dd-MMM-yyyy hh:mm:ss tt'')  AS DOC, CASE ISNULL(PL1.QPAYREGNO,0) WHEN 0 THEN ''QLOOK'' ELSE ''QPAY'' END AS ACCOUNTTYPE,
   (CASE WHEN C.COUNTRYNAME=''UNITED STATES'' THEN ''US'' WHEN C.COUNTRYNAME=''UNITED KINGDOM'' THEN ''UK'' ELSE  C.COUNTRYNAME END  ) AS COUNTRYNAME,
    (Case When PL1.IPADDRESS=''By Admin'' Then ''Admin'' When isnull(PL1.SpounserType,0)=0 Then ''Direct'' When PL1.SpounserType=2 Then ''Member Referrals'' When PL1.SpounserType=1 Then ''Customer Referrals'' END) As JoinedVia,
	--(Case When PL1.IPADDRESS=''By Admin'' Then ''Admin'' When PL1.INTRO_REFID=0 Then ''Direct'' When PL1.INTRO_REFID>0 Then ''Customer Referrals'' END) As JoinedVia,
   (CASE PL1.ACTIVE WHEN 1 THEN ''Active'' WHEN 0 THEN ''Deactive'' END)AS STATUS,ISNULL(PL1.IPADDRESS,''-'') AS IPADDRESS,
   CASE WHEN (ISNULL(PL1.PMID,0)=0 AND ISNULL(PL1.INTRO_PLID,0)=0 AND ISNULL(SMD.SMDID,0)=0) THEN ''None'' 
   WHEN (ISNULL(PL1.PMID,0)<>0 AND ISNULL(PL1.INTRO_PLID,0)=0 AND ISNULL(SMD.SMDID,0)=0) THEN ''BL'' 
   WHEN (ISNULL(PL1.PMID,0)=0 AND ISNULL(PL1.INTRO_PLID,0)<>0 AND ISNULL(SMD.SMDID,0)=0) THEN ''RP'' 
   WHEN (ISNULL(PL1.PMID,0)=0 AND ISNULL(PL1.INTRO_PLID,0)=0 AND ISNULL(SMD.SMDID,0)<>0) THEN ''PPC''
   WHEN (ISNULL(PL1.PMID,0)<>0 AND ISNULL(PL1.INTRO_PLID,0)<>0 AND ISNULL(SMD.SMDID,0)=0) THEN ''BL, RP''
   WHEN (ISNULL(PL1.PMID,0)<>0 AND ISNULL(PL1.INTRO_PLID,0)=0 AND ISNULL(SMD.SMDID,0)<>0) THEN ''BL, PPC''
   WHEN (ISNULL(PL1.PMID,0)=0 AND ISNULL(PL1.INTRO_PLID,0)<>0 AND ISNULL(SMD.SMDID,0)<>0) THEN ''RP, PPC''
   WHEN (ISNULL(PL1.PMID,0)<>0 AND ISNULL(PL1.INTRO_PLID,0)<>0 AND ISNULL(SMD.SMDID,0)<>0) THEN ''BL, RP, PPC'' END AS ENGAGEDIN,
   CASE WHEN (ISNULL(PL1.PMID,0)=0 AND ISNULL(PL1.INTRO_PLID,0)=0 AND ISNULL(SMD.SMDID,0)=0) THEN ''None'' 
   WHEN (ISNULL(PL1.PMID,0)<>0 AND ISNULL(PL1.INTRO_PLID,0)=0 AND ISNULL(SMD.SMDID,0)=0) THEN ''Bussiness Listing'' 
   WHEN (ISNULL(PL1.PMID,0)=0 AND ISNULL(PL1.INTRO_PLID,0)<>0 AND ISNULL(SMD.SMDID,0)=0) THEN ''Referral Program'' 
   WHEN (ISNULL(PL1.PMID,0)=0 AND ISNULL(PL1.INTRO_PLID,0)=0 AND ISNULL(SMD.SMDID,0)<>0) THEN ''Pay Per Click''
   WHEN (ISNULL(PL1.PMID,0)<>0 AND ISNULL(PL1.INTRO_PLID,0)<>0 AND ISNULL(SMD.SMDID,0)=0) THEN ''Bussiness Listing, Referral Program''
   WHEN (ISNULL(PL1.PMID,0)<>0 AND ISNULL(PL1.INTRO_PLID,0)=0 AND ISNULL(SMD.SMDID,0)<>0) THEN ''Bussiness Listing, Pay Per Click''
  WHEN (ISNULL(PL1.PMID,0)=0 AND ISNULL(PL1.INTRO_PLID,0)<>0 AND ISNULL(SMD.SMDID,0)<>0) THEN ''Referral Program, Pay Per Click''
   WHEN (ISNULL(PL1.PMID,0)<>0 AND ISNULL(PL1.INTRO_PLID,'''')<>0 AND ISNULL(SMD.SMDID,0)<>0) THEN ''Bussiness Listing, Referral Program, Pay Per Click'' end as engtooltip,
   ISNULL(PL1.FNAME,'''') +'' ''+ISNULL(PL1.LNAME,'''') AS NAME,PL1.EMAILID,ISNULL(RUN.Username,'''') AS Reference_Username,
   ISNULL(PL1.DID,0) AS DID ,isnull(CW.AVAILABLEBALANCE,0) as CustomerWallet ,isnull(CMW.AVAILABLEBALANCE,0) as MLMWallet
   FROM TBL_CUSTOMERLOGIN PL1 LEFT JOIN PORTAL_MASTER PM ON PM.PMID=ISNULL(PL1.PMID,0)
   LEFT JOIN TBL_DISTRIBUTOR TD ON TD.DID=PL1.DID
   LEFT JOIN SPONSOR_MASTER_DETAIL SMD ON SMD.PLID=PL1.CLID
   LEFT JOIN TBL_CUSTOMERLOGIN PL2 ON PL2.CLID=PL1.INTRO_REFID JOIN
   COUNTRY C ON C.CID=PL1.CID LEFT JOIN MEMBER_MASTER MM ON MM.PLID=PL1.CLID 
   left join Tbl_ReferenceUserName as RUN on RUN.CLID=PL2.CLID
   left join tbl_customerwallet as CW on CW.CLID=PL1.CLID
   left join  tbl_customermlmwallet as CMW on CMW.CLID=PL1.CLID
    WHERE PL1.ACTIVE>=0 ';
  IF (v_fromdate = '' OR v_todate = '') THEN
  IF (v_fromdate <> '') THEN
  v_sqlquery := v_sqlquery || ' AND CONVERT(DATE, PL1.DOC,103) >= REPLACE(CONVERT(DATE,''' || v_fromdate || ''',103),''/'',''-'') ';
  END IF;
  IF (v_todate <> '') THEN
  v_sqlquery := v_sqlquery || ' AND CONVERT(DATE, PL1.DOC,103)  <=REPLACE(CONVERT(DATE,''' || v_todate || ''',103),''/'',''-'') ';
  END IF;
  END IF;
  IF (v_fromdate <> '' AND v_todate <> '') THEN
  v_sqlquery := v_sqlquery || '  AND  CONVERT(DATE, PL1.DOC,103)  BETWEEN  REPLACE(CONVERT(DATE,''' || v_fromdate || ''',103),''/'',''-'')  AND REPLACE(CONVERT(DATE,''' || v_todate || ''',103),''/'',''-'')';
  END IF;
  IF (v_mobile <> '') THEN
  v_sqlquery := v_sqlquery || (' AND PL1.PHONE =''' || v_mobile || ''' ');
  END IF;
  IF (v_searchfield = 'Emailid') THEN
  v_sqlquery := v_sqlquery || ' AND PL1.Emailid LIKE ''%' || v_searchvalue || '%'' ';
  END IF;
  IF (v_searchfield = 'FULLNAME') THEN
  v_sqlquery := v_sqlquery || ' AND (PL1.FNAME+'' ''+PL1.LNAME) LIKE ''%' || v_searchvalue || '%'' ';
  END IF;
  IF (v_searchfield = 'PHONE') THEN
  v_sqlquery := v_sqlquery || ' AND PL1.PHONE LIKE ''%' || v_searchvalue || '%'' ';
  END IF;
  IF (v_searchfield = 'SourceID') THEN
  v_sqlquery := v_sqlquery || ' AND PL1.Reference_Username LIKE ''%' || v_searchvalue || '%'' ';
  END IF;
  IF (v_searchfield = 'REFERAL') THEN
  v_sqlquery := v_sqlquery || ' AND PL2.LOGINID LIKE ''%' || v_searchvalue || '%'' ';
  END IF;
  IF (v_searchfield = 'USERNAME') THEN
  IF (EXISTS(SELECT 1 FROM portal_login WHERE username = v_searchvalue)) THEN
  v_sqlquery := v_sqlquery || (' AND PL1.USERNAME LIKE ''%' || v_searchvalue || '%''');
  ELSE
  IF (EXISTS(SELECT 1 FROM portal_login_history WHERE username = v_searchvalue)) THEN
  v_newusername := '';
  SELECT (SELECT username FROM portal_login WHERE plid IN (SELECT plid FROM portal_login_history WHERE username = v_searchvalue)) INTO v_newusername;
  v_sqlquery := v_sqlquery || (' AND PL1.USERNAME LIKE ''%' || v_newusername || '%''');
  ELSE
  v_sqlquery := v_sqlquery || ' AND PL1.USERNAME LIKE ''%' || v_searchvalue || '%'' ';
  END IF;
  END IF;
  END IF;
  IF (v_cid <> '') THEN
  v_sqlquery := v_sqlquery || (' AND C.CID =' || v_cid || ' ');
  END IF;
  IF (v_qualification <> '0') THEN
  v_sqlquery := v_sqlquery || (' AND PL1.HIGHESTQUALIFICATION =' || CAST(v_qualification AS VARCHAR(30)) || ' ');
  END IF;
  IF (v_gender <> '0') THEN
  v_sqlquery := v_sqlquery || (' AND PL1.GENDER =' || CAST(v_gender AS VARCHAR(30)) || ' ');
  END IF;
  IF (v_usertype <> '') THEN
  IF (v_usertype = 'ByAdmin') THEN
  v_sqlquery := v_sqlquery || (' AND PL1.IPADDRESS=''By Admin''');
  END IF;
  IF (v_usertype = 'Direct') THEN
  v_sqlquery := v_sqlquery || (' AND (PL1.INTRO_REFID=0 OR PL1.INTRO_REFID=1)');
  END IF;
  IF (v_usertype = 'CustomerReferrals') THEN
  v_sqlquery := v_sqlquery || (' AND PL1.INTRO_REFID>1');
  END IF;
  IF (v_usertype = 'ActiveCustomerReferrals') THEN
  v_sqlquery := v_sqlquery || (' AND PL1.INTRO_REFID IN(Select PLID From Tbl_AllSubscriptionMaster Where ISNULL(IsApproved,0)=1 AND ''~''+AllPackageType+''~'' Like ''%~1~%'')');
  END IF;
  END IF;
  IF (v_eggagetypes <> '') THEN
  IF (v_eggagetypes = 'BL') THEN
  v_sqlquery := v_sqlquery || (' AND (ISNULL(PL1.PMID,0)<>0 AND ISNULL(PL1.INTRO_PLID,0)=0 AND ISNULL(SMD.SMDID,0)=0) ');
  END IF;
  IF (v_eggagetypes = 'RP') THEN
  v_sqlquery := v_sqlquery || (' AND (ISNULL(PL1.PMID,0)=0 AND ISNULL(PL1.INTRO_PLID,0)<>0 AND ISNULL(SMD.SMDID,0)=0) ');
  END IF;
  IF (v_eggagetypes = 'PPC') THEN
  v_sqlquery := v_sqlquery || (' AND (ISNULL(PL1.PMID,0)=0 AND ISNULL(PL1.INTRO_PLID,0)=0 AND ISNULL(SMD.SMDID,0)<>0) ');
  END IF;
  IF (v_eggagetypes = 'BL, RP') THEN
  v_sqlquery := v_sqlquery || (' AND (ISNULL(PL1.PMID,0)<>0 AND ISNULL(PL1.INTRO_PLID,0)<>0 AND ISNULL(SMD.SMDID,0)=0) ');
  END IF;
  IF (v_eggagetypes = 'BL, PPC') THEN
  v_sqlquery := v_sqlquery || (' AND (ISNULL(PL1.PMID,0)<>0 AND ISNULL(PL1.INTRO_PLID,0)=0 AND ISNULL(SMD.SMDID,0)<>0) ');
  END IF;
  IF (v_eggagetypes = 'RP, PPC') THEN
  v_sqlquery := v_sqlquery || (' AND (ISNULL(PL1.PMID,0)=0 AND ISNULL(PL1.INTRO_PLID,0)<>0 AND ISNULL(SMD.SMDID,0)<>0) ');
  END IF;
  IF (v_eggagetypes = 'BL, RP, PPC') THEN
  v_sqlquery := v_sqlquery || (' AND (ISNULL(PL1.PMID,0)<>0 AND ISNULL(PL1.INTRO_PLID,0)<>0 AND ISNULL(SMD.SMDID,0)<>0) ');
  END IF;
  END IF;
  IF (v_did > 0) THEN
  v_sqlquery := v_sqlquery || (' and TD.DID =' || CAST(v_did AS VARCHAR(30)) || '');
  END IF;
  IF (v_orderby = 'DESC') THEN
  v_sqlquery := v_sqlquery || ('  ORDER BY PL1.DOC ' || v_orderby || ' ');
  END IF;
  IF (v_orderby = 'ASC') THEN
  v_sqlquery := v_sqlquery || ('  ORDER BY PL1.DOC  ');
  END IF;
  EXECUTE v_sqlquery;
  RETURN QUERY SELECT * FROM tmp_temp66 WHERE rownumber BETWEEN v_minindex AND v_maxindex;
  SELECT COUNT(rownumber) INTO v_recordcount FROM tmp_temp66;
  SELECT COUNT(1) INTO v_recordcount FROM tmp_temp66;
  IF (v_isdownload = 0) THEN
  RETURN QUERY SELECT * FROM tmp_temp66 WHERE rownumber BETWEEN v_startrowindex AND v_maxrows;
  ELSE
  RETURN QUERY SELECT rownumber AS "s.no.", TO_DATE(doc, 'DD TMMon YYYY') AS "reg.date", username AS "user name", loginid AS "email id", fullname AS name, ipaddress AS ip, joinedvia AS "joined via", status AS status, engagedin AS "engagged in" FROM tmp_temp66;
  INSERT INTO tbl_exceltrackingreport (report_name, file_name, type, download_by, download_date) VALUES ('All Member', 'AllMember-List.xls', 1, v_userid, CURRENT_TIMESTAMP);
  END IF;
  DROP TABLE IF EXISTS tmp_temp66;
  -- SET option (removed)
END;
$$;


--
-- Name: usp_returnresellerwallet(integer, character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_returnresellerwallet(v_mode integer DEFAULT 0, v_ordernumber character varying DEFAULT ''::character varying) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_clid INT;
  v_loginid VARCHAR(500);
  v_did INT;
  v_shoppingwallet DECIMAL(18,8);
  v_pmid int;
  v_distributorbalance decimal(18,8);
  v_billamount DECIMAL(18,8);
  v_orderid VARCHAR(500);
  v_totalpaidamount DECIMAL(18,8);
  v_oorid INT;
  v_remark VARCHAR(600);
  v_tranid Varchar(100);
BEGIN
  -- BEGIN TRAN (removed)
  -- SET option (removed)
  v_clid := 0;
  v_loginid := '';
  v_did := 0;
  v_pmid := 0;
  v_distributorbalance := 0;
  v_billamount := 0;
  v_orderid := '';
  v_totalpaidamount := 0;
  v_remark := '';
  v_tranid := '';
  SELECT loginid, amount, orderid, oorid INTO v_loginid, v_billamount, v_orderid, v_oorid FROM tbl_orderonlinerequests WHERE transactionid = v_ordernumber;
  SELECT clid, did INTO v_clid, v_did FROM tbl_customerlogin WHERE loginid = v_loginid;
  SELECT pmid INTO v_pmid FROM tbl_distributor WHERE did = v_did;
  SELECT COALESCE(available_wallet, 0) INTO v_distributorbalance FROM tbl_distributor_prepaid_setting WHERE pmid = v_pmid;
  SELECT COALESCE(traceno, '') INTO v_tranid FROM tbl_resellerwalletstatement WHERE did = v_did AND crdrtype = 'DR' ORDER BY rwsid DESC NULLS LAST LIMIT 1;
  IF (v_mode = 1) THEN
  IF EXISTS(SELECT 1 FROM tbl_orderpaymentsdetails WHERE transid = v_ordernumber AND status = 1) THEN
  v_remark := 'Credit against order number ' || v_orderid;
  UPDATE tbl_distributor_prepaid_setting SET available_wallet = available_wallet + v_billamount, used_wallet = used_wallet - v_billamount WHERE pmid = v_pmid;
  INSERT INTO tbl_resellerwalletstatement (did, date, crdrtype, cr_amount, dr_amount, remarks, status, traceno, old_bal, balance, trsid) VALUES (v_did, dbo.FUN_GETCURRENTDATE(), 'CR', v_billamount, 0, v_remark, 1, v_tranid, v_distributorbalance, (v_distributorbalance + v_billamount), 2);
  UPDATE tbl_orderpaymentsdetails SET status = 2 WHERE transid = v_ordernumber AND status = 1;
  END IF;
  END IF;
  IF (v_mode = 2) THEN
  IF EXISTS(SELECT 1 FROM tbl_orderpaymentsdetails WHERE transid = v_ordernumber AND status = 1) THEN
  v_remark := 'Credit against RECHARGE ' || v_orderid;
  UPDATE tbl_distributor_prepaid_setting SET available_wallet = available_wallet + v_billamount, used_wallet = used_wallet - v_billamount WHERE pmid = v_pmid;
  INSERT INTO tbl_resellerwalletstatement (did, date, crdrtype, cr_amount, dr_amount, remarks, status, traceno, old_bal, balance, trsid) VALUES (v_did, dbo.FUN_GETCURRENTDATE(), 'CR', 0, v_billamount, v_remark, 1, v_tranid, v_distributorbalance, (v_distributorbalance + v_billamount), 1);
  UPDATE tbl_orderpaymentsdetails SET status = 2 WHERE transid = v_ordernumber AND status = 1;
  END IF;
  END IF;
  -- SET option (removed)
  -- COMMIT (removed)
END;
$$;


--
-- Name: usp_reviewmaster(integer, integer, character varying, character varying, character varying, character varying, integer, character varying, integer, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_reviewmaster(v_startrowindex integer DEFAULT 1, v_maxrows integer DEFAULT 1000, v_searchfield character varying DEFAULT ''::character varying, v_searchvalue character varying DEFAULT ''::character varying, v_fromdate character varying DEFAULT ''::character varying, v_todate character varying DEFAULT ''::character varying, v_totalcount integer DEFAULT 0, v_productname character varying DEFAULT ''::character varying, v_rating integer DEFAULT 0, v_status integer DEFAULT 0) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_minindex int;
  v_maxindex int;
  v_query text;
BEGIN
  v_minindex := (v_startrowindex - 1) * v_maxrows + 1;
  v_maxindex := v_startrowindex * v_maxrows;
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp (RWID bigint GENERATED BY DEFAULT AS IDENTITY,
PMID bigint,
NAME Varchar(30),
Loginid Varchar(50),
REVIEWTITLE varchar(100),
REVIEWDESC text,
STARS int,
DATE varchar(50),
STATUS int,
ReviewType int,
productname varchar(300),
emailid varchar(300),
phone varchar(30),	
SubCatName varchar(200),
fullname varchar(200),
email varchar(200),
SPRID int,
SubPrCode varchar(200),
ratingcount int) ON COMMIT DROP;
  v_query := 'insert into #temp select rm.PMID,isnull(rm.NAME,'''') as NAME,isnull(rm.EMAILID,'''') as Loginid,
 isnull(rm.REVIEWTITLE,'''') as REVIEWTITLE,isnull(rm.REVIEWDESC,'''') as REVIEWDESC,isnull(rm.STARS,0)
  as STARS,
 FORMAT(rm.DATE,''dd-MMM-yyyy hh:mm:ss tt'') AS Date,isnull(rm.STATUS,0) as STATUS,isnull(rm.ReviewType,0) as ReviewType ,
 mps.producttitle,cl.emailid,cl.PHONE,km.SubCatName,cl.fname+''''+cl.lname,rm.emailid ,isp.sprid,isp.SubPrCode,
 isnull((select count(1) from TBL_REVIEWMASTER where EMAILID= rm.EMAILID),0)as ratingcount
 from TBL_REVIEWMASTER rm left join IMS_masterProduct mps on mps.MPRID=rm.PMID
left join tbl_Sub_Category km on km.SUBCATID=mps.SubCategoryId left join IMS_SubProduct isp on isp.mprid=mps.mprid
left join tbl_customerlogin cl on cl.LOGINID=rm.EMAILID where rm.rwid>0';
  IF (v_rating > 0) THEN
  v_query := v_query || ' AND rm.STARS =''' || CAST(v_rating AS VARCHAR(50)) || '''';
  END IF;
  IF (v_status = 1) THEN
  v_query := v_query || ' AND rm.STATUS =1';
  END IF;
  IF (v_status = 2) THEN
  v_query := v_query || ' AND rm.STATUS =0';
  END IF;
  IF (v_fromdate = '' OR v_todate = '') THEN
  IF (v_fromdate <> '') THEN
  v_query := v_query || ' AND CONVERT(DATE, rm.DATE,103) >= REPLACE(CONVERT(DATE,''' || v_fromdate || ''',103),''/'',''-'') ';
  END IF;
  IF (v_todate <> '') THEN
  v_query := v_query || ' AND CONVERT(DATE, rm.DATE,103)  <=REPLACE(CONVERT(DATE,''' || v_todate || ''',103),''/'',''-'') ';
  END IF;
  END IF;
  IF (v_fromdate <> '' AND v_todate <> '') THEN
  v_query := v_query || '  AND  CONVERT(DATE, rm.DATE,103)  BETWEEN  REPLACE(CONVERT(DATE,''' || v_fromdate || ''',103),''/'',''-'')  AND REPLACE(CONVERT(DATE,''' || v_todate || ''',103),''/'',''-'')';
  END IF;
  IF (v_searchfield = 'Email') THEN
  v_query := v_query || 'AND cl.emailid LIKE ''%' || v_searchvalue || '%''';
  END IF;
  IF (v_searchfield = 'NAME') THEN
  v_query := v_query || ' AND cl.fname+''''+cl.lname LIKE ''%' || v_searchvalue || '%'' ';
  END IF;
  IF (v_productname <> '') THEN
  v_productname := REPLACE(v_productname, '''', '''''');
  END IF;
  v_query := v_query || ' and mps.producttitle like ''%' || v_productname || '%''';
  IF (v_searchfield = 'Phone') THEN
  v_query := v_query || ' AND cl.PHONE LIKE ''%' || v_searchvalue || '%''';
  END IF;
  EXECUTE v_query;
  RETURN QUERY SELECT * FROM tmp_temp WHERE rwid BETWEEN v_minindex AND v_maxindex;
  SELECT COUNT(rwid) INTO v_totalcount FROM tmp_temp;
  DROP TABLE IF EXISTS tmp_temp;
  -- SET option (removed)
END;
$$;


--
-- Name: usp_reviewslist(character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_reviewslist(v_productid character varying DEFAULT '46'::character varying) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
BEGIN
  -- BEGIN TRAN (removed)
  -- SET option (removed)
  RETURN QUERY SELECT rv.pmid, (cm.fname || '' || lname) AS name, rv.reviewtitle, rv.reviewdesc, rv.stars, CAST(TO_CHAR(date, 'DD TMMon YYYY') AS VARCHAR(100)) AS reviewdate FROM tbl_reviewmaster AS rv LEFT JOIN tbl_customerlogin AS cm ON rv.emailid = cm.loginid WHERE rv.pmid = v_productid AND status = 1;
  -- SET option (removed)
  -- COMMIT (removed)
END;
$$;


--
-- Name: usp_rewardmaster(integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_rewardmaster(v_mode integer DEFAULT 0) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_start timestamp;
  v_end timestamp;
  v_x INT;
BEGIN
  RETURN QUERY SELECT CAST(EXTRACT(epoch FROM CAST(CAST(todate AS TIMESTAMP) AS TIMESTAMP) - CAST(CAST(CURRENT_TIMESTAMP AS TIMESTAMP) AS TIMESTAMP)) / 86400 AS BIGINT) AS day, * FROM tbl_reward_master WHERE status = 1;
END;
$$;


--
-- Name: usp_roimaster(integer, integer, integer, integer, integer, integer, integer, numeric, integer, numeric, integer, numeric, integer, numeric, integer, character varying, integer, integer, integer, integer, integer, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_roimaster(v_mode integer DEFAULT 2, v_startrowindex integer DEFAULT 1, v_maxrows integer DEFAULT 100, v_tmroiamid integer DEFAULT 0, v_tsmid integer DEFAULT 0, v_totalcreditedaddpoints integer DEFAULT 0, v_maxnoofclicksperdayforview integer DEFAULT 0, v_priceperlinkforview numeric DEFAULT 0.00, v_maxnooflinkperdayforshare integer DEFAULT 0, v_priceperlinkforshare numeric DEFAULT 0.00, v_maxnoofblogperday integer DEFAULT 0, v_priceperblog numeric DEFAULT 0.00, v_maxnoofclassifiedperday integer DEFAULT 0, v_priceperclassified numeric DEFAULT 0.00, v_lastupdateddate integer DEFAULT 0, v_status character varying DEFAULT ''::character varying, v_maxpointforview integer DEFAULT 0, v_maxpointforshare integer DEFAULT 0, v_maxpointforblog integer DEFAULT 0, v_maxpointforclassified integer DEFAULT 0, v_intresult integer DEFAULT 0, v_recordcount integer DEFAULT 0) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_perdaypointsforblog Decimal(10,2);
  v_perdaypointforclassified Decimal(10,2);
  v_noofdayforpackage double precision;
  v_perdaypointsforshare Decimal(10,2);
  v_perdaypointforview Decimal(10,2);
BEGIN
  -- SET option (removed)
  v_perdaypointsforblog := 0.00;
  v_perdaypointforclassified := 0.00;
  v_noofdayforpackage := 0;
  v_perdaypointsforshare := 0.00;
  v_perdaypointforview := 0.00;
  IF (v_mode = 1) THEN
  SELECT noofdaysforactivation INTO v_noofdayforpackage FROM tbl_subscriptionmaster WHERE tsmid = v_tsmid;
  SELECT v_maxpointforblog / v_noofdayforpackage INTO v_perdaypointsforblog;
  SELECT v_maxpointforclassified / v_noofdayforpackage INTO v_perdaypointforclassified;
  SELECT v_maxpointforshare / v_noofdayforpackage INTO v_perdaypointsforshare;
  SELECT v_maxpointforview / v_noofdayforpackage INTO v_perdaypointforview;
  IF NOT EXISTS(SELECT 1 FROM tbl_roimaster WHERE tsmid = v_tsmid) THEN
  RETURN QUERY SELECT noofdaysforactivation FROM tbl_subscriptionmaster WHERE tsmid = 2;
  INSERT INTO tbl_roimaster (tsmid, totalcreditedaddpoints, maxnoofclicksperdayforview, priceperlinkforview, maxnooflinkperdayforshare, priceperlinkforshare, maxnoofblogperday, priceperblog, maxnoofclassifiedperday, priceperclassified, lastupdateddate, status, maxpointforview, maxpointforshare, maxpointforblog, maxpointforclaassified, pointperdayforblog, pointperdayforclassified, pointperdayforshare, pointperdayforview) VALUES (v_tsmid, v_totalcreditedaddpoints, v_maxnoofclicksperdayforview, v_priceperlinkforview, v_maxnooflinkperdayforshare, v_priceperlinkforshare, v_maxnoofblogperday, v_priceperblog, v_maxnoofclassifiedperday, v_priceperclassified, CURRENT_TIMESTAMP, 1, v_maxpointforview, v_maxpointforshare, v_maxpointforblog, v_maxpointforclassified, v_perdaypointsforblog, v_perdaypointforclassified, v_perdaypointsforshare, v_perdaypointforview);
  v_intresult := 1;
  ELSE
  v_intresult := -1;
  END IF;
  END IF;
  IF (v_mode = 2) THEN
  RETURN QUERY SELECT ROW_NUMBER() OVER (ORDER BY tmroiamid NULLS FIRST) AS rownunber, tmroiamid, tsm.subscriptionheading, trm.totalcreditedaddpoints, trm.maxnoofclicksperdayforview, trm.priceperlinkforview, trm.maxnooflinkperdayforshare, trm.priceperlinkforshare, trm.maxnoofclassifiedperday, trm.priceperclassified, trm.maxnoofblogperday, trm.priceperblog, CAST(TO_CHAR(trm.lastupdateddate, 'DD-MM-YYYY') AS VARCHAR(30)) AS lastupdateddate, CASE WHEN trm.status = 1 THEN 'Active' ELSE 'Deactive' END AS status FROM tbl_roimaster AS trm INNER JOIN tbl_subscriptionmaster AS tsm ON trm.tsmid = tsm.tsmid;
  SELECT COUNT(1) INTO v_recordcount FROM tbl_roimaster;
  END IF;
  IF (v_mode = 3) THEN
  RETURN QUERY SELECT * FROM tbl_roimaster WHERE tmroiamid = v_tmroiamid;
  END IF;
  IF (v_mode = 4) THEN
  SELECT noofdaysforactivation INTO v_noofdayforpackage FROM tbl_subscriptionmaster WHERE tsmid = v_tsmid;
  SELECT v_maxpointforblog / v_noofdayforpackage INTO v_perdaypointsforblog;
  SELECT v_maxpointforclassified / v_noofdayforpackage INTO v_perdaypointforclassified;
  SELECT v_maxpointforshare / v_noofdayforpackage INTO v_perdaypointsforshare;
  SELECT v_maxpointforview / v_noofdayforpackage INTO v_perdaypointforview;
  UPDATE tbl_roimaster SET tsmid = v_tsmid, totalcreditedaddpoints = v_totalcreditedaddpoints, maxnoofclicksperdayforview = v_maxnoofclicksperdayforview, priceperlinkforview = v_priceperlinkforview, maxnooflinkperdayforshare = v_maxnooflinkperdayforshare, priceperlinkforshare = v_priceperlinkforshare, maxnoofblogperday = v_maxnoofblogperday, priceperblog = v_priceperblog, maxnoofclassifiedperday = v_maxnoofclassifiedperday, priceperclassified = v_priceperclassified, lastupdateddate = CURRENT_TIMESTAMP, maxpointforview = v_maxpointforview, maxpointforshare = v_maxpointforshare, maxpointforblog = v_maxpointforblog, maxpointforclaassified = v_maxpointforclassified, pointperdayforblog = v_perdaypointsforblog, pointperdayforclassified = v_perdaypointforclassified, pointperdayforshare = v_perdaypointsforshare, pointperdayforview = v_perdaypointsforshare WHERE tmroiamid = v_tmroiamid;
  v_intresult := 2;
  END IF;
  -- SET option (removed)
  IF (0 <> 0) THEN
  v_intresult := 0;
  RETURN;
  END IF;
END;
$$;


--
-- Name: usp_roll_list(integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_roll_list(v_rid integer DEFAULT 0) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_active boolean;
  v_count1 INT;
  v_count2 INT;
  v_mid INT;
  v_sid INT;
  v_isedit INT;
  v_submenuchecked INT;
  v_submenuedit INT;
  v_rolldelete INT;
BEGIN
  v_isedit := 0;
  v_submenuchecked := 0;
  v_submenuedit := 0;
  v_rolldelete := 0;
  v_active := 0;
  SELECT COUNT(sid) INTO v_submenuchecked FROM tbl_submenurole WHERE rid = v_rid;
  DROP TABLE IF EXISTS tmp_tempmain;
  CREATE TEMP TABLE tmp_tempmain ON COMMIT DROP AS SELECT ROW_NUMBER() OVER (ORDER BY mm.displayorder ASC NULLS FIRST, mm.mid ASC NULLS FIRST, sm.displayorder ASC NULLS FIRST) AS rownumber, mm.mid, mm.title AS mainmenutitle, mm.herf AS mainhref, mm.aiclass, mm.bclass, sm.displayorder, COALESCE(sm.sid, 0) AS sid, COALESCE(sm.title, '') AS submenutitle, COALESCE(sm.herf, '') AS subhref, v_active AS active, v_isedit AS userright_isedit, v_rolldelete AS rolldelete, CASE WHEN mm.ischecked = 1 THEN mm.ischecked ELSE (SELECT COUNT(mid) FROM tbl_submenurole WHERE mid = 10 AND active = 1 AND sid = 0) END AS mainmenuview, mm.isedit AS mainmenuedit, sm.ischecked AS submenuview, sm.isedit AS submenuedit, v_submenuchecked AS submenuchecked, v_submenuedit AS submenueditcount FROM tbl_mainmenu AS mm LEFT JOIN tbl_submenu AS sm ON sm.mid = mm.mid WHERE mm.status = 1 AND COALESCE(sm.status, 1) = 1 ORDER BY mm.displayorder ASC NULLS FIRST, sm.displayorder ASC NULLS FIRST;
  DROP TABLE IF EXISTS tmp_tempactivemenu;
  CREATE TEMP TABLE tmp_tempactivemenu ON COMMIT DROP AS SELECT ROW_NUMBER() OVER (ORDER BY mid ASC NULLS FIRST, sid ASC NULLS FIRST) AS rownumber, * FROM tbl_submenurole WHERE active = 1 AND rid = v_rid ORDER BY mid ASC NULLS FIRST, sid ASC NULLS FIRST;
  v_count1 := 1;
  SELECT COUNT(1) INTO v_count2 FROM tmp_tempactivemenu;
  WHILE (v_count1 <= v_count2) LOOP
  SELECT mid, sid, isedit, COALESCE(isdelete, 0) INTO v_mid, v_sid, v_isedit, v_rolldelete FROM tmp_tempactivemenu WHERE rownumber = v_count1;
  UPDATE tmp_tempmain SET active = 1, userright_isedit = v_isedit, rolldelete = COALESCE(v_rolldelete, 0) WHERE mid = v_mid AND sid = v_sid;
  v_count1 := v_count1 + 1;
  END LOOP;
  DROP TABLE IF EXISTS tmp_tempactivemenu;
  RETURN QUERY SELECT * FROM tmp_tempmain ORDER BY rownumber ASC NULLS FIRST;
  DROP TABLE IF EXISTS tmp_tempmain;
END;
$$;


--
-- Name: usp_sales_report(integer, integer, integer, character varying, boolean, character varying, character varying, character varying, character varying, character varying, integer, character varying, character varying, character varying, character varying, integer, integer, character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_sales_report(v_startrowindex integer DEFAULT 1, v_maxrows integer DEFAULT 100, v_reqfield integer DEFAULT 0, v_orderbyfield character varying DEFAULT ''::character varying, v_asc boolean DEFAULT false, v_searchfield character varying DEFAULT ''::character varying, v_searchvalue character varying DEFAULT ''::character varying, v_fromdate character varying DEFAULT ''::character varying, v_todate character varying DEFAULT ''::character varying, v_mode character varying DEFAULT '0'::character varying, v_recordcount integer DEFAULT 0, v_status character varying DEFAULT ''::character varying, v_loginid character varying DEFAULT ''::character varying, v_username character varying DEFAULT ''::character varying, v_mobile character varying DEFAULT ''::character varying, v_isdownload integer DEFAULT 0, v_userid integer DEFAULT 0, v_invoice character varying DEFAULT ''::character varying) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_regno BIGINT;
  v_sqlquery text;
  v_modestatus varchar(10);
  v_newusername varchar(200);
  v_totalwithouttax decimal(18,2);
  v_totalservicetax decimal(18,2);
  v_totalamount decimal(18,2);
BEGIN
  -- SET option (removed)
  v_sqlquery := '';
  v_modestatus := '0';
  v_sqlquery := '';
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp (Rownumber Int GENERATED BY DEFAULT AS IDENTITY,
TASMID bigint,
With_out_tax_Amount decimal(18,2),
TotalPayableAmount decimal(18,2),
service_tax decimal(18,2),
ModeName varchar(250),
Transaction_id varchar(250),
username varchar(150),
emailid varchar(150),
fullname varchar(150),
phone varchar(50),
CommentORRemark text,
RegNo bigint,
IsApproved int,
PuchaseDate varchar(35),
plid bigint,
invoice_no varchar(50)) ON COMMIT DROP;
  v_sqlquery := v_sqlquery || (' INSERT INTO #TEMP SELECT TID.TASMID,ISNULL(With_out_tax_Amount,0) as With_out_tax_Amount,isnull(TotalPayableAmount,0) as TotalPayableAmount,isnull(TID.service_tax,0),TID.ModeName,
isnull(TID.Transaction_id,''''),isnull(pl.username,''''),isnull(pl.LoginID,''''),
isnull(pl.FNAME,'''')+'' ''+isnull(pl.Lname,'''') as fullname, isnull(pl.phone,0),isnull(TID.CommentORRemark,''''),TID.RegNo,isnull(IsApproved,0),
FORMAT(TID.PuchaseDate,''dd-MMM-yyyy''),TID.plid,isnull(TID.invoice_no,'''') FROM Tbl_AllSubscriptionMaster TID 
 inner join portal_login pl on pl.plid=TID.RegNo where TID.IsApproved=1 ');
  IF (v_mobile <> '') THEN
  v_sqlquery := v_sqlquery || (' AND PL.phone LIKE ''%' || v_mobile || '%'' ');
  END IF;
  IF (v_searchvalue = 'LOGINID') THEN
  v_sqlquery := v_sqlquery || (' AND PL.emailid LIKE ''%' || v_searchfield || '%'' ');
  END IF;
  IF (v_searchvalue = 'USERNAME') THEN
  v_sqlquery := v_sqlquery || (' AND PL.USERNAME LIKE ''%' || v_searchfield || '%'' ');
  END IF;
  IF (v_searchvalue = 'Phone') THEN
  v_sqlquery := v_sqlquery || (' AND  pl.phone LIKE ''%' || v_searchfield || '%'' ');
  END IF;
  IF (v_invoice <> '') THEN
  v_sqlquery := v_sqlquery || (' AND TID.invoice_no LIKE ''%' || v_invoice || '%'' ');
  END IF;
  IF (v_loginid <> '') THEN
  v_sqlquery := v_sqlquery || ' AND ISNULL(PL.emailid,'''') LIKE ''%' || v_loginid || '%''';
  END IF;
  IF (v_username <> '') THEN
  IF (EXISTS(SELECT 1 FROM portal_login WHERE username = v_searchvalue)) THEN
  v_sqlquery := v_sqlquery || (' AND PL.USERNAME LIKE ''%' || v_username || '%''');
  ELSE
  IF (EXISTS(SELECT 1 FROM portal_login_history WHERE username = v_username)) THEN
  v_newusername := '';
  SELECT (SELECT username FROM portal_login WHERE plid IN (SELECT plid FROM portal_login_history WHERE username = v_username)) INTO v_newusername;
  v_sqlquery := v_sqlquery || (' AND PL.USERNAME LIKE ''%' || v_newusername || '%''');
  ELSE
  v_sqlquery := v_sqlquery || ' AND PL.USERNAME LIKE ''%' || v_username || '%'' ';
  END IF;
  END IF;
  END IF;
  IF (v_mobile <> '') THEN
  v_sqlquery := v_sqlquery || ' AND ISNULL(pl.phone,'''') LIKE ''%' || v_mobile || '%''';
  END IF;
  IF ((v_fromdate <> '') AND (v_todate = '')) THEN
  v_sqlquery := v_sqlquery || ' and CONVERT(date, TID.PuchaseDate, 105) between  CONVERT(date, ''' || v_fromdate || ''', 105) and  CONVERT(date, dbo.fun_getCurrentDate(), 105) ';
  END IF;
  IF ((v_fromdate = '') AND (v_todate <> '')) THEN
  v_sqlquery := v_sqlquery || ' and CONVERT(date, TID.PuchaseDate, 105) between  CONVERT(date, ''' || v_todate || ''', 105) and  CONVERT(date, dbo.fun_getCurrentDate(), 105) ';
  END IF;
  IF ((v_fromdate <> '') AND (v_todate <> '')) THEN
  v_sqlquery := v_sqlquery || ' and CONVERT(date, TID.PuchaseDate, 105) between CONVERT(date, ''' || v_fromdate || ''', 105) and  CONVERT(date, ''' || v_todate || ''', 105) ';
  END IF;
  v_sqlquery := v_sqlquery || ' order by TID.PuchaseDate desc';
  EXECUTE v_sqlquery;
  v_totalwithouttax := 0;
  v_totalservicetax := 0;
  v_totalamount := 0;
  SELECT COALESCE(SUM(with_out_tax_amount), 0), COALESCE(SUM(service_tax), 0), COALESCE(SUM(totalpayableamount), 0) INTO v_totalwithouttax, v_totalservicetax, v_totalamount FROM tmp_temp;
  IF (v_isdownload = 0) THEN
  RETURN QUERY SELECT *, v_totalwithouttax AS totalwithouttax, v_totalservicetax AS totalservicetax, v_totalamount AS totalamount FROM tmp_temp WHERE rownumber BETWEEN v_startrowindex AND v_maxrows;
  SELECT COUNT(*) INTO v_recordcount FROM tmp_temp;
  RETURN QUERY SELECT v_recordcount AS recordcount;
  ELSE
  RETURN QUERY SELECT rownumber AS "s.no.", fullname AS "customer name", username AS "user name", emailid AS "email id", puchasedate AS date, invoice_no AS "invoice no.", with_out_tax_amount AS "total amount", service_tax AS "service tax", totalpayableamount AS "payable amount" FROM tmp_temp;
  INSERT INTO tbl_exceltrackingreport (report_name, file_name, type, download_by, download_date) VALUES ('Sales Report', 'SalesReport_List.xls', 1, v_userid, CURRENT_TIMESTAMP);
  END IF;
  DROP TABLE IF EXISTS tmp_temp;
  -- SET option (removed)
END;
$$;


--
-- Name: usp_save_affiliate_bonus(character varying, numeric, integer, text, integer, character, integer, character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_save_affiliate_bonus(v_bonus_type character varying, v_bonus_value numeric, v_redeedays integer, v_sprids text, v_created_by integer, v_status character, v_out_result integer DEFAULT 0, v_out_message character varying DEFAULT ''::character varying) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
BEGIN
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp (SPRID INT,BONUS_TYPE VARCHAR(50),BONUS_VALUE DECIMAL(18,2),REDEEM_DAYS INT,IS_EXISTS boolean) ON COMMIT DROP;
  INSERT INTO tmp_temp (sprid, bonus_type, bonus_value, redeem_days) SELECT CAST(item AS INT), v_bonus_type, v_bonus_value, v_redeedays FROM dbo.SPLITSTRING(v_sprids, ',');
  RETURN QUERY SELECT * FROM tmp_temp AS t INNER JOIN affiliate_bonus_on_product AS ab ON ab.sprid = t.sprid;
  UPDATE t SET is_exists = 1 FROM tmp_temp AS t INNER JOIN affiliate_bonus_on_product AS ab ON ab.sprid = t.sprid;
  UPDATE ab SET bonus_type = t.bonus_type, bonus_value = t.bonus_value, updated_on = CURRENT_TIMESTAMP, updated_by = v_created_by, is_active = 1, redeem_after_days = t.redeem_days, status = v_status FROM affiliate_bonus_on_product AS ab INNER JOIN tmp_temp AS t ON t.sprid = ab.sprid;
  INSERT INTO affiliate_bonus_on_product (sprid, bonus_type, bonus_value, created_on, created_by, is_active, redeem_after_days, status) SELECT sprid, bonus_type, bonus_value, CURRENT_TIMESTAMP, v_created_by, 1, redeem_days, v_status FROM tmp_temp WHERE COALESCE(is_exists, 0) = 0;
  v_out_result := 1;
  v_out_message := 'Affiliate bonus Added Successfully';
END;
$$;


--
-- Name: usp_save_approve_reject_affiliate_request(integer, character, character varying, character varying, boolean, integer, character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_save_approve_reject_affiliate_request(v_abpid integer, v_status character, v_remark character varying, v_action character varying DEFAULT ''::character varying, INOUT v_out_status boolean DEFAULT NULL::boolean, INOUT v_out_result integer DEFAULT NULL::integer, INOUT v_out_message character varying DEFAULT NULL::character varying) RETURNS record
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF NOT EXISTS(SELECT 1 FROM affiliate_bonus_on_product WHERE abpid = v_abpid) THEN
  v_out_status := 0;
  v_out_result := 0;
  v_out_message := 'Invalid Request';
  RETURN;
  ELSE
  UPDATE affiliate_bonus_on_product SET status = v_status, remark = v_remark WHERE abpid = v_abpid;
  v_out_status := 1;
  v_out_result := 2;
  v_out_message := v_action || ' Successfully';
  RETURN;
  END IF;
END;
$$;


--
-- Name: usp_saveadview(bigint, bigint, character varying, boolean, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_saveadview(v_pmid bigint, v_account bigint DEFAULT 1, v_ipaddress character varying DEFAULT NULL::character varying, v_active boolean DEFAULT true, INOUT v_intresult integer DEFAULT 0) RETURNS integer
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_count int;
BEGIN
  SELECT COUNT(*) INTO v_count FROM adview WHERE pmid = v_pmid;
  IF (v_count = 0) THEN
  INSERT INTO adview (account, pmid) VALUES (v_account, v_pmid);
  INSERT INTO adview_ipaddress (pmid, ipaddress) VALUES (v_pmid, v_ipaddress);
  v_intresult := 1;
  RETURN;
  ELSE
  UPDATE adview SET account = account + 1 WHERE pmid = v_pmid;
  INSERT INTO adview_ipaddress (pmid, ipaddress) VALUES (v_pmid, v_ipaddress);
  v_intresult := 1;
  RETURN;
  END IF;
END;
$$;


--
-- Name: usp_saved_ad(integer, integer, integer, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_saved_ad(v_pmid integer DEFAULT 0, v_plid integer DEFAULT 0, v_dealsid integer DEFAULT 0, INOUT v_intresult integer DEFAULT NULL::integer) RETURNS integer
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_err INT;
  v_vmid INT;
BEGIN
  -- BEGIN TRAN (removed)
  v_vmid := 0;
  v_intresult := 0;
  IF EXISTS(SELECT said FROM saved_ad WHERE plid = v_plid AND pmid = v_pmid AND active = 1 AND dealsid = 0) THEN
  v_intresult := 2;
  ELSE
  IF EXISTS(SELECT said FROM saved_ad WHERE plid = v_plid AND pmid = 0 AND active = 1 AND dealsid = v_dealsid) THEN
  v_intresult := 2;
  ELSE
  INSERT INTO saved_ad (vmid, pmid, active, plid, dealsid) VALUES (0, v_pmid, 1, v_plid, v_dealsid);
  v_intresult := 1;
  END IF;
  END IF;
  IF (v_err <> 0) THEN
  v_intresult := 0;
  -- ROLLBACK (removed)
  RETURN;
  END IF;
  -- COMMIT (removed)
END;
$$;


--
-- Name: usp_search_suggestions(character varying, character varying, character varying, character varying, character varying, character varying, boolean, character varying, character varying, character varying, character varying, integer, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_search_suggestions(v_name character varying DEFAULT ''::character varying, v_mobile character varying DEFAULT ''::character varying, v_email character varying DEFAULT ''::character varying, v_search character varying DEFAULT ''::character varying, v_city character varying DEFAULT ''::character varying, v_area character varying DEFAULT ''::character varying, v_active boolean DEFAULT true, v_ipaddress character varying DEFAULT ''::character varying, v_ipcontry character varying DEFAULT ''::character varying, v_ipstate character varying DEFAULT ''::character varying, v_ipcity character varying DEFAULT ''::character varying, v_countryid integer DEFAULT 0, v_mode integer DEFAULT 1) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF (v_mode = 1) THEN
  INSERT INTO suggested_product (search, city, email, area, name, mobile, active, cid, ipaddress, ipcountry, ipstate, ipcity, suggestdate) VALUES (v_search, v_city, v_email, v_area, v_name, v_mobile, v_active, v_countryid, v_ipaddress, v_ipcontry, v_ipstate, v_ipcity, CURRENT_TIMESTAMP);
  END IF;
  IF (v_mode = 2) THEN
  RETURN QUERY SELECT spid, search, city, email, area, name, mobile, active, cid, ipaddress, ipcountry, ipstate, active, ipcity, suggestdate FROM suggested_product;
  END IF;
END;
$$;


--
-- Name: usp_searcharea(character varying, integer, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_searcharea(v_username character varying, v_ctid integer DEFAULT 0, v_cid integer DEFAULT 0) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF (v_ctid <> 0 AND v_cid <> 0) THEN
  RETURN QUERY SELECT DISTINCT areaname AS username FROM portal_master WHERE cid = v_cid AND ctid = v_ctid AND areaname LIKE '%' || v_username || '%';
  ELSE
  IF (v_ctid <> 0 AND v_cid = 0) THEN
  RETURN QUERY SELECT DISTINCT areaname AS username FROM portal_master WHERE ctid = v_ctid AND areaname LIKE '%' || v_username || '%';
  ELSE
  IF (v_ctid = 0 AND v_cid <> 0) THEN
  RETURN QUERY SELECT DISTINCT areaname AS username FROM portal_master WHERE cid = v_cid AND areaname LIKE '%' || v_username || '%';
  ELSE
  RETURN QUERY SELECT DISTINCT areaname AS username FROM portal_master WHERE areaname LIKE '%' || v_username || '%';
  END IF;
  END IF;
  END IF;
END;
$$;


--
-- Name: usp_searchareaforlisting(character varying, integer, integer, integer, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_searchareaforlisting(v_keyupvalue character varying DEFAULT 'Bo'::character varying, v_ctid integer DEFAULT 0, v_sid integer DEFAULT 0, v_cid integer DEFAULT 91, v_mode integer DEFAULT 1) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_query text;
BEGIN
  IF (v_mode = 0) THEN
  IF (v_ctid <> 0 AND v_cid <> 0) THEN
  v_query := 'SELECT DISTINCT TOP 25 AREANAME AS USERNAME FROM AREA_MASTER WHERE CID=' || CAST(v_cid AS VARCHAR(100)) || ' AND CTID=' || CAST(v_ctid AS VARCHAR(100)) || ' 
	AND AREANAME LIKE''' || v_keyupvalue || '%''' || 'ORDER BY AREANAME';
  EXECUTE v_query;
  ELSE
  IF (v_ctid <> 0 AND v_cid = 0) THEN
  v_query := 'SELECT DISTINCT TOP 25 AREANAME AS USERNAME FROM AREA_MASTER WHERE CTID=' || CAST(v_ctid AS VARCHAR(100)) || ' AND AREANAME LIKE''' || v_keyupvalue || '%''' || 'ORDER BY AREANAME';
  EXECUTE v_query;
  ELSE
  IF (v_ctid = 0 AND v_cid <> 0) THEN
  v_query := 'SELECT DISTINCT TOP 25 AREANAME AS USERNAME FROM AREA_MASTER WHERE CID=' || CAST(v_cid AS VARCHAR(100)) || ' AND AREANAME LIKE''' || v_keyupvalue || '%''' || 'ORDER BY AREANAME';
  EXECUTE v_query;
  ELSE
  v_query := 'SELECT DISTINCT TOP 25 AREANAME AS USERNAME FROM AREA_MASTER WHERE AREANAME LIKE ''' || v_keyupvalue || '%''' || 'ORDER BY AREANAME';
  EXECUTE v_query;
  END IF;
  END IF;
  END IF;
  ELSE
  IF (v_cid <> 0) THEN
  v_query := ' SELECT DISTINCT TOP 25 CITYNAME AS USERNAME FROM CITY WHERE CID= ' || CAST(v_cid AS VARCHAR(100)) || ' 
	AND ACTIVE=1 AND CITYNAME LIKE ''' || v_keyupvalue || '%''' || 'ORDER BY CITYNAME';
  EXECUTE v_query;
  ELSE
  RETURN QUERY SELECT DISTINCT cityname AS username FROM city WHERE active = 1 ORDER BY cityname NULLS FIRST LIMIT 25;
  END IF;
  END IF;
END;
$$;


--
-- Name: usp_searchareaforselectedcities(character varying, character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_searchareaforselectedcities(v_username character varying, v_ctid character varying) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_query text;
BEGIN
  v_query := 'select distinct areaname as UserName from area_master where ctid in (' || CAST(v_ctid AS VARCHAR(100)) || ') and areaname like''' || v_username || '%''' || 'order by areaname';
  EXECUTE v_query;
END;
$$;


--
-- Name: usp_searchcategory(character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_searchcategory(v_username character varying) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
BEGIN
  RETURN QUERY SELECT catname, catid FROM product_category WHERE catname LIKE LTRIM(RTRIM(v_username)) || '%';
END;
$$;


--
-- Name: usp_searchcity(character varying, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_searchcity(v_username character varying, v_country integer DEFAULT 0) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF v_country = 0 THEN
  RETURN QUERY SELECT cityname, ctid FROM city WHERE cityname LIKE LTRIM(RTRIM(v_username)) || '%';
  ELSE
  RETURN QUERY SELECT cityname, ctid FROM city WHERE cityname LIKE LTRIM(RTRIM(v_username)) || '%' AND cid = v_country;
  END IF;
END;
$$;


--
