CREATE FUNCTION dbo.usp_searchdistributor(v_serchitem character varying) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_count int;
BEGIN
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp (fomatedResult text,
searchResult text,
forurl text,
searchtype varchar(200)) ON COMMIT DROP;
  INSERT INTO tmp_temp SELECT pmm.username, pmm.username, pmm.did, 'Name' FROM tbl_distributor AS pmm WHERE ' ' || pmm.username LIKE '%' || v_serchitem || '%';
