--
-- Name: usp_searching_pincodeor_area(character varying, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_searching_pincodeor_area(v_keyupvalue character varying DEFAULT ''::character varying, v_cid integer DEFAULT 0) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_query text;
BEGIN
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp (USERNAME text) ON COMMIT DROP;
  IF EXISTS(SELECT 1 FROM area_master WHERE cid = v_cid AND pincode LIKE '' || v_keyupvalue || '%') THEN
  INSERT INTO tmp_temp SELECT ((am.pincode || ',' || am.areaname || ',' || ct.cityname || ',' || st.statename)) FROM area_master AS am INNER JOIN city AS ct ON am.ctid = ct.ctid INNER JOIN state AS st ON st.sid = ct.sid AND am.pincode LIKE '' || v_keyupvalue || '%' AND am.cid = v_cid ORDER BY am.areaname NULLS FIRST LIMIT 20;
  END IF;
  IF EXISTS(SELECT 1 FROM area_master WHERE cid = v_cid AND areaname LIKE '' || v_keyupvalue || '%') THEN
  INSERT INTO tmp_temp SELECT ((CASE COALESCE(am.pincode, '') WHEN '' THEN '' ELSE am.pincode || ',' END) + am.areaname || ',' || ct.cityname || ',' || st.statename) FROM area_master AS am INNER JOIN city AS ct ON am.ctid = ct.ctid INNER JOIN state AS st ON st.sid = ct.sid AND am.areaname LIKE '' || v_keyupvalue || '%' AND am.cid = v_cid ORDER BY am.areaname ASC NULLS FIRST LIMIT 20;
  END IF;
  RETURN QUERY SELECT * FROM tmp_temp;
  DROP TABLE IF EXISTS tmp_temp;
END;
$$;


