  IF EXISTS(SELECT aid FROM area_master WHERE LTRIM(RTRIM(areaname)) = v_areaname AND ctid = v_ctid) THEN
  SELECT aid INTO v_aid FROM area_master WHERE LTRIM(RTRIM(areaname)) = v_areaname AND ctid = v_ctid;
  INSERT INTO tbl_searchlog (keywordid, pmid, cid, sid, ctid, aid, catid, active, searchaccounttype, searchdate, ipaddress, ipcountryname, ipstatename, ipcityname) VALUES (0, 0, v_cid, v_sid, v_ctid, v_aid, v_searchid, 1, 0, CURRENT_TIMESTAMP, v_ipaddress, v_ipcountryname, v_ipstatename, v_ipcityname);
  END IF;
  ELSE
  IF (v_ctid <> 0 AND v_areaname = '') THEN
  INSERT INTO tbl_searchlog (keywordid, pmid, cid, sid, ctid, aid, catid, active, searchaccounttype, searchdate, ipaddress, ipcountryname, ipstatename, ipcityname) VALUES (0, 0, v_cid, v_sid, v_ctid, 0, v_searchid, 1, 0, CURRENT_TIMESTAMP, v_ipaddress, v_ipcountryname, v_ipstatename, v_ipcityname);
  ELSE
  IF (v_ctid = 0 AND v_areaname = '') THEN
  INSERT INTO tbl_searchlog (keywordid, pmid, cid, sid, ctid, aid, catid, active, searchaccounttype, searchdate, ipaddress, ipcountryname, ipstatename, ipcityname) VALUES (0, 0, v_cid, v_sid, 0, 0, v_searchid, 1, 0, CURRENT_TIMESTAMP, v_ipaddress, v_ipcountryname, v_ipstatename, v_ipcityname);
  END IF;
  END IF;
