--
-- Name: usp_searchnotfoundlogselect(integer, integer, character varying, character varying, character varying, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_searchnotfoundlogselect(v_startrowindex integer, v_maxrows integer, v_country character varying, v_fromdate character varying, v_todate character varying, v_recordcount integer) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_sqlquery text;
BEGIN
  -- SET option (removed)
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp (rowNumber bigint,
snflid bigint,
countrys varchar(150),
city varchar(100),
ipaddres varchar(150),
dates varchar(50),
searchitem varchar(300),
category varchar(200),
keyword varchar(200)) ON COMMIT DROP;
  v_sqlquery := '';
  v_sqlquery := 'insert into #temp select ROW_NUMBER() over(order by snfl.snfid) as rownumber,snfl.snfid,
 case cn.countryName when ''UNITED STATES'' then ''U S'' when ''UNITED KINGDOM'' then ''U K''  when ''South Africa'' then ''S A'' else cn.countryName end as countryName, ct.cityName,
 snfl.ipaddress,cast (snfl.searchdate as date) as date,snfl.searchitem,pc.CatName,km.keywordname  from COUNTRY cn inner join 
 tbl_searchnotfoundlog snfl on snfl.cid=cn.CID inner join CITY ct on ct.CID=snfl.cid
inner join Product_Category pc on pc.catId=snfl.catid inner join keyword_master km on km.kmid=snfl.keyid ';
  IF (v_country <> '') THEN
  v_sqlquery := v_sqlquery || (' and cn.cid =' || v_country || ' ');
  END IF;
  IF (v_fromdate = '' OR v_todate = '') THEN
  IF (v_fromdate <> '') THEN
  v_sqlquery := v_sqlquery || ' and convert(date,snfl.searchdate,105) = replace(convert(date,''' || v_fromdate || ''',105),''/'',''-'') ';
  END IF;
  IF (v_todate <> '') THEN
  v_sqlquery := v_sqlquery || ' and convert(date,snfl.searchdate,105)  =replace(convert(date,''' || v_todate || ''',105),''/'',''-'') ';
  END IF;
  END IF;
  IF (v_fromdate <> '' AND v_todate <> '') THEN
  v_sqlquery := v_sqlquery || ' and  convert(date,snfl.searchdate,105)  between  replace(convert(date,''' || v_fromdate || ''',105),''/'',''-'')  and replace(convert(date,''' || v_todate || ''',105),''/'',''-'')';
  END IF;
  RETURN QUERY SELECT v_sqlquery;
  -- SET option (removed)
END;
$$;


--
-- Name: usp_searchorderno(character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_searchorderno(v_serchitem character varying DEFAULT ''::character varying) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_count int;
BEGIN
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp (fomatedResult text,
searchResult text,
forurl text,
searchtype varchar(200)) ON COMMIT DROP;
  IF EXISTS(SELECT 1 FROM tbl_product_order_master WHERE orderid LIKE '%' || v_serchitem || '%') THEN
  INSERT INTO tmp_temp SELECT pmm.orderid, pmm.orderid, pmm.poid, 'Name' FROM tbl_product_order_master AS pmm WHERE pmm.orderid LIKE '%' || v_serchitem || '%';
  RETURN QUERY SELECT DISTINCT searchresult, fomatedresult, forurl, searchtype AS serachtext FROM tmp_temp LIMIT 1;
  ELSE
  INSERT INTO tmp_temp SELECT pmm.orderno, pmm.orderno, pmm.poid, 'Name' FROM tbl_product_order_master AS pmm WHERE pmm.orderno LIKE '%' || v_serchitem || '%';
  RETURN QUERY SELECT DISTINCT searchresult, fomatedresult, forurl, searchtype AS serachtext FROM tmp_temp LIMIT 1;
  END IF;
  DROP TABLE IF EXISTS tmp_temp;
END;
$$;


