CREATE FUNCTION dbo.usp_searchportal(v_scatid integer DEFAULT 0, v_bmid integer DEFAULT 0, v_mid integer DEFAULT 0, v_bodystle character varying DEFAULT ''::character varying, v_transmission character varying DEFAULT ''::character varying, v_year character varying DEFAULT ''::character varying, v_milage character varying DEFAULT ''::character varying, v_minprice text DEFAULT ''::text, v_maxprice text DEFAULT ''::text, v_fueltype character varying DEFAULT ''::character varying, v_sellertype character varying DEFAULT ''::character varying, v_condition character varying DEFAULT ''::character varying, v_adtype character varying DEFAULT ''::character varying, v_minenginesize integer DEFAULT 0, v_maxenginesize integer DEFAULT 0, v_color character varying DEFAULT ''::character varying, v_sortby integer DEFAULT 0, v_ctid integer DEFAULT 0) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_strquery varchar(800);
  v_brandname varchar(100);
  v_paramdefinition varchar(2000);
  v_sqloutput text;
  v_slice1 text;
