  v_strquery := 'select pm.photo,pm.pmid,sm.sellertype,pm.packagetype,pm.AddPDate,pm.CertifiedStatus,pm.CertifiedImage,pm.price,pm.title,pm.brandname,pm.model,pm.FuelType,pm.year,



 pm.kmdriven,pm.Color,pm.description,' || '''1''' || 'from portal_master pm, seller_master sm where pm.pmid=sm.pmid and pm.active=1 and pm.packagetype=2 ';
  ELSE
  v_strquery := 'select pm.photo,pm.pmid,sm.sellertype,pm.packagetype,pm.AddPDate,pm.CertifiedStatus,pm.CertifiedImage,pm.price,pm.title,pm.brandname,pm.model,pm.FuelType,pm.year,



   pm.kmdriven,pm.Color,pm.description,' || '''1''' || 'from portal_master pm, seller_master sm where pm.pmid=sm.pmid and pm.active=1';
  END IF;
  IF (v_ctid <> 0) THEN
  v_strquery := v_strquery || ' and pm.ctid=' || CAST(v_ctid AS VARCHAR(100));
  END IF;
  IF (v_scatid <> 0) THEN
  v_strquery := v_strquery || ' and pm.scatid=' || CAST(v_scatid AS VARCHAR(100));
  END IF;
  IF (v_bmid <> 0) THEN
  v_strquery := v_strquery || ' and pm.brandid=' || CAST(v_bmid AS VARCHAR(100));
