  END IF;
  IF (v_fueltype <> '') THEN
  v_strquery := v_strquery || ' and pm.FuelType iN (' || v_fueltype || ')';
  END IF;
  IF (v_condition <> '') THEN
  v_strquery := v_strquery || ' and pm.condition iN (' || v_condition || ')';
  END IF;
  IF (v_adtype <> '') THEN
  v_strquery := v_strquery || ' and pm.AdType iN (' || v_adtype || ')';
  END IF;
  IF (v_sellertype <> '') THEN
  v_strquery := v_strquery || ' and sm.sellertype iN (' || v_sellertype || ')';
  END IF;
  IF (v_minenginesize <> 0) THEN
  v_strquery := v_strquery || ' and pm.EngineSize>=' || CAST(v_minenginesize AS VARCHAR(100));
  END IF;
  IF (v_maxenginesize <> 0) THEN
  v_strquery := v_strquery || ' and pm.EngineSize<=' || CAST(v_maxenginesize AS VARCHAR(100));
  END IF;
  IF (v_color <> '') THEN
  v_strquery := v_strquery || ' and pm.Color=''' || v_color || '''';
  END IF;
  IF (v_sortby <> 0) THEN
  IF (v_sortby = 1) THEN
  v_strquery := v_strquery || ' union all select pm.photo,pm.pmid,sm.sellertype,pm.packagetype,pm.AddPDate,pm.CertifiedStatus,pm.CertifiedImage,pm.price,pm.title,pm.brandname,



			pm.model,pm.FuelType,pm.year,pm.kmdriven,pm.Color,pm.description,  ROW_NUMBER() OVER (ORDER BY pm.AddPDate desc) as' || '''1''' || ' from portal_master pm, seller_master sm 



			where pm.pmid=sm.pmid and pm.active=1  and pm.packagetype!=2';
  END IF;
  IF (v_sortby = 2) THEN
  v_strquery := v_strquery || ' union all select pm.photo,pm.pmid,sm.sellertype,pm.packagetype,pm.AddPDate,pm.CertifiedStatus,pm.CertifiedImage,pm.price,pm.title,pm.brandname,



			pm.model,pm.FuelType,pm.year,pm.kmdriven,pm.Color,pm.description,  ROW_NUMBER() OVER (ORDER BY pm.price ) as ' || '''1''' || ' from portal_master pm, seller_master sm where 



			pm.pmid=sm.pmid and pm.active=1  and pm.packagetype!=2';
  END IF;
  IF (v_sortby = 3) THEN
  v_strquery := v_strquery || ' union all select pm.photo,pm.pmid,sm.sellertype,pm.packagetype,pm.AddPDate,pm.CertifiedStatus,pm.CertifiedImage,pm.price,pm.title,pm.brandname,



			pm.model,pm.FuelType,pm.year,pm.kmdriven,pm.Color,pm.description,  ROW_NUMBER() OVER (ORDER BY pm.price desc) as ' || '''1''' || ' from portal_master pm, seller_master sm where pm.pmid=sm.pmid and pm.active=1  and pm.packagetype!=2';
  END IF;
  IF (v_sortby = 4) THEN
  v_strquery := v_strquery || ' union all select pm.photo,pm.pmid,sm.sellertype,pm.packagetype,pm.AddPDate,pm.CertifiedStatus,pm.CertifiedImage,pm.price,pm.title,pm.brandname,



			pm.model,pm.FuelType,pm.year,pm.kmdriven,pm.Color,pm.description,  ROW_NUMBER() OVER (ORDER BY pm.kmdriven ) as ' || '''1''' || ' from portal_master pm, seller_master sm 



			where pm.pmid=sm.pmid and pm.active=1  and pm.packagetype!=2';
