  END IF;
  IF (v_mid <> 0) THEN
  v_strquery := v_strquery || ' and pm.modalid=' || CAST(v_mid AS VARCHAR(100));
  END IF;
  IF (v_bodystle <> '') THEN
  v_strquery := v_strquery || ' and pm.bodystyle=''' || v_bodystle || '''';
  END IF;
  IF (v_transmission <> '') THEN
  v_strquery := v_strquery || ' and pm.transmission=''' || v_transmission || '''';
  END IF;
  IF (v_year <> '') THEN
  v_strquery := v_strquery || ' and pm.year=''' || v_year || '''';
  END IF;
  IF (v_milage <> '') THEN
  v_strquery := v_strquery || ' and pm.kmdriven<=''' || v_milage || '''';
  END IF;
  IF (v_sellertype <> '') THEN
  v_strquery := v_strquery || ' and sm.sellertype iN (' || v_sellertype || ')';
  END IF;
  IF (v_fueltype <> '') THEN
  v_strquery := v_strquery || ' and pm.FuelType iN (' || v_fueltype || ')';
  END IF;
  IF (v_condition <> '') THEN
  v_strquery := v_strquery || ' and pm.condition iN (' || v_condition || ')';
  END IF;
  IF (v_adtype <> '') THEN
  v_strquery := v_strquery || ' and pm.AdType iN (' || v_adtype || ')';
  END IF;
  IF (v_minenginesize <> 0) THEN
  v_strquery := v_strquery || ' and pm.EngineSize>=' || CAST(v_minenginesize AS VARCHAR(100));
  END IF;
  IF (v_maxenginesize <> 0) THEN
  v_strquery := v_strquery || ' and pm.EngineSize<=' || CAST(v_maxenginesize AS VARCHAR(100));
  END IF;
  IF (v_color <> '') THEN
  v_strquery := v_strquery || ' and pm.Color=''' || v_color || '''';
  END IF;
  ELSE
  v_strquery := v_strquery || ' order by pm.packagetype desc, pm.accountype ,pm.title';
  END IF;
  IF (v_minprice <> '' AND v_maxprice <> '') THEN
  DROP TABLE IF EXISTS tmp_temp12;
  CREATE TEMP TABLE tmp_temp12 (photo text,



		   pmid bigint,



		   sellertype int,



		   packagetype int,



		   AddPDate date,



		   CertifiedStatus int,



		   CertifiedImage text,



		   price numeric(19,4),



		   title  text,



		   brandname text,



		   model text,



		   FuelType text,



		   year text,



		   kmdriven text,



		   Color text,



		   description text,



		   NoColumnName varchar(10)) ON COMMIT DROP;
  DROP TABLE IF EXISTS tmp_temp13;
  CREATE TEMP TABLE tmp_temp13 (photo text,



		   pmid bigint,



		   sellertype int,



		   packagetype int,



		   AddPDate date,



		   CertifiedStatus int,



		   CertifiedImage text,



		   price numeric(19,4),



		   title  text,



		   brandname text,



		   model text,



		   FuelType text,



		   year text,



		   kmdriven text,



		   Color text,



		   description text,



		   NoColumnName varchar(10)) ON COMMIT DROP;
  v_strquery := 'insert into #temp12 ' || v_strquery;
  EXECUTE v_strquery;
  v_slice1 := v_minprice;
  v_slice3 := v_maxprice;
  v_index1 := 1;
  v_index2 := 1;
  WHILE v_index1 <> 0 AND v_index2 <> 0 LOOP
  SELECT POSITION(',' IN v_slice1) INTO v_index1;
  SELECT POSITION(',' IN v_slice3) INTO v_index2;
  IF v_index1 <> 0 AND v_index2 <> 0 THEN
  SELECT LEFT(CAST(v_slice1 AS TEXT), v_index1 - 1) INTO v_slice2;
  SELECT LEFT(CAST(v_slice3 AS TEXT), v_index2 - 1) INTO v_slice4;
  ELSE
  SELECT v_slice1 INTO v_slice2;
  SELECT v_slice3 INTO v_slice4;
  END IF;
  v_query := 'insert  into #temp13' || ' select * from #temp12 where price>=' || v_slice2 || '  and price<=' || v_slice4 || '';
  EXECUTE v_query;
  IF (0 <> 0) THEN
  -- ROLLBACK (removed)
  RETURN;
  END IF;
  SELECT RIGHT(CAST(v_slice1 AS TEXT), LENGTH(CAST(v_slice1 AS TEXT)) - v_index1) INTO v_slice1;
  SELECT RIGHT(CAST(v_slice3 AS TEXT), LENGTH(CAST(v_slice3 AS TEXT)) - v_index2) INTO v_slice3;
  IF LENGTH(CAST(v_slice1 AS TEXT)) = 0 AND LENGTH(CAST(v_slice3 AS TEXT)) = 0 THEN
  EXIT;
  END IF;
  -- SET option (removed)
  END LOOP;
  RETURN QUERY SELECT * FROM tmp_temp13;
  DROP TABLE IF EXISTS tmp_temp13;
  DROP TABLE IF EXISTS tmp_temp12;
  ELSE
  EXECUTE v_strquery;
  END IF;
  -- SET option (removed)
END;
$$;


