--
-- Name: usp_searchresult_dealsck(character varying, integer, character varying, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_searchresult_dealsck(v_username character varying, v_ctid integer DEFAULT 0, v_aid character varying DEFAULT NULL::character varying, v_cid integer DEFAULT 0) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
BEGIN
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp (UserName varchar(500),
		searchtype varchar(10),
		charcount int,
		dealid bigint,
		pmid bigint) ON COMMIT DROP;
  INSERT INTO tmp_temp SELECT catname AS username, '3' AS searchtype, dbo.fun_findcount(catname) AS charcount, 0, 0 FROM product_category WHERE catactive = 1 AND ' ' || catname LIKE '% ' || v_username || '%' ORDER BY searchtype DESC NULLS LAST LIMIT 5;
  INSERT INTO tmp_temp SELECT keywordname AS username, '2' AS searchtype, dbo.fun_findcount(keywordname) AS charcount, 0, 0 FROM keyword_master WHERE kactive = 1 AND ' ' || keywordname LIKE '% ' || v_username || '%' ORDER BY searchtype DESC NULLS LAST LIMIT 5;
  INSERT INTO tmp_temp SELECT pdm.title AS username, '1' AS searchtype, dbo.fun_findcount(pdm.title) AS charcount, pdm.dealid, pdm.pmid FROM portal_deal_master AS pdm INNER JOIN portal_master AS pm ON pm.pmid = pdm.pmid WHERE pdm.active = 1 AND pdm.verify = 1 AND ' ' || pdm.title LIKE '% ' || v_username || '%' AND pm.cid = v_cid ORDER BY searchtype DESC NULLS LAST LIMIT 10;
  DROP TABLE IF EXISTS tmp_temp7;
  CREATE TEMP TABLE tmp_temp7 ON COMMIT DROP AS SELECT username, searchtype, charcount, dealid, pmid FROM tmp_temp;
  RETURN QUERY SELECT username, searchtype, charcount, (dbo.findarea_city_on_pmid(pmid)) AS areaname, dbo.findtotalreating(dealid) AS totalreview, dealid FROM tmp_temp7 ORDER BY charcount ASC NULLS FIRST;
  DROP TABLE IF EXISTS tmp_temp7;
  DROP TABLE IF EXISTS tmp_temp;
END;
$$;


--
-- Name: usp_searchresult_m(character varying, integer, character varying, integer, text); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_searchresult_m(v_inputsearchtext character varying DEFAULT 'LIKE media'::character varying, v_ctid integer DEFAULT 0, v_aid character varying DEFAULT ''::character varying, v_cid integer DEFAULT 96, v_searchtype text DEFAULT '4'::text) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
BEGIN
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp (SEARCHRESULT VARCHAR(500),    
FORMATEDRESULT VARCHAR(300),    
AREANNAME VARCHAR(200),    
PMID BIGINT,    
DealsUrl text) ON COMMIT DROP;
  IF (v_searchtype = '3') THEN
  INSERT INTO tmp_temp SELECT catname, catname, '<b><span class=''cssPlusText'' style=''color:red''> [++] </span></b>', 0, '' FROM product_category WHERE catactive = 1 AND ' ' || catname LIKE '% ' || v_inputsearchtext || '%' AND categoryrelatedto = 2 LIMIT 8;
  INSERT INTO tmp_temp SELECT companyname AS catname, companyname, '', 0, '' FROM portal_master WHERE active = 1 AND COALESCE(isverified, 0) = 1 AND ' ' || companyname LIKE '% ' || v_inputsearchtext || '%' AND storetypeid = 2 LIMIT 8;
  ELSE
  IF (v_searchtype = '4') THEN
  INSERT INTO tmp_temp SELECT catname, catname, '<b><span class=''cssPlusText'' style=''color:red''> [++] </span></b>', 0, '' FROM product_category WHERE catactive = 1 AND ' ' || catname LIKE '% ' || v_inputsearchtext || '%' AND categoryrelatedto = 1 LIMIT 8;
  INSERT INTO tmp_temp SELECT companyname AS catname, companyname, '', 0, '' FROM portal_master WHERE active = 1 AND COALESCE(isverified, 0) = 1 AND ' ' || companyname LIKE '% ' || v_inputsearchtext || '%' AND storetypeid = 1 LIMIT 8;
  ELSE
  INSERT INTO tmp_temp SELECT catname, catname, '<b><span class=''cssPlusText'' style=''color:red''> [++] </span></b>', 0, '' FROM product_category WHERE catactive = 1 AND ' ' || catname LIKE '% ' || v_inputsearchtext || '%' LIMIT 8;
  INSERT INTO tmp_temp SELECT keywordname, keywordname, '<b><span class=''cssPlusText'' style=''color:red''> [+] </span></b>', 0, '' FROM keyword_master WHERE kactive = 1 AND ' ' || keywordname LIKE '% ' || v_inputsearchtext || '%' LIMIT 8;
  END IF;
  END IF;
  IF (v_searchtype = '1') THEN
  INSERT INTO tmp_temp SELECT companyname, companyname, '<span class=''cssArea''>[' || (dbo.FINDAREA_CITY_ON_PMID(pmid)) || ']</span>', pmid, '' FROM portal_master WHERE active = 1 AND isverified = 1 AND ' ' || title LIKE '% ' || v_inputsearchtext || '%' AND cid = v_cid LIMIT 8;
  END IF;
  IF (v_searchtype = '2') THEN
  INSERT INTO tmp_temp SELECT pdm.title, pdm.title, '<span class=''cssArea''>[' || (dbo.FINDAREA_CITY_ON_PMID(pdm.pmid)) || ']</span>', dealid, REPLACE(REPLACE(dbo.GENRATINGDEALLISTINGSURL(pdm.dealid), '/', '/'), '''', '+opos') FROM portal_master AS pm INNER JOIN portal_deal_master AS pdm ON pdm.pmid = pm.pmid WHERE verify = 1 AND pdm.active = 1 AND CAST(CURRENT_TIMESTAMP AS DATE) BETWEEN fromtime AND totime AND images <> '' AND COALESCE(startprice, 0) > 0 AND pm.active = 1 AND isverified = 1 AND ' ' || pdm.title LIKE '% ' || v_inputsearchtext || '%' AND cid = v_cid LIMIT 8;
  END IF;
  RETURN QUERY SELECT REPLACE(searchresult, '&', '-and-') AS searchresult, '<dt>' || REPLACE(REPLACE(formatedresult, v_inputsearchtext, '<b><span class=''cssHighLightedSearch''>' || v_inputsearchtext || '</span></b>') || areanname, '&', '-and-') || '</dt>' AS fomateddata, pmid FROM tmp_temp ORDER BY dbo.FUN_FINDCOUNT(searchresult) ASC NULLS FIRST;
END;
$$;


--
-- Name: usp_searchresult_new(character varying, integer, character varying, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_searchresult_new(v_inputsearchtext character varying, v_ctid integer DEFAULT 0, v_aid character varying DEFAULT NULL::character varying, v_cid integer DEFAULT 0) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
BEGIN
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp (USERNAME VARCHAR(500),
			SEARCHTYPE VARCHAR(10),
			CHARCOUNT INT,
			PMID BIGINT) ON COMMIT DROP;
  INSERT INTO tmp_temp SELECT catname AS username, '3' AS searchtype, dbo.FUN_FINDCOUNT(catname) AS charcount, 0 FROM product_category WHERE catactive = 1 AND ' ' || catname LIKE '% ' || v_inputsearchtext || '%' ORDER BY searchtype DESC NULLS LAST LIMIT 5;
  INSERT INTO tmp_temp SELECT keywordname AS username, '2' AS searchtype, dbo.FUN_FINDCOUNT(keywordname) AS charcount, 0 FROM keyword_master WHERE kactive = 1 AND ' ' || keywordname LIKE '% ' || v_inputsearchtext || '%' ORDER BY searchtype DESC NULLS LAST LIMIT 5;
  INSERT INTO tmp_temp SELECT companyname AS username, '1' AS searchtype, dbo.FUN_FINDCOUNT(companyname) AS charcount, pmid FROM portal_master WHERE active = 1 AND isverified = 1 AND ' ' || title LIKE '% ' || v_inputsearchtext || '%' AND cid = v_cid ORDER BY searchtype DESC NULLS LAST LIMIT 10;
  DROP TABLE IF EXISTS tmp_temp7;
  CREATE TEMP TABLE tmp_temp7 ON COMMIT DROP AS SELECT username, searchtype, charcount, pmid FROM tmp_temp;
  RETURN QUERY SELECT username, searchtype, charcount, (dbo.FINDAREA_CITY_ON_PMID(pmid)) AS areaname, dbo.FINDTOTALREATING(pmid) AS totalreview, pmid FROM tmp_temp7 ORDER BY charcount ASC NULLS FIRST;
END;
$$;


--
-- Name: usp_searchresultdeal_m(character varying, integer, character varying, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_searchresultdeal_m(v_inputsearchtext character varying, v_ctid integer DEFAULT 0, v_aid character varying DEFAULT NULL::character varying, v_cid integer DEFAULT 0) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
BEGIN
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp (searchResult varchar(500),
			formatedResult varchar(300),
			areanName varchar(200),
			dealid bigint) ON COMMIT DROP;
  INSERT INTO tmp_temp SELECT catname, catname, '<span class=cssPlusText> [++] </span>', 0 FROM product_category WHERE catactive = 1 AND ' ' || catname LIKE '% ' || v_inputsearchtext || '%' LIMIT 8;
  INSERT INTO tmp_temp SELECT keywordname, keywordname, '<span class=cssPlusText> [+] </span>', 0 FROM keyword_master WHERE kactive = 1 AND ' ' || keywordname LIKE '% ' || v_inputsearchtext || '%' LIMIT 8;
  INSERT INTO tmp_temp SELECT pdm.title, pdm.title, ' ' || '<span class=cssArea>[' || (dbo.findarea_city_on_pmid(pm.pmid)) || ']</span>', pdm.dealid FROM portal_master AS pm INNER JOIN portal_deal_master AS pdm ON pm.pmid = pdm.pmid WHERE pm.active = 1 AND pm.isverified = 1 AND pdm.active = 1 AND pdm.verify = 1 AND ' ' || pdm.title LIKE '% ' || v_inputsearchtext || '%' AND pm.cid = v_cid LIMIT 8;
  RETURN QUERY SELECT searchresult, REPLACE(formatedresult, v_inputsearchtext, '<span class=cssHighLightedSearch>' || v_inputsearchtext || '</span>') || areanname AS fomateddata, dealid FROM tmp_temp ORDER BY dbo.fun_findcount(searchresult) ASC NULLS FIRST;
END;
$$;


--
-- Name: usp_searchsentemailhistory(integer, integer, integer, character varying, character varying, character varying, character varying, integer, integer, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_searchsentemailhistory(v_mode integer DEFAULT 1, v_startrowindex integer DEFAULT 1, v_maxrows integer DEFAULT 100, v_fromdate character varying DEFAULT ''::character varying, v_todate character varying DEFAULT ''::character varying, v_fromemail character varying DEFAULT ''::character varying, v_toemail character varying DEFAULT ''::character varying, v_isactive integer DEFAULT 0, v_isdeleted integer DEFAULT 0, v_intresult integer DEFAULT 0) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_sqlquery text;
  v_recordcount BIGINT;
BEGIN
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp (ROWNUMBER BIGINT GENERATED BY DEFAULT AS IDENTITY,

SMID BIGINT,

FROMEMAIL VARCHAR(100),

TOEMAIL VARCHAR(100),

SENTDATE VARCHAR(50),

SUBJECT text,

BODY text,

ISACTIVE INT) ON COMMIT DROP;
  v_sqlquery := '';
  IF (v_fromdate = '' OR v_todate = '') THEN
  IF (v_fromdate = '' AND v_todate <> '') THEN
  v_sqlquery := v_sqlquery || (' INSERT INTO #TEMP SELECT SMID,FROMEMAIL,TOEMAIL,CONVERT(DATE,SENDDATE,106) AS SENTDATE,SUBJECT,BODY,ISACTIVE

	          FROM [TBL_ADMINSENTMAILHISTORY] WHERE (CONVERT(DATE,SENDDATE,106) <= CONVERT(DATE,@TODATE,106)) ');
  ELSE
  IF (v_fromdate <> '' AND v_todate = '') THEN
  v_sqlquery := v_sqlquery || ('   INSERT INTO #TEMP SELECT SMID,FROMEMAIL,TOEMAIL,CONVERT(DATE,SENDDATE,106) AS SENTDATE,SUBJECT,BODY,ISACTIVE

	          FROM [TBL_ADMINSENTMAILHISTORY] WHERE (CONVERT(DATE,SENDDATE,106) >= CONVERT(DATE,@TODATE,106)) AND (ISNULL(SENDDATE,'')<>'') ');
  ELSE
  v_sqlquery := v_sqlquery || (' INSERT INTO #TEMP SELECT SMID,FROMEMAIL,TOEMAIL,CONVERT(DATE,SENDDATE,106) AS SENTDATE,SUBJECT,BODY,ISACTIVE

	          FROM [TBL_ADMINSENTMAILHISTORY] WHERE ISDELETED=0 ');
  END IF;
  END IF;
  ELSE
  v_sqlquery := v_sqlquery || (' INSERT INTO #TEMP SELECT SMID,FROMEMAIL,TOEMAIL,CONVERT(DATE,SENDDATE,106) AS SENTDATE,SUBJECT,BODY,ISACTIVE

        FROM [TBL_ADMINSENTMAILHISTORY] WHERE (CONVERT(DATE,SENDDATE,106)

	   BETWEEN CONVERT(DATE,@FROMDATE,106) AND CONVERT(DATE,@TODATE,106)) AND (ISNULL(SENDDATE,'')<>'') ');
  END IF;
  IF (v_fromemail <> '') THEN
  v_sqlquery := v_sqlquery || (' AND TBL_ADMINSENTMAILHISTORY.FROMEMAIL LIKE ''%' || v_fromemail || '%''');
  END IF;
  IF (v_toemail <> '') THEN
  v_sqlquery := v_sqlquery || (' AND TBL_ADMINSENTMAILHISTORY.TOEMAIL LIKE ''%' || v_toemail || '%''');
  END IF;
  EXECUTE v_sqlquery;
  SELECT COUNT(1) INTO v_recordcount FROM tmp_temp;
  RETURN QUERY SELECT * FROM tmp_temp;
  DROP TABLE IF EXISTS tmp_temp;
  RETURN QUERY SELECT v_recordcount AS recordcount;
END;
$$;


--
-- Name: usp_sendticket(text); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_sendticket(v_ticketno text) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
BEGIN
  RETURN QUERY SELECT trm.message, (SELECT dbo.GETFRIENDLYDATETIMEVALUE(trm.date)) AS date, trm.trid, CASE image WHEN '' THEN '' WHEN image THEN 'TicketCenterImage/' || image ELSE '' END AS imageurl, CASE image WHEN '' THEN 0 WHEN image THEN 1 ELSE 0 END AS imgpr, CASE fromtype WHEN 1 THEN 'You' WHEN 2 THEN 'Member' ELSE trm.adminuser END AS adminuser, COALESCE(tm.isdelete, 0) AS isdelete FROM tbl_ticketreply AS trm LEFT OUTER JOIN tbl_ticketmaster AS tm ON trm.tmid = tm.tmid WHERE tm.ticketno = v_ticketno AND COALESCE(tm.isdelete, 0) = 0 ORDER BY trm.date DESC NULLS LAST;
END;
$$;


