--
-- Name: usp_service_tax_history(integer, integer, integer, character varying, boolean, character varying, character varying, character varying, character varying, character varying, integer, character varying, character varying, character varying, character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_service_tax_history(v_startrowindex integer DEFAULT 1, v_maxrows integer DEFAULT 100, v_reqfield integer DEFAULT 0, v_orderbyfield character varying DEFAULT ''::character varying, v_asc boolean DEFAULT false, v_searchfield character varying DEFAULT ''::character varying, v_searchvalue character varying DEFAULT ''::character varying, v_fromdate character varying DEFAULT ''::character varying, v_todate character varying DEFAULT ''::character varying, v_mode character varying DEFAULT '0'::character varying, v_recordcount integer DEFAULT 0, v_status character varying DEFAULT ''::character varying, v_loginid character varying DEFAULT ''::character varying, v_username character varying DEFAULT ''::character varying, v_mobile character varying DEFAULT ''::character varying) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_regno BIGINT;
  v_sqlquery text;
  v_modestatus varchar(10);
BEGIN
  -- SET option (removed)
  v_sqlquery := '';
  v_modestatus := '0';
  v_sqlquery := '';
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp (Rownumber Int GENERATED BY DEFAULT AS IDENTITY,
TASMID bigint,
service_tax decimal(18,2),
ModeName varchar(250),
Transaction_id varchar(250),
username varchar(150),
emailid varchar(150),
fullname varchar(150),
phone varchar(50),
CommentORRemark text,
RegNo bigint,
IsApproved int,
PuchaseDate timestamp) ON COMMIT DROP;
  v_sqlquery := v_sqlquery || (' INSERT INTO #TEMP SELECT TID.TASMID,isnull(TID.service_tax,0),TID.ModeName,
isnull(TID.Transaction_id,''''),isnull(pl.username,''''),isnull(pl.emailid,''''),
isnull(pl.FNAME,'''')+'' ''+isnull(pl.Lname,'''') as fullname, isnull(pl.phone,0),isnull(TID.CommentORRemark,''''),TID.RegNo,isnull(IsApproved,0),TID.PuchaseDate FROM Tbl_AllSubscriptionMaster TID 
 inner join portal_login pl on pl.plid=TID.RegNo where TID.IsApproved=1 ');
  IF (v_searchvalue = 'LOGINID') THEN
  v_sqlquery := v_sqlquery || (' AND PL.emailid LIKE ''%' || v_searchfield || '%'' ');
  END IF;
  IF (v_searchvalue = 'USERNAME') THEN
  v_sqlquery := v_sqlquery || (' AND PL.USERNAME LIKE ''%' || v_searchfield || '%'' ');
  END IF;
  IF (v_searchvalue = 'Phone') THEN
  v_sqlquery := v_sqlquery || (' AND  pl.phone LIKE ''%' || v_searchfield || '%'' ');
  END IF;
  IF (v_loginid <> '') THEN
  v_sqlquery := v_sqlquery || ' AND ISNULL(PL.emailid,'''') LIKE ''%' || v_loginid || '%''';
  END IF;
  IF (v_username <> '') THEN
  v_sqlquery := v_sqlquery || ' AND ISNULL(PL.USERNAME,'''') LIKE ''%' || v_username || '%''';
  END IF;
  IF (v_mobile <> '') THEN
  v_sqlquery := v_sqlquery || ' AND ISNULL(pl.phone,'''') LIKE ''%' || v_mobile || '%''';
  END IF;
  EXECUTE v_sqlquery;
  RETURN QUERY SELECT * FROM tmp_temp WHERE rownumber BETWEEN v_startrowindex AND v_maxrows;
  SELECT COUNT(*) INTO v_recordcount FROM tmp_temp;
  RETURN QUERY SELECT v_recordcount AS recordcount;
  DROP TABLE IF EXISTS tmp_temp;
  -- SET option (removed)
END;
$$;


