--
-- Name: usp_sessionservicesforanroid(character varying, integer, integer, integer, integer, bigint); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_sessionservicesforanroid(v_sessionid character varying, v_status integer, v_active integer, v_mode integer, v_intresult integer, v_clid bigint) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
BEGIN
  -- BEGIN TRAN (removed)
  BEGIN
  IF (v_mode = 1) THEN
  v_intresult := 1;
  UPDATE tbl_sessionservicesforanroid SET clid = v_clid WHERE sessionid = v_sessionid;
  END IF;
  IF (v_mode = 2) THEN
  RETURN QUERY SELECT 1 FROM tbl_sessionservicesforanroid AS ath WHERE ath.sessionid = v_sessionid AND ath.active = 1 AND ath.status = 1;
  END IF;
  IF (v_mode = 3) THEN
  IF EXISTS(SELECT 1 FROM tbl_sessionservicesforanroid AS ath WHERE ath.sessionid = v_sessionid) THEN
  UPDATE tbl_sessionservicesforanroid SET active = 0, status = 0 WHERE sessionid = v_sessionid;
  v_intresult := 1;
  END IF;
  END IF;
  IF (v_mode = 5) THEN
  v_intresult := 1;
  IF (v_clid > 0) THEN
  INSERT INTO tbl_sessionservicesforanroid (sessionid, create_date, status, active, clid) VALUES (v_sessionid, dbo.FUN_GETCURRENTDATE(), 1, 1, v_clid);
  ELSE
  INSERT INTO tbl_sessionservicesforanroid (sessionid, create_date, status, active, clid) VALUES (v_sessionid, dbo.FUN_GETCURRENTDATE(), 1, 1, 0);
  END IF;
  END IF;
  IF (v_mode = 6) THEN
  v_intresult := 1;
  IF NOT EXISTS(SELECT 1 FROM tbl_sessionservicesforanroid WHERE sessionid = v_sessionid) THEN
  INSERT INTO tbl_sessionservicesforanroid (sessionid, create_date, status, active, clid) VALUES (v_sessionid, dbo.FUN_GETCURRENTDATE(), 1, 1, v_clid);
  ELSE
  UPDATE tbl_sessionservicesforanroid SET clid = v_clid WHERE sessionid = v_sessionid;
  END IF;
  END IF;
  IF (v_mode = 7) THEN
  v_intresult := 0;
  IF EXISTS(SELECT 1 FROM tbl_sessionservicesforanroid WHERE sessionid = v_sessionid) THEN
  UPDATE tbl_sessionservicesforanroid SET clid = v_clid WHERE sessionid = v_sessionid;
  v_intresult := 1;
  END IF;
  END IF;
  -- COMMIT (removed)
  EXCEPTION WHEN OTHERS THEN
  IF (0 > 0) THEN
  PERFORM dbo.sp_errorlog();
  v_intresult := 0;
  -- ROLLBACK (removed)
  RETURN;
  END IF;
  END;
END;
$$;


