-- Name: usp_settlementorderhistory(integer, character varying, character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_settlementorderhistory(v_plid integer DEFAULT 1, v_orderno character varying DEFAULT '714572'::character varying, v_strresult character varying DEFAULT ''::character varying) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_gstpercentage numeric(19,4);
BEGIN
  -- BEGIN TRAN (removed)
  -- SET option (removed)
  v_gstpercentage := 0;
  v_strresult := 'OK';
  IF (v_orderno = '') THEN
  -- COMMIT (removed)
  v_strresult := 'ORDER NUMBER IS NOT EXITS.';
  RETURN;
  END IF;
  IF (v_plid = 0) THEN
  -- COMMIT (removed)
  v_strresult := 'MERCHANT NOT EXISTS.';
  RETURN;
  END IF;
  SELECT COALESCE(limits, 0) INTO v_gstpercentage FROM settings WHERE sid = 22 AND active = 1;
  RETURN QUERY SELECT ROW_NUMBER() OVER (ORDER BY om.orderdate DESC NULLS LAST) AS rownumber, pom.loginid, (om.fname || '' || COALESCE(om.lname, '')) AS name, b.clid AS brcode, om.mobileno, om.orderid, CAST(TO_CHAR(om.orderdate, 'DD TMMon YYYY') AS VARCHAR(50)) AS orderdate, om.order_qty, om.order_dap, om.order_netamt, (CASE WHEN om.paymode = 'PAYUMONEY' THEN 'WALLET' ELSE om.paymode END) AS paymode, COALESCE(om.sh_city, '') AS city, om.total_vat, om.intstatus AS orderintstatus, pom.poid, CAST(pom.subprcode AS BIGINT) AS sprid, pom.product_qty, pom.single_dap, ((pom.total_purchase_cost * imsp.admincharge) / 100) AS admincharge2, pom.total_dap, pom.total_ship_ch, pom.total_cost, pom.total_vat AS producttotalvat, pom.total_purchase_cost, pom.product_name, pom.prodqty, pom.prounit, pom.prodcolor, pom.prodsize, pom.prod_images, pom.status, pom.intstatus AS productintstatus, pom.processby, pom.processdate, pom.processremark, COALESCE(pom.invqty, 0) AS invqty, pom.reason, COALESCE(pom.iscancelbymember, 0) AS iscancelbymember, COALESCE(pom.isreturn, 0) AS isreturn, COALESCE(om.address, '') AS address, COALESCE(om.pincode, '') AS pincode, COALESCE(ims.countryname, '') AS countryname, COALESCE(imsp.pv, 0) AS jp, COALESCE(imsp.bv, 0) AS bv, pma.companyname, pma.pmid, imsp.subprcode, COALESCE(ocs.packed, '') AS approved, COALESCE(ocs.packed + imsp.procurementsla, '') AS dispatchdate, imsp.procurementsla, COALESCE(ocs.orderno, '') AS orderno, COALESCE(cm.carrier_name, '') AS couriername, COALESCE(pom.docketno, '') AS docketno, COALESCE(CAST(EXTRACT(epoch FROM CAST(CAST(ocs.delivered AS TIMESTAMP) AS TIMESTAMP) - CAST(CAST(om.orderdate AS TIMESTAMP) AS TIMESTAMP)) / 86400 AS BIGINT), 0) AS datediff, CAST(TO_CHAR(ocs.createddate, 'DD TMMon YYYY') AS VARCHAR(30)) AS createddate, CAST(TO_CHAR(ocs.packed, 'DD TMMon YYYY') AS VARCHAR(30)) AS packed, CAST(TO_CHAR(ocs.handover, 'DD TMMon YYYY') AS VARCHAR(30)) AS handover, CAST(TO_CHAR(ocs.intransit, 'DD TMMon YYYY') AS VARCHAR(30)) AS intransit, CAST(TO_CHAR(ocs.picked, 'DD TMMon YYYY') AS VARCHAR(30)) AS picked, CAST(TO_CHAR(ocs.delivered, 'DD TMMon YYYY') AS VARCHAR(30)) AS delivered, CAST((((pom.total_purchase_cost * imsp.admincharge) / 100) + imsp.handlingcharge + ((pom.total_purchase_cost * imsp.fixedfee) / 100)) * (tmcs.cgstrate + tmcs.sgstrate + tmcs.igstrate) / 100 AS DECIMAL(18, 2)) AS totalgst, CAST(((pom.total_purchase_cost * imsp.admincharge) / 100) + imsp.handlingcharge + tms.shippingcharges + ((pom.total_purchase_cost * imsp.fixedfee) / 100) AS DECIMAL(18, 2)) AS marketplacefee, COALESCE(CAST((pom.total_purchase_cost * imsp.admincharge) / 100 AS DECIMAL(18, 2)), 0) AS admincharge1, COALESCE(cwr.pickup_charges + cwr.deliverycharhes + cwr.taxcharges + cwr.fueltax, 0) AS delieverycharge, imsp.handlingcharge, COALESCE(CAST((pom.total_purchase_cost * imsp.fixedfee) / 100 AS DECIMAL(18, 2)), 0) AS fixedfee, COALESCE(CAST((pom.total_purchase_cost * imsp.admincharge) / 100 * (tmcs.cgstrate + tmcs.sgstrate + tmcs.igstrate) / 100 AS DECIMAL(18, 2)), 0) AS admingst, COALESCE(CAST((cwr.pickup_charges + cwr.deliverycharhes + cwr.taxcharges + cwr.fueltax) * (tms.cgstrate + tms.igstrate + tms.sgstrate) / 100 AS DECIMAL(18, 2)), 0) AS deleverygst, CAST(imsp.handlingcharge * (tmcs.cgstrate + tmcs.sgstrate + tmcs.igstrate) / 100 AS DECIMAL(18, 2)) AS handlinggst, CAST(imsp.fixedfee * (tmcs.cgstrate + tmcs.sgstrate + tmcs.igstrate) / 100 AS DECIMAL(18, 2)) AS fixedfeegst, imsp.admincharge AS adminchargepercentage, CAST(TO_CHAR(modt.duedate, 'DD TMMon YYYY') AS VARCHAR(100)) AS duedate, CAST(TO_CHAR(msc.createdate, 'DD TMMon YYYY') AS VARCHAR(100)) AS settalmentdate FROM tbl_order_master AS om LEFT JOIN tbl_product_order_master AS pom ON pom.orderid = om.orderid JOIN portal_login AS pl ON pl.plid = pom.plid JOIN tbl_customerlogin AS b ON b.loginid = om.loginid LEFT JOIN ims_customeraddress AS ims ON ims.id = b.clid LEFT JOIN portal_master AS pma ON pma.pmid = pl.pmid LEFT JOIN ims_subproduct AS imsp ON imsp.sprid = pom.subprcode LEFT JOIN tbl_couriermaster AS cm ON cm.cmid = pom.cmid LEFT JOIN tbl_order_confirmedstaus AS ocs ON ocs.orderno = pom.orderno LEFT JOIN tbl_courierweeklyreports AS cwr ON pom.docketno = cwr.docketno LEFT JOIN tbl_merchant_ordertransactions AS modt ON pom.invoiceno = modt.invoiceno LEFT JOIN tbl_merchant_settlement_commissions AS msc ON modt.tmorid = msc.tmorid LEFT JOIN tbl_merchant_shippinginvoices_details AS tms ON pom.orderno = tms.orderno LEFT JOIN tbl_merchant_commissioninvoices_details AS tmcs ON pom.orderno = tmcs.orderno WHERE pl.plid = v_plid AND pom.orderno = v_orderno;
  v_strresult := 'OK';
  -- SET option (removed)
  -- COMMIT (removed)
END;
$$;


--
-- Name: usp_shipingchargemaster(integer, character varying, integer, integer, integer, integer, integer, integer, numeric, numeric, character varying, integer, integer, character varying, character varying, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_shipingchargemaster(v_shipdid integer DEFAULT 0, v_weightslab character varying DEFAULT ''::character varying, v_localprice integer DEFAULT NULL::integer, v_zonalprice integer DEFAULT NULL::integer, v_nationalprice integer DEFAULT NULL::integer, v_status integer DEFAULT NULL::integer, v_addby integer DEFAULT NULL::integer, v_mode integer DEFAULT 3, v_minweight numeric DEFAULT NULL::numeric, v_maxweight numeric DEFAULT NULL::numeric, v_strresult character varying DEFAULT NULL::character varying, v_startrowindex integer DEFAULT 1, v_maxrows integer DEFAULT 100, v_fromdate character varying DEFAULT ''::character varying, v_todate character varying DEFAULT ''::character varying, v_totalcount integer DEFAULT 0) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_maxid INT;
BEGIN
  -- BEGIN TRAN (removed)
  -- SET option (removed)
  IF (v_mode = 1) THEN
  v_maxid := 0;
  v_totalcount := 100;
  v_strresult := '';
  IF EXISTS(SELECT shipdid FROM shipingchargesmaster WHERE shipdid = v_shipdid) THEN
  UPDATE shipingchargesmaster SET weightslab = v_weightslab, localprice = v_localprice, zonalprice = v_zonalprice, nationalprice = v_nationalprice, status = v_status, modifydate = CURRENT_TIMESTAMP, minweight = v_minweight, maxweight = v_maxweight WHERE shipdid = v_shipdid;
  v_strresult := 'Update';
  ELSE
  INSERT INTO shipingchargesmaster (weightslab, localprice, zonalprice, nationalprice, status, addby, createdon, modifydate, minweight, maxweight) VALUES (v_weightslab, v_localprice, v_zonalprice, v_nationalprice, v_status, v_addby, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, v_minweight, v_maxweight);
  v_strresult := 'Add';
  END IF;
  END IF;
  IF (v_mode = 2) THEN
  DELETE FROM shipingchargesmaster WHERE shipdid = v_shipdid;
  v_strresult := 'SUCCESS';
  END IF;
  IF (v_mode = 3) THEN
  RETURN QUERY SELECT * FROM shipingchargesmaster;
  END IF;
  IF (0 <> 0) THEN
  v_strresult := 'Error';
  v_totalcount := 100;
  -- ROLLBACK (removed)
  RETURN;
  END IF;
  -- COMMIT (removed)
  -- SET option (removed)
END;
$$;


--
-- Name: usp_showcampaign(integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_showcampaign(v_smcid integer DEFAULT 0) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_slice1 text;
  v_index1 INT;
  v_slice2 text;
  v_campainname varchar(300);
  v_budjetperday numeric(19,4);
  v_adtype int;
  v_campaincreatedate timestamp;
  v_displayurl varchar(500);
  v_destinationurl varchAR(500);
  v_imagename varchar(300);
  v_framesize varchar(100);
  v_keywordid text;
  v_ctid text;
  v_slice3 text;
  v_slice4 text;
  v_index2 int;
  v_keywordname text;
  v_cityname text;
  v_status varchar(50);
BEGIN
  -- SET option (removed)
  DROP TABLE IF EXISTS tmp_tempcamp;
  CREATE TEMP TABLE tmp_tempcamp (id int GENERATED BY DEFAULT AS IDENTITY,



keywordname text) ON COMMIT DROP;
  DROP TABLE IF EXISTS tmp_tempcamp2;
  CREATE TEMP TABLE tmp_tempcamp2 (id int GENERATED BY DEFAULT AS IDENTITY,



cityName text) ON COMMIT DROP;
  SELECT keywordid INTO v_keywordid FROM tbl_sponsor_master_campain WHERE smcid = v_smcid;
  SELECT ctid INTO v_ctid FROM tbl_sponsor_master_campain WHERE smcid = v_smcid;
  v_slice3 := v_ctid;
  v_index2 := 1;
  WHILE v_index2 <> 0 LOOP
  SELECT POSITION(',' IN v_slice3) INTO v_index2;
  IF v_index2 <> 0 THEN
  SELECT LEFT(CAST(v_slice3 AS TEXT), v_index2 - 1) INTO v_slice4;
  ELSE
  SELECT v_slice3 INTO v_slice4;
  END IF;
  INSERT INTO tmp_tempcamp2 SELECT cityname FROM city WHERE ctid = v_slice4;
  IF (0 <> 0) THEN
  RETURN;
  END IF;
  SELECT RIGHT(CAST(v_slice3 AS TEXT), LENGTH(CAST(v_slice3 AS TEXT)) - v_index2) INTO v_slice3;
  IF LENGTH(CAST(v_slice3 AS TEXT)) = 0 THEN
  EXIT;
  END IF;
  -- SET option (removed)
  END LOOP;
  v_slice1 := v_keywordid;
  v_index1 := 1;
  WHILE v_index1 <> 0 LOOP
  SELECT POSITION(',' IN v_slice1) INTO v_index1;
  IF v_index1 <> 0 THEN
  SELECT LEFT(CAST(v_slice1 AS TEXT), v_index1 - 1) INTO v_slice2;
  ELSE
  SELECT v_slice1 INTO v_slice2;
  END IF;
  INSERT INTO tmp_tempcamp SELECT keywordname FROM keyword_master WHERE kmid = v_slice2;
  IF (0 <> 0) THEN
  RETURN;
  END IF;
  SELECT RIGHT(CAST(v_slice1 AS TEXT), LENGTH(CAST(v_slice1 AS TEXT)) - v_index1) INTO v_slice1;
  IF LENGTH(CAST(v_slice1 AS TEXT)) = 0 THEN
  EXIT;
  END IF;
  -- SET option (removed)
  END LOOP;
  SELECT COALESCE(v_keywordname || ',', '') || CAST(keywordname AS VARCHAR(50)) INTO v_keywordname FROM (SELECT keywordname FROM tmp_tempcamp) AS demo;
  SELECT COALESCE(v_cityname || ',', '') || CAST(cityname AS VARCHAR(50)) INTO v_cityname FROM (SELECT cityname FROM tmp_tempcamp2) AS demo2;
  RETURN QUERY SELECT campainname, cidforallcity, budjetperday, (CASE WHEN adtype = 1 THEN 'Image' WHEN adtype = 0 THEN 'Text' END) AS adtype, campaincreatedate, displayurl, destinationurl, imagename, framesize, (CASE WHEN campactive = 0 THEN 'Deactive' WHEN campactive = 1 THEN 'Active' END) AS status, (v_keywordname) AS keywordname, (v_cityname) AS cityname, c.countryname, cm.currencysymbol, heading, descriptionline1, descriptionline2 FROM tbl_sponsor_master_campain JOIN country AS c ON tbl_sponsor_master_campain.cid = c.cid JOIN tbl_currencymaster AS cm ON tbl_sponsor_master_campain.cid = cm.cid WHERE smcid = v_smcid;
  DROP TABLE IF EXISTS tmp_tempcamp;
  DROP TABLE IF EXISTS tmp_tempcamp2;
END;
$$;


