CREATE FUNCTION dbo.usp_showdealimages_detailspage(v_dealid integer) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_image text;
  v_title varchar(500);
  v_alt varchar(500);
BEGIN
  SELECT images, title, LOWER(title) INTO v_image, v_title, v_alt FROM portal_deal_master WHERE dealid = v_dealid AND images <> '';
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp ON COMMIT DROP AS SELECT REPLACE(value, '''', '+opose') AS imgurl, v_title AS title, v_alt AS alttag, ROW_NUMBER() OVER (ORDER BY value ASC NULLS FIRST) AS rownumber FROM dbo.SPLITSTRINGBYCOMMA(v_image);
  RETURN QUERY SELECT *, '' AS imgtitle FROM tmp_temp WHERE imgurl <> '';
  DROP TABLE IF EXISTS tmp_temp;
END;
$$;


