--
-- Name: usp_showenquirylist(integer, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_showenquirylist(v_plid integer DEFAULT 0, v_pmid integer DEFAULT 0) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
BEGIN
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp (RowNUmber Int GENERATED BY DEFAULT AS IDENTITY,
MAILDATE text,
TYPE text,
CCEMAILID text,
CCNAME text,
MOBILE text,
SUBJECT text,
MESSAGE text) ON COMMIT DROP;
  INSERT INTO tmp_temp SELECT CAST(TO_CHAR(maildate, 'DD TMMon YYYY') AS VARCHAR(11)), 'Via Contact Form', ccemailid, ccname, '+' || ' ' || c.isdcode || '-' || ' ' || mobile AS mobile, subject, message FROM portal_inbox INNER JOIN country AS c ON c.countryname = portal_inbox.ipcountry WHERE pmid = v_pmid;
  INSERT INTO tmp_temp SELECT CAST(TO_CHAR(distributeddate, 'DD TMMon YYYY') AS VARCHAR(11)), ('Via Tranfered') AS type, emailid, name, mobile, lookingfor, message FROM tbl_usersystemdistributedenquiry AS tusde INNER JOIN tbl_systemenquiry AS tse ON tusde.tseid = tse.tseid AND tusde.plid = v_plid;
  INSERT INTO tmp_temp SELECT CAST(TO_CHAR(pdi.maildate, 'DD TMMon YYYY') AS VARCHAR(11)) AS maildate, ('Deals') AS type, pdi.ccemailid, pdi.ccname, pdi.mobile, (CASE WHEN pdi.subject = '' THEN 'N/A' ELSE pdi.subject END) AS subject, pdi.message FROM portal_deal_inbox AS pdi INNER JOIN portal_deal_master AS pdm ON pdm.dealid = pdi.dealid WHERE pdm.pmid = v_pmid;
  IF (0 = 0) THEN
  RETURN QUERY SELECT * FROM tmp_temp;
  END IF;
END;
$$;


--
-- Name: usp_showoperatorlisting(bigint, character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_showoperatorlisting(v_optid bigint DEFAULT NULL::bigint, v_date character varying DEFAULT ''::character varying) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
BEGIN
  RETURN QUERY SELECT ROW_NUMBER() OVER (ORDER BY pm.pmid DESC NULLS LAST) AS rownumber, pm.companyname, pm.pmid, (CASE COALESCE(pm.isverified, 0) WHEN 0 THEN 'Unverified' WHEN 1 THEN 'Verified' WHEN 2 THEN 'In Process' END) AS status, (CASE WHEN cn.countryname = 'UNITED STATES' THEN 'US' WHEN cn.countryname = 'UNITED KINGDOM' THEN 'UK' ELSE cn.countryname END) AS countryname, CONCAT(dbo.fun_GetCategoryName(pm.catid), dbo.fun_GetkeyName(pm.keyid), dbo.fun_GetCategoryName(pm.autocatid)) AS catid, (CAST(TO_CHAR(pm.doc, 'DD-MM-YYYY') AS VARCHAR(10)) || ' ' || CAST(TO_CHAR(pm.doc, 'HH24:MI:SS') AS VARCHAR(8))) AS doc FROM portal_master AS pm INNER JOIN tbl_operator_master AS op ON op.optid = pm.optid INNER JOIN country AS cn ON cn.cid = pm.cid WHERE op.optid = v_optid AND TO_DATE(pm.doc, 'YYYY/MM/DD') = TO_DATE(v_date, 'DD-MM-YYYY');
END;
$$;


