--
-- Name: usp_showproductallvideo(integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_showproductallvideo(v_pmid integer DEFAULT 3) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_video text;
  v_videowithcomma text;
  cur_video CURSOR FOR SELECT data FROM videodata WHERE pmid = v_pmid AND status = 1 ORDER BY id ASC NULLS FIRST;
BEGIN
  v_video := '';
  v_videowithcomma := '';
  OPEN cur_video;
  FETCH cur_video INTO v_video;
  WHILE (found) LOOP
  v_videowithcomma := v_videowithcomma || (v_video || ',');
  FETCH cur_video INTO v_video;
  END LOOP;
  CLOSE cur_video;
  -- DEALLOCATE (removed)
  IF (v_video <> '') THEN
  SELECT SUBSTRING(v_videowithcomma FROM 0 FOR (LENGTH(CAST(v_videowithcomma AS TEXT)) - 1)) INTO v_video;
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp ON COMMIT DROP AS SELECT value AS videourl FROM dbo.SPLITSTRINGBYCOMMA(v_video);
  RETURN QUERY SELECT * FROM tmp_temp WHERE videourl <> '';
  DROP TABLE IF EXISTS tmp_temp;
  ELSE
  RETURN QUERY SELECT '' AS videourl;
  END IF;
END;
$$;


