--
-- Name: usp_showrechargehistory(integer, bigint, character varying, character varying, numeric, text, numeric, character varying, text, character varying, character varying, character varying, integer, character varying, character varying, integer, integer, character varying, integer, character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_showrechargehistory(v_mode integer DEFAULT 1, v_plid bigint DEFAULT 0, v_mobile character varying DEFAULT ''::character varying, v_operator character varying DEFAULT ''::character varying, v_amount numeric DEFAULT 0, v_api_refid text DEFAULT ''::text, v_api_balance numeric DEFAULT 0, v_api_errorcode character varying DEFAULT ''::character varying, v_api_remark text DEFAULT ''::text, v_api_reqid character varying DEFAULT ''::character varying, v_api_status character varying DEFAULT ''::character varying, v_strresult character varying DEFAULT ''::character varying, v_totalcount integer DEFAULT 0, v_fromdate character varying DEFAULT ''::character varying, v_todate character varying DEFAULT ''::character varying, v_startrowindex integer DEFAULT 1, v_maxrows integer DEFAULT 100, v_opcode character varying DEFAULT '0'::character varying, v_paymentmode integer DEFAULT 0, v_username character varying DEFAULT ''::character varying) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_minindex INT;
  v_maxindex INT;
  v_query text;
BEGIN
  v_minindex := 1;
  v_maxindex := 100;
  v_minindex := (v_startrowindex - 1) * v_maxrows + 1;
  v_maxindex := v_startrowindex * v_maxrows;
  v_totalcount := 0;
  IF (v_mode = 1) THEN
  DROP TABLE IF EXISTS tmp_temp1;
  CREATE TEMP TABLE tmp_temp1 (ROWNUMBER BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,  
TRHID BIGINT,
PLID  BIGINT, 
NAME VARCHAR(300),  
ACCOUNTNUMBER BIGINT,  
TopupMobileNo BIGINT,  
OPERATOR VARCHAR(1000),  
AMOUNT DECIMAL(18,8), 
RechargeDateAndTime timestamp, 
API_REFID VARCHAR(500),  
API_BALANCE DECIMAL(18,8),  
API_ERRORCODE VARCHAR(1000),  
API_REMARK VARCHAR(1000),  
API_REQID VARCHAR(500),  
API_STATUS VARCHAR(1000), 
JcPercent Decimal(18,8),
IWalletPercent  Decimal(18,8),
BvPercent Decimal(18,8),
STATUS VARCHAR(100),  
INTSTATUS INT) ON COMMIT DROP;
  v_query := '';
  v_query := 'INSERT INTO #TEMP1 Select TRHID,PLID,(Case When FNAME='''' Then ''Not Updated'' Else FNAME End)AS NAME,(LOGINID)AS ACCOUNTNUMBER,(MobileNumber)As TopupMobileNo,Operator,Amount,
(DateAndTime)As RechargeDateAndTime,
API_REFID,API_BALANCE,API_ERRORCODE,  
API_REMARK,API_REQID,API_STATUS,(JPPOINTREDEEMPERCENTAGE)As JcPercent,(EWALLETREDEEMPERCENTAGE)As IWalletPercent,(BVPERCENTAGE)As BvPercent ,
(CASE WHEN TR.STATUS = 1 THEN ''Success''   
When TR.STATUS = 2 Then ''Inprocess''   
When TR.STATUS = 3 Then ''Failed''   
When TR.STATUS = 4 Then ''Refunded'' End),
TR.STATUS From [TBL_RECHARGEHISTORY] TR Inner Join TBL_CUSTOMERLOGIN
ON TBL_CUSTOMERLOGIN.CLID=TR.PLID WHERE TR.STATUS != 0 ';
  IF (v_mobile <> '') THEN
  v_query := v_query || (' AND TR.MOBILENUMBER LIKE ''%' || v_mobile || '%''');
  END IF;
  IF (v_fromdate <> '' AND v_todate = '') THEN
  v_query := v_query || (' AND CONVERT(DATE,TR.DATEANDTIME) >= CONVERT(DATE,''' || v_fromdate || ''')');
  END IF;
  IF (v_fromdate = '' AND v_todate <> '') THEN
  v_query := v_query || (' AND CONVERT(DATE,TR.DATEANDTIME) <= CONVERT(DATE,''' || v_todate || ''')');
  END IF;
  IF (v_fromdate <> '' AND v_todate <> '') THEN
  v_query := v_query || (' AND CONVERT(DATE,TR.DATEANDTIME) BETWEEN CONVERT(DATE,''' || v_fromdate || ''') AND CONVERT(DATE,''' || v_todate || ''')');
  END IF;
  IF (v_api_status <> '' AND v_api_status <> '0') THEN
  v_query := v_query || (' AND TR.STATUS= ''' || v_api_status || '''');
  END IF;
  IF (v_username <> '') THEN
  v_query := v_query || (' AND TBL_CUSTOMERLOGIN.USERNAME LIKE ''%' || v_username || '%'' ');
  END IF;
  v_query := v_query || ' Order By TRHID Desc';
  EXECUTE v_query;
  RETURN QUERY SELECT * FROM tmp_temp1 WHERE rownumber BETWEEN v_minindex AND v_maxindex;
  SELECT COUNT(1) INTO v_totalcount FROM tmp_temp1;
  DROP TABLE IF EXISTS tmp_temp1;
  END IF;
END;
$$;


--
-- Name: usp_singleoperator_all_listings(integer, integer, character varying, character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_singleoperator_all_listings(v_startrowindex integer, v_maxrows integer, v_month character varying DEFAULT ''::character varying, v_operator character varying DEFAULT NULL::character varying) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_sqlquery text;
  v_count int;
  v_count1 int;
  v_date varchar(100);
  v_unverified int;
  v_verified int;
  v_process int;
  v_oprator bigint;
  v_recordcount int;
  v_totallisting int;
  v_totalverified int;
  v_totalunverified int;
  v_totalinprocess int;
  v_operatorname varchar(100);
BEGIN
  -- SET option (removed)
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp (rowNumber int,
optid bigint,
optname varchar(100),
date varchar(100),
logintime varchar(100),
logouttime varchar(100),
totallistings bigint,
unverified bigint,
verified bigint,
process bigint) ON COMMIT DROP;
  v_sqlquery := '';
  v_operatorname := '';
  IF (v_operator <> '') THEN
  SELECT COALESCE(name, '') INTO v_operatorname FROM tbl_operator_master WHERE COALESCE(optid, 0) = v_operator;
  END IF;
  v_sqlquery := ' insert into #temp select ROW_NUMBER() over (order by convert(date,doc) desc) as rownumber ,pm.optid,ISNULL(om.loginid,'''') as optname,
              convert(varchar(20),doc,106) as date,isnull((convert(varchar(20),logintime,105)+'' ''+convert(varchar(8),logintime,108)),''-'') as logintime,
			  isnull((convert(varchar(20),logouttime,105)+'' ''+convert(varchar(8),logouttime,108)),''-'') as logouttime,COUNT(1) as totallistings,
			  0 as unverified,0 as verified,0 as process from portal_master pm left join tbl_operator_report omr 
			  on convert(varchar(20),omr.logintime,105)=convert(varchar(20),pm.doc,105) and ISNULL(omr.optid,0)=ISNULL(pm.optid,0)
			  left join tbl_operator_master om on ISNULL(om.optid,0)=ISNULL(pm.optid,0)
			  where ISNULL(pm.optid,0)<>0  and ISNULL(doc,'''')<>'''' ';
  IF (v_operator <> '') THEN
  v_sqlquery := v_sqlquery || (' and pm.optid = ' || CAST(v_operator AS VARCHAR(20)) || ' ');
  END IF;
  IF (v_month <> '') THEN
  v_sqlquery := v_sqlquery || (' and convert(varchar(7), doc, 126)= ''' || v_month || ''' ');
  END IF;
  v_sqlquery := v_sqlquery || (' group by convert(date,doc),convert(varchar(20),doc,106),(convert(varchar(20),logintime,105)+'' ''+convert(varchar(8),logintime,108)),
		     	   isnull((convert(varchar(20),logouttime,105)+'' ''+convert(varchar(8),logouttime,108)),''-''),pm.optid,ISNULL(om.loginid,'''')  ');
  EXECUTE v_sqlquery;
  v_count1 := v_maxrows;
  v_count := v_startrowindex;
  WHILE (v_count <= v_count1) LOOP
  IF EXISTS(SELECT 1 FROM tmp_temp WHERE rownumber = v_count) THEN
  SELECT date, optid INTO v_date, v_oprator FROM tmp_temp WHERE rownumber = v_count;
  SELECT COUNT(1) INTO v_unverified FROM portal_master WHERE COALESCE(isverified, 0) = 0 AND CAST(TO_CHAR(doc, 'DD TMMon YYYY') AS VARCHAR(20)) = v_date AND COALESCE(optid, 0) = v_oprator;
  SELECT COUNT(1) INTO v_verified FROM portal_master WHERE COALESCE(isverified, 0) = 1 AND CAST(TO_CHAR(doc, 'DD TMMon YYYY') AS VARCHAR(20)) = v_date AND COALESCE(optid, 0) = v_oprator;
  SELECT COUNT(1) INTO v_process FROM portal_master WHERE COALESCE(isverified, 0) = 2 AND CAST(TO_CHAR(doc, 'DD TMMon YYYY') AS VARCHAR(20)) = v_date AND COALESCE(optid, 0) = v_oprator;
  UPDATE tmp_temp SET unverified = v_unverified, verified = v_verified, process = v_process WHERE rownumber = v_count;
  END IF;
  v_count := v_count + 1;
  END LOOP;
  RETURN QUERY SELECT * FROM tmp_temp WHERE rownumber BETWEEN v_startrowindex AND v_maxrows;
  SELECT COUNT(1) INTO v_recordcount FROM tmp_temp;
  SELECT SUM(totallistings) INTO v_totallisting FROM tmp_temp WHERE rownumber BETWEEN v_startrowindex AND v_maxrows;
  SELECT SUM(verified) INTO v_totalverified FROM tmp_temp WHERE rownumber BETWEEN v_startrowindex AND v_maxrows;
  SELECT SUM(unverified) INTO v_totalunverified FROM tmp_temp WHERE rownumber BETWEEN v_startrowindex AND v_maxrows;
  SELECT SUM(process) INTO v_totalinprocess FROM tmp_temp WHERE rownumber BETWEEN v_startrowindex AND v_maxrows;
  RETURN QUERY SELECT v_recordcount AS total, v_operatorname AS operatorname, v_totallisting AS totallistings, v_totalverified AS totalverified, v_totalunverified AS totalunverified, v_totalinprocess AS totalprocess;
  DROP TABLE IF EXISTS tmp_temp;
  -- SET option (removed)
END;
$$;


--
-- Name: usp_sitemapdetails(integer, integer, character varying, text, integer, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_sitemapdetails(v_startrowindex integer DEFAULT 0, v_maxrows integer DEFAULT 0, v_cid character varying DEFAULT ''::character varying, v_catid text DEFAULT ''::text, v_pageno integer DEFAULT 1, v_pagesize integer DEFAULT 30) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_recordcount int;
  v_regno bigint;
  v_pmid int;
  v_isroll varchar(50);
  v_minindex int;
  v_maxindex int;
  v_sqlquery text;
BEGIN
  -- SET option (removed)
  v_minindex := 0;
  v_maxindex := 0;
  v_minindex := ((v_pageno - 1) * v_pagesize) + 1;
  v_maxindex := (v_pageno * v_pagesize);
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp (rowNumber bigint,
pmid bigint,
title text,
canonicalUrl text) ON COMMIT DROP;
  v_sqlquery := '';
  v_sqlquery := 'insert into #temp select ROW_NUMBER() OVER(ORDER BY PM.pmid asc) as rowNumber,PM.pmid,pm.title,
 lower(''qlook.bz/business-details/''+replace(replace(replace(replace(replace(replace(replace(REPLACE(rtrim(ltrim(replace (PM.title,''.'','''')))+'' ''+rtrim(ltrim(PC.CatName))+'' in ''+rtrim(ltrim(ct.cityName)) +''-in-''+ rtrim(ltrim(C.countryName))+''-''+ CONVERT(varchar(50), PM.pmid),'' '',''-''),''&'',''and''),''/'',''-''),''|'',''-''),''#'',''-''),''*'',''-''),'':'',''-''),''+'',''plus'')) as companyname
 from portal_master PM left join country C on pm.cid=c.CID
 left join Portal_Login PL  on pl.pmid=PM.Pmid
 left join CITY ct on PM.ctid=CT.CTID 
 left join Product_Category PC ON PC.catId= CONVERT (int, SUBSTRING((PM.catid+'',''),0,Convert(int,CHARINDEX('','',(PM.catid+'','')))))  where isnull(PM.pmid,0)>0  and pm.active=1 and pm.isverified=1 ';
  IF (v_catid <> '') THEN
  v_sqlquery := v_sqlquery || (' and PC.CatName=''' || v_catid || '''');
  END IF;
  IF (v_cid <> '') THEN
  v_sqlquery := v_sqlquery || (' and c.countryName=''' || v_cid || '''');
  END IF;
  EXECUTE v_sqlquery || ' order by PM.pmid asc ';
  SELECT COUNT(*) INTO v_recordcount FROM tmp_temp;
  RETURN QUERY SELECT * FROM tmp_temp WHERE rownumber BETWEEN v_minindex AND v_maxindex;
  DROP TABLE IF EXISTS tmp_temp;
  RETURN QUERY SELECT v_recordcount AS recordcount;
  -- SET option (removed)
END;
$$;


