-- Name: usp_sms_api(character varying, character varying, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_sms_api(v_smsapi character varying, INOUT v_result character varying, v_pmid integer) RETURNS character varying
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF EXISTS(SELECT 1 FROM distributor_master WHERE pmid = v_pmid) THEN
  IF NOT EXISTS(SELECT 1 FROM tbl_companysettings WHERE pmid = v_pmid) THEN
  INSERT INTO tbl_companysettings (smsapi, pmid) VALUES (v_smsapi, v_pmid);
  v_result := 'Insert';
  ELSE
  UPDATE tbl_companysettings SET smsapi = v_smsapi WHERE pmid = v_pmid;
  v_result := 'Update';
  END IF;
  ELSE
  v_result := 'Invalid Distributor';
  END IF;
END;
$$;


--
-- Name: usp_smscampaignmaster(integer, bigint, text, text, integer, text, character varying, character varying, integer, integer, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_smscampaignmaster(v_plid integer DEFAULT 0, v_type bigint DEFAULT 0, v_tomobile text DEFAULT ''::text, v_message text DEFAULT ''::text, INOUT v_intresult integer DEFAULT 0, v_campaignname text DEFAULT ''::text, v_campaigndate character varying DEFAULT ''::character varying, v_campaigntime character varying DEFAULT ''::character varying, v_issendsms integer DEFAULT 3, v_tscmid integer DEFAULT 0, v_mode integer DEFAULT 0) RETURNS integer
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_msgtype VARCHAR(50);
  v_frommobile VARCHAR(50);
  v_intresultoutput Int;
BEGIN
  v_msgtype := '';
  IF (v_type = 1) THEN
  v_msgtype := 'Transactional';
  END IF;
  IF (v_type = 2) THEN
  v_msgtype := 'Promotional';
  END IF;
  v_frommobile := 'User';
  IF (v_mode = 1) THEN
  -- BEGIN TRAN (removed)
  IF (v_issendsms = 1) THEN
  IF (v_type = 1) THEN
  INSERT INTO msg_history SELECT v_msgtype, v_frommobile, value, dbo.FUN_GETCURRENTDATE(), v_message, 0, 0, v_plid, 1 FROM dbo.SPLITSTRINGBYCUSTOMSYMBOLUPDATE(v_tomobile, ',');
  INSERT INTO tbl_smscampaignmaster (msgtype, smsfromplid, frommobile, smsto, message, campaignname, campaigndate, campaigntime, createddate, issmssent, isactive, status, isdeleted) VALUES (v_msgtype, v_plid, v_frommobile, v_tomobile, v_message, v_campaignname, v_campaigndate, v_campaigntime, dbo.FUN_GETCURRENTDATE(), v_issendsms, 1, 1, 0);
  v_intresult := 1;
  END IF;
  IF (v_type = 2) THEN
  INSERT INTO msg_history SELECT v_msgtype, v_frommobile, value, dbo.FUN_GETCURRENTDATE(), v_message, 0, 0, 0, 1 FROM dbo.SPLITSTRINGBYCUSTOMSYMBOLUPDATE(v_tomobile, ',');
  v_intresult := 1;
  END IF;
  v_intresultoutput := 0;
  SELECT v_intresultoutput INTO v_intresultoutput FROM dbo.usp_emailsmstrafficboosteraccountmanagement(v_mode => 2, v_plid => v_plid, v_tosmsoremail => v_tomobile, v_intresultoutput => v_intresultoutput);
  IF (v_intresultoutput = 0) THEN
  v_intresult := 0;
  -- ROLLBACK (removed)
  RETURN;
  END IF;
  END IF;
  IF (v_issendsms = 0) THEN
  INSERT INTO tbl_smscampaignmaster (msgtype, smsfromplid, frommobile, smsto, message, campaignname, campaigndate, campaigntime, createddate, issmssent, isactive, status, isdeleted) VALUES (v_msgtype, v_plid, v_frommobile, v_tomobile, v_message, v_campaignname, v_campaigndate, v_campaigntime, dbo.FUN_GETCURRENTDATE(), v_issendsms, 1, 1, 0);
  v_intresult := 2;
  END IF;
  IF (0 <> 0) THEN
  v_intresult := 0;
  -- ROLLBACK (removed)
  RETURN;
  END IF;
  -- COMMIT (removed)
  END IF;
  IF (v_mode = 2) THEN
  IF EXISTS(SELECT 1 FROM tbl_smscampaignmaster WHERE issmssent = 1 AND tscmid = v_tscmid) THEN
  v_intresult := 4;
  ELSE
  UPDATE tbl_smscampaignmaster SET msgtype = v_msgtype, smsfromplid = v_plid, frommobile = v_frommobile, smsto = v_tomobile, message = v_message, campaignname = v_campaignname, campaigndate = v_campaigndate, campaigntime = v_campaigntime, issmssent = (CASE WHEN v_issendsms = 3 THEN 0 ELSE v_issendsms END) WHERE tscmid = v_tscmid;
  IF (v_issendsms = 1) THEN
  v_intresult := 3;
  ELSE
  v_intresult := 6;
  END IF;
  END IF;
  END IF;
END;
$$;


--
-- Name: usp_smspackmaster(integer, character varying, text, integer, numeric, numeric, numeric, bigint, bigint, integer, integer, numeric); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_smspackmaster(v_mode integer DEFAULT 1, v_packagename character varying DEFAULT ''::character varying, v_packagefeaturedescription text DEFAULT ''::text, v_isactive integer DEFAULT 0, v_amount numeric DEFAULT 0.00, v_totalamount numeric DEFAULT 0.00, v_st numeric DEFAULT 0.00, v_noofsms bigint DEFAULT 0, v_noofdaysvalidity bigint DEFAULT 0, v_intresult integer DEFAULT 0, v_tspmid integer DEFAULT 0, v_bvpercentage numeric DEFAULT 0.00) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF (v_mode = 1) THEN
  RETURN QUERY SELECT ROW_NUMBER() OVER (ORDER BY tspmid NULLS FIRST) AS rownumber, tspmid, packagename, packagefeaturedescription, (CASE WHEN isactive = 1 THEN 'Active' ELSE 'Deactive' END) AS isactive, amount, totalamount, st, noofsms, noofdaysvalidity, bvpercentage FROM tbl_smspackmaster;
  v_intresult := 1;
  END IF;
  IF (v_mode = 2) THEN
  INSERT INTO tbl_smspackmaster (packagename, packagefeaturedescription, isactive, amount, totalamount, st, noofsms, noofdaysvalidity, bvpercentage) VALUES (v_packagename, v_packagefeaturedescription, v_isactive, v_amount, v_totalamount, v_st, v_noofsms, v_noofdaysvalidity, v_bvpercentage);
  v_intresult := 2;
  END IF;
  IF (v_mode = 3) THEN
  UPDATE tbl_smspackmaster SET packagename = v_packagename, packagefeaturedescription = v_packagefeaturedescription, isactive = v_isactive, amount = v_amount, totalamount = v_totalamount, st = v_st, noofsms = v_noofsms, noofdaysvalidity = v_noofdaysvalidity, bvpercentage = v_bvpercentage WHERE tspmid = v_tspmid;
  v_intresult := 3;
  END IF;
  IF (0 <> 0) THEN
  v_intresult := 0;
  RETURN;
  END IF;
END;
$$;


--
-- Name: usp_social_logincheck(character varying, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_social_logincheck(v_emailid character varying, v_did integer) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_plid BIGINT;
  v_regno BIGINT;
BEGIN
  v_plid := 0;
  SELECT clid INTO v_plid FROM tbl_customerlogin WHERE emailid = v_emailid AND did = v_did;
  IF (v_plid = 0) THEN
  SELECT clid, regno INTO v_plid, v_regno FROM tbl_customerlogin WHERE emailid = v_emailid AND did = v_did;
  ELSE
  IF EXISTS(SELECT 1 FROM tbl_customerlogin WHERE emailid = v_emailid AND did = v_did) THEN
  RETURN QUERY SELECT CAST(pl.clid AS BIGINT) AS plid, CAST(COALESCE(pl.pmid, 0) AS BIGINT) AS pmid, CAST(COALESCE(smd.smdid, 0) AS BIGINT) AS smdid, pl.loginid, (COALESCE(pl.fname, '') || ' ' || COALESCE(pl.lname, '')) AS name, COALESCE(pl.username, pl.loginid) AS username, CAST(COALESCE(pl.cid, 0) AS BIGINT) AS cid, did FROM tbl_customerlogin AS pl LEFT JOIN sponsor_master_detail AS smd ON pl.clid = smd.plid WHERE pl.emailid = v_emailid AND did = v_did AND pl.active = 1;
  END IF;
  END IF;
END;
$$;


