CREATE FUNCTION dbo.usp_sponser_addpackage(v_pegref integer DEFAULT 0, v_locationno integer DEFAULT 0, v_locationname character varying DEFAULT ''::character varying, v_framesize character varying DEFAULT ''::character varying, v_locationprice bigint DEFAULT NULL::bigint, v_description character varying DEFAULT ''::character varying, v_image character varying DEFAULT ''::character varying, v_packagename character varying DEFAULT ''::character varying, v_mode integer DEFAULT 0, v_sapid integer DEFAULT 0, v_active integer DEFAULT 1, INOUT v_intresult integer DEFAULT NULL::integer) RETURNS integer
