  IF (COALESCE(v_image, '') <> '' OR v_image <> NULL) THEN
  UPDATE sponser_addpackage SET image = v_image WHERE sapid = v_sapid;
  END IF;
  ELSE
  INSERT INTO sponser_addpackage (pegref, locationno, locationname, framesize, locationprice, description, active, image, packagename) VALUES (v_pegref, v_locationno, v_locationname, v_framesize, v_locationprice, v_description, v_active, v_image, v_packagename);
  END IF;
  IF (0 <> 0) THEN
  -- ROLLBACK (removed)
  v_intresult := 0;
  RETURN;
  END IF;
  v_intresult := 1;
END;
$$;


