--
-- Name: usp_sponserlist(integer, integer, character varying, boolean, date, date, character varying, character varying, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_sponserlist(v_startrowindex integer, v_maxrows integer, v_orderbyfield character varying, v_asc boolean, v_todate date DEFAULT NULL::date, v_fromdate date DEFAULT NULL::date, v_searchfield character varying DEFAULT NULL::character varying, v_searchvalue character varying DEFAULT NULL::character varying, v_mode integer DEFAULT NULL::integer) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_recordcount int;
  v_regno bigint;
BEGIN
  -- SET option (removed)
  DROP TABLE IF EXISTS tmp_temp12;
  CREATE TEMP TABLE tmp_temp12 ON COMMIT DROP AS SELECT ROW_NUMBER() OVER (ORDER BY sp.spid DESC NULLS LAST) AS rownumber, sp.spid, sp.url, (CASE sp.pageref WHEN 1 THEN 'Main Page' WHEN 2 THEN 'Category Page' ELSE 'Sub Category Page' END) AS pageref, (CASE sp.locationno WHEN 1 THEN 'Top' WHEN 2 THEN 'Right Top' WHEN 3 THEN 'Right Middle' ELSE 'Right Buttom' END) AS locationno, sp.framesize, sp.locationprice, sp.packagename, sr.name, sr.emailid, sr.mobileno, sr.msg, sr.reqdate, sr.reqappdate, sr.active FROM sponsoredadd AS sp JOIN sponsoredaddrequest AS sr ON sp.spid = sr.spid AND sr.active = 1 AND sp.active = 1;
  SELECT COUNT(*) INTO v_recordcount FROM tmp_temp12;
  IF (v_searchfield = '1') THEN
  RETURN QUERY SELECT * FROM tmp_temp12 WHERE name = v_searchvalue;
  END IF;
  IF (v_searchfield = '2') THEN
  RETURN QUERY SELECT * FROM tmp_temp12 WHERE pageref = v_searchvalue;
  END IF;
  IF (v_searchfield = '3') THEN
  RETURN QUERY SELECT * FROM tmp_temp12 WHERE locationno = v_searchvalue;
  END IF;
  IF (v_searchfield = '4') THEN
  RETURN QUERY SELECT * FROM tmp_temp12 WHERE locationprice = v_searchvalue;
  END IF;
  IF (v_searchfield = '5') THEN
  RETURN QUERY SELECT * FROM tmp_temp12 WHERE packagename = v_searchvalue;
  END IF;
  IF (v_todate <> '' AND v_fromdate <> '') THEN
  RETURN QUERY SELECT * FROM tmp_temp12 WHERE reqappdate BETWEEN v_todate AND v_fromdate;
  END IF;
  IF (v_searchfield = '') THEN
  RETURN QUERY SELECT * FROM tmp_temp12 WHERE rownumber BETWEEN v_startrowindex AND v_maxrows;
  END IF;
  DROP TABLE IF EXISTS tmp_temp12;
  -- SET option (removed)
END;
$$;


