    LANGUAGE plpgsql
    AS $$
DECLARE
  v_slice1 text;
  v_slice3 text;
  v_index1 INT;
  v_index2 INT;
  v_slice2 text;
  v_slice4 text;
  v_sid int;
  v_cid int;
  v_catid int;
BEGIN
  v_sid := 0;
  v_cid := 0;
  v_catid := 0;
