  v_slice1 := v_cityid;
  v_intresult := 1;
  v_index1 := 1;
  UPDATE tbl_sponsor_search SET searchactive = 0 WHERE smcid = v_smcid;
  WHILE v_index1 <> 0 LOOP
  SELECT POSITION(',' IN v_slice1) INTO v_index1;
  IF v_index1 <> 0 THEN
  SELECT LEFT(CAST(v_slice1 AS TEXT), v_index1 - 1) INTO v_slice2;
  ELSE
  SELECT v_slice1 INTO v_slice2;
  END IF;
  v_index2 := 1;
  v_slice3 := v_keywordid;
  WHILE v_index2 <> 0 LOOP
  SELECT POSITION(',' IN v_slice3) INTO v_index2;
  IF v_index2 <> 0 THEN
  SELECT LEFT(CAST(v_slice3 AS TEXT), v_index2 - 1) INTO v_slice4;
  ELSE
  SELECT v_slice3 INTO v_slice4;
  END IF;
  SELECT cid, sid INTO v_cid, v_sid FROM city WHERE ctid = v_slice2;
  SELECT catid INTO v_catid FROM keyword_master WHERE kmid = v_slice4;
  IF EXISTS(SELECT keyid FROM tbl_sponsor_search WHERE keyid = v_slice4 AND smcid = v_smcid AND ctid = v_slice2) THEN
  UPDATE tbl_sponsor_search SET searchactive = 1 WHERE keyid = v_slice4 AND smcid = v_smcid AND ctid = v_slice2;
  ELSE
  INSERT INTO tbl_sponsor_search (smid, smcid, pageref, pagelocation, keyid, catid, cid, sid, ctid, cidforallcity, adtype) VALUES (v_smid, v_smcid, v_pageref, v_pagelocation, v_slice4, v_catid, v_cid, v_sid, v_slice2, v_cidforallcity, v_adtype);
  END IF;
  IF (0 <> 0) THEN
  v_intresult := 2;
  -- ROLLBACK (removed)
  RETURN;
  END IF;
  SELECT RIGHT(CAST(v_slice3 AS TEXT), LENGTH(CAST(v_slice3 AS TEXT)) - v_index2) INTO v_slice3;
  IF LENGTH(CAST(v_slice3 AS TEXT)) = 0 THEN
  EXIT;
  END IF;
  END LOOP;
  IF (0 <> 0) THEN
  v_intresult := 2;
  -- ROLLBACK (removed)
  RETURN;
  END IF;
  SELECT RIGHT(CAST(v_slice1 AS TEXT), LENGTH(CAST(v_slice1 AS TEXT)) - v_index1) INTO v_slice1;
  IF LENGTH(CAST(v_slice1 AS TEXT)) = 0 THEN
  EXIT;
  END IF;
  -- SET option (removed)
  END LOOP;
END;
$$;


