CREATE FUNCTION dbo.usp_statecountry(v_startrowindex integer, v_maxrows integer, v_orderbyfield character varying, v_asc boolean, v_searchfield character varying, v_searchvalue character varying, v_mode integer) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_recordcount int;
  v_regno bigint;
BEGIN
  -- SET option (removed)
  DROP TABLE IF EXISTS tmp_temp13;
  CREATE TEMP TABLE tmp_temp13 ON COMMIT DROP AS SELECT ROW_NUMBER() OVER (ORDER BY countryname NULLS FIRST) AS rownumber, c.cid, c.countryname FROM country AS c WHERE cactive = 1 ORDER BY c.countryname NULLS FIRST;
  SELECT COUNT(*) INTO v_recordcount FROM tmp_temp13;
  IF (v_searchfield = 'countryName') THEN
  RETURN QUERY SELECT * FROM tmp_temp13 WHERE countryname LIKE '%' || v_searchvalue || '%' AND rownumber BETWEEN v_startrowindex AND v_maxrows;
  END IF;
  IF (v_searchfield = '') THEN
  RETURN QUERY SELECT * FROM tmp_temp13 WHERE rownumber BETWEEN v_startrowindex AND v_maxrows;
  END IF;
  DROP TABLE IF EXISTS tmp_temp13;
  -- SET option (removed)
END;
$$;


--
-- Name: usp_statepaging(integer, integer, character varying, boolean, character varying, character varying, integer, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_statepaging(v_startrowindex integer, v_maxrows integer, v_orderbyfield character varying, v_asc boolean, v_searchfield character varying, v_searchvalue character varying, v_mode integer, v_intresult integer DEFAULT 0) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_recordcount int;
  v_regno bigint;
  v_minindex INT;
  v_maxindex INT;
  v_query text;
BEGIN
  -- SET option (removed)
  v_minindex := (v_startrowindex - 1) * v_maxrows + 1;
  v_maxindex := v_startrowindex * v_maxrows;
  DROP TABLE IF EXISTS tmp_temp13;
  CREATE TEMP TABLE tmp_temp13 ON COMMIT DROP AS SELECT ROW_NUMBER() OVER (ORDER BY c.countryname NULLS FIRST, s.statename NULLS FIRST) AS rownumber, sid, c.cid, c.countryname, s.statename, s.sactive FROM country AS c LEFT OUTER JOIN state AS s ON c.cid = s.cid WHERE c.cactive = 1 AND s.sactive = 1 ORDER BY s.statename ASC NULLS FIRST;
  SELECT COUNT(*) INTO v_recordcount FROM tmp_temp13;
  IF (v_searchfield = 'countryName') THEN
  RETURN QUERY SELECT * FROM tmp_temp13 WHERE countryname LIKE '%' || v_searchvalue || '%' AND rownumber BETWEEN v_startrowindex AND v_maxrows;
  END IF;
  IF (v_searchfield = 'stateName') THEN
  RETURN QUERY SELECT * FROM tmp_temp13 WHERE statename LIKE '%' || v_searchvalue || '%' AND rownumber BETWEEN v_startrowindex AND v_maxrows;
  END IF;
  IF (v_searchfield = '') THEN
  RETURN QUERY SELECT * FROM tmp_temp13 WHERE rownumber BETWEEN v_minindex AND v_maxindex;
  END IF;
  SELECT COUNT(1) INTO v_intresult FROM tmp_temp13;
  DROP TABLE IF EXISTS tmp_temp13;
  -- SET option (removed)
END;
$$;


