  INSERT INTO tmp_temppmid (srno, pmid) SELECT ROW_NUMBER() OVER (ORDER BY dbo.MYRANDOM_GEN_REPLACE1(v_randnumber, pmid) NULLS FIRST) AS srno, pmid FROM distributor_master WHERE cid = v_cid AND aid = v_aid AND (',' || subkeyid || ',') LIKE '%,' || v_catid || ',%' AND (',' || CAST(ctid AS VARCHAR(50)) || ',') LIKE '%,' || v_city || ',%' AND active = 1 AND COALESCE(isverified, 0) = 1 AND NOT pmid IN (SELECT pmid FROM tmp_temppmid);
  ELSE
  INSERT INTO tmp_temppmid (srno, pmid) SELECT ROW_NUMBER() OVER (ORDER BY dbo.MYRANDOM_GEN_REPLACE1(v_randnumber, pmid) NULLS FIRST) AS srno, pmid FROM distributor_master WHERE cid = v_cid AND aid = v_aid AND (',' || CAST(ctid AS VARCHAR(100)) || ',') LIKE '%,' || v_city || ',%' AND active = 1 AND COALESCE(isverified, 0) = 1 AND expirydate >= GETUTCDATE() AND NOT pmid IN (SELECT pmid FROM tmp_temppmid);
  INSERT INTO tmp_temppmid (srno, pmid) SELECT ROW_NUMBER() OVER (ORDER BY dbo.MYRANDOM_GEN_REPLACE1(v_randnumber, pmid) NULLS FIRST) AS srno, pmid FROM distributor_master WHERE cid = v_cid AND aid = v_aid AND (',' || subctid || ',') LIKE '%,' || v_city || ',%' AND active = 1 AND COALESCE(isverified, 0) = 1 AND expirydate >= GETUTCDATE() AND NOT pmid IN (SELECT pmid FROM tmp_temppmid);
  INSERT INTO tmp_temppmid (srno, pmid) SELECT ROW_NUMBER() OVER (ORDER BY dbo.MYRANDOM_GEN_REPLACE1(v_randnumber, pmid) NULLS FIRST) AS srno, pmid FROM distributor_master WHERE cid = v_cid AND aid = v_aid AND (',' || CAST(ctid AS VARCHAR(50)) || ',') LIKE '%,' || v_city || ',%' AND active = 1 AND COALESCE(isverified, 0) = 1 AND NOT pmid IN (SELECT pmid FROM tmp_temppmid);
  INSERT INTO tmp_temppmid (srno, pmid) SELECT ROW_NUMBER() OVER (ORDER BY dbo.MYRANDOM_GEN_REPLACE1(v_randnumber, pmid) NULLS FIRST) AS srno, pmid FROM distributor_master WHERE cid = v_cid AND aid = v_aid AND (',' || CAST(subctid AS VARCHAR(50)) || ',') LIKE '%,' || v_city || ',%' AND active = 1 AND COALESCE(isverified, 0) = 1 AND NOT pmid IN (SELECT pmid FROM tmp_temppmid);
  END IF;
  END IF;
  IF ((v_city = '0' OR v_city = '') AND v_aid = '') THEN
  IF (v_catid <> '' AND v_catid <> '0') THEN
  INSERT INTO tmp_temppmid (srno, pmid) SELECT ROW_NUMBER() OVER (ORDER BY dbo.MYRANDOM_GEN_REPLACE1(v_randnumber, pmid) NULLS FIRST) AS srno, pmid FROM distributor_master WHERE cid = v_cid AND (',' || keyid || ',') LIKE '%,' || v_catid || ',%' AND (',' || CAST(ctid AS VARCHAR(100)) || ',') LIKE '%,' || v_city || ',%' AND active = 1 AND COALESCE(isverified, 0) = 1 AND expirydate >= GETUTCDATE() AND NOT pmid IN (SELECT pmid FROM tmp_temppmid);
  INSERT INTO tmp_temppmid (srno, pmid) SELECT ROW_NUMBER() OVER (ORDER BY dbo.MYRANDOM_GEN_REPLACE1(v_randnumber, pmid) NULLS FIRST) AS srno, pmid FROM distributor_master WHERE cid = v_cid AND (',' || subkeyid || ',') LIKE '%,' || v_catid || ',%' AND active = 1 AND COALESCE(isverified, 0) = 1 AND expirydate >= GETUTCDATE() AND NOT pmid IN (SELECT pmid FROM tmp_temppmid);
  INSERT INTO tmp_temppmid (srno, pmid) SELECT ROW_NUMBER() OVER (ORDER BY dbo.MYRANDOM_GEN_REPLACE1(v_randnumber, pmid) NULLS FIRST) AS srno, pmid FROM distributor_master WHERE cid = v_cid AND (',' || keyid || ',') LIKE '%,' || v_catid || ',%' AND active = 1 AND COALESCE(isverified, 0) = 1 AND NOT pmid IN (SELECT pmid FROM tmp_temppmid);
  INSERT INTO tmp_temppmid (srno, pmid) SELECT ROW_NUMBER() OVER (ORDER BY dbo.MYRANDOM_GEN_REPLACE1(v_randnumber, pmid) NULLS FIRST) AS srno, pmid FROM distributor_master WHERE cid = v_cid AND (',' || subkeyid || ',') LIKE '%,' || v_catid || ',%' AND active = 1 AND COALESCE(isverified, 0) = 1 AND NOT pmid IN (SELECT pmid FROM tmp_temppmid);
  ELSE
  INSERT INTO tmp_temppmid (srno, pmid) SELECT ROW_NUMBER() OVER (ORDER BY dbo.MYRANDOM_GEN_REPLACE1(v_randnumber, pmid) NULLS FIRST) AS srno, pmid FROM distributor_master WHERE cid = v_cid AND active = 1 AND COALESCE(isverified, 0) = 1 AND expirydate >= GETUTCDATE() AND NOT pmid IN (SELECT pmid FROM tmp_temppmid);
  INSERT INTO tmp_temppmid (srno, pmid) SELECT ROW_NUMBER() OVER (ORDER BY dbo.MYRANDOM_GEN_REPLACE1(v_randnumber, pmid) NULLS FIRST) AS srno, pmid FROM distributor_master WHERE cid = v_cid AND active = 1 AND COALESCE(isverified, 0) = 1 AND expirydate >= GETUTCDATE() AND NOT pmid IN (SELECT pmid FROM tmp_temppmid);
  INSERT INTO tmp_temppmid (srno, pmid) SELECT ROW_NUMBER() OVER (ORDER BY dbo.MYRANDOM_GEN_REPLACE1(v_randnumber, pmid) NULLS FIRST) AS srno, pmid FROM distributor_master WHERE cid = v_cid AND active = 1 AND COALESCE(isverified, 0) = 1 AND NOT pmid IN (SELECT pmid FROM tmp_temppmid);
  INSERT INTO tmp_temppmid (srno, pmid) SELECT ROW_NUMBER() OVER (ORDER BY dbo.MYRANDOM_GEN_REPLACE1(v_randnumber, pmid) NULLS FIRST) AS srno, pmid FROM distributor_master WHERE cid = v_cid AND active = 1 AND COALESCE(isverified, 0) = 1 AND NOT pmid IN (SELECT pmid FROM tmp_temppmid);
  END IF;
  END IF;
  SELECT COUNT(pmid) INTO v_count FROM tmp_temppmid;
  IF (v_count = 0) THEN
  SELECT catid INTO v_catid FROM keyword_master WHERE kmid = v_catid;
  v_searchtype := 'C';
  END IF;
  END IF;
  END IF;
  SELECT COUNT(rownumber) INTO v_noofrec FROM tmp_temppmid;
  RETURN QUERY SELECT CAST(ROW_NUMBER() OVER (ORDER BY plid ASC NULLS FIRST) AS INT) AS rownumber, ('https://laviecarebiz.com/images/logo.png') AS companyimage, p.pmid, p.title, p.mobileno, p.url, p.comemailid, (p.areaname || ', ' || c.cityname || ', ' || p.pincode) AS completeaddress, dbo.GENRATINGURL(p.pmid) AS detailsurl, v_noofrec AS noofrec, dbo.FINDTOTALREATING(p.pmid) AS avgrating, (SELECT COUNT(rwid) FROM tbl_reviewmaster WHERE pmid = p.pmid AND status = 1) AS totalreviews, (SUBSTRING(p.companydesc FROM 1 FOR 175)) AS companydesc FROM distributor_master AS p, city AS c WHERE p.ctid = c.ctid;
  DROP TABLE IF EXISTS tmp_temppmid;
  DROP TABLE IF EXISTS tmp_tempareaid;
  -- SET option (removed)
END;
$$;


--
-- Name: usp_subcategory(integer, integer, integer, integer, integer, text, text, integer, text, integer, integer, numeric, integer, numeric, numeric, character varying, character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_subcategory(v_mode integer DEFAULT 0, v_sequence integer DEFAULT 0, v_intresult integer DEFAULT 0, v_catid integer DEFAULT 0, v_scatid integer DEFAULT 0, v_scatname text DEFAULT ''::text, v_scatdesc text DEFAULT ''::text, v_scatactive integer DEFAULT 1, v_scatimgname text DEFAULT ''::text, v_startrowindex integer DEFAULT 1, v_maxrows integer DEFAULT 100, v_admincommission numeric DEFAULT 0, v_delieverycharges integer DEFAULT 0, v_handlingcharges numeric DEFAULT 0, v_fixedfee numeric DEFAULT 0, v_searchcategory character varying DEFAULT ''::character varying, v_searchsubcategory character varying DEFAULT ''::character varying) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_minindex INT;
  v_maxindex INT;
  v_query text;
  v_condition text;
  v_countquery text;
  v_oldmaincatid int;
  v_totalproduct INT;
  v_catid_hid int;
  v_recordcount INT;
  v_parmdefinition varchar(70);
  v_outputparam Int;
BEGIN
  -- BEGIN TRAN (removed)
  -- SET option (removed)
  v_intresult := 0;
  IF (v_mode = 0) THEN
  v_query := '';
  v_condition := '';
  v_countquery := '';
  v_oldmaincatid := 0;
  v_totalproduct := 0;
  v_catid_hid := 0;
  v_minindex := (v_startrowindex - 1) * v_maxrows + 1;
  v_maxindex := v_startrowindex * v_maxrows;
  v_query := 'SELECT ROW_NUMBER() OVER(ORDER BY PS.SCATID DESC ) AS ROWNUMBER,PS.SCATID,PS.SCATNAME,PS.SCATDESC,PC.CATNAME,
ISNULL(PS.SCAT_CODE,'''') AS SCAT_CODE, (CASE PS.SCATACTIVE WHEN 1 THEN ''Active'' ELSE ''Deactive'' END) AS SCATACTIVE,
ISNULL(TC.AdminCharge,0) AS ADMINCHARGE,ISNULL(TC.DelieveryCharge,0) AS DelieveryCharge,ISNULL(TC.HandlingCharge,0) AS HandlingCharge,PS.CatID
INTO #TEMP13 FROM PRODUCT_SUBCATEGORY PS left Join PRODUCT_CATEGORY PC ON PS.CATID=PC.CATID 
Left Join TBL_CATEGORY TC ON TC.CatId=PS.SCATID where 1=1 ';
  v_parmdefinition := N'@INTRESULT NVARCHAR(70) OUTPUT';
  v_countquery := N'SELECT @INTRESULT= COUNT(1)FROM PRODUCT_SUBCATEGORY PS left JOIN PRODUCT_CATEGORY PC ON PS.CATID = PC.CATID 
Left Join TBL_CATEGORY TC ON TC.CatId=PS.SCATID where 1=1';
  IF (v_searchsubcategory <> '') THEN
  v_searchsubcategory := REPLACE(v_searchsubcategory, '''', '''''');
  v_condition := v_condition || ('AND PS.SCATNAME=''' || v_searchsubcategory || '''');
  END IF;
  IF (v_searchcategory <> '') THEN
  v_searchcategory := REPLACE(v_searchcategory, '''', '''''');
  v_condition := v_condition || ('AND PC.CATNAME=''' || v_searchcategory || '''');
  END IF;
  v_query := v_query || v_condition || ' ;SELECT  *  FROM #TEMP13 WHERE ROWNUMBER BETWEEN ' || CAST(v_minindex AS VARCHAR(70)) || ' AND ' || CAST(v_maxindex AS VARCHAR(70)) || '';
  v_countquery := v_countquery || v_condition;
  RAISE NOTICE '%', v_query;
  EXECUTE v_query;
  EXECUTE v_countquery;
  -- COMMIT (removed)
  RETURN;
  END IF;
  IF (v_mode = 1) THEN
  RETURN QUERY SELECT ps.scatid, ps.scatname, ps.scatdesc, pc.catname, ps.scatactive, COALESCE(ps.scat_code, '') AS scat_code, ps.catid, COALESCE(tc.admincharge, 0.00) AS admincharge, COALESCE(tc.delieverycharge, 0) AS delieverycharge, (CASE WHEN (COALESCE(tc.handlingcharge, 0)) = 0 THEN 0 ELSE CAST(handlingcharge AS DECIMAL(10, 2)) END) AS handlingcharge, COALESCE(tc.fixedfee, 0) AS fixedfee FROM product_subcategory AS ps INNER JOIN product_category AS pc ON ps.catid = pc.catid INNER JOIN tbl_category AS tc ON tc.catid = ps.scatid WHERE ps.scatid = v_scatid;
  v_intresult := 2;
  -- COMMIT (removed)
  RETURN;
  END IF;
  IF (v_mode = 2) THEN
  IF EXISTS(SELECT 1 FROM product_subcategory WHERE catid = v_catid AND scatname = v_scatname AND scatid <> v_scatid) THEN
  v_intresult := 6;
  -- COMMIT (removed)
  RETURN;
  END IF;
  INSERT INTO tbl_category_maoncategory_changehistory (catid, maincatid, catname, status, cat_code, cat_imgname, sequence, isdelete, admincharge, ishot_links, ishot_menu, ishot_withitem, delieverycharge, handlingcharge, fixedfee, totalactive, totalqcsend, totalready, totalfailed, create_date) SELECT catid, maincatid, catname, status, cat_code, cat_imgname, sequence, isdelete, admincharge, ishot_links, ishot_menu, ishot_withitem, delieverycharge, handlingcharge, fixedfee, totalactive, totalqcsend, totalready, totalfailed, dbo.FUN_GETCURRENTDATE() FROM tbl_category WHERE catid = v_scatid;
  SELECT IDENT_CURRENT('TBL_CATEGORY_MAONCATEGORY_CHANGEHISTORY') INTO v_catid_hid;
  SELECT COALESCE(maincatid, 0) INTO v_oldmaincatid FROM tbl_category_maoncategory_changehistory WHERE catid_hid = v_catid_hid;
  UPDATE product_subcategory SET scatname = v_scatname, scatdesc = v_scatdesc, scatactive = v_scatactive, catid = v_catid, scat_code = dbo.REMOVESPACESANDSPECIALCHARS(v_scatname) WHERE scatid = v_scatid;
  UPDATE tbl_category SET maincatid = v_catid, catname = v_scatname, cat_code = dbo.REMOVESPACESANDSPECIALCHARS(v_scatname), status = v_scatactive, sequence = (CASE WHEN v_sequence = 0 THEN sequence ELSE v_sequence END), admincharge = v_admincommission, delieverycharge = v_delieverycharges, handlingcharge = v_handlingcharges, fixedfee = v_fixedfee WHERE catid = v_scatid;
  IF NOT EXISTS(SELECT 1 FROM tbl_sub_category WHERE catid = v_scatid AND maincatid = v_catid) THEN
  UPDATE tbl_sub_category SET maincatid = v_catid WHERE catid = v_scatid;
  END IF;
  IF NOT EXISTS(SELECT 1 FROM keyword_master WHERE scatid = v_scatid AND catid = v_catid) THEN
  UPDATE keyword_master SET catid = v_catid WHERE scatid = v_scatid;
  END IF;
  IF NOT EXISTS(SELECT 1 FROM tbl_attributes_with_category WHERE main_cat_id = v_catid AND cat_id = v_scatid) THEN
  UPDATE tbl_attributes_with_category SET main_cat_id = v_catid WHERE cat_id = v_scatid;
  END IF;
  IF NOT EXISTS(SELECT 1 FROM ims_masterproduct_temp WHERE maincategoryid = v_catid AND catid = v_scatid) THEN
  UPDATE ims_masterproduct_temp SET maincategoryid = v_catid WHERE catid = v_scatid;
  END IF;
  IF NOT EXISTS(SELECT 1 FROM ims_masterproduct WHERE maincategoryid = v_catid AND catid = v_scatid) THEN
  UPDATE ims_masterproduct SET maincategoryid = v_catid WHERE catid = v_scatid;
  END IF;
  IF (v_catid <> 0) THEN
  v_totalproduct := 0;
  SELECT v_totalcount INTO v_totalproduct FROM dbo.usp_totalproducts(v_maincatid => v_catid, v_catid => 0, v_subcatid => 0, v_totalcount => v_totalproduct);
  UPDATE tbl_main_category SET totalactive = v_totalproduct WHERE maincatid = v_catid AND status = 1 AND isdelete = 0;
  END IF;
  IF (v_oldmaincatid <> 0) THEN
  v_totalproduct := 0;
  SELECT v_totalcount INTO v_totalproduct FROM dbo.usp_totalproducts(v_maincatid => v_oldmaincatid, v_catid => 0, v_subcatid => 0, v_totalcount => v_totalproduct);
  UPDATE tbl_main_category SET totalactive = v_totalproduct WHERE maincatid = v_oldmaincatid AND status = 1 AND isdelete = 0;
  END IF;
  v_intresult := 3;
  -- COMMIT (removed)
  RETURN;
  END IF;
  IF (v_mode = 3) THEN
  IF EXISTS(SELECT 1 FROM product_subcategory WHERE catid = v_catid AND scatname = v_scatname) THEN
  v_intresult := 6;
  -- COMMIT (removed)
  RETURN;
  END IF;
  v_outputparam := 0;
  SELECT v_intresult INTO v_outputparam FROM dbo.usp_insert_alltypecategory_new(v_id => v_catid, v_value => v_scatname, v_type => 'CATEGORY', v_varresult => '', v_intresult => v_outputparam, v_imagename => '', v_imagesequence => v_sequence, v_hotlink => 0, v_catimgnamemobile => v_admincommission, v_admincharge => v_delieverycharges, v_delieverycharge => v_handlingcharges, v_handlingcharge => v_fixedfee);
  IF (v_outputparam = 0) THEN
  v_intresult := 0;
  -- ROLLBACK (removed)
  RETURN;
  END IF;
  INSERT INTO product_subcategory (scatname, scatdesc, scatactive, catid, scat_code) VALUES (v_scatname, v_scatdesc, v_scatactive, v_catid, dbo.REMOVESPACESANDSPECIALCHARS(v_scatname));
  v_intresult := 4;
  END IF;
  -- SET option (removed)
  -- COMMIT (removed)
END;
$$;


--
-- Name: usp_subcategorylist(integer, integer, character varying, character varying, character varying, integer, character varying, character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_subcategorylist(v_startrowindex integer DEFAULT 1, v_maxrows integer DEFAULT 10, v_searchfield character varying DEFAULT ''::character varying, v_searchvalue character varying DEFAULT ''::character varying, v_status character varying DEFAULT ''::character varying, v_totalcount integer DEFAULT 0, v_searchcategory character varying DEFAULT ''::character varying, v_searchsubcategory character varying DEFAULT ''::character varying) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_minindex int;
  v_maxindex int;
  v_query text;
BEGIN
  v_minindex := (v_startrowindex - 1) * v_maxrows + 1;
  v_maxindex := v_startrowindex * v_maxrows;
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp (rowNumber int,
SCATID bigint,
SCATNAME varchar(500),
SCATDESC varchar(500),
SCATACTIVE varchar(100),
CATNAME varchar(500)) ON COMMIT DROP;
  v_query := 'insert into #temp  select ROW_NUMBER() over (order by PS.SCATID desc) as rownumber,SCATID,
  isnull(SCATNAME,'''') as SCATNAME,isnull(SCATDESC,'''') as SCATDESC,(CASE SCATACTIVE WHEN 1 THEN ''Active'' ELSE ''Deactive'' END) AS SCATACTIVE,isnull(PC.CATNAME,'''') as CATNAME
   from PRODUCT_SUBCATEGORY PS   left join PRODUCT_CATEGORY PC  ON PC.CATID=PS.CATID where 1=1';
  v_query := v_query;
  IF (v_searchfield = 'SCATNAME') THEN
  v_query := v_query || ' and PS.SCATNAME like ''%' || v_searchvalue || '%''';
  END IF;
  IF (v_searchfield = 'CATNAME') THEN
  v_query := v_query || ' and PC.CATNAME like ''%' || v_searchvalue || '%''';
  END IF;
  IF (v_status <> '') THEN
  v_query := v_query || ' AND PS.SCATACTIVE = +CONVERT(VARCHAR(20),''' || v_status || ''') ';
  END IF;
  IF (v_searchsubcategory <> '') THEN
  v_searchsubcategory := REPLACE(v_searchsubcategory, '''', '''''');
  v_query := v_query || ('AND PS.SCATNAME=''' || v_searchsubcategory || '''');
  END IF;
  IF (v_searchcategory <> '') THEN
  v_searchcategory := REPLACE(v_searchcategory, '''', '''''');
  v_query := v_query || ('AND PC.CATNAME=''' || v_searchcategory || '''');
  END IF;
  EXECUTE v_query;
  RETURN QUERY SELECT * FROM tmp_temp WHERE rownumber BETWEEN v_minindex AND v_maxindex ORDER BY rownumber ASC NULLS FIRST;
  SELECT COUNT(rownumber) INTO v_totalcount FROM tmp_temp;
  DROP TABLE IF EXISTS tmp_temp;
  -- SET option (removed)
END;
$$;


--
-- Name: usp_submit_enquiry(character varying, character varying, character varying, text, character varying, text, character varying, character varying, character varying, character varying, character varying, character varying, integer, integer, integer, character varying, character varying, character varying, character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_submit_enquiry(v_name character varying DEFAULT ''::character varying, v_email character varying DEFAULT ''::character varying, v_subject character varying DEFAULT ''::character varying, v_message text DEFAULT ''::text, v_type character varying DEFAULT ''::character varying, v_replymsg text DEFAULT ''::text, v_mode character varying DEFAULT 'Get'::character varying, v_mobile character varying DEFAULT ''::character varying, v_strresult character varying DEFAULT ''::character varying, v_city character varying DEFAULT ''::character varying, v_state character varying DEFAULT ''::character varying, v_source character varying DEFAULT 'Customer Enquiry'::character varying, v_intresult integer DEFAULT 0, v_startrowindex integer DEFAULT 1, v_maxrows integer DEFAULT 100, v_searchfield character varying DEFAULT ''::character varying, v_searchvalue character varying DEFAULT ''::character varying, v_fromdate character varying DEFAULT ''::character varying, v_todate character varying DEFAULT ''::character varying) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_query text;
  v_minindex INT;
  v_maxindex INT;
BEGIN
  IF (v_mode = 'Add') THEN
  INSERT INTO tbl_enquiry (name, emailid, mobile, businessname, message, status, enqdate, type, source, city, state) VALUES (v_name, v_email, v_mobile, v_subject, v_message, 1, CURRENT_TIMESTAMP, v_type, v_source, v_city, v_state);
  v_strresult := 'ok';
  v_intresult := 1;
  END IF;
  IF (v_mode = 'Get') THEN
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp (RowNumber Int GENERATED BY DEFAULT AS IDENTITY,
	Id	int,
	Name	varchar(500),
	EmailId	varchar(500),
	Mobile	varchar(500),
	Subject	varchar(500),
	Message	text,
	EnqDate	varchar(50),
	Type Varchar(500),
	ShortMessage VarChar(500),
	Source VarChar(500),
	State varchar(50),
	City varchar(50),
	BusinessName varchar(50)) ON COMMIT DROP;
  v_query := '';
  v_minindex := (v_startrowindex - 1) * v_maxrows + 1;
  v_maxindex := v_startrowindex * v_maxrows;
  v_query := v_query || ('Insert Into #Temp Select Id,Name,EmailId, Mobile,Type as Subject ,Message,
			Convert(Varchar(15),EnqDate,106)As EnqDate,Type,(Case When Len(Message)>40 Then Substring(Message,1,40)+''...'' Else Message End) As ShortMessage,
			ISNULL(Source,'''') as Source,isnull(State,'''') as State,isnull(City,'''') as City,isnull(BusinessName,'''') as BusinessName  From Tbl_Enquiry where Status =1 ');
  IF (v_type <> '') THEN
  IF (v_type = '1') THEN
  v_query := v_query || (' And Type = ''Support'' ');
  END IF;
  IF (v_type = '2') THEN
  v_query := v_query || (' And Type = ''Sales'' ');
  END IF;
  IF (v_type = '3') THEN
  v_query := v_query || (' And Type = ''Complaint'' ');
  END IF;
  END IF;
  IF (v_email <> '') THEN
  v_query := v_query || (' And EmailId = ''' || v_email || ''' ');
  END IF;
  IF (v_mobile <> '') THEN
  v_query := v_query || (' And Mobile = ''' || v_mobile || ''' ');
  END IF;
  IF (v_source <> '0') THEN
  IF (v_source = '1') THEN
  v_query := v_query || (' And Source = ''Admin'' ');
  END IF;
  IF (v_source = '2') THEN
  v_query := v_query || (' And Source = ''Contact Us'' ');
  END IF;
  END IF;
  IF (v_fromdate <> '' AND v_todate <> '') THEN
  v_query := v_query || (' And  Convert(Varchar,EnqDate,110) Between ''' || CAST(TO_CHAR(v_fromdate, 'MM-DD-YYYY') AS VARCHAR(30)) || ''' And ''' || CAST(TO_CHAR(v_todate, 'MM-DD-YYYY') AS VARCHAR(30)) || ''' ');
  END IF;
  IF (v_fromdate <> '') THEN
  v_query := v_query || (' AND CONVERT(Varchar, EnqDate,110) = CONVERT(Varchar,''' || v_fromdate || ''',110) ');
  END IF;
  IF (v_todate <> '') THEN
  v_query := v_query || (' AND CONVERT(Varchar, EnqDate,110)  = CONVERT(Varchar,''' || v_todate || ''',110) ');
  END IF;
  IF (v_searchfield = 'Mobile') THEN
  v_query := v_query || ' AND Mobile= ''' || v_searchvalue || ''' ';
  END IF;
  IF (v_searchfield = 'EmailId') THEN
  v_query := v_query || ' AND EmailId = ''' || v_searchvalue || ''' ';
  END IF;
  IF (v_searchfield = 'Name') THEN
  v_query := v_query || ' AND Name= ''' || v_searchvalue || ''' ';
  END IF;
  IF (v_source <> '') THEN
  v_query := v_query || ' AND Source= ''' || v_source || ''' ';
  END IF;
  v_query := v_query || (' Order By ID Desc ');
  EXECUTE v_query;
  RETURN QUERY SELECT * FROM tmp_temp WHERE rownumber BETWEEN v_minindex AND v_maxindex;
  SELECT COUNT(rownumber) INTO v_intresult FROM tmp_temp;
  END IF;
  IF (0 <> 0) THEN
  v_strresult := 'Some Error occured';
  END IF;
END;
$$;


--
-- Name: usp_submitenquiry_merchant(character varying, character varying, character varying, text, character varying, text, character varying, character varying, character varying, character varying, character varying, integer, integer, integer, character varying, character varying, character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_submitenquiry_merchant(v_name character varying DEFAULT ''::character varying, v_email character varying DEFAULT ''::character varying, v_subject character varying DEFAULT ''::character varying, v_message text DEFAULT ''::text, v_type character varying DEFAULT ''::character varying, v_replymsg text DEFAULT ''::text, v_mode character varying DEFAULT ''::character varying, v_mobile character varying DEFAULT ''::character varying, v_strresult character varying DEFAULT ''::character varying, v_city character varying DEFAULT ''::character varying, v_state character varying DEFAULT ''::character varying, v_intresult integer DEFAULT 0, v_startrowindex integer DEFAULT 1, v_maxrows integer DEFAULT 100, v_fromdate character varying DEFAULT ''::character varying, v_todate character varying DEFAULT ''::character varying, v_source character varying DEFAULT 'Enquiry'::character varying) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_query text;
  v_minindex INT;
  v_maxindex INT;
BEGIN
  IF (v_mode = 'Add') THEN
  INSERT INTO tbl_enquiry_merchant (name, emailid, mobile, businessname, message, status, enqdate, type, source, city, state) VALUES (v_name, v_email, v_mobile, v_subject, v_message, 1, CURRENT_TIMESTAMP, v_type, v_source, v_city, v_state);
  v_strresult := 'ok';
  v_intresult := 1;
  END IF;
  IF (v_mode = 'Get') THEN
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp (RowNumber Int GENERATED BY DEFAULT AS IDENTITY,
	EId	int,
	Name	varchar(500),
	EmailId	varchar(500),
	Mobile	varchar(500),
	Subject	varchar(500),
	Message	text,
	EnqDate	varchar(50),
	Type Varchar(500),
	ShortMessage VarChar(80),
	Source VarChar(80)) ON COMMIT DROP;
  v_query := '';
  v_minindex := (v_startrowindex - 1) * v_maxrows + 1;
  v_maxindex := v_startrowindex * v_maxrows;
  v_query := v_query || ('Insert Into #Temp Select EId,Name,EmailId, Mobile,Subject,Message,
			Convert(Varchar(15),EnqDate,106)As EnqDate,Type,(Case When Len(Message)>40 Then Substring(Message,1,40)+''...'' Else Message End) As ShortMessage,
			ISNULL(Source,'''') as Source  From Tbl_Enquiry_Merchant where Status =1 ');
  IF (v_type <> '') THEN
  IF (v_type = '1') THEN
  v_query := v_query || (' And Type = ''Support'' ');
  END IF;
  IF (v_type = '2') THEN
  v_query := v_query || (' And Type = ''Sales'' ');
  END IF;
  IF (v_type = '3') THEN
  v_query := v_query || (' And Type = ''Complaint'' ');
  END IF;
  END IF;
  IF (v_email <> '') THEN
  v_query := v_query || (' And Emailid = ''' || v_email || ''' ');
  END IF;
  IF (v_mobile <> '') THEN
  v_query := v_query || (' And Mobile = ''' || v_mobile || ''' ');
  END IF;
  IF (v_source <> '0') THEN
  IF (v_source = '1') THEN
  v_query := v_query || (' And Source = ''Admin'' ');
  END IF;
  IF (v_source = '2') THEN
  v_query := v_query || (' And Source = ''Contact Us'' ');
  END IF;
  END IF;
  IF (v_fromdate <> '' AND v_todate <> '') THEN
  v_query := v_query || (' And  Convert(Varchar,EnqDate,110) Between ''' || CAST(TO_CHAR(v_fromdate, 'MM-DD-YYYY') AS VARCHAR(30)) || ''' And ''' || CAST(TO_CHAR(v_todate, 'MM-DD-YYYY') AS VARCHAR(30)) || ''' ');
  END IF;
  IF (v_fromdate <> '') THEN
  v_query := v_query || (' AND CONVERT(Varchar, EnqDate,110) >= CONVERT(Varchar,''' || v_fromdate || ''',110) ');
  END IF;
  IF (v_todate <> '') THEN
  v_query := v_query || (' AND CONVERT(Varchar, EnqDate,110)  <= CONVERT(Varchar,''' || v_todate || ''',110) ');
  END IF;
  v_query := v_query || (' Order By EID Desc ');
  EXECUTE v_query;
  RETURN QUERY SELECT * FROM tmp_temp WHERE rownumber BETWEEN v_startrowindex AND v_maxrows;
  RETURN QUERY SELECT COUNT(1) AS totalrows FROM tmp_temp;
  END IF;
  IF (0 <> 0) THEN
  v_strresult := 'Some Error occured';
  END IF;
END;
$$;


