--
-- Name: usp_subscription_approved(integer, integer, character varying, boolean, character varying, character varying, character varying, character varying, character varying, character varying, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_subscription_approved(v_startrowindex integer, v_maxrows integer, v_orderbyfield character varying, v_asc boolean, v_searchfield character varying, v_searchvalue character varying, v_cid character varying DEFAULT ''::character varying, v_fromdate character varying DEFAULT ''::character varying, v_todate character varying DEFAULT ''::character varying, v_mode character varying DEFAULT NULL::character varying, v_recordcount integer DEFAULT NULL::integer) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_regno bigint;
  v_sqlquery text;
BEGIN
  -- SET option (removed)
  v_sqlquery := '';
  IF (v_orderbyfield = '') THEN
  v_orderbyfield := 'tsd.subscriptiondate desc';
  END IF;
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp (rowNumber bigint,
active varchar(100),
companyname text,
loginID varchar(150),
remark varchar(300),
price numeric(19,4),
totalprice numeric(19,4),
paidamount numeric(19,4), 
depositedate date,
noofmonth int,
paymode varchar(50),
subscriptiondate date,
packagetype varchar(50),
sdid bigint,
countryName varchar(100),
CID int,
cityName varchar(100),
currencysymbol varchar(400)) ON COMMIT DROP;
  v_sqlquery := ' insert into #temp select  ROW_NUMBER() over(order by ' || v_orderbyfield || ') as rownumber,
               (case isnull(tsd.status,0) when 1 then ''active'' when 0 then ''deactive'' end ) as active,
			   pm.companyname,pl.LoginId,tsd.remark,tsd.price,tsd.totalprice,tsd.paidamount,tsd.depositedate,tsd.noofmonth,tsd.paymode,
			   convert(varchar(50),tsd.subscriptiondate,106) as subscriptiondate,tsd.packagetype,tsd.sdid,
			   (case when C.countryName=''UNITED STATES'' then ''US'' when C.countryName=''UNITED KINGDOM'' then ''UK'' else  C.countryName end  ) as countryName,
			   c.CID,ct.cityName,c.currencycode as currencysymbol from tbl_subscription_details tsd inner join  portal_master pm on  pm.pmid=tsd.pmid 
			   inner join Portal_Login pl on pm.pmid=pl.PMID inner join  COUNTRY c on pm.cid=c.CID inner join city ct on pm.ctid=ct.CTID
			   where isnull(tsd.status,0)=''' || v_mode || '''  and tsd.isdeleted=0';
  IF (v_cid <> '') THEN
  v_sqlquery := v_sqlquery || ' and ('',''+convert(varchar(50),C.cid)+'','') like  ''%,' || '' || CAST(v_cid AS text) || '' || ',%''';
  END IF;
  IF (v_fromdate <> '') THEN
  IF (v_todate <> '') THEN
  IF (v_fromdate <> '' AND v_todate <> '') THEN
  v_sqlquery := v_sqlquery || ' and convert(varchar(50), tsd.subscriptiondate,103)  between  convert(varchar(50),''' || v_fromdate || ''',103)  
			                             and convert(varchar(50),''' || v_todate || ''',103)';
  END IF;
  END IF;
  END IF;
  IF (v_searchfield = '1') THEN
  v_sqlquery := v_sqlquery || ' and pl.LoginId like ''%' || v_searchvalue || '%''';
  END IF;
  IF (v_searchfield = '2') THEN
  v_sqlquery := v_sqlquery || ' and pm.companyname like ''%' || v_searchvalue || '%''';
  END IF;
  EXECUTE v_sqlquery;
  SELECT COUNT(*) INTO v_recordcount FROM tmp_temp;
  RETURN QUERY SELECT * FROM tmp_temp WHERE rownumber BETWEEN v_startrowindex AND v_maxrows;
  DROP TABLE IF EXISTS tmp_temp;
  RETURN QUERY SELECT v_recordcount AS recordcount;
  -- SET option (removed)
END;
$$;


--
-- Name: usp_subscription_wallet_fund_history(integer, integer, integer, character varying, boolean, character varying, character varying, integer, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_subscription_wallet_fund_history(v_startrowindex integer, v_maxrows integer, v_plid integer DEFAULT 0, v_orderbyfield character varying DEFAULT NULL::character varying, v_asc boolean DEFAULT NULL::boolean, v_searchfield character varying DEFAULT NULL::character varying, v_searchvalue character varying DEFAULT NULL::character varying, v_mode integer DEFAULT NULL::integer, v_recordcount integer DEFAULT NULL::integer) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_regno bigint;
  v_sqlquery text;
BEGIN
  -- SET option (removed)
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp (rowNumber int,
SWHID bigint,
PLID bigint,
Amount varchar(500),
CrDrType varchar(200),
Type varchar(20),
Remark varchar(200),
Date varchar(50)) ON COMMIT DROP;
  v_sqlquery := '';
  v_sqlquery := 'insert into #temp select  ROW_NUMBER() over(order by SWHID desc) as rownumber,SWHID,PLID,isnull(Amount,0) as Amount,CrDrType,Type,Remark,
(CASE WHEN Date IS not NULL THEN convert(varchar(10),Date, 105) ELSE '' ''  END) AS  Date from tbl_Subscription_Wallet_History where plid=' || CAST(v_plid AS VARCHAR(20));
  EXECUTE v_sqlquery;
  SELECT COUNT(*) INTO v_recordcount FROM tmp_temp;
  RETURN QUERY SELECT * FROM tmp_temp WHERE rownumber BETWEEN v_startrowindex AND v_maxrows;
  DROP TABLE IF EXISTS tmp_temp;
  RETURN QUERY SELECT v_recordcount AS recordcount;
  -- SET option (removed)
END;
$$;


--
-- Name: usp_subscriptionbyadmin(numeric, integer, text, text, integer, text, text, text, text, text, text, text, text, text, text, text, integer, text, numeric, integer, character varying, character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_subscriptionbyadmin(v_totalpayableamount numeric DEFAULT 0, v_paymentmode integer DEFAULT 0, v_modename text DEFAULT ''::text, v_commentorremark text DEFAULT ''::text, v_regno integer DEFAULT 0, v_imagename text DEFAULT ''::text, v_bankname text DEFAULT ''::text, v_branchname text DEFAULT ''::text, v_referencedate text DEFAULT ''::text, v_referencenumber text DEFAULT ''::text, v_walletid text DEFAULT ''::text, v_transactionpassword text DEFAULT ''::text, v_googleauthenticationcode text DEFAULT ''::text, v_allpackageid text DEFAULT ''::text, v_allpackagetype text DEFAULT ''::text, v_allpackageamount text DEFAULT ''::text, v_plid integer DEFAULT 0, v_allpackagename text DEFAULT ''::text, v_processingfee numeric DEFAULT 0.00, INOUT v_intresult integer DEFAULT 0, INOUT v_tasmid character varying DEFAULT ''::character varying, INOUT v_stroutputresult character varying DEFAULT ''::character varying) RETURNS record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_transaction_id VARCHAR(10);
  v_lower BIGINT;
  v_upper BIGINT;
  v_isstop Int;
  v_countformultiplepurchase BigInt;
  v_service_tax_per DECIMAL(18,8);
  v_service_tax_amt DECIMAL(18,8);
  v_with_out_tax_amount DECIMAL(18,8);
BEGIN
  -- BEGIN TRAN (removed)
  BEGIN
  v_transaction_id := '';
  v_isstop := 0;
  WHILE (v_isstop = 0) LOOP
  SELECT CAST(RANDOM() * 9999999999 AS DECIMAL(10, 0)) INTO v_transaction_id;
  IF EXISTS(SELECT 1 FROM tbl_allsubscriptionmaster WHERE transaction_id = v_transaction_id AND status = 1) THEN
  v_isstop := 0;
  ELSE
  v_isstop := 1;
  END IF;
  END LOOP;
  v_countformultiplepurchase := 0;
  SELECT COUNT(1) INTO v_countformultiplepurchase FROM tbl_allsubscriptionmaster WHERE '~' || allpackagetype || '~' LIKE '%~1~%' AND '~' || allpackageid || '~' LIKE '%~' || CAST(v_allpackageid AS text) || '~%' AND plid = v_plid AND COALESCE(isapproved, 0) <> 2;
  IF (v_countformultiplepurchase > 0) THEN
  v_stroutputresult := 'AlreadyPurchased';
  v_intresult := 0;
  -- ROLLBACK (removed)
  RETURN;
  END IF;
  IF (v_referencenumber <> '') THEN
  IF EXISTS(SELECT 1 FROM tbl_allsubscriptionmaster WHERE referencenumber = v_referencenumber AND status = 1 AND isapproved <> 2) THEN
  v_stroutputresult := 'Reference Number Already Used.';
  v_intresult := 0;
  -- ROLLBACK (removed)
  RETURN;
  END IF;
  END IF;
  v_service_tax_per := 0.00;
  v_service_tax_amt := 0.00;
  v_with_out_tax_amount := 0.00;
  v_with_out_tax_amount := v_totalpayableamount;
  SELECT limits INTO v_service_tax_per FROM dbo.settings WHERE caption = 'IsTaxApplicableOnPackagePrice' AND active = 1;
  v_totalpayableamount := 0;
  v_service_tax_amt := COALESCE(v_with_out_tax_amount, 0) * COALESCE(v_service_tax_per, 0);
  IF (v_service_tax_amt > 0) THEN
  v_service_tax_amt := v_service_tax_amt / 100;
  ELSE
  v_service_tax_amt := 0;
  END IF;
  v_totalpayableamount := v_with_out_tax_amount + v_service_tax_amt;
  INSERT INTO tbl_allsubscriptionmaster (totalpayableamount, paymentmode, modename, commentorremark, regno, imagename, bankname, branchname, referencedate, referencenumber, walletid, transactionpassword, googleauthenticationcode, allpackageid, allpackagetype, allpackageamount, puchasedate, isactive, status, plid, allpackagename, transaction_id, service_tax_per, service_tax, with_out_tax_amount, invoice_no, processingfee) VALUES (v_totalpayableamount, v_paymentmode, (CASE WHEN v_paymentmode = 1 THEN 'Credit Card' WHEN v_paymentmode = 2 THEN 'Debit Card' WHEN v_paymentmode = 3 THEN 'NEFT' WHEN v_paymentmode = 4 THEN 'Atm Transfer' WHEN v_paymentmode = 5 THEN 'POS Machine' WHEN v_paymentmode = 6 THEN 'IMPS' WHEN v_paymentmode = 7 THEN 'Cheque' WHEN v_paymentmode = 8 THEN 'DD' WHEN v_paymentmode = 9 THEN 'Cash' WHEN v_paymentmode = 10 THEN 'On Credit' ELSE 'N/A' END), v_commentorremark, v_regno, v_imagename, v_bankname, v_branchname, v_referencedate, v_referencenumber, v_walletid, v_transactionpassword, v_googleauthenticationcode, v_allpackageid, v_allpackagetype, v_allpackageamount, dbo.FUN_GETCURRENTDATE(), 1, 1, v_plid, v_allpackagename, v_transaction_id, COALESCE(v_service_tax_per, 0.00), COALESCE(v_service_tax_amt, 0), COALESCE(v_with_out_tax_amount, 0), '', v_processingfee);
  IF (0 = 0) THEN
  v_stroutputresult := 'Subscription Purchased Successfully.';
  SELECT IDENT_CURRENT('TBL_ALLSUBSCRIPTIONMASTER') INTO v_tasmid;
  v_intresult := 1;
  -- COMMIT (removed)
  RETURN;
  ELSE
  v_stroutputresult := 'Some Error Occur While Subscribing.';
  v_intresult := 0;
  -- ROLLBACK (removed)
  RETURN;
  END IF;
  EXCEPTION WHEN OTHERS THEN
  v_stroutputresult := 'Some Error Occur While Subscribing.';
  v_intresult := 0;
  -- ROLLBACK (removed)
  END;
  -- COMMIT (removed)
END;
$$;


--
-- Name: usp_subscriptionlistsmsemailtraffic(integer, integer, character varying, character varying, character varying, integer, integer, integer, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_subscriptionlistsmsemailtraffic(v_mode integer DEFAULT 1, v_isgiven integer DEFAULT 2, v_requestedby character varying DEFAULT ''::character varying, v_fromdate character varying DEFAULT ''::character varying, v_todate character varying DEFAULT ''::character varying, v_pageno integer DEFAULT 1, v_pagesize integer DEFAULT 100, v_id integer DEFAULT 0, v_intresult integer DEFAULT 0) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_query text;
  v_minindex INT;
  v_maxindex INT;
  v_noofrec INT;
  v_diff INT;
BEGIN
  v_minindex := 0;
  v_maxindex := 0;
  v_noofrec := 0;
  v_diff := 0;
  v_minindex := ((v_pageno - 1) * v_pagesize) + 1;
  v_maxindex := (v_pageno * v_pagesize);
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp (RowNumber INT GENERATED BY DEFAULT AS IDENTITY,
		ID INT,
		PurchasedDate varchar(100),
		LOGINID VarChar(500),
		PackageName varchar(100),
		TotalNumber varchar(100),
		Status Varchar(100),
		ActivationDate Varchar(100),
		ActivateTillDate VarChar(100)) ON COMMIT DROP;
  IF (v_mode = 1) THEN
  v_query := ' INSERT INTO #TEMP SELECT TUSPMID,CONVERT(VARCHAR(11),PURCHASEDDATE,106) AS PurchasedDate,
	PL.LOGINID,TSPM.PACKAGENAME,IsNull(TUSPM.NoOfSms,0) As TotalNumber,
	(Case When ISGIVEN = 1 Then ''Yes'' Else ''No'' End) As Status,
	CONVERT(VARCHAR(11),ActivationDate,106),CONVERT(VARCHAR(11),ActivateTillDate,106)
	FROM Tbl_UserSMSPackMaster TUSPM INNER JOIN 
	Tbl_SMSPackMaster TSPM	ON TUSPM.TSPMID=TSPM.TSPMID INNER JOIN 
	Portal_Login Pl On Pl.Plid=TUSPM.PLID  WHERE  TUSPMID>0 ';
  IF (v_isgiven <> 2) THEN
  v_query := v_query || (' AND ISGIVEN = ' || CAST(v_isgiven AS VARCHAR(2)) || ' ');
  END IF;
  IF (v_requestedby <> '') THEN
  v_query := v_query || (' AND PL.LOGINID LIKE ''%' || v_requestedby || '%'' ');
  END IF;
  IF (v_fromdate <> '' OR v_todate <> '') THEN
  IF (v_fromdate <> '') THEN
  v_query := v_query || (' AND CONVERT(DATE,PURCHASEDDATE,103) >= CONVERT(DATE,''' || v_fromdate || ''',103) ');
  END IF;
  IF (v_todate <> '') THEN
  v_query := v_query || (' AND CONVERT(DATE,PURCHASEDDATE,103) <= CONVERT(DATE,''' || v_todate || ''',103) ');
  END IF;
  ELSE
  IF (v_fromdate <> '' AND v_todate <> '') THEN
  v_query := v_query || ('  AND CONVERT(DATE,PURCHASEDDATE,103) BETWEEN CONVERT(DATE,''' || v_fromdate || ''',103) AND CONVERT(DATE,''' || v_todate || ''',103) ');
  END IF;
  END IF;
  END IF;
  IF (v_mode = 2) THEN
  UPDATE tbl_usersmspackmaster SET isgiven = (CASE WHEN isgiven = 0 THEN 1 WHEN isgiven = 1 THEN 0 END) WHERE tuspmid = v_id;
  v_intresult := 1;
  END IF;
  IF (v_mode = 3) THEN
  v_query := ' INSERT INTO #TEMP  SELECT TUEPMID,CONVERT(VARCHAR(11),PurchasedDate,106) AS PurchasedDate,
	PL.LOGINID,TEPM.PackageName,IsNull(TEPM.NoOfEmail,0) As TotalNumber,
	(Case When ISGIVEN = 1 Then ''Yes'' Else ''No'' End) As Status,
	CONVERT(VARCHAR(11),ActivationDate,106),CONVERT(VARCHAR(11),ActivateTillDate,106)
	FROM Tbl_UserEmailPackMaster TUEPM INNER JOIN 
	TBL_EMAILPACKMASTER TEPM ON TUEPM.TEPMID=TEPM.TEPMID INNER JOIN 
	Portal_Login Pl On Pl.Plid=TUEPM.PLID  WHERE  TUEPMID > 0 ';
  IF (v_isgiven <> 2) THEN
  v_query := v_query || (' AND ISGIVEN = ' || CAST(v_isgiven AS VARCHAR(2)) || ' ');
  END IF;
  IF (v_requestedby <> '') THEN
  v_query := v_query || (' AND PL.LOGINID LIKE ''%' || v_requestedby || '%'' ');
  END IF;
  IF (v_fromdate <> '' OR v_todate <> '') THEN
  IF (v_fromdate <> '') THEN
  v_query := v_query || (' AND CONVERT(DATE,PURCHASEDDATE,103) >= CONVERT(DATE,''' || v_fromdate || ''',103) ');
  END IF;
  IF (v_todate <> '') THEN
  v_query := v_query || (' AND CONVERT(DATE,PURCHASEDDATE,103) <= CONVERT(DATE,''' || v_todate || ''',103) ');
  END IF;
  ELSE
  IF (v_fromdate <> '' AND v_todate <> '') THEN
  v_query := v_query || (' AND CONVERT(DATE,PURCHASEDDATE,103) BETWEEN CONVERT(DATE,''' || v_fromdate || ''',103) 


AND CONVERT(DATE,''' || v_todate || ''',103) ');
  END IF;
  END IF;
  END IF;
  IF (v_mode = 4) THEN
  UPDATE tbl_useremailpackmaster SET isgiven = (CASE WHEN isgiven = 0 THEN 1 END) WHERE tuepmid = v_id;
  v_intresult := 1;
  END IF;
  IF (v_mode = 5) THEN
  v_query := ' INSERT INTO #TEMP  Select TUTBID ,Convert(Varchar(12),PurchasedDate,106) As PurchasedDate,PL.LOGINID,TTB.PackageName,
	IsNull(TTB.NoOfHits,0) as TotalNumber,(Case When ISGIVEN = 1 Then ''Yes'' Else ''No'' End) As Status,
	Convert(Varchar(12),ActivationDate,106) As ActivationDate,Convert(Varchar(12),ActivateTillDate,106) As ActivateTillDate
	From Tbl_UserTrafficBooster TB Inner Join PORTAL_LOGIN PL on TB.PLid = PL.PLID
	Inner Join Tbl_TrafficBooster TTB On TTB.TTBID=TB.TTBID
	Where Pl.ACTIVE = 1 ';
  IF (v_isgiven <> 2) THEN
  v_query := v_query || (' AND ISGIVEN = ' || CAST(v_isgiven AS VARCHAR(2)) || ' ');
  END IF;
  IF (v_requestedby <> '') THEN
  v_query := v_query || (' AND PL.LOGINID LIKE ''%' || v_requestedby || '%'' ');
  END IF;
  IF (v_fromdate <> '' OR v_todate <> '') THEN
  IF (v_fromdate <> '') THEN
  v_query := v_query || (' AND CONVERT(DATE,PURCHASEDDATE,103) >= CONVERT(DATE,''' || v_fromdate || ''',103) ');
  END IF;
  IF (v_todate <> '') THEN
  v_query := v_query || (' AND CONVERT(DATE,PURCHASEDDATE,103) <= CONVERT(DATE,''' || v_todate || ''',103) ');
  END IF;
  ELSE
  IF (v_fromdate <> '' AND v_todate <> '') THEN
  v_query := v_query || (' AND CONVERT(DATE,PURCHASEDDATE,103) BETWEEN CONVERT(DATE,''' || v_fromdate || ''',103)






	AND CONVERT(DATE,''' || v_todate || ''',103) ');
  END IF;
  END IF;
  END IF;
  EXECUTE v_query;
  RETURN QUERY SELECT * FROM tmp_temp WHERE rownumber BETWEEN v_minindex AND v_maxindex;
  SELECT COUNT(1) INTO v_noofrec FROM tmp_temp;
  SELECT COALESCE(COUNT(1), 0) INTO v_intresult FROM tmp_temp;
  SELECT (v_noofrec - ((v_noofrec / v_pagesize) * v_pagesize)) INTO v_diff;
  IF (v_noofrec > 0) THEN
  IF (v_diff > 0) THEN
  RETURN QUERY SELECT ((v_noofrec / v_pagesize) + 1) AS pages;
  RETURN QUERY SELECT v_noofrec AS totalrows;
  ELSE
  RETURN QUERY SELECT (v_noofrec / v_pagesize) AS pages;
  RETURN QUERY SELECT v_noofrec AS totalrows;
  END IF;
  ELSE
  RETURN QUERY SELECT 1 AS pages;
  RETURN QUERY SELECT v_noofrec AS totalrows;
  END IF;
  DROP TABLE IF EXISTS tmp_temp;
END;
$$;


--
-- Name: usp_subscriptionlogin(character varying, character varying, character varying, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_subscriptionlogin(v_emailid character varying DEFAULT ''::character varying, v_ipcontry character varying DEFAULT ''::character varying, v_ipaddress character varying DEFAULT ''::character varying, INOUT v_intresult integer DEFAULT NULL::integer) RETURNS integer
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_smid bigint;
BEGIN
  -- SET option (removed)
  IF EXISTS(SELECT emailid FROM subscription_master WHERE active = 1 AND isdeleted = 0 AND emailid = v_emailid) THEN
  v_intresult := 1;
  RAISE NOTICE '%', 1;
  RETURN;
  END IF;
  IF EXISTS(SELECT emailid FROM subscription_master WHERE active = 0 AND isdeleted = 0 AND emailid = v_emailid) THEN
  v_intresult := 3;
  RAISE NOTICE '%', 3;
  RETURN;
  END IF;
  IF EXISTS(SELECT emailid FROM subscription_master WHERE active = 0 AND isdeleted = 1 AND emailid = v_emailid) THEN
  SELECT smid INTO v_smid FROM subscription_master WHERE RTRIM(LTRIM(emailid)) = RTRIM(LTRIM(v_emailid)) AND active = 0 AND isdeleted = 1;
  v_intresult := 4;
  UPDATE subscription_master SET subscriptiondate = CURRENT_TIMESTAMP, isdeleted = 0, active = 1 WHERE smid = v_smid;
  RAISE NOTICE '%', 4;
  RETURN;
  ELSE
  v_intresult := 2;
  INSERT INTO subscription_master (emailid, subscriptiondate, active, isdeleted, country_name, ipaddress) VALUES (v_emailid, CURRENT_TIMESTAMP, 0, 0, v_ipcontry, v_ipaddress);
  RAISE NOTICE '%', 2;
  RETURN;
  END IF;
  IF (0 <> 0) THEN
  v_intresult := 5;
  RETURN;
  END IF;
  -- SET option (removed)
END;
$$;


--
-- Name: usp_subscriptionmaster(integer, character varying, character varying, integer, integer, bigint, integer, bigint, integer, bigint, integer, bigint, integer, integer, numeric, integer, integer, text, integer, integer, integer, integer, numeric, numeric, integer, integer, bigint, numeric); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_subscriptionmaster(v_mode integer DEFAULT 4, v_subscriptionheading character varying DEFAULT ''::character varying, v_subscriptiondetails character varying DEFAULT ''::character varying, v_daysforactivation integer DEFAULT 0, v_issmslimits integer DEFAULT 0, v_smslimit bigint DEFAULT 0, v_isemaillimit integer DEFAULT 0, v_emaillimit bigint DEFAULT 0, v_iswhatsapplimit integer DEFAULT 0, v_whatsapplimit bigint DEFAULT 0, v_iswebsitelimit integer DEFAULT 0, v_websitelimit bigint DEFAULT 0, v_isleadslandingpagelimit integer DEFAULT 0, v_leadslandingpagelimit integer DEFAULT 0, v_price numeric DEFAULT 0.00, v_isdiscountapplicable integer DEFAULT 0, v_istrialsubscription integer DEFAULT 0, v_commentorremark text DEFAULT ''::text, v_isactive integer DEFAULT 0, v_intresult integer DEFAULT 0, v_tsmid integer DEFAULT 1, v_ttsid integer DEFAULT 0, v_discount numeric DEFAULT 0.00, v_netpayable numeric DEFAULT 0.00, v_noofcities integer DEFAULT 0, v_noofkeywords integer DEFAULT 0, v_noofhits bigint DEFAULT 0, v_bvpercentage numeric DEFAULT 0.00) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF (v_issmslimits = 0) THEN
  v_smslimit := 999999;
  END IF;
  IF (v_isemaillimit = 0) THEN
  v_emaillimit := 999999;
  END IF;
  IF (v_iswhatsapplimit = 0) THEN
  v_whatsapplimit := 999999;
  END IF;
  IF (v_iswebsitelimit = 0) THEN
  v_websitelimit := 999999;
  END IF;
  IF (v_isleadslandingpagelimit = 0) THEN
  v_leadslandingpagelimit := 999999;
  END IF;
  IF (v_mode = 1) THEN
  RETURN QUERY SELECT ROW_NUMBER() OVER (ORDER BY tsmid NULLS FIRST) AS rownumber, tsmid, subscriptionheading, subscriptiondetails, noofdaysforactivation, issmslimits, noofsms, isemaillimits, noofemail, iswhatsuplimits, noofwhatsupmessage, isnoofwebsitelimits, noofwebsiteselection, isleadlandingpagelimits, noofleadlandingpage, price, isdiscountapplicable, commentorremark, discount, netpayable, ts.name AS trafficsource, (CASE WHEN tsm.status = 1 THEN 'Active' ELSE 'Deactive' END) AS status, istrailsubscription, COALESCE(noofcities, 0) AS noofcities, COALESCE(noofkeywords, 0) AS noofkeywords, COALESCE(noofhits, 0) AS noofhits, bvpercentage FROM tbl_subscriptionmaster AS tsm INNER JOIN tbl_trafficsource AS ts ON ts.ttsid = tsm.ttsid;
  v_intresult := 1;
  END IF;
  IF (v_mode = 2) THEN
  INSERT INTO tbl_subscriptionmaster (subscriptionheading, subscriptiondetails, noofdaysforactivation, issmslimits, noofsms, isemaillimits, noofemail, iswhatsuplimits, noofwhatsupmessage, isnoofwebsitelimits, noofwebsiteselection, isleadlandingpagelimits, noofleadlandingpage, price, isdiscountapplicable, commentorremark, status, istrailsubscription, isactive, ttsid, discount, netpayable, noofcities, noofkeywords, noofhits, bvpercentage) VALUES (v_subscriptionheading, v_subscriptiondetails, v_daysforactivation, v_issmslimits, v_smslimit, v_isemaillimit, v_emaillimit, v_iswhatsapplimit, v_whatsapplimit, v_iswebsitelimit, v_websitelimit, v_isleadslandingpagelimit, v_leadslandingpagelimit, v_price, v_isdiscountapplicable, v_commentorremark, v_isactive, v_istrialsubscription, 1, v_ttsid, v_discount, v_netpayable, v_noofcities, v_noofkeywords, v_noofhits, v_bvpercentage);
  v_intresult := 2;
  END IF;
  IF (v_mode = 3) THEN
  UPDATE tbl_subscriptionmaster SET subscriptionheading = v_subscriptionheading, subscriptiondetails = v_subscriptiondetails, noofdaysforactivation = v_daysforactivation, issmslimits = v_issmslimits, noofsms = v_smslimit, isemaillimits = v_isemaillimit, noofemail = v_emaillimit, iswhatsuplimits = v_iswhatsapplimit, noofwhatsupmessage = v_whatsapplimit, isnoofwebsitelimits = v_iswebsitelimit, noofwebsiteselection = v_websitelimit, isleadlandingpagelimits = v_isleadslandingpagelimit, noofleadlandingpage = v_leadslandingpagelimit, price = v_price, isdiscountapplicable = v_isdiscountapplicable, commentorremark = v_commentorremark, status = v_isactive, istrailsubscription = v_istrialsubscription, ttsid = v_ttsid, discount = v_discount, netpayable = v_netpayable, noofcities = v_noofcities, noofkeywords = v_noofkeywords, noofhits = v_noofhits, bvpercentage = v_bvpercentage WHERE tsmid = v_tsmid;
  v_intresult := 3;
  END IF;
  IF (v_mode = 4) THEN
  RETURN QUERY SELECT ROW_NUMBER() OVER (ORDER BY tsmid NULLS FIRST) AS rownumber, tsmid, subscriptionheading, subscriptiondetails, noofdaysforactivation, issmslimits, noofsms, isemaillimits, noofemail, iswhatsuplimits, noofwhatsupmessage, isnoofwebsitelimits, noofwebsiteselection, isleadlandingpagelimits, noofleadlandingpage, price, isdiscountapplicable, commentorremark, discount, netpayable, status, istrailsubscription, ttsid, COALESCE(noofcities, 0) AS noofcities, COALESCE(noofkeywords, 0) AS noofkeywords, COALESCE(noofhits, 0) AS noofhits, bvpercentage FROM tbl_subscriptionmaster WHERE tsmid = v_tsmid;
  v_intresult := 1;
  END IF;
  IF (0 <> 0) THEN
  v_intresult := 0;
  RETURN;
  END IF;
END;
$$;


--
-- Name: usp_subscriptionnow(bigint, text, text, text, text, numeric, integer, character varying, numeric, text, date, date, character varying, character varying, character varying, character varying, numeric, character varying, character varying, character varying, character varying, character varying, character varying, character varying, character varying, text, character varying, character varying, character varying, character varying, numeric, integer, character varying, character varying, character varying); Type: FUNCTION; Schema: dbo; Owner: -
