CREATE FUNCTION dbo.usp_subscriptionnow(v_pmid bigint DEFAULT 0, v_catid text DEFAULT ''::text, v_ctid text DEFAULT ''::text, v_aid text DEFAULT ''::text, v_keyid text DEFAULT ''::text, v_totalprice numeric DEFAULT 0, v_noofmonth integer DEFAULT 1, v_paymode character varying DEFAULT ''::character varying, v_paidamount numeric DEFAULT 0, v_remarks text DEFAULT NULL::text, v_depositdate date DEFAULT NULL::date, v_checkdate date DEFAULT NULL::date, v_checknumber character varying DEFAULT ''::character varying, v_bankname character varying DEFAULT ''::character varying, v_branchname character varying DEFAULT ''::character varying, v_accountnumber character varying DEFAULT ''::character varying, v_checkamount numeric DEFAULT 0, v_memberid character varying DEFAULT ''::character varying, v_password character varying DEFAULT ''::character varying, v_couponno character varying DEFAULT ''::character varying, v_w_accountname character varying DEFAULT ''::character varying, v_w_accountno character varying DEFAULT ''::character varying, v_w_bankname character varying DEFAULT ''::character varying, v_w_transid character varying DEFAULT ''::character varying, v_w_transdate character varying DEFAULT ''::character varying, v_w_remark text DEFAULT ''::text, v_w_receipt character varying DEFAULT ''::character varying, v_filename character varying DEFAULT ''::character varying, v_sdidforupdate character varying DEFAULT ''::character varying, v_mode character varying DEFAULT ''::character varying, v_ewalateamt numeric DEFAULT 0, v_ewalatetype integer DEFAULT 0, v_loginid_subs character varying DEFAULT ''::character varying, v_password_subs character varying DEFAULT ''::character varying, INOUT v_strresult character varying DEFAULT NULL::character varying) RETURNS character varying
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_cid INT;
  v_plid BIGINT;
  v_amount numeric(19,4);
  v_dramount numeric(19,4);
  v_sdid BIGINT;
  v_finalprice numeric(19,4);
  v_coupon_cid INT;
  v_coupon_amount numeric(19,4);
  v_paybleamount numeric(19,4);
  v_transid VARCHAR(100);
  v_totalcategory text;
  v_paidusercid INT;
BEGIN
  -- BEGIN TRAN (removed)
  v_finalprice := 0;
  v_paybleamount := 0;
  v_paidusercid := 0;
  SELECT cid INTO v_cid FROM portal_login WHERE pmid = v_pmid;
  SELECT CAST(ROUND(CAST(((99999 - 11111 - 1) * RANDOM() + 11111) AS DECIMAL), 0) AS VARCHAR(50)) + CAST(ROUND(CAST(((99999 - 11111 - 1) * RANDOM() + 11111) AS DECIMAL), 0) AS VARCHAR(50)) INTO v_transid;
  v_finalprice := v_totalprice;
  v_paybleamount := v_finalprice;
  IF (v_paymode = 'ewallet') THEN
  v_ewalateamt := v_finalprice;
  IF NOT EXISTS(SELECT plid FROM portal_login WHERE pmid = v_pmid AND password = v_password) THEN
  v_strresult := 'error^' || 'InvalidLoginID';
  -- COMMIT (removed)
  RETURN;
  END IF;
  SELECT plid INTO v_plid FROM portal_login WHERE pmid = v_pmid;
  SELECT COALESCE(cid, 0) INTO v_paidusercid FROM portal_login WHERE plid = v_plid;
  IF NOT EXISTS(SELECT 1 FROM tbl_membersubscriptionaccount WHERE CURRENT_TIMESTAMP BETWEEN activationdate AND tilldate AND plid = v_plid AND isactive = 1) THEN
  v_strresult := 'error^' || 'NotSubscribed';
  -- COMMIT (removed)
  RETURN;
  END IF;
  SELECT COALESCE(amount, 0), COALESCE(dramount, 0) INTO v_amount, v_dramount FROM ewallet WHERE plid = v_plid;
  INSERT INTO tbl_subscription_details (pmid, catid, cid, ctid, aid, status, keyid, price, noofmonth, totalprice, packagetype, subscriptiondate, paymode, paidamount, remark, depositedate, qpaymemberid, qpaymemberpassword, couponno, filenames, transid, ewalateamt, fromplid) VALUES (v_pmid, v_catid, v_cid, v_ctid, v_aid, 1, v_keyid, v_totalprice, v_noofmonth, v_finalprice, '', dbo.FUN_GETCURRENTDATE(), v_paymode, v_paidamount, v_remarks, v_depositdate, v_memberid, v_password, v_couponno, v_filename, v_transid, v_ewalateamt, v_plid);
  SELECT MAX(sdid) INTO v_sdid FROM tbl_subscription_details WHERE pmid = v_pmid;
  v_strresult := 'success^' || 'Business subscription has been activated successfully.';
  END IF;
  IF (v_mode = 'update') THEN
  UPDATE tbl_subscription_details SET sdidforupdate = v_sdidforupdate WHERE sdid = v_sdid;
  UPDATE portal_master SET expirydate = dbo.FUN_GETCURRENTDATE() WHERE pmid = (SELECT pmid FROM tbl_subscription_details WHERE sdid = v_sdidforupdate);
  END IF;
  IF 0 > 0 THEN
  v_strresult := 'error^error';
  -- ROLLBACK (removed)
  RETURN;
  END IF;
  -- COMMIT (removed)
END;
$$;


