-- Name: usp_subscriptionnow1(bigint, text, text, text, text, numeric, integer, character varying, numeric, text, date, date, character varying, character varying, character varying, character varying, numeric, character varying, character varying, character varying, character varying, character varying, character varying, character varying, character varying, text, character varying, character varying, character varying, character varying, character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_subscriptionnow1(v_pmid bigint DEFAULT 0, v_catid text DEFAULT ''::text, v_ctid text DEFAULT ''::text, v_aid text DEFAULT ''::text, v_keyid text DEFAULT ''::text, v_totalprice numeric DEFAULT 0, v_noofmonth integer DEFAULT 1, v_paymode character varying DEFAULT ''::character varying, v_paidamount numeric DEFAULT 0, v_remarks text DEFAULT NULL::text, v_depositdate date DEFAULT NULL::date, v_checkdate date DEFAULT NULL::date, v_checknumber character varying DEFAULT ''::character varying, v_bankname character varying DEFAULT ''::character varying, v_branchname character varying DEFAULT ''::character varying, v_accountnumber character varying DEFAULT ''::character varying, v_checkamount numeric DEFAULT 0, v_memberid character varying DEFAULT ''::character varying, v_password character varying DEFAULT ''::character varying, v_couponno character varying DEFAULT ''::character varying, v_w_accountname character varying DEFAULT ''::character varying, v_w_accountno character varying DEFAULT ''::character varying, v_w_bankname character varying DEFAULT ''::character varying, v_w_transid character varying DEFAULT ''::character varying, v_w_transdate character varying DEFAULT ''::character varying, v_w_remark text DEFAULT ''::text, v_w_receipt character varying DEFAULT ''::character varying, v_filename character varying DEFAULT ''::character varying, v_sdidforupdate character varying DEFAULT ''::character varying, v_mode character varying DEFAULT ''::character varying, INOUT v_strresult character varying DEFAULT NULL::character varying) RETURNS character varying
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_cid int;
  v_plid bigint;
  v_amount numeric(19,4);
  v_dramount numeric(19,4);
  v_sdid bigint;
  v_finalprice numeric(19,4);
  v_coupon_cid int;
  v_coupon_amount numeric(19,4);
  v_paybleamount numeric(19,4);
  v_transid varchar(100);
  v_totalcategory text;
  v_paidusercid int;
BEGIN
  -- BEGIN TRAN (removed)
  v_finalprice := 0;
  v_paybleamount := 0;
  v_paidusercid := 0;
  SELECT cid INTO v_cid FROM portal_login WHERE pmid = v_pmid;
  SELECT CAST(ROUND(CAST(((99999 - 11111 - 1) * RANDOM() + 11111) AS DECIMAL), 0) AS VARCHAR(50)) + CAST(ROUND(CAST(((99999 - 11111 - 1) * RANDOM() + 11111) AS DECIMAL), 0) AS VARCHAR(50)) INTO v_transid;
  v_finalprice := v_totalprice * v_noofmonth;
  v_paybleamount := v_finalprice;
  IF (v_paymode = 'wiretransfer') THEN
  INSERT INTO tbl_subscription_details (pmid, catid, cid, ctid, aid, status, keyid, price, noofmonth, totalprice, packagetype, subscriptiondate, paymode, paidamount, remark, w_accountname, w_accountno, w_bankname, w_transid, w_transdate, w_remark, w_receipt, filenames, transid) VALUES (v_pmid, v_catid, v_cid, v_ctid, v_aid, 0, v_keyid, v_totalprice, v_noofmonth, v_finalprice, '', dbo.fun_getCurrentDate(), v_paymode, v_paidamount, v_remarks, v_w_accountname, v_w_accountno, v_w_bankname, v_w_transid, v_w_transdate, v_w_remark, v_w_receipt, v_filename, v_transid);
  SELECT MAX(sdid) INTO v_sdid FROM tbl_subscription_details WHERE pmid = v_pmid;
  v_strresult := 'success^' || 'Subscription request has been created successfully. Your transaction ID is ' || CAST(v_transid AS VARCHAR(50)) || CAST(v_sdid AS VARCHAR(10));
  END IF;
  IF (v_paymode = 'Cash') THEN
  INSERT INTO tbl_subscription_details (pmid, catid, cid, ctid, aid, status, keyid, price, noofmonth, totalprice, packagetype, subscriptiondate, paymode, paidamount, remark, depositedate, checkdate, chechnumber, bankname, branchname, accountno, checkamount, couponno, filenames, transid) VALUES (v_pmid, v_catid, v_cid, v_ctid, v_aid, 0, v_keyid, v_totalprice, v_noofmonth, v_finalprice, '', dbo.fun_getCurrentDate(), v_paymode, v_paidamount, v_remarks, v_depositdate, v_checkdate, v_checknumber, v_bankname, v_branchname, v_accountnumber, v_checkamount, v_couponno, v_filename, v_transid);
  v_strresult := 'success^' || 'Subscription request has been created successfully. Your transaction ID is ' || CAST(v_transid AS VARCHAR(50)) || CAST(v_sdid AS VARCHAR(10));
  END IF;
  IF (v_paymode = 'Cheque') THEN
  INSERT INTO tbl_subscription_details (pmid, catid, cid, ctid, aid, status, keyid, price, noofmonth, totalprice, packagetype, subscriptiondate, paymode, paidamount, remark, depositedate, checkdate, chechnumber, bankname, branchname, accountno, checkamount, couponno, filenames, transid) VALUES (v_pmid, v_catid, v_cid, v_ctid, v_aid, 0, v_keyid, v_totalprice, v_noofmonth, v_finalprice, '', dbo.fun_getCurrentDate(), v_paymode, v_paidamount, v_remarks, v_depositdate, v_checkdate, v_checknumber, v_bankname, v_branchname, v_accountnumber, v_checkamount, v_couponno, v_filename, v_transid);
  UPDATE coupon_master SET status = 0, usedby = v_pmid WHERE coupon_number = v_couponno;
  v_strresult := 'success^' || 'Subscription request has been created successfully. Your transaction ID is ' || CAST(v_transid AS VARCHAR(50)) || CAST(v_sdid AS VARCHAR(10));
  END IF;
  IF (v_paymode = 'paypal') THEN
  INSERT INTO tbl_subscription_details (pmid, catid, cid, ctid, aid, status, keyid, price, noofmonth, totalprice, packagetype, subscriptiondate, paymode, paidamount, remark, depositedate, checkdate, chechnumber, bankname, branchname, accountno, checkamount, couponno, filenames, transid, onlinepaystauts) VALUES (v_pmid, v_catid, v_cid, v_ctid, v_aid, 0, v_keyid, v_totalprice, v_noofmonth, v_finalprice, '', dbo.fun_getCurrentDate(), v_paymode, v_paidamount, v_remarks, v_depositdate, v_checkdate, v_checknumber, v_bankname, v_branchname, v_accountnumber, v_checkamount, v_couponno, v_filename, v_transid, 'pending');
  UPDATE coupon_master SET status = 0, usedby = v_pmid WHERE coupon_number = v_couponno;
  v_strresult := 'success^' || v_transid;
  END IF;
  IF (v_paymode = 'ewallet') THEN
  IF NOT EXISTS(SELECT plid FROM portal_login WHERE loginid = v_memberid AND password = v_password) THEN
  v_strresult := 'error^' || 'InvalidLoginID';
  -- COMMIT (removed)
  RETURN;
  END IF;
  SELECT plid INTO v_plid FROM portal_login WHERE loginid = v_memberid AND password = v_password;
  SELECT COALESCE(cid, 0) INTO v_paidusercid FROM portal_login WHERE plid = v_plid;
  IF (v_cid <> v_paidusercid) THEN
  v_strresult := 'error^' || 'InvalidCountryUser';
  -- COMMIT (removed)
  RETURN;
  END IF;
  IF NOT EXISTS(SELECT amount FROM ewallet WHERE plid = v_plid) THEN
  v_strresult := 'error^' || 'InsufficientBalance';
  -- COMMIT (removed)
  RETURN;
  END IF;
  SELECT COALESCE(amount, 0), COALESCE(dramount, 0) INTO v_amount, v_dramount FROM ewallet WHERE plid = v_plid;
  IF (v_amount < v_finalprice) THEN
  v_strresult := 'error^' || 'InsufficientBalance';
  -- COMMIT (removed)
  RETURN;
  END IF;
  INSERT INTO tbl_subscription_details (pmid, catid, cid, ctid, aid, status, keyid, price, noofmonth, totalprice, packagetype, subscriptiondate, paymode, paidamount, remark, depositedate, qpaymemberid, qpaymemberpassword, couponno, filenames, transid) VALUES (v_pmid, v_catid, v_cid, v_ctid, v_aid, 1, v_keyid, v_totalprice, v_noofmonth, v_finalprice, '', dbo.fun_getCurrentDate(), v_paymode, v_paidamount, v_remarks, v_depositdate, v_memberid, v_password, v_couponno, v_filename, v_transid);
  SELECT MAX(sdid) INTO v_sdid FROM tbl_subscription_details WHERE pmid = v_pmid;
  PERFORM dbo.usp_approvesubscription(v_sdid => v_sdid, v_mode => 'approve', v_currencyrate => '');
  UPDATE ewallet SET amount = COALESCE(amount, 0) - v_finalprice, dramount = COALESCE(dramount, 0) + v_finalprice WHERE plid = v_plid;
  INSERT INTO member_perfornemce (plid, childpmid, amount, date, active, trantype) VALUES (v_plid, v_pmid, v_finalprice, dbo.fun_getCurrentDate(), 1, 'Subscription');
  v_transid := v_transid || 1;
  v_strresult := 'success^' || 'Business subscription has been activated successfully. Your transaction ID is ' || CAST(v_transid AS VARCHAR(50)) || CAST(v_sdid AS VARCHAR(10));
  UPDATE coupon_master SET status = 0, usedby = v_pmid WHERE coupon_number = v_couponno;
  END IF;
  IF (v_mode = 'update') THEN
  UPDATE tbl_subscription_details SET sdidforupdate = v_sdidforupdate WHERE sdid = v_sdid;
  UPDATE portal_master SET expirydate = dbo.fun_getcurrentDate() WHERE pmid = (SELECT pmid FROM tbl_subscription_details WHERE sdid = v_sdidforupdate);
  END IF;
  IF 0 > 0 THEN
  v_strresult := 'error^error';
  -- ROLLBACK (removed)
  RETURN;
  END IF;
  -- COMMIT (removed)
END;
$$;


--
-- Name: usp_subscriptionprice(character varying, character varying, character varying, integer, character varying, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_subscriptionprice(v_ctid character varying DEFAULT ''::character varying, v_aid character varying DEFAULT ''::character varying, v_catid character varying DEFAULT ''::character varying, v_cid integer DEFAULT 0, v_package character varying DEFAULT ''::character varying, v_intresult integer DEFAULT 0) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_sid int;
  v_pctid int;
  v_kmid int;
  v_keywordrate numeric(19,4);
  v_noofhits bigint;
  v_symbol varchar(100);
  v_totalnoofhits bigint;
  v_price numeric(19,4);
  v_areaname VARCHAR(100);
  v_index1 INT;
  v_slice2 text;
  v_scatname VARCHAR(100);
  v_keyword VARCHAR(100);
  v_slice1 text;
  v_index3 INT;
  v_index4 INT;
  v_slice3 text;
  v_slice4 text;
  v_index2 INT;
  v_firsttime int;
  updatelrdirect CURSOR FOR SELECT kmid FROM keyword_master WHERE kactive = 1 AND catid IN (v_slice2);
BEGIN
  -- BEGIN TRAN (removed)
  -- SET option (removed)
  DROP TABLE IF EXISTS tmp_temp111;
  CREATE TEMP TABLE tmp_temp111 (totalnoofhits bigint,
keywordname varchar (100),
price numeric(19,4) ,
symbol varchar (100),
kmid int) ON COMMIT DROP;
  v_intresult := 0;
  v_slice3 := v_aid;
  v_slice1 := v_catid;
  v_index3 := 1;
  WHILE v_index3 <> 0 LOOP
  SELECT POSITION(',' IN v_slice1) INTO v_index3;
  IF v_index3 <> 0 THEN
  SELECT LEFT(CAST(v_slice1 AS TEXT), v_index3 - 1) INTO v_slice2;
  ELSE
  v_slice2 := v_slice1;
  END IF;
  OPEN updatelrdirect;
  FETCH updatelrdirect INTO v_kmid;
  WHILE FOUND LOOP
  v_totalnoofhits := 0;
  v_slice3 := v_aid;
  v_index2 := 1;
  WHILE v_index2 <> 0 LOOP
  SELECT POSITION(',' IN v_slice3) INTO v_index2;
  IF v_index2 <> 0 THEN
  SELECT LEFT(CAST(v_slice3 AS TEXT), v_index2 - 1) INTO v_slice4;
  ELSE
  v_slice4 := v_slice3;
  END IF;
  v_noofhits := 0;
  SELECT v_totalnoofhits INTO v_noofhits FROM dbo.usp_totalnoofhitsmonthlyofarea(v_aid => v_slice4, v_kid => v_kmid, v_totalnoofhits => v_noofhits);
  v_noofhits := COALESCE(v_noofhits, 0);
  v_totalnoofhits := v_totalnoofhits + v_noofhits;
  SELECT RIGHT(CAST(v_slice3 AS TEXT), LENGTH(CAST(v_slice3 AS TEXT)) - v_index2) INTO v_slice3;
  IF LENGTH(CAST(v_slice3 AS TEXT)) = 0 THEN
  EXIT;
  END IF;
  END LOOP;
  SELECT v_keywordrate, v_symbol INTO v_keywordrate, v_symbol FROM dbo.usp_keywordrate_countrywise(v_cid => v_cid, v_kmid => v_kmid, v_package => v_package, v_keywordrate => v_keywordrate, v_symbol => v_symbol);
  v_keywordrate := COALESCE(v_keywordrate, 0);
  v_symbol := COALESCE(v_symbol, 'Rs');
  v_price := v_totalnoofhits * v_keywordrate;
  SELECT keywordname INTO v_keyword FROM keyword_master WHERE kmid = v_kmid;
  INSERT INTO tmp_temp111 (totalnoofhits, price, kmid, keywordname, symbol) VALUES (v_totalnoofhits, v_price, v_kmid, v_keyword, v_symbol);
  FETCH updatelrdirect INTO v_kmid;
  END LOOP;
  CLOSE updatelrdirect;
  -- DEALLOCATE (removed)
  SELECT RIGHT(CAST(v_slice1 AS TEXT), LENGTH(CAST(v_slice1 AS TEXT)) - v_index3) INTO v_slice1;
  IF LENGTH(CAST(v_slice1 AS TEXT)) = 0 THEN
  EXIT;
  END IF;
  END LOOP;
  RETURN QUERY SELECT kmid, CONCAT(keywordname, ' (No. of Hits ', totalnoofhits, ' , Price ', price, ' ', 'In ', symbol, ' ', ') ') AS keywordname, price FROM tmp_temp111 ORDER BY keywordname NULLS FIRST;
  IF (0 <> 0) THEN
  v_intresult := 2;
  -- ROLLBACK (removed)
  RETURN;
  END IF;
  DROP TABLE IF EXISTS tmp_temp111;
  -- SET option (removed)
  -- COMMIT (removed)
END;
$$;


--
-- Name: usp_subscriptionprice_dhm(character varying, character varying, character varying, integer, character varying, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_subscriptionprice_dhm(v_ctid character varying DEFAULT ''::character varying, v_aid character varying DEFAULT ''::character varying, v_catid character varying DEFAULT ''::character varying, v_cid integer DEFAULT 0, v_package character varying DEFAULT ''::character varying, v_intresult integer DEFAULT 0) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $_$
DECLARE
  v_sid int;
  v_pctid int;
  v_kmid int;
  v_keywordrate numeric(19,4);
  v_noofhits bigint;
  v_symbol varchar(100);
  v_totalnoofhits bigint;
  v_price numeric(19,4);
  v_areaname VARCHAR(100);
  v_index1 INT;
  v_slice2 text;
  v_scatname VARCHAR(100);
  v_keyword VARCHAR(100);
  v_slice1 text;
  v_index3 INT;
  v_index4 INT;
  v_slice3 text;
  v_slice4 text;
  v_index2 INT;
  v_firsttime int;
  v_categoryname varchar(100);
  v_catid2 bigint;
  updatelrdirect CURSOR FOR SELECT kmid FROM keyword_master WHERE kactive = 1 AND catid IN (v_slice2);
BEGIN
  -- BEGIN TRAN (removed)
  -- SET option (removed)
  DROP TABLE IF EXISTS tmp_temp111;
  CREATE TEMP TABLE tmp_temp111 (totalnoofhits bigint,

keywordname varchar (100),

price numeric(19,4) ,

symbol varchar (100),

kmid int,

categoryname varchar(100)) ON COMMIT DROP;
  v_intresult := 0;
  v_slice3 := v_aid;
  v_slice1 := v_catid;
  v_index3 := 1;
  WHILE v_index3 <> 0 LOOP
  SELECT POSITION(',' IN v_slice1) INTO v_index3;
  IF v_index3 <> 0 THEN
  SELECT LEFT(CAST(v_slice1 AS TEXT), v_index3 - 1) INTO v_slice2;
  ELSE
  v_slice2 := v_slice1;
  END IF;
  OPEN updatelrdirect;
  FETCH updatelrdirect INTO v_kmid;
  WHILE FOUND LOOP
  v_totalnoofhits := 0;
  v_slice3 := v_aid;
  v_index2 := 1;
  WHILE v_index2 <> 0 LOOP
  SELECT POSITION(',' IN v_slice3) INTO v_index2;
  IF v_index2 <> 0 THEN
  SELECT LEFT(CAST(v_slice3 AS TEXT), v_index2 - 1) INTO v_slice4;
  ELSE
  v_slice4 := v_slice3;
  END IF;
  v_noofhits := 0;
  SELECT v_totalnoofhits INTO v_noofhits FROM dbo.usp_totalnoofhitsmonthlyofarea(v_aid => v_slice4, v_kid => v_kmid, v_totalnoofhits => v_noofhits);
  v_noofhits := COALESCE(v_noofhits, 0);
  v_totalnoofhits := v_totalnoofhits + v_noofhits;
  SELECT RIGHT(CAST(v_slice3 AS TEXT), LENGTH(CAST(v_slice3 AS TEXT)) - v_index2) INTO v_slice3;
  IF LENGTH(CAST(v_slice3 AS TEXT)) = 0 THEN
  EXIT;
  END IF;
  END LOOP;
  SELECT v_keywordrate, v_symbol INTO v_keywordrate, v_symbol FROM dbo.usp_keywordrate_countrywise(v_cid => v_cid, v_kmid => v_kmid, v_package => v_package, v_keywordrate => v_keywordrate, v_symbol => v_symbol);
  v_keywordrate := COALESCE(v_keywordrate, 0);
  v_symbol := COALESCE(v_symbol, '$');
  v_price := v_totalnoofhits * v_keywordrate;
  SELECT keywordname, catid INTO v_keyword, v_catid2 FROM keyword_master WHERE kmid = v_kmid;
  SELECT catname INTO v_categoryname FROM product_category WHERE catid = v_catid2;
  INSERT INTO tmp_temp111 (totalnoofhits, price, kmid, keywordname, symbol, categoryname) VALUES (v_totalnoofhits, v_price, v_kmid, v_keyword, v_symbol, v_categoryname);
  FETCH updatelrdirect INTO v_kmid;
  END LOOP;
  CLOSE updatelrdirect;
  -- DEALLOCATE (removed)
  SELECT RIGHT(CAST(v_slice1 AS TEXT), LENGTH(CAST(v_slice1 AS TEXT)) - v_index3) INTO v_slice1;
  IF LENGTH(CAST(v_slice1 AS TEXT)) = 0 THEN
  EXIT;
  END IF;
  END LOOP;
  RETURN QUERY SELECT kmid, CONCAT(keywordname, ' (Hits ', totalnoofhits, ' , Price ', price, ' ', '', symbol, ' ', ') ') AS keywordname, price, categoryname FROM tmp_temp111 ORDER BY categoryname ASC NULLS FIRST;
  IF (0 <> 0) THEN
  v_intresult := 2;
  -- ROLLBACK (removed)
  RETURN;
  END IF;
  DROP TABLE IF EXISTS tmp_temp111;
  -- SET option (removed)
  -- COMMIT (removed)
END;
$_$;


--
-- Name: usp_subsctract_city_state_area_pincode(text, integer, bigint, character varying, character varying, character varying, character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_subsctract_city_state_area_pincode(v_location text, v_cid integer DEFAULT 0, INOUT v_ctid bigint DEFAULT 0, INOUT v_cityname character varying DEFAULT ''::character varying, INOUT v_areaname character varying DEFAULT ''::character varying, INOUT v_statename character varying DEFAULT ''::character varying, INOUT v_pincode character varying DEFAULT ''::character varying) RETURNS record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_valuecount int;
  v_statenametemp varchar(100);
  v_citynametemp varchar(100);
  v_areanametemp varchar(100);
  v_pincodetemp varchar(100);
  v_pincodeexists varchar(10);
  v_areanameexists varchar(10);
  v_cityenameexists varchar(10);
  v_statenameexists varchar(10);
  v_findareaid bigint;
BEGIN
  v_statenametemp := '';
  v_citynametemp := '';
  v_areanametemp := '';
  v_pincodeexists := 'no';
  v_areanameexists := 'no';
  v_cityenameexists := 'no';
  v_statenameexists := 'no';
  v_ctid := 0;
  v_cityname := '';
  v_statename := '';
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp (id int GENERATED BY DEFAULT AS IDENTITY,
	tempvalue varchar(100)) ON COMMIT DROP;
  SELECT COUNT(*) INTO v_valuecount FROM dbo.SPLITSTRINGBYCOMMA(v_location);
  IF (v_valuecount = 4) THEN
  INSERT INTO tmp_temp SELECT * FROM dbo.SPLITSTRINGBYCOMMA(v_location);
  SELECT tempvalue INTO v_statenametemp FROM tmp_temp WHERE id = 4;
  SELECT tempvalue INTO v_citynametemp FROM tmp_temp WHERE id = 3;
  SELECT tempvalue INTO v_areanametemp FROM tmp_temp WHERE id = 2;
  SELECT tempvalue INTO v_pincodetemp FROM tmp_temp WHERE id = 1;
  IF EXISTS(SELECT pincode FROM area_master WHERE pincode = v_pincodetemp) THEN
  v_pincodeexists := 'yes';
  END IF;
  IF EXISTS(SELECT areaname FROM area_master WHERE areaname = v_areanametemp) THEN
  v_areanameexists := 'yes';
  END IF;
  IF EXISTS(SELECT cityname FROM city WHERE cityname = v_citynametemp) THEN
  v_cityenameexists := 'yes';
  END IF;
  IF EXISTS(SELECT statename FROM state WHERE statename = v_statenametemp) THEN
  v_statenameexists := 'yes';
  END IF;
  IF (v_pincodeexists = 'yes' AND v_areanameexists = 'yes' AND v_cityenameexists = 'yes' AND v_statenameexists = 'yes') THEN
  SELECT RTRIM(LTRIM(s.statename)), c.ctid, RTRIM(LTRIM(c.cityname)), RTRIM(LTRIM(am.areaname)), am.pincode INTO v_statename, v_ctid, v_cityname, v_areaname, v_pincode FROM area_master AS am INNER JOIN city AS c ON am.ctid = c.ctid INNER JOIN state AS s ON c.sid = s.sid WHERE am.pincode = v_pincodetemp AND am.areaname = v_areanametemp AND c.cityname = v_citynametemp AND s.statename = v_statenametemp;
  ELSE
  IF (v_cityenameexists = 'yes') THEN
  SELECT RTRIM(LTRIM(c.ctid)), RTRIM(LTRIM(c.cityname)), RTRIM(LTRIM(s.statename)) INTO v_ctid, v_cityname, v_statename FROM city AS c INNER JOIN state AS s ON c.sid = s.sid WHERE RTRIM(LTRIM(LOWER(c.cityname))) = RTRIM(LTRIM(LOWER(v_citynametemp))) AND c.cid = v_cid LIMIT 1;
  END IF;
  END IF;
  END IF;
  IF (v_valuecount = 3) THEN
  INSERT INTO tmp_temp SELECT * FROM dbo.SPLITSTRINGBYCOMMA(v_location);
  SELECT tempvalue INTO v_statenametemp FROM tmp_temp WHERE id = 3;
  SELECT tempvalue INTO v_citynametemp FROM tmp_temp WHERE id = 2;
  SELECT tempvalue INTO v_areanametemp FROM tmp_temp WHERE id = 1;
  IF EXISTS(SELECT areaname FROM area_master WHERE areaname = v_areanametemp) THEN
  v_areanameexists := 'yes';
  END IF;
  IF EXISTS(SELECT cityname FROM city WHERE cityname = v_citynametemp) THEN
  v_cityenameexists := 'yes';
  END IF;
  IF EXISTS(SELECT statename FROM state WHERE statename = v_statenametemp) THEN
  v_statenameexists := 'yes';
  END IF;
  IF (v_areanameexists = 'yes' AND v_cityenameexists = 'yes' AND v_statenameexists = 'yes') THEN
  SELECT RTRIM(LTRIM(s.statename)), c.ctid, RTRIM(LTRIM(c.cityname)), RTRIM(LTRIM(am.areaname)) INTO v_statename, v_ctid, v_cityname, v_areaname FROM area_master AS am INNER JOIN city AS c ON am.ctid = c.ctid INNER JOIN state AS s ON c.sid = s.sid WHERE am.areaname = v_areanametemp AND c.cityname = v_citynametemp AND s.statename = v_statenametemp;
  ELSE
  IF (v_cityenameexists = 'yes') THEN
  SELECT RTRIM(LTRIM(c.ctid)), RTRIM(LTRIM(c.cityname)), RTRIM(LTRIM(s.statename)) INTO v_ctid, v_cityname, v_statename FROM city AS c INNER JOIN state AS s ON c.sid = s.sid WHERE RTRIM(LTRIM(LOWER(c.cityname))) = RTRIM(LTRIM(LOWER(v_citynametemp))) AND c.cid = v_cid LIMIT 1;
  END IF;
  END IF;
  END IF;
  IF (v_valuecount = 2) THEN
  INSERT INTO tmp_temp SELECT * FROM dbo.SPLITSTRINGBYCOMMA(v_location);
  SELECT tempvalue INTO v_statenametemp FROM tmp_temp WHERE id = 2;
  SELECT tempvalue INTO v_citynametemp FROM tmp_temp WHERE id = 1;
  IF EXISTS(SELECT cityname FROM city WHERE cityname = v_citynametemp) THEN
  v_cityenameexists := 'yes';
  END IF;
  IF EXISTS(SELECT statename FROM state WHERE statename = v_statenametemp) THEN
  v_statenameexists := 'yes';
  END IF;
  IF (v_cityenameexists = 'yes' AND v_statenameexists = 'yes') THEN
  SELECT RTRIM(LTRIM(s.statename)), c.ctid, RTRIM(LTRIM(c.cityname)) INTO v_statename, v_ctid, v_cityname FROM city AS c INNER JOIN state AS s ON c.sid = s.sid WHERE c.cityname = v_citynametemp AND s.statename = v_statenametemp;
  ELSE
  IF (v_cityenameexists = 'yes' AND v_statenameexists = 'no') THEN
  SELECT RTRIM(LTRIM(c.ctid)), RTRIM(LTRIM(c.cityname)), RTRIM(LTRIM(s.statename)) INTO v_ctid, v_cityname, v_statename FROM city AS c INNER JOIN state AS s ON c.sid = s.sid WHERE RTRIM(LTRIM(LOWER(c.cityname))) = RTRIM(LTRIM(LOWER(v_citynametemp))) AND c.cid = v_cid LIMIT 1;
  ELSE
  IF (v_cityenameexists = 'no' AND v_statenameexists = 'yes') THEN
  SELECT RTRIM(LTRIM(c.ctid)), RTRIM(LTRIM(c.cityname)), RTRIM(LTRIM(s.statename)) INTO v_ctid, v_cityname, v_statename FROM state AS s INNER JOIN city AS c ON s.sid = c.sid WHERE RTRIM(LTRIM(LOWER(s.statename))) = RTRIM(LTRIM(LOWER(v_statenametemp))) AND s.cid = v_cid LIMIT 1;
  END IF;
  END IF;
  END IF;
  END IF;
  IF (v_valuecount = 1) THEN
  IF EXISTS(SELECT areaname FROM area_master WHERE areaname = v_areanametemp) THEN
  v_areanameexists := 'yes';
  END IF;
  IF EXISTS(SELECT cityname FROM city WHERE cityname = v_citynametemp) THEN
  v_cityenameexists := 'yes';
  END IF;
  IF (v_areanameexists = 'yes' AND v_cityenameexists = 'yes') THEN
  SELECT RTRIM(LTRIM(ctid)) INTO v_ctid FROM city WHERE cityname = v_location AND cid = v_cid LIMIT 1;
  SELECT cityname, statename INTO v_cityname, v_statename FROM city AS c INNER JOIN state AS s ON c.sid = s.sid WHERE c.ctid = v_ctid AND c.cid = v_cid;
  ELSE
  IF (v_areanameexists = 'yes' AND v_cityenameexists = 'no') THEN
  SELECT aid INTO v_findareaid FROM area_master WHERE areaname = v_location AND cid = v_cid LIMIT 1;
  SELECT RTRIM(LTRIM(areaname)), RTRIM(LTRIM(c.ctid)), RTRIM(LTRIM(c.cityname)), RTRIM(LTRIM(s.statename)) INTO v_areaname, v_ctid, v_cityname, v_statename FROM area_master AS am INNER JOIN city AS c ON am.ctid = c.ctid INNER JOIN state AS s ON c.sid = s.sid WHERE am.aid = v_findareaid AND am.cid = v_cid;
  ELSE
  IF (v_areanameexists = 'no' AND v_cityenameexists = 'yes') THEN
  SELECT RTRIM(LTRIM(ctid)) INTO v_ctid FROM city WHERE cityname = v_location AND cid = v_cid LIMIT 1;
  SELECT cityname, statename INTO v_cityname, v_statename FROM city AS c INNER JOIN state AS s ON c.sid = s.sid WHERE c.ctid = v_ctid AND c.cid = v_cid;
  END IF;
  END IF;
  END IF;
  END IF;
  DROP TABLE IF EXISTS tmp_temp;
END;
$$;


--
-- Name: usp_subsubcategorylist(integer, integer, character varying, character varying, character varying, integer, character varying, character varying, character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_subsubcategorylist(v_startrowindex integer DEFAULT 1, v_maxrows integer DEFAULT 100, v_searchfield character varying DEFAULT ''::character varying, v_searchvalue character varying DEFAULT ''::character varying, v_status character varying DEFAULT ''::character varying, v_totalcount integer DEFAULT 0, v_searchsubsubcategory character varying DEFAULT ''::character varying, v_searchsubcategory character varying DEFAULT ''::character varying, v_searchcategory character varying DEFAULT ' '::character varying) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_minindex int;
  v_maxindex int;
  v_query text;
BEGIN
  v_minindex := (v_startrowindex - 1) * v_maxrows + 1;
  v_maxindex := v_startrowindex * v_maxrows;
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp (rowNumber int,
SUBCATID bigint,
SubCatName varchar(500),
Status varchar(100),
SCATNAME varchar(500),

CATNAME varchar(500)) ON COMMIT DROP;
  v_query := 'insert into #temp  select ROW_NUMBER() over (order by TSC.SUBCATID desc) as rownumber,isnull(SUBCATID,0),
  isnull(TSC.SubCatName,'''') as SubCatName,(CASE TSC.Status WHEN 1 THEN ''Active'' ELSE ''Deactive'' END) AS Status,isnull(PSC.SCATNAME,'''') as SCATNAME,isnull(PC.CATNAME,'''') as CATNAME
   FROM KEYWORD_MASTER KM INNER JOIN PRODUCT_CATEGORY PC ON KM.CATID = PC.CATID
INNER JOIN PRODUCT_SUBCATEGORY PSC ON PSC.SCATID = KM.SCATID 
Left Join TBL_SUB_CATEGORY TSC ON TSC.SUBCATID=KM.KMID where 1=1';
  IF (v_searchfield = 'SubCatName') THEN
  v_query := v_query || ' and TSC.SubCatName like ''%' || v_searchvalue || '%''';
  END IF;
  IF (v_searchfield = 'SCATNAME') THEN
  v_query := v_query || ' and PSC.SCATNAME like ''%' || v_searchvalue || '%''';
  END IF;
  IF (v_searchfield = 'CATNAME') THEN
  v_query := v_query || ' and PC.CATNAME like ''%' || v_searchvalue || '%''';
  END IF;
  IF (v_status <> '') THEN
  v_query := v_query || ' AND TSC.Status = +CONVERT(VARCHAR(20),''' || v_status || ''') ';
  END IF;
  IF (v_searchsubsubcategory <> '') THEN
  v_searchsubsubcategory := REPLACE(v_searchsubsubcategory, '''', '''''');
  v_query := v_query || ('AND km.KEYWORDNAME=''' || v_searchsubsubcategory || '''');
  END IF;
  IF (v_searchsubcategory <> '') THEN
  v_searchsubcategory := REPLACE(v_searchsubcategory, '''', '''''');
  v_query := v_query || ('AND PSC.SCATNAME=''' || v_searchsubcategory || '''');
  END IF;
  IF (v_searchcategory <> '') THEN
  v_searchcategory := REPLACE(v_searchcategory, '''', '''''');
  v_query := v_query || ('AND PC.CATNAME=''' || v_searchcategory || '''');
  END IF;
  EXECUTE v_query;
  RETURN QUERY SELECT * FROM tmp_temp WHERE rownumber BETWEEN v_minindex AND v_maxindex ORDER BY rownumber ASC NULLS FIRST;
  SELECT COUNT(rownumber) INTO v_totalcount FROM tmp_temp;
  DROP TABLE IF EXISTS tmp_temp;
  -- SET option (removed)
END;
$$;


--
-- Name: usp_successorfailedrecharge(integer, character varying, numeric, character varying, character varying, character varying, character varying, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_successorfailedrecharge(v_mode integer DEFAULT 4, v_loginid character varying DEFAULT '49428122'::character varying, v_amount numeric DEFAULT 28.00, INOUT v_walletbalance character varying DEFAULT ''::character varying, INOUT v_strresult character varying DEFAULT ''::character varying, v_usernameewallet character varying DEFAULT ''::character varying, v_transactionpasswordewallet character varying DEFAULT ''::character varying, v_plid integer DEFAULT 0) RETURNS record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_db_name VARCHAR(100);
  v_ref_regno VARCHAR(10);
  v_stroutput varchar(100);
  v_transactionidout varchar(100);
  v_parmdefinition text;
  v_querysql text;
  v_noofminute Int;
  v_previousotpdateandtime timestamp;
  v_amountforuse Decimal(18,8);
BEGIN
  -- BEGIN TRAN (removed)
  v_ref_regno := '';
  v_stroutput := '';
  v_transactionidout := '';
  v_parmdefinition := N'@StrOutPut Nvarchar(100) OUTPUT,@TransactionIdOut Nvarchar(100) OUTPUT';
  v_querysql := '';
  IF (v_mode = 1) THEN
  SELECT db_name INTO v_db_name FROM tbl_distributor WHERE did = 1;
  SELECT COALESCE(reference_regno, 0) INTO v_ref_regno FROM tbl_customerlogin WHERE loginid = v_loginid;
  IF (v_ref_regno = 0) THEN
  v_strresult := 'You have insufficient fund in your I-Wallet for mobile topup.';
  -- COMMIT (removed)
  RETURN;
  END IF;
  v_noofminute := 0;
  v_amountforuse := 0.00;
  IF (v_transactionpasswordewallet = '') THEN
  -- COMMIT (removed)
  v_strresult := 'I-Wallet OTP Is Blank';
  RETURN;
  END IF;
  IF EXISTS(SELECT 1 FROM tbl_shoppingotpmaster WHERE plid = v_plid AND active = 1 AND status = 1 AND otp = v_transactionpasswordewallet AND mode = 3 AND username = v_usernameewallet) THEN
  SELECT MAX(datetime), COALESCE(MAX(amountforuse), 0.00) INTO v_previousotpdateandtime, v_amountforuse FROM tbl_shoppingotpmaster WHERE plid = v_plid AND active = 1 AND status = 1 AND otp = v_transactionpasswordewallet AND mode = 3 AND username = v_usernameewallet LIMIT 1;
  ELSE
  v_previousotpdateandtime := NULL;
  END IF;
  IF (v_previousotpdateandtime IS NULL) THEN
  -- COMMIT (removed)
  v_strresult := 'Invalid I-Wallet OTP';
  RETURN;
  END IF;
  SELECT CAST(AGE(CAST(CAST(dbo.FUN_GETCURRENTDATE() AS TIMESTAMP) AS TIMESTAMP), CAST(CAST(v_previousotpdateandtime AS TIMESTAMP) AS TIMESTAMP)) AS BIGINT) INTO v_noofminute;
  IF (v_noofminute > 5) THEN
  -- COMMIT (removed)
  v_strresult := 'Your I-Wallet OTP Expired try again';
  RETURN;
  END IF;
  IF (v_amount <> v_amountforuse) THEN
  -- COMMIT (removed)
  v_strresult := 'I-Wallet OTP Does Not Match For Requested Amount';
  RETURN;
  END IF;
  v_querysql := 'EXEC [' || v_db_name || '].[DBO].[USP_SHOPING_TRANSACTION_DEBIT] ' || CAST(v_ref_regno AS VARCHAR(10)) || ',      
   ' || CAST(v_amount AS VARCHAR(20)) || ','''',@StrOutPut Out,@TransactionIdOut Out,1';
  EXECUTE v_querysql;
  IF (v_stroutput <> 'success') THEN
  v_strresult := v_stroutput;
  -- COMMIT (removed)
  RETURN;
  END IF;
  v_walletbalance := 0;
  v_strresult := 'success';
  -- COMMIT (removed)
  RETURN;
  END IF;
  IF (0 <> 0) THEN
  -- ROLLBACK (removed)
  RETURN;
  ELSE
  -- COMMIT (removed)
  END IF;
END;
$$;


