--
-- Name: usp_suggestedproduct(integer, integer, character varying, boolean, character varying, character varying, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_suggestedproduct(v_startrowindex integer, v_maxrows integer, v_orderbyfield character varying, v_asc boolean, v_searchfield character varying, v_searchvalue character varying, v_mode integer) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_recordcount int;
  v_regno bigint;
BEGIN
  -- SET option (removed)
  DROP TABLE IF EXISTS tmp_temp12;
  CREATE TEMP TABLE tmp_temp12 ON COMMIT DROP AS SELECT ROW_NUMBER() OVER (ORDER BY spid DESC NULLS LAST) AS rownumber, ' IpAddress  : ' || sp.ipaddress || '  ||  Ip-Country  : ' || sp.ipcountry || '  ||  Ip-State  : ' || sp.ipstate || '  ||  Ip-City  : ' || sp.ipcity AS ipaddress, sp.spid, sp.name, sp.email, sp.mobile, sp.city, sp.area, sp.active, sp.search, sp.suggestdate FROM dbo.suggested_product AS sp WHERE sp.active = 1;
  SELECT COUNT(*) INTO v_recordcount FROM tmp_temp12;
  IF (v_searchfield = 'Name') THEN
  RETURN QUERY SELECT * FROM tmp_temp12 WHERE name LIKE '%' || v_searchvalue || '%';
  END IF;
  IF (v_searchfield = 'Mobile') THEN
  RETURN QUERY SELECT * FROM tmp_temp12 WHERE mobile = v_searchvalue;
  END IF;
  IF (v_searchfield = 'City') THEN
  RETURN QUERY SELECT * FROM tmp_temp12 WHERE city LIKE '%' || v_searchvalue || '%';
  END IF;
  IF (v_searchfield = '') THEN
  RETURN QUERY SELECT * FROM tmp_temp12 WHERE rownumber BETWEEN v_startrowindex AND v_maxrows;
  END IF;
  DROP TABLE IF EXISTS tmp_temp12;
  -- SET option (removed)
END;
$$;


--
-- Name: usp_suggestkeywordtoadmin(character varying, bigint, character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_suggestkeywordtoadmin(v_suggestkeyword character varying, v_pmid bigint, INOUT v_strresult character varying) RETURNS character varying
    LANGUAGE plpgsql
    AS $$
BEGIN
  -- BEGIN TRAN (removed)
  v_strresult := 'ok';
  IF EXISTS(SELECT 1 FROM tbl_keywordsuggestions WHERE keyword = v_suggestkeyword AND status = 0) THEN
  v_strresult := 'Added keyword already Suggested';
  -- COMMIT (removed)
  RETURN;
  END IF;
  IF EXISTS(SELECT 1 FROM product_category WHERE COALESCE(catactive, 0) = 1 AND COALESCE(catname, '') = v_suggestkeyword) THEN
  v_strresult := 'This keyword already Exist';
  -- COMMIT (removed)
  RETURN;
  END IF;
  IF EXISTS(SELECT 1 FROM keyword_master WHERE COALESCE(kactive, 0) = 1 AND COALESCE(keywordname, '') = v_suggestkeyword) THEN
  v_strresult := 'This keyword already Exist';
  -- COMMIT (removed)
  RETURN;
  END IF;
  INSERT INTO tbl_keywordsuggestions (pmid, keyword, suggestiondate, status) VALUES (v_pmid, v_suggestkeyword, dbo.fun_getCurrentDate(), 0);
  IF (0 <> 0) THEN
  -- ROLLBACK (removed)
  v_strresult := 'Error Occured !!!';
  RETURN;
  END IF;
  -- COMMIT (removed)
END;
$$;


--
-- Name: usp_taskautoscheduling(integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_taskautoscheduling(v_intresult integer DEFAULT 0) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_mode INT;
  v_memberplid INT;
  v_strresult text;
  v_count Int;
  v_totalcount Int;
  v_earnedpoint Decimal(10,2);
  v_previousremainlinkforclick BigInt;
  v_previousremainlinkforshare BigInt;
  v_amount Decimal(10,2);
  v_netamount Decimal(10,2);
  v_currentincome Decimal(10,2);
  v_tds_per double precision;
  v_tds Decimal(10,2);
  v_admincharge_per double precision;
  v_admincharge Decimal(10,2);
  v_regno BigInt;
  v_stroutputresult Int;
  v_pointperdayforview double precision;
  v_pointperdayforshare double precision;
  v_previousremainpointforclick double precision;
  v_previousremainpointforshare double precision;
  v_priceperlinkforview double precision;
  v_priceperlinkforshare double precision;
  v_previousdate timestamp;
  v_islooping Int;
  v_tempdate Date;
BEGIN
  BEGIN
  -- SET option (removed)
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp (RowNumber Int GENERATED BY DEFAULT AS IDENTITY,
PLID Int) ON COMMIT DROP;
  v_mode := 2;
  v_memberplid := 0;
  v_strresult := '';
  v_count := 1;
  v_totalcount := 0;
  INSERT INTO tmp_temp SELECT DISTINCT (plid) FROM portal_login WHERE active = 1;
  SELECT COUNT(1) INTO v_totalcount FROM tmp_temp;
  WHILE (v_count <= v_totalcount) LOOP
  SELECT plid INTO v_memberplid FROM tmp_temp WHERE rownumber = v_count;
  v_earnedpoint := 0;
  v_previousremainlinkforclick := 0;
  v_previousremainlinkforshare := 0;
  v_amount := 0.00;
  v_netamount := 0.00;
  v_currentincome := 0.00;
  v_tds_per := 0.00;
  v_tds := 0.00;
  v_admincharge_per := 0.00;
  v_admincharge := 0.00;
  v_regno := 0;
  v_stroutputresult := 0;
  v_pointperdayforview := 0;
  v_pointperdayforshare := 0;
  v_previousremainpointforclick := 0;
  v_previousremainpointforshare := 0;
  v_priceperlinkforview := 0.00;
  v_priceperlinkforshare := 0.00;
  v_islooping := 1;
  v_tempdate := dbo.FUN_GETCURRENTDATE();
  IF (v_mode = 2) THEN
  BEGIN
  IF EXISTS(SELECT 1 FROM tbl_membersubscriptionaccount WHERE dbo.FUN_GETCURRENTDATE() BETWEEN activationdate AND tilldate AND plid = v_memberplid) THEN
  IF NOT EXISTS(SELECT 1 FROM tbl_dailytasklimits WHERE plid = v_memberplid AND CAST(date AS DATE) = CAST(dbo.FUN_GETCURRENTDATE() AS DATE)) THEN
  SELECT perdaypointforview, perdaypointforshare, priceperlinkforview, priceperlinkforshare INTO v_pointperdayforview, v_pointperdayforshare, v_priceperlinkforview, v_priceperlinkforshare FROM tbl_datewisecommonroiaccount WHERE CAST(date AS DATE) = CAST(dbo.FUN_GETCURRENTDATE() AS DATE) LIMIT 1;
  SELECT COALESCE((CASE WHEN totalavailableclicksforday >= totalclicked THEN ((totalavailableclicksforday - totalclicked) + previousremainclick) WHEN totalclicked > totalavailableclicksforday THEN previousremainclick ELSE 0 END), 0), COALESCE((CASE WHEN totalavailableshareforday >= totalshared THEN ((totalavailableshareforday - totalshared) + previousremainshare) WHEN totalshared > totalavailableshareforday THEN previousremainshare ELSE 0 END), 0), COALESCE(previouscarryforwardpointforclick, 0), COALESCE(previouscarryforwardpointforshare, 0), date INTO v_previousremainlinkforclick, v_previousremainlinkforshare, v_previousremainpointforclick, v_previousremainpointforshare, v_previousdate FROM tbl_dailytasklimits WHERE plid = v_memberplid ORDER BY date DESC NULLS LAST LIMIT 1;
  SELECT (COALESCE(v_previousremainpointforclick, 0) + COALESCE((v_pointperdayforview - (priceperlinkforview * maxnoofclicksperdayforview)), 0)), (COALESCE(v_previousremainpointforshare, 0) + COALESCE((v_pointperdayforshare - (priceperlinkforshare * maxnooflinkperdayforshare)), 0)) INTO v_previousremainpointforclick, v_previousremainpointforshare FROM tbl_datewisecommonroiaccount WHERE CAST(date AS DATE) = CAST(dbo.FUN_GETCURRENTDATE() AS DATE) LIMIT 1;
  WHILE (v_islooping = 1 AND (v_previousremainpointforclick > 0 OR v_previousremainpointforshare > 0)) LOOP
  IF (v_previousremainpointforclick >= v_priceperlinkforview) THEN
  v_islooping := 1;
  v_previousremainpointforclick := v_previousremainpointforclick - v_priceperlinkforview;
  v_previousremainlinkforclick := v_previousremainlinkforclick + 1;
  ELSE
  v_islooping := 0;
  END IF;
  IF (v_previousremainpointforshare >= v_priceperlinkforshare) THEN
  v_islooping := 1;
  v_previousremainpointforshare := v_previousremainpointforshare - v_priceperlinkforshare;
  v_previousremainlinkforshare := v_previousremainlinkforshare + 1;
  END IF;
  END LOOP;
  INSERT INTO tbl_dailytasklimits (date, plid, tsmid, totalavailableclicksforday, priceperclick, totalclicked, status, previouscarryforwardclick, previousremainclick, totalavailableshareforday, pricepershare, totalshared, previouscarryforwardshare, previousremainshare, previouscarryforwardpointforclick, previouscarryforwardpointforshare) SELECT dbo.FUN_GETCURRENTDATE(), v_memberplid, 0, maxnoofclicksperdayforview, priceperlinkforview, 0, status, v_previousremainlinkforclick, v_previousremainlinkforclick, maxnooflinkperdayforshare, priceperlinkforshare, 0, v_previousremainlinkforshare, v_previousremainlinkforshare, v_previousremainpointforclick, v_previousremainpointforshare FROM tbl_datewisecommonroiaccount WHERE CAST(date AS DATE) = CAST(dbo.FUN_GETCURRENTDATE() AS DATE) LIMIT 1;
  IF (CAST(v_previousdate AS DATE) <> CAST(dbo.FUN_GETCURRENTDATE() AS DATE)) THEN
  PERFORM dbo.usp_blogandclassifiedmanagemnt(v_plid => v_memberplid, v_tsmid => 0, v_intresultoutput => v_strresult, v_previousdate => v_previousdate);
  RETURN QUERY SELECT v_strresult;
  IF (v_strresult <> 'Ok') THEN
  v_strresult := 'Some Error..!! Sorry.';
  END IF;
  ELSE
  PERFORM dbo.usp_blogandclassifiedmanagemnt(v_plid => v_memberplid, v_tsmid => 0, v_intresultoutput => v_strresult, v_previousdate => v_tempdate);
  IF (v_strresult <> 'Ok') THEN
  v_strresult := 'Some Error..!! Sorry.';
  END IF;
  END IF;
  END IF;
  ELSE
  v_strresult := 'Not Eligible For ROI..!! Sorry.';
  END IF;
  -- SET option (removed)
  v_strresult := 'Ok';
  EXCEPTION WHEN OTHERS THEN
  -- SET option (removed)
  v_strresult := 'Cancel';
  END;
  END IF;
  v_intresult := 1;
  v_count := v_count + 1;
  END LOOP;
  EXCEPTION WHEN OTHERS THEN
  v_intresult := 0;
  END;
END;
$$;


--
-- Name: usp_taskincome_master_setting(integer, integer, numeric, numeric, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_taskincome_master_setting(v_mode integer DEFAULT 2, v_ttpsmid integer DEFAULT 0, v_rate numeric DEFAULT 0.00, v_percentage numeric DEFAULT 0.00, v_intresult integer DEFAULT 0) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_checkincome DECIMAL(10,2);
  v_totalcheckincome DECIMAL(10,2);
BEGIN
  -- SET option (removed)
  IF (v_mode = 1) THEN
  RETURN QUERY SELECT ROW_NUMBER() OVER (ORDER BY ttm.tasktype NULLS FIRST) AS rownumber, tpsm.ttpsmid, ttm.tasktype, tpsm.rate, tpsm.distributionpercentageofcompanyrevenue FROM tbl_tasktypemaster AS ttm INNER JOIN tbl_taskpricesettingmaster AS tpsm ON (ttm.tttid = tpsm.tttid) ORDER BY ttm.tasktype NULLS FIRST;
  END IF;
  IF (v_mode = 2) THEN
  RETURN QUERY SELECT ROW_NUMBER() OVER (ORDER BY sid NULLS FIRST) AS rownumber, sid, clubdesc, (CASE WHEN caption = 'BTCAddress' THEN clubcond ELSE CAST(limits AS text) END) AS limits FROM settings WHERE editable = 1;
  END IF;
  IF (v_mode = 3) THEN
  v_checkincome := 0.00;
  v_totalcheckincome := 0.00;
  SELECT SUM(COALESCE(distributionpercentageofcompanyrevenue, 0.00)) INTO v_checkincome FROM tbl_taskpricesettingmaster WHERE ttpsmid <> v_ttpsmid;
  SELECT COALESCE(limits, 0.00) INTO v_totalcheckincome FROM settings WHERE caption = 'DISTRIBUTION-PERCENTAGE-OF-COMPANY-REVENUE-AS-TASK-INCOME';
  IF (v_totalcheckincome >= (v_checkincome + v_percentage)) THEN
  UPDATE tbl_taskpricesettingmaster SET rate = v_rate, distributionpercentageofcompanyrevenue = v_percentage, lastupdateddate = CURRENT_TIMESTAMP WHERE ttpsmid = v_ttpsmid;
  v_intresult := 1;
  ELSE
  v_intresult := v_totalcheckincome;
  END IF;
  END IF;
  -- SET option (removed)
  IF (0 <> 0) THEN
  v_intresult := 0;
  RETURN;
  END IF;
END;
$$;


