--
-- Name: usp_taskstatusmaster(integer, integer, character varying, integer, integer, integer, integer, integer, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_taskstatusmaster(v_mode integer DEFAULT 0, v_tsmid integer DEFAULT 0, v_date character varying DEFAULT ''::character varying, v_allowview integer DEFAULT 0, v_allowshare integer DEFAULT 0, v_allowblog integer DEFAULT 0, v_allowclassified integer DEFAULT 0, v_intresult integer DEFAULT 0, v_recordcount integer DEFAULT 0) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
BEGIN
  -- SET option (removed)
  IF (v_mode = 1) THEN
  IF (v_tsmid = 0) THEN
  INSERT INTO tbl_taskstatusmaster (date, isallowview, isallowshare, isallowblog, isallowclassified, createdate, createdby, updatedby, updateddate, status) VALUES (v_date, v_allowview, v_allowshare, v_allowblog, v_allowclassified, CURRENT_TIMESTAMP, 1, 0, '', 1);
  v_intresult := 1;
  ELSE
  IF EXISTS(SELECT 1 FROM tbl_taskstatusmaster WHERE tsmid = v_tsmid AND status = 1) THEN
  UPDATE tbl_taskstatusmaster SET date = v_date, isallowview = v_allowview, isallowshare = v_allowshare, isallowblog = v_allowblog, isallowclassified = v_allowclassified, updatedby = 1, updateddate = CURRENT_TIMESTAMP;
  v_intresult := 2;
  ELSE
  v_intresult := 3;
  END IF;
  END IF;
  END IF;
  IF (v_mode = 2) THEN
  RETURN QUERY SELECT ROW_NUMBER() OVER (ORDER BY tsmid NULLS FIRST) AS number, tsmid, CASE WHEN date = '1900-01-01' THEN '---' ELSE CAST(TO_CHAR(date, 'DD-MM-YYYY') AS VARCHAR(200)) END AS date, CASE WHEN isallowview = 1 THEN 'Allow' ELSE 'Not Allow' END AS isallowview, CASE WHEN isallowshare = 1 THEN 'Allow' ELSE 'Not Allow' END AS isallowshare, CASE WHEN isallowblog = 1 THEN 'Allow' ELSE 'Not Allow' END AS isallowblog, CASE WHEN isallowclassified = 1 THEN 'Allow' ELSE 'Not Allow' END AS isallowclassified, CASE WHEN createdate = '1900-01-01' THEN '' ELSE CAST(TO_CHAR(createdate, 'DD-MM-YYYY') AS VARCHAR(200)) END AS createdate, CASE WHEN status = 1 THEN 'Active' ELSE 'Deactive' END AS status FROM tbl_taskstatusmaster;
  END IF;
  IF (v_mode = 3) THEN
  RETURN QUERY SELECT CAST(TO_CHAR(date, 'MM/DD/YYYY') AS VARCHAR(200)) AS date, * FROM tbl_taskstatusmaster WHERE tsmid = v_tsmid AND status = 1;
  END IF;
  -- SET option (removed)
  IF (0 <> 0) THEN
  v_intresult := 0;
  RETURN;
  END IF;
END;
$$;


--
-- Name: usp_tbl_addvatcategory(integer, bigint, text, numeric, character varying, character, character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_tbl_addvatcategory(v_vcid integer, v_branchid bigint DEFAULT NULL::bigint, v_vattitle text DEFAULT NULL::text, v_vatpercvalue numeric DEFAULT NULL::numeric, v_mode character varying DEFAULT NULL::character varying, v_status character DEFAULT ''::bpchar, INOUT v_strresult character varying DEFAULT NULL::character varying) RETURNS character varying
    LANGUAGE plpgsql
    AS $$
BEGIN
  -- BEGIN TRAN (removed)
  IF (v_mode = 'Insert') THEN
  INSERT INTO tbl_vat_categories (vattitle, vatpercvalue, active, branchid, statename) VALUES (v_vattitle, v_vatpercvalue, CASE COALESCE(v_status, 0) WHEN 0 THEN 0 ELSE v_status END, 0, '');
  SELECT MAX(vcid) INTO v_vcid FROM tbl_vat_categories;
  v_strresult := CAST(v_vcid AS VARCHAR(30)) || '^Insert';
  END IF;
  IF (v_mode = 'Update') THEN
  UPDATE tbl_vat_categories SET vattitle = v_vattitle, vatpercvalue = v_vatpercvalue, branchid = 0, active = CASE COALESCE(v_status, 0) WHEN 0 THEN 0 ELSE v_status END WHERE vcid = v_vcid;
  v_strresult := 'Update';
  END IF;
  IF (v_mode = 'DELETE') THEN
  UPDATE tbl_vat_categories SET active = 0 WHERE vcid = v_vcid;
  v_strresult := 'Delete';
  END IF;
  IF (0 <> 0) THEN
  v_strresult := 'Error occurred. Please try later';
  -- ROLLBACK (removed)
  RETURN;
  END IF;
  -- COMMIT (removed)
END;
$$;


