--
-- Name: usp_tds_history(character varying, integer, integer, character varying, character varying, character varying, character varying, character varying, character varying, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_tds_history(v_plid character varying DEFAULT ''::character varying, v_startrowindex integer DEFAULT 1, v_maxrows integer DEFAULT 10, v_searchfield character varying DEFAULT ''::character varying, v_searchvalue character varying DEFAULT ''::character varying, v_fromdate character varying DEFAULT ''::character varying, v_todate character varying DEFAULT ''::character varying, v_loginid character varying DEFAULT ''::character varying, v_pancard character varying DEFAULT ''::character varying, v_totalcount integer DEFAULT 0) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_minindex int;
  v_maxindex int;
  v_query text;
BEGIN
  v_minindex := (v_startrowindex - 1) * v_maxrows + 1;
  v_maxindex := v_startrowindex * v_maxrows;
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp (rownumber bigint,
LIID bigint,
OPID varchar(100),
FROMID varchar(100),
TOID varchar(100),
AMOUNT decimal(18,2),
INCOME decimal(18,2),
LEVEL int,
TYPE text,
DATE timestamp,
REMARK text,
PAYID int,
STATUS varchar(100),
ACTIVE boolean,
ISSKIP int,
kit_price numeric(19,4),
comm_per numeric(19,4),
tds_amt decimal(18,2),
tds_per numeric(19,4),
admin_amt decimal(18,2),
admin_per numeric(19,4),
member_active int,
fullName varchar(200),
fromloginid varchar(200),
PANNO varchar(200),
tds_section_id int,
section varchar(200),
section_name varchar(200),
section_section_name varchar(250)) ON COMMIT DROP;
  v_query := 'insert into #temp  select ROW_NUMBER() OVER(ORDER BY wh.DATE desc) AS rowNumber,wh.LIID,wh.OPID,wh.FROMID,wh.TOID,isnull(wh.AMOUNT,0),isnull(wh.INCOME,0),
wh.LEVEL,wh.TYPE,wh.DATE,isnull(wh.REMARK,0),wh.PAYID, case wh.STATUS when 0 then ''Pending''  when 1 then''Paid'' end as STATUS,wh.ACTIVE,wh.ISSKIP,wh.kit_price,
wh.comm_per,wh.tds_amt,wh.tds_per,wh.admin_amt,wh.admin_per,isnull(wh.member_active,''''), mm.FName+'' ''+isnull(mm.LName,'''') as fullName,isnull(pl.loginid,'''') as fromloginid,
isnull(mm.PANNO,'''') as PANNO,wh.tds_section_id,ts.section,ts.section_name,ts.section+'' ''+isnull(ts.section_name,'''') as section_section_name  from LEVEL_INCOME wh 
inner join member_master mm on mm.loginid=wh.FROMID left join PORTAL_LOGIN pl on pl.plid=mm.plid left join TDs_Section ts on ts.int_id=wh.tds_section_id where wh.status=1
union all
select ROW_NUMBER() OVER(ORDER BY wh.DATE desc) AS rowNumber,wh.DIID,wh.OPID,wh.FROMID,wh.TOID,isnull(wh.AMOUNT,0),isnull(wh.INCOME,0),
wh.LEVEL,wh.TYPE,wh.DATE,isnull(wh.REMARK,0),wh.PAYID, case wh.STATUS when 0 then ''Pending''  when 1 then''Paid'' end as STATUS,wh.ACTIVE,wh.ISSKIP,wh.kit_price,
wh.comm_per,wh.tds_amt,wh.tds_per,wh.admin_amt,wh.admin_per,isnull(wh.member_active,''''), mm.FName+'' ''+isnull(mm.LName,'''') as fullName,isnull(pl.loginid,'''') as fromloginid,
isnull(mm.PANNO,'''') as PANNO,wh.tds_section_id,ts.section,ts.section_name,ts.section+'' ''+isnull(ts.section_name,'''') as section_section_name  from directIncomes wh 
inner join member_master mm on mm.loginid=wh.FROMID left join PORTAL_LOGIN pl on pl.plid=mm.plid left join TDs_Section ts on ts.int_id=wh.tds_section_id where wh.status=1
';
  IF (v_plid <> 0) THEN
  v_query := v_query || ' and  wh.TOID =''' || v_plid || ''' ';
  END IF;
  IF (v_searchfield <> '' AND v_searchvalue <> '') THEN
  IF (v_searchfield = 'loginid') THEN
  v_query := v_query || ' and pl.loginid =''' || v_searchvalue || ''' ';
  END IF;
  END IF;
  IF ((v_fromdate <> '') AND (v_todate = '')) THEN
  v_query := v_query || ' and CONVERT(date, wh.DATE, 105) between  CONVERT(date, ''' || v_fromdate || ''', 105) and  CONVERT(date, dbo.fun_getCurrentDate(), 105) ';
  END IF;
  IF ((v_fromdate = '') AND (v_todate <> '')) THEN
  v_query := v_query || ' and CONVERT(date, wh.DATE, 105) between  CONVERT(date, ''' || v_todate || ''', 105) and  CONVERT(date, dbo.fun_getCurrentDate(), 105) ';
  END IF;
  IF ((v_fromdate <> '') AND (v_todate <> '')) THEN
  v_query := v_query || ' and CONVERT(date, wh.DATE, 105) between CONVERT(date, ''' || v_fromdate || ''', 105) and  CONVERT(date, ''' || v_todate || ''', 105) ';
  END IF;
  IF (v_loginid <> '') THEN
  v_query := v_query || ' AND ISNULL(pl.loginid,'''') LIKE ''%' || v_loginid || '%''';
  END IF;
  IF (v_pancard <> '') THEN
  v_query := v_query || ' AND ISNULL(mm.PANNO,'''') LIKE ''%' || v_pancard || '%''';
  END IF;
  EXECUTE v_query;
  RETURN QUERY SELECT * FROM tmp_temp WHERE rownumber BETWEEN v_minindex AND v_maxindex;
  SELECT COUNT(rownumber) INTO v_totalcount FROM tmp_temp;
  DROP TABLE IF EXISTS tmp_temp;
  -- SET option (removed)
END;
$$;


--
-- Name: usp_testimonial(integer, integer, character varying, boolean, character varying, character varying, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_testimonial(v_startrowindex integer, v_maxrows integer, v_orderbyfield character varying, v_asc boolean, v_searchfield character varying, v_searchvalue character varying, v_mode integer) RETURNS SETOF record
