--
-- Name: usp_textsearching(character varying, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_textsearching(v_searchtext character varying, INOUT v_pmid integer) RETURNS integer
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_count int;
BEGIN
  DROP TABLE IF EXISTS tmp_temp1;
  CREATE TEMP TABLE tmp_temp1 ON COMMIT DROP AS SELECT LTRIM(RTRIM(v_searchtext)) AS searchtext;
  SELECT COUNT(pmid) INTO v_count FROM portal_master WHERE companyname = (SELECT searchtext FROM tmp_temp1);
  IF (v_count = 0) THEN
  v_pmid := 0;
  DROP TABLE IF EXISTS tmp_temp1;
  RETURN;
  ELSE
  DROP TABLE IF EXISTS tmp_temp2;
  CREATE TEMP TABLE tmp_temp2 ON COMMIT DROP AS SELECT LTRIM(RTRIM(v_searchtext)) AS searchtext;
  SELECT pmid INTO v_pmid FROM portal_master WHERE companyname = (SELECT searchtext FROM tmp_temp2) LIMIT 1;
  DROP TABLE IF EXISTS tmp_temp2;
  RETURN;
  END IF;
END;
$$;


--
-- Name: usp_ticketgeneraldetails(integer, integer, integer, integer, integer, integer, integer, text, text, character varying, text, integer, integer, text, integer, integer, integer, integer, character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_ticketgeneraldetails(v_mode integer DEFAULT 0, v_ticketid integer DEFAULT 0, v_userid integer DEFAULT 0, v_from integer DEFAULT 0, v_touser integer DEFAULT 0, v_prid integer DEFAULT 0, v_catid integer DEFAULT 0, v_message text DEFAULT ''::text, v_comment text DEFAULT ''::text, v_date character varying DEFAULT ''::character varying, v_project text DEFAULT ''::text, v_pagesize integer DEFAULT 100, v_pageno integer DEFAULT 1, v_clientid text DEFAULT ''::text, v_intresult integer DEFAULT 0, v_issolved integer DEFAULT 0, v_status integer DEFAULT 0, v_brid integer DEFAULT 0, v_image character varying DEFAULT ''::character varying) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
BEGIN
  -- BEGIN TRAN (removed)
  IF (v_mode = 1) THEN
  RETURN QUERY SELECT DISTINCT trm.trid, trm.message, trm.date, trm.tmid, CASE image WHEN '' THEN '' WHEN image THEN image ELSE '' END AS imageurl, CASE image WHEN '' THEN 0 WHEN image THEN 1 ELSE 0 END AS imgpr FROM tbl_ticketreply AS trm LEFT OUTER JOIN tbl_ticketmaster AS tm ON trm.tmid = tm.tmid WHERE tm.tmid = v_ticketid ORDER BY date DESC NULLS LAST;
  END IF;
  IF (0 <> 0) THEN
  v_intresult := 0;
  -- ROLLBACK (removed)
  END IF;
  -- COMMIT (removed)
END;
$$;


--
-- Name: usp_topaccountmanager(integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_topaccountmanager(v_mode integer DEFAULT 1) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF (v_mode = 1) THEN
  RETURN QUERY SELECT username, (fname || lname) AS name, phone, emailid, (userid) AS accountno, plid FROM portal_login WHERE plid IN (SELECT plid FROM tbl_customercoinbuytradingmaster WHERE active = 1 GROUP BY plid ORDER BY COALESCE(SUM((traderateinusd * cloedtradevolume)), 0) ASC NULLS FIRST LIMIT 100);
  ELSE
  IF (v_mode = 2) THEN
  RETURN QUERY SELECT username, (fname || lname) AS name, phone, emailid, (userid) AS accountno, plid FROM portal_login WHERE plid IN (SELECT plid FROM tbl_customercoinsaletradingmaster WHERE active = 1 GROUP BY plid ORDER BY COALESCE(SUM((traderateinusd * cloedtradevolume)), 0) DESC NULLS LAST LIMIT 100);
  ELSE
  IF (v_mode = 3) THEN
  DROP TABLE IF EXISTS v_temptrade;
  CREATE TEMP TABLE v_temptrade (RowNumber Int,
PLID Int,
BuyTradeUSDWorth Decimal(18,8),
SaleTradeUSDWorth Decimal(18,8)) ON COMMIT DROP;
  INSERT INTO v_temptrade SELECT plid, COALESCE(SUM((traderateinusd * cloedtradevolume)), 0), 0 FROM tbl_customercoinbuytradingmaster WHERE active = 1 GROUP BY plid ORDER BY COALESCE(SUM((traderateinusd * cloedtradevolume)), 0) ASC NULLS FIRST;
  INSERT INTO v_temptrade SELECT plid, 0, COALESCE(SUM((traderateinusd * cloedtradevolume)), 0) FROM tbl_customercoinsaletradingmaster WHERE active = 1 GROUP BY plid ORDER BY COALESCE(SUM((traderateinusd * cloedtradevolume)), 0) DESC NULLS LAST;
  RETURN QUERY SELECT username, (fname || lname) AS name, phone, emailid, (userid) AS accountno, plid FROM portal_login WHERE plid IN (SELECT plid FROM v_temptrade GROUP BY plid ORDER BY COALESCE(SUM(buytradeusdworth), 0) + COALESCE(SUM(saletradeusdworth), 0) DESC NULLS LAST LIMIT 100);
  END IF;
  END IF;
  END IF;
END;
$$;


--
-- Name: usp_topup_request_history(integer, integer, character varying, character varying, character varying, integer, character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_topup_request_history(v_startrowindex integer DEFAULT 1, v_maxrows integer DEFAULT 100, v_fromdate character varying DEFAULT ''::character varying, v_todate character varying DEFAULT ''::character varying, v_paymode character varying DEFAULT ''::character varying, v_totalcount integer DEFAULT 0, v_did character varying DEFAULT '2'::character varying) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_minindex INT;
  v_maxindex INT;
  v_query text;
BEGIN
  BEGIN
  v_minindex := (v_startrowindex - 1) * v_maxrows + 1;
  v_maxindex := v_startrowindex * v_maxrows;
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp (Row_NUMBER int,
AMOUNT DECIMAL(18,2),
DATE timestamp,
PAYMODE VARCHAR(100),
BANKNAME VARCHAR(250),
IFsC_Code VARCHAR(50),
MEM_REMARK text,
Status varchar(50),
ReferenceID varchar(50)) ON COMMIT DROP;
  v_query := 'INSERT INTO #TEMP SELECT  ROW_NUMBER() OVER(ORDER BY DATE DESC) ROW_NUMBER, AMOUNT,DATE,
		    CASE PAYMODE WHEN 1 THEN ''BANK ACCOUNT'' WHEN 9 THEN ''DD'' WHEN 10 THEN ''CHEQUE'' WHEN 11 THEN ''NEFT'' 
			WHEN 12 THEN ''RTGS'' WHEN 13 THEN ''IMPS'' WHEN 0 THEN ''COMISSION WALLET'' END PAYMODE,
			BANKNAME,[IFSC CODE] AS IFSC_CODE,MEM_REMARK, 
			CASE STATUS WHEN 1 THEN ''PENDING REQUEST'' WHEN 2 THEN ''APPROVED'' WHEN 3 THEN ''REJECTED'' END STATUS,REFERANCE_ID AS REFERENCEID 
			FROM TBL_RESELLERWALLETREQUEST WHERE PMID=CAST(''' || v_did || ''' AS INT) ';
  RAISE NOTICE '%', v_query;
  IF (v_paymode <> '') THEN
  v_query := v_query || ' And PAYMODE = ''' || v_paymode || '''';
  END IF;
  IF ((v_fromdate <> '') AND (v_fromdate = '')) THEN
  v_query := v_query || ' AND CONVERT(DATE, DATE) =  CONVERT(DATE, ''' || v_fromdate || ''')';
  END IF;
  IF ((v_fromdate = '') AND (v_todate <> '')) THEN
  v_query := v_query || ' AND CONVERT(DATE, DATE) =  CONVERT(DATE, ''' || v_todate || ''') ';
  END IF;
  IF ((v_fromdate <> '') AND (v_todate <> '')) THEN
  v_query := v_query || ' AND CONVERT(DATE, DATE) BETWEEN CONVERT(DATE, ''' || v_fromdate || ''') AND  CONVERT(DATE, ''' || v_todate || ''') ';
  END IF;
  EXECUTE v_query;
  RETURN QUERY SELECT * FROM tmp_temp WHERE row_number BETWEEN v_minindex AND v_maxindex;
  SELECT COUNT(row_number) INTO v_totalcount FROM tmp_temp;
  DROP TABLE IF EXISTS tmp_temp;
  -- SET option (removed)
  EXCEPTION WHEN OTHERS THEN
  PERFORM dbo.sp_errorlog();
  IF (0 > 0) THEN
  -- ROLLBACK (removed)
  END IF;
  RETURN;
  END;
END;
$$;


--
-- Name: usp_total_avg_reviews(character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_total_avg_reviews(v_productid character varying DEFAULT '24'::character varying) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
BEGIN
  -- BEGIN TRAN (removed)
  -- SET option (removed)
  RETURN QUERY SELECT COALESCE(COUNT(emailid), 0) AS totalreviews, COALESCE(SUM(stars), 0) AS totalratings, COALESCE((SUM(stars) / COUNT(emailid)), 0) AS averagestars, COALESCE(5 - (SUM(stars) / COUNT(emailid)), 0) AS remainingstars, (SELECT COALESCE(COUNT(stars), 0) FROM tbl_reviewmaster WHERE stars = 5 AND pmid = v_productid) AS fiveratings, (SELECT COALESCE(COUNT(stars), 0) FROM tbl_reviewmaster WHERE stars = 4 AND pmid = v_productid) AS fourratings, (SELECT COALESCE(COUNT(stars), 0) FROM tbl_reviewmaster WHERE stars = 3 AND pmid = v_productid) AS threeratings, (SELECT COALESCE(COUNT(stars), 0) FROM tbl_reviewmaster WHERE stars = 2 AND pmid = v_productid) AS tworatings, (SELECT COALESCE(COUNT(stars), 0) FROM tbl_reviewmaster WHERE stars = 1 AND pmid = v_productid) AS oneratings FROM tbl_reviewmaster WHERE pmid = v_productid AND status = 1;
  -- SET option (removed)
  -- COMMIT (removed)
END;
$$;


--
-- Name: usp_total_avg_reviews_mobile(character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_total_avg_reviews_mobile(v_productid character varying DEFAULT '46'::character varying) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
BEGIN
  -- BEGIN TRAN (removed)
  -- SET option (removed)
  RETURN QUERY SELECT COALESCE(COUNT(emailid), 0) AS totalreviews, COALESCE(SUM(stars), 0) AS totalratings, COALESCE((SUM(stars) / COUNT(emailid)), 0) AS averagestars, COALESCE(5 - (SUM(stars) / COUNT(emailid)), 0) AS remainingstars, (SELECT COALESCE(COUNT(stars), 0) FROM tbl_reviewmaster WHERE stars = 5 AND pmid = v_productid) * (COALESCE(COUNT(emailid), 0) / 100) AS fiveratings, (SELECT COALESCE(COUNT(stars), 0) FROM tbl_reviewmaster WHERE stars = 4 AND pmid = v_productid) * (COALESCE(COUNT(emailid), 0) / 100) AS fourratings, (SELECT COALESCE(COUNT(stars), 0) FROM tbl_reviewmaster WHERE stars = 3 AND pmid = v_productid) * (COALESCE(COUNT(emailid), 0) / 100) AS threeratings, (SELECT COALESCE(COUNT(stars), 0) FROM tbl_reviewmaster WHERE stars = 2 AND pmid = v_productid) * (COALESCE(COUNT(emailid), 0) / 100) AS tworatings, (SELECT COALESCE(COUNT(stars), 0) FROM tbl_reviewmaster WHERE stars = 1 AND pmid = v_productid) * (COALESCE(COUNT(emailid), 0) / 100) AS oneratings, (SELECT COALESCE(COUNT(stars), 0) FROM tbl_reviewmaster WHERE stars = 5 AND pmid = v_productid) AS fiveratingstotal, (SELECT COALESCE(COUNT(stars), 0) FROM tbl_reviewmaster WHERE stars = 4 AND pmid = v_productid) AS fourratingstotal, (SELECT COALESCE(COUNT(stars), 0) FROM tbl_reviewmaster WHERE stars = 3 AND pmid = v_productid) AS threeratingstotal, (SELECT COALESCE(COUNT(stars), 0) FROM tbl_reviewmaster WHERE stars = 2 AND pmid = v_productid) AS tworatingstotal, (SELECT COALESCE(COUNT(stars), 0) FROM tbl_reviewmaster WHERE stars = 1 AND pmid = v_productid) AS oneratingstotal FROM tbl_reviewmaster WHERE pmid = v_productid AND status = 1;
  -- SET option (removed)
  -- COMMIT (removed)
END;
$$;


--
-- Name: usp_totalnoofhitsmonthlyofarea(character varying, character varying, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_totalnoofhitsmonthlyofarea(v_aid character varying DEFAULT ''::character varying, v_kid character varying DEFAULT ''::character varying, INOUT v_totalnoofhits integer DEFAULT 0) RETURNS integer
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_prevyear date;
  v_prevmonth date;
  v_sumofnoofhits int;
  v_countofnoofhits int;
BEGIN
  SELECT CAST(CURRENT_TIMESTAMP AS DATE) + INTERVAL '-1 MONTH' INTO v_prevmonth;
  SELECT CAST(CAST(CURRENT_TIMESTAMP AS DATE) + INTERVAL '-1 MONTH' AS DATE) + INTERVAL '-1 YEAR' INTO v_prevyear;
  SELECT COALESCE(SUM(noofhits), 0) INTO v_sumofnoofhits FROM tblnumberofhitsmonthly WHERE keywordid = v_kid AND aid = v_aid AND hitmonth BETWEEN v_prevyear AND v_prevmonth;
  SELECT COUNT(noofhits) INTO v_countofnoofhits FROM tblnumberofhitsmonthly WHERE keywordid = v_kid AND aid = v_aid AND hitmonth BETWEEN v_prevyear AND v_prevmonth;
  IF (v_countofnoofhits = 0) THEN
  v_totalnoofhits := 0;
  ELSE
  v_totalnoofhits := v_sumofnoofhits / v_countofnoofhits;
  END IF;
END;
$$;


--
-- Name: usp_totalproducts(integer, integer, integer, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_totalproducts(v_maincatid integer DEFAULT 1, v_catid integer DEFAULT 0, v_subcatid integer DEFAULT 0, INOUT v_totalcount integer DEFAULT 0) RETURNS integer
    LANGUAGE plpgsql
    AS $$
BEGIN
  BEGIN
  -- SET option (removed)
  DROP TABLE IF EXISTS tmp_tempsearching;
  CREATE TEMP TABLE tmp_tempsearching ON COMMIT DROP AS SELECT ROW_NUMBER() OVER (ORDER BY mprid NULLS FIRST) AS rowno, mprid, productcode, producttitle, shotdescription, fulldescription, vp.sprid, productimages, discountpercentage, sellmrp, dap, masterproductattriubuteid, attributetitle, attributevalue, keyfeatures, CAST(dbo.FUN_GETRATINGOFSUBPRODUCT(vp.sprid) AS INT) AS ratingstar, maincategoryid, subcategoryid, catid, dealsids, createddate, modifydate, replacementday, procurementsla, cashondelivery, shippingcharges, stockin, stockout, stocknet, isoutofstock, COALESCE(dpw.bv, 0) AS bv, COALESCE(dpw.pv, 0) AS pv FROM ims_view_allproductdeals AS vp LEFT JOIN tbl_distributor_comm_productwise AS dpw ON dpw.sprid = vp.sprid WHERE (v_maincatid = 0 OR maincategoryid = v_maincatid) AND (v_catid = 0 OR catid = v_catid) AND (v_subcatid = 0 OR subcategoryid = v_subcatid);
  DROP TABLE IF EXISTS tmp_tempsearching1;
  CREATE TEMP TABLE tmp_tempsearching1 (PRODUCTTITLE varchar (250)) ON COMMIT DROP;
  INSERT INTO tmp_tempsearching1 SELECT producttitle FROM tmp_tempsearching GROUP BY producttitle HAVING COUNT(producttitle) >= 1;
  SELECT COUNT(producttitle) INTO v_totalcount FROM tmp_tempsearching1;
  DROP TABLE IF EXISTS tmp_tempsearching;
  DROP TABLE IF EXISTS tmp_tempsearching1;
  -- SET option (removed)
  EXCEPTION WHEN OTHERS THEN
  v_totalcount := 0;
  END;
END;
$$;


