CREATE FUNCTION dbo.usp_track_order(v_poid integer DEFAULT 10018, v_loginid character varying DEFAULT ''::character varying) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
BEGIN
  -- SET option (removed)
  RETURN QUERY SELECT intstatus, COALESCE(CAST(TO_CHAR(ocs.createddate, 'DD TMMon YYYY') AS VARCHAR(30)), '') AS createddate, COALESCE(CAST(TO_CHAR(ocs.date, 'DD TMMon YYYY') AS VARCHAR(30)), '') AS approveddate, COALESCE(CAST(TO_CHAR(ocs.packed, 'DD TMMon YYYY') AS VARCHAR(30)), '') AS packeddate, COALESCE(CAST(TO_CHAR(ocs.handover, 'DD TMMon YYYY') AS VARCHAR(30)), '') AS handoverdate, COALESCE(CAST(TO_CHAR(ocs.intransit, 'DD TMMon YYYY') AS VARCHAR(30)), '') AS transitdate, COALESCE(CAST(TO_CHAR(ocs.picked, 'DD TMMon YYYY') AS VARCHAR(30)), '') AS pickeddate, COALESCE(CAST(TO_CHAR(ocs.delivered, 'DD TMMon YYYY') AS VARCHAR(30)), '') AS delivereddate, COALESCE(CAST(TO_CHAR(ocs.outfordelivery, 'DD TMMon YYYY') AS VARCHAR(30)), '') AS outfordelivery, COALESCE(CAST(TO_CHAR(ocs.cancel, 'DD TMMon YYYY') AS VARCHAR(30)), '') AS canceldate, COALESCE(CAST(TO_CHAR(ocs.refunddate, 'DD TMMon YYYY') AS VARCHAR(30)), '') AS refunddate, COALESCE(ocs.refundfileimage, '') AS refundfileimage FROM tbl_product_order_master AS pom LEFT JOIN tbl_order_confirmedstaus AS ocs ON ocs.orderno = pom.orderno WHERE poid = v_poid AND loginid = v_loginid;
  -- SET option (removed)
END;
$$;


--
-- Name: usp_track_order_mobile(integer, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_track_order_mobile(v_poid integer DEFAULT 0, v_clid integer DEFAULT 0) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_loginid varchar(20);
BEGIN
  v_loginid := '';
  SELECT loginid INTO v_loginid FROM tbl_customerlogin WHERE clid = v_clid;
  RETURN QUERY SELECT intstatus, COALESCE(CAST(TO_CHAR(ocs.createddate, 'DD TMMon YYYY') AS VARCHAR(30)), '') AS createddate, COALESCE(CAST(TO_CHAR(ocs.date, 'DD TMMon YYYY') AS VARCHAR(30)), '') AS approveddate, COALESCE(CAST(TO_CHAR(ocs.packed, 'DD TMMon YYYY') AS VARCHAR(30)), '') AS packeddate, COALESCE(CAST(TO_CHAR(ocs.handover, 'DD TMMon YYYY') AS VARCHAR(30)), '') AS handoverdate, COALESCE(CAST(TO_CHAR(ocs.intransit, 'DD TMMon YYYY') AS VARCHAR(30)), '') AS transitdate, COALESCE(CAST(TO_CHAR(ocs.picked, 'DD TMMon YYYY') AS VARCHAR(30)), '') AS pickeddate, COALESCE(CAST(TO_CHAR(ocs.delivered, 'DD TMMon YYYY') AS VARCHAR(30)), '') AS delivereddate FROM tbl_product_order_master AS pom LEFT JOIN tbl_order_confirmedstaus AS ocs ON ocs.orderno = pom.orderno WHERE poid = v_poid AND loginid = v_loginid;
END;
$$;


--
-- Name: usp_trafficboostermaster(integer, character varying, text, integer, numeric, numeric, numeric, integer, bigint, integer, integer, numeric); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_trafficboostermaster(v_mode integer DEFAULT 1, v_packagename character varying DEFAULT ''::character varying, v_packagefeaturedescription text DEFAULT ''::text, v_isactive integer DEFAULT 0, v_amount numeric DEFAULT 0.00, v_totalamount numeric DEFAULT 0.00, v_st numeric DEFAULT 0.00, v_noofhits integer DEFAULT 0, v_noofdaysvalidity bigint DEFAULT 0, v_intresult integer DEFAULT 0, v_ttbid integer DEFAULT 0, v_bvpercentage numeric DEFAULT 0.00) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_from Int;
  v_to Int;
BEGIN
  v_from := 0;
  v_to := 0;
  IF (v_mode = 1) THEN
  RETURN QUERY SELECT ROW_NUMBER() OVER (ORDER BY ttbid NULLS FIRST) AS rownumber, ttbid, packagename, packagefeaturedescription, (CASE WHEN isactive = 1 THEN 'Active' ELSE 'Deactive' END) AS isactive, amount, totalamount, st, noofdaysvalidity, noofhits, bvpercentage FROM tbl_trafficbooster;
  v_intresult := 1;
  END IF;
  IF (v_mode = 2) THEN
  INSERT INTO tbl_trafficbooster (packagename, packagefeaturedescription, isactive, amount, totalamount, st, noofdaysvalidity, noofhits, bvpercentage) VALUES (v_packagename, v_packagefeaturedescription, v_isactive, v_amount, v_totalamount, v_st, v_noofdaysvalidity, v_noofhits, v_bvpercentage);
  v_intresult := 2;
  END IF;
  IF (v_mode = 3) THEN
  UPDATE tbl_trafficbooster SET packagename = v_packagename, packagefeaturedescription = v_packagefeaturedescription, isactive = v_isactive, amount = v_amount, totalamount = v_totalamount, st = v_st, noofdaysvalidity = v_noofdaysvalidity, noofhits = v_noofhits, bvpercentage = v_bvpercentage WHERE ttbid = v_ttbid;
  v_intresult := 3;
  END IF;
  IF (v_mode = 4) THEN
  RETURN QUERY SELECT ROW_NUMBER() OVER (ORDER BY ttbid NULLS FIRST) AS rownumber, ttbid, packagename, packagefeaturedescription, isactive, amount, totalamount, st, noofdaysvalidity, noofhits, bvpercentage FROM tbl_trafficbooster WHERE ttbid = v_ttbid;
  v_intresult := 1;
  END IF;
  IF (0 <> 0) THEN
  v_intresult := 0;
  RETURN;
  END IF;
END;
$$;


--
-- Name: usp_trafficboostersubscription(integer, integer, character varying, character varying, character varying, character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_trafficboostersubscription(v_startrowindex integer DEFAULT 1, v_maxrows integer DEFAULT 10, v_activationdate character varying DEFAULT ''::character varying, v_tilldate character varying DEFAULT ''::character varying, v_activitydate character varying DEFAULT ''::character varying, v_loginid character varying DEFAULT ''::character varying) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_query text;
  v_minindex INT;
  v_maxindex INT;
  v_queryresult text;
BEGIN
  v_query := '';
  v_queryresult := '';
  v_minindex := (v_startrowindex - 1) * v_maxrows + 1;
  v_maxindex := v_startrowindex * v_maxrows;
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp (RowNumber BIGINT GENERATED BY DEFAULT AS IDENTITY,
TUTBID INT,
TTBID	INT,
PurchasedDate Varchar(15),
ActivationDate Varchar(15),
ActivateTillDate Varchar(15),
RemainNoOfHits BIGINT,
PaymentMode INT,
PaymentModeName Varchar(600),
PaymentStatus INT,
BankName Varchar(600),
BranchName Varchar(600),
ReferenceNo Varchar(600),
ReferenceDate Varchar(15),
CommentOrRemark text,
NoOfDaysValidity BIGINT,
IsActive Varchar(50),
LOGINID Varchar(200),
NoOfHits BigInt) ON COMMIT DROP;
  v_query := 'Insert Into #TEMP Select TUTBID ,TTBID,Convert(Varchar(12),PurchasedDate,106),
Convert(Varchar(12),ActivationDate,106) As ActivationDate,Convert(Varchar(12),ActivateTillDate,106) As ActivateTillDate,
RemainNoOfHits,PaymentMode,PaymentModeName,IsNull(PaymentStatus,0) As PaymentStatus,BankName,BranchName,
ReferenceNo,Convert(Varchar(12),ReferenceDate,106) As ReferenceDate,CommentOrRemark,NoOfDaysValidity,
(Case When TB.IsActive= 1 Then ''Active'' Else ''Deactive'' End) As IsActive,PL.LOGINID,IsNull(NoOfHits,0) as NoOfHits
From Tbl_UserTrafficBooster TB Inner Join PORTAL_LOGIN PL on TB.PLid = PL.PLID Where Pl.ACTIVE = 1';
  IF (v_activationdate <> '' OR v_tilldate <> '' OR v_activitydate <> '') THEN
  v_query := v_query || ' And Convert(Date,ActivationDate,105)= Convert(Date,''' || v_activationdate || ''',105) OR Convert(Date,TillDate,105) = Convert(Date,''' || v_tilldate || ''',105) OR Convert(Date,ActivityDate,105) = Convert(Date,''' || v_activitydate || ''',105)';
  END IF;
  IF (v_loginid <> '') THEN
  v_query := v_query || ' And Pl.LOGINID Like ''%' || v_loginid || '%'' ';
  END IF;
  EXECUTE v_query;
  RETURN QUERY SELECT * FROM tmp_temp WHERE rownumber BETWEEN v_minindex AND v_maxindex;
  RETURN QUERY SELECT COUNT(tutbid) AS totalcount FROM tmp_temp;
END;
$$;


--
-- Name: usp_trailsubscription(bigint, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_trailsubscription(v_plid bigint DEFAULT 1028, INOUT v_intresult integer DEFAULT 0) RETURNS integer
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_tempregno Int;
  v_totalcreditedaddpoints BigInt;
BEGIN
  -- BEGIN TRAN (removed)
  -- SET option (removed)
  BEGIN
  IF NOT EXISTS(SELECT 1 FROM tbl_membersubscriptionaccount WHERE plid = v_plid) THEN
  INSERT INTO tbl_membersubscriptionaccount (plid, noofdaysforactivation, activationdate, tilldate, tsmid, allocatednoofsms, remainnoofsms, allocatednoofemail, remainnoofemail, allocatednoofwhatsupmessage, remainnoofwhatsupmessage, paymentmode, paymentmodename, paymentstatus, bankname, branchname, referenceno, referencedate, activitydate, isactive, status, commentorremark) SELECT v_plid, noofdaysforactivation, CAST(CURRENT_TIMESTAMP AS DATE), CAST((CURRENT_TIMESTAMP + noofdaysforactivation) AS DATE), tsmid, noofsms, noofsms, noofemail, noofemail, noofwhatsupmessage, noofwhatsupmessage, 0, 'N/A', 1, 'N/A', 'N/A', '', NULL, CURRENT_TIMESTAMP, 1, 1, 'Free Trail Subscription' FROM tbl_subscriptionmaster WHERE istrailsubscription = 1 LIMIT 1;
  IF NOT EXISTS(SELECT 1 FROM tbl_memberroiaccount WHERE plid = v_plid) THEN
  v_tempregno := 0;
  v_totalcreditedaddpoints := 0;
  SELECT regno INTO v_tempregno FROM portal_login WHERE plid = v_plid;
  INSERT INTO tbl_memberroiaccount (regno, plid, tsmid, totalcreditedaddpoints, maxnoofclicksperdayforview, priceperlinkforview, maxnooflinkperdayforshare, priceperlinkforshare, maxnoofblogperday, priceperblog, maxnoofclassifiedperday, priceperclassified, lastupdateddate, status, maxpointforview, maxpointforshare, maxpointforblog, maxpointforclassified, perdaypointforblog, perdaypointforclassified, perdaypointforview, perdaypointforshare) SELECT v_tempregno, v_plid, tsmid, totalcreditedaddpoints, maxnoofclicksperdayforview, priceperlinkforview, maxnooflinkperdayforshare, priceperlinkforshare, maxnoofblogperday, priceperblog, maxnoofclassifiedperday, priceperclassified, dbo.FUN_GETCURRENTDATE(), 1, maxpointforview, maxpointforshare, maxpointforblog, maxpointforclaassified, pointperdayforblog, pointperdayforclassified, pointperdayforview, pointperdayforshare FROM tbl_roimaster WHERE tsmid IN (SELECT tsmid FROM tbl_subscriptionmaster WHERE istrailsubscription = 1);
  SELECT totalcreditedaddpoints INTO v_totalcreditedaddpoints FROM tbl_roimaster WHERE tsmid IN (SELECT tsmid FROM tbl_subscriptionmaster WHERE istrailsubscription = 1);
  UPDATE member_performance SET totaltaskpoints = COALESCE(totaltaskpoints, 0) + v_totalcreditedaddpoints WHERE regno = v_tempregno;
  END IF;
  END IF;
  IF (0 = 0) THEN
  v_intresult := 1;
  -- COMMIT (removed)
  RETURN;
  ELSE
  v_intresult := 0;
  -- ROLLBACK (removed)
  RETURN;
  END IF;
  EXCEPTION WHEN OTHERS THEN
  v_intresult := 0;
  -- ROLLBACK (removed)
  RETURN;
  END;
  -- SET option (removed)
  -- COMMIT (removed)
END;
$$;


--
-- Name: usp_transaction_count(character varying, character varying, character varying, character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_transaction_count(v_withdrawalfromdate character varying DEFAULT ''::character varying, v_withdrawaltodate character varying DEFAULT ''::character varying, v_searchfield character varying DEFAULT ''::character varying, v_searchvalue character varying DEFAULT ''::character varying) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_query text;
  v_maxregno text;
  v_query1 text;
  v_username VARCHAR(200);
BEGIN
  v_query := '';
  v_maxregno := '';
  v_query1 := '';
  v_username := '';
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp (REQUEST INT,
	  AMOUNT DECIMAL(18,8),
	  NOOFTRANSACTION INT) ON COMMIT DROP;
  v_query := 'INSERT INTO #TEMP SELECT ISNULL(COUNT(1),0) AS REQUEST,SUM(ISNULL(TCT.WITHDRAWALAMOUNT,0)) AS AMOUNT,COUNT(DISTINCT TCT.CLID) AS NOOFTRANSACTION  
 FROM TBL_CUSTOMER_TRANSFERTOBANK TCT
 WHERE TCT.CLID>0 AND TCT.STATUS=0 AND ISPAID=0 ';
  IF (v_withdrawalfromdate <> '' AND v_withdrawaltodate <> '') THEN
  v_query := v_query || ' AND CONVERT(VARCHAR(12),TCT.WITHDRAWALDATE,105) BETWEEN CONVERT(VARCHAR(12),''' || v_withdrawalfromdate || ''') AND CONVERT(VARCHAR(12),''' || v_withdrawaltodate || ''',105) ';
  ELSE
  IF (v_withdrawalfromdate <> '') THEN
  v_query := v_query || ' AND CONVERT(VARCHAR(12),TCT.WITHDRAWALDATE,105)= CONVERT(VARCHAR(12),''' || v_withdrawalfromdate || ''',105)';
  ELSE
  IF (v_withdrawaltodate <> '') THEN
  v_query := v_query || ' AND CONVERT(VARCHAR(12),TCT.WITHDRAWALDATE,105)= CONVERT(VARCHAR(12),''' || v_withdrawaltodate || ''',105) ';
  END IF;
  END IF;
  END IF;
  v_query := v_query || ' GROUP BY TCT.CLID ';
  RAISE NOTICE '%', v_query;
  EXECUTE v_query;
  RETURN QUERY SELECT COALESCE(SUM(request), 0) AS request, COALESCE(SUM(amount), 0) AS amount, COALESCE(SUM(nooftransaction), 0) AS nooftransaction FROM tmp_temp;
  DROP TABLE IF EXISTS tmp_temp;
END;
$$;


--
-- Name: usp_transaction_count_merchant(character varying, character varying, character varying, character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_transaction_count_merchant(v_withdrawalfromdate character varying DEFAULT ''::character varying, v_withdrawaltodate character varying DEFAULT ''::character varying, v_searchfield character varying DEFAULT ''::character varying, v_searchvalue character varying DEFAULT ''::character varying) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_query text;
  v_maxregno text;
  v_query1 text;
  v_username VARCHAR(200);
BEGIN
  v_query := '';
  v_maxregno := '';
  v_query1 := '';
  v_username := '';
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp (REQUEST INT,
	  AMOUNT DECIMAL(18,8),
	  NOOFTRANSACTION INT) ON COMMIT DROP;
  v_query := 'INSERT INTO #TEMP SELECT ISNULL(COUNT(1),0) AS REQUEST,SUM(ISNULL(TCT.WITHDRAWAMOUNT,0)) AS AMOUNT,COUNT(DISTINCT TCT.PLID) AS NOOFTRANSACTION  
 FROM TBL_MERCHANT_WITHDRAWALS TCT
 WHERE TCT.PLID>0 AND TCT.STATUS=0 ';
  IF (v_withdrawalfromdate <> '' AND v_withdrawaltodate <> '') THEN
  v_query := v_query || ' AND CONVERT(VARCHAR(12),TCT.CREATEDDATE,105) BETWEEN CONVERT(VARCHAR(12),''' || v_withdrawalfromdate || ''') AND CONVERT(VARCHAR(12),''' || v_withdrawaltodate || ''',105) ';
  ELSE
  IF (v_withdrawalfromdate <> '') THEN
  v_query := v_query || ' AND CONVERT(VARCHAR(12),TCT.CREATEDDATE,105)= CONVERT(VARCHAR(12),''' || v_withdrawalfromdate || ''',105)';
  ELSE
  IF (v_withdrawaltodate <> '') THEN
  v_query := v_query || ' AND CONVERT(VARCHAR(12),TCT.CREATEDDATE,105)= CONVERT(VARCHAR(12),''' || v_withdrawaltodate || ''',105) ';
  END IF;
  END IF;
  END IF;
  v_query := v_query || ' GROUP BY TCT.PLID ';
  RAISE NOTICE '%', v_query;
  EXECUTE v_query;
  RETURN QUERY SELECT COALESCE(SUM(request), 0) AS request, COALESCE(SUM(amount), 0) AS amount, COALESCE(SUM(nooftransaction), 0) AS nooftransaction FROM tmp_temp;
  DROP TABLE IF EXISTS tmp_temp;
END;
$$;


--
-- Name: usp_transaction_count_reseller(character varying, character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_transaction_count_reseller(v_withdrawalfromdate character varying DEFAULT ''::character varying, v_withdrawaltodate character varying DEFAULT ''::character varying) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_query text;
  v_maxregno text;
  v_query1 text;
  v_username VARCHAR(200);
