  CREATE TEMP TABLE tmp_temp (REQUEST INT,
	  AMOUNT DECIMAL(18,8),
	  NOOFTRANSACTION INT) ON COMMIT DROP;
  v_query := 'INSERT INTO #TEMP SELECT ISNULL(COUNT(1),0) AS REQUEST,SUM(ISNULL(TCT.AMOUNT,0)) AS AMOUNT,COUNT(DISTINCT TCT.DID) AS NOOFTRANSACTION  
 FROM TBL_RESELLER_TRANSFERTOBANK_REQUEST TCT
 WHERE TCT.DID>0 AND TCT.PAIDSTATUS=0 ';
