  v_query := v_query || ' AND CONVERT(VARCHAR(12),TCT.DATE,105)= CONVERT(VARCHAR(12),''' || v_withdrawaltodate || ''',105) ';
  END IF;
  END IF;
  END IF;
  v_query := v_query || ' GROUP BY TCT.DID ';
  RAISE NOTICE '%', v_query;
  EXECUTE v_query;
  RETURN QUERY SELECT COALESCE(SUM(request), 0) AS request, COALESCE(SUM(amount), 0) AS amount, COALESCE(SUM(nooftransaction), 0) AS nooftransaction FROM tmp_temp;
  DROP TABLE IF EXISTS tmp_temp;
END;
$$;


--
-- Name: usp_transferfromqpay(bigint, numeric, numeric, numeric, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_transferfromqpay(v_qpayregno bigint, v_amount numeric, v_poundamount numeric, v_bonustrans numeric, INOUT v_intresult integer) RETURNS integer
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_plid BIGINT;
  v_countewlt INT;
BEGIN
  -- BEGIN TRAN (removed)
  SELECT plid INTO v_plid FROM portal_login WHERE COALESCE(qpayregno, 0) = v_qpayregno;
  SELECT COUNT(plid) INTO v_countewlt FROM ewallet WHERE plid = v_plid AND active = 1;
  IF (v_countewlt = 0) THEN
  INSERT INTO ewallet (plid, amount, active, cramount) VALUES (v_plid, v_amount, 1, v_amount);
  ELSE
  IF (v_countewlt > 0) THEN
  UPDATE ewallet SET amount = COALESCE(amount, 0.00) + v_amount, cramount = COALESCE(cramount, 0.00) + v_amount WHERE plid = v_plid AND active = 1;
  END IF;
  END IF;
  INSERT INTO member_perfornemce (plid, childpmid, amount, cpmmision_percentage, refincome, date, qpayregno, active, trantype, poundamount, bonustrans) VALUES (v_plid, 0, v_amount, 0, 0, GETUTCDATE(), v_qpayregno, 1, 'Transfer', v_poundamount, v_bonustrans);
  IF (0 <> 0) THEN
  v_intresult := 0;
  -- ROLLBACK (removed)
  RETURN;
  END IF;
  v_intresult := 1;
  -- COMMIT (removed)
END;
$$;


--
-- Name: usp_transferlisting(); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_transferlisting() RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_pmid bigint;
  cr_pmid CURSOR FOR SELECT pmid FROM portal_master WHERE optid = 10 ORDER BY pmid ASC NULLS FIRST;
BEGIN
  -- BEGIN TRAN (removed)
  OPEN cr_pmid;
  FETCH cr_pmid INTO v_pmid;
  WHILE (found) LOOP
  INSERT INTO tbl_listingswithqa (pmid, optid, date, status) VALUES (v_pmid, 13, dbo.fun_getIndiaCurrentDate(), 0);
  IF (0 <> 0) THEN
  CLOSE cr_pmid;
  -- DEALLOCATE (removed)
  -- ROLLBACK (removed)
  RETURN;
  END IF;
  FETCH cr_pmid INTO v_pmid;
  END LOOP;
  CLOSE cr_pmid;
  -- DEALLOCATE (removed)
  -- COMMIT (removed)
END;
$$;


--
-- Name: usp_trending_search_list(integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_trending_search_list(v_did integer DEFAULT 0) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
BEGIN
  RETURN QUERY SELECT COALESCE(type, '') AS producttitle, '' AS categoryin, '' AS producttext, COALESCE(sprid, 0) AS sprid, 0 AS cnt, COALESCE(maincatid, 0) AS maincatid, COALESCE(catid, 0) AS catid, COALESCE(subcatid, 0) AS scatid FROM tbl_trending_search_option AS ts WHERE did = v_did GROUP BY type, sprid, maincatid, catid, subcatid LIMIT 10;
END;
$$;


--
-- Name: usp_trending_search_option(integer, integer, integer, integer, integer, integer, character varying, character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_trending_search_option(v_clid integer DEFAULT 0, v_did integer DEFAULT 0, v_maincatid integer DEFAULT 0, v_catid integer DEFAULT 0, v_subcatid integer DEFAULT 0, v_sprid integer DEFAULT 0, v_type character varying DEFAULT ''::character varying, INOUT v_strresult character varying DEFAULT ''::character varying) RETURNS character varying
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF (v_type <> '' AND v_type <> '0') THEN
  INSERT INTO tbl_trending_search_option VALUES (v_clid, v_did, v_maincatid, v_catid, v_subcatid, v_sprid, v_type, 1);
  v_strresult := '1';
  ELSE
  v_strresult := '0';
  END IF;
END;
$$;


--
-- Name: usp_unvarifylisting_admin(bigint, text, character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_unvarifylisting_admin(v_pmid bigint, v_message text DEFAULT ''::text, INOUT v_strresult character varying DEFAULT NULL::character varying) RETURNS character varying
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_lwqid BIGINT;
  v_optid BIGINT;
  v_listingoptid BIGINT;
  v_plid BIGINT;
  v_result text;
BEGIN
  -- BEGIN TRAN (removed)
  v_strresult := 'OK';
  v_plid := 0;
  v_result := '';
  SELECT lwq_id, optid INTO v_lwqid, v_optid FROM tbl_listingswithqa WHERE v_pmid = pmid;
  SELECT COALESCE(optid, 0) INTO v_listingoptid FROM portal_master WHERE v_pmid = pmid;
  UPDATE portal_master SET isverified = 2 WHERE pmid = v_pmid;
  IF EXISTS(SELECT pmid FROM unvarifiedlisting_master WHERE pmid = v_pmid) THEN
  UPDATE unvarifiedlisting_master SET status = 0 WHERE pmid = v_pmid;
  INSERT INTO unvarifiedlisting_master (pmid, message, optid, qaid, status, date) VALUES (v_pmid, v_message, v_listingoptid, v_optid, 1, dbo.FUN_GETINDIACURRENTDATE());
  ELSE
  INSERT INTO unvarifiedlisting_master (pmid, message, optid, qaid, status, date) VALUES (v_pmid, v_message, v_listingoptid, v_optid, 1, dbo.FUN_GETINDIACURRENTDATE());
  END IF;
  SELECT plid INTO v_plid FROM portal_master WHERE pmid = v_pmid;
  SELECT v_strresult INTO v_result FROM dbo.usp_merchantcat_subcat_keywordmaster(v_mode => 1, v_plid => v_plid, v_tmcskmid => 0, v_category => '', v_subcategory => '', v_keyword => '', v_strresult => v_result);
  RAISE NOTICE '%', v_result;
  IF (0 <> 0) THEN
  -- ROLLBACK (removed)
  v_strresult := 'Some error occured,Please try again !';
  RETURN;
  END IF;
  -- COMMIT (removed)
END;
$$;


--
-- Name: usp_unverified_merchant_list(integer, integer, character varying, character varying, character varying, character varying, integer, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_unverified_merchant_list(v_startrowindex integer DEFAULT 1, v_maxrows integer DEFAULT 50, v_searchfield character varying DEFAULT ''::character varying, v_searchvalue character varying DEFAULT ''::character varying, v_fromdate character varying DEFAULT ''::character varying, v_todate character varying DEFAULT ''::character varying, v_intresult integer DEFAULT 0, v_merchantrelatedto integer DEFAULT 0) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_minindex int;
  v_maxindex int;
  v_query text;
BEGIN
  v_minindex := (v_startrowindex - 1) * v_maxrows + 1;
  v_maxindex := v_startrowindex * v_maxrows;
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp (ROWNUMBER BIGINT GENERATED BY DEFAULT AS IDENTITY,
ROWNUMBER1 BIGINT,
PLID bigint,
LOGINID varchar(150),
DOC varchar(150),
PASSWORD varchar(150),
USERNAME varchar(150),
MEMBERNAME varchar(150),
IPADDRESS  varchar(150),
EMAILID  varchar(150),
PHONE varchar(150),
iskycapproved int,
PMID  int,
Active int,
RELEATEDTO INT) ON COMMIT DROP;
  v_query := 'insert into #temp
                SELECT  ROW_NUMBER() OVER(PARTITION BY PHONE,EMAILID  ORDER BY PLTID desc) AS ROWNUMBER1,(0) as PLID,LOGINID,DOC,PASSWORD,
USERNAME,ISNULL(SP_FIRSTNAME,'''')+''''+ISNULL(SP_LASTNAME,'''') AS MEMBERNAME,isnull(IPADDRESS,'''') as IPADDRESS,
EMAILID,PHONE,(0) as iskycapproved,(0) as PMID,Active,ISNULL(MerchantRelatedTo,0) AS RELEATEDTO  
                    FROM PORTAL_LOGIN_TEMP where active=1
               ';
  v_query := v_query;
  IF (v_merchantrelatedto > 0) THEN
  v_query := v_query || ' AND MerchantRelatedTo= ''' || CAST(v_merchantrelatedto AS VARCHAR(50)) || '''';
  END IF;
  IF (v_searchfield = 'EMAILID') THEN
  v_query := v_query || ' and EMAILID like ''%' || v_searchvalue || '%''';
  END IF;
  IF (v_searchfield = 'MEMBERNAME') THEN
  v_query := v_query || ' and SP_FIRSTNAME like ''%' || v_searchvalue || '%''';
  END IF;
  IF (v_searchfield = 'PHONE') THEN
  v_query := v_query || ' and PHONE like ''%' || v_searchvalue || '%''';
  END IF;
  IF (v_searchfield = 'LOGINID') THEN
  v_searchvalue := REPLACE(v_searchvalue, 'EM', '');
  v_query := v_query || ' and LOGINID like ''%' || v_searchvalue || '%''';
  END IF;
  IF (v_fromdate <> '' AND v_todate <> '') THEN
  v_query := v_query || (' And Convert(date,DOC,105) Between Convert(date,''' || v_fromdate || ''',105) And Convert(date,''' || v_todate || ''',105)');
  END IF;
  IF (v_fromdate <> '') THEN
  v_query := v_query || (' And Convert(date,DOC,105) >= Convert(date,''' || v_fromdate || ''',105)');
  END IF;
  IF (v_todate <> '') THEN
  v_query := v_query || (' And Convert(date,DOC,105) <= Convert(date,''' || v_todate || ''',105)');
  END IF;
  EXECUTE v_query;
  RAISE NOTICE '%', v_query;
  RETURN QUERY SELECT * FROM tmp_temp WHERE rownumber BETWEEN v_minindex AND v_maxindex ORDER BY rownumber ASC NULLS FIRST;
  SELECT COUNT(rownumber) INTO v_intresult FROM tmp_temp;
  DROP TABLE IF EXISTS tmp_temp;
  -- SET option (removed)
END;
$$;


--
-- Name: usp_unverified_reseller_list(integer, integer, character varying, character varying, character varying, character varying, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_unverified_reseller_list(v_startrowindex integer DEFAULT 1, v_maxrows integer DEFAULT 50, v_searchfield character varying DEFAULT ''::character varying, v_searchvalue character varying DEFAULT ''::character varying, v_fromdate character varying DEFAULT ''::character varying, v_todate character varying DEFAULT ''::character varying, v_intresult integer DEFAULT 0) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_minindex int;
  v_maxindex int;
  v_query text;
BEGIN
  v_minindex := (v_startrowindex - 1) * v_maxrows + 1;
  v_maxindex := v_startrowindex * v_maxrows;
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp (ROWNUMBER BIGINT,
PLID bigint,
PLITID int,
LOGINID varchar(150),
DOC varchar(150),
PASSWORD varchar(150),
USERNAME varchar(150),
MEMBERNAME varchar(150),
IPADDRESS  varchar(150),
EMAILID  varchar(150),
PHONE varchar(150),
iskycapproved int,
PMID  int,
isAdminVerifyed int) ON COMMIT DROP;
  v_query := 'insert into #temp  SELECT ROW_NUMBER() OVER(ORDER BY DOC DESC) AS ROWNUMBER,(0) as PLID,PLTID,LOGINID,DOC,PASSWORD,USERNAME,ISNULL(SP_FIRSTNAME,'''')+''''+ISNULL(SP_LASTNAME,'''') AS MEMBERNAME,isnull(IPADDRESS,'''') as IPADDRESS,
			EMAILID,PHONE,(0) as iskycapproved,(0) as PMID,isAdminVerifyed from Distributor_LOGIN_TEMP  where 1=1 and Active=0';
  v_query := v_query;
  IF (v_searchfield = 'EMAILID') THEN
  v_query := v_query || ' and EMAILID like ''%' || v_searchvalue || '%''';
  END IF;
  IF (v_searchfield = 'MEMBERNAME') THEN
  v_query := v_query || ' and SP_FIRSTNAME like ''%' || v_searchvalue || '%''';
  END IF;
  IF (v_searchfield = 'PHONE') THEN
  v_query := v_query || ' and PHONE like ''%' || v_searchvalue || '%''';
  END IF;
  IF (v_fromdate <> '' AND v_todate <> '') THEN
  v_query := v_query || (' And Convert(date,DOC,105) Between Convert(date,''' || v_fromdate || ''',105) And Convert(date,''' || v_todate || ''',105)');
  END IF;
  IF (v_fromdate <> '') THEN
  v_query := v_query || (' And Convert(date,DOC,105) >= Convert(date,''' || v_fromdate || ''',105)');
  END IF;
  IF (v_todate <> '') THEN
  v_query := v_query || (' And Convert(date,DOC,105) <= Convert(date,''' || v_todate || ''',105)');
  END IF;
  EXECUTE v_query;
  RETURN QUERY SELECT * FROM tmp_temp WHERE rownumber BETWEEN v_minindex AND v_maxindex ORDER BY rownumber ASC NULLS FIRST;
  SELECT COUNT(rownumber) INTO v_intresult FROM tmp_temp;
  DROP TABLE IF EXISTS tmp_temp;
  -- SET option (removed)
END;
$$;


--
-- Name: usp_upadteareamaster(text, text, text, text, integer, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_upadteareamaster(v_aid text DEFAULT ''::text, v_sid text DEFAULT ''::text, v_area text DEFAULT ''::text, v_pincode text DEFAULT NULL::text, v_intmode integer DEFAULT 0, INOUT v_result integer DEFAULT NULL::integer) RETURNS integer
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_res int;
  v_cid bigint;
  v_ctid bigint;
  v_stateid bigint;
  v_getcuretncid bigint;
  v_aidcount bigint;
  v_pmidcount bigint;
  v_newpmid bigint;
  v_newpmtid bigint;
BEGIN
  IF (v_intmode = 0) THEN
  UPDATE suggestedarea_master SET active = 0 WHERE said = v_sid;
  v_result := 2;
  ELSE
  UPDATE suggestedarea_master SET areaname = v_area, pincode = v_pincode WHERE said = v_sid;
  SELECT ctid, cid, sid, COALESCE(pmid, 0), COALESCE(pmtid, 0) INTO v_ctid, v_cid, v_stateid, v_newpmid, v_newpmtid FROM suggestedarea_master WHERE said = v_sid;
  SELECT COUNT(aid) INTO v_aidcount FROM area_master WHERE cid = v_cid AND sid = v_stateid AND ctid = v_ctid AND areaname = v_area AND pincode = v_pincode;
  IF (v_aidcount = 0) THEN
  INSERT INTO area_master (cid, sid, ctid, areaname, cactive, pincode, pmid, pmtid) VALUES (v_cid, v_stateid, v_ctid, v_area, 1, v_pincode, 0, 0);
  SELECT aid INTO v_getcuretncid FROM area_master WHERE cid = v_cid AND sid = v_stateid AND ctid = v_ctid AND areaname = v_area AND pincode = v_pincode;
  IF (v_newpmid > 0) THEN
  UPDATE portal_master SET sid = v_stateid, ctid = v_ctid, aid = v_getcuretncid, cid = v_cid WHERE pmid = v_newpmid;
  END IF;
  IF (v_newpmtid > 0) THEN
  UPDATE portal_master_temp SET sid = v_stateid, ctid = v_ctid, aid = v_getcuretncid, cid = v_cid WHERE pmtid = v_newpmtid;
  UPDATE portal_master SET sid = v_stateid, ctid = v_ctid, aid = v_getcuretncid, cid = v_cid WHERE pmtid = v_newpmtid;
  END IF;
  END IF;
  UPDATE suggestedarea_master SET active = 0 WHERE said = v_sid;
  v_result := 1;
  END IF;
END;
$$;


--
-- Name: usp_update_affiliate_admin_charge(character varying, numeric, boolean, integer, character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_update_affiliate_admin_charge(v_config_name character varying, v_value numeric, INOUT v_out_status boolean, INOUT v_out_result integer, INOUT v_out_message character varying) RETURNS record
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF (COALESCE(v_config_name, '') = '') THEN
  v_out_status := 0;
  v_out_result := 0;
  v_out_message := 'invalid action';
  RETURN;
  END IF;
  IF (CAST(v_value AS DECIMAL) < 0) THEN
  v_out_status := 0;
  v_out_result := 0;
  v_out_message := 'Charge should be grater then zero';
  RETURN;
  END IF;
  UPDATE configuration_master SET config_value = v_value WHERE config_name = v_config_name;
  v_out_status := 1;
  v_out_result := 1;
  v_out_message := 'updated Succesfully';
END;
$$;


--
-- Name: usp_update_affiliate_bonus(integer, character varying, numeric, integer, integer, integer, character, boolean, integer, character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_update_affiliate_bonus(v_abpid integer, v_bonus_type character varying, v_bonus_value numeric, v_redeedays integer, v_sprid integer, v_created_by integer, v_status character, INOUT v_out_status boolean DEFAULT false, INOUT v_out_result integer DEFAULT 0, INOUT v_out_message character varying DEFAULT ''::character varying) RETURNS record
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF NOT EXISTS(SELECT 1 FROM affiliate_bonus_on_product WHERE sprid = v_sprid AND abpid = v_abpid) THEN
  v_out_status := 0;
  v_out_result := 0;
  v_out_message := 'Invalid Request';
  RETURN;
  END IF;
  IF NOT EXISTS(SELECT 1 FROM ims_masterproduct AS mp INNER JOIN ims_subproduct AS sp ON sp.mprid = mp.mprid WHERE sp.sprid = v_sprid AND mp.branchid = v_created_by) THEN
  v_out_status := 0;
  v_out_result := 0;
  v_out_message := 'not authorized to submit';
  RETURN;
  END IF;
  IF NOT EXISTS(SELECT 1 FROM ims_subproduct WHERE sprid = v_sprid AND isverified = 1) THEN
  v_out_status := 0;
  v_out_result := 0;
  v_out_message := 'Product is Inactive';
  RETURN;
  END IF;
  UPDATE affiliate_bonus_on_product SET bonus_type = v_bonus_type, bonus_value = v_bonus_value, redeem_after_days = v_redeedays, status = v_status WHERE sprid = v_sprid AND abpid = v_abpid;
  v_out_status := 1;
  v_out_result := 1;
  v_out_message := 'Affiliate bonus Re-Request Successfully';
END;
$$;


--
-- Name: usp_update_bank_excel(character varying, character varying, character varying, character varying, character varying, character varying, numeric, integer, character varying, character varying, character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_update_bank_excel(v_requestid character varying DEFAULT ''::character varying, v_accountholdername character varying DEFAULT ''::character varying, v_bankname character varying DEFAULT ''::character varying, v_accountno character varying DEFAULT ''::character varying, v_ifsccode character varying DEFAULT ''::character varying, v_branchname character varying DEFAULT ''::character varying, v_amount numeric DEFAULT 0, v_plid integer DEFAULT 0, v_transactionid character varying DEFAULT ''::character varying, v_transactiondate character varying DEFAULT ''::character varying, INOUT v_strresult character varying DEFAULT ''::character varying) RETURNS character varying
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_temp_plid bigint;
BEGIN
  -- BEGIN TRAN (removed)
  v_temp_plid := 0;
  IF (v_transactiondate = '') THEN
  v_strresult := 'ERROR^TRANSACTION DATE IS NOT DEFINED';
  -- COMMIT (removed)
  RETURN;
  END IF;
  IF (v_transactionid = '') THEN
  v_strresult := 'ERROR^TRANSACTION ID  NOT DEFINED';
  -- COMMIT (removed)
  RETURN;
  END IF;
  IF EXISTS(SELECT 1 FROM tbl_uploaded_bank_payout_excel WHERE transactionid = v_transactionid) THEN
  v_strresult := 'NOT OK^ALREADY EXIST';
  END IF;
  IF NOT EXISTS(SELECT 1 FROM tbl_uploaded_bank_payout_excel WHERE transactionid = v_transactionid) THEN
  IF EXISTS(SELECT 1 FROM bank_accounts_merchant WHERE accountholdername = v_accountholdername AND accountno = v_accountno AND ifsccode = v_ifsccode AND active = 1) THEN
  SELECT COALESCE(plid, 0) INTO v_temp_plid FROM bank_accounts_merchant WHERE accountholdername = v_accountholdername AND accountno = v_accountno AND ifsccode = v_ifsccode AND active = 1;
  UPDATE tbl_merchant_withdrawals SET remainamount = 0, trans_id = v_transactionid, date = v_transactiondate, status = 'Released', paid_status = 'Paid' WHERE plid = v_temp_plid AND paybleamount = v_amount AND status = 'PENDING' AND paid_status = 'Unpaid';
  END IF;
  INSERT INTO tbl_uploaded_bank_payout_excel (accountholdername, bankname, branchname, ifsccode, accountno, amount, transactionid, transactiondate, status, requestid) VALUES (v_accountholdername, v_bankname, v_branchname, v_ifsccode, v_accountno, v_amount, v_transactionid, v_transactiondate, 1, v_requestid);
  v_strresult := 'OK^UPLOADED SUCCESSFULLY';
  END IF;
  IF (0 <> 0) THEN
  -- ROLLBACK (removed)
  v_strresult := 'ERROR^' || 0;
  RETURN;
  END IF;
  -- COMMIT (removed)
END;
$$;


