--
-- Name: usp_update_courier_list(character varying, character varying, character varying, character varying, character varying, integer, character varying, text, integer, character varying, character varying, character varying, character varying, character varying, character varying, character varying, numeric, numeric, character varying, character varying, character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_update_courier_list(v_orderid character varying DEFAULT 'OD390330954'::character varying, v_docketno character varying DEFAULT ''::character varying, v_weight character varying DEFAULT ''::character varying, v_status character varying DEFAULT 'Intransit'::character varying, v_typeofservice character varying DEFAULT ''::character varying, v_plid integer DEFAULT 1, INOUT v_strresult character varying DEFAULT ''::character varying, v_productname text DEFAULT '2dozay M9 Bluetooth Smart Watch (Silver)'::text, v_no_of_piece integer DEFAULT 1, v_customer_name character varying DEFAULT ''::character varying, v_shipping_add1 character varying DEFAULT '4/8 2nd F Nehru Nagar Lajpata Nagar, Address 2'::character varying, v_shipping_add2 character varying DEFAULT 'N/A'::character varying, v_city character varying DEFAULT 'DELHI'::character varying, v_state character varying DEFAULT 'DELHI'::character varying, v_pincode character varying DEFAULT '110065'::character varying, v_mobile character varying DEFAULT '9650020493'::character varying, v_invoicevalue numeric DEFAULT 17400, v_collectableamount numeric DEFAULT 0, v_dtdcstatus character varying DEFAULT ''::character varying, v_statusdate character varying DEFAULT '25/2/2020'::character varying, v_ordernoexcel character varying DEFAULT '837276'::character varying) RETURNS character varying
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_intstatus INT;
  v_autoremark VARCHAR(150);
  v_orderstatus VARCHAR(100);
  v_orderno VARCHAR(100);
  v_allorderno text;
  v_excelstatus INT;
  v_invoiceno VARCHAR(100);
  v_invioicedate timestamp;
  v_dispatchdate timestamp;
  v_duedate timestamp;
  v_totalinvoicevalue DECIMAl(18,2);
  v_sta VARCHAR(200);
  v_tempplid INT;
BEGIN
  -- BEGIN TRAN (removed)
  v_intstatus := 0;
  v_autoremark := '';
  v_orderstatus := '';
  v_orderno := '';
  v_allorderno := '';
  v_excelstatus := 0;
  v_invoiceno := '';
  v_invioicedate := '';
  v_dispatchdate := '';
  v_duedate := '';
  v_totalinvoicevalue := 0;
  IF (v_status = '') THEN
  v_strresult := 'ERROR^STATUS IS NOT DEFINED';
  -- COMMIT (removed)
  RETURN;
  END IF;
  v_sta := '';
  SELECT status INTO v_sta FROM tbl_product_order_master WHERE orderno = v_ordernoexcel;
  IF (v_sta = 'Completed') THEN
  v_strresult := 'OK^UPDATE STATUS';
  -- COMMIT (removed)
  RETURN;
  END IF;
  IF (v_status = 'PACKED') THEN
  IF (v_sta <> 'PACKED') THEN
  UPDATE tbl_product_order_master SET intstatus = 2, status = 'PACKED' WHERE orderno = v_ordernoexcel;
  END IF;
  v_strresult := 'OK^UPDATE STATUS';
  -- COMMIT (removed)
  RETURN;
  END IF;
  IF (v_status = 'HANDOVER') THEN
  IF (v_sta <> 'Ready for Dispatch') THEN
  UPDATE tbl_product_order_master SET intstatus = 3, status = 'READY FOR DISPATCH' WHERE orderno = v_ordernoexcel;
  UPDATE tbl_order_confirmedstaus SET handover = dbo.FUN_GETCURRENTDATE() WHERE orderno = v_ordernoexcel;
  UPDATE tbl_customer_notifications SET notificationdate = dbo.FUN_GETCURRENTDATE(), isread = 0, active = 1, isreaddate = NULL WHERE referenceid = v_ordernoexcel;
  END IF;
  v_strresult := 'OK^UPDATE STATUS';
  -- COMMIT (removed)
  RETURN;
  END IF;
  v_excelstatus := 1;
  IF EXISTS(SELECT orderid FROM tbl_invoicedetailsmaster WHERE orderid = v_orderid AND orderno = v_ordernoexcel) THEN
  IF (v_excelstatus = 1) THEN
  SELECT statusname, osid INTO v_orderstatus, v_intstatus FROM orderstatusmaster WHERE osid = 4;
  END IF;
  IF (v_excelstatus = 2) THEN
  SELECT statusname, osid INTO v_orderstatus, v_intstatus FROM orderstatusmaster WHERE osid = 9;
  END IF;
  IF (v_excelstatus = 3) THEN
  SELECT statusname, osid INTO v_orderstatus, v_intstatus FROM orderstatusmaster WHERE osid = 6;
  END IF;
  SELECT COALESCE(v_allorderno || ',', '') || orderno INTO v_allorderno FROM tbl_invoicedetailsmaster WHERE orderid = v_orderid;
  v_allorderno := SUBSTRING(v_allorderno FROM 2 FOR LENGTH(CAST(v_allorderno AS TEXT)));
  IF EXISTS(SELECT 1 FROM tbl_invoicedetailsmaster WHERE orderid = v_orderid AND remark = '' AND orderno = v_ordernoexcel AND type_of_service = '') THEN
  UPDATE tbl_invoicedetailsmaster SET weight = v_weight, remark = v_status, type_of_service = v_typeofservice, tracking_no = v_docketno WHERE orderid = v_orderid AND orderno = v_ordernoexcel;
  UPDATE tbl_product_order_master SET status = v_status, intstatus = v_intstatus, docketno = v_docketno WHERE orderid = v_orderid AND orderno = v_ordernoexcel;
  UPDATE tbl_order_confirmedstaus SET intransit = v_statusdate WHERE orderid = v_orderid AND orderno = v_ordernoexcel;
  UPDATE dbo.tbl_customer_notifications SET isread = 0, active = 1, isreaddate = NULL, notificationdate = dbo.FUN_GETCURRENTDATE() WHERE orderid = v_orderid;
  END IF;
  v_autoremark := 'ORDER NO ' || v_orderid || ' STATUS HAS BEEN CHANGE TO ' || v_status || ' BY  EMP CODE:' || CAST(v_plid AS VARCHAR(20)) || ' (BRID:' || CAST(v_plid AS VARCHAR(20)) || ')';
  INSERT INTO tbl_ordernotes (orderid, date, remark, brcode, emp_code, active, status, intstatus, orderno) VALUES (v_orderid, dbo.FUN_GETCURRENTDATE(), v_autoremark, CAST(v_plid AS VARCHAR(20)), CAST(v_plid AS VARCHAR(20)), 1, v_status, v_intstatus, v_ordernoexcel);
  v_strresult := 'OK^UPDATE STATUS';
  v_tempplid := 0;
  SELECT invoiceno, invoice_date, plid INTO v_invoiceno, v_invioicedate, v_tempplid FROM tbl_invoicedetailsmaster WHERE orderid = v_orderid AND tracking_no = v_docketno;
  SELECT COALESCE(intransit, '') INTO v_dispatchdate FROM tbl_order_confirmedstaus WHERE orderno IN (SELECT value FROM dbo.SPLITSTRINGBYCOMMA(v_allorderno)) LIMIT 1;
  SELECT COALESCE(SUM(total_purchase_cost), 0) INTO v_totalinvoicevalue FROM tbl_product_order_master WHERE orderno IN (SELECT value FROM dbo.SPLITSTRINGBYCOMMA(v_allorderno));
  IF (v_dispatchdate <> '') THEN
  SELECT NULL INTO v_duedate;
  v_statusdate := NULL;
  END IF;
  IF NOT EXISTS(SELECT 1 FROM tbl_merchant_ordertransactions WHERE invoiceno = v_invoiceno) THEN
  INSERT INTO tbl_merchant_ordertransactions (invoiceno, invoicedate, orderid, dispatchdate, deliverydate, duedate, invoiceamount, status, active, createdate, plid) VALUES (v_invoiceno, v_invioicedate, v_orderid, v_dispatchdate, v_statusdate, v_duedate, v_totalinvoicevalue, 'INPROCESS', 1, dbo.FUN_GETCURRENTDATE(), v_tempplid);
  END IF;
  ELSE
  v_strresult := 'ERROR^INVALID ORDER NO';
  -- COMMIT (removed)
  RETURN;
  END IF;
  IF (0 <> 0) THEN
  -- ROLLBACK (removed)
  v_strresult := 'ERROR^' || 0;
  RETURN;
  END IF;
  -- COMMIT (removed)
END;
$$;


--
-- Name: usp_update_courier_list_complete(character varying, character varying, character varying, character varying, character varying, integer, character varying, text, integer, character varying, character varying, character varying, character varying, character varying, character varying, character varying, numeric, numeric, character varying, character varying, character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_update_courier_list_complete(v_orderid character varying DEFAULT ''::character varying, v_docketno character varying DEFAULT ''::character varying, v_weight character varying DEFAULT ''::character varying, v_status character varying DEFAULT ''::character varying, v_typeofservice character varying DEFAULT ''::character varying, v_plid integer DEFAULT 600001, INOUT v_strresult character varying DEFAULT ''::character varying, v_productname text DEFAULT ''::text, v_no_of_piece integer DEFAULT 0, v_customer_name character varying DEFAULT ''::character varying, v_shipping_add1 character varying DEFAULT ''::character varying, v_shipping_add2 character varying DEFAULT ''::character varying, v_city character varying DEFAULT ''::character varying, v_state character varying DEFAULT ''::character varying, v_pincode character varying DEFAULT ''::character varying, v_mobile character varying DEFAULT ''::character varying, v_invoicevalue numeric DEFAULT 0, v_collectableamount numeric DEFAULT 0, v_dtdcstatus character varying DEFAULT ''::character varying, v_statusdate character varying DEFAULT ''::character varying, v_orderno character varying DEFAULT ''::character varying) RETURNS character varying
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_intstatus INT;
  v_autoremark VARCHAR(150);
  v_orderstatus VARCHAR(100);
  v_allorderno text;
  v_excelstatus INT;
  v_totalcountorder int;
  v_tocompleteorder int;
  v_duedate timestamp;
BEGIN
  -- BEGIN TRAN (removed)
  v_intstatus := 0;
  v_duedate := '';
  IF (v_status = '') THEN
  v_strresult := 'ERROR^STATUS IS NOT DEFINED';
  -- COMMIT (removed)
  RETURN;
  END IF;
  SELECT COALESCE(csid, 0) INTO v_excelstatus FROM tbl_courierexcelstatuslist WHERE statusname = v_status AND status = 1;
  IF EXISTS(SELECT orderid FROM tbl_invoicedetailsmaster WHERE orderid = v_orderid AND orderno = v_orderno) THEN
  UPDATE tbl_invoicedetailsmaster SET tracking_no = v_docketno WHERE orderid = v_orderid AND orderno = v_orderno;
  IF (v_excelstatus = 2) THEN
  SELECT statusname, osid INTO v_orderstatus, v_intstatus FROM orderstatusmaster WHERE osid = 9;
  ELSE
  IF (v_excelstatus = 3) THEN
  SELECT statusname, osid INTO v_orderstatus, v_intstatus FROM orderstatusmaster WHERE osid = 6;
  END IF;
  END IF;
  SELECT COALESCE(v_allorderno || ',', '') || orderno INTO v_allorderno FROM tbl_invoicedetailsmaster WHERE orderid = v_orderid AND tracking_no = v_docketno;
  v_allorderno := SUBSTRING(v_allorderno FROM 1 FOR LENGTH(CAST(v_allorderno AS TEXT)));
  IF EXISTS(SELECT orderid FROM tbl_product_order_master WHERE orderid = v_orderid) THEN
  UPDATE tbl_product_order_master SET status = v_orderstatus, intstatus = v_intstatus WHERE orderno IN (SELECT value FROM dbo.SPLITSTRINGBYCOMMA(v_allorderno));
  IF (v_excelstatus = 2) THEN
  UPDATE tbl_order_confirmedstaus SET outfordelivery = v_statusdate, status = v_intstatus WHERE orderno IN (SELECT value FROM dbo.SPLITSTRINGBYCOMMA(v_allorderno));
  ELSE
  IF (v_excelstatus = 3) THEN
  IF (v_statusdate <> '') THEN
  SELECT v_statusdate + INTERVAL '15 DAY' INTO v_duedate;
  END IF;
  UPDATE tbl_order_confirmedstaus SET delivered = v_statusdate, status = v_intstatus WHERE orderno IN (SELECT value FROM dbo.SPLITSTRINGBYCOMMA(v_allorderno));
  UPDATE tbl_merchant_ordertransactions SET deliverydate = v_statusdate, status = 'DELIVERED', duedate = v_duedate WHERE orderid = v_orderid;
  END IF;
  END IF;
  SELECT COUNT(1) INTO v_totalcountorder FROM tbl_product_order_master WHERE orderid = v_orderid AND intstatus <> 7;
  SELECT COUNT(1) INTO v_tocompleteorder FROM tbl_product_order_master WHERE orderid = v_orderid AND intstatus = v_intstatus;
  IF (v_totalcountorder = v_tocompleteorder) THEN
  UPDATE tbl_order_master SET status = v_orderstatus, intstatus = v_intstatus, description = v_dtdcstatus WHERE orderid = v_orderid;
  END IF;
  END IF;
  UPDATE dbo.tbl_customer_notifications SET isread = 0, active = 1, isreaddate = NULL, notificationdate = dbo.FUN_GETCURRENTDATE() WHERE orderid = v_orderid;
  UPDATE tbl_merchant_notifications SET isread = 0, active = 1, notificationdate = dbo.FUN_GETCURRENTDATE() WHERE orderid = v_orderid;
  v_autoremark := 'ORDER NO ' || v_orderid || ' STATUS HAS BEEN CHANGE TO ' || v_status || ' BY  EMP CODE:' || CAST(v_plid AS VARCHAR(20)) || ' (BRID:' || CAST(v_plid AS VARCHAR(20)) || ')';
  INSERT INTO tbl_ordernotes (orderid, date, remark, brcode, emp_code, active, status, intstatus, orderno) VALUES (v_orderid, dbo.FUN_GETCURRENTDATE(), v_autoremark, CAST(v_plid AS VARCHAR(20)), CAST(v_plid AS VARCHAR(20)), 1, v_status, v_intstatus, v_allorderno);
  v_strresult := 'OK^UPDATE STATUS';
  INSERT INTO tbl_courier_statusexceldata (orderid, productname, no_of_piece, customer_name, shipping_address1, shipping_address2, city, state, pincode, mobileno, invoicevalue, collectable_amount, docket_no, weight, statusname, intstaus, typeofservice, status, credate_date, uploadstatus, dtdcstaus, statusdate) VALUES (v_orderid, v_productname, v_no_of_piece, v_customer_name, v_shipping_add1, v_shipping_add2, v_city, v_state, v_pincode, v_mobile, v_invoicevalue, v_collectableamount, v_docketno, v_weight, v_status, v_excelstatus, v_typeofservice, 1, dbo.FUN_GETCURRENTDATE(), 'INTRANSIT UPLOAD DATA', v_dtdcstatus, v_statusdate);
  ELSE
  v_strresult := 'ERROR^INVALID ORDER NO';
  -- COMMIT (removed)
  RETURN;
  END IF;
  IF (0 <> 0) THEN
  -- ROLLBACK (removed)
  v_strresult := 'ERROR^' || 0;
  RETURN;
  END IF;
  -- COMMIT (removed)
END;
$$;


--
-- Name: usp_update_customer_bankwithdrawalstatus_byexecll(character varying, character varying, character varying, character varying, character varying, character varying, character varying, character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_update_customer_bankwithdrawalstatus_byexecll(v_groupnumber character varying DEFAULT '00674082092444400753299'::character varying, v_accountno character varying DEFAULT ''::character varying, v_status character varying DEFAULT ''::character varying, v_processby character varying DEFAULT ''::character varying, v_processipaddress character varying DEFAULT '1'::character varying, INOUT v_strresult character varying DEFAULT ''::character varying, v_mode character varying DEFAULT '2'::character varying, v_utrno character varying DEFAULT ''::character varying) RETURNS character varying
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_getchid INT;
  v_getallwdid text;
  v_getupdatestatus text;
BEGIN
  v_getchid := 0;
  v_getallwdid := '';
  SELECT chid INTO v_getchid FROM tbl_customer_clubhistory WHERE clubgroup = v_groupnumber;
  v_strresult := '1';
  v_getupdatestatus := '';
  IF (v_mode = 2) THEN
  SELECT RIGHT(CAST(allwdid AS TEXT), LENGTH(CAST(allwdid AS TEXT)) - 1) INTO v_getallwdid FROM tbl_customer_clubhistory WHERE chid = v_getchid;
  v_getupdatestatus := 'UPDATE TBL_CUSTOMER_TRANSFERTOBANK SET STATUS=0,ISPAID=0 WHERE TCTTB IN  (SELECT * FROM SPLITSTRING(''' || v_getallwdid || ''','',''))';
  EXECUTE v_getupdatestatus;
  UPDATE tbl_customer_downloadclubdata SET status = 2, processby = v_processby, processipaddress = v_processipaddress, processdate = dbo.FUN_GETCURRENTDATE() WHERE chid = v_getchid;
  UPDATE tbl_customer_clubhistory SET processstatus = 2, processby = v_processby, processipaddress = v_processipaddress, processdate = dbo.FUN_GETCURRENTDATE() WHERE chid = v_getchid;
  v_strresult := '1';
  END IF;
  IF (v_mode = 1) THEN
  SELECT RIGHT(CAST(allwdid AS TEXT), LENGTH(CAST(allwdid AS TEXT)) - 1) INTO v_getallwdid FROM tbl_customer_downloadclubdata WHERE chid = v_getchid AND accountnumber = v_accountno;
  v_getupdatestatus := 'UPDATE TBL_CUSTOMER_TRANSFERTOBANK SET STATUS=1,TRANSACTIONID=''' || v_utrno || ''',ISPAID=1 WHERE TCTTB IN  (SELECT * FROM SPLITSTRING(''' || v_getallwdid || ''','',''))';
  EXECUTE v_getupdatestatus;
  UPDATE tbl_customer_downloadclubdata SET status = 1, processby = v_processby, processipaddress = v_processipaddress, processdate = dbo.FUN_GETCURRENTDATE() WHERE chid = v_getchid AND accountnumber = v_accountno;
  UPDATE tbl_customer_clubhistory SET processstatus = 1, processby = v_processby, processipaddress = v_processipaddress, processdate = dbo.FUN_GETCURRENTDATE() WHERE chid = v_getchid;
  v_strresult := '1';
  END IF;
END;
$$;


--
-- Name: usp_update_customer_dth_recharge_response(character varying, character varying, character varying, text, character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_update_customer_dth_recharge_response(v_custtransactionid character varying DEFAULT '1174857003'::character varying, v_apitransactionid character varying DEFAULT ''::character varying, v_rechargeresponsestatus character varying DEFAULT 'FAILED'::character varying, v_rechargeresponseremarks text DEFAULT 'RECHARGE FAILED'::text, INOUT v_stroutput character varying DEFAULT ''::character varying) RETURNS character varying
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_clid INT;
  v_custwallet DECIMAL(18,2);
  v_custrechargeamount DECIMAL(18,2);
  v_did INT;
  v_oldbalance DECIMAL(18,2);
  v_newbalance DECIMAL(18,2);
  v_custmobile VARCHAR(20);
  v_rechargeoperator VARCHAR(100);
  v_commissionper DECIMAL(18,2);
  v_bv DECIMAL(18,2);
  v_strresult VARCHAR(100);
  v_operatorname VARCHAR(100);
  v_amount DECIMAL(18,2);
  v_reselleroldbalance DECIMAL(18,2);
  v_resellernewbalance DECIMAL(18,2);
BEGIN
  BEGIN
  -- BEGIN TRAN (removed)
  v_clid := 0;
  v_custwallet := 0;
  v_custrechargeamount := 0;
  v_did := 0;
  v_oldbalance := 0;
  v_newbalance := 0;
  v_custmobile := '';
  v_rechargeoperator := '';
  v_commissionper := 0;
  SELECT clid, rechargeamount, mobileno, operatorname INTO v_clid, v_custrechargeamount, v_custmobile, v_rechargeoperator FROM dbo.tbl_customer_dth_recharges WHERE transactionid = v_custtransactionid;
  IF (v_custtransactionid <> '' AND v_apitransactionid <> '' AND (UPPER(v_rechargeresponsestatus) = 'SUCCESS' OR UPPER(v_rechargeresponsestatus) = 'PENDING')) THEN
  IF EXISTS(SELECT 1 FROM dbo.tbl_customer_dth_recharges WHERE transactionid = v_custtransactionid AND rechargestatus IS NULL) THEN
  UPDATE dbo.tbl_customer_dth_recharges SET apitransactionid = v_apitransactionid, rechargestatus = v_rechargeresponsestatus, responsedate = dbo.FUN_GETCURRENTDATE(), responseremarks = v_rechargeresponseremarks WHERE transactionid = v_custtransactionid AND rechargestatus IS NULL;
  v_bv := 0;
  v_strresult := '';
  v_operatorname := '';
  v_amount := 0;
  SELECT COALESCE(did, 0) INTO v_did FROM tbl_customerlogin WHERE clid = v_clid;
  SELECT COALESCE(admincommission, 0), COALESCE(operatorname, ''), COALESCE(rechargeamount, 0) INTO v_bv, v_operatorname, v_amount FROM tbl_customer_dth_recharges WHERE transactionid = v_custtransactionid;
  SELECT v_strresult INTO v_strresult FROM dbo.usp_utility_reseller_bv_pv_commission(v_did => v_did, v_custtransactionid => v_custtransactionid, v_operatorname => v_operatorname, v_amount => v_amount, v_strresult => v_strresult);
  SELECT v_strresult INTO v_strresult FROM dbo.usp_insert_bv_utility(v_did => v_did, v_transaid => v_custtransactionid, v_bv => v_bv, v_strresult => v_strresult);
  SELECT COALESCE(resellercommission, 0) INTO v_commissionper FROM tbl_customer_dth_recharges WHERE transactionid = v_custtransactionid;
  INSERT INTO tbl_reseller_commission_wallet (did, crtype, totalamount, commissionpercentage, cr, dr, traceno, remarks, servicetype, status, transdate) VALUES (v_did, 'CR', v_custrechargeamount, v_commissionper, CAST((v_custrechargeamount * v_commissionper) AS DECIMAL(18, 9)) / 100, 0, v_custtransactionid, 'Wallet credited against ' || CAST(v_rechargeoperator AS VARCHAR(100)) || ' Recharge on ' || CAST(v_custmobile AS VARCHAR(20)) || ' ', 1, 1, dbo.FUN_GETCURRENTDATE());
  END IF;
  v_stroutput := 'SUCCESS';
  -- COMMIT (removed)
  ELSE
  IF EXISTS(SELECT 1 FROM dbo.tbl_customer_dth_recharges WHERE transactionid = v_custtransactionid AND rechargestatus IS NULL) THEN
