  UPDATE dbo.tbl_customer_postpaid_recharges SET apitransactionid = v_apitransactionid, rechargestatus = v_rechargeresponsestatus, responsedate = dbo.FUN_GETCURRENTDATE(), responseremarks = v_rechargeresponseremarks WHERE transactionid = v_custtransactionid AND rechargestatus IS NULL;
