-- Name: usp_update_customer_prepaid_recharge_response(character varying, character varying, character varying, text, character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_update_customer_prepaid_recharge_response(v_custtransactionid character varying DEFAULT ''::character varying, v_apitransactionid character varying DEFAULT ''::character varying, v_rechargeresponsestatus character varying DEFAULT ''::character varying, v_rechargeresponseremarks text DEFAULT ''::text, INOUT v_stroutput character varying DEFAULT ''::character varying) RETURNS character varying
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_clid INT;
  v_custwallet DECIMAL(18,2);
  v_custrechargeamount DECIMAL(18,2);
  v_did INT;
  v_oldbalance DECIMAL(18,2);
  v_newbalance DECIMAL(18,2);
  v_custmobile VARCHAR(20);
  v_rechargeoperator VARCHAR(100);
  v_commissionper DECIMAL(18,2);
  v_bv DECIMAL(18,2);
  v_strresult VARCHAR(100);
  v_operatorname VARCHAR(100);
  v_amount DECIMAL(18,2);
  v_reselleroldbalance DECIMAL(18,2);
  v_resellernewbalance DECIMAL(18,2);
BEGIN
  BEGIN
  -- BEGIN TRAN (removed)
  v_clid := 0;
  v_custwallet := 0;
  v_custrechargeamount := 0;
  v_did := 0;
  v_oldbalance := 0;
  v_newbalance := 0;
  v_custmobile := '';
  v_rechargeoperator := '';
  v_commissionper := 0;
  SELECT clid, rechargeamount, mobileno, operatorname INTO v_clid, v_custrechargeamount, v_custmobile, v_rechargeoperator FROM dbo.tbl_customer_prepaid_recharges WHERE transactionid = v_custtransactionid;
  IF (v_custtransactionid <> '' AND v_apitransactionid <> '' AND (UPPER(v_rechargeresponsestatus) = 'SUCCESS' OR UPPER(v_rechargeresponsestatus) = 'PENDING')) THEN
  IF EXISTS(SELECT 1 FROM dbo.tbl_customer_prepaid_recharges WHERE transactionid = v_custtransactionid AND rechargestatus IS NULL) THEN
  UPDATE dbo.tbl_customer_prepaid_recharges SET apitransactionid = v_apitransactionid, rechargestatus = v_rechargeresponsestatus, responsedate = dbo.FUN_GETCURRENTDATE(), responseremarks = v_rechargeresponseremarks WHERE transactionid = v_custtransactionid AND rechargestatus IS NULL;
  v_bv := 0;
  v_strresult := '';
  v_operatorname := '';
  v_amount := 0;
  SELECT COALESCE(did, 0) INTO v_did FROM tbl_customerlogin WHERE clid = v_clid;
  SELECT COALESCE(admincommission, 0), COALESCE(operatorname, ''), COALESCE(rechargeamount, 0) INTO v_bv, v_operatorname, v_amount FROM tbl_customer_prepaid_recharges WHERE transactionid = v_custtransactionid;
  SELECT v_strresult INTO v_strresult FROM dbo.usp_utility_reseller_bv_pv_commission(v_did => v_did, v_custtransactionid => v_custtransactionid, v_operatorname => v_operatorname, v_amount => v_amount, v_strresult => v_strresult);
  SELECT v_strresult INTO v_strresult FROM dbo.usp_insert_bv_utility(v_did => v_did, v_transaid => v_custtransactionid, v_bv => v_bv, v_strresult => v_strresult);
  SELECT COALESCE(admincommission, 0) INTO v_commissionper FROM tbl_customer_prepaid_recharges WHERE transactionid = v_custtransactionid;
  INSERT INTO tbl_reseller_commission_wallet (did, crtype, totalamount, commissionpercentage, cr, dr, traceno, remarks, servicetype, status, transdate) VALUES (v_did, 'CR', v_custrechargeamount, v_commissionper, CAST((v_custrechargeamount * v_commissionper) AS DECIMAL(18, 9)) / 100, 0, v_custtransactionid, 'Wallet credited against ' || CAST(v_rechargeoperator AS VARCHAR(100)) || ' Recharge on ' || CAST(v_custmobile AS VARCHAR(20)) || ' ', 1, 1, dbo.FUN_GETCURRENTDATE());
  END IF;
  v_stroutput := 'SUCCESS';
  -- COMMIT (removed)
  ELSE
  IF EXISTS(SELECT 1 FROM dbo.tbl_customer_prepaid_recharges WHERE transactionid = v_custtransactionid AND rechargestatus IS NULL) THEN
  IF (UPPER(v_rechargeresponsestatus) = 'FAILED' OR UPPER(v_rechargeresponsestatus) = 'FAILURE' OR UPPER(v_rechargeresponsestatus) = 'ERROR') THEN
  SELECT COALESCE(availablebalance, 0) INTO v_oldbalance FROM tbl_customerwallet WHERE clid = v_clid;
  SELECT v_oldbalance + v_custrechargeamount INTO v_newbalance;
  UPDATE tbl_customerwallet SET availablebalance = availablebalance + v_custrechargeamount WHERE clid = v_clid;
  INSERT INTO tbl_customerwallet_statements (clid, processdate, crdrtype, cramt, dramt, old_balance, balance, remarks, traceno, status) VALUES (v_clid, dbo.FUN_GETCURRENTDATE(), 'CR', v_custrechargeamount, 0, v_oldbalance, v_newbalance, 'Wallet credited against refund for ' || CAST(v_rechargeoperator AS VARCHAR(100)) || ' Recharge on ' || CAST(v_custmobile AS VARCHAR(20)) || ' ', v_custtransactionid, 1);
  v_reselleroldbalance := 0;
  v_resellernewbalance := 0;
  SELECT did INTO v_did FROM tbl_customerlogin WHERE clid = v_clid;
  SELECT COALESCE(available_wallet, 0) INTO v_reselleroldbalance FROM tbl_distributor_prepaid_setting WHERE pmid = v_did;
  SELECT v_reselleroldbalance + v_custrechargeamount INTO v_resellernewbalance;
  UPDATE tbl_distributor_prepaid_setting SET available_wallet = COALESCE(available_wallet, 0) + v_custrechargeamount WHERE pmid = v_did;
  INSERT INTO tbl_resellerwalletstatement (did, date, crdrtype, cr_amount, dr_amount, remarks, status, traceno, old_bal, balance, trsid) VALUES (v_did, dbo.FUN_GETCURRENTDATE(), 'CR', v_custrechargeamount, 0, 'Wallet credited against refund for ' || CAST(v_rechargeoperator AS VARCHAR(100)) || ' recharge on ' || CAST(v_custmobile AS VARCHAR(20)) || ' ', 1, v_custtransactionid, v_reselleroldbalance, v_resellernewbalance, 1);
  IF EXISTS(SELECT 1 FROM tbl_reseller_commission_wallet WHERE traceno = v_custtransactionid) THEN
  UPDATE tbl_reseller_commission_wallet SET status = 0 WHERE traceno = v_custtransactionid;
  END IF;
  END IF;
  UPDATE dbo.tbl_customer_prepaid_recharges SET apitransactionid = v_apitransactionid, rechargestatus = v_rechargeresponsestatus, responsedate = dbo.FUN_GETCURRENTDATE(), responseremarks = v_rechargeresponseremarks WHERE transactionid = v_custtransactionid AND rechargestatus IS NULL;
  END IF;
  v_stroutput := 'SUCCESS';
  -- COMMIT (removed)
  END IF;
  EXCEPTION WHEN OTHERS THEN
  IF (0 <> 0) THEN
  PERFORM dbo.sp_errorlog();
  v_stroutput := 'Error in request';
  -- ROLLBACK (removed)
  RETURN;
  END IF;
  END;
END;
$$;


--
-- Name: usp_update_customer_prepaid_recharge_response_mobile(character varying, character varying, character varying, text, character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_update_customer_prepaid_recharge_response_mobile(v_custtransactionid character varying DEFAULT '1174857003'::character varying, v_apitransactionid character varying DEFAULT ''::character varying, v_rechargeresponsestatus character varying DEFAULT 'FAILED'::character varying, v_rechargeresponseremarks text DEFAULT 'RECHARGE FAILED'::text, v_stroutput character varying DEFAULT ''::character varying) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_clid INT;
  v_custwallet DECIMAL(18,2);
  v_custrechargeamount DECIMAL(18,2);
  v_oldbalance DECIMAL(18,2);
  v_newbalance DECIMAL(18,2);
  v_custmobile VARCHAR(20);
  v_did INT;
  v_distributorbalance decimal(18,8);
  v_pmid int;
BEGIN
  BEGIN
  -- BEGIN TRAN (removed)
  v_clid := 0;
  v_custwallet := 0;
  v_custrechargeamount := 0;
  v_oldbalance := 0;
  v_newbalance := 0;
  v_custmobile := '';
  v_did := 0;
  v_distributorbalance := 0;
  v_pmid := 0;
  SELECT clid, rechargeamount, mobileno INTO v_clid, v_custrechargeamount, v_custmobile FROM dbo.tbl_customer_prepaid_recharges WHERE transactionid = v_custtransactionid;
  SELECT did INTO v_did FROM tbl_customerlogin WHERE clid = v_clid;
  SELECT pmid INTO v_pmid FROM tbl_distributor WHERE did = v_did;
  RETURN QUERY SELECT v_pmid, v_did, v_clid;
  SELECT COALESCE(available_wallet, 0) INTO v_distributorbalance FROM tbl_distributor_prepaid_setting WHERE pmid = v_pmid;
  IF (v_custtransactionid <> '' AND v_apitransactionid <> '' AND (UPPER(v_rechargeresponsestatus) = 'SUCCESS' OR UPPER(v_rechargeresponsestatus) = 'PENDING')) THEN
  IF EXISTS(SELECT 1 FROM dbo.tbl_customer_prepaid_recharges WHERE transactionid = v_custtransactionid AND rechargestatus IS NULL) THEN
  UPDATE dbo.tbl_customer_prepaid_recharges SET apitransactionid = v_apitransactionid, rechargestatus = v_rechargeresponsestatus, responsedate = dbo.FUN_GETCURRENTDATE(), responseremarks = v_rechargeresponseremarks WHERE transactionid = v_custtransactionid AND rechargestatus IS NULL;
  END IF;
  v_stroutput := 'SUCCESS';
  -- COMMIT (removed)
  ELSE
  IF EXISTS(SELECT 1 FROM dbo.tbl_customer_prepaid_recharges WHERE transactionid = v_custtransactionid AND rechargestatus IS NULL) THEN
  IF (UPPER(v_rechargeresponsestatus) = 'FAILED' OR UPPER(v_rechargeresponsestatus) = 'FAILURE' OR UPPER(v_rechargeresponsestatus) = 'ERROR') THEN
  SELECT COALESCE(availablebalance, 0) INTO v_oldbalance FROM tbl_customerwallet WHERE clid = v_clid;
  SELECT v_oldbalance + v_custrechargeamount INTO v_newbalance;
  RETURN QUERY SELECT v_newbalance;
  UPDATE tbl_customerwallet SET availablebalance = availablebalance + v_custrechargeamount WHERE clid = v_clid;
  INSERT INTO tbl_customerwallet_statements (clid, processdate, crdrtype, cramt, dramt, old_balance, balance, remarks, traceno, status) VALUES (v_clid, dbo.FUN_GETCURRENTDATE(), 'CR', v_custrechargeamount, 0, v_oldbalance, v_newbalance, 'Wallet credited against refund for postpaid recharge on ' || CAST(v_custmobile AS VARCHAR(20)) || ' ', v_custtransactionid, 1);
  UPDATE tbl_distributor_prepaid_setting SET available_wallet = available_wallet + v_custrechargeamount, used_wallet = used_wallet - v_custrechargeamount WHERE pmid = v_pmid;
  INSERT INTO tbl_resellerwalletstatement (did, date, crdrtype, cr_amount, dr_amount, remarks, status, traceno, old_bal, balance) VALUES (v_did, dbo.FUN_GETCURRENTDATE(), 'Cr', v_custrechargeamount, 0, 'Wallet credited against refund for prepaid recharge on ' || CAST(v_custmobile AS VARCHAR(20)) || ' ', 1, v_custtransactionid, v_distributorbalance, (v_distributorbalance + v_custrechargeamount));
  UPDATE dbo.tbl_customer_prepaid_recharges SET apitransactionid = v_apitransactionid, rechargestatus = v_rechargeresponsestatus, responsedate = dbo.FUN_GETCURRENTDATE(), responseremarks = v_rechargeresponseremarks WHERE transactionid = v_custtransactionid AND rechargestatus IS NULL;
  END IF;
  END IF;
  v_stroutput := 'SUCCESS';
  -- COMMIT (removed)
  END IF;
  EXCEPTION WHEN OTHERS THEN
  IF (0 <> 0) THEN
  PERFORM dbo.sp_errorlog();
  v_stroutput := 'Error in request';
  -- ROLLBACK (removed)
  RETURN;
  END IF;
  END;
END;
$$;


