--
-- Name: usp_update_invoice_details(character varying, character varying, character varying, character varying, character varying, character varying, character varying, character varying, character varying, character varying, character varying, character varying, character varying, bigint, bigint, character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_update_invoice_details(v_smethod character varying, v_scarrier character varying, v_noofboxes character varying, v_weight character varying, v_carrierby character varying, v_carriercontactno character varying, v_paymode character varying, v_status character varying, v_dispatcheddate character varying, v_deliverrydate character varying, v_remark character varying, v_recievedby character varying, v_invoiceno character varying, v_empcode bigint, v_brcode bigint, INOUT v_result character varying) RETURNS character varying
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_prcode VARCHAR(50);
  v_prqty INT;
  v_orderid VARCHAR(50);
  v_rowcount INT;
  v_crow INT;
  v_emp_id BIGINT;
  v_intstatus INT;
  v_orderbrcode BIGINT;
BEGIN
  -- BEGIN TRAN (removed)
  v_crow := 1;
  v_result := 'Success';
  IF NOT EXISTS(SELECT 1 FROM tbl_invoice_master WHERE invno = v_invoiceno) THEN
  -- COMMIT (removed)
  v_result := 'Invalid Invoice No';
  RETURN;
  END IF;
  SELECT intstatus INTO v_intstatus FROM tbl_invoice_master WHERE invno = v_invoiceno;
  IF (v_intstatus >= 2) THEN
  -- COMMIT (removed)
  v_result := 'Invoice Allready Canceled ';
  RETURN;
  END IF;
  IF (v_result = 'success') THEN
  SELECT orderid INTO v_orderid FROM tbl_invoice_master WHERE invno = v_invoiceno;
  SELECT branchid INTO v_orderbrcode FROM tbl_order_master WHERE orderid = v_orderid;
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp ON COMMIT DROP AS SELECT *, ROW_NUMBER() OVER (ORDER BY invno ASC NULLS FIRST) AS row FROM tbl_product_inv_master WHERE invno = v_invoiceno;
  SELECT COUNT(row) INTO v_rowcount FROM tmp_temp;
  WHILE v_crow <= v_rowcount LOOP
  SELECT subprcode, product_qty INTO v_prcode, v_prqty FROM tmp_temp WHERE row = v_crow;
  UPDATE tbl_product_order_master SET status = v_status WHERE subprcode = v_prcode AND orderid = v_orderid;
  IF (v_status = 'Canceled') THEN
  UPDATE tbl_product_order_master SET invqty = COALESCE(invqty, 0) - v_prqty, status = v_status WHERE subprcode = v_prcode AND orderid = v_orderid;
  UPDATE tbl_invoice_master SET intstatus = 2 WHERE invno = v_invoiceno;
  END IF;
  IF (v_status = 'Delivered') THEN
  UPDATE tbl_invoice_master SET intstatus = 1 WHERE invno = v_invoiceno;
  END IF;
  v_crow := v_crow + 1;
  END LOOP;
  UPDATE tbl_invoice_master SET status = v_status, shipmethod = v_smethod, carrier_id = v_scarrier, carrier_by = v_carrierby, carrier_contact = v_carriercontactno, noofboxes = v_noofboxes, weightinkg = v_weight, dispatch_date = v_dispatcheddate, delivere_date = v_deliverrydate, recieved_by = v_recievedby, paymode = v_paymode, remark = v_remark WHERE invno = v_invoiceno;
  SELECT v_empcode INTO v_emp_id;
  INSERT INTO tbl_ordernotes (orderid, date, remark, brcode, emp_code, active) VALUES (v_orderid, dbo.FUN_GETCURRENTDATE(), 'InvoiceNo ' || CAST(v_invoiceno AS VARCHAR(50)) || ' Status has been Changed to ' || v_status || ' by EMP Code : ' || CAST(v_emp_id AS VARCHAR(50)) || '(BRID' || CAST(v_brcode AS VARCHAR(50)) || ')', v_brcode, v_empcode, 1);
  END IF;
  IF (0 <> 0) THEN
  -- ROLLBACK (removed)
  v_result := 'Some Error Occurred Please Try Later  ';
  RETURN;
  END IF;
  -- COMMIT (removed)
END;
$$;


--
-- Name: usp_update_merchant_bankwithdrawalstatus_byexecll(character varying, character varying, character varying, character varying, character varying, character varying, character varying, character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_update_merchant_bankwithdrawalstatus_byexecll(v_groupnumber character varying DEFAULT ''::character varying, v_accountno character varying DEFAULT ''::character varying, v_status character varying DEFAULT ''::character varying, v_processby character varying DEFAULT ''::character varying, v_processipaddress character varying DEFAULT '1'::character varying, INOUT v_strresult character varying DEFAULT ''::character varying, v_mode character varying DEFAULT '2'::character varying, v_utrno character varying DEFAULT ''::character varying) RETURNS character varying
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_getchid INT;
  v_getallwdid text;
  v_getupdatestatus text;
BEGIN
  v_getchid := 0;
  v_getallwdid := '';
  SELECT chid INTO v_getchid FROM tbl_merchant_clubhistory WHERE clubgroup = v_groupnumber;
  v_strresult := '1';
  v_getupdatestatus := '';
  IF (v_mode = 2) THEN
  SELECT RIGHT(CAST(allwdid AS TEXT), LENGTH(CAST(allwdid AS TEXT)) - 1) INTO v_getallwdid FROM tbl_customer_clubhistory WHERE chid = v_getchid;
  v_getupdatestatus := 'UPDATE TBL_MERCHANT_WITHDRAWALS SET STATUS=0 WHERE TMWDID IN  (SELECT * FROM SPLITSTRING(''' || v_getallwdid || ''','',''))';
  EXECUTE v_getupdatestatus;
  UPDATE tbl_merchant_downloadclubdata SET status = 2, processby = v_processby, processipaddress = v_processipaddress, processdate = dbo.FUN_GETCURRENTDATE() WHERE chid = v_getchid;
  UPDATE tbl_merchant_clubhistory SET processstatus = 2, processby = v_processby, processipaddress = v_processipaddress, processdate = dbo.FUN_GETCURRENTDATE() WHERE chid = v_getchid;
  v_strresult := '1';
  END IF;
  IF (v_mode = 1) THEN
  SELECT RIGHT(CAST(allwdid AS TEXT), LENGTH(CAST(allwdid AS TEXT)) - 1) INTO v_getallwdid FROM tbl_customer_downloadclubdata WHERE chid = v_getchid AND accountnumber = v_accountno;
  v_getupdatestatus := 'UPDATE TBL_MERCHANT_WITHDRAWALS SET STATUS=1,TRANSACTIONID=''' || v_utrno || ''',ISPAID=1 WHERE TCTTB IN  (SELECT * FROM SPLITSTRING(''' || v_getallwdid || ''','',''))';
  EXECUTE v_getupdatestatus;
  UPDATE tbl_merchant_downloadclubdata SET status = 1, processby = v_processby, processipaddress = v_processipaddress, processdate = dbo.FUN_GETCURRENTDATE() WHERE chid = v_getchid AND accountnumber = v_accountno;
  UPDATE tbl_merchant_clubhistory SET processstatus = 1, processby = v_processby, processipaddress = v_processipaddress, processdate = dbo.FUN_GETCURRENTDATE() WHERE chid = v_getchid;
  v_strresult := '1';
  END IF;
END;
$$;


--
-- Name: usp_update_merchant_cofig_data(character varying, integer, character varying, character varying, boolean, integer, character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_update_merchant_cofig_data(v_flag character varying DEFAULT NULL::character varying, v_merchant_id integer DEFAULT NULL::integer, v_value character varying DEFAULT NULL::character varying, v_column_name character varying DEFAULT NULL::character varying, INOUT v_out_status boolean DEFAULT false, INOUT v_out_result integer DEFAULT 0, INOUT v_out_message character varying DEFAULT ''::character varying) RETURNS record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_query text;
  v_datatype varchar(100);
BEGIN
  BEGIN
  v_query := '';
  v_datatype := '';
  SELECT data_type INTO v_datatype FROM information_schema.columns WHERE table_name = 'MERCHANT_CONFIGURATION  ' AND column_name = '' || v_column_name || '';
  IF v_datatype IS NULL THEN
  v_out_status := 0;
  v_out_result := 0;
  v_out_message := 'Invalid column name';
  RETURN;
  END IF;
  v_query := N'
            UPDATE dbo.MERCHANT_CONFIGURATION
            SET ' + QUOTENAME(v_column_name) + N' = 
                CAST(@VAL AS ' || v_datatype || N')
            WHERE MERCHANT_ID = @MID; ';
  RAISE NOTICE '%', v_query;
  EXECUTE v_query;
  v_out_status := 1;
  v_out_result := 1;
  v_out_message := 'Updated Successfully!!';
  EXCEPTION WHEN OTHERS THEN
  v_out_status := 1;
  v_out_result := 1;
  v_out_message := sqlerrm;
  END;
END;
$$;


--
-- Name: usp_update_merchantonlinepackagepurchaserequests(integer, character varying, character varying, character varying, character varying, character varying, character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_update_merchantonlinepackagepurchaserequests(v_mode integer DEFAULT 0, v_transid character varying DEFAULT ''::character varying, INOUT v_stroutput character varying DEFAULT ''::character varying, INOUT v_strpackagename character varying DEFAULT ''::character varying, INOUT v_utilityname character varying DEFAULT ''::character varying, INOUT v_packagedate character varying DEFAULT ''::character varying, INOUT v_packageamountdata character varying DEFAULT ''::character varying) RETURNS record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_did INT;
  v_trpid INT;
  v_paymode VARCHAR(100);
  v_trsid INT;
  v_invoiceno VARCHAR(100);
  v_currentyear VARCHAR(100);
  v_nextyear VARCHAR(100);
  v_countno VARCHAR(100);
  v_invoicecode VARCHAR(10);
  v_packagename VARCHAR(100);
  v_packageamount DECIMAL(18,2);
  v_gstpercentage DECIMAL(18,2);
  v_lastdigit INT;
  v_transactionrate DECIMAL(18,2);
BEGIN
  BEGIN
  -- BEGIN TRAN (removed)
  v_did := 0;
  v_trpid := 0;
  v_paymode := '';
  v_trsid := 0;
  v_invoiceno := '';
  v_invoicecode := 'PP';
  v_packagename := '';
  v_packageamount := 0;
  v_lastdigit := 0;
  v_transactionrate := 0;
  IF (v_mode = 1 AND v_transid <> '') THEN
  IF EXISTS(SELECT 1 FROM dbo.tbl_merchantpackagepurchase_onlinerequests WHERE transactionid = v_transid AND status = 0 AND active = 1) THEN
  SELECT RIGHT(CAST(EXTRACT(YEAR FROM CAST(dbo.FUN_GETCURRENTDATE() AS DATE)) AS TEXT), 2), RIGHT(CAST(EXTRACT(YEAR FROM CAST(dbo.FUN_GETCURRENTDATE() AS DATE)) AS TEXT), 2) + 1 INTO v_currentyear, v_nextyear;
  SELECT COALESCE(MAX(invoicecode), 0) INTO v_countno FROM tbl_merchant_package_invoice WHERE status = 1;
  v_countno := v_countno || 1;
  v_lastdigit := v_countno;
  v_currentyear := RIGHT(CAST(v_currentyear AS TEXT), 2);
  v_nextyear := RIGHT(CAST(v_nextyear AS TEXT), 2);
  SELECT RIGHT(CAST('000000' || CAST(v_countno AS VARCHAR(6)) AS TEXT), 6) INTO v_countno;
  v_invoiceno := v_invoicecode || '/' || v_currentyear || '-' || v_nextyear || '/' || v_countno;
  RAISE NOTICE '%', v_invoiceno;
  SELECT plid, mpid, paymentmode INTO v_did, v_trpid, v_paymode FROM dbo.tbl_merchantpackagepurchase_onlinerequests WHERE transactionid = v_transid AND status = 0 AND active = 1;
  SELECT COALESCE(mpid, 0) INTO v_trsid FROM tbl_merchantpackeages WHERE mpid = v_trpid;
  UPDATE dbo.tbl_merchantpackagepurchase_onlinerequests SET status = 1 WHERE transactionid = v_transid AND status = 0 AND active = 1;
  INSERT INTO dbo.tbl_merchant_purchased_packages_history (tmpphid, plid, mpid, purchaseddate, active, createdate, status, invoiceno, historydate, trsid) SELECT tmppid, plid, pmid, purchaseddate, active, createdate, status, invoiceno, dbo.FUN_GETCURRENTDATE(), pmid FROM tbl_merchant_purchased_packages WHERE plid = v_did AND pmid = v_trpid;
  IF NOT EXISTS(SELECT 1 FROM tbl_merchant_purchased_packages WHERE plid = v_did AND trsid = v_trsid) THEN
  INSERT INTO tbl_merchant_purchased_packages (plid, pmid, purchaseddate, active, createdate, status, invoiceno, trsid) VALUES (v_did, v_trpid, dbo.FUN_GETCURRENTDATE(), 1, dbo.FUN_GETCURRENTDATE(), 1, v_invoiceno, v_trsid);
  ELSE
  UPDATE dbo.tbl_merchant_purchased_packages SET pmid = v_trpid, purchaseddate = dbo.FUN_GETCURRENTDATE(), active = 1, createdate = dbo.FUN_GETCURRENTDATE(), status = 1, invoiceno = v_invoiceno WHERE plid = v_did AND active = 1 AND trsid = v_trsid;
  END IF;
  SELECT COALESCE(transationpayumoneyrate, 0) INTO v_transactionrate FROM tbl_companysettings WHERE pmid = 8;
  SELECT COALESCE(limits, 0) INTO v_gstpercentage FROM settings WHERE caption = 'GST PERCENTAGE';
  SELECT COALESCE(name, ''), COALESCE(amount, 0) INTO v_packagename, v_packageamount FROM tbl_merchantpackeages WHERE mpid = v_trpid;
  IF EXISTS(SELECT 1 FROM tbl_merchant_package_invoice WHERE plid = v_did AND status = 1 AND trsid = v_trsid) THEN
  UPDATE tbl_merchant_package_invoice SET status = 0 WHERE plid = v_did AND trsid = v_trsid;
  END IF;
  INSERT INTO dbo.tbl_merchant_package_invoice (plid, transactionid, invoicenumber, invoicename, packagename, amount, gstpercentage, gstamount, totalamount, paymode, status, invoicecode, invoicedate, packageid, trsid, transactionrate) VALUES (v_did, v_transid, v_invoiceno, 'IN' || v_countno || '.pdf', v_packagename, v_packageamount, v_gstpercentage, (v_packageamount * v_gstpercentage) / 100, (v_gstpercentage + (v_packageamount * v_gstpercentage) / 100), v_paymode, 1, v_lastdigit, dbo.FUN_GETCURRENTDATE(), v_trpid, v_trsid, v_transactionrate);
  v_stroutput := 'Success';
  SELECT trp.name, CAST(TO_CHAR(trpp.purchaseddate, 'DD TMMon YYYY') AS VARCHAR(15)), v_packageamount INTO v_strpackagename, v_packagedate, v_packageamountdata FROM dbo.tbl_merchant_purchased_packages AS trpp INNER JOIN tbl_merchantpackeages AS trp ON trpp.pmid = trp.mpid WHERE trpp.trsid = v_trsid AND plid = v_did AND trpp.pmid = v_trpid;
  SELECT COALESCE(name, '') INTO v_utilityname FROM tbl_merchantpackeages WHERE mpid = v_trpid AND status = 1;
  -- COMMIT (removed)
  END IF;
  ELSE
  v_stroutput := 'Invalid Request';
  -- COMMIT (removed)
  RETURN;
  END IF;
  EXCEPTION WHEN OTHERS THEN
  IF (0 <> 0) THEN
  v_stroutput := 'Error';
  -- COMMIT (removed)
  RETURN;
  END IF;
  END;
END;
$$;


--
-- Name: usp_update_merchantpaymentsstatus(integer, character varying, character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_update_merchantpaymentsstatus(v_mode integer DEFAULT 0, v_transid character varying DEFAULT ''::character varying, INOUT v_stroutput character varying DEFAULT ''::character varying) RETURNS character varying
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_clid INT;
  v_loginid VARCHAR(50);
  v_transactionid VARCHAR(50);
  v_requestamount DECIMAL(18,2);
  v_iswalletexist INT;
  v_oldbalance DECIMAL(18,2);
  v_newbalance DECIMAL(18,2);
BEGIN
  BEGIN
  -- BEGIN TRAN (removed)
  v_clid := 0;
  v_loginid := '';
  v_transactionid := '';
  v_requestamount := 0;
  v_iswalletexist := 0;
  v_oldbalance := 0;
  v_newbalance := 0;
  IF (v_mode <> 0 AND v_mode = 1) THEN
  IF (v_transid <> '') THEN
  SELECT clid, COALESCE(loginid, ''), COALESCE(amount, 0) INTO v_clid, v_loginid, v_requestamount FROM tbl_addmoneyrequests WHERE transactionid = v_transid;
  IF EXISTS(SELECT 1 FROM tbl_customerlogin WHERE clid = v_clid) THEN
  IF EXISTS(SELECT 1 FROM tbl_addmoneyrequests WHERE clid = v_clid AND loginid = v_loginid AND transactionid = v_transid AND responsedatetime IS NULL AND updateddate IS NULL) THEN
  IF EXISTS(SELECT 1 FROM tbl_customerwallet WHERE clid = v_clid AND loginid = v_loginid AND active = 1) THEN
  SELECT availablebalance INTO v_oldbalance FROM tbl_customerwallet WHERE clid = v_clid AND loginid = v_loginid;
  v_newbalance := v_oldbalance + v_requestamount;
  v_iswalletexist := 1;
  ELSE
  v_oldbalance := 0;
  v_newbalance := v_oldbalance + v_requestamount;
  v_iswalletexist := 0;
  END IF;
  UPDATE tbl_addmoneyrequests SET status = 1, responsedatetime = dbo.FUN_GETCURRENTDATE(), updateddate = dbo.FUN_GETCURRENTDATE() WHERE transactionid = v_transid AND clid = v_clid AND loginid = v_loginid AND amount = v_requestamount AND active = 1;
  IF (v_iswalletexist = 1) THEN
  UPDATE tbl_customerwallet SET availablebalance = COALESCE(availablebalance, 0) + v_requestamount, totalbalance = COALESCE(totalbalance, 0) + v_requestamount, updateddate = dbo.FUN_GETCURRENTDATE() WHERE clid = v_clid AND loginid = v_loginid AND active = 1;
  ELSE
  INSERT INTO tbl_customerwallet (clid, loginid, addmoney, transfertobank, totalbalance, availablebalance, updateddate) VALUES (v_clid, v_loginid, v_requestamount, 0, v_requestamount, v_requestamount, dbo.FUN_GETCURRENTDATE());
  END IF;
  INSERT INTO tbl_customerwallet_statements (clid, processdate, crdrtype, cramt, dramt, old_balance, balance, remarks, traceno, status) VALUES (v_clid, dbo.FUN_GETCURRENTDATE(), 'CR', v_requestamount, 0, v_oldbalance, v_newbalance, 'ADD MONEY', v_transid, 1);
  v_stroutput := 'SUCCESS';
  -- COMMIT (removed)
  ELSE
  v_stroutput := 'Invalid Transaction';
  -- COMMIT (removed)
  RETURN;
  END IF;
  ELSE
  v_stroutput := 'Invalid user';
  -- COMMIT (removed)
  RETURN;
  END IF;
  END IF;
  END IF;
  IF (v_mode <> 0 AND v_mode = 2) THEN
  IF (v_transid <> '') THEN
  IF EXISTS(SELECT 1 FROM dbo.tbl_merchantpackagepurchase_onlinerequests WHERE transactionid = v_transid AND status = 0 AND active = 1) THEN
  UPDATE tbl_merchantpackagepurchase_onlinerequests SET status = 3, active = 0 WHERE transactionid = v_transid;
  v_stroutput := 'SUCCESS';
  -- COMMIT (removed)
  ELSE
  v_stroutput := 'Invalid user';
  -- COMMIT (removed)
  RETURN;
  END IF;
  END IF;
  END IF;
  IF (v_mode <> 0 AND v_mode = 3) THEN
  IF (v_transid <> '') THEN
  IF EXISTS(SELECT 1 FROM dbo.tbl_merchantpackagepurchase_onlinerequests WHERE transactionid = v_transid AND status = 0 AND active = 1) THEN
  UPDATE tbl_merchantpackagepurchase_onlinerequests SET status = 2, active = 0 WHERE transactionid = v_transid;
  v_stroutput := 'SUCCESS';
  -- COMMIT (removed)
  ELSE
  v_stroutput := 'Invalid Transaction';
  -- COMMIT (removed)
  RETURN;
  END IF;
  END IF;
  END IF;
  EXCEPTION WHEN OTHERS THEN
  IF (0 <> 0) THEN
  v_stroutput := 'ERROR';
  -- ROLLBACK (removed)
  RETURN;
  END IF;
  END;
END;
$$;


--
-- Name: usp_update_pendingdeals_qa(bigint, bigint, text, text, character varying, character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_update_pendingdeals_qa(v_optid bigint, v_dqid bigint, v_title text, v_message text, v_mode character varying, INOUT v_strresult character varying) RETURNS character varying
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_optidlisting bigint;
  v_dealid bigint;
BEGIN
  -- BEGIN TRAN (removed)
  v_strresult := 'ok';
  SELECT COALESCE(optid, 0) INTO v_optidlisting FROM portal_master WHERE pmid = (SELECT pmid FROM tbl_dealswithqa WHERE dqid = v_dqid);
  IF NOT EXISTS(SELECT dqid FROM tbl_dealswithqa WHERE optid = v_optid AND dqid = v_dqid) THEN
  -- COMMIT (removed)
  v_strresult := 'Invalid details !';
  RETURN;
  END IF;
  SELECT dealid INTO v_dealid FROM tbl_dealswithqa WHERE dqid = v_dqid;
  IF (v_mode = 'reply') THEN
  UPDATE portal_deal_master SET verify = 2 WHERE dealid = v_dealid;
  INSERT INTO unvarifiedlisting_master (pmid, message, optid, qaid, status, date) VALUES (v_dealid, v_message, v_optidlisting, v_optid, 1, dbo.fun_getIndiaCurrentDate());
  END IF;
  IF (v_mode = 'verify') THEN
  UPDATE tbl_dealswithqa SET verify_date = dbo.fun_getIndiaCurrentDate(), status = 1 WHERE dqid = v_dqid;
  UPDATE tbl_operator_report SET totalverified = COALESCE(totalverified, 0) + 1 WHERE optid = v_optid;
  UPDATE portal_deal_master SET verify = 1 WHERE dealid = v_dealid;
  END IF;
  IF (v_mode = 'update') THEN
  UPDATE portal_deal_master SET title = v_title, description = v_message WHERE dealid = v_dealid;
  END IF;
  IF (0 <> 0) THEN
  -- ROLLBACK (removed)
  v_strresult := 'some error occured,Pleas try again !';
  RETURN;
  END IF;
  -- COMMIT (removed)
END;
$$;


--
-- Name: usp_update_pendinglisting_qa(bigint, bigint, text, text, character varying, character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_update_pendinglisting_qa(v_optid bigint, v_lwqid bigint, v_title text, v_message text, v_mode character varying, INOUT v_strresult character varying) RETURNS character varying
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_optidlisting bigint;
  v_pmid bigint;
BEGIN
  -- BEGIN TRAN (removed)
  v_strresult := 'ok';
  SELECT COALESCE(optid, 0) INTO v_optidlisting FROM portal_master WHERE pmid = (SELECT pmid FROM tbl_listingswithqa WHERE lwq_id = v_lwqid);
  IF NOT EXISTS(SELECT lwq_id FROM tbl_listingswithqa WHERE optid = v_optid AND lwq_id = v_lwqid) THEN
  -- COMMIT (removed)
  v_strresult := 'Invalid details !';
  RETURN;
  END IF;
  SELECT pmid INTO v_pmid FROM tbl_listingswithqa WHERE lwq_id = v_lwqid;
  IF (v_mode = 'reply') THEN
  UPDATE portal_master SET isverified = 2 WHERE pmid = v_pmid;
  INSERT INTO unvarifiedlisting_master (pmid, message, optid, qaid, status, date) VALUES (v_pmid, v_message, v_optidlisting, v_optid, 1, dbo.fun_getIndiaCurrentDate());
  END IF;
  IF (v_mode = 'verify') THEN
  UPDATE unvarifiedlisting_master SET status = 0 WHERE pmid = v_pmid;
  UPDATE tbl_listingswithqa SET verify_date = dbo.fun_getIndiaCurrentDate(), status = 1 WHERE lwq_id = v_lwqid;
  UPDATE tbl_operator_report SET totalverified = COALESCE(totalverified, 0) + 1 WHERE optid = v_optid;
  UPDATE portal_master SET isverified = 1 WHERE pmid = v_pmid;
  END IF;
  IF (v_mode = 'update') THEN
  UPDATE portal_master SET title = v_title, companyname = v_title, companydesc = v_message WHERE pmid = v_pmid;
  END IF;
  IF (0 <> 0) THEN
  -- ROLLBACK (removed)
  v_strresult := 'some error occured,Pleas try again !';
  RETURN;
  END IF;
  -- COMMIT (removed)
END;
$$;


--
-- Name: usp_update_pendinglistingdeals_qa(bigint, bigint, text, text, character varying, character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_update_pendinglistingdeals_qa(v_optid bigint, v_dqid bigint, v_title text DEFAULT NULL::text, v_message text DEFAULT NULL::text, v_mode character varying DEFAULT NULL::character varying, INOUT v_strresult character varying DEFAULT NULL::character varying) RETURNS character varying
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_optidlisting bigint;
  v_pmid bigint;
BEGIN
  -- BEGIN TRAN (removed)
  v_strresult := 'ok';
  SELECT COALESCE(optid, 0) INTO v_optidlisting FROM portal_master WHERE pmid = (SELECT pmid FROM tbl_dealswithqa WHERE dealid = v_dqid);
  IF NOT EXISTS(SELECT dqid FROM tbl_dealswithqa WHERE optid = v_optid AND dealid = v_dqid) THEN
  -- COMMIT (removed)
  v_strresult := 'Invalid details !';
  RETURN;
  END IF;
  IF (v_mode = 'reply') THEN
  SELECT pmid INTO v_pmid FROM portal_deal_master WHERE dealid = v_dqid;
  UPDATE portal_deal_master SET verify = 2 WHERE dealid = v_dqid;
  INSERT INTO unvarifieddeals_master (pmid, message, optid, dealid, status, date) VALUES (v_pmid, v_message, v_optid, v_dqid, 1, dbo.fun_getIndiaCurrentDate());
  END IF;
  IF (v_mode = 'delete') THEN
  SELECT pmid INTO v_pmid FROM portal_deal_master WHERE dealid = v_dqid;
  UPDATE portal_deal_master SET verify = 3 WHERE dealid = v_dqid;
  INSERT INTO unvarifieddealsdelete_master (pmid, message, optid, dealid, status, date) VALUES (v_pmid, v_message, v_optid, v_dqid, 1, dbo.fun_getIndiaCurrentDate());
  END IF;
  IF (v_mode = 'verify') THEN
  UPDATE tbl_dealswithqa SET verify_date = dbo.fun_getIndiaCurrentDate(), status = 1 WHERE dealid = v_dqid;
  UPDATE tbl_operator_report SET totalverified = COALESCE(totalverified, 0) + 1 WHERE optid = v_optid;
  UPDATE portal_deal_master SET verify = 1 WHERE dealid = v_dqid;
  END IF;
  IF (v_mode = 'update') THEN
  UPDATE portal_deal_master SET title = v_title, description = v_message WHERE dealid = v_dqid;
  END IF;
  IF (0 <> 0) THEN
  -- ROLLBACK (removed)
  v_strresult := 'some error occured,Pleas try again !';
  RETURN;
  END IF;
  -- COMMIT (removed)
END;
$$;


--
-- Name: usp_update_product_admin(integer, bigint, integer, numeric, numeric, numeric, integer, numeric, numeric, numeric, numeric, numeric, character varying, character varying, text, character varying, character varying, character varying, character varying, character varying, character varying, character varying, character varying, character varying, character varying, character varying, character varying, numeric, numeric, numeric, numeric, numeric, numeric, numeric, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_update_product_admin(v_mode integer DEFAULT 1, v_sprid bigint DEFAULT 0, v_isverified integer DEFAULT 0, v_sellmrp numeric DEFAULT 0, v_discount numeric DEFAULT 0, v_dap numeric DEFAULT 0, v_stockin integer DEFAULT 0, v_length numeric DEFAULT 0, v_breadth numeric DEFAULT 0, v_weight numeric DEFAULT 0, v_height numeric DEFAULT 0, v_shippingcharges numeric DEFAULT 0, v_shortdesc character varying DEFAULT ''::character varying, v_keyfeatures character varying DEFAULT ''::character varying, v_fulldesc text DEFAULT ''::text, v_strresult character varying DEFAULT ''::character varying, v_image character varying DEFAULT ''::character varying, v_manufacturingdetail character varying DEFAULT ''::character varying, v_importerdetail character varying DEFAULT ''::character varying, v_packerdetail character varying DEFAULT ''::character varying, v_gst character varying DEFAULT ''::character varying, v_procurementtype character varying DEFAULT ''::character varying, v_fullfilmentseller character varying DEFAULT ''::character varying, v_procurementsla character varying DEFAULT ''::character varying, v_hsn character varying DEFAULT ''::character varying, v_luxurycess character varying DEFAULT ''::character varying, v_countryorigin character varying DEFAULT ''::character varying, v_admincharge numeric DEFAULT NULL::numeric, v_fixedcharge numeric DEFAULT NULL::numeric, v_handlingcharge numeric DEFAULT NULL::numeric, v_deliverycharge numeric DEFAULT NULL::numeric, v_bv numeric DEFAULT NULL::numeric, v_jc numeric DEFAULT NULL::numeric, v_cashback numeric DEFAULT NULL::numeric, v_didid integer DEFAULT 0) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_mprid BigInt;
BEGIN
  -- BEGIN TRAN (removed)
  IF (v_mode = 1) THEN
  SELECT mprid INTO v_mprid FROM ims_subproduct WHERE sprid = v_sprid;
  UPDATE ims_masterproduct SET shotdescription = v_shortdesc, fulldescription = v_fulldesc, keyfeatures = v_keyfeatures, modifydate = CURRENT_TIMESTAMP WHERE mprid = v_mprid;
  UPDATE ims_subproduct SET discountpercentage = v_discount, dap = v_dap, modifydate = CURRENT_TIMESTAMP, weight_kg = v_weight, length_cms = v_length, breadth_cms = v_breadth, height_cms = v_height, shippingcharges = v_shippingcharges, stockin = v_stockin, sellmrp = v_sellmrp, isverified = v_isverified, procurementsla = v_procurementsla, manufacturerdetails = v_manufacturingdetail, luxurycess = v_luxurycess, hsn = v_hsn, procurementtype = v_procurementtype, fullfilmentby = v_fullfilmentseller, importerdetails = v_importerdetail, packerdetails = v_packerdetail, countryorigin = v_countryorigin, admincharge = v_admincharge, fixedfee = v_fixedcharge, handlingcharge = v_handlingcharge, delieverycharge = v_deliverycharge, bv = v_bv, pv = v_jc, cashback_per = v_cashback WHERE sprid = v_sprid;
  v_strresult := 'updated successfully';
  END IF;
  IF NOT EXISTS(SELECT 1 FROM tbl_distributor_comm_productwise WHERE sprid = v_sprid AND did = v_didid) THEN
  INSERT INTO tbl_distributor_comm_productwise VALUES (v_didid, v_sprid, v_bv, v_jc, v_admincharge, v_deliverycharge, v_handlingcharge, v_fixedcharge, v_cashback, 1, dbo.FUN_GETCURRENTDATE(), dbo.FUN_GETCURRENTDATE());
  ELSE
  INSERT INTO tbl_distributor_comm_productwise_history SELECT * FROM tbl_distributor_comm_productwise WHERE sprid = v_sprid AND did = v_didid;
  UPDATE tbl_distributor_comm_productwise SET bv = v_bv, pv = v_jc, admincharge = v_admincharge, delieverycharge = v_deliverycharge, handlingcharge = v_handlingcharge, fixedfee = v_fixedcharge, cashback_per = v_cashback WHERE sprid = v_sprid AND did = v_didid;
  END IF;
  IF (v_mode = 2) THEN
  SELECT mprid INTO v_mprid FROM ims_subproduct WHERE sprid = v_sprid;
  RETURN QUERY SELECT sm.subprcode, pm.shotdescription, pm.fulldescription, pm.keyfeatures, sm.discountpercentage, sm.dap, sm.weight_kg, sm.length_cms, sm.breadth_cms, sm.height_cms, sm.shippingcharges, sm.stockin, sm.sellmrp, sm.isverified, pm.producttitle, sm.procurementsla, sm.manufacturerdetails, sm.luxurycess, sm.hsn, sm.procurementtype, sm.fullfilmentby, sm.importerdetails, sm.packerdetails, sm.countryorigin FROM ims_subproduct AS sm INNER JOIN ims_masterproduct AS pm ON sm.mprid = pm.mprid WHERE sprid = v_sprid;
  END IF;
  IF (0 <> 0) THEN
  v_strresult := 'Some Error Occoured !';
  -- ROLLBACK (removed)
  RETURN;
  END IF;
  -- COMMIT (removed)
END;
$$;


--
-- Name: usp_update_productcount_inactive(integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_update_productcount_inactive(v_plid integer DEFAULT 10) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_count INT;
  v_totalcount INT;
  v_maincatid INT;
  v_catid INT;
  v_subcatid INT;
  v_totalproduct INT;
BEGIN
  -- BEGIN TRAN (removed)
  -- SET option (removed)
  v_count := 1;
  v_totalcount := 0;
  v_maincatid := 0;
  v_catid := 0;
  v_subcatid := 0;
  v_totalproduct := 0;
  IF (v_plid = 0) THEN
  -- COMMIT (removed)
  RETURN;
  END IF;
  IF (v_plid > 0) THEN
  DROP TABLE IF EXISTS tmp_maincategorytemp;
  CREATE TEMP TABLE tmp_maincategorytemp (ROWNUMBER INT GENERATED BY DEFAULT AS IDENTITY,MAINCATEGORYID INT) ON COMMIT DROP;
  INSERT INTO tmp_maincategorytemp SELECT DISTINCT maincategoryid FROM ims_masterproduct WHERE branchid = v_plid;
  SELECT COUNT(*) INTO v_totalcount FROM tmp_maincategorytemp;
  WHILE (v_totalcount >= v_count) LOOP
  SELECT maincategoryid INTO v_maincatid FROM tmp_maincategorytemp WHERE rownumber = v_count;
  SELECT v_totalcount INTO v_totalproduct FROM dbo.usp_totalproducts(v_maincatid => v_maincatid, v_catid => 0, v_subcatid => 0, v_totalcount => v_totalproduct);
  UPDATE tbl_main_category SET totalactive = v_totalproduct WHERE maincatid = v_maincatid AND status = 1 AND isdelete = 0;
  v_count := v_count + 1;
  END LOOP;
  v_maincatid := 0;
  DROP TABLE IF EXISTS tmp_maincategorytemp;
  DROP TABLE IF EXISTS tmp_categorytemp;
  CREATE TEMP TABLE tmp_categorytemp (ROWNUMBER INT GENERATED BY DEFAULT AS IDENTITY,MAINCATEGORYID INT,CATID INT) ON COMMIT DROP;
  INSERT INTO tmp_categorytemp SELECT DISTINCT maincategoryid, catid FROM ims_masterproduct WHERE branchid = v_plid;
  v_totalcount := 0;
  v_count := 1;
  SELECT COUNT(*) INTO v_totalcount FROM tmp_categorytemp;
  WHILE (v_totalcount >= v_count) LOOP
  SELECT maincategoryid, catid INTO v_maincatid, v_catid FROM tmp_categorytemp WHERE rownumber = v_count;
  SELECT v_totalcount INTO v_totalproduct FROM dbo.usp_totalproducts(v_maincatid => v_maincatid, v_catid => v_catid, v_subcatid => 0, v_totalcount => v_totalproduct);
  UPDATE tbl_category SET totalactive = v_totalproduct WHERE catid = v_catid AND maincatid = v_maincatid AND status = 1 AND isdelete = 0;
  v_count := v_count + 1;
  END LOOP;
  v_maincatid := 0;
  v_catid := 0;
  DROP TABLE IF EXISTS tmp_categorytemp;
  DROP TABLE IF EXISTS tmp_subcategorytemp;
  CREATE TEMP TABLE tmp_subcategorytemp (ROWNUMBER INT GENERATED BY DEFAULT AS IDENTITY,MAINCATEGORYID INT,CATID INT,SUBCATID INT) ON COMMIT DROP;
  INSERT INTO tmp_subcategorytemp SELECT DISTINCT maincategoryid, catid, subcategoryid FROM ims_masterproduct WHERE branchid = v_plid;
  v_totalcount := 0;
  v_count := 1;
  SELECT COUNT(*) INTO v_totalcount FROM tmp_subcategorytemp;
  WHILE (v_totalcount >= v_count) LOOP
  SELECT maincategoryid, catid, subcatid INTO v_maincatid, v_catid, v_subcatid FROM tmp_subcategorytemp WHERE rownumber = v_count;
  SELECT v_totalcount INTO v_totalproduct FROM dbo.usp_totalproducts(v_maincatid => v_maincatid, v_catid => v_catid, v_subcatid => v_subcatid, v_totalcount => v_totalproduct);
  UPDATE tbl_sub_category SET totalactive = v_totalproduct WHERE subcatid = v_subcatid AND catid = v_catid AND maincatid = v_maincatid AND status = 1 AND isdelete = 0;
  v_count := v_count + 1;
  END LOOP;
  DROP TABLE IF EXISTS tmp_subcategorytemp;
  END IF;
  -- SET option (removed)
  -- COMMIT (removed)
END;
$$;


--
-- Name: usp_update_profile_bank_billing(bigint, character varying, integer, character varying, character varying, character varying, character varying, character varying, character varying, character varying, character varying, character varying, character varying, character varying, character varying, character varying, character varying, character varying, character varying, integer, integer, bigint, character varying, character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_update_profile_bank_billing(v_plid bigint DEFAULT 0, v_username character varying DEFAULT ''::character varying, v_title integer DEFAULT 0, v_fname character varying DEFAULT ''::character varying, v_lname character varying DEFAULT ''::character varying, v_phoneno character varying DEFAULT ''::character varying, v_emailid character varying DEFAULT ''::character varying, v_designation character varying DEFAULT ''::character varying, v_accountno character varying DEFAULT ''::character varying, v_ifsccode character varying DEFAULT ''::character varying, v_bankname character varying DEFAULT ''::character varying, v_branchname character varying DEFAULT ''::character varying, v_businessname character varying DEFAULT ''::character varying, v_contactname character varying DEFAULT ''::character varying, v_phonenumber character varying DEFAULT ''::character varying, v_cid character varying DEFAULT ''::character varying, v_sid character varying DEFAULT ''::character varying, v_city character varying DEFAULT ''::character varying, v_baddress character varying DEFAULT ''::character varying, v_mode integer DEFAULT 0, INOUT v_intresult integer DEFAULT 0, v_billid bigint DEFAULT 0, v_billing_postalcode character varying DEFAULT ''::character varying, v_panno character varying DEFAULT ''::character varying) RETURNS integer
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_regno bigint;
  v_getcount int;
BEGIN
  v_regno := 0;
  SELECT plid INTO v_regno FROM member_master WHERE regno = v_plid;
  IF (v_mode = 0) THEN
  UPDATE portal_login SET designation = v_designation, username = v_username, title = v_title, fname = v_fname, lname = v_lname, phone = v_phoneno, emailid = v_emailid WHERE plid = v_regno;
  ELSE
  IF (v_mode = 1) THEN
  UPDATE member_master SET username = v_username, accountno = v_accountno, ifsccode = v_ifsccode, bankname = v_bankname, phone = v_phoneno, branchname = v_branchname, panno = v_panno WHERE plid = v_plid;
  ELSE
  IF (v_mode = 2) THEN
  v_getcount := 0;
  SELECT COUNT(plid) INTO v_getcount FROM tbl_sponserbilling WHERE plid = v_plid;
  IF (v_getcount > 0) THEN
  UPDATE tbl_sponserbilling SET businessname = v_businessname, contactname = v_contactname, phonenumber = v_phonenumber, postalcode = COALESCE(v_billing_postalcode, ''), cid = v_cid, sid = v_sid, city = v_city, address = v_baddress WHERE billid = v_billid;
  ELSE
  INSERT INTO tbl_sponserbilling (plid, businessname, contactname, phonenumber, address, city, postalcode, sid, cid, billingstatus, date, recentbillinginformation) VALUES (v_plid, v_businessname, v_contactname, v_phonenumber, v_baddress, v_city, COALESCE(v_billing_postalcode, ''), v_sid, v_cid, 1, dbo.FUN_GETCURRENTDATE(), '');
  END IF;
  END IF;
  END IF;
  END IF;
  v_intresult := 1;
END;
$$;


