CREATE FUNCTION dbo.usp_update_rechargestatus(v_uniqueaccountnumber character varying DEFAULT ''::character varying, v_apiresponse text DEFAULT ''::text, v_apitransactionid character varying DEFAULT ''::character varying, v_responseremarks character varying DEFAULT ''::character varying, v_rechargestatus character varying DEFAULT ''::character varying, INOUT v_stroutput character varying DEFAULT ''::character varying) RETURNS character varying
