  UPDATE tbl_customer_electricity_recharges SET apiresponse = v_apiresponse, apitransactionid = v_apitransactionid, responsedate = dbo.FUN_GETCURRENTDATE(), responseremarks = v_responseremarks, rechargestatus = v_rechargestatus WHERE transactionid = v_uniqueaccountnumber;
