  UPDATE tbl_customer_water_recharges SET apiresponse = v_apiresponse, apitransactionid = v_apitransactionid, responsedate = dbo.FUN_GETCURRENTDATE(), responseremarks = v_responseremarks, rechargestatus = v_rechargestatus WHERE transactionid = v_uniqueaccountnumber;
  ELSE
  IF EXISTS(SELECT 1 FROM tbl_customer_gas_recharges WHERE transactionid = v_uniqueaccountnumber AND COALESCE(apiresponse, '') = '' AND COALESCE(rechargestatus, -1) = -1) THEN
  UPDATE tbl_customer_gas_recharges SET apiresponse = v_apiresponse, apitransactionid = v_apitransactionid, responsedate = dbo.FUN_GETCURRENTDATE(), responseremarks = v_responseremarks, rechargestatus = v_rechargestatus WHERE transactionid = v_uniqueaccountnumber;
  ELSE
  IF EXISTS(SELECT 1 FROM tbl_customer_broadband_recharges WHERE transactionid = v_uniqueaccountnumber AND COALESCE(apiresponse, '') = '' AND COALESCE(rechargestatus, -1) = -1) THEN
  UPDATE tbl_customer_broadband_recharges SET apiresponse = v_apiresponse, apitransactionid = v_apitransactionid, responsedate = dbo.FUN_GETCURRENTDATE(), responseremarks = v_responseremarks, rechargestatus = v_rechargestatus WHERE transactionid = v_uniqueaccountnumber;
  END IF;
  END IF;
  END IF;
  END IF;
  END IF;
  END IF;
  END IF;
