--
-- Name: usp_update_refferenceid_behalf_service_mobile(character varying, character varying, character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_update_refferenceid_behalf_service_mobile(v_transactionid character varying DEFAULT ''::character varying, v_type character varying DEFAULT ''::character varying, INOUT v_intresult character varying DEFAULT ''::character varying) RETURNS character varying
    LANGUAGE plpgsql
    AS $$
BEGIN
  -- BEGIN TRAN (removed)
  v_intresult := '1';
  IF (v_type = 'PREPAID') THEN
  UPDATE tbl_customer_prepaid_recharges SET isandroidorweb = 1 WHERE transactionid = v_transactionid;
  v_intresult := 'success';
  ELSE
  IF (v_type = 'POSTPAID') THEN
  UPDATE tbl_customer_postpaid_recharges SET isandroidorweb = 1 WHERE transactionid = v_transactionid;
  v_intresult := 'success';
  ELSE
  IF (v_type = 'DTH') THEN
  UPDATE tbl_customer_dth_recharges SET isandroidorweb = 1 WHERE transactionid = v_transactionid;
  v_intresult := 'success';
  ELSE
  IF (v_type = 'GAS') THEN
  UPDATE tbl_customer_gas_recharges SET isandroidorweb = 1 WHERE transactionid = v_transactionid;
  v_intresult := 'success';
  ELSE
  IF (v_type = 'ELECTRICITY') THEN
  UPDATE tbl_customer_electricity_recharges SET isandroidorweb = 1 WHERE transactionid = v_transactionid;
  v_intresult := 'success';
  END IF;
  END IF;
  END IF;
  END IF;
  END IF;
  IF (0 <> 0) THEN
  v_intresult := 0;
  -- ROLLBACK (removed)
  RETURN;
  END IF;
  -- COMMIT (removed)
END;
$$;


--
-- Name: usp_update_reseller_bankwithdrawalstatus_byexecll(character varying, character varying, character varying, character varying, character varying, character varying, character varying, character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_update_reseller_bankwithdrawalstatus_byexecll(v_groupnumber character varying DEFAULT ''::character varying, v_accountno character varying DEFAULT ''::character varying, v_status character varying DEFAULT ''::character varying, v_processby character varying DEFAULT ''::character varying, v_processipaddress character varying DEFAULT '1'::character varying, INOUT v_strresult character varying DEFAULT ''::character varying, v_mode character varying DEFAULT '2'::character varying, v_utrno character varying DEFAULT ''::character varying) RETURNS character varying
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_getchid INT;
  v_getallwdid text;
  v_getupdatestatus text;
BEGIN
  v_getchid := 0;
  v_getallwdid := '';
  SELECT chid INTO v_getchid FROM tbl_reseller_clubhistory WHERE clubgroup = v_groupnumber;
  v_strresult := '1';
  v_getupdatestatus := '';
  IF (v_mode = 2) THEN
  SELECT RIGHT(CAST(allwdid AS TEXT), LENGTH(CAST(allwdid AS TEXT)) - 1) INTO v_getallwdid FROM tbl_reseller_clubhistory WHERE chid = v_getchid;
  v_getupdatestatus := 'UPDATE TBL_RESELLER_TRANSFERTOBANK_REQUEST SET PAIDSTATUS=0 WHERE TRTBWID IN  (SELECT * FROM SPLITSTRING(''' || v_getallwdid || ''','',''))';
  EXECUTE v_getupdatestatus;
  UPDATE tbl_reseller_downloadclubdata SET status = 2, processby = v_processby, processipaddress = v_processipaddress, processdate = dbo.FUN_GETCURRENTDATE() WHERE chid = v_getchid;
  UPDATE tbl_reseller_clubhistory SET processstatus = 2, processby = v_processby, processipaddress = v_processipaddress, processdate = dbo.FUN_GETCURRENTDATE() WHERE chid = v_getchid;
  v_strresult := '1';
  END IF;
  IF (v_mode = 1) THEN
  SELECT RIGHT(CAST(allwdid AS TEXT), LENGTH(CAST(allwdid AS TEXT)) - 1) INTO v_getallwdid FROM tbl_customer_downloadclubdata WHERE chid = v_getchid AND accountnumber = v_accountno;
  v_getupdatestatus := 'UPDATE TBL_RESELLER_TRANSFERTOBANK_REQUEST SET PAIDSTATUS=1,TRANS_ID=''' || v_utrno || ''', WHERE TRTBWID IN  (SELECT * FROM SPLITSTRING(''' || v_getallwdid || ''','',''))';
  EXECUTE v_getupdatestatus;
  UPDATE tbl_reseller_downloadclubdata SET status = 1, processby = v_processby, processipaddress = v_processipaddress, processdate = dbo.FUN_GETCURRENTDATE() WHERE chid = v_getchid AND accountnumber = v_accountno;
  UPDATE tbl_reseller_clubhistory SET processstatus = 1, processby = v_processby, processipaddress = v_processipaddress, processdate = dbo.FUN_GETCURRENTDATE() WHERE chid = v_getchid;
  v_strresult := '1';
  END IF;
END;
$$;


--
-- Name: usp_update_reselleronlinepackagepurchaserequests(integer, character varying, character varying, character varying, character varying, character varying, character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_update_reselleronlinepackagepurchaserequests(v_mode integer DEFAULT 0, v_transid character varying DEFAULT ''::character varying, INOUT v_stroutput character varying DEFAULT ''::character varying, INOUT v_strpackagename character varying DEFAULT ''::character varying, INOUT v_utilityname character varying DEFAULT ''::character varying, INOUT v_packagedate character varying DEFAULT ''::character varying, INOUT v_packageamountdata character varying DEFAULT ''::character varying) RETURNS record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_did INT;
  v_trpid INT;
  v_paymode VARCHAR(100);
  v_trsid INT;
  v_invoiceno VARCHAR(100);
  v_currentyear VARCHAR(100);
  v_nextyear VARCHAR(100);
  v_countno VARCHAR(100);
  v_invoicecode VARCHAR(10);
  v_packagename VARCHAR(100);
  v_packageamount DECIMAL(18,2);
  v_gstpercentage DECIMAL(18,2);
  v_lastdigit INT;
  v_transactionrate DECIMAL(18,2);
BEGIN
  BEGIN
  -- BEGIN TRAN (removed)
  v_did := 0;
  v_trpid := 0;
  v_paymode := '';
  v_trsid := 0;
  v_invoiceno := '';
  v_invoicecode := 'PP';
  v_packagename := '';
  v_packageamount := 0;
  v_lastdigit := 0;
  v_transactionrate := 0;
  IF (v_mode = 1 AND v_transid <> '') THEN
  IF EXISTS(SELECT 1 FROM dbo.tbl_resellerpackagepurchase_onlinerequests WHERE transactionid = v_transid AND status = 0 AND active = 1) THEN
  SELECT RIGHT(CAST(EXTRACT(YEAR FROM CAST(dbo.FUN_GETCURRENTDATE() AS DATE)) AS TEXT), 2), RIGHT(CAST(EXTRACT(YEAR FROM CAST(dbo.FUN_GETCURRENTDATE() AS DATE)) AS TEXT), 2) + 1 INTO v_currentyear, v_nextyear;
  SELECT COALESCE(MAX(invoicecode), 0) INTO v_countno FROM tbl_reseller_package_invoice WHERE status = 1;
  v_countno := v_countno || 1;
  v_lastdigit := v_countno;
  v_currentyear := RIGHT(CAST(v_currentyear AS TEXT), 2);
  v_nextyear := RIGHT(CAST(v_nextyear AS TEXT), 2);
  SELECT RIGHT(CAST('000000' || CAST(v_countno AS VARCHAR(6)) AS TEXT), 6) INTO v_countno;
  v_invoiceno := v_invoicecode || '/' || v_currentyear || '-' || v_nextyear || '/' || v_countno;
  RAISE NOTICE '%', v_invoiceno;
  SELECT did, trpid, paymentmode INTO v_did, v_trpid, v_paymode FROM dbo.tbl_resellerpackagepurchase_onlinerequests WHERE transactionid = v_transid AND status = 0 AND active = 1;
  SELECT COALESCE(trsid, 0) INTO v_trsid FROM tbl_reseller_packages WHERE trpid = v_trpid;
  UPDATE dbo.tbl_resellerpackagepurchase_onlinerequests SET status = 1 WHERE transactionid = v_transid AND status = 0 AND active = 1;
  INSERT INTO dbo.tbl_reseller_purchased_packages_history (trpphid, did, trpid, purchaseddate, active, createdate, status, invoiceno, historydate, trsid) SELECT trppid, did, trpid, purchaseddate, active, createdate, status, invoiceno, dbo.FUN_GETCURRENTDATE(), trsid FROM tbl_reseller_purchased_packages WHERE did = v_did AND trsid = v_trsid;
  IF NOT EXISTS(SELECT 1 FROM tbl_reseller_purchased_packages WHERE did = v_did AND trsid = v_trsid) THEN
  INSERT INTO tbl_reseller_purchased_packages (did, trpid, purchaseddate, active, createdate, status, invoiceno, trsid) VALUES (v_did, v_trpid, dbo.FUN_GETCURRENTDATE(), 1, dbo.FUN_GETCURRENTDATE(), 1, v_invoiceno, v_trsid);
  ELSE
  UPDATE dbo.tbl_reseller_purchased_packages SET trpid = v_trpid, purchaseddate = dbo.FUN_GETCURRENTDATE(), active = 1, createdate = dbo.FUN_GETCURRENTDATE(), status = 1, invoiceno = v_invoiceno WHERE did = v_did AND active = 1 AND trsid = v_trsid;
  END IF;
  SELECT COALESCE(transationpayumoneyrate, 0) INTO v_transactionrate FROM tbl_companysettings WHERE pmid = 8;
  SELECT COALESCE(limits, 0) INTO v_gstpercentage FROM settings WHERE caption = 'GST PERCENTAGE';
  SELECT COALESCE(packagename, ''), COALESCE(packageamount, 0) INTO v_packagename, v_packageamount FROM tbl_reseller_packages WHERE trpid = v_trpid;
  IF EXISTS(SELECT 1 FROM tbl_reseller_package_invoice WHERE did = v_did AND status = 1 AND trsid = v_trsid) THEN
  UPDATE tbl_reseller_package_invoice SET status = 0 WHERE did = v_did AND trsid = v_trsid;
  END IF;
  INSERT INTO dbo.tbl_reseller_package_invoice (did, transactionid, invoicenumber, invoicename, packagename, amount, gstpercentage, gstamount, totalamount, paymode, status, invoicecode, invoicedate, packageid, trsid, transactionrate) VALUES (v_did, v_transid, v_invoiceno, 'IN' || v_countno || '.pdf', v_packagename, v_packageamount, v_gstpercentage, (v_packageamount * v_gstpercentage) / 100, (v_gstpercentage + (v_packageamount * v_gstpercentage) / 100), v_paymode, 1, v_lastdigit, dbo.FUN_GETCURRENTDATE(), v_trpid, v_trsid, v_transactionrate);
  v_stroutput := 'Success';
  SELECT trp.packagename, CAST(TO_CHAR(trpp.purchaseddate, 'DD TMMon YYYY') AS VARCHAR(15)), v_packageamount INTO v_strpackagename, v_packagedate, v_packageamountdata FROM dbo.tbl_reseller_purchased_packages AS trpp INNER JOIN tbl_reseller_packages AS trp ON trpp.trpid = trp.trpid WHERE trpp.trsid = v_trsid AND did = v_did AND trpp.trpid = v_trpid;
  SELECT COALESCE(packagename, '') INTO v_utilityname FROM tbl_reseller_packages WHERE trpid = v_trpid AND active = 1;
  -- COMMIT (removed)
  END IF;
  ELSE
  v_stroutput := 'Invalid Request';
  -- COMMIT (removed)
  RETURN;
  END IF;
  EXCEPTION WHEN OTHERS THEN
  IF (0 <> 0) THEN
  v_stroutput := 'Error';
  -- COMMIT (removed)
  RETURN;
  END IF;
  END;
END;
$$;


