--
-- Name: usp_update_status_and_expirydate(integer, integer, integer, character varying, integer, integer, character varying, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_update_status_and_expirydate(v_dealid integer, v_mode integer, v_state integer, v_totime character varying, v_discount integer, v_startprice integer, v_descr character varying, INOUT v_intresult integer) RETURNS integer
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF (v_mode = 1) THEN
  UPDATE portal_deal_master SET totime = CAST(v_totime AS TIMESTAMP), discount = v_discount, startprice = v_startprice, description = v_descr WHERE dealid = v_dealid;
  v_intresult := 1;
  END IF;
  IF (v_mode = 2) THEN
  UPDATE portal_deal_master SET active = v_state WHERE dealid = v_dealid;
  v_intresult := 1;
  END IF;
  IF (0 <> 0) THEN
  v_intresult := 0;
  END IF;
END;
$$;


--
-- Name: usp_updateadspaymentrequests(bigint, character varying, text, character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_updateadspaymentrequests(v_sfdid bigint, v_type character varying, v_rejection_reason text, INOUT v_strresult character varying) RETURNS character varying
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_requestamount numeric(19,4);
  v_status smallint;
  v_plid bigint;
  v_max_aew_id bigint;
BEGIN
  -- BEGIN TRAN (removed)
  v_strresult := 'ok';
  SELECT depositamount, status, plid INTO v_requestamount, v_status, v_plid FROM tbl_sponserfunddetails WHERE sfdid = v_sfdid;
  IF (v_type = 'approve') THEN
  IF (v_status = 0) THEN
  IF NOT EXISTS(SELECT plid FROM tbl_adsewallet WHERE plid = v_plid) THEN
  SELECT COALESCE(MAX(aew_id), 0) INTO v_max_aew_id FROM tbl_adsewallet;
  v_max_aew_id := v_max_aew_id + 1;
  INSERT INTO tbl_adsewallet (aew_id, plid, total_amount, current_amount, ads_deduct, status) VALUES (v_max_aew_id, v_plid, 0, 0, 0, 1);
  END IF;
  UPDATE tbl_adsewallet SET total_amount = COALESCE(total_amount, 0) + v_requestamount, current_amount = COALESCE(current_amount, 0) + v_requestamount WHERE plid = v_plid;
  UPDATE tbl_sponserfunddetails SET status = 1, fundapprovedate = dbo.fun_getCurrentDate() WHERE sfdid = v_sfdid;
  END IF;
  IF (v_status = 1) THEN
  v_strresult := 'This request is already approved !!!';
  END IF;
  IF (v_status = 2) THEN
  v_strresult := 'This request is rejected, it can not be approved .';
  END IF;
  END IF;
  IF (v_type = 'reject') THEN
  IF (v_status = 0) THEN
  UPDATE tbl_sponserfunddetails SET status = 2, fundapprovedate = dbo.fun_getCurrentDate(), rejectreview = v_rejection_reason WHERE sfdid = v_sfdid;
  END IF;
  IF (v_status = 1) THEN
  v_strresult := 'This request is approved, it can not be rejected .';
  END IF;
  IF (v_status = 2) THEN
  v_strresult := 'This request is already rejected .';
  END IF;
  END IF;
  IF (0 <> 0) THEN
  -- ROLLBACK (removed)
  v_strresult := 'some error occured !';
  RETURN;
  END IF;
  -- COMMIT (removed)
END;
$$;


--
-- Name: usp_updateaidofportalmaster(); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_updateaidofportalmaster() RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_aid text;
  v_areaname text;
  v_pincode text;
  v_ctid text;
  v_sid int;
  v_cid int;
  v_pmid bigint;
  cr_id CURSOR FOR SELECT areaname, pincode, sid, cid, pmid FROM portal_master WHERE COALESCE(aid, 0) = 0 ORDER BY pmid DESC NULLS LAST;
BEGIN
  -- BEGIN TRAN (removed)
  OPEN cr_id;
  FETCH cr_id INTO v_areaname,v_pincode,v_sid,v_cid,v_pmid;
  WHILE (found) LOOP
  SELECT ctid, aid INTO v_ctid, v_aid FROM area_master WHERE areaname = v_areaname AND cid = v_cid AND sid = v_sid AND pincode = v_pincode;
  UPDATE portal_master SET aid = v_aid, ctid = v_ctid WHERE pmid = v_pmid;
  IF (0 <> 0) THEN
  CLOSE cr_id;
  -- DEALLOCATE (removed)
  -- ROLLBACK (removed)
  RETURN;
  END IF;
  FETCH cr_id INTO v_areaname,v_pincode,v_sid,v_cid,v_pmid;
  END LOOP;
  CLOSE cr_id;
  -- DEALLOCATE (removed)
  -- COMMIT (removed)
END;
$$;


--
-- Name: usp_updateallitemssorted(text, character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_updateallitemssorted(v_sortedvalue text, INOUT v_strresult character varying) RETURNS character varying
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_seqmain int;
  v_seqcat int;
  v_seqsubcat int;
  v_count1 int;
  v_count2 int;
  v_mainid varchar(10);
  v_catid varchar(10);
  v_subcatid varchar(10);
  v_remainstring varchar(50);
  v_idx int;
  v_oldmainid varchar(10);
  v_oldcatid varchar(10);
  v_oldsubcatid varchar(10);
BEGIN
  -- BEGIN TRAN (removed)
  v_seqmain := 0;
  v_seqcat := 0;
  v_seqsubcat := 0;
  v_strresult := 'ok';
  v_oldmainid := 0;
  v_oldcatid := 0;
  v_oldsubcatid := 0;
  DROP TABLE IF EXISTS tmp_tempsinglerow;
  CREATE TEMP TABLE tmp_tempsinglerow (rowno int GENERATED BY DEFAULT AS IDENTITY,
	singlerow varchar(50)) ON COMMIT DROP;
  INSERT INTO tmp_tempsinglerow SELECT value FROM dbo.SPLITSTRINGBYCUSTOMSYMBOL1(v_sortedvalue, '~') WHERE value <> '';
  v_count1 := 1;
  SELECT COUNT(1) INTO v_count2 FROM tmp_tempsinglerow;
  WHILE (v_count1 <= v_count2) LOOP
  SELECT singlerow INTO v_remainstring FROM tmp_tempsinglerow WHERE rowno = v_count1;
  v_idx := POSITION('|' IN v_remainstring);
  v_mainid := LEFT(CAST(v_remainstring AS TEXT), v_idx - 1);
  v_remainstring := RIGHT(CAST(v_remainstring AS TEXT), LENGTH(CAST(v_remainstring AS TEXT)) - v_idx);
  v_idx := POSITION('|' IN v_remainstring);
  v_catid := LEFT(CAST(v_remainstring AS TEXT), v_idx - 1);
  v_remainstring := RIGHT(CAST(v_remainstring AS TEXT), LENGTH(CAST(v_remainstring AS TEXT)) - v_idx);
  v_subcatid := v_remainstring;
  IF (v_catid = '') THEN
  v_catid := '0';
  END IF;
  IF (v_subcatid = '') THEN
  v_subcatid := '0';
  END IF;
  IF (v_oldmainid <> v_mainid) THEN
  v_seqmain := v_seqmain + 1;
  v_seqcat := 1;
  v_seqsubcat := 1;
  END IF;
  IF (v_oldmainid = v_mainid AND v_oldcatid <> v_catid) THEN
  v_seqcat := v_seqcat + 1;
  v_seqsubcat := 1;
  END IF;
  IF (v_oldmainid = v_mainid AND v_oldcatid = v_catid AND v_oldsubcatid <> v_subcatid) THEN
  v_seqsubcat := v_seqsubcat + 1;
  END IF;
  UPDATE tbl_sub_category SET maincatid = v_mainid, catid = v_catid, sequence = v_seqsubcat WHERE subcatid = v_subcatid;
  UPDATE tbl_category SET maincatid = v_mainid, sequence = v_seqcat WHERE catid = v_catid;
  UPDATE tbl_main_category SET sequence = v_seqmain WHERE maincatid = v_mainid;
  v_oldmainid := v_mainid;
  v_oldcatid := v_catid;
  v_oldsubcatid := v_subcatid;
  v_count1 := v_count1 + 1;
  END LOOP;
  DROP TABLE IF EXISTS tmp_tempsinglerow;
  IF (0 <> 0) THEN
  -- ROLLBACK (removed)
  v_strresult := 'Something went wrong. Please try later';
  RETURN;
  END IF;
  -- COMMIT (removed)
END;
$$;


--
-- Name: usp_updateallproduct(integer, bigint, integer, numeric, numeric, numeric, integer, numeric, numeric, numeric, numeric, numeric, character varying, character varying, text, character varying, character varying, character varying, character varying, character varying, character varying, character varying, character varying, character varying, character varying, character varying, character varying, text, numeric, numeric, numeric, text, text, text, numeric); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_updateallproduct(v_mode integer DEFAULT 2, v_sprid bigint DEFAULT 10, v_isverified integer DEFAULT 0, v_sellmrp numeric DEFAULT 0, v_discount numeric DEFAULT 0, v_dap numeric DEFAULT 0, v_stockin integer DEFAULT 0, v_length numeric DEFAULT 0, v_breadth numeric DEFAULT 0, v_weight numeric DEFAULT 0, v_height numeric DEFAULT 0, v_shippingcharges numeric DEFAULT 0, v_shortdesc character varying DEFAULT ''::character varying, v_keyfeatures character varying DEFAULT ''::character varying, v_fulldesc text DEFAULT ''::text, v_strresult character varying DEFAULT ''::character varying, v_image character varying DEFAULT ''::character varying, v_manufacturingdetail character varying DEFAULT ''::character varying, v_importerdetail character varying DEFAULT ''::character varying, v_packerdetail character varying DEFAULT ''::character varying, v_gst character varying DEFAULT ''::character varying, v_procurementtype character varying DEFAULT ''::character varying, v_fullfilmentseller character varying DEFAULT ''::character varying, v_procurementsla character varying DEFAULT ''::character varying, v_hsn character varying DEFAULT ''::character varying, v_luxurycess character varying DEFAULT ''::character varying, v_countryorigin character varying DEFAULT ''::character varying, v_specification text DEFAULT ''::text, v_bv numeric DEFAULT 0.00, v_pv numeric DEFAULT 0.00, v_cashback numeric DEFAULT 0.00, v_prodimages text DEFAULT ''::text, v_allattributes text DEFAULT ''::text, v_produnit text DEFAULT ''::text, v_activationpointvalue numeric DEFAULT 0.00) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_mprid BIGINT;
  v_qccount INT;
  v_gstpercentage DECIMAL(18,2);
  v_qccounttemp INT;
  v_catid INT;
  v_subcatid INT;
  v_maincatid INT;
  v_count1 INT;
  v_count2 INT;
  v_value VARCHAR(200);
  v_title VARCHAR(100);
  v_itemval VARCHAR(100);
  v_awk INT;
BEGIN
  -- BEGIN TRAN (removed)
  IF (v_mode = 1) THEN
  v_qccount := 0;
  v_gstpercentage := 0;
  v_catid := 0;
  v_subcatid := 0;
  v_maincatid := 0;
  SELECT mprid INTO v_mprid FROM ims_subproduct WHERE sprid = v_sprid;
  SELECT qc_count INTO v_qccount FROM ims_subproduct WHERE mprid = v_mprid;
  SELECT COALESCE(vatpercvalue, 0) INTO v_gstpercentage FROM tbl_vat_categories WHERE vcid IN (SELECT vatcategoryid FROM ims_masterproduct WHERE mprid = v_mprid);
  SELECT maincategoryid, catid, subcategoryid INTO v_maincatid, v_catid, v_subcatid FROM ims_masterproduct WHERE mprid = v_mprid;
  UPDATE ims_masterproduct SET shotdescription = v_shortdesc, fulldescription = v_fulldesc, keyfeatures = v_keyfeatures, modifydate = CURRENT_TIMESTAMP WHERE mprid = v_mprid;
  UPDATE ims_subproduct SET discountpercentage = v_discount, dap = CAST((v_dap * (100 / CAST((100 + v_gstpercentage) AS DECIMAL(18, 2)))) AS DECIMAL(18, 2)), modifydate = CURRENT_TIMESTAMP, weight_kg = v_weight, length_cms = v_length, breadth_cms = v_breadth, height_cms = v_height, shippingcharges = v_shippingcharges, stockin = (stockin + v_stockin), sellmrp = v_sellmrp, procurementsla = v_procurementsla, manufacturerdetails = v_manufacturingdetail, luxurycess = v_luxurycess, hsn = v_hsn, procurementtype = v_procurementtype, fullfilmentby = v_fullfilmentseller, importerdetails = v_importerdetail, packerdetails = v_packerdetail, countryorigin = v_countryorigin, stocknet = (stocknet + v_stockin), qc_count = v_qccount + 1, specification = v_specification, bv = v_bv, pv = v_pv, cashback_per = v_cashback, activationpv_per = v_activationpointvalue, productimages = (CASE WHEN v_prodimages = '' THEN productimages ELSE v_prodimages END), unit = (CASE WHEN v_produnit = '' THEN unit ELSE v_produnit END) WHERE sprid = v_sprid;
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp (ROWNO INT GENERATED BY DEFAULT AS IDENTITY,VALUE VARCHAR(200)) ON COMMIT DROP;
  INSERT INTO tmp_temp SELECT value FROM dbo.SPLITSTRINGBYCUSTOMSYMBOL1(v_allattributes, '^') WHERE COALESCE(value, '') <> '';
  v_count1 := 1;
  SELECT COUNT(1) INTO v_count2 FROM tmp_temp;
  WHILE (v_count1 <= v_count2) LOOP
  SELECT value INTO v_value FROM tmp_temp WHERE rowno = v_count1;
  v_title := SUBSTRING(v_value FROM 1 FOR POSITION('~' IN v_value) - 1);
  v_itemval := SUBSTRING(v_value FROM POSITION('~' IN v_value) + 1 FOR LENGTH(CAST(v_value AS TEXT)));
  IF (v_value <> 'NO') THEN
  v_awk := 0;
  END IF;
  IF (COALESCE(v_subcatid, 0) <> 0) THEN
  SELECT awct_id INTO v_awk FROM tbl_attributes_with_category WHERE att_name = v_title AND (sub_cat_id = COALESCE(v_subcatid, 0) AND cat_id = COALESCE(v_catid, 0) AND main_cat_id = COALESCE(v_maincatid, 0));
  ELSE
  IF (COALESCE(v_catid, 0) <> 0) THEN
  SELECT awct_id INTO v_awk FROM tbl_attributes_with_category WHERE att_name = v_title AND sub_cat_id = 0 AND (cat_id = COALESCE(v_catid, 0) AND main_cat_id = COALESCE(v_maincatid, 0));
  SELECT awct_id INTO v_awk FROM tbl_attributes_with_category WHERE att_name = v_title AND sub_cat_id = 0 AND (cat_id = COALESCE(v_catid, 0) AND main_cat_id = COALESCE(v_maincatid, 0));
  ELSE
  IF (COALESCE(v_maincatid, 0) <> 0) THEN
  SELECT awct_id INTO v_awk FROM tbl_attributes_with_category WHERE att_name = v_title AND sub_cat_id = 0 AND cat_id = 0 AND main_cat_id = COALESCE(v_maincatid, 0);
  END IF;
  END IF;
  END IF;
  IF (v_itemval <> '' AND v_title <> '') THEN
  IF EXISTS(SELECT 1 FROM ims_masterproductattribute WHERE sprid = v_sprid AND title = v_title AND isactive = 1 AND awcid = v_awk) THEN
  UPDATE ims_masterproductattribute SET value = v_itemval, awcid = v_awk WHERE sprid = v_sprid AND title = v_title AND isactive = 1;
  ELSE
  INSERT INTO ims_masterproductattribute (sprid, title, value, showongrid, position, isactive, catid, awcid, subcatid) VALUES (v_sprid, v_title, v_itemval, 1, 1, 1, v_catid, v_awk, v_subcatid);
  END IF;
  ELSE
  IF EXISTS(SELECT 1 FROM ims_masterproductattribute WHERE sprid = v_sprid AND title = v_title AND isactive = 1 AND awcid = v_awk) THEN
  DELETE FROM ims_masterproductattribute WHERE sprid = v_sprid AND title = v_title;
  END IF;
  END IF;
  v_count1 := v_count1 + 1;
  END LOOP;
  DROP TABLE IF EXISTS tmp_temp;
  v_strresult := 'Updated Successfully';
  END IF;
  IF (v_mode = 2) THEN
  SELECT mprid INTO v_mprid FROM ims_subproduct WHERE sprid = v_sprid;
  RETURN QUERY SELECT sm.subprcode, pm.shotdescription, pm.fulldescription, pm.keyfeatures, sm.discountpercentage, sm.dap, sm.weight_kg, sm.length_cms, sm.breadth_cms, sm.height_cms, sm.shippingcharges, sm.stockin, sm.sellmrp, sm.isverified, pm.producttitle, sm.procurementsla, sm.manufacturerdetails, sm.luxurycess, sm.hsn, sm.procurementtype, sm.fullfilmentby, sm.importerdetails, sm.packerdetails, sm.countryorigin, sm.bv, sm.pv, sm.cashback_per, activationpv_per FROM ims_subproduct AS sm INNER JOIN ims_masterproduct AS pm ON sm.mprid = pm.mprid WHERE sprid = v_sprid;
  END IF;
  IF (0 <> 0) THEN
  v_strresult := 'Some Error Occoured !';
  -- ROLLBACK (removed)
  RETURN;
  END IF;
  -- COMMIT (removed)
END;
$$;


--
-- Name: usp_updateallproductlist(integer, bigint, integer, numeric, numeric, numeric, integer, numeric, numeric, numeric, numeric, numeric, character varying, character varying, text, character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_updateallproductlist(v_mode integer DEFAULT 2, v_sprid bigint DEFAULT 956, v_isverified integer DEFAULT 0, v_sellmrp numeric DEFAULT 0, v_discount numeric DEFAULT 0, v_dap numeric DEFAULT 0, v_stockin integer DEFAULT 0, v_length numeric DEFAULT 0, v_breadth numeric DEFAULT 0, v_weight numeric DEFAULT 0, v_height numeric DEFAULT 0, v_shippingcharges numeric DEFAULT 0, v_shortdesc character varying DEFAULT ''::character varying, v_keyfeatures character varying DEFAULT ''::character varying, v_fulldesc text DEFAULT ''::text, v_strresult character varying DEFAULT ''::character varying) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_mprid BIGINT;
  v_attributedata text;
BEGIN
  -- BEGIN TRAN (removed)
  IF (v_mode = 1) THEN
  SELECT mprid INTO v_mprid FROM ims_subproduct WHERE sprid = v_sprid;
  UPDATE ims_masterproduct SET shotdescription = v_shortdesc, fulldescription = v_fulldesc, keyfeatures = v_keyfeatures, modifydate = CURRENT_TIMESTAMP WHERE mprid = v_mprid;
  UPDATE ims_subproduct SET discountpercentage = v_discount, dap = v_dap, modifydate = CURRENT_TIMESTAMP, weight_kg = v_weight, length_cms = v_length, breadth_cms = v_breadth, height_cms = v_height, shippingcharges = v_shippingcharges, stockin = v_stockin, sellmrp = v_sellmrp, isverified = v_isverified WHERE sprid = v_sprid;
  v_strresult := 'updated successfully';
  END IF;
  IF (v_mode = 2) THEN
  v_attributedata := '';
  SELECT COALESCE(v_attributedata || ',', '') || (title || '^' || value) INTO v_attributedata FROM ims_masterproductattribute WHERE sprid = v_sprid;
  v_attributedata := SUBSTRING(v_attributedata FROM 2 FOR LENGTH(CAST(v_attributedata AS TEXT)));
  SELECT mprid INTO v_mprid FROM ims_subproduct WHERE sprid = v_sprid;
  RETURN QUERY SELECT COALESCE(sm.subprcode, '') AS subprcode, COALESCE(pm.shotdescription, '') AS shotdescription, COALESCE(pm.fulldescription, '') AS fulldescription, COALESCE(pm.keyfeatures, '') AS keyfeatures, COALESCE(sm.discountpercentage, 0) AS discountpercentage, COALESCE(sm.dap, 0) AS dap, COALESCE(sm.weight_kg, 0) AS weight_kg, COALESCE(sm.length_cms, 0) AS length_cms, COALESCE(sm.breadth_cms, 0) AS breadth_cms, COALESCE(sm.height_cms, 0) AS height_cms, COALESCE(sm.shippingcharges, 0) AS shippingcharges, COALESCE(sm.stockin, 0) AS stockin, COALESCE(sm.sellmrp, 0) AS sellmrp, COALESCE(sm.isverified, 0) AS isverified, COALESCE(pm.producttitle, '') AS producttitle, COALESCE(sm.fullfilmentby, 0) AS fullfilmentby, COALESCE(sm.procurementtype, 0) AS procurementtype, COALESCE(sm.procurementsla, 0) AS procurementsla, COALESCE(sm.hsn, '') AS hsn, COALESCE(sm.luxurycess, 0) AS luxurycess, COALESCE(sm.manufacturerdetails, '') AS manufacturerdetails, COALESCE(sm.importerdetails, '') AS importerdetails, COALESCE(sm.packerdetails, '') AS packerdetails, COALESCE(sm.countryorigin, 0) AS countryorigin, (SELECT vattitle FROM tbl_vat_categories WHERE vcid = sm.vatcategoryid) AS vattitle, COALESCE(sm.bv, 0) AS bv, COALESCE(sm.pv, 0) AS pv, COALESCE(sm.cashback_per, 0) AS cashback_per, COALESCE(sm.delieverycharge, 0) AS delieverycharge, COALESCE(sm.handlingcharge, 0) AS handlingcharge, COALESCE(sm.fixedfee, 0) AS fixedfee, COALESCE(sm.admincharge, 0) AS admincharge, COALESCE(specification, '') AS specification, (SELECT vatpercvalue FROM tbl_vat_categories WHERE vcid = sm.vatcategoryid) AS vatpercentage, COALESCE(tsc.bvper, 0) AS bvsubcat, COALESCE(tsc.redeemcashback_per, 0) AS pvsubcat, COALESCE(tsc.cashback_per, 0) AS cashbacksubcat, sm.productimages, pm.subcategoryid, v_attributedata AS attributedata, sm.unit, sm.activationpv_per, sm.sprid FROM ims_subproduct AS sm INNER JOIN ims_masterproduct AS pm ON sm.mprid = pm.mprid INNER JOIN tbl_sub_category AS tsc ON tsc.subcatid = pm.subcategoryid WHERE sprid = v_sprid;
  END IF;
  IF (v_mode = 3) THEN
  SELECT mprid INTO v_mprid FROM ims_subproduct WHERE sprid = v_sprid;
  RETURN QUERY SELECT COALESCE(sm.subprcode, '') AS subprcode, COALESCE(pm.shotdescription, '') AS shotdescription, COALESCE(pm.fulldescription, '') AS fulldescription, COALESCE(pm.keyfeatures, '') AS keyfeatures, COALESCE(sm.discountpercentage, 0) AS discountpercentage, COALESCE(sm.dap, 0) AS dap, COALESCE(sm.weight_kg, 0) AS weight_kg, COALESCE(sm.length_cms, 0) AS length_cms, COALESCE(sm.breadth_cms, 0) AS breadth_cms, COALESCE(sm.height_cms, 0) AS height_cms, COALESCE(sm.shippingcharges, 0) AS shippingcharges, COALESCE(sm.stockin, 0) AS stockin, COALESCE(sm.sellmrp, 0) AS sellmrp, COALESCE(sm.isverified, 0) AS isverified, COALESCE(pm.producttitle, '') AS producttitle, COALESCE(sm.fullfilmentby, 0) AS fullfilmentby, COALESCE(sm.procurementtype, 0) AS procurementtype, COALESCE(sm.procurementsla, 0) AS procurementsla, COALESCE(sm.hsn, '') AS hsn, COALESCE(sm.luxurycess, 0) AS luxurycess, COALESCE(sm.manufacturerdetails, '') AS manufacturerdetails, COALESCE(sm.importerdetails, '') AS importerdetails, COALESCE(sm.packerdetails, '') AS packerdetails, COALESCE(sm.countryorigin, 0) AS countryorigin, (SELECT vattitle FROM tbl_vat_categories WHERE vcid = sm.vatcategoryid) AS vattitle, COALESCE(dcpw.bv, 0) AS bv, COALESCE(dcpw.pv, 0) AS pv, COALESCE(dcpw.cashback_per, 0) AS cashback_per, COALESCE(dcpw.delieverycharge, 0) AS delieverycharge, COALESCE(dcpw.handlingcharge, 0) AS handlingcharge, COALESCE(dcpw.fixedfee, 0) AS fixedfee, COALESCE(dcpw.admincharge, 0) AS admincharge, COALESCE(tsc.bvper, 0) AS bvsubcat, COALESCE(tsc.redeemcashback_per, 0) AS pvsubcat, COALESCE(tsc.cashback_per, 0) AS cashbacksubcat, sm.productimages, pm.subcategoryid, sm.activationpv_per, sm.sprid FROM ims_subproduct AS sm INNER JOIN ims_masterproduct AS pm ON sm.mprid = pm.mprid INNER JOIN tbl_sub_category AS tsc ON tsc.subcatid = pm.subcategoryid LEFT JOIN tbl_distributor_comm_productwise AS dcpw ON dcpw.sprid = sm.sprid WHERE dcpw.sprid = v_sprid AND dcpw.did = v_isverified;
  END IF;
  IF (0 <> 0) THEN
  v_strresult := 'Some Error Occoured !';
  -- ROLLBACK (removed)
  RETURN;
  END IF;
  -- COMMIT (removed)
END;
$$;


--
-- Name: usp_updateallproductlist1(integer, bigint, integer, numeric, numeric, numeric, integer, numeric, numeric, numeric, numeric, numeric, character varying, character varying, text, character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_updateallproductlist1(v_mode integer DEFAULT 2, v_sprid bigint DEFAULT 6, v_isverified integer DEFAULT 0, v_sellmrp numeric DEFAULT 0, v_discount numeric DEFAULT 0, v_dap numeric DEFAULT 0, v_stockin integer DEFAULT 0, v_length numeric DEFAULT 0, v_breadth numeric DEFAULT 0, v_weight numeric DEFAULT 0, v_height numeric DEFAULT 0, v_shippingcharges numeric DEFAULT 0, v_shortdesc character varying DEFAULT ''::character varying, v_keyfeatures character varying DEFAULT ''::character varying, v_fulldesc text DEFAULT ''::text, v_strresult character varying DEFAULT ''::character varying) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_mprid BIGINT;
  v_attributedata text;
BEGIN
  -- BEGIN TRAN (removed)
  IF (v_mode = 1) THEN
  SELECT mprid INTO v_mprid FROM ims_subproduct WHERE sprid = v_sprid;
  UPDATE ims_masterproduct SET shotdescription = v_shortdesc, fulldescription = v_fulldesc, keyfeatures = v_keyfeatures, modifydate = CURRENT_TIMESTAMP WHERE mprid = v_mprid;
  UPDATE ims_subproduct SET discountpercentage = v_discount, dap = v_dap, modifydate = CURRENT_TIMESTAMP, weight_kg = v_weight, length_cms = v_length, breadth_cms = v_breadth, height_cms = v_height, shippingcharges = v_shippingcharges, stockin = v_stockin, sellmrp = v_sellmrp, isverified = v_isverified WHERE sprid = v_sprid;
  v_strresult := 'UPDATED SUCCESSFULLY';
  END IF;
  IF (v_mode = 2) THEN
  v_attributedata := '';
  SELECT COALESCE(v_attributedata || ',', '') || (title || '^' || value) INTO v_attributedata FROM ims_masterproductattribute_temp WHERE sprid = v_sprid;
  v_attributedata := SUBSTRING(v_attributedata FROM 2 FOR LENGTH(CAST(v_attributedata AS TEXT)));
  SELECT mprid INTO v_mprid FROM ims_subproduct WHERE sprid = v_sprid;
  RETURN QUERY SELECT COALESCE(sm.subprcode, '') AS subprcode, COALESCE(pm.shotdescription, '') AS shotdescription, COALESCE(pm.fulldescription, '') AS fulldescription, COALESCE(pm.keyfeatures, '') AS keyfeatures, COALESCE(sm.discountpercentage, 0) AS discountpercentage, COALESCE(sm.dap, 0) AS dap, COALESCE(sm.weight_kg, 0) AS weight_kg, COALESCE(sm.length_cms, 0) AS length_cms, COALESCE(sm.breadth_cms, 0) AS breadth_cms, COALESCE(sm.height_cms, 0) AS height_cms, COALESCE(sm.shippingcharges, 0) AS shippingcharges, COALESCE(sm.stockin, 0) AS stockin, COALESCE(sm.sellmrp, 0) AS sellmrp, COALESCE(sm.isverified, 0) AS isverified, COALESCE(pm.producttitle, '') AS producttitle, COALESCE(sm.fullfilmentby, 0) AS fullfilmentby, COALESCE(sm.procurementtype, 0) AS procurementtype, COALESCE(sm.procurementsla, 0) AS procurementsla, COALESCE(sm.hsn, '') AS hsn, COALESCE(sm.luxurycess, 0) AS luxurycess, COALESCE(sm.manufacturerdetails, '') AS manufacturerdetails, COALESCE(sm.importerdetails, '') AS importerdetails, COALESCE(sm.packerdetails, '') AS packerdetails, COALESCE(sm.countryorigin, 0) AS countryorigin, COALESCE(sm.ismerchantstatus, 0) AS ismerchantstatus, (SELECT vattitle FROM tbl_vat_categories WHERE vcid = sm.vatcategoryid) AS vattitle, COALESCE(specification, '') AS specification, sm.productimages, pm.subcategoryid, sm.unit, v_attributedata AS attributedata, sm.sprid FROM ims_subproduct_temp AS sm INNER JOIN ims_masterproduct_temp AS pm ON sm.mprid = pm.mprid WHERE sprid = v_sprid;
  END IF;
  IF (0 <> 0) THEN
  v_strresult := 'SOME ERROR OCCOURED !';
  -- ROLLBACK (removed)
  RETURN;
  END IF;
  -- COMMIT (removed)
END;
$$;


--
-- Name: usp_updatebusiness(integer, integer, bigint, bigint, bigint, character varying, bigint); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_updatebusiness(v_pmid integer DEFAULT 0, INOUT v_intresult integer DEFAULT NULL::integer, INOUT v_maxpmid bigint DEFAULT NULL::bigint, INOUT v_maxplid bigint DEFAULT NULL::bigint, INOUT v_intoplid bigint DEFAULT NULL::bigint, INOUT v_intosymb character varying DEFAULT NULL::character varying, INOUT v_introqpayregno bigint DEFAULT 0) RETURNS record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_autocatid text;
  v_companyname text;
  v_keyid text;
  v_phoneno text;
  v_building varchar(100);
  v_landmark varchar(100);
  v_comemailid varchar(100);
  v_cid int;
  v_sid int;
  v_ctid int;
  v_aid varchar(100);
  v_yearofestable varchar(100);
  v_cperwebsite varchar(100);
  v_annualturnover numeric(19,4);
  v_noofemployee varchar(100);
  v_businessstatus varchar(100);
  v_username varchar(100);
  v_ipaddress varchar(100);
  v_cpertitle varchar(100);
  v_cperdesignation varchar(100);
  v_cpermobileno varchar(100);
  v_cperemailid varchar(100);
  v_firstname varchar(100);
  v_lastname varchar(100);
  v_accounttype int;
  v_catid text;
  v_pincode varchar(100);
  v_intro_refid bigint;
  v_passworduser varchar(100);
  v_sugessmode int;
  v_introrefforewallet bigint;
  v_intoplid1 bigint;
  v_intosymb1 varchar(100);
  v_optid int;
  v_ismannual smallint;
  v_pmtid bigint;
  v_saactive smallint;
BEGIN
  v_intresult := 0;
  v_autocatid := NULL;
  v_companyname := '';
  v_phoneno := '';
  v_building := '';
  v_landmark := '';
  v_comemailid := '';
  v_cid := 0;
  v_sid := 0;
  v_ctid := 0;
  v_aid := '';
  v_yearofestable := '';
  v_cperwebsite := '';
  v_annualturnover := 0;
  v_noofemployee := '';
  v_businessstatus := '';
  v_username := '';
  v_ipaddress := '';
  v_cpertitle := '';
  v_cperdesignation := '';
  v_cpermobileno := '';
  v_cperemailid := '';
  v_firstname := '';
  v_lastname := '';
  v_accounttype := 0;
  v_catid := '';
  v_pincode := '';
  v_intro_refid := 0;
  v_passworduser := '';
  v_sugessmode := 0;
  v_introrefforewallet := 0;
  v_intoplid1 := 0;
  v_intosymb1 := '';
  v_optid := 0;
  IF EXISTS(SELECT pmtid FROM portal_master_temp WHERE pmtid = v_pmid AND active = 0) THEN
  UPDATE portal_master_temp SET active = 1, approved_date = dbo.fun_getCurrentDate() WHERE pmtid = v_pmid;
  SELECT pmt.autocatid, pmt.companyname, pmt.keyid, pmt.mobileno, pmt.address, pmt.lankmark, pmt.comemailid, pmt.cid, pmt.sid, pmt.ctid, pmt.areaname, pmt.yearofestable, pmt.url, pmt.annualturnover, pmt.noofemployee, pmt.business_status, pmt.accounttype, pmt.catid, pmt.pincode, ismannual, COALESCE(pmt.ismannual, 0), pmt.pmtid INTO v_autocatid, v_companyname, v_keyid, v_phoneno, v_building, v_landmark, v_comemailid, v_cid, v_sid, v_ctid, v_aid, v_yearofestable, v_cperwebsite, v_annualturnover, v_noofemployee, v_businessstatus, v_accounttype, v_catid, v_pincode, v_sugessmode, v_ismannual, v_pmtid FROM portal_master_temp AS pmt WHERE pmt.pmtid = v_pmid;
  IF (v_ismannual = 1) THEN
  SELECT active INTO v_saactive FROM suggestedarea_master WHERE pmtid = v_pmtid;
  IF (v_saactive = 1) THEN
  SELECT sid, ctid INTO v_sid, v_ctid FROM area_master WHERE pmtid = v_pmtid;
  v_aid := NULL;
  END IF;
  IF (v_saactive = 0) THEN
  SELECT sid, ctid, aid INTO v_sid, v_ctid, v_aid FROM area_master WHERE pmtid = v_pmtid;
  END IF;
  END IF;
  SELECT intro_refid, username, ipaddress, password, title, designation, phone, cper_emailid, sp_firstname, sp_lastname INTO v_intro_refid, v_username, v_ipaddress, v_passworduser, v_cpertitle, v_cperdesignation, v_cpermobileno, v_cperemailid, v_firstname, v_lastname FROM portal_login_temp WHERE pmtid = v_pmid;
  SELECT v_intresult INTO v_intresult FROM dbo.usp_businesslisting(v_autocatid => v_autocatid, v_keyid => v_keyid, v_companyname => v_companyname, v_optid => v_optid, v_phoneno => v_phoneno, v_building => v_building, v_landmark => v_landmark, v_comemailid => v_comemailid, v_cid => v_cid, v_sid => v_sid, v_ctid => v_ctid, v_aid => v_aid, v_yearofestable => v_yearofestable, v_cperwebsite => v_cperwebsite, v_annualturnover => v_annualturnover, v_noofemployee => v_noofemployee, v_businessstatus => v_businessstatus, v_cpertitle => v_cpertitle, v_cperdesignation => v_cperdesignation, v_cpermobileno => v_cpermobileno, v_cperemailid => v_cperemailid, v_firstname => v_firstname, v_lastname => v_lastname, v_accounttype => v_accounttype, v_intresult => v_intresult, v_pmtid => v_pmid, v_catid => v_catid, v_pincode => v_pincode, v_intro_refid => v_intro_refid, v_passworduser => v_passworduser, v_username => v_username, v_ipaddress => v_ipaddress, v_sugessmode => v_sugessmode);
  UPDATE portal_master_temp SET approved_date = dbo.fun_getCurrentDate(), active = 1 WHERE pmtid = v_pmid;
  UPDATE portal_login_temp SET active = 1 WHERE pmtid = v_pmid;
  v_maxpmid := IDENT_CURRENT('portal_master');
  v_maxplid := IDENT_CURRENT('portal_login');
  SELECT COALESCE(intro_refid, 0) INTO v_introrefforewallet FROM portal_login WHERE plid = v_maxplid;
  IF (v_introrefforewallet > 0) THEN
  SELECT currencysymbol, plid, COALESCE(qpayregno, 0) INTO v_intosymb1, v_intoplid1, v_introqpayregno FROM portal_login WHERE plid = v_introrefforewallet;
  v_intosymb := v_intosymb1;
  v_intoplid := v_intoplid1;
  ELSE
  v_intosymb := '';
  v_intoplid := 0;
  END IF;
  IF (v_intresult = 1) THEN
  RETURN;
  ELSE
  RETURN;
  END IF;
  END IF;
END;
$$;


--
-- Name: usp_updatebusinessfromadmin(integer, bigint, bigint, character varying, bigint, character varying, bigint); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_updatebusinessfromadmin(v_pmid integer DEFAULT 0, INOUT v_maxpmid bigint DEFAULT NULL::bigint, INOUT v_maxplid bigint DEFAULT NULL::bigint, INOUT v_strresult character varying DEFAULT NULL::character varying, INOUT v_intoplid bigint DEFAULT NULL::bigint, INOUT v_intosymb character varying DEFAULT NULL::character varying, INOUT v_introqpayregno bigint DEFAULT 0) RETURNS record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_autocatid text;
  v_companyname text;
  v_keyid text;
  v_phoneno text;
  v_building varchar(100);
  v_landmark varchar(100);
  v_comemailid varchar(100);
  v_cid int;
  v_sid int;
  v_ctid int;
  v_aid varchar(100);
  v_yearofestable varchar(100);
  v_cperwebsite varchar(100);
  v_annualturnover numeric(19,4);
  v_noofemployee varchar(100);
  v_businessstatus varchar(100);
  v_cpertitle varchar(100);
  v_cperdesignation varchar(100);
  v_cpermobileno varchar(100);
  v_cperemailid varchar(100);
  v_firstname varchar(100);
  v_lastname varchar(100);
  v_accounttype int;
  v_catid varchar(100);
  v_pincode varchar(100);
  v_intro_refid bigint;
  v_passworduser varchar(100);
  v_username varchar(100);
  v_ipaddress varchar(100);
  v_intresult int;
  v_loginid varchar(150);
  v_sugessmode int;
  v_introrefforewallet bigint;
  v_intoplid1 bigint;
  v_intosymb1 varchar(100);
  v_ismannual smallint;
  v_pmtid bigint;
  v_saactive smallint;
BEGIN
  -- BEGIN TRAN (removed)
  v_strresult := 'ok';
  v_companyname := '';
  v_phoneno := '';
  v_building := '';
  v_landmark := '';
  v_comemailid := '';
  v_cid := 0;
  v_sid := 0;
  v_ctid := 0;
  v_aid := '';
  v_yearofestable := '';
  v_cperwebsite := '';
  v_annualturnover := 0;
  v_noofemployee := '';
  v_businessstatus := '';
  v_cpertitle := '';
  v_cperdesignation := '';
  v_cpermobileno := '';
  v_cperemailid := '';
  v_firstname := '';
  v_lastname := '';
  v_accounttype := 0;
  v_catid := '';
  v_pincode := '';
  v_intro_refid := 0;
  v_passworduser := '';
  v_username := '';
  v_ipaddress := '';
  v_sugessmode := 0;
  v_introrefforewallet := 0;
  v_intoplid1 := 0;
  v_intosymb1 := '';
  v_intresult := 0;
  IF EXISTS(SELECT pmtid FROM portal_master_temp WHERE pmtid = v_pmid AND active = 0) THEN
  SELECT pmt.autocatid, pmt.companyname, pmt.keyid, pmt.mobileno, pmt.address, pmt.lankmark, pmt.comemailid, pmt.cid, pmt.sid, pmt.ctid, pmt.areaname, pmt.yearofestable, pmt.url, pmt.annualturnover, pmt.noofemployee, pmt.business_status, pmt.accounttype, pmt.catid, pmt.pincode, pmt.ismannual, COALESCE(pmt.ismannual, 0), pmt.pmtid INTO v_autocatid, v_companyname, v_keyid, v_phoneno, v_building, v_landmark, v_comemailid, v_cid, v_sid, v_ctid, v_aid, v_yearofestable, v_cperwebsite, v_annualturnover, v_noofemployee, v_businessstatus, v_accounttype, v_catid, v_pincode, v_sugessmode, v_ismannual, v_pmtid FROM portal_master_temp AS pmt WHERE pmt.pmtid = v_pmid;
  SELECT intro_refid, password, loginid, username, ipaddress, title, designation, phone, loginid, sp_firstname, sp_lastname INTO v_intro_refid, v_passworduser, v_loginid, v_username, v_ipaddress, v_cpertitle, v_cperdesignation, v_cpermobileno, v_cperemailid, v_firstname, v_lastname FROM portal_login_temp WHERE pmtid = v_pmid;
  IF NOT EXISTS(SELECT plid FROM portal_login WHERE loginid = v_cperemailid) THEN
  IF (v_ismannual = 1) THEN
  SELECT active INTO v_saactive FROM suggestedarea_master WHERE pmtid = v_pmtid;
  IF (v_saactive = 1) THEN
  SELECT sid, ctid, aid INTO v_sid, v_ctid, v_aid FROM area_master WHERE pmtid = v_pmtid;
  v_aid := NULL;
  END IF;
  IF (v_saactive = 0) THEN
  SELECT sid, ctid, aid INTO v_sid, v_ctid, v_aid FROM area_master WHERE pmtid = v_pmtid;
  END IF;
  END IF;
  SELECT v_intresult INTO v_intresult FROM dbo.usp_businesslisting(v_autocatid => v_autocatid, v_keyid => v_keyid, v_companyname => v_companyname, v_optid => 0, v_phoneno => v_phoneno, v_building => v_building, v_landmark => v_landmark, v_comemailid => v_comemailid, v_cid => v_cid, v_sid => v_sid, v_ctid => v_ctid, v_aid => v_aid, v_yearofestable => v_yearofestable, v_cperwebsite => v_cperwebsite, v_annualturnover => v_annualturnover, v_noofemployee => v_noofemployee, v_businessstatus => v_businessstatus, v_cpertitle => v_cpertitle, v_cperdesignation => v_cperdesignation, v_cpermobileno => v_cpermobileno, v_cperemailid => v_loginid, v_firstname => v_firstname, v_lastname => v_lastname, v_accounttype => v_accounttype, v_intresult => v_intresult, v_pmtid => v_pmid, v_catid => v_catid, v_pincode => v_pincode, v_intro_refid => v_intro_refid, v_passworduser => v_passworduser, v_username => v_username, v_ipaddress => v_ipaddress, v_sugessmode => v_sugessmode);
  UPDATE portal_master_temp SET approved_date = dbo.fun_getCurrentDate(), active = 1 WHERE pmtid = v_pmid;
  v_maxpmid := IDENT_CURRENT('portal_master');
  v_maxplid := IDENT_CURRENT('portal_login');
  SELECT COALESCE(intro_refid, 0) INTO v_introrefforewallet FROM portal_login WHERE plid = v_maxplid;
  IF (v_introrefforewallet > 0) THEN
  SELECT currencysymbol, plid, COALESCE(qpayregno, 0) INTO v_intosymb1, v_intoplid1, v_introqpayregno FROM portal_login WHERE plid = v_introrefforewallet;
  v_intosymb := v_intosymb1;
  v_intoplid := v_intoplid1;
  ELSE
  v_intosymb := '';
  v_intoplid := 0;
  v_introqpayregno := 0;
  END IF;
  ELSE
  v_strresult := 'Email ID aleready exists !';
  -- ROLLBACK (removed)
  RETURN;
  END IF;
  IF (0 <> 0) THEN
  v_strresult := 'Failed';
  -- ROLLBACK (removed)
  RETURN;
  END IF;
  ELSE
  v_strresult := 'This listing already approved !';
  -- ROLLBACK (removed)
  RETURN;
  END IF;
  -- COMMIT (removed)
END;
$$;


