    LANGUAGE plpgsql
    AS $$
DECLARE
  v_tbkdid int;
BEGIN
  v_tbkdid := 0;
  IF EXISTS(SELECT 1 FROM tbl_businesskycdetails WHERE panno = v_panno AND plid <> v_plid AND type = v_type) THEN
  v_intresult := 3;
  RETURN;
  END IF;
  IF EXISTS(SELECT 1 FROM tbl_businesskycdetails WHERE panno = v_panno AND type <> v_type) THEN
  v_intresult := 3;
  RETURN;
  ELSE
  IF NOT EXISTS(SELECT 1 FROM tbl_businesskycdetails WHERE plid = v_plid AND type = v_type) THEN
  INSERT INTO tbl_businesskycdetails (plid, entitytype, panno, doi, active, status, type) VALUES (v_plid, v_entitytype, v_panno, v_doi, 1, 1, v_type);
  v_intresult := 1;
  RETURN;
  ELSE
  SELECT COALESCE(tbkdid, 0) INTO v_tbkdid FROM tbl_businesskycdetails WHERE plid = v_plid AND type = v_type AND active = 1;
  UPDATE tbl_businesskycdetails SET entitytype = (CASE WHEN v_entitytype = 0 THEN entitytype ELSE v_entitytype END), panno = (CASE WHEN v_panno = '' THEN panno ELSE v_panno END), doi = (CASE WHEN v_doi = '' THEN doi ELSE (CASE WHEN v_doi = '' THEN NULL ELSE v_doi END) END), type = v_type WHERE plid = v_plid AND tbkdid = v_tbkdid;
  INSERT INTO tbl_businesskycdetails_history (plid, entitytype, panno, doi, type, lastupdateddate) VALUES (v_plid, v_entitytype, v_panno, v_doi, v_type, dbo.FUN_GETCURRENTDATE());
  v_intresult := 2;
  RETURN;
  END IF;
  END IF;
END;
$$;


