--
-- Name: usp_updatefundrequests(bigint, character varying, text, character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_updatefundrequests(v_sfdid bigint, v_type character varying, v_rejection_reason text, INOUT v_strresult character varying) RETURNS character varying
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_requestamount numeric(19,4);
  v_status smallint;
  v_plid bigint;
  v_max_aew_id bigint;
  v_fundtype varchar(20);
  v_paytype varchar(30);
BEGIN
  -- BEGIN TRAN (removed)
  v_strresult := 'ok';
  SELECT depositamount, status, plid, fundtype, paymenttype INTO v_requestamount, v_status, v_plid, v_fundtype, v_paytype FROM tbl_sponserfunddetails WHERE sfdid = v_sfdid;
  IF (v_type = 'approve') THEN
  IF (v_status = 0) THEN
  IF (v_fundtype = 'ppc') THEN
  IF NOT EXISTS(SELECT plid FROM tbl_adsewallet WHERE plid = v_plid) THEN
  SELECT COALESCE(MAX(aew_id), 0) INTO v_max_aew_id FROM tbl_adsewallet;
  v_max_aew_id := v_max_aew_id + 1;
  INSERT INTO tbl_adsewallet (aew_id, plid, total_amount, current_amount, ads_deduct, status) VALUES (v_max_aew_id, v_plid, 0, 0, 0, 1);
  END IF;
  UPDATE tbl_adsewallet SET total_amount = COALESCE(total_amount, 0) + v_requestamount, current_amount = COALESCE(current_amount, 0) + v_requestamount WHERE plid = v_plid;
  END IF;
  IF (v_fundtype = 'subs_wallet') THEN
  IF NOT EXISTS(SELECT plid FROM tbl_subscription_wallet WHERE plid = v_plid) THEN
  INSERT INTO tbl_subscription_wallet (plid, total_amount, current_amount, subs_deduct, status) VALUES (v_plid, 0, 0, 0, 1);
  END IF;
  UPDATE tbl_subscription_wallet SET total_amount = COALESCE(total_amount, 0) + v_requestamount, current_amount = COALESCE(current_amount, 0) + v_requestamount WHERE plid = v_plid;
  END IF;
  UPDATE tbl_sponserfunddetails SET status = 1, fundapprovedate = dbo.fun_getCurrentDate() WHERE sfdid = v_sfdid;
  IF (v_paytype = 'cash') THEN
  INSERT INTO tbl_subscription_wallet_history (plid, amount, crdrtype, type, remark, date, status) VALUES (v_plid, v_requestamount, 'Cr', 'cash', 'Cash Deposit', dbo.fun_getCurrentDate(), 1);
  END IF;
  IF (v_paytype = 'cheque') THEN
  INSERT INTO tbl_subscription_wallet_history (plid, amount, crdrtype, type, remark, date, status) VALUES (v_plid, v_requestamount, 'Cr', 'cheque', 'Cheque Deposit', dbo.fun_getCurrentDate(), 1);
  END IF;
  IF (v_paytype = 'paypal') THEN
  INSERT INTO tbl_subscription_wallet_history (plid, amount, crdrtype, type, remark, date, status) VALUES (v_plid, v_requestamount, 'Cr', 'paypal', 'Paypal Transfer', dbo.fun_getCurrentDate(), 1);
  END IF;
  END IF;
  IF (v_status = 1) THEN
  v_strresult := 'This request is already approved !!!';
  END IF;
  IF (v_status = 2) THEN
  v_strresult := 'This request is rejected, it can not be approved .';
  END IF;
  END IF;
  IF (v_type = 'reject') THEN
  IF (v_status = 0) THEN
  UPDATE tbl_sponserfunddetails SET status = 2, fundapprovedate = dbo.fun_getCurrentDate(), rejectreview = v_rejection_reason WHERE sfdid = v_sfdid;
  END IF;
  IF (v_status = 1) THEN
  v_strresult := 'This request is approved, it can not be rejected .';
  END IF;
  IF (v_status = 2) THEN
  v_strresult := 'This request is already rejected .';
  END IF;
  END IF;
  IF (0 <> 0) THEN
  -- ROLLBACK (removed)
  v_strresult := 'some error occured !';
  RETURN;
  END IF;
  -- COMMIT (removed)
END;
$$;


