--
-- Name: usp_updateorderstatus(character varying, bigint, bigint, character varying, character varying, character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_updateorderstatus(v_orderid character varying DEFAULT ''::character varying, v_branchid bigint DEFAULT 0, v_empid bigint DEFAULT 0, v_status character varying DEFAULT ''::character varying, v_remark character varying DEFAULT ''::character varying, INOUT v_strresult character varying DEFAULT NULL::character varying) RETURNS character varying
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_intstatus INT;
  v_autoremark VARCHAR(150);
  v_total_pv decimal(14,2);
  v_total_bv decimal(14,2);
  v_transactionid varchar(250);
  v_discountcodetransactionid varchar(250);
BEGIN
  -- BEGIN TRAN (removed)
  v_intstatus := 0;
  IF (v_status = 'UnVerified') THEN
  v_intstatus := -1;
  END IF;
  IF (v_status = 'Pending') THEN
  v_intstatus := 0;
  END IF;
  IF (v_status = 'Confirm') THEN
  v_intstatus := 1;
  END IF;
  IF (v_status = 'Dispatched') THEN
  v_intstatus := 2;
  END IF;
  IF (v_status = 'Pack') THEN
  v_intstatus := 3;
  END IF;
  IF (v_status = 'ReadyToShip') THEN
  v_intstatus := 4;
  END IF;
  IF (v_status = 'Cancel') THEN
  v_intstatus := 5;
  END IF;
  IF (v_status = 'Return') THEN
  v_intstatus := 6;
  END IF;
  v_strresult := 'ok^ok';
  IF (v_remark = '') THEN
  v_remark := 'Order status is ' || v_status;
  END IF;
  IF EXISTS(SELECT 1 FROM tbl_order_master WHERE orderid = v_orderid AND status = 'READYTOSHIP' AND intstatus = 4) THEN
  v_strresult := 'error^Order Allready ReadyToShip ';
  -- COMMIT (removed)
  RETURN;
  END IF;
  v_total_pv := 0;
  v_total_bv := 0;
  v_transactionid := '';
  v_discountcodetransactionid := '';
  SELECT total_pv, total_bv INTO v_total_pv, v_total_bv FROM tbl_product_order_master WHERE orderid = v_orderid;
  SELECT transactionid, discountcodetransactionid INTO v_transactionid, v_discountcodetransactionid FROM tbl_order_master WHERE orderid = v_orderid;
  IF EXISTS(SELECT orderid FROM tbl_order_master WHERE orderid = v_orderid) THEN
  UPDATE tbl_order_master SET status = v_status, intstatus = v_intstatus, description = v_remark WHERE orderid = v_orderid;
  UPDATE tbl_product_order_master SET status = v_status, intstatus = v_intstatus WHERE orderid = v_orderid;
  v_autoremark := 'Order No ' || v_orderid || ' status has been change to ' || v_status || ' by  EMP Code:' || CAST(v_branchid AS VARCHAR(20)) || ' (BRID:' || CAST(v_branchid AS VARCHAR(20)) || ')';
  INSERT INTO tbl_ordernotes (orderid, date, remark, brcode, emp_code, active, status, intstatus) VALUES (v_orderid, dbo.FUN_GETCURRENTDATE(), v_autoremark, CAST(v_branchid AS VARCHAR(20)), CAST(v_empid AS VARCHAR(20)), 1, v_status, v_intstatus);
  IF (v_status = 'ReadyToShip' AND v_intstatus = 4) THEN
  SELECT v_result INTO v_strresult FROM dbo.ims_usp_createorderledger(v_orderid => v_orderid, v_operatoruserid => v_empid, v_result => v_strresult);
  v_strresult := 'ok^ok';
  END IF;
  ELSE
  v_strresult := 'error^Invalid Order No';
  -- COMMIT (removed)
  RETURN;
  END IF;
  IF (0 <> 0) THEN
  -- ROLLBACK (removed)
  v_strresult := 'error^' || 0;
  RETURN;
  END IF;
  -- COMMIT (removed)
END;
$$;


--
-- Name: usp_updateorderstatus_new(character varying, character varying, character varying, character varying, character varying, boolean, character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_updateorderstatus_new(v_orderid character varying DEFAULT 'OD378802751'::character varying, v_poid character varying DEFAULT 172, v_status character varying DEFAULT NULL::character varying, v_remark character varying DEFAULT 'AAA'::character varying, v_reason character varying DEFAULT NULL::character varying, v_iscancelbymember boolean DEFAULT false, INOUT v_strresult character varying DEFAULT ''::character varying) RETURNS character varying
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_intstatus INT;
  v_autoremark VARCHAR(150);
  v_activationpv DECIMAL(18,8);
  v_orderamount DECIMAL(18,2);
  v_oldbalance DECIMAL(18,2);
  v_loginid VARCHAR(50);
  v_clid INT;
  v_availablebalance DECIMAL(18,2);
  v_processorderno VARCHAR(50);
  v_processresult VARCHAR(250);
  v_loopcount INT;
  v_totalrows INT;
  v_output VARCHAR(500);
  v_distributorbalance DECIMAL (18,8);
  v_billamount DECIMAL (18,8);
  v_did1 INT;
  v_pmid1 INT;
  v_loginid1 VARCHAR(100);
BEGIN
  -- BEGIN TRAN (removed)
  v_intstatus := 0;
  IF (v_status = 'Completed') THEN
  v_intstatus := 1;
  END IF;
  IF (v_status = 'Cancel') THEN
  v_intstatus := 7;
  END IF;
  IF (v_status = 'Return') THEN
  v_intstatus := 8;
  END IF;
  v_strresult := 'ok^ok';
  IF (v_remark = '') THEN
  v_remark := 'Order Status Is ' || v_status;
  END IF;
  v_activationpv := 0.00;
  SELECT order_activationpv INTO v_activationpv FROM tbl_order_master WHERE orderid = v_orderid;
  IF (v_activationpv > 0) THEN
  v_strresult := 'error^Order Can Not Be Cancel !';
  -- COMMIT (removed)
  RETURN;
  END IF;
  IF (v_intstatus = 7) THEN
  IF NOT EXISTS(SELECT 1 FROM tbl_product_order_master WHERE orderid = v_orderid AND intstatus = 0) THEN
  v_strresult := 'error^Order Can Not Be Cancel !';
  -- COMMIT (removed)
  RETURN;
  END IF;
  IF EXISTS(SELECT 1 FROM tbl_product_order_master WHERE orderid = v_orderid AND intstatus <> 0) THEN
  v_strresult := 'error^Order Can Not Be Cancel !';
  -- COMMIT (removed)
  RETURN;
  END IF;
  END IF;
  RAISE NOTICE '%', 11;
  IF EXISTS(SELECT * FROM tbl_product_order_master WHERE orderid = v_orderid) THEN
  RAISE NOTICE '%', 12;
  UPDATE tbl_order_master SET status = v_status, intstatus = v_intstatus, description = v_remark WHERE orderid = v_orderid;
  UPDATE tbl_product_order_master SET status = v_status, intstatus = v_intstatus, reason = v_reason, iscancelbymember = (CASE WHEN v_intstatus <> 7 THEN v_iscancelbymember ELSE 0 END), isreturn = (CASE WHEN v_intstatus = 7 THEN 1 ELSE 0 END), cancellationtype = 1 WHERE orderid = v_orderid;
  UPDATE tbl_order_confirmedstaus SET cancel = dbo.FUN_GETCURRENTDATE() WHERE orderid = v_orderid;
  IF (v_iscancelbymember = 1) THEN
  RAISE NOTICE '%', 13;
  v_autoremark := 'ORDER NO :' || v_orderid || ' STATUS HAS BEEN CHANGE TO ' || v_status || ' BY  OWN CUSTOMER WITH REASON : ' || v_reason;
  ELSE
  RAISE NOTICE '%', 14;
  v_autoremark := 'ORDER NO :' || v_orderid || ' STATUS HAS BEEN CHANGE TO ' || v_status || ' BY  OWN CUSTOMER WITH REASON : ' || v_reason;
  END IF;
  INSERT INTO tbl_ordernotes (orderid, date, remark, active, status, intstatus) VALUES (v_orderid, dbo.FUN_GETCURRENTDATE(), v_autoremark, 1, v_status, v_intstatus);
  IF (v_intstatus IN (7, 8)) THEN
  v_orderamount := 0;
  v_oldbalance := 0;
  v_loginid := '';
  v_clid := 0;
  v_availablebalance := 0;
  SELECT SUM(COALESCE(total_purchase_cost, 0)), COALESCE(loginid, '') INTO v_orderamount, v_loginid FROM tbl_product_order_master WHERE orderid = v_orderid GROUP BY loginid;
  SELECT clid INTO v_clid FROM tbl_customerlogin WHERE loginid = v_loginid;
  SELECT COALESCE(availablebalance, 0) INTO v_oldbalance FROM tbl_customerwallet WHERE clid = v_clid;
  UPDATE tbl_customerwallet SET availablebalance = availablebalance + v_orderamount WHERE clid = v_clid;
  INSERT INTO tbl_customerwallet_statements (clid, processdate, crdrtype, cramt, dramt, old_balance, balance, remarks, traceno, status) VALUES (v_clid, dbo.FUN_GETCURRENTDATE(), 'Cr', v_orderamount, 0, v_oldbalance, (v_oldbalance + v_orderamount), 'Wallet Credited Against Cancelled Order: ' || CAST(v_orderid AS VARCHAR(50)) || '', '', 1);
  END IF;
  IF (v_intstatus = 7 OR v_intstatus = 8) THEN
  v_processorderno := '';
  v_processresult := '';
  v_loopcount := 1;
  v_totalrows := 0;
  SELECT orderno INTO v_processorderno FROM tbl_product_order_master WHERE orderid = v_orderid;
  v_output := '';
  v_distributorbalance := 0;
  v_billamount := 0;
  v_did1 := 0;
  v_pmid1 := 0;
  v_loginid1 := '';
  SELECT total_purchase_cost INTO v_billamount FROM tbl_product_order_master WHERE orderid = v_orderid;
  SELECT loginid INTO v_loginid1 FROM tbl_order_master WHERE orderid = v_orderid;
  SELECT did INTO v_did1 FROM tbl_customerlogin WHERE loginid = v_loginid1;
  SELECT pmid INTO v_pmid1 FROM tbl_distributor WHERE did = v_did1;
  SELECT COALESCE(available_wallet, 0) INTO v_distributorbalance FROM tbl_distributor_prepaid_setting WHERE pmid = v_pmid1;
  UPDATE tbl_distributor_prepaid_setting SET available_wallet = available_wallet + v_billamount, used_wallet = used_wallet - v_billamount WHERE pmid = v_pmid1;
  INSERT INTO tbl_resellerwalletstatement (did, date, crdrtype, cr_amount, dr_amount, remarks, status, traceno, old_bal, balance, trsid) VALUES (v_did1, dbo.FUN_GETCURRENTDATE(), 'Cr', v_billamount, 0, v_remark, 1, v_orderid, v_distributorbalance, (v_distributorbalance + v_billamount), 2);
  DROP TABLE IF EXISTS tmp_allorders;
  CREATE TEMP TABLE tmp_allorders (ROWNUMBER INT GENERATED BY DEFAULT AS IDENTITY NOT NULL,            
    ORDERNO VARCHAR(50)) ON COMMIT DROP;
  INSERT INTO tmp_allorders SELECT orderno FROM tbl_product_order_master WHERE intstatus = 0 AND orderid = v_orderid AND status = 'Pending';
  SELECT COUNT(1) INTO v_totalrows FROM tmp_allorders;
  WHILE (v_loopcount <= v_totalrows) LOOP
  SELECT orderno INTO v_processorderno FROM tmp_allorders WHERE rownumber = v_loopcount;
  SELECT v_strresult INTO v_processresult FROM dbo.usp_manageresellercommission(v_orderno => v_processorderno, v_issettlementprocess => 0, v_strresult => v_processresult);
  v_loopcount := v_loopcount + 1;
  END LOOP;
  END IF;
  ELSE
  RAISE NOTICE '%', 15;
  v_strresult := 'error^Invalid Order No';
  -- COMMIT (removed)
  RETURN;
  END IF;
  IF (0 <> 0) THEN
  -- ROLLBACK (removed)
  v_strresult := 'error^' || 0;
  RETURN;
  END IF;
  -- COMMIT (removed)
END;
$$;


--
-- Name: usp_updateorderstatus_new_back04072018(character varying, character varying, character varying, character varying, character varying, boolean, character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_updateorderstatus_new_back04072018(v_orderid character varying, v_poid character varying, v_status character varying, v_remark character varying DEFAULT ''::character varying, v_reason character varying DEFAULT NULL::character varying, v_iscancelbymember boolean DEFAULT false, INOUT v_strresult character varying DEFAULT NULL::character varying) RETURNS character varying
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_intstatus INT;
  v_autoremark VARCHAR(150);
  v_qty INT;
  v_sprid BIGINT;
BEGIN
  -- BEGIN TRAN (removed)
  v_intstatus := 0;
  v_qty := 0;
  v_sprid := 0;
  IF (v_status = 'Completed') THEN
  v_intstatus := 1;
  END IF;
  IF (v_status = 'Cancel') THEN
  v_intstatus := 2;
  END IF;
  IF (v_status = 'Return') THEN
  v_intstatus := 3;
  END IF;
  v_strresult := 'ok^ok';
  IF (v_remark = '') THEN
  v_remark := 'Order status is ' || v_status;
  END IF;
  IF EXISTS(SELECT 1 FROM tbl_order_master WHERE orderid = v_orderid AND status = 'Completed' AND v_status <> 'Return' AND intstatus = 1) THEN
  v_strresult := 'error^Order Allready Completed ';
  -- COMMIT (removed)
  RETURN;
  END IF;
  RAISE NOTICE '%', 11;
  IF EXISTS(SELECT * FROM tbl_product_order_master WHERE orderid = v_orderid AND poid = CAST(v_poid AS BIGINT)) THEN
  RAISE NOTICE '%', 12;
  UPDATE tbl_order_master SET status = v_status, intstatus = v_intstatus, description = v_remark WHERE orderid = v_orderid;
  UPDATE tbl_product_order_master SET status = v_status, intstatus = v_intstatus, reason = v_reason, v_qty = product_qty, v_sprid = subprcode, iscancelbymember = (CASE WHEN v_intstatus <> 3 THEN v_iscancelbymember ELSE 0 END), isreturn = (CASE WHEN v_intstatus = 3 THEN 1 ELSE 0 END) WHERE orderid = v_orderid AND poid = CAST(v_poid AS BIGINT);
  UPDATE ims_subproduct SET stockin = COALESCE(stockin, 0) + v_qty, stockout = COALESCE(stockout, 0) - v_qty, stocknet = COALESCE(stocknet, 0) + v_qty, isoutofstock = (CASE WHEN COALESCE(stockin, 0) = v_qty THEN 1 ELSE 0 END) WHERE sprid = v_sprid;
  IF (v_iscancelbymember = 1) THEN
  RAISE NOTICE '%', 13;
  v_autoremark := 'Order No :' || v_orderid || ',POID : ' || v_poid || ' status has been change to ' || v_status || ' by  Own Customer with Reason : ' || v_reason;
  ELSE
  RAISE NOTICE '%', 14;
  v_autoremark := 'Order No :' || v_orderid || ',POID : ' || v_poid || ' status has been change to ' || v_status || ' by  Own Customer with Reason : ' || v_reason;
  END IF;
  INSERT INTO tbl_ordernotes (orderid, date, remark, active, status, intstatus) VALUES (v_orderid, dbo.FUN_GETCURRENTDATE(), v_autoremark, 1, v_status, v_intstatus);
  ELSE
  RAISE NOTICE '%', 15;
  v_strresult := 'error^Invalid Order No';
  -- COMMIT (removed)
  RETURN;
  END IF;
  IF (0 <> 0) THEN
  -- ROLLBACK (removed)
  v_strresult := 'error^' || 0;
  RETURN;
  END IF;
  -- COMMIT (removed)
END;
$$;


