  UPDATE tbl_product_order_master SET status = v_status, intstatus = v_intstatus, reason = v_reason, iscancelbymember = (CASE WHEN v_intstatus <> 7 THEN v_iscancelbymember ELSE 0 END) WHERE orderid = v_orderid;
  UPDATE tbl_order_confirmedstaus SET refundfileimage = v_image, refunddate = dbo.FUN_GETCURRENTDATE() WHERE orderid = v_orderid;
  IF (v_iscancelbymember = 1) THEN
  RAISE NOTICE '%', 13;
  v_autoremark := 'ORDER NO :' || v_orderid || ' STATUS HAS BEEN CHANGE TO ' || v_status || ' BY  OWN CUSTOMER WITH REASON : ' || v_reason;
  ELSE
  RAISE NOTICE '%', 14;
  v_autoremark := 'ORDER NO :' || v_orderid || ' STATUS HAS BEEN CHANGE TO ' || v_status || ' BY  OWN CUSTOMER WITH REASON : ' || v_reason;
  END IF;
  INSERT INTO tbl_ordernotes (orderid, date, remark, active, status, intstatus) VALUES (v_orderid, dbo.FUN_GETCURRENTDATE(), v_autoremark, 1, v_status, v_intstatus);
  ELSE
  v_strresult := 'error^Invalid Order No';
  -- COMMIT (removed)
  RETURN;
  END IF;
  IF (0 <> 0) THEN
  -- ROLLBACK (removed)
  v_strresult := 'error^' || 0;
  RETURN;
  END IF;
  -- COMMIT (removed)
END;
$$;


--
-- Name: usp_updateorderstatus_return(character varying, character varying, character varying, character varying, character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_updateorderstatus_return(v_orderid character varying DEFAULT 'OD378802751'::character varying, v_status character varying DEFAULT ''::character varying, v_remark character varying DEFAULT 'AAA'::character varying, v_reason character varying DEFAULT NULL::character varying, INOUT v_strresult character varying DEFAULT ''::character varying) RETURNS character varying
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_intstatus INT;
  v_autoremark VARCHAR(150);
  v_activationpv DECIMAL(18,8);
  v_orderamount DECIMAL(18,2);
  v_oldbalance DECIMAL(18,2);
