  END IF;
  IF (v_intstatus = 8) THEN
  v_processorderno := '';
  v_processresult := '';
  v_loopcount := 1;
  v_totalrows := 0;
  SELECT orderno INTO v_processorderno FROM tbl_product_order_master WHERE orderid = v_orderid;
  v_output := '';
  v_distributorbalance := 0;
  v_billamount := 0;
  v_did1 := 0;
  v_pmid1 := 0;
  v_loginid1 := '';
  SELECT total_purchase_cost INTO v_billamount FROM tbl_product_order_master WHERE orderid = v_orderid;
  SELECT loginid INTO v_loginid1 FROM tbl_order_master WHERE orderid = v_orderid;
  SELECT did INTO v_did1 FROM tbl_customerlogin WHERE loginid = v_loginid1;
  SELECT pmid INTO v_pmid1 FROM tbl_distributor WHERE did = v_did1;
  SELECT COALESCE(available_wallet, 0) INTO v_distributorbalance FROM tbl_distributor_prepaid_setting WHERE pmid = v_pmid1;
  UPDATE tbl_distributor_prepaid_setting SET available_wallet = available_wallet + v_billamount, used_wallet = used_wallet - v_billamount WHERE pmid = v_pmid1;
  INSERT INTO tbl_resellerwalletstatement (did, date, crdrtype, cr_amount, dr_amount, remarks, status, traceno, old_bal, balance, trsid) VALUES (v_did1, dbo.FUN_GETCURRENTDATE(), 'Cr', v_billamount, 0, v_remark, 1, v_orderid, v_distributorbalance, (v_distributorbalance + v_billamount), 2);
  DROP TABLE IF EXISTS tmp_allorders;
  CREATE TEMP TABLE tmp_allorders (ROWNUMBER INT GENERATED BY DEFAULT AS IDENTITY NOT NULL,              
    ORDERNO VARCHAR(50)) ON COMMIT DROP;
  INSERT INTO tmp_allorders SELECT orderno FROM tbl_product_order_master WHERE intstatus = 0 AND orderid = v_orderid AND status = 'Pending';
  SELECT COUNT(1) INTO v_totalrows FROM tmp_allorders;
  WHILE (v_loopcount <= v_totalrows) LOOP
  SELECT orderno INTO v_processorderno FROM tmp_allorders WHERE rownumber = v_loopcount;
  IF (v_intstatus = 8) THEN
  SELECT v_strresult INTO v_processresult FROM dbo.usp_manageresellercommission(v_orderno => v_processorderno, v_issettlementprocess => 0, v_strresult => v_processresult);
  END IF;
  v_loopcount := v_loopcount + 1;
  END LOOP;
  END IF;
  ELSE
  RAISE NOTICE '%', 15;
  v_strresult := 'error^Invalid Order No';
  -- COMMIT (removed)
  RETURN;
  END IF;
  IF (0 <> 0) THEN
  -- ROLLBACK (removed)
  v_strresult := 'error^' || 0;
  RETURN;
  END IF;
  -- COMMIT (removed)
END;
$$;


--
-- Name: usp_updateorderstatusexcel(integer, character varying, character varying, integer, character varying, bigint, bigint, character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_updateorderstatusexcel(v_poid integer DEFAULT 0, v_status character varying DEFAULT ''::character varying, v_docketno character varying DEFAULT ''::character varying, v_cmid integer DEFAULT 0, v_orderid character varying DEFAULT ''::character varying, v_branchid bigint DEFAULT 0, v_empid bigint DEFAULT 0, INOUT v_strresult character varying DEFAULT NULL::character varying) RETURNS character varying
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_intstatus INT;
  v_autoremark VARCHAR(150);
BEGIN
  -- BEGIN TRAN (removed)
  v_intstatus := 0;
  IF (v_status = '') THEN
  v_strresult := 'error^Status is not defined';
  -- COMMIT (removed)
  RETURN;
  END IF;
  IF (v_docketno = '') THEN
  v_strresult := 'error^Docket Number not defined';
  -- COMMIT (removed)
  RETURN;
  END IF;
  IF (v_cmid = '') THEN
  v_strresult := 'error^Courier is not defined';
  -- COMMIT (removed)
  RETURN;
  END IF;
  IF (v_status = 'UnVerified') THEN
  v_intstatus := -1;
  END IF;
  IF (v_status = 'Pending') THEN
  v_intstatus := 0;
  END IF;
  IF (v_status = 'Confirm') THEN
  v_intstatus := 1;
  END IF;
  IF (v_status = 'Dispatched') THEN
  v_intstatus := 2;
  END IF;
  IF (v_status = 'Pack') THEN
  v_intstatus := 3;
  END IF;
  IF (v_status = 'ReadyToShip') THEN
  v_intstatus := 4;
  END IF;
  IF (v_status = 'Cancel') THEN
  v_intstatus := 5;
  END IF;
  IF (v_status = 'Return') THEN
  v_intstatus := 6;
  END IF;
  v_strresult := 'ok^ok';
  IF EXISTS(SELECT 1 FROM tbl_order_master WHERE orderid = v_orderid AND status = 'READYTOSHIP' AND intstatus = 4) THEN
  v_strresult := 'error^Order Allready ReadyToShip ';
  -- COMMIT (removed)
  RETURN;
  END IF;
  IF EXISTS(SELECT orderid FROM tbl_order_master WHERE orderid = v_orderid) THEN
  UPDATE tbl_product_order_master SET status = v_status, intstatus = v_intstatus, docketno = v_docketno, cmid = v_cmid WHERE poid = v_poid;
  INSERT INTO tbl_ordernotes (orderid, date, remark, brcode, emp_code, active, status, intstatus) VALUES (v_orderid, dbo.FUN_GETCURRENTDATE(), v_autoremark, CAST(v_branchid AS VARCHAR(20)), CAST(v_empid AS VARCHAR(20)), 1, v_status, v_intstatus);
  IF (v_status = 'ReadyToShip' AND v_intstatus = 4) THEN
  SELECT v_result INTO v_strresult FROM dbo.ims_usp_createorderledger(v_orderid => v_orderid, v_operatoruserid => v_empid, v_result => v_strresult);
  v_strresult := 'ok^ok';
  END IF;
  ELSE
  v_strresult := 'error^Invalid Order No';
  -- COMMIT (removed)
  RETURN;
  END IF;
  IF (0 <> 0) THEN
  -- ROLLBACK (removed)
  v_strresult := 'error^' || 0;
  RETURN;
  END IF;
  -- COMMIT (removed)
END;
$$;


--
-- Name: usp_updateorderstatusmerchant_complete(character varying, bigint, bigint, integer, character varying, character varying, character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_updateorderstatusmerchant_complete(v_orderno character varying DEFAULT '913385'::character varying, v_branchid bigint DEFAULT 1, v_empid bigint DEFAULT 1, v_intstatus integer DEFAULT 6, v_remark character varying DEFAULT ''::character varying, INOUT v_strresult character varying DEFAULT 0, v_statusdate character varying DEFAULT ''::character varying) RETURNS character varying
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_status VARCHAR(50);
  v_autoremark VARCHAR(150);
  v_orderid VARCHAR(50);
  v_totalcountorder int;
  v_tocompleteorder int;
  v_stroutput1 varchar(100);
  v_loginid1 VARCHAR(100);
  v_intresult varchar(200);
  v_tranids varchar(200);
  v_paymentmodeno INT;
  v_paymodename VARCHAR(50);
  v_ref_regnoconf BIGINT;
  v_fromregnoid BIGINT;
  v_allproductname VARCHAR(5000);
  v_orderamount DECIMAL(14,4);
  v_orderbva DECIMAL(14,4);
  v_username VARCHAR(50);
  v_transactioniduser VARCHAR(200);
  v_stroutputgetcrypto VARCHAR(500);
  v_intresultgetcrypto INT;
  v_duedate timestamp;
  v_deliverydate timestamp;
BEGIN
  -- BEGIN TRAN (removed)
  v_status := '';
  v_orderid := '';
  IF (v_intstatus <> 6) THEN
  v_strresult := 'WRONG STATUS.';
  -- ROLLBACK (removed)
  RETURN;
  END IF;
  IF (v_orderno = '') THEN
  v_strresult := 'ORDER NUMBER MISSING.';
  -- ROLLBACK (removed)
  RETURN;
  END IF;
  IF (v_statusdate = '') THEN
  SELECT dbo.FUN_GETCURRENTDATE() INTO v_statusdate;
  END IF;
  SELECT COALESCE(statusname, '') INTO v_status FROM orderstatusmaster WHERE osid = v_intstatus AND status = 1;
  SELECT COALESCE(orderid, '') INTO v_orderid FROM tbl_product_order_master WHERE orderno = v_orderno;
  IF (v_remark = '') THEN
  v_remark := 'ORDER STATUS IS ' || v_status;
  END IF;
  IF EXISTS(SELECT orderno FROM tbl_product_order_master WHERE orderid = v_orderid AND orderno = v_orderno) THEN
  UPDATE tbl_product_order_master SET status = v_status, intstatus = v_intstatus WHERE orderid = v_orderid AND orderno = v_orderno;
  UPDATE tbl_order_confirmedstaus SET delivered = v_statusdate, status = v_intstatus WHERE orderid = v_orderid AND orderno = v_orderno AND status = 1;
  SELECT COUNT(1) INTO v_totalcountorder FROM tbl_product_order_master WHERE orderid = v_orderid AND intstatus <> 7;
  SELECT COUNT(1) INTO v_tocompleteorder FROM tbl_product_order_master WHERE orderid = v_orderid AND intstatus = v_intstatus;
  IF (v_totalcountorder = v_tocompleteorder) THEN
  UPDATE tbl_order_master SET status = v_status, intstatus = v_intstatus, description = v_remark WHERE orderid = v_orderid;
  END IF;
  v_autoremark := 'ORDER NO ' || v_orderid || ' STATUS HAS BEEN CHANGE TO ' || v_status || ' BY  EMP CODE:' || CAST(v_branchid AS VARCHAR(20)) || ' (BRID:' || CAST(v_branchid AS VARCHAR(20)) || ')';
  INSERT INTO tbl_ordernotes (orderid, date, remark, brcode, emp_code, active, status, intstatus) VALUES (v_orderno, dbo.FUN_GETCURRENTDATE(), v_autoremark, CAST(v_branchid AS VARCHAR(20)), CAST(v_empid AS VARCHAR(20)), 1, v_status, v_intstatus);
  IF (v_intstatus = 4) THEN
  SELECT v_result INTO v_strresult FROM dbo.ims_usp_createorderledger(v_orderid => v_orderid, v_operatoruserid => v_empid, v_result => v_strresult);
  v_strresult := 'OK^OK';
  END IF;
  IF (v_totalcountorder = v_tocompleteorder) THEN
  IF (v_intstatus = 6) THEN
  v_stroutput1 := '';
  v_loginid1 := '';
  v_intresult := '';
  v_tranids := '';
  v_paymentmodeno := 0;
  v_paymodename := '';
  v_ref_regnoconf := 0;
  v_fromregnoid := 0;
  v_allproductname := '';
  v_orderamount := 0;
  v_orderbva := 0;
  v_username := '';
  v_transactioniduser := '';
  v_stroutputgetcrypto := '';
  v_intresultgetcrypto := 0;
  SELECT paymode, payidforwordaffiliateid, transactionid INTO v_paymodename, v_fromregnoid, v_transactioniduser FROM tbl_order_master WHERE orderid = v_orderid;
  SELECT SUM((COALESCE(total_dap, 0) + COALESCE(total_ship_ch, 0) + COALESCE(total_vat, 0))), SUM(total_bv) INTO v_orderamount, v_orderbva FROM tbl_product_order_master WHERE orderid = v_orderid AND intstatus = 6;
  IF (v_paymodename = 'COD') THEN
  v_paymodename := 'COD';
  v_paymentmodeno := 6;
  ELSE
  v_paymodename := 'I-WALLET';
  v_paymentmodeno := 7;
  END IF;
  SELECT loginid INTO v_loginid1 FROM tbl_product_order_master WHERE orderid = v_orderid;
  SELECT COALESCE(reference_regno, 0), username INTO v_ref_regnoconf, v_username FROM tbl_customerlogin WHERE loginid = v_loginid1;
  SELECT COALESCE(v_allproductname || ',', '') || CAST(product_name AS VARCHAR) INTO v_allproductname FROM tbl_product_order_master WHERE orderid = v_orderid;
  v_allproductname := RIGHT(CAST(v_allproductname AS TEXT), LENGTH(CAST(v_allproductname AS TEXT)) - 1);
  v_duedate := (dbo.FUN_GETCURRENTDATE()) + INTERVAL '14 DAY';
  v_deliverydate := dbo.FUN_GETCURRENTDATE();
  UPDATE tbl_merchant_ordertransactions SET deliverydate = v_deliverydate, duedate = v_duedate WHERE orderid = v_orderid;
  v_strresult := 1;
  END IF;
  END IF;
  ELSE
  v_strresult := 'ERROR^INVALID ORDER NO';
  -- COMMIT (removed)
  RETURN;
  END IF;
  IF (0 <> 0) THEN
  -- ROLLBACK (removed)
  v_strresult := 'ERROR^' || 0;
  RETURN;
  END IF;
  -- COMMIT (removed)
END;
$$;


