-- Name: usp_updatepaymentgateway(character varying, integer, character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_updatepaymentgateway(v_paymode character varying DEFAULT ''::character varying, v_checked integer DEFAULT 0, INOUT v_stroutput character varying DEFAULT ''::character varying) RETURNS character varying
