--
-- Name: usp_updateprdouctcount(integer, integer, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_updateprdouctcount(v_sprid integer DEFAULT 1305, v_status integer DEFAULT 1, INOUT v_intresult integer DEFAULT 0) RETURNS integer
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_mprid INT;
  v_maincatgoryid INT;
  v_catid INT;
  v_subcatid INT;
  v_totalproduct int;
BEGIN
  -- BEGIN TRAN (removed)
  -- SET option (removed)
  IF EXISTS(SELECT 1 FROM ims_subproduct WHERE sprid = v_sprid AND isverified <> v_status) THEN
  UPDATE ims_subproduct SET isverified = v_status WHERE sprid = v_sprid;
  v_intresult := v_status;
  END IF;
  SELECT mprid INTO v_mprid FROM ims_subproduct WHERE sprid = v_sprid;
  SELECT maincategoryid, catid, subcategoryid INTO v_maincatgoryid, v_catid, v_subcatid FROM ims_masterproduct WHERE mprid = v_mprid;
  IF (v_maincatgoryid <> 0) THEN
  SELECT v_totalcount INTO v_totalproduct FROM dbo.usp_totalproducts(v_maincatid => v_maincatgoryid, v_catid => 0, v_subcatid => 0, v_totalcount => v_totalproduct);
  UPDATE tbl_main_category SET totalactive = v_totalproduct WHERE maincatid = v_maincatgoryid AND status = 1 AND isdelete = 0;
  END IF;
  IF (v_maincatgoryid <> 0 AND v_catid <> 0) THEN
  SELECT v_totalcount INTO v_totalproduct FROM dbo.usp_totalproducts(v_maincatid => v_maincatgoryid, v_catid => v_catid, v_subcatid => 0, v_totalcount => v_totalproduct);
  UPDATE tbl_category SET totalactive = v_totalproduct WHERE catid = v_catid AND maincatid = v_maincatgoryid AND status = 1 AND isdelete = 0;
  END IF;
  IF (v_maincatgoryid <> 0 AND v_catid <> 0 AND v_subcatid <> 0) THEN
  SELECT v_totalcount INTO v_totalproduct FROM dbo.usp_totalproducts(v_maincatid => v_maincatgoryid, v_catid => v_catid, v_subcatid => v_subcatid, v_totalcount => v_totalproduct);
  UPDATE tbl_sub_category SET totalactive = v_totalproduct WHERE subcatid = v_subcatid AND catid = v_catid AND maincatid = v_maincatgoryid AND status = 1 AND isdelete = 0;
  END IF;
  v_intresult := v_status;
  RAISE NOTICE '%', v_intresult;
  -- SET option (removed)
  -- COMMIT (removed)
END;
$$;


--
-- Name: usp_updateprofile_mobile(bigint, character varying, integer, character varying, character varying, character varying, character varying, character varying, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_updateprofile_mobile(v_clid bigint DEFAULT 2189, v_name character varying DEFAULT ''::character varying, v_gender integer DEFAULT 0, v_mobile character varying DEFAULT ''::character varying, v_emailid character varying DEFAULT ''::character varying, INOUT v_strresult character varying DEFAULT ''::character varying, v_imagename character varying DEFAULT ''::character varying, v_username character varying DEFAULT ''::character varying, v_did integer DEFAULT 0) RETURNS character varying
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_emailcount int;
  v_pvsemailid varchar(50);
  v_getcount int;
BEGIN
  v_emailcount := 0;
  v_pvsemailid := '';
  v_getcount := 0;
  SELECT COALESCE(COUNT(1), 0) INTO v_getcount FROM tbl_customerlogin WHERE clid = v_clid AND did = v_did;
  IF (v_getcount = 0) THEN
  v_strresult := 'Something went wrong';
  ELSE
  v_strresult := 'SUCCESS';
  END IF;
  SELECT COALESCE(COUNT(1), 0) INTO v_emailcount FROM tbl_customerlogin WHERE emailid = v_emailid AND clid <> v_clid;
  SELECT COALESCE(emailid, '') INTO v_pvsemailid FROM tbl_customerlogin WHERE clid = v_clid;
  IF (v_username <> '' AND v_name <> '') THEN
  UPDATE tbl_customerlogin SET fname = v_name, gender = v_gender, username = v_username WHERE clid = v_clid AND did = v_did;
  END IF;
  IF (v_imagename <> '') THEN
  UPDATE tbl_customerlogin SET imagename = v_imagename WHERE clid = v_clid AND did = v_did;
  END IF;
END;
$$;


--
-- Name: usp_updateprofile_mobile_merchant(bigint, character varying, integer, character varying, character varying, character varying, text); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_updateprofile_mobile_merchant(v_plid bigint DEFAULT 0, v_name character varying DEFAULT ''::character varying, v_gender integer DEFAULT 0, v_mobile character varying DEFAULT ''::character varying, v_emailid character varying DEFAULT ''::character varying, INOUT v_strresult character varying DEFAULT ''::character varying, v_imagename text DEFAULT ''::text) RETURNS character varying
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_emailcount int;
  v_pvsemailid varchar(50);
BEGIN
  v_emailcount := 0;
  v_pvsemailid := '';
  v_strresult := 'SUCCESS';
  SELECT COALESCE(COUNT(1), 0) INTO v_emailcount FROM portal_login WHERE emailid = v_emailid AND plid <> v_plid;
  SELECT COALESCE(emailid, '') INTO v_pvsemailid FROM portal_login WHERE plid = v_plid;
  UPDATE portal_login SET fname = v_name, gender = v_gender WHERE plid = v_plid;
  IF (v_emailcount = 0) THEN
  UPDATE portal_login SET emailid = v_emailid WHERE plid = v_plid;
  END IF;
  IF (v_pvsemailid = '') THEN
  UPDATE portal_login SET emailid = v_emailid WHERE plid = v_plid;
  END IF;
  IF (v_emailcount > 0) THEN
  v_strresult := 'EmailID already Exists !';
  END IF;
END;
$$;


