--
-- Name: usp_updatesingleproduct(integer, bigint, integer, numeric, numeric, numeric, integer, numeric, numeric, numeric, numeric, numeric, character varying, character varying, text, character varying, character varying, character varying, character varying, character varying, character varying, character varying, character varying, character varying, character varying, character varying, character varying, text, text, text, text); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_updatesingleproduct(v_mode integer DEFAULT 1, v_sprid bigint DEFAULT 0, v_isverified integer DEFAULT 0, v_sellmrp numeric DEFAULT 0, v_discount numeric DEFAULT 0, v_dap numeric DEFAULT 0, v_stockin integer DEFAULT 0, v_length numeric DEFAULT 0, v_breadth numeric DEFAULT 0, v_weight numeric DEFAULT 0, v_height numeric DEFAULT 0, v_shippingcharges numeric DEFAULT 0, v_shortdesc character varying DEFAULT ''::character varying, v_keyfeatures character varying DEFAULT ''::character varying, v_fulldesc text DEFAULT ''::text, v_strresult character varying DEFAULT ''::character varying, v_image character varying DEFAULT ''::character varying, v_manufacturingdetail character varying DEFAULT ''::character varying, v_importerdetail character varying DEFAULT ''::character varying, v_packerdetail character varying DEFAULT ''::character varying, v_gst character varying DEFAULT ''::character varying, v_procurementtype character varying DEFAULT ''::character varying, v_fullfilmentseller character varying DEFAULT ''::character varying, v_procurementsla character varying DEFAULT ''::character varying, v_hsn character varying DEFAULT ''::character varying, v_luxurycess character varying DEFAULT ''::character varying, v_countryorigin character varying DEFAULT ''::character varying, v_specification text DEFAULT ''::text, v_prodimages text DEFAULT ''::text, v_allattributes text DEFAULT ''::text, v_produnit text DEFAULT ''::text) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_mprid BIGINT;
  v_qccounttemp INT;
  v_catid INT;
  v_subcatid INT;
  v_count1 INT;
  v_count2 INT;
  v_value VARCHAR(200);
  v_title VARCHAR(100);
  v_itemval VARCHAR(100);
  v_maincatid INT;
  v_awk INT;
BEGIN
  -- BEGIN TRAN (removed)
  IF (v_mode = 1) THEN
  v_catid := 0;
  v_subcatid := 0;
  SELECT mprid INTO v_mprid FROM ims_subproduct_temp WHERE sprid = v_sprid;
  SELECT qc_count INTO v_qccounttemp FROM ims_subproduct_temp WHERE sprid = v_sprid;
  UPDATE ims_masterproduct_temp SET shotdescription = v_shortdesc, fulldescription = v_fulldesc, keyfeatures = v_keyfeatures, modifydate = CURRENT_TIMESTAMP, v_catid = catid, v_subcatid = subcategoryid WHERE mprid = v_mprid;
  UPDATE ims_subproduct_temp SET discountpercentage = v_discount, dap = v_dap, modifydate = CURRENT_TIMESTAMP, weight_kg = v_weight, length_cms = v_length, breadth_cms = v_breadth, height_cms = v_height, shippingcharges = v_shippingcharges, stockin = v_stockin, stocknet = v_stockin, sellmrp = v_sellmrp, procurementsla = v_procurementsla, manufacturerdetails = v_manufacturingdetail, luxurycess = v_luxurycess, hsn = v_hsn, procurementtype = v_procurementtype, fullfilmentby = v_fullfilmentseller, importerdetails = v_importerdetail, packerdetails = v_packerdetail, countryorigin = v_countryorigin, isverified = 0, ismerchantstatus = 4, qc_count = v_qccounttemp + 1, specification = v_specification, productimages = v_prodimages, unit = v_produnit WHERE sprid = v_sprid;
  v_maincatid := 0;
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp (ROWNO INT GENERATED BY DEFAULT AS IDENTITY,VALUE VARCHAR(200)) ON COMMIT DROP;
  INSERT INTO tmp_temp SELECT value FROM dbo.SPLITSTRINGBYCUSTOMSYMBOL1(v_allattributes, '^') WHERE COALESCE(value, '') <> '';
  v_count1 := 1;
  SELECT COUNT(1) INTO v_count2 FROM tmp_temp;
  WHILE (v_count1 <= v_count2) LOOP
  SELECT value INTO v_value FROM tmp_temp WHERE rowno = v_count1;
  v_title := SUBSTRING(v_value FROM 1 FOR POSITION('~' IN v_value) - 1);
  v_itemval := SUBSTRING(v_value FROM POSITION('~' IN v_value) + 1 FOR LENGTH(CAST(v_value AS TEXT)));
  IF (v_value <> 'NO') THEN
  v_awk := 0;
  END IF;
  SELECT maincatid INTO v_maincatid FROM dbo.tbl_category WHERE catid = v_catid;
  SELECT maincatid, catid INTO v_maincatid, v_catid FROM dbo.tbl_sub_category WHERE subcatid = v_subcatid;
  IF (COALESCE(v_subcatid, 0) <> 0) THEN
  SELECT awct_id INTO v_awk FROM tbl_attributes_with_category WHERE att_name = v_title AND (sub_cat_id = COALESCE(v_subcatid, 0) OR cat_id = COALESCE(v_catid, 0) OR main_cat_id = COALESCE(v_maincatid, 0));
  ELSE
  IF (COALESCE(v_catid, 0) <> 0) THEN
  SELECT awct_id INTO v_awk FROM tbl_attributes_with_category WHERE att_name = v_title AND sub_cat_id = 0 AND (cat_id = COALESCE(v_catid, 0) OR main_cat_id = COALESCE(v_maincatid, 0));
  SELECT awct_id INTO v_awk FROM tbl_attributes_with_category WHERE att_name = v_title AND sub_cat_id = 0 AND (cat_id = COALESCE(v_catid, 0) AND main_cat_id = COALESCE(v_maincatid, 0));
  ELSE
  IF (COALESCE(v_maincatid, 0) <> 0) THEN
  SELECT awct_id INTO v_awk FROM tbl_attributes_with_category WHERE att_name = v_title AND sub_cat_id = 0 AND cat_id = 0 OR main_cat_id = COALESCE(v_maincatid, 0);
  END IF;
  END IF;
  END IF;
  IF (v_itemval <> '' AND v_title <> '') THEN
  IF EXISTS(SELECT 1 FROM ims_masterproductattribute_temp WHERE sprid = v_sprid AND title = v_title AND isactive = 1) THEN
  UPDATE ims_masterproductattribute_temp SET value = v_itemval WHERE sprid = v_sprid AND title = v_title AND isactive = 1;
  ELSE
  INSERT INTO ims_masterproductattribute_temp (sprid, title, value, showongrid, position, isactive, catid, awcid, subcatid) VALUES (v_sprid, v_title, v_itemval, 1, 1, 1, v_catid, v_awk, v_subcatid);
  END IF;
  END IF;
  v_count1 := v_count1 + 1;
  END LOOP;
  DROP TABLE IF EXISTS tmp_temp;
  v_strresult := 'UPDATED SUCCESSFULLY';
  END IF;
  IF (v_mode = 2) THEN
  SELECT mprid INTO v_mprid FROM ims_subproduct WHERE sprid = v_sprid;
  RETURN QUERY SELECT sm.subprcode, pm.shotdescription, pm.fulldescription, pm.keyfeatures, sm.discountpercentage, sm.dap, sm.weight_kg, sm.length_cms, sm.breadth_cms, sm.height_cms, sm.shippingcharges, sm.stockin, sm.sellmrp, sm.isverified, pm.producttitle, sm.procurementsla, sm.manufacturerdetails, sm.luxurycess, sm.hsn, sm.procurementtype, sm.fullfilmentby, sm.importerdetails, sm.packerdetails, sm.countryorigin FROM ims_subproduct AS sm INNER JOIN ims_masterproduct AS pm ON sm.mprid = pm.mprid WHERE sprid = v_sprid;
  END IF;
  IF (0 <> 0) THEN
  v_strresult := 'SOME ERROR OCCOURED !';
  -- ROLLBACK (removed)
  RETURN;
  END IF;
  -- COMMIT (removed)
END;
$$;


--
-- Name: usp_updatesponsor(integer, integer, character varying, character varying, character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_updatesponsor(v_pltid integer DEFAULT 0, INOUT v_intresult integer DEFAULT NULL::integer, INOUT v_loginidout character varying DEFAULT NULL::character varying, INOUT v_passwordout character varying DEFAULT NULL::character varying, INOUT v_sponsornameout character varying DEFAULT NULL::character varying) RETURNS record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_loginid varchar(100);
  v_password varchar(100);
  v_intro_refid bigint;
  v_username varchar(100);
  v_currencysymbol varchar(100);
  v_cid int;
  v_ipaddress varchar(100);
  v_title varchar(100);
  v_sp_firtname varchar(100);
  v_sp_lastname varchar(100);
  v_sp_url varchar(100);
  v_maxplid bigint;
BEGIN
  v_intresult := 0;
  SELECT loginid, password, intro_refid, username, currencysymbol, cid, ipaddress, title, sp_firstname, sp_lastname, sp_url INTO v_loginid, v_password, v_intro_refid, v_username, v_currencysymbol, v_cid, v_ipaddress, v_title, v_sp_firtname, v_sp_lastname, v_sp_url FROM portal_login_temp WHERE pltid = v_pltid AND active = 0;
  IF NOT EXISTS(SELECT 1 FROM portal_login WHERE RTRIM(LTRIM(loginid)) = RTRIM(LTRIM(v_loginid))) AND NOT EXISTS(SELECT 1 FROM portal_login_temp WHERE RTRIM(LTRIM(loginid)) = RTRIM(LTRIM(v_loginid))) THEN
  v_intresult := 1;
  INSERT INTO portal_login (loginid, password, active, intro_refid, doc, currencysymbol, cid, title, username, ipaddress, fname, lname, cper_emailid) VALUES (v_loginid, v_password, 1, v_intro_refid, GETUTCDATE(), v_currencysymbol, v_cid, v_title, v_username, v_ipaddress, v_sp_firtname, v_sp_lastname, v_loginid);
  v_maxplid := IDENT_CURRENT('portal_login');
  INSERT INTO sponsor_master_detail (plid, cid, url, doc) VALUES (v_maxplid, v_cid, v_sp_url, GETUTCDATE());
  UPDATE portal_login_temp SET active = 1, doc = GETUTCDATE() WHERE pltid = v_pltid;
  v_loginidout := v_loginid;
  v_passwordout := v_password;
  v_sponsornameout := v_sp_firtname || ' ' || v_sp_lastname;
  ELSE
  v_intresult := 2;
  END IF;
END;
$$;


--
-- Name: usp_updatestatus(integer, integer, character varying, character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_updatestatus(v_agid integer DEFAULT 1, v_mode integer DEFAULT 3, INOUT v_strresult character varying DEFAULT ''::character varying, v_remark character varying DEFAULT 'dfgsdfg'::character varying) RETURNS character varying
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF (v_mode = 2) THEN
  UPDATE tbl_agreement_details SET status = 1, remark = v_remark WHERE agid = v_agid;
  v_strresult := 'Agreement Verifyed successfully';
  END IF;
  IF (v_mode = 3) THEN
  UPDATE tbl_agreement_details SET status = 2, remark = v_remark WHERE agid = v_agid;
  v_strresult := 'Agreement Rejected successfully';
  END IF;
END;
$$;


