CREATE FUNCTION dbo.usp_updatestatusoflisting(v_pmid text DEFAULT ''::text, INOUT v_result integer DEFAULT NULL::integer) RETURNS integer
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_res int;
BEGIN
  SELECT active INTO v_res FROM portal_master WHERE pmid = v_pmid;
  IF (v_res = 0) THEN
  UPDATE portal_master SET active = 1 WHERE pmid = v_pmid;
  v_result := 2;
  RAISE NOTICE '%', v_result;
  END IF;
  IF (v_res = 1) THEN
  UPDATE portal_master SET active = 0 WHERE pmid = v_pmid;
  v_result := 1;
  RAISE NOTICE '%', v_result;
  END IF;
END;
$$;


