--
-- Name: usp_updatevisitor(integer, integer, bigint, character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_updatevisitor(v_plid integer DEFAULT 5129, v_intresult integer DEFAULT 0, v_maxplid bigint DEFAULT 0, v_emailid character varying DEFAULT ''::character varying) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_loginid VARCHAR(100);
  v_password VARCHAR(100);
  v_currencysymbol varchar(50);
  v_currency varchar(50);
  v_spounsertype int;
  v_cid INT;
  v_plidref VARCHAR(100);
  v_username VARCHAR(100);
  v_ipaddress VARCHAR(100);
  v_intromemid VARCHAR(500);
  v_placementmemid VARCHAR(50);
  v_placementregnoside smallint;
  v_fname VARCHAR(100);
  v_mname VARCHAR(100);
  v_lname VARCHAR(100);
  v_gender smallint;
  v_dob VARCHAR(50);
  v_email VARCHAR(100);
  v_mobile VARCHAR(20);
  v_sid INT;
  v_statename VARCHAR(250);
  v_ctid INT;
  v_cityname VARCHAR(200);
  v_address VARCHAR(5000);
  v_pincode VARCHAR(20);
  v_panno VARCHAR(100);
  v_trpassword VARCHAR(100);
  v_ipadd VARCHAR(100);
  v_epinnumber VARCHAR(100);
  v_nomineename VARCHAR(100);
  v_nomineerelation VARCHAR(100);
  v_sessionloginid VARCHAR(50);
  v_kitid Int;
  v_strresult VARCHAR(200);
  v_application_formno varchar(500);
  v_referalcode varchar(10);
  v_introrefid Int;
  v_sponsorids varchar(500);
  v_placementids varchar(500);
  v_side Int;
  v_title varchar(500);
  v_desigantion varchar(500);
  v_imagename varchar(500);
  v_userid varchar(500);
  v_atc_walletaddress varchar(500);
  v_atcuserid varchar(500);
  v_sourceid int;
  v_did int;
  v_merchantrelatedto Int;
  v_affiliateuserid Varchar(100);
  v_outputresult INT;
BEGIN
  BEGIN
  -- SET option (removed)
  -- SET option (removed)
  -- BEGIN TRAN (removed)
  IF (v_emailid <> '') THEN
  SELECT pltid INTO v_plid FROM portal_login_temp WHERE emailid = v_emailid LIMIT 1;
  END IF;
  v_spounsertype := 0;
  v_intromemid := '';
  v_placementmemid := '';
  v_placementregnoside := 0;
  v_fname := '';
  v_mname := '';
  v_lname := '';
  v_gender := 0;
  v_dob := '';
  v_email := '';
  v_mobile := '';
  v_sid := 0;
  v_statename := '';
  v_ctid := 0;
  v_cityname := '';
  v_address := '';
  v_pincode := '';
  v_panno := '';
  v_trpassword := '';
  v_ipadd := '';
  v_epinnumber := '';
  v_nomineename := '';
  v_nomineerelation := '';
  v_sessionloginid := '';
  v_kitid := 0;
  v_strresult := '';
  v_application_formno := '';
  v_referalcode := '';
  v_introrefid := 0;
  v_sponsorids := '';
  v_placementids := '';
  v_side := 0;
  v_title := '';
  v_desigantion := '';
  v_imagename := '';
  v_userid := '';
  v_atc_walletaddress := '';
  v_atcuserid := '';
  v_sourceid := 0;
  v_did := 0;
  v_merchantrelatedto := 0;
  v_affiliateuserid := '';
  v_intresult := 0;
  IF EXISTS(SELECT 1 FROM portal_login_temp WHERE pltid = v_plid AND active = 0) THEN
  SELECT loginid, password, password, intro_refid, username, currencysymbol, cid, ipaddress, COALESCE(sp_firstname, ''), COALESCE(sp_lastname, ''), phone, emailid, COALESCE(refral_id, ''), sponserid, placementid, side, title, designation, imagename, COALESCE(spounsertype, 0), userid, sid, ctid, COALESCE(sourceid, 0), did, merchantrelatedto, affiliateuserid INTO v_loginid, v_password, v_trpassword, v_plidref, v_username, v_currencysymbol, v_cid, v_ipaddress, v_fname, v_lname, v_mobile, v_email, v_referalcode, v_sponsorids, v_placementids, v_side, v_title, v_desigantion, v_imagename, v_spounsertype, v_userid, v_sid, v_ctid, v_sourceid, v_did, v_merchantrelatedto, v_affiliateuserid FROM portal_login_temp WHERE pltid = v_plid;
  SELECT currencycode INTO v_currency FROM country WHERE cid = v_cid;
  IF NOT EXISTS(SELECT plid FROM portal_login WHERE username = v_username AND loginid = v_loginid) THEN
  SELECT plid INTO v_introrefid FROM portal_login WHERE username = v_sponsorids;
