BEGIN
  -- BEGIN TRAN (removed)
  OPEN cr_opentime;
  FETCH cr_opentime INTO v_opentime, v_closetime,v_openeveningtime,v_closeeveningtime,v_id;
  WHILE (found) LOOP
  IF (ISNUMERIC(v_opentime) = 1) THEN
  IF (v_opentime <= 12) THEN
  UPDATE tblopeningdate SET openingtime = CAST(openingtime AS VARCHAR(10)) || ':00 AM' WHERE id = v_id;
  END IF;
  IF (v_opentime > 12) THEN
  UPDATE tblopeningdate SET openingtime = CAST((openingtime - 12) AS VARCHAR(20)) || ':00 PM' WHERE id = v_id;
  END IF;
  END IF;
  IF (ISNUMERIC(v_closetime) = 1) THEN
  IF (v_closetime <= 12) THEN
  UPDATE tblopeningdate SET closingtime = CAST(closingtime AS VARCHAR(10)) || ':00 AM' WHERE id = v_id;
  END IF;
  IF (v_closetime > 12) THEN
  UPDATE tblopeningdate SET closingtime = CAST((closingtime - 12) AS VARCHAR(20)) || ':00 PM' WHERE id = v_id;
  END IF;
  END IF;
  IF (ISNUMERIC(v_openeveningtime) = 1) THEN
  IF (v_openeveningtime <= 12) THEN
  UPDATE tblopeningdate SET openingtimeevening = CAST(openingtimeevening AS VARCHAR(10)) || ':00 AM' WHERE id = v_id;
  END IF;
  IF (v_openeveningtime > 12) THEN
  UPDATE tblopeningdate SET openingtimeevening = CAST((openingtimeevening - 12) AS VARCHAR(20)) || ':00 PM' WHERE id = v_id;
  END IF;
  END IF;
  IF (ISNUMERIC(v_closeeveningtime) = 1) THEN
  IF (v_closeeveningtime <= 12) THEN
  UPDATE tblopeningdate SET closingtimeevening = CAST(closingtimeevening AS VARCHAR(10)) || ':00 AM' WHERE id = v_id;
  END IF;
  IF (v_closeeveningtime > 12) THEN
  UPDATE tblopeningdate SET closingtimeevening = CAST((closingtimeevening - 12) AS VARCHAR(20)) || ':00 PM' WHERE id = v_id;
  END IF;
  END IF;
  IF (0 < 0) THEN
  CLOSE cr_opentime;
  -- DEALLOCATE (removed)
  -- ROLLBACK (removed)
  -- COMMIT (removed)
  END IF;
  FETCH cr_opentime INTO v_opentime, v_closetime,v_openeveningtime,v_closeeveningtime,v_id;
  END LOOP;
  CLOSE cr_opentime;
  -- DEALLOCATE (removed)
  -- COMMIT (removed)
END;
$$;


--
-- Name: usp_updating_keyword_and_category_price_individual(character varying, integer, bigint, character varying, character varying, bigint, character varying, character varying, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_updating_keyword_and_category_price_individual(v_type character varying DEFAULT ''::character varying, v_cid integer DEFAULT 0, v_kmid bigint DEFAULT 0, v_keywordprice character varying DEFAULT ''::character varying, v_minkeywordprice character varying DEFAULT ''::character varying, v_catid bigint DEFAULT 0, v_catprice character varying DEFAULT ''::character varying, v_mincatprice character varying DEFAULT ''::character varying, INOUT v_intresult integer DEFAULT NULL::integer) RETURNS integer
    LANGUAGE plpgsql
    AS $$
BEGIN
  -- BEGIN TRAN (removed)
  IF (v_type = 'keyword') THEN
  IF NOT EXISTS(SELECT * FROM tbl_update_keyword_and_category_price_cwise_packagetype WHERE cid = v_cid AND kmid = v_kmid) THEN
  INSERT INTO tbl_update_keyword_and_category_price_cwise_packagetype (type, cid, kmid, keywordprice, minkeywordprice) VALUES (v_type, v_cid, CAST(v_kmid AS BIGINT), CAST(v_keywordprice AS MONEY), CAST(v_minkeywordprice AS MONEY));
  ELSE
  UPDATE tbl_update_keyword_and_category_price_cwise_packagetype SET type = v_type, keywordprice = CAST(v_keywordprice AS MONEY), minkeywordprice = CAST(v_minkeywordprice AS MONEY) WHERE cid = v_cid AND kmid = v_kmid;
  END IF;
  END IF;
  IF (v_type = 'category') THEN
  IF NOT EXISTS(SELECT * FROM tbl_update_keyword_and_category_price_cwise_packagetype WHERE cid = v_cid AND catid = v_catid) THEN
  INSERT INTO tbl_update_keyword_and_category_price_cwise_packagetype (type, cid, catid, catprice, mincatprice) VALUES (v_type, v_cid, CAST(v_catid AS BIGINT), CAST(v_catprice AS MONEY), CAST(v_mincatprice AS MONEY));
  ELSE
  UPDATE tbl_update_keyword_and_category_price_cwise_packagetype SET type = v_type, catprice = CAST(v_catprice AS MONEY), mincatprice = CAST(v_mincatprice AS MONEY) WHERE cid = v_cid AND catid = v_catid;
  END IF;
  END IF;
  IF (0 <> 0) THEN
  v_intresult := 0;
  -- ROLLBACK (removed)
  RETURN;
  END IF;
  v_intresult := 1;
  -- COMMIT (removed)
END;
$$;


--
-- Name: usp_updatinglatitude_formated_add(bigint, character varying, character varying, text, text); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_updatinglatitude_formated_add(v_pmid bigint DEFAULT 0, v_latitude character varying DEFAULT ''::character varying, v_longitude character varying DEFAULT ''::character varying, v_formatedadd text DEFAULT ''::text, INOUT v_strresult text DEFAULT NULL::text) RETURNS text
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_description text;
BEGIN
  -- BEGIN TRAN (removed)
  v_strresult := 'fffffff';
  SELECT companyname INTO v_description FROM portal_master WHERE pmid = v_pmid;
  IF NOT EXISTS(SELECT pmid FROM locations WHERE pmid = v_pmid) THEN
  INSERT INTO locations (pmid, areaname, latitude, longitude, active, discription) VALUES (v_pmid, v_formatedadd, v_latitude, v_longitude, 1, v_description || ' , ' || v_formatedadd);
  v_strresult := 'Business location inserted sucessfully';
  ELSE
  UPDATE locations SET latitude = v_latitude, longitude = v_longitude, areaname = v_formatedadd, discription = v_description || ' , ' || v_formatedadd WHERE pmid = v_pmid;
  v_strresult := 'Business location updated sucessfully';
  END IF;
  IF (0 <> 0) THEN
  -- ROLLBACK (removed)
  v_strresult := 'There is error while updating the new location';
  RETURN;
  END IF;
  -- COMMIT (removed)
END;
$$;


