--
-- Name: usp_upload_weekly_excel_report(character varying, character varying, character varying, numeric, timestamp without time zone, character varying, numeric, numeric, numeric, numeric); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_upload_weekly_excel_report(v_requestid character varying DEFAULT ''::character varying, v_docketno character varying DEFAULT ''::character varying, v_weight character varying DEFAULT ''::character varying, v_price numeric DEFAULT 0, v_date timestamp without time zone DEFAULT NULL::timestamp without time zone, INOUT v_strresult character varying DEFAULT 0, v_deliverycharge numeric DEFAULT 0, v_tax_charge numeric DEFAULT 0, v_total_amount numeric DEFAULT 0, v_fueltax numeric DEFAULT 0) RETURNS character varying
    LANGUAGE plpgsql
    AS $$
BEGIN
  -- BEGIN TRAN (removed)
  IF (v_requestid = '') THEN
  v_strresult := 'ERROR^REQUESTID IS NOT DEFINED';
  -- COMMIT (removed)
  RETURN;
  END IF;
  IF (v_docketno = '') THEN
  v_strresult := 'ERROR^DOCKETNO IS NOT DEFINED';
  -- COMMIT (removed)
  RETURN;
  END IF;
  IF NOT EXISTS(SELECT 1 FROM tbl_courierweeklyreports WHERE docketno = v_docketno AND active = 1) THEN
  INSERT INTO tbl_courierweeklyreports (docketno, weight, pickup_charges, active, createddate, requestid, deliverycharhes, taxcharges, total_amount, date, fueltax) VALUES (v_docketno, v_weight, v_price, 1, TO_DATE(v_date, 'DD/MM/YYYY'), v_requestid, v_deliverycharge, v_tax_charge, (v_price + v_deliverycharge + v_tax_charge + v_fueltax), dbo.FUN_GETCURRENTDATE(), v_fueltax);
  v_strresult := 'OK^UPDATE STATUS';
  END IF;
  IF (0 <> 0) THEN
  -- ROLLBACK (removed)
  v_strresult := 'ERROR^' || 0;
  RETURN;
  END IF;
  -- COMMIT (removed)
END;
$$;


