--
-- Name: usp_uploadbulkdata(text, text, xml, text, integer, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_uploadbulkdata(v_newgroupname text DEFAULT ''::text, v_groupname text DEFAULT ''::text, v_addressxmllist xml DEFAULT NULL::xml, v_emailid text DEFAULT ''::text, INOUT v_intresult integer DEFAULT 0, v_mode integer DEFAULT 1) RETURNS integer
    LANGUAGE plpgsql
    AS $$
BEGIN
  BEGIN
  IF (v_mode = 1) THEN
  DROP TABLE IF EXISTS tmp_tmp;
  CREATE TEMP TABLE tmp_tmp (RowNumber BIGINT GENERATED BY DEFAULT AS IDENTITY,GroupName text,EmailId text) ON COMMIT DROP;
  INSERT INTO tmp_tmp (groupname, emailid) SELECT (CASE WHEN v_groupname = '' THEN (CASE WHEN v_newgroupname = '' THEN 'Default' ELSE v_newgroupname END) ELSE v_groupname END), t.c.value('./F2[1]', 'text') FROM v_addressxmllist.NODES('/NewDataSet/Table') AS t(c);
  INSERT INTO tbl_tbladminbulkuploadedemailmaster (groupname, emailid, isactive, isdeleted, uploadeddate) SELECT groupname, emailid, 1, 0, CURRENT_TIMESTAMP FROM tmp_tmp;
  ELSE
  IF (v_mode = 2) THEN
  INSERT INTO tbl_tbladminbulkuploadedemailmaster (groupname, emailid, isactive, isdeleted, uploadeddate) SELECT (CASE WHEN v_groupname = '' THEN (CASE WHEN v_newgroupname = '' THEN 'Default' ELSE v_newgroupname END) ELSE v_groupname END), v_emailid, 1, 0, CURRENT_TIMESTAMP;
  END IF;
  END IF;
  v_intresult := 1;
  EXCEPTION WHEN OTHERS THEN
  v_intresult := 0;
  END;
END;
$$;


--
-- Name: usp_uploaded_bank_excel_history(integer, integer, integer, character varying, character varying, character varying, character varying, integer, character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_uploaded_bank_excel_history(v_mode integer DEFAULT 0, v_startrowindex integer DEFAULT 1, v_maxrows integer DEFAULT 100, v_searchfield character varying DEFAULT ''::character varying, v_searchvalue character varying DEFAULT ''::character varying, v_fromdate character varying DEFAULT ''::character varying, v_todate character varying DEFAULT ''::character varying, v_totalcount integer DEFAULT 0, v_requestid character varying DEFAULT ''::character varying) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_minindex INT;
  v_maxindex INT;
  v_query text;
BEGIN
  v_minindex := (v_startrowindex - 1) * v_maxrows + 1;
  v_maxindex := v_startrowindex * v_maxrows;
  IF (v_mode = 0) THEN
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp (ROWNUMBER BIGINT GENERATED BY DEFAULT AS IDENTITY, 
	CHID BIGINT,       
	FILENAME varchar(100),         
	DATE timestamp,	
	CLUBGROUP varchar(100),
	BANKNAME varchar(100),
	TOTALREQUEST INT,	
	TOTALAMOUNT decimal(18,2),	
	TOTAL_TANSACTION decimal(18,2),			
    PROCESSDATE varchar(100),	
	PROCESSBY varchar(100),			
    PROCESSSTATUS varchar(100),
	PROCESSIPADDRESS varchar(100),
	ALLWDID varchar(100)) ON COMMIT DROP;
  v_query := 'INSERT INTO #TEMP SELECT CWS.CHID,CWS.FILENAME,Convert(DATE, CWS.DATE,106) as DATE,CWS.CLUBGROUP,CWS.BANKNAME,CWS.TOTALREQUEST,
CWS.TOTALAMOUNT,CWS.TOTAL_TANSACTION,Convert(varchar,CWS.PROCESSDATE,106),CWS.PROCESSBY,CWS.PROCESSSTATUS,CWS.PROCESSIPADDRESS,CWS.ALLWDID
FROM TBL_CLUBHISTORY CWS   WHERE 1=1 ';
  IF ((v_fromdate <> '') AND (v_todate = '')) THEN
  v_query := v_query || ' AND CONVERT(DATE, CWS.DATE, 105) BETWEEN  CONVERT(DATE, ''' || v_fromdate || ''', 105) AND  CONVERT(DATE, DBO.FUN_GETCURRENTDATE(), 105)';
  END IF;
  IF ((v_fromdate = '') AND (v_todate <> '')) THEN
  v_query := v_query || 'AND CONVERT(DATE, CWS.DATE, 105) BETWEEN  CONVERT(DATE, ''' || v_todate || ''', 105) AND  CONVERT(DATE, DBO.FUN_GETCURRENTDATE(), 105)';
  END IF;
  IF ((v_fromdate <> '') AND (v_todate <> '')) THEN
  v_query := v_query || 'AND CONVERT(DATE, CWS.DATE, 105) BETWEEN CONVERT(DATE, ''' || v_fromdate || ''', 105) AND  CONVERT(DATE, ''' || v_todate || ''', 105)';
  END IF;
  EXECUTE v_query;
  RETURN QUERY SELECT * FROM tmp_temp WHERE rownumber BETWEEN v_minindex AND v_maxindex;
  SELECT COUNT(rownumber) INTO v_totalcount FROM tmp_temp;
  DROP TABLE IF EXISTS tmp_temp;
  -- SET option (removed)
  END IF;
  IF (v_mode = 1) THEN
  DROP TABLE IF EXISTS tmp_temp1;
  CREATE TEMP TABLE tmp_temp1 (ROWNUMBER INT GENERATED BY DEFAULT AS IDENTITY,        
	TUBPEID INT,         
	ACCOUNTHOLDERNAME VARCHAR(500),	
	BANKNAME VARCHAR(500),	
	BRANCHNAME VARCHAR(500),
	IFSCCODE VARCHAR(500),
	ACCOUNTNO VARCHAR(500),
	AMOUNT DECIMAL(18,2),
	TRANSACTIONID VARCHAR(200),
	TRANSACTIONDATE timestamp,
    STATUS INT,				
	REQUESTID VARCHAR(50)) ON COMMIT DROP;
  v_query := 'INSERT INTO #TEMP1 SELECT TUBPEID,ISNULL(ACCOUNTHOLDERNAME,'''') AS ACCOUNTHOLDERNAME,ISNULL(BANKNAME,'''') AS BANKNAME,
  ISNULL(BRANCHNAME,'''') AS BRANCHNAME,ISNULL(IFSCCODE,'''') AS IFSCCODE,ISNULL(ACCOUNTNO,'''') AS ACCOUNTNO,ISNULL(AMOUNT,0) AS AMOUNT,
  ISNULL(TRANSACTIONID,'''') AS TRANSACTIONID,TRANSACTIONDATE,ISNULL(STATUS,0) AS STATUS,ISNULL(REQUESTID,'''') AS REQUESTID
	 FROM TBL_UPLOADED_BANK_PAYOUT_EXCEL CWS   WHERE 1=1 ';
  IF ((v_fromdate <> '') AND (v_todate = '')) THEN
  v_query := v_query || ' AND CONVERT(DATE, TRANSACTIONDATE, 105) BETWEEN  CONVERT(DATE, ''' || v_fromdate || ''', 105) AND  CONVERT(DATE, DBO.FUN_GETCURRENTDATE(), 105)';
  END IF;
  IF ((v_fromdate = '') AND (v_todate <> '')) THEN
  v_query := v_query || 'AND CONVERT(DATE, TRANSACTIONDATE, 105) BETWEEN  CONVERT(DATE, ''' || v_todate || ''', 105) AND  CONVERT(DATE, DBO.FUN_GETCURRENTDATE(), 105)';
  END IF;
  IF ((v_fromdate <> '') AND (v_todate <> '')) THEN
  v_query := v_query || 'AND CONVERT(DATE, TRANSACTIONDATE, 105) BETWEEN CONVERT(DATE, ''' || v_fromdate || ''', 105) AND  CONVERT(DATE, ''' || v_todate || ''', 105)';
  END IF;
  IF (v_searchfield <> '') THEN
  v_query := v_query || ' AND DOCKETNO= ''' || v_searchfield || ''' ';
  END IF;
  IF (v_requestid <> '') THEN
  v_query := v_query || ' AND REQUESTID= ''' || v_requestid || ''' ';
  END IF;
  EXECUTE v_query;
  RETURN QUERY SELECT * FROM tmp_temp1 WHERE rownumber BETWEEN v_minindex AND v_maxindex;
  SELECT COUNT(rownumber) INTO v_totalcount FROM tmp_temp1;
  DROP TABLE IF EXISTS tmp_temp1;
  -- SET option (removed)
  END IF;
END;
$$;


