  v_query := v_query || 'AND CONVERT(DATE, CWS.DATE, 105) BETWEEN CONVERT(DATE, ''' || v_fromdate || ''', 105) AND  CONVERT(DATE, ''' || v_todate || ''', 105)';
  END IF;
  EXECUTE v_query;
  RETURN QUERY SELECT * FROM tmp_temp WHERE rownumber BETWEEN v_minindex AND v_maxindex;
  SELECT COUNT(rownumber) INTO v_totalcount FROM tmp_temp;
  DROP TABLE IF EXISTS tmp_temp;
  -- SET option (removed)
  END IF;
END;
$$;


--
-- Name: usp_uploaded_excel_history(integer, integer, character varying, character varying, character varying, character varying, integer, character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_uploaded_excel_history(v_startrowindex integer DEFAULT 1, v_maxrows integer DEFAULT 100, v_orderid character varying DEFAULT ''::character varying, v_docketno character varying DEFAULT ''::character varying, v_fromdate character varying DEFAULT ''::character varying, v_todate character varying DEFAULT ''::character varying, v_totalcount integer DEFAULT 0, v_invoiceno character varying DEFAULT ''::character varying) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_minindex INT;
  v_maxindex INT;
  v_query text;
BEGIN
  v_minindex := (v_startrowindex - 1) * v_maxrows + 1;
  v_maxindex := v_startrowindex * v_maxrows;
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp (ROWNUMBER INT GENERATED BY DEFAULT AS IDENTITY, 
	ORDERID VARCHAR(100),  
	ProductName text, 
	CUSTOMER_NAME VARCHAR(500), 
    Shipping_Address1 VARCHAR(1000),  
	Pincode VARCHAR(50),     
	Mobileno  VARCHAR(50),        
	COLLECTABLE_AMOUNT decimal(18,2),
	TypeOfService VARCHAR(100),	
	DTDCSTAUS VARCHAR(50),
	Docket_no VARCHAR(500), 	
	Credate_date timestamp) ON COMMIT DROP;
  v_query := 'INSERT INTO #TEMP select ORDERID,ProductName,CUSTOMER_NAME,Shipping_Address1,Pincode,Mobileno,COLLECTABLE_AMOUNT 
 ,TypeOfService,DTDCSTAUS,Docket_no,Credate_date from TBL_COURIER_STATUSEXCELDATA WHERE 1=1 ';
  IF ((v_fromdate <> '') AND (v_todate = '')) THEN
  v_query := v_query || ' AND CONVERT(DATE, Credate_date, 105) BETWEEN  CONVERT(DATE, ''' || v_fromdate || ''', 105) AND  CONVERT(DATE, DBO.FUN_GETCURRENTDATE(), 105)';
  END IF;
  IF ((v_fromdate = '') AND (v_todate <> '')) THEN
  v_query := v_query || 'AND CONVERT(DATE, Credate_date, 105) BETWEEN  CONVERT(DATE, ''' || v_todate || ''', 105) AND  CONVERT(DATE, DBO.FUN_GETCURRENTDATE(), 105)';
  END IF;
  IF ((v_fromdate <> '') AND (v_todate <> '')) THEN
  v_query := v_query || 'AND CONVERT(DATE, Credate_date, 105) BETWEEN CONVERT(DATE, ''' || v_fromdate || ''', 105) AND  CONVERT(DATE, ''' || v_todate || ''', 105)';
  END IF;
  IF (v_orderid <> '') THEN
  v_query := v_query || ' AND ORDERID= ''' || v_orderid || ''' ';
  END IF;
  IF (v_docketno <> '') THEN
  v_query := v_query || ' AND Docket_no= ''' || v_docketno || ''' ';
  END IF;
  IF (v_invoiceno <> '') THEN
  v_query := v_query || ' AND INVOICENO= ''' || v_invoiceno || ''' ';
  END IF;
  EXECUTE v_query;
  RETURN QUERY SELECT * FROM tmp_temp WHERE rownumber BETWEEN v_minindex AND v_maxindex;
  SELECT COUNT(rownumber) INTO v_totalcount FROM tmp_temp;
  DROP TABLE IF EXISTS tmp_temp;
  -- SET option (removed)
END;
$$;


