--
-- Name: usp_uploadzone1(text, character varying, text, text, integer, character varying, character varying, character varying, character varying, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_uploadzone1(v_compnyimg text DEFAULT ''::text, v_url character varying DEFAULT ''::character varying, v_pdfname text DEFAULT ''::text, v_imagename text DEFAULT ''::text, v_pmid integer DEFAULT 0, v_name character varying DEFAULT ''::character varying, v_contenttype character varying DEFAULT ''::character varying, v_data character varying DEFAULT ''::character varying, v_title character varying DEFAULT ''::character varying, INOUT v_intresult integer DEFAULT NULL::integer) RETURNS integer
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_scatid int;
  v_catid int;
  v_categoryname varchar(100);
  v_scategoryname varchar(100);
  v_alreadyimage varchar(100);
BEGIN
  v_intresult := 1;
  IF NOT EXISTS(SELECT pmid FROM pdfupload WHERE pmid = v_pmid) THEN
  INSERT INTO pdfupload (pmid, pdfname, title, active) VALUES (v_pmid, v_pdfname, v_title, 1);
  ELSE
  UPDATE pdfupload SET title = v_title WHERE pmid = v_pmid;
  IF (v_pdfname <> '') THEN
  UPDATE pdfupload SET pdfname = v_pdfname WHERE pmid = v_pmid;
  END IF;
  END IF;
  IF NOT EXISTS(SELECT pmid FROM videodata WHERE pmid = v_pmid) THEN
  INSERT INTO videodata (pmid, name, contenttype, data, status) VALUES (v_pmid, v_name, v_contenttype, v_data, 1);
  ELSE
  UPDATE videodata SET name = v_name, contenttype = v_contenttype, status = 1, data = v_data WHERE pmid = v_pmid;
  END IF;
  IF NOT EXISTS(SELECT pmid FROM portalmember_photogallery1 WHERE pmid = v_pmid) THEN
  INSERT INTO portalmember_photogallery1 (imagename, pmid, active) VALUES (v_imagename, v_pmid, 1);
  ELSE
  UPDATE portalmember_photogallery1 SET imagename = v_imagename, active = 1 WHERE pmid = v_pmid;
  END IF;
  IF (v_compnyimg <> '') THEN
  UPDATE portal_master_details SET companyimage = v_compnyimg WHERE pmid = v_pmid;
  END IF;
  IF (0 <> 0) THEN
  v_intresult := 0;
  RETURN;
  END IF;
END;
$$;


--
-- Name: usp_uploadzone_new(text, character varying, integer, character varying, character varying, character varying, character varying, text, text, character varying, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_uploadzone_new(v_imagename text DEFAULT ''::text, v_url character varying DEFAULT ''::character varying, v_pmid integer DEFAULT 0, v_name character varying DEFAULT ''::character varying, v_contenttype character varying DEFAULT ''::character varying, v_data character varying DEFAULT ''::character varying, v_title character varying DEFAULT ''::character varying, v_compnyimg text DEFAULT ''::text, v_pdfname text DEFAULT ''::text, v_intmode character varying DEFAULT 'ImageName'::character varying, INOUT v_intresult integer DEFAULT NULL::integer) RETURNS integer
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_scatid int;
  v_catid int;
  v_categoryname varchar(100);
  v_scategoryname varchar(100);
  v_alreadyimage varchar(100);
BEGIN
  -- BEGIN TRAN (removed)
  v_intresult := 1;
  IF (v_intmode = 'pdfname') THEN
  IF NOT EXISTS(SELECT pmid FROM pdfupload WHERE pmid = v_pmid) THEN
  INSERT INTO pdfupload (pmid, pdfname, title, active) VALUES (v_pmid, v_pdfname, v_title, 1);
  ELSE
  UPDATE pdfupload SET title = v_title WHERE pmid = v_pmid;
  IF (v_pdfname <> '') THEN
  UPDATE pdfupload SET pdfname = v_pdfname WHERE pmid = v_pmid;
  END IF;
  END IF;
  END IF;
  IF (v_intmode = 'VideoData') THEN
  IF NOT EXISTS(SELECT pmid FROM videodata WHERE pmid = v_pmid) THEN
  INSERT INTO videodata (pmid, name, contenttype, data, status) VALUES (v_pmid, v_name, v_contenttype, v_data, 1);
  ELSE
  UPDATE videodata SET name = v_name, contenttype = v_contenttype, status = 1, data = v_data WHERE pmid = v_pmid;
  END IF;
  END IF;
  IF (v_intmode = 'ImageName') THEN
  IF NOT EXISTS(SELECT pmid FROM portalmember_photogallery WHERE pmid = v_pmid) THEN
  RAISE NOTICE '%', 'Not Exist';
  IF (v_imagename <> '') THEN
  RAISE NOTICE '%', '@ImageName blank';
  INSERT INTO portalmember_photogallery (imagename, pmid, active) VALUES (v_imagename, v_pmid, 1);
  END IF;
  ELSE
  RAISE NOTICE '%', '@ImageName not blank';
  UPDATE portalmember_photogallery SET imagename = v_imagename, active = 1 WHERE pmid = v_pmid;
  END IF;
  END IF;
  IF (v_intmode = 'Logoes') THEN
  IF (v_compnyimg <> '') THEN
  UPDATE portal_master SET companyimage = v_compnyimg WHERE pmid = v_pmid;
  END IF;
  END IF;
  IF (0 <> 0) THEN
  -- ROLLBACK (removed)
  v_intresult := 0;
  RETURN;
  END IF;
  -- COMMIT (removed)
END;
$$;


--
-- Name: usp_urlavailability(character varying, character varying, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_urlavailability(v_destinationurl character varying, v_displayurl character varying, v_slid integer) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_expressiontosearch varchar(300);
BEGIN
  v_expressiontosearch := '';
  -- SET option (removed)
  SELECT url INTO v_expressiontosearch FROM sponsor_master_detail WHERE plid = v_slid;
  IF POSITION(v_expressiontosearch IN v_displayurl) = 0 AND POSITION(v_expressiontosearch IN v_destinationurl) = 0 THEN
  RETURN QUERY SELECT 4 AS status, ('Your Destination and Display Url Must Contain Your Registered Url. And Your Registered Url is:' || url || '') AS url FROM sponsor_master_detail WHERE plid = v_slid;
  RETURN;
  ELSE
  IF POSITION(v_expressiontosearch IN v_destinationurl) = 0 THEN
  RETURN QUERY SELECT 2 AS status, ('Your Destination Url Must Contain Your Registered Url. And Your Registered Url is: ' || url || '') AS url FROM sponsor_master_detail WHERE plid = v_slid;
  RETURN;
  ELSE
  IF POSITION(v_expressiontosearch IN v_displayurl) = 0 THEN
  RETURN QUERY SELECT 3 AS status, ('Your Display Url Must Contain Your Registered Url. And Your Registered Url is: ' || url || '') AS url FROM sponsor_master_detail WHERE plid = v_slid;
  RETURN;
  ELSE
  RETURN QUERY SELECT 1 AS status, ('<span style="color:red">' || url || '</span>') AS url FROM sponsor_master_detail WHERE plid = v_slid;
  RETURN;
  END IF;
  END IF;
  END IF;
END;
$$;


--
-- Name: usp_urlvalidationforsponsor(character varying, integer, character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_urlvalidationforsponsor(v_url character varying, v_cid integer, INOUT v_strresult character varying) RETURNS character varying
    LANGUAGE plpgsql
    AS $$
BEGIN
  v_strresult := 'ok';
  IF EXISTS(SELECT 1 FROM portal_login_temp WHERE RTRIM(LTRIM(sp_url)) LIKE '%' || v_url || '%' AND cid = v_cid) OR EXISTS(SELECT smdid FROM sponsor_master_detail WHERE RTRIM(LTRIM(url)) LIKE '%' || v_url || '%' AND cid = v_cid) THEN
  v_strresult := 'not ok';
  ELSE
  v_strresult := 'ok';
  END IF;
END;
$$;


--
-- Name: usp_user_order_list(integer, integer, character varying, character varying, character varying, character varying, character varying, integer, character varying, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_user_order_list(v_startrowindex integer DEFAULT 1, v_maxrows integer DEFAULT 50, v_searchfield character varying DEFAULT ''::character varying, v_searchvalue character varying DEFAULT ''::character varying, v_fromdate character varying DEFAULT ''::character varying, v_todate character varying DEFAULT ''::character varying, v_loginid character varying DEFAULT ''::character varying, v_totalcount integer DEFAULT 0, v_status character varying DEFAULT ''::character varying, v_did integer DEFAULT 0) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_minindex INT;
  v_maxindex INT;
  v_query text;
  v_openstatus1 INT;
  v_openstatus2 INT;
  v_openstatus3 INT;
BEGIN
  v_minindex := (v_startrowindex - 1) * v_maxrows + 1;
  v_maxindex := v_startrowindex * v_maxrows;
  v_openstatus1 := 8;
  v_openstatus2 := 7;
  v_openstatus3 := 6;
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp (ROWNUMBER BIGINT,          
ORID BIGINT,          
POID BIGINT,          
REPLACEMENTDAY INT,          
ReplacementDate DATE,          
CHECKSLA INT,      
ORDERID VARCHAR(100),          
TOTALPAYBLEAMT numeric(19,4),          
PAYMODE VARCHAR(100),          
PAYREMARK VARCHAR(100),          
ORDERDATE VARCHAR(100),          
NAME VARCHAR(100),          
MOBILENO VARCHAR(100),          
SHIPPINGADDRESS VARCHAR(500),          
PRODUCT_NAME VARCHAR(200),          
QUNTITY INT ,          
SINGLEPRODPRICE numeric(19,4),          
NETPAYBLEPRICE numeric(19,4),          
TOTAL_SHIP_CH DECIMAL(18,2),          
TOTAL_COST DECIMAL(18,2),          
TOTAL_PAYBLE_VAT DECIMAL(18,2),          
TOTAL_PURCHASE_COST DECIMAL(18,2),          
ORDERQTY INT,          
ORDERTOTALAMOUNT DECIMAL(18,2),          
ORDERTOTALVAT DECIMAL(18,2),          
ORDERSHIPPINGCHARGES DECIMAL(18,2),          
PROD_IMAGES text,          
STATUS VARCHAR(30),          
OSTATUS VARCHAR(30),          
BRCODE  BIGINT,          
BRNAME  text,          
ORDER_PV DECIMAL(18,2),          
ORDER_BV DECIMAL(18,2),          
INTSTATUS INT,        
CUSTOMERWALLET DECIMAL(18,2),         
          
MLMWALLET DECIMAL(18,2),          
MLMWALLET1 DECIMAL(18,2),         
MLMWALLET2 DECIMAL(18,2),         
MLMWALLET3 DECIMAL(18,2),         
OnlinePayments DECIMAL(18,2),        
        
MLMWALLETTransactionId Varchar(200),          
MLMWALLET1TransactionId Varchar(200),         
MLMWALLET2TransactionId Varchar(200),         
MLMWALLET3TransactionId Varchar(200),         
OnlinePaymentsTransactionId Varchar(200),        
        
         
CANCELDATE VARCHAR(100),          
EMAILID VARCHAR(100)  ,      
InvoiceNo VARCHAR(100) ,      
SPRID BIGINT,      
RefundFileImage varchar(1000)) ON COMMIT DROP;
  v_query := 'INSERT INTO #TEMP SELECT ROW_NUMBER() OVER (ORDER BY OM.ORDERDATE DESC) AS ROWNUMBER,          
OM.ORID,POM.POID,ISNULL(IMSP.ProcurementSLA,0)As REPLACEMENTDAY, DATEADD(DAY,ISNULL(IMSP.ProcurementSLA,0),OM.ORDERDATE) AS ReplacementDate ,        
(CASE WHEN DATEADD(DAY,ISNULL(IMSP.ProcurementSLA,0),OM.ORDERDATE) >= dbo.FUN_GETCURRENTDATE() THEN 1 ELSE 0 END) AS CHECKSLA,        
OM.ORDERID, OM.ORDER_NETAMT AS TOTALPAYBLEAMT, OM.PAYMODE,OM.PAYREMARK,          
REPLACE(CONVERT(VARCHAR(11), OM.ORDERDATE, 106), '' '', ''-'') +'' ''+STUFF(RIGHT( CONVERT(VARCHAR,OM.ORDERDATE,100 ) ,7), 6, 0, '' '') ORDERDATE,          
OM.FNAME + '' '' + OM.LNAME As NAME,OM.MOBILENO          
,OM.ADDRESS+'' '' + OM.SH_CITY  +'' (''+OM.PINCODE +'')'' + '' India '' AS SHIPPINGADDRESS,          
POM.PRODUCT_NAME,POM.PRODUCT_QTY AS QUNTITY,POM.SINGLE_DAP AS SINGLEPRODPRICE,POM.TOTAL_DAP AS NETPAYBLEPRICE,          
POM.TOTAL_SHIP_CH,POM.TOTAL_COST,POM.TOTAL_PAYBLE_VAT,POM.TOTAL_PURCHASE_COST,OM.ORDER_QTY AS ORDERQTY ,          
OM.ORDER_DAP AS ORDERTOTALAMOUNT,OM.TOTAL_VAT AS ORDERTOTALVAT,OM.TOTAL_SHIP_CH AS ORDERSHIPPINGCHARGES,          
ISNULL(POM.PROD_IMAGES,''default-product-image.png'')  AS PROD_IMAGES,POM.STATUS,          
OM.STATUS AS OSTATUS,OM.BRANCHID,BRM.FNAME,           
ISNULL(IMSP.PV,0) AS ORDER_PV,ISNULL(IMSP.BV,0) AS ORDER_BV,          
POM.INTSTATUS,        
ISNULL(0,0) AS CUSTOMERWALLET,         
ISNULL(CASHBACKWALLETUSED,0) AS MLMWALLET,        
ISNULL(CASHWALLETUSED,0) AS MLMWALLET1,         
ISNULL(VOUCHERWALLETUSED,0) AS MLMWALLET2,        
ISNULL(0.00,0.00) AS MLMWALLET3,         
ISNULL(TBL_ONLINEPAYMENTHISTORY.AMOUNT,0.00) AS OnlinePayments,        
ISNULL(CashbackWalletTransactionId,0) AS MLMWALLETTransactionId,        
ISNULL(CashWalletTransactionId,0) AS MLMWALLET1TransactionId,         
ISNULL(VoucherWalletTransactionId,0) AS MLMWALLET2TransactionId,        
ISNULL('''','''') AS MLMWALLET3TransactionId,         
ISNULL(TBL_ONLINEPAYMENTHISTORY.OrderId,'''') AS OnlinePaymentsTransactionId,          
REPLACE(CONVERT(VARCHAR(11), OCS.CANCEL, 106), '' '', ''-'')        
+'' ''+STUFF(RIGHT( CONVERT(VARCHAR,OCS.CANCEL,100 ) ,7), 6, 0, '' '') As CancelDate,BRM.EMAILID   ,POM.InvoiceNo ,ISNULL(IMSP.SPRID,0) AS SPRID,ISNULL(OCS.RefundFileImage,'''') As  RefundFileImage      
FROM TBL_ORDER_MASTER OM           
LEFT JOIN TBL_PRODUCT_ORDER_MASTER POM ON OM.ORDERID=POM.ORDERID            
LEFT JOIN IMS_SUBPRODUCT IMSP ON IMSP.SPRID= POM.SUBPRCODE          
LEFT JOIN TBL_CUSTOMERLOGIN BRM ON BRM.LOGINID=OM.LOGINID            
LEFT JOIN TBL_ORDERPAYMENT_HISTORY ON TBL_ORDERPAYMENT_HISTORY.ORDERID=OM.ORDERID        
LEFT JOIN TBL_ORDERONLINEREQUESTS ON TBL_ORDERONLINEREQUESTS.ORDERID=OM.ORDERID       
LEFT JOIN TBL_ONLINEPAYMENTHISTORY ON TBL_ONLINEPAYMENTHISTORY.REFERNECID=TBL_ORDERONLINEREQUESTS.TRANSACTIONID            
LEFT JOIN TBL_ORDER_CONFIRMEDSTAUS OCS ON POM.ORDERNO=OCS.ORDERNO           
WHERE POM.INTSTATUS>=0 AND  OM.LOGINID=''' || v_loginid || '''';
  IF (v_searchfield <> '') THEN
  v_query := v_query || 'AND OM.ORDERID=''' || v_searchfield || '''';
  END IF;
  IF (v_did > 1) THEN
  v_query := v_query || ' AND BRM.DID=''' || CAST(v_did AS VARCHAR(30)) || ''' ';
  END IF;
  v_query := v_query || ' ORDER BY POM.POID ASC';
  RAISE NOTICE '%', (v_query);
  EXECUTE v_query;
  IF (v_status = 'OPEN') THEN
  RETURN QUERY SELECT * FROM tmp_temp WHERE rownumber BETWEEN v_minindex AND v_maxindex AND (intstatus = 0 OR intstatus = 1);
  SELECT COUNT(rownumber) INTO v_totalcount FROM tmp_temp WHERE (intstatus = 0 OR intstatus = 1);
  ELSE
  IF (v_status = 'Refund') THEN
  RETURN QUERY SELECT * FROM tmp_temp WHERE rownumber BETWEEN v_minindex AND v_maxindex AND status = '' || v_status || '';
  SELECT COUNT(rownumber) INTO v_totalcount FROM tmp_temp WHERE status = '' || v_status || '';
  ELSE
  IF (v_status = 'CANCELLED') THEN
  RETURN QUERY SELECT * FROM tmp_temp WHERE rownumber BETWEEN v_minindex AND v_maxindex AND intstatus = '' || v_openstatus2 || '';
  SELECT COUNT(rownumber) INTO v_totalcount FROM tmp_temp WHERE intstatus = '' || v_openstatus2 || '';
  ELSE
  IF (v_status = 'COMPLETED') THEN
  RETURN QUERY SELECT * FROM tmp_temp WHERE rownumber BETWEEN v_minindex AND v_maxindex AND intstatus = '' || v_openstatus3 || '';
  SELECT COUNT(rownumber) INTO v_totalcount FROM tmp_temp WHERE intstatus = '' || v_openstatus3 || '';
  ELSE
  RETURN QUERY SELECT * FROM tmp_temp WHERE rownumber BETWEEN v_minindex AND v_maxindex;
  SELECT COUNT(rownumber) INTO v_totalcount FROM tmp_temp;
  END IF;
  END IF;
  END IF;
  END IF;
  DROP TABLE IF EXISTS tmp_temp;
  -- SET option (removed)
END;
$$;


--
-- Name: usp_user_order_list_mobile(integer, integer, character varying, character varying, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_user_order_list_mobile(v_startrowindex integer DEFAULT 1, v_maxrows integer DEFAULT 100, v_status character varying DEFAULT ''::character varying, v_orderid character varying DEFAULT 'OD290247215'::character varying, v_clid integer DEFAULT 2159) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_minindex int;
  v_maxindex int;
  v_query text;
  v_loginid varchar(100);
  v_totalcount int;
  v_dynamicurl varchar(100);
BEGIN
  v_minindex := (v_startrowindex - 1) * v_maxrows + 1;
  v_maxindex := v_startrowindex * v_maxrows;
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp (rowNumber bigint,
	orid bigint,
	Poid bigint,
	SPRID bigint,
	orderID varchar(100),
	totalPaybleAmt numeric(19,4),
	PayMode varchar(100),
	PayRemark varchar(100),
	orderDate varchar(100),
	Name varchar(100),
	MobileNo varchar(100),
	ShippingAddress varchar(500),
	Product_Name varchar(200),
	quntity int ,
	singleProdPrice numeric(19,4),
	netPayblePrice numeric(19,4),
	Total_Ship_Ch decimal(18,0),
	total_cost decimal(18,0),
	Total_payble_vat decimal(18,0),
	total_purchase_cost decimal(18,0),
	OrderQty int,
	OrderTotalAmount decimal(18,0),
	OrderTotalVat decimal(18,0),
	OrderShippingCharges decimal(18,0),
	Prod_Images varchar(500),
	Status varchar(30),
	OStatus varchar(30),
	BrCode  bigint,
	BrName  text,
	Order_PV decimal(18,0),
	Order_BV decimal(18,0),
	IntStatus int,
	CreatedDate varchar(50), 
	APPROVEDDATE varchar(50),
	PACKEDDATE varchar(50),
	HANDOVERDATE varchar(50),
	TransitDate varchar(50),
	PickedDate varchar(50),
	DeliveredDate varchar(50)) ON COMMIT DROP;
  v_loginid := '';
  v_totalcount := 0;
  SELECT loginid INTO v_loginid FROM tbl_customerlogin WHERE clid = v_clid;
  v_dynamicurl := '';
  SELECT merchantimagepath INTO v_dynamicurl FROM tbl_company;
  v_query := 'INSERT INTO #TEMP  SELECT ROW_NUMBER() OVER (ORDER BY OM.ORDERDATE DESC) AS ROWNUMBER,
OM.ORID,POM.POID,IMSP.SPRID,
OM.ORDERID, OM.ORDER_NETAMT AS TOTALPAYBLEAMT, OM.PAYMODE,OM.PAYREMARK,convert(varchar(50),OM.ORDERDATE,106) as ORDERDATE, OM.FNAME + '' '' + OM.LNAME,OM.MOBILENO
, OM.ADDRESS+'' '' + OM.SH_CITY  +''( ''+OM.PINCODE +'' )'' + '' India '' AS SHIPPINGADDRESS,
POM.PRODUCT_NAME,POM.PRODUCT_QTY AS QUNTITY,POM.SINGLE_DAP AS SINGLEPRODPRICE,POM.TOTAL_DAP AS NETPAYBLEPRICE,
POM.TOTAL_SHIP_CH,POM.TOTAL_COST,POM.TOTAL_PAYBLE_VAT,POM.TOTAL_PURCHASE_COST,OM.ORDER_QTY AS ORDERQTY ,
OM.ORDER_DAP AS ORDERTOTALAMOUNT,OM.TOTAL_VAT AS ORDERTOTALVAT,OM.TOTAL_SHIP_CH AS ORDERSHIPPINGCHARGES,
case when CHARINDEX(''^'',POM.PROD_IMAGES) >0 then (LEFT(''' || v_dynamicurl || '''+POM.PROD_IMAGES ,CHARINDEX(''^'',''' || v_dynamicurl || '''+POM.PROD_IMAGES)+0)) ELSE  ''' || v_dynamicurl || '''+
				POM.PROD_IMAGES+''^'' end   AS PROD_IMAGES,POM.STATUS,
OM.STATUS AS OSTATUS,OM.BRANCHID,BRM.FNAME, 
isnull(IMSP.PV,0) AS Order_PV,ISNULL(IMSP.BV,0) AS Order_BV,
POM.IntStatus,isnull(convert(varchar,OCS.CreatedDate,106),'''')CreatedDate,isnull(convert(varchar,OCS.[Date],106),'''')APPROVEDDATE,
isnull(convert(varchar,OCS.Packed,106),'''')PACKEDDATE,isnull(convert(varchar,OCS.Handover,106),'''')HANDOVERDATE,
isnull(convert(varchar,OCS.Intransit,106),'''')TransitDate,isnull(convert(varchar,OCS.Picked,106),'''')PickedDate,isnull(convert(varchar,OCS.Delivered,106),'''')DeliveredDate
FROM TBL_ORDER_MASTER OM 
LEFT JOIN TBL_PRODUCT_ORDER_MASTER POM ON OM.ORDERID=POM.ORDERID  
left join IMS_SubProduct IMSP on IMSP.SPRID= POM.SubPrCode
LEFT JOIN TBL_CUSTOMERLOGIN BRM 
ON BRM.LOGINID=OM.LOGINID  left join tbl_Order_ConfirmedStaus OCS on OCS.ORDERno=POM.ORDERno
WHERE  OM.LOGINID=''' || v_loginid || '''  ORDER BY POM.POID ASC';
  EXECUTE v_query;
  RAISE NOTICE '%', (v_query);
  IF (v_status <> '' AND v_orderid = '') THEN
  RETURN QUERY SELECT * FROM tmp_temp WHERE rownumber BETWEEN v_minindex AND v_maxindex AND intstatus = '' || v_status || '';
  SELECT COUNT(rownumber) INTO v_totalcount FROM tmp_temp WHERE intstatus = '' || v_status || '';
  ELSE
  IF (v_status <> '' AND v_orderid <> '') THEN
  RETURN QUERY SELECT * FROM tmp_temp WHERE rownumber BETWEEN v_minindex AND v_maxindex AND intstatus = '' || v_status || '' AND orderid = v_orderid;
  SELECT COUNT(rownumber) INTO v_totalcount FROM tmp_temp WHERE intstatus = '' || v_status || '' AND orderid = v_orderid;
  ELSE
  IF (v_orderid <> '') THEN
  RETURN QUERY SELECT * FROM tmp_temp WHERE rownumber BETWEEN v_minindex AND v_maxindex AND orderid = v_orderid;
  SELECT COUNT(rownumber) INTO v_totalcount FROM tmp_temp WHERE orderid = v_orderid;
  ELSE
  RETURN QUERY SELECT * FROM tmp_temp WHERE rownumber BETWEEN v_minindex AND v_maxindex;
  SELECT COUNT(rownumber) INTO v_totalcount FROM tmp_temp;
  END IF;
  END IF;
  END IF;
  DROP TABLE IF EXISTS tmp_temp;
  -- SET option (removed)
END;
$$;


--
-- Name: usp_user_subscription_details(bigint); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_user_subscription_details(v_pmid bigint) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
BEGIN
  -- SET option (removed)
  RETURN QUERY SELECT ROW_NUMBER() OVER (ORDER BY tsd.subscriptiondate DESC NULLS LAST) AS rownumber, tsd.sdid, (CASE tsd.status WHEN 1 THEN 'Active' WHEN 0 THEN 'Pending' END) AS active, tsd.price, tsd.totalprice, tsd.paidamount, tsd.noofmonth, tsd.subscriptiondate AS subscriptiondate, approvedate + (INTERVAL '1 MONTH' * noofmonth) AS expiredate, tcm.currencysymbol FROM tbl_subscription_details AS tsd, tbl_currencymaster AS tcm WHERE tsd.cid = tcm.cid AND tsd.pmid = v_pmid;
  -- SET option (removed)
END;
$$;


--
-- Name: usp_user_wish_list(character varying, integer, integer, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_user_wish_list(v_loginid character varying DEFAULT ''::character varying, v_totalcount integer DEFAULT 0, v_did integer DEFAULT 0, v_mode integer DEFAULT NULL::integer) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_minindex INT;
  v_maxindex INT;
  v_query text;
BEGIN
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp (ROWNUMBER BIGINT,
	PRODTITLE VARCHAR(200),
	SHORTDESC text,
	PRODIMAGES VARCHAR(500),
	DAP numeric(19,4),
	SPRID BIGINT,
	WLID INT,
	PV decimal(18,0),
	BV decimal(18,0),
	DID bigint,
	IsOutOfStock boolean) ON COMMIT DROP;
  IF (v_mode = 1) THEN
  v_query := 'INSERT INTO #TEMP  SELECT ROW_NUMBER() OVER (ORDER BY TWL.DATE DESC) AS ROWNUMBER, PMM.PRODUCTTITLE,PMM.SHOTDESCRIPTION,
	PMS.PRODUCTIMAGES, PMS.DAP,TWL.SPRID,TWL.WLID,ISNULL(PMS.PV,0)PV,ISNULL(PMS.BV,0)BV,cl.DID,PMS.IsOutOfStock
	--ISNULL(DPW.BV,0) as dist_BV,ISNULL(DPW.PV,0) as dist_PV 
	FROM IMS_SUBPRODUCT PMS INNER JOIN IMS_MASTERPRODUCT PMM ON PMS.MPRID=PMM.MPRID   
	INNER JOIN TBL_WISHLIST TWL ON TWL.SPRID=PMS.SPRID INNER join TBL_CUSTOMERLOGIN cl on cl.CLID=TWL.LoginId 
	--left join Tbl_DISTRIBUTOR_Comm_ProductWise DPW on TWL.SPRID=PMS.SPRID  and DPW.DID=cl.DID 
	 WHERE TWL.STATUS=1 AND TWL.LOGINID=''' || CAST(v_loginid AS VARCHAR(50)) || ''' and cl.DID=''' || CAST(v_did AS VARCHAR(10)) || ''' order by twl.date desc';
  EXECUTE v_query;
  RETURN QUERY SELECT * FROM tmp_temp;
  END IF;
  IF (v_mode = 2) THEN
  RETURN QUERY SELECT COUNT(1) FROM ims_subproduct AS pms INNER JOIN ims_masterproduct AS pmm ON pms.mprid = pmm.mprid INNER JOIN tbl_wishlist AS twl ON twl.sprid = pms.sprid INNER JOIN tbl_customerlogin AS cl ON cl.clid = twl.loginid WHERE twl.status = 1 AND twl.loginid = '' || CAST(v_loginid AS VARCHAR(50)) || '' AND cl.did = '' || CAST(v_did AS VARCHAR(10)) || '';
  END IF;
  SELECT COUNT(1) INTO v_totalcount FROM tmp_temp;
  DROP TABLE IF EXISTS tmp_temp;
  -- SET option (removed)
END;
$$;


--
-- Name: usp_user_wish_list_mobile(character varying, integer, integer, integer, character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_user_wish_list_mobile(v_loginid character varying DEFAULT ''::character varying, v_totalcount integer DEFAULT 0, v_did integer DEFAULT 0, v_mode integer DEFAULT NULL::integer, v_uidno character varying DEFAULT ''::character varying) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_dynamicurl varchar(100);
BEGIN
  v_dynamicurl := '';
  SELECT merchantimagepath INTO v_dynamicurl FROM tbl_company;
  RETURN QUERY SELECT ROW_NUMBER() OVER (ORDER BY twl.date DESC NULLS LAST) AS rownumber, pmm.producttitle, pmm.shotdescription, CASE WHEN POSITION('^' IN pms.productimages) > 0 THEN (LEFT(CAST(v_dynamicurl || pms.productimages AS TEXT), POSITION('^' IN v_dynamicurl || pms.productimages) + 0)) ELSE v_dynamicurl || pms.productimages || '^' END AS productimages, pms.dap, twl.sprid, twl.wlid, COALESCE(dcs.bv, 0) AS bv, COALESCE(dcs.cashback, 0) AS cashback, 0 AS did, pms.isoutofstock, pms.discountpercentage, pms.sellmrp FROM ims_subproduct AS pms INNER JOIN ims_masterproduct AS pmm ON pms.mprid = pmm.mprid INNER JOIN tbl_wishlist AS twl ON twl.sprid = pms.sprid LEFT OUTER JOIN tbl_sub_category AS tsb ON pmm.subcategoryid = tsb.subcatid LEFT OUTER JOIN tbl_distributor_commission_structure AS dcs ON dcs.subsubcatid = tsb.subcatid AND dcs.did = v_did WHERE twl.status = 1 AND twl.loginid = v_loginid ORDER BY twl.date DESC NULLS LAST;
END;
$$;


--
-- Name: usp_userinvoice(integer, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_userinvoice(v_plid integer DEFAULT 0, v_sfdid integer DEFAULT 0) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_minindex INT;
  v_maxindex INT;
  v_query text;
BEGIN
  IF (v_plid = 0) THEN
  SELECT plid INTO v_plid FROM tbl_allsubscriptionmaster WHERE tasmid = v_sfdid;
  END IF;
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp (ROWNUMBER INT GENERATED BY DEFAULT AS IDENTITY,TASMID BIGINT,TOTALPAYABLEAMOUNT numeric(19,4),PAYMENTMODE INT,MODENAME VARCHAR(100),COMMENTORREMARK text,REGNO BIGINT,IMAGENAME text,
BANKNAME VARCHAR(100),BRANCHNAME VARCHAR(100),REFERENCEDATE VARCHAR(100),REFERENCENUMBER VARCHAR(100),WALLETID VARCHAR(100),TRANSACTIONPASSWORD VARCHAR(100),
GOOGLEAUTHENTICATIONCODE VARCHAR(100),ALLPACKAGEID VARCHAR(100),ALLPACKAGETYPE VARCHAR(100),ALLPACKAGEAMOUNT VARCHAR(100),PUCHASEDATE timestamp,ISACTIVE INT,
STATUS INT,PLID BIGINT,ALLPACKAGENAME VARCHAR(500),ISAPPROVED INT,TRANSACTION_ID VARCHAR(100),SERVICE_TAX numeric(19,4),SERVICE_TAX_PER numeric(19,4),WITH_OUT_TAX_AMOUNT numeric(19,4),
USERNAME VARCHAR(200),FULLNAME VARCHAR(200),MOBILE VARCHAR(100),EMAILID VARCHAR(100),ADDRESS VARCHAR(100),CITY VARCHAR(100),POSTALCODE VARCHAR(100),ALLADDRESS text,SID INT,
STATENAME VARCHAR(100),STATENAMEPINCODE VARCHAR(300),INVOICE_NO VARCHAR(50)) ON COMMIT DROP;
  v_query := 'INSERT INTO #TEMP  SELECT  SM.TASMID,SM.TOTALPAYABLEAMOUNT,SM.PAYMENTMODE,SM.MODENAME,SM.COMMENTORREMARK,SM.REGNO,SM.IMAGENAME,
SM.BANKNAME,SM.BRANCHNAME,SM.REFERENCEDATE,SM.REFERENCENUMBER,SM.WALLETID,SM.TRANSACTIONPASSWORD,SM.GOOGLEAUTHENTICATIONCODE ,SM.ALLPACKAGEID,SM.ALLPACKAGETYPE ,
SM.ALLPACKAGEAMOUNT ,SM.PUCHASEDATE ,ISNULL(SM.ISACTIVE,0),ISNULL(SM.STATUS,0) ,SM.PLID,REPLACE(ISNULL(SM.ALLPACKAGENAME,''''),''~'','',''),ISNULL(SM.ISAPPROVED,0) ,
SM.TRANSACTION_ID,ISNULL(SM.SERVICE_TAX,0),ISNULL(SM.SERVICE_TAX_PER,0) ,ISNULL(SM.WITH_OUT_TAX_AMOUNT,0),PL.USERNAME,ISNULL(PL.FNAME,'''')+'' ''+ISNULL(PL.LNAME,'''') AS FULLNAME,
ISNULL(PL.PHONE,'''') AS MOBILE,ISNULL(PL.EMAILID,'''') AS EMAILID,ISNULL(SB.ADDRESS,''''),ISNULL(SB.CITY,''''),ISNULL(SB.POSTALCODE,'''')
,ISNULL(SB.ADDRESS,'''')+'',''+ISNULL(SB.CITY,'''') AS ALLADDRESS,ISNULL(SB.SID,0),ISNULL(S.STATENAME,''''),ISNULL(S.STATENAME,'''')+''-''+ISNULL(SB.POSTALCODE,'''') AS STATENAMEPINCODE
,ISNULL(SM.INVOICE_NO,'''') FROM TBL_ALLSUBSCRIPTIONMASTER SM INNER JOIN PORTAL_LOGIN PL ON PL.PLID=SM.PLID LEFT JOIN TBL_SPONSERBILLING SB ON SB.PLID=SM.PLID LEFT JOIN STATE S ON S.SID=SB.SID 
WHERE SM.PLID=' || CAST(v_plid AS VARCHAR(50)) || '';
  IF (v_sfdid > 0) THEN
  v_query := v_query || ' AND SM.TASMID=' || CAST(v_sfdid AS VARCHAR(50));
  END IF;
  EXECUTE v_query;
  RAISE NOTICE '%', (v_query);
  RETURN QUERY SELECT * FROM tmp_temp;
  DROP TABLE IF EXISTS tmp_temp;
  -- SET option (removed)
END;
$$;


--
-- Name: usp_userresellerwallet(character varying, numeric, character varying, numeric, numeric, integer, character varying, character varying, character varying, numeric, numeric); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_userresellerwallet(v_ordernumber character varying DEFAULT ''::character varying, v_usedamount numeric DEFAULT 0, v_tranid character varying DEFAULT ''::character varying, v_mlmwalletusedamount numeric DEFAULT 0, v_voucherqty numeric DEFAULT 0, v_walletid integer DEFAULT 0, v_beni_username character varying DEFAULT ''::character varying, v_mlmtranid character varying DEFAULT ''::character varying, INOUT v_strresult character varying DEFAULT ''::character varying, v_onlinepayment numeric DEFAULT 0, v_codpayment numeric DEFAULT 0) RETURNS character varying
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_clid INT;
  v_loginid VARCHAR(500);
  v_did INT;
  v_shoppingwallet DECIMAL(18,8);
  v_pmid INT;
  v_distributorbalance DECIMAL(18,8);
  v_billamount DECIMAL(18,8);
  v_orderid VARCHAR(500);
  v_totalpaidamount DECIMAL(18,8);
  v_oorid INT;
  v_remark VARCHAR(600);
BEGIN
  -- BEGIN TRAN (removed)
  v_strresult := 'success';
  v_clid := 0;
  v_loginid := '';
  v_did := 0;
  v_pmid := 0;
  v_distributorbalance := 0;
  v_billamount := 0;
  v_orderid := '';
  v_totalpaidamount := 0;
  v_totalpaidamount := COALESCE(v_usedamount, 0) + COALESCE(v_mlmwalletusedamount, 0);
  SELECT loginid, amount, orderid, oorid INTO v_loginid, v_billamount, v_orderid, v_oorid FROM tbl_orderonlinerequests WHERE transactionid = v_ordernumber;
  SELECT clid, did INTO v_clid, v_did FROM tbl_customerlogin WHERE loginid = v_loginid;
  SELECT COALESCE(availablebalance, 0) INTO v_shoppingwallet FROM tbl_customerwallet WHERE clid = v_clid;
  IF NOT EXISTS(SELECT 1 FROM tbl_orderpayment_history WHERE orderid = v_orderid) THEN
  INSERT INTO tbl_orderpayment_history (orderid, cashbackwalletused, cashwalletused, voucherwalletused, cashwallettransactionid, cashbackwallettransactionid, voucherwallettransactionid, activitydatetime, debitcashwallettransactionid, debitcashbackwallettransactionid, debitvoucherwallettransactionid, status, active, codpayment) VALUES (v_orderid, 0, 0, 0, '', '', '', dbo.FUN_GETCURRENTDATE(), '', '', '', 1, 1, v_codpayment);
  END IF;
  IF (v_walletid = 5) THEN
  UPDATE tbl_orderpayment_history SET voucherwalletused = voucherwalletused + v_voucherqty, activitydatetime = dbo.FUN_GETCURRENTDATE(), voucherwallettransactionid = (CASE WHEN voucherwallettransactionid = '' THEN v_mlmtranid ELSE '^' || v_mlmtranid END), debitvoucherwallettransactionid = (CASE WHEN debitvoucherwallettransactionid = '' THEN v_tranid ELSE '^' || v_tranid END) WHERE orderid = v_orderid;
  END IF;
  IF (v_walletid = 1) THEN
  UPDATE tbl_orderpayment_history SET cashbackwalletused = cashbackwalletused + v_mlmwalletusedamount, activitydatetime = dbo.FUN_GETCURRENTDATE(), cashbackwallettransactionid = (CASE WHEN cashbackwallettransactionid = '' THEN v_mlmtranid ELSE '^' || v_mlmtranid END), debitcashbackwallettransactionid = (CASE WHEN debitcashbackwallettransactionid = '' THEN v_tranid ELSE '^' || v_tranid END) WHERE orderid = v_orderid;
  END IF;
  IF (v_walletid = 4) THEN
  UPDATE tbl_orderpayment_history SET cashwalletused = cashwalletused + v_mlmwalletusedamount, activitydatetime = dbo.FUN_GETCURRENTDATE(), cashwallettransactionid = (CASE WHEN cashwallettransactionid = '' THEN v_mlmtranid ELSE '^' || v_mlmtranid END), debitcashwallettransactionid = (CASE WHEN debitcashwallettransactionid = '' THEN v_tranid ELSE '^' || v_tranid END) WHERE orderid = v_orderid;
  END IF;
  IF (v_walletid = 9) THEN
  UPDATE tbl_orderpayment_history SET ewalletused = ewalletused + v_mlmwalletusedamount, activitydatetime = dbo.FUN_GETCURRENTDATE(), ewallettransactionid = (CASE WHEN ewallettransactionid = '' THEN v_mlmtranid ELSE '^' || v_mlmtranid END), debitewallettransactionid = (CASE WHEN debitewallettransactionid = '' THEN v_tranid ELSE '^' || v_tranid END) WHERE orderid = v_orderid;
  END IF;
  IF (v_walletid = 3) THEN
  UPDATE tbl_orderpayment_history SET codpayment = v_mlmwalletusedamount, activitydatetime = dbo.FUN_GETCURRENTDATE() WHERE orderid = v_orderid;
  END IF;
  IF NOT EXISTS(SELECT 1 FROM tbl_orderonlinerequests WHERE transactionid = v_ordernumber) THEN
  v_strresult := 'Invalid Order Id !';
  -- COMMIT (removed)
  RETURN;
  END IF;
  IF (v_usedamount > v_shoppingwallet) THEN
  v_strresult := 'Insufficient fund in your wallet!';
  -- COMMIT (removed)
  RETURN;
  END IF;
  IF (v_usedamount > 0) THEN
  IF (v_totalpaidamount <> v_billamount) THEN
  v_strresult := 'You need to pay ' || CAST(v_billamount AS VARCHAR(100)) || ' only to complete this order!';
  -- COMMIT (removed)
  RETURN;
  END IF;
  END IF;
  v_remark := '';
  IF (v_usedamount > 0) THEN
  v_remark := 'Debit against order number ' || v_orderid;
  UPDATE tbl_customerwallet SET availablebalance = availablebalance - v_usedamount WHERE clid = v_clid;
  INSERT INTO tbl_customerwallet_statements (clid, processdate, crdrtype, cramt, dramt, old_balance, balance, remarks, traceno, status) VALUES (v_clid, dbo.FUN_GETCURRENTDATE(), 'DR', 0, v_usedamount, v_shoppingwallet, (v_shoppingwallet - v_usedamount), v_remark, v_tranid, 1);
  ELSE
  v_remark := 'Debit against order number ' || v_orderid;
  END IF;
  INSERT INTO tbl_resellerwalletstatement (did, date, crdrtype, cr_amount, dr_amount, remarks, status, traceno, old_bal, balance, trsid) VALUES (v_did, dbo.FUN_GETCURRENTDATE(), 'DR', 0, v_billamount, v_remark, 1, v_tranid, 0, 0, 2);
  INSERT INTO tbl_orderpaymentsdetails (oorid, orderid, paymentdate, transid, mlmwallet, mlmtranid, beni_username, customerwallet, status, onlinepayment, walletid) VALUES (v_oorid, v_orderid, dbo.FUN_GETCURRENTDATE(), v_ordernumber, (CASE WHEN v_walletid = 5 THEN v_voucherqty ELSE v_mlmwalletusedamount END), v_mlmtranid, v_beni_username, v_usedamount, 1, v_onlinepayment, v_walletid);
  -- COMMIT (removed)
END;
$$;


--
-- Name: usp_userresellerwallet_recharge(character varying, numeric, character varying, numeric, integer, character varying, character varying, character varying, numeric); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_userresellerwallet_recharge(v_ordernumber character varying DEFAULT '1561529522'::character varying, v_usedamount numeric DEFAULT 10, v_tranid character varying DEFAULT '201902131454071096'::character varying, v_mlmwalletusedamount numeric DEFAULT 0, v_walletid integer DEFAULT 0, v_beni_username character varying DEFAULT ''::character varying, v_mlmtranid character varying DEFAULT ''::character varying, INOUT v_strresult character varying DEFAULT ''::character varying, v_onlinepayment numeric DEFAULT 0) RETURNS character varying
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_clid INT;
  v_loginid VARCHAR(500);
  v_did INT;
  v_shoppingwallet DECIMAL(18,8);
  v_pmid int;
  v_distributorbalance decimal(18,8);
  v_billamount DECIMAL(18,8);
  v_orderid VARCHAR(500);
  v_totalpaidamount DECIMAL(18,8);
  v_oorid INT;
  v_mobileno VARCHAR(20);
  v_rechargetype VARCHAR(100);
  v_remark VARCHAR(600);
BEGIN
  -- BEGIN TRAN (removed)
  v_strresult := 'SUCCESS';
  v_clid := 0;
  v_loginid := '';
  v_did := 0;
  v_pmid := 0;
  v_distributorbalance := 0;
  v_billamount := 0;
  v_orderid := '';
  v_totalpaidamount := 0;
  v_oorid := 0;
  v_mobileno := '';
  v_rechargetype := '';
  v_totalpaidamount := COALESCE(v_usedamount, 0) + COALESCE(v_mlmwalletusedamount, 0);
  IF NOT EXISTS(SELECT 1 FROM dbo.tbl_customer_postpaid_recharges WHERE transactionid = v_ordernumber AND rechargestatus IS NULL) AND NOT EXISTS(SELECT 1 FROM dbo.tbl_customer_dth_recharges WHERE transactionid = v_ordernumber AND rechargestatus IS NULL) AND NOT EXISTS(SELECT 1 FROM dbo.tbl_customer_prepaid_recharges WHERE transactionid = v_ordernumber AND rechargestatus IS NULL) AND NOT EXISTS(SELECT 1 FROM dbo.tbl_customer_electricity_recharges WHERE transactionid = v_ordernumber AND rechargestatus IS NULL) AND NOT EXISTS(SELECT 1 FROM dbo.tbl_customer_gas_recharges WHERE transactionid = v_ordernumber AND rechargestatus IS NULL) THEN
  v_strresult := 'Invalid Transaction Id!';
  -- COMMIT (removed)
  RETURN;
  END IF;
  IF EXISTS(SELECT 1 FROM dbo.tbl_customer_postpaid_recharges WHERE transactionid = v_ordernumber AND rechargestatus IS NULL) THEN
  v_rechargetype := 'POSTPAID';
  END IF;
  IF EXISTS(SELECT 1 FROM dbo.tbl_customer_dth_recharges WHERE transactionid = v_ordernumber AND rechargestatus IS NULL) THEN
  v_rechargetype := 'DTH';
  END IF;
  IF EXISTS(SELECT 1 FROM dbo.tbl_customer_prepaid_recharges WHERE transactionid = v_ordernumber AND rechargestatus IS NULL) THEN
  v_rechargetype := 'PREPAID';
  END IF;
  IF EXISTS(SELECT 1 FROM dbo.tbl_customer_electricity_recharges WHERE transactionid = v_ordernumber AND rechargestatus IS NULL) THEN
  v_rechargetype := 'ELECTRICITY';
  END IF;
  IF EXISTS(SELECT 1 FROM dbo.tbl_customer_gas_recharges WHERE transactionid = v_ordernumber AND rechargestatus IS NULL) THEN
  v_rechargetype := 'GAS';
  END IF;
  IF (v_rechargetype = 'POSTPAID') THEN
  SELECT clid, rechargeamount, mobileno INTO v_clid, v_billamount, v_mobileno FROM dbo.tbl_customer_postpaid_recharges WHERE transactionid = v_ordernumber;
  END IF;
  IF (v_rechargetype = 'DTH') THEN
  SELECT clid, rechargeamount, mobileno INTO v_clid, v_billamount, v_mobileno FROM dbo.tbl_customer_dth_recharges WHERE transactionid = v_ordernumber;
  END IF;
  IF (v_rechargetype = 'PREPAID') THEN
  SELECT clid, rechargeamount, mobileno INTO v_clid, v_billamount, v_mobileno FROM dbo.tbl_customer_prepaid_recharges WHERE transactionid = v_ordernumber;
  END IF;
  IF (v_rechargetype = 'ELECTRICITY') THEN
  SELECT clid, rechargeamount, mobileno INTO v_clid, v_billamount, v_mobileno FROM dbo.tbl_customer_electricity_recharges WHERE transactionid = v_ordernumber;
  END IF;
  IF (v_rechargetype = 'GAS') THEN
  SELECT clid, rechargeamount, mobileno INTO v_clid, v_billamount, v_mobileno FROM dbo.tbl_customer_gas_recharges WHERE transactionid = v_ordernumber;
  END IF;
  SELECT clid, did, loginid INTO v_clid, v_did, v_loginid FROM tbl_customerlogin WHERE clid = v_clid;
  SELECT COALESCE(availablebalance, 0) INTO v_shoppingwallet FROM tbl_customerwallet WHERE clid = v_clid;
  IF (v_usedamount > v_shoppingwallet) THEN
  v_strresult := 'Insufficient fund in your wallet!';
  -- COMMIT (removed)
  RETURN;
  END IF;
  SELECT pmid INTO v_pmid FROM tbl_distributor WHERE did = v_did;
  IF NOT EXISTS(SELECT 1 FROM tbl_distributor_prepaid_setting WHERE pmid = v_pmid) THEN
  v_strresult := 'Reseller Wallet does not Exist!';
  -- COMMIT (removed)
  RETURN;
  END IF;
  SELECT COALESCE(available_wallet, 0) INTO v_distributorbalance FROM tbl_distributor_prepaid_setting WHERE pmid = v_pmid;
  IF (v_billamount > v_distributorbalance) THEN
  v_strresult := 'Insufficient fund in reseller wallet!';
  -- COMMIT (removed)
  RETURN;
  END IF;
  IF (v_totalpaidamount <> v_billamount) THEN
  v_strresult := 'You need to pay ' || CAST(v_billamount AS VARCHAR(100)) || ' only to complete this order!';
  -- COMMIT (removed)
  RETURN;
  END IF;
  v_remark := '';
  IF (v_usedamount > 0) THEN
  IF (v_rechargetype = 'POSTPAID') THEN
  v_remark := 'Debit wallet against POSTPAID RECHARGE on ' || CAST(v_mobileno AS VARCHAR(20)) || ' with transaction id ' || v_ordernumber;
  END IF;
  IF (v_rechargetype = 'PREPAID') THEN
  v_remark := 'Debit wallet against PREPAID RECHARGE on ' || CAST(v_mobileno AS VARCHAR(20)) || ' with transaction id ' || v_ordernumber;
  END IF;
  IF (v_rechargetype = 'DTH') THEN
