--
-- Name: usp_uspnotifications_show(integer, integer, integer, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_uspnotifications_show(v_tcnid integer DEFAULT 0, v_tcntid integer DEFAULT 0, v_clid integer DEFAULT 2, v_mode integer DEFAULT 1) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF (v_mode = 1) THEN
  RETURN QUERY SELECT tcnid, cn.tcntid, clid, notificationdescription, notificationdate, isread, cn.active, isreaddate, referenceid, orderid FROM tbl_customer_notifications_type AS nt JOIN tbl_customer_notifications AS cn ON cn.tcntid = nt.tcntid WHERE clid = v_clid AND isread = 0 AND cn.active = 1;
  END IF;
  IF (v_mode = 2) THEN
  UPDATE tbl_customer_notifications SET isread = 0, active = 0, isreaddate = CURRENT_TIMESTAMP WHERE tcnid = v_tcnid;
  END IF;
  IF (v_mode = 3) THEN
  RETURN QUERY SELECT tcnid, cn.tcntid, clid, notificationdescription, notificationdate, isread, cn.active, isreaddate, referenceid, orderid FROM tbl_customer_notifications_type AS nt JOIN tbl_customer_notifications AS cn ON cn.tcntid = nt.tcntid WHERE clid = v_clid AND isread = 0 AND cn.active = 0;
  END IF;
  IF (v_mode = 4) THEN
  RETURN QUERY SELECT COALESCE(COUNT(1), 0) FROM tbl_customer_notifications_type AS nt JOIN tbl_customer_notifications AS cn ON cn.tcntid = nt.tcntid WHERE clid = v_clid AND isread = 0 AND cn.active = 1;
  END IF;
END;
$$;


--
-- Name: usp_uspnotifications_show_all(integer, integer, integer, integer, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_uspnotifications_show_all(v_tcnid integer DEFAULT 0, v_tcntid integer DEFAULT 0, v_clid integer DEFAULT 2, v_mode integer DEFAULT 1, v_did integer DEFAULT 1) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_dynamicurl varchar(100);
  v_merchantproductlargeimage varchar(250);
  v_software_url varchar(250);
  v_companyredirect varchar(250);
BEGIN
  IF (v_tcnid > 0) THEN
  UPDATE cn SET isread = 1, isreaddate = CURRENT_TIMESTAMP FROM dbo.tbl_customer_notifications AS cn JOIN tbl_customerlogin AS cl ON cl.clid = cn.clid WHERE tcnid = v_tcnid AND cl.did = v_did;
  END IF;
  v_dynamicurl := '';
  v_merchantproductlargeimage := '';
  v_software_url := '';
  v_companyredirect := '';
  SELECT merchantimagepath, merchantproductlargeimage, software_url INTO v_dynamicurl, v_merchantproductlargeimage, v_software_url FROM tbl_company;
  SELECT COALESCE(companyredirect, '') INTO v_companyredirect FROM tbl_companysettings WHERE pmid = v_did;
  RETURN QUERY SELECT tcnid, tcntid, cn.clid, notificationdescription AS notificationdesc, REPLACE(CAST(TO_CHAR(notificationdate, 'DD TMMon YYYY') AS VARCHAR(11)), ' ', '-') || ' ' || STUFF(RIGHT(CAST(CAST(TO_CHAR(notificationdate, 'TMMon DD YYYY FMHH12:MI%p') AS VARCHAR(30)) AS TEXT), 7), 6, 0, ' ') AS notificationdate, referenceid AS referenceid, isread AS isread, cn.active AS active, CASE WHEN tcntid = 2 THEN v_software_url || '/images/ticket.png' WHEN tcntid = 1 THEN prod_images WHEN tcntid = 3 THEN v_companyredirect || '/kyc.png' ELSE COALESCE(prod_images, '') END AS prod_images, CAST(TO_CHAR(createdate + 7, 'TMMon DD, YYYY') AS VARCHAR(50)) AS expecteddelivery, COALESCE(pom.orderid, '') AS orderid, COALESCE(pom.status, '') AS status, COALESCE(product_name, '') AS product_name, COALESCE(poid, 0) AS poid, v_dynamicurl AS baseurl FROM dbo.tbl_customer_notifications AS cn LEFT JOIN tbl_product_order_master AS pom ON pom.orderno = cn.referenceid LEFT JOIN tbl_customerlogin AS cl ON cl.clid = cn.clid WHERE cn.clid = v_clid AND cn.active = 1 AND cl.did = v_did ORDER BY cn.tcnid DESC NULLS LAST;
END;
$$;


--
-- Name: usp_utility_commission_settings(integer, numeric, numeric, numeric, numeric, numeric, integer, integer, character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_utility_commission_settings(v_tvrcsid integer DEFAULT 1, v_pack1 numeric DEFAULT 0, v_pack2 numeric DEFAULT 0, v_pack3 numeric DEFAULT 0, v_pack4 numeric DEFAULT 0, v_admincharge numeric DEFAULT 0, v_userid integer DEFAULT 0, v_did integer DEFAULT 0, INOUT v_result character varying DEFAULT ''::character varying) RETURNS character varying
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_operatorname VARCHAR(100);
  v_operatorcode VARCHAR(100);
  v_providername VARCHAR(100);
  v_providercode VARCHAR(100);
BEGIN
  -- BEGIN TRAN (removed)
  v_operatorname := '';
  v_operatorcode := '';
  v_providername := '';
  v_providercode := '';
  IF (v_tvrcsid = 0) THEN
  -- COMMIT (removed)
  v_result := 'DATA IS NOT EXISTS';
  RETURN;
  END IF;
  IF (v_did = 0) THEN
  -- COMMIT (removed)
  v_result := 'Reseller is not Exists';
  RETURN;
  END IF;
  SELECT operatorname, operatorcode, servicename INTO v_operatorname, v_operatorcode, v_providername FROM tbl_vendor_recharge_commission_structure WHERE tvrcsid = v_tvrcsid;
  IF (v_operatorname <> '' AND v_providername <> '') THEN
  IF NOT EXISTS(SELECT 1 FROM tbl_reseller_wise_package_commission_settings WHERE operatorname = v_operatorname AND providername = v_providername AND did = v_did) THEN
  INSERT INTO tbl_reseller_wise_package_commission_settings (did, operatorname, operatorcode, providername, providercode, package1commission, package2commission, package3commission, package4commission, adminsurcharge, active, createddate, createdby, status) VALUES (v_did, v_operatorname, v_operatorcode, v_providername, v_providercode, v_pack1, v_pack2, v_pack3, v_pack4, v_admincharge, 1, dbo.FUN_GETCURRENTDATE(), v_userid, 1);
  v_result := '1';
  ELSE
  INSERT INTO tbl_reseller_wise_package_commission_settings_history SELECT * FROM tbl_reseller_wise_package_commission_settings WHERE operatorname = v_operatorname AND providername = v_providername;
  UPDATE tbl_reseller_wise_package_commission_settings SET operatorname = v_operatorname, operatorcode = v_operatorcode, providername = v_providername, providercode = v_providercode, package1commission = v_pack1, package2commission = v_pack2, package3commission = v_pack3, package4commission = v_pack4, adminsurcharge = v_admincharge, updateddate = dbo.FUN_GETCURRENTDATE(), updatedby = v_userid WHERE operatorname = v_operatorname AND providername = v_providername AND did = v_did;
  v_result := '2';
  END IF;
  END IF;
  -- COMMIT (removed)
  IF (0 <> 0) THEN
  PERFORM dbo.sp_errorlog();
  v_result := 'ERROR IN REQUEST';
  -- ROLLBACK (removed)
  END IF;
END;
$$;


--
-- Name: usp_utility_reseller_bv_pv_commission(integer, character varying, character varying, numeric, character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_utility_reseller_bv_pv_commission(v_did integer DEFAULT 2, v_custtransactionid character varying DEFAULT '1152964997'::character varying, v_operatorname character varying DEFAULT 'Airtel'::character varying, v_amount numeric DEFAULT 10, INOUT v_strresult character varying DEFAULT ''::character varying) RETURNS character varying
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_orderstatus INT;
  v_orderbv DECIMAL(18,8);
  v_loginid VARCHAR(20);
  v_mode INT;
  v_orderid VARCHAR(50);
  v_tvrcsid int;
  v_bv DECIMAL(18,2);
  v_pv DECIMAL(18,2);
  v_comid INT;
  v_realcommission DECIMAL(18,2);
  v_totalpurchasecost DECIMAL(18,2);
BEGIN
  -- BEGIN TRAN (removed)
  v_orderbv := 0;
  v_loginid := '';
  v_mode := 0;
  v_orderid := '';
  v_tvrcsid := 0;
  v_bv := 0;
  v_pv := 0;
  v_comid := 0;
  v_realcommission := 0;
  v_totalpurchasecost := 0;
  SELECT COALESCE(tvrcsid, 0) INTO v_tvrcsid FROM tbl_vendor_recharge_commission_structure WHERE operatorname = v_operatorname;
  SELECT COALESCE(bv, 0), COALESCE(pv, 0), COALESCE(commission, 0) INTO v_bv, v_pv, v_realcommission FROM tbl_utilities_wise_bv_pv_setting WHERE did = v_did AND tvrcsid = v_tvrcsid;
  IF NOT EXISTS(SELECT 1 FROM tbl_reseller_bv_pv_master WHERE orderid = v_custtransactionid) THEN
  INSERT INTO tbl_reseller_bv_pv_master (orderid, totalcommission, totalbv, totalpv, status, type, did, create_date) VALUES (v_custtransactionid, v_realcommission, v_bv, v_pv, 1, 1, v_did, dbo.FUN_GETCURRENTDATE());
  END IF;
  SELECT MAX(comid) INTO v_comid FROM tbl_reseller_bv_pv_master;
  IF NOT EXISTS(SELECT 1 FROM tbl_reseller_bv_pv_details WHERE orderno = v_custtransactionid) THEN
  INSERT INTO tbl_reseller_bv_pv_details (comid, orderno, commissionpercentage, commissionvalue, bvpercentage, bvalue, pvpercentage, pvalue, status, type, releasedstatus, create_date) VALUES (v_comid, v_custtransactionid, v_realcommission, (v_amount * v_realcommission) / 100, v_bv, (v_amount * v_bv) / 100, v_pv, (v_amount * v_pv) / 100, 1, 1, 0, dbo.FUN_GETCURRENTDATE());
  END IF;
  IF (0 > 0) THEN
  v_strresult := 'ERROR';
  -- ROLLBACK (removed)
  RETURN;
  END IF;
  -- COMMIT (removed)
END;
$$;


--
-- Name: usp_utilitycommission_list(integer, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_utilitycommission_list(v_stid integer DEFAULT 1, v_did integer DEFAULT 1046) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
BEGIN
  -- BEGIN TRAN (removed)
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp ON COMMIT DROP AS SELECT DISTINCT tvrcsid, trcs.operatorname, commission, surcharge, (CASE WHEN trcs.active = 1 THEN 'ACTIVE' ELSE 'DEACTIVE' END) AS active, REPLACE(CAST(TO_CHAR(trcs.createdate, 'DD TMMon YYYY') AS VARCHAR(11)), ' ', '-') || ' ' || STUFF(RIGHT(CAST(CAST(TO_CHAR(CURRENT_TIMESTAMP, 'TMMon DD YYYY FMHH12:MI%p') AS VARCHAR(30)) AS TEXT), 7), 6, 0, ' ') AS createdate, COALESCE(rpcs.actualpercentagepack1, 0) AS package1commission, COALESCE(rpcs.actualpercentagepack2, 0) AS package2commission, COALESCE(rpcs.actualpercentagepack3, 0) AS package3commission, COALESCE(rpcs.actualpercentagepack4, 0) AS package4commission, COALESCE(rpcs.adminsurcharge, 0) AS adminsurcharge FROM tbl_vendor_recharge_commission_structure AS trcs LEFT JOIN tbl_default_package_commission_settings AS rpcs ON trcs.operatorname = rpcs.operatorname LEFT JOIN tbl_reseller_packages AS trs ON trcs.trsid = trs.trsid WHERE trcs.stid = v_stid AND trcs.active = 1 AND trs.active = 1;
  RETURN QUERY SELECT ROW_NUMBER() OVER (ORDER BY tvrcsid NULLS FIRST) AS rownumber, * FROM tmp_temp;
  DROP TABLE IF EXISTS tmp_temp;
  -- SET option (removed)
  -- COMMIT (removed)
END;
$$;


