--
-- Name: usp_validatecoupon(bigint, character varying, character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_validatecoupon(v_pmid bigint, v_couponno character varying, v_strresult character varying) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_membercurrency varchar(5);
  v_couponcurrency varchar(5);
  v_couponamount numeric(19,4);
BEGIN
  -- BEGIN TRAN (removed)
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp (valid varchar(50),

price numeric(19,4),

currency varchar(10)) ON COMMIT DROP;
  IF EXISTS(SELECT * FROM coupon_master WHERE coupon_number = v_couponno AND usedby = 0 AND status = 1) THEN
  SELECT currencysymbol INTO v_membercurrency FROM portal_login WHERE plid = (SELECT plid FROM portal_login WHERE pmid = v_pmid);
  SELECT currencysymbol INTO v_couponcurrency FROM coupon_master WHERE coupon_number = v_couponno;
  IF (v_membercurrency = v_couponcurrency) THEN
  SELECT amount INTO v_couponamount FROM coupon_master WHERE coupon_number = v_couponno;
  INSERT INTO tmp_temp VALUES ('valid', v_couponamount, v_couponcurrency);
  ELSE
  INSERT INTO tmp_temp VALUES ('Invalid coupon currency for subscription !', 0, '');
  END IF;
  ELSE
  INSERT INTO tmp_temp VALUES ('Invalid coupon code !', 0, '');
  END IF;
  RETURN QUERY SELECT * FROM tmp_temp;
  IF (0 <> 0) THEN
  -- ROLLBACK (removed)
  DROP TABLE IF EXISTS tmp_temp;
  RETURN;
  END IF;
  -- COMMIT (removed)
END;
$$;


--
-- Name: usp_validateuser(character varying, character varying, character varying, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_validateuser(v_loginid character varying DEFAULT ''::character varying, v_username character varying DEFAULT ''::character varying, v_mobileno character varying DEFAULT ''::character varying, INOUT v_intresult integer DEFAULT 0) RETURNS integer
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_username_count INT;
  v_duplicate_mobile INT;
  v_updatedusercount INT;
  v_duplicateemailid_count INT;
BEGIN
  v_intresult := 0;
  v_username_count := 0;
  v_duplicate_mobile := 0;
  v_updatedusercount := 0;
  v_duplicateemailid_count := 0;
  SELECT COUNT(1) INTO v_username_count FROM portal_login WHERE username = v_username;
  SELECT COUNT(1) INTO v_duplicate_mobile FROM portal_login WHERE phone = v_mobileno;
  SELECT COUNT(1) INTO v_updatedusercount FROM portal_login_history WHERE username = v_username;
  SELECT COUNT(1) INTO v_duplicateemailid_count FROM portal_login WHERE loginid = v_loginid;
  IF (COALESCE(v_username_count, 0) > 0) THEN
  v_intresult := 5;
  RETURN;
  ELSE
  IF (COALESCE(v_updatedusercount, 0) > 0) THEN
  v_intresult := 5;
  RETURN;
  ELSE
  IF (COALESCE(v_duplicate_mobile, 0) > 0) THEN
  v_intresult := 6;
  RETURN;
  END IF;
  END IF;
  END IF;
  IF (COALESCE(v_duplicateemailid_count, 0) > 0) THEN
  v_intresult := 2;
  RETURN;
  ELSE
  v_intresult := 1;
  RETURN;
  END IF;
END;
$$;


