  END IF;
  IF EXISTS(SELECT aid FROM area_master WHERE REPLACE(areaname, ' ', '-') = REPLACE(v_sessionareaname, ' ', '-') AND ctid = v_ctid AND cid = v_cid) THEN
  v_areacount := 1;
  END IF;
  v_count := v_statecount + v_citycount + v_areacount;
  IF (v_searchtype = 'c') THEN
  IF EXISTS(SELECT catid FROM product_category WHERE REPLACE(catname, '&', 'and') = v_cat_or_key_name AND catid = v_cat_or_key_id AND catactive = 1) THEN
  IF (v_count = 3) THEN
  v_intresult := 1;
  ELSE
  v_intresult := 0;
  END IF;
  ELSE
  v_intresult := 0;
  END IF;
  END IF;
  IF (v_searchtype = 'k') THEN
  IF EXISTS(SELECT kmid FROM keyword_master WHERE REPLACE(keywordname, '&', 'and') = v_cat_or_key_name AND kmid = v_cat_or_key_id AND kactive = 1) THEN
  IF (v_count = 3) THEN
  v_intresult := 1;
  ELSE
  v_intresult := 0;
