  ELSE
  v_intresult := 0;
  END IF;
  END IF;
  END IF;
  IF (v_sessionstatename <> '' AND v_sessionctname <> '' AND v_sessionareaname = '' AND v_sessionpincode = '') THEN
  IF EXISTS(SELECT sid FROM state WHERE REPLACE(statename, ' ', '-') = REPLACE(v_sessionstatename, ' ', '-') AND cid = v_cid) THEN
  SELECT sid INTO v_sid FROM state WHERE REPLACE(statename, ' ', '-') = REPLACE(v_sessionstatename, ' ', '-') AND cid = v_cid;
  v_statecount := 1;
  END IF;
  IF EXISTS(SELECT ctid FROM city WHERE REPLACE(cityname, ' ', '-') = REPLACE(v_sessionctname, ' ', '-') AND sid = v_sid AND cid = v_cid) THEN
  SELECT ctid INTO v_ctid FROM city WHERE REPLACE(cityname, ' ', '-') = REPLACE(v_sessionctname, ' ', '-') AND sid = v_sid AND cid = v_cid;
  v_citycount := 1;
  END IF;
  v_count := v_statecount + v_citycount;
  IF (v_searchtype = 'c') THEN
  IF EXISTS(SELECT catid FROM product_category WHERE REPLACE(catname, '&', 'and') = v_cat_or_key_name AND catid = v_cat_or_key_id AND catactive = 1) THEN
  IF (v_count = 2) THEN
  v_intresult := 1;
  ELSE
  v_intresult := 0;
  END IF;
  ELSE
  v_intresult := 0;
  END IF;
  END IF;
  IF (v_searchtype = 'k') THEN
  IF EXISTS(SELECT kmid FROM keyword_master WHERE REPLACE(keywordname, '&', 'and') = v_cat_or_key_name AND kmid = v_cat_or_key_id AND kactive = 1) THEN
