--
-- Name: usp_varifylisting_admin(bigint, character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_varifylisting_admin(v_pmid bigint, INOUT v_strresult character varying) RETURNS character varying
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_lwqid BIGINT;
  v_optid BIGINT;
  v_catid text;
  v_subcatid text;
  v_keyid text;
  v_plid BIGINT;
  v_result text;
  v_tempintresult INT;
  v_tempstrresult text;
BEGIN
  -- BEGIN TRAN (removed)
  v_strresult := 'ok';
  v_catid := '';
  v_subcatid := '';
  v_plid := 0;
  v_result := '';
  SELECT lwq_id, optid INTO v_lwqid, v_optid FROM tbl_listingswithqa WHERE v_pmid = pmid;
  UPDATE tbl_listingswithqa SET verify_date = dbo.FUN_GETINDIACURRENTDATE(), status = 1 WHERE lwq_id = v_lwqid;
  UPDATE tbl_operator_report SET totalverified = COALESCE(totalverified, 0) + 1 WHERE optid = v_optid;
  UPDATE portal_master SET isverified = 1 WHERE pmid = v_pmid;
  v_tempintresult := 0;
  v_tempstrresult := '';
  SELECT v_intresult, v_strresult INTO v_tempintresult, v_tempstrresult FROM dbo.usp_setaccuracypercent(v_id => v_pmid, v_accuracy => 1, v_intresult => v_tempintresult, v_strresult => v_tempstrresult, v_mode => 3);
  SELECT plid, catid, subcatid, keyid INTO v_plid, v_catid, v_subcatid, v_keyid FROM portal_master WHERE pmid = v_pmid;
  SELECT v_strresult INTO v_result FROM dbo.usp_merchantcat_subcat_keywordmaster(v_mode => 1, v_plid => v_plid, v_tmcskmid => 0, v_category => v_subcatid, v_subcategory => v_keyid, v_keyword => '', v_strresult => v_result);
  RAISE NOTICE '%', v_result;
  IF (v_tempintresult = 1) THEN
  -- COMMIT (removed)
  RETURN;
  ELSE
  -- ROLLBACK (removed)
  v_strresult := 'Some error occured,Pleas try again !';
  RETURN;
  END IF;
  IF (0 <> 0) THEN
  -- ROLLBACK (removed)
  v_strresult := 'Some error occured,Pleas try again !';
  RETURN;
  END IF;
  -- COMMIT (removed)
END;
$$;


--
-- Name: usp_vendor_master_list(integer, integer, integer, character varying, character varying, integer, character varying, character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_vendor_master_list(v_mode integer DEFAULT 0, v_startrowindex integer DEFAULT 1, v_maxrows integer DEFAULT 100, v_fromdate character varying DEFAULT ''::character varying, v_todate character varying DEFAULT ''::character varying, v_totalcount integer DEFAULT 0, v_searchfield character varying DEFAULT ''::character varying, v_searchvalue character varying DEFAULT ''::character varying) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_minindex INT;
  v_maxindex INT;
  v_query text;
BEGIN
  v_minindex := (v_startrowindex - 1) * v_maxrows + 1;
  v_maxindex := v_startrowindex * v_maxrows;
  IF (v_mode = 0) THEN
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp (ROWNUMBER BIGINT GENERATED BY DEFAULT AS IDENTITY, 
	TVID INT,       
	VENDORNAME VARCHAR(100),      
	VENDORCODE VARCHAR(100),	
	CREATEDATE VARCHAR(100),
	ACTIVE Varchar(100)) ON COMMIT DROP;
  v_query := 'INSERT INTO #TEMP SELECT TV.TVID,TV.VENDORNAME,TV.VENDORCODE,TV.CREATEDATE,
(Case When TV.ACTIVE=1 Then ''Active'' ELSE ''Deactive'' END)
FROM TBL_VENDORS TV  
WHERE 1=1';
  IF ((v_fromdate <> '') AND (v_todate = '')) THEN
  v_query := v_query || ' AND CONVERT(DATE, TV.CREATEDATE, 105) BETWEEN  CONVERT(DATE, ''' || v_fromdate || ''', 105) AND  CONVERT(DATE, DBO.FUN_GETCURRENTDATE(), 105)';
  END IF;
  IF ((v_fromdate = '') AND (v_todate <> '')) THEN
  v_query := v_query || 'AND CONVERT(DATE, TV.CREATEDATE, 105) BETWEEN  CONVERT(DATE, ''' || v_todate || ''', 105) AND  CONVERT(DATE, DBO.FUN_GETCURRENTDATE(), 105)';
  END IF;
  IF ((v_fromdate <> '') AND (v_todate <> '')) THEN
  v_query := v_query || 'AND CONVERT(DATE, TV.CREATEDATE, 105) BETWEEN CONVERT(DATE, ''' || v_fromdate || ''', 105) AND  CONVERT(DATE, ''' || v_todate || ''', 105)';
  END IF;
  IF (v_searchfield = 'VENDORNAME') THEN
  v_query := v_query || ' AND TV.VENDORNAME LIKE ''%' || v_searchvalue || '%'' ';
  END IF;
  IF (v_searchfield = 'VENDORCODE') THEN
  v_query := v_query || ' AND TV.VENDORCODE LIKE ''%' || v_searchvalue || '%'' ';
  END IF;
  v_query := v_query || ' ORDER BY TV.CREATEDATE DESC';
  EXECUTE v_query;
  RAISE NOTICE '%', v_query;
  RETURN QUERY SELECT * FROM tmp_temp WHERE rownumber BETWEEN v_minindex AND v_maxindex;
  SELECT COUNT(rownumber) INTO v_totalcount FROM tmp_temp;
  DROP TABLE IF EXISTS tmp_temp;
  -- SET option (removed)
  END IF;
END;
$$;


--
-- Name: usp_verificationcode(text, text, text, integer, character varying, integer, text); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_verificationcode(v_username text DEFAULT ''::text, v_emailid text DEFAULT ''::text, v_mobileno text DEFAULT ''::text, v_relatedtoid integer DEFAULT 0, v_affiliate character varying DEFAULT ''::character varying, INOUT v_intresult integer DEFAULT 0, INOUT v_verificationcode text DEFAULT ''::text) RETURNS record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_username_count INT;
  v_duplicate_mobile INT;
  v_emailidcount INT;
  v_updatedusercount text;
  v_relatedto varchar(50);
  v_selectrelatedto varchar(100);
BEGIN
  v_intresult := 0;
  v_username_count := 0;
  v_duplicate_mobile := 0;
  v_emailidcount := 0;
  v_updatedusercount := '';
  v_relatedto := '';
  SELECT COUNT(1) INTO v_duplicate_mobile FROM portal_login WHERE phone = v_mobileno;
  SELECT COUNT(1) INTO v_emailidcount FROM portal_login WHERE emailid = v_emailid;
  SELECT kit.type INTO v_relatedto FROM db_affiliate.dbo.member_master AS mm INNER JOIN db_affiliate.dbo.kit_master AS kit ON kit.kid = mm.kid WHERE mm.username = v_affiliate;
  v_selectrelatedto := (CASE WHEN v_relatedtoid = 1 THEN 'Professional' WHEN v_relatedtoid = 2 THEN 'Seller' WHEN v_relatedtoid = 3 THEN 'Service' ELSE '' END);
  IF (COALESCE(v_username_count, 0) > 0) THEN
  v_intresult := 5;
  v_verificationcode := '';
  RETURN;
  ELSE
  IF (COALESCE(v_updatedusercount, 0) > 0) THEN
  v_intresult := 5;
  v_verificationcode := '';
  RETURN;
  ELSE
  IF (COALESCE(v_duplicate_mobile, 0) > 0) THEN
  v_intresult := 6;
  v_verificationcode := '';
  RETURN;
  ELSE
  IF (COALESCE(v_emailidcount, 0) > 0) THEN
  v_intresult := 2;
  v_verificationcode := '';
  RETURN;
  END IF;
  END IF;
  END IF;
  END IF;
  IF (v_relatedto <> v_selectrelatedto) THEN
  v_intresult := 7;
  v_verificationcode := '';
  RETURN;
  ELSE
  v_intresult := 1;
  SELECT CAST(RANDOM() * 899999 AS DECIMAL(6, 0)) + 100000 INTO v_verificationcode;
  RETURN;
  END IF;
END;
$$;


--
-- Name: usp_verificationcode_reseller(text, text, text, integer, text); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_verificationcode_reseller(v_username text DEFAULT ''::text, v_emailid text DEFAULT 'ashish1@awapal.com'::text, v_mobileno text DEFAULT '9582105255'::text, INOUT v_intresult integer DEFAULT 0, INOUT v_verificationcode text DEFAULT ''::text) RETURNS record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_username_count INT;
  v_duplicate_mobile INT;
  v_emailidcount INT;
  v_updatedusercount text;
BEGIN
  v_intresult := 0;
  v_username_count := 0;
  v_duplicate_mobile := 0;
  v_emailidcount := 0;
  v_updatedusercount := '';
  SELECT COUNT(1) INTO v_duplicate_mobile FROM tbl_distributor WHERE phone = v_mobileno;
  SELECT COUNT(1) INTO v_emailidcount FROM tbl_distributor WHERE emailid = v_emailid;
  IF (COALESCE(v_username_count, 0) > 0) THEN
  v_intresult := 5;
  v_verificationcode := '';
  RETURN;
  ELSE
  IF (COALESCE(v_updatedusercount, 0) > 0) THEN
  v_intresult := 5;
  v_verificationcode := '';
  RETURN;
  ELSE
  IF (COALESCE(v_duplicate_mobile, 0) > 0) THEN
  v_intresult := 6;
  v_verificationcode := '';
  RETURN;
  ELSE
  IF (COALESCE(v_emailidcount, 0) > 0) THEN
  v_intresult := 2;
  v_verificationcode := '';
  RETURN;
  ELSE
  v_intresult := 1;
  SELECT CAST(RANDOM() * 899999 AS DECIMAL(6, 0)) + 100000 INTO v_verificationcode;
  RETURN;
  RAISE NOTICE '%', v_verificationcode;
  END IF;
  END IF;
  END IF;
  END IF;
END;
$$;


--
-- Name: usp_verifydealsadmin(bigint, character varying, integer, text); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_verifydealsadmin(v_dealid bigint, INOUT v_strresult character varying, v_type integer DEFAULT 0, v_reason text DEFAULT ''::text) RETURNS character varying
    LANGUAGE plpgsql
    AS $$
BEGIN
  -- BEGIN TRAN (removed)
  v_strresult := 'OK';
  IF (v_type = 1) THEN
  UPDATE tbl_dealswithqa SET verify_date = dbo.fun_getIndiaCurrentDate(), status = 1 WHERE dealid = v_dealid;
  UPDATE portal_deal_master SET approveddate = dbo.FUN_GETINDIACURRENTDATE(), verify = 1, active = 1 WHERE dealid = v_dealid;
  END IF;
  IF (v_type = 2) THEN
  UPDATE tbl_dealswithqa SET isdeleted = 1, status = 0 WHERE dealid = v_dealid;
  UPDATE portal_deal_master SET rejectdate = dbo.FUN_GETINDIACURRENTDATE(), verify = 2, rejectreason = v_reason, active = 0 WHERE dealid = v_dealid;
  END IF;
  IF (0 <> 0) THEN
