--
-- Name: usp_viewincrement(integer, character varying, character varying, character varying, character varying, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_viewincrement(v_blogid integer, v_ip character varying, v_ipcountry character varying, v_ipstate character varying, v_ipcity character varying, INOUT v_intresult integer) RETURNS integer
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_previoustime timestamp;
  v_difference int;
  v_current timestamp;
BEGIN
  v_current := CURRENT_TIMESTAMP;
  v_intresult := 1;
  IF NOT EXISTS(SELECT ipid FROM tbl_blogvisitip WHERE blogid = v_blogid AND ip = v_ip) THEN
  INSERT INTO tbl_blogvisitip (blogid, ip, viewtime, ipcountry, ipstate, ipcity) VALUES (v_blogid, v_ip, v_current, v_ipcountry, v_ipstate, v_ipcity);
  UPDATE tbl_blogmaster SET visits = COALESCE(visits, 0) + 1 WHERE status = 1 AND publishstatus = 1 AND draftstatus = 0 AND blogid = v_blogid;
  v_intresult := 1;
  ELSE
  SELECT viewtime INTO v_previoustime FROM tbl_blogvisitip WHERE blogid = v_blogid AND ip = v_ip;
  SELECT CAST(EXTRACT(epoch FROM CAST(CAST(v_current AS TIMESTAMP) AS TIMESTAMP) - CAST(CAST(v_previoustime AS TIMESTAMP) AS TIMESTAMP)) / 3600 AS BIGINT) INTO v_difference;
  IF (v_difference >= 24) THEN
  INSERT INTO tbl_blogvisitip (blogid, ip, viewtime, ipcountry, ipstate, ipcity) VALUES (v_blogid, v_ip, v_current, v_ipcountry, v_ipstate, v_ipcity);
  UPDATE tbl_blogmaster SET visits = COALESCE(visits, 0) + 1 WHERE status = 1 AND publishstatus = 1 AND draftstatus = 0 AND blogid = v_blogid;
  v_intresult := 2;
  END IF;
  END IF;
END;
$$;


--
-- Name: usp_visitlogsonperticulardate(integer, integer, character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_visitlogsonperticulardate(v_startrowindex integer, v_maxrows integer, v_singledate character varying) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_total int;
  v_ttlssns int;
  v_ttlpagesvisit int;
BEGIN
  -- SET option (removed)
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp (rowNumber int GENERATED BY DEFAULT AS IDENTITY,
country varchar(100),
state varchar(100),
cityname varchar(100),
ipaddress varchar(100),
ssncount bigint,
pagesvisitcnt bigint) ON COMMIT DROP;
  INSERT INTO tmp_temp SELECT country, state, city, ipaddress, COALESCE(sessioncount, 0), COALESCE(pagecount, 0) FROM tbl_visitorhistory WHERE CAST(date AS DATE) = v_singledate ORDER BY date DESC NULLS LAST;
  RETURN QUERY SELECT * FROM tmp_temp WHERE rownumber BETWEEN v_startrowindex AND v_maxrows;
  SELECT COUNT(1) INTO v_total FROM tmp_temp;
  SELECT SUM(ssncount) INTO v_ttlssns FROM tmp_temp WHERE rownumber BETWEEN v_startrowindex AND v_maxrows;
  SELECT SUM(pagesvisitcnt) INTO v_ttlpagesvisit FROM tmp_temp WHERE rownumber BETWEEN v_startrowindex AND v_maxrows;
  RETURN QUERY SELECT v_total AS total, v_ttlssns AS ttlssns, v_ttlpagesvisit AS ttlpages;
  DROP TABLE IF EXISTS tmp_temp;
  -- SET option (removed)
END;
$$;


