  ELSE
  IF (v_mobileno <> '') THEN
  IF EXISTS(SELECT 1 FROM customer_login_temp WHERE username = v_username AND active = 0) THEN
  UPDATE customer_login_temp SET doc = dbo.FUN_GETCURRENTDATE(), password = v_password, emailid = v_loginid, phone = v_mobileno, sponserid = v_sponsorids, placementid = v_placementids, side = v_side, imagename = v_imagename, designation = v_desigantion, title = v_title, sp_firstname = v_firstname, sp_lastname = v_lastname, cid = v_cid, sid = v_sid, ctid = v_ctid WHERE username = v_username;
