--
-- Name: usp_visitor_signup(character varying, character varying, integer, integer, bigint, character varying, character varying, character varying, integer, character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_visitor_signup(v_loginid character varying DEFAULT ''::character varying, v_password character varying DEFAULT ''::character varying, INOUT v_intresult integer DEFAULT NULL::integer, v_mode integer DEFAULT 0, v_qpayregno bigint DEFAULT 0, v_currencysymbol character varying DEFAULT ''::character varying, v_country character varying DEFAULT ''::character varying, v_username character varying DEFAULT ''::character varying, INOUT v_plid integer DEFAULT NULL::integer, v_introrefid character varying DEFAULT ''::character varying) RETURNS record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_err int;
  v_cid bigint;
  v_plidref int;
BEGIN
  v_intresult := 0;
  IF EXISTS(SELECT plid FROM portal_login WHERE refral_id = v_introrefid) THEN
  SELECT plid INTO v_plidref FROM portal_login WHERE refral_id = v_introrefid;
  ELSE
  v_plidref := 0;
  END IF;
  IF EXISTS(SELECT COALESCE(cid, '231') FROM country WHERE countryname = v_country AND cactive = 1) THEN
  SELECT COALESCE(cid, '231') INTO v_cid FROM country WHERE countryname = v_country AND cactive = 1;
  ELSE
  v_cid := 231;
  END IF;
  IF (v_mode = 0) THEN
  IF NOT EXISTS(SELECT loginid FROM portal_login WHERE loginid = v_loginid) THEN
  INSERT INTO portal_login (loginid, password, active, doc, currencysymbol, cid, intro_refid) VALUES (v_loginid, v_password, 0, GETUTCDATE() + INTERVAL '330 MI', v_currencysymbol, v_cid, v_plidref);
  v_plid := IDENT_CURRENT('Portal_Login');
  INSERT INTO ewallet (plid, amount, active, currencysymbol) VALUES (v_plid, 0, 1, v_currencysymbol);
  v_intresult := 1;
  ELSE
