  PERFORM dbo.ims_usp_createcustomeraddress(v_id => 0, v_pincode => v_pincode, v_shortaddress => v_address, v_landmark => '', v_countryid => 0, v_cityname => v_ctname, v_countryname => v_country, v_phoneno1 => v_mobileno, v_phoneno2 => '', v_email1 => v_loginid, v_remarks => '', v_addresstype => 'PermanentAddress', v_touserid => v_maxplid, v_tousertype => 'Customer', v_addresstype1 => 1, v_cname => '', v_ipaddress => v_ipaddress, v_success => 0, v_message => '', v_sqlresult => '');
  END IF;
  IF (v_intresult = 0) THEN
  -- ROLLBACK (removed)
  RETURN;
  END IF;
  UPDATE tbl_customerlogin SET usersource = 2 WHERE clid = v_plid;
  ELSE
  UPDATE tbl_customerlogin SET did = v_distributerid WHERE phone = v_mobileno;
  END IF;
  END IF;
  EXCEPTION WHEN OTHERS THEN
  v_intresult := 0;
  RETURN;
  END;
  v_intresult := 1;
  ELSE
  IF EXISTS(SELECT 1 FROM customer_login_temp WHERE phone = v_mobileno AND active = 0) THEN
  UPDATE customer_login_temp SET doc = dbo.FUN_GETCURRENTDATE(), password = v_password, emailid = v_loginid, phone = v_mobileno, sponserid = v_sponsorids, placementid = v_placementids, side = v_side, imagename = v_imagename, designation = v_desigantion, title = v_title, sp_firstname = v_firstname, sp_lastname = v_lastname, cid = v_cid, sid = v_sid, ctid = v_ctid WHERE phone = v_mobileno;
  v_intresult := 1;
  ELSE
  v_intresult := 2;
  END IF;
  SELECT pltid INTO v_plid FROM customer_login_temp WHERE phone = v_mobileno;
  END IF;
  RAISE NOTICE '%', v_intresult;
  END IF;
  END IF;
  IF (v_err <> 0) THEN
  v_intresult := 0;
  -- ROLLBACK (removed)
  RETURN;
  END IF;
END;
$$;


