-- Name: usp_visitor_signup_temp_member_mobile(character varying, character varying, character varying, integer, integer, bigint, character varying, character varying, integer, character varying, character varying, text, integer, character varying, integer, character varying, character varying, character varying, character varying, text, text, integer, integer, text, text, text, text, integer, integer, integer, integer, text, text, text); Type: FUNCTION; Schema: dbo; Owner: -
