CREATE FUNCTION dbo.usp_visitor_signup_temp_member_mobile(v_loginid character varying DEFAULT ''::character varying, v_password character varying DEFAULT ''::character varying, v_username character varying DEFAULT ''::character varying, INOUT v_intresult integer DEFAULT 0, v_mode integer DEFAULT 0, v_qpayregno bigint DEFAULT 0, v_currencysymbol character varying DEFAULT ''::character varying, v_country character varying DEFAULT ''::character varying, INOUT v_plid integer DEFAULT 0, v_referrelcode character varying DEFAULT ''::character varying, v_ipaddress character varying DEFAULT ''::character varying, v_mobileno text DEFAULT ''::text, v_distributerid integer DEFAULT 0, v_ref_username character varying DEFAULT ''::character varying, v_ref_regno integer DEFAULT 0, v_address character varying DEFAULT ''::character varying, v_statename character varying DEFAULT ''::character varying, v_ctname character varying DEFAULT ''::character varying, v_pincode character varying DEFAULT ''::character varying, v_sponsorids text DEFAULT ''::text, v_placementids text DEFAULT ''::text, v_side integer DEFAULT 0, v_title integer DEFAULT 0, v_firstname text DEFAULT ''::text, v_lastname text DEFAULT ''::text, v_desigantion text DEFAULT ''::text, v_imagename text DEFAULT ''::text, v_modeforjoining integer DEFAULT 0, v_cid integer DEFAULT 0, v_sid integer DEFAULT 0, v_ctid integer DEFAULT 0, v_atc_walletaddress text DEFAULT ''::text, v_cityname text DEFAULT ''::text, v_atcuserid text DEFAULT ''::text) RETURNS record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_err INT;
  v_plidref INT;
  v_spounsertype INT;
  v_username_count INT;
  v_duplicate_mobile INT;
  v_updatedusercount INT;
  v_duplicateemailid_count INT;
  v_chars char(88);
  v_referalcode text;
  v_intcontinue INT;
  v_userid text;
  v_maxplid INT;
  v_outputparam text;
BEGIN
  v_modeforjoining := 1;
  v_spounsertype := 0;
  v_placementids := v_sponsorids;
  v_intresult := 0;
  v_username_count := 0;
  v_duplicate_mobile := 0;
  v_updatedusercount := 0;
  v_duplicateemailid_count := 0;
  SELECT COUNT(1) INTO v_duplicate_mobile FROM tbl_customerlogin WHERE phone = v_mobileno AND did = v_distributerid AND reference_username = v_ref_username AND reference_regno = v_ref_regno;
  IF (v_plid <> 0) THEN
  SELECT COUNT(1) INTO v_updatedusercount FROM tbl_customerloginhistory WHERE plid = v_plid;
  END IF;
  IF (v_loginid <> '') THEN
  SELECT COUNT(1) INTO v_duplicateemailid_count FROM tbl_customerlogin WHERE emailid = v_loginid AND did = v_distributerid AND reference_username = v_ref_username AND reference_regno = v_ref_regno;
  END IF;
  IF (COALESCE(v_username_count, 0) > 0) THEN
  v_intresult := 5;
  RETURN;
  ELSE
  IF (COALESCE(v_updatedusercount, 0) > 0) THEN
  v_intresult := 5;
  RETURN;
  ELSE
  IF (COALESCE(v_duplicate_mobile, 0) > 0) THEN
  v_intresult := 6;
  RETURN;
  END IF;
  END IF;
  END IF;
  IF (COALESCE(v_duplicateemailid_count, 0) > 0) THEN
  v_intresult := 2;
  RETURN;
  ELSE
  IF EXISTS(SELECT clid FROM tbl_customerlogin WHERE username = v_referrelcode AND COALESCE(v_referrelcode, '') <> '') THEN
  SELECT clid, loginid, loginid, COALESCE(communityside, 3) INTO v_plidref, v_sponsorids, v_placementids, v_side FROM tbl_customerlogin WHERE username = v_referrelcode;
  ELSE
  IF (v_sponsorids <> '' AND v_side > 0) THEN
  v_referrelcode := v_sponsorids;
  IF EXISTS(SELECT 1 FROM tbl_customerlogin WHERE username = v_referrelcode AND COALESCE(v_referrelcode, '') <> '') THEN
  SELECT clid, loginid, loginid INTO v_plidref, v_sponsorids, v_placementids FROM tbl_customerlogin WHERE username = v_referrelcode;
  END IF;
  ELSE
  SELECT loginid, clid, loginid, COALESCE(communityside, 3) INTO v_sponsorids, v_plidref, v_placementids, v_side FROM tbl_customerlogin WHERE clid = 1;
  END IF;
  END IF;
  v_spounsertype := 0;
