  IF (v_mode = 0) THEN
  IF NOT EXISTS(SELECT 1 FROM customer_login_temp WHERE phone = v_mobileno AND did = v_distributerid AND active = 1) AND NOT EXISTS(SELECT 1 FROM tbl_customerlogin WHERE phone = v_mobileno AND did = v_distributerid AND reference_username = v_ref_username AND reference_regno = v_ref_regno) THEN
  DROP TABLE IF EXISTS tmp_tb1;
  CREATE TEMP TABLE tmp_tb1 ON COMMIT DROP AS SELECT ROW_NUMBER() OVER (ORDER BY item NULLS FIRST) AS row, item FROM dbo.SPLITSTRING(v_username, '');
  v_referalcode := '';
  v_intcontinue := 0;
  v_chars := N'0123456789';
  WHILE (v_intcontinue = 0) LOOP
  v_referalcode := SUBSTRING(v_chars FROM CAST((RANDOM() * LENGTH(CAST(v_chars AS TEXT))) AS INT) + 1 FOR 1) || SUBSTRING(v_chars FROM CAST((RANDOM() * LENGTH(CAST(v_chars AS TEXT))) AS INT) + 1 FOR 1) || SUBSTRING(v_chars FROM CAST((RANDOM() * LENGTH(CAST(v_chars AS TEXT))) AS INT) + 1 FOR 1) || SUBSTRING(v_chars FROM CAST((RANDOM() * LENGTH(CAST(v_chars AS TEXT))) AS INT) + 1 FOR 1) || SUBSTRING(v_chars FROM CAST((RANDOM() * LENGTH(CAST(v_chars AS TEXT))) AS INT) + 1 FOR 1) || SUBSTRING(v_chars FROM CAST((RANDOM() * LENGTH(CAST(v_chars AS TEXT))) AS INT) + 1 FOR 1);
  IF EXISTS(SELECT 1 FROM customer_login_temp WHERE refral_id = v_referalcode) THEN
  v_intcontinue := 0;
  ELSE
  IF (LENGTH(CAST(v_referalcode AS TEXT)) < 6) THEN
  v_intcontinue := 0;
  ELSE
  IF ((SELECT SUBSTRING(v_referalcode FROM 1 FOR 1)) <= 0) THEN
  v_intcontinue := 0;
  ELSE
  v_intcontinue := 1;
  END IF;
  END IF;
  END IF;
  END LOOP;
  v_userid := '';
  SELECT 0 INTO v_intcontinue;
  v_chars := N'8123456789';
  WHILE (v_intcontinue = 0) LOOP
  v_userid := SUBSTRING(v_chars FROM CAST((RANDOM() * LENGTH(CAST(v_chars AS TEXT))) AS INT) + 1 FOR 1) || SUBSTRING(v_chars FROM CAST((RANDOM() * LENGTH(CAST(v_chars AS TEXT))) AS INT) + 1 FOR 1) || SUBSTRING(v_chars FROM CAST((RANDOM() * LENGTH(CAST(v_chars AS TEXT))) AS INT) + 1 FOR 1) || SUBSTRING(v_chars FROM CAST((RANDOM() * LENGTH(CAST(v_chars AS TEXT))) AS INT) + 1 FOR 1) || SUBSTRING(v_chars FROM CAST((RANDOM() * LENGTH(CAST(v_chars AS TEXT))) AS INT) + 1 FOR 1) || SUBSTRING(v_chars FROM CAST((RANDOM() * LENGTH(CAST(v_chars AS TEXT))) AS INT) + 1 FOR 1) || SUBSTRING(v_chars FROM CAST((RANDOM() * LENGTH(CAST(v_chars AS TEXT))) AS INT) + 1 FOR 1) || SUBSTRING(v_chars FROM CAST((RANDOM() * LENGTH(CAST(v_chars AS TEXT))) AS INT) + 1 FOR 1);
  IF EXISTS(SELECT 1 FROM customer_login_temp WHERE userid = v_userid) THEN
  v_intcontinue := 0;
  ELSE
  IF (LENGTH(CAST(v_userid AS TEXT)) < 8) THEN
  v_intcontinue := 0;
  ELSE
  IF ((SELECT SUBSTRING(v_userid FROM 1 FOR 1)) <= 0) THEN
  v_intcontinue := 0;
  ELSE
  v_intcontinue := 1;
  END IF;
  END IF;
  END IF;
  END LOOP;
  IF NOT EXISTS(SELECT 1 FROM customer_login_temp WHERE phone = v_mobileno AND reference_regno = v_ref_regno AND did = v_distributerid AND active = 1) THEN
  INSERT INTO customer_login_temp (loginid, password, active, doc, currencysymbol, cid, intro_refid, username, ipaddress, refral_id, phone, sponserid, placementid, side, imagename, designation, title, sp_firstname, sp_lastname, spounsertype, userid, emailid, sid, ctid, did, reference_username, reference_regno) VALUES (v_userid, v_password, 0, dbo.FUN_GETCURRENTDATE(), v_currencysymbol, v_cid, v_plidref, v_username, v_ipaddress, v_referalcode, v_mobileno, v_sponsorids, v_placementids, v_side, v_imagename, v_desigantion, v_title, (CASE WHEN COALESCE(v_firstname, '') = '' THEN (SELECT item FROM tmp_tb1 WHERE row = 1) ELSE v_firstname END), (CASE WHEN COALESCE(v_lastname, '') = '' THEN (SELECT item FROM tmp_tb1 WHERE row = 2) ELSE v_lastname END), v_spounsertype, v_userid, v_loginid, v_sid, v_ctid, v_distributerid, v_ref_username, v_ref_regno);
  DROP TABLE IF EXISTS tmp_tb1;
  v_plid := IDENT_CURRENT('CUSTOMER_LOGIN_TEMP');
  ELSE
  UPDATE customer_login_temp SET did = v_distributerid WHERE phone = v_mobileno AND reference_regno = v_ref_regno;
  SELECT pltid INTO v_plid FROM customer_login_temp WHERE phone = v_mobileno AND reference_regno = v_ref_regno;
  END IF;
  v_maxplid := 0;
  v_outputparam := '';
  BEGIN
  IF (v_modeforjoining = 1 OR v_modeforjoining = 2) THEN
  IF NOT EXISTS(SELECT 1 FROM tbl_customerlogin WHERE did = v_distributerid AND phone = v_mobileno) THEN
  SELECT v_intresult, v_maxplid INTO v_intresult, v_maxplid FROM dbo.usp_customerregister_mobile(v_plid => v_plid, v_intresult => v_intresult, v_maxplid => v_maxplid, v_distributerid => v_distributerid, v_ref_username => v_ref_username, v_ref_regno => v_ref_regno);
  IF (v_intresult = 0) THEN
  -- ROLLBACK (removed)
  RETURN;
  END IF;
  UPDATE tbl_customerlogin SET usersource = 2 WHERE clid = v_plid;
  ELSE
  UPDATE tbl_customerlogin SET did = v_distributerid WHERE phone = v_mobileno;
  END IF;
  END IF;
  EXCEPTION WHEN OTHERS THEN
  v_intresult := 0;
  RETURN;
  END;
  v_intresult := 1;
  ELSE
  IF EXISTS(SELECT 1 FROM customer_login_temp WHERE phone = v_mobileno AND active = 0) THEN
  UPDATE customer_login_temp SET doc = dbo.FUN_GETCURRENTDATE(), password = v_password, emailid = v_loginid, phone = v_mobileno, sponserid = v_sponsorids, placementid = v_placementids, side = v_side, imagename = v_imagename, designation = v_desigantion, title = v_title, sp_firstname = v_firstname, sp_lastname = v_lastname, cid = v_cid, sid = v_sid, ctid = v_ctid WHERE phone = v_mobileno;
