  ELSE
  v_intresult := 2;
  END IF;
  SELECT pltid INTO v_plid FROM customer_login_temp WHERE phone = v_mobileno;
  END IF;
  END IF;
  END IF;
  IF (v_err <> 0) THEN
  v_intresult := 0;
  -- ROLLBACK (removed)
  RETURN;
  END IF;
END;
$$;


