CREATE FUNCTION dbo.usp_visitor_signup_temp_reseller(v_loginid character varying DEFAULT 'anubhav@eblaa.com'::character varying, v_password character varying DEFAULT '123'::character varying, v_username character varying DEFAULT ''::character varying, v_intresult integer DEFAULT 0, v_mode integer DEFAULT 0, v_qpayregno bigint DEFAULT 0, v_currencysymbol character varying DEFAULT 'Rs'::character varying, v_country character varying DEFAULT 'India'::character varying, v_plid integer DEFAULT 0, v_referrelcode character varying DEFAULT 'Root'::character varying, v_ipaddress character varying DEFAULT '::1'::character varying, v_mobileno text DEFAULT '9971676527'::text, v_source character varying DEFAULT 'Direct'::character varying, v_sponsorids text DEFAULT ''::text, v_placementids text DEFAULT ''::text, v_side integer DEFAULT 0, v_title integer DEFAULT 0, v_firstname text DEFAULT ''::text, v_lastname text DEFAULT ''::text, v_desigantion text DEFAULT ''::text, v_imagename text DEFAULT ''::text, v_modeforjoining integer DEFAULT 0, v_cid integer DEFAULT 0, v_sid integer DEFAULT 0, v_ctid integer DEFAULT 0, v_atc_walletaddress text DEFAULT ''::text, v_cityname text DEFAULT ''::text, v_atcuserid text DEFAULT ''::text) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_err INT;
  v_plidref INT;
  v_spounsertype INT;
  v_sourceid Int;
  v_username_count INT;
  v_duplicate_mobile INT;
