  v_intresult := 5;
  RETURN;
  ELSE
  IF (COALESCE(v_updatedusercount, 0) > 0) THEN
  v_intresult := 5;
  RETURN;
  END IF;
  END IF;
  IF (COALESCE(v_duplicateemailid_count, 0) > 0) THEN
  v_intresult := 2;
  RETURN;
  ELSE
  IF EXISTS(SELECT 1 FROM portal_login WHERE username = v_referrelcode AND COALESCE(v_referrelcode, '') <> '' AND v_source = 'Merchant') THEN
  SELECT did, loginid, loginid, COALESCE(communityside, 3) INTO v_plidref, v_sponsorids, v_placementids, v_side FROM distributor_login WHERE username = v_referrelcode;
  END IF;
