  SELECT emp_id, emp_loginid, emp_loginid, 3 INTO v_plidref, v_sponsorids, v_placementids, v_side FROM tbl_employee_master WHERE emp_loginid = v_referrelcode;
  END IF;
  IF EXISTS(SELECT 1 FROM tbl_customerlogin WHERE username = v_referrelcode AND COALESCE(v_referrelcode, '') <> '' AND v_source = 'Customer') THEN
  SELECT loginid, loginid, loginid, 3 INTO v_plidref, v_sponsorids, v_placementids, v_side FROM tbl_customerlogin WHERE username = v_referrelcode;
  ELSE
  v_source := 'Direct';
  SELECT id INTO v_sourceid FROM tbl_trafficsource WHERE name = v_source;
  SELECT loginid, did, loginid, COALESCE(communityside, 3) INTO v_sponsorids, v_plidref, v_placementids, v_side FROM tbl_distributor WHERE did = 1;
  END IF;
  ELSE
  v_source := 'Direct';
  SELECT id INTO v_sourceid FROM tbl_trafficsource WHERE name = v_source;
  SELECT loginid, did, loginid, COALESCE(communityside, 3) INTO v_sponsorids, v_plidref, v_placementids, v_side FROM tbl_distributor WHERE did = 1;
  END IF;
  END IF;
