  v_spounsertype := 0;
  ELSE
  SELECT v_sourceid INTO v_spounsertype;
  END IF;
  IF EXISTS(SELECT COALESCE(cid, '96') FROM country WHERE countryname = v_country AND cactive = 1) THEN
  IF (v_cid = 0) THEN
  SELECT COALESCE(cid, '96') INTO v_cid FROM country WHERE countryname = v_country AND cactive = 1;
  END IF;
  ELSE
  IF (v_cid = 0) THEN
  v_cid := 96;
  END IF;
  END IF;
  IF (v_mode = 0) THEN
  IF NOT EXISTS(SELECT 1 FROM distributor_login_temp WHERE emailid = v_loginid) AND NOT EXISTS(SELECT 1 FROM tbl_distributor WHERE emailid = v_loginid) THEN
  DROP TABLE IF EXISTS tmp_tb1;
  CREATE TEMP TABLE tmp_tb1 ON COMMIT DROP AS SELECT ROW_NUMBER() OVER (ORDER BY item NULLS FIRST) AS row, item FROM dbo.SPLITSTRING(v_username, '');
  v_referalcode := '';
