  IF EXISTS(SELECT 1 FROM distributor_login_temp WHERE refral_id = v_referalcode) THEN
  v_intcontinue := 0;
  ELSE
  IF (LENGTH(CAST(v_referalcode AS TEXT)) < 6) THEN
  v_intcontinue := 0;
  ELSE
  IF ((SELECT SUBSTRING(v_referalcode FROM 1 FOR 1)) <= 0) THEN
  v_intcontinue := 0;
  ELSE
  v_intcontinue := 1;
  END IF;
  END IF;
  END IF;
  END LOOP;
  v_userid := '';
  SELECT 0 INTO v_intcontinue;
  v_chars := N'8123456789';
  WHILE (v_intcontinue = 0) LOOP
  v_userid := SUBSTRING(v_chars FROM CAST((RANDOM() * LENGTH(CAST(v_chars AS TEXT))) AS INT) + 1 FOR 1) || SUBSTRING(v_chars FROM CAST((RANDOM() * LENGTH(CAST(v_chars AS TEXT))) AS INT) + 1 FOR 1) || SUBSTRING(v_chars FROM CAST((RANDOM() * LENGTH(CAST(v_chars AS TEXT))) AS INT) + 1 FOR 1) || SUBSTRING(v_chars FROM CAST((RANDOM() * LENGTH(CAST(v_chars AS TEXT))) AS INT) + 1 FOR 1) || SUBSTRING(v_chars FROM CAST((RANDOM() * LENGTH(CAST(v_chars AS TEXT))) AS INT) + 1 FOR 1) || SUBSTRING(v_chars FROM CAST((RANDOM() * LENGTH(CAST(v_chars AS TEXT))) AS INT) + 1 FOR 1) || SUBSTRING(v_chars FROM CAST((RANDOM() * LENGTH(CAST(v_chars AS TEXT))) AS INT) + 1 FOR 1) || SUBSTRING(v_chars FROM CAST((RANDOM() * LENGTH(CAST(v_chars AS TEXT))) AS INT) + 1 FOR 1);
  IF EXISTS(SELECT 1 FROM distributor_login_temp WHERE userid = v_userid) THEN
  v_intcontinue := 0;
  ELSE
  IF (LENGTH(CAST(v_userid AS TEXT)) < 8) THEN
  v_intcontinue := 0;
  ELSE
  IF ((SELECT SUBSTRING(v_userid FROM 1 FOR 1)) <= 0) THEN
  v_intcontinue := 0;
  ELSE
  v_intcontinue := 1;
  END IF;
  END IF;
  END IF;
  END LOOP;
  IF (v_username = '') THEN
  v_username := v_userid;
  END IF;
  INSERT INTO distributor_login_temp (loginid, password, active, doc, currencysymbol, cid, intro_refid, username, ipaddress, refral_id, phone, sponserid, placementid, side, imagename, designation, title, sp_firstname, sp_lastname, spounsertype, userid, emailid, sid, ctid, sourceid) VALUES (v_userid, v_password, 0, dbo.FUN_GETCURRENTDATE(), v_currencysymbol, v_cid, v_plidref, v_username, v_ipaddress, v_referalcode, v_mobileno, v_sponsorids, v_placementids, v_side, v_imagename, v_desigantion, v_title, (CASE WHEN v_firstname = '' THEN (SELECT item FROM tmp_tb1 WHERE row = 1) ELSE v_firstname END), (CASE WHEN v_lastname = '' THEN (SELECT item FROM tmp_tb1 WHERE row = 2) ELSE v_lastname END), v_spounsertype, v_userid, v_loginid, v_sid, v_ctid, v_sourceid);
