  BEGIN
  IF (v_modeforjoining = 1 OR v_modeforjoining = 2) THEN
  SELECT v_intresult, v_maxplid INTO v_intresult, v_maxplid FROM dbo.usp_updatevisitor(v_plid => v_plid, v_intresult => v_intresult, v_maxplid => v_maxplid);
  IF (v_intresult = 0) THEN
  -- ROLLBACK (removed)
  RETURN;
  END IF;
  UPDATE tbl_distributor SET usersource = 2 WHERE did = v_plid;
  END IF;
  EXCEPTION WHEN OTHERS THEN
  v_intresult := 0;
  RETURN;
  END;
  v_intresult := 1;
  ELSE
  IF EXISTS(SELECT 1 FROM distributor_login_temp WHERE emailid = v_loginid AND active = 0) THEN
  UPDATE distributor_login_temp SET doc = dbo.FUN_GETCURRENTDATE(), password = v_password, emailid = v_loginid, phone = v_mobileno, sponserid = v_sponsorids, placementid = v_placementids, side = v_side, imagename = v_imagename, designation = v_desigantion, title = v_title, sp_firstname = v_firstname, sp_lastname = v_lastname, cid = v_cid, sid = v_sid, ctid = v_ctid WHERE phone = v_mobileno;
  v_intresult := 1;
  ELSE
  RETURN QUERY SELECT 1;
  v_intresult := 2;
  END IF;
  END IF;
  SELECT pltid INTO v_plid FROM distributor_login_temp WHERE phone = v_mobileno;
  END IF;
  END IF;
  IF (v_err <> 0) THEN
  v_intresult := 0;
  -- ROLLBACK (removed)
  RETURN;
  END IF;
END;
$$;


--
-- Name: usp_visitor_signup_temp_sponsor(character varying, character varying, character varying, integer, integer, bigint, character varying, character varying, integer, character varying, character varying, character varying, character varying, character varying, character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_visitor_signup_temp_sponsor(v_loginid character varying DEFAULT ''::character varying, v_password character varying DEFAULT ''::character varying, v_username character varying DEFAULT ''::character varying, INOUT v_intresult integer DEFAULT NULL::integer, v_mode integer DEFAULT 0, v_qpayregno bigint DEFAULT 0, v_currencysymbol character varying DEFAULT ''::character varying, v_country character varying DEFAULT ''::character varying, INOUT v_plid integer DEFAULT NULL::integer, v_introrefid character varying DEFAULT ''::character varying, v_ipaddress character varying DEFAULT ''::character varying, v_sp_firstname character varying DEFAULT ''::character varying, v_sp_lastname character varying DEFAULT ''::character varying, v_sp_url character varying DEFAULT ''::character varying, v_title character varying DEFAULT ''::character varying) RETURNS record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_err int;
  v_cid bigint;
  v_plidref int;
BEGIN
  v_intresult := 0;
  IF EXISTS(SELECT plid FROM portal_login WHERE refral_id = v_introrefid) THEN
  SELECT plid INTO v_plidref FROM portal_login WHERE refral_id = v_introrefid;
  ELSE
  v_plidref := 0;
  END IF;
  IF EXISTS(SELECT COALESCE(cid, '231') FROM country WHERE countryname = v_country AND cactive = 1) THEN
  SELECT COALESCE(cid, '231') INTO v_cid FROM country WHERE countryname = v_country AND cactive = 1;
  ELSE
  v_cid := 231;
  END IF;
  IF (v_mode = 0) THEN
  IF NOT EXISTS(SELECT loginid FROM portal_login_temp WHERE loginid = v_loginid) AND NOT EXISTS(SELECT loginid FROM portal_login WHERE loginid = v_loginid) THEN
  INSERT INTO portal_login_temp (loginid, password, active, doc, currencysymbol, cid, intro_refid, username, ipaddress, sp_firstname, sp_lastname, sp_url, title) VALUES (v_loginid, v_password, 0, dbo.fun_getCurrentDate(), v_currencysymbol, v_cid, v_plidref, v_username, v_ipaddress, v_sp_firstname, v_sp_lastname, v_sp_url, v_title);
  v_plid := IDENT_CURRENT('Portal_Login_temp');
  v_intresult := 1;
  ELSE
  UPDATE portal_login_temp SET doc = dbo.fun_getCurrentDate(), password = v_password, username = v_username WHERE loginid = v_loginid;
  SELECT pltid INTO v_plid FROM portal_login_temp WHERE loginid = v_loginid;
  v_intresult := 1;
  END IF;
  END IF;
  IF (v_err <> 0) THEN
  v_intresult := 0;
  -- ROLLBACK (removed)
  RETURN;
  END IF;
END;
$$;


--
-- Name: usp_visitor_statics(bigint); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_visitor_statics(v_plid bigint DEFAULT 1) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_currentdate timestamp;
  v_pre_date timestamp;
  v_register_user int;
  v_active_user int;
  v_referral_user int;
  v_sno bigint;
  v_loginid Varchar(100);
BEGIN
  v_loginid := '';
  SELECT loginid INTO v_loginid FROM member_master WHERE plid = v_plid;
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp (SRNO INT,
DATE Int,
DateWithMonth varchar(200),
REGISTER_USER INT,
ACTIVE_USER INT,
REFERRAL_USER INT,
Predate timestamp) ON COMMIT DROP;
  SELECT CURRENT_TIMESTAMP, GETUTCDATE() + INTERVAL '330 MINUTE' + INTERVAL '-7 DAY' INTO v_currentdate, v_pre_date;
  v_sno := 1;
  WHILE (v_pre_date <= v_currentdate) LOOP
  SELECT COUNT(1) INTO v_register_user FROM member_master WHERE TO_DATE(regdate, 'DD-MM-YYYY') = TO_DATE(v_pre_date, 'DD-MM-YYYY') AND introregno = v_plid;
  SELECT COUNT(1) INTO v_active_user FROM member_master WHERE TO_DATE(doc, 'DD-MM-YYYY') = TO_DATE(v_pre_date, 'DD-MM-YYYY') AND introregno = v_plid;
  SELECT COUNT(DISTINCT loginid) INTO v_referral_user FROM FUN_ALL_DOWNLINE_MEMBERLIST('' || v_loginid || '', 0) WHERE TO_DATE(regdate, 'DD-MM-YYYY') = TO_DATE(v_pre_date, 'DD-MM-YYYY');
  INSERT INTO tmp_temp VALUES (v_sno, EXTRACT(DAY FROM v_pre_date), TO_CHAR(CAST(v_pre_date AS TIMESTAMP), 'TMMonth') || '  ' || CAST(EXTRACT(DAY FROM v_pre_date) AS VARCHAR), v_register_user, v_active_user, v_referral_user, v_pre_date);
  v_pre_date := v_pre_date + 1;
  v_sno := v_sno + 1;
  END LOOP;
  RETURN QUERY SELECT * FROM tmp_temp ORDER BY predate ASC NULLS FIRST;
  DROP TABLE IF EXISTS tmp_temp;
  IF (0 <> 0) THEN
  -- ROLLBACK (removed)
  DROP TABLE IF EXISTS tmp_temp;
  RETURN;
  END IF;
END;
$$;


--
-- Name: usp_visitorsearch(integer, integer, character varying, boolean, date, date, character varying, character varying, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_visitorsearch(v_startrowindex integer, v_maxrows integer, v_orderbyfield character varying, v_asc boolean, v_todate date DEFAULT NULL::date, v_fromdate date DEFAULT NULL::date, v_searchfield character varying DEFAULT NULL::character varying, v_searchvalue character varying DEFAULT NULL::character varying, v_mode integer DEFAULT NULL::integer) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_recordcount int;
  v_regno bigint;
BEGIN
  -- SET option (removed)
  DROP TABLE IF EXISTS tmp_temp88;
  CREATE TEMP TABLE tmp_temp88 ON COMMIT DROP AS SELECT ROW_NUMBER() OVER (ORDER BY doc DESC NULLS LAST) AS rownumber, vmid, fname, COALESCE(mobileno, 'N/A') AS mobileno, COALESCE(city, 'N/A') AS city, COALESCE(state, 'N/A') AS state, loginid, password, emailid, doc, (CASE active WHEN 1 THEN 'active' WHEN 0 THEN 'Deactive' WHEN 2 THEN 'Deleted' END) AS status FROM visitor_master;
  SELECT COUNT(*) INTO v_recordcount FROM tmp_temp88;
  IF (v_searchfield = 'fname') THEN
  RETURN QUERY SELECT * FROM tmp_temp88 WHERE fname LIKE '%' || v_searchvalue || '%';
  END IF;
  IF (v_searchfield = 'lname') THEN
  RETURN QUERY SELECT * FROM tmp_temp88 WHERE lname LIKE '%' || v_searchvalue || '%';
  END IF;
  IF (v_searchfield = 'loginid') THEN
  RETURN QUERY SELECT * FROM tmp_temp88 WHERE loginid = v_searchvalue;
  END IF;
  IF (v_searchfield = 'emailid') THEN
  RETURN QUERY SELECT * FROM tmp_temp88 WHERE emailid = v_searchvalue;
  END IF;
  IF (v_searchfield = 'mobileno') THEN
  RETURN QUERY SELECT * FROM tmp_temp88 WHERE mobileno = v_searchvalue;
  END IF;
  IF (v_todate <> '' AND v_fromdate <> '') THEN
  RETURN QUERY SELECT * FROM tmp_temp88 WHERE doc BETWEEN v_todate AND v_fromdate;
  END IF;
  IF (v_searchfield = '') THEN
  RETURN QUERY SELECT * FROM tmp_temp88 WHERE rownumber BETWEEN v_startrowindex AND v_maxrows;
  END IF;
  DROP TABLE IF EXISTS tmp_temp88;
  -- SET option (removed)
END;
$$;


--
-- Name: usp_voucher_cms(integer, integer, character varying, character varying, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_voucher_cms(v_startrowindex integer DEFAULT 2, v_maxrows integer DEFAULT 20, v_searchfield character varying DEFAULT ''::character varying, v_searchvalue character varying DEFAULT ''::character varying, v_totalcount integer DEFAULT 0) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_minindex INT;
  v_maxindex INT;
  v_recordcount INT;
  v_regno BIGINT;
BEGIN
  -- SET option (removed)
  v_maxrows := 200;
  v_minindex := (v_startrowindex - 1) * v_maxrows + 1;
  v_maxindex := v_startrowindex * v_maxrows;
  DROP TABLE IF EXISTS tmp_temp12;
  CREATE TEMP TABLE tmp_temp12 ON COMMIT DROP AS SELECT ROW_NUMBER() OVER (ORDER BY vm.vmid DESC NULLS LAST) AS rownumber, vm.vmid, vm.brandname, vm.description, vm.termofuse, vm.instruction, (CASE WHEN vm.active = 1 THEN 'ACTIVE' ELSE 'DEACTIVE' END) AS active FROM tbl_voucher_master AS vm WHERE vm.active = 1;
  RETURN QUERY SELECT * FROM tmp_temp12 WHERE rownumber BETWEEN v_startrowindex AND v_maxrows ORDER BY rownumber ASC NULLS FIRST;
  SELECT COUNT(1) INTO v_totalcount FROM tmp_temp12;
  DROP TABLE IF EXISTS tmp_temp12;
  -- SET option (removed)
END;
$$;


--
-- Name: usp_wallet_history(character varying, integer, integer, character varying, character varying, character varying, character varying, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_wallet_history(v_plid character varying DEFAULT '0'::character varying, v_startrowindex integer DEFAULT 1, v_maxrows integer DEFAULT 10, v_searchfield character varying DEFAULT ''::character varying, v_searchvalue character varying DEFAULT ''::character varying, v_fromdate character varying DEFAULT ''::character varying, v_todate character varying DEFAULT ''::character varying, v_totalcount integer DEFAULT 0) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_minindex INT;
  v_maxindex INT;
  v_query text;
BEGIN
  v_minindex := (v_startrowindex - 1) * v_maxrows + 1;
  v_maxindex := v_startrowindex * v_maxrows;
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp (ROWNUMBER BIGINT,
WDID BIGINT,
PLID BIGINT,
TYPE VARCHAR(100),
CRDRTYPE VARCHAR(100),
WITHDRAWLPOINTS DECIMAL,
WITHDRAWAMOUNT DECIMAL,
ADMINCHARGE DECIMAL,
TDS DECIMAL,
PAYBLEAMOUNT DECIMAL,
DATE timestamp,
REMARKS text,
STATUS VARCHAR(50),
ACCOUNTNO VARCHAR(100),
ACCOUNTHOLDERNAME VARCHAR(100),
BANKNAME VARCHAR(100),
BRANCHNAME VARCHAR(100),
IFSC VARCHAR(100),
TRANS_ID VARCHAR(100),
PAID_STATUS VARCHAR(100),
PAID_MODE INT,
ADMIN_REMARK VARCHAR(100),
INT_PAID_ACID INT,
TDS_SECTION_ID	int,
TDS_PERForAdsPoints	DECIMAL,
ADMINCHARGE_PERForAdsPoints	DECIMAL,
TDS_SECTION_ID_ForAdsPoints	int,
BinaryAndDirectWithdrawal	DECIMAL,
AdsPointsWithdrawal	DECIMAL,
WithDrawlPointsForAdsPoints	DECIMAL,
TDSForBinaryAndDirect 	DECIMAL,
TDSForAdsPoints DECIMAL) ON COMMIT DROP;
  v_query := 'INSERT INTO #TEMP  SELECT ROW_NUMBER() OVER(ORDER BY WH.DATE DESC) AS ROWNUMBER,WH.WDID,WH.PLID,WH.TYPE,WH.CRDRTYPE,WH.WITHDRAWLPOINTS,ISNULL(WH.WITHDRAWAMOUNT,0),ISNULL(WH.ADMINCHARGE,0),
WH.TDS,WH.PAYBLEAMOUNT,WH.DATE AS DATE,ISNULL(WH.REMARKS,0),WH.STATUS,ISNULL(MM.ACCOUNTNO,''''),ISNULL(MM.ACCOUNTHOLDERNAME,''''),ISNULL(MM.BANKNAME,''''),ISNULL(MM.BRANCHNAME,''''),ISNULL(MM.IFSC,''''),
ISNULL(WH.TRANS_ID,''''),ISNULL(PAID_STATUS,''''),PAID_MODE,
ADMIN_REMARK,INT_PAID_ACID,TDS_SECTION_ID,TDS_PERForAdsPoints,ADMINCHARGE_PERForAdsPoints,
TDS_SECTION_ID_ForAdsPoints,BinaryAndDirectWithdrawal,AdsPointsWithdrawal,WithDrawlPointsForAdsPoints,TDSForBinaryAndDirect,TDSForAdsPoints 
FROM TBL_WITHDRAWALS WH INNER JOIN WITHDRAWAL_HISTORY MM ON MM.WDID=WH.WDID WHERE WH.PLID=''' || v_plid || '''';
  IF ((v_fromdate <> '') AND (v_todate = '')) THEN
  v_query := v_query || ' AND CONVERT(DATE, WH.DATE, 105) BETWEEN  CONVERT(DATE, ''' || v_fromdate || ''', 105) AND  CONVERT(DATE, DBO.FUN_GETCURRENTDATE(), 105) ';
  END IF;
  IF ((v_fromdate = '') AND (v_todate <> '')) THEN
  v_query := v_query || ' AND CONVERT(DATE, WH.DATE, 105) BETWEEN  CONVERT(DATE, ''' || v_todate || ''', 105) AND  CONVERT(DATE, DBO.FUN_GETCURRENTDATE(), 105) ';
  END IF;
  IF ((v_fromdate <> '') AND (v_todate <> '')) THEN
  v_query := v_query || ' AND CONVERT(DATE, WH.DATE, 105) BETWEEN CONVERT(DATE, ''' || v_fromdate || ''', 105) AND  CONVERT(DATE, ''' || v_todate || ''', 105) ';
  END IF;
  EXECUTE v_query;
  RETURN QUERY SELECT * FROM tmp_temp WHERE rownumber BETWEEN v_minindex AND v_maxindex;
  SELECT COUNT(rownumber) INTO v_totalcount FROM tmp_temp;
  DROP TABLE IF EXISTS tmp_temp;
  -- SET option (removed)
END;
$$;


--
-- Name: usp_wallet_history_admin(text, text, text, text, text, text, text, text, integer, integer, text, text, text, integer, integer, integer, character varying, character varying, character varying, character varying, character varying, integer, character varying, numeric, numeric, numeric, numeric, numeric, numeric, numeric, character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_wallet_history_admin(v_withdrawalfromdate text DEFAULT ''::text, v_withdrawaltodate text DEFAULT ''::text, v_loginid text DEFAULT ''::text, v_accountno text DEFAULT ''::text, v_ifsccode text DEFAULT ''::text, v_accountholdername text DEFAULT ''::text, v_bankname text DEFAULT ''::text, v_branchname text DEFAULT ''::text, v_startrowindex integer DEFAULT 1, v_maxrows integer DEFAULT 100, v_panno text DEFAULT ''::text, v_section text DEFAULT '0'::text, v_name text DEFAULT ''::text, v_totalcount integer DEFAULT 0, v_mode integer DEFAULT 0, v_wdid integer DEFAULT 0, v_transactionid character varying DEFAULT ''::character varying, v_tdsamount character varying DEFAULT ''::character varying, v_searchby character varying DEFAULT '0'::character varying, v_searchfrom character varying DEFAULT ''::character varying, v_searchto character varying DEFAULT ''::character varying, v_isdownload integer DEFAULT 0, v_status character varying DEFAULT ''::character varying, v_totalcashpoint numeric DEFAULT 0, v_totalcpamount numeric DEFAULT 0, v_totalcptds numeric DEFAULT 0, v_totaladvertpoint numeric DEFAULT 0, v_totaladvertspointsamount numeric DEFAULT 0, v_totaladvertpointtds numeric DEFAULT 0, v_totalnetpayable numeric DEFAULT 0, v_username character varying DEFAULT ''::character varying) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_query text;
  v_newusername varchar(200);
BEGIN
  -- SET option (removed)
  IF (v_mode = 0) THEN
  v_query := '';
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp (ROWNUMBER BIGINT,
WDID BIGINT,
PLID BIGINT,
LOGINID text,
TYPE VARCHAR(100),
CRDRTYPE VARCHAR(100),
WITHDRAWLPOINTS DECIMAL,
WITHDRAWAMOUNT DECIMAL,
ADMINCHARGE DECIMAL,
TDS DECIMAL,
PAYBLEAMOUNT DECIMAL,
DATE timestamp,
REMARKS text,
STATUS VARCHAR(50),
ACCOUNTNO VARCHAR(100),
ACCOUNTHOLDERNAME VARCHAR(100),
BANKNAME VARCHAR(100),
BRANCHNAME VARCHAR(100),
IFSC VARCHAR(100),
TRANS_ID VARCHAR(100),
PAID_STATUS VARCHAR(100),
PAID_MODE INT,
ADMIN_REMARK VARCHAR(100),
INT_PAID_ACID INT,
TDS_SECTION_ID	int,
TDS_PERForAdsPoints	DECIMAL,
ADMINCHARGE_PERForAdsPoints	DECIMAL,
TDS_SECTION_ID_ForAdsPoints	int,
BinaryAndDirectWithdrawal	DECIMAL,
AdsPointsWithdrawal	DECIMAL,
WithDrawlPointsForAdsPoints	DECIMAL,
TDSForBinaryAndDirect 	DECIMAL,
TDSForAdsPoints DECIMAL,
PANNO text,
PANIMAGE  text) ON COMMIT DROP;
  v_query := 'INSERT INTO #TEMP SELECT ROW_NUMBER() OVER(ORDER BY WH.DATE DESC) AS ROWNUMBER,WH.WDID,WH.PLID,PL.LOGINID,WH.TYPE,WH.CRDRTYPE,
WH.WITHDRAWLPOINTS,ISNULL(WH.WITHDRAWAMOUNT,0),ISNULL(WH.ADMINCHARGE,0),
WH.TDS,WH.PAYBLEAMOUNT,WH.DATE AS DATE,ISNULL(WH.REMARKS,0),WH.STATUS,ISNULL(MM.ACCOUNTNO,''''),ISNULL(MM.ACCOUNTHOLDERNAME,''''),
ISNULL(MM.BANKNAME,''''),ISNULL(MM.BRANCHNAME,''''),ISNULL(MM.IFSC,''''),
ISNULL(WH.TRANS_ID,''''),ISNULL(PAID_STATUS,''''),PAID_MODE,
ADMIN_REMARK,INT_PAID_ACID,TDS_SECTION_ID,TDS_PERForAdsPoints,ADMINCHARGE_PERForAdsPoints,
TDS_SECTION_ID_ForAdsPoints,BinaryAndDirectWithdrawal,AdsPointsWithdrawal,WithDrawlPointsForAdsPoints,TDSForBinaryAndDirect,TDSForAdsPoints,
MMT.PANNO,ISNULL((SELECT KYC.IMAGE FROM KYC WHERE TYPE=''PANCARD-DETAILS'' AND KYC.REGNO=MMT.REGNO),''NoImage.jpg'' )as PANIMAGE
FROM TBL_WITHDRAWALS WH INNER JOIN WITHDRAWAL_HISTORY MM ON MM.WDID=WH.WDID
INNER JOIN PORTAL_LOGIN PL ON PL.PLID=WH.PLID INNER JOIN MEMBER_MASTER MMT ON MMT.PLID=WH.PLID WHERE WH.PLID>0';
  IF (v_withdrawalfromdate <> '' AND v_withdrawaltodate <> '') THEN
  v_query := v_query || ' AND Convert(Date,WH.DATE,103) BETWEEN CONVERT(DATE,''' || v_withdrawalfromdate || ''',103) AND CONVERT(DATE,''' || v_withdrawaltodate || ''',103) ';
  END IF;
  IF (v_withdrawalfromdate <> '') THEN
  v_query := v_query || ' AND Convert(Date,WH.DATE,103)>= CONVERT(Date,''' || v_withdrawalfromdate || ''',103) ';
  END IF;
  IF (v_withdrawaltodate <> '') THEN
  v_query := v_query || ' AND Convert(Date,WH.DATE,103)<= CONVERT(Date,''' || v_withdrawaltodate || ''',103) ';
  END IF;
  IF (v_loginid <> '') THEN
  v_query := v_query || ' AND PL.LOGINID Like ''%' || v_loginid || '%'' ';
  END IF;
  IF (v_username <> '') THEN
  IF (EXISTS(SELECT 1 FROM portal_login WHERE username = v_username)) THEN
  v_query := v_query || (' AND PL.USERNAME LIKE ''%' || v_username || '%''');
  ELSE
  IF (EXISTS(SELECT 1 FROM portal_login_history WHERE username = v_username)) THEN
  v_newusername := '';
  SELECT (SELECT username FROM portal_login WHERE plid IN (SELECT plid FROM portal_login_history WHERE username = v_username)) INTO v_newusername;
  v_query := v_query || (' AND PL.USERNAME LIKE ''%' || v_newusername || '%''');
  ELSE
  v_query := v_query || ' AND PL.USERNAME LIKE ''%' || v_username || '%'' ';
  END IF;
  END IF;
  END IF;
  IF (v_accountno <> '') THEN
  v_query := v_query || ' AND MM.ACCOUNTNO Like ''%' || v_accountno || '%'' ';
  END IF;
  IF (v_ifsccode <> '') THEN
  v_query := v_query || ' AND MM.IFSC Like ''%' || v_ifsccode || '%'' ';
  END IF;
  IF (v_accountholdername <> '') THEN
  v_query := v_query || ' AND MM.ACCOUNTHOLDERNAME Like ''%' || v_accountholdername || '%'' ';
  END IF;
  IF (v_bankname <> '') THEN
  v_query := v_query || ' AND MM.BANKNAME Like ''%' || v_bankname || '%'' ';
  END IF;
  IF (v_branchname <> '') THEN
  v_query := v_query || ' AND MM.BRANCHNAME Like ''%' || v_branchname || '%'' ';
  END IF;
  IF (v_panno <> '') THEN
  v_query := v_query || ' AND MMT.PANNO Like ''%' || v_panno || '%'' ';
  END IF;
  IF (v_name <> '') THEN
  v_query := v_query || ' AND PL.FNAME Like ''%' || v_name || '%'' ';
  END IF;
  IF (v_transactionid <> '') THEN
  v_query := v_query || ' AND WH.TRANS_ID = ''' || v_transactionid || ''' ';
  END IF;
  IF (v_status <> '') THEN
  v_query := v_query || ' AND WH.PAID_STATUS = ''' || v_status || ''' ';
  END IF;
  IF (v_searchby <> '0') THEN
  IF (v_searchfrom <> '' AND v_searchto <> '') THEN
  IF (v_searchby = 'CASHPOINTS') THEN
  v_query := v_query || ' AND WH.WITHDRAWLPOINTS BETWEEN ''' || v_searchfrom || ''' AND ''' || v_searchto || ''' ';
  END IF;
  IF (v_searchby = 'ADVERTPOINTS') THEN
  v_query := v_query || ' AND WH.WITHDRAWLPOINTSFORADSPOINTS BETWEEN ''' || v_searchfrom || ''' AND ''' || v_searchto || ''' ';
  END IF;
  IF (v_searchby = 'NETPAYABLE') THEN
  v_query := v_query || ' AND WH.PAYBLEAMOUNT BETWEEN ''' || v_searchfrom || ''' AND ''' || v_searchto || ''' ';
  END IF;
  END IF;
  IF (v_searchfrom = '' AND v_searchto <> '') THEN
  IF (v_searchby = 'CASHPOINTS') THEN
  v_query := v_query || ' AND WH.WITHDRAWLPOINTS <= ''' || v_searchto || '''  ';
  END IF;
  IF (v_searchby = 'ADVERTPOINTS') THEN
  v_query := v_query || ' AND WH.WITHDRAWLPOINTSFORADSPOINTS <= ''' || v_searchto || '''= ';
  END IF;
  IF (v_searchby = 'NETPAYABLE') THEN
  v_query := v_query || ' AND WH.PAYBLEAMOUNT <= ''' || v_searchto || ''' ';
  END IF;
  END IF;
  IF (v_searchto = '' AND v_searchfrom <> '') THEN
  IF (v_searchby = 'CASHPOINTS') THEN
  v_query := v_query || ' AND WH.WITHDRAWLPOINTS >=''' || v_searchfrom || ''' ';
  END IF;
  IF (v_searchby = 'ADVERTPOINTS') THEN
  v_query := v_query || ' AND WH.WITHDRAWLPOINTSFORADSPOINTS >= ''' || v_searchfrom || '''  ';
  END IF;
  IF (v_searchby = 'NETPAYABLE') THEN
  v_query := v_query || ' AND WH.PAYBLEAMOUNT >=''' || v_searchfrom || '''  ';
  END IF;
  END IF;
  END IF;
  EXECUTE v_query;
  IF (v_isdownload = 0) THEN
  RETURN QUERY SELECT * FROM tmp_temp WHERE rownumber BETWEEN v_startrowindex AND v_maxrows;
  SELECT SUM(COALESCE(withdrawlpoints, 0)), SUM(COALESCE(binaryanddirectwithdrawal, 0)), SUM(COALESCE(tdsforbinaryanddirect, 0)), SUM(COALESCE(withdrawlpointsforadspoints, 0)), SUM(COALESCE(adspointswithdrawal, 0)), SUM(COALESCE(tdsforadspoints, 0)), SUM(COALESCE(paybleamount, 0)) INTO v_totalcashpoint, v_totalcpamount, v_totalcptds, v_totaladvertpoint, v_totaladvertspointsamount, v_totaladvertpointtds, v_totalnetpayable FROM tmp_temp;
  ELSE
  RETURN QUERY SELECT ROW_NUMBER() OVER (ORDER BY rownumber NULLS FIRST) AS "s.no.", date, trans_id AS "transaction id", loginid AS "login id", panno AS "pan no.", withdrawlpoints AS "cash points", withdrawamount AS amount, tds, withdrawlpointsforadspoints AS "advert. points", adspointswithdrawal AS amount, tds_perforadspoints AS tds, paybleamount AS "net payable", accountno AS "account no.", status FROM tmp_temp;
  INSERT INTO tbl_exceltrackingreport (report_name, file_name, type, download_by, download_date) VALUES ('TDS REPORT', 'TDS_report.xls', 1, 1, CURRENT_TIMESTAMP);
  END IF;
  RETURN QUERY SELECT COUNT(1) AS totalrows FROM tmp_temp;
  SELECT COUNT(rownumber) INTO v_totalcount FROM tmp_temp;
  END IF;
  IF (v_mode = 1) THEN
  RETURN QUERY SELECT withdrawlpoints, withdrawamount, tds FROM tbl_withdrawals WHERE wdid = v_wdid;
  END IF;
  IF (v_mode = 2) THEN
  RETURN QUERY SELECT accountholdername, bankname, branchname, ifsc FROM withdrawal_history WHERE wdid = v_wdid;
  END IF;
  -- SET option (removed)
END;
$$;


--
-- Name: usp_wallet_statement_dashboard(integer, integer, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_wallet_statement_dashboard(v_pmid integer DEFAULT 0, v_did integer DEFAULT 0, v_mode integer DEFAULT 0) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF (v_mode = 1) THEN
  RETURN QUERY SELECT COALESCE(dm.companyname, '') AS name, COALESCE(dps.available_wallet, 0) AS available_wallet, COALESCE(dps.credit_wallet, 0) AS credit_wallet, COALESCE(dps.used_wallet, 0) AS used_wallet FROM tbl_distributor AS dl LEFT JOIN tbl_distributor_prepaid_setting AS dps ON dl.did = dps.pmid LEFT JOIN distributor_master AS dm ON dm.pmid = dl.pmid WHERE dl.active = 1 AND iskycapproved = 1 AND dl.pmid = v_pmid ORDER BY dps.createddate DESC NULLS LAST LIMIT 10;
  END IF;
  IF (v_mode = 2) THEN
  RETURN QUERY SELECT ROW_NUMBER() OVER (ORDER BY rw.rwrid DESC NULLS LAST) AS rownumber, CAST(rw.date AS DATE) AS date, rw.referance_id AS referenceid, rw.amount, CASE WHEN rw.paymode = 1 THEN 'Bank' WHEN rw.paymode = 9 THEN 'DD' WHEN rw.paymode = 10 THEN 'Cheque' WHEN rw.paymode = 11 THEN 'NEFT' WHEN rw.paymode = 12 THEN 'RTGS' END AS paymode, CASE WHEN rw.status = 1 THEN 'Pending' WHEN rw.status = 2 THEN 'Approved' WHEN rw.status = 3 THEN 'Rejected' END AS status FROM tbl_resellerwalletrequest AS rw WHERE rw.pmid = v_pmid LIMIT 5;
  END IF;
  IF (v_mode = 3) THEN
  RETURN QUERY SELECT ROW_NUMBER() OVER (ORDER BY rwsid DESC NULLS LAST) AS rownumber, date, traceno AS transactionid, crdrtype AS type, CASE WHEN crdrtype = 'Cr' THEN cr_amount WHEN crdrtype = 'Dr' THEN dr_amount END AS amount, balance FROM tbl_resellerwalletstatement WHERE did = v_did LIMIT 5;
  END IF;
  IF (v_mode = 4) THEN
  RETURN QUERY SELECT COALESCE(holdcommission, 0) AS holdcommission, COALESCE(pendingcommission, 0) AS pendingcommission, COALESCE(releasecommission, 0) AS releasecommission, COALESCE(totalcommission, 0) AS totalcommission FROM tbl_resellercommission WHERE did = v_did;
  END IF;
END;
$$;


--
-- Name: usp_waterrecharge_details(integer, integer, integer, character varying, character varying, integer, character varying, character varying, character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_waterrecharge_details(v_mode integer DEFAULT 0, v_startrowindex integer DEFAULT 1, v_maxrows integer DEFAULT 100, v_fromdate character varying DEFAULT ''::character varying, v_todate character varying DEFAULT ''::character varying, v_totalcount integer DEFAULT 0, v_searchfield character varying DEFAULT ''::character varying, v_searchvalue character varying DEFAULT ''::character varying, v_status character varying DEFAULT ''::character varying) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_minindex INT;
  v_maxindex INT;
  v_query text;
BEGIN
  v_minindex := (v_startrowindex - 1) * v_maxrows + 1;
  v_maxindex := v_startrowindex * v_maxrows;
  IF (v_mode = 0) THEN
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp (ROWNUMBER BIGINT GENERATED BY DEFAULT AS IDENTITY,         
 TCPRID BIGINT,               
 CLID BIGINT,                 
 MOBILENO VARCHAR(100),         
 OPERATORTYPE VARCHAR(100),        
 RECHARGEAMOUNT DECIMAL(18,2),        
 TRANSACTIONID  VARCHAR(100),         
 RECHARGEDATE VARCHAR(100),         
 ADMINSTATUS VARCHAR(100),        
 NAME VARCHAR(100),        
 EMAILID VARCHAR(100),        
 OPERATORNAME VARCHAR(100),        
 OPERATORCODE VARCHAR(100),        
 ISANDROIDORWEB INT,        
 PaidViaCashWallet Decimal(18,8),    
PaidViaCahbackWallet Decimal(18,8),    
PaidViaKreazVoucher Int,    
PaidViaOnline Decimal(18,8)) ON COMMIT DROP;
  v_query := 'INSERT INTO #TEMP SELECT TCPR.TCWRID,TCPR.CLID,TCPR.MOBILENO,TCPR.OPERATORTYPE,        
TCPR.RECHARGEAMOUNT,TCPR.TRANSACTIONID,CAST(TCPR.RECHARGEDATE AS VARCHAR(50)) ,TCPR.RECHARGESTATUS        
,(CL.FNAME+'' ''+CL.LNAME) AS NAME,CL.EMAILID,TCPR.OPERATORNAME,TCPR.OPERATORCODE,TCPR.ISANDROIDORWEB,        
 ISNULL(CASHWALLETUSED,0),  
ISNULL(CASHBACKWALLETUSED,0),    
ISNULL(VOUCHERWALLETUSED,0),  
ISNULL(TBL_ONLINEPAYMENTHISTORY.AMOUNT,0)         
FROM TBL_CUSTOMER_WATER_RECHARGES TCPR    
LEFT JOIN TBL_ORDERPAYMENT_HISTORY ON TBL_ORDERPAYMENT_HISTORY.ORDERID=TCPR.TRANSACTIONID      
LEFT JOIN TBL_ORDERONLINEREQUESTS ON TBL_ORDERONLINEREQUESTS.ORDERID=TCPR.TRANSACTIONID     
LEFT JOIN TBL_ONLINEPAYMENTHISTORY ON TBL_ONLINEPAYMENTHISTORY.REFERNECID=TBL_ORDERONLINEREQUESTS.TRANSACTIONID                                  
LEFT JOIN TBL_CUSTOMERLOGIN CL ON CL.CLID=TCPR.CLID           
WHERE TCPR.RECHARGESTATUS Is Not Null';
  IF ((v_fromdate <> '') AND (v_todate = '')) THEN
  v_query := v_query || ' AND CONVERT(DATE, TCPR.RECHARGEDATE, 105) BETWEEN  CONVERT(DATE, ''' || v_fromdate || ''', 105) AND  CONVERT(DATE, DBO.FUN_GETCURRENTDATE(), 105)';
  END IF;
  IF ((v_fromdate = '') AND (v_todate <> '')) THEN
  v_query := v_query || 'AND CONVERT(DATE, TCPR.RECHARGEDATE, 105) BETWEEN  CONVERT(DATE, ''' || v_todate || ''', 105) AND  CONVERT(DATE, DBO.FUN_GETCURRENTDATE(), 105)';
  END IF;
  IF ((v_fromdate <> '') AND (v_todate <> '')) THEN
  v_query := v_query || 'AND CONVERT(DATE, TCPR.RECHARGEDATE, 105) BETWEEN CONVERT(DATE, ''' || v_fromdate || ''', 105) AND  CONVERT(DATE, ''' || v_todate || ''', 105)';
  END IF;
  IF (v_searchfield = 'NAME') THEN
  v_query := v_query || ' AND (CL.FNAME+CL.LNAME) LIKE ''%' || v_searchvalue || '%'' ';
  END IF;
  IF (v_searchfield = 'PHONE') THEN
  v_query := v_query || ' AND TCPR.MOBILENO LIKE ''%' || v_searchvalue || '%'' ';
  END IF;
  IF (v_searchfield = 'EMAILID') THEN
  v_query := v_query || ' AND CL.EMAILID LIKE ''%' || v_searchvalue || '%'' ';
  END IF;
  IF (v_searchfield = 'TRANSACTIONID') THEN
  v_query := v_query || ' AND TCPR.TRANSACTIONID LIKE ''%' || v_searchvalue || '%'' ';
  END IF;
  IF (v_status <> '') THEN
  v_query := v_query || ' AND TCPR.RECHARGESTATUS =''' || v_status || ''' ';
  END IF;
  v_query := v_query || ' ORDER BY TCPR.RECHARGEDATE DESC';
  EXECUTE v_query;
  RETURN QUERY SELECT rownumber, tcprid, clid, mobileno, operatortype, rechargeamount, transactionid, rechargedate, adminstatus, name, emailid, operatorname, operatorcode, isandroidorweb, paidviacashwallet, paidviacahbackwallet, paidviakreazvoucher, paidviaonline FROM tmp_temp WHERE rownumber BETWEEN v_minindex AND v_maxindex ORDER BY rownumber ASC NULLS FIRST;
  SELECT COUNT(rownumber) INTO v_totalcount FROM tmp_temp;
  DROP TABLE IF EXISTS tmp_temp;
  -- SET option (removed)
  END IF;
END;
$$;


