--
-- Name: usp_webenquiry_new(integer, integer, character varying, character varying, character varying, character varying, character varying, character varying, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_webenquiry_new(v_startrowindex integer, v_maxrows integer, v_searchfield character varying, v_searchvalue character varying, v_fromdate character varying, v_todate character varying, v_cid character varying, v_dept character varying, v_recordcount integer) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_sqlquery text;
BEGIN
  -- SET option (removed)
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp (rowNumber int,
id bigint,
Name varchar(150),
Mobile varchar(100),
E_mail varchar(150),
Your_Message text,
enquirydate varchar(200),
countryname varchar(50),
department varchar(20),
reply varchar(30)) ON COMMIT DROP;
  v_sqlquery := '';
  v_sqlquery := 'insert into #temp select ROW_NUMBER() over(order by w.enquirydate desc) as rownumber , w.id ,w.Name,w.Mobile,w.E_mail,w.Your_Message,(CONVERT(VARCHAR(10), w.enquirydate, 105) +'' ''+CONVERT(VARCHAR(10), w.enquirydate, 108)) as enquirydate
,isnull((case when cn.countryname=''UNITED STATES'' then ''US'' when cn.countryname=''UNITED KINGDOM'' then ''UK'' else cn.countryname end ),''-'') as countryname,(case
 when department=''1'' then ''Support'' when department=''2'' then ''Sales'' when department=''3'' then  '' Complains'' else ''-'' end) as department ,(case
 when lastReplyDate is null then ''Reply'' when lastReplyDate is not null then ''Replied'' end) as reply
 from website_enquiry w left join COUNTRY cn on cn.cid=w.cid where w.active=1  ';
  IF (v_cid <> '') THEN
  v_sqlquery := v_sqlquery || (' and cn.cid =' || v_cid || ' ');
  END IF;
  IF (v_fromdate = '' OR v_todate = '') THEN
  IF (v_fromdate <> '') THEN
  v_sqlquery := v_sqlquery || ' and convert(date,w.enquirydate,103)= replace(convert(date,''' || v_fromdate || ''',103),''/'',''-'') ';
  END IF;
  IF (v_todate <> '') THEN
  v_sqlquery := v_sqlquery || ' and convert(date, w.enquirydate,103)  =replace(convert(date,''' || v_todate || ''',103),''/'',''-'') ';
  END IF;
  END IF;
  IF (v_fromdate <> '' AND v_todate <> '') THEN
  v_sqlquery := v_sqlquery || ' and  convert(date,w.enquirydate,103)  between  replace(convert(date,''' || v_fromdate || ''',103),''/'',''-'')  and replace(convert(date,''' || v_todate || ''',103),''/'',''-'')';
  END IF;
  IF (v_dept <> '') THEN
  v_sqlquery := v_sqlquery || (' and department =' || v_dept || ' ');
  END IF;
  IF (v_searchfield = 'Name') THEN
  v_sqlquery := v_sqlquery || ' and w.name like ''%' || v_searchvalue || '%''';
  END IF;
  IF (v_searchfield = 'Mobile') THEN
  v_sqlquery := v_sqlquery || ' and w.mobile like ''%' || v_searchvalue || '%''';
  END IF;
  IF (v_searchfield = 'email') THEN
  v_sqlquery := v_sqlquery || ' and w.E_mail like ''%' || v_searchvalue || '%''';
  END IF;
  EXECUTE v_sqlquery || ' order by w.enquirydate desc ';
  SELECT COUNT(*) INTO v_recordcount FROM tmp_temp;
  RETURN QUERY SELECT * FROM tmp_temp WHERE rownumber BETWEEN v_startrowindex AND v_maxrows;
  DROP TABLE IF EXISTS tmp_temp;
  RETURN QUERY SELECT v_recordcount AS recordcount;
  -- SET option (removed)
END;
$$;


--
-- Name: usp_webinquery(integer, integer, character varying, boolean, character varying, character varying, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_webinquery(v_startrowindex integer, v_maxrows integer, v_orderbyfield character varying, v_asc boolean, v_searchfield character varying, v_searchvalue character varying, v_mode integer) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_recordcount int;
  v_regno bigint;
BEGIN
  -- SET option (removed)
  DROP TABLE IF EXISTS tmp_temp12;
  CREATE TEMP TABLE tmp_temp12 ON COMMIT DROP AS SELECT ROW_NUMBER() OVER (ORDER BY id DESC NULLS LAST) AS rownumber, w.id, w.name, w.mobile, w.city, w.e_mail, w.your_message, w.enquirydate FROM dbo.website_enquiry AS w WHERE w.active = 1;
  SELECT COUNT(*) INTO v_recordcount FROM tmp_temp12;
  IF (v_searchfield = 'Name') THEN
  RETURN QUERY SELECT * FROM tmp_temp12 WHERE name LIKE '%' || v_searchvalue || '%';
  END IF;
  IF (v_searchfield = 'Mobile') THEN
  RETURN QUERY SELECT * FROM tmp_temp12 WHERE mobile = v_searchvalue;
  END IF;
  IF (v_searchfield = 'City') THEN
  RETURN QUERY SELECT * FROM tmp_temp12 WHERE city LIKE '%' || v_searchvalue || '%';
  END IF;
  IF (v_searchfield = '') THEN
  RETURN QUERY SELECT * FROM tmp_temp12 WHERE rownumber BETWEEN v_startrowindex AND v_maxrows;
  END IF;
  DROP TABLE IF EXISTS tmp_temp12;
  -- SET option (removed)
END;
$$;


--
-- Name: usp_whatsuppackmaster(integer, character varying, text, integer, numeric, numeric, numeric, bigint, bigint, integer, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_whatsuppackmaster(v_mode integer DEFAULT 1, v_packagename character varying DEFAULT ''::character varying, v_packagefeaturedescription text DEFAULT ''::text, v_isactive integer DEFAULT 0, v_amount numeric DEFAULT 0.00, v_totalamount numeric DEFAULT 0.00, v_st numeric DEFAULT 0.00, v_noofmessages bigint DEFAULT 0, v_noofdaysvalidity bigint DEFAULT 0, v_intresult integer DEFAULT 0, v_twupmid integer DEFAULT 0) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF (v_mode = 1) THEN
  RETURN QUERY SELECT ROW_NUMBER() OVER (ORDER BY twupmid NULLS FIRST) AS rownumber, twupmid, packagename, packagefeaturedescription, (CASE WHEN isactive = 1 THEN 'Active' ELSE 'Deactive' END) AS isactive, amount, totalamount, st, noofmessages, noofdaysvalidity FROM tbl_whatsuppackmaster;
  v_intresult := 1;
  END IF;
  IF (v_mode = 2) THEN
  INSERT INTO tbl_whatsuppackmaster (packagename, packagefeaturedescription, isactive, amount, totalamount, st, noofmessages, noofdaysvalidity) VALUES (v_packagename, v_packagefeaturedescription, v_isactive, v_amount, v_totalamount, v_st, v_noofmessages, v_noofdaysvalidity);
  v_intresult := 2;
  END IF;
  IF (v_mode = 3) THEN
  UPDATE tbl_whatsuppackmaster SET packagename = v_packagename, packagefeaturedescription = v_packagefeaturedescription, isactive = v_isactive, amount = v_amount, totalamount = v_totalamount, st = v_st, noofmessages = v_noofmessages, noofdaysvalidity = v_noofdaysvalidity WHERE twupmid = v_twupmid;
  v_intresult := 3;
  END IF;
  IF (0 <> 0) THEN
  v_intresult := 0;
  RETURN;
  END IF;
END;
$$;


--
-- Name: usp_withdrawal(integer, integer, character varying, boolean, character varying, character varying, character varying, character varying, character varying, character varying, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_withdrawal(v_startrowindex integer DEFAULT 1, v_maxrows integer DEFAULT 10, v_orderbyfield character varying DEFAULT NULL::character varying, v_asc boolean DEFAULT NULL::boolean, v_searchfield character varying DEFAULT NULL::character varying, v_searchvalue character varying DEFAULT NULL::character varying, v_cid character varying DEFAULT ''::character varying, v_fromdate character varying DEFAULT ''::character varying, v_todate character varying DEFAULT ''::character varying, v_mode character varying DEFAULT NULL::character varying, v_recordcount integer DEFAULT NULL::integer) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_regno bigint;
  v_sqlquery text;
  v_modestatus varchar(10);
BEGIN
  -- SET option (removed)
  v_sqlquery := '';
  v_modestatus := '0';
  DROP TABLE IF EXISTS tmp_newtemp;
  CREATE TEMP TABLE tmp_newtemp (rownumber varchar(20),

whid bigint,plid varchar(20),CrDrType varchar(10),amount numeric(19,4),TranType varchar(25),membername varchar(250),

LoginId varchar(125),name varchar(150),countryName varchar(150),currencySymbol varchar(30),recorddate timestamp,status varchar(25),paymode varchar(35),tranId varchar(35)) ON COMMIT DROP;
  v_sqlquery := '';
  v_sqlquery := ' insert into #newtemp select ROW_NUMBER() OVER (PARTITION BY wh.Date ORDER By Date) ,wh.whid,wh.plid,wh.CrDrType,ISNULL(wh.amount,0) as amount,wh.TranType,

	 ISNULL(pl.Fname,'''')+''''+ISNULL(pl.Lname,'''') as membername	,pl.LoginId,ISNULL(pl.Fname,'''')+''''+isnull(pl.Lname,'''') as name,con.countryName,cr.currencysymbol,
	 wh.date as recorddate,case when wh.status=''accept'' then ''Accepted'' when wh.status=''reject'' then ''Rejected'' else ''Pending'' end as status,wh.paymode,wh.tranId 
	 from withdrawal_history wh inner join Portal_Login pl on wh.plid=pl.PLID Left join COUNTRY con on con.CID=pl.cid left join tbl_currencymaster cr on con.cid=cr.CID where wh.whid>0 ';
  IF (v_mode <> '') THEN
  v_sqlquery := v_sqlquery || ' and wh.status=''' || v_mode || '''';
  ELSE
  v_sqlquery := v_sqlquery || ' and wh.status<>''pending''';
  END IF;
  IF (v_cid <> '') THEN
  v_sqlquery := v_sqlquery || ' and convert(varchar(50),pl.cid)=' || CAST(v_cid AS VARCHAR(50)) || ' ';
  END IF;
  IF (v_fromdate = '' OR v_todate = '') THEN
  IF (v_fromdate = '' AND v_todate <> '') THEN
  v_sqlquery := v_sqlquery || ' and convert(varchar(50), wh.date,103)<=convert(varchar(50),''' || v_todate || ''',103) ';
  END IF;
  IF (v_fromdate <> '' AND v_todate = '') THEN
  v_sqlquery := v_sqlquery || ' and convert(varchar(50), wh.date,103)>=convert(varchar(50),''' || v_fromdate || ''',103) ';
  END IF;
  ELSE
  v_sqlquery := v_sqlquery || ' and convert(varchar(50), wh.date,103)  between  convert(varchar(50),''' || v_fromdate || ''',103) 

			                       and convert(varchar(50),''' || v_todate || ''',103) ';
  END IF;
  IF (v_searchfield = 'loginid') THEN
  v_sqlquery := v_sqlquery || ' and pl.LoginId like ''%' || v_searchvalue || '%'' ';
  END IF;
  EXECUTE v_sqlquery;
  SELECT COUNT(*) INTO v_recordcount FROM tmp_newtemp;
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp ON COMMIT DROP AS SELECT * FROM tmp_newtemp WHERE rownumber = 1;
  TRUNCATE TABLE tmp_temp;
  IF (v_orderbyfield = 'datedesc') THEN
  INSERT INTO tmp_temp SELECT ROW_NUMBER() OVER (ORDER BY recorddate DESC NULLS LAST) AS rownumber, whid, plid, crdrtype, amount, trantype, membername, loginid, name, countryname, currencysymbol, recorddate, status, tranid, paymode FROM tmp_newtemp ORDER BY recorddate DESC NULLS LAST;
  END IF;
  IF (v_orderbyfield = 'dateasc') THEN
  INSERT INTO tmp_temp SELECT ROW_NUMBER() OVER (ORDER BY recorddate ASC NULLS FIRST) AS rownumber, whid, plid, crdrtype, amount, trantype, membername, loginid, name, countryname, currencysymbol, recorddate, status, tranid, paymode FROM tmp_newtemp ORDER BY recorddate ASC NULLS FIRST;
  END IF;
  RETURN QUERY SELECT * FROM tmp_temp WHERE rownumber BETWEEN v_startrowindex AND v_maxrows;
  RETURN QUERY SELECT v_recordcount AS recordcount;
  DROP TABLE IF EXISTS tmp_temp;
  DROP TABLE IF EXISTS tmp_newtemp;
  -- SET option (removed)
END;
$$;


--
-- Name: usp_withdrawal_approveorreject(integer, integer, text, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_withdrawal_approveorreject(v_wdid integer DEFAULT 0, v_mode integer DEFAULT 0, INOUT v_strresult text DEFAULT ''::text, INOUT v_intresult integer DEFAULT 0) RETURNS record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_regno Int;
  v_plid Int;
  v_withdrawaldate Date;
  v_binaryanddirectwithdrawal Decimal(10,2);
  v_adspointswithdrawal Decimal(10,2);
  v_withdrawalamount Decimal(10,2);
  v_paymentstatus text;
  v_actualstatus text;
BEGIN
  -- BEGIN TRAN (removed)
  BEGIN
  -- SET option (removed)
  v_regno := 0;
  v_plid := 0;
  v_binaryanddirectwithdrawal := 0.00;
  v_adspointswithdrawal := 0.00;
  v_withdrawalamount := 0.00;
  v_paymentstatus := '';
  v_actualstatus := '';
  SELECT status INTO v_paymentstatus FROM tbl_withdrawals WHERE wdid = v_wdid;
  SELECT (CASE WHEN v_mode = 1 THEN 'Paid' ELSE 'Rejected' END) INTO v_actualstatus;
  IF (v_mode = 2) THEN
  IF (v_paymentstatus = 'Paid') THEN
  v_strresult := 'Payment already paid so you can not reject it !';
  -- COMMIT (removed)
  RETURN;
  ELSE
  IF (v_paymentstatus = 'Rejected') THEN
  v_strresult := 'Payment already rejected so you can not reject it again !';
  -- COMMIT (removed)
  RETURN;
  END IF;
  END IF;
  END IF;
  IF (v_mode = 1) THEN
  IF (v_paymentstatus = 'Paid') THEN
  v_strresult := 'Payment already paid so you can not pay again !';
  -- COMMIT (removed)
  RETURN;
  END IF;
  IF (v_paymentstatus = 'Rejected') THEN
  v_strresult := 'Payment already rejected so you can not pay !';
  -- COMMIT (removed)
  RETURN;
  END IF;
  END IF;
  IF (v_mode = 2) THEN
  UPDATE tbl_withdrawals SET status = v_actualstatus, paid_status = v_actualstatus, rejectamt = withdrawamount WHERE wdid = v_wdid;
  UPDATE withdrawal_history SET status = v_actualstatus WHERE wdid = v_wdid;
  SELECT 0, plid, date, withdrawamount, binaryanddirectwithdrawal, adspointswithdrawal INTO v_regno, v_plid, v_withdrawaldate, v_withdrawalamount, v_binaryanddirectwithdrawal, v_adspointswithdrawal FROM tbl_withdrawals WHERE wdid = v_wdid;
  SELECT regno INTO v_regno FROM portal_login WHERE plid = v_plid;
  INSERT INTO money_statements (regno, processdate, crdrtype, cr_amount, dr_amount, remarks, type, typeid, status, traceno, pmoid, balance, old_bal) VALUES (v_regno, dbo.FUN_GETCURRENTDATE(), 'CR', v_withdrawalamount, 0, 'Point Credited Due To Rejection Of Payout', 'Point Credited Due To Rejection Of Payout', 0, 1, '', 0, COALESCE(0, 0), COALESCE(0, 0));
  UPDATE member_performance SET currentincome = COALESCE(currentincome, 0) + COALESCE(v_binaryanddirectwithdrawal, 0), withdrawalamount = COALESCE(withdrawalamount, 0) - COALESCE(v_binaryanddirectwithdrawal, 0), redeemedpoints = COALESCE(redeemedpoints, 0) + COALESCE(v_adspointswithdrawal, 0), withdrawlredeemedpoints = COALESCE(withdrawlredeemedpoints, 0) - COALESCE(v_adspointswithdrawal, 0) WHERE regno = v_regno;
  END IF;
  IF (v_mode = 1) THEN
  UPDATE tbl_withdrawals SET status = v_actualstatus, paid_status = v_actualstatus WHERE wdid = v_wdid;
  UPDATE withdrawal_history SET status = v_actualstatus WHERE wdid = v_wdid;
  END IF;
  -- SET option (removed)
  v_strresult := 'success';
  IF (0 <> 0) THEN
  v_strresult := 'some error occur';
  -- ROLLBACK (removed)
  RETURN;
  END IF;
  EXCEPTION WHEN OTHERS THEN
  v_strresult := 'some error occur';
  -- ROLLBACK (removed)
  RETURN;
  END;
  -- COMMIT (removed)
END;
$$;


--
-- Name: usp_withdrawal_paid_unpaid(bigint, character varying, text, character varying, character varying, character varying, character varying, character varying, character varying, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_withdrawal_paid_unpaid(v_wdid bigint DEFAULT 0, v_status character varying DEFAULT ''::character varying, v_remarks text DEFAULT ''::text, v_acountno character varying DEFAULT ''::character varying, v_bankname character varying DEFAULT ''::character varying, v_ifcs character varying DEFAULT ''::character varying, v_branchname character varying DEFAULT ''::character varying, v_transid character varying DEFAULT ''::character varying, v_date character varying DEFAULT ''::character varying, INOUT v_intresult integer DEFAULT 0) RETURNS integer
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_currentamount numeric(19,4);
  v_plid bigint;
  v_regno bigint;
  v_amount numeric(19,4);
BEGIN
  -- BEGIN TRAN (removed)
  v_currentamount := 0;
  v_plid := 0;
  v_regno := 0;
  v_amount := 0;
  SELECT withdrawamount INTO v_amount FROM tbl_withdrawals WHERE wdid = v_wdid;
  SELECT plid INTO v_plid FROM tbl_withdrawals WHERE wdid = v_wdid;
  SELECT regno INTO v_regno FROM member_master WHERE plid = v_plid;
  SELECT currentincome INTO v_currentamount FROM member_performance WHERE regno = v_regno;
  IF (v_status = 'Paid') THEN
  UPDATE tbl_withdrawals SET paid_status = v_status, admin_remark = v_remarks WHERE wdid = v_wdid;
  INSERT INTO tbl_admin_bankdeatails (member_regno, wdid, bankname, branchname, accountno, ifsc, transid, date) VALUES (v_regno, v_wdid, v_bankname, v_branchname, v_acountno, v_ifcs, v_transid, v_date);
  v_intresult := 1;
  -- COMMIT (removed)
  RETURN;
  ELSE
  IF (v_status = 'Rejected') THEN
  INSERT INTO money_statements (regno, processdate, crdrtype, cr_amount, dr_amount, remarks, type, typeid, status, traceno, pmoid, balance, old_bal) VALUES (v_regno, dbo.FUN_GETCURRENTDATE(), 'Dr', 0, v_amount, 'Withdrawal Rejected', 'Withdrawal', 0, 1, '', 0, COALESCE(v_currentamount + v_amount, 0), COALESCE(v_currentamount, 0));
  UPDATE tbl_withdrawals SET paid_status = v_status, remarks = v_remarks, admin_remark = v_remarks WHERE wdid = v_wdid;
  UPDATE withdrawal_history SET remarks = v_remarks WHERE wdid = v_wdid;
  UPDATE member_performance SET currentincome = COALESCE(currentincome, 0) + v_amount, withdrawalamount = COALESCE(withdrawalamount, 0) - v_amount WHERE regno = v_regno;
  v_intresult := 2;
  -- COMMIT (removed)
  RETURN;
  END IF;
  END IF;
  IF (0 <> 0) THEN
  v_intresult := 0;
  -- ROLLBACK (removed)
  RETURN;
  END IF;
  -- COMMIT (removed)
END;
$$;


--
-- Name: usp_withdrawal_pending_aproved(bigint, character varying, text, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_withdrawal_pending_aproved(v_wdid bigint DEFAULT 0, v_status character varying DEFAULT ''::character varying, v_remarks text DEFAULT ''::text, INOUT v_intresult integer DEFAULT 0) RETURNS integer
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_currentamount numeric(19,4);
  v_plid BIGINT;
  v_regno BIGINT;
  v_amount numeric(19,4);
BEGIN
  -- BEGIN TRAN (removed)
  v_currentamount := 0;
  v_plid := 0;
  v_regno := 0;
  v_amount := 0;
  SELECT withdrawamount INTO v_amount FROM tbl_withdrawals WHERE wdid = v_wdid;
  SELECT plid INTO v_plid FROM tbl_withdrawals WHERE wdid = v_wdid;
  SELECT regno INTO v_regno FROM member_master WHERE plid = v_plid;
  SELECT currentincome INTO v_currentamount FROM member_performance WHERE regno = v_regno;
  IF (v_status = 'Aproved') THEN
  UPDATE tbl_withdrawals SET status = 'Aproved', remarks = v_remarks WHERE wdid = v_wdid;
  UPDATE withdrawal_history SET status = 'Aproved', remarks = v_remarks WHERE wdid = v_wdid;
  v_intresult := 1;
  -- COMMIT (removed)
  RETURN;
  ELSE
  IF (v_status = 'Hold') THEN
  UPDATE tbl_withdrawals SET status = 'Hold', remarks = v_remarks WHERE wdid = v_wdid;
  UPDATE withdrawal_history SET status = 'Hold', remarks = v_remarks WHERE wdid = v_wdid;
  v_intresult := 2;
  -- COMMIT (removed)
  RETURN;
  ELSE
  IF (v_status = 'Rejected') THEN
  INSERT INTO money_statements (regno, processdate, crdrtype, cr_amount, dr_amount, remarks, type, typeid, status, traceno, pmoid, balance, old_bal) VALUES (v_regno, dbo.FUN_GETCURRENTDATE(), 'Cr', v_amount, 0, 'Withdrawal Rejected', 'Withdrawal', 0, 1, '', 0, COALESCE(v_currentamount + v_amount, 0), COALESCE(v_currentamount, 0));
  UPDATE tbl_withdrawals SET status = 'Rejected', remarks = v_remarks WHERE wdid = v_wdid;
  UPDATE withdrawal_history SET status = 'Rejected', remarks = v_remarks WHERE wdid = v_wdid;
  UPDATE member_performance SET currentincome = COALESCE(currentincome, 0) + v_amount, withdrawalamount = COALESCE(withdrawalamount, 0) - v_amount WHERE regno = v_regno;
  v_intresult := 3;
  -- COMMIT (removed)
  RETURN;
  END IF;
  END IF;
  END IF;
  IF (0 <> 0) THEN
  v_intresult := 0;
  -- ROLLBACK (removed)
  RETURN;
  END IF;
  -- COMMIT (removed)
END;
$$;


--
-- Name: usp_withdrawal_request(bigint, bigint, numeric, text, character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_withdrawal_request(v_plid bigint DEFAULT 0, v_points bigint DEFAULT 0, v_adspoint numeric DEFAULT 0.00, v_remark text DEFAULT ''::text, INOUT v_strresult character varying DEFAULT ''::character varying) RETURNS character varying
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_regno BIGINT;
  v_currentdirectandbinaryincome numeric(19,4);
  v_currentadsincome numeric(19,4);
  v_trans_id VARCHAR(100);
  v_minamount numeric(19,4);
  v_count INT;
  v_all_kyc_verification INT;
  v_kyc_status VARCHAR(50);
  v_maxamount numeric(19,4);
  v_withdrawaladmincharge numeric(19,4);
  v_withdrawaltds numeric(19,4);
  v_multipleamount numeric(19,4);
  v_admincharges numeric(19,4);
  v_tdscharge numeric(19,4);
  v_withdrawalamount numeric(19,4);
  v_kyc_count INT;
  v_pendingcount INT;
  v_withdrawlday text;
  v_todayday text;
  v_binaryanddirectamount numeric(19,4);
  v_adpointsamount numeric(19,4);
  v_pointamountratio Decimal(10,2);
  v_profile_status INT;
  v_dayid INT;
  v_cyclestartdate timestamp;
  v_cycleenddate timestamp;
  v_currentdateandtime timestamp;
  v_tdsforbinaryanddirect numeric(19,4);
  v_tdsforadspoints numeric(19,4);
  v_adminchargeforbinaryanddirect numeric(19,4);
  v_adminchargeforadspoints numeric(19,4);
  v_remainamountforbinaryanddirect numeric(19,4);
  v_remainamountforadspoints numeric(19,4);
  v_tds_perforbinaryanddirect numeric(19,4);
  v_admincharge_perforbinaryanddirect numeric(19,4);
  v_wdid BIGINT;
  v_tds_perforadspoints numeric(19,4);
  v_admincharge_perforadspoints numeric(19,4);
  v_accountno VARCHAR(100);
  v_accountholdername VARCHAR(100);
  v_bankname VARCHAR(100);
  v_ifsc VARCHAR(100);
  v_branchname VARCHAR(100);
  v_tds_section_id_forbinaryanddirect BIGINT;
  v_tds_section_id_foradspoints BIGINT;
  v_amount numeric(19,4);
  v_admincharge numeric(19,4);
  v_tds numeric(19,4);
  v_remainamount numeric(19,4);
  v_acid BIGINT;
BEGIN
  -- BEGIN TRAN (removed)
  v_regno := 0;
  v_currentdirectandbinaryincome := 0;
  v_currentadsincome := 0;
  v_trans_id := '';
  v_minamount := 0;
  v_count := 0;
  v_all_kyc_verification := 0;
  v_kyc_status := '';
  v_maxamount := 0;
  v_withdrawaladmincharge := 0;
  v_withdrawaltds := 0;
  v_multipleamount := 0;
  v_admincharges := 0;
  v_tdscharge := 0;
  v_withdrawalamount := 0;
  v_kyc_count := 0;
  v_pendingcount := 0;
  v_withdrawlday := '';
  v_todayday := '';
  v_binaryanddirectamount := 0;
  v_adpointsamount := 0;
  v_pointamountratio := 0.00;
  SELECT regno INTO v_regno FROM member_master WHERE plid = v_plid;
  SELECT COUNT(1) INTO v_count FROM tbl_withdrawals WHERE plid = v_regno;
  SELECT COUNT(1) INTO v_pendingcount FROM tbl_withdrawals WHERE status = 'Pending' AND plid = v_regno;
  v_profile_status := 0;
  SELECT COALESCE(is_profile_status, 0) INTO v_profile_status FROM member_master WHERE regno = v_regno;
  IF (v_profile_status <> 1) THEN
  v_strresult := 'Your profile is not verified by admin.';
  -- COMMIT (removed)
  RETURN;
  END IF;
  v_dayid := 0;
  v_currentdateandtime := dbo.FUN_GETCURRENTDATE();
  SELECT EXTRACT(DAYOFWEEK FROM v_currentdateandtime) INTO v_dayid;
  IF (v_dayid = 7) THEN
  v_dayid := 0;
  END IF;
  SELECT v_currentdateandtime - v_dayid INTO v_cyclestartdate;
  SELECT v_cyclestartdate + 6 INTO v_cycleenddate;
  IF EXISTS(SELECT 1 FROM tbl_withdrawals WHERE date >= v_cyclestartdate AND date <= v_cycleenddate AND plid = v_plid) THEN
  v_strresult := 'Your can request only one withdrawal between Saturday To Friday.';
  -- COMMIT (removed)
  RETURN;
  END IF;
  SELECT CASE WHEN (SELECT COUNT(regno) FROM kyc WHERE regno = v_regno) < 4 THEN 'Pending' WHEN (SELECT COUNT(regno) FROM kyc WHERE regno = v_regno AND isaprove = 2) > 0 THEN 'Rejected' WHEN (SELECT COUNT(regno) FROM kyc WHERE regno = v_regno AND isaprove = 0) > 0 THEN 'InProcess' ELSE 'Aproved' END INTO v_kyc_status;
  IF (v_kyc_status <> 'Aproved') THEN
  v_strresult := 'Your kyc is ' || COALESCE(v_kyc_status, 'Pending') || ' !';
  -- COMMIT (removed)
  RETURN;
  END IF;
  SELECT minamount, maxamount, admincharge, tds, multipleamount, activedays INTO v_minamount, v_maxamount, v_withdrawaladmincharge, v_withdrawaltds, v_multipleamount, v_withdrawlday FROM tbl_transconditions WHERE title = 'Withdrawal' AND isstop = 1;
  SELECT TO_CHAR(CAST(CURRENT_TIMESTAMP AS TIMESTAMP), 'TMDay') INTO v_todayday;
  IF (COALESCE(v_points, 0) < COALESCE(v_minamount, 0) AND (v_points > 0)) THEN
  v_strresult := 'Minimum withdrawal points is: ' || CAST(v_minamount AS VARCHAR(10)) || ' !';
  -- COMMIT (removed)
  RETURN;
  END IF;
  IF (COALESCE(v_adspoint, 0) < COALESCE(v_minamount, 0) AND (v_adspoint > 0)) THEN
  v_strresult := 'Minimum withdrawal points is: ' || CAST(v_minamount AS VARCHAR(10)) || ' !';
  -- COMMIT (removed)
  RETURN;
  END IF;
  IF (v_points > v_maxamount AND v_maxamount > 0) THEN
  v_strresult := 'Maximum withdrawal points is: ' || CAST(v_maxamount AS VARCHAR(10)) || ' !';
  -- COMMIT (removed)
  RETURN;
  END IF;
  IF (v_adspoint > v_maxamount AND v_maxamount > 0) THEN
  v_strresult := 'Maximum withdrawal points is: ' || CAST(v_maxamount AS VARCHAR(10)) || ' !';
  -- COMMIT (removed)
  RETURN;
  END IF;
  v_trans_id := GEN_RANDOM_UUID();
  v_trans_id := SUBSTRING(v_trans_id FROM 1 FOR 13) || '-' || dbo.FUN_GET_UNIQUE_TRACING_NUMBER();
  v_trans_id := dbo.FUN_GET_UNIQUE_TRACING_NUMBER();
  SELECT currentincome INTO v_currentdirectandbinaryincome FROM member_performance WHERE regno = v_regno;
  SELECT redeemedpoints INTO v_currentadsincome FROM member_performance WHERE regno = v_regno;
  v_strresult := 'success';
  IF (v_points <= COALESCE(v_currentdirectandbinaryincome, 0) AND v_adspoint <= COALESCE(v_currentadsincome, 0)) THEN
  SELECT limits INTO v_pointamountratio FROM settings WHERE caption = 'Point & Amount Ratio';
  v_binaryanddirectamount := COALESCE((v_pointamountratio * v_points), 0);
  v_adpointsamount := COALESCE((v_pointamountratio * v_adspoint), 0);
  IF (v_binaryanddirectamount = 0 AND v_adpointsamount = 0) THEN
  v_strresult := 'Nothing for withdrawal !';
  -- COMMIT (removed)
  RETURN;
  END IF;
  v_tdsforbinaryanddirect := 0;
  v_tdsforadspoints := 0;
  v_adminchargeforbinaryanddirect := 0;
  v_adminchargeforadspoints := 0;
  v_remainamountforbinaryanddirect := 0;
  v_remainamountforadspoints := 0;
  v_tds_perforbinaryanddirect := 0;
  v_admincharge_perforbinaryanddirect := 0;
  v_wdid := 0;
  v_tds_perforadspoints := 0;
  v_admincharge_perforadspoints := 0;
  v_accountno := '';
  v_accountholdername := '';
  v_bankname := '';
  v_ifsc := '';
  v_branchname := '';
  v_tds_section_id_forbinaryanddirect := 0;
  v_tds_section_id_foradspoints := 0;
  v_amount := 0;
  v_admincharge := 0;
  v_tds := 0;
  v_remainamount := 0;
  SELECT COALESCE(tds_withkyc, 0), COALESCE(int_id, 0) INTO v_tds_perforbinaryanddirect, v_tds_section_id_forbinaryanddirect FROM tds_section WHERE int_status = 1 AND section = '94B';
  SELECT COALESCE(tds_withkyc, 0), COALESCE(int_id, 0) INTO v_tds_perforadspoints, v_tds_section_id_foradspoints FROM tds_section WHERE int_status = 1 AND section = '94A';
  IF (COALESCE(v_tds_perforbinaryanddirect, 0) = 0) THEN
  SELECT COALESCE(limits, 0) INTO v_tds_perforbinaryanddirect FROM settings WHERE caption = 'TDS_VERIFIED_KYC' AND active = 1;
  SELECT COALESCE(limits, 0) INTO v_tds_perforadspoints FROM settings WHERE caption = 'TDS_VERIFIED_KYC' AND active = 1;
  END IF;
  SELECT COALESCE(v_binaryanddirectamount * v_tds_perforbinaryanddirect / 100, 0) INTO v_tdsforbinaryanddirect;
  SELECT COALESCE(v_adpointsamount * v_tds_perforadspoints / 100, 0) INTO v_tdsforadspoints;
  SELECT 0.00 INTO v_adminchargeforbinaryanddirect;
  SELECT v_binaryanddirectamount - COALESCE((v_tdsforbinaryanddirect + v_adminchargeforbinaryanddirect), 0) INTO v_remainamountforbinaryanddirect;
  SELECT 0.00 INTO v_adminchargeforadspoints;
  SELECT v_adpointsamount - COALESCE((v_tdsforadspoints + v_adminchargeforadspoints), 0) INTO v_remainamountforadspoints;
  SELECT v_binaryanddirectamount + v_adpointsamount INTO v_amount;
  SELECT (v_adminchargeforbinaryanddirect + v_adminchargeforadspoints) INTO v_admincharge;
  SELECT v_tdsforbinaryanddirect + v_tdsforadspoints INTO v_tds;
  SELECT v_amount - v_tds - v_admincharge INTO v_remainamount;
  v_acid := 0;
  SELECT COALESCE(acid, 0) INTO v_acid FROM bank_accounts WHERE regno = v_regno AND active = 1;
  SELECT accountholdername, accountno, bankname, ifsccode, branchname INTO v_accountholdername, v_accountno, v_bankname, v_ifsc, v_branchname FROM bank_accounts WHERE acid = v_acid;
  INSERT INTO tbl_withdrawals (plid, type, crdrtype, withdrawamount, admincharge, tds, paybleamount, remainamount, transamount, date, status, remarks, acceptamt, rejectamt, tds_per, admicharge_per, trans_id, acid, withdrawlpoints, tds_section_id, tds_perforadspoints, admincharge_perforadspoints, tds_section_id_foradspoints, binaryanddirectwithdrawal, adspointswithdrawal, withdrawlpointsforadspoints, tdsforbinaryanddirect, tdsforadspoints) VALUES (v_regno, '', 'Dr', v_amount, v_admincharge, v_tds, v_remainamount, v_remainamount, 0.00, dbo.FUN_GETCURRENTDATE(), 'Pending', v_remark, 0, 0, v_tds_perforbinaryanddirect, v_admincharge_perforbinaryanddirect, COALESCE(v_trans_id, ''), COALESCE(v_acid, 0), v_points, v_tds_section_id_forbinaryanddirect, v_tds_perforadspoints, v_admincharge_perforadspoints, v_tds_section_id_foradspoints, v_binaryanddirectamount, v_adpointsamount, v_adspoint, v_tdsforbinaryanddirect, v_tdsforadspoints);
  SELECT wdid INTO v_wdid FROM tbl_withdrawals WHERE plid = v_regno;
  INSERT INTO withdrawal_history (wdid, plid, crdrtype, amount, trantype, date, remarks, paymode, accountholdername, accountno, bankname, branchname, ifsc, responsetype, status, tranid, withdrawlpoints) VALUES (v_wdid, v_regno, '', v_amount, 'Dr', dbo.FUN_GETCURRENTDATE(), v_remark, '', v_accountholdername, v_accountno, v_bankname, v_branchname, v_ifsc, '', 'Pending', v_trans_id, (v_points + v_adspoint));
  INSERT INTO money_statements (regno, processdate, crdrtype, cr_amount, dr_amount, remarks, type, typeid, status, traceno, pmoid, balance, old_bal, withdrawlpoints) VALUES (v_regno, dbo.FUN_GETCURRENTDATE(), 'Dr', 0, v_amount, 'Withdrawal', 'Withdrawal', 0, 1, '', 0, COALESCE((v_currentadsincome + v_currentdirectandbinaryincome) - v_amount, 0), COALESCE((v_currentadsincome + v_currentdirectandbinaryincome), 0), (v_points + v_adspoint));
  UPDATE member_performance SET currentincome = currentincome - v_points, withdrawalamount = COALESCE(withdrawalamount, 0) + COALESCE(v_points, 0), redeemedpoints = redeemedpoints - v_adspoint, withdrawlredeemedpoints = COALESCE(withdrawlredeemedpoints, 0) + COALESCE(v_adspoint, 0) WHERE regno = v_regno;
  v_strresult := 'success';
  ELSE
  v_strresult := 'Your have insufficient funds for withdrawal.';
  END IF;
  IF (0 <> 0) THEN
  v_strresult := 'error';
  -- ROLLBACK (removed)
  RETURN;
  END IF;
  -- COMMIT (removed)
END;
$$;


--
-- Name: usp_withdrawlrequestreport(text, text, text, text, text, text, text, text, text, integer, integer, integer, text, numeric, numeric, text, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usp_withdrawlrequestreport(v_withdrawalfromdate text DEFAULT ''::text, v_withdrawaltodate text DEFAULT ''::text, v_loginid text DEFAULT ''::text, v_phone text DEFAULT ''::text, v_accountno text DEFAULT ''::text, v_ifsccode text DEFAULT ''::text, v_accountholdername text DEFAULT ''::text, v_bankname text DEFAULT ''::text, v_branchname text DEFAULT ''::text, v_startrowindex integer DEFAULT 1, v_maxrows integer DEFAULT 100, v_mode integer DEFAULT 1, v_username text DEFAULT ''::text, v_totalwithdrawalpoints numeric DEFAULT 0, v_totalpayableamount numeric DEFAULT 0, v_status text DEFAULT ''::text, v_totalrecord integer DEFAULT 0) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_query text;
  v_newusername varchar(200);
BEGIN
  IF (v_mode = 1) THEN
  -- SET option (removed)
  v_query := '';
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp (RowNumber Int GENERATED BY DEFAULT AS IDENTITY,
Date text,
EmailId text,
FULLEmailId text,
UserName text,
FullName text,
PHONE text,
WithdrawalAmount Decimal(10,2),
PayableAmount Decimal(10,2),
AccountNo text,
AccountHolderName text,
BankName text,
BranchName text,
IFSCCODE text,
WDID Int,
Status text,
TransactionId text) ON COMMIT DROP;
  v_query := 'INSERT INTO #Temp Select CONVERT(nvarchar,TW.DATE,106),
(Case When Len(PL.LOGINID)>10 Then SUBSTRING(PL.LOGINID,0,10) + ''... '' Else PL.LOGINID   End) as  ShortEmailId,EmailId,
PL.USERNAME,(PL.FNAME+'' ''+PL.LNAME)As Name,PL.PHONE,
TW.WITHDRAWAMOUNT,TW.PAYBLEAMOUNT,WH.ACCOUNTNO,
WH.ACCOUNTHOLDERNAME,WH.BANKNAME,WH.BRANCHNAME,
WH.IFSC,TW.WDID,TW.Status,TW.Trans_Id From TBL_WITHDRAWALS TW INNER JOIN WITHDRAWAL_HISTORY WH ON TW.WDID=WH.WDID
INNER JOIN PORTAL_LOGIN PL ON PL.PLID=TW.PLID WHERE PL.PLID>0';
  IF (v_withdrawalfromdate <> '' AND v_withdrawaltodate <> '') THEN
  v_query := v_query || ' AND Convert(nvarchar,TW.DATE) Between ''' || CAST(TO_CHAR(v_withdrawalfromdate, 'DD/MM/YYYY') AS VARCHAR(30)) || ''' AND ''' || CAST(TO_CHAR(v_withdrawaltodate, 'DD/MM/YYYY') AS VARCHAR(30)) || ''' ';
  ELSE
  IF (v_withdrawalfromdate <> '') THEN
  v_query := v_query || ' AND Convert(nvarchar,TW.DATE,103)>= CONVERT(nvarchar,''' || v_withdrawalfromdate || ''',103)';
  ELSE
  IF (v_withdrawaltodate <> '') THEN
  v_query := v_query || ' AND Convert(nvarchar,TW.DATE,103)<= CONVERT(nvarchar,''' || v_withdrawaltodate || ''',103) ';
  END IF;
  END IF;
  END IF;
  IF (v_loginid <> '') THEN
  v_query := v_query || ' AND PL.LOGINID Like ''%' || v_loginid || '%'' ';
  END IF;
  IF (v_username <> '') THEN
  IF (EXISTS(SELECT 1 FROM portal_login WHERE username = v_username)) THEN
  v_query := v_query || (' AND PL.USERNAME LIKE ''%' || v_username || '%''');
  ELSE
  IF (EXISTS(SELECT 1 FROM portal_login_history WHERE username = v_username)) THEN
  v_newusername := '';
  SELECT (SELECT username FROM portal_login WHERE plid IN (SELECT plid FROM portal_login_history WHERE username = v_username)) INTO v_newusername;
  v_query := v_query || (' AND PL.USERNAME LIKE ''%' || v_newusername || '%''');
  ELSE
  v_query := v_query || ' AND PL.USERNAME LIKE ''%' || v_username || '%'' ';
  END IF;
  END IF;
  END IF;
  IF (v_phone <> '') THEN
  v_query := v_query || ' AND PL.PHONE Like ''%' || v_phone || '%'' ';
  END IF;
  IF (v_accountno <> '') THEN
  v_query := v_query || ' AND WH.ACCOUNTNO Like ''%' || v_accountno || '%'' ';
  END IF;
  IF (v_ifsccode <> '') THEN
  v_query := v_query || ' AND WH.IFSC Like ''%' || v_ifsccode || '%'' ';
  END IF;
  IF (v_accountholdername <> '') THEN
  v_query := v_query || ' AND WH.ACCOUNTHOLDERNAME Like ''%' || v_accountholdername || '%'' ';
  END IF;
  IF (v_bankname <> '') THEN
  v_query := v_query || ' AND WH.BANKNAME Like ''%' || v_bankname || '%'' ';
  END IF;
  IF (v_branchname <> '') THEN
  v_query := v_query || ' AND WH.BRANCHNAME Like ''%' || v_branchname || '%'' ';
  END IF;
  IF (v_status <> '') THEN
  v_query := v_query || ' AND TW.Status = ''' || v_status || ''' ';
  END IF;
  v_query := v_query || 'order by TW.DATE desc';
  EXECUTE v_query;
  RETURN QUERY SELECT * FROM tmp_temp WHERE rownumber BETWEEN v_startrowindex AND v_maxrows;
  SELECT COALESCE(SUM(withdrawalamount), 0), COALESCE(SUM(payableamount), 0) INTO v_totalwithdrawalpoints, v_totalpayableamount FROM tmp_temp;
  SELECT COUNT(1) INTO v_totalrecord FROM tmp_temp;
  -- SET option (removed)
  END IF;
END;
$$;


--
-- Name: uspinsertarea(integer, integer, integer, character varying, boolean, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.uspinsertarea(v_cid integer DEFAULT 0, v_sid integer DEFAULT 0, v_ctid integer DEFAULT 0, v_areaname character varying DEFAULT NULL::character varying, v_active boolean DEFAULT NULL::boolean, INOUT v_intresult integer DEFAULT NULL::integer) RETURNS integer
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_slice1 text;
  v_index1 INT;
  v_slice2 text;
BEGIN
  -- SET option (removed)
  v_slice1 := v_areaname;
  v_intresult := 1;
  v_index1 := 1;
  WHILE v_index1 <> 0 LOOP
  SELECT POSITION(',' IN v_slice1) INTO v_index1;
  IF v_index1 <> 0 THEN
  SELECT LEFT(CAST(v_slice1 AS TEXT), v_index1 - 1) INTO v_slice2;
  ELSE
  SELECT v_slice1 INTO v_slice2;
  END IF;
  IF EXISTS(SELECT areaname FROM area_master WHERE areaname = v_slice2 AND cactive = 1 AND ctid = v_ctid) THEN
  v_intresult := 2;
  RETURN;
  ELSE
  INSERT INTO area_master (ctid, areaname, cid, sid, cactive) VALUES (v_ctid, v_slice2, v_cid, v_sid, v_active);
  v_intresult := 1;
  END IF;
  IF (0 <> 0) THEN
  v_intresult := 0;
  -- ROLLBACK (removed)
  RETURN;
  END IF;
  SELECT RIGHT(CAST(v_slice1 AS TEXT), LENGTH(CAST(v_slice1 AS TEXT)) - v_index1) INTO v_slice1;
  IF LENGTH(CAST(v_slice1 AS TEXT)) = 0 THEN
  EXIT;
  END IF;
  -- SET option (removed)
  END LOOP;
END;
$$;


--
-- Name: uspinsertcity(integer, text, boolean, integer, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.uspinsertcity(v_cid integer DEFAULT 0, v_cityname text DEFAULT ''::text, v_active boolean DEFAULT NULL::boolean, v_sid integer DEFAULT 0, INOUT v_intresult integer DEFAULT NULL::integer) RETURNS integer
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_slice1 text;
  v_index1 INT;
  v_slice2 text;
  v_id int;
  v_ctid int;
  v_idd int;
BEGIN
  -- SET option (removed)
  v_slice1 := v_cityname;
  v_intresult := 1;
  v_index1 := 1;
  WHILE v_index1 <> 0 LOOP
  SELECT POSITION(',' IN v_slice1) INTO v_index1;
  IF v_index1 <> 0 THEN
  SELECT LEFT(CAST(v_slice1 AS TEXT), v_index1 - 1) INTO v_slice2;
  ELSE
  SELECT v_slice1 INTO v_slice2;
  END IF;
  IF EXISTS(SELECT cityname FROM db_affiliate.dbo.city WHERE cityname = v_slice2 AND active = 1 AND sid = v_sid) THEN
  v_intresult := 2;
  RETURN;
  ELSE
  SELECT (MAX(ctid)) INTO v_id FROM city;
  INSERT INTO city (cid, sid, cityname, active, ctid) VALUES (v_cid, v_sid, v_slice2, v_active, v_id + 1);
  SELECT (MAX(ctid)) INTO v_idd FROM db_affiliate.dbo.city;
  INSERT INTO db_affiliate.dbo.city (cid, sid, cityname, active, ctid) VALUES (v_cid, v_sid, v_slice2, v_active, v_idd + 1);
  END IF;
  IF (0 <> 0) THEN
  v_intresult := 0;
  -- ROLLBACK (removed)
  RETURN;
  END IF;
  SELECT RIGHT(CAST(v_slice1 AS TEXT), LENGTH(CAST(v_slice1 AS TEXT)) - v_index1) INTO v_slice1;
  IF LENGTH(CAST(v_slice1 AS TEXT)) = 0 THEN
  EXIT;
  END IF;
  -- SET option (removed)
  END LOOP;
END;
$$;


