CREATE FUNCTION dbo.uspinsertstate(v_cid integer DEFAULT 96, v_statename character varying DEFAULT ''::character varying, v_active boolean DEFAULT true, v_scode character varying DEFAULT ''::character varying, v_intresult integer DEFAULT 0) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_slice1 text;
  v_index1 INT;
  v_slice2 text;
  v_maxsid int;
BEGIN
  -- SET option (removed)
  v_slice1 := v_statename;
  v_intresult := 1;
  v_index1 := 1;
  WHILE v_index1 <> 0 LOOP
  SELECT POSITION(',' IN v_slice1) INTO v_index1;
  IF v_index1 <> 0 THEN
  SELECT LEFT(CAST(v_slice1 AS TEXT), v_index1 - 1) INTO v_slice2;
  ELSE
  SELECT v_slice1 INTO v_slice2;
  END IF;
  RETURN QUERY SELECT v_slice2;
  IF EXISTS(SELECT statename FROM state WHERE statename = v_slice2 AND sactive = 1 AND cid = v_cid) THEN
  RETURN QUERY SELECT 1 AS duplicate;
  v_intresult := 2;
  RETURN;
  ELSE
  SELECT MAX(sid) INTO v_maxsid FROM state;
  v_maxsid := v_maxsid + 1;
  INSERT INTO state (cid, statename, scode, sid, sactive) VALUES (v_cid, v_slice2, v_scode, v_maxsid, v_active);
  v_intresult := 1;
  END IF;
  IF (0 <> 0) THEN
  v_intresult := 0;
  -- ROLLBACK (removed)
  RETURN;
  END IF;
  SELECT RIGHT(CAST(v_slice1 AS TEXT), LENGTH(CAST(v_slice1 AS TEXT)) - v_index1) INTO v_slice1;
  IF LENGTH(CAST(v_slice1 AS TEXT)) = 0 THEN
  EXIT;
  END IF;
  -- SET option (removed)
  END LOOP;
END;
$$;


