--
-- Name: usplogin(character varying, character varying, integer, integer, integer, character varying, character varying, character varying); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.usplogin(v_username character varying DEFAULT ''::character varying, v_password character varying DEFAULT ''::character varying, v_employeeid integer DEFAULT 0, v_userid integer DEFAULT 0, v_parentid integer DEFAULT 0, v_oldpass character varying DEFAULT ''::character varying, v_newpass character varying DEFAULT ''::character varying, v_querytype character varying DEFAULT ''::character varying) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_optid int;
  v_optdailytrget int;
  v_matchpass VARCHAR(100);
  v_result INT;
BEGIN
  -- SET option (removed)
  v_optid := 0;
  IF (v_querytype = 'operator') THEN
  SELECT limits INTO v_optdailytrget FROM settings WHERE caption = 'opttarget' AND active = 1;
  UPDATE tbl_operator_master SET lastlogin = (SELECT dbo.fun_getIndiaCurrentDate()) WHERE LOWER(loginid) = LOWER(v_username) AND LOWER(password) = LOWER(v_password) AND LOWER(usertype) = LOWER(v_querytype) AND status = 1;
  RETURN QUERY SELECT 8 AS result, * FROM tbl_operator_master WHERE LOWER(loginid) = LOWER(v_username) AND LOWER(password) = LOWER(v_password) AND LOWER(usertype) = LOWER(v_querytype) AND status = 1;
  SELECT optid INTO v_optid FROM tbl_operator_master WHERE LOWER(loginid) = LOWER(v_username) AND LOWER(password) = LOWER(v_password) AND LOWER(usertype) = LOWER(v_querytype) AND status = 1;
  IF (v_optid <> 0) THEN
  IF NOT EXISTS(SELECT 1 FROM tbl_operator_report WHERE optid = v_optid AND CAST(logintime AS DATE) = CAST(dbo.fun_getIndiaCurrentDate() AS DATE)) THEN
  INSERT INTO tbl_operator_report (optid, logintime, totallisting, totalverified, dailytarget) VALUES (v_optid, dbo.fun_getIndiaCurrentDate(), 0, 0, v_optdailytrget);
  END IF;
  END IF;
  END IF;
  IF (v_querytype = 'qa') THEN
  UPDATE tbl_operator_master SET lastlogin = (SELECT dbo.fun_getIndiaCurrentDate()) WHERE LOWER(loginid) = LOWER(v_username) AND LOWER(password) = LOWER(v_password) AND LOWER(usertype) = LOWER(v_querytype) AND status = 1;
  RETURN QUERY SELECT 8 AS result, * FROM tbl_operator_master WHERE LOWER(loginid) = LOWER(v_username) AND LOWER(password) = LOWER(v_password) AND LOWER(usertype) = LOWER(v_querytype) AND status = 1;
  SELECT optid INTO v_optid FROM tbl_operator_master WHERE LOWER(loginid) = LOWER(v_username) AND LOWER(password) = LOWER(v_password) AND LOWER(usertype) = LOWER(v_querytype) AND status = 1;
  IF (v_optid <> 0) THEN
  IF NOT EXISTS(SELECT 1 FROM tbl_operator_report WHERE optid = v_optid AND CAST(logintime AS DATE) = CAST(dbo.fun_getIndiaCurrentDate() AS DATE)) THEN
  INSERT INTO tbl_operator_report (optid, logintime, totallisting, totalverified) VALUES (v_optid, dbo.fun_getIndiaCurrentDate(), 0, 0);
  END IF;
  END IF;
  END IF;
  IF (v_querytype = 'GetUserDetails') THEN
  RETURN QUERY SELECT u.* FROM tbluser AS u WHERE u.username = v_username AND u.password = v_password AND u.isactive = 1 AND u.isdeleted = 0;
  END IF;
  IF (v_querytype = 'GetUserPassword') THEN
  RETURN QUERY SELECT password FROM tbluser WHERE username = v_username AND isactive = 1 AND isdeleted = 0;
  END IF;
  IF (v_querytype = 'GetEmployeeDetails') THEN
  RETURN QUERY SELECT emp.employeecode, emp.associatedtoid, emp.brid, emp.name, emp.isactive, us.username, us.password, us.roleid, r.rolename, a.association FROM tblemployee AS emp LEFT OUTER JOIN tbluser AS us ON emp.eid = us.eid LEFT OUTER JOIN tblrole AS r ON r.roleid = us.roleid LEFT OUTER JOIN tblassociatedto AS a ON a.asoid = emp.associatedtoid WHERE (emp.isactive = 1 AND emp.isdeleted = 0) AND emp.employeecode = v_employeeid;
  END IF;
  IF (v_querytype = 'GetAccessiblePage') THEN
  RETURN QUERY SELECT t.url AS pagename FROM tblusermodule AS m INNER JOIN tblmenu AS t ON t.id = m.moduleid AND m.isactive = 1 AND m.userid = v_userid;
  END IF;
  IF (v_querytype = 'ChangePassword') THEN
  SELECT password INTO v_matchpass FROM tbluser AS tu WHERE tu.userid = v_userid;
  IF COALESCE(v_matchpass, '') = '' THEN
  v_result := 1;
  ELSE
  IF (v_matchpass <> v_oldpass) THEN
  v_result := 2;
  END IF;
  IF (v_matchpass = v_oldpass) THEN
  UPDATE tbluser SET password = v_newpass WHERE userid = v_userid AND password = v_oldpass;
  v_result := 3;
  END IF;
  END IF;
  RETURN QUERY SELECT v_result AS result;
  END IF;
  IF v_querytype = 'MenuRootLevel' THEN
  RETURN QUERY SELECT id, title, url, (SELECT COUNT(*) FROM tblmenu WHERE parentid = mm.id) AS childnodecount FROM tblusermodule AS mu LEFT OUTER JOIN tblmenu AS mm ON mu.moduleid = mm.id WHERE COALESCE(mm.parentid, '') = '' AND mu.isactive = 1 AND mu.userid = v_userid ORDER BY mm.displayorder ASC NULLS FIRST;
  END IF;
  IF v_querytype = 'MenuSubRootLevel' THEN
  RETURN QUERY SELECT id, title, url, (SELECT COUNT(*) FROM tblmenu WHERE parentid = mm.id) AS childnodecount FROM tblusermodule AS mu LEFT OUTER JOIN tblmenu AS mm ON mu.moduleid = mm.id WHERE COALESCE(mm.parentid, '') <> '' AND mm.parentid = v_parentid AND mu.userid = v_userid AND mu.isactive = 1 ORDER BY mm.displayorder ASC NULLS FIRST;
  END IF;
  IF v_querytype = 'GetMenuByUserId' THEN
  RETURN QUERY SELECT id, title, url, imgname, COALESCE(parentid, 0) AS parentid, (SELECT COUNT(*) FROM tblmenu WHERE parentid = mm.id) AS childnodecount FROM tblusermodule AS mu LEFT OUTER JOIN tblmenu AS mm ON mu.moduleid = mm.id WHERE mu.isactive = 1 AND mm.isdeleted = 0 AND mm.isactive = 1 AND mm.id <> 1 AND mu.userid = v_userid ORDER BY mm.displayorder ASC NULLS FIRST;
  END IF;
  IF (v_querytype = 'GetMemberDetails1') THEN
  IF EXISTS(SELECT pl.pmid FROM portal_login AS pl, portal_master AS pm WHERE pl.loginid = v_username AND pl.password = v_password AND pl.pmid = pm.pmid AND pl.active = 1) AND NOT EXISTS(SELECT smd.smdid FROM portal_login AS pl, sponsor_master_detail AS smd WHERE pl.loginid = v_username AND pl.password = v_password AND pl.plid = smd.plid AND pl.active = 1) THEN
  RETURN QUERY SELECT pl.*, pm.*, 3 AS result FROM portal_login AS pl, portal_master AS pm WHERE pl.loginid = v_username AND pl.password = v_password AND pl.pmid = pm.pmid AND pl.active = 1;
  END IF;
  IF EXISTS(SELECT pl.plid FROM portal_login AS pl WHERE pl.loginid = v_username AND pl.password = v_password AND pl.active = 1) AND NOT EXISTS(SELECT smd.smdid FROM portal_login AS pl, sponsor_master_detail AS smd WHERE pl.loginid = v_username AND pl.password = v_password AND pl.plid = smd.plid AND pl.active = 1) THEN
  RETURN QUERY SELECT *, 4 AS result FROM portal_login WHERE loginid = v_username AND password = v_password AND active = 1;
  END IF;
  IF EXISTS(SELECT smd.smdid FROM portal_login AS pl, sponsor_master_detail AS smd WHERE pl.loginid = v_username AND pl.password = v_password AND pl.plid = smd.plid AND pl.active = 1) AND NOT EXISTS(SELECT pl.pmid FROM portal_login AS pl, portal_master AS pm WHERE pl.loginid = v_username AND pl.password = v_password AND pl.pmid = pm.pmid AND pl.active = 1) THEN
  RETURN QUERY SELECT pl.*, smd.*, 5 AS result FROM portal_login AS pl, sponsor_master_detail AS smd WHERE pl.loginid = v_username AND pl.password = v_password AND pl.plid = smd.plid AND pl.active = 1;
  END IF;
  IF EXISTS(SELECT smd.smdid FROM portal_login AS pl, sponsor_master_detail AS smd WHERE pl.loginid = v_username AND pl.password = v_password AND pl.plid = smd.plid AND pl.active = 1) AND EXISTS(SELECT pl.pmid FROM portal_login AS pl, portal_master AS pm WHERE pl.loginid = v_username AND pl.password = v_password AND pl.pmid = pm.pmid AND pl.active = 1) THEN
  RETURN QUERY SELECT pl.*, smd.*, 6 AS result FROM portal_login AS pl, sponsor_master_detail AS smd WHERE pl.loginid = v_username AND pl.password = v_password AND pl.plid = smd.plid AND pl.active = 1;
  END IF;
  END IF;
END;
$$;


