--
-- Name: uspsponsorad(integer, integer, character varying, bigint, text, integer, character varying, character varying, character varying, boolean, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.uspsponsorad(v_pageref integer DEFAULT 0, v_locationno integer DEFAULT 0, v_framesize character varying DEFAULT ''::character varying, v_locationprice bigint DEFAULT 0, v_packagename text DEFAULT ''::text, v_spid integer DEFAULT NULL::integer, v_imageopt character varying DEFAULT ''::character varying, v_url character varying DEFAULT ''::character varying, v_description character varying DEFAULT ''::character varying, v_active boolean DEFAULT NULL::boolean, INOUT v_intresult integer DEFAULT NULL::integer) RETURNS integer
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_plid bigint;
  v_err int;
  v_count int;
BEGIN
