CREATE FUNCTION dbo.uspuser(v_employeeid character varying DEFAULT ''::character varying, v_name character varying DEFAULT ''::character varying, v_uid integer DEFAULT 0, v_associatedtoid integer DEFAULT 0, v_eid integer DEFAULT 0, v_username character varying DEFAULT ''::character varying, v_password character varying DEFAULT ''::character varying, v_roleid integer DEFAULT 0, v_createdbyid integer DEFAULT 0, v_isactive boolean DEFAULT true, v_querytype character varying DEFAULT ''::character varying, v_brid integer DEFAULT 0, v_mobileno character varying DEFAULT ''::character varying, v_mailid character varying DEFAULT ''::character varying, v_address character varying DEFAULT ''::character varying, v_pincode character varying DEFAULT ''::character varying, v_stateid integer DEFAULT 0, v_cityid integer DEFAULT 0, v_intresult integer DEFAULT 0, v_cid integer DEFAULT 0, v_phone character varying DEFAULT ''::character varying, v_photo character varying DEFAULT ''::character varying, v_faxno character varying DEFAULT ''::character varying, v_instantman character varying DEFAULT ''::character varying, v_orgname character varying DEFAULT ''::character varying, v_date timestamp without time zone DEFAULT NULL::timestamp without time zone, v_addtionalinfo character varying DEFAULT ''::character varying, v_instatntmanid1 integer DEFAULT 0, v_instantman_name character varying DEFAULT ''::character varying) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_error VARCHAR(100);
  v_userid bigint;
  v_maxempid bigint;
  v_usid varchar(10);
  v_assoto bigint;
  v_moduleid int;
  instcursor CURSOR FOR SELECT id FROM tblmenu WHERE isactive = 1 AND isdeleted = 0 AND (associatedto = v_assoto OR associatedto = 0) ORDER BY id NULLS FIRST;
BEGIN
  -- SET option (removed)
  v_error := 'Error while saving the record';
  v_intresult := 0;
  IF v_querytype = 'BindUserList' THEN
  RETURN QUERY SELECT userid, username FROM tbluser WHERE isactive = 1 AND isdeleted = 0;
  END IF;
  IF v_querytype = 'BindUserByAssociation' THEN
  RETURN QUERY SELECT userid, username FROM tbluser WHERE isactive = 1 AND isdeleted = 0 AND associatedtoid = v_associatedtoid;
  END IF;
  IF v_querytype = 'GetAllUsers' THEN
  RETURN QUERY SELECT e.eid, e.employeecode, u.userid, u.username, e.name FROM tbluser AS u INNER JOIN tblemployee AS e ON u.eid = e.eid WHERE u.isactive = 1 AND u.roleid <> 1 AND u.username <> 'supersupport' ORDER BY u.userid ASC NULLS FIRST;
  END IF;
  IF v_querytype = 'GetUserByName' THEN
  RETURN QUERY SELECT userid FROM tbluser WHERE username = v_username;
  END IF;
  IF v_querytype = 'GetUserByEmployeeID' THEN
  RETURN QUERY SELECT ey.eid, ey.employeecode, ey.associatedtoid, ey.brid, ey.name, us.username, us.password, us.roleid FROM tblemployee AS ey INNER JOIN tbluser AS us ON us.eid = ey.eid WHERE us.isactive = 1 AND us.isdeleted = 0 AND ey.employeecode = v_employeeid;
  END IF;
  IF v_querytype = 'GetUserByUserID' THEN
  RETURN QUERY SELECT ey.eid, ey.employeecode, ey.associatedtoid, ey.brid, ey.name, us.userid, us.username, us.password, us.roleid, us.isactive, ey.mailid, ey.mobileno, ey.permamentaddress, ey.pincode, ey.cityid, ey.stateid, ey.cid, ey.phone, COALESCE(ey.photo, '') AS photo, ey.faxno, ey.instantmanagerid, ey.organizationname, ey.dob, ey.additionalinformation, ey.instantmanagername, ey.instantmanagerid1 FROM tblemployee AS ey INNER JOIN tbluser AS us ON us.eid = ey.eid WHERE us.isactive = 1 AND us.isdeleted = 0 AND us.userid = v_uid;
  END IF;
  IF v_querytype = 'DeleteUser' THEN
  SELECT userid, eid INTO v_usid, v_eid FROM tbluser WHERE eid IN (SELECT eid FROM tblemployee WHERE employeecode = v_employeeid);
  DELETE FROM tblusermodule WHERE userid = v_usid;
  DELETE FROM tbluser WHERE eid = v_eid;
  DELETE FROM tblemployee WHERE employeecode = v_employeeid;
  END IF;
  IF v_querytype = 'SaveEmployee' THEN
  BEGIN
  -- BEGIN TRAN (removed)
  SELECT MAX(eid) + 1 INTO v_maxempid FROM tblemployee WHERE isactive = 1 AND isdeleted = 0;
  IF EXISTS(SELECT 1 FROM tblemployee WHERE employeecode = v_employeeid AND v_eid = 0) THEN
  v_error := 'Employee already exists';
  RAISE EXCEPTION '%', v_error;
  RETURN;
  END IF;
  IF v_eid = 0 THEN
  INSERT INTO tblemployee (employeecode, associatedtoid, brid, name, createdbyid, createdon) VALUES (v_maxempid, v_associatedtoid, v_brid, v_name, v_createdbyid, CURRENT_TIMESTAMP);
  RETURN QUERY SELECT v_maxempid;
  ELSE
  UPDATE tblemployee SET name = v_name, modbyid = v_createdbyid, modon = CURRENT_TIMESTAMP WHERE eid = v_eid;
  RETURN QUERY SELECT v_maxempid;
  END IF;
  -- COMMIT (removed)
  EXCEPTION WHEN OTHERS THEN
  RAISE EXCEPTION '%', v_error;
  RETURN;
  END;
  END IF;
  IF v_querytype = 'SaveUser' THEN
  BEGIN
  -- BEGIN TRAN (removed)
  IF EXISTS(SELECT 1 FROM tbluser WHERE eid = v_eid AND v_uid = 0) THEN
  v_error := 'User already exists';
  RAISE EXCEPTION '%', v_error;
  RETURN;
  END IF;
  IF v_uid = 0 THEN
  INSERT INTO tbluser (associatedtoid, eid, username, password, roleid, createdbyid, createdon) VALUES (v_associatedtoid, v_eid, v_username, v_password, v_roleid, v_createdbyid, CURRENT_TIMESTAMP);
  ELSE
  UPDATE tbluser SET username = v_username, password = v_password, roleid = v_roleid, modbyid = v_createdbyid, modon = CURRENT_TIMESTAMP WHERE eid = v_eid;
  END IF;
  -- COMMIT (removed)
  EXCEPTION WHEN OTHERS THEN
  RAISE EXCEPTION '%', v_error;
  RETURN;
  END;
  END IF;
  IF v_querytype = 'SaveUserWithEmployee' THEN
  BEGIN
  -- BEGIN TRAN (removed)
  IF EXISTS(SELECT username FROM tbluser WHERE username = v_username AND v_uid = 0) THEN
  -- ROLLBACK (removed)
  v_intresult := 2;
  RETURN;
  END IF;
  SELECT MAX(eid) + 1 INTO v_maxempid FROM tblemployee WHERE isactive = 1 AND isdeleted = 0;
  SELECT associatedtoid INTO v_assoto FROM tblrole WHERE roleid = v_roleid;
  IF (v_uid = 0 AND v_eid = 0) THEN
  INSERT INTO tblemployee (employeecode, associatedtoid, brid, name, createdbyid, createdon, mobileno, mailid, permamentaddress, pincode, stateid, cityid, cid, phone, photo) VALUES (v_maxempid, v_assoto, v_brid, v_name, v_createdbyid, CURRENT_TIMESTAMP, v_mobileno, v_mailid, v_address, v_pincode, v_stateid, v_cityid, v_cid, v_phone, v_photo);
  IF (0 <> 0) THEN
  -- ROLLBACK (removed)
  v_intresult := 1;
  RETURN;
  END IF;
  SELECT MAX(eid) INTO v_eid FROM tblemployee;
  INSERT INTO tbluser (associatedtoid, eid, username, password, roleid, createdbyid, createdon) VALUES (v_assoto, v_eid, v_username, v_password, v_roleid, v_createdbyid, CURRENT_TIMESTAMP);
  IF (0 <> 0) THEN
  -- ROLLBACK (removed)
  v_intresult := 1;
  RETURN;
  END IF;
  SELECT MAX(userid) INTO v_userid FROM tbluser;
  OPEN instcursor;
  FETCH instcursor INTO v_moduleid;
  WHILE (found) LOOP
  INSERT INTO tblusermodule (userid, moduleid, createdbyid, createdon) VALUES (v_userid, v_moduleid, v_createdbyid, CURRENT_TIMESTAMP);
  FETCH instcursor INTO v_moduleid;
  END LOOP;
  CLOSE instcursor;
  -- DEALLOCATE (removed)
  IF (0 <> 0) THEN
  -- ROLLBACK (removed)
  v_intresult := 1;
  RETURN;
  END IF;
  END IF;
  -- COMMIT (removed)
  EXCEPTION WHEN OTHERS THEN
  -- ROLLBACK (removed)
  v_intresult := 1;
  RETURN;
  END;
  END IF;
  IF (v_querytype = 'UpdateUserWithEmployee') THEN
  BEGIN
  -- BEGIN TRAN (removed)
  IF EXISTS(SELECT username FROM tbluser WHERE username = v_username AND userid <> v_uid) THEN
  -- ROLLBACK (removed)
  v_intresult := 2;
  RETURN;
  END IF;
  IF (v_eid > 0) THEN
  UPDATE tblemployee SET name = v_name, modbyid = v_createdbyid, modon = CURRENT_TIMESTAMP, phone = v_phone, mobileno = v_mobileno, mailid = v_mailid, permamentaddress = v_address, pincode = v_pincode, stateid = v_stateid, cityid = v_cityid, cid = v_cid, photo = v_photo, faxno = v_faxno, instantmanagername = v_instantman_name, instantmanagerid = v_instantman, organizationname = v_orgname, dob = v_date, instantmanagerid1 = v_instatntmanid1, additionalinformation = v_addtionalinfo WHERE eid = v_eid;
  IF (0 <> 0) THEN
  -- ROLLBACK (removed)
  v_intresult := 1;
  RETURN;
  END IF;
  END IF;
  IF (v_uid > 0) THEN
  UPDATE tbluser SET username = v_username, password = v_password, modbyid = v_createdbyid, modon = CURRENT_TIMESTAMP WHERE userid = v_uid;
  IF (0 <> 0) THEN
  -- ROLLBACK (removed)
  v_intresult := 1;
  RETURN;
  END IF;
  END IF;
  -- COMMIT (removed)
  EXCEPTION WHEN OTHERS THEN
  -- ROLLBACK (removed)
  v_intresult := 1;
  RETURN;
  END;
  END IF;
END;
$$;


