CREATE FUNCTION dbo.uspuser1(v_name character varying DEFAULT ''::character varying, v_uid integer DEFAULT 0, v_associatedtoid integer DEFAULT 0, v_eid integer DEFAULT 0, v_username character varying DEFAULT ''::character varying, v_password character varying DEFAULT ''::character varying, v_roleid integer DEFAULT 0, v_createdbyid integer DEFAULT 0, v_isactive boolean DEFAULT true, v_querytype character varying DEFAULT ''::character varying, v_mailid character varying DEFAULT ''::character varying, v_intresult integer DEFAULT 0, v_cid integer DEFAULT 0, v_phone character varying DEFAULT ''::character varying, v_photo character varying DEFAULT ''::character varying) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_error VARCHAR(100);
  v_userid bigint;
  v_maxempid bigint;
BEGIN
  v_error := 'Error while saving the record';
  v_intresult := 0;
  IF v_querytype = 'BindUserList' THEN
  RETURN QUERY SELECT userid, username FROM tbluser WHERE isactive = 1 AND isdeleted = 0;
  END IF;
  IF v_querytype = 'BindUserByAssociation' THEN
  RETURN QUERY SELECT userid, username FROM tbluser WHERE isactive = 1 AND isdeleted = 0 AND associatedtoid = v_associatedtoid;
  END IF;
  IF v_querytype = 'GetAllUsers' THEN
  RETURN QUERY SELECT e.eid, e.employeecode, u.userid, u.username, e.name FROM tbluser AS u INNER JOIN tblemployee AS e ON u.eid = e.eid WHERE u.isactive = 1 AND u.roleid <> 1 AND u.username <> 'supersupport' ORDER BY u.userid ASC NULLS FIRST;
  END IF;
  IF v_querytype = 'GetUserByName' THEN
  RETURN QUERY SELECT userid FROM tbluser WHERE username = v_username;
  END IF;
  IF v_querytype = 'SaveUser' THEN
  -- BEGIN TRAN (removed)
  IF EXISTS(SELECT 1 FROM tbluser WHERE eid = v_eid AND v_uid = 0) THEN
  v_error := 'User already exists';
  END IF;
  IF v_uid = 0 THEN
  INSERT INTO tbluser (name, associatedtoid, eid, username, password, roleid, createdbyid, createdon, isactive, isdeleted, lastlogon, modon, modbyid, countryid, phonenumber, emailid, photo) VALUES (v_name, v_associatedtoid, v_eid, v_username, v_password, v_roleid, v_createdbyid, CURRENT_TIMESTAMP, v_isactive, 0, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0, v_cid, v_phone, v_mailid, v_photo);
  ELSE
  UPDATE tbluser SET username = v_username, password = v_password, roleid = v_roleid, modbyid = v_createdbyid, modon = CURRENT_TIMESTAMP WHERE eid = v_eid;
  END IF;
  -- COMMIT (removed)
  END IF;
  IF (v_querytype = 'UpdateUser') THEN
  IF (v_uid > 0) THEN
  UPDATE tbluser SET name = v_name, roleid = v_roleid, password = v_password, countryid = v_cid, phonenumber = v_phone, emailid = v_mailid, modbyid = v_createdbyid, modon = CURRENT_TIMESTAMP WHERE userid = v_uid;
  END IF;
  IF (v_isactive = 0) THEN
  UPDATE tbluser SET isactive = 0, isdeleted = 1 WHERE userid = v_uid;
  END IF;
  IF (v_photo <> '') THEN
  UPDATE tbluser SET photo = v_photo WHERE userid = v_uid;
  END IF;
  IF (0 <> 0) THEN
  v_intresult := 1;
  RETURN;
  END IF;
  END IF;
END;
$$;


--
-- Name: withdrawal_appovered_list(integer, integer, character varying, boolean, character varying, character varying, character varying, character varying, integer, character varying, numeric, numeric, character varying, character varying, character varying, integer, integer, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.withdrawal_appovered_list(v_startrowindex integer DEFAULT 1, v_maxrows integer DEFAULT 100, v_orderbyfield character varying DEFAULT ''::character varying, v_asc boolean DEFAULT true, v_searchfield character varying DEFAULT ''::character varying, v_searchvalue character varying DEFAULT ''::character varying, v_fromdate character varying DEFAULT ''::character varying, v_todate character varying DEFAULT ''::character varying, v_mode integer DEFAULT 0, v_loginid character varying DEFAULT ''::character varying, v_fromamount numeric DEFAULT 0, v_toamount numeric DEFAULT 0, v_city character varying DEFAULT ''::character varying, v_state character varying DEFAULT ''::character varying, v_status character varying DEFAULT ''::character varying, v_isdownload integer DEFAULT 1, v_recordcount integer DEFAULT 0, v_userid integer DEFAULT 0) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_minindex INT;
  v_maxindex INT;
  v_query text;
BEGIN
  v_minindex := (v_startrowindex - 1) * v_maxrows + 1;
  v_maxindex := v_startrowindex * v_maxrows;
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp (ROWNUMBER BIGINT,
WDID BIGINT,
PLID BIGINT,
TYPE VARCHAR(100),
CRDRTYPE VARCHAR(100),
WITHDRAWAMOUNT DECIMAL (18,2),
ADMINCHARGE DECIMAL,
TDS DECIMAL,
DATE VARCHAR(100),
REMARKS text,
STATUS VARCHAR(50),
PAID_STATUS VARCHAR(50),
ACCOUNTNO VARCHAR(100),
ACCOUNTHOLDERNAME VARCHAR(100),
BANKNAME VARCHAR(100),
BRANCHNAME VARCHAR(100),
IFSC VARCHAR(100),
TRANS_ID VARCHAR(100),
KYCSTATUS VARCHAR(100),
USERNAME VARCHAR(100),
EMAILID VARCHAR(150),
LOGINID VARCHAR(100),
SID INT,
CITY VARCHAR(100),
STATENAME VARCHAR(100)) ON COMMIT DROP;
  v_query := 'INSERT INTO #TEMP  SELECT ROW_NUMBER() OVER(ORDER BY WH.DATE DESC) AS ROWNUMBER,WH.WDID,WH.PLID,WH.TYPE,WH.CRDRTYPE,ISNULL(WH.WITHDRAWAMOUNT,0),ISNULL(WH.ADMINCHARGE,0),
WH.TDS,CONVERT(VARCHAR(30),WH.DATE,105) AS DATE,ISNULL(WH.REMARKS,0), WH.STATUS,ISNULL(WH.PAID_STATUS,'''') AS PAID_STATUS,ISNULL(MM.ACCOUNTNO,''''),ISNULL(MM.ACCOUNTHOLDERNAME,''''),
ISNULL(MM.BANKNAME,''''),ISNULL(MM.BRANCHNAME,''''),ISNULL(MM.IFSC,''''),ISNULL(WH.TRANS_ID,''''),(CASE WHEN (SELECT COUNT(REGNO) FROM KYC WHERE REGNO=MM1.REGNO AND 
ISAPROVE=1)=(SELECT COUNT(REGNO) FROM KYC WHERE REGNO=MM1.REGNO )  THEN ''VERIFIED''  WHEN (SELECT COUNT(REGNO) FROM KYC WHERE REGNO=MM1.REGNO AND ISAPROVE=2)=(SELECT COUNT(REGNO)
FROM KYC WHERE REGNO=MM1.REGNO )   THEN ''Rejected'' ELSE ''Pending''   END) AS KYCSTATUS,MM1.USERNAME,MM1.EMAILID,PL.LOGINID,ISNULL(SB.SID,0),ISNULL(SB.CITY,''''),
ISNULL(S.STATENAME,'''')  FROM TBL_WITHDRAWALS WH INNER JOIN WITHDRAWAL_HISTORY MM  ON MM.WDID=WH.WDID LEFT JOIN MEMBER_MASTER MM1 ON MM1.PLID=WH.PLID LEFT JOIN PORTAL_LOGIN PL
ON PL.PLID= MM1.REGNO LEFT JOIN TBL_SPONSERBILLING SB ON SB.PLID=WH.PLID LEFT JOIN STATE S ON S.SID=SB.SID  WHERE MM1.REGNO IN(SELECT REGNO FROM KYC) AND
WH.STATUS= ''Aproved''';
  IF (v_searchfield <> '' AND v_searchvalue <> '') THEN
  IF (v_searchfield = 'LOGINID') THEN
  v_query := v_query || ' AND PL.LOGINID =''' || v_searchvalue || ''' ';
  END IF;
  END IF;
  IF ((v_fromdate <> '') AND (v_todate = '')) THEN
  v_query := v_query || ' AND CONVERT(DATE, WH.DATE, 105) BETWEEN  CONVERT(DATE, ''' || v_fromdate || ''', 105) AND  CONVERT(DATE, DBO.FUN_GETCURRENTDATE(), 105) ';
  END IF;
  IF ((v_fromdate = '') AND (v_todate <> '')) THEN
  v_query := v_query || ' AND CONVERT(DATE, WH.DATE, 105) BETWEEN  CONVERT(DATE, ''' || v_todate || ''', 105) AND  CONVERT(DATE, DBO.FUN_GETCURRENTDATE(), 105) ';
  END IF;
  IF ((v_fromdate <> '') AND (v_todate <> '')) THEN
  v_query := v_query || ' AND CONVERT(DATE, WH.DATE, 105) BETWEEN CONVERT(DATE, ''' || v_fromdate || ''', 105) AND  CONVERT(DATE, ''' || v_todate || ''', 105) ';
  END IF;
  IF (v_loginid <> '') THEN
  v_query := v_query || ' AND  ISNULL(PL.LOGINID,'''') LIKE ''%' || v_loginid || '%''';
  END IF;
  IF ((v_fromamount <> '') AND (v_toamount = '')) THEN
  v_query := v_query || ' AND ISNULL(WH.WITHDRAWAMOUNT,0) >= ''' || CAST(v_fromamount AS VARCHAR(20)) || '''';
  END IF;
  IF ((v_toamount <> '') AND (v_fromamount = '')) THEN
  v_query := v_query || ' AND ISNULL(WH.WITHDRAWAMOUNT,0) <= ''' || CAST(v_toamount AS VARCHAR(20)) || '''';
  END IF;
  IF ((v_fromamount <> '') AND (v_toamount <> '')) THEN
  v_query := v_query || ' AND ISNULL(WH.WITHDRAWAMOUNT,0) BETWEEN ''' || CAST(v_fromamount AS VARCHAR(20)) || ''' AND ''' || CAST(v_toamount AS VARCHAR(20)) || '''';
  END IF;
  IF (v_city <> '') THEN
  v_query := v_query || ' AND ISNULL(SB.CITY,'''') LIKE''%' || v_city || '%''';
  END IF;
  IF (v_state <> '') THEN
  v_query := v_query || ' AND ISNULL(S.STATENAME,'''') LIKE''%' || v_state || '%''';
  END IF;
  IF (v_status <> '') THEN
  v_query := v_query || ' AND ISNULL(WH.PAID_STATUS,'''') =''' || v_status || ''' ';
  END IF;
  EXECUTE v_query;
  IF (v_isdownload = 0) THEN
  RETURN QUERY SELECT * FROM tmp_temp WHERE rownumber BETWEEN v_minindex AND v_maxindex;
  ELSE
  RETURN QUERY SELECT rownumber AS "s.no.", date AS "request date", loginid AS "login id", withdrawamount AS amount, bankname AS "bank name", accountno AS "account no.", ifsc AS "ifsc code", paid_status AS status FROM tmp_temp;
  INSERT INTO tbl_exceltrackingreport (report_name, file_name, type, download_by, download_date) VALUES ('Payout Report', 'Payout-List.xls', 1, v_userid, CURRENT_TIMESTAMP);
  END IF;
  SELECT COUNT(rownumber) INTO v_recordcount FROM tmp_temp;
  DROP TABLE IF EXISTS tmp_temp;
  RETURN QUERY SELECT v_recordcount AS recordcount;
  -- SET option (removed)
END;
$$;


--
-- Name: withdrawal_list(integer, integer, character varying, boolean, character varying, character varying, character varying, character varying, integer, character varying, character varying, integer); Type: FUNCTION; Schema: dbo; Owner: -
--

CREATE FUNCTION dbo.withdrawal_list(v_startrowindex integer, v_maxrows integer, v_orderbyfield character varying, v_asc boolean, v_searchfield character varying, v_searchvalue character varying, v_fromdate character varying, v_todate character varying, v_mode integer, v_loginid character varying DEFAULT ''::character varying, v_status character varying DEFAULT NULL::character varying, v_recordcount integer DEFAULT NULL::integer) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_minindex int;
  v_maxindex int;
  v_query text;
BEGIN
  v_minindex := (v_startrowindex - 1) * v_maxrows + 1;
  v_maxindex := v_startrowindex * v_maxrows;
  DROP TABLE IF EXISTS tmp_temp;
  CREATE TEMP TABLE tmp_temp (rownumber bigint,
WDID bigint,
PLID bigint,
TYPE varchar(100),
CRDRTYPE varchar(100),
WITHDRAWAMOUNT decimal (18,2),
ADMINCHARGE decimal,
TDS decimal,
DATE varchar(100),
REMARKS text,
STATUS varchar(50),
ACCOUNTNO varchar(100),
ACCOUNTHOLDERNAME varchar(100),
BANKNAME varchar(100),
BRANCHNAME varchar(100),
IFSC varchar(100),
Trans_Id varchar(100),
kycstatus varchar(100),
userName varchar(100),
emailid varchar(150),
loginID varchar(100)) ON COMMIT DROP;
  v_query := 'insert into #temp  select ROW_NUMBER() OVER(ORDER BY wh.DATE desc) AS rowNumber,wh.WDID,wh.PLID,wh.TYPE,wh.CRDRTYPE,isnull(wh.WITHDRAWAMOUNT,0),isnull(wh.ADMINCHARGE,0),
wh.TDS,Convert(varchar(30),wh.DATE,105) as DATE,isnull(wh.REMARKS,0),wh.STATUS,isnull(mm.ACCOUNTNO,''''),isnull(mm.ACCOUNTHOLDERNAME,''''),isnull(mm.BANKNAME,''''),
isnull(mm.BRANCHNAME,''''),isnull(mm.IFSC,''''),isnull(wh.Trans_Id,''''),(case when (select count(REGNO) from KYC where Regno=mm1.REGNO and isAprove=1)=(select count(Regno)
 from kyc where Regno=mm1.REGNO )  then ''Verified''  when (select count(REGNO) from KYC where Regno=mm1.REGNO and isAprove=2)=(select count(Regno) from kyc where Regno=mm1.REGNO )
   then ''Rejected'' ELSE ''Pending''   end) as kycstatus,mm1.userName,mm1.emailid,pl.loginID  from TBL_WITHDRAWALS wh inner join withdrawal_history mm  on mm.WDID=wh.WDID left join 
   member_master mm1 on mm1.PLID=wh.PLID left join PORTAL_LOGIN pl on pl.plid= mm1.regno where mm1.REGNO in(select REGNO from KYC)  ';
  IF (v_searchfield <> '' AND v_searchvalue <> '') THEN
  IF (v_searchfield = 'loginid') THEN
  v_query := v_query || ' and pl.loginID =''' || v_searchvalue || ''' ';
  END IF;
  END IF;
  IF ((v_fromdate <> '') AND (v_todate = '')) THEN
  v_query := v_query || ' and CONVERT(date, wh.DATE, 105) >=  CONVERT(date, ''' || v_fromdate || ''', 105) ';
  END IF;
  IF ((v_fromdate = '') AND (v_todate <> '')) THEN
  v_query := v_query || ' and CONVERT(date, wh.DATE, 105) <=  CONVERT(date, ''' || v_todate || ''', 105) ';
  END IF;
  IF ((v_fromdate <> '') AND (v_todate <> '')) THEN
  v_query := v_query || ' and CONVERT(date, wh.DATE, 105) between CONVERT(date, ''' || v_fromdate || ''', 105) and  CONVERT(date, ''' || v_todate || ''', 105) ';
  END IF;
  IF (v_loginid <> '') THEN
  v_query := v_query || ' AND ISNULL(pl.loginid,'''') LIKE ''%' || v_loginid || '%''';
  END IF;
  IF (v_status <> '') THEN
  v_query := v_query || ' AND ISNULL(wh.STATUS,'''') = ''' || v_status || '''';
  END IF;
  EXECUTE v_query;
  RETURN QUERY SELECT * FROM tmp_temp WHERE rownumber BETWEEN v_minindex AND v_maxindex;
  SELECT COUNT(rownumber) INTO v_recordcount FROM tmp_temp;
  DROP TABLE IF EXISTS tmp_temp;
  RETURN QUERY SELECT v_recordcount AS recordcount;
  -- SET option (removed)
END;
$$;


