--
-- Name: view_allemail_ids; Type: VIEW; Schema: dbo; Owner: -
--

CREATE VIEW dbo.view_allemail_ids AS
 SELECT pl.loginid AS emailid,
    c.countryname AS country_name,
    pl.doc AS date,
    'reg-user'::text AS type,
    pl.lastmaildate
   FROM (dbo.portal_login pl
     LEFT JOIN dbo.country c ON ((pl.cid = c.cid)))
UNION ALL
 SELECT subscription_master.emailid,
    subscription_master.country_name,
    subscription_master.subscriptiondate AS date,
    'blog-user'::text AS type,
    subscription_master.lastmaildate
   FROM dbo.subscription_master
UNION ALL
 SELECT tbl_newsletteremailid.emailid,
    tbl_newsletteremailid.country_name,
    tbl_newsletteremailid.date,
    'emai-subs-user'::text AS type,
    tbl_newsletteremailid.lastmaildate
   FROM dbo.tbl_newsletteremailid;


--
-- Name: view_portalmasterdetails; Type: VIEW; Schema: dbo; Owner: -
--

CREATE VIEW dbo.view_portalmasterdetails AS
 SELECT pl.plid,
    pl.loginid,
    pl.password,
    pl.title,
    pl.fname,
    pl.lname,
        CASE (((((COALESCE(pl.title, ''::character varying))::text || ' '::text) || (COALESCE(pl.fname, ''::character varying))::text) || ' '::text) || (COALESCE(pl.lname, ''::character varying))::text)
            WHEN 'Title'::text THEN '-'::text
            ELSE (((((COALESCE(pl.title, ''::character varying))::text || ' '::text) || (COALESCE(pl.fname, ''::character varying))::text) || ' '::text) || (COALESCE(pl.lname, ''::character varying))::text)
        END AS fullname,
        CASE COALESCE(pl.username, ''::character varying)
            WHEN ''::text THEN '-'::character varying
            ELSE pl.username
        END AS username,
    pl.doc,
    COALESCE(pl2.loginid, '-'::character varying) AS introid,
    COALESCE(pl.refral_id, '-'::character varying) AS refral_id,
    pl.currencysymbol,
        CASE COALESCE(pl.phone, ''::character varying)
            WHEN ''::text THEN '-'::character varying
            ELSE pl.phone
        END AS phone,
    c.countryname,
    COALESCE(pl.qpayregno, (0)::bigint) AS qpayregno,
    pl.cid
   FROM (((dbo.portal_login pl
     LEFT JOIN dbo.portal_master pm ON ((pl.pmid = pm.pmid)))
     LEFT JOIN dbo.portal_login pl2 ON ((pl.intro_refid = pl2.plid)))
     LEFT JOIN dbo.country c ON ((pl.cid = c.cid)));


